            ,V_CURRENCY
            ,V_MEASURE
            ,V_DOM_EXP
            ,V_FCST_TYPE
            ,V_INCOTERMS
            ,V_PRICE
            ,V_CREATED_BY
            ,SYSDATE
            ,V_LAST_UPDATED_BY
            ,SYSDATE
        FROM   SCM_MGR.GT_FCSV_RESULTS_MST
        WHERE  V_ACTIVE_FLAG <> 'D';   -- DELETE값이 아닌경우만

        --------------------------------------------------------------------------------------  20180510 SKH ADD START
        INSERT INTO SCM_MGR.GT_FCSV_RESULTS
        (
             V_DIVISION_ID
            ,V_PROJECT_CODE
            ,V_SCM_SITE_ID
            ,V_ITEM_ID
            ,V_DOM_EXP
            ,V_FCST_TYPE
            ,V_INCOTERMS
            ,V_MEASURE
            ,V_PLANT_SITE_ID
            ,V_YYYYMMDD
            ,V_CURRENCY
            ,V_PRICE
            ,V_CREATED_BY
        )
        SELECT
             V_DIVISION_ID
            ,V_PROJECT_CODE
            ,V_SCM_SITE_ID
            ,V_ITEM_ID
            ,V_DOM_EXP
            ,V_FCST_TYPE
            ,V_INCOTERMS
            ,V_MEASURE
            ,V_PLANT_SITE_ID
            ,V_YYYYMMDD
