            ,V_PRICE
            ,V_CREATED_BY
        FROM   SCM_MGR.GT_FCSV_RESULTS_MST
        WHERE  V_ACTIVE_FLAG <> 'D';   -- DELETE값이 아닌경우만

        -- Procedure 호출 #results 테이블의 데이터를 전달하여 처리함
        PKG_DMF0020.P_PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW_SINGLE;
