                       AND TGT.FCST_TYPE      =   v_FCST_TYPE
                       AND TGT.INCOTERMS      =   v_INCOTERMS
				  ) > 0;
END;
--===================================================================================== delete end


--===================================================================================== update, insert start
-- 20180718  KHSONG  기존 MERGE - INTO 구조에서 오류발견되어 DELETE - INSERT 구조로 변경함 (START)
BEGIN
