					,cast(V_PRICE as NUMBER(20,10))
					,V_CREATED_BY
					,SYSDATE
					,V_LAST_UPDATED_BY
					,SYSDATE
				FROM GT_DMF0020_RESULTS_MST
					where v_active_flag    <> 'D';

							INSERT INTO  SCM_MST_FUTURE_PRICE_H
