										,PROJECT_CODE
										,SCM_SITE_ID
										,PLANT_SITE_ID
										,ITEM_ID
										,YYYYMMDD
										,CURRENCY
										,MEASURE
										,DOM_EXP
										,FCST_TYPE
										,INCOTERMS
										,PRICE
										,CREATED_BY
										,CREATION_DATE
										,LAST_UPDATED_BY
										,LAST_UPDATE_DATE
									  )
								SELECT
										 v_DIVISION_ID
										,SEQ1_SCM_MST_FUTURE_PRICE_H.NEXTVAL
										,v_PROJECT_CODE
										,v_SCM_SITE_ID
										,v_PLANT_SITE_ID
										,v_ITEM_ID
										,v_YYYYMMDD
										,v_CURRENCY
										,v_MEASURE
										,v_DOM_EXP
										,v_FCST_TYPE
										,v_INCOTERMS
