										,SYSDATE
								 FROM  GT_DMF0020_RESULTS_MST  WHERE v_active_flag <> 'D';   -- DELETE값이 아닌경우만

						--------------------------------------------------------------------------------------  20180510 SKH ADD START
                        INSERT INTO GT_DMF0020_RESULTS
									(v_DIVISION_ID
								    ,v_PROJECT_CODE
								    ,v_SCM_SITE_ID
								    ,v_ITEM_ID
								    ,v_DOM_EXP
								    ,v_FCST_TYPE
