						PKG_DMF0020.P_PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW_SINGLE;
						--------------------------------------------------------------------------------------  20180510 SKH ADD END

END;
--===================================================================================== update, insert end

  	-- 트랜잭션 (COMMIT)
        COMMIT;  -- sss
	--------------------------------------------------------------------------------------------
		EXCEPTION
			WHEN e_invalid_data THEN
