				--[C20200909-000203] LOG 표준화 적용
				-- 트랜잭션 (END)
				ROLLBACK TO SAVEPOINT SCM_MST_FUTURE_PRICE_ALL;  -- sss

				v_log_type := 'ERROR';
				v_log_message := SUBSTR(SQLERRM, 1, 1000);
				v_description := 'ERROR_LINE : ' || TO_CHAR($$PLSQL_LINE);
				d_event_date := SYSDATE;

