    V_INCOTERMS                   VARCHAR2(10 CHAR);
    V_MEASURE                     VARCHAR2(50 CHAR);
    V_YYYYMMDD                    VARCHAR2(8 CHAR);
    V_PLANT_SITE_ID               VARCHAR2(30 CHAR);
    V2_REQUEST_NO                 VARCHAR2(30 CHAR);

    V_MSG                         VARCHAR2(1000 CHAR);


    V_TABLE_BODY                  CLOB;
    V_BODY_CONTENTS               CLOB;
    V_HEAD_CONT                   CLOB;
    V_BODY_CONT                   CLOB;
    V_MAIL_TITLE                  VARCHAR2(100 CHAR);
    V_CNT                         NUMBER(10);
    V_I                           NUMBER(10);
    /* [사용자 결정 2026-08-03] 원본 NVARCHAR(150). MSSQL 은 151자에서 무음 절단이나 Oracle 은 ORA-06502 로
       상한 4000 = 하위 SCM_ADM_MAIL_SEND 내부 V_TO_MAIL VARCHAR2(4000 CHAR) 와 정합. */
    V_TO_MAIL                     VARCHAR2(4000 CHAR);

    V_ITEM_SEQ                    NUMBER(10);
    V_ITEM_NAME                   VARCHAR2(50 CHAR);
    V_UOM                         VARCHAR2(8 CHAR);
    V_PLAN_QTY                    NUMBER(30, 10);
    V_CREATED_BY                  VARCHAR2(150 CHAR);
    V_LAST_UPDATE_DATE            DATE;
    V_CURSOR_YYYYMMDD             VARCHAR2(10 CHAR);

    /* 변환 도입 변수 (MSSQL IF (SELECT COUNT(*) ...) 를 PL/SQL 로 옮기기 위한 수신 변수) */
    N_TMP_CNT                     NUMBER(10);
    V_IN_PARA_DATA                VARCHAR2(4000 CHAR);

BEGIN
/*

--대상추출 과 분리하여 PR_REQUEST만 생성


--전주 화요일에 추출된 것들 대상
--	-1:일요일, 0:월요일, 1:화요일, 2:수요일, 3:목요일, 4:금요일, 5:토요일
SELECT DATEADD(WK, DATEDIFF(WK,0, DATEADD(WEEK,-1,GETDATE())), 1)


--메인테이블 변경
DM_PLN_BNP_IN_PR_DETAIL_AUTO
=>DM_PLN_AUTO_PR_CHECK


--채번규칙 변경
프로젝트 별
=>프로젝트별 / 아이템별


--실제 반영시 주석해제해야할것
1.'전주 화요일에 발송된 것들만 대상'
2.데이터 가져올때 week+1 한 부분에서 +1 삭제


*/


    /* 시작 LOG  (START) */
    V_LOG_TYPE        := 'START';
    V_LOG_MESSAGE     := '########## Start of procedure @@@##########';
    V_LOG_DESCRIPTION := '';
    D_EVENT_DATE      := SYSDATE;
    PR_DM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_LOG_DESCRIPTION, D_EVENT_DATE, 'SCM_BATCH');
    V_LOG_MESSAGE := NULL;      /* 변수 재사용을 위하여 초기화해야함 */


    /* -------------------------------------------------------------------------------------------- */
    BEGIN
    /* -------------------------------------------------------------------------------------------- */
            /* 메일발송 주기(케이스 별) */
            /*
            *1차
        (A) Incoterms= EXW => D-91(13주)
        (B) Incoterms = C* or F*, Country=KR => D-119(17주)
        (C) Incoterms = D*, Country=JP => D-119(17주)
        (D) Incoterms = D*, Country = not KR => D-175(25주)


            *2차
        (A) Incoterms= EXW => D-20 (3주 전)
        (B) Incoterms = C* or F*, Country=KR => D-48 (7주 전)
        (C) Incoterms = D*, Country=JP => D-48 (7주 전)
        (D) Incoterms = D*, Country = not KR => D-104 (15주 전)
            */
        V_SUB_QRY := '';

        /* ---------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3')||' ### BNP IN 대상 가져오기');
        /* ---------------------------------------------------------------------------------------- */
        /* 원본 : IF OBJECT_ID('TEMPDB..#TMP_BNP_TARGET_LIST') IS NOT NULL DROP TABLE + CREATE TABLE #TMP_BNP_TARGET_LIST */
        DELETE
          FROM GT_DMF70PR_BNP_TARGET_LIST;

        V_SUB_QRY := '';

        FOR CUR_GUIDE_LIST IN ( SELECT SEGMENT1
                                     , SEGMENT2
                                     , SEGMENT3
                                     , SEGMENT4
                                     , SEGMENT5
                                  FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                                 WHERE LOOKUP_TYPE = 'AUTO_PR_CHECK_CRITERIA'
                                   AND VALID_YN = 'Y'
                                 ORDER BY DISPLAY_SEQ ) LOOP

            V_CUR_DIVISION  := CUR_GUIDE_LIST.SEGMENT1;
            V_CUR_INCOTERMS := CUR_GUIDE_LIST.SEGMENT2;
            V_CUR_COUNTRY   := CUR_GUIDE_LIST.SEGMENT3;
            V_CUR_BNP_WEEK  := CUR_GUIDE_LIST.SEGMENT4;
            V_CUR_DATA_WEEK := CUR_GUIDE_LIST.SEGMENT5;

            IF V_SUB_QRY IS NOT NULL THEN
                V_SUB_QRY := V_SUB_QRY||'
                UNION
                ';
            END IF;

            V_SUB_QRY := V_SUB_QRY||'
                SELECT A.DIVISION_ID
                     , A.PROJECT_CODE
                     , A.SCM_SITE_ID
                     , A.ITEM_ID
                     , A.DOM_EXP
                     , A.FCST_TYPE
                     , A.INCOTERMS
                     , ''BNPIn'' AS MEASURE
                     , A.PLANT_SITE_ID
                     , A.YYYYMMDD
                     , A.QTY
                     , TO_CHAR(TO_DATE(A.YYYYMMDD, ''YYYYMMDD'') - 7 * ('||V_CUR_BNP_WEEK||'), ''YYYYMMDD'') AS BNP_YYYYMMDD
                     , (SELECT SEGMENT1
                          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                         WHERE LOOKUP_TYPE = ''DM_PR_PUCH''
                           AND ROWNUM = 1) AS PUCH_MGR
                     , (SELECT SEGMENT2
                          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                         WHERE LOOKUP_TYPE = ''DM_PR_PUCH''
                           AND ROWNUM = 1) AS PUCH_GROUP
                     , CASE WHEN (SELECT PROJECT_NAME
                                    FROM SCM_MST_PROJECT
                                   WHERE DIVISION_ID = A.DIVISION_ID
                                     AND PROJECT_CODE = A.PROJECT_CODE
                                     AND ROWNUM = 1) IS NULL
                            THEN NULL
                            ELSE '' ( ''||A.PROJECT_CODE||'' ) ''
                                 ||(SELECT PROJECT_NAME
                                      FROM SCM_MST_PROJECT
                                     WHERE DIVISION_ID = A.DIVISION_ID
                                       AND PROJECT_CODE = A.PROJECT_CODE
                                       AND ROWNUM = 1)
                                 ||B.SEGMENT2
                       END AS PR_HEADER  /* (Project Code) + Project + ''물량''(룩업관리) */
                    /* ,B.SEGMENT4 STORAGE_ID -- SLOC(룩업관리) */
                    /* , B.SEGMENT3 STORAGE_PLANT_ID--(룩업관리) => 별도 쿼리 해오다가 룩업관리로 변경함 */
                    /* , B.SEGMENT5 ITEM_DETAIL--(룩업관리) */
                     , D.STORAGE_ID
                     , D.STORAGE_PLANT_ID
                     , D.PR_ITEM_DETAIL AS ITEM_DETAIL
                     , (SELECT ITEM_UOM
                          FROM DM_MST_ITEM_SINGLE_V
                         WHERE DIVISION_ID = A.DIVISION_ID
                           AND ITEM_ID = A.ITEM_ID) AS UOM
                  FROM DM_PLN_MKT_FCST              A
                     , SCM_ADM_LOOKUP_MASTER_DETAIL B
                     , SCM_MST_SITE                 C
                     , DM_PLN_AUTO_PR_CHECK         D
                 WHERE B.SEGMENT1 = A.DIVISION_ID
                   AND C.DIVISION_ID = A.DIVISION_ID
                   AND C.SCM_SITE_ID = A.SCM_SITE_ID
                   AND D.DIVISION_ID = A.DIVISION_ID
                   AND D.PROJECT_CODE = A.PROJECT_CODE
                   AND D.SCM_SITE_ID = A.SCM_SITE_ID
                   AND D.ITEM_ID = A.ITEM_ID
                   AND D.DOM_EXP = A.DOM_EXP
                   AND D.INCOTERMS = A.INCOTERMS
                   AND D.PLANT_SITE_ID = A.PLANT_SITE_ID
                   AND D.MKT_FCST_DATE = A.YYYYMMDD
                   AND B.LOOKUP_TYPE = ''AUTO_PR_CHECK_TEXT''
                   AND B.VALID_YN = ''Y''
                   AND D.AUTO_FLAG = ''Y''
                   AND RTRIM(D.BNP_IN_DATE) IS NULL  /* BNP IN 데이터 생성 안된것만 */
                   AND D.MAIL_INFO_DATE = TO_CHAR(TRUNC(SYSDATE - 6, ''IW'') + 1, ''YYYYMMDD'')  /* 전주 화요일에 발송된 것들만 대상 */
                   AND RTRIM(D.STORAGE_PLANT_ID) IS NOT NULL  /* Plant Site 가 입력된 것들만 */
                   AND RTRIM(D.STORAGE_ID) IS NOT NULL  /* SLOC 가 입력된 것들만 */
                   AND A.MEASURE = ''MKT_FCST''
                   AND RTRIM(A.ATTRIBUTE9) IS NULL  /* 확정되지 않은 것들 */
                   AND ( ( A.YYYYMMDD >= (SELECT BASIS_START_DATE
                                            FROM SCM_SYS_CALENDAR_M
                                           WHERE BASIS_YYYYMMDD = TO_CHAR(SYSDATE + 7 * ('||V_CUR_DATA_WEEK||'), ''YYYYMMDD''))
                       AND A.YYYYMMDD <= (SELECT BASIS_END_DATE
                                            FROM SCM_SYS_CALENDAR_M
                                           WHERE BASIS_YYYYMMDD = TO_CHAR(SYSDATE + 7 * ('||V_CUR_DATA_WEEK||'), ''YYYYMMDD'')) )
                        OR ( A.YYYYMMDD >= (SELECT BASIS_START_DATE
                                             FROM SCM_SYS_CALENDAR_M
                                            WHERE BASIS_YYYYMMDD = TO_CHAR(SYSDATE + 7 * ('||TO_CHAR(TO_NUMBER(V_CUR_DATA_WEEK) - 10)||'), ''YYYYMMDD''))  /* 2차처리는 1차의 10주 뒤 */
                       AND A.YYYYMMDD <= (SELECT BASIS_END_DATE
                                            FROM SCM_SYS_CALENDAR_M
                                           WHERE BASIS_YYYYMMDD = TO_CHAR(SYSDATE + 7 * ('||V_CUR_DATA_WEEK||'), ''YYYYMMDD'')) ) )  /* To는 1차발송일과 동일 */
                ';

                /* INCOTERMS */
                IF V_CUR_INCOTERMS <> '-' THEN
                    IF INSTR(V_CUR_INCOTERMS, '*') > 0 THEN
                        V_SUB_QRY := V_SUB_QRY||'
                   AND A.INCOTERMS LIKE '''||REPLACE(V_CUR_INCOTERMS, '*', '%')||'''
                ';
                    ELSIF INSTR(UPPER(V_CUR_INCOTERMS), 'NOT_') > 0 THEN
                    /*
                    --Not 의 규칙
                    1)Not_로 등록
                    2)여러개일 경우는 ,로 구분
                    */
                        FOR CUR_NOT_COND IN ( SELECT TOKEN
                                                FROM TABLE(UF_FX_STRING_SPLIT(V_CUR_INCOTERMS, ',')) ) LOOP

                            V_CUR_NOT_COND := CUR_NOT_COND.TOKEN;

                            V_SUB_QRY := V_SUB_QRY||'
                   AND A.INCOTERMS <> '''||REGEXP_REPLACE(V_CUR_NOT_COND, 'NOT_', '', 1, 0, 'i')||'''
                ';

                        END LOOP;

                    ELSE
                        V_SUB_QRY := V_SUB_QRY||'
                   AND A.INCOTERMS = '''||V_CUR_INCOTERMS||'''
                ';
                    END IF;
                END IF;

                /* COUNTRY */
                IF V_CUR_COUNTRY <> '-' THEN
                    IF INSTR(V_CUR_COUNTRY, '*') > 0 THEN
                        V_SUB_QRY := V_SUB_QRY||'
                   AND C.COUNTRY LIKE '''||REPLACE(V_CUR_COUNTRY, '*', '%')||'''
                ';
                    ELSIF INSTR(UPPER(V_CUR_COUNTRY), 'NOT_') > 0 THEN

                    /*
                        SET @V_SUB_QRY = @V_SUB_QRY + N'
                            AND MS.COUNTRY <> ''' + REPLACE(@CUR_COUNTRY,'NOT ', '') + '''
                        '
                        */
                        /*
                        --Not 의 규칙
                        1)Not_로 등록
                        2)여러개일 경우는 ,로 구분
                        */
                        FOR CUR_NOT_COND IN ( SELECT TOKEN
                                                FROM TABLE(UF_FX_STRING_SPLIT(V_CUR_COUNTRY, ',')) ) LOOP

                            V_CUR_NOT_COND := CUR_NOT_COND.TOKEN;

                            V_SUB_QRY := V_SUB_QRY||'
                   AND C.COUNTRY <> '''||REGEXP_REPLACE(V_CUR_NOT_COND, 'NOT_', '', 1, 0, 'i')||'''
                ';

                        END LOOP;
                    ELSE
                        V_SUB_QRY := V_SUB_QRY||'
                   AND C.COUNTRY = '''||V_CUR_COUNTRY||'''
                ';
                    END IF;
                END IF;

        END LOOP;

        /* PRINT @V_SUB_QRY */
        /* [사용자 결정 2026-08-03] 유효 criteria 가 0건이면 V_SUB_QRY 가 NULL 이라 컬럼목록만 남은 */
        IF V_SUB_QRY IS NOT NULL THEN
        EXECUTE IMMEDIATE 'INSERT
  INTO GT_DMF70PR_BNP_TARGET_LIST
     ( DIVISION_ID
     , PROJECT_CODE
     , SCM_SITE_ID
     , ITEM_ID
     , DOM_EXP
     , FCST_TYPE
     , INCOTERMS
     , MEASURE
     , PLANT_SITE_ID
     , YYYYMMDD
     , QTY
     , BNP_YYYYMMDD
     , PUCH_MGR
     , PUCH_GROUP
     , PR_HEADER
     , STORAGE_ID
     , STORAGE_PLANT_ID
     , ITEM_DETAIL
     , UOM )
'||V_SUB_QRY;
        END IF;

        /* select * from #TMP_BNP_TARGET_LIST */

        /* ---------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3')||' ### BNP IN 데이터 생성');
        /* ---------------------------------------------------------------------------------------- */

        /* 머지구문으로 변경
           기존에 있던 승인나지 않은 데이터 수량 업데이트 */
        MERGE INTO DM_PLN_MKT_FCST A
        USING GT_DMF70PR_BNP_TARGET_LIST B
           ON ( A.DIVISION_ID = B.DIVISION_ID
            AND A.PROJECT_CODE = B.PROJECT_CODE
            AND A.SCM_SITE_ID = B.SCM_SITE_ID
            AND A.ITEM_ID = B.ITEM_ID
            AND A.DOM_EXP = B.DOM_EXP
            AND A.FCST_TYPE = B.FCST_TYPE
            AND A.INCOTERMS = B.INCOTERMS
            AND A.MEASURE = B.MEASURE
            AND A.PLANT_SITE_ID = B.PLANT_SITE_ID
            AND A.YYYYMMDD = B.BNP_YYYYMMDD          /* 룩업에 등록된BNPIN WEEK */
            AND RTRIM(A.ATTRIBUTE9) IS NULL )        /* 승인나지 않은 것 */
        WHEN MATCHED THEN
            UPDATE
               SET A.QTY = B.QTY
                 , A.LAST_UPDATED_BY = 'SCM_BATCH'
                 , A.LAST_UPDATE_DATE = SYSDATE
        WHEN NOT MATCHED THEN
            INSERT ( DIVISION_ID
                   , PROJECT_CODE
                   , SCM_SITE_ID
                   , ITEM_ID
                   , DOM_EXP
                   , FCST_TYPE
                   , INCOTERMS
                   , MEASURE
                   , PLANT_SITE_ID
                   , YYYYMMDD
                   , QTY
                   , CREATED_BY
                   , CREATION_DATE
                   , LAST_UPDATED_BY
                   , LAST_UPDATE_DATE )
            VALUES ( B.DIVISION_ID
                   , B.PROJECT_CODE
                   , B.SCM_SITE_ID
                   , B.ITEM_ID
                   , B.DOM_EXP
                   , B.FCST_TYPE
                   , B.INCOTERMS
                   , B.MEASURE
                   , B.PLANT_SITE_ID
                   , B.BNP_YYYYMMDD                  /* 룩업에 등록된BNPIN WEEK */
                   , B.QTY
                   , 'SCM_BATCH'
                   , SYSDATE
                   , 'SCM_BATCH'
                   , SYSDATE );

        /* ---------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3')||' ### BNP IN YYYYMMDD를 메일발송 테이블의 BNP_IN_DATE에 저장');   /* 추후 BNP IN 생성여부 판단 수월하게 하기 위함 */
        /* ---------------------------------------------------------------------------------------- */

        /* 원본 UPDATE ATO SET ... FROM DM_PLN_AUTO_PR_CHECK ATO INNER JOIN #TMP_BNP_TARGET_LIST T_LIST ON ...
              상관 UPDATE + EXISTS(ROWNUM = 1) 로 옮긴다. */
        UPDATE DM_PLN_AUTO_PR_CHECK A
           SET A.BNP_IN_DATE = (SELECT B.BNP_YYYYMMDD
                                  FROM GT_DMF70PR_BNP_TARGET_LIST B
                                 WHERE A.DIVISION_ID = B.DIVISION_ID
                                   AND A.PROJECT_CODE = B.PROJECT_CODE
                                   AND A.SCM_SITE_ID = B.SCM_SITE_ID
                                   AND A.ITEM_ID = B.ITEM_ID
                                   AND A.DOM_EXP = B.DOM_EXP
                                   AND A.FCST_TYPE = B.FCST_TYPE
                                   AND A.INCOTERMS = B.INCOTERMS
                                   AND A.PLANT_SITE_ID = B.PLANT_SITE_ID
                                   AND A.MKT_FCST_DATE = B.YYYYMMDD
                                   AND ROWNUM = 1)
         WHERE EXISTS (SELECT 1
                         FROM GT_DMF70PR_BNP_TARGET_LIST B
                        WHERE A.DIVISION_ID = B.DIVISION_ID
                          AND A.PROJECT_CODE = B.PROJECT_CODE
                          AND A.SCM_SITE_ID = B.SCM_SITE_ID
                          AND A.ITEM_ID = B.ITEM_ID
                          AND A.DOM_EXP = B.DOM_EXP
                          AND A.FCST_TYPE = B.FCST_TYPE
                          AND A.INCOTERMS = B.INCOTERMS
                          AND A.PLANT_SITE_ID = B.PLANT_SITE_ID
                          AND A.MKT_FCST_DATE = B.YYYYMMDD);

        SELECT COUNT(*)
          INTO N_TMP_CNT
          FROM GT_DMF70PR_BNP_TARGET_LIST;

        IF N_TMP_CNT > 0 THEN

            /* ------------------------------------------------------------------------------------ */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3')||' ### PR Request 데이터 생성');
            /* ------------------------------------------------------------------------------------ */

            FOR CUR_BNP_PJT_LIST IN ( SELECT DIVISION_ID
                                           , PROJECT_CODE
                                           , SCM_SITE_ID
                                           , ITEM_ID
                                           , DOM_EXP
                                           , FCST_TYPE
                                           , INCOTERMS
                                           , PLANT_SITE_ID
                                           , BNP_YYYYMMDD          /* BNP IN YYYYMMDD */
                                           , UOM
                                           , QTY
                                           , STORAGE_ID
                                           , STORAGE_PLANT_ID
                                           , PUCH_MGR
                                           , PUCH_GROUP
                                           , PR_HEADER
                                           , ITEM_DETAIL
                                        FROM GT_DMF70PR_BNP_TARGET_LIST ) LOOP   /* 프로젝트 코드 */

                V_CURSSP_DIVISION_ID      := CUR_BNP_PJT_LIST.DIVISION_ID;
                V_CURSSP_PROJECT_CODE     := CUR_BNP_PJT_LIST.PROJECT_CODE;
                V_CURSSP_SCM_SITE_ID      := CUR_BNP_PJT_LIST.SCM_SITE_ID;
                V_CURSSP_ITEM_ID          := CUR_BNP_PJT_LIST.ITEM_ID;
                V_CURSSP_DOM_EXP          := CUR_BNP_PJT_LIST.DOM_EXP;
                V_CURSSP_FCST_TYPE        := CUR_BNP_PJT_LIST.FCST_TYPE;
                V_CURSSP_INCOTERMS        := CUR_BNP_PJT_LIST.INCOTERMS;
                V_CURSSP_PLANT_SITE_ID    := CUR_BNP_PJT_LIST.PLANT_SITE_ID;
                V_CURSSP_BNP_YYYYMMDD     := CUR_BNP_PJT_LIST.BNP_YYYYMMDD;      /* BNP IN YYYYMMDD */
                V_CURSSP_UOM              := CUR_BNP_PJT_LIST.UOM;
                V_CURSSP_QTY              := CUR_BNP_PJT_LIST.QTY;
                V_CURSSP_STORAGE_ID       := CUR_BNP_PJT_LIST.STORAGE_ID;
                V_CURSSP_STORAGE_PLANT_ID := CUR_BNP_PJT_LIST.STORAGE_PLANT_ID;
                V_CURSSP_PUCH_MGR         := CUR_BNP_PJT_LIST.PUCH_MGR;
                V_CURSSP_PUCH_GROUP       := CUR_BNP_PJT_LIST.PUCH_GROUP;
                V_CURSSP_PR_HEADER        := CUR_BNP_PJT_LIST.PR_HEADER;
                V_CURSSP_ITEM_DETAIL      := CUR_BNP_PJT_LIST.ITEM_DETAIL;

                /*
                V_REQUEST_NO 채번
                */
                SELECT MAX(REQUEST_NO)
                  INTO V_MAX_NO
                  FROM DM_PLN_PR_DETAIL
                 WHERE REQUEST_NO LIKE TO_CHAR(SYSDATE, 'YYYYMMDD')||'%'
                   AND PROJECT_CODE = V_CURSSP_PROJECT_CODE
                   AND ITEM_ID = V_CURSSP_ITEM_ID;

                IF V_MAX_NO IS NOT NULL THEN

                    /* 기존의 MAX 값 + 1 */
                    SELECT MAX(REQUEST_NO)
                      INTO V_MAX_NO
                      FROM DM_PLN_PR_DETAIL
                     WHERE REQUEST_NO LIKE TO_CHAR(SYSDATE, 'YYYYMMDD')||'%';

                    V_REQUEST_NO := TO_CHAR(SYSDATE, 'YYYYMMDD')||FN_ZERO_LPAD(TO_CHAR(TO_NUMBER(SUBSTR(V_MAX_NO, -6)) + 1), 6);
                ELSE
                    /* SET @V_REQUEST_NO = CONVERT(CHAR(8), GETDATE(), 112) + '000001' */

                    /* 없을 경우에는 기존의 MAX 값 + 1 */
                    SELECT MAX(REQUEST_NO)
                      INTO V_MAX_NO
                      FROM DM_PLN_PR_DETAIL
                     WHERE REQUEST_NO LIKE TO_CHAR(SYSDATE, 'YYYYMMDD')||'%';

                    IF V_MAX_NO IS NOT NULL THEN
                        V_REQUEST_NO := TO_CHAR(SYSDATE, 'YYYYMMDD')||FN_ZERO_LPAD(TO_CHAR(TO_NUMBER(SUBSTR(V_MAX_NO, -6)) + 1), 6);
                    ELSE
                        V_REQUEST_NO := TO_CHAR(SYSDATE, 'YYYYMMDD')||'000001';
                    END IF;

                END IF;

                /* ---------------------------------------------------------------- */

                /*
                ITEM_SEQ 채번
                */
                SELECT MAX(ITEM_SEQ)
                  INTO V_MAX_SEQ
                  FROM DM_PLN_PR_DETAIL
                 WHERE REQUEST_NO = V_REQUEST_NO;

                IF V_MAX_SEQ IS NOT NULL THEN
                    V_SEQ := V_SEQ + 1;
                ELSE
                    V_SEQ := 1;
                END IF;

                /* PR_ITEM_DETAIL 값이 없으면 PR 자동화 요청물량 입력 */
                IF ( RTRIM(V_CURSSP_ITEM_DETAIL) IS NULL ) THEN
                    V_CURSSP_ITEM_DETAIL := 'PR 자동화 요청물량';
                END IF;

                INSERT
                  INTO DM_PLN_PR_DETAIL
                     ( REQUEST_NO
                     , ITEM_SEQ
                     , DIVISION_ID
                     , PROJECT_CODE
                     , SCM_SITE_ID
                     , ITEM_ID
                     , DOM_EXP
                     , FCST_TYPE
                     , INCOTERMS
                     , PLANT_SITE_ID
                     , YYYYMMDD
                     , UOM
                     , PLAN_QTY
                     , STORAGE_ID
                     , STORAGE_PLANT_ID
                     , PUCH_MGR
                     , PUCH_GROUP
                     , PR_HEADER
                     , PR_ITEM_DETAIL
                     , CREATED_BY
                     , CREATION_DATE
                     , LAST_UPDATED_BY
                     , LAST_UPDATE_DATE
                     , SSP_TRANSFER_FLAG
                     , ATTRIBUTE1 )
                VALUES ( V_REQUEST_NO
                       , V_SEQ                        /* row_number() OVER( ORDER BY PROJECT_CODE,SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE,INCOTERMS,YYYYMMDD ) */
                       , V_CURSSP_DIVISION_ID
                       , V_CURSSP_PROJECT_CODE
                       , V_CURSSP_SCM_SITE_ID
                       , V_CURSSP_ITEM_ID
                       , V_CURSSP_DOM_EXP
                       , V_CURSSP_FCST_TYPE
                       , V_CURSSP_INCOTERMS
                       , V_CURSSP_PLANT_SITE_ID
                       , V_CURSSP_BNP_YYYYMMDD        /* BNP IN YYYYMMDD */
                       , V_CURSSP_UOM
                       , V_CURSSP_QTY
                       , V_CURSSP_STORAGE_ID
                       , V_CURSSP_STORAGE_PLANT_ID
                       , V_CURSSP_PUCH_MGR
                       , V_CURSSP_PUCH_GROUP
                       , V_CURSSP_PR_HEADER
                       , V_CURSSP_ITEM_DETAIL
                       , 'SCM_BATCH'
                       , SYSDATE
                       , 'SCM_BATCH'
                       , SYSDATE
                       , 'N'
                       , 'SCM_BATCH' );

                /* -------------------------------------------------------------------------------- */
                DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3')||' ### ESS 프로시저 호출');
                /* -------------------------------------------------------------------------------- */

                /*
                SELECT TOP 1 @V_DIVISION_ID	= DIVISION_ID
                    , @V_PROJECT_CODE	= PROJECT_CODE
                    , @V_SCM_SITE_ID	= SCM_SITE_ID
                    , @V_ITEM_ID		= ITEM_ID
                    , @V_DOM_EXP		= DOM_EXP
                    , @V_FCST_TYPE		= FCST_TYPE
                    , @V_INCOTERMS		= INCOTERMS
                    , @V_MEASURE		= 'BNPIn'
                    , @V_YYYYMMDD		= BNP_YYYYMMDD	--BNP IN YYYYMMDD
                    , @V_PLANT_SITE_ID	= PLANT_SITE_ID
                FROM #TMP_BNP_TARGET_LIST
                WHERE PROJECT_CODE = @V_CUR_PROJECT_CODE
                */
                /* ESS 프로시저 호출
                   트랜잭션 문제가 해결이 안된 관계로 여기서 처리하고, 문제 발생시 DM_PLN_PR_DETAIL 삭제 및 DM_PLN_MKT_FCST UPDATE 한다. */

                /* select @V_REQUEST_NO,@V_CURSSP_DIVISION_ID */

                /* 임시로 */
                PR_SSP_ANL_ESS_REQ(V_REQUEST_NO, V_CURSSP_DIVISION_ID, V_MSG);

                /* NERP 대응 - PR Reqeust를 Interface Table 에 생성하는 프로시저 호출 */
                PR_DM_XIF_ERP_PR_DETAIL_S(P_REQUEST_NO => V_REQUEST_NO);

            END LOOP;

            /* ------------------------------------------------------------------------------------ */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3')||' ### PR Request 메일발송');
            /* ------------------------------------------------------------------------------------ */

            V_TABLE_BODY    := '';
            V_BODY_CONTENTS := '';
            V_HEAD_CONT     := '';
            V_BODY_CONT     := '';
            V_MAIL_TITLE    := '';

            V_TO_MAIL := '';

            /* DECLARE @T_MAIL_ADDR TABLE ( ADDR NVARCHAR(150), SEQ INT IDENTITY(0,1) ) */
            DELETE
              FROM GT_DMF70PR_MAIL_ADDR;

            INSERT
              INTO GT_DMF70PR_MAIL_ADDR
                 ( ADDR
                 , SEQ )
            SELECT A.SEGMENT1
                 , ROW_NUMBER() OVER (ORDER BY A.SEGMENT1) - 1 AS SEQ
              FROM SCM_ADM_LOOKUP_MASTER_DETAIL A
             WHERE A.LOOKUP_TYPE = 'DM_PR_MAIL_ADDR'
               AND A.VALID_YN = 'Y';

            SELECT COUNT(*)
              INTO V_CNT
              FROM GT_DMF70PR_MAIL_ADDR;

            V_I       := 0;
            V_TO_MAIL := '';

            WHILE ( V_I < V_CNT ) LOOP

                /* 원본 : @V_TO_MAIL + ADDR + ';'  (+ CASE WHEN @V_I <> 0 THEN ';' ELSE '' END + ADDR 는 원본에서 주석) */
                SELECT V_TO_MAIL||ADDR||';'
                  INTO V_TO_MAIL
                  FROM GT_DMF70PR_MAIL_ADDR
                 WHERE SEQ = V_I;

                V_I := V_I + 1;
            END LOOP;

            /* ----------------------------- */
            /* SET @v_mail_title = N'[GSCM] PR Requested' */
            V_MAIL_TITLE := '[SCM] PR Requested';     /* [E20230721-001841] 용어 수정  GSCM->SCM */
            V_BODY_CONTENTS := '하기와 같이 PR Request 가 접수 되었습니다. 기 확보된 재고 Allo 후 PR 생성 바랍니다.';
            V_BODY_CONT := '';
            V_HEAD_CONT := '<TR>
                <TH>Request No</TH>
                <TH>Div</TH>
                <TH>Project Code</TH>
                <TH>Seq.</TH>
                <TH>Model</TH>
                <TH>Model Name</TH>
                <TH>UOM</TH>
                <TH>To Site</TH>
                <TH>Request Date</TH>
                <TH>Request Qty</TH>
                <TH>Requestor</TH>
                <TH>Update date</TH>
                </TR>';

            FOR CUR_SEND IN ( SELECT A.REQUEST_NO
                                   , A.DIVISION_ID
                                   , A.PROJECT_CODE
                                   , A.ITEM_SEQ
                                   , A.ITEM_ID
                                   , B.ITEM_NAME
                                   , A.UOM
                                   , A.SCM_SITE_ID
                                   , A.YYYYMMDD
                                   , A.PLAN_QTY
                                   , A.CREATED_BY
                                   , A.LAST_UPDATE_DATE
                                FROM DM_PLN_PR_DETAIL            A
                                   , DM_MST_ITEM_SINGLE_V        B
                                   , GT_DMF70PR_BNP_TARGET_LIST  C
                               WHERE A.DIVISION_ID = B.DIVISION_ID(+)
                                 AND A.ITEM_ID = B.ITEM_ID(+)
                                 AND A.DIVISION_ID = C.DIVISION_ID
                                 AND A.PROJECT_CODE = C.PROJECT_CODE
                                 AND A.SCM_SITE_ID = C.SCM_SITE_ID
                                 AND A.ITEM_ID = C.ITEM_ID
                                 AND A.DOM_EXP = C.DOM_EXP
                                 AND A.FCST_TYPE = C.FCST_TYPE
                                 AND A.INCOTERMS = C.INCOTERMS
                                 AND A.PLANT_SITE_ID = C.PLANT_SITE_ID
                                 AND A.YYYYMMDD = C.BNP_YYYYMMDD
                                 AND A.UOM = C.UOM
                                 AND A.STORAGE_ID = C.STORAGE_ID
                                 AND A.STORAGE_PLANT_ID = C.STORAGE_PLANT_ID
                                 AND A.SSP_TRANSFER_FLAG = 'Y'   /* 20240430 SM TRANSFER_FLAG가 Y인건에 대해서만, 메일 발송하는 대상으로 수정 */
                               ORDER BY A.REQUEST_NO, A.ITEM_SEQ ) LOOP

                V2_REQUEST_NO      := CUR_SEND.REQUEST_NO;
                V_DIVISION_ID      := CUR_SEND.DIVISION_ID;
                V_PROJECT_CODE     := CUR_SEND.PROJECT_CODE;
                V_ITEM_SEQ         := CUR_SEND.ITEM_SEQ;
                V_ITEM_ID          := CUR_SEND.ITEM_ID;
                V_ITEM_NAME        := CUR_SEND.ITEM_NAME;
                V_UOM              := CUR_SEND.UOM;
                V_SCM_SITE_ID      := CUR_SEND.SCM_SITE_ID;
                V_CURSOR_YYYYMMDD  := CUR_SEND.YYYYMMDD;
                V_PLAN_QTY         := CUR_SEND.PLAN_QTY;
                V_CREATED_BY       := CUR_SEND.CREATED_BY;
                V_LAST_UPDATE_DATE := CUR_SEND.LAST_UPDATE_DATE;

                V_BODY_CONT := V_BODY_CONT||'<TR>';
                V_BODY_CONT := V_BODY_CONT||'<TD>'||V2_REQUEST_NO||'</TD>';
                V_BODY_CONT := V_BODY_CONT||'<TD>'||V_DIVISION_ID||'</TD>';
                V_BODY_CONT := V_BODY_CONT||'<TD>'||V_PROJECT_CODE||'</TD>';
                V_BODY_CONT := V_BODY_CONT||'<TD>'||TO_CHAR(V_ITEM_SEQ)||'</TD>';
                V_BODY_CONT := V_BODY_CONT||'<TD>'||V_ITEM_ID||'</TD>';
                V_BODY_CONT := V_BODY_CONT||'<TD>'||V_ITEM_NAME||'</TD>';
                V_BODY_CONT := V_BODY_CONT||'<TD>'||V_UOM||'</TD>';
                V_BODY_CONT := V_BODY_CONT||'<TD>'||V_SCM_SITE_ID||'</TD>';
                V_BODY_CONT := V_BODY_CONT||'<TD>'||TO_CHAR(TO_DATE(V_CURSOR_YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD')||'</TD>';
                V_BODY_CONT := V_BODY_CONT||'<TD ALIGN="RIGHT">'||FN_GET_NUMER_TO_STRING(V_PLAN_QTY, 0)||'</TD>';
                V_BODY_CONT := V_BODY_CONT||'<TD>'||V_CREATED_BY||'</TD>';
                V_BODY_CONT := V_BODY_CONT||'<TD>'||TO_CHAR(V_LAST_UPDATE_DATE, 'YYYY-MM-DD')||'</TD>';
                V_BODY_CONT := V_BODY_CONT||'</TR>';

            END LOOP;

            V_TABLE_BODY := ' <html>
                            <head>
                                    <title>Untitled Document</title>
                                    <style>
                                        * {margin:0;padding:0;}
                                        body {font-family:Malgun Gothic, Arial, Helvetica, sans-serif;font-size:12px;line-height:1.8;color:#333333;}
                                        table {border-collapse:collapse;width:100%;}
                                        table th {background:#f5f5f5;border-bottom:1px solid #e1e1e1;}
                                        table td {background:#fff;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1;border-bottom:1px solid #e1e1e1;}
                                        table tbody th {border-left:1px solid #e1e1e1;text-align:right;padding:6px 8px;font-size:12px}
                                        table tbody td {padding:6px 8px;font-size:12px}
                                        table thead th {text-align:center;padding:3px;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1; border-bottom:1px solid #d1d1d1;font-size:12px}
                                        .hori-table table thead td {text-align:center;padding:3px;}
                                        .hori-table table tbody td {text-align:center;padding:3px;}
                                        .vertical-table, .hori-table {margin-bottom:20px;}
                                    </style>
                                    </head>
                                    <body>'||'</br>'||
                                            '<b>'||REPLACE(V_BODY_CONTENTS, CHR(10), '<br>')||'</b>'||
                                            '<div id="divBody" style="width: 100%; overflow-x: auto; overflow-y: auto; font-size: 9pt; line-break: auto;">'||
                                        '<table style=''border-top:2px solid #c8294b; width:1450px;''>
                                        <thead>'||V_HEAD_CONT||'</thead>
                                        <tbody>'||V_BODY_CONT||'</tbody>
                                        </div>
                                    </body>
                            </html>';

    /*
                EXEC SCM_ADM_MAIL_SEND
                    'kjj0070@lgespartner.com'				--//'kahonmalu@lgensol.com'
                    , @v_mail_title
                    , @TABLE_BODY
                    , 'Y'
    */

            /* 메일 발송 */
            /* 발송 환경 가드 교정(2026-10-06) : 원본 IF DB_NAME() <> 'LGCE_SCMDEV' 는 사내망 MSSQL 이
               개발·품질 둘 다 DB 이름 LGCE_SCMDEV 라 운영 전용 조건이다. Oracle 엔 그 이름의 DB 가 없어
               항상 참(=항상 발송)이 되므로 운영 PDB 일치 조건 LIKE 'OCGSCMP%' 로 교체했다. */
            IF SYS_CONTEXT('USERENV', 'DB_NAME') LIKE 'OCGSCMP%' THEN
                /* 원본 EXEC SCM_ADM_MAIL_SEND @v_to_mail, @v_mail_title, @TABLE_BODY, 'Y' */
                PKG_SEND_MAIL.P_SEND_MAIL_CLOB(V_TO_MAIL          /* 원본 주석 : 'kahonmalu@lgensol.com' */
                                             , V_MAIL_TITLE
                                             , V_TABLE_BODY
                                             , 'Y');

                /* MAIL 발송 LOG 저장 */
                SCM_ADM_SAVE_MAIL_SEND_BATCH_LOG(
                    'MAIL'
                  , 0
                  , V_PROGRAM_NAME
                  , V_DIVISION_ID
                  , V_REQUEST_NO
                  , ''
                  , ''
                  , ''
                  , ''
                  , ''
                  , ''
                  , ''
                  , ''                                           /* p_send_pgm */
                  , V_TO_MAIL
                );
            END IF;

        END IF;

        IF DBMS_TRANSACTION.LOCAL_TRANSACTION_ID IS NOT NULL THEN
            COMMIT;
        END IF;
    /* ------------------------------------------------------------------------------------------ */

    /* -------------------------------------------------------------------------------------------- */

    /* -------------------------------------------------------------- */
    EXCEPTION
    /* -------------------------------------------------------------- */
        WHEN OTHERS THEN
            /* 트랜잭션 (END)
               select XACT_STATE() as xact_state_1, @@trancount
               select XACT_STATE() as xact_state_2, @@trancount, 'A21' */
            IF DBMS_TRANSACTION.LOCAL_TRANSACTION_ID IS NOT NULL THEN
                ROLLBACK;
            END IF;

            V_LOG_TYPE        := 'ERROR';
            V_LOG_MESSAGE     := SUBSTR(SQLERRM, 1, 1000);
            V_LOG_DESCRIPTION := 'ERROR_LINE : '||SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 480);
            D_EVENT_DATE      := SYSDATE;
            V_IN_PARA_DATA    := NULL;

            DBMS_OUTPUT.PUT_LINE('['||TO_CHAR(SQLCODE)||']'||SQLERRM);   /* 에러메시지 DISPLAY */

            PR_DM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_LOG_DESCRIPTION, D_EVENT_DATE, 'SCM_BATCH'
                              , V_IN_PARA_DATA, TO_CHAR(SQLCODE), SQLERRM, DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);


            RAISE_APPLICATION_ERROR(-20001, '['||V_PROGRAM_NAME||'] SQLCODE='||SQLCODE||' / SQLERRM='||SQLERRM
                                          ||' / BACKTRACE='||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);

    /* -------------------------------------------------------------- */
    END;
    /* -------------------------------------------------------------- */


    V_LOG_TYPE        := 'END';
    V_LOG_MESSAGE     := '########## END of procedure @@@##########';
    V_LOG_DESCRIPTION := 'input_count: '||TO_CHAR(N_INPUT_COUNT);
    D_EVENT_DATE      := SYSDATE;

    PR_DM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_LOG_DESCRIPTION, D_EVENT_DATE, 'SCM_BATCH');

END;

PROCEDURE DMF0070_AUTO_PR_REQUEST_MAIL
/* ============================================================
 * Program ID   : DMF0070_AUTO_PR_REQUEST_MAIL
 * Description  : Procedure 작성 가이드
 * Usage        : PR Request 자동 생성 대상 추출하여 메일발송
 * Parameter    :
 * Program History
 *------------------------------------------------------------
 * Date          In Charge      Description
 *------------------------------------------------------------
 * 2024-01-25    kjj            신규생성
 * 2024-06-05    JSSBAE         [E20240529-001017]_Auto PR Request 개선요청건
 *                              W1 주차에 Auto PR 데이터 생성 후 BNP In이 생성되지 않은 대상은
 *                              W2 주차에 대상이되는 데이터로 Auto PR 목록에 다시 생성 되어야 함
 * 2026-08-03    ZIONEX         [PJ202650304]  NextSCM Migration
 *
 * EXEC DMF0070_AUTO_PR_REQUEST_MAIL
 * ============================================================ */
AS

/*
--메인테이블 변경
DM_PLN_BNP_IN_PR_DETAIL_AUTO
=>DM_PLN_AUTO_PR_CHECK


*/

    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME     VARCHAR2(150 CHAR) := 'DMF0070_AUTO_PR_REQUEST_MAIL';
    V_LOG_TYPE         VARCHAR2(30 CHAR);   /* START/END/ERROR/... */
    N_LOG_COUNT        NUMBER := 0;
    V_LOG_MESSAGE      VARCHAR2(1000 CHAR);
    V_LOG_DESCRIPTION  VARCHAR2(500 CHAR);
    D_EVENT_DATE       DATE;
    N_DELETE_COUNT     NUMBER := 0;
    N_INSERT_COUNT     NUMBER := 0;
    N_INPUT_COUNT      NUMBER := 0;
    N_LOGO_COUNT       NUMBER := 0;
    N_INVALID_ITEM     VARCHAR2(50 CHAR);
    N_MSG              VARCHAR2(1000 CHAR);
    V_BF_REQ_NO        VARCHAR2(30 CHAR);
    V_BF_QTY           NUMBER(10) := 0;
    V_THIS_QTY         NUMBER(10) := 0;


    /* 원본 @V_SUB_QRY NVARCHAR(MAX) = '' : Oracle 은 ''=NULL 이므로 초기값 NULL,
       원본 IF @V_SUB_QRY <> '' 은 IF V_SUB_QRY IS NOT NULL 로 대응 */
    V_SUB_QRY          CLOB;

    V_CUR_DIVISION     VARCHAR2(100 CHAR);
    V_CUR_INCOTERMS    VARCHAR2(100 CHAR);
    V_CUR_COUNTRY      VARCHAR2(100 CHAR);
    V_CUR_BNP_WEEK     VARCHAR2(100 CHAR);  /* BNP IN 출하시점 */
    V_CUR_DATA_WEEK    VARCHAR2(150 CHAR);  /* DATA 생성 시점(대상추출 메일발송은 DATA 생성시점의 1주 전) */
    V_CUR_NOT_COND     VARCHAR2(1000 CHAR); /* NOT 조건으로 지정된 건 */

    V_TABLE_BODY       CLOB;
    V_BODY_CONTENTS    CLOB;
    V_HEAD_CONT        CLOB;
    V_BODY_CONT        CLOB;
    /* , @v_to_mail  NVARCHAR(150) */
    V_MAIL_TITLE       VARCHAR2(100 CHAR);
    V_CNT              NUMBER(10);
    V_I                NUMBER(10);

    V_CUR_MODEL        VARCHAR2(100 CHAR);
    V_CUR_SITE         VARCHAR2(100 CHAR);
    V_CUR_PROJECT      VARCHAR2(8 CHAR);
    V_CUR_QTY          NUMBER(30,10);
    V_CUR_YYYYMMDD     VARCHAR2(10 CHAR);
    V_CUR_TOOWNER      VARCHAR2(150 CHAR);
    V_CUR_TOMAIL       VARCHAR2(150 CHAR);

    /* ------------------------------------------------------------
    * 본문 동일 수신자 묶음 (2026-10-06) — 같은 내용을 오너별로 개별 발송하던 것을
    * 수신인을 ';' 로 이어 한 통으로 보내기 위한 작업용 선언
    * ------------------------------------------------------------ */
    C_TO_MAIL_MAX    CONSTANT PLS_INTEGER := 4000;   /* PKG_SEND_MAIL 바디의 V_TO_MAIL VARCHAR2(4000) 와 정합 */
    C_GRP_PROBE_LEN  CONSTANT PLS_INTEGER := 1000;   /* 해시 후보용 선두 글자수. 1000자 x 최대 3바이트 < 4000 */
    TYPE T_GRP_REC IS RECORD ( BODY_CONT CLOB
                             , ADDR_LIST VARCHAR2(4000 CHAR) );
    TYPE T_GRP_TAB IS TABLE OF T_GRP_REC INDEX BY VARCHAR2(200 CHAR);
    V_GROUP            T_GRP_TAB;
    V_GRP_REC          T_GRP_REC;
    V_GRP_KEY          VARCHAR2(200 CHAR);
    V_SLOT_KEY         VARCHAR2(200 CHAR);
    V_GRP_IDX          VARCHAR2(200 CHAR);
    V_SLOT             PLS_INTEGER;
    V_GRP_PROBE        VARCHAR2(4000 CHAR);
    V_SAME_BODY        BOOLEAN;

    V_IN_PARA_DATA     VARCHAR2(4000 CHAR);

BEGIN


    /* 시작 LOG  (START) */
    V_LOG_TYPE := 'START';
    V_LOG_MESSAGE := '########## Start of procedure @@@##########';
    V_LOG_DESCRIPTION := '';
    D_EVENT_DATE := SYSDATE;
    PR_DM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_LOG_DESCRIPTION, D_EVENT_DATE, 'SCM_BATCH');
    V_LOG_MESSAGE := NULL;   /* 변수 재사용을 위하여 초기화해야함 */


    /* -------------------------------------------------------------------------------------- */

    /* -------------------------------------------------------------------------------------- */
    BEGIN
            /* 메일발송 주기(케이스 별) */
            /*
            *1차
        (A) Incoterms= EXW => D-91(13주)
        (B) Incoterms = C* or F*, Country=KR => D-119(17주)
        (C) Incoterms = D*, Country=JP => D-119(17주)
        (D) Incoterms = D*, Country = not KR => D-175(25주)


            *2차
        (A) Incoterms= EXW => D-20 (3주 전)
        (B) Incoterms = C* or F*, Country=KR => D-48 (7주 전)
        (C) Incoterms = D*, Country=JP => D-48 (7주 전)
        (D) Incoterms = D*, Country = not KR => D-104 (15주 전)
            */

            /* ------------------------------------------------------------------------------ */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### 메일발송 대상추출 ');
            /* ------------------------------------------------------------------------------ */
            /* 대상 추출------------------------------------------ */

            DELETE
              FROM GT_DMF70ML_TARGET_LIST;

            V_SUB_QRY := NULL;


            FOR R_GUIDE IN ( SELECT SEGMENT1
                                  , SEGMENT2
                                  , SEGMENT3
                                  , SEGMENT4
                                  , SEGMENT5
                               FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                              WHERE LOOKUP_TYPE = 'AUTO_PR_CHECK_CRITERIA'
                                AND VALID_YN = 'Y'
                              ORDER BY DISPLAY_SEQ )
            LOOP

                V_CUR_DIVISION  := R_GUIDE.SEGMENT1;
                V_CUR_INCOTERMS := R_GUIDE.SEGMENT2;
                V_CUR_COUNTRY   := R_GUIDE.SEGMENT3;
                V_CUR_BNP_WEEK  := R_GUIDE.SEGMENT4;
                V_CUR_DATA_WEEK := R_GUIDE.SEGMENT5;

                IF V_SUB_QRY IS NOT NULL THEN
                    V_SUB_QRY := V_SUB_QRY || '
                    UNION
                    ';
                END IF;

                /*                   n = @CUR_DATA_WEEK + 1 : MSSQL 은 nvarchar + int 를 자료형우선순위로 int 연산 → TO_NUMBER 사용. */
                V_SUB_QRY := V_SUB_QRY || '
                    SELECT MS.COUNTRY
                  , (
                        SELECT MP.PROJECT_OWNER FROM SCM_MST_PROJECT MP
                        WHERE MP.DIVISION_ID = MF.DIVISION_ID
                        AND MP.PROJECT_CODE = MF.PROJECT_CODE
                        AND ROWNUM = 1
                    ) PROJECT_OWNER
                  , (
                        SELECT ITM.OWNER FROM SCM_MST_SITE_ITEM ITM
                        WHERE ITM.DIVISION_ID = MF.DIVISION_ID
                        AND ITM.PROJECT_CODE = MF.PROJECT_CODE
                        AND ITM.SCM_SITE_ID = MF.SCM_SITE_ID
                        AND ITM.ITEM_ID = MF.ITEM_ID
                        AND ROWNUM = 1
                    ) OWNER
                    , MF.ITEM_ID, MF.SCM_SITE_ID, MF.PROJECT_CODE, MF.QTY, MF.YYYYMMDD
                    , MF.DIVISION_ID
                    , MF.DOM_EXP
                    , MF.FCST_TYPE
                    , MF.INCOTERMS
                    , MF.MEASURE
                    , MF.PLANT_SITE_ID
                    FROM DM_PLN_MKT_FCST MF
                       , SCM_ADM_LOOKUP_MASTER_DETAIL LUP
                       , SCM_MST_SITE MS
                    WHERE MF.DIVISION_ID = LUP.SEGMENT1
                    AND MF.ITEM_ID = LUP.SEGMENT2
                    AND MF.DIVISION_ID = MS.DIVISION_ID
                    AND MF.SCM_SITE_ID = MS.SCM_SITE_ID
                    AND LUP.VALID_YN = ''Y''
                    AND LUP.LOOKUP_TYPE = ''ESS_PRICE_EXCEPT_MODEL''
                    AND MF.MEASURE = ''MKT_FCST''
                    AND RTRIM(MF.ATTRIBUTE9) IS NULL /* 확정되지 않은 것들 (원본 ISNULL(MF.ATTRIBUTE9,'''')='''') */
                    /* [E20240529-001017]_Auto PR Request 개선요청건
                    AND NOT EXISTS --메일전송목록에 없는 것들만 발송
                    (
                        SELECT * FROM DM_PLN_AUTO_PR_CHECK ATO WITH(NOLOCK)
                        WHERE ATO.DIVISION_ID = MF.DIVISION_ID
                        AND ATO.PROJECT_CODE = MF.PROJECT_CODE
                        AND ATO.SCM_SITE_ID = MF.SCM_SITE_ID
                        AND ATO.ITEM_ID = MF.ITEM_ID
                        AND ATO.DOM_EXP = MF.DOM_EXP
                        AND ATO.FCST_TYPE = MF.FCST_TYPE
                        AND ATO.INCOTERMS = MF.INCOTERMS
                        AND ATO.PLANT_SITE_ID = MF.PLANT_SITE_ID
                        AND ATO.MKT_FCST_DATE = MF.YYYYMMDD
                        AND ATO.PLAN_QTY = MF.QTY
                    ) */
                    AND MF.QTY > 0 /* 수량이 0 이상인 것들만 */
                    AND
                    (
                        (
                            MF.YYYYMMDD >=
                            (
                                    SELECT BASIS_START_DATE FROM SCM_SYS_CALENDAR_M
                                    WHERE BASIS_YYYYMMDD = TO_CHAR(SYSDATE + (' || TO_CHAR(TO_NUMBER(V_CUR_DATA_WEEK) + 1) || ' * 7), ''YYYYMMDD'') /* 데이터 생성 시점의 1주 전 */
                            )
                            AND MF.YYYYMMDD <=
                            (
                                    SELECT BASIS_END_DATE FROM SCM_SYS_CALENDAR_M
                                    WHERE BASIS_YYYYMMDD = TO_CHAR(SYSDATE + (' || TO_CHAR(TO_NUMBER(V_CUR_DATA_WEEK) + 1) || ' * 7), ''YYYYMMDD'')
                            )
                        )
                        OR
                        (
                            MF.YYYYMMDD >=
                            (
                                    SELECT BASIS_START_DATE FROM SCM_SYS_CALENDAR_M
                                    WHERE BASIS_YYYYMMDD = TO_CHAR(SYSDATE + (' || TO_CHAR(TO_NUMBER(V_CUR_DATA_WEEK) + 1 - 10) || ' * 7), ''YYYYMMDD'') /* 2차발송은 1차의 10주 뒤 */
                            )
                            AND MF.YYYYMMDD <=
                            (
                                    SELECT BASIS_END_DATE FROM SCM_SYS_CALENDAR_M
                                    WHERE BASIS_YYYYMMDD = TO_CHAR(SYSDATE + (' || TO_CHAR(TO_NUMBER(V_CUR_DATA_WEEK) + 1) || ' * 7), ''YYYYMMDD'') /* To는 1차발송일과 동일 */
                            )
                        )
                    )

                ';

                /* INCOTERMS */
                IF V_CUR_INCOTERMS <> '-' THEN

                    IF INSTR(V_CUR_INCOTERMS, '*') > 0 THEN

                        V_SUB_QRY := V_SUB_QRY || '
                            AND MF.INCOTERMS LIKE ''' || REPLACE(V_CUR_INCOTERMS, '*', '%') || '''
                        ';


                    ELSIF INSTR(UPPER(V_CUR_INCOTERMS), 'NOT_') > 0 THEN
                    /*
                    --Not 의 규칙
                    1)Not_로 등록
                    2)여러개일 경우는 ,로 구분
                    */
                        /* 원본 CUR_NOT_COND CURSOR : SELECT TOKEN FROM DBO.UF_FX_STRING_SPLIT(@CUR_INCOTERMS, ',') */
                        FOR R_NOT IN ( SELECT TOKEN
                                         FROM TABLE(UF_FX_STRING_SPLIT(V_CUR_INCOTERMS, ',')) )
                        LOOP

                            V_CUR_NOT_COND := R_NOT.TOKEN;

                            /* 원본 REPLACE(@V_CUR_NOT_COND,'NOT_','') : MSSQL REPLACE 는 CI 콜레이션이라 'Not_' 도 제거.
                               Oracle REPLACE 는 대소문자 구분 → REGEXP_REPLACE(...,'i') 로 CI 재현 */
                            V_SUB_QRY := V_SUB_QRY || '
                                AND MF.INCOTERMS <> ''' || REGEXP_REPLACE(V_CUR_NOT_COND, 'NOT_', '', 1, 0, 'i') || '''
                            ';

                        END LOOP;

                    ELSE

                        V_SUB_QRY := V_SUB_QRY || '
                            AND MF.INCOTERMS = ''' || V_CUR_INCOTERMS || '''
                        ';

                    END IF;
                END IF;

                /* COUNTRY */
                IF V_CUR_COUNTRY <> '-' THEN

                    IF INSTR(V_CUR_COUNTRY, '*') > 0 THEN

                        V_SUB_QRY := V_SUB_QRY || '
                            AND MS.COUNTRY LIKE ''' || REPLACE(V_CUR_COUNTRY, '*', '%') || '''
                        ';

                    ELSIF INSTR(UPPER(V_CUR_COUNTRY), 'NOT_') > 0 THEN

                    /*
                        SET @V_SUB_QRY = @V_SUB_QRY + N'
                            AND MS.COUNTRY <> ''' + REPLACE(@CUR_COUNTRY,'NOT ', '') + '''
                        '
                        */
                        /*
                        --Not 의 규칙
                        1)Not_로 등록
                        2)여러개일 경우는 ,로 구분
                        */
                        FOR R_NOT IN ( SELECT TOKEN
                                         FROM TABLE(UF_FX_STRING_SPLIT(V_CUR_COUNTRY, ',')) )
                        LOOP

                            V_CUR_NOT_COND := R_NOT.TOKEN;

                            V_SUB_QRY := V_SUB_QRY || '
                                AND MS.COUNTRY <> ''' || REGEXP_REPLACE(V_CUR_NOT_COND, 'NOT_', '', 1, 0, 'i') || '''
                            ';

                        END LOOP;

                    ELSE

                        V_SUB_QRY := V_SUB_QRY || '
                            AND MS.COUNTRY = ''' || V_CUR_COUNTRY || '''
                        ';

                    END IF;
                END IF;

            END LOOP;

            /* PRINT @V_SUB_QRY */
            /* EXEC (@V_SUB_QRY)  : 원본 주석행 — 실행코드 아님 */

            /* PRINT @V_QRY */
            /* 원본 INSERT #TMP_TARGET_LIST EXEC (@V_SUB_QRY) → EXECUTE IMMEDIATE 로 GTT 적재
               (동적 SELECT 의 컬럼 순서 = 아래 컬럼 목록 순서와 1:1) */
            EXECUTE IMMEDIATE 'INSERT INTO GT_DMF70ML_TARGET_LIST ( COUNTRY, PROJECT_OWNER, OWNER, ITEM_ID, SCM_SITE_ID, PROJECT_CODE, QTY, YYYYMMDD, DIVISION_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID ) ' || V_SUB_QRY;

            /* SELECT * FROM #TMP_TARGET_LIST */


            DELETE
              FROM GT_DMF70ML_OWNER_LIST;

            /* OWNER 정보 추출 */
            INSERT INTO GT_DMF70ML_OWNER_LIST
                 ( TO_OWNER )
            SELECT A.TO_OWNER
              FROM ( SELECT UPPER(PROJECT_OWNER) TO_OWNER
                       FROM GT_DMF70ML_TARGET_LIST
                      WHERE RTRIM(PROJECT_OWNER) IS NOT NULL
                     UNION
                     SELECT UPPER(OWNER) TO_OWNER
                       FROM GT_DMF70ML_TARGET_LIST
                      WHERE RTRIM(OWNER) IS NOT NULL ) A;

            /* ------------------------------------------------------------------------------ */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### 메일발송');
            /* ------------------------------------------------------------------------------ */

            /* ----------------------------- */
            V_MAIL_TITLE := '[SCM.DM] BNP In & PR Request 자동생성 대상 안내';
            V_BODY_CONTENTS := '안녕하십니까, SCM.DM 시스템입니다. 다음주 <B>월요일</B> BNP In과 PR Request 자동수행 대상을 안내드립니다.</BR>
                    자동생성을 위해서는 SCM 시스템 → Demand → Demand Plan → Auto PR Check화면에서 <B>Plant Site, SLOC 정보를 이번 주</B> 안에 입력해주셔야 합니다. (공란일 시 생성 X)
                    PR 요청 취소가 필요하다면 SCM 시스템 → Demand > Demand Plan > Auto PR Check 화면에 접속하시어 ''BNP In/PR Request Auto'' 값을 <B>N</B> 으로 수정해주시기 바랍니다.
                    PR 요청 수정이 필요하다면
                1) MKT FCST 입력값을 수정 → 1주 후에 다시 메일 안내 드리며
                2) 긴급 건은 수기로 BNP In 입력 → 수기로 PR Request 진행 부탁드립니다.';

            V_BODY_CONT := '';
            V_HEAD_CONT := '<TR>
                <TH>Model 코드</TH>
                <TH>Sales Site</TH>
                <TH>Project Code</TH>
                <TH>QTY</TH>
                <TH>YYYYMMDD</TH>
                </TR>';

            /* 발송할 오너 가져오기 */
            FOR R_OWNER IN ( SELECT TO_OWNER
                                  , TO_OWNER || '@lgensol.com' AS TO_MAIL
                               FROM GT_DMF70ML_OWNER_LIST )
            LOOP

                V_CUR_TOOWNER := R_OWNER.TO_OWNER;
                V_CUR_TOMAIL  := R_OWNER.TO_MAIL;

                V_BODY_CONT := '';

                /* 오너에 맞는 대상 목록 가져오기 */
                FOR R_TARGET IN ( SELECT ITEM_ID
                                       , SCM_SITE_ID
                                       , SUBSTR(PROJECT_CODE, 1, 8) AS PROJECT_CODE
                                       , QTY
                                       , YYYYMMDD
                                    FROM GT_DMF70ML_TARGET_LIST
                                   WHERE UPPER(PROJECT_OWNER) = UPPER(V_CUR_TOOWNER)
                                      OR UPPER(OWNER) = UPPER(V_CUR_TOOWNER) )
                LOOP

                    V_CUR_MODEL    := R_TARGET.ITEM_ID;
                    V_CUR_SITE     := R_TARGET.SCM_SITE_ID;
                    V_CUR_PROJECT  := R_TARGET.PROJECT_CODE;
                    V_CUR_QTY      := R_TARGET.QTY;
                    V_CUR_YYYYMMDD := R_TARGET.YYYYMMDD;


                    V_BODY_CONT := V_BODY_CONT || '<TR>';
                    V_BODY_CONT := V_BODY_CONT || '<TD>' || V_CUR_MODEL || '</TD>';
                    V_BODY_CONT := V_BODY_CONT || '<TD>' || V_CUR_SITE || '</TD>';
                    V_BODY_CONT := V_BODY_CONT || '<TD>' || V_CUR_PROJECT || '</TD>';
                    V_BODY_CONT := V_BODY_CONT || '<TD ALIGN="RIGHT">' || FN_GET_NUMER_TO_STRING(V_CUR_QTY, 0) || '</TD>';
                    V_BODY_CONT := V_BODY_CONT || '<TD>' || V_CUR_YYYYMMDD || '</TD>';
                    V_BODY_CONT := V_BODY_CONT || '</TR>';

                END LOOP;

                /* ------------------------------------------------------------
                * 본문이 같은 오너를 한 묶음으로 모은다 (2026-10-06)
                * - 해시는 묶음 후보를 빨리 찾기 위한 것이고, 합칠지는 본문 전문 비교로 확정한다
                *   (해시가 충돌해 다른 본문이 한 통에 섞이면 잘못된 내용이 나가기 때문)
                * - 본문이 CLOB 이라 해시는 선두 C_GRP_PROBE_LEN 글자로 만들고
                *   확정 비교는 DBMS_LOB.COMPARE 로 본문 전문을 본다
                * - 수신인 목록이 상한을 넘으면 같은 본문으로 묶음을 하나 더 만든다(절단 방지)
                * ------------------------------------------------------------ */
                V_GRP_PROBE := NVL(DBMS_LOB.SUBSTR(V_BODY_CONT, C_GRP_PROBE_LEN, 1), ' ');
                V_GRP_KEY   := TO_CHAR(DBMS_UTILITY.GET_HASH_VALUE(V_GRP_PROBE, 0, 1073741824));
                V_SLOT      := 1;

                LOOP

                    V_SLOT_KEY := V_GRP_KEY || '|' || TO_CHAR(V_SLOT);

                    IF NOT V_GROUP.EXISTS(V_SLOT_KEY) THEN
                        V_GRP_REC.BODY_CONT := V_BODY_CONT;
                        V_GRP_REC.ADDR_LIST := V_CUR_TOMAIL;
                        V_GROUP(V_SLOT_KEY) := V_GRP_REC;
                        EXIT;
                    END IF;

                    V_SAME_BODY := ( V_GROUP(V_SLOT_KEY).BODY_CONT IS NULL AND V_BODY_CONT IS NULL );

                    IF NOT V_SAME_BODY
                       AND V_GROUP(V_SLOT_KEY).BODY_CONT IS NOT NULL
                       AND V_BODY_CONT IS NOT NULL THEN
                        V_SAME_BODY := ( DBMS_LOB.COMPARE(V_GROUP(V_SLOT_KEY).BODY_CONT, V_BODY_CONT) = 0 );
                    END IF;

                    IF V_SAME_BODY
                       AND LENGTHB(V_GROUP(V_SLOT_KEY).ADDR_LIST || ';' || V_CUR_TOMAIL) <= C_TO_MAIL_MAX THEN
                        V_GROUP(V_SLOT_KEY).ADDR_LIST := V_GROUP(V_SLOT_KEY).ADDR_LIST || ';' || V_CUR_TOMAIL;
                        EXIT;
                    END IF;

                    V_SLOT := V_SLOT + 1;

                END LOOP;

            END LOOP;

            /* 묶음마다 한 통만 발송한다 (수신인 = ';' 로 연결) */
            V_GRP_IDX := V_GROUP.FIRST;

            WHILE V_GRP_IDX IS NOT NULL LOOP

                V_BODY_CONT := V_GROUP(V_GRP_IDX).BODY_CONT;

                V_TABLE_BODY := ' <html>
                                <head>
                                        <title>Untitled Document</title>
                                        <style>
                                            * {margin:0;padding:0;}
                                            body {font-family:Malgun Gothic, Arial, Helvetica, sans-serif;font-size:12px;line-height:1.8;color:#333333;}
                                            table {border-collapse:collapse;width:100%;}
                                            table th {background:#f5f5f5;border-bottom:1px solid #e1e1e1;}
                                            table td {background:#fff;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1;border-bottom:1px solid #e1e1e1;}
                                            table tbody th {border-left:1px solid #e1e1e1;text-align:right;padding:6px 8px;font-size:12px}
                                            table tbody td {padding:6px 8px;font-size:12px}
                                            table thead th {text-align:center;padding:3px;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1; border-bottom:1px solid #d1d1d1;font-size:12px}
                                            .hori-table table thead td {text-align:center;padding:3px;}
                                            .hori-table table tbody td {text-align:center;padding:3px;}
                                            .vertical-table, .hori-table {margin-bottom:20px;}
                                        </style>
                                        </head>
                                        <body>' || '</br>' ||
                                                '<b>' || REPLACE(V_BODY_CONTENTS, CHR(10), '<br>') || '</b>' ||
                                                '<div id="divBody" style="width: 100%; overflow-x: auto; overflow-y: auto; font-size: 9pt; line-break: auto;">'    ||
                                            '<table style=''border-top:2px solid #c8294b; width:1450px;''>
                                            <thead>' || V_HEAD_CONT || '</thead>
                                            <tbody>' || V_BODY_CONT || '</tbody>
                                            </div>
                                        </body>
                                </html>';

                    /*
                    EXEC SCM_ADM_MAIL_SEND
                            'kjj0070@lgespartner.com;park.choyi@lgespartner.com' @CUR_TOMAIL
                        , @v_mail_title
                        , @TABLE_BODY
                        , 'Y'
                        */
                        /*
                    EXEC SCM_ADM_MAIL_SEND
                            'kjj0070@lgespartner.com' @CUR_TOMAIL
                        , @v_mail_title
                        , @TABLE_BODY
                        , 'Y'
                        */
                        /* SELECT @v_body_cont */
                        /* SELECT @CUR_TOMAIL */


                    /* 발송 환경 가드 교정(2026-10-06) : 원본 IF DB_NAME() <> 'LGCE_SCMDEV' 는 사내망 MSSQL 이
                       개발·품질 둘 다 DB 이름 LGCE_SCMDEV 라 운영 전용 조건이다. Oracle 엔 그 이름의 DB 가 없어
                       항상 참(=항상 발송)이 되므로 운영 PDB 일치 조건 LIKE 'OCGSCMP%' 로 교체했다. */
                    IF SYS_CONTEXT('USERENV', 'DB_NAME') LIKE 'OCGSCMP%' THEN
                        /* 원본 EXEC SCM_ADM_MAIL_SEND @CUR_TOMAIL, @v_mail_title, @TABLE_BODY, 'Y'
                             (형제 DMF0070_AUTO_PR_REQUEST / DMF0070_DIFF_QTY_MAIL_SEND_AUTO 와 정책 통일).
                             2026-10-06 수신인을 묶음의 ADDR_LIST(';' 로 연결)로 교체 — 본문이 같은
                             오너끼리 한 통으로 보낸다. 누가 무엇을 보는지는 바뀌지 않는다. */
                        PKG_SEND_MAIL.P_SEND_MAIL_CLOB( V_GROUP(V_GRP_IDX).ADDR_LIST
                                                      , V_MAIL_TITLE
                                                      , V_TABLE_BODY
                                                      , 'Y' );
                    END IF;

                V_GRP_IDX := V_GROUP.NEXT(V_GRP_IDX);

            END LOOP;

            /* ------------------------------------------------------------------------------ */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### 신규테이블에 저장');
            /* ------------------------------------------------------------------------------ */

            MERGE INTO DM_PLN_AUTO_PR_CHECK A
            USING GT_DMF70ML_TARGET_LIST B
               ON ( A.DIVISION_ID = B.DIVISION_ID
                AND A.PROJECT_CODE = B.PROJECT_CODE
                AND A.SCM_SITE_ID = B.SCM_SITE_ID
                AND A.ITEM_ID = B.ITEM_ID
                AND A.DOM_EXP = B.DOM_EXP
                AND A.FCST_TYPE = B.FCST_TYPE
                AND A.INCOTERMS = B.INCOTERMS
                AND A.PLANT_SITE_ID = B.PLANT_SITE_ID
                AND A.MKT_FCST_DATE = B.YYYYMMDD
                AND A.MAIL_INFO_DATE = TO_CHAR(SYSDATE, 'YYYYMMDD') )
            WHEN MATCHED THEN
                UPDATE
                   SET A.PLAN_QTY = B.QTY
                     , A.CREATION_DATE = SYSDATE
                     , A.LAST_UPDATE_DATE = SYSDATE
            WHEN NOT MATCHED THEN
                INSERT
                     ( MAIL_INFO_DATE
                     , DIVISION_ID
                     , PROJECT_CODE
                     , SCM_SITE_ID
                     , ITEM_ID
                     , DOM_EXP
                     , FCST_TYPE
                     , INCOTERMS
                     , PLANT_SITE_ID
                     , MKT_FCST_DATE
                     , PLAN_QTY
                     , CREATED_BY
                     , CREATION_DATE
                     , LAST_UPDATED_BY
                     , LAST_UPDATE_DATE )
                VALUES ( TO_CHAR(SYSDATE, 'YYYYMMDD')
                       , B.DIVISION_ID
                       , B.PROJECT_CODE
                       , B.SCM_SITE_ID
                       , B.ITEM_ID
                       , B.DOM_EXP
                       , B.FCST_TYPE
                       , B.INCOTERMS
                       , B.PLANT_SITE_ID
                       , B.YYYYMMDD
                       , B.QTY
                       , 'SCM_BATCH'
                       , SYSDATE
                       , 'SCM_BATCH'
                       , SYSDATE );

        /* 원본 IF XACT_STATE() > 0 and @@trancount > 0 THEN COMMIT TRAN */
        IF DBMS_TRANSACTION.LOCAL_TRANSACTION_ID IS NOT NULL THEN
            COMMIT;
        END IF;
    /* ---------------------------------------------------------------------------------- */

    /* ---------------------------------------------------------------------------------- */

    /* ------------------------------------------------------ */
    EXCEPTION

    /* ------------------------------------------------------ */
        WHEN OTHERS THEN
            /* 트랜잭션 (END) */
            /* select XACT_STATE() as xact_state_1, @@trancount */
            /* select XACT_STATE() as xact_state_2, @@trancount, 'A21' */
            /* 원본 IF @@trancount > 0 THEN ROLLBACK TRAN */
            IF DBMS_TRANSACTION.LOCAL_TRANSACTION_ID IS NOT NULL THEN
                ROLLBACK;
            END IF;

            V_LOG_TYPE := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);

            V_LOG_DESCRIPTION := SUBSTR('ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 500);
            D_EVENT_DATE := SYSDATE;

            /* 원본 SELECT '[' || Convert(NVARCHAR(10), ERROR_NUMBER()) || ']' || ERROR_MESSAGE() AS ERR_MSG
               (에러메시지 DISPLAY) : 스케줄 배치라 결과셋 소비자가 없음 → DBMS_OUTPUT 로 대체(H-9b) */
            DBMS_OUTPUT.PUT_LINE('[' || TO_CHAR(SQLCODE) || ']' || V_LOG_MESSAGE);


            PR_DM_SYS_LOG_BATCH(V_PROGRAM_NAME
                              , V_LOG_TYPE
                              , N_LOG_COUNT
                              , V_LOG_MESSAGE
                              , V_LOG_DESCRIPTION
                              , D_EVENT_DATE
                              , 'SCM_BATCH'
                              , P_IN_PARA_DATA  => V_IN_PARA_DATA
                              , P_SQL_ERR_CODE  => SQLCODE
                              , P_SQL_ERR_MSG   => SQLERRM
                              , P_SQL_BACKTRACE => DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);


            RAISE_APPLICATION_ERROR(-20001
                                  , '[' || V_PROGRAM_NAME || '] SQLCODE=' || SQLCODE || ' / SQLERRM=' || SQLERRM ||
                                    ' / BACKTRACE=' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE || ' / PARAMS=' || V_IN_PARA_DATA);

    /* ------------------------------------------------------ */

    /* ------------------------------------------------------ */
    END;

    /* 종료 LOG */
    V_LOG_TYPE := 'END';
    V_LOG_MESSAGE := '########## END of procedure @@@##########';
    V_LOG_DESCRIPTION := 'input_count: ' || TO_CHAR(N_INPUT_COUNT);
    D_EVENT_DATE := SYSDATE;

    PR_DM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_LOG_DESCRIPTION, D_EVENT_DATE, 'SCM_BATCH');

END;

PROCEDURE           "DMF0070_DIFF_QTY_MAIL_SEND_AUTO" 
/*************************************************************************************************
* Program ID  : DMF0003_DIFF_QTY_MAIL_SEND_AUTO
* Description : Procedure 작성 가이드
* Usage       : PR Request가 확정된 후에 MKT FCST 데이터가 변경되면(수정 or 삭제), 외주관리팀 담당자에게 자동메일 발송 (실시간 or 일 단위)
* Parameter   :
* Program History
*------------------------------------------------------------------------------------------------
* Date        In Charge    Description
*------------------------------------------------------------------------------------------------
* 2024-01-26   kjj          신규생성
* 2026-08-03   ZIONEX       [PJ202650304]  NextSCM Migration
* --EXEC DMF0070_DIFF_QTY_MAIL_SEND_AUTO
***************************************************************************************************/
/* ================================================================================================
 * 변환 비고 (원본 헤더와 별개. 1:1 이탈 3건은 전부 사용자 결정 2026-08-03 "Oracle에서 안전하게 개선")
 *------------------------------------------------------------------------------------------------
 * [1] 메일 본문 : SCM_ADM_MAIL_SEND(P_BODY_CONTENTS VARCHAR2) -> PKG_SEND_MAIL.P_SEND_MAIL_CLOB
 *     (P_BODY_CLOB CLOB) 로 전환. 사유 = 게이트웨이 경유 시 CLOB 본문을 VARCHAR2 로 넘겨야 해
 *     DBMS_LOB.SUBSTR(...,32767,1) 캡이 필요한데, 이 캡은 예외를 내지 않고 32767 byte 에서
 *     조용히 잘린다(dev 26ai 실증 : 33033/40033/60033자 입력 모두 무예외·32767 byte 반환).
 *     고정부 = HTML 셸 + 인사말 + 헤더행 = 1665 chars / 1797 byte(실측). 고정 프리픽스에 비ASCII
 *     66자가 있어(제목·인사문·Model 코드·QTY(수정전)·QTY(수정후)) 캡의 문자수 상한은
 *     32767 - 132 = 32635 chars 로 결정되고, 행 데이터에 한글이 섞이면 더 줄어들 뿐 늘지 않는다.
 *     행폭은 마크업 고정 109자 + 데이터폭이라 실데이터 실측 최대(OWNER 58 / ITEM_ID 16 /
 *     SCM_SITE_ID 29 / PROJECT_CODE 8자 절단 / PROJECT_OWNER 12 + 수량·일자 문자열) 기준
 *     약 109~230자 -> 한 DIVISION 이 약 135~284행을 넘으면 꼬리 행과 닫는 태그가 통째로
 *     사라진 깨진 HTML 메일이 로그도 없이 발송된다. 수량 문자열 길이가 데이터 의존이라
 *     상한 230 은 확정치가 아니다(하한 135 쪽이 보수적 기준).
 *     원본 NVARCHAR(MAX) 는 무제한이라 명백한 발산 -> 무음 손실을 제거하는 쪽으로 확정.
 *     P_SEND_MAIL_CLOB 은 UTL_SMTP 로 4000자씩 스트리밍해 절단이 없다(ALL_SOURCE 실측).
 *     P_SENDER 기본값이 게이트웨이가 넘기던 값과 동일해 발신자도 불변.
 *     선례 : PR_SSP_MAIL_SEND_SHIP_PLAN_INTER_COM_PO (2026-07-23 결정, 본문 약 85행 초과 시 CLOB).
 *     상실분(게이트웨이 본문 96줄 전수 대조) 4건 :
 *       (a) 게이트웨이 START/END 로그 -> 사라짐(본 proc 자체 로그로 대체).
 *       (b) DB_NAME LIKE '%ESSCMD%' 시 제목 접두 'DEV Oracle 개발서버 ' -> 사라짐.
 *           [3] 가드가 dev/품질 발송을 원천 차단하므로 실질 영향 없음.
 *       (c) 게이트웨이 EXCEPTION 의 ROLLBACK + 10인자 ERROR 로그(프로그램명
 *           SCM_ADM_MAIL_SEND.<caller>, in_para 에 제목·본문 수록) -> 사라짐. ROLLBACK 은 본 proc
 *           핸들러가 동일 수행하므로 무해하나, 발송 실패 시 제목·본문이 담긴 진단 로그 행이
 *           없어진다. 본 proc 의 ERROR 로그는 V_CUR_DIV/V_CUR_ADDR 만 담아 부분 보상에 그친다.
 *       (d) 게이트웨이의 RAISE_APPLICATION_ERROR(-20001, ...+PARAMS) -> 원시 오류 전파로 바뀜.
 *           본 proc 이 다시 -20001 로 감싸므로 잡 실패 감지는 무영향, 메시지가 원시 오류라
 *           진단상 오히려 유리.
 * [1-a] ★배포 전제 : 대상 환경에서 PKG_SEND_MAIL PACKAGE BODY 가 VALID 여야 한다
 *     (ALL_OBJECTS.STATUS + ALL_ERRORS 로 실측 확인). dev 26ai 는 현재 INVALID 다 —
 *     PLS-00201 'UTL_MAIL.SEND'(L142) / 'UTL_MAIL.SEND_ATTACH_RAW'(L195). 오류는
 *     P_SEND_MAIL·P_SEND_MAIL_ATTACH 에만 있고 P_SEND_MAIL_CLOB 은 UTL_SMTP 만 쓰지만,
 *     Oracle 은 바디 전체가 INVALID 면 어떤 서브프로그램도 ORA-06508 로 호출 불가다.
 *     즉 CLOB 전환으로도 UTL_MAIL 의존이 사라지지 않는다. 이는 이번 변경이 만든 위험이 아니라
 *     PKG_SEND_MAIL 을 쓰는 전 메일 변환본의 공통 전제다.
 * [2] 오류 전파 : 원본 CATCH 는 에러를 흡수하고 결과셋으로만 알렸으나, Oracle 변환본에서 그
 *     결과셋이 DBMS_OUTPUT 으로 대체되면 스케줄러 잡이 실패해도 SUCCESS 로 기록된다.
 *     로깅 표준(2026-07-03 확정)대로 에러 로그(11인자) 기록 후 RAISE_APPLICATION_ERROR(-20001) 로
 *     재발생시킨다. 재발생 때문에 에러 경로에서는 종료 LOG 를 남기지 않는다(정상 경로는 유지).
 * [3] 메일 발송 환경 가드 : 원본 IF DB_NAME() <> 'LGCE_SCMDEV' 는 Oracle 에 그 이름의 DB 가
 *     없어 dev/품질/운영 어디서나 항상 참(= 항상 발송)이 된다.
 *     -> SYS_CONTEXT('USERENV','DB_NAME') LIKE 'OCGSCMP%' 로 교체(2026-10-06 재교정).
 *     ★구 교정 NOT IN ('OCGSCMD_P01','OCGSCMQ_P01','ESSCMD') 는 사내망 개발·품질만 막아
 *       사외(ZIOUI1·HSD·AJS)에서도 발송됐다. 원본은 개발·품질 DB 이름이 둘 다 LGCE_SCMDEV 라
 *       운영 전용 조건이므로 운영 PDB(OCGSCMP_P01) 일치 조건이 동등하다.
 *     서비스명을 쓰지 않는 이유 = DBMS_SCHEDULER 잡 세션에서 SERVICE_NAME 이 SYS$USERS 로 나온다
 *     (실측). DB_NAME 은 일반 세션과 잡 세션이 동일하다.
 * ================================================================================================ */
IS
/*
 * 3.포맷정렬(SQL포맷정렬_표준) : 로직 불변, 정렬·주석형식·별칭·조건나열순서만 정리(1.ORA 기준).
 *   - 라인주석을 블록주석으로 전환(2.3), T/E자 우측정렬·leading comma·값 +2칸 적용.
 *   - 조인 CNS화(FM-015) : 유일한 조인인 INNER JOIN DM_PLN_AUTO_PR_CHECK 를 콤마조인 + WHERE 로
 *     전환했다. OUTER JOIN 이 없어 (+) 대상은 없다. INNER 는 ON 조건과 WHERE 조건이 논리적으로
 *     동치라 결과집합·카디널리티 불변.
 *   - 별칭 개명(4.70 FM-016) : MF -> A, MSND -> B, 스칼라 서브쿼리 MP -> SA, ITM -> SB.
 *     토큰만 바뀌고 로직 불변.
 *   - WHERE 나열순서(4.73 FM-020) : 조인조건 -> 상수조건 순으로 재배열. 전부 AND 결합이라
 *     교환법칙상 결과 불변.
 *   - C1/C2 정합성(NVL 선택조건·(+) 배치)은 1.기능변환에서 확정했고 3.에서 재적용하지 않는다(FM-025).
 */
    /* ================================================================================================
     * 원본 @변수 -> Oracle 지역변수(SOP 3.1). 이름은 '@' 만 떼고 대문자화하되, 원본이 접두 없이
     * 선언한 @TABLE_BODY / @CUR_* 는 지역변수임을 드러내도록 V_ 접두를 붙였다(외부 계약 없음).
     * 원본 본문 중간 DECLARE(메일용/커서용)는 전부 선언부로 끌어올렸다(CV-011).
     * ================================================================================================ */

    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME     VARCHAR2(150 CHAR) := 'DMF0070_DIFF_QTY_MAIL_SEND_AUTO';
    V_LOG_TYPE         VARCHAR2(30 CHAR);          /* START/END/ERROR/... */
    N_LOG_COUNT        INTEGER := 0;
    V_LOG_MESSAGE      VARCHAR2(1000 CHAR);
    V_LOG_DESCRIPTION  VARCHAR2(500 CHAR);
    D_EVENT_DATE       DATE;                       /* 원본 DATETIME : 수신 P_EVENT_DATE 가 DATE (H-6/CV-055) */
    N_DELETE_COUNT     INTEGER := 0;
    N_INSERT_COUNT     INTEGER := 0;
    N_INPUT_COUNT      INTEGER := 0;
    N_LOGO_COUNT       INTEGER := 0;
    N_INVALID_ITEM     VARCHAR2(50 CHAR);
    N_MSG              VARCHAR2(1000 CHAR);
    V_BF_REQ_NO        VARCHAR2(30 CHAR);
    V_BF_QTY           NUMBER(10) := 0;            /* 원본 INT */
    V_THIS_QTY         NUMBER(10) := 0;            /* 원본 INT */

    /* ----------------------------------------------------------------------------------------------
     * 메일발송용(원본 본문 중간 DECLARE)
     * @TABLE_BODY/@v_body_contents/@v_head_cont/@v_body_cont : 원본 NVARCHAR(MAX) -> CLOB.
     *   VARCHAR2 로 선언하면 행수가 많을 때 누적 대입에서 ORA-06502 가 난다
     *   (MSSQL NVARCHAR(MAX)는 무제한). 발송도 CLOB 인자를 그대로 받는
     *   PKG_SEND_MAIL.P_SEND_MAIL_CLOB 로 보내 절단 지점을 없앴다(변환 비고 [1]).
     * ---------------------------------------------------------------------------------------------- */
    V_TABLE_BODY       CLOB;
    V_BODY_CONTENTS    CLOB;
    V_HEAD_CONT        CLOB;
    V_BODY_CONT        CLOB;
    /* , @v_to_mail		NVARCHAR(150) */
    V_MAIL_TITLE       VARCHAR2(100 CHAR);
    V_CNT              NUMBER(10);                 /* 원본 @v_cnt int (원본에서도 미사용) */
    V_I                NUMBER(10);                 /* 원본 @v_i int   (원본에서도 미사용) */

    /* ----------------------------------------------------------------------------------------------
     * 커서 FETCH 수신용(원본 본문 중간 DECLARE)
     * ★V_CUR_PROJECT : 원본 @CUR_PROJECT 가 NVARCHAR(8) 인데 원천 PROJECT_CODE 는 VARCHAR2(50 CHAR)
     *   (실측 최대길이 19, dev 26ai DM_PLN_MKT_FCST 120만행) -> MSSQL 은 변수대입 시 조용히 8자로
     *   잘라 메일에 싣지만 Oracle 은 폭초과 대입이 ORA-06502 로 죽는다. 원본 선언폭을 그대로 두고
     *   대입만 SUBSTR(...,1,8) 로 감싸 MSSQL 의 조용한 절단을 그대로 재현한다(SOP 부록D).
     *   ※원본 결함 후보(메일의 Project Code 가 8자로 잘려 표시됨) — 폭 확대는 사용자 확인 후.
     * ---------------------------------------------------------------------------------------------- */
    V_CUR_MODEL        VARCHAR2(100 CHAR);
    V_CUR_SITE         VARCHAR2(100 CHAR);
    V_CUR_PROJECT      VARCHAR2(8 CHAR);
    V_CUR_PJTOWNER     VARCHAR2(150 CHAR);
    V_CUR_OWNER        VARCHAR2(150 CHAR);
    V_CUR_BEFORE_QTY   NUMBER(30,10);              /* 원본 NUMERIC(30,10) : 정밀도까지 이관 */
    V_CUR_AFTER_QTY    NUMBER(30,10);              /* 원본 NUMERIC(30,10) : 정밀도까지 이관 */
    V_CUR_YYYYMMDD     VARCHAR2(10 CHAR);
    V_CUR_DIV          VARCHAR2(100 CHAR);
    V_CUR_ADDR         VARCHAR2(100 CHAR);

    /* ------------------------------------------------------------
    * 본문 동일 수신자 묶음 (2026-10-06) — 한 DIVISION 의 수신자는 **모두 같은 본문**을 받으므로
    * 수신인을 ';' 로 이어 한 통으로 보낸다. 누가 무엇을 보는지는 바뀌지 않는다.
    * 수신인 목록이 상한을 넘으면 묶음을 하나 더 만든다(절단 방지).
    * ★V_CUR_ADDR(100자)에 이어 붙이면 주소 2~3개에서 ORA-06502 라 별도 변수에 담는다.
    * ------------------------------------------------------------ */
    C_TO_MAIL_MAX    CONSTANT PLS_INTEGER := 4000;  /* PKG_SEND_MAIL 바디의 V_TO_MAIL VARCHAR2(4000) 와 정합 */
    TYPE T_ADDR_TAB IS TABLE OF VARCHAR2(4000 CHAR) INDEX BY PLS_INTEGER;
    V_ADDR_SLOT        T_ADDR_TAB;
    V_SLOT_CNT         PLS_INTEGER;

    /* ----------------------------------------------------------------------------------------------
     * EXCEPTION 진단용(원본에 없음). PR_DM_SYS_LOG_BATCH 는 Oracle 에 11인자 표준본으로 배포되어
     * 있어(all_arguments 실측) 에러 경로에서 P_IN_PARA_DATA/P_SQL_ERR_CODE/P_SQL_ERR_MSG/
     * P_SQL_BACKTRACE 4값을 채운다. 정상 경로 호출 인자는 원본과 동일(7인자).
     * ---------------------------------------------------------------------------------------------- */
    V_PROC_INPUT       VARCHAR2(4000 CHAR);
    V_SQL_ERR_CODE     VARCHAR2(100 CHAR);
    V_SQL_ERR_MSG      VARCHAR2(1000 CHAR);
    V_BACKTRACE        VARCHAR2(4000 CHAR);
BEGIN

    /* 원본 MSSQL 세션설정(Oracle 불요, 보존) :
       SET TRANSACTION ISOLATION LEVEL READ COMMITTED;   (Oracle 기본 격리수준과 동일)
       SET NOCOUNT ON;
       SET XACT_ABORT ON;
       SET ANSI_WARNINGS ON;
       ※원본 SELECT 의 WITH(NOLOCK) 힌트도 Oracle 은 읽기일관성으로 대체되어 제거한다. */

    /* 시작 LOG  (START) */
    V_LOG_TYPE := 'START';
    V_LOG_MESSAGE := '########## Start of procedure @@@##########';
    V_LOG_DESCRIPTION := '';
    D_EVENT_DATE := SYSDATE;
    PR_DM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_LOG_DESCRIPTION, D_EVENT_DATE, 'SCM_Batch');
    V_LOG_MESSAGE := NULL;      /* -- <- 변수 재사용을 위하여 초기화해야함 -- */

    /* 원본 :
       --BEGIN TRANSACTION
       BEGIN TRANSACTION
       -> Oracle 은 첫 DML 에서 트랜잭션이 암묵 시작되므로 대응 문장이 없다. 원본이 이름 없는
          BEGIN TRANSACTION / COMMIT TRAN / ROLLBACK TRAN 이고, 본 proc 은 SQL Agent 잡
          (JOB.DMF0070_DIFF_QTY_MAIL_SEND_AUTO step2)에서만 호출되는 최상위 배치라
          (DB 내 호출자 0건 = callgraph 완전고립 실측) SAVEPOINT/ROLLBACK TO 가 아니라
          평범한 COMMIT/ROLLBACK 이 원본 의미와 1:1 이다(CV-051 : SAVEPOINT 는 이름 있는 TRAN 대응). */

    BEGIN   /* BEGIN TRY */

        /* 원본 IF OBJECT_ID('TEMPDB..#TMP_DIFF_QTY_LIST') IS NOT NULL DROP TABLE #TMP_DIFF_QTY_LIST
           -> GTT(GT_DMF70DQ_DIFF_QTY_LIST) : ON COMMIT PRESERVE ROWS 이므로 적재 전 DELETE 로 초기화
              (TRUNCATE 는 DDL = 암시 COMMIT 이라 금지) */
        DELETE
          FROM GT_DMF70DQ_DIFF_QTY_LIST;

        /* 대상 추출 : 원본 SELECT ... INTO #TMP_DIFF_QTY_LIST -> GTT INSERT ... SELECT */
        INSERT
          INTO GT_DMF70DQ_DIFF_QTY_LIST
             ( DIVISION_ID
             , ITEM_ID
             , SCM_SITE_ID
             , PROJECT_CODE
             , PROJECT_OWNER
             , OWNER
             , BEFORE_QTY
             , AFTER_QTY
             , YYYYMMDD )
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , A.SCM_SITE_ID
             , A.PROJECT_CODE
             , (SELECT SA.PROJECT_OWNER                        /* 원본 TOP 1 (ORDER BY 없음) -> ROWNUM = 1 (CV-026) */
                  FROM SCM_MST_PROJECT SA
                 WHERE SA.DIVISION_ID = A.DIVISION_ID
                   AND SA.PROJECT_CODE = A.PROJECT_CODE
                   AND ROWNUM = 1) AS PROJECT_OWNER
             , (SELECT SB.OWNER
                  FROM SCM_MST_SITE_ITEM SB
                 WHERE SB.DIVISION_ID = A.DIVISION_ID
                   AND SB.PROJECT_CODE = A.PROJECT_CODE
                   AND SB.SCM_SITE_ID = A.SCM_SITE_ID
                   AND SB.ITEM_ID = A.ITEM_ID
                   AND ROWNUM = 1) AS OWNER
             , B.PLAN_QTY AS BEFORE_QTY
             , A.QTY AS AFTER_QTY
             , A.YYYYMMDD
          FROM DM_PLN_MKT_FCST A
             , DM_PLN_AUTO_PR_CHECK B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.PROJECT_CODE = A.PROJECT_CODE
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND B.ITEM_ID = A.ITEM_ID
           AND B.DOM_EXP = A.DOM_EXP
           AND B.FCST_TYPE = A.FCST_TYPE
           AND B.INCOTERMS = A.INCOTERMS
           AND B.PLANT_SITE_ID = A.PLANT_SITE_ID
           AND B.MKT_FCST_DATE = A.YYYYMMDD
           AND A.QTY <> B.PLAN_QTY                             /* 수량이 다른것들 (PLAN_QTY NULL 이면 양 DB 모두 제외) */
           AND B.AUTO_FLAG = 'Y'
           AND A.MEASURE = 'MKT_FCST'
           AND RTRIM(A.ATTRIBUTE9) IS NOT NULL                 /* 원본 ISNULL(MF.ATTRIBUTE9,'') <> '' 확정된 것들 (CV-028/H-4) */
           AND A.LAST_UPDATE_DATE >= SYSDATE - 12/24           /* 원본 DATEADD(HOUR, -12, GETDATE()) 12시간 이전에 데이터가 변경된 것들 */
           AND A.YYYYMMDD > TO_CHAR(SYSDATE, 'YYYYMMDD');      /* 원본 CONVERT(VARCHAR(8), GETDATE(), 112) d-DAY가 도래하지 않은 것들 */
        /* 삭제가 된 경우는? */

        /* ----------------------------------------------------------------------------------------------------------------
           메일발송
           ---------------------------------------------------------------------------------------------------------------- */

        /* DIVISION 별로 처리하기 위해 타겟의 DIVISION을 가져온다
           원본 IF OBJECT_ID('TEMPDB..#TMP_DIV_LIST') IS NOT NULL DROP TABLE #TMP_DIV_LIST */
        DELETE
          FROM GT_DMF70DQ_DIV_LIST;

        INSERT
          INTO GT_DMF70DQ_DIV_LIST
             ( DIVISION_ID )
        SELECT DISTINCT DIVISION_ID
          FROM GT_DMF70DQ_DIFF_QTY_LIST;

        /* ----------------------------- */
        V_MAIL_TITLE := '[SCM.DM] PR 확정 후 MKT FCST 데이터 변경';
        V_BODY_CONTENTS := '안녕하십니까, SCM.DM 시스템입니다. PR Request확정 후에 MKT FCST 데이터가 변경된 건을 공유드립니다.
             데이터 수정 사유에 관해서는 마케팅/PM담당자와 확인 부탁드립니다..';

        V_BODY_CONT := '';
        V_HEAD_CONT := '<TR>
			<TH>Model 코드</TH>
			<TH>Sales Site</TH>
			<TH>Project Code</TH>
			<TH>Project Owner</TH>
			<TH>Owner</TH>
			<TH>QTY(수정전)</TH>
			<TH>QTY(수정후)</TH>
			<TH>YYYYMMDD</TH>
			</TR>';

        /* 원본 DECLARE CUR_DIV_LIST CURSOR FAST_FORWARD FOR ... OPEN/FETCH/WHILE @@FETCH_STATUS=0
           -> Oracle 커서 FOR 루프(CV-059). 원본 FETCH 대상 변수에 그대로 대입해 이후 로직·폭을 보존한다. */
        FOR C_DIV IN (SELECT DIVISION_ID
                        FROM GT_DMF70DQ_DIV_LIST) LOOP

            V_CUR_DIV := C_DIV.DIVISION_ID;

            /* DIV에 맞는 목록 가져와 메일 BODY 만들기
               원본은 첫 FETCH 직후·WHILE 진입 전에 @v_body_cont 를 빈문자로 초기화한다(= 루프 직전 초기화와 등가) */
            V_BODY_CONT := '';

            FOR C_QTY IN (SELECT ITEM_ID
                               , SCM_SITE_ID
                               , PROJECT_CODE
                               , PROJECT_OWNER
                               , OWNER
                               , BEFORE_QTY
                               , AFTER_QTY
                               , YYYYMMDD
                            FROM GT_DMF70DQ_DIFF_QTY_LIST
                           WHERE DIVISION_ID = V_CUR_DIV) LOOP

                V_CUR_MODEL := C_QTY.ITEM_ID;
                V_CUR_SITE := C_QTY.SCM_SITE_ID;
                /* ★원본 @CUR_PROJECT NVARCHAR(8) 의 조용한 절단 재현(선언부 주석 참조) */
                V_CUR_PROJECT := SUBSTR(C_QTY.PROJECT_CODE, 1, 8);
                V_CUR_PJTOWNER := C_QTY.PROJECT_OWNER;
                V_CUR_OWNER := C_QTY.OWNER;
                V_CUR_BEFORE_QTY := C_QTY.BEFORE_QTY;
                V_CUR_AFTER_QTY := C_QTY.AFTER_QTY;
                V_CUR_YYYYMMDD := C_QTY.YYYYMMDD;

                /* 원본 문자열 결합 + 를 || 로(CV-025). 원본의 ISNULL(x, 빈문자) 는 Oracle 에서
                   NULL 결합이 곧 무시라 그대로 등가이므로 제거한다(LS-044. NVL(x, 빈문자) 는 CV-029 금지). */
                V_BODY_CONT := V_BODY_CONT || '<TR>';
                V_BODY_CONT := V_BODY_CONT || '<TD>' || V_CUR_MODEL || '</TD>';
                V_BODY_CONT := V_BODY_CONT || '<TD>' || V_CUR_SITE || '</TD>';
                V_BODY_CONT := V_BODY_CONT || '<TD>' || V_CUR_PROJECT || '</TD>';
                V_BODY_CONT := V_BODY_CONT || '<TD>' || V_CUR_PJTOWNER || '</TD>';
                V_BODY_CONT := V_BODY_CONT || '<TD>' || V_CUR_OWNER || '</TD>';
                V_BODY_CONT := V_BODY_CONT || '<TD ALIGN="RIGHT">' || FN_GET_NUMER_TO_STRING(V_CUR_BEFORE_QTY, 0) || '</TD>';
                V_BODY_CONT := V_BODY_CONT || '<TD ALIGN="RIGHT">' || FN_GET_NUMER_TO_STRING(V_CUR_AFTER_QTY, 0) || '</TD>';
                V_BODY_CONT := V_BODY_CONT || '<TD>' || V_CUR_YYYYMMDD || '</TD>';
                V_BODY_CONT := V_BODY_CONT || '</TR>';

            END LOOP;

            V_TABLE_BODY := ' <html>
							<head>
									<title>Untitled Document</title>
									<style>
										* {margin:0;padding:0;}
										body {font-family:Malgun Gothic, Arial, Helvetica, sans-serif;font-size:12px;line-height:1.8;color:#333333;}
										table {border-collapse:collapse;width:100%;}
										table th {background:#f5f5f5;border-bottom:1px solid #e1e1e1;}
										table td {background:#fff;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1;border-bottom:1px solid #e1e1e1;}
										table tbody th {border-left:1px solid #e1e1e1;text-align:right;padding:6px 8px;font-size:12px}
										table tbody td {padding:6px 8px;font-size:12px}
										table thead th {text-align:center;padding:3px;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1; border-bottom:1px solid #d1d1d1;font-size:12px}
										.hori-table table thead td {text-align:center;padding:3px;}
										.hori-table table tbody td {text-align:center;padding:3px;}
										.vertical-table, .hori-table {margin-bottom:20px;}
									</style>
									</head>
									<body>' || '</br>' ||
											'<b>' || REPLACE(V_BODY_CONTENTS, CHR(10), '<br>') || '</b>' ||
											'<div id="divBody" style="width: 100%; overflow-x: auto; overflow-y: auto; font-size: 9pt; line-break: auto;">'    ||
										'<table style=''border-top:2px solid #c8294b; width:1450px;''>
										<thead>' || V_HEAD_CONT || '</thead>
										<tbody>' || V_BODY_CONT || '</tbody>
										</div>
									</body>
							</html>';

            /* SELECT @v_body_cont */
            /*
            EXEC SCM_ADM_MAIL_SEND
                    'kjj0070@lgespartner.com;park.choyi@lgespartner.com'
                , @v_mail_title
                , @TABLE_BODY
                , 'Y'
                */

            /* 메일 전송은 지정된 두명에게 전송 */
            /* ID: harrylee(이형훈 사원) , jjkim1129(김재준 책임) */
            /*IF DB_NAME() <> 'LGCE_SCMDEV'
            BEGIN
                EXEC SCM_ADM_MAIL_SEND
                        'harrylee@lgensol.com'
                    , @v_mail_title
                    , @TABLE_BODY
                    , 'Y'

                EXEC SCM_ADM_MAIL_SEND
                        'jjkim1129@lgensol.com'
                    , @v_mail_title
                    , @TABLE_BODY
                    , 'Y'

            END
            */

            /* 원본 CLOSE CUR_DIFF_QTY_LIST; DEALLOCATE CUR_DIFF_QTY_LIST;
               -> 커서 FOR 루프가 종료 시 자동 CLOSE 하므로 대응 문장 없음 */

            /* DIV에 맞는 룩업 등록 주소로 메일발송 */
            /* 2026-10-06 : 주소마다 한 통씩 보내던 것을 **본문이 같으므로 ';' 로 묶어** 보낸다.
               아래 루프는 발송하지 않고 수신인만 모으고, 발송은 그 뒤 묶음 루프에서 한다. */
            V_ADDR_SLOT.DELETE;
            V_SLOT_CNT := 0;

            FOR C_ADDR IN (SELECT SEGMENT2
                             FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                            WHERE LOOKUP_TYPE = 'AUTO_PR_CHECK_CHANGE_MAIL'
                              AND VALID_YN = 'Y'
                              AND SEGMENT1 = V_CUR_DIV) LOOP

                V_CUR_ADDR := C_ADDR.SEGMENT2;

                IF V_SLOT_CNT = 0
                   OR LENGTHB(V_ADDR_SLOT(V_SLOT_CNT) || ';' || V_CUR_ADDR) > C_TO_MAIL_MAX THEN
                    V_SLOT_CNT := V_SLOT_CNT + 1;
                    V_ADDR_SLOT(V_SLOT_CNT) := V_CUR_ADDR;
                ELSE
                    V_ADDR_SLOT(V_SLOT_CNT) := V_ADDR_SLOT(V_SLOT_CNT) || ';' || V_CUR_ADDR;
                END IF;

            END LOOP;

            FOR I IN 1 .. V_SLOT_CNT LOOP

                V_CUR_ADDR := SUBSTR(V_ADDR_SLOT(I), 1, 100);   /* ERROR 로그 진단용(선언 100자) */

                /* 원본 IF DB_NAME() <> 'LGCE_SCMDEV' (개발DB 발송차단)
                   -> Oracle 에는 그 이름의 DB 가 없어 1:1 이식하면 dev/품질/운영 어디서나 항상 참이
                      되어 개발DB 차단 의도가 사라진다. 사용자 결정(2026-08-03)으로 Oracle 개발·품질
                      DB명 목록 제외로 교체(변환 비고 [3]). 서비스명은 잡 세션에서 SYS$USERS 라 불가. */
                /* 발송 환경 가드 교정(2026-10-06) : 원본 IF DB_NAME() <> 'LGCE_SCMDEV' 는 사내망 MSSQL 이
                   개발·품질 둘 다 DB 이름 LGCE_SCMDEV 라 운영 전용 조건이다. Oracle 엔 그 이름의 DB 가 없어
                   항상 참(=항상 발송)이 되므로 운영 PDB 일치 조건 LIKE 'OCGSCMP%' 로 교체했다. */
                IF SYS_CONTEXT('USERENV', 'DB_NAME') LIKE 'OCGSCMP%' THEN
                    /* 원본 EXEC SCM_ADM_MAIL_SEND @V_CUR_ADDR, @v_mail_title, @TABLE_BODY, 'Y'
                       -> 게이트웨이 SCM_ADM_MAIL_SEND 는 P_BODY_CONTENTS 가 VARCHAR2 라 CLOB 본문을
                          32767 byte 에서 무음 절단시킨다. 사용자 결정(2026-08-03)으로 메일표준
                          PKG_SEND_MAIL.P_SEND_MAIL_CLOB(CLOB 본문) 직접 호출로 전환(변환 비고 [1]).
                          P_SEND_MAIL_CLOB(P_TO_MAIL, P_SUBJECT, P_BODY_CLOB, P_HTML_YN,
                                           P_SENDER 기본 'scmpi@lgensol.com', P_CC_MAIL 기본 NULL)
                          — all_arguments 실측. 앞 4인자 의미는 원본 호출과 1:1.
                       2026-10-06 수신인을 묶음(';' 로 연결)으로 교체 — 본문은 그대로다. */
                    PKG_SEND_MAIL.P_SEND_MAIL_CLOB(V_ADDR_SLOT(I)
                                                 , V_MAIL_TITLE
                                                 , V_TABLE_BODY
                                                 , 'Y');
                END IF;

            END LOOP;
            /* 원본 CLOSE CUR_PR_CHECK; DEALLOCATE CUR_PR_CHECK; */

        END LOOP;
        /* 원본 CLOSE CUR_DIV_LIST; DEALLOCATE CUR_DIV_LIST; */

        /* 원본 IF XACT_STATE() > 0 and @@trancount > 0 BEGIN COMMIT TRAN END
           XACT_STATE()>0(커밋 가능한 활성 트랜잭션) + @@TRANCOUNT>0 은 Oracle 에서 단일 술어
           DBMS_TRANSACTION.LOCAL_TRANSACTION_ID IS NOT NULL 로 수렴한다(CV-067). */
        IF DBMS_TRANSACTION.LOCAL_TRANSACTION_ID IS NOT NULL THEN
            COMMIT;
        END IF;
    /* END TRY */

    /* BEGIN CATCH */
    EXCEPTION
        WHEN OTHERS THEN
            /* 트랜잭션 (END) */
            /* select XACT_STATE() as xact_state_1, @@trancount */
            /* select XACT_STATE() as xact_state_2, @@trancount, 'A21' */
            /* 원본 IF @@trancount > 0 BEGIN ROLLBACK TRAN END */
            IF DBMS_TRANSACTION.LOCAL_TRANSACTION_ID IS NOT NULL THEN
                ROLLBACK;
            END IF;

            V_LOG_TYPE := 'ERROR';
            /* 원본 CAST(ERROR_MESSAGE() AS NVARCHAR(1000)) : 폭 초과 시 핸들러 안 ORA-06502 회피(LS-041) */
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_SQL_ERR_CODE := TO_CHAR(SQLCODE);
            V_SQL_ERR_MSG := SQLERRM;
            V_BACKTRACE := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
            /* 원본 'ERROR_LINE : ' + STR(ERROR_LINE()) : Oracle 은 오류행 대신 백트레이스 */
            V_LOG_DESCRIPTION := SUBSTR('ERROR_LINE : ' || V_BACKTRACE, 1, 500);
            D_EVENT_DATE := SYSDATE;
            /* 원본 무파라미터 proc 이라 진단 JSON 은 실패 시점의 루프 상태를 담는다 */
            V_PROC_INPUT := JSON_OBJECT('V_CUR_DIV' VALUE V_CUR_DIV
                                      , 'V_CUR_ADDR' VALUE V_CUR_ADDR
                                        RETURNING VARCHAR2(4000 CHAR));

            /* 원본 SELECT '[' + Convert(NVARCHAR(10), ERROR_NUMBER()) + ']' + ERROR_MESSAGE() AS ERR_MSG;
               ( -- 에러메시지 DISPLAY -- )
               -> 배치 잡 전용(결과셋 소비자 없음, DB 내 호출자 0건)이라 OUT 커서 대신 DBMS_OUTPUT (H-9(b)) */
            DBMS_OUTPUT.PUT_LINE('[' || V_SQL_ERR_CODE || ']' || V_SQL_ERR_MSG);

            PR_DM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_LOG_DESCRIPTION, D_EVENT_DATE, 'SCM_Batch'
                              , V_PROC_INPUT, V_SQL_ERR_CODE, V_SQL_ERR_MSG, V_BACKTRACE);

            /* 사용자 결정(2026-08-03, 변환 비고 [2]) : 원본 CATCH 는 에러를 흡수했으나 그러면
               DBMS_SCHEDULER 잡이 실패해도 SUCCESS 로 기록된다 -> 로깅 표준대로 재발생시킨다.
               이 RAISE 로 아래 종료 LOG 는 에러 경로에서 실행되지 않는다(정상 경로만 기록). */
            RAISE_APPLICATION_ERROR(-20001, '[' || V_PROGRAM_NAME || '] SQLCODE=' || SQLCODE
                                         || ' / SQLERRM=' || SQLERRM
                                         || ' / BACKTRACE=' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);

    /* END CATCH */
    END;

    /* 종료 LOG (정상 경로 전용. 에러 경로는 위 RAISE_APPLICATION_ERROR 로 도달하지 않는다) */
    V_LOG_TYPE := 'END';
    V_LOG_MESSAGE := '########## END of procedure @@@##########';
    V_LOG_DESCRIPTION := 'input_count: ' || TO_CHAR(N_INPUT_COUNT);
    D_EVENT_DATE := SYSDATE;

    PR_DM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_LOG_DESCRIPTION, D_EVENT_DATE, 'SCM_Batch');

END DMF0070_DIFF_QTY_MAIL_SEND_AUTO;

PROCEDURE DMF0073_SAVE_VERSION_SALESPRICE
(
    P_DIVISION_ID           IN  VARCHAR2,   /* 창 Division (콤마 복수 허용 — 조회 프로시저와 같은 규약) */
    P_VERSION_NO            IN  VARCHAR2,   /* 변경 행 CODE(순수 버전번호) '^' 연결                     */
    P_MONTHLY_ROLLING_FCST  IN  VARCHAR2,   /* 변경 값(Y/N) '^' 연결 — P_VERSION_NO 와 같은 차례        */
    P_USER_ID               IN  VARCHAR2,   /* 저장 사용자                                             */
    P_MENU_ID               IN  VARCHAR2,   /* 부른 화면 (편집 권한 판정 기준)                          */
    O_RESULT_CURSOR         OUT SYS_REFCURSOR
)
/****************************************************************************************************/
/* Program ID  : DMF0073_SAVE_VERSION_SALESPRICE                                                     */
/* Description : Version 창 — MONTHLY_ROLLING_FCST(DM_MST_VERSION.ATTRIBUTE7) 저장                    */
/*               조회 프로시저 DMF0073_GET_VERSION_SALESPRICE 와 짝이며, 그 조회를 공유하는            */
/*               DMF0020 · DMF0074 · DMF0082 가 함께 쓴다. 편집 권한 판정 기준은 P_MENU_ID 다.         */
/*--------------------------------------------------------------------------------------------------*/
/* Date        In Charge    Description                                                              */
/*--------------------------------------------------------------------------------------------------*/
/* 2024/05/13  KJJ          AS-IS DMF0073_SAVE_VERSION_SALESPRICE 신규                                */
/* 2026/09/28  ZIONEX       [PJ202650304] MSSQL -> Oracle 전환.                                       */
/*                          AS-IS 동작(ATTRIBUTE7/LAST_UPDATED_BY/LAST_UPDATE_DATE UPDATE)은 그대로.   */
/*                          서버 검증 4종은 PKG_DMF0035.P_DMF0035_SAVE_VERSION_MRF(2026-09-22 이식)와  */
/*                          같은 규칙이며, 그 판은 화면이 DMF0035 로 고정되어 다른 화면에서 권한 판정이 */
/*                          어긋나므로 화면을 인자로 받도록 했다.                                      */
/*                          AS-IS 는 DIVISION_ID 단일값 비교라 복수 Division 선택 시 0건 갱신.         */
/****************************************************************************************************/
IS
    V_CUR_YYYYWW    VARCHAR2(10 CHAR);
    N_VER_CNT       PLS_INTEGER := 0;
    N_VAL_CNT       PLS_INTEGER := 0;
    N_UPD_CNT       PLS_INTEGER := 0;
    V_INVALID       VARCHAR2(4000 CHAR);

    /* EXCEPTION 블록 변수 */
    V_PROC_INPUT    VARCHAR2(4000 CHAR);
    V_BACKTRACE     VARCHAR2(4000 CHAR);
    V_SQL_CODE      VARCHAR2(100 CHAR);
    V_SQL_ERRMSG    VARCHAR2(1000 CHAR);
    V_LOG_TYPE      VARCHAR2(100 CHAR);
    V_LOG_MESSAGE   VARCHAR2(4000 CHAR);
    V_DESCRIPTION   VARCHAR2(4000 CHAR);
    N_LOG_COUNT     PLS_INTEGER := 0;
    D_EVENT_DATE    DATE := SYSDATE;

BEGIN

    /* 시작 로그 */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## START of procedure ##########';
    V_DESCRIPTION := 'MENU_ID : ' || P_MENU_ID;
    D_EVENT_DATE  := SYSDATE;
    BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH($$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE); END;

    /* 1. 입력 건수 정합 */
    IF TRIM(P_VERSION_NO) IS NULL THEN
        OPEN O_RESULT_CURSOR FOR
            SELECT '-1' AS CODE, '저장할 데이터가 없습니다.' AS MSG, CAST(NULL AS VARCHAR2(4000 CHAR)) AS EVENT FROM DUAL;
        RETURN;
    END IF;

    N_VER_CNT := REGEXP_COUNT(P_VERSION_NO || '^', '\^');
    N_VAL_CNT := REGEXP_COUNT(NVL(P_MONTHLY_ROLLING_FCST, '') || '^', '\^');

    IF N_VER_CNT <> N_VAL_CNT THEN
        OPEN O_RESULT_CURSOR FOR
            SELECT '-1' AS CODE, 'Version / Monthly Rolling Forecast 건수가 일치하지 않습니다.' AS MSG
                 , N_VER_CNT || ' / ' || N_VAL_CNT AS EVENT FROM DUAL;
        RETURN;
    END IF;

    /* 2. 값 검증 — Y/N 만 (AS-IS MSG00002 필수 입력 + 선택 목록 Y/N) */
    SELECT LISTAGG(VER, ', ') WITHIN GROUP (ORDER BY N)
      INTO V_INVALID
      FROM (SELECT LEVEL AS N
                 , TRIM(REGEXP_SUBSTR(P_VERSION_NO || '^', '(.*?)\^', 1, LEVEL, NULL, 1)) AS VER
                 , TRIM(REGEXP_SUBSTR(P_MONTHLY_ROLLING_FCST || '^', '(.*?)\^', 1, LEVEL, NULL, 1)) AS VAL
              FROM DUAL
           CONNECT BY LEVEL <= N_VER_CNT)
     WHERE NVL(VAL, '-') NOT IN ('Y', 'N');

    IF V_INVALID IS NOT NULL THEN
        OPEN O_RESULT_CURSOR FOR
            SELECT '-1' AS CODE, 'Monthly Rolling Forecast 값은 Y 또는 N 이어야 합니다.' AS MSG, V_INVALID AS EVENT FROM DUAL;
        RETURN;
    END IF;

    /* 3. 당주 버전 + 사업부 편집 권한 검증 (조회 프로시저의 EDITABLE / EDIT_YN 과 같은 조건 — 연도 포함) */
    SELECT MAX(ISO_YYYYWW)
      INTO V_CUR_YYYYWW
      FROM SCM_MGR.SCM_SYS_CALENDAR_M
     WHERE BASIS_YYYYMMDD = TO_CHAR(SYSDATE, 'YYYYMMDD');

    SELECT LISTAGG(T.VER, ', ') WITHIN GROUP (ORDER BY T.N)
      INTO V_INVALID
      FROM (SELECT LEVEL AS N
                 , TRIM(REGEXP_SUBSTR(P_VERSION_NO || '^', '(.*?)\^', 1, LEVEL, NULL, 1)) AS VER
              FROM DUAL
           CONNECT BY LEVEL <= N_VER_CNT) T
     WHERE NOT EXISTS (SELECT 1
                         FROM SCM_MGR.DM_MST_VERSION A
                        INNER JOIN SCM_MGR.SCM_SYS_CALENDAR_M B
                           ON B.BASIS_YYYYMMDD = A.YYYYMMDD
                        INNER JOIN TABLE(SCM_MGR.PKG_SCM_USER_MNU.PR_SCM_EDIT_YN(P_USER_ID, P_MENU_ID)) TEI
                           ON TEI.UNIT_ID = A.DIVISION_ID
                          AND TEI.EDIT_YN = 'Y'
                        WHERE A.VERSION_NO  = T.VER
                          AND A.VERSION_TYPE LIKE 'SP\_%' ESCAPE '\'   -- Sales Plan 계열 버전만 (MKT/BIZ 저장 불가 — 사용자 확정 2026-09-22)
                          AND A.DIVISION_ID IN (SELECT TOKEN FROM TABLE(SCM_MGR.FN_STRING_SPLIT(P_DIVISION_ID, ',')))
                          AND B.ISO_YYYYWW  = V_CUR_YYYYWW);

    IF V_INVALID IS NOT NULL THEN
        OPEN O_RESULT_CURSOR FOR
            SELECT '-1' AS CODE, '당주 Sales Plan 버전이면서 편집 권한이 있는 사업부의 버전만 수정할 수 있습니다.' AS MSG, V_INVALID AS EVENT FROM DUAL;
        RETURN;
    END IF;

    /* 4. 저장 — AS-IS UPDATE 1:1 (ATTRIBUTE7 / LAST_UPDATED_BY / LAST_UPDATE_DATE) */
    UPDATE SCM_MGR.DM_MST_VERSION M_VER
       SET M_VER.ATTRIBUTE7       = (SELECT T.VAL
                                       FROM (SELECT TRIM(REGEXP_SUBSTR(P_VERSION_NO || '^', '(.*?)\^', 1, LEVEL, NULL, 1)) AS VER
                                                  , TRIM(REGEXP_SUBSTR(P_MONTHLY_ROLLING_FCST || '^', '(.*?)\^', 1, LEVEL, NULL, 1)) AS VAL
                                               FROM DUAL
                                            CONNECT BY LEVEL <= N_VER_CNT) T
                                      WHERE T.VER = M_VER.VERSION_NO
                                      FETCH FIRST 1 ROWS ONLY)
         , M_VER.LAST_UPDATED_BY  = P_USER_ID
         , M_VER.LAST_UPDATE_DATE = SYSDATE
     WHERE M_VER.DIVISION_ID IN (SELECT TOKEN FROM TABLE(SCM_MGR.FN_STRING_SPLIT(P_DIVISION_ID, ',')))
       AND M_VER.VERSION_TYPE LIKE 'SP\_%' ESCAPE '\'
       AND M_VER.VERSION_NO  IN (SELECT TRIM(REGEXP_SUBSTR(P_VERSION_NO || '^', '(.*?)\^', 1, LEVEL, NULL, 1))
                                   FROM DUAL
                                CONNECT BY LEVEL <= N_VER_CNT)
       AND EXISTS (SELECT 1
                     FROM TABLE(SCM_MGR.PKG_SCM_USER_MNU.PR_SCM_EDIT_YN(P_USER_ID, P_MENU_ID)) TEI
                    WHERE TEI.UNIT_ID = M_VER.DIVISION_ID
                      AND TEI.EDIT_YN = 'Y');

    N_UPD_CNT   := SQL%ROWCOUNT;
    N_LOG_COUNT := N_UPD_CNT;

    COMMIT;

    /* 종료 로그 */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := 'UPDATED=' || N_UPD_CNT;
