FUNCTION FN_ASIS_SORT_KEY
(
    P_TEXT              IN  VARCHAR2
)
RETURN RAW DETERMINISTIC
IS
    /* 구두점 27자 + 기호 4자 = 31자를 순서대로 CHR(1)~CHR(31) 로 옮긴다.
       뒤에 붙인 홑따옴표와 하이픈은 옮길 자리가 없어 빠진다(AS-IS 와 같다). */
    C_FROM      CONSTANT VARCHAR2(40 CHAR) := ' !"#$%&()*,./:;?@[\]^_`{|}~+<=>''-';
    C_TO        CONSTANT VARCHAR2(40 CHAR) :=
                CHR(1)  || CHR(2)  || CHR(3)  || CHR(4)  || CHR(5)  || CHR(6)  || CHR(7)  || CHR(8)
             || CHR(9)  || CHR(10) || CHR(11) || CHR(12) || CHR(13) || CHR(14) || CHR(15) || CHR(16)
             || CHR(17) || CHR(18) || CHR(19) || CHR(20) || CHR(21) || CHR(22) || CHR(23) || CHR(24)
             || CHR(25) || CHR(26) || CHR(27) || CHR(28) || CHR(29) || CHR(30) || CHR(31);
BEGIN
    IF P_TEXT IS NULL THEN
        RETURN NULL;
    END IF;

    RETURN NLSSORT(TRANSLATE(P_TEXT, C_FROM, C_TO), 'NLS_SORT=BINARY_CI');
END FN_ASIS_SORT_KEY;

FUNCTION           "FN_CHARINDEX_REV" 
(
    P_STR1      IN VARCHAR2
  , P_STR2      IN VARCHAR2
  , P_START_LOC IN NUMBER DEFAULT 0
)
RETURN NUMBER
/*
 * Program ID   : FN_CHARINDEX_REV
 * Description  : 특정 문자열에서 해당 문자 또는 문자열이 처음 나오는 위치를 반환(뒤에서부터)
 * Parameter    : 문자열 , 찾는 문자 , 검색 시작 위치(뒤에서부터)
 * Execute      :
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2018.02.19   김재정         Initial Release
 * 2026-07-03   ZIONEX  [PJ202650304]  NextSCM Migration
 *
 */
IS

    V_I        NUMBER;
    V_S1       VARCHAR2(2000 CHAR);

    V_STR1_LEN NUMBER;
    V_STR2_LEN NUMBER;

BEGIN

    IF P_STR1 IS NULL THEN
        RETURN 0;
    END IF;

    IF P_STR2 IS NULL THEN
        RETURN 0;
    END IF;

    V_STR1_LEN := LENGTH(P_STR1);
    V_STR2_LEN := LENGTH(P_STR2);

    V_I := V_STR1_LEN - V_STR2_LEN + 1;

    IF P_START_LOC <> 0 AND V_I > P_START_LOC THEN
        V_I := P_START_LOC;
    END IF;

    WHILE V_I > 0 LOOP
        V_S1 := SUBSTR(P_STR1, V_I, V_STR2_LEN);

        IF V_S1 = P_STR2 THEN
            EXIT;
        END IF;

        V_I := V_I - 1;
    END LOOP;

    RETURN V_I;

END;

FUNCTION           "FN_GET_BIZ_DAY" 
(
    P_CUR_DATE  IN VARCHAR2
  , P_DAY_CNT   IN PLS_INTEGER
)
RETURN VARCHAR2
/****************************************************************************
  * PROJECT       : LG CHEM SCM PRJ.
  * FUNCTION NAME : FN_GET_BIZ_DAY
  * DESCRIPTION   : @P_CUR_DATE 에 영업일로 @P_DAY_CNT 만큼의 일자를 더한 날짜를 리턴함.
  *
  * INPUT         : @P_CUR_DATE : 현재일자 @P_DAY_CNT : 더해줄 일자
  * PROGRAM HISTORY
  *--------------------------------------------------------------
  *  DATE      IN CHARGE           DESCRIPTION
  *--------------------------------------------------------------
  * 2021-03-25   HWI1993		INITIAL
  * 2026.07.06   ZIONEX  [PJ202650304]  NextSCM Migration
  ****************************************************************************/
AS

    V_RTN_YYYYMMDD  VARCHAR2(8 CHAR);
    V_CNT           PLS_INTEGER;    /* @ADD_DAY 에 포함된 영업일 갯수 */
    V_ADD_DAY       PLS_INTEGER;    /* 더해야할 총일자수 */
    V_DT            DATE;
    V_DW            PLS_INTEGER;

BEGIN

    V_CNT     := 0;
    V_ADD_DAY := 0;

    WHILE ( V_CNT < P_DAY_CNT ) LOOP

        V_ADD_DAY := V_ADD_DAY + 1;


        V_DT := TO_DATE(P_CUR_DATE, 'YYYYMMDD') + V_ADD_DAY;
        V_DW := MOD(TRUNC(V_DT) - TRUNC(V_DT, 'IW') + 1, 7) + 1;

        IF (V_DW NOT IN (7, 1)) THEN
            V_CNT := V_CNT + 1;
        END IF;

    END LOOP;

    RETURN TO_CHAR(TO_DATE(P_CUR_DATE, 'YYYYMMDD') + V_ADD_DAY, 'YYYYMMDD');

END;

FUNCTION           "FN_GET_BUCKET_YYYYMMDD_DW" (P_BUCKET_NO IN INTEGER)
      RETURN VARCHAR2
AS
/****************************************************************************
  * PROJECT       : LG CHEM SCP PRJ.
  * FUNCTION NAME : FN_GET_BUCKET_YYYYMMDD_DW
  * DESCRIPTION   : 금주를 버킷번호0로 했을때, 입력버킷번호에 해당하는 시작일자
  *                 단,현재일자의 요일이 월,화이면 이전주 시작일자를 리턴
  *
  * INPUT         : @P_BUCKET_NO : 버킷번호
  * PROGRAM HISTORY
  *--------------------------------------------------------------
  *  DATE      IN CHARGE           DESCRIPTION
  *--------------------------------------------------------------
  * 2018-01-16   YYDOK        INITIAL
  * 2026.07.06   ZIONEX   [PJ202650304] NextSCM Migration
  ****************************************************************************/

  X_BUCKET_YYYYMMDD  VARCHAR2(8 CHAR);
  X_DW               INTEGER;
  N_BUCKET_NO        INTEGER := P_BUCKET_NO;

BEGIN

  X_DW := TO_NUMBER(TO_CHAR(SYSDATE, 'D'));

  /* DAY OF WEEK이 월요일(2),화요일(3)이면 일주일을 뺀다 */
  IF X_DW = 2 OR X_DW = 3 THEN
    N_BUCKET_NO := N_BUCKET_NO - 1;
  END IF;

  X_BUCKET_YYYYMMDD :=
          FN_DATE_TO_CHAR(TO_DATE(FN_GET_START_YYYYMMDD(NULL), 'YYYYMMDD') + (7 * N_BUCKET_NO));

  RETURN X_BUCKET_YYYYMMDD;

END FN_GET_BUCKET_YYYYMMDD_DW;

FUNCTION         FN_GET_CALC_SHIP_FROZEN_DAY_CNT
(
    P_FROZEN_TYPE IN VARCHAR2
)
RETURN NUMBER
IS
    V_SHIP_FROZEN NUMBER := 0;
BEGIN
    IF P_FROZEN_TYPE IS NULL THEN
        RETURN 0;
    END IF;

    IF SUBSTR(P_FROZEN_TYPE, 1, 1) = 'W' THEN
        V_SHIP_FROZEN := (TO_NUMBER(SUBSTR(P_FROZEN_TYPE, -1, 1)) + 1) * 7;
    ELSE
        V_SHIP_FROZEN := TO_NUMBER(SUBSTR(P_FROZEN_TYPE, 2, LENGTH(P_FROZEN_TYPE) - 1));
    END IF;

    RETURN NVL(V_SHIP_FROZEN, 0);
END FN_GET_CALC_SHIP_FROZEN_DAY_CNT;

FUNCTION FN_GET_COUNTRY_CITY_NAME
(
    P_DIVISION_ID IN VARCHAR2
  , P_SCM_SITE_ID IN VARCHAR2
  , P_RET_TYPE    IN VARCHAR2
)
RETURN VARCHAR2
/****************************************************************************
  * PROJECT       : LG CHEM SCP PRJ.
  * FUNCTION NAME : [FN_GET_COUNTRY_CITY_NAME]
  * DESCRIPTION   : SCM_SITE의 COUNTRY, CITY명을 반환
  *
  * INPUT         : @P_DIVISION_ID : DIVISION @P_SCM_SITE_ID : SCM_SITE_ID @P_RET_TYPE    : 'C':국가명,'T' : 도시명
  * OUTPUT        : DIVISION NAME
  * USAGE         : SELECT DBO.[FN_GET_COUNTRY_CITY_NAME]('81','Audi_DE_ING','T')
                    SELECT DBO.[FN_GET_COUNTRY_CITY_NAME]('81','Audi_DE_ING','C')
  * PROGRAM HISTORY
  *--------------------------------------------------------------
  *  DATE      IN CHARGE           DESCRIPTION
  *--------------------------------------------------------------
  * 2018-03-23   PJS        INITIAL
  * 2026.07.06   ZIONEX   [PJ202650304] NextSCM Migration
  ****************************************************************************/
IS

    V_RESULT_COUNTRY VARCHAR2(1000 CHAR);
    V_RESULT_CITY    VARCHAR2(1000 CHAR);
    V_RESULT         VARCHAR2(1000 CHAR);

BEGIN

    V_RESULT_COUNTRY := '';
    V_RESULT_CITY    := '';
    V_RESULT         := '';

    SELECT COUNTRY
         , CITY
      INTO V_RESULT_COUNTRY
         , V_RESULT_CITY
      FROM (
            SELECT COUNTRY
                 , CITY
              FROM SCM_MST_SITE A
             WHERE A.DIVISION_ID = P_DIVISION_ID
               AND A.SCM_SITE_ID = P_SCM_SITE_ID
           )
     WHERE ROWNUM = 1;

    IF (P_RET_TYPE = 'C') THEN
        V_RESULT := V_RESULT_COUNTRY;
    ELSE
        V_RESULT := V_RESULT_CITY;
    END IF;

    RETURN V_RESULT;

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RETURN '';

END;

FUNCTION           "FN_GET_DM_MKT_OWNER_NAME" 

(

    P_OWNER     IN VARCHAR2

  , P_DELIM     IN VARCHAR2

  , P_LANGUAGE  IN VARCHAR2

)

RETURN VARCHAR2

/*

 * Program ID   : FN_GET_SSP_MKT_OWNER_NAME

 * Description  : PROJECT OWNER

 *

 *

 * Program History

 *===================================================================================================

 *   Date       In Charge      Description

 *===================================================================================================

