2.MKT FCST[R+P] Cell
  - ITEM_CLASS_NAME(Model Type)
	  CELL        : MKT FCST 수량
	  Module/Pack : MKT FCST 수량 * (Cell/Module)
	  이외의 Type에 대해서는 값을 0 으로 함. 만들지 않으면 됨.
3.RTF[R+P] Car
  - ITEM_CLASS_NAME(Model Type)
	  CELL        : MKT FCST 수량 / (Cell/Car)
	  Module/Pack : MKT FCST 수량 / ((Cell/Car) / (Cell/Module))
	  이외의 Type에 대해서는 값을 0 으로 함. 만들지 않으면 됨.
4.RTF[R+P] Cell
  - ITEM_CLASS_NAME(Model Type)
	  CELL        : MKT FCST 수량
	  Module/Pack : MKT FCST 수량 * (Cell/Module)
	  이외의 Type에 대해서는 값을 0 으로 함. 만들지 않으면 됨.
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2018.04.17   sj.Hwang         Initial Release
 * 2026.07.06   ZIONEX  [PJ202650304]  NextSCM Migration
 */
AS

    V_X_SALES_QTY      NUMBER(30,10) := 0;
    V_ITEM_CLASS_NAME  VARCHAR2(200 CHAR);
    V_QTY              NUMBER(30,10);
    V_CELL_PER_CAR     NUMBER(30,10);
    V_CELL_PER_MODULE  NUMBER(30,10);

BEGIN

    V_ITEM_CLASS_NAME := P_ITEM_CLASS_NAME;
    V_QTY             := NVL(P_QTY, 0);
    V_CELL_PER_CAR    := NVL(P_CELL_PER_CAR, 0);
    V_CELL_PER_MODULE := NVL(P_CELL_PER_MODULE, 0);
    V_X_SALES_QTY     := V_QTY;

/* RETURN @x_sales_qty; */
/* ,CASE WHEN isnull(ITEM.ITEM_CLASS_NAME,'') = '[AC]Cell' THEN ISNULL( A.QTY / isnull(SITE_ITEM.CELL_PER_CAR,1), 0) */
/* 	  WHEN isnull(ITEM.ITEM_CLASS_NAME,'') = '[AM]Module' OR isnull(ITEM.ITEM_CLASS_NAME,'') = '[AP]Pack' THEN ISNULL( ISNULL(A.QTY,1) / isnull(SITE_ITEM.CELL_PER_CAR,1) / isnull(SITE_ITEM.CELL_PER_MODULE,1), 0) */
/* 	  ELSE 0 END */
/* 	  AS QTY */

/* ,CASE WHEN isnull(ITEM.ITEM_CLASS_NAME,'') = '[AC]Cell' THEN A.QTY */
/* 	  WHEN isnull(ITEM.ITEM_CLASS_NAME,'') = '[AM]Module' OR isnull(ITEM.ITEM_CLASS_NAME,'') = '[AP]Pack' THEN A.QTY / isnull(SITE_ITEM.CELL_PER_MODULE,1) */
/* 	  ELSE 0 END */
/* 	  AS QTY */

    IF INSTR(P_MEASURE, 'MKT_FCST_RP_CAR') > 0 OR INSTR(P_MEASURE, 'RTF_RP_CAR') > 0 THEN
        IF INSTR(V_ITEM_CLASS_NAME, 'Cell') > 0 THEN /* @p_item_class_name = '[AC]Cell' */
            IF V_CELL_PER_CAR = 0 THEN
                V_X_SALES_QTY := 0;
            ELSE
                V_X_SALES_QTY := V_QTY / V_CELL_PER_CAR;
            END IF;
        ELSIF INSTR(V_ITEM_CLASS_NAME, 'Module') > 0 OR INSTR(V_ITEM_CLASS_NAME, 'Pack') > 0 THEN /* @p_item_class_name = '[AM]Module' OR @p_item_class_name = '[AP]Pack' */
            IF V_CELL_PER_CAR = 0 OR V_CELL_PER_MODULE = 0 THEN
                V_X_SALES_QTY := 0;
            ELSE
                V_X_SALES_QTY := V_QTY / ( V_CELL_PER_CAR / V_CELL_PER_MODULE );
            END IF;
        ELSE
            V_X_SALES_QTY := 0;
        END IF;
    ELSIF INSTR(P_MEASURE, 'MKT_FCST_RP_CELL') > 0 OR INSTR(P_MEASURE, 'RTF_RP_CELL') > 0 THEN
        IF INSTR(V_ITEM_CLASS_NAME, 'Cell') > 0 THEN /* @p_item_class_name = '[AC]Cell' */
            IF V_CELL_PER_CAR = 0 THEN
                V_X_SALES_QTY := 0;
            ELSE
                V_X_SALES_QTY := V_QTY;
            END IF;
        ELSIF INSTR(V_ITEM_CLASS_NAME, 'Module') > 0 OR INSTR(V_ITEM_CLASS_NAME, 'Pack') > 0 THEN
            IF V_CELL_PER_MODULE = 0 THEN
                V_X_SALES_QTY := 0;
            ELSE
                V_X_SALES_QTY := V_QTY * V_CELL_PER_MODULE;
            END IF;
        ELSE
            V_X_SALES_QTY := 0;
        END IF;
    END IF;

    RETURN V_X_SALES_QTY;

END;

