 * 2022.11.16	kdw2819		[C20221107-000343]BP Waterfall 오류 수정 요청의 건
 * 2026.07.06   ZIONEX  [PJ202650304]  NextSCM Migration
 */
AS

    V_X_SALES_QTY      NUMBER := 0;
    V_ITEM_CLASS_NAME  VARCHAR2(200 CHAR);
    V_QTY              NUMBER;
    V_CELL_PER_CAR     NUMBER;
    V_CELL_PER_MODULE  NUMBER;

BEGIN

    V_ITEM_CLASS_NAME := P_ITEM_CLASS_NAME;
    V_QTY             := NVL(P_QTY, 0);
    V_CELL_PER_CAR    := NVL(P_CELL_PER_CAR, 0);
    V_CELL_PER_MODULE := NVL(P_CELL_PER_MODULE, 0);
    V_X_SALES_QTY     := V_QTY;

/* RETURN @x_sales_qty; */
/* ,CASE WHEN isnull(ITEM.ITEM_CLASS_NAME,'') = '[AC]Cell' THEN ISNULL( A.QTY / isnull(SITE_ITEM.CELL_PER_CAR,1), 0) */
/* 	  WHEN isnull(ITEM.ITEM_CLASS_NAME,'') = '[AM]Module' OR isnull(ITEM.ITEM_CLASS_NAME,'') = '[AP]Pack' THEN ISNULL( ISNULL(A.QTY,1) / isnull(SITE_ITEM.CELL_PER_CAR,1) / isnull(SITE_ITEM.CELL_PER_MODULE,1), 0) */
/* 	  ELSE 0 END */
/* 	  AS QTY */

/* ,CASE WHEN isnull(ITEM.ITEM_CLASS_NAME,'') = '[AC]Cell' THEN A.QTY */
/* 	  WHEN isnull(ITEM.ITEM_CLASS_NAME,'') = '[AM]Module' OR isnull(ITEM.ITEM_CLASS_NAME,'') = '[AP]Pack' THEN A.QTY / isnull(SITE_ITEM.CELL_PER_MODULE,1) */
/* 	  ELSE 0 END */
/* 	  AS QTY */

    IF INSTR(P_MEASURE, 'MKT_FCST_RP_CAR') > 0 OR INSTR(P_MEASURE, 'RTF_RP_CAR') > 0 OR INSTR(P_MEASURE, 'RTF_SYS_RP_CAR') > 0 THEN
        IF INSTR(V_ITEM_CLASS_NAME, 'Cell') > 0 THEN /* @p_item_class_name = '[AC]Cell' */
            IF V_CELL_PER_CAR = 0 THEN
                V_X_SALES_QTY := 0;
            ELSE
                V_X_SALES_QTY := V_QTY / V_CELL_PER_CAR;
            END IF;
        ELSIF INSTR(V_ITEM_CLASS_NAME, 'Module') > 0 OR INSTR(V_ITEM_CLASS_NAME, 'Pack') > 0 THEN /* @p_item_class_name = '[AM]Module' OR @p_item_class_name = '[AP]Pack' */
            IF V_CELL_PER_CAR = 0 OR V_CELL_PER_MODULE = 0 THEN
                V_X_SALES_QTY := 0;
            ELSE
                V_X_SALES_QTY := V_QTY / ( V_CELL_PER_CAR / V_CELL_PER_MODULE );
            END IF;
        ELSE
            V_X_SALES_QTY := 0;
        END IF;
    ELSIF INSTR(P_MEASURE, 'MKT_FCST_RP_CELL') > 0 OR INSTR(P_MEASURE, 'RTF_RP_CELL') > 0 OR INSTR(P_MEASURE, 'RTF_SYS_RP_CELL') > 0 THEN
        IF INSTR(V_ITEM_CLASS_NAME, 'Cell') > 0 THEN /* @p_item_class_name = '[AC]Cell' */
            IF V_CELL_PER_CAR = 0 THEN
                V_X_SALES_QTY := 0;
            ELSE
                V_X_SALES_QTY := V_QTY;
            END IF;
        ELSIF INSTR(V_ITEM_CLASS_NAME, 'Module') > 0 OR INSTR(V_ITEM_CLASS_NAME, 'Pack') > 0 THEN
            IF V_CELL_PER_MODULE = 0 THEN
                V_X_SALES_QTY := 0;
            ELSE
                V_X_SALES_QTY := V_QTY * V_CELL_PER_MODULE;
            END IF;
        ELSE
            V_X_SALES_QTY := 0;
        END IF;
    END IF;

/* 20181114 추가 */
    IF ((P_MEASURE IN ('MKT_FCST', 'MKT_FCST_RP', 'MKT_FCST_RP_CAR', 'MKT_FCST_RP_CELL'
                      , 'RTF', 'RTF_RP_CAR', 'RTF_RP_CELL'
                        , 'CUST_FCST'
                        , 'RTF_SCP'
                        , 'RTF_SYS_RP', 'RTF_SYS_RP_CAR', 'RTF_SYS_RP_CELL'      /* 20191115 KHSONG MEASURE 2개 추가 */
                        , 'Business_Plan'))                                       /* [C20221107-000343]BP Waterfall 오류 수정 요청의 건 */
        AND (P_CELL_YN = 'Y')) THEN
        V_X_SALES_QTY := V_X_SALES_QTY * P_CELL_PACK_COUNT;
    END IF;
/* 20181114 추가 */

/* [C20210304-000196] 소형 부자재 및 전극 매출 수량 표기(biz_type is null 제외) */
/* 20190507 KHSONG [CSR ID:3985608] Biz Type이 없는건은 수량만 zero로 변환요청 (START) */
/*
if			@p_division_id = '40'
		and @p_forecast_info_biz_type is null
		and @p_measure NOT IN ('SalesAmt_KRW','SalesAmt_LOC','SalesAmt_USD')
	BEGIN
		SET @x_sales_qty = 0
	END */
/* 20190507 KHSONG [CSR ID:3985608] Biz Type이 없는건은 수량만 zero로 변환요청 (END) */

    RETURN V_X_SALES_QTY;

END;

FUNCTION "FN_GET_ELEC_CELL_PER_METER"
(
    P_DIVISION_ID  IN VARCHAR2
  , P_PLANT_ID     IN VARCHAR2
  , P_ITEM_ID      IN VARCHAR2
)
RETURN NUMBER
AS
    /* 전극ITEM의 CELL/M 환산값 리턴. MSSQL -> Oracle (1:1). */
    X_VALUE NUMBER := 0;
BEGIN
    IF SUBSTR(P_ITEM_ID, 1, 5) NOT IN ('APCAN', 'APCCA', 'APCCS') THEN
        RETURN NULL;
    END IF;

    /* 셀 하위 전극BOM 소요량 = 1셀당 전극M => CELL/M = 1.0 / 전극소요량 */
    BEGIN
        SELECT 1.0 / A.ACCUMULATED_CHILD_QTY
          INTO X_VALUE
          FROM SCM_MST_MODEL_FINAL_ITEM_BOM_V A
             , SCM_MST_ITEM_SN I
         WHERE I.DIVISION_ID = P_DIVISION_ID
           AND I.ITEM_ID = P_ITEM_ID
           AND A.MODEL_ID = NVL(I.APPLIED_MODEL, A.MODEL_ID)
           AND A.DIVISION_ID = I.DIVISION_ID
           AND A.CHILD_ITEM_ID = I.ITEM_ID
           AND A.MODEL_ID LIKE '_C%'
           AND A.OPERATION_GROUP_ID = 'E'
           AND ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            X_VALUE := NULL;
    END;

    RETURN NVL(X_VALUE, 0);
END;

FUNCTION FN_GET_IN_STR
(
 P_CSV_TEXT_LIST         IN CLOB
)
RETURN CLOB
/*
 * Program ID   : FN_GET_IN_STR
 * Description  :
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2018/05/20  ygkim       Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 * 2026.07.06   ZIONEX   [PJ202650304] NextSCM Migration
*/
AS
    V_CSV_TEXT_LIST    CLOB; /* := REPLACE(REPLACE(P_CSV_TEXT_LIST,CHR(13),''),CHR(10),','); */
    V_CONDTION_VALUE   VARCHAR2(100 CHAR);
    V_SQL_TEXT         CLOB;
    V_COUNT            PLS_INTEGER := 0 ;
    V_LIST_COUNT       PLS_INTEGER := 0 ;
    V_1ST_NODE         VARCHAR2(4000 CHAR);
    V_2ND_NODE         VARCHAR2(4000 CHAR);
BEGIN
    V_CSV_TEXT_LIST := REPLACE(REPLACE(P_CSV_TEXT_LIST, CHR(13), ''), CHR(10), ',');
    V_SQL_TEXT := '';
    V_LIST_COUNT := 0;
    /* ---------------------------------------------------------------------- */

    /* ---------------------------------------------------------------------- */

    /* ---------------------------------------------------------------------- */
    IF NVL(DBMS_LOB.SUBSTR(V_CSV_TEXT_LIST, 3, 1), 'ALL') = 'ALL' THEN
        V_SQL_TEXT := '';
    /* ---------------------------------------------------------------------- */
    ELSIF DBMS_LOB.GETLENGTH(V_CSV_TEXT_LIST) = 0 THEN
        V_SQL_TEXT := '';
    END IF;

    BEGIN
        IF NVL(DBMS_LOB.GETLENGTH(P_CSV_TEXT_LIST), 0) = 0 THEN
            RETURN '';
        END IF;

        V_SQL_TEXT := '';
        V_LIST_COUNT := 1;
        /* SET @I = 0; */
        WHILE (V_LIST_COUNT <= 1000) LOOP
            /* [dbo].[SCM_ARR_SPL_CNT] */
            V_CONDTION_VALUE := TRIM(FN_SCM_SPLIT(V_CSV_TEXT_LIST, V_LIST_COUNT, ','));

            IF V_CONDTION_VALUE IS NULL THEN
                EXIT;
            ELSE
                V_COUNT := V_COUNT + 1 ;
                IF (V_COUNT > 1) THEN
                    V_SQL_TEXT := V_SQL_TEXT || ',''' || V_CONDTION_VALUE || '''' ;
                ELSE
                    V_SQL_TEXT := V_SQL_TEXT || '''' || V_CONDTION_VALUE || '''' ;
                END IF;

                V_LIST_COUNT := V_LIST_COUNT + 1;
            END IF;
        END LOOP;
    END;

    /* ---------------------------------------------------------------------- */
    RETURN V_SQL_TEXT;
    /* ---------------------------------------------------------------------- */

END;

FUNCTION           "FN_GET_ITEM_PROD_OP" 
      (
       P_DIVISION_ID      VARCHAR2
     , P_OPERATION_GROUP  VARCHAR2
     , P_ITEM_ID          VARCHAR2
       )
       RETURN VARCHAR2
AS
/****************************************************************************
  * FUNCTION NAME : FN_GET_ITEM_PROD_OP
  * DESCRIPTION   : ITEM_ID_ASSY 로 ITEM_PROD 찾기
  * INPUT         : P_DIVISION_ID,P_ITEM_ID
  * OUTPUT        : ITEM_PROD
  * PROGRAM HISTORY
  *--------------------------------------------------------------
    DATE      IN CHARGE           DESCRIPTION
  *--------------------------------------------------------------
  * 2023-08-02   vadabi3        INITIAL
  * 2026.07.06   ZIONEX   [PJ202650304] NextSCM Migration
  ****************************************************************************/

   V_X_ITEM_ID_PROD VARCHAR2(150 CHAR);

BEGIN

   /* CELL, PaCK, 전극 중 CELL일 경우만 체크 */
   IF (P_OPERATION_GROUP != 'A') THEN
      RETURN P_ITEM_ID;
   END IF;

   /* VALID_YN 이 조건에 없어 Multi row 리턴 될 수 있어 Top 1 Return */
   /* 20230804 값이 Null 인 경우 입력 받은 값 리턴 */
   BEGIN
      SELECT ITEM_ID_PROD
        INTO V_X_ITEM_ID_PROD
        FROM (SELECT NVL(ITEM_ID_PROD, P_ITEM_ID) AS ITEM_ID_PROD
                FROM SCP_MST_CELL_PROD_ASSY_MAP
               WHERE 1 = 1
                 AND DIVISION_ID  = P_DIVISION_ID
                 AND ITEM_ID_ASSY = P_ITEM_ID
               ORDER BY NVL(ITEM_ID_PROD, P_ITEM_ID) DESC)
       WHERE ROWNUM = 1;
   EXCEPTION
      WHEN NO_DATA_FOUND THEN
         V_X_ITEM_ID_PROD := NULL;
   END;

   IF (V_X_ITEM_ID_PROD IS NULL) THEN
      V_X_ITEM_ID_PROD := P_ITEM_ID;
   END IF;

   RETURN V_X_ITEM_ID_PROD;

END;

FUNCTION           "FN_GET_MULTI_OWNER_NAME" 
(
    P_OWNER  IN VARCHAR2
  , P_DELIM  IN VARCHAR2
  , P_FLAG   IN VARCHAR2
)
RETURN VARCHAR2
/****************************************************************************
  * PROJECT       : LG CHEM SCP PRJ.
  * FUNCTION NAME : FN_GET_MULTI_OWNER_NAME
  * DESCRIPTION   : 여러 Owner(User_ID
  *
  * INPUT         : NVARCHAR
  * OUTPUT        : NVARCHAR
  * USAGE         : SELECT dbo.FN_GET_MULTI_OWNER_NAME('kimsuhyeon,youngsangkim', ',', '1')
  * PROGRAM HISTORY
  *--------------------------------------------------------------
  *  DATE      IN CHARGE           DESCRIPTION
  *--------------------------------------------------------------
  * 2018-08-03   JYE                  INITIAL
  * 2026-07-03   ZIONEX  [PJ202650304]  NextSCM Migration
  ****************************************************************************/
AS

    V_IDX        PLS_INTEGER;
    V_FOUND_IDX  PLS_INTEGER;
    V_RE_STR     VARCHAR2(32767 CHAR);
    V_USER_NAME  VARCHAR2(32767 CHAR);
    V_OWNER      VARCHAR2(32767 CHAR) := P_OWNER;

BEGIN

    V_IDX       := 1;
    V_FOUND_IDX := INSTR(V_OWNER, P_DELIM);
    V_RE_STR    := '';

    IF (V_FOUND_IDX <> 0) THEN

        WHILE (V_FOUND_IDX > 0) LOOP

            IF (P_FLAG = '1') THEN
                BEGIN
                    SELECT USER_NAME_EN
                      INTO V_USER_NAME
                      FROM SCM_MST_SSO_USER_INFO
                     WHERE UPPER(USER_ID) = UPPER(TRIM(SUBSTR(V_OWNER, 1, V_FOUND_IDX - 1)));
                EXCEPTION
                    WHEN NO_DATA_FOUND THEN NULL;
                END;
            ELSE
                BEGIN
                    SELECT USER_NAME
                      INTO V_USER_NAME
                      FROM SCM_MST_SSO_USER_INFO
                     WHERE UPPER(USER_ID) = UPPER(TRIM(SUBSTR(V_OWNER, 1, V_FOUND_IDX - 1)));
                EXCEPTION
                    WHEN NO_DATA_FOUND THEN NULL;
                END;
            END IF;

            V_RE_STR := TRIM(V_RE_STR) || V_USER_NAME || ',';

            V_OWNER     := SUBSTR(V_OWNER, V_FOUND_IDX + 1, LENGTH(V_OWNER) - V_FOUND_IDX);
            V_IDX       := V_IDX + 1;
            V_FOUND_IDX := INSTR(V_OWNER, P_DELIM);

        END LOOP;

        IF (P_FLAG = '1') THEN
            BEGIN
                SELECT V_RE_STR || USER_NAME_EN
                  INTO V_RE_STR
                  FROM SCM_MST_SSO_USER_INFO
                 WHERE UPPER(USER_ID) = UPPER(TRIM(V_OWNER));
            EXCEPTION
                WHEN NO_DATA_FOUND THEN NULL;
            END;
        ELSE
            BEGIN
                SELECT V_RE_STR || USER_NAME
                  INTO V_RE_STR
                  FROM SCM_MST_SSO_USER_INFO
                 WHERE UPPER(USER_ID) = UPPER(TRIM(V_OWNER));
            EXCEPTION
                WHEN NO_DATA_FOUND THEN NULL;
            END;
        END IF;

    ELSE

        IF (P_FLAG = '1') THEN
            BEGIN
                SELECT USER_NAME_EN
                  INTO V_RE_STR
                  FROM SCM_MST_SSO_USER_INFO
                 WHERE UPPER(USER_ID) = UPPER(TRIM(V_OWNER));
            EXCEPTION
                WHEN NO_DATA_FOUND THEN NULL;
            END;
        ELSE
            BEGIN
                SELECT USER_NAME
                  INTO V_RE_STR
                  FROM SCM_MST_SSO_USER_INFO
                 WHERE UPPER(USER_ID) = UPPER(TRIM(V_OWNER));
            EXCEPTION
                WHEN NO_DATA_FOUND THEN NULL;
            END;
        END IF;

    END IF;

    RETURN V_RE_STR;

END;

FUNCTION           "FN_GET_NERP_IN_VALUES" (
    P_INPUTVALUES IN VARCHAR2
)
RETURN VARCHAR2
AS
    /* NERP) 컨버전시 콤마로 되어 있는 값을 Dynamic SQL 의 IN 절에 사용하기 위함 */
    V_FORMATTEDSTRING VARCHAR2(32767);
BEGIN
    SELECT  LISTAGG('''' || REPLACE(TRIM(TOKEN), '''', '''''') || '''', ',') WITHIN GROUP (ORDER BY N)
      INTO  V_FORMATTEDSTRING
      FROM  ( SELECT  LEVEL                                                       AS N
                     ,REGEXP_SUBSTR(P_INPUTVALUES, '(.*?)(,|$)', 1, LEVEL, NULL, 1) AS TOKEN
                FROM  DUAL
             CONNECT BY LEVEL <= REGEXP_COUNT(P_INPUTVALUES, ',') + 1 );

    RETURN NVL(V_FORMATTEDSTRING, '');
END;

FUNCTION           "FN_GET_NORMAL_STRING" 
(
