(
      P_PLAN_START_YYYYMMDD  IN VARCHAR2
    , P_FROM_YYYYMMDD        IN VARCHAR2
    , P_TO_YYYYMMDD          IN VARCHAR2
)
RETURN T_FN_GET_REPORT_TERM_INFO_TAB PIPELINED
/*
 * Program ID   : FN_GET_REPORT_TERM_INFO
 * Description  : 계획일자, 기간시작일자, 기간종료일자에 해당하는 계획, 실적 기간정보 생성
 * Program History
 *================================================================================================================================================
 *   Date       In Charge                           Description
 *================================================================================================================================================
 * 2023/01/24   chaan         V1.1.1                PJ20230692  SCM 역량 강화 위한 SCP 개선과제 이행 Phase2     - Initial Release
 *================================================================================================================================================
 * 2026.07.06   ZIONEX  [PJ202650304]  NextSCM Migration
 */
AS

    V_PLAN_FROM_YYYYMMDD    VARCHAR2(8 CHAR) := '';
    V_PLAN_TO_YYYYMMDD      VARCHAR2(8 CHAR) := '';
    V_PLAN_FROM_YYYYMM      VARCHAR2(8 CHAR) := '';
    V_PLAN_TO_YYYYMM        VARCHAR2(8 CHAR) := '';
    V_RESULT_FROM_YYYYMMDD  VARCHAR2(8 CHAR) := '';
    V_RESULT_TO_YYYYMMDD    VARCHAR2(8 CHAR) := '';
    V_PLAN_FROM_PARTIAL_WW  VARCHAR2(8 CHAR) := '';
    V_PLAN_TO_PARTIAL_WW    VARCHAR2(8 CHAR) := '';
    V_PLAN_FROM_ISO_WW      VARCHAR2(8 CHAR) := '';
    V_PLAN_TO_ISO_WW        VARCHAR2(8 CHAR) := '';

BEGIN

    BEGIN
        SELECT C.BASIS_START_DATE
          INTO V_PLAN_FROM_YYYYMMDD
          FROM SCM_SYS_CALENDAR_M C
         WHERE 1 = 1
           AND C.BASIS_YYYYMMDD = P_PLAN_START_YYYYMMDD;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN V_PLAN_FROM_YYYYMMDD := NULL;
    END;

    BEGIN
        SELECT C.BASIS_START_DATE
          INTO V_RESULT_FROM_YYYYMMDD
          FROM SCM_SYS_CALENDAR_M C
         WHERE 1 = 1
           AND C.BASIS_YYYYMMDD = P_FROM_YYYYMMDD;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN V_RESULT_FROM_YYYYMMDD := NULL;
    END;

    BEGIN
        SELECT C.BASIS_START_DATE
          INTO V_RESULT_TO_YYYYMMDD
          FROM SCM_SYS_CALENDAR_M C
         WHERE 1 = 1
           AND C.BASIS_YYYYMMDD = P_TO_YYYYMMDD;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN V_RESULT_TO_YYYYMMDD := NULL;
    END;

    IF V_PLAN_FROM_YYYYMMDD > V_RESULT_FROM_YYYYMMDD THEN
        /* 실적 보여줌 */
        V_PLAN_TO_YYYYMMDD   := P_TO_YYYYMMDD;
        V_RESULT_TO_YYYYMMDD := V_PLAN_FROM_YYYYMMDD;
    ELSIF V_PLAN_FROM_YYYYMMDD <= V_RESULT_FROM_YYYYMMDD THEN
        /* 실적 없음 */
        V_PLAN_TO_YYYYMMDD     := P_TO_YYYYMMDD;
        V_RESULT_FROM_YYYYMMDD := TO_CHAR(ADD_MONTHS(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD'), 6), 'YYYYMMDD');
        V_RESULT_TO_YYYYMMDD   := TO_CHAR(ADD_MONTHS(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD'), -6), 'YYYYMMDD');
    ELSIF V_PLAN_FROM_YYYYMMDD > V_RESULT_TO_YYYYMMDD THEN
        V_PLAN_FROM_YYYYMMDD   := TO_CHAR(ADD_MONTHS(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD'), -6), 'YYYYMMDD');
        V_PLAN_TO_YYYYMMDD     := TO_CHAR(ADD_MONTHS(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD'), -6), 'YYYYMMDD');
        V_RESULT_FROM_YYYYMMDD := P_FROM_YYYYMMDD;
        V_RESULT_TO_YYYYMMDD   := P_TO_YYYYMMDD;
    ELSIF V_PLAN_FROM_YYYYMMDD = V_RESULT_TO_YYYYMMDD THEN
        V_PLAN_TO_YYYYMMDD     := V_PLAN_FROM_YYYYMMDD;
        V_RESULT_FROM_YYYYMMDD := P_FROM_YYYYMMDD;
        V_RESULT_TO_YYYYMMDD   := P_TO_YYYYMMDD;
    END IF;

    V_PLAN_FROM_YYYYMM := SUBSTR(P_FROM_YYYYMMDD, 1, 6);
    V_PLAN_TO_YYYYMM   := SUBSTR(P_TO_YYYYMMDD, 1, 6);

    SELECT MIN(WW), MAX(WW)
      INTO V_PLAN_FROM_PARTIAL_WW, V_PLAN_TO_PARTIAL_WW
      FROM (
            SELECT SUBSTR(ISO_YYYYWW, 1, 4) || SUBSTR(PARTIAL_WEEK_NAME, 2, 3) AS WW
              FROM SCM_SYS_CALENDAR_M A
             WHERE 1 = 1
               AND A.BASIS_YYYYMMDD >= P_FROM_YYYYMMDD
               AND A.BASIS_YYYYMMDD <= P_TO_YYYYMMDD
             GROUP BY SUBSTR(ISO_YYYYWW, 1, 4) || SUBSTR(PARTIAL_WEEK_NAME, 2, 3)
           ) A;

    SELECT MIN(ISO_YYYYWW), MAX(ISO_YYYYWW)
      INTO V_PLAN_FROM_ISO_WW, V_PLAN_TO_ISO_WW
      FROM (
            SELECT ISO_YYYYWW
              FROM SCM_SYS_CALENDAR_M A
             WHERE 1 = 1
               AND A.BASIS_YYYYMMDD >= P_FROM_YYYYMMDD
               AND A.BASIS_YYYYMMDD <= P_TO_YYYYMMDD
             GROUP BY ISO_YYYYWW
           ) A;

    PIPE ROW (T_FN_GET_REPORT_TERM_INFO_ROW(
          V_PLAN_FROM_YYYYMMDD
        , V_PLAN_TO_YYYYMMDD
        , V_PLAN_FROM_YYYYMM
        , V_PLAN_TO_YYYYMM
        , V_RESULT_FROM_YYYYMMDD
        , V_RESULT_TO_YYYYMMDD
        , V_PLAN_FROM_PARTIAL_WW
        , V_PLAN_TO_PARTIAL_WW
        , V_PLAN_FROM_ISO_WW
        , V_PLAN_TO_ISO_WW));

    RETURN;

END;

FUNCTION FN_GET_SCP_CONFIDENCE
(
    P_ALPHA          IN BINARY_DOUBLE,   /* Confidence level (e.g., 0.2 for 20% confidence) */
    P_STANDARD_DEV   IN BINARY_DOUBLE,   /* Standard deviation of your data */
    P_SIZE           IN NUMBER           /* Sample size */
)
RETURN BINARY_DOUBLE
/* ============================================================
 * Program ID   : FN_GET_SCP_CONFIDENCE
 * Description  : Confidence interval calculation (two-tailed) using Z-score
 * Program History
 *------------------------------------------------------------
 * Date          In Charge      Description
 *------------------------------------------------------------
 * 2026.07.06    ZIONEX         [PJ202650304] NextSCM Migration
 * ============================================================ */
AS
    V_Z       BINARY_DOUBLE;
    V_RESULT  BINARY_DOUBLE;
BEGIN
    /* Calculate the Z-score for the given alpha and a two-tailed test using your NORMSINV function */
    V_Z := ABS(FN_GET_SCP_NORMSINV(1 - P_ALPHA / 2));

    /* Calculate the confidence interval */
    V_RESULT := V_Z * (P_STANDARD_DEV / SQRT(P_SIZE));

    RETURN V_RESULT;
END;

