FUNCTION FN_GET_SCP_NORMSINV
(
    P_P  IN  BINARY_DOUBLE
)
RETURN BINARY_DOUBLE

AS
    V_A1 BINARY_DOUBLE := -3.969683028665376E+01;
    V_A2 BINARY_DOUBLE :=  2.209460984245205E+02;
    V_A3 BINARY_DOUBLE := -2.759285104469687E+02;
    V_A4 BINARY_DOUBLE :=  1.383577518672690E+02;
    V_A5 BINARY_DOUBLE := -3.066479806614716E+01;
    V_A6 BINARY_DOUBLE :=  2.506628277459239E+00;

    V_B1 BINARY_DOUBLE := -5.447609879822406E+01;
    V_B2 BINARY_DOUBLE :=  1.615858368580409E+02;
    V_B3 BINARY_DOUBLE := -1.556989798598866E+02;
    V_B4 BINARY_DOUBLE :=  6.680131188771972E+01;
    V_B5 BINARY_DOUBLE := -1.328068155288572E+01;

    V_C1 BINARY_DOUBLE := -7.784894002430293E-03;
    V_C2 BINARY_DOUBLE := -3.223964580411365E-01;
    V_C3 BINARY_DOUBLE := -2.400758277161838E+00;
    V_C4 BINARY_DOUBLE := -2.549732539343734E+00;
    V_C5 BINARY_DOUBLE :=  4.374664141464968E+00;
    V_C6 BINARY_DOUBLE :=  2.938163982698783E+00;

    V_D1 BINARY_DOUBLE :=  7.784695709041462E-03;
    V_D2 BINARY_DOUBLE :=  3.224671290700398E-01;
    V_D3 BINARY_DOUBLE :=  2.445134137142996E+00;
    V_D4 BINARY_DOUBLE :=  3.754408661907416E+00;

    V_Q  BINARY_DOUBLE;
    V_T  BINARY_DOUBLE;
BEGIN
    IF (P_P < 0 OR P_P > 1) THEN
        RETURN NULL;
    END IF;

    IF (P_P < 0.02425) THEN
        V_Q := SQRT(-2 * LN(P_P));
    ELSE
        V_Q := SQRT(-2 * LN(1 - P_P));
    END IF;

    IF (ABS(V_Q) <= 0.425) THEN
        V_T := V_Q * V_Q;
    ELSE
        V_T := V_Q;
    END IF;

    V_T := (((((V_C1 * V_T + V_C2) * V_T + V_C3) * V_T + V_C4) * V_T + V_C5) * V_T + V_C6) /
           ((((V_D1 * V_T + V_D2) * V_T + V_D3) * V_T + V_D4) * V_T + 1.0);

    IF (V_Q < 0) THEN
        V_T := -V_T;
    END IF;

    RETURN V_T;
END;

FUNCTION FN_GET_SCP_PLAN_MIN_DATE
(
    P_PROGRAMID        IN VARCHAR2
  , P_DIVISION_ID      IN VARCHAR2
  , P_PLAN_TYPE        IN VARCHAR2
  , P_OPERATION_GROUP  IN VARCHAR2
  , P_SEQ              IN NUMBER
)
RETURN T_SCP_MINDT_TAB PIPELINED
/*
 * Program ID   : FN_GET_SCP_PLAN_MIN_DATE
 * Description  : _anl_ table 과 hist Table 분리를 위한 MIN(PLAN_START_YYYYMMDD)
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2021.07.22   lwy            PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2)
                                 - scp_anl_production_plan / hist_scp_anl_production_plan 분리작업
 * 2022.07.20   vadabi3        PROGRAMID = 'SCP0079' 추가
 * 2026.07.06   ZIONEX   [PJ202650304] NextSCM Migration
 */
AS
    V_MIN  VARCHAR2(8 CHAR);
BEGIN
    /* Shipment Plan FG */
    /* 20220720 SCP0079 추가 */
    IF P_PROGRAMID = 'SCP0009' OR P_PROGRAMID = 'SCP0079' THEN
        SELECT SUBSTR(MIN(PLAN_START_YYYYMMDD), 1, 8)
          INTO V_MIN
          FROM SCP_ANL_SHIPMENT_PLAN_FG
         WHERE DIVISION_ID = P_DIVISION_ID;
        PIPE ROW (T_SCP_MINDT_ROW(V_MIN));
    /* Shipment Plan SEMI */
    ELSIF P_PROGRAMID = 'SCP0010' THEN
        SELECT SUBSTR(MIN(PLAN_START_YYYYMMDD), 1, 8)
          INTO V_MIN
          FROM SCP_ANL_SHIPMENT_PLAN_SEMI
         WHERE DIVISION_ID = P_DIVISION_ID;
        PIPE ROW (T_SCP_MINDT_ROW(V_MIN));
    /* Production Plan / Production Plan Line */
    ELSIF P_PROGRAMID = 'SCP0011' OR P_PROGRAMID = 'SCP0013' THEN
        /* lwy : 현업 조회안되는 문제로 임시 +30 설정
         * INSERT INTO @TBL(MIN_YYYYMMDD)
         * SELECT CONVERT(nvarchar(8), MIN(PLAN_START_YYYYMMDD),112)
         *  FROM scp_anl_production_plan WITH(NOLOCK)
         * WHERE DIVISION_ID = @P_DIVISION_ID
         */
        SELECT TO_CHAR(TO_DATE(MIN(PLAN_START_YYYYMMDD), 'YYYYMMDD') + 30, 'YYYYMMDD')
          INTO V_MIN
          FROM SCP_ANL_PRODUCTION_PLAN
         WHERE DIVISION_ID = P_DIVISION_ID;
        PIPE ROW (T_SCP_MINDT_ROW(V_MIN));
    END IF;

    RETURN;
END;

FUNCTION FN_GET_SHIPMENT_NO_DISPLAY
