    V_SHIPMENT_NO       VARCHAR2(100 CHAR);
BEGIN
    IF P_RESULT_TYPE = 'S' THEN
        V_SHIPMENT_NO := '-';
    ELSE
        V_SHIPMENT_NO := P_SHIPMENT_NO;
