FUNCTION           "FN_GET_SOURCE_CODE" 
(
    P_USE_TYPE     IN VARCHAR2
  , P_MODULE       IN VARCHAR2
  , P_SUBMODULE    IN VARCHAR2
  , P_CATEGORY_ID  IN NUMBER
  , P_SEQ          IN NUMBER
)
RETURN VARCHAR2
/*
 * Program ID   : FN_GET_SOURCE_CODE
 * Description  :
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2018/01/30  ygkim       Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 *
 * 2026-07-03   ZIONEX  [PJ202650304]  NextSCM Migration
*/
AS

    V_TEXT    CLOB;
    V_RETURN  VARCHAR2(4000 CHAR);
    V_SEQ     NUMBER := P_SEQ;

BEGIN

    BEGIN
        SELECT SQL_LONG_TEXT
          INTO V_TEXT
          FROM SCM_ADM_RECIPIENT_LIST A
         WHERE 1 = 1
           AND A.USE_TYPE_CODE   = P_USE_TYPE
           AND A.MODULE_CODE     = P_MODULE
           AND A.SUB_MODULE_CODE = P_SUBMODULE
           AND A.CATEGORY_ID     = P_CATEGORY_ID;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            V_TEXT := NULL;
    END;

    IF V_SEQ < 0 THEN
        V_SEQ := 1;
    END IF;

    IF (V_SEQ = 1) THEN
        V_RETURN := SUBSTR(V_TEXT, 1, 4000);
    ELSIF (V_SEQ = 2) THEN
        V_RETURN := SUBSTR(V_TEXT, 4001, 4000);
    ELSIF (V_SEQ = 3) THEN
        V_RETURN := SUBSTR(V_TEXT, 8001, 4000);
    ELSIF (V_SEQ = 4) THEN
        V_RETURN := SUBSTR(V_TEXT, 12001, 4000);
    ELSIF (V_SEQ = 5) THEN
        V_RETURN := SUBSTR(V_TEXT, 16001, 4000);
    ELSIF (V_SEQ = 6) THEN
        V_RETURN := SUBSTR(V_TEXT, 20001, 4000);
    ELSIF (V_SEQ = 7) THEN
        V_RETURN := SUBSTR(V_TEXT, 24001, 4000);
    ELSIF (V_SEQ = 8) THEN
        V_RETURN := SUBSTR(V_TEXT, 28001, 4000);
    END IF;

    RETURN V_RETURN;  /* @v_return */

END;

FUNCTION FN_GET_SSP_INT_JOBNEXTTIME
(
    I_EXECCLCVAL   IN INTEGER
  , I_EXECCLCTYPE  IN VARCHAR2
  , I_CURTIME      IN DATE
  , I_FIRSTTIME    IN DATE
)
RETURN DATE
/***************************************************************************************************
 * Program ID   : PR_SSP_INT_SYSTEMEXEC_RUNJOB
 * Description  :
 * OutTable     :
 * Execute      : EXEC PR_SSP_INT_SYSTEMEXEC_RUNJOB
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2021.10.01   SSP Pjt.       Create.
 * 2026.07.06   ZIONEX   [PJ202650304] NextSCM Migration
****************************************************************************************************/
AS
    V_NEXTTIME  DATE;
BEGIN

    IF I_EXECCLCTYPE = 'MONTH' THEN
        V_NEXTTIME := ADD_MONTHS(I_CURTIME, I_EXECCLCVAL);
    ELSIF I_EXECCLCTYPE = 'DAY' THEN

        /* = (CURTIME + VAL일)의 날짜부분 + FIRSTTIME 의 시간부분 */
        V_NEXTTIME := TRUNC(I_CURTIME + I_EXECCLCVAL) + (I_FIRSTTIME - TRUNC(I_FIRSTTIME));
    ELSIF I_EXECCLCTYPE = 'HOUR' THEN
        V_NEXTTIME := I_CURTIME + I_EXECCLCVAL / 24;
    ELSIF I_EXECCLCTYPE = 'MINUTE' THEN
        V_NEXTTIME := I_CURTIME + I_EXECCLCVAL / 1440;
    ELSE
        V_NEXTTIME := I_CURTIME;
    END IF;

    /* 초를 00초로 바꿔서 지속적인 처리시간 유지를 위함. */
    /* 분:초를 00:00초로 바꿔서 지속적인 처리시간 유지를 위함. 2014.11.21 재수정 */

    V_NEXTTIME := TRUNC(V_NEXTTIME, 'MI');

    RETURN V_NEXTTIME;

END;

FUNCTION "FN_GET_SSP_MKT_OWNER_NAME" 
(
  p_owner     IN VARCHAR2,
  p_delim     IN VARCHAR2,
  p_language  IN VARCHAR2
)
RETURN CLOB
AS
/*
 * Program ID   : FN_GET_SSP_MKT_OWNER_NAME
 * Description  : PROJECT OWNER  
 *        
 *        
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2018.11.01   juhlee     Initial Release [PJ20182279] 전지본부 출하계획 시스템 구축 프로젝트
 * 2026.03.06   jcnam          [PJ20264226] NextSCM Pilot 설계 및 개발 
 * 2026.10.07   AJS            조회 속도 - 아이디 조회 6곳 FULL(U) 힌트를 대문자 아이디 함수 인덱스(IDX02) 사용으로 변경
 *                             결함 - 담당자 값이 구분자로 끝나면(예 abc,) 반복이 끝나지 않던 것 수정(남은 값 없음 = 종료)
 *
 */
  v_owner     VARCHAR2(4000 CHAR) := p_owner;
  v_restr     CLOB := EMPTY_CLOB();
  v_username  VARCHAR2(4000 CHAR);
  v_token     VARCHAR2(4000 CHAR);
  n_pos       PLS_INTEGER;

  FUNCTION fn_trim(p_str VARCHAR2) RETURN VARCHAR2 IS
  BEGIN
    RETURN TRIM(p_str);
  END;
BEGIN

  IF v_owner IS NULL OR TRIM(v_owner) IS NULL THEN
    RETURN NULL;
  END IF;

  n_pos := INSTR(v_owner, p_delim);

  IF n_pos > 0 THEN
    LOOP
      EXIT WHEN n_pos <= 0;

      v_token := fn_trim(SUBSTR(v_owner, 1, n_pos - 1));

      IF p_language = 'KO' THEN
        BEGIN
          SELECT /*+ INDEX(U IDX02_SCM_MST_SSO_USER_INFO) */   /* AJS 20261007 속도 : 원본 힌트 FULL(U) — 대문자 아이디 함수 인덱스 사용 */
                 U.USER_NAME || '(' || U.USER_ID || ')'
          INTO   v_username
          FROM   SCM_MST_SSO_USER_INFO U
          /* AS-IS MSSQL 은 대소문자를 가리지 않는다 — 원장 사용자 아이디는 거의 전건 소문자이므로 양쪽을 UPPER */
          WHERE  UPPER(U.USER_ID) = UPPER(v_token);
        EXCEPTION
          WHEN NO_DATA_FOUND THEN
            v_username := '(' || v_token || ')';
        END;
      ELSE
        BEGIN
          SELECT /*+ INDEX(U IDX02_SCM_MST_SSO_USER_INFO) */   /* AJS 20261007 속도 : 원본 힌트 FULL(U) — 대문자 아이디 함수 인덱스 사용 */
                 U.USER_NAME_EN || '(' || U.USER_ID || ')'
          INTO   v_username
          FROM   SCM_MST_SSO_USER_INFO U
          /* AS-IS MSSQL 은 대소문자를 가리지 않는다 — 원장 사용자 아이디는 거의 전건 소문자이므로 양쪽을 UPPER */
          WHERE  UPPER(U.USER_ID) = UPPER(v_token);
        EXCEPTION
          WHEN NO_DATA_FOUND THEN
            v_username := '(' || v_token || ')';
        END;
      END IF;

      v_restr := TRIM(v_restr) || v_username || ',';

      v_owner := SUBSTR(v_owner, n_pos + LENGTH(p_delim));
      /* n_pos   := INSTR(v_owner, p_delim); */
      n_pos   := NVL(INSTR(v_owner, p_delim), 0);   /* AJS 20261007 결함 : 담당자 값이 구분자로 끝나면 남은 값이 NULL 이 되어 끝나지 않던 반복 종료 */
    END LOOP;

    v_token := fn_trim(v_owner);

    IF p_language = 'KO' THEN
      BEGIN
        SELECT /*+ INDEX(U IDX02_SCM_MST_SSO_USER_INFO) */   /* AJS 20261007 속도 : 원본 힌트 FULL(U) — 대문자 아이디 함수 인덱스 사용 */
               U.USER_NAME || '(' || U.USER_ID || ')'
        INTO   v_username
        FROM   SCM_MST_SSO_USER_INFO U
        /* AS-IS MSSQL 은 대소문자를 가리지 않는다 — 원장 사용자 아이디는 거의 전건 소문자이므로 양쪽을 UPPER */
        WHERE  UPPER(U.USER_ID) = UPPER(v_token);
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          v_username := '(' || v_token || ')';
      END;
    ELSE
      BEGIN
        SELECT /*+ INDEX(U IDX02_SCM_MST_SSO_USER_INFO) */   /* AJS 20261007 속도 : 원본 힌트 FULL(U) — 대문자 아이디 함수 인덱스 사용 */
               U.USER_NAME_EN || '(' || U.USER_ID || ')'
        INTO   v_username
        FROM   SCM_MST_SSO_USER_INFO U
        /* AS-IS MSSQL 은 대소문자를 가리지 않는다 — 원장 사용자 아이디는 거의 전건 소문자이므로 양쪽을 UPPER */
        WHERE  UPPER(U.USER_ID) = UPPER(v_token);
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          v_username := '(' || v_token || ')';
      END;
    END IF;

    v_restr := v_restr || v_username;

  ELSE

    v_token := fn_trim(v_owner);

    IF p_language = 'KO' THEN
      BEGIN
        SELECT /*+ INDEX(U IDX02_SCM_MST_SSO_USER_INFO) */   /* AJS 20261007 속도 : 원본 힌트 FULL(U) — 대문자 아이디 함수 인덱스 사용 */
               U.USER_NAME || '(' || U.USER_ID || ')'
        INTO   v_restr
        FROM   SCM_MST_SSO_USER_INFO U
        /* AS-IS MSSQL 은 대소문자를 가리지 않는다 — 원장 사용자 아이디는 거의 전건 소문자이므로 양쪽을 UPPER */
        WHERE  UPPER(U.USER_ID) = UPPER(v_token);
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          v_restr := '(' || v_token || ')';
      END;
    ELSE
      BEGIN
        SELECT /*+ INDEX(U IDX02_SCM_MST_SSO_USER_INFO) */   /* AJS 20261007 속도 : 원본 힌트 FULL(U) — 대문자 아이디 함수 인덱스 사용 */
               U.USER_NAME_EN || '(' || U.USER_ID || ')'
        INTO   v_restr
        FROM   SCM_MST_SSO_USER_INFO U
        /* AS-IS MSSQL 은 대소문자를 가리지 않는다 — 원장 사용자 아이디는 거의 전건 소문자이므로 양쪽을 UPPER */
        WHERE  UPPER(U.USER_ID) = UPPER(v_token);
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          v_restr := '(' || v_token || ')';
      END;
    END IF;

  END IF;

  RETURN v_restr;

END FN_GET_SSP_MKT_OWNER_NAME;

FUNCTION FN_GET_SSP_PACKER_MODEL
(
    P_DIVISION_ID  IN VARCHAR2
  , P_FROM_SITE    IN VARCHAR2
  , P_ITEM_ID      IN VARCHAR2
)
RETURN VARCHAR2
/*************************************************************************************************
  * PROJECT       : LG CHEM SCP PRJ.
  * FUNCTION NAME : FN_GET_SSP_PACKER_MODEL
  * DESCRIPTION   : RETURN1 PACKER ITEM ID
  * INPUT         : P_DIVISION_ID,@P_FROM_SITE, P_ITEM_ID
  * OUTPUT        : PACKER ITEM_ID
  * PROGRAM HISTORY
  *------------------------------------------------------------------------------------------------
    DATE         IN CHARGE     DESCRIPTION
  *------------------------------------------------------------------------------------------------
  * 2018-09-11   LJH           Initial Release [PJ20182279] 전지본부 출하계획 시스템 구축 프로젝트
  * 2026.07.06   ZIONEX   [PJ202650304] NextSCM Migration
  *************************************************************************************************/
AS
    X_PACKER_MODEL     VARCHAR2(100 CHAR) := '';
    X_OPERATION_GROUP  VARCHAR2(1 CHAR)   := '';
    X_PACKER_SUFFIX    VARCHAR2(10 CHAR)  := '';
BEGIN

    IF P_DIVISION_ID = '40' THEN   /* 소형일 경우만 */
        BEGIN
            SELECT OG
              INTO X_OPERATION_GROUP
              FROM ( SELECT I.SCP_OPERATION_GROUP AS OG
                       FROM SCM_MST_ITEM_SN I
                      WHERE 1 = 1
                        AND I.DIVISION_ID = P_DIVISION_ID
                        AND I.ITEM_ID     = P_ITEM_ID )
             WHERE ROWNUM = 1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                X_OPERATION_GROUP := '';
        END;

        IF X_OPERATION_GROUP = 'P' THEN   /* PACK인 경우만 */
            SELECT NVL(MAX(PACKER_ITEM_ID_SUFFIX), '@')
              INTO X_PACKER_SUFFIX
              FROM SCM_MST_SITE
             WHERE DIVISION_ID = '40'
               AND SITE_TYPE   = 'PLANT'
               AND OSP_YN      = 'Y'
               AND SCM_SITE_ID = P_FROM_SITE;

            IF X_PACKER_SUFFIX <> '@' THEN   /* PACKER_SUFFIX가 있는 경우만 */
                X_PACKER_MODEL := SUBSTR(P_ITEM_ID, 1, 11) || X_PACKER_SUFFIX;
            ELSE
                X_PACKER_MODEL := P_ITEM_ID;
            END IF;
        ELSE
            X_PACKER_MODEL := P_ITEM_ID;
        END IF;
    ELSE
        X_PACKER_MODEL := P_ITEM_ID;
    END IF;

    RETURN X_PACKER_MODEL;

END;

FUNCTION FN_GET_SSP_SITE_INFO
(
    P_DIVISION_ID   VARCHAR2
   ,P_SCM_SITE_ID   VARCHAR2
   ,P_RETURN_TYPE   VARCHAR2
)
RETURN VARCHAR2
IS
/****************************************************************************
  * FUNCTION NAME : FN_GET_SSP_SITE_INFO
  * DESCRIPTION   : ERP전송을 위한 SITE 정보
  * INPUT         : P_DIVISION_ID : DIVISION
                    P_SCM_SITE_ID : SCM_SITE_ID
                    P_RETURN_TYPE : SITE_TYPE, PLANT_ID, VENDOR_ID, SOLDTO_CODE, SHIPTO_CODE, COMPANY_ID , COUNTRY, VMI_YN
  * PROGRAM HISTORY
  *--------------------------------------------------------------
  *  DATE      IN CHARGE           DESCRIPTION
  *--------------------------------------------------------------
  * 2018.11.26   juhlee     Initial Release [PJ20182279] 전지본부 출하계획 시스템 구축 프로젝트
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
  ****************************************************************************/
    V_SITE_TYPE     VARCHAR2(100) := '';
    V_PLANT_ID      VARCHAR2(100) := '';
    V_VENDOR_ID     VARCHAR2(100) := '';
    V_SOLDTO_CODE   VARCHAR2(100) := '';
    V_SHIPTO_CODE   VARCHAR2(100) := '';
    V_COMPANY_ID    VARCHAR2(100) := '';
    V_COUNTRY       VARCHAR2(100) := '';
    V_VMI_YN        VARCHAR2(100) := '';
    V_RESULT        VARCHAR2(100) := '';
BEGIN

    BEGIN
        SELECT CASE WHEN A.SITE_TYPE = 'SALES' THEN 'A'                             /* Sales Site */
                    WHEN A.SITE_TYPE = 'PLANT' AND A.OSP_YN = 'N' THEN 'B'          /* Factory Site */
                    WHEN A.SITE_TYPE = 'PLANT' AND A.OSP_YN = 'Y' THEN 'C'          /* Packer */
               END
             , A.LOGISTIC_PLANT_ID
             , CASE WHEN A.SITE_TYPE = 'PLANT' AND A.OSP_YN = 'Y' THEN A.PLANT_ID END
             , B.SOLDTO_CODE
             , B.SHIPTO_CODE
             , A.COMPANY_ID
             , A.COUNTRY
             , A.VMI_YN
          INTO V_SITE_TYPE
             , V_PLANT_ID
             , V_VENDOR_ID
             , V_SOLDTO_CODE
             , V_SHIPTO_CODE
             , V_COMPANY_ID
             , V_COUNTRY
             , V_VMI_YN
          FROM SCM_MST_SITE A
             , SCM_MST_SITE_CUSTOMER B
         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
           AND B.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND B.VALID_YN(+) = 'Y'
           AND B.REP_YN(+) = 'Y'
           AND A.DIVISION_ID = P_DIVISION_ID
           AND A.SCM_SITE_ID = P_SCM_SITE_ID
           AND A.VALID_YN = 'Y'
           AND ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            NULL;
    END;

    IF (P_RETURN_TYPE = 'SITE_TYPE') THEN
        V_RESULT := V_SITE_TYPE;
    ELSIF (P_RETURN_TYPE = 'PLANT_ID') THEN
        V_RESULT := V_PLANT_ID;
    ELSIF (P_RETURN_TYPE = 'VENDOR_ID') THEN
        V_RESULT := V_VENDOR_ID;
    ELSIF (P_RETURN_TYPE = 'SOLDTO_CODE') THEN
        V_RESULT := V_SOLDTO_CODE;
    ELSIF (P_RETURN_TYPE = 'SHIPTO_CODE') THEN
        V_RESULT := V_SHIPTO_CODE;
    ELSIF (P_RETURN_TYPE = 'COMPANY_ID') THEN
        V_RESULT := V_COMPANY_ID;
    ELSIF (P_RETURN_TYPE = 'COUNTRY') THEN
        V_RESULT := V_COUNTRY;
    ELSIF (P_RETURN_TYPE = 'VMI_YN') THEN
        V_RESULT := V_VMI_YN;
    ELSE
        V_RESULT := NULL;
    END IF;

    RETURN V_RESULT;

END FN_GET_SSP_SITE_INFO;

FUNCTION FN_GET_SSP_SITE_INFO_EXCEPTION
(
    P_DIVISION_ID       VARCHAR2
   ,P_FROM_SCM_SITE_ID  VARCHAR2
   ,P_TO_SCM_SITE_ID    VARCHAR2
   ,P_RETURN_TYPE       VARCHAR2
)
RETURN VARCHAR2
IS
/****************************************************************************
  * FUNCTION NAME : FN_GET_SSP_SITE_INFO_EXCEPTION
  * DESCRIPTION   : FN_GET_SSP_SITE_INFO에서 FROM 정보를 참고하여야 하는 경우의 예외 처리
  * 일반적으로 FN_GET_SSP_SITE_INFO 함수를 이용해서 TO_COMPANY_ID 정보를 획득한다.
  * [E20250821-001308] --
  * 2025/07/08 자동차.마케팅,마케팅1.Ford티에서 WA법인 기준으로 설정된 Ford_MX_CTN 출하사이트에 대해서
  *            From Site가 MI인 경우 MI법인으로 From Site가 WA인 경우 WA법인으로 출하하도록 수정요청
  * 2025/08/18 COMPANY_ID 구현
  * 2025/08/19 같은 룩업에서 SITE_TYPE 예외 추가를 요청함
  * 예외는 lookup type ssp_site_info_exception에 정의한다
  * PROGRAM HISTORY
  *--------------------------------------------------------------
  *  DATE      IN CHARGE           DESCRIPTION
  *--------------------------------------------------------------
  * 2025.0818   chkim.68     FN_GET_SSP_SITE_INFO의 COMPANY 대체 예외 적용
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
  ****************************************************************************/
    V_PLANT_ID          VARCHAR2(100) := '';
    V_EXCEPTION_VALUE   VARCHAR2(100) := NULL;
BEGIN

    /* company_id 타입 아닌 경우는 from_site 무시하고 fn_get_ssp_site_info를 그대로 사용한다 */
    IF P_RETURN_TYPE <> 'COMPANY_ID' THEN
        IF P_RETURN_TYPE <> 'SITE_TYPE' THEN
            RETURN FN_GET_SSP_SITE_INFO(P_DIVISION_ID, P_TO_SCM_SITE_ID, P_RETURN_TYPE);
        END IF;
    END IF;

    /* to_site에 대한 예외가 존재하 */
    V_PLANT_ID := FN_GET_SSP_SITE_INFO(P_DIVISION_ID, P_FROM_SCM_SITE_ID, 'PLANT_ID');

    IF P_TO_SCM_SITE_ID IS NULL THEN
        RETURN FN_GET_SSP_SITE_INFO(P_DIVISION_ID, P_TO_SCM_SITE_ID, P_RETURN_TYPE);
    END IF;

    IF P_RETURN_TYPE = 'COMPANY_ID' THEN

        BEGIN
            /* 등록값이 소문자라 AS-IS(대소문자 무시)와 같은 결과가 되도록 UPPER 비교 */
            SELECT SEGMENT5
              INTO V_EXCEPTION_VALUE
              FROM SCM_ADM_LOOKUP_MASTER_DETAIL
             WHERE UPPER(TRIM(LOOKUP_TYPE)) = 'SSP_SITE_INFO_EXCEPTION'
               AND (SEGMENT4 = V_PLANT_ID
                OR SEGMENT4 = '-')
               AND UPPER(TRIM(SEGMENT1)) = 'COMPANY_ID'
               AND SEGMENT2 = P_DIVISION_ID
               AND SEGMENT3 = P_TO_SCM_SITE_ID
               AND UPPER(TRIM(VALID_YN)) = 'Y'
               AND ROWNUM = 1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                V_EXCEPTION_VALUE := NULL;
        END;

        IF V_EXCEPTION_VALUE IS NULL THEN
            RETURN FN_GET_SSP_SITE_INFO(P_DIVISION_ID, P_TO_SCM_SITE_ID, P_RETURN_TYPE);
        END IF;

        RETURN V_EXCEPTION_VALUE;

    END IF;

    IF P_RETURN_TYPE = 'SITE_TYPE' THEN

        BEGIN
            SELECT SEGMENT5
              INTO V_EXCEPTION_VALUE
              FROM SCM_ADM_LOOKUP_MASTER_DETAIL
             WHERE UPPER(TRIM(LOOKUP_TYPE)) = 'SSP_SITE_INFO_EXCEPTION'
               AND (SEGMENT4 = V_PLANT_ID
                OR SEGMENT4 = '-')
               AND UPPER(TRIM(SEGMENT1)) = 'SITE_TYPE'
               AND SEGMENT2 = P_DIVISION_ID
               AND SEGMENT3 = P_TO_SCM_SITE_ID
               AND UPPER(TRIM(VALID_YN)) = 'Y'
               AND ROWNUM = 1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                V_EXCEPTION_VALUE := NULL;
        END;

        IF V_EXCEPTION_VALUE IS NULL THEN
            RETURN FN_GET_SSP_SITE_INFO(P_DIVISION_ID, P_TO_SCM_SITE_ID, P_RETURN_TYPE);
        END IF;

        RETURN V_EXCEPTION_VALUE;

    END IF;

    RETURN FN_GET_SSP_SITE_INFO(P_DIVISION_ID, P_TO_SCM_SITE_ID, P_RETURN_TYPE);

END FN_GET_SSP_SITE_INFO_EXCEPTION;

FUNCTION FN_GET_VOC_DELAY_YN
(
    P_VALUE_STATUS IN VARCHAR2
  , P_VALUE_DATE   IN VARCHAR2
)
RETURN VARCHAR2
/****************************************************************************
  * PROJECT       : LG CHEM SCM REPORT.
  * FUNCTION NAME : FN_GET_VOC_DELAY_YN
  * DESCRIPTION   : DELAY YN
  *
  * INPUT         : @strValue : 입력값 @splitChar :구분자
  * PROGRAM HISTORY
  *--------------------------------------------------------------
  *  DATE      IN CHARGE           DESCRIPTION
  *--------------------------------------------------------------
  * 2022-02-21   vadabi3		INITIAL
  *--------------------------------------------------------------
  SELECT dbo.FN_GET_VOC_DELAY_YN(CLASSIFY_STATUS,CLASSIFY_DATE) FROM SCM_ADM_SYS_VOC
  2026.07.06   ZIONEX   [PJ202650304] NextSCM Migration
  ****************************************************************************/
AS
  V_CHECK_DATE     VARCHAR2(20 CHAR);
  V_DELAY_YN       VARCHAR2(20 CHAR);
  V_CONVERT_DATE   DATE;
  V_NOW_DATE       DATE;
  V_VALUE_STATUS   VARCHAR2(4000 CHAR);
BEGIN

  V_VALUE_STATUS := P_VALUE_STATUS;

  IF V_VALUE_STATUS IS NULL
  THEN
    V_VALUE_STATUS := 'RN';
  END IF;

  V_CHECK_DATE := P_VALUE_DATE;
  V_DELAY_YN   := 'N';

  /* 진행중인 경우만 체크 대상 */
  IF P_VALUE_DATE IS NULL
  THEN
    RETURN 'NULL';
  END IF;

  IF V_VALUE_STATUS <> 'RN'
  THEN
    RETURN 'NO RUN';
  END IF;

  /* 체크 데이트 값이 의미 있는 값인지 확인 */
  IF LENGTH(P_VALUE_DATE) > 10
  THEN
    /* 완료일 수정 = 2번째 날자값이 대상 */
    BEGIN
      SELECT VAL
        INTO V_CHECK_DATE
        FROM TABLE(FN_GET_VOC_SPLIT(P_VALUE_DATE, CHR(13) || CHR(10)))
       WHERE POS = 2;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        NULL;
    END;

    V_CHECK_DATE := LTRIM(V_CHECK_DATE);
    V_CHECK_DATE := RTRIM(V_CHECK_DATE);
    V_CHECK_DATE := REPLACE(V_CHECK_DATE, '-', '');

    V_DELAY_YN := 'DATE ERROR';
    IF LENGTH(V_CHECK_DATE) = 8
    THEN
      /* 현재시간과 비교 */
      V_CONVERT_DATE := TO_DATE(V_CHECK_DATE, 'YYYYMMDD');
      V_NOW_DATE     := TRUNC(SYSDATE);
      V_DELAY_YN     := 'OK';

      IF V_CONVERT_DATE < V_NOW_DATE
      THEN
        V_DELAY_YN := 'Y';
      END IF;
    END IF;

  END IF;

  RETURN V_DELAY_YN;

END;

FUNCTION FN_GET_VOC_SOON_YN
(
  P_VALUE_STATUS IN VARCHAR2
, P_VALUE_DATE   IN VARCHAR2
)
RETURN VARCHAR2
AS
/****************************************************************************
  * PROJECT       : LG CHEM SCM REPORT.
  * FUNCTION NAME : FN_GET_VOC_SOON_YN
  * DESCRIPTION   : SOON YN : 완료 일주일전 체크
  *
  * INPUT         : @strValue : 입력값 @splitChar :구분자
  * PROGRAM HISTORY
  *--------------------------------------------------------------
  *  DATE      IN CHARGE           DESCRIPTION
  *--------------------------------------------------------------
  * 2022-02-21   vadabi3		INITIAL
  *--------------------------------------------------------------
  * 2026.07.06   ZIONEX   [PJ202650304] NextSCM Migration
  SELECT dbo.FN_GET_VOC_SOON_YN(CLASSIFY_STATUS,CLASSIFY_DATE) FROM SCM_ADM_SYS_VOC
  ****************************************************************************/
  V_CHECK_DATE     VARCHAR2(20 CHAR);
  V_SOON_YN        VARCHAR2(20 CHAR);
  D_CONVERT_DATE   DATE;
  D_SOON_DATE      DATE;
  D_NOW_DATE       DATE;
  V_VALUE_STATUS   VARCHAR2(4000 CHAR);
BEGIN

  V_CHECK_DATE   := P_VALUE_DATE;
  V_SOON_YN      := 'N';
  V_VALUE_STATUS := P_VALUE_STATUS;

  IF V_VALUE_STATUS = '' THEN
    V_VALUE_STATUS := 'RN';
  END IF;

  /* 진행중인 경우만 체크 대상 */
  IF P_VALUE_DATE IS NULL THEN
    RETURN 'NO DATE';
  END IF;

  IF V_VALUE_STATUS != 'RN' THEN
    RETURN 'NO RUN';
  END IF;

  /* 체크 데이트 값이 의미 있는 값인지 확인 */
  IF LENGTH(P_VALUE_DATE) > 10 THEN

    /* 완료일 수정 = 2번째 날자값이 대상 */
    BEGIN
      SELECT VAL
        INTO V_CHECK_DATE
        FROM FN_GET_VOC_SPLIT(P_VALUE_DATE, CHR(13) || CHR(10))
       WHERE POS = 2
         AND ROWNUM = 1;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        V_CHECK_DATE := NULL;
    END;

    V_CHECK_DATE := TRIM(V_CHECK_DATE);
    V_CHECK_DATE := REPLACE(V_CHECK_DATE, '-', '');

    V_SOON_YN := 'DATE ERROR';

    IF LENGTH(V_CHECK_DATE) = 8 THEN

      /* 현재시간과 비교 */
      BEGIN
        D_CONVERT_DATE := TO_DATE(V_CHECK_DATE, 'YYYYMMDD');
      EXCEPTION
        WHEN OTHERS THEN
          D_CONVERT_DATE := NULL;
      END;

      D_SOON_DATE := TRUNC(SYSDATE) + 7;
      D_NOW_DATE  := TRUNC(SYSDATE);

      V_SOON_YN := 'OK';

      IF D_CONVERT_DATE IS NOT NULL THEN
        IF D_CONVERT_DATE < D_SOON_DATE AND D_CONVERT_DATE >= D_NOW_DATE THEN
          V_SOON_YN := 'Y';
        END IF;
      END IF;

    END IF;

  END IF;

  RETURN V_SOON_YN;

END FN_GET_VOC_SOON_YN;

FUNCTION FN_GET_VOC_SPLIT
(
  STRVALUE   IN VARCHAR2
, SPLITCHAR  IN VARCHAR2
)
RETURN T_FN_GET_VOC_SPLIT_TAB
PIPELINED
/****************************************************************************
  * PROJECT       : LG CHEM SCM REPORT.
  * FUNCTION NAME : FN_GET_VOC_SPLIT
  * DESCRIPTION   : SPLIT
  *
  * INPUT         : @strValue : 입력값 @splitChar :구분자
  * PROGRAM HISTORY
  *--------------------------------------------------------------
  *  DATE      IN CHARGE           DESCRIPTION
  *--------------------------------------------------------------
  * 2022-02-21   vadabi3		INITIAL
  * 2026.07.06   ZIONEX   [PJ202650304] NextSCM Migration
  ****************************************************************************/
AS
  V_STR         VARCHAR2(32767 CHAR);
  V_SPLIT       VARCHAR2(4000 CHAR);
  N_SPLIT_LEN   PLS_INTEGER;
  N_POS         PLS_INTEGER;
  N_NEXT        PLS_INTEGER;
  N_SEQ         PLS_INTEGER := 0;
  V_TOKEN       VARCHAR2(200 CHAR);
BEGIN
  /* - '' 값도 반환한다
  - 마지막은 분리자로 끝낸다
  SELECT * FROM dbo.[FN_GET_VOC_SPLIT]('2021-02-10\r\n2021-02-11\r\n2021-02-12','\r\n') A
  */

  /* ------------------------------------------------------------------
     진행중인 경우만 체크 대상
     ------------------------------------------------------------------ */
  IF STRVALUE IS NULL THEN
    RETURN;
  END IF;


  IF SPLITCHAR IS NULL THEN
    RETURN;
  END IF;

  V_STR   := STRVALUE;
  V_SPLIT := SPLITCHAR;

  N_SPLIT_LEN := LENGTH(V_SPLIT);

  /* 마지막은 분리자로 끝낸다: RIGHT(@strValue,@splitCharSize) != @splitChar 이면 분리자 추가 */
  IF SUBSTR(V_STR, LENGTH(V_STR) - N_SPLIT_LEN + 1, N_SPLIT_LEN) != V_SPLIT THEN
    V_STR := V_STR || V_SPLIT;
  END IF;

  /* 앞에 분리자를 붙인다: @strValue = @splitChar + @strValue */
  V_STR := V_SPLIT || V_STR;

  LOOP
    N_POS  := INSTR(V_STR, V_SPLIT);
    N_NEXT := INSTR(V_STR, V_SPLIT, N_POS + N_SPLIT_LEN);

    EXIT WHEN N_NEXT <= 0;

    V_TOKEN := SUBSTR(V_STR, N_POS + N_SPLIT_LEN, N_NEXT - N_POS - N_SPLIT_LEN);

    N_SEQ := N_SEQ + 1;
    PIPE ROW (T_FN_GET_VOC_SPLIT_ROW(N_SEQ, SUBSTR(V_TOKEN, 1, 200)));


    V_STR := SUBSTR(V_STR, 1, N_POS - 1) || SUBSTR(V_STR, N_POS + N_SPLIT_LEN);
  END LOOP;

  RETURN;
END FN_GET_VOC_SPLIT;

FUNCTION           "FN_GET_WEEK_ENG" 
(
