)
RETURN VARCHAR2
/****************************************************************************
  * PROJECT       : LG CHEM SCP PRJ.
  * FUNCTION NAME : FN_GET_WEEK_ENG
  * DESCRIPTION   : 숫자로된 요일을 영문으로 반환해준다.
  *
  * INPUT         : @P_WEEK : 요일
  * OUTPUT        : 영문 요일
