FUNCTION FN_IS_DIVISION(
    P_DIVISION_ID  VARCHAR2
  , P_CHECK        VARCHAR2
  , P_TAG          VARCHAR2 DEFAULT NULL
) RETURN NUMBER
/****************************************************************************
  * PROJECT       : LG ES GSCM SCP PRJ.
  * FUNCTION NAME : [FN_IS_DIVISION]
  * DESCRIPTION   : 사업부별 체크결과를 반환
  *
  * INPUT         : @P_DIVISION_ID : 사업부ID, @P_CHECk : 체크할 사항
  * OUTPUT        :
  * USAGE         :
        - JOINT VENDOR 여부 : SELECT DBO.[FN_IS_DIVISION]('81_HM', 'JV')
        - 자동차사업부및 자동차합작사업부 여부 ;  SELECT DBO.[FN_IS_DIVISION]('81_HM', '자동차')
  * PROGRAM HISTORY
  *--------------------------------------------------------------
  *  DATE      IN CHARGE           DESCRIPTION
  *--------------------------------------------------------------
  * 2023-05-10   KSK        INITIAL
  * 2026.07.06   ZIONEX   [PJ202650304] NextSCM Migration
  ****************************************************************************/
IS
    V_RET              NUMBER(1) := 0;
    V_ELECTRODE_GROUP  VARCHAR2(30 CHAR);
    V_CNT              NUMBER;
BEGIN

    /* 합작법인의 사업부 여부(JV : Joint Ventor) */
    IF P_CHECK = 'JV' THEN
        SELECT COUNT(*) INTO V_CNT
          FROM SCM_MST_DIVISION
         WHERE DIVISION_ID = P_DIVISION_ID
           AND ATTRIBUTE3 != P_DIVISION_ID;
        IF V_CNT > 0 THEN
            V_RET := 1;
        END IF;

    /* 데이터 생성시의 사업부 여부 */
    ELSIF P_CHECK = 'CREATE' THEN
        SELECT COUNT(*) INTO V_CNT
          FROM SCM_MST_DIVISION
         WHERE DIVISION_ID = P_DIVISION_ID
           AND ATTRIBUTE3 = P_TAG;
        IF V_CNT > 0 THEN
            V_RET := 1;
        END IF;

    /* 소속상의 사업부 여부 */
    ELSIF P_CHECK = 'GROUP' THEN
        SELECT COUNT(*) INTO V_CNT
          FROM SCM_MST_DIVISION
         WHERE DIVISION_ID = P_DIVISION_ID
           AND ATTRIBUTE4 = P_TAG;
        IF V_CNT > 0 THEN
            V_RET := 1;
        END IF;

    /* 전극기준의 사업부 여부 */
    ELSIF P_CHECK = 'ELECTRODE' THEN
        /* 전극은 비교사업부에서 제외 */
        SELECT MAX(ATTRIBUTE4) INTO V_ELECTRODE_GROUP
          FROM SCM_MST_DIVISION
         WHERE DIVISION_ID = P_TAG
           AND SUBSTR(P_TAG, 1, 2) != 'EE';

        IF V_ELECTRODE_GROUP IS NOT NULL THEN
            SELECT COUNT(*) INTO V_CNT
              FROM SCM_MST_DIVISION
             WHERE DIVISION_ID = P_DIVISION_ID
               AND ATTRIBUTE4 = V_ELECTRODE_GROUP;
            IF V_CNT > 0 THEN
                V_RET := 1;
            END IF;
        END IF;
    END IF;

    RETURN NVL(V_RET, 0);
END FN_IS_DIVISION;

FUNCTION           "FN_MULTY_TIME" 
(
    P_TIME_ZONE  IN  VARCHAR2
)
RETURN DATE
/*
 * Program ID   : FN_MULTY_TIME
 * Description  : 멀티 타임
 * 사용방법: SELECT DBO.FN_MULTY_TIME('EU042')		;
 * 부가설명: 매월 주차는 1일 기준으로 돌아오는 같은주 이전 일까지를 1주차로 본다
 * 입력방법: ATTRIBUTE1(국가), ATTRIBUTE2(OFFSET), ATTRIBUTE3(써머타입 적용여부), LOOKUP_CODE(기준코드)
 * 			 시작: ATTRIBUTE4(월), ATTRIBUTE5(주차), ATTRIBUTE6 (요일),ATTRIBUTE7 (시간)
 *           종료: ATTRIBUTE8(월), ATTRIBUTE9(주차), ATTRIBUTE10(요일),ATTRIBUTE11(시간)
 *           ATTRIBUTE5(주차), ATTRIBUTE9(주차) : -1 일 경우 마지막 주차의 요일을 가져온다.
 *			 Summer Time 적용 기준
 *           - 월   : 1 ~ 12
 *           - 주차 : 1 (1주차), 2 (2주차), 3 (3주차), -1 (마지막주차)  -> 1주차 기준 : 해당 월의 일자가 첫번째 일요일인 경우 1주차 ( ex- 3일이 일요일인 경우 3일 주차가 1주차)
 *           - 요일 : 1 (일), 2 (월), 3 (화), 4 (수), 5 (목), 6 (금), 7 (토)
 *           - 시간 : 0 ~ 23
 * Program History
 *===================================================================================================
 *   Date          In Charge      Description
 *===================================================================================================
 * 2017. 11. 27    정원식         Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 * 2018. 03. 21    ygkim
 * - 입력방법 수정, LOOKUP 테이블 변경, 프로시저 신규 작성, 시작, 종료 일자 가져오는 FN_WEEKOFDAY_DATE 함수 추가
 * 2026.07.06   ZIONEX   [PJ202650304] NextSCM Migration
 */
IS
    L_TZ            VARCHAR2(600 CHAR) := NVL(P_TIME_ZONE, 'AS054');

    L_OFFSET_HOUR   NUMBER;
    L_SUMMERTIME    VARCHAR2(600 CHAR);

    L_START_MONTH   VARCHAR2(6 CHAR);
    L_START_WEEK    VARCHAR2(600 CHAR);
    L_START_DAY     VARCHAR2(600 CHAR);
    L_START_TIME    VARCHAR2(600 CHAR);

    L_END_MONTH     VARCHAR2(6 CHAR);
    L_END_WEEK      VARCHAR2(600 CHAR);
    L_END_DAY       VARCHAR2(600 CHAR);
    L_END_TIME      VARCHAR2(600 CHAR);

    L_UTC_NOW       DATE := CAST(SYS_EXTRACT_UTC(SYSTIMESTAMP) AS DATE);
    L_UTCTIME       DATE;

    L_YEAR          VARCHAR2(4 CHAR);
    L_SRT_YYYYMM    VARCHAR2(10 CHAR);
    L_END_YYYYMM    VARCHAR2(10 CHAR);

    L_START_DAY_STR VARCHAR2(10 CHAR);
    L_END_DAY_STR   VARCHAR2(10 CHAR);

    L_START_DATE    DATE;
    L_END_DATE      DATE;

    L_SUMMER_ZONE   DATE;
    L_RESULT        DATE;
BEGIN
    SELECT TO_NUMBER(A.ATTRIBUTE2)
         , A.ATTRIBUTE3
         , LPAD(A.ATTRIBUTE4, 2, '0')
         , A.ATTRIBUTE5
         , A.ATTRIBUTE6
         , A.ATTRIBUTE7
         , LPAD(A.ATTRIBUTE8, 2, '0')
         , A.ATTRIBUTE9
         , A.ATTRIBUTE10
         , A.ATTRIBUTE11
      INTO L_OFFSET_HOUR
         , L_SUMMERTIME
         , L_START_MONTH
         , L_START_WEEK
         , L_START_DAY
         , L_START_TIME
         , L_END_MONTH
         , L_END_WEEK
         , L_END_DAY
         , L_END_TIME
      FROM SCM_ADM_LOOKUP_MASTER_DETAIL A
     WHERE A.SEGMENT1    = L_TZ
       AND A.LOOKUP_TYPE = 'TIME_ZONE'
       AND A.VALID_YN    = 'Y';

    L_UTCTIME := L_UTC_NOW + (L_OFFSET_HOUR / 24);

    L_YEAR := TO_CHAR(L_UTC_NOW, 'YYYY');

    L_SRT_YYYYMM := L_YEAR || L_START_MONTH;
    L_END_YYYYMM := L_YEAR || L_END_MONTH;

    IF L_SUMMERTIME = 'Y' THEN
        L_START_DAY_STR := FN_WEEKOFDAY_DATE(L_SRT_YYYYMM, L_START_WEEK, L_START_DAY);
        L_END_DAY_STR   := FN_WEEKOFDAY_DATE(L_END_YYYYMM, L_END_WEEK, L_END_DAY);

        L_START_DATE := TO_DATE(L_START_DAY_STR || ' ' || LPAD(L_START_TIME, 2, '0') || ':00:00', 'YYYY-MM-DD HH24:MI:SS');
        L_END_DATE   := TO_DATE(L_END_DAY_STR   || ' ' || LPAD(L_END_TIME,   2, '0') || ':00:00', 'YYYY-MM-DD HH24:MI:SS');
    ELSE
        L_START_DATE := NULL;
        L_END_DATE   := NULL;
    END IF;

    IF L_SUMMERTIME = 'Y' AND L_UTCTIME >= L_START_DATE THEN
        L_SUMMER_ZONE := L_UTCTIME + (1 / 24);
    ELSE
        L_SUMMER_ZONE := L_UTCTIME;
    END IF;

    IF L_SUMMERTIME = 'Y' AND L_SUMMER_ZONE > L_END_DATE THEN
        L_RESULT := L_SUMMER_ZONE - (1 / 24);
    ELSE
        L_RESULT := L_SUMMER_ZONE;
    END IF;

    RETURN L_RESULT;

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RETURN NULL;
    WHEN OTHERS THEN
        RETURN NULL;
END FN_MULTY_TIME;

FUNCTION           "FN_NEXT_DAY" 
(
    P_DATEVAL  IN DATE
  , P_WEEK     IN VARCHAR2
)
RETURN DATE
/*
 * Program ID   : FN_NEXT_DAY
 * Description  : 특정 일자 이후 요일 일자 찾기
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2017.11.22   Kim SungGi     Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 * 2026.07.06   ZIONEX  [PJ202650304]  NextSCM Migration
 *
 */
AS

    V_DAYVAL     PLS_INTEGER;
    V_RESULTDAY  DATE;
    V_DW         PLS_INTEGER;

BEGIN

    IF P_WEEK = 'SUN' THEN /* OR @week = '일' */
        V_DAYVAL := 1;
    ELSIF P_WEEK = 'MON' THEN /* OR @week = '월' */
        V_DAYVAL := 2;
    ELSIF P_WEEK = 'TUE' THEN /* OR @week = '화' */
        V_DAYVAL := 3;
    ELSIF P_WEEK = 'WED' THEN /* OR @week = '수' */
        V_DAYVAL := 4;
    ELSIF P_WEEK = 'THU' THEN /* OR @week = '목' */
        V_DAYVAL := 5;
    ELSIF P_WEEK = 'FRI' THEN /* OR @week = '금' */
        V_DAYVAL := 6;
    ELSIF P_WEEK = 'SAT' THEN /* OR @week = '토' */
        V_DAYVAL := 7;
    ELSE
        V_DAYVAL := 0;
        RETURN NULL;
    END IF;


    V_DW := MOD(TRUNC(P_DATEVAL) - TRUNC(P_DATEVAL, 'IW') + 1, 7) + 1;

    V_RESULTDAY := P_DATEVAL + 7;
    V_RESULTDAY := V_RESULTDAY - V_DW;
    V_RESULTDAY := V_RESULTDAY + V_DAYVAL;

    IF V_DW < V_DAYVAL THEN
        V_RESULTDAY := V_RESULTDAY - 7;
    END IF;

    RETURN V_RESULTDAY;

END;

FUNCTION           "FN_NEXT_WORK_DAY" 
(
    P_START_DATE  IN DATE          /* Input Date */
  , P_INTERVAL    IN PLS_INTEGER   /* Lead Time */
)
RETURN DATE
/*
 *===================================================================================================
 * Program ID   : FN_NEXT_WORK_DAY
 * Description  : 토,일요일을 제외한 영업일의 LeadTime을 계산하여 Return시킴
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2019.10.23   SONG KEE HO     Initial Release [PS02199094B] LG화학 서비스 설명서
 * 2026-07-03   ZIONEX  [PJ202650304]  NextSCM Migration
 *===================================================================================================
 */
AS

    V_RESULRT_DATE  DATE;              /* 결과값 */
    V_INTERVAL_W    PLS_INTEGER;       /* Loop용 Lead Time 복제 변수 */
    V_RCNT          PLS_INTEGER;
    V_CCNT          PLS_INTEGER;
    V_CCNT_W        PLS_INTEGER;       /* 정수용 */
    V_START_DATE    DATE := P_START_DATE;
    V_CNT_CHK       PLS_INTEGER;

BEGIN

    /* 날짜값이 NULL인경우 무한LOOP발생으로 오늘날짜를 기본값으로 셋팅함 */
    IF V_START_DATE IS NULL THEN
        V_START_DATE := TO_DATE(TO_CHAR(SYSDATE, 'YYYYMMDD'), 'YYYYMMDD');
    END IF;

    IF P_INTERVAL = 0 THEN

        V_RESULRT_DATE := V_START_DATE;   /* 제로 값이면 입력받은 날짜 그대로 Return */

    ELSE

        V_INTERVAL_W := P_INTERVAL;   /* Loop용 변수에 값복사 */

        /* Lead Time 값이 음수인경우 Loop용 변수값을 정수로 변환 */
        IF V_INTERVAL_W < 0 THEN
            V_INTERVAL_W := V_INTERVAL_W * -1;
        END IF;

        /* Count 변수값 초기화 */
        V_RCNT := 1;
        V_CCNT := 1;

        WHILE V_INTERVAL_W >= V_RCNT LOOP

            /* Lead Time 값이 음수인경우 Count변수값을 정수에서 음수로 변환시킴 */
            IF P_INTERVAL < 0 THEN
                V_CCNT_W := V_CCNT * -1;
            ELSE
                V_CCNT_W := V_CCNT;
            END IF;

            SELECT COUNT(1)
              INTO V_CNT_CHK
              FROM SCM_SYS_CALENDAR_M
             WHERE DATE_FULL_NAME = TO_CHAR(V_START_DATE + V_CCNT_W, 'YYYY-MM-DD')
               AND DAYOFWEEK_NO IN (2, 3, 4, 5, 6);

            IF V_CNT_CHK > 0 THEN
                /* 월~금요일인경우만 Count */
                V_RCNT := V_RCNT + 1;
            END IF;

            V_RESULRT_DATE := V_START_DATE + V_CCNT_W;

            /* Count변수값 Add */
            V_CCNT := V_CCNT + 1;

        END LOOP;

    END IF;

    RETURN V_RESULRT_DATE;

END;

