FUNCTION           "FN_SCM_GET_WHERE_SQL" 
(
    P_COLUMN_NAME           IN VARCHAR2
  , P_LOGICAL_OPERATOR_CODE IN VARCHAR2
  , P_CSV_TEXT_LIST         IN VARCHAR2
)
RETURN VARCHAR2
/* ============================================================
 * Program ID   : FN_SCM_GET_WHERE_SQL
 * Description  :
 * Program History
 *------------------------------------------------------------
 * Date          In Charge      Description
 *------------------------------------------------------------
 * 2017/12/20    SongDH         Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 * 2026.07.06    ZIONEX         [PJ202650304] NextSCM Migration
 * ============================================================ */
/*   ALTER FUNCTION [dbo].[SCM_ARR_SPL_VAL]
   (  @sText NVARCHAR(max),  @str NVARCHAR(1)= (파이프),  @idx INT )
   RETURNS NVARCHAR(100) AS BEGIN
     DECLARE @word NVARCHAR(1000);  DECLARE @sTextData NVARCHAR(max);  DECLARE @num INT;
     ...  RETURN(@word); END ; */
IS

    V_CSV_TEXT_LIST    VARCHAR2(32767 CHAR);
    V_UPPER_CSV_TEXT_LIST    VARCHAR2(32767 CHAR);
    V_LOGICAL_OPERATOR VARCHAR2(100 CHAR);
    V_CONDTION_VALUE   VARCHAR2(100 CHAR);
    V_COLUMN_NAME      VARCHAR2(1000 CHAR);
    V_SQL_TEXT         VARCHAR2(32767 CHAR);
    V_COUNT            PLS_INTEGER := 0;
    V_LIST_COUNT       PLS_INTEGER := 0;
    V_1ST_NODE         VARCHAR2(4000 CHAR);
    V_2ND_NODE         VARCHAR2(4000 CHAR);
    /* 원본 @i 는 '-' 분기 안에서만 DECLARE @i INT=0 → 다른 분기 진입시 NULL. */
    V_I                PLS_INTEGER;
BEGIN
    V_CSV_TEXT_LIST    := REPLACE(REPLACE(P_CSV_TEXT_LIST, CHR(13), ''), CHR(10), ',');
    /* 2026-08-21 V_CSV_TEXT_LIST를 대문자로 변환해서 검색할 수 있도록 UPPER추가 */
    V_UPPER_CSV_TEXT_LIST    := UPPER(REPLACE(REPLACE(P_CSV_TEXT_LIST, CHR(13), ''), CHR(10), ','));
    V_LOGICAL_OPERATOR := NVL(UPPER(P_LOGICAL_OPERATOR_CODE), 'LK');
    V_COLUMN_NAME      := TRIM(SCM_ARR_SPL_VAL(P_COLUMN_NAME, ':', 1));
    V_SQL_TEXT         := '';
    V_LIST_COUNT       := 0;

    /* -------------------------------------------------------------------------- */
    /* CheckedListFilter : (!)value1,valu2...(:LK) */
    /* MonthRangePicker, DateRangePicker : '20171201:20171231' 형식이므로 제외 */
    /* ComboColumn : column_name:value */
    /* -------------------------------------------------------------------------- */
    /* 원본 CHARINDEX(@v_csv_text_list,':') = "@v_csv_text_list 를 ':' 안에서 검색"
       (find/search 인자 뒤바뀐 원본 quirk 그대로 보존) -> INSTR(':', V_CSV_TEXT_LIST). */
    IF INSTR(':', V_CSV_TEXT_LIST) > 0 AND V_LOGICAL_OPERATOR NOT IN ('BW','BETWEEN','BD','BETWEN DATE','BM','BETWEEN MONTH')
    THEN

        IF TRIM(FN_SCM_SPLIT(V_CSV_TEXT_LIST, 2, ':')) = 'LK'
        THEN
            /* CheckedListFilter : Like 검색 */
            V_LOGICAL_OPERATOR := TRIM(FN_SCM_SPLIT(V_CSV_TEXT_LIST, 2, ':'));
        END IF;

        V_CSV_TEXT_LIST := TRIM(FN_SCM_SPLIT(V_CSV_TEXT_LIST, 1, ':'));

        /* CheckedListFilter : 'end_customer_code:end_customer_name' */
        IF INSTR(':', P_COLUMN_NAME) > 0
        THEN
            V_COLUMN_NAME := TRIM(FN_SCM_SPLIT(P_COLUMN_NAME, 2, ':'));
        ELSE
            /* ComboColumn : column_name:value --2017.12.20 */
            V_COLUMN_NAME := TRIM(FN_SCM_SPLIT(V_CSV_TEXT_LIST, 1, ':'));
        END IF;

        V_CSV_TEXT_LIST := TRIM(FN_SCM_SPLIT(V_CSV_TEXT_LIST, 2, ':'));
    END IF;

    /* -------------------------------------------------------------------------- */
    IF V_LOGICAL_OPERATOR = '-'
    THEN
        V_I := 0;
        WHILE V_I <= 1000
        LOOP
            V_CONDTION_VALUE := TRIM(FN_SCM_SPLIT(V_CSV_TEXT_LIST, V_I, ','));
            IF V_CONDTION_VALUE IS NULL
            THEN
                EXIT;
            ELSE
                CONTINUE;

                V_COUNT := V_COUNT + 1;

                IF V_I > 1
                THEN
                    V_SQL_TEXT := V_SQL_TEXT || ',';
                END IF;

                V_SQL_TEXT := V_SQL_TEXT || '''' || V_CONDTION_VALUE || '''';
            END IF;
        END LOOP;
        RETURN V_SQL_TEXT;
    END IF;

    /* V_SQL_TEXT := '3333'; */

    /* -------------------------------------------------------------------------- */
    IF NVL(V_CSV_TEXT_LIST, 'ALL') = 'ALL'
    THEN
        V_SQL_TEXT := '';
    /* -------------------------------------------------------------------------- */
    ELSIF V_CSV_TEXT_LIST = ''
    THEN
        V_SQL_TEXT := '';
    ELSIF P_COLUMN_NAME IS NULL
    THEN
        V_SQL_TEXT := '';
    /* -------------------------------------------------------------------------- */

    /* V_COLUMN_NAME := SUBSTR(P_COLUMN_NAME,INSTR(P_COLUMN_NAME,'[')+1,INSTR(P_COLUMN_NAME,']')-INSTR(P_COLUMN_NAME,'[')-1); */
    /* V_SQL_TEXT    := REPLACE(P_COLUMN_NAME,'['||V_COLUMN_NAME||']',SCM_GET_WHERE_SQL_FUNC(V_COLUMN_NAME,V_LOGICAL_OPERATOR,V_CSV_TEXT_LIST)); */
    /* V_SQL_TEXT    := 'AND ' || REPLACE(V_SQL_TEXT,'*','%'); */
    /* -------------------------------------------------------------------------- */
    ELSIF V_LOGICAL_OPERATOR IN ('LK','LIKE')
    /* -------------------------------------------------------------------------- */
    THEN
        /* 값목록이 복수개로 입력되면 AND (  col LIKE v1 OR col LIKE v2 ) 로변환 */
        IF P_CSV_TEXT_LIST = ''
        THEN
            RETURN '';
        END IF;

        V_SQL_TEXT   := CHR(10) || ' AND ( ';
        V_LIST_COUNT := 1;
        WHILE V_LIST_COUNT <= 1000
        LOOP
            /* -[dbo].[SCM_ARR_SPL_CNT] */
	        /* 2026-08-21 V_UPPER_CSV_TEXT_LIST로 대문자리스트 사용 */
            V_CONDTION_VALUE := TRIM(FN_SCM_SPLIT(V_UPPER_CSV_TEXT_LIST, V_LIST_COUNT, ','));

            IF V_CONDTION_VALUE IS NULL
            THEN
                EXIT;
            ELSE
                V_COUNT    := V_COUNT + 1;
                V_SQL_TEXT := V_SQL_TEXT || V_COLUMN_NAME;

                IF SUBSTR(V_CONDTION_VALUE, 1, 1) = '!'
                THEN
                    V_CONDTION_VALUE := SUBSTR(V_CONDTION_VALUE, 2, 2 * LENGTH(V_CONDTION_VALUE) - 1);
                    V_SQL_TEXT := V_SQL_TEXT || ' NOT LIKE N' || '''%' || TRIM(V_CONDTION_VALUE) || '%'' OR ';
                ELSE
                    V_CONDTION_VALUE := SUBSTR(V_CONDTION_VALUE, 1, 2 * LENGTH(V_CONDTION_VALUE));
                    V_SQL_TEXT := V_SQL_TEXT || ' LIKE N' || '''%' || TRIM(V_CONDTION_VALUE) || '%'' OR ';
                END IF;

                V_LIST_COUNT := V_LIST_COUNT + 1;
            END IF;
        END LOOP;

        V_SQL_TEXT := SUBSTR(V_SQL_TEXT, 1, LENGTH(RTRIM(V_SQL_TEXT)) - 3) || ' ) ';

        /* 값목록이 한건밖에 없으면 바로 LIKE로만 처리 */
        /* 2026-08-21 V_UPPER_CSV_TEXT_LIST로 대문자리스트 사용 */
        IF V_COUNT = 1
        THEN
            IF SUBSTR(V_UPPER_CSV_TEXT_LIST, 1, 1) = '!'
            THEN
                V_SQL_TEXT := CHR(10) || ' AND ' || V_COLUMN_NAME || ' NOT LIKE N' || '''%' || TRIM(SUBSTR(V_UPPER_CSV_TEXT_LIST, 1, 2)) || '%'' ';
            ELSE
                V_SQL_TEXT := CHR(10) || ' AND ' || V_COLUMN_NAME || ' LIKE N' || '''%' || TRIM(V_UPPER_CSV_TEXT_LIST) || '%'' ';
            END IF;
        END IF;

        /* 사용자가 * 로 WildCard입력시 %로 변환 */
        V_SQL_TEXT := REPLACE(V_SQL_TEXT, '*', '%');

    /* -------------------------------------------------------------------------- */
    ELSIF V_LOGICAL_OPERATOR IN ('NL','NOT LIKE')  /* NOT LIKE */
    /* -------------------------------------------------------------------------- */
    THEN
        /* 값목록이 복수개로 입력되면 AND (  col NOT LIKE v1 OR col NOT LIKE v2 ) 로변환 */
        IF P_CSV_TEXT_LIST = ''
        THEN
            RETURN '';
        END IF;

        V_SQL_TEXT   := CHR(10) || ' AND ( ';
        V_LIST_COUNT := 1;
        WHILE V_LIST_COUNT <= 1000
        LOOP
            /* -[dbo].[SCM_ARR_SPL_CNT] */
            V_CONDTION_VALUE := TRIM(FN_SCM_SPLIT(V_CSV_TEXT_LIST, V_LIST_COUNT, ','));

            IF V_CONDTION_VALUE IS NULL
            THEN
                EXIT;
            ELSE
                V_COUNT    := V_COUNT + 1;
                V_SQL_TEXT := V_SQL_TEXT || V_COLUMN_NAME;

                V_CONDTION_VALUE := SUBSTR(V_CONDTION_VALUE, 1, 2 * LENGTH(V_CONDTION_VALUE));
                V_SQL_TEXT := V_SQL_TEXT || ' NOT LIKE N' || '''%' || TRIM(V_CONDTION_VALUE) || '%'' OR ';

                V_LIST_COUNT := V_LIST_COUNT + 1;
            END IF;
        END LOOP;

        V_SQL_TEXT := SUBSTR(V_SQL_TEXT, 1, LENGTH(RTRIM(V_SQL_TEXT)) - 3) || ' ) ';

        /* 값목록이 한건밖에 없으면 바로 NOT LIKE로만 처리 */
        IF V_COUNT = 1
        THEN
            V_SQL_TEXT := CHR(10) || ' AND ' || P_COLUMN_NAME || ' NOT LIKE N' || '''%' || TRIM(V_CSV_TEXT_LIST) || '%'' ';
        END IF;

        /* 사용자가 * 로 WildCard입력시 %로 변환 */
        V_SQL_TEXT := REPLACE(V_SQL_TEXT, '*', '%');

    /* -------------------------------------------------------------------------- */
    ELSIF V_LOGICAL_OPERATOR IN ('EQ','EQUAL','IN')
    /* -------------------------------------------------------------------------- */
    THEN
        /* 값목록이 복수개로 입력되면 IN ( v1, v2 , v3, v4 ) 로변환 */
        IF SUBSTR(V_CSV_TEXT_LIST, 1, 1) = '!'
        THEN
            V_SQL_TEXT := CHR(10) || ' AND ' || V_COLUMN_NAME || ' NOT IN (';
        ELSE
            V_SQL_TEXT := CHR(10) || ' AND ' || V_COLUMN_NAME || ' IN (';
        END IF;

        V_I := 1;
        WHILE V_I <= 1000
        LOOP
            V_CONDTION_VALUE := TRIM(FN_SCM_SPLIT(REPLACE(V_CSV_TEXT_LIST, '!', ''), V_I, ','));
            IF V_CONDTION_VALUE IS NULL
            THEN
                EXIT;
            ELSE
                V_COUNT    := V_COUNT + 1;
                V_SQL_TEXT := V_SQL_TEXT || 'N''' || V_CONDTION_VALUE || ''',';
                V_I := V_I + 1;
            END IF;
        END LOOP;

        V_SQL_TEXT := SUBSTR(V_SQL_TEXT, 1, LENGTH(RTRIM(V_SQL_TEXT)) - 1) || ') ';
        RETURN V_SQL_TEXT;
        /* 원본 quirk: 위 RETURN(원본 SCMPROD의 활성 return @v_sql_text)으로 아래 단건 EQUAL 처리 도달불가 그대로 보존 */
        /* 값목록이 한건밖에 없으면 바로 EQUAL 로만 처리 */
        V_CSV_TEXT_LIST := TRIM(REPLACE(V_CSV_TEXT_LIST, '*', '%'));
        IF V_COUNT = 1
        THEN
            IF SUBSTR(V_CSV_TEXT_LIST, 1, 1) = '!'
            THEN
                IF SUBSTR(V_CSV_TEXT_LIST, -1, 1) = '%'
                THEN
                    V_SQL_TEXT := CHR(10) || ' AND ' || V_COLUMN_NAME || ' NOT LIKE N' || '''%' || TRIM(SUBSTR(V_CSV_TEXT_LIST, 1, 2)) || '%'' ';
                ELSE
                    V_SQL_TEXT := CHR(10) || ' AND ' || V_COLUMN_NAME || ' != N' || '''' || TRIM(SUBSTR(V_CSV_TEXT_LIST, 1, 2)) || ''' ';
                END IF;
            ELSE
                IF SUBSTR(V_CSV_TEXT_LIST, -1, 1) = '%'
                THEN
                    V_SQL_TEXT := CHR(10) || ' AND ' || V_COLUMN_NAME || ' LIKE N' || '''%' || TRIM(V_CSV_TEXT_LIST) || '%'' ';
                ELSE
                    V_SQL_TEXT := CHR(10) || ' AND ' || V_COLUMN_NAME || ' = N' || '''' || TRIM(V_CSV_TEXT_LIST) || ''' ';
                END IF;
            END IF;
        END IF;

    /* -------------------------------------------------------------------------- */
    ELSIF V_LOGICAL_OPERATOR IN ('NE','NOT EQUAL','NI','NOT IN')
    /* -------------------------------------------------------------------------- */
    THEN
        /* 값목록이 복수개로 입력되면 NOT IN ( v1, v2 , v3, v4 ) 로변환 */
        V_SQL_TEXT := CHR(10) || ' AND ' || P_COLUMN_NAME || ' NOT IN (';
        V_I := 1;
        WHILE V_I <= 1000
        LOOP
            V_CONDTION_VALUE := TRIM(FN_SCM_SPLIT(V_CSV_TEXT_LIST, V_I, ','));
            IF V_CONDTION_VALUE IS NULL
            THEN
                EXIT;
            ELSE
                V_COUNT    := V_COUNT + 1;
                V_SQL_TEXT := V_SQL_TEXT || 'N''' || V_CONDTION_VALUE || ''',';
                V_I := V_I + 1;
            END IF;
        END LOOP;
        /* 값목록이 한건밖에 없으면 바로 NOT EQUAL 로만 처리 */
        /* 원본 DATALENGTH(@v_sql_text)-1 = 2*LENGTH-1 (NVARCHAR 바이트수) 그대로 보존 */
        V_SQL_TEXT := SUBSTR(V_SQL_TEXT, 1, 2 * LENGTH(V_SQL_TEXT) - 1) || ') ';
        IF V_COUNT = 1
        THEN
            V_SQL_TEXT := CHR(10) || ' AND ' || P_COLUMN_NAME || ' != N' || '''' || TRIM(V_CSV_TEXT_LIST) || ''' ';
        END IF;

    /* -------------------------------------------------------------------------- */
    ELSIF V_LOGICAL_OPERATOR IN ('BW','BETWEEN')
    /* -------------------------------------------------------------------------- */
    THEN
        /* 값목록이 복수개로 입력되면 AND (  col LIKE v1 OR col LIKE v2 ) 로변환 */
        V_SQL_TEXT := CHR(10) || ' AND ( ';
        V_I := 1;
        WHILE V_I <= 1000
        LOOP
            V_CONDTION_VALUE := TRIM(FN_SCM_SPLIT(V_CSV_TEXT_LIST, V_I, ','));
            IF V_CONDTION_VALUE IS NULL
            THEN
                EXIT;
            ELSE
                V_COUNT    := V_COUNT + 1;
                V_1ST_NODE := TRIM(FN_SCM_SPLIT(V_CONDTION_VALUE, 1, ':'));
                V_2ND_NODE := TRIM(FN_SCM_SPLIT(V_CONDTION_VALUE, 2, ':'));
                V_SQL_TEXT := V_SQL_TEXT || ' ( ' || P_COLUMN_NAME || ' BETWEEN ''' || V_1ST_NODE
                                         || ''' AND ''' || NVL(V_2ND_NODE, V_1ST_NODE)
                                         || ''' ) OR ';
                V_I := V_I + 1;
            END IF;
        END LOOP;

        V_SQL_TEXT := SUBSTR(V_SQL_TEXT, 1, LENGTH(RTRIM(V_SQL_TEXT)) - 3) || ' ) ';
        /* 값목록이 한건밖에 없으면 바로 LIKE로만 처리 */
        IF V_COUNT = 1
        THEN

            V_1ST_NODE := TRIM(FN_SCM_SPLIT(V_CSV_TEXT_LIST, ':', 1));
            V_2ND_NODE := TRIM(FN_SCM_SPLIT(V_CSV_TEXT_LIST, ':', 2));
            V_SQL_TEXT := CHR(10) || ' AND ' || P_COLUMN_NAME || ' BETWEEN ''' || V_1ST_NODE
                                   || ''' AND ''' || NVL(V_2ND_NODE, V_1ST_NODE)
                                   || ''' ';
        END IF;

    /* -------------------------------------------------------------------------- */
    ELSIF V_LOGICAL_OPERATOR IN ('BD','BETWEEN DATE')
    /* -------------------------------------------------------------------------- */
    THEN
        /* 값목록이 복수개로 입력되면 AND (  col LIKE v1 OR col LIKE v2 ) 로변환 */

        V_SQL_TEXT := CHR(10) || ' AND ( ';
        WHILE V_I <= 1000
        LOOP
            V_CONDTION_VALUE := TRIM(FN_SCM_SPLIT(V_CSV_TEXT_LIST, ',', V_I));
            IF V_CONDTION_VALUE IS NULL
            THEN
                EXIT;
            ELSE
                V_COUNT    := V_COUNT + 1;
                V_1ST_NODE := TRIM(FN_SCM_SPLIT(V_CONDTION_VALUE, 1, ':'));
                V_2ND_NODE := TRIM(FN_SCM_SPLIT(V_CONDTION_VALUE, 2, ':'));
                V_SQL_TEXT := V_SQL_TEXT || ' ( ' || P_COLUMN_NAME || ' BETWEEN CONVERT(CHAR(8)''' || V_1ST_NODE || ''',112) '
                                         || ' AND     CONVERT(CHAR(8)''' || NVL(V_2ND_NODE, V_1ST_NODE) || ''',112) + 86399/86400 '
                                         || ') OR ';
            END IF;
        END LOOP;
        V_SQL_TEXT := SUBSTR(V_SQL_TEXT, 1, 2 * LENGTH(V_SQL_TEXT) - 3) || ' ) ';
        /* 값목록이 한건밖에 없으면 바로 LIKE로만 처리 */
        IF V_COUNT = 1
        THEN
            V_1ST_NODE := TRIM(FN_SCM_SPLIT(V_CSV_TEXT_LIST, 1, ':'));
            V_2ND_NODE := TRIM(FN_SCM_SPLIT(V_CSV_TEXT_LIST, 2, ':'));
            V_SQL_TEXT := CHR(10) || ' AND ' || P_COLUMN_NAME || ' BETWEEN CONVERT(CHAR(8)''' || V_1ST_NODE || ''',''YYYYMMDD'') '
                                   || ' AND CONVERT(CHAR(8)''' || NVL(V_2ND_NODE, V_1ST_NODE) || ''',''YYYYMMDD'') + 86399/86400';
        END IF;

    /* -------------------------------------------------------------------------- */
    ELSIF V_LOGICAL_OPERATOR IN ('BM','BETWEEN MONTH')
    /* -------------------------------------------------------------------------- */
    THEN
        /* 값목록이 복수개로 입력되면 AND (  col LIKE v1 OR col LIKE v2 ) 로변환 */

        V_SQL_TEXT := CHR(10) || ' AND ( ';
        WHILE V_I <= 1000
        LOOP
            V_CONDTION_VALUE := TRIM(FN_SCM_SPLIT(V_CSV_TEXT_LIST, V_I, ','));
            IF V_CONDTION_VALUE IS NULL
            THEN
                EXIT;
            ELSE
                V_COUNT    := V_COUNT + 1;
                V_1ST_NODE := TRIM(FN_SCM_SPLIT(V_CONDTION_VALUE, 1, ':'));
                V_2ND_NODE := TRIM(FN_SCM_SPLIT(V_CONDTION_VALUE, 2, ':'));
                V_SQL_TEXT := V_SQL_TEXT || ' ( ' || P_COLUMN_NAME || ' BETWEEN CONVERT(CHAR(6)''' || V_1ST_NODE || ''',112) '
                                         || ' AND CONVERT(CHAR(6), DATEADD(MM, 1,''' || NVL(V_2ND_NODE, V_1ST_NODE) || ''',112),1) - 1/86400 '
                                         || ') OR ';
            END IF;
        END LOOP;

        V_SQL_TEXT := SUBSTR(V_SQL_TEXT, 1, 2 * LENGTH(V_SQL_TEXT) - 3) || ' ) ';
        /* 값목록이 한건밖에 없으면 바로 LIKE로만 처리 */
        IF V_COUNT = 1
        THEN
            V_1ST_NODE := TRIM(FN_SCM_SPLIT(V_CSV_TEXT_LIST, 1, ':'));
            V_2ND_NODE := TRIM(FN_SCM_SPLIT(V_CSV_TEXT_LIST, 2, ':'));
            V_SQL_TEXT := CHR(10) || ' AND ' || P_COLUMN_NAME || ' BETWEEN TO_DATE(''' || V_1ST_NODE || ''',112) '
                                   || ' AND ADD_MONTHS(TO_DATE(''' || NVL(V_2ND_NODE, V_1ST_NODE) || ''',112),1) - 1/86400 ';
        END IF;

    /* -------------------------------------------------------------------------- */
    ELSIF V_LOGICAL_OPERATOR = 'GT'
    /* -------------------------------------------------------------------------- */
    THEN
        V_SQL_TEXT := CHR(10) || ' AND ' || P_COLUMN_NAME || ' > ''' || TRIM(V_CSV_TEXT_LIST) || ''' ';
    /* -------------------------------------------------------------------------- */
    ELSIF V_LOGICAL_OPERATOR = 'GE'
    /* -------------------------------------------------------------------------- */
    THEN
        V_SQL_TEXT := CHR(10) || ' AND ' || P_COLUMN_NAME || ' >= ''' || TRIM(V_CSV_TEXT_LIST) || ''' ';
    /* -------------------------------------------------------------------------- */
    ELSIF V_LOGICAL_OPERATOR = 'LT'
    /* -------------------------------------------------------------------------- */
    THEN
        V_SQL_TEXT := CHR(10) || ' AND ' || P_COLUMN_NAME || ' < ''' || TRIM(V_CSV_TEXT_LIST) || ''' ';
    /* -------------------------------------------------------------------------- */
    ELSIF V_LOGICAL_OPERATOR = 'LE'
    /* -------------------------------------------------------------------------- */
    THEN
        V_SQL_TEXT := CHR(10) || ' AND ' || P_COLUMN_NAME || ' <= ''' || TRIM(V_CSV_TEXT_LIST) || ''' ';
    /* -------------------------------------------------------------------------- */
    ELSIF V_LOGICAL_OPERATOR = 'CK'   /* CheckBox for Y Only */
    /* -------------------------------------------------------------------------- */
    THEN
        IF TRIM(V_CSV_TEXT_LIST) = 'Y'
        THEN
            V_SQL_TEXT := CHR(10) || ' AND ' || P_COLUMN_NAME || ' = ''Y'' ';
        END IF;
    /* -------------------------------------------------------------------------- */
    ELSE
    /* -------------------------------------------------------------------------- */
        V_SQL_TEXT := CHR(10) || ' AND ' || P_COLUMN_NAME || ' LIKE ''%' || TRIM(V_CSV_TEXT_LIST) || '%'' ';
        /* 사용자가 * 로 WildCard입력시 %로 변환 */
        V_SQL_TEXT := REPLACE(V_SQL_TEXT, '*', '%');
    END IF;

    /* -------------------------------------------------------------------------- */
    RETURN V_SQL_TEXT;
    /* -------------------------------------------------------------------------- */

END;

FUNCTION           "FN_SCM_GET_WHERE_SQL2" 
(
    p_column_name           IN VARCHAR2,
    p_logical_operator_code IN VARCHAR2,
    p_csv_text_list         IN VARCHAR2
)
RETURN VARCHAR2
/*
 * Program ID   : FN_SCM_GET_WHERE_SQL                                                             
 * Description  :
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2017/12/20  SongDH       Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트 
 * 2026-03-06   jcnam          [PJ20264226] NextSCM Pilot 설계 및 개발
 *                                                                                                  
*/
IS
    v_csv_text_list    VARCHAR2(32767 CHAR);
    v_logical_operator VARCHAR2(100 CHAR);
    v_condtion_value   VARCHAR2(100 CHAR);
    v_column_name      VARCHAR2(1000 CHAR);
    v_sql_text         VARCHAR2(32767 CHAR);
    v_count            PLS_INTEGER := 0;
    v_list_count       PLS_INTEGER := 0;
    v_1st_node         VARCHAR2(4000 CHAR);
    v_2nd_node         VARCHAR2(4000 CHAR);
    v_i                PLS_INTEGER := 0;

BEGIN

    v_csv_text_list    := REPLACE(REPLACE(p_csv_text_list, CHR(13), ''), CHR(10), ',');
    v_logical_operator := NVL(UPPER(p_logical_operator_code), 'LK');
    v_column_name      := TRIM(FN_SCM_SPLIT(p_column_name, 1, ':'));
    v_sql_text         := '';
    v_list_count       := 0;

    ----------------------------------------------------------------------------
    -- CheckedListFilter : (!)value1,valu2...(:LK) 
    -- MonthRangePicker, DateRangePicker : '20171201:20171231' 형식이므로 제외
    -- ComboColumn : column_name:value
    ----------------------------------------------------------------------------

    IF INSTR(v_csv_text_list, ':') > 0
       AND v_logical_operator NOT IN ('BW','BETWEEN','BD','BETWEN DATE','BM','BETWEEN MONTH')
    THEN
        IF TRIM(FN_SCM_SPLIT(v_csv_text_list, 2, ':')) = 'LK' THEN
            -- CheckedListFilter : Like 검색
            v_logical_operator := TRIM(FN_SCM_SPLIT(v_csv_text_list, 2, ':'));
            v_csv_text_list    := TRIM(FN_SCM_SPLIT(v_csv_text_list, 1, ':'));

            -- CheckedListFilter : 'end_customer_code:end_customer_name'
            IF INSTR(p_column_name, ':') > 0 THEN
                v_column_name := TRIM(FN_SCM_SPLIT(p_column_name, 2, ':'));
            END IF;
        ELSE
            -- ComboColumn : column_name:value --2017.12.20
            v_column_name   := TRIM(FN_SCM_SPLIT(v_csv_text_list, 1, ':'));
            v_csv_text_list := TRIM(FN_SCM_SPLIT(v_csv_text_list, 2, ':'));
        END IF;
    END IF;

    ----------------------------------------------------------------------------

    IF v_logical_operator = '-' THEN
        v_i := 0;
        WHILE v_i <= 1000 LOOP
            v_condtion_value := TRIM(FN_SCM_SPLIT(v_csv_text_list, v_i, ','));
            IF v_condtion_value IS NULL THEN
                EXIT;
            ELSE
                v_count := v_count + 1;
                IF v_i > 1 THEN
                    v_sql_text := v_sql_text || ',';
                END IF;
                v_sql_text := v_sql_text || '''' || v_condtion_value || '''';
                v_i := v_i + 1;
            END IF;
        END LOOP;
        RETURN v_sql_text;

    ----------------------------------------------------------------------------
    ELSIF NVL(v_csv_text_list, 'ALL') = 'ALL' THEN
        v_sql_text := '';
    ----------------------------------------------------------------------------
    ELSIF v_csv_text_list = '' THEN
        v_sql_text := '';
    ELSIF p_column_name IS NULL THEN
        v_sql_text := '';
    ----------------------------------------------------------------------------
    ELSIF v_logical_operator IN ('LK','LIKE') THEN
    ----------------------------------------------------------------------------
        -- 값목록이 복수개로 입력되면 AND (  col LIKE v1 OR col LIKE v2 ) 로변환
        IF p_csv_text_list = '' THEN
            RETURN '';
        END IF;

        v_sql_text   := CHR(10) || ' AND ( ';
        v_list_count := 1;

        WHILE v_list_count <= 1000 LOOP
            v_condtion_value := TRIM(FN_SCM_SPLIT(v_csv_text_list, v_list_count, ','));

            IF v_condtion_value IS NULL THEN
                EXIT;
            ELSE
                v_count    := v_count + 1;
                v_sql_text := v_sql_text || v_column_name;

                IF SUBSTR(v_condtion_value, 1, 1) = '!' THEN
                    v_condtion_value := SUBSTR(v_condtion_value, 2, LENGTHB(v_condtion_value) - 1);
                    v_sql_text := v_sql_text || ' NOT LIKE''%' || TRIM(v_condtion_value) || '%'' OR ';
                ELSE
                    v_condtion_value := SUBSTR(v_condtion_value, 1, LENGTHB(v_condtion_value));
                    v_sql_text := v_sql_text || ' LIKE ''%' || TRIM(v_condtion_value) || '%'' OR ';
                END IF;

                v_list_count := v_list_count + 1;
            END IF;
        END LOOP;

        v_sql_text := SUBSTR(v_sql_text, 1, LENGTH(RTRIM(v_sql_text)) - 3) || ' ) ';

        -- 값목록이 한건밖에 없으면 바로 LIKE로만 처리
        IF v_count = 1 THEN
            IF SUBSTR(v_csv_text_list, 1, 1) = '!' THEN
                v_sql_text := CHR(10) || ' AND ' || v_column_name || ' NOT LIKE ''%' || TRIM(SUBSTR(v_csv_text_list, 2)) || '%'' ';
            ELSE
                v_sql_text := CHR(10) || ' AND ' || v_column_name || ' LIKE ''%' || TRIM(v_csv_text_list) || '%'' ';
            END IF;
        END IF;

        -- 사용자가 * 로 WildCard입력시 %로 변환
        v_sql_text := REPLACE(v_sql_text, '*', '%');

    ----------------------------------------------------------------------------
    ELSIF v_logical_operator IN ('NL','NOT LIKE') THEN
    ----------------------------------------------------------------------------
        -- 값목록이 복수개로 입력되면 AND (  col NOT LIKE v1 OR col NOT LIKE v2 ) 로변환
        IF p_csv_text_list = '' THEN
            RETURN '';
        END IF;

        v_sql_text   := CHR(10) || ' AND ( ';
        v_list_count := 1;

        WHILE v_list_count <= 1000 LOOP
            v_condtion_value := TRIM(FN_SCM_SPLIT('N' || v_csv_text_list, v_list_count, ','));

            IF v_condtion_value IS NULL THEN
                EXIT;
            ELSE
                v_count          := v_count + 1;
                v_sql_text       := v_sql_text || v_column_name;
                v_condtion_value := SUBSTR(v_condtion_value, 1, LENGTHB(v_condtion_value));
                v_sql_text       := v_sql_text || ' NOT LIKE ''%' || TRIM(v_condtion_value) || '%'' OR ';
                v_list_count     := v_list_count + 1;
            END IF;
        END LOOP;

        v_sql_text := SUBSTR(v_sql_text, 1, LENGTH(v_sql_text) - 3) || ' ) ';

        -- 값목록이 한건밖에 없으면 바로 NOT LIKE로만 처리
        IF v_count = 1 THEN
            v_sql_text := CHR(10) || ' AND ' || p_column_name || ' NOT LIKE ''%' || TRIM(v_csv_text_list) || '%'' ';
        END IF;

        -- 사용자가 * 로 WildCard입력시 %로 변환
        v_sql_text := REPLACE(v_sql_text, '*', '%');

    ----------------------------------------------------------------------------
    ELSIF v_logical_operator IN ('EQ','EQUAL','IN') THEN
    ----------------------------------------------------------------------------
        -- 값목록이 복수개로 입력되면 IN ( v1, v2 , v3, v4 ) 로변환
        IF SUBSTR(v_csv_text_list, 1, 1) = '!' THEN
            v_sql_text := CHR(10) || ' AND ' || v_column_name || ' NOT IN (';
        ELSE
            v_sql_text := CHR(10) || ' AND ' || v_column_name || ' IN (';
        END IF;

        v_i := 1;
        WHILE v_i <= 1000 LOOP
            v_condtion_value := TRIM(FN_SCM_SPLIT(REPLACE(v_csv_text_list, '!', ''), v_i, ','));
            IF v_condtion_value IS NULL THEN
                EXIT;
            ELSE
                v_count    := v_count + 1;
                v_sql_text := v_sql_text || '''' || v_condtion_value || ''',';
                v_i        := v_i + 1;
            END IF;
        END LOOP;

        v_sql_text := SUBSTR(v_sql_text, 1, LENGTH(v_sql_text) - 1) || ') ';
        RETURN v_sql_text;

        -- 값목록이 한건밖에 없으면 바로 EQUAL 로만 처리
        -- ※ 원본 MSSQL에서 RETURN 이후 도달 불가 코드이나 원본 주석 구조 유지
        v_csv_text_list := TRIM(REPLACE(v_csv_text_list, '*', '%'));
        IF v_count = 1 THEN
            IF SUBSTR(v_csv_text_list, 1, 1) = '!' THEN
                IF SUBSTR(v_csv_text_list, -1, 1) = '%' THEN
                    v_sql_text := CHR(10) || ' AND ' || v_column_name || ' NOT LIKE ''' || TRIM(SUBSTR(v_csv_text_list, 2)) || ''' ';
                ELSE
                    v_sql_text := CHR(10) || ' AND ' || v_column_name || ' != ''' || TRIM(SUBSTR(v_csv_text_list, 2)) || ''' ';
                END IF;
            ELSE
                IF SUBSTR(v_csv_text_list, -1, 1) = '%' THEN
                    v_sql_text := CHR(10) || ' AND ' || v_column_name || ' LIKE ''' || TRIM(v_csv_text_list) || ''' ';
                ELSE
                    v_sql_text := CHR(10) || ' AND ' || v_column_name || ' = ''' || TRIM(v_csv_text_list) || ''' ';
                END IF;
            END IF;
        END IF;

    ----------------------------------------------------------------------------
    ELSIF v_logical_operator IN ('NE','NOT EQUAL','NI','NOT IN') THEN
    ----------------------------------------------------------------------------
        -- 값목록이 복수개로 입력되면 NOT IN ( v1, v2 , v3, v4 ) 로변환
        v_sql_text := CHR(10) || ' AND ' || p_column_name || ' NOT IN (';
        v_i := 1;
        WHILE v_i <= 1000 LOOP
            v_condtion_value := TRIM(FN_SCM_SPLIT(v_csv_text_list, v_i, ','));
            IF v_condtion_value IS NULL THEN
                EXIT;
            ELSE
                v_count    := v_count + 1;
                v_sql_text := v_sql_text || '''' || v_condtion_value || ''',';
                v_i        := v_i + 1;
            END IF;
        END LOOP;

        -- 값목록이 한건밖에 없으면 바로 NOT EQUAL 로만 처리
        v_sql_text := SUBSTR(v_sql_text, 1, LENGTHB(v_sql_text) - 1) || ') ';
        IF v_count = 1 THEN
            v_sql_text := CHR(10) || ' AND ' || p_column_name || ' != ''' || TRIM(v_csv_text_list) || ''' ';
        END IF;

    ----------------------------------------------------------------------------
    ELSIF v_logical_operator IN ('BW','BETWEEN') THEN
    ----------------------------------------------------------------------------
        -- 값목록이 복수개로 입력되면 AND (  col LIKE v1 OR col LIKE v2 ) 로변환
        v_sql_text := CHR(10) || ' AND ( ';
        v_i := 1;
        WHILE v_i <= 1000 LOOP
            v_condtion_value := TRIM(FN_SCM_SPLIT(v_csv_text_list, v_i, ','));
            IF v_condtion_value IS NULL THEN
                EXIT;
            ELSE
                v_count     := v_count + 1;
                v_1st_node  := TRIM(FN_SCM_SPLIT(v_condtion_value, 1, ':'));
                v_2nd_node  := TRIM(FN_SCM_SPLIT(v_condtion_value, 2, ':'));
                v_sql_text  := v_sql_text
                               || ' ( ' || p_column_name || ' BETWEEN ''' || v_1st_node
                               || ''' AND ''' || NVL(v_2nd_node, v_1st_node)
                               || ''' ) OR ';
                v_i := v_i + 1;
            END IF;
        END LOOP;

        v_sql_text := SUBSTR(v_sql_text, 1, LENGTH(v_sql_text) - 3) || ' ) ';

        -- 값목록이 한건밖에 없으면 바로 LIKE로만 처리
        IF v_count = 1 THEN
            v_1st_node := TRIM(FN_SCM_SPLIT(v_csv_text_list, 1, ':'));
            v_2nd_node := TRIM(FN_SCM_SPLIT(v_csv_text_list, 2, ':'));
            v_sql_text := CHR(10) || ' AND ' || p_column_name || ' BETWEEN ''' || v_1st_node
                          || ''' AND ''' || NVL(v_2nd_node, v_1st_node) || ''' ';
        END IF;

    ----------------------------------------------------------------------------
    ELSIF v_logical_operator IN ('BD','BETWEEN DATE') THEN
    ----------------------------------------------------------------------------
        -- 값목록이 복수개로 입력되면 AND (  col LIKE v1 OR col LIKE v2 ) 로변환
        v_sql_text := CHR(10) || ' AND ( ';
        WHILE v_i <= 1000 LOOP
            v_condtion_value := TRIM(FN_SCM_SPLIT(v_csv_text_list, v_i, ','));
            IF v_condtion_value IS NULL THEN
                EXIT;
            ELSE
                v_count    := v_count + 1;
                v_1st_node := TRIM(FN_SCM_SPLIT(v_condtion_value, 1, ':'));
                v_2nd_node := TRIM(FN_SCM_SPLIT(v_condtion_value, 2, ':'));
                v_sql_text := v_sql_text
                              || ' ( ' || p_column_name
                              || ' BETWEEN TO_DATE(''' || v_1st_node || ''',''YYYYMMDD'') '
                              || ' AND     TO_DATE(''' || NVL(v_2nd_node, v_1st_node) || ''',''YYYYMMDD'') + 86399/86400 '
                              || ') OR ';
                v_i := v_i + 1;
            END IF;
        END LOOP;

        v_sql_text := SUBSTR(v_sql_text, 1, LENGTHB(v_sql_text) - 3) || ' ) ';

        -- 값목록이 한건밖에 없으면 바로 LIKE로만 처리
        IF v_count = 1 THEN
            v_1st_node := TRIM(FN_SCM_SPLIT(v_csv_text_list, 1, ':'));
            v_2nd_node := TRIM(FN_SCM_SPLIT(v_csv_text_list, 2, ':'));
            v_sql_text := CHR(10) || ' AND ' || p_column_name
                          || ' BETWEEN TO_DATE(''' || v_1st_node || ''',''YYYYMMDD'') '
                          || ' AND TO_DATE(''' || NVL(v_2nd_node, v_1st_node) || ''',''YYYYMMDD'') + 86399/86400';
        END IF;

    ----------------------------------------------------------------------------
    ELSIF v_logical_operator IN ('BM','BETWEEN MONTH') THEN
    ----------------------------------------------------------------------------
        -- 값목록이 복수개로 입력되면 AND (  col LIKE v1 OR col LIKE v2 ) 로변환
        v_sql_text := CHR(10) || ' AND ( ';
        WHILE v_i <= 1000 LOOP
            v_condtion_value := TRIM(FN_SCM_SPLIT(v_csv_text_list, v_i, ','));
            IF v_condtion_value IS NULL THEN
                EXIT;
            ELSE
                v_count    := v_count + 1;
                v_1st_node := TRIM(FN_SCM_SPLIT(v_condtion_value, 1, ':'));
                v_2nd_node := TRIM(FN_SCM_SPLIT(v_condtion_value, 2, ':'));
                v_sql_text := v_sql_text
                              || ' ( ' || p_column_name
                              || ' BETWEEN TO_DATE(''' || v_1st_node || ''',''YYYYMMDD'') '
                              || ' AND ADD_MONTHS(TO_DATE(''' || NVL(v_2nd_node, v_1st_node) || ''',''YYYYMMDD''),1) - 1/86400 '
                              || ') OR ';
                v_i := v_i + 1;
            END IF;
        END LOOP;

        v_sql_text := SUBSTR(v_sql_text, 1, LENGTHB(v_sql_text) - 3) || ' ) ';

        -- 값목록이 한건밖에 없으면 바로 LIKE로만 처리
        IF v_count = 1 THEN
            v_1st_node := TRIM(FN_SCM_SPLIT(v_csv_text_list, 1, ':'));
            v_2nd_node := TRIM(FN_SCM_SPLIT(v_csv_text_list, 2, ':'));
            v_sql_text := CHR(10) || ' AND ' || p_column_name
                          || ' BETWEEN TO_DATE(''' || v_1st_node || ''',''YYYYMMDD'') '
                          || ' AND ADD_MONTHS(TO_DATE(''' || NVL(v_2nd_node, v_1st_node) || ''',''YYYYMMDD''),1) - 1/86400 ';
        END IF;

    ----------------------------------------------------------------------------
    ELSIF v_logical_operator = 'GT' THEN
    ----------------------------------------------------------------------------
        v_sql_text := CHR(10) || ' AND ' || p_column_name || ' > ''' || TRIM(v_csv_text_list) || ''' ';
    ----------------------------------------------------------------------------
    ELSIF v_logical_operator = 'GE' THEN
    ----------------------------------------------------------------------------
        v_sql_text := CHR(10) || ' AND ' || p_column_name || ' >= ''' || TRIM(v_csv_text_list) || ''' ';
    ----------------------------------------------------------------------------
    ELSIF v_logical_operator = 'LT' THEN
    ----------------------------------------------------------------------------
        v_sql_text := CHR(10) || ' AND ' || p_column_name || ' < ''' || TRIM(v_csv_text_list) || ''' ';
    ----------------------------------------------------------------------------
    ELSIF v_logical_operator = 'LE' THEN
    ----------------------------------------------------------------------------
        v_sql_text := CHR(10) || ' AND ' || p_column_name || ' <= ''' || TRIM(v_csv_text_list) || ''' ';
    ----------------------------------------------------------------------------
    ELSIF v_logical_operator = 'CK' THEN   -- CheckBox for Y Only
    ----------------------------------------------------------------------------
        IF TRIM(v_csv_text_list) = 'Y' THEN
            v_sql_text := CHR(10) || ' AND ' || p_column_name || ' = ''Y'' ';
        END IF;
    ----------------------------------------------------------------------------
    ELSE
    ----------------------------------------------------------------------------
        v_sql_text := CHR(10) || ' AND ' || p_column_name || ' LIKE ''%' || TRIM(v_csv_text_list) || '%'' ';
        -- 사용자가 * 로 WildCard입력시 %로 변환
        v_sql_text := REPLACE(v_sql_text, '*', '%');
    END IF;

    ----------------------------------------------------------------------------
    RETURN v_sql_text;
    ----------------------------------------------------------------------------

END FN_SCM_GET_WHERE_SQL2;

FUNCTION           "FN_SCM_SPLIT" 

(
    P_INPUT_DATA IN VARCHAR2
  , P_NODE_NO    IN NUMBER
  , P_DELIMITER  IN VARCHAR2 DEFAULT ','
) RETURN VARCHAR2
/*
 * Program ID   : FN_SCM_SPLIT
 * Description  :
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2024.12.26  vardadbi       Initial Release NERP 구축 프로젝트
 * 2026.03.06   kimcd        [PJ20264226] NextSCM Pilot 설계 및 개발
 *
 * 2026.07.06	ZIONEX		[PJ202650304] NextSCM Migration
*/
IS
    V_INPUT_LENGTH  NUMBER := 0;
    V_SPLIT_LENGTH  NUMBER := 0;
    V_START_LENGTH  NUMBER := 1;
    V_LAST_LENGTH   NUMBER := 1;
    V_RETURN        VARCHAR2(32767 CHAR);
    V_DELIMITER     VARCHAR2(100 CHAR);
    V_I             NUMBER := 1;
    V_TEMP_POS      NUMBER;
BEGIN

    IF (P_DELIMITER IS NULL OR P_DELIMITER = '') THEN
        V_DELIMITER := ',';
    ELSE
        V_DELIMITER := P_DELIMITER;
    END IF;

    V_INPUT_LENGTH := LENGTHB(P_INPUT_DATA);
    V_SPLIT_LENGTH := LENGTH(V_DELIMITER);


    IF (V_INPUT_LENGTH = 0 OR P_INPUT_DATA IS NULL) THEN
        RETURN NULL;
    END IF;


    IF (P_NODE_NO = 1) THEN
        V_START_LENGTH := 1;
    ELSE

        IF INSTR(P_INPUT_DATA, V_DELIMITER, 1) = 0 THEN
            RETURN NULL;
        END IF;

        V_START_LENGTH := 1;
        V_I := 1;


        WHILE (V_I < P_NODE_NO) LOOP
            V_TEMP_POS := INSTR(P_INPUT_DATA, V_DELIMITER, V_START_LENGTH);

            IF V_TEMP_POS = 0 THEN
                RETURN NULL;
            END IF;

            V_START_LENGTH := V_TEMP_POS + V_SPLIT_LENGTH;
            V_I := V_I + 1;
        END LOOP;
    END IF;


    V_LAST_LENGTH := INSTR(P_INPUT_DATA, V_DELIMITER, V_START_LENGTH);


    IF (V_LAST_LENGTH = 0) THEN
        V_LAST_LENGTH := V_INPUT_LENGTH + 1;
    END IF;


    V_RETURN := SUBSTR(P_INPUT_DATA, V_START_LENGTH, V_LAST_LENGTH - V_START_LENGTH);

    RETURN V_RETURN;

EXCEPTION
    WHEN OTHERS THEN
        RETURN NULL;
END FN_SCM_SPLIT;

FUNCTION FN_SCP0104_GET_SPREAD_TITLE
(
    P_FROM_YYYYMM   IN VARCHAR2
  , P_PROGRAM_ID    IN VARCHAR2
  , P_SHEET_NAME    IN VARCHAR2
)
RETURN T_FN_SCP0104_SPREAD_TITLE_TAB PIPELINED
/* ============================================================
 * Program ID   : FN_SCP0104_GET_SPREAD_TITLE
 * Description  : CAPA NEW 날짜 타이틀 리턴 (SCP0104, SCP0105, SCP0106, SCP0107, SCP0108 공통)
 * Program History
 *------------------------------------------------------------
 * Date          In Charge      Description
 *------------------------------------------------------------
 * 2023/10/12    chaan          V1.1.1  PJ20230692  SCM 역량 강화 위한 SCP 개선과제 이행 Phase2  - Initial Release
 * 2024/12/09    chaan          V1.1.8  PJ20230692  Pre 버전 예외처리
 * 2025/02/09    mrchois        V1.1.8  PJ20249346  (scp0106 Loss Plan UI 수정) Improvement Rate 입력 영역을 제거하고
 *                                                  Operation Plan 에 Goal 직접 입력 형태로 수정
 * 2026.09.27    ZIONEX         [PJ202650304] MSSQL -> Oracle 전환
 * ============================================================ */
IS

    V_SHEET_NAME        VARCHAR2(100 CHAR) := REPLACE(REPLACE(P_SHEET_NAME, '_ASSEMBLY', ''), '_ELTR', '');

    V_FROM_YYYY         VARCHAR2(4 CHAR)   := SUBSTR(P_FROM_YYYYMM, 1, 4);
    /* SCP0106_GET_CAPA_LOSS_PLAN 은 앞에 2개년도를 월별로 추가 */
    V_TO_YYYY_SCP0106   VARCHAR2(4 CHAR)   := TO_CHAR(TO_NUMBER(SUBSTR(P_FROM_YYYYMM, 1, 4)) + 1);
    /* 처음 3년은 월별 */
    V_TO_YYYY_MONTHLY   VARCHAR2(4 CHAR)   := TO_CHAR(TO_NUMBER(SUBSTR(P_FROM_YYYYMM, 1, 4)) + 2);
    /* 4~6년까지는 연도별 */
    V_FROM_YYYY_YEAR    VARCHAR2(4 CHAR)   := TO_CHAR(TO_NUMBER(SUBSTR(P_FROM_YYYYMM, 1, 4)) + 3);
    V_TO_YYYY_YEAR      VARCHAR2(4 CHAR)   := TO_CHAR(TO_NUMBER(SUBSTR(P_FROM_YYYYMM, 1, 4)) + 5);

    /* 보고 코드 — 원문 @TBL_RPT_CODE 를 대신한다 */
    V_RPT_CODE_NM_PLAN  VARCHAR2(100 CHAR);
    V_RPT_CODE_NM_ETC   VARCHAR2(100 CHAR);

    TYPE T_TBL IS TABLE OF T_FN_SCP0104_SPREAD_TITLE_ROW INDEX BY PLS_INTEGER;
    V_TBL1              T_TBL;
    N_IDX               PLS_INTEGER := 0;
    N_CNT               PLS_INTEGER;

BEGIN

    /* 보고 코드는 원문이 상관 없는 조인(1=1)으로 한 행만 붙이므로 값 하나만 가져온다 */
    BEGIN
        SELECT MAX(A.SEGMENT4)
          INTO V_RPT_CODE_NM_PLAN
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL A
         WHERE A.LOOKUP_TYPE = 'SCP_CAPA_RPT_CODE'
           AND A.VALID_YN    = 'Y'
           AND A.SEGMENT1    = P_PROGRAM_ID
           AND A.SEGMENT2    = V_SHEET_NAME
           AND A.SEGMENT3    = 'PLAN';
    EXCEPTION
        WHEN NO_DATA_FOUND
        THEN
            V_RPT_CODE_NM_PLAN := NULL;
    END;

    BEGIN
        SELECT MAX(A.SEGMENT4)
          INTO V_RPT_CODE_NM_ETC
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL A
         WHERE A.LOOKUP_TYPE = 'SCP_CAPA_RPT_CODE'
           AND A.VALID_YN    = 'Y'
           AND A.SEGMENT1    = P_PROGRAM_ID
           AND A.SEGMENT2    = V_SHEET_NAME
           AND A.SEGMENT3    = 'ETC';
    EXCEPTION
        WHEN NO_DATA_FOUND
        THEN
            V_RPT_CODE_NM_ETC := NULL;
    END;

    /* 처음 3년은 월별 */
    IF P_PROGRAM_ID IN ('SCP0104', 'SCP0105', 'SCP0106')
    THEN

        FOR R IN (SELECT 'M_01' || A.BASIS_YYYYMM                       AS COLUMN_NAME   /* 동일 기간과 중복되므로 00/01 로 구분 */
                       , A.MONTH_NAME                                   AS COLUMN_LABEL_NAME
                       , A.CALENDAR_YYYY                                AS SMALL_CLASS_LABEL_NAME
                       , V_RPT_CODE_NM_PLAN                             AS LARGE_CLASS_LABEL_NAME
                       , ''                                             AS DAY_CODE
                       , '01' || MIN(A.BASIS_START_DATE) || '01'        AS SORT_ORDER_NO
                    FROM SCM_SYS_CALENDAR_M A
                   WHERE A.CALENDAR_YYYY BETWEEN V_FROM_YYYY AND V_TO_YYYY_MONTHLY
                   GROUP BY A.CALENDAR_YYYY
                          , A.BASIS_YYYYMM
                          , A.MONTH_NAME
                   ORDER BY A.BASIS_YYYYMM
                          , A.MONTH_NAME)
        LOOP
            N_IDX := N_IDX + 1;
            V_TBL1(N_IDX) := T_FN_SCP0104_SPREAD_TITLE_ROW(R.COLUMN_NAME, R.COLUMN_LABEL_NAME
                           , R.SMALL_CLASS_LABEL_NAME, R.LARGE_CLASS_LABEL_NAME, R.DAY_CODE, R.SORT_ORDER_NO);
        END LOOP;

    ELSIF P_PROGRAM_ID IN ('SCP0107', 'SCP0108')    /* TEEP, LOB */
    THEN

        FOR R IN (SELECT 'M_01' || A.BASIS_YYYYMM                       AS COLUMN_NAME   /* 동일 기간과 중복되므로 00/01 로 구분 */
                       , A.MONTH_NAME                                   AS COLUMN_LABEL_NAME
                       , A.CALENDAR_YYYY                                AS SMALL_CLASS_LABEL_NAME
                       , V_RPT_CODE_NM_ETC                              AS LARGE_CLASS_LABEL_NAME
                       , ''                                             AS DAY_CODE
                       , '01' || MIN(A.BASIS_START_DATE) || '01'        AS SORT_ORDER_NO
                    FROM SCM_SYS_CALENDAR_M A
                   WHERE A.CALENDAR_YYYY BETWEEN V_FROM_YYYY AND V_TO_YYYY_MONTHLY
                   GROUP BY A.CALENDAR_YYYY
                          , A.BASIS_YYYYMM
                          , A.MONTH_NAME
                   ORDER BY A.BASIS_YYYYMM
                          , A.MONTH_NAME)
        LOOP
            N_IDX := N_IDX + 1;
            V_TBL1(N_IDX) := T_FN_SCP0104_SPREAD_TITLE_ROW(R.COLUMN_NAME, R.COLUMN_LABEL_NAME
                           , R.SMALL_CLASS_LABEL_NAME, R.LARGE_CLASS_LABEL_NAME, R.DAY_CODE, R.SORT_ORDER_NO);
        END LOOP;

    END IF;

    /* 4~6년까지는 연도별 */
    IF P_PROGRAM_ID = 'SCP0106'
    THEN

        FOR R IN (SELECT 'Y_' || A.CALENDAR_YYYY                        AS COLUMN_NAME
                       , A.CALENDAR_YYYY                                AS COLUMN_LABEL_NAME
                       , A.CALENDAR_YYYY                                AS SMALL_CLASS_LABEL_NAME
                       , V_RPT_CODE_NM_PLAN                             AS LARGE_CLASS_LABEL_NAME
                       , ''                                             AS DAY_CODE
                       , '01' || MIN(A.BASIS_START_DATE) || '01'        AS SORT_ORDER_NO
                    FROM SCM_SYS_CALENDAR_M A
                   WHERE A.CALENDAR_YYYY BETWEEN V_FROM_YYYY_YEAR AND V_TO_YYYY_YEAR
                   GROUP BY A.CALENDAR_YYYY
                   ORDER BY A.CALENDAR_YYYY)
        LOOP
            N_IDX := N_IDX + 1;
            V_TBL1(N_IDX) := T_FN_SCP0104_SPREAD_TITLE_ROW(R.COLUMN_NAME, R.COLUMN_LABEL_NAME
                           , R.SMALL_CLASS_LABEL_NAME, R.LARGE_CLASS_LABEL_NAME, R.DAY_CODE, R.SORT_ORDER_NO);
        END LOOP;

    ELSE

        FOR R IN (SELECT 'Y_' || A.CALENDAR_YYYY                        AS COLUMN_NAME
                       , A.CALENDAR_YYYY                                AS COLUMN_LABEL_NAME
                       , A.CALENDAR_YYYY                                AS SMALL_CLASS_LABEL_NAME
                       , V_RPT_CODE_NM_ETC                              AS LARGE_CLASS_LABEL_NAME
                       , ''                                             AS DAY_CODE
                       , '01' || MIN(A.BASIS_START_DATE) || '01'        AS SORT_ORDER_NO
                    FROM SCM_SYS_CALENDAR_M A
                   WHERE A.CALENDAR_YYYY BETWEEN V_FROM_YYYY_YEAR AND V_TO_YYYY_YEAR
                   GROUP BY A.CALENDAR_YYYY
                   ORDER BY A.CALENDAR_YYYY)
        LOOP
            N_IDX := N_IDX + 1;
            V_TBL1(N_IDX) := T_FN_SCP0104_SPREAD_TITLE_ROW(R.COLUMN_NAME, R.COLUMN_LABEL_NAME
                           , R.SMALL_CLASS_LABEL_NAME, R.LARGE_CLASS_LABEL_NAME, R.DAY_CODE, R.SORT_ORDER_NO);
        END LOOP;

    END IF;

    /* 조회 시작 월보다 앞선 월은 뺀다 */
    N_CNT := N_IDX;
    N_IDX := 0;

    FOR I IN 1 .. N_CNT
    LOOP

        IF NOT (SUBSTR(V_TBL1(I).COLUMN_NAME, 5, 6) < P_FROM_YYYYMM)
        THEN
            N_IDX := N_IDX + 1;
            PIPE ROW (V_TBL1(I));

            /* 우선순위 컬럼 추가 */
            IF P_PROGRAM_ID IN ('SCP0105', 'SCP0106')
            THEN
                PIPE ROW (T_FN_SCP0104_SPREAD_TITLE_ROW(
                              V_TBL1(I).COLUMN_NAME || '_ASSIGN_PRIORITY'
                            , V_TBL1(I).COLUMN_LABEL_NAME
                            , V_TBL1(I).SMALL_CLASS_LABEL_NAME
                            , V_TBL1(I).LARGE_CLASS_LABEL_NAME
                            , V_TBL1(I).DAY_CODE
                            , '99' || SUBSTR(V_TBL1(I).SORT_ORDER_NO, 3)));
            END IF;

        END IF;

    END LOOP;

    RETURN;

END FN_SCP0104_GET_SPREAD_TITLE;

