FUNCTION FN_SITE_TIME
(
    P_SITE_ID  IN VARCHAR2
)
RETURN DATE
/*
 * FUNCTION NAME : FN_SITE_TIME
 * DESCRIPTION   : 사이트별 현재시각(UTC+오프셋, 서머타임 반영) 반환. A004=EU DST, 그외=US DST
 * PROGRAM HISTORY
 *--------------------------------------------------------------
 * 2026.07.06   ZIONEX  [PJ202650304]  NextSCM Migration
 */
AS

    V_SITE_TIME  DATE;
    V_SITE_ID    VARCHAR2(4000 CHAR) := P_SITE_ID;
    V_UTC        DATE;
    V_STANDARD   DATE;
    V_YEAR       VARCHAR2(4 CHAR);
    V_MAR1       DATE;
    V_NOV1       DATE;
    V_MAR25      DATE;
    V_OCT25      DATE;
    V_FROMDAY    DATE;
    V_TODAY      DATE;

BEGIN

    SELECT NVL(MAX(SITE_ID), 'A001')
      INTO V_SITE_ID
      FROM SCM_SITE_M_SN
     WHERE SITE_ID = V_SITE_ID;

    V_UTC      := CAST(SYS_EXTRACT_UTC(SYSTIMESTAMP) AS DATE);
    V_STANDARD := V_UTC;
    V_YEAR     := SUBSTR(TO_CHAR(V_UTC, 'YYYYMMDD'), 1, 4);
    V_MAR1     := TO_DATE(V_YEAR || '-03-01', 'YYYY-MM-DD');
    V_NOV1     := TO_DATE(V_YEAR || '-11-01', 'YYYY-MM-DD');
    V_MAR25    := TO_DATE(V_YEAR || '-03-25', 'YYYY-MM-DD');
    V_OCT25    := TO_DATE(V_YEAR || '-10-25', 'YYYY-MM-DD');

    IF V_SITE_ID = 'A004' THEN

        V_FROMDAY := ( CASE MOD(TRUNC(V_MAR25) - TRUNC(V_MAR25, 'IW') + 1, 7) + 1
                            WHEN 1 THEN V_MAR25 + 0
                            WHEN 2 THEN V_MAR25 + 6
                            WHEN 3 THEN V_MAR25 + 5
                            WHEN 4 THEN V_MAR25 + 4
                            WHEN 5 THEN V_MAR25 + 3
                            WHEN 6 THEN V_MAR25 + 2
                            WHEN 7 THEN V_MAR25 + 1
                       END ) + 2/24;
        V_TODAY := ( CASE MOD(TRUNC(V_OCT25) - TRUNC(V_OCT25, 'IW') + 1, 7) + 1
                          WHEN 1 THEN V_OCT25 + 0
                          WHEN 2 THEN V_OCT25 + 6
                          WHEN 3 THEN V_OCT25 + 5
                          WHEN 4 THEN V_OCT25 + 4
                          WHEN 5 THEN V_OCT25 + 3
                          WHEN 6 THEN V_OCT25 + 2
                          WHEN 7 THEN V_OCT25 + 1
                     END ) + 3/24;
    ELSE

        V_FROMDAY := ( CASE MOD(TRUNC(V_MAR1) - TRUNC(V_MAR1, 'IW') + 1, 7) + 1
                            WHEN 2 THEN V_MAR1 + 13
                            WHEN 3 THEN V_MAR1 + 12
                            WHEN 4 THEN V_MAR1 + 11
                            WHEN 5 THEN V_MAR1 + 10
                            WHEN 6 THEN V_MAR1 + 9
                            WHEN 7 THEN V_MAR1 + 8
                            WHEN 1 THEN V_MAR1 + 7
                       END ) + 7/24;
        V_TODAY := ( CASE MOD(TRUNC(V_NOV1) - TRUNC(V_NOV1, 'IW') + 1, 7) + 1
                          WHEN 2 THEN V_NOV1 + 6
                          WHEN 3 THEN V_NOV1 + 5
                          WHEN 4 THEN V_NOV1 + 4
                          WHEN 5 THEN V_NOV1 + 3
                          WHEN 6 THEN V_NOV1 + 2
                          WHEN 7 THEN V_NOV1 + 1
                          WHEN 1 THEN V_NOV1
                     END ) + 7/24;
    END IF;

    BEGIN
        SELECT CASE WHEN V_STANDARD >= V_FROMDAY AND V_STANDARD <= V_TODAY
                    THEN V_STANDARD + NVL(NVL(SUMMER_TIME, "INTERVAL"), 0) / 24
                    ELSE V_STANDARD + NVL("INTERVAL", 0) / 24
               END
          INTO V_SITE_TIME
          FROM (
                SELECT SUMMER_TIME, "INTERVAL"
                  FROM SCM_SITE_M_SN A
                 WHERE A.SITE_ID = V_SITE_ID
                 ORDER BY A."INTERVAL" DESC NULLS LAST
               )
         WHERE ROWNUM <= 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            V_SITE_TIME := NULL;
    END;

    RETURN V_SITE_TIME;

END;

FUNCTION           "FN_SPLITSTRING" 

(

    P_STRING     IN VARCHAR2

  , P_DELIMITER  IN VARCHAR2

)

RETURN T_FN_SPLITSTRING_TAB PIPELINED

/*

 * Program ID   : FN_SplitString

 * Description  : 기존 fn_scm_split 함수 속도 문제 때문에 TABLE 변수 FN_SplitString 생성함.

 * 실행 예제    : SELECT * FROM dbo.FN_SplitString('AJRJR0101A::acer::acer_TW_BAL~A01::E::MPS::NF::20180824::NOPLANT','::')

 * Program History

 *===================================================================================================

 *   Date       In Charge      Description

 *===================================================================================================

 * 2018.08.22  KTH       Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트

 * 2020.03.12  KTH       @Stringing 타입 변경 NVARCHAR(4000) --> NVARCHAR(MAX)

 * 2024.08.02  KSK       MAXRECUSION 횟수제한(최대 100건)을 해제하기 위하여 로직 변경

 * 2026.07.06   ZIONEX  [PJ202650304]  NextSCM Migration

*/

AS



    V_IDX        PLS_INTEGER;

    V_FOUND_IDX  PLS_INTEGER;

    V_STRING     VARCHAR2(32767 CHAR) := P_STRING;

    V_ID         PLS_INTEGER := 0;



BEGIN



    V_IDX       := 1;

    V_FOUND_IDX := INSTR(V_STRING, P_DELIMITER);



    WHILE (V_FOUND_IDX > 0) LOOP



        V_ID := V_ID + 1;

        PIPE ROW (T_FN_SPLITSTRING_ROW(V_ID, TRIM(SUBSTR(V_STRING, 1, V_FOUND_IDX - 1))));



        V_STRING    := SUBSTR(V_STRING, V_FOUND_IDX + LENGTH(P_DELIMITER));

        V_IDX       := V_IDX + 1;

        V_FOUND_IDX := INSTR(V_STRING, P_DELIMITER);



    END LOOP;



    V_ID := V_ID + 1;

    PIPE ROW (T_FN_SPLITSTRING_ROW(V_ID, TRIM(V_STRING)));



    RETURN;



END;

FUNCTION           "FN_STRING_SPLIT" 
(
    P_STR   IN VARCHAR2
   ,P_DELIM IN VARCHAR2 DEFAULT ','
)
/*=====================================================================================================================================================
     * Program ID   : FN_STRING_SPLIT
     * Description  : MS SQL의 STRING_SPLIT 대응
     * Program History
     *=====================================================================================================================================================
     *   Date       In Charge      Description
     *=====================================================================================================================================================
     * ChatGPT
     * 2026.02.12   김준규           MS SQL의 STRING_SPLIT 대응 신규생성(with ChatGPT)
    */
 RETURN T_TOKEN_TAB
    PIPELINED IS
    V_START PLS_INTEGER := 1;
    V_END   PLS_INTEGER;
BEGIN
    IF P_STR IS NULL THEN
        RETURN;
    END IF;

    LOOP
        V_END := INSTR(P_STR, P_DELIM, V_START);

        IF V_END = 0 THEN
            PIPE ROW(T_TOKEN_ROW(TRIM(SUBSTR(P_STR, V_START))));
            EXIT;
        ELSE
            PIPE ROW(T_TOKEN_ROW(TRIM(SUBSTR(P_STR, V_START, V_END - V_START))));
            V_START := V_END + LENGTH(P_DELIM);
        END IF;
    END LOOP;

    RETURN;
END;

FUNCTION FN_XLS_PLANCODE
(
     P_PLAN_START_YYYYMMDD  IN  VARCHAR2 DEFAULT '20241203'
    ,P_PLAN_TYPE            IN  VARCHAR2 DEFAULT 'PR'
    ,P_SEQ                  IN  NUMBER   DEFAULT 1
)
RETURN VARCHAR2
AS
/*
 * Program ID   : FN_XLS_PLANCODE
 * Description  : 비교가능한 플랜정보로 반환
 * OutTable     :
 * Execute      :
 *
 *  SELECT  DBO.FN_XLS_PLANCODE ( '20241202', 'PR', 1 )
 *
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2024.12.03   KSK      iNITIAL RELEASE
 * 2026.07.06   ZIONEX   [PJ202650304] NextSCM Migration
 */
    V_VAL      VARCHAR2(2 CHAR);
    V_SEQ_STR  VARCHAR2(40 CHAR);
BEGIN

    V_VAL := CASE P_PLAN_TYPE
                  WHEN 'PR' THEN '01'
                  WHEN 'MA' THEN '02'
                  WHEN 'SE' THEN '03'
                  WHEN 'FN' THEN '04'
             END;

    /* 매칭 LABEL 없으면 MSSQL SELECT 0행 -> 스칼라 NULL -> NULL 반환 */
    IF V_VAL IS NULL THEN
        RETURN NULL;
    END IF;


    V_SEQ_STR := TO_CHAR(P_SEQ);
    IF LENGTH(V_SEQ_STR) < 3 THEN
        V_SEQ_STR := LPAD(V_SEQ_STR, 3, '0');
    END IF;

    RETURN P_PLAN_START_YYYYMMDD || '_' || V_VAL || '_' || V_SEQ_STR;
END;

