            , T1.FCST_TYPE
            , T1.INCOTERMS
            , T1.DOM_EXP
            , T1.ITEM_ID
            , T1.ACTIVE_YN
            , T1.UNLOADING_POINT
            , T1.CUSTOMER_PLANT
            , T1.SOLDTO_CODE
            , T1.SHIPTO_CODE
            , T1.CUSTOMER_ITEM_ID
            ,'BATCH SYSTEM' AS CREATED_BY
            ,SYSTIMESTAMP CREATION_DATE
            ,'BATCH SYSTEM' AS LAST_UPDATED_BY
