            , T1.SOLDTO_CODE
            , T1.SHIPTO_CODE
            , T1.CUSTOMER_ITEM_ID
            ,'BATCH SYSTEM' AS CREATED_BY
            ,SYSTIMESTAMP CREATION_DATE
            ,'BATCH SYSTEM' AS LAST_UPDATED_BY
            ,SYSTIMESTAMP LAST_UPDATE_DATE
        FROM
            (SELECT DISTINCT
                    A.DIVISION_ID
                  , A.DATA_TYPE_CODE
                  , A.END_CUSTOMER
                  , A.SCM_SITE_ID
                  , A.PROJECT_CODE
                  , A.FCST_TYPE
