                          , SCM_SITE_ID           = V_SCM_SITE_ID
                          , DOM_EXP               = V_DOM_EXP
                          , FCST_TYPE             = V_FCST_TYPE
                          , MEASURE_GROUP         = V_MEASURE_GROUP
                          , MEASURE               = V_MEASURE
                          , YYYYMMDD              = V_YYYYMMDD
                          , INCOTERMS             = V_INCOTERMS
                          , PLANT_SITE_ID         = V_PLANT_SITE_ID
