                         , A.ATTRIBUTE2
                         , A.ATTRIBUTE3
                         , A.ATTRIBUTE4
                         , A.ATTRIBUTE5
                         , A.ATTRIBUTE6
                         , A.ATTRIBUTE7
                         , A.ATTRIBUTE8
                         , A.ATTRIBUTE9
                         , A.ATTRIBUTE10
                      FROM GT_DPCF_T3_DM_PLN_CUSTOMER_PSI A
                     WHERE N_MIN_YYYYMMDD <= YYYYMMDD
                       AND N_MAX_YYYYMMDD >= YYYYMMDD;

                /* [PJ2024-50647] RPA, EXCEL의 경우 N:N 매핑없이 처리함. END */
            END;

