                          GROUP BY DIVISION_ID
                                 , SCM_SITE_ID
                                 , PROJECT_CODE
                                 , ITEM_ID
                                 , DOM_EXP
                                 , FCST_TYPE
                                 , INCOTERMS
                                 , PLANT_SITE_ID
                                 , MEASURE
                                 , YYYYMMDD
                       ) MM;
            END;

            /* (11) */
            /*-------------------- DM_PLN_MKT_FCST 테이블 DELETE FROM count 확인 --------------------*/
            BEGIN
                SELECT COUNT(*)
                  INTO N_FCST_DELETE_COUNT
                  FROM DM_PLN_MKT_FCST A
                 WHERE 1 = 1
                   AND EXISTS (SELECT 1
                                 FROM GT_DPCF_T2_DM_PLN_CUSTOMER_PSI B
