                     , T.ATTRIBUTE5       = S.ATTRIBUTE5
                     , T.ATTRIBUTE6       = S.ATTRIBUTE6
                     , T.ATTRIBUTE7       = S.ATTRIBUTE7
                     , T.ATTRIBUTE8       = S.ATTRIBUTE8
                     , T.ATTRIBUTE9       = S.ATTRIBUTE9
                     , T.ATTRIBUTE10      = S.ATTRIBUTE10
                WHEN NOT MATCHED THEN
