WHILE LENGTH(l_DIVISION_ID) > 0
LOOP

    index_DIVISION_ID      := INSTR(l_DIVISION_ID,      '^');
	index_active_flag      := INSTR(l_active_flag,      '^');
	index_PROJECT_CODE     := INSTR(l_PROJECT_CODE,     '^');
