BEGIN

	INSERT INTO GT_DMF0020_EXCH (DIVISION_ID, YYYYMMDD, CURRENCY, UNIT_CURRENCY, EXCHANGE_PRICE)
	SELECT DISTINCT A.DIVISION_ID, A.YYYYMMDD, A.CURRENCY, A.UNIT_CURRENCY, A.EXCHANGE_PRICE
	FROM DM_MST_EXCHANGE_RATE A
	JOIN GT_DMF0020_RESULTS_MST B
		ON A.DIVISION_ID	= B.v_DIVISION_ID
		AND A.YYYYMMDD		= SUBSTR(B.v_YYYYMMDD, 1, 6) || '01'
		AND A.CURRENCY		= 'KRW';

	-- LOC 동일값
		INSERT INTO GT_DMF0020_RESULTS_MST ( v_active_flag
									,v_DIVISION_ID
									,v_PROJECT_CODE
									,v_SCM_SITE_ID
									,v_PLANT_SITE_ID
									,v_ITEM_ID
									,v_YYYYMMDD
									,v_CURRENCY
									,v_MEASURE
									,v_DOM_EXP
									,v_FCST_TYPE
									,v_INCOTERMS
									,v_PRICE
									,v_CREATED_BY
									,v_CREATION_DATE
									,v_LAST_UPDATED_BY)
		SELECT v_active_flag
				,v_DIVISION_ID
				,v_PROJECT_CODE
				,v_SCM_SITE_ID
				,v_PLANT_SITE_ID
				,v_ITEM_ID
				,v_YYYYMMDD
				,v_CURRENCY
				,v_CURRENCY AS v_MEASURE
				,v_DOM_EXP
				,v_FCST_TYPE
				,v_INCOTERMS
				,v_PRICE
				,v_CREATED_BY
				,v_CREATION_DATE
				,v_LAST_UPDATED_BY
		FROM GT_DMF0020_RESULTS_MST A
		WHERE A.v_MEASURE = 'LOC'
		AND A.v_CURRENCY IN('KRW', 'USD');

		-- KRW값 구하기
		INSERT INTO GT_DMF0020_RESULTS_MST ( v_active_flag
									,v_DIVISION_ID
									,v_PROJECT_CODE
									,v_SCM_SITE_ID
									,v_PLANT_SITE_ID
									,v_ITEM_ID
									,v_YYYYMMDD
									,v_CURRENCY
									,v_MEASURE
									,v_DOM_EXP
									,v_FCST_TYPE
									,v_INCOTERMS
									,v_PRICE
									,v_CREATED_BY
									,v_CREATION_DATE
									,v_LAST_UPDATED_BY)
		SELECT v_active_flag
				,v_DIVISION_ID
				,v_PROJECT_CODE
				,v_SCM_SITE_ID
				,v_PLANT_SITE_ID
				,v_ITEM_ID
				,v_YYYYMMDD
				,v_CURRENCY
				,'KRW' AS v_MEASURE
				,v_DOM_EXP
				,v_FCST_TYPE
				,v_INCOTERMS
				--[E20260930-DMF0020FXZERO] 원문: ,ROUND(A.v_PRICE * B.EXCHANGE_PRICE, 3)
				,ROUND(A.v_PRICE * NVL(B.EXCHANGE_PRICE, 0), 3)   -- 환율 없으면 KRW 0
				,v_CREATED_BY
				,v_CREATION_DATE
				,v_LAST_UPDATED_BY
		FROM GT_DMF0020_RESULTS_MST A
		--[E20260930-DMF0020FXZERO] 원문: JOIN GT_DMF0020_EXCH B
		LEFT JOIN GT_DMF0020_EXCH B   -- 환율 없는 달도 KRW 행 생성
		ON B.UNIT_CURRENCY = A.v_CURRENCY
		AND B.YYYYMMDD = SUBSTR(A.v_YYYYMMDD, 1, 6) || '01'
		WHERE A.v_MEASURE = 'LOC'
		AND A.v_CURRENCY <> 'KRW';

		-- USD값 구하기
		INSERT INTO GT_DMF0020_RESULTS_MST ( v_active_flag
									,v_DIVISION_ID
									,v_PROJECT_CODE
									,v_SCM_SITE_ID
									,v_PLANT_SITE_ID
