									,v_MEASURE
									,v_DOM_EXP
									,v_FCST_TYPE
									,v_INCOTERMS
									,v_PRICE
									,v_CREATED_BY
									,v_CREATION_DATE
									,v_LAST_UPDATED_BY)
		SELECT  v_active_flag
				,v_DIVISION_ID
				,v_PROJECT_CODE
				,v_SCM_SITE_ID
				,v_PLANT_SITE_ID
				,v_ITEM_ID
				,v_YYYYMMDD
				,v_CURRENCY
				,'USD' AS v_MEASURE
				,v_DOM_EXP
				,v_FCST_TYPE
				,v_INCOTERMS
