                UNION ALL SELECT NULL FROM DUAL WHERE (p_owner IS NULL OR p_owner IN ('ALL','/')) /* 2026.08.14 AJS Oracle 은 ''=NULL 이라 IN 목록에 NULL 이 섞여 결과가 UNKNOWN → 조건 무력화 */ ) c    --  2026.10.11 AJS
