        ) A
        JOIN SCM_MGR.SCM_SYS_CALENDAR_M B ON A.YYYYMMDD = B.BASIS_YYYYMMDD
        JOIN SCM_MGR.SCM_MST_FUTURE_PRICE C
          ON A.DIVISION_ID   = C.DIVISION_ID
