    --[E20241030-000923] END
    ------------------------------------------------------------------------------------------
    --  컬럼리스트 만들고, MKT FCST 와 비슷한 방식으로, CTE 로 데이터를 만들고, CTE SELECT 문에 컬럼리스트 삽입한다.
    ------------------------------------------------------------------------------------------

    -- 컬럼리스트 생성
    V_PV_LIST     := '';
    V_PV_COL_LIST := '';
    V_PV_COL      := '';

    FOR R_BUCKET IN C_BUCKET LOOP
        V_PV_COL_LIST := V_PV_COL_LIST || CASE WHEN V_PV_COL_LIST IS NOT NULL AND LENGTH(V_PV_COL_LIST) > 0 THEN ',' ELSE '' END || R_BUCKET.COLUMN_NAME;
        V_PV_LIST     := V_PV_LIST     || CASE WHEN V_PV_LIST     IS NOT NULL AND LENGTH(V_PV_LIST)     > 0 THEN ',' ELSE '' END || R_BUCKET.PV_NAME;
        V_PV_COL      := V_PV_COL      || CASE WHEN V_PV_COL      IS NOT NULL AND LENGTH(V_PV_COL)      > 0 THEN ',' ELSE '' END || 'NVL(' || R_BUCKET.PV_NAME || ', 0) AS ' || R_BUCKET.PV_NAME;
    END LOOP;

    /* 20240518 KCW3408 속도개선_템프사용 */
    INSERT INTO SCM_MGR.GT_DM35_TEMP_SCM_SITE
          (SCM_SITE_ID, DIVISION_ID, PROJECT_CODE, ITEM_ID, DEPT_ID
         , SOLDTO_CODE, VMI_YN, END_CUSTOMER, SOLDTO_CUSTOMER
         , CITY_NAME, COUNTRY_NAME, SHIPTO_DESCRIPTION, SOLDTO_DESCRIPTION
          )
    SELECT B.SCM_SITE_ID, B.DIVISION_ID, B.PROJECT_CODE, B.ITEM_ID, B.DEPT_ID
         , K.SOLDTO_CODE, B.VMI_YN, B.END_CUSTOMER, B.SOLDTO_CUSTOMER
         , H.CITY_NAME, J.COUNTRY_NAME, L.SHIPTO_DESCRIPTION, L.SOLDTO_DESCRIPTION
    FROM (SELECT A.DIVISION_ID, B.PROJECT_CODE, A.SCM_SITE_ID, B.ITEM_ID, B.DEPT_ID, A.END_CUSTOMER, A.VMI_YN, A.SOLDTO_CUSTOMER, A.CITY, A.COUNTRY
              FROM SCM_MGR.SCM_MST_SITE A
                   LEFT OUTER JOIN SCM_MGR.SCM_MST_SITE_ITEM B
                        ON A.DIVISION_ID = B.DIVISION_ID
                       AND A.SCM_SITE_ID = B.SCM_SITE_ID
             WHERE 1=1
             GROUP BY A.DIVISION_ID, B.PROJECT_CODE, A.SCM_SITE_ID, B.ITEM_ID, B.DEPT_ID, A.END_CUSTOMER, A.VMI_YN, A.SOLDTO_CUSTOMER, A.CITY, A.COUNTRY
            ) B
    LEFT OUTER JOIN SCM_MGR.SCM_MST_SITE_CUSTOMER K
               ON B.DIVISION_ID = K.DIVISION_ID
              AND B.SCM_SITE_ID = K.SCM_SITE_ID
              AND K.REP_YN      = 'Y'
    LEFT OUTER JOIN SCM_MGR.SCM_MST_CITY H ON B.CITY = H.CITY
    LEFT OUTER JOIN SCM_MGR.SCM_MST_COUNTRY J ON B.COUNTRY = J.COUNTRY
    LEFT OUTER JOIN SCM_MGR.SCM_MST_CUSTOMER L
               ON K.DIVISION_ID = L.DIVISION_ID AND K.SHIPTO_CODE = L.SHIPTO_CODE AND K.SOLDTO_CODE = L.SOLDTO_CODE;


    N_LOG_COUNT   := SQL%ROWCOUNT;
    V_LOG_TYPE    := 'INFO';
    V_LOG_MESSAGE := 'G1--GT_DM35_TEMP_SCM_SITE';
    D_EVENT_DATE  := SYSDATE;
    BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE); END;

    DBMS_STATS.SET_TABLE_PREFS('SCM_MGR', 'GT_DM35_TEMP_SCM_SITE', 'GLOBAL_TEMP_TABLE_STATS', 'SESSION');
    DBMS_STATS.GATHER_TABLE_STATS(ownname => 'SCM_MGR', tabname => 'GT_DM35_TEMP_SCM_SITE', estimate_percent => DBMS_STATS.AUTO_SAMPLE_SIZE, method_opt => 'FOR ALL COLUMNS SIZE 1');

    SELECT COUNT(1)
    INTO   N_LOG_COUNT
    FROM   GT_DM35_RAW_DATA
    ;

    V_LOG_TYPE    := 'INFO';
    V_LOG_MESSAGE := 'G2--GT_DM35_RAW_DATA COUNT';
    D_EVENT_DATE  := SYSDATE;
    BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE); END;


    ----- 일반 컬럼 -----------------------------------------------------------------------------------------------------------
    --V_COLUMN_NAME := '';
    --V_COLUMN      := '';
    --V_ORDERBY     := '';
    V_COL_LIST    := '';
    V_ORDER_LIST  := '';

    SELECT COUNT(*) INTO V_I_COUNT
    FROM SCM_MGR.SCM_MST_TITLESET_USER U
    WHERE U.PROGRAM_ID                    = V_P_PROGRAM_ID
    AND   U.SHEET_NAME                    = V_P_SHEET_NAME
    AND   U.USER_ID                       = P_CREATED_BY
    AND   U.USER_INQUIRY_COLUMN_TYPE_CODE = 'C';

    IF V_I_COUNT = 0
    THEN
        SELECT LISTAGG(' ' || COLUMN_NAME || ',', '') WITHIN GROUP (ORDER BY SORT_ORDER_NO)
             , LISTAGG(' ' || COLUMN_NAME || ' ' || DATA_SORT_METHOD_CODE || ',', '') WITHIN GROUP (ORDER BY SORT_ORDER_NO)
        INTO   V_COL_LIST, V_ORDER_LIST
        FROM (
            SELECT SORT_ORDER_NO, COLUMN_NAME, DATA_SORT_METHOD_CODE
            FROM SCM_MGR.SCM_MST_SHEET_COLUMNS C
            WHERE C.PROGRAM_ID = V_P_PROGRAM_ID
            AND   C.SHEET_NAME = V_P_COLS_SHEET
            AND   (C.DEFAULT_FLAG = 'Y'
                OR (C.VISIBLE_FLAG = 'N' AND RTRIM(C.DEFAULT_FLAG, ' -') IS NULL AND C.VALID_YN = 'Y'))  --[E20260806-WF] 숨은컬럼 빈값 판정(0051 동형)
        ) TBCOLLIST;
    ELSE
        SELECT LISTAGG(' ' || COLUMN_NAME || ',', '') WITHIN GROUP (ORDER BY SORT_ORDER_NO)
             , LISTAGG(' ' || COLUMN_NAME || ' ' || DATA_SORT_METHOD_CODE || ',', '') WITHIN GROUP (ORDER BY SORT_ORDER_NO)
        INTO   V_COL_LIST, V_ORDER_LIST
        FROM (
            SELECT CASE WHEN C.COLUMN_NAME = 'GROUP_ID' THEN NVL(TU.SORT_ORDER_NO, 95) - 0.5 ELSE U.SORT_ORDER_NO END AS SORT_ORDER_NO
                 , C.COLUMN_NAME, U.DATA_SORT_METHOD_CODE
            FROM SCM_MGR.SCM_MST_TITLESET_USER U
            INNER JOIN SCM_MGR.SCM_MST_SHEET_COLUMNS C
                    ON U.PROGRAM_ID  = C.PROGRAM_ID
                   AND C.SHEET_NAME  = V_P_COLS_SHEET
                   AND U.COLUMN_NAME = C.COLUMN_NAME
                   AND U.PROGRAM_ID  = V_P_PROGRAM_ID
                   AND U.SHEET_NAME  = V_P_SHEET_NAME
                   AND U.USER_ID     = P_CREATED_BY
                   AND U.USER_INQUIRY_COLUMN_TYPE_CODE = 'C'
                   AND U.COLUMN_NAME NOT IN ('MEASURE')  --[E20260916-VERCOL] VERSION_NO 제외 해제 — 아래 ① 설명
    --[E20260916-PERSDIV2] 개인화('C') 컬럼목록에 조회 division 필터 적용 (사용자 지시 2026-09-16).
    --  증상: 개인화를 저장하기 전에 다른 DIVISION 으로 조회하면, 직전 division 에서 등록한
    --        개인화 컬럼이 그대로 조회에 실린다(예: END_CUSTOMER/END_CUSTOMER40 쌍을 둘 다 보유).
    --  근거: 같은 축을 **TITLE SP 와 FE 컬럼메타 SP 는 이미 걸러낸다** —
    --        TITLE(PKG_DMF0035 'INSTR(...DIVISION_ID...)>0' / PKG_DMF0022 '20180620 division 추가'),
    --        FE(PKG_NSCM_UI_COM_MENU.PR_GET_SHEET_COLUMN_LIST 의 division 필터).
    --        메인 데이터 SP 의 컬럼목록만 걸러지지 않아, 화면에 보이지도 않는 컬럼이
    --        SELECT/GROUP BY/PIVOT 축으로 남아 있었다([E20260910-GRAINFIX]·[E20260916-DIVBLANK] 동일 계보).
    --  판정식은 FE 메타 SP 와 동일하게 맞춘다(NULL = 전 division 허용, 공백 ' ' 은 불일치로 제외).
    --  ⚠ [E20260910-PERSDIV] 원복 이력과의 차이: 그때 지목된 -29행 사유는 END_CUSTOMER40 이
    --    PROJECT_CODE 의 유일한 운반체였다는 것인데, 매핑 실측 결과 PKG_DMF0035 는
    --    'CASE WHEN A.DIVISION_ID=''40'' THEN A.PROJECT_CODE ELSE '' '' END' 라 div<>40 에서 상수이며,
    --    PKG_DMF0022 만 'A.PROJECT_CODE' 무조건 매핑이다. 적용 전후 A/B 실측으로 영향을 확인한다.
    --  ⚠ AS-IS 파리티: AS-IS DMF0022 는 이 조건을 2019-01-25 주석처리(KHSONG)했다.
    --    본 적용은 사용자 지시에 따른 **의도적 AS-IS 이탈**이다(DMF0051 은 AS-IS 도 필터 보유).
                   AND ( C.DIVISION_ID IS NULL
                      OR INSTR(',' || C.DIVISION_ID || ',', ',' || P_DIVISION_ID || ',') > 0 )
    --[E20260916-VERCOL] ① AS-IS 는 이 NOT IN 으로 VERSION_NO·MEASURE 를 개인화 목록에서 빼고,
    --  아래 UNION ALL '숨은컬럼 arm'(VISIBLE_FLAG='N' AND DEFAULT_FLAG='' AND VALID_YN='Y')으로
    --  **무조건 재주입**한다(AS-IS 실측: 그 arm 대상 = VERSION_NO(220)·MEASURE(500) 2개뿐).
    --  TO-BE 는 SCM_MST_SHEET_COLUMNS 의 두 컬럼이 VISIBLE_FLAG='Y'/DEFAULT_FLAG='Y' 로 이관돼
    --  그 재주입 경로가 끊겼고, 개인화('C')를 가진 사용자는 VERSION_NO 가 목록에서 통째로 사라져
    --  최종 SELECT/GROUP BY 와 그리드 VERSION 이 빈 값이 됐다(사용자 신고 2026-09-16).
    --  TO-BE 개인화에는 VERSION_NO 가 제 자리(SHEET_COLUMNS SORT 220 시드)로 이미 들어 있으므로
    --  제외만 풀면 V_COL_LIST·V_ORDER_LIST 양쪽에 올바른 위치로 복귀한다(정렬은 아래 REPLACE 규약).
    --  MEASURE 는 [E20260909-MEASURECOL] 가드가 이미 담당하므로 그대로 둔다(무변경).
    --[E20260910-PERSDIV] 원복(2026-09-10). 개인화 컬럼목록에 DIVISION 필터를 걸었으나,
    --  그 목록은 GROUP BY 에도 쓰여 grain 이 바뀐다. 클라우드 div81 실측: 타 DIVISION 컬럼
    --  END_CUSTOMER40(= A.PROJECT_CODE) 이 그 사용자 개인화에서 PROJECT_CODE 의 유일한 운반체였고,
    --  제외되자 PROJECT_CODE 가 GROUP BY 에서 사라져 29쌍이 합산 병합됐다(AS-IS 대비 -29행).
    --  AS-IS DMF0022 는 이 조건을 2019-01-25 의도적으로 주석처리(KHSONG)했다 — 원복이 AS-IS 파리티.
    --  당초 목적이던 ORA-00904 는 [E20260910-FROMSITE](사전 등재) + MEASURECOL 로 이미 해소됐고,
    --  82 오류의 실제 원인은 [E20260910-QTYMASK] 였다. 컬럼사전 미등재 갭은 사내·클라우드 모두 0.

            LEFT OUTER JOIN SCM_MGR.SCM_MST_TITLESET_USER TU
                         ON TU.PROGRAM_ID  = C.PROGRAM_ID
                        AND TU.SHEET_NAME  = V_P_SHEET_NAME
                        AND TU.USER_INQUIRY_COLUMN_TYPE_CODE = 'C'
                        AND TU.COLUMN_NAME IN ('ITEM_ID')
                        AND TU.USER_ID     = P_CREATED_BY
            UNION ALL
            SELECT C.SORT_ORDER_NO, C.COLUMN_NAME, C.DATA_SORT_METHOD_CODE
            FROM SCM_MGR.SCM_MST_SHEET_COLUMNS C
            WHERE C.PROGRAM_ID   = V_P_PROGRAM_ID
            AND   C.SHEET_NAME   = V_P_COLS_SHEET
            AND   C.VISIBLE_FLAG = 'N'
            AND   RTRIM(C.DEFAULT_FLAG, ' -') IS NULL  --[E20260806-WF] 숨은컬럼 빈값 판정(0051 동형)
            AND   C.VALID_YN     = 'Y'
            AND   ROWNUM         <= 100
        ) TBCOLLIST;
    END IF;

    N_LOG_COUNT   := SQL%ROWCOUNT;
    V_LOG_TYPE    := 'INFO';
    V_LOG_MESSAGE := 'G3--V_COL_LIST,V_ORDER_LIST';
    D_EVENT_DATE  := SYSDATE;
    BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE); END;


    -- 마지막 콤마 제거
    V_COL_LIST   := RTRIM(V_COL_LIST, ',');
    V_ORDER_LIST := RTRIM(V_ORDER_LIST, ',');

    --[E20231128-000738] 해당컬럼으로 숫자표기형태를 구분하려고 하니, 해당 컬럼을 추출할수있도록 추가
    V_COL_LIST   := V_COL_LIST || ',NOTATION';

    --[E20260909-MEASURECOL] MEASURE 컬럼 보장 — T_WF_DATA 는 컬럼목록(V_COL_LIST)을 사전과 조인해
    --  SELECT 를 만드는데, 아래 집계부는 F.MEASURE 를 **무조건** 참조한다(BALANCE/VMI_Inv/AS_Inv/
    --  SS_LVL/SS_GAP 주말값 처리 + LOC 평균 분기). 그런데 'C' 개인화가 있는 사용자는 위 ELSE 분기의
    --  NOT IN ('MEASURE','VERSION_NO') 때문에 MEASURE 가 목록에서 빠지고, 바로 아래 REPLACE 도
    --  치환 대상이 없어 무동작 → T_WF_DATA 에 MEASURE 부재 → ORA-00904 "F"."MEASURE".
    --  개인화가 없는 사용자는 IF 분기(SHEET_COLUMNS DEFAULT_FLAG='Y')로 MEASURE 가 들어와 무증상이라
    --  [E20260909-SHEETUNIFY] 로 titleset 시트명이 실등록명으로 바뀌면서 비로소 드러났다(A/B 실증).
    --  MEASURE 는 표시축이자 집계 grain 이므로 목록 말미에 보장 삽입한다(정렬은 REPLACE 규약이 담당).
    IF INSTR(',' || REPLACE(REPLACE(V_COL_LIST, ' ', ''), CHR(10), '') || ',', ',MEASURE,') = 0 THEN
        V_COL_LIST := V_COL_LIST || ',MEASURE';
        --[E20260917-MEASUREORDER] 정렬축도 함께 보강 (사용자 신고 2026-09-17 — MEASURE POPUP 순서 미반영).
        --  아래 [E20260916-VERCOL] VERSION_NO 가드와 **동형**이다. 종전에는 V_COL_LIST 에만 넣어
        --  L3082 `REPLACE(V_ORDER_LIST,'MEASURE','SORT_ORDER_NO')` 가 치환 대상을 못 찾고 무동작 →
        --  ORDER BY 에 SORT_ORDER_NO 가 빠져 메저 순서가 비결정이었다('C' 개인화 사용자 한정 증상).
        --  위치(말미)는 개인화 없는 경로와 동일하다 — SHEET_COLUMNS MEASURE SORT_ORDER_NO=999 = 최후미.
        V_ORDER_LIST := CASE WHEN V_ORDER_LIST IS NULL OR LENGTH(TRIM(V_ORDER_LIST)) = 0
                             THEN 'MEASURE ASC' ELSE V_ORDER_LIST || ',MEASURE ASC' END;
    END IF;

    --[E20260916-VERCOL] ② VERSION_NO 보장 — MEASURECOL(2026-09-09) 동형 가드.
    --  사용자가 Column Setting 에서 VERSION 을 끈 경우에도 목록에 없으면 보강한다.
    --  FE 는 VERSION_NO 를 FORCED_AXIS 로 선언해(waterfall.columns.ts) '컬럼 설정으로도 끌 수 없는'
    --  행 축으로 취급하므로 SP 도 같은 계약을 지킨다. 정렬축(V_ORDER_LIST)도 함께 보강해야
    --  AS-IS 규약(VERSION_SORT DESC)이 살아난다 — 바로 아래 REPLACE 가 확장한다.
    --  위치는 ①(개인화 자리)과 동일하게 목록 말미로 맞춘다.
    IF INSTR(',' || REPLACE(REPLACE(V_COL_LIST, ' ', ''), CHR(10), '') || ',', ',VERSION_NO,') = 0 THEN
        V_COL_LIST   := V_COL_LIST || ',VERSION_NO';
        V_ORDER_LIST := CASE WHEN V_ORDER_LIST IS NULL OR LENGTH(TRIM(V_ORDER_LIST)) = 0
                             THEN 'VERSION_NO ASC' ELSE V_ORDER_LIST || ',VERSION_NO ASC' END;
    END IF;

    V_COL_LIST   := REPLACE(V_COL_LIST,   'VERSION_NO', 'VERSION_SORT,VERSION_NO');
    V_COL_LIST   := REPLACE(V_COL_LIST,   'MEASURE',    'MEASURE_GROUP,MEASURE,SORT_ORDER_NO');
    V_ORDER_LIST := REPLACE(V_ORDER_LIST, 'VERSION_NO', 'VERSION_SORT DESC,VERSION_NO');
    V_ORDER_LIST := REPLACE(V_ORDER_LIST, 'MEASURE',    'SORT_ORDER_NO');

