                AND   C.INCOTERMS          = A.INCOTERMS
                AND   C.PLANT_SITE_ID      = A.PLANT_SITE_ID
                AND   C.CELL_PROD_SITE_ID  = A.CELL_PROD_SITE_ID -- [PJ2025-50017] CELL_PROD_SITE_ID 추가
        );


