		    --4). 들어가있는 데이터와 형식을 동일하게 맞추기위해서, 데이터 형식을 맞춰주는 작업을 진행한다.
        INSERT INTO SCM_MGR.GT_DM35_VMI_INV_RESULT
              (VERSION_NO, CUTOFF_YYYYMMDD, DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, PLANT_SITE_ID, ITEM_ID, INCOTERMS, DOM_EXP, FCST_TYPE, MEASURE
           , MEASURE_GROUP, YYYYMMDD, QTY, VALID_YN, PLAN_RESULT, GUBUN, CREATE_DATE, LAST_UPDATED_BY, SENDER_CODE, SENDER_NAME, AS_FROM_SITE
           , CELL_NICKNAME, PRODUCT_LEVEL1, PRODUCT_LEVEL2, PRODUCT_LEVEL3, NOTATION
           , CELL_PROD_SITE_ID)
        SELECT B.VERSION_NO, B.CUTOFF_YYYYMMDD, A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.PLANT_SITE_ID, A.ITEM_ID, A.INCOTERMS, A.DOM_EXP, A.FCST_TYPE, A.MEASURE
           , B.MEASURE_GROUP, A.YYYYMMDD, A.QTY, B.VALID_YN, B.PLAN_RESULT, B.GUBUN, B.CREATE_DATE, B.LAST_UPDATED_BY, B.SENDER_CODE, B.SENDER_NAME, B.AS_FROM_SITE
           , B.CELL_NICKNAME, B.PRODUCT_LEVEL1, B.PRODUCT_LEVEL2, B.PRODUCT_LEVEL3, B.NOTATION
           , B.CELL_PROD_SITE_ID-- [PJ2025-50017] CELL_PROD_SITE_ID 추가
        FROM SCM_MGR.GT_DM35_TEMP_VMI_INV A
             INNER JOIN SCM_MGR.GT_DM35_RAW_DATA_FINAL B
                ON A.DIVISION_ID    = B.DIVISION_ID
               AND A.PROJECT_CODE   = B.PROJECT_CODE
               AND A.SCM_SITE_ID    = B.SCM_SITE_ID
               AND A.ITEM_ID      = B.ITEM_ID
               AND A.DOM_EXP      = B.DOM_EXP
               AND A.FCST_TYPE    = B.FCST_TYPE
               AND A.INCOTERMS    = B.INCOTERMS
               AND A.MEASURE      = B.MEASURE
               AND A.PLANT_SITE_ID  = B.PLANT_SITE_ID
               AND A.YYYYMMDD     = B.YYYYMMDD
               AND A.CELL_PROD_SITE_ID= B.CELL_PROD_SITE_ID-- [PJ2025-50017] CELL_PROD_SITE_ID 추가
         ;

        --5). PERIOD 기간만큼 데이터를 생성한다.
        INSERT INTO SCM_MGR.GT_DM35_VMI_INV_RESULT
            ( VERSION_NO, CUTOFF_YYYYMMDD, DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, PLANT_SITE_ID, ITEM_ID, INCOTERMS, DOM_EXP, FCST_TYPE
            , MEASURE, MEASURE_GROUP, YYYYMMDD, QTY, VALID_YN, PLAN_RESULT, GUBUN, CREATE_DATE, LAST_UPDATED_BY, SENDER_CODE
            , SENDER_NAME, AS_FROM_SITE, CELL_NICKNAME, PRODUCT_LEVEL1, PRODUCT_LEVEL2, PRODUCT_LEVEL3, NOTATION
            , CELL_PROD_SITE_ID-- [PJ2025-50017] CELL_PROD_SITE_ID 추가
            )
        SELECT DISTINCT B.VERSION_NO, B.CUTOFF_YYYYMMDD, B.DIVISION_ID, B.PROJECT_CODE, B.SCM_SITE_ID, B.PLANT_SITE_ID, B.ITEM_ID, B.INCOTERMS, B.DOM_EXP, B.FCST_TYPE
           , B.MEASURE, B.MEASURE_GROUP, A.BASIS_YYYYMMDD, B.QTY, B.VALID_YN, B.PLAN_RESULT, B.GUBUN, B.CREATE_DATE, B.LAST_UPDATED_BY, B.SENDER_CODE
           , B.SENDER_NAME, B.AS_FROM_SITE, B.CELL_NICKNAME, B.PRODUCT_LEVEL1, B.PRODUCT_LEVEL2, B.PRODUCT_LEVEL3, B.NOTATION
           , B.CELL_PROD_SITE_ID-- [PJ2025-50017] CELL_PROD_SITE_ID 추가
        FROM SCM_SYS_CALENDAR_M A
              LEFT OUTER JOIN SCM_MGR.GT_DM35_VMI_INV_RESULT B
                     ON A.BASIS_YYYYMMDD  > B.YYYYMMDD
        WHERE A.BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
        AND A.BASIS_YYYYMMDD > B.YYYYMMDD
        ;

        --모수로 잡았던 데이터는 삭제한다.
        DELETE FROM SCM_MGR.GT_DM35_VMI_INV_RESULT A
        WHERE  A.DIVISION_ID = '82'
--      AND    A.MEASURE = 'VMI_INV'   --  2026.10.08 AJS
        AND    A.MEASURE = 'VMI_Inv'   --  2026.10.08 AJS
        AND EXISTS ( SELECT DIVISION_ID
                     FROM   SCM_MGR.GT_DM35_TEMP_VMI_INV Z
                     WHERE  1=1
                     AND    A.DIVISION_ID    = Z.DIVISION_ID
                     AND    A.PROJECT_CODE   = Z.PROJECT_CODE
                     AND    A.SCM_SITE_ID    = Z.SCM_SITE_ID
                     AND    A.ITEM_ID        = Z.ITEM_ID
                     AND    A.DOM_EXP        = Z.DOM_EXP
                     AND    A.FCST_TYPE      = Z.FCST_TYPE
                     AND    A.INCOTERMS      = Z.INCOTERMS
                     AND    A.PLANT_SITE_ID  = Z.PLANT_SITE_ID
                     AND    A.YYYYMMDD       = Z.YYYYMMDD
                     AND    A.CELL_PROD_SITE_ID = Z.CELL_PROD_SITE_ID-- [PJ2025-50017] CELL_PROD_SITE_ID 추가
                     );


        DBMS_STATS.SET_TABLE_PREFS('SCM_MGR', 'GT_DM35_VMI_INV_RESULT', 'GLOBAL_TEMP_TABLE_STATS', 'SESSION');
        DBMS_STATS.GATHER_TABLE_STATS(ownname => 'SCM_MGR', tabname => 'GT_DM35_VMI_INV_RESULT', estimate_percent => DBMS_STATS.AUTO_SAMPLE_SIZE, method_opt => 'FOR ALL COLUMNS SIZE 1');

        --6). 임시로 만든 데이터를, 주 임시테이블에 INSERT 한다.
        INSERT INTO SCM_MGR.GT_DM35_RAW_DATA_FINAL
        (  VERSION_NO, CUTOFF_YYYYMMDD, DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, PLANT_SITE_ID, ITEM_ID, INCOTERMS, DOM_EXP, FCST_TYPE
         , MEASURE, MEASURE_GROUP, YYYYMMDD, QTY, VALID_YN, PLAN_RESULT, GUBUN, CREATE_DATE, LAST_UPDATED_BY, SENDER_CODE
         , SENDER_NAME, AS_FROM_SITE, CELL_NICKNAME, PRODUCT_LEVEL1, PRODUCT_LEVEL2, PRODUCT_LEVEL3, NOTATION
         , CELL_PROD_SITE_ID-- [PJ2025-50017] CELL_PROD_SITE_ID 추가
         )
        SELECT VERSION_NO, CUTOFF_YYYYMMDD, DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, PLANT_SITE_ID, ITEM_ID, INCOTERMS, DOM_EXP, FCST_TYPE
           , MEASURE, MEASURE_GROUP, YYYYMMDD, QTY, VALID_YN, PLAN_RESULT, GUBUN, CREATE_DATE, LAST_UPDATED_BY, SENDER_CODE
             , SENDER_NAME, AS_FROM_SITE, CELL_NICKNAME, PRODUCT_LEVEL1, PRODUCT_LEVEL2, PRODUCT_LEVEL3, NOTATION
           , CELL_PROD_SITE_ID-- [PJ2025-50017] CELL_PROD_SITE_ID 추가
        FROM SCM_MGR.GT_DM35_VMI_INV_RESULT
        ;


        DBMS_STATS.SET_TABLE_PREFS('SCM_MGR', 'GT_DM35_RAW_DATA_FINAL', 'GLOBAL_TEMP_TABLE_STATS', 'SESSION');
        DBMS_STATS.GATHER_TABLE_STATS(ownname => 'SCM_MGR', tabname => 'GT_DM35_RAW_DATA_FINAL', estimate_percent => DBMS_STATS.AUTO_SAMPLE_SIZE, method_opt => 'FOR ALL COLUMNS SIZE 1');


    END IF; -- P_DIVISION_ID = '82'

    --[E20240102-000545]_[마케팅PI] 82번 사업부 - VMI표기 로직 개선  END

    /* @v_sql_text 안쪽데이타 빼냄 */
    INSERT INTO SCM_MGR.GT_DM35_CALENDAR (BASIS_YYYYMMWW, ISO_YYYYWW, ISO_WEEK, BASIS_YYYYMMDD, END_FLAG, BASIS_YYYYMM)
    SELECT A.BASIS_YYYYMMWW, A.ISO_YYYYWW, A.ISO_WEEK, B.BASIS_YYYYMMDD, B.END_FLAG, B.BASIS_YYYYMM
    FROM (
        SELECT SUBSTR(MAX(BASIS_YYYYMMDD), 1, 6) || ISO_WEEK AS BASIS_YYYYMMWW, ISO_YYYYWW, ISO_WEEK
        FROM SCM_MGR.SCM_SYS_CALENDAR_M
        WHERE BASIS_YYYYMMDD >= P_FROM_YYYYMMDD
        AND   BASIS_YYYYMMDD <= P_TO_YYYYMMDD
        GROUP BY ISO_YYYYWW, ISO_WEEK
    ) A
    JOIN SCM_MGR.SCM_SYS_CALENDAR_M B ON A.ISO_YYYYWW = B.ISO_YYYYWW AND A.ISO_WEEK = B.ISO_WEEK;

    INSERT INTO SCM_MGR.GT_DM35_CAL_MONTH_END (MONTH_END_DATE)
    SELECT MAX(BASIS_YYYYMMDD) AS MONTH_END_DATE
    FROM SCM_MGR.SCM_SYS_CALENDAR_M
    WHERE BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
    GROUP BY BASIS_YYYYMM;

    INSERT INTO SCM_MGR.GT_DM35_CAL_WEEK_END (WEEK_END_DATE)
    SELECT MAX(BASIS_YYYYMMDD) AS WEEK_END_DATE
    FROM SCM_MGR.SCM_SYS_CALENDAR_M
    WHERE BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
    GROUP BY ISO_YYYYWW || PARTIAL_WEEK_NAME;

    N_LOG_COUNT   := SQL%ROWCOUNT;
    V_LOG_TYPE    := 'INFO';
    V_LOG_MESSAGE := 'H--';
    D_EVENT_DATE  := SYSDATE;
    BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE); END;

    --[E20230906-000992] ENERGY MEASURE에 한해 표기형식변경 (MKT FCST 화면값과 일치화)
    V_SQL_TEXT := ' WITH T_WF_DATA AS (' ||
        CHR(10) || 'SELECT CASE WHEN A.MEASURE IN (''RTF_ENERGY'', ''MKT_FCST_ENERGY'') THEN ' ||
        CHR(10) || '   CAST(CASE WHEN ''' || P_CELL_YN || ''' = ''Y'' AND A.MEASURE_GROUP NOT IN ( ''SFA'',''VMI_DIO'',''OVER_FCST'',''LESS_FCST'',''CFA'',''CFCR'' ) AND NVL(D.FORECAST_INFO_CELL_PACK_COUNT,1) <> 1 THEN A.QTY * D.FORECAST_INFO_CELL_PACK_COUNT ELSE A.QTY END AS NUMBER(30,10)) ' ||
        CHR(10) || '   ELSE ' ||
        CHR(10) || '   CAST(CASE WHEN ''' || P_CELL_YN || ''' = ''Y'' AND A.MEASURE_GROUP NOT IN ( ''SFA'',''VMI_DIO'',''OVER_FCST'',''LESS_FCST'',''CFA'',''CFCR'' ) AND NVL(D.FORECAST_INFO_CELL_PACK_COUNT,1) <> 1 THEN A.QTY * D.FORECAST_INFO_CELL_PACK_COUNT ELSE A.QTY END AS NUMBER(19,0)) ' ||
        CHR(10) || '   END AS QTY ' ||
        CHR(10) || ' , CASE WHEN ''' || P_BUCKET || ''' = ''DAILY'' THEN A.YYYYMMDD ELSE '''' END AS YYYYMMDD ' ||
        CHR(10) || ' , CAL.BASIS_YYYYMM, CAL.ISO_WEEK, CAL.BASIS_YYYYMMWW ' ||
        CHR(10) || ' , M.SORT_ORDER_NO ' ||
        CHR(10) || ' , CASE WHEN C2.MONTH_END_DATE IS NOT NULL THEN ''Y'' ELSE ''N'' END AS MONTH_END_YN ' ||
        CHR(10) || ' , CASE WHEN C3.WEEK_END_DATE  IS NOT NULL THEN ''Y'' ELSE ''N'' END AS WEEK_END_YN ' ||
        CHR(10) || ' , C.PROJECT_S_OP_REPORT  --[E20241030-000923]_MKT FCST, MKT FCST Waterfall 화면 신규 컬럼 추가 요청 건 ' ||
        CHR(10) || ' , CASE WHEN LENGTH(NVL(EE.ATTRIBUTE1,'''')) = 0 THEN ''Common'' ELSE EE.ATTRIBUTE1 END AS CELL_PROD_SITE_ID -- [PJ2025-50017] CELL_PROD_SITE_ID 추가 ' ||
        CHR(10) || ' , ' || V_SQL_SELECT ||
        CHR(10) || ' , EDY.EDIT_YN ' ||
        CHR(10) || ' FROM SCM_MGR.GT_DM35_RAW_DATA_FINAL A ' ||
        CHR(10) || '      INNER JOIN SCM_MGR.SCM_ADM_USER_MNU_EDIT_AUTH_V EDY ' ||
        CHR(10) || '           ON EDY.USER_ID = ''' || P_USER_ID || '''' ||
        CHR(10) || '          AND EDY.MNU_ID  = ''' || P_MENU_ID || '''' ||
        CHR(10) || '          AND EDY.UNIT_ID = A.DIVISION_ID ' ||
        CHR(10) || ' LEFT OUTER JOIN SCM_MGR.GT_DM35_TEMP_SCM_SITE B ON A.SCM_SITE_ID = B.SCM_SITE_ID AND A.DIVISION_ID = B.DIVISION_ID AND A.PROJECT_CODE = B.PROJECT_CODE AND A.ITEM_ID = B.ITEM_ID ' ||
        CHR(10) || ' LEFT OUTER JOIN SCM_MGR.GT_DM35_SITE_ITEM C ON A.DIVISION_ID = C.DIVISION_ID AND A.PROJECT_CODE = C.PROJECT_CODE AND A.SCM_SITE_ID = C.SCM_SITE_ID AND A.ITEM_ID = C.ITEM_ID ' ||
        CHR(10) || ' LEFT OUTER JOIN SCM_MGR.GT_DM35_ITEM_SINGLE_V D ON A.DIVISION_ID = D.DIVISION_ID AND A.ITEM_ID = D.ITEM_ID ' ||
        CHR(10) || ' LEFT OUTER JOIN SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL E ON D.CELL_TYPE = E.SEGMENT1 AND E.LOOKUP_TYPE = ''CELL_TYPE'' ' ||
        CHR(10) || ' LEFT OUTER JOIN SCM_MGR.GT_DM35_ITEM_SINGLE_V F ON D.DIVISION_ID = F.DIVISION_ID AND NVL(D.FORECAST_INFO_CELL_MODEL,'''') = F.ITEM_ID ' ||
        CHR(10) || ' LEFT OUTER JOIN SCM_MGR.SCM_MST_PROJECT G ON A.DIVISION_ID = G.DIVISION_ID AND A.PROJECT_CODE = G.PROJECT_CODE ' ||
        CHR(10) || ' LEFT OUTER JOIN SCM_MGR.SCP_MST_ITEM_GROUP_DETAIL I ON A.DIVISION_ID = I.DIVISION_ID AND A.PROJECT_CODE = I.PROJECT_CODE AND A.ITEM_ID = I.ITEM_ID ' ||
        CHR(10) || ' JOIN SCM_MGR.GT_DM35_SEL_MEASURE M ON A.MEASURE = M.MEASURE ' ||
        CHR(10) || ' --[PJ2024-50461] Team Mapping------------------------------------ ' ||
        CHR(10) || ' --LEFT OUTER JOIN SCM_MGR.SCM_MST_SSO_DEPT_INFO N ON CASE WHEN A.DIVISION_ID = ''40'' THEN C.DEPT_ID ELSE B.DEPT_ID END = N.DEPT_ID ' ||
        CHR(10) || ' LEFT OUTER JOIN SCM_MGR.SCM_MST_SSO_DEPT_INFO N ON C.DEPT_ID = N.DEPT_ID ' ||
        CHR(10) || ' --[PJ2024-50461] Team Mapping------------------------------------ ' ||
        CHR(10) || ' LEFT OUTER JOIN SCM_MGR.SCM_MST_SSO_DEPT_INFO O ON N.UPPER_DEPT_ID = O.DEPT_ID ' ||
        CHR(10) || ' JOIN SCM_MGR.GT_DM35_CALENDAR CAL ON A.YYYYMMDD = CAL.BASIS_YYYYMMDD ' ||
        CHR(10) || ' LEFT OUTER JOIN SCM_MGR.GT_DM35_CAL_MONTH_END C2 ON A.YYYYMMDD = C2.MONTH_END_DATE ' ||
        CHR(10) || ' LEFT OUTER JOIN SCM_MGR.GT_DM35_CAL_WEEK_END C3 ON A.YYYYMMDD = C3.WEEK_END_DATE ' ||
        CHR(10) || ' LEFT OUTER JOIN SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL EE ' ||
        CHR(10) || ' ON EE.LOOKUP_TYPE = ''SP_CELL_PROD_SITE'' ' ||
        CHR(10) || ' AND EE.SEGMENT1 = CASE WHEN LENGTH(NVL(A.CELL_PROD_SITE_ID,'''')) = 0 THEN ''-'' ELSE A.CELL_PROD_SITE_ID END -- [PJ2025-50017] CELL_PROD_SITE_ID 추가 ' ||    -- MS 원본이 '-'    --  2026.10.12 AJS
        CHR(10) || ' AND EE.SEGMENT2 = ''-'' AND EE.SEGMENT3 = ''-'' AND EE.SEGMENT4 = ''-'' AND EE.SEGMENT5 = ''-'' AND EE.VALID_YN = ''Y'' ' ||
        CHR(10) || ' )'
        ;

    -- Oracle에서는 MSSQL의 SELECT ... INTO #WF 를 Dynamic SQL 내부에서 처리할 수 없으므로
    -- #WF 해당하는 집계 결과를 직접 PIVOT 쿼리로 구성하여 O_RC1 커서로 반환한다.
    -- (Oracle에는 PIVOT 구문이 있으나 동적 컬럼은 Dynamic SQL로 처리)

    -- Dynamic SQL 최종 구성 (PIVOT 포함)
    IF P_DIVISION_ID = '40'
    THEN
        V_SQL_TEXT := V_SQL_TEXT ||
            ' SELECT ' || V_COL_LIST || ', EDIT_YN, ' || V_PV_COL ||
            CHR(10) || ' FROM ( ';
    ELSE
        V_SQL_TEXT := V_SQL_TEXT ||
            ' SELECT ' || V_COL_LIST || ', EDIT_YN, ' || V_PV_LIST ||
            CHR(10) || ' FROM ( ';
    END IF;

    IF P_BUCKET = 'DAILY'
    THEN
        V_SQL_TEXT := V_SQL_TEXT ||
            CHR(10) || ' SELECT ' || V_COL_LIST || ', ''D_'' || F.YYYYMMDD AS YYYYMMDD, F.QTY, F.EDIT_YN ' ||
            CHR(10) || ' FROM   T_WF_DATA F ' ||
            CHR(10) || ' WHERE F.QTY <> 0 ' ||
            CHR(10) || ' UNION ALL ';
    END IF;

    IF P_BUCKET != 'ONLY_WEEKLY'
    THEN
        V_SQL_TEXT := V_SQL_TEXT ||
            CHR(10) || ' SELECT ' || V_COL_LIST || ', YYYYMMDD , SUM(QTY) AS QTY , EDIT_YN' ||
            CHR(10) || ' FROM   ( ' ||
            CHR(10) || ' SELECT ' || V_COL_LIST || ', ''W_'' || F.BASIS_YYYYMM || F.ISO_WEEK AS YYYYMMDD, F.EDIT_YN ' ||
   --[E20260910-LOCAVG] AS-IS 원형 복원 (사용자 지시 2026-09-10)
            CHR(10) || '     , CASE WHEN F.MEASURE IN (''BALANCE'', ''VMI_Inv'', ''AS_Inv'', ''SS_LVL'', ''SS_GAP'') THEN'||
            CHR(10) || '                     CASE WHEN F.WEEK_END_YN = ''Y'' THEN SUM(F.QTY) ELSE 0 END  ' ||
            CHR(10) || '                WHEN F.MEASURE = ''LOC'' THEN AVG(F.QTY) ' ||
            CHR(10) || '                ELSE SUM(F.QTY) END AS QTY ' ||
            CHR(10) || ' FROM T_WF_DATA F ' ||
            CHR(10) || ' WHERE F.QTY <> 0 ' ||
            CHR(10) || ' GROUP BY ' || V_COL_LIST || ', F.BASIS_YYYYMM, F.ISO_WEEK, F.WEEK_END_YN, F.EDIT_YN ' ||
            CHR(10) || ' UNION ALL ' ||
            CHR(10) || ' SELECT ' || V_COL_LIST || ', ''M_'' || F.BASIS_YYYYMM AS YYYYMMDD, F.EDIT_YN ' ||
   --[E20260910-LOCAVG] AS-IS 원형 복원 (사용자 지시 2026-09-10)
            CHR(10) || '     , CASE WHEN F.MEASURE IN (''BALANCE'', ''VMI_Inv'', ''AS_Inv'', ''SS_LVL'', ''SS_GAP'') THEN'||
            CHR(10) || '                     CASE WHEN F.MONTH_END_YN = ''Y'' THEN SUM(F.QTY) ELSE 0 END  ' ||
            CHR(10) || '                WHEN F.MEASURE = ''LOC'' THEN AVG(F.QTY) ' ||
            CHR(10) || '                ELSE SUM(F.QTY) END AS QTY ' ||
            CHR(10) || ' FROM T_WF_DATA F ' ||
            CHR(10) || ' WHERE F.QTY <> 0 ' ||
            CHR(10) || ' GROUP BY ' || V_COL_LIST || ', F.BASIS_YYYYMM, F.MONTH_END_YN, F.EDIT_YN ' ||
            CHR(10) || ' ) GROUP BY ' || V_COL_LIST || ', YYYYMMDD, EDIT_YN ';
    ELSIF P_BUCKET = 'ONLY_WEEKLY'
    THEN
        V_SQL_TEXT := V_SQL_TEXT ||
            CHR(10) || ' SELECT ' || V_COL_LIST || ', YYYYMMDD , SUM(QTY) AS QTY, EDIT_YN' ||
            CHR(10) || ' FROM   ( ' ||
            CHR(10) || ' SELECT ' || V_COL_LIST || ', ''W_'' || F.BASIS_YYYYMMWW AS YYYYMMDD, F.EDIT_YN ' ||
   --[E20260910-LOCAVG] AS-IS 원형 복원 (사용자 지시 2026-09-10)
            CHR(10) || '     , CASE WHEN F.MEASURE IN (''BALANCE'', ''VMI_Inv'', ''AS_Inv'', ''SS_LVL'', ''SS_GAP'') THEN'||
            CHR(10) || '                     CASE WHEN F.WEEK_END_YN = ''Y'' THEN SUM(F.QTY) ELSE 0 END  ' ||
            CHR(10) || '                WHEN F.MEASURE = ''LOC'' THEN AVG(F.QTY) ' ||
            CHR(10) || '                ELSE SUM(F.QTY) END AS QTY ' ||
            CHR(10) || ' FROM T_WF_DATA F ' ||
            CHR(10) || ' WHERE F.QTY <> 0 ' ||
            CHR(10) || ' GROUP BY ' || V_COL_LIST || ', F.BASIS_YYYYMMWW, F.ISO_WEEK, F.WEEK_END_YN, F.EDIT_YN ' ||
            CHR(10) || ' ) GROUP BY ' || V_COL_LIST || ', YYYYMMDD, EDIT_YN ';
    END IF;

    V_SQL_TEXT := V_SQL_TEXT ||
        CHR(10) || ' ) F ' ||
        CHR(10) || ' PIVOT (SUM(QTY) FOR YYYYMMDD IN (' || V_PV_COL_LIST || ')) PVT ' ||
        CHR(10) || ' ORDER BY ' || V_ORDER_LIST;

    -- Oracle에서 Dynamic SQL은 DBMS_SQL 또는 OPEN RC FOR로 반환
    -- WF_DATA는 GT_DM35_RAW_DATA_FINAL 기반 인라인 뷰로 처리
    N_LOG_COUNT   := SQL%ROWCOUNT;
    V_LOG_TYPE    := 'INFO';
    V_LOG_MESSAGE := 'H_p--';
    D_EVENT_DATE  := SYSDATE;
    BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE); END;

    -- V_SQL_TEXT 내 플레이스홀더 치환 (Oracle: [] 브래킷은 열 별칭에만 사용, 실제 쿼리에서는 제거)
    /*V_SQL_TEXT := REPLACE(V_SQL_TEXT, '[@v_PV_COL_LIST]', V_PV_LIST);
    V_SQL_TEXT := REPLACE(V_SQL_TEXT, '[@v_PV_LIST]',     V_PV_LIST);
    V_SQL_TEXT := REPLACE(V_SQL_TEXT, '[@v_column]',      V_SQL_SELECT);
    V_SQL_TEXT := REPLACE(V_SQL_TEXT, '[@v_orderby]',     V_ORDER_LIST);
    V_SQL_TEXT := REPLACE(V_SQL_TEXT, '[@SQL_SELECT]',    V_SQL_SELECT);
    V_SQL_TEXT := REPLACE(V_SQL_TEXT, '[@SQL_GROUPBY]',   V_SQL_GROUPBY);
    V_SQL_TEXT := REPLACE(V_SQL_TEXT, '[@CellQtyYN]',     P_CELL_YN);*/

    DBMS_OUTPUT.ENABLE(1000000);

    DBMS_OUTPUT.PUT_LINE('=============================');
    DBMS_OUTPUT.PUT_LINE('V_PV_LIST : '||V_PV_LIST ||CHR(10)||CHR(10));
    DBMS_OUTPUT.PUT_LINE('V_PV_COL_LIST : '||V_PV_COL_LIST ||CHR(10)||CHR(10));
    DBMS_OUTPUT.PUT_LINE('V_PV_COL : '||V_PV_COL ||CHR(10)||CHR(10));
    DBMS_OUTPUT.PUT_LINE('V_COL_LIST : '||V_COL_LIST ||CHR(10)||CHR(10));
    DBMS_OUTPUT.PUT_LINE('V_ORDER_LIST :'||V_ORDER_LIST ||CHR(10)||CHR(10));
    DBMS_OUTPUT.PUT_LINE('V_SQL_SELECT :'||V_SQL_SELECT ||CHR(10)||CHR(10));
    DBMS_OUTPUT.PUT_LINE('V_SQL_GROUPBY :'||V_SQL_GROUPBY ||CHR(10)||CHR(10));
    DBMS_OUTPUT.PUT_LINE('=============================');


    DBMS_OUTPUT.PUT_LINE(v_sql_text);

    -- RC1: 메인 결과셋 (Pivot 결과)
    OPEN O_RC1 FOR V_SQL_TEXT;

    -- RC2: 현재 주차/날짜 정보
    OPEN O_RC2 FOR
        SELECT ISO_WEEK, BASIS_DATE
        FROM SCM_MGR.SCM_SYS_CALENDAR_M
        WHERE BASIS_YYYYMMDD = TO_CHAR(SYSDATE, 'YYYYMMDD');

    -- 테스트용 코드
    --OPEN O_RC2 FOR SELECT ISO_WEEK, BASIS_DATE FROM SCM_MGR.SCM_SYS_CALENDAR_M WHERE BASIS_YYYYMMDD = '20220725';

    N_LOG_COUNT   := SQL%ROWCOUNT;
    V_LOG_TYPE    := 'INFO';
    V_LOG_MESSAGE := 'I--';
    D_EVENT_DATE  := SYSDATE;
    BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE); END;

    -- 20190711 정렬 관련 추가 (주석처리된 원본 코드)
    /*
    DECLARE V_ORDER VARCHAR2(32767 CHAR) := '';
    --SELECT @ORDER = @ORDER + T1.COLUMN_NAME + ' ' + T1.DATA_SORT_METHOD_CODE + ','
    FROM ....
    */

    /* 2024/05/17   kcw3408   이동계획 판가 매출GROUP_ID( Item은 Group 기준으로 정렬) 추가) */
    /*
     kjj 수정(2024.6.24)
     - GROUP_ID 화면표시 위해 [SCM_MST_TITLESET_USER] 조인 추가
     - ITEM_ID의 정렬보다 무조건 바로 앞에 GROUP_ID가 위치하게
     =>2024.06.25. 불필요한 정렬이므로 위의 정렬 값 그대로 리턴..추후 화면에서도 제거해야 함
    */

    -- 정렬 컬럼 문자열에서 브래킷 제거
    V_ORDER_LIST := REPLACE(V_ORDER_LIST, '[', '');
    V_ORDER_LIST := REPLACE(V_ORDER_LIST, ']', '');

    -- RC3: 정렬 컬럼 정보 반환
    -- (O_RESULT_CURSOR로 성공 반환)
    OPEN O_RC3 FOR
        SELECT V_ORDER_LIST FROM DUAL;

    N_LOG_COUNT   := SQL%ROWCOUNT;
    V_LOG_TYPE    := 'INFO';
    V_LOG_MESSAGE := 'J--';
    D_EVENT_DATE  := SYSDATE;
    BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE); END;

    COMMIT;

    -- RC3: 정렬 컬럼 정보 반환
    -- (O_RESULT_CURSOR로 성공 반환)
    OPEN O_RESULT_CURSOR FOR
        SELECT '0' AS CODE, 'SUCCESS' AS MSG, NULL AS EVENT FROM DUAL;

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;

        V_LOG_TYPE    := 'ERROR';
        V_LOG_MESSAGE := 'EXCEPTION';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        V_SQL_CODE    := TO_CHAR(SQLCODE);
        V_SQL_ERRMSG  := SQLERRM;
        V_PROC_INPUT  := JSON_OBJECT(
            'P_DIVISION_ID'  VALUE P_DIVISION_ID,
            'P_DEPT_ID'      VALUE P_DEPT_ID,
            'P_END_CUSTOMER' VALUE P_END_CUSTOMER,
            'P_SCM_SITE_ID'  VALUE P_SCM_SITE_ID,
            'P_PROJECT_CODE' VALUE P_PROJECT_CODE,
            'P_ITEM_ID'      VALUE P_ITEM_ID,
            'P_ITEM_TYPE'    VALUE P_ITEM_TYPE,
            'P_FROM_YYYYMMDD' VALUE P_FROM_YYYYMMDD,
            'P_TO_YYYYMMDD'  VALUE P_TO_YYYYMMDD,
            'P_CREATED_BY'   VALUE P_CREATED_BY,
            'P_PLANT_SITE_ID' VALUE P_PLANT_SITE_ID,
            'P_BIZ_TYPE'     VALUE P_BIZ_TYPE,
            'P_OWNER'        VALUE P_OWNER,
            'P_VERSION_NO'   VALUE P_VERSION_NO,
            'P_BUCKET'       VALUE P_BUCKET,
            'P_USER_DEPT_ID' VALUE P_USER_DEPT_ID,
            'P_GROUP_ID'     VALUE P_GROUP_ID,
            'P_CELL_YN'      VALUE P_CELL_YN,
            'P_SENDER_CODE'  VALUE P_SENDER_CODE
        );
        V_BACKTRACE   := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;

        BEGIN
            SCM_MGR.PR_SCM_SYS_LOG_BATCH(
                V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE,
                V_DESCRIPTION, D_EVENT_DATE, V_PROC_INPUT,
                V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE
            );
        END;

        RAISE_APPLICATION_ERROR(-20001,
            '[' || V_PROGRAM_NAME || '] SQLCODE=' || V_SQL_CODE ||
            ' / SQLERRM=' || V_SQL_ERRMSG ||
            ' / BACKTRACE=' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE ||
            ' / PARAMS=' || V_PROC_INPUT
        );
END P_DMF0035_GET_MKT_FCST_WATERFALL;


-- [E20260806-WF] SPREAD_TITLE 합류 본문 (standalone 원문 무수정, 헤더/END 개명만)
PROCEDURE P_DMF0035_GET_SPREAD_TITLE
(
    P_START_YYYYMMDD  IN VARCHAR2,
    P_END_YYYYMMDD    IN VARCHAR2,
    P_CREATED_BY      IN VARCHAR2,
    P_DIVISION_ID     IN VARCHAR2,
    P_BUCKET          IN VARCHAR2,
    O_RC1             OUT SYS_REFCURSOR,
    O_RESULT_CURSOR   OUT SYS_REFCURSOR
)
---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
/****************************************************************************************************/
/* Program ID  : DM0035_GET_SPREAD_TITLE                                                             */
/* Description : Procedure 작성 가이드                                                              */
/* Usage       : Procedure 작성 시 참조하세요!                                                      */
/* Parameter   :                                                                                    */
/*                                                                                                  */
/*--------------------------------------------------------------------------------------------------*/
/* Date        In Charge    Description                                                             */
/*--------------------------------------------------------------------------------------------------*/
/* 2018/02/05  pjs       Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트 */
/* 2019/02/01	JYE		42, 44 추가                          */
/* 2021/11/03	rosia27		MKT FCST WATERFALL 속도개선												*/
/*
 * 2022/07/19	kdw2819		[C20220620-000567]GSCM DM 시스템의 수작업 LOSS 및 분석 용이하기 하귀 위한 기능 개선 ( Partail week의 경우 week만 표시)
 */
/* 2026.03.18   jcnam        [PJ20264226] NextSCM Pilot 설계 및 개발                                  */
/****************************************************************************************************/
/*****************************************************************************************************
 ※ 작성 Rule
   1. 대문자, 소문자
      - 테이블, 컬럼, 변수는 소문자로 작성하고, 그 이외는 대문자로 통일
   2. Naming Rule - Prefix
      - 파라메터 : @p_
      - 변수 : 데이타 타입에 따라 @v_(문자), @n_(숫자), @d_(날짜)
   3. 들여쓰기 : 2 space
   4. 기타
      - SQL 수직 배치 : SQL 구문의 세로줄(왼쪽)로 맞춤, 컬럼이나 변수도 KEYWORD 이후 왼쪽 정렬
      - 콤마로 분리된 ID 가 여러 줄에 걸쳐 나올 때, 콤마를 라인의 처음에 위치
******************************************************************************************************/
IS

    V_USER_COL_CNT    PLS_INTEGER := 0;
    V_PROGRAM_ID      VARCHAR2(50 CHAR) := 'DMF0035';
    V_SHEET_NAME      VARCHAR2(50 CHAR) := 'Mkt Fcst Waterfall';
    V_TITLESET_SHEET  VARCHAR2(50 CHAR) := 'Mkt Fcst Waterfall';  --[E20260909-SHEETUNIFY] TITLESET_USER 실등록명 (구 'mktFcstWaterfall' = 미등록명)

    /* ── EXCEPTION 블록 필수 변수 ── */
    V_PROC_INPUT    VARCHAR2(4000 CHAR);
    V_BACKTRACE     VARCHAR2(4000 CHAR);
    V_SQL_CODE      VARCHAR2(100 CHAR);
    V_SQL_ERRMSG    VARCHAR2(1000 CHAR);
    V_LOG_TYPE      VARCHAR2(100 CHAR);
    V_LOG_MESSAGE   VARCHAR2(4000 CHAR);
    V_DESCRIPTION   VARCHAR2(4000 CHAR);
    N_LOG_COUNT     PLS_INTEGER := 0;
    D_EVENT_DATE    DATE := SYSDATE;

BEGIN

    /* ── 시작 로그 ── */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## START of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH($$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE); END;

    /* ── 사용자 컬럼 설정 건수 조회 (Case 28/29: EXISTS 패턴) ── */
    BEGIN
        SELECT 1
        INTO   V_USER_COL_CNT
        FROM   DUAL
        WHERE  EXISTS (
            SELECT 1
            FROM   SCM_MST_TITLESET_USER U
            WHERE  1 = 1
            AND    U.PROGRAM_ID = V_PROGRAM_ID
            AND    U.SHEET_NAME = V_TITLESET_SHEET
            AND    U.USER_INQUIRY_COLUMN_TYPE_CODE = 'C'
            AND    U.USER_ID    = P_CREATED_BY
        );
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            V_USER_COL_CNT := 0;
    END;

    /* ── 메인 조회 결과 반환 (O_RC1) ── */
    IF V_USER_COL_CNT > 0 THEN

        OPEN O_RC1 FOR
        SELECT * FROM (
            /* ── 사용자 설정 컬럼 ── */
            SELECT U.PROGRAM_ID
                 , U.SHEET_NAME
                 , U.COLUMN_NAME
                 , C.COLUMN_LABEL_NAME
                 , TO_CHAR(U.SORT_ORDER_NO) AS SORT_ORDER_NO        --CONVERT(NVARCHAR(10), U.SORT_ORDER_NO) AS SORT_ORDER_NO
                 , U.DATA_SORT_METHOD_CODE
                 , C.SMALL_CLASS_LABEL_NAME
                 , C.LARGE_CLASS_LABEL_NAME
                 , '' AS DAY_CODE
                 , C.FIXED_FLAG
                 , C.COLUMN_WIDTH
                 , C.CELL_CONTROL_OBJECT_TYPE_CODE
                 , C.CELL_COMBO_DATA_TYPE
                 , TO_CHAR(C.DATA_SCALE_NUMBER) AS DATA_SCALE_NUMBER
                 , TO_CHAR(C.DATA_MAX_LENGTH) AS DATA_MAX_LENGTH
                 , C.HORIZONTAL_ALIGN_CODE
                 , C.UPPERCASE_APPLY_FLAG
                 , C.VISIBLE_FLAG
                 , C.DEFAULT_FLAG
                 , C.USER_SELECTABLE_FLAG
                 , C.VALID_YN
                 , C.DIVISION_ID
            FROM   SCM_MST_TITLESET_USER U
                 , SCM_MST_SHEET_COLUMNS C
            WHERE  1 = 1
            AND    U.PROGRAM_ID  = C.PROGRAM_ID
            AND    C.SHEET_NAME  = V_SHEET_NAME
            AND    U.COLUMN_NAME = C.COLUMN_NAME
            AND    U.PROGRAM_ID  = V_PROGRAM_ID
            AND    U.SHEET_NAME  = V_TITLESET_SHEET
            AND    U.USER_ID     = P_CREATED_BY
            AND    U.USER_INQUIRY_COLUMN_TYPE_CODE = 'C'
            AND    INSTR(',' || C.DIVISION_ID || ',', ',' || P_DIVISION_ID || ',') > 0

            UNION ALL

            /* ── 비노출 기본 컬럼 ── */
            SELECT C.PROGRAM_ID
                 , C.SHEET_NAME
                 , C.COLUMN_NAME
                 , C.COLUMN_LABEL_NAME
                 , TO_CHAR(C.SORT_ORDER_NO) AS SORT_ORDER_NO        --CONVERT(NVARCHAR(10), U.SORT_ORDER_NO) AS SORT_ORDER_NO
                 , C.DATA_SORT_METHOD_CODE
                 , C.SMALL_CLASS_LABEL_NAME
                 , C.LARGE_CLASS_LABEL_NAME
                 , '' AS DAY_CODE
                 , C.FIXED_FLAG
                 , C.COLUMN_WIDTH
                 , C.CELL_CONTROL_OBJECT_TYPE_CODE
                 , C.CELL_COMBO_DATA_TYPE
                 , TO_CHAR(C.DATA_SCALE_NUMBER) AS DATA_SCALE_NUMBER
                 , TO_CHAR(C.DATA_MAX_LENGTH) AS DATA_MAX_LENGTH
                 , C.HORIZONTAL_ALIGN_CODE
                 , C.UPPERCASE_APPLY_FLAG
                 , C.VISIBLE_FLAG
                 , C.DEFAULT_FLAG
                 , C.USER_SELECTABLE_FLAG
                 , C.VALID_YN
                 , C.DIVISION_ID
            FROM   SCM_MST_SHEET_COLUMNS C
            WHERE  1 = 1
            AND    C.PROGRAM_ID  = V_PROGRAM_ID
            AND    C.SHEET_NAME  = V_SHEET_NAME
            AND    C.VISIBLE_FLAG = 'N'
            AND    RTRIM(C.DEFAULT_FLAG, ' -') IS NULL  --[E20260831-W34] AS-IS DEFAULT_FLAG='' 숨은컬럼 arm — ''=NULL(' '/'-' 흡수) 정정
            AND    C.VALID_YN     = 'Y'
            AND    INSTR(',' || C.DIVISION_ID || ',', ',' || P_DIVISION_ID || ',') > 0

            UNION ALL

            /* ── 캘린더 동적 컬럼 ── */
            SELECT V_PROGRAM_ID   AS PROGRAM_ID
                 , V_SHEET_NAME AS SHEET_NAME
                 , T.COLUMN_NAME
                 , T.COLUMN_LABEL_NAME
                 , T.SORT_ORDER_NO
                 , ''         AS DATA_SORT_METHOD_CODE
                 , T.SMALL_CLASS_LABEL_NAME
                 , T.LARGE_CLASS_LABEL_NAME
                 , T.DAY_CODE
                 , ''         AS FIXED_FLAG
                 , CASE WHEN P_BUCKET = 'ONLY_WEEKLY' THEN 100
                        ELSE 50 END AS COLUMN_WIDTH
                 , 'FPNumber' AS CELL_CONTROL_OBJECT_TYPE_CODE
                 , ''         AS CELL_COMBO_DATA_TYPE
                 , ''         AS DATA_SCALE_NUMBER
                 , ''         AS DATA_MAX_LENGTH
                 , 'R'        AS HORIZONTAL_ALIGN_CODE
                 , 'Y'        AS UPPERCASE_APPLY_FLAG
                 , 'Y'        AS VISIBLE_FLAG
                 , ''         AS DEFAULT_FLAG
                 , ''         AS USER_SELECTABLE_FLAG
                 , ''         AS VALID_YN
                 --, CASE WHEN CHARINDEX('81', @p_divisIon_id) > 0 OR CHARINDEX('82', @p_divisIon_id) > 0 THEN
                    --  CASE WHEN CHARINDEX('40', @p_divisIon_id) > 0 THEN '40,81,82'
                    --       ELSE '81,82' END
                 --  ELSE
                    --  '40'
                 --  END AS DIVISION_ID
                 , P_DIVISION_ID AS DIVISION_ID      -- 20190201
            FROM  (
                   SELECT 'D_' || A.BASIS_YYYYMMDD   AS COLUMN_NAME
                        , A.CALENDAR_DAY            AS COLUMN_LABEL_NAME
                        , A.WEEK_NAME               AS SMALL_CLASS_LABEL_NAME
                        , A.MONTH_NAME              AS LARGE_CLASS_LABEL_NAME
                        , A.DAYOFWEEK               AS DAY_CODE
                        , A.BASIS_YYYYMMDD || TO_CHAR(31) AS SORT_ORDER_NO
                   FROM   SCM_SYS_CALENDAR_M A
                   WHERE  A.BASIS_YYYYMMDD >= P_START_YYYYMMDD --CONVERT(CHAR(8), CURRENT_TIMESTAMP, 112)
                   AND    A.BASIS_YYYYMMDD <= P_END_YYYYMMDD --CONVERT(CHAR(8), DATEADD(YYYY, 1, CURRENT_TIMESTAMP), 112)
                   AND    1 = CASE WHEN P_BUCKET = 'DAILY' THEN 1 ELSE 2 END
                   UNION ALL
                   SELECT 'W_' || A.BASIS_YYYYMM || A.ISO_WEEK   AS COLUMN_NAME
                        , A.WEEK_NAME          AS COLUMN_LABEL_NAME
                        , A.WEEK_NAME          AS SMALL_CLASS_LABEL_NAME
                        , A.MONTH_NAME         AS LARGE_CLASS_LABEL_NAME
                        , ''                   AS DAY_CODE
                        , A.BASIS_START_DATE || TO_CHAR(21) AS SORT_ORDER_NO
                   FROM   SCM_SYS_CALENDAR_M A
                   WHERE  A.BASIS_YYYYMMDD >= P_START_YYYYMMDD --CONVERT(CHAR(8), CURRENT_TIMESTAMP, 112)
                   AND    A.BASIS_YYYYMMDD <= P_END_YYYYMMDD --CONVERT(CHAR(8), DATEADD(YYYY, 1, CURRENT_TIMESTAMP), 112)
                   AND    1 = CASE WHEN P_BUCKET != 'ONLY_WEEKLY' THEN 1 ELSE 2 END
                   GROUP BY A.BASIS_YYYYMM
                          , A.ISO_WEEK
                          , A.WEEK_NAME
                          , A.MONTH_NAME
                          , A.BASIS_START_DATE
                   UNION ALL
                   SELECT 'M_' || A.BASIS_YYYYMM  AS COLUMN_NAME
                         , A.MONTH_NAME          AS COLUMN_LABEL_NAME
                         , A.MONTH_NAME          AS SMALL_CLASS_LABEL_NAME
                         , A.MONTH_NAME          AS LARGE_CLASS_LABEL_NAME
                         , ''                    AS DAY_CODE
                         , MIN(A.BASIS_START_DATE) || '01' AS SORT_ORDER_NO
                   FROM    SCM_SYS_CALENDAR_M A
                   WHERE  A.BASIS_YYYYMMDD >= P_START_YYYYMMDD --CONVERT(CHAR(8), CURRENT_TIMESTAMP, 112)
                   AND    A.BASIS_YYYYMMDD <= P_END_YYYYMMDD --CONVERT(CHAR(8), DATEADD(YYYY, 1, CURRENT_TIMESTAMP), 112)
                   AND    1 = CASE WHEN P_BUCKET != 'ONLY_WEEKLY' THEN 1 ELSE 2 END
                   GROUP BY A.BASIS_YYYYMM
                          , A.MONTH_NAME
                   -- [C20220620-000567]GSCM DM 시스템의 수작업 LOSS 및 분석 용이하기 하귀 위한 기능 개선 ( Partail week의 경우 week만 표시)
                   UNION ALL
                   SELECT 'W_' || SUBSTR(MAX(BASIS_YYYYMMDD), 1, 6) || ISO_WEEK AS COLUMN_NAME
                         , WEEK_NAME AS COLUMN_LABEL_NAME
                         , WEEK_NAME AS SMALL_CLASS_LABEL_NAME
                         , SUBSTR(MIN(BASIS_YYYYMMDD), 5, 2) || '.' || SUBSTR(MIN(BASIS_YYYYMMDD), 7, 2)
                         || ' ~ ' || SUBSTR(MAX(BASIS_YYYYMMDD), 5, 2) || '.' || SUBSTR(MAX(BASIS_YYYYMMDD), 7, 2)  AS LARGE_CLASS_LABEL_NAME
                         , ''                   AS DAY_CODE
                         , MAX(BASIS_YYYYMMDD) || TO_CHAR(21) AS SORT_ORDER_NO
                   FROM   SCM_SYS_CALENDAR_M A
                   WHERE  A.BASIS_YYYYMMDD >= P_START_YYYYMMDD
                   AND    A.BASIS_YYYYMMDD <= P_END_YYYYMMDD
                   AND    1 = CASE WHEN P_BUCKET = 'ONLY_WEEKLY' THEN 1 ELSE 2 END
                   GROUP BY ISO_YYYYWW, ISO_WEEK, WEEK_NAME
              ) T
        ) A
        WHERE INSTR(',' || A.DIVISION_ID || ',', ',' || P_DIVISION_ID || ',') > 0
        ORDER BY SORT_ORDER_NO;

    ELSE
        /* ── V_USER_COL_CNT = 0 : 기본 컬럼 설정 ── */
        OPEN O_RC1 FOR
        SELECT C.PROGRAM_ID
             , C.SHEET_NAME
             , C.COLUMN_NAME
             , C.COLUMN_LABEL_NAME
             , TO_CHAR(C.SORT_ORDER_NO) AS SORT_ORDER_NO        --CONVERT(NVARCHAR(10), U.SORT_ORDER_NO) AS SORT_ORDER_NO
             , C.DATA_SORT_METHOD_CODE
             , C.SMALL_CLASS_LABEL_NAME
             , C.LARGE_CLASS_LABEL_NAME
             , '' AS DAY_CODE
             , C.FIXED_FLAG
             , C.COLUMN_WIDTH
             , C.CELL_CONTROL_OBJECT_TYPE_CODE
             , C.CELL_COMBO_DATA_TYPE
             , TO_CHAR(C.DATA_SCALE_NUMBER) AS DATA_SCALE_NUMBER
             , TO_CHAR(C.DATA_MAX_LENGTH) AS DATA_MAX_LENGTH
             , C.HORIZONTAL_ALIGN_CODE
             , C.UPPERCASE_APPLY_FLAG
             , C.VISIBLE_FLAG
             , C.DEFAULT_FLAG
             , C.USER_SELECTABLE_FLAG
             , C.VALID_YN
             , C.DIVISION_ID
        FROM   SCM_MST_SHEET_COLUMNS C
        WHERE  1 = 1
        AND    C.PROGRAM_ID  = V_PROGRAM_ID
        AND    C.SHEET_NAME  = V_SHEET_NAME
        AND    C.DEFAULT_FLAG = 'Y'
        AND    C.VALID_YN     = 'Y'
        AND    INSTR(',' || C.DIVISION_ID || ',', ',' || P_DIVISION_ID || ',') > 0

        UNION ALL

        SELECT * FROM (
            /* ── 비노출 기본 컬럼 ── */
            SELECT C.PROGRAM_ID
                 , C.SHEET_NAME
                 , C.COLUMN_NAME
                 , C.COLUMN_LABEL_NAME
                 , TO_CHAR(C.SORT_ORDER_NO) AS SORT_ORDER_NO        --CONVERT(NVARCHAR(10), U.SORT_ORDER_NO) AS SORT_ORDER_NO
                 , C.DATA_SORT_METHOD_CODE
                 , C.SMALL_CLASS_LABEL_NAME
                 , C.LARGE_CLASS_LABEL_NAME
                 , '' AS DAY_CODE
                 , C.FIXED_FLAG
                 , C.COLUMN_WIDTH
                 , C.CELL_CONTROL_OBJECT_TYPE_CODE
                 , C.CELL_COMBO_DATA_TYPE
                 , TO_CHAR(C.DATA_SCALE_NUMBER) AS DATA_SCALE_NUMBER
                 , TO_CHAR(C.DATA_MAX_LENGTH) AS DATA_MAX_LENGTH
                 , C.HORIZONTAL_ALIGN_CODE
                 , C.UPPERCASE_APPLY_FLAG
                 , C.VISIBLE_FLAG
                 , C.DEFAULT_FLAG
                 , C.USER_SELECTABLE_FLAG
                 , C.VALID_YN
                 , C.DIVISION_ID
            FROM   SCM_MST_SHEET_COLUMNS C
            WHERE  1 = 1
            AND    C.PROGRAM_ID  = V_PROGRAM_ID
            AND    C.SHEET_NAME  = V_SHEET_NAME
            AND    C.VISIBLE_FLAG = 'N'
            AND    RTRIM(C.DEFAULT_FLAG, ' -') IS NULL  --[E20260831-W34] AS-IS DEFAULT_FLAG='' 숨은컬럼 arm — ''=NULL(' '/'-' 흡수) 정정
            AND    C.VALID_YN     = 'Y'
            AND    INSTR(',' || C.DIVISION_ID || ',', ',' || P_DIVISION_ID || ',') > 0

            UNION ALL

            /* ── 캘린더 동적 컬럼 ── */
            SELECT V_PROGRAM_ID   AS PROGRAM_ID
                 , V_SHEET_NAME AS SHEET_NAME
                 , T.COLUMN_NAME
                 , T.COLUMN_LABEL_NAME
                 , T.SORT_ORDER_NO
                 , ''         AS DATA_SORT_METHOD_CODE
                 , T.SMALL_CLASS_LABEL_NAME
                 , T.LARGE_CLASS_LABEL_NAME
                 , T.DAY_CODE
                 , ''         AS FIXED_FLAG
                 , CASE WHEN P_BUCKET = 'ONLY_WEEKLY' THEN 100
                        ELSE 50 END AS COLUMN_WIDTH
                 , 'FPNumber' AS CELL_CONTROL_OBJECT_TYPE_CODE
                 , ''         AS CELL_COMBO_DATA_TYPE
                 , ''         AS DATA_SCALE_NUMBER
                 , ''         AS DATA_MAX_LENGTH
                 , 'R'        AS HORIZONTAL_ALIGN_CODE
                 , 'Y'        AS UPPERCASE_APPLY_FLAG
                 , 'Y'        AS VISIBLE_FLAG
                 , ''         AS DEFAULT_FLAG
                 , ''         AS USER_SELECTABLE_FLAG
                 , ''         AS VALID_YN
                 --, CASE WHEN CHARINDEX('81', @p_divisIon_id) > 0 OR CHARINDEX('82', @p_divisIon_id) > 0 THEN
                    --  CASE WHEN CHARINDEX('40', @p_divisIon_id) > 0 THEN '40,81,82'
                    --       ELSE '81,82' END
                 --  ELSE
                    --  '40'
                 --  END AS DIVISION_ID
                 , P_DIVISION_ID AS DIVISION_ID      -- 20190201
            FROM  (
                   SELECT 'D_' || A.BASIS_YYYYMMDD   AS COLUMN_NAME
                        , A.CALENDAR_DAY            AS COLUMN_LABEL_NAME
                        , A.WEEK_NAME               AS SMALL_CLASS_LABEL_NAME
                        , A.MONTH_NAME              AS LARGE_CLASS_LABEL_NAME
                        , A.DAYOFWEEK               AS DAY_CODE
                        , A.BASIS_YYYYMMDD || TO_CHAR(31) AS SORT_ORDER_NO
                   FROM   SCM_SYS_CALENDAR_M A
                   WHERE  A.BASIS_YYYYMMDD >= P_START_YYYYMMDD --CONVERT(CHAR(8), CURRENT_TIMESTAMP, 112)
                   AND    A.BASIS_YYYYMMDD <= P_END_YYYYMMDD --CONVERT(CHAR(8), DATEADD(YYYY, 1, CURRENT_TIMESTAMP), 112)
                   AND    1 = CASE WHEN P_BUCKET = 'DAILY' THEN 1 ELSE 2 END
                   UNION ALL
                   SELECT 'W_' || A.BASIS_YYYYMM || A.ISO_WEEK   AS COLUMN_NAME
                        , A.WEEK_NAME          AS COLUMN_LABEL_NAME
                        , A.WEEK_NAME          AS SMALL_CLASS_LABEL_NAME
                        , A.MONTH_NAME         AS LARGE_CLASS_LABEL_NAME
                        , ''                   AS DAY_CODE
                        , A.BASIS_START_DATE || TO_CHAR(21) AS SORT_ORDER_NO
                   FROM   SCM_SYS_CALENDAR_M A
                   WHERE  A.BASIS_YYYYMMDD >= P_START_YYYYMMDD --CONVERT(CHAR(8), CURRENT_TIMESTAMP, 112)
                   AND    A.BASIS_YYYYMMDD <= P_END_YYYYMMDD --CONVERT(CHAR(8), DATEADD(YYYY, 1, CURRENT_TIMESTAMP), 112)
                   AND    1 = CASE WHEN P_BUCKET != 'ONLY_WEEKLY' THEN 1 ELSE 2 END
                   GROUP BY A.BASIS_YYYYMM
                          , A.ISO_WEEK
                          , A.WEEK_NAME
                          , A.MONTH_NAME
                          , A.BASIS_START_DATE
                   UNION ALL
                   SELECT 'M_' || A.BASIS_YYYYMM  AS COLUMN_NAME
                         , A.MONTH_NAME          AS COLUMN_LABEL_NAME
                         , A.MONTH_NAME          AS SMALL_CLASS_LABEL_NAME
                         , A.MONTH_NAME          AS LARGE_CLASS_LABEL_NAME
                         , ''                    AS DAY_CODE
                         , MIN(A.BASIS_START_DATE) || '01' AS SORT_ORDER_NO
                   FROM    SCM_SYS_CALENDAR_M A
                   WHERE  A.BASIS_YYYYMMDD >= P_START_YYYYMMDD --CONVERT(CHAR(8), CURRENT_TIMESTAMP, 112)
                   AND    A.BASIS_YYYYMMDD <= P_END_YYYYMMDD --CONVERT(CHAR(8), DATEADD(YYYY, 1, CURRENT_TIMESTAMP), 112)
                   AND    1 = CASE WHEN P_BUCKET != 'ONLY_WEEKLY' THEN 1 ELSE 2 END
                   GROUP BY A.BASIS_YYYYMM
                          , A.MONTH_NAME
                   -- [C20220620-000567]GSCM DM 시스템의 수작업 LOSS 및 분석 용이하기 하귀 위한 기능 개선 ( Partail week의 경우 week만 표시)
                   UNION ALL
                   SELECT 'W_' || SUBSTR(MAX(BASIS_YYYYMMDD), 1, 6) || ISO_WEEK  AS COLUMN_NAME
                         , WEEK_NAME AS COLUMN_LABEL_NAME
                         , WEEK_NAME AS SMALL_CLASS_LABEL_NAME
                         , SUBSTR(MIN(BASIS_YYYYMMDD), 5, 2) || '.' || SUBSTR(MIN(BASIS_YYYYMMDD), 7, 2)
                         || ' ~ ' || SUBSTR(MAX(BASIS_YYYYMMDD), 5, 2) || '.' || SUBSTR(MAX(BASIS_YYYYMMDD), 7, 2)  AS LARGE_CLASS_LABEL_NAME
                         , ''                   AS DAY_CODE
                         , MAX(BASIS_YYYYMMDD) || TO_CHAR(21) AS SORT_ORDER_NO
                   -- , 'FPNumber' AS CELL_CONTROL_OBJECT_TYPE_CODE
                   FROM   SCM_SYS_CALENDAR_M A
                   WHERE  A.BASIS_YYYYMMDD >= P_START_YYYYMMDD
                   AND    A.BASIS_YYYYMMDD <= P_END_YYYYMMDD
                   AND    1 = CASE WHEN P_BUCKET = 'ONLY_WEEKLY' THEN 1 ELSE 2 END
                   GROUP BY ISO_YYYYWW, ISO_WEEK, WEEK_NAME
                ) T
            ) A
            WHERE INSTR(',' || A.DIVISION_ID || ',', ',' || P_DIVISION_ID || ',') > 0
          ORDER BY SORT_ORDER_NO;

    END IF;

    /* ── 프로시저 처리 결과 반환 (O_RESULT_CURSOR) — 조회 성공 ── */
    OPEN O_RESULT_CURSOR FOR
    SELECT '0' AS CODE, 'SUCCESS' AS MSG, CASE WHEN 1 = 2 THEN '-' ELSE NULL END AS EVENT FROM DUAL;

    /* ── 종료 로그 ── */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH($$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE); END;

EXCEPTION
    WHEN OTHERS THEN
        -- 1) 트랜잭션이 있으면 ROLLBACK
        ROLLBACK;

        -- 2) 에러 정보 캡처
        V_LOG_TYPE    := 'ERROR';
        V_LOG_MESSAGE := 'EXCEPTION';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        V_SQL_CODE    := TO_CHAR(SQLCODE);
        V_SQL_ERRMSG  := SQLERRM;
        V_PROC_INPUT  := JSON_OBJECT(
            'P_START_YYYYMMDD' VALUE P_START_YYYYMMDD,
            'P_END_YYYYMMDD'   VALUE P_END_YYYYMMDD,
            'P_CREATED_BY'     VALUE P_CREATED_BY,
            'P_DIVISION_ID'    VALUE P_DIVISION_ID,
            'P_BUCKET'         VALUE P_BUCKET
        );
        V_BACKTRACE   := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;

        -- 3) 에러 로그 기록
        BEGIN
            SCM_MGR.PR_SCM_SYS_LOG_BATCH(
                $$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE,
                V_DESCRIPTION, D_EVENT_DATE, V_PROC_INPUT,
                V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE
            );
        END;

        -- 4) 에러 전파 (O_RESULT_CURSOR 미오픈)
        RAISE_APPLICATION_ERROR(-20001,
          '[' || $$PLSQL_UNIT || '] SQLCODE=' || V_SQL_CODE ||
          ' / SQLERRM=' || V_SQL_ERRMSG ||
          ' / BACKTRACE=' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE ||
          ' / PARAMS=' || V_PROC_INPUT
        );
        RAISE;
END P_DMF0035_GET_SPREAD_TITLE;

-- [E20260922-VERMRF] Version 팝업(SALES) Monthly Rolling Forecast 저장 — AS-IS DMF0073_SAVE_VERSION_SALESPRICE 1:1 + 서버 검증 보강
PROCEDURE P_DMF0035_SAVE_VERSION_MRF
(
    P_DIVISION_ID           IN VARCHAR2,   -- 팝업 Division (콤마 복수 허용 — 조회 SP 와 동일 규약)
    P_VERSION_NO            IN VARCHAR2,   -- 변경 행 CODE(순수 버전번호) '^' 연결
    P_MONTHLY_ROLLING_FCST  IN VARCHAR2,   -- 변경 값(Y/N) '^' 연결 — P_VERSION_NO 와 같은 순서
    P_USER_ID               IN VARCHAR2,   -- 저장 사용자 (BE 세션값)
    O_RESULT_CURSOR         OUT SYS_REFCURSOR
)
---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
/****************************************************************************************************/
/* Program ID  : P_DMF0035_SAVE_VERSION_MRF                                                          */
/* Description : Sales Plan Waterfall Version 팝업 — MONTHLY_ROLLING_FCST(DM_MST_VERSION.ATTRIBUTE7) 저장 */
/*--------------------------------------------------------------------------------------------------*/
/* Date        In Charge    Description                                                             */
/*--------------------------------------------------------------------------------------------------*/
/* 2024/05/13  KJJ          AS-IS DMF0073_SAVE_VERSION_SALESPRICE 신규 (DMF0073_VersionBySalesPricePopup) */
/* 2026/09/22  NextSCM      [E20260922-VERMRF] DMF0035 통합 Waterfall 로 이식.                        */
/*                          AS-IS 동작(ATTRIBUTE7/LAST_UPDATED_BY/LAST_UPDATE_DATE UPDATE)은 그대로,     */
/*                          AS-IS 에 없던 서버 검증 4종 추가 — 값 Y/N · Sales Plan(SP_) 버전 ·            */
/*                          당주(ISO 주차+연도) 버전 ·                                                   */
/*                          사업부 편집권한(PR_SCM_EDIT_YN). 화면 게이트와 같은 조건이라 정상 경로에선 통과. */
/*                          AS-IS 는 DIVISION_ID = 단일값 비교라 복수 Division 선택 시 0건 갱신 → 분할 IN. */
/****************************************************************************************************/
IS
    V_MENU_ID       VARCHAR2(50 CHAR) := 'DMF0035';
    V_CUR_YYYYWW    VARCHAR2(10 CHAR);
    N_VER_CNT       PLS_INTEGER := 0;
    N_VAL_CNT       PLS_INTEGER := 0;
    N_UPD_CNT       PLS_INTEGER := 0;
    V_INVALID       VARCHAR2(4000 CHAR);

    /* ── EXCEPTION 블록 필수 변수 ── */
    V_PROC_INPUT    VARCHAR2(4000 CHAR);
    V_BACKTRACE     VARCHAR2(4000 CHAR);
    V_SQL_CODE      VARCHAR2(100 CHAR);
    V_SQL_ERRMSG    VARCHAR2(1000 CHAR);
    V_LOG_TYPE      VARCHAR2(100 CHAR);
    V_LOG_MESSAGE   VARCHAR2(4000 CHAR);
    V_DESCRIPTION   VARCHAR2(4000 CHAR);
    N_LOG_COUNT     PLS_INTEGER := 0;
    D_EVENT_DATE    DATE := SYSDATE;

BEGIN

    /* ── 시작 로그 ── */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## START of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH($$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE); END;

    /* ── 1. 입력 건수 정합 ── */
    IF TRIM(P_VERSION_NO) IS NULL THEN
        OPEN O_RESULT_CURSOR FOR
            SELECT '-1' AS CODE, '저장할 데이터가 없습니다.' AS MSG, CAST(NULL AS VARCHAR2(4000 CHAR)) AS EVENT FROM DUAL;
        RETURN;
    END IF;

    N_VER_CNT := REGEXP_COUNT(P_VERSION_NO || '^', '\^');
    N_VAL_CNT := REGEXP_COUNT(NVL(P_MONTHLY_ROLLING_FCST, '') || '^', '\^');
    IF N_VER_CNT <> N_VAL_CNT THEN
        OPEN O_RESULT_CURSOR FOR
            SELECT '-1' AS CODE, 'Version / Monthly Rolling Forecast 건수가 일치하지 않습니다.' AS MSG
                 , N_VER_CNT || ' / ' || N_VAL_CNT AS EVENT FROM DUAL;
        RETURN;
    END IF;

    /* ── 2. 값 검증 — Y/N 만 (AS-IS MSG00002 필수 입력 + 콤보 Y/N) ── */
    SELECT LISTAGG(VER, ', ') WITHIN GROUP (ORDER BY N)
      INTO V_INVALID
      FROM (SELECT LEVEL AS N
                 , TRIM(REGEXP_SUBSTR(P_VERSION_NO || '^', '(.*?)\^', 1, LEVEL, NULL, 1)) AS VER
                 , TRIM(REGEXP_SUBSTR(P_MONTHLY_ROLLING_FCST || '^', '(.*?)\^', 1, LEVEL, NULL, 1)) AS VAL
              FROM DUAL
           CONNECT BY LEVEL <= N_VER_CNT)
     WHERE NVL(VAL, '-') NOT IN ('Y', 'N');

    IF V_INVALID IS NOT NULL THEN
        OPEN O_RESULT_CURSOR FOR
            SELECT '-1' AS CODE, 'Monthly Rolling Forecast 값은 Y 또는 N 이어야 합니다.' AS MSG, V_INVALID AS EVENT FROM DUAL;
        RETURN;
    END IF;

    /* ── 3. 당주 버전 + 사업부 편집권한 검증 (조회 SP 의 EDITABLE / EDIT_YN 과 같은 조건 — 연도 포함) ── */
    SELECT MAX(ISO_YYYYWW)
      INTO V_CUR_YYYYWW
      FROM SCM_MGR.SCM_SYS_CALENDAR_M
     WHERE BASIS_YYYYMMDD = TO_CHAR(SYSDATE, 'YYYYMMDD');

    SELECT LISTAGG(T.VER, ', ') WITHIN GROUP (ORDER BY T.N)
      INTO V_INVALID
      FROM (SELECT LEVEL AS N
                 , TRIM(REGEXP_SUBSTR(P_VERSION_NO || '^', '(.*?)\^', 1, LEVEL, NULL, 1)) AS VER
              FROM DUAL
           CONNECT BY LEVEL <= N_VER_CNT) T
     WHERE NOT EXISTS (SELECT 1
                         FROM SCM_MGR.DM_MST_VERSION A
                        INNER JOIN SCM_MGR.SCM_SYS_CALENDAR_M B
                           ON B.BASIS_YYYYMMDD = A.YYYYMMDD
                        INNER JOIN TABLE(SCM_MGR.PKG_SCM_USER_MNU.PR_SCM_EDIT_YN(P_USER_ID, V_MENU_ID)) TEI
                           ON TEI.UNIT_ID = A.DIVISION_ID
                          AND TEI.EDIT_YN = 'Y'
                        WHERE A.VERSION_NO  = T.VER
                          AND A.VERSION_TYPE LIKE 'SP\_%' ESCAPE '\'   -- Sales Plan 버전만 (MKT/BIZ 저장 불가 — 사용자 확정 2026-09-22)
                          AND A.DIVISION_ID IN (SELECT TOKEN FROM TABLE(SCM_MGR.FN_STRING_SPLIT(P_DIVISION_ID, ',')))
                          AND B.ISO_YYYYWW  = V_CUR_YYYYWW);

    IF V_INVALID IS NOT NULL THEN
        OPEN O_RESULT_CURSOR FOR
            SELECT '-1' AS CODE, '당주 Sales Plan 버전이면서 편집 권한이 있는 사업부의 버전만 수정할 수 있습니다.' AS MSG, V_INVALID AS EVENT FROM DUAL;
        RETURN;
    END IF;

    /* ── 4. 저장 — AS-IS UPDATE 1:1 (ATTRIBUTE7 / LAST_UPDATED_BY / LAST_UPDATE_DATE) ── */
    UPDATE SCM_MGR.DM_MST_VERSION M_VER
       SET M_VER.ATTRIBUTE7       = (SELECT T.VAL
                                       FROM (SELECT TRIM(REGEXP_SUBSTR(P_VERSION_NO || '^', '(.*?)\^', 1, LEVEL, NULL, 1)) AS VER
                                                  , TRIM(REGEXP_SUBSTR(P_MONTHLY_ROLLING_FCST || '^', '(.*?)\^', 1, LEVEL, NULL, 1)) AS VAL
                                               FROM DUAL
                                            CONNECT BY LEVEL <= N_VER_CNT) T
                                      WHERE T.VER = M_VER.VERSION_NO
                                      FETCH FIRST 1 ROWS ONLY)
         , M_VER.LAST_UPDATED_BY  = P_USER_ID
         , M_VER.LAST_UPDATE_DATE = SYSDATE
     WHERE M_VER.DIVISION_ID IN (SELECT TOKEN FROM TABLE(SCM_MGR.FN_STRING_SPLIT(P_DIVISION_ID, ',')))
       AND M_VER.VERSION_TYPE LIKE 'SP\_%' ESCAPE '\'
       AND M_VER.VERSION_NO  IN (SELECT TRIM(REGEXP_SUBSTR(P_VERSION_NO || '^', '(.*?)\^', 1, LEVEL, NULL, 1))
                                   FROM DUAL
                                CONNECT BY LEVEL <= N_VER_CNT)
       AND EXISTS (SELECT 1
                     FROM TABLE(SCM_MGR.PKG_SCM_USER_MNU.PR_SCM_EDIT_YN(P_USER_ID, V_MENU_ID)) TEI
                    WHERE TEI.UNIT_ID = M_VER.DIVISION_ID
                      AND TEI.EDIT_YN = 'Y');

    N_UPD_CNT := SQL%ROWCOUNT;
    N_LOG_COUNT := N_UPD_CNT;

    COMMIT;

    /* ── 종료 로그 ── */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := 'UPDATED=' || N_UPD_CNT;
    D_EVENT_DATE  := SYSDATE;
    BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH($$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE); END;

    OPEN O_RESULT_CURSOR FOR
        SELECT '0' AS CODE, 'success' AS MSG, TO_CHAR(N_UPD_CNT) AS EVENT FROM DUAL;

EXCEPTION
    WHEN OTHERS THEN
        -- 1) 트랜잭션이 있으면 ROLLBACK
        ROLLBACK;

        -- 2) 에러 정보 캡처
        V_LOG_TYPE    := 'ERROR';
        V_LOG_MESSAGE := 'EXCEPTION';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        V_SQL_CODE    := TO_CHAR(SQLCODE);
        V_SQL_ERRMSG  := SQLERRM;
        V_PROC_INPUT  := SUBSTR(JSON_OBJECT(
            'P_DIVISION_ID'          VALUE P_DIVISION_ID,
            'P_VERSION_NO'           VALUE P_VERSION_NO,
            'P_MONTHLY_ROLLING_FCST' VALUE P_MONTHLY_ROLLING_FCST,
            'P_USER_ID'              VALUE P_USER_ID
        ), 1, 4000);
        V_BACKTRACE   := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;

        -- 3) 에러 로그 기록
        BEGIN
            SCM_MGR.PR_SCM_SYS_LOG_BATCH(
                $$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE,
                V_DESCRIPTION, D_EVENT_DATE, V_PROC_INPUT,
                V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE
            );
        END;

        -- 4) 화면이 원인을 볼 수 있게 결과 커서로 반환 (CODE '9' / EVENT = SQLERRM)
        OPEN O_RESULT_CURSOR FOR
            SELECT '9' AS CODE, 'fail' AS MSG, SUBSTR(V_SQL_ERRMSG, 1, 4000) AS EVENT FROM DUAL;
END P_DMF0035_SAVE_VERSION_MRF;

END PKG_DMF0035;

