    DBMS_OUTPUT.PUT_LINE('D1A1--' || SYSDATE /*[E20260827-DATEINS] hook #109 — DATE 컬럼 문자열 INSERT(NLS 의존 ORA-01861) 정정*/||' : '||TO_CHAR(SQL%ROWCOUNT));

    -- =========================================================================
