    -- =========================================================================

    SELECT COUNT(1) INTO V_EXISTS_CNT FROM SCM_MGR.SCM_MST_DIVISION WHERE ATTRIBUTE3 LIKE '81%' AND ATTRIBUTE3 = '82' AND DIVISION_ID = P_DIVISION_ID;
    IF V_EXISTS_CNT > 0 THEN
