        TARGET_VERSION_NO AS (
            SELECT TOKEN AS VERSION_NO
                 , CASE WHEN ROW_NUMBER() OVER (ORDER BY VERSION_NO_SORT DESC) = 1 THEN 'Version(A)'
                        WHEN ROW_NUMBER() OVER (ORDER BY VERSION_NO_SORT DESC) = 2 THEN 'Version(B)'
                   ELSE 'VERSION_X'
