    IF P_PLANT_SITE_ID IS NOT NULL AND NVL(P_PLANT_SITE_ID,'@#@#@#') NOT IN ('ALL','@#@#@#') THEN
        V_SQL_TEXT := V_SQL_TEXT || ' AND F.PLANT_SITE_ID IN ('
            || CHR(10) || ' (SELECT TRIM(REGEXP_SUBSTR(''' || P_PLANT_SITE_ID || ''',''[^,]+'',1,LEVEL))'
            || CHR(10) || '   FROM DUAL CONNECT BY REGEXP_SUBSTR(''' || P_PLANT_SITE_ID || ''',''[^,]+'',1,LEVEL) IS NOT NULL))'; /*[E20260914-MULTISEL] 닫는 괄호 누락 — Plant Site 선택 시 ORA-00907*/
    END IF;

    IF P_DIVISION_ID <> '40' THEN
        NULL;
    ELSE
        IF P_CUSTOMER IS NOT NULL AND NVL(P_CUSTOMER,'@#@#@#') NOT IN ('ALL','@#@#@#') THEN
            /*[E20260914-MULTISEL] 40 End Customer 멀티선택 — 콤마 문자열 통째 LIKE('%A,B%')는 2건 이상 0행.
              AS-IS FN_SCM_GET_WHERE_SQL('F.PROJECT_CODE','LK') = 값별 'LIKE %v%' OR 결합 + '*'→'%' 와 동일하게 복원 */
            V_SQL_TEXT := V_SQL_TEXT || ' AND EXISTS (SELECT 1 FROM (SELECT TRIM(REGEXP_SUBSTR(''' || P_CUSTOMER || ''',''[^,]+'',1,LEVEL)) AS TK'
                || CHR(10) || '   FROM DUAL CONNECT BY REGEXP_SUBSTR(''' || P_CUSTOMER || ''',''[^,]+'',1,LEVEL) IS NOT NULL) CUST_TK'
                || CHR(10) || '   WHERE F.PROJECT_CODE LIKE ''%'' || REPLACE(CUST_TK.TK, ''*'', ''%'') || ''%'')';
        END IF;
    END IF;

    -- @p_owner 필터 (owner 조건 DELETE → Oracle에서는 CTE NOT EXISTS로 구현)
    V_SQL_TEXT := V_SQL_TEXT || q'[
        ),
        ALL_QUERY_DATA_FILTERED AS (
            SELECT A.*
            FROM   ALL_QUERY_DATA_B A
            LEFT OUTER JOIN TARGET_SITE_ITEM B
                   ON  A.ITEM_ID      = B.ITEM_ID
                   AND A.SCM_SITE_ID  = B.SCM_SITE_ID
                   AND A.PROJECT_CODE = B.PROJECT_CODE
				   AND A.DIVISION_ID  = B.DIVISION_ID
        ]';

    IF P_OWNER IS NOT NULL THEN
        V_SQL_TEXT := V_SQL_TEXT || q'[
            WHERE EXISTS (
                SELECT 1
                FROM (
                    SELECT TRIM(REGEXP_SUBSTR(']' || P_OWNER || q'[', '[^,]+', 1, LEVEL)) AS TOKEN
                    FROM   DUAL
                    CONNECT BY REGEXP_SUBSTR(']' || P_OWNER || q'[', '[^,]+', 1, LEVEL) IS NOT NULL
                ) C
                WHERE  B.OWNER         LIKE '%' || C.TOKEN || '%'
                OR     B.OWNER_NAME    LIKE '%' || C.TOKEN || '%'
                OR     B.OWNER_NAME_KO LIKE '%' || C.TOKEN || '%'
            )
        ]';
    END IF;

    V_SQL_TEXT := V_SQL_TEXT || q'[
        ),
        ALL_QUERY_DATA AS (
        ]';

    /* @p_diff_only = False 인경우만 쿼리실행 */
    IF P_DIFF_ONLY = 'False' THEN
        V_SQL_TEXT := V_SQL_TEXT || q'[
            SELECT A.VERSION_NO, DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, PLANT_SITE_ID
                 , ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, YYYYMMDD
                 --[E20260909-VERLABEL] 화면 메저명 = 실제 선택 VERSION_ID (사용자 지시 2026-09-09, 재반영 2026-09-15)
                 --  AS-IS: , V.VERSION_TYPE AS MEASURE, QTY, CELL_MODEL
                 --  'Version(A)/(B)' 는 표시 라벨이면서 동시에 VERSION_SORT 판정 키였다.
                 --  표시축(MEASURE=VERSION_NO)과 판정축(VERSION_TYPE)을 분리해 파생표까지 통과시킨다.
                 , V.VERSION_NO AS MEASURE, QTY, CELL_MODEL
                 , V.VERSION_TYPE AS VERSION_TYPE   --[E20260909-VERLABEL] 판정축
            FROM   ALL_QUERY_DATA_FILTERED A
            INNER JOIN TARGET_VERSION_NO V
                   ON  A.VERSION_NO = V.VERSION_NO
            UNION ALL
        ]';
    END IF;

    V_SQL_TEXT := V_SQL_TEXT || q'[
            SELECT '' AS VERSION_NO
                 , DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, PLANT_SITE_ID
                 , ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, YYYYMMDD
                 , 'Difference' AS MEASURE
                 , SUM(CASE WHEN V.VERSION_TYPE = 'Version(A)' THEN QTY ELSE -QTY END) AS QTY
                 , CELL_MODEL
                 , 'Difference' AS VERSION_TYPE   --[E20260909-VERLABEL] UNION ALL 컬럼 정합
            FROM   ALL_QUERY_DATA_FILTERED B
            INNER JOIN TARGET_VERSION_NO V
                   ON  B.VERSION_NO = V.VERSION_NO
            GROUP BY DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, PLANT_SITE_ID
                   , ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, YYYYMMDD, CELL_MODEL
        ),
        MKT_FCST AS (
            SELECT A.VERSION_NO
                 --[E20260909-VERLABEL] AS-IS: CASE WHEN A.MEASURE = 'Version(A)' ... A.MEASURE = 'Version(B)'
                 , CASE WHEN A.VERSION_TYPE = 'Version(A)' THEN '1'
                        WHEN A.VERSION_TYPE = 'Version(B)' THEN '2'
                   ELSE 'Z'
                   END AS VERSION_SORT
                 , A.DIVISION_ID
                 , A.DIVISION_ID AS DIVISION_ID40

                 --[PJ2024-50461] Team Mapping------------------------------------
			     --ENG 언어 설정시 Team 그리드 영어로 표시 26.09.09 ssh
				, TEAM.DEPT_ID                                                                  
				, CASE NVL((SELECT MAX(U0.LANG_CD) FROM SCM_ADM_USER_M U0 WHERE U0.USER_ID = ']' || P_CREATED_BY || q'['), 'KO')
                        WHEN 'EN' THEN TEAM.DEPT_NAME_EN
                        WHEN 'CN' THEN TEAM.DEPT_NAME_CN
                        ELSE TEAM.DEPT_NAME_KO
                   END AS DEPT_NAME_KO
                 , TEAM.DEPT_ID AS TEAM_ID
                 , NVL(CASE NVL((SELECT MAX(U1.LANG_CD) FROM SCM_ADM_USER_M U1 WHERE U1.USER_ID = ']' || P_CREATED_BY || q'['), 'KO')
                            WHEN 'EN' THEN TEAM.DEPT_NAME_EN
                            WHEN 'CN' THEN TEAM.DEPT_NAME_CN
                            ELSE TEAM.DEPT_NAME_KO
                       END, '') AS TEAM_NAME_KO
                 --, TEAM.DEPT_NAME_KO
                 --, TEAM.DEPT_ID AS TEAM_ID
                 --, NVL(TEAM.DEPT_NAME_KO, '') AS TEAM_NAME_KO  --[PJ2024-50611] 정렬시 사용하는 컬럼인데 하드코딩이 되어져 있음. null 방지 처리함
                 --[PJ2024-50461] Team Mapping------------------------------------

                 , G.END_CUSTOMER
                 , A.PROJECT_CODE AS END_CUSTOMER40
                 , F.BIZ_TYPE
                 , G.SOLDTO_CUSTOMER
                 , I.COUNTRY
                 , I.COUNTRY_NAME
                 , H.CITY
                 , H.CITY_NAME
                 , A.SCM_SITE_ID
                 , A.SCM_SITE_ID AS SCM_SITE_ID40
                 , A.PLANT_SITE_ID
                 , A.PROJECT_CODE
                 , F.PROJECT_NAME
                 , SCM_MGR.FN_GET_MULTI_OWNER_NAME(E.OWNER, ',', '1') AS OWNER  -- 20180817
                 , CASE WHEN A.DIVISION_ID <> '40' THEN F.PROJECT_OWNER
                   ELSE J.USER_NAME_EN END AS PROJECT_OWNER -- 20180705
                 , J.USER_ID
                 --20180809 ytchoi modify(e)
                 , A.ITEM_ID
                 , A.ITEM_ID AS ITEM_ID40
                 , L.ITEM_NAME
                 , L.NICK_NAME
                 , A.INCOTERMS
                 , L.ITEM_TYPE
                 , A.FCST_TYPE
                 , A.DOM_EXP
                 , F.PROJECT_STATUS
                 , A.MEASURE
                 , C.BASIS_YYYYMM   AS YYYYMM
                 , CASE WHEN ']' || P_BUCKET || q'[' = 'ONLY_WEEKLY' THEN C.BASIS_YYYYMMWW
                   ELSE C.BASIS_YYYYMM || C.ISO_WEEK END AS YYYYMMWW
                 , C.BASIS_YYYYMMDD AS YYYYMMDD
                 , C.DAYOFWEEK
                 , CASE WHEN M.BUCKET_PER = 'Y' THEN 'Y' WHEN M.BUCKET_PER = 'N' THEN 'N' ELSE NULL END AS PER  -- 20181101 khsong add
                 , D.QTY
                 , C.END_FLAG
                 , E.CUST_GROUP
                 , E.CUST_GROUP_DTL
                 , E.APPLICATION
                 , E.ROUTE
                 -- 20180711 추가
                 , L.MDM_PROJECT_NAME
                 , L.MIN_CAPACITY
                 , L.FORECAST_INFO_BIZ_TYPE
                 , L.FORECAST_INFO_PRODUCT_GROUP
                 , A.FORECAST_INFO_CELL_MODEL  -- 20180809 ytchoi
                 , LOOK.NAME AS CELL_TYPE  --20180911 LookUp 테이블 조인으로 CELL_TYPE 명칭
                 , L.FORECAST_INFO_CELL_PACK_COUNT
                 , L.FORECAST_INFO_SPEC || L.FORECAST_INFOR_VERSION AS FORECAST_INFO_SPEC
                 , G.VMI_YN  -- 20180719
                 , CASE WHEN
                       C.BASIS_YYYYMMDD = TO_CHAR(LAST_DAY(TO_DATE(C.BASIS_YYYYMMDD, 'YYYYMMDD')), 'YYYYMMDD')
                   THEN 'Y' ELSE 'N' END AS M_LAST_D_FLAG
                 , CASE WHEN A.DIVISION_ID = '40' THEN
                       CASE WHEN
                            --[PJ2024-50461] Team Mapping------------------------------------
--                          ((A.MEASURE IN ('MKT_FCST_RP','RTF','CUST_FCST','VMI_IN_Req')) AND (SCM_MGR.FN_GET_DEPT_LIST(']' || P_CREATED_BY || q'[', TEAM.DEPT_ID) = 'Y'))   --  2026.10.08 AJS
                            ((A.MEASURE IN ('MKT_FCST_RP','RTF','CUST_FCST','VMI_In_Req')) AND (SCM_MGR.FN_GET_DEPT_LIST(']' || P_CREATED_BY || q'[', TEAM.DEPT_ID) = 'Y'))   --  2026.10.08 AJS
                            --[PJ2024-50461] Team Mapping------------------------------------
--                          OR ((A.MEASURE IN ('MKT_FCST_RP','RTF','CUST_FCST','VMI_IN_Req')) AND (']' || V_GROUP_ID || q'[' = 'ADMIN'))   --  2026.10.08 AJS
                            OR ((A.MEASURE IN ('MKT_FCST_RP','RTF','CUST_FCST','VMI_In_Req')) AND (']' || V_GROUP_ID || q'[' = 'ADMIN'))   --  2026.10.08 AJS
                       THEN 'Y' ELSE 'N' END
                   END AS EDIT_FLAG
                 , CASE WHEN A.DIVISION_ID = '40' AND G.VMI_YN = 'Y' AND A.MEASURE = 'VMI_In_Req' THEN 'Y'
                        WHEN A.DIVISION_ID = '40' AND G.VMI_YN = 'N' AND A.MEASURE = 'MKT_FCST_RP' THEN 'Y'
                   ELSE 'N' END AS SCP_USE_YN
                 , E.ATTRIBUTE7 AS PRIORITY  --201811116
                 --[E20231017-000634] SCP정보수집
                 , SCP.CELL_NICKNAME  --20231025
                 , CASE WHEN SUBSTR(A.DIVISION_ID, 1, 2) = '81' OR A.DIVISION_ID = '82' THEN SCP.GROUP_CODE6
                   ELSE SCP.CELL_TYPE_GROUP_NAME END AS PRODUCT_LEVEL1
                 , CASE WHEN SUBSTR(A.DIVISION_ID, 1, 2) = '81' OR A.DIVISION_ID = '82' THEN SCP.GROUP_CODE7
                   ELSE SCP.BASIC_NICKNAME_CELL40 END AS PRODUCT_LEVEL2
                 , CASE WHEN SUBSTR(A.DIVISION_ID, 1, 2) = '81' THEN SCP.GROUP_CODE5
                        WHEN A.DIVISION_ID = '82'               THEN SCP.GROUP_CODE4
                   ELSE SCP.NICKNAME_40 END AS PRODUCT_LEVEL3
            FROM (
                SELECT DISTINCT F.VERSION_NO, F.DIVISION_ID, F.PROJECT_CODE, F.SCM_SITE_ID, F.PLANT_SITE_ID
                              , F.ITEM_ID, F.DOM_EXP, F.FCST_TYPE, F.INCOTERMS, F.MEASURE, F.VERSION_TYPE   --[E20260909-VERLABEL] 파생표 A 로 판정축 통과 (DISTINCT 카디널리티 불변 — MEASURE 에 함수종속)
                              , CELL_MODEL AS FORECAST_INFO_CELL_MODEL   -- 20180809 ytchoi
                FROM   ALL_QUERY_DATA F
        ]';

    -- [@sp_project_code_join]
    IF P_PROJECT_CODE IS NOT NULL THEN /*[E20260914-MULTISEL] 원본 <> '' 는 Oracle 에서 항상 UNKNOWN — 조인 미적용(사문화). AS-IS IF @p_project_code <> '' 의미로 복원*/
        V_SQL_TEXT := V_SQL_TEXT || q'[
                INNER JOIN SCM_MGR.GT_DM40_PROJECT_INPUT PROJECT_INPUT
                        ON F.PROJECT_CODE = PROJECT_INPUT.PROJECT_CODE
        ]';
    END IF;

    V_SQL_TEXT := V_SQL_TEXT || q'[
                WHERE  1 = 1    -- 20180809 ytchoi
            ) A
            INNER JOIN CALENDAR C
                   ON  1 = 1
            LEFT JOIN ALL_QUERY_DATA D
                   ON  A.DIVISION_ID   = D.DIVISION_ID
                   AND A.PROJECT_CODE  = D.PROJECT_CODE
                   AND A.SCM_SITE_ID   = D.SCM_SITE_ID
                   AND A.PLANT_SITE_ID = D.PLANT_SITE_ID
                   AND A.ITEM_ID       = D.ITEM_ID
                   AND A.DOM_EXP       = D.DOM_EXP
                   AND A.FCST_TYPE     = D.FCST_TYPE
                   AND A.INCOTERMS     = D.INCOTERMS
                   AND A.MEASURE       = D.MEASURE
                   AND C.BASIS_YYYYMMDD = D.YYYYMMDD
                   AND NVL(A.VERSION_NO,'@#@#@#') = NVL(D.VERSION_NO,'@#@#@#')
            INNER JOIN (SELECT E.DIVISION_ID,E.SCM_SITE_ID,E.PROJECT_CODE,E.ITEM_ID
                              ,(SELECT TRIM(REGEXP_SUBSTR(E.OWNER, '[^,]+', 1, 1)) FROM DUAL WHERE ROWNUM = 1) AS USER_ID
                              ,E.OWNER
                              ,E.CUST_GROUP
                              ,E.CUST_GROUP_DTL
                              ,E.APPLICATION
                              ,E.ROUTE
                              ,E.ATTRIBUTE7
                              ,E.DEPT_ID  -- 2026-09-06 hook#150 AJS
                        FROM   SCM_MGR.SCM_MST_SITE_ITEM E
                       ) E
                   ON  A.DIVISION_ID   = E.DIVISION_ID
                   AND A.SCM_SITE_ID   = E.SCM_SITE_ID
                   AND A.PROJECT_CODE  = E.PROJECT_CODE
                   AND A.ITEM_ID       = E.ITEM_ID
            LEFT JOIN SCM_MGR.SCM_MST_PROJECT F
                   ON  A.DIVISION_ID   = F.DIVISION_ID
                   AND A.PROJECT_CODE  = F.PROJECT_CODE
            LEFT OUTER JOIN SCM_MGR.SCM_MST_SITE G
                   ON  A.DIVISION_ID   = G.DIVISION_ID
                   AND A.SCM_SITE_ID   = G.SCM_SITE_ID
            LEFT OUTER JOIN SCM_MGR.SCM_MST_CITY H
                   ON  G.CITY          = H.CITY
            LEFT OUTER JOIN SCM_MGR.SCM_MST_COUNTRY I
                   ON  G.COUNTRY       = I.COUNTRY
            --[E20231017-000634]
            LEFT OUTER JOIN SCP_ITEM_INFO SCP
                   ON  SCP.DIVISION_ID = A.DIVISION_ID
                   AND SCP.ITEM_ID     = A.ITEM_ID
            -- 20180809 추가  -----------------
            -- [hook#150 2026-09-06 AJS] AS-IS: LEFT JOIN (
                -- [hook#150 2026-09-06 AJS] AS-IS: SELECT B.USER_ID, B.USER_NAME, B.USER_NAME_EN, B.DEPT_ID, C.DEPT_NAME_KO
                -- [hook#150 2026-09-06 AJS] AS-IS: FROM   SCM_MGR.SCM_MST_SSO_USER_INFO B
                -- [hook#150 2026-09-06 AJS] AS-IS: INNER JOIN SCM_MGR.SCM_MST_SSO_DEPT_INFO C
                        -- [hook#150 2026-09-06 AJS] AS-IS: ON B.DEPT_ID = C.DEPT_ID
            -- [hook#150 2026-09-06 AJS] AS-IS: ) TEAM
                   -- [hook#150 2026-09-06 AJS] AS-IS: ON  TEAM.USER_ID = E.USER_ID
            -- 2026-09-06 hook#150 AJS: DEPT_ID 원천 = SCM_MST_SITE_ITEM.DEPT_ID (SCM_MST_SITE.DEPT_ID 삭제 예정 / OWNER 경유 폐기)
            LEFT JOIN SCM_MGR.SCM_MST_SSO_DEPT_INFO TEAM
                   ON  TEAM.DEPT_ID = E.DEPT_ID
            -- 20180809 추가  -----------------
            LEFT JOIN SCM_MGR.SCM_MST_SSO_USER_INFO J
                   ON  E.OWNER = J.USER_ID -- 20180724 add son young suk
            LEFT JOIN SCM_MGR.SCM_MST_SSO_DEPT_INFO K
            --[PJ2024-50461] Team Mapping------------------------------------
                   ON  E.DEPT_ID = K.DEPT_ID  -- 2026-09-06 hook#150 AJS (AS-IS: J.DEPT_ID = OWNER 경유)
            --[PJ2024-50461] Team Mapping------------------------------------
            INNER JOIN SCM_MGR.GT_DM40_ITEM_SINGLE L
                   ON  A.DIVISION_ID = L.DIVISION_ID
                   AND A.ITEM_ID     = L.ITEM_ID
            LEFT JOIN SCM_MGR.DM_MST_BUCKET_CONVERSION M
                   ON  A.DIVISION_ID = M.DIVISION_ID
                   AND A.SCM_SITE_ID = M.SCM_SITE_ID
                   AND A.INCOTERMS   = M.INCOTERMS
                   AND C.DAYOFWEEK   = M.YYYYMMDD
            LEFT JOIN (  --** 20180911  Son Young Suk  조회 컬럼 CELL_TYPE 추가 DM_MST_ITEM_SINGLE_V.CELL_TYPE 사용 LookUp 테이블로 명칭 조회 LookUp 테이블 조인
                        SELECT SEGMENT1 AS CODE, SEGMENT2 AS NAME
                        FROM   SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL
                        WHERE  LOOKUP_TYPE = 'CELL_TYPE'
                    ) LOOK
                   ON  LOOK.CODE = L.CELL_TYPE
            WHERE 1=1
            AND D.QTY IS NOT NULL -- [20240312] 조건 추가함.
        ]';

    -- [@v_team_id]
    --[PJ2024-50461] Team Mapping -검색조건 처리 누락 수정
    IF P_TEAM_ID IS NOT NULL AND NVL(P_TEAM_ID,'@#@#@#') NOT IN ('ALL','@#@#@#') THEN
        V_SQL_TEXT := V_SQL_TEXT || ' AND TEAM.DEPT_ID IN ('
            || CHR(10) || ' (SELECT TRIM(REGEXP_SUBSTR(''' || P_TEAM_ID || ''',''[^,]+'',1,LEVEL))'
            || CHR(10) || '   FROM DUAL CONNECT BY REGEXP_SUBSTR(''' || P_TEAM_ID || ''',''[^,]+'',1,LEVEL) IS NOT NULL))';
    END IF;

    -- [@v_item_type]
    IF P_ITEM_TYPE IS NOT NULL AND NVL(P_ITEM_TYPE,'@#@#@#') NOT IN ('ALL','@#@#@#') THEN
        V_SQL_TEXT := V_SQL_TEXT || ' AND L.ITEM_TYPE IN ('
            || CHR(10) || ' (SELECT TRIM(REGEXP_SUBSTR(''' || P_ITEM_TYPE || ''',''[^,]+'',1,LEVEL))'
            || CHR(10) || '   FROM DUAL CONNECT BY REGEXP_SUBSTR(''' || P_ITEM_TYPE || ''',''[^,]+'',1,LEVEL) IS NOT NULL))';
    END IF;


    V_SQL_TEXT := V_SQL_TEXT || '
        )
        /* 기존SQL */
        SELECT ' || V_COLUMN || '
             , F.VERSION_SORT AS SORT_ORDER_NO
               [V_ITERATION]
             , EDY.EDIT_YN
        FROM   MKT_FCST F
               INNER JOIN SCM_MGR.SCM_ADM_USER_MNU_EDIT_AUTH_V EDY
                    ON EDY.USER_ID = ''' || P_USER_ID || '''
                   AND EDY.MNU_ID  = ''' || P_MENU_ID || '''
                   AND EDY.UNIT_ID = F.DIVISION_ID
        WHERE  1 = 1
        -- add 181102 속도개선을 의해서 추가
        -- [20240312] 주석처리함. AND    ( F.PER IS NOT NULL OR F.QTY IS NOT NULL )
    ';


    -- [@v_customer]
    IF P_DIVISION_ID <> '40' THEN
        IF P_CUSTOMER IS NOT NULL AND NVL(P_CUSTOMER,'@#@#@#') NOT IN ('ALL','@#@#@#') THEN
            V_SQL_TEXT := V_SQL_TEXT || ' AND F.END_CUSTOMER IN ('
                || CHR(10) || ' (SELECT TRIM(REGEXP_SUBSTR(''' || P_CUSTOMER || ''',''[^,]+'',1,LEVEL))'
                || CHR(10) || '   FROM DUAL CONNECT BY REGEXP_SUBSTR(''' || P_CUSTOMER || ''',''[^,]+'',1,LEVEL) IS NOT NULL))';
        END IF;
    END IF;

    -- [@v_biz_type]
    IF P_DIVISION_ID <> '40' THEN
        IF P_BIZ_TYPE IS NOT NULL AND NVL(P_BIZ_TYPE,'@#@#@#') NOT IN ('ALL','@#@#@#') THEN
            V_SQL_TEXT := V_SQL_TEXT || ' AND F.BIZ_TYPE IN ('
                || CHR(10) || ' (SELECT TRIM(REGEXP_SUBSTR(''' || P_BIZ_TYPE || ''',''[^,]+'',1,LEVEL))'
                || CHR(10) || '   FROM DUAL CONNECT BY REGEXP_SUBSTR(''' || P_BIZ_TYPE || ''',''[^,]+'',1,LEVEL) IS NOT NULL))';
        END IF;
    ELSE
        IF P_BIZ_TYPE IS NOT NULL AND NVL(P_BIZ_TYPE,'@#@#@#') NOT IN ('ALL','@#@#@#') THEN
            V_SQL_TEXT := V_SQL_TEXT || ' AND FORECAST_INFO_BIZ_TYPE IN ('
                || CHR(10) || ' (SELECT TRIM(REGEXP_SUBSTR(''' || P_BIZ_TYPE || ''',''[^,]+'',1,LEVEL))'
                || CHR(10) || '   FROM DUAL CONNECT BY REGEXP_SUBSTR(''' || P_BIZ_TYPE || ''',''[^,]+'',1,LEVEL) IS NOT NULL))';
        END IF;
    END IF;

    V_SQL_TEXT := V_SQL_TEXT || V_GROUPBY ||' ,EDY.EDIT_YN ' || CHR(10);

    -- =========================================================================
    -- [E20240201-001467] 20240216: ORDER BY 동적 구성
    -- =========================================================================
    V_ORDER := '';
    FOR R_ORD IN (
        SELECT COLUMN_NAME, DATA_SORT_METHOD_CODE
        FROM   SCM_MGR.SCM_MST_TITLESET_USER U
        WHERE  U.USER_INQUIRY_COLUMN_TYPE_CODE = 'C'
        AND    U.PROGRAM_ID                    = V_PROGRAM_ID
        AND    U.SHEET_NAME                    = V_SHEET_NAME
        AND    U.USER_ID                       = P_CREATED_BY
        --[E20260827-SORTCODE] VERSION_NO/MEASURE 는 ORDER BY 제외 (SORT_ORDER_NO 가 대신) —
        --  구 L1444 REPLACE(',VERSION_NO','') 는 이름만 지우고 방향 토큰(ASC)을 남겨 ORA-03048 (실증 2026-08-27)
        AND    U.COLUMN_NAME NOT IN ('VERSION_NO', 'MEASURE')
        ORDER BY SORT_ORDER_NO
    ) LOOP
        --[E20260827-SORTCODE] 'DESC' 외 전부 'ASC' (기존 '-' 데이터 방어)
        V_ORDER := V_ORDER || R_ORD.COLUMN_NAME || ' ' || CASE WHEN UPPER(R_ORD.DATA_SORT_METHOD_CODE) = 'DESC' THEN 'DESC' ELSE 'ASC' END || ',';
    END LOOP;

    --[E20260827-SORTCODE] titleset 0건 시 'ORDER BY ,' 고아 콤마 방어
    IF V_ORDER IS NULL OR V_ORDER = '' THEN
        V_ORDER := ' ORDER BY SORT_ORDER_NO ASC ';
    ELSE
        V_ORDER := ' ORDER BY ' || SUBSTR(V_ORDER, 1, LENGTH(V_ORDER) - 1) || ' , SORT_ORDER_NO ASC ';
    END IF;
    V_ORDER := REPLACE(REPLACE(V_ORDER, ',VERSION_NO', ''), ',MEASURE', '');

    DBMS_OUTPUT.PUT_LINE('V_ORDER : '||V_ORDER);
    --end-----------------------------------------------------------------------------
    --[E20240201-001467]
    V_SQL_TEXT := V_SQL_TEXT || V_ORDER;

    V_SQL_TEXT := PKG_DMF0007.F_FN_REPLACE_CLOB(V_SQL_TEXT,'[V_ITERATION]', V_ITERATION);

    -- =========================================================================
    -- 동적 SQL 실행 → O_RC1 반환
    -- =========================================================================
    DBMS_OUTPUT.PUT_LINE('V_COLUMN : '||V_COLUMN);
    PKG_DMF0007.P_PR_PRINT_CLOB('V_SQL_TEXT', V_ITERATION);
    PKG_DMF0007.P_PR_PRINT_CLOB('V_SQL_TEXT', V_SQL_TEXT);

    V_SQL_CURSOR := DBMS_SQL.OPEN_CURSOR;
    DBMS_SQL.PARSE(V_SQL_CURSOR, V_SQL_TEXT, DBMS_SQL.NATIVE);
    V_EXECUTE_RET := DBMS_SQL.EXECUTE(V_SQL_CURSOR);
    O_RC1 := DBMS_SQL.TO_REFCURSOR(V_SQL_CURSOR);
    V_SQL_CURSOR := NULL;

    IF DBMS_LOB.ISTEMPORARY(V_SQL_TEXT) = 1 THEN
        DBMS_LOB.FREETEMPORARY(V_SQL_TEXT);
    END IF;

    IF DBMS_LOB.ISTEMPORARY(V_ITERATION) = 1 THEN
        DBMS_LOB.FREETEMPORARY(V_ITERATION);
    END IF;

    OPEN O_RESULT_CURSOR FOR
    SELECT '0' AS CODE, 'SUCCESS' AS MSG, CASE WHEN 1=2 THEN '-' ELSE NULL END AS EVENT FROM DUAL;

    COMMIT;

    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE); END;

EXCEPTION
    WHEN OTHERS THEN
        IF DBMS_SQL.IS_OPEN(V_SQL_CURSOR) THEN
            DBMS_SQL.CLOSE_CURSOR(V_SQL_CURSOR);
        END IF;

        IF DBMS_LOB.ISTEMPORARY(V_SQL_TEXT) = 1 THEN
            DBMS_LOB.FREETEMPORARY(V_SQL_TEXT);
        END IF;

        IF DBMS_LOB.ISTEMPORARY(V_ITERATION) = 1 THEN
            DBMS_LOB.FREETEMPORARY(V_ITERATION);
        END IF;

        ROLLBACK;

        V_LOG_TYPE    := 'ERROR';
        V_LOG_MESSAGE := 'EXCEPTION';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        V_SQL_CODE    := TO_CHAR(SQLCODE);
        V_SQL_ERRMSG  := SQLERRM;
        V_PROC_INPUT  := JSON_OBJECT(
            'P_DIVISION_ID'   VALUE P_DIVISION_ID,
            'P_SCM_SITE_ID'   VALUE P_SCM_SITE_ID,
            'P_PLANT_SITE_ID' VALUE P_PLANT_SITE_ID,
            'P_TEAM_ID'       VALUE P_TEAM_ID,
            'P_CUSTOMER'      VALUE P_CUSTOMER,
            'P_BIZ_TYPE'      VALUE P_BIZ_TYPE,
            'P_PROJECT_CODE'  VALUE P_PROJECT_CODE,
            'P_ITEM_ID'       VALUE P_ITEM_ID,
            'P_FROM_YYYYMMDD' VALUE P_FROM_YYYYMMDD,
            'P_TO_YYYYMMDD'   VALUE P_TO_YYYYMMDD,
            'P_CREATED_BY'    VALUE P_CREATED_BY,
            'P_VERSION_NO'    VALUE P_VERSION_NO,
            'P_ITEM_TYPE'     VALUE P_ITEM_TYPE,
            'P_OWNER'         VALUE P_OWNER,
            'P_DIFF_ONLY'     VALUE P_DIFF_ONLY,
            'P_BUCKET'        VALUE P_BUCKET
        );
        V_BACKTRACE   := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;

        BEGIN
            SCM_MGR.PR_SCM_SYS_LOG_BATCH(
                V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE,
                V_DESCRIPTION, D_EVENT_DATE, V_PROC_INPUT,
                V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE
            );
        END;

        RAISE_APPLICATION_ERROR(-20001,
            '[' || V_PROGRAM_NAME || '] SQLCODE=' || V_SQL_CODE ||
            ' / SQLERRM=' || V_SQL_ERRMSG ||
            ' / BACKTRACE=' || V_BACKTRACE ||
            ' / PARAMS=' || V_PROC_INPUT
        );
END P_DMF0040_GET_MKT_FCST_COMPARISON;

    -- [2026-09-15 UIPKG] standalone DMF0040_GET_SPREAD_TITLE 취합
PROCEDURE P_DMF0040_GET_SPREAD_TITLE 
(
    P_START_YYYYMMDD  IN VARCHAR2,
    P_END_YYYYMMDD    IN VARCHAR2,
    P_CREATED_BY      IN VARCHAR2,
    P_DIVISION_ID     IN VARCHAR2,
    P_BUCKET          IN VARCHAR2,
    O_RC1             OUT SYS_REFCURSOR,
    O_RESULT_CURSOR   OUT SYS_REFCURSOR
)
/****************************************************************************************************/
/* Program ID  : DM0035_GET_SPREAD_TITLE                                                             */
/* Description : Procedure 작성 가이드                                                              */
/* Usage       : Procedure 작성 시 참조하세요!                                                      */
/* Parameter   :                                                                                    */
/*                                                                                                  */
/*--------------------------------------------------------------------------------------------------*/
/* Date        In Charge    Description                                                             */
/*--------------------------------------------------------------------------------------------------*/
/* 2018/02/05  pjs       Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트 */
/* 2019/02/12	JYE		 42, 44 추가                                                             */
/*
 * 2022/07/25	kdw2819		[C20220620-000567]GSCM DM 시스템의 수작업 LOSS 및 분석 용이하기 하귀 위한 기능 개선 ( Partail week의 경우 week만 표시)
 * 2024.02.15 HMIN [E20240201-001467] MKT FCST Comparison 화면 정렬 Order 개선   (데이터 중복으로 되던 부분 수정 , TITLE SETTING오류  수정)
 */
/* 2026.03.18   jcnam        [PJ20264226] NextSCM Pilot 설계 및 개발                                  */
/****************************************************************************************************/
/*****************************************************************************************************
 ※ 작성 Rule
   1. 대문자, 소문자
      - 테이블, 컬럼, 변수는 소문자로 작성하고, 그 이외는 대문자로 통일
   2. Naming Rule - Prefix
      - 파라메터 : @p_
      - 변수 : 데이타 타입에 따라 @v_(문자), @n_(숫자), @d_(날짜)
   3. 들여쓰기 : 2 space
   4. 기타
      - SQL 수직 배치 : SQL 구문의 세로줄(왼쪽)로 맞춤, 컬럼이나 변수도 KEYWORD 이후 왼쪽 정렬
      - 콤마로 분리된 ID 가 여러 줄에 걸쳐 나올 때, 콤마를 라인의 처음에 위치
******************************************************************************************************/
IS

    V_USER_COL_CNT    PLS_INTEGER := 0;
    V_PROGRAM_ID      VARCHAR2(50 CHAR) := 'DMF0040';
    V_SHEET_NAME      VARCHAR2(50 CHAR) := 'Mkt Fcst Waterfall';

    /* ── EXCEPTION 블록 필수 변수 ── */
    V_PROC_INPUT    VARCHAR2(4000 CHAR);
    V_BACKTRACE     VARCHAR2(4000 CHAR);
    V_SQL_CODE      VARCHAR2(100 CHAR);
    V_SQL_ERRMSG    VARCHAR2(1000 CHAR);
    V_LOG_TYPE      VARCHAR2(100 CHAR);
    V_LOG_MESSAGE   VARCHAR2(4000 CHAR);
    V_DESCRIPTION   VARCHAR2(4000 CHAR);
    N_LOG_COUNT     PLS_INTEGER := 0;
    D_EVENT_DATE    DATE := SYSDATE;

BEGIN

    /* ── 시작 로그 ── */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## START of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH($$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE); END;

    /* ── 사용자 컬럼 설정 건수 조회 (Case 28/29: EXISTS 패턴) ── */
    BEGIN
        SELECT 1
        INTO   V_USER_COL_CNT
        FROM   DUAL
        WHERE  EXISTS (
            SELECT 1
            FROM   SCM_MST_TITLESET_USER U
            WHERE  1 = 1
            AND    U.PROGRAM_ID = V_PROGRAM_ID
            AND    U.SHEET_NAME = V_SHEET_NAME
            AND    U.USER_INQUIRY_COLUMN_TYPE_CODE = 'C'
            AND    U.USER_ID    = P_CREATED_BY
        );
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            V_USER_COL_CNT := 0;
    END;

    /* ── 메인 조회 결과 반환 (O_RC1) ── */
    IF V_USER_COL_CNT > 0 THEN

        OPEN O_RC1 FOR
        SELECT * FROM (
            /* ── 사용자 설정 컬럼 ── */
            SELECT U.PROGRAM_ID
                 , U.SHEET_NAME
                 , U.COLUMN_NAME
                 , C.COLUMN_LABEL_NAME
                 , TO_CHAR(U.SORT_ORDER_NO) AS SORT_ORDER_NO        --CONVERT(NVARCHAR(10), U.SORT_ORDER_NO) AS SORT_ORDER_NO
                 , U.DATA_SORT_METHOD_CODE
                 , C.SMALL_CLASS_LABEL_NAME
                 , C.LARGE_CLASS_LABEL_NAME
                 , '' AS DAY_CODE
                 , C.FIXED_FLAG
                 , C.COLUMN_WIDTH
                 , C.CELL_CONTROL_OBJECT_TYPE_CODE
                 , C.CELL_COMBO_DATA_TYPE
                 , TO_CHAR(C.DATA_SCALE_NUMBER) AS DATA_SCALE_NUMBER
                 , TO_CHAR(C.DATA_MAX_LENGTH) AS DATA_MAX_LENGTH
                 , C.HORIZONTAL_ALIGN_CODE
                 , C.UPPERCASE_APPLY_FLAG
                 , C.VISIBLE_FLAG
                 , C.DEFAULT_FLAG
                 , C.USER_SELECTABLE_FLAG
                 , C.VALID_YN
                 , C.DIVISION_ID
            FROM   SCM_MST_TITLESET_USER U
                 , SCM_MST_SHEET_COLUMNS C
            WHERE  1 = 1
            AND    U.PROGRAM_ID  = C.PROGRAM_ID
            AND    U.SHEET_NAME  = C.SHEET_NAME
            AND    U.COLUMN_NAME = C.COLUMN_NAME
            AND    U.PROGRAM_ID  = V_PROGRAM_ID
            AND    U.SHEET_NAME  = V_SHEET_NAME
            AND    U.USER_ID     = P_CREATED_BY
            AND    U.USER_INQUIRY_COLUMN_TYPE_CODE = 'C'
            AND    INSTR(',' || C.DIVISION_ID || ',', ',' || P_DIVISION_ID || ',') > 0
            AND    C.VISIBLE_FLAG = 'Y' --[E20240201-001467] 조건이 없어 아래 DEFAULT설정한 정보와 이중으로 처리되어 오류발생

            UNION ALL

            /* ── 비노출 기본 컬럼 ── */
            SELECT C.PROGRAM_ID
                 , C.SHEET_NAME
                 , C.COLUMN_NAME
                 , C.COLUMN_LABEL_NAME
                 , TO_CHAR(C.SORT_ORDER_NO) AS SORT_ORDER_NO        --CONVERT(NVARCHAR(10), U.SORT_ORDER_NO) AS SORT_ORDER_NO
                 , C.DATA_SORT_METHOD_CODE
                 , C.SMALL_CLASS_LABEL_NAME
                 , C.LARGE_CLASS_LABEL_NAME
                 , '' AS DAY_CODE
                 , C.FIXED_FLAG
                 , C.COLUMN_WIDTH
                 , C.CELL_CONTROL_OBJECT_TYPE_CODE
                 , C.CELL_COMBO_DATA_TYPE
                 , TO_CHAR(C.DATA_SCALE_NUMBER) AS DATA_SCALE_NUMBER
                 , TO_CHAR(C.DATA_MAX_LENGTH) AS DATA_MAX_LENGTH
                 , C.HORIZONTAL_ALIGN_CODE
                 , C.UPPERCASE_APPLY_FLAG
                 , C.VISIBLE_FLAG
                 , C.DEFAULT_FLAG
                 , C.USER_SELECTABLE_FLAG
                 , C.VALID_YN
                 , C.DIVISION_ID
            FROM   SCM_MST_SHEET_COLUMNS C
            WHERE  1 = 1
            AND    C.PROGRAM_ID  = V_PROGRAM_ID
            AND    C.SHEET_NAME  = V_SHEET_NAME
            AND    C.VISIBLE_FLAG = 'N'
            -- 2026.09.28 AJS 주석처리 (START)
            /* AS-IS MSSQL 의 DEFAULT_FLAG = '' 는 빈 값 비교로 성립하지만 Oracle 은 NULL 비교라 항상 거짓 */
            /* 비노출 기본 칸 갈래가 0행이 되어 Version 칸 정의가 내려가지 않음 — AS-IS 실측 [N]['']  = TO-BE [N]['Y'] */
            -- AND    C.DEFAULT_FLAG = ''
            AND    C.DEFAULT_FLAG = 'Y'
            -- 2026.09.28 AJS 주석처리 (END)
            AND    C.VALID_YN     = 'Y'
            AND    INSTR(',' || C.DIVISION_ID || ',', ',' || P_DIVISION_ID || ',') > 0

            UNION ALL

            /* ── 캘린더 동적 컬럼 ── */
            SELECT V_PROGRAM_ID   AS PROGRAM_ID
                 , V_SHEET_NAME AS SHEET_NAME
                 , T.COLUMN_NAME
                 , T.COLUMN_LABEL_NAME
                 , T.SORT_ORDER_NO
                 , ''         AS DATA_SORT_METHOD_CODE
                 , T.SMALL_CLASS_LABEL_NAME
                 , T.LARGE_CLASS_LABEL_NAME
                 , T.DAY_CODE
                 , ''         AS FIXED_FLAG
                 , CASE WHEN P_BUCKET = 'ONLY_WEEKLY' THEN 100
                        ELSE 50 END AS COLUMN_WIDTH
                 , 'FPNumber' AS CELL_CONTROL_OBJECT_TYPE_CODE
                 , ''         AS CELL_COMBO_DATA_TYPE
                 , ''         AS DATA_SCALE_NUMBER
                 , ''         AS DATA_MAX_LENGTH
                 , 'R'        AS HORIZONTAL_ALIGN_CODE
                 , 'Y'        AS UPPERCASE_APPLY_FLAG
                 , 'Y'        AS VISIBLE_FLAG
                 , ''         AS DEFAULT_FLAG
                 , ''         AS USER_SELECTABLE_FLAG
                 , ''         AS VALID_YN
                 --, CASE WHEN CHARINDEX('81', @p_divisIon_id) > 0 OR CHARINDEX('82', @p_divisIon_id) > 0 THEN
                    --  CASE WHEN CHARINDEX('40', @p_divisIon_id) > 0 THEN '40,81,82'
                    --  ELSE '81,82' END
                 --  ELSE
                    --  '40'
                 --  END AS DIVISION_ID
                 , P_DIVISION_ID AS DIVISION_ID
            FROM  (
                   SELECT 'D_' || A.BASIS_YYYYMMDD   AS COLUMN_NAME
                        , A.CALENDAR_DAY            AS COLUMN_LABEL_NAME
                        , A.WEEK_NAME               AS SMALL_CLASS_LABEL_NAME
                        , A.MONTH_NAME              AS LARGE_CLASS_LABEL_NAME
                        , A.DAYOFWEEK               AS DAY_CODE
                        , A.BASIS_YYYYMMDD || TO_CHAR(31) AS SORT_ORDER_NO
                   FROM   SCM_SYS_CALENDAR_M A
                   WHERE  A.BASIS_YYYYMMDD >= P_START_YYYYMMDD --CONVERT(CHAR(8), CURRENT_TIMESTAMP, 112)
                   AND    A.BASIS_YYYYMMDD <= P_END_YYYYMMDD --CONVERT(CHAR(8), DATEADD(YYYY, 1, CURRENT_TIMESTAMP), 112)
                   AND    1 = CASE WHEN P_BUCKET != 'ONLY_WEEKLY' THEN 1 ELSE 2 END
                   UNION ALL
                   SELECT 'W_' || A.BASIS_YYYYMM || A.ISO_WEEK   AS COLUMN_NAME
                        , A.WEEK_NAME          AS COLUMN_LABEL_NAME
                        , A.WEEK_NAME          AS SMALL_CLASS_LABEL_NAME
                        , A.MONTH_NAME         AS LARGE_CLASS_LABEL_NAME
                        , ''                   AS DAY_CODE
                        , A.BASIS_START_DATE || TO_CHAR(21) AS SORT_ORDER_NO
                   FROM   SCM_SYS_CALENDAR_M A
                   WHERE  A.BASIS_YYYYMMDD >= P_START_YYYYMMDD --CONVERT(CHAR(8), CURRENT_TIMESTAMP, 112)
                   AND    A.BASIS_YYYYMMDD <= P_END_YYYYMMDD --CONVERT(CHAR(8), DATEADD(YYYY, 1, CURRENT_TIMESTAMP), 112)
                   AND    1 = CASE WHEN P_BUCKET != 'ONLY_WEEKLY' THEN 1 ELSE 2 END
                   GROUP BY A.BASIS_YYYYMM
                          , A.ISO_WEEK
                          , A.WEEK_NAME
                          , A.MONTH_NAME
                          , A.BASIS_START_DATE
                   UNION ALL
                   SELECT 'M_' || A.BASIS_YYYYMM  AS COLUMN_NAME
                         , A.MONTH_NAME          AS COLUMN_LABEL_NAME
                         , A.MONTH_NAME          AS SMALL_CLASS_LABEL_NAME
                         , A.MONTH_NAME          AS LARGE_CLASS_LABEL_NAME
                         , ''                    AS DAY_CODE
                         , MIN(A.BASIS_START_DATE) || '01' AS SORT_ORDER_NO
                   FROM    SCM_SYS_CALENDAR_M A
                   WHERE  A.BASIS_YYYYMMDD >= P_START_YYYYMMDD --CONVERT(CHAR(8), CURRENT_TIMESTAMP, 112)
                   AND    A.BASIS_YYYYMMDD <= P_END_YYYYMMDD --CONVERT(CHAR(8), DATEADD(YYYY, 1, CURRENT_TIMESTAMP), 112)
                   AND    1 = CASE WHEN P_BUCKET != 'ONLY_WEEKLY' THEN 1 ELSE 2 END
                   GROUP BY A.BASIS_YYYYMM
                          , A.MONTH_NAME
                            -- [C20220620-000567]GSCM DM 시스템의 수작업 LOSS 및 분석 용이하기 하귀 위한 기능 개선 ( Partail week의 경우 week만 표시)
                   UNION ALL
                   SELECT 'W_' || SUBSTR(MAX(BASIS_YYYYMMDD), 1, 6) || ISO_WEEK AS COLUMN_NAME
                         , WEEK_NAME AS COLUMN_LABEL_NAME
                         , WEEK_NAME AS SMALL_CLASS_LABEL_NAME
                         , SUBSTR(MIN(BASIS_YYYYMMDD), 5, 2) || '.' || SUBSTR(MIN(BASIS_YYYYMMDD), 7, 2)
                         || ' ~ ' || SUBSTR(MAX(BASIS_YYYYMMDD), 5, 2) || '.' || SUBSTR(MAX(BASIS_YYYYMMDD), 7, 2)  AS LARGE_CLASS_LABEL_NAME
                         , ''                   AS DAY_CODE
                         , MAX(BASIS_YYYYMMDD) || TO_CHAR(21) AS SORT_ORDER_NO
                   FROM   SCM_SYS_CALENDAR_M A
                   WHERE  A.BASIS_YYYYMMDD >= P_START_YYYYMMDD
                   AND    A.BASIS_YYYYMMDD <= P_END_YYYYMMDD
                   AND    1 = CASE WHEN P_BUCKET = 'ONLY_WEEKLY' THEN 1 ELSE 2 END
                   GROUP BY ISO_YYYYWW, ISO_WEEK, WEEK_NAME
              ) T
        ) A
        WHERE INSTR(',' || A.DIVISION_ID || ',', ',' || P_DIVISION_ID || ',') > 0
        ORDER BY SORT_ORDER_NO;

    ELSE
        /* ── V_USER_COL_CNT = 0 : 기본 컬럼 설정 ── */
        OPEN O_RC1 FOR
        SELECT C.PROGRAM_ID
             , C.SHEET_NAME
             , C.COLUMN_NAME
             , C.COLUMN_LABEL_NAME
             , TO_CHAR(C.SORT_ORDER_NO) AS SORT_ORDER_NO        --CONVERT(NVARCHAR(10), U.SORT_ORDER_NO) AS SORT_ORDER_NO
             , C.DATA_SORT_METHOD_CODE
             , C.SMALL_CLASS_LABEL_NAME
             , C.LARGE_CLASS_LABEL_NAME
             , '' AS DAY_CODE
             , C.FIXED_FLAG
             , C.COLUMN_WIDTH
             , C.CELL_CONTROL_OBJECT_TYPE_CODE
             , C.CELL_COMBO_DATA_TYPE
             , TO_CHAR(C.DATA_SCALE_NUMBER) AS DATA_SCALE_NUMBER
             , TO_CHAR(C.DATA_MAX_LENGTH) AS DATA_MAX_LENGTH
             , C.HORIZONTAL_ALIGN_CODE
             , C.UPPERCASE_APPLY_FLAG
             , C.VISIBLE_FLAG
             , C.DEFAULT_FLAG
             , C.USER_SELECTABLE_FLAG
             , C.VALID_YN
             , C.DIVISION_ID
        FROM   SCM_MST_SHEET_COLUMNS C
        WHERE  1 = 1
        AND    C.PROGRAM_ID  = V_PROGRAM_ID
        AND    C.SHEET_NAME  = V_SHEET_NAME
        AND    C.DEFAULT_FLAG = 'Y'
        AND    C.VALID_YN     = 'Y'
        AND    INSTR(',' || C.DIVISION_ID || ',', ',' || P_DIVISION_ID || ',') > 0

        UNION ALL

        SELECT * FROM (
            /* ── 비노출 기본 컬럼 ── */
            SELECT C.PROGRAM_ID
                 , C.SHEET_NAME
                 , C.COLUMN_NAME
                 , C.COLUMN_LABEL_NAME
                 , TO_CHAR(C.SORT_ORDER_NO) AS SORT_ORDER_NO        --CONVERT(NVARCHAR(10), U.SORT_ORDER_NO) AS SORT_ORDER_NO
                 , C.DATA_SORT_METHOD_CODE
                 , C.SMALL_CLASS_LABEL_NAME
                 , C.LARGE_CLASS_LABEL_NAME
                 , '' AS DAY_CODE
                 , C.FIXED_FLAG
                 , C.COLUMN_WIDTH
                 , C.CELL_CONTROL_OBJECT_TYPE_CODE
                 , C.CELL_COMBO_DATA_TYPE
                 , TO_CHAR(C.DATA_SCALE_NUMBER) AS DATA_SCALE_NUMBER
                 , TO_CHAR(C.DATA_MAX_LENGTH) AS DATA_MAX_LENGTH
                 , C.HORIZONTAL_ALIGN_CODE
                 , C.UPPERCASE_APPLY_FLAG
                 , C.VISIBLE_FLAG
                 , C.DEFAULT_FLAG
                 , C.USER_SELECTABLE_FLAG
                 , C.VALID_YN
                 , C.DIVISION_ID
            FROM   SCM_MST_SHEET_COLUMNS C
            WHERE  1 = 1
            AND    C.PROGRAM_ID  = V_PROGRAM_ID
            AND    C.SHEET_NAME  = V_SHEET_NAME
            AND    C.VISIBLE_FLAG = 'N'
            -- 2026.09.28 AJS 주석처리 (START)
            /* AS-IS MSSQL 의 DEFAULT_FLAG = '' 는 빈 값 비교로 성립하지만 Oracle 은 NULL 비교라 항상 거짓 */
            /* 비노출 기본 칸 갈래가 0행이 되어 Version 칸 정의가 내려가지 않음 — AS-IS 실측 [N]['']  = TO-BE [N]['Y'] */
            -- AND    C.DEFAULT_FLAG = ''
            AND    C.DEFAULT_FLAG = 'Y'
            -- 2026.09.28 AJS 주석처리 (END)
            AND    C.VALID_YN     = 'Y'
            AND    INSTR(',' || C.DIVISION_ID || ',', ',' || P_DIVISION_ID || ',') > 0

            UNION ALL

            /* ── 캘린더 동적 컬럼 ── */
            SELECT V_PROGRAM_ID   AS PROGRAM_ID
                 , V_SHEET_NAME AS SHEET_NAME
                 , T.COLUMN_NAME
                 , T.COLUMN_LABEL_NAME
                 , T.SORT_ORDER_NO
                 , ''         AS DATA_SORT_METHOD_CODE
                 , T.SMALL_CLASS_LABEL_NAME
                 , T.LARGE_CLASS_LABEL_NAME
                 , T.DAY_CODE
                 , ''         AS FIXED_FLAG
                 , CASE WHEN P_BUCKET = 'ONLY_WEEKLY' THEN 100
                        ELSE 50 END AS COLUMN_WIDTH
                 , 'FPNumber' AS CELL_CONTROL_OBJECT_TYPE_CODE
                 , ''         AS CELL_COMBO_DATA_TYPE
                 , ''         AS DATA_SCALE_NUMBER
                 , ''         AS DATA_MAX_LENGTH
                 , 'R'        AS HORIZONTAL_ALIGN_CODE
                 , 'Y'        AS UPPERCASE_APPLY_FLAG
                 , 'Y'        AS VISIBLE_FLAG
                 , ''         AS DEFAULT_FLAG
                 , ''         AS USER_SELECTABLE_FLAG
                 , ''         AS VALID_YN
                 --, CASE WHEN CHARINDEX('81', @p_divisIon_id) > 0 OR CHARINDEX('82', @p_divisIon_id) > 0 THEN
                    --  CASE WHEN CHARINDEX('40', @p_divisIon_id) > 0 THEN '40,81,82'
                    --       ELSE '81,82' END
                 --  ELSE
                    --  '40'
                 --  END AS DIVISION_ID
                 , P_DIVISION_ID AS DIVISION_ID
            FROM  (
                   SELECT 'D_' || A.BASIS_YYYYMMDD   AS COLUMN_NAME
                        , A.CALENDAR_DAY            AS COLUMN_LABEL_NAME
                        , A.WEEK_NAME               AS SMALL_CLASS_LABEL_NAME
                        , A.MONTH_NAME              AS LARGE_CLASS_LABEL_NAME
                        , A.DAYOFWEEK               AS DAY_CODE
                        , A.BASIS_YYYYMMDD || TO_CHAR(31) AS SORT_ORDER_NO
                   FROM   SCM_SYS_CALENDAR_M A
                   WHERE  A.BASIS_YYYYMMDD >= P_START_YYYYMMDD --CONVERT(CHAR(8), CURRENT_TIMESTAMP, 112)
                   AND    A.BASIS_YYYYMMDD <= P_END_YYYYMMDD --CONVERT(CHAR(8), DATEADD(YYYY, 1, CURRENT_TIMESTAMP), 112)
                   AND    1 = CASE WHEN P_BUCKET != 'ONLY_WEEKLY' THEN 1 ELSE 2 END
                   UNION ALL
                   SELECT 'W_' || A.BASIS_YYYYMM || A.ISO_WEEK   AS COLUMN_NAME
                        , A.WEEK_NAME          AS COLUMN_LABEL_NAME
                        , A.WEEK_NAME          AS SMALL_CLASS_LABEL_NAME
                        , A.MONTH_NAME         AS LARGE_CLASS_LABEL_NAME
                        , ''                   AS DAY_CODE
                        , A.BASIS_START_DATE || TO_CHAR(21) AS SORT_ORDER_NO
                   FROM   SCM_SYS_CALENDAR_M A
                   WHERE  A.BASIS_YYYYMMDD >= P_START_YYYYMMDD --CONVERT(CHAR(8), CURRENT_TIMESTAMP, 112)
                   AND    A.BASIS_YYYYMMDD <= P_END_YYYYMMDD --CONVERT(CHAR(8), DATEADD(YYYY, 1, CURRENT_TIMESTAMP), 112)
                   AND    1 = CASE WHEN P_BUCKET != 'ONLY_WEEKLY' THEN 1 ELSE 2 END
                   GROUP BY A.BASIS_YYYYMM
                          , A.ISO_WEEK
                          , A.WEEK_NAME
                          , A.MONTH_NAME
                          , A.BASIS_START_DATE
                   UNION ALL
                   SELECT 'M_' || A.BASIS_YYYYMM  AS COLUMN_NAME
                         , A.MONTH_NAME          AS COLUMN_LABEL_NAME
                         , A.MONTH_NAME          AS SMALL_CLASS_LABEL_NAME
                         , A.MONTH_NAME          AS LARGE_CLASS_LABEL_NAME
                         , ''                    AS DAY_CODE
                         , MIN(A.BASIS_START_DATE) || '01' AS SORT_ORDER_NO
                   FROM    SCM_SYS_CALENDAR_M A
                   WHERE  A.BASIS_YYYYMMDD >= P_START_YYYYMMDD --CONVERT(CHAR(8), CURRENT_TIMESTAMP, 112)
                   AND    A.BASIS_YYYYMMDD <= P_END_YYYYMMDD --CONVERT(CHAR(8), DATEADD(YYYY, 1, CURRENT_TIMESTAMP), 112)
                   AND    1 = CASE WHEN P_BUCKET != 'ONLY_WEEKLY' THEN 1 ELSE 2 END
                   GROUP BY A.BASIS_YYYYMM
                          , A.MONTH_NAME
                   -- [C20220620-000567]GSCM DM 시스템의 수작업 LOSS 및 분석 용이하기 하귀 위한 기능 개선 ( Partail week의 경우 week만 표시)
                   UNION ALL
                   SELECT 'W_' || SUBSTR(MAX(BASIS_YYYYMMDD), 1, 6) || ISO_WEEK  AS COLUMN_NAME
                         , WEEK_NAME AS COLUMN_LABEL_NAME
                         , WEEK_NAME AS SMALL_CLASS_LABEL_NAME
                         , SUBSTR(MIN(BASIS_YYYYMMDD), 5, 2) || '.' || SUBSTR(MIN(BASIS_YYYYMMDD), 7, 2)
                         || ' ~ ' || SUBSTR(MAX(BASIS_YYYYMMDD), 5, 2) || '.' || SUBSTR(MAX(BASIS_YYYYMMDD), 7, 2)  AS LARGE_CLASS_LABEL_NAME
                         , ''                   AS DAY_CODE
                         , MAX(BASIS_YYYYMMDD) || TO_CHAR(21) AS SORT_ORDER_NO
                   FROM   SCM_SYS_CALENDAR_M A
                   WHERE  A.BASIS_YYYYMMDD >= P_START_YYYYMMDD
                   AND    A.BASIS_YYYYMMDD <= P_END_YYYYMMDD
                   AND    1 = CASE WHEN P_BUCKET = 'ONLY_WEEKLY' THEN 1 ELSE 2 END
                   GROUP BY ISO_YYYYWW, ISO_WEEK, WEEK_NAME
                ) T
            ) A
            WHERE INSTR(',' || A.DIVISION_ID || ',', ',' || P_DIVISION_ID || ',') > 0
          ORDER BY SORT_ORDER_NO;

    END IF;

    /* ── 프로시저 처리 결과 반환 (O_RESULT_CURSOR) — 조회 성공 ── */
    OPEN O_RESULT_CURSOR FOR
    SELECT '0' AS CODE, 'SUCCESS' AS MSG, CASE WHEN 1 = 2 THEN '-' ELSE NULL END AS EVENT FROM DUAL;

    /* ── 종료 로그 ── */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH($$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE); END;

EXCEPTION
    WHEN OTHERS THEN
        -- 1) 트랜잭션이 있으면 ROLLBACK
        ROLLBACK;

        -- 2) 에러 정보 캡처
        V_LOG_TYPE    := 'ERROR';
        V_LOG_MESSAGE := 'EXCEPTION';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        V_SQL_CODE    := TO_CHAR(SQLCODE);
        V_SQL_ERRMSG  := SQLERRM;
        V_PROC_INPUT  := JSON_OBJECT(
            'P_START_YYYYMMDD' VALUE P_START_YYYYMMDD,
            'P_END_YYYYMMDD'   VALUE P_END_YYYYMMDD,
            'P_CREATED_BY'     VALUE P_CREATED_BY,
            'P_DIVISION_ID'    VALUE P_DIVISION_ID,
            'P_BUCKET'         VALUE P_BUCKET
        );
        V_BACKTRACE   := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;

        -- 3) 에러 로그 기록
        BEGIN
            SCM_MGR.PR_SCM_SYS_LOG_BATCH(
                $$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE,
                V_DESCRIPTION, D_EVENT_DATE, V_PROC_INPUT,
                V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE
            );
        END;

        -- 4) 에러 전파 (O_RESULT_CURSOR 미오픈)
        RAISE_APPLICATION_ERROR(-20001,
          '[' || $$PLSQL_UNIT || '] SQLCODE=' || V_SQL_CODE ||
          ' / SQLERRM=' || V_SQL_ERRMSG ||
          ' / BACKTRACE=' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE ||
          ' / PARAMS=' || V_PROC_INPUT
        );
        RAISE;
END P_DMF0040_GET_SPREAD_TITLE;

END PKG_DMF0040;

