            CREATION_DATE,
            p_created_by, --LAST_UPDATED_BY,
            SYSDATE, --LAST_UPDATE_DATE,
            p_version_no, --ATTRIBUTE1,
            ATTRIBUTE2,
            ATTRIBUTE3,
            ATTRIBUTE4,
            ATTRIBUTE5,
            ATTRIBUTE6,
