    OPEN O_RC1 FOR SELECT 'OK' RESULT, p_count CNT FROM DUAL;
    OPEN O_RC2 FOR SELECT 'OK' RESULT FROM DUAL;


EXCEPTION
    WHEN OTHERS THEN
    V_LOG_TYPE   := 'ERROR';
    V_SQL_CODE   := TO_CHAR(SQLCODE);
