    v_to_yyyymmdd   := SUBSTR(p_to_yyyymmdd, 1, 6);

    --============================================================================
    -- 사용자의 팀정보 & 권한
    --============================================================================
    BEGIN
        SELECT NVL(( SELECT SEGMENT3 FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                     WHERE LOOKUP_TYPE = 'PM_TEAM_MAPPING'
                     AND   VALID_YN = 'Y'
                     AND   SEGMENT1 = U.DEPT_ID
