        FROM SCM_ADM_USER_M U   -- [2026-10-06 / POJ] TO-BE기준 테이블 변경 TB_FX_User → SCM_ADM_USER_M
        WHERE U.USER_ID = p_created_by;   -- [2026-10-06 / POJ] TO-BE기준 컬럼 변경 UserID → USER_ID
