                -- [E20250522-001188]_Business Plan UI 데이터 저장 시 Trim 처리 (END)
                -- -----------------------------------------------------------------------------------------------
                INSERT /*+ NO_PARALLEL */
                INTO GT_SDPB2_BP_FCST_4
