                          AND C.CURRENCY = B.CURRENCY
                          AND C.DEPT_ID = B.DEPT_ID
                          AND C.END_CUSTOMER = B.END_CUSTOMER
                          AND C.BIZ_TYPE = B.BIZ_TYPE
