               AND UNIT_TP_CD = ''D''
        ) T2
        ON A.DIVISION_ID = T2.UNIT_ID


    ) T
PIVOT (SUM(QTY) FOR YYYYMM IN (' || V_PROD || ')
) PVT
ORDER BY DATA_TYPE NULLS FIRST, DIVISION_ID NULLS FIRST, VERSION_NO NULLS FIRST, CUTOFF_TYPE NULLS FIRST, CUTOFF_YYYYMMDD NULLS FIRST, DISPLAY_SEQ1 NULLS FIRST, DISPLAY_SEQ2 NULLS FIRST, CUST_REPORT NULLS FIRST, END_CUST_REPORT NULLS FIRST, CUST_GROUP_DTL NULLS FIRST
