       , CURRENCY NULLS FIRST, COMPANY_ID NULLS FIRST, CELL_PROD_SITE NULLS FIRST, BIZ_TYPE_NAME40 NULLS FIRST, APPLICATION_GR NULLS FIRST, NVL(APP, '''') NULLS FIRST
