                             , NVL(NULLIF(RTRIM(A.CUST_REPORT),''), '/'), NVL(NULLIF(RTRIM(A.PRODUCT_GROUP),''), '/'), NVL(NULLIF(RTRIM(A.SCM_SITE_ID),''), '/'), NVL(NULLIF(RTRIM(A.ITEM_ID),''), '/'), NVL(A.DOM_EXP, '/'), NVL(NULLIF(RTRIM(A.FCST_TYPE),''), '/'), NVL(NULLIF(RTRIM(A.INCOTERMS),''), '/'), 'LOC', '/', NVL(NULLIF(RTRIM(B.YYYYMMDD),''), '/')    --  2026.10.11 AJS
                             , NVL(NULLIF(RTRIM(A.CURRENCY),''), '/'), NVL(TO_NUMBER(B.QTY), 0), V_CREATED_BY, SYSDATE, V_CREATED_BY, SYSDATE
                             , A.ATTRIBUTE1, A.ATTRIBUTE2, A.ATTRIBUTE3, A.ATTRIBUTE4, A.ATTRIBUTE5, A.ATTRIBUTE6, A.ATTRIBUTE7, A.ATTRIBUTE8, A.ATTRIBUTE9, A.ATTRIBUTE10
--                             , NVL(A.COMPANY_ID, '-'), NVL(NULLIF(RTRIM(A.PROJECT_CODE),''), '/'), A.SOLDTO_CUST_REPORT, A.OWNER_NAME, A.CUST_GROUP_DTL, A.PRODUCT_DETAILS, A.FORECAST_INFO_SPEC, A.NICK_NAME    --  2026.10.11 AJS
                             , NVL(A.COMPANY_ID, '/'), NVL(NULLIF(RTRIM(A.PROJECT_CODE),''), '/'), A.SOLDTO_CUST_REPORT, A.OWNER_NAME, A.CUST_GROUP_DTL, A.PRODUCT_DETAILS, A.FORECAST_INFO_SPEC, A.NICK_NAME    --  2026.10.11 AJS
                             , A.FORECAST_INFO_CELL_MODEL, A.FORECAST_INFO_CELL_PACK_COUNT, A.FORECAST_INFO_BIZ_TYPE, A.COMPANY_NAME, A.APPLICATION, A.APPLICATION_GR
                             , A.COUNTRY_KR_NAME, A.ROUTE, NVL(NULLIF(RTRIM(A.CELL_PROD_SITE),''), '/') --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
