                         AND A.PROJECT_CODE = B.PROJECT_CODE AND A.SCM_SITE_ID = B.SCM_SITE_ID AND A.ITEM_ID = B.ITEM_ID
                         AND A.YYYYMMDD LIKE SUBSTR(B.YYYYMMDD,1,4)||'%' AND A.CURRENCY = B.CURRENCY AND A.COMPANY_ID = B.COMPANY_ID
