--                             , NVL(NULLIF(RTRIM(A.CUST_REPORT),''), '/'), NVL(NULLIF(RTRIM(A.PRODUCT_GROUP),''), '/'), NVL(NULLIF(RTRIM(A.SCM_SITE_ID),''), '/'), NVL(NULLIF(RTRIM(A.ITEM_ID),''), '/'), NVL(A.DOM_EXP, '-'), NVL(NULLIF(RTRIM(A.FCST_TYPE),''), '/'), NVL(NULLIF(RTRIM(A.INCOTERMS),''), '/'), 'SalesAmt_USD', '/', NVL(NULLIF(RTRIM(B.YYYYMMDD),''), '/')    --  2026.10.11 AJS
                             , NVL(NULLIF(RTRIM(A.CUST_REPORT),''), '/'), NVL(NULLIF(RTRIM(A.PRODUCT_GROUP),''), '/'), NVL(NULLIF(RTRIM(A.SCM_SITE_ID),''), '/'), NVL(NULLIF(RTRIM(A.ITEM_ID),''), '/'), NVL(A.DOM_EXP, '/'), NVL(NULLIF(RTRIM(A.FCST_TYPE),''), '/'), NVL(NULLIF(RTRIM(A.INCOTERMS),''), '/'), 'SalesAmt_USD', '/', NVL(NULLIF(RTRIM(B.YYYYMMDD),''), '/')    --  2026.10.11 AJS
                             , NVL(NULLIF(RTRIM(A.CURRENCY),''), '/'), NVL(TO_NUMBER(B.QTY), 0), V_CREATED_BY, SYSDATE, V_CREATED_BY, SYSDATE
                             , A.ATTRIBUTE1, A.ATTRIBUTE2, A.ATTRIBUTE3, A.ATTRIBUTE4, A.ATTRIBUTE5, A.ATTRIBUTE6, A.ATTRIBUTE7, A.ATTRIBUTE8, A.ATTRIBUTE9, A.ATTRIBUTE10
