     * 2022.08.31   LWY            PJ20216994 / LGES Digital SCM 3 Level 가속화를 위한 개선 Phase 2 - Isuzu 추가
     * 2023.01.02   LWY            PJ20216994 / LGES Digital SCM 3 Level 가속화를 위한 개선 Phase 2 - 조회기준 변경(main / hist) - 당주,전주(main) / 당주,전주 이전(hist)
     * 2023/04/10   LWY			   PJ20230691R  LGES SCM 역량 강화 위한 SCP 개선과제 이행 - DIVISION_ID 공통화 작업(div_commonization)
     * 2023.07.26   vadabi3		   PJ20230691R  LGES SCM 역량 강화 위한 SCP 개선과제 이행 - Model, Material 개선
     * 2026.09.17                  [MSSQL -> Oracle 전환] 머리 행 적재 동적 SQL 을 정적 SQL 로 전환(기간 칸만 동적)
     *                             시트 이름 · 사용자 ID 대소문자 무시 비교(AS-IS 정렬규칙 CI 대응)
     * 2026.10.06   AJS            ISUZU 품목 적재 조회 속도 개선 : 품목 뷰를 하위 뷰(SCM_MST_FINAL_ITEM_ORIGIN_DIV_V)로 바꿔 사업부 갈래 중복 전개 제거 (EXISTS 판정 품목 동일)
     *==================================================================================================*/
    PROCEDURE P_SCP0011_GET_PROD_MODEL_TITLE
    (
        P_DIVISION_ID           IN  VARCHAR2,
        P_OPERATION_GROUP       IN  VARCHAR2,
        P_SCM_SITE_ID           IN  VARCHAR2,
        P_MODEL_ID              IN  VARCHAR2,
        P_ITEM_ID               IN  VARCHAR2,
        P_FROM_YYYYMMDD         IN  VARCHAR2,
        P_TO_YYYYMMDD           IN  VARCHAR2,
        P_PLAN_START_YYYYMMDD   IN  VARCHAR2,
        P_PLAN_TYPE             IN  VARCHAR2,
        P_SEQ                   IN  VARCHAR2,
        P_PROGRAM_ID            IN  VARCHAR2 DEFAULT 'SCP0011',
        P_SHEET_NAME            IN  VARCHAR2 DEFAULT 'MODEL',
        P_USER_ID               IN  VARCHAR2,
        P_ELECTRODE_TYPE        IN  VARCHAR2 DEFAULT NULL,
        P_NICK_NAME             IN  VARCHAR2 DEFAULT NULL,
        P_BUCKET                IN  VARCHAR2 DEFAULT NULL,
        P_CHK_ALL               IN  VARCHAR2 DEFAULT NULL,
        P_DEBUG_MODE            IN  VARCHAR2 DEFAULT 'F',
        O_RC1                   OUT SYS_REFCURSOR,
        O_RESULT_CODE           OUT VARCHAR2,
        O_RESULT_MSG            OUT VARCHAR2
    )
    IS
        V_DIVISION_ID           VARCHAR2(50 CHAR)  := UPPER(P_DIVISION_ID);
        V_OPERATION_GROUP       VARCHAR2(50 CHAR)  := UPPER(P_OPERATION_GROUP);
        V_PLAN_TYPE             VARCHAR2(50 CHAR)  := UPPER(P_PLAN_TYPE);
        V_PROGRAM_ID            VARCHAR2(300 CHAR) := UPPER(P_PROGRAM_ID);
        V_SHEET_NAME            VARCHAR2(150 CHAR) := UPPER(P_SHEET_NAME);
        V_USER_ID               VARCHAR2(150 CHAR) := UPPER(P_USER_ID);
        V_BUCKET                VARCHAR2(10 CHAR)  := UPPER(P_BUCKET);
        V_SEQ                   NUMBER;
        V_PLAN_START_DATE       DATE;

        V_CNT_USR_MEASURE       NUMBER := 0;
        V_MIN_YYYYMMDD          VARCHAR2(8 CHAR);
        V_FROM_YYYYMMDD         VARCHAR2(8 CHAR);
        V_TO_YYYYMMDD           VARCHAR2(8 CHAR);
        V_FROM_RESULT           VARCHAR2(8 CHAR);
        V_TO_RESULT             VARCHAR2(8 CHAR);
        V_FROM_RESULT_DATE      DATE;
        V_TO_RESULT_DATE        DATE;
        V_FROM_CMP              VARCHAR2(8 CHAR);   /* 빈 문자 비교값 */
        V_TO_CMP                VARCHAR2(8 CHAR);

        V_SITE_TAB              T_STR_TAB;
        V_SITE_ALL              VARCHAR2(1 CHAR);
        V_ITEM_TAB              T_STR_TAB;
        V_ITEM_ALL              VARCHAR2(1 CHAR);
        V_ELEC_TAB              T_STR_TAB;
        V_ELEC_ALL              VARCHAR2(1 CHAR);
        V_MODEL_TAB             T_STR_TAB;
        V_MODEL_ALL             VARCHAR2(1 CHAR);
        V_RES_DIV_TAB           T_STR_TAB;
        V_OSP_DIV_TAB           T_STR_TAB;
        V_NICK_YN               VARCHAR2(1 CHAR) := 'N';

        V_QRY_SUM               CLOB;
        V_SQL                   CLOB;
    BEGIN

        O_RESULT_CODE := 'S';
        O_RESULT_MSG  := NULL;

        V_SEQ             := TO_NUMBER(P_SEQ);
        SELECT TO_DATE(P_PLAN_START_YYYYMMDD DEFAULT NULL ON CONVERSION ERROR, 'YYYYMMDD')
          INTO V_PLAN_START_DATE
          FROM DUAL;

        SELECT COUNT(*)
          INTO V_CNT_USR_MEASURE
          FROM SCM_MST_TITLESET_USER
         WHERE PROGRAM_ID         = V_PROGRAM_ID
           AND UPPER(SHEET_NAME)  = V_SHEET_NAME
           AND UPPER(USER_ID)     = V_USER_ID;

        P_SET_PERIOD(P_PLAN_START_YYYYMMDD, P_FROM_YYYYMMDD, P_TO_YYYYMMDD
                   , V_FROM_YYYYMMDD, V_TO_YYYYMMDD, V_FROM_RESULT, V_TO_RESULT);

        V_FROM_RESULT_DATE := F_STR_DATE(V_FROM_RESULT);
        V_TO_RESULT_DATE   := F_STR_DATE(V_TO_RESULT);
        V_FROM_CMP         := F_CMP(V_FROM_YYYYMMDD);
        V_TO_CMP           := F_CMP(V_TO_YYYYMMDD);

        IF P_DEBUG_MODE = 'T' THEN
            DBMS_OUTPUT.PUT_LINE('----------------------------------');
            DBMS_OUTPUT.PUT_LINE('v_from_yyyymmdd =' || V_FROM_YYYYMMDD);
            DBMS_OUTPUT.PUT_LINE('v_to_yyyymmdd =' || V_TO_YYYYMMDD);
            DBMS_OUTPUT.PUT_LINE('v_from_result =' || V_FROM_RESULT);
            DBMS_OUTPUT.PUT_LINE('v_to_result =' || V_TO_RESULT);
            DBMS_OUTPUT.PUT_LINE('----------------------------------');
        END IF;

        P_SPLIT_LIST(P_SCM_SITE_ID   , 'Y', V_SITE_TAB , V_SITE_ALL);
        P_SPLIT_LIST(P_ITEM_ID       , 'Y', V_ITEM_TAB , V_ITEM_ALL);
        P_SPLIT_LIST(P_ELECTRODE_TYPE, 'Y', V_ELEC_TAB , V_ELEC_ALL);
        P_SPLIT_LIST(P_MODEL_ID      , 'Y', V_MODEL_TAB, V_MODEL_ALL);

        -- 2021.11.24 : 체크 시 bucket='daily' 조회
        IF UPPER(P_CHK_ALL) = 'Y' THEN
            V_BUCKET := 'DAILY';
        END IF;

        IF V_DIVISION_ID = 'EE' THEN
            V_RES_DIV_TAB := T_STR_TAB('40', '81', '82');
        ELSIF V_DIVISION_ID = 'EE_UC' THEN
            V_RES_DIV_TAB := T_STR_TAB('81_UC');
        ELSIF V_DIVISION_ID = 'EE_HM' THEN
            V_RES_DIV_TAB := T_STR_TAB('81_HM');
        ELSIF V_DIVISION_ID = 'EE_ST' THEN
            V_RES_DIV_TAB := T_STR_TAB('81_ST');
        ELSE
            V_RES_DIV_TAB := T_STR_TAB(V_DIVISION_ID);
        END IF;

        IF V_DIVISION_ID = 'EE' THEN
            V_OSP_DIV_TAB := T_STR_TAB('40', '81', '82');
        ELSIF V_DIVISION_ID = 'EE_UC' THEN
            V_OSP_DIV_TAB := T_STR_TAB('81_UC');
        ELSE
            V_OSP_DIV_TAB := T_STR_TAB(V_DIVISION_ID);
        END IF;

        /********************************************************************************
        * 임시테이블 초기화
        ********************************************************************************/
        DELETE FROM GT_0011_NICKITEM;
        DELETE FROM GT_0011_ISUZU;
        DELETE FROM GT_0011_TTL_HDR;
        DELETE FROM GT_0011_TTL_MAIN;

        /********************************************************************************
        * 임시테이블만들기 - nick name 조회 시
        ********************************************************************************/
        IF RTRIM(P_NICK_NAME) IS NOT NULL THEN

            V_NICK_YN := 'Y';

            INSERT INTO GT_0011_NICKITEM
                 (
                   ITEM_ID
                 )
            SELECT DISTINCT
                   ITEM_ID
              FROM SCM_MST_ITEM_SN
             WHERE NICK_NAME IS NOT NULL
               AND NICK_NAME LIKE '%' || UPPER(P_NICK_NAME) || '%';     /* 원장 NICK_NAME 소문자 0 건 */

        END IF;

        -- 2022.08.31 start
        -- ISUZU item
        INSERT INTO GT_0011_ISUZU
             (
               ITEM_ID
             )
        SELECT A.ITEM_ID
--          FROM SCM_MST_FINAL_ITEM_V A                                                     --  2026.10.06 AJS
          FROM SCM_MST_FINAL_ITEM_ORIGIN_DIV_V A          /* 품목 뷰 사업부 갈래 중복 전개 제거 - EXISTS 판정 품목 동일 */   --  2026.10.06 AJS
             , SCP_MST_FINAL_ITEM_V B
         WHERE A.ITEM_ID = B.ITEM_ID
           AND A.IS_YN   = 'Y';
        -- 2022.08.31 end

        -- 2023.01.02
        V_MIN_YYYYMMDD := F_PREV_MONDAY;     -- previous monday

        /********************************************************************************
        * 임시테이블만들기 - Header 부분
        ********************************************************************************/
        -- 계획 구간
        IF F_CMP(P_PLAN_START_YYYYMMDD) >= V_MIN_YYYYMMDD THEN

            INSERT INTO GT_0011_TTL_HDR
                 (
                   DIVISION_ID
                  ,OPERATION_GROUP
                  ,SCM_SITE_ID
                  ,ITEM_ID
                  ,OPERATION_ID
                  ,LINE_ID
                  ,MEASURE
                  ,ORIGIN_DIVISION_ID
                  ,ELECTRODE_TYPE
                 )
            SELECT A.DIVISION_ID
                 , A.OPERATION_GROUP
                 , A.SCM_SITE_ID
                 , A.ITEM_ID
                 , A.OPERATION_ID
                 , A.LINE_ID
                 , A.MEASURE
                 , A.ORIGIN_DIVISION_ID
                 , A.ELECTRODE_TYPE
              FROM SCP_ANL_PRODUCTION_PLAN A
             WHERE A.YYYYMMDD                >= P_FROM_YYYYMMDD
               AND A.YYYYMMDD                <= P_TO_YYYYMMDD
               AND A.DIVISION_ID              = V_DIVISION_ID
               AND A.PLAN_START_YYYYMMDD      = P_PLAN_START_YYYYMMDD
               AND A.PLAN_START_YYYYMMDD_DATE = V_PLAN_START_DATE          /* 파티션 프루닝 */
               AND A.PLAN_TYPE                = V_PLAN_TYPE
               AND A.SEQ                      = V_SEQ
               AND A.OPERATION_GROUP          = V_OPERATION_GROUP
               AND (V_SITE_ALL = 'Y' OR A.SCM_SITE_ID    IN (SELECT COLUMN_VALUE FROM TABLE(V_SITE_TAB)))
               AND (V_ITEM_ALL = 'Y' OR A.ITEM_ID        IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)))
               AND (V_ELEC_ALL = 'Y' OR A.ELECTRODE_TYPE IN (SELECT COLUMN_VALUE FROM TABLE(V_ELEC_TAB)));

        ELSIF F_CMP(P_PLAN_START_YYYYMMDD) < V_MIN_YYYYMMDD THEN

            INSERT INTO GT_0011_TTL_HDR
                 (
                   DIVISION_ID
                  ,OPERATION_GROUP
                  ,SCM_SITE_ID
                  ,ITEM_ID
                  ,OPERATION_ID
                  ,LINE_ID
                  ,MEASURE
                  ,ORIGIN_DIVISION_ID
                  ,ELECTRODE_TYPE
                 )
            SELECT A.DIVISION_ID
                 , A.OPERATION_GROUP
                 , A.SCM_SITE_ID
                 , A.ITEM_ID
                 , A.OPERATION_ID
                 , A.LINE_ID
                 , A.MEASURE
                 , A.ORIGIN_DIVISION_ID
                 , A.ELECTRODE_TYPE
              FROM HIST_SCP_ANL_PRODUCTION_PLAN A
             WHERE A.YYYYMMDD                >= P_FROM_YYYYMMDD
               AND A.YYYYMMDD                <= P_TO_YYYYMMDD
               AND A.DIVISION_ID              = V_DIVISION_ID
               AND A.PLAN_START_YYYYMMDD      = P_PLAN_START_YYYYMMDD
               AND A.PLAN_START_YYYYMMDD_DATE = V_PLAN_START_DATE          /* 파티션 프루닝 */
               AND A.PLAN_TYPE                = V_PLAN_TYPE
               AND A.SEQ                      = V_SEQ
               AND A.OPERATION_GROUP          = V_OPERATION_GROUP
               AND (V_SITE_ALL = 'Y' OR A.SCM_SITE_ID    IN (SELECT COLUMN_VALUE FROM TABLE(V_SITE_TAB)))
               AND (V_ITEM_ALL = 'Y' OR A.ITEM_ID        IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)))
               AND (V_ELEC_ALL = 'Y' OR A.ELECTRODE_TYPE IN (SELECT COLUMN_VALUE FROM TABLE(V_ELEC_TAB)));

        END IF;

        -- anl 테이블에는 과거구간 YYYYMMDD가 없으므로 실적 테이블에서 YYYYMMDD를 조회하여 추가해준다.
        INSERT INTO GT_0011_TTL_HDR
             (
               DIVISION_ID
              ,OPERATION_GROUP
              ,SCM_SITE_ID
              ,ITEM_ID
              ,OPERATION_ID
              ,LINE_ID
              ,MEASURE
              ,ORIGIN_DIVISION_ID
              ,ELECTRODE_TYPE
             )
        SELECT V_DIVISION_ID                                        AS DIVISION_ID     --div_commonization
             , A.SCP_OPERATION_GROUP                                AS OPERATION_GROUP
             , A.SCM_SITE_ID
             , A.ITEM_ID
             , A.OPERATION_ID
             , A.LINE_ID
             , 'PROD_PLAN_ENGINE'                                   AS MEASURE
             , A.DIVISION_ID                                        AS ORIGIN_DIVISION_ID
             , A.ELECTRODE_TYPE
          FROM SCM_DNM_PRODUCT_RESULT_V A
         WHERE (   SUBSTR(A.OPERATION_ID, 1, 5) IN (SELECT XA.SEGMENT1     --LOOKUP_TYPE 'SCP_PLAN_OPERATION' 에 정의된 공정만 조회
                                                      FROM SCM_ADM_LOOKUP_MASTER_DETAIL XA
                                                     WHERE XA.LOOKUP_TYPE = 'SCP_PLAN_OPERATION'
                                                       AND XA.SEGMENT1   <> 'F6000')
                -- 2022.08.31 start
                OR (    A.OPERATION_ID LIKE 'P5000%'
                    AND EXISTS (SELECT 1
                                  FROM GT_0011_ISUZU XB
                                 WHERE XB.ITEM_ID = A.ITEM_ID))
                -- 2022.08.31 end
                OR A.OPERATION_ID IN (SELECT XC.PLANT_ID                    --외주PACKER의 업체코드
                                        FROM SCM_MST_SITE XC
                                       WHERE XC.DIVISION_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_OSP_DIV_TAB))
                                         AND XC.SITE_TYPE    = 'PLANT'
                                         AND XC.OSP_YN       = 'Y'
                                         AND XC.VALID_YN     = 'Y'))
           AND A.PLAN_DATE           >= V_FROM_RESULT_DATE
           AND A.PLAN_DATE           <  V_TO_RESULT_DATE                  -- equal 표시 주의할것
           AND A.DIVISION_ID         IN (SELECT COLUMN_VALUE FROM TABLE(V_RES_DIV_TAB))
           AND A.SCP_OPERATION_GROUP  = V_OPERATION_GROUP
           AND A.SCM_SITE_ID         IS NOT NULL
           AND (V_SITE_ALL = 'Y' OR A.SCM_SITE_ID    IN (SELECT COLUMN_VALUE FROM TABLE(V_SITE_TAB)))
           AND (V_ITEM_ALL = 'Y' OR A.ITEM_ID        IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)))
           AND (V_ELEC_ALL = 'Y' OR A.ELECTRODE_TYPE IN (SELECT COLUMN_VALUE FROM TABLE(V_ELEC_TAB)));

        /* GT_0011_TTL_HDR 통계 수집(DBMS_STATS)은 넣지 않는다 - 임시 테이블이라도 트랜잭션이 확정되어 호출 측 작업이 함께 확정된다 */

        /********************************************************************************
        * 데이타조회, 임시테이블에 저장 - Main : #TblDynamicPivot_SCP0011_01
        ********************************************************************************/
        INSERT INTO GT_0011_TTL_MAIN
             (
               KEY_IDX
              ,DIVISION_ID
              ,OPERATION_GROUP
              ,SCM_SITE_ID
              ,ITEM_ID
              ,PLAN_TYPE
              ,PLAN_SEQ
              ,MEASURE
              ,MEASURE_NAME
              ,USER_SORT_ORDER_NO
              ,FROM_YYYYMMDD
              ,TO_YYYYMMDD
              ,PLAN_START_YYYYMMDD
              ,ORIGIN_DIVISION_ID
              ,ELECTRODE_TYPE
             )
        SELECT CASE
                   WHEN    IA.DIVISION_ID     IS NULL
                        OR IA.OPERATION_GROUP IS NULL
                        OR IA.SCM_SITE_ID     IS NULL
                        OR IA.ITEM_ID         IS NULL
                        OR IA.MEASURE         IS NULL
                   THEN NULL        /* AS-IS 문자열 결합은 NULL 이 섞이면 NULL */
                   ELSE IA.DIVISION_ID || IA.OPERATION_GROUP || IA.SCM_SITE_ID || IA.ITEM_ID || IA.MEASURE
               END                                                  AS KEY_IDX
             , IA.DIVISION_ID
             , IA.OPERATION_GROUP
             , IA.SCM_SITE_ID
             , IA.ITEM_ID
             , P_PLAN_TYPE                                          AS PLAN_TYPE
             , P_SEQ                                                AS PLAN_SEQ
             , IA.MEASURE
             , IA.MEASURE_NAME
             , IA.USER_SORT_ORDER_NO
             , P_FROM_YYYYMMDD                                      AS FROM_YYYYMMDD
             , P_TO_YYYYMMDD                                        AS TO_YYYYMMDD
             , P_PLAN_START_YYYYMMDD                                AS PLAN_START_YYYYMMDD
             , IA.ORIGIN_DIVISION_ID
             , IA.ELECTRODE_TYPE
          FROM (SELECT XC.DIVISION_ID
                     , XC.OPERATION_GROUP
                     , XC.SCM_SITE_ID
                     , XC.ITEM_ID
                     , XC.LINE_ID
                     , XC.OPERATION_ID
                     , XA.COLUMN_NAME                               AS MEASURE
                     , XA.COLUMN_LABEL_NAME                         AS MEASURE_NAME
                     , NVL(XB.SORT_ORDER_NO, XA.SORT_ORDER_NO)      AS USER_SORT_ORDER_NO
                     , XC.ORIGIN_DIVISION_ID
                     , XC.ELECTRODE_TYPE
                  FROM SCM_MST_SHEET_MEASURE    XA
                     , SCM_MST_TITLESET_USER    XB
                     , GT_0011_TTL_HDR          XC      -- Header : #TblDynamicPivot_SCP0011_02
                 WHERE XA.PROGRAM_ID          = XB.PROGRAM_ID(+)
                   AND UPPER(XA.SHEET_NAME)   = UPPER(XB.SHEET_NAME(+))
                   AND UPPER(XA.COLUMN_NAME)  = UPPER(XB.COLUMN_NAME(+))
                   AND UPPER(XB.USER_ID(+))   = V_USER_ID
                   AND (   V_CNT_USR_MEASURE = 0
                        OR EXISTS (SELECT 1
                                     FROM SCM_MST_TITLESET_USER SA
                                    WHERE SA.PROGRAM_ID         = V_PROGRAM_ID
                                      AND UPPER(SA.SHEET_NAME)  = V_SHEET_NAME
                                      AND UPPER(SA.USER_ID)     = V_USER_ID
                                      AND UPPER(SA.COLUMN_NAME) = UPPER(XA.COLUMN_NAME)))
                   AND XA.VALID_YN            = 'Y'
                   AND XA.PROGRAM_ID          = V_PROGRAM_ID
                   AND UPPER(XA.SHEET_NAME)   = V_SHEET_NAME
                   AND (   V_OPERATION_GROUP = 'A'
                        OR XA.ATTRIBUTE1 IS NULL
                        OR XA.ATTRIBUTE1 <> 'A')
                 GROUP BY XC.DIVISION_ID
                        , XC.OPERATION_GROUP
                        , XC.SCM_SITE_ID
                        , XC.ITEM_ID
                        , XC.LINE_ID
                        , XC.OPERATION_ID
                        , XA.COLUMN_NAME
                        , XA.COLUMN_LABEL_NAME
                        , XC.ORIGIN_DIVISION_ID
                        , XC.ELECTRODE_TYPE
                        , NVL(XB.SORT_ORDER_NO, XA.SORT_ORDER_NO)) IA;

        /* GT_0011_TTL_MAIN 통계 수집(DBMS_STATS)은 넣지 않는다 - 임시 테이블이라도 트랜잭션이 확정되어 호출 측 작업이 함께 확정된다 */

        /********************************************************************************
        * PIVOIT처리 - 칸 값은 모두 '0'
        ********************************************************************************/
        -- PIVOIT 대상 날짜문자열 생성
        V_QRY_SUM := NULL;

        FOR R IN (SELECT IA.COL_NAME
                    FROM (SELECT 'W_' || XA.BASIS_YYYYMM || XA.ISO_WEEK             AS COL_NAME
                               , XA.BASIS_START_DATE || '21'                        AS SORT_ORDER_NO
                            FROM SCM_SYS_CALENDAR_M XA
                           WHERE XA.BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                             AND (V_BUCKET = 'DAILY' OR V_BUCKET = 'WEEKLY')
                           GROUP BY XA.BASIS_YYYYMM
                                  , XA.ISO_WEEK
                                  , XA.BASIS_START_DATE
                           UNION ALL
                          SELECT 'M_' || XB.BASIS_YYYYMM                            AS COL_NAME
                               , MIN(XB.BASIS_START_DATE) || '01'                   AS SORT_ORDER_NO
                            FROM SCM_SYS_CALENDAR_M XB
                           WHERE XB.BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                           GROUP BY XB.BASIS_YYYYMM
                                  , XB.MONTH_NAME
                           UNION ALL
                          SELECT 'D_' || XC.BASIS_YYYYMMDD                          AS COL_NAME
                               , XC.BASIS_YYYYMMDD || '31'                          AS SORT_ORDER_NO
                            FROM SCM_SYS_CALENDAR_M XC
                           WHERE XC.BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                             AND V_BUCKET = 'DAILY'
                           GROUP BY XC.BASIS_YYYYMMDD) IA
                   ORDER BY IA.SORT_ORDER_NO)
        LOOP
            V_QRY_SUM := V_QRY_SUM || '             , ''0'' AS ' || R.COL_NAME || CHR(10);
        END LOOP;

        V_SQL := 'SELECT IX.*' || CHR(10)
              || '  FROM (SELECT XA.KEY_IDX' || CHR(10)
              || '             , XA.DIVISION_ID' || CHR(10)
              || '             , XA.DIVISION_ID AS DIVISION_NAME' || CHR(10)
              || '             , XA.OPERATION_GROUP' || CHR(10)
              || '             , FN_GET_LOOKUP_CODE_DESC(''OPERATION_GROUP'', XA.OPERATION_GROUP) AS OPERATION_GROUP_NAME' || CHR(10)
              || '             , XA.SCM_SITE_ID' || CHR(10)
              || '             , FN_GET_SCM_SITE_DESCRIPTION(XA.DIVISION_ID, XA.SCM_SITE_ID) AS SCM_SITE_DESCRIPTION' || CHR(10)
              || '             , FN_GET_ITEM_PROD_OP(XA.DIVISION_ID, XA.OPERATION_GROUP, XA.ITEM_ID) AS MODEL_ID' || CHR(10)
              || '             , XA.ITEM_ID' || CHR(10)
              || '             , NVL(FN_GET_ITEM_NICKNAME(XA.DIVISION_ID, XA.ITEM_ID), ''-'') AS NICK_NAME' || CHR(10)
              || '             , FN_GET_SCP_ANL_BOH_QTY(XA.DIVISION_ID, XA.PLAN_START_YYYYMMDD, XA.PLAN_TYPE, TO_NUMBER(XA.PLAN_SEQ), XA.SCM_SITE_ID, XA.ITEM_ID, XA.FROM_YYYYMMDD) AS BOH' || CHR(10)
              || '             , XA.MEASURE' || CHR(10)
              || '             , XA.MEASURE_NAME' || CHR(10)
              || '             , XA.USER_SORT_ORDER_NO' || CHR(10)
              || '             , XA.PLAN_START_YYYYMMDD' || CHR(10)
              || '             , XA.PLAN_TYPE' || CHR(10)
              || '             , XA.PLAN_SEQ' || CHR(10)
              || '             , XA.FROM_YYYYMMDD' || CHR(10)
              || '             , XA.TO_YYYYMMDD' || CHR(10)
              || '             , XA.ORIGIN_DIVISION_ID' || CHR(10)
              || '             , XA.ELECTRODE_TYPE' || CHR(10)
              || V_QRY_SUM
              || '          FROM GT_0011_TTL_MAIN XA' || CHR(10)
              || '         WHERE XA.ORIGIN_DIVISION_ID NOT IN (SELECT COLUMN_VALUE FROM TABLE(FN_GET_DIVISION_DIV(''EE'')))' || CHR(10);   --div_commonization

        IF V_NICK_YN = 'Y' THEN
            V_SQL := V_SQL
                  || '           AND XA.ITEM_ID IN (SELECT XB.ITEM_ID FROM GT_0011_NICKITEM XB)' || CHR(10);
        END IF;

        V_SQL := V_SQL
              || '         GROUP BY XA.KEY_IDX, XA.DIVISION_ID, XA.OPERATION_GROUP, XA.SCM_SITE_ID, XA.ITEM_ID, XA.MEASURE, XA.MEASURE_NAME, XA.USER_SORT_ORDER_NO' || CHR(10)
              || '                , XA.PLAN_START_YYYYMMDD, XA.PLAN_TYPE, XA.PLAN_SEQ, XA.FROM_YYYYMMDD, XA.TO_YYYYMMDD, XA.ORIGIN_DIVISION_ID, XA.ELECTRODE_TYPE' || CHR(10)
              || '       ) IX' || CHR(10);

        IF V_MODEL_ALL = 'N' THEN
            V_SQL := V_SQL
                  || ' WHERE IX.MODEL_ID IN (SELECT COLUMN_VALUE FROM TABLE(:B_MODEL_TAB))' || CHR(10);
        END IF;

        V_SQL := V_SQL
              || ' ORDER BY IX.DIVISION_ID NULLS FIRST, IX.OPERATION_GROUP NULLS FIRST, IX.SCM_SITE_ID NULLS FIRST, IX.ITEM_ID NULLS FIRST, IX.USER_SORT_ORDER_NO NULLS FIRST';   /* AS-IS 오름차순은 NULL 이 앞 */

        -----------------------------------------------------------
        -- DEBUG QRY 출력
        -----------------------------------------------------------
        IF P_DEBUG_MODE = 'T' THEN
            P_PUT_CLOB(V_SQL);
        END IF;

        IF V_MODEL_ALL = 'N' THEN
            OPEN O_RC1 FOR V_SQL USING V_MODEL_TAB;
        ELSE
            OPEN O_RC1 FOR V_SQL;
        END IF;

    EXCEPTION
        WHEN OTHERS THEN
            O_RESULT_CODE := 'F';
            O_RESULT_MSG  := '[' || TO_CHAR(SQLCODE) || ']' || SQLERRM;

            P_LOG_ERROR('SCP0011_GET_PRODUCTION_PLAN_MODEL_TITLE_PARAL'
                      , 'P_DIVISION_ID=' || P_DIVISION_ID
                     || ', P_OPERATION_GROUP=' || P_OPERATION_GROUP
                     || ', P_SCM_SITE_ID=' || P_SCM_SITE_ID
                     || ', P_MODEL_ID=' || P_MODEL_ID
                     || ', P_ITEM_ID=' || P_ITEM_ID
                     || ', P_FROM_YYYYMMDD=' || P_FROM_YYYYMMDD
                     || ', P_TO_YYYYMMDD=' || P_TO_YYYYMMDD
                     || ', P_PLAN_START_YYYYMMDD=' || P_PLAN_START_YYYYMMDD
                     || ', P_PLAN_TYPE=' || P_PLAN_TYPE
                     || ', P_SEQ=' || P_SEQ
                     || ', P_USER_ID=' || P_USER_ID
                     || ', P_BUCKET=' || P_BUCKET
                     || ', P_CHK_ALL=' || P_CHK_ALL
                      , SQLCODE
                      , SQLERRM
                      , DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);

    END P_SCP0011_GET_PROD_MODEL_TITLE;


    /*==================================================================================================
     * Program ID   : SCP0011_GET_PRODUCTION_PLAN_LINE
     * Description  : Production Plan Line Header 조회
     * Program History
     *===================================================================================================
     *   Date       In Charge      Description
     *===================================================================================================
     * 2018/01/22   byunghunjung   Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
     * 2018/02/13   PJS   성능개선  PIVOT제거, CASE SUM방식으로 변경
     * 2018/04/17   PJS   임시테이블 삭제 OBJECT_ID형식으로 변경
     * 2018/05/28   byunghunjung 실적 테이블 값 조회시 scp_operation_group 조회조건 추가
     * 2018/05/29   PJS 주Sum 집계방식 변경
     * 2018/07/11   byunghunjung EE 사업부 실적 추가
     * 2018/07/18   YHW				전극용 조회항목 추가
     * 2021.10.25   khj79			[PJ20209643] LGES Digital SCM Level.3 달성을 위한 개선 (Phase.3) - 이력 테이블 분리(SCP_ANL_PRODUCTION_PLAN / HIST_SCP_ANL_PRODUCTION_PLAN)
     * 2022.05.13   LSC             PJ20216891 Digital SCM 3 Level 가속화를 위한 개선 : GM JV 추가
     * 2023/01/02   LWY             PJ20216994 / LGES Digital SCM 3 Level 가속화를 위한 개선 Phase 2 - 조회기준 변경(main / hist) - 당주,전주(main) / 당주,전주 이전(hist)
     * 2023/04/10   LWY				PJ20230691R  LGES SCM 역량 강화 위한 SCP 개선과제 이행 - DIVISION_ID 공통화 작업(div_commonization)
     * 2023.07.26   vadabi3		   PJ20230691R  LGES SCM 역량 강화 위한 SCP 개선과제 이행 - Model, Material 개선
     * 2026.09.17                  [MSSQL -> Oracle 전환] 시트 이름 · 사용자 ID 대소문자 무시 비교(AS-IS 정렬규칙 CI 대응)
     *==================================================================================================*/
    PROCEDURE P_SCP0011_GET_PROD_PLAN_LINE
    (
        P_DIVISION_ID           IN  VARCHAR2,
        P_OPERATION_GROUP       IN  VARCHAR2,
        P_SCM_SITE_ID           IN  VARCHAR2,
        P_ITEM_ID               IN  VARCHAR2,
        P_FROM_YYYYMMDD         IN  VARCHAR2,
        P_TO_YYYYMMDD           IN  VARCHAR2,
        P_PLAN_START_YYYYMMDD   IN  VARCHAR2,
        P_PLAN_TYPE             IN  VARCHAR2,
        P_SEQ                   IN  VARCHAR2,
        P_PROGRAM_ID            IN  VARCHAR2 DEFAULT 'SCP0011',
        P_SHEET_NAME            IN  VARCHAR2 DEFAULT 'LINE',
        P_USER_ID               IN  VARCHAR2,
        P_ELECTRODE_TYPE        IN  VARCHAR2 DEFAULT NULL,
        P_DEBUG_MODE            IN  VARCHAR2 DEFAULT 'F',
        O_RC1                   OUT SYS_REFCURSOR,
        O_RESULT_CODE           OUT VARCHAR2,
        O_RESULT_MSG            OUT VARCHAR2
    )
    IS
        V_DIVISION_ID           VARCHAR2(50 CHAR)  := UPPER(P_DIVISION_ID);
        V_OPERATION_GROUP       VARCHAR2(50 CHAR)  := UPPER(P_OPERATION_GROUP);
        V_SCM_SITE_ID           VARCHAR2(150 CHAR) := UPPER(P_SCM_SITE_ID);
        V_ITEM_ID               VARCHAR2(300 CHAR) := UPPER(P_ITEM_ID);
        V_PLAN_TYPE             VARCHAR2(50 CHAR)  := UPPER(P_PLAN_TYPE);
        V_PROGRAM_ID            VARCHAR2(300 CHAR) := UPPER(P_PROGRAM_ID);
        V_SHEET_NAME            VARCHAR2(150 CHAR) := UPPER(P_SHEET_NAME);
        V_USER_ID               VARCHAR2(150 CHAR) := UPPER(P_USER_ID);
        V_SEQ                   NUMBER;
        V_PLAN_START_DATE       DATE;

        V_CNT_USR_MEASURE       NUMBER := 0;
        V_MIN_YYYYMMDD          VARCHAR2(8 CHAR);
        V_FROM_YYYYMMDD         VARCHAR2(8 CHAR);
        V_TO_YYYYMMDD           VARCHAR2(8 CHAR);
        V_FROM_RESULT           VARCHAR2(8 CHAR);
        V_TO_RESULT             VARCHAR2(8 CHAR);
        V_FROM_RESULT_DATE      DATE;
        V_TO_RESULT_DATE        DATE;
        V_FROM_CMP              VARCHAR2(8 CHAR);   /* 빈 문자 비교값 */
        V_TO_CMP                VARCHAR2(8 CHAR);

        V_SITE_TAB              T_STR_TAB;
        V_SITE_ALL              VARCHAR2(1 CHAR);
        V_ITEM_TAB              T_STR_TAB;
        V_ITEM_ALL              VARCHAR2(1 CHAR);
        V_ELEC_TAB              T_STR_TAB;
        V_ELEC_ALL              VARCHAR2(1 CHAR);

        V_QRY_SUM               CLOB;
        V_SQL                   CLOB;
    BEGIN

        O_RESULT_CODE := 'S';
        O_RESULT_MSG  := NULL;

        V_SEQ             := TO_NUMBER(P_SEQ);
        SELECT TO_DATE(P_PLAN_START_YYYYMMDD DEFAULT NULL ON CONVERSION ERROR, 'YYYYMMDD')
          INTO V_PLAN_START_DATE
          FROM DUAL;

        SELECT COUNT(*)
          INTO V_CNT_USR_MEASURE
          FROM SCM_MST_TITLESET_USER
         WHERE PROGRAM_ID         = V_PROGRAM_ID
           AND UPPER(SHEET_NAME)  = V_SHEET_NAME
           AND UPPER(USER_ID)     = V_USER_ID;

        P_SET_PERIOD(P_PLAN_START_YYYYMMDD, P_FROM_YYYYMMDD, P_TO_YYYYMMDD
                   , V_FROM_YYYYMMDD, V_TO_YYYYMMDD, V_FROM_RESULT, V_TO_RESULT);

        V_FROM_RESULT_DATE := F_STR_DATE(V_FROM_RESULT);
        V_TO_RESULT_DATE   := F_STR_DATE(V_TO_RESULT);
        V_FROM_CMP         := F_CMP(V_FROM_YYYYMMDD);
        V_TO_CMP           := F_CMP(V_TO_YYYYMMDD);

        IF P_DEBUG_MODE = 'T' THEN
            DBMS_OUTPUT.PUT_LINE('----------------------------------');
            DBMS_OUTPUT.PUT_LINE('v_from_yyyymmdd =' || V_FROM_YYYYMMDD);
            DBMS_OUTPUT.PUT_LINE('v_to_yyyymmdd =' || V_TO_YYYYMMDD);
            DBMS_OUTPUT.PUT_LINE('v_from_result =' || V_FROM_RESULT);
            DBMS_OUTPUT.PUT_LINE('v_to_result =' || V_TO_RESULT);
            DBMS_OUTPUT.PUT_LINE('----------------------------------');
            DBMS_OUTPUT.PUT_LINE('');
        END IF;

        /* 생산실적 조회 조건은 쉼표 목록, 계획 조회 조건은 단일 값이다 (AS-IS 원문 그대로) */
        P_SPLIT_LIST(P_SCM_SITE_ID   , 'Y', V_SITE_TAB, V_SITE_ALL);
        P_SPLIT_LIST(P_ITEM_ID       , 'Y', V_ITEM_TAB, V_ITEM_ALL);
        P_SPLIT_LIST(P_ELECTRODE_TYPE, 'Y', V_ELEC_TAB, V_ELEC_ALL);

        -- 2023.01.02
        V_MIN_YYYYMMDD := F_PREV_MONDAY;     -- previous monday

        /********************************************************************************
        * 임시테이블 초기화
        ********************************************************************************/
        DELETE FROM GT_0011_LINE;

        /********************************************************************************
        * 데이타조회, 임시테이블에 저장
        ********************************************************************************/
        -- 2021.10.25 : 이력 테이블 분리
        IF F_CMP(P_PLAN_START_YYYYMMDD) >= V_MIN_YYYYMMDD THEN

            INSERT INTO GT_0011_LINE
                 (
                   DIVISION_ID
                  ,OPERATION_GROUP
                  ,SCM_SITE_ID
                  ,LINE_ID
                  ,ITEM_ID
                  ,MEASURE
                  ,MEASURE_NAME
                  ,USER_SORT_ORDER_NO
                  ,OPERATION_ID
                  ,PLAN_TYPE
                  ,PLAN_SEQ
                  ,FROM_YYYYMMDD
                  ,PLAN_START_YYYYMMDD
                  ,YYYYMMDD
                  ,YYYYMM
                  ,ISO_WEEK
                  ,QTY
                  ,ORIGIN_DIVISION_ID
                  ,ELECTRODE_TYPE
                 )
            SELECT IA.DIVISION_ID
                 , IA.OPERATION_GROUP
                 , IA.SCM_SITE_ID
                 , IA.LINE_ID
                 , IA.ITEM_ID
                 , IA.MEASURE
                 , IA.MEASURE_NAME
                 , IA.USER_SORT_ORDER_NO
                 , IA.OPERATION_ID
                 , P_PLAN_TYPE                                      AS PLAN_TYPE
                 , P_SEQ                                            AS PLAN_SEQ
                 , P_FROM_YYYYMMDD                                  AS FROM_YYYYMMDD
                 , P_PLAN_START_YYYYMMDD                            AS PLAN_START_YYYYMMDD
                 , 'D_' || IA.YYYYMMDD                              AS YYYYMMDD
                 , C.BASIS_YYYYMM                                   AS YYYYMM
                 , SUBSTR(C.BASIS_YYYYMM, -4) || C.ISO_WEEK         AS ISO_WEEK
                 , IB.QTY
                 , IA.ORIGIN_DIVISION_ID
                 , IA.ELECTRODE_TYPE
              FROM (SELECT XC.DIVISION_ID
                         , XC.PLAN_START_YYYYMMDD
                         , XC.PLAN_TYPE
                         , XC.SEQ
                         , XC.OPERATION_GROUP
                         , XC.SCM_SITE_ID
                         , XC.ITEM_ID
                         , XC.LINE_ID
                         , XC.OPERATION_ID
                         , XA.COLUMN_NAME                           AS MEASURE
                         , XA.COLUMN_LABEL_NAME                     AS MEASURE_NAME
                         , NVL(XB.SORT_ORDER_NO, XA.SORT_ORDER_NO)  AS USER_SORT_ORDER_NO
                         , XC.YYYYMMDD
                         , XC.ORIGIN_DIVISION_ID
                         , XC.ELECTRODE_TYPE
                      FROM SCM_MST_SHEET_MEASURE    XA
                         , SCM_MST_TITLESET_USER    XB
                         , (SELECT SA.DIVISION_ID
                                 , SA.PLAN_START_YYYYMMDD
                                 , SA.PLAN_TYPE
                                 , SA.SEQ
                                 , SA.OPERATION_GROUP
                                 , SA.SCM_SITE_ID
                                 , SA.ITEM_ID
                                 , SA.OPERATION_ID
                                 , SA.LINE_ID
                                 , SA.MEASURE
                                 , SA.YYYYMMDD
                                 , NVL(SA.ORIGIN_DIVISION_ID, '-')  AS ORIGIN_DIVISION_ID
                                 , NVL(SA.ELECTRODE_TYPE, '-')      AS ELECTRODE_TYPE
                              FROM SCP_ANL_PRODUCTION_PLAN SA
                             WHERE SA.YYYYMMDD                >= P_FROM_YYYYMMDD
                               AND SA.YYYYMMDD                <= P_TO_YYYYMMDD
                               AND SA.DIVISION_ID              = V_DIVISION_ID
                               AND SA.OPERATION_GROUP          = V_OPERATION_GROUP
                               AND SA.SCM_SITE_ID              = V_SCM_SITE_ID
                               AND SA.ITEM_ID                  = V_ITEM_ID
                               AND SA.PLAN_START_YYYYMMDD      = P_PLAN_START_YYYYMMDD
                               AND SA.PLAN_START_YYYYMMDD_DATE = V_PLAN_START_DATE     /* 파티션 프루닝 */
                               AND SA.PLAN_TYPE                = V_PLAN_TYPE
                               AND SA.SEQ                      = V_SEQ
                               AND (V_ELEC_ALL = 'Y' OR NVL(SA.ELECTRODE_TYPE, '-') IN (SELECT COLUMN_VALUE FROM TABLE(V_ELEC_TAB)))
                             GROUP BY SA.DIVISION_ID
                                    , SA.PLAN_START_YYYYMMDD
                                    , SA.PLAN_TYPE
                                    , SA.SEQ
                                    , SA.OPERATION_GROUP
                                    , SA.SCM_SITE_ID
                                    , SA.ITEM_ID
                                    , SA.LINE_ID
                                    , SA.OPERATION_ID
                                    , SA.MEASURE
                                    , SA.YYYYMMDD
                                    , SA.ORIGIN_DIVISION_ID
                                    , SA.ELECTRODE_TYPE
                             UNION ALL
                            -- 생산실적
                            -- Plan 테이블에는 실적 보고자 하는 YYYYMMDD가 없으므로 생성을 위해 추가
                            SELECT V_DIVISION_ID                    AS DIVISION_ID     -- div_commonization
                                 , P_PLAN_START_YYYYMMDD            AS PLAN_START_YYYYMMDD
                                 , P_PLAN_TYPE                      AS PLAN_TYPE
                                 , V_SEQ                            AS SEQ
                                 , SB.SCP_OPERATION_GROUP           AS OPERATION_GROUP
                                 , SB.SCM_SITE_ID
                                 , SB.ITEM_ID
                                 , SB.OPERATION_ID
                                 , SB.LINE_ID
                                 , 'PROD_PLAN_ENGINE'               AS MEASURE
                                 , TO_CHAR(SB.PLAN_DATE, 'YYYYMMDD') AS YYYYMMDD
                                 , SB.DIVISION_ID                   AS ORIGIN_DIVISION_ID
                                 , NVL(SB.ELECTRODE_TYPE, '-')      AS ELECTRODE_TYPE
                              FROM SCM_DNM_PRODUCT_RESULT_V SB
                             WHERE SB.DIVISION_ID IN (SELECT SC.DIVISION_ID      --div_commonization
                                                        FROM SCM_MST_DIVISION SC
                                                       WHERE SC.ATTRIBUTE4 IN (SELECT SD.ATTRIBUTE4
                                                                                 FROM SCM_MST_DIVISION SD
                                                                                WHERE SD.DIVISION_ID = V_DIVISION_ID
                                                                                  AND SD.ATTRIBUTE3  = 'EE')
                                                         AND SC.ATTRIBUTE3 <> 'EE'
                                                       UNION ALL
                                                      SELECT V_DIVISION_ID
                                                        FROM DUAL)
                               AND SB.PLAN_DATE           >= V_FROM_RESULT_DATE
                               AND SB.PLAN_DATE           <  V_TO_RESULT_DATE      -- equal 표시 주의할것
                               AND SB.SCP_OPERATION_GROUP  = V_OPERATION_GROUP
                               AND (V_SITE_ALL = 'Y' OR SB.SCM_SITE_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_SITE_TAB)))
                               AND (V_ITEM_ALL = 'Y' OR SB.ITEM_ID     IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)))
                               AND (V_ELEC_ALL = 'Y' OR NVL(SB.ELECTRODE_TYPE, '-') IN (SELECT COLUMN_VALUE FROM TABLE(V_ELEC_TAB)))
                             GROUP BY SB.DIVISION_ID
                                    , SB.SCP_OPERATION_GROUP
                                    , SB.SCM_SITE_ID
                                    , SB.ITEM_ID
                                    , SB.LINE_ID
                                    , SB.OPERATION_ID
                                    , SB.PLAN_DATE
                                    , SB.ELECTRODE_TYPE) XC
                     WHERE XA.PROGRAM_ID          = XB.PROGRAM_ID(+)
                       AND UPPER(XA.SHEET_NAME)   = UPPER(XB.SHEET_NAME(+))
                       AND UPPER(XA.COLUMN_NAME)  = UPPER(XB.COLUMN_NAME(+))
                       AND UPPER(XB.USER_ID(+))   = V_USER_ID
                       AND (   V_CNT_USR_MEASURE = 0
                            OR EXISTS (SELECT 1
                                         FROM SCM_MST_TITLESET_USER SE
                                        WHERE SE.PROGRAM_ID         = V_PROGRAM_ID
                                          AND UPPER(SE.SHEET_NAME)  = V_SHEET_NAME
                                          AND UPPER(SE.USER_ID)     = V_USER_ID
                                          AND UPPER(SE.COLUMN_NAME) = UPPER(XA.COLUMN_NAME)))
                       AND XA.PROGRAM_ID          = V_PROGRAM_ID
                       AND UPPER(XA.SHEET_NAME)   = V_SHEET_NAME
                       AND XA.VALID_YN            = 'Y'
                     GROUP BY XC.DIVISION_ID
                            , XC.PLAN_START_YYYYMMDD
                            , XC.PLAN_TYPE
                            , XC.SEQ
                            , XC.OPERATION_GROUP
                            , XC.SCM_SITE_ID
                            , XC.ITEM_ID
                            , XC.LINE_ID
                            , XC.OPERATION_ID
                            , XA.COLUMN_NAME
                            , XA.COLUMN_LABEL_NAME
                            , XC.YYYYMMDD
                            , NVL(XB.SORT_ORDER_NO, XA.SORT_ORDER_NO)
                            , XC.ORIGIN_DIVISION_ID
                            , XC.ELECTRODE_TYPE) IA
                 , (  -- 계획
                    SELECT XD.DIVISION_ID
                         , XD.OPERATION_GROUP
                         , XD.SCM_SITE_ID
                         , XD.ITEM_ID
                         , XD.OPERATION_ID
                         , XD.LINE_ID
                         , XD.MEASURE
                         , XD.YYYYMMDD
                         , XD.QTY
                         , NVL(XD.ORIGIN_DIVISION_ID, '-')          AS ORIGIN_DIVISION_ID
                         , NVL(XD.ELECTRODE_TYPE, '-')              AS ELECTRODE_TYPE
                      FROM SCP_ANL_PRODUCTION_PLAN XD
                     WHERE XD.YYYYMMDD                >= V_FROM_CMP
                       AND XD.YYYYMMDD                <= V_TO_CMP
                       AND XD.DIVISION_ID              = V_DIVISION_ID
                       AND XD.OPERATION_GROUP          = V_OPERATION_GROUP
                       AND XD.SCM_SITE_ID              = V_SCM_SITE_ID
                       AND XD.ITEM_ID                  = V_ITEM_ID
                       AND XD.PLAN_START_YYYYMMDD      = P_PLAN_START_YYYYMMDD
                       AND XD.PLAN_START_YYYYMMDD_DATE = V_PLAN_START_DATE     /* 파티션 프루닝 */
                       AND XD.PLAN_TYPE                = V_PLAN_TYPE
                       AND XD.SEQ                      = V_SEQ
                       AND (V_ELEC_ALL = 'Y' OR NVL(XD.ELECTRODE_TYPE, '-') IN (SELECT COLUMN_VALUE FROM TABLE(V_ELEC_TAB)))
                     UNION ALL
                    -- 생산실적
                    SELECT V_DIVISION_ID                            AS DIVISION_ID     --div_commonization
                         , XE.SCP_OPERATION_GROUP                   AS OPERATION_GROUP
                         , XE.SCM_SITE_ID
                         , XE.ITEM_ID
                         , XE.OPERATION_ID
                         , XE.LINE_ID
                         , 'PROD_PLAN_ENGINE'                       AS MEASURE
                         , TO_CHAR(XE.PLAN_DATE, 'YYYYMMDD')        AS YYYYMMDD
                         , XE.ACTUAL_GOOD_QTY                       AS QTY
                         , XE.DIVISION_ID                           AS ORIGIN_DIVISION_ID
                         , NVL(XE.ELECTRODE_TYPE, '-')              AS ELECTRODE_TYPE
                      FROM SCM_DNM_PRODUCT_RESULT_V XE
                     WHERE XE.DIVISION_ID IN (SELECT SF.DIVISION_ID      --div_commonization
                                                FROM SCM_MST_DIVISION SF
                                               WHERE SF.ATTRIBUTE4 IN (SELECT SG.ATTRIBUTE4
                                                                         FROM SCM_MST_DIVISION SG
                                                                        WHERE SG.DIVISION_ID = V_DIVISION_ID
                                                                          AND SG.ATTRIBUTE3  = 'EE')
                                                 AND SF.ATTRIBUTE3 <> 'EE'
                                               UNION ALL
                                              SELECT V_DIVISION_ID
                                                FROM DUAL)
                       AND XE.PLAN_DATE           >= V_FROM_RESULT_DATE
                       AND XE.PLAN_DATE           <  V_TO_RESULT_DATE      -- equal 표시 주의할것
                       AND XE.SCP_OPERATION_GROUP  = V_OPERATION_GROUP
                       AND XE.SCM_SITE_ID          = V_SCM_SITE_ID
                       AND XE.ITEM_ID              = V_ITEM_ID
                       AND (V_ELEC_ALL = 'Y' OR NVL(XE.ELECTRODE_TYPE, '-') IN (SELECT COLUMN_VALUE FROM TABLE(V_ELEC_TAB)))) IB
                 , SCM_SYS_CALENDAR_M C
             WHERE IA.DIVISION_ID        = IB.DIVISION_ID(+)
               AND IA.OPERATION_GROUP    = IB.OPERATION_GROUP(+)
               AND IA.SCM_SITE_ID        = IB.SCM_SITE_ID(+)
               AND IA.ITEM_ID            = IB.ITEM_ID(+)
               AND IA.OPERATION_ID       = IB.OPERATION_ID(+)
               AND IA.LINE_ID            = IB.LINE_ID(+)
               AND IA.MEASURE            = IB.MEASURE(+)
               AND IA.YYYYMMDD           = IB.YYYYMMDD(+)
               AND IA.ORIGIN_DIVISION_ID = IB.ORIGIN_DIVISION_ID(+)
               AND IA.ELECTRODE_TYPE     = IB.ELECTRODE_TYPE(+)
               AND IA.YYYYMMDD           = C.BASIS_YYYYMMDD
                -- 조회조건 추가부분 (Model Tab에서만 사용하는 REQUIREMENT , FORMATION_YIELD Measure는 *로 입력되어 Line조회시 제외함)
               AND IA.LINE_ID           IS NOT NULL
               AND IA.LINE_ID           <> '*';

        ELSIF F_CMP(P_PLAN_START_YYYYMMDD) < V_MIN_YYYYMMDD THEN

            INSERT INTO GT_0011_LINE
                 (
                   DIVISION_ID
                  ,OPERATION_GROUP
                  ,SCM_SITE_ID
                  ,LINE_ID
                  ,ITEM_ID
                  ,MEASURE
                  ,MEASURE_NAME
                  ,USER_SORT_ORDER_NO
                  ,OPERATION_ID
                  ,PLAN_TYPE
                  ,PLAN_SEQ
                  ,FROM_YYYYMMDD
                  ,PLAN_START_YYYYMMDD
                  ,YYYYMMDD
                  ,YYYYMM
                  ,ISO_WEEK
                  ,QTY
                  ,ORIGIN_DIVISION_ID
                  ,ELECTRODE_TYPE
                 )
            SELECT IA.DIVISION_ID
                 , IA.OPERATION_GROUP
                 , IA.SCM_SITE_ID
                 , IA.LINE_ID
                 , IA.ITEM_ID
                 , IA.MEASURE
                 , IA.MEASURE_NAME
                 , IA.USER_SORT_ORDER_NO
                 , IA.OPERATION_ID
                 , P_PLAN_TYPE                                      AS PLAN_TYPE
                 , P_SEQ                                            AS PLAN_SEQ
                 , P_FROM_YYYYMMDD                                  AS FROM_YYYYMMDD
                 , P_PLAN_START_YYYYMMDD                            AS PLAN_START_YYYYMMDD
                 , 'D_' || IA.YYYYMMDD                              AS YYYYMMDD
                 , C.BASIS_YYYYMM                                   AS YYYYMM
                 , SUBSTR(C.BASIS_YYYYMM, -4) || C.ISO_WEEK         AS ISO_WEEK
                 , IB.QTY
                 , IA.ORIGIN_DIVISION_ID
                 , IA.ELECTRODE_TYPE
              FROM (SELECT XC.DIVISION_ID
                         , XC.PLAN_START_YYYYMMDD
                         , XC.PLAN_TYPE
                         , XC.SEQ
                         , XC.OPERATION_GROUP
                         , XC.SCM_SITE_ID
                         , XC.ITEM_ID
                         , XC.LINE_ID
                         , XC.OPERATION_ID
                         , XA.COLUMN_NAME                           AS MEASURE
                         , XA.COLUMN_LABEL_NAME                     AS MEASURE_NAME
                         , NVL(XB.SORT_ORDER_NO, XA.SORT_ORDER_NO)  AS USER_SORT_ORDER_NO
                         , XC.YYYYMMDD
                         , XC.ORIGIN_DIVISION_ID
                         , XC.ELECTRODE_TYPE
                      FROM SCM_MST_SHEET_MEASURE    XA
                         , SCM_MST_TITLESET_USER    XB
                         , (SELECT SA.DIVISION_ID
                                 , SA.PLAN_START_YYYYMMDD
                                 , SA.PLAN_TYPE
                                 , SA.SEQ
                                 , SA.OPERATION_GROUP
                                 , SA.SCM_SITE_ID
                                 , SA.ITEM_ID
                                 , SA.OPERATION_ID
                                 , SA.LINE_ID
                                 , SA.MEASURE
                                 , SA.YYYYMMDD
                                 , NVL(SA.ORIGIN_DIVISION_ID, '-')  AS ORIGIN_DIVISION_ID
                                 , NVL(SA.ELECTRODE_TYPE, '-')      AS ELECTRODE_TYPE
                              FROM HIST_SCP_ANL_PRODUCTION_PLAN SA
                             WHERE SA.YYYYMMDD                >= P_FROM_YYYYMMDD
                               AND SA.YYYYMMDD                <= P_TO_YYYYMMDD
                               AND SA.DIVISION_ID              = V_DIVISION_ID
                               AND SA.OPERATION_GROUP          = V_OPERATION_GROUP
                               AND SA.SCM_SITE_ID              = V_SCM_SITE_ID
                               AND SA.ITEM_ID                  = V_ITEM_ID
                               AND SA.PLAN_START_YYYYMMDD      = P_PLAN_START_YYYYMMDD
                               AND SA.PLAN_START_YYYYMMDD_DATE = V_PLAN_START_DATE     /* 파티션 프루닝 */
                               AND SA.PLAN_TYPE                = V_PLAN_TYPE
                               AND SA.SEQ                      = V_SEQ
                               AND (V_ELEC_ALL = 'Y' OR NVL(SA.ELECTRODE_TYPE, '-') IN (SELECT COLUMN_VALUE FROM TABLE(V_ELEC_TAB)))
                             GROUP BY SA.DIVISION_ID
                                    , SA.PLAN_START_YYYYMMDD
                                    , SA.PLAN_TYPE
                                    , SA.SEQ
                                    , SA.OPERATION_GROUP
                                    , SA.SCM_SITE_ID
                                    , SA.ITEM_ID
                                    , SA.LINE_ID
                                    , SA.OPERATION_ID
                                    , SA.MEASURE
                                    , SA.YYYYMMDD
                                    , SA.ORIGIN_DIVISION_ID
                                    , SA.ELECTRODE_TYPE
                             UNION ALL
                            -- 생산실적
                            -- Plan 테이블에는 실적 보고자 하는 YYYYMMDD가 없으므로 생성을 위해 추가
                            SELECT V_DIVISION_ID                    AS DIVISION_ID     --div_commonization
                                 , P_PLAN_START_YYYYMMDD            AS PLAN_START_YYYYMMDD
                                 , P_PLAN_TYPE                      AS PLAN_TYPE
                                 , V_SEQ                            AS SEQ
                                 , SB.SCP_OPERATION_GROUP           AS OPERATION_GROUP
                                 , SB.SCM_SITE_ID
                                 , SB.ITEM_ID
                                 , SB.OPERATION_ID
                                 , SB.LINE_ID
                                 , 'PROD_PLAN_ENGINE'               AS MEASURE
                                 , TO_CHAR(SB.PLAN_DATE, 'YYYYMMDD') AS YYYYMMDD
                                 , SB.DIVISION_ID                   AS ORIGIN_DIVISION_ID
                                 , NVL(SB.ELECTRODE_TYPE, '-')      AS ELECTRODE_TYPE
                              FROM SCM_DNM_PRODUCT_RESULT_V SB
                             WHERE SB.DIVISION_ID IN (SELECT SC.DIVISION_ID      --div_commonization
                                                        FROM SCM_MST_DIVISION SC
                                                       WHERE SC.ATTRIBUTE4 IN (SELECT SD.ATTRIBUTE4
                                                                                 FROM SCM_MST_DIVISION SD
                                                                                WHERE SD.DIVISION_ID = V_DIVISION_ID
                                                                                  AND SD.ATTRIBUTE3  = 'EE')
                                                         AND SC.ATTRIBUTE3 <> 'EE'
                                                       UNION ALL
                                                      SELECT V_DIVISION_ID
                                                        FROM DUAL)
                               AND SB.PLAN_DATE           >= V_FROM_RESULT_DATE
                               AND SB.PLAN_DATE           <  V_TO_RESULT_DATE      -- equal 표시 주의할것
                               AND SB.SCP_OPERATION_GROUP  = V_OPERATION_GROUP
                               AND (V_SITE_ALL = 'Y' OR SB.SCM_SITE_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_SITE_TAB)))
                               AND (V_ITEM_ALL = 'Y' OR SB.ITEM_ID     IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)))
                               AND (V_ELEC_ALL = 'Y' OR NVL(SB.ELECTRODE_TYPE, '-') IN (SELECT COLUMN_VALUE FROM TABLE(V_ELEC_TAB)))
                             GROUP BY SB.DIVISION_ID
                                    , SB.SCP_OPERATION_GROUP
                                    , SB.SCM_SITE_ID
                                    , SB.ITEM_ID
                                    , SB.LINE_ID
                                    , SB.OPERATION_ID
                                    , SB.PLAN_DATE
                                    , SB.ELECTRODE_TYPE) XC
                     WHERE XA.PROGRAM_ID          = XB.PROGRAM_ID(+)
                       AND UPPER(XA.SHEET_NAME)   = UPPER(XB.SHEET_NAME(+))
                       AND UPPER(XA.COLUMN_NAME)  = UPPER(XB.COLUMN_NAME(+))
                       AND UPPER(XB.USER_ID(+))   = V_USER_ID
                       AND (   V_CNT_USR_MEASURE = 0
                            OR EXISTS (SELECT 1
                                         FROM SCM_MST_TITLESET_USER SE
                                        WHERE SE.PROGRAM_ID         = V_PROGRAM_ID
                                          AND UPPER(SE.SHEET_NAME)  = V_SHEET_NAME
                                          AND UPPER(SE.USER_ID)     = V_USER_ID
                                          AND UPPER(SE.COLUMN_NAME) = UPPER(XA.COLUMN_NAME)))
                       AND XA.PROGRAM_ID          = V_PROGRAM_ID
                       AND UPPER(XA.SHEET_NAME)   = V_SHEET_NAME
                       AND XA.VALID_YN            = 'Y'
                     GROUP BY XC.DIVISION_ID
                            , XC.PLAN_START_YYYYMMDD
                            , XC.PLAN_TYPE
                            , XC.SEQ
                            , XC.OPERATION_GROUP
                            , XC.SCM_SITE_ID
                            , XC.ITEM_ID
                            , XC.LINE_ID
                            , XC.OPERATION_ID
                            , XA.COLUMN_NAME
                            , XA.COLUMN_LABEL_NAME
                            , XC.YYYYMMDD
                            , NVL(XB.SORT_ORDER_NO, XA.SORT_ORDER_NO)
                            , XC.ORIGIN_DIVISION_ID
                            , XC.ELECTRODE_TYPE) IA
                 , (  -- 계획
                    SELECT XD.DIVISION_ID
                         , XD.OPERATION_GROUP
                         , XD.SCM_SITE_ID
                         , XD.ITEM_ID
                         , XD.OPERATION_ID
                         , XD.LINE_ID
                         , XD.MEASURE
                         , XD.YYYYMMDD
                         , XD.QTY
                         , NVL(XD.ORIGIN_DIVISION_ID, '-')          AS ORIGIN_DIVISION_ID
                         , NVL(XD.ELECTRODE_TYPE, '-')              AS ELECTRODE_TYPE
                      FROM HIST_SCP_ANL_PRODUCTION_PLAN XD
                     WHERE XD.YYYYMMDD                >= V_FROM_CMP
                       AND XD.YYYYMMDD                <= V_TO_CMP
                       AND XD.DIVISION_ID              = V_DIVISION_ID
                       AND XD.OPERATION_GROUP          = V_OPERATION_GROUP
                       AND XD.SCM_SITE_ID              = V_SCM_SITE_ID
                       AND XD.ITEM_ID                  = V_ITEM_ID
                       AND XD.PLAN_START_YYYYMMDD      = P_PLAN_START_YYYYMMDD
                       AND XD.PLAN_START_YYYYMMDD_DATE = V_PLAN_START_DATE     /* 파티션 프루닝 */
                       AND XD.PLAN_TYPE                = V_PLAN_TYPE
                       AND XD.SEQ                      = V_SEQ
                       AND (V_ELEC_ALL = 'Y' OR NVL(XD.ELECTRODE_TYPE, '-') IN (SELECT COLUMN_VALUE FROM TABLE(V_ELEC_TAB)))
                     UNION ALL
                    -- 생산실적
                    SELECT V_DIVISION_ID                            AS DIVISION_ID     --div_commonization
                         , XE.SCP_OPERATION_GROUP                   AS OPERATION_GROUP
                         , XE.SCM_SITE_ID
                         , XE.ITEM_ID
                         , XE.OPERATION_ID
                         , XE.LINE_ID
                         , 'PROD_PLAN_ENGINE'                       AS MEASURE
                         , TO_CHAR(XE.PLAN_DATE, 'YYYYMMDD')        AS YYYYMMDD
                         , XE.ACTUAL_GOOD_QTY                       AS QTY
                         , XE.DIVISION_ID                           AS ORIGIN_DIVISION_ID
                         , NVL(XE.ELECTRODE_TYPE, '-')              AS ELECTRODE_TYPE
                      FROM SCM_DNM_PRODUCT_RESULT_V XE
                     WHERE XE.DIVISION_ID IN (SELECT SF.DIVISION_ID      --div_commonization
                                                FROM SCM_MST_DIVISION SF
                                               WHERE SF.ATTRIBUTE4 IN (SELECT SG.ATTRIBUTE4
                                                                         FROM SCM_MST_DIVISION SG
                                                                        WHERE SG.DIVISION_ID = V_DIVISION_ID
                                                                          AND SG.ATTRIBUTE3  = 'EE')
                                                 AND SF.ATTRIBUTE3 <> 'EE'
                                               UNION ALL
                                              SELECT V_DIVISION_ID
                                                FROM DUAL)
                       AND XE.PLAN_DATE           >= V_FROM_RESULT_DATE
                       AND XE.PLAN_DATE           <  V_TO_RESULT_DATE      -- equal 표시 주의할것
                       AND XE.SCP_OPERATION_GROUP  = V_OPERATION_GROUP
                       AND XE.SCM_SITE_ID          = V_SCM_SITE_ID
                       AND XE.ITEM_ID              = V_ITEM_ID
                       AND (V_ELEC_ALL = 'Y' OR NVL(XE.ELECTRODE_TYPE, '-') IN (SELECT COLUMN_VALUE FROM TABLE(V_ELEC_TAB)))) IB
                 , SCM_SYS_CALENDAR_M C
             WHERE IA.DIVISION_ID        = IB.DIVISION_ID(+)
               AND IA.OPERATION_GROUP    = IB.OPERATION_GROUP(+)
               AND IA.SCM_SITE_ID        = IB.SCM_SITE_ID(+)
               AND IA.ITEM_ID            = IB.ITEM_ID(+)
               AND IA.OPERATION_ID       = IB.OPERATION_ID(+)
               AND IA.LINE_ID            = IB.LINE_ID(+)
               AND IA.MEASURE            = IB.MEASURE(+)
               AND IA.YYYYMMDD           = IB.YYYYMMDD(+)
               AND IA.ORIGIN_DIVISION_ID = IB.ORIGIN_DIVISION_ID(+)
               AND IA.ELECTRODE_TYPE     = IB.ELECTRODE_TYPE(+)
               AND IA.YYYYMMDD           = C.BASIS_YYYYMMDD
                -- 조회조건 추가부분 (Model Tab에서만 사용하는 REQUIREMENT , FORMATION_YIELD Measure는 *로 입력되어 Line조회시 제외함)
               AND IA.LINE_ID           IS NOT NULL
               AND IA.LINE_ID           <> '*';

        END IF;

        /********************************************************************************
        * PIVOIT처리
        ********************************************************************************/
        -- PIVOIT 대상 날짜문자열 생성
        V_QRY_SUM := NULL;

        FOR R IN (SELECT IA.COL_NAME
                    FROM (SELECT 'W_' || XA.BASIS_YYYYMM || XA.ISO_WEEK             AS COL_NAME
                               , XA.BASIS_START_DATE || '21'                        AS SORT_ORDER_NO
                            FROM SCM_SYS_CALENDAR_M XA
                           WHERE XA.BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                           GROUP BY XA.BASIS_YYYYMM
                                  , XA.ISO_WEEK
                                  , XA.BASIS_START_DATE
                           UNION ALL
                          SELECT 'M_' || XB.BASIS_YYYYMM                            AS COL_NAME
                               , MIN(XB.BASIS_START_DATE) || '01'                   AS SORT_ORDER_NO
                            FROM SCM_SYS_CALENDAR_M XB
                           WHERE XB.BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                           GROUP BY XB.BASIS_YYYYMM
                                  , XB.MONTH_NAME
                           UNION ALL
                          SELECT 'D_' || XC.BASIS_YYYYMMDD                          AS COL_NAME
                               , XC.BASIS_YYYYMMDD || '31'                          AS SORT_ORDER_NO
                            FROM SCM_SYS_CALENDAR_M XC
                           WHERE XC.BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                           GROUP BY XC.BASIS_YYYYMMDD) IA
                   ORDER BY IA.SORT_ORDER_NO)
        LOOP
            IF SUBSTR(R.COL_NAME, 1, 2) = 'M_' THEN
                V_QRY_SUM := V_QRY_SUM
                          || '     , SUM(CASE WHEN YYYYMM = ''' || SUBSTR(R.COL_NAME, -6) || ''' THEN QTY END) AS ' || R.COL_NAME || CHR(10);
            ELSIF SUBSTR(R.COL_NAME, 1, 2) = 'W_' THEN
                V_QRY_SUM := V_QRY_SUM
                          || '     , SUM(CASE WHEN ISO_WEEK = ''' || SUBSTR(R.COL_NAME, -6) || ''' THEN QTY END) AS ' || R.COL_NAME || CHR(10);
            ELSE
                V_QRY_SUM := V_QRY_SUM
                          || '     , SUM(CASE WHEN YYYYMMDD = ''' || R.COL_NAME || ''' THEN QTY END) AS ' || R.COL_NAME || CHR(10);
            END IF;
        END LOOP;

        V_SQL := 'SELECT DIVISION_ID' || CHR(10)
              || '     , FN_GET_DIVISION_NAME(DIVISION_ID) AS DIVISION_NAME' || CHR(10)
              || '     , OPERATION_GROUP' || CHR(10)
              || '     , FN_GET_LOOKUP_CODE_DESC(''OPERATION_GROUP'', OPERATION_GROUP) AS OPERATION_GROUP_NAME' || CHR(10)
              || '     , SCM_SITE_ID' || CHR(10)
              || '     , FN_GET_SCM_SITE_DESCRIPTION(DIVISION_ID, SCM_SITE_ID) AS SCM_SITE_DESCRIPTION' || CHR(10)
              || '     , LINE_ID' || CHR(10)
              || '     , FN_GET_ITEM_PROD_OP(DIVISION_ID, OPERATION_GROUP, ITEM_ID) AS MODEL_ID' || CHR(10)
              || '     , ITEM_ID' || CHR(10)
              || '     , NVL(FN_GET_ITEM_NICKNAME(DIVISION_ID, ITEM_ID), ''-'') AS NICK_NAME' || CHR(10)
              || '     , MEASURE' || CHR(10)
              || '     , MEASURE_NAME' || CHR(10)
              || '     , OPERATION_ID' || CHR(10)
              || '     , PLAN_TYPE' || CHR(10)
              || '     , PLAN_SEQ' || CHR(10)
              || '     , PLAN_START_YYYYMMDD' || CHR(10)
              || '     , FROM_YYYYMMDD' || CHR(10)
              || '     , USER_SORT_ORDER_NO' || CHR(10)
              || '     , ORIGIN_DIVISION_ID' || CHR(10)
              || '     , ELECTRODE_TYPE' || CHR(10)
              || V_QRY_SUM
              || '  FROM GT_0011_LINE' || CHR(10)
              || ' GROUP BY DIVISION_ID, OPERATION_GROUP, SCM_SITE_ID, LINE_ID, ITEM_ID, MEASURE, MEASURE_NAME, OPERATION_ID, PLAN_TYPE, PLAN_SEQ, PLAN_START_YYYYMMDD, FROM_YYYYMMDD, USER_SORT_ORDER_NO' || CHR(10)
              || '        , ORIGIN_DIVISION_ID, ELECTRODE_TYPE' || CHR(10)
              || ' ORDER BY DIVISION_ID NULLS FIRST, OPERATION_GROUP NULLS FIRST, SCM_SITE_ID NULLS FIRST, LINE_ID NULLS FIRST, ITEM_ID NULLS FIRST, USER_SORT_ORDER_NO NULLS FIRST';   /* AS-IS 오름차순은 NULL 이 앞 */

        -----------------------------------------------------------
        -- DEBUG QRY 출력
        -----------------------------------------------------------
        IF P_DEBUG_MODE = 'T' THEN
            P_PUT_CLOB(V_SQL);
        END IF;

        OPEN O_RC1 FOR V_SQL;

    EXCEPTION
        WHEN OTHERS THEN
            O_RESULT_CODE := 'F';
            O_RESULT_MSG  := '[' || TO_CHAR(SQLCODE) || ']' || SQLERRM;

            P_LOG_ERROR('SCP0011_GET_PRODUCTION_PLAN_LINE'
                      , 'P_DIVISION_ID=' || P_DIVISION_ID
                     || ', P_OPERATION_GROUP=' || P_OPERATION_GROUP
                     || ', P_SCM_SITE_ID=' || P_SCM_SITE_ID
                     || ', P_ITEM_ID=' || P_ITEM_ID
                     || ', P_FROM_YYYYMMDD=' || P_FROM_YYYYMMDD
                     || ', P_TO_YYYYMMDD=' || P_TO_YYYYMMDD
                     || ', P_PLAN_START_YYYYMMDD=' || P_PLAN_START_YYYYMMDD
                     || ', P_PLAN_TYPE=' || P_PLAN_TYPE
                     || ', P_SEQ=' || P_SEQ
                     || ', P_USER_ID=' || P_USER_ID
                     || ', P_ELECTRODE_TYPE=' || P_ELECTRODE_TYPE
                      , SQLCODE
                      , SQLERRM
                      , DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);

    END P_SCP0011_GET_PROD_PLAN_LINE;


    /*==================================================================================================
     * Program ID   : SCP0011_GET_PLAN_EDIT_INFO
     * Description  : PLAN 별 편집가능 여부 정보 조회
     * Program History
     *===================================================================================================
     *   Date       In Charge      Description
     *===================================================================================================
     * 2018/04/02   PJS    			Initial Release  전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
     * 2018/05/21   PJS             PR 수정모드 조건 변경
     * 2018/06/01   PJS             PLAN 시작일 가져오는 조건 변경
     * 2018/06/07   PJS             MA일 경우 FP운용기간-7일 처리
     * 2018/06/20   PJS             edit_start_date 계산 로직수정(offset -7반영)
     * 2018/07/18	YHW				전극데이터 편집가능여부 조건 수정(ORIGIN DIVISION 사용)
     * 2020/10/28   khj79           [C20201019-000175] , 자동차(81) 사업부의 경우 Final Plan 제외하고 전 구간 생산계획 수정 가능
     * 2021/10/13   khj79			[PJ20209643] LGES Digital SCM Level.3 달성을 위한 개선 (Phase.3) - 82(ESS) 'MA' 플랜 전 구간 수정 가능
     * 2023/05/03   LWY			    PJ20230691R  LGES SCM 역량 강화 위한 SCP 개선과제 이행 - 81 / SE : PROD_FROZEN 구간 EDIT 불가 적용.
     * 2026.09.17                   [MSSQL -> Oracle 전환] 사이트 비교 대소문자 무시(AS-IS 정렬규칙 CI 대응)
     *==================================================================================================*/
    PROCEDURE P_SCP0011_GET_PLAN_EDIT_INFO
    (
        P_DIVISION_ID           IN  VARCHAR2,
        P_SCM_SITE_ID           IN  VARCHAR2,
        P_PLAN_START_YYYYMMDD   IN  VARCHAR2,
        P_PLAN_TYPE             IN  VARCHAR2,
        P_SEQ                   IN  VARCHAR2,
        P_ORIGIN_DIVISION_ID    IN  VARCHAR2 DEFAULT NULL,
        P_DEBUG_MODE            IN  VARCHAR2 DEFAULT 'F',
        O_RC1                   OUT SYS_REFCURSOR,
        O_RESULT_CODE           OUT VARCHAR2,
        O_RESULT_MSG            OUT VARCHAR2
    )
    IS
        V_DIVISION_ID           VARCHAR2(50 CHAR) := UPPER(P_DIVISION_ID);
        V_PLAN_TYPE             VARCHAR2(50 CHAR) := UPPER(P_PLAN_TYPE);
        V_ORIGIN_DIVISION_ID    VARCHAR2(60 CHAR) := UPPER(P_ORIGIN_DIVISION_ID);
        V_SEQ                   NUMBER;
        V_BUCKET_M10            VARCHAR2(8 CHAR);       /* 10주전 */
    BEGIN

        O_RESULT_CODE := 'S';
        O_RESULT_MSG  := NULL;

        V_SEQ        := TO_NUMBER(P_SEQ);
        V_BUCKET_M10 := FN_GET_BUCKET_YYYYMMDD(-10);

        OPEN O_RC1 FOR
        SELECT IA.DIVISION_ID
             , IA.PLAN_VERSION_ID
             , IA.PLAN_NAME                                         AS PLAN_START_YYYYMMDD
             , IA.PLAN_TYPE
             , IA.PLAN_SEQ
             , IC.OSP_YN
             , IC.FP_PLAN_PERIOD
             , CASE
                   WHEN IA.PLAN_TYPE = 'PR' THEN 0
                   WHEN IA.PLAN_TYPE = 'MA' THEN IC.OFFSET - 7
                   ELSE IC.OFFSET
               END                                                  AS OFFSET
                -- 자동차(81) 사업부의 경우 Final Plan 제외하고 전 구간 생산계획 수정 가능
                -- 2021.10.13 : ESS(82) 사업부의 경우 'MA' 플랜 전 구간 생산계획 수정 가능
             , TO_CHAR(TO_DATE(IA.PLAN_NAME, 'YYYYMMDD')
                       + CASE
                             WHEN IA.PLAN_TYPE = 'PR' THEN 0
                              -- LWY begin (2023/05/03)
                              --WHEN A.DIVISION_ID = '81' THEN 0
                             WHEN IA.DIVISION_ID = '81'  AND IA.PLAN_TYPE != 'SE' THEN 0
                             WHEN IA.DIVISION_ID = '81'  AND IA.PLAN_TYPE  = 'SE' THEN IC.PROD_FROZEN
                              -- LWY end	 (2023/05/03)
                              -- 2021.10.13 : ESS(82) 사업부의 경우 'MA' 플랜 전 구간 생산계획 수정 가능
                              --WHEN plan_type ='MA' THEN c.offset -7
                             WHEN IA.DIVISION_ID = '82'  AND IA.PLAN_TYPE  = 'MA' THEN 0
                             WHEN IA.DIVISION_ID != '82' AND IA.PLAN_TYPE  = 'MA' THEN IC.OFFSET - 7
                             ELSE IC.OFFSET
                         END, 'YYYYMMDD')                           AS EDIT_START_DATE
             , CASE IA.PLAN_TYPE
                   WHEN 'PR' THEN 0
                   WHEN 'MA' THEN 1
                   WHEN 'SE' THEN 3
                   WHEN 'FI' THEN 4
                   ELSE 9
               END                                                  AS PLAN_TYPE_ORDER
             , IA.CONFIRM_YN
             , CASE
                   WHEN IA.PLAN_NAME < IB.BASIS_START_DATE
                   THEN 'N'
                   ELSE 'Y'
               END                                                  AS DATE_CHK
             , 'Y'                                                  AS IS_EDITABLE
          FROM (SELECT XA.DIVISION_ID
                     , XB.PLAN_NAME || '-' || XA.PLAN_TYPE || '-' || FN_ZERO_LPAD(TO_CHAR(XA.PLAN_SEQ), 2)  AS PLAN_VERSION_ID
                     , XB.PLAN_NAME
                     , XA.PLAN_SEQ
                     , XA.PLAN_TYPE
                     , CASE
                           WHEN RTRIM(XA.CONFIRM_FLAG) IS NULL
                           THEN 'N'
                           ELSE XA.CONFIRM_FLAG
                       END                                          AS CONFIRM_YN
                  FROM SCM_MST_PLAN_DETAIL  XA
                     , SCM_MST_PLAN         XB
                     , SCM_MST_MODELING     XC
                 WHERE XC.MODELING_ID = XA.MODELING_ID
                   AND XC.DIVISION_ID = XA.DIVISION_ID
                   AND XB.DIVISION_ID = XA.DIVISION_ID
                   AND XB.PLAN_CYCLE  = XC.PLAN_CYCLE
                   AND XB.PLAN_ID     = XA.PLAN_ID
                   AND XC.PLAN_CYCLE  = 'WEEKLY'
                   AND XB.PLAN_NAME  >= V_BUCKET_M10       --10주전
                   AND XA.DIVISION_ID = V_DIVISION_ID
                   AND XA.PLAN_TYPE   = V_PLAN_TYPE
                   AND XA.PLAN_SEQ    = V_SEQ
                   AND XB.PLAN_NAME   = P_PLAN_START_YYYYMMDD) IA
             , (SELECT TO_CHAR(TO_DATE(XD.BASIS_YYYYMMDD, 'YYYYMMDD') - (XD.DAYOFWEEK_NO - 1), 'YYYYMMDD') AS BASIS_START_DATE
                  FROM (SELECT CASE
                                   WHEN SA.DAYOFWEEK_NO - 1 = 0
                                   THEN 7
                                   ELSE SA.DAYOFWEEK_NO - 1
                               END                                  AS DAYOFWEEK_NO
                             , SA.BASIS_YYYYMMDD
                          FROM SCM_SYS_CALENDAR_M SA
                         WHERE SA.BASIS_YYYYMMDD = TO_CHAR(SYSDATE, 'YYYYMMDD')) XD) IB
             , (SELECT XE.OSP_YN
                     , XE.FP_PLAN_PERIOD
                     , CASE
                           WHEN XE.OSP_YN = 'Y'
                           THEN 0
                           ELSE XE.FP_PLAN_PERIOD
                       END                                          AS OFFSET
                     , XE.PROD_FROZEN -- LWY
                  FROM SCM_MST_SITE XE
                 WHERE XE.DIVISION_ID        = V_ORIGIN_DIVISION_ID
                   AND UPPER(XE.SCM_SITE_ID) = UPPER(P_SCM_SITE_ID)) IC;

    EXCEPTION
        WHEN OTHERS THEN
            O_RESULT_CODE := 'F';
            O_RESULT_MSG  := '[' || TO_CHAR(SQLCODE) || ']' || SQLERRM;

            P_LOG_ERROR('SCP0011_GET_PLAN_EDIT_INFO'
                      , 'P_DIVISION_ID=' || P_DIVISION_ID
                     || ', P_SCM_SITE_ID=' || P_SCM_SITE_ID
                     || ', P_PLAN_START_YYYYMMDD=' || P_PLAN_START_YYYYMMDD
                     || ', P_PLAN_TYPE=' || P_PLAN_TYPE
                     || ', P_SEQ=' || P_SEQ
                     || ', P_ORIGIN_DIVISION_ID=' || P_ORIGIN_DIVISION_ID
                      , SQLCODE
                      , SQLERRM
                      , DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);

    END P_SCP0011_GET_PLAN_EDIT_INFO;


    /*==================================================================================================
     * Program ID   : PR_SCP_ANL_PRODUCTION_PLAN_I_AMEND
     * Description  :
     * OutTable     :
     * Execute      : EXEC PR_SCP_ANL_PRODUCTION_PLAN_I_AMEND N'81',N'20180108',N'MA',N'2',N'LTW'
     * Program History
     *===================================================================================================
     *   Date       In Charge      Description
     *===================================================================================================
     * 2018.06.07   LTW         Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
     * 2018.06.11	HWY			EOH 계산 관련 RETURN값 수정
     * 2026.09.18               [MSSQL -> Oracle 전환] 화면 Target-Plan(Amend) 재계산 (SCP0011 만 호출)
     *                          조인 갱신은 재계산 값을 임시 테이블에 담은 뒤 상관 갱신으로 전환
     *==================================================================================================*/
    PROCEDURE P_SCP_ANL_PROD_PLAN_I_AMEND
    (
        P_DIVISION_ID           IN  VARCHAR2,
        P_PLAN_START_YYYYMMDD   IN  VARCHAR2,   -- plan_name
        P_PLAN_TYPE             IN  VARCHAR2,
        P_SEQ                   IN  VARCHAR2,
        P_OPERATION_GROUP       IN  VARCHAR2,
        P_USER_ID               IN  VARCHAR2 DEFAULT 'scp_batch',
        O_RC1                   OUT SYS_REFCURSOR,
        O_RESULT_CODE           OUT VARCHAR2,
        O_RESULT_MSG            OUT VARCHAR2
    )
    IS
        V_DIVISION_ID           VARCHAR2(30 CHAR)   := UPPER(P_DIVISION_ID);
        V_PLAN_TYPE             VARCHAR2(30 CHAR)   := UPPER(P_PLAN_TYPE);
        V_OPERATION_GROUP       VARCHAR2(10 CHAR)   := UPPER(P_OPERATION_GROUP);
        V_SEQ                   NUMBER;
        V_PLAN_START_DATE       DATE;

        -- LOG 용 변수 설정
        V_BATCH_USER            VARCHAR2(150 CHAR)  := P_USER_ID;
        V_PROGRAM_NAME          VARCHAR2(150 CHAR)  := 'PR_SCP_ANL_PRODUCTION_PLAN_I_AMEND';
        V_LOG_TYPE              VARCHAR2(30 CHAR);  -- START/END/ERROR/...
        N_LOG_COUNT             NUMBER              := 0;
        V_LOG_MESSAGE           VARCHAR2(1000 CHAR);
        V_DESCRIPTION           VARCHAR2(500 CHAR);
        V_TABLE_ID              VARCHAR2(150 CHAR)  := 'SCP_ANL_PRODUCTION_PLAN';
        D_EVENT_DATE            DATE;
    BEGIN

        O_RESULT_CODE := 'S';
        O_RESULT_MSG  := NULL;

        -- 시작 LOG
        V_LOG_TYPE    := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := V_PROGRAM_NAME || ':' || ' SCP_ANL_PRODUCTION_PLAN UPDATE LOGIC';
        D_EVENT_DATE  := SYSDATE;
        PR_SCP_SYS_LOG_BATCH(P_PROGRAM_NAME => V_PROGRAM_NAME
                           , P_LOG_TYPE     => V_LOG_TYPE
                           , P_LOG_COUNT    => N_LOG_COUNT
                           , P_LOG_MESSAGE  => V_LOG_MESSAGE
                           , P_DESCRIPTION  => V_DESCRIPTION
                           , P_EVENT_DATE   => D_EVENT_DATE
                           , P_USER_ID      => V_BATCH_USER);

        BEGIN

            /* AS-IS 는 문자 차수를 숫자 칸과 비교해 형 변환 오류가 나면 CATCH 로 간다 */
            V_SEQ := TO_NUMBER(P_SEQ);

            /* 파티션 프루닝용 - 형식이 틀리면 NULL 이고, 이때는 계획 일자 조건이 이미 0 건이다 */
            SELECT TO_DATE(P_PLAN_START_YYYYMMDD DEFAULT NULL ON CONVERSION ERROR, 'YYYYMMDD')
              INTO V_PLAN_START_DATE
              FROM DUAL;

            -----------------------------------------------------------
            --1. 생산계획(ONHAND_EOH) 데이터 AMEND
            -----------------------------------------------------------
            DELETE FROM GT_0011_AMEND;

            /* 사이트 · 품목별 누적(생산계획 AMEND - 요구량) — 같은 일자 행은 같은 누적값(RANGE 기본 범위) */
            INSERT INTO GT_0011_AMEND
                 (
                   SCM_SITE_ID
                  ,ITEM_ID
                  ,YYYYMMDD
                  ,QTY
                 )
            SELECT DISTINCT
                   IA.SCM_SITE_ID
                 , IA.ITEM_ID
                 , IA.YYYYMMDD
                 , IA.P_SUM - IA.S_SUM                              AS QTY
              FROM (SELECT A.SCM_SITE_ID
                         , A.ITEM_ID
                         , A.YYYYMMDD
                         , SUM(CASE
                                   WHEN A.MEASURE = 'REQUIREMENT'
                                   THEN NVL(A.QTY, 0)
                                   ELSE 0
                               END) OVER (PARTITION BY A.SCM_SITE_ID
                                                     , A.ITEM_ID
                                              ORDER BY A.SCM_SITE_ID
                                                     , A.ITEM_ID
                                                     , A.YYYYMMDD)  AS S_SUM
                         , SUM(CASE
                                   WHEN A.MEASURE = 'PROD_PLAN_AMEND'
                                   THEN NVL(A.QTY, 0)
                                   ELSE 0
                               END) OVER (PARTITION BY A.SCM_SITE_ID
                                                     , A.ITEM_ID
                                              ORDER BY A.SCM_SITE_ID
                                                     , A.ITEM_ID
                                                     , A.YYYYMMDD)  AS P_SUM
                      FROM SCP_ANL_PRODUCTION_PLAN A
                     WHERE A.MEASURE                 IN ('PROD_PLAN_AMEND', 'REQUIREMENT')
                       AND A.PLAN_START_YYYYMMDD      = P_PLAN_START_YYYYMMDD
                       AND A.PLAN_START_YYYYMMDD_DATE = V_PLAN_START_DATE        /* 파티션 프루닝 */
                       AND A.PLAN_TYPE                = V_PLAN_TYPE
                       AND A.SEQ                      = V_SEQ
                       AND A.DIVISION_ID              = V_DIVISION_ID
                       AND A.OPERATION_GROUP          = V_OPERATION_GROUP) IA;

            UPDATE SCP_ANL_PRODUCTION_PLAN A
               SET A.QTY              = (SELECT SA.QTY
                                           FROM GT_0011_AMEND SA
                                          WHERE SA.SCM_SITE_ID = A.SCM_SITE_ID
                                            AND SA.ITEM_ID     = A.ITEM_ID
                                            AND SA.YYYYMMDD    = A.YYYYMMDD)
                 , A.LAST_UPDATED_BY  = P_USER_ID
                 , A.LAST_UPDATE_DATE = SYSDATE
             WHERE EXISTS (SELECT 1
                             FROM GT_0011_AMEND SB
                            WHERE SB.SCM_SITE_ID = A.SCM_SITE_ID
                              AND SB.ITEM_ID     = A.ITEM_ID
                              AND SB.YYYYMMDD    = A.YYYYMMDD)
               AND A.MEASURE                  = 'ONHAND_EOH'
               AND A.PLAN_START_YYYYMMDD      = P_PLAN_START_YYYYMMDD
               AND A.PLAN_START_YYYYMMDD_DATE = V_PLAN_START_DATE            /* 파티션 프루닝 */
               AND A.PLAN_TYPE                = V_PLAN_TYPE
               AND A.SEQ                      = V_SEQ
               AND A.DIVISION_ID              = V_DIVISION_ID
               AND A.OPERATION_GROUP          = V_OPERATION_GROUP;

            -- TXN LOG
            V_LOG_TYPE    := 'TXN';
            N_LOG_COUNT   := 1;     /* AS-IS 는 변수 대입 직후의 @@ROWCOUNT(=1)를 기록한다 */
            V_LOG_MESSAGE := 'UPDATE ' || V_TABLE_ID;
            V_DESCRIPTION := 'Process Complete...' || ':' || TO_CHAR(D_EVENT_DATE, 'YYYY-MM-DD HH24:MI:SS') || '.000';
            D_EVENT_DATE  := SYSDATE;
            PR_SCP_SYS_LOG_BATCH(P_PROGRAM_NAME => V_PROGRAM_NAME
                               , P_LOG_TYPE     => V_LOG_TYPE
                               , P_LOG_COUNT    => N_LOG_COUNT
                               , P_LOG_MESSAGE  => V_LOG_MESSAGE
                               , P_DESCRIPTION  => V_DESCRIPTION
                               , P_EVENT_DATE   => D_EVENT_DATE
                               , P_USER_ID      => V_BATCH_USER);

            /* AS-IS 는 명시 트랜잭션 없이 문장 단위로 확정된다 */
            COMMIT;

            -- 결과코드 반환
            OPEN O_RC1 FOR
            SELECT 'S'                                              AS RESULT_CODE
              FROM DUAL;

        EXCEPTION
            WHEN OTHERS THEN
                ROLLBACK;

                O_RESULT_CODE := 'F';
                O_RESULT_MSG  := '[' || TO_CHAR(SQLCODE) || ']' || SQLERRM;

                -- ERROR LOG
                V_LOG_TYPE    := 'ERROR';
                V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
                V_DESCRIPTION := 'ERROR_LINE : ' || SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 480);
                D_EVENT_DATE  := SYSDATE;
                PR_SCP_SYS_LOG_BATCH(P_PROGRAM_NAME => V_PROGRAM_NAME
                                   , P_LOG_TYPE     => V_LOG_TYPE
                                   , P_LOG_COUNT    => N_LOG_COUNT
                                   , P_LOG_MESSAGE  => V_LOG_MESSAGE
                                   , P_DESCRIPTION  => V_DESCRIPTION
                                   , P_EVENT_DATE   => D_EVENT_DATE
                                   , P_USER_ID      => V_BATCH_USER);

                -- 결과코드 반환
                OPEN O_RC1 FOR
                SELECT 'F'                                          AS RESULT_CODE
                  FROM DUAL;
        END;

        -- 종료 LOG
        V_LOG_TYPE    := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := NULL;
        D_EVENT_DATE  := SYSDATE;
        PR_SCP_SYS_LOG_BATCH(P_PROGRAM_NAME => V_PROGRAM_NAME
                           , P_LOG_TYPE     => V_LOG_TYPE
                           , P_LOG_COUNT    => N_LOG_COUNT
                           , P_LOG_MESSAGE  => V_LOG_MESSAGE
                           , P_DESCRIPTION  => V_DESCRIPTION
                           , P_EVENT_DATE   => D_EVENT_DATE
                           , P_USER_ID      => V_BATCH_USER);

    END P_SCP_ANL_PROD_PLAN_I_AMEND;

END PKG_SCP0011;

PACKAGE BODY PKG_SCP0017
IS
/*
 * Program ID   : PKG_SCP0017
 * Description  : SCP0017 Waterfall Production Plan
 * Program History
 *===================================================================================================
 * Date         In Charge       Description
 *===================================================================================================
 * 2026.09.26   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 * 2026.10.07   AJS          화면 조회조건 사이트 · 라인 · 전극유형의 ALL 을 조건 없음으로 처리(AS-IS 빈 값과 같은 의미)
 * 2026.10.07   AJS          조회 속도 개선 : 기준정보 적재(GT_0017_RAW)의 사업부명 · 생산품목 함수 결과 재사용, 사이트명 · 별칭은 값마다 한 번 조회, 달력 해시 조인
 */

    /*******************************************************************************
     * FN_ORDER_EXPR
     *   AS-IS 정렬 순서를 내는 ORDER BY 식을 만든다.
     *   문자 칸은 공용 함수 FN_ASIS_SORT_KEY 를 쓴다
     *   (AS-IS 순서를 글자 95 자 전수로 재어 만든 것 · 하이픈·홑따옴표는 빠지고
     *    구두점·기호는 숫자·문자보다 앞 · 대소문자를 가리지 않음).
     *   ★NULLS FIRST 를 반드시 붙인다 — 값이 하이픈뿐이면 정렬 열쇠가 NULL 이 되고
     *     Oracle 기본은 NULL 을 맨 뒤에 두지만 AS-IS 는 맨 앞이다.
     *   숫자 칸은 바꾸지 않는다.
     *******************************************************************************/
    FUNCTION FN_ORDER_EXPR
    (
        P_COLS  IN VARCHAR2
    )
    RETURN VARCHAR2
    IS

        C_NUMBER_COLS   CONSTANT VARCHAR2(200) := ',CELL_CF,QTY,';

        V_RESULT        VARCHAR2(4000);
        V_TOKEN         VARCHAR2(200);
        V_COL           VARCHAR2(200);
        V_DESC_YN       VARCHAR2(1);
        V_EXPR          VARCHAR2(600);
        V_IDX           PLS_INTEGER := 1;

    BEGIN

        LOOP

            V_TOKEN := TRIM(REGEXP_SUBSTR(P_COLS, '[^,]+', 1, V_IDX));

            EXIT WHEN V_TOKEN IS NULL;

            IF UPPER(V_TOKEN) LIKE '% DESC' THEN
                V_COL     := TRIM(SUBSTR(V_TOKEN, 1, LENGTH(V_TOKEN) - 5));
                V_DESC_YN := 'Y';
            ELSE
                V_COL     := V_TOKEN;
                V_DESC_YN := 'N';
            END IF;

            IF INSTR(C_NUMBER_COLS, ',' || UPPER(V_COL) || ',') > 0 THEN
                /* 숫자 칸 */
                IF V_DESC_YN = 'Y' THEN
                    V_EXPR := V_COL || ' DESC NULLS LAST';
                ELSE
                    V_EXPR := V_COL || ' NULLS FIRST';
                END IF;
            ELSE
                /* 문자 칸 : AS-IS 정렬 순서를 내는 공용 함수 */
                V_EXPR := 'FN_ASIS_SORT_KEY(' || V_COL || ')';

                IF V_DESC_YN = 'Y' THEN
                    V_EXPR := V_EXPR || ' DESC NULLS LAST';
                ELSE
                    V_EXPR := V_EXPR || ' NULLS FIRST';
                END IF;
            END IF;

            IF V_RESULT IS NULL THEN
                V_RESULT := V_EXPR;
            ELSE
                V_RESULT := V_RESULT || CHR(10) || '        , ' || V_EXPR;
            END IF;

            V_IDX := V_IDX + 1;

        END LOOP;

        RETURN V_RESULT;

    END FN_ORDER_EXPR;

    /*******************************************************************************
     * P_SCP0017_GET_SHEET_CALENDAR_3SPAN
     *   화면 머리글 달력. AS-IS 에 SCP0017 전용 프로시저가 없고
     *   화면 등록이 이 패키지를 가리키므로 공용
     *   PKG_COM0000.P_SCP0009_GET_SHEET_CALENDAR_3SPAN 과 같은 내용으로 둔다.
     *
     * 전환 기준 (AS-IS 동작 재현)
     *   1. 인자는 AS-IS NVARCHAR(8) 이므로 앞 8 자만 사용
     *   2. AS-IS 비교 콜레이션은 하이픈·아포스트로피를 견주지 않고 기호·공백류를 숫자보다 앞에 둔다
     *   3. 시작일이 빈값이면 AS-IS 는 '' 비교로 전체 기간 조회
     *   4. DAY_CODE 빈 문자('')는 Oracle 에서 NULL
     *******************************************************************************/
    PROCEDURE P_SCP0017_GET_SHEET_CALENDAR_3SPAN
    (
        P_START_YYYYMMDD        IN  VARCHAR2
      , P_END_YYYYMMDD          IN  VARCHAR2
      , O_RC1                   OUT SYS_REFCURSOR
      , O_RESULT_CURSOR         OUT SYS_REFCURSOR
    )
    IS

        V_START_KEY     VARCHAR2(40);
        V_END_KEY       VARCHAR2(40);

        /* AS-IS 문자열 비교 기준으로 인자 변환 */
        FUNCTION F_COMPARE_KEY(P_VALUE IN VARCHAR2) RETURN VARCHAR2
        IS
            V_VALUE     VARCHAR2(40);
        BEGIN
            /* NVARCHAR(8) 절삭 */
            V_VALUE := SUBSTR(P_VALUE, 1, 8);
            /* 비교에서 견주지 않는 문자 제거 : 아포스트로피 · 하이픈 · 소프트 하이픈 · EN DASH */
            V_VALUE := TRANSLATE(V_VALUE
                               , CHR(1) || '''-' || UNISTR('\00AD\2013')
                               , CHR(1));
            /* 전각·위첨자 숫자는 숫자로, 숫자보다 앞에 정렬되는 기호·공백류는 공백으로 */
            V_VALUE := TRANSLATE(V_VALUE
                               , UNISTR('\FF10\FF11\FF12\FF13\FF14\FF15\FF16\FF17\FF18\FF19\00B9\00B2\00B3')
                                 || ':;<=>?@[\]^_`{|}~'
                                 || UNISTR('\3000\00A0')
                               , '0123456789123'
                                 || RPAD(' ', 19));
            RETURN V_VALUE;
        END F_COMPARE_KEY;

    BEGIN

        /* 시작일 빈값 = AS-IS '' 비교(전체) */
        V_START_KEY := NVL(F_COMPARE_KEY(P_START_YYYYMMDD), ' ');
        /* 종료일 빈값 = NULL 비교(0건), AS-IS '' 비교와 같은 결과 */
        V_END_KEY   := F_COMPARE_KEY(P_END_YYYYMMDD);

        OPEN O_RC1 FOR
            SELECT 'D_' || BASIS_YYYYMMDD           AS COLUMN_NAME
                 , CALENDAR_DAY                     AS COLUMN_LABEL_NAME
                 , WEEK_NAME                        AS SMALL_CLASS_LABEL_NAME
                 , MONTH_NAME                       AS LARGE_CLASS_LABEL_NAME
                 , DAYOFWEEK                        AS DAY_CODE
                 , BASIS_YYYYMMDD || '31'           AS SORT_ORDER_NO
              FROM SCM_SYS_CALENDAR_M
             WHERE BASIS_YYYYMMDD >= V_START_KEY
               AND BASIS_YYYYMMDD <= V_END_KEY
             UNION ALL
            SELECT 'W_' || BASIS_YYYYMM || ISO_WEEK AS COLUMN_NAME
                 , WEEK_NAME                        AS COLUMN_LABEL_NAME
                 , WEEK_NAME                        AS SMALL_CLASS_LABEL_NAME
                 , MONTH_NAME                       AS LARGE_CLASS_LABEL_NAME
                 , NULL                             AS DAY_CODE
                 , BASIS_START_DATE || '21'         AS SORT_ORDER_NO
              FROM SCM_SYS_CALENDAR_M
             WHERE BASIS_YYYYMMDD >= V_START_KEY
               AND BASIS_YYYYMMDD <= V_END_KEY
             GROUP BY BASIS_YYYYMM
                    , ISO_WEEK
                    , WEEK_NAME
                    , MONTH_NAME
                    , BASIS_START_DATE
             UNION ALL
            SELECT 'M_' || BASIS_YYYYMM             AS COLUMN_NAME
                 , MONTH_NAME                       AS COLUMN_LABEL_NAME
                 , MONTH_NAME                       AS SMALL_CLASS_LABEL_NAME
                 , MONTH_NAME                       AS LARGE_CLASS_LABEL_NAME
                 , NULL                             AS DAY_CODE
                 , MIN(BASIS_START_DATE) || '01'    AS SORT_ORDER_NO
              FROM SCM_SYS_CALENDAR_M
             WHERE BASIS_YYYYMMDD >= V_START_KEY
               AND BASIS_YYYYMMDD <= V_END_KEY
             GROUP BY BASIS_YYYYMM
                    , MONTH_NAME
             ORDER BY SORT_ORDER_NO;

        OPEN O_RESULT_CURSOR FOR
            SELECT '0' AS CODE, 'SUCCESS' AS MSG, '0' AS EVENT FROM DUAL;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[PKG_SCP0017.P_SCP0017_GET_SHEET_CALENDAR_3SPAN] ' || SQLERRM);

    END P_SCP0017_GET_SHEET_CALENDAR_3SPAN;


    /*******************************************************************************
     * P_SCP0017_GET_PRODUCTION_PLAN_MODEL_WATERFALL
     *   AS-IS SCP0017_GET_PRODUCTION_PLAN_MODEL_WATERFALL
     *
     * 전환 기준
     *   1. AS-IS 임시 자료는 전역 임시 테이블(GT_0017_*)로 옮기고 시작할 때 비운다.
     *   2. AS-IS 가 문자열로 조립하던 조회문은 조건 분기가 있는 정적 SQL 로 바꾼다.
     *      조회 기간에 따라 칸 개수가 달라지는 마지막 피벗만 동적으로 둔다.
     *   3. AS-IS 가 만들기만 하고 쓰지 않는 임시 자료(NICKITEM)는 만들지 않는다.
     *   4. 원본 MSSQL 주석은 형태 그대로 둔다.
     *******************************************************************************/
    PROCEDURE P_SCP0017_GET_PRODUCTION_PLAN_MODEL_WATERFALL
    (
        P_DIVISION_ID           IN  VARCHAR2
      , P_OPERATION_GROUP       IN  VARCHAR2
      , P_SCM_SITE_ID           IN  VARCHAR2
      , P_MODEL_ID              IN  VARCHAR2
      , P_ITEM_ID               IN  VARCHAR2
      , P_FROM_YYYYMMDD         IN  VARCHAR2
      , P_TO_YYYYMMDD           IN  VARCHAR2
      , P_VERSION_NO            IN  VARCHAR2
      , P_PROGRAM_ID            IN  VARCHAR2
      , P_SHEET_NAME            IN  VARCHAR2
      , P_USER_ID               IN  VARCHAR2
      , P_ELECTRODE_TYPE        IN  VARCHAR2
      , P_NICK_NAME             IN  VARCHAR2
      , P_GAP                   IN  VARCHAR2
      , P_LINE_ID               IN  VARCHAR2
      , DEBUG_MODE              IN  VARCHAR2
      , O_RC1                   OUT SYS_REFCURSOR
      , O_RESULT_CURSOR         OUT SYS_REFCURSOR
    )
    IS

        V_PLAN_START_YYYYMMDD   VARCHAR2(4000);
        V_TO_PERIOD             VARCHAR2(20);
        V_CNT_USER_MEASURE      PLS_INTEGER := 0;
        V_CNT_USR_COLUMN        PLS_INTEGER := 0;
        V_CNT_USR_COLUMN_FINAL  PLS_INTEGER := 0;

        V_FROM_YYYYMMDD         VARCHAR2(8);
        V_TO_YYYYMMDD           VARCHAR2(8);
        V_FROM_RESULT           VARCHAR2(8);
        V_TO_RESULT             VARCHAR2(8);

        V_CURR_CNT              PLS_INTEGER := 0;
        V_CURR_PLAN_START       VARCHAR2(100);

        V_DIV_ATTRIBUTE3        VARCHAR2(100);
        V_CURR_YYYYMM           VARCHAR2(6);

        /* 화면 칸 목록 */
        V_USER_COLS             VARCHAR2(4000);     /* AS-IS @v_final_user_cols   : MEASURE 가 두 번 들어갈 수 있다 */
        V_USER_COLS_UNIQ        VARCHAR2(4000);     /* 같은 목록에서 중복 이름을 뺀 것 (적재용) */
        V_USER_COLS_ORDER       VARCHAR2(4000);     /* AS-IS @v_final_user_cols_order */
        V_GAP_USER_COLS         VARCHAR2(4000);     /* AS-IS @v_gap_user_cols : 'A.' 를 붙인 것 */
        V_GAP_USER_KEYS         VARCHAR2(4000);     /* AS-IS @v_gap_user_keys : 키 연결식 */

        /* 피벗 칸 */
        V_PIVOT_COLS            CLOB;               /* 결과 칸 이름 목록 ('     , A.D_20260601' 꼴) */
        V_ACC_SEL_COLS          CLOB;               /* 누계 조회에서 고른 값 목록 */
        V_SUM_COLS              CLOB;
        V_ACC_DAY_COLS          CLOB;
        V_ACC_WEEK_COLS         CLOB;
        V_ACC_MONTH_COLS        CLOB;
        V_SQL                   CLOB;

        V_ERR_MSG               VARCHAR2(4000);

    BEGIN

        DBMS_LOB.CREATETEMPORARY(V_PIVOT_COLS,     TRUE);
        DBMS_LOB.CREATETEMPORARY(V_ACC_SEL_COLS,   TRUE);
        DBMS_LOB.CREATETEMPORARY(V_SUM_COLS,       TRUE);
        DBMS_LOB.CREATETEMPORARY(V_ACC_DAY_COLS,   TRUE);
        DBMS_LOB.CREATETEMPORARY(V_ACC_WEEK_COLS,  TRUE);
        DBMS_LOB.CREATETEMPORARY(V_ACC_MONTH_COLS, TRUE);
        DBMS_LOB.CREATETEMPORARY(V_SQL,            TRUE);

        /* 임시 자료 비우기 */
        DELETE FROM GT_0017_COLUMN_ALL;
        DELETE FROM GT_0017_COLUMN;
        DELETE FROM GT_0017_UOM;
        DELETE FROM GT_0017_CELL_TYPE_GROUP;
        DELETE FROM GT_0017_PRE;
        DELETE FROM GT_0017_FINAL_ITEM;
        DELETE FROM GT_0017_STD;
        DELETE FROM GT_0017_STD_PLAN;
        DELETE FROM GT_0017_STD_RESULT;
        DELETE FROM GT_0017_STD_RESULT_TEMP;
        DELETE FROM GT_0017_STD_TEMP;
        DELETE FROM GT_0017_RAW;
        DELETE FROM GT_0017_RAW_ALL_UOM;
        DELETE FROM GT_0017_FINAL_RAW;
        DELETE FROM GT_0017_GAP_DAY;
        DELETE FROM GT_0017_GAP_WEEK;
        DELETE FROM GT_0017_GAP_MONTH;

        V_PLAN_START_YYYYMMDD := REPLACE(P_VERSION_NO, 'PP_W_', '');
        V_TO_PERIOD           := P_TO_YYYYMMDD;
        V_CURR_YYYYMM         := TO_CHAR(SYSDATE, 'YYYYMM');

        SELECT COUNT(*)
          INTO V_CNT_USER_MEASURE
          FROM SCM_MST_TITLESET_USER
         WHERE 1 = 1
           AND PROGRAM_ID = P_PROGRAM_ID
           AND SHEET_NAME = P_SHEET_NAME
           AND USER_ID    = P_USER_ID;
           /* AND USER_INQUIRY_COLUMN_TYPE_CODE = 'M' */

        /* 사업부 계열 (E20260907-000019 신규로직에서 쓴다) */
        BEGIN
            SELECT ATTRIBUTE3
              INTO V_DIV_ATTRIBUTE3
              FROM SCM_MST_DIVISION
             WHERE DIVISION_ID = P_DIVISION_ID;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                V_DIV_ATTRIBUTE3 := NULL;
        END;

        /*==========================================================================
         * 화면 칸 목록
         *========================================================================*/
        INSERT INTO GT_0017_COLUMN_ALL
        (
            COLUMN_NAME
          , USER_SORT_ORDER_NO
        )
        SELECT COLUMN_NAME
             , USER_SORT_ORDER_NO
          FROM ( SELECT A.COLUMN_NAME
                      , ROW_NUMBER() OVER (ORDER BY NVL(B.SORT_ORDER_NO, A.SORT_ORDER_NO))  AS USER_SORT_ORDER_NO
                   FROM SCM_MST_SHEET_COLUMNS   A
                      , SCM_MST_TITLESET_USER   B
                  WHERE B.PROGRAM_ID(+)                    = A.PROGRAM_ID
                    AND B.SHEET_NAME(+)                    = A.SHEET_NAME
                    AND B.COLUMN_NAME(+)                   = A.COLUMN_NAME
                    AND B.USER_ID(+)                       = P_USER_ID
                    AND B.USER_INQUIRY_COLUMN_TYPE_CODE(+) = 'C'
                    AND A.PROGRAM_ID                       = P_PROGRAM_ID
                    AND A.SHEET_NAME                       = P_SHEET_NAME
                    AND A.VALID_YN                         = 'Y'
                    AND A.VISIBLE_FLAG                     = 'Y'
               )  IA;

        SELECT COUNT(1)
          INTO V_CNT_USR_COLUMN
          FROM GT_0017_COLUMN_ALL;

        INSERT INTO GT_0017_COLUMN
        (
            COLUMN_NAME
          , USER_SORT_ORDER_NO
        )
        SELECT A.COLUMN_NAME
             , A.USER_SORT_ORDER_NO
          FROM GT_0017_COLUMN_ALL  A
         WHERE 1 = 1
           AND ( V_CNT_USR_COLUMN = 0
                 OR EXISTS (SELECT 1
                              FROM SCM_MST_TITLESET_USER
                             WHERE 1 = 1
                               AND PROGRAM_ID                      = P_PROGRAM_ID
                               AND SHEET_NAME                      = P_SHEET_NAME
                               AND COLUMN_NAME                     = A.COLUMN_NAME
                               AND USER_ID                         = P_USER_ID
                               AND USER_INQUIRY_COLUMN_TYPE_CODE   = 'C')
               );

        SELECT COUNT(*)
          INTO V_CNT_USR_COLUMN_FINAL
          FROM GT_0017_COLUMN;

        /* 사용자ID 오류로 인해서 컬럼 못 가져오는 경우 있음(원인불명) */
        IF V_CNT_USR_COLUMN_FINAL = 0 THEN

            INSERT INTO GT_0017_COLUMN
            (
                COLUMN_NAME
              , USER_SORT_ORDER_NO
            )
            SELECT COLUMN_NAME
                 , USER_SORT_ORDER_NO
              FROM GT_0017_COLUMN_ALL;

        END IF;

        /*==========================================================================
         * UOM 은 DIV = 'EE' & @p_operation_group = 'E' 일때만 표시
         *========================================================================*/
        IF P_DIVISION_ID = 'EE' AND P_OPERATION_GROUP = 'E' THEN

            INSERT INTO GT_0017_UOM (UOM) SELECT 'M'  AS UOM FROM DUAL;
            INSERT INTO GT_0017_UOM (UOM) SELECT 'EA' AS UOM FROM DUAL;

        ELSE

            INSERT INTO GT_0017_UOM (UOM) SELECT 'EA' AS UOM FROM DUAL;

        END IF;

        /*==========================================================================
         * 셀 종류 묶음
         *========================================================================*/
        INSERT INTO GT_0017_CELL_TYPE_GROUP
        (
            CELL_TYPE_CODE
          , FLOW_TYPE
          , CELL_TYPE_GROUP_CODE
          , CELL_TYPE_GROUP_NAME
          , DISPLAY_SEQ
        )
        SELECT A.CODE                   AS CELL_TYPE_CODE
             , SUBSTR(A.NAME, 1, 1)     AS FLOW_TYPE
             , A.GROUP_CODE             AS CELL_TYPE_GROUP_CODE
             , G.NAME                   AS CELL_TYPE_GROUP_NAME
             , A.DISPLAY_SEQ
          FROM ( SELECT B.SEGMENT1  AS CODE
                      , B.SEGMENT2  AS NAME
                      , B.SEGMENT3  AS GROUP_CODE
                      , B.DISPLAY_SEQ
                   FROM SCM_ADM_LOOKUP_MASTER          A
                      , SCM_ADM_LOOKUP_MASTER_DETAIL   B
                  WHERE A.LOOKUP_TYPE = B.LOOKUP_TYPE
                    AND B.VALID_YN    = 'Y'
                    AND A.LOOKUP_TYPE = 'CELL_TYPE_ITEM_CODE'
                    AND A.VALID_YN    = 'Y'
               )  A
             , ( SELECT B.SEGMENT1  AS CODE
                      , B.SEGMENT2  AS NAME
                   FROM SCM_ADM_LOOKUP_MASTER          A
                      , SCM_ADM_LOOKUP_MASTER_DETAIL   B
                  WHERE A.LOOKUP_TYPE = B.LOOKUP_TYPE
                    AND B.VALID_YN    = 'Y'
                    AND A.LOOKUP_TYPE = 'CELL_TYPE_ITEM_GROUP'
                    AND A.VALID_YN    = 'Y'
               )  G
         WHERE A.GROUP_CODE = G.CODE;

        /*==========================================================================
         * 대상 품목
         *   [PJ20257329] Cell 완성 공정 하드 코딩 변경
         *   AS-IS 는 완성 공정 목록을 테이블 변수에 담아 외부조인했다.
         *   목록이 중복 없는 한 칸짜리라 EXISTS 로 옮겨도 결과가 같다.
         *========================================================================*/
        INSERT INTO GT_0017_PRE
        (
            DIVISION_ID
          , OPERATION_ID
          , ITEM_ID
          , CELL_TYPE_CODE
          , LEVEL_EXCEPT
          , CELL_NICKNAME
          , BASIC_NICKNAME_CELL40
          , NICKNAME_40
          , GROUP_CODE4
          , GROUP_CODE5
          , GROUP_CODE6
          , GROUP_CODE7
          , FLOW_TYPE
        )
        SELECT A.DIVISION_ID
             , A.FLOW_ID                        AS OPERATION_ID
             , A.ITEM_ID
             , SUBSTR(A.ITEM_ID, 3, 1)          AS CELL_TYPE_CODE
             , SUBSTR(A.ITEM_ID, 1, 2)          AS LEVEL_EXCEPT /* 예외적용 */
             , CASE
                 WHEN SUBSTR(A.DIVISION_ID, 1, 2) = '81'  THEN A.GROUP_CODE1
                 WHEN A.DIVISION_ID = '82'                THEN A.LEVEL2_CODE
                 ELSE ''
               END                              AS CELL_NICKNAME
             , CASE
                 WHEN SUBSTR(A.ITEM_ID, 1, 2) = 'EC' THEN 'ESS'
                 WHEN SUBSTR(A.ITEM_ID, 1, 2) = 'AM' THEN 'M50L'
                 ELSE
                   CASE
                     WHEN A.OPERATION_GROUP = 'P'
                     THEN (SELECT SA.NICK_NAME
                             FROM ( SELECT B.NICK_NAME
                                      FROM SCP_MST_FINAL_ITEM B
                                     WHERE B.DIVISION_ID = A.DIVISION_ID
                                       AND B.ITEM_ID     = (SELECT XA.DOE
                                                              FROM ( SELECT C.DOE
                                                                       FROM SCM_MST_ITEM_SN C
                                                                      WHERE C.DIVISION_ID = A.DIVISION_ID
                                                                        AND C.ITEM_ID     = A.ATTRIBUTE1
                                                                        AND C.DOE IS NOT NULL
                                                                   )  XA
                                                             WHERE ROWNUM = 1)
                                  )  SA
                            WHERE ROWNUM = 1)
                     ELSE (SELECT SA.NICK_NAME
                             FROM ( SELECT B.NICK_NAME
                                      FROM SCP_MST_FINAL_ITEM B
                                     WHERE B.DIVISION_ID = A.DIVISION_ID
                                       AND B.ITEM_ID     = (SELECT XA.DOE
                                                              FROM ( SELECT C.DOE
                                                                       FROM SCM_MST_ITEM_SN C
                                                                      WHERE C.DIVISION_ID = A.DIVISION_ID
                                                                        AND C.ITEM_ID     = A.ITEM_ID
                                                                        AND C.DOE IS NOT NULL
                                                                   )  XA
                                                             WHERE ROWNUM = 1)
                                  )  SA
                            WHERE ROWNUM = 1)
                   END
               END                              AS BASIC_NICKNAME_CELL40
             , A.NICK_NAME                      AS NICKNAME_40
             , A.GROUP_CODE4
             , A.GROUP_CODE5
             , A.GROUP_CODE6
             , A.GROUP_CODE7
             , CASE
                 /* [PJ20257329] 변경전 WHEN A.FLOW_ID IN ('A3000', 'A9000') THEN 'C' */
                 WHEN EXISTS (SELECT 1                      /* [PJ20257329] Cell 완성 공정 하드 코딩 변경 */
                                FROM SCM_ADM_LOOKUP_MASTER_DETAIL LK
                               WHERE LK.LOOKUP_TYPE = 'SCP_PLAN_OPERATION'
                                 AND LK.SEGMENT3    = 'A'   /* 공정그룹(Cell) */
                                 AND LK.ATTRIBUTE1  = 'Y'   /* Final Operation */
                                 AND LK.SEGMENT1    = A.FLOW_ID)
                 THEN 'C'
                 ELSE 'E'
               END                              AS FLOW_TYPE
          FROM SCP_MST_FINAL_ITEM A
         WHERE 1 = 1
           AND (SUBSTR(A.ATTRIBUTE8, 1, 2) <> 'CA' OR A.ATTRIBUTE8 IS NULL)   /* 활성화코드 분리 */
           AND A.DIVISION_ID = P_DIVISION_ID
           AND ( TRIM(P_OPERATION_GROUP) IS NULL
                 OR A.OPERATION_GROUP IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(P_OPERATION_GROUP, ','))) )
           AND ( TRIM(P_MODEL_ID) IS NULL
                 OR A.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(P_MODEL_ID, ','))) );

        INSERT INTO GT_0017_FINAL_ITEM
        (
            DIVISION_ID
          , OPERATION_ID
          , ITEM_ID
          , CELL_TYPE_CODE
          , LEVEL_EXCEPT
          , CELL_NICKNAME
          , BASIC_NICKNAME_CELL40
          , NICKNAME_40
          , GROUP_CODE4
          , GROUP_CODE5
          , GROUP_CODE6
          , GROUP_CODE7
          , FLOW_TYPE
          , CELL_TYPE_GROUP_NAME
        )
        SELECT P.DIVISION_ID
             , P.OPERATION_ID
             , P.ITEM_ID
             , P.CELL_TYPE_CODE
             , P.LEVEL_EXCEPT
             , P.CELL_NICKNAME
             , P.BASIC_NICKNAME_CELL40
             , P.NICKNAME_40
             , P.GROUP_CODE4
             , P.GROUP_CODE5
             , P.GROUP_CODE6
             , P.GROUP_CODE7
             , P.FLOW_TYPE
             , CASE
                 WHEN P.LEVEL_EXCEPT = 'EC' THEN 'Pouch'
                 WHEN P.LEVEL_EXCEPT = 'AM' THEN 'Cylindrical'
                 WHEN SUBSTR(P.ITEM_ID, 3, 1) = 'M' AND P.OPERATION_ID = 'P9500' THEN 'Pouch'
                 ELSE G.CELL_TYPE_GROUP_NAME
               END                              AS CELL_TYPE_GROUP_NAME
          FROM GT_0017_PRE               P
             , GT_0017_CELL_TYPE_GROUP   G
         WHERE P.FLOW_TYPE      = G.FLOW_TYPE(+)
           AND P.CELL_TYPE_CODE = G.CELL_TYPE_CODE(+);


        /*==========================================================================
         * 기준일(버전)별 되풀이
         *   AS-IS 는 커서로 @p_plan_start_yyyymmdd 를 쉼표로 나눠 돌린다.
         *   AS-IS String_Split 의 순번(nr)은 1 부터이므로 ROWNUM 으로 옮긴다.
         *========================================================================*/
        FOR CUR_SCP0017 IN ( SELECT ROWNUM        AS NR
                                  , COLUMN_VALUE  AS TOKEN
                               FROM TABLE(STRING_SPLIT(V_PLAN_START_YYYYMMDD, ','))
                           )
        LOOP

            V_CURR_CNT        := CUR_SCP0017.NR;
            V_CURR_PLAN_START := CUR_SCP0017.TOKEN;

            BEGIN
                SELECT C.BASIS_START_DATE
                  INTO V_FROM_YYYYMMDD
                  FROM SCM_SYS_CALENDAR_M C
                 WHERE 1 = 1
                   AND C.BASIS_YYYYMMDD = V_CURR_PLAN_START;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    V_FROM_YYYYMMDD := NULL;
            END;

            BEGIN
                SELECT C.BASIS_START_DATE
                  INTO V_FROM_RESULT
                  FROM SCM_SYS_CALENDAR_M C
                 WHERE 1 = 1
                   AND C.BASIS_YYYYMMDD = P_FROM_YYYYMMDD;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    V_FROM_RESULT := NULL;
            END;

            BEGIN
                SELECT C.BASIS_START_DATE
                  INTO V_TO_RESULT
                  FROM SCM_SYS_CALENDAR_M C
                 WHERE 1 = 1
                   AND C.BASIS_YYYYMMDD = P_TO_YYYYMMDD;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    V_TO_RESULT := NULL;
            END;

            IF V_FROM_YYYYMMDD > V_FROM_RESULT THEN
                /* 실적 보여줌 */
                V_TO_YYYYMMDD   := P_TO_YYYYMMDD;
                V_TO_RESULT     := V_FROM_YYYYMMDD;
            ELSIF V_FROM_YYYYMMDD <= V_FROM_RESULT THEN
                /* 실적 없음 */
                V_TO_YYYYMMDD   := P_TO_YYYYMMDD;
                V_FROM_RESULT   := TO_CHAR(ADD_MONTHS(TO_DATE(V_CURR_PLAN_START, 'YYYYMMDD'),  6), 'YYYYMMDD');
                V_TO_RESULT     := TO_CHAR(ADD_MONTHS(TO_DATE(V_CURR_PLAN_START, 'YYYYMMDD'), -6), 'YYYYMMDD');
            ELSIF V_FROM_YYYYMMDD > V_TO_RESULT THEN
                V_FROM_YYYYMMDD := TO_CHAR(ADD_MONTHS(TO_DATE(V_CURR_PLAN_START, 'YYYYMMDD'), -6), 'YYYYMMDD');
                V_TO_YYYYMMDD   := TO_CHAR(ADD_MONTHS(TO_DATE(V_CURR_PLAN_START, 'YYYYMMDD'), -6), 'YYYYMMDD');
                V_FROM_RESULT   := P_FROM_YYYYMMDD;
                V_TO_RESULT     := P_TO_YYYYMMDD;
            ELSIF V_FROM_YYYYMMDD = V_TO_RESULT THEN
                V_TO_YYYYMMDD   := V_FROM_YYYYMMDD;
                V_FROM_RESULT   := P_FROM_YYYYMMDD;
                V_TO_RESULT     := P_TO_YYYYMMDD;
            END IF;

            /*======================================================================
             * 기준정보 RESULT C : 회차마다 비운다
             *====================================================================*/
            DELETE FROM GT_0017_STD;
            DELETE FROM GT_0017_STD_PLAN;
            DELETE FROM GT_0017_STD_RESULT;
            DELETE FROM GT_0017_STD_RESULT_TEMP;
            DELETE FROM GT_0017_STD_TEMP;

            /* 계획 */
            INSERT INTO GT_0017_STD_PLAN
            (
                DIVISION_ID
              , OPERATION_GROUP
              , SCM_SITE_ID
              , ITEM_ID
              , OPERATION_ID
              , LINE_ID
              , MEASURE
              , YYYYMMDD
              , QTY
              , ORIGIN_DIVISION_ID
              , ELECTRODE_TYPE
            )
            SELECT A.DIVISION_ID
                 , A.OPERATION_GROUP
                 , A.SCM_SITE_ID
                 , A.ITEM_ID
                 , A.OPERATION_ID
                 , A.LINE_ID
                 , A.MEASURE
                 , A.YYYYMMDD
                 , A.QTY
                 , CASE WHEN TRIM(A.ORIGIN_DIVISION_ID) IS NULL THEN A.DIVISION_ID
                        ELSE A.ORIGIN_DIVISION_ID END               AS ORIGIN_DIVISION_ID
                 , CASE WHEN TRIM(A.ELECTRODE_TYPE) IS NULL THEN '/'
                        ELSE A.ELECTRODE_TYPE END                   AS ELECTRODE_TYPE
              FROM SCP_ANL_PRODUCTION_PLAN_C A
             WHERE 1 = 1
               AND A.YYYYMMDD            >= P_FROM_YYYYMMDD
               AND A.YYYYMMDD            <= P_TO_YYYYMMDD
               AND A.DIVISION_ID          = P_DIVISION_ID
               AND A.PLAN_START_YYYYMMDD  = V_CURR_PLAN_START
               /* 2026.09.26 성능 : 버전을 함께 걸어 기본키(사업부 · 버전 · …) 선두를 쓰게 한다.
                *   버전을 빼면 기본키 건너뛰기 조회가 되어 결과가 742 행인데 100 만 블록을 뒤진다.
                *   원장에서 버전은 언제나 'PP_W_' + 기준일 이다(실측 2026-09-26 · 사업부 82 어긋남 0 행).
                *   화면이 이 값을 받아 라인 조회에 그대로 넘기고 라인 조회가 버전으로 조회하므로
                *   짝이 어긋나면 라인 조회가 애초에 0 행이 된다. */
               AND A.VERSION_NO           = 'PP_W_' || V_CURR_PLAN_START
               AND A.OPERATION_GROUP      = P_OPERATION_GROUP
               AND A.QTY                 <> 0
               AND ( TRIM(P_SCM_SITE_ID) IS NULL
                  OR UPPER(TRIM(P_SCM_SITE_ID)) = 'ALL'                                                       --  2026.10.07 AJS
                     OR A.SCM_SITE_ID IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(P_SCM_SITE_ID, ','))) )
               AND ( ( TRIM(P_ITEM_ID) IS NULL AND TRIM(P_NICK_NAME) IS NULL )
                     OR A.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(FN_GET_ITEM_LIKE_CONDITION(P_ITEM_ID, P_NICK_NAME))) )
               AND ( TRIM(P_ELECTRODE_TYPE) IS NULL
                  OR UPPER(TRIM(P_ELECTRODE_TYPE)) = 'ALL'                                                    --  2026.10.07 AJS
                     OR A.ELECTRODE_TYPE IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(P_ELECTRODE_TYPE, ','))) )
               AND ( TRIM(P_LINE_ID) IS NULL
                  OR UPPER(TRIM(P_LINE_ID)) = 'ALL'                                                           --  2026.10.07 AJS
                     OR A.LINE_ID IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(P_LINE_ID, ','))) );

            /* 실적 */
            INSERT INTO GT_0017_STD_RESULT_TEMP
            (
                DIVISION_ID
              , OPERATION_GROUP
              , SCM_SITE_ID
              , ITEM_ID
              , OPERATION_ID
              , LINE_ID
              , MEASURE
              , YYYYMMDD
              , QTY
              , ORIGIN_DIVISION_ID
              , ELECTRODE_TYPE
            )
            SELECT CASE
                     /* E20260907-000019 기존 로직 주석처리 */
                     /* WHEN @p_division_id = 'EE' OR @p_division_id = 'EE_UC' OR @p_division_id = 'EE_HM' THEN @p_division_id */
                     /* E20260907-000019 신규로직 */
                     WHEN V_DIV_ATTRIBUTE3 = 'EE' THEN P_DIVISION_ID
                     ELSE A.DIVISION_ID
                   END                                              AS DIVISION_ID
                 , A.SCP_OPERATION_GROUP                            AS OPERATION_GROUP
                 , A.SCM_SITE_ID
                 , A.ITEM_ID
                 , A.OPERATION_ID
                 , A.LINE_ID
                 , 'PROD_PLAN_ENGINE'                               AS MEASURE
                 , TO_CHAR(A.PLAN_DATE, 'YYYYMMDD')                 AS YYYYMMDD
                 , A.ACTUAL_GOOD_QTY                                AS QTY
                 , A.DIVISION_ID                                    AS ORIGIN_DIVISION_ID
                 , CASE WHEN TRIM(A.ELECTRODE_TYPE) IS NULL THEN '/'
                        ELSE A.ELECTRODE_TYPE END                   AS ELECTRODE_TYPE
              FROM SCM_DNM_PRODUCT_RESULT_V A
             WHERE 1 = 1
               /* AND ( @p_division_id IN (SELECT DIVISION_ID FROM dbo.FN_GET_DIVISION_DIV('EE')) OR A.division_id = @p_division_id ) --div_commonization */
               AND ( A.DIVISION_ID = P_DIVISION_ID
                     OR A.DIVISION_ID IN (SELECT DIVISION_ID
                                            FROM SCM_MST_DIVISION
                                           WHERE ATTRIBUTE4 IN (SELECT ATTRIBUTE4
                                                                  FROM SCM_MST_DIVISION
                                                                 WHERE DIVISION_ID = P_DIVISION_ID)
                                             AND ATTRIBUTE3 <> 'EE') )    /* div_commonization */
               AND A.COMPANY_ID IN (SELECT DISTINCT COMPANY_ID
                                      FROM SCM_MST_SITE
                                     WHERE 1 = 1
                                       AND ( P_DIVISION_ID IN (SELECT COLUMN_VALUE FROM TABLE(FN_GET_DIVISION_DIV('EE')))
                                             OR DIVISION_ID = P_DIVISION_ID )   /* div_commonization */
                                       AND SITE_TYPE = 'PLANT'
                                       AND VALID_YN  = 'Y')
               AND A.PLAN_DATE >= TO_DATE(V_FROM_RESULT, 'YYYYMMDD')
               AND A.PLAN_DATE <  TO_DATE(V_TO_RESULT,   'YYYYMMDD');

            INSERT INTO GT_0017_STD_RESULT
            (
                DIVISION_ID
              , OPERATION_GROUP
              , SCM_SITE_ID
              , ITEM_ID
              , OPERATION_ID
              , LINE_ID
              , MEASURE
              , YYYYMMDD
              , QTY
              , ORIGIN_DIVISION_ID
              , ELECTRODE_TYPE
            )
            SELECT A.DIVISION_ID
                 , A.OPERATION_GROUP
                 , A.SCM_SITE_ID
                 , A.ITEM_ID
                 , A.OPERATION_ID
                 , A.LINE_ID
                 , A.MEASURE
                 , A.YYYYMMDD
                 , A.QTY
                 , A.ORIGIN_DIVISION_ID
                 , A.ELECTRODE_TYPE
              FROM GT_0017_STD_RESULT_TEMP A
             WHERE 1 = 1
               AND A.OPERATION_GROUP = P_OPERATION_GROUP
               AND ( SUBSTR(A.OPERATION_ID, 1, 5) IN    /* LOOKUP_TYPE 'SCP_PLAN_OPERATION' 에 정의된 공정만 조회 */
                                                     (SELECT SEGMENT1  AS OPERATION_ID
                                                        FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                                                       WHERE LOOKUP_TYPE = 'SCP_PLAN_OPERATION'
                                                         AND SEGMENT1   <> 'F6000'
                                                         AND VALID_YN    = 'Y')
                     OR A.OPERATION_ID IN             /* 외주PACKER의 업체코드 */
                                                     (SELECT S.PLANT_ID  AS OPERATION_ID
                                                        FROM SCM_MST_SITE S
                                                       WHERE 1 = 1
                                                         AND ( ( P_DIVISION_ID = 'EE'
                                                                 AND S.DIVISION_ID IN ('40', '81', '82') )
                                                               OR ( P_DIVISION_ID = 'EE_UC'
                                                                    AND S.DIVISION_ID = '81_UC' )
                                                               OR ( P_DIVISION_ID NOT IN ('EE', 'EE_UC')
                                                                    AND S.DIVISION_ID = P_DIVISION_ID ) )
                                                         AND S.SITE_TYPE = 'PLANT'
                                                         AND S.OSP_YN    = 'Y'
                                                         AND S.VALID_YN  = 'Y') )
               AND ( TRIM(P_SCM_SITE_ID) IS NULL
                  OR UPPER(TRIM(P_SCM_SITE_ID)) = 'ALL'                                                       --  2026.10.07 AJS
                     OR A.SCM_SITE_ID IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(P_SCM_SITE_ID, ','))) )
               AND ( ( TRIM(P_ITEM_ID) IS NULL AND TRIM(P_NICK_NAME) IS NULL )
                     OR A.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(FN_GET_ITEM_LIKE_CONDITION(P_ITEM_ID, P_NICK_NAME))) )
               AND ( TRIM(P_ELECTRODE_TYPE) IS NULL
                  OR UPPER(TRIM(P_ELECTRODE_TYPE)) = 'ALL'                                                    --  2026.10.07 AJS
                     OR A.ELECTRODE_TYPE IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(P_ELECTRODE_TYPE, ','))) )
               AND ( TRIM(P_LINE_ID) IS NULL
                  OR UPPER(TRIM(P_LINE_ID)) = 'ALL'                                                           --  2026.10.07 AJS
                     OR A.LINE_ID IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(P_LINE_ID, ','))) );

            INSERT INTO GT_0017_STD
            (
                DIVISION_ID
