                 , ELECTRODE_TYPE
              FROM GT_0017_STD
             WHERE 1 = 1
               AND MEASURE = 'PROD_PLAN_ENGINE';

            DELETE FROM GT_0017_STD
             WHERE 1 = 1
               AND MEASURE = 'PROD_PLAN_AMEND';

            INSERT INTO GT_0017_STD
            (
                DIVISION_ID
              , OPERATION_GROUP
              , SCM_SITE_ID
              , ITEM_ID
              , OPERATION_ID
              , LINE_ID
              , MEASURE
              , YYYYMMDD
              , QTY
              , ORIGIN_DIVISION_ID
