--                 , FROM_SITE
--                 , VARIOUS_KEY
--                 , INCOTERMS
--                 , MEASURE                      AS MEASURE_UI
--                 , SUM(CELL_QTY)                AS QTY
--                 , SUM(FROM_BOH_QTY)            AS FROM_BOH_QTY
--                 , SUM(TO_BOH_QTY)              AS TO_BOH_QTY
--                 , MAX(CELL_CF)                 AS CELL_CF
--              FROM GT_SCP0100_RAW
--             GROUP BY YYYYPW
--                    , DIVISION_ID
--                    , PLAN_TYPE
--                    , CELL_GROUP
--                    , OPERATION_GROUP
--                    , OPERATION_ID
--                    , PRODUCT_LEVEL1
