            INSERT INTO GT_SCP0100_RAW_CELL_CF
            (
                DIVISION_ID
              , CELL_GROUP
              , PLAN_TYPE
              , OPERATION_GROUP
              , OPERATION_ID
              , ITEM_ID
              , TO_SITE
              , FROM_SITE
              , INCOTERMS
              , PRODUCT_LEVEL1
              , PRODUCT_LEVEL2
              , PRODUCT_LEVEL3
              , MEASURE
              , VARIOUS_KEY
              , CELL_CF
            )
            SELECT DIVISION_ID
                 , CELL_GROUP
                 , PLAN_TYPE                    /* E20260708-000926 */
                 , OPERATION_GROUP
                 , OPERATION_ID
                 , ITEM_ID
                 , TO_SITE
                 , FROM_SITE
                 , INCOTERMS
                 , PRODUCT_LEVEL1
                 , PRODUCT_LEVEL2
                 , PRODUCT_LEVEL3
                 , MEASURE
                 , VARIOUS_KEY
                 , MAX(CELL_CF)                 AS CELL_CF
              FROM GT_SCP0100_RAW
             GROUP BY DIVISION_ID
                    , CELL_GROUP
                    , PLAN_TYPE
                    , OPERATION_GROUP
                    , OPERATION_ID
                    , ITEM_ID
                    , TO_SITE
                    , FROM_SITE
                    , INCOTERMS
                    , PRODUCT_LEVEL1
                    , PRODUCT_LEVEL2
                    , PRODUCT_LEVEL3
                    , MEASURE
                    , VARIOUS_KEY;

            INSERT INTO GT_SCP0100_ALL_MEASURE_UI
            (
                DIVISION_ID
              , PLAN_TYPE
              , CELL_GROUP
              , OPERATION_GROUP
              , OPERATION_ID
              , ITEM_ID
              , TO_SITE
              , FROM_SITE
              , INCOTERMS
              , PRODUCT_LEVEL1
              , PRODUCT_LEVEL2
              , PRODUCT_LEVEL3
              , CELL_CF
              , MEASURE_GROUP
              , MEASURE_UI
              , MEASURE_NAME
              , SORT_ORDER_NO
              , CODE
              , VARIOUS_KEY
              , DISPLAY_SEQ
            )
            SELECT A.DIVISION_ID
                 , A.PLAN_TYPE                  /* E20260708-000926 */
                 , A.CELL_GROUP
                 , A.OPERATION_GROUP
                 , A.OPERATION_ID
                 , A.ITEM_ID
                 , A.TO_SITE
                 , A.FROM_SITE
                 , A.INCOTERMS
                 , A.PRODUCT_LEVEL1
                 , A.PRODUCT_LEVEL2
                 , A.PRODUCT_LEVEL3
                 , A.CELL_CF
                 , B.MEASURE_GROUP              AS MEASURE_GROUP
                 , B.MEASURE_UI                 AS MEASURE_UI
                 , B.MEASURE_NAME               AS MEASURE_NAME
                 , B.SORT_ORDER_NO              AS SORT_ORDER_NO
                 , CAST(NULL AS VARCHAR2(800))  AS CODE
                 , A.VARIOUS_KEY
                 , 1                            AS DISPLAY_SEQ
              FROM GT_SCP0100_RAW_CELL_CF   A
                 , GT_SCP0100_MEASURE1      B
             WHERE B.MEASURE_UI = A.MEASURE;

            INSERT INTO GT_SCP0100_ALL_VARIOUS_KEY
            (
                DIVISION_ID
              , PLAN_TYPE
              , CELL_GROUP
              , OPERATION_GROUP
              , OPERATION_ID
              , ITEM_ID
              , TO_SITE
              , FROM_SITE
              , INCOTERMS
              , PRODUCT_LEVEL1
              , PRODUCT_LEVEL2
              , PRODUCT_LEVEL3
              , CELL_CF
              , MEASURE_GROUP
              , MEASURE_UI
              , MEASURE_NAME
              , SORT_ORDER_NO
              , CODE
              , VARIOUS_KEY
              , DISPLAY_SEQ
            )
            SELECT A.DIVISION_ID
                 , A.PLAN_TYPE                  /* E20260708-000926 */
                 , A.CELL_GROUP
                 , A.OPERATION_GROUP
                 , A.OPERATION_ID
                 , A.ITEM_ID
                 , A.TO_SITE
                 , A.FROM_SITE
                 , A.INCOTERMS
                 , A.PRODUCT_LEVEL1
                 , A.PRODUCT_LEVEL2
                 , A.PRODUCT_LEVEL3
                 , A.CELL_CF
                 , B.MEASURE_GROUP              AS MEASURE_GROUP
                 , B.MEASURE_UI                 AS MEASURE_UI
                 , B.MEASURE_NAME               AS MEASURE_NAME
                 , B.SORT_ORDER_NO              AS SORT_ORDER_NO
                 , C.CODE
                 , C.CODE                       AS VARIOUS_KEY
                 , C.DISPLAY_SEQ
              FROM GT_SCP0100_RAW_CELL_CF           A
                 , GT_SCP0100_MEASURE2              B
                 , GT_SCP0100_TRANSPORT_MODE_CODE   C
             WHERE B.MEASURE_UI = A.MEASURE
               AND C.CODE       = A.VARIOUS_KEY;

            INSERT INTO GT_SCP0100_ALL_DISPLAY_SEQ
            (
                DIVISION_ID
              , PLAN_TYPE
              , CELL_GROUP
              , OPERATION_GROUP
              , OPERATION_ID
              , ITEM_ID
              , TO_SITE
              , FROM_SITE
              , INCOTERMS
              , PRODUCT_LEVEL1
              , PRODUCT_LEVEL2
              , PRODUCT_LEVEL3
              , CELL_CF
              , MEASURE_GROUP
              , MEASURE_UI
              , MEASURE_NAME
              , SORT_ORDER_NO
              , CODE
              , VARIOUS_KEY
              , DISPLAY_SEQ
            )
            SELECT A.DIVISION_ID
                 , A.PLAN_TYPE                  /* E20260708-000926 */
                 , A.CELL_GROUP
                 , A.OPERATION_GROUP
                 , A.OPERATION_ID
                 , A.ITEM_ID
                 , A.TO_SITE
                 , A.FROM_SITE
                 , A.INCOTERMS
                 , A.PRODUCT_LEVEL1
                 , A.PRODUCT_LEVEL2
                 , A.PRODUCT_LEVEL3
                 , A.CELL_CF
                 , B.MEASURE_GROUP              AS MEASURE_GROUP
                 , B.MEASURE_UI                 AS MEASURE_UI
                 , B.MEASURE_NAME               AS MEASURE_NAME
                 , B.SORT_ORDER_NO              AS SORT_ORDER_NO
                 , C.VARIOUS_KEY                AS CODE
                 , C.VARIOUS_KEY                AS VARIOUS_KEY
                 , 1                            AS DISPLAY_SEQ
              FROM GT_SCP0100_RAW_CELL_CF   A
                 , GT_SCP0100_MEASURE3      B
                 , GT_SCP0100_LINE          C
             WHERE B.MEASURE_UI      = A.MEASURE
               AND C.DIVISION_ID     = A.DIVISION_ID
               AND C.PLAN_TYPE       = A.PLAN_TYPE           /* E20260708-000926 */
               AND C.CELL_GROUP      = A.CELL_GROUP
               AND C.OPERATION_GROUP = A.OPERATION_GROUP
               AND C.OPERATION_ID    = A.OPERATION_ID
               AND C.PRODUCT_LEVEL1  = A.PRODUCT_LEVEL1
               AND C.PRODUCT_LEVEL2  = A.PRODUCT_LEVEL2
               AND C.PRODUCT_LEVEL3  = A.PRODUCT_LEVEL3
               AND C.ITEM_ID         = A.ITEM_ID
               AND C.TO_SITE         = A.TO_SITE
               AND C.FROM_SITE       = A.FROM_SITE
               AND C.INCOTERMS       = A.INCOTERMS
               AND C.MEASURE         = B.MEASURE_UI;

            INSERT INTO GT_SCP0100_ALL
            (
                DIVISION_ID
              , PLAN_TYPE
              , CELL_GROUP
              , OPERATION_GROUP
              , OPERATION_ID
              , ITEM_ID
              , TO_SITE
              , FROM_SITE
              , INCOTERMS
              , PRODUCT_LEVEL1
              , PRODUCT_LEVEL2
              , PRODUCT_LEVEL3
              , CELL_CF
              , MEASURE_GROUP
              , MEASURE_UI
              , MEASURE_NAME
              , SORT_ORDER_NO
              , CODE
              , VARIOUS_KEY
              , DISPLAY_SEQ
            )
            SELECT DIVISION_ID
                 , PLAN_TYPE
                 , CELL_GROUP
                 , OPERATION_GROUP
                 , OPERATION_ID
                 , ITEM_ID
                 , TO_SITE
                 , FROM_SITE
                 , INCOTERMS
                 , PRODUCT_LEVEL1
                 , PRODUCT_LEVEL2
                 , PRODUCT_LEVEL3
                 , CELL_CF
                 , MEASURE_GROUP
                 , MEASURE_UI
                 , MEASURE_NAME
