/****************************************************************************************************/
/* Program ID  : P_SCP0132_GET_SEARCH_INFO                                                          */
/* Description : 조회조건 초기값 (결과 여섯 묶음)                                                   */
/****************************************************************************************************/
PROCEDURE P_SCP0132_GET_SEARCH_INFO
(
    O_RC1               OUT SYS_REFCURSOR
  , O_RC2               OUT SYS_REFCURSOR
  , O_RC3               OUT SYS_REFCURSOR
  , O_RC4               OUT SYS_REFCURSOR
  , O_RC5               OUT SYS_REFCURSOR
  , O_RC6               OUT SYS_REFCURSOR
  , O_RESULT_CURSOR     OUT SYS_REFCURSOR
)
IS
BEGIN

    /* 1. 계획 그룹 */
    OPEN O_RC1 FOR
        SELECT OPMZ_PLAN_GR_ID                          AS CODE
             , OPMZ_PLAN_GR_NAME                        AS NAME
             , DIVISION_ID
          FROM SCP_OPMZ_PLAN_GR_M
         WHERE VALID_YN = 'Y'
         ORDER BY FN_ASIS_SORT_KEY(OPMZ_PLAN_GR_NAME) NULLS FIRST;

    /* 2. 사이트 — 판매 사이트(사업부 40 은 사이트 품목 기준) + 공장 사이트 */
    OPEN O_RC2 FOR
        SELECT IA.DIVISION_ID
             , IA.CODE
             , IA.NAME
          FROM (SELECT DISTINCT A.DIVISION_ID
                     , A.SCM_SITE_ID                    AS CODE
                     , A.SCM_SITE_ID                    AS NAME
                     , A.SITE_TYPE
                  FROM SCM_MST_SITE A
                 WHERE A.SITE_TYPE   = 'SALES'
                   AND A.DIVISION_ID <> '40'
                   AND A.VALID_YN    = 'Y'
                UNION ALL
                SELECT DISTINCT A.DIVISION_ID
                     , A.SCM_SITE_ID                    AS CODE
                     , A.SCM_SITE_ID                    AS NAME
                     , A.SITE_TYPE
                  FROM SCM_MST_SITE       A
                     , SCM_MST_SITE_ITEM  B
                 WHERE B.DIVISION_ID(+) = A.DIVISION_ID
                   AND B.SCM_SITE_ID(+) = A.SCM_SITE_ID
                   AND A.SITE_TYPE      = 'SALES'
                   AND A.DIVISION_ID    = '40'
                   AND A.VALID_YN       = 'Y'
                UNION ALL
                SELECT DISTINCT A.DIVISION_ID
                     , A.SCM_SITE_ID                    AS CODE
                     , A.SCM_SITE_ID                    AS NAME
                     , A.SITE_TYPE
                  FROM SCM_MST_SITE A
                 WHERE A.SITE_TYPE = 'PLANT') IA
         ORDER BY FN_ASIS_SORT_KEY(IA.SITE_TYPE) NULLS FIRST
                , FN_ASIS_SORT_KEY(IA.NAME)      NULLS FIRST;

    /* 3. 사업부별 공장 사이트 */
    OPEN O_RC3 FOR
        SELECT DISTINCT A.DIVISION_ID
             , A.SCM_SITE_ID                            AS CODE
             , A.SCM_SITE_ID                            AS NAME
          FROM SCM_MST_SITE A
         WHERE A.SITE_TYPE = 'PLANT'
           AND A.VALID_YN  = 'Y'
         ORDER BY FN_ASIS_SORT_KEY(A.SCM_SITE_ID) NULLS FIRST
                , FN_ASIS_SORT_KEY(A.DIVISION_ID) NULLS FIRST;

    /* 4. 공정 — 이 화면용 표시가 있는 것만 */
    OPEN O_RC4 FOR
        SELECT SEGMENT1                                 AS DIVISION_ID
             , SEGMENT3                                 AS CODE
             , ATTRIBUTE1                               AS NAME
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
         WHERE LOOKUP_TYPE LIKE 'OPMZ_STAGE_CD'
           AND VALID_YN    = 'Y'
           AND ATTRIBUTE2  = 'Y'
         ORDER BY FN_ASIS_SORT_KEY(SEGMENT1) NULLS FIRST    /* 원문에 정렬이 없어 화면 순서가 흔들린다 — 저장 순서와 같게 고정 */
                , FN_ASIS_SORT_KEY(SEGMENT3) NULLS FIRST;

    /* 5. 모델 그룹 */
    OPEN O_RC5 FOR
        SELECT DISTINCT A.DIVISION_ID
             , A.MDL_GR_NM                              AS CODE
             , A.MDL_GR_NM                              AS NAME
          FROM SCP_OPMZ_CONSTRAINT_OF_SHIPMENT_QTY A
         ORDER BY FN_ASIS_SORT_KEY(A.MDL_GR_NM) NULLS FIRST;

    /* 6. 품목 */
    OPEN O_RC6 FOR
        SELECT DISTINCT A.DIVISION_ID
             , A.ITEM_ID
          FROM SCP_MST_FINAL_ITEM A
         ORDER BY FN_ASIS_SORT_KEY(A.DIVISION_ID) NULLS FIRST   /* 원문에 정렬이 없어 화면 순서가 흔들린다 — 원장 열쇠 순서와 같게 고정 */
                , FN_ASIS_SORT_KEY(A.ITEM_ID)     NULLS FIRST;

    OPEN O_RESULT_CURSOR FOR
        SELECT '0'          AS RESULT_CODE
             , 'SUCCESS'    AS RESULT_MESSAGE
          FROM DUAL;

END P_SCP0132_GET_SEARCH_INFO;

/****************************************************************************************************/
/* Program ID  : P_SCP0132_GET_CONSTRAINT_OF_SHIPMENT_QTY                                           */
/* Description : 출하수량 제약 조회                                                                 */
/****************************************************************************************************/
PROCEDURE P_SCP0132_GET_CONSTRAINT_OF_SHIPMENT_QTY
(
    P_DIVISION_ID       IN  CLOB
  , P_PLAN_GROUP_ID     IN  CLOB
  , P_FROM_SITE_ID      IN  CLOB
  , P_TO_SITE_ID        IN  CLOB
  , P_MDL_GR_NM         IN  CLOB
  , P_ITEM_ID           IN  CLOB
  , P_STAGE             IN  CLOB
  , P_FROM_YYYYMMDD     IN  CLOB
  , P_TO_YYYYMMDD       IN  CLOB
  , P_VALID_YN          IN  CLOB
  , O_RC1               OUT SYS_REFCURSOR
  , O_RESULT_CURSOR     OUT SYS_REFCURSOR
)
IS
    /* 원문이 조회조건을 NVARCHAR(200) 변수로 받아 200자에서 자른다 */
    V_DIVISION_ID       VARCHAR2(200 CHAR)   := TO_CHAR(SUBSTR(P_DIVISION_ID,   1, 200));
    V_PLAN_GROUP_ID     VARCHAR2(200 CHAR)   := TO_CHAR(SUBSTR(P_PLAN_GROUP_ID, 1, 200));
    V_FROM_SITE_ID      VARCHAR2(200 CHAR)   := TO_CHAR(SUBSTR(P_FROM_SITE_ID,  1, 200));
    V_TO_SITE_ID        VARCHAR2(200 CHAR)   := TO_CHAR(SUBSTR(P_TO_SITE_ID,    1, 200));
    V_MDL_GR_NM         VARCHAR2(200 CHAR)   := TO_CHAR(SUBSTR(P_MDL_GR_NM,     1, 200));
    V_STAGE             VARCHAR2(200 CHAR)   := TO_CHAR(SUBSTR(P_STAGE,         1, 200));
    V_FROM_YYYYMMDD     VARCHAR2(200 CHAR)   := TO_CHAR(SUBSTR(P_FROM_YYYYMMDD, 1, 200));
    V_TO_YYYYMMDD       VARCHAR2(200 CHAR)   := TO_CHAR(SUBSTR(P_TO_YYYYMMDD,   1, 200));
    V_VALID_YN          VARCHAR2(200 CHAR)   := TO_CHAR(SUBSTR(P_VALID_YN,      1, 200));
    /* 품목만 원문이 자르지 않은 값을 쓴다 */
    V_ITEM_ID           VARCHAR2(32767 CHAR) := TO_CHAR(SUBSTR(P_ITEM_ID,       1, 32767));
BEGIN

    OPEN O_RC1 FOR
        SELECT A.DIVISION_ID
             , A.OPMZ_PLAN_GR_ID
             , A.MDL_GR_NM
             , A.ITEM_ID
             , A.STAGE
             , A.FROM_STE_ID
             , A.TO_STE_ID
             /* ★원문은 하이픈을 넣은 문자로 돌려준다 */
             , CASE WHEN A.FROM_YYYYMMDD IS NULL THEN ''
                    ELSE TO_CHAR(TO_DATE(A.FROM_YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD')
               END                                              AS FROM_YYYYMMDD
             , CASE WHEN A.TO_YYYYMMDD IS NULL THEN ''
                    ELSE TO_CHAR(TO_DATE(A.TO_YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD')
               END                                              AS TO_YYYYMMDD
             , A.SIPM_MIN_QYT
             , A.SIPM_MAX_QTY
             , A.SAT_SIPM_MIN_QTY
             , A.SAT_SIPM_MAX_QTY
             , A.SUN_SIPM_MIN_QTY
             , A.SUN_SIPM_MAX_QTY
             , A.VAL_TP_CD
             , A.VALUE_DESCRIPTION
             , A.VALID_YN
             , A.CREATED_BY
             , A.CREATION_DATE
             , A.LAST_UPDATED_BY
             , A.LAST_UPDATE_DATE
             /* 이어 붙이는 네 칸은 모두 원장이 값을 요구하므로 빈 값이 되지 않는다 */
             , A.DIVISION_ID || '|' || A.OPMZ_PLAN_GR_ID || '|' || A.MDL_GR_NM || '|' || A.ITEM_ID AS PRE_KEY_VALUES
          FROM SCP_OPMZ_CONSTRAINT_OF_SHIPMENT_QTY A
             , (SELECT DISTINCT '%' || UPPER(COLUMN_VALUE) || '%' AS TST
                  FROM TABLE(STRING_SPLIT(V_ITEM_ID, ','))) IA
         WHERE (UPPER(V_ITEM_ID) = 'ALL'      /* 조회조건 ALL 은 조건 없음 */
                OR  A.ITEM_ID LIKE IA.TST)
           /* AS-IS 는 대소문자를 가리지 않는다. 원장 실측상 소문자가 섞인 칸은 사이트뿐이라
              사이트만 칸과 입력값을 함께, 나머지는 입력값만 대문자로 맞춘다 */
           AND (TRIM(V_DIVISION_ID) IS NULL
            OR  UPPER(V_DIVISION_ID) = 'ALL'                     /* 조회조건 ALL 은 조건 없음 */
            OR  A.DIVISION_ID IN (SELECT UPPER(COLUMN_VALUE)
                                    FROM TABLE(STRING_SPLIT(V_DIVISION_ID, ','))))
           AND (TRIM(V_PLAN_GROUP_ID) IS NULL
            OR  UPPER(V_PLAN_GROUP_ID) = 'ALL'                   /* 조회조건 ALL 은 조건 없음 */
            OR  A.OPMZ_PLAN_GR_ID IN (SELECT UPPER(COLUMN_VALUE)
                                        FROM TABLE(STRING_SPLIT(V_PLAN_GROUP_ID, ','))))
           AND (TRIM(V_FROM_SITE_ID) IS NULL
            OR  UPPER(V_FROM_SITE_ID) = 'ALL'                    /* 조회조건 ALL 은 조건 없음 */
            OR  UPPER(A.FROM_STE_ID) IN (SELECT UPPER(COLUMN_VALUE)
                                           FROM TABLE(STRING_SPLIT(V_FROM_SITE_ID, ','))))
           AND (TRIM(V_TO_SITE_ID) IS NULL
            OR  UPPER(V_TO_SITE_ID) = 'ALL'                      /* 조회조건 ALL 은 조건 없음 */
            OR  UPPER(A.TO_STE_ID) IN (SELECT UPPER(COLUMN_VALUE)
                                         FROM TABLE(STRING_SPLIT(V_TO_SITE_ID, ','))))
           AND (TRIM(V_STAGE) IS NULL
            OR  UPPER(V_STAGE) = 'ALL'                           /* 조회조건 ALL 은 조건 없음 */
            OR  A.STAGE IN (SELECT UPPER(COLUMN_VALUE)
                              FROM TABLE(STRING_SPLIT(V_STAGE, ','))))
           AND (TRIM(V_VALID_YN) IS NULL
            OR  UPPER(V_VALID_YN) = 'ALL'                        /* 조회조건 ALL 은 조건 없음 */
            OR  A.VALID_YN IN (SELECT UPPER(COLUMN_VALUE)
                                 FROM TABLE(STRING_SPLIT(V_VALID_YN, ','))))
           AND (TRIM(V_MDL_GR_NM) IS NULL
            OR  UPPER(V_MDL_GR_NM) = 'ALL'                       /* 조회조건 ALL 은 조건 없음 */
            OR  UPPER(A.MDL_GR_NM) IN (SELECT UPPER(COLUMN_VALUE)
                                         FROM TABLE(STRING_SPLIT(V_MDL_GR_NM, ','))))
           AND A.FROM_YYYYMMDD     <= V_TO_YYYYMMDD
           AND A.TO_YYYYMMDD       >= V_FROM_YYYYMMDD
         /* 원문에 정렬이 없어 화면 순서가 흔들린다 — 원장 열쇠 순서와 같게 고정 */
         ORDER BY FN_ASIS_SORT_KEY(A.DIVISION_ID)     NULLS FIRST
                , FN_ASIS_SORT_KEY(A.OPMZ_PLAN_GR_ID) NULLS FIRST
                , FN_ASIS_SORT_KEY(A.MDL_GR_NM)       NULLS FIRST
                , FN_ASIS_SORT_KEY(A.ITEM_ID)         NULLS FIRST;

    OPEN O_RESULT_CURSOR FOR
        SELECT '0'          AS RESULT_CODE
             , 'SUCCESS'    AS RESULT_MESSAGE
          FROM DUAL;

END P_SCP0132_GET_CONSTRAINT_OF_SHIPMENT_QTY;
/****************************************************************************************************/
/* Program ID  : P_SCP0132_SAVE_CONSTRAINT_OF_SHIPMENT_QTY                                          */
/* Description : 출하수량 제약 등록 · 수정 · 삭제                                                   */
/****************************************************************************************************/
PROCEDURE P_SCP0132_SAVE_CONSTRAINT_OF_SHIPMENT_QTY
(
    P_ACTIVE_FLAG       IN  CLOB
  , P_DIVISION_ID       IN  CLOB
  , P_OPMZ_PLAN_GR_ID   IN  CLOB
  , P_MDL_GR_NM         IN  CLOB
  , P_ITEM_ID           IN  CLOB
  , P_STAGE             IN  CLOB
  , P_FROM_STE_ID       IN  CLOB
  , P_TO_STE_ID         IN  CLOB
  , P_FROM_YYYYMMDD     IN  CLOB
  , P_TO_YYYYMMDD       IN  CLOB
  , P_SIPM_MIN_QYT      IN  CLOB
  , P_SIPM_MAX_QTY      IN  CLOB
  , P_SAT_SIPM_MIN_QTY  IN  CLOB
  , P_SAT_SIPM_MAX_QTY  IN  CLOB
  , P_SUN_SIPM_MIN_QTY  IN  CLOB
  , P_SUN_SIPM_MAX_QTY  IN  CLOB
  , P_VAL_TP_CD         IN  CLOB
  , P_VALUE_DESCRIPTION IN  CLOB
  , P_VALID_YN          IN  CLOB
  , P_USER_ID           IN  CLOB
  , P_PRE_DIVISION_ID   IN  CLOB
  , P_PRE_OPMZ_PLAN_GR_ID IN CLOB
  , P_PRE_MDL_GR_NM     IN  CLOB
  , P_PRE_ITEM_ID       IN  CLOB
  , O_RC1               OUT SYS_REFCURSOR
  , O_RESULT_CURSOR     OUT SYS_REFCURSOR
)
IS
    C_DELIMITER         CONSTANT VARCHAR2(1 CHAR) := '^';
    /* 원문은 빈 문자와 견준다. Oracle 에서 빈 문자는 값이 없는 것이라 그대로 두면 판정이 뒤집힌다.
       값이 없을 때 원장 값과 절대 같아지지 않는 글자를 세워 원문과 같게 만든다 */
    C_NOMATCH           CONSTANT VARCHAR2(1 CHAR) := CHR(1);
    C_NULL_VAL          CONSTANT NUMBER           := -99999;   /* 원문의 값 없음 대체 숫자 */

    V_ACTIVE_FLAG       VARCHAR2(4000 CHAR);
    V_DIVISION_ID       VARCHAR2(4000 CHAR);
    V_OPMZ_PLAN_GR_ID   VARCHAR2(4000 CHAR);
    V_MDL_GR_NM         VARCHAR2(4000 CHAR);
    V_ITEM_ID           VARCHAR2(4000 CHAR);
    V_STAGE             VARCHAR2(4000 CHAR);
    V_FROM_STE_ID       VARCHAR2(4000 CHAR);
    V_TO_STE_ID         VARCHAR2(4000 CHAR);
    V_FROM_YYYYMMDD     VARCHAR2(4000 CHAR);
    V_TO_YYYYMMDD       VARCHAR2(4000 CHAR);
    V_VAL_TP_CD         VARCHAR2(4000 CHAR);
    V_VALUE_DESCRIPTION VARCHAR2(4000 CHAR);
    V_VALID_YN          VARCHAR2(4000 CHAR);
    V_LAST_UPDATED_BY   VARCHAR2(4000 CHAR) := TO_CHAR(SUBSTR(P_USER_ID, 1, 4000));

    /* 수량 칸은 숫자로 바꿔 쓴다 */
    V_N_SIPM_MIN_QYT        NUMBER(18);
    V_N_SIPM_MAX_QTY        NUMBER(18);
    V_N_SAT_SIPM_MIN_QTY    NUMBER(18);
    V_N_SAT_SIPM_MAX_QTY    NUMBER(18);
    V_N_SUN_SIPM_MIN_QTY    NUMBER(18);
    V_N_SUN_SIPM_MAX_QTY    NUMBER(18);

    V_PRE_DIVISION_ID   VARCHAR2(4000 CHAR);
    V_PRE_PLAN_GR_ID    VARCHAR2(4000 CHAR);
    V_PRE_MDL_GR_NM     VARCHAR2(4000 CHAR);
    V_PRE_ITEM_ID       VARCHAR2(4000 CHAR);

    V_MAX_LOOP_CNT      NUMBER(10) := 0;
    V_MST_LOOP_CNT      NUMBER(10) := 0;
    V_CNT               NUMBER(10) := 0;
    V_CNT_SUB           NUMBER(10) := 0;

    V_PROGRAM_NAME      VARCHAR2(150 CHAR) := 'SCP0132_SAVE_CONSTRAINT_OF_SHIPMENT_QTY';
    V_LOG_TYPE          VARCHAR2(30 CHAR);
    N_LOG_COUNT         NUMBER(10) := 0;
    V_LOG_MESSAGE       VARCHAR2(1000 CHAR);
    V_DESCRIPTION       VARCHAR2(500 CHAR);
    D_EVENT_DATE        DATE;
    V_SQLERRM           VARCHAR2(4000 CHAR);
BEGIN

    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    V_MAX_LOOP_CNT := SCM_ARR_SPL_CNT(P_ACTIVE_FLAG, C_DELIMITER);

    WHILE LENGTH(P_ACTIVE_FLAG) > 0
      AND V_MST_LOOP_CNT < V_MAX_LOOP_CNT
    LOOP

        V_MST_LOOP_CNT      := V_MST_LOOP_CNT + 1;

        V_ACTIVE_FLAG       := SCM_ARR_SPL_VAL(P_ACTIVE_FLAG,         C_DELIMITER, V_MST_LOOP_CNT);
        V_DIVISION_ID       := SCM_ARR_SPL_VAL(P_DIVISION_ID,         C_DELIMITER, V_MST_LOOP_CNT);
        V_OPMZ_PLAN_GR_ID   := SCM_ARR_SPL_VAL(P_OPMZ_PLAN_GR_ID,     C_DELIMITER, V_MST_LOOP_CNT);
        V_MDL_GR_NM         := SCM_ARR_SPL_VAL(P_MDL_GR_NM,           C_DELIMITER, V_MST_LOOP_CNT);
        V_ITEM_ID           := SCM_ARR_SPL_VAL(P_ITEM_ID,             C_DELIMITER, V_MST_LOOP_CNT);
        V_STAGE             := SCM_ARR_SPL_VAL(P_STAGE,               C_DELIMITER, V_MST_LOOP_CNT);
        V_FROM_STE_ID       := SCM_ARR_SPL_VAL(P_FROM_STE_ID,         C_DELIMITER, V_MST_LOOP_CNT);
        V_TO_STE_ID         := SCM_ARR_SPL_VAL(P_TO_STE_ID,           C_DELIMITER, V_MST_LOOP_CNT);
        V_FROM_YYYYMMDD     := SCM_ARR_SPL_VAL(P_FROM_YYYYMMDD,       C_DELIMITER, V_MST_LOOP_CNT);
        V_TO_YYYYMMDD       := SCM_ARR_SPL_VAL(P_TO_YYYYMMDD,         C_DELIMITER, V_MST_LOOP_CNT);
        V_VALUE_DESCRIPTION := SCM_ARR_SPL_VAL(P_VALUE_DESCRIPTION,   C_DELIMITER, V_MST_LOOP_CNT);
        V_VALID_YN          := SCM_ARR_SPL_VAL(P_VALID_YN,            C_DELIMITER, V_MST_LOOP_CNT);

        V_PRE_DIVISION_ID   := SCM_ARR_SPL_VAL(P_PRE_DIVISION_ID,     C_DELIMITER, V_MST_LOOP_CNT);
        V_PRE_PLAN_GR_ID    := SCM_ARR_SPL_VAL(P_PRE_OPMZ_PLAN_GR_ID, C_DELIMITER, V_MST_LOOP_CNT);
        V_PRE_MDL_GR_NM     := SCM_ARR_SPL_VAL(P_PRE_MDL_GR_NM,       C_DELIMITER, V_MST_LOOP_CNT);
        V_PRE_ITEM_ID       := SCM_ARR_SPL_VAL(P_PRE_ITEM_ID,         C_DELIMITER, V_MST_LOOP_CNT);

        /* ★수량 칸을 숫자로 바꾼다. 원문은 빈 값이 오면 여기서 오류를 내지만,
              원장이 값 없음을 허용하고 아래 구분 판정도 값 없음을 전제로 하므로 값 없음으로 둔다 */
        V_N_SIPM_MIN_QYT     := TO_NUMBER(SCM_ARR_SPL_VAL(P_SIPM_MIN_QYT,     C_DELIMITER, V_MST_LOOP_CNT));
        V_N_SIPM_MAX_QTY     := TO_NUMBER(SCM_ARR_SPL_VAL(P_SIPM_MAX_QTY,     C_DELIMITER, V_MST_LOOP_CNT));
        V_N_SAT_SIPM_MIN_QTY := TO_NUMBER(SCM_ARR_SPL_VAL(P_SAT_SIPM_MIN_QTY, C_DELIMITER, V_MST_LOOP_CNT));
        V_N_SAT_SIPM_MAX_QTY := TO_NUMBER(SCM_ARR_SPL_VAL(P_SAT_SIPM_MAX_QTY, C_DELIMITER, V_MST_LOOP_CNT));
        V_N_SUN_SIPM_MIN_QTY := TO_NUMBER(SCM_ARR_SPL_VAL(P_SUN_SIPM_MIN_QTY, C_DELIMITER, V_MST_LOOP_CNT));
        V_N_SUN_SIPM_MAX_QTY := TO_NUMBER(SCM_ARR_SPL_VAL(P_SUN_SIPM_MAX_QTY, C_DELIMITER, V_MST_LOOP_CNT));

        /* 삭제가 아닌 경우 확인 */
        IF V_ACTIVE_FLAG <> 'D'
        THEN

            /***** 중복체크 *****/
            /* 1. 열쇠 중복 확인 */
            SELECT COUNT(*)
              INTO V_CNT
              FROM SCP_OPMZ_CONSTRAINT_OF_SHIPMENT_QTY
             WHERE DIVISION_ID     = V_DIVISION_ID
               AND OPMZ_PLAN_GR_ID = V_OPMZ_PLAN_GR_ID
               AND MDL_GR_NM       = V_MDL_GR_NM
               AND ITEM_ID         = V_ITEM_ID
               AND NOT (
                            DIVISION_ID     = NVL(V_PRE_DIVISION_ID, C_NOMATCH)
                        AND OPMZ_PLAN_GR_ID = NVL(V_PRE_PLAN_GR_ID,  C_NOMATCH)
                        AND MDL_GR_NM       = NVL(V_PRE_MDL_GR_NM,   C_NOMATCH)
                        AND ITEM_ID         = NVL(V_PRE_ITEM_ID,     C_NOMATCH)
                       );

            IF V_CNT > 0
            THEN
                RAISE_APPLICATION_ERROR(-20010, ' 신규 입력 데이터 중 중복된 데이터가 있습니다.');
            END IF;

            /* 2. 값 일치 확인
                  열쇠(사업부 · 계획그룹 · 모델그룹)가 같으면 나머지 값도 같아야 한다.
                  단 사용 중인 행에 한한다 */
            IF V_ACTIVE_FLAG = 'I'
            THEN

                SELECT COUNT(*)
                  INTO V_CNT
                  FROM SCP_OPMZ_CONSTRAINT_OF_SHIPMENT_QTY
                 WHERE DIVISION_ID     = V_DIVISION_ID
                   AND OPMZ_PLAN_GR_ID = V_OPMZ_PLAN_GR_ID
                   AND MDL_GR_NM       = V_MDL_GR_NM
                   AND VALID_YN        = 'Y';

                IF V_CNT > 0
                THEN

                    SELECT COUNT(*)
                      INTO V_CNT_SUB
                      FROM SCP_OPMZ_CONSTRAINT_OF_SHIPMENT_QTY
                     WHERE DIVISION_ID     = V_DIVISION_ID
                       AND OPMZ_PLAN_GR_ID = V_OPMZ_PLAN_GR_ID
                       AND MDL_GR_NM       = V_MDL_GR_NM
                       AND STAGE           = V_STAGE
                       AND FROM_STE_ID     = V_FROM_STE_ID
                       AND TO_STE_ID       = V_TO_STE_ID
                       AND FROM_YYYYMMDD   = V_FROM_YYYYMMDD
                       AND TO_YYYYMMDD     = V_TO_YYYYMMDD
                       AND NVL(SIPM_MIN_QYT,     C_NULL_VAL) = NVL(V_N_SIPM_MIN_QYT,     C_NULL_VAL)
                       AND NVL(SIPM_MAX_QTY,     C_NULL_VAL) = NVL(V_N_SIPM_MAX_QTY,     C_NULL_VAL)
                       AND NVL(SAT_SIPM_MIN_QTY, C_NULL_VAL) = NVL(V_N_SAT_SIPM_MIN_QTY, C_NULL_VAL)
                       AND NVL(SAT_SIPM_MAX_QTY, C_NULL_VAL) = NVL(V_N_SAT_SIPM_MAX_QTY, C_NULL_VAL)
                       AND NVL(SUN_SIPM_MIN_QTY, C_NULL_VAL) = NVL(V_N_SUN_SIPM_MIN_QTY, C_NULL_VAL)
                       AND NVL(SUN_SIPM_MAX_QTY, C_NULL_VAL) = NVL(V_N_SUN_SIPM_MAX_QTY, C_NULL_VAL)
                       AND VALID_YN        = 'Y';

                    IF V_CNT_SUB <> V_CNT
                   AND V_CNT_SUB <> 0
                    THEN
                        RAISE_APPLICATION_ERROR(-20010, ' 입력한 데이타의 값이 일치하지 않는 데이타가 있습니다.');
                    END IF;

                END IF;

            END IF;
            /***** 중복체크 *****/

            /** TYPE 체크  **/
            IF V_N_SAT_SIPM_MIN_QTY IS NULL
           AND V_N_SAT_SIPM_MAX_QTY IS NULL
           AND V_N_SUN_SIPM_MIN_QTY IS NULL
           AND V_N_SUN_SIPM_MAX_QTY IS NULL
            THEN
                V_VAL_TP_CD := 'A';
            ELSE
                V_VAL_TP_CD := 'B';
            END IF;
            /** tYPE 체크 END  **/

        END IF;

        IF V_ACTIVE_FLAG = 'I'
        THEN

            INSERT INTO SCP_OPMZ_CONSTRAINT_OF_SHIPMENT_QTY
                        (
                          DIVISION_ID
                        , OPMZ_PLAN_GR_ID
                        , MDL_GR_NM
                        , ITEM_ID
                        , STAGE
                        , FROM_STE_ID
                        , TO_STE_ID
                        , FROM_YYYYMMDD
                        , TO_YYYYMMDD
                        , SIPM_MIN_QYT
                        , SIPM_MAX_QTY
                        , SAT_SIPM_MIN_QTY
                        , SAT_SIPM_MAX_QTY
                        , SUN_SIPM_MIN_QTY
                        , SUN_SIPM_MAX_QTY
                        , VAL_TP_CD
                        , VALUE_DESCRIPTION
                        , VALID_YN
                        , CREATED_BY
                        , CREATION_DATE
                        , LAST_UPDATED_BY
                        , LAST_UPDATE_DATE
                        )
                 VALUES (
                          V_DIVISION_ID
                        , V_OPMZ_PLAN_GR_ID
                        , V_MDL_GR_NM
                        , V_ITEM_ID
                        , V_STAGE
                        , V_FROM_STE_ID
                        , V_TO_STE_ID
                        , V_FROM_YYYYMMDD
                        , V_TO_YYYYMMDD
                        , V_N_SIPM_MIN_QYT
                        , V_N_SIPM_MAX_QTY
                        , V_N_SAT_SIPM_MIN_QTY
                        , V_N_SAT_SIPM_MAX_QTY
                        , V_N_SUN_SIPM_MIN_QTY
                        , V_N_SUN_SIPM_MAX_QTY
                        , V_VAL_TP_CD
                        , V_VALUE_DESCRIPTION
                        , V_VALID_YN
                        , V_LAST_UPDATED_BY
                        , SYSDATE
                        , V_LAST_UPDATED_BY
                        , SYSDATE
                        );

        ELSIF V_ACTIVE_FLAG = 'M'
        THEN

            /* 1. 개별 수정 */
            UPDATE SCP_OPMZ_CONSTRAINT_OF_SHIPMENT_QTY
               SET DIVISION_ID       = V_DIVISION_ID
                 , OPMZ_PLAN_GR_ID   = V_OPMZ_PLAN_GR_ID
                 , MDL_GR_NM         = V_MDL_GR_NM
                 , ITEM_ID           = V_ITEM_ID
                 , STAGE             = V_STAGE
                 , FROM_STE_ID       = V_FROM_STE_ID
                 , TO_STE_ID         = V_TO_STE_ID
                 , FROM_YYYYMMDD     = V_FROM_YYYYMMDD
                 , TO_YYYYMMDD       = V_TO_YYYYMMDD
                 , SIPM_MIN_QYT      = V_N_SIPM_MIN_QYT
                 , SIPM_MAX_QTY      = V_N_SIPM_MAX_QTY
                 , SAT_SIPM_MIN_QTY  = V_N_SAT_SIPM_MIN_QTY
                 , SAT_SIPM_MAX_QTY  = V_N_SAT_SIPM_MAX_QTY
                 , SUN_SIPM_MIN_QTY  = V_N_SUN_SIPM_MIN_QTY
                 , SUN_SIPM_MAX_QTY  = V_N_SUN_SIPM_MAX_QTY
                 , VAL_TP_CD         = V_VAL_TP_CD
                 , VALUE_DESCRIPTION = V_VALUE_DESCRIPTION
                 , VALID_YN          = V_VALID_YN
                 , LAST_UPDATED_BY   = V_LAST_UPDATED_BY
                 , LAST_UPDATE_DATE  = SYSDATE
             WHERE DIVISION_ID       = NVL(V_PRE_DIVISION_ID, C_NOMATCH)
               AND OPMZ_PLAN_GR_ID   = NVL(V_PRE_PLAN_GR_ID,  C_NOMATCH)
               AND MDL_GR_NM         = NVL(V_PRE_MDL_GR_NM,   C_NOMATCH)
               AND ITEM_ID           = NVL(V_PRE_ITEM_ID,     C_NOMATCH);

            /* 2. ★같은 모델 그룹에서 사용 중인 행을 한꺼번에 맞춘다(열쇠와 설명 · 사용여부는 두고).
                  한 줄을 고치면 같은 모델 그룹의 다른 줄도 함께 바뀐다 */
            UPDATE SCP_OPMZ_CONSTRAINT_OF_SHIPMENT_QTY
               SET STAGE             = V_STAGE
                 , FROM_STE_ID       = V_FROM_STE_ID
                 , TO_STE_ID         = V_TO_STE_ID
                 , FROM_YYYYMMDD     = V_FROM_YYYYMMDD
                 , TO_YYYYMMDD       = V_TO_YYYYMMDD
                 , SIPM_MIN_QYT      = V_N_SIPM_MIN_QYT
                 , SIPM_MAX_QTY      = V_N_SIPM_MAX_QTY
                 , SAT_SIPM_MIN_QTY  = V_N_SAT_SIPM_MIN_QTY
                 , SAT_SIPM_MAX_QTY  = V_N_SAT_SIPM_MAX_QTY
                 , SUN_SIPM_MIN_QTY  = V_N_SUN_SIPM_MIN_QTY
                 , SUN_SIPM_MAX_QTY  = V_N_SUN_SIPM_MAX_QTY
                 , VAL_TP_CD         = V_VAL_TP_CD
                 /* , VALUE_DESCRIPTION = V_VALUE_DESCRIPTION */
                 /* , VALID_YN          = V_VALID_YN */
                 , LAST_UPDATED_BY   = V_LAST_UPDATED_BY
                 , LAST_UPDATE_DATE  = SYSDATE
             WHERE DIVISION_ID       = V_DIVISION_ID
               AND OPMZ_PLAN_GR_ID   = V_OPMZ_PLAN_GR_ID
               AND MDL_GR_NM         = V_MDL_GR_NM
               AND VALID_YN          = 'Y';

        ELSIF V_ACTIVE_FLAG = 'D'                               /* 삭제기능 추가 (2025-07-16) */
        THEN

            DELETE FROM SCP_OPMZ_CONSTRAINT_OF_SHIPMENT_QTY
             WHERE DIVISION_ID       = NVL(V_PRE_DIVISION_ID, C_NOMATCH)
               AND OPMZ_PLAN_GR_ID   = NVL(V_PRE_PLAN_GR_ID,  C_NOMATCH)
               AND MDL_GR_NM         = NVL(V_PRE_MDL_GR_NM,   C_NOMATCH)
               AND ITEM_ID           = NVL(V_PRE_ITEM_ID,     C_NOMATCH);

        END IF;

    END LOOP;

    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    COMMIT;

    OPEN O_RC1 FOR
        SELECT 'S'              AS RESULT_CODE
             , V_MAX_LOOP_CNT   AS RESULT_CNT
          FROM DUAL;

    OPEN O_RESULT_CURSOR FOR
        SELECT '0'          AS RESULT_CODE
             , 'SUCCESS'    AS RESULT_MESSAGE
          FROM DUAL;

EXCEPTION
    WHEN OTHERS THEN
        V_SQLERRM := SQLERRM;

        ROLLBACK;

        INSERT INTO SCM_SYS_LOG_BATCH
                    (
                      PROGRAM_NAME, LOG_TYPE, LOG_COUNT, LOG_MESSAGE, DESCRIPTION
                    , EVENT_DATE, CREATION_DATE, CREATED_BY, LAST_UPDATE_DATE, LAST_UPDATED_BY
                    )
             VALUES (
                      V_PROGRAM_NAME, 'ERROR', NULL, V_SQLERRM, NULL
                    , SYSDATE, SYSDATE, V_PROGRAM_NAME, SYSDATE, V_PROGRAM_NAME
                    );

        COMMIT;

        OPEN O_RC1 FOR
            SELECT 'F'                          AS RESULT_CODE
                 , SUBSTR(V_SQLERRM, 1, 4000)   AS RESULT_CNT
              FROM DUAL;

        OPEN O_RESULT_CURSOR FOR
            SELECT '1'                          AS RESULT_CODE
                 , SUBSTR(V_SQLERRM, 1, 4000)   AS RESULT_MESSAGE
              FROM DUAL;

END P_SCP0132_SAVE_CONSTRAINT_OF_SHIPMENT_QTY;

END PKG_SCP0132;

PACKAGE BODY           "PKG_SEND_MAIL" 
IS
    -- 패키지 내부 상수
    C_SMTP_HOST  CONSTANT VARCHAR2(256) := 'mailrelay.lgensol.com';
    C_SMTP_PORT  CONSTANT NUMBER       := 25;
    C_CRLF       CONSTANT VARCHAR2(2)  := CHR(13) || CHR(10);

    /*===========================================
      [내부] 세미콜론 -> 콤마 통일 함수
      - 모든 프로시저에서 공통 사용
    ===========================================*/
    FUNCTION F_NORMALIZE_DELIM (
        p_str IN VARCHAR2
    ) RETURN VARCHAR2
    IS
    BEGIN
        IF p_str IS NULL THEN
            RETURN NULL;
        END IF;
        RETURN REPLACE(p_str, ';', ',');
    END F_NORMALIZE_DELIM;

    FUNCTION F_ENC_SUBJECT (
        p_subject IN VARCHAR2
    ) RETURN VARCHAR2
    IS
        C_MAXB CONSTANT PLS_INTEGER := 45;
        v_out  VARCHAR2(4000);
        v_buf  VARCHAR2(400);
        v_ch   VARCHAR2(4);

        PROCEDURE flush_buf IS
        BEGIN
            IF v_buf IS NULL THEN
                RETURN;
            END IF;
            v_out := v_out
                  || CASE WHEN v_out IS NULL THEN NULL ELSE C_CRLF || ' ' END
                  || '=?UTF-8?B?'
                  || REPLACE(REPLACE(UTL_RAW.CAST_TO_VARCHAR2(
                         UTL_ENCODE.BASE64_ENCODE(UTL_RAW.CAST_TO_RAW(v_buf))),
                         CHR(13), ''), CHR(10), '')
                  || '?=';
            v_buf := NULL;
        END flush_buf;
    BEGIN
        IF p_subject IS NULL THEN
            RETURN NULL;
        END IF;

        FOR i IN 1 .. LENGTH(p_subject) LOOP
            v_ch := SUBSTR(p_subject, i, 1);
            IF LENGTHB(v_buf || v_ch) > C_MAXB THEN
                flush_buf;
            END IF;
            v_buf := v_buf || v_ch;
        END LOOP;
        flush_buf;

        RETURN v_out;
    END F_ENC_SUBJECT;

    /*===========================================
      메일 주소 유효성 검증 (단일)
    ===========================================*/
    FUNCTION F_VALIDATE_EMAIL (
        p_email IN VARCHAR2
    ) RETURN VARCHAR2
    IS
    BEGIN
        IF p_email IS NULL THEN
            RETURN 'N';
        END IF;

        IF REGEXP_LIKE(TRIM(p_email), '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$') THEN
            RETURN 'Y';
        ELSE
            RETURN 'N';
        END IF;
    END F_VALIDATE_EMAIL;

    /*===========================================
      다중 메일 주소 유효성 검증 (콤마/세미콜론 구분)
      - 하나라도 유효하지 않으면 'N' 리턴
    ===========================================*/
    FUNCTION F_VALIDATE_EMAIL_LIST (
        p_email_list IN VARCHAR2
    ) RETURN VARCHAR2
    IS
        v_list  VARCHAR2(4000);
        v_addr  VARCHAR2(500);
        v_pos   NUMBER;
    BEGIN
        IF p_email_list IS NULL THEN
            RETURN 'N';
        END IF;

        -- 세미콜론 -> 콤마 통일
        v_list := F_NORMALIZE_DELIM(p_email_list) || ',';

        LOOP
            v_pos := INSTR(v_list, ',');
            EXIT WHEN NVL(v_pos, 0) = 0;
            v_addr := TRIM(SUBSTR(v_list, 1, v_pos - 1));
            IF v_addr IS NOT NULL AND F_VALIDATE_EMAIL(v_addr) = 'N' THEN
                RETURN 'N';
            END IF;
            v_list := SUBSTR(v_list, v_pos + 1);
        END LOOP;

        RETURN 'Y';
    END F_VALIDATE_EMAIL_LIST;

    /*===========================================
      메일 발송 로그 기록 (AUTONOMOUS_TRANSACTION)
    ===========================================*/
    PROCEDURE P_LOG_MAIL (
        p_to_mail    IN VARCHAR2,
        p_subject    IN VARCHAR2,
        p_status     IN VARCHAR2,
        p_error_msg  IN VARCHAR2 DEFAULT NULL,
        p_mail_type  IN VARCHAR2 DEFAULT 'BASIC',
        p_sender     IN VARCHAR2 DEFAULT NULL,
        p_cc_mail    IN VARCHAR2 DEFAULT NULL,
        p_bcc_mail   IN VARCHAR2 DEFAULT NULL
    )
    IS
        PRAGMA AUTONOMOUS_TRANSACTION;
    BEGIN
        INSERT INTO TB_MAIL_LOG (
            LOG_SEQ, TO_MAIL, CC_MAIL, BCC_MAIL,
            SUBJECT, STATUS, ERROR_MSG, MAIL_TYPE,
            SENDER, SEND_DATE, REG_ID, REG_DATE
        ) VALUES (
            SEQ1_MAIL_LOG.NEXTVAL, p_to_mail, p_cc_mail, p_bcc_mail,
            p_subject, p_status, p_error_msg, p_mail_type,
            p_sender, SYSDATE, USER, SYSDATE
        );
        COMMIT;
    EXCEPTION
        WHEN OTHERS THEN
            ROLLBACK;
    END P_LOG_MAIL;

    /*===========================================
      기본 메일 발송
      - UTL_MAIL 사용
      - 다중 수신자: 콤마/세미콜론 구분 자동 지원
    ===========================================*/
    PROCEDURE P_SEND_MAIL (
        p_to_mail        IN VARCHAR2,
        p_subject        IN VARCHAR2,
        p_body_contents  IN VARCHAR2,
        p_html_yn        IN VARCHAR2 DEFAULT 'N',
        p_sender         IN VARCHAR2 DEFAULT 'scmpi@lgensol.com',
        p_cc_mail        IN VARCHAR2 DEFAULT NULL,
        p_bcc_mail       IN VARCHAR2 DEFAULT NULL
    )
    IS
        v_mime_type VARCHAR2(100);
        v_to_mail   VARCHAR2(4000);
        v_cc_mail   VARCHAR2(4000);
        v_bcc_mail  VARCHAR2(4000);
    BEGIN
        -- 구분자 통일 (세미콜론 -> 콤마)
        v_to_mail  := F_NORMALIZE_DELIM(p_to_mail);
        v_cc_mail  := F_NORMALIZE_DELIM(p_cc_mail);
        v_bcc_mail := F_NORMALIZE_DELIM(p_bcc_mail);

        -- 수신자 유효성 체크
        IF v_to_mail IS NULL THEN
            P_LOG_MAIL(v_to_mail, p_subject, 'FAIL', '수신자 없음', 'BASIC', p_sender);
            RETURN;
        END IF;

        IF (p_html_yn = 'Y') THEN
            v_mime_type := 'text/html; charset=UTF-8';
        ELSE
            v_mime_type := 'text/plain; charset=UTF-8';
        END IF;

        /* 메일 발송 주석 처리. 홍성대 2026.08.18 */
        /*UTL_MAIL.SEND(
            sender     => p_sender,
            recipients => v_to_mail,
            cc         => v_cc_mail,
            bcc        => v_bcc_mail,
            subject    => p_subject,
            message    => p_body_contents,
            mime_type  => v_mime_type
        );*/

        P_LOG_MAIL(v_to_mail, p_subject, 'SUCCESS', NULL, 'BASIC', p_sender, v_cc_mail, v_bcc_mail);

    EXCEPTION
        WHEN OTHERS THEN
            P_LOG_MAIL(v_to_mail, p_subject, 'FAIL', SQLERRM, 'BASIC', p_sender, v_cc_mail, v_bcc_mail);
            RAISE;
    END P_SEND_MAIL;

    /*===========================================
      첨부파일 포함 메일 발송
      - UTL_MAIL.SEND_ATTACH_RAW 사용
    ===========================================*/
    PROCEDURE P_SEND_MAIL_ATTACH (
        p_to_mail        IN VARCHAR2,
        p_subject        IN VARCHAR2,
        p_body_contents  IN VARCHAR2,
        p_attach_data    IN RAW,
        p_attach_name    IN VARCHAR2,
        p_attach_mime    IN VARCHAR2 DEFAULT 'application/octet-stream',
        p_html_yn        IN VARCHAR2 DEFAULT 'N',
        p_sender         IN VARCHAR2 DEFAULT 'scmpi@lgensol.com',
        p_cc_mail        IN VARCHAR2 DEFAULT NULL
    )
    IS
        v_mime_type VARCHAR2(100);
        v_to_mail   VARCHAR2(4000);
        v_cc_mail   VARCHAR2(4000);
    BEGIN
        -- 구분자 통일 (세미콜론 -> 콤마)
        v_to_mail := F_NORMALIZE_DELIM(p_to_mail);
        v_cc_mail := F_NORMALIZE_DELIM(p_cc_mail);

        IF v_to_mail IS NULL THEN
            P_LOG_MAIL(v_to_mail, p_subject, 'FAIL', '수신자 없음', 'ATTACH', p_sender);
            RETURN;
        END IF;

        IF (p_html_yn = 'Y') THEN
            v_mime_type := 'text/html; charset=UTF-8';
        ELSE
            v_mime_type := 'text/plain; charset=UTF-8';
        END IF;

        /* 메일 발송 주석 처리. 홍성대 2026.08.18 */
        /*UTL_MAIL.SEND_ATTACH_RAW(
            sender        => p_sender,
            recipients    => v_to_mail,
            cc            => v_cc_mail,
            subject       => p_subject,
            message       => p_body_contents,
            mime_type     => v_mime_type,
            attachment    => p_attach_data,
            att_inline    => FALSE,
            att_mime_type => p_attach_mime,
            att_filename  => p_attach_name
        );*/

        P_LOG_MAIL(v_to_mail, p_subject, 'SUCCESS', NULL, 'ATTACH', p_sender, v_cc_mail);

    EXCEPTION
        WHEN OTHERS THEN
            P_LOG_MAIL(v_to_mail, p_subject, 'FAIL', SQLERRM, 'ATTACH', p_sender, v_cc_mail);
            RAISE;
    END P_SEND_MAIL_ATTACH;

    /*===========================================
      CLOB 본문 메일 발송 (32KB 초과)
      - UTL_SMTP 사용 (UTL_MAIL 32KB 제한)
      - 다중 수신자 지원 (콤마/세미콜론 구분)
      - CC 지원
    ===========================================*/
    PROCEDURE P_SEND_MAIL_CLOB (
        p_to_mail        IN VARCHAR2,
        p_subject        IN VARCHAR2,
        p_body_clob      IN CLOB,
        p_html_yn        IN VARCHAR2 DEFAULT 'N',
        p_sender         IN VARCHAR2 DEFAULT 'scmpi@lgensol.com',
        p_cc_mail        IN VARCHAR2 DEFAULT NULL
    )
    IS
        v_connection  UTL_SMTP.CONNECTION;
        v_mime_type   VARCHAR2(100);
        v_offset      INTEGER := 1;
        v_chunk_size  INTEGER := 4000;
        v_length      INTEGER;
        v_to_mail     VARCHAR2(4000);
        v_cc_mail     VARCHAR2(4000);
        v_list        VARCHAR2(4000);
        v_addr        VARCHAR2(500);
        v_pos         NUMBER;
        v_body_blob   BLOB;
        v_destoff     INTEGER := 1;
        v_srcoff      INTEGER := 1;
        v_lang        INTEGER := 0;
        v_warn        INTEGER;
        v_bp          INTEGER;
    BEGIN
        -- 구분자 통일 (세미콜론 -> 콤마)
        v_to_mail := F_NORMALIZE_DELIM(p_to_mail);
        v_cc_mail := F_NORMALIZE_DELIM(p_cc_mail);

        /* 메일 발송 주석 처리. 홍성대 2026.08.18 */
        RETURN;

        IF v_to_mail IS NULL THEN
            P_LOG_MAIL(v_to_mail, p_subject, 'FAIL', '수신자 없음', 'CLOB', p_sender);
            RETURN;
        END IF;

        IF (p_html_yn = 'Y') THEN
            v_mime_type := 'text/html; charset=UTF-8';
        ELSE
            v_mime_type := 'text/plain; charset=UTF-8';
        END IF;

        -- SMTP 연결
        v_connection := UTL_SMTP.OPEN_CONNECTION(C_SMTP_HOST, C_SMTP_PORT);
        UTL_SMTP.HELO(v_connection, C_SMTP_HOST);
        UTL_SMTP.MAIL(v_connection, p_sender);

        -- TO: 다중 수신자 처리
        v_list := v_to_mail || ',';
        LOOP
            v_pos := INSTR(v_list, ',');
            EXIT WHEN NVL(v_pos, 0) = 0;
            v_addr := TRIM(SUBSTR(v_list, 1, v_pos - 1));
            IF v_addr IS NOT NULL THEN
                UTL_SMTP.RCPT(v_connection, v_addr);
            END IF;
            v_list := SUBSTR(v_list, v_pos + 1);
        END LOOP;

        -- CC: 다중 수신자 처리
        IF v_cc_mail IS NOT NULL THEN
            v_list := v_cc_mail || ',';
            LOOP
                v_pos := INSTR(v_list, ',');
                EXIT WHEN NVL(v_pos, 0) = 0;
                v_addr := TRIM(SUBSTR(v_list, 1, v_pos - 1));
                IF v_addr IS NOT NULL THEN
                    UTL_SMTP.RCPT(v_connection, v_addr);
                END IF;
                v_list := SUBSTR(v_list, v_pos + 1);
            END LOOP;
        END IF;

        -- 헤더 작성
        UTL_SMTP.OPEN_DATA(v_connection);
        UTL_SMTP.WRITE_DATA(v_connection, 'From: '            || p_sender   || C_CRLF);
        UTL_SMTP.WRITE_DATA(v_connection, 'To: '              || v_to_mail  || C_CRLF);
        IF v_cc_mail IS NOT NULL THEN
            UTL_SMTP.WRITE_DATA(v_connection, 'Cc: '          || v_cc_mail  || C_CRLF);
        END IF;
        UTL_SMTP.WRITE_DATA(v_connection, 'Subject: ' || F_ENC_SUBJECT(p_subject) || C_CRLF);
        UTL_SMTP.WRITE_DATA(v_connection, 'MIME-Version: 1.0'              || C_CRLF);
        UTL_SMTP.WRITE_DATA(v_connection, 'Content-Type: '    || v_mime_type || C_CRLF);
        UTL_SMTP.WRITE_DATA(v_connection, 'Content-Transfer-Encoding: base64' || C_CRLF);
        UTL_SMTP.WRITE_DATA(v_connection, C_CRLF);

        -- CLOB 본문을 청크 단위로 전송
        DBMS_LOB.CREATETEMPORARY(v_body_blob, TRUE);
        IF p_body_clob IS NOT NULL AND DBMS_LOB.GETLENGTH(p_body_clob) > 0 THEN
            DBMS_LOB.CONVERTTOBLOB(v_body_blob, p_body_clob, DBMS_LOB.LOBMAXSIZE,
                                   v_destoff, v_srcoff, NLS_CHARSET_ID('AL32UTF8'),
                                   v_lang, v_warn);
        END IF;

        v_length := DBMS_LOB.GETLENGTH(v_body_blob);
        v_bp := 1;
        WHILE v_bp <= v_length LOOP
            UTL_SMTP.WRITE_RAW_DATA(v_connection,
                UTL_ENCODE.BASE64_ENCODE(DBMS_LOB.SUBSTR(v_body_blob, 48, v_bp)));
            UTL_SMTP.WRITE_DATA(v_connection, C_CRLF);
            v_bp := v_bp + 48;
        END LOOP;

        IF DBMS_LOB.ISTEMPORARY(v_body_blob) = 1 THEN
            DBMS_LOB.FREETEMPORARY(v_body_blob);
        END IF;

        UTL_SMTP.CLOSE_DATA(v_connection);
        UTL_SMTP.QUIT(v_connection);

        P_LOG_MAIL(v_to_mail, p_subject, 'SUCCESS', NULL, 'CLOB', p_sender, v_cc_mail);

    EXCEPTION
        WHEN OTHERS THEN
            P_LOG_MAIL(v_to_mail, p_subject, 'FAIL', SQLERRM, 'CLOB', p_sender, v_cc_mail);
            BEGIN
                UTL_SMTP.QUIT(v_connection);
            EXCEPTION
                WHEN OTHERS THEN NULL;
            END;
            RAISE;
    END P_SEND_MAIL_CLOB;

    /*===========================================
      대용량 첨부 메일 발송 (파일 없이 CLOB -> UTL_SMTP MIME/Base64)
      - UTL_MAIL 32KB 제한 없음
      - 첨부 CLOB을 UTF-8(+BOM) Base64 로 MIME 첨부
      - 본문/제목 한글 안전(UTF-8 base64)
    ===========================================*/
    PROCEDURE P_SEND_MAIL_CLOB_ATTACH (
        p_to_mail        IN VARCHAR2,
        p_subject        IN VARCHAR2,
        p_body_contents  IN VARCHAR2,
        p_attach_clob    IN CLOB,
        p_attach_name    IN VARCHAR2,
        p_attach_mime    IN VARCHAR2 DEFAULT 'text/csv; charset=UTF-8',
        p_sender         IN VARCHAR2 DEFAULT 'scmpi@lgensol.com',
        p_cc_mail        IN VARCHAR2 DEFAULT NULL,
        p_add_bom        IN VARCHAR2 DEFAULT 'Y'
    )
    IS
        C_BND   CONSTANT VARCHAR2(60) := '====NSCM_MIME_BOUNDARY_8f3a2c====';
        C_STEP  CONSTANT PLS_INTEGER  := 48;   -- 48B -> 64 base64 chars/line
        v_conn      UTL_SMTP.CONNECTION;
        v_to_mail   VARCHAR2(4000);
        v_cc_mail   VARCHAR2(4000);
        v_blob      BLOB;
        v_body_blob BLOB;
        v_destoff   INTEGER := 1;
        v_srcoff    INTEGER := 1;
        v_lang      INTEGER := 0;
        v_warn      INTEGER;
        v_l         INTEGER;
        v_p         INTEGER;

        PROCEDURE rcpt_all(p IN VARCHAR2) IS
            v_s VARCHAR2(4000) := F_NORMALIZE_DELIM(p) || ',';
            v_i NUMBER;
            v_a VARCHAR2(500);
        BEGIN
            LOOP
                v_i := INSTR(v_s, ',');
                EXIT WHEN NVL(v_i, 0) = 0;
                v_a := TRIM(SUBSTR(v_s, 1, v_i - 1));
                IF v_a IS NOT NULL THEN UTL_SMTP.RCPT(v_conn, v_a); END IF;
                v_s := SUBSTR(v_s, v_i + 1);
            END LOOP;
        END;
    BEGIN
        v_to_mail := F_NORMALIZE_DELIM(p_to_mail);
        v_cc_mail := F_NORMALIZE_DELIM(p_cc_mail);

        /* 메일 발송 주석 처리. 홍성대 2026.08.18 */
        RETURN;

        IF v_to_mail IS NULL THEN
            P_LOG_MAIL(v_to_mail, p_subject, 'FAIL', '수신자 없음', 'CLOB_ATTACH', p_sender);
            RETURN;
        END IF;

        -- 첨부 CLOB -> BLOB(UTF-8) (+BOM)
        DBMS_LOB.CREATETEMPORARY(v_blob, TRUE);
        IF NVL(p_add_bom,'Y') = 'Y' THEN
            DBMS_LOB.WRITEAPPEND(v_blob, 3, HEXTORAW('EFBBBF'));
            v_destoff := 4;
        END IF;
        IF p_attach_clob IS NOT NULL AND DBMS_LOB.GETLENGTH(p_attach_clob) > 0 THEN
            DBMS_LOB.CONVERTTOBLOB(v_blob, p_attach_clob, DBMS_LOB.LOBMAXSIZE,
                                   v_destoff, v_srcoff, NLS_CHARSET_ID('AL32UTF8'),
                                   v_lang, v_warn);
        END IF;

        -- 본문 -> BLOB(UTF-8)
        DBMS_LOB.CREATETEMPORARY(v_body_blob, TRUE);
        DBMS_LOB.WRITEAPPEND(v_body_blob,
            UTL_RAW.LENGTH(UTL_RAW.CAST_TO_RAW(NVL(p_body_contents, ' '))),
            UTL_RAW.CAST_TO_RAW(NVL(p_body_contents, ' ')));

        v_conn := UTL_SMTP.OPEN_CONNECTION(C_SMTP_HOST, C_SMTP_PORT);
        UTL_SMTP.HELO(v_conn, C_SMTP_HOST);
        UTL_SMTP.MAIL(v_conn, p_sender);
        rcpt_all(v_to_mail);
        IF v_cc_mail IS NOT NULL THEN rcpt_all(v_cc_mail); END IF;

        UTL_SMTP.OPEN_DATA(v_conn);
        UTL_SMTP.WRITE_DATA(v_conn, 'From: ' || p_sender || C_CRLF);
        UTL_SMTP.WRITE_DATA(v_conn, 'To: ' || v_to_mail || C_CRLF);
        IF v_cc_mail IS NOT NULL THEN
            UTL_SMTP.WRITE_DATA(v_conn, 'Cc: ' || v_cc_mail || C_CRLF);
        END IF;
        UTL_SMTP.WRITE_DATA(v_conn, 'Subject: ' || F_ENC_SUBJECT(p_subject) || C_CRLF);
        UTL_SMTP.WRITE_DATA(v_conn, 'MIME-Version: 1.0' || C_CRLF);
        UTL_SMTP.WRITE_DATA(v_conn, 'Content-Type: multipart/mixed; boundary="' || C_BND || '"' || C_CRLF);
        UTL_SMTP.WRITE_DATA(v_conn, C_CRLF);

        -- 본문 파트
        UTL_SMTP.WRITE_DATA(v_conn, '--' || C_BND || C_CRLF);
        UTL_SMTP.WRITE_DATA(v_conn, 'Content-Type: text/plain; charset=UTF-8' || C_CRLF);
        UTL_SMTP.WRITE_DATA(v_conn, 'Content-Transfer-Encoding: base64' || C_CRLF);
        UTL_SMTP.WRITE_DATA(v_conn, C_CRLF);
        v_l := DBMS_LOB.GETLENGTH(v_body_blob); v_p := 1;
        WHILE v_p <= v_l LOOP
            UTL_SMTP.WRITE_RAW_DATA(v_conn, UTL_ENCODE.BASE64_ENCODE(DBMS_LOB.SUBSTR(v_body_blob, C_STEP, v_p)));
            UTL_SMTP.WRITE_DATA(v_conn, C_CRLF);
            v_p := v_p + C_STEP;
        END LOOP;
        UTL_SMTP.WRITE_DATA(v_conn, C_CRLF);

        -- 첨부 파트
        UTL_SMTP.WRITE_DATA(v_conn, '--' || C_BND || C_CRLF);
        UTL_SMTP.WRITE_DATA(v_conn, 'Content-Type: ' || p_attach_mime || C_CRLF);
        UTL_SMTP.WRITE_DATA(v_conn, 'Content-Transfer-Encoding: base64' || C_CRLF);
        UTL_SMTP.WRITE_DATA(v_conn, 'Content-Disposition: attachment; filename="' || p_attach_name || '"' || C_CRLF);
        UTL_SMTP.WRITE_DATA(v_conn, C_CRLF);
        v_l := DBMS_LOB.GETLENGTH(v_blob); v_p := 1;
        WHILE v_p <= v_l LOOP
            UTL_SMTP.WRITE_RAW_DATA(v_conn, UTL_ENCODE.BASE64_ENCODE(DBMS_LOB.SUBSTR(v_blob, C_STEP, v_p)));
            UTL_SMTP.WRITE_DATA(v_conn, C_CRLF);
            v_p := v_p + C_STEP;
        END LOOP;
        UTL_SMTP.WRITE_DATA(v_conn, C_CRLF);

        UTL_SMTP.WRITE_DATA(v_conn, '--' || C_BND || '--' || C_CRLF);
        UTL_SMTP.CLOSE_DATA(v_conn);
        UTL_SMTP.QUIT(v_conn);

        IF DBMS_LOB.ISTEMPORARY(v_blob) = 1 THEN DBMS_LOB.FREETEMPORARY(v_blob); END IF;
        IF DBMS_LOB.ISTEMPORARY(v_body_blob) = 1 THEN DBMS_LOB.FREETEMPORARY(v_body_blob); END IF;

        P_LOG_MAIL(v_to_mail, p_subject, 'SUCCESS', NULL, 'CLOB_ATTACH', p_sender, v_cc_mail);
    EXCEPTION
        WHEN OTHERS THEN
            BEGIN UTL_SMTP.QUIT(v_conn); EXCEPTION WHEN OTHERS THEN NULL; END;
            P_LOG_MAIL(v_to_mail, p_subject, 'FAIL', SQLERRM, 'CLOB_ATTACH', p_sender, v_cc_mail);
            RAISE;
    END P_SEND_MAIL_CLOB_ATTACH;

    /*===========================================
      메일 발송 통계 조회
    ===========================================*/
    FUNCTION F_MAIL_STATS (
        p_from_date  IN DATE DEFAULT TRUNC(SYSDATE, 'MM'),
        p_to_date    IN DATE DEFAULT SYSDATE
    ) RETURN T_MAIL_STATS_TAB PIPELINED
    IS
        v_rec T_MAIL_STATS_REC;
    BEGIN
        FOR r IN (
            SELECT TRUNC(SEND_DATE) AS SEND_DT,
                   MAIL_TYPE,
                   STATUS,
                   COUNT(*)          AS CNT,
                   COUNT(DISTINCT TO_MAIL) AS RCPT_CNT
              FROM TB_MAIL_LOG
             WHERE SEND_DATE BETWEEN p_from_date AND p_to_date + 1
             GROUP BY TRUNC(SEND_DATE), MAIL_TYPE, STATUS
             ORDER BY 1 DESC, 2, 3
        ) LOOP
            v_rec.SEND_DT   := r.SEND_DT;
            v_rec.MAIL_TYPE := r.MAIL_TYPE;
            v_rec.STATUS    := r.STATUS;
            v_rec.CNT       := r.CNT;
            v_rec.RCPT_CNT  := r.RCPT_CNT;
            PIPE ROW (v_rec);
        END LOOP;
        RETURN;
    END F_MAIL_STATS;


END PKG_SEND_MAIL;

PACKAGE BODY           "PKG_SPMS_SEND_MAIL" 
IS
    -- 패키지 내부 상수
    C_SMTP_HOST  CONSTANT VARCHAR2(256) := 'mailrelay.lgensol.com';
    C_SMTP_PORT  CONSTANT NUMBER       := 25;
    C_CRLF       CONSTANT VARCHAR2(2)  := CHR(13) || CHR(10);

    /*===========================================
      [내부] 세미콜론 -> 콤마 통일 함수
      - 모든 프로시저에서 공통 사용
    ===========================================*/
    FUNCTION F_NORMALIZE_DELIM (
        p_str IN VARCHAR2
    ) RETURN VARCHAR2
    IS
    BEGIN
        IF p_str IS NULL THEN
            RETURN NULL;
        END IF;
        RETURN REPLACE(p_str, ';', ',');
    END F_NORMALIZE_DELIM;

    /*===========================================
      메일 주소 유효성 검증 (단일)
    ===========================================*/
    FUNCTION F_VALIDATE_EMAIL (
        p_email IN VARCHAR2
    ) RETURN VARCHAR2
    IS
    BEGIN
        IF p_email IS NULL THEN
            RETURN 'N';
        END IF;

        IF REGEXP_LIKE(TRIM(p_email), '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$') THEN
            RETURN 'Y';
        ELSE
            RETURN 'N';
        END IF;
    END F_VALIDATE_EMAIL;

    /*===========================================
      다중 메일 주소 유효성 검증 (콤마/세미콜론 구분)
      - 하나라도 유효하지 않으면 'N' 리턴
    ===========================================*/
    FUNCTION F_VALIDATE_EMAIL_LIST (
        p_email_list IN VARCHAR2
    ) RETURN VARCHAR2
    IS
        v_list  VARCHAR2(4000);
        v_addr  VARCHAR2(500);
        v_pos   NUMBER;
    BEGIN
        IF p_email_list IS NULL THEN
            RETURN 'N';
        END IF;

        -- 세미콜론 -> 콤마 통일
        v_list := F_NORMALIZE_DELIM(p_email_list) || ',';

        LOOP
            v_pos := INSTR(v_list, ',');
            EXIT WHEN NVL(v_pos, 0) = 0;
            v_addr := TRIM(SUBSTR(v_list, 1, v_pos - 1));
            IF v_addr IS NOT NULL AND F_VALIDATE_EMAIL(v_addr) = 'N' THEN
                RETURN 'N';
            END IF;
            v_list := SUBSTR(v_list, v_pos + 1);
        END LOOP;

        RETURN 'Y';
    END F_VALIDATE_EMAIL_LIST;

    /*===========================================
      메일 발송 로그 기록 (AUTONOMOUS_TRANSACTION)
    ===========================================*/
    PROCEDURE P_LOG_MAIL (
        p_to_mail    IN VARCHAR2,
        p_subject    IN VARCHAR2,
        p_status     IN VARCHAR2,
        p_error_msg  IN VARCHAR2 DEFAULT NULL,
        p_mail_type  IN VARCHAR2 DEFAULT 'BASIC',
        p_sender     IN VARCHAR2 DEFAULT NULL,
        p_cc_mail    IN VARCHAR2 DEFAULT NULL,
        p_bcc_mail   IN VARCHAR2 DEFAULT NULL
    )
    IS
        PRAGMA AUTONOMOUS_TRANSACTION;
    BEGIN
        INSERT INTO TB_MAIL_LOG (
            LOG_SEQ, TO_MAIL, CC_MAIL, BCC_MAIL,
            SUBJECT, STATUS, ERROR_MSG, MAIL_TYPE,
            SENDER, SEND_DATE, REG_ID, REG_DATE
        ) VALUES (
            SEQ1_MAIL_LOG.NEXTVAL, p_to_mail, p_cc_mail, p_bcc_mail,
            p_subject, p_status, p_error_msg, p_mail_type,
            p_sender, SYSDATE, USER, SYSDATE
        );
        COMMIT;
    EXCEPTION
        WHEN OTHERS THEN
            ROLLBACK;
    END P_LOG_MAIL;

    /*===========================================
      기본 메일 발송
      - UTL_MAIL 사용
      - 다중 수신자: 콤마/세미콜론 구분 자동 지원
    ===========================================*/
    PROCEDURE P_SEND_MAIL (
        p_to_mail        IN VARCHAR2,
        p_subject        IN VARCHAR2,
        p_body_contents  IN VARCHAR2,
        p_html_yn        IN VARCHAR2 DEFAULT 'N',
        p_sender         IN VARCHAR2 DEFAULT 'scmpi@lgensol.com',
        p_cc_mail        IN VARCHAR2 DEFAULT NULL,
        p_bcc_mail       IN VARCHAR2 DEFAULT NULL
    )
    IS
        v_mime_type VARCHAR2(100);
        v_to_mail   VARCHAR2(4000);
        v_cc_mail   VARCHAR2(4000);
        v_bcc_mail  VARCHAR2(4000);
    BEGIN
        -- 구분자 통일 (세미콜론 -> 콤마)
        v_to_mail  := F_NORMALIZE_DELIM(p_to_mail);
        v_cc_mail  := F_NORMALIZE_DELIM(p_cc_mail);
        v_bcc_mail := F_NORMALIZE_DELIM(p_bcc_mail);

        -- 수신자 유효성 체크
        IF v_to_mail IS NULL THEN
            P_LOG_MAIL(v_to_mail, p_subject, 'FAIL', '수신자 없음', 'BASIC', p_sender);
            RETURN;
        END IF;

        IF (p_html_yn = 'Y') THEN
            v_mime_type := 'text/html; charset=UTF-8';
        ELSE
            v_mime_type := 'text/plain; charset=UTF-8';
        END IF;

        -- 메일 발송하는 부분
        UTL_MAIL.SEND(
            sender     => p_sender,
            recipients => v_to_mail,
            cc         => v_cc_mail,
            bcc        => v_bcc_mail,
            subject    => p_subject,
            message    => p_body_contents,
            mime_type  => v_mime_type
        );

        P_LOG_MAIL(v_to_mail, p_subject, 'SUCCESS', NULL, 'BASIC', p_sender, v_cc_mail, v_bcc_mail);

    EXCEPTION
        WHEN OTHERS THEN
            P_LOG_MAIL(v_to_mail, p_subject, 'FAIL', SQLERRM, 'BASIC', p_sender, v_cc_mail, v_bcc_mail);
            RAISE;
    END P_SEND_MAIL;

    /*===========================================
      첨부파일 포함 메일 발송
      - UTL_MAIL.SEND_ATTACH_RAW 사용
    ===========================================*/
    PROCEDURE P_SEND_MAIL_ATTACH (
        p_to_mail        IN VARCHAR2,
        p_subject        IN VARCHAR2,
        p_body_contents  IN VARCHAR2,
        p_attach_data    IN RAW,
        p_attach_name    IN VARCHAR2,
        p_attach_mime    IN VARCHAR2 DEFAULT 'application/octet-stream',
        p_html_yn        IN VARCHAR2 DEFAULT 'N',
        p_sender         IN VARCHAR2 DEFAULT 'scmpi@lgensol.com',
        p_cc_mail        IN VARCHAR2 DEFAULT NULL
    )
    IS
        v_mime_type VARCHAR2(100);
        v_to_mail   VARCHAR2(4000);
        v_cc_mail   VARCHAR2(4000);
    BEGIN
        -- 구분자 통일 (세미콜론 -> 콤마)
        v_to_mail := F_NORMALIZE_DELIM(p_to_mail);
        v_cc_mail := F_NORMALIZE_DELIM(p_cc_mail);

        IF v_to_mail IS NULL THEN
            P_LOG_MAIL(v_to_mail, p_subject, 'FAIL', '수신자 없음', 'ATTACH', p_sender);
            RETURN;
        END IF;

        IF (p_html_yn = 'Y') THEN
            v_mime_type := 'text/html; charset=UTF-8';
        ELSE
            v_mime_type := 'text/plain; charset=UTF-8';
        END IF;

        -- 메일 발송하는 부분
        UTL_MAIL.SEND_ATTACH_RAW(
            sender        => p_sender,
            recipients    => v_to_mail,
            cc            => v_cc_mail,
            subject       => p_subject,
            message       => p_body_contents,
            mime_type     => v_mime_type,
            attachment    => p_attach_data,
            att_inline    => FALSE,
            att_mime_type => p_attach_mime,
            att_filename  => p_attach_name
        );

        P_LOG_MAIL(v_to_mail, p_subject, 'SUCCESS', NULL, 'ATTACH', p_sender, v_cc_mail);

    EXCEPTION
        WHEN OTHERS THEN
            P_LOG_MAIL(v_to_mail, p_subject, 'FAIL', SQLERRM, 'ATTACH', p_sender, v_cc_mail);
            RAISE;
    END P_SEND_MAIL_ATTACH;

    /*===========================================
      CLOB 본문 메일 발송 (32KB 초과)
      - UTL_SMTP 사용 (UTL_MAIL 32KB 제한)
      - 다중 수신자 지원 (콤마/세미콜론 구분)
      - CC 지원
    ===========================================*/
    PROCEDURE P_SEND_MAIL_CLOB (
        p_to_mail        IN VARCHAR2,
        p_subject        IN VARCHAR2,
        p_body_clob      IN CLOB,
        p_html_yn        IN VARCHAR2 DEFAULT 'N',
        p_sender         IN VARCHAR2 DEFAULT 'scmpi@lgensol.com',
        p_cc_mail        IN VARCHAR2 DEFAULT NULL
    )
    IS
        v_connection  UTL_SMTP.CONNECTION;
        v_mime_type   VARCHAR2(100);
        v_offset      INTEGER := 1;
        v_chunk_size  INTEGER := 4000;
        v_length      INTEGER;
        v_to_mail     VARCHAR2(4000);
        v_cc_mail     VARCHAR2(4000);
        v_list        VARCHAR2(4000);
        v_addr        VARCHAR2(500);
        v_pos         NUMBER;
    BEGIN
        -- 구분자 통일 (세미콜론 -> 콤마)
        v_to_mail := F_NORMALIZE_DELIM(p_to_mail);
        v_cc_mail := F_NORMALIZE_DELIM(p_cc_mail);

        /* 메일 발송 주석 처리. 홍성대 2026.08.18 */
        RETURN;

        IF v_to_mail IS NULL THEN
            P_LOG_MAIL(v_to_mail, p_subject, 'FAIL', '수신자 없음', 'CLOB', p_sender);
            RETURN;
        END IF;

        IF (p_html_yn = 'Y') THEN
            v_mime_type := 'text/html; charset=UTF-8';
        ELSE
            v_mime_type := 'text/plain; charset=UTF-8';
        END IF;

        -- SMTP 연결
        v_connection := UTL_SMTP.OPEN_CONNECTION(C_SMTP_HOST, C_SMTP_PORT);
        UTL_SMTP.HELO(v_connection, C_SMTP_HOST);
        UTL_SMTP.MAIL(v_connection, p_sender);

        -- TO: 다중 수신자 처리
        v_list := v_to_mail || ',';
        LOOP
            v_pos := INSTR(v_list, ',');
            EXIT WHEN NVL(v_pos, 0) = 0;
            v_addr := TRIM(SUBSTR(v_list, 1, v_pos - 1));
            IF v_addr IS NOT NULL THEN
                UTL_SMTP.RCPT(v_connection, v_addr);
            END IF;
            v_list := SUBSTR(v_list, v_pos + 1);
        END LOOP;

        -- CC: 다중 수신자 처리
        IF v_cc_mail IS NOT NULL THEN
            v_list := v_cc_mail || ',';
            LOOP
                v_pos := INSTR(v_list, ',');
                EXIT WHEN NVL(v_pos, 0) = 0;
                v_addr := TRIM(SUBSTR(v_list, 1, v_pos - 1));
                IF v_addr IS NOT NULL THEN
                    UTL_SMTP.RCPT(v_connection, v_addr);
                END IF;
                v_list := SUBSTR(v_list, v_pos + 1);
            END LOOP;
        END IF;

        -- 헤더 작성
        UTL_SMTP.OPEN_DATA(v_connection);
        UTL_SMTP.WRITE_DATA(v_connection, 'From: '            || p_sender   || C_CRLF);
        UTL_SMTP.WRITE_DATA(v_connection, 'To: '              || v_to_mail  || C_CRLF);
        IF v_cc_mail IS NOT NULL THEN
            UTL_SMTP.WRITE_DATA(v_connection, 'Cc: '          || v_cc_mail  || C_CRLF);
        END IF;
        UTL_SMTP.WRITE_DATA(v_connection, 'Subject: '         || p_subject  || C_CRLF);
        UTL_SMTP.WRITE_DATA(v_connection, 'MIME-Version: 1.0'              || C_CRLF);
        UTL_SMTP.WRITE_DATA(v_connection, 'Content-Type: '    || v_mime_type || C_CRLF);
        UTL_SMTP.WRITE_DATA(v_connection, C_CRLF);

        -- CLOB 본문을 청크 단위로 전송
        v_length := DBMS_LOB.GETLENGTH(p_body_clob);
        WHILE v_offset <= v_length LOOP
            UTL_SMTP.WRITE_DATA(v_connection, DBMS_LOB.SUBSTR(p_body_clob, v_chunk_size, v_offset));
            v_offset := v_offset + v_chunk_size;
        END LOOP;

        UTL_SMTP.CLOSE_DATA(v_connection);
        UTL_SMTP.QUIT(v_connection);

        P_LOG_MAIL(v_to_mail, p_subject, 'SUCCESS', NULL, 'CLOB', p_sender, v_cc_mail);

    EXCEPTION
        WHEN OTHERS THEN
            P_LOG_MAIL(v_to_mail, p_subject, 'FAIL', SQLERRM, 'CLOB', p_sender, v_cc_mail);
            BEGIN
                UTL_SMTP.QUIT(v_connection);
            EXCEPTION
                WHEN OTHERS THEN NULL;
            END;
            RAISE;
    END P_SEND_MAIL_CLOB;

    /*===========================================
      대용량 첨부 메일 발송 (파일 없이 CLOB -> UTL_SMTP MIME/Base64)
      - UTL_MAIL 32KB 제한 없음
      - 첨부 CLOB을 UTF-8(+BOM) Base64 로 MIME 첨부
      - 본문/제목 한글 안전(UTF-8 base64)
    ===========================================*/
    PROCEDURE P_SEND_MAIL_CLOB_ATTACH (
        p_to_mail        IN VARCHAR2,
        p_subject        IN VARCHAR2,
        p_body_contents  IN VARCHAR2,
        p_attach_clob    IN CLOB,
        p_attach_name    IN VARCHAR2,
        p_attach_mime    IN VARCHAR2 DEFAULT 'text/csv; charset=UTF-8',
        p_sender         IN VARCHAR2 DEFAULT 'scmpi@lgensol.com',
        p_cc_mail        IN VARCHAR2 DEFAULT NULL,
        p_add_bom        IN VARCHAR2 DEFAULT 'Y'
    )
    IS
        C_BND   CONSTANT VARCHAR2(60) := '====NSCM_MIME_BOUNDARY_8f3a2c====';
        C_STEP  CONSTANT PLS_INTEGER  := 57;   -- 57B -> 76 base64 chars/line
        v_conn      UTL_SMTP.CONNECTION;
        v_to_mail   VARCHAR2(4000);
        v_cc_mail   VARCHAR2(4000);
        v_blob      BLOB;
        v_body_blob BLOB;
        v_destoff   INTEGER := 1;
        v_srcoff    INTEGER := 1;
        v_lang      INTEGER := 0;
        v_warn      INTEGER;
        v_l         INTEGER;
        v_p         INTEGER;

        PROCEDURE rcpt_all(p IN VARCHAR2) IS
            v_s VARCHAR2(4000) := F_NORMALIZE_DELIM(p) || ',';
            v_i NUMBER;
            v_a VARCHAR2(500);
        BEGIN
            LOOP
                v_i := INSTR(v_s, ',');
                EXIT WHEN NVL(v_i, 0) = 0;
                v_a := TRIM(SUBSTR(v_s, 1, v_i - 1));
                IF v_a IS NOT NULL THEN UTL_SMTP.RCPT(v_conn, v_a); END IF;
                v_s := SUBSTR(v_s, v_i + 1);
            END LOOP;
        END;
    BEGIN
        v_to_mail := F_NORMALIZE_DELIM(p_to_mail);
        v_cc_mail := F_NORMALIZE_DELIM(p_cc_mail);

        /* 메일 발송 주석 처리. 홍성대 2026.08.18 */
        RETURN;

        IF v_to_mail IS NULL THEN
            P_LOG_MAIL(v_to_mail, p_subject, 'FAIL', '수신자 없음', 'CLOB_ATTACH', p_sender);
            RETURN;
        END IF;

        -- 첨부 CLOB -> BLOB(UTF-8) (+BOM)
        DBMS_LOB.CREATETEMPORARY(v_blob, TRUE);
        IF NVL(p_add_bom,'Y') = 'Y' THEN
            DBMS_LOB.WRITEAPPEND(v_blob, 3, HEXTORAW('EFBBBF'));
            v_destoff := 4;
        END IF;
        IF p_attach_clob IS NOT NULL AND DBMS_LOB.GETLENGTH(p_attach_clob) > 0 THEN
            DBMS_LOB.CONVERTTOBLOB(v_blob, p_attach_clob, DBMS_LOB.LOBMAXSIZE,
                                   v_destoff, v_srcoff, NLS_CHARSET_ID('AL32UTF8'),
                                   v_lang, v_warn);
        END IF;

        -- 본문 -> BLOB(UTF-8)
        DBMS_LOB.CREATETEMPORARY(v_body_blob, TRUE);
        DBMS_LOB.WRITEAPPEND(v_body_blob,
            UTL_RAW.LENGTH(UTL_RAW.CAST_TO_RAW(NVL(p_body_contents, ' '))),
            UTL_RAW.CAST_TO_RAW(NVL(p_body_contents, ' ')));

        v_conn := UTL_SMTP.OPEN_CONNECTION(C_SMTP_HOST, C_SMTP_PORT);
        UTL_SMTP.HELO(v_conn, C_SMTP_HOST);
        UTL_SMTP.MAIL(v_conn, p_sender);
        rcpt_all(v_to_mail);
        IF v_cc_mail IS NOT NULL THEN rcpt_all(v_cc_mail); END IF;

        UTL_SMTP.OPEN_DATA(v_conn);
        UTL_SMTP.WRITE_DATA(v_conn, 'From: ' || p_sender || C_CRLF);
        UTL_SMTP.WRITE_DATA(v_conn, 'To: ' || v_to_mail || C_CRLF);
        IF v_cc_mail IS NOT NULL THEN
            UTL_SMTP.WRITE_DATA(v_conn, 'Cc: ' || v_cc_mail || C_CRLF);
        END IF;
        UTL_SMTP.WRITE_DATA(v_conn, 'Subject: =?UTF-8?B?' ||
            UTL_RAW.CAST_TO_VARCHAR2(UTL_ENCODE.BASE64_ENCODE(UTL_RAW.CAST_TO_RAW(p_subject))) ||
            '?=' || C_CRLF);
        UTL_SMTP.WRITE_DATA(v_conn, 'MIME-Version: 1.0' || C_CRLF);
        UTL_SMTP.WRITE_DATA(v_conn, 'Content-Type: multipart/mixed; boundary="' || C_BND || '"' || C_CRLF);
        UTL_SMTP.WRITE_DATA(v_conn, C_CRLF);

        -- 본문 파트
        UTL_SMTP.WRITE_DATA(v_conn, '--' || C_BND || C_CRLF);
        UTL_SMTP.WRITE_DATA(v_conn, 'Content-Type: text/plain; charset=UTF-8' || C_CRLF);
        UTL_SMTP.WRITE_DATA(v_conn, 'Content-Transfer-Encoding: base64' || C_CRLF);
        UTL_SMTP.WRITE_DATA(v_conn, C_CRLF);
        v_l := DBMS_LOB.GETLENGTH(v_body_blob); v_p := 1;
        WHILE v_p <= v_l LOOP
            UTL_SMTP.WRITE_RAW_DATA(v_conn, UTL_ENCODE.BASE64_ENCODE(DBMS_LOB.SUBSTR(v_body_blob, C_STEP, v_p)));
            UTL_SMTP.WRITE_DATA(v_conn, C_CRLF);
            v_p := v_p + C_STEP;
        END LOOP;
        UTL_SMTP.WRITE_DATA(v_conn, C_CRLF);

        -- 첨부 파트
        UTL_SMTP.WRITE_DATA(v_conn, '--' || C_BND || C_CRLF);
        UTL_SMTP.WRITE_DATA(v_conn, 'Content-Type: ' || p_attach_mime || C_CRLF);
        UTL_SMTP.WRITE_DATA(v_conn, 'Content-Transfer-Encoding: base64' || C_CRLF);
        UTL_SMTP.WRITE_DATA(v_conn, 'Content-Disposition: attachment; filename="' || p_attach_name || '"' || C_CRLF);
        UTL_SMTP.WRITE_DATA(v_conn, C_CRLF);
        v_l := DBMS_LOB.GETLENGTH(v_blob); v_p := 1;
        WHILE v_p <= v_l LOOP
            UTL_SMTP.WRITE_RAW_DATA(v_conn, UTL_ENCODE.BASE64_ENCODE(DBMS_LOB.SUBSTR(v_blob, C_STEP, v_p)));
            UTL_SMTP.WRITE_DATA(v_conn, C_CRLF);
            v_p := v_p + C_STEP;
        END LOOP;
        UTL_SMTP.WRITE_DATA(v_conn, C_CRLF);

        UTL_SMTP.WRITE_DATA(v_conn, '--' || C_BND || '--' || C_CRLF);
        UTL_SMTP.CLOSE_DATA(v_conn);
        UTL_SMTP.QUIT(v_conn);

        IF DBMS_LOB.ISTEMPORARY(v_blob) = 1 THEN DBMS_LOB.FREETEMPORARY(v_blob); END IF;
        IF DBMS_LOB.ISTEMPORARY(v_body_blob) = 1 THEN DBMS_LOB.FREETEMPORARY(v_body_blob); END IF;

        P_LOG_MAIL(v_to_mail, p_subject, 'SUCCESS', NULL, 'CLOB_ATTACH', p_sender, v_cc_mail);
    EXCEPTION
        WHEN OTHERS THEN
            BEGIN UTL_SMTP.QUIT(v_conn); EXCEPTION WHEN OTHERS THEN NULL; END;
            P_LOG_MAIL(v_to_mail, p_subject, 'FAIL', SQLERRM, 'CLOB_ATTACH', p_sender, v_cc_mail);
            RAISE;
    END P_SEND_MAIL_CLOB_ATTACH;

    /*===========================================
      메일 발송 통계 조회
    ===========================================*/
    FUNCTION F_MAIL_STATS (
        p_from_date  IN DATE DEFAULT TRUNC(SYSDATE, 'MM'),
        p_to_date    IN DATE DEFAULT SYSDATE
    ) RETURN T_MAIL_STATS_TAB PIPELINED
    IS
        v_rec T_MAIL_STATS_REC;
    BEGIN
        FOR r IN (
            SELECT TRUNC(SEND_DATE) AS SEND_DT,
                   MAIL_TYPE,
                   STATUS,
                   COUNT(*)          AS CNT,
                   COUNT(DISTINCT TO_MAIL) AS RCPT_CNT
              FROM TB_MAIL_LOG
             WHERE SEND_DATE BETWEEN p_from_date AND p_to_date + 1
             GROUP BY TRUNC(SEND_DATE), MAIL_TYPE, STATUS
             ORDER BY 1 DESC, 2, 3
        ) LOOP
            v_rec.SEND_DT   := r.SEND_DT;
            v_rec.MAIL_TYPE := r.MAIL_TYPE;
            v_rec.STATUS    := r.STATUS;
            v_rec.CNT       := r.CNT;
            v_rec.RCPT_CNT  := r.RCPT_CNT;
            PIPE ROW (v_rec);
        END LOOP;
        RETURN;
    END F_MAIL_STATS;


END PKG_SPMS_SEND_MAIL;

PACKAGE BODY PKG_SSP0005
IS
    /*
     * Program ID   : PKG_SSP0005
     * Description  : SSP0005 Shipment Working Day 화면 - 출하 가능일 달력 조회 / 저장
     * Program History
     *===================================================================================================
     *   Date       In Charge      Description
     *===================================================================================================
     * 2026.09.22                  AS-IS 프로시저 2 건 패키지 전환
     */

    C_DELIMITER         CONSTANT VARCHAR2(1 CHAR) := '^';

    TYPE T_TOKEN_TAB IS TABLE OF VARCHAR2(32767 CHAR) INDEX BY PLS_INTEGER;
    TYPE T_FOUND_TAB IS TABLE OF VARCHAR2(1 CHAR) INDEX BY PLS_INTEGER;

    /* ==============================================================================================
       내부 : 구분자 개수 + 1 (AS-IS SCM_ARR_SPL_CNT 와 같은 값 · CLOB 대응)
       ============================================================================================== */
    FUNCTION F_SPL_CNT
    (
        P_TEXT              IN  CLOB
    )
    RETURN PLS_INTEGER
    IS
        V_CNT               PLS_INTEGER := 1;
        V_POS               PLS_INTEGER;
    BEGIN
        IF P_TEXT IS NULL THEN
            RETURN V_CNT;
        END IF;

        V_POS := DBMS_LOB.INSTR(P_TEXT, C_DELIMITER, 1, 1);

        WHILE V_POS > 0 LOOP
            V_CNT := V_CNT + 1;
            V_POS := DBMS_LOB.INSTR(P_TEXT, C_DELIMITER, V_POS + 1, 1);
        END LOOP;

        RETURN V_CNT;
    END F_SPL_CNT;

    /* ==============================================================================================
       내부 : 앞뒤 공백을 뺀 마지막 글자 위치 (없으면 0)
       ============================================================================================== */
    FUNCTION F_LAST_NON_SPACE
    (
        P_TEXT              IN  CLOB
    )
    RETURN PLS_INTEGER
    IS
        V_POS               PLS_INTEGER;
    BEGIN
        V_POS := NVL(DBMS_LOB.GETLENGTH(P_TEXT), 0);

        WHILE V_POS > 0
          AND DBMS_LOB.SUBSTR(P_TEXT, 1, V_POS) = ' ' LOOP
            V_POS := V_POS - 1;
        END LOOP;

        RETURN V_POS;
    END F_LAST_NON_SPACE;

    /* ==============================================================================================
       내부 : 구분 문자열을 순서대로 한 번에 분리 (AS-IS SCM_ARR_SPL_VAL 과 같은 규칙 · CLOB 대응)
              - 전체 앞뒤 공백 제거 후 끝에 구분자를 붙인 문자열에서 차례로 잘라 앞뒤 공백 제거
              - 다음 위치 = 현재 위치 + 공백 제거한 값 길이 + 1 (AS-IS 와 같은 계산)
              - O_FOUND = 'Y' : 구분자를 찾은 자리 (값이 비어도 AS-IS 는 빈 문자)
                O_FOUND = 'N' : 구분자를 못 찾은 자리 (AS-IS 는 NULL)
       ============================================================================================== */
    PROCEDURE P_SPL_ARR
    (
        P_TEXT              IN  CLOB,
        P_CNT               IN  PLS_INTEGER,
        O_TOKEN             OUT T_TOKEN_TAB,
        O_FOUND             OUT T_FOUND_TAB
    )
    IS
        V_END               PLS_INTEGER;
        V_OFF               PLS_INTEGER := 1;
        V_POS               PLS_INTEGER;
        V_WORD              VARCHAR2(32767 CHAR);
    BEGIN
        V_END := F_LAST_NON_SPACE(P_TEXT);

        /* 전체 앞 공백 */
        WHILE V_OFF <= V_END
          AND DBMS_LOB.SUBSTR(P_TEXT, 1, V_OFF) = ' ' LOOP
            V_OFF := V_OFF + 1;
        END LOOP;

        FOR I IN 1 .. P_CNT LOOP
            IF P_TEXT IS NULL
            OR V_OFF > V_END + 1 THEN
                O_TOKEN(I) := NULL;
                O_FOUND(I) := 'N';
            ELSE
                V_POS := DBMS_LOB.INSTR(P_TEXT, C_DELIMITER, V_OFF, 1);

                IF V_POS = 0
                OR V_POS > V_END THEN
                    V_POS := V_END + 1;   /* 끝에 붙인 구분자 자리 */
                END IF;

                IF V_POS > V_OFF THEN
                    V_WORD := TRIM(DBMS_LOB.SUBSTR(P_TEXT, V_POS - V_OFF, V_OFF));
                ELSE
                    V_WORD := NULL;
                END IF;

                O_TOKEN(I) := V_WORD;
                O_FOUND(I) := 'Y';

                V_OFF := V_OFF + NVL(LENGTH(V_WORD), 0) + 1;

                /* 남은 문자열 앞 공백 */
                WHILE V_OFF <= V_END
                  AND DBMS_LOB.SUBSTR(P_TEXT, 1, V_OFF) = ' ' LOOP
                    V_OFF := V_OFF + 1;
                END LOOP;
            END IF;
        END LOOP;
    END P_SPL_ARR;

    /* ==============================================================================================
       SSP0005_GET_SHIPMENT_WORKING_DAY
       ============================================================================================== */
    PROCEDURE P_SSP0005_GET_SHIPMENT_WORKING_DAY
    (
        P_FROM_YYYYMMDD     IN  VARCHAR2,
        P_TO_YYYYMMDD       IN  VARCHAR2,
        P_DIVISION_ID       IN  VARCHAR2,
        P_COMPANY_ID        IN  VARCHAR2,
        P_DEBUG_MODE        IN  VARCHAR2,
        O_RC1               OUT SYS_REFCURSOR,
        O_RESULT_CURSOR     OUT SYS_REFCURSOR
    )
    IS
    /*
     * Program ID   : SSP0005_GET_SHIPMENT_WORKING_DAY
     * Description  : SHIPMENT_WORKING_DAY 조회
     * Program History
     *===================================================================================================
     *   Date       In Charge      Description
     *===================================================================================================
     * 2018/04/25   ygkim		   Initial Release [PJ20182279] 전지본부 출하계획 시스템 구축 프로젝트
     * EX)
     * EXEC SSP0005_GET_SHIPMENT_WORKING_DAY @p_from_yyyymmdd='20180425', @p_to_yyyymmdd='20181028', @p_division_id='40', @p_company_id='ALL,C100,G180,G380,G450,G480', @debug_mode='T'
     *
     * 2026.09.22                  [MSSQL -> Oracle 전환]
     *                             - 일자 칸(D_YYYYMMDD)이 조회 기간에 따라 달라지므로 피벗 문장만 동적으로 연다.
     *                               칸 이름의 출처는 달력 기준 테이블(SCM_SYS_CALENDAR_M)이고 조회 조건값은 모두 바인드한다.
     *                             - #TblDynamicPivot_SSP0005 는 한 번만 참조하므로 임시 테이블 대신 인라인 뷰로 옮겼다.
     *                             - 분리 함수 반환 칸은 별칭을 붙여(SA.COLUMN_VALUE · XA.COLUMN_VALUE) 참조한다.
     *                               별칭을 빼면 바깥 칸으로 해석되어 오류 없이 0 행이 된다.
     *                             - 선택 조건의 빈 값 판정은 TRIM(입력값) IS NULL (공백만 입력도 조건 없음)
     *                             - 대소문자 · 뒤 공백 무시 비교 재현 : 원장 값에 소문자 · 뒤 공백이 0 건이라
     *                               (2026.09.22 실측 227,456 행 중 0) 입력값만 UPPER(RTRIM()) 한다.
     *                               칸에 UPPER 를 씌우면 기본키 인덱스를 못 써 전체 읽기가 된다
     *                             - 정렬 : 대소문자 · 하이픈 무시, 밑줄은 글자 · 숫자 앞, NULL 앞
     *                             - TOP 10000 은 정렬 전에 걸리므로 ROWNUM 을 인라인 뷰 바깥에 두었다.
     */
        V_DIVISION_ID       VARCHAR2(4000 CHAR) := TRIM(P_DIVISION_ID);
        V_COMPANY_ID        VARCHAR2(4000 CHAR) := TRIM(P_COMPANY_ID);

        V_MQUERY            CLOB;
        V_MEXEC             CLOB;
        V_POS               PLS_INTEGER;
        V_LEN               PLS_INTEGER;
        V_ERR               VARCHAR2(4000 CHAR);
    BEGIN
        /********************************************************************************
            * PIVOIT처리
        ********************************************************************************/
        /* PIVOIT 대상 날짜문자열 생성 - 대상 일자가 없으면 V_MQUERY 는 비고 일자 칸 없이 열린다 */
        FOR C IN (SELECT IA.YYYYMMDD
                       , IA.SORT_ORDER_NO
                    FROM (SELECT 'D_' || BASIS_YYYYMMDD AS YYYYMMDD
                               , BASIS_YYYYMMDD || '31' AS SORT_ORDER_NO   /* a.basis_yyyymmdd + CONVERT(CHAR(2), 31) */
                            FROM SCM_SYS_CALENDAR_M
                           WHERE BASIS_YYYYMMDD >= P_FROM_YYYYMMDD
                             AND BASIS_YYYYMMDD <= P_TO_YYYYMMDD
                           GROUP BY BASIS_YYYYMMDD) IA
                   WHERE ROWNUM <= 10000                                   /* SELECT TOP 10000 */
                   ORDER BY SORT_ORDER_NO) LOOP

            V_MQUERY := V_MQUERY
                     || '     , MAX(CASE WHEN IA.YYYYMMDD = ''' || C.YYYYMMDD || ''' THEN IA.WORKDAY_YN END) AS ' || C.YYYYMMDD || CHR(10);
        END LOOP;

        V_MEXEC := 'SELECT IA.DIVISION_ID' || CHR(10)
                || '     , IA.COMPANY_ID' || CHR(10)
                || V_MQUERY
                || '  FROM (SELECT DISTINCT DIVISION_ID' || CHR(10)
                || '             , COMPANY_ID' || CHR(10)
                || '             , WORKDAY_YN' || CHR(10)
                || '             , ''D_'' || YYYYMMDD AS YYYYMMDD' || CHR(10)
                || '          FROM SSP_MST_SHIP_CALENDAR' || CHR(10)
                || '         WHERE YYYYMMDD >= :B_FROM_YYYYMMDD' || CHR(10)
                || '           AND YYYYMMDD <= :B_TO_YYYYMMDD' || CHR(10)
                || '           AND (:B_DIVISION_YN IS NULL' || CHR(10)
               || '                OR UPPER(:B_DIVISION_YN) = ''ALL''' || CHR(10)   /* 조회조건 ALL 은 조건 없음 */
                || '                OR DIVISION_ID IN (SELECT UPPER(RTRIM(SA.COLUMN_VALUE))' || CHR(10)
                || '                                     FROM TABLE(STRING_SPLIT(:B_DIVISION_ID, '','')) SA))' || CHR(10)
                || '           AND (:B_COMPANY_YN IS NULL' || CHR(10)
               || '                OR UPPER(:B_COMPANY_YN) = ''ALL''' || CHR(10)    /* 조회조건 ALL 은 조건 없음 */
                || '                OR COMPANY_ID IN (SELECT UPPER(RTRIM(XA.COLUMN_VALUE))' || CHR(10)
                || '                                    FROM TABLE(STRING_SPLIT(:B_COMPANY_ID, '','')) XA))) IA' || CHR(10)
                || ' GROUP BY IA.DIVISION_ID' || CHR(10)
                || '        , IA.COMPANY_ID' || CHR(10)
                /* 옛 정렬규칙 재현 : 대소문자 무시 · 하이픈 무시 · 밑줄은 글자 · 숫자보다 앞 · 빈값 맨 앞 */
                || ' ORDER BY UPPER(TRANSLATE(IA.DIVISION_ID, ''_-'', ''/'')) NULLS FIRST' || CHR(10)
                || '        , IA.DIVISION_ID NULLS FIRST' || CHR(10)
                || '        , UPPER(TRANSLATE(IA.COMPANY_ID, ''_-'', ''/'')) NULLS FIRST' || CHR(10)
                || '        , IA.COMPANY_ID NULLS FIRST';
                --SET @mEXEC = @mEXEC+'	ORDER BY division_id , company_id '+CHAR(10);

        -----------------------------------------------------------
        -- DEBUG QRY 출력
        -----------------------------------------------------------
        IF P_DEBUG_MODE = 'T' THEN
            BEGIN
                V_POS := 1;
                V_LEN := DBMS_LOB.GETLENGTH(V_MEXEC);
                WHILE V_POS <= V_LEN LOOP
                    DBMS_OUTPUT.PUT_LINE(DBMS_LOB.SUBSTR(V_MEXEC, 4000, V_POS));
                    V_POS := V_POS + 4000;
                END LOOP;
            EXCEPTION
                WHEN OTHERS THEN
                    NULL;   /* 출력 버퍼 한도 초과는 조회 결과와 무관하므로 무시 */
            END;
        END IF;
        -----------------------------------------------------------

        /* 일자 칸이 조회 기간에 따라 달라지므로 동적 문장으로 연다 (조건값은 모두 바인드) */
        OPEN O_RC1 FOR V_MEXEC
        /* ★같은 이름을 다시 써도 Oracle 은 자리마다 값을 따로 받는다 — ALL 판정 자리 둘을 더 넘긴다 */
        USING P_FROM_YYYYMMDD, P_TO_YYYYMMDD
            , V_DIVISION_ID, V_DIVISION_ID, V_DIVISION_ID
            , V_COMPANY_ID,  V_COMPANY_ID,  V_COMPANY_ID;

        OPEN O_RESULT_CURSOR FOR
            SELECT '0'       AS CODE
                 , 'SUCCESS' AS MSG
              FROM DUAL;

    EXCEPTION
        WHEN OTHERS THEN
            V_ERR := SUBSTR(SQLERRM, 1, 4000);

            OPEN O_RC1 FOR
                SELECT NULL AS DIVISION_ID
                     , NULL AS COMPANY_ID
                  FROM DUAL
                 WHERE 1 = 0;

            OPEN O_RESULT_CURSOR FOR
                SELECT '-1'  AS CODE
                     , V_ERR AS MSG
                  FROM DUAL;
    END P_SSP0005_GET_SHIPMENT_WORKING_DAY;

    /* ==============================================================================================
       SSP0005_SAVE_SHIPMENT_WORKING_DAY_ROW
       ============================================================================================== */
    PROCEDURE P_SSP0005_SAVE_SHIPMENT_WORKING_DAY
    (
        P_ACTIVE_FLAG       IN  CLOB,
        P_DIVISION_ID       IN  CLOB,
        P_COMPANY_ID        IN  CLOB,
        P_YYYYMMDD          IN  CLOB,
        P_WORKDAY_YN        IN  CLOB,
        P_LAST_UPDATED_BY   IN  VARCHAR2,
        P_TIME_ZONE         IN  VARCHAR2,
        P_DEBUG_MODE        IN  VARCHAR2,
        O_RESULT_CURSOR     OUT SYS_REFCURSOR
    )
    IS
    /*
     * Program ID   : SSP0005_SAVE_SHIPMENT_WORKING_DAY
     * Description  : SHIPMENT_WORKING_DAY 수정
     * Program History
     *===================================================================================================
     *   Date       In Charge      Description
     *===================================================================================================
     * 2018/04/25   ygkim   Initial Release [PJ20182279] 전지본부 출하계획 시스템 구축 프로젝트
     * 2018/05/29   ygkim			create date, last update date 시간 변경
     *
     * 2026.09.22                  [MSSQL -> Oracle 전환]
     *                             - AS-IS 는 화면이 변경 칸마다 한 번씩 부르고 첫 행 · 끝 행에만 로그를 남겼다.
     *                               TO-BE 는 변경 칸 전부를 '^' 로 이어 한 번에 받으므로 호출 시작과 끝에 한 번씩 남긴다.
     *                               (그래서 AS-IS 인자 @p_first_row · @p_last_row 는 두지 않는다)
     *                             - '^' 분리 규칙은 AS-IS SCM_ARR_SPL_VAL 과 같음 - 행마다 처음부터 다시 자르지 않는다
     *                             - AS-IS 는 수정(UPDATE)만 있다. 등록 · 삭제 구문이 없어 화면이 보낸 구분값
     *                               @p_active_flag 는 쓰이지 않는다. 전환본도 같게 두고 인자만 남겼다.
     *                             - 키 비교 대소문자 · 뒤 공백 무시 재현 : 보낸 키는 늘 UPPER(RTRIM()) 으로 맞춘다
     *                               (칸에는 함수를 씌우지 않아 기본키 인덱스를 그대로 쓴다).
     *                               원장 키에 소문자 · 뒤 공백이 있으면 그때만 양쪽 UPPER(RTRIM()) 비교로 바꾼다
     *                               - 2026.09.22 실측 227,456 행 중 소문자 · 뒤 공백 0 건이라 아래 경로를 탄다
     *                             - 값 자리가 비어 있으면 그대로 NULL 로 둔다. 원장 칸이 필수면 오류가 나고
     *                               AS-IS 처럼 빈 문자를 저장하지 않는다 (키 칸이 비면 맞는 행이 없어 0 건 - AS-IS 와 같음)
     *                             - @v_creation_date = SYSDATETIME() -> SYSDATE (원장 칸이 DATE 라 밀리초는 없어진다)
     *                             - @p_time_zone 은 AS-IS 에서 쓰이지 않는다(FN_MULTY_TIME 호출이 주석). 인자만 남겼다.
     *                             - 트랜잭션 : 시작 시 SAVEPOINT, 오류 시 SAVEPOINT 까지 되돌린 뒤 오류 로그 기록 후 COMMIT
     *                               (시작 로그는 PR_SCM_SYS_LOG_BATCH 자율 트랜잭션이라 오류 시에도 남는다)
     *                             - 결과 건수 : AS-IS 는 늘 0 을 돌려주었으나(@mst_loop_cnt 를 올리는 곳이 없음)
     *                               전환본은 실제로 수정된 행 수를 돌려준다
     */
        V_ACTIVE_FLAG       T_TOKEN_TAB;
        V_DIVISION_ID       T_TOKEN_TAB;
        V_COMPANY_ID        T_TOKEN_TAB;
        V_YYYYMMDD          T_TOKEN_TAB;
        V_WORKDAY_YN        T_TOKEN_TAB;

        V_F_ACTIVE_FLAG     T_FOUND_TAB;
        V_F_DIVISION_ID     T_FOUND_TAB;
        V_F_COMPANY_ID      T_FOUND_TAB;
        V_F_YYYYMMDD        T_FOUND_TAB;
        V_F_WORKDAY_YN      T_FOUND_TAB;

        V_DIV               VARCHAR2(32767 CHAR);
        V_COM               VARCHAR2(32767 CHAR);
        V_YMD               VARCHAR2(32767 CHAR);
        V_WORK              VARCHAR2(32767 CHAR);

        V_CREATION_DATE     DATE;
        V_MAX_LOOP_CNT      PLS_INTEGER := 0;
        V_MST_LOOP_CNT      PLS_INTEGER := 0;
        V_UPD_CNT           PLS_INTEGER := 0;
        V_KEY_CI_YN         VARCHAR2(1 CHAR) := 'N';

        -- LOG 용 변수 설정
        V_PROGRAM_NAME      VARCHAR2(150 CHAR) := '[SSP0005_SAVE_SHIPMENT_WORKING_DAY_ROW]';
        V_LOG_TYPE          VARCHAR2(30 CHAR);     -- START/END/ERROR/...
        V_N_LOG_COUNT       PLS_INTEGER := 0;
        V_LOG_MESSAGE       VARCHAR2(1000 CHAR);
        V_DESCRIPTION       VARCHAR2(500 CHAR);
        V_EVENT_DATE        DATE;

        -- 예외처리 변수 설정
        V_ERR_CODE          VARCHAR2(20 CHAR);
        V_ERR_MESSAGE       VARCHAR2(4000 CHAR);
    BEGIN
        -- 트렌젝션 시작
        SAVEPOINT SP_SSP0005_SAVE;

        V_CREATION_DATE := SYSDATE;   --[dbo].[FN_MULTY_TIME](@p_time_zone);

        -- 시작 LOG
        V_LOG_TYPE    := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := '';
        V_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, V_N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, V_EVENT_DATE);

        -- 프로시저 LOOP 길이를 판단
        V_MAX_LOOP_CNT := F_SPL_CNT(P_ACTIVE_FLAG);

        /* 보낸 값이 없거나 공백만이면 저장 없음 */
        IF F_LAST_NON_SPACE(P_ACTIVE_FLAG) > 0 THEN
            -- 각 컬럼들에 대한 스플릿처리로직 스타트
            P_SPL_ARR(P_ACTIVE_FLAG, V_MAX_LOOP_CNT, V_ACTIVE_FLAG, V_F_ACTIVE_FLAG);
            P_SPL_ARR(P_DIVISION_ID, V_MAX_LOOP_CNT, V_DIVISION_ID, V_F_DIVISION_ID);
            P_SPL_ARR(P_COMPANY_ID,  V_MAX_LOOP_CNT, V_COMPANY_ID,  V_F_COMPANY_ID);
            P_SPL_ARR(P_YYYYMMDD,    V_MAX_LOOP_CNT, V_YYYYMMDD,    V_F_YYYYMMDD);
            P_SPL_ARR(P_WORKDAY_YN,  V_MAX_LOOP_CNT, V_WORKDAY_YN,  V_F_WORKDAY_YN);

            /* 원장 키에 소문자 · 뒤 공백이 있으면 대소문자 무시 비교 */
            BEGIN
                SELECT 'Y'
                  INTO V_KEY_CI_YN
                  FROM SSP_MST_SHIP_CALENDAR
                 WHERE (DIVISION_ID <> UPPER(RTRIM(DIVISION_ID))
                     OR COMPANY_ID <> UPPER(RTRIM(COMPANY_ID))
                     OR YYYYMMDD <> UPPER(RTRIM(YYYYMMDD)))
                   AND ROWNUM = 1;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    V_KEY_CI_YN := 'N';
            END;

            WHILE V_MST_LOOP_CNT < V_MAX_LOOP_CNT LOOP
                -- @mst_loop_cnt 1증가
                V_MST_LOOP_CNT := V_MST_LOOP_CNT + 1;

                V_DIV  := V_DIVISION_ID(V_MST_LOOP_CNT);
                V_COM  := V_COMPANY_ID(V_MST_LOOP_CNT);
                V_YMD  := V_YYYYMMDD(V_MST_LOOP_CNT);
                V_WORK := V_WORKDAY_YN(V_MST_LOOP_CNT);

                -- 수정
                IF V_KEY_CI_YN = 'Y' THEN
                    UPDATE SSP_MST_SHIP_CALENDAR
                       SET WORKDAY_YN = V_WORK
                         , LAST_UPDATED_BY = P_LAST_UPDATED_BY
                         , LAST_UPDATE_DATE = V_CREATION_DATE
                     WHERE UPPER(RTRIM(DIVISION_ID)) = UPPER(RTRIM(V_DIV))
                       AND UPPER(RTRIM(COMPANY_ID)) = UPPER(RTRIM(V_COM))
                       AND UPPER(RTRIM(YYYYMMDD)) = UPPER(RTRIM(V_YMD));
                ELSE
                    UPDATE SSP_MST_SHIP_CALENDAR
                       SET WORKDAY_YN = V_WORK
                         , LAST_UPDATED_BY = P_LAST_UPDATED_BY
                         , LAST_UPDATE_DATE = V_CREATION_DATE
                     WHERE DIVISION_ID = UPPER(RTRIM(V_DIV))
                       AND COMPANY_ID = UPPER(RTRIM(V_COM))
                       AND YYYYMMDD = UPPER(RTRIM(V_YMD));
                END IF;

                V_UPD_CNT := V_UPD_CNT + SQL%ROWCOUNT;
            END LOOP;
        END IF;

        V_LOG_TYPE    := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := '';
        V_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, V_N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, V_EVENT_DATE);

        COMMIT;

        -- 결과코드, 결과 카운트 반환
        OPEN O_RESULT_CURSOR FOR
            SELECT 'S'       AS RESULT_CODE
                 , V_UPD_CNT AS RESULT_CNT
                 , '0'       AS CODE
                 , 'SUCCESS' AS MSG
              FROM DUAL;

    EXCEPTION
        WHEN OTHERS THEN
            /* SQLCODE · SQLERRM 은 SQL 문 안에서 바로 쓸 수 없으므로 변수로 받는다 */
            V_ERR_CODE    := TO_CHAR(SQLCODE);
            V_ERR_MESSAGE := SUBSTR(SQLERRM, 1, 4000);

            ROLLBACK TO SAVEPOINT SP_SSP0005_SAVE; --입력 데이타 롤백 처리

            INSERT INTO SCM_SYS_LOG_BATCH
                 (
                   PROGRAM_NAME
                 , LOG_TYPE
                 , LOG_COUNT
                 , LOG_MESSAGE
                 , DESCRIPTION
                 , EVENT_DATE
                 , CREATION_DATE
                 , CREATED_BY
                 , LAST_UPDATE_DATE
                 , LAST_UPDATED_BY
                 )
            VALUES
                 (
                   'SSP0005_SAVE_SHIPMENT_WORKING_DAY_ROW'
                 , 'ERROR'
                 , NULL
                 , SUBSTR(V_ERR_MESSAGE, 1, 1000)
                 , NULL
                 , SYSDATE
                 , SYSDATE
                 , 'SSP0005_SAVE_SHIPMENT_WORKING_DAY_ROW'
                 , SYSDATE
                 , 'SSP0005_SAVE_SHIPMENT_WORKING_DAY_ROW'
                 );

            COMMIT;

            -- error코드, errror 메시지 반환
            OPEN O_RESULT_CURSOR FOR
                SELECT 'F'                                        AS RESULT_CODE
                     , '[' || V_ERR_CODE || ']' || V_ERR_MESSAGE  AS ERR_MESSAGE
                     , '-1'                                       AS CODE
                     , '[' || V_ERR_CODE || ']' || V_ERR_MESSAGE  AS MSG
                  FROM DUAL;
    END P_SSP0005_SAVE_SHIPMENT_WORKING_DAY;

END PKG_SSP0005;

PACKAGE BODY PKG_SSP0020
IS
    /*
     * Program ID   : PKG_SSP0020
     * Description  : SSP0020 Delegate 화면 — 담당자 위임 조회 · 설정 · 해제, 사용자 확인
     * Program History
     *===================================================================================================
     *   Date       In Charge      Description
     *===================================================================================================
     * 2026.09.27   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
     */

/****************************************************************************************************/
/* Program ID  : P_GET_DELEGATE                                                                     */
/* Description : Delegate 조회                                                                      */
/****************************************************************************************************/
PROCEDURE P_GET_DELEGATE
(
    P_USER_ID           IN  CLOB
  , P_LANGUAGE          IN  CLOB
  , O_RC1               OUT SYS_REFCURSOR
  , O_RC2               OUT SYS_REFCURSOR
  , O_RESULT_CURSOR     OUT SYS_REFCURSOR
)
IS
    V_USER_ID           VARCHAR2(4000 CHAR) := TO_CHAR(SUBSTR(P_USER_ID,  1, 4000));
    V_LANGUAGE          VARCHAR2(4000 CHAR) := TO_CHAR(SUBSTR(P_LANGUAGE, 1, 4000));
BEGIN

    /* ★원문은 조회문을 문자로 이어 붙여 실행한다. 끼워 넣는 값이 사용자와 언어뿐이라
          문장을 조립할 이유가 없어 정적 조회 두 개로 옮겼다 */

    /* 1. 내가 위임한 것 */
    OPEN O_RC1 FOR
        SELECT A.DIVISION_ID
             , TO_DATE(A.FROM_DATE, 'YYYYMMDD')                     AS FROM_DATE
             , TO_DATE(A.TO_DATE,   'YYYYMMDD')                     AS TO_DATE
             /* 2026.09.30 AJS 수정 (START) */
--             , CASE WHEN V_LANGUAGE = 'KO' THEN B.USERNAME ELSE B.USERNAME_E END
             , CASE WHEN V_LANGUAGE = 'KO' THEN B.USER_NM ELSE B.USER_ENG_NM END
             /* 2026.09.30 AJS 수정 (END) */
               || '(' || A.DELEGATEE_ID || ')'                      AS DELEGATEE
             , A.VALID_YN                                           AS VALID
             /* 2026.09.30 AJS 수정 (START) */
--             , CASE WHEN V_LANGUAGE = 'KO' THEN C.USERNAME ELSE C.USERNAME_E END
             , CASE WHEN V_LANGUAGE = 'KO' THEN C.USER_NM ELSE C.USER_ENG_NM END
             /* 2026.09.30 AJS 수정 (END) */
               || '(' || A.LAST_UPDATED_BY || ')'                   AS LAST_UPDATED_BY
             , A.LAST_UPDATE_DATE
             , A.USER_ID
             , A.DELEGATEE_ID
          FROM SSP_MST_DELEGATE  A
             /* 2026.09.30 AJS 수정 (START) */
--             , TB_FX_USER        B
--             , TB_FX_USER        C
--         WHERE B.USERID    = A.DELEGATEE_ID
--           AND C.USERID    = A.LAST_UPDATED_BY
             , SCM_ADM_USER_M    B
             , SCM_ADM_USER_M    C
         WHERE B.USER_ID   = A.DELEGATEE_ID
           AND C.USER_ID   = A.LAST_UPDATED_BY
             /* 2026.09.30 AJS 수정 (END) */
           AND A.VALID_YN  = 'Y'
           AND A.USER_ID   = V_USER_ID
         ORDER BY FN_ASIS_SORT_KEY(A.DELEGATEE_ID) NULLS FIRST
                , TO_DATE(A.FROM_DATE, 'YYYYMMDD')
                , TO_DATE(A.TO_DATE,   'YYYYMMDD')
                , FN_ASIS_SORT_KEY(A.DIVISION_ID)  NULLS FIRST
                , A.LAST_UPDATE_DATE;

    /* 2. 내가 위임받은 것 */
    OPEN O_RC2 FOR
        SELECT A.DIVISION_ID
             , TO_DATE(A.FROM_DATE, 'YYYYMMDD')                     AS FROM_DATE
             , TO_DATE(A.TO_DATE,   'YYYYMMDD')                     AS TO_DATE
             /* 2026.09.30 AJS 수정 (START) */
--             , CASE WHEN V_LANGUAGE = 'KO' THEN B.USERNAME ELSE B.USERNAME_E END
             , CASE WHEN V_LANGUAGE = 'KO' THEN B.USER_NM ELSE B.USER_ENG_NM END
             /* 2026.09.30 AJS 수정 (END) */
               || '(' || A.USER_ID || ')'                           AS DELEGATOR
             , A.VALID_YN                                           AS VALID
             /* 2026.09.30 AJS 수정 (START) */
--             , CASE WHEN V_LANGUAGE = 'KO' THEN C.USERNAME ELSE C.USERNAME_E END
             , CASE WHEN V_LANGUAGE = 'KO' THEN C.USER_NM ELSE C.USER_ENG_NM END
             /* 2026.09.30 AJS 수정 (END) */
               || '(' || A.LAST_UPDATED_BY || ')'                   AS LAST_UPDATED_BY
             , A.LAST_UPDATE_DATE
          FROM SSP_MST_DELEGATE  A
             /* 2026.09.30 AJS 수정 (START) */
--             , TB_FX_USER        B
--             , TB_FX_USER        C
--         WHERE B.USERID       = A.USER_ID
--           AND C.USERID       = A.LAST_UPDATED_BY
             , SCM_ADM_USER_M    B
             , SCM_ADM_USER_M    C
         WHERE B.USER_ID      = A.USER_ID
           AND C.USER_ID      = A.LAST_UPDATED_BY
             /* 2026.09.30 AJS 수정 (END) */
           AND A.VALID_YN     = 'Y'
           AND A.DELEGATEE_ID = V_USER_ID
         ORDER BY FN_ASIS_SORT_KEY(A.DELEGATEE_ID) NULLS FIRST
                , TO_DATE(A.FROM_DATE, 'YYYYMMDD')
                , TO_DATE(A.TO_DATE,   'YYYYMMDD')
                , FN_ASIS_SORT_KEY(A.DIVISION_ID)  NULLS FIRST
                , A.LAST_UPDATE_DATE;

    OPEN O_RESULT_CURSOR FOR
        SELECT '0'          AS RESULT_CODE
             , 'SUCCESS'    AS RESULT_MESSAGE
          FROM DUAL;

END P_GET_DELEGATE;

/****************************************************************************************************/
/* Program ID  : P_SAVE_DELEGATE                                                                    */
/* Description : Approval Delegate 수정                                                             */
/****************************************************************************************************/
PROCEDURE P_SAVE_DELEGATE
(
    P_DIVISION_ID       IN  CLOB
  , P_DELEGATEE_ID      IN  CLOB
  , P_FROM_DATE         IN  CLOB
  , P_TO_DATE           IN  CLOB
  , P_USER_ID           IN  CLOB
  , P_LANGUAGE          IN  CLOB
  , P_DEBUG_MODE        IN  CLOB      /* 원문도 받기만 하고 쓰지 않는다 */
  , O_RC1               OUT SYS_REFCURSOR
  , O_RESULT_CURSOR     OUT SYS_REFCURSOR
)
IS
    C_DELIMITER         CONSTANT VARCHAR2(1 CHAR) := '^';

    V_DIVISION_ID       VARCHAR2(4000 CHAR);
    V_DELEGATEE_ID      VARCHAR2(4000 CHAR) := TO_CHAR(SUBSTR(P_DELEGATEE_ID, 1, 4000));
    V_FROM_DATE         VARCHAR2(4000 CHAR) := TO_CHAR(SUBSTR(P_FROM_DATE,    1, 4000));
    V_TO_DATE           VARCHAR2(4000 CHAR) := TO_CHAR(SUBSTR(P_TO_DATE,      1, 4000));
    V_USER_ID           VARCHAR2(4000 CHAR) := TO_CHAR(SUBSTR(P_USER_ID,      1, 4000));
    V_LANGUAGE          VARCHAR2(4000 CHAR) := TO_CHAR(SUBSTR(P_LANGUAGE,     1, 4000));

    V_MAX_LOOP_CNT      NUMBER(10) := 0;
    V_MST_LOOP_CNT      NUMBER(10) := 0;

    V_PROGRAM_NAME      VARCHAR2(150 CHAR) := 'SSP0020_SAVE_DELEGATE';
    V_LOG_TYPE          VARCHAR2(30 CHAR);
    N_LOG_COUNT         NUMBER(10) := 0;
    V_LOG_MESSAGE       VARCHAR2(1000 CHAR);
    V_DESCRIPTION       VARCHAR2(500 CHAR);
    D_EVENT_DATE        DATE;
    V_SQLERRM           VARCHAR2(4000 CHAR);
BEGIN

    D_EVENT_DATE := SYSDATE;

    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '';
    PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    V_MAX_LOOP_CNT := SCM_ARR_SPL_CNT(P_DIVISION_ID, C_DELIMITER);

    WHILE LENGTH(P_DIVISION_ID) > 0
      AND V_MST_LOOP_CNT < V_MAX_LOOP_CNT
    LOOP

        V_MST_LOOP_CNT := V_MST_LOOP_CNT + 1;

        V_DIVISION_ID  := SCM_ARR_SPL_VAL(P_DIVISION_ID, C_DELIMITER, V_MST_LOOP_CNT);

        /* 데이터 저장 */
        IF V_MST_LOOP_CNT > 0
        THEN

            INSERT INTO SSP_MST_DELEGATE
                        (
                          DIVISION_ID
                        , USER_ID
                        , DELEGATEE_ID
                        , FROM_DATE
                        , TO_DATE
                        , VALID_YN
                        , CREATED_BY
                        , CREATION_DATE
                        , LAST_UPDATED_BY
                        , LAST_UPDATE_DATE
                        )
                 VALUES (
                          V_DIVISION_ID
                        , V_USER_ID
                        , V_DELEGATEE_ID
                        , V_FROM_DATE
                        , V_TO_DATE
                        , 'Y'
                        , V_USER_ID
                        , D_EVENT_DATE
                        , V_USER_ID
                        , D_EVENT_DATE
                        );

        END IF;

    END LOOP;

    /* MAIL SEND */
    PR_SSP_MAIL_SEND_DELEGATE('S', TO_CHAR(SUBSTR(P_DIVISION_ID, 1, 4000)), V_USER_ID
                            , V_DELEGATEE_ID, V_FROM_DATE, V_TO_DATE, V_LANGUAGE, 'Y');

    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    COMMIT;

    /* 결과코드 리턴 */
    OPEN O_RC1 FOR
        SELECT 'S'              AS RESULT_CODE
             , V_MST_LOOP_CNT   AS RESULT_CNT
          FROM DUAL;

    OPEN O_RESULT_CURSOR FOR
        SELECT '0'          AS RESULT_CODE
             , 'SUCCESS'    AS RESULT_MESSAGE
          FROM DUAL;

EXCEPTION
    WHEN OTHERS THEN
        V_SQLERRM := SQLERRM;

        ROLLBACK;

        INSERT INTO SCM_SYS_LOG_BATCH
                    (
                      PROGRAM_NAME, LOG_TYPE, LOG_COUNT, LOG_MESSAGE, DESCRIPTION
                    , EVENT_DATE, CREATION_DATE, CREATED_BY, LAST_UPDATE_DATE, LAST_UPDATED_BY
                    )
             VALUES (
                      V_PROGRAM_NAME, 'ERROR', NULL, V_SQLERRM, NULL
                    , SYSDATE, SYSDATE, V_PROGRAM_NAME, SYSDATE, V_PROGRAM_NAME
                    );

        COMMIT;

        OPEN O_RC1 FOR
            SELECT 'F'                          AS RESULT_CODE
                 , SUBSTR(V_SQLERRM, 1, 4000)   AS RESULT_CNT
              FROM DUAL;

        OPEN O_RESULT_CURSOR FOR
            SELECT '1'                          AS RESULT_CODE
                 , SUBSTR(V_SQLERRM, 1, 4000)   AS RESULT_MESSAGE
              FROM DUAL;

END P_SAVE_DELEGATE;

/****************************************************************************************************/
/* Program ID  : P_SAVE_UNSET                                                                       */
/* Description : Delegate 설정해제                                                                  */
/****************************************************************************************************/
PROCEDURE P_SAVE_UNSET
(
    P_DIVISION_ID       IN  CLOB
  , P_FROM_DATE         IN  CLOB
  , P_TO_DATE           IN  CLOB
  , P_SHEET_NAME        IN  CLOB
  , P_DELEGATE          IN  CLOB
  , P_LAST_UPDATE_BY    IN  CLOB
  , P_LAST_UPDATE_DATE  IN  CLOB      /* 원문도 받기만 하고 쓰지 않는다 */
  , P_USER_ID           IN  CLOB
  , P_LANGUAGE          IN  CLOB
  , O_RC1               OUT SYS_REFCURSOR
  , O_RESULT_CURSOR     OUT SYS_REFCURSOR
)
IS
    C_DELIMITER         CONSTANT VARCHAR2(1 CHAR) := '^';

    V_DIVISION_ID       VARCHAR2(4000 CHAR);
    V_FROM_DATE         VARCHAR2(4000 CHAR) := TO_CHAR(SUBSTR(P_FROM_DATE,      1, 4000));
    V_TO_DATE           VARCHAR2(4000 CHAR) := TO_CHAR(SUBSTR(P_TO_DATE,        1, 4000));
    V_SHEET_NAME        VARCHAR2(4000 CHAR) := TO_CHAR(SUBSTR(P_SHEET_NAME,     1, 4000));
    V_DELEGATE          VARCHAR2(4000 CHAR) := TO_CHAR(SUBSTR(P_DELEGATE,       1, 4000));
    V_LAST_UPDATE_BY    VARCHAR2(4000 CHAR) := TO_CHAR(SUBSTR(P_LAST_UPDATE_BY, 1, 4000));
    V_USER_ID           VARCHAR2(4000 CHAR) := TO_CHAR(SUBSTR(P_USER_ID,        1, 4000));
    V_LANGUAGE          VARCHAR2(4000 CHAR) := TO_CHAR(SUBSTR(P_LANGUAGE,       1, 4000));

    V_MAIL_DIVISIONID   VARCHAR2(4000 CHAR);

    V_MAX_LOOP_CNT      NUMBER(10) := 0;
    V_MST_LOOP_CNT      NUMBER(10) := 0;

    V_PROGRAM_NAME      VARCHAR2(150 CHAR) := 'SSP0020_SAVE_UNSET';
    V_LOG_TYPE          VARCHAR2(30 CHAR);
    N_LOG_COUNT         NUMBER(10) := 0;
    V_LOG_MESSAGE       VARCHAR2(1000 CHAR);
    V_DESCRIPTION       VARCHAR2(500 CHAR);
    D_EVENT_DATE        DATE;
    V_SQLERRM           VARCHAR2(4000 CHAR);
BEGIN

    D_EVENT_DATE := SYSDATE;

    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '';
    PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    V_MAX_LOOP_CNT := SCM_ARR_SPL_CNT(P_DIVISION_ID, C_DELIMITER);

    WHILE LENGTH(P_DIVISION_ID) > 0
      AND V_MST_LOOP_CNT < V_MAX_LOOP_CNT
    LOOP

        V_MST_LOOP_CNT := V_MST_LOOP_CNT + 1;

        V_DIVISION_ID  := SCM_ARR_SPL_VAL(P_DIVISION_ID, C_DELIMITER, V_MST_LOOP_CNT);

        /* 데이터 저장 */
        IF V_MST_LOOP_CNT > 0
        THEN

            IF V_SHEET_NAME = 'Delegate'
            THEN

                UPDATE SSP_MST_DELEGATE
                   SET VALID_YN         = 'N'
                     , LAST_UPDATED_BY  = V_USER_ID
                     , LAST_UPDATE_DATE = D_EVENT_DATE
                 WHERE DIVISION_ID      = V_DIVISION_ID
                   AND FROM_DATE        = V_FROM_DATE
                   AND TO_DATE          = V_TO_DATE
                   AND DELEGATEE_ID     = V_DELEGATE
                   AND LAST_UPDATED_BY  = V_LAST_UPDATE_BY;

            ELSE

                UPDATE SSP_MST_DELEGATE
                   SET VALID_YN         = 'N'
                     , LAST_UPDATED_BY  = V_USER_ID
                     , LAST_UPDATE_DATE = D_EVENT_DATE
                 WHERE DIVISION_ID      = V_DIVISION_ID
                   AND FROM_DATE        = V_FROM_DATE
                   AND TO_DATE          = V_TO_DATE
                   AND DELEGATEE_ID     = V_USER_ID
                   AND LAST_UPDATED_BY  = V_LAST_UPDATE_BY;

            END IF;

        END IF;

    END LOOP;

    V_MAIL_DIVISIONID := REPLACE(TO_CHAR(SUBSTR(P_DIVISION_ID, 1, 4000)), C_DELIMITER, ', ');

    /* MAIL SEND */
    PR_SSP_MAIL_SEND_DELEGATE('U', V_MAIL_DIVISIONID, V_USER_ID
                            , V_DELEGATE, V_FROM_DATE, V_TO_DATE, V_LANGUAGE, 'Y');

    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    COMMIT;

    /* 결과코드 리턴 */
    OPEN O_RC1 FOR
        SELECT 'S'              AS RESULT_CODE
             , V_MST_LOOP_CNT   AS RESULT_CNT
          FROM DUAL;

    OPEN O_RESULT_CURSOR FOR
        SELECT '0'          AS RESULT_CODE
             , 'SUCCESS'    AS RESULT_MESSAGE
          FROM DUAL;

EXCEPTION
    WHEN OTHERS THEN
        V_SQLERRM := SQLERRM;

        ROLLBACK;

        INSERT INTO SCM_SYS_LOG_BATCH
                    (
                      PROGRAM_NAME, LOG_TYPE, LOG_COUNT, LOG_MESSAGE, DESCRIPTION
                    , EVENT_DATE, CREATION_DATE, CREATED_BY, LAST_UPDATE_DATE, LAST_UPDATED_BY
                    )
             VALUES (
                      V_PROGRAM_NAME, 'ERROR', NULL, V_SQLERRM, NULL
                    , SYSDATE, SYSDATE, V_PROGRAM_NAME, SYSDATE, V_PROGRAM_NAME
                    );

        COMMIT;

        OPEN O_RC1 FOR
            SELECT 'F'                          AS RESULT_CODE
                 , SUBSTR(V_SQLERRM, 1, 4000)   AS RESULT_CNT
              FROM DUAL;

        OPEN O_RESULT_CURSOR FOR
            SELECT '1'                          AS RESULT_CODE
                 , SUBSTR(V_SQLERRM, 1, 4000)   AS RESULT_MESSAGE
              FROM DUAL;

END P_SAVE_UNSET;

/****************************************************************************************************/
/* Program ID  : P_USER_CHECK                                                                       */
/* Description : SSP 사용자 LIST — 사용자 정보 조회                                                 */
/*               (AS-IS 공용 UP_FX_GetSSPUserUseInfoList · 이 화면만 부른다)                        */
/****************************************************************************************************/
PROCEDURE P_USER_CHECK
(
    P_SEARCH            IN  CLOB
  , P_LANGUAGE          IN  CLOB      /* 원문도 받기만 하고 쓰지 않는다 (사용자 원장의 언어로 판단) */
  , P_USEYN             IN  CLOB
  , O_RC1               OUT SYS_REFCURSOR
  , O_RESULT_CURSOR     OUT SYS_REFCURSOR
)
IS
    /* 원문이 찾는 값을 NVARCHAR(12)·사용여부를 NVARCHAR(1) 로 받아 그 길이에서 자른다 */
    V_SEARCH            VARCHAR2(12 CHAR) := TO_CHAR(SUBSTR(P_SEARCH, 1, 12));
    /* V_USEYN             VARCHAR2(1 CHAR)  := TO_CHAR(SUBSTR(P_USEYN,  1, 1)); */
    V_USEYN             VARCHAR2(1 CHAR)  := NVL(TO_CHAR(SUBSTR(P_USEYN,  1, 1)), 'Y');   /* AJS 20261007 화면검증 */
BEGIN

    OPEN O_RC1 FOR
        SELECT A.USERID
             , A.USERNAME
             , A.USERNAME_E
             , A.EMAIL
             , A.DEPT_ID
             , CASE A.LANGUAGE
                    WHEN 'KO' THEN (SELECT XA.DEPT_NAME_KO
                                      FROM SCM_MST_SSO_DEPT_INFO XA
                                     WHERE XA.DEPT_ID = A.DEPT_ID)
                    WHEN 'EN' THEN (SELECT XB.DEPT_NAME_EN
                                      FROM SCM_MST_SSO_DEPT_INFO XB
                                     WHERE XB.DEPT_ID = A.DEPT_ID)
                    WHEN 'CN' THEN (SELECT XC.DEPT_NAME_CN
                                      FROM SCM_MST_SSO_DEPT_INFO XC
                                     WHERE XC.DEPT_ID = A.DEPT_ID)
               END                                                  AS DEPT_NAME
             , A.OFFICEPHONENUM
             , A.CELLPHONENUM
             , A.LANGUAGE
             , A.DEFAULTGROUPID
             , (SELECT XD.GRPNAME
                  FROM TB_FX_GROUPINFO     XD
                     , TB_FX_USERGROUPINFO XE
                 WHERE XD.GROUPID = XE.GROUPID
                   AND XE.USERID  = A.USERID
                   AND XE.GROUPID = A.DEFAULTGROUPID)               AS GRPNAME
             , A.TIMEZONE
             , A.LASTLOGINDATETIME
             , A.USEYN
             , A.REGTUSERID
             , A.ATTRIBUTE1
             , A.ATTRIBUTE2
             , A.ATTRIBUTE3
             , A.ATTRIBUTE4
             , A.ATTRIBUTE5
             , A.ATTRIBUTE6
             , A.ATTRIBUTE7
             , A.ATTRIBUTE8
             , A.ATTRIBUTE9
             , A.ATTRIBUTE10
          FROM TB_FX_USER A
         WHERE A.USEYN = V_USEYN
           /* AS-IS 는 대소문자를 가리지 않는다. 사용자 번호 · 이름 세 칸 모두 대문자로 맞춘다.
              ★원문은 찾는 값이 없을 때만 통과시키는 조건을 세 번 이어 붙여 두었다(값이 있으면
                세 칸 중 하나라도 맞으면 통과). 원문 그대로 옮긴다 */
           AND (   (V_SEARCH IS NULL OR UPPER(A.USERID)     LIKE '%' || UPPER(V_SEARCH) || '%')
                OR (V_SEARCH IS NULL OR UPPER(A.USERNAME)   LIKE '%' || UPPER(V_SEARCH) || '%')
                OR (V_SEARCH IS NULL OR UPPER(A.USERNAME_E) LIKE '%' || UPPER(V_SEARCH) || '%'))
         /* 원문에 정렬이 없어 화면 순서가 흔들린다 — 사용자 번호 순으로 고정 */
         ORDER BY FN_ASIS_SORT_KEY(A.USERID) NULLS FIRST;

    OPEN O_RESULT_CURSOR FOR
        SELECT '0'          AS RESULT_CODE
             , 'SUCCESS'    AS RESULT_MESSAGE
          FROM DUAL;

END P_USER_CHECK;

END PKG_SSP0020;

