        PROCEDURE OPEN_RS
        (
            P_RC    IN OUT SYS_REFCURSOR,
            P_KIND  IN VARCHAR2,
            P_CODE  IN VARCHAR2,
            P_VAL1  IN VARCHAR2,
            P_VAL2  IN VARCHAR2,
            P_VAL3  IN VARCHAR2
        )
