                    SELECT P_CODE AS RESULT_CODE
                         , P_VAL1 AS REASON_ID
                         , P_VAL2 AS DIVISION_ID
                         , P_VAL3 AS TO_SITE
                      FROM DUAL;
            ELSIF P_KIND = 'S' THEN
                OPEN P_RC FOR
                    SELECT P_CODE AS RESULT_CODE
                         , P_VAL1 AS "ConfrimID"
                      FROM DUAL;
            ELSE
                OPEN P_RC FOR
                    SELECT P_CODE AS RESULT_CODE
                      FROM DUAL;
            END IF;
        END OPEN_RS;

        PROCEDURE OPEN_ALL_RS
        IS
        BEGIN
            OPEN_RS(O_RC1, V_RS1_KIND, V_RS1_CODE, V_RS1_VAL1, V_RS1_VAL2, V_RS1_VAL3);
            IF V_RS_CNT >= 2 THEN
                OPEN_RS(O_RC3, V_RSL_KIND, V_RSL_CODE, V_RSL_VAL1, V_RSL_VAL2, V_RSL_VAL3);
            ELSE
                OPEN O_RC3 FOR
                    SELECT CAST(NULL AS VARCHAR2(1)) AS RESULT_CODE
                      FROM DUAL
                     WHERE 1 = 0;
            END IF;
        END OPEN_ALL_RS;

        /* ------------------------------------------------------------
           AS-IS SCM_ARR_SPL_VAL 이 해당 순번에서 값('' 포함)을 돌려주는지 여부
           (Oracle 은 '' 와 NULL 을 구분하지 못하므로 토큰 존재 여부를 따로 판정)
           ------------------------------------------------------------ */
        FUNCTION FN_SPL_EXISTS
        (
            P_TEXT  IN VARCHAR2,
            P_IDX   IN PLS_INTEGER
        )
        RETURN BOOLEAN
        IS
            V_DATA   VARCHAR2(32767 CHAR) := TRIM(P_TEXT) || '^';
            V_WORD   VARCHAR2(32767 CHAR);
            V_FOUND  BOOLEAN := FALSE;
        BEGIN
            FOR I IN 1 .. P_IDX LOOP
                IF INSTR(V_DATA, '^') > 0 THEN
                    V_WORD  := TRIM(SUBSTR(V_DATA, 1, INSTR(V_DATA, '^') - 1));
                    V_DATA  := TRIM(SUBSTR(V_DATA, NVL(LENGTH(V_WORD), 0) + 2));
                    V_FOUND := TRUE;
                ELSE
                    V_FOUND := FALSE;
                END IF;
            END LOOP;
            RETURN V_FOUND;
        END FN_SPL_EXISTS;

        /* AS-IS nvarchar -> int/bigint 암묵 변환(정수 형식만 허용, 아니면 변환 오류) */
        FUNCTION FN_TO_INT
        (
            P_VAL   IN VARCHAR2,
            P_MAX   IN NUMBER
        )
        RETURN NUMBER
        IS
            V_NUM   NUMBER;
        BEGIN
            IF P_VAL IS NULL THEN
                RETURN NULL;
            END IF;
            IF NOT REGEXP_LIKE(P_VAL, '^\s*[+-]?[0-9]+\s*$') THEN
                RAISE_APPLICATION_ERROR(-20001, 'Conversion failed when converting the nvarchar value ''' || SUBSTR(P_VAL, 1, 100) || ''' to data type int.');
            END IF;
            V_NUM := TO_NUMBER(TRIM(P_VAL));
            IF ABS(V_NUM) > P_MAX THEN
                RAISE_APPLICATION_ERROR(-20001, 'Arithmetic overflow error converting expression to data type int.');
            END IF;
            RETURN V_NUM;
        END FN_TO_INT;

        /* AS-IS nvarchar -> numeric(20,10) 암묵 변환('' 는 변환 오류, 소수 10자리 반올림, 정수부 10자리 초과는 overflow) */
        FUNCTION FN_TO_NUM_20_10
        (
            P_VAL   IN VARCHAR2
        )
        RETURN NUMBER
        IS
            V_NUM   NUMBER;
        BEGIN
            IF P_VAL IS NULL
            OR NOT REGEXP_LIKE(P_VAL, '^\s*[+-]?([0-9]+\.?[0-9]*|\.[0-9]+)\s*$') THEN
                RAISE_APPLICATION_ERROR(-20001, 'Error converting data type nvarchar to numeric.');
            END IF;
            V_NUM := ROUND(TO_NUMBER(TRIM(P_VAL)), 10);
            IF ABS(V_NUM) >= 10000000000 THEN
                RAISE_APPLICATION_ERROR(-20001, 'Arithmetic overflow error converting nvarchar to data type numeric.');
            END IF;
            RETURN V_NUM;
        END FN_TO_NUM_20_10;

        /* ------------------------------------------------------------
           AS-IS dbo.FN_GET_SSP_SITE_INFO (ERP전송을 위한 SITE 정보)
           ※ 사이트가 없으면 AS-IS 는 '' 반환 → Oracle NULL
           ------------------------------------------------------------ */
        FUNCTION FN_SITE_INFO
        (
            P_DIVISION_ID   IN VARCHAR2,
            P_SCM_SITE_ID   IN VARCHAR2,
            P_RETURN_TYPE   IN VARCHAR2
        )
        RETURN VARCHAR2
        IS
            V_SITE_TYPE     VARCHAR2(100 CHAR);
            V_PLANT_ID      VARCHAR2(100 CHAR);
            V_VENDOR_ID     VARCHAR2(100 CHAR);
            V_SOLDTO_CODE   VARCHAR2(100 CHAR);
            V_SHIPTO_CODE   VARCHAR2(100 CHAR);
            V_COMPANY_ID    VARCHAR2(100 CHAR);
            V_COUNTRY       VARCHAR2(100 CHAR);
            V_VMI_YN        VARCHAR2(100 CHAR);
        BEGIN
            BEGIN
                SELECT CASE WHEN UPPER(A.SITE_TYPE) = 'SALES'                             THEN 'A'   /* Sales Site' */
                            WHEN UPPER(A.SITE_TYPE) = 'PLANT' AND UPPER(A.OSP_YN) = 'N' THEN 'B'   /* Factory Site */
                            WHEN UPPER(A.SITE_TYPE) = 'PLANT' AND UPPER(A.OSP_YN) = 'Y' THEN 'C'   /* Packer */
                       END
                     , A.LOGISTIC_PLANT_ID
                     , CASE WHEN UPPER(A.SITE_TYPE) = 'PLANT' AND UPPER(A.OSP_YN) = 'Y' THEN A.PLANT_ID END
                     , B.SOLDTO_CODE
                     , B.SHIPTO_CODE
                     , A.COMPANY_ID
                     , A.COUNTRY
                     , A.VMI_YN
                  INTO V_SITE_TYPE
                     , V_PLANT_ID
                     , V_VENDOR_ID
                     , V_SOLDTO_CODE
                     , V_SHIPTO_CODE
                     , V_COMPANY_ID
                     , V_COUNTRY
                     , V_VMI_YN
                  FROM SCM_MST_SITE          A
                     , SCM_MST_SITE_CUSTOMER B
                 WHERE B.DIVISION_ID(+) = A.DIVISION_ID
                   AND B.SCM_SITE_ID(+) = A.SCM_SITE_ID
                   AND B.VALID_YN(+)    = 'Y'
                   AND B.REP_YN(+)      = 'Y'
                   AND A.VALID_YN       = 'Y'
                   AND A.DIVISION_ID    = P_DIVISION_ID
                   AND UPPER(A.SCM_SITE_ID) = UPPER(P_SCM_SITE_ID)
                   AND ROWNUM           = 1;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    NULL;
            END;

            IF P_RETURN_TYPE = 'SITE_TYPE' THEN
                RETURN V_SITE_TYPE;
            ELSIF P_RETURN_TYPE = 'PLANT_ID' THEN
                RETURN V_PLANT_ID;
            ELSIF P_RETURN_TYPE = 'VENDOR_ID' THEN
                RETURN V_VENDOR_ID;
            ELSIF P_RETURN_TYPE = 'SOLDTO_CODE' THEN
                RETURN V_SOLDTO_CODE;
            ELSIF P_RETURN_TYPE = 'SHIPTO_CODE' THEN
                RETURN V_SHIPTO_CODE;
            ELSIF P_RETURN_TYPE = 'COMPANY_ID' THEN
                RETURN V_COMPANY_ID;
            ELSIF P_RETURN_TYPE = 'COUNTRY' THEN
                RETURN V_COUNTRY;
            ELSIF P_RETURN_TYPE = 'VMI_YN' THEN
                RETURN V_VMI_YN;
            END IF;
            RETURN NULL;
        END FN_SITE_INFO;

        /* ------------------------------------------------------------
           AS-IS dbo.FN_GET_SSP_SITE_INFO_EXCEPTION
           ([E20250821-001308] FROM SITE 의 PLANT_ID 에 따라 TO 의 COMPANY_ID / SITE_TYPE 예외 적용,
            예외는 lookup type ssp_site_info_exception 에 정의)
           ------------------------------------------------------------ */
        FUNCTION FN_SITE_INFO_EXCEPTION
        (
            P_DIVISION_ID       IN VARCHAR2,
            P_FROM_SCM_SITE_ID  IN VARCHAR2,
            P_TO_SCM_SITE_ID    IN VARCHAR2,
            P_RETURN_TYPE       IN VARCHAR2
        )
        RETURN VARCHAR2
        IS
            V_PLANT_ID          VARCHAR2(100 CHAR);
            V_EXCEPTION_VALUE   VARCHAR2(100 CHAR);
        BEGIN
            /* company_id 타입 아닌 경우는 from_site 무시하고 fn_get_ssp_site_info를 그대로 사용한다 */
            IF P_RETURN_TYPE NOT IN ('COMPANY_ID', 'SITE_TYPE') THEN
                RETURN FN_SITE_INFO(P_DIVISION_ID, P_TO_SCM_SITE_ID, P_RETURN_TYPE);
            END IF;

            /* to_site에 대한 예외가 존재하 */
            V_PLANT_ID := FN_SITE_INFO(P_DIVISION_ID, P_FROM_SCM_SITE_ID, 'PLANT_ID');

            IF P_TO_SCM_SITE_ID IS NULL THEN
                RETURN FN_SITE_INFO(P_DIVISION_ID, P_TO_SCM_SITE_ID, P_RETURN_TYPE);
            END IF;

            BEGIN
                SELECT SEGMENT5
                  INTO V_EXCEPTION_VALUE
                  FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                 WHERE 1 = 1
                   AND UPPER(LOOKUP_TYPE) = 'SSP_SITE_INFO_EXCEPTION'
                   AND (   SEGMENT4 = V_PLANT_ID   /* plant_id of from_sizte */
                        OR SEGMENT4 = '-'
                       )
                   AND UPPER(SEGMENT1)    = P_RETURN_TYPE
                   AND SEGMENT2           = P_DIVISION_ID
                   AND UPPER(SEGMENT3)    = UPPER(P_TO_SCM_SITE_ID)   /* to_site */
                   AND UPPER(VALID_YN)    = 'Y'
                   AND ROWNUM             = 1;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    V_EXCEPTION_VALUE := NULL;
            END;

            IF TRIM(V_EXCEPTION_VALUE) IS NULL THEN
                RETURN FN_SITE_INFO(P_DIVISION_ID, P_TO_SCM_SITE_ID, P_RETURN_TYPE);
            END IF;
            RETURN V_EXCEPTION_VALUE;
        END FN_SITE_INFO_EXCEPTION;

    BEGIN

        SAVEPOINT SP_SSP0200_SAVE_CFM_NEW;

        /* 시작 LOG */
        V_LOG_TYPE    := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
        COMMIT;

        V_MAX_LOOP_CNT := SCM_ARR_SPL_CNT(P_ACTIVE_FLAG, V_DELIMITER);

        WHILE LENGTH(RTRIM(P_ACTIVE_FLAG)) > 0 AND V_MST_LOOP_CNT < V_MAX_LOOP_CNT
        LOOP

            /* 행 단위 되돌림 지점(AS-IS 는 문장마다 확정) */
            SAVEPOINT SP_SSP0200_SAVE_CFM_NEW;

            /* @mst_loop_cnt 1증가 */
            V_MST_LOOP_CNT := V_MST_LOOP_CNT + 1;

            /* 각 컬럼들에 대한 스플릿처리로직 스타트 */
            V_ACTIVE_FLAG        := SCM_ARR_SPL_VAL(P_ACTIVE_FLAG,    V_DELIMITER, V_MST_LOOP_CNT);
            V_DIVISION_ID        := SCM_ARR_SPL_VAL(P_DIVISION_ID,    V_DELIMITER, V_MST_LOOP_CNT);
            V_FROM_SITE          := SCM_ARR_SPL_VAL(P_FROM_SITE,      V_DELIMITER, V_MST_LOOP_CNT);
            V_TO_SITE            := SCM_ARR_SPL_VAL(P_TO_SITE,        V_DELIMITER, V_MST_LOOP_CNT);
            V_PROJECT_CODE_40    := SCM_ARR_SPL_VAL(P_PROJECT_CODE40, V_DELIMITER, V_MST_LOOP_CNT);
            V_PROJECT_CODE       := SCM_ARR_SPL_VAL(P_PROJECT_CODE,   V_DELIMITER, V_MST_LOOP_CNT);
            V_FCST_TYPE          := SCM_ARR_SPL_VAL(P_FCST_TYPE,      V_DELIMITER, V_MST_LOOP_CNT);
            V_ITEM_ID            := SCM_ARR_SPL_VAL(P_ITEM_ID,        V_DELIMITER, V_MST_LOOP_CNT);
            V_SHIPMENT_DATE      := SCM_ARR_SPL_VAL(P_SHIPMENT_DATE,  V_DELIMITER, V_MST_LOOP_CNT);
            V_SHIPMENT_QTY       := SCM_ARR_SPL_VAL(P_SHIPMENT_QTY,   V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_INCOTERMS      := SCM_ARR_SPL_VAL(P_INCOTERMS,      V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_TRANSPORT_MODE := SCM_ARR_SPL_VAL(P_TRANSPORT_MODE, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_CUSTOMER_LT    := SCM_ARR_SPL_VAL(P_LT,             V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_ETD_DATE       := SCM_ARR_SPL_VAL(P_ETD,            V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_ETA_DATE       := SCM_ARR_SPL_VAL(P_ETA,            V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_ROUTE_ID       := SCM_ARR_SPL_VAL(P_ROUTE_ID,       V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_BOD_ID         := SCM_ARR_SPL_VAL(P_BOD_ID,         V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_D_CONTRY       := SCM_ARR_SPL_VAL(P_D_COUNTRY,      V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_D_PORT_CODE    := SCM_ARR_SPL_VAL(P_D_PORT_CODE,    V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_A_COUNTRY      := SCM_ARR_SPL_VAL(P_A_CONUNTRY,     V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_A_PORT_CODE    := SCM_ARR_SPL_VAL(P_A_PORT_CODE,    V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_TO_COUNTRY     := SCM_ARR_SPL_VAL(P_TO_COUNTRY,     V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_TO_CITY        := SCM_ARR_SPL_VAL(P_TO_CITY,        V_DELIMITER, V_MST_LOOP_CNT);
            V_REMARKS            := SCM_ARR_SPL_VAL(P_REMARKS,        V_DELIMITER, V_MST_LOOP_CNT);
            V_REMARKS2           := SCM_ARR_SPL_VAL(P_REMARKS2,       V_DELIMITER, V_MST_LOOP_CNT);
            V_REMARKS3           := SCM_ARR_SPL_VAL(P_REMARKS3,       V_DELIMITER, V_MST_LOOP_CNT);

            /**** 20211018   SHINMYUNGSU   항목추가   ******************************************************************/
            V_ERP_ATTR1          := SCM_ARR_SPL_VAL(P_ERP_ATTR1,      V_DELIMITER, V_MST_LOOP_CNT);
            V_ERP_ATTR2          := SCM_ARR_SPL_VAL(P_ERP_ATTR2,      V_DELIMITER, V_MST_LOOP_CNT);
            V_ERP_ATTR3          := SCM_ARR_SPL_VAL(P_ERP_ATTR3,      V_DELIMITER, V_MST_LOOP_CNT);
            /***********************************************************************************************************/

            V_PROJECT_CODE_EXISTS  := FN_SPL_EXISTS(P_PROJECT_CODE,  V_MST_LOOP_CNT);
            V_ITEM_ID_EXISTS       := FN_SPL_EXISTS(P_ITEM_ID,       V_MST_LOOP_CNT);
            V_SHIPMENT_DATE_EXISTS := FN_SPL_EXISTS(P_SHIPMENT_DATE, V_MST_LOOP_CNT);
            V_SHIPMENT_QTY_EXISTS  := FN_SPL_EXISTS(P_SHIPMENT_QTY,  V_MST_LOOP_CNT);

            /* start E20260514-001358 TO_ shipto / soldto 없는 경우 출하 금지 */
            V_DIVISION_ID_OR := V_DIVISION_ID;
            V_TO_SITE_OR     := V_TO_SITE;

            /* BOD 유효기간 비교 : AS-IS 는 'YYYY-MM-DD HH:MI:SS.MMM' 문자열을 'YYYYMMDD' 칸과 비교(하이픈 무시 정렬) */
            V_SHIP_DATE_KEY := REPLACE(V_SHIPMENT_DATE, '-', '');

            /* 우선순위 1순위 BOD 정보로 치환(없으면 입력값 유지 - AS-IS SELECT TOP 1 변수 대입과 동일) */
            V_BOD_FOUND := FALSE;
            BEGIN
                SELECT IA.DIVISION_ID
                     , IA.BOD_ID
                     , IA.FROM_SITE
                     , IA.TO_SITE
                     , IA.SSP_INCOTERMS
                     , IA.TRANSPORT_MODE
                     , IA.ROUTE_ID
                     , IA.D_COUNTRY
                     , IA.D_PORT_CODE
                     , IA.A_COUNTRY
                     , IA.A_PORT_CODE
                     , IA.LT_TOTAL
                     , IA.TO_COUNTRY
                     , IA.TO_CITY
                  INTO V_DIVISION_ID
                     , V_NEW_BOD_ID
                     , V_FROM_SITE
                     , V_TO_SITE
                     , V_NEW_INCOTERMS
                     , V_NEW_TRANSPORT_MODE
                     , V_NEW_ROUTE_ID
                     , V_NEW_D_CONTRY
                     , V_NEW_D_PORT_CODE
                     , V_NEW_A_COUNTRY
                     , V_NEW_A_PORT_CODE
                     , V_NEW_CUSTOMER_LT
                     , V_NEW_TO_COUNTRY
                     , V_NEW_TO_CITY
                  FROM (SELECT DISTINCT
                               B.DIVISION_ID
                             , B.BOD_ID
                             , B.FROM_SITE
                             , B.TO_SITE
                             , B.SSP_INCOTERMS
                             , B.TRANSPORT_MODE
                             , TO_CHAR(B.ROUTE_ID) AS ROUTE_ID
                             , B.D_COUNTRY
                             , B.D_PORT_CODE
                             , B.A_COUNTRY
                             , B.A_PORT_CODE
                             , TO_CHAR(B.LT_TOTAL) AS LT_TOTAL
                             , B.LT_TOTAL_ORIGIN
                             , B.TO_COUNTRY
                             , B.TO_CITY
                             , B.PRIORITY
                             , B.BOD_VALID_YN
                          FROM SCP_MST_BOD_N_V B
                         WHERE EXISTS (SELECT 1
                                         FROM SCP_MST_BOD_ITEM XA
                                        WHERE XA.DIVISION_ID = B.DIVISION_ID
                                          AND XA.BOD_ID      = B.BOD_ID
                                          AND XA.DIVISION_ID = V_DIVISION_ID
                                          AND UPPER(XA.ITEM_ID) = UPPER(V_ITEM_ID))
                           AND UPPER(B.BOD_VALID_YN)   = 'Y'
                           AND B.DIVISION_ID           = V_DIVISION_ID
                           AND UPPER(B.FROM_SITE)      = UPPER(V_FROM_SITE)
                           AND UPPER(B.TO_SITE)        = UPPER(V_TO_SITE)
                           AND UPPER(B.TRANSPORT_MODE) = UPPER(V_NEW_TRANSPORT_MODE)
                           AND UPPER(B.SSP_INCOTERMS)  = UPPER(V_NEW_INCOTERMS)
                           AND B.FROM_YYYYMMDD        <= V_SHIP_DATE_KEY
                           AND B.TO_YYYYMMDD          >= V_SHIP_DATE_KEY
                         ORDER BY B.PRIORITY NULLS FIRST
                                , B.BOD_ID
                                , ROUTE_ID
                       ) IA
                 WHERE ROWNUM = 1;
                V_BOD_FOUND := TRUE;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    V_BOD_FOUND := FALSE;
            END;

            IF (   V_DIVISION_ID        IS NULL
                OR V_NEW_BOD_ID         IS NULL
                OR V_FROM_SITE          IS NULL
                OR V_TO_SITE            IS NULL
                OR V_NEW_INCOTERMS      IS NULL
                OR V_NEW_TRANSPORT_MODE IS NULL
                OR V_NEW_ROUTE_ID       IS NULL
                OR V_NEW_D_CONTRY       IS NULL
                OR V_NEW_D_PORT_CODE    IS NULL
                OR V_NEW_A_COUNTRY      IS NULL
                OR V_NEW_A_PORT_CODE    IS NULL
                OR V_NEW_CUSTOMER_LT    IS NULL
                OR V_NEW_TO_COUNTRY     IS NULL
                OR V_NEW_TO_CITY        IS NULL
               ) THEN

                ADD_RS('C', 'X');
                V_LOG_TYPE    := 'END';
                V_LOG_MESSAGE := '########## END of procedure ##########';
                /* SET @v_description = 'Confrim_ID : ' + @v_new_confirm_id + ' / Time Zone : ' + @v_tmp_fn_time_zone + ' / Seq : ' + @v_tmp_seq_confirm; */
                D_EVENT_DATE  := SYSDATE;
                PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
                COMMIT;

                OPEN_ALL_RS;
                OPEN O_RC2 FOR SELECT NULL AS ERR_CODE, NULL AS ERR_MESSAGE FROM DUAL WHERE 1 = 0;
                RETURN;

            END IF;

            /* 출발 사이트 사업부·운영그룹 (없으면 앞 행 값 유지 - AS-IS 변수 대입과 동일) */
            BEGIN
                SELECT DIVISION_ID
                     , OPERATION_GROUP
                  INTO V_ORIGIN_FROM_DIVISION_ID
                     , V_OPERATION_GROUP
                  FROM SCM_MST_SITE
                 WHERE UPPER(VALID_YN)    = 'Y'
                   AND UPPER(SCM_SITE_ID) = UPPER(V_FROM_SITE)
                   AND DIVISION_ID        = V_DIVISION_ID
                   AND ROWNUM             = 1;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    NULL;
            END;

            IF V_PROJECT_CODE = '-' THEN
                V_PROJECT_CODE := NULL;
            END IF;

            IF UPPER(V_OPERATION_GROUP) <> 'E' THEN
                V_ELECTRODE_YN            := 'N';
                V_ORIGIN_TO_DIVISION_ID   := V_ORIGIN_FROM_DIVISION_ID;
            ELSE
                V_ELECTRODE_YN := 'Y';

                BEGIN
                    SELECT DIVISION_ID
                      INTO V_ORIGIN_TO_DIVISION_ID
                      FROM SCM_MST_SITE
                     WHERE UPPER(VALID_YN)    = 'Y'
                       AND UPPER(SCM_SITE_ID) = UPPER(V_TO_SITE)
                    /* AND   SITE_TYPE  = 'PLANT' */
                       AND ROWNUM             = 1;
                EXCEPTION
                    WHEN NO_DATA_FOUND THEN
                        NULL;
                END;
            END IF;

            /* VALIDATION 체크 - 1:해당 MODEL 있음 / 0:해당 MODEL 없음
               ※ AS-IS : 없는 토큰(NULL)은 LIKE 결과가 NULL → 0건, 빈 토큰('')은 '%%' → 전체 일치 */
            V_CNT_ITEM_ID := 0;
            IF V_PROJECT_CODE_EXISTS AND V_ITEM_ID_EXISTS THEN
                IF UPPER(V_DIVISION_ID) = 'ALL' THEN
                    SELECT COUNT(*)
                      INTO V_CNT_ITEM_ID
                      FROM DUAL
                     WHERE EXISTS (SELECT 1
                                     FROM SCM_MST_SITE_ITEM A
                                        , SCM_MST_DIVISION  B
                                        , SCM_MST_SITE      C
                                        , SCM_MST_ITEM_SN   D
                                    WHERE B.DIVISION_ID = A.DIVISION_ID
                                      AND C.DIVISION_ID = A.DIVISION_ID
                                      AND C.SCM_SITE_ID = A.SCM_SITE_ID
                                      AND D.DIVISION_ID = A.DIVISION_ID
                                      AND D.ITEM_ID     = A.ITEM_ID
                                      AND UPPER(A.PROJECT_CODE) LIKE '%' || UPPER(V_PROJECT_CODE) || '%'
                                      AND (   UPPER(A.ITEM_ID)   LIKE '%' || UPPER(V_ITEM_ID) || '%'
                                           OR UPPER(D.ITEM_NAME) LIKE '%' || UPPER(V_ITEM_ID) || '%'
                                           OR UPPER(D.NICK_NAME) LIKE '%' || UPPER(V_ITEM_ID) || '%'));
                ELSE
                    SELECT COUNT(*)
                      INTO V_CNT_ITEM_ID
                      FROM DUAL
                     WHERE EXISTS (SELECT 1
                                     FROM SCM_MST_SITE_ITEM A
                                        , SCM_MST_DIVISION  B
                                        , SCM_MST_SITE      C
                                        , SCM_MST_ITEM_SN   D
                                    WHERE B.DIVISION_ID = A.DIVISION_ID
                                      AND C.DIVISION_ID = A.DIVISION_ID
                                      AND C.SCM_SITE_ID = A.SCM_SITE_ID
                                      AND D.DIVISION_ID = A.DIVISION_ID
                                      AND D.ITEM_ID     = A.ITEM_ID
                                      AND A.DIVISION_ID IN (SELECT XA.COLUMN_VALUE
                                                              FROM TABLE(STRING_SPLIT(V_DIVISION_ID, ',')) XA)
                                      AND UPPER(A.PROJECT_CODE) LIKE '%' || UPPER(V_PROJECT_CODE) || '%'
                                      AND (   UPPER(A.ITEM_ID)   LIKE '%' || UPPER(V_ITEM_ID) || '%'
                                           OR UPPER(D.ITEM_NAME) LIKE '%' || UPPER(V_ITEM_ID) || '%'
                                           OR UPPER(D.NICK_NAME) LIKE '%' || UPPER(V_ITEM_ID) || '%'));
                END IF;
            END IF;

            IF V_CNT_ITEM_ID > 0 THEN
                V_VAL_CODE := 1;
            ELSE
                V_VAL_CODE := 0;
            END IF;

            IF V_VAL_CODE = 1 THEN

                V_DESCRIPTION := '';
                D_EVENT_DATE  := SYSDATE;

                V_TMP_FN_TIME_ZONE := TO_CHAR(FN_MULTY_TIME(P_TIME_ZONE), 'YYYYMMDD');
                V_TMP_SEQ_CONFIRM  := TO_CHAR(SEQ1_SSP_ANL_SHIP_CONFIRM_ID.NEXTVAL);
                /* AS-IS : 'C' + NULL 은 NULL → CONFIRM_ID NOT NULL 위반(오류) */
                IF V_TMP_FN_TIME_ZONE IS NULL THEN
                    V_NEW_CONFIRM_ID := NULL;
                ELSE
                    V_NEW_CONFIRM_ID := 'C' || V_TMP_FN_TIME_ZONE || SUBSTR('000000' || V_TMP_SEQ_CONFIRM, -6);
                END IF;
                /* //==================================================================================================================================== */
                SELECT NVL(MAX(PLAN_START_YYYYMMDD), TO_CHAR(SYSDATE, 'YYYYMMDD'))
                     , NVL(TO_CHAR(MAX(PLAN_SEQ)), '1')
                  INTO V_PLAN_START_YYYYMMDD
                     , V_SEQ
                  FROM SSP_PLAN_VERSION_V
                 WHERE PLAN_TYPE           = 'SP'
                   AND CONFIRM_FLAG        = 'Y'
                   AND PLAN_START_YYYYMMDD = (SELECT MAX(XA.PLAN_START_YYYYMMDD)
                                                FROM SSP_PLAN_VERSION_V XA
                                               WHERE XA.PLAN_TYPE    = 'SP'
                                                 AND XA.CONFIRM_FLAG = 'Y'
                                                 AND XA.DIVISION_ID  = V_DIVISION_ID)
                   AND DIVISION_ID         = V_DIVISION_ID;

                /* [E20250821-001308] begin 대체코드 -- TO_COMPANY_ID를 FROM_SITE에 따라 다르게 적용하는 예외를 적용 */
                V_TMP_DIVISION_ID       := V_ORIGIN_FROM_DIVISION_ID;
                V_FROM_SITE_TYPE        := FN_SITE_INFO(V_TMP_DIVISION_ID, V_FROM_SITE, 'SITE_TYPE');
                V_FROM_SITE_PLANT_ID    := FN_SITE_INFO(V_TMP_DIVISION_ID, V_FROM_SITE, 'PLANT_ID');
                V_FROM_SITE_VENDOR_ID   := FN_SITE_INFO(V_TMP_DIVISION_ID, V_FROM_SITE, 'VENDOR_ID');
                V_FROM_SITE_COMPANY_ID  := FN_SITE_INFO(V_TMP_DIVISION_ID, V_FROM_SITE, 'COMPANY_ID');
                V_FROM_SITE_SOLDTO_CODE := FN_SITE_INFO(V_TMP_DIVISION_ID, V_FROM_SITE, 'SOLDTO_CODE');
                V_FROM_SITE_SHIPTO_CODE := FN_SITE_INFO(V_TMP_DIVISION_ID, V_FROM_SITE, 'SHIPTO_CODE');

                V_TMP_DIVISION_ID       := CASE WHEN V_DIVISION_ID = 'EE' THEN V_ORIGIN_FROM_DIVISION_ID ELSE V_ORIGIN_TO_DIVISION_ID END;
                V_TO_SITE_TYPE          := FN_SITE_INFO_EXCEPTION(V_TMP_DIVISION_ID, V_FROM_SITE, V_TO_SITE, 'SITE_TYPE');
                V_TO_SITE_PLANT_ID      := FN_SITE_INFO(V_TMP_DIVISION_ID, V_TO_SITE, 'PLANT_ID');
                V_TO_SITE_VENDOR_ID     := FN_SITE_INFO(V_TMP_DIVISION_ID, V_TO_SITE, 'VENDOR_ID');
                V_TO_SITE_COMPANY_ID    := FN_SITE_INFO_EXCEPTION(V_TMP_DIVISION_ID, V_FROM_SITE, V_TO_SITE, 'COMPANY_ID');
                V_TO_SITE_SOLDTO_CODE   := FN_SITE_INFO(V_TMP_DIVISION_ID, V_TO_SITE, 'SOLDTO_CODE');
                V_TO_SITE_SHIPTO_CODE   := FN_SITE_INFO(V_TMP_DIVISION_ID, V_TO_SITE, 'SHIPTO_CODE');
                /* [E20250821-001308] end 대체코드 */

                /* [E20250821-001308] 주석 구코드 */
                /* start E20260514-001358 TO_ shipto / soldto 없는 경우 출하 금지 */
                /* shipto, soldto validation */
                IF TRIM(V_TO_SITE_SOLDTO_CODE) IS NULL OR TRIM(V_TO_SITE_SHIPTO_CODE) IS NULL THEN

                    IF TRIM(V_TO_SITE_SOLDTO_CODE) IS NULL THEN
                        ADD_RS('R', 'X', 'no soldto code', V_DIVISION_ID_OR, V_TO_SITE_OR);
                    ELSIF TRIM(V_TO_SITE_SHIPTO_CODE) IS NULL THEN
                        ADD_RS('R', 'X', 'no shipto code', V_DIVISION_ID_OR, V_TO_SITE_OR);
                    END IF;
                    V_LOG_TYPE    := 'END';
                    V_LOG_MESSAGE := SUBSTR('########## ' || V_DIVISION_ID_OR || ' ' || V_TO_SITE_OR
                                     || V_TO_SITE_SHIPTO_CODE || ' ' || V_TO_SITE_SOLDTO_CODE || ' ' || ' Error END of procedure ##########', 1, 1000);
                    D_EVENT_DATE  := SYSDATE;
                    PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
                    COMMIT;

                    OPEN_ALL_RS;
                    OPEN O_RC2 FOR SELECT NULL AS ERR_CODE, NULL AS ERR_MESSAGE FROM DUAL WHERE 1 = 0;
                    RETURN;
                    /* end E20260514-001358 TO_ shipto / soldto 없는 경우 출하 금지 */
                END IF;

                /* mkt owner select */
                IF V_DIVISION_ID = '40' THEN

                    SELECT COUNT(PROJECT_CODE) AS CNT
                      INTO V_PRJ_CNT
                      FROM SCM_MST_SITE_ITEM
                     WHERE DIVISION_ID         = V_DIVISION_ID
                       AND UPPER(SCM_SITE_ID)  = UPPER(V_TO_SITE)
                       AND UPPER(ITEM_ID)      = UPPER(V_ITEM_ID)
                       AND UPPER(PROJECT_CODE) = UPPER(V_PROJECT_CODE_40);

                    IF V_PRJ_CNT = 0 THEN
                        BEGIN
                            SELECT PROJECT_CODE
                              INTO V_PROJECT_CODE
                              FROM SCM_MST_SITE_ITEM
                             WHERE DIVISION_ID        = V_DIVISION_ID
                               AND UPPER(SCM_SITE_ID) = UPPER(V_TO_SITE)
                               AND UPPER(ITEM_ID)     = UPPER(V_ITEM_ID)
                               AND ROWNUM             = 1;
                        EXCEPTION
                            WHEN NO_DATA_FOUND THEN
                                NULL;
                        END;
                    END IF;

                END IF;

                /*
                판가 입력 정보 조회
                52주 구간 전부에 입력이 안되어있으면 신규 생성 불가
                현재 SSP는 내/외수를 구분하지 않기 때문에 DOM_EXP 타입을 'DOM'로 강제로 설정 후 처리하였음(한개로 처리하기 위해서)
                */
                SELECT COUNT(*)
                  INTO V_SALES_PRICE_CHECK_CNT
                  FROM (SELECT DISTINCT
                               A.DIVISION_ID
                             , A.PROJECT_CODE
                             , A.SCM_SITE_ID
                             , A.PLANT_SITE_ID
                             , A.ITEM_ID
                             , A.MEASURE
                             , 'DOM' AS DOM_EXP
                             , A.FCST_TYPE
                             , A.INCOTERMS
                             , COUNT(*) AS CNT
                          FROM SCM_MST_FUTURE_PRICE A
                             , SCM_SYS_CALENDAR_M   B
                             , (SELECT MIN(M.BASIS_START_DATE) AS BASIS_START_DATE
                                     , MAX(M.BASIS_END_DATE)   AS BASIS_END_DATE
                                  FROM SCM_SYS_CALENDAR_M M
                                 WHERE M.BASIS_YYYYMMDD BETWEEN TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7, 'YYYYMMDD')              /* 당주 월요일부터 */
                                                            AND TO_CHAR(TRUNC(FN_NEXT_DAY(SYSDATE, 'MON') - 7) + 84, 'YYYYMMDD') /* 12주후 월요일까지 */
                               ) IA
                         WHERE B.BASIS_YYYYMMDD = A.YYYYMMDD
                           AND UPPER(A.FCST_TYPE) NOT IN (SELECT UPPER(XA.SEGMENT2)
                                                            FROM SCM_ADM_LOOKUP_MASTER_DETAIL XA
                                                           WHERE 1 = 1
                                                             AND XA.LOOKUP_TYPE = 'MKT_FCST_VALIDATION_PRICE'
                                                             AND XA.SEGMENT1    = 'FCST_TYPE'
                                                             AND XA.VALID_YN    = 'Y')
                           AND B.DAYOFWEEK      = 'MON'
                           AND UPPER(A.MEASURE) = 'KRW'
                           AND A.YYYYMMDD BETWEEN IA.BASIS_START_DATE AND IA.BASIS_END_DATE
                           AND A.DIVISION_ID    = V_DIVISION_ID
                           AND A.PROJECT_CODE   = CASE WHEN V_DIVISION_ID = '40' THEN V_PROJECT_CODE_40 ELSE V_PROJECT_CODE END
                           AND UPPER(A.SCM_SITE_ID) = UPPER(V_TO_SITE)
                        /* AND A.PLANT_SITE_ID = CASE WHEN @p_division_id = '81' THEN @p_from_site ELSE '' END */
                           AND A.ITEM_ID        = V_ITEM_ID
                           AND UPPER(A.FCST_TYPE) = UPPER(V_FCST_TYPE)
                           AND UPPER(A.INCOTERMS) = UPPER(V_NEW_INCOTERMS)
                        /* AND A.DOM_EXP		= @p_dom_exp */
                        /* and a.yyyymmdd >= '' */
                         GROUP BY A.DIVISION_ID
                                , A.PROJECT_CODE
                                , A.SCM_SITE_ID
                                , A.PLANT_SITE_ID
                                , A.ITEM_ID
                                , A.MEASURE
                                , A.DOM_EXP
                                , A.FCST_TYPE
                                , A.INCOTERMS
                        HAVING COUNT(*) = 13
                       ) XX;

                IF V_SALES_PRICE_CHECK_CNT > 1 THEN
                    V_SALES_PRICE_CHECK_CNT := 1;
                END IF;

                /* 해당 LOOKUP 등록 정보는 판가입력 정보를 Check 하지 않음. */
                SELECT COUNT(*)
                  INTO V_MKT_FCST_CHECK_CNT
                  FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                 WHERE 1 = 1
                   AND LOOKUP_TYPE     = 'MKT_FCST_VALIDATION_PRICE'
                   AND SEGMENT1        = 'FCST_TYPE'
                   AND VALID_YN        = 'Y'
                   AND UPPER(SEGMENT2) = UPPER(V_FCST_TYPE);

                /* 법인간 거래이면 판가입력 정보를 Check 하지 않음. */
                IF    (V_FROM_SITE_TYPE = 'B' AND V_TO_SITE_TYPE = 'B')
                   OR (V_FROM_SITE_TYPE = 'B' AND V_TO_SITE_TYPE = 'C')
                   OR (V_FROM_SITE_TYPE = 'C' AND V_TO_SITE_TYPE = 'C')
                   OR (V_FROM_SITE_TYPE = 'C' AND V_TO_SITE_TYPE = 'B') THEN
                    V_SALES_PRICE_CHECK_CNT := 1;
                END IF;

                /* print @v_sales_price_check_cnt; */
                /* 판가 정보없고, 법인간 거래가 아니거나, LOOKUP에 등록된 FCST_TYPE이 아니면 RETURN */
                IF V_SALES_PRICE_CHECK_CNT = 1 THEN
                    V_SALES_PRICE_CHECK_CNT := 1;
                ELSIF V_MKT_FCST_CHECK_CNT = 1 THEN
                    V_SALES_PRICE_CHECK_CNT := 1;
                ELSE
                    ADD_RS('C', 'F');
                    V_LOG_TYPE    := 'END';
                    V_LOG_MESSAGE := '########## END of procedure ##########';
                    /* SET @v_description = 'Confrim_ID : ' + @v_new_confirm_id + ' / Time Zone : ' + @v_tmp_fn_time_zone + ' / Seq : ' + @v_tmp_seq_confirm; */
                    D_EVENT_DATE  := SYSDATE;
                    PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
                    COMMIT;

                    OPEN_ALL_RS;
                    OPEN O_RC2 FOR SELECT NULL AS ERR_CODE, NULL AS ERR_MESSAGE FROM DUAL WHERE 1 = 0;
                    RETURN;
                END IF;

                V_SHIPMENT_DATE := REPLACE(SUBSTR(V_SHIPMENT_DATE, 1, 10), '-', '');
                V_NEW_ETD_DATE  := REPLACE(SUBSTR(V_SHIPMENT_DATE, 1, 10), '-', '');
                /* SET @p_eta = REPLACE(SUBSTRING(@p_eta,1,10),'-','') */
                V_ETA           := FN_GET_SSP_ETA_DATE(V_DIVISION_ID, V_NEW_BOD_ID, V_SHIPMENT_DATE);
                /* @v_etd = FN_GET_SSP_ETD_DATE(...) : 저장에 쓰이지 않아 옮기지 않음 */

                V_LAST_UPDATE_DATE := SYSDATE;

                IF V_PROJECT_CODE IS NULL THEN
                    V_PROJECT_CODE := '-';
                END IF;

                /* AS-IS NOT NULL 칸에 NULL(없는 토큰) 입력 시 오류 - Oracle 원장은 DEFAULT ON NULL 이라 명시적으로 막는다 */
                IF V_NEW_CONFIRM_ID IS NULL THEN
                    RAISE_APPLICATION_ERROR(-20001, 'Cannot insert the value NULL into column ''CONFIRM_ID'', table ''SSP_ANL_SHIP_CONFIRM''.');
                END IF;
                IF NOT V_SHIPMENT_DATE_EXISTS THEN
                    RAISE_APPLICATION_ERROR(-20001, 'Cannot insert the value NULL into column ''YYYYMMDD'', table ''SSP_ANL_SHIP_CONFIRM''.');
                END IF;

                /* 수량 : 빈 토큰은 AS-IS 변환 오류, 없는 토큰은 NULL 저장 */
                IF V_SHIPMENT_QTY_EXISTS THEN
                    V_QTY_NUM := FN_TO_NUM_20_10(V_SHIPMENT_QTY);
                ELSE
                    V_QTY_NUM := NULL;
                END IF;

                /* 정수 칸(SEQ·ROUTE_ID bigint, CUSTOMER_LT int) 암묵 변환 */
                V_SEQ_NUM         := FN_TO_INT(V_SEQ, 9223372036854775807);
                V_ROUTE_ID_NUM    := FN_TO_INT(V_NEW_ROUTE_ID, 9223372036854775807);
                V_CUSTOMER_LT_NUM := FN_TO_INT(V_NEW_CUSTOMER_LT, 2147483647);

                INSERT INTO SSP_ANL_SHIP_CONFIRM
                     ( CONFIRM_ID
                     , SHIPMENT_STATUS
                     , DIVISION_ID
                     , PLAN_START_YYYYMMDD
                     , PLAN_TYPE
                     , SEQ
                     , ITEM_ID
                     , FROM_SITE
                     , TO_SITE
                     , YYYYMMDD
                     , PLANNED_QTY
                     , QTY
                     , BOD_ID
                     , ROUTE_ID
                     , BIZ_TYPE
                     , PROJECT_CODE
                     , FCST_TYPE
                     , FCST_ETD_DATE
                     , FCST_ETA_DATE
                     , ETD_DATE
                     , ETA_DATE
                     , INCOTERMS
                     , TRANSPORT_MODE
                     , D_COUNTRY
                     , D_PORT_CODE
                     , A_COUNTRY
                     , A_PORT_CODE
                     , CUSTOMER_LT
                     , TO_COUNTRY
                     , TO_CITY
                     , FROM_SITE_TYPE
                     , FROM_SITE_PLANT_ID
                     , FROM_SITE_VENDOR_ID
                     , FROM_SITE_SOLDTO_CODE
                     , FROM_SITE_SHIPTO_CODE
                     , FROM_SITE_COMPANY_ID
                     , TO_SITE_TYPE
                     , TO_SITE_PLANT_ID
                     , TO_SITE_VENDOR_ID
                     , TO_SITE_SOLDTO_CODE
                     , TO_SITE_SHIPTO_CODE
                     , TO_SITE_COMPANY_ID
                     , CHANGE_TYPE
                     , CREATED_BY
                     , CREATION_DATE
                     , LAST_UPDATED_BY
                     , LAST_UPDATE_DATE
                     , REMARKS
                     , REMARKS2
                     , REMARKS3
                     , ELECTRODE_YN
                     , ORIGIN_FROM_DIVISION_ID
                     , ORIGIN_TO_DIVISION_ID
                     , BEFORE_QTY
                     , CHECK_NEED_YN
                     , REQUESTOR
                     , ATTRIBUTE10
                     /**** 20211018   SHINMYUNGSU   항목추가   ************/
                     , ERP_ATTR1
                     , ERP_ATTR2
                     , ERP_ATTR3
                     /*********************************************************/
                     )
                VALUES
                     ( V_NEW_CONFIRM_ID
                     , 'C'
                     , V_DIVISION_ID
                     , V_PLAN_START_YYYYMMDD
                     , 'SP'
                     , V_SEQ_NUM
                     , V_ITEM_ID
                     , V_FROM_SITE
                     , V_TO_SITE
                     , V_SHIPMENT_DATE
                     , 0
                     , V_QTY_NUM
                     , V_NEW_BOD_ID
                     , V_ROUTE_ID_NUM
                     , V_OPERATION_GROUP
                     , CASE WHEN V_DIVISION_ID = '40' THEN V_PROJECT_CODE_40 ELSE V_PROJECT_CODE END
                     , V_FCST_TYPE
                     , V_NEW_ETD_DATE
                     , V_ETA
                     , V_NEW_ETD_DATE
                     , V_ETA
                     , V_NEW_INCOTERMS
                     , V_NEW_TRANSPORT_MODE
                     , V_NEW_D_CONTRY
                     , V_NEW_D_PORT_CODE
                     , V_NEW_A_COUNTRY
                     , V_NEW_A_PORT_CODE
                     , V_CUSTOMER_LT_NUM
                     , V_NEW_TO_COUNTRY
                     , V_NEW_TO_CITY
                     , V_FROM_SITE_TYPE
                     , V_FROM_SITE_PLANT_ID
                     , V_FROM_SITE_VENDOR_ID
                     , V_FROM_SITE_SOLDTO_CODE
                     , V_FROM_SITE_SHIPTO_CODE
                     , V_FROM_SITE_COMPANY_ID
                     , V_TO_SITE_TYPE
                     , V_TO_SITE_PLANT_ID
                     , V_TO_SITE_VENDOR_ID
                     , V_TO_SITE_SOLDTO_CODE
                     , V_TO_SITE_SHIPTO_CODE
                     , V_TO_SITE_COMPANY_ID
                     , 'N'
                     , P_USER_ID
                     , V_LAST_UPDATE_DATE
                     , P_USER_ID
                     , V_LAST_UPDATE_DATE
                     , V_REMARKS
                     , V_REMARKS2
                     , V_REMARKS3
                     , V_ELECTRODE_YN
                     , V_ORIGIN_FROM_DIVISION_ID
                     , V_ORIGIN_TO_DIVISION_ID
                     , 0
                     , 'Y'
                     , P_USER_ID
                     , 'I'
                     /**** 20211018   SHINMYUNGSU   항목추가   ************/
                     , V_ERP_ATTR1
                     , V_ERP_ATTR2
                     , V_ERP_ATTR3
                     /*********************************************************/
                     );

                /* 230226 jilee DM Confirm 동기화 추가 */
                PR_DM_SSP_CONFIRM_SYNC(V_DIVISION_ID, V_NEW_CONFIRM_ID);

                /* ---- 결과코드, 결과 카운트 반환 */
                /* SELECT  'S' AS result_code, @v_new_confirm_id as ConfrimID ; */

            ELSIF V_VAL_CODE = 0 THEN
                ADD_RS('C', 'N');
            END IF;

            /* 행 처리 확정(AS-IS 는 문장마다 확정) */
            COMMIT;

        END LOOP;

        /* 결과코드, 결과 카운트 반환 */
        ADD_RS('S', 'S', V_NEW_CONFIRM_ID);

        V_LOG_TYPE    := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        /* AS-IS : 결합 값 중 하나라도 NULL 이면 설명 전체가 NULL */
        IF V_NEW_CONFIRM_ID IS NULL OR V_TMP_FN_TIME_ZONE IS NULL OR V_TMP_SEQ_CONFIRM IS NULL THEN
            V_DESCRIPTION := NULL;
        ELSE
            V_DESCRIPTION := 'Confrim_ID : ' || V_NEW_CONFIRM_ID || ' / Time Zone : ' || V_TMP_FN_TIME_ZONE || ' / Seq : ' || V_TMP_SEQ_CONFIRM;
        END IF;
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
        COMMIT;

        OPEN_ALL_RS;
        OPEN O_RC2 FOR SELECT NULL AS ERR_CODE, NULL AS ERR_MESSAGE FROM DUAL WHERE 1 = 0;

    EXCEPTION
        WHEN OTHERS THEN

            V_ERR_CODE    := SQLCODE;
            V_ERR_MESSAGE := SQLERRM;

            /* 입력 데이타 롤백 처리(현재 행) - 커서 OPEN 전에 되돌린다 */
            ROLLBACK TO SP_SSP0200_SAVE_CFM_NEW;

            INSERT INTO SCM_SYS_LOG_BATCH
                 ( PROGRAM_NAME
                 , LOG_TYPE
                 , LOG_COUNT
                 , LOG_MESSAGE
                 , DESCRIPTION
                 , EVENT_DATE
                 , CREATION_DATE
                 , CREATED_BY
                 , LAST_UPDATE_DATE
                 , LAST_UPDATED_BY
                 )
            VALUES
                 ( V_ERR_PROGRAM_NAME
                 , 'ERROR'
                 , NULL
                 , SUBSTR(V_ERR_MESSAGE, 1, 1000)
                 , NULL
                 , SYSDATE
                 , SYSDATE
                 , V_ERR_PROGRAM_NAME
                 , SYSDATE
                 , V_ERR_PROGRAM_NAME
                 );
            COMMIT;

            /* error코드, errror 메시지 반환 */
            ADD_RS('C', 'F');
            OPEN_ALL_RS;
            OPEN O_RC2 FOR SELECT V_ERR_CODE AS ERR_CODE, V_ERR_MESSAGE AS ERR_MESSAGE FROM DUAL;

    END P_SSP0200_SAVE_SHIPMENT_CONFIRM_NEW;

END PKG_ZTMP_S200D;

PROCEDURE           "PR_4MCC_SCM_MST_PROJECT" 


/*
 Program ID  : PR_4MCC_SCM_MST_PROJECT
 Description : PR_4MCC_SCM_MST_PROJECT
--------------------------------------------------------------------------------------------------
 Date        In Charge    Description
--------------------------------------------------------------------------------------------------
 2023/11/17  Chano0612  Initial Release [E20230608-000782] 4MCC 시스템 신규 구축에 따른 SCM 인터페이스 관련 항목 개발
 2023/11/22  JSSBAE		14일 이전 데이터 삭제 후 생성하는 로직 추가, 컬럼 정보 추가, SEQ채번 RULE 변경
 2024/03/21	 JSSBAE		[E20240320-000882]_DM XIF 인덱스 생성 요청_데이터 삭제 로직 오류로 수정진행
 2026.03.25   jcnam     [PJ20264226] NextSCM Pilot 설계 및 개발
--------------------------------------------------------------------------------------------------
 * 2026.07.06	ZIONEX		[PJ202650304] NextSCM Migration
*/
IS
    V_IF_NAME           VARCHAR2(12 CHAR);
    V_IF_NO             PLS_INTEGER;
    V_CNT               PLS_INTEGER;
    V_DUP_YN            VARCHAR2(1 CHAR);

    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME      VARCHAR2(200 CHAR);
    V_LOG_TYPE          VARCHAR2(100 CHAR);
    N_LOG_COUNT         PLS_INTEGER := 0;
    V_LOG_MESSAGE       VARCHAR2(4000 CHAR);
    V_DESCRIPTION       VARCHAR2(4000 CHAR);
    D_EVENT_DATE        DATE := SYSDATE;


    V_PROC_INPUT        VARCHAR2(4000 CHAR);
    V_BACKTRACE         VARCHAR2(4000 CHAR);
    V_SQL_CODE          VARCHAR2(100 CHAR);
    V_SQL_ERRMSG        VARCHAR2(1000 CHAR);
BEGIN

    IF UTL_CALL_STACK.SUBPROGRAM(1).COUNT > 1 THEN
        V_PROGRAM_NAME := $$PLSQL_UNIT || '.' || UTL_CALL_STACK.SUBPROGRAM(1)(2);
    ELSE
        V_PROGRAM_NAME := $$PLSQL_UNIT;
    END IF;

    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    BEGIN PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE); END;

