        JOB.PR_DM_PLN_SALES_PLAN_WEEKLY_ROLLING_40          SALES PLAN CUTOFF 정상 작동 40                      해당 시점에 JOB로그가 찍히지 않는다면 문자발송
        JOB.PR_DM_PLN_SALES_PLAN_WEEKLY_ROLLING_81          SALES PLAN CUTOFF 정상 작동 81                      해당 시점에 JOB로그가 찍히지 않는다면 문자발송
        JOB.PR_DM_PLN_SALES_PLAN_WEEKLY_ROLLING_81_HM   SALES PLAN CUTOFF 정상 작동 81_HM                   해당 시점에 JOB로그가 찍히지 않는다면 문자발송
        JOB.PR_DM_PLN_SALES_PLAN_WEEKLY_ROLLING_81_ST   SALES PLAN CUTOFF 정상 작동 81_ST                   해당 시점에 JOB로그가 찍히지 않는다면 문자발송
        JOB.PR_DM_PLN_SALES_PLAN_WEEKLY_ROLLING_81_UC   SALES PLAN CUTOFF 정상 작동 81_UC                   해당 시점에 JOB로그가 찍히지 않는다면 문자발송
        JOB.PR_DM_PLN_SALES_PLAN_WEEKLY_ROLLING_82          SALES PLAN CUTOFF 정상 작동 82                      해당 시점에 JOB로그가 찍히지 않는다면 문자발송
        JOB.PR_DM_DNM_SALES_RESULT                          Sales Result 반영(to DM)                              해당 시점에 JOB로그가 찍히지 않는다면 문자발송
        JOB_RFC.매출 실적 정보                                ERP Sales Result 수신                             해당 시점에 JOB로그가 찍히지 않는다면 문자발송
        JOB_RFC.판매법인(G260) 재고                       판매법인(G260) 재고                               해당 시점에 JOB로그가 찍히지 않는다면 문자발송
        JOB_RFC.DM_VMI_재고 입출고 실적                        VMI 재고 입출고 실적                               해당 시점에 JOB로그가 찍히지 않는다면 문자발송
        JOB.PR_DM_PLN_XIF_ERP_MDF_TO_DM_MDF_RESULT          전지사업본부 MDF(판매장려금) 실적 정보                 해당 시점에 JOB로그가 찍히지 않는다면 문자발송
        -------------------------------------------------  -------------------------------------------------    --------------------------------------------------------------------------
        ● 문자 발송 대상 LIST
        DM : 카테고리 102
    ============================================================================================================================ * 2026.03.24 김준규       [PJ20264226] NextSCM Pilot 설계 및 개발
 * 2026.07.06	ZIONEX		[PJ202650304] NextSCM Migration
     */
 AS

    V_IN_PARA_DATA    VARCHAR2(4000 CHAR);
    V_JOB_NAME        VARCHAR2(150 CHAR);
    V_JOB_DESCRIPTION VARCHAR2(150 CHAR);
    V_JOB_EVENT_TM    DATE;
    V_CODE            VARCHAR2(150 CHAR);
    V_TEXT            VARCHAR2(4000 CHAR);
    V_PROGRAM_NAME    VARCHAR2(150 CHAR) := $$PLSQL_UNIT;
    V_LOG_TYPE        VARCHAR2(30 CHAR);
    N_LOG_COUNT       INTEGER := 0;
    V_LOG_MESSAGE     VARCHAR2(1000 CHAR);
    V_DESCRIPTION     VARCHAR2(500 CHAR);
    D_EVENT_DATE      DATE;
    V_CNT_1           INTEGER := 0;
BEGIN


    /* ----------------------------------------------------------------------------------------------------
       대상건 Fetch 변수
       ----------------------------------------------------------------------------------------------------
       LOG 용 변수 설정
       ----------------------------------------------------------------------------------------------------
       시작 LOG (START)
       ---------------------------------------------------------------------------------------------------- */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := NULL;
    D_EVENT_DATE  := SYSTIMESTAMP;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    /* ----------------------------------------------------------------------------------------------------
       시작 LOG (END)
       ---------------------------------------------------------------------------------------------------- */
    EXECUTE IMMEDIATE 'TRUNCATE TABLE GT_DCBS_DAYINFO';
    EXECUTE IMMEDIATE 'TRUNCATE TABLE GT_DCBS_CHECKED';
    EXECUTE IMMEDIATE 'TRUNCATE TABLE GT_DCBS_DM_CHECK_BEFOREHAND';
    BEGIN
        /* ----------------------------------------------------------------------------------------------------
           임시TB 삭제하고 시작한다.
           ----------------------------------------------------------------------------------------------------
           ----------------------------------------------------------------------------------------------------
           당일 날짜가 어떤날짜인지 데이터 추출
           ---------------------------------------------------------------------------------------------------- */

        INSERT
          INTO GT_DCBS_DAYINFO
        SELECT DAYOFWEEK AS DAYOFWEEKS
          FROM SCM_SYS_CALENDAR_M
         WHERE BASIS_YYYYMMDD = TO_CHAR(SYSDATE, 'YYYYMMDD');

        /* ----------------------------------------------------------------------------------------------------
           현재시점 모니터링 해야되는 대상 추출(5분에 한번씩 도는 배치이므로, 10분전 데이터를 가지고와서 비교한다.)
           ---------------------------------------------------------------------------------------------------- */

        INSERT
          INTO GT_DCBS_CHECKED
        SELECT SEGMENT2 AS JOB_NAMES
             , SEGMENT3 DAYOFWEEKS
             , SEGMENT4 TIMES
             , DESCRIPTION SMS_MESSAGE
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
         WHERE LOOKUP_TYPE = 'DM_CHECKED_BEFOREHAND'
           AND SEGMENT1 = CASE
                              WHEN P_SYSTEM_NAME IS NULL OR P_SYSTEM_NAME = 'ALL' THEN
                               SEGMENT1
                              ELSE
                               P_SYSTEM_NAME
                          END /* [E20250529-001289]_ALL인경우는 시스템과 관계없이 타도록 수정 */
                  /* AND SEGMENT1 = P_SYSTEM_NAME [E20250529-001289]_기존 소스 주석처리 */
           AND (SEGMENT3 = 'ALL' OR SEGMENT3 IN (SELECT DAYOFWEEKS FROM GT_DCBS_DAYINFO))
           AND VALID_YN = 'Y'
           AND TO_NUMBER(SEGMENT4) + 5 BETWEEN TO_NUMBER(REPLACE(SUBSTR(TO_CHAR(SYSDATE - 5 / 1440, 'HH24:MI'), 1, 5), ':', '')) AND
                   TO_NUMBER(REPLACE(SUBSTR(TO_CHAR(SYSDATE, 'HH24:MI'), 1, 5), ':', ''));

        /* ----------------------------------------------------------------------------------------------------
           현재 기준으로 모니터링이 필요한 대상 데이터가 없는 경우에는 넘어간다
           ---------------------------------------------------------------------------------------------------- */
        SELECT COUNT(*)
          INTO V_CNT_1
          FROM GT_DCBS_CHECKED;
        IF V_CNT_1 > 0 THEN
            /*          --JOB이 실행되고 있는 이력을 확인한다.
                        SELECT W.JOB_NAMES AS JOB_NAME, SMS_MESSAGE
                        WHERE NOT EXISTS ( SELECT J.NAME AS JOB_NAME, H.RUN_STATUS, H.RUN_DATE, H.RUN_TIME, MSDB.AGENT_DATETIME(RUN_DATE, RUN_TIME) RUN_DATE_TIME
                            SELECT JOB_NAME, SMS_MESSAGE FROM GT_DCBS_DM_CHECK_BEFOREHAND;


                            END;


                        END;
            */


            INSERT
              INTO GT_DCBS_DM_CHECK_BEFOREHAND
            SELECT W.JOB_NAMES AS JOB_NAME
                 , W.SMS_MESSAGE
              FROM (SELECT JOB_NAMES, DAYOFWEEKS, TIMES, SMS_MESSAGE FROM GT_DCBS_CHECKED) W
             WHERE NOT EXISTS (SELECT 1
                                 FROM ALL_SCHEDULER_JOB_RUN_DETAILS D
                                WHERE D.JOB_NAME = W.JOB_NAMES
                                  AND TRUNC(D.LOG_DATE) = TRUNC(SYSDATE)
                                  AND TO_NUMBER(TO_CHAR(D.LOG_DATE, 'HH24MI')) BETWEEN W.TIMES - 5 AND W.TIMES + 5
                        );


            DECLARE
                CURSOR CUR_DM_CHECK_LOG IS
                    SELECT JOB_NAME, SMS_MESSAGE FROM GT_DCBS_DM_CHECK_BEFOREHAND;

                V_JOB_NAME        GT_DCBS_DM_CHECK_BEFOREHAND.JOB_NAME%TYPE;
                V_JOB_DESCRIPTION GT_DCBS_DM_CHECK_BEFOREHAND.SMS_MESSAGE%TYPE;
                V_TEXT            VARCHAR2(4000 CHAR);
                V_CODE            VARCHAR2(100 CHAR) := P_CATEGORY_ID;
            BEGIN
                OPEN CUR_DM_CHECK_LOG;
                LOOP
                    FETCH CUR_DM_CHECK_LOG
                        INTO V_JOB_NAME, V_JOB_DESCRIPTION;
                    EXIT WHEN CUR_DM_CHECK_LOG%NOTFOUND;

                    V_TEXT := V_JOB_DESCRIPTION;
                    SCM_ADM_SMS_SEND_BATCH(V_CODE, V_TEXT);
                END LOOP;
                CLOSE CUR_DM_CHECK_LOG;
            END;
        END IF;
    END;

EXCEPTION
    WHEN OTHERS THEN
        V_LOG_TYPE    := 'ERROR';
        V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
        V_DESCRIPTION := 'ERROR_LINE : ' || TO_CHAR(NULL);
        D_EVENT_DATE  := SYSTIMESTAMP;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        V_LOG_TYPE    := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := NULL;
        D_EVENT_DATE  := SYSTIMESTAMP;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
        RAISE_APPLICATION_ERROR(-20001
                               ,'[' || V_PROGRAM_NAME || '] SQLCODE=' || SQLCODE || ' / SQLERRM=' || SQLERRM || ' / BACKTRACE=' ||
                                DBMS_UTILITY.FORMAT_ERROR_BACKTRACE || ' / PARAMS=' || V_IN_PARA_DATA);
END;

