        JOB.PR_DM_PLN_MKT_FCST_WEEKLY_ROLLING_TUE_81_2      MKT FCST CUTOFF 정상 작동 (81, 81_ST, 81_HM)            해당 JOB이 오류가 발생하면 문자발송
        JOB.PR_DM_PLN_MKT_FCST_WEEKLY_ROLLING_TUE_81_UC     MKT FCST CUTOFF 정상 작동 (81_UC)                   해당 JOB이 오류가 발생하면 문자발송
        JOB.PR_DM_PLN_MKT_FCST_WEEKLY_ROLLING_TUE_TOTAL     MKT FCST CUTOFF 정상 작동 (82, 40)                  해당 JOB이 오류가 발생하면 문자발송
        JOB.PR_DM_PLN_SALES_PLAN_WEEKLY_ROLLING_40          SALES PLAN CUTOFF 정상 작동 40                      해당 JOB이 오류가 발생하면 문자발송
        JOB.PR_DM_PLN_SALES_PLAN_WEEKLY_ROLLING_81          SALES PLAN CUTOFF 정상 작동 81                      해당 JOB이 오류가 발생하면 문자발송
        JOB.PR_DM_PLN_SALES_PLAN_WEEKLY_ROLLING_81_HD   SALES PLAN CUTOFF 정상 작동 81_HD                   해당 JOB이 오류가 발생하면 문자발송
        JOB.PR_DM_PLN_SALES_PLAN_WEEKLY_ROLLING_81_HG   SALES PLAN CUTOFF 정상 작동 81_HG                   해당 JOB이 오류가 발생하면 문자발송
        JOB.PR_DM_PLN_SALES_PLAN_WEEKLY_ROLLING_81_HM   SALES PLAN CUTOFF 정상 작동 81_HM                   해당 JOB이 오류가 발생하면 문자발송
        JOB.PR_DM_PLN_SALES_PLAN_WEEKLY_ROLLING_81_ST   SALES PLAN CUTOFF 정상 작동 81_ST                   해당 JOB이 오류가 발생하면 문자발송
        JOB.PR_DM_PLN_SALES_PLAN_WEEKLY_ROLLING_81_UC   SALES PLAN CUTOFF 정상 작동 81_UC                   해당 JOB이 오류가 발생하면 문자발송
        JOB.PR_DM_PLN_SALES_PLAN_WEEKLY_ROLLING_82          SALES PLAN CUTOFF 정상 작동 82                      해당 JOB이 오류가 발생하면 문자발송
        JOB.PR_DM_DNM_SALES_RESULT                          Sales Result 반영(to DM)                              해당 JOB이 오류가 발생하면 문자발송
        JOB_RFC.매출 실적 정보                                ERP Sales Result 수신                             해당 JOB이 오류가 발생하면 문자발송
        JOB_RFC.판매법인(G260) 재고                       판매법인(G260) 재고                               해당 JOB이 오류가 발생하면 문자발송
        JOB_RFC.DM_VMI_재고 입출고 실적                        VMI 재고 입출고 실적                               해당 JOB이 오류가 발생하면 문자발송
        JOB.PR_DM_PLN_XIF_ERP_MDF_TO_DM_MDF_RESULT          전지사업본부 MDF(판매장려금) 실적 정보                 해당 JOB이 오류가 발생하면 문자발송
        -------------------------------------------------  -------------------------------------------------    --------------------------------------------------------------------------
      ● 문자 발송 대상 LIST
        DM : 카테고리 103
 * 2026.07.06	ZIONEX		[PJ202650304] NextSCM Migration
    */
 AS

    V_JOB_NAME        VARCHAR2(150 CHAR);
    V_JOB_DESCRIPTION VARCHAR2(4000 CHAR);
    V_CODE            VARCHAR2(150 CHAR);
    V_TEXT            VARCHAR2(4000 CHAR);
    N_DEF_CHECK_TM    INTEGER := 6;
    N_CHECK_TM        INTEGER;
    V_PROGRAM_NAME    VARCHAR2(150 CHAR) := $$PLSQL_UNIT;
    V_LOG_TYPE        VARCHAR2(30 CHAR);
    N_LOG_COUNT       INTEGER := 0;
    V_LOG_MESSAGE     VARCHAR2(1000 CHAR);
    V_DESCRIPTION     VARCHAR2(500 CHAR);
    D_EVENT_DATE      DATE;
    V_IN_PARA_DATA    VARCHAR2(4000 CHAR);
    V_STEP            VARCHAR2(4000 CHAR) := NULL;
    V_FETCH_STATUS    INTEGER;

    CURSOR CUR_DM_CHECK_LOG IS
        SELECT JOB_NAME, JOB_NAME FROM GT_DCJE_DM_CHECK_BEFOREHAND;
BEGIN

    IF UTL_CALL_STACK.SUBPROGRAM(1).COUNT > 1 THEN
        V_PROGRAM_NAME := $$PLSQL_UNIT || '.' || UTL_CALL_STACK.SUBPROGRAM(1) (2);
    END IF;

    V_IN_PARA_DATA := JSON_OBJECT('p_category_id' VALUE P_CATEGORY_ID, 'p_check_tm' VALUE P_CHECK_TM, 'p_system_name' VALUE P_SYSTEM_NAME);

    EXECUTE IMMEDIATE 'TRUNCATE TABLE GT_DCJE_CHECKED';
    EXECUTE IMMEDIATE 'TRUNCATE TABLE GT_DCJE_DM_CHECK_BEFOREHAND';
    /* -------------------------------------------------------------------------------------------------- */
    /* 대상건 Fetch 변수 */
    /* -------------------------------------------------------------------------------------------------- */
    /* LOG 용 변수 설정 */
    /* -------------------------------------------------------------------------------------------------- */
    /* 시간이 들어오지 않은 경우에는 기 선언한 시간으로 변경해준다. */
    /* -------------------------------------------------------------------------------------------------- */
    BEGIN
        IF (P_CHECK_TM > 0) THEN
            N_CHECK_TM := P_CHECK_TM;
        ELSE
            N_CHECK_TM := N_DEF_CHECK_TM;
        END IF;
    END;
    /* -------------------------------------------------------------------------------------------------- */
    /* 시작 LOG */
    /* -------------------------------------------------------------------------------------------------- */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := NULL;
    D_EVENT_DATE  := SYSTIMESTAMP;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);


    BEGIN
        /* -------------------------------------------------------------------------------------------------- */
        /* 임시TB 삭제하고 시작한다. */
        /* -------------------------------------------------------------------------------------------------- */
        /* 모니터링할 대상의 배치에 대해서를 추출한다. (룩업: DM_CHECKED_BEFOREHAND) */
        /* -------------------------------------------------------------------------------------------------- */
        INSERT
          INTO GT_DCJE_CHECKED
        SELECT SEGMENT2 AS JOB_NAMES
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
         WHERE LOOKUP_TYPE = 'DM_CHECKED_BEFOREHAND'
           AND VALID_YN = 'Y'
           AND SEGMENT1 = CASE WHEN P_SYSTEM_NAME IS NULL OR P_SYSTEM_NAME = 'ALL' THEN SEGMENT1
                               ELSE P_SYSTEM_NAME
                          END
         GROUP BY SEGMENT2;

        /* -------------------------------------------------------------------------------------------------- */
        /* 룩업에 등록된 JOB이 실행되고 있는 이력을 확인하여, 대상만 TEMP 테이블에 담는다. */
        /* -------------------------------------------------------------------------------------------------- */
        INSERT
          INTO GT_DCJE_DM_CHECK_BEFOREHAND
        SELECT T.PROGRAM_NAME AS JOB_NAME
             , T.PROGRAM_NAME AS SMS_MESSAGE
          FROM (SELECT L.PROGRAM_NAME
                     , L.LOG_TYPE
                     , L.EVENT_DATE
                  FROM SCM_SYS_LOG_BATCH L
                     , GT_DCJE_CHECKED   LOOK
                 WHERE LOOK.JOB_NAMES = L.PROGRAM_NAME
                   AND L.LOG_TYPE = 'ERROR') T
         WHERE 1 = 1
           AND (TRUNC(SYSDATE, 'MI') - TRUNC(T.EVENT_DATE, 'MI')) * 1440 < N_CHECK_TM
           AND T.LOG_TYPE = 'ERROR'
         GROUP BY T.PROGRAM_NAME
                , T.LOG_TYPE;

        OPEN CUR_DM_CHECK_LOG;
        FETCH CUR_DM_CHECK_LOG
            INTO V_JOB_NAME, V_JOB_DESCRIPTION;
        V_FETCH_STATUS := CASE
                              WHEN CUR_DM_CHECK_LOG%FOUND THEN
                               0
                              ELSE
                               -1
                          END;

        WHILE V_FETCH_STATUS = 0 LOOP
            BEGIN
                V_TEXT := NULL;
                V_CODE := P_CATEGORY_ID;
                V_TEXT := V_JOB_DESCRIPTION;

                SCM_ADM_SMS_SEND_BATCH(V_CODE, V_TEXT);
            END;

            FETCH CUR_DM_CHECK_LOG
                INTO V_JOB_NAME, V_JOB_DESCRIPTION;
            V_FETCH_STATUS := CASE
                                  WHEN CUR_DM_CHECK_LOG%FOUND THEN
                                   0
                                  ELSE
                                   -1
                              END;
        END LOOP;

        CLOSE CUR_DM_CHECK_LOG;

    EXCEPTION
        WHEN OTHERS THEN
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SQLERRM;
            V_DESCRIPTION := 'ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
            D_EVENT_DATE  := SYSTIMESTAMP;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    END;

    /* --------------------------------------------------------------------------------------------------------------------------- */

    /* --------------------------------------------------------------------------------------------------------------------------- */

    /* --------------------------------------------------------------------------------------------------------------------------- */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := NULL;
    D_EVENT_DATE  := SYSTIMESTAMP;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME
                            ,'ERROR'
                            ,0
                            ,SQLERRM
                            ,NULL
                            ,SYSDATE
                            ,P_IN_PARA_DATA  => V_IN_PARA_DATA
                            ,P_SQL_ERR_CODE  => SQLCODE
                            ,P_SQL_ERR_MSG   => SQLERRM
                            ,P_SQL_BACKTRACE => DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
END;

PROCEDURE           "PR_DM_CUST_DEMAND_ANL_SUMMARY" 
(
     P_DIVISION_ID     VARCHAR2
    ,P_REPLAN_YN       VARCHAR2
    ,P_EXE_YYYYMMDD    VARCHAR2
)
/*
 * Program ID  : [PR_DM_CUST_DEMAND_ANL_SUMMARY]
 * Description  : 고객수요증감분석 데이터 기초값 생성 및 인터페이스 전송
 * 메인테이블
   DM_CUST_DEMAND_ANL_SUMMARY
   XIF_DM_ANL_MKT_PSI_DW_S
   XIF_DM_ANL_MKT_PSI_DETAIL_DW_S
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 2024.10.30    KANG.H.J       [PJ2024-50647] 자동차사업부 고객 수요 분석 기능 개선
 2025.02.03    KANG.H.J       [PJ2024-50647] 자동차사업부 고객 수요 분석 기능 개선 - 단종예상 및 신규 데이터 기능 보완
 2025.02.11    Philsu Park    [E20250205-000991] 변동비 - ITEM단위 집계 프로시저 추가 호출.
 2026.07.06    ZIONEX         [PJ202650304] NextSCM Migration
 */
/*
 PR_DM_CUST_DEMAND_ANL_SUMMARY('81', 'N', '20241210');
 */
/* ------------------------------------------------------------------------------------------------------------------------------- */
AS
    V_PROGRAM_NAME             VARCHAR2(150 CHAR) := $$PLSQL_UNIT;
    V_IN_PARA_DATA             CLOB;
    V_STEP                     VARCHAR2(4000 CHAR) := NULL;
    V_LOG_TYPE                 VARCHAR2(30 CHAR);
    N_LOG_COUNT                INTEGER := 0;
    V_LOG_MESSAGE              VARCHAR2(1000 CHAR);
    V_DESCRIPTION              VARCHAR2(500 CHAR);
    D_EVENT_DATE               DATE;
    N_DELETE_COUNT             INTEGER := 0;
    N_INSERT_COUNT             INTEGER := 0;
    V_CREATED_BY               VARCHAR2(150 CHAR) := 'SYS_CUST_DEMAND_ANL_SUMMARY';
    V_CURR_MONTH               VARCHAR2(06 CHAR);
    V_PREV1_MONTH              VARCHAR2(06 CHAR);
    V_PREV2_MONTH              VARCHAR2(06 CHAR);
    V_PREV3_MONTH              VARCHAR2(06 CHAR);
    V_PREV4_MONTH              VARCHAR2(06 CHAR);
    V_CURR_MONTH_TUESDAY       VARCHAR2(08 CHAR);
    V_CURR_MONTH_MONDAY        VARCHAR2(08 CHAR);
    V_CURR_MONTH_FIRSTDAY      VARCHAR2(08 CHAR);
    V_CURR_MONTH_LASTDAY       VARCHAR2(08 CHAR);
    V_CURR_MKT_FCST_VERSION_NO VARCHAR2(4000 CHAR);
    V_CURR_MONTH_SUMMARY_CNT   INTEGER := 0;
    V_EXE_YYYYMMDD             VARCHAR2(8 CHAR);
    V_DELIMITER                VARCHAR2(1 CHAR);
    V_DIVISION_ID              VARCHAR2(10 CHAR);
    V_REPLAN_YN                VARCHAR2(01 CHAR);
    V_CNT_RESULT               INTEGER := 0;
    V_CNT_FCST                 INTEGER := 0;
    V_STD_MONTH                VARCHAR2(10 CHAR);
    O_SUB_RC1                  SYS_REFCURSOR;
    O_SUB_RESULT               SYS_REFCURSOR;
BEGIN

    IF UTL_CALL_STACK.SUBPROGRAM(1).COUNT > 1 THEN
        V_PROGRAM_NAME := $$PLSQL_UNIT || '.' || UTL_CALL_STACK.SUBPROGRAM(1) (2);
    END IF;

    V_IN_PARA_DATA := JSON_OBJECT('p_division_id' VALUE P_DIVISION_ID, 'p_replan_yn' VALUE P_REPLAN_YN, 'p_exe_yyyymmdd' VALUE P_EXE_YYYYMMDD);

    /* 여기서부터 TRANSACTION 처리 */
    /* */


    /* LOG 용 변수 설정 */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## START OF PROCEDURE ##########';
    V_DESCRIPTION := NULL;
    D_EVENT_DATE  := SYSTIMESTAMP;
    PR_DM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_CREATED_BY);

    EXECUTE IMMEDIATE 'TRUNCATE TABLE GT_DCDA_DM_PLN_MKT_FCST_RESULT';

    EXECUTE IMMEDIATE 'TRUNCATE TABLE GT_DCDA_DM_PLN_MKT_FCST';
    EXECUTE IMMEDIATE 'TRUNCATE TABLE GT_DCDA_CUSTOMER_PROJECT';

    V_DIVISION_ID := P_DIVISION_ID;
    V_REPLAN_YN   := P_REPLAN_YN;
    IF P_EXE_YYYYMMDD IS NULL THEN
        V_EXE_YYYYMMDD := TO_CHAR(SYSDATE, 'YYYYMMDD');
    ELSE
        V_EXE_YYYYMMDD := P_EXE_YYYYMMDD;
    END IF;

    /* STEP01 : 오늘이 당월의 첫주 수요일보다 작으면 RETURN */
    /* 오늘기준의 당월 / 전월 */
    V_CURR_MONTH  := SUBSTR(V_EXE_YYYYMMDD, 1, 6);
    V_PREV1_MONTH := TO_CHAR(ADD_MONTHS(TO_DATE(V_EXE_YYYYMMDD, 'YYYYMMDD'), -1), 'YYYYMM');
    V_PREV2_MONTH := TO_CHAR(ADD_MONTHS(TO_DATE(V_EXE_YYYYMMDD, 'YYYYMMDD'), -2), 'YYYYMM');
    V_PREV3_MONTH := TO_CHAR(ADD_MONTHS(TO_DATE(V_EXE_YYYYMMDD, 'YYYYMMDD'), -3), 'YYYYMM');
    V_PREV4_MONTH := TO_CHAR(ADD_MONTHS(TO_DATE(V_EXE_YYYYMMDD, 'YYYYMMDD'), -4), 'YYYYMM');

    /* 당월의 첫날 구하기 */
    V_CURR_MONTH_FIRSTDAY := SUBSTR(V_EXE_YYYYMMDD, 1, 6) || '01';
    /* 당월의 마지막날 구하기 */
    SELECT MAX(BASIS_YYYYMMDD) INTO V_CURR_MONTH_LASTDAY FROM SCM_SYS_CALENDAR_M A WHERE A.BASIS_YYYYMM = SUBSTR(V_EXE_YYYYMMDD, 1, 6);
    /* 당월의 첫 수요일 구하기  (당월의 첫 수요일이 있는 주가 당월의 첫주로 인식함.) */
    SELECT MIN(BASIS_YYYYMMDD)
    INTO   V_CURR_MONTH_TUESDAY
    FROM   SCM_SYS_CALENDAR_M A
    WHERE  DAYOFWEEK = 'WED'
    AND    A.BASIS_YYYYMMDD >= V_CURR_MONTH_FIRSTDAY
    AND    A.BASIS_YYYYMMDD <= V_CURR_MONTH_LASTDAY;
    /* 당월의 첫 수요일이 있는 월요일 날짜 */
    SELECT BASIS_YYYYMMDD
    INTO   V_CURR_MONTH_MONDAY
    FROM   SCM_SYS_CALENDAR_M
    WHERE  ISO_YYYYWW IN (SELECT ISO_YYYYWW FROM SCM_SYS_CALENDAR_M WHERE BASIS_YYYYMMDD = V_CURR_MONTH_TUESDAY)
    AND    DAYOFWEEK = 'MON';

    /* 당월 첫주의 MKT_FCST VERSION_NO 추출 */
    SELECT MAX(VERSION_NO)
    INTO   V_CURR_MKT_FCST_VERSION_NO
    FROM   DM_MST_VERSION
    WHERE  DIVISION_ID = V_DIVISION_ID
    AND    VERSION_TYPE = 'MF_W'
    AND    YYYYMMDD >= V_CURR_MONTH_MONDAY
    AND    YYYYMMDD < TO_CHAR(TO_DATE(V_CURR_MONTH_MONDAY, 'YYYYMMDD') + (1) * 7, 'YYYYMMDD');

    /* ----------------------------------------------------------------------------------------------------- */
    /* 대상데이터 LOG (START) */
    /* ----------------------------------------------------------------------------------------------------- */
    V_LOG_TYPE    := 'APPEND';
    V_LOG_MESSAGE := 'MKT_FCST : ' || V_DIVISION_ID;
    V_DESCRIPTION := 'VERSION(M+0) : ' || V_CURR_MKT_FCST_VERSION_NO;
    D_EVENT_DATE  := SYSTIMESTAMP;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, 0, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    IF (V_EXE_YYYYMMDD < V_CURR_MONTH_TUESDAY) THEN
        /* 종료 LOG */
        V_LOG_TYPE    := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := NULL;
        D_EVENT_DATE  := SYSTIMESTAMP;

        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        RETURN;
    END IF;

    IF (V_CURR_MKT_FCST_VERSION_NO IS NULL) THEN
        /* 종료 LOG */
        V_LOG_TYPE    := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := NULL;
        D_EVENT_DATE  := SYSTIMESTAMP;

        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        RETURN;
    END IF;

    /*STEP02 : REPLAN을 할 경우는 재수행을 위해서 당월 SUMMARY 데이터 삭제 */
    IF (V_REPLAN_YN = 'Y') THEN

        DELETE FROM DM_CUST_DEMAND_ANL_SUMMARY
        WHERE  DIVISION_ID = V_DIVISION_ID
        AND    PLAN_YYYYMM = V_CURR_MONTH;

    END IF;

    /*STEP03 : 당월의 DM_CUST_DEMAND_ANL_SUMMARY cnt=0이면 당월 Summary 수행 (단, 그렇지 않다면 프로시져 종료) */
    SELECT COUNT(*)
    INTO   V_CURR_MONTH_SUMMARY_CNT
    FROM   DM_CUST_DEMAND_ANL_SUMMARY
    WHERE  DIVISION_ID = V_DIVISION_ID
    AND    PLAN_YYYYMM = V_CURR_MONTH;

    IF (V_CURR_MONTH_SUMMARY_CNT != 0) THEN
        /* 종료 LOG */
        V_LOG_TYPE    := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := NULL;
        D_EVENT_DATE  := SYSTIMESTAMP;

        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        RETURN;
    END IF;

    /* 여기서부터 TRANSACTION 처리 */
    DBMS_OUTPUT.PUT_LINE('A1--전월 FINAL 생성 ' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));

    /*STEP04 : DM_CUST_DEMAND_ANL_SUMMARY.YYYYMM(전월-MKT_FCST_FNL)의 값 생성 */
    SELECT COUNT(*)
    INTO   V_CNT_RESULT
    FROM   DM_PLN_MKT_FCST_RESULT_C
    WHERE  DIVISION_ID = V_DIVISION_ID
    AND    VERSION_NO = V_CURR_MKT_FCST_VERSION_NO
    AND    CUTOFF_TYPE = 'MF_W';

    SELECT COUNT(*)
    INTO   V_CNT_FCST
    FROM   DM_PLN_MKT_FCST_C
    WHERE  DIVISION_ID = V_DIVISION_ID
    AND    VERSION_NO = V_CURR_MKT_FCST_VERSION_NO
    AND    CUTOFF_TYPE = 'MF_W';

    IF (V_CNT_RESULT != 0) THEN
        INSERT
        INTO GT_DCDA_DM_PLN_MKT_FCST_RESULT
            (DIVISION_ID
            ,VERSION_NO
            ,CUTOFF_TYPE
            ,CUTOFF_YYYYMMDD
            ,PROJECT_CODE
            ,SCM_SITE_ID
            ,ITEM_ID
            ,DOM_EXP
            ,FCST_TYPE
            ,INCOTERMS
            ,MEASURE
            ,PLANT_SITE_ID
            ,YYYYMMDD
            ,QTY)
            SELECT DIVISION_ID
                  ,VERSION_NO
                  ,CUTOFF_TYPE
                  ,CUTOFF_YYYYMMDD
                  ,PROJECT_CODE
                  ,SCM_SITE_ID
                  ,ITEM_ID
                  ,DOM_EXP
                  ,FCST_TYPE
                  ,INCOTERMS
                  ,MEASURE
                  ,PLANT_SITE_ID
                  ,YYYYMMDD
                  ,QTY
            FROM   DM_PLN_MKT_FCST_RESULT_C A
            WHERE  A.DIVISION_ID = V_DIVISION_ID
            AND    A.VERSION_NO = V_CURR_MKT_FCST_VERSION_NO
            AND    A.FCST_TYPE IN ('MPS', 'Mass');

    ELSE
        INSERT
        INTO GT_DCDA_DM_PLN_MKT_FCST_RESULT
            (DIVISION_ID
            ,VERSION_NO
            ,CUTOFF_TYPE
            ,CUTOFF_YYYYMMDD
            ,PROJECT_CODE
            ,SCM_SITE_ID
            ,ITEM_ID
            ,DOM_EXP
            ,FCST_TYPE
            ,INCOTERMS
            ,MEASURE
            ,PLANT_SITE_ID
            ,YYYYMMDD
            ,QTY)
            SELECT DIVISION_ID
                  ,VERSION_NO
                  ,CUTOFF_TYPE
                  ,CUTOFF_YYYYMMDD
                  ,PROJECT_CODE
                  ,SCM_SITE_ID
                  ,ITEM_ID
                  ,DOM_EXP
                  ,FCST_TYPE
                  ,INCOTERMS
                  ,MEASURE
                  ,PLANT_SITE_ID
                  ,YYYYMMDD
                  ,QTY
            FROM   DM_PLN_MKT_FCST_RESULT_C_KEEP A
            WHERE  A.DIVISION_ID = V_DIVISION_ID
            AND    A.VERSION_NO = V_CURR_MKT_FCST_VERSION_NO
            AND    A.FCST_TYPE IN ('MPS', 'Mass');
    END IF;

    IF (V_CNT_FCST != 0) THEN
        INSERT
        INTO GT_DCDA_DM_PLN_MKT_FCST
            (DIVISION_ID
            ,VERSION_NO
            ,CUTOFF_TYPE
            ,CUTOFF_YYYYMMDD
            ,PROJECT_CODE
            ,SCM_SITE_ID
            ,ITEM_ID
            ,DOM_EXP
            ,FCST_TYPE
            ,INCOTERMS
            ,MEASURE
            ,PLANT_SITE_ID
            ,YYYYMMDD
            ,QTY)
            SELECT DIVISION_ID
                  ,VERSION_NO
                  ,CUTOFF_TYPE
                  ,CUTOFF_YYYYMMDD
                  ,PROJECT_CODE
                  ,SCM_SITE_ID
                  ,ITEM_ID
                  ,DOM_EXP
                  ,FCST_TYPE
                  ,INCOTERMS
                  ,MEASURE
                  ,PLANT_SITE_ID
                  ,YYYYMMDD
                  ,QTY
            FROM   DM_PLN_MKT_FCST_C A
            WHERE  A.DIVISION_ID = V_DIVISION_ID
            AND    A.VERSION_NO = V_CURR_MKT_FCST_VERSION_NO
            AND    A.FCST_TYPE IN ('MPS', 'Mass');

    ELSE
        INSERT
        INTO GT_DCDA_DM_PLN_MKT_FCST
            (DIVISION_ID
            ,VERSION_NO
            ,CUTOFF_TYPE
            ,CUTOFF_YYYYMMDD
            ,PROJECT_CODE
            ,SCM_SITE_ID
            ,ITEM_ID
            ,DOM_EXP
            ,FCST_TYPE
            ,INCOTERMS
            ,MEASURE
            ,PLANT_SITE_ID
            ,YYYYMMDD
            ,QTY)
            SELECT DIVISION_ID
                  ,VERSION_NO
                  ,CUTOFF_TYPE
                  ,CUTOFF_YYYYMMDD
                  ,PROJECT_CODE
                  ,SCM_SITE_ID
                  ,ITEM_ID
                  ,DOM_EXP
                  ,FCST_TYPE
                  ,INCOTERMS
                  ,MEASURE
                  ,PLANT_SITE_ID
                  ,YYYYMMDD
                  ,QTY
            FROM   DM_PLN_MKT_FCST_C_KEEP A
            WHERE  A.DIVISION_ID = V_DIVISION_ID
            AND    A.VERSION_NO = V_CURR_MKT_FCST_VERSION_NO
            AND    A.FCST_TYPE IN ('MPS', 'Mass');
    END IF;

    /* 당월 CUST_FCST_QTY 및 각 월별 CUST_FCST_QTY/MKT_FCST는 동일 월의 FIRST에서 가져옴 */
    MERGE INTO DM_CUST_DEMAND_ANL_SUMMARY A
    USING (SELECT *
           FROM   DM_CUST_DEMAND_ANL_SUMMARY B
           WHERE  B.MEASURE = 'MKT_FCST_FST'
           AND    B.DIVISION_ID = V_DIVISION_ID
           AND    B.PLAN_YYYYMM = V_PREV1_MONTH) B
    ON (A.DIVISION_ID = B.DIVISION_ID AND A.END_CUSTOMER = B.END_CUSTOMER AND A.PROJECT_CODE = B.PROJECT_CODE AND A.PLAN_YYYYMM = B.PLAN_YYYYMM AND A.DIVISION_ID = V_DIVISION_ID AND A.PLAN_YYYYMM = V_PREV1_MONTH AND A.MEASURE = 'MKT_FCST_FNL')
    WHEN MATCHED THEN
        UPDATE
        SET    A.CUST_FCST_QTY    = B.CUST_FCST_QTY
              ,A.M1_CUST_FCST_QTY = B.M1_CUST_FCST_QTY
              ,A.M2_CUST_FCST_QTY = B.M2_CUST_FCST_QTY
              ,A.M3_CUST_FCST_QTY = B.M3_CUST_FCST_QTY
              ,A.M1_MKT_FCST_QTY  = B.M1_MKT_FCST_QTY
              ,A.M2_MKT_FCST_QTY  = B.M2_MKT_FCST_QTY
              ,A.M3_MKT_FCST_QTY  = B.M3_MKT_FCST_QTY
              ,A.LAST_UPDATED_BY  = V_CREATED_BY
              ,A.LAST_UPDATE_DATE = SYSDATE;
    IF (SUBSTR(V_CURR_MONTH_MONDAY, 1, 6) = V_CURR_MONTH) THEN

        MERGE INTO DM_CUST_DEMAND_ANL_SUMMARY A
        USING (SELECT B.DIVISION_ID, B.END_CUSTOMER, B.PROJECT_CODE, B.PLAN_YYYYMM, B.SUM_QTY
               FROM   (SELECT A.DIVISION_ID, B.END_CUSTOMER, A.PROJECT_CODE, SUBSTR(A.YYYYMMDD, 1, 6) PLAN_YYYYMM, SUM(A.QTY) SUM_QTY
                       FROM   GT_DCDA_DM_PLN_MKT_FCST_RESULT A
                       INNER  JOIN SCM_MST_SITE B
                       ON     A.DIVISION_ID = B.DIVISION_ID
                       AND    A.SCM_SITE_ID = B.SCM_SITE_ID
                       WHERE  A.DIVISION_ID = V_DIVISION_ID
                       AND    A.VERSION_NO = V_CURR_MKT_FCST_VERSION_NO
                       AND    A.MEASURE = 'RTF_SYS_RP'
                       AND    SUBSTR(A.YYYYMMDD, 1, 6) = V_PREV1_MONTH
                       GROUP  BY A.DIVISION_ID, B.END_CUSTOMER, A.PROJECT_CODE, SUBSTR(A.YYYYMMDD, 1, 6)) B) B
        ON (A.DIVISION_ID = B.DIVISION_ID AND A.END_CUSTOMER = B.END_CUSTOMER AND A.PROJECT_CODE = B.PROJECT_CODE AND A.PLAN_YYYYMM = B.PLAN_YYYYMM AND A.MEASURE = 'MKT_FCST_FNL' AND A.DIVISION_ID = V_DIVISION_ID AND A.PLAN_YYYYMM = V_PREV1_MONTH)
        WHEN MATCHED THEN
            UPDATE SET A.MKT_FCST_QTY = B.SUM_QTY, A.LAST_UPDATED_BY = V_CREATED_BY, A.LAST_UPDATE_DATE = SYSDATE;
    ELSIF (SUBSTR(V_CURR_MONTH_MONDAY, 1, 6) = V_PREV1_MONTH) THEN

        MERGE INTO DM_CUST_DEMAND_ANL_SUMMARY A
        USING (SELECT *
               FROM   (SELECT A.DIVISION_ID, A.END_CUSTOMER, A.PROJECT_CODE, A.PLAN_YYYYMM, SUM(A.SUM_QTY) SUM_QTY
                       FROM   (SELECT A.DIVISION_ID, B.END_CUSTOMER, A.PROJECT_CODE, SUBSTR(A.YYYYMMDD, 1, 6) PLAN_YYYYMM, SUM(A.QTY) SUM_QTY
                               FROM   GT_DCDA_DM_PLN_MKT_FCST_RESULT A
                               INNER  JOIN SCM_MST_SITE B
                               ON     A.DIVISION_ID = B.DIVISION_ID
                               AND    A.SCM_SITE_ID = B.SCM_SITE_ID
                               WHERE  A.DIVISION_ID = V_DIVISION_ID
                               AND    A.VERSION_NO = V_CURR_MKT_FCST_VERSION_NO
                               AND    A.MEASURE = 'RTF_SYS_RP'
                               AND    SUBSTR(A.YYYYMMDD, 1, 6) = V_PREV1_MONTH /* '202409' */
                               GROUP  BY A.DIVISION_ID, B.END_CUSTOMER, A.PROJECT_CODE, SUBSTR(A.YYYYMMDD, 1, 6)
                               UNION ALL
                               SELECT A.DIVISION_ID, B.END_CUSTOMER, A.PROJECT_CODE, SUBSTR(A.YYYYMMDD, 1, 6) PLAN_YYYYMM, SUM(A.QTY) SUM_QTY
                               FROM   GT_DCDA_DM_PLN_MKT_FCST A
                               INNER  JOIN SCM_MST_SITE B
                               ON     A.DIVISION_ID = B.DIVISION_ID
                               AND    A.SCM_SITE_ID = B.SCM_SITE_ID
                               WHERE  A.DIVISION_ID = V_DIVISION_ID
                               AND    A.VERSION_NO = V_CURR_MKT_FCST_VERSION_NO
                               AND    A.MEASURE = 'MKT_FCST'
                               AND    A.YYYYMMDD >= V_CURR_MONTH_MONDAY /* '20240930' */
                               AND    A.YYYYMMDD < V_CURR_MONTH_FIRSTDAY /* '20241001' */
                               GROUP  BY A.DIVISION_ID, B.END_CUSTOMER, A.PROJECT_CODE, SUBSTR(A.YYYYMMDD, 1, 6)) A
                       GROUP  BY A.DIVISION_ID, A.END_CUSTOMER, A.PROJECT_CODE, A.PLAN_YYYYMM) B) SRC_UPD
        ON (A.DIVISION_ID = SRC_UPD.DIVISION_ID AND A.END_CUSTOMER = SRC_UPD.END_CUSTOMER AND A.PROJECT_CODE = SRC_UPD.PROJECT_CODE AND A.PLAN_YYYYMM = SRC_UPD.PLAN_YYYYMM AND A.MEASURE = 'MKT_FCST_FNL' AND A.DIVISION_ID = V_DIVISION_ID AND A.PLAN_YYYYMM = V_PREV1_MONTH)
        WHEN MATCHED THEN
            UPDATE SET A.MKT_FCST_QTY = SRC_UPD.SUM_QTY, A.LAST_UPDATED_BY = V_CREATED_BY, A.LAST_UPDATE_DATE = SYSDATE;

    END IF;

    DBMS_OUTPUT.PUT_LINE('A2--당월 FIRST 생성 기준마련' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));
    /*STEP05 : DM_PLN_MKT_FCST_RESULT_C (M-26 ~ M) 사이에 있는 division / end_customer / project 코드 생성 ==> GT_DCDA_CUSTOMER_PROJECT */
    /* 당월은 아래 기준으로만 생성함. */
    INSERT
    INTO GT_DCDA_CUSTOMER_PROJECT
        SELECT DISTINCT A.DIVISION_ID, B.END_CUSTOMER, A.PROJECT_CODE, C.PROJECT_NAME
        FROM   DM_PLN_MKT_FCST_RESULT A
        INNER  JOIN SCM_MST_SITE B
        ON     A.DIVISION_ID = B.DIVISION_ID
        AND    A.SCM_SITE_ID = B.SCM_SITE_ID
        INNER  JOIN SCM_MST_PROJECT C
        ON     A.DIVISION_ID = C.DIVISION_ID
        AND    A.PROJECT_CODE = C.PROJECT_CODE
        WHERE  A.DIVISION_ID = V_DIVISION_ID
        AND    A.PROJECT_CODE IS NOT NULL
        AND    B.END_CUSTOMER IS NOT NULL
        AND    MEASURE = 'RTF_SYS_RP'
        AND    YYYYMMDD >= TO_CHAR(ADD_MONTHS(TO_DATE(V_EXE_YYYYMMDD, 'YYYYMMDD'), -12), 'YYYYMMDD') /* 12개월 기준 실적이 있을 경우만 */
        AND    YYYYMMDD <= V_EXE_YYYYMMDD
        AND    QTY != 0 /* 실적이 있을 때만 */
        GROUP  BY A.DIVISION_ID, B.END_CUSTOMER, A.PROJECT_CODE, C.PROJECT_NAME
        UNION
        SELECT A.DIVISION_ID, B.END_CUSTOMER, A.PROJECT_CODE, C.PROJECT_NAME
        FROM   DM_PLN_MKT_FCST A
        INNER  JOIN SCM_MST_SITE B
        ON     A.DIVISION_ID = B.DIVISION_ID
        AND    A.SCM_SITE_ID = B.SCM_SITE_ID
        INNER  JOIN SCM_MST_PROJECT C
        ON     A.DIVISION_ID = C.DIVISION_ID
        AND    A.PROJECT_CODE = C.PROJECT_CODE
        WHERE  A.DIVISION_ID = V_DIVISION_ID
        AND    A.PROJECT_CODE IS NOT NULL
        AND    B.END_CUSTOMER IS NOT NULL
        AND    MEASURE = 'MKT_FCST'
        AND    YYYYMMDD >= V_CURR_MONTH_FIRSTDAY
        AND    YYYYMMDD <= V_CURR_MONTH_LASTDAY
        GROUP  BY A.DIVISION_ID, B.END_CUSTOMER, A.PROJECT_CODE, C.PROJECT_NAME;

    DBMS_OUTPUT.PUT_LINE('A3--당월 FIRST 생성 ' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));

    /*STEP06 : DM_CUST_DEMAND_ANL_SUMMARY.YYYYMM(당월-MKT_FCST_FST)의 값 생성 */
    /* 과거 데이터는 집계시점의 데이터를 가져옴. */
    /* 당월 첫주 월요일이 당월일 경우 당월 계획은 (전주 실적+ 당월 계획) 이어야 함.. */
    IF (SUBSTR(V_CURR_MONTH_MONDAY, 1, 6) = V_CURR_MONTH) THEN
        DBMS_OUTPUT.PUT_LINE('A3-1--당월 FIRST 생성(1) ' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));

        INSERT INTO DM_CUST_DEMAND_ANL_SUMMARY
            (DIVISION_ID
            ,END_CUSTOMER
            ,PROJECT_CODE
            ,MEASURE
            ,PLAN_YYYYMM
            ,PROJECT_NAME
            ,CUST_FCST_QTY
            ,MKT_FCST_QTY
             /*,M1_CUST_FCST_QTY,M2_CUST_FCST_QTY,M3_CUST_FCST_QTY */
             /*,M1_MKT_FCST_QTY,M2_MKT_FCST_QTY,M3_MKT_FCST_QTY */
            ,CREATED_BY
            ,CREATION_DATE
            ,LAST_UPDATED_BY
            ,LAST_UPDATE_DATE)

            SELECT A.DIVISION_ID
                  ,A.END_CUSTOMER
                  ,A.PROJECT_CODE
                  ,'MKT_FCST_FST' AS MEASURE
                  ,V_CURR_MONTH PLAN_YYYYMM
                  ,A.PROJECT_NAME
                  ,NVL(B.SUM_QTY, 0) CUST_FCST_QTY
                  ,NVL(C.SUM_QTY, 0) MKT_FCST_QTY
                   /*, NVL(D.M1_CUST_FCST_QTY, 0) M1_CUST_FCST_QTY */
                   /*, NVL(D.M2_CUST_FCST_QTY, 0) M2_CUST_FCST_QTY */
                   /*, NVL(D.M3_CUST_FCST_QTY, 0) M3_CUST_FCST_QTY */
                   /*, NVL(D.M1_MKT_FCST_QTY, 0) M1_MKT_FCST_QTY */
                   /*, NVL(D.M2_MKT_FCST_QTY, 0) M2_MKT_FCST_QTY */
                   /*, NVL(D.M3_MKT_FCST_QTY, 0) M3_MKT_FCST_QTY */
                  ,V_CREATED_BY CREATED_BY
                  ,SYSDATE      CREATION_DATE
                  ,V_CREATED_BY LAST_UPDATED_BY
                  ,SYSDATE      LAST_UPDATE_DATE
            FROM   GT_DCDA_CUSTOMER_PROJECT A
            LEFT   OUTER JOIN (
                               /* CUST_FCST_QTY는 DM_PLN_MKT_FCST_C (CUST_FCST)에서 가져옴. */
                               /* 단, 당월의 계획값이 Result에 있어도 가져옴 */
                               /*==> 버젼은 당주 첫주차 version_no = "MF_W_20241001_V002" */
                               SELECT A.DIVISION_ID, A.END_CUSTOMER, A.PROJECT_CODE, SUM(A.SUM_QTY) SUM_QTY
                               FROM   (
                                        /*당월의 전주 실적*/
                                        SELECT A.DIVISION_ID, B.END_CUSTOMER, A.PROJECT_CODE, SUM(A.QTY) SUM_QTY
                                        FROM   GT_DCDA_DM_PLN_MKT_FCST_RESULT A
                                        INNER  JOIN SCM_MST_SITE B
                                        ON     A.DIVISION_ID = B.DIVISION_ID
                                        AND    A.SCM_SITE_ID = B.SCM_SITE_ID
                                        WHERE  A.DIVISION_ID = V_DIVISION_ID
                                        AND    A.VERSION_NO = V_CURR_MKT_FCST_VERSION_NO
                                              /*                  AND   A.MEASURE IN ('Customer FCST','CUST_FCST_EDI') */
                                        AND    A.MEASURE IN ('CUST_FCST') /* CUST_FCST = Customer FCST + CUST_FCST_EDI 임 */
                                        AND    A.YYYYMMDD >= V_CURR_MONTH_FIRSTDAY
                                        AND    A.YYYYMMDD < V_CURR_MONTH_MONDAY
                                        GROUP  BY A.DIVISION_ID, B.END_CUSTOMER, A.PROJECT_CODE
                                        UNION ALL
                                        /*당월의 당주 이후 계획*/
                                        SELECT A.DIVISION_ID, B.END_CUSTOMER, A.PROJECT_CODE, SUM(QTY) SUM_QTY
                                        FROM   GT_DCDA_DM_PLN_MKT_FCST A
                                        INNER  JOIN SCM_MST_SITE B
                                        ON     A.DIVISION_ID = B.DIVISION_ID
                                        AND    A.SCM_SITE_ID = B.SCM_SITE_ID
                                        WHERE  A.DIVISION_ID = V_DIVISION_ID
                                        AND    A.VERSION_NO = V_CURR_MKT_FCST_VERSION_NO
                                        AND    A.CUTOFF_TYPE = 'MF_W'
                                              /*AND   A.MEASURE IN ('Customer FCST','CUST_FCST_EDI') */
                                        AND    A.MEASURE IN ('CUST_FCST') /* CUST_FCST = Customer FCST + CUST_FCST_EDI 임 */
                                        AND    A.YYYYMMDD >= V_CURR_MONTH_MONDAY
                                        AND    A.YYYYMMDD <= V_CURR_MONTH_LASTDAY
                                        GROUP  BY A.DIVISION_ID, B.END_CUSTOMER, A.PROJECT_CODE) A
                               GROUP  BY A.DIVISION_ID, A.END_CUSTOMER, A.PROJECT_CODE) B
            ON     A.DIVISION_ID = B.DIVISION_ID
            AND    A.END_CUSTOMER = B.END_CUSTOMER
            AND    A.PROJECT_CODE = B.PROJECT_CODE
            LEFT   OUTER JOIN (
                               /* MTK_FCST는 당월 계획 (MKT_FCST_C.MKT_FCST mesaure.version_no = "MF_W_20241001_V002" )에서 가져옴. */
                               /* (단, 당월 첫주가 전주라면  DM_PLN_MKT_FCST_RESULT_C(RTF_SYS_RP)에서 전주 1일 실적부터 합산함) */
                               SELECT A.DIVISION_ID, A.END_CUSTOMER, A.PROJECT_CODE, SUM(SUM_QTY) SUM_QTY
                               FROM   (
                                        /*당월의 전주 실적*/
                                        SELECT A.DIVISION_ID, B.END_CUSTOMER, A.PROJECT_CODE, SUM(QTY) SUM_QTY
                                        FROM   GT_DCDA_DM_PLN_MKT_FCST_RESULT A
                                        INNER  JOIN SCM_MST_SITE B
                                        ON     A.DIVISION_ID = B.DIVISION_ID
                                        AND    A.SCM_SITE_ID = B.SCM_SITE_ID
                                        WHERE  A.DIVISION_ID = V_DIVISION_ID
                                        AND    A.VERSION_NO = V_CURR_MKT_FCST_VERSION_NO
                                        AND    A.MEASURE IN ('RTF_SYS_RP')
                                        AND    A.YYYYMMDD >= V_CURR_MONTH_FIRSTDAY /*'20241101' */
                                        AND    A.YYYYMMDD < V_CURR_MONTH_MONDAY /*'20241104' */
                                        GROUP  BY A.DIVISION_ID, B.END_CUSTOMER, A.PROJECT_CODE
                                        UNION ALL
                                        /*당월의 당주 이후 계획*/
                                        SELECT A.DIVISION_ID, B.END_CUSTOMER, A.PROJECT_CODE, SUM(QTY) SUM_QTY
                                        FROM   GT_DCDA_DM_PLN_MKT_FCST A
                                        INNER  JOIN SCM_MST_SITE B
                                        ON     A.DIVISION_ID = B.DIVISION_ID
                                        AND    A.SCM_SITE_ID = B.SCM_SITE_ID
                                        WHERE  A.DIVISION_ID = V_DIVISION_ID
                                        AND    A.VERSION_NO = V_CURR_MKT_FCST_VERSION_NO
                                        AND    A.CUTOFF_TYPE = 'MF_W'
                                        AND    A.MEASURE IN ('MKT_FCST')
                                        AND    A.YYYYMMDD >= V_CURR_MONTH_MONDAY /*'20241104' */
                                        AND    A.YYYYMMDD <= V_CURR_MONTH_LASTDAY /*'20241130' */
                                        GROUP  BY A.DIVISION_ID, B.END_CUSTOMER, A.PROJECT_CODE) A
                               GROUP  BY A.DIVISION_ID, A.END_CUSTOMER, A.PROJECT_CODE) C
            ON     A.DIVISION_ID = C.DIVISION_ID
            AND    A.END_CUSTOMER = C.END_CUSTOMER
            AND    A.PROJECT_CODE = C.PROJECT_CODE;
        /* 아래 로직은 PR_DM_CUST_DEMAND_ANL_SUMMARY_SUB 에서 생성함 */
        /*LEFT OUTER JOIN */
        /*( */
        /* -- M1_CUST_FCST_QTY / M2_CUST_FCST_QTY / M3_CUST_FCST_QTY / M1_MKT_FCST_QTY / M2_MKT_FCST_QTY / M3_MKT_FCST_QTY는  DM_CUST_DEMAND_ANL_SUMMARY (Final) 에서 가져옴. */
        /* SELECT DIVISION_ID, END_CUSTOMER, PROJECT_CODE */
        /*    , CUST_FCST_QTY M1_CUST_FCST_QTY   -- 전월의 현재는 당월은 M-1임 */
        /*    , M1_CUST_FCST_QTY M2_CUST_FCST_QTY        -- 전월의 M-1는 당월은 M-2임 */
        /*    , M2_CUST_FCST_QTY M3_CUST_FCST_QTY        -- 전월의 M-2는 당월은 M-3임 */
        /*    , MKT_FCST_QTY M1_MKT_FCST_QTY */
        /*    , M1_MKT_FCST_QTY M2_MKT_FCST_QTY */
        /*    , M2_MKT_FCST_QTY M3_MKT_FCST_QTY */
        /* FROM DM_CUST_DEMAND_ANL_SUMMARY A */
        /* WHERE A.DIVISION_ID = v_division_id */
        /* AND   A.MEASURE   = 'MKT_FCST_FNL' */
        /* AND   A.PLAN_YYYYMM = v_prev1_month */
        /*) D */
        /*ON   A.DIVISION_ID   = D.DIVISION_ID */
        /*AND A.END_CUSTOMER   = D.END_CUSTOMER */
        /*AND A.PROJECT_CODE   = D.PROJECT_CODE */

        /* 당월 첫주 월요일이 전월일 경우 당월은 모두 계획임. */
    ELSIF (SUBSTR(V_CURR_MONTH_MONDAY, 1, 6) = V_PREV1_MONTH) THEN
        DBMS_OUTPUT.PUT_LINE('A3-2--당월 FIRST 생성(2) ' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));

        INSERT INTO DM_CUST_DEMAND_ANL_SUMMARY
            (DIVISION_ID
            ,END_CUSTOMER
            ,PROJECT_CODE
            ,MEASURE
            ,PLAN_YYYYMM
            ,PROJECT_NAME
            ,CUST_FCST_QTY
            ,MKT_FCST_QTY
             /*,M1_CUST_FCST_QTY,M2_CUST_FCST_QTY,M3_CUST_FCST_QTY */
             /*,M1_MKT_FCST_QTY,M2_MKT_FCST_QTY,M3_MKT_FCST_QTY */
            ,CREATED_BY
            ,CREATION_DATE
            ,LAST_UPDATED_BY
            ,LAST_UPDATE_DATE)

            SELECT A.DIVISION_ID
                  ,A.END_CUSTOMER
                  ,A.PROJECT_CODE
                  ,'MKT_FCST_FST' AS MEASURE
                  ,V_CURR_MONTH PLAN_YYYYMM
                  ,A.PROJECT_NAME
                  ,NVL(B.SUM_QTY, 0) CUST_FCST_QTY
                  ,NVL(C.SUM_QTY, 0) MKT_FCST_QTY
                   /*, NVL(D.M1_CUST_FCST_QTY, 0) M1_CUST_FCST_QTY */
                   /*, NVL(D.M2_CUST_FCST_QTY, 0) M2_CUST_FCST_QTY */
                   /*, NVL(D.M3_CUST_FCST_QTY, 0) M3_CUST_FCST_QTY */
                   /*, NVL(D.M1_MKT_FCST_QTY, 0) M1_MKT_FCST_QTY */
                   /*, NVL(D.M2_MKT_FCST_QTY, 0) M2_MKT_FCST_QTY */
                   /*, NVL(D.M3_MKT_FCST_QTY, 0) M3_MKT_FCST_QTY */
                  ,V_CREATED_BY CREATED_BY
                  ,SYSDATE      CREATION_DATE
                  ,V_CREATED_BY LAST_UPDATED_BY
                  ,SYSDATE      LAST_UPDATE_DATE
            FROM   GT_DCDA_CUSTOMER_PROJECT A
            LEFT   OUTER JOIN (
                               /* CUST_FCST_QTY는 DM_PLN_MKT_FCST_C(Cust.FCST_RPA[P+P], CUST_FCST, CUST_FCST_EDI)에서 가져옴. ==> 버젼은 당주 첫주차 version_no = "MF_W_20241001_V002" */
                               SELECT A.DIVISION_ID, B.END_CUSTOMER, A.PROJECT_CODE, SUM(QTY) SUM_QTY
                               FROM   GT_DCDA_DM_PLN_MKT_FCST A
                               INNER  JOIN SCM_MST_SITE B
                               ON     A.DIVISION_ID = B.DIVISION_ID
                               AND    A.SCM_SITE_ID = B.SCM_SITE_ID
                               WHERE  A.DIVISION_ID = V_DIVISION_ID
                               AND    A.VERSION_NO = V_CURR_MKT_FCST_VERSION_NO
                               AND    A.CUTOFF_TYPE = 'MF_W'
                                     /*              AND   A.MEASURE IN ('Customer FCST','CUST_FCST_EDI') */
                               AND    A.MEASURE IN ('CUST_FCST') /* CUST_FCST = Customer FCST + CUST_FCST_EDI 임 */
                               AND    A.YYYYMMDD >= V_CURR_MONTH_FIRSTDAY
                               AND    A.YYYYMMDD <= V_CURR_MONTH_LASTDAY
                               GROUP  BY A.DIVISION_ID, B.END_CUSTOMER, A.PROJECT_CODE) B
            ON     A.DIVISION_ID = B.DIVISION_ID
            AND    A.END_CUSTOMER = B.END_CUSTOMER
            AND    A.PROJECT_CODE = B.PROJECT_CODE
            LEFT   OUTER JOIN (
                               /* MTK_FCST는 당월 계획 (MKT_FCST_C.MKT_FCST mesaure.version_no = "MF_W_20241001_V002" )에서 가져옴. */
                               /* (단, 당월 첫주가 전주라면  DM_PLN_MKT_FCST_RESULT_C(RTF_SYS_RP)에서 전주 1일 실적부터 합산함) */
                               SELECT A.DIVISION_ID, B.END_CUSTOMER, A.PROJECT_CODE, SUM(QTY) SUM_QTY
                               FROM   GT_DCDA_DM_PLN_MKT_FCST A
                               INNER  JOIN SCM_MST_SITE B
                               ON     A.DIVISION_ID = B.DIVISION_ID
                               AND    A.SCM_SITE_ID = B.SCM_SITE_ID
                               WHERE  A.DIVISION_ID = V_DIVISION_ID
                               AND    A.VERSION_NO = V_CURR_MKT_FCST_VERSION_NO
                               AND    A.CUTOFF_TYPE = 'MF_W'
                               AND    A.MEASURE IN ('MKT_FCST')
                               AND    A.YYYYMMDD >= V_CURR_MONTH_FIRSTDAY
                               AND    A.YYYYMMDD <= V_CURR_MONTH_LASTDAY
                               GROUP  BY A.DIVISION_ID, B.END_CUSTOMER, A.PROJECT_CODE) C
            ON     A.DIVISION_ID = C.DIVISION_ID
            AND    A.END_CUSTOMER = C.END_CUSTOMER
            AND    A.PROJECT_CODE = C.PROJECT_CODE;
        /*LEFT OUTER JOIN */
        /*( */
        /*   -- M1_CUST_FCST_QTY / M2_CUST_FCST_QTY / M3_CUST_FCST_QTY / M1_MKT_FCST_QTY / M2_MKT_FCST_QTY / M3_MKT_FCST_QTY는  DM_CUST_DEMAND_ANL_SUMMARY (Final) 에서 가져옴. */
        /* SELECT DIVISION_ID, END_CUSTOMER, PROJECT_CODE */
        /*    , CUST_FCST_QTY M1_CUST_FCST_QTY   -- 전월의 현재는 당월은 M-1임 */
        /*    , M1_CUST_FCST_QTY M2_CUST_FCST_QTY        -- 전월의 M-1는 당월은 M-2임 */
        /*    , M2_CUST_FCST_QTY M3_CUST_FCST_QTY        -- 전월의 M-2는 당월은 M-3임 */
        /*    , MKT_FCST_QTY M1_MKT_FCST_QTY */
        /*    , M1_MKT_FCST_QTY M2_MKT_FCST_QTY */
        /*    , M2_MKT_FCST_QTY M3_MKT_FCST_QTY */
        /* FROM DM_CUST_DEMAND_ANL_SUMMARY A */
        /* WHERE A.DIVISION_ID = v_division_id */
        /* AND   A.MEASURE   = 'MKT_FCST_FNL' */
        /* AND   A.PLAN_YYYYMM = v_prev1_month */
        /*) D */
        /*ON   A.DIVISION_ID   = D.DIVISION_ID */
        /*AND A.END_CUSTOMER   = D.END_CUSTOMER */
        /*AND A.PROJECT_CODE   = D.PROJECT_CODE */

    END IF;

    DBMS_OUTPUT.PUT_LINE('A4--당월 FINAL 생성 ' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));

    /*STEP07 : DM_CUST_DEMAND_ANL_SUMMARY.YYYYMM(당월-MKT_FCST_FNL)의 값 DEFALT로 생성 */
    INSERT INTO DM_CUST_DEMAND_ANL_SUMMARY
        (DIVISION_ID
        ,END_CUSTOMER
        ,PROJECT_CODE
        ,MEASURE
        ,PLAN_YYYYMM
        ,PROJECT_NAME
        ,CUST_FCST_QTY
        ,MKT_FCST_QTY
         /*,M1_CUST_FCST_QTY,M2_CUST_FCST_QTY,M3_CUST_FCST_QTY */
         /*,M1_MKT_FCST_QTY,M2_MKT_FCST_QTY,M3_MKT_FCST_QTY */
        ,CREATED_BY
        ,CREATION_DATE
        ,LAST_UPDATED_BY
        ,LAST_UPDATE_DATE)
        SELECT A.DIVISION_ID
              ,A.END_CUSTOMER
              ,A.PROJECT_CODE
              ,'MKT_FCST_FNL' AS MEASURE
              ,V_CURR_MONTH PLAN_YYYYMM
              ,A.PROJECT_NAME
              ,NVL(B.CUST_FCST_QTY, 0) CUST_FCST_QTY
              ,0 MKT_FCST_QTY
               /*, NVL(D.M1_CUST_FCST_QTY, 0) M1_CUST_FCST_QTY */
               /*, NVL(D.M2_CUST_FCST_QTY, 0) M2_CUST_FCST_QTY */
               /*, NVL(D.M3_CUST_FCST_QTY, 0) M3_CUST_FCST_QTY */
               /*, NVL(D.M1_MKT_FCST_QTY, 0) M1_MKT_FCST_QTY */
               /*, NVL(D.M2_MKT_FCST_QTY, 0) M2_MKT_FCST_QTY */
               /*, NVL(D.M3_MKT_FCST_QTY, 0) M3_MKT_FCST_QTY */
              ,V_CREATED_BY CREATED_BY
              ,SYSDATE      CREATION_DATE
              ,V_CREATED_BY LAST_UPDATED_BY
              ,SYSDATE      LAST_UPDATE_DATE
        FROM   GT_DCDA_CUSTOMER_PROJECT A
        LEFT   OUTER JOIN (SELECT DIVISION_ID, END_CUSTOMER, PROJECT_CODE, CUST_FCST_QTY CUST_FCST_QTY /* 당월의 FIRST의 CUST_FCST 가져옴 */
                           FROM   DM_CUST_DEMAND_ANL_SUMMARY A
                           WHERE  A.DIVISION_ID = V_DIVISION_ID
                           AND    A.MEASURE = 'MKT_FCST_FST'
                           AND    A.PLAN_YYYYMM = V_CURR_MONTH) B
        ON     A.DIVISION_ID = B.DIVISION_ID
        AND    A.END_CUSTOMER = B.END_CUSTOMER
        AND    A.PROJECT_CODE = B.PROJECT_CODE;
    /*LEFT OUTER JOIN */
    /*( */
    /*    -- M1_CUST_FCST_QTY / M2_CUST_FCST_QTY / M3_CUST_FCST_QTY / M1_MKT_FCST_QTY / M2_MKT_FCST_QTY / M3_MKT_FCST_QTY는  DM_CUST_DEMAND_ANL_SUMMARY (Final) 에서 가져옴. */
    /*    SELECT DIVISION_ID, END_CUSTOMER, PROJECT_CODE */
    /*            , CUST_FCST_QTY M1_CUST_FCST_QTY        -- 전월의 현재는 당월은 M-1임 */
    /*            , M1_CUST_FCST_QTY M2_CUST_FCST_QTY     -- 전월의 M-1는 당월은 M-2임 */
    /*            , M2_CUST_FCST_QTY M3_CUST_FCST_QTY     -- 전월의 M-2는 당월은 M-3임 */
    /*            , MKT_FCST_QTY M1_MKT_FCST_QTY */
    /*            , M1_MKT_FCST_QTY M2_MKT_FCST_QTY */
    /*            , M2_MKT_FCST_QTY M3_MKT_FCST_QTY */
    /*    FROM DM_CUST_DEMAND_ANL_SUMMARY A */
    /*    WHERE A.DIVISION_ID   = v_division_id */
    /*    AND   A.MEASURE     = 'MKT_FCST_FNL' */
    /*    AND   A.PLAN_YYYYMM   = v_prev1_month */
    /*) D */
    /*ON  A.DIVISION_ID = D.DIVISION_ID */
    /*AND A.END_CUSTOMER  = D.END_CUSTOMER */
    /*AND A.PROJECT_CODE  = D.PROJECT_CODE */

    /*STEP08 : 당월 기준 데이터가 없는 내용 0으로 추가 */
    INSERT INTO DM_CUST_DEMAND_ANL_SUMMARY
        (DIVISION_ID
        ,END_CUSTOMER
        ,PROJECT_CODE
        ,MEASURE
        ,PLAN_YYYYMM
        ,PROJECT_NAME
        ,CUST_FCST_QTY
        ,MKT_FCST_QTY
        ,M1_CUST_FCST_QTY
        ,M2_CUST_FCST_QTY
        ,M3_CUST_FCST_QTY
        ,M1_MKT_FCST_QTY
        ,M2_MKT_FCST_QTY
        ,M3_MKT_FCST_QTY
        ,CREATED_BY
        ,CREATION_DATE
        ,LAST_UPDATED_BY
        ,LAST_UPDATE_DATE)
        SELECT A.DIVISION_ID
              ,A.END_CUSTOMER
              ,A.PROJECT_CODE
              ,B.MEASURE
              ,V_CURR_MONTH   PLAN_YYYYMM
              ,A.PROJECT_NAME
              ,0              CUST_FCST_QTY
              ,0              MKT_FCST_QTY
              ,0              M1_CUST_FCST_QTY
              ,0              M2_CUST_FCST_QTY
              ,0              M3_CUST_FCST_QTY
              ,0              M1_MKT_FCST_QTY
              ,0              M2_MKT_FCST_QTY
              ,0              M3_MKT_FCST_QTY
              ,V_CREATED_BY   CREATED_BY
              ,SYSDATE        CREATION_DATE
              ,V_CREATED_BY   LAST_UPDATED_BY
              ,SYSDATE        LAST_UPDATE_DATE
        FROM   (SELECT A.DIVISION_ID, A.END_CUSTOMER, A.PROJECT_CODE, A.PROJECT_NAME
                FROM   GT_DCDA_CUSTOMER_PROJECT A
                LEFT   OUTER JOIN (SELECT *
                                  FROM   DM_CUST_DEMAND_ANL_SUMMARY
                                  WHERE  DIVISION_ID = V_DIVISION_ID
                                  AND    PLAN_YYYYMM = V_CURR_MONTH) B
                ON     A.DIVISION_ID = B.DIVISION_ID
                AND    A.END_CUSTOMER = B.END_CUSTOMER
                AND    A.PROJECT_CODE = B.PROJECT_CODE
                WHERE  B.DIVISION_ID IS NULL) A
              ,(SELECT 'MKT_FCST_FST' AS MEASURE FROM DUAL UNION ALL SELECT 'MKT_FCST_FNL' AS MEASURE FROM DUAL) B;

    /*STEP09 : (M-1 ~ M-3) 기준의 당월 계획 수집 */
    V_STD_MONTH := V_CURR_MONTH;

    PR_DM_CUST_DEMAND_ANL_SUMMARY_SUB(V_DIVISION_ID, V_STD_MONTH, V_PREV1_MONTH, 'M-1', O_SUB_RC1, O_SUB_RESULT);
    IF O_SUB_RC1%ISOPEN THEN CLOSE O_SUB_RC1; END IF;
    IF O_SUB_RESULT%ISOPEN THEN CLOSE O_SUB_RESULT; END IF;
    PR_DM_CUST_DEMAND_ANL_SUMMARY_SUB(V_DIVISION_ID, V_STD_MONTH, V_PREV2_MONTH, 'M-2', O_SUB_RC1, O_SUB_RESULT);
    IF O_SUB_RC1%ISOPEN THEN CLOSE O_SUB_RC1; END IF;
    IF O_SUB_RESULT%ISOPEN THEN CLOSE O_SUB_RESULT; END IF;
    PR_DM_CUST_DEMAND_ANL_SUMMARY_SUB(V_DIVISION_ID, V_STD_MONTH, V_PREV3_MONTH, 'M-3', O_SUB_RC1, O_SUB_RESULT);
    IF O_SUB_RC1%ISOPEN THEN CLOSE O_SUB_RC1; END IF;
    IF O_SUB_RESULT%ISOPEN THEN CLOSE O_SUB_RESULT; END IF;

    /*STEP10 : null 데이터 0으로 치환 */
    UPDATE DM_CUST_DEMAND_ANL_SUMMARY
    SET    CUST_FCST_QTY = 0
    WHERE  DIVISION_ID = V_DIVISION_ID
    AND    PLAN_YYYYMM = V_CURR_MONTH
    AND    CUST_FCST_QTY IS NULL;

    UPDATE DM_CUST_DEMAND_ANL_SUMMARY
    SET    MKT_FCST_QTY = 0
    WHERE  DIVISION_ID = V_DIVISION_ID
    AND    PLAN_YYYYMM = V_CURR_MONTH
    AND    MKT_FCST_QTY IS NULL;

    UPDATE DM_CUST_DEMAND_ANL_SUMMARY
    SET    M1_CUST_FCST_QTY = 0
    WHERE  DIVISION_ID = V_DIVISION_ID
    AND    PLAN_YYYYMM = V_CURR_MONTH
    AND    M1_CUST_FCST_QTY IS NULL;

    UPDATE DM_CUST_DEMAND_ANL_SUMMARY
    SET    M2_CUST_FCST_QTY = 0
    WHERE  DIVISION_ID = V_DIVISION_ID
    AND    PLAN_YYYYMM = V_CURR_MONTH
    AND    M2_CUST_FCST_QTY IS NULL;

    UPDATE DM_CUST_DEMAND_ANL_SUMMARY
    SET    M3_CUST_FCST_QTY = 0
    WHERE  DIVISION_ID = V_DIVISION_ID
    AND    PLAN_YYYYMM = V_CURR_MONTH
    AND    M3_CUST_FCST_QTY IS NULL;

    UPDATE DM_CUST_DEMAND_ANL_SUMMARY
    SET    M1_MKT_FCST_QTY = 0
    WHERE  DIVISION_ID = V_DIVISION_ID
    AND    PLAN_YYYYMM = V_CURR_MONTH
    AND    M1_MKT_FCST_QTY IS NULL;

    UPDATE DM_CUST_DEMAND_ANL_SUMMARY
    SET    M2_MKT_FCST_QTY = 0
    WHERE  DIVISION_ID = V_DIVISION_ID
    AND    PLAN_YYYYMM = V_CURR_MONTH
    AND    M2_MKT_FCST_QTY IS NULL;

    UPDATE DM_CUST_DEMAND_ANL_SUMMARY
    SET    M3_MKT_FCST_QTY = 0
    WHERE  DIVISION_ID = V_DIVISION_ID
    AND    PLAN_YYYYMM = V_CURR_MONTH
    AND    M3_MKT_FCST_QTY IS NULL;

    BEGIN
        /*2025.02.11 Philsu Park: [E20250205-000991] ITEM 단위 집계 처리 추가 수행. */
        PR_DM_CUST_DEMAND_BY_ITM_SUMMARY(P_DIVISION_ID, P_REPLAN_YN, V_EXE_YYYYMMDD);
    END;

    COMMIT;


EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;

        /* ERROR LOG */
        V_LOG_TYPE    := 'ERROR';
        V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
        V_DESCRIPTION := 'ERROR_LINE : ' || TO_CHAR(NULL);
        D_EVENT_DATE  := SYSTIMESTAMP;

        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        DBMS_OUTPUT.PUT_LINE('A12-- ERROR ' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || V_LOG_MESSAGE);


        /* 종료 LOG */
        V_LOG_TYPE    := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := NULL;
        D_EVENT_DATE  := SYSTIMESTAMP;

        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        DBMS_OUTPUT.PUT_LINE('A13-- END ' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));

        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME
                            ,'ERROR'
                            ,0
                            ,SQLERRM
                            ,NULL
                            ,SYSDATE
                            ,P_IN_PARA_DATA  => V_IN_PARA_DATA
                            ,P_SQL_ERR_CODE  => SQLCODE
                            ,P_SQL_ERR_MSG   => SQLERRM
                            ,P_SQL_BACKTRACE => DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
        RAISE_APPLICATION_ERROR(-20001
                               ,'[' || V_PROGRAM_NAME || '] SQLCODE=' || SQLCODE || ' / SQLERRM=' || SQLERRM || ' / BACKTRACE=' ||
                                DBMS_UTILITY.FORMAT_ERROR_BACKTRACE || ' / PARAMS=' || V_IN_PARA_DATA);
END PR_DM_CUST_DEMAND_ANL_SUMMARY;

PROCEDURE           "PR_DM_CUST_DEMAND_ANL_SUMMARY_SUB" 
(
     P_DIVISION_ID     VARCHAR2
    ,P_STD_MONTH       VARCHAR2            /* 202411월 기준월 */
    ,P_PREV_MONTH      VARCHAR2            /* 202409월 조사할 데이터 */
    ,P_PREV_DESC       VARCHAR2            /* M-2 : 202411월 기준으로는 202409월은 M-2월임 */
    ,O_RC1             OUT SYS_REFCURSOR
    ,O_RESULT_CURSOR   OUT SYS_REFCURSOR
)
/* ===================================================================================================
 * Program ID  : [PR_DM_CUST_DEMAND_ANL_SUMMARY_SUB]
 * Description  : 고객수요증감분석 데이터 기초값 생성 및 인터페이스 전송
 * 메인테이블
   DM_CUST_DEMAND_ANL_SUMMARY
   XIF_DM_ANL_MKT_PSI_DW_S
   XIF_DM_ANL_MKT_PSI_DETAIL_DW_S
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 2024.11.28    KANG.H.J       [PJ2024-50647] 자동차사업부 고객 수요 분석 기능 개선
 2026.07.06    ZIONEX         [PJ202650304] NextSCM Migration
 */
/*
 PR_DM_CUST_DEMAND_ANL_SUMMARY_SUB('81', '202412', '202411', 'M-1');
 */
/* ------------------------------------------------------------------------------------------------------------------------------- */
AS
    V_STEP                     VARCHAR2(4000 CHAR) := NULL;

    V_PROGRAM_NAME             VARCHAR2(150 CHAR) := $$PLSQL_UNIT;
    V_LOG_TYPE                 VARCHAR2(30 CHAR);
    N_LOG_COUNT                INTEGER := 0;
    V_LOG_MESSAGE              VARCHAR2(1000 CHAR);
    V_DESCRIPTION              VARCHAR2(500 CHAR);
    D_EVENT_DATE               DATE;
    N_DELETE_COUNT             INTEGER := 0;
    N_INSERT_COUNT             INTEGER := 0;
    V_CREATED_BY               VARCHAR2(150 CHAR) := 'PR_DM_CUST_DEMAND_ANL_SUMMARY_SUB';
    V_CURR_MONTH_FIRSTDAY      VARCHAR2(08 CHAR);
    V_CURR_MONTH_LASTDAY       VARCHAR2(08 CHAR);
    V_PREV_MONTH_TUESDAY       VARCHAR2(08 CHAR);
    V_PREV_MONTH_MONDAY        VARCHAR2(08 CHAR);
    V_PREV_MKT_FCST_VERSION_NO VARCHAR2(4000 CHAR);
    V_PREV_MONTH               VARCHAR2(8 CHAR);
    V_CURR_MONTH               VARCHAR2(06 CHAR);
    V_DELIMITER                VARCHAR2(1 CHAR);
    V_DIVISION_ID              VARCHAR2(10 CHAR);
    V_STD_MONTH                VARCHAR2(10 CHAR);
    V_PREV_DESC                VARCHAR2(10 CHAR);
    V_CNT_FCST                 INTEGER := 0;
    V_IN_PARA_DATA             VARCHAR2(4000 CHAR);
BEGIN

    IF UTL_CALL_STACK.SUBPROGRAM(1).COUNT > 1 THEN
        V_PROGRAM_NAME := $$PLSQL_UNIT || '.' || UTL_CALL_STACK.SUBPROGRAM(1)(2);
    END IF;

    V_IN_PARA_DATA := JSON_OBJECT(
            'p_division_id' VALUE P_DIVISION_ID
          , 'p_std_month' VALUE P_STD_MONTH
          , 'p_prev_month' VALUE P_PREV_MONTH
          , 'p_prev_desc' VALUE P_PREV_DESC
          );


    /* LOG 용 변수 설정 */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## START OF PROCEDURE ##########';
    V_DESCRIPTION := NULL;
    D_EVENT_DATE  := SYSTIMESTAMP;
    PR_DM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_CREATED_BY);


    DELETE FROM GT_DCDA_DM_PLN_MKT_FCST_RESULT;

    DELETE FROM GT_DCDA_DM_PLN_MKT_FCST_SUB;

    DELETE FROM GT_DCDA_DM_CUST_DEMAND_ANL_SUM;

    DELETE FROM GT_DCDA_CUSTOMER_PROJECT_SUB;

    V_DIVISION_ID := P_DIVISION_ID;
    V_STD_MONTH   := P_STD_MONTH;
    V_PREV_MONTH  := P_PREV_MONTH;
    V_PREV_DESC   := P_PREV_DESC;

    /* STEP01 : 기준데이터 정의 */
    /* 오늘기준의 당월 */
    V_CURR_MONTH := V_STD_MONTH;

    /* 당월의 첫날 구하기 */
    V_CURR_MONTH_FIRSTDAY := V_CURR_MONTH || '01';

    /* 당월의 마지막날 구하기 */
    SELECT MAX(BASIS_YYYYMMDD)
      INTO V_CURR_MONTH_LASTDAY
      FROM SCM_SYS_CALENDAR_M A
     WHERE A.BASIS_YYYYMM = V_CURR_MONTH;

    /* M-1~M-3의 첫 수요일 구하기 */
    SELECT MIN(BASIS_YYYYMMDD)
      INTO V_PREV_MONTH_TUESDAY
      FROM SCM_SYS_CALENDAR_M A
     WHERE A.DAYOFWEEK = 'WED'
       AND A.BASIS_YYYYMMDD >= V_PREV_MONTH || '01'
       AND A.BASIS_YYYYMMDD <= V_PREV_MONTH || '28';

    /* M-1~M-3의 첫 수요일이 있는 월요일 날짜 */
    SELECT BASIS_YYYYMMDD
      INTO V_PREV_MONTH_MONDAY
      FROM SCM_SYS_CALENDAR_M A
     WHERE A.ISO_YYYYWW IN (SELECT B.ISO_YYYYWW
                              FROM SCM_SYS_CALENDAR_M B
                             WHERE B.BASIS_YYYYMMDD = V_PREV_MONTH_TUESDAY)
       AND A.DAYOFWEEK = 'MON';

    /* M-1~M-3의 첫주의 MKT_FCST VERSION_NO 추출 */
    SELECT MAX(VERSION_NO)
      INTO V_PREV_MKT_FCST_VERSION_NO
      FROM DM_MST_VERSION A
     WHERE A.DIVISION_ID = V_DIVISION_ID
       AND A.VERSION_TYPE = 'MF_W'
       AND A.YYYYMMDD >= V_PREV_MONTH_MONDAY
       AND A.YYYYMMDD < TO_CHAR(TO_DATE(V_PREV_MONTH_MONDAY, 'YYYYMMDD') + (1) * 7, 'YYYYMMDD');

    /* 여기서부터 TRANSACTION 처리 */
    DBMS_OUTPUT.PUT_LINE('A1--대상 데이터 추출 ' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));

    /* STEP02 : 대상 데이터 추출 */
    SELECT COUNT(*)
      INTO V_CNT_FCST
      FROM DM_PLN_MKT_FCST_C A
     WHERE A.DIVISION_ID = V_DIVISION_ID
       AND A.VERSION_NO = V_PREV_MKT_FCST_VERSION_NO
       AND A.CUTOFF_TYPE = 'MF_W';

    IF (V_CNT_FCST != 0) THEN
        INSERT
          INTO GT_DCDA_DM_PLN_MKT_FCST_SUB
             ( DIVISION_ID
             , VERSION_NO
             , CUTOFF_TYPE
             , CUTOFF_YYYYMMDD
             , PROJECT_CODE
             , SCM_SITE_ID
             , ITEM_ID
             , DOM_EXP
             , FCST_TYPE
             , INCOTERMS
             , MEASURE
             , PLANT_SITE_ID
             , YYYYMMDD
             , QTY )
        SELECT A.DIVISION_ID
             , A.VERSION_NO
             , A.CUTOFF_TYPE
             , A.CUTOFF_YYYYMMDD
             , A.PROJECT_CODE
             , A.SCM_SITE_ID
             , A.ITEM_ID
             , A.DOM_EXP
             , A.FCST_TYPE
             , A.INCOTERMS
             , A.MEASURE
             , A.PLANT_SITE_ID
             , A.YYYYMMDD
             , A.QTY
          FROM DM_PLN_MKT_FCST_C A
         WHERE A.DIVISION_ID = V_DIVISION_ID
           AND A.VERSION_NO = V_PREV_MKT_FCST_VERSION_NO
           AND A.FCST_TYPE IN ('MPS', 'Mass');

    ELSE
        INSERT
          INTO GT_DCDA_DM_PLN_MKT_FCST_SUB
             ( DIVISION_ID
             , VERSION_NO
             , CUTOFF_TYPE
             , CUTOFF_YYYYMMDD
             , PROJECT_CODE
             , SCM_SITE_ID
             , ITEM_ID
             , DOM_EXP
             , FCST_TYPE
             , INCOTERMS
             , MEASURE
             , PLANT_SITE_ID
             , YYYYMMDD
             , QTY )
        SELECT A.DIVISION_ID
             , A.VERSION_NO
             , A.CUTOFF_TYPE
             , A.CUTOFF_YYYYMMDD
             , A.PROJECT_CODE
             , A.SCM_SITE_ID
             , A.ITEM_ID
             , A.DOM_EXP
             , A.FCST_TYPE
             , A.INCOTERMS
             , A.MEASURE
             , A.PLANT_SITE_ID
             , A.YYYYMMDD
             , A.QTY
          FROM DM_PLN_MKT_FCST_C_KEEP A
         WHERE A.DIVISION_ID = V_DIVISION_ID
           AND A.VERSION_NO = V_PREV_MKT_FCST_VERSION_NO
           AND A.FCST_TYPE IN ('MPS', 'Mass');
    END IF;

    DBMS_OUTPUT.PUT_LINE('A2- M-1~M-3 생성 기준마련' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));

    /* STEP03 : DM_PLN_MKT_FCST_RESULT_C (M-26 ~ M) 사이에 있는 division / end_customer / project 코드 생성 ==> GT_DCDA_CUSTOMER_PROJECT_SUB (데이터 생성의 기준점이 됨) */
    /* 당월은 아래 기준으로만 생성함. */
    INSERT
      INTO GT_DCDA_CUSTOMER_PROJECT_SUB
    SELECT A.DIVISION_ID
         , B.END_CUSTOMER
         , A.PROJECT_CODE
         , C.PROJECT_NAME
      FROM DM_PLN_MKT_FCST_RESULT A
         , SCM_MST_SITE           B
         , SCM_MST_PROJECT        C
     WHERE A.DIVISION_ID = B.DIVISION_ID
       AND A.SCM_SITE_ID = B.SCM_SITE_ID
       AND A.DIVISION_ID = C.DIVISION_ID
       AND A.PROJECT_CODE = C.PROJECT_CODE
       AND A.DIVISION_ID = V_DIVISION_ID
       AND A.PROJECT_CODE IS NOT NULL
       AND B.END_CUSTOMER IS NOT NULL
       AND A.MEASURE = 'RTF_SYS_RP'
       AND A.YYYYMMDD >= TO_CHAR(ADD_MONTHS(TO_DATE(V_PREV_MONTH || '01', 'YYYYMMDD'), -26), 'YYYYMMDD')  /* 당월이전 26개월 이후로 하되. */
       AND A.YYYYMMDD <  TO_CHAR(ADD_MONTHS(TO_DATE(V_PREV_MONTH || '01', 'YYYYMMDD'), +1), 'YYYYMMDD')   /* 당월보다는 작아야 함. */
     GROUP BY A.DIVISION_ID, B.END_CUSTOMER, A.PROJECT_CODE, C.PROJECT_NAME
     UNION
    SELECT A.DIVISION_ID
         , B.END_CUSTOMER
         , A.PROJECT_CODE
         , C.PROJECT_NAME
      FROM DM_PLN_MKT_FCST   A
         , SCM_MST_SITE      B
         , SCM_MST_PROJECT   C
     WHERE A.DIVISION_ID = B.DIVISION_ID
       AND A.SCM_SITE_ID = B.SCM_SITE_ID
       AND A.DIVISION_ID = C.DIVISION_ID
       AND A.PROJECT_CODE = C.PROJECT_CODE
       AND A.DIVISION_ID = V_DIVISION_ID
       AND A.PROJECT_CODE IS NOT NULL
       AND B.END_CUSTOMER IS NOT NULL
       AND A.MEASURE = 'MKT_FCST'
       AND A.YYYYMMDD >= V_CURR_MONTH_FIRSTDAY
       AND A.YYYYMMDD <= V_CURR_MONTH_LASTDAY
     GROUP BY A.DIVISION_ID, B.END_CUSTOMER, A.PROJECT_CODE, C.PROJECT_NAME;

    DBMS_OUTPUT.PUT_LINE('A3--당월 FIRST 생성 ' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));

    /* STEP04 : M-1 ~ M-3 중 대상이 되는 (CUST_FCST / MKT_FCST_FST)의 값 생성 */
    DBMS_OUTPUT.PUT_LINE('A3-1--당월 FIRST 생성' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));

    INSERT
      INTO GT_DCDA_DM_CUST_DEMAND_ANL_SUM
         ( DIVISION_ID
         , END_CUSTOMER
         , PROJECT_CODE
         , PLAN_YYYYMM
         , PROJECT_NAME
         , CUST_FCST_QTY
         , MKT_FCST_QTY
         , PREV_DESC )
    SELECT A.DIVISION_ID
         , A.END_CUSTOMER
         , A.PROJECT_CODE
         , V_CURR_MONTH        PLAN_YYYYMM
         , A.PROJECT_NAME
         , NVL(B.SUM_QTY, 0)   CUST_FCST_QTY
         , NVL(C.SUM_QTY, 0)   MKT_FCST_QTY
         , P_PREV_DESC         PREV_DESC
      FROM GT_DCDA_CUSTOMER_PROJECT_SUB A
         , ( /* CUST_FCST_QTY는 DM_PLN_MKT_FCST_C(Cust.FCST_RPA[P+P], CUST_FCST, CUST_FCST_EDI)에서 가져옴. ==> 버젼은 당주 첫주차 version_no = "MF_W_20241001_V002" */
             SELECT D.DIVISION_ID
                  , E.END_CUSTOMER
                  , D.PROJECT_CODE
                  , SUM(D.QTY) SUM_QTY
               FROM GT_DCDA_DM_PLN_MKT_FCST_SUB D
                  , SCM_MST_SITE               E
              WHERE D.DIVISION_ID = E.DIVISION_ID
                AND D.SCM_SITE_ID = E.SCM_SITE_ID
                AND D.DIVISION_ID = V_DIVISION_ID
                AND D.VERSION_NO = V_PREV_MKT_FCST_VERSION_NO
                AND D.CUTOFF_TYPE = 'MF_W'
                    /* AND   D.MEASURE IN ('Customer FCST','CUST_FCST_EDI') */
                AND D.MEASURE IN ('CUST_FCST')  /* CUST_FCST = Customer FCST + CUST_FCST_EDI 임 */
                AND D.YYYYMMDD >= V_CURR_MONTH_FIRSTDAY
                AND D.YYYYMMDD <= V_CURR_MONTH_LASTDAY
              GROUP BY D.DIVISION_ID, E.END_CUSTOMER, D.PROJECT_CODE ) B
         , ( /* MTK_FCST는 당월 계획 (MKT_FCST_C.MKT_FCST mesaure.version_no = "MF_W_20241001_V002" )에서 가져옴. */
             /* (단, 당월 첫주가 전주라면  DM_PLN_MKT_FCST_RESULT_C(RTF_SYS_RP)에서 전주 1일 실적부터 합산함) */
             SELECT F.DIVISION_ID
                  , G.END_CUSTOMER
                  , F.PROJECT_CODE
                  , SUM(F.QTY) SUM_QTY
               FROM GT_DCDA_DM_PLN_MKT_FCST_SUB F
                  , SCM_MST_SITE               G
              WHERE F.DIVISION_ID = G.DIVISION_ID
                AND F.SCM_SITE_ID = G.SCM_SITE_ID
                AND F.DIVISION_ID = V_DIVISION_ID
                AND F.VERSION_NO = V_PREV_MKT_FCST_VERSION_NO
                AND F.CUTOFF_TYPE = 'MF_W'
                AND F.MEASURE IN ('MKT_FCST')
                AND F.YYYYMMDD >= V_CURR_MONTH_FIRSTDAY
                AND F.YYYYMMDD <= V_CURR_MONTH_LASTDAY
              GROUP BY F.DIVISION_ID, G.END_CUSTOMER, F.PROJECT_CODE ) C
     WHERE A.DIVISION_ID = B.DIVISION_ID(+)
       AND A.END_CUSTOMER = B.END_CUSTOMER(+)
       AND A.PROJECT_CODE = B.PROJECT_CODE(+)
       AND A.DIVISION_ID = C.DIVISION_ID(+)
       AND A.END_CUSTOMER = C.END_CUSTOMER(+)
       AND A.PROJECT_CODE = C.PROJECT_CODE(+);


    DBMS_OUTPUT.PUT_LINE('A4--당월 FINAL 생성 ' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));

    /* STEP05 : M-1 ~ M-3 중 대상이 되는 (CUST_FCST / MKT_FCST_FST)의 데이터 UPDATE */
    IF ( P_PREV_DESC = 'M-1') THEN

        MERGE INTO DM_CUST_DEMAND_ANL_SUMMARY A
        USING GT_DCDA_DM_CUST_DEMAND_ANL_SUM B
        ON ( A.DIVISION_ID = B.DIVISION_ID
         AND A.END_CUSTOMER = B.END_CUSTOMER
         AND A.PROJECT_CODE = B.PROJECT_CODE
         AND A.PROJECT_NAME = B.PROJECT_NAME
         AND A.PLAN_YYYYMM = P_STD_MONTH )
        WHEN MATCHED THEN
            UPDATE SET A.M1_CUST_FCST_QTY = B.CUST_FCST_QTY
                     , A.M1_MKT_FCST_QTY = B.MKT_FCST_QTY;

        /* ----------------------------------------------------------------------------------------------------- */
        /* 대상데이터 LOG (START) */
        /* ----------------------------------------------------------------------------------------------------- */
        V_LOG_TYPE    := 'APPEND';
        V_LOG_MESSAGE := 'MKT_FCST : ' || V_DIVISION_ID;
        V_DESCRIPTION := 'VERSION(M-1) : ' || V_PREV_MKT_FCST_VERSION_NO;
        D_EVENT_DATE  := SYSTIMESTAMP;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, 0, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE
          , P_IN_PARA_DATA => V_IN_PARA_DATA
          );

    ELSIF ( P_PREV_DESC = 'M-2') THEN
        MERGE INTO DM_CUST_DEMAND_ANL_SUMMARY A
        USING GT_DCDA_DM_CUST_DEMAND_ANL_SUM B
        ON ( A.DIVISION_ID = B.DIVISION_ID
         AND A.END_CUSTOMER = B.END_CUSTOMER
         AND A.PROJECT_CODE = B.PROJECT_CODE
         AND A.PROJECT_NAME = B.PROJECT_NAME
         AND A.PLAN_YYYYMM = P_STD_MONTH )
        WHEN MATCHED THEN
            UPDATE SET A.M2_CUST_FCST_QTY = B.CUST_FCST_QTY
                     , A.M2_MKT_FCST_QTY = B.MKT_FCST_QTY;

        /* ----------------------------------------------------------------------------------------------------- */
        /* 대상데이터 LOG (START) */
        /* ----------------------------------------------------------------------------------------------------- */
        V_LOG_TYPE    := 'APPEND';
        V_LOG_MESSAGE := 'MKT_FCST : ' || V_DIVISION_ID;
        V_DESCRIPTION := 'VERSION(M-2) : ' || V_PREV_MKT_FCST_VERSION_NO;
        D_EVENT_DATE  := SYSTIMESTAMP;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, 0, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE
          , P_IN_PARA_DATA => V_IN_PARA_DATA
          );

    ELSIF ( P_PREV_DESC = 'M-3') THEN
        MERGE INTO DM_CUST_DEMAND_ANL_SUMMARY A
        USING GT_DCDA_DM_CUST_DEMAND_ANL_SUM B
        ON ( A.DIVISION_ID = B.DIVISION_ID
         AND A.END_CUSTOMER = B.END_CUSTOMER
         AND A.PROJECT_CODE = B.PROJECT_CODE
         AND A.PROJECT_NAME = B.PROJECT_NAME
         AND A.PLAN_YYYYMM = P_STD_MONTH )
        WHEN MATCHED THEN
            UPDATE SET A.M3_CUST_FCST_QTY = B.CUST_FCST_QTY
                     , A.M3_MKT_FCST_QTY = B.MKT_FCST_QTY;

        /* ----------------------------------------------------------------------------------------------------- */
        /* 대상데이터 LOG (START) */
        /* ----------------------------------------------------------------------------------------------------- */
        V_LOG_TYPE    := 'APPEND';
        V_LOG_MESSAGE := 'MKT_FCST : ' || V_DIVISION_ID;
        V_DESCRIPTION := 'VERSION(M-3) : ' || V_PREV_MKT_FCST_VERSION_NO;
        D_EVENT_DATE  := SYSTIMESTAMP;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, 0, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE
          , P_IN_PARA_DATA => V_IN_PARA_DATA
          );

    END IF;


    OPEN O_RC1 FOR
    SELECT '0'                 AS CODE
         , 'SUCCESS'           AS MSG
         , TO_CHAR(N_LOG_COUNT) AS EVENT
      FROM DUAL;


    OPEN O_RESULT_CURSOR FOR
    SELECT '1'                                          AS RESULT_CODE
         , CASE WHEN 1 = 2 THEN '-' ELSE NULL END       AS RESULT_MSG
         , 'SUCCESS'                                    AS ERR_EVENT
      FROM DUAL;
EXCEPTION
    WHEN OTHERS THEN

        ROLLBACK;

        /* ERROR LOG */
        PR_SCM_SYS_LOG_BATCH(
            V_PROGRAM_NAME, 'ERROR', 0, SQLERRM, NULL, SYSDATE
          , P_IN_PARA_DATA => V_IN_PARA_DATA
          , P_SQL_ERR_CODE => SQLCODE
          , P_SQL_ERR_MSG  => SQLERRM
          , P_SQL_BACKTRACE => DBMS_UTILITY.FORMAT_ERROR_BACKTRACE
        );
        RAISE_APPLICATION_ERROR(-20001
          , '[' || V_PROGRAM_NAME || '] SQLCODE=' || SQLCODE ||
            ' / SQLERRM=' || SQLERRM ||
            ' / BACKTRACE=' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE ||
            ' / PARAMS=' || V_IN_PARA_DATA
        );
END;

PROCEDURE           "PR_DM_CUTOFF_DATA_CLEANSING" 
/* =====================================================================================================
 * Program ID   : PR_DM_CUTOFF_DATA_CLEANSING
 * Description  :
 * Program History
 *-----------------------------------------------------------------------------------------------------
 *   Date       In Charge      Description
 *-----------------------------------------------------------------------------------------------------
 * 2018. 10. 30    SongKH      Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 * 2020/09/09     P.C.I		[C20200909-000203] LOG 표준화 적용
 * 2021/03/16		HWI1993	[C20210316-000106] Daily Cutoff Data Cleansing, 삭제주기를 -7*8 --> -7*2 (2주전 월요일 이전데이터), 삭제단위를 5만으로 변경, 환율테이블 추가함.
 * 2021/03/18		HWI1993	성능문제로 테이블별로 인덱스에 맞춰서 삭제쿼리 다시 작성함.
 * 2021/06/24		hwi1993	[2021하반기과제] 성능개선 - 컷오프테이블 데이터 이동
 * 2021/07/23		hwi1993	[2021하반기과제] 소형 중장기계획에 따른 DM_PLN_BP_FCST_C_KEEP 컬럼변경 적용
 * 2022/01/04		kdw2819 [C20220103-000581] 다빈치 DataLake 데이터 수집을 위한 보관테이블 이력 기록
 * 2022.04.05       HWI1993 GM JV 작업
 * 2022.06.21		rosia27	[C20220609-000168]GSCM Business Plan 신규 키컬럼 추가 및 체크박스 옵션 추가 요청의 건
 * 2022.09.23		rosia27	[C20220905-000191]Sales Report 데이터 보관 기간 설정의 건
 * 2024.05.09		JSSBAE	[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
 * 2024.12.01		KANG.H.J [PJ2024-50611]  FROM_SITE_ID 추가
 * 2025.02.05		KANG.H.J [PJ2025-50017] 소형 매출계획 동기화 개선 - DM_PLN_CFM_MKT_DEMAND_PLAN 동기화
 * 2025.04.08		KANG.H.J [PJ2025-50017] 소형 매출계획 동기화 개선 - DM_PLN_RTF_ALLOCATION 삭제처리
 * 2025.04.25		KANG.H.J [PJ2025-50017] 소형 매출계획 동기화 개선 - DM_PLN_CFM_MKT_DEMAND_PLAN_C_KEEP 등록
 * 2025.06.23		KANG.H.J [PJ2025-50188] 매출실적 CELL_PROD_SITE_ID 추가
 * 2025.07.24		KANG.H.J [PJ2025-50188] 소형 매출계획 동기화 개선 - DM_PLN_CFM_MKT_DEMAND_PLAN_C_KEEP / DM_PLN_CFM_SELLING_PRICE_C_KEEP 등록
 * 2026.07.06   ZIONEX  [PJ202650304]  NextSCM Migration
 * ===================================================================================================== */
AS

    V_PROGRAM_NAME  VARCHAR2(150 CHAR) := 'PR_DM_CUTOFF_DATA_CLEANSING';
    V_LOG_TYPE      VARCHAR2(30 CHAR);
    N_LOG_COUNT     INTEGER := 0;
    V_LOG_MESSAGE   VARCHAR2(1000 CHAR);
    V_DESCRIPTION   VARCHAR2(500 CHAR);
    D_EVENT_DATE    DATE;

    V_VERSION_NO    VARCHAR2(50 CHAR);
    V_WEEKDAY       NUMBER;
    V_DATA_CNT      INTEGER;
    V_MOVE_CNT      INTEGER;
    V_DIVISION_ID   VARCHAR2(30 CHAR);
BEGIN

    /* 시작 LOG (START) */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := NULL;
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    V_LOG_MESSAGE := NULL; /* <- 변수 재사용을 위하여 초기화해야함 */

    BEGIN


        V_WEEKDAY := MOD(TRUNC(SYSDATE) - TRUNC(SYSDATE, 'IW') + 1, 7) + 1;

        /* ============================ DAILY CUTOFF DATA 삭제 ============================ */

        /* dm_pln_mkt_fcst_c 삭제 */
        IF V_WEEKDAY IN (1, 7) THEN
            FOR R IN ( SELECT A.VERSION_NO
                         FROM DM_MST_VERSION    A
                            , DM_PLN_MKT_FCST_C  B
                        WHERE A.DIVISION_ID  = B.DIVISION_ID
                          AND A.VERSION_TYPE = B.CUTOFF_TYPE
                          AND A.YYYYMMDD     = B.CUTOFF_YYYYMMDD
                          AND A.VERSION_NO   = B.VERSION_NO
                          AND A.YYYYMMDD     < TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') + (-7 * 2), 'YYYYMMDD')
                          AND A.VERSION_TYPE = 'MF_D'
                        GROUP BY A.VERSION_NO
                        ORDER BY A.VERSION_NO ) LOOP
                DELETE
                  FROM DM_PLN_MKT_FCST_C
                 WHERE VERSION_NO  = R.VERSION_NO
                   AND DIVISION_ID IN ( SELECT DIVISION_ID
                                          FROM SCM_MST_DIVISION
                                         WHERE ATTRIBUTE3 IN ('40', '81', '82') );
                V_WEEKDAY := MOD(TRUNC(SYSDATE) - TRUNC(SYSDATE, 'IW') + 1, 7) + 1;
                EXIT WHEN V_WEEKDAY NOT IN (1, 7);
            END LOOP;
        END IF;

        V_LOG_TYPE    := 'PROCESS';
        V_LOG_MESSAGE := '########## Process............##########';
        V_DESCRIPTION := 'dm_pln_mkt_fcst_c 삭제';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
        V_LOG_MESSAGE := NULL; /* <- 변수 재사용을 위하여 초기화해야함 */

        /* dm_pln_sales_plan_c 삭제 */
        IF V_WEEKDAY IN (1, 7) THEN
            FOR R IN ( SELECT DISTINCT A.VERSION_NO
                         FROM DM_MST_VERSION      A
                            , DM_PLN_SALES_PLAN_C  B
                        WHERE A.DIVISION_ID     = B.DIVISION_ID
                          AND A.VERSION_NO      = B.VERSION_NO
                          AND B.CUTOFF_TYPE     = 'SP_D'
                          AND B.CUTOFF_YYYYMMDD < TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') + (-7 * 2), 'YYYYMMDD')
                          AND A.YYYYMMDD        < TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') + (-7 * 2), 'YYYYMMDD')
                          AND A.VERSION_TYPE    = 'SP_D'
                        GROUP BY A.VERSION_NO
                        ORDER BY A.VERSION_NO ) LOOP
                DELETE
                  FROM DM_PLN_SALES_PLAN_C
                 WHERE VERSION_NO  = R.VERSION_NO
                   AND DIVISION_ID IN ( SELECT DIVISION_ID
                                          FROM SCM_MST_DIVISION
                                         WHERE ATTRIBUTE3 IN ('40', '81', '82') );
                V_WEEKDAY := MOD(TRUNC(SYSDATE) - TRUNC(SYSDATE, 'IW') + 1, 7) + 1;
                EXIT WHEN V_WEEKDAY NOT IN (1, 7);
            END LOOP;
        END IF;

        V_LOG_TYPE    := 'PROCESS';
        V_LOG_MESSAGE := '########## Process............##########';
        V_DESCRIPTION := 'dm_pln_sales_plan_c 삭제';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
        V_LOG_MESSAGE := NULL; /* <- 변수 재사용을 위하여 초기화해야함 */

        /* dm_pln_mkt_fcst_result_c 삭제 */
        IF V_WEEKDAY IN (1, 7) THEN
            FOR R IN ( SELECT A.VERSION_NO
                         FROM DM_MST_VERSION           A
                            , DM_PLN_MKT_FCST_RESULT_C  B
                        WHERE A.DIVISION_ID  = B.DIVISION_ID
                          AND A.VERSION_TYPE = B.CUTOFF_TYPE
                          AND A.YYYYMMDD     = B.CUTOFF_YYYYMMDD
                          AND A.VERSION_NO   = B.VERSION_NO
                          AND A.YYYYMMDD     < TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') + (-7 * 2), 'YYYYMMDD')
                          AND A.VERSION_TYPE = 'MF_D'
                        GROUP BY A.VERSION_NO
                        ORDER BY A.VERSION_NO ) LOOP
                DELETE
                  FROM DM_PLN_MKT_FCST_RESULT_C
                 WHERE VERSION_NO  = R.VERSION_NO
                   AND DIVISION_ID IN ( SELECT DIVISION_ID
                                          FROM SCM_MST_DIVISION
                                         WHERE ATTRIBUTE3 IN ('40', '81', '82') );
                V_WEEKDAY := MOD(TRUNC(SYSDATE) - TRUNC(SYSDATE, 'IW') + 1, 7) + 1;
                EXIT WHEN V_WEEKDAY NOT IN (1, 7);
            END LOOP;
        END IF;

        V_LOG_TYPE    := 'PROCESS';
        V_LOG_MESSAGE := '########## Process............##########';
        V_DESCRIPTION := 'dm_pln_mkt_fcst_result_c 삭제';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
        V_LOG_MESSAGE := NULL; /* <- 변수 재사용을 위하여 초기화해야함 */

        /* dm_pln_sales_plan_result_c 삭제 */
        IF V_WEEKDAY IN (1, 7) THEN
            FOR R IN ( SELECT A.VERSION_NO
                         FROM DM_MST_VERSION             A
                            , DM_PLN_SALES_PLAN_RESULT_C  B
                        WHERE A.DIVISION_ID  = B.DIVISION_ID
                          AND A.VERSION_TYPE = B.CUTOFF_TYPE
                          AND A.YYYYMMDD     = B.CUTOFF_YYYYMMDD
                          AND A.VERSION_NO   = B.VERSION_NO
                          AND A.YYYYMMDD     < TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') + (-7 * 2), 'YYYYMMDD')
                          AND A.VERSION_TYPE = 'SP_D'
                        GROUP BY A.VERSION_NO
                        ORDER BY A.VERSION_NO ) LOOP
                DELETE
                  FROM DM_PLN_SALES_PLAN_RESULT_C
                 WHERE VERSION_NO  = R.VERSION_NO
                   AND DIVISION_ID IN ( SELECT DIVISION_ID
                                          FROM SCM_MST_DIVISION
                                         WHERE ATTRIBUTE3 IN ('40', '81', '82') );
                V_WEEKDAY := MOD(TRUNC(SYSDATE) - TRUNC(SYSDATE, 'IW') + 1, 7) + 1;
