         WHERE WORK_YYYYMMDD < TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') + (-7 * 27), 'YYYYMMDD');

        DELETE
          FROM DM_ANL_KPI_SALES_ACCURACY
         WHERE WORK_YYYYMMDD < TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') + (-7 * 27), 'YYYYMMDD');

        V_LOG_TYPE    := 'PROCESS';
        V_LOG_MESSAGE := '########## Process............##########';
        V_DESCRIPTION := 'KPI 삭제';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
        V_LOG_MESSAGE := NULL; /* <- 변수 재사용을 위하여 초기화해야함 */


        IF V_WEEKDAY IN (1, 7) THEN
            FOR R IN ( SELECT A.VERSION_NO
                            , A.DIVISION_ID
                         FROM DM_MST_VERSION          A
                            , DM_PLN_DEMANDID_PEGGING  B
                        WHERE A.DIVISION_ID = B.DIVISION_ID
                          AND A.VERSION_NO  = B.VERSION_NO
                          AND A.YYYYMMDD    < TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') + (-7 * 14), 'YYYYMMDD')
                        GROUP BY A.VERSION_NO, A.DIVISION_ID ) LOOP
                V_VERSION_NO  := R.VERSION_NO;
                V_DIVISION_ID := R.DIVISION_ID;

                DELETE
                  FROM DM_PLN_DEMANDID_PEGGING
                 WHERE VERSION_NO  = V_VERSION_NO
                   AND DIVISION_ID = V_DIVISION_ID;

                V_WEEKDAY := MOD(TRUNC(SYSDATE) - TRUNC(SYSDATE, 'IW') + 1, 7) + 1;
                EXIT WHEN V_WEEKDAY NOT IN (1, 7);
            END LOOP;
        END IF;

        V_LOG_TYPE    := 'PROCESS';
        V_LOG_MESSAGE := '########## Process............##########';
        V_DESCRIPTION := 'DM_PLN_DEMANDID_PEGGING 삭제';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
        V_LOG_MESSAGE := NULL; /* <- 변수 재사용을 위하여 초기화해야함 */


        IF V_WEEKDAY IN (1, 7) THEN
            FOR R IN ( SELECT A.VERSION_NO
                            , A.DIVISION_ID
                         FROM DM_MST_VERSION      A
                            , DM_PLN_NET_DEMAND    B
                        WHERE A.DIVISION_ID = B.DIVISION_ID
                          AND A.VERSION_NO  = B.VERSION_NO
                          AND A.YYYYMMDD    < TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') + (-7 * 14), 'YYYYMMDD')
                        GROUP BY A.VERSION_NO, A.DIVISION_ID ) LOOP
                V_VERSION_NO  := R.VERSION_NO;
                V_DIVISION_ID := R.DIVISION_ID;

                DELETE
                  FROM DM_PLN_NET_DEMAND
                 WHERE VERSION_NO  = V_VERSION_NO
                   AND DIVISION_ID = V_DIVISION_ID;

                V_WEEKDAY := MOD(TRUNC(SYSDATE) - TRUNC(SYSDATE, 'IW') + 1, 7) + 1;
                EXIT WHEN V_WEEKDAY NOT IN (1, 7);
            END LOOP;
        END IF;

        V_LOG_TYPE    := 'PROCESS';
        V_LOG_MESSAGE := '########## Process............##########';
        V_DESCRIPTION := 'DM_PLN_NET_DEMAND 삭제';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
        V_LOG_MESSAGE := NULL; /* <- 변수 재사용을 위하여 초기화해야함 */


        DELETE
          FROM DM_PLN_SALES_PLAN_REPORT_C A
         WHERE EXISTS ( SELECT 1
                          FROM DM_MDF_VERSION B
                         WHERE B.DIVISION_ID   = A.DIVISION_ID
                           AND B.VERSION_NO    = A.VERSION_NO
                           AND B.CREATION_DATE < ADD_MONTHS(SYSDATE, -3)
                           AND B.SEND_YN      <> 'Y' );


        IF V_WEEKDAY IN (1, 7) THEN
            FOR R IN ( SELECT A.VERSION_NO
                            , A.DIVISION_ID
                            , COUNT(*)  AS CNT
                         FROM DM_MDF_VERSION               A
                            , DM_PLN_SALES_PLAN_REPORT_C    B
                        WHERE A.DIVISION_ID   = B.DIVISION_ID
                          AND A.VERSION_NO    = B.VERSION_NO
                          AND A.CREATION_DATE < ADD_MONTHS(SYSDATE, -18)
                          AND NVL(A.ATTRIBUTE3, ' ') <> 'MOVE'
                        GROUP BY A.VERSION_NO, A.DIVISION_ID ) LOOP
                V_VERSION_NO  := R.VERSION_NO;
                V_DIVISION_ID := R.DIVISION_ID;
                V_DATA_CNT    := R.CNT;

                UPDATE DM_MDF_VERSION
                   SET ATTRIBUTE3 = 'ING'
                 WHERE DIVISION_ID = V_DIVISION_ID
                   AND VERSION_NO  = V_VERSION_NO;

                INSERT
                  INTO DM_PLN_SALES_PLAN_REPORT_C_KEEP
                     ( DATA_TYPE
                     , DIVISION_ID
                     , VERSION_NO
                     , CUTOFF_TYPE
                     , CUTOFF_YYYYMMDD
                     , DEPARTMENT_ID
                     , DEPARTMENT_NAME
                     , DEPT_ID
                     , DEPT_NAME
                     , END_CUST_REPORT
                     , CUST_REPORT
                     , PRODUCT_GROUP
                     , PROJECT_CODE
                     , SCM_SITE_ID
                     , ITEM_ID
                     , DOM_EXP
                     , FCST_TYPE
                     , INCOTERMS
                     , MEASURE
                     , PLANT_SITE_ID
                     , YYYYMMDD
                     , CURRENCY
                     , QTY
                     , CREATED_BY
                     , CREATION_DATE
                     , LAST_UPDATED_BY
                     , LAST_UPDATE_DATE
                     , ATTRIBUTE1
                     , ATTRIBUTE2
                     , ATTRIBUTE3
                     , ATTRIBUTE4
                     , ATTRIBUTE5
                     , ATTRIBUTE6
                     , ATTRIBUTE7
                     , ATTRIBUTE8
                     , ATTRIBUTE9
                     , ATTRIBUTE10
                     , COMPANY_ID
                     , SOLDTO_CUST_REPORT
                     , OWNER_NAME
                     , CUST_GROUP_DTL
                     , PRODUCT_DETAILS
                     , FORECAST_INFO_SPEC
                     , NICK_NAME
                     , FORECAST_INFO_CELL_MODEL
                     , FORECAST_INFO_CELL_PACK_COUNT
                     , FORECAST_INFO_BIZ_TYPE
                     , COMPANY_NAME
                     , APPLICATION
                     , APPLICATION_GR
                     , COUNTRY_KR_NAME
                     , ROUTE
                     , CELL_PROD_SITE )   /* [E20240429-000397] Sales Report화면 Cell Prod Site 칼럼 추가 */
                SELECT DATA_TYPE
                     , DIVISION_ID
                     , VERSION_NO
                     , CUTOFF_TYPE
                     , CUTOFF_YYYYMMDD
                     , DEPARTMENT_ID
                     , DEPARTMENT_NAME
                     , DEPT_ID
                     , DEPT_NAME
                     , END_CUST_REPORT
                     , CUST_REPORT
                     , PRODUCT_GROUP
                     , PROJECT_CODE
                     , SCM_SITE_ID
                     , ITEM_ID
                     , DOM_EXP
                     , FCST_TYPE
                     , INCOTERMS
                     , MEASURE
                     , PLANT_SITE_ID
                     , YYYYMMDD
                     , CURRENCY
                     , QTY
                     , CREATED_BY
                     , CREATION_DATE
                     , LAST_UPDATED_BY
                     , LAST_UPDATE_DATE
                     , ATTRIBUTE1
                     , ATTRIBUTE2
                     , ATTRIBUTE3
                     , ATTRIBUTE4
                     , ATTRIBUTE5
                     , ATTRIBUTE6
                     , ATTRIBUTE7
                     , ATTRIBUTE8
                     , ATTRIBUTE9
                     , ATTRIBUTE10
                     , COMPANY_ID
                     , SOLDTO_CUST_REPORT
                     , OWNER_NAME
                     , CUST_GROUP_DTL
                     , PRODUCT_DETAILS
                     , FORECAST_INFO_SPEC
                     , NICK_NAME
                     , FORECAST_INFO_CELL_MODEL
                     , FORECAST_INFO_CELL_PACK_COUNT
                     , FORECAST_INFO_BIZ_TYPE
                     , COMPANY_NAME
                     , APPLICATION
                     , APPLICATION_GR
                     , COUNTRY_KR_NAME
                     , ROUTE
                     , CELL_PROD_SITE     /* [E20240429-000397] Sales Report화면 Cell Prod Site 칼럼 추가 */
                  FROM DM_PLN_SALES_PLAN_REPORT_C
                 WHERE DIVISION_ID = V_DIVISION_ID
                   AND VERSION_NO  = V_VERSION_NO;

                SELECT COUNT(*)
                  INTO V_MOVE_CNT
                  FROM DM_PLN_SALES_PLAN_REPORT_C_KEEP
                 WHERE DIVISION_ID = V_DIVISION_ID
                   AND VERSION_NO  = V_VERSION_NO;

                IF ( V_MOVE_CNT = V_DATA_CNT ) THEN
                    DELETE
                      FROM DM_PLN_SALES_PLAN_REPORT_C A
                     WHERE A.VERSION_NO  = V_VERSION_NO
                       AND A.DIVISION_ID = V_DIVISION_ID
                       AND EXISTS ( SELECT 1
                                      FROM DM_PLN_SALES_PLAN_REPORT_C_KEEP B
                                     WHERE A.DIVISION_ID   = B.DIVISION_ID
                                       AND A.VERSION_NO    = B.VERSION_NO
                                       AND A.DEPARTMENT_ID = B.DEPARTMENT_ID
                                       AND A.DEPT_ID       = B.DEPT_ID
                                       AND A.PROJECT_CODE  = B.PROJECT_CODE
                                       AND A.SCM_SITE_ID   = B.SCM_SITE_ID
                                       AND A.ITEM_ID       = B.ITEM_ID
                                       AND A.FCST_TYPE     = B.FCST_TYPE
                                       AND A.INCOTERMS     = B.INCOTERMS
                                       AND A.MEASURE       = B.MEASURE
                                       AND A.PLANT_SITE_ID = B.PLANT_SITE_ID
                                       AND A.YYYYMMDD      = B.YYYYMMDD
                                       AND A.CURRENCY      = B.CURRENCY
                                       AND A.COMPANY_ID    = B.COMPANY_ID
                                       AND A.COMPO_40      = B.COMPO_40 );
                END IF;

                UPDATE DM_MDF_VERSION
                   SET ATTRIBUTE3 = 'MOVE'
                     , ATTRIBUTE5 = TO_CHAR(SYSDATE, 'YYYYMMDD')  /* [C20220103-000581] 다빈치 DataLake 이력 기록 */
                 WHERE DIVISION_ID = V_DIVISION_ID
                   AND VERSION_NO  = V_VERSION_NO;

                V_WEEKDAY := MOD(TRUNC(SYSDATE) - TRUNC(SYSDATE, 'IW') + 1, 7) + 1;
                EXIT WHEN V_WEEKDAY NOT IN (1, 7);
            END LOOP;
        END IF;

        V_LOG_TYPE    := 'PROCESS';
        V_LOG_MESSAGE := '########## Process............##########';
        V_DESCRIPTION := 'DM_PLN_SALES_PLAN_REPORT_C 이동';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
        V_LOG_MESSAGE := NULL; /* <- 변수 재사용을 위하여 초기화해야함 */

        COMMIT;

    EXCEPTION
        WHEN OTHERS THEN
            ROLLBACK;
            /* ERROR LOG VALUE SAVE (원본 CATCH : ERROR_MESSAGE()/ERROR_LINE()) */
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := 'ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
            D_EVENT_DATE  := SYSDATE;
            /* [C20200909-000203] LOG 표준화 적용 */
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    END;


    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := NULL;
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

END PR_DM_CUTOFF_DATA_CLEANSING;

PROCEDURE           "PR_DM_DNM_BPMS_MAIL_SEND" 
/* ============================================================
 * Program ID   : PR_DM_DNM_BPMS_MAIL_SEND
 * Description  : BPMS에서 수신된 공급품목의 VALID 가 'N'으로 변경되면 Owner에게 메일 발송
 * Program History
 *------------------------------------------------------------
 * Date          In Charge      Description
 *------------------------------------------------------------
 * 2021.06.08    P.C.I          [C20210312-000399] BPMS -> GSCM I/F 시 VALID 'N'은 Sales Site Project Model 적용
 * 2026.07.06    ZIONEX         [PJ202650304]  NextSCM Migration
 * ============================================================ */
AS
/* ------------------------------------------------------------
 *   - PIVOT([1]..[7]) MNG주소 -> LISTAGG(SEGMENT1,';') ORDER BY DISPLAY_SEQ (RN<=7, 후행 ';' 유지)
 * ------------------------------------------------------------ */
    V_PROGRAM_NAME   VARCHAR2(150 CHAR) := 'PR_DM_DNM_BPMS_MAIL_SEND';
    V_LOG_TYPE       VARCHAR2(30 CHAR);
    N_LOG_COUNT      INTEGER := 0;
    V_LOG_MESSAGE    VARCHAR2(1000 CHAR);
    V_DESCRIPTION    VARCHAR2(500 CHAR);
    D_EVENT_DATE     DATE;
    V_CNT            INTEGER;
    V_MAIL_TITLE     VARCHAR2(100 CHAR);
    V_BODY_CONTENTS  VARCHAR2(4000 CHAR);
    V_HEAD_CONT      VARCHAR2(2000 CHAR);
    V_BODY_CONT      VARCHAR2(32767 CHAR);
    V_TABLE_BODY     VARCHAR2(32767 CHAR);
    V_LIKE_STRING    VARCHAR2(100 CHAR);
    /* ------------------------------------------------------------
     * 본문 동일 수신자 묶음 (2026-09-22) — 같은 내용을 개별 발송하던 것을
     * 수신인을 ';' 로 이어 한 통으로 보내기 위한 작업용 선언
     * ------------------------------------------------------------ */
    C_TO_MAIL_MAX    CONSTANT PLS_INTEGER := 4000;   /* PKG_SEND_MAIL.P_SEND_MAIL 의 V_TO_MAIL VARCHAR2(4000) */
    TYPE T_GRP_REC IS RECORD ( OWNER_TYPE VARCHAR2(3 CHAR)
                             , BODY_CONT  VARCHAR2(32767 CHAR)
                             , ADDR_LIST  VARCHAR2(4000 CHAR) );
    TYPE T_GRP_TAB IS TABLE OF T_GRP_REC INDEX BY VARCHAR2(200 CHAR);
    V_GROUP          T_GRP_TAB;
    V_GRP_REC        T_GRP_REC;
    V_GRP_KEY        VARCHAR2(200 CHAR);
    V_SLOT_KEY       VARCHAR2(200 CHAR);
    V_GRP_IDX        VARCHAR2(200 CHAR);
    V_SLOT           PLS_INTEGER;
BEGIN
    /* 시작 LOG */
    V_LOG_TYPE := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := NULL;
    D_EVENT_DATE := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    BEGIN
        DELETE
          FROM GT_BPMS_MAIN;

        DELETE
          FROM GT_BPMS_ADDR;


        INSERT
          INTO GT_BPMS_MAIN
             ( DEPT_NAME_KO
             , END_CUSTOMER
             , SCM_SITE_ID
             , PROJECT_CODE
             , PROJECT_NAME
             , ITEM_ID
             , OWNER )
        SELECT D.DEPT_NAME_KO
             , NVL(E.SEGMENT3, C.END_CUSTOMER)
             , A.SCM_SITE_ID
             , A.PROJECT_CODE
             , F.PROJECT_NAME
             , A.ITEM_ID
             , A.OWNER
          FROM ( SELECT DIVISION_ID
                      , SCM_SITE_ID
                      , PROJECT_CODE
                      , ITEM_ID
                      , OWNER
                      , DEPT_ID                                            -- 2026.09.03 AJS
                   FROM SCM_MST_SITE_ITEM
                  WHERE LAST_UPDATED_BY = 'SYSTEM_BATCH_BOM_VALID_N'
                    AND VALID_YN = 'N' ) A
             , SCM_MST_SITE                 C
             , SCM_MST_SSO_DEPT_INFO        D
             , SCM_ADM_LOOKUP_MASTER_DETAIL E
             , SCM_MST_PROJECT              F
         WHERE A.DIVISION_ID  = C.DIVISION_ID(+)
           AND A.SCM_SITE_ID  = C.SCM_SITE_ID(+)
--           AND C.DEPT_ID      = D.DEPT_ID(+)
           AND A.DEPT_ID      = D.DEPT_ID(+)                                -- 2026.09.03 AJS
           AND C.DIVISION_ID  = E.SEGMENT1(+)
           AND C.END_CUSTOMER = E.SEGMENT2(+)
           AND E.LOOKUP_TYPE(+) = 'END_CUSTOMER'
           AND A.DIVISION_ID  = F.DIVISION_ID(+)
           AND A.PROJECT_CODE = F.PROJECT_CODE(+)
         GROUP BY D.DEPT_NAME_KO
                , NVL(E.SEGMENT3, C.END_CUSTOMER)
                , A.SCM_SITE_ID
                , A.PROJECT_CODE
                , F.PROJECT_NAME
                , A.ITEM_ID
                , A.OWNER;

        SELECT COUNT(*)
          INTO V_CNT
          FROM GT_BPMS_MAIN;

        IF V_CNT > 0 THEN
            /* GEN 주소 : OWNER 콤마분할 + @LGENSOL.COM */
            INSERT
              INTO GT_BPMS_ADDR
                 ( ADDR
                 , OWNER_TYPE )
            SELECT DISTINCT B.COLUMN_VALUE || '@LGENSOL.COM'
                 , 'GEN'
              FROM GT_BPMS_MAIN                      A
                 , TABLE(STRING_SPLIT(A.OWNER, ',')) B
             WHERE B.COLUMN_VALUE IS NOT NULL;


            INSERT
              INTO GT_BPMS_ADDR
                 ( ADDR
                 , OWNER_TYPE )
            SELECT LISTAGG(SEGMENT1, ';') WITHIN GROUP (ORDER BY DISPLAY_SEQ) || ';'
                 , 'MNG'
              FROM ( SELECT SEGMENT1
                          , DISPLAY_SEQ
                          , ROW_NUMBER() OVER (ORDER BY DISPLAY_SEQ) AS RN
                       FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                      WHERE LOOKUP_TYPE = 'DM_BPMS_MAIL_ADDR'
                        AND VALID_YN = 'Y' )
             WHERE RN <= 7;

            /* [2026-10-07] 비운영에서는 제목에 'DEV Oracle 개발서버 ' 를 붙인다 (사용자 결정 가).
             * 원본 MSSQL 은 이 건을 SCM_ADM_MAIL_SEND(행 17) 경유로 보내고 Oracle 행 17 에 같은 분기가 있는데,
             * Oracle 은 PKG_SEND_MAIL 을 직접 불러(계보 평탄화) 그 표시가 빠졌다.
             * 발송 동작은 원본 그대로 두고 식별만 되살린다 — 행 10·17 과 같은 판정식이다. */
            IF SYS_CONTEXT('USERENV', 'DB_NAME') NOT LIKE 'OCGSCMP%' THEN
                V_MAIL_TITLE := 'DEV Oracle 개발서버 '||'BPMS 공급품목 Active = N 리스트 안내';
            ELSE
                V_MAIL_TITLE := 'BPMS 공급품목 Active = N 리스트 안내';
            END IF;
            V_BODY_CONTENTS := '안녕하십니까? </br> ' || TO_CHAR(SYSDATE, 'YYYY-MM-DD HH24:MI:SS')
                || ' BPMS 공급품목에서 삭제 되어, Sales Site Project Model에서 아래 모델은 Active = N으로 변경되었습니다.</BR></BR>';
            V_HEAD_CONT := '<TR>'
                || '<TH rowspan="1">팀</TH><TH rowspan="1">고객명</TH><TH rowspan="1">Sales Site</TH>'
                || '<TH rowspan="1">Project Code</TH><TH rowspan="1">프로젝트명</TH><TH rowspan="1">Model</TH><TH rowspan="1">담당자</TH>'
                || '</TR>';


            FOR A IN (SELECT ADDR, OWNER_TYPE FROM GT_BPMS_ADDR) LOOP
                V_LIKE_STRING := CASE WHEN INSTR(A.ADDR, '@') > 0 THEN SUBSTR(A.ADDR, 1, INSTR(A.ADDR, '@') - 1) ELSE A.ADDR END;
                V_BODY_CONT := NULL;


                FOR R IN ( SELECT DEPT_NAME_KO
                                , END_CUSTOMER
                                , SCM_SITE_ID
                                , PROJECT_CODE
                                , PROJECT_NAME
                                , ITEM_ID
                                , OWNER
                             FROM GT_BPMS_MAIN
                            WHERE OWNER LIKE '%' || CASE WHEN A.OWNER_TYPE = 'GEN' THEN V_LIKE_STRING END || '%' ) LOOP
                    V_BODY_CONT := V_BODY_CONT
                        || '<TR>'
                        || '<TD>' || R.DEPT_NAME_KO || '</TD>'
                        || '<TD>' || R.END_CUSTOMER || '</TD>'
                        || '<TD>' || R.SCM_SITE_ID  || '</TD>'
                        || '<TD>' || R.PROJECT_CODE || '</TD>'
                        || '<TD>' || R.PROJECT_NAME || '</TD>'
                        || '<TD>' || R.ITEM_ID      || '</TD>'
                        || '<TD>' || R.OWNER        || '</TD>'
                        || '</TR>';
                END LOOP;

                /* ------------------------------------------------------------
                 * 「발송구분 + 본문」이 같은 수신자를 한 묶음으로 모은다.
                 *   - 해시는 묶음 후보를 빨리 찾기 위한 것이고, 합칠지는 본문 전문 비교로 확정한다
                 *     (해시가 충돌해 다른 본문이 한 통에 섞이면 잘못된 내용이 나가기 때문)
                 *   - 수신인 목록이 상한을 넘으면 같은 본문으로 묶음을 하나 더 만든다(절단 방지)
                 *   - GEN 과 MNG 은 키에 발송구분을 넣어 섞이지 않게 한다
                 * ------------------------------------------------------------ */
                V_GRP_KEY := A.OWNER_TYPE || '|'
                          || TO_CHAR(DBMS_UTILITY.GET_HASH_VALUE(NVL(V_BODY_CONT, ' '), 0, 1073741824));
                V_SLOT := 1;

                LOOP
                    V_SLOT_KEY := V_GRP_KEY || '|' || TO_CHAR(V_SLOT);

                    IF NOT V_GROUP.EXISTS(V_SLOT_KEY) THEN
                        V_GRP_REC.OWNER_TYPE := A.OWNER_TYPE;
                        V_GRP_REC.BODY_CONT  := V_BODY_CONT;
                        V_GRP_REC.ADDR_LIST  := A.ADDR;
                        V_GROUP(V_SLOT_KEY)  := V_GRP_REC;
                        EXIT;
                    END IF;

                    IF ( V_GROUP(V_SLOT_KEY).BODY_CONT = V_BODY_CONT
                         OR (V_GROUP(V_SLOT_KEY).BODY_CONT IS NULL AND V_BODY_CONT IS NULL) )
                       AND LENGTHB(V_GROUP(V_SLOT_KEY).ADDR_LIST || ';' || A.ADDR) <= C_TO_MAIL_MAX THEN
                        V_GROUP(V_SLOT_KEY).ADDR_LIST := V_GROUP(V_SLOT_KEY).ADDR_LIST || ';' || A.ADDR;
                        EXIT;
                    END IF;

                    V_SLOT := V_SLOT + 1;
                END LOOP;
            END LOOP;


            /* 묶음마다 한 통만 발송한다 (수신인 = ';' 로 연결) */
            V_GRP_IDX := V_GROUP.FIRST;

            WHILE V_GRP_IDX IS NOT NULL LOOP
                V_BODY_CONT := V_GROUP(V_GRP_IDX).BODY_CONT;

                V_TABLE_BODY := '<html><head><title>Untitled Document</title><style>'
                    || '* {margin:0;padding:0;} body {font-family:Malgun Gothic, Arial, Helvetica, sans-serif;font-size:12px;line-height:1.8;color:#333333;}'
                    || ' table {border-collapse:collapse;width:100%;} table th {background:#f5f5f5;border-bottom:1px solid #e1e1e1;}'
                    || ' table td {background:#fff;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1;border-bottom:1px solid #e1e1e1;}'
                    /* [2026-10-06] 원본 MSSQL 의 <style> 규칙 5개가 변환 시 빠져 있었다(MSSQL 11개 ↔ Oracle 6개).
                     * 교차수행에서 본문이 629자 차이로 드러났다. 원본 순서대로 복원한다(원본 충실).
                     * 실제 렌더에 효과가 나는 것은 `table tbody td`(본문 TD 7칸의 패딩·글자크기)이고
                     * 나머지는 본문에 해당 요소·클래스가 없어 효과가 없으나 원본과 1:1 로 맞춘다. */
                    || ' table tbody th {border-left:1px solid #e1e1e1;text-align:right;padding:6px 8px;font-size:12px}'
                    || ' table tbody td {padding:6px 8px;font-size:12px}'
                    || ' table thead th {text-align:center;padding:3px;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1; border-bottom:1px solid #d1d1d1;font-size:12px}'
                    || ' .hori-table table thead td {text-align:center;padding:3px;}'
                    || ' .hori-table table tbody td {text-align:center;padding:3px;}'
                    || ' .vertical-table, .hori-table {margin-bottom:20px;}'
                    || '</style></head><body></br><b>' || REPLACE(V_BODY_CONTENTS, CHR(10), '<br>') || '</b>'
                    || '<div id="divBody" style="width: 100%; overflow-x: auto; overflow-y: auto; font-size: 9pt; line-break: auto;">'
                    || '<table style=''border-top:2px solid #c8294b; width:1450px;''><thead>' || V_HEAD_CONT || '</thead>'
                    || '<tbody>' || V_BODY_CONT || '</tbody></div></body></html>';


                PKG_SEND_MAIL.P_SEND_MAIL(V_GROUP(V_GRP_IDX).ADDR_LIST, V_MAIL_TITLE, V_TABLE_BODY, 'Y');


                /* ★로그 컬럼 SEGMENT4 는 VARCHAR2(100 CHAR) 다 — 본문을 그대로 넘기면
                 * ORA-12899 가 나고, 공용 로그가 END 에서 RAISE_APPLICATION_ERROR(-20001) 로
                 * 재발생시켜 이 발송 루프가 중단된다(2026-09-22 실측 4통중 1통).
                 * MSSQL 은 파라미터 NVARCHAR(150) 에서 잘려 실패가 CATCH 에 흡수됐다.
                 * 여기서 잘라 넘긴다(사용자 결정 2026-09-22). */
                SCM_ADM_SAVE_MAIL_SEND_BATCH_LOG('MAIL', 0, V_PROGRAM_NAME, V_GROUP(V_GRP_IDX).OWNER_TYPE, V_MAIL_TITLE, SUBSTR(V_TABLE_BODY, 1, 100)
                                               , NULL, NULL, NULL, NULL, NULL, NULL, NULL, V_GROUP(V_GRP_IDX).ADDR_LIST);

                V_GRP_IDX := V_GROUP.NEXT(V_GRP_IDX);
            END LOOP;


            UPDATE
                   SCM_MST_SITE_ITEM
               SET LAST_UPDATED_BY  = 'SYSTEM_BATCH_BOM'
                 , LAST_UPDATE_DATE = SYSDATE
             WHERE LAST_UPDATED_BY = 'SYSTEM_BATCH_BOM_VALID_N'
               AND VALID_YN = 'N';
        END IF;

        COMMIT;

    EXCEPTION
        WHEN OTHERS THEN
            V_LOG_TYPE := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := 'ERROR_CODE : ' || TO_CHAR(SQLCODE);
            D_EVENT_DATE := SYSDATE;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    END;

    /* 종료 LOG */
    V_LOG_TYPE := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := NULL;
    D_EVENT_DATE := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
END;

PROCEDURE           "PR_DM_DNM_CREATE_C_WS_RTF" 
(
      P_DIVISION_ID   IN  VARCHAR2
    , P_VERSION_NO    IN  VARCHAR2
)
/* ==============================================================================================================================================
 * PROGRAM ID   : PR_DM_DNM_CREATE_C_WS_RTF
 * DESCRIPTION  : W/S 의 Sales Site 의 RTF 를 생성 ( Shipment Plan 참조 )
 * PROGRAM HISTORY
 *==============================================================================================================================================
 *   DATE       IN CHARGE      DESCRIPTION
 *==============================================================================================================================================
 * 2021.11.09   hwi1993     [PJ20209643]    INITIAL RELEASE
 * 2021.11.16   HWI1993     룩업에 VALID 조건 추가
 * 2022.01.06   hwi1993     기존 데이터 삭제시 created_by 대신 last_updated_by로 변경
 * 2022.04.05   HWI1993     GM JV 작업
 * 2022.04.12   Hwi1993     확정구간의 ETA 와 미확정구간의 RTF 가 겹쳐서 발생하는 오류 수정
 * 2022.08.30   HWI1993     AS INV PK 오류 수정 ( DISTINCT 추가 )
 * 2022.11.04   HWI1993     [C20220916-000290] [SCM PI] DM 시스템의 AS RTF 정확도 향상을 위한 기능변경 건
 * 2022.11.22   HWI1993     [C20220916-000290] 오류 수정 재배포
 * 2024.02.19   JSSBAE      [E20240214-000835]_[영업마케팅 PI팀] 81번사업부 AS Inv 생성 로직 변경 요청
 * 2024.03.15   JSSBAE      [E20240226-000021]_52주구간 AS INV VIEW 확보
 * 2024.09.26   JSSBAE      [E20240926-001366]_[공급 SCM PI팀] AS 관련 메저 생성 시 SCPSSP RTF간 우선순위 지정(SCP RTF 우선시)
 *                          PR_DM_PLN_MKT_FCST_C_QTY_BALANCE_CREATE에서 기 생성된 RTF_SCP와 SSP_RTF가 겹치는 현상이 발생하여 수정
 * 2024.10.21   JSSBAE      [E20241007-000267]_[공급 SCM PI팀] AS 관련 메저 생성 시 SSP 기존 로직 제거
 *                          81, 81_JV들만 제거하고 다른 사업부는 현행과 동일하게 유지한다.
 * 2024.12.01   KANG_H.J    [PJ2024-50611] BPS 매출(RTF_SYS_RP Measrue) 전송 시 전 사업부 FROM_SITE_ID 추가
 * 2025.01.13   P.C.I       [E20250113-000270]_[공급/생산 SCM PI팀] 운송중 재고 AS RTF 산출시 적용 요청
 * 2025.01.31   JSSBAE      [E20250120-000036]_[공급/생산 SCM PI팀] AS Inv -> RTF 생성로직 개선 (재고 기반 RTF 산출)
 * 2025.02.05   KANG.H.J    [PJ2025-50017] 소형 매출계획 동기화 개선 - DM_PLN_CFM_MKT_DEMAND_PLAN 동기화
 * 2025.04.08   KANG.H.J    [PJ2025-50017] 소형 매출계획 동기화 개선 - DM_PLN_RTF_ALLOCATION 삭제처리
 * 2025.09.09   JSSBAE      [E20250909-000795]_Kangoo 모델 AS INV REQ 값 이상[RTF 미산출)
 * 2026.02.12   JSSBAE      [E20260212-001318]_MKT FCST Waterfall - RTF 조회 불가 현상
 * 2026.03.27   JSSBAE      [E20260327-001732]_[긴급] MKT FCST Watefall cut-off(자동차)_AS 물동 관련 오류 수정
 * 2026.05.26   JSSBAE      [E20260402-001736]_AS 관련 기능 개선 건
 * 2026.09.18   AJS         40·82 PLANT_SITE_ID, 81·82 END_CUSTOMER 빈값 채움값 ' '·'' → '-' 통일(14자리)
 *==============================================================================================================================================
 *   USAGE : EXEC PR_DM_DNM_CREATE_C_WS_RTF '82'
 *----------------------------------------------------------------------------------------------------------------------------------------------
 *     - ATTRIBUTE10 <> '' -> IS NOT NULL, V_INV_QTY 는 원본 INT(정수절단) -> TRUNC 적용
 *============================================================================================================================================== */
IS

    V_PROGRAM_NAME        VARCHAR2(150 CHAR) := 'PR_DM_DNM_CREATE_C_WS_RTF';
    V_LOG_TYPE            VARCHAR2(30 CHAR);
    N_LOG_COUNT           NUMBER := 0;
    V_LOG_MESSAGE         VARCHAR2(1000 CHAR);
    V_DESCRIPTION         VARCHAR2(500 CHAR);
    D_EVENT_DATE          DATE;
    N_DELETE_COUNT        NUMBER := 0;
    N_INSERT_COUNT        NUMBER := 0;
    V_CREATED_BY          VARCHAR2(150 CHAR) := 'SYSTEM_WS';

    V_START_YYYYMMDD      VARCHAR2(8 CHAR);
    V_SHIP_START_YYYYMMDD VARCHAR2(8 CHAR);
    V_CUTOFF_TYPE         VARCHAR2(50 CHAR);
    V_CUTOFF_YYYYMMDD     VARCHAR2(8 CHAR);


    I                     NUMBER;
    CNT                   NUMBER;
    SUB_I                 NUMBER;
    SUB_CNT               NUMBER;
    V_ALLOC_I             NUMBER;
    V_ALLOC_CNT           NUMBER;
    V_YYYYMMDD            VARCHAR2(8 CHAR);
    V_INV                 NUMBER(20,10);
    V_RTF                 NUMBER(20,10);
    V_SSP_RTF             NUMBER(20,10);
    V_MKT_FCST            NUMBER(20,10);
    V_MKT_FCST_NET        NUMBER(20,10);
    V_SCM_SITE_ID         VARCHAR2(30 CHAR);
    V_PROJECT_CODE        VARCHAR2(50 CHAR);
    V_ITEM_ID             VARCHAR2(50 CHAR);
    V_ALLOC_SUM_RTF       NUMBER(20,10);
    V_ALLOC_RTF           NUMBER(20,10);

    I_SUB                 NUMBER;
    CNT_SUB               NUMBER;
    V_DIVISION_ID         VARCHAR2(30 CHAR);
    V_DOM_EXP             VARCHAR2(3 CHAR);
    V_FCST_TYPE           VARCHAR2(20 CHAR);
    V_INCOTERMS           VARCHAR2(10 CHAR);
    V_PLANT_SITE_ID       VARCHAR2(30 CHAR);
    V_INV_QTY             NUMBER;

    V_SITE_SEQ            NUMBER;
    V_DATE                VARCHAR2(8 CHAR);
    V_MAX_DATE            VARCHAR2(8 CHAR);
    V_FROM_SITE           VARCHAR2(30 CHAR);
    V_FROM_PLANT          VARCHAR2(30 CHAR);

    V_SUM_REQ_QTY         NUMBER(30,10);
    V_REQ_QTY             NUMBER(30,10);
    V_REM_QTY             NUMBER(30,10);
    I_RCV                 NUMBER;
    CNT_RCV               NUMBER;
    V_INV_ADJ_QTY         NUMBER(30,10);
    V_KEY_VAL             NUMBER;

BEGIN

    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## START OF PROCEDURE ##########';
    V_DESCRIPTION := '@P_DIVISION_ID: ' || P_DIVISION_ID || ' / @P_VERSION_NO: ' || P_VERSION_NO;
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    V_LOG_MESSAGE := NULL;

    BEGIN

        /* 당주 월요일 */
        V_START_YYYYMMDD := TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7, 'YYYYMMDD');

        BEGIN
            SELECT VERSION_TYPE
                 , YYYYMMDD
              INTO V_CUTOFF_TYPE
                 , V_CUTOFF_YYYYMMDD
              FROM DM_MST_VERSION A
             WHERE A.DIVISION_ID = P_DIVISION_ID
               AND A.VERSION_NO  = P_VERSION_NO;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN NULL;
        END;

        V_SHIP_START_YYYYMMDD := TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7, 'YYYYMMDD');

        /* --------------------------------------------------------------------------------------- */

        /* --------------------------------------------------------------------------------------- */
        DELETE FROM GT_PRDM_SSP;
        DELETE FROM GT_PRDM_END_RTF_RAW;
        DELETE FROM GT_PRDM_AS_INV;
        DELETE FROM GT_PRDM_END_RTF_LOOP;
        DELETE FROM GT_PRDM_AS_LOOP;
        DELETE FROM GT_PRDM_RTF;
        DELETE FROM GT_PRDM_RCV;
        DELETE FROM GT_PRDM_RTF_SITE;

        /* --------------------------------------------------------------------------------------- */
        /* 1. 기존 RTF 계열 삭제 ( 고객향 / AS Plant향 ) */
        /* --------------------------------------------------------------------------------------- */
        /* 고객향 */
        DELETE FROM DM_PLN_MKT_FCST_C A
         WHERE A.DIVISION_ID     = P_DIVISION_ID
           AND A.VERSION_NO      = P_VERSION_NO
           AND A.LAST_UPDATED_BY = V_CREATED_BY
           AND A.YYYYMMDD       >= V_START_YYYYMMDD
           AND A.MEASURE IN ('RTF_SYS_RP', 'RTF_SCP', 'RTF', 'AS_SHIP_PLAN', 'RTF_PR');

        /* AS Plant향 */
        DELETE FROM DM_PLN_MKT_FCST_C A
         WHERE EXISTS ( SELECT 1
                          FROM SCM_MST_SITE B
                         WHERE A.DIVISION_ID     = B.DIVISION_ID
                           AND A.SCM_SITE_ID     = B.SCM_SITE_ID
                           AND B.OPERATION_GROUP = 'W'
                           AND B.SITE_TYPE       = 'SALES' )
           AND A.DIVISION_ID     = P_DIVISION_ID
           AND A.VERSION_NO      = P_VERSION_NO
           AND A.LAST_UPDATED_BY = V_CREATED_BY
           AND A.YYYYMMDD       >= V_START_YYYYMMDD
           AND A.MEASURE IN ('RTF_SYS_RP', 'RTF_SCP', 'RTF', 'AS_SHIP_PLAN', 'RTF_PR');

        /* [PJ2025-50017] 소형 : 고객향 */
        DELETE FROM DM_PLN_CFM_MKT_DEMAND_PLAN_C A
         WHERE A.DIVISION_ID = P_DIVISION_ID
           AND A.VERSION_NO  = P_VERSION_NO
           AND A.CREATED_BY  = V_CREATED_BY
           AND A.YYYYMMDD   >= V_START_YYYYMMDD
           AND A.MEASURE IN ('RTF_SYS_RP', 'RTF_SCP', 'RTF', 'AS_SHIP_PLAN', 'RTF_PR');

        /* [PJ2025-50017] 소형 : AS Plant향 */
        DELETE FROM DM_PLN_CFM_MKT_DEMAND_PLAN_C A
         WHERE EXISTS ( SELECT 1
                          FROM SCM_MST_SITE B
                         WHERE A.DIVISION_ID     = B.DIVISION_ID
                           AND A.SCM_SITE_ID     = B.SCM_SITE_ID
                           AND B.OPERATION_GROUP = 'W'
                           AND B.SITE_TYPE       = 'SALES' )
           AND A.DIVISION_ID = P_DIVISION_ID
           AND A.VERSION_NO  = P_VERSION_NO
           AND A.CREATED_BY  = V_CREATED_BY
           AND A.YYYYMMDD   >= V_START_YYYYMMDD
           AND A.MEASURE IN ('RTF_SYS_RP', 'RTF_SCP', 'RTF', 'AS_SHIP_PLAN', 'RTF_PR');

        /* --------------------------------------------------------------------------------------- */

        /* --------------------------------------------------------------------------------------- */
        INSERT INTO GT_PRDM_SSP ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE
            , INCOTERMS, MEASURE, PLANT_SITE_ID, AS_SITE, ETA_YYYYMMDD, SHIP_YYYYMMDD, QTY, GUBUN, AS_FROM_PLANT )
        SELECT T0.DIVISION_ID
             , T0.PROJECT_CODE
             , T0.TO_SITE
             , T0.ITEM_ID
             , 'E'
             , T0.FCST_TYPE
             , T1.INCOTERMS
             , 'SSP_RTF'
             , CASE WHEN T0.DIVISION_ID LIKE '81%' THEN T0.FROM_SITE_PLANT_ID ELSE '' END
             , T3.SEGMENT1
             , T0.ETA_DATE
             , T0.YYYYMMDD
             , SUM(T0.QTY)
             , 'CONFIRM'
             , T3.SEGMENT2
          FROM SSP_ANL_SHIP_CONFIRM T0
          JOIN SCP_MST_BOD_N_V T1 ON T0.DIVISION_ID = T1.DIVISION_ID AND T0.BOD_ID = T1.BOD_ID
          JOIN SCP_MST_DISTRIBUTION_ROUTE T2 ON T2.ROUTE_ID = T1.ROUTE_ID
          JOIN SCM_ADM_LOOKUP_MASTER_DETAIL T3 ON T0.FROM_SITE = T3.SEGMENT2 AND T3.LOOKUP_TYPE = 'AS_SITE_PLANT' AND T3.SEGMENT2 <> '-' AND T3.SEGMENT3 = P_DIVISION_ID AND T3.VALID_YN = 'Y'
          JOIN SCM_MST_SITE T4 ON T0.TO_SITE = T4.SCM_SITE_ID AND T0.DIVISION_ID = T4.DIVISION_ID AND T4.SITE_TYPE = 'SALES'
          JOIN SCM_ADM_LOOKUP_MASTER_DETAIL T5 ON T0.FCST_TYPE = T5.SEGMENT1 AND T5.LOOKUP_TYPE = 'SALES_TYPE_CODE2' AND T5.VALID_YN = 'Y'
          JOIN SCM_MST_SITE T6 ON T0.FROM_SITE = T6.SCM_SITE_ID AND T0.DIVISION_ID = T6.DIVISION_ID
         WHERE 1 = 1
           AND ( T0.YYYYMMDD BETWEEN V_SHIP_START_YYYYMMDD AND CASE WHEN P_DIVISION_ID LIKE '81%' THEN V_SHIP_START_YYYYMMDD ELSE TO_CHAR(TO_DATE(V_SHIP_START_YYYYMMDD, 'YYYYMMDD') + T6.SHIP_FROZEN, 'YYYYMMDD') END
                 OR ( T0.YYYYMMDD < TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7, 'YYYYMMDD')
                      AND T0.ETA_DATE >= TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7, 'YYYYMMDD') )
               )
           AND T0.QTY <> 0
           AND T0.DIVISION_ID = P_DIVISION_ID
           AND T0.FCST_TYPE <> '-'
           AND T0.SHIPMENT_STATUS = 'C'
           AND T0.CHANGE_TYPE = 'C'
           AND T0.ETA_DATE IS NOT NULL
         GROUP BY T0.DIVISION_ID, T0.PROJECT_CODE, T0.TO_SITE, T0.ITEM_ID, T0.FCST_TYPE, T1.INCOTERMS
             , CASE WHEN T0.DIVISION_ID LIKE '81%' THEN T0.FROM_SITE_PLANT_ID ELSE '' END
             , T3.SEGMENT1, T0.ETA_DATE, T0.YYYYMMDD, T3.SEGMENT2;

        /* 소형 DOM_EXP 보정 1 ( YYYYMMDD 포함 ) */
        MERGE INTO GT_PRDM_SSP A
        USING ( SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.FCST_TYPE, A.INCOTERMS, A.YYYYMMDD
                     , MAX(A.DOM_EXP) AS DOM_EXP
                  FROM DM_PLN_MKT_FCST_C A
                 WHERE A.DIVISION_ID = P_DIVISION_ID
                   AND A.VERSION_NO  = P_VERSION_NO
                   AND A.YYYYMMDD BETWEEN V_START_YYYYMMDD AND TO_CHAR(ADD_MONTHS(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD'), 3), 'YYYYMMDD')
                   AND A.MEASURE IN ('RTF_SCP', 'MKT_FCST')
                 GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.FCST_TYPE, A.INCOTERMS, A.YYYYMMDD ) B
        ON (    B.DIVISION_ID  = A.DIVISION_ID
            AND B.PROJECT_CODE = A.PROJECT_CODE
            AND B.SCM_SITE_ID  = A.SCM_SITE_ID
            AND B.ITEM_ID      = A.ITEM_ID
            AND B.FCST_TYPE    = A.FCST_TYPE
            AND B.INCOTERMS    = A.INCOTERMS
            AND B.YYYYMMDD     = A.ETA_YYYYMMDD )
        WHEN MATCHED THEN UPDATE SET A.DOM_EXP = B.DOM_EXP;

        /* 동일 일자 값 없는 건 : YYYYMMDD 제외 재보정 ( DOM_EXP='E' 인 건만 ) */
        MERGE INTO GT_PRDM_SSP A
        USING ( SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.FCST_TYPE, A.INCOTERMS
                     , MAX(A.DOM_EXP) AS DOM_EXP
                  FROM DM_PLN_MKT_FCST_C A
                 WHERE A.DIVISION_ID = P_DIVISION_ID
                   AND A.VERSION_NO  = P_VERSION_NO
                   AND A.YYYYMMDD BETWEEN V_START_YYYYMMDD AND TO_CHAR(ADD_MONTHS(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD'), 3), 'YYYYMMDD')
                   AND A.MEASURE IN ('RTF_SCP', 'MKT_FCST')
                 GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.FCST_TYPE, A.INCOTERMS ) B
        ON (    B.DIVISION_ID  = A.DIVISION_ID
            AND B.PROJECT_CODE = A.PROJECT_CODE
            AND B.SCM_SITE_ID  = A.SCM_SITE_ID
            AND B.ITEM_ID      = A.ITEM_ID
            AND B.FCST_TYPE    = A.FCST_TYPE
            AND B.INCOTERMS    = A.INCOTERMS )
        WHEN MATCHED THEN UPDATE SET A.DOM_EXP = B.DOM_EXP WHERE A.DOM_EXP = 'E';

        /* --------------------------------------------------------------------------------------- */
        /* 고객향 RTF / MKT FCST -> GT_PRDM_END_RTF_RAW */
        /* [E20241007-000267] 81 사업부는 SSP RTF 미사용. 82/40 만 SSP 구간 생성. */
        /* --------------------------------------------------------------------------------------- */
        IF P_DIVISION_ID IN ('82', '40') THEN
            INSERT INTO GT_PRDM_END_RTF_RAW ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY, FROM_SITE, AS_PLANT )
            SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
                 -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (START)
--                 , A.FCST_TYPE, A.INCOTERMS, 'SSP_RTF', CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '' END, A.ETA_YYYYMMDD
                 , A.FCST_TYPE, A.INCOTERMS, 'SSP_RTF', CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '/' END, A.ETA_YYYYMMDD
                 -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (END)
                 , SUM(A.QTY)
                 , A.AS_SITE, A.AS_FROM_PLANT
              FROM GT_PRDM_SSP A
             GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
                 -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (START)
--                 , A.FCST_TYPE, A.INCOTERMS, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '' END, A.ETA_YYYYMMDD, A.AS_SITE, A.AS_FROM_PLANT;
                 , A.FCST_TYPE, A.INCOTERMS, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '/' END, A.ETA_YYYYMMDD, A.AS_SITE, A.AS_FROM_PLANT;
                 -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (END)
        END IF;

        /* 고객향 MKT FCST INSERT */
        INSERT INTO GT_PRDM_END_RTF_RAW ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY, MF_QTY, RTF_QTY, FROM_SITE, AS_PLANT )
        SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
             , A.FCST_TYPE, A.INCOTERMS, 'MKT_FCST', A.PLANT_SITE_ID, A.YYYYMMDD
             , SUM(A.QTY), SUM(A.QTY), 0, C.SEGMENT1, A.ATTRIBUTE10
          FROM DM_PLN_MKT_FCST_C A
          JOIN SCM_MST_SITE B ON A.DIVISION_ID = B.DIVISION_ID
                             AND A.ATTRIBUTE10 = B.SCM_SITE_ID
                             AND B.OPERATION_GROUP = 'W'
                             AND B.SITE_TYPE = 'PLANT'
          JOIN SCM_ADM_LOOKUP_MASTER_DETAIL C ON B.SCM_SITE_ID = C.SEGMENT2 AND B.DIVISION_ID = C.SEGMENT3 AND C.LOOKUP_TYPE = 'AS_SITE_PLANT'
         WHERE A.DIVISION_ID = P_DIVISION_ID
           AND A.VERSION_NO  = P_VERSION_NO
           AND A.MEASURE IN ('MKT_FCST')
           AND A.YYYYMMDD >= V_START_YYYYMMDD
           AND A.ATTRIBUTE10 IS NOT NULL  /* 원본 ATTRIBUTE10 <> '' */
         GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
             , A.FCST_TYPE, A.INCOTERMS, A.PLANT_SITE_ID, A.YYYYMMDD, A.ATTRIBUTE10, C.SEGMENT1
        HAVING SUM(A.QTY) <> 0;  /* [E20260327-001732] QTY 0 제외 */

        /* #RAW 에 LT 추가 */
        MERGE INTO GT_PRDM_END_RTF_RAW A
        USING ( SELECT FROM_SITE, TO_SITE, INCOTERMS, LT_TOTAL
                  FROM ( SELECT FROM_SITE, TO_SITE, INCOTERMS, LT_TOTAL
                              , ROW_NUMBER() OVER ( PARTITION BY FROM_SITE, TO_SITE, INCOTERMS ORDER BY PRIORITY ) AS PRT
                           FROM SCP_MST_BOD_V
                          WHERE DIVISION_ID = P_DIVISION_ID
                            AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN FROM_YYYYMMDD AND TO_YYYYMMDD )
                 WHERE PRT = 1 ) B
        ON ( A.AS_PLANT = B.FROM_SITE AND A.SCM_SITE_ID = B.TO_SITE AND A.INCOTERMS = B.INCOTERMS )
        WHEN MATCHED THEN UPDATE SET A.LT_DAYS = B.LT_TOTAL;

        /* SEQ ( DENSE_RANK by YYYYMMDD ) */
        MERGE INTO GT_PRDM_END_RTF_RAW A
        USING ( SELECT KEY_VAL
                     , DENSE_RANK() OVER ( PARTITION BY DIVISION_ID, SCM_SITE_ID, PROJECT_CODE, ITEM_ID ORDER BY YYYYMMDD ) AS SEQ
                  FROM GT_PRDM_END_RTF_RAW ) B
        ON ( A.KEY_VAL = B.KEY_VAL )
        WHEN MATCHED THEN UPDATE SET A.SEQ = B.SEQ;

        /* MF_SEQ ( MKT_FCST 한정 DENSE_RANK by YYYYMMDD,QTY ) */
        MERGE INTO GT_PRDM_END_RTF_RAW A
        USING ( SELECT KEY_VAL
                     , DENSE_RANK() OVER ( PARTITION BY DIVISION_ID, SCM_SITE_ID, PROJECT_CODE, ITEM_ID ORDER BY YYYYMMDD, QTY ) AS SEQ
                  FROM GT_PRDM_END_RTF_RAW
                 WHERE MEASURE = 'MKT_FCST' ) B
        ON ( A.KEY_VAL = B.KEY_VAL )
        WHEN MATCHED THEN UPDATE SET A.MF_SEQ = B.SEQ;

        /* --------------------------------------------------------------------------------------- */
        /* 고객향 SITE 재고 루프 ( SEQ 0부터 ROW_NUMBER 채번 ) */
        /* --------------------------------------------------------------------------------------- */
        INSERT INTO GT_PRDM_END_RTF_LOOP ( SCM_SITE_ID, PROJECT_CODE, ITEM_ID, SEQ )
        SELECT SCM_SITE_ID, PROJECT_CODE, ITEM_ID
             , ROW_NUMBER() OVER ( ORDER BY SCM_SITE_ID, PROJECT_CODE, ITEM_ID ) - 1
          FROM ( SELECT DISTINCT SCM_SITE_ID, PROJECT_CODE, ITEM_ID FROM GT_PRDM_END_RTF_RAW );

        SELECT 0, MAX(SEQ) INTO I, CNT FROM GT_PRDM_END_RTF_LOOP;
        V_SCM_SITE_ID  := NULL;
        V_PROJECT_CODE := NULL;
        V_ITEM_ID      := NULL;

        WHILE I <= CNT LOOP

            SELECT SCM_SITE_ID, PROJECT_CODE, ITEM_ID
              INTO V_SCM_SITE_ID, V_PROJECT_CODE, V_ITEM_ID
              FROM GT_PRDM_END_RTF_LOOP
             WHERE SEQ = I;

            SELECT 1, NVL(MAX(A.SEQ), 0), 0, 0, 0, 0, 0, NULL
              INTO SUB_I, SUB_CNT, V_INV, V_RTF, V_SSP_RTF, V_MKT_FCST, V_MKT_FCST_NET, V_YYYYMMDD
              FROM GT_PRDM_END_RTF_RAW A
             WHERE A.SCM_SITE_ID  = V_SCM_SITE_ID
               AND A.PROJECT_CODE = V_PROJECT_CODE
               AND A.ITEM_ID      = V_ITEM_ID
               AND A.MEASURE IN ('SSP_RTF', 'MKT_FCST');

            WHILE ( SUB_I <= SUB_CNT ) LOOP

                SELECT SUM(CASE WHEN A.MEASURE = 'SSP_RTF' THEN A.QTY ELSE 0 END)
                     , SUM(CASE WHEN A.MEASURE = 'MKT_FCST' THEN A.QTY ELSE 0 END)
                     , MAX(A.YYYYMMDD)
                  INTO V_SSP_RTF, V_MKT_FCST, V_YYYYMMDD
                  FROM GT_PRDM_END_RTF_RAW A
                 WHERE A.SCM_SITE_ID  = V_SCM_SITE_ID
                   AND A.PROJECT_CODE = V_PROJECT_CODE
                   AND A.ITEM_ID      = V_ITEM_ID
                   AND A.MEASURE IN ('SSP_RTF', 'MKT_FCST')
                   AND A.SEQ = SUB_I;

                /* 당일의 기초재고 및 요청총량 계산 */
                V_INV          := V_INV + NVL(V_SSP_RTF, 0);
                V_MKT_FCST_NET := V_MKT_FCST_NET + NVL(V_MKT_FCST, 0);

                IF V_INV >= V_MKT_FCST_NET THEN
                    V_INV          := V_INV - V_MKT_FCST_NET;
                    V_RTF          := V_MKT_FCST_NET;
                    V_MKT_FCST_NET := 0;
                ELSE
                    V_RTF          := V_INV;
                    V_MKT_FCST_NET := V_MKT_FCST_NET - V_INV;
                    V_INV          := 0;
                END IF;

                IF ( V_RTF > 0 ) THEN

                    SELECT 0, 0, MIN(A.SEQ)
                      INTO V_ALLOC_SUM_RTF, V_ALLOC_RTF, V_ALLOC_I
                      FROM GT_PRDM_END_RTF_RAW A
                     WHERE A.SCM_SITE_ID  = V_SCM_SITE_ID
                       AND A.PROJECT_CODE = V_PROJECT_CODE
                       AND A.ITEM_ID      = V_ITEM_ID
                       AND A.MEASURE IN ('MKT_FCST')
                       AND A.SEQ <= SUB_I
                       AND A.RTF_QTY < A.MF_QTY;

                    /* 하나씩 풀면서 V_RTF 숫자에 도달할때까지 넣어준다. */
                    WHILE ( V_ALLOC_SUM_RTF < V_RTF ) LOOP

                        V_ALLOC_RTF := 0;

                        BEGIN
                            SELECT CASE WHEN A.QTY - NVL(A.RTF_QTY, 0) < V_RTF - V_ALLOC_SUM_RTF THEN A.QTY - NVL(A.RTF_QTY, 0)
                                        ELSE V_RTF - V_ALLOC_SUM_RTF END
                              INTO V_ALLOC_RTF
                              FROM GT_PRDM_END_RTF_RAW A
                             WHERE A.SCM_SITE_ID  = V_SCM_SITE_ID
                               AND A.PROJECT_CODE = V_PROJECT_CODE
                               AND A.ITEM_ID      = V_ITEM_ID
                               AND A.MEASURE IN ('MKT_FCST')
                               AND A.SEQ = V_ALLOC_I
                               AND ROWNUM = 1;
                        EXCEPTION
                            WHEN NO_DATA_FOUND THEN EXIT;
                        END;

                        INSERT INTO GT_PRDM_END_RTF_RAW ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY, FROM_SITE, AS_PLANT )
                        SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, 'RTF', PLANT_SITE_ID, V_YYYYMMDD
                             , V_ALLOC_RTF, FROM_SITE, AS_PLANT
                          FROM GT_PRDM_END_RTF_RAW A
                         WHERE A.SCM_SITE_ID  = V_SCM_SITE_ID
                           AND A.PROJECT_CODE = V_PROJECT_CODE
                           AND A.ITEM_ID      = V_ITEM_ID
                           AND A.MEASURE IN ('MKT_FCST')
                           AND A.SEQ = V_ALLOC_I;

                        UPDATE GT_PRDM_END_RTF_RAW
                           SET RTF_QTY = NVL(RTF_QTY, 0) + V_ALLOC_RTF
                         WHERE SCM_SITE_ID  = V_SCM_SITE_ID
                           AND PROJECT_CODE = V_PROJECT_CODE
                           AND ITEM_ID      = V_ITEM_ID
                           AND MEASURE IN ('MKT_FCST')
                           AND SEQ = V_ALLOC_I;

                        V_ALLOC_SUM_RTF := V_ALLOC_SUM_RTF + V_ALLOC_RTF;
                        V_ALLOC_I       := V_ALLOC_I + 1;
                    END LOOP;

                END IF;

                SUB_I := SUB_I + 1;
            END LOOP;

            I := I + 1;
        END LOOP;

        /* --------------------------------------------------------------------------------------- */
        /* [E20240926-001366] SCP RTF 우선 : 겹치는 SSP RTF 제거 */
        /* --------------------------------------------------------------------------------------- */
        DELETE FROM GT_PRDM_END_RTF_RAW R
         WHERE EXISTS ( SELECT 1
                          FROM DM_PLN_MKT_FCST_C M
                         WHERE M.DIVISION_ID     = R.DIVISION_ID
                           AND M.VERSION_NO      = P_VERSION_NO
                           AND M.CUTOFF_TYPE     = V_CUTOFF_TYPE
                           AND M.CUTOFF_YYYYMMDD = V_CUTOFF_YYYYMMDD
                           AND M.PROJECT_CODE    = R.PROJECT_CODE
                           AND M.SCM_SITE_ID     = R.SCM_SITE_ID
                           AND M.ITEM_ID         = R.ITEM_ID
                           AND M.DOM_EXP         = R.DOM_EXP
                           AND M.FCST_TYPE       = R.FCST_TYPE
                           AND M.INCOTERMS       = R.INCOTERMS
                           AND M.PLANT_SITE_ID   = R.PLANT_SITE_ID
                           AND M.YYYYMMDD        = R.YYYYMMDD
                           AND M.MEASURE IN ('RTF', 'RTF_SCP', 'RTF_SYS_RP', 'RTF_PR') );

        /* --------------------------------------------------------------------------------------- */
        /* 계산된 RTF / 소형 동기화 INSERT ( 82, 40 ) */
        /* --------------------------------------------------------------------------------------- */
        IF P_DIVISION_ID IN ('82', '40') THEN

            INSERT INTO DM_PLN_MKT_FCST_C
                ( DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD
                , PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP
                , FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD
                , QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
                , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
            SELECT A.DIVISION_ID, P_VERSION_NO, V_CUTOFF_TYPE, V_CUTOFF_YYYYMMDD
                 , A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
                 , A.FCST_TYPE, A.INCOTERMS, B.MEASURE, A.PLANT_SITE_ID, A.YYYYMMDD
                 , SUM(A.QTY)
                 , V_CREATED_BY, SYSDATE, V_CREATED_BY, SYSDATE
                 , '', '', '', '', ''
                 , '', '', '', '', A.AS_PLANT
              FROM GT_PRDM_END_RTF_RAW A
              JOIN ( SELECT 'RTF' AS MEASURE FROM DUAL
                     UNION ALL SELECT 'RTF_SCP' FROM DUAL
                     UNION ALL SELECT 'RTF_SYS_RP' FROM DUAL
                     UNION ALL SELECT 'RTF_PR' FROM DUAL ) B ON 1 = 1
             WHERE A.MEASURE = 'RTF'
             GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
                 , A.FCST_TYPE, A.INCOTERMS, A.PLANT_SITE_ID, A.YYYYMMDD, B.MEASURE, A.AS_PLANT;

            /* [PJ2025-50017] 소형 동기화 */
            INSERT INTO DM_PLN_CFM_MKT_DEMAND_PLAN_C
                ( DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD
                , PROJECT_CODE, END_CUSTOMER
                , SCM_SITE_ID, ITEM_ID, DOM_EXP
                , FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID, YYYYMMDD
                , QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
                , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
            SELECT A.DIVISION_ID, P_VERSION_NO, V_CUTOFF_TYPE, V_CUTOFF_YYYYMMDD
                 , A.PROJECT_CODE
                 -- 2026.09.18 AJS END_CUSTOMER 빈값 채움값 '-' 로 통일 (START)
--                 , CASE WHEN A.DIVISION_ID = '40' THEN A.PROJECT_CODE ELSE ' ' END
                 , CASE WHEN A.DIVISION_ID = '40' THEN A.PROJECT_CODE ELSE '/' END
                 -- 2026.09.18 AJS END_CUSTOMER 빈값 채움값 '-' 로 통일 (END)
                 , A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
                 , A.FCST_TYPE, A.INCOTERMS, B.MEASURE, A.PLANT_SITE_ID, '-', A.YYYYMMDD
                 , SUM(A.QTY)
                 , V_CREATED_BY, SYSDATE, V_CREATED_BY, SYSDATE
                 , '', NULL, '', '', ''
                 , '', '', '', '', A.AS_PLANT
              FROM GT_PRDM_END_RTF_RAW A
              JOIN ( SELECT 'RTF' AS MEASURE FROM DUAL
                     UNION ALL SELECT 'RTF_SCP' FROM DUAL
                     UNION ALL SELECT 'RTF_SYS_RP' FROM DUAL
                     UNION ALL SELECT 'RTF_PR' FROM DUAL ) B ON 1 = 1
             WHERE A.MEASURE = 'RTF'
             GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
                 , A.FCST_TYPE, A.INCOTERMS, A.PLANT_SITE_ID, A.YYYYMMDD, B.MEASURE, A.AS_PLANT;

        END IF;

        /* --------------------------------------------------------------------------------------- */
        /* AS SITE( PLANT )에 SHIPMENT_PLAN 생성 ( 82, 40 ) */
        /* --------------------------------------------------------------------------------------- */
        IF P_DIVISION_ID IN ('82', '40') THEN

            INSERT INTO DM_PLN_MKT_FCST_C
                ( DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD
                , PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP
                , FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD
                , QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
                , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
            SELECT A.DIVISION_ID, P_VERSION_NO, V_CUTOFF_TYPE, V_CUTOFF_YYYYMMDD
                 , A.PROJECT_CODE, A.AS_SITE, A.ITEM_ID, MAX(A.DOM_EXP)
                 -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (START)
--                 , MAX(A.FCST_TYPE), MAX(A.INCOTERMS), 'AS_SHIP_PLAN', MAX(CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE ' ' END), A.SHIP_YYYYMMDD
                 , MAX(A.FCST_TYPE), MAX(A.INCOTERMS), 'AS_SHIP_PLAN', MAX(CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '/' END), A.SHIP_YYYYMMDD
                 -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (END)
                 , SUM(A.QTY), V_CREATED_BY, SYSDATE, V_CREATED_BY, SYSDATE
                 , '', '', '', '', ''
                 , '', '', '', '', ''
              FROM GT_PRDM_SSP A
             WHERE A.SHIP_YYYYMMDD >= V_START_YYYYMMDD
             GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.AS_SITE, A.ITEM_ID, A.SHIP_YYYYMMDD;

            /* [PJ2025-50017] 소형 동기화 */
            INSERT INTO DM_PLN_CFM_MKT_DEMAND_PLAN_C
                ( DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD
                , PROJECT_CODE, END_CUSTOMER
                , SCM_SITE_ID, ITEM_ID, DOM_EXP
                , FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID, YYYYMMDD
                , QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
                , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
            SELECT A.DIVISION_ID, P_VERSION_NO, V_CUTOFF_TYPE, V_CUTOFF_YYYYMMDD
                 , A.PROJECT_CODE
                 -- 2026.09.18 AJS END_CUSTOMER 빈값 채움값 '-' 로 통일 (START)
--                 , CASE WHEN A.DIVISION_ID = '40' THEN A.PROJECT_CODE ELSE ' ' END
                 , CASE WHEN A.DIVISION_ID = '40' THEN A.PROJECT_CODE ELSE '/' END
                 -- 2026.09.18 AJS END_CUSTOMER 빈값 채움값 '-' 로 통일 (END)
                 , A.AS_SITE, A.ITEM_ID, MAX(A.DOM_EXP)
                 -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (START)
--                 , MAX(A.FCST_TYPE), MAX(A.INCOTERMS), 'AS_SHIP_PLAN', MAX(CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE ' ' END), '-', A.SHIP_YYYYMMDD
                 , MAX(A.FCST_TYPE), MAX(A.INCOTERMS), 'AS_SHIP_PLAN', MAX(CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '/' END), '-', A.SHIP_YYYYMMDD
                 -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (END)
                 , SUM(A.QTY), V_CREATED_BY, SYSDATE, V_CREATED_BY, SYSDATE
                 , '', NULL, '', '', ''
                 , '', '', '', '', ''
              FROM GT_PRDM_SSP A
             WHERE A.SHIP_YYYYMMDD >= V_START_YYYYMMDD
             GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.AS_SITE, A.ITEM_ID, A.SHIP_YYYYMMDD;

        END IF;

        /* --------------------------------------------------------------------------------------- */
        /* AS SITE( PLANT )에서 SHIPMENT_PLAN 이용 AS_INV 재계산 -> GT_PRDM_AS_INV */
        /* --------------------------------------------------------------------------------------- */
        INSERT INTO GT_PRDM_AS_INV ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, YYYYMMDD, PLANT_SITE_ID, QTY )
        SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, A.MEASURE, A.YYYYMMDD, A.PLANT_SITE_ID, A.QTY
          FROM DM_PLN_MKT_FCST_C A
          JOIN SCM_MST_SITE B ON A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID AND B.OPERATION_GROUP = 'W' AND B.SITE_TYPE = 'SALES'
         WHERE A.DIVISION_ID = P_DIVISION_ID
           AND A.VERSION_NO  = P_VERSION_NO
           AND A.MEASURE IN ('AS_In_Plan', 'AS_SHIP_PLAN')
           AND A.YYYYMMDD >= V_START_YYYYMMDD;

        /* 기존 AS_INV 메저 보유행에 SITE_SEQ=1 */
        MERGE INTO GT_PRDM_AS_INV A
        USING ( SELECT DISTINCT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID
                  FROM DM_PLN_MKT_FCST_C
                 WHERE YYYYMMDD = TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD')
--                 AND MEASURE = 'AS_INV'   --  2026.10.08 AJS
                   AND MEASURE = 'AS_Inv'   --  2026.10.08 AJS
                   AND DIVISION_ID = P_DIVISION_ID
                   AND VERSION_NO  = P_VERSION_NO ) B
        ON (    A.DIVISION_ID   = B.DIVISION_ID
            AND A.PROJECT_CODE  = B.PROJECT_CODE
            AND A.SCM_SITE_ID   = B.SCM_SITE_ID
            AND A.ITEM_ID       = B.ITEM_ID
            AND A.DOM_EXP       = B.DOM_EXP
            AND A.FCST_TYPE     = B.FCST_TYPE
            AND A.INCOTERMS     = B.INCOTERMS
            AND A.PLANT_SITE_ID = B.PLANT_SITE_ID )
        WHEN MATCHED THEN UPDATE SET A.SITE_SEQ = 1;

        /* 한 SITE,ITEM 에 SITE_SEQ=1 여러개면 조정( NULL ) */
        MERGE INTO GT_PRDM_AS_INV A
        USING ( SELECT KEY_VAL
                  FROM ( SELECT KEY_VAL
                              , ROW_NUMBER() OVER ( PARTITION BY DIVISION_ID, SCM_SITE_ID, ITEM_ID ORDER BY KEY_VAL ) AS SUB_SEQ
                           FROM GT_PRDM_AS_INV
                          WHERE SITE_SEQ = 1 )
                 WHERE SUB_SEQ <> 1 ) B
        ON ( A.KEY_VAL = B.KEY_VAL )
        WHEN MATCHED THEN UPDATE SET A.SITE_SEQ = NULL;

        /* SITE_SEQ 없는 SITE 조정 */
        MERGE INTO GT_PRDM_AS_INV A
        USING ( SELECT C.KEY_VAL
                  FROM ( SELECT KEY_VAL, DIVISION_ID, SCM_SITE_ID, ITEM_ID
                              , ROW_NUMBER() OVER ( PARTITION BY DIVISION_ID, SCM_SITE_ID, ITEM_ID ORDER BY KEY_VAL DESC ) AS ROW_NUM
                           FROM GT_PRDM_AS_INV ) C
                  JOIN ( SELECT DIVISION_ID, SCM_SITE_ID, ITEM_ID, MIN(SITE_SEQ) AS SITE_SEQ
                           FROM GT_PRDM_AS_INV
                          GROUP BY DIVISION_ID, SCM_SITE_ID, ITEM_ID ) D
                    ON C.DIVISION_ID = D.DIVISION_ID AND C.SCM_SITE_ID = D.SCM_SITE_ID AND C.ITEM_ID = D.ITEM_ID
                 WHERE D.SITE_SEQ IS NULL
                   AND C.ROW_NUM = 1 ) B
        ON ( A.KEY_VAL = B.KEY_VAL )
        WHEN MATCHED THEN UPDATE SET A.SITE_SEQ = 1;

        /* --------------------------------------------------------------------------------------- */
        /* [E20240214-000835] 기초재고 추가 ( 81 / 그 외 분기 ) */
        /* --------------------------------------------------------------------------------------- */
        IF P_DIVISION_ID = '81' THEN

            /* 81 : AS_STORAGE_YN='Y' 인 행의 재고만 사용, MKT FCST 기준 데이터로 생성 */
            INSERT INTO GT_PRDM_AS_INV ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, YYYYMMDD, PLANT_SITE_ID, QTY, SITE_SEQ, AS_PLANT )
            SELECT B.DIVISION_ID, B.PROJECT_CODE, B.SCM_SITE_ID, B.ITEM_ID, B.DOM_EXP, B.FCST_TYPE, B.INCOTERMS, 'AS_Inv'
                 , TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD'), B.PLANT_SITE_ID
                 , SUM(A.QTY)
                 , B.SEQ
                 , A.AS_PLANT
              FROM ( SELECT A.DIVISION_ID, C.SEGMENT1 AS AS_SITE, A.ITEM_ID, SUM(SCM_QTY) AS QTY, C.SEGMENT2 AS AS_PLANT
                       FROM SSP_DNM_STOCK_C A
                       JOIN SCM_ADM_LOOKUP_MASTER_DETAIL B
                         ON B.SEGMENT1 = A.DIVISION_ID AND B.SEGMENT3 = A.PLANT_ID AND B.SEGMENT4 = A.STORAGE_ID
                        AND B.LOOKUP_TYPE = 'SSP_AS_DIV_SLOC' AND B.VALID_YN = 'Y' AND B.SEGMENT5 = 'Y'
                       JOIN SCM_ADM_LOOKUP_MASTER_DETAIL C ON B.SEGMENT1 = C.SEGMENT3 AND B.SEGMENT2 = C.SEGMENT2 AND C.LOOKUP_TYPE = 'AS_SITE_PLANT' AND C.VALID_YN = 'Y'
                      /* [E20260402-001736] SSP CUTOFF_DATE = 일요일(당주 월요일 -1). DATE 컬럼 = DATE 로 비교. */
                      WHERE A.CUTOFF_DATE = TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') - 1
                        AND A.STOCK_TYPE = 'INVENTORY'
                      GROUP BY A.DIVISION_ID, C.SEGMENT1, A.ITEM_ID, C.SEGMENT2
                     UNION ALL
                     /* [E20250113-000270] 운송중(INTRANSIT) 재고 적용 */
                     SELECT A.DIVISION_ID, C.SEGMENT1 AS AS_SITE, A.ITEM_ID, SUM(DELIVERY_QTY) AS QTY, C.SEGMENT2 AS AS_PLANT
                       FROM SCM_DNM_INTRANSIT_C A
                       JOIN SCM_ADM_LOOKUP_MASTER_DETAIL B
                         ON B.SEGMENT1 = A.DIVISION_ID AND B.SEGMENT3 = A.PLANT_ID AND B.SEGMENT4 = A.ATTRIBUTE2
                        AND B.LOOKUP_TYPE = 'SSP_AS_DIV_SLOC' AND B.VALID_YN = 'Y' AND B.SEGMENT5 = 'Y'
                       JOIN SCM_ADM_LOOKUP_MASTER_DETAIL C ON B.SEGMENT1 = C.SEGMENT3 AND B.SEGMENT2 = C.SEGMENT2 AND C.LOOKUP_TYPE = 'AS_SITE_PLANT' AND C.VALID_YN = 'Y'
                      WHERE A.RESULT_DATE = TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD')
                        AND A.RESULT_TYPE = 'I'
                      GROUP BY A.DIVISION_ID, C.SEGMENT1, A.ITEM_ID, C.SEGMENT2 ) A
              JOIN ( SELECT DISTINCT B.DIVISION_ID, B.PROJECT_CODE, B.FROM_SITE AS SCM_SITE_ID, B.ITEM_ID, B.DOM_EXP, B.FCST_TYPE, B.INCOTERMS, B.PLANT_SITE_ID, B.SEQ
                       FROM ( SELECT DIVISION_ID, FROM_SITE, ITEM_ID, MIN(SEQ) AS MIN_SEQ
                                FROM GT_PRDM_END_RTF_RAW
                               GROUP BY DIVISION_ID, FROM_SITE, ITEM_ID ) A
                       JOIN GT_PRDM_END_RTF_RAW B ON A.DIVISION_ID = B.DIVISION_ID AND A.FROM_SITE = B.FROM_SITE AND A.ITEM_ID = B.ITEM_ID AND A.MIN_SEQ = B.SEQ
                      UNION ALL
                      SELECT DISTINCT B.DIVISION_ID, B.PROJECT_CODE, B.SCM_SITE_ID, B.ITEM_ID, B.DOM_EXP, B.FCST_TYPE, B.INCOTERMS, B.PLANT_SITE_ID, B.SITE_SEQ
                       FROM ( SELECT DIVISION_ID, SCM_SITE_ID, ITEM_ID, MIN(SITE_SEQ) AS MIN_SEQ
                                FROM GT_PRDM_AS_INV
                               GROUP BY DIVISION_ID, SCM_SITE_ID, ITEM_ID ) A
                       JOIN GT_PRDM_AS_INV B ON A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID AND A.ITEM_ID = B.ITEM_ID AND A.MIN_SEQ = B.SITE_SEQ
                    ) B ON A.DIVISION_ID = B.DIVISION_ID AND A.AS_SITE = B.SCM_SITE_ID AND A.ITEM_ID = B.ITEM_ID
             GROUP BY B.DIVISION_ID, B.PROJECT_CODE, B.SCM_SITE_ID, B.ITEM_ID, B.DOM_EXP, B.FCST_TYPE, B.INCOTERMS, B.PLANT_SITE_ID, B.SEQ, A.AS_PLANT;

        ELSE

            INSERT INTO GT_PRDM_AS_INV ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, YYYYMMDD, PLANT_SITE_ID, QTY, SITE_SEQ, AS_PLANT )
            SELECT B.DIVISION_ID, B.PROJECT_CODE, B.SCM_SITE_ID, B.ITEM_ID, B.DOM_EXP, B.FCST_TYPE, B.INCOTERMS, 'AS_Inv'
                 , TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD'), B.PLANT_SITE_ID
                 , SUM(A.QTY)
                 , B.SITE_SEQ, A.AS_PLANT
              FROM ( SELECT A.DIVISION_ID, C.SEGMENT1 AS AS_SITE, A.ITEM_ID, SUM(SCM_QTY) AS QTY, C.SEGMENT2 AS AS_PLANT
                       FROM SSP_DNM_STOCK_C A
                       JOIN SCM_ADM_LOOKUP_MASTER_DETAIL B ON B.SEGMENT1 = A.DIVISION_ID AND B.SEGMENT3 = A.PLANT_ID AND B.SEGMENT4 = A.STORAGE_ID AND B.LOOKUP_TYPE = 'SSP_AS_DIV_SLOC' AND B.VALID_YN = 'Y'
                       JOIN SCM_ADM_LOOKUP_MASTER_DETAIL C ON B.SEGMENT1 = C.SEGMENT3 AND B.SEGMENT2 = C.SEGMENT2 AND C.LOOKUP_TYPE = 'AS_SITE_PLANT' AND C.VALID_YN = 'Y'
                      /* [E20260402-001736] SSP CUTOFF_DATE = 일요일. DATE 컬럼 = DATE 로 비교. */
                      WHERE A.CUTOFF_DATE = TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') - 1
                        AND A.STOCK_TYPE = 'INVENTORY'
                      GROUP BY A.DIVISION_ID, C.SEGMENT1, A.ITEM_ID, C.SEGMENT2
                     UNION ALL
                     /* [E20250113-000270] 운송중(INTRANSIT) 재고 적용 */
                     SELECT A.DIVISION_ID, C.SEGMENT1 AS AS_SITE, A.ITEM_ID, SUM(DELIVERY_QTY) AS QTY, C.SEGMENT2 AS AS_PLANT
                       FROM SCM_DNM_INTRANSIT_C A
                       JOIN SCM_ADM_LOOKUP_MASTER_DETAIL B ON B.SEGMENT1 = A.DIVISION_ID AND B.SEGMENT3 = A.PLANT_ID AND B.SEGMENT4 = A.ATTRIBUTE2 AND B.LOOKUP_TYPE = 'SSP_AS_DIV_SLOC' AND B.VALID_YN = 'Y'
                       JOIN SCM_ADM_LOOKUP_MASTER_DETAIL C ON B.SEGMENT1 = C.SEGMENT3 AND B.SEGMENT2 = C.SEGMENT2 AND C.LOOKUP_TYPE = 'AS_SITE_PLANT' AND C.VALID_YN = 'Y'
                      WHERE A.RESULT_DATE = TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD')
                        AND A.RESULT_TYPE = 'I'
                      GROUP BY A.DIVISION_ID, C.SEGMENT1, A.ITEM_ID, C.SEGMENT2 ) A
              JOIN ( SELECT DISTINCT B.DIVISION_ID, B.PROJECT_CODE, B.SCM_SITE_ID, B.ITEM_ID, B.DOM_EXP, B.FCST_TYPE, B.INCOTERMS, B.PLANT_SITE_ID, B.SITE_SEQ
                       FROM ( SELECT DIVISION_ID, SCM_SITE_ID, ITEM_ID, MIN(SITE_SEQ) AS MIN_SEQ
                                FROM GT_PRDM_AS_INV
                               GROUP BY DIVISION_ID, SCM_SITE_ID, ITEM_ID ) A
                       JOIN GT_PRDM_AS_INV B ON A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID AND A.ITEM_ID = B.ITEM_ID AND A.MIN_SEQ = B.SITE_SEQ
                    ) B ON A.DIVISION_ID = B.DIVISION_ID AND A.AS_SITE = B.SCM_SITE_ID AND A.ITEM_ID = B.ITEM_ID
             GROUP BY B.DIVISION_ID, B.PROJECT_CODE, B.SCM_SITE_ID, B.ITEM_ID, B.DOM_EXP, B.FCST_TYPE, B.INCOTERMS, B.PLANT_SITE_ID, B.SITE_SEQ, A.AS_PLANT;

        END IF;

        /* AS_PLANT 일괄 업데이트 */
        MERGE INTO GT_PRDM_AS_INV A
        USING ( SELECT SEGMENT3, SEGMENT1, MAX(SEGMENT2) AS SEGMENT2
                  FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                 WHERE LOOKUP_TYPE = 'AS_SITE_PLANT' AND VALID_YN = 'Y'
                 GROUP BY SEGMENT3, SEGMENT1 ) B
        ON ( A.DIVISION_ID = B.SEGMENT3 AND A.SCM_SITE_ID = B.SEGMENT1 )
        WHEN MATCHED THEN UPDATE SET A.AS_PLANT = B.SEGMENT2;

        /* --------------------------------------------------------------------------------------- */
        /* AS PLANT 기준 모델 적재 -> GT_PRDM_AS_LOOP ( SEQ 1부터 연속채번 ) */
        /* --------------------------------------------------------------------------------------- */
        INSERT INTO GT_PRDM_AS_LOOP ( DIVISION_ID, SCM_SITE_ID, ITEM_ID, CALC_START_DATE, FROM_PLANT, SEQ )
        SELECT X.DIVISION_ID, X.SCM_SITE_ID, X.ITEM_ID, X.CALC_START_DATE, X.FROM_PLANT
             , ROW_NUMBER() OVER ( ORDER BY X.DIVISION_ID, X.SCM_SITE_ID, X.ITEM_ID )
          FROM ( SELECT DISTINCT A.DIVISION_ID, A.SCM_SITE_ID, A.ITEM_ID
                      , CASE WHEN P_DIVISION_ID LIKE '81%' THEN V_SHIP_START_YYYYMMDD ELSE TO_CHAR(TO_DATE(V_SHIP_START_YYYYMMDD, 'YYYYMMDD') + B.SHIP_FROZEN, 'YYYYMMDD') END AS CALC_START_DATE
                      , C.SEGMENT2 AS FROM_PLANT
                   FROM GT_PRDM_AS_INV A
                   JOIN SCM_MST_SITE B ON A.DIVISION_ID = B.DIVISION_ID AND A.AS_PLANT = B.SCM_SITE_ID
                   JOIN SCM_ADM_LOOKUP_MASTER_DETAIL C ON A.DIVISION_ID = C.SEGMENT3 AND A.SCM_SITE_ID = C.SEGMENT1 AND C.LOOKUP_TYPE = 'AS_SITE_PLANT' AND C.VALID_YN = 'Y'
                  WHERE A.SITE_SEQ = 1 ) X;

        INSERT INTO GT_PRDM_AS_LOOP ( DIVISION_ID, SCM_SITE_ID, ITEM_ID, CALC_START_DATE, FROM_PLANT, SEQ )
        SELECT X.DIVISION_ID, X.SCM_SITE_ID, X.ITEM_ID, X.CALC_START_DATE, X.FROM_PLANT
             , ( SELECT NVL(MAX(SEQ), 0) FROM GT_PRDM_AS_LOOP ) + ROW_NUMBER() OVER ( ORDER BY X.DIVISION_ID, X.SCM_SITE_ID, X.ITEM_ID )
          FROM ( SELECT DISTINCT A.DIVISION_ID, A.SCM_SITE_ID, A.ITEM_ID
                      , CASE WHEN P_DIVISION_ID LIKE '81%' THEN V_SHIP_START_YYYYMMDD ELSE TO_CHAR(TO_DATE(V_SHIP_START_YYYYMMDD, 'YYYYMMDD') + C.SHIP_FROZEN, 'YYYYMMDD') END AS CALC_START_DATE
                      , B.SEGMENT2 AS FROM_PLANT
                   FROM DM_PLN_MKT_FCST_C A
                   JOIN SCM_ADM_LOOKUP_MASTER_DETAIL B ON A.DIVISION_ID = B.SEGMENT3 AND A.SCM_SITE_ID = B.SEGMENT1 AND B.LOOKUP_TYPE = 'AS_SITE_PLANT' AND B.VALID_YN = 'Y'
                   JOIN SCM_MST_SITE C ON A.DIVISION_ID = C.DIVISION_ID AND B.SEGMENT2 = C.SCM_SITE_ID
                   LEFT OUTER JOIN GT_PRDM_AS_LOOP E ON A.DIVISION_ID = E.DIVISION_ID AND A.SCM_SITE_ID = E.SCM_SITE_ID AND A.ITEM_ID = E.ITEM_ID
                   JOIN ( SELECT DISTINCT A.DIVISION_ID, A.SCM_SITE_ID, A.ITEM_ID, C.SEGMENT2
                            FROM GT_PRDM_AS_INV A
                            JOIN SCM_ADM_LOOKUP_MASTER_DETAIL C ON A.DIVISION_ID = C.SEGMENT3 AND A.SCM_SITE_ID = C.SEGMENT1 AND C.LOOKUP_TYPE = 'AS_SITE_PLANT' AND C.VALID_YN = 'Y'
                         ) F ON A.DIVISION_ID = F.DIVISION_ID AND A.SCM_SITE_ID = F.SCM_SITE_ID AND A.ITEM_ID = F.ITEM_ID
                  WHERE A.DIVISION_ID = P_DIVISION_ID
                    AND A.VERSION_NO  = P_VERSION_NO
                    AND A.YYYYMMDD >= V_SHIP_START_YYYYMMDD
                    AND E.DIVISION_ID IS NULL ) X;

        /* --------------------------------------------------------------------------------------- */
        /* #T_AS_INV 일자별 재고 생성 루프 ( 첫 AS_LOOP WHILE ) */
        /* --------------------------------------------------------------------------------------- */
        SELECT 1, COUNT(*) INTO I, CNT FROM GT_PRDM_AS_LOOP;

        WHILE ( I <= CNT ) LOOP

            SELECT DIVISION_ID, SCM_SITE_ID, ITEM_ID
              INTO V_DIVISION_ID, V_SCM_SITE_ID, V_ITEM_ID
              FROM GT_PRDM_AS_LOOP
             WHERE SEQ = I;

            BEGIN
                SELECT PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID
                  INTO V_PROJECT_CODE, V_SCM_SITE_ID, V_ITEM_ID, V_DOM_EXP, V_FCST_TYPE, V_INCOTERMS, V_PLANT_SITE_ID
                  FROM ( SELECT PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID
                           FROM GT_PRDM_AS_INV
                          WHERE DIVISION_ID = V_DIVISION_ID
                            AND SCM_SITE_ID = V_SCM_SITE_ID
                            AND ITEM_ID = V_ITEM_ID
                            AND SITE_SEQ = 1 )
                 WHERE ROWNUM = 1;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN NULL;
            END;

            INSERT INTO GT_PRDM_AS_INV ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, YYYYMMDD, PLANT_SITE_ID, QTY, SITE_SEQ )
            SELECT DISTINCT V_DIVISION_ID, V_PROJECT_CODE, V_SCM_SITE_ID, V_ITEM_ID, V_DOM_EXP, V_FCST_TYPE, V_INCOTERMS, 'AS_Inv', A.BASIS_YYYYMMDD, V_PLANT_SITE_ID
--               , SUM( CASE WHEN B.MEASURE IN ('AS_In_Plan', 'AS_INV') THEN NVL(B.QTY, 0) ELSE NVL(-B.QTY, 0) END ) OVER ( ORDER BY A.BASIS_YYYYMMDD )   --  2026.10.08 AJS
                 , SUM( CASE WHEN B.MEASURE IN ('AS_In_Plan', 'AS_Inv') THEN NVL(B.QTY, 0) ELSE NVL(-B.QTY, 0) END ) OVER ( ORDER BY A.BASIS_YYYYMMDD )   --  2026.10.08 AJS
                 , B.SITE_SEQ
              FROM SCM_SYS_CALENDAR_M A
              LEFT OUTER JOIN GT_PRDM_AS_INV B ON A.BASIS_YYYYMMDD = B.YYYYMMDD
                                              AND B.DIVISION_ID = V_DIVISION_ID
                                              AND B.SCM_SITE_ID = V_SCM_SITE_ID
                                              AND B.ITEM_ID = V_ITEM_ID
             WHERE A.BASIS_YYYYMMDD BETWEEN TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD')
                                        AND TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') + 7*16, 'YYYYMMDD');

            /* 기초재고 일자 중복행 삭제 ( 나중에 넣은 데이터 ) */
            DELETE FROM GT_PRDM_AS_INV A
             WHERE A.YYYYMMDD = TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD')
               AND A.AS_PLANT IS NULL;

            I := I + 1;
        END LOOP;

        /* --------------------------------------------------------------------------------------- */
        /* [E20240226-000021] 54주 보완 : SITE_SEQ 없는 AS_Inv 최초일자에 SITE_SEQ=1 */
        /* --------------------------------------------------------------------------------------- */
        MERGE INTO GT_PRDM_AS_INV A
        USING ( SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, MIN(YYYYMMDD) AS YYYYMMDD
                  FROM GT_PRDM_AS_INV C
                 WHERE SITE_SEQ IS NULL
                   AND MEASURE = 'AS_Inv'
                   AND NOT EXISTS ( SELECT 1 FROM GT_PRDM_AS_INV D
                                     WHERE D.MEASURE = 'AS_Inv' AND D.SITE_SEQ = 1
                                       AND C.DIVISION_ID = D.DIVISION_ID AND C.SCM_SITE_ID = D.SCM_SITE_ID AND C.ITEM_ID = D.ITEM_ID )
                 GROUP BY DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID ) B
        ON (    A.DIVISION_ID   = B.DIVISION_ID
            AND A.PROJECT_CODE  = B.PROJECT_CODE
            AND A.SCM_SITE_ID   = B.SCM_SITE_ID
            AND A.ITEM_ID       = B.ITEM_ID
            AND A.DOM_EXP       = B.DOM_EXP
            AND A.FCST_TYPE     = B.FCST_TYPE
            AND A.INCOTERMS     = B.INCOTERMS
            AND A.PLANT_SITE_ID = B.PLANT_SITE_ID
            AND A.YYYYMMDD      = B.YYYYMMDD )
        WHEN MATCHED THEN UPDATE SET A.SITE_SEQ = 1 WHERE A.MEASURE = 'AS_Inv';

        /* --------------------------------------------------------------------------------------- */
        /* 받는 Site 들에 RTF 생성 ( SSP 확정구간 이후 ) : MKT FCST 취합 -> GT_PRDM_RTF */
        /* --------------------------------------------------------------------------------------- */
        INSERT INTO GT_PRDM_RTF ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, YYYYMMDD, PLANT_SITE_ID, QTY, FROM_PLANT, ETD_DATE, SITE_SEQ )
        SELECT B.DIVISION_ID, B.PROJECT_CODE, B.SCM_SITE_ID, B.ITEM_ID, B.DOM_EXP, B.FCST_TYPE, B.INCOTERMS, B.MEASURE, B.YYYYMMDD, B.PLANT_SITE_ID, B.QTY
             , A.FROM_SITE, TO_CHAR(TO_DATE(B.YYYYMMDD, 'YYYYMMDD') - A.LT_TOTAL, 'YYYYMMDD')
             , ROW_NUMBER() OVER ( PARTITION BY B.DIVISION_ID, A.FROM_SITE, B.ITEM_ID, B.YYYYMMDD ORDER BY B.SCM_SITE_ID )
          FROM ( SELECT A.SEGMENT2 AS FROM_SITE, B.TO_SITE, B.LT_TOTAL, ROW_NUMBER() OVER ( PARTITION BY B.DIVISION_ID, B.FROM_SITE, B.TO_SITE ORDER BY B.PRIORITY ) AS BOD_SEQ
                   FROM SCM_ADM_LOOKUP_MASTER_DETAIL A
                   JOIN SCP_MST_BOD_N_V B ON A.SEGMENT2 = B.FROM_SITE AND B.DIVISION_ID = P_DIVISION_ID AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN B.FROM_YYYYMMDD AND B.TO_YYYYMMDD
                   JOIN SCM_MST_SITE C ON B.TO_SITE = C.SCM_SITE_ID AND C.SITE_TYPE = 'SALES' AND C.VALID_YN = 'Y' AND C.DIVISION_ID = P_DIVISION_ID
                  WHERE A.LOOKUP_TYPE = 'AS_SITE_PLANT' AND A.SEGMENT3 = P_DIVISION_ID AND A.VALID_YN = 'Y' ) A
          JOIN DM_PLN_MKT_FCST_C B ON A.TO_SITE = B.SCM_SITE_ID AND B.MEASURE = 'MKT_FCST' AND B.YYYYMMDD >= V_START_YYYYMMDD
                                  AND A.FROM_SITE = B.ATTRIBUTE10 AND B.DIVISION_ID = P_DIVISION_ID AND B.VERSION_NO = P_VERSION_NO
          JOIN SCM_MST_SITE C ON A.FROM_SITE = C.SCM_SITE_ID AND C.DIVISION_ID = P_DIVISION_ID
         WHERE A.BOD_SEQ = 1
           AND B.YYYYMMDD > CASE WHEN P_DIVISION_ID LIKE '81%' THEN V_SHIP_START_YYYYMMDD ELSE TO_CHAR(TO_DATE(V_SHIP_START_YYYYMMDD, 'YYYYMMDD') + C.SHIP_FROZEN, 'YYYYMMDD') END
           AND B.QTY <> 0;

        UPDATE GT_PRDM_RTF A
           SET A.ALLOC_SCD_RTF = CASE WHEN A.YYYYMMDD > NVL( ( SELECT MAX(YYYYMMDD)
                                                                 FROM GT_PRDM_END_RTF_RAW E
                                                                WHERE E.MEASURE IN ('RTF', 'SSP_RTF')
                                                                  AND E.DIVISION_ID = A.DIVISION_ID
                                                                  AND E.SCM_SITE_ID = A.SCM_SITE_ID ), '19000101' )
                                      THEN 'Y' ELSE 'N' END;


        INSERT INTO GT_PRDM_RTF_SITE ( FROM_SITE, SCM_SITE_ID, MAX_YMD )
        SELECT A.FROM_SITE, A.SCM_SITE_ID
             , CASE WHEN NVL(D.MAX_YMD, '19000101') > CASE WHEN P_DIVISION_ID LIKE '81%' THEN TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') + NVL(C.LT_TOTAL, 0), 'YYYYMMDD')
                                                           ELSE TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') + NVL(B.SHIP_FROZEN, 0) + NVL(C.LT_TOTAL, 0), 'YYYYMMDD') END
                    THEN D.MAX_YMD
                    ELSE CASE WHEN P_DIVISION_ID LIKE '81%' THEN TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') + NVL(C.LT_TOTAL, 0), 'YYYYMMDD')
                              ELSE TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') + NVL(B.SHIP_FROZEN, 0) + NVL(C.LT_TOTAL, 0), 'YYYYMMDD') END
               END
          FROM ( SELECT DISTINCT FROM_SITE, SCM_SITE_ID, AS_PLANT FROM GT_PRDM_END_RTF_RAW ) A
          JOIN SCM_MST_SITE B ON A.AS_PLANT = B.SCM_SITE_ID AND B.DIVISION_ID = P_DIVISION_ID
          JOIN ( SELECT FROM_SITE, TO_SITE, LT_TOTAL, ROW_NUMBER() OVER ( PARTITION BY FROM_SITE, TO_SITE, INCOTERMS ORDER BY PRIORITY ) AS PRT
                   FROM SCP_MST_BOD_N_V
                  WHERE DIVISION_ID = P_DIVISION_ID AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN FROM_YYYYMMDD AND TO_YYYYMMDD ) C
            ON A.AS_PLANT = C.FROM_SITE AND A.SCM_SITE_ID = C.TO_SITE AND C.PRT = 1
          LEFT OUTER JOIN ( SELECT FROM_SITE, SCM_SITE_ID, MAX(YYYYMMDD) AS MAX_YMD
                              FROM GT_PRDM_END_RTF_RAW
                             WHERE MEASURE = 'RTF'
                             GROUP BY FROM_SITE, SCM_SITE_ID ) D
            ON A.FROM_SITE = D.FROM_SITE AND A.SCM_SITE_ID = D.SCM_SITE_ID;

        MERGE INTO GT_PRDM_END_RTF_RAW A
        USING ( SELECT FROM_SITE, SCM_SITE_ID, MAX(MAX_YMD) AS MAX_YMD
                  FROM GT_PRDM_RTF_SITE
                 GROUP BY FROM_SITE, SCM_SITE_ID ) B
        ON ( A.SCM_SITE_ID = B.SCM_SITE_ID AND A.FROM_SITE = B.FROM_SITE )
        WHEN MATCHED THEN UPDATE SET A.SCD_ALLOC_START_DATE = B.MAX_YMD;

        UPDATE GT_PRDM_END_RTF_RAW
           SET LT_YYYYMMDD = TO_CHAR(TO_DATE(YYYYMMDD, 'YYYYMMDD') - NVL(LT_DAYS, 0), 'YYYYMMDD')
         WHERE MEASURE = 'MKT_FCST';

        /* --------------------------------------------------------------------------------------- */

        /* --------------------------------------------------------------------------------------- */
        SELECT 1, COUNT(*) INTO I, CNT FROM GT_PRDM_AS_LOOP;

        WHILE ( I <= CNT ) LOOP

            SELECT A.DIVISION_ID, A.FROM_PLANT, A.SCM_SITE_ID, A.ITEM_ID, TRUNC(NVL(B.QTY, 0)), A.CALC_START_DATE
                 , 0
                 , TO_CHAR(TO_DATE(V_SHIP_START_YYYYMMDD, 'YYYYMMDD') + 7*82, 'YYYYMMDD')
                 , 0, 0
              INTO V_DIVISION_ID, V_FROM_PLANT, V_FROM_SITE, V_ITEM_ID, V_INV_QTY, V_DATE
                 , V_SUM_REQ_QTY
                 , V_MAX_DATE
                 , V_INV_ADJ_QTY, V_SUM_REQ_QTY
              FROM GT_PRDM_AS_LOOP A
              LEFT OUTER JOIN GT_PRDM_AS_INV B ON A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID AND A.ITEM_ID = B.ITEM_ID
                   AND B.YYYYMMDD = TO_CHAR(TO_DATE(A.CALC_START_DATE, 'YYYYMMDD') - 1, 'YYYYMMDD')
--                 AND B.MEASURE = 'AS_INV'   --  2026.10.08 AJS
                   AND B.MEASURE = 'AS_Inv'   --  2026.10.08 AJS
             WHERE A.SEQ = I;

            WHILE ( V_DATE <= V_MAX_DATE ) LOOP


                SELECT V_INV_QTY + NVL(SUM(QTY), 0)
                  INTO V_INV_QTY
                  FROM GT_PRDM_AS_INV
                 WHERE MEASURE = 'AS_In_Plan'
                   AND DIVISION_ID = V_DIVISION_ID
                   AND SCM_SITE_ID = V_FROM_SITE
                   AND ITEM_ID = V_ITEM_ID
                   AND YYYYMMDD = V_DATE;
                V_INV_QTY := TRUNC(V_INV_QTY);

                SELECT NVL(SUM(NVL(MF_QTY, 0) - NVL(RTF_QTY, 0)), 0)
                  INTO V_SUM_REQ_QTY
                  FROM GT_PRDM_END_RTF_RAW
                 WHERE AS_PLANT = V_FROM_PLANT
                   AND ITEM_ID = V_ITEM_ID
                   AND DIVISION_ID = V_DIVISION_ID
                   AND LT_YYYYMMDD <= V_DATE
                   AND MEASURE = 'MKT_FCST'
                   AND NVL(MF_QTY, 0) > NVL(RTF_QTY, 0);

                /* 재고보다 요청수량이 적으면 요청만큼 생성 */
                IF ( V_SUM_REQ_QTY <= V_INV_QTY ) THEN

                    INSERT INTO GT_PRDM_AS_INV ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, YYYYMMDD, PLANT_SITE_ID, QTY, SITE_SEQ, FROM_SITE, ADD_YN )
                    SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, 'RTF_SCP'
                         , TO_CHAR(TO_DATE(V_DATE, 'YYYYMMDD') + NVL(LT_DAYS, 0), 'YYYYMMDD'), A.PLANT_SITE_ID, SUM(NVL(MF_QTY, 0) - NVL(RTF_QTY, 0)), NULL, A.AS_PLANT, 'Y'
                      FROM GT_PRDM_END_RTF_RAW A
                     WHERE A.AS_PLANT = V_FROM_PLANT
                       AND A.ITEM_ID = V_ITEM_ID
                       AND A.DIVISION_ID = V_DIVISION_ID
                       AND LT_YYYYMMDD <= V_DATE
                       AND MEASURE = 'MKT_FCST'
                       AND NVL(MF_QTY, 0) > NVL(RTF_QTY, 0)
                     GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS
                         , A.PLANT_SITE_ID, A.AS_PLANT, TO_CHAR(TO_DATE(V_DATE, 'YYYYMMDD') + NVL(LT_DAYS, 0), 'YYYYMMDD');

                    UPDATE GT_PRDM_END_RTF_RAW A
                       SET RTF_QTY = MF_QTY
                     WHERE A.AS_PLANT = V_FROM_PLANT
                       AND A.ITEM_ID = V_ITEM_ID
                       AND A.DIVISION_ID = V_DIVISION_ID
                       AND LT_YYYYMMDD <= V_DATE
                       AND MEASURE = 'MKT_FCST'
                       AND NVL(MF_QTY, 0) > NVL(RTF_QTY, 0);

                    V_INV_QTY := TRUNC(V_INV_QTY - V_SUM_REQ_QTY);

                ELSE  /* 재고가 적으면 배분 */

                    DELETE FROM GT_PRDM_RCV;

                    INSERT INTO GT_PRDM_RCV ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, YYYYMMDD, PLANT_SITE_ID, QTY, FROM_SITE, ETD_DATE, SITE_SEQ, RTF_RAW_KEY_VAL )
                    SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE
                         , TO_CHAR(TO_DATE(V_DATE, 'YYYYMMDD') + NVL(LT_DAYS, 0), 'YYYYMMDD'), PLANT_SITE_ID
                         , NVL(MF_QTY, 0) - NVL(RTF_QTY, 0)
                         , AS_PLANT, V_DATE
                         , ROW_NUMBER() OVER ( ORDER BY A.YYYYMMDD, A.SCM_SITE_ID )
                         , KEY_VAL
                      FROM GT_PRDM_END_RTF_RAW A
                     WHERE A.AS_PLANT = V_FROM_PLANT
                       AND A.ITEM_ID = V_ITEM_ID
                       AND A.DIVISION_ID = V_DIVISION_ID
                       AND LT_YYYYMMDD <= V_DATE
                       AND MEASURE = 'MKT_FCST'
                       AND NVL(MF_QTY, 0) > NVL(RTF_QTY, 0);

                    SELECT 1, COUNT(*) INTO I_RCV, CNT_RCV FROM GT_PRDM_RCV;

                    WHILE ( I_RCV <= CNT_RCV AND V_INV_QTY > 0 ) LOOP

                        SELECT QTY, RTF_RAW_KEY_VAL INTO V_REQ_QTY, V_KEY_VAL
                          FROM GT_PRDM_RCV
                         WHERE SITE_SEQ = I_RCV;

                        INSERT INTO GT_PRDM_AS_INV ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, YYYYMMDD, PLANT_SITE_ID, QTY, SITE_SEQ, FROM_SITE, ADD_YN )
                        SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, 'RTF_SCP'
                             , A.YYYYMMDD, A.PLANT_SITE_ID
                             , SUM( CASE WHEN V_REQ_QTY <= V_INV_QTY THEN V_REQ_QTY ELSE V_INV_QTY END )
                             , A.SITE_SEQ, A.FROM_SITE, 'Y'
                          FROM GT_PRDM_RCV A
                         WHERE SITE_SEQ = I_RCV
                         GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS
                             , A.YYYYMMDD, A.PLANT_SITE_ID, A.SITE_SEQ, A.FROM_SITE;

                        UPDATE GT_PRDM_END_RTF_RAW
                           SET RTF_QTY = RTF_QTY + CASE WHEN V_REQ_QTY <= V_INV_QTY THEN V_REQ_QTY ELSE V_INV_QTY END
                         WHERE KEY_VAL = V_KEY_VAL;

                        V_INV_QTY := TRUNC( CASE WHEN V_REQ_QTY <= V_INV_QTY THEN V_INV_QTY - V_REQ_QTY ELSE 0 END );

                        I_RCV := I_RCV + 1;
                    END LOOP;

                END IF;

                /* Inv Insert / Update */
                UPDATE GT_PRDM_AS_INV
                   SET QTY = V_INV_QTY
                 WHERE DIVISION_ID = V_DIVISION_ID
                   AND SCM_SITE_ID = V_FROM_SITE
                   AND ITEM_ID = V_ITEM_ID
                   AND YYYYMMDD = V_DATE
                   AND MEASURE = 'AS_Inv';

                IF SQL%ROWCOUNT = 0 THEN
                    INSERT INTO GT_PRDM_AS_INV ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, YYYYMMDD, PLANT_SITE_ID, QTY, SITE_SEQ )
                    SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, 'AS_Inv', V_DATE, A.PLANT_SITE_ID
                         , V_INV_QTY, 1
                      FROM GT_PRDM_AS_INV A
                     WHERE A.DIVISION_ID = V_DIVISION_ID
                       AND A.SCM_SITE_ID = V_FROM_SITE
                       AND A.ITEM_ID = V_ITEM_ID
                       AND A.MEASURE = 'AS_Inv'
                       AND A.SITE_SEQ = 1
                       AND ROWNUM = 1;
                END IF;

                V_DATE := TO_CHAR(TO_DATE(V_DATE, 'YYYYMMDD') + 1, 'YYYYMMDD');

            END LOOP;

            I := I + 1;
        END LOOP;


        DELETE FROM GT_PRDM_AS_INV WHERE YYYYMMDD < V_START_YYYYMMDD;

        /* --------------------------------------------------------------------------------------- */
        /* 결과 INSERT : DM_PLN_MKT_FCST_C ( AS_Inv + 8주 이후 RTF ) */
        /* --------------------------------------------------------------------------------------- */
        DELETE FROM DM_PLN_MKT_FCST_C A
         WHERE EXISTS ( SELECT 1 FROM SCM_ADM_LOOKUP_MASTER_DETAIL B
                         WHERE A.DIVISION_ID = B.SEGMENT3 AND A.SCM_SITE_ID = B.SEGMENT1
                           AND B.LOOKUP_TYPE = 'AS_SITE_PLANT' AND B.VALID_YN = 'Y' )
           AND A.DIVISION_ID = P_DIVISION_ID
           AND A.VERSION_NO  = P_VERSION_NO
           AND A.MEASURE = 'AS_Inv'
           AND A.YYYYMMDD >= V_START_YYYYMMDD;

        INSERT INTO DM_PLN_MKT_FCST_C
            ( DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD
            , PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP
            , FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD
            , QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
            , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
            , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
        SELECT DISTINCT A.DIVISION_ID, P_VERSION_NO, V_CUTOFF_TYPE, V_CUTOFF_YYYYMMDD
             , A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
             -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (START)
--             , A.FCST_TYPE, A.INCOTERMS, A.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE ' ' END, A.YYYYMMDD
             , A.FCST_TYPE, A.INCOTERMS, A.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '/' END, A.YYYYMMDD
             -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (END)
             , A.QTY, V_CREATED_BY, SYSDATE, V_CREATED_BY, SYSDATE
             , '', '', '', '', ''
             , '', '', '', '', ''
          FROM GT_PRDM_AS_INV A
         WHERE MEASURE = 'AS_Inv';


        INSERT INTO DM_PLN_MKT_FCST_C
            ( DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD
            , PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP
            , FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD
            , QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
            , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
            , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
        SELECT A.DIVISION_ID, A.VERSION_NO, A.CUTOFF_TYPE, A.CUTOFF_YYYYMMDD
             , A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
             , A.FCST_TYPE, A.INCOTERMS, A.MEASURE, A.PLANT_SITE_ID, A.YYYYMMDD
             , A.QTY, A.CREATED_BY, A.CREATION_DATE, A.LAST_UPDATED_BY, A.LAST_UPDATE_DATE
             , A.ATTRIBUTE1, A.ATTRIBUTE2, A.ATTRIBUTE3, A.ATTRIBUTE4, A.ATTRIBUTE5
             , A.ATTRIBUTE6, A.ATTRIBUTE7, A.ATTRIBUTE8, A.ATTRIBUTE9, A.ATTRIBUTE10
          FROM ( SELECT A.DIVISION_ID, P_VERSION_NO AS VERSION_NO, V_CUTOFF_TYPE AS CUTOFF_TYPE, V_CUTOFF_YYYYMMDD AS CUTOFF_YYYYMMDD
                      , A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
                      -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (START)
--                      , A.FCST_TYPE, A.INCOTERMS, B.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE ' ' END AS PLANT_SITE_ID, A.YYYYMMDD
                      , A.FCST_TYPE, A.INCOTERMS, B.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '/' END AS PLANT_SITE_ID, A.YYYYMMDD
                      -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (END)
                      , SUM(A.QTY) AS QTY, V_CREATED_BY AS CREATED_BY, SYSDATE AS CREATION_DATE, V_CREATED_BY AS LAST_UPDATED_BY, SYSDATE AS LAST_UPDATE_DATE
                      , '' AS ATTRIBUTE1, '' AS ATTRIBUTE2, '' AS ATTRIBUTE3, '' AS ATTRIBUTE4, '' AS ATTRIBUTE5
                      , '' AS ATTRIBUTE6, '' AS ATTRIBUTE7, '' AS ATTRIBUTE8, '' AS ATTRIBUTE9, A.FROM_SITE AS ATTRIBUTE10
                   FROM GT_PRDM_AS_INV A
                   JOIN ( SELECT 'RTF' AS MEASURE FROM DUAL
                          UNION ALL SELECT 'RTF_SCP' FROM DUAL
                          UNION ALL SELECT 'RTF_SYS_RP' FROM DUAL
                          UNION ALL SELECT 'RTF_PR' FROM DUAL ) B ON 1 = 1
                  WHERE A.ADD_YN = 'Y' AND A.MEASURE = 'RTF_SCP'
                  GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
                      -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (START)
--                      , A.FCST_TYPE, A.INCOTERMS, B.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE ' ' END, A.YYYYMMDD, A.FROM_SITE ) A
                      , A.FCST_TYPE, A.INCOTERMS, B.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '/' END, A.YYYYMMDD, A.FROM_SITE ) A
                      -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (END)
          LEFT OUTER JOIN DM_PLN_MKT_FCST_C B
            ON A.DIVISION_ID = B.DIVISION_ID
           AND NVL(A.PROJECT_CODE, '@') = NVL(B.PROJECT_CODE, '@')
           AND A.SCM_SITE_ID = B.SCM_SITE_ID
           AND A.ITEM_ID = B.ITEM_ID
           AND NVL(A.DOM_EXP, '@') = NVL(B.DOM_EXP, '@')
           AND NVL(A.FCST_TYPE, '@') = NVL(B.FCST_TYPE, '@')
           AND NVL(A.INCOTERMS, '@') = NVL(B.INCOTERMS, '@')
           AND A.MEASURE = B.MEASURE
           AND NVL(A.PLANT_SITE_ID, '@') = NVL(B.PLANT_SITE_ID, '@')
           AND A.YYYYMMDD = B.YYYYMMDD
           AND B.VERSION_NO = P_VERSION_NO
           AND B.CUTOFF_TYPE = V_CUTOFF_TYPE
           AND B.CUTOFF_YYYYMMDD = V_CUTOFF_YYYYMMDD
         WHERE B.DIVISION_ID IS NULL;

        /* --------------------------------------------------------------------------------------- */
        /* [PJ2025-50017] 결과 INSERT : DM_PLN_CFM_MKT_DEMAND_PLAN_C ( AS_Inv + 8주 이후 RTF ) */
        /* --------------------------------------------------------------------------------------- */
        DELETE FROM DM_PLN_CFM_MKT_DEMAND_PLAN_C A
         WHERE EXISTS ( SELECT 1 FROM SCM_ADM_LOOKUP_MASTER_DETAIL B
                         WHERE A.DIVISION_ID = B.SEGMENT3 AND A.SCM_SITE_ID = B.SEGMENT1
                           AND B.LOOKUP_TYPE = 'AS_SITE_PLANT' AND B.VALID_YN = 'Y' )
           AND A.DIVISION_ID = P_DIVISION_ID
           AND A.VERSION_NO  = P_VERSION_NO
           AND A.MEASURE = 'AS_Inv'
           AND A.YYYYMMDD >= V_START_YYYYMMDD;

        INSERT INTO DM_PLN_CFM_MKT_DEMAND_PLAN_C
            ( DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD
            , PROJECT_CODE, END_CUSTOMER, SCM_SITE_ID, ITEM_ID, DOM_EXP
            , FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID, YYYYMMDD
            , QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
            , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
            , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
        SELECT DISTINCT A.DIVISION_ID, P_VERSION_NO, V_CUTOFF_TYPE, V_CUTOFF_YYYYMMDD
             , A.PROJECT_CODE
             -- 2026.09.18 AJS END_CUSTOMER 빈값 채움값 '-' 로 통일 (START)
--             , CASE WHEN A.DIVISION_ID = '40' THEN A.PROJECT_CODE ELSE ' ' END
             , CASE WHEN A.DIVISION_ID = '40' THEN A.PROJECT_CODE ELSE '/' END
             -- 2026.09.18 AJS END_CUSTOMER 빈값 채움값 '-' 로 통일 (END)
             , A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
             -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (START)
--             , A.FCST_TYPE, A.INCOTERMS, A.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE ' ' END, '-', A.YYYYMMDD
             , A.FCST_TYPE, A.INCOTERMS, A.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '/' END, '-', A.YYYYMMDD
             -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (END)
             , A.QTY, V_CREATED_BY, SYSDATE, V_CREATED_BY, SYSDATE
             , '', NULL, '', '', ''
             , '', '', '', '', ''
          FROM GT_PRDM_AS_INV A
         WHERE MEASURE = 'AS_Inv';


        INSERT INTO DM_PLN_CFM_MKT_DEMAND_PLAN_C
            ( DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD
            , PROJECT_CODE, END_CUSTOMER, SCM_SITE_ID, ITEM_ID, DOM_EXP
            , FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID, YYYYMMDD
            , QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
            , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
            , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
        SELECT A.DIVISION_ID, A.VERSION_NO, A.CUTOFF_TYPE, A.CUTOFF_YYYYMMDD
             , A.PROJECT_CODE
             -- 2026.09.18 AJS END_CUSTOMER 빈값 채움값 '-' 로 통일 (START)
--             , CASE WHEN A.DIVISION_ID = '40' THEN A.PROJECT_CODE ELSE ' ' END
             , CASE WHEN A.DIVISION_ID = '40' THEN A.PROJECT_CODE ELSE '/' END
             -- 2026.09.18 AJS END_CUSTOMER 빈값 채움값 '-' 로 통일 (END)
             , A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
             , A.FCST_TYPE, A.INCOTERMS, A.MEASURE, A.PLANT_SITE_ID, A.FROM_SITE_ID, A.YYYYMMDD
             , A.QTY, A.CREATED_BY, A.CREATION_DATE, A.LAST_UPDATED_BY, A.LAST_UPDATE_DATE
             , A.ATTRIBUTE1, A.ATTRIBUTE2, A.ATTRIBUTE3, A.ATTRIBUTE4, A.ATTRIBUTE5
             , A.ATTRIBUTE6, A.ATTRIBUTE7, A.ATTRIBUTE8, A.ATTRIBUTE9, A.ATTRIBUTE10
          FROM ( SELECT A.DIVISION_ID, P_VERSION_NO AS VERSION_NO, V_CUTOFF_TYPE AS CUTOFF_TYPE, V_CUTOFF_YYYYMMDD AS CUTOFF_YYYYMMDD
                      , A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
                      -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (START)
--                      , A.FCST_TYPE, A.INCOTERMS, B.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE ' ' END AS PLANT_SITE_ID
                      , A.FCST_TYPE, A.INCOTERMS, B.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '/' END AS PLANT_SITE_ID
                      -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (END)
                      , '-' AS FROM_SITE_ID, A.YYYYMMDD
                      , SUM(A.QTY) AS QTY, V_CREATED_BY AS CREATED_BY, SYSDATE AS CREATION_DATE, V_CREATED_BY AS LAST_UPDATED_BY, SYSDATE AS LAST_UPDATE_DATE
                      , '' AS ATTRIBUTE1, NULL AS ATTRIBUTE2, '' AS ATTRIBUTE3, '' AS ATTRIBUTE4, '' AS ATTRIBUTE5
                      , '' AS ATTRIBUTE6, '' AS ATTRIBUTE7, '' AS ATTRIBUTE8, '' AS ATTRIBUTE9, A.FROM_SITE AS ATTRIBUTE10
                   FROM GT_PRDM_AS_INV A
                   JOIN ( SELECT 'RTF' AS MEASURE FROM DUAL
                          UNION ALL SELECT 'RTF_SCP' FROM DUAL
                          UNION ALL SELECT 'RTF_SYS_RP' FROM DUAL
                          UNION ALL SELECT 'RTF_PR' FROM DUAL ) B ON 1 = 1
                  WHERE A.ADD_YN = 'Y' AND A.MEASURE = 'RTF_SCP'
                  GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
                      -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (START)
--                      , A.FCST_TYPE, A.INCOTERMS, B.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE ' ' END, A.YYYYMMDD, A.FROM_SITE ) A
                      , A.FCST_TYPE, A.INCOTERMS, B.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '/' END, A.YYYYMMDD, A.FROM_SITE ) A
                      -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (END)
          LEFT OUTER JOIN DM_PLN_CFM_MKT_DEMAND_PLAN_C B
            ON A.DIVISION_ID = B.DIVISION_ID
           AND NVL(A.PROJECT_CODE, '@') = NVL( CASE WHEN B.DIVISION_ID = '40' THEN B.END_CUSTOMER ELSE B.PROJECT_CODE END, '@')
           AND A.SCM_SITE_ID = B.SCM_SITE_ID
           AND A.ITEM_ID = B.ITEM_ID
           AND NVL(A.DOM_EXP, '@') = NVL(B.DOM_EXP, '@')
           AND NVL(A.FCST_TYPE, '@') = NVL(B.FCST_TYPE, '@')
           AND NVL(A.INCOTERMS, '@') = NVL(B.INCOTERMS, '@')
           AND A.MEASURE = B.MEASURE
           AND NVL(A.PLANT_SITE_ID, '@') = NVL(B.PLANT_SITE_ID, '@')
           AND A.YYYYMMDD = B.YYYYMMDD
           AND B.VERSION_NO = P_VERSION_NO
           AND B.CUTOFF_TYPE = V_CUTOFF_TYPE
           AND B.CUTOFF_YYYYMMDD = V_CUTOFF_YYYYMMDD
         WHERE B.DIVISION_ID IS NULL;

        COMMIT;

    EXCEPTION
        WHEN OTHERS THEN
            ROLLBACK;
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := '@P_DIVISION_ID: ' || P_DIVISION_ID || ' / @P_VERSION_NO: ' || P_VERSION_NO
                             || '/ ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
            D_EVENT_DATE  := SYSDATE;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE
                , V_DESCRIPTION, TO_CHAR(SQLCODE), SUBSTR(SQLERRM, 1, 1000), SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 1000));
    END;


    IF V_LOG_TYPE IS NULL OR V_LOG_TYPE <> 'ERROR' THEN
        V_LOG_TYPE    := 'END';
        V_LOG_MESSAGE := '########## END OF PROCEDURE ##########';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    END IF;

END PR_DM_DNM_CREATE_C_WS_RTF;

PROCEDURE           "PR_DM_DNM_CREATE_WS_RTF" 
(
    P_DIVISION_ID   IN  VARCHAR2  /* 사업부 확장에 대비해서 사업부별로 호출하도록 한다. */
)
/* ==============================================================================================================================================
 * PROGRAM ID   : PR_DM_DNM_CREATE_WS_RTF
 * DESCRIPTION  : W/S 의 Sales Site 의 RTF 를 생성 ( Shipment Plan 참조 )
 * PROGRAM HISTORY
 *==============================================================================================================================================
 *   DATE       IN CHARGE      DESCRIPTION
 *==============================================================================================================================================
 * 2021.09.27   hwi1993     [PJ20209643]    INITIAL RELEASE
 * 2021.11.04   HWI1993     운영 적용후 보완
 * 2021.11.16   HWI1993     룩업에 VALID 조건 추가
 * 2021.12.23   HWI1993     FCST TYPE 조건 변경
 * 2022.01.21   HWI1993     C20220118-000097 MKT FSCT에 RTF 미조회 건 - 고객향 RTF 메저에 ATTR10 에 FROM_PLANT 추가함( MKT FCST 화면에서 조회용 )
 * 2022.04.05   HWI1993     GM JV 작업
 * 2022.04.12   Hwi1993     확정구간의 ETA 와 미확정구간의 RTF 가 겹쳐서 발생하는 오류 수정
 * 2022.08.30   Hwi1993     PK 오류 수정
 * 2022.11.04   HWI1993     [C20220916-000290] [SCM PI] DM 시스템의 AS RTF 정확도 향상을 위한 기능변경 건
 * 2022.11.22   HWI1993     [C20220916-000290] 오류 수정 재배포
 * 2024.02.19   JSSBAE      [E20240214-000835]_[영업마케팅 PI팀] 81번사업부 AS Inv 생성 로직 변경 요청
 * 2024.03.15   JSSBAE      [E20240226-000021]_52주구간 AS INV VIEW 확보
 * 2024.09.26   JSSBAE      [E20240926-001366]_[공급 SCM PI팀] AS 관련 메저 생성 시 SCPSSP RTF간 우선순위 지정(SCP RTF 우선시)
 *                          PR_DM_PLN_MKT_FCST_C_QTY_BALANCE_CREATE에서 기 생성된 RTF_SCP와 SSP_RTF가 겹치는 현상이 발생하여 수정
 * 2024.10.21   JSSBAE      [E20241007-000267]_[공급 SCM PI팀] AS 관련 메저 생성 시 SSP 기존 로직 제거
 *                          82 사업부는 현행과 동일한 개념으로 진행, 81 사업부는 SSP 개념을 모두 제거한 부분으로 수정
 * 2024.12.01   KANG.H.J    [PJ2024-50611] BPS 매출(RTF_SYS_RP Measrue) 전송 시 전 사업부 FROM_SITE_ID 추가
 * 2025.01.13   P.C.I       [E20250113-000270]_[공급/생산 SCM PI팀] 운송중 재고 AS RTF 산출시 적용 요청
 * 2025.01.31   JSSBAE      [E20250120-000036]_[공급/생산 SCM PI팀] AS Inv -> RTF 생성로직 개선 (재고 기반 RTF 산출)
 * 2025.02.05   KANG.H.J    [PJ2025-50017] 소형 매출계획 동기화 개선 - DM_PLN_CFM_MKT_DEMAND_PLAN 동기화
 * 2025.04.08   KANG.H.J    오류 대응 - DM_PLN_CFM_MKT_DEMAND_PLAN PROJECT_CODE 조인시 사업부별 조건처리
 * 2025.04.08   KANG.H.J    [PJ2025-50017] 소형 매출계획 동기화 개선 - DM_PLN_RTF_ALLOCATION 삭제처리
 * 2025.09.09   JSSBAE      [E20250909-000795]_Kangoo 모델 AS INV REQ 값 이상[RTF 미산출)
 * 2026.05.26   JSSBAE      [E20260402-001736]_AS 관련 기능 개선 건
 * 2026.09.18   AJS         40·82 PLANT_SITE_ID, 81·82 END_CUSTOMER 빈값 채움값 ' '·'' → '-' 통일(14자리)
 *==============================================================================================================================================
 *   USAGE : EXEC PR_DM_DNM_CREATE_WS_RTF '82'
 *----------------------------------------------------------------------------------------------------------------------------------------------
 *     - PLANT_SITE_ID/END_CUSTOMER(NOT NULL) : ''->' '(공백), CELL_PROD_SITE_ID '-', ATTRIBUTE10 <> '' -> IS NOT NULL
 *============================================================================================================================================== */
IS

    V_PROGRAM_NAME        VARCHAR2(150 CHAR) := 'PR_DM_DNM_CREATE_WS_RTF';
    V_LOG_TYPE            VARCHAR2(30 CHAR);
    N_LOG_COUNT           NUMBER := 0;
    V_LOG_MESSAGE         VARCHAR2(1000 CHAR);
    V_DESCRIPTION         VARCHAR2(500 CHAR);
    D_EVENT_DATE          DATE;
    N_DELETE_COUNT        NUMBER := 0;
    N_INSERT_COUNT        NUMBER := 0;
    V_CREATED_BY          VARCHAR2(150 CHAR) := 'SYSTEM_WS';

    V_START_YYYYMMDD      VARCHAR2(8 CHAR);  /* 당주 월요일 */
    V_SHIP_START_YYYYMMDD VARCHAR2(8 CHAR);


    I                     NUMBER;
    CNT                   NUMBER;
    SUB_I                 NUMBER;
    SUB_CNT               NUMBER;
    V_ALLOC_I             NUMBER;
    V_ALLOC_CNT           NUMBER;
    V_YYYYMMDD            VARCHAR2(8 CHAR);
    V_INV                 NUMBER(20,10);
    V_RTF                 NUMBER(20,10);
    V_SSP_RTF             NUMBER(20,10);
    V_MKT_FCST            NUMBER(20,10);
    V_MKT_FCST_NET        NUMBER(20,10);
    V_SCM_SITE_ID         VARCHAR2(30 CHAR);
    V_PROJECT_CODE        VARCHAR2(50 CHAR);
    V_ITEM_ID             VARCHAR2(50 CHAR);
    V_ALLOC_SUM_RTF       NUMBER(20,10);
    V_ALLOC_RTF           NUMBER(20,10);

    I_SUB                 NUMBER;
    CNT_SUB               NUMBER;
    V_DIVISION_ID         VARCHAR2(30 CHAR);
    V_DOM_EXP             VARCHAR2(3 CHAR);
    V_FCST_TYPE           VARCHAR2(20 CHAR);
    V_INCOTERMS           VARCHAR2(10 CHAR);
    V_PLANT_SITE_ID       VARCHAR2(30 CHAR);
    V_INV_QTY             NUMBER;

    V_SITE_SEQ            NUMBER;
    V_DATE                VARCHAR2(8 CHAR);
    V_MAX_DATE            VARCHAR2(8 CHAR);
    V_FROM_SITE           VARCHAR2(30 CHAR);
    V_FROM_PLANT          VARCHAR2(30 CHAR);

    V_SUM_REQ_QTY         NUMBER(30,10);
    V_REQ_QTY             NUMBER(30,10);
    V_REM_QTY             NUMBER(30,10);
    I_RCV                 NUMBER;
    CNT_RCV               NUMBER;
    V_INV_ADJ_QTY         NUMBER(30,10);
    V_KEY_VAL             NUMBER;

BEGIN

    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## START OF PROCEDURE ##########';
    V_DESCRIPTION := '@P_DIVISION_ID: ' || P_DIVISION_ID;
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    V_LOG_MESSAGE := NULL;

    BEGIN

        /* 당주 월요일 */
        V_START_YYYYMMDD      := TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7, 'YYYYMMDD');
        V_SHIP_START_YYYYMMDD := TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7, 'YYYYMMDD');

        /* --------------------------------------------------------------------------------------- */

        /* --------------------------------------------------------------------------------------- */
        DELETE FROM GT_PRDM_SSP;
        DELETE FROM GT_PRDM_END_RTF_RAW;
        DELETE FROM GT_PRDM_AS_INV;
        DELETE FROM GT_PRDM_END_RTF_LOOP;
        DELETE FROM GT_PRDM_AS_LOOP;
        DELETE FROM GT_PRDM_RTF;
        DELETE FROM GT_PRDM_RCV;
        DELETE FROM GT_PRDM_RTF_SITE;

        /* --------------------------------------------------------------------------------------- */
        /* 1. 기존 RTF 계열 삭제 ( 고객향 / AS Plant향 ) */
        /* rtf 계열 메저에는 attr10 이 없으므로 생성자(CREATED_BY)를 이용해서 삭제한다. */
        /* --------------------------------------------------------------------------------------- */
        /* 고객향 */
        DELETE FROM DM_PLN_MKT_FCST A
         WHERE A.DIVISION_ID = P_DIVISION_ID
           AND A.CREATED_BY  = V_CREATED_BY
           AND A.YYYYMMDD   >= V_START_YYYYMMDD
           AND A.MEASURE IN ('RTF_SYS_RP', 'RTF_SCP', 'RTF', 'AS_SHIP_PLAN', 'RTF_PR');  /* [PJ2025-50017] RTF_PR 신규 추가 */

        /* AS Plant향 */
        DELETE FROM DM_PLN_MKT_FCST A
         WHERE EXISTS ( SELECT 1
                          FROM SCM_MST_SITE B
                         WHERE A.DIVISION_ID     = B.DIVISION_ID
                           AND A.SCM_SITE_ID     = B.SCM_SITE_ID
                           AND B.OPERATION_GROUP = 'W'
                           AND B.SITE_TYPE       = 'SALES' )
           AND A.DIVISION_ID = P_DIVISION_ID
           AND A.CREATED_BY  = V_CREATED_BY
           AND A.YYYYMMDD   >= V_START_YYYYMMDD
           AND A.MEASURE IN ('RTF_SYS_RP', 'RTF_SCP', 'RTF', 'AS_SHIP_PLAN', 'RTF_PR');

        /* [PJ2025-50017] 소형 매출계획 동기화 : 고객향 */
        DELETE FROM DM_PLN_CFM_MKT_DEMAND_PLAN A
         WHERE A.DIVISION_ID = P_DIVISION_ID
           AND A.CREATED_BY  = V_CREATED_BY
           AND A.YYYYMMDD   >= V_START_YYYYMMDD
           AND A.MEASURE IN ('RTF_SYS_RP', 'RTF_SCP', 'RTF', 'AS_SHIP_PLAN', 'RTF_PR');

        /* [PJ2025-50017] 소형 매출계획 동기화 : AS Plant향 */
        DELETE FROM DM_PLN_CFM_MKT_DEMAND_PLAN A
         WHERE EXISTS ( SELECT 1
                          FROM SCM_MST_SITE B
                         WHERE A.DIVISION_ID     = B.DIVISION_ID
                           AND A.SCM_SITE_ID     = B.SCM_SITE_ID
                           AND B.OPERATION_GROUP = 'W'
                           AND B.SITE_TYPE       = 'SALES' )
           AND A.DIVISION_ID = P_DIVISION_ID
           AND A.CREATED_BY  = V_CREATED_BY
           AND A.YYYYMMDD   >= V_START_YYYYMMDD
           AND A.MEASURE IN ('RTF_SYS_RP', 'RTF_SCP', 'RTF', 'AS_SHIP_PLAN', 'RTF_PR');

        /* --------------------------------------------------------------------------------------- */
        /* Ship Confirm -> GT_PRDM_SSP  ( 최종 RTF 가 아니라서 SSP_RTF 로 넣는다. ) */
        /* --------------------------------------------------------------------------------------- */
        INSERT INTO GT_PRDM_SSP ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE
            , INCOTERMS, MEASURE, PLANT_SITE_ID, AS_SITE, ETA_YYYYMMDD, SHIP_YYYYMMDD, QTY, GUBUN, AS_FROM_PLANT )
        SELECT T0.DIVISION_ID
             , T0.PROJECT_CODE
             , T0.TO_SITE
             , T0.ITEM_ID
             , 'E'
             , T0.FCST_TYPE
             , T1.INCOTERMS
             , 'SSP_RTF'
             , CASE WHEN T0.DIVISION_ID LIKE '81%' THEN T0.FROM_SITE_PLANT_ID ELSE '' END
             , T3.SEGMENT1
             , T0.ETA_DATE
             , T0.YYYYMMDD
             , SUM(T0.QTY)
             , 'CONFIRM'
             , T3.SEGMENT2
          FROM SSP_ANL_SHIP_CONFIRM T0
          JOIN SCP_MST_BOD_N_V T1 ON T0.DIVISION_ID = T1.DIVISION_ID AND T0.BOD_ID = T1.BOD_ID
          JOIN SCP_MST_DISTRIBUTION_ROUTE T2 ON T2.ROUTE_ID = T1.ROUTE_ID
          JOIN SCM_ADM_LOOKUP_MASTER_DETAIL T3 ON T0.FROM_SITE = T3.SEGMENT2 AND T3.LOOKUP_TYPE = 'AS_SITE_PLANT' AND T3.SEGMENT2 <> '-' AND T3.SEGMENT3 = P_DIVISION_ID AND T3.VALID_YN = 'Y'
          JOIN SCM_MST_SITE T4 ON T0.TO_SITE = T4.SCM_SITE_ID AND T0.DIVISION_ID = T4.DIVISION_ID AND T4.SITE_TYPE = 'SALES'
          JOIN SCM_ADM_LOOKUP_MASTER_DETAIL T5 ON T0.FCST_TYPE = T5.SEGMENT1 AND T5.LOOKUP_TYPE = 'SALES_TYPE_CODE2' AND T5.VALID_YN = 'Y'
          JOIN SCM_MST_SITE T6 ON T0.FROM_SITE = T6.SCM_SITE_ID AND T0.DIVISION_ID = T6.DIVISION_ID
         WHERE 1 = 1
           /* [E20250120-000036] 81 사업부인 경우 SHIP_FROZEN 미적용 */
           AND ( T0.YYYYMMDD BETWEEN V_SHIP_START_YYYYMMDD AND CASE WHEN P_DIVISION_ID LIKE '81%' THEN V_SHIP_START_YYYYMMDD ELSE TO_CHAR(TO_DATE(V_SHIP_START_YYYYMMDD, 'YYYYMMDD') + T6.SHIP_FROZEN, 'YYYYMMDD') END
                 OR ( T0.YYYYMMDD < TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7, 'YYYYMMDD')
                      AND T0.ETA_DATE >= TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7, 'YYYYMMDD') )
               )
           AND T0.QTY <> 0
           AND T0.DIVISION_ID = P_DIVISION_ID
           AND T0.FCST_TYPE <> '-'  /* MKT_FCST 없는 경우 */
           AND T0.SHIPMENT_STATUS = 'C'
           AND T0.CHANGE_TYPE = 'C'
           AND T0.ETA_DATE IS NOT NULL
         GROUP BY T0.DIVISION_ID, T0.PROJECT_CODE, T0.TO_SITE, T0.ITEM_ID, T0.FCST_TYPE, T1.INCOTERMS
             , CASE WHEN T0.DIVISION_ID LIKE '81%' THEN T0.FROM_SITE_PLANT_ID ELSE '' END
             , T3.SEGMENT1, T0.ETA_DATE, T0.YYYYMMDD, T3.SEGMENT2;

        /* 소형 DOM_EXP 보정 1 ( 키 + YYYYMMDD 일치 ) */
        MERGE INTO GT_PRDM_SSP A
        USING ( SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.FCST_TYPE, A.INCOTERMS, A.YYYYMMDD
                     , MAX(A.DOM_EXP) AS DOM_EXP
                  FROM DM_PLN_MKT_FCST A
                 WHERE A.DIVISION_ID = P_DIVISION_ID
                   AND A.YYYYMMDD BETWEEN V_START_YYYYMMDD AND TO_CHAR(ADD_MONTHS(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD'), 3), 'YYYYMMDD')
                   AND A.MEASURE IN ('RTF_SCP', 'MKT_FCST')
                 GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.FCST_TYPE, A.INCOTERMS, A.YYYYMMDD ) B
        ON (    B.DIVISION_ID  = A.DIVISION_ID
            AND B.PROJECT_CODE = A.PROJECT_CODE
            AND B.SCM_SITE_ID  = A.SCM_SITE_ID
            AND B.ITEM_ID      = A.ITEM_ID
            AND B.FCST_TYPE    = A.FCST_TYPE
            AND B.INCOTERMS    = A.INCOTERMS
            AND B.YYYYMMDD     = A.ETA_YYYYMMDD )
        WHEN MATCHED THEN UPDATE SET A.DOM_EXP = B.DOM_EXP;

        /* 동일 일자 값 없는 건 : YYYYMMDD 제외 재보정 ( DOM_EXP='E' 인 건만 ) */
        MERGE INTO GT_PRDM_SSP A
        USING ( SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.FCST_TYPE, A.INCOTERMS
                     , MAX(A.DOM_EXP) AS DOM_EXP
                  FROM DM_PLN_MKT_FCST A
                 WHERE A.DIVISION_ID = P_DIVISION_ID
                   AND A.YYYYMMDD BETWEEN V_START_YYYYMMDD AND TO_CHAR(ADD_MONTHS(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD'), 3), 'YYYYMMDD')
                   AND A.MEASURE IN ('RTF_SCP', 'MKT_FCST')
                 GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.FCST_TYPE, A.INCOTERMS ) B
        ON (    B.DIVISION_ID  = A.DIVISION_ID
            AND B.PROJECT_CODE = A.PROJECT_CODE
            AND B.SCM_SITE_ID  = A.SCM_SITE_ID
            AND B.ITEM_ID      = A.ITEM_ID
            AND B.FCST_TYPE    = A.FCST_TYPE
            AND B.INCOTERMS    = A.INCOTERMS )
        WHEN MATCHED THEN UPDATE SET A.DOM_EXP = B.DOM_EXP WHERE A.DOM_EXP = 'E';

        /* --------------------------------------------------------------------------------------- */
        /* 고객향 RTF / MKT FCST -> GT_PRDM_END_RTF_RAW */
        /* [E20241007-000267] 81 사업부는 SSP RTF 미사용. 82/40 만 SSP 구간 생성. */
        /* --------------------------------------------------------------------------------------- */
        IF P_DIVISION_ID IN ('82', '40') THEN
            /* 고객향 RTF INSERT ( FROM SSP, FROM AS SITE ) */
            INSERT INTO GT_PRDM_END_RTF_RAW ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY, FROM_SITE, AS_PLANT )
            SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
                 -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (START)
--                 , A.FCST_TYPE, A.INCOTERMS, 'SSP_RTF', CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '' END, A.ETA_YYYYMMDD
                 , A.FCST_TYPE, A.INCOTERMS, 'SSP_RTF', CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '/' END, A.ETA_YYYYMMDD
                 -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (END)
                 , SUM(A.QTY)
                 , A.AS_SITE, A.AS_FROM_PLANT
              FROM GT_PRDM_SSP A
             GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
                 -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (START)
--                 , A.FCST_TYPE, A.INCOTERMS, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '' END, A.ETA_YYYYMMDD, A.AS_SITE, A.AS_FROM_PLANT;
                 , A.FCST_TYPE, A.INCOTERMS, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '/' END, A.ETA_YYYYMMDD, A.AS_SITE, A.AS_FROM_PLANT;
                 -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (END)
        END IF;

        /* 고객향 MKT FCST INSERT */
        INSERT INTO GT_PRDM_END_RTF_RAW ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY, MF_QTY, RTF_QTY, FROM_SITE, AS_PLANT )
        SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
             , A.FCST_TYPE, A.INCOTERMS, 'MKT_FCST', A.PLANT_SITE_ID, A.YYYYMMDD
             , SUM(A.QTY), SUM(A.QTY), 0, C.SEGMENT1, A.ATTRIBUTE10
          FROM DM_PLN_MKT_FCST A
          /* AS PLANT 정보 */
          JOIN SCM_MST_SITE B ON A.DIVISION_ID = B.DIVISION_ID
                             AND A.ATTRIBUTE10 = B.SCM_SITE_ID
                             AND B.OPERATION_GROUP = 'W'
                             AND B.SITE_TYPE = 'PLANT'
          /* AS SITE 로 변환 */
          JOIN SCM_ADM_LOOKUP_MASTER_DETAIL C ON B.SCM_SITE_ID = C.SEGMENT2 AND B.DIVISION_ID = C.SEGMENT3 AND C.LOOKUP_TYPE = 'AS_SITE_PLANT'
         WHERE A.DIVISION_ID = P_DIVISION_ID
           AND A.MEASURE IN ('MKT_FCST')
           AND A.YYYYMMDD >= V_START_YYYYMMDD
           AND A.ATTRIBUTE10 IS NOT NULL  /* 원본 ATTRIBUTE10 <> '' */
         GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
             , A.FCST_TYPE, A.INCOTERMS, A.PLANT_SITE_ID, A.YYYYMMDD, A.ATTRIBUTE10, C.SEGMENT1
        HAVING SUM(A.QTY) <> 0;  /* 20231124 [SM] 수량0제외 */

        /* #RAW 에 LT 추가 */
        MERGE INTO GT_PRDM_END_RTF_RAW A
        USING ( SELECT FROM_SITE, TO_SITE, INCOTERMS, LT_TOTAL
                  FROM ( SELECT FROM_SITE, TO_SITE, INCOTERMS, LT_TOTAL
                              , ROW_NUMBER() OVER ( PARTITION BY FROM_SITE, TO_SITE, INCOTERMS ORDER BY PRIORITY ) AS PRT
                           FROM SCP_MST_BOD_V
                          WHERE DIVISION_ID = P_DIVISION_ID
                            AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN FROM_YYYYMMDD AND TO_YYYYMMDD )
                 WHERE PRT = 1 ) B
        ON ( A.AS_PLANT = B.FROM_SITE AND A.SCM_SITE_ID = B.TO_SITE AND A.INCOTERMS = B.INCOTERMS )
        WHEN MATCHED THEN UPDATE SET A.LT_DAYS = B.LT_TOTAL;

        /* SEQ ( DENSE_RANK by YYYYMMDD ) */
        MERGE INTO GT_PRDM_END_RTF_RAW A
        USING ( SELECT KEY_VAL
                     , DENSE_RANK() OVER ( PARTITION BY DIVISION_ID, SCM_SITE_ID, PROJECT_CODE, ITEM_ID ORDER BY YYYYMMDD ) AS SEQ
                  FROM GT_PRDM_END_RTF_RAW ) B
        ON ( A.KEY_VAL = B.KEY_VAL )
        WHEN MATCHED THEN UPDATE SET A.SEQ = B.SEQ;

        /* MF_SEQ ( MKT_FCST 한정 DENSE_RANK by YYYYMMDD,QTY ) */
        MERGE INTO GT_PRDM_END_RTF_RAW A
        USING ( SELECT KEY_VAL
                     , DENSE_RANK() OVER ( PARTITION BY DIVISION_ID, SCM_SITE_ID, PROJECT_CODE, ITEM_ID ORDER BY YYYYMMDD, QTY ) AS SEQ
                  FROM GT_PRDM_END_RTF_RAW
                 WHERE MEASURE = 'MKT_FCST' ) B
        ON ( A.KEY_VAL = B.KEY_VAL )
        WHEN MATCHED THEN UPDATE SET A.MF_SEQ = B.SEQ;

        /* --------------------------------------------------------------------------------------- */
        /* 고객향 SITE 재고 루프 ( 도착 SSP RTF 를 입고로 보고 MKT FCST 발생일에 재고가 있으면 RTF 생성 ) */

        /* --------------------------------------------------------------------------------------- */
        INSERT INTO GT_PRDM_END_RTF_LOOP ( SCM_SITE_ID, PROJECT_CODE, ITEM_ID, SEQ )
        SELECT SCM_SITE_ID, PROJECT_CODE, ITEM_ID
             , ROW_NUMBER() OVER ( ORDER BY SCM_SITE_ID, PROJECT_CODE, ITEM_ID ) - 1
          FROM ( SELECT DISTINCT SCM_SITE_ID, PROJECT_CODE, ITEM_ID FROM GT_PRDM_END_RTF_RAW );

        SELECT 0, MAX(SEQ) INTO I, CNT FROM GT_PRDM_END_RTF_LOOP;
        V_SCM_SITE_ID  := NULL;
        V_PROJECT_CODE := NULL;
        V_ITEM_ID      := NULL;

        /* 할당단위별 루프 */
        WHILE I <= CNT LOOP

            SELECT SCM_SITE_ID, PROJECT_CODE, ITEM_ID
              INTO V_SCM_SITE_ID, V_PROJECT_CODE, V_ITEM_ID
              FROM GT_PRDM_END_RTF_LOOP
             WHERE SEQ = I;

            SELECT 1, NVL(MAX(A.SEQ), 0), 0, 0, 0, 0, 0, NULL
              INTO SUB_I, SUB_CNT, V_INV, V_RTF, V_SSP_RTF, V_MKT_FCST, V_MKT_FCST_NET, V_YYYYMMDD
              FROM GT_PRDM_END_RTF_RAW A
             WHERE A.SCM_SITE_ID  = V_SCM_SITE_ID
               AND A.PROJECT_CODE = V_PROJECT_CODE
               AND A.ITEM_ID      = V_ITEM_ID
               AND A.MEASURE IN ('SSP_RTF', 'MKT_FCST');

            /* 단위 내에서 일자별(순번별) 루프 */
            WHILE ( SUB_I <= SUB_CNT ) LOOP

                SELECT SUM(CASE WHEN A.MEASURE = 'SSP_RTF' THEN A.QTY ELSE 0 END)
                     , SUM(CASE WHEN A.MEASURE = 'MKT_FCST' THEN A.QTY ELSE 0 END)
                     , MAX(A.YYYYMMDD)
                  INTO V_SSP_RTF, V_MKT_FCST, V_YYYYMMDD
                  FROM GT_PRDM_END_RTF_RAW A
                 WHERE A.SCM_SITE_ID  = V_SCM_SITE_ID
                   AND A.PROJECT_CODE = V_PROJECT_CODE
                   AND A.ITEM_ID      = V_ITEM_ID
                   AND A.MEASURE IN ('SSP_RTF', 'MKT_FCST')
                   AND A.SEQ = SUB_I;

                /* 당일의 기초재고 및 요청총량 계산 */
                V_INV          := V_INV + NVL(V_SSP_RTF, 0);
                V_MKT_FCST_NET := V_MKT_FCST_NET + NVL(V_MKT_FCST, 0);

                /* 당일에 풀 수 있는 수량 및 재고 정리 */
                IF V_INV >= V_MKT_FCST_NET THEN
                    V_INV          := V_INV - V_MKT_FCST_NET;
                    V_RTF          := V_MKT_FCST_NET;
                    V_MKT_FCST_NET := 0;
                ELSE
                    V_RTF          := V_INV;
                    V_MKT_FCST_NET := V_MKT_FCST_NET - V_INV;
                    V_INV          := 0;
                END IF;

                IF ( V_RTF > 0 ) THEN

                    SELECT 0, 0, MIN(A.SEQ)
                      INTO V_ALLOC_SUM_RTF, V_ALLOC_RTF, V_ALLOC_I
                      FROM GT_PRDM_END_RTF_RAW A
                     WHERE A.SCM_SITE_ID  = V_SCM_SITE_ID
                       AND A.PROJECT_CODE = V_PROJECT_CODE
                       AND A.ITEM_ID      = V_ITEM_ID
                       AND A.MEASURE IN ('MKT_FCST')
                       AND A.SEQ <= SUB_I
                       AND A.RTF_QTY < A.MF_QTY;

                    /* 하나씩 풀면서 V_RTF 숫자에 도달할때까지 넣어준다. */
                    WHILE ( V_ALLOC_SUM_RTF < V_RTF ) LOOP

                        V_ALLOC_RTF := 0;

                        BEGIN
                            SELECT CASE WHEN A.QTY - NVL(A.RTF_QTY, 0) < V_RTF - V_ALLOC_SUM_RTF THEN A.QTY - NVL(A.RTF_QTY, 0)
                                        ELSE V_RTF - V_ALLOC_SUM_RTF END
                              INTO V_ALLOC_RTF
                              FROM GT_PRDM_END_RTF_RAW A
                             WHERE A.SCM_SITE_ID  = V_SCM_SITE_ID
                               AND A.PROJECT_CODE = V_PROJECT_CODE
                               AND A.ITEM_ID      = V_ITEM_ID
                               AND A.MEASURE IN ('MKT_FCST')
                               AND A.SEQ = V_ALLOC_I
                               AND ROWNUM = 1;
                        EXCEPTION
                            WHEN NO_DATA_FOUND THEN EXIT;
                        END;

                        INSERT INTO GT_PRDM_END_RTF_RAW ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY, FROM_SITE, AS_PLANT )
                        SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, 'RTF', PLANT_SITE_ID, V_YYYYMMDD
                             , V_ALLOC_RTF, FROM_SITE, AS_PLANT
                          FROM GT_PRDM_END_RTF_RAW A
                         WHERE A.SCM_SITE_ID  = V_SCM_SITE_ID
                           AND A.PROJECT_CODE = V_PROJECT_CODE
                           AND A.ITEM_ID      = V_ITEM_ID
                           AND A.MEASURE IN ('MKT_FCST')
                           AND A.SEQ = V_ALLOC_I;

                        UPDATE GT_PRDM_END_RTF_RAW
                           SET RTF_QTY = NVL(RTF_QTY, 0) + V_ALLOC_RTF
                         WHERE SCM_SITE_ID  = V_SCM_SITE_ID
                           AND PROJECT_CODE = V_PROJECT_CODE
                           AND ITEM_ID      = V_ITEM_ID
                           AND MEASURE IN ('MKT_FCST')
                           AND SEQ = V_ALLOC_I;

                        V_ALLOC_SUM_RTF := V_ALLOC_SUM_RTF + V_ALLOC_RTF;
                        V_ALLOC_I       := V_ALLOC_I + 1;
                    END LOOP;

                END IF;

                SUB_I := SUB_I + 1;
            END LOOP;

            I := I + 1;
        END LOOP;

        /* --------------------------------------------------------------------------------------- */
        /* [E20240926-001366] SCP RTF 우선 : DM_PLN_MKT_FCST 에 이미 RTF 계열 있는 키는 GT 에서 제거 */
        /* ( SSP RTF 와 SCP RTF 가 중복되는 경우 SCP RTF 로 보여지도록 겹치는 SSP RTF 는 무시 ) */
        /* --------------------------------------------------------------------------------------- */
        DELETE FROM GT_PRDM_END_RTF_RAW R
         WHERE EXISTS ( SELECT 1
                          FROM DM_PLN_MKT_FCST M
                         WHERE M.DIVISION_ID   = R.DIVISION_ID
                           AND M.PROJECT_CODE  = R.PROJECT_CODE
                           AND M.SCM_SITE_ID   = R.SCM_SITE_ID
                           AND M.ITEM_ID       = R.ITEM_ID
                           AND M.DOM_EXP       = R.DOM_EXP
                           AND M.FCST_TYPE     = R.FCST_TYPE
                           AND M.INCOTERMS     = R.INCOTERMS
                           AND M.PLANT_SITE_ID = R.PLANT_SITE_ID
                           AND M.YYYYMMDD      = R.YYYYMMDD
                           AND M.MEASURE IN ('RTF', 'RTF_SCP', 'RTF_SYS_RP', 'RTF_PR') );

        /* --------------------------------------------------------------------------------------- */
        /* 계산된 RTF / 소형 동기화 INSERT ( 82, 40 ) */
        /* --------------------------------------------------------------------------------------- */
        IF P_DIVISION_ID IN ('82', '40') THEN

            /* 계산된 RTF INSERT */
            INSERT INTO DM_PLN_MKT_FCST
                ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP
                , FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD
                , QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
                , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
            SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
                 , A.FCST_TYPE, A.INCOTERMS, B.MEASURE, A.PLANT_SITE_ID, A.YYYYMMDD
                 , SUM(A.QTY)
                 , V_CREATED_BY, SYSDATE, V_CREATED_BY, SYSDATE
                 , '', '', '', '', ''
                 , '', '', '', '', A.AS_PLANT
              FROM GT_PRDM_END_RTF_RAW A
              JOIN ( SELECT 'RTF' AS MEASURE FROM DUAL
                     UNION ALL SELECT 'RTF_SCP' FROM DUAL
                     UNION ALL SELECT 'RTF_SYS_RP' FROM DUAL
                     UNION ALL SELECT 'RTF_PR' FROM DUAL ) B ON 1 = 1  /* [PJ2025-50017] RTF_PR 신규 추가 */
             WHERE A.MEASURE = 'RTF'
             GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
                 , A.FCST_TYPE, A.INCOTERMS, A.PLANT_SITE_ID, A.YYYYMMDD, B.MEASURE, A.AS_PLANT;

            /* [PJ2025-50017] 소형 매출계획 동기화 : 계산된 RTF INSERT ( END_CUSTOMER : 40 만 PROJECT_CODE, 그외 NOT NULL 공백 ) */
            INSERT INTO DM_PLN_CFM_MKT_DEMAND_PLAN
                ( DIVISION_ID, PROJECT_CODE, END_CUSTOMER, SCM_SITE_ID, ITEM_ID, DOM_EXP
                , FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID, YYYYMMDD
                , QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
                , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
            SELECT A.DIVISION_ID, A.PROJECT_CODE
                 -- 2026.09.18 AJS END_CUSTOMER 빈값 채움값 '-' 로 통일 (START)
--                 , CASE WHEN A.DIVISION_ID = '40' THEN A.PROJECT_CODE ELSE ' ' END
                 , CASE WHEN A.DIVISION_ID = '40' THEN A.PROJECT_CODE ELSE '/' END
                 -- 2026.09.18 AJS END_CUSTOMER 빈값 채움값 '-' 로 통일 (END)
                 , A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
                 , A.FCST_TYPE, A.INCOTERMS, B.MEASURE, A.PLANT_SITE_ID, '-', A.YYYYMMDD  /* CELL_PROD_SITE_ID '-' : AS 모델은 SCP 무관 RTF */
                 , SUM(A.QTY)
                 , V_CREATED_BY, SYSDATE, V_CREATED_BY, SYSDATE
                 , '', NULL, '', '', ''
                 , '', '', '', '', A.AS_PLANT
              FROM GT_PRDM_END_RTF_RAW A
              JOIN ( SELECT 'RTF' AS MEASURE FROM DUAL
                     UNION ALL SELECT 'RTF_SCP' FROM DUAL
                     UNION ALL SELECT 'RTF_SYS_RP' FROM DUAL
                     UNION ALL SELECT 'RTF_PR' FROM DUAL ) B ON 1 = 1
             WHERE A.MEASURE = 'RTF'
             GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
                 , A.FCST_TYPE, A.INCOTERMS, A.PLANT_SITE_ID, A.YYYYMMDD, B.MEASURE, A.AS_PLANT;

        END IF;

        /* --------------------------------------------------------------------------------------- */
        /* AS SITE( PLANT )에 SHIPMENT_PLAN 생성 ( 82, 40 ) */
        /* --------------------------------------------------------------------------------------- */
        IF P_DIVISION_ID IN ('82', '40') THEN

            INSERT INTO DM_PLN_MKT_FCST
                ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP
                , FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD
                , QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
                , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
            SELECT A.DIVISION_ID, A.PROJECT_CODE, A.AS_SITE, A.ITEM_ID, MAX(A.DOM_EXP)
                 -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (START)
--                 , MAX(A.FCST_TYPE), MAX(A.INCOTERMS), 'AS_SHIP_PLAN', MAX(CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE ' ' END), A.SHIP_YYYYMMDD
                 , MAX(A.FCST_TYPE), MAX(A.INCOTERMS), 'AS_SHIP_PLAN', MAX(CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '/' END), A.SHIP_YYYYMMDD
                 -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (END)
                 , SUM(A.QTY), V_CREATED_BY, SYSDATE, V_CREATED_BY, SYSDATE
                 , '', '', '', '', ''
                 , '', '', '', '', ''
              FROM GT_PRDM_SSP A
             WHERE A.SHIP_YYYYMMDD >= V_START_YYYYMMDD
             GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.AS_SITE, A.ITEM_ID, A.SHIP_YYYYMMDD;

            /* [PJ2025-50017] 소형 매출계획 동기화 : AS SITE( PLANT )에 SHIPMENT_PLAN 생성 */
            INSERT INTO DM_PLN_CFM_MKT_DEMAND_PLAN
                ( DIVISION_ID, PROJECT_CODE, END_CUSTOMER, SCM_SITE_ID, ITEM_ID, DOM_EXP
                , FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID, YYYYMMDD
                , QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
                , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
            SELECT A.DIVISION_ID, A.PROJECT_CODE
                 -- 2026.09.18 AJS END_CUSTOMER 빈값 채움값 '-' 로 통일 (START)
--                 , CASE WHEN A.DIVISION_ID = '40' THEN A.PROJECT_CODE ELSE ' ' END
                 , CASE WHEN A.DIVISION_ID = '40' THEN A.PROJECT_CODE ELSE '/' END
                 -- 2026.09.18 AJS END_CUSTOMER 빈값 채움값 '-' 로 통일 (END)
                 , A.AS_SITE, A.ITEM_ID, MAX(A.DOM_EXP)
                 -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (START)
--                 , MAX(A.FCST_TYPE), MAX(A.INCOTERMS), 'AS_SHIP_PLAN', MAX(CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE ' ' END), '-', A.SHIP_YYYYMMDD
                 , MAX(A.FCST_TYPE), MAX(A.INCOTERMS), 'AS_SHIP_PLAN', MAX(CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '/' END), '-', A.SHIP_YYYYMMDD
                 -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (END)
                 , SUM(A.QTY), V_CREATED_BY, SYSDATE, V_CREATED_BY, SYSDATE
                 , '', NULL, '', '', ''
                 , '', '', '', '', ''
              FROM GT_PRDM_SSP A
             WHERE A.SHIP_YYYYMMDD >= V_START_YYYYMMDD
             GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.AS_SITE, A.ITEM_ID, A.SHIP_YYYYMMDD;

        END IF;

        /* --------------------------------------------------------------------------------------- */
        /* AS SITE( PLANT )에서 SHIPMENT_PLAN 이용 AS_INV 재계산 -> GT_PRDM_AS_INV */
        /* --------------------------------------------------------------------------------------- */
        INSERT INTO GT_PRDM_AS_INV ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, YYYYMMDD, PLANT_SITE_ID, QTY )
        SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, A.MEASURE, A.YYYYMMDD, A.PLANT_SITE_ID, A.QTY
          FROM DM_PLN_MKT_FCST A
          JOIN SCM_MST_SITE B ON A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID AND B.OPERATION_GROUP = 'W' AND B.SITE_TYPE = 'SALES'
         WHERE A.DIVISION_ID = P_DIVISION_ID
           AND A.MEASURE IN ('AS_In_Plan', 'AS_SHIP_PLAN')
           AND A.YYYYMMDD >= V_START_YYYYMMDD;

        /* 기존 AS_INV 메저 보유행에 SITE_SEQ=1 */
        MERGE INTO GT_PRDM_AS_INV A
        USING ( SELECT DISTINCT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID
                  FROM DM_PLN_MKT_FCST
                 WHERE YYYYMMDD = TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD')
--                 AND MEASURE = 'AS_INV'   --  2026.10.08 AJS
                   AND MEASURE = 'AS_Inv'   --  2026.10.08 AJS
                   AND DIVISION_ID = P_DIVISION_ID ) B
        ON (    A.DIVISION_ID   = B.DIVISION_ID
            AND A.PROJECT_CODE  = B.PROJECT_CODE
            AND A.SCM_SITE_ID   = B.SCM_SITE_ID
            AND A.ITEM_ID       = B.ITEM_ID
            AND A.DOM_EXP       = B.DOM_EXP
            AND A.FCST_TYPE     = B.FCST_TYPE
            AND A.INCOTERMS     = B.INCOTERMS
            AND A.PLANT_SITE_ID = B.PLANT_SITE_ID )
        WHEN MATCHED THEN UPDATE SET A.SITE_SEQ = 1;

        /* 한 SITE,ITEM 에 SITE_SEQ=1 여러개면 조정( 2번째부터 NULL ) */
        MERGE INTO GT_PRDM_AS_INV A
        USING ( SELECT KEY_VAL
                  FROM ( SELECT KEY_VAL
                              , ROW_NUMBER() OVER ( PARTITION BY DIVISION_ID, SCM_SITE_ID, ITEM_ID ORDER BY KEY_VAL ) AS SUB_SEQ
                           FROM GT_PRDM_AS_INV
                          WHERE SITE_SEQ = 1 )
                 WHERE SUB_SEQ <> 1 ) B
        ON ( A.KEY_VAL = B.KEY_VAL )
        WHEN MATCHED THEN UPDATE SET A.SITE_SEQ = NULL;

        /* SITE_SEQ 없는 SITE 조정 ( KEY_VAL DESC 최종 1행 ) */
        MERGE INTO GT_PRDM_AS_INV A
        USING ( SELECT C.KEY_VAL
                  FROM ( SELECT KEY_VAL, DIVISION_ID, SCM_SITE_ID, ITEM_ID
                              , ROW_NUMBER() OVER ( PARTITION BY DIVISION_ID, SCM_SITE_ID, ITEM_ID ORDER BY KEY_VAL DESC ) AS ROW_NUM
                           FROM GT_PRDM_AS_INV ) C
                  JOIN ( SELECT DIVISION_ID, SCM_SITE_ID, ITEM_ID, MIN(SITE_SEQ) AS SITE_SEQ
                           FROM GT_PRDM_AS_INV
                          GROUP BY DIVISION_ID, SCM_SITE_ID, ITEM_ID ) D
                    ON C.DIVISION_ID = D.DIVISION_ID AND C.SCM_SITE_ID = D.SCM_SITE_ID AND C.ITEM_ID = D.ITEM_ID
                 WHERE D.SITE_SEQ IS NULL
                   AND C.ROW_NUM = 1 ) B
        ON ( A.KEY_VAL = B.KEY_VAL )
        WHEN MATCHED THEN UPDATE SET A.SITE_SEQ = 1;

        /* --------------------------------------------------------------------------------------- */
        /* [E20240214-000835] 기초재고 추가 ( 81 / 그 외 분기 ) */
        /* --------------------------------------------------------------------------------------- */
        IF P_DIVISION_ID = '81' THEN

            /* [E20250120-000036] 81 : AS_STORAGE_YN='Y' 재고만, MKT FCST 기준 데이터로 생성 */
            INSERT INTO GT_PRDM_AS_INV ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, YYYYMMDD, PLANT_SITE_ID, QTY, SITE_SEQ, AS_PLANT )
            SELECT B.DIVISION_ID, B.PROJECT_CODE, B.SCM_SITE_ID, B.ITEM_ID, B.DOM_EXP, B.FCST_TYPE, B.INCOTERMS, 'AS_Inv'
                 , TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD'), B.PLANT_SITE_ID
                 , SUM(A.QTY)
                 , B.SEQ
                 , A.AS_PLANT
              FROM ( SELECT A.DIVISION_ID, C.SEGMENT1 AS AS_SITE, A.ITEM_ID, SUM(SCM_QTY) AS QTY, C.SEGMENT2 AS AS_PLANT
                       FROM SSP_DNM_STOCK_C A
                       JOIN SCM_ADM_LOOKUP_MASTER_DETAIL B
                         ON B.SEGMENT1 = A.DIVISION_ID AND B.SEGMENT3 = A.PLANT_ID AND B.SEGMENT4 = A.STORAGE_ID
                        AND B.LOOKUP_TYPE = 'SSP_AS_DIV_SLOC' AND B.VALID_YN = 'Y' AND B.SEGMENT5 = 'Y'  /* AS_STORAGE_YN */
                       JOIN SCM_ADM_LOOKUP_MASTER_DETAIL C ON B.SEGMENT1 = C.SEGMENT3 AND B.SEGMENT2 = C.SEGMENT2 AND C.LOOKUP_TYPE = 'AS_SITE_PLANT' AND C.VALID_YN = 'Y'
                      /* [E20260402-001736] SSP CUTOFF_DATE = 일요일(당주 월요일 -1). DATE 컬럼 = DATE 로 비교(원본 CONVERT(NVARCHAR(10),..,120)). */
                      WHERE A.CUTOFF_DATE = TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') - 1
                        AND A.STOCK_TYPE = 'INVENTORY'
                      GROUP BY A.DIVISION_ID, C.SEGMENT1, A.ITEM_ID, C.SEGMENT2
                     UNION ALL
                     /* [E20250113-000270] NERP 운송중 VMI 재고 제외분 -> INTRANSIT Inventory 적용 */
                     SELECT A.DIVISION_ID, C.SEGMENT1 AS AS_SITE, A.ITEM_ID, SUM(DELIVERY_QTY) AS QTY, C.SEGMENT2 AS AS_PLANT
                       FROM SCM_DNM_INTRANSIT_C A
                       JOIN SCM_ADM_LOOKUP_MASTER_DETAIL B
                         ON B.SEGMENT1 = A.DIVISION_ID AND B.SEGMENT3 = A.PLANT_ID AND B.SEGMENT4 = A.ATTRIBUTE2  /* STORAGE_ID */
                        AND B.LOOKUP_TYPE = 'SSP_AS_DIV_SLOC' AND B.VALID_YN = 'Y' AND B.SEGMENT5 = 'Y'
                       JOIN SCM_ADM_LOOKUP_MASTER_DETAIL C ON B.SEGMENT1 = C.SEGMENT3 AND B.SEGMENT2 = C.SEGMENT2 AND C.LOOKUP_TYPE = 'AS_SITE_PLANT' AND C.VALID_YN = 'Y'
                      /* [E20260402-001736] SCP RESULT_DATE = 일요일. RESULT_DATE 문자열 컬럼 = YYYYMMDD 비교. */
                      WHERE A.RESULT_DATE = TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD')
                        AND A.RESULT_TYPE = 'I'
                      GROUP BY A.DIVISION_ID, C.SEGMENT1, A.ITEM_ID, C.SEGMENT2 ) A
              /* [E20250120-000036] 81, 81_JV 는 AS_IN_PLAN 부재해도 생성 : MKT FCST 기준 + AS_INV 기준 UNION */
              JOIN ( SELECT DISTINCT B.DIVISION_ID, B.PROJECT_CODE, B.FROM_SITE AS SCM_SITE_ID, B.ITEM_ID, B.DOM_EXP, B.FCST_TYPE, B.INCOTERMS, B.PLANT_SITE_ID, B.SEQ
                       FROM ( SELECT DIVISION_ID, FROM_SITE, ITEM_ID, MIN(SEQ) AS MIN_SEQ
                                FROM GT_PRDM_END_RTF_RAW
                               GROUP BY DIVISION_ID, FROM_SITE, ITEM_ID ) A
                       JOIN GT_PRDM_END_RTF_RAW B ON A.DIVISION_ID = B.DIVISION_ID AND A.FROM_SITE = B.FROM_SITE AND A.ITEM_ID = B.ITEM_ID AND A.MIN_SEQ = B.SEQ
                      UNION ALL
                      SELECT DISTINCT B.DIVISION_ID, B.PROJECT_CODE, B.SCM_SITE_ID, B.ITEM_ID, B.DOM_EXP, B.FCST_TYPE, B.INCOTERMS, B.PLANT_SITE_ID, B.SITE_SEQ
                       FROM ( SELECT DIVISION_ID, SCM_SITE_ID, ITEM_ID, MIN(SITE_SEQ) AS MIN_SEQ
                                FROM GT_PRDM_AS_INV
                               GROUP BY DIVISION_ID, SCM_SITE_ID, ITEM_ID ) A
                       JOIN GT_PRDM_AS_INV B ON A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID AND A.ITEM_ID = B.ITEM_ID AND A.MIN_SEQ = B.SITE_SEQ
                    ) B ON A.DIVISION_ID = B.DIVISION_ID AND A.AS_SITE = B.SCM_SITE_ID AND A.ITEM_ID = B.ITEM_ID
             GROUP BY B.DIVISION_ID, B.PROJECT_CODE, B.SCM_SITE_ID, B.ITEM_ID, B.DOM_EXP, B.FCST_TYPE, B.INCOTERMS, B.PLANT_SITE_ID, B.SEQ, A.AS_PLANT;

        ELSE

            INSERT INTO GT_PRDM_AS_INV ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, YYYYMMDD, PLANT_SITE_ID, QTY, SITE_SEQ, AS_PLANT )
            SELECT B.DIVISION_ID, B.PROJECT_CODE, B.SCM_SITE_ID, B.ITEM_ID, B.DOM_EXP, B.FCST_TYPE, B.INCOTERMS, 'AS_Inv'
                 , TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD'), B.PLANT_SITE_ID
                 , SUM(A.QTY)
                 , B.SITE_SEQ, A.AS_PLANT
              FROM ( SELECT A.DIVISION_ID, C.SEGMENT1 AS AS_SITE, A.ITEM_ID, SUM(SCM_QTY) AS QTY, C.SEGMENT2 AS AS_PLANT
                       FROM SSP_DNM_STOCK_C A
                       JOIN SCM_ADM_LOOKUP_MASTER_DETAIL B ON B.SEGMENT1 = A.DIVISION_ID AND B.SEGMENT3 = A.PLANT_ID AND B.SEGMENT4 = A.STORAGE_ID AND B.LOOKUP_TYPE = 'SSP_AS_DIV_SLOC' AND B.VALID_YN = 'Y'
                       JOIN SCM_ADM_LOOKUP_MASTER_DETAIL C ON B.SEGMENT1 = C.SEGMENT3 AND B.SEGMENT2 = C.SEGMENT2 AND C.LOOKUP_TYPE = 'AS_SITE_PLANT' AND C.VALID_YN = 'Y'
                      /* [E20260402-001736] SSP CUTOFF_DATE = 일요일. DATE 컬럼 = DATE 로 비교. */
                      WHERE A.CUTOFF_DATE = TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') - 1
                        AND A.STOCK_TYPE = 'INVENTORY'
                      GROUP BY A.DIVISION_ID, C.SEGMENT1, A.ITEM_ID, C.SEGMENT2
                     UNION ALL
                     /* [E20250113-000270] 운송중(INTRANSIT) 재고 적용 */
                     SELECT A.DIVISION_ID, C.SEGMENT1 AS AS_SITE, A.ITEM_ID, SUM(DELIVERY_QTY) AS QTY, C.SEGMENT2 AS AS_PLANT
                       FROM SCM_DNM_INTRANSIT_C A
                       JOIN SCM_ADM_LOOKUP_MASTER_DETAIL B ON B.SEGMENT1 = A.DIVISION_ID AND B.SEGMENT3 = A.PLANT_ID AND B.SEGMENT4 = A.ATTRIBUTE2 AND B.LOOKUP_TYPE = 'SSP_AS_DIV_SLOC' AND B.VALID_YN = 'Y'
                       JOIN SCM_ADM_LOOKUP_MASTER_DETAIL C ON B.SEGMENT1 = C.SEGMENT3 AND B.SEGMENT2 = C.SEGMENT2 AND C.LOOKUP_TYPE = 'AS_SITE_PLANT' AND C.VALID_YN = 'Y'
                      WHERE A.RESULT_DATE = TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD')
                        AND A.RESULT_TYPE = 'I'
                      GROUP BY A.DIVISION_ID, C.SEGMENT1, A.ITEM_ID, C.SEGMENT2 ) A
              JOIN ( SELECT DISTINCT B.DIVISION_ID, B.PROJECT_CODE, B.SCM_SITE_ID, B.ITEM_ID, B.DOM_EXP, B.FCST_TYPE, B.INCOTERMS, B.PLANT_SITE_ID, B.SITE_SEQ
                       FROM ( SELECT DIVISION_ID, SCM_SITE_ID, ITEM_ID, MIN(SITE_SEQ) AS MIN_SEQ
                                FROM GT_PRDM_AS_INV
                               GROUP BY DIVISION_ID, SCM_SITE_ID, ITEM_ID ) A
                       JOIN GT_PRDM_AS_INV B ON A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID AND A.ITEM_ID = B.ITEM_ID AND A.MIN_SEQ = B.SITE_SEQ
                    ) B ON A.DIVISION_ID = B.DIVISION_ID AND A.AS_SITE = B.SCM_SITE_ID AND A.ITEM_ID = B.ITEM_ID
             GROUP BY B.DIVISION_ID, B.PROJECT_CODE, B.SCM_SITE_ID, B.ITEM_ID, B.DOM_EXP, B.FCST_TYPE, B.INCOTERMS, B.PLANT_SITE_ID, B.SITE_SEQ, A.AS_PLANT;

        END IF;

        /* AS_PLANT 일괄 업데이트 ( ORA-30926 회피 위해 SEGMENT3/SEGMENT1 GROUP BY 로 유일화 ) */
        MERGE INTO GT_PRDM_AS_INV A
        USING ( SELECT SEGMENT3, SEGMENT1, MAX(SEGMENT2) AS SEGMENT2
                  FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                 WHERE LOOKUP_TYPE = 'AS_SITE_PLANT' AND VALID_YN = 'Y'
                 GROUP BY SEGMENT3, SEGMENT1 ) B
        ON ( A.DIVISION_ID = B.SEGMENT3 AND A.SCM_SITE_ID = B.SEGMENT1 )
        WHEN MATCHED THEN UPDATE SET A.AS_PLANT = B.SEGMENT2;

        /* --------------------------------------------------------------------------------------- */
        /* AS PLANT 기준 모델 적재 -> GT_PRDM_AS_LOOP ( SEQ 1부터 연속채번, 원본 IDENTITY(1,1) ) */
        /* --------------------------------------------------------------------------------------- */
        INSERT INTO GT_PRDM_AS_LOOP ( DIVISION_ID, SCM_SITE_ID, ITEM_ID, CALC_START_DATE, FROM_PLANT, SEQ )
        SELECT X.DIVISION_ID, X.SCM_SITE_ID, X.ITEM_ID, X.CALC_START_DATE, X.FROM_PLANT
             , ROW_NUMBER() OVER ( ORDER BY X.DIVISION_ID, X.SCM_SITE_ID, X.ITEM_ID )
          FROM ( SELECT DISTINCT A.DIVISION_ID, A.SCM_SITE_ID, A.ITEM_ID
                      /* [E20250120-000036] 81 사업부는 SHIP_FROZEN 미적용 */
                      , CASE WHEN P_DIVISION_ID LIKE '81%' THEN V_SHIP_START_YYYYMMDD ELSE TO_CHAR(TO_DATE(V_SHIP_START_YYYYMMDD, 'YYYYMMDD') + B.SHIP_FROZEN, 'YYYYMMDD') END AS CALC_START_DATE
                      , C.SEGMENT2 AS FROM_PLANT
                   FROM GT_PRDM_AS_INV A
                   JOIN SCM_MST_SITE B ON A.DIVISION_ID = B.DIVISION_ID AND A.AS_PLANT = B.SCM_SITE_ID
                   JOIN SCM_ADM_LOOKUP_MASTER_DETAIL C ON A.DIVISION_ID = C.SEGMENT3 AND A.SCM_SITE_ID = C.SEGMENT1 AND C.LOOKUP_TYPE = 'AS_SITE_PLANT' AND C.VALID_YN = 'Y'
                  WHERE A.SITE_SEQ = 1 ) X;

        INSERT INTO GT_PRDM_AS_LOOP ( DIVISION_ID, SCM_SITE_ID, ITEM_ID, CALC_START_DATE, FROM_PLANT, SEQ )
        SELECT X.DIVISION_ID, X.SCM_SITE_ID, X.ITEM_ID, X.CALC_START_DATE, X.FROM_PLANT
             , ( SELECT NVL(MAX(SEQ), 0) FROM GT_PRDM_AS_LOOP ) + ROW_NUMBER() OVER ( ORDER BY X.DIVISION_ID, X.SCM_SITE_ID, X.ITEM_ID )
          FROM ( SELECT DISTINCT A.DIVISION_ID, A.SCM_SITE_ID, A.ITEM_ID
                      , CASE WHEN P_DIVISION_ID LIKE '81%' THEN V_SHIP_START_YYYYMMDD ELSE TO_CHAR(TO_DATE(V_SHIP_START_YYYYMMDD, 'YYYYMMDD') + C.SHIP_FROZEN, 'YYYYMMDD') END AS CALC_START_DATE
                      , B.SEGMENT2 AS FROM_PLANT
                   FROM DM_PLN_MKT_FCST A
                   JOIN SCM_ADM_LOOKUP_MASTER_DETAIL B ON A.DIVISION_ID = B.SEGMENT3 AND A.SCM_SITE_ID = B.SEGMENT1 AND B.LOOKUP_TYPE = 'AS_SITE_PLANT' AND B.VALID_YN = 'Y'
                   JOIN SCM_MST_SITE C ON A.DIVISION_ID = C.DIVISION_ID AND B.SEGMENT2 = C.SCM_SITE_ID
                   LEFT OUTER JOIN GT_PRDM_AS_LOOP E ON A.DIVISION_ID = E.DIVISION_ID AND A.SCM_SITE_ID = E.SCM_SITE_ID AND A.ITEM_ID = E.ITEM_ID
                   JOIN ( SELECT DISTINCT A.DIVISION_ID, A.SCM_SITE_ID, A.ITEM_ID, C.SEGMENT2
                            FROM GT_PRDM_AS_INV A
                            JOIN SCM_ADM_LOOKUP_MASTER_DETAIL C ON A.DIVISION_ID = C.SEGMENT3 AND A.SCM_SITE_ID = C.SEGMENT1 AND C.LOOKUP_TYPE = 'AS_SITE_PLANT' AND C.VALID_YN = 'Y'
                         ) F ON A.DIVISION_ID = F.DIVISION_ID AND A.SCM_SITE_ID = F.SCM_SITE_ID AND A.ITEM_ID = F.ITEM_ID
                  WHERE A.DIVISION_ID = P_DIVISION_ID
                    AND A.YYYYMMDD >= V_SHIP_START_YYYYMMDD
                    AND E.DIVISION_ID IS NULL ) X;

        /* --------------------------------------------------------------------------------------- */
        /* #T_AS_INV 일자별 재고 생성 루프 ( 첫 AS_LOOP WHILE ) */
        /* --------------------------------------------------------------------------------------- */
        SELECT 1, COUNT(*) INTO I, CNT FROM GT_PRDM_AS_LOOP;

        WHILE ( I <= CNT ) LOOP

            SELECT DIVISION_ID, SCM_SITE_ID, ITEM_ID
              INTO V_DIVISION_ID, V_SCM_SITE_ID, V_ITEM_ID
              FROM GT_PRDM_AS_LOOP
             WHERE SEQ = I;


            BEGIN
                SELECT PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID
                  INTO V_PROJECT_CODE, V_SCM_SITE_ID, V_ITEM_ID, V_DOM_EXP, V_FCST_TYPE, V_INCOTERMS, V_PLANT_SITE_ID
                  FROM ( SELECT PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID
                           FROM GT_PRDM_AS_INV
                          WHERE DIVISION_ID = V_DIVISION_ID
                            AND SCM_SITE_ID = V_SCM_SITE_ID
                            AND ITEM_ID = V_ITEM_ID
                            AND SITE_SEQ = 1 )
                 WHERE ROWNUM = 1;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN NULL;
            END;

            INSERT INTO GT_PRDM_AS_INV ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, YYYYMMDD, PLANT_SITE_ID, QTY, SITE_SEQ )
            SELECT DISTINCT V_DIVISION_ID, V_PROJECT_CODE, V_SCM_SITE_ID, V_ITEM_ID, V_DOM_EXP, V_FCST_TYPE, V_INCOTERMS, 'AS_Inv', A.BASIS_YYYYMMDD, V_PLANT_SITE_ID
--               , SUM( CASE WHEN B.MEASURE IN ('AS_In_Plan', 'AS_INV') THEN NVL(B.QTY, 0) ELSE NVL(-B.QTY, 0) END ) OVER ( ORDER BY A.BASIS_YYYYMMDD )   --  2026.10.08 AJS
                 , SUM( CASE WHEN B.MEASURE IN ('AS_In_Plan', 'AS_Inv') THEN NVL(B.QTY, 0) ELSE NVL(-B.QTY, 0) END ) OVER ( ORDER BY A.BASIS_YYYYMMDD )   --  2026.10.08 AJS
                 , B.SITE_SEQ
              FROM SCM_SYS_CALENDAR_M A
              LEFT OUTER JOIN GT_PRDM_AS_INV B ON A.BASIS_YYYYMMDD = B.YYYYMMDD
                                              AND B.DIVISION_ID = V_DIVISION_ID
                                              AND B.SCM_SITE_ID = V_SCM_SITE_ID
                                              AND B.ITEM_ID = V_ITEM_ID
             WHERE A.BASIS_YYYYMMDD BETWEEN TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD')
                                        AND TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') + 7*16, 'YYYYMMDD');

            /* 기초재고 일자 중복행 삭제 ( 나중에 넣은 데이터 ) */
            DELETE FROM GT_PRDM_AS_INV A
             WHERE A.YYYYMMDD = TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD')
               AND A.AS_PLANT IS NULL;

            I := I + 1;
        END LOOP;

        /* --------------------------------------------------------------------------------------- */
        /* [E20250909-000795][E20240226-000021] 54주 보완 : SITE_SEQ 없는 AS_Inv 최초일자에 SITE_SEQ=1 */
        /* --------------------------------------------------------------------------------------- */
        MERGE INTO GT_PRDM_AS_INV A
        USING ( SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, MIN(YYYYMMDD) AS YYYYMMDD
                  FROM GT_PRDM_AS_INV C
                 WHERE SITE_SEQ IS NULL
                   AND MEASURE = 'AS_Inv'
                   AND NOT EXISTS ( SELECT 1 FROM GT_PRDM_AS_INV D
                                     WHERE D.MEASURE = 'AS_Inv' AND D.SITE_SEQ = 1
                                       AND C.DIVISION_ID = D.DIVISION_ID AND C.SCM_SITE_ID = D.SCM_SITE_ID AND C.ITEM_ID = D.ITEM_ID )
                 GROUP BY DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID ) B
        ON (    A.DIVISION_ID   = B.DIVISION_ID
            AND A.PROJECT_CODE  = B.PROJECT_CODE
            AND A.SCM_SITE_ID   = B.SCM_SITE_ID
            AND A.ITEM_ID       = B.ITEM_ID
            AND A.DOM_EXP       = B.DOM_EXP
            AND A.FCST_TYPE     = B.FCST_TYPE
            AND A.INCOTERMS     = B.INCOTERMS
            AND A.PLANT_SITE_ID = B.PLANT_SITE_ID
            AND A.YYYYMMDD      = B.YYYYMMDD )
        WHEN MATCHED THEN UPDATE SET A.SITE_SEQ = 1 WHERE A.MEASURE = 'AS_Inv';

        /* --------------------------------------------------------------------------------------- */
        /* 받는 Site 들에 RTF 생성 ( SSP 확정구간 이후 ) : MKT FCST 취합 -> GT_PRDM_RTF */
        /* --------------------------------------------------------------------------------------- */
        INSERT INTO GT_PRDM_RTF ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, YYYYMMDD, PLANT_SITE_ID, QTY, FROM_PLANT, ETD_DATE, SITE_SEQ )
        SELECT B.DIVISION_ID, B.PROJECT_CODE, B.SCM_SITE_ID, B.ITEM_ID, B.DOM_EXP, B.FCST_TYPE, B.INCOTERMS, B.MEASURE, B.YYYYMMDD, B.PLANT_SITE_ID, B.QTY
             , A.FROM_SITE, TO_CHAR(TO_DATE(B.YYYYMMDD, 'YYYYMMDD') - A.LT_TOTAL, 'YYYYMMDD')
             , ROW_NUMBER() OVER ( PARTITION BY B.DIVISION_ID, A.FROM_SITE, B.ITEM_ID, B.YYYYMMDD ORDER BY B.SCM_SITE_ID )
          FROM ( SELECT A.SEGMENT2 AS FROM_SITE, B.TO_SITE, B.LT_TOTAL, ROW_NUMBER() OVER ( PARTITION BY B.DIVISION_ID, B.FROM_SITE, B.TO_SITE ORDER BY B.PRIORITY ) AS BOD_SEQ
                   FROM SCM_ADM_LOOKUP_MASTER_DETAIL A
                   JOIN SCP_MST_BOD_N_V B ON A.SEGMENT2 = B.FROM_SITE AND B.DIVISION_ID = P_DIVISION_ID AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN B.FROM_YYYYMMDD AND B.TO_YYYYMMDD
                   JOIN SCM_MST_SITE C ON B.TO_SITE = C.SCM_SITE_ID AND C.SITE_TYPE = 'SALES' AND C.VALID_YN = 'Y' AND C.DIVISION_ID = P_DIVISION_ID
                  WHERE A.LOOKUP_TYPE = 'AS_SITE_PLANT' AND A.SEGMENT3 = P_DIVISION_ID AND A.VALID_YN = 'Y' ) A
          JOIN DM_PLN_MKT_FCST B ON A.TO_SITE = B.SCM_SITE_ID AND B.MEASURE = 'MKT_FCST' AND B.YYYYMMDD >= V_START_YYYYMMDD
                                AND A.FROM_SITE = B.ATTRIBUTE10 AND B.DIVISION_ID = P_DIVISION_ID
          JOIN SCM_MST_SITE C ON A.FROM_SITE = C.SCM_SITE_ID AND C.DIVISION_ID = P_DIVISION_ID
         WHERE A.BOD_SEQ = 1
           /* [E20250120-000036] 81 사업부는 SHIP_FROZEN 미적용 */
           AND B.YYYYMMDD > CASE WHEN P_DIVISION_ID LIKE '81%' THEN V_SHIP_START_YYYYMMDD ELSE TO_CHAR(TO_DATE(V_SHIP_START_YYYYMMDD, 'YYYYMMDD') + C.SHIP_FROZEN, 'YYYYMMDD') END
           AND B.QTY <> 0;

        UPDATE GT_PRDM_RTF A
           SET A.ALLOC_SCD_RTF = CASE WHEN A.YYYYMMDD > NVL( ( SELECT MAX(YYYYMMDD)
                                                                 FROM GT_PRDM_END_RTF_RAW E
                                                                WHERE E.MEASURE IN ('RTF', 'SSP_RTF')
                                                                  AND E.DIVISION_ID = A.DIVISION_ID
                                                                  AND E.SCM_SITE_ID = A.SCM_SITE_ID ), '19000101' )
                                      THEN 'Y' ELSE 'N' END;


        /* MAX[ 출발지의 확정구간 + 도착지 BOD LT 적용일자, 도착지의 SSP_RTF ] */
        INSERT INTO GT_PRDM_RTF_SITE ( FROM_SITE, SCM_SITE_ID, MAX_YMD )
        SELECT A.FROM_SITE, A.SCM_SITE_ID
             , CASE WHEN NVL(D.MAX_YMD, '19000101') > CASE WHEN P_DIVISION_ID LIKE '81%' THEN TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') + NVL(C.LT_TOTAL, 0), 'YYYYMMDD')
                                                           ELSE TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') + NVL(B.SHIP_FROZEN, 0) + NVL(C.LT_TOTAL, 0), 'YYYYMMDD') END
                    THEN D.MAX_YMD
                    ELSE CASE WHEN P_DIVISION_ID LIKE '81%' THEN TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') + NVL(C.LT_TOTAL, 0), 'YYYYMMDD')
                              ELSE TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') + NVL(B.SHIP_FROZEN, 0) + NVL(C.LT_TOTAL, 0), 'YYYYMMDD') END
               END
          FROM ( SELECT DISTINCT FROM_SITE, SCM_SITE_ID, AS_PLANT FROM GT_PRDM_END_RTF_RAW ) A
          JOIN SCM_MST_SITE B ON A.AS_PLANT = B.SCM_SITE_ID AND B.DIVISION_ID = P_DIVISION_ID
          JOIN ( SELECT FROM_SITE, TO_SITE, LT_TOTAL, ROW_NUMBER() OVER ( PARTITION BY FROM_SITE, TO_SITE, INCOTERMS ORDER BY PRIORITY ) AS PRT
                   FROM SCP_MST_BOD_N_V
                  WHERE DIVISION_ID = P_DIVISION_ID AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN FROM_YYYYMMDD AND TO_YYYYMMDD ) C
            ON A.AS_PLANT = C.FROM_SITE AND A.SCM_SITE_ID = C.TO_SITE AND C.PRT = 1
          LEFT OUTER JOIN ( SELECT FROM_SITE, SCM_SITE_ID, MAX(YYYYMMDD) AS MAX_YMD
                              FROM GT_PRDM_END_RTF_RAW
                             WHERE MEASURE = 'RTF'
                             GROUP BY FROM_SITE, SCM_SITE_ID ) D
            ON A.FROM_SITE = D.FROM_SITE AND A.SCM_SITE_ID = D.SCM_SITE_ID;

        MERGE INTO GT_PRDM_END_RTF_RAW A
        USING ( SELECT FROM_SITE, SCM_SITE_ID, MAX(MAX_YMD) AS MAX_YMD
                  FROM GT_PRDM_RTF_SITE
                 GROUP BY FROM_SITE, SCM_SITE_ID ) B
        ON ( A.SCM_SITE_ID = B.SCM_SITE_ID AND A.FROM_SITE = B.FROM_SITE )
        WHEN MATCHED THEN UPDATE SET A.SCD_ALLOC_START_DATE = B.MAX_YMD;

        UPDATE GT_PRDM_END_RTF_RAW
           SET LT_YYYYMMDD = TO_CHAR(TO_DATE(YYYYMMDD, 'YYYYMMDD') - NVL(LT_DAYS, 0), 'YYYYMMDD')
         WHERE MEASURE = 'MKT_FCST';

        /* --------------------------------------------------------------------------------------- */


        /* --------------------------------------------------------------------------------------- */
        SELECT 1, COUNT(*) INTO I, CNT FROM GT_PRDM_AS_LOOP;

        WHILE ( I <= CNT ) LOOP

            SELECT A.DIVISION_ID, A.FROM_PLANT, A.SCM_SITE_ID, A.ITEM_ID, TRUNC(NVL(B.QTY, 0)), A.CALC_START_DATE
                 , 0
                 , TO_CHAR(TO_DATE(V_SHIP_START_YYYYMMDD, 'YYYYMMDD') + 7*82, 'YYYYMMDD')  /* [E20250909-000795] 54 -> 82 */
                 , 0, 0
              INTO V_DIVISION_ID, V_FROM_PLANT, V_FROM_SITE, V_ITEM_ID, V_INV_QTY, V_DATE
                 , V_SUM_REQ_QTY
                 , V_MAX_DATE
                 , V_INV_ADJ_QTY, V_SUM_REQ_QTY
              FROM GT_PRDM_AS_LOOP A
              LEFT OUTER JOIN GT_PRDM_AS_INV B ON A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID AND A.ITEM_ID = B.ITEM_ID
                   AND B.YYYYMMDD = TO_CHAR(TO_DATE(A.CALC_START_DATE, 'YYYYMMDD') - 1, 'YYYYMMDD')
--                 AND B.MEASURE = 'AS_INV'   --  2026.10.08 AJS
                   AND B.MEASURE = 'AS_Inv'   --  2026.10.08 AJS
             WHERE A.SEQ = I;

            /* 비축용 사이트 기준 일자별 나눠주기 */
            WHILE ( V_DATE <= V_MAX_DATE ) LOOP

                /* 재고는 V_DATE 전날 재고이므로 당일 입고 감안 */
                SELECT V_INV_QTY + NVL(SUM(QTY), 0)
                  INTO V_INV_QTY
                  FROM GT_PRDM_AS_INV
                 WHERE MEASURE = 'AS_In_Plan'
                   AND DIVISION_ID = V_DIVISION_ID
                   AND SCM_SITE_ID = V_FROM_SITE
                   AND ITEM_ID = V_ITEM_ID
                   AND YYYYMMDD = V_DATE;
                V_INV_QTY := TRUNC(V_INV_QTY);

                SELECT NVL(SUM(NVL(MF_QTY, 0) - NVL(RTF_QTY, 0)), 0)
                  INTO V_SUM_REQ_QTY
                  FROM GT_PRDM_END_RTF_RAW
                 WHERE AS_PLANT = V_FROM_PLANT
                   AND ITEM_ID = V_ITEM_ID
                   AND DIVISION_ID = V_DIVISION_ID
                   AND LT_YYYYMMDD <= V_DATE
                   AND MEASURE = 'MKT_FCST'
                   AND NVL(MF_QTY, 0) > NVL(RTF_QTY, 0);

                /* 재고보다 요청수량이 적으면 요청만큼 생성 */
                IF ( V_SUM_REQ_QTY <= V_INV_QTY ) THEN

                    INSERT INTO GT_PRDM_AS_INV ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, YYYYMMDD, PLANT_SITE_ID, QTY, SITE_SEQ, FROM_SITE, ADD_YN )
                    SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, 'RTF_SCP'
                         , TO_CHAR(TO_DATE(V_DATE, 'YYYYMMDD') + NVL(LT_DAYS, 0), 'YYYYMMDD'), A.PLANT_SITE_ID, SUM(NVL(MF_QTY, 0) - NVL(RTF_QTY, 0)), NULL, A.AS_PLANT, 'Y'
                      FROM GT_PRDM_END_RTF_RAW A
                     WHERE A.AS_PLANT = V_FROM_PLANT
                       AND A.ITEM_ID = V_ITEM_ID
                       AND A.DIVISION_ID = V_DIVISION_ID
                       AND LT_YYYYMMDD <= V_DATE
                       AND MEASURE = 'MKT_FCST'
                       AND NVL(MF_QTY, 0) > NVL(RTF_QTY, 0)
                     GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS
                         , A.PLANT_SITE_ID, A.AS_PLANT, TO_CHAR(TO_DATE(V_DATE, 'YYYYMMDD') + NVL(LT_DAYS, 0), 'YYYYMMDD');

                    UPDATE GT_PRDM_END_RTF_RAW A
                       SET RTF_QTY = MF_QTY
                     WHERE A.AS_PLANT = V_FROM_PLANT
                       AND A.ITEM_ID = V_ITEM_ID
                       AND A.DIVISION_ID = V_DIVISION_ID
                       AND LT_YYYYMMDD <= V_DATE
                       AND MEASURE = 'MKT_FCST'
                       AND NVL(MF_QTY, 0) > NVL(RTF_QTY, 0);

                    V_INV_QTY := TRUNC(V_INV_QTY - V_SUM_REQ_QTY);

                ELSE  /* 재고가 적으면 배분 */

                    DELETE FROM GT_PRDM_RCV;

                    INSERT INTO GT_PRDM_RCV ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, YYYYMMDD, PLANT_SITE_ID, QTY, FROM_SITE, ETD_DATE, SITE_SEQ, RTF_RAW_KEY_VAL )
                    SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE
                         , TO_CHAR(TO_DATE(V_DATE, 'YYYYMMDD') + NVL(LT_DAYS, 0), 'YYYYMMDD'), PLANT_SITE_ID
                         , NVL(MF_QTY, 0) - NVL(RTF_QTY, 0)
                         , AS_PLANT, V_DATE
                         , ROW_NUMBER() OVER ( ORDER BY A.YYYYMMDD, A.SCM_SITE_ID )
                         , KEY_VAL
                      FROM GT_PRDM_END_RTF_RAW A
                     WHERE A.AS_PLANT = V_FROM_PLANT
                       AND A.ITEM_ID = V_ITEM_ID
                       AND A.DIVISION_ID = V_DIVISION_ID
                       AND LT_YYYYMMDD <= V_DATE
                       AND MEASURE = 'MKT_FCST'
                       AND NVL(MF_QTY, 0) > NVL(RTF_QTY, 0);

                    SELECT 1, COUNT(*) INTO I_RCV, CNT_RCV FROM GT_PRDM_RCV;

                    WHILE ( I_RCV <= CNT_RCV AND V_INV_QTY > 0 ) LOOP

                        SELECT QTY, RTF_RAW_KEY_VAL INTO V_REQ_QTY, V_KEY_VAL
                          FROM GT_PRDM_RCV
                         WHERE SITE_SEQ = I_RCV;

                        /* 할당 가능한 수량이면 할당하고 다음 SITE 로 */
                        INSERT INTO GT_PRDM_AS_INV ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, YYYYMMDD, PLANT_SITE_ID, QTY, SITE_SEQ, FROM_SITE, ADD_YN )
                        SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, 'RTF_SCP'
                             , A.YYYYMMDD, A.PLANT_SITE_ID
                             , SUM( CASE WHEN V_REQ_QTY <= V_INV_QTY THEN V_REQ_QTY ELSE V_INV_QTY END )
                             , A.SITE_SEQ, A.FROM_SITE, 'Y'
                          FROM GT_PRDM_RCV A
                         WHERE SITE_SEQ = I_RCV
                         GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS
                             , A.YYYYMMDD, A.PLANT_SITE_ID, A.SITE_SEQ, A.FROM_SITE;

                        UPDATE GT_PRDM_END_RTF_RAW
                           SET RTF_QTY = RTF_QTY + CASE WHEN V_REQ_QTY <= V_INV_QTY THEN V_REQ_QTY ELSE V_INV_QTY END
                         WHERE KEY_VAL = V_KEY_VAL;

                        V_INV_QTY := TRUNC( CASE WHEN V_REQ_QTY <= V_INV_QTY THEN V_INV_QTY - V_REQ_QTY ELSE 0 END );

                        I_RCV := I_RCV + 1;
                    END LOOP;

                END IF;

                /* Inv Insert / Update */
                UPDATE GT_PRDM_AS_INV
                   SET QTY = V_INV_QTY
                 WHERE DIVISION_ID = V_DIVISION_ID
                   AND SCM_SITE_ID = V_FROM_SITE
                   AND ITEM_ID = V_ITEM_ID
                   AND YYYYMMDD = V_DATE
                   AND MEASURE = 'AS_Inv';

                IF SQL%ROWCOUNT = 0 THEN
                    INSERT INTO GT_PRDM_AS_INV ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, YYYYMMDD, PLANT_SITE_ID, QTY, SITE_SEQ )
                    SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, 'AS_Inv', V_DATE, A.PLANT_SITE_ID
                         , V_INV_QTY, 1
                      FROM GT_PRDM_AS_INV A
                     WHERE A.DIVISION_ID = V_DIVISION_ID
                       AND A.SCM_SITE_ID = V_FROM_SITE
                       AND A.ITEM_ID = V_ITEM_ID
                       AND A.MEASURE = 'AS_Inv'
                       AND A.SITE_SEQ = 1
                       AND ROWNUM = 1;
                END IF;

                V_DATE := TO_CHAR(TO_DATE(V_DATE, 'YYYYMMDD') + 1, 'YYYYMMDD');

            END LOOP;

            I := I + 1;
        END LOOP;


        DELETE FROM GT_PRDM_AS_INV WHERE YYYYMMDD < V_START_YYYYMMDD;

        /* --------------------------------------------------------------------------------------- */
        /* 결과 INSERT : DM_PLN_MKT_FCST ( AS_Inv + 8주 이후 RTF ) */
        /* --------------------------------------------------------------------------------------- */
        DELETE FROM DM_PLN_MKT_FCST A
         WHERE EXISTS ( SELECT 1 FROM SCM_ADM_LOOKUP_MASTER_DETAIL B
                         WHERE A.DIVISION_ID = B.SEGMENT3 AND A.SCM_SITE_ID = B.SEGMENT1
                           AND B.LOOKUP_TYPE = 'AS_SITE_PLANT' AND B.VALID_YN = 'Y' )
           AND A.DIVISION_ID = P_DIVISION_ID
           AND A.MEASURE = 'AS_Inv'
           AND A.YYYYMMDD >= V_START_YYYYMMDD;

        INSERT INTO DM_PLN_MKT_FCST
            ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP
            , FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD
            , QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
            , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
            , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
        SELECT DISTINCT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
             -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (START)
--             , A.FCST_TYPE, A.INCOTERMS, A.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE ' ' END, A.YYYYMMDD
             , A.FCST_TYPE, A.INCOTERMS, A.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '/' END, A.YYYYMMDD
             -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (END)
             , A.QTY, V_CREATED_BY, SYSDATE, V_CREATED_BY, SYSDATE
             , '', '', '', '', ''
             , '', '', '', '', ''
          FROM GT_PRDM_AS_INV A
         WHERE MEASURE = 'AS_Inv';


        INSERT INTO DM_PLN_MKT_FCST
            ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP
            , FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD
            , QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
            , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
            , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
        SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
             , A.FCST_TYPE, A.INCOTERMS, A.MEASURE, A.PLANT_SITE_ID, A.YYYYMMDD
             , A.QTY, A.CREATED_BY, A.CREATION_DATE, A.LAST_UPDATED_BY, A.LAST_UPDATE_DATE
             , A.ATTRIBUTE1, A.ATTRIBUTE2, A.ATTRIBUTE3, A.ATTRIBUTE4, A.ATTRIBUTE5
             , A.ATTRIBUTE6, A.ATTRIBUTE7, A.ATTRIBUTE8, A.ATTRIBUTE9, A.ATTRIBUTE10
          FROM ( SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
                      -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (START)
--                      , A.FCST_TYPE, A.INCOTERMS, B.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE ' ' END AS PLANT_SITE_ID, A.YYYYMMDD
                      , A.FCST_TYPE, A.INCOTERMS, B.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '/' END AS PLANT_SITE_ID, A.YYYYMMDD
                      -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (END)
                      , SUM(A.QTY) AS QTY, V_CREATED_BY AS CREATED_BY, SYSDATE AS CREATION_DATE, V_CREATED_BY AS LAST_UPDATED_BY, SYSDATE AS LAST_UPDATE_DATE
                      , '' AS ATTRIBUTE1, '' AS ATTRIBUTE2, '' AS ATTRIBUTE3, '' AS ATTRIBUTE4, '' AS ATTRIBUTE5
                      , '' AS ATTRIBUTE6, '' AS ATTRIBUTE7, '' AS ATTRIBUTE8, '' AS ATTRIBUTE9, A.FROM_SITE AS ATTRIBUTE10
                   FROM GT_PRDM_AS_INV A
                   JOIN ( SELECT 'RTF' AS MEASURE FROM DUAL
                          UNION ALL SELECT 'RTF_SCP' FROM DUAL
                          UNION ALL SELECT 'RTF_SYS_RP' FROM DUAL
                          UNION ALL SELECT 'RTF_PR' FROM DUAL ) B ON 1 = 1
                  WHERE A.ADD_YN = 'Y' AND A.MEASURE = 'RTF_SCP'
                  GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
                      -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (START)
--                      , A.FCST_TYPE, A.INCOTERMS, B.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE ' ' END, A.YYYYMMDD, A.FROM_SITE ) A
                      , A.FCST_TYPE, A.INCOTERMS, B.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '/' END, A.YYYYMMDD, A.FROM_SITE ) A
                      -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (END)
          LEFT OUTER JOIN DM_PLN_MKT_FCST B
            ON A.DIVISION_ID = B.DIVISION_ID
           AND A.PROJECT_CODE = B.PROJECT_CODE
           AND A.SCM_SITE_ID = B.SCM_SITE_ID
           AND A.ITEM_ID = B.ITEM_ID
           AND A.DOM_EXP = B.DOM_EXP
           AND A.FCST_TYPE = B.FCST_TYPE
           AND A.INCOTERMS = B.INCOTERMS
           AND A.MEASURE = B.MEASURE
           AND A.YYYYMMDD = B.YYYYMMDD
           AND A.PLANT_SITE_ID = B.PLANT_SITE_ID
         WHERE B.DIVISION_ID IS NULL;

        /* --------------------------------------------------------------------------------------- */
        /* [PJ2025-50017] 결과 INSERT : DM_PLN_CFM_MKT_DEMAND_PLAN ( AS_Inv + 8주 이후 RTF ) */
        /* --------------------------------------------------------------------------------------- */
        DELETE FROM DM_PLN_CFM_MKT_DEMAND_PLAN A
         WHERE EXISTS ( SELECT 1 FROM SCM_ADM_LOOKUP_MASTER_DETAIL B
                         WHERE A.DIVISION_ID = B.SEGMENT3 AND A.SCM_SITE_ID = B.SEGMENT1
                           AND B.LOOKUP_TYPE = 'AS_SITE_PLANT' AND B.VALID_YN = 'Y' )
           AND A.DIVISION_ID = P_DIVISION_ID
           AND A.MEASURE = 'AS_Inv'
           AND A.YYYYMMDD >= V_START_YYYYMMDD;

        INSERT INTO DM_PLN_CFM_MKT_DEMAND_PLAN
            ( DIVISION_ID, PROJECT_CODE, END_CUSTOMER, SCM_SITE_ID, ITEM_ID, DOM_EXP
            , FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID, YYYYMMDD
            , QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
            , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
            , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
        SELECT DISTINCT A.DIVISION_ID, A.PROJECT_CODE
             -- 2026.09.18 AJS END_CUSTOMER 빈값 채움값 '-' 로 통일 (START)
--             , CASE WHEN A.DIVISION_ID = '40' THEN A.PROJECT_CODE ELSE ' ' END
             , CASE WHEN A.DIVISION_ID = '40' THEN A.PROJECT_CODE ELSE '/' END
             -- 2026.09.18 AJS END_CUSTOMER 빈값 채움값 '-' 로 통일 (END)
             , A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
             -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (START)
--             , A.FCST_TYPE, A.INCOTERMS, A.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE ' ' END, '-', A.YYYYMMDD
             , A.FCST_TYPE, A.INCOTERMS, A.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '/' END, '-', A.YYYYMMDD
             -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (END)
             , A.QTY, V_CREATED_BY, SYSDATE, V_CREATED_BY, SYSDATE
             , '', NULL, '', '', ''
             , '', '', '', '', ''
          FROM GT_PRDM_AS_INV A
         WHERE MEASURE = 'AS_Inv';


        INSERT INTO DM_PLN_CFM_MKT_DEMAND_PLAN
            ( DIVISION_ID, PROJECT_CODE, END_CUSTOMER, SCM_SITE_ID, ITEM_ID, DOM_EXP
            , FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID, YYYYMMDD
            , QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
            , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
            , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
        SELECT A.DIVISION_ID, A.PROJECT_CODE, A.END_CUSTOMER
             , A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
             , A.FCST_TYPE, A.INCOTERMS, A.MEASURE, A.PLANT_SITE_ID, A.CELL_PROD_SITE_ID, A.YYYYMMDD
             , A.QTY, A.CREATED_BY, A.CREATION_DATE, A.LAST_UPDATED_BY, A.LAST_UPDATE_DATE
             , A.ATTRIBUTE1, A.ATTRIBUTE2, A.ATTRIBUTE3, A.ATTRIBUTE4, A.ATTRIBUTE5
             , A.ATTRIBUTE6, A.ATTRIBUTE7, A.ATTRIBUTE8, A.ATTRIBUTE9, A.ATTRIBUTE10
          FROM ( SELECT A.DIVISION_ID, A.PROJECT_CODE
                      -- 2026.09.18 AJS END_CUSTOMER 빈값 채움값 '-' 로 통일 (START)
--                      , CASE WHEN A.DIVISION_ID = '40' THEN A.PROJECT_CODE ELSE ' ' END AS END_CUSTOMER
                      , CASE WHEN A.DIVISION_ID = '40' THEN A.PROJECT_CODE ELSE '/' END AS END_CUSTOMER
                      -- 2026.09.18 AJS END_CUSTOMER 빈값 채움값 '-' 로 통일 (END)
                      , A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
                      -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (START)
--                      , A.FCST_TYPE, A.INCOTERMS, B.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE ' ' END AS PLANT_SITE_ID
                      , A.FCST_TYPE, A.INCOTERMS, B.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '/' END AS PLANT_SITE_ID
                      -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (END)
                      , '-' AS CELL_PROD_SITE_ID, A.YYYYMMDD
                      , SUM(A.QTY) AS QTY, V_CREATED_BY AS CREATED_BY, SYSDATE AS CREATION_DATE, V_CREATED_BY AS LAST_UPDATED_BY, SYSDATE AS LAST_UPDATE_DATE
                      , '' AS ATTRIBUTE1, NULL AS ATTRIBUTE2, '' AS ATTRIBUTE3, '' AS ATTRIBUTE4, '' AS ATTRIBUTE5
                      , '' AS ATTRIBUTE6, '' AS ATTRIBUTE7, '' AS ATTRIBUTE8, '' AS ATTRIBUTE9, A.FROM_SITE AS ATTRIBUTE10
                   FROM GT_PRDM_AS_INV A
                   JOIN ( SELECT 'RTF' AS MEASURE FROM DUAL
                          UNION ALL SELECT 'RTF_SCP' FROM DUAL
                          UNION ALL SELECT 'RTF_SYS_RP' FROM DUAL
                          UNION ALL SELECT 'RTF_PR' FROM DUAL ) B ON 1 = 1
                  WHERE A.ADD_YN = 'Y' AND A.MEASURE = 'RTF_SCP'
                  GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
                      -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (START)
--                      , A.FCST_TYPE, A.INCOTERMS, B.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE ' ' END, A.YYYYMMDD, A.FROM_SITE ) A
                      , A.FCST_TYPE, A.INCOTERMS, B.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '/' END, A.YYYYMMDD, A.FROM_SITE ) A
                      -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (END)
          LEFT OUTER JOIN DM_PLN_CFM_MKT_DEMAND_PLAN B
            ON A.DIVISION_ID = B.DIVISION_ID
           AND A.PROJECT_CODE = ( CASE WHEN B.DIVISION_ID = '40' THEN B.END_CUSTOMER ELSE B.PROJECT_CODE END )
           AND A.SCM_SITE_ID = B.SCM_SITE_ID
           AND A.ITEM_ID = B.ITEM_ID
           AND A.DOM_EXP = B.DOM_EXP
           AND A.FCST_TYPE = B.FCST_TYPE
           AND A.INCOTERMS = B.INCOTERMS
           AND A.MEASURE = B.MEASURE
           AND A.YYYYMMDD = B.YYYYMMDD
           AND A.PLANT_SITE_ID = B.PLANT_SITE_ID
         WHERE B.DIVISION_ID IS NULL;

        COMMIT;

    EXCEPTION
        WHEN OTHERS THEN
            ROLLBACK;
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := '@P_DIVISION_ID: ' || P_DIVISION_ID || ' / ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
            D_EVENT_DATE  := SYSDATE;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE
                , V_DESCRIPTION, TO_CHAR(SQLCODE), SUBSTR(SQLERRM, 1, 1000), SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 1000));
            RAISE;
    END;


    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END OF PROCEDURE ##########';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

END PR_DM_DNM_CREATE_WS_RTF;

PROCEDURE         "PR_DM_DNM_EDI_CALLOFF" 
/* ============================================================
 * Program ID   : PR_DM_DNM_EDI_CALLOFF
 * Description  : BMW / AUDI등 EDI 정보 I/F
 *                XIF_ERP_EDI_CALLOFF_HEAD_R    -> DM_DNM_EDI_CALLOFF_HEAD
 *                XIF_ERP_EDI_CALLOFF_PARTNER_R -> DM_DNM_EDI_CALLOFF_PARTNER
 *                XIF_ERP_EDI_CALLOFF_ITEM_R    -> DM_DNM_EDI_CALLOFF_ITEM
 * Program History
 *------------------------------------------------------------
 * Date          In Charge      Description
 *------------------------------------------------------------
 * 배포시 주의사항 : 개발기 -> LGCE_INFDEV , 운영기 -> LGCE_INF
 * 20181008 KHSONG   Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 * 20190130 KHSONG   [CSR ID:3910052] Scheduling data 구분 처리
 * 20190211 KHSONG   DM_MST_CUSTOMER_FCST 기존 사용자의 CUST_FCST 값이 존재하는경우 20000102 한건만 VALID_YN='Y'로 UPDATE하고 나머지 구간은 'N' 처리함
 * 20190225 KHSONG   PSA고객사 MESSAGE_TYPE 구분처리 로직 추가
 * 20190311 KHSONG   QTY 데이터타입 오류로 변환방식으로 수정
 * 20190404 KHSONG   PSA고객사 Periodic DELFOR 값에 대한 구간반영 적용
 * 20191118 KHSONG   [CSR ID:4098705] GSCM(DM)에서 Incoterms 조건에 따라 Customer EDI의 DP 반영 요청의 건
 * 20191121 KHSONG   [C20191031-000137] EDI로 수신 받은 Call-off 정보 편집 기능 제외 처리
 * 20200331 KHSONG   FCA 신규건 수신시 컬럼정보의 비교시 NULL 오류로 보완함
 * 20201029 HWI1993  C20200617-000033 EDI 성능개선
 * 20200923 hwi1993  C20200827-000257 [SCM PI팀] EDI 연계 관련 GSCM setting 건, 소형 테슬라 추가. DIVISION_ID 를 하드코딩에서 변수로 변경
 *                   위 내용 수정부분을 2020.10.29 머지함.
 * 20200209 KUNIID   [C20210208-000443] EDI CALL-OFF수신 시 적용 사항
 *                   필수정보인 SOLD TO CUSTOMER가 누락된 건만 제외하고 나머지 정상 DATA는 GSCM에 매핑해 주도록 함
 * 20211222 HWI1993  PK오류 수정
 * 20220105 hwi1993  컷오프 수정과 같이 배포예정, SCM_MST_SITE_CUSTOMER 에 동일한 SHIPTO, SOLDTO 가 중복으로 있을 경우 ITEM 테이블에 중복값이 들어가는 오류 수정
 * 20220224 kdw2819  RDD_START가 NULL인 잘못된 데이터 제외 하도록 수정
 * 20220729 hwi1993  [C20220728-000062]DOC_STATUS 추가 ( 'S', 'W' 는 정상, 'E'는 오류, 국내는 정상건만 수신되는데 null 로 들어옴 )
 * 20221122 HWI1993  C20221103-000432 EDI 상시 점검
 * 20221130 HWI1993  [C20221103-000435] EDI데이터 송수신 I/F 변경
 * 20221130 HWI1993  [C20221103-000435] EDI데이터 송수신 I/F 변경 - SENDER CODE 룰 변경
 * 20221213 HWI1993  [C20221103-000435] sender_code Data Type이 5자리로 변경되어서 그에 맞도록 수정
 * 20221220 CHANO0612 [C20221221-000148] EDI Data I/F Status 변경 요청
 * 20230118 kdmcc14  [E20230118-000139] I/F 테이블 데이터 이관시 EDI_CALLOFF 테이블에 SENDER_CODE, SENDER_NAME 입력되도록 개선
 * 20240429 kcw3408  N:N Model Mapping_적재 배치 추가(PR_DM_CUST_ITEM_MAPPING)
 * 20241216 KANG.H.J [PJ2024-50647] 자동차사업부 고객 수요 분석 기능 개선
 * 2026.07.06   ZIONEX         [PJ202650304]  NextSCM Migration
 * ============================================================ */
AS
    V_PROGRAM_NAME  VARCHAR2(150 CHAR) := 'PR_DM_DNM_EDI_CALLOFF';
    V_LOG_TYPE      VARCHAR2(30 CHAR);
    N_LOG_COUNT     NUMBER := 0;
    V_LOG_MESSAGE   VARCHAR2(1000 CHAR);
    V_DESCRIPTION   VARCHAR2(500 CHAR);
    D_EVENT_DATE    DATE;
    V_ERR           VARCHAR2(1000 CHAR);
BEGIN
    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := NULL;
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    BEGIN
        /* EDI I/F 데이터 이관 */
        PR_DM_DNM_EDI_CALLOFF_DATA; 

        /* EDI STATUS 상태코드 체크 */
        PR_DM_DNM_EDI_CALLOFF_STATUS;

        /* EDI N:N Model Mapping 적재 (2024.04.29) */
        PR_DM_CUST_MODEL_MAPPING_IF('ERP');
        PR_DM_CUST_MODEL_MAPPING('SCM');

        /* MKT FCST 생성 */
        PR_DM_DNM_EDI_CALLOFF_MKT_FCST;

    EXCEPTION
        WHEN OTHERS THEN

            V_ERR         := SQLERRM;
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(V_ERR, 1, 1000);
            V_DESCRIPTION := 'ERROR_LINE : ' || TO_CHAR(SQLCODE);
            D_EVENT_DATE  := SYSDATE;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    END;

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := NULL;
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

END PR_DM_DNM_EDI_CALLOFF;

PROCEDURE PR_DM_DNM_ERP_EDI_MST_SUMMARY_MAIL_SEND
AS
/****************************************************************************************************/
/*
 * Program ID   : PR_DM_DNM_ERP_EDI_MST_SUMMARY_MAIL_SEND
 * Description  : EDI ERP정비 데이터 메일 발송 - 매일 08시00분 발송
 * PARAMETER    : N/A
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2023.07.03 kdmcc14  [EDI 프로젝트] EDI ERP정비 데이터 메일 발송 요청 건
 * 2026.07.06 ZIONEX   [PJ202650304]  NextSCM Migration
 */
/****************************************************************************************************/
/* ------------------------------------------------------------------------------------------------
 * 변환(MSSQL->Oracle) 재변환 : DM EDI Master 정비현황 요약 메일 발송 (메일표준 PKG_SEND_MAIL.P_SEND_MAIL 직접전환 : 2026-07-19 정책 확정)
 *   - #T_EDI_MST_SUMMARY -> GT_DDEMS_SUMMARY, #T_MAIL_ADDR -> GT_DDEMS_MAIL_ADDR (PRESERVE ROWS=게이트웨이 내부 COMMIT 대비, 초기화 DELETE)
 *   - 로깅 START/END 6인자, ERROR 10인자(SQLCODE/SQLERRM/BACKTRACE), 예외 흡수(RAISE 없음), END 로그 예외 바깥
 * ------------------------------------------------------------------------------------------------ */
    V_PROGRAM_NAME   VARCHAR2(150 CHAR) := 'PR_DM_DNM_ERP_EDI_MST_SUMMARY_MAIL_SEND';
    V_LOG_TYPE       VARCHAR2(30 CHAR);
    N_LOG_COUNT      INTEGER := 0;
    V_LOG_MESSAGE    VARCHAR2(1000 CHAR);
    V_DESCRIPTION    VARCHAR2(500 CHAR);
    D_EVENT_DATE     DATE;
    V_TABLE_BODY     VARCHAR2(32767 CHAR);
    V_BODY_CONTENTS  VARCHAR2(4000 CHAR);
    V_HEAD_CONT      VARCHAR2(2000 CHAR);
    V_BODY_CONT      VARCHAR2(32767 CHAR);
    V_MAIL_TITLE     VARCHAR2(150 CHAR);
    V_OWNER          VARCHAR2(100 CHAR);
BEGIN

    /* STEP 01. LOG 저장 (시작) */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '##### Start of procedure #####';
    V_DESCRIPTION := 'EDI ERP정비 데이터 메일 발송';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    BEGIN

        /* STEP 02. 작업 GTT 초기화 (PRESERVE ROWS) */
        DELETE FROM GT_DDEMS_SUMMARY;
        DELETE FROM GT_DDEMS_MAIL_ADDR;

        /* STEP 03. EDI MASTER 정비 데이터 조회 */
        INSERT INTO GT_DDEMS_SUMMARY
             ( DIVISION_ID
             , EDI_SENDER_NAME
             , ERP_MASTER_DATA
             , GSCM_MASTER_DATA
             , SUCCESS )
        SELECT X.DIVISION_ID
             , X.EDI_SENDER_NAME
             , X.ERP_MASTER_DATA
             , X.GSCM_MASTER_DATA
             , X.SUCCESS
          FROM ( SELECT A.DIVISION_ID
                      , A.SENDER_NAME AS EDI_SENDER_NAME
                      , SUM(CASE WHEN A.STATUS_CODE IN ('U', 'E') AND A.ERP_STATUS = 'ING_ERP'  THEN 1 ELSE 0 END) AS ERP_MASTER_DATA
                      , SUM(CASE WHEN A.STATUS_CODE IN ('U', 'E') AND A.ERP_STATUS = 'ING_GSCM' THEN 1 ELSE 0 END) AS GSCM_MASTER_DATA
                      , SUM(CASE WHEN A.STATUS_CODE = 'S'         AND A.ERP_STATUS IS NULL      THEN 1 ELSE 0 END) AS SUCCESS
                   FROM ( SELECT A.DIVISION_ID, A.SENDER_CODE, A.SENDER_NAME, A.UNLOADING_POINT, A.CUSTOMER_PLANT, A.CUST_MATERIAL_CODE
                               , A.SHIPTO_CODE, A.SOLDTO_CODE, A.ITEM_ID, A.SCM_SITE_ID, A.STATUS_CODE, A.SSPM_STATUS, A.EDI_INCOTERMS
                               , A.PROJECT_CODE, B.END_CUSTOMER, A.SALES_PLANT_SITE_STATUS, A.ERP_STATUS
                            FROM DM_DNM_EDI_CALLOFF_ITEM A
                               , SCM_MST_SITE            B
                           WHERE A.DIVISION_ID  = B.DIVISION_ID(+)
                             AND A.SCM_SITE_ID  = B.SCM_SITE_ID(+)
                             AND B.SITE_TYPE(+) = 'SALES'
                             AND B.VALID_YN(+)  = 'Y'
                             AND A.CREATE_DATE >= '20230101'
                             AND A.DIVISION_ID LIKE '81%'
                             AND A.SENDER_NAME <> 'LUCID'
                           GROUP BY A.DIVISION_ID, A.SENDER_CODE, A.SENDER_NAME, A.UNLOADING_POINT, A.CUSTOMER_PLANT, A.CUST_MATERIAL_CODE
                                  , A.SHIPTO_CODE, A.SOLDTO_CODE, A.ITEM_ID, A.SCM_SITE_ID, A.STATUS_CODE, A.SSPM_STATUS, A.EDI_INCOTERMS
                                  , A.PROJECT_CODE, B.END_CUSTOMER, A.SALES_PLANT_SITE_STATUS, A.ERP_STATUS ) A
                  GROUP BY A.DIVISION_ID, A.SENDER_NAME ) X
         WHERE ( X.ERP_MASTER_DATA <> 0 OR X.GSCM_MASTER_DATA <> 0 )
         ORDER BY X.DIVISION_ID, X.EDI_SENDER_NAME;

        /* STEP 04. 메일발송 대상 (Lookup : EDI_MST_MAIL_ADDR) */
        INSERT INTO GT_DDEMS_MAIL_ADDR
             ( SEGMENT1
             , SEQ )
        SELECT A.SEGMENT1
             , ROW_NUMBER() OVER (ORDER BY A.SEGMENT1) AS SEQ
          FROM ( SELECT A.SEGMENT1
                   FROM SCM_ADM_LOOKUP_MASTER_DETAIL A
                  WHERE A.LOOKUP_TYPE = 'EDI_MST_MAIL_ADDR'
                    AND A.VALID_YN = 'Y'
                    AND REPLACE(A.SEGMENT2, '-', '') IS NULL ) A;

        /* STEP 05-1. 테이블 HEADER */
        /* [2026-10-07] 비운영에서는 제목에 'DEV Oracle 개발서버 ' 를 붙인다 (사용자 결정 가).
         * 원본 MSSQL 은 이 건을 SCM_ADM_MAIL_SEND(행 17) 경유로 보내고 Oracle 행 17 에 같은 분기가 있는데,
         * Oracle 은 PKG_SEND_MAIL 을 직접 불러(계보 평탄화) 그 표시가 빠졌다.
         * 발송 동작은 원본 그대로 두고 식별만 되살린다 — 행 10·17 과 같은 판정식이다. */
        IF SYS_CONTEXT('USERENV', 'DB_NAME') NOT LIKE 'OCGSCMP%' THEN
            V_MAIL_TITLE := 'DEV Oracle 개발서버 '||'[EDI Master Data Report] 입니다.';
        ELSE
            V_MAIL_TITLE := '[EDI Master Data Report] 입니다.';
        END IF;
        V_BODY_CONTENTS := '[EDI Master Data Report] </br> '
                        || '안녕하세요. GSCM.DM 입니다. </br> '
                        || '아래와 같이 EDI Master Data 정비 현황을 전달 드립니다. </br> '
                        || '고객 수요를 놓치는 일이 없도록 ERP와 GSCM에서 Master Data를 정비/관리 부탁 드립니다. </br></br>'
                        || '[EDI Master Summary] </br>';

        V_HEAD_CONT := '<TR>
                            <TH>Div</TH>
                            <TH>EDI Sender Name</TH>
                            <TH>ERP Master Data 정비필요</TH>
                            <TH>GSCM Master Data 정비필요</TH>
                            <TH>정상</TH>
                        </TR>';

        /* STEP 05-2. 테이블 반복 내용 (대상 주소만큼 반복) */
        FOR ADDR_REC IN ( SELECT SEGMENT1, SEQ FROM GT_DDEMS_MAIL_ADDR ORDER BY SEQ ) LOOP

            V_OWNER     := ADDR_REC.SEGMENT1;
            V_BODY_CONT := NULL;

            /* 본문내용 생성 (CUR_SEND) */
            FOR R IN ( SELECT DIVISION_ID, EDI_SENDER_NAME, ERP_MASTER_DATA, GSCM_MASTER_DATA, SUCCESS
                         FROM GT_DDEMS_SUMMARY
                        ORDER BY DIVISION_ID, EDI_SENDER_NAME ) LOOP

                V_BODY_CONT := V_BODY_CONT || '<TR>';
                V_BODY_CONT := V_BODY_CONT || '<TD align = center>' || R.DIVISION_ID      || '</TD>';
                V_BODY_CONT := V_BODY_CONT || '<TD align = center>' || R.EDI_SENDER_NAME  || '</TD>';
                V_BODY_CONT := V_BODY_CONT || '<TD align = center>' || R.ERP_MASTER_DATA  || '</TD>';
                V_BODY_CONT := V_BODY_CONT || '<TD align = center>' || R.GSCM_MASTER_DATA || '</TD>';
                V_BODY_CONT := V_BODY_CONT || '<TD align = center>' || R.SUCCESS          || '</TD>';
                V_BODY_CONT := V_BODY_CONT || '</TR>';

            END LOOP;

            V_TABLE_BODY := ' <html>
                                <head>
                                    <title>Untitled Document</title>
                                    <style>
                                        * {margin:0;padding:0;}
                                        body {font-family:Malgun Gothic, Arial, Helvetica, sans-serif;font-size:12px;line-height:1.8;color:#333333;}
                                        table {border-collapse:collapse;width:100%;}
                                        table th {background:#f5f5f5;border-bottom:1px solid #e1e1e1;}
                                        table td {background:#fff;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1;border-bottom:1px solid #e1e1e1;}
                                        table tbody th {border-left:1px solid #e1e1e1;text-align:right;padding:6px 8px;font-size:12px}
                                        table tbody td {padding:6px 8px;font-size:12px}
                                        table thead th {text-align:center;padding:3px;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1; border-bottom:1px solid #d1d1d1;font-size:12px}
                                        .hori-table table thead td {text-align:center;padding:3px;}
                                        .hori-table table tbody td {text-align:center;padding:3px;}
                                        .vertical-table, .hori-table {margin-bottom:20px;}
                                    </style>
                                </head>
                                <body></br><b>' || REPLACE(V_BODY_CONTENTS, CHR(10), '<br>') || '</b>'
                                || '<div id="divBody" style="width: 100%; overflow-x: auto; overflow-y: auto; font-size: 9pt; line-break: auto;">'
                                || '<table style=''border-top:2px solid #c8294b; width:1450px;''>
                                <thead>' || V_HEAD_CONT || '</thead>
                                <tbody>' || V_BODY_CONT || '</tbody>
                                </div>
                            </body>
                       </html>';

            /* STEP 05-3. Mail 전송 (메일표준 PKG_SEND_MAIL.P_SEND_MAIL 직접호출 : 2026-07-19 정책 확정) */
            PKG_SEND_MAIL.P_SEND_MAIL(V_OWNER, V_MAIL_TITLE, V_TABLE_BODY, 'Y');

            /* [2026-10-07] 발송 간 대기 삭제 (사용자 지시 2026-10-06).
             * ②묶음발송 적용 여부는 그 트랙에서 별도 판단한다 — 대기 삭제만 먼저 반영한다.
             * 원본 MSSQL 의 WAITFOR DELAY 는 그대로 둔다 — 원본을 고치는 게 아니라 Oracle 발송 방식에 맞춘 것이다.
             * 삭제한 블록 : IF MOD(ADDR_REC.SEQ, 5) IN (0, 5) THEN SYS.DBMS_SESSION.SLEEP(30); END IF; */

        END LOOP;

    EXCEPTION
        WHEN OTHERS THEN
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := 'ERROR_BACKTRACE : ' || SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 480);
            D_EVENT_DATE  := SYSDATE;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME
                                , V_LOG_TYPE
                                , N_LOG_COUNT
                                , V_LOG_MESSAGE
                                , V_DESCRIPTION
                                , D_EVENT_DATE
                                , P_IN_PARA_DATA  => NULL
                                , P_SQL_ERR_CODE  => SQLCODE
                                , P_SQL_ERR_MSG   => SQLERRM
                                , P_SQL_BACKTRACE => DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
    END;


    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '##### END of procedure #####';
    V_DESCRIPTION := 'EDI ERP정비 데이터 메일 발송';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

END;

PROCEDURE PR_DM_DNM_EXCHANGE_RATE_MAIL_SEND
/* ============================================================
 * Program ID   : PR_DM_DNM_EXCHANGE_RATE_MAIL_SEND
 * Description  : 최신 환율 정보 공유 메일 발송 - 매주 수요일 밤 11시40분 발송
 * PARAMETER    : N/A
 * Program History
 *------------------------------------------------------------
 * Date          In Charge      Description
 *------------------------------------------------------------
 * 2021.08.03    SJHAN          [C20210723-000366] GSCM 환율 IF 알람(현재월포함 13개월)
 * 2021.08.24    hwi1993        [C20210723-000366] - 메일 누락 수정
 * 2022.11.28    chano0612       [C20221124-000290] 환율 IF관련 수정 요청 건
 * 2023-08-04    HMIN           [E20230721-001841] 용어 수정  GSCM->SCM
 * 2025.07.03    kjiyoon        [PJ2025-50188]소형 매출계획 동기화 개선 고도화 : 각 담당하는 사업부 환율 정보만 수신
 * 2026.07.06    ZIONEX         [PJ202650304]  NextSCM Migration
 * ============================================================ */
AS
    V_PROGRAM_NAME       VARCHAR2(200 CHAR) := $$PLSQL_UNIT;
    V_LOG_TYPE           VARCHAR2(30 CHAR);
    N_LOG_COUNT          INTEGER := 0;
    V_LOG_MESSAGE        VARCHAR2(1000 CHAR);
    V_DESCRIPTION        VARCHAR2(500 CHAR);
    D_EVENT_DATE         DATE;
    V_DISPATCH_SERIAL_NO PLS_INTEGER;

    V_PROC_INPUT         VARCHAR2(4000 CHAR);
    V_SQL_CODE           VARCHAR2(100 CHAR);
    V_SQL_ERRMSG         VARCHAR2(1000 CHAR);
    V_BACKTRACE          VARCHAR2(4000 CHAR);

    V_FROMDATE           VARCHAR2(10 CHAR);
    V_TODATE             VARCHAR2(10 CHAR);
    V_NSQL               VARCHAR2(32767 CHAR);
    V_SCNT               PLS_INTEGER := 1;
    V_TCNT               PLS_INTEGER := 1;

    V_CUR_DIV_DIVISION_ID      VARCHAR2(10 CHAR);
    V_CUR_DIV_DIVISION_ID_LIST VARCHAR2(200 CHAR);

    V_TABLE_BODY         VARCHAR2(32767 CHAR);
    V_BODY_CONTENTS      VARCHAR2(32767 CHAR);
    V_HEAD_CONT          VARCHAR2(32767 CHAR);
    V_BODY_CONT          VARCHAR2(32767 CHAR);
    V_TO_MAIL            VARCHAR2(150 CHAR);
    V_MAIL_TITLE         VARCHAR2(100 CHAR);
    V_OWNER              VARCHAR2(100 CHAR);
    V_OWNER_TYPE         VARCHAR2(3 CHAR);
    V_LIKE_STRING        VARCHAR2(100 CHAR);

    V_THISYEARCOL        VARCHAR2(10 CHAR);
    V_NEXTYEARCOL        VARCHAR2(10 CHAR);
    V_THISYEAR           VARCHAR2(10 CHAR);
    V_NEXTYEAR           VARCHAR2(10 CHAR);

    V_YYMMDD             VARCHAR2(8 CHAR);
    V_YYYY               VARCHAR2(4 CHAR);
    V_MM                 VARCHAR2(2 CHAR);
    V_DD                 VARCHAR2(2 CHAR);
    V_DATETIME           VARCHAR2(50 CHAR);
    V_MAIL_ADDR_LIST     VARCHAR2(4000 CHAR) := '';

    V_C_DIVISION_ID      VARCHAR2(150 CHAR);
    V_C_CURRENCY         VARCHAR2(100 CHAR);
    V_C_UNIT_CURRENCY    VARCHAR2(50 CHAR);
    V_C_MON01            VARCHAR2(50 CHAR);
    V_C_MON02            VARCHAR2(50 CHAR);
    V_C_MON03            VARCHAR2(50 CHAR);
    V_C_MON04            VARCHAR2(50 CHAR);
    V_C_MON05            VARCHAR2(50 CHAR);
    V_C_MON06            VARCHAR2(50 CHAR);
    V_C_MON07            VARCHAR2(50 CHAR);
    V_C_MON08            VARCHAR2(50 CHAR);
    V_C_MON09            VARCHAR2(50 CHAR);
    V_C_MON10            VARCHAR2(50 CHAR);
    V_C_MON11            VARCHAR2(50 CHAR);
    V_C_MON12            VARCHAR2(50 CHAR);
    V_C_MON13            VARCHAR2(50 CHAR);

    /* 사업부별 CURSOR [PJ2025-50188] */
    CURSOR CUR_DIV IS
    SELECT ATTRIBUTE3 AS DIVISION_ID
         , LISTAGG(DIVISION_ID, ',') WITHIN GROUP (ORDER BY DIVISION_ID) AS DIVISION_ID_LIST
      FROM SCM_MST_DIVISION
     WHERE ATTRIBUTE3 IN ('40', '81', '82')
     GROUP BY ATTRIBUTE3;

    /* 본문 생성 CURSOR (원본 CUR_SEND: SELECT * FROM #EXCHANGE) */
    CURSOR CUR_SEND IS
    SELECT DIVISION_ID
         , CURRENCY
         , UNIT_CURRENCY
         , C1
         , C2
         , C3
         , C4
         , C5
         , C6
         , C7
         , C8
         , C9
         , C10
         , C11
         , C12
         , C13
      FROM GT_EXRT_EXCHANGE
     ORDER BY DIVISION_ID, CURRENCY, UNIT_CURRENCY;

BEGIN
    /* ----------------------------------------------------------------------------------------------- */
    /* STEP 01. LOG 저장 (변수 생성 및 실행) */
    /* ----------------------------------------------------------------------------------------------- */

    DELETE
      FROM GT_EXRT_EXCHANGE;

    DELETE
      FROM GT_EXRT_MAIL_ADDR;

    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '##### Start of procedure #####';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    /* ----------------------------------------------------------------------------------------------- */
    /* STEP 02. 임시테이블 / 변수 생성 */
    /* ----------------------------------------------------------------------------------------------- */
    V_FROMDATE := TO_CHAR(SYSDATE, 'YYYYMM') || '01';                    /* 날짜 From */
    V_TODATE   := TO_CHAR(ADD_MONTHS(SYSDATE, 12), 'YYYYMM') || '01';    /* 날짜 To */

    /* ----------------------------------------------------------------------------------------------- */
    /* STEP 03. 환율 DATA 조회 (사업부별 CURSOR 루프) [PJ2025-50188] */
    /* ----------------------------------------------------------------------------------------------- */
    OPEN CUR_DIV;
    FETCH CUR_DIV INTO V_CUR_DIV_DIVISION_ID, V_CUR_DIV_DIVISION_ID_LIST;

    WHILE CUR_DIV%FOUND LOOP

        DELETE
          FROM GT_EXRT_EXCHANGE;

        INSERT
          INTO GT_EXRT_EXCHANGE
             ( DIVISION_ID
             , CURRENCY
             , UNIT_CURRENCY
             , C1
             , C2
             , C3
             , C4
             , C5
             , C6
             , C7
             , C8
             , C9
             , C10
             , C11
             , C12
             , C13 )
        SELECT DIVISION_ID
             , CURRENCY
             , UNIT_CURRENCY
             , MAX(CASE WHEN ROW_NUM = 1  THEN EXCHANGE_PRICE END)
             , MAX(CASE WHEN ROW_NUM = 2  THEN EXCHANGE_PRICE END)
             , MAX(CASE WHEN ROW_NUM = 3  THEN EXCHANGE_PRICE END)
             , MAX(CASE WHEN ROW_NUM = 4  THEN EXCHANGE_PRICE END)
             , MAX(CASE WHEN ROW_NUM = 5  THEN EXCHANGE_PRICE END)
             , MAX(CASE WHEN ROW_NUM = 6  THEN EXCHANGE_PRICE END)
             , MAX(CASE WHEN ROW_NUM = 7  THEN EXCHANGE_PRICE END)
             , MAX(CASE WHEN ROW_NUM = 8  THEN EXCHANGE_PRICE END)
             , MAX(CASE WHEN ROW_NUM = 9  THEN EXCHANGE_PRICE END)
             , MAX(CASE WHEN ROW_NUM = 10 THEN EXCHANGE_PRICE END)
             , MAX(CASE WHEN ROW_NUM = 11 THEN EXCHANGE_PRICE END)
             , MAX(CASE WHEN ROW_NUM = 12 THEN EXCHANGE_PRICE END)
             , MAX(CASE WHEN ROW_NUM = 13 THEN EXCHANGE_PRICE END)
          FROM (SELECT DIVISION_ID
                     , CURRENCY
                     , UNIT_CURRENCY
                     , FN_GET_NUMER_TO_STRING(ROUND(EXCHANGE_PRICE, 2), 2) AS EXCHANGE_PRICE
                     , DENSE_RANK() OVER (ORDER BY YYYYMMDD) AS ROW_NUM
                  FROM DM_MST_EXCHANGE_RATE
                 WHERE YYYYMMDD >= V_FROMDATE
                   AND YYYYMMDD <= V_TODATE
                   AND CURRENCY = 'KRW'
                   AND UNIT_CURRENCY IN (SELECT SEGMENT1
                                           FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                                          WHERE LOOKUP_TYPE = 'DMF0020_CURRENCY'
                                            AND VALID_YN = 'Y')
                   AND DIVISION_ID IN (SELECT REGEXP_SUBSTR(V_CUR_DIV_DIVISION_ID_LIST, '[^,]+', 1, LEVEL)
                                         FROM DUAL
                                      CONNECT BY REGEXP_SUBSTR(V_CUR_DIV_DIVISION_ID_LIST, '[^,]+', 1, LEVEL) IS NOT NULL)
                 GROUP BY DIVISION_ID, CURRENCY, UNIT_CURRENCY, YYYYMMDD, EXCHANGE_PRICE) IA
         GROUP BY DIVISION_ID, CURRENCY, UNIT_CURRENCY;

        /* ------------------------------------------------------------------------------------------- */
        /* STEP 04. 메일발송 대상 */
        /* ------------------------------------------------------------------------------------------- */
        DELETE
          FROM GT_EXRT_MAIL_ADDR;

        INSERT
          INTO GT_EXRT_MAIL_ADDR
             ( SEGMENT1
             , SEQ )
        SELECT SEGMENT1
             , ROW_NUMBER() OVER (ORDER BY SEGMENT1) AS SEQ
          FROM (SELECT A.SEGMENT1
                  FROM SCM_ADM_LOOKUP_MASTER_DETAIL A
                 WHERE A.LOOKUP_TYPE = 'DM_EXCHANGE_RATE_MAIL_ADDR'
                   AND A.VALID_YN = 'Y'
                   AND REPLACE(A.SEGMENT2, '-', '') IS NULL
                   AND EXISTS (SELECT 1
                                 FROM (SELECT REGEXP_SUBSTR(A.SEGMENT3, '[^,]+', 1, LEVEL) AS TOKEN
                                         FROM DUAL
                                      CONNECT BY REGEXP_SUBSTR(A.SEGMENT3, '[^,]+', 1, LEVEL) IS NOT NULL) SS
                                WHERE SS.TOKEN IN (SELECT REGEXP_SUBSTR(V_CUR_DIV_DIVISION_ID_LIST, '[^,]+', 1, LEVEL)
                                                     FROM DUAL
                                                  CONNECT BY REGEXP_SUBSTR(V_CUR_DIV_DIVISION_ID_LIST, '[^,]+', 1, LEVEL) IS NOT NULL))
                 UNION   /* UNION ALL -> UNION 으로 변경 [PJ2025-50188] */
                SELECT INFO.USER_ID || '@lgensol.com'   /* POTAL ID + 에너지솔루션 MAIL주소 */
                  FROM SCM_MST_SSO_USER_INFO INFO
                     , (SELECT B.DEPT_ID
                          FROM SCM_ADM_LOOKUP_MASTER_DETAIL A
                             , SCM_MST_SSO_DEPT_INFO B
                         WHERE A.SEGMENT2 = B.DEPT_ID
                           AND A.LOOKUP_TYPE = 'DM_EXCHANGE_RATE_MAIL_ADDR'
                           AND A.VALID_YN = 'Y'
                           AND REPLACE(A.SEGMENT2, '-', '') IS NOT NULL
                           AND EXISTS (SELECT 1
                                         FROM (SELECT REGEXP_SUBSTR(A.SEGMENT3, '[^,]+', 1, LEVEL) AS TOKEN
                                                 FROM DUAL
                                              CONNECT BY REGEXP_SUBSTR(A.SEGMENT3, '[^,]+', 1, LEVEL) IS NOT NULL) SS
                                        WHERE SS.TOKEN IN (SELECT REGEXP_SUBSTR(V_CUR_DIV_DIVISION_ID_LIST, '[^,]+', 1, LEVEL)
                                                             FROM DUAL
                                                          CONNECT BY REGEXP_SUBSTR(V_CUR_DIV_DIVISION_ID_LIST, '[^,]+', 1, LEVEL) IS NOT NULL))) B
                 WHERE INFO.DEPT_ID = B.DEPT_ID) IA;

        SELECT COUNT(*)
          INTO V_TCNT
          FROM GT_EXRT_MAIL_ADDR;

        /* ------------------------------------------------------------------------------------------- */
        /* STEP 05. 메일발송 - 전송대상만큼 반복 (헤더, 본문) */
        /* ------------------------------------------------------------------------------------------- */

        /* STEP 05-1. 테이블 헤더 rowspan, colspan, 대상 월 구하기 */
        V_THISYEARCOL := TO_CHAR(12 - TO_NUMBER(TO_CHAR(SYSDATE, 'MM')) + 1);
        V_NEXTYEARCOL := TO_CHAR(13 - TO_NUMBER(V_THISYEARCOL));
        V_THISYEAR    := TO_CHAR(SYSDATE, 'YYYY');
        V_NEXTYEAR    := TO_CHAR(ADD_MONTHS(SYSDATE, 12), 'YYYY');

        /* STEP 05-2. 최근환율 년, 월, 일 - 메일 제목 변수 */
        BEGIN
            SELECT V_YMD
                 , V_DT
              INTO V_YYMMDD, V_DATETIME
              FROM (SELECT TO_CHAR(LAST_UPDATE_DATE, 'YYYYMMDD') AS V_YMD
                         , TO_CHAR(LAST_UPDATE_DATE, 'YYYY-MM-DD HH24:MI:SS') AS V_DT
                      FROM DM_MST_EXCHANGE_RATE
                     ORDER BY LAST_UPDATE_DATE DESC) IA
             WHERE ROWNUM = 1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                V_YYMMDD   := NULL;
                V_DATETIME := NULL;
        END;

        V_YYYY := SUBSTR(V_YYMMDD, 1, 4);
        V_MM   := SUBSTR(V_YYMMDD, 5, 2);
        V_DD   := SUBSTR(V_YYMMDD, 7, 2);

        /* STEP 05-2. 테이블 HEADER */
        /* [2026-10-07] 비운영에서는 제목에 'DEV Oracle 개발서버 ' 를 붙인다 (사용자 결정 가).
         * 원본 MSSQL 은 이 건을 SCM_ADM_MAIL_SEND(행 17) 경유로 보내고 Oracle 행 17 에 같은 분기가 있는데,
         * Oracle 은 PKG_SEND_MAIL 을 직접 불러(계보 평탄화) 그 표시가 빠졌다.
         * 발송 동작은 원본 그대로 두고 식별만 되살린다 — 행 10·17 과 같은 판정식이다. */
        IF SYS_CONTEXT('USERENV', 'DB_NAME') NOT LIKE 'OCGSCMP%' THEN
            V_MAIL_TITLE := 'DEV Oracle 개발서버 '||'최신 환율 정보 공유';
        ELSE
            V_MAIL_TITLE := '최신 환율 정보 공유';
        END IF;
        V_BODY_CONTENTS := '안녕하십니까? </br> '
            || '</br> BPS 로부터 [ ' || V_DATETIME || ' ] 에 IF받은 Exchange Rate가 SCM에 적용되어 있습니다. </br></br>';  /* [E20230721-001841] 용어 수정  GSCM->SCM */

        V_HEAD_CONT := '<TR>
            <TH rowspan="2">DIV</TH>
            <TH rowspan="2">Currency</TH>
            <TH rowspan="2">Unit</TH>
            <TH colspan="' || V_THISYEARCOL || '">' || V_THISYEAR || '</TH>
            <TH colspan="' || V_NEXTYEARCOL || '">' || V_NEXTYEAR || '</TH>
            </TR>
            <TR>
            <TH>' || TO_CHAR(SYSDATE, 'MM') || '</TH>
            <TH>' || TO_CHAR(ADD_MONTHS(SYSDATE, 1), 'MM') || '</TH>
            <TH>' || TO_CHAR(ADD_MONTHS(SYSDATE, 2), 'MM') || '</TH>
            <TH>' || TO_CHAR(ADD_MONTHS(SYSDATE, 3), 'MM') || '</TH>
            <TH>' || TO_CHAR(ADD_MONTHS(SYSDATE, 4), 'MM') || '</TH>
            <TH>' || TO_CHAR(ADD_MONTHS(SYSDATE, 5), 'MM') || '</TH>
            <TH>' || TO_CHAR(ADD_MONTHS(SYSDATE, 6), 'MM') || '</TH>
            <TH>' || TO_CHAR(ADD_MONTHS(SYSDATE, 7), 'MM') || '</TH>
            <TH>' || TO_CHAR(ADD_MONTHS(SYSDATE, 8), 'MM') || '</TH>
            <TH>' || TO_CHAR(ADD_MONTHS(SYSDATE, 9), 'MM') || '</TH>
            <TH>' || TO_CHAR(ADD_MONTHS(SYSDATE, 10), 'MM') || '</TH>
            <TH>' || TO_CHAR(ADD_MONTHS(SYSDATE, 11), 'MM') || '</TH>
            <TH>' || TO_CHAR(ADD_MONTHS(SYSDATE, 12), 'MM') || '</TH>
            </TR>';

        /* LOOP 수행전 COUNT 변수 초기화 [PJ2025-50188] */
        V_SCNT := 1;

        /* STEP 05-3. 테이블 반복 내용 */
        WHILE V_SCNT <= V_TCNT LOOP

            V_OWNER     := '';
            V_BODY_CONT := '';

            SELECT SEGMENT1
              INTO V_OWNER
              FROM GT_EXRT_MAIL_ADDR
             WHERE SEQ = V_SCNT;

            /* 본문내용 생성 */
            OPEN CUR_SEND;
            FETCH CUR_SEND INTO V_C_DIVISION_ID, V_C_CURRENCY, V_C_UNIT_CURRENCY
              , V_C_MON01, V_C_MON02, V_C_MON03, V_C_MON04, V_C_MON05, V_C_MON06, V_C_MON07
              , V_C_MON08, V_C_MON09, V_C_MON10, V_C_MON11, V_C_MON12, V_C_MON13;

            WHILE CUR_SEND%FOUND LOOP
                V_BODY_CONT := V_BODY_CONT || '<TR>';
                V_BODY_CONT := V_BODY_CONT || '<TD align = center>' || V_C_DIVISION_ID   || '</TD>';
                V_BODY_CONT := V_BODY_CONT || '<TD align = center>' || V_C_CURRENCY      || '</TD>';
                V_BODY_CONT := V_BODY_CONT || '<TD align = center>' || V_C_UNIT_CURRENCY || '</TD>';
                V_BODY_CONT := V_BODY_CONT || '<TD align = right>'  || V_C_MON01 || '</TD>';
                V_BODY_CONT := V_BODY_CONT || '<TD align = right>'  || V_C_MON02 || '</TD>';
                V_BODY_CONT := V_BODY_CONT || '<TD align = right>'  || V_C_MON03 || '</TD>';
                V_BODY_CONT := V_BODY_CONT || '<TD align = right>'  || V_C_MON04 || '</TD>';
                V_BODY_CONT := V_BODY_CONT || '<TD align = right>'  || V_C_MON05 || '</TD>';
                V_BODY_CONT := V_BODY_CONT || '<TD align = right>'  || V_C_MON06 || '</TD>';
                V_BODY_CONT := V_BODY_CONT || '<TD align = right>'  || V_C_MON07 || '</TD>';
                V_BODY_CONT := V_BODY_CONT || '<TD align = right>'  || V_C_MON08 || '</TD>';
                V_BODY_CONT := V_BODY_CONT || '<TD align = right>'  || V_C_MON09 || '</TD>';
                V_BODY_CONT := V_BODY_CONT || '<TD align = right>'  || V_C_MON10 || '</TD>';
                V_BODY_CONT := V_BODY_CONT || '<TD align = right>'  || V_C_MON11 || '</TD>';
                V_BODY_CONT := V_BODY_CONT || '<TD align = right>'  || V_C_MON12 || '</TD>';
                V_BODY_CONT := V_BODY_CONT || '<TD align = right>'  || V_C_MON13 || '</TD>';
                V_BODY_CONT := V_BODY_CONT || '</TR>';

                FETCH CUR_SEND INTO V_C_DIVISION_ID, V_C_CURRENCY, V_C_UNIT_CURRENCY
                  , V_C_MON01, V_C_MON02, V_C_MON03, V_C_MON04, V_C_MON05, V_C_MON06, V_C_MON07
                  , V_C_MON08, V_C_MON09, V_C_MON10, V_C_MON11, V_C_MON12, V_C_MON13;
            END LOOP;

            CLOSE CUR_SEND;

            V_TABLE_BODY := ' <html>
                        <head>
                                <title>Untitled Document</title>
                                <style>
                                    * {margin:0;padding:0;}
                                    body {font-family:Malgun Gothic, Arial, Helvetica, sans-serif;font-size:12px;line-height:1.8;color:#333333;}
                                    table {border-collapse:collapse;width:100%;}
                                    table th {background:#f5f5f5;border-bottom:1px solid #e1e1e1;}
                                    table td {background:#fff;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1;border-bottom:1px solid #e1e1e1;}
                                    table tbody th {border-left:1px solid #e1e1e1;text-align:right;padding:6px 8px;font-size:12px}
                                    table tbody td {padding:6px 8px;font-size:12px}
                                    table thead th {text-align:center;padding:3px;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1; border-bottom:1px solid #d1d1d1;font-size:12px}
                                    .hori-table table thead td {text-align:center;padding:3px;}
                                    .hori-table table tbody td {text-align:center;padding:3px;}
                                    .vertical-table, .hori-table {margin-bottom:20px;}
                                </style>
                                </head>
                                <body></br><b>' || REPLACE(V_BODY_CONTENTS, CHR(10), '<br>') || '</b>'
                                        || '<div id="divBody" style="width: 100%; overflow-x: auto; overflow-y: auto; font-size: 9pt; line-break: auto;">'
                                        || '<table style=''border-top:2px solid #c8294b; width:1450px;''>
                                    <thead>' || V_HEAD_CONT || '</thead>
                                    <tbody>' || V_BODY_CONT || '</tbody>
                                    </div>
                                </body>
                        </html>';

            /* STEP 05-4. Mail 전송 (메일표준 PKG_SEND_MAIL.P_SEND_MAIL 직접전환(2026-07-19 정책 확정), 4 positional) */
            PKG_SEND_MAIL.P_SEND_MAIL(V_OWNER, V_MAIL_TITLE, V_TABLE_BODY, 'Y');

            /* [2026-10-07] 발송 간 대기 삭제 (사용자 지시 2026-10-06).
             * 수신자를 묶어 보내 통수가 줄어 대기의 목적(메일서버 부하 분산)이 사라졌다.
             * 원본 MSSQL 의 WAITFOR DELAY 는 그대로 둔다 — 원본을 고치는 게 아니라 Oracle 발송 방식에 맞춘 것이다.
             * 삭제한 블록 : IF MOD(V_SCNT, 5) = 0 THEN DBMS_SESSION.SLEEP(30); END IF; */

            V_SCNT := V_SCNT + 1;

        END LOOP;

        FETCH CUR_DIV INTO V_CUR_DIV_DIVISION_ID, V_CUR_DIV_DIVISION_ID_LIST;
    END LOOP;

    CLOSE CUR_DIV;

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '##### END of procedure #####';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;

        V_LOG_TYPE    := 'ERROR';
        V_LOG_MESSAGE := 'EXCEPTION';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        V_SQL_CODE    := TO_CHAR(SQLCODE);
        V_SQL_ERRMSG  := SQLERRM;
        V_PROC_INPUT  := NULL;
        V_BACKTRACE   := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;

        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE
                           , V_DESCRIPTION, D_EVENT_DATE, V_PROC_INPUT
                           , V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE);

        RAISE_APPLICATION_ERROR(-20001
          , '[' || V_PROGRAM_NAME || '] SQLCODE=' || V_SQL_CODE ||
            ' / SQLERRM=' || V_SQL_ERRMSG ||
            ' / BACKTRACE=' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
END;

PROCEDURE PR_DM_ERP_EDI_MST_MODEL
/*
 * Program ID   : PR_DM_ERP_EDI_MST_MODEL
 * Description  :
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2023.04.06   chano0612       []  ERP, EDI MASTER DATA 정비 I/F
 * 2026.07.06   ZIONEX          [PJ202650304] NextSCM Migration
 */
IS
    /* -- LOG 용 변수 설정 */
    V_LOG_TYPE          VARCHAR2(30 CHAR);      /* START/END/ERROR/... */
    N_LOG_COUNT         PLS_INTEGER := 0;
    V_LOG_MESSAGE       VARCHAR2(1000 CHAR);
    V_DESCRIPTION       VARCHAR2(500 CHAR);
    D_EVENT_DATE        DATE;
    N_HISTORY_SEQ       NUMBER(19);
    V_DIVISION_ID       VARCHAR2(30 CHAR);

    V_BATCH_USER        VARCHAR2(150 CHAR) := 'scm_batch';
    V_PROGRAM_NAME      VARCHAR2(150 CHAR) := 'PR_DM_ERP_EDI_MST_MODEL';
    V_BATCH_CHK_MSG     VARCHAR2(150 CHAR) := ' ';

    V_CNT               PLS_INTEGER := 0;
    V_CNT1              PLS_INTEGER := 0;
    V_CNT2              PLS_INTEGER := 0;
    V_I                 PLS_INTEGER := 1;
    V_I1                PLS_INTEGER := 1;
    V_I2                PLS_INTEGER := 1;

    M_SALES_ORG                 VARCHAR2(50 CHAR);
    M_CUSTOMER_CODE             VARCHAR2(50 CHAR);
    M_DESC1_SP                  VARCHAR2(50 CHAR);
    M_DESC1_SH                  VARCHAR2(50 CHAR);
    M_COMPANY_ID                VARCHAR2(50 CHAR);
    M_SCM_SITE_ID               VARCHAR2(50 CHAR);
    M_SENDER_CODE               VARCHAR2(50 CHAR);
    M_SOLDTO_CODE               VARCHAR2(50 CHAR);
    M_SHIPTO_CODE               VARCHAR2(50 CHAR);
    M_ITEM_ID                   VARCHAR2(50 CHAR);
    M_CUST_MATERIAL_CODE        VARCHAR2(50 CHAR);
    M_UNLOADING_POINT           VARCHAR2(50 CHAR);
    M_SALES_PLANT               VARCHAR2(50 CHAR);
    M_PROJECT_CODE              VARCHAR2(50 CHAR);

    V_COMPANY_ID                VARCHAR2(50 CHAR);
    V_SCM_SITE_ID               VARCHAR2(50 CHAR);
    V_SENDER_CODE               VARCHAR2(50 CHAR);
    V_SOLDTO_CODE               VARCHAR2(50 CHAR);
    V_SHIPTO_CODE               VARCHAR2(50 CHAR);
    V_ITEM_ID                   VARCHAR2(50 CHAR);
    V_CUST_MATERIAL_CODE        VARCHAR2(50 CHAR);
    V_UNLOADING_POINT           VARCHAR2(50 CHAR);
    V_SALES_PLANT               VARCHAR2(50 CHAR);
    V_PROJECT_CODE              VARCHAR2(50 CHAR);
BEGIN


    /* 시작 LOG */
    V_LOG_TYPE := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    BEGIN


        DELETE FROM GT_DEEMM_DM_DNM_EDI_CALLOFF_STATUS;
        DELETE FROM GT_DEEMM_MST_MODEL_SALES_SITE;
        DELETE FROM GT_DEEMM_MST_MODEL_UPDATE;

        INSERT
          INTO GT_DEEMM_DM_DNM_EDI_CALLOFF_STATUS
        SELECT ROW_NUMBER() OVER(ORDER BY SEQ) AS SEQ
             , DIVISION_ID
             , COMPANY_ID
             , SENDER_CODE
             , SENDER_NAME
             , SOLDTO_CODE
             , SHIPTO_CODE
             , UNLOADING_POINT
             , SALES_PLANT
             , SCM_SITE_ID
             , PROJECT_CODE
             , REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(ITEM_ID, ' ', ''), '-', ''), '.', ''), '/', ''), ',', ''), ':', ''), ';', ''), '+', ''), '_', ''), '(', ''), ')', ''), '*', ''), '^', ''), '$', ''), '#', '')
             , REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(CUST_MATERIAL_CODE, ' ', ''), '-', ''), '.', ''), '/', ''), ',', ''), ':', ''), ';', ''), '+', ''), '_', ''), '(', ''), ')', ''), '*', ''), '^', ''), '$', ''), '#', '')
          FROM DM_DNM_EDI_CALLOFF_STATUS
         WHERE ERP_STATUS = 'ING_ERP';

        SELECT COUNT(1)
          INTO V_CNT
          FROM GT_DEEMM_DM_DNM_EDI_CALLOFF_STATUS;

        DBMS_OUTPUT.PUT_LINE(V_CNT);
        V_I := 1;

        WHILE V_I <= V_CNT
        LOOP

            V_COMPANY_ID          := ' ';
            V_SENDER_CODE         := ' ';
            V_SOLDTO_CODE         := ' ';
            V_SHIPTO_CODE         := ' ';
            V_UNLOADING_POINT     := ' ';
            V_SALES_PLANT         := ' ';
            V_SCM_SITE_ID         := ' ';
            V_PROJECT_CODE        := ' ';
            V_ITEM_ID             := ' ';
            V_CUST_MATERIAL_CODE  := ' ';

            M_SALES_ORG           := ' ';
            M_CUSTOMER_CODE       := ' ';
            M_ITEM_ID             := ' ';
            M_CUST_MATERIAL_CODE  := ' ';

            SELECT DIVISION_ID
                 , COMPANY_ID
                 , SENDER_CODE
                 , SOLDTO_CODE
                 , SHIPTO_CODE
                 , UNLOADING_POINT
                 , SALES_PLANT
                 , NVL(SCM_SITE_ID, ' ')
                 , PROJECT_CODE
                 , NVL(ITEM_ID, ' ')
                 , CUST_MATERIAL_CODE
              INTO V_DIVISION_ID
                 , V_COMPANY_ID
                 , V_SENDER_CODE
                 , V_SOLDTO_CODE
                 , V_SHIPTO_CODE
                 , V_UNLOADING_POINT
                 , V_SALES_PLANT
                 , V_SCM_SITE_ID
                 , V_PROJECT_CODE
                 , V_ITEM_ID
                 , V_CUST_MATERIAL_CODE
              FROM GT_DEEMM_DM_DNM_EDI_CALLOFF_STATUS
             WHERE SEQ = V_I;

            /* SOLDTO_CODE, V_SHIPTO_CODE 는 있으나 */
            IF (V_SOLDTO_CODE <> ' ' AND V_SHIPTO_CODE <> ' ' AND V_SCM_SITE_ID = ' ') THEN

                FOR REC IN (SELECT SCM_SITE_ID
                              FROM SCM_MST_SITE_CUSTOMER
                             WHERE DIVISION_ID = V_DIVISION_ID
                               AND SOLDTO_CODE = V_SOLDTO_CODE
                               AND SHIPTO_CODE = V_SHIPTO_CODE
                               AND VALID_YN = 'Y') LOOP
                    M_SCM_SITE_ID := REC.SCM_SITE_ID;
                END LOOP;

                UPDATE DM_DNM_EDI_CALLOFF_ITEM
                   SET SCM_SITE_ID      = M_SCM_SITE_ID
                     , ATTRIBUTE10      = 'C'
                     , LAST_UPDATE_DATE = SYSDATE
                     , LAST_UPDATED_BY  = 'scm_batch'
                 WHERE DIVISION_ID = V_DIVISION_ID
                   AND SOLDTO_CODE = V_SOLDTO_CODE
                   AND SHIPTO_CODE = V_SHIPTO_CODE
                   AND STATUS_CODE <> 'S';
                   /* --AND ERP_STATUS = 'ING_ERP' */

                INSERT
                  INTO DM_DNM_ERP_EDI_MST_LOG
                     ( COMPANY_ID
                     , SOLDTO_CODE
                     , SHIPTO_CODE
                     , SCM_SITE_ID
                     , ITEM_ID
                     , ORIGIN_DATA
                     , COOKED_DATA
                     , CONDITION
                     , CREATE_DATE )
                VALUES ( M_SALES_ORG
                       , V_SOLDTO_CODE
                       , V_SHIPTO_CODE
                       , ''
                       , ' '
                       , ''
                       , ''
                       , ''
                       , SYSDATE );

            END IF;

            /* SOLDTO_CODE, V_SHIPTO_CODE, V_CUST_MATERIAL_CODE 는 있으나 V_ITEM_ID 없는 경우 */
            IF (V_SOLDTO_CODE <> ' ' AND V_SHIPTO_CODE <> ' ' AND V_CUST_MATERIAL_CODE <> ' ' AND V_ITEM_ID = ' ') THEN

                FOR REC IN (SELECT SALES_ORG, CUSTOMER_CODE, ITEM_ID, CUSTOMER_ITEM_ID
                              FROM DM_DNM_ERP_EDI_MST_CUST_MATERIAL
                             WHERE SALES_ORG = V_COMPANY_ID
                               AND CUSTOMER_CODE = V_SOLDTO_CODE
                               AND CUSTOMER_ITEM_ID = V_CUST_MATERIAL_CODE
                             GROUP BY SALES_ORG, CUSTOMER_CODE, ITEM_ID, CUSTOMER_ITEM_ID) LOOP
                    M_SALES_ORG          := REC.SALES_ORG;
                    M_CUSTOMER_CODE      := REC.CUSTOMER_CODE;
                    M_ITEM_ID            := REC.ITEM_ID;
                    M_CUST_MATERIAL_CODE := REC.CUSTOMER_ITEM_ID;
                END LOOP;

                IF V_ITEM_ID = ' ' AND V_COMPANY_ID = M_SALES_ORG AND V_SOLDTO_CODE = M_CUSTOMER_CODE AND V_CUST_MATERIAL_CODE = M_CUST_MATERIAL_CODE THEN

                    UPDATE DM_DNM_EDI_CALLOFF_ITEM
                       SET ITEM_ID          = M_ITEM_ID
                         , ATTRIBUTE10      = 'C'
                         , LAST_UPDATE_DATE = SYSDATE
                         , LAST_UPDATED_BY  = 'scm_batch'
                     WHERE COMPANY_ID = M_SALES_ORG
                       AND SOLDTO_CODE = M_CUSTOMER_CODE
                       AND REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(CUST_MATERIAL_CODE, ' ', ''), '-', ''), '.', ''), '/', ''), ',', ''), ':', ''), ';', ''), '+', ''), '_', ''), '(', ''), ')', ''), '*', ''), '^', ''), '$', ''), '#', '') = M_CUST_MATERIAL_CODE
                       AND STATUS_CODE <> 'S';
                       /* --AND ISNULL(ATTRIBUTE10, '') <> 'C' */

                    INSERT
                      INTO DM_DNM_ERP_EDI_MST_LOG
                         ( COMPANY_ID
                         , SOLDTO_CODE
                         , SHIPTO_CODE
                         , SCM_SITE_ID
                         , ITEM_ID
                         , ORIGIN_DATA
                         , COOKED_DATA
                         , CONDITION
                         , CREATE_DATE )
                    VALUES ( M_SALES_ORG
                           , M_CUSTOMER_CODE
                           , ''
                           , ''
                           , M_ITEM_ID
                           , V_CUST_MATERIAL_CODE
                           , M_ITEM_ID
                           , '>>' || M_ITEM_ID
                           , SYSDATE );

                END IF;

            END IF;

            /* CUST_MATERIAL_CODE = ITEM가 동일한 경우 ITEM_ID 정비 */
            IF (V_SOLDTO_CODE <> ' ' AND V_ITEM_ID <> ' ' AND V_ITEM_ID = V_CUST_MATERIAL_CODE) THEN

                FOR REC IN (SELECT SALES_ORG, CUSTOMER_CODE, ITEM_ID, CUSTOMER_ITEM_ID
                              FROM DM_DNM_ERP_EDI_MST_CUST_MATERIAL
                             WHERE SALES_ORG = V_COMPANY_ID
                               AND CUSTOMER_CODE = V_SOLDTO_CODE
                               AND CUSTOMER_ITEM_ID = V_CUST_MATERIAL_CODE
                             GROUP BY SALES_ORG, CUSTOMER_CODE, ITEM_ID, CUSTOMER_ITEM_ID) LOOP
                    M_SALES_ORG          := REC.SALES_ORG;
                    M_CUSTOMER_CODE      := REC.CUSTOMER_CODE;
                    M_ITEM_ID            := REC.ITEM_ID;
                    M_CUST_MATERIAL_CODE := REC.CUSTOMER_ITEM_ID;
                END LOOP;

                IF V_COMPANY_ID = M_SALES_ORG AND V_SOLDTO_CODE = M_CUSTOMER_CODE THEN

                    UPDATE DM_DNM_EDI_CALLOFF_ITEM
                       SET ITEM_ID = M_ITEM_ID
                     WHERE COMPANY_ID = M_SALES_ORG
                       AND SOLDTO_CODE = M_CUSTOMER_CODE
                       AND REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(ITEM_ID, ' ', ''), '-', ''), '.', ''), '/', ''), ',', ''), ':', ''), ';', ''), '+', ''), '_', ''), '(', ''), ')', ''), '*', ''), '^', ''), '$', ''), '#', '') = M_CUST_MATERIAL_CODE
                       AND STATUS_CODE <> 'S';
                       /* --AND ISNULL(ATTRIBUTE10, '') <> 'C' */

                    INSERT
                      INTO DM_DNM_ERP_EDI_MST_LOG
                         ( COMPANY_ID
                         , SOLDTO_CODE
                         , SHIPTO_CODE
                         , SCM_SITE_ID
                         , ITEM_ID
                         , ORIGIN_DATA
                         , COOKED_DATA
                         , CONDITION
                         , CREATE_DATE )
                    VALUES ( M_SALES_ORG
                           , M_CUSTOMER_CODE
                           , ''
                           , ''
                           , M_ITEM_ID
                           , V_CUST_MATERIAL_CODE
                           , M_ITEM_ID
                           , '>>' || M_ITEM_ID
                           , SYSDATE );

                END IF;

            END IF;

            IF (V_SHIPTO_CODE <> ' ' AND V_ITEM_ID <> ' ' AND V_ITEM_ID = V_CUST_MATERIAL_CODE) THEN

                FOR REC IN (SELECT SALES_ORG, CUSTOMER_CODE, ITEM_ID, CUSTOMER_ITEM_ID
                              FROM DM_DNM_ERP_EDI_MST_CUST_MATERIAL
                             WHERE SALES_ORG = V_COMPANY_ID
                               AND CUSTOMER_CODE = V_SHIPTO_CODE
                               AND CUSTOMER_ITEM_ID = V_CUST_MATERIAL_CODE
                             GROUP BY SALES_ORG, CUSTOMER_CODE, ITEM_ID, CUSTOMER_ITEM_ID) LOOP
                    M_SALES_ORG          := REC.SALES_ORG;
                    M_CUSTOMER_CODE      := REC.CUSTOMER_CODE;
                    M_ITEM_ID            := REC.ITEM_ID;
                    M_CUST_MATERIAL_CODE := REC.CUSTOMER_ITEM_ID;
                END LOOP;

                IF V_COMPANY_ID = M_SALES_ORG AND V_SHIPTO_CODE = M_CUSTOMER_CODE THEN

                    UPDATE DM_DNM_EDI_CALLOFF_ITEM
                       SET ITEM_ID = M_ITEM_ID
                     WHERE COMPANY_ID = M_SALES_ORG
                       AND SHIPTO_CODE = M_CUSTOMER_CODE
                       AND REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(ITEM_ID, ' ', ''), '-', ''), '.', ''), '/', ''), ',', ''), ':', ''), ';', ''), '+', ''), '_', ''), '(', ''), ')', ''), '*', ''), '^', ''), '$', ''), '#', '') = M_CUST_MATERIAL_CODE
                       AND STATUS_CODE <> 'S';
                       /* --AND ISNULL(ATTRIBUTE10, '') <> 'C' */

                    INSERT
                      INTO DM_DNM_ERP_EDI_MST_LOG
                         ( COMPANY_ID
                         , SOLDTO_CODE
                         , SHIPTO_CODE
                         , SCM_SITE_ID
                         , ITEM_ID
                         , ORIGIN_DATA
                         , COOKED_DATA
                         , CONDITION
                         , CREATE_DATE )
                    VALUES ( M_SALES_ORG
                           , M_CUSTOMER_CODE
                           , ''
                           , ''
                           , M_ITEM_ID
                           , V_CUST_MATERIAL_CODE
                           , M_ITEM_ID
                           , '>>' || M_ITEM_ID
                           , SYSDATE );

                END IF;

            END IF;

            V_I := V_I + 1;

        END LOOP;

        /* EDI STATUS 정비 */
        PR_DM_DNM_EDI_CALLOFF_STATUS;

        /*
           EDI 소급적용 데이터 생성(배치JOB에서 1시간 간격으로 실행)
           -- PR_DM_DNM_EDI_CALLOFF_MKT_FCST_EDI;
        */

        COMMIT;

    EXCEPTION
        WHEN OTHERS THEN
            ROLLBACK;

            V_LOG_TYPE := 'E';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := SUBSTR('ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 500);
            D_EVENT_DATE := SYSDATE;

            DBMS_OUTPUT.PUT_LINE(V_LOG_MESSAGE);

            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE
                               , NULL, SQLCODE, SQLERRM, DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
    END;

    /* 종료 LOG */
    V_LOG_TYPE := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    D_EVENT_DATE := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);


END PR_DM_ERP_EDI_MST_MODEL;

PROCEDURE PR_DM_IF_CHECK_SMS_SEND
/*====================================================================================================================
 * Program ID   : PR_DM_IF_CHECK_SMS_SEND
 * Description  : DM IF검증후 SMS발송대상 처리
 * OutTable     :
 * Execute      :
 * Program History
 *====================================================================================================================
 *   Date       In Charge		Description
 *====================================================================================================================
 * 2020.02.27   KHSONG			Initial Release [PS03209094B] SM이관 선행관리
 * 2021.01.25   P.C.I			[C20210204-000087] 판매법인(G260) 재고 추가
 * 2021.08.31	rosia27			[C20210721-000120] 소형사업부 VMI 실적 수신 BATCH JOB
 * 2021.10.05	rosia27			[C20210917-000233] 판매 법인 재고 IF 알람 로직 수정
 * 2021.11.05	rosia27			[C20211103-000324] VMI실적 관련 에러 문자 메세지가 발송 관련 건
 * 2024.03.22	jssbae			[E20240319-000706]_안정적인 운영을 위한 ERP 실적관련 프로세스 모니터링 및 작업추가 요청
 * 2025.01.01	P.C.I			[PJ20228272] NERP 대응. RFC Log 변경으로 SMS 전송 로직 수정
 * 2026.01.06	JSSBAE			[E20260106-000753]_EDI Calloff 데이터 IF 로직 개선
 * 2026.07.06	ZIONEX			[PJ202650304] NextSCM Migration
 *====================================================================================================================
	● 대상 List
	------------  --------------------------------  -----------------------------   --------------------------   ----------------------------------------------------------
	CATEGORY_ID	  CATEGORY_DESC						BATCH JOB NAME			        사유							 전송기준
	------------  --------------------------------  -----------------------------   --------------------------   ----------------------------------------------------------
	61			  Project Master Batch Error		PR_SCM_MST_PROJECT		        PROJECT 매핑시 필수정보	     배치로그 에러발견시
	62			  Project DV Batch Error			PR_SCM_MST_PROJECT_DV_MASTER	PROJECT 매핑시 필수정보	     배치로그 에러발견시
	63			  Project Item Mapping Batch Error  PR_SCM_MST_PROJECT_ITEM         PROJECT 매핑시 필수정보	     배치로그 에러발견시
	64			  Customer Master Batch Error		PR_SCM_MST_CUSTOMER             Sales Site 등록시 필수정보	 배치로그 에러발견시
	65			  SD0069 EDI Call off Batch Error   PR_DM_DNM_EDI_CALLOFF           CUST_FCST 수신확인 필요	     배치로그 에러 or 고객사별로 일주일동안 수신건이 없을 경우 => [E20260106-000753]_GERP 종료로 모니터링 제거
	66			  Sales Result Batch Error			PR_DM_DNM_SALES_RESULT_IF       ERP 실적. 주요정보		     수신된 데이터가 없는 경우 or 배치로그 에러발견시
	73			  Stock Sales Batch Error			PR_SCM_DNM_STOCK_SALES          판매법인(G260) 재고 		 배치로그 에러 or 당일 수신건이 없을 경우[C20210204-000087]
	79			  VMI 실적 Batch Error				PR_SCM_DNM_MAT_DOCUMENT			VMI 실적					 배치로그 에러 OR 당일 수신건이 없을 경우[C20211103-000324]
	------------  --------------------------------  -----------------------------   --------------------------   ----------------------------------------------------------
 ====================================================================================================================*/
 AS
    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME VARCHAR2(150 CHAR) := 'PR_DM_IF_CHECK_SMS_SEND';
    V_LOG_TYPE     VARCHAR2(30 CHAR);   /* START/END/ERROR/... */
    N_LOG_COUNT    INTEGER := 0;
    V_LOG_MESSAGE  VARCHAR2(1000 CHAR);
    V_DESCRIPTION  VARCHAR2(500 CHAR);
    D_EVENT_DATE   DATE;
    V_TEXT         VARCHAR2(200 CHAR);
    V_CODE         VARCHAR2(10 CHAR);
    V_PGM_NAME     VARCHAR2(100 CHAR);
    V_CNT          INTEGER := 0;         /* 건수 체크용(MSSQL 인라인 서브쿼리 IF → SELECT INTO) */

    CURSOR CURSOR_C1 IS
        SELECT PROGRAM_NAME
          FROM GT_PRDM_SCM_LOG_BATCH
         WHERE 1 = 1
         GROUP BY PROGRAM_NAME;
  BEGIN
    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := NULL;
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);


      BEGIN

        /* -------------------------------------------------------------------------------------------------------
         *                                                                                  JOB LIST TABLE 생성
         * ------------------------------------------------------------------------------------------------------- */
        /* MSSQL: #BATCH_JOB_NAME DROP/CREATE → GTT GT_PRDM_BATCH_JOB_NAME (ON COMMIT PRESERVE ROWS) 초기화 */
        DELETE
          FROM GT_PRDM_BATCH_JOB_NAME;

        INSERT
          INTO GT_PRDM_BATCH_JOB_NAME (CATEGORY_ID, PROGRAM_NAME)
        SELECT '61', 'PR_SCM_MST_PROJECT' FROM DUAL
        UNION ALL
        SELECT '62', 'PR_SCM_MST_PROJECT_DV_MASTER' FROM DUAL
        UNION ALL
        SELECT '63', 'PR_SCM_MST_PROJECT_ITEM' FROM DUAL
        UNION ALL
        SELECT '64', 'PR_SCM_MST_CUSTOMER' FROM DUAL
        /* [E20260106-000753]_GERP EDI 종료로 인하여 EDI 주석처리 (START) */
        /*
		UNION ALL
		SELECT '65','PR_DM_DNM_EDI_CALLOFF' FROM DUAL
		*/
        /* [E20260106-000753]_GERP EDI 종료로 인하여 EDI 주석처리 (END) */
        UNION ALL
        SELECT '66', 'PR_DM_DNM_SALES_RESULT_IF' FROM DUAL
        UNION ALL
        SELECT '73', 'PR_SCM_DNM_STOCK_SALES' FROM DUAL;

        /* -------------------------------------------------------------------------------------------------------
         *                                                                                       초기화 (BEGIN)
         * ------------------------------------------------------------------------------------------------------- */
        /* MSSQL: SELECT TOP 0 .. INTO #TEMP_SCM_LOG_BATCH (구조복제) → GTT GT_PRDM_SCM_LOG_BATCH 초기화 */
        DELETE
          FROM GT_PRDM_SCM_LOG_BATCH;
        /* -------------------------------------------------------------------------------------------------------
         *                                                                                         초기화 (END)
         * ------------------------------------------------------------------------------------------------------- */

        /* -------------------------------------------------------------------------------------------------------
         *                                                                         BATCH JOB ERROR 대상 (BEGIN)
         * ------------------------------------------------------------------------------------------------------- */
        INSERT
          INTO GT_PRDM_SCM_LOG_BATCH
             ( PROGRAM_NAME
             , LOG_TYPE
             , LOG_COUNT
             , LOG_MESSAGE
             , DESCRIPTION
             , EVENT_DATE
             , CREATION_DATE
             , CREATED_BY
             , LAST_UPDATE_DATE
             , LAST_UPDATED_BY
             , ATTRIBUTE1 )
        SELECT A.PROGRAM_NAME
             , A.LOG_TYPE
             , A.LOG_COUNT
             , A.LOG_MESSAGE
             , A.DESCRIPTION
             , A.EVENT_DATE
             , A.CREATION_DATE
             , A.CREATED_BY
             , A.LAST_UPDATE_DATE
             , A.LAST_UPDATED_BY
             , A.ATTRIBUTE1
          FROM SCM_SYS_LOG_BATCH      A
             , GT_PRDM_BATCH_JOB_NAME B
         WHERE A.PROGRAM_NAME = B.PROGRAM_NAME
           AND 1 = 1
           AND A.LOG_TYPE = 'ERROR'
           AND A.CREATION_DATE >= TRUNC(SYSDATE) - 1                          /* 하루전까지 */
           AND (A.ATTRIBUTE1 <> 'DM SMS SEND OK' OR A.ATTRIBUTE1 IS NULL);    /* SMS발송완료대상은 제외, ATTRIBUTE1은 초기값인 대상 */

        /* -------------------------------------------------------------------------------------------------------
         *                                    ERROR 케이스 처리 (update 는 성능이 느려서 delete/insert 로 수행)
         * ------------------------------------------------------------------------------------------------------- */


        /*
		IF EXISTS (SELECT 1 FROM SYS.SYSCURSORS WHERE CURSOR_NAME = 'CURSOR_C1')
			BEGIN
			END;
		*/
        OPEN CURSOR_C1;
        LOOP
            FETCH CURSOR_C1 INTO V_PGM_NAME;
            EXIT WHEN CURSOR_C1%NOTFOUND;

            DELETE
              FROM SCM_SYS_LOG_BATCH
             WHERE 1 = 1
               AND EXISTS (SELECT 1
                             FROM GT_PRDM_SCM_LOG_BATCH C
                            WHERE 1 = 1
                              AND SCM_SYS_LOG_BATCH.PROGRAM_NAME = C.PROGRAM_NAME)
               AND LOG_TYPE = 'ERROR'
               AND CREATION_DATE >= TRUNC(SYSDATE) - 1                        /* 하루전까지 */
               AND (ATTRIBUTE1 <> 'DM SMS SEND OK' OR ATTRIBUTE1 IS NULL);    /* SMS발송완료대상은 제외, ATTRIBUTE1은 초기값인 대상 */

            INSERT
              INTO SCM_SYS_LOG_BATCH
                 ( PROGRAM_NAME
                 , LOG_TYPE
                 , LOG_COUNT
                 , LOG_MESSAGE
                 , DESCRIPTION
                 , EVENT_DATE
                 , CREATION_DATE
                 , CREATED_BY
                 , LAST_UPDATE_DATE
                 , LAST_UPDATED_BY
                 , ATTRIBUTE1 )
            SELECT PROGRAM_NAME
                 , LOG_TYPE
                 , LOG_COUNT
                 , LOG_MESSAGE
                 , DESCRIPTION
                 , EVENT_DATE
                 , CREATION_DATE
                 , CREATED_BY
                 , LAST_UPDATE_DATE
                 , LAST_UPDATED_BY
                 , 'DM SMS SEND OK'
              FROM GT_PRDM_SCM_LOG_BATCH
             WHERE PROGRAM_NAME = V_PGM_NAME;

            SELECT CATEGORY_ID
              INTO V_CODE
              FROM GT_PRDM_BATCH_JOB_NAME
             WHERE PROGRAM_NAME = V_PGM_NAME;

            V_TEXT := '[Job오류발생 : ' || V_PGM_NAME || ']';

            SCM_ADM_SMS_SEND_BATCH(TO_NUMBER(V_CODE), V_TEXT);

        END LOOP;
        CLOSE CURSOR_C1;

        /* -------------------------------------------------------------------------------------------------------
         *                                                                         BATCH JOB ERROR 대상 (END)
         * ------------------------------------------------------------------------------------------------------- */

        /* -------------------------------------------------------------------------------------------------------
         *                                                                    수신된 데이터가 없는 대상 (BEGIN)
         * ------------------------------------------------------------------------------------------------------- */
        IF TO_CHAR(SYSDATE, 'HH24') = '08' THEN   /* 하루 1회 08시에만 수행함. */
            /* -------- */
            /* [E20260106-000753]_GERP EDI 종료로 인하여 EDI 주석처리 (START) */
            /*
			--------------------------------
			-- (1) PR_DM_DNM_EDI_CALLOFF
			--------------------------------
			IF ( SELECT COUNT(1) FROM LGCE_INF.DBO.XIF_ERP_EDI_CALLOFF_ITEM_R WITH(NOLOCK)
				 WHERE TRANSFER_CREATE_DATE >= CONVERT(CHAR(8),GETDATE()-7,112)  -- 일주일간 수신데이터가 없는경우
				) < 1  -- 데이터가 존재하지 않는경우
			BEGIN
				SET @v_text = ''
				SET @v_code = ''
				SET @v_text = N'[일주일간 수신데이터가 없음 : ' + 'PR_DM_DNM_EDI_CALLOFF' + N']'
				SET @v_code = (SELECT CATEGORY_ID FROM #BATCH_JOB_NAME WHERE PROGRAM_NAME = 'PR_DM_DNM_EDI_CALLOFF')
				EXEC SCM_ADM_SMS_SEND_BATCH	@v_code, @v_text
			END
		*/
            /* [E20260106-000753]_GERP EDI 종료로 인하여 EDI 주석처리 (END) */

            /* -------------------------------- */
            /* (2) PR_DM_DNM_SALES_RESULT_IF */
            /* -------------------------------- */
            SELECT COUNT(*)
              INTO V_CNT
              FROM (SELECT SUBSTR(TRANSFER_DATE, 1, 8) || SUBSTR(TRANSFER_TIME, 1, 2)   /* 24시간동안 3건의 배치작업 데이터 */
                      FROM XIF_ERP_SALES_RESULT_R_SN
                     WHERE SUBSTR(TRANSFER_DATE, 1, 8) || SUBSTR(TRANSFER_TIME, 1, 2) >= TO_CHAR(SYSDATE - 1, 'YYYYMMDD') || TO_CHAR(SYSDATE, 'HH24')   /* 24시간동안의 데이터 */
                     GROUP BY SUBSTR(TRANSFER_DATE, 1, 8) || SUBSTR(TRANSFER_TIME, 1, 2)   /* 날짜8자리+시간2자리 */
                     FETCH FIRST 3 ROWS ONLY
                   );
            IF V_CNT < 3 THEN   /* 24시간내에 3번의 작업이 되어야 정상임 */
                V_TEXT := '[24시간내 3회 미만 작업됨 : ' || 'PR_DM_DNM_SALES_RESULT_IF' || ']';
                SELECT CATEGORY_ID
                  INTO V_CODE
                  FROM GT_PRDM_BATCH_JOB_NAME
                 WHERE PROGRAM_NAME = 'PR_DM_DNM_SALES_RESULT_IF';
                SCM_ADM_SMS_SEND_BATCH(TO_NUMBER(V_CODE), V_TEXT);
            END IF;

        /* -------- */
        END IF;
        /* -------- */

        IF TO_CHAR(SYSDATE, 'HH24') = '10' THEN   /* 하루 1회 10시에만 수행함.[C20210204-000087] */
            /* -------- */
            /* -------------------------------- */
            /* (3) PR_SCM_DNM_STOCK_SALES */
            /* -------------------------------- */
            /* [C20210917-000233] 판매 법인 재고 IF 알람 로직 수정 */
            SELECT COUNT(1)
              INTO V_CNT
              FROM XIF_ERP_SALES_STOCK_R_SN
             WHERE TRANSFER_DATE = TO_CHAR(SYSDATE, 'YYYYMMDD');   /* 당일 수신데이터가 없는경우 */
            IF V_CNT < 1 THEN   /* 데이터가 존재하지 않는경우 */
                V_TEXT := '[당일 수신데이터가 없음 : ' || 'PR_SCM_DNM_STOCK_SALES' || ']';
                SELECT CATEGORY_ID
                  INTO V_CODE
                  FROM GT_PRDM_BATCH_JOB_NAME
                 WHERE PROGRAM_NAME = 'PR_SCM_DNM_STOCK_SALES';
                SCM_ADM_SMS_SEND_BATCH(TO_NUMBER(V_CODE), V_TEXT);
            END IF;
            /* -------- */
        END IF;
        /* -------- */

        /* [C20210721-000120] 소형사업부 VMI 실적 수신 BATCH JOB */
        IF TO_CHAR(SYSDATE, 'HH24') = '10' THEN   /* 하루 1회 10시에만 수행함. */
            /* -------- */
            /* -------------------------------- */
            /* (4) PR_SCM_DNM_MAT_DOCUMENT */
            /* -------------------------------- */
            /* [PJ20228272] NERP 대응. RFC Log 변경으로 SMS 전송 로직 수정 Start */
            /*
			IF NOT EXISTS (SELECT LOG_TYPE	FROM SCM_SYS_LOG_BATCH
				WHERE PROGRAM_NAME = N'XIF_ERP_MATERIAL_DOCUMENT_DM_R'
				AND LOG_TYPE='Success of RFC Call'
				AND CREATION_DATE >= CONVERT(CHAR(10),GETDATE(),120))
				*/
            /* [PJ20228272] NERP 대응. RFC Log 변경으로 SMS 전송 로직 수정 End */
            /* NOT EXISTS → COUNT(*) = 0 */
            SELECT COUNT(*)
              INTO V_CNT
              FROM SCM_SYS_LOG_BATCH
             WHERE PROGRAM_NAME = 'SAPRFC_Batch_NERP'
               AND LOG_TYPE = 'XIF_ERP_MATERIAL_DOCUMENT_DM_R'
               AND LOG_MESSAGE = 'INSERT'
               AND LOG_COUNT > 0
               AND CREATION_DATE >= TRUNC(SYSDATE);   /* CONVERT(CHAR(10),GETDATE(),120) = 당일 00:00 */
            IF V_CNT = 0 THEN
                V_CODE := '79';
                V_TEXT := '[Job오류발생 : PR_SCM_DNM_MAT_DOCUMENT( VMI 실적 )]';
                SCM_ADM_SMS_SEND_BATCH(TO_NUMBER(V_CODE), V_TEXT);
            END IF;
            /* -------- */
        END IF;
        /* -------- */

        /* [E20240319-000706]_안정적인 운영을 위한 ERP 실적관련 프로세스 모니터링 및 작업추가 요청 20240322 */
        /* 일요일 배치 미실행시 해당 문구 발송예정 */
        /* ------------------------------------------------------------------------------------------------------------------------ */
        /* 1.JOB_RFC.DM_VMI_재고 입출고 실적 */
        /* ------------------------------------------------------------------------------------------------------------------------ */
        IF TO_CHAR(SYSDATE, 'HH24') = '13' THEN
            BEGIN
                SELECT COUNT(1)
                  INTO V_CNT
                  FROM XIF_ERP_MATERIAL_DOCUMENT_DM_R_SN
                 WHERE TRANSFER_DATE = TO_CHAR(SYSDATE, 'YYYYMMDD');   /* 당일 수신데이터가 없는경우 */
                IF V_CNT < 1 THEN   /* 데이터가 존재하지 않는경우 */
                    /* VMI실적 BATCH ERROR */
                    V_CODE := '79';
                    V_TEXT := '[★★VMI재고입출고실적 ERP배치실행필요★★ : JOB_RFC.DM_VMI_재고 입출고 실적' || ']';
                    SCM_ADM_SMS_SEND_BATCH(TO_NUMBER(V_CODE), V_TEXT);
                END IF;
            END;

            /* ------------------------------------------------------------------------------------------------------------------------ */
            /* 2.JOB_RFC.매출 실적 정보 */
            /* ------------------------------------------------------------------------------------------------------------------------ */
            BEGIN
                SELECT COUNT(1)
                  INTO V_CNT
                  FROM XIF_ERP_SALES_RESULT_R_SN
                 WHERE TRANSFER_DATE = TO_CHAR(SYSDATE, 'YYYYMMDD');   /* 당일 수신데이터가 없는경우 */
                IF V_CNT < 1 THEN   /* 데이터가 존재하지 않는경우 */
                    V_TEXT := '[★★매출실적정보 ERP배치실행필요★★ : JOB_RFC.매출 실적 정보' || ']';
                    SELECT CATEGORY_ID
                      INTO V_CODE
                      FROM GT_PRDM_BATCH_JOB_NAME
                     WHERE PROGRAM_NAME = 'PR_DM_DNM_SALES_RESULT_IF';
                    SCM_ADM_SMS_SEND_BATCH(TO_NUMBER(V_CODE), V_TEXT);
                END IF;
            END;

            /* ------------------------------------------------------------------------------------------------------------------------ */
            /* 3.JOB_RFC.판매법인(G260) 재고 */
            /* ------------------------------------------------------------------------------------------------------------------------ */
            BEGIN
                SELECT COUNT(1)
                  INTO V_CNT
                  FROM XIF_ERP_SALES_STOCK_R_SN
                 WHERE TRANSFER_DATE = TO_CHAR(SYSDATE, 'YYYYMMDD');   /* 당일 수신데이터가 없는경우 */
                IF V_CNT < 1 THEN   /* 데이터가 존재하지 않는경우 */
                    V_TEXT := '[★★매출실적정보 ERP배치실행필요★★ : JOB_RFC.판매법인(G260) 재고' || ']';
                    SELECT CATEGORY_ID
                      INTO V_CODE
                      FROM GT_PRDM_BATCH_JOB_NAME
                     WHERE PROGRAM_NAME = 'PR_SCM_DNM_STOCK_SALES';
                    SCM_ADM_SMS_SEND_BATCH(TO_NUMBER(V_CODE), V_TEXT);
                END IF;
            END;

            /* ------------------------------------------------------------------------------------------------------------------------ */
            /* 4.전지사업본부 MDF(판매장려금) 실적 정보 */
            /* ------------------------------------------------------------------------------------------------------------------------ */
            /* [PJ20228272] NERP 대응. 사용하지 않는 데이터이므로 SMS 전송 목록에서 삭제 */
            /*
			BEGIN
				IF (
						SELECT COUNT(1) FROM DBO.XIF_ERP_FI_MDF_R_SN WITH(NOLOCK)
							WHERE TRANSFER_DATE = CONVERT(CHAR(8),GETDATE(),112)  -- 당일 수신데이터가 없는경우
					   ) < 1  -- 데이터가 존재하지 않는경우
						BEGIN
							SET @v_text = ''
							SET @v_code = '98'
							SET @v_text = N'[★★MDF실적정보 ERP배치실행필요★★ : JOB.PR_DM_PLN_XIF_ERP_MDF_TO_DM_MDF_RESULT' + N']'
							EXEC SCM_ADM_SMS_SEND_BATCH	@v_code, @v_text
						END
			END*/
        END IF;
        /* -------------------------------------------------------------------------------------------------------
         *                                                                    수신된 데이터가 없는 대상 (END)
         * ------------------------------------------------------------------------------------------------------- */


      EXCEPTION
        /* ----------
         * BEGIN CATCH (Oracle: 에러 LOG 직접 INSERT 후 재발생)
         * ---------- */
        WHEN OTHERS THEN
            /* ERROR LOG (SQLERRM 은 정적 INSERT VALUES 직접 사용 불가 → 지역변수로) */
            V_LOG_MESSAGE := SQLERRM;
            INSERT
              INTO SCM_SYS_LOG_BATCH
                 ( PROGRAM_NAME
                 , LOG_TYPE
                 , LOG_COUNT
                 , LOG_MESSAGE
                 , DESCRIPTION
                 , EVENT_DATE
                 , CREATION_DATE
                 , CREATED_BY
                 , LAST_UPDATE_DATE
                 , LAST_UPDATED_BY )
            VALUES ( V_PROGRAM_NAME
                 , 'ERROR'
                 , NULL
                 , V_LOG_MESSAGE
                 , NULL
                 , SYSDATE
                 , SYSDATE
                 , V_PROGRAM_NAME
                 , SYSDATE
                 , V_PROGRAM_NAME );
            COMMIT;
            /* MSSQL BEGIN CATCH: 에러로그 INSERT 후 RAISERROR/THROW 없이 return -1 (삼킴·호출자 예외전파 없음, 종료LOG도 생략) */

            RETURN;
      END;

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := NULL;
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);


    COMMIT;

  END PR_DM_IF_CHECK_SMS_SEND;

PROCEDURE         PR_DM_IRREGULAR_SALES_PLAN_CUTOFF_MAIL_SEND

(
    P_DIVISION_ID   VARCHAR2 /* DIVISION_ID */
   ,P_CREATION_TYPE VARCHAR2 /* [E20250529-001289]_생성에 따라 메일링 문구가 다르기 때문에, 배치일정을 기본으로 셋팅한다. */
)
/*==============================================================================================================================
    * Program ID   : PR_DM_IRREGULAR_SALES_PLAN_CUTOFF_MAIL_SEND
    * Description  : Sales Plan 정기 CUTOFF 외 SCP에서 CALL하여 CUTOFF 진행되는 경우 메일 발송
    * Parameter    : Division, p_creation_type--[E20250529-001289]_추가
    * Program History
    *==============================================================================================================================
    *   Date       In Charge Description
    *==============================================================================================================================
    * 2025-02-24 JSSBAE        [E20250210-000219]_SCP 엔진 재수행에 따른 Sales Plan Cutoff 재수행 자동화
    * 2025-06-05 JSSBAE        [E20250529-001289]_DM 장애 대응 개선을 위한 시스템 개선
    * 2026-03-23   김준규        [PJ20264226] NextSCM Pilot 설계 및 개발
    * 2026-03-27   김준규        P_CATEGORY_ID 입력 변수 number 이기에 '-' 를 0 으로 변경

    * PR_DM_IRREGULAR_SALES_PLAN_CUTOFF_MAIL_SEND(p_division_id='82', p_creation_type='REGULAR');
 * 2026.07.06	ZIONEX		[PJ202650304] NextSCM Migration
    ==============================================================================================================================*/
 AS

    V_PROGRAM_NAME  VARCHAR2(200 CHAR) := $$PLSQL_UNIT;
    V_STEP          VARCHAR2(4000 CHAR) := NULL;
    V_LOG_TYPE      VARCHAR2(30 CHAR);
    N_LOG_COUNT     INTEGER := 0;
    V_LOG_MESSAGE   VARCHAR2(1000 CHAR);
    V_DESCRIPTION   VARCHAR2(500 CHAR);
    D_EVENT_DATE    DATE;
    V_MAX_NO        VARCHAR2(30 CHAR);
    V_TABLE_BODY    VARCHAR2(4000 CHAR);
    V_BODY_CONTENTS VARCHAR2(4000 CHAR);
    V_HEAD_CONT     VARCHAR2(4000 CHAR);
    V_BODY_CONT     VARCHAR2(4000 CHAR);
    V_MAIL_TITLE    VARCHAR2(150 CHAR);
    /* [2026-10-06] 동일 내용 메일을 수신자 ; 묶음으로 발송(사용자 결정 B) — 수신자 문자열이 길어져 확장.
     * 상한 4000 = 하위 PKG_SEND_MAIL 수신자 파라미터 정합. GTT GT_DISP_T_MAIL_ADDR.ADDR 은
     * VARCHAR2(150 CHAR) 라 묶은 문자열을 담을 수 없어 GTT 를 건드리지 않고 PL/SQL 슬롯에 담는다
     * (동반객체 DDL 변경이 없어 사내망 반출 품목이 늘지 않는다 · 행 3·4 와 같은 패턴). */
    V_OWNER         VARCHAR2(4000 CHAR);
    C_TO_MAIL_MAX   CONSTANT PLS_INTEGER := 4000;
    TYPE T_ADDR_TAB IS TABLE OF VARCHAR2(4000 CHAR) INDEX BY PLS_INTEGER;
    V_ADDR_SLOT     T_ADDR_TAB;
    V_SLOT_CNT      PLS_INTEGER := 0;
    V_OWNER_TYPE    CHAR(3);
    V_LIKE_STRING   VARCHAR2(100 CHAR);
    V_CNT           INTEGER;
    V_I             INTEGER;
    V_CNT_1         INTEGER := 0;
    V_IN_PARA_DATA  VARCHAR2(4000 CHAR);
BEGIN

    IF UTL_CALL_STACK.SUBPROGRAM(1).COUNT > 1 THEN
        V_PROGRAM_NAME := $$PLSQL_UNIT || '.' || UTL_CALL_STACK.SUBPROGRAM(1) (2);
    END IF;

    V_IN_PARA_DATA := JSON_OBJECT('p_division_id' VALUE P_DIVISION_ID, 'p_creation_type' VALUE P_CREATION_TYPE);

    /* ================================================================================================= */
    /* STEP 01. LOG 저장 (변수 생성 및 실행) */
    /* ================================================================================================= */
    /* ------------------------------------------------------------------------------------------------ */
    /* LOG 용 변수 설정 */
    /* ------------------------------------------------------------------------------------------------ */
    /* 시작 LOG (START) */
    /* ------------------------------------------------------------------------------------------------ */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '##### Start of procedure #####';
    V_DESCRIPTION := 'Sales Plan CUTOFF 후 알림 메일 발송';
    D_EVENT_DATE  := SYSTIMESTAMP;

    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    /* ------------------------------------------------------------------------------------------------ */
    /* 시작 LOG (END) */
    /* ------------------------------------------------------------------------------------------------ */

    BEGIN
        EXECUTE IMMEDIATE 'TRUNCATE TABLE GT_DISP_SALES_PLAN_CUTOFF';
    /* ================================================================================================= */
    /* STEP 02. 임시테이블 / 변수 생성 */
    /* ================================================================================================= */
    DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME || ' A001: ' || 'DIVISION_ID: ' || P_DIVISION_ID || ' / CREATION_TYPE: ' || P_CREATION_TYPE || ' / ' ||
                         TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));
    /* ================================================================================================= */
    /* STEP 03. 호출된 날짜로 SALES PLAN CUTOFF가 진행된 내역이 있는지 데이터 보관 */
    /* ================================================================================================= */
    BEGIN

        SELECT MAX(VERSION_NO)
          INTO V_MAX_NO
          FROM DM_MST_VERSION
         WHERE VERSION_TYPE = 'SP_W'
           AND DIVISION_ID = P_DIVISION_ID
           AND TO_CHAR(CREATION_DATE, 'YYYYMMDD') = TO_CHAR(SYSDATE, 'YYYYMMDD');

        INSERT
          INTO GT_DISP_SALES_PLAN_CUTOFF
        SELECT DIVISION_ID
             , VERSION_NO
             , VERSION_DESCRIPTION
             , VERSION_TYPE
             , CREATED_BY
             , CREATION_DATE
          FROM DM_MST_VERSION
         WHERE DIVISION_ID = P_DIVISION_ID
           AND VERSION_NO = V_MAX_NO;
    END;

    DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME || ' A002: ' || 'DIVISION_ID: ' || P_DIVISION_ID || ' / MAX_VERSION_NO: ' || V_MAX_NO || ' / ' ||
                         TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));
    /* ================================================================================================= */
    /* STEP 04. 메일발송 대상 */
    /* ================================================================================================= */
    BEGIN
        EXECUTE IMMEDIATE 'TRUNCATE TABLE GT_DISP_T_MAIL_ADDR';

        /* 룩업에 등록된 대상에 대해서만 메일을 발송한다. */
        INSERT
          INTO GT_DISP_T_MAIL_ADDR
             ( ADDR
             , SEQ )
        SELECT A.SEGMENT2
             , (ROW_NUMBER() OVER (ORDER BY A.SEGMENT2)) - 1
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL A
         WHERE A.LOOKUP_TYPE = 'DM_IRREGULAR_SALES_PLAN_CUTOFF_MAIL_ADDR'
           AND (A.SEGMENT1 = P_DIVISION_ID OR A.SEGMENT1 = 'ALL')
           AND A.VALID_YN = 'Y';
    END;
    DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME || ' A003: ' || 'DIVISION_ID: ' || P_DIVISION_ID || ' / MAX_VERSION_NO: ' || V_MAX_NO || ' / ' ||
                         TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));

    /* ================================================================================================= */
    /* STEP 05. 메일발송 - 전송대상만큼 반복 (헤더, 본문) */
    /* ================================================================================================= */
    BEGIN

        /* STEP 05-1. 테이블 HEADER */
        /* ------------------------------------------------------------------------------------------------ */
        /* v_mail_title := 'Sales Plan Cutoff 재수행' --[E20250529-001289]_정기적으로 CUTOFF 진행하는 SALES PLAN에 대해서도 CUTOFF를 요청하여 문구 분기처리하기 위해 원소스 주석처리 */
        /* ------------------------------------------------------------------------------------------------ */
        /* [E20250529-001289]_정기배치인 경우는 문구 수행완료, 비정기로 발생한 건은 재수행완료로 메시지 셋팅 START */
        /* ------------------------------------------------------------------------------------------------ */
        IF P_CREATION_TYPE = 'REGULAR' THEN
            V_MAIL_TITLE := 'Sales Plan Cutoff 수행완료';
        ELSE
            V_MAIL_TITLE := 'Sales Plan Cutoff 재수행완료';
        END IF;
        /* ------------------------------------------------------------------------------------------------ */
        /* [E20250529-001289]_정기배치인 경우는 문구 수행완료, 비정기로 발생한 건은 재수행완료로 메시지 셋팅 END */
        /* ------------------------------------------------------------------------------------------------ */
        /* 운영용 */
        V_BODY_CONTENTS := '안녕하십니까, SCM.DM 시스템입니다. </br> ';
        /* || 'Sales Plan Cutoff가 재생성되어, 생성된 버전 안내드립니다. </br> ' --[E20250529-001289]_정기적으로 CUTOFF 진행하는 SALES PLAN에 대해서도 CUTOFF를 요청하여 문구 분기처리하기 위해 원소스 주석처리 */
        /* 개발용
        v_body_contents := '개발시스템 TEST 진행중입니다. </br> ';
                             || '안녕하십니까, SCM.DM 시스템입니다.  </br> '
                             --|| 'Sales Plan Cutoff가 재생성되어, 생성된 버전 안내드립니다. </br> ' --[E20250529-001289]_정기적으로 CUTOFF 진행하는 SALES PLAN에 대해서도 CUTOFF를 요청하여 문구 분기처리하기 위해 원소스 주석처리
        */
        /* ------------------------------------------------------------------------------------------------ */
        /* [E20250529-001289]_정기배치인 경우는 문구 수행완료, 비정기로 발생한 건은 재수행완료로 메시지 셋팅 START */
        /* ------------------------------------------------------------------------------------------------ */
        IF P_CREATION_TYPE = 'REGULAR' THEN
            V_BODY_CONTENTS := V_BODY_CONTENTS || 'Sales Plan Cutoff가 생성되어, 생성된 버전 안내드립니다. </br> ';
        ELSE
            V_BODY_CONTENTS := V_BODY_CONTENTS || 'Sales Plan Cutoff가 재생성되어, 생성된 버전 안내드립니다. </br> ';
        END IF;
        /* ------------------------------------------------------------------------------------------------ */
        /* [E20250529-001289]_정기배치인 경우는 문구 수행완료, 비정기로 발생한 건은 재수행완료로 메시지 셋팅 END */
        /* ------------------------------------------------------------------------------------------------ */
        /* [2026-10-07] 본문 화살표를 원본 표기로 복원 (상시지시 : 기능·로직 영향 없는 표기 차이는 원본을 따른다).
         * 원본 MSSQL : N'Report → Waterfall → Sales Plan Waterfall 화면에서 …' — 화살표 문자 →
         * 변환본이 ASCII '-->' 로 바꿔 놓아 받는 사람 본문에 '-->' 가 찍혔다(교차수행이 본문 차이로 잡았다).
         * 같은 화살표를 쓰는 다른 메일객체 2건(DMF0070_AUTO_PR_REQUEST_MAIL ·
         * PR_DM_DNM_SALES_PRICE_EXIST_MAIL_SEND)은 → 를 유지했다 — 3건 중 이 건만 바뀐 변환 비일관이었다. */
        V_BODY_CONTENTS := V_BODY_CONTENTS || 'Report → Waterfall → Sales Plan Waterfall 화면에서 해당 버전 조회 가능하십니다. </br>' || P_DIVISION_ID || ' Version: ' ||
                           V_MAX_NO || ' </br></br>';
        V_BODY_CONT     := NULL;

        DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME || ' A004: ' || V_BODY_CONT);
        /* --------------------------------------------------------------------------------------------------- */
        /* STEP 05-2. 테이블 반복 내용 */
        /* --------------------------------------------------------------------------------------------------- */
        /* [2026-10-06] 수신자를 ; 로 묶는다 — 본문이 수신자와 무관하게 동일하므로 한 통으로 보낸다.
         * 원본 MSSQL 은 [E20260529-001499] 로 「5명씩」 묶었는데 Oracle 변환본은 그 변경이 미반영된
         * 「한 명씩」이었다. 사용자 결정 B 에 따라 동일 본문 전체를 한 통으로 묶는다.
         * 4000바이트를 넘으면 슬롯을 더 만들어 나눠 보낸다(주소가 늘어도 ORA-01489/12899 가 없다). */
        V_SLOT_CNT := 0;

        FOR A IN ( SELECT ADDR
                     FROM GT_DISP_T_MAIL_ADDR
                    WHERE ADDR IS NOT NULL
                    ORDER BY SEQ ) LOOP
            IF V_SLOT_CNT = 0
               OR LENGTHB(V_ADDR_SLOT(V_SLOT_CNT) || ';' || A.ADDR) > C_TO_MAIL_MAX THEN
                V_SLOT_CNT := V_SLOT_CNT + 1;
                V_ADDR_SLOT(V_SLOT_CNT) := A.ADDR;
            ELSE
                V_ADDR_SLOT(V_SLOT_CNT) := V_ADDR_SLOT(V_SLOT_CNT) || ';' || A.ADDR;
            END IF;
        END LOOP;

        V_CNT := V_SLOT_CNT;
        DBMS_OUTPUT.PUT_LINE(' V_CNT : ' || V_CNT);
        V_I := 0;

        WHILE (V_I < V_CNT) LOOP
            V_OWNER := V_ADDR_SLOT(V_I + 1);   /* 슬롯은 1부터 */

            V_TABLE_BODY := ' <html>
<head>
											<title>Untitled Document</title>
											<style>
												* {margin:0;padding:0;}
												body {font-family:Malgun Gothic, Arial, Helvetica, sans-serif;font-size:12px;line-height:1.8;color:#333333;}
												table {border-collapse:collapse;width:100%;}
												table th {background:#f5f5f5;border-bottom:1px solid #e1e1e1;}
												table td {background:#fff;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1;border-bottom:1px solid #e1e1e1;}
												table tbody th {border-left:1px solid #e1e1e1;text-align:right;padding:6px 8px;font-size:12px}
												table tbody td {padding:6px 8px;font-size:12px}
												table thead th {text-align:center;padding:3px;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1; border-bottom:1px solid #d1d1d1;font-size:12px}
												.hori-table table thead td {text-align:center;padding:3px;}
												.hori-table table tbody td {text-align:center;padding:3px;}
												.vertical-table, .hori-table {margin-bottom:20px;}
											</style>
										</head>
										<body></br><b>' || REPLACE(V_BODY_CONTENTS, CHR(10), '<br>') || '</b>' ||
                            '<div id="divBody" style="width: 100%; overflow-x: auto; overflow-y: auto; font-size: 9pt; line-break: auto;">' ||
                            /* [2026-10-07] HTML 속성 따옴표를 원본대로 복원 (사용자 결정 「원본을 따라간다」).
                             * 원본 MSSQL : N'<table style=''border-top:…;''>'  → T-SQL 이스케이프라 `'` 한 개가 나간다.
                             * 변환본이 이것을 `"` 로 바꿔 놓아 생성 HTML 이 style="…" 가 됐다.
                             * HTML 상 기능은 동일하지만, 같은 관용구를 쓰는 메일객체 14건 중 12건은 ''를 유지했고
                             * 교차수행(행10 · 77통)에서 유일한 본문 차이가 이 2자였다. 원본 충실·14건 일관으로 되돌린다.
                             * ★같은 줄의 <div id="divBody" …> 의 " 는 원본에도 " 라서 손대지 않는다. */
                            '<table style=''border-top:2px solid #c8294b; width:1450px;''>
											<thead>' || V_HEAD_CONT || '</thead>
											<tbody>' || V_BODY_CONT || '</tbody>
											</div>
										</body>
									</html>';

            /* --------------------------------------------------------------------------------------------------- */
            /* STEP 05-3. Mail 전송 */
            /* --------------------------------------------------------------------------------------------------- */
            /* 실제로 생성된 버전이 존재하는 경우에만 메일을 발송한다. */
            SELECT COUNT(*)
              INTO V_CNT_1
              FROM GT_DISP_SALES_PLAN_CUTOFF;
            IF V_CNT_1 > 0 THEN
                /*
                    , v_mail_title
                    , 'Y'
                */
                /* 현업한테 가는 메일은 운영일 경우에만 발송함. */
                /* 발송 환경 가드 교정(2026-10-06) : 원본 IF DB_NAME() <> 'LGCE_SCMDEV' 는 사내망 MSSQL 이
                   개발·품질 둘 다 DB 이름 LGCE_SCMDEV 라 운영 전용 조건이다. Oracle 엔 그 이름의 DB 가 없어
                   항상 참(=항상 발송)이 되므로 운영 PDB 일치 조건 LIKE 'OCGSCMP%' 로 교체했다. */
                IF SYS_CONTEXT('USERENV', 'DB_NAME') LIKE 'OCGSCMP%' THEN
                    PKG_SEND_MAIL.P_SEND_MAIL(V_OWNER, V_MAIL_TITLE, V_TABLE_BODY, 'Y');
                END IF;

                /* MAIL 발송 LOG 저장 */

                /* [2026-10-07] 로그에 넘기는 수신자를 100자로 자른다 (사용자 결정 가).
                 * SCM_ADM_SMS_MAIL_SEND_LOG.SEGMENT2 는 VARCHAR2(100) 이고 하위 프로시저에 길이 보정이 없어
                 * 2026-10-06 묶음 교정으로 V_OWNER 가 길어진 뒤에는 주소 2~3개만 묶여도
                 * ORA-12899 -> ORA-20001 로 RAISE 되어 **발송 루프가 중단**된다(2026-10-07 실측 150자부터 터짐).
                 * 발송에는 전체 V_OWNER 를 그대로 쓰고 **로그에만** 자른다.
                 * 원본 MSSQL 도 @p_segment2 가 nvarchar(150) 이라 잘린 뒤 컬럼(100)에서 터지는 같은 구조다. */
                SCM_ADM_SAVE_MAIL_SEND_BATCH_LOG('MAIL', 0, V_PROGRAM_NAME, SUBSTR(V_OWNER, 1, 100), '', '', '', '', '', '', '', '', '', '');
            END IF;

            /* [2026-10-06] 발송 간 대기 삭제 — 수신자를 묶어 보내므로 통수가 줄어 대기의 목적
             * (메일서버 부하 분산)이 사라졌다(사용자 지시). 원본 MSSQL 의 WAITFOR DELAY 는 그대로 둔다.
             * 삭제한 블록 : IF (MOD(V_I, 5) IN (0, 5)) THEN SYS.DBMS_SESSION.SLEEP(30); END IF; */
            V_I := V_I + 1;
        END LOOP;

        DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME || ' A005: ' || 'DIVISION_ID: ' || P_DIVISION_ID || ' / MAX_VERSION_NO: ' || V_MAX_NO || ' / ' ||
                             TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));
    END;

    COMMIT;

    EXCEPTION
        WHEN OTHERS THEN
            ROLLBACK;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME
                                ,'ERROR'
                                ,0
                                ,SQLERRM
                                ,NULL
                                ,SYSDATE
                                ,P_IN_PARA_DATA  => V_IN_PARA_DATA
                                ,P_SQL_ERR_CODE  => SQLCODE
                                ,P_SQL_ERR_MSG   => SQLERRM
                                ,P_SQL_BACKTRACE => DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
    END;

    /* ================================================================================================= */
    /* 종료 LOG (START) */
    /* ================================================================================================= */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '##### END of procedure #####';
    V_DESCRIPTION := 'Sales Plan CUTOFF 후 알림 메일 발송';
    D_EVENT_DATE  := SYSTIMESTAMP;

    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    /* ================================================================================================= */
    /* 종료 LOG (END) */
    /* ================================================================================================= */
END;

PROCEDURE           "PR_DM_LONGPLAN_40_BACKUP" 

(
      P_DIVISION_ID   IN VARCHAR2
    , P_CREATED_BY    IN VARCHAR2
)
/*
 * Program ID   : PR_DM_LONGPLAN_40_BACKUP (소형 중장기 - SP/BP 데이터 백업)
 * Called by    : 필요에 의해 직접 수행(수동 유틸리티)
 * 변환(MSSQL->Oracle) 2026-07-01 SCMADM : 구 파손(BEGIN TRY·본문중DECLARE) 재작성(LONGPLAN 형제)
 *   - ISDATE(x)<1 → NULL체크+TO_DATE블록. GETDATE→SYSDATE, CONVERT(CHAR8,112)→TO_CHAR(,'YYYYMMDD'), DATEADD(DD,-7,FN_NEXT_DAY)→FN_NEXT_DAY-7
 *   - 버전생성/SP재계산 EXEC→호출(PR_DM_PLN_VERSION_CREATE OUT 2개, PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW). 검증 DIFF→DBMS_OUTPUT(H-9)
 *   - MKT_FCST/CFM/SALES_PLAN → _C 백업(버전 스탬프). 의존 모두 VALID
 * 2026.07.06	ZIONEX		[PJ202650304] NextSCM Migration
 */
AS
    V_PROGRAM_NAME             VARCHAR2(150 CHAR) := 'PR_DM_LONGPLAN_40_BACKUP';
    V_LOG_TYPE                 VARCHAR2(30 CHAR);
    N_LOG_COUNT                INTEGER := 0;
    V_LOG_MESSAGE              VARCHAR2(1000 CHAR);
    V_DESCRIPTION              VARCHAR2(500 CHAR);
    V_ERRMSG                   VARCHAR2(1000 CHAR);
    D_EVENT_DATE               DATE;
    V_MF_VERSION               VARCHAR2(100 CHAR);
    V_SP_VERSION               VARCHAR2(100 CHAR);
    V_RESTRICT_START_YYYYMMDD  VARCHAR2(8 CHAR);
    V_OK_DESCRIPTION           VARCHAR2(1200 CHAR);
    V_DUMMY                    DATE;
    V_CNT                      NUMBER;
    V_MONDAY                   VARCHAR2(8 CHAR);
BEGIN
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := 'p_division_id :' || P_DIVISION_ID || '/ p_created_by :' || P_CREATED_BY || '/ 소형 중장기';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    V_LOG_MESSAGE := NULL;

    BEGIN
        V_MONDAY := TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7, 'YYYYMMDD');

        /* 1. 입력제한일 */
        SELECT MAX(ATTRIBUTE1) INTO V_RESTRICT_START_YYYYMMDD
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
         WHERE LOOKUP_TYPE = 'DM_LONG_PLAN_START_YYYYMMDD' AND SEGMENT1 = P_DIVISION_ID AND VALID_YN = 'Y';
        IF V_RESTRICT_START_YYYYMMDD IS NULL THEN RAISE_APPLICATION_ERROR(-20001, '입력제한 일자가 설정되지 않았습니다.'); END IF;
        BEGIN V_DUMMY := TO_DATE(V_RESTRICT_START_YYYYMMDD, 'YYYYMMDD');
        EXCEPTION WHEN OTHERS THEN RAISE_APPLICATION_ERROR(-20001, '입력제한 일자가 설정되지 않았습니다.'); END;


        PR_DM_PLN_VERSION_CREATE(P_DIVISION_ID, '중장기용 백업', 'MF_M', P_CREATED_BY, V_MF_VERSION, V_OK_DESCRIPTION);
        PR_DM_PLN_VERSION_CREATE(P_DIVISION_ID, '중장기용 백업', 'SP_M', P_CREATED_BY, V_SP_VERSION, V_OK_DESCRIPTION);


        PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW(P_DIVISION_ID, 'SYSTEM');

        /* 5. MKT_FCST → _C */
        INSERT INTO DM_PLN_MKT_FCST_C
               ( DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD, PROJECT_CODE
               , SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY, CREATED_BY
               , CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7
               , ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
        SELECT DIVISION_ID, V_MF_VERSION, 'MF_M', TO_CHAR(SYSDATE,'YYYYMMDD'), PROJECT_CODE
             , SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY, P_CREATED_BY
             , SYSDATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7
             , ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10
          FROM DM_PLN_MKT_FCST
         WHERE YYYYMMDD >= V_MONDAY AND DIVISION_ID = P_DIVISION_ID;


        INSERT INTO DM_PLN_CFM_MKT_DEMAND_PLAN_C
               ( DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD, PROJECT_CODE, END_CUSTOMER
               , SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID, YYYYMMDD, QTY, CREATED_BY, CREATION_DATE
               , LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7
               , ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
        SELECT DIVISION_ID, V_MF_VERSION, 'MF_M', TO_CHAR(SYSDATE,'YYYYMMDD'), PROJECT_CODE, END_CUSTOMER
             , SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID, YYYYMMDD, QTY, P_CREATED_BY
             , SYSDATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7
             , ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10
          FROM DM_PLN_CFM_MKT_DEMAND_PLAN
         WHERE YYYYMMDD >= V_MONDAY AND DIVISION_ID = P_DIVISION_ID;

        /* 7. SALES_PLAN → _C */
        INSERT INTO DM_PLN_SALES_PLAN_C
               ( DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD, PROJECT_CODE
               , SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, CURRENCY, QTY, CREATED_BY
               , CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6
               , ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10, CELL_PROD_SITE_ID )
        SELECT DIVISION_ID, V_SP_VERSION, 'SP_M', TO_CHAR(SYSDATE,'YYYYMMDD'), PROJECT_CODE
             , SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, CURRENCY, QTY, P_CREATED_BY
             , SYSDATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6
             , ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10, CELL_PROD_SITE_ID
          FROM DM_PLN_SALES_PLAN
         WHERE YYYYMMDD >= V_MONDAY AND DIVISION_ID = P_DIVISION_ID;

        COMMIT;


        SELECT COUNT(*) INTO V_CNT FROM (
            SELECT DIVISION_ID,PROJECT_CODE,SCM_SITE_ID,ITEM_ID,DOM_EXP,FCST_TYPE,INCOTERMS,MEASURE,PLANT_SITE_ID,YYYYMMDD,QTY
              FROM DM_PLN_MKT_FCST_C WHERE VERSION_NO=V_MF_VERSION AND DIVISION_ID=P_DIVISION_ID AND YYYYMMDD>=V_RESTRICT_START_YYYYMMDD AND QTY<>0
             GROUP BY DIVISION_ID,PROJECT_CODE,SCM_SITE_ID,ITEM_ID,DOM_EXP,FCST_TYPE,INCOTERMS,MEASURE,PLANT_SITE_ID,YYYYMMDD,QTY ) A
        FULL OUTER JOIN (
            SELECT DIVISION_ID,PROJECT_CODE,SCM_SITE_ID,ITEM_ID,DOM_EXP,FCST_TYPE,INCOTERMS,MEASURE,YYYYMMDD,PLANT_SITE_ID,QTY
              FROM DM_PLN_MKT_FCST WHERE DIVISION_ID=P_DIVISION_ID AND YYYYMMDD>=V_RESTRICT_START_YYYYMMDD AND QTY<>0
             GROUP BY DIVISION_ID,PROJECT_CODE,SCM_SITE_ID,ITEM_ID,DOM_EXP,FCST_TYPE,INCOTERMS,MEASURE,YYYYMMDD,PLANT_SITE_ID,QTY ) B
          ON A.DIVISION_ID=B.DIVISION_ID AND A.PROJECT_CODE=B.PROJECT_CODE AND A.SCM_SITE_ID=B.SCM_SITE_ID AND A.ITEM_ID=B.ITEM_ID
         AND A.DOM_EXP=B.DOM_EXP AND A.FCST_TYPE=B.FCST_TYPE AND A.INCOTERMS=B.INCOTERMS AND A.MEASURE=B.MEASURE AND A.YYYYMMDD=B.YYYYMMDD AND A.PLANT_SITE_ID=B.PLANT_SITE_ID
         WHERE ((A.QTY<>B.QTY) OR (A.DIVISION_ID IS NULL) OR (B.DIVISION_ID IS NULL));
        DBMS_OUTPUT.PUT_LINE('DM_PLN_MKT_FCST_C vs DM_PLN_MKT_FCST DIFF 건 : ' || V_CNT);

        SELECT COUNT(*) INTO V_CNT FROM (
            SELECT DIVISION_ID,PROJECT_CODE,SCM_SITE_ID,ITEM_ID,DOM_EXP,FCST_TYPE,INCOTERMS,MEASURE,PLANT_SITE_ID,YYYYMMDD,CELL_PROD_SITE_ID,QTY
              FROM DM_PLN_SALES_PLAN_C WHERE VERSION_NO=V_SP_VERSION AND DIVISION_ID=P_DIVISION_ID AND YYYYMMDD>=V_RESTRICT_START_YYYYMMDD AND QTY<>0
             GROUP BY DIVISION_ID,PROJECT_CODE,SCM_SITE_ID,ITEM_ID,DOM_EXP,FCST_TYPE,INCOTERMS,MEASURE,PLANT_SITE_ID,YYYYMMDD,CELL_PROD_SITE_ID,QTY ) A
        FULL OUTER JOIN (
            SELECT DIVISION_ID,PROJECT_CODE,SCM_SITE_ID,ITEM_ID,DOM_EXP,FCST_TYPE,INCOTERMS,MEASURE,PLANT_SITE_ID,YYYYMMDD,CELL_PROD_SITE_ID,QTY
              FROM DM_PLN_SALES_PLAN WHERE DIVISION_ID=P_DIVISION_ID AND YYYYMMDD>=V_RESTRICT_START_YYYYMMDD AND QTY<>0
             GROUP BY DIVISION_ID,PROJECT_CODE,SCM_SITE_ID,ITEM_ID,DOM_EXP,FCST_TYPE,INCOTERMS,MEASURE,PLANT_SITE_ID,YYYYMMDD,CELL_PROD_SITE_ID,QTY ) B
          ON A.DIVISION_ID=B.DIVISION_ID AND A.PROJECT_CODE=B.PROJECT_CODE AND A.SCM_SITE_ID=B.SCM_SITE_ID AND A.ITEM_ID=B.ITEM_ID
         AND A.DOM_EXP=B.DOM_EXP AND A.FCST_TYPE=B.FCST_TYPE AND A.INCOTERMS=B.INCOTERMS AND A.MEASURE=B.MEASURE AND A.PLANT_SITE_ID=B.PLANT_SITE_ID AND A.YYYYMMDD=B.YYYYMMDD AND A.CELL_PROD_SITE_ID=B.CELL_PROD_SITE_ID
         WHERE ((A.QTY<>B.QTY) OR (A.DIVISION_ID IS NULL) OR (B.DIVISION_ID IS NULL));
        DBMS_OUTPUT.PUT_LINE('DM_PLN_SALES_PLAN_C vs DM_PLN_SALES_PLAN DIFF 건 : ' || V_CNT);

    EXCEPTION
        WHEN OTHERS THEN
            V_ERRMSG      := SUBSTR(SQLERRM, 1, 1000);
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := V_ERRMSG;
            V_DESCRIPTION := 'ERROR_LINE : ' || SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 400);
            D_EVENT_DATE  := SYSDATE;
            DBMS_OUTPUT.PUT_LINE('[' || TO_CHAR(SQLCODE) || ']' || V_ERRMSG);
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    END;

    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := 'p_division_id :' || P_DIVISION_ID || '/ V_MF_VERSION :' || V_MF_VERSION || '/ V_SP_VERSION :' || V_SP_VERSION || '/ 소형 중장기';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
END PR_DM_LONGPLAN_40_BACKUP;

PROCEDURE PR_DM_MDF_SIMULATION_CUTOFF_CREATE
(
      P_DIVISION_ID       IN  VARCHAR2
    , P_VER_DESCRIPTION    IN  VARCHAR2
    , P_VER_TYPE           IN  VARCHAR2
    , P_OLD_VERSION_NO     IN  VARCHAR2
    , P_CREATED_BY         IN  VARCHAR2
)
/* ============================================================
 * Program ID   : PR_DM_MDF_SIMULATION_CUTOFF_CREATE
 * Description  : MDF SIMULATOR CUTOFF CREATE
 * Program History
 *------------------------------------------------------------
 * Date          In Charge      Description
 *------------------------------------------------------------
 * 20180806      JSYOUN         INIT C20190314_48991 [CSR ID:3948991] GSCM MDF 시뮬레이터 개발 요청의 건
 * 2026-07-23    ZIONEX         [PJ202650304]  NextSCM Migration
 * ============================================================ */
IS

    /*
        -----------------------------------------------------------------------------------------
        000
            : VARIABLE DECLARATION
        -----------------------------------------------------------------------------------------
    */

    RECV_ACTIVE_FLAG    VARCHAR2(4000 CHAR);
    V_DIVISION_ID       VARCHAR2(4000 CHAR);
    V_VER_DESCRIPTION   VARCHAR2(4000 CHAR);
    V_VER_TYPE          VARCHAR2(4000 CHAR);
    V_OLD_VERSION_NO    VARCHAR2(4000 CHAR);
    V_CREATED_BY        VARCHAR2(4000 CHAR);

    V_VER_RETURN_NO     VARCHAR2(100 CHAR);   /* cut off Generated Number */
    N_HISTORY_SEQ       PLS_INTEGER;
    V_PLAN_WEEK         VARCHAR2(4000 CHAR);
    V_OK_DESCRIPTION    VARCHAR2(1200 CHAR);  /* cut off Generated Number */

    V_DELIMITER         VARCHAR2(1 CHAR);
    MAX_LOOP_CNT        PLS_INTEGER := 0;
    MST_LOOP_CNT        PLS_INTEGER := 0;

    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME      VARCHAR2(150 CHAR) := 'PR_DM_PLN_MKT_FCST_WEEKLY_ROLLING';
    V_LOG_TYPE          VARCHAR2(30 CHAR);    /* START/END/ERROR/... */
    N_LOG_COUNT         PLS_INTEGER := 0;
    V_LOG_MESSAGE       VARCHAR2(1000 CHAR);
    V_DESCRIPTION       VARCHAR2(500 CHAR);
    D_EVENT_DATE        DATE;

BEGIN


    V_DIVISION_ID     := NULL;
    V_VER_DESCRIPTION := NULL;
    V_VER_TYPE        := NULL;
    V_OLD_VERSION_NO  := NULL;
    V_CREATED_BY      := NULL;

    V_DELIMITER := '^';

    /*
        -----------------------------------------------------------------------------------------
        100
            : START LOG
        -----------------------------------------------------------------------------------------
    */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;

    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    V_LOG_MESSAGE := NULL;   /* 변수 재사용을 위하여 초기화해야함 */


    /*
        -----------------------------------------------------------------------------------------
        200
            : MAIN LOGIC
        -----------------------------------------------------------------------------------------
    */
    BEGIN

        V_DIVISION_ID := P_DIVISION_ID;
        DBMS_OUTPUT.PUT_LINE(V_DIVISION_ID);

        SELECT (SELECT A.ISO_YYYYWW
                  FROM SCM_SYS_CALENDAR_M A
                 WHERE A.BASIS_YYYYMMDD = TO_CHAR(SYSDATE, 'YYYYMMDD'))
          INTO V_PLAN_WEEK
          FROM DUAL
        ;
        DBMS_OUTPUT.PUT_LINE(V_PLAN_WEEK);

        V_VER_DESCRIPTION := P_VER_DESCRIPTION;
        DBMS_OUTPUT.PUT_LINE(V_VER_DESCRIPTION);

        V_VER_TYPE := P_VER_TYPE;
        DBMS_OUTPUT.PUT_LINE(V_VER_TYPE);

        V_OLD_VERSION_NO := P_OLD_VERSION_NO;
        DBMS_OUTPUT.PUT_LINE(V_OLD_VERSION_NO);

        V_CREATED_BY := P_CREATED_BY;
        DBMS_OUTPUT.PUT_LINE(V_CREATED_BY);

        PR_DM_PLN_VERSION_CREATE(
              V_DIVISION_ID
            , V_VER_DESCRIPTION
            , V_VER_TYPE
            , V_CREATED_BY
            , V_VER_RETURN_NO
            , V_OK_DESCRIPTION
        );

        DBMS_OUTPUT.PUT_LINE(V_VER_RETURN_NO);
        DBMS_OUTPUT.PUT_LINE(V_OK_DESCRIPTION);

        DBMS_OUTPUT.PUT_LINE('1');

