            /* ---input 데이터의 시작과 끝 산출 ------------------------------------------------------------- (start) EEEE */
            /* MSSQL: #TEMP_MIN_MAX_PSI$ DROP + SELECT INTO → GTT DELETE 후 적재(그룹루프 매회 신규) */
            DELETE FROM GT_DPCFSM_MIN_MAX;
            BEGIN
                INSERT
                INTO GT_DPCFSM_MIN_MAX
                    (YYYYMMDD, RN)
                    SELECT YYYYMMDD
                         , ROW_NUMBER() OVER (ORDER BY YYYYMMDD) RN
                      FROM GT_DPCFSM_T3
                      GROUP BY YYYYMMDD
                      ORDER BY YYYYMMDD;
            END;
            BEGIN
                BEGIN
                    SELECT YYYYMMDD
                      INTO N_MIN_YYYYMMDD
                      FROM GT_DPCFSM_MIN_MAX
                     WHERE RN = 1;
                EXCEPTION
                    WHEN NO_DATA_FOUND THEN
                        N_MIN_YYYYMMDD := NULL;
                END;

                BEGIN
                    SELECT YYYYMMDD
                      INTO N_MAX_YYYYMMDD
                      FROM GT_DPCFSM_MIN_MAX
                     WHERE RN = (SELECT MAX(RN)
                                   FROM GT_DPCFSM_MIN_MAX
                                );
                EXCEPTION
                    WHEN NO_DATA_FOUND THEN
                        N_MAX_YYYYMMDD := NULL;
                END;
            END;
            /* -input 데이터의 시작과 끝 산출 ------------------------------------------------------------- (end) */

            /* ---insert 할 실제 데이터의 시작과 끝 구간 산출 ----------------------------------------------- (start) 20180409 */
            DELETE FROM GT_DPCFSM_SITE_CUST_MAP; /* MEASURE별 cursor 작업이므로 초기화 */

            INSERT
            INTO GT_DPCFSM_SITE_CUST_MAP
                (DIVISION_ID, SCM_SITE_ID, MEASURE, START_DAY, END_DAY)
                SELECT A.DIVISION_ID
                     , A.SCM_SITE_ID
                     , A.MEASURE
                     , A.SUMMARY_BUCKET_VALUE START_DAY
                     , CASE
                            WHEN SUMMARY_BUCKET_TYPE = 'WEEKLY' THEN TO_CHAR(FN_NEXT_DAY(TO_DATE(SUMMARY_BUCKET_VALUE, 'YYYYMMDD'), 'SUN') + (0), 'YYYYMMDD')
                            ELSE A.SUMMARY_BUCKET_VALUE
                        END END_DAY
                  FROM DM_MST_CUSTOMER_FCST A
                     , (SELECT DISTINCT DIVISION_ID
                              , SCM_SITE_ID
                              , MEASURE_GROUP
                           FROM GT_DPCFSM_T3
                        ) RSLT
                 WHERE A.DIVISION_ID = RSLT.DIVISION_ID
                   AND A.SCM_SITE_ID = RSLT.SCM_SITE_ID
                   AND A.MEASURE_GROUP = RSLT.MEASURE_GROUP
                   AND 1 = 1
                   AND VALID_YN = 'Y' /* 20240507 KCW3408 수정 */
                   AND A.PLAN_WEEK = (SELECT MAX(PLAN_WEEK)
                                        FROM DM_MST_CUSTOMER_FCST X
                                       WHERE X.DIVISION_ID = A.DIVISION_ID
                                         AND X.SCM_SITE_ID = A.SCM_SITE_ID
                                         AND X.MEASURE_GROUP = A.MEASURE_GROUP
                                     )
                   AND A.SUMMARY_BUCKET_VALUE >= TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') + (-7 * 1), 'YYYYMMDD') /* 당주 월요일 이후데이터만 */
                   AND SUMMARY_BUCKET_TYPE IN ('DAILY', 'WEEKLY')
                  UNION
                SELECT A.DIVISION_ID
                     , A.SCM_SITE_ID
                     , A.MEASURE
                     , CASE
                            WHEN SUMMARY_BUCKET_VALUE = TO_CHAR(TRUNC(SYSDATE, 'MM'), 'YYYYMMDD') THEN TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') + (-7 * 1), 'YYYYMMDD')
                            ELSE SUMMARY_BUCKET_VALUE
                        END AS START_DAY
                     , TO_CHAR(LAST_DAY(TO_DATE(SUMMARY_BUCKET_VALUE, 'YYYYMMDD')), 'YYYYMMDD') END_DAY /* MSSQL: SUMMARY_BUCKET_VALUE 월의 말일 */
                  FROM DM_MST_CUSTOMER_FCST A
                     , (SELECT DISTINCT DIVISION_ID
                              , SCM_SITE_ID
                              , MEASURE_GROUP
                           FROM GT_DPCFSM_T3
                        ) RSLT
                 WHERE A.DIVISION_ID = RSLT.DIVISION_ID
                   AND A.SCM_SITE_ID = RSLT.SCM_SITE_ID
                   AND A.MEASURE_GROUP = RSLT.MEASURE_GROUP
                   AND 1 = 1
                   AND VALID_YN = 'Y'
                   AND A.PLAN_WEEK = (SELECT MAX(PLAN_WEEK)
                                        FROM DM_MST_CUSTOMER_FCST X
                                       WHERE X.DIVISION_ID = A.DIVISION_ID
                                         AND X.SCM_SITE_ID = A.SCM_SITE_ID
                                         AND X.MEASURE_GROUP = A.MEASURE_GROUP
                                     )
                   AND A.SUMMARY_BUCKET_VALUE >= TO_CHAR(TRUNC(SYSDATE, 'MM'), 'YYYYMMDD')
                   AND SUMMARY_BUCKET_TYPE IN ('MONTHLY');


            /* select '#TEMP3_DM_PLN_CUSTOMER_PSI$ '; select * from #TEMP3 ...; select '@tmp_site_customer_map'; select * from @tmp_site_customer_map; */
            RETURN;

            DBMS_OUTPUT.PUT_LINE('20240605-zzzzzzzzzzzzzzzzzzzzzzzzzz');
            /* -insert 할 실제 데이터의 시작과 끝 구간 산출 ----------------------------------------------- (end) 20180409 */

            /* (88) 데이터의 시작~끝 날짜 구하기 ---------------------------------------------- (start) */
            BEGIN
                IF N_UPLOAD_BUCKET_TYPE = 'DAILY' THEN
                    BEGIN
                        SELECT BASIS_YYYYMMDD
                          INTO N_MAX_YYYYMMDD
                          FROM SCM_SYS_CALENDAR_M T
                         WHERE T.BASIS_YYYYMMDD = TO_CHAR(TO_DATE(N_MAX_YYYYMMDD, 'YYYYMMDD') + 0, 'YYYYMMDD'); /* MAX_YYYYMMDD 셋팅 */
                    EXCEPTION
                        WHEN NO_DATA_FOUND THEN
                            NULL;
                    END;
                ELSIF N_UPLOAD_BUCKET_TYPE = 'WEEKLY' THEN
                    N_MIN_YYYYMMDD := TO_CHAR(FN_NEXT_DAY(TO_DATE(N_MIN_YYYYMMDD, 'YYYYMMDD'), 'MON') + (-7), 'YYYYMMDD'); /* MIN_YYYYMMDD 셋팅 */
                    BEGIN
                        SELECT BASIS_YYYYMMDD
                          INTO N_MAX_YYYYMMDD
                          FROM SCM_SYS_CALENDAR_M T
                         WHERE T.BASIS_YYYYMMDD = TO_CHAR(TO_DATE(N_MAX_YYYYMMDD, 'YYYYMMDD') + 6, 'YYYYMMDD'); /* MAX_YYYYMMDD 셋팅 */
                    EXCEPTION
                        WHEN NO_DATA_FOUND THEN
                            NULL;
                    END;
                ELSIF N_UPLOAD_BUCKET_TYPE = 'MONTHLY' THEN
                    BEGIN
                        SELECT BASIS_YYYYMMDD
                          INTO N_MAX_YYYYMMDD
                          FROM SCM_SYS_CALENDAR_M T
                         WHERE T.BASIS_YYYYMMDD = TO_CHAR(ADD_MONTHS(TO_DATE(N_MAX_YYYYMMDD, 'YYYYMMDD'), 1) - 1, 'YYYYMMDD'); /* MAX_YYYYMMDD 셋팅 : MSSQL DATEADD(DD,-1, MM+1월초) */
                    EXCEPTION
                        WHEN NO_DATA_FOUND THEN
                            NULL;
                    END;
                END IF;
            END;
            /* (88) 데이터의 시작~끝 날짜 구하기 ---------------------------------------------- (end) */
            DBMS_OUTPUT.PUT_LINE('20240605-zzzzzzzzzzzzzzzzzzzzzzzzzz' ||N_UPLOAD_BUCKET_TYPE);
            DBMS_OUTPUT.PUT_LINE('@n_MIN_YYYYMMDD : ' ||N_MIN_YYYYMMDD);
            DBMS_OUTPUT.PUT_LINE('20240605-eeee');

            /* DM_PLN_CUSTOMER_PSI 최종 데이터 INSERT --------------------------------------------------------------------------------------- */

            /* 2024.05.02    kcw3408       고객수요 N:N Mapping  */
            /* 매핑테이블 데이블  INSERT */
            BEGIN
                PR_DM_CUST_ITEM_MAPPING('RPA');
            END;

            /* 대상 추출 : MSSQL #TEMP_DM_CUST_ITEM_MAPPING_DTL_N DROP + SELECT INTO → GTT DELETE 후 적재 */
            BEGIN
                DELETE FROM GT_DPCFSM_CUST_ITEM_MAP_DTL;

                INSERT
                INTO GT_DPCFSM_CUST_ITEM_MAP_DTL
                    (DIVISION_ID
                    , DATA_TYPE_CODE
                    , END_CUSTOMER
                    , SCM_SITE_ID
                    , PROJECT_CODE
                    , FCST_TYPE
                    , INCOTERMS
                    , DOM_EXP
                    , ITEM_ID
                    , UNLOADING_POINT
                    , CUSTOMER_PLANT
                    , CUSTOMER_ITEM_ID
                    , VALID_START_DATE
                    , VALID_END_DATE
                    , MAPPING_ITEM_ID)
                    SELECT B.DIVISION_ID
                         , B.DATA_TYPE_CODE
                         , B.END_CUSTOMER
                         , B.SCM_SITE_ID
                         , B.PROJECT_CODE
                         , B.FCST_TYPE
                         , B.INCOTERMS
                         , B.DOM_EXP
                         , B.ITEM_ID
                         , B.UNLOADING_POINT
                         , B.CUSTOMER_PLANT
                         , B.CUSTOMER_ITEM_ID
                         , B.VALID_START_DATE
                         , B.VALID_END_DATE
                         , B.MAPPING_ITEM_ID
                      FROM DM_CUST_ITEM_MAPPING_M A
                         , DM_CUST_ITEM_MAPPING_DTL_N B
                     WHERE A.DIVISION_ID = B.DIVISION_ID
                       AND A.DATA_TYPE_CODE = B.DATA_TYPE_CODE
                       AND A.END_CUSTOMER = B.END_CUSTOMER
                       AND A.SCM_SITE_ID = B.SCM_SITE_ID
                       AND A.PROJECT_CODE = B.PROJECT_CODE
                       AND A.FCST_TYPE = B.FCST_TYPE
                       AND A.INCOTERMS = B.INCOTERMS
                       AND A.DOM_EXP = B.DOM_EXP
                       AND A.ITEM_ID = B.ITEM_ID
                       AND A.UNLOADING_POINT = B.UNLOADING_POINT
                       AND RTRIM(LTRIM(A.CUSTOMER_PLANT)) = RTRIM(LTRIM(B.CUSTOMER_PLANT))
                       AND RTRIM(LTRIM(A.CUSTOMER_ITEM_ID)) = RTRIM(LTRIM(B.CUSTOMER_ITEM_ID))
                       AND A.ACTIVE_YN = 'Y'
                       AND A.DATA_TYPE_CODE IN ('RPA', 'EXCEL');
            END;

            /* DM_PLN_CUSTOMER_PSI 최종 데이터 INSERT 전 임시테이블에 모두 저장 : N:N Model Mapping 적용 (2024.05.02 kcw3408) */
            BEGIN
                INSERT
                INTO GT_DPCFSM_T2
                    SELECT DISTINCT A.DIVISION_ID
                         , A.CUSTOMER_PROJECT_CODE
                         , A.CUSTOMER_MODEL
                         , A.SCM_SITE_ID
                         , A.DOM_EXP
                         , A.FCST_TYPE
                         , A.MEASURE_GROUP
                         , V_MEASURE /* 20180227변경사항 measure를 기존값으로 그대로 사용함 */
                         , A.YYYYMMDD
                         , A.INCOTERMS
                         , A.PLANT_SITE_ID
                         , A.PROJECT_CODE
                         , B.MAPPING_ITEM_ID /* AS ITEM_ID */
                         , A.QTY
                         , A.UPLOAD_UOM
                         , A.CREATED_BY
                         , A.CREATION_DATE
                         , A.LAST_UPDATED_BY
                         , A.LAST_UPDATE_DATE
                         , A.BATCH_RESULT
                         , A.MST_UPLOAD_UOM
                         , A.MST_UPLOAD_BUCKET_TYPE
                         , A.MST_SUMMARY_BUCKET_TYPE
                         , A.MST_CONVERT_QTY
                         , A.PLAN_WEEK
                         , A.SPLIT_RESULT
                         , A.ATTRIBUTE1
                         , A.ATTRIBUTE2
                         , A.ATTRIBUTE3
                         , A.ATTRIBUTE4
                         , A.ATTRIBUTE5
                         , A.ATTRIBUTE6
                         , A.ATTRIBUTE7
                         , A.ATTRIBUTE8
                         , A.ATTRIBUTE9
                         , A.ATTRIBUTE10
                      FROM GT_DPCFSM_T3 A
                    /* 2024.05.02 kcw3408 고객수요 N:N Mapping : 집계 시점에 Cust Item/Unloading Point/Plant 반영, Valid Range 1~5 밖은 Calloff 미집계 */
                         , GT_DPCFSM_CUST_ITEM_MAP_DTL B
                     WHERE A.DIVISION_ID = B.DIVISION_ID
                       AND A.SCM_SITE_ID = B.SCM_SITE_ID
                       AND A.PROJECT_CODE = B.PROJECT_CODE
                       AND A.FCST_TYPE = B.FCST_TYPE
                       AND A.INCOTERMS = B.INCOTERMS
                       AND A.DOM_EXP = B.DOM_EXP
                       AND A.ITEM_ID = B.ITEM_ID
                       AND A.YYYYMMDD >= B.VALID_START_DATE
                       AND A.YYYYMMDD <= B.VALID_END_DATE
                       AND B.MAPPING_ITEM_ID > ' '
                       AND CASE
                               WHEN A.CREATED_BY LIKE '%robot' THEN
                                'RPA'
                               ELSE
                                'EXCEL'
                           END = B.DATA_TYPE_CODE
                       AND N_MIN_YYYYMMDD <= YYYYMMDD
                       AND N_MAX_YYYYMMDD >= YYYYMMDD;
            END;

            /* DM_PLN_CUSTOMER_PSI insert count 확인 ---------------------------------------------------------------------------------------- */
            BEGIN
                SELECT N_PSI_INSERT_COUNT + COUNT(*)
                  INTO N_PSI_INSERT_COUNT
                  FROM GT_DPCFSM_T2;
            END;

            /* DM_PLN_CUSTOMER_PSI test222222 ---------------------------------------------------------------------------------------- */
