PROCEDURE PR_DM_PLN_ESS_CHANNEL_PSI_CUTOFF
(
      P_DIVISION_ID          IN  VARCHAR2    /* division_id 전달받음 */
    , P_VERSION_DESCRIPTION  IN  CLOB        /* description 전달받음 */
    , P_VER_TYPE             IN  VARCHAR2
    , P_CREATED_BY           IN  VARCHAR2
)
/*
 * Program ID   : PR_DM_PLN_ESS_CHANNEL_PSI_CUTOFF
 * Description  :
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2018. 03. 05    KHSONG      Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 * 2020/09/09     P.C.I        [C20200909-000203] LOG 표준화 적용
 * 2026.07.06   ZIONEX   [PJ202650304] NextSCM Migration
 *
 */
AS


    N_HISTORY_SEQ      INTEGER;
    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME     VARCHAR2(150 CHAR) := 'PR_DM_PLN_ESS_CHANNEL_PSI_CUTOFF';
    V_LOG_TYPE         VARCHAR2(30 CHAR);      /* START/END/ERROR/... */
    N_LOG_COUNT        INTEGER := 0;
    V_LOG_MESSAGE      VARCHAR2(1000 CHAR);
    V_DESCRIPTION      VARCHAR2(500 CHAR);
    D_EVENT_DATE       DATE;

    /* */
    V_DIVISION_ID      VARCHAR2(4000 CHAR);
    V_VER_DESCRIPTION  VARCHAR2(4000 CHAR);
    V_VER_TYPE         VARCHAR2(4000 CHAR);
    V_ROLLING_TYPE     VARCHAR2(4000 CHAR);
    V_CREATED_BY       VARCHAR2(4000 CHAR);

    V_VER_RETURN_NO    VARCHAR2(100 CHAR);     /* cut off Generated Number */
    V_PLAN_WEEK        VARCHAR2(4000 CHAR);
    V_OK_DESCRIPTION   VARCHAR2(1200 CHAR);    /* cut off Generated Number */


    V_PROC_INPUT       VARCHAR2(4000 CHAR);
    V_SQL_CODE         VARCHAR2(100 CHAR);
    V_SQL_ERRMSG       VARCHAR2(1000 CHAR);
    V_BACKTRACE        VARCHAR2(4000 CHAR);
BEGIN
    V_DIVISION_ID     := NULL;
    V_VER_DESCRIPTION := NULL;
    V_VER_TYPE        := NULL;
    V_ROLLING_TYPE    := NULL;
    V_CREATED_BY      := NULL;

    /* 시작 LOG  (START) */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    V_LOG_MESSAGE := NULL;      /*-- <- 변수 재사용을 위하여 초기화해야함 --*/
    /* 시작 LOG  (END) */

    /*------------------------------------------------------------------------------------------*/
    BEGIN  /* 트랜잭션 (START) / BEGIN TRY */
    /*------------------------------------------------------------------------------------------*/
        V_DIVISION_ID := P_DIVISION_ID;

        PR_DM_PLN_VERSION_CREATE(   /* @return_value = PR_DM_PLN_VERSION_CREATE */
              V_DIVISION_ID
            , P_VERSION_DESCRIPTION
            , P_VER_TYPE
            , P_CREATED_BY
            , V_VER_RETURN_NO
            , V_OK_DESCRIPTION
        );

        /* 확인 SELECT @v_division_id AS '@v_division_id' ; */
        /* 확인 SELECT @v_ver_return_no AS '@v_ver_return_no' , @v_OK_description AS '@v_OK_description'; */

        /* (1) */

        /* CUTOFF DATA INSERT */
        INSERT
          INTO DM_PLN_ESS_CHANNEL_PSI_C
        SELECT DIVISION_ID
             , V_VER_RETURN_NO AS VERSION_NO                    /* VERSION_NO */
             , P_VER_TYPE AS CUTOFF_TYPE                        /* CUTOFF_TYPE */
             , TO_CHAR(SYSDATE, 'YYYYMMDD') AS CUTOFF_YYYYMMDD  /* CUTOFF_YYYYMMDD */
             , SCM_SITE_ID
             , ITEM_ID
             , MEASURE
             , YYYYMMDD
             , VALUE
             , P_CREATED_BY AS CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , ATTRIBUTE6
             , ATTRIBUTE7
             , ATTRIBUTE8
             , ATTRIBUTE9
             , ATTRIBUTE10
          FROM DM_PLN_ESS_CHANNEL_PSI
         WHERE DIVISION_ID = V_DIVISION_ID
           AND YYYYMMDD >= TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7, 'YYYYMMDD');

        /* 트랜잭션 (COMMIT) */
        COMMIT;

    /*------------------------------------------------------------------------------------------*/
    EXCEPTION
    /*------------------------------------------------------------------------------------------*/
        WHEN OTHERS THEN
            /* [C20200909-000203] LOG 표준화 적용 */
            /* 트랜잭션 (END) */
            ROLLBACK;
            /* ROLLBACK */
            /* ERROR LOG VALUE SAVE */
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SQLERRM;
            V_DESCRIPTION := 'ERROR_BACKTRACE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
            D_EVENT_DATE  := SYSDATE;
            V_SQL_CODE    := TO_CHAR(SQLCODE);
            V_SQL_ERRMSG  := SQLERRM;
            V_PROC_INPUT  := JSON_OBJECT(
                  'DIVISION_ID' VALUE P_DIVISION_ID
                , 'VER_TYPE'    VALUE P_VER_TYPE
                , 'CREATED_BY'  VALUE P_CREATED_BY
                  RETURNING VARCHAR2(4000 CHAR)
            );
            V_BACKTRACE   := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;

            /* 에러메시지 DISPLAY
            SELECT '[' + Convert(NVARCHAR(10), ERROR_NUMBER()) + ']' + ERROR_MESSAGE();
            */

            PR_SCM_SYS_LOG_BATCH(
                  V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE
                , V_DESCRIPTION, D_EVENT_DATE, V_PROC_INPUT
                , V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE
            );
    /*------------------------------------------------------------------------------------------*/
    END;
    /*------------------------------------------------------------------------------------------*/

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;

    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
END;

