PROCEDURE           "PR_DM_SMS_LOG_BATCH" 
(
    P_CATEGORY_NAME   IN VARCHAR2
  , P_LOG_TYPE        IN VARCHAR2
  , P_DESCRIPTION     IN VARCHAR2
  , P_EVENT_DATE      IN DATE
)
/*=====================================================================================================================================================================
 * Program ID   : PR_DM_SMS_LOG_BATCH
 * Program ID   : PR_DM_SMS_LOG_BATCH
 * Description  : 로그에 생성되는 내용으로 SMS 발송
 * Program History
 *=====================================================================================================================================================================
 *   Date       In Charge		Description
 *=====================================================================================================================================================================
 * 2025.08.25	JSSBAE			[E20250805-000632]_MKT FCST Cutoff 프로시저 모니터링용 SMS 발송
 * 2026.07.06   ZIONEX   [PJ202650304] NextSCM Migration
 *====================================================================================================================================================================*/
AS

    V_CATEGORY_ID   VARCHAR2(10 CHAR);
    V_SMS_DESC      VARCHAR2(4000 CHAR);
BEGIN


    BEGIN

        DBMS_OUTPUT.PUT_LINE('PR_DM_SMS_LOG_BATCH' || ': A001: ' || ' @p_category_name: ' || P_CATEGORY_NAME || ' @p_log_type: ' || P_LOG_TYPE || ' @p_description: ' || P_DESCRIPTION || TO_CHAR(SYSDATE, 'YYYY-MM-DD HH24:MI:SS'));

        V_SMS_DESC := P_DESCRIPTION || '::' || P_LOG_TYPE || '::';

        SELECT MAX(A.CATEGORY_ID)
          INTO V_CATEGORY_ID
          FROM SCM_ADM_RECIPIENT_LIST A
         WHERE A.CATEGORY_DESC = P_CATEGORY_NAME;

        SCM_ADM_SMS_SEND_BATCH(V_CATEGORY_ID, V_SMS_DESC);

