PROCEDURE         PR_DM_UNLOGIN_MAIL_SEND

/*
    * Program ID   : PR_DM_UNLOGIN_MAIL_SEND
    * Description  : 3개월 미접속자 권한을 회수 메일 발송
    * PARAMETER    : N/A
    * Program History
    *===================================================================================================
    *   Date       In Charge      Description
    *===================================================================================================
    * 2023/10/19   KJJ            PJ20230691R  LGES SCM 역량 강화 위한 SCP 개선과제 이행 -  3개월 미접속자 권한을 회수 메일 발송
    * 2026/03/23   김준규          [PJ20264226] NextSCM Pilot 설계 및 개발
 * 2026.07.06	ZIONEX		[PJ202650304] NextSCM Migration
    */
 AS

    /* FP의 PR_SCM_DECOMMISSION_AUTHORITY 참고 */
    /*

    SELECT SYS_CONTEXT('USERENV', 'DB_NAME')           AS DB_NAME,        -- DB 이름

    scm쪽 관련 테이블

    SELECT  UserID
          ,LogInTime
          ,LogOutTime
          ,CnntCode
          ,SN
          ,PushKey
      WHERE USERID = 'kjj0070'

      SELECT *
      WHERE USERID = 'kjj0070';
    */
    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME       VARCHAR2(200 CHAR) := $$PLSQL_UNIT;
    V_STEP               VARCHAR2(4000 CHAR) := NULL;
    V_LOG_TYPE           VARCHAR2(30 CHAR); /* START/END/ERROR/... */
    N_LOG_COUNT          INTEGER := 0;
    V_LOG_MESSAGE        VARCHAR2(1000 CHAR);
    V_DESCRIPTION        VARCHAR2(500 CHAR);
    D_EVENT_DATE         DATE;
    V_DISPATCH_SERIAL_NO INTEGER;

    V_TABLE_BODY    VARCHAR2(4000 CHAR);
    V_BODY_CONTENTS VARCHAR2(4000 CHAR);
    V_HEAD_CONT     VARCHAR2(4000 CHAR);
    V_BODY_CONT     VARCHAR2(4000 CHAR);
    V_TO_MAIL       VARCHAR2(150 CHAR);
    V_MAIL_TITLE    VARCHAR2(100 CHAR);
    V_OWNER         VARCHAR2(100 CHAR);
    V_OWNER_TYPE    CHAR(3);
    V_LIKE_STRING   VARCHAR2(100 CHAR);
    V_CNT           INTEGER;
    C_END_CUSTOMER  VARCHAR2(100 CHAR);
    C_SCM_SITE_ID   VARCHAR2(200 CHAR);
    C_PROJECT_CODE  VARCHAR2(50 CHAR);
    C_PROJECT_NAME  VARCHAR2(200 CHAR);
    C_ITEM_ID       VARCHAR2(50 CHAR);
    C_OWNER         VARCHAR2(100 CHAR);
    V_DELTIME       VARCHAR2(100 CHAR);
    V_CUR_MAIL_ADDR VARCHAR2(100 CHAR);
    V_I             INTEGER;
    C_DEPT_NAME_KO  VARCHAR2(150 CHAR);
    V_IN_PARA_DATA  CLOB;

    CURSOR CUR IS
        SELECT USER_ID || '@lgensol.com' MAIL_ADDR
             /* [2026-10-07] 날짜서식 교정 (사용자 승인).
              * 원본 : CONVERT(VARCHAR(10), DATEADD(DAY, 91, LASTLOGINDATETIME), 120)
              * style 120 은 'YYYY-MM-DD HH:MI:SS' 지만 VARCHAR(10) 으로 잘라 **날짜 10자만** 쓴다.
              * 이 값은 메일 본문의 「권한 삭제 일자 : 」에 그대로 찍히므로 시·분·초가 붙으면 본문이 달라진다. */
             , TO_CHAR(LOGN_DTM + (91), 'YYYY-MM-DD') DELTIME
          FROM SCM_ADM_USER_M
         WHERE USE_YN = 'Y'
           AND LOGN_DTM IS NOT NULL
           AND (LOGN_DTM <= SYSDATE + (-83) AND LOGN_DTM >= SYSDATE + (-90));

BEGIN
    IF UTL_CALL_STACK.SUBPROGRAM(1).COUNT > 1 THEN
        V_PROGRAM_NAME := $$PLSQL_UNIT || '.' || UTL_CALL_STACK.SUBPROGRAM(1) (2);
    END IF;

    V_IN_PARA_DATA := NULL;

    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := NULL;
    D_EVENT_DATE  := SYSTIMESTAMP;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);


    /* --------------------------------------------------------------------------------------------------- */
    /* 대상 추출 */
    /* --------------------------------------------------------------------------------------------------- */
    /*SELECT USERID || 'v_lgensol.com' MAIL_ADDR FROM SCM_ADM_USER_M
    WHERE USEYN = 'Y'
    AND LASTLOGINDATETIME IS NOT NULL
    GROUP BY USERID
    HAVING MAX(LASTLOGINDATETIME) < SYSDATE + (-83);
    */
    /* --------------------------------------------------------------------------------------------------- */
    /* 메일발송 시작 */
    /* --------------------------------------------------------------------------------------------------- */

    IF SYS_CONTEXT('USERENV', 'DB_NAME') NOT LIKE 'OCGSCMP%' THEN
        V_MAIL_TITLE := 'DEV Oracle 개발서버 '||'SCM 시스템 장기 미접속 알림';
    ELSE
        V_MAIL_TITLE := 'SCM 시스템 장기 미접속 알림';
    END IF;


    OPEN CUR;
    FETCH CUR
        INTO V_CUR_MAIL_ADDR, V_DELTIME;

    WHILE CUR%FOUND LOOP

        V_BODY_CONTENTS := '안녕하세요. </br> ' || 'SCM 시스템 장기 미접속 안내메일입니다. </br> ' || '시스템 미접속 3개월 이후에는 권한이 삭제됩니다.</br>' || '참고 하시기 바랍니다. </br> ' || '권한 삭제 일자 : ' ||
                           V_DELTIME || ' </br> ';

        V_TABLE_BODY := ' <html>
														<head>
															<title>Untitled Document</title>
															<style>
																* {margin:0;padding:0;}
																body {font-family:Malgun Gothic, Arial, Helvetica, sans-serif;font-size:12px;line-height:1.8;color:#333333;}
																table {border-collapse:collapse;width:100%;}
																table th {background:#f5f5f5;border-bottom:1px solid #e1e1e1;}
																table td {background:#fff;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1;border-bottom:1px solid #e1e1e1;}
																table tbody th {border-left:1px solid #e1e1e1;text-align:right;padding:6px 8px;font-size:12px}
																table tbody td {padding:6px 8px;font-size:12px}
																table thead th {text-align:center;padding:3px;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1; border-bottom:1px solid #d1d1d1;font-size:12px}
																.hori-table table thead td {text-align:center;padding:3px;}
																.hori-table table tbody td {text-align:center;padding:3px;}
																.vertical-table, .hori-table {margin-bottom:20px;}
															</style>
														</head>
														<body></br><b>' || REPLACE(V_BODY_CONTENTS, CHR(10), '<br>') || '</b>' ||
                        '<div id="divBody" style="width: 100%; overflow-x: auto; overflow-y: auto; font-size: 9pt; line-break: auto;">' ||
                        /* [2026-10-07] HTML 속성 따옴표를 원본대로 복원 (사용자 결정 「원본을 따라간다」).
                             * 원본 MSSQL : N'<table style=''border-top:…;''>'  → T-SQL 이스케이프라 `'` 한 개가 나간다.
                             * 변환본이 이것을 `"` 로 바꿔 놓아 생성 HTML 이 style="…" 가 됐다.
                             * HTML 상 기능은 동일하지만, 같은 관용구를 쓰는 메일객체 14건 중 12건은 ''를 유지했고
                             * 교차수행(행10 · 77통)에서 유일한 본문 차이가 이 2자였다. 원본 충실·14건 일관으로 되돌린다.
                             * ★같은 줄의 <div id="divBody" …> 의 " 는 원본에도 " 라서 손대지 않는다. */
                        '<table style=''border-top:2px solid #c8294b; width:1450px;''>
															<thead>' || V_HEAD_CONT || '</thead>
															<tbody>' || V_BODY_CONT || '</tbody>
															</div>
														</body>
												   </html>';

        PKG_SEND_MAIL.P_SEND_MAIL(V_CUR_MAIL_ADDR
                         ,V_MAIL_TITLE /* v_mail_title */
                         ,V_TABLE_BODY
                         ,'Y' /* html 여부 */
                          );

        FETCH CUR
            INTO V_CUR_MAIL_ADDR, V_DELTIME;
    END LOOP;

    CLOSE CUR;

EXCEPTION
    WHEN OTHERS THEN
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME
                            ,'ERROR'
                            ,0
                            ,SQLERRM
                            ,NULL
                            ,SYSDATE
                            ,P_IN_PARA_DATA  => V_IN_PARA_DATA
                            ,P_SQL_ERR_CODE  => SQLCODE
                            ,P_SQL_ERR_MSG   => SQLERRM
                            ,P_SQL_BACKTRACE => DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
        RAISE_APPLICATION_ERROR(-20001
                               ,'[' || V_PROGRAM_NAME || '] SQLCODE=' || SQLCODE || ' / SQLERRM=' || SQLERRM || ' / BACKTRACE=' ||
                                DBMS_UTILITY.FORMAT_ERROR_BACKTRACE || ' / PARAMS=' || V_IN_PARA_DATA);
END;

PROCEDURE PR_DM_WEEKLY_ROLLING_CUTOFF_MAIL_SEND
(
      P_DIVISION_ID   IN  VARCHAR2   /* DIVISION_ID */
    , P_VERSION_NO    IN  VARCHAR2   /* VERSION_NO */
)
/****************************************************************************************************/
/*
 * Program ID   : PR_DM_WEEKLY_ROLLING_CUTOFF_MAIL_SEND
 * Description  : MF_W, SF_W CUTOFF시 완료 후 메일 발송
 * Parameter    : P_DIVISION_ID, P_VERSION_NO
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2025.05.29   JSSBAE         [E20250529-001289]_DM 장애 대응 개선을 위한 시스템 개선
 * 2026.06.01   JSSBAE         [E20260529-001499]_Sales Plan Cutoff 메일링 방식 개선
 * 2026.07.06   ZIONEX         [PJ202650304]  NextSCM Migration
 *
 * EXEC PR_DM_WEEKLY_ROLLING_CUTOFF_MAIL_SEND @p_division_id=N'82', @p_version_no = N'MF_W_20250529_V002'
 */
/****************************************************************************************************/
/* ------------------------------------------------------------------------------------------------
 * 변환(MSSQL->Oracle) 재변환 : Weekly Rolling Cutoff 완료 후 메일 발송 (메일표준 PKG_SEND_MAIL.P_SEND_MAIL 직접전환, 2026-07-19 정책 확정)
 *   - SELECT TOP 1 @v = col ... WHERE RN=1 -> SELECT col INTO ... WHERE RN=1 AND ROWNUM=1
 *   - 메일대상 : MSSQL 활성라인 = SELECT A.SEGMENT2 (수신자 1인/행, IDENTITY(0,1)) -> 수신자별 발송 유지.
 *     SEQ = ROW_NUMBER() OVER(ORDER BY SEGMENT2) - 1 (0-base, MSSQL IDENTITY(0,1) 충실).
 *     (원본에서 STRING_AGG 일괄발송 라인은 주석처리 상태 -> 비활성. 아래 주석에 원문 보존)
 *   - 로깅 : START/END = PR_SCM_SYS_LOG_BATCH 6인자 / ERROR = 10인자(P_IN_PARA_DATA=JSON, SQLCODE/SQLERRM/BACKTRACE)
 * ------------------------------------------------------------------------------------------------ */
AS
    V_PROGRAM_NAME        VARCHAR2(150 CHAR) := 'PR_DM_WEEKLY_ROLLING_CUTOFF_MAIL_SEND';
    V_LOG_TYPE            VARCHAR2(30 CHAR);
    N_LOG_COUNT           INTEGER := 0;
    V_LOG_MESSAGE         VARCHAR2(1000 CHAR);
    V_DESCRIPTION         VARCHAR2(500 CHAR);
    D_EVENT_DATE          DATE;
    V_IN_PARA_DATA        VARCHAR2(4000 CHAR);

    S_MKT_FCST_CNT        VARCHAR2(15 CHAR);      /* MKT FCST CUTOFF COUNT 보관용변수 */
    S_NETDEMAND_CNT       VARCHAR2(15 CHAR);      /* NET_DEMAND COUNT 보관용변수 */
    S_PEGGING_CNT         VARCHAR2(15 CHAR);      /* PEGGING COUNT 보관용변수 */
    S_NET_PEGGING_VERSION VARCHAR2(200 CHAR);     /* NET_DEMAND, PEGGING VERSION 보관용 변수 */

    V_TABLE_BODY          VARCHAR2(32767 CHAR);
    V_BODY_CONTENTS       VARCHAR2(4000 CHAR);
    V_HEAD_CONT           VARCHAR2(2000 CHAR);
    V_BODY_CONT           VARCHAR2(32767 CHAR);
    V_MAIL_TITLE          VARCHAR2(150 CHAR);
    /* [2026-10-07] 동일 내용 메일을 수신자 ; 묶음으로 발송(사용자 결정 B · 행 9 선례).
     * 수신자 문자열이 길어져 V_OWNER 를 150 -> 4000 으로 확장했다.
     * 상한 4000 = 하위 PKG_SEND_MAIL 수신자 파라미터 정합.
     * GTT GT_DWRC_MAIL_ADDR.ADDR 은 VARCHAR2(150 CHAR) 라 묶은 문자열을 담을 수 없어
     * GTT 를 건드리지 않고 PL/SQL 슬롯에 담는다(동반객체 DDL 변경이 없어 사내망 반출 품목이 늘지 않는다). */
    V_OWNER               VARCHAR2(4000 CHAR);
    C_TO_MAIL_MAX CONSTANT PLS_INTEGER := 4000;
    TYPE T_ADDR_TAB IS TABLE OF VARCHAR2(4000 CHAR) INDEX BY PLS_INTEGER;
    V_ADDR_SLOT           T_ADDR_TAB;
    V_SLOT_CNT            PLS_INTEGER := 0;
    V_SLOT_I              PLS_INTEGER := 0;
    V_OWNER_TYPE          CHAR(3 CHAR);
    V_LIKE_STRING         VARCHAR2(100 CHAR);
    V_INFO_CNT            INTEGER;
BEGIN

    V_IN_PARA_DATA := JSON_OBJECT('p_division_id' VALUE P_DIVISION_ID, 'p_version_no' VALUE P_VERSION_NO);

    /* STEP 01. LOG 저장 (시작 START) */
    DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME||' : A001--'||'Div: '||P_DIVISION_ID||' /VerNo: '||P_VERSION_NO
                         ||' / '||TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));

    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '##### Start of procedure #####';
    V_DESCRIPTION := 'Weekly Cutoff 완료 후 메일 발송 / Div: '||P_DIVISION_ID||' / Ver: '||P_VERSION_NO;
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    BEGIN

        /* STEP 02. 작업 GTT 초기화 (PRESERVE ROWS) */
        DELETE
          FROM GT_DWRC_CUTOFF_INFO;

        DELETE
          FROM GT_DWRC_MAIL_ADDR;

        /* NetDemand/Pegging 은 당주(월~일) MF_W/SF_W 중 최근 버전(동일 날짜면 SF_W 우선)으로 COUNT 하기 위해 버전을 먼저 구함 */
        BEGIN
            SELECT VERSION_NO
              INTO S_NET_PEGGING_VERSION
              FROM (SELECT VERSION_NO
                         , RANK() OVER (ORDER BY YYYYMMDD DESC, VER_CRE_SEQ DESC, VERSION_TYPE DESC) AS RN
                      FROM DM_MST_VERSION
                     WHERE DIVISION_ID  = P_DIVISION_ID
                       AND VERSION_TYPE IN ('MF_W', 'SF_W')
                       AND YYYYMMDD     >= TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7 * 1, 'YYYYMMDD')
                       AND YYYYMMDD     <= TO_CHAR(FN_NEXT_DAY(SYSDATE, 'SUN'), 'YYYYMMDD')) A
             WHERE RN     = 1
               AND ROWNUM = 1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                S_NET_PEGGING_VERSION := NULL;
        END;

        /* STEP 03_01. MKT FCST CUTOFF 생성건수확인 */
        SELECT COUNT(*)
          INTO S_MKT_FCST_CNT
          FROM (SELECT DIVISION_ID
                  FROM DM_PLN_MKT_FCST_C
                 WHERE DIVISION_ID = P_DIVISION_ID
                   AND VERSION_NO  = P_VERSION_NO
                UNION ALL
                SELECT DIVISION_ID
                  FROM DM_PLN_MKT_FCST_RESULT_C
                 WHERE DIVISION_ID = P_DIVISION_ID
                   AND VERSION_NO  = P_VERSION_NO) T;

        /* STEP 03_02. MKT FCST CUTOFF 데이터 적재 */
        INSERT INTO GT_DWRC_CUTOFF_INFO
             ( CUTOFF_TYPE
             , DIVISION_ID
             , VERSION_NO
             , CNT )
        VALUES ( 'MKT FCST CUTOFF'
             , P_DIVISION_ID
             , P_VERSION_NO
             , S_MKT_FCST_CNT );

        /* STEP 03_03. NET DEMAND 생성건수확인 */
        SELECT COUNT(*)
          INTO S_NETDEMAND_CNT
          FROM (SELECT DIVISION_ID
                  FROM DM_PLN_NET_DEMAND
                 WHERE DIVISION_ID = P_DIVISION_ID
                   AND VERSION_NO  = S_NET_PEGGING_VERSION) T;

        /* STEP 03_04. NET DEMAND 데이터 적재 */
        INSERT INTO GT_DWRC_CUTOFF_INFO
             ( CUTOFF_TYPE
             , DIVISION_ID
             , VERSION_NO
             , CNT )
        VALUES ( 'NET_DEMAND'
             , P_DIVISION_ID
             , S_NET_PEGGING_VERSION
             , S_NETDEMAND_CNT );

        /* STEP 03_05. PEGGING 생성건수확인 */
        SELECT COUNT(*)
          INTO S_PEGGING_CNT
          FROM (SELECT DIVISION_ID
                  FROM DM_PLN_DEMANDID_PEGGING
                 WHERE DIVISION_ID = P_DIVISION_ID
                   AND VERSION_NO  = S_NET_PEGGING_VERSION) T;

        /* STEP 03_06. PEGGING 데이터 적재 */
        INSERT INTO GT_DWRC_CUTOFF_INFO
             ( CUTOFF_TYPE
             , DIVISION_ID
             , VERSION_NO
             , CNT )
        VALUES ( 'PEGGING'
             , P_DIVISION_ID
             , S_NET_PEGGING_VERSION
             , S_PEGGING_CNT );

        DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME||' : A002--'||'MKT FCST CUTOFF: 버전:'||P_VERSION_NO||' /건수:'||S_MKT_FCST_CNT
                             ||' /NET DEMAND: 버전:'||S_NET_PEGGING_VERSION||' /건수:'||S_NETDEMAND_CNT
                             ||' /PEGGING: 버전:'||S_NET_PEGGING_VERSION||' /건수:'||S_PEGGING_CNT
                             ||' / '||TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));


        V_LOG_TYPE    := 'APPEND';
        V_LOG_MESSAGE := '##### APPEND of procedure #####';
        V_DESCRIPTION := 'MKT FCST CUTOFF: 버전:'||P_VERSION_NO||' /건수:'||S_MKT_FCST_CNT
                         ||' /NET DEMAND: 버전:'||S_NET_PEGGING_VERSION||' /건수:'||S_NETDEMAND_CNT
                         ||' /PEGGING: 버전:'||S_NET_PEGGING_VERSION||' /건수:'||S_PEGGING_CNT;
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        /* STEP 04. 메일발송 대상 : 룩업에 등록된 대상에 대해서만 발송 */
        /* [E20260529-001499] 방식변경(AS_IS 한명씩 / TO_BE 한번에 모두) - 원본 활성라인 = SELECT A.SEGMENT2(한명씩) */
        /* 원본 주석처리(비활성) 라인 : SELECT STRING_AGG( A.SEGMENT2, ';') */
        INSERT INTO GT_DWRC_MAIL_ADDR
             ( ADDR
             , SEQ )
        SELECT A.SEGMENT2
             , ROW_NUMBER() OVER (ORDER BY A.SEGMENT2) - 1 AS SEQ
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL A
         WHERE A.LOOKUP_TYPE = 'DM_WEEKLY_ROLLING_CUTOFF_MAIL_ADDR'
           AND (A.SEGMENT1 = P_DIVISION_ID OR A.SEGMENT1 = 'ALL')
           AND A.VALID_YN   = 'Y';

        DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME||' : A003--'||'Div: '||P_DIVISION_ID||' /VerNo: '||P_VERSION_NO
                             ||' /net_pegging_VerNo: '||S_NET_PEGGING_VERSION
                             ||' / '||TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));

        /* STEP 05. 메일발송 - 전송대상만큼 반복 (헤더, 본문) */
        /* STEP 05_01. 테이블 HEADER */
        V_MAIL_TITLE := 'Weekly Rolling Cutoff 완료 메일 발송';

        /* 원본 주석처리(개발용 문구) 보존 : 개발인경우 무조건 보내기 / 운영인 경우 주석처리 */
        /*   SET @v_body_contents = N'개발시스템 TEST 진행중입니다. </br> ' */
        /*                        + N'Weekly Rolling Cutoff가 완료되어, 생성된 버전 및 해당 데이터의 건수 안내드립니다. </br> ' */
        V_BODY_CONTENTS := '안녕하십니까, SCM.DM 시스템입니다. </br> '
                        || 'Weekly Rolling Cutoff가 완료되어, 생성된 버전 및 해당 데이터의 건수 안내드립니다. </br> ';

        V_HEAD_CONT := '<TR>
    <TH width:400px>CUTOFF TYPE</TH>
    <TH width:110px>DIVISION</TH>
    <TH width:150px>VERSION_NO</TH>
    <TH width:50px>CNT</TH>
    </TR>';

        DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME||' : A004--'||'Div: '||P_DIVISION_ID||' /VerNo: '||P_VERSION_NO
                             ||' /net_pegging_VerNo: '||S_NET_PEGGING_VERSION
                             ||' / '||TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));

        /* STEP 05_02. 테이블 반복 내용 (CUTOFF INFO 가 있을 때만 대상 수신자별 반복) */
        SELECT COUNT(*)
          INTO V_INFO_CNT
          FROM GT_DWRC_CUTOFF_INFO;

        IF V_INFO_CNT > 0 THEN

            /* [2026-10-07] 수신자를 ; 로 묶는다 — 본문이 수신자와 무관하게 동일하므로 한 통으로 보낸다.
             * 원본 MSSQL 은 [E20260529-001499] 로 「5명씩」 묶었는데(STRING_AGG + ((ROW_NUMBER()-1)/5)+1)
             * Oracle 변환본은 그 변경이 미반영된 「한 명씩」이었다. 사용자 결정 B 에 따라 동일 본문 전체를 묶는다.
             * 4000바이트를 넘으면 슬롯을 더 만들어 나눠 보낸다(주소가 늘어도 ORA-01489/12899 가 없다). */
            V_SLOT_CNT := 0;

            FOR A IN ( SELECT ADDR
                         FROM GT_DWRC_MAIL_ADDR
                        WHERE ADDR IS NOT NULL
                        ORDER BY SEQ ) LOOP
                IF V_SLOT_CNT = 0
                   OR LENGTHB(V_ADDR_SLOT(V_SLOT_CNT) || ';' || A.ADDR) > C_TO_MAIL_MAX THEN
                    V_SLOT_CNT := V_SLOT_CNT + 1;
                    V_ADDR_SLOT(V_SLOT_CNT) := A.ADDR;
                ELSE
                    V_ADDR_SLOT(V_SLOT_CNT) := V_ADDR_SLOT(V_SLOT_CNT) || ';' || A.ADDR;
                END IF;
            END LOOP;

            V_SLOT_I := 0;
            WHILE (V_SLOT_I < V_SLOT_CNT) LOOP

                V_OWNER     := V_ADDR_SLOT(V_SLOT_I + 1);   /* 슬롯은 1부터 */
                V_BODY_CONT := NULL;  /* 본문내용 생성 */

                FOR R IN (SELECT CUTOFF_TYPE, DIVISION_ID, VERSION_NO, CNT FROM GT_DWRC_CUTOFF_INFO A) LOOP
                    V_BODY_CONT := V_BODY_CONT||'<TR>';
                    V_BODY_CONT := V_BODY_CONT||'<TD ALIGN = LEFT >'||R.CUTOFF_TYPE||'</TD>';
                    V_BODY_CONT := V_BODY_CONT||'<TD ALIGN = LEFT >'||R.DIVISION_ID||'</TD>';
                    V_BODY_CONT := V_BODY_CONT||'<TD ALIGN = LEFT >'||R.VERSION_NO||'</TD>';
                    V_BODY_CONT := V_BODY_CONT||'<TD ALIGN = LEFT >'||R.CNT||'</TD>';
                    V_BODY_CONT := V_BODY_CONT||'</TR>';
                END LOOP;

                V_TABLE_BODY := ' <html>
                                        <head>
                                        <title>Untitled Document</title>
                                        <style>
                                            * {margin:0;padding:0;}
                                            body {font-family:Malgun Gothic, Arial, Helvetica, sans-serif;font-size:12px;line-height:1.8;color:#333333;}
                                            table {border-collapse:collapse;width:100%;}
                                            table th {background:#f5f5f5;border-bottom:1px solid #e1e1e1;}
                                            table td {background:#fff;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1;border-bottom:1px solid #e1e1e1;}
                                            table tbody th {border-left:1px solid #e1e1e1;text-align:right;padding:6px 8px;font-size:12px}
                                            table tbody td {padding:6px 8px;font-size:12px}
                                            table thead th {text-align:center;padding:3px;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1; border-bottom:1px solid #d1d1d1;font-size:12px}
                                            .hori-table table thead td {text-align:center;padding:3px;}
                                            .hori-table table tbody td {text-align:center;padding:3px;}
                                            .vertical-table, .hori-table {margin-bottom:20px;}
                                        </style>
                                        </head>
                                        <body></br><b>'||REPLACE(V_BODY_CONTENTS, CHR(10), '<br>')||'</b>'
                                        ||'<div id="divBody" style="width: 100%; overflow-x: auto; overflow-y: auto; font-size: 9pt; line-break: auto;">'
                                        ||'<table style=''border-top:2px solid #c8294b; width:700px;''>
                                    <thead>'||V_HEAD_CONT||'</thead>
                                    <tbody>'||V_BODY_CONT||'</tbody>
                                    </div>
                                </body>
                            </html>';

                DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME||' : A005--'||'Div: '||P_DIVISION_ID||' /VerNo: '||P_VERSION_NO
                                     ||' /net_pegging_VerNo: '||S_NET_PEGGING_VERSION
                                     ||' / '||TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));

                /* STEP 05_03. Mail 전송 (메일표준 PKG_SEND_MAIL.P_SEND_MAIL 직접전환, 2026-07-19 정책 확정) */

                /*   PKG_SEND_MAIL.P_SEND_MAIL('JSSBAE@lgespartner.com', V_MAIL_TITLE, V_TABLE_BODY, 'Y') */

                /* STEP 05_04. 메일은 운영일 경우에만 발송함. */
                /* 발송 환경 가드 교정(2026-10-06) : 원본 IF DB_NAME() <> 'LGCE_SCMDEV' 는 사내망 MSSQL 이
                   개발·품질 둘 다 DB 이름 LGCE_SCMDEV 라 운영 전용 조건이다. Oracle 엔 그 이름의 DB 가 없어
                   항상 참(=항상 발송)이 되므로 운영 PDB 일치 조건 LIKE 'OCGSCMP%' 로 교체했다. */
                IF SYS_CONTEXT('USERENV', 'DB_NAME') LIKE 'OCGSCMP%' THEN
                    PKG_SEND_MAIL.P_SEND_MAIL(V_OWNER, V_MAIL_TITLE, V_TABLE_BODY, 'Y');
                END IF;

                /* MAIL 발송 LOG 저장 (P_CATEGORY_ID 는 NUMBER -> MSSQL '-' 를 0 으로 전달) */
                /* [2026-10-07] 로그에 넘기는 수신자를 100자로 자른다 (사용자 결정 가).
                 * SCM_ADM_SMS_MAIL_SEND_LOG.SEGMENT2 는 VARCHAR2(100) 이고 하위 프로시저에 길이 보정이 없어
                 * 묶음 후 주소 2~3개만 넘어도 ORA-12899 -> ORA-20001 로 RAISE 되어 발송 루프가 중단된다(실측).
                 * 발송에는 전체 V_OWNER 를 쓰고 로그에만 자른다. */
                SCM_ADM_SAVE_MAIL_SEND_BATCH_LOG('MAIL', 0, V_PROGRAM_NAME, SUBSTR(V_OWNER, 1, 100)
                  , '', '', '', '', '', '', '', '', '', '');

                /* [2026-10-07] 발송 간 대기 삭제 (사용자 지시 2026-10-06).
                 * 묶음 교정은 별건으로 결정 대기(행 9 선례 B 적용 가능) — 대기 삭제만 먼저 반영한다.
                 * 원본 MSSQL 의 WAITFOR DELAY 는 그대로 둔다 — 원본을 고치는 게 아니라 Oracle 발송 방식에 맞춘 것이다.
                 * 삭제한 블록 : IF MOD(ADDR_REC.SEQ, 5) IN (0, 5) THEN SYS.DBMS_SESSION.SLEEP(30); END IF; */

                V_SLOT_I := V_SLOT_I + 1;
            END LOOP;

        END IF;

        DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME||' : A006--'||'Div: '||P_DIVISION_ID||' /VerNo: '||P_VERSION_NO
                             ||' /net_pegging_VerNo: '||S_NET_PEGGING_VERSION
                             ||' / '||TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));

    EXCEPTION
        WHEN OTHERS THEN
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := 'ERROR_BACKTRACE : '||SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 480);
            D_EVENT_DATE  := SYSDATE;
            DBMS_OUTPUT.PUT_LINE(V_LOG_MESSAGE);
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME
                                , V_LOG_TYPE
                                , N_LOG_COUNT
                                , V_LOG_MESSAGE
                                , V_DESCRIPTION
                                , D_EVENT_DATE
                                , P_IN_PARA_DATA  => V_IN_PARA_DATA
                                , P_SQL_ERR_CODE  => SQLCODE
                                , P_SQL_ERR_MSG   => SQLERRM
                                , P_SQL_BACKTRACE => DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
    END;

    /* 종료 LOG (END) - 예외 바깥 = 정상/에러 모두 항상 기록 */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '##### END of procedure #####';
    V_DESCRIPTION := 'Weekly Cutoff 완료 후 메일 발송 / Div: '||P_DIVISION_ID||' / Ver: '||P_VERSION_NO;
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

END;

