        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        -- [E20260701-001086]_웹서비스는 ERP -> SCM 데이터 Insert 작업까지만 한다. 주석처리 (START) [E20261006-ASISDELTA]
        -- 해당 작업은 [JOB.PR_DM_CUST_MODEL_MAPPING_IF] 작업에서 수행하도록 따로 뺌
--         /* ------------------------------------------------------------------------------------------------------------------------ */
--         /* PR_DM_CUST_MODEL_MAPPING_IF 호출 START LOG */
--         /* ------------------------------------------------------------------------------------------------------------------------ */
--         V_LOG_TYPE    := 'APPEND';
--         V_LOG_MESSAGE := 'PR_DM_CUST_MODEL_MAPPING_IF 호출 START';
--         V_DESCRIPTION := 'PR_DM_CUST_MODEL_MAPPING_IF 호출 START  ';
--         D_EVENT_DATE  := SYSDATE;
