PROCEDURE           "PR_DM_XIF_ERP_NSD0011_S" (
    O_RESULT_CURSOR OUT SYS_REFCURSOR,
    O_STATUS_CURSOR OUT SYS_REFCURSOR
)
/*
 * Program ID   : PR_DM_XIF_ERP_NSD0011_S
 * Description  : NERP SAP PO 전송 (XIF_ERP_SITE_ITEM_S_SN 전송대상 추출 및 전송상태 갱신)
 * 변환(MSSQL->Oracle) 2026-07-01 : SCMADM worker
 *   - 원본 테이블변수 @XIF_ERP_SITE_ITEM_S -> GTT GT_DXE_NSD0011 (ON COMMIT PRESERVE ROWS)
 *     내부 COMMIT 이후 OUT 커서가 스냅샷 rows 반환하도록 PRESERVE + 호출 시작 DELETE 초기화
 *   - 원본 2개 결과셋(전송대상 SELECT / E_TYPE,E_MESSAGE SELECT) -> 2개 OUT SYS_REFCURSOR
 *     (메타주도 BE 다중 OUT 커서 지원)
 *   - 원본 CATCH는 재발생(RAISE) 없이 상태만 반환 -> Oracle도 swallow 후 상태커서로 S/E 반환(충실)
 *   - XIF_ERP_SITE_ITEM_S_SN = SCM_MGR 시노님 -> INF_MGR.XIF_ERP_SITE_ITEM_S (SELECT/INSERT/UPDATE 직접 grant 보유)
 *   - GETDATE->SYSDATE, @@ROWCOUNT->SQL%ROWCOUNT, TRY/CATCH->EXCEPTION WHEN OTHERS
 *   - 원본에서 주석처리된 START/END 로그는 주석 유지(충실)
 * 2026.07.06	ZIONEX		[PJ202650304] NextSCM Migration
 */
AS
    E_TYPE          VARCHAR2(50 CHAR)   := 'S';        /* S:성공, E:오류 */
    E_MESSAGE       VARCHAR2(1000 CHAR) := 'SUCCESS';
    V_PROGRAM_NAME  VARCHAR2(150 CHAR)  := 'PR_DM_XIF_ERP_NSD0011_S';
    V_LOG_TYPE      VARCHAR2(30 CHAR);
    N_LOG_COUNT     INTEGER := 0;
    V_LOG_MESSAGE   VARCHAR2(1000 CHAR);
    V_DESCRIPTION   VARCHAR2(500 CHAR);
    D_EVENT_DATE    DATE;
BEGIN


    BEGIN

        UPDATE XIF_ERP_SITE_ITEM_S_SN
           SET TRANSFER_FLAG = 'P'
         WHERE TRANSFER_FLAG = 'N';


        DELETE
          FROM GT_DXE_NSD0011;

        INSERT
          INTO GT_DXE_NSD0011
             ( SEND_TIME
             , SERI_NO
             , DIVISION_ID
             , SCM_SITE_ID
             , END_CUSTOMER
             , SOLDTO_CODE
             , SHIPTO_CODE
             , PROJECT_CODE
             , ITEM_ID
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE )
        SELECT SEND_TIME
             , SERI_NO
             , DIVISION_ID
             , SCM_SITE_ID
             , END_CUSTOMER
             , SOLDTO_CODE
             , SHIPTO_CODE
             , PROJECT_CODE
             , ITEM_ID
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
          FROM XIF_ERP_SITE_ITEM_S_SN
         WHERE TRANSFER_FLAG = 'P';


        UPDATE XIF_ERP_SITE_ITEM_S_SN
           SET TRANSFER_FLAG = 'Y'
             , TRANSFER_DATE = SYSDATE
         WHERE TRANSFER_FLAG = 'P';

        IF SQL%ROWCOUNT > 0 THEN
            /* HISTORY LOG */
            N_LOG_COUNT   := SQL%ROWCOUNT;
            V_LOG_TYPE    := 'TXN';
            V_LOG_MESSAGE := 'INSERT INTO @XIF_ERP_SITE_ITEM_S_SN';
            V_DESCRIPTION := NULL;
            D_EVENT_DATE  := SYSDATE;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
        END IF;

        COMMIT;
    EXCEPTION
        WHEN OTHERS THEN
            ROLLBACK;
            E_TYPE    := 'E';
            E_MESSAGE := SQLERRM;
            /* ERROR LOG */
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := 'ERROR_LINE : ' || TO_CHAR(SQLCODE);
            D_EVENT_DATE  := SYSDATE;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    END;


    OPEN O_RESULT_CURSOR FOR
        SELECT SEND_TIME
             , SERI_NO
             , DIVISION_ID
             , SCM_SITE_ID
             , END_CUSTOMER
             , SOLDTO_CODE
             , SHIPTO_CODE
             , PROJECT_CODE
             , ITEM_ID
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
          FROM GT_DXE_NSD0011;

    /* 결과셋2 : 수행결과 성공여부 */
    OPEN O_STATUS_CURSOR FOR
        SELECT E_TYPE AS E_TYPE
             , E_MESSAGE AS E_MESSAGE
          FROM DUAL;


END;

PROCEDURE           "PR_DM_XIF_ERP_PR_DETAIL_S" 
(
    P_REQUEST_NO   IN  VARCHAR2   /* NVARCHAR(MAX) : REQUEST_NO 전달받음. */
)
/*
 * Program ID   : PR_DM_XIF_ERP_PR_DETAIL_S
 * Description  : NERP 대응 관련 신규I/F
 *                DM_PLN_PR_DETAIL -> XIF_ERP_PR_DETAIL_S_SN 테이블로 I/F 처리 Procedure
 * Program History
 *====================================================================================================
 *   Date       In Charge      Description
 *====================================================================================================
 * 2024.11.11	P.C.I			[PJ20228272] NERP 대응
 * ---------------------------------------------------------------------------------------------------
 * 	● 제약 조건 상세화 (DM → NERP)
 * 	- ESS 사업부만 대상
 *  - DM -> SSP로 전송되는 데이터를 NERP에 그대로 전송
 *  - REQUEST_NO 기준으로 데이터 생성
 * ---------------------------------------------------------------------------------------------------
 * 2026.08.03    ZIONEX    [PJ202650304]  NextSCM Migration
 */
AS

    /* 변수 설정 */
    V_TRANSFER_FLAG   VARCHAR2(1 CHAR)    := 'N';       /* IF_FLAG 인터페이스전송상태 (N:미처리,P:처리중,Y:처리완료) */
    V_TRANSFER_DATE   DATE                := SYSDATE;   /* IF_FLAG 인터페이스전송시간 (원본 GETDATE()) */

    V_SEND_TIME       VARCHAR2(50 CHAR)   := TO_CHAR(SYSDATE, 'YYYYMMDDHH24MISS');

    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME    VARCHAR2(150 CHAR)  := 'PR_DM_XIF_ERP_PR_DETAIL_S';
    V_LOG_TYPE        VARCHAR2(30 CHAR);                /* START/END/ERROR/... */
    N_LOG_COUNT       INTEGER             := 0;
    V_LOG_MESSAGE     VARCHAR2(1000 CHAR);
    V_DESCRIPTION     VARCHAR2(500 CHAR);
    D_EVENT_DATE      DATE;

    V_IN_PARA_DATA    VARCHAR2(4000 CHAR);

BEGIN


    V_IN_PARA_DATA := JSON_OBJECT('P_REQUEST_NO' VALUE P_REQUEST_NO);

    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';

    V_DESCRIPTION := '';
    D_EVENT_DATE  := V_TRANSFER_DATE;

    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    /* 트랜잭션 (START) */

    BEGIN

        /* I/F 테이블에 INSERT 처리
           XIF_ERP_PR_DETAIL_S_SN 은 SCM_MGR 시노님이고 실테이블은 INF_MGR.XIF_ERP_PR_DETAIL_S 다(LS-048 실측). */
        INSERT
          INTO XIF_ERP_PR_DETAIL_S_SN
             ( SEND_TIME
             , SERI_NO
             , REQUEST_NO
             , ITEM_SEQ
             , DIVISION_ID
             , PROJECT_CODE
             , SCM_SITE_ID
             , ITEM_ID
             , DOM_EXP
             , FCST_TYPE
             , INCOTERMS
             , PLANT_SITE_ID
             , REQ_YYYYMMDD
             , YYYYMMDD
             , UOM
             , PLAN_QTY
             , STORAGE_ID
             , STORAGE_PLANT_ID
             , PUCH_MGR
             , PUCH_GROUP
             , PR_HEADER
             , PR_ITEM_DETAIL
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , SSP_TRANSFER_FLAG
             , TRANSFER_FLAG
             , TRANSFER_DATE )
        SELECT V_SEND_TIME

             , ROW_NUMBER() OVER(ORDER BY NULL) AS SERI_NO
             , REQUEST_NO
             , ITEM_SEQ
             , DIVISION_ID
             , PROJECT_CODE
             , SCM_SITE_ID
             , ITEM_ID
             , DOM_EXP
             , FCST_TYPE
             , INCOTERMS
             , PLANT_SITE_ID
             , SUBSTR(REQUEST_NO, 1, 8) AS REQ_YYYYMMDD
             , YYYYMMDD
             , UOM
             , PLAN_QTY
             , STORAGE_ID
             , STORAGE_PLANT_ID
             , PUCH_MGR
             , PUCH_GROUP
             , PR_HEADER
             , PR_ITEM_DETAIL
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , SSP_TRANSFER_FLAG
             , V_TRANSFER_FLAG
             , V_TRANSFER_DATE
          FROM DM_PLN_PR_DETAIL
         WHERE REQUEST_NO = P_REQUEST_NO;

        /* HISTORY LOG
           SQL%ROWCOUNT 는 직전 SQL 기준이라 INSERT 바로 다음에서 변수로 받는다(원본 @@ROWCOUNT 위치 동일, CV-027) */
        N_LOG_COUNT   := SQL%ROWCOUNT;
        V_LOG_TYPE    := 'TXN';
        V_LOG_MESSAGE := 'INSERT INTO XIF_ERP_PR_DETAIL_S_SN';
        V_DESCRIPTION := '@P_REQUEST_NO : ' || P_REQUEST_NO;
        D_EVENT_DATE  := V_TRANSFER_DATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        /* 트랜잭션 (COMMIT)
           원본 COMMIT WORK; - 호출자 DMF0070_AUTO_PR_REQUEST 가 BEGIN TRANSACTION 안에서 호출하므로
             - 호출자 전수 = DMF0070_AUTO_PR_REQUEST 1건뿐(MSSQL 본문 전수 grep), 자기 COMMIT TRAN 소유 +
           => 성공 COMMIT 을 두지 않는다(호출자 최종 COMMIT 에 합류 = 원자성 유지). */

    EXCEPTION
        WHEN OTHERS THEN

            /* 트랜잭션 (END) */
            ROLLBACK;

            /* ERROR LOG */
            V_LOG_TYPE    := 'ERROR';

            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);

            V_DESCRIPTION := SUBSTR('ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 500);
            D_EVENT_DATE  := V_TRANSFER_DATE;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME
                                ,V_LOG_TYPE
                                ,N_LOG_COUNT
                                ,V_LOG_MESSAGE
                                ,V_DESCRIPTION
                                ,D_EVENT_DATE
                                ,P_IN_PARA_DATA  => V_IN_PARA_DATA
                                ,P_SQL_ERR_CODE  => SQLCODE
                                ,P_SQL_ERR_MSG   => SQLERRM
                                ,P_SQL_BACKTRACE => DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);

            RAISE_APPLICATION_ERROR(-20001
                                   ,SUBSTR('[' || V_PROGRAM_NAME || '] SQLCODE=' || SQLCODE || ' / SQLERRM=' || SQLERRM ||
                                           ' / BACKTRACE=' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE ||
                                           ' / PARAMS=' || V_IN_PARA_DATA, 1, 2000));
    END;

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := V_TRANSFER_DATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

END PR_DM_XIF_ERP_PR_DETAIL_S;

PROCEDURE           "PR_DM_XIF_ERP_SITE_ITEM_S"
(
    O_RESULT_CURSOR   OUT SYS_REFCURSOR
)
/*================================================================================================================================
 * Program ID   : PR_DM_XIF_ERP_SITE_ITEM_S
 * Description  : NERP 대응 관련 신규I/F
 *                SCM_MST_SITE_ITEM -> XIF_ERP_SITE_ITEM_S_SN 테이블로 I/F 처리 Procedure
 * Program History
 *================================================================================================================================
 *   Date       In Charge      Description
 *================================================================================================================================
 * 2024.11.11   P.C.I          [PJ20228272] NERP 대응
 *                             ● 제약 조건 상세화 (DM --> NERP)
 *                             - 자동차 사업부만 대상
 *                             - SCM_MST_SITE_ITEM에 신규로 추가되는 데이터를 NERP에 전송
 *                             - GT_DXES_XIF_ERP_SITE_ITEM 기준으로 데이터 생성
 * 2026.07.06   ZIONEX         [PJ202650304] NextSCM Migration
 * 2026.10.09   POJ            전송 시각 24시간제 · 오류 시 호출한 저장으로 오류 전달(AS-IS 와 같음)
 *================================================================================================================================*/
AS
    V_TRANSFER_FLAG   VARCHAR2(1 CHAR)    := 'N';
    V_TRANSFER_DATE   DATE                := SYSDATE;
    -- V_SEND_TIME       VARCHAR2(50 CHAR)   := TO_CHAR(CURRENT_TIMESTAMP, 'yyyyMMddHHmmss');    -- 2026.10.09 POJ 원본
    V_SEND_TIME       VARCHAR2(50 CHAR)   := TO_CHAR(CURRENT_TIMESTAMP, 'YYYYMMDDHH24MISS');    -- 2026.10.09 POJ 24시간제 시분초(AS-IS FORMAT 'yyyyMMddHHmmss' 와 같은 값)
    V_INPUT_COUNT     INTEGER             := 0;
    V_PROGRAM_NAME    VARCHAR2(200 CHAR)  := $$PLSQL_UNIT;
    V_STEP            VARCHAR2(4000 CHAR) := NULL;
    V_LOG_TYPE        VARCHAR2(30 CHAR);
    N_LOG_COUNT       INTEGER             := 0;
    V_LOG_MESSAGE     VARCHAR2(1000 CHAR);
    V_DESCRIPTION     VARCHAR2(500 CHAR);
    D_EVENT_DATE      DATE;
    V_IN_PARA_DATA    CLOB;
BEGIN
    IF UTL_CALL_STACK.SUBPROGRAM(1).COUNT > 1 THEN
        V_PROGRAM_NAME := $$PLSQL_UNIT || '.' || UTL_CALL_STACK.SUBPROGRAM(1) (2);
    END IF;
    /* 변수 설정 */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := NULL;
    D_EVENT_DATE  := V_TRANSFER_DATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    /* 트랜잭션 (START) */
    SELECT COUNT(*)
      INTO V_INPUT_COUNT
      FROM GT_DXES_XIF_ERP_SITE_ITEM;
    IF V_INPUT_COUNT > 0 THEN
        /* I/F 테이블에 INSERT 처리 */
        /* ※ XIF_ERP_SITE_ITEM_S_SN = SCM_MGR 시노님 -> 실테이블 INF_MGR.XIF_ERP_SITE_ITEM_S */
        INSERT /* XIF_ERP_SITE_ITEM_S_SN 적재 */
          INTO XIF_ERP_SITE_ITEM_S_SN
             ( SEND_TIME
             , SERI_NO
             , DIVISION_ID
             , SCM_SITE_ID
             , END_CUSTOMER
             , SOLDTO_CODE
             , SHIPTO_CODE
             , PROJECT_CODE
             , ITEM_ID
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , TRANSFER_FLAG
             , TRANSFER_DATE )
        SELECT V_SEND_TIME
             , ROW_NUMBER() OVER (ORDER BY 1)   AS SERI_NO
             , XESI.DIVISION_ID
             , XESI.SCM_SITE_ID
             , SMS.END_CUSTOMER
             , SMSC.SOLDTO_CODE
             , SMSC.SHIPTO_CODE
             , XESI.PROJECT_CODE
             , XESI.ITEM_ID
             , XESI.CREATED_BY
             , XESI.CREATION_DATE
             , XESI.LAST_UPDATED_BY
             , XESI.LAST_UPDATE_DATE
             , V_TRANSFER_FLAG
             , V_TRANSFER_DATE
          FROM GT_DXES_XIF_ERP_SITE_ITEM   XESI
             , SCM_MST_SITE                SMS
             , SCM_MST_SITE_CUSTOMER       SMSC
         WHERE SMS.DIVISION_ID(+)  = XESI.DIVISION_ID
           AND SMS.SCM_SITE_ID(+)  = XESI.SCM_SITE_ID
           AND SMSC.DIVISION_ID    = XESI.DIVISION_ID
           AND SMSC.SCM_SITE_ID    = XESI.SCM_SITE_ID
           AND XESI.DIVISION_ID LIKE '81%'
           AND SMSC.REP_YN      =  'Y';
    END IF;
    /* HISTORY LOG */
    N_LOG_COUNT   := SQL%ROWCOUNT;
    V_LOG_TYPE    := 'TXN';
    V_LOG_MESSAGE := 'INSERT INTO XIF_ERP_SITE_ITEM_S_SN';
    V_DESCRIPTION := NULL;
    D_EVENT_DATE  := V_TRANSFER_DATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    /* 트랜잭션 (COMMIT) */
    COMMIT;
    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := NULL;
    D_EVENT_DATE  := V_TRANSFER_DATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
EXCEPTION
    WHEN OTHERS THEN
        /* 트랜잭션 (END) */
        ROLLBACK;
        /* ERROR LOG */
        V_LOG_TYPE    := 'ERROR';
        V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
        V_DESCRIPTION := 'ERROR_LINE : ';
        D_EVENT_DATE  := V_TRANSFER_DATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
        /* 종료 LOG */
        V_LOG_TYPE    := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := NULL;
        D_EVENT_DATE  := V_TRANSFER_DATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME
                            ,'E'
                            ,0
                            ,SQLERRM
                            ,NULL
                            ,SYSDATE
                            ,P_IN_PARA_DATA  => V_IN_PARA_DATA
                            ,P_SQL_ERR_CODE  => SQLCODE
                            ,P_SQL_ERR_MSG   => SQLERRM
                            ,P_SQL_BACKTRACE => DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
        RAISE;    -- 2026.10.09 POJ 오류를 호출한 저장으로 전달(AS-IS 는 ROLLBACK 으로 저장 전체 실패)
END;

PROCEDURE PR_ERROR_CHK_SMS_SEND
(
    P_CATEGORY_ID INTEGER
   ,P_LONGTM_MSG  VARCHAR2 DEFAULT ''
   ,P_CHECK_TM    INTEGER
)
/*
    * Program ID   : PR_ERROR_CHK_SMS_SEND
    * Description  : 오류작업 체크 및 SMS 전송
    * Program History
    *===================================================================================================
    *   Date       In Charge      Description
    *===================================================================================================
    * [E20250529-001289]         check time 5 -> 6 분 (JOB 이 5분단위로 돌기때문에 놓치는 건이 발생함)
    * [E20250529-001289]         JOB 에서 오류가 나는 경우에도 SMS 발송을 진행한다
    * 2026.09.21   ZIONEX         [PJ202650304] NextSCM Migration
    */
 AS

    V_IN_PARA_DATA     VARCHAR2(4000 CHAR);
    V_RESULT           VARCHAR2(4000 CHAR);
    N_DEF_CHECK_TM     INTEGER := 6;
    N_CHECK_TM         INTEGER;
    N_LONGTM_FETCH_STS INTEGER;
    N_PROC_CNT         INTEGER;
    V_PGM_NAME         VARCHAR2(150 CHAR);
    V_PGM_LOG_TYPE     VARCHAR2(150 CHAR);
    V_PGM_EVENT_TM     DATE;
    V_MESSAGE_CONTENT  VARCHAR2(4000 CHAR);
    V_SMS_PHONE        VARCHAR2(50 CHAR);
    V_SMS_SEND_PHONE   VARCHAR2(50 CHAR);
    V_USE_TYPE_CODE    VARCHAR2(10 CHAR);
    V_MODULE_CODE      VARCHAR2(30 CHAR);
    V_PROGRAM_NAME     VARCHAR2(150 CHAR) := $$PLSQL_UNIT;
    V_LOG_TYPE         VARCHAR2(30 CHAR);
    N_LOG_COUNT        INTEGER := 0;
    V_LOG_MESSAGE      VARCHAR2(1000 CHAR);
    V_DESCRIPTION      VARCHAR2(500 CHAR);
    D_EVENT_DATE       DATE;

    CURSOR CUR_ERROR_LOG IS
        SELECT *
          FROM GT_ECSS_SCP_ERROR_CHECK;

    CURSOR CUR_ERLM_SEND IS
        SELECT *
          FROM GT_ECSS_TBLERRSMSSENDBATCH;
BEGIN

    IF UTL_CALL_STACK.SUBPROGRAM(1).COUNT > 1 THEN
        V_PROGRAM_NAME := $$PLSQL_UNIT || '.' || UTL_CALL_STACK.SUBPROGRAM(1) (2);
    END IF;

    V_IN_PARA_DATA := JSON_OBJECT('p_category_id' VALUE P_CATEGORY_ID, 'p_longtm_msg' VALUE P_LONGTM_MSG, 'p_check_tm' VALUE P_CHECK_TM);

    EXECUTE IMMEDIATE 'TRUNCATE TABLE GT_ECSS_SCP_ERROR_CHECK';
    EXECUTE IMMEDIATE 'TRUNCATE TABLE GT_ECSS_TBLERRSMSSENDBATCH';

    /* 처리용 변수 설정 */
    /* LOG 용 변수 설정 */
    BEGIN
        IF (P_CHECK_TM > 0) THEN
            N_CHECK_TM := P_CHECK_TM;
        ELSE
            N_CHECK_TM := N_DEF_CHECK_TM;
        END IF;
    END;

    /********************************************************************************
    * 오류작업 SMS 를 보낼 대상을 추출하기 위해서 임시테이블만들기
    ********************************************************************************/
    INSERT
      INTO GT_ECSS_SCP_ERROR_CHECK
    SELECT PROGRAM_NAME
         , LOG_TYPE
         , MAX(EVENT_DATE) AS EVENT_DATE
      FROM SCM_SYS_LOG_BATCH
     WHERE 1 = 1
       AND ((SYSDATE - EVENT_DATE) * 1440) < N_CHECK_TM
       AND LOG_TYPE = 'ERROR'
     GROUP BY PROGRAM_NAME, LOG_TYPE;

    /* ---------------------------------------------------------------------------------------------
       [E20250529-001289]_JOB에서 오류가 나는 경우에도 SMS 발송을 진행한다. START
       --------------------------------------------------------------------------------------------- */
    /* MSSQL 원본은 SQL Agent 잡 이력(msdb)을 읽는다. Oracle 에는 msdb 가 없어 그대로 옮길 수 없다.
       원본 :
       --INSERT INTO #tmp_SCP_ERROR_CHECK
       --SELECT T.PROGRAM_NAME, T.LOG_TYPE, MAX(T.EVENT_DATE) AS EVENT_DATE
       --FROM (  SELECT JOB.NAME AS PROGRAM_NAME, 'ERROR' AS LOG_TYPE
       --             , msdb.dbo.agent_datetime(run_date, run_time) as EVENT_DATE
       --        FROM  [msdb].[dbo].[sysjobhistory] HS
       --        INNER JOIN [msdb].[dbo].[sysjobs] JOB ON HS.JOB_ID = JOB.JOB_ID
       --        INNER JOIN  sys.sql_logins LOGI ON JOB.OWNER_SID = LOGI.SID
       --        WHERE   HS.RUN_STATUS = 0
       --        AND     LOGI.DEFAULT_DATABASE_NAME <> 'LGCE_LOGIPROD'
       --        AND     HS.STEP_ID > 0 ) T
       -- WHERE 1=1
       -- AND DATEDIFF ( MI, T.EVENT_DATE, GETDATE()) < @n_check_tm
       -- AND T.LOG_TYPE = 'ERROR'
       -- GROUP BY PROGRAM_NAME, LOG_TYPE
       -- ;
       대체 : Oracle 스케줄러 잡 실행이력 ALL_SCHEDULER_JOB_RUN_DETAILS 로 재설계(사용자 결정 2026-09-21).
         · sysjobhistory/sysjobs      -> ALL_SCHEDULER_JOB_RUN_DETAILS (잡 이름 = JOB_NAME)
         · HS.RUN_STATUS = 0 (실패)   -> STATUS <> 'SUCCEEDED'
         · agent_datetime(run_date,run_time) -> ACTUAL_START_DATE (TIMESTAMP WITH TIME ZONE -> DATE 캐스팅)
         · LOGI.DEFAULT_DATABASE_NAME <> 'LGCE_LOGIPROD'
             -> Oracle 에는 잡 소유자의 기본 DB 개념이 없다. 원본 의도(물류 DB 잡은 감시 제외 = 우리 잡만 감시)를
                살려 OWNER = 'SCM_MGR' 로 치환(사용자 결정).
         · HS.STEP_ID > 0
             -> MSSQL 은 스텝별 행 + 잡 요약 행(STEP_ID=0)이 함께 남아 요약행을 걸러내는 조건이다.
                Oracle 스케줄러 잡은 스텝 구분 없이 실행 1건 = 1행이라 중복이 없어 조건이 불필요하다(사용자 결정). */
    INSERT
      INTO GT_ECSS_SCP_ERROR_CHECK
    SELECT T.PROGRAM_NAME
         , T.LOG_TYPE
         , MAX(T.EVENT_DATE) AS EVENT_DATE
      FROM (SELECT D.JOB_NAME AS PROGRAM_NAME
                 , 'ERROR' AS LOG_TYPE
                 , CAST(D.ACTUAL_START_DATE AS DATE) AS EVENT_DATE
              FROM ALL_SCHEDULER_JOB_RUN_DETAILS D
             WHERE D.STATUS <> 'SUCCEEDED'
               AND D.OWNER = 'SCM_MGR') T
     WHERE 1 = 1
       AND ((SYSDATE - T.EVENT_DATE) * 1440) < N_CHECK_TM
       AND T.LOG_TYPE = 'ERROR'
     GROUP BY T.PROGRAM_NAME, T.LOG_TYPE;
    /* ---------------------------------------------------------------------------------------------
       [E20250529-001289]_JOB에서 오류가 나는 경우에도 SMS 발송을 진행한다. END
       --------------------------------------------------------------------------------------------- */

    /********************************************************************************
    * SMS 대상자 임시테이블만들기
    ********************************************************************************/
    V_RESULT := NULL;
    V_RESULT := V_RESULT || '        SELECT b.message_content ' || CHR(10);
    V_RESULT := V_RESULT || '              ,c.sms_phone ' || CHR(10);
    V_RESULT := V_RESULT || '              ,a.use_type_code ' || CHR(10);
    /* 원본은 이 줄만 CHAR(30) 으로 되어 있으나(다른 줄은 전부 CHAR(10)) 줄바꿈 의도가 분명하고
       자매 PR_LONGTIME_CHK_SMS_SEND 변환본도 CHR(10) 으로 맞춰져 있어 동일하게 CHR(10) 을 쓴다.
       원본 : SET @v_result = @v_result+'              ,a.module_code '+CHAR(30) */
    V_RESULT := V_RESULT || '              ,a.module_code ' || CHR(10);
    V_RESULT := V_RESULT || '          FROM SCM_ADM_RECIPIENT_LIST a ' || CHR(10);
    V_RESULT := V_RESULT || '         INNER JOIN SCM_ADM_RECIPIENT_MESSAGE b ' || CHR(10);
    V_RESULT := V_RESULT || '            ON a.CATEGORY_ID = b.CATEGORY_ID  ' || CHR(10);
    V_RESULT := V_RESULT || '         INNER JOIN SCM_ADM_RECIPIENT_SMS_ASSIGN c   ' || CHR(10);
    V_RESULT := V_RESULT || '            ON a.CATEGORY_ID = c.CATEGORY_ID ' || CHR(10);
    V_RESULT := V_RESULT || '         WHERE a.CATEGORY_ID =' || TO_CHAR(P_CATEGORY_ID) || CHR(10);
    V_RESULT := V_RESULT || '              AND a.VALID_YN = ''Y'' ' || CHR(10);

    EXECUTE IMMEDIATE 'INSERT /*+ NO_PARALLEL */ INTO GT_ECSS_TBLERRSMSSENDBATCH ' || V_RESULT;

    /********************************************************************************
    메인 처리시작
    ********************************************************************************/

    /* SP 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := NULL;
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    OPEN CUR_ERROR_LOG;
    FETCH CUR_ERROR_LOG
        INTO V_PGM_NAME, V_PGM_LOG_TYPE, V_PGM_EVENT_TM;

    IF CUR_ERROR_LOG%NOTFOUND THEN
        N_LONGTM_FETCH_STS := -1;
    ELSE
        N_LONGTM_FETCH_STS := 0;
    END IF;  /* 이중 loop 를 사용하므로 장기실행 미완료 건에 대한 fetch status 를 보관한다. */

    N_PROC_CNT := 0;

    /* 장기수행 미완료 건을 Fetch 해서 순차처리한다. */
    V_LOG_TYPE    := 'TXN';
    N_LOG_COUNT   := SQL%ROWCOUNT;
    V_LOG_MESSAGE := 'Error process check';
    V_DESCRIPTION := 'sms category / check time(min) ... ' || ' / ' || TO_CHAR(P_CATEGORY_ID) || ' / ' || TO_CHAR(P_CHECK_TM);
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    WHILE N_LONGTM_FETCH_STS = 0 LOOP

        /* select v_pgm_name, v_pgm_log_type, v_pgm_event_tm; */
        /* 현재 Fetch 된 미완료건을 SMS 대상자 모두에게 전송한다. */
        IF N_PROC_CNT = 0 THEN
            OPEN CUR_ERLM_SEND;
        END IF;

        IF N_PROC_CNT = 9 THEN
            CLOSE CUR_ERLM_SEND;
            OPEN CUR_ERLM_SEND;
            FETCH CUR_ERLM_SEND
                INTO V_MESSAGE_CONTENT, V_SMS_PHONE, V_USE_TYPE_CODE, V_MODULE_CODE;
        ELSE
            FETCH CUR_ERLM_SEND
                INTO V_MESSAGE_CONTENT, V_SMS_PHONE, V_USE_TYPE_CODE, V_MODULE_CODE;
        END IF;

        N_PROC_CNT := 1;

        WHILE CUR_ERLM_SEND%FOUND LOOP

            BEGIN
                IF P_LONGTM_MSG IS NOT NULL THEN
                    V_MESSAGE_CONTENT := SUBSTR('[' || V_MODULE_CODE || ']' || P_LONGTM_MSG || ' ' || V_MESSAGE_CONTENT, 1, 79);
                ELSE
                    V_MESSAGE_CONTENT := SUBSTR('[' || V_MODULE_CODE || ']PNM:' || V_PGM_NAME || ' ' || V_MESSAGE_CONTENT, 1, 79);
                END IF;
            END;

            V_SMS_SEND_PHONE := NULL;
            V_SMS_SEND_PHONE := '01099999999';

            INSERT
              INTO XIF_IFS_SMS_DATA_SN
                 ( IF_TYPE
                 , IF_ID
                 , IF_INS_DATE
                 , IF_FLAG
                 , TR_SENDSTAT
                 , TR_MSGTYPE
                 , TR_PHONE
                 , TR_CALLBACK
                 , TR_MSG )
            VALUES ( 'S'
                   , 'OFP0_OSMS_SMS'
                   , SYSDATE
                   , 'N'
                   , '0'
                   , '0'
                   , V_SMS_PHONE
                   , V_SMS_SEND_PHONE
                   , V_MESSAGE_CONTENT );

            /* SMS 발송 LOG 저장 */
            SCM_ADM_SAVE_MAIL_SEND_BATCH_LOG(V_USE_TYPE_CODE
                                            ,P_CATEGORY_ID
                                            ,V_SMS_PHONE
                                            ,V_MESSAGE_CONTENT
                                            ,''
                                            ,''
                                            ,''
                                            ,''
                                            ,''
                                            ,''
                                            ,''
                                            ,''
                                            ,''  /* p_send_pgm */
                                            ,V_SMS_PHONE);

            /* select v_use_type_code, p_category_id, v_sms_phone, v_message_content; */

            V_MESSAGE_CONTENT := NULL;

            FETCH CUR_ERLM_SEND
                INTO V_MESSAGE_CONTENT, V_SMS_PHONE, V_USE_TYPE_CODE, V_MODULE_CODE;

        END LOOP;

        N_PROC_CNT := 9;

        /* 다음 미완료 건을 Fetch 한다. */
        FETCH CUR_ERROR_LOG
            INTO V_PGM_NAME, V_PGM_LOG_TYPE, V_PGM_EVENT_TM;

        IF CUR_ERROR_LOG%NOTFOUND THEN
            N_LONGTM_FETCH_STS := -1;
        ELSE
            N_LONGTM_FETCH_STS := 0;
        END IF;  /* 이중 loop 를 사용하므로 장기실행 미완료 건에 대한 fetch status 를 보관한다. */

    END LOOP;  /* 장기수행 미완료건 loop end. */

    /* 장기수행 미완료건 커서해제 */
    CLOSE CUR_ERROR_LOG;

    /* SMS 대상자 커서해제 */
    IF N_PROC_CNT > 0 THEN
        CLOSE CUR_ERLM_SEND;
    END IF;

    /* 임시 테이블 삭제
       원본은 여기서 #tmp_SCP_LONGTM_CHECK / #tmp_TblSmsSendBatch 를 DROP 하나, 이 프로시저가 만드는 것은
       #tmp_SCP_ERROR_CHECK / #tmp_TblErrSmsSendBatch 라 실제로는 아무것도 지우지 않는다(자매에서 복사된 이름).
       Oracle 은 GTT 라 세션 종료 시 자동 정리되고 진입부 TRUNCATE 로 초기화하므로 대응 구문이 없다.
       원본 :
       --IF EXISTS (SELECT * FROM tempdb.sys.sysobjects WHERE name = '#tmp_SCP_LONGTM_CHECK')
       --   DROP TABLE #tmp_SCP_LONGTM_CHECK
       --IF EXISTS (SELECT * FROM tempdb.sys.sysobjects WHERE name = '#tmp_TblSmsSendBatch')
       --   DROP TABLE #tmp_TblSmsSendBatch */

    /* SP 종료 log. */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := NULL;
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    COMMIT;

    /* error catch... */
EXCEPTION
    WHEN OTHERS THEN
        /* cursor 를 해제한다. */
        IF CUR_ERROR_LOG%ISOPEN THEN
            CLOSE CUR_ERROR_LOG;
        END IF;

        IF CUR_ERLM_SEND%ISOPEN THEN
            CLOSE CUR_ERLM_SEND;
        END IF;

        ROLLBACK;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME
                            ,'ERROR'
                            ,0
                            ,SQLERRM
                            ,NULL
                            ,SYSDATE
                            ,P_IN_PARA_DATA  => V_IN_PARA_DATA
                            ,P_SQL_ERR_CODE  => SQLCODE
                            ,P_SQL_ERR_MSG   => SQLERRM
                            ,P_SQL_BACKTRACE => DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);

        /* 원본은 에러코드/메시지를 결과셋으로 반환하나(SELECT 'F' AS result_code; / SELECT '['+...+']'+ERROR_MESSAGE();),
           이 프로시저는 스케줄 배치(JOB.PR_ERROR_CHK_SMS_SEND)에서만 호출되어 결과셋 소비자가 없다(SOP H-9(b)).
           오류 내용은 바로 위 PR_SCM_SYS_LOG_BATCH 로 SCM_SYS_LOG_BATCH 에 남고, 호출자에는 예외로 전파한다.
           원본 :
           --SELECT 'F' AS result_code;
           --SELECT '[' + Convert(NVARCHAR(10), ERROR_NUMBER()) + ']' + ERROR_MESSAGE(); */
        RAISE_APPLICATION_ERROR(-20001
                               ,'[' || V_PROGRAM_NAME || '] SQLCODE=' || SQLCODE || ' / SQLERRM=' || SQLERRM || ' / BACKTRACE=' ||
                                DBMS_UTILITY.FORMAT_ERROR_BACKTRACE || ' / PARAMS=' || V_IN_PARA_DATA);

END;

