      INTO V_INTERFACEID
      FROM GT_ZSDGR05700
     WHERE 1 = 1;


    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    BEGIN

        INSERT INTO XIF_ERP_VMI_STOCK_R_SN
             ( IFSEQNO
             , INTERFACEID
             , IFDAT
             , IFTYPE
             , IFSEQ
             , WERKS
             , LGORT
             , MATNR
             , BSART
             , EBELN
             , VKORG
             , VTWEG
             , SPART
             , TKNUM
             , VBELN_D
             , INVN_QTY
             , UNIT
             , ACT_IN_DATE
             , BASE_DT
             , STATUS_CD
             , TRANSFER_DATE
             , TRANSFER_FLAG
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , ATTRIBUTE6
             , ATTRIBUTE7
             , ATTRIBUTE8
             , ATTRIBUTE9
             , ATTRIBUTE10 )
        SELECT TO_CHAR(SYSDATE, 'YYYYMMDD') || SUBSTR('000000' || TO_CHAR(SEQ1_XIF_ERP_VMI_STOCK_R.NEXTVAL), -6)
             , NVL(V_INTERFACEID, '-')
             , IFDAT
             , IFTYPE
             , IFSEQ
             , WERKS
             , LGORT
             , MATNR
             , BSART
             , EBELN
             , VKORG
             , VTWEG
             , SPART
             , TKNUM
             , VBELN_D
             , INVN_QTY
             , UNIT
             , ACT_IN_DATE
             , BASE_DT
             , STATUS_CD
             , V_TRANSFER_DATE
             , V_TRANSFER_FLAG
             , ''
             , ''
             , ''
             , ''
             , ''
             , ''
             , ''
             , ''
             , ''
             , ''
          FROM GT_ZSDGR05700;

        /* HISTORY LOG (TXN) */
        N_LOG_COUNT   := SQL%ROWCOUNT;
        V_LOG_TYPE    := 'TXN';
        V_LOG_MESSAGE := 'INSERT INTO XIF_ERP_VMI_STOCK_R_SN';
        V_DESCRIPTION := '@ZSDGT50770';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    EXCEPTION
        WHEN OTHERS THEN

            ROLLBACK;
            V_E_TYPE    := 'E';
            V_E_MESSAGE := SUBSTR(SQLERRM, 1, 100);
            /* ERROR LOG */
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := 'ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
            D_EVENT_DATE  := SYSDATE;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    END;


    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);


    OPEN O_RESULT_CURSOR FOR
    SELECT V_E_TYPE    AS E_TYPE
         , V_E_MESSAGE AS E_MESSAGE
      FROM DUAL;
END;

PROCEDURE           "PR_LONGTIME_CHK_SMS_SEND" 

(
    P_CATEGORY_ID INTEGER
   ,P_LONGTM_MSG  VARCHAR2 DEFAULT ''
   ,P_CHECK_TM    INTEGER
)
/*
    * Program ID   : PR_LONGTIME_CHK_SMS_SEND
    * Description  : 장기수행작업 체크 및 SMS 전송
    * Program History
    *===================================================================================================
    *   Date       In Charge      Description
    *===================================================================================================
    * 2020/08/13   KSW            장기수행작업 체크 및 SMS 전송
    * 2020/08/25   KSW            장기수행 체크 예외처리 (LOOKUP 등록건 예외처리)
    * 2020/09/22   KSW            프로시저 이름이 긴 경우 오류가 발생하므로 MSG 길이를 80 byte 제한
    * 2024/11/25   kimcd          기본 30분 초과 시간 초과 작업별 초과 시간 조정하여 작업 중요도 전송. 수신자 level 관리
    * 2026.03.24   김준규           [PJ20264226] NextSCM Pilot 설계 및 개발
 * 2026.07.06	ZIONEX		[PJ202650304] NextSCM Migration
    */
 AS

    V_IN_PARA_DATA     VARCHAR2(4000 CHAR);
    V_RESULT           VARCHAR2(4000 CHAR);
    N_DEF_CHECK_TM     INTEGER := 30;
    N_CHECK_TM         INTEGER;
    N_LONGTM_FETCH_STS INTEGER;
    N_PROC_CNT         INTEGER;
    V_PGM_NAME         VARCHAR2(150 CHAR);
    V_PGM_LOG_TYPE     VARCHAR2(150 CHAR);
    V_PGM_EVENT_TM     DATE;
    V_PGM_RUN_TIME     NUMBER;
    V_PGM_C_TIME       INTEGER;
    V_MESSAGE_CONTENT  VARCHAR2(4000 CHAR);
    V_SMS_PHONE        VARCHAR2(50 CHAR);
    V_SMS_SEND_PHONE   VARCHAR2(50 CHAR);
    V_USE_TYPE_CODE    VARCHAR2(10 CHAR);
    V_MODULE_CODE      VARCHAR2(30 CHAR);
    V_RECEIVER_LEVEL   INTEGER;
    V_PROGRAM_NAME     VARCHAR2(150 CHAR) := $$PLSQL_UNIT;
    V_LOG_TYPE         VARCHAR2(30 CHAR);
    N_LOG_COUNT        INTEGER := 0;
    V_LOG_MESSAGE      VARCHAR2(1000 CHAR);
    V_DESCRIPTION      VARCHAR2(500 CHAR);
    D_EVENT_DATE       DATE;
    V_CNT_1            INTEGER := 0;
    V_CNT_2            INTEGER := 0;
    V_CNT_3            INTEGER := 0;
    V_CNT_4            INTEGER := 0;

    CURSOR CUR_LONGTM_LOG IS
        SELECT *
          FROM GT_LCSS_SCP_LONGTM_CHECK;

    CURSOR CUR_LM_SEND IS
        SELECT *
          FROM GT_LCSS_TBLSMSSENDBATCH;
BEGIN

    IF UTL_CALL_STACK.SUBPROGRAM(1).COUNT > 1 THEN
        V_PROGRAM_NAME := $$PLSQL_UNIT || '.' || UTL_CALL_STACK.SUBPROGRAM(1) (2);
    END IF;

    V_IN_PARA_DATA := JSON_OBJECT('p_category_id' VALUE P_CATEGORY_ID, 'p_longtm_msg' VALUE P_LONGTM_MSG, 'p_check_tm' VALUE P_CHECK_TM);

    EXECUTE IMMEDIATE 'TRUNCATE TABLE GT_LCSS_SCP_LONGTM_CHECK';
    EXECUTE IMMEDIATE 'TRUNCATE TABLE GT_LCSS_TBLSMSSENDBATCH';

    NULL;

    /* 처리용 변수 설정 */
    /* LOG 용 변수 설정 */
    BEGIN
        IF (P_CHECK_TM > 0) THEN
            N_CHECK_TM := P_CHECK_TM;
        ELSE
            N_CHECK_TM := N_DEF_CHECK_TM;
        END IF;
    END;

    /********************************************************************************
    * 장기수행작업 SMS 를 보낼 대상을 추출하기 위해서 임시테이블만들기
    ********************************************************************************/

    NULL;

    /* ------------------------------------------------------------------------------
       장기수행 체크 예외처리 (LOOKUP 등록건 예외처리) 추가 :: 2020.08.25 KSW - start
       ------------------------------------------------------------------------------
       이하 주석처리
       --INSERT \*+ NO_PARALLEL *\ INTO GT_LCSS_SCP_LONGTM_CHECK
       --SELECT W.PROGRAM_NAME, W.LOG_TYPE, MAX(W.EVENT_DATE) EVENT_DATE
       --  FROM (
       --     SELECT PROGRAM_NAME, LOG_TYPE, EVENT_DATE
       --       FROM SCM_SYS_LOG_BATCH
       --      WHERE (SYSDATE - EVENT_DATE) < 1
       --        AND LOG_TYPE = 'START'
       --      ) W
       -- WHERE NOT EXISTS ( SELECT 1 FROM SCM_SYS_LOG_BATCH X
       --                  WHERE W.PROGRAM_NAME = X.PROGRAM_NAME
       --                    AND W.EVENT_DATE <= X.EVENT_DATE
       --                    AND X.LOG_TYPE IN ( 'END', 'ERROR' )
       --               )
       --   AND ((SYSDATE - EVENT_DATE) * 1440) > n_check_tm
       --    GROUP BY W.PROGRAM_NAME, W.LOG_TYPE
       -- ; */
    /* 2024-11-25 kimcd 작업 기준 시간 조회 추가 */
    INSERT
      INTO GT_LCSS_SCP_LONGTM_CHECK
    SELECT W.PROGRAM_NAME
         , W.LOG_TYPE
         , MAX(W.EVENT_DATE) EVENT_DATE
         , MAX(((SYSDATE - EVENT_DATE) * 1440)) RUN_TIME  /* 2024-11-25 kimcd 작업 경과 시간 추가 */
         , NVL((SELECT TO_NUMBER(JOB.C_TIME)
                  FROM (SELECT SEGMENT1 AS PROC_NAME, ATTRIBUTE1 C_TIME
                          FROM SCM_ADM_LOOKUP_MASTER_DETAIL AMD
                         WHERE AMD.LOOKUP_TYPE = 'SCM_LONG_TEMP_JOB'
                           AND AMD.VALID_YN = 'Y') JOB
                 WHERE JOB.PROC_NAME = W.PROGRAM_NAME)
              , N_CHECK_TM) C_TIME  /* 2024-11-25 kimcd 기준 시간 추가 */
      FROM (SELECT PROGRAM_NAME, LOG_TYPE, EVENT_DATE
              FROM SCM_SYS_LOG_BATCH
             WHERE (SYSDATE - EVENT_DATE) < 1
               AND LOG_TYPE = 'START'
               AND NOT PROGRAM_NAME IN (SELECT SEGMENT2 AS PROGRAM_NM
                                          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                                         WHERE LOOKUP_TYPE = 'LONGTIME_SMS_EXCEPT_LIST'
                                           AND VALID_YN = 'Y')) W
     WHERE NOT EXISTS (SELECT 1
                         FROM SCM_SYS_LOG_BATCH X
                        WHERE W.PROGRAM_NAME = X.PROGRAM_NAME
                          AND W.EVENT_DATE <= X.EVENT_DATE
                          AND X.LOG_TYPE IN ('END', 'ERROR'))
       AND ((SYSDATE - EVENT_DATE) * 1440) > NVL((SELECT TO_NUMBER(JOB2.C_TIME)
                                                    FROM (SELECT SEGMENT1 AS PROC_NAME, ATTRIBUTE1 C_TIME
                                                            FROM SCM_ADM_LOOKUP_MASTER_DETAIL AMD
                                                           WHERE AMD.LOOKUP_TYPE = 'SCM_LONG_TEMP_JOB'
                                                             AND AMD.VALID_YN = 'Y') JOB2
                                                   WHERE JOB2.PROC_NAME = W.PROGRAM_NAME)
                                                , N_CHECK_TM)
       /* 2024-11-25 kimcd 작업 기준 시간으로 조회 조건 추가 */
     GROUP BY W.PROGRAM_NAME, W.LOG_TYPE;

    /* ------------------------------------------------------------------------------
       장기수행 체크 예외처리 (LOOKUP 등록건 예외처리) 추가 :: 2020.08.25 KSW - end
       ------------------------------------------------------------------------------
       CUR_LONGTM_LOG CURSOR FOR */
    NULL;

    /********************************************************************************
    * SMS 대상자 임시테이블만들기
    ********************************************************************************/
    NULL;

    V_RESULT := NULL;
    V_RESULT := V_RESULT || '        SELECT b.message_content ' || CHR(10);
    V_RESULT := V_RESULT || '              ,c.sms_phone ' || CHR(10);
    V_RESULT := V_RESULT || '              ,a.use_type_code ' || CHR(10);
    V_RESULT := V_RESULT || '              ,a.module_code ' || CHR(10);
    V_RESULT := V_RESULT || '              ,c.receiver_level ' || CHR(10);  /* 2024-11-25 kimcd 수신자 level 추가 */
    V_RESULT := V_RESULT || '          FROM SCM_ADM_RECIPIENT_LIST a ' || CHR(10);
    V_RESULT := V_RESULT || '         INNER JOIN SCM_ADM_RECIPIENT_MESSAGE b ' || CHR(10);
    V_RESULT := V_RESULT || '            ON a.CATEGORY_ID = b.CATEGORY_ID  ' || CHR(10);
    V_RESULT := V_RESULT || '         INNER JOIN SCM_ADM_RECIPIENT_SMS_ASSIGN c   ' || CHR(10);
    V_RESULT := V_RESULT || '            ON a.CATEGORY_ID = c.CATEGORY_ID ' || CHR(10);
    V_RESULT := V_RESULT || '         WHERE a.CATEGORY_ID =' || TO_CHAR(P_CATEGORY_ID) || CHR(10);
    V_RESULT := V_RESULT || '              AND a.VALID_YN = ''Y'' ' || CHR(10);

    EXECUTE IMMEDIATE 'INSERT /*+ NO_PARALLEL */ INTO GT_LCSS_TBLSMSSENDBATCH ' || V_RESULT;

    /********************************************************************************
    메인 처리시작
    ********************************************************************************/

    /* SP 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := NULL;
    D_EVENT_DATE  := SYSTIMESTAMP;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    OPEN CUR_LONGTM_LOG;
    FETCH CUR_LONGTM_LOG
        INTO V_PGM_NAME, V_PGM_LOG_TYPE, V_PGM_EVENT_TM, V_PGM_RUN_TIME, V_PGM_C_TIME;  /* 2024-11-25 kimcd 작업 경과 시간 추가; */

    IF CUR_LONGTM_LOG%NOTFOUND THEN
        N_LONGTM_FETCH_STS := -1;
    ELSE
        N_LONGTM_FETCH_STS := 0;
    END IF;  /* 이중 loop 를 사용하므로 장기실행 미완료 건에 대한 fetch status 를 보관한다. */

    N_PROC_CNT := 0;

    /* 장기수행 미완료 건을 Fetch 해서 순차처리한다. */
    V_LOG_TYPE    := 'TXN';
    N_LOG_COUNT   := SQL%ROWCOUNT;
    V_LOG_MESSAGE := 'Start Long time process';
    V_DESCRIPTION := 'sms category / check time(min) ... ' || ' / ' || TO_CHAR(P_CATEGORY_ID) || ' / ' || TO_CHAR(P_CHECK_TM);
    D_EVENT_DATE  := SYSTIMESTAMP;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    WHILE N_LONGTM_FETCH_STS = 0 LOOP

        /* select v_pgm_name, v_pgm_log_type, v_pgm_event_tm; */
        /* 현재 Fetch 된 미완료건을 SMS 대상자 모두에게 전송한다. */
        IF N_PROC_CNT = 0 THEN
            OPEN CUR_LM_SEND;
        END IF;

        IF N_PROC_CNT = 9 THEN
            CLOSE CUR_LM_SEND;
            OPEN CUR_LM_SEND;
            FETCH CUR_LM_SEND
                INTO V_MESSAGE_CONTENT, V_SMS_PHONE, V_USE_TYPE_CODE, V_MODULE_CODE, V_RECEIVER_LEVEL;  /* 2024-11-25 kimcd 수신자 level 추가 */
        ELSE
            FETCH CUR_LM_SEND
                INTO V_MESSAGE_CONTENT, V_SMS_PHONE, V_USE_TYPE_CODE, V_MODULE_CODE, V_RECEIVER_LEVEL;  /* 2024-11-25 kimcd 수신자 level 추가 */
        END IF;

        N_PROC_CNT := 1;

        WHILE CUR_LM_SEND%FOUND LOOP
            IF V_RECEIVER_LEVEL IS NULL OR V_RECEIVER_LEVEL = 0 OR V_RECEIVER_LEVEL = 1 OR (V_RECEIVER_LEVEL = 2 AND V_PGM_RUN_TIME > V_PGM_C_TIME * 2) OR
               (V_RECEIVER_LEVEL = 3 AND V_PGM_RUN_TIME > V_PGM_C_TIME * 3) THEN
                BEGIN
                    IF P_LONGTM_MSG IS NOT NULL THEN
                        V_MESSAGE_CONTENT := SUBSTR('[' || V_MODULE_CODE || ']' || P_LONGTM_MSG || ' ' || V_MESSAGE_CONTENT, 1, 79);
                    ELSE
                        V_MESSAGE_CONTENT := SUBSTR('[' || V_MODULE_CODE || ']PNM:' || V_PGM_NAME || ' ' || V_MESSAGE_CONTENT || ' RUN :' ||
                                                    TO_CHAR(V_PGM_RUN_TIME)
                                                   ,1
                                                   ,79);  /* 2024-11-25 kimcd 작업 경과 시간 추가 */
                    END IF;
                END;

                V_SMS_SEND_PHONE := NULL;
                V_SMS_SEND_PHONE := '01099999999';

                INSERT
                  INTO XIF_IFS_SMS_DATA_SN
                     ( IF_TYPE
                     , IF_ID
                     , IF_INS_DATE
                     , IF_FLAG
                     , TR_SENDSTAT
                     , TR_MSGTYPE
                     , TR_PHONE
                     , TR_CALLBACK
                     , TR_MSG )
                VALUES ( 'S'
                       , 'OFP0_OSMS_SMS'
                       , SYSDATE
                       , 'N'
                       , '0'
                       , '0'
                       , V_SMS_PHONE
                       , V_SMS_SEND_PHONE
                       , V_MESSAGE_CONTENT );

                /* SMS 발송 LOG 저장 */
                SCM_ADM_SAVE_MAIL_SEND_BATCH_LOG(V_USE_TYPE_CODE
                                                ,P_CATEGORY_ID
                                                ,V_SMS_PHONE
                                                ,V_MESSAGE_CONTENT
                                                ,''
                                                ,''
                                                ,''
                                                ,''
                                                ,''
                                                ,''
                                                ,''
                                                ,''
                                                ,''  /* p_send_pgm */
                                                ,V_SMS_PHONE);

                /* select v_use_type_code, p_category_id, v_sms_phone, v_message_content; */
            END IF;

            FETCH CUR_LM_SEND
                INTO V_MESSAGE_CONTENT, V_SMS_PHONE, V_USE_TYPE_CODE, V_MODULE_CODE, V_RECEIVER_LEVEL;  /* 2024-11-25 kimcd 수신자 level 추가 */

        END LOOP;

        N_PROC_CNT := 9;

        /* 다음 미완료 건을 Fetch 한다. */
        FETCH CUR_LONGTM_LOG
            INTO V_PGM_NAME, V_PGM_LOG_TYPE, V_PGM_EVENT_TM, V_PGM_RUN_TIME, V_PGM_C_TIME;  /* 2024-11-25 kimcd 작업 경과 시간 추가; */

        IF CUR_LONGTM_LOG%NOTFOUND THEN
            N_LONGTM_FETCH_STS := -1;
        ELSE
            N_LONGTM_FETCH_STS := 0;
        END IF;  /* 이중 loop 를 사용하므로 장기실행 미완료 건에 대한 fetch status 를 보관한다. */

    END LOOP;

    /* 장기수행 미완료건 커서해제 */
    CLOSE CUR_LONGTM_LOG;

    /* SMS 대상자 커서해제 */
    IF N_PROC_CNT > 0 THEN
        CLOSE CUR_LM_SEND;
    END IF;

    /* 임시 테이블 삭제 */
    NULL;
    /* SP 종료 log. */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := NULL;
    D_EVENT_DATE  := SYSTIMESTAMP;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    COMMIT;


    /* error catch... */
EXCEPTION
    WHEN OTHERS THEN
        /* cursor 를 해제한다. */
        IF CUR_LONGTM_LOG%ISOPEN THEN
            CLOSE CUR_LONGTM_LOG;
        END IF;

        IF CUR_LM_SEND%ISOPEN THEN
            CLOSE CUR_LM_SEND;
        END IF;

        ROLLBACK;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME
                            ,'ERROR'
                            ,0
                            ,SQLERRM
                            ,NULL
                            ,SYSDATE
                            ,P_IN_PARA_DATA  => V_IN_PARA_DATA
                            ,P_SQL_ERR_CODE  => SQLCODE
                            ,P_SQL_ERR_MSG   => SQLERRM
                            ,P_SQL_BACKTRACE => DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
        RAISE_APPLICATION_ERROR(-20001
                               ,'[' || V_PROGRAM_NAME || '] SQLCODE=' || SQLCODE || ' / SQLERRM=' || SQLERRM || ' / BACKTRACE=' ||
                                DBMS_UTILITY.FORMAT_ERROR_BACKTRACE || ' / PARAMS=' || V_IN_PARA_DATA);


END;

PROCEDURE PR_NERP_XLS_TOBE_CONVERTER
(
      P_ROLLIN      IN  VARCHAR2                  /* NVARCHAR(30)  : 1ST 2ND 3RD 4TH */
    , P_SYS_TYPE    IN  VARCHAR2 DEFAULT 'USAGE'
    , P_SYS_FLAG    IN  VARCHAR2 DEFAULT ''
    , P_SYS_GUBUN   IN  VARCHAR2 DEFAULT 'MERGE'
    , P_USER_ID     IN  VARCHAR2 DEFAULT 'AUTO'
    , P_OPTION      IN  VARCHAR2 DEFAULT 'N'
)
/* ===================================================================================================
 * Program ID   : PR_NERP_XLS_TOBE_CONVERTER
 * Author       : P.C.I
 * Create date  : 2024-06-13
 * Description  : XLS to DEV db conversion table - PR_NERP_XLS_TO_CONVERTER 참조수정(ZNERP_TOBE_CODE_INFO)
 *                EXEC PR_SCM_SYS_RFC_CALL_NERP 'ZCMCM_AS_TOBE_CODE_INFO'  ,'HQ00'
 *                EXEC PR_NERP_XLS_TOBE_CONVERTER @p_rollin='2ND',@p_sys_type='ALL'
 * Program History
 *---------------------------------------------------------------------------------------------------
 *   Date       In Charge      Description
 *---------------------------------------------------------------------------------------------------
 * 2025.04.08   김준규          SCP용 추가 work_site, work_site_desc, work_cost_center, ROLLIN 차수 재정의
 *                             본프로그램으로 1차(한국,WA) 작업되는 부분 운영 값으로 대체(1차데이터 비정상)
 * 2025.04.17   김준규          입력 변수로 ROLLIN 차수 입력받음(VENDOR_ID, END_CUSTOMER_ID는 이전차수 제외 하고 처리)
 * 2025.05.13   김준규          IF @p_sys_type='ALL'  backup 하고 truncate 하고 merge 한다
 *                             없어지는 CODE도 존재하여 기존 MERGE로만 작업시 사라진 코드를 그대로 사용하고 있는 문제 있음
 * 2025.05.23   김준규          QA서버에 테이블 전체 컬럼에 UK 만들어 놓음. 현재 중복 INSERT되는데 원인 파악필요.
 * 2025.05.25   김준규          1차 오펀시 백업데이터는 QA 및 운영에 통일 테이블 명(BACKUP_NERP_CONV_MASTER_PROD_250417)으로
 *                             동일하게 데이터 존재해서 프로그램 수정함(운영이관시 즉시 변경없이 사용가능)
 * 2025.07.10   김준규          2차 오펀시 백업데이터는 QA 및 운영에 통일 테이블 명(BACKUP_NERP_CONV_MASTER_PROD_250710)으로
 *                             동일하게 데이터 존재해서 프로그램 수정함(운영이관시 즉시 변경없이 사용가능)
 * 2025.09.11   김준규          DM용 CURRENCY RMB TO CNY 변경 추가, 기존 WAERS를 사용했으나 금번에 3RD에 DM한정으로 사용 별도 CODETYPE으로 만듦.
 * 2025.10.14   김준규          3차 오펀시 백업데이터는 QA 및 운영에 통일 테이블 명(BACKUP_NERP_CONV_MASTER_PROD_251010)으로
 *                             동일하게 데이터 존재해서 프로그램 수정함(운영이관시 즉시 변경없이 사용가능)
 * 2025.10.20   김준규          @P_ROLLIN의 차수 "4N5"는 여기서는 입력 하면 안됨,교체식 제외처리 값으로 X4N5X@ 추가
 * 2025.11.14   김준규          DM용 G670,G671 PLANT_ID,SCP_SITE_ID 강제 수작업 추가
 * 2025.11.17   김준규          4TH 백업하고 BACKUP_NERP_CONV_MASTER_4TH_251117을 5TH에 사용(NERP QA에서만 사용해야 됨,운영없음)
 * 2025.11.18   김준규          기존 운영에서 사용하고 있는 SCP_SITE_ID가 누락되지 않게 해달라는 요청 적용
 *                             운영환경일 경우 백업테이블명: @NewTableName 에서 SCP_SITE_ID 신규 값으로 설정되지 않은 것 INSERT 처리
 * 2025.12.11   김준규          4TH BACKUP_NERP_CONV_MASTER_PROD_251204을 5TH에 사용
 * 2025.12.17   김준규          기존 운영에서 사용하고 있는 SCP_SITE_ID가 누락되지 않게 할때, 차수를 '9TH' ATTRIBUTE5   9TH로 강제로 변경
 * 2026-07-23   ZIONEX         [PJ202650304]  NextSCM Migration
 * =================================================================================================== */
IS
    V_CREATED_BY            VARCHAR2(128 CHAR);

    /* 2025-05-13 김준규 백업/드롭 로직 변수 */
    V_BASE_TABLE_NAME       VARCHAR2(254 CHAR) := 'NERP_CONV_MASTER';   /* 기본 테이블 이름 */
    V_DATE_PART             VARCHAR2(8 CHAR);                            /* 오늘 날짜 (예: 20250513) */
    V_NEW_TABLE_NAME        VARCHAR2(254 CHAR);
    V_COUNTER               PLS_INTEGER := 1;
    V_SQL_TBL               VARCHAR2(4000 CHAR);
    V_DROP_DATE_THRESHOLD   VARCHAR2(8 CHAR);
    V_DROP_SQL              VARCHAR2(4000 CHAR);
    V_CNT                   PLS_INTEGER;

    V_DELETE_OPTION         VARCHAR2(1 CHAR) := 'N';
    V_MATCHING_OPTION       PLS_INTEGER := 0;

    V_WORK_COMPANY          PLS_INTEGER := 0;       /* BUKRS */
    V_WORK_PLANT            PLS_INTEGER := 0;       /* WERKS */
    V_WORK_STORAGE          PLS_INTEGER := 0;       /* LGORT */
    V_WORK_END_CUSTOMER     PLS_INTEGER := 0;       /* KUNNR */
    V_WORK_VENDOR           PLS_INTEGER := 0;       /* LIFNR */
    V_WORK_BIZ_PARTNER      PLS_INTEGER := 0;       /* PARTNER */
    V_WORK_BIZ_AREA         PLS_INTEGER := 0;       /* GSBER */
    V_WORK_MATERIAL_GROUP   PLS_INTEGER := 0;       /* MATKL */
    V_WORK_INDICATOR_GL     PLS_INTEGER := 0;       /* UMSKZ */
    V_WORK_PROFIT_CENTER    PLS_INTEGER := 0;       /* PRCTR */
    V_WORK_MOVEMENT_TYPE    PLS_INTEGER := 0;       /* BWART */
    V_WORK_DISTRIBUTE_CHANNEL PLS_INTEGER := 0;     /* VTWEG */
    V_WORK_SALES_GROUP      PLS_INTEGER := 0;       /* VKGRP */
    V_WORK_SALES_ORDER_TYPE PLS_INTEGER := 0;       /* AUART */
    V_WORK_INCOTERMS        PLS_INTEGER := 0;       /* INCO1(엑셀 별도) */
    V_WORK_ROUTES           PLS_INTEGER := 0;       /* ROUTE */
    V_WORK_DOCUMENT_TYPE    PLS_INTEGER := 0;       /* BLART */
    V_WORK_VAT_CODE         PLS_INTEGER := 0;       /* MWSKZ */
    V_WORK_SITE             PLS_INTEGER := 0;       /* 자체 제작 // PLANT+OPERATION_GROUP (EX. A010-A 등) */
    /* 2025.04.08 김준규 SCP용 추가 */
    V_WORK_SITE_DESC        PLS_INTEGER := 0;       /* 자체 제작 // PLANT+성격 (LGESMI Elec MI00,LGESMI Automotive Waranty MI00 등) */
    V_WORK_COST_CENTER      PLS_INTEGER := 0;       /* BKLAS */
