    V_ELEMENT1              VARCHAR2(10 CHAR) := '';
    V_ELEMENT2              VARCHAR2(10 CHAR) := '';
    V_ELEMENT3              VARCHAR2(10 CHAR) := '';
    V_ELEMENT4              VARCHAR2(10 CHAR) := '';

    V_SQL                   CLOB;
BEGIN
    /* 2025.04.17 김준규 롤인차수 추가 시작 */
    IF P_ROLLIN NOT IN ('1ST','2ND','3RD','4TH','5TH','X4N5X@') THEN   /* 교체식 제외처리 값으로 X4N5X@ 추가 */
