        /* TODO */

        RETURN;
    END IF;

    /* 2025-05-13 김준규 추가 시작 */
    /* backup 하고 truncate 하고 merge 한다 */
    IF P_SYS_TYPE = 'ALL' THEN
        V_DATE_PART := TO_CHAR(SYSDATE, 'YYYYMMDD');   /* 오늘 날짜 (예: 20250513) */

        /* 2개월 전 날짜 계산 */
        V_DROP_DATE_THRESHOLD := TO_CHAR(ADD_MONTHS(SYSDATE, -2), 'YYYYMMDD');

        /* 테이블이 존재하는지 확인하고, 존재하면 숫자를 증가시켜 새로운 테이블 이름 생성 */
        LOOP
            SELECT COUNT(*)
              INTO V_CNT
              FROM USER_TABLES
             WHERE TABLE_NAME = V_BASE_TABLE_NAME || '_' || V_DATE_PART || '_' || TO_CHAR(V_COUNTER);
            EXIT WHEN V_CNT = 0;
            V_COUNTER := V_COUNTER + 1;
        END LOOP;

        /* 최종 새로운 테이블 이름 설정 */
        V_NEW_TABLE_NAME := V_BASE_TABLE_NAME || '_' || V_DATE_PART || '_' || TO_CHAR(V_COUNTER);

        /* SELECT INTO 구문을 동적으로 생성(MSSQL SELECT * INTO → Oracle CREATE TABLE AS SELECT) */
        V_SQL_TBL := 'CREATE TABLE ' || V_NEW_TABLE_NAME || ' AS SELECT * FROM ' || V_BASE_TABLE_NAME;

        /* 동적 SQL 실행 */
        EXECUTE IMMEDIATE V_SQL_TBL;

        /* 데이터 삭제하고 작업처리 */
        /* ############################################################################## */
        EXECUTE IMMEDIATE 'TRUNCATE TABLE NERP_CONV_MASTER';
        /* ############################################################################## */

        /* ---------------------------------------------------------------------------------- */
        /* 2개월 이전 테이블 삭제 로직 */
        /* ---------------------------------------------------------------------------------- */
        FOR REC IN (SELECT TABLE_NAME
                      FROM USER_TABLES
                     WHERE REGEXP_LIKE(TABLE_NAME, '^' || V_BASE_TABLE_NAME || '_[0-9]{8}_')   /* 날짜 패턴 포함 */
                       AND SUBSTR(TABLE_NAME, LENGTH(V_BASE_TABLE_NAME) + 2, 8) < V_DROP_DATE_THRESHOLD)
        LOOP
            V_DROP_SQL := 'DROP TABLE ' || REC.TABLE_NAME;
            BEGIN
                EXECUTE IMMEDIATE V_DROP_SQL;
                DBMS_OUTPUT.PUT_LINE('테이블 삭제됨: ' || REC.TABLE_NAME);
            EXCEPTION
                WHEN OTHERS THEN
                    DBMS_OUTPUT.PUT_LINE('테이블 삭제 실패: ' || REC.TABLE_NAME);
                    DBMS_OUTPUT.PUT_LINE(SQLERRM);
            END;
        END LOOP;

        /* 2025-05-13 김준규 추가 종료 */
    END IF;

    IF P_OPTION LIKE 'C%' THEN
        V_DELETE_OPTION := 'Y';
    END IF;

    IF P_OPTION LIKE '%M' THEN
        V_MATCHING_OPTION := 1;
    END IF;

    /* DELETE EXISTING DATA */
    IF V_DELETE_OPTION = 'Y' THEN
        DELETE FROM NERP_CONV_MASTER
         WHERE 1=1;
    END IF;

    IF P_SYS_TYPE = 'ALL' THEN
        V_WORK_COMPANY := 1;
        V_WORK_PLANT := 1;
