        V_WORK_SITE := 1;
        /* 2025.04.08 김준규 SCP용 추가 시작 */
        V_WORK_SITE_DESC := 1;
        V_WORK_COST_CENTER := 1;
        /* 2025.04.08 김준규 SCP용 추가 시작 */
        V_WORK_PURCHASE_GROUP := 1;
    ELSIF P_SYS_TYPE = 'COMPANY' OR P_SYS_TYPE = 'COMPANY_ID' OR P_SYS_TYPE = 'BUKRS' THEN
        V_WORK_COMPANY := 1;
    ELSIF P_SYS_TYPE = 'PLANT' OR P_SYS_TYPE = 'PLANT_ID' OR P_SYS_TYPE = 'WERKS_D' THEN
