    ELSIF P_SYS_TYPE = 'BIZ' OR P_SYS_TYPE = 'BIZ_PARTNER' OR P_SYS_TYPE = 'PARTNER' THEN
        V_WORK_BIZ_PARTNER := 1;
    ELSIF P_SYS_TYPE = 'BIZ_AREA' OR P_SYS_TYPE = 'BUSINESS_AREA' OR P_SYS_TYPE = 'GSBER' THEN
        V_WORK_BIZ_AREA := 1;
    ELSIF P_SYS_TYPE = 'MATERIAL' OR P_SYS_TYPE = 'MATERIAL_GROUP' OR P_SYS_TYPE = 'MATKL' THEN
        V_WORK_MATERIAL_GROUP := 1;
    ELSIF P_SYS_TYPE = 'INDICATOR' OR P_SYS_TYPE = 'INDICATOR_GL' OR P_SYS_TYPE = 'UMSKZ' THEN
        V_WORK_INDICATOR_GL := 1;
    ELSIF P_SYS_TYPE = 'PROFIT' OR P_SYS_TYPE = 'PROFIT_CENTER' OR P_SYS_TYPE = 'PRCTR' THEN
        V_WORK_PROFIT_CENTER := 1;
    ELSIF P_SYS_TYPE = 'MOVEMENT' OR P_SYS_TYPE = 'MOVEMENT_TYPE' OR P_SYS_TYPE = 'BWART' THEN
