        END IF;
        IF V_WORK_ROUTES = 1 THEN
            DELETE FROM NERP_CONV_MASTER
             WHERE 1=1
               AND CODETYPE = 'ROUTE_ID';
        END IF;
        IF V_WORK_DOCUMENT_TYPE = 1 THEN
            DELETE FROM NERP_CONV_MASTER
             WHERE 1=1
               AND CODETYPE = 'DOCUMENT_TYPE_ID';
        END IF;
        IF V_WORK_VAT_CODE = 1 THEN
            DELETE FROM NERP_CONV_MASTER
             WHERE 1=1
               AND CODETYPE = 'VAT_CODE_ID';
        END IF;
        /* 2025.04.08 김준규 SCP용 추가 시작 */
        IF V_WORK_SITE = 1 THEN
            DELETE FROM NERP_CONV_MASTER
             WHERE 1=1
               AND CODETYPE = 'SCP_SITE_ID';
        END IF;
        IF V_WORK_SITE = 1 THEN
            DELETE FROM NERP_CONV_MASTER
             WHERE 1=1
               AND CODETYPE = 'SCP_SITE_DESCRIPTION';
        END IF;
        IF V_WORK_COST_CENTER = 1 THEN
            DELETE FROM NERP_CONV_MASTER
             WHERE 1=1
               AND CODETYPE = 'BKLAS';
        END IF;
        /* 2025.04.08 김준규 SCP용 추가 종료 */
        IF V_WORK_PURCHASE_GROUP = 1 THEN
            DELETE FROM NERP_CONV_MASTER
             WHERE 1=1
               AND CODETYPE = 'PURCHASE_GROUP_ID';
        END IF;
    ELSIF P_SYS_TYPE = 'COMPANY' OR P_SYS_TYPE = 'COMPANY_ID' OR P_SYS_TYPE = 'BUKRS' THEN
        V_WORK_COMPANY := 1;
    ELSIF P_SYS_TYPE = 'PLANT' OR P_SYS_TYPE = 'PLANT_ID' OR P_SYS_TYPE = 'WERKS' THEN
        V_WORK_PLANT := 1;
    ELSIF P_SYS_TYPE = 'STORAGE' OR P_SYS_TYPE = 'STORAGE_ID' OR P_SYS_TYPE = 'LGORT' THEN
