    ELSIF P_SYS_TYPE = 'CUSTOMER' OR P_SYS_TYPE = 'END_CUSTOMER' OR P_SYS_TYPE = 'KUNNR' THEN
        V_WORK_END_CUSTOMER := 1;
    ELSIF P_SYS_TYPE = 'VENDOR' OR P_SYS_TYPE = 'VENDOR_ID' OR P_SYS_TYPE = 'LIFNR' THEN
        V_WORK_VENDOR := 1;
    ELSIF P_SYS_TYPE = 'BIZ' OR P_SYS_TYPE = 'BIZ_PARTNER' OR P_SYS_TYPE = 'PARTNER' THEN
        V_WORK_BIZ_PARTNER := 1;
    ELSIF P_SYS_TYPE = 'BIZ_AREA' OR P_SYS_TYPE = 'BUSINESS_AREA' OR P_SYS_TYPE = 'GSBER' THEN
        V_WORK_BIZ_AREA := 1;
    ELSIF P_SYS_TYPE = 'MATERIAL' OR P_SYS_TYPE = 'MATERIAL_GROUP' OR P_SYS_TYPE = 'MATKL' THEN
