           ,DESC2
           ,DESC3
           ,DESC4
           ,COMMENT1
           ,COMMENT2
           ,COMMENT3
           ,COMMENT4
           ,COMMENT5
           ,COMMENT6
           ,COMMENT7
           ,ACTIVE_FLAG
           ,ATTRIBUTE1
           ,ATTRIBUTE2
           ,ATTRIBUTE3
           ,ATTRIBUTE4
           ,ATTRIBUTE5
           ,INSERT_ID
           ,INSERT_DATE
           ,UPDATE_ID
           ,UPDATE_DATE
