           ,X.NEW_VALUE1
           ,X.NEW_VALUE2
           ,X.NEW_VALUE3
           ,X.NEW_VALUE4
           ,X.ELEMENT1
           ,X.ELEMENT2
           ,X.ELEMENT3
           ,X.ELEMENT4
           /* ,DESC1=(CASE WHEN ISNULL(NRV.DESC1,'') = '' THEN MCV.DESC1 ELSE NRV.DESC1 END) */
           ,CASE WHEN NRV1.DESC1 IS NOT NULL THEN NRV1.DESC1
                 WHEN NRV2.DESC1 IS NOT NULL THEN NRV2.DESC1
                 WHEN MCV1.DESC1 IS NOT NULL THEN MCV1.DESC1
                 WHEN MCV2.DESC1 IS NOT NULL THEN MCV2.DESC1 ELSE X.DESC1 END AS DESC1
           ,X.DESC2
           ,X.DESC3
           ,X.DESC4
           ,X.COMMENT1
           ,X.COMMENT2
           ,X.COMMENT3
           ,X.COMMENT4
           ,X.COMMENT5
           ,X.COMMENT6
           ,X.COMMENT7
           ,X.ACTIVE_FLAG
           ,X.ATTRIBUTE1
           ,X.ATTRIBUTE2
           ,X.ATTRIBUTE3
           ,X.ATTRIBUTE4
           ,X.ATTRIBUTE5
