                   ,NCM.COMMENT4
                   ,NCM.COMMENT5
                   ,NCM.COMMENT6
                   ,NCM.COMMENT7
                   ,NCM.ACTIVE_FLAG
                   ,NCM.ATTRIBUTE1
                   ,NCM.ATTRIBUTE2
                   ,NCM.ATTRIBUTE3
                   ,NCM.ATTRIBUTE4
                   ,NCM.ATTRIBUTE5
                   ,NCM.INSERT_ID
                   ,NCM.INSERT_DATE
                   ,NCM.UPDATE_ID
                   ,NCM.UPDATE_DATE
              FROM NERP_CONV_MASTER NCM
              JOIN (SELECT LEVEL AS "NUMBER" FROM DUAL CONNECT BY LEVEL <= 3) CPT ON 1=1
             WHERE NCM.ATTRIBUTE5 = '5TH'
