            /* SCP_SITE_ID 회사 스타일 값 수작업 강제 추가 */
            SELECT  NCM.CODETYPE
                   ,'G671' AS OLD_VALUE1
                   ,NCM.OLD_VALUE2
                   ,NCM.OLD_VALUE3
                   ,NCM.OLD_VALUE4
                   ,'GM00' AS NEW_VALUE1
                   ,NCM.NEW_VALUE2
                   ,NCM.NEW_VALUE3
                   ,NCM.NEW_VALUE4
                   ,NCM.ELEMENT1
                   ,NCM.ELEMENT2
                   ,NCM.ELEMENT3
                   ,NCM.ELEMENT4
                   ,NCM.DESC1
                   ,NCM.DESC2
                   ,NCM.DESC3
                   ,NCM.DESC4
                   ,'수작업강제입력 BASE ON G690' AS COMMENT1
                   ,NCM.COMMENT2
                   ,NCM.COMMENT3
                   ,NCM.COMMENT4
                   ,NCM.COMMENT5
                   ,NCM.COMMENT6
                   ,NCM.COMMENT7
                   ,NCM.ACTIVE_FLAG
                   ,NCM.ATTRIBUTE1
                   ,NCM.ATTRIBUTE2
                   ,NCM.ATTRIBUTE3
                   ,NCM.ATTRIBUTE4
                   ,NCM.ATTRIBUTE5
                   ,NCM.INSERT_ID
                   ,NCM.INSERT_DATE
                   ,NCM.UPDATE_ID
                   ,NCM.UPDATE_DATE
              FROM NERP_CONV_MASTER NCM
             WHERE NCM.ATTRIBUTE5 = '5TH'
               AND NCM.CODETYPE = 'SCP_SITE_ID'
               AND NCM.OLD_VALUE1 = 'G690'
