            /* PLANT_ID 공장 스타일 수작업 강제 추가 */
            /* PLANT_ID 회사 스티일 없음 */
            SELECT  NCM.CODETYPE
                   ,CASE WHEN CPT."NUMBER" = 1 THEN 'G670-A' WHEN CPT."NUMBER" = 2 THEN 'G671-A' WHEN CPT."NUMBER" = 3 THEN 'G673-A' WHEN CPT."NUMBER" = 4 THEN 'G690-A' WHEN CPT."NUMBER" = 5 THEN 'G690-P' END AS OLD_VALUE1
