                   ,NCM.NEW_VALUE2
                   ,NCM.NEW_VALUE3
                   ,NCM.NEW_VALUE4
                   ,NCM.ELEMENT1
                   ,NCM.ELEMENT2
                   ,NCM.ELEMENT3
                   ,NCM.ELEMENT4
                   ,NCM.DESC1
                   ,NCM.DESC2
                   ,NCM.DESC3
                   ,NCM.DESC4
                   ,'수작업강제입력 BASE ON G671' AS COMMENT1
                   ,NCM.COMMENT2
                   ,NCM.COMMENT3
                   ,NCM.COMMENT4
                   ,NCM.COMMENT5
                   ,NCM.COMMENT6
                   ,NCM.COMMENT7
                   ,NCM.ACTIVE_FLAG
                   ,NCM.ATTRIBUTE1
                   ,NCM.ATTRIBUTE2
                   ,NCM.ATTRIBUTE3
                   ,NCM.ATTRIBUTE4
                   ,NCM.ATTRIBUTE5
                   ,NCM.INSERT_ID
                   ,NCM.INSERT_DATE
                   ,NCM.UPDATE_ID
                   ,NCM.UPDATE_DATE
              FROM NERP_CONV_MASTER NCM
              JOIN (SELECT LEVEL AS "NUMBER" FROM DUAL CONNECT BY LEVEL <= 5) CPT ON 1=1
             WHERE NCM.ATTRIBUTE5 = '5TH'
               AND NCM.CODETYPE = 'PLANT_ID'
               AND OLD_VALUE1 = 'G671'
          ) X
      , NERP_CONV_OLD_NEW_REF_V  NRV1
      , NERP_CONV_OLD_NEW_REF_V  NRV2
      , NERP_CONV_MASTER_CFM_V   MCV1
      , NERP_CONV_MASTER_CFM_V   MCV2
 WHERE NRV1.ATTRIBUTE5(+) = '5TH'
   AND NRV1.NEW_VALUE1(+) = X.NEW_VALUE1
   AND NRV1.CODETYPE(+)   = 'PLANT_ID'
   AND NRV2.ATTRIBUTE5(+) = '5TH'
   AND NRV2.NEW_VALUE1(+) = X.NEW_VALUE1
   AND NRV2.CODETYPE(+)   = 'SCP_SITE_ID'
   AND MCV1.ATTRIBUTE5(+) = '5TH'
   AND MCV1.OLD_VALUE1(+) = X.OLD_VALUE1
   AND MCV1.CODETYPE(+)   = 'PLANT_ID'
   AND MCV2.ATTRIBUTE5(+) = '5TH'
   AND MCV2.OLD_VALUE1(+) = X.OLD_VALUE1
   AND MCV2.CODETYPE(+)   = 'SCP_SITE_ID';

        /* 아래는 원본 MSSQL에서 위 INSERT 뒤에 이어지던 독립 SELECT(결과셋 미리보기)이다.
           다중행 SELECT 를 허용하지 않는다(OUT 커서 신설은 시그니처 발명). INSERT 데이터 */
        /*
        SELECT
           --,NRV.*
           --,DESC1=(CASE WHEN ISNULL(NRV.DESC1,'') = '' THEN MCV.DESC1 ELSE NRV.DESC1 END)
           --,DESC1=(CASE WHEN ISNULL(NRV.DESC1,'') = '' THEN MCV.DESC1 ELSE NRV.DESC1 END)
           ,DESC1=(CASE WHEN ISNULL(NRV1.DESC1,'') <> '' THEN NRV1.DESC1
        FROM (
            --SCP_SITE_ID 공장 스타일 값 수작업 강제 추가
            SELECT  NCM.CODETYPE
                   ,CASE WHEN CPT.number = 1 THEN 'G670-A' WHEN CPT.number = 2 THEN 'G690-A' WHEN CPT.number = 3 THEN 'G690-P' END AS OLD_VALUE1
                   ,CASE WHEN CPT.number = 1 THEN 'GM00-A' WHEN CPT.number = 2 THEN 'EG00-A'  WHEN CPT.number = 3 THEN 'EG00-P' END AS NEW_VALUE1
                   ,N'수작업강제입력 BASE ON G671-A' AS COMMENT1
            FROM   NERP_CONV_MASTER NCM WITH(NOLOCK)
            JOIN   (SELECT number FROM master.dbo.spt_values WHERE type = 'P' AND number BETWEEN 1 AND 3) CPT ON 1=1
            AND    NCM.CODETYPE = 'SCP_SITE_ID'
            AND    OLD_VALUE1 = 'G671-A'
            --SCP_SITE_ID 회사 스타일 값 수작업 강제 추가
            SELECT  NCM.CODETYPE
                   ,'G671' AS OLD_VALUE1
                   ,'GM00' AS NEW_VALUE1
                   ,N'수작업강제입력 BASE ON G690' AS COMMENT1
            FROM   NERP_CONV_MASTER NCM WITH(NOLOCK)
            AND    NCM.CODETYPE = 'SCP_SITE_ID'
            --PLANT_ID 공장 스타일 수작업 강제 추가
            --PLANT_ID 회사 스티일 없음
            SELECT  NCM.CODETYPE
                   ,CASE WHEN CPT.number = 1 THEN 'G670-A' WHEN CPT.number = 2 THEN 'G671-A' WHEN CPT.number = 3 THEN 'G673-A' WHEN CPT.number = 4 THEN 'G690-A' WHEN CPT.number = 5 THEN 'G690-P' END AS OLD_VALUE1
                   ,CASE WHEN CPT.number = 1 THEN 'GM00-A' WHEN CPT.number = 2 THEN 'GM00-A' WHEN CPT.number = 3 THEN 'GM01-A' WHEN CPT.number = 4 THEN 'EG00-A' WHEN CPT.number = 5 THEN 'EG00-P' END AS NEW_VALUE1
                   ,N'수작업강제입력 BASE ON G671' AS COMMENT1
            FROM   NERP_CONV_MASTER NCM WITH(NOLOCK)
            JOIN   (SELECT number FROM master.dbo.spt_values WHERE type = 'P' AND number BETWEEN 1 AND 5) CPT ON 1=1
            AND    NCM.CODETYPE = 'PLANT_ID'
            AND    OLD_VALUE1 = 'G671'
        ) X
        LEFT JOIN NERP_CONV_OLD_NEW_REF_V NRV1 WITH(NOLOCK)
            ON NRV1.ATTRIBUTE5='5TH' AND NRV1.NEW_VALUE1 = X.NEW_VALUE1 AND NRV1.CODETYPE = 'PLANT_ID'
        LEFT JOIN NERP_CONV_OLD_NEW_REF_V NRV2 WITH(NOLOCK)
            ON NRV2.ATTRIBUTE5='5TH' AND NRV2.NEW_VALUE1 = X.NEW_VALUE1 AND NRV2.CODETYPE = 'SCP_SITE_ID'
        LEFT JOIN NERP_CONV_MASTER_CFM_V MCV1 WITH(NOLOCK)
            ON MCV1.ATTRIBUTE5='5TH' AND MCV1.OLD_VALUE1 = X.OLD_VALUE1 AND MCV1.CODETYPE = 'PLANT_ID'
        LEFT JOIN NERP_CONV_MASTER_CFM_V MCV2 WITH(NOLOCK)
            ON MCV2.ATTRIBUTE5='5TH' AND MCV2.OLD_VALUE1 = X.OLD_VALUE1 AND MCV2.CODETYPE = 'SCP_SITE_ID'
        WHERE 1=1
        AND NOT EXISTS (SELECT 1
                        FROM   NERP_CONV_MASTER NCM
                        )
        */
    END IF;
    /* 2025.11.14 김준규 DM용 G670,G671 PLANT_ID,SCP_SITE_ID 강제 수작업 추가 종료 */

    /* 2025.11.18 김준규 기존 운영에서 사용하고 있는 SCP_SITE_ID가 누락되지 않게 해달라는 요청 적용 */
    IF P_SYS_TYPE = 'ALL' THEN

        /* 엘지씨이 에스씨엠피알오디 : 운영 -- 뒤가 7자리 */
        IF SYS_CONTEXT('USERENV', 'DB_NAME') = 'LGCE_' || FN_GET_NERP_DECODE_BY_INDEXES('ASDDCMXPFFRCOYD', '2,5,6,8,11,13,15') THEN

            /* 프로그램 시작시 BACKUP 해 놓은 테이블을 사용한다. */
            /* 테이블 명은 상단에 V_NEW_TABLE_NAME로 기록 되어 있다. */

            V_SQL := 'BEGIN';
            V_SQL := V_SQL || ' INSERT INTO NERP_CONV_MASTER (';
            V_SQL := V_SQL || ' CODETYPE ,OLD_VALUE1 ,OLD_VALUE2 ,OLD_VALUE3 ,OLD_VALUE4';
            V_SQL := V_SQL || ' ,NEW_VALUE1 ,NEW_VALUE2 ,NEW_VALUE3 ,NEW_VALUE4';
            V_SQL := V_SQL || ' ,ELEMENT1 ,ELEMENT2 ,ELEMENT3 ,ELEMENT4';
            V_SQL := V_SQL || ' ,DESC1 ,DESC2 ,DESC3 ,DESC4';
            V_SQL := V_SQL || ' ,COMMENT1 ,COMMENT2 ,COMMENT3 ,COMMENT4 ,COMMENT5 ,COMMENT6 ,COMMENT7';
            V_SQL := V_SQL || ' ,ACTIVE_FLAG';
            V_SQL := V_SQL || ' ,ATTRIBUTE1 ,ATTRIBUTE2 ,ATTRIBUTE3 ,ATTRIBUTE4 ,ATTRIBUTE5';
            V_SQL := V_SQL || ' ,INSERT_ID ,INSERT_DATE ,UPDATE_ID ,UPDATE_DATE';
            V_SQL := V_SQL || ' )';
            V_SQL := V_SQL || ' SELECT CODETYPE ,OLD_VALUE1 ,OLD_VALUE2 ,OLD_VALUE3 ,OLD_VALUE4';
            V_SQL := V_SQL || ' ,NEW_VALUE1 ,NEW_VALUE2 ,NEW_VALUE3 ,NEW_VALUE4';
            V_SQL := V_SQL || ' ,ELEMENT1 ,ELEMENT2 ,ELEMENT3 ,ELEMENT4';
            V_SQL := V_SQL || ' ,DESC1 ,DESC2 ,DESC3 ,DESC4';
            V_SQL := V_SQL || ' ,COMMENT1 ,COMMENT2 ,COMMENT3 ,COMMENT4 ,COMMENT5 ,COMMENT6 ,COMMENT7';
            V_SQL := V_SQL || ' ,ACTIVE_FLAG';
            V_SQL := V_SQL || ' ,ATTRIBUTE1 ,ATTRIBUTE2 ,ATTRIBUTE3';
            V_SQL := V_SQL || ' ,''LOST'' ATTRIBUTE4';
            V_SQL := V_SQL || ' ,''9TH'' ATTRIBUTE5';   /* 9TH로 강제로 변경 */
            V_SQL := V_SQL || ' ,INSERT_ID ,INSERT_DATE ,UPDATE_ID ,UPDATE_DATE';
            V_SQL := V_SQL || ' FROM ' || V_NEW_TABLE_NAME || ' BNCM';
            V_SQL := V_SQL || ' WHERE 1=1';
            V_SQL := V_SQL || ' AND   BNCM.CODETYPE IN ( ''SCP_SITE_ID'',''PLANT_ID'' )';
            V_SQL := V_SQL || ' AND   NOT EXISTS (SELECT 1';
            V_SQL := V_SQL || ' FROM   NERP_CONV_MASTER NCM';
            V_SQL := V_SQL || ' WHERE  NCM.CODETYPE IN ( ''SCP_SITE_ID'',''PLANT_ID'' )';
            V_SQL := V_SQL || ' AND    NCM.OLD_VALUE1 = BNCM.OLD_VALUE1';
            V_SQL := V_SQL || ' );';
            V_SQL := V_SQL || ' END;';
        END IF;

        EXECUTE IMMEDIATE V_SQL;
    END IF;

END PR_NERP_XLS_TOBE_CONVERTER;

