--            UPDATE TB_FX_USERGROUPINFO UG
--               SET UG.USEYN          = 'N'
--                 , UG.UPDATEUSERID   = 'scm_batch'
--                 , UG.UPDATEDATETIME = SYSDATE
--             WHERE UG.USERID = R_CHG.USER_ID
--               AND UG.GROUPID = R_GD.GROUP_ID
--               AND UG.USEYN   = 'Y'
--               AND NOT EXISTS ( SELECT 1
--                                  FROM TB_FX_USERGROUPAUTHEXTENTION
--                                 WHERE USERID = UG.USERID
--                                   AND GROUPID = UG.GROUPID );
            DELETE FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M
             WHERE USER_ID    = R_CHG.USER_ID
               AND USER_GR_ID = R_GD.GROUP_ID
               AND UNIT_ID    = R_GD.DIVISION_ID;

            UPDATE SCM_ADM_USER_GR_MPG_M UG
               SET UG.USE_YN           = 'N'
                 , UG.LAST_UPDATED_BY  = 'scm_batch'
                 , UG.LAST_UPDATE_DATE = SYSDATE
             WHERE UG.USER_ID    = R_CHG.USER_ID
               AND UG.USER_GR_ID = R_GD.GROUP_ID
               AND UG.USE_YN     = 'Y'
               AND NOT EXISTS ( SELECT 1
                                  FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M
                                 WHERE USER_ID    = UG.USER_ID
                                   AND USER_GR_ID = UG.USER_GR_ID );
            /* 2026.09.30 AJS 수정 (END) */

  /* 기존 SCM 권한요청을 REJECT 처리 */
            UPDATE SCM_MST_AUTH_REQUEST
               SET APPROVAL_RESULT  = 'REJECT'
                 , REJECT_REASON    = 'DEPT_CHANGED_AUTH_DELETE'
                 , LAST_UPDATED_BY  = 'scm_batch'
                 , LAST_UPDATE_DATE = SYSDATE
             WHERE USER_ID     = R_CHG.USER_ID
               AND GROUP_ID    = R_GD.GROUP_ID
               AND DIVISION_ID = R_GD.DIVISION_ID;

            IF R_GD.GROUP_ID = 'FP Planner' THEN
  /* FP 권한삭제 (UPDATE...FROM JOIN → EXISTS) */
                UPDATE TH_UIS_USER_INSTANCE_RELATE_SN UIR
                   SET UIR.USE_AT_FLAG = 'N'
                     , UIR.UPDATE_ID   = 'scm_batch'
                     , UIR.UPDATE_DTTM = SYSDATE
                 WHERE UIR.USER_ID    = R_CHG.USER_ID
                   AND UIR.SAVE_FLAG  = (CASE WHEN R_GD.GROUP_ID = 'FP Planner' THEN 'Y' ELSE 'N' END)
                   AND UIR.USE_AT_FLAG = 'Y'
                   AND EXISTS ( SELECT 1
                                  FROM TH_UIS_ROLE_INSTANCE_SN RI
                                 WHERE RI.ROLE_ID = UIR.ROLE_ID
                                   AND EXISTS ( SELECT 1
                                                  FROM TH_UIS_ROLE_INSTANCE_RELATE_SN RIR
                                                 WHERE RIR.ROLE_ID     = RI.ROLE_ID
                                                   AND RIR.DIVISION_ID = R_GD.DIVISION_ID ) );

  /* 기존 FP 권한요청을 REJECT 처리 */
                UPDATE FP_AUTH_REQUEST_INFO_M_SN
                   SET APPROVAL_FLAG = 'N'
                     , DESCRIPTION   = 'DEPT_CHANGED_AUTH_DELETE'
                     , APPROVAL_ID   = 'scm_batch'
                     , APPROVAL_TIME = SYSDATE
                 WHERE USER_ID           = R_CHG.USER_ID
                   AND DIVISION_ID       = R_GD.DIVISION_ID
                   AND MENU_AUTHORITY_ID = (CASE WHEN R_GD.GROUP_ID = 'FP Planner' THEN 'PLANNER' ELSE 'VIEWER' END)
                   AND APPROVAL_FLAG     = 'Y';
            END IF;
        END LOOP;
    END LOOP;

    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
EXCEPTION
    WHEN OTHERS THEN
        V_ERRMSG := SQLERRM;
        V_DESCRIPTION := V_PROGRAM_NAME || 'ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
        INSERT INTO SCM_SYS_LOG_BATCH
             ( PROGRAM_NAME, LOG_TYPE, LOG_COUNT, LOG_MESSAGE, DESCRIPTION
             , EVENT_DATE, CREATION_DATE, CREATED_BY, LAST_UPDATE_DATE, LAST_UPDATED_BY )
        VALUES
             ( V_PROGRAM_NAME, 'ERROR', NULL, SUBSTR(V_ERRMSG, 1, 1000), SUBSTR(V_DESCRIPTION, 1, 500)
             , SYSDATE, SYSDATE, V_PROGRAM_NAME, SYSDATE, V_PROGRAM_NAME );
        COMMIT;
END;

PROCEDURE PR_SCM_ADM_DEPT_CHANGED_MAIL
/*
 * Program ID   : PR_SCM_ADM_DEPT_CHANGED_MAIL
 * Description  : 부서변경으로 인한 권한삭제 메일 전송
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2023.02.20   FP Pjt.        [E20230216-000381]권한 보유자의 소속변경(부서이동)시 권한삭제 예정 안내 메일 전송(유예기간 15일)
 * 2023.03.07   FP Pjt.        메일 제목에 영문 추가
 * 2026.07.06   ZIONEX         [PJ202650304]  NextSCM Migration
 */
AS
    V_USER_ID           VARCHAR2(30 CHAR);    /* 사용자ID */
    V_USER_NAME         VARCHAR2(150 CHAR);   /* 사용자명 */
    V_REMAIN_DAY        VARCHAR2(30 CHAR);    /* 권한회수까지 남은 일수 */
    V_MAIL_RECEIVER     VARCHAR2(60 CHAR);
    V_MAIL_SUBJECT      VARCHAR2(400 CHAR);
    V_MAIL_BODY         VARCHAR2(32767 CHAR);
    V_MAIL_SEND_CNT     PLS_INTEGER := 1;     /* 메일 전송 카운트 */

    V_BODY_TEXT1        VARCHAR2(4000 CHAR);
    V_BODY_TEXT2        VARCHAR2(4000 CHAR);
    V_BODY_TEXT3        VARCHAR2(4000 CHAR);
    V_BODY_TEXT4        VARCHAR2(4000 CHAR);
    V_TABLE_COL         VARCHAR2(4000 CHAR);
    V_TABLE_ROW         VARCHAR2(32767 CHAR);
    V_TABLE_BODY        VARCHAR2(32767 CHAR);

    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME      VARCHAR2(150 CHAR) := 'PR_SCM_ADM_DEPT_CHANGED_MAIL';
    V_LOG_TYPE          VARCHAR2(30 CHAR);    /* START/END/ERROR/... */
    N_LOG_COUNT         NUMBER := 0;
    V_LOG_MESSAGE       VARCHAR2(1000 CHAR);
    V_DESCRIPTION       VARCHAR2(500 CHAR);
    D_EVENT_DATE        DATE;

    V_INX               PLS_INTEGER := 0;
    V_MAX_NUM           PLS_INTEGER := 0;

    V_T_GROUP_ID        VARCHAR2(20 CHAR);
    V_T_DIVISION_ID     VARCHAR2(30 CHAR);
    V_T_APPROVAL_RESULT VARCHAR2(10 CHAR);
    V_T_APPROVAL_ID     VARCHAR2(150 CHAR);
    V_T_APPROVAL_NAME   VARCHAR2(150 CHAR);
    V_T_APPROVED_DATE   VARCHAR2(150 CHAR);

    /* 원본 @TAB 테이블변수 → 공유 GTT GT_SADCM_TAB (ROWNUM 예약어 → ROW_NO). DDL = output/gtt/GT_SADCM_TAB.sql */
BEGIN


    /* 메일 내용 설정 */
    /* [2026-10-07] 비운영에서는 제목에 'DEV Oracle 개발서버 ' 를 붙인다 (사용자 결정).
     * 원본 MSSQL 은 SELECT @v_profile_name = IIF(db_name()='LGCE_SCMPROD','GSCM_MAIL_PROD','GSCM_MAIL_TEST')
     * 로 **운영/비운영을 메일 프로필로 구분**했는데, Oracle PKG_SEND_MAIL 은 프로필 개념이 없고
     * C_SMTP_HOST 단일 호스트라 그 구분이 사라졌다. 제목 표시로 그 목적을 대체한다.
     * 발송 동작은 원본 그대로(비운영에도 발송) — 행 10·17 과 같은 판정식이다. */
    IF SYS_CONTEXT('USERENV', 'DB_NAME') NOT LIKE 'OCGSCMP%' THEN
        V_MAIL_SUBJECT := 'DEV Oracle 개발서버 '||'부서변경으로 인한 GSCM 시스템 권한 삭제 안내(Guidance on the deletion of GSCM system authority due to department changes)';
    ELSE
        V_MAIL_SUBJECT := '부서변경으로 인한 GSCM 시스템 권한 삭제 안내(Guidance on the deletion of GSCM system authority due to department changes)';
    END IF;


    BEGIN
        /* 시작 LOG */
        V_LOG_TYPE    := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);


        FOR CUR_CHANGED IN (SELECT DISTINCT V.USER_ID
                                 , V.USER_NAME
                                 , V.REMAIN_DAYS
                              FROM SCM_ADM_DEPT_CHANGED_V V
                             WHERE 1 = 1
                               AND V.ELAPSED_DAYS IN (0, 1, 5, 10))
        LOOP
            V_USER_ID    := CUR_CHANGED.USER_ID;
            V_USER_NAME  := CUR_CHANGED.USER_NAME;
            V_REMAIN_DAY := CUR_CHANGED.REMAIN_DAYS;


            DELETE
              FROM GT_SADCM_TAB;

            INSERT
              INTO GT_SADCM_TAB
                 ( ROW_NO
                 , GROUP_ID
                 , DIVISION_ID
                 , APPROVAL_RESULT
                 , APPROVAL_ID
                 , APPROVAL_NAME
                 , APPROVED_DATE )
            SELECT ROW_NUMBER() OVER (ORDER BY V.GROUP_ID, V.DIVISION_ID) AS ROW_NO
                 , V.GROUP_ID
                 , V.DIVISION_ID
                 , V.APPROVAL_RESULT
                 , V.APPROVAL_ID
                 , V.APPROVAL_NAME
                 , V.APPROVED_DATE
              FROM SCM_ADM_DEPT_CHANGED_V V
             WHERE 1 = 1
               AND V.USER_ID = V_USER_ID;

            IF TO_NUMBER(V_REMAIN_DAY) > 0 THEN
                V_BODY_TEXT1 := '부서변경으로 인하여 ' || V_USER_NAME || '님의 아래 GSCM권한이 ' || V_REMAIN_DAY || '일내로 회수될 예정입니다.';
                V_BODY_TEXT3 := 'Your SCM authority will be deleted in ' || V_REMAIN_DAY || ' days due to change your department.';
            ELSE
                V_BODY_TEXT1 := '부서변경으로 인하여 ' || V_USER_NAME || '님의 아래 GSCM권한이 즉시 회수될 예정입니다.';
                V_BODY_TEXT3 := 'Your SCM authority will be deleted immediately due to change your department.';
            END IF;

            V_BODY_TEXT2 := '권한유지를 원하신다면 시스템을 통해 재 신청해 주세요. 권한 신청관련 문의사항 있으시면 SCM PI팀으로 연락주시기 바랍니다.';
            V_BODY_TEXT4 := 'If you want to last your authority, please register authority request. If you have any questions about authority request, please contact the SCM PI Team.';


            V_TABLE_COL := '<tr style="text-align:center">';
            V_TABLE_COL := V_TABLE_COL || '<th>' || 'Authority'       || '</th>';
            V_TABLE_COL := V_TABLE_COL || '<th>' || 'Division'        || '</th>';
            V_TABLE_COL := V_TABLE_COL || '<th>' || 'Approval Result' || '</th>';
            V_TABLE_COL := V_TABLE_COL || '<th>' || 'Approval User'   || '</th>';
            V_TABLE_COL := V_TABLE_COL || '<th>' || 'Approved Date'   || '</th>';
            V_TABLE_COL := V_TABLE_COL || '</tr>';

            V_TABLE_ROW := '';

            SELECT 1
                 , COUNT(*)
              INTO V_INX
                 , V_MAX_NUM
              FROM GT_SADCM_TAB;


            WHILE V_INX <= V_MAX_NUM
            LOOP
                SELECT GROUP_ID
                     , DIVISION_ID
                     , APPROVAL_RESULT
                     , APPROVAL_ID
                     , APPROVAL_NAME
                     , APPROVED_DATE
                  INTO V_T_GROUP_ID
                     , V_T_DIVISION_ID
                     , V_T_APPROVAL_RESULT
                     , V_T_APPROVAL_ID
                     , V_T_APPROVAL_NAME
                     , V_T_APPROVED_DATE
                  FROM GT_SADCM_TAB
                 WHERE ROW_NO = V_INX;

                /* [2026-10-07] MSSQL `+` 의 NULL 전파를 재현한다.
                 *  원본 : SET @t_approval_name = @t_approval_name + '(' + @t_approval_id + ')'
                 *  MSSQL 은 피연산자 하나라도 NULL 이면 **식 전체가 NULL** 이 되고, 아래 출력의
                 *  ISNULL(..., '') 가 그것을 빈칸으로 바꿔 <td></td> 가 된다.
                 *  Oracle `||` 는 NULL 을 흡수하므로 그대로 두면 '(승인자ID)' 가 남아 본문이 달라진다.
                 *  실측 : SCM_ADM_DEPT_CHANGED_V 55행 중 APPROVAL_NAME NULL 12행(21.8%) — 실제로 갈린다. */
                V_T_APPROVAL_NAME := CASE
                                         WHEN V_T_APPROVAL_NAME IS NULL
                                           OR V_T_APPROVAL_ID   IS NULL
                                         THEN NULL
                                         ELSE V_T_APPROVAL_NAME || '(' || V_T_APPROVAL_ID || ')'
                                     END;


                V_TABLE_ROW := V_TABLE_ROW || '<tr style="text-align:center">';
                V_TABLE_ROW := V_TABLE_ROW || '<td>' || REPLACE(V_T_GROUP_ID,        CHR(10), ' ') || '</td>';
                V_TABLE_ROW := V_TABLE_ROW || '<td>' || REPLACE(V_T_DIVISION_ID,     CHR(10), ' ') || '</td>';
                V_TABLE_ROW := V_TABLE_ROW || '<td>' || REPLACE(V_T_APPROVAL_RESULT, CHR(10), ' ') || '</td>';
                V_TABLE_ROW := V_TABLE_ROW || '<td>' || REPLACE(V_T_APPROVAL_NAME,   CHR(10), ' ') || '</td>';
                V_TABLE_ROW := V_TABLE_ROW || '<td>' || REPLACE(V_T_APPROVED_DATE,   CHR(10), ' ') || '</td>';
                V_TABLE_ROW := V_TABLE_ROW || '</tr>';

                V_INX := V_INX + 1;
            END LOOP;


            V_TABLE_BODY := ' <html>
                            <head>
                            <title>Untitled Document</title>
                            <style>
                                * {margin:0;padding:0;}
                                body {font-family:Malgun Gothic, Arial, Helvetica, sans-serif;font-size:12px;line-height:1.8;color:#333333;}
                                table {border-collapse:collapse;width:100%;}
                                table th {background:#f5f5f5;border-bottom:1px solid #e1e1e1;}
                                table td {background:#fff;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1;border-bottom:1px solid #e1e1e1;}
                                table tbody th {border-left:1px solid #e1e1e1;text-align:center;padding:6px 8px;font-size:12px}
                                table tbody td {padding:6px 8px;font-size:12px}
                                table thead th {text-align:center;padding:3px;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1; border-bottom:1px solid #d1d1d1;font-size:12px}
                                .hori-table table thead td {text-align:center;padding:3px;}
                                .hori-table table tbody td {text-align:center;padding:3px;}
                                .vertical-table, .hori-table {margin-bottom:20px;}
                            </style>
                            </head>
                            <body>'
                                || '<br />'
                                || '<b>' || REPLACE(V_BODY_TEXT1, CHR(10), '<br />') || '</b>'
                                || '<br />'
                                || '<b>' || REPLACE(V_BODY_TEXT2, CHR(10), '<br />') || '</b>'
                                || '<br />'
                                || '<br />'
                                || '<b>' || REPLACE(V_BODY_TEXT3, CHR(10), '<br />') || '</b>'
                                || '<br />'
                                || '<b>' || REPLACE(V_BODY_TEXT4, CHR(10), '<br />') || '</b>'
                                || '<br />'
                                || '<br />'
                                || '<br />'
                                || '<div><table style=''border-top:2px solid #c8294b; width:750px;''>
                                    <thead>' || V_TABLE_COL || '</thead>
                                    <tbody>' || V_TABLE_ROW || '</tbody>
                                   </div>
                            </body>
                    </html>';

            V_MAIL_RECEIVER := V_USER_ID || '@lgensol.com';   /* 실제 사용자 */
            /*             *   V_MAIL_RECEIVER := V_USER_ID || '@lgespartner.com';
             *   V_MAIL_RECEIVER := 'crjung@lgespartner.com'; */


            /* [2026-10-07] 발송 간 대기 삭제 (사용자 지시 2026-10-06).
             * ★이 건은 수신자마다 본문이 달라 묶음 발송 대상이 아니다 — 묶음과 무관하게 대기 로직 자체를 삭제하라는 지시다.
             * 원본 MSSQL 의 WAITFOR DELAY 는 그대로 둔다 — 원본을 고치는 게 아니라 Oracle 발송 방식에 맞춘 것이다.
             * 삭제한 블록 : IF MOD(V_MAIL_SEND_CNT, 10) = 0 THEN DBMS_SESSION.SLEEP(5); DBMS_OUTPUT.PUT_LINE('메일 전송 대기 중 입니다.'); END IF; */

            V_MAIL_BODY := V_TABLE_BODY;

            /* 메일 전송
             *   SELECT @v_profile_name = IIF(db_name() = 'LGCE_SCMPROD', 'GSCM_MAIL_PROD', 'GSCM_MAIL_TEST');
             *   EXEC msdb.dbo.sp_send_dbmail @profile_name = @v_profile_name, @recipients = @v_mail_receiver, */
            PKG_SEND_MAIL.P_SEND_MAIL(V_MAIL_RECEIVER, V_MAIL_SUBJECT, V_MAIL_BODY, 'Y');

            /* 메일 전송 카운트 증가 */
            V_MAIL_SEND_CNT := V_MAIL_SEND_CNT + 1;
        END LOOP;

        /* 종료 LOG */
        V_LOG_TYPE    := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);


    EXCEPTION
        WHEN OTHERS THEN

            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := SUBSTR(V_PROGRAM_NAME || 'ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 500);
            INSERT
              INTO SCM_SYS_LOG_BATCH
                 ( PROGRAM_NAME
                 , LOG_TYPE
                 , LOG_COUNT
                 , LOG_MESSAGE
                 , DESCRIPTION
                 , EVENT_DATE
                 , CREATION_DATE
                 , CREATED_BY
                 , LAST_UPDATE_DATE
                 , LAST_UPDATED_BY )
            VALUES ( V_PROGRAM_NAME
                 , 'ERROR'
                 , NULL
                 , V_LOG_MESSAGE
                 , V_DESCRIPTION
                 , SYSDATE
                 , SYSDATE
                 , V_PROGRAM_NAME
                 , SYSDATE
                 , V_PROGRAM_NAME );
            COMMIT;
            /*             *   SELECT 'F' AS result_code;
             *   SELECT '[' + CONVERT(nvarchar(10), ERROR_NUMBER()) + ']' + ERROR_MESSAGE(); */
            DBMS_OUTPUT.PUT_LINE('F');
            DBMS_OUTPUT.PUT_LINE('[' || TO_CHAR(SQLCODE) || ']' || V_LOG_MESSAGE);
    END;
END;

PROCEDURE PR_SCM_ADM_LONG_TERM_STOCK_MAIL

AS
/*
 * Program ID   : PR_SCM_ADM_LONG_TERM_STOCK_MAIL  (장기(징후)자재 월간 메일 리포트, 매달 8/20일)
 * 변환(MSSQL->Oracle) 2026-06-26 : #30 B(메일) 트랙 — CSV 첨부 = CLOB 엔진
 *   - ★bcp(파일 CSV생성)+xp_cmdshell(del) -> PL/SQL 동적쿼리 결과를 CSV(CLOB) 조립 -> PKG_SEND_MAIL.P_SEND_MAIL_CLOB_ATTACH(CLOB, 크기무제한)
 *     (#16은 RAW 32KB한계 -> 대량 LTS CSV는 CLOB 엔진이 적합. 사용자 결정 2026-06-26)
 *   - 거대 동적 리포트SQL: @v_targetDB(DB_NAME) 제거(동일DB), IIF->CASE, STR/RTRIM/LTRIM->TRIM(TO_CHAR(ROUND())), ISNULL(x,'')!=''->x IS NOT NULL, N'..'->'..'
 *   - @v_tb_recipient(테이블변수)+CTE -> 동적커서(C_RECIP_Q, 섹션별 prefix A%/B%/C% USING)
 *   - 중첩 서브프로그램: GET_CNT(필터)·BUILD_CSV(필터)RETURN CLOB·LOG_MAIL(건수,설명)
 *   - @v_toMail='' 상수 -> IF(toMail!='') 분기는 dead(항상 ELSE: 담당자+추가수신자). 충실 반영
 *   - FORMAT(yyyyMM)->TO_CHAR(ADD_MONTHS(SYSDATE,-1),'YYYYMM'), STUFF(FOR XML 추가수신자)->LISTAGG(SEGMENT3,';')
 *   ※발송 런타임=dev UTL_MAIL 미설치(PKG_SEND_MAIL BODY INVALID)로 보류=DBA 인프라(컴파일 VALID 무관)
 * 2026.07.06	ZIONEX		[PJ202650304] NextSCM Migration
 */
    V_PROGRAM_NAME    VARCHAR2(150 CHAR) := 'PR_SCM_ADM_LONG_TERM_STOCK_MAIL';
    V_LOG_TYPE        VARCHAR2(30 CHAR);
    N_LOG_COUNT       INTEGER := 0;
    V_LOG_MESSAGE     VARCHAR2(1000 CHAR);
    V_DESCRIPTION     VARCHAR2(500 CHAR);
    D_EVENT_DATE      DATE;
    V_ESOC            VARCHAR2(8 CHAR);
    V_TOMAIL          VARCHAR2(200 CHAR) := NULL;
    V_TOMAIL_ADDL     VARCHAR2(1000 CHAR);              /* 추가수신자 */
    V_YYYYMM          VARCHAR2(6 CHAR);
    V_SUBJECT         VARCHAR2(200 CHAR);
    V_SUBJECT1        VARCHAR2(200 CHAR);
    V_BODYCONTENTS    VARCHAR2(200 CHAR);
    V_FROMWHERE       VARCHAR2(4000 CHAR);
    V_CSV_BASE        VARCHAR2(100 CHAR);

    V_COLS  CONSTANT VARCHAR2(2000 CHAR) :=
        'A.YYYYMM, A.DIVISION_ID, '
        ||'REPLACE(B.PLANT_NAME,'','','' ''), REPLACE(A.PLANT_ID,'','','' ''), REPLACE(A.ITEM_ID,'','','' ''), '
        ||'REPLACE(A.ITEM_NAME,'','','' ''), REPLACE(A.ITEM_UOM,'','','' ''), REPLACE(A.LONG_TERM_TYPE,'','','' ''), '
        ||'REPLACE(D.ITEM_TYPE,'','','' ''), REPLACE(D.PROCESS_GROUP,'','','' ''), REPLACE(D.PROCESS_DETAIL,'','','' ''), '
        ||'A.VALUATION_CLASS, A.DEVALUATION_AGE, '
        ||'TRIM(TO_CHAR(ROUND(A.LONG_TERM_STOCK_QTY))), '
        ||'TRIM(TO_CHAR(ROUND(CASE WHEN A.WAERS=''KRW'' OR A.EX_TO_BAMT=0 THEN A.LONG_TERM_STOCK_AMOUNT ELSE A.UNIT_PRICE*A.EX_TO_BAMT*A.LONG_TERM_STOCK_QTY END))), '
        ||'TRIM(TO_CHAR(ROUND(CASE WHEN A.WAERS=''KRW'' OR A.EX_TO_BAMT=0 THEN A.UNIT_PRICE ELSE A.UNIT_PRICE*A.EX_TO_BAMT END))), '
        ||'E.PIC_NM, '
        ||'CASE WHEN F.ITEM_ID IS NOT NULL THEN ''O'' ELSE F.ITEM_ID END';
    V_HEADER CONSTANT VARCHAR2(1000 CHAR) :=
        'YY.MM,DIV,Plant Site,Plant,Material,Description,Unit,Long Term Type,Item Type,Process Group,Material Group,Valuation class,Devaluation Age,Qty(Long term stock),Amount(Long term stock)(KRW),Unit price(KRW),PIC,NO Usage in 3M';

    V_RECIP_Q CONSTANT VARCHAR2(2000 CHAR) :=
        'WITH SUB AS (SELECT SEGMENT1,SEGMENT3,LOOKUP_TYPE FROM SCM_ADM_LOOKUP_MASTER_DETAIL WHERE LOOKUP_TYPE=''SCP_LTS_RECIPIENT'' AND VALID_YN=''Y''),'
        ||'SUB1 AS (SELECT SEGMENT1,SEGMENT2,SEGMENT3,SEGMENT4,DISPLAY_SEQ FROM SCM_ADM_LOOKUP_MASTER_DETAIL WHERE LOOKUP_TYPE=''SCP_LTS_VIEW_LIST'' AND VALID_YN=''Y''),'
        ||'SUB2 AS (SELECT ROW_NUMBER() OVER (ORDER BY B.DISPLAY_SEQ) DISPLAY_SEQ, A.SEGMENT1, B.SEGMENT1 SEGMENT2, A.SEGMENT3, B.SEGMENT2 SEGMENT4, B.SEGMENT4 SEGMENT5 '
        ||'FROM SUB A INNER JOIN SUB1 B ON A.SEGMENT3=B.SEGMENT3 WHERE A.LOOKUP_TYPE=''SCP_LTS_RECIPIENT'' AND A.SEGMENT1 LIKE :p) '
        ||'SELECT SEGMENT2, SEGMENT3, SEGMENT5 FROM SUB2 ORDER BY DISPLAY_SEQ';
    CRLF CONSTANT VARCHAR2(2 CHAR) := CHR(13)||CHR(10);
    V_RCUR    SYS_REFCURSOR;
    V_SEG2    VARCHAR2(100 CHAR);
    V_SEG3    VARCHAR2(100 CHAR);
    V_SEG5    VARCHAR2(100 CHAR);
    V_FILTER  VARCHAR2(4000 CHAR);
    V_CNT     INTEGER;
    V_CSV     CLOB;

    FUNCTION GET_CNT(P_FILTER IN VARCHAR2) RETURN INTEGER IS
        V_N INTEGER;
    BEGIN
        EXECUTE IMMEDIATE 'SELECT COUNT(*) ' || V_FROMWHERE || P_FILTER INTO V_N;
        RETURN V_N;
    END;

    FUNCTION BUILD_CSV(P_FILTER IN VARCHAR2) RETURN CLOB IS
        V_OUT  CLOB;
        V_BUF  VARCHAR2(32767 CHAR);
        V_CUR  SYS_REFCURSOR;
        C1 VARCHAR2(4000 CHAR); C2 VARCHAR2(4000 CHAR); C3 VARCHAR2(4000 CHAR); C4 VARCHAR2(4000 CHAR); C5 VARCHAR2(4000 CHAR); C6 VARCHAR2(4000 CHAR);
        C7 VARCHAR2(4000 CHAR); C8 VARCHAR2(4000 CHAR); C9 VARCHAR2(4000 CHAR); C10 VARCHAR2(4000 CHAR); C11 VARCHAR2(4000 CHAR); C12 VARCHAR2(4000 CHAR);
        C13 VARCHAR2(4000 CHAR); C14 VARCHAR2(4000 CHAR); C15 VARCHAR2(4000 CHAR); C16 VARCHAR2(4000 CHAR); C17 VARCHAR2(4000 CHAR); C18 VARCHAR2(4000 CHAR);
        V_LINE VARCHAR2(32767 CHAR);
    BEGIN
        DBMS_LOB.CREATETEMPORARY(V_OUT, TRUE);
        V_BUF := V_HEADER || CRLF;
        OPEN V_CUR FOR 'SELECT ' || V_COLS || ' ' || V_FROMWHERE || P_FILTER;
        LOOP
            FETCH V_CUR INTO C1,C2,C3,C4,C5,C6,C7,C8,C9,C10,C11,C12,C13,C14,C15,C16,C17,C18;
            EXIT WHEN V_CUR%NOTFOUND;
            V_LINE := C1||','||C2||','||C3||','||C4||','||C5||','||C6||','||C7||','||C8||','||C9||','||C10||','
                    ||C11||','||C12||','||C13||','||C14||','||C15||','||C16||','||C17||','||C18||CRLF;
            IF LENGTH(V_BUF) + LENGTH(V_LINE) > 32000 THEN
                DBMS_LOB.WRITEAPPEND(V_OUT, LENGTH(V_BUF), V_BUF);
                V_BUF := NULL;
            END IF;
            V_BUF := V_BUF || V_LINE;
        END LOOP;
        CLOSE V_CUR;
        IF V_BUF IS NOT NULL AND LENGTH(V_BUF) > 0 THEN
            DBMS_LOB.WRITEAPPEND(V_OUT, LENGTH(V_BUF), V_BUF);
        END IF;
        RETURN V_OUT;
    END;

    PROCEDURE LOG_MAIL(P_CNT IN INTEGER, P_DESC IN VARCHAR2) IS
    BEGIN
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, 'MAIL', P_CNT, NULL, P_DESC, SYSDATE);
    END;
BEGIN
    /* NERP 매핑코드 */
    V_ESOC := FN_GET_LOOKUP_VALUE('PR_SCM_ADM_LONG_TERM_STOCK_MAIL', 'ESOC');

    /* 시작 LOG */
    V_LOG_TYPE := 'START'; V_LOG_MESSAGE := '########## Start of procedure ##########'; V_DESCRIPTION := NULL; D_EVENT_DATE := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);


    SELECT LISTAGG(SEGMENT3, ';') WITHIN GROUP (ORDER BY SEGMENT3)
      INTO V_TOMAIL_ADDL
      FROM SCM_ADM_LOOKUP_MASTER_DETAIL
     WHERE LOOKUP_TYPE = 'SCP_RPA_ADDITIONAL_RECIPIENTS'
       AND VALID_YN    = 'Y';

    V_YYYYMM       := TO_CHAR(ADD_MONTHS(SYSDATE, -1), 'YYYYMM');
    V_CSV_BASE     := V_YYYYMM || '_long_term_stock_list';
    V_SUBJECT      := '[담당자 확인] ' || TO_CHAR(SYSDATE, 'YY') || '년 ' || TO_CHAR(ADD_MONTHS(SYSDATE, -1), 'MM') || '월 장기(징후) 자재 자동 알람';
    /* [2026-10-07] 비운영에서는 제목에 'DEV Oracle 개발서버 ' 를 붙인다 (사용자 결정 가).
     * 원본 MSSQL 은 이 건을 SCM_ADM_MAIL_SEND(행 17) 경유로 보내고 Oracle 행 17 에 같은 분기가 있는데,
     * Oracle 은 PKG_SEND_MAIL 을 직접 불러(계보 평탄화) 그 표시가 빠졌다.
     * 발송 동작은 원본 그대로 두고 식별만 되살린다 — 행 10·17 과 같은 판정식이다. */
    IF SYS_CONTEXT('USERENV', 'DB_NAME') NOT LIKE 'OCGSCMP%' THEN
        V_SUBJECT := 'DEV Oracle 개발서버 '||V_SUBJECT;
    END IF;
    V_SUBJECT1     := V_SUBJECT || ' PIC 미입력';
    V_BODYCONTENTS := '장기(징후) 자재에 대해 아래(첨부)와 같이 송부드리오니, 확인 및 조치하시길 바랍니다.';

    /* 리포트 기준쿼리 FROM+WHERE (@v_targetDB 제거) */
    V_FROMWHERE :=
        'FROM SCP_ANL_LONG_TERM_STOCK A '
        ||'INNER JOIN (SELECT PLANT_ID, MAX(PLANT_NAME) PLANT_NAME FROM SCM_PLANT_M_SN GROUP BY PLANT_ID) B ON A.PLANT_ID=B.PLANT_ID '
        ||'LEFT JOIN (SELECT ITEM_ID, MAX(SCP_EXTRA_SPEC) SCP_EXTRA_SPEC, MAX(ITEM_CLASS) ITEM_CLASS FROM SCM_MST_ITEM_SN GROUP BY ITEM_ID) C ON A.ITEM_ID=C.ITEM_ID '
        ||'LEFT JOIN SCM_MST_ITEM_CLASS_M D ON C.ITEM_CLASS=D.CLASS_ID '
        ||'LEFT JOIN SCP_MST_PIC_INFO E ON E.PLANT_ID=A.PLANT_ID AND E.ITEM_ID=A.ITEM_ID '
        ||'LEFT JOIN SCP_MST_NO_USE_3M F ON F.PLANT_ID=A.PLANT_ID AND F.ITEM_ID=A.ITEM_ID '
        ||'INNER JOIN (SELECT PLANT_ID FROM SCM_MST_SITE WHERE OSP_YN=''N'' AND OPERATION_GROUP<>''W'' GROUP BY PLANT_ID) G ON A.PLANT_ID=G.PLANT_ID '
        ||'WHERE A.YYYYMM=''' || V_YYYYMM || ''' AND A.VALUATION_CLASS IN (''3000'',''3001'') AND A.DEVALUATION_AGE NOT IN (''GRM00'',''GRM01'',''GRM02'',''GRM03'')';

    BEGIN
        /* ----------------------------------------------------------------- */

        /* ----------------------------------------------------------------- */
        OPEN V_RCUR FOR V_RECIP_Q USING 'A%';
        LOOP
            FETCH V_RCUR INTO V_SEG2, V_SEG3, V_SEG5;
            EXIT WHEN V_RCUR%NOTFOUND;

            V_FILTER := ' AND EXISTS (SELECT 1 FROM SCM_ADM_LOOKUP_MASTER_DETAIL WHERE LOOKUP_TYPE=''SCP_LTS_VIEW_LIST'' AND VALID_YN=''Y'' AND SEGMENT1=E.PIC_NO AND SEGMENT2 IN '
                      ||'(SELECT B.SEGMENT2 FROM (SELECT SEGMENT1,SEGMENT3,LOOKUP_TYPE FROM SCM_ADM_LOOKUP_MASTER_DETAIL WHERE LOOKUP_TYPE=''SCP_LTS_RECIPIENT'' AND VALID_YN=''Y'') A '
                      ||'INNER JOIN (SELECT SEGMENT1,SEGMENT2,SEGMENT3,SEGMENT4,DISPLAY_SEQ FROM SCM_ADM_LOOKUP_MASTER_DETAIL WHERE LOOKUP_TYPE=''SCP_LTS_VIEW_LIST'' AND VALID_YN=''Y'') B '
                      ||'ON A.SEGMENT3=B.SEGMENT3 WHERE A.LOOKUP_TYPE=''SCP_LTS_RECIPIENT'' AND B.SEGMENT4 LIKE ''' || V_SEG5 || '%''))';
            V_CNT := GET_CNT(V_FILTER);
            V_CSV := BUILD_CSV(V_FILTER);
            PKG_SEND_MAIL.P_SEND_MAIL_CLOB_ATTACH(V_SEG3,        V_SUBJECT, V_BODYCONTENTS, V_CSV, V_CSV_BASE||'_(team).csv', 'text/csv');
            PKG_SEND_MAIL.P_SEND_MAIL_CLOB_ATTACH(V_TOMAIL_ADDL, V_SUBJECT, V_BODYCONTENTS, V_CSV, V_CSV_BASE||'_(team).csv', 'text/csv');
            DBMS_LOB.FREETEMPORARY(V_CSV);
            LOG_MAIL(V_CNT, '[메일발신] : ' || V_SEG3);

            V_FILTER := ' AND E.PIC_NO IS NULL AND EXISTS (SELECT 1 FROM SCM_MST_SITE WHERE PLANT_ID=A.PLANT_ID AND SITE_TYPE=''PLANT'' AND COMPANY_ID=''' || V_ESOC || ''' AND OSP_YN=''N'')';
            V_CNT := GET_CNT(V_FILTER);
            V_CSV := BUILD_CSV(V_FILTER);
            PKG_SEND_MAIL.P_SEND_MAIL_CLOB_ATTACH(V_SEG3,        V_SUBJECT1, V_BODYCONTENTS, V_CSV, V_CSV_BASE||'_(team)_NOPIC.csv', 'text/csv');
            PKG_SEND_MAIL.P_SEND_MAIL_CLOB_ATTACH(V_TOMAIL_ADDL, V_SUBJECT,  V_BODYCONTENTS, V_CSV, V_CSV_BASE||'_(team)_NOPIC.csv', 'text/csv');
            DBMS_LOB.FREETEMPORARY(V_CSV);
            LOG_MAIL(V_CNT, '[메일발신 (NOPIC)] : ' || V_SEG3);
        END LOOP;
        CLOSE V_RCUR;

        /* ----------------------------------------------------------------- */

        /* ----------------------------------------------------------------- */
        OPEN V_RCUR FOR V_RECIP_Q USING 'B%';
        LOOP
            FETCH V_RCUR INTO V_SEG2, V_SEG3, V_SEG5;
            EXIT WHEN V_RCUR%NOTFOUND;
            V_FILTER := ' AND EXISTS (SELECT 1 FROM SCM_ADM_LOOKUP_MASTER_DETAIL WHERE LOOKUP_TYPE=''SCP_LTS_VIEW_LIST'' AND VALID_YN=''Y'' AND SEGMENT1=E.PIC_NO AND SEGMENT2 IN '
                      ||'(SELECT B.SEGMENT2 FROM (SELECT SEGMENT1,SEGMENT3,LOOKUP_TYPE FROM SCM_ADM_LOOKUP_MASTER_DETAIL WHERE LOOKUP_TYPE=''SCP_LTS_RECIPIENT'' AND VALID_YN=''Y'') A '
                      ||'INNER JOIN (SELECT SEGMENT1,SEGMENT2,SEGMENT3,SEGMENT4,DISPLAY_SEQ FROM SCM_ADM_LOOKUP_MASTER_DETAIL WHERE LOOKUP_TYPE=''SCP_LTS_VIEW_LIST'' AND VALID_YN=''Y'') B '
                      ||'ON A.SEGMENT3=B.SEGMENT3 WHERE A.LOOKUP_TYPE=''SCP_LTS_RECIPIENT'' AND B.SEGMENT4 LIKE ''' || V_SEG5 || '%''))';
            V_CNT := GET_CNT(V_FILTER);
            V_CSV := BUILD_CSV(V_FILTER);
            PKG_SEND_MAIL.P_SEND_MAIL_CLOB_ATTACH(V_SEG3, V_SUBJECT, V_BODYCONTENTS, V_CSV, V_CSV_BASE||'_(part).csv', 'text/csv');
            DBMS_LOB.FREETEMPORARY(V_CSV);
            LOG_MAIL(V_CNT, '[메일발신] : ' || V_SEG3);
            V_FILTER := ' AND E.PIC_NO IS NULL AND EXISTS (SELECT 1 FROM SCM_MST_SITE WHERE PLANT_ID=A.PLANT_ID AND SITE_TYPE=''PLANT'' AND COMPANY_ID=''' || V_ESOC || ''' AND OSP_YN=''N'')';
            V_CNT := GET_CNT(V_FILTER);
            V_CSV := BUILD_CSV(V_FILTER);
            PKG_SEND_MAIL.P_SEND_MAIL_CLOB_ATTACH(V_SEG3, V_SUBJECT1, V_BODYCONTENTS, V_CSV, V_CSV_BASE||'_(part)_NOPIC.csv', 'text/csv');
            DBMS_LOB.FREETEMPORARY(V_CSV);
            LOG_MAIL(V_CNT, '[메일발신 (NOPIC)] : ' || V_SEG3);
        END LOOP;
        CLOSE V_RCUR;

        /* ----------------------------------------------------------------- */

        /* ----------------------------------------------------------------- */
        OPEN V_RCUR FOR V_RECIP_Q USING 'C%';
        LOOP
            FETCH V_RCUR INTO V_SEG2, V_SEG3, V_SEG5;
            EXIT WHEN V_RCUR%NOTFOUND;
            V_FILTER := ' AND E.PIC_NO = ''' || V_SEG2 || '''';
            V_CNT := GET_CNT(V_FILTER);
            IF V_CNT > 0 THEN
                V_CSV := BUILD_CSV(V_FILTER);
                PKG_SEND_MAIL.P_SEND_MAIL_CLOB_ATTACH(V_SEG3, V_SUBJECT, V_BODYCONTENTS, V_CSV, V_CSV_BASE||'.csv', 'text/csv');
                DBMS_LOB.FREETEMPORARY(V_CSV);
            END IF;
            LOG_MAIL(V_CNT, '[메일발신] : ' || V_SEG3);
        END LOOP;
        CLOSE V_RCUR;

    EXCEPTION
        WHEN OTHERS THEN
            IF V_RCUR%ISOPEN THEN CLOSE V_RCUR; END IF;
            V_LOG_TYPE := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := 'ERROR_CODE : ' || TO_CHAR(SQLCODE);
            D_EVENT_DATE := SYSDATE;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    END;

    /* 종료 LOG */
    V_LOG_TYPE := 'END'; V_LOG_MESSAGE := '########## END of procedure ##########'; V_DESCRIPTION := NULL; D_EVENT_DATE := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
END;

PROCEDURE           "PR_SCM_ADM_MAIL_AND_FILE_SEND" 
(
    P_TO_MAIL        IN  VARCHAR2
  , P_SUBJECT        IN  VARCHAR2
  , P_BODY_CONTENTS  IN  VARCHAR2,
    P_ATTACH_DATA    IN  RAW,
    P_ATTACH_NAME    IN  VARCHAR2,
    P_ATTACH_MIME    IN  VARCHAR2 DEFAULT 'text/csv',
    O_RESULT         OUT SYS_REFCURSOR
)
AS
/*
 * Program ID   : PR_SCM_ADM_MAIL_AND_FILE_SEND  (메일+파일첨부 공통엔진)
 * 변환(MSSQL->Oracle) 2026-06-26 : #16 B(메일) 트랙
 *   - ★As-Is sp_send_dbmail @file_attachments(파일경로) -> 계약변경: P_ATTACH_DATA RAW + P_ATTACH_NAME
 *     (Oracle DIRECTORY 부재·파일생성도 마이그 대상이라 경로방식 폐기. 사용자 승인 2026-06-26)
 *   - 발송: SCM_MGR.PKG_SEND_MAIL.P_SEND_MAIL_ATTACH(RAW). P_HTML_YN='N'(As-Is sp_send_dbmail 기본=TEXT)
 *   - As-Is 다중파일(A;B;C)=실사용0 -> 단일 RAW(다중필요시 호출부 반복)
 *   - 결과셋: 성공 'S' / 에러 'F'+메시지 -> OUT SYS_REFCURSOR. CATCH 직접 INSERT 로그 -> PR_SCM_SYS_LOG_BATCH(표준)
 *   - RAW 32767 한계: 대용량 첨부는 PKG_SEND_MAIL.P_SEND_MAIL_CLOB_ATTACH(CLOB) 별도(범위밖)
 *   ※런타임 발송은 dev UTL_MAIL 미설치(PKG_SEND_MAIL BODY INVALID)로 ORA-04063 -> CATCH가 'F' 반환=정상동작. 컴파일 VALID는 무관(DBA 인프라)
 * 2026.07.06	ZIONEX		[PJ202650304] NextSCM Migration
 */
    V_PROGRAM_NAME   VARCHAR2(150 CHAR) := 'PR_SCM_ADM_MAIL_AND_FILE_SEND';
    V_LOG_TYPE       VARCHAR2(30 CHAR);
    N_LOG_COUNT      INTEGER := 0;
    V_LOG_MESSAGE    VARCHAR2(1000 CHAR);
    V_DESCRIPTION    VARCHAR2(500 CHAR);
    D_EVENT_DATE     DATE;
    V_ERR_DISPLAY    VARCHAR2(1100 CHAR);
BEGIN
    /* 시작 LOG */
    V_LOG_TYPE := 'START'; V_LOG_MESSAGE := '########## Start of procedure ##########'; V_DESCRIPTION := NULL; D_EVENT_DATE := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);


    PKG_SEND_MAIL.P_SEND_MAIL_ATTACH(
          P_TO_MAIL       => P_TO_MAIL
        , P_SUBJECT       => P_SUBJECT
        , P_BODY_CONTENTS => P_BODY_CONTENTS
        , P_ATTACH_DATA   => P_ATTACH_DATA
        , P_ATTACH_NAME   => P_ATTACH_NAME
        , P_ATTACH_MIME   => P_ATTACH_MIME
        , P_HTML_YN       => 'N');


    V_LOG_TYPE := 'END'; V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := 'recipients : ' || P_TO_MAIL; D_EVENT_DATE := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    OPEN O_RESULT FOR SELECT 'S' AS RESULT_CODE, CAST(NULL AS VARCHAR2(1100 CHAR)) AS ERROR_MESSAGE FROM DUAL;

EXCEPTION
    WHEN OTHERS THEN
        V_ERR_DISPLAY := '[' || TO_CHAR(SQLCODE) || ']' || SQLERRM;
        V_LOG_TYPE := 'ERROR';
        V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
        V_DESCRIPTION := V_PROGRAM_NAME || ' SQLCODE : ' || TO_CHAR(SQLCODE);
        D_EVENT_DATE := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
        OPEN O_RESULT FOR SELECT 'F' AS RESULT_CODE, V_ERR_DISPLAY AS ERROR_MESSAGE FROM DUAL;
END;

PROCEDURE         PR_SCM_ADM_NOTICE_CONFIRM_HIST

(
    P_NOTICE_ID       INTEGER
   ,P_USER_ID         VARCHAR2
   ,P_CREATED_BY      VARCHAR2
   ,P_CREATION_DATE   VARCHAR2
   ,P_LAST_UPDATED_BY VARCHAR2
)
/*
 * Program ID   : PR_SCM_ADM_NOTICE_CONFIRM_HIST
 * Description  : NOTICE CONFIRM History
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2018.02.26   ygkim      Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 *
 * 2026.03.24   김준규     [PJ20264226] NextSCM Pilot 설계 및 개발
 *
 * 2026.07.06   ZIONEX   [PJ202650304] NextSCM Migration
 */
 AS

    V_IN_PARA_DATA  VARCHAR2(4000 CHAR);
    N_HISTORY_SEQ   INTEGER;
    V_PROGRAM_NAME  VARCHAR2(200 CHAR) := $$PLSQL_UNIT;
    V_STEP          VARCHAR2(4000 CHAR) := NULL;
    V_LOG_TYPE      VARCHAR2(30 CHAR);
    N_LOG_COUNT     INTEGER := 0;
    V_LOG_MESSAGE   VARCHAR2(1000 CHAR);
    V_DESCRIPTION   VARCHAR2(500 CHAR);
    D_EVENT_DATE    DATE;
    V_CREATION_DATE DATE := TO_DATE(P_CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS');
BEGIN

    IF UTL_CALL_STACK.SUBPROGRAM(1).COUNT > 1 THEN
        V_PROGRAM_NAME := $$PLSQL_UNIT || '.' || UTL_CALL_STACK.SUBPROGRAM(1) (2);
    END IF;

    V_IN_PARA_DATA := JSON_OBJECT('p_notice_id' VALUE P_NOTICE_ID
                                 ,'p_user_id' VALUE P_USER_ID
                                 ,'p_created_by' VALUE P_CREATED_BY
                                 ,'p_creation_date' VALUE P_CREATION_DATE
                                 ,'p_last_updated_by' VALUE P_LAST_UPDATED_BY);

    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := NULL;
    D_EVENT_DATE  := SYSTIMESTAMP;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    BEGIN
        N_HISTORY_SEQ := SEQ1_SCM_ADM_NOTICE_CONFIRM_H.NEXTVAL;

        BEGIN
            INSERT
              INTO SCM_ADM_NOTICE_CONFIRM_H
                 ( HISTORY_SEQ
                 , NOTICE_ID
                 , USER_ID
                 , CREATED_BY
                 , CREATION_DATE
                 , LAST_UPDATED_BY
                 , LAST_UPDATE_DATE )
            VALUES ( N_HISTORY_SEQ
                   , P_NOTICE_ID
                   , P_USER_ID
                   , P_CREATED_BY
                   , V_CREATION_DATE
                   , P_LAST_UPDATED_BY
                   , SYSTIMESTAMP );
        END;
    END;

    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := NULL;
    D_EVENT_DATE  := SYSTIMESTAMP;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    COMMIT;

EXCEPTION
    WHEN OTHERS THEN
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME
                            ,'ERROR'
                            ,0
                            ,SQLERRM
                            ,NULL
                            ,SYSDATE
                            ,P_IN_PARA_DATA  => V_IN_PARA_DATA
                            ,P_SQL_ERR_CODE  => SQLCODE
                            ,P_SQL_ERR_MSG   => SQLERRM
                            ,P_SQL_BACKTRACE => DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
END;

PROCEDURE PR_SCM_ADM_NOTICE_CONTENT_MASTER_HIST
(
    P_NOTICE_ID       VARCHAR2
  , P_LANGUAGE        VARCHAR2
  , P_TITLE           VARCHAR2
  , P_CONTENT         VARCHAR2
  , P_CREATED_BY      VARCHAR2
  , P_CREATION_DATE   VARCHAR2
  , P_LAST_UPDATED_BY VARCHAR2
)
/*
 * Program ID   : PR_SCM_ADM_NOTICE_CONTENT_MASTER_HIST
 * Description  : NOTICE Message History
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2018.02.22   ygkim      Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 * 2026.07.06   ZIONEX   [PJ202650304] NextSCM Migration
 *
 */
AS
    N_HISTORY_SEQ   INTEGER;

    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME  VARCHAR2(150 CHAR) := $$PLSQL_UNIT;
    V_LOG_TYPE      VARCHAR2(30 CHAR); /* START/END/ERROR/... */
    N_LOG_COUNT     INTEGER := 0;
    V_LOG_MESSAGE   VARCHAR2(1000 CHAR);
    V_DESCRIPTION   VARCHAR2(500 CHAR);
    D_EVENT_DATE    DATE;
    V_IN_PARA_DATA  VARCHAR2(4000 CHAR);

    V_PROC_INPUT    VARCHAR2(4000 CHAR);
    V_BACKTRACE     VARCHAR2(4000 CHAR);
    V_SQL_CODE      VARCHAR2(100 CHAR);
    V_SQL_ERRMSG    VARCHAR2(1000 CHAR);
BEGIN

    IF UTL_CALL_STACK.SUBPROGRAM(1).COUNT > 1 THEN
        V_PROGRAM_NAME := $$PLSQL_UNIT || '.' || UTL_CALL_STACK.SUBPROGRAM(1) (2);
    END IF;

    V_IN_PARA_DATA := JSON_OBJECT('P_NOTICE_ID' VALUE P_NOTICE_ID
                                 ,'P_LANGUAGE' VALUE P_LANGUAGE
                                 ,'P_TITLE' VALUE P_TITLE
                                 ,'P_CONTENT' VALUE P_CONTENT
                                 ,'P_CREATED_BY' VALUE P_CREATED_BY
                                 ,'P_CREATION_DATE' VALUE P_CREATION_DATE
                                 ,'P_LAST_UPDATED_BY' VALUE P_LAST_UPDATED_BY
                                  RETURNING VARCHAR2(4000 CHAR));

    /* 시작 LOG */
    V_LOG_TYPE := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := NULL;
    D_EVENT_DATE := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    BEGIN
        SELECT SEQ1_SCM_ADM_NOTICE_CONTENT_MASTER_H.NEXTVAL
          INTO N_HISTORY_SEQ
          FROM DUAL;

        BEGIN
            INSERT
              INTO SCM_ADM_NOTICE_CONTENT_MASTER_H
                 ( HISTORY_SEQ
                 , NOTICE_ID
                 , LANGUAGE_CODE
                 , NOTICE_TITLE
                 , NOTICE_CONTENT
                 , CREATED_BY
                 , CREATION_DATE
                 , LAST_UPDATED_BY
                 , LAST_UPDATE_DATE )
            VALUES ( N_HISTORY_SEQ
                   , P_NOTICE_ID
                   , P_LANGUAGE
                   , P_TITLE
                   , P_CONTENT
                   , P_CREATED_BY
                   , P_CREATION_DATE
                   , P_LAST_UPDATED_BY
                   , SYSDATE );
        END;
    END;


    V_LOG_TYPE := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := NULL;
    D_EVENT_DATE := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME
                            ,'ERROR'
                            ,0
                            ,SQLERRM
                            ,NULL
                            ,SYSDATE
                            ,P_IN_PARA_DATA  => V_IN_PARA_DATA
                            ,P_SQL_ERR_CODE  => SQLCODE
                            ,P_SQL_ERR_MSG   => SQLERRM
                            ,P_SQL_BACKTRACE => DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);

END;

