PROCEDURE           "PR_SCM_ADM_SAVE_UPLOAD_DATA"
(
    P_PROGRAM_ID VARCHAR2
   ,P_SHEET_NAME VARCHAR2
   ,P_CREATED_BY VARCHAR2
)
/*
 * Program ID   : PR_SCM_ADM_SAVE_UPLOAD_DATA
 * Description  : PSI UPLOAD DATA
 * Program History
 *===========================================================================================================
 *   Date       In Charge      Description
 *===========================================================================================================
 * 2017. 12. 15    SongDH     Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 *
 * 2026.07.06   ZIONEX   [PJ202650304] NextSCM Migration
 */
AS
    V_PROGRAM_NAME VARCHAR2(200 CHAR) := $$PLSQL_UNIT;
    V_SQL_TEXT     VARCHAR2(4000 CHAR);
    V_IN_PARA_DATA VARCHAR2(4000 CHAR);
    V_O_RC1        SYS_REFCURSOR;
BEGIN

    IF UTL_CALL_STACK.SUBPROGRAM(1).COUNT > 1 THEN
        V_PROGRAM_NAME := $$PLSQL_UNIT || '.' || UTL_CALL_STACK.SUBPROGRAM(1) (2);
    END IF;

    V_IN_PARA_DATA := JSON_OBJECT('p_program_id' VALUE P_PROGRAM_ID, 'p_sheet_name' VALUE P_SHEET_NAME, 'p_created_by' VALUE P_CREATED_BY);

    V_SQL_TEXT := NULL;

    BEGIN
        SELECT Z.OK
          INTO V_SQL_TEXT
          FROM (SELECT A.STORAGE_SQL_ID AS OK
                       /* A.STORAGE_SQL_ID + '(0.' + @v_created_by +')' AS OK */
                  FROM SCM_ADM_EXCEL_COLUMNS A
                 WHERE 1 = 1
                   AND A.PROGRAM_ID = P_PROGRAM_ID
                   AND A.SHEET_NAME = P_SHEET_NAME) Z;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            V_SQL_TEXT := NULL;
    END;

    EXECUTE IMMEDIATE 'BEGIN ' || V_SQL_TEXT || '(:1, :2, :3); END;'
        USING IN '1', IN P_CREATED_BY, OUT V_O_RC1;
    /* EXEC SP_EXECUTESQL @v_sql_text; */

    COMMIT;

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME
                            ,'ERROR'
                            ,0
                            ,SQLERRM
                            ,NULL
                            ,SYSDATE
                            ,P_IN_PARA_DATA  => V_IN_PARA_DATA
                            ,P_SQL_ERR_CODE  => SQLCODE
                            ,P_SQL_ERR_MSG   => SQLERRM
                            ,P_SQL_BACKTRACE => DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
        RAISE_APPLICATION_ERROR(-20001
                               ,'[' || V_PROGRAM_NAME || '] SQLCODE=' || SQLCODE || ' / SQLERRM=' || SQLERRM || ' / BACKTRACE=' ||
                                DBMS_UTILITY.FORMAT_ERROR_BACKTRACE || ' / PARAMS=' || V_IN_PARA_DATA);

END;

PROCEDURE           "PR_SCM_ADM_SAVE_UPLOAD_TEMP" 
(
    P_PROGRAM_ID      IN  VARCHAR2  /* NVARCHAR(MAX)  DMF0009^DMF0012^DMF0010 */
  , P_SHEET_NAME      IN  VARCHAR2  /* NVARCHAR(MAX)  sss^sss^sss */
  , P_COLUMN_VALUES   IN  VARCHAR2  /* NVARCHAR(MAX)  site|itemid|12|11|22|33|^... */
  , P_CREATED_BY      IN  VARCHAR2
  , O_RESULT_CURSOR   OUT SYS_REFCURSOR
)
/*
 * Program ID   : PR_SCM_ADM_SAVE_UPLOAD_TEMP
 * Description  : PSI UPLOAD SAVE
 * Program History
 *===========================================================================================================
 *   Date       In Charge      Description
 *===========================================================================================================
 * 2018.01.02   SongDH     Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 * 2019.01.11   hwyoon     한글깨짐 수정
 * 2023.08.02   chkim.68   DataTable (UpdateBatch) 방식 Excel Upload의 경우, Upload 데이터 무시, Validation만 실시
 * 2026.07.06   ZIONEX     [PJ202650304] NextSCM Migration
 *
 */
IS
    V_PROGRAM_ID          VARCHAR2(4000 CHAR);
    V_SHEET_NAME          VARCHAR2(4000 CHAR);
    V_COLUMN_VALUES       VARCHAR2(4000 CHAR);
    V_COLUMN_DTL_VALUES   VARCHAR2(4000 CHAR);
    V_CREATED_BY          VARCHAR2(4000 CHAR);

    V_SQL                 VARCHAR2(32767 CHAR);
    V_COLUMNS             VARCHAR2(32767 CHAR);
    V_VALUES              VARCHAR2(32767 CHAR);
    V_SYSDATE             VARCHAR2(40 CHAR);

    V_SQL_TEXT            VARCHAR2(32767 CHAR);
    V_PROCEDURE           VARCHAR2(150 CHAR);
    V_CREATION_DATE       VARCHAR2(40 CHAR);

    V_DELIMITER           VARCHAR2(1 CHAR) := '^';   /* 데이터 구분자 */
    V_DELIMITER1          VARCHAR2(1 CHAR) := '|';   /* 데이터 구분자1 */

    MAX_LOOP_CNT          PLS_INTEGER := 0;
    MST_LOOP_CNT          PLS_INTEGER := 0;
    DTL_LOOP_CNT          PLS_INTEGER := 0;
    DTL_SUB_LOOP_CNT      PLS_INTEGER := 0;

    RECV_ACTIVE_FLAG      VARCHAR2(4000 CHAR);
    RECV_DTL_ACTIVE_FLAG  VARCHAR2(4000 CHAR);

    N_UPD_SEQ             PLS_INTEGER := 0;

    /* 결과 커서(하위 Validation 프로시저 반환) 처리용 */
    V_RESULT_CURSOR       SYS_REFCURSOR;
    V_REC_CODE            VARCHAR2(200  CHAR);
    V_REC_MSG             VARCHAR2(1000 CHAR);
    V_REC_EVENT           VARCHAR2(4000 CHAR);


    V_LOG_TYPE            VARCHAR2(100  CHAR);
    V_LOG_MESSAGE         VARCHAR2(4000 CHAR);
    V_DESCRIPTION         VARCHAR2(4000 CHAR);
    N_LOG_COUNT           PLS_INTEGER  := 0;
    D_EVENT_DATE          DATE         := SYSDATE;
    V_PROC_INPUT          VARCHAR2(4000 CHAR);
    V_SQL_CODE            VARCHAR2(100  CHAR);
    V_SQL_ERRMSG          VARCHAR2(1000 CHAR);
    V_BACKTRACE           VARCHAR2(4000 CHAR);
BEGIN

    V_PROGRAM_ID         := NULL;
    V_SHEET_NAME         := NULL;
    V_COLUMN_VALUES      := NULL;
    V_COLUMN_DTL_VALUES  := NULL;
    V_CREATED_BY         := NULL;

    V_SQL                := NULL;
    V_COLUMNS            := NULL;
    V_VALUES             := NULL;
    V_SYSDATE            := NULL;
    V_SQL_TEXT           := NULL;

    RECV_ACTIVE_FLAG     := P_PROGRAM_ID;
    RECV_DTL_ACTIVE_FLAG := NULL;

    /* 프로시저 LOOP 길이를 판단 */
    MAX_LOOP_CNT := SCM_ARR_SPL_CNT(P_PROGRAM_ID, V_DELIMITER);
    V_SYSDATE    := TO_CHAR(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS');

    /* TABLE TYPE UPLOAD인 경우 대응 (원본: IF ISNULL(@p_column_values,'') <> 'TABLEUPLOAD') */
    IF P_COLUMN_VALUES IS NOT NULL AND P_COLUMN_VALUES <> 'TABLEUPLOAD' THEN

        WHILE LENGTH(RECV_ACTIVE_FLAG) > 0 AND MST_LOOP_CNT < MAX_LOOP_CNT
        LOOP

            /* MST_LOOP_CNT 1증가 */
            MST_LOOP_CNT := MST_LOOP_CNT + 1;

            RECV_DTL_ACTIVE_FLAG := NULL;
            RECV_DTL_ACTIVE_FLAG := V_PROGRAM_ID;

            /* 각 컬럼들에 대한 스플릿처리로직 스타트 */
            BEGIN

                V_PROGRAM_ID    := SCM_ARR_SPL_VAL(P_PROGRAM_ID,    V_DELIMITER, MST_LOOP_CNT);
                V_SHEET_NAME    := SCM_ARR_SPL_VAL(P_SHEET_NAME,    V_DELIMITER, MST_LOOP_CNT);
                V_COLUMN_VALUES := SCM_ARR_SPL_VAL(P_COLUMN_VALUES, V_DELIMITER, MST_LOOP_CNT);
                V_CREATED_BY    := SCM_ARR_SPL_VAL(P_CREATED_BY,    V_DELIMITER, MST_LOOP_CNT);

                BEGIN

                    N_UPD_SEQ := SEQ1_SCM_ADM_EXCEL_UPLOAD.NEXTVAL;

                    V_COLUMNS := 'UPLOAD_ID,PROGRAM_ID,SHEET_NAME,UPLOAD_STATUS_CODE,CREATION_DATE,LAST_UPDATE_DATE,CREATED_BY,LAST_UPDATED_BY';

                    /* 원본 CONVERT(CHAR(19),CURRENT_TIMESTAMP,120) 문자열을 DATE 컬럼(CREATION_DATE/LAST_UPDATE_DATE)에 넣기 위해 TO_DATE 로 변환 */
                    V_VALUES := TO_CHAR(N_UPD_SEQ)
                             || ',''' || V_PROGRAM_ID
                             || ''',''' || V_SHEET_NAME
                             || ''',''UPLOAD'
                             || ''',TO_DATE(''' || V_SYSDATE || ''',''YYYY-MM-DD HH24:MI:SS'')'
                             ||   ',TO_DATE(''' || V_SYSDATE || ''',''YYYY-MM-DD HH24:MI:SS'')'
                             ||   ',''' || V_CREATED_BY
                             || ''',''' || V_CREATED_BY
                             ;

                    /* 프로시저 LOOP 길이를 판단   -- sdfjshd^1|2|3|^~~ */
                    DTL_LOOP_CNT := SCM_ARR_SPL_CNT(V_COLUMN_VALUES, V_DELIMITER1);

                    WHILE DTL_SUB_LOOP_CNT < DTL_LOOP_CNT
                    LOOP

                        /* DTL_SUB_LOOP_CNT 1증가 */
                        DTL_SUB_LOOP_CNT := DTL_SUB_LOOP_CNT + 1;

                        V_COLUMN_DTL_VALUES := SCM_ARR_SPL_VAL(V_COLUMN_VALUES, V_DELIMITER1, DTL_SUB_LOOP_CNT);

                        V_COLUMNS := V_COLUMNS || ',ATTRIBUTE' || TO_CHAR(DTL_SUB_LOOP_CNT);

                        V_VALUES  := V_VALUES || ''',''' || V_COLUMN_DTL_VALUES;

                    END LOOP;

                    DTL_SUB_LOOP_CNT := 0;

                END;

                BEGIN

                    V_SQL := 'INSERT INTO SCM_ADM_EXCEL_UPLOAD (' || V_COLUMNS || ') VALUES (' || V_VALUES || ''')';

                    /*                       INSERT INTO SCM_ADM_EXCEL_UPLOAD (UPLOAD_ID,PROGRAM_ID,SHEET_NAME,UPLOAD_STATUS_CODE,CREATION_DATE,LAST_UPDATE_DATE,CREATED_BY,LAST_UPDATED_BY,ATTRIBUTE1,ATTRIBUTE2)
                       VALUES (70,'DMF0009','sss1','UPLOAD',TO_DATE('2018-01-05 21:14:18','YYYY-MM-DD HH24:MI:SS'),TO_DATE('2018-01-05 21:14:18','YYYY-MM-DD HH24:MI:SS'),'OKAniel','OKAniel','site','itemid') */

                    EXECUTE IMMEDIATE V_SQL;

                END;

            END;

        END LOOP;

    ELSE
        BEGIN

            V_PROGRAM_ID  := P_PROGRAM_ID;
            V_SHEET_NAME  := P_SHEET_NAME;
            V_CREATED_BY  := P_CREATED_BY;
        END;
    END IF;

    /*----------------------------------------------------------------------------------
     *   -- BEGIN TRAN / COMMIT WORK / BEGIN TRY..END TRY / BEGIN CATCH..END CATCH
     *   -- CATCH: ERROR LOG VALUE SAVE / ROLLBACK TRANSACTION / 에러메시지 DISPLAY
     *---------------------------------------------------------------------------------- */

    BEGIN
        /* yyyymmddhh24miss */
        V_CREATION_DATE := TO_CHAR(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS');

        /* PROGRAM_ID / SHEET_NAME 에 매핑된 실행 대상(Validation) 프로시저명 조회 (원본 STORAGE_SQL_ID, WITH(NOLOCK) 제거) */
        SELECT Z.OK
          INTO V_SQL_TEXT
          FROM (SELECT A.STORAGE_SQL_ID AS OK
                  FROM SCM_ADM_EXCEL_COLUMNS A
                 WHERE 1 = 1
                   AND A.PROGRAM_ID = V_PROGRAM_ID
                   AND A.SHEET_NAME = V_SHEET_NAME) Z;

        /* 원본 EXEC @v_sql_text '0', @v_created_by 를 동적 프로시저 호출로 변환. */
        EXECUTE IMMEDIATE 'BEGIN ' || V_SQL_TEXT || '(:p1, :p2, :p3); END;'
            USING '0', V_CREATED_BY, V_RESULT_CURSOR;


        LOOP
            FETCH V_RESULT_CURSOR INTO V_REC_CODE, V_REC_MSG, V_REC_EVENT;
            EXIT WHEN V_RESULT_CURSOR%NOTFOUND;
        END LOOP;

        CLOSE V_RESULT_CURSOR;

        IF V_REC_CODE <> '0' THEN

            ROLLBACK;
            V_LOG_TYPE    := 'END';
            V_LOG_MESSAGE := '########## END of procedure ##########';
            V_DESCRIPTION := V_REC_EVENT;
            D_EVENT_DATE  := SYSDATE;
            PR_SCM_SYS_LOG_BATCH($$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

            OPEN O_RESULT_CURSOR FOR
            SELECT '-1'                                          AS CODE
                 , 'ERR_RTN: - Validation Check - ' || V_SQL_TEXT AS MSG
                 , V_REC_EVENT                                    AS EVENT
              FROM DUAL;
            RETURN;
        END IF;

    END;

    N_LOG_COUNT := SQL%ROWCOUNT;

    COMMIT;

    OPEN O_RESULT_CURSOR FOR
    SELECT '0'                  AS CODE
         , 'SUCCESS'            AS MSG
         , TO_CHAR(N_LOG_COUNT) AS EVENT
      FROM DUAL;

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;

        V_LOG_TYPE    := 'ERROR';
        V_LOG_MESSAGE := 'EXCEPTION';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        V_SQL_CODE    := TO_CHAR(SQLCODE);
        V_SQL_ERRMSG  := SQLERRM;
        V_PROC_INPUT  := JSON_OBJECT(
            'P_PROGRAM_ID'    VALUE P_PROGRAM_ID
          , 'P_SHEET_NAME'    VALUE P_SHEET_NAME
          , 'P_COLUMN_VALUES' VALUE P_COLUMN_VALUES
          , 'P_CREATED_BY'    VALUE P_CREATED_BY
        );
        V_BACKTRACE   := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;

        PR_SCM_SYS_LOG_BATCH(
            $$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE
          , V_DESCRIPTION, D_EVENT_DATE, V_PROC_INPUT
          , V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE
        );

        RAISE_APPLICATION_ERROR(-20001
          , '[' || $$PLSQL_UNIT || '] SQLCODE=' || V_SQL_CODE ||
            ' / SQLERRM=' || V_SQL_ERRMSG ||
            ' / PARAMS=' || V_PROC_INPUT
        );

END PR_SCM_ADM_SAVE_UPLOAD_TEMP;

PROCEDURE PR_SCM_DNM_FP_RELEASE_PROD_PLAN_C
/*
 * Program ID   : PR_SCM_DNM_FP_RELEASE_PROD_PLAN_C
 * Description  : FP 생산 계획 Cutoff 프로시져
 *              : 매주 화요일 동기화
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2018. 4.26    Kim Jaejung   Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 * 2018. 5.15    Kim Jihye     creation_date, update_date 프로시저 수행 일자로 변경
 * 2019.07.09    KSG           [CSR ID:4034546] GSCM 계획 수립 시점 별 FP Version 조회가능 UI 개발 요청 : Plan Version 저장 작업 Call 추가
 *
 * 2026-07-30   ZIONEX   [PJ202650304]  NextSCM Migration
 */
AS


    /* LOG 용 변수 설정 */
    V_BATCH_USER       VARCHAR2(150 CHAR) := 'scm_batch';
    V_PROGRAM_NAME     VARCHAR2(150 CHAR) := 'PR_SCM_DNM_FP_RELEASE_PROD_PLAN_C';
    V_LOG_TYPE         VARCHAR2(30 CHAR);            /* START/END/ERROR/... */
    N_LOG_COUNT        INTEGER := 0;
    V_LOG_MESSAGE      VARCHAR2(1000 CHAR);
    V_DESCRIPTION      VARCHAR2(500 CHAR);
    D_EVENT_DATE       DATE;
    V_IFSEQNO          VARCHAR2(30 CHAR);
    N_HISTORY_SEQ      NUMBER(19);
    V_BASIS_START_DATE VARCHAR2(8 CHAR);
    V_DEL_YYYYMMDD     VARCHAR2(8 CHAR) := '';       /* Delete 기준 일자 */


    V_PROC_INPUT       VARCHAR2(4000 CHAR);
    V_SQL_CODE         VARCHAR2(100 CHAR);
    V_SQL_ERRMSG       VARCHAR2(1000 CHAR);
    V_BACKTRACE        VARCHAR2(4000 CHAR);
BEGIN

    /*       FN_NEXT_DAY 는 Oracle 에서도 DATE in / DATE out (ALL_ARGUMENTS 실측) 이라 래핑 불요. */
    V_DEL_YYYYMMDD := TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') + (-7 * 13), 'YYYYMMDD');  /* 12주 전 월요일 일자 */

    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;

    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    BEGIN


        BEGIN
            SELECT /* PR_SCM_DNM_FP_RELEASE_PROD_PLAN_C */
                   BASIS_YYYYMMDD
              INTO V_BASIS_START_DATE
              FROM SCM_SYS_CALENDAR_M CM
             WHERE ISO_YYYYWW IN (SELECT ISO_YYYYWW
                                    FROM SCM_SYS_CALENDAR_M
                                   WHERE BASIS_YYYYMMDD = TO_CHAR(SYSDATE, 'YYYYMMDD'))
               AND DAYOFWEEK = 'MON';
        EXCEPTION
            WHEN NO_DATA_FOUND THEN NULL;
        END;

        /* ------------------------------------------------
           Plan Cutoff 작업
           ------------------------------------------------ */
        DELETE /* PR_SCM_DNM_FP_RELEASE_PROD_PLAN_C */
          FROM SCM_DNM_FP_RELEASE_PROD_PLAN_C
         WHERE YYYYMMDD = V_BASIS_START_DATE;

        INSERT /* PR_SCM_DNM_FP_RELEASE_PROD_PLAN_C */
          INTO SCM_DNM_FP_RELEASE_PROD_PLAN_C
             ( YYYYMMDD
             , COMPANY_ID
             , DIVISION_ID
             , SCM_SITE_ID
             , PLANT_ID
             , FACTORY_ID
             , OPERATION_ID
             , LOCATION
             , TOP_ITEM_ID
             , ITEM_ID
             , PRODUCTION_TYPE
             , MARKET
             , LINE_ID
             , ELECTRODE_TYPE
             , PLAN_DATE
             , PLAN_QTY
             , PLAN_IN_QTY
             , EQUIPMENT_ID
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE )
        SELECT V_BASIS_START_DATE
             , COMPANY_ID
             , DIVISION_ID
             , SCM_SITE_ID
             , PLANT_ID
             , FACTORY_ID
             , OPERATION_ID
             , LOCATION
             , TOP_ITEM_ID
             , ITEM_ID
             , FP_PRODUCTION_TYPE
             , MARKET
             , LINE_ID
             , ELECTRODE_TYPE
             , PLAN_DATE
             , PLAN_QTY
             , PLAN_IN_QTY
             , EQUIPMENT_ID
             , V_BATCH_USER
             , SYSDATE                  /* 2018. 5. 15    Kim Jihye */
             , V_BATCH_USER
             , SYSDATE
          FROM SCM_DNM_PLAN_FROZEN_V
         WHERE PLAN_DATE >= TO_DATE(V_BASIS_START_DATE || ' 00:00:00', 'YYYYMMDD HH24:MI:SS');

    EXCEPTION
        WHEN OTHERS THEN

            ROLLBACK;

            /* ERROR LOG (로깅 10인자 표준: 에러경로 진단 4값 채움) */
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := SUBSTR('ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE || ' : ' || V_BASIS_START_DATE, 1, 500);
            D_EVENT_DATE  := SYSDATE;
            V_PROC_INPUT  := NULL;
            V_SQL_CODE    := TO_CHAR(SQLCODE);
            V_SQL_ERRMSG  := SQLERRM;
            V_BACKTRACE   := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;

            PR_SCM_SYS_LOG_BATCH(
                V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE
              , V_DESCRIPTION, D_EVENT_DATE, V_PROC_INPUT
              , V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE);
    END;

    /* ------------------------------------------------
       1. Plan Version 저장 작업 Call : 20190709
       2. 과거 정보 삭제
         위치 조정하지 말 것 : 오류 발생해도 Plan Cutoff 작업은 정상 종료되어야 함
       ------------------------------------------------ */
    PR_SCM_MST_PLAN_FP_RELEASE_ID(V_BASIS_START_DATE, NULL, NULL, NULL, 'PR', NULL);

    DELETE /* PR_SCM_DNM_FP_RELEASE_PROD_PLAN_C */
      FROM SCM_DNM_FP_RELEASE_PROD_PLAN_C
     WHERE YYYYMMDD < V_DEL_YYYYMMDD;

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);


    COMMIT;

END PR_SCM_DNM_FP_RELEASE_PROD_PLAN_C;

PROCEDURE PR_SCM_DNM_LOSS_MMLY
