 *
 *				 - Target : SCM_DNM_LOSS_EQP_MMLY (설비별)
 *				            SCM_DNM_LOSS_LN_MMLY  (라인별)
 *				            SCM_DNM_LOSS_MDL_MMLY (모델별)
 *
 *				 - 조립 Cell 모델에 대한 실적만 대상으로 함 (pack과 전극은 대상 아님- 팩은 실적이 없음?)
 *
 * Program History
 *===================================================================================================
 *   Date      In Charge	Description
 *===================================================================================================
 * 2024.02.27	hrkim		Initial Release PJ20230692 SCM 역량 강화 위한 SCP 개선과제 이행 Phase2
 * 2024.04.05	hrkim		투입실적 참조 테이블 변경 XIF_DW_PRD_INPUT_DAILY_YLD_R_SN -> SCM_DNM_INPT_PRDN_DDLY
 * 2024.04.09	hrkim		조업율이 0%인경우(비조업100%) 부하/가동 100%로 맞춤.
 *							변상현 책임 : 비부하/비가동이 실적에서 Loss 시간의 % 를 1-XX% 로 부하율/시간가동율로 만드는 로직이니 일단 100% 로 맞춰주세요~!
 * 2024.04.19	hrkim		라인별 양품가동률 추가
 * 2024.04.24	hrkim		DW Loss Time 실적 IF 수신 데이터 중복데이터 필터링
 * 2024.04.29	hrkim		생산가동률/TEEP 추가
 * 2024.04.29	hrkim		전극라인유형코드값 로직 수정 (FP설비 Master Product_Leve3_Code참조)
 * 2024.05.13	hrkim		전극라인유형코드 매핑시 lookup  추가 참조 (OPERATION_ELECTRODE_TYPE)
 * 2024.05.14	hrkim		기간참조구분에 따른 참조 범위 변경적용
 *							1 : loss_ym  해당월 1개월 참조
 *							3 : loss_ym 기준 M-2부터 M(loss_ym) 까지 참조
 * 2024.05.27	hrkim		소수 자릿수 처리 로직 보완 (연산:FLOAT, 저장:NUMERIC(20,10))
 * 2024.06.05	hrkim		성능가동률 계산시 적용되는 MMD설계속도 모델별데이터 라인별 집계시 투입수량 가중치 적용
 * 2024.08.14	hrkim		양품가동률 적재 기준 변경 - cell 환산 적용 안함.
 *							- 변경전 : CELL_GOOD_QTY / CELL_INPUT_QTY
 *							- 변경후 : OUT_GOOD_QTY / (OUT_DEFECT_QTY + OUT_GOOD_QTY)
 * 2024.08.26	hrkim		INPUT_QTY 0인 건도 포함 - 투입수량이 0인데 생산수량이 0이 아닌 데이터 존재.
 *							DW 투입실적 적용 수정
 * 2024.10.25	hrkim		PJ20239037 LGES CPS VOE 반영 및 고도화 : MMD 지표 예외 정보 적용
 * 2024.10.30	hrkim		PJ20239037 LGES CPS VOE 반영 및 고도화 : 설비별 loss 최대조업일수 정보 추가 (조업률.attribute1)
 * 2024.11.04	hrkim		PJ20239037 LGES CPS VOE 반영 및 고도화 : 성능가동률 100%으로 적재 (PI 변상현 책임)
 * 2024.12.15   vadabi3     NERP - 특정 Company 별도 처리 개선
 * 2025.03.21	hrkim		(NERP)DW 데이터 plant 조인 컬럼 변경 (plant_id -> mes_plant_id)
 * 2025.03.24	hrkim		PJ20249548R  LGES SCP역량 강화를 위한 기준정보PSI엔진 기능개선 : CPS 소형 확산
 *							- A3000/A9000 완성 공정만 대상으로 함
 * 2025.08.01   hrkim		PJ20257329 최적화 Planning Input Constraint UI 개발 및 Master Validation 확산 : Cell 완성 공정 하드코딩 변경
 * 2026.07.06   ZIONEX   [PJ202650304] NextSCM Migration
 */
    V_ESHM            VARCHAR2(8 CHAR);  /* G740 */
    V_LOSS_YM         VARCHAR2(6 CHAR) := P_LOSS_YM;
    V_PERD_DIVS_CD    NUMBER := P_PERD_DIVS_CD;
    V_LOSS_FROM_YMD   VARCHAR2(8 CHAR);
    V_LOSS_TO_YMD     VARCHAR2(8 CHAR);
    V_DD_SSN          NUMBER := 86400;  /* 1일 초수 */
    /* 2024.10.15 주석처리  declare @v_mm_ddn float  = datediff(dd, convert(date,@v_loss_from_ymd,112) , convert(date, @v_loss_to_ymd,112)) + 1 ;	-- 월(기간) 일수 */
    /* 2024.10.15 주석처리  declare @v_mm_ssn float  = null;	-- 월(기간) 초수 */
    /* 2024.10.15 주석처리  select  @v_mm_ssn = @v_mm_ddn * @v_dd_ssn ; -- 월(기간) 초수 (일수 * 1일초수) */
    V_START_TIME      DATE := SYSDATE;  /* 실행시간 확인용 */
    V_EXEC_TIME       VARCHAR2(10 CHAR) := '';  /* '[00:00]'; */
    V_SEC             NUMBER;
    V_PROGRAM_NAME    VARCHAR2(150 CHAR) := 'PR_SCM_DNM_LOSS_MMLY';  /* Proc별 이름 설정 */
    V_LOG_TYPE        VARCHAR2(30 CHAR);  /* START/END/ERROR/... */
    N_LOG_COUNT       INTEGER := 0;
    V_LOG_MESSAGE     VARCHAR2(1000 CHAR);
    V_DESCRIPTION     VARCHAR2(500 CHAR);
    D_EVENT_DATE      DATE;
    V_BATCH_USER      VARCHAR2(150 CHAR) := 'scm_batch';
    /* NUMERIC(20,10) -> VARCHAR2 저장 시 MSSQL 은 소수 10자리 문자열('nn.0000000000')로 적재 -> 동일 재현용 포맷 */
    C_FMT_N2010       CONSTANT VARCHAR2(30 CHAR) := 'FM9999999990.0000000000';
BEGIN

    /* ---------------------------------------------------------------------------------------------------------------- */


    /* ---------------------------------------------------------------------------------------------------------------- */
    DELETE FROM GT_SDLM_SCP_CELL_FINAL_OP;
    DELETE FROM GT_SDLM_LOSS_CODE;
    DELETE FROM GT_SDLM_OP_ELTR_TYPE_MAP;
    DELETE FROM GT_SDLM_EQP_PRDLVL3_CODE;
    DELETE FROM GT_SDLM_SCM_MST_EQUIPMENT_SN;
    DELETE FROM GT_SDLM_SCP_MST_MMD_KPI_EXCT;
    DELETE FROM GT_SDLM_LOSS_TIME_RAW_DATA;
    DELETE FROM GT_SDLM_LOSS_TIME_R_EQP_MMLY;
    DELETE FROM GT_SDLM_LOSS_TIME_RT_EQP_MMLY;
    DELETE FROM GT_SDLM_LOSS_TIME_R_LN_MMLY;
    DELETE FROM GT_SDLM_LOSS_TIME_RT_LN_MMLY;
    DELETE FROM GT_SDLM_SCP_MST_ITEM_BSI_IFO;
    DELETE FROM GT_SDLM_SCP_MST_ITEM_CELL_CF;
    DELETE FROM GT_SDLM_PRD_INPUT_EQP_R;
    DELETE FROM GT_SDLM_PIC_CONVERT_R;
    DELETE FROM GT_SDLM_PROD_INPUT_RESULT;
    DELETE FROM GT_SDLM_PIC_CONVERT_R_LN;
    DELETE FROM GT_SDLM_PROD_INPUT_RESULT_LN;
    DELETE FROM GT_SDLM_SCP_MST_MDL_EQP_SPED;
    DELETE FROM GT_SDLM_LOSS_RT_MDL_MMLY;

    V_ESHM := FN_GET_LOOKUP_VALUE('PR_SCM_DNM_LOSS_MMLY','ESHM');

    /* loss ym */
    IF V_LOSS_YM IS NULL OR LTRIM(RTRIM(V_LOSS_YM)) IS NULL THEN
        V_LOSS_YM := TO_CHAR(ADD_MONTHS(SYSDATE, -1), 'YYYYMM');  /* default M-1월 기준 적재 */
    END IF;

    /* 기간 구분코드 */
    IF V_PERD_DIVS_CD IS NULL OR V_PERD_DIVS_CD < 1 THEN
        V_PERD_DIVS_CD := 1;
    END IF;

    V_LOSS_FROM_YMD := TO_CHAR(ADD_MONTHS(TO_DATE(V_LOSS_YM || '01', 'YYYYMMDD'), -(V_PERD_DIVS_CD - 1)), 'YYYYMMDD');
    V_LOSS_TO_YMD   := TO_CHAR(ADD_MONTHS(TO_DATE(V_LOSS_YM || '01', 'YYYYMMDD'), 1) - 1, 'YYYYMMDD');

    DBMS_OUTPUT.PUT_LINE('----------------------------------------------------------------');
    DBMS_OUTPUT.PUT_LINE(' @p_loss_ym			: ' || P_LOSS_YM);
    DBMS_OUTPUT.PUT_LINE(' @v_loss_ym			: ' || V_LOSS_YM);
    DBMS_OUTPUT.PUT_LINE(' @p_perd_divs_cd		: ' || TO_CHAR(P_PERD_DIVS_CD));
    DBMS_OUTPUT.PUT_LINE(' @v_perd_divs_cd		: ' || TO_CHAR(V_PERD_DIVS_CD));
    DBMS_OUTPUT.PUT_LINE(' @v_loss_from_ymd	: ' || V_LOSS_FROM_YMD);
    DBMS_OUTPUT.PUT_LINE(' @v_loss_to_ymd		: ' || V_LOSS_TO_YMD);
    DBMS_OUTPUT.PUT_LINE(' @v_loss_to_ymd		: ' || V_LOSS_TO_YMD);
    DBMS_OUTPUT.PUT_LINE(' @v_dd_ssn			: ' || TO_CHAR(V_DD_SSN));
    /* 2024.10.15 주석처리  print ' @v_mm_ddn			: '	+ convert(nvarchar(20), @v_mm_ddn) */
    /* 2024.10.15 주석처리  print ' @v_mm_ssn			: '	+ convert(nvarchar(20), @v_mm_ssn) */
    DBMS_OUTPUT.PUT_LINE('----------------------------------------------------------------');

    /* ---------------------------------------------------------------------------------------------------------------- */
    /* [PJ20257329] Cell 완성 공정 하드 코딩 변경 (임시테이블 변수 셋팅) */
    DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' SCP Cell Final 공정 정보 - Cell Packaging/Assembly');
    /* ---------------------------------------------------------------------------------------------------------------- */
    INSERT INTO GT_SDLM_SCP_CELL_FINAL_OP
    SELECT SEGMENT1 AS OPERATION_ID
      FROM SCM_ADM_LOOKUP_MASTER_DETAIL LK
     WHERE 1 = 1
       AND LK.LOOKUP_TYPE = 'SCP_PLAN_OPERATION'
       AND LK.SEGMENT3    = 'A'  /* 공정그룹 (Cell) */
       AND LK.ATTRIBUTE1  = 'Y';  /* Final Operation */
    /* ---------------------------------------------------------------------------------------------------------------- */

    BEGIN

        /* 시작 LOG  (START) */
        V_LOG_TYPE    := 'START';
        V_LOG_MESSAGE := '##### Start of procedure #####';
        V_DESCRIPTION := '[81,82,JV][loss_ym=' || V_LOSS_YM || '][p_perd_divs_cd=' || TO_CHAR(P_PERD_DIVS_CD) || ']';
        D_EVENT_DATE  := SYSDATE;
        PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER);
        V_LOG_MESSAGE := NULL;

        /* ------------------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### Loss Code 정보 - #LOSS_CODE');
        /* ------------------------------------------------------------------------------------------------- */
        INSERT INTO GT_SDLM_LOSS_CODE
        SELECT SEGMENT1     AS LOSS_CD
              ,ATTRIBUTE1   AS LOSS_UNIT
              ,ATTRIBUTE2   AS DW_LOSS_CD
              ,ATTRIBUTE3   AS LOSS_GR_CD
              ,ATTRIBUTE4   AS LOSS_NM
              ,DISPLAY_SEQ  AS SEQ
              ,ATTRIBUTE4   AS LOSS_NM_KO
              ,ATTRIBUTE5   AS LOSS_NM_EN
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
         WHERE 1 = 1
           AND LOOKUP_TYPE = 'SCP_CAPA_LOSS_MEASURE'
           AND VALID_YN    = 'Y';

        /* --------------------------------------------------------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### 설비 Product Level3코드에 대한 전극라인유형코드 정보 - #OPERATION_ELECTRODE_TYPE_MAPPING');  /* 5/13  추가 */
        /* --------------------------------------------------------------------------------------------------------------------------------------- */
        INSERT INTO GT_SDLM_OP_ELTR_TYPE_MAP
        SELECT SEGMENT1        AS DIVISION_ID
              ,SEGMENT2        AS OPERATION_ID
              ,SEGMENT3        AS EQP_ID_4_3
              ,MAX(ATTRIBUTE1) AS ELTR_LN_TP_CD
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
         WHERE 1 = 1
           AND LOOKUP_TYPE = 'OPERATION_ELECTRODE_TYPE_MAPPING'
           AND VALID_YN = 'Y'
         GROUP BY SEGMENT1
                 ,SEGMENT2
                 ,SEGMENT3;

        /* --------------------------------------------------------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### 설비 Product Level3코드에 대한 전극라인유형코드 정보 - #EQUIPMENT_PRODUCT_LEVEL3_CODE');
        /* --------------------------------------------------------------------------------------------------------------------------------------- */
        INSERT INTO GT_SDLM_EQP_PRDLVL3_CODE
        SELECT SEGMENT1        AS OPERATION_ID
              ,SEGMENT2        AS EQP_PRODUCT_LEVEL3_CODE
              ,MAX(ATTRIBUTE1) AS ELTR_LN_TP_CD
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
         WHERE 1 = 1
           AND LOOKUP_TYPE = 'EQUIPMENT_PRODUCT_LEVEL3_CODE'
           AND VALID_YN = 'Y'
         GROUP BY SEGMENT1
                 ,SEGMENT2;

        /* ------------------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### FP 설비 Master - #SCM_MST_EQUIPMENT_SN');
        /* ------------------------------------------------------------------------------------------------- */
        INSERT INTO GT_SDLM_SCM_MST_EQUIPMENT_SN
        SELECT EM.COMPANY_ID
              ,EM.DIVISION_ID
              ,EM.SITE_ID
              ,EM.PLANT_ID
              ,EM.FACTORY_ID
              ,EM.EQUIPMENT_ID
              ,EM.OPERATION_ID
              ,EM.ELECTRODE_TYPE
              ,CASE  WHEN PL.ELTR_LN_TP_CD IS NOT NULL                                   THEN PL.ELTR_LN_TP_CD  /* lookup EQUIPMENT_PRODUCT_LEVEL3_CODE : FP설비Product Level3 코드 값에 따른 전극/라인유형 */
                     WHEN ET.ELTR_LN_TP_CD IS NOT NULL                                   THEN ET.ELTR_LN_TP_CD  /* lookup OPERATION_ELECTRODE_TYPE_MAPPING : A8000/A8400 설비ID 4번째 3자리에 대한 전극/라인유형 매핑 */
                     WHEN EM.OPERATION_ID = 'A7400' AND EM.ELECTRODE_TYPE = 'A'          THEN 'Anode'  /* CPM 기준 PPM계산시 전극수량 참조를 위함(UI참조 Lookup과 매핑을 위해서도). */
                     WHEN EM.OPERATION_ID = 'A7400' AND EM.ELECTRODE_TYPE = 'C'          THEN 'Cathode'  /* CPM 기준 PPM계산시 전극수량 참조를 위함(UI참조 Lookup과 매핑을 위해서도). */
                     WHEN EM.OPERATION_ID LIKE 'P%' OR  CO.OPERATION_ID IS NOT NULL      THEN '-'  /* [PJ20257329] Cell 완성 공정 하드 코딩 변경 */
                     /* [PJ20257329] 변경전 WHEN EM.OPERATION_ID like 'P%' OR  EM.OPERATION_ID = 'A9000' 		THEN '-' */
                     ELSE EM.ELECTRODE_TYPE
                END  AS ELTR_LN_TP_CD
              ,EM.LINE_ID
              ,FM.MES_PLANT_ID  /* 2025.03.21 추가 */
          FROM SCM_MST_EQUIPMENT_SN   EM
               INNER JOIN SCM_MST_DIVISION DM
                       ON DM.DIVISION_ID = EM.DIVISION_ID
                      AND DM.VALID_YN    = 'Y'
                      AND DM.ATTRIBUTE3  IN ('81', '82')  /* JV포함 */
               INNER JOIN SCM_MST_FACTORY_SN FM  /* 2025.03.21 추가 참조 */
                       ON FM.COMPANY_ID = EM.COMPANY_ID
                      AND FM.FACTORY_ID = EM.FACTORY_ID
               LEFT  JOIN GT_SDLM_EQP_PRDLVL3_CODE PL  /* 20240429 추가 */
                       ON PL.OPERATION_ID            = EM.OPERATION_ID
                      AND PL.EQP_PRODUCT_LEVEL3_CODE = EM.PRODUCT_LEVEL3_CODE
               LEFT  JOIN GT_SDLM_OP_ELTR_TYPE_MAP ET  /* A8000/A8400 공정에 대한 전극/라인 유형 매핑 */
                       ON ET.DIVISION_ID  = EM.DIVISION_ID
                      AND ET.OPERATION_ID = EM.OPERATION_ID
                      AND ET.EQP_ID_4_3   = SUBSTR(EM.EQUIPMENT_ID, 4, 3)
               /* [PJ20257329] Cell 완성 공정 하드 코딩 변경 -- Start */
               LEFT  JOIN GT_SDLM_SCP_CELL_FINAL_OP CO
                       ON CO.OPERATION_ID = EM.OPERATION_ID
               /* [PJ20257329] Cell 완성 공정 하드 코딩 변경 -- End */
         WHERE 1 = 1
           AND EM.EQUIPMENT_TYPE = 'M'  /* Main 설비 */
           AND EM.ACTIVE_FLAG    = 'Y'
           AND EM.OPERATION_ID   LIKE 'A%';  /* 셀만 */

        /* ------------------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### FP 설비 Master - #SCM_MST_EQUIPMENT_SN - 소형');
        /* 2025.03.24 PJ20249548R  LGES SCP역량 강화를 위한 기준정보PSI엔진 기능개선 : CPS 소형 확산 */
        /* 완성 공정만 대상으로 함 : 셀 : A3000, A9000 */
        /* ------------------------------------------------------------------------------------------------- */
        INSERT INTO GT_SDLM_SCM_MST_EQUIPMENT_SN
        SELECT EM.COMPANY_ID
              ,EM.DIVISION_ID
              ,EM.SITE_ID
              ,EM.PLANT_ID
              ,EM.FACTORY_ID
              ,EM.EQUIPMENT_ID
              ,EM.OPERATION_ID
              ,EM.ELECTRODE_TYPE
              ,'-'   AS ELTR_LN_TP_CD
              ,EM.LINE_ID
              ,FM.MES_PLANT_ID  /* 2025.03.21 추가 */
          FROM SCM_MST_EQUIPMENT_SN   EM
             , SCM_MST_DIVISION       DM
             , SCM_MST_FACTORY_SN     FM  /* 2025.03.21 추가 참조 */
             /* [PJ20257329] Cell 완성 공정 하드 코딩 변경 -- Start */
             , GT_SDLM_SCP_CELL_FINAL_OP CO
             /* [PJ20257329] Cell 완성 공정 하드 코딩 변경 -- End */
         WHERE DM.DIVISION_ID    = EM.DIVISION_ID
           AND FM.COMPANY_ID     = EM.COMPANY_ID
           AND FM.FACTORY_ID     = EM.FACTORY_ID
           AND CO.OPERATION_ID   = EM.OPERATION_ID
           AND DM.VALID_YN       = 'Y'
           AND DM.ATTRIBUTE3     = '40'  /* 소형 */
           AND EM.EQUIPMENT_TYPE = 'M'  /* Main 설비 */
           AND EM.ACTIVE_FLAG    = 'Y';
           /* [PJ20257329] 변경전 AND EM.OPERATION_ID    IN ('A3000', 'A9000') --- LIKE 'A%'	-- 셀만 */

        /* --------------------------------------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### MMD 지표 예외 정보 ');
        /* --------------------------------------------------------------------------------------------------------------------- */
        INSERT INTO GT_SDLM_SCP_MST_MMD_KPI_EXCT
        SELECT FACTORY_ID
              ,LINE_ID
              ,OPERATION_ID
              ,EQUIPMENT_ID  AS EQP_ID
              ,FROM_DATE
              ,TO_DATE
          FROM SCP_MST_MMD_KPI_EXCT KE
         WHERE 1 = 1
           AND KE.VALID_YN = 'Y'
           AND KE.KPI_TYPE = 'OEE';

        /* ------------------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### dw loss time 실적 rawdata - #LOSS_TIME_RAW_DATA');
        /* ------------------------------------------------------------------------------------------------- */
        INSERT INTO GT_SDLM_LOSS_TIME_RAW_DATA
        SELECT R.SITE_ID
              ,R.PLANT_ID
              ,R.AREA_ID     AS FACTORY_ID
              ,R.LINE_ID
              ,R.PROCESS_ID  AS OPERATION_ID
              ,R.EQPT_ID     AS EQP_ID
              ,M.LOSS_CD
              ,R.WORK_DATE  /* 2024.10.15 추가 for MMD 지표 예외 정보 적용 */
              ,TO_NUMBER(REPLACE(R.LOSS_TIME, 'null', '0'))  AS LOSS_TIME
              ,TO_NUMBER(REPLACE(R.LOSS_CNT,  'null', '0'))  AS LOSS_CNT
              ,M.LOSS_GR_CD
              ,ROW_NUMBER() OVER (PARTITION BY R.SITE_ID, R.PLANT_ID, R.AREA_ID, R.LINE_ID, R.PROCESS_ID, R.EQPT_ID, M.LOSS_CD, R.WORK_DATE
                                      ORDER BY R.SORT_ORDER, R.CREATE_DATE DESC ) AS RN  /* 20240424 FP 프로시저 PR_XIF_DW_LOSS_TIME_R 참조 (중복 수신데이터를 거르기 위함) */
          FROM XIF_DW_RECEIVE_LOSS_TIME_R_SN R
             , GT_SDLM_LOSS_CODE M
         WHERE M.DW_LOSS_CD = R.MEASURE_CODE
           AND R.WORK_DATE BETWEEN V_LOSS_FROM_YMD AND V_LOSS_TO_YMD
           AND R.PROCESS_ID LIKE 'A%';  /* Cell */

        /* -------------------------------------------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### dw loss time 실적 rawdata - #LOSS_TIME_RAW_DATA - 중복 데이터 삭제');
        /* -------------------------------------------------------------------------------------------------------------------------- */
        DELETE FROM GT_SDLM_LOSS_TIME_RAW_DATA R
         WHERE R.RN != 1;  /* 20240424 중복 수신데이터가 존재할시 최종?데이터로 필터링(우선순위 FP 프로시저 참조) */

        /* -------------------------------------------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### dw loss time 실적 rawdata - #LOSS_TIME_RAW_DATA - MMD 지표 예외데이터 삭제');
        /* -------------------------------------------------------------------------------------------------------------------------- */
        DELETE FROM GT_SDLM_LOSS_TIME_RAW_DATA R
         WHERE 1 = 1
           AND EXISTS (SELECT 1  /* 2024.10.17 MMD 지표예외 대상 제외 */
                         FROM GT_SDLM_SCP_MST_MMD_KPI_EXCT KE
                        WHERE 1 = 1
                          AND (KE.EQP_ID = R.EQP_ID OR KE.EQP_ID = 'ALL')
                          AND KE.FACTORY_ID   = R.FACTORY_ID
                          AND KE.LINE_ID      = R.LINE_ID
                          AND KE.OPERATION_ID = R.OPERATION_ID
                          AND R.WORK_DATE BETWEEN KE.FROM_DATE
                                              AND KE.TO_DATE
                          );

        /* ------------------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### Loss Time 설비별 집계 - #LOSS_TIME_R_EQP_MMLY');
        /* ------------------------------------------------------------------------------------------------- */
        INSERT INTO GT_SDLM_LOSS_TIME_R_EQP_MMLY
        SELECT E.COMPANY_ID
              ,E.DIVISION_ID
              ,R.SITE_ID
              ,E.PLANT_ID  /* 2025.03.21 r.plant_id -> e.plant_id */
              ,R.FACTORY_ID
              ,R.LINE_ID
              ,R.OPERATION_ID
              ,R.EQP_ID
              ,E.ELTR_LN_TP_CD
              ,CAST(R.LOSS_CD AS VARCHAR2(30 CHAR))                    AS LOSS_CD
              ,R.LOSS_GR_CD
              ,COUNT(DISTINCT R.WORK_DATE)                             AS MM_DAYS  /* 2024.10.15 추가 for MMD 지표 예외 정보 적용 */
              ,COUNT(DISTINCT R.WORK_DATE) * V_DD_SSN                  AS MM_SSN  /* 2024.10.15 추가 for MMD 지표 예외 정보 적용 */
              ,SUM(LOSS_CNT)                                           AS LOSS_CNT
              ,SUM(LOSS_TIME)                                          AS LOSS_TM_SSN
              ,SUM(CASE WHEN R.LOSS_GR_CD = 'NAV' THEN SUM(LOSS_TIME) ELSE 0 END)
                       OVER (PARTITION BY E.COMPANY_ID, E.DIVISION_ID, R.SITE_ID, R.FACTORY_ID, R.LINE_ID, R.OPERATION_ID, R.EQP_ID, E.ELTR_LN_TP_CD) AS NAV_TOT_LOSS_TM  /* 비조업 */
              ,SUM(CASE WHEN R.LOSS_GR_CD = 'NLD' THEN SUM(LOSS_TIME) ELSE 0 END)
                       OVER (PARTITION BY E.COMPANY_ID, E.DIVISION_ID, R.SITE_ID, R.FACTORY_ID, R.LINE_ID, R.OPERATION_ID, R.EQP_ID, E.ELTR_LN_TP_CD) AS NLD_TOT_LOSS_TM  /* 비부하 */
              ,SUM(CASE WHEN R.LOSS_GR_CD = 'NOP' THEN SUM(LOSS_TIME) ELSE 0 END)
                       OVER (PARTITION BY E.COMPANY_ID, E.DIVISION_ID, R.SITE_ID, R.FACTORY_ID, R.LINE_ID, R.OPERATION_ID, R.EQP_ID, E.ELTR_LN_TP_CD) AS NOP_TOT_LOSS_TM  /* 비가동 */
          FROM GT_SDLM_LOSS_TIME_RAW_DATA R
             , GT_SDLM_SCM_MST_EQUIPMENT_SN E
         WHERE E.SITE_ID      = R.SITE_ID
           AND E.MES_PLANT_ID = R.PLANT_ID  /* 2025.03.21 plant_id -> mes_plant_id */
           AND E.FACTORY_ID   = R.FACTORY_ID
           AND E.EQUIPMENT_ID = R.EQP_ID
           AND E.OPERATION_ID = R.OPERATION_ID
           AND R.RN = 1  /* 20240424 중복 수신데이터가 존재할시 최종?데이터로 필터링(우선순위 FP 프로시저 참조) */
         GROUP BY E.COMPANY_ID
                 ,E.DIVISION_ID
                 ,R.SITE_ID
                 ,E.PLANT_ID  /* 2025.03.21 r.plant_id -> e.plant_id */
                 ,R.FACTORY_ID
                 ,R.LINE_ID
                 ,R.OPERATION_ID
                 ,R.EQP_ID
                 ,E.ELTR_LN_TP_CD
                 ,R.LOSS_CD
                 ,R.LOSS_GR_CD;

        /* ---------------------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### 설비별 집계 Loss율 계산 - #LOSS_TIME_RT_EQP_MMLY');
        /* 비조업 분모 : 해당월total시간(s) */
        /* 비부하 분모 : 해당월total시간(s) - 비조업합계(s) */
        /* 비가동 분모 : 해당월total시간(s) - 비조업합계(s) - 비부하합계(s) */
        /* 2024.10.15 MMD 지표 예외 정보 적용 (@v_mm_ssn -> mm_ssn 으로 변경) */
        /* ---------------------------------------------------------------------------------------------------- */
        INSERT INTO GT_SDLM_LOSS_TIME_RT_EQP_MMLY
        SELECT R.*
              ,CAST(
               CASE WHEN LOSS_GR_CD = 'NAV'  /* 비조업 */                                    THEN LOSS_TM_SSN / MM_SSN
                    WHEN LOSS_GR_CD = 'NLD' AND MM_SSN = NAV_TOT_LOSS_TM                      THEN 0
                    WHEN LOSS_GR_CD = 'NLD'  /* 비부하 */                                    THEN LOSS_TM_SSN / (MM_SSN - NAV_TOT_LOSS_TM)
                    WHEN LOSS_GR_CD = 'NOP' AND MM_SSN = NAV_TOT_LOSS_TM + NLD_TOT_LOSS_TM    THEN 0
                    WHEN LOSS_GR_CD = 'NOP'  /* 비가동 */                                    THEN LOSS_TM_SSN / (MM_SSN - NAV_TOT_LOSS_TM - NLD_TOT_LOSS_TM)
               END AS NUMBER(20,10))  AS LOSS_RT
          FROM GT_SDLM_LOSS_TIME_R_EQP_MMLY R
         WHERE 1 = 1;

        /* ------------------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### #loss_time_r_ln_mmly (라인별집계)');
        /* ------------------------------------------------------------------------------------------------- */
        INSERT INTO GT_SDLM_LOSS_TIME_R_LN_MMLY
        SELECT R.COMPANY_ID
              ,R.DIVISION_ID
              ,R.SITE_ID
              ,R.PLANT_ID
              ,R.FACTORY_ID
              ,R.LINE_ID
              ,R.OPERATION_ID
              ,R.ELTR_LN_TP_CD
              ,R.LOSS_CD
              ,R.LOSS_GR_CD
              ,SUM(R.MM_DAYS)                    AS MM_DAYS  /* 2024.10.15 추가 for MMD 지표 예외 정보 적용   (설비대수 반영된 정보로 max가 아닌 sum) */
              ,SUM(R.MM_SSN)                     AS MM_SSN  /* 2024.10.15 추가 for MMD 지표 예외 정보 적용   (설비대수 반영된 정보로 max가 아닌 sum) */
              ,COUNT(DISTINCT R.EQP_ID)          AS EQP_NBU
              ,SUM(LOSS_CNT)                     AS LOSS_CNT
              ,SUM(LOSS_TM_SSN)                  AS LOSS_TM_SSN
              ,SUM(CASE WHEN R.LOSS_GR_CD = 'NAV' THEN SUM(LOSS_TM_SSN) ELSE 0 END)
                       OVER (PARTITION BY R.COMPANY_ID, R.DIVISION_ID, R.SITE_ID, R.FACTORY_ID, R.LINE_ID, R.OPERATION_ID, R.ELTR_LN_TP_CD) AS NAV_TOT_LOSS_TM  /* 비조업 */
              ,SUM(CASE WHEN R.LOSS_GR_CD = 'NLD' THEN SUM(LOSS_TM_SSN) ELSE 0 END)
                       OVER (PARTITION BY R.COMPANY_ID, R.DIVISION_ID, R.SITE_ID, R.FACTORY_ID, R.LINE_ID, R.OPERATION_ID, R.ELTR_LN_TP_CD) AS NLD_TOT_LOSS_TM  /* 비부하 */
              ,SUM(CASE WHEN R.LOSS_GR_CD = 'NOP' THEN SUM(LOSS_TM_SSN) ELSE 0 END)
                       OVER (PARTITION BY R.COMPANY_ID, R.DIVISION_ID, R.SITE_ID, R.FACTORY_ID, R.LINE_ID, R.OPERATION_ID, R.ELTR_LN_TP_CD) AS NOP_TOT_LOSS_TM  /* 비가동 */
          FROM GT_SDLM_LOSS_TIME_R_EQP_MMLY R
         GROUP BY R.COMPANY_ID
                 ,R.DIVISION_ID
                 ,R.SITE_ID
                 ,R.PLANT_ID
                 ,R.FACTORY_ID
                 ,R.LINE_ID
                 ,R.OPERATION_ID
                 ,R.ELTR_LN_TP_CD
                 ,R.LOSS_CD
                 ,R.LOSS_GR_CD;

        /* ------------------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### #loss_time_rt_ln_mmly (라인별집계-loss율계산)');
        /* 비조업 분모 : 해당월total시간(s) * 장비수 */
        /* 비부하 분모 : 해당월total시간(s) * 장비수 - 비조업합계(s) */
        /* 비가동 분모 : 해당월total시간(s) * 장비수 - 비조업합계(s) - 비부하합계(s) */
        /* 2024.10.15 MMD 지표 예외 정보 적용 (@v_mm_ssn * eqp_nbu -> mm_ssn(설비대수 반영된 값)으로 변경) */
        /* ------------------------------------------------------------------------------------------------- */
        INSERT INTO GT_SDLM_LOSS_TIME_RT_LN_MMLY
        SELECT R.*
              ,CAST(
               CASE WHEN LOSS_GR_CD = 'NAV'  /* 비조업 */                                  THEN LOSS_TM_SSN / MM_SSN
                    WHEN LOSS_GR_CD = 'NLD' AND MM_SSN = NAV_TOT_LOSS_TM                    THEN 0
                    WHEN LOSS_GR_CD = 'NLD'  /* 비부하 */                                  THEN LOSS_TM_SSN / (MM_SSN - NAV_TOT_LOSS_TM)
                    WHEN LOSS_GR_CD = 'NOP' AND MM_SSN = NAV_TOT_LOSS_TM + NLD_TOT_LOSS_TM  THEN 0
                    WHEN LOSS_GR_CD = 'NOP'  /* 비가동 */                                  THEN LOSS_TM_SSN / (MM_SSN - NAV_TOT_LOSS_TM - NLD_TOT_LOSS_TM)
               END AS NUMBER(20,10))  AS LOSS_RT
          FROM GT_SDLM_LOSS_TIME_R_LN_MMLY R
         WHERE 1 = 1;

        /* --------------------------------------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### #loss_time_rt_eqp_mmly - 조업율/부하율/시간가동률 추가 (설비별)');
        /* 2024.10.15 MMD 지표 예외 정보 적용 (@v_mm_ssn -> max(r.mm_ssn)으로 변경) */
        /* --------------------------------------------------------------------------------------------------------------------- */
        /* -조업율/부하율/시간가동률 추가 */
        INSERT INTO GT_SDLM_LOSS_TIME_RT_EQP_MMLY
        SELECT R.COMPANY_ID
              ,R.DIVISION_ID
              ,R.SITE_ID
              ,R.PLANT_ID
              ,R.FACTORY_ID
              ,R.LINE_ID
              ,R.OPERATION_ID
              ,R.EQP_ID
              ,R.ELTR_LN_TP_CD
              ,CASE WHEN LOSS_GR_CD = 'NAV' THEN 'AV_RT'
                    WHEN LOSS_GR_CD = 'NLD' THEN 'LD_RT'
                    WHEN LOSS_GR_CD = 'NOP' THEN 'OP_RT'
                END                     AS LOSS_CD
              ,'-'                      AS LOSS_GR_CD
              ,MAX(R.MM_DAYS)           AS MM_DAYS  /* 2024.10.15 추가 for MMD 지표 예외 정보 적용 */
              ,MAX(R.MM_SSN)            AS MM_SSN  /* 2024.10.15 추가 for MMD 지표 예외 정보 적용 */
              ,0                        AS LOSS_CNT
              ,CASE WHEN LOSS_GR_CD = 'NAV' THEN MAX(R.MM_SSN) - MAX(NAV_TOT_LOSS_TM)  /* 조업시간(초) */
                    WHEN LOSS_GR_CD = 'NLD' THEN MAX(R.MM_SSN) - MAX(NAV_TOT_LOSS_TM) - MAX(NLD_TOT_LOSS_TM)  /* 부하시간(초) */
                    WHEN LOSS_GR_CD = 'NOP' THEN MAX(R.MM_SSN) - MAX(NAV_TOT_LOSS_TM) - MAX(NLD_TOT_LOSS_TM) - MAX(NOP_TOT_LOSS_TM)  /* 가동시간(초) */
                    ELSE 0
                END                                                 AS LOSS_TM_SSN
              , MAX(NAV_TOT_LOSS_TM)                                AS NAV_TOT_LOSS_TM
              , MAX(NLD_TOT_LOSS_TM)                                AS NLD_TOT_LOSS_TM
              , MAX(NOP_TOT_LOSS_TM)                                AS NOP_TOT_LOSS_TM
              , 1 - SUM(LOSS_RT)                                    AS LOSS_RT
          FROM GT_SDLM_LOSS_TIME_RT_EQP_MMLY R
         WHERE 1 = 1
           AND R.LOSS_GR_CD IN ('NAV', 'NLD', 'NOP')
         GROUP BY R.COMPANY_ID
                 ,R.DIVISION_ID
                 ,R.SITE_ID
                 ,R.PLANT_ID
                 ,R.FACTORY_ID
                 ,R.LINE_ID
                 ,R.OPERATION_ID
                 ,R.ELTR_LN_TP_CD
                 ,R.LOSS_GR_CD
                 ,R.EQP_ID;

        /* --------------------------------------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### #loss_time_rt_ln_mmly - 조업율/부하율/시간가동률 추가 (라인별)');
        /* 2024.10.15 MMD 지표 예외 정보 적용 */
        /* 변경전 : @v_mm_ssn * eqp_nbu */
        /* 변경후 : max(r.mm_ssn)  -> 설비대수 적용된 값 */
        /* --------------------------------------------------------------------------------------------------------------------- */
        /* -조업율/부하율/시간가동률 추가 */
        INSERT INTO GT_SDLM_LOSS_TIME_RT_LN_MMLY
        SELECT R.COMPANY_ID
              ,R.DIVISION_ID
              ,R.SITE_ID
              ,R.PLANT_ID
              ,R.FACTORY_ID
              ,R.LINE_ID
              ,R.OPERATION_ID
              ,R.ELTR_LN_TP_CD
              ,CASE WHEN LOSS_GR_CD = 'NAV' THEN 'AV_RT'
                    WHEN LOSS_GR_CD = 'NLD' THEN 'LD_RT'
                    WHEN LOSS_GR_CD = 'NOP' THEN 'OP_RT'
                END                     AS LOSS_CD
              ,'-'                      AS LOSS_GR_CD
              ,MAX(R.MM_DAYS)           AS MM_DAYS  /* 2024.10.15 추가 for MMD 지표 예외 정보 적용 */
              ,MAX(R.MM_SSN)            AS MM_SSN  /* 2024.10.15 추가 for MMD 지표 예외 정보 적용 */
              ,R.EQP_NBU
              ,0                        AS LOSS_CNT
              /* 2024.10.15 변경 : 이미 설비 대수 반영된 값 - 조업:비조업 = 1 : N이라 max로 반영 */
              ,CASE WHEN LOSS_GR_CD = 'NAV' THEN MAX(R.MM_SSN) - MAX(NAV_TOT_LOSS_TM)  /* 조업시간(초) */
                    WHEN LOSS_GR_CD = 'NLD' THEN MAX(R.MM_SSN) - MAX(NAV_TOT_LOSS_TM) - MAX(NLD_TOT_LOSS_TM)  /* 부하시간(초) */
                    WHEN LOSS_GR_CD = 'NOP' THEN MAX(R.MM_SSN) - MAX(NAV_TOT_LOSS_TM) - MAX(NLD_TOT_LOSS_TM) - MAX(NOP_TOT_LOSS_TM)  /* 가동시간(초) */
                    ELSE 0
                END                                                 AS LOSS_TM_SSN
              , MAX(NAV_TOT_LOSS_TM)                                AS NAV_TOT_LOSS_TM
              , MAX(NLD_TOT_LOSS_TM)                                AS NLD_TOT_LOSS_TM
              , MAX(NOP_TOT_LOSS_TM)                                AS NOP_TOT_LOSS_TM
              , 1 - SUM(LOSS_RT)                                    AS LOSS_RT
          FROM GT_SDLM_LOSS_TIME_RT_LN_MMLY R
         WHERE 1 = 1
           AND R.LOSS_GR_CD IN ('NAV', 'NLD', 'NOP')
         GROUP BY R.COMPANY_ID
                 ,R.DIVISION_ID
                 ,R.SITE_ID
                 ,R.PLANT_ID
                 ,R.FACTORY_ID
                 ,R.LINE_ID
                 ,R.OPERATION_ID
                 ,R.ELTR_LN_TP_CD
                 ,R.LOSS_GR_CD
                 ,R.EQP_NBU;

        /* ----------------------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### 품목ID Basic NickName 정보 #SCP_MST_ITEM_BSI_IFO');
        /* ----------------------------------------------------------------------------------------------------- */
        INSERT INTO GT_SDLM_SCP_MST_ITEM_BSI_IFO
        SELECT ITEM_ID
              ,SCP_OPERATION_GROUP
              ,OPERATION_ID
              ,ELTR_LN_TP_CD
              ,BASIC_NICK_NAME
              ,ITEM_CLASS
          FROM SCP_MST_ITEM_BSI_IFO
         WHERE 1 = 1;

        /* ----------------------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### 셀 환산계수 정보 #SCP_MST_ITEM_CELL_CF');
        /* ----------------------------------------------------------------------------------------------------- */
        INSERT INTO GT_SDLM_SCP_MST_ITEM_CELL_CF
        SELECT ITEM_ID
              ,TARGET_CELL
              ,TO_NUMBER(NVL(CELL_CF, '1'))  AS CELL_CF
          FROM SCP_MST_ITEM_CELL_CF
         WHERE 1 = 1;

        /* -------------------------------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### DW 생산 투입 실적 - #PRD_INPUT_EQP_R ');
        /* -------------------------------------------------------------------------------------------------------------- */
        /* --### Stacking & Folding */
        /* ES0701	[AFCFC]Folded Cell */
        /* ES0801	[ASCSC]Stacked Cell */
        /* -------------------------------------------------------------------------------------------------------------- */
        INSERT INTO GT_SDLM_PRD_INPUT_EQP_R
        SELECT R.SITE_ID
              ,F.PLANT_ID  /* 2025.03.21 r.plant_id -> f.plant_id */
              ,R.AREA_ID                    AS FACTORY_ID
              ,R.LINE_ID
              ,CASE WHEN R.PROCESS_ID = 'A4000DW' THEN 'A3000'
                    WHEN R.PROCESS_ID = 'A7400DW' THEN CASE WHEN F.COMPANY_ID = V_ESHM THEN 'A7400' ELSE 'A7000' END
                    WHEN R.PROCESS_ID = 'A8400DW' THEN CASE WHEN F.COMPANY_ID = V_ESHM THEN 'A8400' ELSE 'A8000' END
                    ELSE R.PROCESS_ID
                END                         AS OPERATION_ID
              ,R.EQPT_ID                    AS EQP_ID
              ,R.PRODUCT_ID                 AS ITEM_ID
              ,R.MATERIAL_ID
              ,I.ITEM_CLASS
              ,CASE WHEN I.ITEM_CLASS IN ('ES0701', 'ES0801')  /* Stacking & Folding인 경우 투입 Material의 품목 분류정보 추가 */
                    THEN MI.ITEM_CLASS
                    ELSE '-'
                END AS MATERIAL_ITEM_CLASS
              ,I.BASIC_NICK_NAME            AS NICK_NAME
              ,I.ELTR_LN_TP_CD
              ,TO_NUMBER(NVL(CM.CELL_CF, '1'))                  AS MATERIAL_CELL_CONV_RATE
              ,TO_NUMBER(NVL(CP.CELL_CF, '1'))                  AS PRODUCT_CELL_CONV_RATE
              ,SUM(R.INPUT_QTY     )                            AS INPUT_QTY
              ,SUM(R.OUT_INPUT_QTY )                            AS OUT_INPUT_QTY  /* 6/5 추가 */
              ,SUM(R.GOOD_QTY      )                            AS GOOD_QTY
              ,SUM(R.OUT_GOOD_QTY  )                            AS OUT_GOOD_QTY
              ,SUM(R.OUT_DEFECT_QTY)                            AS OUT_DEFECT_QTY  /* 2024.08.14 추가 */
          FROM SCM_DNM_INPT_PRDN_DDLY R
               INNER JOIN SCM_MST_FACTORY_SN F
                       ON F.FACTORY_ID   = R.AREA_ID
                      AND F.MES_PLANT_ID = R.PLANT_ID  /* 2025.03.21 plant_id -> mes_plant_id */
               INNER JOIN GT_SDLM_SCP_MST_ITEM_BSI_IFO I
                       ON I.ITEM_ID = R.PRODUCT_ID
               LEFT  JOIN GT_SDLM_SCP_MST_ITEM_BSI_IFO MI
                       ON MI.ITEM_ID = R.MATERIAL_ID
               LEFT  JOIN GT_SDLM_SCP_MST_ITEM_CELL_CF CM
                       ON CM.ITEM_ID = R.MATERIAL_ID
               LEFT  JOIN GT_SDLM_SCP_MST_ITEM_CELL_CF CP
                       ON CP.ITEM_ID = R.PRODUCT_ID
         WHERE 1 = 1
           AND R.CAL_YMD_ID BETWEEN V_LOSS_FROM_YMD
                                AND V_LOSS_TO_YMD
           AND R.LOT_TYPE_ID IN ('P', 'R', 'H', 'S', 'Y', 'B')  /* FP YLD 대상 조건에 'B' 추가 */
           AND R.PROCESS_ID  LIKE 'A%'  /* Cell */
           AND R.EQPT_ID     != '@'  /* 설비정보가 없는 경우 투입수량이 0임? */
           AND R.MATERIAL_ID != '@'  /* 투입자재가 없는 경우 투입수량이 0임? */
           /* 2024.08.23 투입수량0인 데이터도 포함    AND R.INPUT_QTY   != 0 */
         GROUP BY R.SITE_ID
              ,F.PLANT_ID  /* 2025.03.21 R.plant_id -> F.plant_id */
              ,R.AREA_ID
              ,R.LINE_ID
              ,CASE WHEN R.PROCESS_ID = 'A4000DW' THEN 'A3000'
                    WHEN R.PROCESS_ID = 'A7400DW' THEN CASE WHEN F.COMPANY_ID = V_ESHM THEN 'A7400' ELSE 'A7000' END
                    WHEN R.PROCESS_ID = 'A8400DW' THEN CASE WHEN F.COMPANY_ID = V_ESHM THEN 'A8400' ELSE 'A8000' END
                    ELSE R.PROCESS_ID
                END
              ,R.EQPT_ID
              ,R.PRODUCT_ID
              ,R.MATERIAL_ID
              ,I.ITEM_CLASS
              ,MI.ITEM_CLASS
              ,I.BASIC_NICK_NAME
              ,I.ELTR_LN_TP_CD
              ,TO_NUMBER(NVL(CM.CELL_CF, '1'))
              ,TO_NUMBER(NVL(CP.CELL_CF, '1'))
              ,CASE WHEN I.ITEM_CLASS IN ('ES0701', 'ES0801')
                    THEN MI.ITEM_CLASS
                    ELSE '-'
                END;

        /* ---------------------------------- */
        /* 제외대상 삭제 */
        /* ---------------------------------- */
        DELETE
          FROM GT_SDLM_PRD_INPUT_EQP_R
         WHERE 1 = 1
           AND ITEM_CLASS = 'ES0701'
           AND NVL(MATERIAL_ITEM_CLASS, 'Z') NOT IN ('ES0601', 'ES0602');  /* Folding 투입 반제품이 A/C Type Bi Cell이 아닌 경우 */

        /* ------------------------------------------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### DW 생산 투입 실적  #PRD_INPUT_EQP_R : 대상 LOSS 실적이 없는 데이터 삭제');
        /* 2025.03.26 지표 예외로 대상에서 제외된 LOSS 실적등 불필요한 투입실적 참조 삭제 */

        /* ------------------------------------------------------------------------------------------------------------------------- */
        DELETE
          FROM GT_SDLM_PRD_INPUT_EQP_R I
         WHERE 1 = 1
           AND NOT EXISTS (SELECT 1
                             FROM GT_SDLM_LOSS_TIME_RAW_DATA L
                            WHERE 1 = 1
                              AND L.LINE_ID      = I.LINE_ID
                              AND L.OPERATION_ID = I.OPERATION_ID
                              AND L.FACTORY_ID   = I.FACTORY_ID
                              );

        /* ------------------------------------------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### DW 생산 투입 실적  #PRD_INPUT_CELL_CONVERT_R : Cell기준 환산수량 계산');
        /* ------------------------------------------------------------------------------------------------------------------------- */
        /* ---### Nothcing */
        /* -	ES0501	[ANPAN]Anode Notched Pancake */
        /* -	ES0502	[ANPCA]Cathode Notched Pancake */
        /* ---### Lamination */
        /* -	ES0601	[ABCAT]A-Type Bi-Cell */
        /* -	ES0602	[ABCCT]C-Type Bi-Cell */
        /* -	ES1007	[AMCMC]Mono-Type Cell */
        /* -	ES1101	[AHCHC]HALF-Type Cell */
        /* ---### Stacking & Folding */
        /* -	ES0701	[AFCFC]Folded Cell */
        /* -	ES0801	[ASCSC]Stacked Cell */
        /* ---### PKG */
        /* -	ES1901	[ACACA]Cell Assembly */
        /* ------------------------------------------------------------------------------------------------------------------------- */
        INSERT INTO GT_SDLM_PIC_CONVERT_R
        SELECT E.COMPANY_ID
              ,E.DIVISION_ID
              ,R.SITE_ID
              ,R.PLANT_ID
              ,R.FACTORY_ID
              ,R.LINE_ID
              ,R.OPERATION_ID
              ,R.NICK_NAME
              ,E.ELTR_LN_TP_CD  /* - 5/13 */
              ,R.MATERIAL_ITEM_CLASS
              ,R.EQP_ID  /* 20240826 */
              /* - 20240826 ,CONVERT(FLOAT, COUNT(DISTINCT R.EQP_ID))	AS EQP_NBU */
              ,SUM(R.INPUT_QTY)          AS INPUT_QTY  /* 반제품기준 투입수량 */
              ,SUM(R.OUT_INPUT_QTY )     AS OUT_INPUT_QTY  /* 6/5 추가 OUT기준 투입수량 */
              ,SUM(CASE WHEN R.MATERIAL_CELL_CONV_RATE = 0                                       THEN 0
                        WHEN R.ITEM_CLASS = 'ES0801' AND NVL(R.MATERIAL_ITEM_CLASS,'Z') != 'ES1007' THEN 0  /* Stacking Mono 투입이 아닌 경우 0 */
                        WHEN R.ITEM_CLASS IN ('ES0501', 'ES0502', 'ES0701', 'ES0801')  THEN R.INPUT_QTY * R.MATERIAL_CELL_CONV_RATE  /* 노칭(Anode/Cathode), 폴딩, SKG */
                        WHEN R.PRODUCT_CELL_CONV_RATE = 0                               THEN 0
                        WHEN R.ITEM_CLASS IN ('ES0601', 'ES0602')                       THEN R.INPUT_QTY * R.PRODUCT_CELL_CONV_RATE / 3  /* 라미 (A,C) */
                        WHEN R.ITEM_CLASS = 'ES1007'                                    THEN R.INPUT_QTY * R.PRODUCT_CELL_CONV_RATE / 2  /* 라미 (Mono) */
                        WHEN R.ITEM_CLASS IN ('ES1901', 'ES1101')                       THEN R.INPUT_QTY  /* PKG, 라미(Half) */
                        END)             AS CELL_INPUT_QTY  /* Cell기준 투입수량 */
              ,SUM(R.OUT_GOOD_QTY)       AS OUT_GOOD_QTY  /* 반제품기준 양품생산수량 */
              ,SUM(R.OUT_DEFECT_QTY)     AS OUT_DEFECT_QTY  /* 2024.08.14 추가 */
              ,SUM(CASE WHEN R.MATERIAL_CELL_CONV_RATE = 0                                       THEN 0
                        WHEN R.ITEM_CLASS = 'ES0801' AND NVL(R.MATERIAL_ITEM_CLASS,'Z') != 'ES1007' THEN 0  /* Stacking Mono 투입이 아닌 경우 0 */
                        WHEN R.ITEM_CLASS IN ('ES0501', 'ES0502', 'ES0701', 'ES0801')  THEN R.GOOD_QTY * R.MATERIAL_CELL_CONV_RATE  /* 노칭(Anode/Cathode), 폴딩, SKG */
                        WHEN R.PRODUCT_CELL_CONV_RATE = 0                               THEN 0
                        WHEN R.ITEM_CLASS IN ('ES0601', 'ES0602')                       THEN R.GOOD_QTY * R.PRODUCT_CELL_CONV_RATE / 3  /* 라미 (A,C) */
                        WHEN R.ITEM_CLASS = 'ES1007'                                    THEN R.GOOD_QTY * R.PRODUCT_CELL_CONV_RATE / 2  /* 라미 (Mono) */
                        WHEN R.ITEM_CLASS IN ('ES1901', 'ES1101')                       THEN R.GOOD_QTY  /* PKG, 라미(Half) */
                        END)             AS CELL_GOOD_QTY  /* Cell기준 양품 생산수량 */
          FROM GT_SDLM_PRD_INPUT_EQP_R R
             , GT_SDLM_SCM_MST_EQUIPMENT_SN E
         WHERE E.SITE_ID       = R.SITE_ID
           AND E.PLANT_ID      = R.PLANT_ID
           AND E.FACTORY_ID    = R.FACTORY_ID
           AND E.EQUIPMENT_ID  = R.EQP_ID
           AND E.OPERATION_ID  = R.OPERATION_ID
           AND E.ELTR_LN_TP_CD = R.ELTR_LN_TP_CD  /* 2024.08.26 */
         GROUP BY  E.COMPANY_ID
              ,E.DIVISION_ID
              ,R.SITE_ID
              ,R.PLANT_ID
              ,R.FACTORY_ID
              ,R.LINE_ID
              ,R.OPERATION_ID
              ,R.NICK_NAME
              ,E.ELTR_LN_TP_CD  /* 5/13 */
              ,R.MATERIAL_ITEM_CLASS
              ,R.EQP_ID;  /* 20240826 */

        /* ------------------------------------------------------------------------------------------------------------------ */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### 생산 투입 실적 - #PROD_INPUT_RESULT (모델별:Basic Model NickName)');
        /* ------------------------------------------------------------------------------------------------------------------ */
        INSERT INTO GT_SDLM_PROD_INPUT_RESULT
        SELECT R.COMPANY_ID
              ,R.DIVISION_ID
              ,R.SITE_ID
              ,R.PLANT_ID
              ,R.FACTORY_ID
              ,R.LINE_ID
              ,R.OPERATION_ID
              ,R.NICK_NAME                        AS MDL_NM
              ,R.ELTR_LN_TP_CD
              ,COUNT(DISTINCT R.EQP_ID)           AS EQP_NBU
              ,SUM(INPUT_QTY     )                AS INPUT_QTY
              ,SUM(OUT_INPUT_QTY )                AS OUT_INPUT_QTY  /* 6/5 추가 OUT기준 투입수량 */
              ,CASE WHEN R.ELTR_LN_TP_CD = 'Folding'
                    THEN AVG(CELL_INPUT_QTY)
                    ELSE SUM(CELL_INPUT_QTY)
               END                                AS CELL_INPUT_QTY
              ,NVL(SUM(OUT_GOOD_QTY)  , 0)        AS OUT_GOOD_QTY
              ,NVL(SUM(OUT_DEFECT_QTY), 0)        AS OUT_DEFECT_QTY  /* 2024.08.14 추가 */
              ,CASE WHEN R.ELTR_LN_TP_CD = 'Folding'
                    THEN AVG(CELL_GOOD_QTY)
                    ELSE SUM(CELL_GOOD_QTY)
               END                                AS CELL_GOOD_QTY
          FROM GT_SDLM_PIC_CONVERT_R R  /* 2024.08.26 변경 */
         WHERE 1 = 1
         GROUP BY R.COMPANY_ID
              ,R.DIVISION_ID
              ,R.SITE_ID
              ,R.PLANT_ID
              ,R.FACTORY_ID
              ,R.LINE_ID
              ,R.OPERATION_ID
              ,R.NICK_NAME
              ,R.ELTR_LN_TP_CD;

        /* ---------------------------------------------------------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### DW 생산 투입 실적  #PRD_INPUT_CELL_CONVERT_R_LN : Cell기준 환산수량 라인별/material class별 집계');
        /* ---------------------------------------------------------------------------------------------------------------------------------------- */
        INSERT INTO GT_SDLM_PIC_CONVERT_R_LN
        SELECT R.COMPANY_ID
              ,R.DIVISION_ID
              ,R.SITE_ID
              ,R.PLANT_ID
              ,R.FACTORY_ID
              ,R.LINE_ID
              ,R.OPERATION_ID
              ,R.ELTR_LN_TP_CD
              ,R.MATERIAL_ITEM_CLASS  /* for Folding */
              ,COUNT(DISTINCT R.EQP_ID)   AS EQP_NBU
              ,SUM(R.INPUT_QTY)           AS INPUT_QTY
              ,SUM(R.CELL_INPUT_QTY)      AS CELL_INPUT_QTY
              ,SUM(R.OUT_GOOD_QTY)        AS OUT_GOOD_QTY
              ,SUM(R.CELL_GOOD_QTY)       AS CELL_GOOD_QTY
              ,SUM(R.OUT_INPUT_QTY)       AS OUT_INPUT_QTY
              ,SUM(R.OUT_DEFECT_QTY)      AS OUT_DEFECT_QTY
          FROM GT_SDLM_PIC_CONVERT_R R
         WHERE 1 = 1
         GROUP BY R.COMPANY_ID
              ,R.DIVISION_ID
              ,R.SITE_ID
              ,R.PLANT_ID
              ,R.FACTORY_ID
              ,R.LINE_ID
              ,R.OPERATION_ID
              ,R.ELTR_LN_TP_CD
              ,R.MATERIAL_ITEM_CLASS;

        /* -------------------------------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### 생산 투입 실적 - #PROD_INPUT_RESULT_LN (라인별)');
        /* -------------------------------------------------------------------------------------------------------------- */
        INSERT INTO GT_SDLM_PROD_INPUT_RESULT_LN
        SELECT R.COMPANY_ID
              ,R.DIVISION_ID
              ,R.SITE_ID
              ,R.PLANT_ID
              ,R.FACTORY_ID
              ,R.LINE_ID
              ,R.OPERATION_ID
              ,R.ELTR_LN_TP_CD
              ,MAX(EQP_NBU  )                     AS EQP_NBU
              ,SUM(INPUT_QTY)                     AS INPUT_QTY
              ,CASE WHEN R.ELTR_LN_TP_CD = 'Folding'
                    THEN AVG(CELL_INPUT_QTY)
                    ELSE SUM(CELL_INPUT_QTY)
               END                                AS CELL_INPUT_QTY
              ,SUM(OUT_GOOD_QTY)                  AS OUT_GOOD_QTY
              ,SUM(OUT_DEFECT_QTY)                AS OUT_DEFECT_QTY
              ,CASE WHEN R.ELTR_LN_TP_CD = 'Folding'
                    THEN AVG(CELL_GOOD_QTY)
                    ELSE SUM(CELL_GOOD_QTY)
               END                                AS CELL_GOOD_QTY
          FROM GT_SDLM_PIC_CONVERT_R_LN R
         WHERE 1 = 1
         GROUP BY R.COMPANY_ID
              ,R.DIVISION_ID
              ,R.SITE_ID
              ,R.PLANT_ID
              ,R.FACTORY_ID
              ,R.LINE_ID
              ,R.OPERATION_ID
              ,R.ELTR_LN_TP_CD;

        /* ----------------------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### MMD 라인별 설계속도 - #SCP_MST_MDL_EQP_SPED (라인별)');
        /* MMD설계속도: 한 라인에 여러 Basic Nickname이 존재하는 경우 투입수량 가중치 적용 */
        /* 단위가 Tact Time인 경우 : 60 / 설계속도 */
        /* ----------------------------------------------------------------------------------------------------- */
        INSERT INTO GT_SDLM_SCP_MST_MDL_EQP_SPED
        SELECT S.COMPANY_ID
              ,S.DIVISION_ID
              ,S.SITE_ID
              ,S.PLANT_ID
              ,S.FACTORY_ID
              ,S.LINE_ID
              ,S.OPERATION_ID
              ,S.ELTR_LN_TP_CD
              ,CASE WHEN SUM(R.OUT_INPUT_QTY) = 0     THEN 0
                    WHEN MAX(EQP_SPED_UNIT_CD) = 'TTT'
                    THEN 60 / ( SUM(S.EQP_SPED * R.OUT_INPUT_QTY)  /* 2024.06.05 output기준 투입수량 가중치 적용 */
                              / SUM(R.OUT_INPUT_QTY)
                              )
                    ELSE   SUM(S.EQP_SPED * R.OUT_INPUT_QTY)  /* 2024.06.05 output기준 투입수량 가중치 적용 */
                         / SUM(R.OUT_INPUT_QTY)
                END                       AS EQP_SPED  /* MMD설계속도 */
              ,MAX(EQP_SPED_UNIT_CD)      AS EQP_SPED_UNIT_CD
          FROM SCP_MST_MDL_EQP_SPED S
             , GT_SDLM_PROD_INPUT_RESULT R  /* 모델별 투입수량 */
         WHERE R.MDL_NM       = S.MDL_NM
           AND R.COMPANY_ID   = S.COMPANY_ID
           AND R.DIVISION_ID  = S.DIVISION_ID
           AND R.SITE_ID      = S.SITE_ID
           AND R.PLANT_ID     = S.PLANT_ID
           AND R.FACTORY_ID   = S.FACTORY_ID
           AND R.LINE_ID      = S.LINE_ID
           AND R.OPERATION_ID = S.OPERATION_ID
           AND R.ELTR_LN_TP_CD = S.ELTR_LN_TP_CD
         GROUP BY S.COMPANY_ID
                 ,S.DIVISION_ID
                 ,S.SITE_ID
                 ,S.PLANT_ID
                 ,S.FACTORY_ID
                 ,S.LINE_ID
                 ,S.OPERATION_ID
                 ,S.ELTR_LN_TP_CD;

        /* --------------------------------------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### #loss_time_rt_ln_mmly - 생산평균속도 (라인별)');
        /* --------------------------------------------------------------------------------------------------------------------- */
        /* --	생산평균속도 */
        /* --	 1) 설계속도 단위가 mm/s (Notching공정) = 투입 수량 (개) - 반제품 기준/가동시간(분)*1000/60 */
        /* --	 2) 나머지 = 투입 수량 (개) - Cell 기준/가동시간(분) * 생산 수량 (개) - 반제품 (양품량)/생산 수량 (개) - Cell 기준 (양품량) */
        /* --------------------------------------------------------------------------------------------------------------------- */
        INSERT INTO GT_SDLM_LOSS_TIME_RT_LN_MMLY
        SELECT R.COMPANY_ID
              ,R.DIVISION_ID
              ,R.SITE_ID
              ,R.PLANT_ID
              ,R.FACTORY_ID
              ,R.LINE_ID
              ,R.OPERATION_ID
              ,R.ELTR_LN_TP_CD
              ,'PROD_AVG_SPED'          AS LOSS_CD
              ,'-'                      AS LOSS_GR_CD
              ,R.MM_DAYS                AS MM_DAYS  /* 2024.10.15 추가 for MMD 지표 예외 정보 적용 */
              ,R.MM_SSN                 AS MM_SSN  /* 2024.10.15 추가 for MMD 지표 예외 정보 적용 */
              ,R.EQP_NBU
              ,0                        AS LOSS_CNT
              ,0                        AS LOSS_TM_SSN
              ,0                        AS NAV_TOT_LOSS_TM
              ,0                        AS NLD_TOT_LOSS_TM
              ,0                        AS NOP_TOT_LOSS_TM
              ,CASE WHEN R.LOSS_TM_SSN = 0  /* 가동시간이 0 이면 0 */
                    THEN 0
                    WHEN R.OPERATION_ID = 'A5000'  /* Notching (mm/s) */
                    THEN NVL(PR.INPUT_QTY, 0)
                            / (R.LOSS_TM_SSN / 60)
                            * 1000
                            / 60
                    WHEN NVL(PR.CELL_GOOD_QTY, 0) = 0  /* 생산 수량 (개) - Cell (양품량) */
                    THEN 0
                    ELSE NVL(PR.CELL_INPUT_QTY, 0)
                              / (R.LOSS_TM_SSN / 60)
                              * NVL(PR.OUT_GOOD_QTY, 0)
                              / PR.CELL_GOOD_QTY
               END  AS LOSS_RT
          FROM GT_SDLM_LOSS_TIME_RT_LN_MMLY R
             , GT_SDLM_PROD_INPUT_RESULT_LN PR
         WHERE PR.COMPANY_ID   = R.COMPANY_ID
           AND PR.DIVISION_ID  = R.DIVISION_ID
           AND PR.SITE_ID      = R.SITE_ID
           AND PR.PLANT_ID     = R.PLANT_ID
           AND PR.FACTORY_ID   = R.FACTORY_ID
           AND PR.LINE_ID      = R.LINE_ID
           AND PR.OPERATION_ID = R.OPERATION_ID
           AND PR.ELTR_LN_TP_CD = R.ELTR_LN_TP_CD
           AND LOSS_CD = 'OP_RT';

        /* --------------------------------------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### #loss_rt_mdl_mmly - 양품가동률 (라인별)');
        /* --------------------------------------------------------------------------------------------------------------------- */
        /* 양품가동률 = 양품수량(Cell기준) / 투입수량 (Cell기준)		-> 2024.08.14 변경전 */
        /* 양품가동률 = OUT_GOOD_QTY / (OUT_DEFECT_QTY + OUT_GOOD_QTY)	-> 2024.08.14 변경후 */
        /* --------------------------------------------------------------------------------------------------------------------- */
        INSERT INTO GT_SDLM_LOSS_TIME_RT_LN_MMLY
        SELECT R.COMPANY_ID
              ,R.DIVISION_ID
              ,R.SITE_ID
              ,R.PLANT_ID
              ,R.FACTORY_ID
              ,R.LINE_ID
              ,R.OPERATION_ID
              ,R.ELTR_LN_TP_CD
              ,'QL_RT_LN'   AS LOSS_CD  /* 라인별 양품가동률 */
              ,'-'          AS LOSS_GR_CD
              ,OP.MM_DAYS  /* 2024.10.15 추가 for MMD 지표 예외 정보 적용 */
              ,OP.MM_SSN  /* 2024.10.15 추가 for MMD 지표 예외 정보 적용 */
              ,R.EQP_NBU
              ,0            AS LOSS_CNT
              ,0            AS LOSS_M_SSN
              ,0            AS NAV_TOT_LOSS_TM
              ,0            AS NLD_TOT_LOSS_TM
              ,0            AS NOP_TOT_LOSS_TM
              ,CASE WHEN (OUT_DEFECT_QTY + OUT_GOOD_QTY) = 0
                    THEN 0
                    ELSE OUT_GOOD_QTY / (OUT_DEFECT_QTY + OUT_GOOD_QTY)  /* 2024.08.14 변경 */
               END  AS LOSS_RT
          FROM GT_SDLM_PROD_INPUT_RESULT_LN R
             , GT_SDLM_LOSS_TIME_RT_LN_MMLY OP  /* 2024.10.15 join 추가 for MMD 지표 예외 정보 적용 */
         WHERE OP.COMPANY_ID(+)    = R.COMPANY_ID
           AND OP.DIVISION_ID(+)   = R.DIVISION_ID
           AND OP.SITE_ID(+)       = R.SITE_ID
           AND OP.PLANT_ID(+)      = R.PLANT_ID
           AND OP.FACTORY_ID(+)    = R.FACTORY_ID
           AND OP.LINE_ID(+)       = R.LINE_ID
           AND OP.OPERATION_ID(+)  = R.OPERATION_ID
           AND OP.ELTR_LN_TP_CD(+) = R.ELTR_LN_TP_CD
           AND OP.LOSS_CD(+)       = 'OP_RT';

        /* --------------------------------------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### #loss_rt_mdl_mmly - 양품가동률 (모델별)');
        /* --------------------------------------------------------------------------------------------------------------------- */
        /* 양품가동률 = 양품수량(Cell기준) / 투입수량 (Cell기준)		-> 2024.08.14 변경전 */
        /* 양품가동률 = OUT_GOOD_QTY / (OUT_DEFECT_QTY + OUT_GOOD_QTY)	-> 2024.08.14 변경후 */
        /* --------------------------------------------------------------------------------------------------------------------- */
        INSERT INTO GT_SDLM_LOSS_RT_MDL_MMLY
        SELECT R.MDL_NM  /* - 3/19 */
              ,R.COMPANY_ID
              ,R.DIVISION_ID
              ,R.SITE_ID
              ,R.PLANT_ID
              ,R.FACTORY_ID
              ,R.LINE_ID
              ,R.OPERATION_ID
              ,R.ELTR_LN_TP_CD
              ,'QL_RT'  AS LOSS_CD
              /* - for 검증 */
              ,0 AS INPUT_QTY
              ,0 AS CELL_INPUT_QTY
              ,0 AS LOSS_TM_MINS
              ,0 AS CELL_GOOD_QTY
              ,0 AS OUT_GOOD_QTY
              /* ------------------------------ */
              ,CASE WHEN (OUT_DEFECT_QTY + OUT_GOOD_QTY) = 0
                    THEN 0
                    ELSE OUT_GOOD_QTY / (OUT_DEFECT_QTY + OUT_GOOD_QTY)  /* 2024.08.14 변경 */
               END  AS LOSS_RT
              /* 2024.08.14 변경전    ,case when isnull(sum(cell_input_qty), 0) = 0 */
              /* 2024.08.14 변경전  		then 0 */
              /* 2024.08.14 변경전  		else convert(float, isnull(sum(cell_good_qty), 0)) / converT(float, sum(cell_input_qty)) */
              /* 2024.08.14 변경전     end  as loss_rt */
          FROM GT_SDLM_PROD_INPUT_RESULT R
         WHERE 1 = 1;

        /* --------------------------------------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### #loss_rt_mdl_mmly - MMD 설계속도 추가 (라인별)');
        /* --------------------------------------------------------------------------------------------------------------------- */
        INSERT INTO GT_SDLM_LOSS_TIME_RT_LN_MMLY
        SELECT R.COMPANY_ID
              ,R.DIVISION_ID
              ,R.SITE_ID
              ,R.PLANT_ID
              ,R.FACTORY_ID
              ,R.LINE_ID
              ,R.OPERATION_ID
              ,R.ELTR_LN_TP_CD
              ,'MMD_SPED'               AS LOSS_CD
              ,'-'                      AS LOSS_GR_CD
              ,R.MM_DAYS                AS MM_DAYS  /* 2024.10.15 추가 for MMD 지표 예외 정보 적용 */
              ,R.MM_SSN                 AS MM_SSN  /* 2024.10.15 추가 for MMD 지표 예외 정보 적용 */
              ,R.EQP_NBU
              ,0                        AS LOSS_CNT
              ,0                        AS LOSS_TM_SSN
              ,0                        AS NAV_TOT_LOSS_TM
              ,0                        AS NLD_TOT_LOSS_TM
              ,0                        AS NOP_TOT_LOSS_TM
              ,S.EQP_SPED               AS LOSS_RT  /* MMD 설계속도 */
          FROM GT_SDLM_LOSS_TIME_RT_LN_MMLY R
             , GT_SDLM_SCP_MST_MDL_EQP_SPED S
         WHERE S.COMPANY_ID   = R.COMPANY_ID
           AND S.DIVISION_ID  = R.DIVISION_ID
           AND S.SITE_ID      = R.SITE_ID
           AND S.PLANT_ID     = R.PLANT_ID
           AND S.FACTORY_ID   = R.FACTORY_ID
           AND S.LINE_ID      = R.LINE_ID
           AND S.OPERATION_ID = R.OPERATION_ID
           AND S.ELTR_LN_TP_CD = R.ELTR_LN_TP_CD
           AND LOSS_CD = 'PROD_AVG_SPED';  /* 생산평균속도 */

        /* --------------------------------------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### #loss_rt_mdl_mmly - 성능가동률 추가 (라인별)');
        /*
        --	설계속도(MMD기준)  - SCP_MST_MDL_EQP_SPED (MDL_NM, DIVISION_ID, COMPANY_ID, SITE_ID, PLANT_ID, FACTORY_ID, LINE_ID, OPERATION_ID, ELTR_LN_TP_CD)
        --	 1) 설계속도 단위가 Tact Time일 경우 = 60/설계속도
        --	 2) 나머지 = 설계속도
        --	생산평균속도
        --	 1) 설계속도 단위가 mm/s (Notching공정) = 투입 수량 (개) - 반제품 기준/가동시간(분)*1000/60
        --	 2) 나머지 = 투입 수량 (개) - Cell 기준/가동시간(분) * 생산 수량 (개) - 반제품 (양품량)/생산 수량 (개) - Cell (양품량)
        ----------------------
        -- 2024.11.04 성능가동률 100%으로 적재
        */
        /* --------------------------------------------------------------------------------------------------------------------- */
        INSERT INTO GT_SDLM_LOSS_TIME_RT_LN_MMLY
        SELECT R.COMPANY_ID
              ,R.DIVISION_ID
              ,R.SITE_ID
              ,R.PLANT_ID
              ,R.FACTORY_ID
              ,R.LINE_ID
              ,R.OPERATION_ID
              ,R.ELTR_LN_TP_CD
              ,'PF_RT'                  AS LOSS_CD
              ,'-'                      AS LOSS_GR_CD
              ,R.MM_DAYS                AS MM_DAYS  /* 2024.10.15 추가 for MMD 지표 예외 정보 적용 */
              ,R.MM_SSN                 AS MM_SSN  /* 2024.10.15 추가 for MMD 지표 예외 정보 적용 */
              ,R.EQP_NBU
              ,0                        AS LOSS_CNT
              ,LOSS_TM_SSN              AS LOSS_TM_SSN  /* 2024.11.04 성능가동률 100% (성능가동시간 = 시간가동시간) */
              ,0                        AS NAV_TOT_LOSS_TM
              ,0                        AS NLD_TOT_LOSS_TM
              ,0                        AS NOP_TOT_LOSS_TM
              /* ------------------------------ */
              ,1.0                      AS LOSS_RT  /* 2024.11.04 성능가동률 100%으로 적재 */
          FROM GT_SDLM_LOSS_TIME_RT_LN_MMLY R
         WHERE 1 = 1
           AND LOSS_CD = 'OP_RT';  /* 시간가동률 */

        /* 2024.11.04 성능가동률 100%으로 변경전 소스
        select r.company_id
              ,r.division_id
              ,r.site_id
              ,r.plant_id
              ,r.factory_id
              ,r.line_id
              ,r.operation_id
              ,r.eltr_ln_tp_cd
              ,'PF_RT'					as loss_cd
              ,'-'						as loss_gr_cd
              ,r.mm_days				as mm_days		-- 2024.10.15 추가 for MMD 지표 예외 정보 적용
              ,r.mm_ssn					as mm_ssn		-- 2024.10.15 추가 for MMD 지표 예외 정보 적용
              ,r.eqp_nbu
              ,0						as loss_cnt
              ,0						as loss_tm_ssn
              ,0						as nav_tot_loss_tm
              ,0						as nld_tot_loss_tm
              ,0						as nop_tot_loss_tm
              --------------------------------
              ,case when s.eqp_sped = 0 or r.loss_rt = 0
                    then 0
                    else convert(float, r.loss_rt) / convert(float, s.eqp_sped) 				--  생산평균속도 / MMD설계속도
                end			as loss_rt
         FROM #loss_time_rt_ln_mmly r
               inner join #SCP_MST_MDL_EQP_SPED s with(nolock)
                       on s.company_id		= r.company_id
                      and s.division_id		= r.division_id
                      and s.site_id			= r.site_id
                      and s.plant_id		= r.plant_id
                      and s.factory_id		= r.factory_id
                      and s.line_id			= r.line_id
                      and s.operation_id	= r.operation_id
                      and s.eltr_ln_tp_cd	= r.eltr_ln_tp_cd
        WHERE 1=1
          AND loss_cd = 'PROD_AVG_SPED' -- 생산평균속도
        */

        /* ----------------------------------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### #loss_rt_mdl_mmly - - 생산가동률 (라인별) ');  /* 20240429 추가 */
        /* ----------------------------------------------------------------------------------------------------------------- */
        /* PROD_OP_RT : 생산가동률  : 부하율 * 시간가동률 * 성능가동률 * 양품가동률(라인별) */
        /* LD_RT      : 부하율 */
        /* OP_RT      : 시간가동률 */
        /* PF_RT      : 성능가동률 */
        /* QL_RT      : 양품가동률 */
        /* ----------------------------------------------------------------------------------------------------------------- */
        INSERT INTO GT_SDLM_LOSS_TIME_RT_LN_MMLY
        SELECT R.COMPANY_ID
              ,R.DIVISION_ID
              ,R.SITE_ID
              ,R.PLANT_ID
              ,R.FACTORY_ID
              ,R.LINE_ID
              ,R.OPERATION_ID
              ,R.ELTR_LN_TP_CD
              ,'PROD_OP_RT'             AS LOSS_CD
              ,'-'                      AS LOSS_GR_CD
              ,MAX(R.MM_DAYS)           AS MM_DAYS  /* 2024.10.15 추가 for MMD 지표 예외 정보 적용 */
              ,MAX(R.MM_SSN)            AS MM_SSN  /* 2024.10.15 추가 for MMD 지표 예외 정보 적용 */
              ,MAX(R.EQP_NBU)           AS EQP_NBU
              ,0                        AS LOSS_CNT
              ,0                        AS LOSS_TM_SSN
              ,0                        AS NAV_TOT_LOSS_TM
              ,0                        AS NLD_TOT_LOSS_TM
              ,0                        AS NOP_TOT_LOSS_TM
              /* ------------------------------ */
              ,  CAST(MAX(CASE WHEN LOSS_CD = 'LD_RT'    THEN LOSS_RT ELSE 0.0 END) AS NUMBER(20,10))
               * CAST(MAX(CASE WHEN LOSS_CD = 'OP_RT'    THEN LOSS_RT ELSE 0.0 END) AS NUMBER(20,10))
               * CAST(MAX(CASE WHEN LOSS_CD = 'PF_RT'    THEN LOSS_RT ELSE 0.0 END) AS NUMBER(20,10))
               * CAST(MAX(CASE WHEN LOSS_CD = 'QL_RT_LN' THEN LOSS_RT ELSE 0.0 END) AS NUMBER(20,10)) AS LOSS_RT
          FROM GT_SDLM_LOSS_TIME_RT_LN_MMLY R
         WHERE 1 = 1
           AND LOSS_CD IN ('LD_RT', 'OP_RT', 'PF_RT', 'QL_RT_LN')
         GROUP BY R.COMPANY_ID
                 ,R.DIVISION_ID
                 ,R.SITE_ID
                 ,R.PLANT_ID
                 ,R.FACTORY_ID
                 ,R.LINE_ID
                 ,R.OPERATION_ID
                 ,R.ELTR_LN_TP_CD;

        /* ----------------------------------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### #loss_rt_mdl_mmly - - TEEP (라인별) ');  /* 20240429 추가 */
        /* ----------------------------------------------------------------------------------------------------------------- */
        /* TEEP : 생산가동률 * 조업률 */
        /* ----------------------------------------------------------------------------------------------------------------- */
        INSERT INTO GT_SDLM_LOSS_TIME_RT_LN_MMLY
        SELECT R.COMPANY_ID
              ,R.DIVISION_ID
              ,R.SITE_ID
              ,R.PLANT_ID
              ,R.FACTORY_ID
              ,R.LINE_ID
              ,R.OPERATION_ID
              ,R.ELTR_LN_TP_CD
              ,'TEEP'                   AS LOSS_CD
              ,'-'                      AS LOSS_GR_CD
              ,MAX(R.MM_DAYS)           AS MM_DAYS  /* 2024.10.15 추가 for MMD 지표 예외 정보 적용 */
              ,MAX(R.MM_SSN)            AS MM_SSN  /* 2024.10.15 추가 for MMD 지표 예외 정보 적용 */
              ,MAX(R.EQP_NBU)           AS EQP_NBU
              ,0                        AS LOSS_CNT
              ,0                        AS LOSS_TM_SSN
              ,0                        AS NAV_TOT_LOSS_TM
              ,0                        AS NLD_TOT_LOSS_TM
              ,0                        AS NOP_TOT_LOSS_TM
              /* ------------------------------ */
              ,  CAST(MAX(CASE WHEN LOSS_CD = 'PROD_OP_RT' THEN LOSS_RT ELSE 0.0 END) AS NUMBER(20,10))
               * CAST(MAX(CASE WHEN LOSS_CD = 'AV_RT'      THEN LOSS_RT ELSE 0.0 END) AS NUMBER(20,10)) AS LOSS_RT
          FROM GT_SDLM_LOSS_TIME_RT_LN_MMLY R
         WHERE 1 = 1
           AND LOSS_CD IN ('PROD_OP_RT', 'AV_RT')
         GROUP BY R.COMPANY_ID
                 ,R.DIVISION_ID
                 ,R.SITE_ID
                 ,R.PLANT_ID
                 ,R.FACTORY_ID
                 ,R.LINE_ID
                 ,R.OPERATION_ID
                 ,R.ELTR_LN_TP_CD;

    /* ----- Begin Tran : ======================================================================================= */
        SAVEPOINT SP_TRAN;  /* - transaction 시작 */

        /* -------------------------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### 손실실적설비별월별집계 DELETE SCM_DNM_LOSS_EQP_MMLY ');
        /* -------------------------------------------------------------------------------------------------------- */
        DELETE FROM SCM_DNM_LOSS_EQP_MMLY TGT
         WHERE LOSS_YM      = V_LOSS_YM
           AND PERD_DIVS_CD = TO_CHAR(V_PERD_DIVS_CD);  /* - 5/14 추가 */

        /* -------------------------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### 손실실적설비별월별집계 INSERT SCM_DNM_LOSS_EQP_MMLY ');
        /* 2024.10.15 MMD 지표 예외 정보 적용 (@v_mm_ssn -> mm_ssn 으로 변경) */
        /* -------------------------------------------------------------------------------------------------------- */
        INSERT INTO SCM_DNM_LOSS_EQP_MMLY
            (  LOSS_YM
              ,PERD_DIVS_CD  /* 5/14 */
              ,COMPANY_ID
              ,DIVISION_ID
              ,SITE_ID
              ,PLANT_ID
              ,FACTORY_ID
              ,LINE_ID
              ,OPERATION_ID
              ,EQP_ID
              ,ELTR_LN_TP_CD
              ,LOSS_CD
              ,LOSS_GR_CD
              ,LOSS_CNT
              ,LOSS_TM_SSN
              ,LOSS_RT
              ,CREATED_BY
              ,CREATION_DATE
              ,LAST_UPDATED_BY
              ,LAST_UPDATE_DATE
              ,ATTRIBUTE1
              ,ATTRIBUTE2
              ,ATTRIBUTE3
              ,ATTRIBUTE4
              )
        SELECT V_LOSS_YM
              ,TO_CHAR(V_PERD_DIVS_CD)  /* - 5/14 */
              ,COMPANY_ID
              ,DIVISION_ID
              ,SITE_ID
              ,PLANT_ID
              ,FACTORY_ID
              ,LINE_ID
              ,OPERATION_ID
              ,EQP_ID
              ,ELTR_LN_TP_CD
              ,LOSS_CD
              ,LOSS_GR_CD
              ,LOSS_CNT
              ,LOSS_TM_SSN
              ,LOSS_RT
              ,V_PROGRAM_NAME
              ,SYSDATE
              ,V_PROGRAM_NAME
              ,SYSDATE
              ,CASE WHEN LOSS_CD = 'AV_RT' OR LOSS_GR_CD = 'NAV'
                    THEN TO_CHAR(MM_DAYS, C_FMT_N2010)  /* 2024.10.30 최대가동일수 */
                    WHEN LOSS_CD = 'OP_RT'
                    THEN TO_CHAR(MM_SSN, C_FMT_N2010)  /* 해당월 초수 */
                    ELSE NULL
                END AS ATTRIBUTE1
              ,CASE WHEN LOSS_CD = 'OP_RT' THEN TO_CHAR(NAV_TOT_LOSS_TM, C_FMT_N2010) ELSE NULL END AS ATTRIBUTE2  /* 비조업시간 */
              ,CASE WHEN LOSS_CD = 'OP_RT' THEN TO_CHAR(NLD_TOT_LOSS_TM, C_FMT_N2010) ELSE NULL END AS ATTRIBUTE3  /* 비부하시간 */
              ,CASE WHEN LOSS_CD = 'OP_RT' THEN TO_CHAR(NOP_TOT_LOSS_TM, C_FMT_N2010) ELSE NULL END AS ATTRIBUTE4  /* 비가동시간 */
          FROM GT_SDLM_LOSS_TIME_RT_EQP_MMLY;

        /* -------------------------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### 손실실적라인별월별집계 DELETE SCM_DNM_LOSS_LN_MMLY ');
        /* -------------------------------------------------------------------------------------------------------- */
        DELETE FROM SCM_DNM_LOSS_LN_MMLY TGT
         WHERE LOSS_YM      = V_LOSS_YM
           AND PERD_DIVS_CD = TO_CHAR(V_PERD_DIVS_CD);  /* - 20240514 추가 */

        /* -------------------------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### 손실실적라인별월별집계 INSERT SCM_DNM_LOSS_LN_MMLY');
        /* 2024.10.15 MMD 지표 예외 정보 적용 */
        /* @v_mm_ssn * EQP_NBU -> mm_ssn 으로 변경 */
        /* @v_mm_ddn -> mm_days */
        /* -------------------------------------------------------------------------------------------------------- */
        INSERT INTO SCM_DNM_LOSS_LN_MMLY
            (  LOSS_YM
              ,PERD_DIVS_CD  /* 5/14 */
              ,COMPANY_ID
              ,DIVISION_ID
              ,SITE_ID
              ,PLANT_ID
              ,FACTORY_ID
              ,LINE_ID
              ,OPERATION_ID
              ,ELTR_LN_TP_CD
              ,LOSS_GR_CD
              ,LOSS_CD
              ,EQP_NBU
              ,LOSS_CNT
              ,LOSS_TM_SSN
              ,LOSS_RT
              ,CREATED_BY
              ,CREATION_DATE
              ,LAST_UPDATED_BY
              ,LAST_UPDATE_DATE
              ,ATTRIBUTE1
              ,ATTRIBUTE2
              ,ATTRIBUTE3
              ,ATTRIBUTE4
              )
        SELECT V_LOSS_YM
              ,TO_CHAR(V_PERD_DIVS_CD)  /* 5/14 추가 */
              ,COMPANY_ID
              ,DIVISION_ID
              ,SITE_ID
              ,PLANT_ID
              ,FACTORY_ID
              ,LINE_ID
              ,OPERATION_ID
              ,ELTR_LN_TP_CD
              ,LOSS_GR_CD
              ,LOSS_CD
              ,EQP_NBU
              ,LOSS_CNT
              ,LOSS_TM_SSN
              ,LOSS_RT
              ,V_PROGRAM_NAME
              ,SYSDATE
              ,V_PROGRAM_NAME
              ,SYSDATE
              ,CASE WHEN LOSS_CD = 'OP_RT'                          THEN TO_CHAR(MM_SSN, C_FMT_N2010)  /* 장비수량반영 해당월 초수 */
                    WHEN LOSS_CD = 'AV_RT' OR LOSS_GR_CD = 'NAV'     THEN TO_CHAR(MM_DAYS
                                                                                / CASE WHEN EQP_NBU = 0
                                                                                       THEN NULL
                                                                                       ELSE EQP_NBU
                                                                                       END, C_FMT_N2010)  /* 최대조업일수 (설비 1대당) */
                    ELSE NULL
                END AS ATTRIBUTE1
              ,CASE WHEN LOSS_CD = 'OP_RT' THEN TO_CHAR(NAV_TOT_LOSS_TM, C_FMT_N2010) ELSE NULL END AS ATTRIBUTE2  /* 비조업시간 */
              ,CASE WHEN LOSS_CD = 'OP_RT' THEN TO_CHAR(NLD_TOT_LOSS_TM, C_FMT_N2010) ELSE NULL END AS ATTRIBUTE3  /* 비부하시간 */
              ,CASE WHEN LOSS_CD = 'OP_RT' THEN TO_CHAR(NOP_TOT_LOSS_TM, C_FMT_N2010) ELSE NULL END AS ATTRIBUTE4  /* 비가동시간 */
          FROM GT_SDLM_LOSS_TIME_RT_LN_MMLY;

        /* -------------------------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### 손실실적모델별월별집계 DELETE SCM_DNM_LOSS_MDL_MMLY ');
        /* -------------------------------------------------------------------------------------------------------- */
        DELETE FROM SCM_DNM_LOSS_MDL_MMLY TGT
         WHERE LOSS_YM      = V_LOSS_YM
           AND PERD_DIVS_CD = TO_CHAR(V_PERD_DIVS_CD);  /* - 20240514 추가 */

        /* -------------------------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### 손실실적모델별월별집계 INSERT SCM_DNM_LOSS_MDL_MMLY');
        /* -------------------------------------------------------------------------------------------------------- */
        INSERT INTO SCM_DNM_LOSS_MDL_MMLY
            (  LOSS_YM
              ,PERD_DIVS_CD  /* 5/14 */
              ,MDL_NM
              ,COMPANY_ID
              ,DIVISION_ID
              ,SITE_ID
              ,PLANT_ID
              ,FACTORY_ID
              ,LINE_ID
              ,OPERATION_ID
              ,ELTR_LN_TP_CD
              ,LOSS_CD
              ,LOSS_RT
              ,CREATED_BY
              ,CREATION_DATE
              ,LAST_UPDATED_BY
              ,LAST_UPDATE_DATE
              )
        SELECT V_LOSS_YM
              ,TO_CHAR(V_PERD_DIVS_CD)  /* 5/14 */
              ,MDL_NM
              ,COMPANY_ID
              ,DIVISION_ID
              ,SITE_ID
              ,PLANT_ID
              ,FACTORY_ID
              ,LINE_ID
              ,OPERATION_ID
              ,ELTR_LN_TP_CD
              ,LOSS_CD
              ,LOSS_RT
              ,V_PROGRAM_NAME
              ,SYSDATE
              ,V_PROGRAM_NAME
              ,SYSDATE
          FROM GT_SDLM_LOSS_RT_MDL_MMLY;

        COMMIT;  /* - transaction 종료 */
    /* ----- End Tran : ========================================================================================================== */

        /* ------------------------------------- */
        /* -- 임시테이블 정리 */


        /* --------------------------------------- */

    EXCEPTION
        WHEN OTHERS THEN
            ROLLBACK;

            /* ERROR LOG */
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := 'ERROR_LINE : ' || SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 480);
            D_EVENT_DATE  := SYSDATE;
            PR_SCP_SYS_LOG_BATCH( V_PROGRAM_NAME
                                 ,V_LOG_TYPE
                                 ,N_LOG_COUNT
                                 ,V_LOG_MESSAGE
                                 ,V_DESCRIPTION
                                 ,D_EVENT_DATE
                                 ,V_BATCH_USER
                                 ,P_IN_PARA_DATA  => JSON_OBJECT('P_LOSS_YM' VALUE P_LOSS_YM, 'P_PERD_DIVS_CD' VALUE P_PERD_DIVS_CD RETURNING VARCHAR2(4000 CHAR))
                                 ,P_SQL_ERR_CODE  => TO_CHAR(SQLCODE)
                                 ,P_SQL_ERR_MSG   => SQLERRM
                                 ,P_SQL_BACKTRACE => DBMS_UTILITY.FORMAT_ERROR_BACKTRACE
                                 );
            DBMS_OUTPUT.PUT_LINE(V_LOG_MESSAGE || ' : ' || V_DESCRIPTION);
            RETURN;
    END;

    V_SEC := ROUND((SYSDATE - V_START_TIME) * 86400);

    V_EXEC_TIME := CASE WHEN LENGTH(TO_CHAR(TRUNC(V_SEC / 60))) > 2 THEN NULL
                        ELSE LPAD(TO_CHAR(TRUNC(V_SEC / 60)), 2, '0') || ':' || LPAD(TO_CHAR(MOD(V_SEC, 60)), 2, '0')
                   END;
    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '##### END of procedure #####';
    V_DESCRIPTION := '[81,82,JV][loss_ym=' || V_LOSS_YM || '][p_perd_divs_cd=' || TO_CHAR(P_PERD_DIVS_CD) || '][' || V_EXEC_TIME || ']';
    D_EVENT_DATE  := SYSDATE;
    PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER);
    DBMS_OUTPUT.PUT_LINE(V_LOG_MESSAGE || ' : ' || V_DESCRIPTION);


END;

PROCEDURE PR_SCM_DNM_MAT_MRP_SUPPLY
/*
 * Program ID   : PR_SCM_DNM_MAT_MRP_SUPPLY
 * Description  : 자재 가시화 I/F MRP RAW 데이터 취합 => SCM_DNM_MAT_MRP_SUPPLY 에 저장
 * Program History
 *================================================================================================================================================
 *   Date       In Charge                           Description
 *================================================================================================================================================
 * 2023/11/07   chaan     V1.1.9    PJ20216994 / LGES Digital SCM 3 Level 가속화를 위한 개선 Phase 2  - Initial release
 * 2023/11/09   chaan     V1.1.10   PJ20216994 / LGES Digital SCM 3 Level 가속화를 위한 개선 Phase 2  - ITEM_CATEGORY, UOM 개선
 * 2023/11/10   chaan     V1.1.11   PJ20216994 / LGES Digital SCM 3 Level 가속화를 위한 개선 Phase 2  - ORIGIN_DIVISION_ID 추적 로직 수정
 * 2023/11/10   chaan     V1.1.12   PJ20216994 / LGES Digital SCM 3 Level 가속화를 위한 개선 Phase 2  - 취합 대상에 반제품 포함
 * 2023/12/01   chaan     V1.1.13   PJ20216994 / LGES Digital SCM 3 Level 가속화를 위한 개선 Phase 2  - M 데이터 중복으로 CUTOFF_DATE 기준 최종 시점 데이터만 저장
 * 2023/12/04   chaan     V1.1.13   PJ20216994 / LGES Digital SCM 3 Level 가속화를 위한 개선 Phase 2  - 취득 데이터 대상을 ACCUM_DATE 기준 당일->전날로 변경
 * 2026.07.06   ZIONEX    [PJ202650304] NextSCM Migration
 */
IS
    /* LOG 용 변수 설정 */
    V_ACCUM_YYYYMMDD  VARCHAR2(8 CHAR)    := '';    /* 원본 NVARCHAR(8)='' (Oracle 에서 ''=NULL). 빈값이면 현재-1일 취합 */
    /* V_ACCUM_YYYYMMDD  VARCHAR2(8 CHAR)  := '20231203'; */
    V_TEST_MODE       VARCHAR2(1 CHAR)    := 'F';
    /* V_TEST_MODE       VARCHAR2(1 CHAR)  := 'T'; */
    V_PROGRAM_NAME    VARCHAR2(150 CHAR)  := 'PR_SCM_DNM_MAT_MRP_SUPPLY';
    V_LOG_TYPE        VARCHAR2(30 CHAR);    /* START/END/ERROR/... */
    N_LOG_COUNT       NUMBER              := 0;
    V_LOG_MESSAGE     VARCHAR2(1000 CHAR);
    V_DESCRIPTION     VARCHAR2(500 CHAR);
    D_EVENT_DATE      DATE                := SYSDATE;
    V_CURR_DATE       DATE;

    V_PROC_INPUT      VARCHAR2(4000 CHAR);
    V_SQL_CODE        VARCHAR2(100 CHAR);
    V_SQL_ERRMSG      VARCHAR2(2000 CHAR);
    V_BACKTRACE       VARCHAR2(4000 CHAR);
BEGIN

    /* 원본 BEGIN TRAN : Oracle 은 암시적 트랜잭션 → 성공 시 말미 COMMIT, 예외 시 ROLLBACK */

    /* 특정 날짜의 데이터를 가져올 때는 위 V_ACCUM_YYYYMMDD 를 특정 날짜로 설정, 빈값이면 현재 날짜의 데이터를 취합한다 */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '';

    IF V_TEST_MODE <> 'T' THEN
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    END IF;

    DBMS_OUTPUT.PUT_LINE(V_LOG_MESSAGE);

    V_CURR_DATE := SYSDATE;
    DBMS_OUTPUT.PUT_LINE('@v_curr_date : ' || TO_CHAR(V_CURR_DATE));

    IF V_ACCUM_YYYYMMDD IS NULL THEN
        V_ACCUM_YYYYMMDD := TO_CHAR(V_CURR_DATE - 1, 'YYYYMMDD');
    END IF;

    DBMS_OUTPUT.PUT_LINE('@v_accum_yyyymmdd : ' || V_ACCUM_YYYYMMDD);

    /* --rollback tran;return; */

    /* ITEM_CATEGORY, UOM 빈값을 채우기 위해 i/f 테이블에서 검색 */
    DBMS_OUTPUT.PUT_LINE('#TblPR_SCM_DNM_MAT_MRP_SUPPLY_CODE - BEGIN');

    DELETE /* PR_SCM_DNM_MAT_MRP_SUPPLY */
      FROM GT_SDMMS_CODE;

    INSERT /* PR_SCM_DNM_MAT_MRP_SUPPLY */
      INTO GT_SDMMS_CODE
    SELECT A.PLANT_ID
         , A.ITEM_ID
         , A.ATTR_07  AS UOM
         , A.ATTR_08  AS ITEM_CATEGORY
      FROM XIF_MRP_CUTOFF_SUPPLY_R_SN A
     WHERE 1 = 1
       AND SUBSTR(A.ACCUM_DATE, 1, 8) = V_ACCUM_YYYYMMDD
       AND (A.IF_TYPE = 'I' OR A.IF_TYPE = 'U')
       AND A.DATA_TYPE = 'M'
     GROUP BY A.PLANT_ID
            , A.ITEM_ID
            , A.ATTR_08
            , A.ATTR_07;

    DBMS_OUTPUT.PUT_LINE('#TblPR_SCM_DNM_MAT_MRP_SUPPLY_CODE - END');

    DBMS_OUTPUT.PUT_LINE('#TblPR_SCM_DNM_MAT_MRP_SUPPLY_CODE_UOM - BEGIN');

    DELETE /* PR_SCM_DNM_MAT_MRP_SUPPLY */
      FROM GT_SDMMS_CODE_UOM;

    INSERT /* PR_SCM_DNM_MAT_MRP_SUPPLY */
      INTO GT_SDMMS_CODE_UOM
    SELECT A.PLANT_ID
         , A.ITEM_ID
         , A.UOM
      FROM GT_SDMMS_CODE A
     WHERE 1 = 1
       AND A.UOM IS NOT NULL
     GROUP BY A.PLANT_ID
            , A.ITEM_ID
            , A.UOM;

    DBMS_OUTPUT.PUT_LINE('#TblPR_SCM_DNM_MAT_MRP_SUPPLY_CODE_UOM - END');
    /*
    --TESTING : OK
    --select * from #TblPR_SCM_DNM_MAT_MRP_SUPPLY_CODE_UOM;rollback tran;return;
    */

    DBMS_OUTPUT.PUT_LINE('#TblPR_SCM_DNM_MAT_MRP_SUPPLY_CODE_ITEM_CATEGORY - BEGIN');

    DELETE /* PR_SCM_DNM_MAT_MRP_SUPPLY */
      FROM GT_SDMMS_CODE_ITEM_CATEGORY;

    INSERT /* PR_SCM_DNM_MAT_MRP_SUPPLY */
      INTO GT_SDMMS_CODE_ITEM_CATEGORY
    SELECT A.PLANT_ID
         , A.ITEM_ID
         , A.ITEM_CATEGORY
      FROM GT_SDMMS_CODE A
     WHERE 1 = 1
       AND A.ITEM_CATEGORY IS NOT NULL
     GROUP BY A.PLANT_ID
            , A.ITEM_ID
            , A.ITEM_CATEGORY;

    DBMS_OUTPUT.PUT_LINE('#TblPR_SCM_DNM_MAT_MRP_SUPPLY_CODE_ITEM_CATEGORY - END');

    /*
    --TESTING : NOK
    --select * from #TblPR_SCM_DNM_MAT_MRP_SUPPLY_CODE_UOM;
    --select * from #TblPR_SCM_DNM_MAT_MRP_SUPPLY_CODE_ITEM_CATEGORY;rollback tran;return;
    */

    DBMS_OUTPUT.PUT_LINE('#TblPR_SCM_DNM_MAT_MRP_SUPPLY_RAW - BEGIN');

    DELETE /* PR_SCM_DNM_MAT_MRP_SUPPLY */
      FROM GT_SDMMS_RAW;

    INSERT /* PR_SCM_DNM_MAT_MRP_SUPPLY */
      INTO GT_SDMMS_RAW
    SELECT A.*
         , SUBSTR(A.ACCUM_DATE, 1, 8)  AS ACCUM_YYYYMMDD
         , SUBSTR(A.ACCUM_DATE, 1, 8)  AS CUTOFF_DATE
      FROM XIF_MRP_CUTOFF_SUPPLY_R_SN A
     WHERE 1 = 1
       AND SUBSTR(A.ACCUM_DATE, 1, 8) = V_ACCUM_YYYYMMDD              /* ACCUM_DATE 로 필터링 */
       AND (A.IF_TYPE = 'I' OR A.IF_TYPE = 'U')                      /* 인터페이스처리유형(I:Insert,U:Update,D:Delete) */
       AND (A.DATA_TYPE = 'M' OR A.DATA_TYPE = 'S')
       AND A.TRANSFER_FLAG = 'N';

    DBMS_OUTPUT.PUT_LINE('#TblPR_SCM_DNM_MAT_MRP_SUPPLY_RAW - END');

    /*
    --TESTING : OK
    --select * from #TblPR_SCM_DNM_MAT_MRP_SUPPLY_RAW;rollback tran;return;
    */

    IF V_TEST_MODE <> 'T' THEN                                       /* 테스트모드에서는 실제 DB 갱신없음 */
        /* 원본 : UPDATE A SET TRANSFER_FLAG='P' FROM XIF A JOIN #RAW B ON A.IF_SEQ=B.IF_SEQ */
        UPDATE /* PR_SCM_DNM_MAT_MRP_SUPPLY */
               XIF_MRP_CUTOFF_SUPPLY_R_SN A
           SET A.TRANSFER_FLAG = 'P'
         WHERE EXISTS (SELECT 1
                         FROM GT_SDMMS_RAW B
                        WHERE B.IF_SEQ = A.IF_SEQ);
    END IF;

    DBMS_OUTPUT.PUT_LINE('#TblPR_SCM_DNM_MAT_MRP_SUPPLY_RAW_M - BEGIN');

    DELETE /* PR_SCM_DNM_MAT_MRP_SUPPLY */
      FROM GT_SDMMS_RAW_M;

    INSERT /* PR_SCM_DNM_MAT_MRP_SUPPLY */
      INTO GT_SDMMS_RAW_M
    SELECT A.*
      FROM GT_SDMMS_RAW A
     WHERE 1 = 1
       AND A.DATA_TYPE = 'M'
       AND A.ATTR_09   = 'Y';

    DBMS_OUTPUT.PUT_LINE('#TblPR_SCM_DNM_MAT_MRP_SUPPLY_RAW_M - END');

    /*
    --TESTING : OK
    --select * from #TblPR_SCM_DNM_MAT_MRP_SUPPLY_RAW_M;rollback tran;return;
    --select * from #TblPR_SCM_DNM_MAT_MRP_SUPPLY_RAW_M where item_id = 'RET00649AA';rollback tran;return;
    */

    DBMS_OUTPUT.PUT_LINE('#TblPR_SCM_DNM_MAT_MRP_SUPPLY_RAW_M_ITEMS - BEGIN');

    DELETE /* PR_SCM_DNM_MAT_MRP_SUPPLY */
      FROM GT_SDMMS_RAW_M_ITEMS;

    INSERT /* PR_SCM_DNM_MAT_MRP_SUPPLY */
      INTO GT_SDMMS_RAW_M_ITEMS
    SELECT A.PLANT_ID
         , A.ITEM_ID
      FROM GT_SDMMS_RAW_M A
     GROUP BY A.PLANT_ID
            , A.ITEM_ID;

    DBMS_OUTPUT.PUT_LINE('#TblPR_SCM_DNM_MAT_MRP_SUPPLY_RAW_M_ITEMS - END');

    DBMS_OUTPUT.PUT_LINE('#TblPR_SCM_DNM_MAT_MRP_SUPPLY_RAW_S_TEMP - BEGIN');

    DELETE /* PR_SCM_DNM_MAT_MRP_SUPPLY */
      FROM GT_SDMMS_RAW_S_TEMP;

    INSERT /* PR_SCM_DNM_MAT_MRP_SUPPLY */
      INTO GT_SDMMS_RAW_S_TEMP
    SELECT A.*
      FROM GT_SDMMS_RAW A
     WHERE 1 = 1
       AND A.DATA_TYPE = 'S'
       AND A.ATTR_03   = 'Y';

    DBMS_OUTPUT.PUT_LINE('#TblPR_SCM_DNM_MAT_MRP_SUPPLY_RAW_S_TEMP - END');

    /*
    --TESTING : OK
    --select * from #TblPR_SCM_DNM_MAT_MRP_SUPPLY_RAW_S_TEMP;rollback tran;return;
    --select * from #TblPR_SCM_DNM_MAT_MRP_SUPPLY_RAW_S_TEMP where item_id = 'RET00649AA';rollback tran;return;
    */

    DBMS_OUTPUT.PUT_LINE('#TblPR_SCM_DNM_MAT_MRP_SUPPLY_RAW_S - BEGIN');

    DELETE /* PR_SCM_DNM_MAT_MRP_SUPPLY */
      FROM GT_SDMMS_RAW_S;

    /* S는 M & Y 인 plant_id, item_id 에 해당하는 것들중 ATTR_03 = 'Y' */
    INSERT /* PR_SCM_DNM_MAT_MRP_SUPPLY */
      INTO GT_SDMMS_RAW_S
    SELECT A.*
      FROM GT_SDMMS_RAW_S_TEMP  A
         , GT_SDMMS_RAW_M_ITEMS B
     WHERE A.PLANT_ID = B.PLANT_ID
       AND A.ITEM_ID  = B.ITEM_ID;

    DBMS_OUTPUT.PUT_LINE('#TblPR_SCM_DNM_MAT_MRP_SUPPLY_RAW_S - END');

    /*
    --TESTING : OK
    --select * from #TblPR_SCM_DNM_MAT_MRP_SUPPLY_RAW_S;rollback tran;return;
    --select * from #TblPR_SCM_DNM_MAT_MRP_SUPPLY_RAW_M;rollback tran;return;
    */

    DBMS_OUTPUT.PUT_LINE('#TblPR_SCM_DNM_MAT_MRP_SUPPLY_RAW_ALL_TEMP - BEGIN');

    DELETE /* PR_SCM_DNM_MAT_MRP_SUPPLY */
      FROM GT_SDMMS_RAW_ALL_TEMP;

    INSERT /* PR_SCM_DNM_MAT_MRP_SUPPLY */
      INTO GT_SDMMS_RAW_ALL_TEMP
    SELECT A.DATA_TYPE
         , A.CUTOFF_DATE
         , A.RTA
         , A.PLANT_ID
         , A.ITEM_ID
         , A.FACTORY_ID
         , A.SOC
         , A.QTY
         , A.ATTR_01
         , A.ATTR_02
         , A.ATTR_03
         , A.ATTR_04
         , A.ATTR_05
         , A.ATTR_06
         , A.ATTR_07
         , A.ATTR_08
         , A.ATTR_09
         , A.ATTR_10
      FROM (SELECT A.DATA_TYPE
                 , A.CUTOFF_DATE
                 , A.RTA
                 , A.PLANT_ID
                 , A.ITEM_ID
                 , A.FACTORY_ID
                 , A.SOC
                 , A.QTY
                 , A.ATTR_01
                 , A.ATTR_02
                 , A.ATTR_03
                 , A.ATTR_04
                 , A.ATTR_05
                 , A.ATTR_06
                 , A.ATTR_07
                 , A.ATTR_08
                 , A.ATTR_09
                 , A.ATTR_10
                 , ROW_NUMBER() OVER (PARTITION BY A.DATA_TYPE
                                                 , A.CUTOFF_DATE
                                                 , A.RTA
                                                 , A.PLANT_ID
                                                 , A.ITEM_ID
                                         ORDER BY A.ACCUM_DATE DESC)  AS RN
              FROM GT_SDMMS_RAW_M A
           ) A
     WHERE 1 = 1
       AND A.RN = 1;

    /*
    --TESTING : NOK
    --select * from #TblPR_SCM_DNM_MAT_MRP_SUPPLY_RAW_M;
    --select * from #TblPR_SCM_DNM_MAT_MRP_SUPPLY_RAW_ALL_TEMP;rollback tran;return;
    */

    /* S는 SCO 별로 여러개 존재하므로 SUM */
    INSERT /* PR_SCM_DNM_MAT_MRP_SUPPLY */
      INTO GT_SDMMS_RAW_ALL_TEMP
    SELECT A.DATA_TYPE
         , A.CUTOFF_DATE
         , A.RTA
         , A.PLANT_ID
         , A.ITEM_ID
         , CAST(NULL AS VARCHAR2(50 CHAR))    AS FACTORY_ID
         , CAST(NULL AS VARCHAR2(50 CHAR))    AS SOC
         , SUM(A.QTY)                         AS QTY
         , CAST(NULL AS VARCHAR2(200 CHAR))   AS ATTR_01
         , CAST(NULL AS VARCHAR2(200 CHAR))   AS ATTR_02
         , CAST(NULL AS VARCHAR2(200 CHAR))   AS ATTR_03
         , CAST(NULL AS VARCHAR2(200 CHAR))   AS ATTR_04
         , CAST(NULL AS VARCHAR2(200 CHAR))   AS ATTR_05
         , CAST(NULL AS VARCHAR2(1000 CHAR))  AS ATTR_06
         , CAST(NULL AS VARCHAR2(1000 CHAR))  AS ATTR_07
         , CAST(NULL AS VARCHAR2(1000 CHAR))  AS ATTR_08
         , CAST(NULL AS VARCHAR2(1000 CHAR))  AS ATTR_09
         , CAST(NULL AS VARCHAR2(1000 CHAR))  AS ATTR_10
      FROM GT_SDMMS_RAW_S A
     GROUP BY A.DATA_TYPE
            , A.CUTOFF_DATE
            , A.RTA
            , A.PLANT_ID
            , A.ITEM_ID;

    DBMS_OUTPUT.PUT_LINE('#TblPR_SCM_DNM_MAT_MRP_SUPPLY_RAW_ALL_TEMP - END');
    /*
    --TESTING : OK
    --select * from #TblPR_SCM_DNM_MAT_MRP_SUPPLY_RAW_ALL_TEMP;rollback tran;return;
    */

    DBMS_OUTPUT.PUT_LINE('#TblPR_SCM_DNM_MAT_MRP_SUPPLY_RAW_ALL - BEGIN');

    DELETE /* PR_SCM_DNM_MAT_MRP_SUPPLY */
      FROM GT_SDMMS_RAW_ALL;

    INSERT /* PR_SCM_DNM_MAT_MRP_SUPPLY */
      INTO GT_SDMMS_RAW_ALL
    SELECT A.DATA_TYPE
         , A.CUTOFF_DATE
         , A.RTA
         , A.PLANT_ID
         , A.ITEM_ID
         , A.FACTORY_ID
         , A.SOC
         , A.QTY
         , A.ATTR_01
         , A.ATTR_02
         , A.ATTR_03
         , A.ATTR_04
         , A.ATTR_05
         , A.ATTR_06
         , CASE WHEN A.ATTR_07 IS NULL THEN CAST(B.UOM AS VARCHAR2(1000 CHAR)) ELSE A.ATTR_07 END               AS ATTR_07
         , CASE WHEN A.ATTR_08 IS NULL THEN CAST(C.ITEM_CATEGORY AS VARCHAR2(1000 CHAR)) ELSE A.ATTR_08 END      AS ATTR_08
         , A.ATTR_09
         , A.ATTR_10
      FROM GT_SDMMS_RAW_ALL_TEMP       A
         , GT_SDMMS_CODE_UOM           B
         , GT_SDMMS_CODE_ITEM_CATEGORY C
     WHERE A.PLANT_ID = B.PLANT_ID(+)
       AND A.ITEM_ID  = B.ITEM_ID(+)
       AND A.PLANT_ID = C.PLANT_ID(+)
       AND A.ITEM_ID  = C.ITEM_ID(+);

    DBMS_OUTPUT.PUT_LINE('#TblPR_SCM_DNM_MAT_MRP_SUPPLY_RAW_ALL - END');

    /*
    --TESTING : OK
    --select * from #TblPR_SCM_DNM_MAT_MRP_SUPPLY_RAW_ALL;rollback tran;return;
    */

    IF V_TEST_MODE <> 'T' THEN                                       /* 테스트모드에서는 실제 DB 갱신없음 */
        DBMS_OUTPUT.PUT_LINE('DELETE dbo.SCM_DNM_MAT_MRP_SUPPLY - BEGIN');

        DELETE /* PR_SCM_DNM_MAT_MRP_SUPPLY */
          FROM SCM_DNM_MAT_MRP_SUPPLY A
         WHERE EXISTS (SELECT 1
                         FROM GT_SDMMS_RAW_ALL B
                        WHERE B.DATA_TYPE   = A.DATA_TYPE
                          AND B.CUTOFF_DATE = A.CUTOFF_DATE
                          AND B.RTA         = A.RTA
                          AND B.PLANT_ID    = A.PLANT_ID
                          AND B.ITEM_ID     = A.ITEM_ID);

        DBMS_OUTPUT.PUT_LINE('DELETE dbo.SCM_DNM_MAT_MRP_SUPPLY - DONE');

        /*
        --TESTING : OK
        --select * from dbo.SCM_DNM_MAT_MRP_SUPPLY;rollback tran;return;
        --select * from SCM_DNM_MAT_MRP_SUPPLY where CUTOFF_DATE = '20231106';rollback tran;return;
        */

        DBMS_OUTPUT.PUT_LINE('INSERT INTO dbo.SCM_DNM_MAT_MRP_SUPPLY - BEGIN');

        INSERT /* PR_SCM_DNM_MAT_MRP_SUPPLY */
          INTO SCM_DNM_MAT_MRP_SUPPLY
             ( DATA_TYPE
             , CUTOFF_DATE
             , RTA
             , PLANT_ID
             , ITEM_ID
             , FACTORY_ID
             , SOC
             , QTY
             , ATTR_01
             , ATTR_02
             , ATTR_03
             , ATTR_04
             , ATTR_05
             , ATTR_06
             , ATTR_07
             , ATTR_08
             , ATTR_09
             , ATTR_10
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , ATTRIBUTE6
             , ATTRIBUTE7
             , ATTRIBUTE8
             , ATTRIBUTE9
             , ATTRIBUTE10
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE )
        SELECT A.DATA_TYPE
             , A.CUTOFF_DATE
             , A.RTA
             , A.PLANT_ID
             , A.ITEM_ID
             , A.FACTORY_ID
             , A.SOC
             , A.QTY
             , A.ATTR_01
             , A.ATTR_02
             , A.ATTR_03
             , A.ATTR_04
             , A.ATTR_05
             , A.ATTR_06
             , A.ATTR_07
             , A.ATTR_08
             , A.ATTR_09
             , A.ATTR_10
             , CAST(NULL AS VARCHAR2(200 CHAR))         AS ATTRIBUTE1
             , CAST(NULL AS VARCHAR2(200 CHAR))         AS ATTRIBUTE2
             , CAST(NULL AS VARCHAR2(200 CHAR))         AS ATTRIBUTE3
             , CAST(NULL AS VARCHAR2(200 CHAR))         AS ATTRIBUTE4
             , CAST(NULL AS VARCHAR2(200 CHAR))         AS ATTRIBUTE5
             , CAST(NULL AS VARCHAR2(200 CHAR))         AS ATTRIBUTE6
             , CAST(NULL AS VARCHAR2(200 CHAR))         AS ATTRIBUTE7
             , CAST(NULL AS VARCHAR2(200 CHAR))         AS ATTRIBUTE8
             , CAST(NULL AS VARCHAR2(200 CHAR))         AS ATTRIBUTE9
             , CAST(NULL AS VARCHAR2(200 CHAR))         AS ATTRIBUTE10
             , CAST('scm_batch' AS VARCHAR2(150 CHAR))  AS CREATED_BY
             , SYSDATE                                  AS CREATION_DATE
             , CAST('scm_batch' AS VARCHAR2(150 CHAR))  AS LAST_UPDATED_BY
             , SYSDATE                                  AS LAST_UPDATE_DATE
          FROM GT_SDMMS_RAW_ALL A;

        DBMS_OUTPUT.PUT_LINE('INSERT INTO dbo.SCM_DNM_MAT_MRP_SUPPLY - DONE');
    END IF;

    /*
    --TESTING : OK
    --select * from SCM_DNM_MAT_MRP_SUPPLY where CUTOFF_DATE = '20231102';rollback tran;return;
    */

    IF V_TEST_MODE <> 'T' THEN                                       /* 테스트모드에서는 실제 DB 갱신없음 */
        /* 원본 : UPDATE A SET TRANSFER_FLAG='Y' FROM XIF A JOIN #RAW B ON A.IF_SEQ=B.IF_SEQ */
        UPDATE /* PR_SCM_DNM_MAT_MRP_SUPPLY */
               XIF_MRP_CUTOFF_SUPPLY_R_SN A
           SET A.TRANSFER_FLAG = 'Y'
         WHERE EXISTS (SELECT 1
                         FROM GT_SDMMS_RAW B
                        WHERE B.IF_SEQ = A.IF_SEQ);
    END IF;


    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;

    IF V_TEST_MODE <> 'T' THEN
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    END IF;

    COMMIT;

    DBMS_OUTPUT.PUT_LINE(V_LOG_MESSAGE);

    /* 원본 말미 임시테이블 DROP 블록 : GTT 는 세션 종료/다음 실행 시작 DELETE 로 정리 → 별도 조치 불요 */
EXCEPTION
    WHEN OTHERS THEN
        /* 원본 : IF (XACT_STATE() <> 0) ROLLBACK TRAN  → 명시 BEGIN TRAN 존재하므로 ROLLBACK 보존 */
        ROLLBACK;

        DBMS_OUTPUT.PUT_LINE('ERROR_PROCEDURE() : ' || $$PLSQL_UNIT);

        /*           원본 : 에러경로에서 SCM_SYS_LOG_BATCH 로 직접 INSERT (아래 원본 보존).
                  → ROLLBACK 후에도 에러로그 독립 커밋 유지(원본 MSSQL 이 ROLLBACK 후 INSERT 하던 의미와 등가).
           INSERT INTO SCM_SYS_LOG_BATCH
           ( PROGRAM_NAME, LOG_TYPE, LOG_COUNT, LOG_MESSAGE, DESCRIPTION, EVENT_DATE, */
        IF V_TEST_MODE <> 'T' THEN
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := '';
            D_EVENT_DATE  := SYSDATE;
            V_PROC_INPUT  := NULL;
            V_SQL_CODE    := TO_CHAR(SQLCODE);
            V_SQL_ERRMSG  := SQLERRM;
            V_BACKTRACE   := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;

            PR_SCM_SYS_LOG_BATCH(
                V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE
              , V_DESCRIPTION, D_EVENT_DATE, V_PROC_INPUT
              , V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE);
        END IF;

        /* 원본 : SELECT 'F' AS result_code / SELECT ERROR_LINE(), ERROR_NUMBER(), ERROR_MESSAGE() */
        DBMS_OUTPUT.PUT_LINE('result_code = F');
        DBMS_OUTPUT.PUT_LINE('ERROR_NO : ' || TO_CHAR(SQLCODE) || ' / ERROR_MSG : ' || SQLERRM);
        DBMS_OUTPUT.PUT_LINE('ERROR_BACKTRACE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
END PR_SCM_DNM_MAT_MRP_SUPPLY;

PROCEDURE         PR_SCM_DNM_STOCK_LOT_CONTROL
/*
 * Program ID   : PR_SCM_DNM_STOCK_LOT_CONTROL
 * Description  :  Pack 보류 재고
 * Program History
 *
 *===================================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================================
 * 2022.11.16   vadabi3        Initial Release PJ20216994 LGES Digital SCM 3 Level 가속화를 위한 개선 Phase 2 : XIF_QMS_LOT_CONTROL_R => SCM_DNM_STOCK_LOT_CONTROL
 * 2022.11.22   vadabi3        Batch정책	1, KEY = Inspection ID 기준 전체 IF 이므로 Inspection ID 기준으로 Delete / Insert 처리
                                            2, DIVISION 매핑은 ITEM 정보로 찾음
											3. CUTOFF DAY = 처리일자
 * 2026.07.06   ZIONEX         [PJ202650304]  NextSCM Migration
 *
 --------------------------------------------------------------------------------------------------------------------
 EXEC PR_SCM_DNM_STOCK_LOT_CONTROL
 */
AS

    /* LOG 용 변수 설정 */
    /* @SummaryOfChanges TABLE(CHANGE VARCHAR(20), IF_SEQ NVARCHAR(50)) : OUTPUT 미사용(항상 공백)으로 GTT/타입 미생성, 하단 조회도 제거 */
    V_BATCH_USER        VARCHAR2(150 CHAR) := 'scm_batch';
    V_PROGRAM_NAME      VARCHAR2(150 CHAR) := 'PR_SCM_DNM_STOCK_LOT_CONTROL';
    V_LOG_TYPE          VARCHAR2(30 CHAR);   /* START/END/ERROR/... */
    N_LOG_COUNT         NUMBER := 0;
    V_LOG_MESSAGE       VARCHAR2(1000 CHAR);
    V_DESCRIPTION       VARCHAR2(500 CHAR);
    D_EVENT_DATE        DATE;
    V_IFSEQNO           VARCHAR2(30 CHAR);
    N_SUCCESS_CNT       NUMBER;
    N_FAIL_CNT          NUMBER;
    V_BATCH_NO          VARCHAR2(20 CHAR);
    V_CUTOFF_DATE       VARCHAR2(8 CHAR);
    V_PRE_CUTOFF_DATE   VARCHAR2(8 CHAR);
BEGIN


    N_SUCCESS_CNT := 0 ;
    N_FAIL_CNT    := 0 ;
    V_CUTOFF_DATE     := TO_CHAR(SYSDATE-1, 'YYYYMMDD') ;
    V_PRE_CUTOFF_DATE := TO_CHAR(TO_DATE(V_CUTOFF_DATE, 'YYYYMMDD') - 1, 'YYYYMMDD') ;

    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);


    BEGIN

        /*------------------------------------------------------------------------------
            1. @batch_no / ATTR_10
        ------------------------------------------------------------------------------*/
        V_BATCH_NO := TO_CHAR(SYSDATE, 'YYYYMMDDHH24MISS');

        /* 처리 비대상 정보 */
        UPDATE XIF_QMS_LOT_CONTROL_R_SN
           SET PROC_FLAG = 'Y'
             , PROC_MSG  = PROC_MSG || '처리 비대상 ' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3')
             , PROC_DATE = SYSDATE
         WHERE INSP_MCLASS_CODE   NOT IN ('ECMM003')
           AND NVL(PROC_FLAG, 'N') = 'N';

        /*------------------------------------------------------------------------------
            1. XIF_QMS_LOT_CONTROL_R_SN 배치 대상 count
        ------------------------------------------------------------------------------*/
        UPDATE XIF_QMS_LOT_CONTROL_R_SN
           SET PROC_FLAG = 'P'
             , PROC_DATE = SYSDATE
             , ATTR_10   = V_BATCH_NO
         WHERE INSP_MCLASS_CODE   = 'ECMM003'
           AND NVL(PROC_FLAG, 'N') = 'N';

        N_LOG_COUNT := SQL%ROWCOUNT;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, 'STEP1', N_LOG_COUNT, '배치 대상 Count ( PROC_FLAG : N) ', V_DESCRIPTION, D_EVENT_DATE);

        /*-------------------------------------------------------------------------------------------------------------
            2. SCM_DNM_STOCK_LOT_CONTROL  :당일 정보가 처음 생성되는 경우 전일 정보를 당일 정보로 Copy
               당일 정보 존재 시 Skip
        -------------------------------------------------------------------------------------------------------------*/
        N_LOG_COUNT := 0;

        SELECT COUNT(*)
          INTO N_LOG_COUNT
          FROM SCM_DNM_STOCK_LOT_CONTROL
         WHERE CUTOFF_DATE = V_CUTOFF_DATE;

        SELECT MAX(CUTOFF_DATE)
          INTO V_PRE_CUTOFF_DATE
          FROM SCM_DNM_STOCK_LOT_CONTROL
         WHERE CUTOFF_DATE <  V_CUTOFF_DATE
           AND CUTOFF_DATE >= TO_CHAR(SYSDATE-3, 'YYYYMMDD');

        /* CUTOFF_DATE = @v_cutoff_date 에 정보 존재하면 Copy는 Skip 함 */
        /* 없으면 전일 정보를 Copy하여 당일 정보로 Insert함 */
        IF (N_LOG_COUNT < 1) THEN
            INSERT INTO SCM_DNM_STOCK_LOT_CONTROL
                 ( DIVISION_ID, SCM_SITE_ID, CUTOFF_DATE, ITEM_ID, ORG_ITEM_ID, QTY
                 , RELEASE_DATE, HOLD_START_DATE, HOLD_END_DATE, CHANGE_REQUEST_USER
                 , DIR, LOT_ID, PLANT_ID, SHOP_ID, LINE_ID, APPLY_PSN_ID, APPLY_DATE
                 , INSPECTION_ID, NOTE, INSP_LCLASS_CODE, INSP_MCLASS_CODE, RISK_RANGE_FLAG
                 , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                 , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
                 , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
            SELECT DIVISION_ID
                 , SCM_SITE_ID
                 , V_CUTOFF_DATE AS CUTOFF_DATE
                 , ITEM_ID
                 , ORG_ITEM_ID
                 , QTY
                 , RELEASE_DATE
                 , HOLD_START_DATE
                 , HOLD_END_DATE
                 , CHANGE_REQUEST_USER
                 , DIR, LOT_ID, PLANT_ID, SHOP_ID, LINE_ID, APPLY_PSN_ID, APPLY_DATE
                 , INSPECTION_ID, NOTE, INSP_LCLASS_CODE, INSP_MCLASS_CODE, RISK_RANGE_FLAG
                 , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                 , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
                 , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10
              FROM SCM_DNM_STOCK_LOT_CONTROL
             WHERE CUTOFF_DATE = V_PRE_CUTOFF_DATE
               AND DIR         = 'HOLD';

            N_LOG_COUNT := SQL%ROWCOUNT;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, 'STEP2', N_LOG_COUNT, 'SCM_DNM_STOCK_LOT_CONTROL > HOLD Copy ', V_DESCRIPTION, D_EVENT_DATE);
        END IF;

        /*-------------------------------------------------------------------------------------------------------------
            3. SCM_DNM_STOCK_LOT_CONTROL 에서 HOLD
            --> CUTOFF_DATE 배치시행일로 생성
            --> Inspection ID 기준 전체 IF 이므로 Inspection ID 기준으로 Delete / Insert 처리
        -------------------------------------------------------------------------------------------------------------*/
        N_LOG_COUNT := 0;

        DELETE
          FROM SCM_DNM_STOCK_LOT_CONTROL
         WHERE INSPECTION_ID IN (SELECT DISTINCT INSPECTION_ID
                                   FROM XIF_QMS_LOT_CONTROL_R_SN X
                                  WHERE 1 = 1
                                    AND PROC_FLAG = 'P')
           AND CUTOFF_DATE = V_CUTOFF_DATE;

        /*------------------------------------------------------------------------------
            3-1. CURSOR Start
            IF OBJECT_ID (N'CURSOR_CONTROL', N'U') IS NOT NULL DEALLOCATE CURSOR_CONTROL;
        ------------------------------------------------------------------------------*/

        BEGIN
            /* [PLANT_ID, PROD_ID, INSPECTION_ID] 기준으로 가장 최신 데이터 적용 */
            FOR REC IN (SELECT IF_SEQ
                          FROM (SELECT X.IF_SEQ
                                     , ROW_NUMBER() OVER (PARTITION BY PLANT_ID, PROD_ID, INSPECTION_ID ORDER BY IF_SEQ DESC) AS RANKNO
                                  FROM XIF_QMS_LOT_CONTROL_R_SN X
                                 WHERE 1 = 1
                                   AND PROC_FLAG = 'P') DATA
                         WHERE RANKNO = 1
                         ORDER BY IF_SEQ)
            LOOP

                /*------------------------------------------------------------------------------
                    3-1. MERGE INTO SCM_DNM_STOCK_LOT_CONTROL
                ------------------------------------------------------------------------------*/
                INSERT INTO SCM_DNM_STOCK_LOT_CONTROL
                     ( DIVISION_ID, SCM_SITE_ID, CUTOFF_DATE, ITEM_ID, ORG_ITEM_ID, QTY
                     , RELEASE_DATE, HOLD_START_DATE, HOLD_END_DATE, CHANGE_REQUEST_USER
                     , DIR, LOT_ID, PLANT_ID, SHOP_ID, LINE_ID, APPLY_PSN_ID, APPLY_DATE
                     , INSPECTION_ID, NOTE, INSP_LCLASS_CODE, INSP_MCLASS_CODE, RISK_RANGE_FLAG
                     , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                     , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
                     , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
                SELECT NVL(I.DIVISION_ID, '-') AS DIVISION_ID
                     , NVL(S.SCM_SITE_ID, '-') AS SCM_SITE_ID
                     /* , CONVERT(CHAR(8), IF_RCV_DATE, 112) AS CUTOFF_DATE */
                     , V_CUTOFF_DATE AS CUTOFF_DATE
                     , FN_GET_PACKER_PLAN_ITEM_ID(S.DIVISION_ID, X.PROD_ID) AS ITEM_ID
                     , X.PROD_ID AS ORG_ITEM_ID
                     , NVL(TO_NUMBER(X.ATTR_01), 0.0) AS QTY
                     , TO_CHAR(TO_DATE(X.ATTR_02), 'YYYYMMDD') AS RELEASE_DATE
                     , TO_CHAR(TO_DATE(X.ATTR_03), 'YYYYMMDD') AS HOLD_START_DATE
                     , TO_CHAR(TO_DATE(X.ATTR_04), 'YYYYMMDD') AS HOLD_END_DATE
                     , X.ATTR_05 AS CHANGE_REQUEST_USER
                     , X.DIR, X.LOT_ID, X.PLANT_ID, X.SHOP_ID, X.LINE_ID, X.APPLY_PSN_ID, X.APPLY_DATE
                     , X.INSPECTION_ID, X.NOTE, X.INSP_LCLASS_CODE, X.INSP_MCLASS_CODE, X.RISK_RANGE_FLAG
                     , V_BATCH_USER AS CREATED_BY
                     , SYSDATE AS CREATION_DATE
                     , V_BATCH_USER AS LAST_UPDATED_BY
                     , SYSDATE AS LAST_UPDATE_DATE
                     , NULL AS ATTRIBUTE1, NULL AS ATTRIBUTE2, NULL AS ATTRIBUTE3, NULL AS ATTRIBUTE4, NULL AS ATTRIBUTE5
                     , NULL AS ATTRIBUTE6, NULL AS ATTRIBUTE7, NULL AS ATTRIBUTE8, NULL AS ATTRIBUTE9
                     , X.IF_SEQ AS ATTRIBUTE10
                  FROM XIF_QMS_LOT_CONTROL_R_SN X
                     , (SELECT DISTINCT DIVISION_ID, ITEM_ID, OPERATION_GROUP_ID FROM SCM_MST_FINAL_ITEM_ORIGIN_DIV_V) I
                     , SCM_MST_SITE S
                 WHERE 1 = 1
                   AND X.PROD_ID            = I.ITEM_ID(+)
                   AND I.DIVISION_ID        = S.DIVISION_ID(+)
                   AND X.PLANT_ID           = S.PLANT_ID(+)
                   AND S.OPERATION_GROUP(+) = 'P'   /* PACK PLANT SITE로 처리 */
                   AND S.OSP_YN(+)          = 'Y'   /* 외주만 대상 */
                   AND S.VALID_YN(+)        = 'Y'
                   AND PROC_FLAG            = 'P'
                   AND X.IF_SEQ             = REC.IF_SEQ;
                /* OUTPUT $action, B.IF_SEQ INTO @SummaryOfChanges; */

                /*------------------------------------------------------------------------------
                    3-2.  배치 성공 처라
                ------------------------------------------------------------------------------*/
                UPDATE XIF_QMS_LOT_CONTROL_R_SN
                   SET PROC_FLAG = 'Y'
                 WHERE IF_SEQ    = REC.IF_SEQ
                   AND PROC_FLAG = 'P';

                N_LOG_COUNT := N_LOG_COUNT + SQL%ROWCOUNT;

            END LOOP;

        EXCEPTION
            WHEN OTHERS THEN

                /*   IF EXISTS (SELECT 1 FROM SYS.SYSCURSORS ...) BEGIN CLOSE/DEALLOCATE CURSOR_CONTROL END */
                NULL;

        END;

        /*------------------------------------------------------------------------------
            3-2.  처리 한 row 마킹
        ------------------------------------------------------------------------------*/
        /* select * from @SummaryOfChanges;  : OUTPUT 미적재로 항상 공백·소비자 없음(배치, OUT 없음) */

        UPDATE XIF_QMS_LOT_CONTROL_R_SN
           SET PROC_FLAG = 'S'
             , PROC_MSG  = PROC_MSG || '이관대상 제외 ' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3')
             , PROC_DATE = SYSDATE
         WHERE PROC_FLAG = 'P';

        /*----------------------------------------------------
            History LOG
        ----------------------------------------------------*/
        V_LOG_TYPE    := 'HISTORY';
        V_DESCRIPTION := '@n_history_seq' || ':' || TO_CHAR(N_SUCCESS_CNT);
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, 'Insert Count', N_LOG_COUNT, D_EVENT_DATE);

        IF DBMS_TRANSACTION.LOCAL_TRANSACTION_ID IS NOT NULL THEN
            COMMIT;
        END IF;


    EXCEPTION

        WHEN OTHERS THEN
            IF DBMS_TRANSACTION.LOCAL_TRANSACTION_ID IS NOT NULL THEN
                ROLLBACK;
            END IF;
            /*----------------------------------------------------
                Error LOG
            ----------------------------------------------------*/
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := 'ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
            D_EVENT_DATE  := SYSDATE;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_FAIL_CNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    END;

    /*----------------------------------------------------
        종료 LOG
    ----------------------------------------------------*/
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

END;

PROCEDURE PR_SCM_DNM_STOCK_OSP_V
(
      P_PLAN_START_YYYYMMDD           IN  VARCHAR2 DEFAULT NULL
)
/*
 * Program ID   : PR_SCM_DNM_STOCK_OSP_V
 * Description  : PR_SCM_DNM_STOCK_OSP_V (SCM_DNM_STOCK_V STOCK_TYPE = 'UPLOAD' -> SCM_DNM_STOCK 데이터 복사)
 * OutTable     :
 * Execute      :
 *
 *    SELECT * FROM SCM_SYS_LOG_BATCH with (nolock)  where [PROGRAM_NAME] ='PR_SCM_DNM_STOCK_OSP_V' order by CREATION_DATE desc
 *
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2026.04.22   강주용      E20260417-001783 STOCK OSP 재고 SCM_DNM_STOCK 추가 반영건
 *                          원본 PR_SCM_DNM_STOCK_V 이며 STOCK TYPE = UPLOAD 부분만 화요일 새벽까지 입력한 OSP STOCK 재처리 하도록 수정
 *                          대상 및 마감시간 관리 LOOKUP : STOCK_OSP_V_BAT_MGNT
 *                          DB JOB : 화요일 00시~ 05시 사이
 * 2026.07.06   ZIONEX   [PJ202650304] NextSCM Migration
 */
IS

    /* LOG 용 변수 설정 */
    V_BATCH_USER    VARCHAR2(150 CHAR) := 'SCP_batch';
    V_PROGRAM_NAME  VARCHAR2(150 CHAR) := 'PR_SCM_DNM_STOCK_OSP_V';
    V_LOG_TYPE      VARCHAR2(30 CHAR);   /* START/END/ERROR/... */
    N_LOG_COUNT     INTEGER := 0;
    V_LOG_MESSAGE   VARCHAR2(1000 CHAR);
    V_DESCRIPTION   VARCHAR2(500 CHAR);
    V_TABLE_ID      VARCHAR2(150 CHAR) := 'SCM_DNM_STOCK';
    D_EVENT_DATE    DATE;

    /* 로직 실행관련 변수 설정 */

    V_START_YYYYMMDD  VARCHAR2(8 CHAR) := CASE WHEN P_PLAN_START_YYYYMMDD IS NULL THEN TO_CHAR(SYSDATE - 2, 'YYYYMMDD') ELSE P_PLAN_START_YYYYMMDD END;   /* 데이터 복사 대상일 */

    /* 실행시간 확인용 */
    V_START_TIME    DATE := SYSDATE;
    V_EXEC_TIME     VARCHAR2(10 CHAR) := '';   /* '00:00' */


    V_PROC_CNT      NUMBER(5);
    V_ROW_CNT       NUMBER(5);
    V_WK_DAY        NUMBER(5);

    /* DECLARE @debug_mode            NVARCHAR(30) = 'T' */


    V_SQL_CODE      VARCHAR2(100 CHAR);
    V_SQL_ERRMSG    VARCHAR2(4000 CHAR);
    V_BACKTRACE     VARCHAR2(4000 CHAR);

BEGIN


    /* 원본 if object_id('tempdb..#TMP_STOCK_OSP_V') drop table : GTT 는 세션 지속(ON COMMIT PRESERVE) → 시작 시 DELETE 로 초기화(TRUNCATE 금지) */
    DELETE
      FROM GT_SDSOV_STOCK_OSP_V;

    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := V_PROGRAM_NAME || ':' || 'INSERT LOGIC';
    D_EVENT_DATE  := SYSDATE;
    PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER);

    BEGIN

        /* @WK_DAY = DATEPART(WEEKDAY, @v_start_yyyymmdd) : 원본은 집계 SELECT 에 동봉되나 테이블과 무관한 스칼라(항상 1행) → 별도 산출. */
        V_WK_DAY := MOD(TRUNC(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD')) - TRUNC(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD'), 'IW') + 1, 7) + 1;

        SELECT COUNT(1)
          INTO V_ROW_CNT
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
         WHERE LOOKUP_TYPE = 'STOCK_OSP_V_BAT_MGNT'
           AND VALID_YN    = 'Y'
           AND SEGMENT3   <= TO_CHAR(SYSDATE, 'HH24:MI')   /* CONVERT(VARCHAR(5),GETDATE(),108) = PROC_TIME 처리시간 (HH:MI) */
           AND ATTRIBUTE1 != V_START_YYYYMMDD;

        /* 입력 CUTOFF DATE로 처리할게 있고(ROW_CNT>0) 그 날이 일요일(WK_DAY=1) 일때 */
        IF (V_ROW_CNT > 0 AND V_WK_DAY = 1) THEN

            /* BEGIN TRAN : Oracle 은 DML 로 트랜잭션 자동 시작 → 무대응. 최종 COMMIT 은 커서 루프 뒤에서 수행 */

            INSERT
              INTO GT_SDSOV_STOCK_OSP_V
                 ( SCM_SITE_ID, COMPANY_ID, DIVISION_ID, SITE_ID, PLANT_ID, FACTORY_ID, STORAGE_ID
                 , CUTOFF_DATE
                 , SEQ, STOCK_TYPE, ITEM_ID, ORIGIN_ITEM_ID, SCM_QTY, SSP_QTY, LANE, PRODUCTION_TYPE, AVAILABLE_DATE, REMAIN_LEAD_TIME, HOLDING_DATE
                 , QTY, QTY_UOM, STOCK_STATUS, OPERATION_ID, LINE_ID, OUTSOURCING_FLAG, OUTSOURCING_FACTORY, DESCRIPTION, FP_APPLY_OPERATION_ID
                 , FP_APPLY_ITEM_ID, FP_APPLY_WIPQTY, WIPHOLD_YN, QMS_HOLD_YN, WIP_TYPE_CODE, QTY2, MODIFY_FP_APPLY_WIPQTY, MODIFY_DESCRIPTION
                 , CAL_QTY, FORMATION_REWORK_TYPE, INSERT_ID, INSERT_TIME, UPDATE_ID, UPDATE_TIME, LOCATION, MOVING_QTY, CAPA_GRD_CODE, VLTG_GRD_CODE, RSST_GRD_CODE
                 , DEFECT_QTY, UNHOLD_EXP_DATE, MES_MAP_SLOC, MES_HOLD_YN, MES_UNHOLD_DATE, QMS_HOLD_DATE, QMS_UNHOLD_EXP_DATE, QMS_UNHOLD_DATE, OPERATION_ID_ORG, LOCATION_CODE
                   /* 20230327 E20230327-000187 : 재고 이전/특별 재고 관련 컬럼 추가 */
                 , MES_ITEM_ID, MES_OPERATION_ID, FROM_SLOC_ID, CUSTOMER_ID, SPECIAL_STOCK_INDICATOR )
            SELECT A.SCM_SITE_ID, A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.PLANT_ID, A.FACTORY_ID, A.STORAGE_ID
                 , TO_CHAR(A.CUTOFF_DATE, 'YYYYMMDD') AS CUTOFF_DATE
                 , A.SEQ, A.STOCK_TYPE, A.ITEM_ID, A.ORIGIN_ITEM_ID, A.SCM_QTY, A.SSP_QTY, A.LANE, A.PRODUCTION_TYPE, A.AVAILABLE_DATE, A.REMAIN_LEAD_TIME, A.HOLDING_DATE
                 , A.QTY, A.QTY_UOM, A.STOCK_STATUS, A.OPERATION_ID, A.LINE_ID, A.OUTSOURCING_FLAG, A.OUTSOURCING_FACTORY, A.DESCRIPTION, A.FP_APPLY_OPERATION_ID
                 , A.FP_APPLY_ITEM_ID, A.FP_APPLY_WIPQTY, A.WIPHOLD_YN, A.QMS_HOLD_YN, A.WIP_TYPE_CODE, A.QTY2, A.MODIFY_FP_APPLY_WIPQTY, A.MODIFY_DESCRIPTION
                 , A.CAL_QTY, A.FORMATION_REWORK_TYPE, A.INSERT_ID, A.INSERT_TIME, A.UPDATE_ID, A.UPDATE_TIME, A.LOCATION, A.MOVING_QTY, A.CAPA_GRD_CODE, A.VLTG_GRD_CODE, A.RSST_GRD_CODE
                 , A.DEFECT_QTY, A.UNHOLD_EXP_DATE, A.MES_MAP_SLOC, A.MES_HOLD_YN, A.MES_UNHOLD_DATE, A.QMS_HOLD_DATE, A.QMS_UNHOLD_EXP_DATE, A.QMS_UNHOLD_DATE, A.OPERATION_ID_ORG, A.LOCATION_CODE
                   /* 20230327 E20230327-000187 : 재고 이전/특별 재고 관련 컬럼 추가 */
                 , A.MES_ITEM_ID, A.MES_OPERATION_ID, A.FROM_SLOC_ID, A.CUSTOMER_ID, A.SPECIAL_STOCK_INDICATOR
              FROM SCM_DNM_STOCK_V              A   /* WITH (NOLOCK) 제거: Oracle 읽기 일관성으로 무대응 */
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
             WHERE A.DIVISION_ID = B.SEGMENT1
               AND A.SCM_SITE_ID = B.SEGMENT2
               AND B.LOOKUP_TYPE = 'STOCK_OSP_V_BAT_MGNT'
               AND B.VALID_YN    = 'Y'
               AND A.STOCK_TYPE  = 'UPLOAD'
               AND B.SEGMENT3   <= TO_CHAR(SYSDATE, 'HH24:MI')   /* CONVERT(VARCHAR(5),GETDATE(),108) = PROC_TIME 처리시간 (HH:MI) */
               AND B.ATTRIBUTE1 != V_START_YYYYMMDD

               AND A.CUTOFF_DATE = TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD');

            /* DECLARE CUR_STOCK_OSP_V CURSOR ... OPEN/FETCH/WHILE → FOR 루프 */
            FOR R IN (SELECT SEGMENT1 AS DIVISION_ID
                           , SEGMENT2 AS SCM_SITE_ID
                        FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                       WHERE LOOKUP_TYPE = 'STOCK_OSP_V_BAT_MGNT'
                         AND VALID_YN    = 'Y'
                         AND SEGMENT3   <= TO_CHAR(SYSDATE, 'HH24:MI')   /* CONVERT(VARCHAR(5),GETDATE(),108) = PROC_TIME 처리시간 (HH:MI) */
                         AND ATTRIBUTE1 != V_START_YYYYMMDD)
            LOOP

                DELETE
                  FROM SCM_DNM_STOCK
                 WHERE CUTOFF_DATE = V_START_YYYYMMDD
                   AND DIVISION_ID = R.DIVISION_ID
                   AND SCM_SITE_ID = R.SCM_SITE_ID
                   AND STOCK_TYPE  = 'UPLOAD';

                INSERT
                  INTO SCM_DNM_STOCK
                     ( SCM_SITE_ID, COMPANY_ID, DIVISION_ID, SITE_ID, PLANT_ID, FACTORY_ID, STORAGE_ID
                     , CUTOFF_DATE
                     , SEQ, STOCK_TYPE, ITEM_ID, ORIGIN_ITEM_ID, SCM_QTY, SSP_QTY, LANE, PRODUCTION_TYPE, AVAILABLE_DATE, REMAIN_LEAD_TIME, HOLDING_DATE
                     , QTY, QTY_UOM, STOCK_STATUS, OPERATION_ID, LINE_ID, OUTSOURCING_FLAG, OUTSOURCING_FACTORY, DESCRIPTION, FP_APPLY_OPERATION_ID
                     , FP_APPLY_ITEM_ID, FP_APPLY_WIPQTY, WIPHOLD_YN, QMS_HOLD_YN, WIP_TYPE_CODE, QTY2, MODIFY_FP_APPLY_WIPQTY, MODIFY_DESCRIPTION
                     , CAL_QTY, FORMATION_REWORK_TYPE, INSERT_ID, INSERT_TIME, UPDATE_ID, UPDATE_TIME, LOCATION, MOVING_QTY, CAPA_GRD_CODE, VLTG_GRD_CODE, RSST_GRD_CODE
                     , DEFECT_QTY, UNHOLD_EXP_DATE, MES_MAP_SLOC, MES_HOLD_YN, MES_UNHOLD_DATE, QMS_HOLD_DATE, QMS_UNHOLD_EXP_DATE, QMS_UNHOLD_DATE, OPERATION_ID_ORG, LOCATION_CODE
                       /* 20230327 E20230327-000187 : 재고 이전/특별 재고 관련 컬럼 추가 */
                     , MES_ITEM_ID, MES_OPERATION_ID, FROM_SLOC_ID, CUSTOMER_ID, SPECIAL_STOCK_INDICATOR
                     , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE )
                SELECT SCM_SITE_ID, COMPANY_ID, DIVISION_ID, SITE_ID, PLANT_ID, FACTORY_ID, STORAGE_ID, CUTOFF_DATE
                     , SEQ, STOCK_TYPE, ITEM_ID, ORIGIN_ITEM_ID, SCM_QTY, SSP_QTY, LANE, PRODUCTION_TYPE, AVAILABLE_DATE, REMAIN_LEAD_TIME, HOLDING_DATE
                     , QTY, QTY_UOM, STOCK_STATUS, OPERATION_ID, LINE_ID, OUTSOURCING_FLAG, OUTSOURCING_FACTORY, DESCRIPTION, FP_APPLY_OPERATION_ID
                     , FP_APPLY_ITEM_ID, FP_APPLY_WIPQTY, WIPHOLD_YN, QMS_HOLD_YN, WIP_TYPE_CODE, QTY2, MODIFY_FP_APPLY_WIPQTY, MODIFY_DESCRIPTION
                     , CAL_QTY, FORMATION_REWORK_TYPE, INSERT_ID, INSERT_TIME, UPDATE_ID, UPDATE_TIME, LOCATION, MOVING_QTY, CAPA_GRD_CODE, VLTG_GRD_CODE, RSST_GRD_CODE
                     , DEFECT_QTY, UNHOLD_EXP_DATE, MES_MAP_SLOC, MES_HOLD_YN, MES_UNHOLD_DATE, QMS_HOLD_DATE, QMS_UNHOLD_EXP_DATE, QMS_UNHOLD_DATE, OPERATION_ID_ORG, LOCATION_CODE
                       /* 20230327 E20230327-000187 : 재고 이전/특별 재고 관련 컬럼 추가 */
                     , MES_ITEM_ID, MES_OPERATION_ID, FROM_SLOC_ID, CUSTOMER_ID, SPECIAL_STOCK_INDICATOR
                     , 'SCP_batch' CREATED_BY, SYSDATE CREATION_DATE, 'SCP_batch' LAST_UPDATED_BY, SYSDATE LAST_UPDATE_DATE
                  FROM GT_SDSOV_STOCK_OSP_V
                 WHERE DIVISION_ID = R.DIVISION_ID
                   AND SCM_SITE_ID = R.SCM_SITE_ID;

                V_PROC_CNT := SQL%ROWCOUNT;

                UPDATE SCM_ADM_LOOKUP_MASTER_DETAIL
                   SET ATTRIBUTE1       = V_START_YYYYMMDD
                     , ATTRIBUTE2       = V_PROC_CNT
                     , LAST_UPDATED_BY  = 'SCP_batch'
                     , LAST_UPDATE_DATE = SYSDATE
                 WHERE LOOKUP_TYPE = 'STOCK_OSP_V_BAT_MGNT'
                   AND SEGMENT1    = R.DIVISION_ID
                   AND SEGMENT2    = R.SCM_SITE_ID;

            END LOOP;   /* OPEN CUR_STOCK_OSP_V */

            COMMIT;

        END IF;   /* IF @ROW_CNT > 0 */

        /* TXN LOG */
        V_LOG_TYPE    := 'TXN';
        /* 캐비앗(C1 계열): 원본은 END IF 직후 @@ROWCOUNT 를 로그건수로 읽음(직전 DML 건수). Oracle SQL%ROWCOUNT 는 COMMIT 후에도 직전 DML 건수를 유지. 진단 로그 전용·데이터 무영향이라 현행 위치 유지. */
        N_LOG_COUNT   := SQL%ROWCOUNT;
        V_LOG_MESSAGE := 'INSERT INTO ' || V_TABLE_ID;
        V_DESCRIPTION := 'Process Complete...' || ':' || TO_CHAR(D_EVENT_DATE, 'YYYYMMDD');
        D_EVENT_DATE  := SYSDATE;

        PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER);

    EXCEPTION
        WHEN OTHERS THEN
            ROLLBACK;   /* 원본 XACT_ABORT ON + CATCH(주석처리된 ROLLBACK) : 오류 시 트랜잭션 원복 */
            V_SQL_CODE    := TO_CHAR(SQLCODE);
            V_SQL_ERRMSG  := SQLERRM;
            V_BACKTRACE   := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;

            /* ERROR LOG */
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);

            V_DESCRIPTION := V_PROGRAM_NAME || 'ERROR_LINE : ';
            D_EVENT_DATE  := SYSDATE;
            PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER, JSON_OBJECT('P_PLAN_START_YYYYMMDD' VALUE P_PLAN_START_YYYYMMDD RETURNING VARCHAR2(4000 CHAR)), V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE);

            /*      PRINT @@ERROR */
            RETURN;
    END;


    DELETE
      FROM GT_SDSOV_STOCK_OSP_V;


    V_EXEC_TIME := CASE WHEN LENGTH(TO_CHAR(TRUNC(ROUND((SYSDATE - V_START_TIME) * 86400) / 60))) > 2 THEN NULL
                        ELSE LPAD(TO_CHAR(TRUNC(ROUND((SYSDATE - V_START_TIME) * 86400) / 60)), 2, '0') || ':' ||
                            LPAD(TO_CHAR(MOD(ROUND((SYSDATE - V_START_TIME) * 86400), 60)), 2, '0')
                   END;

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '[' || V_PROGRAM_NAME || '][' || V_EXEC_TIME || '], start_yyyymmdd (' || V_START_YYYYMMDD || ')';
    D_EVENT_DATE  := SYSDATE;
    PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER);


END PR_SCM_DNM_STOCK_OSP_V;

PROCEDURE PR_SCM_DNM_STOCK_V
(
      P_PLAN_START_YYYYMMDD           IN  VARCHAR2 DEFAULT NULL
)
/*
 * Program ID   : PR_SCM_DNM_STOCK_V
 * Description  : PR_SCM_DNM_STOCK_V (SCM_DNM_STOCK_V -> SCM_DNM_STOCK 데이터 복사)
 * OutTable     :
 * Execute      :
 *
 *    SELECT * FROM SCM_SYS_LOG_BATCH with (nolock)  where [PROGRAM_NAME] ='PR_SCM_DNM_STOCK_V' order by CREATION_DATE desc
 *
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2022.01.04   sclee.lee      Initial Release PJ20216891 LGES Digital SCM 3 Level 가속화를 위한 개선 : Stock_v -> Stock 테이블로 생성
 * 2023.03.27   KSG            E20230327-000187 [SCM물류PI팀] 재고 테이블 SCM_DNM_STOCK 개선 (GSCM 시스템의 재고 정합성 개선을 위한) : 재고 이전/특별 재고 관련 컬럼 추가
 * 2026.07.06   ZIONEX   [PJ202650304] NextSCM Migration
 */
IS

    /* LOG 용 변수 설정 */
    V_BATCH_USER    VARCHAR2(150 CHAR) := 'SCP_batch';
    V_PROGRAM_NAME  VARCHAR2(150 CHAR) := 'PR_SCM_DNM_STOCK_V';
    V_LOG_TYPE      VARCHAR2(30 CHAR);   /* START/END/ERROR/... */
    N_LOG_COUNT     INTEGER := 0;
    V_LOG_MESSAGE   VARCHAR2(1000 CHAR);
    V_DESCRIPTION   VARCHAR2(500 CHAR);
    V_TABLE_ID      VARCHAR2(150 CHAR) := 'SCM_DNM_STOCK';
    D_EVENT_DATE    DATE;

    /* 로직 실행관련 변수 설정 */

    V_START_YYYYMMDD  VARCHAR2(8 CHAR) := CASE WHEN P_PLAN_START_YYYYMMDD IS NULL THEN TO_CHAR(SYSDATE - 1, 'YYYYMMDD') ELSE P_PLAN_START_YYYYMMDD END;  /* 데이터 복사 대상일 */
    V_END_YYYYMMDD    VARCHAR2(8 CHAR) := TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') + 1, 'YYYYMMDD');

    /* 실행시간 확인용 */
    V_START_TIME    DATE := SYSDATE;
    V_EXEC_TIME     VARCHAR2(10 CHAR) := '';   /* '00:00' */


    V_SQL_CODE      VARCHAR2(100 CHAR);
    V_SQL_ERRMSG    VARCHAR2(4000 CHAR);
    V_BACKTRACE     VARCHAR2(4000 CHAR);

BEGIN


    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := V_PROGRAM_NAME || ':' || 'INSERT LOGIC';
    D_EVENT_DATE  := SYSDATE;
    PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER);

    BEGIN


        DELETE
          FROM SCM_DNM_STOCK
         WHERE CUTOFF_DATE BETWEEN V_START_YYYYMMDD AND V_END_YYYYMMDD;


        INSERT
          INTO SCM_DNM_STOCK
             ( SCM_SITE_ID, COMPANY_ID, DIVISION_ID, SITE_ID, PLANT_ID, FACTORY_ID, STORAGE_ID
             , CUTOFF_DATE
             , SEQ, STOCK_TYPE, ITEM_ID, ORIGIN_ITEM_ID, SCM_QTY, SSP_QTY, LANE, PRODUCTION_TYPE, AVAILABLE_DATE, REMAIN_LEAD_TIME, HOLDING_DATE
             , QTY, QTY_UOM, STOCK_STATUS, OPERATION_ID, LINE_ID, OUTSOURCING_FLAG, OUTSOURCING_FACTORY, DESCRIPTION, FP_APPLY_OPERATION_ID
             , FP_APPLY_ITEM_ID, FP_APPLY_WIPQTY, WIPHOLD_YN, QMS_HOLD_YN, WIP_TYPE_CODE, QTY2, MODIFY_FP_APPLY_WIPQTY, MODIFY_DESCRIPTION
             , CAL_QTY, FORMATION_REWORK_TYPE, INSERT_ID, INSERT_TIME, UPDATE_ID, UPDATE_TIME, LOCATION, MOVING_QTY, CAPA_GRD_CODE, VLTG_GRD_CODE, RSST_GRD_CODE
             , DEFECT_QTY, UNHOLD_EXP_DATE, MES_MAP_SLOC, MES_HOLD_YN, MES_UNHOLD_DATE, QMS_HOLD_DATE, QMS_UNHOLD_EXP_DATE, QMS_UNHOLD_DATE, OPERATION_ID_ORG, LOCATION_CODE
               /* 20230327 E20230327-000187 : 재고 이전/특별 재고 관련 컬럼 추가 */
             , MES_ITEM_ID, MES_OPERATION_ID, FROM_SLOC_ID, CUSTOMER_ID, SPECIAL_STOCK_INDICATOR
             , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE )
        SELECT SCM_SITE_ID, COMPANY_ID, DIVISION_ID, SITE_ID, PLANT_ID, FACTORY_ID, STORAGE_ID
             , TO_CHAR(CUTOFF_DATE, 'YYYYMMDD') AS CUTOFF_DATE
             , SEQ, STOCK_TYPE, ITEM_ID, ORIGIN_ITEM_ID, SCM_QTY, SSP_QTY, LANE, PRODUCTION_TYPE, AVAILABLE_DATE, REMAIN_LEAD_TIME, HOLDING_DATE
             , QTY, QTY_UOM, STOCK_STATUS, OPERATION_ID, LINE_ID, OUTSOURCING_FLAG, OUTSOURCING_FACTORY, DESCRIPTION, FP_APPLY_OPERATION_ID
             , FP_APPLY_ITEM_ID, FP_APPLY_WIPQTY, WIPHOLD_YN, QMS_HOLD_YN, WIP_TYPE_CODE, QTY2, MODIFY_FP_APPLY_WIPQTY, MODIFY_DESCRIPTION
             , CAL_QTY, FORMATION_REWORK_TYPE, INSERT_ID, INSERT_TIME, UPDATE_ID, UPDATE_TIME, LOCATION, MOVING_QTY, CAPA_GRD_CODE, VLTG_GRD_CODE, RSST_GRD_CODE
             , DEFECT_QTY, UNHOLD_EXP_DATE, MES_MAP_SLOC, MES_HOLD_YN, MES_UNHOLD_DATE, QMS_HOLD_DATE, QMS_UNHOLD_EXP_DATE, QMS_UNHOLD_DATE, OPERATION_ID_ORG, LOCATION_CODE
               /* 20230327 E20230327-000187 : 재고 이전/특별 재고 관련 컬럼 추가 */
             , MES_ITEM_ID, MES_OPERATION_ID, FROM_SLOC_ID, CUSTOMER_ID, SPECIAL_STOCK_INDICATOR
             , 'SCP_batch' CREATED_BY, SYSDATE CREATION_DATE, 'SCP_batch' LAST_UPDATED_BY, SYSDATE LAST_UPDATE_DATE
          FROM SCM_DNM_STOCK_V   /* WITH (NOLOCK) 제거: Oracle 읽기 일관성으로 무대응 */

         WHERE CUTOFF_DATE BETWEEN TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') AND TO_DATE(V_END_YYYYMMDD, 'YYYYMMDD');

        COMMIT;

        /* TXN LOG */
        V_LOG_TYPE    := 'TXN';
        /* 캐비앗(C1 계열): 원본은 COMMIT 직후 @@ROWCOUNT 를 로그건수로 읽음. Oracle SQL%ROWCOUNT 는 COMMIT 후에도 직전 INSERT 건수를 유지(MSSQL @@ROWCOUNT 는 COMMIT 후 상이 가능). 진단 로그 전용·데이터 무영향이므로 현행 위치 유지. */
        N_LOG_COUNT   := SQL%ROWCOUNT;
        V_LOG_MESSAGE := 'INSERT INTO ' || V_TABLE_ID;
        V_DESCRIPTION := 'Process Complete...' || ':' || TO_CHAR(D_EVENT_DATE, 'YYYYMMDD');
        D_EVENT_DATE  := SYSDATE;

        PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER);

    EXCEPTION
        WHEN OTHERS THEN
            ROLLBACK;
            V_SQL_CODE    := TO_CHAR(SQLCODE);
            V_SQL_ERRMSG  := SQLERRM;
            V_BACKTRACE   := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;

            /* ERROR LOG */
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);

            V_DESCRIPTION := V_PROGRAM_NAME || 'ERROR_LINE : ';
            D_EVENT_DATE  := SYSDATE;
            PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER, JSON_OBJECT('P_PLAN_START_YYYYMMDD' VALUE P_PLAN_START_YYYYMMDD RETURNING VARCHAR2(4000 CHAR)), V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE);

            RETURN;
    END;


    V_EXEC_TIME := CASE WHEN LENGTH(TO_CHAR(TRUNC(ROUND((SYSDATE - V_START_TIME) * 86400) / 60))) > 2 THEN NULL
                        ELSE LPAD(TO_CHAR(TRUNC(ROUND((SYSDATE - V_START_TIME) * 86400) / 60)), 2, '0') || ':' ||
                            LPAD(TO_CHAR(MOD(ROUND((SYSDATE - V_START_TIME) * 86400), 60)), 2, '0')
                   END;

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '[' || V_PROGRAM_NAME || '][' || V_EXEC_TIME || '], start_yyyymmdd (' || V_START_YYYYMMDD || ')';
    D_EVENT_DATE  := SYSDATE;
    PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER);


END PR_SCM_DNM_STOCK_V;

PROCEDURE PR_SCM_ITEM_LINE_VERSION
--@p_master_id nvarchar(MAX) = '-',
--@p_plan_id nvarchar(MAX) = '-'
IS

 -- 변수 정의

    V_MASTER_ID         VARCHAR2(30 CHAR);
    V_PLAN_ID           VARCHAR2(30 CHAR);
    V_COMFIRM_AREA      VARCHAR2(30 CHAR);
    V_RELEASE_GROUP     VARCHAR2(30 CHAR);
    V_START_MIN         NUMBER(20,10);
    V_ALARM_YN          VARCHAR2(30 CHAR);
    V_KEY_MONTH         VARCHAR2(6 CHAR);
--  SET   @key_date     = CONVERT( DATE, GETDATE() )

  -- LOG 용 변수 설정
    V_PROC_NAME         VARCHAR2(100 CHAR) := 'PR_SCM_ITEM_LINE_VERSION';
    V_TABLE_NAME        VARCHAR2(100 CHAR);
    V_MESSAGE           VARCHAR2(250 CHAR);
    V_DESCR             VARCHAR2(250 CHAR);
    V_N_ROW_COUNT       NUMBER(10) := 0;
    V_N_LOG_COUNT       NUMBER(10) := 0;
    V_LOG_CODE          VARCHAR2(10 CHAR);
    V_SYSDATE           DATE := SYSDATE;
    V_TEMP1             VARCHAR2(1000 CHAR);
    V_TEMP2             VARCHAR2(1000 CHAR);
BEGIN

    V_MASTER_ID := 'E_PRE ALL INSTANCE';
    V_PLAN_ID   := 'E_PRE ALL INSTANCE';

    /* AS-IS : ERROR_LINE() 은 CATCH 블록 밖에서 항상 NULL 이므로 두 변수는 결국 NULL 이 된다.
       Oracle 의 || 는 NULL 을 빈 문자로 다루어 'S' 가 남으므로 원문 결과인 NULL 을 그대로 대입한다. */
    V_TEMP1 := NULL;
    V_TEMP2 := NULL;

    V_N_LOG_COUNT := V_N_LOG_COUNT + 1;
    V_SYSDATE := SYSDATE;
    /* PR_LOG_PROCESS(V_SYSDATE, V_MASTER_ID, V_PLAN_ID, V_PROC_NAME, NULL, 'START', V_N_LOG_COUNT, NULL, '############### Start of procedure ###############', V_DESCR); */

  /*
  변수 설정
  */

    BEGIN

      -- 계획 수립일 설정
        V_TABLE_NAME := 'SCM_FP_PLAN_H';

        /* CONVERT(NVARCHAR(6), GETDATE(), 112) : 112 는 YYYYMMDD 서식이고 6자리로 잘려 YYYYMM 이 된다. */
        V_KEY_MONTH := TO_CHAR(SYSDATE, 'YYYYMM');

      --LOG 생성
        V_MESSAGE := 'KEY_MONTH : ' || V_KEY_MONTH;
        V_N_LOG_COUNT := V_N_LOG_COUNT + 1;
        V_SYSDATE := SYSDATE;
        /* PR_LOG_PROCESS(NULL, V_MASTER_ID, V_PLAN_ID, V_PROC_NAME, V_TABLE_NAME, 'SELECT', V_N_LOG_COUNT, NULL, V_MESSAGE, NULL); */

    END;

    BEGIN

    -- 로직 시작
        --------------------------------------------------
        -- 1. ITEM LINE VERSION DATA INSERT
        --    신규 LINE ASSIGN DATA 기준 VERSION 정보 INSERT
        --------------------------------------------------

        INSERT INTO SCM_MST_ITEM_CONV_CALC_USE_SN
             ( COMPANY_ID
             , DIVISION_ID
             , SITE_ID
             , PLANT_ID
             , FACTORY_ID
             , OPERATION_ID
             , MODEL_ID
             , ITEM_ID
             , LINE_ID
             , ELECTRODE_TYPE
             , VERSION
             , ACTIVE_FLAG
             , DESCRIPTION
             , INSERT_ID
             , INSERT_TIME
             , UPDATE_ID
             , UPDATE_TIME
             )
        SELECT DISTINCT A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.FACTORY_ID
             , A.OPERATION_ID
             , C.MODEL_ID
             , A.ITEM_ID
             , A.LINE_ID
             , A.ELECTRODE_TYPE
             , C.VERSION
             , 'Y'           AS ACTIVE_FLAG
             , TO_CHAR(NULL) AS DESCRIPTION
             , V_PROC_NAME   AS INSERT_ID
             , SYSDATE       AS INSERT_TIME
             , V_PROC_NAME   AS UPDATE_ID
             , SYSDATE       AS UPDATE_TIME
          FROM SCM_ITEM_LINE_ASSIGN_M A
             , SCM_LINE_M B
             , SCM_ITEM_CONV_CALC_M C
         WHERE 1 = 1
           AND A.OPERATION_ID = 'E2000'
           AND A.MONTH = V_KEY_MONTH
           AND A.ACTIVE_FLAG = 'Y'
           AND A.COMPANY_ID = B.COMPANY_ID
           AND A.DIVISION_ID = B.DIVISION_ID
           AND A.SITE_ID = B.SITE_ID
           AND A.OPERATION_ID = B.OPERATION_ID
           AND A.FACTORY_ID = B.FACTORY_ID
           AND A.LINE_ID = B.LINE_ID
           AND A.ELECTRODE_TYPE = B.ELECTRODE_TYPE
           AND A.ACTIVE_FLAG = 'Y'
           AND A.COMPANY_ID = C.COMPANY_ID
           AND A.DIVISION_ID = C.DIVISION_ID
           AND A.SITE_ID = C.SITE_ID
           AND A.OPERATION_ID = C.OPERATION
           AND A.FACTORY_ID = C.FACTORY_ID
           AND A.ITEM_ID = C.ITEM_ID
           AND B.PROD_VERSION_TYPE = C.PROD_VERSION_TYPE
           AND NOT EXISTS ( SELECT 1
                              FROM SCM_MST_ITEM_CONV_CALC_USE_SN X
                             WHERE 1 = 1
                               AND A.COMPANY_ID = X.COMPANY_ID
                               AND A.DIVISION_ID = X.DIVISION_ID
                               AND A.SITE_ID = X.SITE_ID
                               AND A.PLANT_ID = X.PLANT_ID
                               AND A.OPERATION_ID = X.OPERATION_ID
                               AND C.MODEL_ID = X.MODEL_ID
                               AND A.ITEM_ID = X.ITEM_ID
                               AND A.LINE_ID = X.LINE_ID
                               AND A.ELECTRODE_TYPE = X.ELECTRODE_TYPE
                               AND C.VERSION = X.VERSION )
         GROUP BY A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.FACTORY_ID
             , A.OPERATION_ID
             , C.MODEL_ID
             , A.ITEM_ID
             , A.LINE_ID
             , A.ELECTRODE_TYPE
             , C.VERSION;

        V_N_ROW_COUNT := SQL%ROWCOUNT;

        --LOG 생성
        V_TABLE_NAME := 'SCM_ITEM_CONV_CALC_USE_M';
        V_MESSAGE := TO_CHAR(V_N_ROW_COUNT);
        V_DESCR := NULL;
        V_N_LOG_COUNT := V_N_LOG_COUNT + 1;
        V_SYSDATE := SYSDATE;
        /* PR_LOG_PROCESS(NULL, V_MASTER_ID, V_PLAN_ID, V_PROC_NAME, V_TABLE_NAME, 'INSERT', V_N_LOG_COUNT, NULL, V_MESSAGE, V_DESCR); */

  --- 후미 ---
    EXCEPTION
        WHEN OTHERS THEN
    --ROLLBACK

            V_DESCR := SUBSTR(SQLERRM, 1, 250);
            V_SYSDATE := SYSDATE;

            V_N_LOG_COUNT := V_N_LOG_COUNT + 1;
            /* PR_LOG_PROCESS(V_SYSDATE, V_MASTER_ID, V_PLAN_ID, V_PROC_NAME, NULL, 'ERROR', V_N_LOG_COUNT, V_TEMP2, NULL, V_DESCR); */
            COMMIT;
    END;

    V_N_LOG_COUNT := V_N_LOG_COUNT + 1;
    /* PR_LOG_PROCESS(V_SYSDATE, V_MASTER_ID, V_PLAN_ID, V_PROC_NAME, NULL, 'END', 999999, NULL, '############### End of procedure ###############', NULL); */

END PR_SCM_ITEM_LINE_VERSION;

PROCEDURE PR_SCM_KPI_PROJECTROUTE_BOM
(
    P_BASIS_YYYYMMDD  IN VARCHAR2 DEFAULT NULL
)
/* ============================================================
 * Program ID   : PR_SCM_KPI_PROJECTROUTE_BOM
 * Description  : Project Route, BOM 준수율 데이타 생성 : 매주 화요일 새벽 당주 정보 생성
 * OutTable     :
 * Execute      :
 * Program History
 *------------------------------------------------------------
 *   Date       In Charge      Description
 *------------------------------------------------------------
 * 2019.04.17   hwyoon         Initial Release [CSR ID:3977249] [지표정의] GSCM Portal - SCP HI 지표 산출
 * 2021.03.30   PJG            대체 BOM 모델링 적용
 * 2021.10.06   sclee.lee      PJ20214907 LGES SCP 계획 수립 시간 단축 및 분석 기능 강화 : RTF개선
 * 2022.03.25   sclee          PJ20216891 LGES Digital SCM 3 Level 가속화를 위한 개선 - 새사업부 추가
 * 2022.11.15   KSG            PJ20216994 / LGES Digital SCM 3 Level 가속화를 위한 개선 Phase 2 - MKT FCST 조건 변경
 * 2023.03.23   hrkim          [PJ20230691R] LGES SCM 역량 강화 위한 SCP 개선과제 이행 : HM JV 가상 사업부 추가 반영
 *                             (다수 참조 테이블 NOLOCK 옵션 추가)
 * 2026.07.06   ZIONEX   [PJ202650304] NextSCM Migration
 * ============================================================ */
IS
/* LOG 용 변수 설정 */
    V_BATCH_USER      VARCHAR2(150 CHAR) := 'scm_batch_PRJBOM';
    V_PROGRAM_NAME    VARCHAR2(150 CHAR) := 'PR_SCM_KPI_PROJECTROUTE_BOM';
    V_LOG_TYPE        VARCHAR2(30 CHAR);  /* START/END/ERROR/... */
    N_LOG_COUNT       NUMBER := 0;
    V_LOG_MESSAGE     VARCHAR2(1000 CHAR);
    V_DESCRIPTION     VARCHAR2(500 CHAR);
    V_TABLE_ID        VARCHAR2(150 CHAR) := 'SCM_KPI_PROJECTROUTE_BOM';
    D_EVENT_DATE      DATE;

/* 업무용 변수 */
    V_BASIS_YYYYMMDD  VARCHAR2(8 CHAR);  /* 기준 일자 */
    V_PLAN_ID         VARCHAR2(8 CHAR);
    N_ROWS            NUMBER;

/* PJ20216891 */
/* DECLARE @p_division_id nvarchar(max) = '40,81,82'; */
    V_P_DIVISION_ID   VARCHAR2(4000 CHAR) := '';  /* '40,81,82,81_UC'; */
    V_DIVISION_ID     VARCHAR2(4000 CHAR) := '';

    N_MAX_LOOP_CNT    NUMBER := 0;
    N_MST_LOOP_CNT    NUMBER := 0;
    V_DELIMITER       VARCHAR2(1 CHAR) := ',';

    V_P_FROM_YYYYMMDD VARCHAR2(8 CHAR) := '';
    V_P_TO_YYYYMMDD   VARCHAR2(8 CHAR) := '';
    V_FROM_YYYYMMDD   VARCHAR2(8 CHAR) := '';
    V_TO_YYYYMMDD     VARCHAR2(8 CHAR) := '';
    V_FROM_RESULT     VARCHAR2(8 CHAR) := '';
    V_TO_RESULT       VARCHAR2(8 CHAR) := '';
    V_UNIT_DATE       VARCHAR2(8 CHAR) := '';  /* 현재일 기준의 주(week)의 시작일자 */

    V_P_STATUS        VARCHAR2(6 CHAR) := NULL;

    V_EXISTS_81       NUMBER;

    V_MQUERY          CLOB;
    V_MEXEC           CLOB;


BEGIN
/* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := V_PROGRAM_NAME || ':' || ' SCM_KPI_PROJECTROUTE_BOM INSERT LOGIC';
    D_EVENT_DATE  := SYSDATE;
    PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER);

/* [PJ20230691R] LGES SCM 역량 강화 위한 SCP 개선과제 이행 : HM JV 가상 사업부 추가 반영 */
/* 원본 STUFF(FOR XML PATH) 문자열집계 → LISTAGG (40,81,82,81_HM,81_UC) */
    SELECT LISTAGG(DIVISION_ID, ',') WITHIN GROUP (ORDER BY SUBSTR(DIVISION_ID, 1, 1), LENGTH(DIVISION_ID), DIVISION_ID)
      INTO V_P_DIVISION_ID
      FROM SCM_MST_DIVISION
     WHERE 1 = 1
       AND ATTRIBUTE3 != 'EE'
       AND VALID_YN   = 'Y';

    BEGIN
/* ---------------------------------------------------------------------------------- */
/* 매주 일요일에 월요일 일자로 적재한다. */
/* ---------------------------------------------------------------------------------- */
/* 기준일자 설정 */
        IF P_BASIS_YYYYMMDD IS NOT NULL THEN
            V_BASIS_YYYYMMDD := P_BASIS_YYYYMMDD;
        ELSE
            V_BASIS_YYYYMMDD := TO_CHAR(SYSDATE, 'YYYYMMDD');  /* 현재일자 */
        END IF;

/* from_yyyymmdd는 현재일자의 월요일로 강제설정 */
        SELECT TO_CHAR(F.BASIS_YYYYMMDD - (F.DAYOFWEEK_NO - 1), 'YYYYMMDD') AS BASIS_START_DATE
          INTO V_P_FROM_YYYYMMDD
          FROM ( SELECT (CASE WHEN DAYOFWEEK_NO - 1 = 0 THEN 7 ELSE DAYOFWEEK_NO - 1 END) DAYOFWEEK_NO
                       ,TO_DATE(BASIS_YYYYMMDD, 'YYYYMMDD') AS BASIS_YYYYMMDD
                       ,DAYOFWEEK
                   FROM SCM_SYS_CALENDAR_M
                  WHERE BASIS_YYYYMMDD = V_BASIS_YYYYMMDD
               ) F;

/* 52주 설정 */
        V_P_TO_YYYYMMDD := TO_CHAR(TO_DATE(V_P_FROM_YYYYMMDD, 'YYYYMMDD') + 364 - 1, 'YYYYMMDD');

        SELECT C.BASIS_START_DATE
          INTO V_UNIT_DATE
          FROM SCM_SYS_CALENDAR_M C
         WHERE 1 = 1
           AND C.BASIS_YYYYMMDD = TO_CHAR(SYSDATE, 'YYYYMMDD');

        IF ( V_UNIT_DATE >= V_P_FROM_YYYYMMDD AND V_UNIT_DATE <= V_P_TO_YYYYMMDD ) THEN
            V_FROM_RESULT   := V_P_FROM_YYYYMMDD;
            V_TO_RESULT     := V_UNIT_DATE;
            V_FROM_YYYYMMDD := V_UNIT_DATE;
            V_TO_YYYYMMDD   := V_P_TO_YYYYMMDD;
            IF ( V_P_FROM_YYYYMMDD = V_UNIT_DATE ) THEN
                V_FROM_RESULT := '';
                V_TO_RESULT   := '';
            END IF;
        ELSIF ( V_UNIT_DATE < V_P_FROM_YYYYMMDD AND V_UNIT_DATE < V_P_TO_YYYYMMDD ) THEN
            V_FROM_YYYYMMDD := V_P_FROM_YYYYMMDD;
            V_TO_YYYYMMDD   := V_P_TO_YYYYMMDD;
            V_FROM_RESULT   := '';
            V_TO_RESULT     := '';
        ELSIF ( V_UNIT_DATE > V_P_FROM_YYYYMMDD AND V_UNIT_DATE > V_P_TO_YYYYMMDD ) THEN
            V_FROM_YYYYMMDD := '';
            V_TO_YYYYMMDD   := '';
            V_FROM_RESULT   := V_P_FROM_YYYYMMDD;
            V_TO_RESULT     := V_P_TO_YYYYMMDD;
        END IF;

/* 주차 데이터 삭제 */
        DELETE FROM SCM_KPI_PROJECTROUTE_BOM
         WHERE PLAN_START_YYYYMMDD = V_FROM_YYYYMMDD;

        N_LOG_COUNT   := SQL%ROWCOUNT;
        V_LOG_TYPE    := '';
        V_LOG_MESSAGE := 'SCM_KPI_PROJECTROUTE_BOM';
        V_DESCRIPTION := 'DELETE';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        /********************************************************************************
        * 임시테이블만들기 - 본 테이블 (원본 #TblDynamicPivot_ProjectRoute → GTT PRESERVE)
        ********************************************************************************/
        DELETE FROM GT_SKPB_PROJECTROUTE;

/* 프로시저 LOOP 길이를 판단 */
        N_MAX_LOOP_CNT := SCM_ARR_SPL_CNT(V_P_DIVISION_ID, V_DELIMITER);

        WHILE N_MST_LOOP_CNT < N_MAX_LOOP_CNT LOOP
/* @mst_loop_cnt 1증가 */
            N_MST_LOOP_CNT := N_MST_LOOP_CNT + 1;

/* 각 컬럼들에 대한 스플릿처리로직 스타트 */
            V_DIVISION_ID := SCM_ARR_SPL_VAL(V_P_DIVISION_ID, V_DELIMITER, N_MST_LOOP_CNT);

/* LOOP 파라미터 출력 DEBUG용 */
            DBMS_OUTPUT.PUT_LINE('@v_division_id    = ' || V_DIVISION_ID);

            /********************************************************************************
            * 임시테이블만들기 (원본 #tmp1/#tmp2 DROP → GTT DELETE)
            ********************************************************************************/
            DELETE FROM GT_SKPB_PROJECTROUTE_TMP1;
            DELETE FROM GT_SKPB_PROJECTROUTE_TMP2;

/* PJ20216891 */
/* IF( @v_division_id = '81' ) */
/* IF( @v_division_id IN ('81', '81_UC') ) */
/* [PJ20230691R] LGES SCM 역량 강화 위한 SCP 개선과제 이행 : HM JV 가상 사업부 추가 반영 */
            SELECT COUNT(*)
              INTO V_EXISTS_81
              FROM SCM_MST_DIVISION
             WHERE 1 = 1
               AND DIVISION_ID = V_DIVISION_ID
               AND ATTRIBUTE3  = '81'
               AND VALID_YN    = 'Y'
               AND ROWNUM      = 1;

            IF V_EXISTS_81 > 0 THEN
/* 81 자동차 사업부 */
                INSERT INTO GT_SKPB_PROJECTROUTE_TMP1
                     ( DIVISION_ID, DIVISION_NAME, SCM_SITE_ID, PROJECT_CODE, ITEM_ID, PLANT_PER_ITEM, CMPLTD_STATUS, MONTH, QTY )
                SELECT T.DIVISION_ID
                     , FN_GET_DIVISION_NAME(T.DIVISION_ID) AS DIVISION_NAME
                     , T.SCM_SITE_ID
                     , T.PROJECT_CODE
                     , T.ITEM_ID
                     , CASE WHEN U.PLANT_PER_ITEM IS NULL THEN 'BOM' ELSE U.PLANT_PER_ITEM END AS PLANT_PER_ITEM
                     , NVL(U.CMPLTD_STATUS, 'N') AS CMPLTD_STATUS
                     , '' AS MONTH  /* substring(yyyymmdd,1,6) AS month */
                     , 1  AS QTY  /* t.qty */
                  FROM ( SELECT DISTINCT A.DIVISION_ID, PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID
                           FROM DM_PLN_MKT_FCST A
                           JOIN SCM_MST_ITEM_SN B ON A.DIVISION_ID = B.DIVISION_ID AND A.ITEM_ID = B.ITEM_ID
                           LEFT JOIN SCM_MST_SITE S ON S.DIVISION_ID = A.DIVISION_ID AND S.SCM_SITE_ID = A.SCM_SITE_ID AND S.VMI_YN = 'Y'
                          WHERE 1 = 1
                            AND A.DIVISION_ID = V_DIVISION_ID
                            /* PJ20214907 */  /* 20221115 PJ20216994 MKT FCST 조건 변경 */
/* AND a.MEASURE = IIF( ISNULL(s.vmi_yn, 'N') = 'Y', 'VMI_In_Req',  'MKT_FCST') */
/* AND a.MEASURE = IIF(ISNULL(s.operation_group, '') = 'W', 'AS_In_Req', IIF(ISNULL(s.vmi_yn, 'N') = 'Y', 'VMI_In_Req',  'MKT_FCST')) */
                            AND A.MEASURE = CASE WHEN S.OPERATION_GROUP = 'W' THEN 'AS_In_Req' WHEN S.VMI_YN = 'Y' THEN 'VMI_In_Req' WHEN RTRIM(A.ATTRIBUTE10) IS NULL THEN 'MKT_FCST' END
                            AND B.SCP_OPERATION_GROUP_ID <> 'E'
                            AND A.YYYYMMDD >= V_FROM_YYYYMMDD
                            AND A.YYYYMMDD <= V_TO_YYYYMMDD
                            AND RTRIM(A.YYYYMMDD) IS NOT NULL AND A.YYYYMMDD IS NOT NULL
                            AND A.QTY > 0
                         UNION ALL
                         SELECT DISTINCT A.DIVISION_ID, PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID
                           FROM DM_PLN_MKT_FCST_RESULT A
                           JOIN SCM_MST_ITEM_SN B ON A.DIVISION_ID = B.DIVISION_ID AND A.ITEM_ID = B.ITEM_ID
                           LEFT JOIN SCM_MST_SITE S ON S.DIVISION_ID = A.DIVISION_ID AND S.SCM_SITE_ID = A.SCM_SITE_ID AND S.VMI_YN = 'Y'
                          WHERE 1 = 1
                            AND A.DIVISION_ID = V_DIVISION_ID
                            /* PJ20214907 */  /* 20221115 PJ20216994 MKT FCST 조건 변경 */
/* AND a.MEASURE = IIF( ISNULL(s.vmi_yn, 'N') = 'Y', 'VMI_In_Req',  'MKT_FCST') */
/* AND a.MEASURE = IIF(ISNULL(s.operation_group, '') = 'W', 'AS_In_Req', IIF(ISNULL(s.vmi_yn, 'N') = 'Y', 'VMI_In_Req',  'MKT_FCST')) */
                            AND A.MEASURE = CASE WHEN S.OPERATION_GROUP = 'W' THEN 'AS_In_Req' WHEN S.VMI_YN = 'Y' THEN 'VMI_In_Req' WHEN RTRIM(A.ATTRIBUTE10) IS NULL THEN 'MKT_FCST' END
                            AND B.SCP_OPERATION_GROUP_ID <> 'E'
                            AND A.YYYYMMDD >= V_FROM_RESULT
                            AND A.YYYYMMDD <= V_TO_RESULT
                            AND RTRIM(A.YYYYMMDD) IS NOT NULL AND A.YYYYMMDD IS NOT NULL
                            AND A.QTY > 0
                       ) T
                       /*******************start of 수량 카운트 부분 ********************************************************************************/
                       LEFT OUTER JOIN ( SELECT DIVISION_ID
                                              , SCM_SITE_ID
                                              , PROJECT_CODE
                                              , MODEL_ID
                                              , TO_CHAR(SUM(PLANT_CNT)) || '/' || TO_CHAR(TOT_CNT) AS PLANT_PER_ITEM
                                              , CASE WHEN SUM(PLANT_CNT) = TOT_CNT THEN 'Y' ELSE 'N' END CMPLTD_STATUS
                                           FROM ( SELECT DIVISION_ID, SCM_SITE_ID, PROJECT_CODE, MODEL_ID
                                                       , COUNT(*) OVER (PARTITION BY DIVISION_ID, SCM_SITE_ID, PROJECT_CODE, MODEL_ID) AS TOT_CNT
                                                       , CASE WHEN PRIMARY_PLANT IS NOT NULL THEN 1 ELSE 0 END AS PLANT_CNT
                                                    FROM ( SELECT DISTINCT
                                                                  (CASE
                                                                    WHEN FN_GET_ITEM_OPERATION_GROUP(A.DIVISION_ID, A.ITEM_ID) = 'E' THEN C.ITEM_ID
                                                                    ELSE B.MODEL_ID
                                                                   END ) AS MODEL_ID
                                                                , (CASE
/* 전극 제외 20180517 */
                                                                    WHEN D.OPERATION_GROUP_ID = 'A' THEN 'Cell'
                                                                    WHEN D.OPERATION_GROUP_ID = 'P' THEN 'Pack'
                                                                   END ) AS OPERATION_GROUP_ID
                                                                , D.ELECTRODE_TYPE
                                                                , B.CHILD_ITEM_ID AS ITEM_ID
                                                                , ( SELECT ROWNUMBER
                                                                      FROM ( SELECT ROW_NUMBER() OVER (ORDER BY FROM_YYYYMMDD) AS ROWNUMBER
                                                                               FROM SCM_MST_SITE_ITEM_PRIORITY S
                                                                              WHERE S.DIVISION_ID   = B.DIVISION_ID
                                                                                AND S.ITEM_ID       = B.CHILD_ITEM_ID
                                                                                AND S.PROJECT_CODE  = A.PROJECT_CODE
                                                                                AND S.SALES_SITE_ID = A.SCM_SITE_ID   /* 20180326 sales site 추가부분 */
                                                                                AND S.TO_YYYYMMDD  >= TO_CHAR(SYSDATE, 'YYYYMMDD')
                                                                                AND S.VALID_YN = 'Y'
                                                                                AND S.PRIORITY = '1'
                                                                           ) A
                                                                     WHERE ROWNUMBER = 1
                                                                  ) AS PRIMARY_PLANT
                                                                , B.DIVISION_ID
                                                                , A.SCM_SITE_ID
                                                                , A.PROJECT_CODE
                                                             FROM DM_PLN_MKT_FCST A
/* 2021.03.30 대체 BOM 모델링 */
/* JOIN scm_mst_bom_sn b    ON a.division_id   = b.division_id */
                                                                  JOIN SCM_MST_BOM_SN_V B ON A.DIVISION_ID = B.DIVISION_ID
                                                                                        AND A.ITEM_ID     = B.MODEL_ID
                                                                  JOIN SCM_MST_ITEM_SN C ON B.COMPANY_ID    = C.COMPANY_ID
                                                                                        AND B.DIVISION_ID   = C.DIVISION_ID
                                                                                        AND B.SITE_ID       = C.SITE_ID
                                                                                        AND B.CHILD_ITEM_ID = C.ITEM_ID
                                                                  JOIN SCM_MST_FINAL_ITEM_V D ON B.DIVISION_ID = D.DIVISION_ID AND B.CHILD_ITEM_ID = D.ITEM_ID
                                                                  LEFT JOIN SCM_MST_SITE S ON S.DIVISION_ID = A.DIVISION_ID AND S.SCM_SITE_ID = A.SCM_SITE_ID AND S.VMI_YN = 'Y'
                                                            WHERE 1 = 1
