                                                              AND EXISTS ( SELECT 1
                                                                             FROM SCM_MST_BOM_ENG_SN
                                                                            WHERE DIVISION_ID = V_DIVISION_ID
                                                                              AND PARENT_ITEM_ID = B.CHILD_ITEM_ID
/* BOM을 제거모델 조회안되도록 수정 */
                                                                              AND EFF_END_DATE >= SYSDATE
                                                                              AND KEY_DATE = ( SELECT MAX(KEY_DATE)
                                                                                                 FROM SCM_MST_BOM_ENG_SN
                                                                                                WHERE PARENT_ITEM_ID = B.CHILD_ITEM_ID
                                                                                                  AND DIVISION_ID = V_DIVISION_ID )
                                                                         )
                                                         ) M
                                                ) N
                                          GROUP BY DIVISION_ID, SCM_SITE_ID, PROJECT_CODE, MODEL_ID, TOT_CNT
                                       ) U ON T.DIVISION_ID  = U.DIVISION_ID
                                          AND T.SCM_SITE_ID  = U.SCM_SITE_ID
                                          AND T.PROJECT_CODE = U.PROJECT_CODE
                                          AND T.ITEM_ID      = U.MODEL_ID
                       /******************end of 수량카운트********************************************************************************************/
                       INNER JOIN SCM_MST_SITE_ITEM V ON T.DIVISION_ID  = V.DIVISION_ID
                                                     AND T.ITEM_ID      = V.ITEM_ID
                                                     AND T.SCM_SITE_ID  = V.SCM_SITE_ID
                                                     AND T.PROJECT_CODE = V.PROJECT_CODE
                       INNER JOIN ( SELECT DIVISION_ID, ITEM_ID, NICK_NAME, ITEM_TYPE
                                         , ROW_NUMBER() OVER ( PARTITION BY DIVISION_ID, ITEM_ID ORDER BY CASE ITEM_TYPE WHEN 'P' THEN 999 WHEN 'H' THEN 888 WHEN 'R' THEN 777 WHEN 'Q' THEN 666 ELSE 0 END DESC ) NUMS
                                      FROM SCM_MST_ITEM_SN
                                  ) I ON T.DIVISION_ID = I.DIVISION_ID
                                     AND T.ITEM_ID     = I.ITEM_ID
                                     AND I.NUMS = 1
                 WHERE 1 = 1
                   AND I.ITEM_TYPE NOT IN ('Q', 'R')
                   /* PJ20214907 */
                   AND T.MEASURE IN ('VMI_In_Req', 'MKT_FCST', 'AS_In_Req')
                   AND T.DIVISION_ID = V_DIVISION_ID
/* AND ( ( @p_scm_site_id  IS NULL OR  @p_scm_site_id  ='' ) OR t.scm_site_id   IN (SELECT token FROM dbo.String_Split(@p_scm_site_id	,',')) )   20180326 sale site 추가부분   */
/* AND ( ( @p_project_code IS NULL OR  @p_project_code ='' ) OR t.project_code  IN (SELECT token FROM dbo.String_Split(@p_project_code	,',')) ) */
/* AND ( ( @p_item_id      IS NULL OR  @p_item_id      ='' ) OR t.item_id       IN (SELECT token FROM dbo.String_Split(@p_item_id		,',')) ) */
                   AND ( ( V_P_STATUS IS NULL ) OR U.CMPLTD_STATUS IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(V_P_STATUS, ','))) );

            ELSIF ( V_DIVISION_ID = '82' OR V_DIVISION_ID = '40' ) THEN
/* 40 소형, 82 ESS */
                INSERT INTO GT_SKPB_PROJECTROUTE_TMP2
                     ( DIVISION_ID, DIVISION_NAME, SCM_SITE_ID, PROJECT_CODE, ITEM_ID, PLANT_PER_ITEM, CMPLTD_STATUS, MONTH, QTY )
                SELECT T.DIVISION_ID
                     , FN_GET_DIVISION_NAME(T.DIVISION_ID) AS DIVISION_NAME
                     , T.SCM_SITE_ID
                     , T.PROJECT_CODE
                     , T.ITEM_ID
                     , CASE WHEN U.PLANT_PER_ITEM IS NULL THEN 'BOM' ELSE U.PLANT_PER_ITEM END AS PLANT_PER_ITEM
                     , NVL(U.CMPLTD_STATUS, 'N') AS CMPLTD_STATUS
                     , '' AS MONTH  /* substring(yyyymmdd,1,6) AS month */
                     , 1  AS QTY  /* t.qty */
                  FROM ( SELECT DISTINCT A.DIVISION_ID
                              , '-' AS PROJECT_CODE
                              , '-' AS SCM_SITE_ID
                              , A.ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID
                           FROM DM_PLN_MKT_FCST A
                           JOIN SCM_MST_ITEM_SN B ON A.DIVISION_ID = B.DIVISION_ID AND A.ITEM_ID = B.ITEM_ID
                           LEFT JOIN SCM_MST_SITE S ON S.DIVISION_ID = A.DIVISION_ID AND S.SCM_SITE_ID = A.SCM_SITE_ID AND S.VMI_YN = 'Y'
                          WHERE 1 = 1
                            AND A.DIVISION_ID = V_DIVISION_ID
                            /* PJ20214907 */  /* 20221115 PJ20216994 MKT FCST 조건 변경 */
/* AND a.MEASURE = IIF( ISNULL(s.vmi_yn, 'N') = 'Y', 'VMI_In_Req',  'MKT_FCST') */
/* AND a.MEASURE = IIF(ISNULL(s.operation_group, '') = 'W', 'AS_In_Req', IIF(ISNULL(s.vmi_yn, 'N') = 'Y', 'VMI_In_Req',  'MKT_FCST')) */
                            AND A.MEASURE = CASE WHEN S.OPERATION_GROUP = 'W' THEN 'AS_In_Req' WHEN S.VMI_YN = 'Y' THEN 'VMI_In_Req' WHEN RTRIM(A.ATTRIBUTE10) IS NULL THEN 'MKT_FCST' END
                            AND B.SCP_OPERATION_GROUP_ID <> 'E'
                            AND A.YYYYMMDD >= V_FROM_YYYYMMDD
                            AND A.YYYYMMDD <= V_TO_YYYYMMDD
                            AND RTRIM(A.YYYYMMDD) IS NOT NULL AND A.YYYYMMDD IS NOT NULL
                            AND A.QTY > 0
                         UNION ALL
                         SELECT DISTINCT A.DIVISION_ID
                              , '-' AS PROJECT_CODE
                              , '-' AS SCM_SITE_ID
                              , A.ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID
                           FROM DM_PLN_MKT_FCST_RESULT A
                           JOIN SCM_MST_ITEM_SN B ON A.DIVISION_ID = B.DIVISION_ID AND A.ITEM_ID = B.ITEM_ID
                           LEFT JOIN SCM_MST_SITE S ON S.DIVISION_ID = A.DIVISION_ID AND S.SCM_SITE_ID = A.SCM_SITE_ID AND S.VMI_YN = 'Y'
                          WHERE 1 = 1
                            AND A.DIVISION_ID = V_DIVISION_ID
                            /* PJ20214907 */  /* 20221115 PJ20216994 MKT FCST 조건 변경 */
/* AND a.MEASURE = IIF( ISNULL(s.vmi_yn, 'N') = 'Y', 'VMI_In_Req',  'MKT_FCST') */
/* AND a.MEASURE = IIF(ISNULL(s.operation_group, '') = 'W', 'AS_In_Req', IIF(ISNULL(s.vmi_yn, 'N') = 'Y', 'VMI_In_Req',  'MKT_FCST')) */
                            AND A.MEASURE = CASE WHEN S.OPERATION_GROUP = 'W' THEN 'AS_In_Req' WHEN S.VMI_YN = 'Y' THEN 'VMI_In_Req' WHEN RTRIM(A.ATTRIBUTE10) IS NULL THEN 'MKT_FCST' END
                            AND B.SCP_OPERATION_GROUP_ID <> 'E'
                            AND A.YYYYMMDD >= V_FROM_RESULT
                            AND A.YYYYMMDD <= V_TO_RESULT
                            AND RTRIM(A.YYYYMMDD) IS NOT NULL AND A.YYYYMMDD IS NOT NULL
                            AND A.QTY > 0
                       ) T
                       /*******************start of 수량 카운트 부분 ********************************************************************************/
                       LEFT OUTER JOIN ( SELECT DIVISION_ID
                                              , SCM_SITE_ID
                                              , PROJECT_CODE
                                              , MODEL_ID
                                              , TO_CHAR(SUM(PLANT_CNT)) || '/' || TO_CHAR(TOT_CNT) AS PLANT_PER_ITEM
                                              , CASE WHEN SUM(PLANT_CNT) = TOT_CNT THEN 'Y' ELSE 'N' END CMPLTD_STATUS
                                           FROM ( SELECT DIVISION_ID, '-' AS SCM_SITE_ID, '-' AS PROJECT_CODE, MODEL_ID
                                                       , COUNT(*) OVER (PARTITION BY DIVISION_ID, MODEL_ID) AS TOT_CNT
                                                       , CASE WHEN PRIMARY_PLANT IS NOT NULL THEN 1 ELSE 0 END AS PLANT_CNT
                                                    FROM ( SELECT DISTINCT
                                                                  (CASE WHEN FN_GET_ITEM_OPERATION_GROUP(A.DIVISION_ID, A.ITEM_ID) = 'E' THEN C.ITEM_ID
                                                                        ELSE B.MODEL_ID
                                                                   END ) AS MODEL_ID
                                                                , (CASE
/* 전극 제외 20180517 */
                                                                    WHEN D.OPERATION_GROUP_ID = 'A' THEN 'Cell'
                                                                    WHEN D.OPERATION_GROUP_ID = 'P' THEN 'Pack'
                                                                   END ) AS OPERATION_GROUP_ID
                                                                , D.ELECTRODE_TYPE
                                                                , B.CHILD_ITEM_ID AS ITEM_ID
                                                                , ( SELECT ROWNUMBER
                                                                      FROM ( SELECT ROW_NUMBER() OVER (ORDER BY FROM_YYYYMMDD) AS ROWNUMBER
                                                                               FROM SCM_MST_SITE_ITEM_PRIORITY S
                                                                              WHERE S.DIVISION_ID = B.DIVISION_ID
                                                                                AND S.ITEM_ID     = B.CHILD_ITEM_ID
                                                                                AND S.TO_YYYYMMDD >= TO_CHAR(SYSDATE, 'YYYYMMDD')
                                                                                AND S.VALID_YN = 'Y'
                                                                                AND S.PRIORITY = '1'
                                                                           ) A
                                                                     WHERE ROWNUMBER = 1
                                                                  ) AS PRIMARY_PLANT
                                                                , B.DIVISION_ID
                                                             FROM DM_PLN_MKT_FCST A
/* JOIN scm_mst_bom_sn  b   ON a.division_id   = b.division_id */
                                                                  JOIN SCM_MST_BOM_SN_V B ON A.DIVISION_ID = B.DIVISION_ID
                                                                                        AND A.ITEM_ID     = B.MODEL_ID
                                                                  JOIN SCM_MST_ITEM_SN C ON B.COMPANY_ID    = C.COMPANY_ID
                                                                                        AND B.DIVISION_ID   = C.DIVISION_ID
                                                                                        AND B.SITE_ID       = C.SITE_ID
                                                                                        AND B.CHILD_ITEM_ID = C.ITEM_ID
                                                                  JOIN SCM_MST_FINAL_ITEM_V D ON B.DIVISION_ID = D.DIVISION_ID AND B.CHILD_ITEM_ID = D.ITEM_ID
                                                                  LEFT JOIN SCM_MST_SITE S ON S.DIVISION_ID = A.DIVISION_ID AND S.SCM_SITE_ID = A.SCM_SITE_ID AND S.VMI_YN = 'Y'
                                                            WHERE 1 = 1
/* Alternate Part 제외로직 추가 */
                                                              AND B.ALT_PRIORITY = 'Y'
/* 실적(등록된 카운트)수량은 분기되기 이전 날짜 전체를 사용해야 카운트가 맞음 */
                                                              AND A.YYYYMMDD >= V_P_FROM_YYYYMMDD
                                                              AND A.YYYYMMDD <= V_P_TO_YYYYMMDD
                                                              /* PJ20214907 */  /* 20221115 PJ20216994 MKT FCST 조건 변경 */
/* AND a.MEASURE = IIF( ISNULL(s.vmi_yn, 'N') = 'Y', 'VMI_In_Req',  'MKT_FCST') */
/* AND a.MEASURE = IIF(ISNULL(s.operation_group, '') = 'W', 'AS_In_Req', IIF(ISNULL(s.vmi_yn, 'N') = 'Y', 'VMI_In_Req',  'MKT_FCST')) */
                                                              AND A.MEASURE = CASE WHEN S.OPERATION_GROUP = 'W' THEN 'AS_In_Req' WHEN S.VMI_YN = 'Y' THEN 'VMI_In_Req' WHEN RTRIM(A.ATTRIBUTE10) IS NULL THEN 'MKT_FCST' END
                                                              AND A.QTY > 0
                                                              AND A.DIVISION_ID = V_DIVISION_ID
/* AND (( @p_item_id IS NULL OR  @p_item_id = '' ) OR b.model_id     IN (SELECT token FROM dbo.String_Split(@p_item_id		,',')) ) */
                                                              AND D.OPERATION_GROUP_ID <> 'E'
/* ESS 팩모델 하위의 CELL중에서 일부가 자동차전지에만 BOM에서 모ITEM으로 존재하지만,PROJECT ROUTE화면에서 ESS에 생산지를 등록하도록 표기되는 오류수정 */
                                                              AND EXISTS ( SELECT 1
                                                                             FROM SCM_MST_BOM_ENG_SN
                                                                            WHERE DIVISION_ID = V_DIVISION_ID
                                                                              AND PARENT_ITEM_ID = B.CHILD_ITEM_ID
/* BOM을 제거모델 조회안되도록 수정 */
                                                                              AND EFF_END_DATE >= SYSDATE
                                                                              AND KEY_DATE = ( SELECT MAX(KEY_DATE)
                                                                                                 FROM SCM_MST_BOM_ENG_SN
                                                                                                WHERE PARENT_ITEM_ID = B.CHILD_ITEM_ID
                                                                                                  AND DIVISION_ID = V_DIVISION_ID )
                                                                         )
                                                         ) M
                                                ) N
                                          GROUP BY DIVISION_ID, SCM_SITE_ID, PROJECT_CODE, MODEL_ID, TOT_CNT
                                       ) U ON T.DIVISION_ID  = U.DIVISION_ID
                                          AND T.SCM_SITE_ID  = U.SCM_SITE_ID
                                          AND T.PROJECT_CODE = U.PROJECT_CODE
                                          AND T.ITEM_ID      = U.MODEL_ID
                       /******************end of 수량카운트********************************************************************************************/
                       INNER JOIN ( SELECT DIVISION_ID, ITEM_ID, NICK_NAME, ITEM_TYPE
                                         , ROW_NUMBER() OVER ( PARTITION BY DIVISION_ID, ITEM_ID ORDER BY CASE ITEM_TYPE WHEN 'P' THEN 999 WHEN 'H' THEN 888 WHEN 'R' THEN 777 WHEN 'Q' THEN 666 ELSE 0 END DESC ) NUMS
                                      FROM SCM_MST_ITEM_SN
                                  ) I ON T.DIVISION_ID = I.DIVISION_ID
                                     AND T.ITEM_ID     = I.ITEM_ID
                                     AND I.NUMS = 1
                 WHERE 1 = 1
                   AND I.ITEM_TYPE NOT IN ('Q', 'R')
                   /* PJ20214907 */
                   AND T.MEASURE IN ('VMI_In_Req', 'MKT_FCST', 'AS_In_Req')
                   AND T.DIVISION_ID = V_DIVISION_ID
                   AND ( ( V_P_STATUS IS NULL ) OR U.CMPLTD_STATUS IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(V_P_STATUS, ','))) );
            END IF;


            V_MQUERY := '';

/* 날짜 컬럼 생성 (원본 dead: @mQuery 결과는 @mEXEC에 미사용) */
            SELECT LISTAGG('[' || MONTH || '], ') WITHIN GROUP (ORDER BY MONTH)
              INTO V_MQUERY
              FROM ( SELECT A.BASIS_YYYYMM AS MONTH
                          , MIN(A.BASIS_START_DATE) || '01' AS SORT_ORDER_NO
                       FROM SCM_SYS_CALENDAR_M A
                      WHERE A.BASIS_YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
                      GROUP BY A.BASIS_YYYYMM, A.MONTH_NAME
                   ) A;

/* PIVOT 쿼리 실행 */
            V_MQUERY := SUBSTR(V_MQUERY, 1, LENGTH(V_MQUERY) - 1);

            V_MEXEC := '';
            V_MEXEC := V_MEXEC || ' INSERT INTO GT_SKPB_PROJECTROUTE ' || CHR(10);
            V_MEXEC := V_MEXEC || '      SELECT DISTINCT ' || V_FROM_YYYYMMDD || ' AS PLAN_START_YYYYMMDD' || CHR(10);
            V_MEXEC := V_MEXEC || '            , DIVISION_ID, SCM_SITE_ID ' || CHR(10);
            V_MEXEC := V_MEXEC || '            , PROJECT_CODE, ITEM_ID, PLANT_PER_ITEM, CMPLTD_STATUS ' || CHR(10);

/* PJ20216891 */
