/* IF( @v_division_id IN ('81', '81_UC') ) */
/* [PJ20230691R] LGES SCM 역량 강화 위한 SCP 개선과제 이행 : HM JV 가상 사업부 추가 반영 */
            IF V_EXISTS_81 > 0 THEN
                V_MEXEC := V_MEXEC || '      FROM GT_SKPB_PROJECTROUTE_TMP1 ' || CHR(10);
            ELSE
                V_MEXEC := V_MEXEC || '      FROM GT_SKPB_PROJECTROUTE_TMP2 ' || CHR(10);
            END IF;
/* SET @mEXEC = @mEXEC+'       PIVOT ( ' +CHAR(10); */
/* SET @mEXEC = @mEXEC+'               SUM(qty) FOR  month IN ('+ @mQuery +') '+CHAR(10); */
/* SET @mEXEC = @mEXEC+'             ) AS A'  +CHAR(10); */
            V_MEXEC := V_MEXEC || '     ORDER BY DIVISION_ID, CMPLTD_STATUS, PLANT_PER_ITEM ' || CHR(10);

            EXECUTE IMMEDIATE V_MEXEC;


            DELETE FROM GT_SKPB_PROJECTROUTE_TMP1;
            DELETE FROM GT_SKPB_PROJECTROUTE_TMP2;

        END LOOP;  /* END OF WHILE */


        N_LOG_COUNT   := SQL%ROWCOUNT;
        V_LOG_TYPE    := '';
        V_LOG_MESSAGE := '#TblDynamicPivot_ProjectRoute_tmp';
        V_DESCRIPTION := 'CREATE';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

/* EE 전극 아이템 추가 */
        INSERT INTO GT_SKPB_PROJECTROUTE
             ( PLAN_START_YYYYMMDD, DIVISION_ID, SCM_SITE_ID, PROJECT_CODE, ITEM_ID, PLANT_PER_ITEM, CMPLTD_STATUS )
        SELECT DISTINCT
               V_FROM_YYYYMMDD AS PLAN_START_YYYYMMDD
             , DM.ELEC_DIVISION_ID AS DIVISION_ID  /* [PJ20230691R] HM JV 가상 사업부 추가 반영 */
             , '-' AS SCM_SITE_ID
             , '-' AS PROJECT_CODE
             , B.CHILD_ITEM_ID AS ITEM_ID
             , '' AS PLANT_PER_ITEM
             , 'N' AS CMPLTD_STATUS
          FROM ( SELECT DISTINCT P.DIVISION_ID, P.ITEM_ID
                      , D.ATTRIBUTE4 AS COMPANY_DV
                   FROM SCP_ANL_PRODUCTION_PLAN P
/* [PJ20230691R] HM JV 가상 사업부 추가 반영 */
                        INNER JOIN SCM_MST_DIVISION D
                                ON D.DIVISION_ID = P.DIVISION_ID
                               AND D.ATTRIBUTE3  != 'EE'
                               AND D.VALID_YN    = 'Y'
                               AND P.DIVISION_ID != '82'  /* 82사업부 제외 */
                  WHERE 1 = 1
                    AND PLAN_START_YYYYMMDD >= FN_GET_BUCKET_YYYYMMDD(-1)
                    AND OPERATION_GROUP = 'A'
                    AND MEASURE = 'PROD_PLAN_AMEND'
               ) A
          INNER JOIN (  /* [PJ20230691R] HM JV 가상 사업부 추가 반영 */
                       SELECT ATTRIBUTE4        AS COMPANY_DV
                            , MAX(DIVISION_ID)  AS ELEC_DIVISION_ID
                         FROM SCM_MST_DIVISION
                        WHERE 1 = 1
                          AND ATTRIBUTE3 = 'EE'
                          AND VALID_YN   = 'Y'
                        GROUP BY ATTRIBUTE4
                     ) DM
                  ON DM.COMPANY_DV = A.COMPANY_DV
             , SCM_MST_MODEL_FINAL_ITEM_BOM_V B
               JOIN SCM_ADM_LOOKUP_MASTER C ON C.LOOKUP_TYPE = 'OPERATION_GROUP' AND C.VALID_YN = 'Y'
               JOIN SCM_ADM_LOOKUP_MASTER_DETAIL D
                 ON D.LOOKUP_TYPE = C.LOOKUP_TYPE
                AND D.VALID_YN = 'Y'
                AND D.SEGMENT1 = 'E'  /* B.OPERATION_GROUP_ID */
         WHERE 1 = 1
           AND A.DIVISION_ID = B.DIVISION_ID
           AND A.ITEM_ID = B.MODEL_ID
           AND B.OPERATION_GROUP_ID = 'E'
           AND B.OPERATION_GROUP_ID = 'E'
           AND NOT EXISTS ( SELECT 1
                              FROM SCM_MST_SITE_ITEM_PRIORITY T
                             WHERE T.DIVISION_ID = B.DIVISION_ID
                               AND T.ITEM_ID     = B.CHILD_ITEM_ID
                               AND T.VALID_YN = 'Y' )
        UNION ALL
        SELECT DISTINCT
               V_FROM_YYYYMMDD AS PLAN_START_YYYYMMDD
             , A.ELEC_DIVISION_ID AS DIVISION_ID  /* [PJ20230691R] HM JV 가상 사업부 추가 반영 */
             , '-' AS SCM_SITE_ID
             , A.PROJECT_CODE
             , A.ITEM_ID
             , '' AS PLANT_PER_ITEM
             , 'Y' AS CMPLTD_STATUS
          FROM ( SELECT TO_CHAR(T.PRIORITY_SEQ) AS PRIORITY_SEQ
                      , T.DIVISION_ID
                      , DM.ELEC_DIVISION_ID  /* [PJ20230691R] HM JV 가상 사업부 추가 반영 */
                      , CASE WHEN RTRIM(T.PROJECT_CODE) IS NULL THEN '-' ELSE T.PROJECT_CODE END AS PROJECT_CODE
                      , T.ITEM_ID
                      , CASE WHEN RTRIM(T.SALES_SITE_ID) IS NULL THEN '-' ELSE T.SALES_SITE_ID END AS SCM_SITE_ID
                      , T.PLANT_SITE_ID
                      , T.PRIORITY
                      , T.VALID_YN
                      , T.VALID_YN AS ORG_VALID_YN
                      , TO_CHAR(FN_CHAR_TO_DATE(T.FROM_YYYYMMDD), 'YYYY-MM-DD') AS FROM_YYYYMMDD
                      , TO_CHAR(FN_CHAR_TO_DATE(T.TO_YYYYMMDD), 'YYYY-MM-DD') AS TO_YYYYMMDD
                      , T.CREATED_BY
                      , T.CREATION_DATE
                      , T.LAST_UPDATED_BY
                      , T.LAST_UPDATE_DATE
                      , S.OPERATION_GROUP
                      , T.FROM_YYYYMMDD AS ORG_FROM_YYYYMMDD
                      , T.TO_YYYYMMDD AS ORG_TO_YYYYMMDD
                      , T.FROM_YYYYMMDD || T.TO_YYYYMMDD AS MERGE_DATE
                      , '' AS IS_PASS_N1
                      , '' AS IS_PASS_N2
                      , '' AS IS_PASS_N3
                      , '' AS IS_PASS_N4
                      , '' AS IS_PASS_N5
                      , '' AS IS_PASS_N6
                      , '' AS IS_PASS_N7
                      , FN_GET_ITEM_NICKNAME(T.DIVISION_ID, T.ITEM_ID) AS NICK_NAME
                      , B.SEGMENT2 AS OPERATION_GROUP_NAME
                      , '-' AS ACTION_FLAG_DIV
                      , 0 AS ROW_COLOR_INDEX
                      , 1 AS SORT_ORDER
                      , NVL(( SELECT COUNT(C.PLANT_SITE_ID) FROM SCP_MST_TACT_TIME C
                                     JOIN SCM_MST_LINE_SN LS ON LS.COMPANY_ID = S.COMPANY_ID AND LS.DIVISION_ID = C.DIVISION_ID AND LS.SITE_ID = S.SITE_ID AND LS.PLANT_ID = S.PLANT_ID
                                                           AND LS.OPERATION_ID = C.OPERATION_ID AND LS.LINE_ID = C.LINE_ID AND LS.ACTIVE_FLAG = 'Y'
                               WHERE 1 = 1
                                 AND ( ( V_P_DIVISION_ID IS NULL ) OR C.DIVISION_ID IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(V_P_DIVISION_ID, ','))) )
/* AND c.DIVISION_ID = @p_division_id */
                                 AND C.ITEM_ID = T.ITEM_ID
                                 AND C.VALID_YN = 'Y'
                                 AND C.PLANT_SITE_ID = S.SCM_SITE_ID
                               GROUP BY C.ITEM_ID, C.PLANT_SITE_ID
                            ), 0) AS TACT_CNT
                      , NVL(( SELECT COUNT(C.PLANT_SITE_ID) FROM SCP_MST_OUTSOURCING_CAPA C
                               WHERE 1 = 1
                                 AND ( ( V_P_DIVISION_ID IS NULL ) OR C.DIVISION_ID IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(V_P_DIVISION_ID, ','))) )
                                 AND C.ITEM_ID = T.ITEM_ID
                                 AND C.VALID_YN = 'Y'
                                 AND C.PLANT_SITE_ID = S.SCM_SITE_ID
                               GROUP BY C.PLANT_SITE_ID, C.ITEM_ID
                            ), 0) AS OUT_CAPA_CNT
                      , S.SITE_DESCRIPTION
                   FROM SCM_MST_SITE_ITEM_PRIORITY T
/* begin [PJ20230691R] HM JV 가상 사업부 추가 반영 */
                        JOIN SCM_MST_DIVISION D
                          ON D.DIVISION_ID = T.DIVISION_ID
                         AND D.VALID_YN    = 'Y'
                        JOIN ( SELECT ATTRIBUTE4        AS COMPANY_DV
                                    , MAX(DIVISION_ID)  AS ELEC_DIVISION_ID
                                 FROM SCM_MST_DIVISION
                                WHERE 1 = 1
                                  AND ATTRIBUTE3 = 'EE'
                                  AND VALID_YN   = 'Y'
                                GROUP BY ATTRIBUTE4
                             ) DM
                          ON DM.COMPANY_DV = D.ATTRIBUTE4
/* end [PJ20230691R] HM JV 가상 사업부 추가 반영 */
                        JOIN SCM_MST_SITE S
                          ON ( (T.DIVISION_ID = S.DIVISION_ID AND S.OPERATION_GROUP != 'E') OR (S.OPERATION_GROUP = 'E') )
                         AND T.PLANT_SITE_ID = S.SCM_SITE_ID
                        JOIN SCM_ADM_LOOKUP_MASTER A
                          ON A.LOOKUP_TYPE = 'OPERATION_GROUP'
                         AND A.VALID_YN = 'Y'
                        JOIN SCM_ADM_LOOKUP_MASTER_DETAIL B
                          ON B.LOOKUP_TYPE = A.LOOKUP_TYPE
                         AND B.VALID_YN = 'Y'
                         AND B.SEGMENT1 = S.OPERATION_GROUP
                  WHERE S.SITE_TYPE = 'PLANT'
                    AND ( ( V_P_DIVISION_ID IS NULL ) OR T.DIVISION_ID IN (SELECT S2.VALUE FROM TABLE(FN_SPLITSTRING(V_P_DIVISION_ID, ',')) S2) )
                    AND S.OPERATION_GROUP = 'E'
               ) A;

        N_LOG_COUNT   := SQL%ROWCOUNT;
        V_LOG_TYPE    := '';
        V_LOG_MESSAGE := '#TblDynamicPivot_ProjectRoute';
        V_DESCRIPTION := 'INSERT';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        INSERT INTO SCM_KPI_PROJECTROUTE_BOM
             ( DIVISION_ID, PLAN_START_YYYYMMDD, PROJECT_CODE, SALES_SITE_ID, ITEM_ID, VALID_TYPE, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE )
        SELECT DIVISION_ID
             , PLAN_START_YYYYMMDD
             , PROJECT_CODE
             , SCM_SITE_ID
             , ITEM_ID
             , CASE WHEN CMPLTD_STATUS = 'Y' THEN 'OK'
                    WHEN CMPLTD_STATUS = 'N' AND PLANT_PER_ITEM = 'BOM' THEN 'NOT_BOM'
                    WHEN CMPLTD_STATUS = 'N' AND NVL(PLANT_PER_ITEM, '-') <> 'BOM' THEN 'NG'
               END AS VALID_TYPE
             , V_BATCH_USER
             , SYSDATE
             , V_BATCH_USER
             , SYSDATE
          FROM GT_SKPB_PROJECTROUTE;

        N_LOG_COUNT   := SQL%ROWCOUNT;
        V_LOG_TYPE    := '';
        V_LOG_MESSAGE := 'SCM_KPI_PROJECTROUTE_BOM';
        V_DESCRIPTION := 'INSERT';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        SELECT COUNT(*) INTO N_LOG_COUNT FROM GT_SKPB_PROJECTROUTE;


        DELETE FROM GT_SKPB_PROJECTROUTE;

    EXCEPTION
        WHEN OTHERS THEN

            ROLLBACK;
/* ERROR LOG (원본 CATCH: 로그 후 return -1 = 조용히 종료, 재전파 없음) */
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := SUBSTR('ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 500);
            D_EVENT_DATE  := SYSDATE;
            PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER
                                , JSON_OBJECT('P_BASIS_YYYYMMDD' VALUE P_BASIS_YYYYMMDD RETURNING VARCHAR2(4000 CHAR)), TO_CHAR(SQLCODE), SQLERRM, DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
            RETURN;
    END;

/* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER);


    COMMIT;
END;

PROCEDURE PR_SCM_KPI_TIMELINE
(
    P_BASIS_YYYYMMDD  IN  VARCHAR2 DEFAULT NULL
)
/* ============================================================
 * Program ID   : PR_SCM_KPI_TIMELINE
 * Description  : Time Line 준수율 데이타 생성 : 매주 일요일 밤에 당주 정보 생성
 * OutTable     :
 * Execute      :
 * Program History
 *------------------------------------------------------------
 * Date          In Charge      Description
 *------------------------------------------------------------
 * 2019.04.22    KSG            Initial Release ******
 * 2026.07.06   ZIONEX   [PJ202650304] NextSCM Migration
 * ============================================================ */
IS
    /* LOG 용 변수 설정 */
    V_BATCH_USER      VARCHAR2(150 CHAR) := 'scm_batch';
    V_PROGRAM_NAME    VARCHAR2(150 CHAR) := 'PR_SCM_KPI_TIMELINE';
    V_LOG_TYPE        VARCHAR2(30 CHAR);
    N_LOG_COUNT       NUMBER := 0;
    V_LOG_MESSAGE     VARCHAR2(1000 CHAR);
    V_DESCRIPTION     VARCHAR2(500 CHAR);
    V_TABLE_ID        VARCHAR2(150 CHAR) := 'SCM_KPI_TIMELINE';
    D_EVENT_DATE      DATE;

    /* 업무용 변수 */
    V_BASIS_YYYYMMDD  VARCHAR2(8 CHAR);   /* 기준 일자 */
    V_PLAN_ID         VARCHAR2(8 CHAR);
BEGIN
    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := V_PROGRAM_NAME || ':' || ' SCM_KPI_TIMELINE INSERT LOGIC';
    D_EVENT_DATE  := SYSDATE;
    PR_SCP_SYS_LOG_BATCH(P_PROGRAM_NAME => V_PROGRAM_NAME, P_LOG_TYPE => V_LOG_TYPE, P_LOG_COUNT => N_LOG_COUNT
                       , P_LOG_MESSAGE => V_LOG_MESSAGE, P_DESCRIPTION => V_DESCRIPTION, P_EVENT_DATE => D_EVENT_DATE
                       , P_USER_ID => V_BATCH_USER);

    /* 매주 일요일에 월요일 일자로 적재한다. */
    /* 기준일자 설정 */
    IF P_BASIS_YYYYMMDD IS NOT NULL THEN
        V_BASIS_YYYYMMDD := P_BASIS_YYYYMMDD;
    ELSE
        /* 당주 월요일(일요일 밤에 Batch 실행 시) */
        V_BASIS_YYYYMMDD := TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7, 'YYYYMMDD');
    END IF;

    /* 기준일자의 Plan ID 설정 */

    SELECT MAX(P.PLAN_ID)
      INTO V_PLAN_ID
      FROM SCM_MST_PLAN P
     WHERE P.PLAN_NAME = V_BASIS_YYYYMMDD
       AND P.DIVISION_ID = '81'      /* 사업부 상관없이 동일하므로 하나만 가져오기 위해 설정 */
       AND P.PLAN_CYCLE = 'WEEKLY';

    /* 동일 주차정보 삭제 */
    DELETE
      FROM SCM_KPI_TIMELINE
     WHERE PLAN_START_YYYYMMDD = V_BASIS_YYYYMMDD;

    /* Time Line 준수율 데이타 생성 */
    INSERT
      INTO SCM_KPI_TIMELINE
         ( DIVISION_ID
         , PLAN_START_YYYYMMDD
         , PLAN_TYPE
         , PLAN_SEQ
         , PLAN_START_DATE
         , PLAN_START_WEEK_DAY
         , PLAN_WEEK_DAY
         , PLAN_START_TIME
         , PLAN_TIME
         , VALID_TYPE
         , CREATED_BY
         , CREATION_DATE
         , LAST_UPDATED_BY
         , LAST_UPDATE_DATE )
    SELECT P.DIVISION_ID
         , P.PLAN_NAME
         , PD.PLAN_TYPE
         , PD.PLAN_SEQ
         , TO_CHAR(PD.INPUT_START_DATE, 'YYYY-MM-DD HH24') AS PLAN_START_DATE
         , TO_CHAR(MOD(TRUNC(PD.INPUT_START_DATE) - TRUNC(PD.INPUT_START_DATE, 'IW') + 1, 7) + 1)  AS PLAN_START_WEEK_DAY
         , L.SEGMENT3                                      AS PLAN_WEEK_DAY
         , TO_CHAR(PD.INPUT_START_DATE, 'HH24')            AS PLAN_START_TIME
         , L.SEGMENT4                                      AS PLAN_TIME
         , CASE WHEN MOD(TRUNC(PD.INPUT_START_DATE) - TRUNC(PD.INPUT_START_DATE, 'IW') + 1, 7) + 1 = TO_NUMBER(L.SEGMENT3)
                 AND TO_CHAR(PD.INPUT_START_DATE, 'HH24') = L.SEGMENT4
                THEN 'OK'
                ELSE 'NG'
           END AS VALID_TYPE
         , V_BATCH_USER
         , SYSDATE
         , V_BATCH_USER
         , SYSDATE
      FROM SCM_MST_PLAN P
         , SCM_MST_PLAN_DETAIL PD
         ,(SELECT DIVISION_ID
                , PLAN_ID
                , PLAN_TYPE
                , MAX(PLAN_SEQ) AS PLAN_SEQ
             FROM SCM_MST_PLAN_DETAIL
            WHERE PLAN_ID = V_PLAN_ID
              AND PLAN_STATUS = '1'
            GROUP BY DIVISION_ID, PLAN_ID, PLAN_TYPE ) PDM
         , SCM_ADM_LOOKUP_MASTER_DETAIL L
     WHERE P.DIVISION_ID = PD.DIVISION_ID
       AND P.PLAN_ID = PD.PLAN_ID
       AND P.PLAN_CYCLE = 'WEEKLY'
       AND P.PLAN_NAME = V_BASIS_YYYYMMDD
       AND PD.DIVISION_ID = PDM.DIVISION_ID
       AND PD.PLAN_ID = PDM.PLAN_ID
       AND PD.PLAN_TYPE = PDM.PLAN_TYPE
       AND PD.PLAN_SEQ = PDM.PLAN_SEQ
       AND P.DIVISION_ID = L.SEGMENT1
       AND PD.PLAN_TYPE = L.SEGMENT2
       AND L.LOOKUP_TYPE = 'PLAN_TIME'
       AND L.VALID_YN = 'Y';

    N_LOG_COUNT := SQL%ROWCOUNT;

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCP_SYS_LOG_BATCH(P_PROGRAM_NAME => V_PROGRAM_NAME, P_LOG_TYPE => V_LOG_TYPE, P_LOG_COUNT => N_LOG_COUNT
                       , P_LOG_MESSAGE => V_LOG_MESSAGE, P_DESCRIPTION => V_DESCRIPTION, P_EVENT_DATE => D_EVENT_DATE
                       , P_USER_ID => V_BATCH_USER);


    COMMIT;

EXCEPTION
    WHEN OTHERS THEN

        ROLLBACK;
        /* ERROR LOG (MSSQL BEGIN CATCH: RAISERROR/THROW 없이 삼킴 -> Oracle 흡수, RAISE 없음. return -1 -> END LOG 미도달과 등가) */
        V_LOG_TYPE    := 'ERROR';
        V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
        V_DESCRIPTION := SUBSTR('ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 500);
        D_EVENT_DATE  := SYSDATE;
        PR_SCP_SYS_LOG_BATCH(P_PROGRAM_NAME => V_PROGRAM_NAME, P_LOG_TYPE => V_LOG_TYPE, P_LOG_COUNT => N_LOG_COUNT
                           , P_LOG_MESSAGE => V_LOG_MESSAGE, P_DESCRIPTION => V_DESCRIPTION, P_EVENT_DATE => D_EVENT_DATE
                           , P_USER_ID => V_BATCH_USER
                           , P_IN_PARA_DATA => JSON_OBJECT('P_BASIS_YYYYMMDD' VALUE P_BASIS_YYYYMMDD RETURNING VARCHAR2(4000 CHAR)), P_SQL_ERR_CODE => TO_CHAR(SQLCODE)
                           , P_SQL_ERR_MSG => SQLERRM, P_SQL_BACKTRACE => DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
END;

PROCEDURE PR_SCM_LGTM_INV_ALLOCATION_SPRD_IGR
(
     P_PLAN_TP_CD              IN VARCHAR2
    ,P_SRCE_PLAN_TP_CD         IN VARCHAR2
    ,P_DIVISION_ID             IN VARCHAR2
    ,P_PLAN_START_YYYYMMDD     IN VARCHAR2
    ,P_BASIS_YYYYMM            IN VARCHAR2
)
/* ============================================================
 * Program ID   : PR_SCM_LGTM_INV_ALLOCATION_SPRD_IGR
 * Description  : 장기재고 관련 반제품 PSI Group EOH 정보 형성
 * Program History
 *------------------------------------------------------------
 * Date          In Charge      Description
 *------------------------------------------------------------
 *                              최초 생성
 * 2025.11.11    park.choyi     [E20250310-000014] 업무 용어 변경에 따른 시스템내 표기 수정 요청 ('부실' 에서 '장기')
 * 2026.07.06    ZIONEX         [PJ202650304]  NextSCM Migration
 * ============================================================ */
AS
    /* ---------------------------------------------------------------- */
    /* LOG 용 변수 */
    /* ---------------------------------------------------------------- */
    V_PROGRAM_NAME   VARCHAR2(150 CHAR) := 'PR_SCM_LGTM_INV_ALLOCATION_S_IGR';
    V_LOG_TYPE       VARCHAR2(30 CHAR);
    N_LOG_COUNT      INTEGER := 0;
    V_LOG_MESSAGE    VARCHAR2(1000 CHAR);
    V_DESCRIPTION    VARCHAR2(500 CHAR);
    D_EVENT_DATE     DATE;

    /* ---------------------------------------------------------------- */
    /* Set Parameter (IN 에서 로컬, 읽기/쓰기 가능) */
    /* ---------------------------------------------------------------- */
    V_PLAN_TP_CD           VARCHAR2(20 CHAR) := P_PLAN_TP_CD;
    V_SRCE_PLAN_TP_CD      VARCHAR2(20 CHAR) := P_SRCE_PLAN_TP_CD;
    V_DIVISION_ID          VARCHAR2(20 CHAR) := P_DIVISION_ID;
    V_PLAN_START_YYYYMMDD  VARCHAR2(8 CHAR)  := P_PLAN_START_YYYYMMDD;
    V_BASIS_YYYYMM         VARCHAR2(6 CHAR)  := P_BASIS_YYYYMM;

    /* ---------------------------------------------------------------- */

    /* ---------------------------------------------------------------- */
    V_COUNTER          INTEGER;
    V_PLAN_YYYYMMDD    VARCHAR2(8 CHAR) := P_BASIS_YYYYMM || '01';
    V_PLAN_YYYYMM      VARCHAR2(6 CHAR);
    V_CNT              INTEGER;
    V_ITEM_CLASS       VARCHAR2(50 CHAR);

    /* Sales */
    V_SALE_QTY         NUMBER;
    V_REASON_CD        VARCHAR2(20 CHAR);
    V_S_GROUP_CODE1    VARCHAR2(30 CHAR);
    V_S_ORG_ITEM_ID    VARCHAR2(30 CHAR);
    V_S_VERSION_NO     VARCHAR2(30 CHAR);

    /* Prod */
    V_PROD_DATA_TP_CD  VARCHAR2(20 CHAR);
    V_SRCE_TP_CD       VARCHAR2(20 CHAR);
    V_GROUP_CODE1      VARCHAR2(30 CHAR);
    V_ORG_ITEM_ID      VARCHAR2(30 CHAR);
    V_SRCE_YYYYMM      VARCHAR2(6 CHAR);
    V_PROD_QTY         NUMBER;
    V_SORT_ORDER       INTEGER;
    V_CLASS_NAME       VARCHAR2(50 CHAR);

    V_COMPANY_ID       VARCHAR2(10 CHAR);
    V_PLANT_ID         VARCHAR2(30 CHAR);

    /* ---------------------------------------------------------------- */


    /* ---------------------------------------------------------------- */
    CURSOR CURRENT_MONTH_SALES_CUR IS
        SELECT   S.DIVISION_ID     AS DIVISION_ID
               , S.SRCE_TP_CD      AS REASON_CD
               , S.GROUP_CODE1     AS GROUP_CODE1
               , S.ITEM_CLASS      AS ITEM_CLASS
               , SUM(CASE WHEN S.QTY < 0 THEN S.QTY * (-1) ELSE S.QTY END) AS SALE_QTY
               , S.CLASS_NAME      AS CLASS_NAME
               , S.COMPANY_ID      AS COMPANY_ID
               , '*'               AS PLANT_ID
          FROM   SCM_LGTM_INV_PSI_SUMMARY_SPRD_IGR S
         WHERE   1 = 1
           AND   S.PLAN_TP_CD          = V_PLAN_TP_CD
           AND   S.PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
           AND   S.DIVISION_ID         = V_DIVISION_ID
           AND   S.PLAN_YYYYMM         = V_PLAN_YYYYMM
           AND   S.DATA_TP_CD         IN ('S', 'BOH')
           AND   S.SRCE_TP_CD       LIKE 'S%'
         GROUP BY S.DIVISION_ID
               , S.SRCE_TP_CD
               , S.GROUP_CODE1
               , S.ITEM_CLASS
               , S.CLASS_NAME
               , S.COMPANY_ID
         ORDER BY S.SRCE_TP_CD DESC;

    /* ---------------------------------------------------------------- */
    /* 내부 커서 : 당월 생산/재고(EOH) FOR UPDATE (MSSQL CURRENT_MONTH_PROD_CUR) */
    /* ---------------------------------------------------------------- */
    CURSOR CURRENT_MONTH_PROD_CUR IS
        SELECT   S.DATA_TP_CD      AS DATA_TP_CD
               , S.SRCE_TP_CD      AS SRCE_TP_CD
               , S.GROUP_CODE1     AS GROUP_CODE1
               , S.ITEM_CLASS      AS ITEM_CLASS
               , S.SRCE_YYYYMM     AS SRCE_YYYYMM
               , S.REMAIN_QTY      AS REMAIN_QTY
               , CASE  WHEN S.SRCE_TP_CD = 'BOH_FERT' THEN 1
                       WHEN S.SRCE_TP_CD = 'BOH_SPRD' THEN 2
                       WHEN S.SRCE_TP_CD = 'BOH_INTS' THEN 3
                       WHEN S.SRCE_TP_CD = 'BOH_DEVL' THEN 4
                       ELSE 5 END  AS SORT_ORDER
               , S.CLASS_NAME      AS CLASS_NAME
               , S.COMPANY_ID      AS COMPANY_ID
               , '*'               AS PLANT_ID
          FROM   SCM_LGTM_INV_PSI_DETAIL_SPRD_IGR S
         WHERE   1 = 1
           AND   S.PLAN_TP_CD          = V_PLAN_TP_CD
           AND   S.PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
           AND   S.DATA_TP_CD          = 'EOH'
           AND   S.SRCE_TP_CD         IN ('BOH_FERT', 'BOH_SPRD', 'BOH_INTS', 'BOH_DEVL', 'P', 'P_SEMI_WHIN')
           AND   S.DIVISION_ID         = V_DIVISION_ID
           AND   S.PLAN_YYYYMM         = V_PLAN_YYYYMM
           AND   S.GROUP_CODE1         = V_S_GROUP_CODE1
           AND   S.ITEM_CLASS          = V_ITEM_CLASS
           AND   S.REMAIN_QTY          > 0
           AND   S.COMPANY_ID          = V_COMPANY_ID
           AND   S.PLANT_ID            = V_PLANT_ID
         ORDER BY S.SRCE_YYYYMM, SORT_ORDER, S.SRCE_TP_CD
        FOR UPDATE;

BEGIN

    /* ---------------------------------------------------------------- */
    /* LOG 시작 */
    /* ---------------------------------------------------------------- */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := P_PLAN_TP_CD || '=>' || P_DIVISION_ID;
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    BEGIN
        /* ------------------------------------------------------------ */
        /* Step 1-1. Delete SUMMARY */
        /* ------------------------------------------------------------ */
        DELETE
          FROM  SCM_LGTM_INV_PSI_SUMMARY_SPRD_IGR
         WHERE  1 = 1
           AND  PLAN_TP_CD          = V_PLAN_TP_CD
           AND  PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
           AND  DIVISION_ID         = V_DIVISION_ID;

        /* ------------------------------------------------------------ */
        /* Step 1-2. Create From Item SUMMARY */
        /* ------------------------------------------------------------ */
        INSERT INTO SCM_LGTM_INV_PSI_SUMMARY_SPRD_IGR
             ( PLAN_TP_CD, PLAN_START_YYYYMMDD, DATA_TP_CD, SRCE_TP_CD, DIVISION_ID
             , GROUP_CODE1, ITEM_CLASS, SRCE_YYYYMM, PLAN_YYYYMM, QTY, CURRENCY
             , STANDARD_COST, AMT, DEVALUATION_AGE, LONG_TERM_TYPE_CODE, LONG_TERM_TYPE
             , CLASS_NAME, COMPANY_ID, PLANT_ID )
        SELECT   V_PLAN_TP_CD AS PLAN_TP_CD
               , SM.PLAN_START_YYYYMMDD
               , SM.DATA_TP_CD
               , SM.SRCE_TP_CD
               , SM.DIVISION_ID
               , SM.GROUP_CODE1
               , CASE WHEN L.ATTRIBUTE2 IS NOT NULL THEN L.ATTRIBUTE2 ELSE '*' END AS ITEM_CLASS
               , SM.SRCE_YYYYMM
               , SM.PLAN_YYYYMM
               , SUM(QTY) AS QTY
               , ''  AS CURRENCY
               , 0   AS STANDARD_COST
               , 0   AS AMT
               , SM.DEVALUATION_AGE
               , SM.LONG_TERM_TYPE_CODE
               , SM.LONG_TERM_TYPE
               , CASE WHEN L.ATTRIBUTE2 IS NOT NULL THEN L.ATTRIBUTE2 ELSE '*' END
               , SM.COMPANY_ID AS COMPANY_ID
               , '*'           AS PLANT_ID
          FROM   SCM_LGTM_INV_PSI_SUMMARY_SPRD SM
               , SCM_MST_SITE SMS
               , ( SELECT DISTINCT DIVISION_ID, ITEM_ID, ITEM_CLASS
                     FROM SCM_ITEM_M_SN ) SIM
               , SCM_MST_ITEM_CLASS_M CLS
               , SCM_ADM_LOOKUP_MASTER_DETAIL L
         WHERE   1 = 1
           AND   SMS.DIVISION_ID(+) = SM.DIVISION_ID
           AND   SMS.SCM_SITE_ID(+) = SM.SCM_SITE_ID
           AND   SIM.DIVISION_ID(+) = SM.DIVISION_ID
           AND   SIM.ITEM_ID(+)     = SM.ITEM_ID
           AND   CLS.CLASS_ID(+)    = SIM.ITEM_CLASS
           AND   L.LOOKUP_TYPE(+)   = 'SCM_LGTM_ELTR_ITEM_CLASS_CD'
           AND   L.VALID_YN(+)      = 'Y'
           AND   L.SEGMENT1(+)      = SIM.ITEM_CLASS
           AND   SM.PLAN_TP_CD          = P_SRCE_PLAN_TP_CD
           AND   SM.PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
           AND   (   ( SM.DATA_TP_CD = 'BOH' AND SM.PLAN_YYYYMM = P_BASIS_YYYYMM )
                  OR ( SM.DATA_TP_CD NOT IN ( 'BOH', 'EOH' ) )
                 )
           AND   SM.DIVISION_ID         = V_DIVISION_ID
         GROUP BY SM.PLAN_TP_CD
               , SM.PLAN_START_YYYYMMDD
               , SM.DATA_TP_CD
               , SM.SRCE_TP_CD
               , SM.DIVISION_ID
               , SM.GROUP_CODE1
               , CASE WHEN L.ATTRIBUTE2 IS NOT NULL THEN L.ATTRIBUTE2 ELSE '*' END
               , SM.SRCE_YYYYMM
               , SM.PLAN_YYYYMM
               , SM.DEVALUATION_AGE
               , SM.LONG_TERM_TYPE_CODE
               , SM.LONG_TERM_TYPE
               , SM.COMPANY_ID;

        /* ------------------------------------------------------------ */
        /* Step 2-1. Delete EOH */
        /* ------------------------------------------------------------ */
        DELETE
          FROM  SCM_LGTM_INV_PSI_SUMMARY_SPRD_IGR
         WHERE  1 = 1
           AND  PLAN_TP_CD          = V_PLAN_TP_CD
           AND  PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
           AND  DATA_TP_CD         IN ('EOH')
           AND  DIVISION_ID         = V_DIVISION_ID;

        /* ------------------------------------------------------------ */
        /* Step 2-1. Delete BOH after start month */
        /* ------------------------------------------------------------ */
        DELETE
          FROM  SCM_LGTM_INV_PSI_SUMMARY_SPRD_IGR
         WHERE  1 = 1
           AND  PLAN_TP_CD          = V_PLAN_TP_CD
           AND  PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
           AND  PLAN_YYYYMM         > V_BASIS_YYYYMM
           AND  DATA_TP_CD         IN ('BOH')
           AND  DIVISION_ID         = V_DIVISION_ID;

        /* ------------------------------------------------------------ */
        /* Step 2-2. Delete DETAIL */
        /* ------------------------------------------------------------ */
        DELETE
          FROM  SCM_LGTM_INV_PSI_DETAIL_SPRD_IGR
         WHERE  1 = 1
           AND  PLAN_TP_CD          = V_PLAN_TP_CD
           AND  PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
           AND  DIVISION_ID         = V_DIVISION_ID;

        /* ------------------------------------------------------------ */

        /* ------------------------------------------------------------ */
        V_COUNTER := 1;

        WHILE (V_COUNTER <= 13)
        LOOP
            V_PLAN_YYYYMM := TO_CHAR(ADD_MONTHS(TO_DATE(V_PLAN_YYYYMMDD, 'YYYYMMDD'), V_COUNTER - 1), 'YYYYMM');

            /* -------------------------------------------------------- */
            /* Step 3-2. EOH 생성. BOH, P 그대로 EOH에 반영. */
            /* -------------------------------------------------------- */
            INSERT INTO SCM_LGTM_INV_PSI_DETAIL_SPRD_IGR
                 ( PLAN_TP_CD, PLAN_START_YYYYMMDD, DATA_TP_CD, SRCE_TP_CD, DIVISION_ID
                 , GROUP_CODE1, ITEM_CLASS, SRCE_YYYYMM, PLAN_YYYYMM, QTY, DECREASE_QTY
                 , REASON_CD, REMAIN_QTY, DEVALUATION_AGE, LONG_TERM_TYPE_CODE, LONG_TERM_TYPE
                 , CLASS_NAME, COMPANY_ID, PLANT_ID )
            SELECT   PLAN_TP_CD
                   , PLAN_START_YYYYMMDD
                   , 'EOH'
                   , SRCE_TP_CD
                   , DIVISION_ID
                   , GROUP_CODE1
                   , ITEM_CLASS
                   , SRCE_YYYYMM
                   , PLAN_YYYYMM
                   , QTY
                   , NULL
                   , 'X'  AS REASON_CD
                   , QTY  AS REMAIN_QTY
                   , DEVALUATION_AGE
                   , LONG_TERM_TYPE_CODE
                   , LONG_TERM_TYPE
                   , CLASS_NAME
                   , COMPANY_ID AS COMPANY_ID
                   , '*'        AS PLANT_ID
              FROM   SCM_LGTM_INV_PSI_SUMMARY_SPRD_IGR S
             WHERE   1 = 1
               AND   S.PLAN_TP_CD          = V_PLAN_TP_CD
               AND   S.PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
               AND   S.DIVISION_ID         = V_DIVISION_ID
               AND   S.PLAN_YYYYMM         = V_PLAN_YYYYMM
               AND   S.DATA_TP_CD         IN ('BOH', 'P')
               AND   S.QTY                 > 0;

            /* -------------------------------------------------------- */

            /* -------------------------------------------------------- */
            OPEN CURRENT_MONTH_SALES_CUR;
            LOOP
                FETCH CURRENT_MONTH_SALES_CUR
                    INTO  V_DIVISION_ID, V_REASON_CD, V_S_GROUP_CODE1, V_ITEM_CLASS
                        , V_SALE_QTY, V_CLASS_NAME, V_COMPANY_ID, V_PLANT_ID;
                EXIT WHEN CURRENT_MONTH_SALES_CUR%NOTFOUND;

                /* ---------------------------------------------------- */
                /* 내부 커서 OPEN (당월 생산/재고) FOR UPDATE */
                /* ---------------------------------------------------- */
                OPEN CURRENT_MONTH_PROD_CUR;
                LOOP
                    FETCH CURRENT_MONTH_PROD_CUR
                        INTO  V_PROD_DATA_TP_CD, V_SRCE_TP_CD, V_GROUP_CODE1, V_ITEM_CLASS
                            , V_SRCE_YYYYMM, V_PROD_QTY, V_SORT_ORDER, V_CLASS_NAME
                            , V_COMPANY_ID, V_PLANT_ID;
                    EXIT WHEN CURRENT_MONTH_PROD_CUR%NOTFOUND;

                    IF ( V_SALE_QTY > 0 ) AND ( V_PROD_QTY <= V_SALE_QTY ) THEN
                        /* Full Pegging (생산<=판매) */
                        UPDATE  SCM_LGTM_INV_PSI_DETAIL_SPRD_IGR
                           SET  DECREASE_QTY     = V_PROD_QTY
                              , REASON_CD        = V_REASON_CD
                              , REMAIN_QTY       = 0
                              , LAST_UPDATE_DATE = SYSDATE
                              , LAST_UPDATED_BY  = V_REASON_CD || '_enough'
                         WHERE  CURRENT OF CURRENT_MONTH_PROD_CUR;

                        V_SALE_QTY := V_SALE_QTY - V_PROD_QTY;

                    ELSIF ( V_SALE_QTY > 0 ) AND ( V_PROD_QTY > V_SALE_QTY ) THEN
                        /* Partial Pegging (생산>판매) */
                        UPDATE  SCM_LGTM_INV_PSI_DETAIL_SPRD_IGR
                           SET  DECREASE_QTY     = V_SALE_QTY
                              , REASON_CD        = V_REASON_CD
                              , REMAIN_QTY       = REMAIN_QTY - V_SALE_QTY
                              , LAST_UPDATE_DATE = SYSDATE
                              , LAST_UPDATED_BY  = V_REASON_CD || '_shortage'
                         WHERE  CURRENT OF CURRENT_MONTH_PROD_CUR;

                        V_SALE_QTY := 0;
                    END IF;
                END LOOP;
                CLOSE CURRENT_MONTH_PROD_CUR;

                /* ---------------------------------------------------- */

                /* ---------------------------------------------------- */
                IF ( V_SALE_QTY > 0 ) THEN
                    INSERT INTO SCM_LGTM_INV_PSI_DETAIL_SPRD_IGR
                         ( PLAN_TP_CD, PLAN_START_YYYYMMDD, DATA_TP_CD, SRCE_TP_CD, DIVISION_ID
                         , GROUP_CODE1, ITEM_CLASS, SRCE_YYYYMM, PLAN_YYYYMM, QTY, DECREASE_QTY
                         , REASON_CD, REMAIN_QTY, CLASS_NAME, COMPANY_ID, PLANT_ID )
                    SELECT   V_PLAN_TP_CD
                           , V_PLAN_START_YYYYMMDD
                           , 'EOH'
                           , V_REASON_CD
                           , V_DIVISION_ID
                           , V_S_GROUP_CODE1
                           , V_ITEM_CLASS
                           , V_PLAN_YYYYMM
                           , V_PLAN_YYYYMM
                           , 0
                           , V_SALE_QTY
                           , V_REASON_CD
                           , V_SALE_QTY * (-1)
                           , V_CLASS_NAME
                           , V_COMPANY_ID
                           , V_PLANT_ID
                      FROM   DUAL;
                END IF;
            END LOOP;
            CLOSE CURRENT_MONTH_SALES_CUR;

            /* -------------------------------------------------------- */
            /* 당월 EOH를 차월 BOH로 반영 (재귀 CTE SEQ : LV 1,2) */
            /* -------------------------------------------------------- */
            INSERT INTO SCM_LGTM_INV_PSI_SUMMARY_SPRD_IGR
                 ( PLAN_TP_CD, PLAN_START_YYYYMMDD, DATA_TP_CD, SRCE_TP_CD, DIVISION_ID
                 , GROUP_CODE1, ITEM_CLASS, SRCE_YYYYMM, PLAN_YYYYMM, QTY
                 , DEVALUATION_AGE, LONG_TERM_TYPE_CODE, LONG_TERM_TYPE, CLASS_NAME
                 , COMPANY_ID, PLANT_ID )
            WITH SEQ (LV) AS
            (
                SELECT 1 LV FROM DUAL
                UNION ALL
                SELECT LV + 1 FROM SEQ WHERE LV + 1 < 3
            )
            SELECT   EOH.PLAN_TP_CD
                   , EOH.PLAN_START_YYYYMMDD
                   , CASE WHEN SEQ.LV = 1 THEN EOH.DATA_TP_CD ELSE 'BOH' END AS DATA_TP_CD
                   , EOH.SRCE_TP_CD
                   , EOH.DIVISION_ID
                   , EOH.GROUP_CODE1
                   , EOH.ITEM_CLASS
                   , EOH.SRCE_YYYYMM
                   , CASE WHEN SEQ.LV = 1 THEN EOH.PLAN_YYYYMM
                          ELSE TO_CHAR(ADD_MONTHS(TO_DATE(V_PLAN_YYYYMMDD, 'YYYYMMDD'), V_COUNTER), 'YYYYMM')
                          END AS PLAN_YYYYMM
                   , EOH.REMAIN_QTY AS QTY
                   , EOH.DEVALUATION_AGE
                   , EOH.LONG_TERM_TYPE_CODE
                   , EOH.LONG_TERM_TYPE
                   , EOH.CLASS_NAME
                   , EOH.COMPANY_ID
                   , EOH.PLANT_ID
              FROM   SCM_LGTM_INV_PSI_DETAIL_SPRD_IGR EOH
                   , SEQ
             WHERE   1 = 1
               AND   EOH.PLAN_TP_CD          = V_PLAN_TP_CD
               AND   EOH.PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
               AND   EOH.DATA_TP_CD          = 'EOH'
               AND   EOH.DIVISION_ID         = V_DIVISION_ID
               AND   EOH.PLAN_YYYYMM         = V_PLAN_YYYYMM
               AND   EOH.REMAIN_QTY         <> 0;

            V_COUNTER := V_COUNTER + 1;
        END LOOP;

        /* ------------------------------------------------------------ */
        /* Step 4-1. 재고 월령(LONG_TERM_TYPE/DEVALUATION_AGE) 일괄 UPDATE */
        /*   #TMP_LONG_TERM_TYPE 룩업 에서 인라인 상관 서브쿼리 */
        /* ------------------------------------------------------------ */
        UPDATE  SCM_LGTM_INV_PSI_SUMMARY_SPRD_IGR A
           SET  ( LONG_TERM_TYPE, LONG_TERM_TYPE_CODE ) =
                (
                    SELECT B.LONG_TERM_TYPE, B.LONG_TERM_TYPE_CODE
                      FROM ( SELECT LMD.SEGMENT1 AS LONG_TERM_TYPE_CODE
                                  , LMD.SEGMENT2 AS LONG_TERM_TYPE
                                  , LMD.SEGMENT3 AS GRM_MM_FROM
                                  , LMD.SEGMENT4 AS GRM_MM_TO
                               FROM SCM_ADM_LOOKUP_MASTER_DETAIL LMD
                                  , SCM_ADM_LOOKUP_MASTER ALM
                              WHERE ALM.LOOKUP_TYPE = LMD.LOOKUP_TYPE
                                AND ALM.LOOKUP_TYPE = 'SCM_LGTM_TYPE'
                                AND ALM.VALID_YN = 'Y'
                                AND LMD.VALID_YN = 'Y' ) B
                     WHERE MONTHS_BETWEEN( TO_DATE(A.PLAN_YYYYMM || '01', 'YYYYMMDD')
                                         , TO_DATE(A.SRCE_YYYYMM || '01', 'YYYYMMDD') ) >= TO_NUMBER(B.GRM_MM_FROM)
                       AND MONTHS_BETWEEN( TO_DATE(A.PLAN_YYYYMM || '01', 'YYYYMMDD')
                                         , TO_DATE(A.SRCE_YYYYMM || '01', 'YYYYMMDD') ) <= TO_NUMBER(B.GRM_MM_TO)
                )
              , DEVALUATION_AGE =
                'GRM' || SUBSTR( '00' || TO_CHAR( MONTHS_BETWEEN( TO_DATE(A.PLAN_YYYYMM || '01', 'YYYYMMDD')
                                                               , TO_DATE(A.SRCE_YYYYMM || '01', 'YYYYMMDD') ) ), -2 )
         WHERE  1 = 1
           AND  A.PLAN_TP_CD          = V_PLAN_TP_CD
           AND  A.PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
           AND  A.DIVISION_ID         = V_DIVISION_ID;

        /* ------------------------------------------------------------ */
        /* Step 5-1. Update RESULT Amount from Item Summary */
        /* ------------------------------------------------------------ */
        UPDATE  SCM_LGTM_INV_PSI_SUMMARY_SPRD_IGR GR
           SET  CURRENCY      = 'KRW'
              , STANDARD_COST = 1
              , AMT = ( SELECT AM.AMT
                          FROM ( SELECT  SM.COMPANY_ID  AS COMPANY_ID
                                       , SM.DIVISION_ID AS DIVISION_ID
                                       , SM.GROUP_CODE1 AS GROUP_CODE1
                                       , CASE WHEN L.ATTRIBUTE2 IS NOT NULL THEN L.ATTRIBUTE2 ELSE '*' END AS ITEM_CLASS
                                       , SM.DATA_TP_CD  AS DATA_TP_CD
                                       , SM.SRCE_TP_CD  AS SRCE_TP_CD
                                       , SM.SRCE_YYYYMM AS SRCE_YYYYMM
                                       , SM.PLAN_YYYYMM AS PLAN_YYYYMM
                                       , SUM(NVL(SM.AMT, 0)) AS AMT
                                   FROM  SCM_LGTM_INV_PSI_SUMMARY_SPRD SM
                                       , ( SELECT DISTINCT DIVISION_ID, ITEM_ID, MAX(ITEM_CLASS) ITEM_CLASS
                                             FROM SCM_ITEM_M_SN
                                            GROUP BY DIVISION_ID, ITEM_ID ) SIM
                                       , SCM_MST_ITEM_CLASS_M CLS
                                       , SCM_ADM_LOOKUP_MASTER_DETAIL L
                                  WHERE  1 = 1
                                    AND  SIM.DIVISION_ID(+) = SM.DIVISION_ID
                                    AND  SIM.ITEM_ID(+)     = SM.ITEM_ID
                                    AND  CLS.CLASS_ID(+)    = SIM.ITEM_CLASS
                                    AND  L.LOOKUP_TYPE(+)   = 'SCM_LGTM_ELTR_ITEM_CLASS_CD'
                                    AND  L.VALID_YN(+)      = 'Y'
                                    AND  L.SEGMENT1(+)      = SIM.ITEM_CLASS
                                    AND  SM.PLAN_TP_CD          = V_SRCE_PLAN_TP_CD
                                    AND  SM.PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
                                    AND  SM.DIVISION_ID         = V_DIVISION_ID
                                    AND  SM.DATA_TP_CD          = 'RESULT'
                                  GROUP BY SM.DIVISION_ID
                                       , SM.GROUP_CODE1
                                       , CASE WHEN L.ATTRIBUTE2 IS NOT NULL THEN L.ATTRIBUTE2 ELSE '*' END
                                       , SM.DATA_TP_CD
                                       , SM.SRCE_TP_CD
                                       , SM.SRCE_YYYYMM
                                       , SM.PLAN_YYYYMM
                                       , SM.COMPANY_ID ) AM
                         WHERE 1 = 1
                           AND AM.DATA_TP_CD  = GR.DATA_TP_CD
                           AND AM.SRCE_TP_CD  = GR.SRCE_TP_CD
                           AND AM.DIVISION_ID = GR.DIVISION_ID
                           AND AM.GROUP_CODE1 = GR.GROUP_CODE1
                           AND AM.ITEM_CLASS  = GR.ITEM_CLASS
                           AND AM.SRCE_YYYYMM = GR.SRCE_YYYYMM
                           AND AM.PLAN_YYYYMM = GR.PLAN_YYYYMM
                           AND AM.COMPANY_ID  = GR.COMPANY_ID )
         WHERE  1 = 1
           AND  GR.PLAN_TP_CD          = V_PLAN_TP_CD
           AND  GR.PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
           AND  GR.DIVISION_ID         = V_DIVISION_ID
           AND  GR.DATA_TP_CD          = 'RESULT';

        /* ------------------------------------------------------------ */
        /* Step 5-2. Update Standard Cost by AVG for each item except RESULT */
        /* ------------------------------------------------------------ */
        UPDATE  SCM_LGTM_INV_PSI_SUMMARY_SPRD_IGR IGR
           SET  CURRENCY      = 'KRW'
              , STANDARD_COST = ( SELECT COST.STANDARD_COST
                                    FROM ( SELECT  SM.COMPANY_ID
                                                 , SM.DIVISION_ID
                                                 , SM.GROUP_CODE1
                                                 , CASE WHEN L.ATTRIBUTE2 IS NOT NULL THEN L.ATTRIBUTE2 ELSE '*' END AS ITEM_CLASS
                                                 , SM.DATA_TP_CD
                                                 , SM.PLAN_YYYYMM
                                                 , CASE WHEN SUM(ABS(SM.QTY)) = 0 THEN 0
                                                        ELSE SUM(ABS(SM.AMT)) / SUM(ABS(SM.QTY)) END AS STANDARD_COST
                                            FROM  SCM_LGTM_INV_PSI_SUMMARY_SPRD SM
                                                , ( SELECT DISTINCT DIVISION_ID, ITEM_ID, ITEM_CLASS
                                                      FROM SCM_ITEM_M_SN ) SIM
                                                , SCM_MST_ITEM_CLASS_M CLS
                                                , SCM_ADM_LOOKUP_MASTER_DETAIL L
                                           WHERE  1 = 1
                                             AND  SIM.DIVISION_ID(+) = SM.DIVISION_ID
                                             AND  SIM.ITEM_ID(+)     = SM.ITEM_ID
                                             AND  CLS.CLASS_ID(+)    = SIM.ITEM_CLASS
                                             AND  L.LOOKUP_TYPE(+)   = 'SCM_LGTM_ELTR_ITEM_CLASS_CD'
                                             AND  L.VALID_YN(+)      = 'Y'
                                             AND  L.SEGMENT1(+)      = SIM.ITEM_CLASS
                                             AND  SM.PLAN_TP_CD          = V_SRCE_PLAN_TP_CD
                                             AND  SM.PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
                                             AND  SM.DIVISION_ID         = V_DIVISION_ID
                                             AND  SM.DATA_TP_CD         != 'RESULT'
                                           GROUP BY SM.DIVISION_ID
                                                 , SM.GROUP_CODE1
                                                 , CASE WHEN L.ATTRIBUTE2 IS NOT NULL THEN L.ATTRIBUTE2 ELSE '*' END
                                                 , SM.DATA_TP_CD
                                                 , SM.PLAN_YYYYMM
                                                 , SM.COMPANY_ID ) COST
                                   WHERE COST.DIVISION_ID = IGR.DIVISION_ID
                                     AND COST.GROUP_CODE1 = IGR.GROUP_CODE1
                                     AND COST.ITEM_CLASS  = IGR.ITEM_CLASS
                                     AND COST.DATA_TP_CD  = IGR.DATA_TP_CD
                                     AND COST.PLAN_YYYYMM = IGR.PLAN_YYYYMM
                                     AND COST.COMPANY_ID  = IGR.COMPANY_ID )
         WHERE  1 = 1
           AND  IGR.PLAN_TP_CD          = V_PLAN_TP_CD
           AND  IGR.PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
           AND  IGR.DIVISION_ID         = V_DIVISION_ID
           AND  IGR.DATA_TP_CD         != 'RESULT';

        /* ------------------------------------------------------------ */
        /* Step 5-2. Update AMOUNT */
        /* ------------------------------------------------------------ */
        UPDATE  SCM_LGTM_INV_PSI_SUMMARY_SPRD_IGR
           SET  AMT = STANDARD_COST * QTY
         WHERE  1 = 1
           AND  PLAN_TP_CD          = V_PLAN_TP_CD
           AND  PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
           AND  DIVISION_ID         = V_DIVISION_ID
           AND  DATA_TP_CD         != 'RESULT';

        /* ------------------------------------------------------------ */
        /* Step 5-3. Clear Non-ELTR BOH/EOH (음수 에서 0) */
        /* ------------------------------------------------------------ */
        UPDATE  SCM_LGTM_INV_PSI_SUMMARY_SPRD_IGR
           SET  QTY              = 0
              , AMT              = 0
              , LAST_UPDATE_DATE = SYSDATE
              , LAST_UPDATED_BY  = 'MINUS_TO_ZERO'
         WHERE  1 = 1
           AND  PLAN_TP_CD          = V_PLAN_TP_CD
           AND  PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
           AND  DIVISION_ID         = V_DIVISION_ID
           AND  ITEM_CLASS         <> 'ELTR'
           AND  DATA_TP_CD         IN ('BOH', 'EOH')
           AND  QTY                 < 0;

        COMMIT;

    EXCEPTION
        WHEN OTHERS THEN
            IF CURRENT_MONTH_PROD_CUR%ISOPEN THEN
                CLOSE CURRENT_MONTH_PROD_CUR;
            END IF;
            IF CURRENT_MONTH_SALES_CUR%ISOPEN THEN
                CLOSE CURRENT_MONTH_SALES_CUR;
            END IF;
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := 'ERROR_LINE : ' || SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 480);
            D_EVENT_DATE  := SYSDATE;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    END;

    /* ---------------------------------------------------------------- */
    /* 종료 LOG */
    /* ---------------------------------------------------------------- */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

END;

PROCEDURE PR_SCM_LGTM_PCY_INV_MGMT_PLAN_DATE_CREATE
(
    P_PLAN_START_YYYYMMDD  IN VARCHAR2
)
/*
 * Program ID   : PR_SCM_LGTM_PCY_INV_MGMT_PLAN_DATE_CREATE
 * Description  : Tac TIme Master History
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2025.07.22   ymh            [csr :E20250721-000256] Policy-based Inv - PLAN DATE 생성건
 * 2026.07.06   ZIONEX   [PJ202650304] NextSCM Migration
 */
IS

    /*   EXEC PR_SCM_LGTM_PCY_INV_MGMT_PLAN_DATE_CREATE('20250623'); */
    /*   EXEC PR_SCM_LGTM_PCY_INV_MGMT_PLAN_DATE_CREATE('20250630'); */
    /*   EXEC PR_SCM_LGTM_PCY_INV_MGMT_PLAN_DATE_CREATE('20250707'); */
    /*   EXEC PR_SCM_LGTM_PCY_INV_MGMT_PLAN_DATE_CREATE('20250714'); */

    /* Procedure 기본조건. */


    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME             VARCHAR2(150 CHAR) := 'PR_SCM_LGTM_PCY_INV_MGMT_PLAN_DATE_CREATE';
    V_LOG_TYPE                 VARCHAR2(30 CHAR);   /* START/END/ERROR/... */
    N_LOG_COUNT                NUMBER := 0;
    V_LOG_MESSAGE             VARCHAR2(1000 CHAR);
    V_DESCRIPTION             VARCHAR2(500 CHAR);
    D_EVENT_DATE              DATE;

    /* Parameter 대신 변수 할당 */
    V_PLAN_START_YYYYMMDD      VARCHAR2(8 CHAR) := P_PLAN_START_YYYYMMDD;   /* '20240701'; */
    V_CHK_PLAN_START_YYYYMMDD  VARCHAR2(8 CHAR);
BEGIN

    /* LOG 시작 */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := P_PLAN_START_YYYYMMDD;
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(P_PROGRAM_NAME => V_PROGRAM_NAME
                        ,P_LOG_TYPE     => V_LOG_TYPE
                        ,P_LOG_COUNT    => N_LOG_COUNT
                        ,P_LOG_MESSAGE  => V_LOG_MESSAGE
                        ,P_DESCRIPTION  => V_DESCRIPTION
                        ,P_EVENT_DATE   => D_EVENT_DATE);


    SAVEPOINT LGTM_PCY_INV_CREATE;

    BEGIN

        /* Step 1. Initialize Data */
        /* Step 1-1. Delete PLAN DATA */
        BEGIN

            DELETE
              FROM SCP_ANL_LGTM_PCY_INV_MGMT_PLAN
             WHERE 1=1
               AND PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD;

        END;

        SELECT MAX(PLAN_START_YYYYMMDD)
          INTO V_CHK_PLAN_START_YYYYMMDD
          FROM SCP_ANL_LGTM_PCY_INV_MGMT_PLAN
         WHERE PLAN_START_YYYYMMDD < V_PLAN_START_YYYYMMDD;

        BEGIN

            INSERT
              INTO SCP_ANL_LGTM_PCY_INV_MGMT_PLAN
            SELECT V_PLAN_START_YYYYMMDD AS PLAN_START_YYYYMMDD
                 , PLAN_TP_CD
                 , DIVISION_ID
                 , PLANT_ID
                 , ITEM_ID
                 , PLAN_YYYYMMDD
                 , OCCR_RSN_CD
                 , OCCR_RSN_CTN
                 , EXHT_TP_CD
                 , EXHT_TP_CTN
                 , QTY
                 , SUPPLIER_CODE
                 , SYSDATE AS CREATE_DATE
                 , 'SYSTEM' AS CREATED_BY
                 , SYSDATE AS LAST_UPDATE_DATE
                 , 'SYSTEM' AS LAST_UPDATED_BY
                 , V_PLAN_START_YYYYMMDD || '-' || TO_CHAR(SEQ1_SCP_ANL_LGTM_PCY_INV_MGMT_PLAN.NEXTVAL) AS REQUEST_NO
                 , COMPANY_ID
              FROM SCP_ANL_LGTM_PCY_INV_MGMT_PLAN
             WHERE PLAN_START_YYYYMMDD = V_CHK_PLAN_START_YYYYMMDD
               AND PLAN_YYYYMMDD >= SUBSTR(V_CHK_PLAN_START_YYYYMMDD, 1, 6) || '01';

        END;

        COMMIT;

    EXCEPTION
        WHEN OTHERS THEN


            ROLLBACK TO SAVEPOINT LGTM_PCY_INV_CREATE;

            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := 'ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
            D_EVENT_DATE  := SYSDATE;
            DBMS_OUTPUT.PUT_LINE('[' || TO_CHAR(SQLCODE) || ']' || SQLERRM);

            PR_SCM_SYS_LOG_BATCH(P_PROGRAM_NAME   => V_PROGRAM_NAME
                                ,P_LOG_TYPE       => V_LOG_TYPE
                                ,P_LOG_COUNT      => N_LOG_COUNT
                                ,P_LOG_MESSAGE    => V_LOG_MESSAGE
                                ,P_DESCRIPTION    => V_DESCRIPTION
                                ,P_EVENT_DATE     => D_EVENT_DATE
                                ,P_IN_PARA_DATA   => JSON_OBJECT('P_PLAN_START_YYYYMMDD' VALUE P_PLAN_START_YYYYMMDD RETURNING VARCHAR2(4000 CHAR))
                                ,P_SQL_ERR_CODE   => TO_CHAR(SQLCODE)
                                ,P_SQL_ERR_MSG    => SQLERRM
                                ,P_SQL_BACKTRACE  => DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
    END;


    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(P_PROGRAM_NAME => V_PROGRAM_NAME
                        ,P_LOG_TYPE     => V_LOG_TYPE
                        ,P_LOG_COUNT    => N_LOG_COUNT
                        ,P_LOG_MESSAGE  => V_LOG_MESSAGE
                        ,P_DESCRIPTION  => V_DESCRIPTION
                        ,P_EVENT_DATE   => D_EVENT_DATE);
END;

PROCEDURE PR_SCM_LGTM_STANDARD_COST_UPDATE
(
    P_PLAN_START_YYYYMMDD  IN VARCHAR2
  , P_BASE_YYYYMM          IN VARCHAR2
  , P_PLAN_TP_CD           IN VARCHAR2
)
/* ============================================================
 * Program ID   : PR_SCM_LGTM_STANDARD_COST_UPDATE
 * Description  : 표준원가(STANDARD_COST) 및 금액(AMT) 업데이트
 * Program History
 *------------------------------------------------------------
 * Date          In Charge      Description
 *------------------------------------------------------------
 * 2025.01.16    Y.S.H          Initial Release
 * 2026.07.06    ZIONEX         [PJ202650304]  NextSCM Migration
 * ============================================================ */
AS
    V_PROGRAM_NAME         VARCHAR2(150 CHAR) := 'PR_SCM_LGTM_MRP_P_RESULT';
    V_LOG_TYPE            VARCHAR2(30 CHAR);
    V_LOG_COUNT          NUMBER := 0;
    V_LOG_MESSAGE        VARCHAR2(1000 CHAR);
    V_DESCRIPTION        VARCHAR2(500 CHAR);
    V_EVENT_DATE         DATE;
    V_PLAN_START_YYYYMMDD VARCHAR2(8 CHAR);
    V_BASIS_YYYYMM       VARCHAR2(6 CHAR);
    V_MRP_P_VERSION_NO   VARCHAR2(50 CHAR);
    V_ADD_DAYS           NUMBER := 9;
    V_RESULT_YYYYMMDD    VARCHAR2(8 CHAR);
BEGIN

    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '';
    V_EVENT_DATE  := SYSTIMESTAMP;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, V_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, V_EVENT_DATE);


    V_PLAN_START_YYYYMMDD := NVL(P_PLAN_START_YYYYMMDD, TO_CHAR(SYSDATE, 'YYYYMMDD'));
    V_BASIS_YYYYMM        := NVL(P_BASE_YYYYMM, SUBSTR(TO_CHAR(ADD_MONTHS(SYSDATE, -1), 'YYYYMMDD'), 1, 6));

    BEGIN


        UPDATE SCM_LGTM_INV_PSI_SUMMARY_RMTL T
           SET T.CURRENCY = 'KRW'
             , T.STANDARD_COST = (SELECT COST.COST
                                    FROM (SELECT MM.DIVISION_ID, MM.PLANT_ID, MM.ITEM_ID, MM.YYYYMM, MM.COST
                                            FROM (SELECT INV.DIVISION_ID, INV.PLANT_ID, INV.ITEM_ID, INV.YYYYMM
                                                       , CASE WHEN SUM(INV.QUANTITY) = 0 THEN 0 ELSE SUM(INV.AMOUNT_KRW) / SUM(INV.QUANTITY) END AS COST
                                                    FROM SCP_ANL_MONTH_END_STOCK_R INV
                                                       , (SELECT ITEM_ID, MAX(SCP_EXTRA_SPEC) AS SCP_EXTRA_SPEC, MAX(ITEM_CLASS) AS ITEM_CLASS
                                                            FROM SCM_MST_ITEM_SN
                                                           GROUP BY ITEM_ID) C
                                                       , SCM_MST_ITEM_CLASS_M D
                                                   WHERE C.ITEM_ID = INV.ITEM_ID
                                                     AND C.ITEM_CLASS = D.CLASS_ID
                                                     AND 1 = 1
                                                     AND INV.DIVISION_ID = '82'
                                                     AND INV.YYYYMM = P_BASE_YYYYMM
                                                     AND CASE WHEN INV.VALUATION_CLASS IN ('3020','3030','3040') THEN '저장품'
                                                              WHEN INV.VALUATION_CLASS IN ('3100','3109') AND D.ITEM_TYPE = '원부자재' THEN '상품'
                                                              ELSE D.ITEM_TYPE
                                                         END = '원부자재'
                                                   GROUP BY INV.DIVISION_ID, INV.PLANT_ID, INV.ITEM_ID, INV.YYYYMM
                                                  HAVING SUM(INV.QUANTITY) != 0
                                                 ) MM
                                         ) COST
                                   WHERE COST.PLANT_ID = T.PLANT_ID
                                     AND COST.ITEM_ID  = T.ITEM_ID)
             , T.CST_CTN = T.CST_CTN || '||8182_SYSTEM'
         WHERE T.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND T.DIVISION_ID = '81'
           AND T.ITEM_ID IN (SELECT DISTINCT ITEM_ID
                               FROM SCM_LGTM_INV_PSI_SUMMARY_RMTL
                              WHERE 1 = 1
                                AND PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                                AND PLAN_TP_CD = P_PLAN_TP_CD
                                AND STANDARD_COST IS NULL)
           AND T.STANDARD_COST IS NULL
           AND T.PLAN_TP_CD = P_PLAN_TP_CD;


        UPDATE SCM_LGTM_INV_PSI_SUMMARY_RMTL T
           SET T.AMT = T.QTY * T.STANDARD_COST
         WHERE T.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND T.DIVISION_ID = '81'
           AND T.ITEM_ID IN (SELECT DISTINCT ITEM_ID
                               FROM SCM_LGTM_INV_PSI_SUMMARY_RMTL
                              WHERE 1 = 1
                                AND PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                                AND STANDARD_COST IS NULL)
           AND T.PLAN_TP_CD = P_PLAN_TP_CD
           AND T.CST_CTN LIKE '%8182%';

        /* 금액(AMT) 업데이트 (2) 단일 ITEM MFL01790AA 보정 */
        UPDATE SCM_LGTM_INV_PSI_SUMMARY_RMTL T
           SET T.AMT = T.QTY * T.STANDARD_COST
         WHERE T.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND T.DIVISION_ID = '81'
           AND T.PLAN_TP_CD = P_PLAN_TP_CD
           AND T.CST_CTN LIKE '%8182%'
           AND T.ITEM_ID = 'MFL01790AA'
           AND T.AMT IS NULL;


        UPDATE SCM_LGTM_INV_PSI_SUMMARY_RMTL T
           SET T.AMT = T.QTY * T.STANDARD_COST
         WHERE T.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND T.DIVISION_ID = '81'
           AND T.PLAN_TP_CD = P_PLAN_TP_CD
           AND T.CST_CTN LIKE '%8182%'
           AND T.STANDARD_COST IS NOT NULL
           AND T.QTY IS NOT NULL
           AND T.AMT IS NULL;

        COMMIT;

    EXCEPTION
        WHEN OTHERS THEN
            ROLLBACK;
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := SUBSTR('ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 500);
            V_EVENT_DATE  := SYSTIMESTAMP;
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SQLCODE) || SQLERRM);
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, V_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, V_EVENT_DATE);
    END;

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    V_EVENT_DATE  := SYSTIMESTAMP;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, V_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, V_EVENT_DATE);

END;

PROCEDURE           "PR_SCM_MST_DEPT_INFO" 

/*
 * Program ID   : PR_SCM_MST_DEPT_INFO
 * Description  : 부서정보 I/F
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2017.11.22   Kim Jaejung    Initial Release 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 * 2020.12.15   P.C.I		   [C20201215-000324] ensol 분사 후 2level_dept_id에 ensol 적용
 * 2026.07.06   ZIONEX		   [PJ202650304] NextSCM Migration
 *
 */
IS
    /* LOG 용 변수 설정 */
    V_BATCH_USER    VARCHAR2(150 CHAR) := 'scm_batch';
    V_PROGRAM_NAME  VARCHAR2(150 CHAR) := 'PR_SCM_MST_DEPT_INFO';
    V_LOG_TYPE      VARCHAR2(30 CHAR);          /* START/END/ERROR/... */
    N_LOG_COUNT     PLS_INTEGER := 0;
    V_LOG_MESSAGE   VARCHAR2(1000 CHAR);
    V_DESCRIPTION   VARCHAR2(500 CHAR);
    D_EVENT_DATE    DATE;
    V_FIRST_DEPT    VARCHAR2(150 CHAR);
    V_IFSEQNO       VARCHAR2(30 CHAR);          /* 누락된 전체 데이터 insert */

    /* 지나간 배치까지 적용하기 위해 Cursor 로 처리 */
    CURSOR CUR_SSO_DEPT IS
        SELECT IFSEQNO
          FROM XIF_SSO_DEPT_INFO_R_SN
         WHERE TRANSFER_FLAG = 'P'
         GROUP BY IFSEQNO
         ORDER BY IFSEQNO ASC;
BEGIN
    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '[dbo].[XIF_SSO_DEPT_INFO_R_SN] to [scm_mst_sso_dept_info]';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    BEGIN
        /* 인터페이스 테이블 처리 ROW UPDATE */
        UPDATE XIF_SSO_DEPT_INFO_R_SN
           SET TRANSFER_FLAG = 'P'
         WHERE NVL(TRANSFER_FLAG, 'N') = 'N';

        /* History 데이터 처리를 위한 TEMP Table 삭제 및 생성 — 원본의 scm_mst_customer_temp$ DROP 은 */

        FOR R IN CUR_SSO_DEPT LOOP
            V_IFSEQNO := R.IFSEQNO;

            MERGE INTO SCM_MST_SSO_DEPT_INFO A
            USING (SELECT /* PR_SCM_MST_DEPT_INFO */
                          B0.CODE_NUMB
                        , B0.CODE_NAME_KO
                        , B0.CODE_NAME_EN
                        , B0.CODE_NAME_CN
                        , B0.CODE_UPER
                        , B0.VALID_FLAG
                        , B0.CREATE_DATE
                     FROM XIF_SSO_DEPT_INFO_R_SN B0
                    WHERE B0.IFSEQNO = V_IFSEQNO
                      AND B0.TRANSFER_FLAG = 'P') B
            ON (A.DEPT_ID = B.CODE_NUMB)
            WHEN MATCHED THEN
                UPDATE
                   SET A.DEPT_NAME_KO     = B.CODE_NAME_KO
                     , A.DEPT_NAME_EN     = B.CODE_NAME_EN
                     , A.DEPT_NAME_CN     = B.CODE_NAME_CN
                     , A.UPPER_DEPT_ID    = B.CODE_UPER
                     , A.VALID_YN         = NVL(B.VALID_FLAG, 'Y')
                     , A.LAST_UPDATED_BY  = V_BATCH_USER
                     , A.LAST_UPDATE_DATE = SYSDATE
            WHEN NOT MATCHED THEN
                INSERT
                    ( DEPT_ID
                    , DEPT_NAME_KO
                    , DEPT_NAME_EN
                    , DEPT_NAME_CN
                    , UPPER_DEPT_ID
                    , VALID_YN
                    , CREATED_BY
                    , CREATION_DATE
                    , LAST_UPDATED_BY
                    , LAST_UPDATE_DATE )
                VALUES
                    ( B.CODE_NUMB
                    , B.CODE_NAME_KO
                    , B.CODE_NAME_EN
                    , B.CODE_NAME_CN
                    , B.CODE_UPER
                    , NVL(B.VALID_FLAG, 'Y')
                    , V_BATCH_USER
                    , SYSDATE
                    , V_BATCH_USER
                    , SYSDATE );

            /* --------------------------------------------------------- */
            /* Merge LOG */
            /* --------------------------------------------------------- */
            V_LOG_TYPE    := 'APPEND';
            V_LOG_MESSAGE := 'MERGE INTO scm_mst_sso_dept_info';
            V_DESCRIPTION := 'ifseqno = ' || V_IFSEQNO;
            D_EVENT_DATE  := SYSDATE;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
            /* --------------------------------------------------------- */
        END LOOP;

        /* 처리 한 row 마킹 */
        UPDATE XIF_SSO_DEPT_INFO_R_SN
           SET TRANSFER_FLAG = 'Y'
         WHERE TRANSFER_FLAG = 'P';

        /* 부서 코드에서 2레벨에 해당하는 코드 INSERT */
        BEGIN
            SELECT SEGMENT1
              INTO V_FIRST_DEPT
              FROM SCM_ADM_LOOKUP_MASTER_DETAIL
             WHERE LOOKUP_TYPE = '1LEVEL_DEPT_ID'
               AND VALID_YN = 'Y'
               AND ROWNUM = 1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                V_FIRST_DEPT := NULL;
        END;


        DELETE
          FROM GT_SMDI_DEPT;

        INSERT
          INTO GT_SMDI_DEPT
             ( CHILD
             , NAME
             , PARENT
             , SORT
             , DEPT_LEVEL2
             , DEPT_NAME )
        WITH DEPT_LEVEL (CHILD, NAME, PARENT, SORT, DEPT_LEVEL2, DEPT_NAME)
          AS (SELECT DEPT_ID AS CHILD
                   , DEPT_NAME_KO AS CODE_NAME_KO
                   , UPPER_DEPT_ID AS PARENT
                   , CAST(DEPT_ID AS VARCHAR2(255 CHAR)) AS SORT
                   , CAST('' AS VARCHAR2(255 CHAR)) AS DEPT_LEVEL2
                   , CAST(DEPT_NAME_KO AS VARCHAR2(255 CHAR)) AS DEPT_NAME
                FROM SCM_MST_SSO_DEPT_INFO
               WHERE DEPT_ID = V_FIRST_DEPT
              UNION ALL
              SELECT B.DEPT_ID AS CHILD
                   , B.DEPT_NAME_KO AS NAME
                   , B.UPPER_DEPT_ID AS PARENT
                   , CAST(SUBSTR(C.SORT||'>'||B.DEPT_ID, 1, 255) AS VARCHAR2(255 CHAR)) AS SORT
                   , CAST('' AS VARCHAR2(255 CHAR)) AS DEPT_LEVEL2
                   , CAST(SUBSTR(C.DEPT_NAME||'>'||B.DEPT_NAME_KO, 1, 255) AS VARCHAR2(255 CHAR)) AS DEPT_NAME
                FROM SCM_MST_SSO_DEPT_INFO B
                   , DEPT_LEVEL           C
               WHERE B.UPPER_DEPT_ID = C.CHILD)
        SELECT CHILD
             , NAME
             , PARENT
             , SORT
             /* [C20201215-000324] ensol 분사 후 2level_dept_id에 ensol 적용 */
             , CASE WHEN INSTR(SORT, '>') > 1 THEN SUBSTR(SORT, 1, INSTR(SORT, '>') - 1) ELSE SORT END AS DEPT_LEVEL2
             /*,CASE WHEN CHARINDEX('>',REPLACE(sort,@v_first_dept+'>','')) > 1
                    THEN SUBSTRING(REPLACE(sort,@v_first_dept+'>',''),0,CHARINDEX('>',REPLACE(sort,@v_first_dept+'>','')))
                    ELSE REPLACE(sort,@v_first_dept+'>','') END dept_level2*/
             , CASE WHEN INSTR(REPLACE(DEPT_NAME, 'LG Chem>', ''), '>') > 1
                    THEN SUBSTR(REPLACE(DEPT_NAME, 'LG Chem>', ''), 1, INSTR(REPLACE(DEPT_NAME, 'LG Chem>', ''), '>') - 1)
                    ELSE REPLACE(DEPT_NAME, 'LG Chem>', '') END AS DEPT_NAME
          FROM DEPT_LEVEL;

        /* 부서 레벨 및 부서명 표시, 개발용 추후 다시 확인 */
        MERGE INTO SCM_MST_SSO_DEPT_INFO A
        USING (SELECT /* PR_SCM_MST_DEPT_INFO_2LEVEL_DEPT */
                      CHILD
                    , NAME
                    , PARENT
                    , SORT
                    , DEPT_LEVEL2
                    , DEPT_NAME
                 FROM GT_SMDI_DEPT) B
        ON (A.DEPT_ID = B.CHILD
        AND A.UPPER_DEPT_ID = B.PARENT)
        WHEN MATCHED THEN
            UPDATE
               SET A."2LEVEL_DEPT_ID" = B.DEPT_LEVEL2
                 , A.ATTRIBUTE1       = B.DEPT_NAME
                 , A.ATTRIBUTE2       = B.SORT;

        COMMIT;

    EXCEPTION
        WHEN OTHERS THEN
            /* ERROR LOG */
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := SUBSTR('ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 500);
            D_EVENT_DATE  := SYSDATE;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    END;

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

END PR_SCM_MST_DEPT_INFO;

PROCEDURE PR_SCM_MST_EXCHANGE_RATE
(
      P_BATCH_YN  VARCHAR2 DEFAULT 'Y'  /* [PJ2025-50188]소형 매출계획 동기화 개선 고도화 : P_BATCH_YN 파라미터 추가하여 배치수행/화면수행 구분 */
)
/*
    * Program ID   : PR_SCM_MST_EXCHANGE_RATE
    * Description  : Chempion 환율 I/F Procedure
    * PARAMETER    : N/A
    * DESCRIPTION  : Chempion 환율 I/F
    * I/F Table    : XIF_GSC_MOVE_EXCHANGE_RATE_SN
    * Program History
    *===================================================================================================
    *   Date       In Charge      Description
    *===================================================================================================
    * 2021.05.13   P.C.I          PJ20209642R Chempion 환율 I/F
    * 2022.03.25   sclee          PJ20216891 LGES Digital SCM 3 Level 가속화를 위한 개선 - 새사업부 추가
    * 2022.05.11   HWI1993        GM JV 수정
    * 2022.11.17   kdw2819        [C20221116-000471]환율정보 수신 배치 오류
    * 2022.11.28   chano0612      [C20221124-000290]환율 IF관련 수정 요청 건
    * 2025.06.24   kjiyoon        [PJ2025-50188]소형 매출계획 동기화 개선 고도화 : 사용자 환율팝업 적용 - 화면 호출용 프로시저 수행 성공/실패 output 추가
    * 2025.07.03   kjiyoon        [PJ2025-50188]소형 매출계획 동기화 개선 고도화 : P_BATCH_YN 파라미터 추가
    * 2025.09.15   김준규           IT20250117A NERP ROLLIN 3차 현재 CNY를 RMB로 변경 저장하는 것을 CNY 그대로 저장변경
    * 2026.03.24   김준규           [PJ20264226] NextSCM Pilot 설계 및 개발
 * 2026.07.06	ZIONEX		[PJ202650304] NextSCM Migration
    */
 AS
    /* ------------------------------------------------------------------------- */
    C_DIVISION_ID       VARCHAR2(30 CHAR);
    C_SCENARIO_TYPE_CD  VARCHAR2(06 CHAR);
    C_PLN_PERIOD_YYYYMM VARCHAR2(06 CHAR);
    C_CURRENCY_CD       VARCHAR2(15 CHAR);
    C_IF_SEQ            NUMBER(16, 0);
    V_RECEIVE_CNT       NUMBER(16, 0);
    V_BATCH_USER        VARCHAR2(150 CHAR) := 'scm_batch';
    V_PROGRAM_NAME      VARCHAR2(150 CHAR) := $$PLSQL_UNIT;
    V_LOG_TYPE          VARCHAR2(30 CHAR);
    N_LOG_COUNT         INTEGER := 0;
    V_LOG_MESSAGE       VARCHAR2(1000 CHAR);
    V_DESCRIPTION       VARCHAR2(500 CHAR);
    D_EVENT_DATE        DATE;
    N_HISTORY_SEQ       NUMBER;
    V_IFSEQNO           VARCHAR2(30 CHAR);
    V_IN_PARA_DATA      VARCHAR2(4000 CHAR);
    V_RESULT_CURSOR     SYS_REFCURSOR;
    CUR_E               SYS_REFCURSOR;

    CURSOR CUR_D IS
        SELECT DIVISION_ID
          FROM GT_SMER_I_DIVISION;
BEGIN

    /* ------------------------------------------------------------------------- */
    /* LOG 용 변수 설정 */
    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := ('P_BATCH_YN = ' || NVL(P_BATCH_YN, 'X')); /* [PJ2025-50188]소형 매출계획 동기화 개선 고도화 : P_BATCH_YN 파라미터 추가 */
    D_EVENT_DATE  := SYSTIMESTAMP;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    /* GTT 초기화 : TRUNCATE 는 DDL 이라 암시 COMMIT 이 발생해 상위 트랜잭션의 ROLLBACK 을 무력화한다 -> DELETE 사용 */
    DELETE FROM GT_SMER_I_DIVISION;

    /* 자동차, ESS, 소형 작업 */
    /* [PJ2025-50188]소형 매출계획 동기화 개선 고도화 : P_BATCH_YN 파라미터 추가 START */
    /* 기존로직 주석처리 */
    /* INSERT +NO_PARALLEL INTO GT_SMER_I_DIVISION (division_id) */
    /* SELECT DIVISION_ID */
    /* FROM SCM_MST_DIVISION */
    /* WHERE ATTRIBUTE3 IN ('40','81', '82' ) */
    IF P_BATCH_YN = 'Y' THEN
        /* 대상 사업부 */
        INSERT
          INTO GT_SMER_I_DIVISION
             ( DIVISION_ID )
        SELECT DIVISION_ID
          FROM SCM_MST_DIVISION
         WHERE ATTRIBUTE3 IN ('81', '82');

        /* 대상 IF 환율 */

        /* CUR_E CURSOR LOCAL FOR */
        OPEN CUR_E FOR
        SELECT SCENARIO_TYPE_CD
             , PLN_PERIOD_YYYYMM
             , CURRENCY_CD
             , IF_SEQ
          FROM (SELECT E.SCENARIO_TYPE_CD
                     , E.PLN_PERIOD_YYYYMM
                     , E.CURRENCY_CD
                     , E.IF_SEQ
                  FROM XIF_GSC_MOVE_EXCHANGE_RATE_SN E
                 WHERE NVL(E.TRANSF_FLAG, 'N') = 'N'
                   AND SCENARIO_TYPE_CD IN ('ML', 'RF') /* [C20221124-000290] SCENARIO_TYPE_CD를 ML, RF만 등록한다.. */
                 GROUP BY E.SCENARIO_TYPE_CD, E.PLN_PERIOD_YYYYMM, E.CURRENCY_CD, E.IF_SEQ) X
         ORDER BY PLN_PERIOD_YYYYMM, CURRENCY_CD, IF_SEQ, SCENARIO_TYPE_CD;
    ELSE
        /* 대상 사업부 */
        INSERT
          INTO GT_SMER_I_DIVISION
             ( DIVISION_ID )
        SELECT DIVISION_ID
          FROM SCM_MST_DIVISION
         WHERE ATTRIBUTE3 IN ('40');

        /* 대상 IF 환율 */

        /* CUR_E CURSOR LOCAL FOR */
        OPEN CUR_E FOR
        SELECT SCENARIO_TYPE_CD
             , PLN_PERIOD_YYYYMM
             , CURRENCY_CD
             , IF_SEQ
          FROM (SELECT E.SCENARIO_TYPE_CD
                     , E.PLN_PERIOD_YYYYMM
                     , E.CURRENCY_CD
                     , E.IF_SEQ
                  FROM XIF_GSC_MOVE_EXCHANGE_RATE_SN E
                 WHERE E.TRANSF_DATE = (SELECT MAX(A.TRANSF_DATE)
                                          FROM XIF_GSC_MOVE_EXCHANGE_RATE_SN A
                                         WHERE 1 = 1
                                           AND A.SCENARIO_TYPE_CD IN ('ML', 'RF'))
                   AND SCENARIO_TYPE_CD IN ('ML', 'RF') /* [C20221124-000290] SCENARIO_TYPE_CD를 ML, RF만 등록한다.. */
                 GROUP BY E.SCENARIO_TYPE_CD, E.PLN_PERIOD_YYYYMM, E.CURRENCY_CD, E.IF_SEQ) X
         ORDER BY PLN_PERIOD_YYYYMM, CURRENCY_CD, IF_SEQ, SCENARIO_TYPE_CD;
    END IF;

    /* [PJ2025-50188]소형 매출계획 동기화 개선 고도화 : P_BATCH_YN 파라미터 추가 END */
    /* DELETE FROM DM_MST_EXCHANGE_RATE WHERE YYYYMMDD BETWEEN TO_CHAR(ADD_MONTHS(SYSDATE, 0), 'YYYYMMDD') || '01' AND TO_CHAR(ADD_MONTHS(SYSDATE, 12), 'YYYYMMDD') || '01' */
    /* [C20221124-000290] DM_MST_EXCHANGE_RATE 에 존재하는 기존 데이터를 삭제한다. */
    /* 위로 로직 이동해서 아래 CURSOR 주석처리 - [PJ2025-50188]소형 매출계획 동기화 개선 고도화 : P_BATCH_YN 파라미터 추가 */
    /* CURSOR 환율 정보 수신 (KEY : SCENARIO_TYPE_CD, PLN_PERIOD_YYYYMM, CURRENCY_CD, IF_SEQ) */

    /* CUR_E CURSOR LOCAL FOR */
    /* select SCENARIO_TYPE_CD, PLN_PERIOD_YYYYMM, CURRENCY_CD, IF_SEQ */
    /* from ( select E.SCENARIO_TYPE_CD */
    /*           , E.PLN_PERIOD_YYYYMM */
    /*           , E.CURRENCY_CD */
    /*           , E.IF_SEQ */
    /*       from XIF_GSC_MOVE_EXCHANGE_RATE_SN E */

    /*       AND SCENARIO_TYPE_CD IN ('ML', 'RF') [C20221124-000290] SCENARIO_TYPE_CD를 ML, RF만 등록한다.. */
    /*       group by E.SCENARIO_TYPE_CD */
    /*           , E.PLN_PERIOD_YYYYMM */
    /*           , E.CURRENCY_CD */
    /*           , E.IF_SEQ */
    /*           ) x */
    /* ORDER BY PLN_PERIOD_YYYYMM, CURRENCY_CD, IF_SEQ, SCENARIO_TYPE_CD */
    /* CURSOR 환율 정보 수신 (KEY : SCENARIO_TYPE_CD, PLN_PERIOD_YYYYMM, CURRENCY_CD, IF_SEQ) */

    /* CUR_D CURSOR FOR */

    NULL;

    /* ------------------------------------------------------------------------- */

    /* Start 환율 Cursor */
    V_RECEIVE_CNT := 0;

    FETCH CUR_E
        INTO C_SCENARIO_TYPE_CD, C_PLN_PERIOD_YYYYMM, C_CURRENCY_CD, C_IF_SEQ;
    WHILE (CUR_E%FOUND) LOOP
        /* ----------------------------------------------------------------- */
        /* * IT20250117A NERP ROLLIN 3차 현재 CNY를 RMB로 변경 저장하는 것을 CNY 그대로 저장변경 시작 */
        /* 변경전 상태 USING ( SELECT B.DIVISION_ID, A.YYYYMMDD, A.CURRENCY, REPLACE(A.UNIT_CURRENCY, 'CNY', 'RMB') UNIT_CURRENCY, A.EXCHANGE_PRICE */
        MERGE INTO DM_MST_EXCHANGE_RATE DME
        USING (SELECT B.DIVISION_ID
                    , A.YYYYMMDD
                    , A.CURRENCY
                    , /*REPLACE(A.UNIT_CURRENCY, 'CNY', 'RMB')*/ A.UNIT_CURRENCY AS UNIT_CURRENCY
                    , A.EXCHANGE_PRICE
                 FROM (SELECT PLN_YYYYMM || '01' AS YYYYMMDD
                            , 'KRW' AS CURRENCY
                            , CURRENCY_CD UNIT_CURRENCY
                            , KRW_CNVT_RATE EXCHANGE_PRICE
                         FROM XIF_GSC_MOVE_EXCHANGE_RATE_SN
                        WHERE SCENARIO_TYPE_CD = C_SCENARIO_TYPE_CD
                          AND PLN_PERIOD_YYYYMM = C_PLN_PERIOD_YYYYMM
                          AND CURRENCY_CD = C_CURRENCY_CD
                          AND IF_SEQ = C_IF_SEQ
                        UNION ALL
                       SELECT PLN_YYYYMM || '01' AS YYYYMMDD
                            , 'USD' AS CURRENCY
                            , CURRENCY_CD UNIT_CURRENCY
                            , USD_CNVT_RATE EXCHANGE_PRICE
                         FROM XIF_GSC_MOVE_EXCHANGE_RATE_SN
                        WHERE SCENARIO_TYPE_CD = C_SCENARIO_TYPE_CD
                          AND PLN_PERIOD_YYYYMM = C_PLN_PERIOD_YYYYMM
                          AND CURRENCY_CD = C_CURRENCY_CD
                          AND IF_SEQ = C_IF_SEQ
                        UNION ALL
                       SELECT PLN_YYYYMM || '01' AS YYYYMMDD
                            , 'EUR' AS CURRENCY
                            , CURRENCY_CD UNIT_CURRENCY
                            , EUR_CNVT_RATE EXCHANGE_PRICE
                         FROM XIF_GSC_MOVE_EXCHANGE_RATE_SN
                        WHERE SCENARIO_TYPE_CD = C_SCENARIO_TYPE_CD
                          AND PLN_PERIOD_YYYYMM = C_PLN_PERIOD_YYYYMM
                          AND CURRENCY_CD = C_CURRENCY_CD
                          AND IF_SEQ = C_IF_SEQ) A
                    , GT_SMER_I_DIVISION B) XXX
        /* * IT20250117A NERP ROLLIN 3차 현재 CNY를 RMB로 변경 저장하는 것을 CNY 그대로 저장변경 종료 */
        ON (DME.DIVISION_ID = XXX.DIVISION_ID AND DME.YYYYMMDD = XXX.YYYYMMDD AND DME.CURRENCY = XXX.CURRENCY AND DME.UNIT_CURRENCY = XXX.UNIT_CURRENCY)
        WHEN MATCHED THEN
            UPDATE SET DME.EXCHANGE_PRICE = XXX.EXCHANGE_PRICE
                     , DME.LAST_UPDATED_BY = 'SYSTEM'
                     , DME.LAST_UPDATE_DATE = SYSDATE
        WHEN NOT MATCHED THEN
            INSERT
                 ( DIVISION_ID
                 , YYYYMMDD
                 , CURRENCY
                 , UNIT_CURRENCY
                 , EXCHANGE_PRICE
                 , CREATED_BY
                 , CREATION_DATE
                 , LAST_UPDATED_BY
                 , LAST_UPDATE_DATE )
            VALUES ( XXX.DIVISION_ID
                   , XXX.YYYYMMDD
                   , XXX.CURRENCY
                   , XXX.UNIT_CURRENCY
                   , XXX.EXCHANGE_PRICE
                   , 'SYSTEM'
                   , SYSDATE
                   , 'SYSTEM'
                   , SYSDATE );
        /* ----------------------------------------------------------------- */
        /* 배치일때만 업데이트하도록 조건추가 - [PJ2025-50188]소형 매출계획 동기화 개선 고도화 : P_BATCH_YN 파라미터 추가 */
        IF P_BATCH_YN = 'Y' THEN
            /* I/F Table TRANSF_FLAG 변경 */
            UPDATE XIF_GSC_MOVE_EXCHANGE_RATE_SN
               SET TRANSF_FLAG = 'Y'
             WHERE SCENARIO_TYPE_CD = C_SCENARIO_TYPE_CD
               AND PLN_PERIOD_YYYYMM = C_PLN_PERIOD_YYYYMM
               AND CURRENCY_CD = C_CURRENCY_CD
               AND IF_SEQ = C_IF_SEQ;
        END IF;

        V_RECEIVE_CNT := V_RECEIVE_CNT + 1;
        /* ----------------------------------------------------------------- */
        FETCH CUR_E
            INTO C_SCENARIO_TYPE_CD, C_PLN_PERIOD_YYYYMM, C_CURRENCY_CD, C_IF_SEQ;
    END LOOP;
    CLOSE CUR_E;

    /* End  환율 Cursor */
    /* Start  Sales Price, Sales Plan Cursor */
    /* select 'V_RECEIVE_CNT', V_RECEIVE_CNT */
    IF (V_RECEIVE_CNT > 0) THEN

        OPEN CUR_D;
        FETCH CUR_D
            INTO C_DIVISION_ID;
        WHILE (CUR_D%FOUND) LOOP

            /* select 'C_DIVISION_ID', C_DIVISION_ID */
            /* Sales Price Update */
            DMF0020_SAVE_SCM_MST_FUTURE_PRICE_CONVERSION(C_DIVISION_ID, V_RESULT_CURSOR);

            /* Sales Plan Update */
            PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW(C_DIVISION_ID, 'EXCHANGE_RATE');

            FETCH CUR_D
                INTO C_DIVISION_ID;
        END LOOP;
        CLOSE CUR_D;

    END IF;
    /* End  Sales Price, Sales Plan Cursor */
    /* 트랜잭션 종료 */
    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := NULL;
    D_EVENT_DATE  := SYSTIMESTAMP;

    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    COMMIT;
    NULL; /* [PJ2025-50188]소형 매출계획 동기화 개선 고도화 : 사용자 환율팝업 적용 */


EXCEPTION
    WHEN OTHERS THEN

        /* ERROR LOG */
        V_LOG_TYPE    := 'ERROR';
        V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
        V_DESCRIPTION := 'ERROR_LINE : ' || TO_CHAR(NULL);
        D_EVENT_DATE  := SYSTIMESTAMP;

        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        NULL;
        /* [PJ2025-50188]소형 매출계획 동기화 개선 고도화 : 사용자 환율팝업 적용 */


        RAISE_APPLICATION_ERROR(-20001
                               ,'[' || $$PLSQL_UNIT || '] SQLCODE=' || SQLCODE || ' / SQLERRM=' || SQLERRM || ' / BACKTRACE=' ||
                                DBMS_UTILITY.FORMAT_ERROR_BACKTRACE || ' / PARAMS=' || V_IN_PARA_DATA);
END;

PROCEDURE         "PR_SCM_MST_EXCHANGE_RATE_UI" (
    P_BATCH_YN      IN  VARCHAR2 DEFAULT 'N',
    O_RESULT_CURSOR OUT SYS_REFCURSOR
) AS
    V_ERR        VARCHAR2(200 CHAR);
    V_TARGET_CNT NUMBER;
BEGIN
    --[E20260915-BPSIFNODATA] 반영 대상 0건 안내 (사용자 지시 2026-09-15).
    --  공유 배치 PR_SCM_MST_EXCHANGE_RATE 는 대상이 없어도 오류 없이 끝나 이 래퍼가 항상 success 를 돌려줬고,
    --  화면은 "정상 반영" 토스트 후 값이 그대로여서 반영된 것으로 오인됐다(사내 XIF 0행 실측).
    --  → 배치 CUR_E 와 **동일 조건**으로 대상 건수를 먼저 세고, 0건이면 배치를 호출하지 않고 안내를 돌려준다.
    --  CODE <> '0' 이면 FE(ExchangeRateModal handleBpsIf)가 RESULT_MSG 를 Alert 로 표시한다 — FE 무변경.
    --  공유 배치 본문은 무수정(야간 배치 P_BATCH_YN='Y' 경로 영향 없음).
    IF P_BATCH_YN = 'Y' THEN
        SELECT COUNT(*)
          INTO V_TARGET_CNT
          FROM SCM_MGR.XIF_GSC_MOVE_EXCHANGE_RATE_SN E
         WHERE NVL(E.TRANSF_FLAG, 'N') = 'N'
           AND E.SCENARIO_TYPE_CD IN ('ML', 'RF');
    ELSE
        SELECT COUNT(*)
          INTO V_TARGET_CNT
          FROM SCM_MGR.XIF_GSC_MOVE_EXCHANGE_RATE_SN E
         WHERE E.TRANSF_DATE = (SELECT MAX(A.TRANSF_DATE)
                                  FROM SCM_MGR.XIF_GSC_MOVE_EXCHANGE_RATE_SN A
                                 WHERE A.SCENARIO_TYPE_CD IN ('ML', 'RF'))
           AND E.SCENARIO_TYPE_CD IN ('ML', 'RF');
    END IF;

    IF V_TARGET_CNT = 0 THEN
        OPEN O_RESULT_CURSOR FOR
            SELECT '1' AS CODE, '반영할 환율 정보가 없습니다' AS RESULT_MSG, CAST(NULL AS VARCHAR2(200 CHAR)) AS EVENT FROM DUAL;
        RETURN;
    END IF;

    SCM_MGR.PR_SCM_MST_EXCHANGE_RATE(P_BATCH_YN);
    OPEN O_RESULT_CURSOR FOR
        SELECT '0' AS CODE, 'success' AS RESULT_MSG, CAST(NULL AS VARCHAR2(200 CHAR)) AS EVENT FROM DUAL;
EXCEPTION
    WHEN OTHERS THEN
        V_ERR := SUBSTR(SQLERRM, 1, 200);
        ROLLBACK;
        OPEN O_RESULT_CURSOR FOR
            SELECT '9' AS CODE, 'fail' AS RESULT_MSG, V_ERR AS EVENT FROM DUAL;
END PR_SCM_MST_EXCHANGE_RATE_UI;

