PROCEDURE PR_SCM_MST_PLAN
(
    P_PLAN_CYCLE  VARCHAR2 DEFAULT 'WEEKLY'
  , P_PLAN_NAME   VARCHAR2 DEFAULT ''
)
/*
 * Program ID   : PR_SCM_MST_PLAN
 * Description  : PLAN ID Create
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2017.11.21   Kim SungGi     Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 * 2020.10.15   KIM BOK KI     p_plan_cycle = 'DAILY' 의 실행 일자 처리 GETDATE() - 1 => GETDATE() 로 변경
 * 2023.03.22   KSG            PJ20230691  SCM 역량 강화 위한 SCP 개선과제 이행 : '사업계획 Plan End Date' 지정
 * 2026.07.31   ZIONEX         [PJ202650304] NextSCM Migration
 */
IS
    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME      VARCHAR2(150 CHAR) := 'PR_SCM_MST_PLAN';
    V_LOG_TYPE          VARCHAR2(30 CHAR);              /* START/END/ERROR/... */
    N_LOG_COUNT         PLS_INTEGER := 0;
    V_LOG_MESSAGE       VARCHAR2(1000 CHAR);
    V_DESCRIPTION       VARCHAR2(500 CHAR);
    D_EVENT_DATE        DATE;

    N_PRE_PLAN_ID       PLS_INTEGER := 0;
    N_CUR_PLAN_ID       PLS_INTEGER := 0;
    N_PRE_WEEK_PLAN_ID  PLS_INTEGER := 0;
    N_CUR_WEEK_PLAN_ID  PLS_INTEGER := 0;
    V_DIVISION_ID       VARCHAR2(30 CHAR);
    V_CUR_MONDAY        VARCHAR2(8 CHAR) := TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7, 'YYYYMMDD'); /* 당주 월요일 YYYYMMDD */
    D_PLAN_NAME         DATE;


    N_ROWCOUNT          PLS_INTEGER := 0;
BEGIN


    /* 시작 LOG */
    V_LOG_TYPE := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    /* MSSQL 문자열 + 는 피연산자가 NULL 이면 전체가 NULL 이다. P_PLAN_CYCLE 은 호출부가 NULL 을 */
    V_DESCRIPTION := CASE
                          WHEN P_PLAN_CYCLE IS NULL THEN NULL
                          ELSE '[PR_SCM_MST_PLAN]' || ':' || P_PLAN_CYCLE
                     END;
    D_EVENT_DATE := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);


    BEGIN

        /* --------------------------------------------------------- */
        /* 실행 Logic START -- */
        /* --------------------------------------------------------- */

        /* --------------------------------------------------------- */
        /* WEEKLY Plan ID 생성 */
        /* --------------------------------------------------------- */
        IF P_PLAN_CYCLE = 'WEEKLY' THEN
            /* 실행 일자 처리 */
            /* WEEKLY : NULL 이거나 미래 일자이면 오늘 일자로 처리 */
            IF P_PLAN_NAME IS NULL THEN
                D_PLAN_NAME := SYSDATE;
            ELSIF P_PLAN_NAME > TO_CHAR(SYSDATE, 'YYYYMMDD') THEN
                D_PLAN_NAME := SYSDATE;
            ELSE
                D_PLAN_NAME := TO_DATE(P_PLAN_NAME, 'YYYYMMDD');
            END IF;

            /* 전주 Plan ID 찾기 */
            N_PRE_PLAN_ID := 0;


            FOR R_PRE IN (
                SELECT /* PR_SCM_MST_PLAN */
                       TO_NUMBER(A.PLAN_ID) AS PLAN_ID
                  FROM ( SELECT P.PLAN_ID
                              , ROW_NUMBER() OVER (ORDER BY P.PLAN_ID DESC) AS "ROWNUM"
                           FROM SCM_MST_PLAN P
                          WHERE P.PLAN_NAME  = TO_CHAR(FN_NEXT_DAY(D_PLAN_NAME, 'MON') - 7 * 2, 'YYYYMMDD') /* 지난 주 월요일 'YYYYMMDD' */
                            AND P.PLAN_CYCLE = P_PLAN_CYCLE ) A
                 WHERE A."ROWNUM" = 1 ) LOOP
                N_PRE_PLAN_ID := R_PRE.PLAN_ID;
            END LOOP;

            /* --------------------------------------------------------- */
            /* Division별 Weekly Plan ID 생성 */
            /* --------------------------------------------------------- */
            V_DIVISION_ID := '0';

            /*               FETCH NEXT FROM div_w_cur INTO @v_division_id; -- 첫 열 Fetch
               WHILE @@FETCH_STATUS = 0 -- 정상 Fetch인 경우
               FETCH NEXT FROM div_w_cur INTO @v_division_id; -- 다음 열 Fetch */
            FOR R_DIV IN (
                SELECT DISTINCT DIVISION_ID
                  FROM SCM_MST_DIVISION
                 ORDER BY DIVISION_ID ) LOOP
                V_DIVISION_ID := R_DIV.DIVISION_ID;

                /* 당주 Plan ID 찾기 */
                N_CUR_PLAN_ID := 0;
                N_ROWCOUNT := 0;

                FOR R_CUR IN (
                    SELECT /* PR_SCM_MST_PLAN */
                           TO_NUMBER(P.PLAN_ID) AS PLAN_ID
                      FROM SCM_MST_PLAN P
                     WHERE P.DIVISION_ID = V_DIVISION_ID
                       AND P.PLAN_CYCLE  = P_PLAN_CYCLE
                       AND P.PLAN_ID     = TRIM(TO_CHAR(N_PRE_PLAN_ID + 1)) ) LOOP
                    N_CUR_PLAN_ID := R_CUR.PLAN_ID;
                    N_ROWCOUNT := N_ROWCOUNT + 1;
                END LOOP;

                IF N_ROWCOUNT = 0 THEN
                    N_CUR_PLAN_ID := 0;
                END IF;

                /* --------------------------------------------------------- */
                /* 당주 Plan ID가 없는 경우만 생성 */
                /* 신규 Division 추가 시 전주 Plan ID 미리 생성 할 것 */
                /* --------------------------------------------------------- */
                IF N_CUR_PLAN_ID = 0 THEN
                    INSERT
                      INTO SCM_MST_PLAN
                         ( DIVISION_ID
                         , PLAN_CYCLE
                         , PLAN_ID
                         , PLAN_NAME
                         , HORIZON_START_DATE
                         , HORIZON_END_DATE
                           /* 20230322 PJ20230691 '사업계획 Plan End Date' 지정 */
                         , ATTRIBUTE1
                         , CREATION_DATE
                         , CREATED_BY
                         , LAST_UPDATE_DATE
                         , LAST_UPDATED_BY )
                    SELECT /* PR_SCM_MST_PLAN */
                           DIVISION_ID
                         , P_PLAN_CYCLE
                         , TRIM(TO_CHAR(TO_NUMBER(PLAN_ID) + 1))
                         , TO_CHAR(TO_DATE(PLAN_NAME, 'YYYYMMDD') + 7, 'YYYYMMDD')
                         , TO_CHAR(TO_DATE(HORIZON_START_DATE, 'YYYYMMDD') + 7, 'YYYYMMDD')
                         , TO_CHAR(TO_DATE(HORIZON_END_DATE, 'YYYYMMDD') + 7, 'YYYYMMDD')
                           /* 20230322 PJ20230691 '사업계획 Plan End Date' 지정 */
                         , TO_CHAR(TO_DATE(ATTRIBUTE1, 'YYYYMMDD') + 7, 'YYYYMMDD')
                         , SYSDATE CREATION_DATE, 'scm_batch' CREATED_BY
                         , SYSDATE LAST_UPDATE_DATE, 'scm_batch' LAST_UPDATED_BY
                      FROM SCM_MST_PLAN T
                     WHERE T.DIVISION_ID = V_DIVISION_ID
                       AND T.PLAN_CYCLE  = P_PLAN_CYCLE
                       AND T.PLAN_ID     = TRIM(TO_CHAR(N_PRE_PLAN_ID));
                   /* COMMIT WORK; */

                    /* --------------------------------------------------------- */
                    /* Insert LOG */
                    /* --------------------------------------------------------- */
                    V_LOG_TYPE := 'APPEND';
                    V_LOG_MESSAGE := 'INSERT INTO scm_mst_plan';
                    /*                       P_PLAN_CYCLE='WEEKLY' 분기 안이고, V_DIVISION_ID 는 NOT NULL 컬럼에서 오며,
                       D_PLAN_NAME 은 위 IF/ELSIF/ELSE 세 갈래에서 모두 대입된다. */
                    V_DESCRIPTION := P_PLAN_CYCLE || ':' || V_DIVISION_ID || ':' || TO_CHAR(D_PLAN_NAME, 'YYYYMMDD');
                    D_EVENT_DATE := SYSDATE;
                    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
                    /* --------------------------------------------------------- */

                END IF; /* IF n_cur_plan_id = 0 THEN */

            END LOOP; /* CURSOR FETCH */

        /* --------------------------------------------------------- */
        /* DAILY Plan ID 생성 */
        /* --------------------------------------------------------- */
        ELSIF P_PLAN_CYCLE = 'DAILY' THEN

            /* 실행 일자 처리 */
            /* DAILY : NULL 이거나 오늘 이후 일자이면 어제 일자로 처리 */
            /*IF (ISNULL(@p_plan_name, '') = '') */
            /*  SET @d_plan_name = DATEADD(DD, -1, GETDATE()) */
            /*ELSE IF @p_plan_name >= CONVERT(CHAR(8), GETDATE(), 112) */
            /*  SET @d_plan_name = DATEADD(DD, -1, GETDATE()) */
            /*ELSE */
            /*  SET @d_plan_name = DATEADD(DD, -1, CONVERT(DATETIME, @p_plan_name)) */

            /* DAILY : NULL 이거나 오늘 이후 일자이면 오늘 일자로 처리 */
            /*                ,CONVERT(CHAR(8), DATEADD(DD, 7, CONVERT (DATE, horizon_end_date)), 112) */
            IF P_PLAN_NAME IS NULL THEN
                D_PLAN_NAME := SYSDATE;
            ELSIF P_PLAN_NAME > TO_CHAR(SYSDATE, 'YYYYMMDD') THEN
                D_PLAN_NAME := SYSDATE;
            ELSE
                D_PLAN_NAME := TO_DATE(P_PLAN_NAME, 'YYYYMMDD');
            END IF;

            /* 전주 WEEKLY Plan ID 찾기 */
            N_PRE_WEEK_PLAN_ID := 0;

            FOR R_PREW IN (
                SELECT /* PR_SCM_MST_PLAN */
                       TO_NUMBER(A.PLAN_ID) AS PLAN_ID
                  FROM ( SELECT P.PLAN_ID
                              , ROW_NUMBER() OVER (ORDER BY P.PLAN_ID) AS "ROWNUM"
                           FROM SCM_MST_PLAN P
                          WHERE P.PLAN_NAME  = TO_CHAR(FN_NEXT_DAY(D_PLAN_NAME, 'MON') - 7 * 2, 'YYYYMMDD') /* 지난 주 월요일 'YYYYMMDD' */
                            AND P.PLAN_CYCLE = 'WEEKLY' ) A
                 WHERE A."ROWNUM" = 1 ) LOOP
                N_PRE_WEEK_PLAN_ID := R_PREW.PLAN_ID;
            END LOOP;

            /* 당주 WEEKLY Plan ID 찾기 */
            N_CUR_WEEK_PLAN_ID := N_PRE_WEEK_PLAN_ID + 1;

            /* --------------------------------------------------------- */
            /* Division별 Daily Plan ID 생성 */
            /* --------------------------------------------------------- */
            V_DIVISION_ID := '0';

            /*               FETCH NEXT FROM div_d_cur INTO @v_division_id; -- 첫 열 Fetch
               WHILE @@FETCH_STATUS = 0 -- 정상 Fetch인 경우
               FETCH NEXT FROM div_d_cur INTO @v_division_id; -- 다음 열 Fetch */
            FOR R_DIV IN (
                SELECT DISTINCT DIVISION_ID
                  FROM SCM_MST_DIVISION
                 ORDER BY DIVISION_ID ) LOOP
                V_DIVISION_ID := R_DIV.DIVISION_ID;

                /* --------------------------------------------------------- */
                /* 신규 Division 추가 시 전주 Plan ID 미리 생성 할 것 */
                /* 1. 월요일 : 전주 월요일 정보 사용하여 생성 */
                /* --------------------------------------------------------- */
                IF V_CUR_MONDAY = TO_CHAR(D_PLAN_NAME, 'YYYYMMDD') THEN

                    /* 전주 DAILY 월요일 Plan ID 찾기 */
                    N_PRE_PLAN_ID := 0;

                    FOR R_PRE IN (
                        SELECT /* PR_SCM_MST_PLAN */
                               TO_NUMBER(A.PLAN_ID) AS PLAN_ID
                          FROM ( SELECT P.PLAN_ID
                                      , ROW_NUMBER() OVER (ORDER BY P.PLAN_ID) AS "ROWNUM"
                                   FROM SCM_MST_PLAN P
                                  WHERE P.PLAN_NAME  = TO_CHAR(FN_NEXT_DAY(D_PLAN_NAME, 'MON') - 7 * 2, 'YYYYMMDD') /* 지난 주 월요일 'YYYYMMDD' */
                                    AND P.PLAN_CYCLE = P_PLAN_CYCLE ) A
                         WHERE A."ROWNUM" = 1 ) LOOP
                        N_PRE_PLAN_ID := R_PRE.PLAN_ID;
                    END LOOP;

                    /* 당일 Plan ID 찾기 */
                    N_CUR_PLAN_ID := 0;
                    N_ROWCOUNT := 0;

                    FOR R_CUR IN (
                        SELECT /* PR_SCM_MST_PLAN */
                               TO_NUMBER(P.PLAN_ID) AS PLAN_ID
                          FROM SCM_MST_PLAN P
                         WHERE P.DIVISION_ID = V_DIVISION_ID
                           AND P.PLAN_CYCLE  = P_PLAN_CYCLE
                           AND P.PLAN_ID     = TRIM(TO_CHAR(N_CUR_WEEK_PLAN_ID)) || '01' ) LOOP /* 당주 월요일 Plan ID */
                        N_CUR_PLAN_ID := R_CUR.PLAN_ID;
                        N_ROWCOUNT := N_ROWCOUNT + 1;
                    END LOOP;

                    IF N_ROWCOUNT = 0 THEN
                        N_CUR_PLAN_ID := 0;
                    END IF;

                    /* --------------------------------------------------------- */
                    /* 당일Plan ID가 없는 경우만 생성 */
                    /* 전주 월요일 정보 사용하여 생성 */
                    /* --------------------------------------------------------- */
                    IF N_CUR_PLAN_ID = 0 THEN
                        INSERT
                          INTO SCM_MST_PLAN
                             ( DIVISION_ID
                             , PLAN_CYCLE
                             , PLAN_ID
                             , PLAN_NAME
                             , HORIZON_START_DATE
                             , HORIZON_END_DATE
                             , CREATION_DATE
                             , CREATED_BY
                             , LAST_UPDATE_DATE
                             , LAST_UPDATED_BY )
                        SELECT /* PR_SCM_MST_PLAN */
                               DIVISION_ID
                             , P_PLAN_CYCLE
                             , TRIM(TO_CHAR(N_CUR_WEEK_PLAN_ID)) || '01'
                             , TO_CHAR(TO_DATE(PLAN_NAME, 'YYYYMMDD') + 7, 'YYYYMMDD')
                             , TO_CHAR(TO_DATE(HORIZON_START_DATE, 'YYYYMMDD') + 7, 'YYYYMMDD')
                             , TO_CHAR(TO_DATE(HORIZON_END_DATE, 'YYYYMMDD') + 7, 'YYYYMMDD')
                             , SYSDATE CREATION_DATE, 'scm_batch' CREATED_BY
                             , SYSDATE LAST_UPDATE_DATE, 'scm_batch' LAST_UPDATED_BY
                          FROM SCM_MST_PLAN T
                         WHERE T.DIVISION_ID = V_DIVISION_ID
                           AND T.PLAN_CYCLE  = P_PLAN_CYCLE
                           AND T.PLAN_ID     = TRIM(TO_CHAR(N_PRE_PLAN_ID));
                      /*  COMMIT WORK; */

                        /* --------------------------------------------------------- */
                        /* Insert LOG */
                        /* --------------------------------------------------------- */
                        V_LOG_TYPE := 'APPEND';
                        V_LOG_MESSAGE := 'INSERT INTO SCM_MST_PLAN : MON';
                        V_DESCRIPTION := P_PLAN_CYCLE || ':' || V_DIVISION_ID || ':' || TO_CHAR(D_PLAN_NAME, 'YYYYMMDD');
                        D_EVENT_DATE := SYSDATE;
                        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
                        /* --------------------------------------------------------- */

                    END IF; /* IF n_cur_plan_id = 0 */

                /* --------------------------------------------------------- */
                /* 2. 월요일 외: 전일 정보 사용하여 생성 */
                /* --------------------------------------------------------- */
                ELSE

                    /* 전일 Plan ID 찾기 */
                    N_PRE_PLAN_ID := 0;

                    FOR R_PRE IN (
                        SELECT /* PR_SCM_MST_PLAN */
                               TO_NUMBER(A.PLAN_ID) AS PLAN_ID
                          FROM ( SELECT P.PLAN_ID
                                      , ROW_NUMBER() OVER (ORDER BY P.PLAN_ID DESC) AS "ROWNUM"
                                   FROM SCM_MST_PLAN P
                                  WHERE P.PLAN_NAME  = TO_CHAR(D_PLAN_NAME - 1, 'YYYYMMDD') /* 어제일자 'YYYYMMDD' */
                                    AND P.PLAN_CYCLE = P_PLAN_CYCLE ) A
                         WHERE A."ROWNUM" = 1 ) LOOP
                        N_PRE_PLAN_ID := R_PRE.PLAN_ID;
                    END LOOP;

                    /* 당일 Plan ID 찾기 */
                    N_CUR_PLAN_ID := 0;
                    N_ROWCOUNT := 0;

                    FOR R_CUR IN (
                        SELECT /* PR_SCM_MST_PLAN */
                               TO_NUMBER(P.PLAN_ID) AS PLAN_ID
                          FROM SCM_MST_PLAN P
                         WHERE P.DIVISION_ID = V_DIVISION_ID
                           AND P.PLAN_CYCLE  = P_PLAN_CYCLE
                           AND P.PLAN_ID     = TRIM(TO_CHAR(N_PRE_PLAN_ID + 1)) ) LOOP
                        N_CUR_PLAN_ID := R_CUR.PLAN_ID;
                        N_ROWCOUNT := N_ROWCOUNT + 1;
                    END LOOP;

                    IF N_ROWCOUNT = 0 THEN
                        N_CUR_PLAN_ID := 0;
                    END IF;

                    /* --------------------------------------------------------- */
                    /* 당일Plan ID가 없는 경우만 생성 */
                    /* 전일 정보 사용하여 생성 */
                    /* --------------------------------------------------------- */
                    IF N_CUR_PLAN_ID = 0 THEN
                        INSERT
                          INTO SCM_MST_PLAN
                             ( DIVISION_ID
                             , PLAN_CYCLE
                             , PLAN_ID
                             , PLAN_NAME
                             , HORIZON_START_DATE
                             , HORIZON_END_DATE
                             , CREATION_DATE
                             , CREATED_BY
                             , LAST_UPDATE_DATE
                             , LAST_UPDATED_BY )
                        SELECT /* PR_SCM_MST_PLAN */
                               DIVISION_ID
                             , P_PLAN_CYCLE
                             , TRIM(TO_CHAR(TO_NUMBER(T.PLAN_ID) + 1))
                             , TO_CHAR(TO_DATE(PLAN_NAME, 'YYYYMMDD') + 1, 'YYYYMMDD')
                             , TO_CHAR(TO_DATE(HORIZON_START_DATE, 'YYYYMMDD') + 1, 'YYYYMMDD')
                             , TO_CHAR(TO_DATE(HORIZON_END_DATE, 'YYYYMMDD') + 1, 'YYYYMMDD') /* END Date도 하루씩 증가 */
                               /*  ,CONVERT(CHAR(8), DATEADD(DD, 0, CONVERT (DATE, horizon_end_date)), 112) -- END Date는 동일 주차일 경우 그대로 유지 */
                             , SYSDATE CREATION_DATE, 'scm_batch' CREATED_BY
                             , SYSDATE LAST_UPDATE_DATE, 'scm_batch' LAST_UPDATED_BY
                          FROM SCM_MST_PLAN T
                         WHERE T.DIVISION_ID = V_DIVISION_ID
                           AND T.PLAN_CYCLE  = P_PLAN_CYCLE
                           AND T.PLAN_ID     = TRIM(TO_CHAR(N_PRE_PLAN_ID));
                     /*   COMMIT WORK; */

                        /* --------------------------------------------------------- */
                        /* Insert LOG */
                        /* --------------------------------------------------------- */
                        V_LOG_TYPE := 'APPEND';
                        V_LOG_MESSAGE := 'INSERT INTO SCM_MST_PLAN : NON MON';
                        V_DESCRIPTION := P_PLAN_CYCLE || ':' || V_DIVISION_ID || ':' || TO_CHAR(D_PLAN_NAME, 'YYYYMMDD');
                        D_EVENT_DATE := SYSDATE;
                        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
                        /* --------------------------------------------------------- */

                    END IF; /* IF n_cur_plan_id = 0 */

                END IF; /* ELSE : MONDAY */

            END LOOP; /* CURSOR FETCH */

        END IF; /* ELSIF p_plan_cycle = 'DAILY' */

        /* --------------------------------------------------------- */
        /* 실행 Logic END -- */
        /* --------------------------------------------------------- */

        /* TXN LOG */
        V_LOG_TYPE := 'TXN';

        N_LOG_COUNT := 1;
        V_LOG_MESSAGE := 'SCM_MST_PLAN';
        /* D_PLAN_NAME 은 p_plan_cycle 이 WEEKLY/DAILY 어느 쪽도 아니면 미대입(NULL)이라 */
        V_DESCRIPTION := CASE
                              WHEN P_PLAN_CYCLE IS NULL OR D_PLAN_NAME IS NULL THEN NULL
                              ELSE 'Process Complete.' || ':' || P_PLAN_CYCLE || ':' || TO_CHAR(D_PLAN_NAME, 'YYYYMMDD')
                         END;
        D_EVENT_DATE := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        IF DBMS_TRANSACTION.LOCAL_TRANSACTION_ID IS NOT NULL THEN
            COMMIT WORK;
        END IF;


    EXCEPTION
        WHEN OTHERS THEN
            /* ROLLBACK */
            /* ERROR LOG */

            V_LOG_TYPE := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := SUBSTR('ERROR LINE ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 500);
            D_EVENT_DATE := SYSDATE;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    END;

    /* 종료 LOG */
    V_LOG_TYPE := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := CASE
                          WHEN P_PLAN_CYCLE IS NULL THEN NULL
                          ELSE '[PR_SCM_MST_PLAN]' || ':' || P_PLAN_CYCLE
                     END;
    D_EVENT_DATE := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

END PR_SCM_MST_PLAN;

PROCEDURE PR_SCM_MST_PROJECTBOM
/*
 * Program ID   : PR_SCM_MST_PROJECTBOM
 * Description  : MDM 수신정보 적재처리 Procedure
 * PARAMETER    : N/A
 * DESCRIPTION  : BPMS으로부터 수신된 정보(자재/Project/ProjectBOM)를 SCM_MST의 관련 테이블에 적재처리 함
 *                지정한 간격마다 자동으로 실행 됨
 * I/F Table    : [dbo].[XIF_BPMS_PROJECTBOM_AUTO_R_SN],[dbo].[XIF_BPMS_PROJECTBOM_ESS_R_SN]
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2021.03.17	P.C.I		   [C20210312-000195] 'BPMS -> DMS -> GSCM' I/F를 'BPMS -> GSCM'으로 변경
 * 2021.06.08	P.C.I		   [C20210312-000399] BPMS -> GSCM I/F 시 VALID 'N'은 Sales Site Project Model 적용
 * 2021.10.20	hwi1993			[PJ20209643] 성능개선] -  COLLATE KOREAN_WANSUNG_CI_AS 제거
 * 2024.04.24	JSSBAE		   [E20240424-000960]_BPMS - SCM IF 시 SSPM의 Inactive 처리는 Site Type = "Sales"인 대상으로 한정되어 RTF 생성에 영향이 없도록 기능변경요청(05_03)
 * 2026.07.06   ZIONEX         [PJ202650304] NextSCM Migration
 */
IS
    V_IF_UID          VARCHAR2(40 CHAR);
    V_MAT_CD          VARCHAR2(100 CHAR);  /* 자재코드 */
    V_PROJECT_CD      VARCHAR2(20 CHAR);   /* PJT Code */
    V_IF_TOTAL_CNT    NUMBER(16, 0);       /* IF총건수 */
    V_IF_SEQ_BY_PJT   NUMBER(16, 0);       /* IF순번(프로젝트별) */
    V_RECEIVE_CNT     NUMBER(16, 0);       /* 수신적재처리건수 */
    V_TXN_FLAG        VARCHAR2(10 CHAR);   /* BPMS 개편으로 인한 TRANSACTION 플래그 */

    /* LOG 용 변수 설정 */
    V_BATCH_USER      VARCHAR2(150 CHAR) := 'scm_batch';
    V_PROGRAM_NAME    VARCHAR2(150 CHAR) := 'PR_SCM_MST_PROJECTBOM';
    V_LOG_TYPE        VARCHAR2(30 CHAR);
    N_LOG_COUNT       INTEGER := 0;
    V_LOG_MESSAGE     VARCHAR2(1000 CHAR);
    V_DESCRIPTION     VARCHAR2(500 CHAR);
    D_EVENT_DATE      DATE;
    V_ERRMSG          VARCHAR2(1000 CHAR);

    /* CURSOR 자동차 프로젝트BOM정보수신 */
    CURSOR CUR_PJTBOM_81 IS
        SELECT IF_UID, PROJECT_CD, MAT_CD, IF_TOTAL_CNT, IF_SEQ_BY_PJT, TXN_FLAG
        FROM   (SELECT MPBARI.IF_UID
                      , MPBARI.PROJECT_CD
                      , MPBARI.MAT_CD
                      , MPBARI.IF_TOTAL_CNT
                      , ROW_NUMBER() OVER(PARTITION BY MPBARI.PROJECT_CD, MPBARI.MAT_CD
                          ORDER BY RECEIVE_DATE ASC, CASE WHEN TXN_FLAG = 'D' THEN 99 ELSE 1 END DESC) AS IF_SEQ_BY_PJT
                      , MPBARI.TXN_FLAG
                FROM   XIF_BPMS_PROJECTBOM_AUTO_R_SN MPBARI
                WHERE  NVL(MPBARI.TRANSFER_FLAG, 'N') = 'N') X
        ORDER  BY PROJECT_CD, MAT_CD, IF_SEQ_BY_PJT;

    /* CURSOR ESS 프로젝트BOM정보수신 */
    CURSOR CUR_PJTBOM_82 IS
        SELECT MPBERI.IF_UID
              , MPBERI.PROJECT_CD
              , MPBERI.MAT_CD
              , MPBERI.IF_TOTAL_CNT
              , ROW_NUMBER() OVER(PARTITION BY MPBERI.PROJECT_CD, MPBERI.IF_UID
                   ORDER BY MPBERI.PROJECT_CD, MPBERI.IF_UID, MPBERI.MAT_CD) AS IF_SEQ_BY_PJT
              , MPBERI.TXN_FLAG
        FROM   XIF_BPMS_PROJECTBOM_ESS_R_SN MPBERI
        WHERE  NVL(MPBERI.TRANSFER_FLAG, 'N') = 'N'
        AND    MPBERI.IF_UID IN (SELECT X.IF_UID
                                 FROM   XIF_BPMS_PROJECTBOM_ESS_R_SN X
                                 WHERE  NVL(X.TRANSFER_FLAG, 'N') = 'N'
                                 GROUP  BY X.IF_UID, X.IF_TOTAL_CNT
                                 HAVING COUNT(*) = X.IF_TOTAL_CNT)
        ORDER  BY MPBERI.PROJECT_CD, MPBERI.IF_UID, MPBERI.MAT_CD;
BEGIN
    /* 시작 LOG */
    V_LOG_TYPE := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    /* [E20240424-000960] TEMP(#DM_MST_ITEM_SINGLE_V / #TEMP_PROJECTBOM)을 GTT로 이관. 세션 잔존행 초기화(단일 TX 원자성 위해 DELETE, TRUNCATE 미사용) */
    DELETE FROM GT_SMPR_DM_MST_ITEM_SINGLE_V;
    DELETE FROM GT_SMPR_PROJECTBOM;

    /* [E20240424-000960] DM_MST_ITEM_SINGLE_V에 문제가 있어서, VIEW 내용 TEMP(GTT)로 담아서 해당 부분으로 사용 */
    INSERT INTO GT_SMPR_DM_MST_ITEM_SINGLE_V
        SELECT T1.DIVISION_ID
              , T1.ITEM_ID
              , MAX(T1.ITEM_NAME)       AS ITEM_NAME        /* 해당 컬럼이 NULL인 경우가 잇으므로 하나로 통일 */
              , MAX(T1.ITEM_CLASS)      AS ITEM_CLASS        /* 해당 컬럼이 NULL인 경우가 잇으므로 하나로 통일 */
              , MAX(T1.ITEM_CLASS_NAME) AS ITEM_CLASS_NAME   /* 해당 컬럼이 NULL인 경우가 잇으므로 하나로 통일 */
              , MAX(T1.NICK_NAME)       AS NICK_NAME         /* 닉네임이 NULL인 경우가 있으므로 하나로 통일 */
              , CASE MIN(CASE WHEN T1.ITEM_TYPE = 'P' THEN 1   /* 타입이 사이트와 사업부, 법인에 따라 다양하게 존재 하므로 하나로 통일 */
                             WHEN T1.ITEM_TYPE = 'H' THEN 2   /* 또한 가장 완성된 상태의 자재 타입을 판매한다고 가정, 해당 자재타입을 사용함 */
                             WHEN T1.ITEM_TYPE = 'Q' THEN 3
                             ELSE 4 END)
                    WHEN 1 THEN 'P'
                    WHEN 2 THEN 'H'
                    WHEN 3 THEN 'Q'
                    ELSE 'R' END AS ITEM_TYPE
              , MAX(T1.MATERIAL_CLASS_NAME) AS MATERIAL_CLASS_NAME
              , MAX(T1.ITEM_UOM)            AS ITEM_UOM
              , MAX(T1.SPEC)                AS SPEC
              , MAX(T1.MDM_PROJECT_NAME)    AS MDM_PROJECT_NAME
              , TO_NUMBER(MAX(T1.MIN_CAPACITY) DEFAULT 0 ON CONVERSION ERROR) AS MIN_CAPACITY
              , MAX(T2.FORECAST_INFO_BIZ_TYPE)         AS FORECAST_INFO_BIZ_TYPE
              , MAX(T2.FORECAST_INFO_PRODUCT_GROUP)    AS FORECAST_INFO_PRODUCT_GROUP
              , MAX(T2.FORECAST_INFO_CELL_MODEL)       AS FORECAST_INFO_CELL_MODEL
              , MAX(T2.FORECAST_INFO_CELL_PACK_COUNT)  AS FORECAST_INFO_CELL_PACK_COUNT
              , MAX(T2.FORECAST_INFO_SPEC)             AS FORECAST_INFO_SPEC
              , MAX(T2.FORECAST_INFOR_VERSION)         AS FORECAST_INFOR_VERSION
              , MAX(T1.ACTIVE_FLAG)        AS ACTIVE_FLAG    /* 20180720 ADD 'Y'대상중 1건 추출 */
              , MAX(T2.CELL_TYPE)          AS CELL_TYPE      /* 20180911 ADD cell_type */
              , MAX(T1.ENERGE)            AS ENERGE          /* 20200116 khsong ADD ENERGE */
              , TO_NUMBER(MAX(T1.CELL_QUANTITY) DEFAULT 0 ON CONVERSION ERROR) AS CELL_QUANTITY /* 20200116 khsong ADD CELL_QUANTITY. 원천 VARCHAR2 -> GTT NUMBER(비수치=0) */
              , MAX(T1.SCP_EXTRA_SPEC)     AS SCP_EXTRA_SPEC /* [20210428 SJHAN / CSR ID:C20210323-000420] */
        FROM   SCM_MST_ITEM_SN T1
        INNER  JOIN (SELECT DIVISION_ID
                           , SUBSTR(ITEM_ID, 1, 12) AS ITEM_ID
                           , MAX(FORECAST_INFO_BIZ_TYPE)        AS FORECAST_INFO_BIZ_TYPE
                           , MAX(FORECAST_INFO_PRODUCT_GROUP)   AS FORECAST_INFO_PRODUCT_GROUP
                           , MAX(FORECAST_INFO_CELL_MODEL)      AS FORECAST_INFO_CELL_MODEL
                           , MAX(FORECAST_INFO_CELL_PACK_COUNT) AS FORECAST_INFO_CELL_PACK_COUNT
                           , MAX(FORECAST_INFO_SPEC)            AS FORECAST_INFO_SPEC
                           , MAX(FORECAST_INFOR_VERSION)        AS FORECAST_INFOR_VERSION
                           , MAX(CELL_TYPE)                     AS CELL_TYPE
                     FROM   SCM_MST_ITEM_SN T2
                     GROUP  BY DIVISION_ID, SUBSTR(ITEM_ID, 1, 12)) T2
        ON     T1.DIVISION_ID = T2.DIVISION_ID
        AND    SUBSTR(T1.ITEM_ID, 1, 12) = T2.ITEM_ID
        WHERE  1 = 1
        GROUP  BY T1.DIVISION_ID, T1.ITEM_ID;

    /* DBMS_OUTPUT.PUT_LINE('A--' ||TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3')); */

    /* ------------------------------------------------------------------ */
    /* Start  81 PROJECTBOM */
    /* ------------------------------------------------------------------ */
    V_RECEIVE_CNT := 0;
    OPEN CUR_PJTBOM_81;
    FETCH CUR_PJTBOM_81 INTO V_IF_UID, V_PROJECT_CD, V_MAT_CD, V_IF_TOTAL_CNT, V_IF_SEQ_BY_PJT, V_TXN_FLAG;
    WHILE CUR_PJTBOM_81%FOUND LOOP
        /* DBMS_OUTPUT.PUT_LINE('B--' ||TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3')); */

        MERGE INTO SCM_MST_PROJECTBOM SMP
        USING (SELECT DIVISION_ID  AS DIVISION_ID
                      , V_PROJECT_CD  AS PROJECT_CD
                      , V_MAT_CD      AS MAT_CD
                      , V_BATCH_USER  AS CREATED_BY
                      , SYSDATE       AS CREATION_DATE
                      , V_BATCH_USER  AS LAST_UPDATED_BY
                      , SYSDATE       AS LAST_UPDATE_DATE
                FROM   SCM_MST_DIVISION
                WHERE  ATTRIBUTE3 = '81' ) XXX
        ON (SMP.DIVISION_ID = XXX.DIVISION_ID AND SMP.PROJECT_CODE = XXX.PROJECT_CD AND SMP.ITEM_ID = XXX.MAT_CD)
        WHEN MATCHED THEN
            UPDATE SET SMP.VALID_YN         = CASE WHEN V_TXN_FLAG = 'D' THEN 'N' ELSE 'Y' END
                      , SMP.LAST_UPDATED_BY  = XXX.LAST_UPDATED_BY
                      , SMP.LAST_UPDATE_DATE = XXX.LAST_UPDATE_DATE
        WHEN NOT MATCHED THEN
            INSERT (DIVISION_ID, PROJECT_CODE, ITEM_ID, REP_YN, VALID_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
            VALUES (XXX.DIVISION_ID, XXX.PROJECT_CD, XXX.MAT_CD, 'N', 'Y', XXX.CREATED_BY, XXX.CREATION_DATE, XXX.LAST_UPDATED_BY, XXX.LAST_UPDATE_DATE);

        UPDATE XIF_BPMS_PROJECTBOM_AUTO_R_SN
        SET    TRANSFER_FLAG = 'Y', TRANSFER_DATE = SYSDATE, LAST_UPDATED_BY = V_BATCH_USER, LAST_UPDATE_DATE = SYSDATE
        WHERE  IF_UID = V_IF_UID
        AND    PROJECT_CD = V_PROJECT_CD
        AND    MAT_CD = V_MAT_CD;
        V_RECEIVE_CNT := V_RECEIVE_CNT + 1;

        FETCH CUR_PJTBOM_81 INTO V_IF_UID, V_PROJECT_CD, V_MAT_CD, V_IF_TOTAL_CNT, V_IF_SEQ_BY_PJT, V_TXN_FLAG;
    END LOOP;
    CLOSE CUR_PJTBOM_81;
    /* ------------------------------------------------------------------ */
    /* End  81 PROJECTBOM */
    /* ------------------------------------------------------------------ */
    /* DBMS_OUTPUT.PUT_LINE('C--' ||TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3')); */

    /* ------------------------------------------------------------------ */
    /* Start  82 PROJECTBOM */
    /* ------------------------------------------------------------------ */
    V_RECEIVE_CNT := 0;
    OPEN CUR_PJTBOM_82;
    FETCH CUR_PJTBOM_82 INTO V_IF_UID, V_PROJECT_CD, V_MAT_CD, V_IF_TOTAL_CNT, V_IF_SEQ_BY_PJT, V_TXN_FLAG;
    WHILE CUR_PJTBOM_82%FOUND LOOP
        /* DBMS_OUTPUT.PUT_LINE('D--' ||TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3')); */

        MERGE INTO SCM_MST_PROJECTBOM MPBM
        USING (SELECT '82'          AS DIVISION_ID
                      , V_PROJECT_CD  AS PROJECT_CD
                      , V_MAT_CD      AS MAT_CD
                      , V_BATCH_USER  AS CREATED_BY
                      , SYSDATE       AS CREATION_DATE
                      , V_BATCH_USER  AS LAST_UPDATED_BY
                      , SYSDATE       AS LAST_UPDATE_DATE
                FROM   DUAL) XXX
        ON (MPBM.DIVISION_ID = XXX.DIVISION_ID AND MPBM.PROJECT_CODE = XXX.PROJECT_CD AND MPBM.ITEM_ID = XXX.MAT_CD)
        WHEN MATCHED THEN
            UPDATE SET MPBM.VALID_YN         = CASE WHEN V_TXN_FLAG = 'D' THEN 'N' ELSE 'Y' END
                      , MPBM.LAST_UPDATED_BY  = XXX.LAST_UPDATED_BY
                      , MPBM.LAST_UPDATE_DATE = XXX.LAST_UPDATE_DATE
        WHEN NOT MATCHED THEN
            INSERT (DIVISION_ID, PROJECT_CODE, ITEM_ID, REP_YN, VALID_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
            VALUES (XXX.DIVISION_ID, XXX.PROJECT_CD, XXX.MAT_CD, 'N', 'Y', XXX.CREATED_BY, XXX.CREATION_DATE, XXX.LAST_UPDATED_BY, XXX.LAST_UPDATE_DATE);

        UPDATE XIF_BPMS_PROJECTBOM_ESS_R_SN
        SET    TRANSFER_FLAG = 'Y', TRANSFER_DATE = SYSDATE, LAST_UPDATED_BY = V_BATCH_USER, LAST_UPDATE_DATE = SYSDATE
        WHERE  IF_UID = V_IF_UID
        AND    PROJECT_CD = V_PROJECT_CD
        AND    MAT_CD = V_MAT_CD;
        V_RECEIVE_CNT := V_RECEIVE_CNT + 1;

        FETCH CUR_PJTBOM_82 INTO V_IF_UID, V_PROJECT_CD, V_MAT_CD, V_IF_TOTAL_CNT, V_IF_SEQ_BY_PJT, V_TXN_FLAG;
    END LOOP;
    CLOSE CUR_PJTBOM_82;
    /* ------------------------------------------------------------------ */
    /* End  82 PROJECTBOM */
    /* ------------------------------------------------------------------ */
    /* DBMS_OUTPUT.PUT_LINE('E--' ||TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3')); */

    /* ------------------------------------------------------------------ */
    /* Start  SCM Project 데이터 적용 */
    /* ------------------------------------------------------------------ */
    INSERT INTO GT_SMPR_PROJECTBOM
        SELECT B.DIVISION_ID
              , B.PROJECT_CODE
              , B.PROJECT_VER_SEQ
              , C.ITEM_ID
              , MAX(CASE WHEN VALID_YN = 'Y' THEN 'Y' ELSE 'N' END) AS VALID_YN
        FROM   SCM_MST_PROJECTBOM A, SCM_MST_PROJECT B, SCM_MST_ITEM_SN C
        WHERE  A.PROJECT_CODE = B.PROJECT_CODE
        AND    A.ITEM_ID <> '-'
        AND    A.ITEM_ID = C.ITEM_ID
        AND    (B.DIVISION_ID = '82' OR B.DIVISION_ID LIKE '81%')
        GROUP  BY B.DIVISION_ID, B.PROJECT_CODE, B.PROJECT_VER_SEQ, C.ITEM_ID;

    /* DBMS_OUTPUT.PUT_LINE('F--' ||TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3')); */

    /* scm_mst_project_item 에 존재하지 않는건 insert 함. */
    INSERT INTO SCM_MST_PROJECT_ITEM
        (DIVISION_ID, PROJECT_CODE, PROJECT_VER_SEQ, ITEM_ID, ITEM_TYPE, VALID_YN, CREATION_DATE, CREATED_BY, LAST_UPDATE_DATE, LAST_UPDATED_BY)
        SELECT A.DIVISION_ID
              , A.PROJECT_CODE
              , A.PROJECT_VER_SEQ
              , A.ITEM_ID
              , (SELECT V.ITEM_TYPE
                 FROM   GT_SMPR_DM_MST_ITEM_SINGLE_V V
                 WHERE  V.DIVISION_ID = A.DIVISION_ID
                 AND    V.ITEM_ID = A.ITEM_ID) AS ITEM_TYPE
              , A.VALID_YN
              , SYSDATE
              , 'SYSTEM_BATCH_BOM'
              , SYSDATE
              , 'SYSTEM_BATCH_BOM'
        FROM   GT_SMPR_PROJECTBOM A
        WHERE  (SELECT COUNT(1)
                 FROM   SCM_MST_PROJECT_ITEM X
                 WHERE  A.DIVISION_ID = X.DIVISION_ID
                 AND    A.ITEM_ID = X.ITEM_ID
                 AND    A.PROJECT_CODE = X.PROJECT_CODE) = 0;

    /* DBMS_OUTPUT.PUT_LINE('G--' ||TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3')); */

    /* VALID_YN이 변경된 것에 대해서 update 처리 (MSSQL UPDATE FROM + INNER JOIN 상관서브쿼리 -> UPDATE EXISTS, 값은 상관 MAX) */
    UPDATE SCM_MST_PROJECT_ITEM T1
    SET    (T1.VALID_YN, T1.LAST_UPDATE_DATE, T1.LAST_UPDATED_BY) =
           (SELECT MAX(A.VALID_YN), SYSDATE, 'SYSTEM_BATCH_BOM'
             FROM   GT_SMPR_PROJECTBOM A
             WHERE  A.DIVISION_ID = T1.DIVISION_ID AND A.PROJECT_CODE = T1.PROJECT_CODE AND A.ITEM_ID = T1.ITEM_ID
             AND    EXISTS (SELECT 1 FROM SCM_MST_PROJECT_ITEM X
                             WHERE A.DIVISION_ID = X.DIVISION_ID AND A.ITEM_ID = X.ITEM_ID AND A.PROJECT_CODE = X.PROJECT_CODE AND A.VALID_YN <> X.VALID_YN))
    WHERE  EXISTS (SELECT 1 FROM GT_SMPR_PROJECTBOM A
                    WHERE A.DIVISION_ID = T1.DIVISION_ID AND A.PROJECT_CODE = T1.PROJECT_CODE AND A.ITEM_ID = T1.ITEM_ID
                    AND   EXISTS (SELECT 1 FROM SCM_MST_PROJECT_ITEM X
                                   WHERE A.DIVISION_ID = X.DIVISION_ID AND A.ITEM_ID = X.ITEM_ID AND A.PROJECT_CODE = X.PROJECT_CODE AND A.VALID_YN <> X.VALID_YN));

    /* DBMS_OUTPUT.PUT_LINE('H--' ||TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3')); */

    /* SCM_MST_SITE_ITEM에 BPMS_EXIST 변경 (MSSQL UPDATE FROM + INNER JOIN 상관서브쿼리 -> UPDATE EXISTS, 값은 상관 MAX) */
    UPDATE SCM_MST_SITE_ITEM T1
    SET    (T1.BPMS_EXIST, T1.LAST_UPDATE_DATE, T1.LAST_UPDATED_BY) =
           (SELECT MAX(A.VALID_YN), SYSDATE, 'SYSTEM_BATCH_BOM'
             FROM   SCM_MST_PROJECT_ITEM A
             WHERE  A.DIVISION_ID = T1.DIVISION_ID AND A.PROJECT_CODE = T1.PROJECT_CODE AND A.ITEM_ID = T1.ITEM_ID
             AND    EXISTS (SELECT 1 FROM SCM_MST_SITE_ITEM X
                             WHERE A.DIVISION_ID = X.DIVISION_ID AND A.ITEM_ID = X.ITEM_ID AND A.PROJECT_CODE = X.PROJECT_CODE AND A.VALID_YN <> X.BPMS_EXIST))
    WHERE  EXISTS (SELECT 1 FROM SCM_MST_PROJECT_ITEM A
                    WHERE A.DIVISION_ID = T1.DIVISION_ID AND A.PROJECT_CODE = T1.PROJECT_CODE AND A.ITEM_ID = T1.ITEM_ID
                    AND   EXISTS (SELECT 1 FROM SCM_MST_SITE_ITEM X
                                   WHERE A.DIVISION_ID = X.DIVISION_ID AND A.ITEM_ID = X.ITEM_ID AND A.PROJECT_CODE = X.PROJECT_CODE AND A.VALID_YN <> X.BPMS_EXIST));

    /* DBMS_OUTPUT.PUT_LINE('I--' ||TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3')); */

    /* [C20210312-000399] BPMS -> GSCM I/F 시 VALID 'N'은 SCM_MST_SITE_ITEM에 VALID_YN 변경 */
    /* [E20240424-000960] Site Type='SALES' 대상으로 한정 (MSSQL UPDATE FROM + 2 INNER JOIN -> UPDATE EXISTS) */
    UPDATE SCM_MST_SITE_ITEM T1
    SET    T1.VALID_YN = 'N'   /* T2.VALID_YN: T2 필터가 A.VALID_YN='N'이므로 항상 'N' */
          , T1.LAST_UPDATE_DATE = SYSDATE
          , T1.LAST_UPDATED_BY  = 'SYSTEM_BATCH_BOM_VALID_N'
    WHERE  T1.VALID_YN = 'Y'
    AND    EXISTS (SELECT 1 FROM SCM_MST_SITE B
                    WHERE T1.DIVISION_ID = B.DIVISION_ID AND T1.SCM_SITE_ID = B.SCM_SITE_ID AND B.SITE_TYPE = 'SALES' )
    AND    EXISTS (SELECT 1 FROM SCM_MST_PROJECT_ITEM A
                    WHERE A.PROJECT_CODE = T1.PROJECT_CODE AND A.DIVISION_ID = T1.DIVISION_ID AND A.ITEM_ID = T1.ITEM_ID
                    AND   A.VALID_YN = 'N'
                    AND   A.LAST_UPDATED_BY = 'SYSTEM_BATCH_BOM' /* [C20210312-000399] BPMS 에서 변경 된 VALID 'N'만 적용 */
                    AND   A.LAST_UPDATE_DATE > SYSDATE - 0.01
                    AND   EXISTS (SELECT 1 FROM SCM_MST_SITE_ITEM X
                                   WHERE A.DIVISION_ID = X.DIVISION_ID AND A.ITEM_ID = X.ITEM_ID AND A.PROJECT_CODE = X.PROJECT_CODE AND A.VALID_YN <> X.VALID_YN));

    /* DBMS_OUTPUT.PUT_LINE('J--' ||TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3')); */
    /* ------------------------------------------------------------------ */
    /* End  SCM 데이터 적용 */
    /* ------------------------------------------------------------------ */
    /* [C20210312-000399] BPMS VALID 'N' Mail 전송 */
    /* NSCM 비활성(사용자 확정 2026-06-17): PR_DM_DNM_BPMS_MAIL_SEND; */
    /* 트랜잭션 종료 */
    COMMIT;

    /* 종료 LOG */
    V_LOG_TYPE := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        /* ERROR LOG (MSSQL CATCH: 로그만 기록, 재던짐 없음) */
        V_ERRMSG := SQLERRM;
        V_LOG_TYPE := 'ERROR';
        V_LOG_MESSAGE := SUBSTR(V_ERRMSG, 1, 1000);
        V_DESCRIPTION := SUBSTR('ERROR_LINE : ' ||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 500);
        D_EVENT_DATE := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
END PR_SCM_MST_PROJECTBOM;

PROCEDURE PR_SCM_MST_SITE_ITEM_FROM_ELEC_TACT_TIME
(
    P_DIVISION_ID   IN VARCHAR2
)
/*
 * Program ID   : PR_SCM_MST_SITE_ITEM_FROM_ELEC_TACT_TIME
 * Description  : CREATE SITE ITEM INFO. FROM ELECTRODE TACT TIME SITE
 *                기초 데이타 생성용으로 초기 setup을 위한 1회성으로 사용하기 위한 프로그램을 개발함.
 *                선행조건: SCP_MST_TACT_TIME에 TACT TIME이 생성되어 있을것.
 * OutTable     :
 * Execute      :
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2018.06.22   YYDOK         Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 * 2026.07.31   ZIONEX        [PJ202650304] NextSCM Migration
 */
IS

    /*       SET TRANSACTION ISOLATION LEVEL READ COMMITTED;   READ COMMITTED 는 Oracle 기본 격리수준이라 등가 */

    /* LOG 용 변수 설정 */
    V_BATCH_USER          VARCHAR2(150 CHAR) := '';
    V_PROGRAM_NAME        VARCHAR2(150 CHAR) := 'PR_SCM_MST_SITE_ITEM_FROM_ELEC_TACT_TIME';
    V_LOG_TYPE            VARCHAR2(30 CHAR);   /* START/END/ERROR/... */
    N_LOG_COUNT           NUMBER := 0;
    V_LOG_MESSAGE         VARCHAR2(1000 CHAR);
    V_DESCRIPTION         VARCHAR2(500 CHAR);
    V_TABLE_ID            VARCHAR2(150 CHAR) := 'SCM_MST_SITE_ITEM,SCM_MST_SITE_ITEM_PRIORITY';
    D_EVENT_DATE          DATE;

    X_PRIORITY_SEQ        NUMBER(19);
    X_DIVISION_ID         VARCHAR2(100 CHAR);
    X_PLANT_SITE_ID       VARCHAR2(100 CHAR);
    X_SALES_SITE_ID       VARCHAR2(100 CHAR);
    X_PROJECT_CODE        VARCHAR2(100 CHAR);
    X_ITEM_ID             VARCHAR2(100 CHAR);
    X_PRIORITY            NUMBER(10);
    X_FROM_YYYYMMDD       VARCHAR2(100 CHAR);
    X_TO_YYYYMMDD         VARCHAR2(100 CHAR);
    X_VALID_YN            VARCHAR2(100 CHAR);
    X_CREATED_BY          VARCHAR2(100 CHAR);
    X_CREATION_DATE       DATE;
    X_LAST_UPDATED_BY     VARCHAR2(100 CHAR);
    X_LAST_UPDATE_DATE    DATE;


    CURSOR CUR_SIP IS
    WITH SUB AS
    (
    SELECT DISTINCT
           DIVISION_ID
         , PLANT_SITE_ID
         , '-' AS SALES_SITE_ID
         , '-' AS PROJECT_CODE
         , ITEM_ID
         , FN_GET_BUCKET_YYYYMMDD(0) AS FROM_YYYYMMDD
         , '99991231' AS TO_YYYYMMDD
         , 'Y' AS VALID_YN
         , 'SCP_BATCH' AS CREATED_BY
         , SYSDATE AS CREATION_DATE
         , 'SCP_BATCH' AS LAST_UPDATED_BY
         , SYSDATE AS LAST_UPDATE_DATE
      FROM SCP_MST_TACT_TIME T
     WHERE DIVISION_ID = P_DIVISION_ID
       AND OPERATION_ID LIKE 'E2000%'
       AND SUBSTR(ITEM_ID, 1, 5) IN ('APCCA', 'APCAN', 'APCCS')
       AND NOT EXISTS (SELECT 1
                         FROM SCM_MST_SITE_ITEM_PRIORITY A
                        WHERE 1 = 1
                          AND A.DIVISION_ID   = T.DIVISION_ID
                          AND A.PLANT_SITE_ID = T.PLANT_SITE_ID
                          AND A.ITEM_ID       = T.ITEM_ID)
    )
    SELECT SEQ1_SCM_MST_SITE_ITEM_PRIORITY.NEXTVAL AS PRIORITY_SEQ
         , SUB.DIVISION_ID
         , SUB.PLANT_SITE_ID
         , SUB.SALES_SITE_ID
         , SUB.PROJECT_CODE
         , SUB.ITEM_ID
         /* ROW_NUMBER() OVER(PARTITION BY DIVISION_ID,ITEM_ID ORDER BY PLANT_SITE_ID) AS PRIORITY, */
         , SUB.FROM_YYYYMMDD
         , SUB.TO_YYYYMMDD
         , SUB.VALID_YN
         , SUB.CREATED_BY
         , SUB.CREATION_DATE
         , SUB.LAST_UPDATED_BY
         , SUB.LAST_UPDATE_DATE
      FROM SUB
     WHERE 1 = 1
       AND NOT EXISTS (SELECT 1
                         FROM SCM_MST_SITE_ITEM_PRIORITY A
                        WHERE 1 = 1
                          AND A.DIVISION_ID   = SUB.DIVISION_ID
                          AND A.PLANT_SITE_ID = SUB.PLANT_SITE_ID
                          AND A.ITEM_ID       = SUB.ITEM_ID);

BEGIN

    V_BATCH_USER := 'SCP';

    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := V_PROGRAM_NAME || ':' || ' SCM_MST_SITE_ITEM INSERT LOGIC';
    D_EVENT_DATE  := SYSDATE;
    PR_SCP_SYS_LOG_BATCH( P_PROGRAM_NAME  => V_PROGRAM_NAME
                        , P_LOG_TYPE      => V_LOG_TYPE
                        , P_LOG_COUNT     => N_LOG_COUNT
                        , P_LOG_MESSAGE   => V_LOG_MESSAGE
                        , P_DESCRIPTION   => V_DESCRIPTION
                        , P_EVENT_DATE    => D_EVENT_DATE
                        , P_USER_ID       => V_BATCH_USER
                        );


    BEGIN
      BEGIN

      /*  BEGIN TRANSACTION TXN_ELEC_SITE_ITEM; */

        /* ----------------------------------------------------------- */
        /* 1. SCM_MST_SITE_ITEM 기존 PROJECT CODE 데이타 삭제          */
        /*    SCM_MST_SITE_ITEM_PRIORITY 기존 PROJECT CODE 데이타 삭제 */
        /* ----------------------------------------------------------- */
/*    -- 혹시 실행할까봐 주석 처리함
        DELETE SCM_MST_SITE_ITEM
        WHERE 1=1
          AND DIVISION_ID    = @P_DIVISION_ID
          AND LEFT(ITEM_ID,5) IN ( 'APCCA','APCAN','APCCS')
          AND PROJECT_CODE   <> '-'
          ;

        DELETE SCM_MST_SITE_ITEM_PRIORITY
        WHERE 1=1
          AND DIVISION_ID    = @P_DIVISION_ID
          AND LEFT(ITEM_ID,5) IN ( 'APCCA','APCAN','APCCS')
          AND PROJECT_CODE   <> '-'
          ;
*/
        /* ----------------------------------------------------------- */
        /* 2. SCM_MST_SITE_ITEM_PRIORITY 데이타 생성                   */
        /*    SCM_MST_SITE_ITEM  데이타 생성                           */
        /* ----------------------------------------------------------- */

        OPEN CUR_SIP;
        FETCH CUR_SIP INTO X_PRIORITY_SEQ
                         , X_DIVISION_ID
                         , X_PLANT_SITE_ID
                         , X_SALES_SITE_ID
                         , X_PROJECT_CODE
                         , X_ITEM_ID
                         , X_FROM_YYYYMMDD
                         , X_TO_YYYYMMDD
                         , X_VALID_YN
                         , X_CREATED_BY
                         , X_CREATION_DATE
                         , X_LAST_UPDATED_BY
                         , X_LAST_UPDATE_DATE;


        WHILE CUR_SIP%FOUND LOOP

            SELECT COUNT(1) + 1
              INTO X_PRIORITY
              FROM SCM_MST_SITE_ITEM_PRIORITY
             WHERE DIVISION_ID = X_DIVISION_ID
               AND ITEM_ID     = X_ITEM_ID;

            INSERT
              INTO SCM_MST_SITE_ITEM_PRIORITY
                 ( PRIORITY_SEQ
                 , DIVISION_ID
                 , PLANT_SITE_ID
                 , SALES_SITE_ID
                 , PROJECT_CODE
                 , ITEM_ID
                 , PRIORITY
                 , FROM_YYYYMMDD
                 , TO_YYYYMMDD
                 , VALID_YN
                 , CREATED_BY
                 , CREATION_DATE
                 , LAST_UPDATED_BY
                 , LAST_UPDATE_DATE )
            VALUES ( X_PRIORITY_SEQ
                   , X_DIVISION_ID
                   , X_PLANT_SITE_ID
                   , X_SALES_SITE_ID
                   , X_PROJECT_CODE
                   , X_ITEM_ID
                   , X_PRIORITY
                   , X_FROM_YYYYMMDD
                   , X_TO_YYYYMMDD
                   , X_VALID_YN
                   , X_CREATED_BY
                   , X_CREATION_DATE
                   , X_LAST_UPDATED_BY
                   , X_LAST_UPDATE_DATE );

            FETCH CUR_SIP INTO X_PRIORITY_SEQ
                             , X_DIVISION_ID
                             , X_PLANT_SITE_ID
                             , X_SALES_SITE_ID
                             , X_PROJECT_CODE
                             , X_ITEM_ID
                             , X_FROM_YYYYMMDD
                             , X_TO_YYYYMMDD
                             , X_VALID_YN
                             , X_CREATED_BY
                             , X_CREATION_DATE
                             , X_LAST_UPDATED_BY
                             , X_LAST_UPDATE_DATE;
        END LOOP;
        CLOSE CUR_SIP;


        INSERT
          INTO SCM_MST_SITE_ITEM
             ( DIVISION_ID
             , PROJECT_CODE
             , SCM_SITE_ID
             , ITEM_ID
             , VALID_YN
             , BPMS_EXIST
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE )
        SELECT DISTINCT
               DIVISION_ID
             , '-' AS PROJECT_CODE
             , PLANT_SITE_ID AS SCM_SITE_ID
             , ITEM_ID
             , 'Y' AS VALID_YN
             , 'N' AS BPMS_EXIST
             , 'SCP_BATCH' AS CREATED_BY
             , SYSDATE AS CREATION_DATE
             , 'SCP_BATCH' AS LAST_UPDATED_BY
             , SYSDATE AS LAST_UPDATE_DATE
          FROM SCP_MST_TACT_TIME T
         WHERE DIVISION_ID = P_DIVISION_ID
           AND OPERATION_ID LIKE 'E2000%'
           AND NOT EXISTS (SELECT 1
                             FROM SCM_MST_SITE_ITEM A
                            WHERE 1 = 1
                              AND A.DIVISION_ID = T.DIVISION_ID
                              AND A.SCM_SITE_ID = T.PLANT_SITE_ID
                              AND A.ITEM_ID     = T.ITEM_ID);

        DBMS_OUTPUT.PUT_LINE('프로시저 종료');

        /* ----------------------------------------------------------- */
        /* 9. 종료 처리                                                */
        /* ----------------------------------------------------------- */

     /*   IF @@TRANCOUNT > 0     */
     /*     BEGIN                */
     /*       COMMIT WORK;       */
     /*     END;                 */

        /* ----------------------------------------------------------- */
        /* 실행 Logic END --                                           */
        /* ----------------------------------------------------------- */

        /* TXN LOG */
        V_LOG_TYPE    := 'TXN';
        N_LOG_COUNT   := SQL%ROWCOUNT;
        V_LOG_MESSAGE := 'INSERT INTO ' || V_TABLE_ID;
        V_DESCRIPTION := 'Process Complete...' || ':' || TO_CHAR(D_EVENT_DATE, 'YYYYMMDD');
        D_EVENT_DATE  := SYSDATE;

        PR_SCP_SYS_LOG_BATCH( P_PROGRAM_NAME  => V_PROGRAM_NAME
                            , P_LOG_TYPE      => V_LOG_TYPE
                            , P_LOG_COUNT     => N_LOG_COUNT
                            , P_LOG_MESSAGE   => V_LOG_MESSAGE
                            , P_DESCRIPTION   => V_DESCRIPTION
                            , P_EVENT_DATE    => D_EVENT_DATE
                            , P_USER_ID       => V_BATCH_USER
                            );

      END;


    EXCEPTION
      WHEN OTHERS THEN

    /*  IF @@TRANCOUNT > 0                              */
    /*    BEGIN                                         */
    /*      ROLLBACK TRANSACTION TXN_ELEC_SITE_ITEM;    */
    /*    END;                                          */

        /* ERROR LOG */
        V_LOG_TYPE    := 'ERROR';
        V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
        V_DESCRIPTION := SUBSTR('ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 500);
        D_EVENT_DATE  := SYSDATE;
        PR_SCP_SYS_LOG_BATCH( P_PROGRAM_NAME  => V_PROGRAM_NAME
                            , P_LOG_TYPE      => V_LOG_TYPE
                            , P_LOG_COUNT     => N_LOG_COUNT
                            , P_LOG_MESSAGE   => V_LOG_MESSAGE
                            , P_DESCRIPTION   => V_DESCRIPTION
                            , P_EVENT_DATE    => D_EVENT_DATE
                            , P_USER_ID       => V_BATCH_USER
                            );

        RETURN;

    END;

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCP_SYS_LOG_BATCH( P_PROGRAM_NAME  => V_PROGRAM_NAME
                        , P_LOG_TYPE      => V_LOG_TYPE
                        , P_LOG_COUNT     => N_LOG_COUNT
                        , P_LOG_MESSAGE   => V_LOG_MESSAGE
                        , P_DESCRIPTION   => V_DESCRIPTION
                        , P_EVENT_DATE    => D_EVENT_DATE
                        , P_USER_ID       => V_BATCH_USER
                        );

    COMMIT;   /* 원본은 명시 TRAN 없이 MSSQL autocommit 으로 매 문장 영속화 → Oracle 은 종료 시 COMMIT 로 등가 */
    RETURN;

END PR_SCM_MST_SITE_ITEM_FROM_ELEC_TACT_TIME;

