PROCEDURE           "PR_SCM_MST_SITE_PLANT"

/*
 * Program ID   : PR_SCM_MST_SITE_PLANT
 * Description  : SCM_SITE_ID mapping용
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2017.11.30   Kim Jaejung    Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 * 2018.05.22   Kim Jihye      전극 사이트 자동생성 제외
 * 2026.07.06   ZIONEX         [PJ202650304] NextSCM Migration
 */
IS
    /* LOG 용 변수 설정 */
    V_BATCH_USER     VARCHAR2(150 CHAR) := 'scm_batch';
    V_PROGRAM_NAME   VARCHAR2(150 CHAR) := 'PR_SCM_MST_SITE_PLANT';
    V_LOG_TYPE       VARCHAR2(30 CHAR);          /* START/END/ERROR/... */
    N_LOG_COUNT      PLS_INTEGER := 0;
    V_LOG_MESSAGE    VARCHAR2(1000 CHAR);
    V_DESCRIPTION    VARCHAR2(500 CHAR);
    D_EVENT_DATE     DATE;
    V_SHIP_FROZEN    PLS_INTEGER := 0;
    V_PROD_FROZEN    PLS_INTEGER := 0;
    V_FP_PLAN_PERIOD PLS_INTEGER := 0;
BEGIN
    /* 시작 LOG */
    V_LOG_TYPE := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    /* 데이터 변경 없이 일단 INSERT 로만 처리해둠 */
    BEGIN
        BEGIN
            SELECT TO_NUMBER(SEGMENT2)
              INTO V_SHIP_FROZEN
              FROM SCM_ADM_LOOKUP_MASTER_DETAIL
             WHERE LOOKUP_TYPE = 'DEFAULT_PERIOD'
               AND SEGMENT1    = 'SHIP_FROZEN'
               AND VALID_YN    = 'Y';
        EXCEPTION WHEN NO_DATA_FOUND THEN V_SHIP_FROZEN := 0;
        END;

        BEGIN
            SELECT TO_NUMBER(SEGMENT2)
              INTO V_PROD_FROZEN
              FROM SCM_ADM_LOOKUP_MASTER_DETAIL
             WHERE LOOKUP_TYPE = 'DEFAULT_PERIOD'
               AND SEGMENT1    = 'PROD_FROZEN'
               AND VALID_YN    = 'Y';
        EXCEPTION WHEN NO_DATA_FOUND THEN V_PROD_FROZEN := 0;
        END;

        BEGIN
            SELECT TO_NUMBER(SEGMENT2)
              INTO V_FP_PLAN_PERIOD
              FROM SCM_ADM_LOOKUP_MASTER_DETAIL
             WHERE LOOKUP_TYPE = 'DEFAULT_PERIOD'
               AND SEGMENT1    = 'FP_PLAN_PERIOD'
               AND VALID_YN    = 'Y';
        EXCEPTION WHEN NO_DATA_FOUND THEN V_FP_PLAN_PERIOD := 0;
        END;

        MERGE INTO SCM_MST_SITE A
        USING (SELECT /* PR_SCM_MST_SITE_PLANT */
                      P.COMPANY_ID
                    , P.DIVISION_ID
                    , P.SITE_ID
                    , P.PLANT_ID
                    , P.PLANT_NAME
                    , P.PLANT_ID||'-'||F.SHOP_GROUP_ID AS SCM_SITE_ID  /* Plant의 경우 기존 FP의 Plant_id 와 shop_group_id 를 더해서 scm_site_id 로 사용 */
                    , P.PLANT_NAME||'-'||FN_GET_LOOKUP_CODE_DESC('OPERATION_GROUP', F.SHOP_GROUP_ID) AS SCM_SITE_DESCRIPTION
                    , F.SHOP_GROUP_ID
                    , 'N' AS ATTRIBUTE1
                    , 'N' AS ATTRIBUTE2
                 FROM SCM_MST_PLANT_SN   P
                    , SCM_MST_FACTORY_SN F
                WHERE P.DIVISION_ID      = F.DIVISION_ID
                  AND P.PLANT_ID         = F.PLANT_ID
                  AND P.OUTSOURCING_FLAG = 'N'  /* 외주 packer 구분 */
                  AND F.ACTIVE_FLAG      = 'Y'
                  AND F.SHOP_GROUP_ID IS NOT NULL
                  AND F.SHOP_GROUP_ID    != 'E'  /* 2018.05.22   Kim Jihye */
                GROUP BY P.COMPANY_ID
                       , P.DIVISION_ID
                       , P.SITE_ID
                       , P.PLANT_ID
                       , F.SHOP_GROUP_ID
                       , P.PLANT_NAME) B
        ON (A.DIVISION_ID = B.DIVISION_ID
               /*AND A.plant_id	    =  B.plant_id*/
           AND A.SCM_SITE_ID = B.SCM_SITE_ID
               /*AND A.site_type		=  B.shop_group_id*/
           )
        WHEN NOT MATCHED THEN
      INSERT ( COMPANY_ID
             , DIVISION_ID
             , SITE_ID
             , SCM_SITE_ID
             , SITE_DESCRIPTION
             , SITE_TYPE
             , OPERATION_GROUP
             , PLANT_ID
             , DEPT_ID  /* Site type sales 일때 사용, 일단은 PLANT 로 입력 */
             , VMI_YN
             , VALID_YN
             , NEW_YN
             , OSP_YN
             , SHIP_FROZEN
             , PROD_FROZEN
             , FP_PLAN_PERIOD
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2 )
      VALUES ( B.COMPANY_ID
             , B.DIVISION_ID
             , B.SITE_ID
             , B.SCM_SITE_ID
             , B.SCM_SITE_DESCRIPTION
             , 'PLANT'
             , B.SHOP_GROUP_ID
             , B.PLANT_ID
             , 'PLANT'
             , 'N'
             , 'Y'
             , 'Y'
             , 'N'
             , V_SHIP_FROZEN
             , V_PROD_FROZEN
             , V_FP_PLAN_PERIOD
             , V_BATCH_USER
             , SYSDATE
             , V_BATCH_USER
             , SYSDATE
             , B.ATTRIBUTE1
             , B.ATTRIBUTE2 );
        /* --------------------------------------------------------- */
        /* Merge LOG */
        /* --------------------------------------------------------- */
        V_LOG_TYPE := 'APPEND';
        V_LOG_MESSAGE := 'MERGE INTO scm_mst_site';
        V_DESCRIPTION := 'insert only ';
        D_EVENT_DATE := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
        /* --------------------------------------------------------- */

        COMMIT;

    EXCEPTION
        WHEN OTHERS THEN
            /* ERROR LOG */
            V_LOG_TYPE := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := SUBSTR('ERROR LINE ' ||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 500);
            D_EVENT_DATE := SYSDATE;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    END;

    /* 종료 LOG */
    V_LOG_TYPE := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

END PR_SCM_MST_SITE_PLANT;

PROCEDURE           "PR_SCM_MST_USER_INFO" 
/*
 * Program ID   : PR_SCM_MST_USER_INFO
 * Description  : USER 정보 I/F
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2017.11.27   Kim Jaejung    Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 * 2018.04.10   Kim Jaejung    tb_fx_user 테이블에 DEPT_ID 최신값으로 동기화. DM 요청.
 * 2020.01.06	hwyoon		   SSO USER 공백제거 후 MERGE
 * 2023.02.22   FP Pjt.        attribute9:부서변경일자, attribute10:이전부서코드
 * 2024.01.25   vadabi3        NERP - 특정 Company 별도 처리 개선
 * 2024.10.28	vadabi5		   NERP) QA DB 적용
 * 2026.06.16   ZIONEX         [PJ202650304] NextSCM Migration
 ----------------------------------------------------------------------------------------------------
 */
IS
    /* LOG 용 변수 설정 */
    V_BATCH_USER    VARCHAR2(150 CHAR) := 'scm_batch';
    V_PROGRAM_NAME  VARCHAR2(150 CHAR) := 'PR_SCM_MST_USER_INFO';
    V_LOG_TYPE      VARCHAR2(30 CHAR);          /* START/END/ERROR/... */
    N_LOG_COUNT     PLS_INTEGER := 0;
    V_LOG_MESSAGE   VARCHAR2(1000 CHAR);
    V_DESCRIPTION   VARCHAR2(500 CHAR);
    D_EVENT_DATE    DATE;
    V_IFSEQNO       VARCHAR2(30 CHAR);

    /* NERP 매핑코드 */
    V_COMPANY_SALES VARCHAR2(8 CHAR);
    V_ESOC          VARCHAR2(8 CHAR);

    /* 지나간 배치까지 적용하기 위해 Cursor 로 처리 */
    CURSOR CUR_SSO_USER IS
        SELECT   IFSEQNO
        FROM     XIF_SSO_USER_INFO_R_SN
        WHERE    ATTRIBUTE15 = 'P'
        GROUP BY IFSEQNO
        ORDER BY IFSEQNO ASC;
BEGIN
    V_COMPANY_SALES := FN_GET_LOOKUP_VALUE('PR_SCM_MST_USER_INFO', 'COMPANY_SALES');
    V_ESOC := FN_GET_LOOKUP_VALUE('PR_SCM_MST_USER_INFO', 'ESOC');

    /* 시작 LOG */
    V_LOG_TYPE := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    BEGIN
        /* 인터페이스 테이블 처리 ROW UPDATE */
        UPDATE XIF_SSO_USER_INFO_R_SN
        SET    ATTRIBUTE15 = 'P'
        WHERE  NVL(ATTRIBUTE15, 'N') = 'N';

        FOR R IN CUR_SSO_USER LOOP
            V_IFSEQNO := R.IFSEQNO;

            MERGE INTO SCM_MST_SSO_USER_INFO A
            USING (
                  SELECT /* PR_SCM_MST_USER_INFO */
                         RTRIM(A0.SA_USER) AS SA_USER
                       , A0.SA_NAME
                       , A0.SA_NAME_E
                       /*,sa_user+'@lgchem.com' as email*/
                       , CASE WHEN A0.SA_DEPT IS NULL THEN A0.SA_DEPT_NEW ELSE A0.SA_DEPT END AS SA_DEPT
                       , A0.SA_JOBX
                       , A0.SA_JOBX_NAME
                       , CASE WHEN A0.SA_COMP = V_COMPANY_SALES THEN V_ESOC
                              ELSE A0.SA_COMP
                              END AS SA_COMP
                       , A0.SSO_EX_FLAG
                       /*,(case isnull(sso_ex_flag,'d') when 'd' then 'n' else 'y' end) as useyn*/
                       , A0.SA_GNMU
                       , A0.SA_GNMU_NAME
                       , A0.SSO_LOCATE
                       , A0.CREATE_DATE
                  FROM XIF_SSO_USER_INFO_R_SN A0
                  WHERE A0.IFSEQNO = V_IFSEQNO
                  /* AND SA_COMP IN(SELECT company_id from SCM_MST_SITE_SN) */
                  AND A0.ATTRIBUTE15 = 'P'
                 ) B
            ON (A.USER_ID = B.SA_USER
               )
            WHEN MATCHED THEN
                 UPDATE SET A.USER_NAME        = B.SA_NAME
                          , A.USER_NAME_EN     = B.SA_NAME_E
                          /*,A.email          =  B.email*/
                          , A.DEPT_ID          = B.SA_DEPT
                          , A.JOB_CODE         = B.SA_JOBX
                          , A.JOB_NAME         = B.SA_JOBX_NAME
                          , A.COMPANY_ID       = B.SA_COMP
                          , A.WORKING_CODE     = B.SA_GNMU
                          , A.WORKING_NAME     = B.SA_GNMU_NAME
                          , A.SSO_LOCATE       = B.SSO_LOCATE
                          , A.ACTIVE_FLAG      = B.SSO_EX_FLAG
                          /*,A.valid_yn      =  B.useyn
                            ,A.created_by       =  @v_batch_user
                            ,A.creation_date    =  B.create_date*/
                          , A.LAST_UPDATED_BY  = V_BATCH_USER
                          , A.LAST_UPDATE_DATE = SYSDATE
                          , A.ATTRIBUTE9       = CASE WHEN A.DEPT_ID != B.SA_DEPT THEN TO_CHAR(SYSDATE, 'YYYYMMDD') ELSE A.ATTRIBUTE9 END   /* 부서 변경일자 */
                          , A.ATTRIBUTE10      = CASE WHEN A.DEPT_ID != B.SA_DEPT THEN A.DEPT_ID ELSE A.ATTRIBUTE10 END                     /* 이전 부서코드 */
            WHEN NOT MATCHED THEN
                 INSERT (USER_ID
                           , USER_NAME
                           , USER_NAME_EN
                           /*,email*/
                           , DEPT_ID
                           /*,funccode
                             ,funcname*/
                           , JOB_CODE
                           , JOB_NAME
                           , COMPANY_ID
                           , WORKING_CODE
                           , WORKING_NAME
                           , SSO_LOCATE
                           , ACTIVE_FLAG
                           , CREATED_BY
                           , CREATION_DATE
                           , LAST_UPDATED_BY
                           , LAST_UPDATE_DATE
                        )
                 VALUES (B.SA_USER
                           , B.SA_NAME
                           , B.SA_NAME_E
                           /*,B.email*/
                           , B.SA_DEPT
                           /*,B.sa_func
                             ,B.sa_func_name_e
                             ,B.useyn*/
                           , B.SA_JOBX
                           , B.SA_JOBX_NAME
                           , B.SA_COMP
                           , B.SA_GNMU
                           , B.SA_GNMU_NAME
                           , B.SSO_LOCATE
                           , B.SSO_EX_FLAG
                           , V_BATCH_USER
                           , SYSDATE
                           , V_BATCH_USER
                           , SYSDATE
                        );

            /* --------------------------------------------------------- */
            /* Merge LOG */
            /* --------------------------------------------------------- */
            V_LOG_TYPE := 'APPEND';
            V_LOG_MESSAGE := 'MERGE INTO scm_mst_sso_user_info';
            V_DESCRIPTION := 'ifseqno = ' ||V_IFSEQNO;
            D_EVENT_DATE := SYSDATE;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
            /* --------------------------------------------------------- */

            /* 2018.04.10 tb_fx_user 테이블에 DEPT_ID 최신값으로 동기화. DM 요청 */
            /* 2026.09.30 AJS 수정 (START) */
--            UPDATE TB_FX_USER FU
--            SET    FU.DEPT_ID = (SELECT MAX(RS.SA_DEPT)
--                                 FROM   XIF_SSO_USER_INFO_R_SN RS
--                                 WHERE  RTRIM(FU.USERID) = RTRIM(RS.SA_USER)
--                                 AND    FU.DEPT_ID != RS.SA_DEPT
--                                 AND    RS.IFSEQNO = V_IFSEQNO
--                                 AND    RS.ATTRIBUTE15 = 'P')
--                 , FU.UPDATEUSERID = V_BATCH_USER
--                 , FU.UPDATEDATETIME = SYSDATE
--            WHERE  EXISTS (SELECT 1
--                           FROM   XIF_SSO_USER_INFO_R_SN RS
--                           WHERE  RTRIM(FU.USERID) = RTRIM(RS.SA_USER)
--                           AND    FU.DEPT_ID != RS.SA_DEPT
--                           AND    RS.IFSEQNO = V_IFSEQNO
--                           AND    RS.ATTRIBUTE15 = 'P');
            UPDATE SCM_ADM_USER_M FU
            SET    FU.DEPT_ID = (SELECT MAX(RS.SA_DEPT)
                                 FROM   XIF_SSO_USER_INFO_R_SN RS
                                 WHERE  RTRIM(FU.USER_ID) = RTRIM(RS.SA_USER)
                                 AND    FU.DEPT_ID != RS.SA_DEPT
                                 AND    RS.IFSEQNO = V_IFSEQNO
                                 AND    RS.ATTRIBUTE15 = 'P')
                  ,FU.LAST_UPDATED_BY = V_BATCH_USER
                  ,FU.LAST_UPDATE_DATE = SYSDATE
            WHERE  EXISTS (SELECT 1
                           FROM   XIF_SSO_USER_INFO_R_SN RS
                           WHERE  RTRIM(FU.USER_ID) = RTRIM(RS.SA_USER)
                           AND    FU.DEPT_ID != RS.SA_DEPT
                           AND    RS.IFSEQNO = V_IFSEQNO
                           AND    RS.ATTRIBUTE15 = 'P');
            /* 2026.09.30 AJS 수정 (END) */

            /* --------------------------------------------------------- */
            /* Merge LOG */
            /* --------------------------------------------------------- */
            V_LOG_TYPE := 'APPEND';
            V_LOG_MESSAGE := 'UPDATE tb_fx_user';
            V_DESCRIPTION := 'ifseqno = ' ||V_IFSEQNO;
            D_EVENT_DATE := SYSDATE;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
        END LOOP;

        /* 처리 한 row 마킹 */
        UPDATE XIF_SSO_USER_INFO_R_SN SET ATTRIBUTE15 = 'Y'
