PROCEDURE           "PR_SCM_PLN_XIF_PROJECT_GQMS_S" 
/*
 * Program ID   : PR_SCM_PLN_XIF_PROJECT_GQMS_S
 * Description  : PR_SCM_PLN_XIF_PROJECT_GQMS_S
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
