        -------------------------------------------------------------------------------------------------------*/
        DELETE FROM XIF_SCM_MST_PROJECT_S_SN
        WHERE  IF_INS_DATE < TRUNC(SYSDATE) - 14;

        /*		SCM_MST_PROJECT		->		XIF_SCM_MST_PROJECT_S		*/
