             'OSCM' ||TO_CHAR(SYSDATE, 'YYMMDD')||FN_ZERO_LPAD(TO_CHAR(SEQ1_XIF_SCM_PROJECT_S.NEXTVAL), 10) AS IF_SEQ, 'S' AS IF_TYPE
            , 'OSCM_GQMS_XIF_SCM_MST_PROJECT' AS IF_ID, SYSDATE AS IF_INS_DATE, 'N' AS IF_FLAG
            , DIVISION_ID, PROJECT_CODE, PROJECT_VER_SEQ, PROJECT_NAME
            , BIZ_TYPE, BIZ_TYPE_NAME, PROJECT_STATUS, PROJECT_OWNER
            , CURRENCY, DROP_YN, CAPACITY, GPLM_PROJECT_CODE
            , GPLM_SYSTEM_PROJECT_CODE, GPLM_DEV_PROJECT_CODE, GPLM_MAPPING_YN, SHIPMENT_DATE
            , PRODUCT_GROUP_CODE, PRODUCT_GROUP_NAME, INCOTERMS, CREATION_DATE
            , CREATED_BY, LAST_UPDATE_DATE, LAST_UPDATED_BY, ATTRIBUTE1
            , ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
            , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9
            , ATTRIBUTE10
