                           , P_LOG_MESSAGE  => V_LOG_MESSAGE
                           , P_DESCRIPTION  => V_DESCRIPTION
                           , P_EVENT_DATE   => D_EVENT_DATE
                           , P_USER_ID      => V_BATCH_USER);

        /* ------------------------------------------------------------------------------------------------------- */
        /* SCP_ANL_PSI_GLOBAL ? */
        /* ------------------------------------------------------------------------------------------------------- */

        /* ------------------------------------------------------------------------------------------------------- */
        /* STEP 4 DELETE FROM SCP_ANL_DIO_REPORT_DETAIL */
        /* ------------------------------------------------------------------------------------------------------- */
        DELETE FROM SCP_ANL_DIO_REPORT_DETAIL
         WHERE DIVISION_ID          = P_DIVISION_ID
           AND PLAN_START_YYYYMMDD  = P_PLAN_START_YYYYMMDD
           AND PLAN_TYPE            = P_PLAN_TYPE
           AND SEQ                  = P_SEQ
           AND VER                  = P_VER;
        /* ------------------------------------------------------------------------------------------------------- */
        N_LOG_COUNT   := SQL%ROWCOUNT;
        V_SEC         := ROUND((SYSDATE - V_START_TIME) * 86400);

        V_EXEC_TIME := CASE WHEN LENGTH(TO_CHAR(TRUNC(V_SEC / 60))) > 2 THEN NULL
                            ELSE LPAD(TO_CHAR(TRUNC(V_SEC / 60)), 2, '0') || ':' || LPAD(TO_CHAR(MOD(V_SEC, 60)), 2, '0')
                       END;
        V_LOG_TYPE    := 'STEP';
        V_LOG_MESSAGE := 'STEP 4 DELETE FROM SCP_ANL_DIO_REPORT_DETAIL';
        V_DESCRIPTION := '[' || V_EXEC_TIME || ']';
        D_EVENT_DATE  := SYSDATE;
        PR_SCP_SYS_LOG_BATCH(P_PROGRAM_NAME => V_PROGRAM_NAME
                           , P_LOG_TYPE     => V_LOG_TYPE
                           , P_LOG_COUNT    => N_LOG_COUNT
                           , P_LOG_MESSAGE  => V_LOG_MESSAGE
                           , P_DESCRIPTION  => V_DESCRIPTION
                           , P_EVENT_DATE   => D_EVENT_DATE
                           , P_USER_ID      => V_BATCH_USER);

        /* ------------------------------------------------------------------------------------------------------- */
        /* STEP 5-1  DELETE FROM SCP_ANL_DIO_REPORT_H */
        /* ------------------------------------------------------------------------------------------------------- */
        DELETE FROM SCP_ANL_DIO_REPORT_H
         WHERE DIVISION_ID          = P_DIVISION_ID
           AND PLAN_START_YYYYMMDD  = P_PLAN_START_YYYYMMDD
           AND PLAN_TYPE            = P_PLAN_TYPE
           AND SEQ                  = P_SEQ
           AND VER                  = P_VER;
        /* ------------------------------------------------------------------------------------------------------- */
        N_LOG_COUNT   := SQL%ROWCOUNT;
        V_SEC         := ROUND((SYSDATE - V_START_TIME) * 86400);

        V_EXEC_TIME := CASE WHEN LENGTH(TO_CHAR(TRUNC(V_SEC / 60))) > 2 THEN NULL
                            ELSE LPAD(TO_CHAR(TRUNC(V_SEC / 60)), 2, '0') || ':' || LPAD(TO_CHAR(MOD(V_SEC, 60)), 2, '0')
                       END;
        V_LOG_TYPE    := 'STEP';
        V_LOG_MESSAGE := 'STEP 5-1 DELETE FROM SCP_ANL_DIO_REPORT_H';
        V_DESCRIPTION := '[' || V_EXEC_TIME || ']';
        D_EVENT_DATE  := SYSDATE;
        PR_SCP_SYS_LOG_BATCH(P_PROGRAM_NAME => V_PROGRAM_NAME
                           , P_LOG_TYPE     => V_LOG_TYPE
                           , P_LOG_COUNT    => N_LOG_COUNT
                           , P_LOG_MESSAGE  => V_LOG_MESSAGE
                           , P_DESCRIPTION  => V_DESCRIPTION
                           , P_EVENT_DATE   => D_EVENT_DATE
                           , P_USER_ID      => V_BATCH_USER);

        /* ------------------------------------------------------------------------------------------------------- */
        /* STEP 5-2  INSERT SCP_ANL_DIO_REPORT_H */
        /* ------------------------------------------------------------------------------------------------------- */
        /* 불필요
    INSERT  INTO  SCP_ANL_DIO_REPORT_H (
                                 DIVISION_ID
                                ,PLAN_START_YYYYMMDD
                                ,PLAN_TYPE
                                ,SEQ
                                ,VER
                                ,NICK_NAME
                                ,PLANT_ID
                                ,FROM_SITE
                                ,TO_SITE
                                ,END_CUSTOMER
                                ,ITEM_ID
                                ,CELL_ITEM_ID
                                ,VERSION
                                ,CREATED_BY
                                ,CREATION_DATE
                                ,LAST_UPDATED_BY
                                ,LAST_UPDATE_DATE
                                )
                         SELECT  @P_DIVISION_ID
                                ,@P_PLAN_START_YYYYMMDD
                                ,@P_PLAN_TYPE
                                ,@P_SEQ
                                ,@P_VER
                                ,'DELETE'
                                ,'DELETE'
                                ,'DELETE'
                                ,'DELETE'
                                ,'DELETE'
                                ,'DELETE'
                                ,'DELETE'
                                ,@P_VER
                                ,@P_CREATED_BY
                                ,SYSDATETIME()
                                ,@P_CREATED_BY
                                ,SYSDATETIME()
        */
        /* ------------------------------------------------------------------------------------------------------- */
        N_LOG_COUNT   := SQL%ROWCOUNT;
        V_SEC         := ROUND((SYSDATE - V_START_TIME) * 86400);

        V_EXEC_TIME := CASE WHEN LENGTH(TO_CHAR(TRUNC(V_SEC / 60))) > 2 THEN NULL
                            ELSE LPAD(TO_CHAR(TRUNC(V_SEC / 60)), 2, '0') || ':' || LPAD(TO_CHAR(MOD(V_SEC, 60)), 2, '0')
                       END;
        V_LOG_TYPE    := 'STEP';
        V_LOG_MESSAGE := 'STEP 5-2  INSERT SCP_ANL_DIO_REPORT_H';
        V_DESCRIPTION := '[' || V_EXEC_TIME || ']';
        D_EVENT_DATE  := SYSDATE;
        PR_SCP_SYS_LOG_BATCH(P_PROGRAM_NAME => V_PROGRAM_NAME
                           , P_LOG_TYPE     => V_LOG_TYPE
                           , P_LOG_COUNT    => N_LOG_COUNT
                           , P_LOG_MESSAGE  => V_LOG_MESSAGE
                           , P_DESCRIPTION  => V_DESCRIPTION
                           , P_EVENT_DATE   => D_EVENT_DATE
                           , P_USER_ID      => V_BATCH_USER);

        /* ------------------------------------------------------------------------------------------------------- */
        /* STEP 6 DELETE FROM SCP_ANL_DIO_CYCLE_INVENTORY */
        /* ------------------------------------------------------------------------------------------------------- */
        DELETE FROM SCP_ANL_DIO_CYCLE_INVENTORY
         WHERE DIVISION_ID          = P_DIVISION_ID
           AND PLAN_START_YYYYMMDD  = P_PLAN_START_YYYYMMDD
           AND PLAN_TYPE            = P_PLAN_TYPE
           AND SEQ                  = P_SEQ
           AND VER                  = P_VER;
        /* ------------------------------------------------------------------------------------------------------- */
        N_LOG_COUNT   := SQL%ROWCOUNT;
        V_SEC         := ROUND((SYSDATE - V_START_TIME) * 86400);

        V_EXEC_TIME := CASE WHEN LENGTH(TO_CHAR(TRUNC(V_SEC / 60))) > 2 THEN NULL
                            ELSE LPAD(TO_CHAR(TRUNC(V_SEC / 60)), 2, '0') || ':' || LPAD(TO_CHAR(MOD(V_SEC, 60)), 2, '0')
                       END;
        V_LOG_TYPE    := 'STEP';
        V_LOG_MESSAGE := 'STEP 6 DELETE FROM SCP_ANL_DIO_CYCLE_INVENTORY';
        V_DESCRIPTION := '[' || V_EXEC_TIME || ']';
        D_EVENT_DATE  := SYSDATE;
        PR_SCP_SYS_LOG_BATCH(P_PROGRAM_NAME => V_PROGRAM_NAME
                           , P_LOG_TYPE     => V_LOG_TYPE
                           , P_LOG_COUNT    => N_LOG_COUNT
                           , P_LOG_MESSAGE  => V_LOG_MESSAGE
                           , P_DESCRIPTION  => V_DESCRIPTION
                           , P_EVENT_DATE   => D_EVENT_DATE
                           , P_USER_ID      => V_BATCH_USER);

        /* ------------------------------------------------------------------------------------------------------- */
        /* STEP 7 DELETE FROM SCP_ANL_DIO_REPORT_DETAIL_AGING -- 20220823 추가 */
        /* ------------------------------------------------------------------------------------------------------- */
        DELETE FROM SCP_ANL_DIO_REPORT_DETAIL_AGING
         WHERE DIVISION_ID          = P_DIVISION_ID
           AND PLAN_START_YYYYMMDD  = P_PLAN_START_YYYYMMDD
           AND PLAN_TYPE            = P_PLAN_TYPE
           AND SEQ                  = P_SEQ
           AND VER                  = P_VER;
        /* ------------------------------------------------------------------------------------------------------- */
        N_LOG_COUNT   := SQL%ROWCOUNT;
        V_SEC         := ROUND((SYSDATE - V_START_TIME) * 86400);

        V_EXEC_TIME := CASE WHEN LENGTH(TO_CHAR(TRUNC(V_SEC / 60))) > 2 THEN NULL
                            ELSE LPAD(TO_CHAR(TRUNC(V_SEC / 60)), 2, '0') || ':' || LPAD(TO_CHAR(MOD(V_SEC, 60)), 2, '0')
                       END;
        V_LOG_TYPE    := 'STEP';
        V_LOG_MESSAGE := 'STEP 7 DELETE FROM SCP_ANL_DIO_REPORT_DETAIL_AGING';
        V_DESCRIPTION := '[' || V_EXEC_TIME || ']';
        D_EVENT_DATE  := SYSDATE;
        PR_SCP_SYS_LOG_BATCH(P_PROGRAM_NAME => V_PROGRAM_NAME
                           , P_LOG_TYPE     => V_LOG_TYPE
                           , P_LOG_COUNT    => N_LOG_COUNT
                           , P_LOG_MESSAGE  => V_LOG_MESSAGE
                           , P_DESCRIPTION  => V_DESCRIPTION
                           , P_EVENT_DATE   => D_EVENT_DATE
                           , P_USER_ID      => V_BATCH_USER);

        /* ------------------------------------------------------------------------------------------------------- */
        /* STEP 8 DELETE FROM SCP_ANL_DIO_REPORT_VERSION */
        /* ------------------------------------------------------------------------------------------------------- */
        DELETE FROM SCP_ANL_DIO_REPORT_VERSION
         WHERE DIVISION_ID          = P_DIVISION_ID
           AND PLAN_START_YYYYMMDD  = P_PLAN_START_YYYYMMDD
           AND PLAN_TYPE            = P_PLAN_TYPE
           AND SEQ                  = P_SEQ
           AND VER                  = P_VER;
        /* ------------------------------------------------------------------------------------------------------- */
        N_LOG_COUNT   := SQL%ROWCOUNT;
        V_SEC         := ROUND((SYSDATE - V_START_TIME) * 86400);

        V_EXEC_TIME := CASE WHEN LENGTH(TO_CHAR(TRUNC(V_SEC / 60))) > 2 THEN NULL
                            ELSE LPAD(TO_CHAR(TRUNC(V_SEC / 60)), 2, '0') || ':' || LPAD(TO_CHAR(MOD(V_SEC, 60)), 2, '0')
                       END;
        V_LOG_TYPE    := 'STEP';
        V_LOG_MESSAGE := 'STEP 8 DELETE FROM SCP_ANL_DIO_REPORT_VERSION';
        V_DESCRIPTION := '[' || V_EXEC_TIME || ']';
        D_EVENT_DATE  := SYSDATE;
        PR_SCP_SYS_LOG_BATCH(P_PROGRAM_NAME => V_PROGRAM_NAME
                           , P_LOG_TYPE     => V_LOG_TYPE
                           , P_LOG_COUNT    => N_LOG_COUNT
                           , P_LOG_MESSAGE  => V_LOG_MESSAGE
                           , P_DESCRIPTION  => V_DESCRIPTION
                           , P_EVENT_DATE   => D_EVENT_DATE
                           , P_USER_ID      => V_BATCH_USER);

        V_RETURN := '1';
        OPEN P_CURSOR FOR SELECT V_RETURN AS RESULT FROM DUAL;

    EXCEPTION
        WHEN OTHERS THEN
            /* ------------------------------------------------------------------------------------------------------- */
            /* LOG ERROR */
            /* ------------------------------------------------------------------------------------------------------- */
            DELETE FROM SCP_ANL_DIO_REPORT_VERSION
             WHERE DIVISION_ID          = P_DIVISION_ID
               AND PLAN_START_YYYYMMDD  = P_PLAN_START_YYYYMMDD
               AND PLAN_TYPE            = P_PLAN_TYPE
               AND SEQ                  = P_SEQ
               AND VER                  = P_VER
               AND VER_STATUS           = 'P';

            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SQLERRM;
            V_DESCRIPTION := 'ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
            D_EVENT_DATE  := SYSDATE;
            PR_SCP_SYS_LOG_BATCH(P_PROGRAM_NAME => V_PROGRAM_NAME
                               , P_LOG_TYPE     => V_LOG_TYPE
                               , P_LOG_COUNT    => N_LOG_COUNT
                               , P_LOG_MESSAGE  => V_LOG_MESSAGE
                               , P_DESCRIPTION  => V_DESCRIPTION
                               , P_EVENT_DATE   => D_EVENT_DATE
                               , P_USER_ID      => V_BATCH_USER);
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SQLCODE));
            DBMS_OUTPUT.PUT_LINE(V_LOG_MESSAGE || ' : ' || V_DESCRIPTION);
            COMMIT;
            RETURN;
    END;

    /* ------------------------------------------------------------------------------------------------------- */
    /* LOG END */
    /* ------------------------------------------------------------------------------------------------------- */
    V_SEC         := ROUND((SYSDATE - V_START_TIME) * 86400);

    V_EXEC_TIME := CASE WHEN LENGTH(TO_CHAR(TRUNC(V_SEC / 60))) > 2 THEN NULL
                        ELSE LPAD(TO_CHAR(TRUNC(V_SEC / 60)), 2, '0') || ':' || LPAD(TO_CHAR(MOD(V_SEC, 60)), 2, '0')
                   END;
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure  ##########';
    V_DESCRIPTION := '[' || V_EXEC_TIME || ']';
    D_EVENT_DATE  := SYSDATE;

    PR_SCP_SYS_LOG_BATCH(P_PROGRAM_NAME => V_PROGRAM_NAME
                       , P_LOG_TYPE     => V_LOG_TYPE
                       , P_LOG_COUNT    => N_LOG_COUNT
                       , P_LOG_MESSAGE  => V_LOG_MESSAGE
                       , P_DESCRIPTION  => V_DESCRIPTION
                       , P_EVENT_DATE   => D_EVENT_DATE
                       , P_USER_ID      => V_BATCH_USER);

    COMMIT;
END;

PROCEDURE PR_SCP_ANL_LONG_TERM_STOCK_REPORT
