 * 2023/05/08   vdabi3      PJ20230691R  LGES SCM 역량 강화 위한 SCP 개선과제  - Amount 적용 개선
 * 2023/05/09   vdabi3      PJ20230691R  LGES SCM 역량 강화 위한 SCP 개선과제  - 현지퐈 표시
 * 2023/09/13   vdabi3      PJ20230691R  LGES SCM 역량 강화 위한 SCP 개선과제  - 환율 - 기말재고와 동기화
 * 2025/02/28   kimcd       PJ20249548R  LGES SCP역량 강화를 위한 기준정보PSI엔진 기능개선
 * 2025/04/03   oij         -            인터페이스 데이터 중복에 의한 마지막 버전을 활용하도록 변경
 * 2025.06.19   김준규      [IT20250117A] NERP 오펀차수별 Mapping Code적용
 * 2025.07.03   김준규      [IT20250117A] 실행시점 1개월전 1일포함 큰것 대상으로  현시점 롤인 상태로 컨버전 수행
 * 2025.11.07   park.choyi  [E20250310-000014] 업무 용어 변경에 따른 시스템내 표기 수정 요청 ('부실' -> '장기')
 * 2025.11.25   park.choyi  [E20250423-000916] 단가 기준 변경. LNETP(Unit cost of ledger) -> CNETP(Unit cost of Total by ledger)
 * 2026.07.06   ZIONEX      [PJ202650304] NextSCM Migration
 ----------------------------------------------------------------------------------------------------
 EXEC PR_SCP_ANL_LONG_TERM_STOCK_REPORT

 SCP_ANL_LONG_TERM_STOCK WITH(NOLOCK)
 SCP_MST_EXCHANGE_RATE WITH(NOLOCK)
 */

    V_DEBUG_MODE            VARCHAR2(8 CHAR) := 'F';

    V_RETURN                VARCHAR2(10 CHAR) := '0';
    V_COUNT                 INTEGER := 0;             /* 기존데이터가 있는지 확인 */
    V_COUNT_CURR            INTEGER := 0;             /* 기존환율데이터가 있는지 확인 */
    V_MAX_SPMON             INTEGER := 0;
    /* V_IFSEQNO_CURR        INTEGER := 0;             환율I/F SEQ 사용안함 */
    V_IFMAXDT_CURR          VARCHAR2(8 CHAR) := '';   /* 환율I/F MAX DATE */

    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME          VARCHAR2(150 CHAR) := 'PR_SCP_ANL_LONG_TERM_STOCK_REPORT';   /* Proc별 이름 설정 */
    V_LOG_TYPE              VARCHAR2(30 CHAR);        /* START/END/ERROR/... */
    N_LOG_COUNT             INTEGER := 0;
    V_LOG_MESSAGE           VARCHAR2(1000 CHAR);
    V_DESCRIPTION           VARCHAR2(500 CHAR);
    D_EVENT_DATE            DATE;
    V_BATCH_USER            VARCHAR2(150 CHAR) := 'scp_batch';

    /* 임시 실행시간 확인용 */
    V_START_TIME            DATE := SYSDATE;
    V_EXEC_TIME             VARCHAR2(10 CHAR) := '';  /* '[00:00]' */

    /* ------------------------------------------------------------------ */
    /* 2025.06.19 김준규 [IT20250117A] NERP 오펀차수별 Mapping Code적용 Start */
    /* ------------------------------------------------------------------ */
    V_NERP_ROLLIN_STAGE     VARCHAR2(30 CHAR);
    V_NERP_START_YYYYMMDD   VARCHAR2(8 CHAR);
    /* ------------------------------------------------------------------ */
    /* 2025.06.19 김준규 [IT20250117A] NERP 오펀차수별 Mapping Code적용 End */
    /* ------------------------------------------------------------------ */

    /* (MSSQL 본문 중간 DECLARE -> 선언부로 이동) */
    V_NOW_DATE              VARCHAR2(20 CHAR);
    V_NOW_TIME              VARCHAR2(20 CHAR);
    V_PRE_YYYYMM            VARCHAR2(6 CHAR) := TO_CHAR(ADD_MONTHS(SYSDATE, -1), 'YYYYMM');
    V_CNT_DUP_PLANTBY_SPMON INTEGER := 0;
BEGIN

    /* 시작 LOG  (START) */
    V_LOG_TYPE := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';   /* [E20250423-000916] Log 양식에 맞춤 */
    V_DESCRIPTION := '' ;
    D_EVENT_DATE := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    V_LOG_MESSAGE := NULL;      /* < - 변수 재사용을 위하여 초기화해야함 */

    /* ------------------------------------------------------------------ */
    /* 2025.06.19 김준규 [IT20250117A] NERP 오펀차수별 Mapping Code적용 Start */
    /* ------------------------------------------------------------------ */
    /* MSSQL SELECT TOP 1 (0행이면 변수 NULL 유지 -> NO_DATA_FOUND 가드) */
    BEGIN
        SELECT SEGMENT1
             , SEGMENT2
          INTO V_NERP_ROLLIN_STAGE
             , V_NERP_START_YYYYMMDD
          FROM ( SELECT LMD.SEGMENT1
                      , LMD.SEGMENT2
                   FROM SCM_ADM_LOOKUP_MASTER_DETAIL LMD
                      , SCM_ADM_LOOKUP_MASTER        ALM
                  WHERE ALM.LOOKUP_TYPE = LMD.LOOKUP_TYPE
                    AND ALM.LOOKUP_TYPE = 'NERP_ROLLIN_STAGE'
                    AND ALM.VALID_YN = 'Y'
                    AND LMD.VALID_YN = 'Y' )
         WHERE ROWNUM = 1;
    EXCEPTION WHEN NO_DATA_FOUND THEN NULL;
    END;
    /* ------------------------------------------------------------------ */
    /* 2025.06.19 김준규 [IT20250117A] NERP 오펀차수별 Mapping Code적용 End */
    /* ------------------------------------------------------------------ */

    /* 시작 LOG */
    BEGIN
        DBMS_OUTPUT.PUT_LINE('----------------------------------');
        DBMS_OUTPUT.PUT_LINE('START');
        DBMS_OUTPUT.PUT_LINE('----------------------------------');
    END;

    BEGIN
        /* --------------------------------------------------------------------------------------------------- */
        /*  기본 데이터 생성 */
        /* --------------------------------------------------------------------------------------------------- */

        DELETE FROM GT_SALTS_XIF;
        DELETE FROM GT_SALTS_XIF2;
        DELETE FROM GT_SALTS_XIF3;
        DELETE FROM GT_SALTS_SEQ_NO;
        DELETE FROM GT_SALTS_CURR;
        DELETE FROM GT_SALTS_MST_ITEM;
        DELETE FROM GT_SALTS_X_ITEM_CLASS;
        DELETE FROM GT_SALTS_XIF_ERP_EXCRATE_R_SN;
        DELETE FROM GT_SALTS_W_RAW;
        /* [E20250310-000014] LONG_TERM_TYPE 임시테이블 삭제 */
        DELETE FROM GT_SALTS_LONG_TERM_TYPE;

        V_NOW_DATE := TO_CHAR(SYSDATE, 'YYYYMMDD');
        V_NOW_TIME := TO_CHAR(SYSDATE, 'HH24MI');

        /* [E20250310-000014] LONG_TERM_TYPE 임시테이블 데이터 생성 */
        INSERT
          INTO GT_SALTS_LONG_TERM_TYPE
             ( LONG_TERM_TYPE_CODE
             , LONG_TERM_TYPE
             , GRM_MM_FROM
             , GRM_MM_TO )
        SELECT LMD.SEGMENT1
             , LMD.SEGMENT2
             , LMD.SEGMENT3
             , LMD.SEGMENT4
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL LMD
             , SCM_ADM_LOOKUP_MASTER        ALM
         WHERE ALM.LOOKUP_TYPE = LMD.LOOKUP_TYPE
           AND ALM.LOOKUP_TYPE = 'SCM_LGTM_TYPE'
           AND ALM.VALID_YN = 'Y'
           AND LMD.VALID_YN = 'Y';

    /* ------------------------------------------------------------------- */
    /* 1. 환율정보 변경전 */
    /* ------------------------------------------------------------------- */
    /* 적용 사유 있을 수 있으므로 백업 및 작동은 유지 */
    /* ------------------------------------------------------------------- */
        UPDATE XIF_ERP_EXCRATE_R_SN
           SET TRANSFER_FLAG = 'P'
             , UPDATE_DATE  = V_NOW_DATE
             , UPDATE_TIME  = V_NOW_TIME
             , UPDATE_USER_ID  = V_BATCH_USER
         WHERE TRANSFER_FLAG = 'N';

        /* 환율정보 가져오기  : MAX (IFSEQNO)가 부정확 해서 MAX(EX_DT) 로 가져옴 */
        SELECT MAX(EX_DT)
          INTO V_IFMAXDT_CURR
          FROM XIF_ERP_EXCRATE_R_SN
         WHERE TRANSFER_FLAG = 'P';

        /* 20250403 */
        INSERT
          INTO GT_SALTS_CURR
             ( EX_FROM_CURR_CD
             , EX_TO_CURR_CD
             , EX_TO_BAMT )
        SELECT EX_FROM_CURR_CD
             , EX_TO_CURR_CD
             , EX_TO_BAMT
          FROM XIF_ERP_EXCRATE_R_SN
         WHERE EX_DT = V_IFMAXDT_CURR
           AND TRANSFER_FLAG = 'P'
           AND IFSEQNO = (SELECT MAX(IFSEQNO)
                            FROM XIF_ERP_EXCRATE_R_SN
                           WHERE 1=1
                             AND EX_DT = V_IFMAXDT_CURR
                             AND TRANSFER_FLAG = 'P');

        SELECT COUNT(*)
          INTO V_COUNT_CURR
          FROM GT_SALTS_CURR;

        IF V_COUNT_CURR > 0 THEN            /* 해당 월의 기존 데이터는 삭제(환율) */
            LOOP
                DELETE
                  FROM SCP_MST_EXCHANGE_RATE
                 WHERE YYYYMM = SUBSTR(V_IFMAXDT_CURR,1,6)
                   AND ROWNUM <= 40000;

                EXIT WHEN SQL%ROWCOUNT = 0;
            END LOOP;
            COMMIT;
        END IF;

        IF V_COUNT_CURR > 0 THEN
            INSERT
              INTO SCP_MST_EXCHANGE_RATE
                 ( YYYYMM
                 , FROM_CURR_CD
                 , TO_CURR_CD
                 , TO_BAMT
                 , CREATED_BY
                 , CREATION_DATE )
            SELECT SUBSTR(V_IFMAXDT_CURR,1,6)
                 , EX_FROM_CURR_CD
                 , EX_TO_CURR_CD
                 , EX_TO_BAMT
                 , V_BATCH_USER
                 , SYSDATE
              FROM GT_SALTS_CURR;

            UPDATE XIF_ERP_EXCRATE_R_SN
               SET TRANSFER_FLAG = 'Y'
             WHERE TRANSFER_FLAG = 'P';

            COMMIT;
        END IF;

        V_LOG_TYPE := 'ING';   /* [E20250423-000916] Log 추가 */
        V_DESCRIPTION := V_IFMAXDT_CURR;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, '변경전 환율 적용 기준일', V_DESCRIPTION, D_EVENT_DATE);

    /* ------------------------------------------------------------------- */
    /* 1. 기말재고 환율정보 적용 */
    /* ------------------------------------------------------------------- */
    /* 2022.05.17 */
    /* 1) 변경전 = 배치일 이전 Last Day (5월3일 실행 시 5월  2일 환율적용)  TO_CHAR(SYSDATE,'YYYYMMDD') */
    /* 2) 변경후 = 이전월 마감 환율     (5월3일 실행 시 4월 30일 환율적용) */
    /* 3) 위안화 RMB -> CNY (하드코딩으로 변경 필요) */
    /* ------------------------------------------------------------------- */
        INSERT
          INTO GT_SALTS_XIF_ERP_EXCRATE_R_SN
             ( EX_FROM_CURR_CD
             , EX_TO_CURR_CD
             , EX_DT
             , EX_TO_BAMT )
        WITH SUB AS
        (
         /* SELECT CASE
                     WHEN EX_FROM_CURR_CD = 'CNY' THEN 'RMB'
                     ELSE EX_FROM_CURR_CD
                     END AS EX_FROM_CURR_CD */
         SELECT EX_FROM_CURR_CD AS EX_FROM_CURR_CD
              , EX_TO_CURR_CD
              , EX_TO_BAMT
              , EX_DT
              , TRANSFER_FLAG
              , ROW_NUMBER() OVER (PARTITION BY EX_FROM_CURR_CD, EX_TO_CURR_CD ORDER BY EX_DT DESC) RN
           FROM XIF_ERP_EXCRATE_R_SN
          WHERE 1 = 1
            AND TRANSFER_FLAG = 'Y'
            AND EX_TO_CURR_CD = 'KRW'
            AND EX_DT <= TO_CHAR(TRUNC(SYSDATE,'MM'), 'YYYYMMDD')

         UNION

         SELECT 'RMB' AS EX_FROM_CURR_CD
              , EX_TO_CURR_CD
              , EX_TO_BAMT
              , EX_DT
              , TRANSFER_FLAG
              , ROW_NUMBER() OVER (PARTITION BY EX_FROM_CURR_CD, EX_TO_CURR_CD ORDER BY EX_DT DESC) RN
           FROM XIF_ERP_EXCRATE_R_SN
          WHERE 1 = 1
            AND TRANSFER_FLAG = 'Y'
            AND EX_TO_CURR_CD = 'KRW'
            AND EX_FROM_CURR_CD = 'CNY'
            AND EX_DT <= TO_CHAR(TRUNC(SYSDATE,'MM'), 'YYYYMMDD')
        )
        SELECT EX_FROM_CURR_CD
             , EX_TO_CURR_CD
             , EX_DT
             , EX_TO_BAMT
          FROM SUB
         WHERE RN = 1;

        /* MSSQL: SELECT @v_description = EX_DT FROM #tmp (복수행->임의1행, 0행이면 이전값 유지) */
        BEGIN
            SELECT EX_DT
              INTO V_DESCRIPTION
              FROM GT_SALTS_XIF_ERP_EXCRATE_R_SN
             WHERE ROWNUM = 1;
        EXCEPTION WHEN NO_DATA_FOUND THEN NULL;
        END;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, '환율 적용 기준일', V_DESCRIPTION, D_EVENT_DATE);

    /* ----------------------------------------------------------------------------------------------------- */
    /* 0. 2025.07.03 김준규 [IT20250117A] 실행시점 1개월전 1일포함 큰것 대상으로  현시점 롤인 상태로 컨버전 수행 시작 */
    /* ----------------------------------------------------------------------------------------------------- */
        /* UPDATE 수행.  (MSSQL UPDATE..FROM CTE(W_RAW) -> W_RAW GTT materialize 후 상관 UPDATE) */
        INSERT
          INTO GT_SALTS_W_RAW
             ( SPMON
             , WERKS
             , PRCTR
             , WAERS
             , MATKL
             , BKLAS
             , TOBE_PLANT
             , TOBE_PRCTR
             , TOBE_WAERS
             , TOBE_VALUATION_CLASS )
        SELECT SPMON
             , WERKS, PRCTR, WAERS, MATKL, BKLAS
             , N1.NEW_VALUE1 AS TOBE_PLANT
             , N2.NEW_VALUE2 AS TOBE_PRCTR
             , N3.NEW_VALUE1 AS TOBE_WAERS
             , CASE
               WHEN A.BKLAS = '3000' AND NVL(E.NEW_VALUE2,A.MATKL) = 'RE01'   THEN '3001'
               WHEN A.BKLAS = '3000' AND NVL(E.NEW_VALUE2,A.MATKL) = 'RE02'   THEN '3002'
               WHEN A.BKLAS = '3000' AND NVL(E.NEW_VALUE2,A.MATKL) = 'RA01'   THEN '3003'
               WHEN A.BKLAS = '3000' AND NVL(E.NEW_VALUE2,A.MATKL) = 'RA02'   THEN '3004'
               WHEN A.BKLAS = '3000' AND NVL(E.NEW_VALUE2,A.MATKL) LIKE 'RP%' THEN '3005'
               WHEN A.BKLAS = '3001' AND NVL(E.NEW_VALUE2,A.MATKL) = 'RE02'   THEN '3002'
               WHEN A.BKLAS = '3001' AND NVL(E.NEW_VALUE2,A.MATKL) = 'RA01'   THEN '3003'
               WHEN A.BKLAS = '3001' AND NVL(E.NEW_VALUE2,A.MATKL) = 'RA02'   THEN '3004'
               WHEN A.BKLAS = '3001' AND NVL(E.NEW_VALUE2,A.MATKL) LIKE 'RP%' THEN '3005'
               WHEN A.BKLAS = '3001' THEN '3000'
               ELSE NULL
                END AS TOBE_VALUATION_CLASS
          FROM XIF_ERP_LONG_TERM_STOCK_R_SN A
             , (SELECT OLD_VALUE1
                     , NEW_VALUE1
                  FROM NERP_CONV_MASTER_CFM_V
                 WHERE CODETYPE = 'PLANT_ID'
                   AND ATTRIBUTE5 = V_NERP_ROLLIN_STAGE) N1
             , (SELECT OLD_VALUE1
                     , NEW_VALUE1
                  FROM NERP_CONV_MASTER_CFM_V
                 WHERE CODETYPE = 'WAERS'
                   AND ATTRIBUTE5 = V_NERP_ROLLIN_STAGE) N3
             , (SELECT NEW_VALUE1
                     , NEW_VALUE2
                  FROM NERP_CONV_MASTER_CFM_V
                 WHERE CODETYPE = 'MATKL'
                   AND ATTRIBUTE5 = V_NERP_ROLLIN_STAGE) E
             , (SELECT OLD_VALUE1
                     , OLD_VALUE2
                     , NEW_VALUE1
                     , NEW_VALUE2
                     , LPAD(OLD_VALUE2, 10, '0') AS ASIS_CODE
                  FROM NERP_CONV_MASTER_CFM_V
                 WHERE CODETYPE = 'PROFIT_CENTER_ID'
                   AND ATTRIBUTE5 = V_NERP_ROLLIN_STAGE) N2
         WHERE A.WERKS = N1.OLD_VALUE1(+)
           AND A.WAERS = N3.OLD_VALUE1(+)
           AND A.MATNR = E.NEW_VALUE1(+)
           AND A.PRCTR = N2.ASIS_CODE(+)
           AND 1=1
           AND A.SPMON >= V_PRE_YYYYMM
           AND A.TRANSFER_FLAG = 'N'
           AND (   N1.NEW_VALUE1 IS NOT NULL
                OR N2.NEW_VALUE2 IS NOT NULL
                OR N3.NEW_VALUE1 IS NOT NULL
                OR E.NEW_VALUE1 IS NOT NULL );

        UPDATE XIF_ERP_LONG_TERM_STOCK_R_SN SRS
           SET SRS.WERKS          = NVL((SELECT WR.TOBE_PLANT FROM GT_SALTS_W_RAW WR WHERE WR.SPMON=SRS.SPMON AND WR.WERKS=SRS.WERKS AND WR.PRCTR=SRS.PRCTR AND WR.WAERS=SRS.WAERS AND WR.MATKL=SRS.MATKL AND WR.BKLAS=SRS.BKLAS AND ROWNUM=1), SRS.WERKS)
             , SRS.PRCTR          = NVL((SELECT WR.TOBE_PRCTR FROM GT_SALTS_W_RAW WR WHERE WR.SPMON=SRS.SPMON AND WR.WERKS=SRS.WERKS AND WR.PRCTR=SRS.PRCTR AND WR.WAERS=SRS.WAERS AND WR.MATKL=SRS.MATKL AND WR.BKLAS=SRS.BKLAS AND ROWNUM=1), SRS.PRCTR)
             , SRS.WAERS          = NVL((SELECT WR.TOBE_WAERS FROM GT_SALTS_W_RAW WR WHERE WR.SPMON=SRS.SPMON AND WR.WERKS=SRS.WERKS AND WR.PRCTR=SRS.PRCTR AND WR.WAERS=SRS.WAERS AND WR.MATKL=SRS.MATKL AND WR.BKLAS=SRS.BKLAS AND ROWNUM=1), SRS.WAERS)
             , SRS.BKLAS          = NVL((SELECT WR.TOBE_VALUATION_CLASS FROM GT_SALTS_W_RAW WR WHERE WR.SPMON=SRS.SPMON AND WR.WERKS=SRS.WERKS AND WR.PRCTR=SRS.PRCTR AND WR.WAERS=SRS.WAERS AND WR.MATKL=SRS.MATKL AND WR.BKLAS=SRS.BKLAS AND ROWNUM=1), SRS.BKLAS)
             , SRS.ATTRIBUTE10    = 'NERP_BATCH_UPDATE'
             , SRS.UPDATE_USER_ID = V_BATCH_USER
             , SRS.UPDATE_DATE    = V_NOW_DATE
             , SRS.UPDATE_TIME    = V_NOW_TIME
         WHERE SRS.SPMON >= V_PRE_YYYYMM
           AND SRS.TRANSFER_FLAG = 'N';

        /* MSSQL: SELECT TOP 1 @CNT = COUNT(*) ... GROUP BY .. HAVING COUNT(*)>1  (0행이면 초기값 0 유지) */
        BEGIN
            SELECT COUNT(*)
              INTO V_CNT_DUP_PLANTBY_SPMON
              FROM ( SELECT DISTINCT SPMON, WERKS, CASE WHEN LENGTH(IFSEQNO) < 15 THEN 'GERP' ELSE 'NERP' END AS IFFROM
                       FROM XIF_ERP_LONG_TERM_STOCK_R_SN
                      WHERE SPMON >= V_PRE_YYYYMM
                        AND TRANSFER_FLAG = 'N'
                   )
             GROUP BY SPMON, WERKS
            HAVING COUNT(*) > 1
             FETCH FIRST 1 ROWS ONLY;
        EXCEPTION WHEN NO_DATA_FOUND THEN NULL;
        END;


        /* GERP,NERP 중복으로 입력되었을 경우 중단하고 에러 발생 */
        IF V_CNT_DUP_PLANTBY_SPMON > 0 THEN

            V_LOG_TYPE := 'ERROR';
            V_LOG_MESSAGE := 'GERP 와 NERP 동일 PLANT 발생, 발생월:' || V_PRE_YYYYMM;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

            RETURN;   /* 종료 끝내기. */
        END IF;

    /* ----------------------------------------------------------------------------------------------------- */
    /* 0. 2025.07.03 김준규 [IT20250117A] 실행시점 1개월전 1일포함 큰것 대상으로  현시점 롤인 상태로 컨버전 수행 종료 */
    /* ----------------------------------------------------------------------------------------------------- */

    /* ------------------------------------------------------------------- */
    /* 1. 월령재고 배치 시작 */
    /* ------------------------------------------------------------------- */
        UPDATE XIF_ERP_LONG_TERM_STOCK_R_SN
           SET TRANSFER_FLAG = 'P'
             , UPDATE_DATE  = V_NOW_DATE
             , UPDATE_TIME  = V_NOW_TIME
             , UPDATE_USER_ID  = V_BATCH_USER
         WHERE TRANSFER_FLAG = 'N'
         /* 2025.06.19 김준규 [IT20250117A] NERP 오펀차수별 Mapping Code적용 Start */
         /* OLD 코드는 반영이 되지 않게 처리 */
           AND NOT EXISTS ( SELECT 1
                              FROM NERP_CONV_MASTER NCM
                             WHERE NCM.CODETYPE = 'PLANT_ID'
                               AND NCM.OLD_VALUE1 = XIF_ERP_LONG_TERM_STOCK_R_SN.WERKS
                               AND NCM.ATTRIBUTE5 <= V_NERP_ROLLIN_STAGE
                           );
         /* 2025.06.19 김준규 [IT20250117A] NERP 오펀차수별 Mapping Code적용 End */

        SELECT MAX(SPMON)
          INTO V_MAX_SPMON
          FROM XIF_ERP_LONG_TERM_STOCK_R_SN
         WHERE TRANSFER_FLAG = 'P';

        INSERT
          INTO GT_SALTS_SEQ_NO
             ( WERKS
             , SEQ_NO )
        SELECT WERKS
             , MAX(IFSEQNO) SEQ_NO
          FROM XIF_ERP_LONG_TERM_STOCK_R_SN
         WHERE TRANSFER_FLAG = 'P'
           AND SPMON = V_MAX_SPMON
         GROUP BY WERKS;

        SELECT COUNT(*)
          INTO V_COUNT
          FROM GT_SALTS_SEQ_NO;

        /* [E20250423-000916] Log 추가 */
        N_LOG_COUNT   := V_COUNT;
        V_LOG_MESSAGE := 'V_MAX_SPMON';
        V_DESCRIPTION := V_MAX_SPMON;
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        IF V_COUNT > 0 THEN
        /* 해당 월의 기존 데이터는 삭제 */
            LOOP
                DELETE
                  FROM SCP_ANL_LONG_TERM_STOCK
                 WHERE YYYYMM = TO_CHAR(V_MAX_SPMON);

                EXIT WHEN SQL%ROWCOUNT = 0;
            END LOOP;
            COMMIT;
        END IF;

        IF V_COUNT > 0 THEN
                /* -------------------------------------------------------------------------------------------------------------------------------------------------------------- */
                INSERT
                  INTO GT_SALTS_XIF
                    (                       IFSEQNO, DIVISION_ID, YYYYMM, BUKRS, PLANT_ID, ITEM_ID, CHARG, SPEMK
                    , PRCTR, PRODH, MATKL, BWTAR, VALUATION_CLASS, WAERS, CURRENCY, UNIT_PRICE_ORG
                    , UNIT_PRICE, LPEIN, SNETP, SPEIN, SMENG, CREATE_DATE, CREATE_TIME, CREATE_USER_ID
                    , UPDATE_DATE, UPDATE_TIME, UPDATE_USER_ID, TRANSFER_DATE, TRANSFER_TIME, TRANSFER_USER_ID, TRANSFER_FLAG, ATTRIBUTE1
                    , ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9
                    , ATTRIBUTE10, ATTRIBUTE11, ATTRIBUTE12, ATTRIBUTE13, ATTRIBUTE14, ATTRIBUTE15, GRM01, GRM02
                    , GRM03, GRM04, GRM05, GRM06, GRM07, GRM08, GRM09, GRM10
                    , GRM11, GRM12, GRM13, GRM14, GRM15, GRM16, GRM17, GRM18
                    , GRM19, GRM20, GRM21, GRM22, GRM23, GRM24, GRM25, GRM26
                    , GRM27, GRM28, GRM29, GRM30, GRM31, GRM32, GRM33, GRM34
                    , GRM35, GRM36, GRM37, GRM38, GRM39, GRM40, GRM41, GRM42
                    , GRM43, GRM44, GRM45, GRM46, GRM47, GRM48, GRM49, GRM50
                    , GRM51, GRM52, GRM53, GRM54, GRM55, GRM56, GRM57, GRM58
                    , GRM59, GRM60, GRM61 )
                WITH SUB9 AS
                (
                    SELECT SEGMENT1 CENTER
                         , SEGMENT3 DIVISION_ID
                      FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                     WHERE LOOKUP_TYPE = 'ERP_POSTING_STOCK_PRCTR_LONG'
                       AND VALID_YN = 'Y'
                )
              , SUB10 AS
                (
                    SELECT SEGMENT3 PLANT_ID
                         , ATTRIBUTE5 DIVISION_ID
                      FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                     WHERE LOOKUP_TYPE = 'ERP_POSTING_STOCK_SETUP'
                       AND ATTRIBUTE5 <> '-'
                       AND VALID_YN = 'Y'
                )
                SELECT IFSEQNO, DIVISION_ID, YYYYMM, BUKRS, PLANT_ID, ITEM_ID, CHARG, SPEMK
                     , PRCTR, PRODH, MATKL, BWTAR, VALUATION_CLASS, WAERS, CURRENCY, UNIT_PRICE_ORG
                     , UNIT_PRICE, LPEIN, SNETP, SPEIN, SMENG, CREATE_DATE, CREATE_TIME, CREATE_USER_ID
                     , UPDATE_DATE, UPDATE_TIME, UPDATE_USER_ID, TRANSFER_DATE, TRANSFER_TIME, TRANSFER_USER_ID, TRANSFER_FLAG, ATTRIBUTE1
                     , ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9
                     , ATTRIBUTE10, ATTRIBUTE11, ATTRIBUTE12, ATTRIBUTE13, ATTRIBUTE14, ATTRIBUTE15, GRM01, GRM02
                     , GRM03, GRM04, GRM05, GRM06, GRM07, GRM08, GRM09, GRM10
                     , GRM11, GRM12, GRM13, GRM14, GRM15, GRM16, GRM17, GRM18
                     , GRM19, GRM20, GRM21, GRM22, GRM23, GRM24, GRM25, GRM26
                     , GRM27, GRM28, GRM29, GRM30, GRM31, GRM32, GRM33, GRM34
                     , GRM35, GRM36, GRM37, GRM38, GRM39, GRM40, GRM41, GRM42
                     , GRM43, GRM44, GRM45, GRM46, GRM47, GRM48, GRM49, GRM50
                     , GRM51, GRM52, GRM53, GRM54, GRM55, GRM56, GRM57, GRM58
                     , GRM59, GRM60, GRM61
                  FROM
                    (
                  SELECT IFSEQNO
                       , NVL(NVL(D.DIVISION_ID, E.DIVISION_ID), SPART) AS DIVISION_ID
                       , SPMON AS YYYYMM, BUKRS, A.WERKS AS PLANT_ID, MATNR AS ITEM_ID
                       , CHARG, SPEMK, MEINS, PRCTR, PRODH, MATKL, BWTAR, BKLAS AS VALUATION_CLASS
                       , WAERS
                       , WAERS AS CURRENCY
                         /* [E20250423-000916] 단가 기준 변경. LNETP(Unit cost of ledger) -> CNETP(Unit cost of Total by ledger) Start */
                         /* GERP 에서는 CNETP 컬럼이 추가되지 않아서 CNETP 이 NULL로 생성 됨. CNETP이 NULL 경우에 기존 LNETP 사용 */
                       , CASE WHEN CNETP IS NULL THEN LNETP ELSE CNETP END AS UNIT_PRICE_ORG
                       , CASE
                         WHEN LPEIN <> 0
                         THEN ROUND(CASE WHEN CNETP IS NULL THEN TO_NUMBER(LNETP) ELSE TO_NUMBER(CNETP) END / LPEIN, 2)
                          END AS UNIT_PRICE
                         /* , LNETP AS UNIT_PRICE_ORG */
                         /* , CASE WHEN LPEIN <> 0 THEN ROUND(TO_NUMBER(LNETP) / LPEIN,2) END AS UNIT_PRICE */
                         /* [E20250423-000916] 단가 기준 변경. LNETP -> CNETP End */
                       , LPEIN
                       , SNETP, SPEIN, SMENG
                       , CREATE_DATE, CREATE_TIME, CREATE_USER_ID, UPDATE_DATE, UPDATE_TIME, UPDATE_USER_ID, TRANSFER_DATE, TRANSFER_TIME, TRANSFER_USER_ID, TRANSFER_FLAG
                       , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10, ATTRIBUTE11, ATTRIBUTE12, ATTRIBUTE13, ATTRIBUTE14, ATTRIBUTE15
                       , GRM01, GRM02, GRM03, GRM04, GRM05, GRM06, GRM07, GRM08, GRM09, GRM10
                       , GRM11, GRM12, GRM13, GRM14, GRM15, GRM16, GRM17, GRM18, GRM19, GRM20
                       , GRM21, GRM22, GRM23, GRM24, GRM25, GRM26, GRM27, GRM28, GRM29, GRM30
                       , GRM31, GRM32, GRM33, GRM34, GRM35, GRM36, GRM37, GRM38, GRM39, GRM40
                       , GRM41, GRM42, GRM43, GRM44, GRM45, GRM46, GRM47, GRM48, GRM49, GRM50
                       , GRM51, GRM52, GRM53, GRM54, GRM55, GRM56, GRM57, GRM58, GRM59, GRM60
                       , GRM61
                    FROM XIF_ERP_LONG_TERM_STOCK_R_SN A
                       , GT_SALTS_SEQ_NO B
                       , SUB10 D
                       , SUB9  E
                   WHERE A.WERKS = B.WERKS
                     AND A.IFSEQNO = B.SEQ_NO
                     AND A.WERKS = D.PLANT_ID(+)
                     AND A.PRCTR = E.CENTER(+)
                     AND SPMON = V_MAX_SPMON
                     /* AND SPART IS NOT NULL */
                     /* AND SPART <> '' */
                     /* AND SPART IN  (SELECT DISTINCT DIVISION_ID FROM SCM_PLANT_M_SN) ---(40,81,82) */
                     /* LOOKUP TYPE : ERP_LONGTERM_EXCEPT_VALCALSS.  제외 대상 CODE : SEGMENT1  (MSSQL NOT IN -> NOT EXISTS) */
                     AND NOT EXISTS ( SELECT 1
                                        FROM SCM_ADM_LOOKUP_MASTER_DETAIL LMD
                                       WHERE LMD.LOOKUP_TYPE = 'ERP_LONGTERM_EXCEPT_VALCALSS'
                                         AND LMD.VALID_YN = 'Y'
                                         AND LMD.SEGMENT1 = A.BKLAS
                                    )
                    ) A
                 WHERE 1 = 1
                   AND DIVISION_ID IN (SELECT DISTINCT DIVISION_ID FROM SCM_PLANT_M_SN);   /* ---(40,81,82) */
                /* -------------------------------------------------------------------------------------------------------------------------------------------------------------- */

                /* Process Group, Process Detail정보 */
                INSERT
                  INTO GT_SALTS_X_ITEM_CLASS
                     ( ITEM_ID
                     , ITEM_TYPE
                     , PROCESS_GROUP
                     , PROCESS_DETAIL
                     , LEVEL_1_NAME
                     , LEVEL_2_NAME
                     , LEVEL_3_NAME
                     , LEVEL_4_NAME )
                SELECT DISTINCT
                       B.ITEM_ID
                     , MAX(A.ITEM_TYPE) AS ITEM_TYPE
                     , MAX(A.PROCESS_GROUP) AS PROCESS_GROUP
                     , MAX(A.PROCESS_DETAIL) AS PROCESS_DETAIL
                     , MAX(A.LEVEL_1_NAME) AS LEVEL_1_NAME
                     , MAX(A.LEVEL_2_NAME) AS LEVEL_2_NAME
                     , MAX(A.LEVEL_3_NAME) AS LEVEL_3_NAME
                     , MAX(A.LEVEL_4_NAME) AS LEVEL_4_NAME
                  FROM SCM_MST_ITEM_CLASS_M A
                     , ( SELECT S.ITEM_CLASS AS CLASS_ID
                              , S.ITEM_ID
                           FROM SCM_MST_ITEM_SN S
                              , GT_SALTS_XIF    R
                          WHERE S.ITEM_ID = R.ITEM_ID
                       ) B
                 WHERE A.CLASS_ID = B.CLASS_ID(+)
                 GROUP BY B.ITEM_ID;

                INSERT
                  INTO GT_SALTS_MST_ITEM
                     ( FORECAST_INFO_CELL_MODEL
                     , NICK_NAME
                     , FORECAST_INFO_CELL_PACK_COUNT
                     , SITE_ID
                     , ITEM_NAME
                     , ITEM_UOM
                     , ITEM_ID )
                SELECT DISTINCT
                       MAX(B.FORECAST_INFO_CELL_MODEL) AS FORECAST_INFO_CELL_MODEL
                     , MAX(B.NICK_NAME) AS NICK_NAME
                     , MAX(B.FORECAST_INFO_CELL_PACK_COUNT) AS FORECAST_INFO_CELL_PACK_COUNT
                     , MAX(B.SITE_ID) AS SITE_ID
                     , MAX(B.ITEM_NAME) AS ITEM_NAME
                     , MAX(B.ITEM_UOM) AS ITEM_UOM
                     , A.ITEM_ID
                  FROM GT_SALTS_XIF A
                     , SCM_MST_ITEM_SN B
                 WHERE A.ITEM_ID = B.ITEM_ID(+)
                 GROUP BY A.ITEM_ID;

                INSERT
                  INTO GT_SALTS_XIF2
                    (                       IFSEQNO, DIVISION_ID, YYYYMM, BUKRS, PLANT_ID, ITEM_ID, CHARG, SPEMK
                    , PRCTR, PRODH, MATKL, BWTAR, VALUATION_CLASS, WAERS, CURRENCY, UNIT_PRICE_ORG
                    , UNIT_PRICE, LPEIN, SNETP, SPEIN, SMENG, CREATE_DATE, CREATE_TIME, CREATE_USER_ID
                    , UPDATE_DATE, UPDATE_TIME, UPDATE_USER_ID, TRANSFER_DATE, TRANSFER_TIME, TRANSFER_USER_ID, TRANSFER_FLAG, ATTRIBUTE1
                    , ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9
                    , ATTRIBUTE10, ATTRIBUTE11, ATTRIBUTE12, ATTRIBUTE13, ATTRIBUTE14, ATTRIBUTE15, GRM01, GRM02
                    , GRM03, GRM04, GRM05, GRM06, GRM07, GRM08, GRM09, GRM10
                    , GRM11, GRM12, GRM13, GRM14, GRM15, GRM16, GRM17, GRM18
                    , GRM19, GRM20, GRM21, GRM22, GRM23, GRM24, GRM25, GRM26
                    , GRM27, GRM28, GRM29, GRM30, GRM31, GRM32, GRM33, GRM34
                    , GRM35, GRM36, GRM37, GRM38, GRM39, GRM40, GRM41, GRM42
                    , GRM43, GRM44, GRM45, GRM46, GRM47, GRM48, GRM49, GRM50
                    , GRM51, GRM52, GRM53, GRM54, GRM55, GRM56, GRM57, GRM58
                    , GRM59, GRM60, GRM61, PROCESS_GROUP, PROCESS_DETAIL, ITEM_NAME, ITEM_UOM, FORECAST_INFO_CELL_MODEL
                    , NICK_NAME, FORECAST_INFO_CELL_PACK_COUNT )
                SELECT DISTINCT
                       A.*
                     , B.PROCESS_GROUP
                     , B.PROCESS_DETAIL
                     , C.ITEM_NAME, C.ITEM_UOM
                     , C.FORECAST_INFO_CELL_MODEL
                     , C.NICK_NAME
                     , C.FORECAST_INFO_CELL_PACK_COUNT
                  FROM GT_SALTS_XIF A
                     , GT_SALTS_X_ITEM_CLASS B
                     , GT_SALTS_MST_ITEM     C
                 WHERE A.ITEM_ID = B.ITEM_ID(+)
                   AND A.ITEM_ID = C.ITEM_ID(+);

                /* GRM01 ~ GRM61값을 UNPIVOT함 */
                INSERT
                  INTO GT_SALTS_XIF3
                    (                       IFSEQNO, DIVISION_ID, YYYYMM, BUKRS, PLANT_ID, ITEM_ID, CHARG, SPEMK
                    , PRCTR, PRODH, MATKL, BWTAR, VALUATION_CLASS, WAERS, CURRENCY, UNIT_PRICE_ORG
                    , UNIT_PRICE, LPEIN, SNETP, SPEIN, SMENG, DEVALUATION_AGE, LONG_TERM_TYPE, LONG_TERM_STOCK_QTY
                    , LONG_TERM_STOCK_AMOUNT, PROCESS_GROUP, PROCESS_DETAIL, ITEM_NAME, ITEM_UOM, FORECAST_INFO_CELL_MODEL, NICK_NAME, FORECAST_INFO_CELL_PACK_COUNT
                    , CREATE_DATE, CREATE_TIME, CREATE_USER_ID, UPDATE_DATE, UPDATE_TIME, UPDATE_USER_ID, TRANSFER_DATE, TRANSFER_TIME
                    , TRANSFER_USER_ID, TRANSFER_FLAG, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6
                    , ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10, ATTRIBUTE11, ATTRIBUTE12, ATTRIBUTE13, ATTRIBUTE14
                    , ATTRIBUTE15 )
                SELECT IFSEQNO, DIVISION_ID, YYYYMM, BUKRS, PLANT_ID, ITEM_ID, CHARG, SPEMK, PRCTR, PRODH, MATKL, BWTAR, VALUATION_CLASS
                     , WAERS, CURRENCY
                     , UNIT_PRICE_ORG, UNIT_PRICE
                     , LPEIN, SNETP, SPEIN, SMENG, DEVALUATION_AGE
                     , TO_NUMBER(REPLACE(DEVALUATION_AGE,'GRM','')) - 1 AS LONG_TERM_TYPE
                     , LONG_TERM_STOCK_QTY
                     , CASE
                       WHEN LPEIN <> 0
                       THEN TO_NUMBER(LONG_TERM_STOCK_QTY) * CAST(UNIT_PRICE_ORG AS NUMBER(20,5)) / LPEIN
                       END AS LONG_TERM_STOCK_AMOUNT
                     , PROCESS_GROUP, PROCESS_DETAIL, ITEM_NAME, ITEM_UOM , FORECAST_INFO_CELL_MODEL ,NICK_NAME ,FORECAST_INFO_CELL_PACK_COUNT
                     , CREATE_DATE, CREATE_TIME, CREATE_USER_ID, UPDATE_DATE, UPDATE_TIME, UPDATE_USER_ID
                     , TRANSFER_DATE, TRANSFER_TIME, TRANSFER_USER_ID, TRANSFER_FLAG
                     , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
                     , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10
                     , ATTRIBUTE11, ATTRIBUTE12, ATTRIBUTE13, ATTRIBUTE14, ATTRIBUTE15
                  FROM GT_SALTS_XIF2
                 UNPIVOT ( LONG_TERM_STOCK_QTY
                           FOR DEVALUATION_AGE
                           IN (
                               GRM01, GRM02, GRM03, GRM04, GRM05, GRM06, GRM07, GRM08, GRM09, GRM10
                             , GRM11, GRM12, GRM13, GRM14, GRM15, GRM16, GRM17, GRM18, GRM19, GRM20
                             , GRM21, GRM22, GRM23, GRM24, GRM25, GRM26, GRM27, GRM28, GRM29, GRM30
                             , GRM31, GRM32, GRM33, GRM34, GRM35, GRM36, GRM37, GRM38, GRM39, GRM40
                             , GRM41, GRM42, GRM43, GRM44, GRM45, GRM46, GRM47, GRM48, GRM49, GRM50
                             , GRM51, GRM52, GRM53, GRM54, GRM55, GRM56, GRM57, GRM58, GRM59, GRM60
                             , GRM61
                              )) XIF_UNPVT
                 WHERE TO_NUMBER(LONG_TERM_STOCK_QTY) > 0;   /* 2025/02/28   kimcd NUMERIC에서 FLOAT로 변경 */

                INSERT
                  INTO SCP_ANL_LONG_TERM_STOCK
                        (
                          DIVISION_ID, YYYYMM, BUKRS, PLANT_ID, ITEM_ID, CHARG, SPEMK,  PRCTR, PRODH, MATKL, BWTAR, VALUATION_CLASS
                        , WAERS, CURRENCY
                        , UNIT_PRICE_ORG, UNIT_PRICE, UNIT_PRICE_KRW
                        , LPEIN, SNETP, SPEIN, SMENG
                        , DEVALUATION_AGE, LONG_TERM_TYPE, LONG_TERM_TYPE_CODE
                        , EX_TO_BAMT
                        , LONG_TERM_STOCK_QTY
                        , LONG_TERM_STOCK_AMOUNT
                        , AMOUNT
                        , AMOUNT_KRW
                        , PROCESS_GROUP, PROCESS_DETAIL, ITEM_NAME, ITEM_UOM, GPLM_CELL_MODEL, MDM_NICK_NAME, GPLM_CELL_CONVERSION_FACTOR
                        , CREATE_DATE,   CREATE_TIME,   CREATE_USER_ID
                        , UPDATE_DATE,   UPDATE_TIME,   UPDATE_USER_ID
                        , TRANSFER_DATE, TRANSFER_TIME, TRANSFER_USER_ID, TRANSFER_FLAG
                        , ATTRIBUTE1,  ATTRIBUTE2,  ATTRIBUTE3,  ATTRIBUTE4,  ATTRIBUTE5
                        , ATTRIBUTE6,  ATTRIBUTE7,  ATTRIBUTE8,  ATTRIBUTE9,  ATTRIBUTE10
                        , ATTRIBUTE11, ATTRIBUTE12, ATTRIBUTE13, ATTRIBUTE14, ATTRIBUTE15
                        )
                SELECT A.DIVISION_ID
                     , A.YYYYMM
                     , A.BUKRS, A.PLANT_ID, A.ITEM_ID, A.CHARG, A.SPEMK,  A.PRCTR, A.PRODH, A.MATKL, A.BWTAR, A.VALUATION_CLASS
                     , A.WAERS, A.CURRENCY
                     , A.UNIT_PRICE_ORG, A.UNIT_PRICE
                     , CASE WHEN A.WAERS = 'KRW' OR B.EX_TO_BAMT = 0 THEN A.UNIT_PRICE ELSE NVL(B.EX_TO_BAMT, 1) * A.UNIT_PRICE END AS UNIT_PRICE_KRW
                       /* , CASE WHEN A.WAERS = 'KRW' OR A.EX_TO_BAMT = 0 THEN A.UNIT_PRICE ELSE ROUND(A.UNIT_PRICE,2,1) * A.EX_TO_BAMT END AS UNIT_PRICE */
                     , A.LPEIN, A.SNETP, A.SPEIN, A.SMENG
                     , CASE WHEN A.LONG_TERM_TYPE > 9
                            THEN  'GRM' || TO_CHAR(A.LONG_TERM_TYPE)
                            ELSE  'GRM0' || TO_CHAR(A.LONG_TERM_TYPE)
                             END AS DEVALUATION_AGE
                       /* [E20250310-000014] GT_SALTS_LONG_TERM_TYPE 룩업 변경. 업무 용어 변경에 따른 시스템내 표기 수정 요청 ('부실' -> '장기') Start */
                     , C.LONG_TERM_TYPE
                     , C.LONG_TERM_TYPE_CODE
                       /* CASE WHEN LONG_TERM_TYPE >= 0 AND LONG_TERM_TYPE <= 2  THEN '비대상'
                              WHEN LONG_TERM_TYPE >= 3 AND LONG_TERM_TYPE <= 5  THEN '부실 징후'
                              WHEN LONG_TERM_TYPE >= 6 THEN '부실'
                               END AS LONG_TERM_TYPE,
                         CASE WHEN LONG_TERM_TYPE >= 0 AND LONG_TERM_TYPE <= 2  THEN 'CODE_2'
                              WHEN LONG_TERM_TYPE >= 3 AND LONG_TERM_TYPE <= 5  THEN 'CODE_5'
                              WHEN LONG_TERM_TYPE >= 6 THEN  'CODE_6'
                               END AS LONG_TERM_TYPE_CODE */
                       /* [E20250310-000014] GT_SALTS_LONG_TERM_TYPE 룩업 변경. 업무 용어 변경에 따른 시스템내 표기 수정 요청 ('부실' -> '장기') End */
                     , NVL(B.EX_TO_BAMT,0) AS EX_TO_BAMT
                     , A.LONG_TERM_STOCK_QTY
                     , A.LONG_TERM_STOCK_AMOUNT AS LONG_TERM_STOCK_AMOUNT
                     , A.LONG_TERM_STOCK_AMOUNT AS AMOUNT
                     , CASE WHEN A.WAERS = 'KRW' OR B.EX_TO_BAMT = 0 THEN A.LONG_TERM_STOCK_AMOUNT ELSE B.EX_TO_BAMT * A.LONG_TERM_STOCK_AMOUNT END AS AMOUNT_KRW
                     , A.PROCESS_GROUP, A.PROCESS_DETAIL
                     , A.ITEM_NAME
                     , A.ITEM_UOM
                     , A.FORECAST_INFO_CELL_MODEL
                     , A.NICK_NAME
                     , A.FORECAST_INFO_CELL_PACK_COUNT
                     , A.CREATE_DATE,   A.CREATE_TIME,   A.CREATE_USER_ID
                     , A.UPDATE_DATE,   A.UPDATE_TIME,   A.UPDATE_USER_ID
                     , A.TRANSFER_DATE, A.TRANSFER_TIME, A.TRANSFER_USER_ID, A.TRANSFER_FLAG
                     , A.DEVALUATION_AGE AS ATTRIBUTE1, A.ATTRIBUTE2, A.ATTRIBUTE3, A.ATTRIBUTE4, A.ATTRIBUTE5
                     , A.ATTRIBUTE6, A.ATTRIBUTE7, A.ATTRIBUTE8, A.ATTRIBUTE9, A.ATTRIBUTE10
                     , A.ATTRIBUTE11, A.ATTRIBUTE12, A.ATTRIBUTE13, A.ATTRIBUTE14, A.ATTRIBUTE15
                  FROM GT_SALTS_XIF3 A
                     , GT_SALTS_XIF_ERP_EXCRATE_R_SN B
                     , GT_SALTS_LONG_TERM_TYPE       C
                 WHERE A.WAERS = B.EX_FROM_CURR_CD(+)
                   /* AND B.YYYYMM = V_MAX_SPMON */
                   /* [E20250310-000014] GT_SALTS_LONG_TERM_TYPE 룩업 변경. 업무 용어 변경에 따른 시스템내 표기 수정 요청 ('부실' -> '장기') Start */
                   AND A.LONG_TERM_TYPE >= C.GRM_MM_FROM(+)
                   AND A.LONG_TERM_TYPE <= C.GRM_MM_TO(+);
                   /* [E20250310-000014] GT_SALTS_LONG_TERM_TYPE 룩업 변경. 업무 용어 변경에 따른 시스템내 표기 수정 요청 ('부실' -> '장기') End */

                UPDATE XIF_ERP_LONG_TERM_STOCK_R_SN
                   SET TRANSFER_FLAG = 'Y'
                 WHERE TRANSFER_FLAG = 'P';

                COMMIT;
        END IF;
        /* --------------------------------------------------------------------------------------------------- */
        /*  데이터 생성 끝 */
        /* --------------------------------------------------------------------------------------------------- */

        /* --------------------------------------------------------------------------------------------------- */
        /* 임시 테이블 삭제  (GTT: 세션 종료/다음 시작 DELETE로 정리. 여기서도 정리) */
        /* --------------------------------------------------------------------------------------------------- */
        DELETE FROM GT_SALTS_XIF;
        DELETE FROM GT_SALTS_XIF2;
        DELETE FROM GT_SALTS_XIF3;
        DELETE FROM GT_SALTS_SEQ_NO;
        DELETE FROM GT_SALTS_CURR;
        DELETE FROM GT_SALTS_MST_ITEM;
        DELETE FROM GT_SALTS_X_ITEM_CLASS;
        DELETE FROM GT_SALTS_XIF_ERP_EXCRATE_R_SN;
        DELETE FROM GT_SALTS_W_RAW;
        /* [E20250310-000014] LONG_TERM_TYPE 임시테이블 삭제 */
        DELETE FROM GT_SALTS_LONG_TERM_TYPE;
        COMMIT;

    EXCEPTION
        WHEN OTHERS THEN
    /*  IF @@TRANCOUNT > 0
          BEGIN
            ROLLBACK
        END;   (원본 ROLLBACK 주석처리=부분작업 유지) */

          /* ERROR LOG */
          V_LOG_TYPE := 'ERROR';
          V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
          V_DESCRIPTION := SUBSTR('ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 500);
          D_EVENT_DATE := SYSDATE;
          PR_SCP_SYS_LOG_BATCH( P_PROGRAM_NAME  => V_PROGRAM_NAME
                               ,P_LOG_TYPE      => V_LOG_TYPE
                               ,P_LOG_COUNT     => N_LOG_COUNT
                               ,P_LOG_MESSAGE   => V_LOG_MESSAGE
                               ,P_DESCRIPTION   => V_DESCRIPTION
                               ,P_EVENT_DATE    => D_EVENT_DATE
                               ,P_USER_ID       => V_BATCH_USER
                              );

           DBMS_OUTPUT.PUT_LINE(V_LOG_MESSAGE || ' : ' || V_DESCRIPTION);

          COMMIT;    /* 원본: 에러 시 ROLLBACK 주석(부분작업/에러로그 유지) -> MSSQL 자동커밋 대응 */
          RETURN;
    END;

    /* 종료 LOG */
    V_LOG_TYPE := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';   /* [E20250423-000916] Log 양식에 맞춤 */
    V_DESCRIPTION := '[' || V_EXEC_TIME || ']';
    D_EVENT_DATE := SYSDATE;
    PR_SCP_SYS_LOG_BATCH( P_PROGRAM_NAME  => V_PROGRAM_NAME
                         ,P_LOG_TYPE      => V_LOG_TYPE
                         ,P_LOG_COUNT     => N_LOG_COUNT
                         ,P_LOG_MESSAGE   => V_LOG_MESSAGE
                         ,P_DESCRIPTION   => V_DESCRIPTION
                         ,P_EVENT_DATE    => D_EVENT_DATE
                         ,P_USER_ID       => V_BATCH_USER
                        );

    /*           BEGIN
           END; */
    RETURN;

END;

PROCEDURE PR_SCP_ANL_MAT_SUPPLY_BATCH
(
      P_SCP_PLAN_START_YYYYMMDD      IN VARCHAR2
    , P_MRP_PLAN_START_YYYYMMDD      IN VARCHAR2
)
/*
 * Program ID   : PR_SCP_ANL_MAT_SUPPLY_BATCH
 * Description  : 자재 제약 가시화 집계 => SCP_ANL_MAT_SUPPLY 에 저장
 * Program History
 *================================================================================================================================================
 *   Date       In Charge                           Description
 *================================================================================================================================================
 * 2024/01/18	chaan					V1.2.1		PJ20230692  SCM 역량 강화 위한 SCP 개선과제 이행 Phase2     - Initial release - 집계일자를 특정해서 집계하기 위해 프로시저 분리
 * 2025.08.01   hrkim								PJ20257329 최적화 Planning Input Constraint UI 개발 및 Master Validation 확산 : Cell 공정 하드코딩 변경
 * 2026.07.06  ZIONEX  [PJ202650304]  NextSCM Migration
 */
IS
    V_TEST_MODE                     VARCHAR2(1 CHAR)     := 'F';
    /* V_TEST_MODE                     VARCHAR2(1 CHAR)     := 'T'; */

    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME                  VARCHAR2(150 CHAR)   := 'PR_SCP_ANL_MAT_SUPPLY_BATCH';
    V_LOG_TYPE                      VARCHAR2(30 CHAR);       /* START/END/ERROR/... */
    N_LOG_COUNT                     NUMBER               := 0;
    V_LOG_MESSAGE                   VARCHAR2(1000 CHAR);
    V_DESCRIPTION                   VARCHAR2(500 CHAR);
    V_D_EVENT_DATE                  DATE                 := SYSDATE;

    V_ELAPSED_TIME_BEG              TIMESTAMP            := SYSTIMESTAMP;

    V_CURR_DATE                     DATE;
    V_TODAY                         VARCHAR2(8 CHAR)     := '';
    V_THIS_MONDAY                   VARCHAR2(8 CHAR)     := '';
    V_LAST_MONDAY                   VARCHAR2(8 CHAR)     := '';
    V_THIS_THURSDAY                 VARCHAR2(8 CHAR)     := '';
    V_SCP_PLAN_START_YYYYMMDD       VARCHAR2(8 CHAR)     := '';
    V_MRP_PLAN_START_YYYYMMDD       VARCHAR2(8 CHAR)     := '';
    V_MRP_PLAN_START_YYYYMMDD_PRE   VARCHAR2(8 CHAR)     := '';
    V_SCP_PLAN_LIMIT_YYYYMMDD       VARCHAR2(8 CHAR)     := '';

    V_ERR_MSG                       VARCHAR2(4000 CHAR);
BEGIN
    /* ---------------------------------------------------------------------------------------------------------------- */
    /* [PJ20257329] Cell 완성 공정 하드 코딩 변경 (임시테이블 변수) */
    DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' SCP Cell Final 공정 정보 - Cell Packaging/Assembly');
    /* ---------------------------------------------------------------------------------------------------------------- */
    DELETE FROM GT_SCP0103_SCP_CELL_FINAL_OP;

    INSERT INTO GT_SCP0103_SCP_CELL_FINAL_OP
    SELECT DISTINCT SEGMENT1 AS OPERATION_ID
      FROM SCM_ADM_LOOKUP_MASTER_DETAIL LK
     WHERE 1=1
       AND LK.LOOKUP_TYPE = 'SCP_PLAN_OPERATION'
       AND LK.SEGMENT3	  = 'A'	 /* 공정그룹 (Cell) */
       AND LK.ATTRIBUTE1  = 'Y';	 /* Final Operation */
    /* ---------------------------------------------------------------------------------------------------------------- */
    /* [PJ20257329] Cell 계획 공정 하드 코딩 변경 (임시테이블 변수) */
    DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' SCP Cell 계획 공정 정보 전체');
    /* ---------------------------------------------------------------------------------------------------------------- */
    DELETE FROM GT_SCP0103_SCP_CELL_PLAN_OP_ALL;

    INSERT INTO GT_SCP0103_SCP_CELL_PLAN_OP_ALL
    SELECT DISTINCT SEGMENT1 AS OPERATION_ID
      FROM SCM_ADM_LOOKUP_MASTER_DETAIL LK
     WHERE 1=1
       AND LK.LOOKUP_TYPE	= 'SCP_PLAN_OPERATION'
       AND LK.SEGMENT3	    = 'A'  /* 공정그룹 (Cell) */
       AND LK.VALID_YN		= 'Y';  /* SCP 계획 공정 여부 */
    /* ---------------------------------------------------------------------------------------------------------------- */

    BEGIN

        V_LOG_TYPE         := 'START';
        V_LOG_MESSAGE      := '########## Start of procedure ##########';
        V_DESCRIPTION      := '';

        IF V_TEST_MODE <> 'T' THEN
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, V_D_EVENT_DATE);
        END IF;

        V_CURR_DATE   := SYSDATE;
        V_TODAY       := TO_CHAR(V_CURR_DATE, 'YYYYMMDD');

        V_THIS_MONDAY   := TO_CHAR((V_CURR_DATE - 1) + (2 - (MOD(TRUNC(V_CURR_DATE - 1) - TRUNC(V_CURR_DATE - 1, 'IW') + 1, 7) + 1)), 'YYYYMMDD');
        V_LAST_MONDAY   := TO_CHAR(TRUNC(CASE WHEN (MOD(TRUNC(V_CURR_DATE) - TRUNC(V_CURR_DATE, 'IW') + 1, 7) + 1) = 1 THEN V_CURR_DATE - 1 ELSE V_CURR_DATE END, 'IW'), 'YYYYMMDD');
        V_THIS_THURSDAY := TO_CHAR(V_CURR_DATE + (5 - (MOD(TRUNC(V_CURR_DATE) - TRUNC(V_CURR_DATE, 'IW') + 1, 7) + 1)), 'YYYYMMDD');

        DBMS_OUTPUT.PUT_LINE('@v_this_monday : ' || V_THIS_MONDAY);
        DBMS_OUTPUT.PUT_LINE('@v_last_monday : ' || V_LAST_MONDAY);
        DBMS_OUTPUT.PUT_LINE('@v_this_thursday : ' || V_THIS_THURSDAY);
        /* return; */

        IF V_TODAY >= V_THIS_THURSDAY THEN /* 현재일자가 목요일이후면 목요일, 아니면 월요일로 @v_mrp_plan_start_yyyymmdd 설정 */

            V_MRP_PLAN_START_YYYYMMDD	:=	V_THIS_THURSDAY;

            BEGIN
                SELECT PLAN_START_YYYYMMDD
                  INTO V_SCP_PLAN_START_YYYYMMDD
                  FROM (
                            SELECT PLAN_START_YYYYMMDD
                            FROM    SCP_PLAN_VERSION_V
                            WHERE   1=1
                                AND PLAN_TYPE		='FN'
                                AND CONFIRM_FLAG	='Y'
                                AND PLAN_START_YYYYMMDD	<= V_THIS_THURSDAY
                            GROUP BY PLAN_START_YYYYMMDD
                            ORDER BY PLAN_START_YYYYMMDD DESC
                       )
                 WHERE ROWNUM = 1;
            EXCEPTION WHEN NO_DATA_FOUND THEN NULL;
            END;
        ELSE

            V_MRP_PLAN_START_YYYYMMDD	:=	V_THIS_MONDAY;

            BEGIN
                SELECT PLAN_START_YYYYMMDD
                  INTO V_SCP_PLAN_START_YYYYMMDD
                  FROM (
                            SELECT PLAN_START_YYYYMMDD
                            FROM    SCP_PLAN_VERSION_V
                            WHERE   1=1
                                AND PLAN_TYPE		='FN'
                                AND CONFIRM_FLAG	='Y'
                                AND PLAN_START_YYYYMMDD	<= V_LAST_MONDAY
                            GROUP BY PLAN_START_YYYYMMDD
                            ORDER BY PLAN_START_YYYYMMDD DESC
                       )
                 WHERE ROWNUM = 1;
            EXCEPTION WHEN NO_DATA_FOUND THEN NULL;
            END;
        END IF;

        /* 특정 날짜의 데이터를 집계 할 때는 여기서 @v_mrp_plan_start_yyyymmdd, @v_scp_plan_start_yyyymmdd 를 특정 날짜로 설정한다 */
        /* SET @v_scp_plan_start_yyyymmdd  = '20231030'; --testing */
        /* SET @v_mrp_plan_start_yyyymmdd  = '20231106'; --testing */
        /* rollback tran;return; */

        /* 파라미터가 비었으면 현재 날짜 기준으로 계획일자 구한다 */
        IF (P_SCP_PLAN_START_YYYYMMDD IS NOT NULL) AND (RTRIM(P_SCP_PLAN_START_YYYYMMDD) IS NOT NULL) THEN   /* 원본 (x <> '') : Oracle 은 ''=NULL 이라 항상 UNKNOWN -> RTRIM(x) IS NOT NULL 로 1:1 재현(CV-029) */
            V_SCP_PLAN_START_YYYYMMDD  := P_SCP_PLAN_START_YYYYMMDD;
        END IF;

        IF (P_MRP_PLAN_START_YYYYMMDD IS NOT NULL) AND (RTRIM(P_MRP_PLAN_START_YYYYMMDD) IS NOT NULL) THEN   /* 원본 (x <> '') : Oracle 은 ''=NULL 이라 항상 UNKNOWN -> RTRIM(x) IS NOT NULL 로 1:1 재현(CV-029) */
            V_MRP_PLAN_START_YYYYMMDD  := P_MRP_PLAN_START_YYYYMMDD;
        END IF;

        /* 생산계획 기간을  MRP_PLAN_START_YYYYMMDD + 365일로 제한 */
        V_SCP_PLAN_LIMIT_YYYYMMDD := TO_CHAR(TO_DATE(V_SCP_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 365, 'YYYYMMDD');

        /* mrp 계획 시작 전날(반제품 재고(BOH) 쿼리용) */
        V_MRP_PLAN_START_YYYYMMDD_PRE := TO_CHAR(TO_DATE(V_MRP_PLAN_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD');

        DBMS_OUTPUT.PUT_LINE('@v_mrp_plan_start_yyyymmdd : ' || V_MRP_PLAN_START_YYYYMMDD);
        DBMS_OUTPUT.PUT_LINE('@v_scp_plan_start_yyyymmdd : ' || V_SCP_PLAN_START_YYYYMMDD);
        DBMS_OUTPUT.PUT_LINE('@v_scp_plan_limit_yyyymmdd : ' || V_SCP_PLAN_LIMIT_YYYYMMDD);
        /* rollback tran;return; */

        DBMS_OUTPUT.PUT_LINE('DELETE dbo.SCP_ANL_MAT_SUPPLY - BEGIN');

        DELETE
        FROM    SCP_ANL_MAT_SUPPLY
        WHERE   1=1
