        DELETE FROM GT_SCP0103_SCP_TREE_RAW_TEMP;

        INSERT INTO GT_SCP0103_SCP_TREE_RAW_TEMP
        SELECT	  A.DIVISION_ID
                , A.PLANT_ID
                , A.PARENT_ITEM_ID
                , A.CHILD_ITEM_ID
                , A.PARENT_QTY
                , A.CHILD_QTY
                , A.ALT_ID
                , A.ALT_PRIORITY
                , A.ALT_RATE
                , A.ACCUMULATED_CHILD_QTY
                , A.ACC_PRIORITY
                , A.PARENT_FLOW_ID
                , A.PARENT_OPERATION_GROUP
                , A.KEY_DATE_RN
                , A.CHILD_FLOW_ID
                , A.CHILD_OPERATION_GROUP
                , A.CHILD_ITEM_CLASS
                , A.CHILD_ELEC_TYPE
                , A.PLANT_PRIORITY
                , TO_CHAR(DENSE_RANK() OVER (PARTITION BY  A.DIVISION_ID
                                                , A.PARENT_ITEM_ID
                                                , A.ALT_ID
                                    ORDER BY A.ALT_PRIORITY) - 1, 'FM000')	AS ALT_ID_PRIORITY
        FROM	(
                    SELECT	  DIVISION_ID
                            , PLANT_ID
                            , PARENT_ITEM_ID
                            , CHILD_ITEM_ID
                            , PARENT_QTY
                            , CHILD_QTY
                            , ALT_ID
                            , ALT_PRIORITY
