PROCEDURE PR_SCP_ANL_PLN_ARCHIVE_COMPRESSION
/*
 * Program ID   : PR_SCP_ANL_PLN_ARCHIVE_COMPRESSION
 * Description  :
 * OutTable     :
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2020.02.28   khj79          [C20200310-000428] Final Plan에 대하여 2년이 지난 Data는 Archive Table 보관하고, 운영 DB 삭제 요청의 건
 *                             SCP ANL ARCHIVE 테이블 COMPRESSION(압축은 테이블 생성되고 한번만 실행)
 *
 * ***  운영 반영 시
 *
 * 2026.07.06	ZIONEX		[PJ202650304] NextSCM Migration
 *
 *
 *      Oracle : ALTER TABLE <t> MOVE ONLINE ROW STORE COMPRESS ADVANCED
 *
 *        - Oracle ROW STORE COMPRESS BASIC 은 직접경로(Direct Path) 적재분만 압축하고 일반 DML 행은
 *        - Oracle ROW STORE COMPRESS ADVANCED(구 COMPRESS FOR OLTP)가 일반 DML 까지 압축하므로
 *          PAGE 압축의 기능 등가다. Advanced Compression Option 이 필요한데
 *          dev 26ai 실측 v$option 'Advanced Compression' = TRUE 로 사용 가능하다.
 *
 *        - ALTER TABLE ... ROW STORE COMPRESS ADVANCED 만 하면 "이후 신규 데이터" 에만 적용되고
 *          적용되며 전 파티션이 COMPRESS ADVANCED 로 바뀌는 것을 확인했다(user_tab_partitions
 *
 */
IS

    V_TABLE_NAME      VARCHAR2(500 CHAR);  /* 원본 테이블 명 */

    /* Dynamic Query 용 변수 설정 */
    V_SQL             VARCHAR2(4000 CHAR); /* 삭제 SQL */

    /* LOG 용 변수 설정 */
    V_BATCH_USER      VARCHAR2(150 CHAR) := 'scp_batch';
    V_PROGRAM_NAME    VARCHAR2(150 CHAR) := 'PR_SCP_ANL_PLN_ARCHIVE_COMPRESSION';
    V_LOG_TYPE        VARCHAR2(30 CHAR);   /* START/END/ERROR/... */
    N_LOG_COUNT       INTEGER := 0;
    V_LOG_MESSAGE     VARCHAR2(1000 CHAR);
    V_DESCRIPTION     VARCHAR2(500 CHAR);
    D_EVENT_DATE      DATE;


    V_TABLE_CNT       NUMBER(10);
    V_ERR_MSG         VARCHAR2(1000 CHAR);

BEGIN

    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    BEGIN
        /* 테이블 리스트 커서 */
        FOR C_TBL IN (SELECT TABLE_NAME
                        FROM USER_TABLES
                       WHERE TABLE_NAME LIKE 'SCP_ANL_%'
                         AND (TABLE_NAME LIKE '%_AR'         /* ARCHIVE 테이블 */
                           OR TABLE_NAME LIKE '%_SWITCH'     /* SWITCH 테이블 */
                             ))
        LOOP

            V_TABLE_NAME := C_TBL.TABLE_NAME;

            /* ARCHIVE 테이블 존재 유무 확인. 존재하면 압축 실행 */
            SELECT COUNT(*)
              INTO V_TABLE_CNT
              FROM USER_TABLES
             WHERE TABLE_NAME = V_TABLE_NAME;

            IF V_TABLE_CNT > 0 THEN
                V_SQL := 'ALTER TABLE ' || V_TABLE_NAME || ' MOVE ONLINE ROW STORE COMPRESS ADVANCED ';

                EXECUTE IMMEDIATE V_SQL;
            ELSE
                DBMS_OUTPUT.PUT_LINE('테이블 [' || V_TABLE_NAME || '] 테이블 이 존재하지 않습니다.');
            END IF;

        END LOOP;

    EXCEPTION
        WHEN OTHERS THEN
            V_ERR_MSG := SUBSTR(SQLERRM, 1, 1000);
            DBMS_OUTPUT.PUT_LINE('오류가 발생 되었습니다.');

            IF DBMS_TRANSACTION.LOCAL_TRANSACTION_ID IS NOT NULL THEN
                ROLLBACK;
            END IF;

            /* ERROR LOG */
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := V_ERR_MSG;
            V_DESCRIPTION := SUBSTR(V_TABLE_NAME, 1, 500);
            D_EVENT_DATE  := SYSDATE;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    END;

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

END;

PROCEDURE PR_SCP_ANL_PLN_ARCHIVE_INSERT_PURGE
/*
 * Program ID   : PR_SCP_ANL_PLN_ARCHIVE_INSERT_PURGE
 * Description  :
 * OutTable     :
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2020.03.10   khj79          [C20200310-000428] Final Plan에 대하여 2년이 지난 Data는 Archive Table 보관하고, 운영 DB 삭제 요청의 건
 *                             SCP ANL ARCHIVE 테이블 INSERT 및 원본 데이터 PURGE
 *
 * ***  운영 반영 시
 *
 * 2026.07.06	ZIONEX		[PJ202650304] NextSCM Migration
 *
 *       SET NOCOUNT ON;        (결과 집합 문구 미표출)   -> Oracle 은 rowcount 안내문 자체가 없어 불요
 *       SET ANSI_WARNINGS OFF; (경고 메시지 미표출)      -> Oracle 대응 구문 없음
 */
IS

    V_STD_YYYYMMDD    VARCHAR2(8 CHAR);    /* 106주 월요일 일자(약2년) */
    V_MIN_YYYYMMDD    VARCHAR2(8 CHAR);    /* 106주 월요일 이전 데이터 중 오랜된 날짜 */

    V_TABLE_NAME      VARCHAR2(500 CHAR);  /* 원본 테이블 명 */
    V_TABLE_ARCHIVE   VARCHAR2(500 CHAR);  /* ARCHIVE 테이블 명 */

    V_RESULT_CNT      NUMBER(10);          /* 삭제 실행 건수 */
    V_TOT_COUNT       NUMBER(10);          /* 삭제 실행 총 건수 */

    /* Dynamic Query 용 변수 설정 */
    V_SQL             VARCHAR2(4000 CHAR); /* 삭제 SQL */

    /* DB 설정 */
    X_DB_NAME         VARCHAR2(100 CHAR);

    /* LOG 용 변수 설정 */
    V_BATCH_USER      VARCHAR2(150 CHAR) := 'scp_batch';
    V_PROGRAM_NAME    VARCHAR2(150 CHAR) := 'PR_SCP_ANL_PLN_ARCHIVE_INSERT_PURGE';
    V_LOG_TYPE        VARCHAR2(30 CHAR);   /* START/END/ERROR/... */
    N_LOG_COUNT       INTEGER := 0;
    V_LOG_MESSAGE     VARCHAR2(1000 CHAR);
    V_DESCRIPTION     VARCHAR2(500 CHAR);
    D_EVENT_DATE      DATE;


    V_ARCHIVE_CNT     NUMBER(10);
    V_ERR_MSG         VARCHAR2(1000 CHAR);

BEGIN

    X_DB_NAME := SYS_CONTEXT('USERENV', 'CON_NAME');

    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := V_STD_YYYYMMDD;
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    BEGIN
        /* 총 삭제 건수 초기화 */
        V_TOT_COUNT := 0;

        /* 테이블 리스트 커서 */
        FOR C_TBL IN (SELECT TABLE_NAME
                        FROM USER_TABLES
                       WHERE 1 = 1
                         AND ( TABLE_NAME LIKE 'SCP_ANL_%' OR TABLE_NAME LIKE 'SCP_PLN_%' )
                         AND TABLE_NAME NOT LIKE '%_V%'    /* 5개 */
                         AND TABLE_NAME NOT LIKE '%_FIX%'
                         AND TABLE_NAME NOT IN ('SCP_ANL_PRODUCTION_PLAN_FIX_H', 'SCP_ANL_SHIPMENT_PLAN_FIX_H'
                                               ,'SCP_PLN_TH_ENG_STOCK_PLAN', 'SCP_PLN_TH_ENG_STOCK_PLAN'
                                               ,'SCP_ANL_TACT_TIME', 'SCP_ANL_WORKING_TIME')
                         AND TABLE_NAME NOT LIKE '%_AR'      /* ARCHIVE 테이블 제외 */
                         AND TABLE_NAME NOT LIKE '%_SWITCH'  /* SWITCH 테이블 제외 */
                       ORDER BY TABLE_NAME)
        LOOP

            V_TABLE_NAME := C_TBL.TABLE_NAME;

            /* 테이블 이름 저장 */
            V_TABLE_ARCHIVE := V_TABLE_NAME || '_AR';

            /* 삭제 날짜 설정(minimum 날짜) : 106주 전 월요일 일자 */
            V_STD_YYYYMMDD := TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7*106, 'YYYYMMDD');

            IF X_DB_NAME = 'OCGSCMD_P01' THEN
                V_STD_YYYYMMDD := '20191231';
            END IF;

            /* 원본 : EXEC sp_executesql @v_sql, N'@v_min_yyyymmdd nvarchar(max) output', @v_min_yyyymmdd OUTPUT
               -> 주석처리된 원본 라인 : AND ISNULL(ATTRIBUTE5,'N') != 'Y'   (테스트 삭제) */
            V_SQL := 'SELECT MIN(PLAN_START_YYYYMMDD)                          '
                  || '  FROM ' || V_TABLE_NAME || '                            '
                  || ' WHERE PLAN_START_YYYYMMDD <= ''' || V_STD_YYYYMMDD || ''' '
                  || '   AND PLAN_TYPE = ''FN''                                ';

            EXECUTE IMMEDIATE V_SQL INTO V_MIN_YYYYMMDD;

            /* ARCHIVE 테이블 존재 유무 확인. 존재하면 데이터 INSERT */
            SELECT COUNT(*)
              INTO V_ARCHIVE_CNT
              FROM USER_TABLES
             WHERE TABLE_NAME = V_TABLE_ARCHIVE;

            IF V_ARCHIVE_CNT > 0 THEN

                /* DATA INSERT ( 원본 테이블 => ARCHIVE 테이블) */
                V_SQL := ' INSERT /* PR_SCP_ANL_PLN_ARCHIVE_INSERT_PURGE */ INTO ' || V_TABLE_ARCHIVE
                      || '     SELECT * FROM ' || V_TABLE_NAME || '                    '
                      || '      WHERE DIVISION_ID = DIVISION_ID                        '
                      || '        AND PLAN_TYPE = ''FN''                               '
                      || '        AND PLAN_START_YYYYMMDD = ''' || V_MIN_YYYYMMDD || ''' ';

                DBMS_OUTPUT.PUT_LINE(V_SQL);
                EXECUTE IMMEDIATE V_SQL;
            END IF;

            /* 원본 테이블 삭제 */
            V_RESULT_CNT := 1;

            WHILE (V_RESULT_CNT > 0)
            LOOP
                /* 원본에 주석처리되어 있던 대체 구문(UPDATE TOP(5000) ... SET ATTRIBUTE5 = 'Y')은 */
                V_SQL := ' DELETE /* PR_SCP_ANL_PLN_ARCHIVE_INSERT_PURGE */ FROM ' || V_TABLE_NAME
                      || '  WHERE DIVISION_ID = DIVISION_ID '
                      || '    AND PLAN_TYPE = ''FN'' '
                      || '    AND PLAN_START_YYYYMMDD = ''' || V_MIN_YYYYMMDD || ''' '
                      || '    AND ROWNUM <= 10000 ';

                EXECUTE IMMEDIATE V_SQL;
                V_RESULT_CNT := SQL%ROWCOUNT;
                N_LOG_COUNT  := N_LOG_COUNT + V_RESULT_CNT; /* 총 삭제 건수(로그 저장) */
            END LOOP;

        END LOOP;

    EXCEPTION
        WHEN OTHERS THEN
            V_ERR_MSG := SUBSTR(SQLERRM, 1, 1000);
            DBMS_OUTPUT.PUT_LINE(V_ERR_MSG);

            IF DBMS_TRANSACTION.LOCAL_TRANSACTION_ID IS NOT NULL THEN
                ROLLBACK;
            END IF;

            /* ERROR LOG */
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := V_ERR_MSG;
            V_DESCRIPTION := SUBSTR(V_STD_YYYYMMDD || '::' || V_MIN_YYYYMMDD || '::' || V_TABLE_NAME || '::' || V_TABLE_ARCHIVE, 1, 500);
            D_EVENT_DATE  := SYSDATE;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    END;

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := SUBSTR(V_STD_YYYYMMDD || '::' || V_MIN_YYYYMMDD, 1, 500);
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

END;

PROCEDURE PR_SCP_ANL_PLN_ARCHIVE_SWITCH
(
    P_PARTITION_YYYY    IN VARCHAR2
)
/*
 * Program ID   : PR_SCP_ANL_PLN_ARCHIVE_SWITCH
 * Description  :
 * OutTable     :
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2020.03.02   khj79          [C20200310-000428] Final Plan에 대하여 2년이 지난 Data는 Archive Table 보관하고, 운영 DB 삭제 요청의 건
 *                             SCP ANL ARCHIVE 테이블 SWITCH
 *
 * ***  운영 반영 시
 *
 * 2026.07.06	ZIONEX		[PJ202650304] NextSCM Migration
 *
 *
 *             입력 타입이어야 하므로, ARCHIVE 테이블의 파티션 키는 문자형 연도값이다.
 *
 *  (2) 원본 : ALTER TABLE <AR> SWITCH PARTITION n TO <SWITCH> PARTITION n
 *      Oracle : ALTER TABLE <AR> EXCHANGE PARTITION FOR ('<yyyy>') WITH TABLE <SWITCH>
 *      의미 차이 : MSSQL SWITCH 는 파티션 <-> 파티션 이동이고 Oracle EXCHANGE PARTITION 은
 *      옵션 근거 : MSSQL SWITCH 는 메타데이터만 바꾸는 연산이고 정렬된(aligned) 인덱스를 요구하며
 *
 */
IS

    V_TABLE_ARCHIVE   VARCHAR2(500 CHAR);  /* ARCHIVE 테이블 명 */
    V_TABLE_SWITCH    VARCHAR2(500 CHAR);  /* SWITCH 테이블 명 */

    V_PARTITION_KEY   VARCHAR2(4 CHAR);    /* 파티션 키(원본 : partition 번호) */

    V_SQL             VARCHAR2(4000 CHAR); /* 삭제 SQL */

    /* LOG 용 변수 설정 */
    V_BATCH_USER      VARCHAR2(150 CHAR) := 'scp_batch';
    V_PROGRAM_NAME    VARCHAR2(150 CHAR) := 'PR_SCP_ANL_PLN_ARCHIVE_SWITCH_' || P_PARTITION_YYYY;
    V_LOG_TYPE        VARCHAR2(30 CHAR);   /* START/END/ERROR/... */
    N_LOG_COUNT       INTEGER := 0;
    V_LOG_MESSAGE     VARCHAR2(1000 CHAR);
    V_DESCRIPTION     VARCHAR2(500 CHAR);
    D_EVENT_DATE      DATE;


    V_SWITCH_CNT      NUMBER(10);
    V_ERR_MSG         VARCHAR2(1000 CHAR);

BEGIN

    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    BEGIN
        /* 테이블 리스트 커서 */
        FOR C_TBL IN (SELECT TABLE_NAME
                        FROM USER_TABLES
                       WHERE TABLE_NAME LIKE 'SCP_ANL_%'
                         AND TABLE_NAME LIKE '%_AR'  /* ARCHIVE 테이블 */)
        LOOP

            V_TABLE_ARCHIVE := C_TBL.TABLE_NAME;


            V_PARTITION_KEY := P_PARTITION_YYYY;

            /* SWITCH 테이블 설정 */
            V_TABLE_SWITCH := REPLACE(V_TABLE_ARCHIVE, '_AR', '_SWITCH');

            /* SWITCH 테이블 존재 유무 확인. 존재하면 데이터 이동 */
            SELECT COUNT(*)
              INTO V_SWITCH_CNT
              FROM USER_TABLES
             WHERE TABLE_NAME = V_TABLE_SWITCH;

            IF V_SWITCH_CNT > 0 THEN

                V_SQL := 'ALTER TABLE ' || V_TABLE_ARCHIVE
                      || ' EXCHANGE PARTITION FOR (''' || V_PARTITION_KEY || ''')'
                      || ' WITH TABLE ' || V_TABLE_SWITCH
                      || ' INCLUDING INDEXES WITHOUT VALIDATION';
                DBMS_OUTPUT.PUT_LINE(V_SQL);
                EXECUTE IMMEDIATE V_SQL;

                V_SQL := 'TRUNCATE TABLE ' || V_TABLE_SWITCH;
                DBMS_OUTPUT.PUT_LINE(V_SQL);

                EXECUTE IMMEDIATE V_SQL;

            ELSE
                DBMS_OUTPUT.PUT_LINE(V_TABLE_ARCHIVE);
            END IF;

        END LOOP;

    EXCEPTION
        WHEN OTHERS THEN
            V_ERR_MSG := SUBSTR(SQLERRM, 1, 1000);
            DBMS_OUTPUT.PUT_LINE('오류가 발생 되었습니다.');

            /* ERROR LOG */
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := V_ERR_MSG;
            V_DESCRIPTION := SUBSTR(P_PARTITION_YYYY || '::' || V_TABLE_ARCHIVE || '::' || V_TABLE_SWITCH || '::' || V_PARTITION_KEY, 1, 500);
            D_EVENT_DATE  := SYSDATE;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    END;

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := SUBSTR(P_PARTITION_YYYY || '::' || V_PARTITION_KEY, 1, 500);
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

END;

PROCEDURE PR_SCP_ANL_PLN_TABLE_DELETE
(
    P_DELETE_TYPE    IN VARCHAR2 DEFAULT NULL
)
/*
 * Program ID   : PR_SCP_ANL_PLN_TABLE_DELETE
 * Description  :
 * OutTable     :
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2020.02.17   khj79          SCP ANL PLN 테이블 삭제
 * 2021.01.28   KSG            C20210126-000135 SCP Table 보관정책 변경에 따른 요청의 건
 * 2021.11.04   KSG            PJ20214907 LGES SCP 계획 수립 시간 단축 및 분석 기능 강화 : 튜닝
 * 2024.11.25   KSG            NERP 대응 : 신규 Rule 적용
 * 2026.07.06   ZIONEX   [PJ202650304] NextSCM Migration
 *
 */
AS

    V_DEL_FLAG             VARCHAR2(10 CHAR) := 'TRUE';

    /* LOG 용 변수 설정 */
    V_BATCH_USER          VARCHAR2(150 CHAR) := 'scp_batch';
    V_PROGRAM_NAME        VARCHAR2(150 CHAR) := 'PR_SCP_ANL_PLN_TABLE_DELETE' || '_' || P_DELETE_TYPE;
    V_LOG_TYPE            VARCHAR2(30 CHAR); /* START/END/ERROR/... */
    N_LOG_COUNT           INTEGER := 0;
    V_LOG_MESSAGE         VARCHAR2(1000 CHAR);
    V_DESCRIPTION         VARCHAR2(500 CHAR);
    D_EVENT_DATE          DATE;

    /* Dynamic Query 용 변수 설정 */
    V_DELETESQL           VARCHAR2(4000 CHAR); /* 삭제 SQL */
    V_WHERESQL            VARCHAR2(4000 CHAR); /* 삭제 조건 SQL */
    V_SQL                 VARCHAR2(4000 CHAR); /* 삭제 SQL */
    V_ROWCOUNT            INTEGER;             /* 삭제 건수 */
    V_TOTCOUNT            INTEGER;             /* 테이블 목록 LOOP 실행 시 총 건수(LOOP 실행 여부 판단) */

    /* DELETE 대상 Table */
    V_TABLE_LIST          VARCHAR2(1000 CHAR);
    V_TABLE_NAME          VARCHAR2(200 CHAR);

    /* DELETE 대상 처리 Index */
    V_INDEX_LIST          VARCHAR2(1000 CHAR);
    V_INDEX_NAME          VARCHAR2(200 CHAR);

    /* 삭제를 날짜 정보 변수 설정 */
    V_STD_DAY  VARCHAR2(10 CHAR) := ''; /* 기준 요일 */
    V_STD_TIME VARCHAR2(10 CHAR) := ''; /* 기준 시간 */
    V_CUR_TIME VARCHAR2(10 CHAR) := ''; /* 현재 시간 */

    /* 삭제 건수 변수 설정 */
    V_DEL_CNT INTEGER := 0;

    /* 삭제 대상 Plan Type */
    V_DEL_PLAN_TYPE_ALL   VARCHAR2(100 CHAR) := ''; /* 20210128 C20210126-000135 삭제 대상 Plan Type 지정 : 전체 삭제 */
    V_DEL_PLAN_TYPE_FN    VARCHAR2(100 CHAR) := ''; /* 20210128 C20210126-000135 삭제 대상 Plan Type 지정 : FN 외 삭제 */
    V_DEL_PLAN_TYPE_FNMA  VARCHAR2(100 CHAR) := ''; /* 20210128 C20210126-000135 삭제 대상 Plan Type 지정 : FN/MA외 삭제 */
    V_DEL_PLAN_TYPE       VARCHAR2(100 CHAR) := ''; /* 아래에서 항목별 기간 재설정함 */

    /* -----------------------------------------------------------
       Delete 기준 일자 정보 셋팅
       운영 : '1'   개발 : '2'
       ----------------------------------------------------------- */
    X_DB_NAME       VARCHAR2(100 CHAR);
    /* 20210128 C20210126-000135 항목별 삭제 기간 지정 */
    V_DEL_YYYYMMDD_6M  VARCHAR2(10 CHAR) := '';  /* 6개월(26주) 기준 */
    V_DEL_YYYYMMDD_1M  VARCHAR2(10 CHAR) := '';  /* 1개월(6주) 기준 */

    V_DEL_YYYYMMDD_START  VARCHAR2(10 CHAR) := '';  /* Delete Start 기준 일자 */
    V_DEL_YYYYMMDD  VARCHAR2(10 CHAR) := '';  /* Delete 기준 일자 */

BEGIN


    X_DB_NAME := SYS_CONTEXT('USERENV', 'CON_NAME');

    /* ----------------------------------------------------------------------------
       운영 : 26주 전 월요일 일자(6개월 이전)
       20210128 C20210126-000135 항목별 삭제 기간 지정
       ---------------------------------------------------------------------------- */
    V_DEL_YYYYMMDD_6M := TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7*27, 'YYYYMMDD'); /* 26주 전 월요일 일자(약 6개월) */
    V_DEL_YYYYMMDD_1M := TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7*7, 'YYYYMMDD');  /* 6주 전 월요일 일자(약 1개월) */
    V_DEL_YYYYMMDD    := V_DEL_YYYYMMDD_6M; /* 기본 6개월(아래에서 항목별 기간 재설정함) */

    /* 개발 :  8주 전 월요일 일자 */

    IF X_DB_NAME = 'OCGSCMD_P01' THEN
        V_DEL_YYYYMMDD_6M := TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7*9, 'YYYYMMDD'); /* 8주 전 월요일 일자 */
        V_DEL_YYYYMMDD_1M := TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7*9, 'YYYYMMDD'); /* 8주 전 월요일 일자 */
        V_DEL_YYYYMMDD    := TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7*9, 'YYYYMMDD'); /* 8주 전 월요일 일자 */
    END IF;

    /* -----------------------------------------------------------
       요일별 삭제 중단 시간 정보 셋팅
       ----------------------------------------------------------- */
    /* 기준 요일 정보 셋팅 */
    V_STD_DAY := TO_CHAR(MOD(TRUNC(SYSDATE) - TRUNC(SYSDATE, 'IW') + 1, 7) + 1);

    /* 기준 시간 정보 셋팅 : 23시 종료로 처리 */
    V_STD_TIME := '230000';

    /* 목 : 18시 */
    IF V_STD_DAY = '5' THEN
        V_STD_TIME := '180000';
    END IF;
/*
    -- 화/수/목/금 : 18시
    IF @v_std_day = N'3' OR @v_std_day = N'4' OR @v_std_day = N'5' OR @v_std_day = N'6'
        SET @v_std_time = '180000';
    -- 월/토 : 23시
    ELSE IF @v_std_day = N'2' OR @v_std_day = N'7'
        SET @v_std_time = '230000';
    -- 일 : 20시
    ELSE IF @v_std_day = N'1'
        SET @v_std_time = '200000';
*/

    /* 현재 시간 정보 셋팅 */
    V_CUR_TIME := TO_CHAR(SYSDATE, 'HH24MISS');

    /* ----------------------------------------------------------------------------
       삭제 대상 Plan Type
       ---------------------------------------------------------------------------- */
    /* 20210128 C20210126-000135 삭제 대상 Plan Type 지정 : 전체 삭제 */
    SELECT LISTAGG(',' || '''' || SEGMENT1 || '''' || ' ', '') WITHIN GROUP (ORDER BY SEGMENT1)
      INTO V_DEL_PLAN_TYPE_ALL
      FROM SCM_ADM_LOOKUP_MASTER_DETAIL A
     WHERE LOOKUP_TYPE = 'PLAN_TYPE';

    /* 20210128 C20210126-000135 삭제 대상 Plan Type 지정 : FN 외 삭제 */
    SELECT LISTAGG(',' || '''' || SEGMENT1 || '''' || ' ', '') WITHIN GROUP (ORDER BY SEGMENT1)
      INTO V_DEL_PLAN_TYPE_FN
      FROM SCM_ADM_LOOKUP_MASTER_DETAIL A
     WHERE LOOKUP_TYPE = 'PLAN_TYPE'
       AND SEGMENT1   <> 'FN';

    /* 20210128 C20210126-000135 삭제 대상 Plan Type 지정 : FN/MA외 삭제 */
    SELECT LISTAGG(',' || '''' || SEGMENT1 || '''' || ' ', '') WITHIN GROUP (ORDER BY SEGMENT1)
      INTO V_DEL_PLAN_TYPE_FNMA
      FROM SCM_ADM_LOOKUP_MASTER_DETAIL A
     WHERE LOOKUP_TYPE = 'PLAN_TYPE'
       AND SEGMENT1    NOT IN ('FN', 'MA');

    V_DEL_PLAN_TYPE := SUBSTR(V_DEL_PLAN_TYPE_FN, 2, 100); /* 기본 FN 외 삭제(아래에서 항목별 기간 재설정함) */

    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := V_PROGRAM_NAME || '::' || V_CUR_TIME || '::' || V_STD_TIME || '::' || V_DEL_FLAG || '::' || V_DEL_YYYYMMDD;
    D_EVENT_DATE  := SYSTIMESTAMP;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    BEGIN
        IF ( V_CUR_TIME < V_STD_TIME AND V_DEL_FLAG = 'TRUE') THEN
            DBMS_OUTPUT.PUT_LINE('현재시간' || V_CUR_TIME || '삭제를 진행 합니다');

            WHILE (V_DEL_FLAG = 'TRUE')
            LOOP
                V_TOTCOUNT := 0; /* 테이블 목록 LOOP 실행 시 총 건수(LOOP 실행 여부 판단) */

                /* ----------------------------------------------------------------- @v_deleteSql 설정 시 Index 태울 버전만 IF 문으로 사용하게 함
                   Table과 Index 는 한 쌍으로 순서도 같게 구성해야 하며, 동일 Type에 속한 전체 Table의 Index 가 전부 있을 경우만 설정해야 함
                   운영 Index 생성 후 조정할 것
                   -----------------------------------------------------------------
                   SCP_ANL_PRODUCTION_PLAN_FIX,SCP_ANL_SHIPMENT_PLAN_FIX,SCP_ANL_TACT_TIME,SCP_ANL_WORKING_TIME : 별도 삭제 중
                   SCP_PLN_INTERFACE_SEND_H,SCP_PLN_INTERFACE_YN                                                : 별도 삭제 중
                   SCP_PLN_TH_ENG_STOCK_PLAN                                                                    : 별도 삭제 중
                   삭제 테이블 설정 (용량에 따라 그룹으로 관리) */
                IF P_DELETE_TYPE = '1' THEN
                    V_TABLE_LIST    := 'SCP_ANL_PSI_PRODUCTION';
                    V_INDEX_LIST    := 'PK_SCP_ANL_PSI_PRODUCTION'; /* 실행 할 SQL에서 Index 지정 -- 20211104  PJ20214907 사용 Index 조정 */
                    V_DEL_YYYYMMDD  := V_DEL_YYYYMMDD_6M;                     /* 20210128 C20210126-000135 항목별 삭제 기간 지정 */
                    V_DEL_YYYYMMDD_START := TO_CHAR(TO_DATE(V_DEL_YYYYMMDD, 'YYYYMMDD') - 7*10, 'YYYYMMDD');
                    V_DEL_PLAN_TYPE := SUBSTR(V_DEL_PLAN_TYPE_FN, 2, 100); /* 20210128 C20210126-000135 삭제 대상 Plan Type 지정 */
                ELSIF P_DELETE_TYPE = '2' THEN
