                    V_DEL_YYYYMMDD  := V_DEL_YYYYMMDD_1M;                      /* @v_del_yyyymmdd_6M -- 20210128 C20210126-000135 항목별 삭제 기간 지정 */
                    V_DEL_YYYYMMDD_START := TO_CHAR(TO_DATE(V_DEL_YYYYMMDD, 'YYYYMMDD') - 7*10, 'YYYYMMDD');
                    V_DEL_PLAN_TYPE := 'ALL'; /* SUBSTRING(@v_del_plan_type_ALL, 2, 100) --SUBSTRING(@v_del_plan_type_FNMA, 2, 100) -- 20210128 C20210126-000135 삭제 대상 Plan Type 지정 */
                ELSIF P_DELETE_TYPE = '3' THEN
                    V_TABLE_LIST    := 'SCP_ANL_PRODUCTION_PLAN';
                    V_INDEX_LIST    := 'IX05_SCP_ANL_PRODUCTION_PLAN'; /* 실행 할 SQL에서 Index 지정 */
                    V_DEL_YYYYMMDD  := V_DEL_YYYYMMDD_1M;
                    V_DEL_YYYYMMDD_START := TO_CHAR(TO_DATE(V_DEL_YYYYMMDD, 'YYYYMMDD') - 7*10, 'YYYYMMDD');
                    V_DEL_PLAN_TYPE := 'ALL'; /* SUBSTRING(@v_del_plan_type_ALL, 2, 100) */
                ELSIF P_DELETE_TYPE = '4' THEN
                    V_TABLE_LIST    := 'SCP_ANL_SHIPMENT_PLAN_SEMI';
                    V_INDEX_LIST    := 'IX04_SCP_ANL_SHIPMENT_PLAN_SEMI'; /* 실행 할 SQL에서 Index 지정 */
                    V_DEL_YYYYMMDD  := V_DEL_YYYYMMDD_1M;                      /* @v_del_yyyymmdd_6M -- 20210128 C20210126-000135 항목별 삭제 기간 지정 */
                    V_DEL_YYYYMMDD_START := TO_CHAR(TO_DATE(V_DEL_YYYYMMDD, 'YYYYMMDD') - 7*10, 'YYYYMMDD');
                    V_DEL_PLAN_TYPE := 'ALL'; /* SUBSTRING(@v_del_plan_type_ALL, 2, 100) --SUBSTRING(@v_del_plan_type_FNMA, 2, 100) -- 20210128 C20210126-000135 삭제 대상 Plan Type 지정 */
                ELSIF P_DELETE_TYPE = '5' THEN
