                    V_DEL_YYYYMMDD_START := TO_CHAR(TO_DATE(V_DEL_YYYYMMDD, 'YYYYMMDD') - 7*10, 'YYYYMMDD');
                    V_DEL_PLAN_TYPE := SUBSTR(V_DEL_PLAN_TYPE_FN, 2, 100); /* 20210128 C20210126-000135 삭제 대상 Plan Type 지정 */
