                    V_DEL_YYYYMMDD_START := TO_CHAR(TO_DATE(V_DEL_YYYYMMDD, 'YYYYMMDD') - 7*10, 'YYYYMMDD');
                    V_DEL_PLAN_TYPE := 'ALL'; /* SUBSTRING(@v_del_plan_type_ALL, 2, 100) -- 20210128 C20210126-000135 삭제 대상 Plan Type 지정 */
                ELSIF P_DELETE_TYPE = '8' THEN
                    V_TABLE_LIST    := 'SCP_PLN_SALES_ONHAND,SCP_PLN_SHIPMENT_PLAN_PEGGING,SCP_PLN_ALLOCATION,SCP_PLN_ELEC_DEMAND_CELL_PLAN';
                    V_INDEX_LIST    := 'IX02_SCP_PLN_SALES_ONHAND,IX04_SCP_PLN_SHIPMENT_PLAN_PEGGING,IX03_SCP_PLN_ALLOCATION,IX02_SCP_PLN_ELEC_DEMAND_CELL_PLAN'; /*  실행 할 SQL에서 Index 지정 */
                    V_DEL_YYYYMMDD  := V_DEL_YYYYMMDD_1M; /* 20210128 C20210126-000135 항목별 삭제 기간 지정 */
                    V_DEL_YYYYMMDD_START := TO_CHAR(TO_DATE(V_DEL_YYYYMMDD, 'YYYYMMDD') - 7*10, 'YYYYMMDD');
                    V_DEL_PLAN_TYPE := 'ALL'; /* SUBSTRING(@v_del_plan_type_ALL, 2, 100) -- 20210128 C20210126-000135 삭제 대상 Plan Type 지정 */
