                    V_INDEX_LIST    := 'IX01_SCP_ANL_PROBLEM_REPORT_PEGGING,IX01_SCP_ANL_PROBLEM_REPORT_DESC,IX01_SCP_ANL_PROBLEM_REPORT_DEMAND'; /* 실행 할 SQL에서 Index 지정 */
                    V_DEL_YYYYMMDD  := V_DEL_YYYYMMDD_6M; /* @v_del_yyyymmdd_1M -- 20241028 삭제 구간 변경 -- 20210128 C20210126-000135 항목별 삭제 기간 지정 */
                    V_DEL_YYYYMMDD_START := TO_CHAR(TO_DATE(V_DEL_YYYYMMDD, 'YYYYMMDD') - 7*10, 'YYYYMMDD');
                    V_DEL_PLAN_TYPE := 'ALL'; /* 20241028 Rule 변경 건 반영 */
                    /* SET @v_del_plan_type = SUBSTRING(@v_del_plan_type_FN, 2, 100) -- 20210128 C20210126-000135 삭제 대상 Plan Type 지정 */
                ELSIF P_DELETE_TYPE = 'C' THEN  /* cutoff_date 기준 삭제 */
                    V_TABLE_LIST    := 'SCP_ANL_PRODUCTION_PLAN_C,SCP_ANL_SHIPMENT_PLAN_FG_C,SCP_ANL_SHIPMENT_PLAN_SEMI_C'; /* cutoff_date 기준 삭제 */
                    V_INDEX_LIST    := 'IX02_SCP_ANL_PRODUCTION_PLAN_C,IX02_SCP_ANL_SHIPMENT_PLAN_FG_C,IX01_SCP_ANL_SHIPMENT_PLAN_SEMI_C'; /*  실행 할 SQL에서 Index 지정 */
                    V_DEL_YYYYMMDD  := V_DEL_YYYYMMDD_6M; /* 20210128 C20210126-000135 항목별 삭제 기간 지정 */
                    V_DEL_YYYYMMDD_START := TO_CHAR(TO_DATE(V_DEL_YYYYMMDD, 'YYYYMMDD') - 7*10, 'YYYYMMDD');
                    V_DEL_PLAN_TYPE := SUBSTR(V_DEL_PLAN_TYPE_FN, 2, 100); /* 20210128 C20210126-000135 삭제 대상 Plan Type 지정 */
                END IF;

                /* 테이블 리스트에 SPLIT 문자열(',') 추가 */
                V_TABLE_LIST := LTRIM(RTRIM(V_TABLE_LIST)) || ',';
                V_INDEX_LIST := LTRIM(RTRIM(V_INDEX_LIST)) || ',';

                /* TRANSACTION 시작 */

                /* 테이블 목록 수 만큼 LOOP 실행 */
                WHILE INSTR(V_TABLE_LIST, ',') <> 0
                LOOP
                    V_TABLE_NAME := SUBSTR(V_TABLE_LIST, 1, INSTR(V_TABLE_LIST, ',') - 1);
                    V_INDEX_NAME := SUBSTR(V_INDEX_LIST, 1, INSTR(V_INDEX_LIST, ',') - 1);

                    /* ----------------------------------------------------------------
                       실행 할 SQL 문장 셋팅
                       ----------------------------------------------------------------
                       한 번에 Delete할 Row 수 */
                    IF V_INDEX_NAME <> 'X' THEN /* Index 지정하는 경우 */
                        V_DELETESQL := 'DELETE /*+ INDEX(A ' || V_INDEX_NAME || ') */ /* PR_SCP_ANL_PLN_TABLE_DELETE */ FROM ' || V_TABLE_NAME
                                        || ' A ';
                    ELSE /* Index 지정 안 하는 경우 */
                        V_DELETESQL := 'DELETE /* PR_SCP_ANL_PLN_TABLE_DELETE */ FROM ' || V_TABLE_NAME || ' A ';
                    END IF;

                    /* ----------------------------------------------------------------
                       일반 GROUP : plan_start_yyyymmdd/plan_type 기준 삭제(FN 제외)
                       ---------------------------------------------------------------- */
                    IF V_DEL_PLAN_TYPE = 'ALL' THEN
                        V_WHERESQL := ' WHERE DIVISION_ID = DIVISION_ID'
                                   || '   AND PLAN_START_YYYYMMDD >= ''' || V_DEL_YYYYMMDD_START || ''' '
                                   || '   AND PLAN_START_YYYYMMDD <  ''' || V_DEL_YYYYMMDD || ''' '
                                   || '   AND ''' || V_CUR_TIME || ''' = ''' || V_CUR_TIME || ''' ';
                    ELSE
                        V_WHERESQL := ' WHERE DIVISION_ID = DIVISION_ID'
                                   || '   AND PLAN_START_YYYYMMDD >= ''' || V_DEL_YYYYMMDD_START || ''' '
                                   || '   AND PLAN_START_YYYYMMDD <  ''' || V_DEL_YYYYMMDD || ''' '
                                   || '   AND PLAN_TYPE           IN ( ' || V_DEL_PLAN_TYPE || ' ) '
                                   || '   AND ''' || V_CUR_TIME || ''' = ''' || V_CUR_TIME || ''' ';
                    END IF;

                    /* ----------------------------------------------------------------
                       GROUP C : cutoff_date 기준으로 삭제한다
                       ---------------------------------------------------------------- */
                    IF P_DELETE_TYPE = 'C' THEN
                        V_WHERESQL := ' WHERE DIVISION_ID = DIVISION_ID'
                                   || '   AND CUTOFF_DATE >= TO_DATE(''' || V_DEL_YYYYMMDD_START || ''', ''YYYYMMDD'') '
                                   || '   AND CUTOFF_DATE <  TO_DATE(''' || V_DEL_YYYYMMDD || ''', ''YYYYMMDD'') '
                                   || '   AND ''' || V_CUR_TIME || ''' = ''' || V_CUR_TIME || ''' ';
                    END IF;

                    V_SQL := V_DELETESQL || V_WHERESQL || ' AND ROWNUM <= 50000 ';

                    /* 테이블을 삭제 처리 한다. */
                    DBMS_OUTPUT.PUT_LINE(V_SQL);
                    EXECUTE IMMEDIATE V_SQL;

                    /* 삭제 건수 저장 */
                    V_ROWCOUNT := SQL%ROWCOUNT;                    /* 실행 카운트 */
                    V_TOTCOUNT := V_TOTCOUNT + V_ROWCOUNT;         /* 테이블 목록 LOOP 실행 시 총 건수(LOOP 실행 여부 판단) */
                    N_LOG_COUNT := N_LOG_COUNT + V_ROWCOUNT;       /* 총 삭제 건수(로그 저장) */

                    DBMS_OUTPUT.PUT_LINE(TO_CHAR(N_LOG_COUNT));

                    /* 현재 시간 정보 셋팅 */
                    V_CUR_TIME := TO_CHAR(SYSDATE, 'HH24MISS');

                    /* 현재 시간이 기준 시간을 초과 하면 flag 값 변경 삭제 중지 */
                    IF V_CUR_TIME >= V_STD_TIME THEN
                        V_DEL_FLAG := 'FALSE';
                        EXIT;
                    END IF;

                    /* 삭제 한 테이블을 제거하고 새롭게 리스트 저장 */
                    V_TABLE_LIST := SUBSTR(V_TABLE_LIST, INSTR(V_TABLE_LIST, ',') + 1, LENGTH(V_TABLE_LIST));
                    V_INDEX_LIST := SUBSTR(V_INDEX_LIST, INSTR(V_INDEX_LIST, ',') + 1, LENGTH(V_INDEX_LIST));

                END LOOP; /* WHILE CHARINDEX(',',@v_table_list) <> 0 */

                /* TRANSACTION 완료 */
                COMMIT;

                /* 각 @p_delete_type 마다 한 번만 실행되도록 Flag 설정함
                   SQL Agent Job : 일정에서 반복 수행하도록 설정
                     => 이전 작업이 안 긑난 경우 다음 작업 실행 안 됨, 작업 종료 후 다음 시점에 새 작업 실행됨 */
                V_DEL_FLAG := 'FALSE';

                /* 삭제 총 건수가 0 이면 LOOP 를 중지 */
                IF V_TOTCOUNT = 0 THEN
                    V_DEL_FLAG := 'FALSE';
                    EXIT;
                END IF;

            END LOOP; /* WHILE (@v_del_flag = 'TRUE') */

        ELSE
            DBMS_OUTPUT.PUT_LINE('현재시간 : ' || V_CUR_TIME || ' 삭제를 진행 할 수 없습니다');
        END IF;

    EXCEPTION
        WHEN OTHERS THEN
            IF DBMS_TRANSACTION.LOCAL_TRANSACTION_ID IS NOT NULL THEN
                ROLLBACK;
            END IF;
        /* ERROR LOG */
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := SUBSTR(V_CUR_TIME || '::' || V_STD_TIME || '::' || V_DEL_FLAG || '::' || V_DEL_YYYYMMDD || '::' || V_DELETESQL || '::' || V_WHERESQL, 1, 500); /* 'ERROR_LINE : ' + CAST(ERROR_LINE() AS nvarchar(10)); */
            D_EVENT_DATE  := SYSTIMESTAMP;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    END;

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := V_CUR_TIME || '::' || V_STD_TIME || '::' || V_DEL_FLAG || '::' || V_DEL_YYYYMMDD;
    D_EVENT_DATE  := SYSTIMESTAMP;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

END;

