                 , PLAN_START_YYYYMMDD
                 , 1 AS SEQ
                 , OPERATION_GROUP
                 , '-' AS FROM_SITE
                 , '-' AS CELL_ITEM_ID
                 , ITEM_ID
                 , 'PROD_PLAN' AS MEASURE
                 , '-' AS VALUE_TYPE
                 , '-' AS TO_PRODUCT
                 , LINE_ID
                 , 0 AS BOH_QTY
                 , '-' AS TO_SITE
                 , '-' AS INCOTERMS
