                 , A.RECEIVING_DTTM_YYYYMM AS YYYYMM
                 , NVL(SUM(NVL(A.QTY, 0)), 0) AS QTY
              FROM GT_PIS_INV A
/* 반영4/4 start */
             WHERE EXISTS (SELECT 1
