               AND (A.DESCR LIKE 'FOR%' OR A.DESCR = 'WH')
/* AND A.ITEM_ID <> 'MASS20253-A2' */
               AND A.ITEM_ID NOT IN (SELECT DISTINCT SEGMENT1
