                 , ARRIVAL_YYYYMMDD )
            SELECT A.DIVISION_ID
                 , A.ORIGIN_FROM_DIVISION_ID
                 , A.ORIGIN_TO_DIVISION_ID
                 , B.COMPANY_ID
                 , X.COMPANY_ID  AS TO_COMPANY_ID
                 , (CASE WHEN B.OSP_YN = 'Y' THEN B.LOGISTIC_PLANT_ID
                         ELSE B.PLANT_ID
                    END )        AS PLANT_ID
                 , (CASE WHEN X.SITE_TYPE = 'SALES' THEN A.TO_SITE
/* 1,2,3순위 조건 추가(2024.12.31) start */
                         WHEN (X.SITE_TYPE = 'PLANT' AND X.OSP_YN = 'N' AND
                               EXISTS (SELECT 1
                                         FROM SCM_MST_SITE SS
                                        WHERE SS.SITE_TYPE       = 'PLANT'
                                          AND SS.VALID_YN        = 'Y'
                                          AND SS.COMPANY_ID      = X.COMPANY_ID
                                          AND SS.DIVISION_ID     = X.DIVISION_ID
                                          AND SS.PLANT_ID        = X.PLANT_ID
                                          AND SS.OPERATION_GROUP = 'E')) THEN (SELECT K.PLANT_ID   /* 이부분을 그냥 x.plant_id 라고 해도 됨. */
                                                                                 FROM SCM_MST_SITE K
                                                                                WHERE K.SITE_TYPE       = 'PLANT'
                                                                                  AND K.VALID_YN        = 'Y'
                                                                                  AND K.COMPANY_ID      = X.COMPANY_ID
                                                                                  AND K.DIVISION_ID     = X.DIVISION_ID
                                                                                  AND K.PLANT_ID        = X.PLANT_ID
                                                                                  AND K.OPERATION_GROUP = 'E'
                                                                                  AND ROWNUM            = 1)
                         WHEN (X.SITE_TYPE = 'PLANT' AND X.OSP_YN = 'N'
                               AND E2.PLANT_ID IS NOT NULL)              THEN E2.PLANT_ID   /* 2025.02.12  cell/전극 plant 매핑 로직 수정 : 2순위 참조 케이스 추가 (division, company, city, country정보로 매핑) */
                         WHEN (X.SITE_TYPE = 'PLANT' AND X.OSP_YN = 'N' AND
                               EXISTS (SELECT 1
                                         FROM SCM_MST_SITE SS
                                        WHERE SS.SITE_TYPE       = 'PLANT'
                                          AND SS.VALID_YN        = 'Y'
                                          AND SS.COMPANY_ID      = X.COMPANY_ID
                                          AND SS.DIVISION_ID     = X.DIVISION_ID
                                          AND SS.OPERATION_GROUP = 'E')) THEN (SELECT K.PLANT_ID
                                                                                 FROM SCM_MST_SITE K
                                                                                WHERE K.SITE_TYPE       = 'PLANT'
                                                                                  AND K.VALID_YN        = 'Y'
                                                                                  AND K.COMPANY_ID      = X.COMPANY_ID
                                                                                  AND K.DIVISION_ID     = X.DIVISION_ID
                                                                                  AND K.OPERATION_GROUP = 'E'
                                                                                  AND ROWNUM            = 1)
                         WHEN (X.SITE_TYPE = 'PLANT' AND X.OSP_YN = 'N')
                                                                          THEN (SELECT K.PLANT_ID
                                                                                 FROM SCM_MST_SITE K
                                                                                WHERE K.SITE_TYPE       = 'PLANT'
                                                                                  AND K.VALID_YN        = 'Y'
                                                                                  AND K.COMPANY_ID      = X.COMPANY_ID
                                                                                  AND K.OPERATION_GROUP = 'E'
                                                                                  AND ROWNUM            = 1)
/* 1,2,3순위 조건 추가(2024.12.31) end */
                         WHEN (X.SITE_TYPE = 'PLANT' AND X.OSP_YN = 'Y') THEN X.LOGISTIC_PLANT_ID
                         ELSE '-'
                    END )        AS TO_PLANT_ID
                 , A.BOD_ID
                 , A.PLAN_START_YYYYMMDD
                 , 1             AS SEQ
                 , 'E'           AS OPERATION_GROUP
                 , A.FROM_SITE
                 , A.ITEM_ID
                 , (CASE WHEN X.SITE_TYPE = 'SALES' THEN A.TO_SITE
                         WHEN X.SITE_TYPE = 'PLANT' THEN X.PLANT_ID
                         ELSE '-'
                    END )        AS TO_SITE
                 , C.SSP_INCOTERMS  AS INCOTERMS
                 , A.QTY
                 , C.LT_TOTAL_SSP
                 , A.YYYYMMDD    AS DEPARTURE_YYYYMMDD


                 , TO_CHAR(TO_DATE(A.YYYYMMDD, 'YYYYMMDD') + TRUNC(C.LT_TOTAL_SSP), 'YYYYMMDD')  AS ARRIVAL_YYYYMMDD
              FROM SCP_ANL_SHIPMENT_PLAN_SEMI A
                 , SCM_MST_SITE               B
                 , SCM_MST_SITE               X
                 , SCP_MST_BOD_N_V            C
                 , GT_PISEO_ELEC_PLANT        E2   /* 2025.02.12  cell/전극 plant 매핑 로직 수정 */
             WHERE B.SCM_SITE_ID(+) = A.FROM_SITE
               AND X.SCM_SITE_ID(+) = A.TO_SITE
               AND C.BOD_ID(+)      = A.BOD_ID
               AND E2.DIVISION_ID(+) = X.DIVISION_ID
               AND E2.COMPANY_ID(+)  = X.COMPANY_ID
               AND E2.CITY(+)        = NVL(X.CITY, 'Z')
               AND E2.COUNTRY(+)     = NVL(X.COUNTRY, 'Z')
               AND E2.ELEC_PLANT_PRIORITY_2ND(+) = 1
               AND C.DIVISION_ID(+) = V_DIVISION_ID
               AND A.PLAN_START_YYYYMMDD = V_EE_PLAN_START_YYYYMMDD
               AND A.PLAN_TYPE           = V_EE_PLAN_TYPE
               AND A.SEQ                 = V_EE_PLAN_SEQ
               AND A.DIVISION_ID         = V_EE_DIVISION_ID
               AND (A.ORIGIN_FROM_DIVISION_ID = V_DIVISION_ID OR A.ORIGIN_TO_DIVISION_ID = V_DIVISION_ID)
               AND A.MEASURE             = 'SHIP_PLAN_AMEND'
               AND A.OPERATION_GROUP     = 'E'
               AND A.YYYYMMDD           <= V_HORIZON_END_YYYYMMDD;

            V_STATUS_DESC := '2.Ship. Plan(Semi) EE 520';

            INSERT
              INTO GT_PISEO_MAIN
                 ( DIVISION_ID
                 , COMPANY_ID
                 , PLANT_ID
                 , PLAN_START_YYYYMMDD
                 , SEQ
                 , OPERATION_GROUP
                 , FROM_SITE
                 , CELL_ITEM_ID
                 , ITEM_ID
                 , MEASURE
                 , VALUE_TYPE
                 , TO_PRODUCT
                 , LINE_ID
                 , BOH_QTY
                 , TO_SITE
                 , INCOTERMS
                 , SEQ_FLAG
                 , YYYYMM
                 , QTY )
            SELECT A.ORIGIN_FROM_DIVISION_ID  AS DIVISION_ID
                 , A.COMPANY_ID
                 , A.PLANT_ID
                 , A.PLAN_START_YYYYMMDD
                 , 1                          AS SEQ
                 , 'E'                        AS OPERATION_GROUP
                 , '-'                        AS FROM_SITE
                 , '-'                        AS CELL_ITEM_ID
                 , A.ITEM_ID
                 , 'SHIP_PLAN_SEMI'           AS MEASURE
                 , '-'                        AS VALUE_TYPE
                 , '-'                        AS TO_PRODUCT
                 , '-'                        AS LINE_ID
                 , 0                          AS BOH_QTY
                 , A.TO_PLANT_ID              AS TO_SITE
                 , A.INCOTERMS
                 , '520'                      AS SEQ_FLAG
                 , SUBSTR(A.ARRIVAL_YYYYMMDD, 1, 6)  AS YYYYMM
                 , NVL(SUM(NVL(A.QTY, 0)), 0)       AS QTY
              FROM GT_PISEO_CCC A
             WHERE A.COMPANY_ID             <> A.TO_COMPANY_ID
               AND A.ORIGIN_FROM_DIVISION_ID = V_DIVISION_ID   /* '81' */
               AND A.ARRIVAL_YYYYMMDD       <= V_HORIZON_END_YYYYMMDD
             GROUP BY A.ORIGIN_FROM_DIVISION_ID
                    , A.COMPANY_ID
                    , A.PLANT_ID
                    , A.PLAN_START_YYYYMMDD
                    , A.ITEM_ID
                    , A.TO_PLANT_ID
                    , A.INCOTERMS
                    , SUBSTR(A.ARRIVAL_YYYYMMDD, 1, 6);

            /* ------------------------------------------------------------------------------------------- */
            /* 5. 전극 ( N/A : 없음) */
            /*    4.Semi WH-IN */
            /* ------------------------------------------------------------------------------------------- */
            V_STATUS_DESC := '4.Semi WH-IN  EE';

            INSERT
              INTO GT_PISEO_MAIN
                 ( DIVISION_ID
                 , COMPANY_ID
                 , PLANT_ID
                 , PLAN_START_YYYYMMDD
                 , SEQ
                 , OPERATION_GROUP
                 , FROM_SITE
                 , CELL_ITEM_ID
                 , ITEM_ID
                 , MEASURE
                 , VALUE_TYPE
                 , TO_PRODUCT
                 , LINE_ID
                 , BOH_QTY
                 , TO_SITE
                 , INCOTERMS
                 , SEQ_FLAG
                 , YYYYMM
                 , QTY )
            SELECT A.ORIGIN_TO_DIVISION_ID  AS DIVISION_ID
                 , A.TO_COMPANY_ID          AS COMPANY_ID
                 , A.TO_PLANT_ID            AS PLANT_ID
                 , A.PLAN_START_YYYYMMDD
                 , 1                        AS SEQ
                 , 'E'                      AS OPERATION_GROUP
                 , '-'                      AS FROM_SITE
                 , '-'                      AS CELL_ITEM_ID
                 , A.ITEM_ID
                 , 'SEMI_WH_IN'             AS MEASURE
                 , '-'                      AS VALUE_TYPE
                 , '-'                      AS TO_PRODUCT
                 , '-'                      AS LINE_ID
                 , 0                        AS BOH_QTY
                 , '-'                      AS TO_SITE
                 , '-'                      AS INCOTERMS
                 , '540'                    AS SEQ_FLAG
                 , SUBSTR(A.ARRIVAL_YYYYMMDD, 1, 6)  AS YYYYMM
                 , NVL(SUM(NVL(A.QTY, 0)), 0)       AS QTY
              FROM GT_PISEO_CCC A
             WHERE A.COMPANY_ID           <> A.TO_COMPANY_ID
               AND A.ORIGIN_TO_DIVISION_ID = V_DIVISION_ID
               AND A.ARRIVAL_YYYYMMDD     <= V_HORIZON_END_YYYYMMDD
             GROUP BY A.ORIGIN_TO_DIVISION_ID
                    , A.TO_COMPANY_ID
                    , A.TO_PLANT_ID
                    , A.PLAN_START_YYYYMMDD
                    , A.ITEM_ID
                    , A.TO_SITE
                    , SUBSTR(A.ARRIVAL_YYYYMMDD, 1, 6);

            /* ------------------------------------------------------------------------------------------- */
            /* 5. 전극 ( N/A : 없음) */
            /*    3.IN_HOUSE_MOVING */
            /* ------------------------------------------------------------------------------------------- */
            V_STATUS_DESC := '3.IN_HOUSE_MOVING  EE';

            INSERT
              INTO GT_PISEO_MAIN
                 ( DIVISION_ID
                 , COMPANY_ID
                 , PLANT_ID
                 , PLAN_START_YYYYMMDD
                 , SEQ
                 , OPERATION_GROUP
                 , FROM_SITE
                 , CELL_ITEM_ID
                 , ITEM_ID
                 , MEASURE
                 , VALUE_TYPE
                 , TO_PRODUCT
                 , LINE_ID
                 , BOH_QTY
                 , TO_SITE
                 , INCOTERMS
                 , SEQ_FLAG
                 , YYYYMM
                 , QTY
                 , CREATED_BY
                 , CREATION_DATE
                 , LAST_UPDATED_BY
                 , LAST_UPDATE_DATE )
            SELECT A.DIVISION_ID
                 , A.COMPANY_ID
                 , A.PLANT_ID
                 , A.PLAN_START_YYYYMMDD
                 , A.SEQ
                 , A.OPERATION_GROUP
                 , A.FROM_SITE
                 , A.CELL_ITEM_ID
                 , A.ITEM_ID
                 , A.MEASURE
                 , A.VALUE_TYPE
                 , A.TO_PRODUCT
                 , A.LINE_ID
                 , A.BOH_QTY
                 , A.TO_SITE
                 , A.INCOTERMS
                 , A.SEQ_FLAG
                 , A.YYYYMM
                 , A.QTY
                 , A.CREATED_BY
                 , A.CREATION_DATE
                 , A.LAST_UPDATED_BY
                 , A.LAST_UPDATE_DATE
            /* select TOP 100 * */
              FROM SCP_ANL_PSI_INTEGRATION A
             WHERE A.PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
               AND A.SEQ                 = '1'
               AND A.DIVISION_ID         = V_DIVISION_ID
               AND A.SEQ_FLAG            = '530';

            /* ------------------------------------------------------------------------------------------- */
            /* 5. 전극 ( N/A : 없음) */
            /*    5.PROD_PLAN */
            /* ------------------------------------------------------------------------------------------- */
            V_STATUS_DESC := '5.PROD_PLAN  EE';

            INSERT
              INTO GT_PISEO_MAIN
                 ( DIVISION_ID
                 , COMPANY_ID
                 , PLANT_ID
                 , PLAN_START_YYYYMMDD
                 , SEQ
                 , OPERATION_GROUP
                 , FROM_SITE
                 , CELL_ITEM_ID
                 , ITEM_ID
                 , MEASURE
                 , VALUE_TYPE
                 , TO_PRODUCT
                 , LINE_ID
                 , BOH_QTY
                 , TO_SITE
                 , INCOTERMS
                 , SEQ_FLAG
                 , YYYYMM
                 , QTY )
            SELECT V_DIVISION_ID
                 , B.COMPANY_ID
                 , (CASE WHEN B.OSP_YN = 'Y' THEN B.LOGISTIC_PLANT_ID
                         ELSE B.PLANT_ID
                    END )                   AS PLANT_ID
                 , A.PLAN_START_YYYYMMDD
                 , 1                        AS SEQ
                 , 'E'                      AS OPERATION_GROUP
                 , '-'                      AS FROM_SITE
                 , '-'                      AS CELL_ITEM_ID
                 , A.ITEM_ID
                 , 'PROD_PLAN'              AS MEASURE
                 , '-'                      AS VALUE_TYPE
                 , '-'                      AS TO_PRODUCT
                 , A.LINE_ID
                 , 0                        AS BOH_QTY
                 , '-'                      AS TO_SITE
                 , '-'                      AS INCOTERMS
                 , '550'                    AS SEQ_FLAG
                 , SUBSTR(A.YYYYMMDD, 1, 6) AS YYYYMM
                 , NVL(SUM(NVL(A.QTY, 0)), 0)  AS QTY
              FROM SCP_ANL_PRODUCTION_PLAN A
                 , SCP_MST_FINAL_ITEM      FI
                 , SCM_MST_SITE            B
             WHERE FI.ITEM_ID    = A.ITEM_ID
               AND B.SCM_SITE_ID = A.SCM_SITE_ID
               AND FI.OPERATION_GROUP = 'E'
               AND FI.CELL_ITEM_ID NOT LIKE 'EC%'
               AND FI.DIVISION_ID = V_DIVISION_ID
               AND B.DIVISION_ID  = V_DIVISION_ID
               AND A.PLAN_START_YYYYMMDD = V_EE_PLAN_START_YYYYMMDD
               AND A.PLAN_TYPE           = V_EE_PLAN_TYPE
               AND A.SEQ                 = V_EE_PLAN_SEQ
               AND A.DIVISION_ID         = V_EE_DIVISION_ID
               AND A.MEASURE             = 'PROD_PLAN_AMEND'
               AND A.OPERATION_GROUP     = 'E'
               AND A.ORIGIN_DIVISION_ID  = V_DIVISION_ID
               AND A.YYYYMMDD           <= V_HORIZON_END_YYYYMMDD
             GROUP BY B.COMPANY_ID
                    , (CASE WHEN B.OSP_YN = 'Y' THEN B.LOGISTIC_PLANT_ID
                            ELSE B.PLANT_ID
                       END )
                    , A.PLAN_START_YYYYMMDD
                    , A.ITEM_ID
                    , A.LINE_ID
                    , SUBSTR(A.YYYYMMDD, 1, 6);

/* 소숫점 없애기 */

            UPDATE GT_PISEO_MAIN A
               SET A.BOH_QTY = ROUND(NVL(A.BOH_QTY, 0), 0)
                 , A.QTY     = ROUND(NVL(A.QTY, 0), 0);

/* 월_INVentory 생성 START */

            V_STATUS_DESC := 'INV';

            V_MIN_YYYYMM := SUBSTR(V_PLAN_START_YYYYMMDD, 1, 6);

            V_MAX_YYYYMM := SUBSTR(V_HORIZON_END_YYYYMMDD, 1, 6);

            V_PROC_YYYYMM := V_MIN_YYYYMM;


            V_PROC_YYYYMMDD := CASE WHEN V_PROC_YYYYMM IS NULL THEN NULL ELSE V_PROC_YYYYMM || '01' END;

            V_I := 0;

            WHILE (V_PROC_YYYYMM <= V_MAX_YYYYMM)
            LOOP

                EXIT WHEN V_I > 50;

                IF ( V_PROC_YYYYMM = V_MIN_YYYYMM ) THEN
                    /* 재고가 없는 경우 첫번째 월을 QTY=0 으로 생성함. */
                    INSERT
                      INTO GT_PISEO_MAIN
                         ( DIVISION_ID
                         , COMPANY_ID
                         , PLANT_ID
                         , PLAN_START_YYYYMMDD
                         , SEQ
                         , OPERATION_GROUP
                         , FROM_SITE
                         , CELL_ITEM_ID
                         , ITEM_ID
                         , MEASURE
                         , VALUE_TYPE
                         , TO_PRODUCT
                         , LINE_ID
                         , BOH_QTY
                         , TO_SITE
                         , INCOTERMS
                         , SEQ_FLAG
                         , YYYYMM
                         , QTY
                         , CREATED_BY
                         , CREATION_DATE
                         , LAST_UPDATED_BY
                         , LAST_UPDATE_DATE )
                    SELECT DISTINCT A.DIVISION_ID
                         , A.COMPANY_ID
                         , A.PLANT_ID
                         , A.PLAN_START_YYYYMMDD
                         , 1              AS SEQ   /* a.SEQ */
                         , A.OPERATION_GROUP
                         , A.FROM_SITE
                         , A.CELL_ITEM_ID
                         , A.ITEM_ID
                         , 'INV'          AS MEASURE
                         , '-'            AS VALUE_TYPE
                         , '-'            AS TO_PRODUCT
                         , '-'            AS LINE_ID
                         , 0              AS BOH_QTY
                         , '-'            AS TO_SITE
                         , '-'            AS INCOTERMS
                         , CASE WHEN A.SEQ_FLAG IS NULL THEN NULL ELSE SUBSTR(A.SEQ_FLAG, 1, 1) || '60' END  AS SEQ_FLAG
                         , V_PROC_YYYYMM  AS YYYYMM
                         , 0              AS QTY
                         , 'SCP BATCH'    AS CREATED_BY
                         , SYSDATE        AS CREATION_DATE
                         , 'SCP BATCH'    AS LAST_UPDATED_BY
                         , SYSDATE        AS LAST_UPDATE_DATE
                      FROM GT_PISEO_MAIN A
                     WHERE NOT EXISTS (SELECT 1
                                         FROM GT_PISEO_MAIN B
                                        WHERE B.DIVISION_ID         = A.DIVISION_ID
                                          AND B.COMPANY_ID          = A.COMPANY_ID
                                          AND B.PLANT_ID            = A.PLANT_ID
                                          AND B.PLAN_START_YYYYMMDD = A.PLAN_START_YYYYMMDD
                                          AND B.SEQ                 = A.SEQ
                                          AND B.OPERATION_GROUP     = A.OPERATION_GROUP
                                          /* and b.FROM_SITE = a.FROM_SITE */
                                          AND B.CELL_ITEM_ID        = A.CELL_ITEM_ID
                                          AND B.ITEM_ID             = A.ITEM_ID
                                          AND B.MEASURE             = 'INV')
                       AND A.MEASURE <> 'MKT_FCST';

                    /* 첫번째 월의 재고(QTY) 반영 */
                    UPDATE GT_PISEO_MAIN A
                       SET A.QTY = NVL((SELECT SUM(CASE WHEN B.MEASURE = 'INV'             THEN B.BOH_QTY
                                                        WHEN B.MEASURE = 'SHIP_PLAN_SEMI'  THEN B.QTY * -1
                                                        WHEN B.MEASURE = 'SHIP_PLAN_RTF'   THEN B.QTY * -1
                                                        WHEN B.MEASURE = 'IN_HOUSE_MOVING' THEN B.QTY * -1
                                                        WHEN B.MEASURE = 'SEMI_WH_IN'      THEN B.QTY
                                                        WHEN B.MEASURE = 'PROD_PLAN'       THEN B.QTY
                                                   END) QTY
                                          FROM GT_PISEO_MAIN B
                                         WHERE B.DIVISION_ID              = A.DIVISION_ID
                                           AND B.COMPANY_ID               = A.COMPANY_ID
                                           AND B.PLANT_ID                 = A.PLANT_ID
                                           AND B.PLAN_START_YYYYMMDD      = A.PLAN_START_YYYYMMDD
                                           AND B.SEQ                      = A.SEQ
                                           AND B.OPERATION_GROUP          = A.OPERATION_GROUP
                                           AND B.FROM_SITE                = A.FROM_SITE
                                           AND B.CELL_ITEM_ID             = A.CELL_ITEM_ID
                                           AND B.ITEM_ID                  = A.ITEM_ID
                                           AND SUBSTR(B.SEQ_FLAG, 1, 1)   = SUBSTR(A.SEQ_FLAG, 1, 1)
                                           AND B.YYYYMM                   = A.YYYYMM), 0)
                     WHERE A.MEASURE = 'INV'
                       AND A.YYYYMM  = V_PROC_YYYYMM;

                ELSE /* 두번째 월부터 마지막 월까지 재고 생성. */

                    INSERT
                      INTO GT_PISEO_MAIN
                         ( DIVISION_ID
                         , COMPANY_ID
                         , PLANT_ID
                         , PLAN_START_YYYYMMDD
                         , SEQ
                         , OPERATION_GROUP
                         , FROM_SITE
                         , CELL_ITEM_ID
                         , ITEM_ID
                         , MEASURE
                         , VALUE_TYPE
                         , TO_PRODUCT
                         , LINE_ID
                         , BOH_QTY
                         , TO_SITE
                         , INCOTERMS
                         , SEQ_FLAG
                         , YYYYMM
                         , QTY
                         , CREATED_BY
                         , CREATION_DATE
                         , LAST_UPDATED_BY
                         , LAST_UPDATE_DATE )
                    SELECT DISTINCT A.DIVISION_ID
                         , A.COMPANY_ID
                         , A.PLANT_ID
                         , A.PLAN_START_YYYYMMDD
                         , 1              AS SEQ   /* a.SEQ */
                         , A.OPERATION_GROUP
                         , A.FROM_SITE
                         , A.CELL_ITEM_ID
                         , A.ITEM_ID
                         , 'INV'          AS MEASURE
                         , '-'            AS VALUE_TYPE
                         , '-'            AS TO_PRODUCT
                         , '-'            AS LINE_ID
                         , A.BOH_QTY      AS BOH_QTY
                         , '-'            AS TO_SITE
                         , '-'            AS INCOTERMS
                         , CASE WHEN A.SEQ_FLAG IS NULL THEN NULL ELSE SUBSTR(A.SEQ_FLAG, 1, 1) || '60' END  AS SEQ_FLAG
                         , V_PROC_YYYYMM  AS YYYYMM
                         , NVL(A.QTY, 0) + NVL((SELECT SUM(CASE WHEN B.MEASURE = 'SHIP_PLAN_SEMI'  THEN B.QTY * -1
                                                               WHEN B.MEASURE = 'SHIP_PLAN_RTF'   THEN B.QTY * -1
                                                               WHEN B.MEASURE = 'IN_HOUSE_MOVING' THEN B.QTY * -1
                                                               WHEN B.MEASURE = 'SEMI_WH_IN'      THEN B.QTY
                                                               WHEN B.MEASURE = 'PROD_PLAN'       THEN B.QTY
                                                          END) QTY
                                                 FROM GT_PISEO_MAIN B
                                                WHERE B.DIVISION_ID            = A.DIVISION_ID
                                                  AND B.COMPANY_ID             = A.COMPANY_ID
                                                  AND B.PLANT_ID               = A.PLANT_ID
                                                  AND B.PLAN_START_YYYYMMDD    = A.PLAN_START_YYYYMMDD
                                                  AND B.SEQ                    = A.SEQ
                                                  AND B.OPERATION_GROUP        = A.OPERATION_GROUP
                                                  AND B.FROM_SITE              = A.FROM_SITE
                                                  AND B.CELL_ITEM_ID           = A.CELL_ITEM_ID
                                                  AND B.ITEM_ID                = A.ITEM_ID
                                                  AND SUBSTR(B.SEQ_FLAG, 1, 1) = SUBSTR(A.SEQ_FLAG, 1, 1)
                                                  AND B.YYYYMM                 = V_PROC_YYYYMM), 0)  AS QTY
                         , 'SCP BATCH'    AS CREATED_BY
                         , SYSDATE        AS CREATION_DATE
                         , 'SCP BATCH'    AS LAST_UPDATED_BY
                         , SYSDATE        AS LAST_UPDATE_DATE
                      FROM GT_PISEO_MAIN A
                     WHERE A.MEASURE = 'INV'
                       AND A.YYYYMM  = V_PRE_YYYYMM;
                END IF;

                V_I := V_I + 1;

                V_PROC_YYYYMMDD := TO_CHAR(ADD_MONTHS(TO_DATE(V_PROC_YYYYMMDD, 'YYYYMMDD'), 1), 'YYYYMMDD');
                V_PRE_YYYYMM    := V_PROC_YYYYMM;
                V_PROC_YYYYMM   := SUBSTR(V_PROC_YYYYMMDD, 1, 6);

            END LOOP;

            /* ------------------------------------------------------------------------------------------- */
            /* ESS 용 전극 Item 정보 삭제 처리 : 81 전극에서 ESS 전극 일부 생산 */
            /* ------------------------------------------------------------------------------------------- */
            DELETE
              FROM GT_PISEO_MAIN
             WHERE 1 = 1
               AND OPERATION_GROUP = 'E'
               AND ITEM_ID IN (SELECT DISTINCT ITEM_ID
                                 FROM SCP_MST_FINAL_ITEM
                                WHERE DIVISION_ID  = V_DIVISION_ID
                                  AND FLOW_ID      LIKE 'E2000%'
                                  AND CELL_ITEM_ID LIKE 'EC%');

    /* ------------------------------------------------------------------------------------------------------ */
    /* ------------------------------------------------------------------------------------------------------ */
    /* 2025.03.013  Begin   PJ20249548R  LGES SCP역량 강화를 위한 기준정보PSI엔진 기능개선 : 빈월 수량 0 데이터 생성 반영 */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSDATE, 'YYYY-MM-DD HH24:MI:SS".000"') || 'Begin   PJ20249548R  LGES SCP역량 강화를 위한 기준정보PSI엔진 기능개선 : 빈월 수량 0 데이터 생성 반영');
    /* ------------------------------------------------------------------------------------------------------ */

            /* ------------------------------------------------------------------------------------------------ */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSDATE, 'YYYY-MM-DD HH24:MI:SS".000"') || '빈월 0 채우기 대상 기간 정보');
            /* ------------------------------------------------------------------------------------------------ */
            V_FILL_0_TARGET_PERIOD            := -1;
            V_FILL_0_TARGET_PERIOD_END_YYYYMM := SUBSTR(V_HORIZON_END_YYYYMMDD, 1, 6);

            BEGIN
                SELECT FILL_0_TARGET_PERIOD
                     , FILL_0_TARGET_PERIOD_END_YYYYMM
                  INTO V_FILL_0_TARGET_PERIOD
                     , V_FILL_0_TARGET_PERIOD_END_YYYYMM
                  FROM (SELECT TO_NUMBER(L.SEGMENT1)  AS FILL_0_TARGET_PERIOD
                             , CASE WHEN TO_NUMBER(L.SEGMENT1) > 0
                                    THEN TO_CHAR(LAST_DAY(ADD_MONTHS(V_PLAN_START_DATE, TO_NUMBER(L.SEGMENT1) - 1)), 'YYYYMM')
                                    ELSE V_FILL_0_TARGET_PERIOD_END_YYYYMM
                               END  AS FILL_0_TARGET_PERIOD_END_YYYYMM
                          FROM SCM_ADM_LOOKUP_MASTER_DETAIL L
                         WHERE 1 = 1
                           AND L.LOOKUP_TYPE = 'INTEGRATION_PSI_FIFO_NEED_PRE_PERIOD'   /* ESS 선입선출 선점 차감 기간 (0 채우기 대상 기간 - 개월수) */
                           AND L.VALID_YN = 'Y'
                           AND NVL(L.SEGMENT1, '0') IS NOT NULL
                           AND VALIDATE_CONVERSION(L.SEGMENT1 AS NUMBER) = 1
                         ORDER BY L.LAST_UPDATE_DATE DESC)
                 WHERE ROWNUM = 1;
            EXCEPTION WHEN NO_DATA_FOUND THEN NULL;
            END;

            IF V_FILL_0_TARGET_PERIOD_END_YYYYMM > SUBSTR(V_HORIZON_END_YYYYMMDD, 1, 6) THEN
                V_FILL_0_TARGET_PERIOD_END_YYYYMM := SUBSTR(V_HORIZON_END_YYYYMMDD, 1, 6);
            END IF;

            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSDATE, 'YYYY-MM-DD HH24:MI:SS".000"') || '@V_FILL_0_TARGET_PERIOD : ' || TO_CHAR(V_FILL_0_TARGET_PERIOD));
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSDATE, 'YYYY-MM-DD HH24:MI:SS".000"') || '@V_FILL_0_TARGET_PERIOD_END_YYYYMM : ' || V_FILL_0_TARGET_PERIOD_END_YYYYMM);

            /* ------------------------------------------------------------------------------------------------ */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSDATE, 'YYYY-MM-DD HH24:MI:SS".000"') || '빈월 0 채우기 대상 기간 월 목록');
            /* ------------------------------------------------------------------------------------------------ */

            INSERT
              INTO GT_PISEO_MM_LIST
                 ( YYYYMM )
            SELECT DISTINCT B.YYYYMM
              FROM SCM_MST_BUCKET B
             WHERE 1 = 1
               AND B.YYYYMM BETWEEN V_PLAN_START_YYYYMM
                                AND V_FILL_0_TARGET_PERIOD_END_YYYYMM;

            /* ------------------------------------------------------------------------------------------------ */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSDATE, 'YYYY-MM-DD HH24:MI:SS".000"') || '빈월 0 채우기 대상 Measure');
            /* 대상 measure : PROD_PLAN , SHIP_PLAN_SEMI */
            /* ------------------------------------------------------------------------------------------------ */

            INSERT
              INTO GT_PISEO_TARGET_MM_0
                 ( DIVISION_ID
                 , COMPANY_ID
                 , PLANT_ID
                 , PLAN_START_YYYYMMDD
                 , SEQ
                 , OPERATION_GROUP
                 , FROM_SITE
                 , CELL_ITEM_ID
                 , ITEM_ID
                 , MEASURE
                 , VALUE_TYPE
                 , TO_PRODUCT
                 , LINE_ID
                 , BOH_QTY
                 , TO_SITE
                 , INCOTERMS
                 , SEQ_FLAG
                 , YYYYMM
                 , QTY
                 , ATTRIBUTE1 )
            SELECT T.DIVISION_ID
                 , T.COMPANY_ID
                 , T.PLANT_ID
                 , T.PLAN_START_YYYYMMDD
                 , T.SEQ
                 , T.OPERATION_GROUP
                 , T.FROM_SITE
                 , T.CELL_ITEM_ID
                 , T.ITEM_ID
                 , T.MEASURE
                 , T.VALUE_TYPE
                 , T.TO_PRODUCT
                 , T.LINE_ID
                 , T.BOH_QTY
                 , T.TO_SITE
                 , T.INCOTERMS
                 , T.SEQ_FLAG
                 , M.YYYYMM
                 , NVL(MAX(CASE WHEN T.YYYYMM = M.YYYYMM THEN T.QTY ELSE NULL END), 0)  AS QTY  /* 재고를 제외하고 음수가 없기 떄문에 MAX처리 문제 없음 ?! */
                 , MAX(T.ATTRIBUTE1)                                                    AS ATTRIBUTE1
              FROM GT_PISEO_MAIN     T
                 , GT_PISEO_MM_LIST  M

             WHERE 1 = 1
               AND T.MEASURE NOT IN ('SHIP_PLAN_RTF', 'MKT_FCST', 'INV')
               AND T.YYYYMM BETWEEN V_PLAN_START_YYYYMM
                                AND V_FILL_0_TARGET_PERIOD_END_YYYYMM
             GROUP BY T.DIVISION_ID
                    , T.COMPANY_ID
                    , T.PLANT_ID
                    , T.PLAN_START_YYYYMMDD
                    , T.SEQ
                    , T.OPERATION_GROUP
                    , T.FROM_SITE
                    , T.CELL_ITEM_ID
                    , T.ITEM_ID
                    , T.MEASURE
                    , T.VALUE_TYPE
                    , T.TO_PRODUCT
                    , T.LINE_ID
                    , T.BOH_QTY
                    , T.TO_SITE
                    , T.INCOTERMS
                    , T.SEQ_FLAG
                    , M.YYYYMM;

            /* ------------------------------------------------------------------------------------------------ */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSDATE, 'YYYY-MM-DD HH24:MI:SS".000"') || '빈월 0 채우기 대상 Measure - 채우기 전 데이터 삭제 (해당 기간)');
            /* ------------------------------------------------------------------------------------------------ */
            DELETE
              FROM GT_PISEO_MAIN T
             WHERE 1 = 1
               AND T.YYYYMM BETWEEN V_PLAN_START_YYYYMM
                                AND V_FILL_0_TARGET_PERIOD_END_YYYYMM
               AND T.MEASURE NOT IN ('SHIP_PLAN_RTF', 'MKT_FCST', 'INV');

            /* ------------------------------------------------------------------------------------------------ */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSDATE, 'YYYY-MM-DD HH24:MI:SS".000"') || '빈월 0 채우기 대상 Measure - 0 채운 데이터 Insert - Start ');
            /* ------------------------------------------------------------------------------------------------ */
            INSERT
              INTO GT_PISEO_MAIN
                 ( DIVISION_ID
                 , COMPANY_ID
                 , PLANT_ID
                 , PLAN_START_YYYYMMDD
                 , SEQ
                 , OPERATION_GROUP
                 , FROM_SITE
                 , CELL_ITEM_ID
                 , ITEM_ID
                 , MEASURE
                 , VALUE_TYPE
                 , TO_PRODUCT
                 , LINE_ID
                 , BOH_QTY
                 , TO_SITE
                 , INCOTERMS
                 , SEQ_FLAG
                 , YYYYMM
                 , QTY
                 , ATTRIBUTE1 )
            SELECT T.DIVISION_ID
                 , T.COMPANY_ID
                 , T.PLANT_ID
                 , T.PLAN_START_YYYYMMDD
                 , T.SEQ
                 , T.OPERATION_GROUP
                 , T.FROM_SITE
                 , T.CELL_ITEM_ID
                 , T.ITEM_ID
                 , T.MEASURE
                 , T.VALUE_TYPE
                 , T.TO_PRODUCT
                 , T.LINE_ID
                 , T.BOH_QTY
                 , T.TO_SITE
                 , T.INCOTERMS
                 , T.SEQ_FLAG
                 , T.YYYYMM
                 , T.QTY
                 , T.ATTRIBUTE1
              FROM GT_PISEO_TARGET_MM_0 T;

    /* ------------------------------------------------------------------------------------------------------ */
    /* 2025.03.013  End   PJ20249548R  LGES SCP역량 강화를 위한 기준정보PSI엔진 기능개선 : 빈월 수량 0 데이터 생성 반영 */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSDATE, 'YYYY-MM-DD HH24:MI:SS".000"') || 'End  PJ20249548R  LGES SCP역량 강화를 위한 기준정보PSI엔진 기능개선 : 빈월 수량 0 데이터 생성 반영');
    /* ------------------------------------------------------------------------------------------------------ */

            /* ------------------------------------------------------------------------------------------- */
            /* 이전 동일 수행건 삭제 후 수행내역 Insert */
            /* 삭제 & insert */
            /* ------------------------------------------------------------------------------------------- */
            V_STATUS_DESC := 'Delete';

            DELETE
              FROM SCP_ANL_PSI_INTEGRATION A
             WHERE A.PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
               AND A.DIVISION_ID         = V_DIVISION_ID
               AND A.SEQ_FLAG IN ('500', '510', '520', '540', '550', '560');

            V_STATUS_DESC := 'insert';

            INSERT
              INTO SCP_ANL_PSI_INTEGRATION
                 ( DIVISION_ID
                 , COMPANY_ID
                 , PLANT_ID
                 , PLAN_START_YYYYMMDD
                 , SEQ
                 , OPERATION_GROUP
                 , FROM_SITE
                 , CELL_ITEM_ID
                 , ITEM_ID
                 , MEASURE            /* 10 */
                 , VALUE_TYPE
                 , TO_PRODUCT
                 , LINE_ID
                 , BOH_QTY
                 , TO_SITE
                 , INCOTERMS
                 , SEQ_FLAG
                 , YYYYMM
                 , QTY
                 , CREATED_BY
                 , CREATION_DATE
                 , LAST_UPDATED_BY    /* 10 */
                 , LAST_UPDATE_DATE
                 , ATTRIBUTE1
                 , ATTRIBUTE2
                 , ATTRIBUTE3
                 , ATTRIBUTE4
                 , ATTRIBUTE5
                 , ATTRIBUTE6
                 , ATTRIBUTE7
                 , ATTRIBUTE8
                 , ATTRIBUTE9
                 , ATTRIBUTE10 )
            SELECT A.DIVISION_ID
                 , NVL(A.COMPANY_ID, '-')
                 , NVL(A.PLANT_ID, '-')
                 , A.PLAN_START_YYYYMMDD
                 , A.SEQ
                 , A.OPERATION_GROUP
                 , A.FROM_SITE
                 , A.CELL_ITEM_ID
                 , A.ITEM_ID
                 , A.MEASURE
                 , A.VALUE_TYPE
                 , A.TO_PRODUCT
                 , A.LINE_ID
                 /* ,BOH_QTY */
                 /* ,isnull(sum(isnull(BOH_QTY,0)),0) as BOH_QTY */
                 , ROUND(NVL(SUM(NVL(A.BOH_QTY, 0)), 0), 0)  AS BOH_QTY
                 , A.TO_SITE
                 , NVL(A.INCOTERMS, '-')
                 , A.SEQ_FLAG
                 , A.YYYYMM
                 /* ,QTY */
                 /* ,isnull(sum(isnull(QTY,0)),0) as QTY */
                 , ROUND(NVL(SUM(NVL(A.QTY, 0)), 0), 0)      AS QTY
                 , 'SCP BATCH'                     AS CREATED_BY
                 , SYSDATE                         AS CREATION_DATE
                 , 'SCP BATCH'                     AS LAST_UPDATED_BY
                 , SYSDATE                         AS LAST_UPDATE_DATE
                 , ''                              AS ATTRIBUTE1
                 , V_PLAN_TYPE                     AS ATTRIBUTE2   /* 2025.03.13 수정 */
                 , TO_CHAR(V_FILL_0_TARGET_PERIOD) AS ATTRIBUTE3   /* 2025.03.13 수정 */
                 , ''                              AS ATTRIBUTE4
                 , ''                              AS ATTRIBUTE5
                 , ''                              AS ATTRIBUTE6
                 , ''                              AS ATTRIBUTE7
                 , ''                              AS ATTRIBUTE8
                 , ''                              AS ATTRIBUTE9
                 , ''                              AS ATTRIBUTE10
              FROM GT_PISEO_MAIN A
             WHERE A.SEQ_FLAG IN ('500', '510', '520', '540', '550', '560')
             GROUP BY A.DIVISION_ID
                    , NVL(A.COMPANY_ID, '-')
                    , NVL(A.PLANT_ID, '-')
                    , A.PLAN_START_YYYYMMDD
                    , A.SEQ
                    , A.OPERATION_GROUP
                    , A.FROM_SITE
                    , A.CELL_ITEM_ID
                    , A.ITEM_ID
                    , A.MEASURE
                    , A.VALUE_TYPE
                    , A.TO_PRODUCT
                    , A.LINE_ID
                    , A.TO_SITE
                    , A.INCOTERMS
                    , A.SEQ_FLAG
                    , A.YYYYMM;


            DELETE
              FROM GT_PISEO_MAIN;

            DELETE
              FROM GT_PISEO_INV;

            DELETE
              FROM GT_PISEO_CCC;

            DELETE
              FROM GT_PISEO_ELEC_PLANT;


            DELETE
              FROM GT_PISEO_MM_LIST;

            DELETE
              FROM GT_PISEO_TARGET_MM_0;

            /* TXN LOG */
            V_LOG_TYPE    := 'TXN';

            N_LOG_COUNT   := 1;
            V_LOG_MESSAGE := 'INSERT INTO ' || V_TABLE_ID;
            D_EVENT_DATE  := SYSDATE;
            V_DESCRIPTION := 'Process Complete...' || ':' || TO_CHAR(D_EVENT_DATE, 'YYYYMMDD') || ':' || V_DIVISION_ID;

            PR_SCP_SYS_LOG_BATCH( P_PROGRAM_NAME => V_PROGRAM_NAME
                                , P_LOG_TYPE     => V_LOG_TYPE
                                , P_LOG_COUNT    => N_LOG_COUNT
                                , P_LOG_MESSAGE  => V_LOG_MESSAGE
                                , P_DESCRIPTION  => V_DESCRIPTION
                                , P_EVENT_DATE   => D_EVENT_DATE
                                , P_USER_ID      => V_BATCH_USER
                                );

            /* ★무TRAN + 최상위 스케줄 배치(master/JOB_차수선정_마스터.csv: JOB.PR_SCP_ANL_PSI_INTEGRATION_40_EE = 프로시저 PR_SCP_ANL_PSI_INTEGRATION_SMALL_ELEC_ONLY 실행) */


            COMMIT;

        END;
    EXCEPTION
        WHEN OTHERS THEN


            ROLLBACK;
            V_JJGV_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            DBMS_OUTPUT.PUT_LINE('ERROR JJG-Catch');
            DBMS_OUTPUT.PUT_LINE(V_JJGV_LOG_MESSAGE);

            /* ERROR LOG */
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := SUBSTR(V_STATUS_DESC || '  ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 500);
            D_EVENT_DATE  := SYSDATE;
            PR_SCP_SYS_LOG_BATCH( P_PROGRAM_NAME => V_PROGRAM_NAME
                                , P_LOG_TYPE     => V_LOG_TYPE
                                , P_LOG_COUNT    => N_LOG_COUNT
                                , P_LOG_MESSAGE  => V_LOG_MESSAGE
                                , P_DESCRIPTION  => V_DESCRIPTION
                                , P_EVENT_DATE   => D_EVENT_DATE
                                , P_USER_ID      => V_BATCH_USER
                                );
            RETURN;
    END;

    /* 임시 운영반영시에 주석처리 할것. */

    V_EXEC_TIME := CASE WHEN LENGTH(TO_CHAR(TRUNC(ROUND((SYSDATE - V_START_TIME) * 86400) / 60))) > 2 THEN NULL
                        ELSE LPAD(TO_CHAR(TRUNC(ROUND((SYSDATE - V_START_TIME) * 86400) / 60)), 2, '0') || ':' ||
                             LPAD(TO_CHAR(MOD(ROUND((SYSDATE - V_START_TIME) * 86400), 60)), 2, '0')
                   END;

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';

    V_DESCRIPTION := CASE WHEN V_PLAN_START_YYYYMMDD IS NULL OR V_EXEC_TIME IS NULL THEN NULL
                          ELSE '[' || V_DIVISION_ID || '][' || V_PLAN_START_YYYYMMDD || '][' || V_EXEC_TIME || ']'
                     END;
    V_DESCRIPTION := CASE WHEN V_PLAN_START_YYYYMMDD IS NULL OR V_EXEC_TIME IS NULL THEN NULL
                          ELSE '[' || V_STATUS_DESC || '][' || V_PLAN_START_YYYYMMDD || '][' || V_EXEC_TIME || ']'
                     END;
    D_EVENT_DATE  := SYSDATE;

    PR_SCP_SYS_LOG_BATCH( P_PROGRAM_NAME => V_PROGRAM_NAME
                        , P_LOG_TYPE     => V_LOG_TYPE
                        , P_LOG_COUNT    => N_LOG_COUNT
                        , P_LOG_MESSAGE  => V_LOG_MESSAGE
                        , P_DESCRIPTION  => V_DESCRIPTION
                        , P_EVENT_DATE   => D_EVENT_DATE
                        , P_USER_ID      => V_BATCH_USER
                        );
    RETURN;

END;

PROCEDURE PR_SCP_ANL_SHIPMENT_PLAN_FG_CUT_HIST
/*
 * Program ID   : PR_SCP_ANL_SHIPMENT_PLAN_FG_CUT_HIST
 * Description  : 매주 해당 주차 정보 HIST_SCP_ANL_SHIPMENT_PLAN_FG 로 이관
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2021.05.27   KSG            Initial Release PJ20209642 Digital SCM Level.3 달성을 위한 개선
 * 2026.07.06   ZIONEX   [PJ202650304] NextSCM Migration
 */
AS

    N_HISTORY_SEQ    NUMBER;

    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME   VARCHAR2(150 CHAR) := 'PR_SCP_ANL_SHIPMENT_PLAN_FG_CUT_HIST';
    V_LOG_TYPE       VARCHAR2(30 CHAR); /* START/END/ERROR/... */
    N_LOG_COUNT      NUMBER := 0;
    V_LOG_MESSAGE    VARCHAR2(1000 CHAR);
    V_DESCRIPTION    VARCHAR2(500 CHAR);
    D_EVENT_DATE     DATE;
    V_PLAN_NAME      VARCHAR2(500 CHAR);

BEGIN


    /* 시작 LOG (START) */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    V_LOG_MESSAGE := NULL;   /* 변수 재사용을 위하여 초기화해야함 */

    /* 트랜잭션 (START) */
    BEGIN

        /* 1. Division별 MAX(plan_seq) */
        /* 금주 월요일 */
        V_PLAN_NAME := TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7, 'YYYYMMDD');

        INSERT INTO HIST_SCP_ANL_SHIPMENT_PLAN_FG
            ( DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, SEQ, BIZ_TYPE, PROJECT_CODE, ITEM_ID
             , TO_SITE, INCOTERMS, FROM_SITE, BOD_ID, MEASURE, YYYYMMDD, QTY, ORIGIN_FROM_DIVISION_ID, ORIGIN_TO_DIVISION_ID, ELECTRODE_TYPE
             , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
             , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
             , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10
            )
        SELECT A.DIVISION_ID
             , A.PLAN_START_YYYYMMDD
             , A.PLAN_TYPE
             , A.SEQ
             , A.BIZ_TYPE
             , A.PROJECT_CODE
             , A.ITEM_ID
             , A.TO_SITE
             , A.INCOTERMS
             , A.FROM_SITE
             , A.BOD_ID
             , A.MEASURE
             , A.YYYYMMDD
             , A.QTY
             , A.ORIGIN_FROM_DIVISION_ID
             , A.ORIGIN_TO_DIVISION_ID
             , A.ELECTRODE_TYPE
             , A.CREATED_BY
             , A.CREATION_DATE
             , A.LAST_UPDATED_BY
             , A.LAST_UPDATE_DATE
             , A.ATTRIBUTE1
             , A.ATTRIBUTE2
             , A.ATTRIBUTE3
             , A.ATTRIBUTE4
             , A.ATTRIBUTE5
             , A.ATTRIBUTE6
             , A.ATTRIBUTE7
             , A.ATTRIBUTE8
             , A.ATTRIBUTE9
             , A.ATTRIBUTE10
        FROM   SCP_ANL_SHIPMENT_PLAN_FG A
             , (SELECT DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, MAX(PLAN_SEQ) AS SEQ
                FROM   SCP_PLAN_VERSION_V
                WHERE  PLAN_START_YYYYMMDD = V_PLAN_NAME
                AND    CONFIRM_FLAG        = 'Y'
                GROUP BY DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE) B
        WHERE  1=1
        AND    A.DIVISION_ID         = B.DIVISION_ID
        AND    A.PLAN_START_YYYYMMDD = B.PLAN_START_YYYYMMDD
        AND    A.PLAN_TYPE           = B.PLAN_TYPE
        AND    A.SEQ                 = B.SEQ;

        N_LOG_COUNT := SQL%ROWCOUNT;

        /* 트랜잭션 (COMMIT) */
        COMMIT;

    EXCEPTION
        WHEN OTHERS THEN
            /* ROLLBACK / ERROR LOG VALUE SAVE */
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := 'ERROR_LINE : ' || V_PLAN_NAME || ' : ';
            D_EVENT_DATE  := SYSDATE;

            /* 트랜잭션 (END) */
            ROLLBACK;

            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    END;

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := V_PLAN_NAME;
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

END;

PROCEDURE PR_SCP_ANL_SHIPMENT_PLAN_FIX_DEL
/* (      @p_division_id          NVARCHAR(30)      ) */
/* ============================================================
 * Program ID   : PR_SCP_ANL_SHIPMENT_PLAN_FIX_DEL
 * Description  : 매주 Pre Plan 수행 전 시점에 Shipment Plan FIX 정보 삭제
 *                - 자동차사업부 / To Site가 SALES인 FG향 정보 대상
 * OutTable     : SCP_ANL_SHIPMENT_PLAN_FIX
 * Execute      : EXEC PR_SCP_ANL_SHIPMENT_PLAN_FIX_DEL
 * Program History
 *------------------------------------------------------------
 *   Date       In Charge      Description
 *------------------------------------------------------------
 * 2019.05.21   KSG           Initial Release [CSR ID:3997268]GSCM Shipment Plan Fix 기능 관련 변경 요청 | [요청번호]C20190520_97268
 * 2021.10.14   KSG           ESS 사업부 추가
 * 2025.05.19   kimcd         E20250429-000386  81 자동차 Division 갱신 로직 주석 처리
 * 2026.07.06   ZIONEX        [PJ202650304] NextSCM Migration
 * ============================================================ */
AS
    /* LOG 용 변수 설정 */
    V_BATCH_USER    VARCHAR2(150 CHAR) := 'scp_batch';
    V_PROGRAM_NAME  VARCHAR2(150 CHAR) := 'PR_SCP_ANL_SHIPMENT_PLAN_FIX_DEL';
    V_LOG_TYPE      VARCHAR2(30 CHAR);          /* START/END/ERROR/... */
    N_LOG_COUNT     INTEGER := 0;
    V_LOG_MESSAGE   VARCHAR2(1000 CHAR);
    V_DESCRIPTION   VARCHAR2(500 CHAR);
    V_TABLE_ID      VARCHAR2(150 CHAR) := 'SCP_ANL_SHIPMENT_PLAN_FIX';
    D_EVENT_DATE    DATE;
    V_ERR           VARCHAR2(1000 CHAR);
BEGIN


    /* 시작 LOG */
    V_LOG_TYPE     := 'START';
    V_LOG_MESSAGE  := '########## Start of procedure ##########';
    V_DESCRIPTION  := V_PROGRAM_NAME || ':' || ' SCP_ANL_SHIPMENT_PLAN_FIX DELETE LOGIC';
    D_EVENT_DATE   := SYSDATE;
    PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER);

    BEGIN
        /* BEGIN TRAN TX_FG */
        /* -----------------------------------------------------------------------------------------------------------
           1. 자동차사업부(81) / FG향(To Site = 'SALES') FIX 정보 삭제
           -----------------------------------------------------------------------------------------------------------
           2025.05.19   kimcd         E20250429-000386  81 자동차 Division 갱신 로직 주석 처리 시작
           --DELETE scp_anl_shipment_plan_fix

          UPDATE scp_anl_shipment_plan_fix
          SET    yyyymmdd         = '20011231'      -- Plan에사용되지 않는 과거 시점
               , last_updated_by  = 'Weekly Delete' -- 구분자
               , last_update_date = GETDATE()
          WHERE  division_id = '81'
          AND    to_site IN (SELECT scm_site_id
                             FROM   scm_mst_site with(nolock)
                             WHERE  division_id = '81'
                             AND    site_type   = 'SALES'
                            )
          ;

        TXN LOG
        SET @n_log_count    = @@ROWCOUNT;
        SET @v_log_type     = N'TXN';
        SET @v_log_message  = N'UPDATE  '+@v_table_id;
        SET @d_event_date   = SYSDATETIME();
        SET @v_description  = N'1. 81 ' + ':' + CONVERT(CHAR(8), @d_event_date, 112);

        EXEC PR_SCP_SYS_LOG_BATCH  @p_program_name  = @v_program_name
                                  ,@p_log_type      = @v_log_type
                                  ,@p_log_count     = @n_log_count
                                  ,@p_log_message   = @v_log_message
                                  ,@p_description   = @v_description
                                  ,@p_event_date    = @d_event_date
                                  ,@p_user_id       = @v_batch_user
                                  ;
           2025.05.19   kimcd         E20250429-000386  81 자동차 Division 갱신 로직 주석 처리 종료 */

        /* -----------------------------------------------------------------------------------------------------------
           2. ESS 사업부(82) / FG향(To Site = 'SALES') FIX 정보 삭제
           -----------------------------------------------------------------------------------------------------------
           --DELETE scp_anl_shipment_plan_fix */
        UPDATE SCP_ANL_SHIPMENT_PLAN_FIX
        SET    YYYYMMDD         = '20011231'       /* Plan에사용되지 않는 과거 시점 */
             , LAST_UPDATED_BY  = 'Weekly Delete'  /* 구분자 */
             , LAST_UPDATE_DATE = SYSDATE
        WHERE  DIVISION_ID = '82'
        AND    TO_SITE IN (SELECT SCM_SITE_ID
                           FROM   SCM_MST_SITE
                           WHERE  DIVISION_ID = '82'
                           AND    SITE_TYPE   = 'SALES'
                          )
        ;

        /* TXN LOG */
        N_LOG_COUNT    := SQL%ROWCOUNT;
        V_LOG_TYPE     := 'TXN';
        V_LOG_MESSAGE  := 'UPDATE  ' || V_TABLE_ID;
        D_EVENT_DATE   := SYSDATE;
        V_DESCRIPTION  := '2. 82 ' || ':' || TO_CHAR(D_EVENT_DATE, 'YYYYMMDD');

        PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER);
        /* -----------------------------------------------------------
           실행 Logic END --
           -----------------------------------------------------------
           IF @@TRANCOUNT > 0
             BEGIN
               COMMIT TRAN TX_FG;
             END; */

    EXCEPTION
        WHEN OTHERS THEN

            ROLLBACK;
            /* ERROR LOG */
            V_ERR          := SUBSTR(SQLERRM, 1, 1000);
            V_LOG_TYPE     := 'ERROR';
            V_LOG_MESSAGE  := V_ERR;
            V_DESCRIPTION  := 'ERROR_LINE : ' || SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 460);
            D_EVENT_DATE   := SYSDATE;
            PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER);
            RETURN;
    END;

    /* 종료 LOG */
    V_LOG_TYPE     := 'END';
    V_LOG_MESSAGE  := '########## END of procedure ##########';
    V_DESCRIPTION  := '';
    D_EVENT_DATE   := SYSDATE;
    PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER);

    /* [2026-07-23 결정] 무TRAN 최상위 스케줄 배치 -> As-Is 자동커밋 등가 COMMIT */
    COMMIT;

END;

PROCEDURE PR_SCP_ANL_SHIPMENT_PLAN_SEMI_CUT_HIST
/*
 * Program ID   : PR_SCP_ANL_SHIPMENT_PLAN_SEMI_CUT_HIST
 * Description  : 매주 해당 주차 정보 HIST_SCP_ANL_SHIPMENT_PLAN_SEMI 로 이관
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2021.07.23   KSG            Initial Release PJ20209643 Digital SCM Level.3 달성을 위한 개선(Phase 2)
 * 2026.07.06   ZIONEX   [PJ202650304] NextSCM Migration
 */
AS

    N_HISTORY_SEQ    NUMBER;

    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME   VARCHAR2(150 CHAR) := 'PR_SCP_ANL_SHIPMENT_PLAN_SEMI_CUT_HIST';
    V_LOG_TYPE       VARCHAR2(30 CHAR); /* START/END/ERROR/... */
    N_LOG_COUNT      NUMBER := 0;
    V_LOG_MESSAGE    VARCHAR2(1000 CHAR);
    V_DESCRIPTION    VARCHAR2(500 CHAR);
    D_EVENT_DATE     DATE;
    V_PLAN_NAME      VARCHAR2(500 CHAR);

BEGIN


    /* 시작 LOG (START) */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    V_LOG_MESSAGE := NULL;   /* 변수 재사용을 위하여 초기화해야함 */

    /* 트랜잭션 (START) */
    BEGIN

        /* 1. Division별 MAX(plan_seq) */
        /* 금주 월요일 */
        V_PLAN_NAME := TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7, 'YYYYMMDD');

        INSERT INTO HIST_SCP_ANL_SHIPMENT_PLAN_SEMI
            ( DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, SEQ, OPERATION_GROUP, ITEM_ID
             , FROM_SITE, BOD_ID, MEASURE, YYYYMMDD, TO_SITE, QTY
             , ORIGIN_FROM_DIVISION_ID, ORIGIN_TO_DIVISION_ID, ELECTRODE_TYPE
             , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
             , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
             , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10
            )
        SELECT A.DIVISION_ID
             , A.PLAN_START_YYYYMMDD
             , A.PLAN_TYPE
             , A.SEQ
             , A.OPERATION_GROUP
             , A.ITEM_ID
             , A.FROM_SITE
             , A.BOD_ID
             , A.MEASURE
             , A.YYYYMMDD
             , A.TO_SITE
             , A.QTY
             , A.ORIGIN_FROM_DIVISION_ID
             , A.ORIGIN_TO_DIVISION_ID
             , A.ELECTRODE_TYPE
             , A.CREATED_BY
             , A.CREATION_DATE
             , A.LAST_UPDATED_BY
             , A.LAST_UPDATE_DATE
             , A.ATTRIBUTE1
             , A.ATTRIBUTE2
             , A.ATTRIBUTE3
             , A.ATTRIBUTE4
             , A.ATTRIBUTE5
             , A.ATTRIBUTE6
             , A.ATTRIBUTE7
             , A.ATTRIBUTE8
             , A.ATTRIBUTE9
             , A.ATTRIBUTE10
        FROM   SCP_ANL_SHIPMENT_PLAN_SEMI A
             , (SELECT DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, MAX(PLAN_SEQ) AS SEQ
                FROM   SCP_PLAN_VERSION_V
                WHERE  PLAN_START_YYYYMMDD = V_PLAN_NAME
                AND    CONFIRM_FLAG        = 'Y'
                GROUP BY DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE) B
        WHERE  1=1
        AND    A.DIVISION_ID         = B.DIVISION_ID
        AND    A.PLAN_START_YYYYMMDD = B.PLAN_START_YYYYMMDD
        AND    A.PLAN_TYPE           = B.PLAN_TYPE
        AND    A.SEQ                 = B.SEQ;

        N_LOG_COUNT := SQL%ROWCOUNT;

        /* 트랜잭션 (COMMIT) */
        COMMIT;

    EXCEPTION
        WHEN OTHERS THEN
            /* ROLLBACK / ERROR LOG VALUE SAVE */
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := 'ERROR_LINE : ' || V_PLAN_NAME || ' : ';
            D_EVENT_DATE  := SYSDATE;

            /* 트랜잭션 (END) */
            ROLLBACK;

            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    END;

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := V_PLAN_NAME;
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

END;

PROCEDURE PR_SCP_EGN_OTPT_PROC_RUN_MAIN
(
    P_PLAN_ID   IN VARCHAR2 DEFAULT NULL
)
IS
/*
 * Program ID   : PR_SCP_EGN_OTPT_PROC_RUN_MAIN
 * Description  : SCP 엔진 출력 프로시저를 순서대로 일괄 수행하는 메인 프로시저
 *
 * Program History
 *===================================================================================================
 *   Date         In Charge   Description
 *===================================================================================================
 * 2026.03.31     hrkim       Initial Release : PJ20264226 Next SCM Pilot 설계 및 개발
 * 2026.10.07     JCH         MSSQL -> Oracle 전환
 */
    V_PLAN_ID         VARCHAR2(100 CHAR)  := P_PLAN_ID;
    V_START_TIME      DATE                := SYSDATE;
    V_EXEC_TIME       VARCHAR2(10 CHAR)   := '';
    V_PROGRAM_NAME    VARCHAR2(150 CHAR)  := 'PR_SCP_EGN_OTPT_PROC_RUN_MAIN';
    V_LOG_TYPE        VARCHAR2(30 CHAR);
    N_LOG_COUNT       NUMBER              := 0;
    V_LOG_MESSAGE     VARCHAR2(1000 CHAR);
    V_DESCRIPTION     VARCHAR2(500 CHAR);
    V_EVENT_DATE      DATE;
    V_BATCH_USER      VARCHAR2(150 CHAR)  := 'scm_batch';
BEGIN

    /* 시작 로그 */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '##### Start of procedure #####';
    V_DESCRIPTION := '[plan_id=' || NVL(V_PLAN_ID, '') || ']';
    V_EVENT_DATE  := SYSDATE;
    PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, V_EVENT_DATE, V_BATCH_USER);

    /* 엔진 출력 처리 프로시저 순차 수행 (각 프로시저가 내부에서 COMMIT 한다) */
    PR_SCP_OPT_ENG_OUT_UPDATE_DBP_M(V_PLAN_ID);
    PR_SCP_EGN_OTPT_INV_M(V_PLAN_ID);
    PR_SCP_EGN_OTPT_PRDN_M(V_PLAN_ID);
    PR_SCP_EGN_OTPT_SIPM_M(V_PLAN_ID);
    PR_SCP_EGN_OTPT_CSP_M(V_PLAN_ID);
    PR_SCP_EGN_OTPT_RTF_M(V_PLAN_ID);
    PR_SCP_EGN_OTPT_PSI_M(V_PLAN_ID);

    /* 종료 로그 */
    V_EXEC_TIME   := LPAD(TO_CHAR(FLOOR((SYSDATE - V_START_TIME) * 1440)), 2, '0') || ':' ||
                     LPAD(TO_CHAR(MOD(ROUND((SYSDATE - V_START_TIME) * 86400), 60)), 2, '0');
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '##### END of procedure #####';
    V_DESCRIPTION := '[plan_id=' || NVL(V_PLAN_ID, '') || '][' || V_EXEC_TIME || ']';
    V_EVENT_DATE  := SYSDATE;
    PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, V_EVENT_DATE, V_BATCH_USER);

EXCEPTION
    WHEN OTHERS THEN
        /* 오류가 나면 미확정 변경을 되돌리고 로그를 남긴다 (원본과 동일하게 상위로 전파하지 않는다) */
        IF DBMS_TRANSACTION.LOCAL_TRANSACTION_ID IS NOT NULL THEN
            ROLLBACK;
        END IF;
        V_LOG_TYPE    := 'ERROR';
        V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
        V_DESCRIPTION := 'ERROR_BACKTRACE : ' || SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 460);
        V_EVENT_DATE  := SYSDATE;
        PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, V_EVENT_DATE, V_BATCH_USER);
END;

PROCEDURE         PR_SCP_ENG_CONTROL_N
    ( p_modeling_id1    IN VARCHAR2
    , p_plan_type1      IN VARCHAR2
)
/*
 * Program ID   : PR_SCP_ENG_CONTROL_N
 * Description  : Plan Control
 * OutTable     :
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2017.12.01   KSG            Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 *.........................................................................................
 *.........................................................................................
 *.........................................................................................
 * 2026.10.01   JCH            Engine Change(Thi-ra to Opt)
 */
IS
    /* --SET TRANSACTION ISOLATION LEVEL READ COMMITTED; */

     /* 20180228 프로시저 속도 개선을 위해서 입력변수를 일반변수로 변경함 */
    p_modeling_id   VARCHAR2(4000 CHAR) := p_modeling_id1 ;
    p_plan_type     VARCHAR2(4000 CHAR) := p_plan_type1 ;

    v_stat_cd           VARCHAR2(50 CHAR); /* Engine Status Input 용 변수 */

    /* LOG 용 변수 설정 */
    v_program_name  VARCHAR2(150 CHAR) := 'PR_SCP_ENG_CONTROL_N';
    v_log_type      VARCHAR2(30 CHAR); /* START/END/ERROR/... */
    n_log_count     PLS_INTEGER := 0;
    v_log_message   VARCHAR2(1000 CHAR);
    v_description   VARCHAR2(500 CHAR);
    v_table_id      VARCHAR2(150 CHAR) := '';
    d_event_date    DATE;

    v_master_id         VARCHAR2(4000 CHAR);
    v_division_id       VARCHAR2(4000 CHAR);
    v_plan_cycle        VARCHAR2(4000 CHAR);
    v_plan_name         VARCHAR2(4000 CHAR);
    v_plan_id           VARCHAR2(4000 CHAR);
    v_engine_plan_id    VARCHAR2(4000 CHAR);
    n_plan_seq          PLS_INTEGER;
    v_outversion_id     VARCHAR2(4000 CHAR);

    n_pre_plan_id       PLS_INTEGER := 0;
    n_cur_plan_id       PLS_INTEGER := 0;
    n_pre_week_plan_id  PLS_INTEGER := 0;
    n_cur_week_plan_id  PLS_INTEGER := 0;
    v_cur_day           VARCHAR2(8 CHAR) := TO_CHAR(SYSDATE, 'YYYYMMDD'); /* 당일 YYYYMMDD */
    v_cur_monday        VARCHAR2(8 CHAR) := TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7, 'YYYYMMDD'); /* 당주 월요일 YYYYMMDD */
    d_plan_name         DATE;
    v_eng_flag          VARCHAR2(10 CHAR);
    n_eng_time          PLS_INTEGER := 0;
    v_version_name      VARCHAR2(100 CHAR);

    v_rows              PLS_INTEGER;
    v_plan_status       PLS_INTEGER := 0;
    v_sms_desc          VARCHAR2(4000 CHAR);
    v_plan_summary1     VARCHAR2(4000 CHAR);
    v_plan_summary2     VARCHAR2(4000 CHAR);

    x_db_name           VARCHAR2(100 CHAR);
    v_db_name           VARCHAR2(100 CHAR);

    v_division_group    VARCHAR2(30 CHAR);    /* (2022.04.01) 변수추가 */

    v_eng_nwdrive_cnt   PLS_INTEGER := 0;     /* 2022.06.15 변수추가 */

    v_rc                SYS_REFCURSOR;        /* 2026.10.13 JCH : PKG_SCP0049.P_SAVE_NEW_VERSION OUT 커서 수신용 */

  BEGIN

  /* 시작 LOG */
    v_log_type := 'START';
    v_log_message := '########## Start of procedure ##########';
    v_description := p_modeling_id || ' / ' || p_plan_type ;
    d_event_date := SYSDATE;

    PR_SCM_SYS_LOG_BATCH(v_program_name, v_log_type, n_log_count, v_log_message, v_description, d_event_date);

    v_rows := 0;

    /* ----------------------------------------------------------
       실행용 변수 설정
       ---------------------------------------------------------- */
    /* 1. Master ID / Division ID / Plan Cycle / Planname */
    BEGIN
      SELECT /* PR_SCP_ENG_CONTROL_N */
             m.enterprise  /* v_master_id */
           , m.division_id /* v_division_id */
           , m.plan_cycle  /* v_plan_cycle */
           , CASE WHEN m.plan_cycle = 'WEEKLY'
                  THEN
                    TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7, 'YYYYMMDD') /* weekly (당주 월요일) */
                  ELSE
                    TO_CHAR(SYSDATE - 1, 'YYYYMMDD') /* daily (전일자) */
             END
        INTO v_master_id
           , v_division_id
           , v_plan_cycle
           , v_plan_name
        FROM scm_mst_modeling m
       WHERE m.modeling_id = p_modeling_id ; /* '1'; -- v_master_id */
    EXCEPTION
      WHEN NO_DATA_FOUND THEN NULL; /* 2026.10.13 JCH : MSSQL 은 0건이면 변수 유지 — 동일 동작 */
    END;
    /* SELECT '1. ==>      ', @v_master_id as master_id, @v_division_id as division_id , @v_division_id as division_id , @v_plan_cycle as plan_cycle , @v_plan_name as plan_name; */

    /* 2. Plan ID */
    BEGIN
      SELECT /* PR_SCP_ENG_CONTROL_N */
             p.plan_id /* v_plan_id */
        INTO v_plan_id
        FROM scm_mst_plan p
       WHERE p.division_id = v_division_id
         AND p.plan_cycle  = v_plan_cycle
         AND p.plan_name   = v_plan_name;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN NULL; /* 2026.10.13 JCH : MSSQL 은 0건이면 변수 유지 — 동일 동작 */
    END;
    /* SELECT '2. ==>      ', @@v_plan_id as plan_id; */

    /* 3. Plan seq : 처음이면 1, 아니면 MAX(Seq) + 1 */
    SELECT /* PR_SCP_ENG_CONTROL_N */
           NVL(MAX(p.plan_seq), 0) + 1 /* n_plan_seq */
      INTO n_plan_seq
      FROM scm_mst_plan_detail p
     WHERE p.modeling_id = p_modeling_id
       AND p.division_id = v_division_id
       AND p.plan_id     = v_plan_id
       AND p.plan_type   = p_plan_type  /* 20180219 추가 (plan_type 별 seq 구하기 위해서 수정함) */
    ;

    /* IF (@n_plan_seq = null)  select @n_plan_seq = ISNULL(@n_plan_seq,1)
       2026.10.13 JCH : 원문의 위 분기는 항상 거짓(= null 비교)이라 수행되지 않는 문장 — 주석 보존 */
    /* SELECT '3. ==>      ', @n_plan_seq as plan_seq; */

    /* 4. Engine Plan ID */
    v_engine_plan_id := v_division_id || '-' || v_plan_name || '-' || p_plan_type || '-' || TO_CHAR(n_plan_seq); /* Opt 호출용 Engine ID */
    v_version_name   := v_division_id || '-' || v_plan_name || '-' || p_plan_type || '-' || TO_CHAR(n_plan_seq);

    /* 5. DIVISION GROUP */
    /*------------------------------------------------------------------
     * Division Group 정의  (2022.04.04: Joint Venture 사업부 추가)
        - JV사업부 코드(81_UC, EE_UC)추가되면서 division_id만으로는 사업부별 로직분개시 구분값으로 활용 불가.
        - 40, 81, 82, EE 등 사업부별 로직전개에 사용할 기준값을 (attribute3)컬럼에 정의하고 변수 '@v_division_group'로 처리
        - 기존의 division_id 분개로직을 division_group 기준으로 대체하여 사용한다.
        - 예) division_group: 81 >> division_id: 81 , 81_UC
    ----------------------------------------------------------------------*/
    BEGIN
      SELECT di.attribute3
        INTO v_division_group
        FROM scm_mst_division di
       WHERE di.valid_yn    = 'Y'
         AND di.division_id = v_division_id ;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN NULL; /* 2026.10.13 JCH : MSSQL 은 0건이면 변수 유지 — 동일 동작 */
    END;


    /* ---------------------------------------------
       Plan Version 저장 작업 Call : 20190709
         오류 발생해도 Plan 작업은 정상 수행되어야 함
       --------------------------------------------- */
    BEGIN
        IF p_plan_type IN ('MA', 'SE', 'FN', 'TM', 'BF') THEN /* PR/TE는 FP Plan Cutoff 시 한 번 수행 */
          PR_SCM_MST_PLAN_FP_RELEASE_ID(v_plan_name, v_plan_id, p_modeling_id, TO_CHAR(n_plan_seq), p_plan_type, v_division_id);
        END IF;
    EXCEPTION
      WHEN OTHERS THEN
        v_log_type := 'TXN'; /* 오류 발생해도 Plan 작업은 정상 수행되어야 함 */
    END;

    /* ------------------------------------- */
    BEGIN
        /* 2026.10.13 JCH : MSSQL 단독 프로시저 SCP0049_SAVE_NEW_VERSION 은 Oracle 에서 PKG_SCP0049.P_SAVE_NEW_VERSION 으로 이관됨 — OUT 커서는 받고 바로 닫는다 */
        PKG_SCP0049.P_SAVE_NEW_VERSION( p_today_yyyymmdd   => v_cur_day
                                      , p_chk_bp           => 'N'
                                      , p_chk_rp           => 'N'
                                      , p_chk_scp          => 'Y'
                                      , p_version_division => v_division_id
                                      , p_version_name     => v_version_name
                                      , p_update_id        => 'scp_batch'
                                      , o_result_cursor    => v_rc );
        IF v_rc%ISOPEN THEN
          CLOSE v_rc;
        END IF;

        PR_SCP_MST_WORKING_TIME_COPY_FROM_FP(v_division_id);

        /* 선행 프로시저 이관 후 주석 해제_JCH (2026.10.13 기준 ZIOUI1 미존재)
        PR_SCP_MST_LOSS_TIME_COPY_FROM_FP(v_division_id);
        PR_SCP_MST_TACT_TIME_EXCEPT_COPY_FROM_FP(v_division_id);
        */

    EXCEPTION
      WHEN OTHERS THEN
        /* 오류 발생해도 SMS 전송 후 Plan 작업은 정상 수행되어야 함 */
        /* ----------------------------------------------------------
           SMS 전송 : Plan ERROR (20)
           ---------------------------------------------------------- */
        v_sms_desc := v_master_id || '::' || p_plan_type || ' : Capa Error' ;
        SCM_ADM_SMS_SEND_BATCH(20, v_sms_desc);
        /* ---------------------------------------------------------- */
    END;

    BEGIN
        /* ----------------------------------------------------------
           Engine 실행 로직 Start
           ----------------------------------------------------------
           ----------------------------------------------------------
           1. Engine Input Create
           ---------------------------------------------------------- */
        v_log_type := 'TXN';
        n_log_count := NVL(SQL%ROWCOUNT, 0);
        v_log_message := 'Plan Input';
        v_description := 'Start Plan Input... ' || ' / ' || v_engine_plan_id ;
        d_event_date := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(v_program_name, v_log_type, n_log_count, v_log_message, v_description, d_event_date);

        /* ----------------------------------------------------------
           SMS 전송 : Plan START (17)
           ---------------------------------------------------------- */
        v_sms_desc := v_master_id || '::' || p_plan_type;
        SCM_ADM_SMS_SEND_BATCH(17, v_sms_desc);
        /* ---------------------------------------------------------- */

        /* ---------------------------------------------------------- */
        IF v_division_group <> 'EE' THEN

                v_stat_cd := 'W';

                INSERT INTO SCP_OPMZ_PLAN_CTRL_ACTV_RUN_M
                (
                      PLAN_START_YYYYMMDD
                    , OPMZ_PRS_CD
                    , OPMZ_PLAN_GR_ID
                    , OPMZ_ACTV_CD
                    , OPMZ_PLAN_ID
                    , OPMZ_ACTV_RUN_STAT_CD
                    , DIVISION_ID
                    , CREATED_BY
                    , CREATION_DATE
                    , LAST_UPDATED_BY
                    , LAST_UPDATE_DATE
                )
                VALUES
                (
                      v_plan_name                           /* 20260601 */
                    , 'P001'                                /* P001     고정 */
                    , v_division_id || '_' || p_plan_type   /* 81_FN */
                    , 'A003'                                /* A003 : Engine Run */
                    , v_engine_plan_id
                    , v_stat_cd
                    , v_division_id
                    , 'scp_batch'
                    , SYSDATE
                    , 'scp_batch'
                    , SYSDATE
                );

        ELSIF v_division_group = 'EE' THEN

            /* 전극 Engine 실행 로직 */
            /* SCP용 DEMAND 데이터 ( OUTPUT 파트에서 생성한 프로시저임) */
            /* 선행 프로시저 이관 후 주석 해제_JCH (2026.10.13 기준 ZIOUI1 미존재 : PR_SCP_PLN_ELEC_DEMAND_CELL_PLAN · PR_SCP_PLN_ASSEMBLY_YIELD_AVG · PR_SCP_PLN_ELEC_YIELD_AVG)
               원문은 EXEC @rows = 프로시저 반환값 수신 — Oracle 이관 시 반환값(OUT) 사양 협의 필요

            PR_SCP_PLN_ELEC_DEMAND_CELL_PLAN(v_division_id, v_plan_name, p_plan_type);
            IF v_rows < 0 THEN GOTO RETURN_ERR_CODE; END IF;

            -- 20220323  PJ20216891 : Line 별 전극 수율 생성 Call : EE/PR 에서만 수행함
            IF p_plan_type IN ('PR') THEN
                PR_SCP_PLN_ASSEMBLY_YIELD_AVG(v_division_id);
                IF v_rows < 0 THEN GOTO RETURN_ERR_CODE; END IF;
            END IF;

            PR_SCP_PLN_ELEC_YIELD_AVG(v_division_id, v_plan_name, p_plan_type);
            IF v_rows < 0 THEN GOTO RETURN_ERR_CODE; END IF;
            */

                v_stat_cd := 'W';

                INSERT INTO SCP_OPMZ_PLAN_CTRL_ACTV_RUN_M
                (
                      PLAN_START_YYYYMMDD
                    , OPMZ_PRS_CD
                    , OPMZ_PLAN_GR_ID
                    , OPMZ_ACTV_CD
                    , OPMZ_PLAN_ID
                    , OPMZ_ACTV_RUN_STAT_CD
                    , DIVISION_ID
                    , CREATED_BY
                    , CREATION_DATE
                    , LAST_UPDATED_BY
                    , LAST_UPDATE_DATE
                )
                VALUES
                (                                           /* Example */
                      v_plan_name                           /* 20260601 */
                    , 'P001'                                /* P001     고정 */
                    , v_division_id || '_' || p_plan_type   /* 81_FN */
                    , 'A003'                                /* A003     : Engine Run(고정) */
                    , v_engine_plan_id
                    , v_stat_cd
                    , v_division_id
                    , 'scp_batch'
                    , SYSDATE
                    , 'scp_batch'
                    , SYSDATE
                );
        END IF;

        /* 최종실행한 Activity의 Plan id를 변경 */
        UPDATE SCP_OPMZ_PLAN_CTRL_ACTV_M
           SET LTST_RUN_OPMZ_PLAN_ID = v_engine_plan_id
             , LAST_UPDATE_DATE      = SYSDATE
         WHERE PLAN_START_YYYYMMDD   = v_plan_name
           AND OPMZ_PRS_CD           = 'P001'
           AND OPMZ_PLAN_GR_ID       = v_division_id || '_' || p_plan_type
           AND OPMZ_ACTV_CD          = 'A003'
        ;

        /* 2026.10.13 JCH : MSSQL 은 문장마다 자동커밋되어 엔진 서버가 요청 행('W')을 즉시 보지만,
           Oracle 은 커밋 전에는 다른 세션에서 보이지 않으므로 폴링 시작 전에 커밋한다 */
        COMMIT;

        /* ---------------------------------------------
           Plan Status Check : 사용자 중지 시 Plan Stop
           --------------------------------------------- */
        v_plan_status := FN_GET_PLAN_STATUS(v_division_id, v_plan_name, p_plan_type, n_plan_seq);
        IF v_plan_status < 0 THEN
          v_rows := -1;
          GOTO RETURN_ERR_CODE;
        END IF;
        /* --------------------------------------------- */

        /* -------------------------------------------------------------------------------------------------------------------
           2. 엔진 수행 여부 확인 후 Output 처리
              무한루프 돌면서 엔진 수행 완료여부 확인
           ------------------------------------------------------------------------------------------------------------------- */
        v_log_type := 'TXN';
        n_log_count := NVL(SQL%ROWCOUNT, 0);
        v_log_message := 'RUN Engine Check';
        v_description := 'Engine Start Check... ' || ' / ' || v_engine_plan_id ;
        d_event_date := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(v_program_name, v_log_type, n_log_count, v_log_message, v_description, d_event_date);

        v_eng_flag := 'W';
        n_eng_time := 0;

        /* 엔진 수행 시작 확인 : 확인 후 시작지 않으면 Error 처리 */
        WHILE v_eng_flag = 'W' LOOP

          DBMS_SESSION.SLEEP(10); /* 10초 Delay */

          /* 엔진제어용 Flag 정보 확인 */
          BEGIN
            SELECT /* PR_SCP_ENG_CONTROL_N */
                   OPMZ_ACTV_RUN_STAT_CD  /* Engine 시작 시 R, 완료시 C 로 Update됨 */
              INTO v_eng_flag
              FROM SCP_OPMZ_PLAN_CTRL_ACTV_RUN_M
             WHERE PLAN_START_YYYYMMDD = v_plan_name
               AND OPMZ_PLAN_ID        = v_engine_plan_id
            ;
          EXCEPTION
            WHEN NO_DATA_FOUND THEN NULL; /* 2026.10.13 JCH : MSSQL 은 0건이면 변수 유지 — 동일 동작 */
          END;

        /*
          OPMZ_ACTV_RUN_STAT_CD   W   Y   Waiting     1   Waiting
          OPMZ_ACTV_RUN_STAT_CD   R   Y   Running     2   Running
          OPMZ_ACTV_RUN_STAT_CD   C   Y   Completed   3   Completed
          OPMZ_ACTV_RUN_STAT_CD   E   Y   Error       9   Error
        */

          n_eng_time := n_eng_time + 10; /* 10초 Delay */

          IF n_eng_time = 1200 THEN /* 20분 */
            EXIT;
          END IF;
        END LOOP;

        /* Input 생성 후 Engine이 시작되지 않은 경우 */
        IF v_eng_flag IN ('W', 'E') THEN
          /* ERROR LOG */
          v_log_type := 'ERROR';
          v_log_message := SUBSTR(SQLERRM, 1, 1000);
          v_description := 'Engine Not Started... ' || ' / ' || v_engine_plan_id ;
          d_event_date := SYSDATE;
          PR_SCM_SYS_LOG_BATCH(v_program_name, v_log_type, n_log_count, v_log_message, v_description, d_event_date);

          v_rows := -1;
          GOTO RETURN_ERR_CODE;

          /* RETURN -1  : 원문의 도달 불가 문장 — 주석 보존 */
        END IF;

        /* ---------------------------------------------
           Plan Status Check : 사용자 중지 시 Plan Stop
           --------------------------------------------- */
        v_plan_status := FN_GET_PLAN_STATUS(v_division_id, v_plan_name, p_plan_type, n_plan_seq);
        IF v_plan_status < 0 THEN
          v_rows := -1;
          GOTO RETURN_ERR_CODE;
        END IF;
        /* --------------------------------------------- */

        /* -------------------------------------------------------------------------------------------------------------------
           3. 엔진 수행 종료 확인 : 확인 후 종료되지 않으면 Error 처리
           ------------------------------------------------------------------------------------------------------------------- */
        /* Engine이 정상 시작되면 Engine 종료 대기 */
        v_log_type := 'TXN';
        n_log_count := NVL(SQL%ROWCOUNT, 0);
        v_log_message := 'RUN Engine';
        v_description := 'Start Engine... ' || ' / ' || v_engine_plan_id ;
        d_event_date := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(v_program_name, v_log_type, n_log_count, v_log_message, v_description, d_event_date);

        WHILE v_eng_flag = 'R' LOOP

          DBMS_SESSION.SLEEP(10); /* 10초 Delay */

          /* 엔진제어용 Flag 정보 확인 */
          BEGIN
            SELECT /* PR_SCP_ENG_CONTROL_N */
                   OPMZ_ACTV_RUN_STAT_CD  /* Engine 시작 시 R, 완료시 C 로 Update됨 */
              INTO v_eng_flag
              FROM SCP_OPMZ_PLAN_CTRL_ACTV_RUN_M
             WHERE PLAN_START_YYYYMMDD = v_plan_name
               AND OPMZ_PLAN_ID        = v_engine_plan_id
            ;
          EXCEPTION
            WHEN NO_DATA_FOUND THEN NULL; /* 2026.10.13 JCH : MSSQL 은 0건이면 변수 유지 — 동일 동작 */
          END;

          n_eng_time := n_eng_time + 10; /* 10초 Delay */

          IF n_eng_time = 10800 THEN /* 180분 */
            EXIT;
          END IF;
        END LOOP;

        /* Engine 시작 후 정해진 시간 내에 종료되지 않은 경우 */
        IF v_eng_flag IN ('R', 'E') THEN /* 2026.10.13 JCH : 엔진이 Error(E) 로 끝난 경우도 오류 처리 (기존엔 타임아웃 R 만 판정) */
          /* ERROR LOG */
          v_log_type := 'ERROR';
          v_log_message := SUBSTR(SQLERRM, 1, 1000);
          v_description := 'Engine Not Completed... ' || ' / ' || v_engine_plan_id ;
          d_event_date := SYSDATE;
          PR_SCM_SYS_LOG_BATCH(v_program_name, v_log_type, n_log_count, v_log_message, v_description, d_event_date);

          v_rows := -1;
          GOTO RETURN_ERR_CODE;

          /* RETURN -1  : 원문의 도달 불가 문장 — 주석 보존 */
        END IF;

        /* ---------------------------------------------
           Plan Status Check : 사용자 중지 시 Plan Stop
           --------------------------------------------- */
        v_plan_status := FN_GET_PLAN_STATUS(v_division_id, v_plan_name, p_plan_type, n_plan_seq);
        IF v_plan_status < 0 THEN
          v_rows := -1;
          GOTO RETURN_ERR_CODE;
        END IF;
        /* --------------------------------------------- */

        /* -------------------------------------------------------------------------------------------------------------------
           4. Engine Output Transfer
           ------------------------------------------------------------------------------------------------------------------- */
        /* Engine이 정상 종료된 경우 */
        v_log_type := 'TXN';
        n_log_count := NVL(SQL%ROWCOUNT, 0);
        v_log_message := 'Plan Output';
        v_description := 'Start Plan Output Transfer... ' || ' / ' || v_engine_plan_id ;
        d_event_date := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(v_program_name, v_log_type, n_log_count, v_log_message, v_description, d_event_date);

         /* 개발 완료 후 주석 해제_JCH
        PR_SCP_ENG_OUT_ALL(v_master_id, v_engine_plan_id);
        IF v_rows < 0 THEN GOTO RETURN_ERR_CODE; END IF;
        */

        /* ---------------------------------------------
           Plan Status Check : 사용자 중지 시 Plan Stop
           --------------------------------------------- */
        v_plan_status := FN_GET_PLAN_STATUS(v_division_id, v_plan_name, p_plan_type, n_plan_seq);
        IF v_plan_status < 0 THEN
          v_rows := -1;
          GOTO RETURN_ERR_CODE;
        END IF;
        /* --------------------------------------------- */

        /* -------------------------------------------------------------------------------------------------------------------
           5. UI용 Output 처리(Next SCM : 통합데이터셋 생성)
           ------------------------------------------------------------------------------------------------------------------- */

        /* -------------------------------------------------------------------------------------------------------------------
           5.1 UI용 Output 처리 : 통합데이터셋
           ------------------------------------------------------------------------------------------------------------------- */
        /* Engine이 정상 종료된 경우 */
        v_log_type := 'TXN';
        n_log_count := NVL(SQL%ROWCOUNT, 0);
        v_log_message := 'Opt. Integration Dataset Output';
        d_event_date := SYSDATE;

        /* WEEKLY */
        IF v_plan_cycle = 'WEEKLY' THEN
          v_description := 'Start Plan SCP Opt Integration Dataset Create... ' || ' / ' || v_engine_plan_id ;
          PR_SCM_SYS_LOG_BATCH(v_program_name, v_log_type, n_log_count, v_log_message, v_description, d_event_date);

        /* 개발 완료 후 주석 해제_JCH
          PR_SCP_PLN_CREATE_DATA(v_master_id, v_engine_plan_id);
          IF v_rows < 0 THEN GOTO RETURN_ERR_CODE; END IF;
        */

        END IF; /* IF @v_plan_cycle = 'WEEKLY' */

        /* Plan Detail 정보 Update */
        UPDATE /* PR_SCP_ENG_CONTROL_N */
               scm_mst_plan_detail
           SET output_end_date  = SYSDATE
             , anl_start_date   = SYSDATE
             , last_update_date = SYSDATE
         WHERE modeling_id = p_modeling_id
           AND division_id = v_division_id
           AND plan_id     = v_plan_id
           AND plan_type   = p_plan_type
           AND plan_seq    = n_plan_seq  /* 2026.10.13 JCH : PLAN_SEQ 는 Oracle 에서 NUMBER — 문자 변환 비교 제거 */
        ;

        /* ---------------------------------------------
           Plan Status Check : 사용자 중지 시 Plan Stop
           --------------------------------------------- */
        v_plan_status := FN_GET_PLAN_STATUS(v_division_id, v_plan_name, p_plan_type, n_plan_seq);
        IF v_plan_status < 0 THEN
          v_rows := -1;
          GOTO RETURN_ERR_CODE;
        END IF;
        /* --------------------------------------------- */

        /* -------------------------------------------------------------------------------------------------------------------
           5.2 UI용 Output 처리 : ANL
           ------------------------------------------------------------------------------------------------------------------- */
        v_log_type := 'TXN';
        n_log_count := NVL(SQL%ROWCOUNT, 0);
        v_log_message := 'Plan ANL Output';
        d_event_date := SYSDATE;

        /* -----------------------------------------
           WEEKLY
           ----------------------------------------- */
        IF v_plan_cycle = 'WEEKLY' THEN
          v_description := 'Start Plan SCP ANL Create... ' || ' / ' || v_engine_plan_id ;
          PR_SCM_SYS_LOG_BATCH(v_program_name, v_log_type, n_log_count, v_log_message, v_description, d_event_date);

          /* WEEKLY 수행용 PR Call */
          /* 개발 완료 후 주석 해제_JCH
          PR_SCP_ANL_CREATE_DATA(v_master_id, v_engine_plan_id);
          IF v_rows < 0 THEN GOTO RETURN_ERR_CODE; END IF;
          */

        END IF; /* IF @v_plan_cycle = 'WEEKLY' */

        /* -----------------------------------------
           Plan Detail 정보 Update
           ----------------------------------------- */
        /* WEEKLY 이면서 PR/SE 인 경우 : Confirm 없음 */
        IF p_plan_type NOT IN ('MA', 'FN') THEN /* 'TE', 'TM', 'BF') */

            UPDATE /* PR_SCP_ENG_OUT_ALL */
                   scm_mst_plan_detail
               SET plan_status        = '1' /* 정상 종료 */
                 , display_yn         = 'Y'
                 , ui_display_yn      = 'Y'
                 , normal_complete_yn = 'Y'
                 , anl_end_date       = SYSDATE
                 , last_update_date   = SYSDATE
             WHERE modeling_id = p_modeling_id
               AND division_id = v_division_id
               AND plan_id     = v_plan_id
               AND plan_type   = p_plan_type
               AND plan_seq    = n_plan_seq
            ;

        END IF;

        /* WEEKLY이면서 MA/FN인 경우 : 자동 Confirm -- 2018.06.19  MA Plan 정상 종료 시 자동 Confirm 처리 */
        IF p_plan_type IN ('MA', 'FN') THEN /* 'TE', 'TM', 'BF') */

            /* 자동 Confirm 실행 */
            UPDATE /* PR_SCP_ENG_CONTROL_N */
                   scm_mst_plan_detail
               SET CONFIRM_FLAG = NULL /* 2026.10.13 JCH : 원문은 '' — Oracle 빈 문자열은 NULL (CONFIRM_DATE 는 MSSQL 에서 1900-01-01 입력, Oracle 은 NULL) */
                 , CONFIRM_USER = NULL
                 , CONFIRM_DATE = NULL
             WHERE modeling_id = p_modeling_id
               AND division_id = v_division_id
               AND plan_id     = v_plan_id
               AND plan_type   = p_plan_type ;

            UPDATE /* PR_SCP_ENG_CONTROL_N */
                   scm_mst_plan_detail
               SET plan_status        = '1' /* 정상 종료 */
                 , display_yn         = 'Y'
                 , ui_display_yn      = 'Y'
                 , normal_complete_yn = 'Y'
                 , anl_end_date       = SYSDATE
                 , last_update_date   = SYSDATE

                 , CONFIRM_FLAG       = 'Y'
                 , CONFIRM_USER       = 'scm_batch'
                 , CONFIRM_DATE       = SYSDATE

             WHERE modeling_id = p_modeling_id
               AND division_id = v_division_id
               AND plan_id     = v_plan_id
               AND plan_type   = p_plan_type
               AND plan_seq    = n_plan_seq
            ;

        END IF; /* IF @p_plan_type IN ('MA', 'FN', 'TE', 'TM', 'BF') */

        /* ----------------------------------------------------------
           SMS 전송 : Plan END (18)
           ---------------------------------------------------------- */
        /* 2026.10.13 JCH : 엔진 점검용 BUF 블록 삭제로 요약 변수가 NULL 이 되어 SMS 내용 전체가 NULL 로 발송되는 문제 방지 */
        v_plan_summary1 := ';' ;
        v_plan_summary2 := ';' ;
        /* SET @v_sms_desc = @v_master_id + '::' + @p_plan_type; */
        v_sms_desc := v_master_id || '::' || p_plan_type || ' / ' || v_plan_summary1 || ' / ' || v_plan_summary2;
        SCM_ADM_SMS_SEND_BATCH(18, v_sms_desc);
        /* ---------------------------------------------------------- */

        /* ----------------------------------------------------------
           엔진결과 외부시스템 인터페이스 처리 실행
           ----------------------------------------------------------
           20230228 PJ20230691R 소형 Pre FP 전송 추가를 위하여 PR에서도 Call함 : PR_SCP_PLN_INTERFACE_PLAN 내부에서 분기 처리
           20241203 PJ20249346 : Semi 도 PR_SCP_PLN_INTERFACE_PLAN 호출 */
        /* 선행 프로시저 이관 후 주석 해제_JCH (2026.10.13 기준 ZIOUI1 미존재 : PR_SCP_PLN_INTERFACE_PLAN)
        IF p_plan_type IN ('PR', 'MA', 'SE', 'FN') THEN

            PR_SCP_PLN_INTERFACE_PLAN(v_division_id, v_plan_name, p_plan_type, n_plan_seq, 'scm_batch');

        END IF; -- IF @p_plan_type IN ('PR', 'MA', 'SE', 'FN')
        */

        /* ----------------------------------------------------------
           재고 DIO Trend 정보 생성 : 20230228 PJ20230691R FN - 81/81_UC
           ---------------------------------------------------------- */
        IF p_plan_type IN ('FN') AND v_division_group IN ('81') THEN
            BEGIN
                PR_SCP_RPT_DIO_TREND_MM(v_division_id, v_plan_name, 'scm_batch');
            EXCEPTION
              WHEN OTHERS THEN
                v_log_type := 'TXN'; /* 오류 발생해도 Plan 작업은 정상 수행되어야 함 */
            END;
        END IF;

        /* ----------------------------------------------------------
           2024.01.29 자동차 Global PSI New 데이터 생성 추가
           20241018  E20241016-000757 81 JV Division 확장 개발건
           2024.11.19 E20241114-000976
            WA 도입셀 정보 반영을 위하여 81_ST Global PSI New 생성 시점 변경
             - 81_ST Final 후 : Global PSI New 정보 생성 중지
             - 81 Final 후 : 81 Global PSI New 정보 생성 이후 81_ST 정보도 같이 생성
           ---------------------------------------------------------- */
        /* 선행 프로시저 이관 후 주석 해제_JCH
           (2026.10.13 기준 ZIOUI1 미존재 : PR_SCP_RPT_GLOBAL_PSI_MD_MM · PR_SCP_RPT_GLOBAL_PSI_MD_WW.
            PR_SCP_RPT_GLOBAL_PSI_STD_DIO 는 존재하나 파라미터가 P_BUCKET·P_SERCH_LEVEL 로 원문(P_PLAN_TYPE)과 달라 배치용 본이 아님 — 이관 시 확인 필요)
        IF p_plan_type IN ('PR','MA','FN') AND v_division_group IN ('81')  -- JV 포함
           AND v_division_id NOT IN ('81_ST') THEN -- 81_ST 는 81 Finlal 이후 수행
            BEGIN
                PR_SCP_RPT_GLOBAL_PSI_MD_MM(v_division_id, v_plan_name, p_plan_type);    -- 월별
                PR_SCP_RPT_GLOBAL_PSI_MD_WW(v_division_id, v_plan_name, p_plan_type);    -- 주별
                PR_SCP_RPT_GLOBAL_PSI_STD_DIO(P_DIVISION_ID => v_division_id, P_PLAN_START_YYYYMMDD => v_plan_name, P_PLAN_TYPE => p_plan_type);
                -- E20260708-000926 Global PSI New 수행 Plan type 추가 요청의 건 기존 로직 신규로직 끝

                -- 81_ST 는 81 Finlal 이후 수행
                IF v_division_id IN ('81') THEN
                    -- E20260708-000926 Global PSI New 수행 Plan type 추가 요청의 건 기존 로직 주석처리 끝
                    -- E20260708-000926 Global PSI New 수행 Plan type 추가 요청의 건 기존 로직 신규로직 시작
                    PR_SCP_RPT_GLOBAL_PSI_MD_MM('81_ST', v_plan_name, p_plan_type);   -- 월별
                    PR_SCP_RPT_GLOBAL_PSI_MD_WW('81_ST', v_plan_name, p_plan_type);   -- 주별
                    PR_SCP_RPT_GLOBAL_PSI_STD_DIO(P_DIVISION_ID => '81_ST', P_PLAN_START_YYYYMMDD => v_plan_name, P_PLAN_TYPE => p_plan_type);
                    -- E20260708-000926 Global PSI New 수행 Plan type 추가 요청의 건 기존 로직 신규로직 끝
                END IF;
            EXCEPTION
              WHEN OTHERS THEN
                v_log_type := 'TXN'; -- 오류 발생해도 Plan 작업은 정상 수행되어야 함
            END;
        END IF;
        */

        /* ----------------------------------------------------------
           PJ20216891 :  bod_n_v를 테이블로 저장
           ---------------------------------------------------------- */
        BEGIN
            PR_SCP_ANL_BOD_N_V_PLAN_H(v_division_id, v_plan_name, p_plan_type, n_plan_seq);
        EXCEPTION
          WHEN OTHERS THEN
            v_log_type := 'TXN'; /* 오류 발생해도 Plan 작업은 정상 수행되어야 함 */
        END;

        /* ----------------------------------------------------------
           Capa Report 용 Prod Plan 정보 생성 : 20240701 PJ20239015 LGES Capa. 관리 시스템 구축
           Capa Proc 내에서 월 마지막 목요일이 속한 주차만 수행됨
           20240820 : Capa 사업 계획 처리로 임시로 막음
           20250106 : CPS_BATCH_PROC_RUN lookup 참조하여 생산계획 반영 프로시저 수행
           ---------------------------------------------------------- */
        /* 선행 프로시저 이관 후 주석 해제_JCH (2026.10.13 기준 ZIOUI1 미존재 : PR_SCP_MST_CAPA_PROD_PLAN_APPLY)
        DECLARE
          v_exists PLS_INTEGER := 0;
        BEGIN
          BEGIN
            SELECT 1
              INTO v_exists
              FROM SCM_ADM_LOOKUP_MASTER_DETAIL LK
             WHERE LK.LOOKUP_TYPE = 'CPS_BATCH_PROC_RUN'
               AND LK.SEGMENT1    = 'PR_SCP_ENG_CONTROL'                  -- 상위 프로시저 : SCP 엔진 Control
               AND LK.SEGMENT2    = 'PR_SCP_MST_CAPA_PROD_PLAN_APPLY'     -- 하위 프로시저 : 조립팩 SCP 생산계획 반영
               AND LK.VALID_YN    = 'Y'
               AND LK.ATTRIBUTE1  = 'Y'                                   -- 수행여부
               AND ROWNUM         = 1;
          EXCEPTION
            WHEN NO_DATA_FOUND THEN v_exists := 0;
          END;

          IF p_plan_type IN ('FN') AND v_division_group NOT IN ('EE') AND v_exists = 1 THEN -- 전극 외
            BEGIN
                PR_SCP_MST_CAPA_PROD_PLAN_APPLY(P_IS_MANUAL => 'N', P_DIVISION_ID => v_division_id);
            EXCEPTION
              WHEN OTHERS THEN
                v_log_type := 'TXN'; -- 오류 발생해도 Plan 작업은 정상 수행되어야 함
            END;
          END IF;
        END;
        */

        /* 선행 프로시저 이관 후 주석 해제_JCH (2026.10.13 기준 ZIOUI1 미존재 : PR_SCP_MST_CAPA_PROD_PLAN_APPLY_ELTR)
        DECLARE
          v_exists PLS_INTEGER := 0;
        BEGIN
          BEGIN
            SELECT 1
              INTO v_exists
              FROM SCM_ADM_LOOKUP_MASTER_DETAIL LK
             WHERE LK.LOOKUP_TYPE = 'CPS_BATCH_PROC_RUN'
               AND LK.SEGMENT1    = 'PR_SCP_ENG_CONTROL'                      -- 상위 프로시저 : SCP 엔진 Control
               AND LK.SEGMENT2    = 'PR_SCP_MST_CAPA_PROD_PLAN_APPLY_ELTR'    -- 하위 프로시저 : 조립팩 SCP 생산계획 반영
               AND LK.VALID_YN    = 'Y'
               AND LK.ATTRIBUTE1  = 'Y'                                       -- 수행여부
               AND ROWNUM         = 1;
          EXCEPTION
            WHEN NO_DATA_FOUND THEN v_exists := 0;
          END;

          IF p_plan_type IN ('FN') AND v_division_group IN ('EE') AND v_exists = 1 THEN -- 전극
            BEGIN
                PR_SCP_MST_CAPA_PROD_PLAN_APPLY_ELTR(P_IS_MANUAL => 'N', P_EE_DIVISION_ID => v_division_id);
            EXCEPTION
              WHEN OTHERS THEN
                v_log_type := 'TXN'; -- 오류 발생해도 Plan 작업은 정상 수행되어야 함
            END;
          END IF;
        END;
        */

        /* ----------------------------------------------------------
           20241107  PJ20249346 ESS 회수포장재 Simulator 정보 생성
             오류 발생해도 Plan 작업은 정상 수행되어야 함
           ---------------------------------------------------------- */
        /* 선행 프로시저 이관 후 주석 해제_JCH (2026.10.13 기준 ZIOUI1 에 존재하나 INVALID — 담당 세션 작업 중)
        IF v_division_id IN ('82') THEN
            BEGIN
                PR_SCP_ANL_CELL_TRAY_SIMULATION(v_division_id, v_plan_name, p_plan_type);
            EXCEPTION
              WHEN OTHERS THEN
                v_log_type := 'TXN'; -- 오류 발생해도 Plan 작업은 정상 수행되어야 함
            END;
        END IF;
        */

        /* ----------------------------------------------------------
           20220208  PJ20216891  Waterfall 생성 사업부별 수행
             오류 발생해도 Plan 작업은 정상 수행되어야 함
           ---------------------------------------------------------- */
        /* 선행 프로시저 이관 후 주석 해제_JCH (2026.10.13 기준 ZIOUI1 미존재 : CUTOFF 3종)

        -- PRODUCTION_PLAN Waterfall
        BEGIN
            IF p_plan_type IN ('FN') THEN
              PR_SCP_ANL_PRODUCTION_PLAN_CUTOFF(v_division_id);
            END IF; -- IF @p_plan_type IN ('FN')
        EXCEPTION
          WHEN OTHERS THEN
            v_log_type := 'TXN'; -- 오류 발생해도 Plan 작업은 정상 수행되어야 함
        END;

        -- SHIPMENT_PLAN_FG Waterfall
        BEGIN
            IF p_plan_type IN ('FN') THEN
              PR_SCP_ANL_SHIPMENT_PLAN_FG_CUTOFF(v_division_id);
            END IF; -- IF @p_plan_type IN ('FN')
        EXCEPTION
          WHEN OTHERS THEN
            v_log_type := 'TXN'; -- 오류 발생해도 Plan 작업은 정상 수행되어야 함
        END;

        -- SHIPMENT_PLAN_SEMI Waterfall
        BEGIN
            IF p_plan_type IN ('FN') THEN
              PR_SCP_ANL_SHIPMENT_PLAN_SEMI_CUTOFF(v_division_id);
            END IF; -- IF @p_plan_type IN ('FN')
        EXCEPTION
          WHEN OTHERS THEN
            v_log_type := 'TXN'; -- 오류 발생해도 Plan 작업은 정상 수행되어야 함
        END;
        */

        /* ----------------------------------------------------------
           실행 Logic END --
           ---------------------------------------------------------- */

        v_log_type := 'TXN';
        n_log_count := NVL(SQL%ROWCOUNT, 0);
        v_log_message := 'RUN ' || v_table_id;
        v_description := 'Process Complete... ' || ' / ' || v_engine_plan_id ;
        d_event_date := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(v_program_name, v_log_type, n_log_count, v_log_message, v_description, d_event_date);

        IF DBMS_TRANSACTION.LOCAL_TRANSACTION_ID IS NOT NULL THEN
          COMMIT;
        END IF;

        <<RETURN_ERR_CODE>>
        BEGIN
          IF v_rows < 0 THEN
              /* ROLLBACK */
              /* ERROR LOG */
              v_log_type := 'ERROR';
              v_log_message := SUBSTR(SQLERRM, 1, 1000);
              v_description := SUBSTR('ERROR_LINE : ' || ' / ' || v_engine_plan_id, 1, 500);
              d_event_date := SYSDATE;
              PR_SCM_SYS_LOG_BATCH(v_program_name, v_log_type, n_log_count, v_log_message, v_description, d_event_date);

              /* Plan Detail 정보 Update */
              UPDATE /* PR_SCP_ENG_OUT_ALL */
                     scm_mst_plan_detail
                 SET plan_status        = '-1' /* Error 종료 */
                   , normal_complete_yn = 'N'
                   , last_update_date   = SYSDATE
               WHERE modeling_id = p_modeling_id
                 AND division_id = v_division_id
                 AND plan_id     = v_plan_id
                 AND plan_seq    = n_plan_seq
                 AND plan_type   = p_plan_type
              ;

              /* ----------------------------------------------------------
                 SMS 전송 : Plan ERROR (20)
                 ---------------------------------------------------------- */
              v_sms_desc := v_master_id || '::' || p_plan_type;
              SCM_ADM_SMS_SEND_BATCH(20, v_sms_desc);
              /* ---------------------------------------------------------- */

              COMMIT; /* 2026.10.13 JCH : MSSQL 자동커밋 대응 — 오류 상태 기록을 확정 */

              RETURN;
          END IF; /* IF @rows < 0 */

        END; /* _RETURN_ERR_CODE: */

    EXCEPTION
      WHEN OTHERS THEN
        /* ROLLBACK */
        /* ERROR LOG */
        v_log_type := 'ERROR';
        v_log_message := SUBSTR(SQLERRM, 1, 1000);
        v_description := SUBSTR('ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE || ' / ' || v_engine_plan_id, 1, 500);
        d_event_date := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(v_program_name, v_log_type, n_log_count, v_log_message, v_description, d_event_date);

        /* Plan Detail 정보 Update */
        UPDATE /* PR_SCP_ENG_OUT_ALL */
               scm_mst_plan_detail
           SET plan_status        = '-1' /* Error 종료 */
             , normal_complete_yn = 'N'
             , last_update_date   = SYSDATE
         WHERE modeling_id = p_modeling_id
           AND division_id = v_division_id
           AND plan_id     = v_plan_id
           AND plan_seq    = n_plan_seq
           AND plan_type   = p_plan_type
        ;

        /* ----------------------------------------------------------
           SMS 전송 : Plan ERROR (20)
           ---------------------------------------------------------- */
        v_sms_desc := v_master_id || '::' || p_plan_type;
        SCM_ADM_SMS_SEND_BATCH(20, v_sms_desc);
        /* ---------------------------------------------------------- */

        COMMIT; /* 2026.10.13 JCH : MSSQL 자동커밋 대응 — 오류 상태 기록을 확정 */

        RETURN;
    END;

    /* 종료 LOG */
    v_log_type := 'END';
    v_log_message := '########## END of procedure ##########';
    v_description := v_engine_plan_id ;
    d_event_date := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(v_program_name, v_log_type, n_log_count, v_log_message, v_description, d_event_date);

  END;

PROCEDURE PR_SCP_IF_CHECK_SMS_SEND
/*
 * Program ID   : PR_SCP_IF_CHECK_SMS_SEND
 * Description  : SCP-ERP,FP 간 I/F DATA Check
 * OutTable     :
 * Execute      :
 * Program History
 *===================================================================================================
 *   Date       In Charge		Description
 *===================================================================================================
 * 2020.02.24   hwwoonins		Initial Release [] 전지GSCM(SCP) SM 운영
 * 2021.01.26   KSG             SO Reserved Stock Check 추가
 * 2026.08.03   ZIONEX          [PJ202650304]  NextSCM Migration
 */
 AS
    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME VARCHAR2(150 CHAR) := 'PR_SCP_IF_CHECK_SMS_SEND';
    V_LOG_TYPE     VARCHAR2(30 CHAR);   /* START/END/ERROR/... */
    N_LOG_COUNT    INTEGER := 0;
    V_LOG_MESSAGE  VARCHAR2(1000 CHAR);
    V_DESCRIPTION  VARCHAR2(500 CHAR);
    D_EVENT_DATE   DATE;

    V_RS           VARCHAR2(10 CHAR);
    V_MESSAGE      VARCHAR2(100 CHAR);
  BEGIN


	/* 시작 LOG */
	V_LOG_TYPE := 'START';
	V_LOG_MESSAGE := '########## Start of procedure ##########';
	V_DESCRIPTION := NULL;
	D_EVENT_DATE := SYSDATE;
	PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);


    BEGIN
      BEGIN

        /* ========================= 해상재고 Intransit =========================== */
        V_RS := NULL;
        V_MESSAGE := NULL;

        WITH RS AS (
        SELECT RESULT_DATE
             , COUNT(IFSEQNO) CNT
          FROM XIF_ERP_INTRANSIT_R_SN
         WHERE RESULT_DATE >= TO_CHAR(SYSDATE - 4, 'YYYYMMDD')
         GROUP BY RESULT_DATE
        )
        SELECT (CASE WHEN RS1.RESULT_DATE IS NULL THEN 'false'
                     WHEN RS1.RESULT_DATE IS NOT NULL AND RS2.RESULT_DATE IS NULL THEN 'true'
                     WHEN RS2.CNT * 0.8 > RS1.CNT THEN 'false'
                     ELSE 'true'
                END)
          INTO V_RS
          FROM (SELECT 'TEST' AS T FROM DUAL) A
          LEFT JOIN RS RS1 ON RS1.RESULT_DATE = TO_CHAR(SYSDATE - 1, 'YYYYMMDD')
          LEFT JOIN RS RS2 ON RS2.RESULT_DATE = TO_CHAR(SYSDATE - 2, 'YYYYMMDD');

        IF (V_RS = 'false') THEN
            BEGIN
                /* PRINT 'ERP In-transit False!'; */
                V_MESSAGE := 'ERP In-transit 해상재고 I/F Check';
                SCM_ADM_SMS_SEND_BATCH(60, V_MESSAGE);
            END;
        END IF;

        /* ========================= 해상재고 Tracking =========================== */
        V_RS := NULL;
        V_MESSAGE := NULL;

        WITH RS AS (
        SELECT TRANSFER_DATE
             , COUNT(IFSEQNO) CNT
          FROM XIF_ERP_DELIVERY_TRACKING_R_SN
         WHERE TRANSFER_DATE >= TO_CHAR(SYSDATE - 4, 'YYYYMMDD')
         GROUP BY TRANSFER_DATE
        )
        SELECT (CASE WHEN RS1.TRANSFER_DATE IS NULL THEN 'false'
                     WHEN RS1.TRANSFER_DATE IS NOT NULL AND RS2.TRANSFER_DATE IS NULL THEN 'true'
                     WHEN RS2.CNT * 0.8 > RS1.CNT THEN 'false'
                     ELSE 'true'
                END)
          INTO V_RS
          FROM (SELECT 'TEST' AS T FROM DUAL) A
          LEFT JOIN RS RS1 ON RS1.TRANSFER_DATE = TO_CHAR(SYSDATE - 1, 'YYYYMMDD')
          LEFT JOIN RS RS2 ON RS2.TRANSFER_DATE = TO_CHAR(SYSDATE - 2, 'YYYYMMDD');

        IF (V_RS = 'false') THEN
            BEGIN
                /* PRINT 'ERP In-transit Tracking False!'; */
                V_MESSAGE := 'ERP 해상재고(GTS) Tracking I/F Check';
                SCM_ADM_SMS_SEND_BATCH(60, V_MESSAGE);
            END;
        END IF;

        /* ========================= 법인간 미착재고 =========================== */
        V_RS := NULL;
        V_MESSAGE := NULL;

        WITH RS AS (
        SELECT RESULT_DATE
             , COUNT(IFSEQNO) CNT
          FROM XIF_ERP_INTRANSIT_CO_SUMMARY_R_SN
         WHERE RESULT_DATE >= TO_CHAR(SYSDATE - 4, 'YYYYMMDD')
         GROUP BY RESULT_DATE
        )
        SELECT (CASE WHEN RS1.RESULT_DATE IS NULL THEN 'false'
                     WHEN RS1.RESULT_DATE IS NOT NULL AND RS2.RESULT_DATE IS NULL THEN 'true'
                     WHEN RS2.CNT * 0.8 > RS1.CNT THEN 'false'
                     ELSE 'true'
                END)
          INTO V_RS
          FROM (SELECT 'TEST' AS T FROM DUAL) A
          LEFT JOIN RS RS1 ON RS1.RESULT_DATE = TO_CHAR(SYSDATE - 1, 'YYYYMMDD')
          LEFT JOIN RS RS2 ON RS2.RESULT_DATE = TO_CHAR(SYSDATE - 2, 'YYYYMMDD');

        IF (V_RS = 'false') THEN
            BEGIN
                /* PRINT N'ERP 법인간 미착재고 False!'; */
                V_MESSAGE := 'ERP 법인간 미착재고 I/F Check';
                SCM_ADM_SMS_SEND_BATCH(60, V_MESSAGE);
            END;
        END IF;

        /* ========================= 고객위탁재고 =========================== */
        V_RS := NULL;
        V_MESSAGE := NULL;

        WITH RS AS (
        SELECT RESULT_DATE
             , COUNT(IFSEQNO) CNT
          FROM XIF_ERP_CUSTOMER_CONSIGN_STOCK_R_SN
         WHERE RESULT_DATE >= TO_CHAR(SYSDATE - 4, 'YYYYMMDD')
           AND ATTRIBUTE1 = 'A'
         GROUP BY RESULT_DATE
        )
        SELECT (CASE WHEN RS1.RESULT_DATE IS NULL THEN 'false'
                     WHEN RS1.RESULT_DATE IS NOT NULL AND RS2.RESULT_DATE IS NULL THEN 'true'
                     WHEN RS2.CNT * 0.8 > RS1.CNT THEN 'false'
                     ELSE 'true'
                END)
          INTO V_RS
          FROM (SELECT 'TEST' AS T FROM DUAL) A
          LEFT JOIN RS RS1 ON RS1.RESULT_DATE = TO_CHAR(SYSDATE - 1, 'YYYYMMDD')
          LEFT JOIN RS RS2 ON RS2.RESULT_DATE = TO_CHAR(SYSDATE - 2, 'YYYYMMDD');

        IF (V_RS = 'false') THEN
            BEGIN
                /* PRINT N'ERP S/O Stock (고객 위탁 재고) False!'; */
                V_MESSAGE := 'ERP 고객 위탁 재고 I/F Check';
                SCM_ADM_SMS_SEND_BATCH(60, V_MESSAGE);
            END;
        END IF;

        /* ========================= SO Reserved Stock =========================== */
        /*  20210126 SO Reserved Stock Check 추가 */
        V_RS := NULL;
        V_MESSAGE := NULL;

        WITH RS AS (
        SELECT RESULT_DATE
             , COUNT(IFSEQNO) CNT
          FROM XIF_ERP_CUSTOMER_CONSIGN_STOCK_R_SN
         WHERE RESULT_DATE >= TO_CHAR(SYSDATE - 4, 'YYYYMMDD')
           AND ATTRIBUTE1 = 'B'
         GROUP BY RESULT_DATE
        )
        SELECT (CASE WHEN RS1.RESULT_DATE IS NULL THEN 'false'
                     WHEN RS1.RESULT_DATE IS NOT NULL AND RS2.RESULT_DATE IS NULL THEN 'true'
                     WHEN RS2.CNT * 0.8 > RS1.CNT THEN 'false'
                     ELSE 'true'
                END)
          INTO V_RS
          FROM (SELECT 'TEST' AS T FROM DUAL) A
          LEFT JOIN RS RS1 ON RS1.RESULT_DATE = TO_CHAR(SYSDATE - 1, 'YYYYMMDD')
          LEFT JOIN RS RS2 ON RS2.RESULT_DATE = TO_CHAR(SYSDATE - 2, 'YYYYMMDD');

        IF (V_RS = 'false') THEN
            BEGIN
                /* PRINT N'ERP S/O Stock (고객 위탁 재고) False!'; */
                V_MESSAGE := 'ERP SO Reserved Stock I/F Check';
                SCM_ADM_SMS_SEND_BATCH(60, V_MESSAGE);
            END;
        END IF;

        /* ========================= VMI STOCK재고 =========================== */
        V_RS := NULL;
        V_MESSAGE := NULL;

        WITH RS AS (
        SELECT IFDAT
             , COUNT(IFSEQNO) CNT
          FROM XIF_ERP_VMI_STOCK_R_SN
         WHERE IFDAT >= TO_CHAR(SYSDATE - 4, 'YYYYMMDD')
         GROUP BY IFDAT
        )
        SELECT (CASE WHEN RS1.IFDAT IS NULL THEN 'false'
                     WHEN RS1.IFDAT IS NOT NULL AND RS2.IFDAT IS NULL THEN 'true'
                     WHEN RS2.CNT * 0.8 > RS1.CNT THEN 'false'
                     ELSE 'true'
                END)
          INTO V_RS
          FROM (SELECT 'TEST' AS T FROM DUAL) A
          LEFT JOIN RS RS1 ON RS1.IFDAT = TO_CHAR(SYSDATE - 1, 'YYYYMMDD')
          LEFT JOIN RS RS2 ON RS2.IFDAT = TO_CHAR(SYSDATE - 2, 'YYYYMMDD');

        IF (V_RS = 'false') THEN
            BEGIN
                /* PRINT N'ERP VMISTOCK(국내) False!'; */
                V_MESSAGE := 'ERP VMISTOCK(국내) I/F Check';
                SCM_ADM_SMS_SEND_BATCH(60, V_MESSAGE);
            END;
        END IF;

        /* ========================= 출하실적 =========================== */
        V_RS := NULL;
        V_MESSAGE := NULL;

        WITH RS AS (
        SELECT TRNF_DATE
             , COUNT(IFSEQNO) CNT
          FROM XIF_ERP_EXFACTORY_RESULT_R_SN
         WHERE TRNF_DATE >= TO_CHAR(SYSDATE - 4, 'YYYYMMDD')
         GROUP BY TRNF_DATE
        )
        SELECT (CASE WHEN RS1.TRNF_DATE IS NULL THEN 'false'
                     ELSE 'true'
                END)
          INTO V_RS
          FROM (SELECT 'TEST' AS T FROM DUAL) A
          LEFT JOIN RS RS1 ON RS1.TRNF_DATE = TO_CHAR(SYSDATE - 1, 'YYYYMMDD');

        IF (V_RS = 'false') THEN
            BEGIN
                /* PRINT N'FP 출하실적 False!'; */
                V_MESSAGE := 'FP 출하실적 I/F Check';
                SCM_ADM_SMS_SEND_BATCH(60, V_MESSAGE);
            END;
        END IF;

      END;


    EXCEPTION

      WHEN OTHERS THEN

        /* ERROR LOG */

        V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);

        INSERT
          INTO SCM_SYS_LOG_BATCH
             ( PROGRAM_NAME
             , LOG_TYPE
             , LOG_COUNT
             , LOG_MESSAGE
             , DESCRIPTION
             , EVENT_DATE
             , CREATION_DATE
             , CREATED_BY
             , LAST_UPDATE_DATE
             , LAST_UPDATED_BY )
        VALUES ( V_PROGRAM_NAME
               , 'ERROR'
               , NULL
               , V_LOG_MESSAGE
               , NULL
               , SYSDATE
               , SYSDATE
               , V_PROGRAM_NAME
               , SYSDATE
               , V_PROGRAM_NAME );


        COMMIT;


        RETURN;

    END;

	/* 종료 LOG */
	V_LOG_TYPE := 'END';
	V_LOG_MESSAGE := '########## END of procedure ##########';
	V_DESCRIPTION := NULL;
	D_EVENT_DATE := SYSDATE;
	PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);


	COMMIT;


  END PR_SCP_IF_CHECK_SMS_SEND;

PROCEDURE PR_SCP_MST_ALTER_BOM_ALL_BATCH
/*
 * Program ID   : PR_SCP_MST_ALTER_BOM_ALL_BATCH
 * Description  : 대체 BOM 생성
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2021.04.12   SEO			PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선
 *							- SCP 대치BOM
 * 2026.07.31   ZIONEX         [PJ202650304] NextSCM Migration
 */
IS
    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME  VARCHAR2(150 CHAR) := 'PR_SCP_MST_ALTER_BOM_ALL_BATCH';
    V_LOG_TYPE      VARCHAR2(30 CHAR);              /* START/END/ERROR/... */
    N_LOG_COUNT     INTEGER := 0;
    V_LOG_MESSAGE   VARCHAR2(1000 CHAR);
    V_DESCRIPTION   VARCHAR2(500 CHAR);
    V_TABLE_ID      VARCHAR2(150 CHAR) := '';
    D_EVENT_DATE    DATE;

    V_ROWS          INTEGER;
BEGIN


    /* 시작 LOG */
    V_LOG_TYPE := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '[PR_SCP_MST_ALTER_BOM_ALL_BATCH]';
    D_EVENT_DATE := SYSDATE;

    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, NULL, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    V_ROWS := 0;


    BEGIN
        /* --------------------------------------------------------- */
        /* 실행 Logic START -- */
        /* --------------------------------------------------------- */

        /* SCM_MST_ALTER_BOM, SCM_MST_ALTER_BOM_MODEL 생성 */
        PR_SCP_MST_ALTER_BOM;
        /* 원본 SELECT 'PR_SCP_MST_ALTER_BOM', @rows; 는 호출부가 없는 배치의 진행 표시용 결과셋이라 */
        DBMS_OUTPUT.PUT_LINE('PR_SCP_MST_ALTER_BOM ' || TO_CHAR(V_ROWS));
        IF V_ROWS < 0 THEN
            GOTO RETURN_ERR_CODE;
        END IF;

        /* SCM_MST_MODEL_BOM 생성 */
        PR_SCP_MST_MODEL_BOM_ALL;
        DBMS_OUTPUT.PUT_LINE('PR_SCP_MST_MODEL_BOM_ALL ' || TO_CHAR(V_ROWS));
        IF V_ROWS < 0 THEN
            GOTO RETURN_ERR_CODE;
        END IF;

        /* SCM_MST_MODEL_BOM_EFFECTIVE 생성 */
        PR_SCP_MST_MODEL_BOM_EFF_ALL;
        DBMS_OUTPUT.PUT_LINE('PR_SCP_MST_MODEL_BOM_EFF_ALL ' || TO_CHAR(V_ROWS));
        IF V_ROWS < 0 THEN
            GOTO RETURN_ERR_CODE;
        END IF;

        /* --------------------------------------------------------- */
        /* 실행 Logic END -- */
        /* --------------------------------------------------------- */
        V_LOG_TYPE := 'TXN';

        N_LOG_COUNT := 1;
        V_LOG_MESSAGE := 'RUN ';
        V_DESCRIPTION := 'Process Complete... ';
        D_EVENT_DATE := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);


        <<RETURN_ERR_CODE>>
        IF V_ROWS < 0 THEN
            V_LOG_TYPE := 'ERROR';

            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);

            V_DESCRIPTION := 'ERROR_LINE : ' || SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 480);
            D_EVENT_DATE := SYSDATE;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

            RETURN;
        END IF;


    EXCEPTION
        WHEN OTHERS THEN
          /* ROLLBACK */
          /* ERROR LOG */
          V_LOG_TYPE := 'ERROR';
          V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
          V_DESCRIPTION := 'ERROR_LINE : ' || SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 480) ;
          D_EVENT_DATE := SYSDATE;
          PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, NULL, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

          RAISE;
    END;

    /* 종료 LOG */
    V_LOG_TYPE := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '[PR_SCP_MST_ALTER_BOM_ALL_BATCH]';
    D_EVENT_DATE := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, NULL, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);


END;

PROCEDURE         PR_SCP_MST_ALTER_BOM_BATCH
/* ============================================================
 * Program ID   : PR_SCP_MST_ALTER_BOM_BATCH
 * Description  : 대체 BOM 생성
 * Program History
 *------------------------------------------------------------
 * Date          In Charge      Description
 *------------------------------------------------------------
 * 2021.04.12    SEO            PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선
 *                              - SCP 대치BOM
 * 2023.06.22    KSG            [PJ20230691] LGES SCM 역량 강화 위한 SCP 개선과제 이행 : 활성화코드 분리 대응
 * 2023.07.25    HRK            [PJ20230691] LGES SCM 역량 강화 위한 SCP 개선과제 이행 : 활성화코드 분리 해외 대응 - PROD/ASSY 매핑정보 생성 호출 순서 변경
 * 2026.07.06    ZIONEX         [PJ202650304]  NextSCM Migration
 * ============================================================ */
AS
    V_PROGRAM_NAME  VARCHAR2(150 CHAR) := 'PR_SCP_MST_ALTER_BOM_BATCH';
    V_LOG_TYPE      VARCHAR2(30 CHAR);
    N_LOG_COUNT     INTEGER := 0;
    V_LOG_MESSAGE   VARCHAR2(1000 CHAR);
    V_DESCRIPTION   VARCHAR2(500 CHAR);
    D_EVENT_DATE    DATE;
BEGIN
    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '[PR_SCP_MST_ALTER_BOM_BATCH]';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, NULL, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    BEGIN
        /* 하위 6 BOM proc 순차 실행 (호출 순서 원본 유지: ASSY맵->ALTER->MODEL->MODEL ADD ASSY->EFF->EFF ADD ASSY) */
        PR_SCP_MST_CELL_PROD_ASSY_MAP;
        PR_SCP_MST_ALTER_BOM;
        PR_SCP_MST_MODEL_BOM;
        PR_SCP_MST_MODEL_BOM_ADD_ASSY;
        PR_SCP_MST_MODEL_BOM_EFF;
        PR_SCP_MST_MODEL_BOM_EFF_ADD_ASSY;


        V_LOG_TYPE    := 'TXN';
        V_LOG_MESSAGE := 'RUN ';
        V_DESCRIPTION := 'Process Complete... ';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, NULL, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    EXCEPTION
        WHEN OTHERS THEN
            ROLLBACK;
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := 'ERROR_LINE : ' || SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 480);
            D_EVENT_DATE  := SYSDATE;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, NULL, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
            RAISE;
    END;

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '[PR_SCP_MST_ALTER_BOM_BATCH]';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, NULL, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
END;

