 *                          분모 시간가동일수가 0 이면 성능가동률을 0 이 아닌 1로 반영
 * 2024.08.29   hrkim       PJ20239037 LGES CPS VOE 반영 및 고도화 : SOP 적용
 * 2024.09.10   hrkim       PJ20239037 LGES CPS VOE 반영 및 고도화 : CPS Formation 공정 처리 로직 추가 - lookupType : CPS_FORMATION_OPERATION
 * 2024.09.12   hrkim       PJ20239037 LGES CPS VOE 반영 및 고도화 : 조립 라인별 attribute8컬럼 SOP반영한 최대조업일수 추가 적재
 * 2024.09.12   hrkim       PJ20239037 LGES CPS VOE 반영 및 고도화 : SOP 적용 최대조업일수 임시테이블 데이터 타입 수정 (FLOAT)
 * 2024.09.25   hrkim       PJ20239037 LGES CPS VOE 반영 및 고도화 : SOP 정보 백업
 * 2024.09.26   hrkim       PJ20239037 LGES CPS VOE 반영 및 고도화 : RP/BP 라인별 loss attribute 컬럼값 (for TEEP 합계계산시 참조) 해당 버전의 값 그대로 적재
 * 2024.09.27   hrkim       PJ20239037 LGES CPS VOE 반영 및 고도화 : 전극 라인별 BASE 조업률/일수 수정
 * 2024.10.16   hrkim       PJ20239037 LGES CPS VOE 반영 및 고도화 : base sop 적용 안함
 * 2024.10.22   hrkim       PJ20239037 LGES CPS VOE 반영 및 고도화 : 조립 라인별 부하/가동/성능/양품/시간가동 일수 계산시 소수점 처리 수정 (임시테이블 numeric(20,10) -> float)
 * 2024.10.23   hrkim       PJ20239037 LGES CPS VOE 반영 및 고도화 : 조립 라인별 비조업 MSR_DDN 컬럼(WT_RT) null처리 / 전극 라인별 비조업 (MSR_DDN컬럼 MSR_NVL값과 일치시킴)
 * 2024.10.29   hrkim       PJ20239037 LGES CPS VOE 반영 및 고도화 : BP(사업계획)/RP(RollingPlan) 참조 기준 변경
 *                                                                   - BP : 실적년월 기준 전년도에 수립한 사업계획 버전의 전월계획 (BIZ_PLAN_USE_YN = 'Y'만 참조)
 *                                                                   - RP : 전전월에 수립한 전월계획 (BIZ_PLAN_USE_YN != 'Y'만 참조 - 사업계획 버전 참조하지 않음)
 *                                                                  * SOP 실적 (지표예외일자 적용된 실적의 최대조업일수 반영)
 *
 * 2025.01.06   hrkim       CPS_BATCH_PROC_RUN lookup 참조하여 next 버전 생성 프로시저 수행
 * 2025.01.14   hrkim       lookup CPS_BATCH_CRTN_THURSDAY(월별 CPS 배치 수행 기준 목요일) 적용
 *                           - 매월 마지막 목요일 기준으로 전/후 일요일에 1,2차 컷오프 수행 및 해당 주차의 SCP FN 생산계획 적용
 *                           - lookup이 등록된 경우 해당 목요일 기준으로 전/후 일요일에 1,2차 컷오프 수행 및 해당 주차의 SCP FN 생산계획 적용
 * 2025.02.05   hrkim       개선/목표율 관리 기능 삭제 - 해당 컬럼 참조 소스 삭제 (IPRV_GOL_DIVS_CD/IPRV_GOL_RT)
 * 2025.03.17   hrkim       CURSOR오류 - 커서 선언문 위치 변경
 * 2026.07.31   ZIONEX      [PJ202650304] NextSCM Migration
 *
 */
AS


    V_IS_MANUAL         VARCHAR2(1 CHAR)    := SUBSTR(P_IS_MANUAL, 1, 1);
    V_DIVISION_ID       VARCHAR2(30 CHAR)   := SUBSTR(P_DIVISION_ID, 1, 30);
    V_VER_ID            VARCHAR2(10 CHAR)   := NULL;
    V_VER_SEQ           NUMBER(3)           := NULL;
    V_LOSS_RSLT_YYYYMM  VARCHAR2(6 CHAR)    := NULL;
    V_BIZP_YYYY         VARCHAR2(4 CHAR)    := NULL;
    V_RP_YYYYMM         VARCHAR2(6 CHAR)    := NULL;

    /* 실행시간 확인용 */
    V_START_TIME        DATE                := SYSDATE;
    V_EXEC_TIME         VARCHAR2(10 CHAR)   := '';          /* '[00:00]'; */
    V_ELAPSED_SEC       NUMBER(10);

    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME      VARCHAR2(150 CHAR)  := 'PR_SCP_MST_CAPA_CUTF_2ND';      /* Proc별 이름 설정 */
    V_LOG_TYPE          VARCHAR2(30 CHAR);  /* START/END/ERROR/... */
    N_LOG_COUNT         NUMBER(10)          := 0;
    V_LOG_MESSAGE       VARCHAR2(1000 CHAR);
    V_DESCRIPTION       VARCHAR2(500 CHAR);
    D_EVENT_DATE        DATE;
    V_BATCH_USER        VARCHAR2(150 CHAR)  := 'scm_batch';


    N_CUTOFF_DAY        NUMBER(1)           := 0;
    N_NEXT_VER_RUN      NUMBER(1)           := 0;

BEGIN

    /*       SET TRANSACTION ISOLATION LEVEL READ COMMITTED;   Oracle 기본 격리수준이 READ COMMITTED 라 별도 설정 불요 */

/* procedure body -- start */


    BEGIN

        /* 시작 LOG  (START) */
        V_LOG_TYPE := 'START';
        V_LOG_MESSAGE := '##### Start of procedure #####';
        V_DESCRIPTION := '[' || NVL(V_DIVISION_ID, 'ALL') || ']';
        D_EVENT_DATE := SYSDATE;
        PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER);
        V_LOG_MESSAGE := NULL;

        DBMS_OUTPUT.PUT_LINE('------------------------------------------------------------------');
        /* MSSQL 문자열 + 는 피연산자가 NULL 이면 전체가 NULL 이다(Oracle || 는 흡수) -> V_IS_MANUAL 은 파라미터 유래라 NULL 가능하므로 CASE 로 1:1 재현. */
        DBMS_OUTPUT.PUT_LINE(CASE WHEN V_IS_MANUAL IS NULL THEN NULL ELSE '@V_IS_MANUAL			= ' || V_IS_MANUAL END);
        DBMS_OUTPUT.PUT_LINE('@V_DIVISION_ID		= ' || NVL(V_DIVISION_ID, 'ALL'));
        DBMS_OUTPUT.PUT_LINE('------------------------------------------------------------------');

        /* ---------------------------------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 컷오프 실행일 정보');
        /* ---------------------------------------------------------------------------------------------------------------- */
        /* 원본 IF OBJECT_ID('TEMPDB..#Cutoff_Date_Info') IS NOT NULL DROP TABLE #Cutoff_Date_Info; -> GTT 초기화 */
        DELETE FROM GT_SMCC2_CUTOFF_DATE_INFO;

        INSERT INTO GT_SMCC2_CUTOFF_DATE_INFO ( YYYYMM, YYYYMM_LAST_THU, YMD_1ST_CUTOFF, YMD_2ND_CUTOFF )
        WITH LAST_THU AS (
            SELECT YYYYMM
                 , MAX(YYYYMMDD) AS YYYYMM_LAST_THU
             FROM SCM_MST_BUCKET THU
            WHERE 1=1
              AND YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(SYSDATE, -1), 'YYYYMM') /* 전월 */
                             AND TO_CHAR(SYSDATE                , 'YYYYMM') /* 당월 */
              AND DAYOFWEEK = 'THU'
            GROUP BY YYYYMM
        ) , THU AS (
            SELECT LT.YYYYMM
                  ,NVL(BT.ATTRIBUTE1, LT.YYYYMM_LAST_THU)   AS YYYYMM_LAST_THU
             FROM LAST_THU  LT
                , SCM_ADM_LOOKUP_MASTER_DETAIL BT
            WHERE 1=1
              AND BT.LOOKUP_TYPE(+) = 'CPS_BATCH_CRTN_THURSDAY' /* 2025.01.14 배치수행 기준 목요일 */
              AND BT.SEGMENT1(+)        = LT.YYYYMM
              AND BT.VALID_YN(+)        = 'Y'
        )
        SELECT TH.YYYYMM
              ,TH.YYYYMM_LAST_THU                   /* 해당월 마지막 목요일 (기준 목요일) */
              ,MAX(BF.YYYYMMDD) AS YMD_1ST_CUTOFF   /* 해당월 1차 컷오프 수행 일요일 (기준 목요일 이전 일요일) */
              ,MIN(AF.YYYYMMDD) AS YMD_2ND_CUTOFF   /* 해당월 2차 컷오프 수행 일요일 (기준 목요일 이후 일요일) */
         FROM THU  TH
            , SCM_MST_BUCKET BF
            , SCM_MST_BUCKET AF
        WHERE 1=1
          AND BF.YYYYMMDD < TH.YYYYMM_LAST_THU
          AND BF.DAYOFWEEK = 'SUN'
          AND AF.YYYYMMDD > TH.YYYYMM_LAST_THU
          AND AF.DAYOFWEEK = 'SUN'
        GROUP BY TH.YYYYMM
              ,TH.YYYYMM_LAST_THU;


      /* 원본 IF @V_IS_MANUAL = 'Y' OR EXISTS(...) : 존재체크는 ROWNUM = 1 인라인뷰 COUNT 로 옮긴다. */
      SELECT COUNT(*)
        INTO N_CUTOFF_DAY
        FROM ( SELECT 1
                 FROM GT_SMCC2_CUTOFF_DATE_INFO
                WHERE YMD_2ND_CUTOFF = TO_CHAR(SYSDATE, 'YYYYMMDD') /* 2차 컷오프 수행일 */
                  AND ROWNUM = 1
             );

      IF V_IS_MANUAL = 'Y' /* 매뉴얼로 실행시 */
         OR
         N_CUTOFF_DAY > 0
      THEN /* ----------------------------------------------------------------------------------- 컷오프 수행일인 경우만 실행!!! */


        /* --------------------------------------------------------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### CPS Formation 공정'); /* 9/10 추가 */
        /* --------------------------------------------------------------------------------------------------------------------------------------- */
        /* 원본 if object_id('tempdb..#CPS_FORMATION_OPERATION') is not null drop table #CPS_FORMATION_OPERATION; -> GTT 초기화 */
        DELETE FROM GT_SMCC2_CPS_FORMATION_OP;

        INSERT INTO GT_SMCC2_CPS_FORMATION_OP ( OPERATION_ID, OPERATION_NAME )
         SELECT SEGMENT1        AS OPERATION_ID
               ,MAX(ATTRIBUTE1) AS OPERATION_NAME
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
         WHERE 1=1
           AND LOOKUP_TYPE = 'CPS_FORMATION_OPERATION'
           AND VALID_YN = 'Y'
        GROUP BY SEGMENT1;

        /*            -- TRY문 안쪽으로 커서 선언 위치 변경 2025.03.17
            DECLARE CAPA_VER_DATA  CURSOR FOR ... ;
            FETCH NEXT FROM CAPA_VER_DATA INTO @V_DIVISION_ID, @V_VER_ID, @V_VER_SEQ
            WHILE @@FETCH_STATUS = 0 -- DATA 가 존재하여 정상적으로 반환된 경우 : 0
            FETCH NEXT FROM CAPA_VER_DATA INTO @V_DIVISION_ID, @V_VER_ID, @V_VER_SEQ
            END  ----- // WHILE @@FETCH_STATUS = 0
            DEALLOCATE CAPA_VER_DATA;   -- 메모리 해제 - 2025.03.17 위치 변경  */
        FOR R_CAPA_VER_DATA IN ( SELECT DIVISION_ID
                                       ,VER_ID
                                       ,VER_SEQ
                                   FROM SCP_MST_CAPA_VERSION
                                  WHERE 1=1
                                    AND DIVISION_ID = NVL(P_DIVISION_ID, DIVISION_ID)
                                    AND VER_ID      >= TO_CHAR(ADD_MONTHS(SYSDATE, -1), 'YYYYMM')    /* ---!!! 2차 cutoff를 당월에 할수 없는 경우 !!! (ex: 202408월 : 8/25 1차, 9/1 2차) ------------------------- */
                                    AND PROG_STAT   = '1'
                                    /* 6/27 AND SCP_FIN_PLAN_ID IS NOT NULL --- scp prod plan 생산 정보가 있는 경우 */
                               ) LOOP

            V_DIVISION_ID   := R_CAPA_VER_DATA.DIVISION_ID;
            V_VER_ID        := R_CAPA_VER_DATA.VER_ID;
            V_VER_SEQ       := R_CAPA_VER_DATA.VER_SEQ;

            V_LOSS_RSLT_YYYYMM  := TO_CHAR(ADD_MONTHS(TO_DATE(V_VER_ID || '01', 'YYYYMMDD')         , -1)   , 'YYYYMM');
            V_BIZP_YYYY         := TO_CHAR(ADD_MONTHS(TO_DATE(V_LOSS_RSLT_YYYYMM || '01', 'YYYYMMDD'), -12) , 'YYYY');
            V_RP_YYYYMM         := TO_CHAR(ADD_MONTHS(TO_DATE(V_VER_ID || '01', 'YYYYMMDD')         , -2)   , 'YYYYMM');

            /* 아래 PRINT 의 + 피연산자는 커서가 돌려주는 NOT NULL 컬럼(DIVISION_ID/VER_ID/VER_SEQ)과 */
            DBMS_OUTPUT.PUT_LINE('------------------------------------------------------------------');
            DBMS_OUTPUT.PUT_LINE('@V_DIVISION_ID			= ' || V_DIVISION_ID);
            DBMS_OUTPUT.PUT_LINE('@V_VER_ID				= ' || V_VER_ID);
            DBMS_OUTPUT.PUT_LINE('@V_VER_SEQ				= ' || TO_CHAR(V_VER_SEQ));
            DBMS_OUTPUT.PUT_LINE('@V_LOSS_RSLT_YYYYMM		= ' || V_LOSS_RSLT_YYYYMM);
            DBMS_OUTPUT.PUT_LINE('@V_BIZP_YYY				= ' || V_BIZP_YYYY);
            DBMS_OUTPUT.PUT_LINE('@V_RP_YYYYMM				= ' || V_RP_YYYYMM);
            DBMS_OUTPUT.PUT_LINE('------------------------------------------------------------------');

            V_LOG_TYPE := 'TXN';
            V_LOG_MESSAGE := 'START - ' || V_DIVISION_ID;
            V_DESCRIPTION := '[' || V_DIVISION_ID || '::' || V_VER_ID || '::' || TO_CHAR(V_VER_SEQ) || ']';
            D_EVENT_DATE := SYSDATE;
            PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER);
            V_LOG_MESSAGE := NULL;


/* --------------------- Start 조립/팩 ------------------------------------------------------------------------------------------------------- */
/* --------------------- Start 조립/팩 ------------------------------------------------------------------------------------------------------- */
/* --------------------- Start 조립/팩 ------------------------------------------------------------------------------------------------------- */

            /* ------------------------------------------------------------------------------------------------------------------------------ */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 템프테이블 모델별 LOSS Cutoff 데이터 -  #SCP_MST_CAPA_LOSS_PLAN_MDL_CUTF');
            /* ------------------------------------------------------------------------------------------------------------------------------ */
            /* 원본 IF OBJECT_ID('TEMPDB..#SCP_MST_CAPA_LOSS_PLAN_MDL_CUTF') IS NOT NULL DROP TABLE #SCP_MST_CAPA_LOSS_PLAN_MDL_CUTF;
               에 이어지는 SELECT .. INTO .. WHERE 1=2 는 빈 골격을 만드는 구문이라 GTT 초기화(DELETE)로 대체한다. */
            DELETE FROM GT_SMCC2_LOSS_PLAN_MDL_CUTF;

            /* -------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 템프테이블 라인별 LOSS 합계 -  #LOSS_PLAN_LN_TTZM');
            /* -------------------------------------------------------------------------------------------------------------- */
            /* 원본 IF OBJECT_ID('TEMPDB..#LOSS_PLAN_LN_TTZM') ... DROP + SELECT .. INTO .. WHERE 1=2 (빈 골격) -> GTT 초기화 */
            DELETE FROM GT_SMCC2_LOSS_PLAN_LN_TTZM;

            /* ----------------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 모델별 Loss Plan 모델별 Cutoff Data -  #SCP_MST_CAPA_LOSS_PLAN_MDL_CUTF');
            /* ----------------------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SMCC2_LOSS_PLAN_MDL_CUTF ( MDL_ALTER_KEY, LN_ALTER_KEY, DIVISION_ID, MDL_NM, PLANT_ID, LINE_ID, OPERATION_ID, ELTR_LN_TP_CD
                                                    , COMPANY_ID, SITE_ID, FACTORY_ID, MSR_TP_CD, YYYYMM, PFRSLT_NVL, BASE_NVL, MSR_GR_CD, MSR_NVL, MSR_DDN )
            SELECT  DENSE_RANK() OVER (PARTITION BY 'A'
                                          ORDER BY LS.MDL_NM
                                                  ,LS.PLANT_ID
                                                  ,LS.FACTORY_ID
                                                  ,LS.LINE_ID
                                                  ,LS.OPERATION_ID
                                                  ,LS.ELTR_LN_TP_CD
                                                  ,LS.DIVISION_ID
                                                  ,LS.COMPANY_ID
                                                  ,LS.SITE_ID
                                                ) AS MDL_ALTER_KEY
                    ,DENSE_RANK() OVER (PARTITION BY 'A'
                                          ORDER BY LS.PLANT_ID
                                                  ,LS.FACTORY_ID
                                                  ,LS.LINE_ID
                                                  ,LS.OPERATION_ID
                                                  ,LS.ELTR_LN_TP_CD
                                                  ,LS.DIVISION_ID
                                                  ,LS.COMPANY_ID
                                                  ,LS.SITE_ID
                                                ) AS LN_ALTER_KEY
                    ,LS.DIVISION_ID
                    ,LS.MDL_NM
                    ,LS.PLANT_ID
                    ,LS.LINE_ID
                    ,LS.OPERATION_ID
                    ,LS.ELTR_LN_TP_CD
                    ,LS.COMPANY_ID
                    ,LS.SITE_ID
                    ,LS.FACTORY_ID
                    ,LS.MSR_TP_CD
                    ,LS.YYYYMM
                    ,LS.PFRSLT_NVL          AS PFRSLT_NVL
                    ,LS.BASE_NVL            AS BASE_NVL
                    /* 2025.02.05 개선/목표일 관리 기능 삭제 ,LS.IPRV_GOL_DIVS_CD */
                    /* 2025.02.05 개선/목표일 관리 기능 삭제 ,LS.IPRV_GOL_RT           AS IPRV_GOL_RT */
                    ,LS.MSR_GR_CD
                    ,LS.MSR_NVL             AS MSR_NVL
                    ,LS.MSR_DDN             AS MSR_DDN
            FROM SCP_MST_CAPA_LOSS_PLAN_MDL_CUTF LS
            WHERE 1=1
              AND LS.VER_ID      = V_VER_ID
              AND LS.VER_SEQ     = V_VER_SEQ
              AND LS.DIVISION_ID = V_DIVISION_ID;

            /* ----------------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 모델별 Loss Plan 모델별 Cutoff Data -  CPS Formation 공정 제외');
            /* 2024.09.10 CPS Formation 공정(Daily Production Capa) TEEP 대상에서 제외 */
            /* ----------------------------------------------------------------------------------------------------------------------- */
            /* 원본 DELETE LS FROM #.. LS INNER JOIN #CPS_FORMATION_OPERATION FO ON .. 는 Oracle 미지원 -> EXISTS 로 옮긴다. */
            DELETE FROM GT_SMCC2_LOSS_PLAN_MDL_CUTF LS
             WHERE 1=1
               AND EXISTS ( SELECT 1
                              FROM GT_SMCC2_CPS_FORMATION_OP FO
                             WHERE FO.OPERATION_ID = LS.OPERATION_ID );

            /* ------------------------------------------------------------------------------------------------------------------------------ */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' Speed Plan Cutoff 데이터 - #SCP_MST_CAPA_SPEED_PLAN_CUTF');
            /* ------------------------------------------------------------------------------------------------------------------------------ */
            /* 원본 IF OBJECT_ID('TEMPDB..#SCP_MST_CAPA_SPEED_PLAN_CUTF') IS NOT NULL DROP TABLE #SCP_MST_CAPA_SPEED_PLAN_CUTF    ; -> GTT 초기화 */
            DELETE FROM GT_SMCC2_SPEED_PLAN_CUTF;

            INSERT INTO GT_SMCC2_SPEED_PLAN_CUTF ( DIVISION_ID, MDL_NM, PLANT_ID, LINE_ID, OPERATION_ID, ELTR_LN_TP_CD
                                                 , COMPANY_ID, SITE_ID, FACTORY_ID, MSR_TP_CD, YYYYMM, BASE_QTY, QTY )
            SELECT DIVISION_ID
                  ,NICK_NAME    AS MDL_NM
                  ,PLANT_ID
                  ,LINE_ID
                  ,OPERATION_ID
                  ,ELTR_LN_TP_CD
                  ,COMPANY_ID
                  ,SITE_ID
                  ,FACTORY_ID
                  ,MSR_TP_CD
                  ,YYYYMM
                  ,CAST(BASE_QTY AS NUMBER) AS BASE_QTY
                  ,CAST(QTY AS NUMBER)      AS QTY
             FROM SCP_MST_CAPA_SPEED_PLAN_CUTF SP
            WHERE 1=1
              AND SP.VER_ID      = V_VER_ID
              AND SP.VER_SEQ     = V_VER_SEQ
              AND SP.DIVISION_ID = V_DIVISION_ID
              AND SP.MSR_TP_CD   = 'EQP_NBU';

            /* --------------------------------------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 모델별 Loss Plan 모델별 Cutoff Data -  #SCP_MST_CAPA_LOSS_PLAN_MDL_CUTF - 설비대수 추가');  /* 5/13 */
            /* --------------------------------------------------------------------------------------------------------------------------------------------- */
            INSERT INTO  GT_SMCC2_LOSS_PLAN_MDL_CUTF ( MDL_ALTER_KEY, LN_ALTER_KEY, DIVISION_ID, MDL_NM, PLANT_ID, LINE_ID, OPERATION_ID, ELTR_LN_TP_CD
                                                     , COMPANY_ID, SITE_ID, FACTORY_ID, MSR_TP_CD, YYYYMM, PFRSLT_NVL, BASE_NVL, MSR_GR_CD, MSR_NVL, MSR_DDN )
            SELECT LP.MDL_ALTER_KEY
                  ,LP.LN_ALTER_KEY
                  ,LP.DIVISION_ID
                  ,LP.MDL_NM
                  ,LP.PLANT_ID
                  ,LP.LINE_ID
                  ,LP.OPERATION_ID
                  ,LP.ELTR_LN_TP_CD
                  ,LP.COMPANY_ID
                  ,LP.SITE_ID
                  ,LP.FACTORY_ID
                  ,'EQP_NBU'                    AS MSR_TP_CD
                  ,LP.YYYYMM
                  ,0                            AS PFRSLT_NVL
                  ,SP.BASE_QTY                  AS BASE_NVL
                  /* 2025.02.05 개선/목표일 관리 기능 삭제 ,''                         AS IPRV_GOL_DIVS_CD */
                  /* 2025.02.05 개선/목표일 관리 기능 삭제 ,0                          AS IPRV_GOL_RT */
                  ,'-'                          AS MSR_GR_CD
                  ,SP.QTY                       AS MSR_NVL
                  ,NULL                         AS MSR_DDN
             FROM GT_SMCC2_LOSS_PLAN_MDL_CUTF LP
                , GT_SMCC2_SPEED_PLAN_CUTF SP
            WHERE 1=1
              AND SP.DIVISION_ID        = LP.DIVISION_ID
              AND SP.COMPANY_ID     = LP.COMPANY_ID
              AND SP.SITE_ID            = LP.SITE_ID
              AND SP.PLANT_ID           = LP.PLANT_ID
              AND SP.FACTORY_ID     = LP.FACTORY_ID
              AND SP.LINE_ID            = LP.LINE_ID
              AND SP.OPERATION_ID       = LP.OPERATION_ID
              AND SP.ELTR_LN_TP_CD  = LP.ELTR_LN_TP_CD
              AND SP.MDL_NM         = LP.MDL_NM
              AND SP.YYYYMM         = LP.YYYYMM
              AND SP.MSR_TP_CD      = 'EQP_NBU'
              AND LP.MSR_TP_CD = 'THRY_CAPA_D';

            /* --------------------------------------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 모델별 Loss Plan 모델별 Cutoff Data -  #SCP_MST_CAPA_LOSS_PLAN_MDL_CUTF - Base 추가');  /* - 2024.05.03 */
            /* --------------------------------------------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SMCC2_LOSS_PLAN_MDL_CUTF ( MDL_ALTER_KEY, LN_ALTER_KEY, DIVISION_ID, MDL_NM, PLANT_ID, LINE_ID, OPERATION_ID, ELTR_LN_TP_CD
                                                    , COMPANY_ID, SITE_ID, FACTORY_ID, MSR_TP_CD, YYYYMM, PFRSLT_NVL, BASE_NVL, MSR_GR_CD, MSR_NVL, MSR_DDN )
            SELECT   LS.MDL_ALTER_KEY
                    ,LS.LN_ALTER_KEY
                    ,LS.DIVISION_ID
                    ,LS.MDL_NM
                    ,LS.PLANT_ID
                    ,LS.LINE_ID
                    ,LS.OPERATION_ID
                    ,LS.ELTR_LN_TP_CD
                    ,LS.COMPANY_ID
                    ,LS.SITE_ID
                    ,LS.FACTORY_ID
                    ,LS.MSR_TP_CD
                    ,'BASE' AS YYYYMM
                    ,MAX(LS.PFRSLT_NVL)
                    ,MAX(LS.BASE_NVL)
                    /* 2025.02.05 개선/목표일 관리 기능 삭제 ,MAX(LS.IPRV_GOL_DIVS_CD) */
                    /* 2025.02.05 개선/목표일 관리 기능 삭제 ,MAX(LS.IPRV_GOL_RT) */
                    ,MAX(LS.MSR_GR_CD)
                    ,MAX(LS.BASE_NVL)   AS MSR_NVL
                    ,NULL               AS MSR_DDN
             FROM GT_SMCC2_LOSS_PLAN_MDL_CUTF LS
            GROUP BY LS.MDL_ALTER_KEY
                    ,LS.LN_ALTER_KEY
                    ,LS.DIVISION_ID
                    ,LS.MDL_NM
                    ,LS.PLANT_ID
                    ,LS.LINE_ID
                    ,LS.OPERATION_ID
                    ,LS.ELTR_LN_TP_CD
                    ,LS.COMPANY_ID
                    ,LS.SITE_ID
                    ,LS.FACTORY_ID
                    ,LS.MSR_TP_CD;

            /* ---------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 월별 일수 정보 -  #YYYYMM_DAYS_INFO');
            /* ---------------------------------------------------------------------------------------------------------------- */
            /* 원본 IF OBJECT_ID('TEMPDB..#YYYYMM_DAYS_INFO') IS NOT NULL DROP TABLE #YYYYMM_DAYS_INFO; -> GTT 초기화 */
            DELETE FROM GT_SMCC2_YYYYMM_DAYS_INFO;

            /*               CONVERT(DATE, 'YYYYMMDD', 112) -> TO_DATE(.., 'YYYYMMDD'), DATEADD(MM/YY, n, d) -> ADD_MONTHS(d, n/12*n). */
            INSERT INTO GT_SMCC2_YYYYMM_DAYS_INFO ( YYYYMM, YYYYMM_DDN )
            SELECT DISTINCT YYYYMM
                           ,CAST(
                                CASE WHEN YYYYMM = 'BASE'
                                     THEN ADD_MONTHS(TO_DATE(V_VER_ID || '01', 'YYYYMMDD'), 1) - TO_DATE(V_VER_ID || '01', 'YYYYMMDD')      /* 월일수 base (버전 당월) */
                                     WHEN LENGTH(YYYYMM) = 4
                                     THEN ADD_MONTHS(TO_DATE(YYYYMM || '0101', 'YYYYMMDD'), 12) - TO_DATE(YYYYMM || '0101', 'YYYYMMDD')     /* 년일수 */
                                     ELSE ADD_MONTHS(TO_DATE(YYYYMM || '01', 'YYYYMMDD'), 1) - TO_DATE(YYYYMM || '01', 'YYYYMMDD')          /* 월일수 */
                                END AS NUMBER)  AS YYYYMM_DDN
             FROM GT_SMCC2_LOSS_PLAN_MDL_CUTF LS
            WHERE 1=1
            UNION ALL
            SELECT 'RSLT'
                  ,CAST(ADD_MONTHS(TO_DATE(V_LOSS_RSLT_YYYYMM || '01', 'YYYYMMDD'), 1) - TO_DATE(V_LOSS_RSLT_YYYYMM || '01', 'YYYYMMDD') AS NUMBER) /* 실적 월 일수 (M-1월) */
              FROM DUAL;

            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 라인별 ALTER KEY 정보 - #ALTER_KEY_INFO_FOR_LN');
            /* ----------------------------------------------------------------------------------------------------------------- */
            /* 원본 IF OBJECT_ID('TEMPDB..#ALTER_KEY_INFO_FOR_LN') IS NOT NULL DROP TABLE #ALTER_KEY_INFO_FOR_LN -> GTT 초기화 */
            DELETE FROM GT_SMCC2_ALTER_KEY_INFO_LN;

            INSERT INTO GT_SMCC2_ALTER_KEY_INFO_LN ( LN_ALTER_KEY, PLANT_ID, LINE_ID, OPERATION_ID, ELTR_LN_TP_CD, DIVISION_ID, COMPANY_ID, SITE_ID, FACTORY_ID )
            SELECT DISTINCT
                   LS.LN_ALTER_KEY
                  ,LS.PLANT_ID
                  ,LS.LINE_ID
                  ,LS.OPERATION_ID
                  ,LS.ELTR_LN_TP_CD
                  ,LS.DIVISION_ID
                  ,LS.COMPANY_ID
                  ,LS.SITE_ID
                  ,LS.FACTORY_ID
            FROM GT_SMCC2_LOSS_PLAN_MDL_CUTF LS;


        /* ----------------------------------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' Capa 재계산 - SOP Master 정보 - #SCP_MST_CAPA_LINE_SOP');
        /* ----------------------------------------------------------------------------------------------------------------- */
        /* 원본 IF OBJECT_ID('TEMPDB..#SCP_MST_CAPA_LINE_SOP') IS NOT NULL DROP TABLE #SCP_MST_CAPA_LINE_SOP -> GTT 초기화 */
        DELETE FROM GT_SMCC2_LINE_SOP;

        /* SOP_DT 는 이름과 달리 실제 타입이 VARCHAR2(8 CHAR) YYYYMMDD 문자열이다(26ai ALL_TAB_COLS 실측).
           따라서 CONVERT(DATE, SP.SOP_DT, 112) 는 TO_DATE(SOP_DT, 'YYYYMMDD') 가 맞다. */
        INSERT INTO GT_SMCC2_LINE_SOP ( DIVISION_ID, COMPANY_ID, SITE_ID, PLANT_ID, FACTORY_ID, LINE_ID, OPERATION_ID, ELTR_LN_TP_CD
                                      , VALID_YN, SOP_DT, SOP_YM, CREATION_DATE, CREATED_BY, LAST_UPDATE_DATE, LAST_UPDATED_BY
                                      , SOP_DDN, SOP_YY, SOP_YY_DDN )
        SELECT SP.DIVISION_ID
              ,SP.COMPANY_ID
              ,SP.SITE_ID
              ,SP.PLANT_ID
              ,SP.FACTORY_ID
              ,SP.LINE_ID
              ,SP.OPERATION_ID
              ,SP.ELTR_LN_TP_CD
              ,SP.VALID_YN
              ,SP.SOP_DT
              ,SP.SOP_YM
              ,SP.CREATION_DATE
              ,SP.CREATED_BY
              ,SP.LAST_UPDATE_DATE
              ,SP.LAST_UPDATED_BY
              ,CAST(SP.SOP_DDN AS NUMBER)   AS SOP_DDN
              ,SUBSTR(SP.SOP_YM, 1, 4)      AS SOP_YY
              ,CAST( ADD_MONTHS(TO_DATE(SUBSTR(SP.SOP_YM, 1, 4) || '0101', 'YYYYMMDD'), 12)
                   - TO_DATE(SP.SOP_DT, 'YYYYMMDD') AS NUMBER)  AS SOP_YY_DDN   /* 년일수 */
          FROM SCP_MST_CAPA_LINE_SOP SP
         WHERE 1=1
           AND SP.DIVISION_ID   = V_DIVISION_ID
           AND SP.VALID_YN      = 'Y'
           AND SP.SOP_DT IS NOT NULL
           AND SP.SOP_YM IS NOT NULL
           AND SP.SOP_DDN IS NOT NULL
           AND SP.SOP_DDN      != 0;

            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' Capa 재계산 - 조립 라인별/월 일수 정보 WITH SOP - #YYYYMM_DAYS_INFO_APPLIED_SOP');
            /* 조립 : DIVISION_ID, COMPANY_ID, SITE_ID, PLANT_ID, FACTORY_ID, LINE_ID, OPERATION_ID, ELTR_LN_TP_CD */
            /* ----------------------------------------------------------------------------------------------------------------- */
            /* 원본 IF OBJECT_ID('TEMPDB..#YYYYMM_DAYS_INFO_APPLIED_SOP') IS NOT NULL DROP TABLE #YYYYMM_DAYS_INFO_APPLIED_SOP -> GTT 초기화 */
            DELETE FROM GT_SMCC2_YYYYMM_DAYS_SOP;

            INSERT INTO GT_SMCC2_YYYYMM_DAYS_SOP ( LN_ALTER_KEY, YYYYMM, YYYYMM_DDN )
            WITH CAPA_LINE_SOP AS (
                SELECT SP.DIVISION_ID
                      ,SP.COMPANY_ID
                      ,SP.SITE_ID
                      ,SP.PLANT_ID
                      ,SP.FACTORY_ID
                      ,SP.LINE_ID
                      ,SP.OPERATION_ID
                      ,SP.ELTR_LN_TP_CD
                      ,SP.SOP_DT
                      ,CASE WHEN YM.DV = 'Y'
                            THEN SP.SOP_YY
                            ELSE SP.SOP_YM
                        END AS SOP_YM
                      ,CASE WHEN YM.DV = 'Y'
                            THEN SP.SOP_YY_DDN
                            ELSE SP.SOP_DDN
                        END AS SOP_DDN
                 FROM GT_SMCC2_LINE_SOP SP
                    , (SELECT 'Y' AS DV FROM DUAL
                                  UNION ALL
                                  SELECT 'M' AS DV FROM DUAL) YM
                WHERE 1=1
                  AND 1=1
            )
            SELECT AK.LN_ALTER_KEY
                  ,DI.YYYYMM
                  ,CAST(    /* 2024.09.12 */
                   CASE WHEN SO.SOP_YM IS NOT NULL AND DI.YYYYMM != 'BASE'  /* 2024.10.16 base SOP 적용 안함 */
                        THEN SO.SOP_DDN
                        ELSE DI.YYYYMM_DDN
                    END AS NUMBER)      AS YYYYMM_DDN
             FROM GT_SMCC2_ALTER_KEY_INFO_LN AK
                 , GT_SMCC2_YYYYMM_DAYS_INFO DI
                 , CAPA_LINE_SOP SO
             WHERE 1=1
               AND 1=1
               AND SO.DIVISION_ID(+)    = AK.DIVISION_ID
               AND SO.COMPANY_ID(+)     = AK.COMPANY_ID
               AND SO.SITE_ID(+)        = AK.SITE_ID
               AND SO.PLANT_ID(+)       = AK.PLANT_ID
               AND SO.FACTORY_ID(+)     = AK.FACTORY_ID
               AND SO.LINE_ID(+)        = AK.LINE_ID
               AND SO.OPERATION_ID(+)   = AK.OPERATION_ID
               AND SO.ELTR_LN_TP_CD(+)  = AK.ELTR_LN_TP_CD
               AND SO.SOP_YM(+)         = CASE  WHEN DI.YYYYMM = 'BASE'
                                                        THEN V_VER_ID
                                                        ELSE DI.YYYYMM
                                                   END;

            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' LOSS 모델별 Cutoff 데이터 -  조업률/조업일수  ');
            /* 1차 Cutoff 및 SCP Final Plan 생산계획 적용 후 미래구간 UI에서 입력된 생산계획정보 포함하여 조업률/조업일수 재계산 */
            /* 조업일수 : SCP생산계획 / 생산 Capa(일) */
            /* 조업률 : 조업일수 / 최대조업일수 */
            /* ----------------------------------------------------------------------------------------------------------------- */
            /* 원본 IF OBJECT_ID('TEMPDB..#LOSS_MDL_CUTOFF_WITH_ALTER_KEY') IS NOT NULL DROP TABLE #LOSS_MDL_CUTOFF_WITH_ALTER_KEY -> GTT 초기화 */
            DELETE FROM GT_SMCC2_LOSS_MDL_CUTOFF_AK;

            INSERT INTO GT_SMCC2_LOSS_MDL_CUTOFF_AK ( MDL_ALTER_KEY, LN_ALTER_KEY, MSR_GR_CD, MSR_TP_CD, YYYYMM, MSR_NVL, MSR_DDN )
            WITH PROD_PLAN_THRY_CAPA AS (
                SELECT MDL_ALTER_KEY
                      ,LN_ALTER_KEY
                      ,YYYYMM
                      ,CAST(MAX(CASE WHEN LP.MSR_TP_CD = 'SCP_PROD_PLAN'    THEN LP.MSR_NVL ELSE 0. END) AS NUMBER) AS SCP_PROD_PLAN
                      ,CAST(MAX(CASE WHEN LP.MSR_TP_CD = 'PROD_CAPA_D'      THEN LP.MSR_NVL ELSE 0. END) AS NUMBER) AS PROD_CAPA_D
                 FROM GT_SMCC2_LOSS_PLAN_MDL_CUTF LP
                WHERE 1=1
                  AND MSR_TP_CD IN ('SCP_PROD_PLAN', 'PROD_CAPA_D')
                GROUP BY MDL_ALTER_KEY
                        ,LN_ALTER_KEY
                        ,YYYYMM
            )
            SELECT PC.MDL_ALTER_KEY
                  ,PC.LN_ALTER_KEY
                  ,'-'      AS MSR_GR_CD
                  ,'AV_RT'  AS MSR_TP_CD
                  ,PC.YYYYMM
                  /* 조업률 */
                  ,CAST(
                   CASE WHEN PC.YYYYMM = 'BASE'
                        THEN 1.       /* Base 조업률 100% */
                        ELSE CASE WHEN NVL(PC.PROD_CAPA_D,0) = 0
                                  THEN 0.
                                  ELSE  CAST(CAST(PC.SCP_PROD_PLAN / PC.PROD_CAPA_D AS NUMBER(20,10)) AS NUMBER)
                              END / DI.YYYYMM_DDN
                    END AS NUMBER(20,10))       AS MSR_NVL
                  /* 조업일수 */
                  ,CAST(
                   CASE WHEN PC.YYYYMM = 'BASE'
                        THEN DI.YYYYMM_DDN              /* BASE는 최대 조업일수 */
                        ELSE CASE WHEN NVL(PC.PROD_CAPA_D,0) = 0
                                  THEN 0.
                                  ELSE  PC.SCP_PROD_PLAN / PC.PROD_CAPA_D
                             END
                    END AS NUMBER(20,10))       AS MSR_DDN
             FROM PROD_PLAN_THRY_CAPA  PC
                , GT_SMCC2_YYYYMM_DAYS_SOP DI   /* 2024/8/29 SOP 적용 */
            WHERE 1=1
              AND DI.YYYYMM         = PC.YYYYMM
              AND DI.LN_ALTER_KEY   = PC.LN_ALTER_KEY;

            /* ---------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' LOSS 모델별 Cutoff 데이터 - PPM (for 양품가동률 일수 계산) ');
            /* ---------------------------------------------------------------------------------------------------------------- */
            /* 원본 IF OBJECT_ID('TEMPDB..#PPM') IS NOT NULL DROP TABLE #PPM; -> GTT 초기화 */
            DELETE FROM GT_SMCC2_PPM;

            INSERT INTO GT_SMCC2_PPM ( MDL_ALTER_KEY, LN_ALTER_KEY, MSR_TP_CD, YYYYMM, MSR_GR_CD, PPM )
            SELECT MDL_ALTER_KEY
                  ,LN_ALTER_KEY
                  ,'PPM'                                    AS MSR_TP_CD
                  ,YYYYMM
                  ,MSR_GR_CD
                  ,CAST(CAST(CAST(MSR_NVL AS NUMBER) / CAST(1440 AS NUMBER) AS NUMBER(20,10)) AS NUMBER) AS PPM
              FROM GT_SMCC2_LOSS_PLAN_MDL_CUTF
             WHERE 1=1
               AND MSR_TP_CD = 'THRY_CAPA_D';

            /* ---------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' LOSS 모델별 Cutoff 데이터 - 조업율/부하율/시간가동률/성능가동률/양품가동률 ');
            /* ---------------------------------------------------------------------------------------------------------------- */
            /* AV_RT    조업율 */
            /* LD_RT    부하율 */
            /* OP_RT    시간가동률 */
            /* PF_RT    성능가동률 */
            /* QL_RT    양품가동률 */
            /* ---------------------------------------------------------------------------------------------------------------- */
            /* 원본 IF OBJECT_ID('TEMPDB..#AV_LD_OP_PF_QL') IS NOT NULL DROP TABLE #AV_LD_OP_PF_QL; -> GTT 초기화 */
            DELETE FROM GT_SMCC2_AV_LD_OP_PF_QL;

            INSERT INTO GT_SMCC2_AV_LD_OP_PF_QL ( MDL_ALTER_KEY, LN_ALTER_KEY, MSR_TP_CD, YYYYMM, MSR_GR_CD, MSR_NVL, MSR_DDN, MSR_SEQ )
            SELECT MDL_ALTER_KEY
                  ,LN_ALTER_KEY
                  ,MSR_TP_CD
                  ,YYYYMM
                  ,MSR_GR_CD
                  ,MSR_NVL
                  ,CAST(MSR_DDN AS NUMBER) AS MSR_DDN
                  ,CASE WHEN MSR_TP_CD = 'AV_RT' THEN 1
                        WHEN MSR_TP_CD = 'LD_RT' THEN 2
                        WHEN MSR_TP_CD = 'OP_RT' THEN 3
                        WHEN MSR_TP_CD = 'PF_RT' THEN 4
                        WHEN MSR_TP_CD = 'QL_RT' THEN 5
                    END MSR_SEQ
             FROM GT_SMCC2_LOSS_PLAN_MDL_CUTF
            WHERE 1=1
              AND MSR_TP_CD IN ('LD_RT', 'OP_RT', 'PF_RT', 'QL_RT');

            /* 조업률/조업일수 추가 */
            INSERT INTO GT_SMCC2_AV_LD_OP_PF_QL ( MDL_ALTER_KEY, LN_ALTER_KEY, MSR_TP_CD, YYYYMM, MSR_GR_CD, MSR_NVL, MSR_DDN, MSR_SEQ )
            SELECT MDL_ALTER_KEY
                  ,LN_ALTER_KEY
                  ,MSR_TP_CD
                  ,YYYYMM
                  ,MSR_GR_CD
                  ,MSR_NVL
                  ,MSR_DDN  AS MSR_DDN
                  ,1        AS MSR_SEQ
             FROM GT_SMCC2_LOSS_MDL_CUTOFF_AK
            WHERE 1=1
              AND MSR_TP_CD = 'AV_RT';

            /* ---------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' Loss 모델별 Cutoff - 조업/부하/시간가동/성능가동/양품가동 일수');
            /* ---------------------------------------------------------------------------------------------------------------- */
            /* 일수정보 : MSR_DDN */
            /* AV_RT    조업율     : 조업일수      = 생산 Capa(월) / 생산 Capa(일) */
            /* LD_RT    부하율     : 부하일수      = 조업일수 * 부하율 */
            /* OP_RT    시간가동률   : 시간가동일수    = 부하일수 * 시간가동률 */
            /* PF_RT    성능가동률   : 성능가동일수    = 시간가동일수 * 성능가동률 */
            /* QL_RT    양품가동률   : 양품가동일수    = 성능가동일수 * PPM */
            /* PPM = 이론 Capa(일) / 1440 */
            /* 2024.10.22 소수점 처리 변경 #MSR_DDN (numeric(20,10) -> float) */
            /* ---------------------------------------------------------------------------------------------------------------- */
            /* 원본 IF OBJECT_ID('TEMPDB..#MSR_DDN') IS NOT NULL DROP TABLE #MSR_DDN; -> GTT 초기화 */
            DELETE FROM GT_SMCC2_MSR_DDN;


            INSERT INTO GT_SMCC2_MSR_DDN ( MDL_ALTER_KEY, LN_ALTER_KEY, MSR_TP_CD, YYYYMM, MSR_GR_CD, MSR_NVL, MSR_DDN, MSR_SEQ )
            WITH RECURSIVE_DATA ( MDL_ALTER_KEY, LN_ALTER_KEY, MSR_TP_CD, YYYYMM, MSR_GR_CD, MSR_NVL, MSR_DDN, MSR_SEQ ) AS (
                SELECT R.MDL_ALTER_KEY
                      ,R.LN_ALTER_KEY
                      ,R.MSR_TP_CD
                      ,R.YYYYMM
                      ,R.MSR_GR_CD
                      ,NVL(R.MSR_NVL, CAST(0 AS NUMBER))    AS MSR_NVL
                      ,NVL(R.MSR_DDN, CAST(0 AS NUMBER))    AS MSR_DDN
                      ,R.MSR_SEQ
                 FROM GT_SMCC2_AV_LD_OP_PF_QL  R
                WHERE R.MSR_SEQ = 1  /* AV_RT : 조업률/조업일수 */
                UNION ALL
                SELECT C.MDL_ALTER_KEY
                      ,C.LN_ALTER_KEY
                      ,C.MSR_TP_CD
                      ,C.YYYYMM
                      ,C.MSR_GR_CD
                      ,C.MSR_NVL
                      ,CASE WHEN C.MSR_TP_CD = 'QL_RT'
                            THEN NVL(P.MSR_DDN, CAST(0 AS NUMBER)) /* 성능가동일수 */
                            /* 2024.10.22 변경전 ELSE CONVERT(FLOAT, CONVERT(NUMERIC(20,10), P.MSR_DDN * ISNULL(C.MSR_NVL, 0.)) ) */
                            ELSE CAST(P.MSR_DDN * NVL(C.MSR_NVL, 0.) AS NUMBER)
                       END AS MSR_DDN
                      ,C.MSR_SEQ
                 FROM RECURSIVE_DATA P
                    , GT_SMCC2_AV_LD_OP_PF_QL C
                     WHERE 1=1
                       AND C.MDL_ALTER_KEY  = P.MDL_ALTER_KEY
                       AND C.LN_ALTER_KEY       = P.LN_ALTER_KEY
                       AND C.YYYYMM         = P.YYYYMM
                       AND C.MSR_SEQ        = P.MSR_SEQ + 1
            )
            SELECT C.MDL_ALTER_KEY
                  ,C.LN_ALTER_KEY
                  ,C.MSR_TP_CD
                  ,C.YYYYMM
                  ,C.MSR_GR_CD
                  ,CAST(C.MSR_NVL AS NUMBER)    AS MSR_NVL    /* 2024.10.22 numerci(20,10) to float */
                  ,CAST(                                      /* 2024.10.22 numerci(20,10) to float */
                   CASE WHEN C.MSR_TP_CD = 'QL_RT'
                        THEN C.MSR_DDN * PM.PPM  /* 양품가동일수 : 성능가동일수 * PPM */
                        ELSE C.MSR_DDN
                    END AS NUMBER)                              AS MSR_DDN
                  ,C.MSR_SEQ
             FROM RECURSIVE_DATA C
                    , GT_SMCC2_PPM PM
            WHERE 1=1
              AND PM.MDL_ALTER_KEY(+)   = C.MDL_ALTER_KEY
              AND PM.LN_ALTER_KEY(+)    = C.LN_ALTER_KEY
              AND PM.YYYYMM(+)          = C.YYYYMM;

            /* ----------------------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' Loss 모델별 Cutoff Data - 조업/부하/시간가동/성능가동/양품가동 비율/일수 수정');
            /* ----------------------------------------------------------------------------------------------------------------------------- */
            /* 원본 UPDATE LP SET .. FROM #.. LP INNER JOIN #MSR_DDN MD ON .. 는 Oracle 미지원.
               조인키(MDL_ALTER_KEY, MSR_TP_CD, YYYYMM)가 #MSR_DDN 에서 유일하지 않을 수 있어 MERGE 는 ORA-30926 위험이 있다. */
            UPDATE GT_SMCC2_LOSS_PLAN_MDL_CUTF LP
               SET ( LP.MSR_NVL
                   , LP.MSR_DDN ) = ( SELECT MD.MSR_NVL
                                            ,MD.MSR_DDN
                                        FROM GT_SMCC2_MSR_DDN MD
                                       WHERE MD.MDL_ALTER_KEY   = LP.MDL_ALTER_KEY
                                         AND MD.MSR_TP_CD       = LP.MSR_TP_CD
                                         AND MD.YYYYMM          = LP.YYYYMM
                                         AND ROWNUM = 1 )
             WHERE 1=1
               AND LP.MSR_TP_CD IN ('AV_RT', 'LD_RT', 'OP_RT', 'PF_RT', 'QL_RT')
               AND EXISTS ( SELECT 1
                              FROM GT_SMCC2_MSR_DDN MD
                             WHERE MD.MDL_ALTER_KEY = LP.MDL_ALTER_KEY
                               AND MD.MSR_TP_CD     = LP.MSR_TP_CD
                               AND MD.YYYYMM        = LP.YYYYMM );


        /* ----------------- BEGIN 라인별 합계 */
        /* ----------------- BEGIN 라인별 합계 */

            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' LOSS 라인별 합계 - 일수 정보 ');
            /* ----------------------------------------------------------------------------------------------------------------- */
            /* AV_RT : 조업율 */
            /* LD_RT : 부하율 */
            /* OP_RT : 시간가동률 */
            /* PF_RT : 성능가동률 */
            /* QL_RT : 양품가동률 */
            /* ----------------------------------------------------------------------------------------------------------------- */
            /* 원본 IF OBJECT_ID('TEMPDB..#MSR_DDN_LN_SUM') IS NOT NULL DROP TABLE #MSR_DDN_LN_SUM; -> GTT 초기화 */
            DELETE FROM GT_SMCC2_MSR_DDN_LN_SUM;

            INSERT INTO GT_SMCC2_MSR_DDN_LN_SUM ( LN_ALTER_KEY, MSR_TP_CD, YYYYMM, MDL_NM, MSR_DDN, MSR_DDN_LN_SUM )
            SELECT MC.LN_ALTER_KEY
                  ,MC.MSR_TP_CD
                  ,MC.YYYYMM
                  ,MC.MDL_NM
                  ,CAST(MC.MSR_DDN AS NUMBER)           AS MSR_DDN
                  ,CAST(
                    SUM(CAST(MC.MSR_DDN AS NUMBER)) OVER (PARTITION BY MC.LN_ALTER_KEY
                                                 , MC.MSR_TP_CD
                                                 , MC.YYYYMM) AS NUMBER)    AS MSR_DDN_LN_SUM
             FROM GT_SMCC2_LOSS_PLAN_MDL_CUTF  MC
            WHERE 1=1
              AND MSR_TP_CD IN ('AV_RT', 'LD_RT', 'OP_RT', 'PF_RT', 'QL_RT');

            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' LOSS 라인별 합계 - 비부하/비가동 ');
            /* ----------------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SMCC2_LOSS_PLAN_LN_TTZM(
                   LN_ALTER_KEY
                  ,MSR_TP_CD
                  ,YYYYMM
                  ,MSR_GR_CD
                  ,MSR_NVL
                  ,MSR_DDN
                )
            SELECT MC.LN_ALTER_KEY
                  ,MC.MSR_TP_CD
                  ,MC.YYYYMM
                  ,MC.MSR_GR_CD
                  ,CASE WHEN LS.MSR_DDN_LN_SUM = 0
                        THEN 0.
                        ELSE CAST(SUM(CAST(MC.MSR_NVL AS NUMBER)*LS.MSR_DDN) AS NUMBER)  / LS.MSR_DDN_LN_SUM
                   END  AS MSR_NVL
                  ,NULL AS MSR_DDN
             FROM GT_SMCC2_LOSS_PLAN_MDL_CUTF  MC
                , GT_SMCC2_MSR_DDN_LN_SUM LS
            WHERE 1=1
              AND LS.MSR_TP_CD  = CASE WHEN MC.MSR_GR_CD = 'NLD'
                                                   THEN 'AV_RT' /* 조업률 */
                                                   ELSE 'LD_RT' /* 부하율 */
                                              END
              AND LS.LN_ALTER_KEY = MC.LN_ALTER_KEY
              AND LS.YYYYMM     = MC.YYYYMM
              AND LS.MDL_NM     = MC.MDL_NM
              AND MC.MSR_GR_CD IN ('NLD', 'NOP') /* 비부하, 비가동 */
            GROUP BY MC.LN_ALTER_KEY
                    ,MC.MSR_TP_CD
                    ,MC.YYYYMM
                    ,MC.MSR_GR_CD
                    ,LS.MSR_DDN_LN_SUM;

            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' LOSS 라인별 합계 - 성능가동률/양품가동률/이론Capa(일)');
            /* ----------------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SMCC2_LOSS_PLAN_LN_TTZM(
                   LN_ALTER_KEY
                  ,MSR_TP_CD
                  ,YYYYMM
                  ,MSR_GR_CD
                  ,MSR_NVL
                  ,MSR_DDN
                )
            SELECT MC.LN_ALTER_KEY
                  ,MC.MSR_TP_CD
                  ,MC.YYYYMM
                  ,MC.MSR_GR_CD
                  ,CASE WHEN LS.MSR_DDN_LN_SUM = 0  AND MC.MSR_TP_CD = 'PF_RT'  /* 2024.08.21 분모(시간가동일수)가 0이면 성능가동률 1(100%)로 반영 */
                        THEN 1.
                        WHEN LS.MSR_DDN_LN_SUM = 0
                        THEN 0.
                        ELSE CAST(SUM(CAST(MC.MSR_NVL AS NUMBER)*LS.MSR_DDN) AS NUMBER) / LS.MSR_DDN_LN_SUM
                   END                  AS MSR_NVL
                  ,SM.MSR_DDN_LN_SUM    AS MSR_DDN
             FROM GT_SMCC2_LOSS_PLAN_MDL_CUTF  MC
                , GT_SMCC2_MSR_DDN_LN_SUM LS
                , GT_SMCC2_MSR_DDN_LN_SUM SM
            WHERE 1=1
              AND LS.MSR_TP_CD  = CASE WHEN MC.MSR_TP_CD = 'PF_RT'  THEN 'OP_RT' /* for 성능가동률 (가동시간) */
                                               WHEN MC.MSR_TP_CD = 'QL_RT'  THEN 'QL_RT' /* for 양품가동률 */
                                               ELSE 'PF_RT'                              /* for 이론 Capa(일) */
                                          END
              AND LS.LN_ALTER_KEY = MC.LN_ALTER_KEY
              AND LS.YYYYMM     = MC.YYYYMM
              AND LS.MDL_NM     = MC.MDL_NM
              AND SM.MSR_TP_CD(+)   = MC.MSR_TP_CD
              AND SM.LN_ALTER_KEY(+) = MC.LN_ALTER_KEY
              AND SM.YYYYMM(+)      = MC.YYYYMM
              AND SM.MDL_NM(+)      = MC.MDL_NM
              AND MC.MSR_TP_CD IN ('PF_RT', 'QL_RT', 'THRY_CAPA_D') /* 성능가동률, 양품가동률 , 이론 Capa(일) */
            GROUP BY MC.LN_ALTER_KEY
                    ,MC.MSR_TP_CD
                    ,MC.YYYYMM
                    ,MC.MSR_GR_CD
                    ,LS.MSR_DDN_LN_SUM
                    ,SM.MSR_DDN_LN_SUM;

            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' LOSS 라인별 합계 - 부하율/시간가동률 추가 ');
            /* ----------------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SMCC2_LOSS_PLAN_LN_TTZM (
                   LN_ALTER_KEY
                  ,MSR_TP_CD
                  ,YYYYMM
                  ,MSR_GR_CD
                  ,MSR_NVL
                  ,MSR_DDN
                )
            WITH MSR_DDN_INFO AS (
                  SELECT LN_ALTER_KEY
                        ,MSR_TP_CD
                        ,YYYYMM
                        ,CAST(NVL(SUM(MSR_DDN), 0.) AS NUMBER)  AS MSR_DDN
                   FROM GT_SMCC2_MSR_DDN_LN_SUM
                  WHERE 1=1
                    AND MSR_TP_CD IN ('LD_RT', 'OP_RT')
                  GROUP BY LN_ALTER_KEY
                          ,MSR_TP_CD
                          ,YYYYMM
            )
            SELECT LP.LN_ALTER_KEY
                  ,CASE WHEN LP.MSR_GR_CD = 'NLD'
                        THEN 'LD_RT'
                        ELSE 'OP_RT'
                    END                                                                             AS MSR_TP_CD
                  ,LP.YYYYMM
                  ,'-'                                                                              AS MSR_GR_CD
                  ,CAST(1 AS NUMBER) - CAST(NVL(SUM(CAST(LP.MSR_NVL AS NUMBER)), 0) AS NUMBER)      AS MSR_NVL
                  ,DI.MSR_DDN
            FROM GT_SMCC2_LOSS_PLAN_LN_TTZM LP
                 , MSR_DDN_INFO DI
            WHERE 1=1
              AND DI.LN_ALTER_KEY(+) = LP.LN_ALTER_KEY
              AND DI.MSR_TP_CD(+)    = CASE WHEN LP.MSR_GR_CD = 'NLD'
                                                    THEN 'LD_RT'
                                                    ELSE 'OP_RT'
                                                END
              AND DI.YYYYMM(+)       = LP.YYYYMM
              AND LP.MSR_GR_CD IN ('NLD', 'NOP')
            GROUP BY
                   LP.LN_ALTER_KEY
                  ,CASE WHEN LP.MSR_GR_CD = 'NLD'
                        THEN 'LD_RT'
                        ELSE 'OP_RT'
                    END
                  ,LP.YYYYMM
                  ,DI.MSR_DDN;

            /* ----------------------------------------------------------------------------------------------------------------- */
            /* 2024.08.13 설비대수 집계로직 변경 : 물동과 상관 없이 라인별 MAX */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' LOSS 라인별 합계 - 설비대수 (물동과 상관 없이 라인별 Max) ');
            /* ----------------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SMCC2_LOSS_PLAN_LN_TTZM(
                   LN_ALTER_KEY
                  ,MSR_GR_CD
                  ,MSR_TP_CD
                  ,YYYYMM
                  ,MSR_NVL
                  ,MSR_DDN
                )
            SELECT LS.LN_ALTER_KEY
                  ,'-'              AS MSR_GR_CD
                  ,LS.MSR_TP_CD     AS MSR_TP_CD
                  ,LS.YYYYMM
                  ,MAX(LS.MSR_NVL)  AS NSR_NVL
                  ,NULL             AS MSR_DDN
             FROM GT_SMCC2_LOSS_PLAN_MDL_CUTF LS
            WHERE 1=1
              AND LS.MSR_TP_CD = 'EQP_NBU'
            GROUP BY LS.LN_ALTER_KEY
                    ,LS.MSR_TP_CD
                    ,LS.YYYYMM;

            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' LOSS 라인별 합계 - 생산가동률 ');
            /* ----------------------------------------------------------------------------------------------------------------- */
            /* 라인별 합계 - PROD_OP_RT : 생산가동률  : 부하율 * 시간가동률 * 성능가동률 * 양품가동률 */
            /* 라인별 합계 - LD_RT : 부하율 */
            /* 라인별 합계 - OP_RT : 시간가동률 */
            /* 라인별 합계 - PF_RT : 성능가동률 */
            /* 라인별 합계 - QL_RT : 양품가동률 */
            /* ----------------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SMCC2_LOSS_PLAN_LN_TTZM(
                   LN_ALTER_KEY
                  ,MSR_TP_CD
                  ,YYYYMM
                  ,MSR_GR_CD
                  ,MSR_NVL
                )
            SELECT LP.LN_ALTER_KEY
                  ,'PROD_OP_RT' AS MSR_TP_CD
                  ,LP.YYYYMM
                  ,'-'          AS MSR_GR_CD
                  ,  CAST(MAX(CASE WHEN MSR_TP_CD = 'LD_RT' THEN MSR_NVL ELSE 0.0 END) AS NUMBER)
                   * CAST(MAX(CASE WHEN MSR_TP_CD = 'OP_RT' THEN MSR_NVL ELSE 0.0 END) AS NUMBER)
                   * CAST(MAX(CASE WHEN MSR_TP_CD = 'PF_RT' THEN MSR_NVL ELSE 0.0 END) AS NUMBER)
                   * CAST(MAX(CASE WHEN MSR_TP_CD = 'QL_RT' THEN MSR_NVL ELSE 0.0 END) AS NUMBER) AS MSR_NVL
             FROM GT_SMCC2_LOSS_PLAN_LN_TTZM LP
            WHERE 1=1
              AND MSR_TP_CD IN ('LD_RT', 'OP_RT', 'PF_RT', 'QL_RT')
            GROUP BY
                   LP.LN_ALTER_KEY
                  ,LP.YYYYMM;

            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' LOSS 라인별 합계 - 생산 CAPA(일)  ');
            /* ----------------------------------------------------------------------------------------------------------------- */
            /* 라인별 합계 - PROD_CAPA_D : 생산 CAPA(일) : 이론 Capa(일) * 생산가동률 */
            /* 라인별 합계 - PROD_OP_RT : 생산가동률  : 부하율 * 시간가동률 * 성능가동률 * 양품가동률 */
            /* 라인별 합계 - THRY_CAPA_D : 이론 CAPA(일) */
            /* ----------------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SMCC2_LOSS_PLAN_LN_TTZM(
                   LN_ALTER_KEY
                  ,MSR_TP_CD
                  ,YYYYMM
                  ,MSR_GR_CD
                  ,MSR_NVL
                )
            SELECT LP.LN_ALTER_KEY
                  ,'PROD_CAPA_D' AS MSR_TP_CD
                  ,LP.YYYYMM
                  ,'-'          AS MSR_GR_CD
                  ,  CAST(MAX(CASE WHEN MSR_TP_CD = 'PROD_OP_RT'  THEN MSR_NVL ELSE 0.0 END) AS NUMBER)
                   * CAST(MAX(CASE WHEN MSR_TP_CD = 'THRY_CAPA_D' THEN MSR_NVL ELSE 0.0 END) AS NUMBER) AS MSR_NVL
             FROM GT_SMCC2_LOSS_PLAN_LN_TTZM LP
            WHERE 1=1
              AND MSR_TP_CD IN ('PROD_OP_RT', 'THRY_CAPA_D')
            GROUP BY LP.LN_ALTER_KEY
                  ,LP.YYYYMM;

            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' LOSS 라인별 합계 - 조업률 = 조업일수 / 월(년)최대조업일수 ');
            /* ----------------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SMCC2_LOSS_PLAN_LN_TTZM(
                   LN_ALTER_KEY
                  ,MSR_TP_CD
                  ,YYYYMM
                  ,MSR_GR_CD
                  ,MSR_NVL
                  ,MSR_DDN
                )
            SELECT
                   AV.LN_ALTER_KEY
                  ,AV.MSR_TP_CD
                  ,AV.YYYYMM
                  ,'-'                                      AS MSR_GR_CD
                  ,CASE WHEN AV.YYYYMM = 'BASE'         /* base 조업률 100% */
                        THEN CAST(1 AS NUMBER)
                        /* 2024.05.17 임의로 조정하면 비조업+조업이 100%이 안됨. 계산상 안맞음.  WHEN MAX(AV.MSR_DDN_LN_SUM) > YM.YYYYMM_DDN */
                        /* 2024.05.17 임의로 조정하면 비조업+조업이 100%이 안됨. 계산상 안맞음.  THEN CONVERT(FLOAT, 1)           -- 최대 조업률 100% (초과시 100으로 맞춤) */
                        ELSE CAST(MAX(AV.MSR_DDN_LN_SUM) AS NUMBER) / YM.YYYYMM_DDN
                    END                                     AS MSR_NVL
                  ,CASE WHEN AV.YYYYMM = 'BASE'
                        THEN YM.YYYYMM_DDN
                        ELSE CAST(MAX(AV.MSR_DDN_LN_SUM) AS NUMBER)
                    END                                     AS MSR_DDN
             FROM GT_SMCC2_MSR_DDN_LN_SUM AV
                , GT_SMCC2_YYYYMM_DAYS_SOP YM   /* 2024/8/29 SOP 적용 */
                , GT_SMCC2_ALTER_KEY_INFO_LN AK
            WHERE 1=1
              AND YM.YYYYMM         = AV.YYYYMM
              AND YM.LN_ALTER_KEY   = AV.LN_ALTER_KEY
              AND AK.LN_ALTER_KEY   = AV.LN_ALTER_KEY
              AND MSR_TP_CD = 'AV_RT'
            GROUP BY AV.LN_ALTER_KEY
                    ,AV.MSR_TP_CD
                    ,AV.YYYYMM
                    ,YM.YYYYMM_DDN;

            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' LOSS 라인별 합계 - 생산 CAPA(월) ');
            /* ----------------------------------------------------------------------------------------------------------------- */
            /* 라인별 합계 - PROD_CAPA_M : 생산 CAPA(월) : 생산 CAPA(일) * 최대조업일수 */
            /* 최대조업일수 : 해당월 또는 해당년도의 Total 일수 */
            /* ----------------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SMCC2_LOSS_PLAN_LN_TTZM(
                   LN_ALTER_KEY
                  ,MSR_TP_CD
                  ,YYYYMM
                  ,MSR_GR_CD
                  ,MSR_NVL
                )
            SELECT LP.LN_ALTER_KEY
                  ,'PROD_CAPA_M'                AS MSR_TP_CD
                  ,LP.YYYYMM
                  ,'-'                          AS MSR_GR_CD
                  ,CAST(LP.MSR_NVL AS NUMBER) * YM.YYYYMM_DDN   AS MSR_NVL      /* 해당월/년 Total Capa (2024.05.09) */
             FROM GT_SMCC2_LOSS_PLAN_LN_TTZM LP
                , GT_SMCC2_YYYYMM_DAYS_SOP YM   /* 2024/8/29 SOP 적용 */
            WHERE 1=1
              AND YM.YYYYMM         = LP.YYYYMM
              AND YM.LN_ALTER_KEY   = LP.LN_ALTER_KEY
              AND MSR_TP_CD = 'PROD_CAPA_D';

            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' LOSS 라인별 합계 - SCP 생산계획 ');
            /* ----------------------------------------------------------------------------------------------------------------- */
            /* 라인별 합계 - SCP 생산 계획 = 생산 CAPA(일) * 조업률 * 월(년)일수 */
            /* 라인별 합계 - SCP 생산 계획 = 생산 CAPA(일) * 조업일수 */
            /* ----------------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SMCC2_LOSS_PLAN_LN_TTZM(
                   LN_ALTER_KEY
                  ,MSR_TP_CD
                  ,YYYYMM
                  ,MSR_GR_CD
                  ,MSR_NVL
                )
            SELECT LP.LN_ALTER_KEY
                  ,'SCP_PROD_PLAN' AS MSR_TP_CD
                  ,LP.YYYYMM
                  ,'-'          AS MSR_GR_CD
                  ,  CAST(MAX(CASE WHEN MSR_TP_CD = 'PROD_CAPA_D'  THEN MSR_NVL ELSE 0.0 END) AS NUMBER)
                   * CAST(MAX(CASE WHEN MSR_TP_CD = 'AV_RT'      THEN MSR_NVL ELSE 0.0 END) AS NUMBER)
                   * CAST(MAX(YM.YYYYMM_DDN) AS NUMBER)
                   AS MSR_NVL
             FROM GT_SMCC2_LOSS_PLAN_LN_TTZM LP
                , GT_SMCC2_YYYYMM_DAYS_SOP YM   /* 2024/8/29 SOP 적용 */
            WHERE 1=1
              AND YM.YYYYMM         = LP.YYYYMM
              AND YM.LN_ALTER_KEY   = LP.LN_ALTER_KEY
              AND MSR_TP_CD IN ('PROD_CAPA_D', 'AV_RT')
              AND LP.YYYYMM != 'BASE'
            GROUP BY LP.LN_ALTER_KEY
                    ,LP.YYYYMM;

            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' LOSS 라인별 합계 - TEEP ');
            /* ----------------------------------------------------------------------------------------------------------------- */
            /* 라인별 합계 - TEEP : 생산가동률 * 조업률 */
            /* ----------------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SMCC2_LOSS_PLAN_LN_TTZM(
                   LN_ALTER_KEY
                  ,MSR_TP_CD
                  ,YYYYMM
                  ,MSR_GR_CD
                  ,MSR_NVL
                )
            SELECT LP.LN_ALTER_KEY
                  ,'TEEP' AS MSR_TP_CD
                  ,LP.YYYYMM
                  ,'-'          AS MSR_GR_CD
                  ,  CAST(MAX(CASE WHEN MSR_TP_CD = 'PROD_OP_RT'  THEN MSR_NVL ELSE 0.0 END) AS NUMBER)
                   * CAST(MAX(CASE WHEN MSR_TP_CD = 'AV_RT'     THEN MSR_NVL ELSE 0.0 END) AS NUMBER) AS MSR_NVL
             FROM GT_SMCC2_LOSS_PLAN_LN_TTZM LP
            WHERE 1=1
              AND MSR_TP_CD IN ('PROD_OP_RT', 'AV_RT')
            GROUP BY LP.LN_ALTER_KEY
                  ,LP.YYYYMM;

            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' LOSS 라인별 합계 - 비조업 추가');
            /* ----------------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SMCC2_LOSS_PLAN_LN_TTZM(
                   LN_ALTER_KEY
                  ,MSR_TP_CD
                  ,YYYYMM
                  ,MSR_GR_CD
                  ,MSR_NVL
                )
            SELECT AK.LN_ALTER_KEY
                  ,LP.MSR_TP_CD
                  ,LP.YYYYMM
                  ,LP.MSR_GR_CD
                  ,LP.MSR_NVL
             FROM SCP_MST_CAPA_LOSS_PLAN_LN LP
                , GT_SMCC2_ALTER_KEY_INFO_LN AK
            WHERE 1=1
              AND AK.DIVISION_ID        = LP.DIVISION_ID
              AND AK.PLANT_ID       = LP.PLANT_ID
              AND AK.LINE_ID            = LP.LINE_ID
              AND AK.OPERATION_ID   = LP.OPERATION_ID
              AND AK.ELTR_LN_TP_CD  = LP.ELTR_LN_TP_CD
              AND AK.COMPANY_ID     = LP.COMPANY_ID
              AND AK.SITE_ID            = LP.SITE_ID
              AND AK.FACTORY_ID     = LP.FACTORY_ID
              AND LP.DIVISION_ID    =  V_DIVISION_ID
              AND LP.MSR_TP_CD     != 'WT_RT'           /* 물동없음(주문대기) 제외 */
              AND LP.MSR_GR_CD      = 'NAV';    /* 비조업 */

            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 라인별 Loss Plan Cutoff - WT_RT : 물동없음(주문대기) 추가');
            /* 물동없음(주문대기) = 최대조업일수(월일수) - 라인별 조업일수(AV_RT) - 비조업일수합(MC_RT + SD_RT + TD_RT) */
            /* ----------------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SMCC2_LOSS_PLAN_LN_TTZM(
                   LN_ALTER_KEY
                  ,MSR_TP_CD
                  ,YYYYMM
                  ,MSR_GR_CD
                  ,MSR_NVL
                  ,MSR_DDN
                )
            SELECT   LP.LN_ALTER_KEY
                    ,'WT_RT'    AS MSR_TP_CD
                    ,LP.YYYYMM
                    ,'NAV'      AS MSR_GR_CD
                    ,   CAST(NVL(MAX(CASE WHEN LP.MSR_TP_CD = 'AV_RT'       THEN YM.YYYYMM_DDN                  ELSE 0.  END), 0.) AS NUMBER)
                      - CAST(NVL(MAX(CASE WHEN LP.MSR_TP_CD = 'AV_RT'       THEN CAST(LP.MSR_DDN AS NUMBER)     ELSE 0.  END), 0.) AS NUMBER)
                      - CAST(NVL(SUM(CASE WHEN LP.MSR_GR_CD = 'NAV'         THEN CAST(LP.MSR_NVL AS NUMBER)     ELSE 0.  END), 0.) AS NUMBER)   AS MSR_NVL  /* 20240726 비조업일 SUM 적용 */
                    ,NULL       AS MSR_DDN  /* 2024.10.23 조립 비조업 MSR_DDN null 처리 (MSR_NVL값이 일수임) */
               FROM GT_SMCC2_LOSS_PLAN_LN_TTZM LP
            , GT_SMCC2_YYYYMM_DAYS_SOP YM   /* 2024/8/29 SOP 적용 */
              WHERE 1=1
                AND YM.YYYYMM       = LP.YYYYMM
                AND YM.LN_ALTER_KEY = LP.LN_ALTER_KEY
                AND (LP.MSR_TP_CD = 'AV_RT' OR LP.MSR_GR_CD = 'NAV')
            GROUP BY LP.LN_ALTER_KEY
                    ,LP.YYYYMM;

            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' LOSS 라인별 합계 - PPM 추가');
            /* PPM = 이론 Capa(일) / 1440 */
            /* ----------------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SMCC2_LOSS_PLAN_LN_TTZM(
                   LN_ALTER_KEY
                  ,MSR_TP_CD
                  ,YYYYMM
                  ,MSR_GR_CD
                  ,MSR_NVL
                )
            SELECT   LP.LN_ALTER_KEY
                    ,'PPM'                                                  AS MSR_TP_CD
                    ,LP.YYYYMM
                    ,'-'                                                    AS MSR_GR_CD
                    ,CAST(LP.MSR_NVL AS NUMBER) / CAST(1440 AS NUMBER)      AS MSR_NVL
               FROM GT_SMCC2_LOSS_PLAN_LN_TTZM LP
              WHERE 1=1
                AND LP.MSR_TP_CD = 'THRY_CAPA_D';   /* 이론 Capa(일) */

            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' LOSS 라인별 합계 - Tact Time(대당 평균) 추가');
            /* Tact Time = 60 / (PPM / 설비대수) */
            /* ----------------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SMCC2_LOSS_PLAN_LN_TTZM(
                   LN_ALTER_KEY
                  ,MSR_TP_CD
                  ,YYYYMM
                  ,MSR_GR_CD
                  ,MSR_NVL
                )
            SELECT   LP.LN_ALTER_KEY
                    ,'TACT_TIME'        AS MSR_TP_CD
                    ,LP.YYYYMM
                    ,'-'                AS MSR_GR_CD
                    ,CASE WHEN NVL(MAX(CASE WHEN LP.MSR_TP_CD = 'PPM' THEN LP.MSR_NVL ELSE 0. END),0) = 0
                               OR
                               NVL(MAX(CASE WHEN LP.MSR_TP_CD = 'EQP_NBU' THEN LP.MSR_NVL ELSE 0. END),0) = 0
                          THEN 0.
                          ELSE CAST(60 AS NUMBER)
                                    / ( CAST(CAST(MAX(CASE WHEN LP.MSR_TP_CD = 'PPM'        THEN LP.MSR_NVL ELSE 0. END) AS NUMBER(20,10)) AS NUMBER)
                                      / CAST(CAST(MAX(CASE WHEN LP.MSR_TP_CD = 'EQP_NBU'    THEN LP.MSR_NVL ELSE 0. END) AS NUMBER(20,10)) AS NUMBER)
                                      )
                     END                AS MSR_NVL
               FROM GT_SMCC2_LOSS_PLAN_LN_TTZM LP
              WHERE 1=1
                AND LP.MSR_TP_CD IN ('EQP_NBU', 'PPM')
            GROUP BY LP.LN_ALTER_KEY
                    ,LP.YYYYMM;

        /* ----------------- End 라인별 합계 */
        /* ----------------- End 라인별 합계 */

        /* ----------------- STart 라인별 합계 PRVS */
        /* ----------------- STart 라인별 합계 PRVS */

            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' LOSS 라인별 PRVS  - 이전 버전 Capa Plan의 당월 계획 ');
            /* ----------------------------------------------------------------------------------------------------------------- */
            /* 원본 IF OBJECT_ID('TEMPDB..#PRVS_CAPA_LOSS_PLAN') IS NOT NULL DROP TABLE #PRVS_CAPA_LOSS_PLAN; -> GTT 초기화 */
            DELETE FROM GT_SMCC2_PRVS_CAPA_LOSS_PLAN;

            /* 원본 SELECT TOP 1 .. ORDER BY .. -> 인라인뷰에서 정렬한 뒤 바깥에서 ROWNUM = 1 (CV-026). */
            INSERT INTO GT_SMCC2_PRVS_CAPA_LOSS_PLAN ( DIVISION_ID, PLANT_ID, LINE_ID, OPERATION_ID, ELTR_LN_TP_CD, COMPANY_ID, SITE_ID, FACTORY_ID
                                                     , MSR_TP_CD, MSR_GR_CD, YYYYMM, MSR_NVL, MSR_DDN
                                                     , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8
                                                     , PRVS_VER_ID, PRVS_VER_SEQ, REF_YYYYMM )
            WITH PRVS_CAPA_VERSION AS (
                SELECT PRVS_VER_ID
                     , PRVS_VER_SEQ
                     , DIVISION_ID
                     , PROG_STAT
                  /*                     NOT NULL 이라(ALL_TAB_COLS 실측) MSSQL 에서도 값이 바뀌지 않는 무효 호출이다. */
                  FROM ( SELECT VER_ID                  AS PRVS_VER_ID
                              , NVL(VER_SEQ, 0)     AS PRVS_VER_SEQ
                              , DIVISION_ID             AS DIVISION_ID
                              , PROG_STAT
                           FROM SCP_MST_CAPA_VERSION PV
                          WHERE 1=1
                            AND DIVISION_ID                 = V_DIVISION_ID
                            AND VER_ID                      = V_RP_YYYYMM       /* M-2월에 수립한 계획 */
                            AND PROG_STAT                   = '2'               /* 이전 2차 컷오프 완료된 최종 버전 */
                            AND NVL(BIZ_PLAN_USE_YN,'N')    != 'Y'              /* 사업계획이 아니면 RP로 간주함 */
                          ORDER BY VER_ID   DESC
                                 , VER_SEQ  DESC )
                 WHERE ROWNUM = 1
            )
            SELECT LP.DIVISION_ID
                  ,LP.PLANT_ID
                  ,LP.LINE_ID
                  ,LP.OPERATION_ID
                  ,LP.ELTR_LN_TP_CD
                  ,LP.COMPANY_ID
                  ,LP.SITE_ID
                  ,LP.FACTORY_ID
                  ,LP.MSR_TP_CD
                  ,LP.MSR_GR_CD
                  ,'PRVS'                                   AS YYYYMM
                  ,CAST(LP.MSR_NVL  AS NUMBER(20,10))       AS MSR_NVL
                  ,CAST(LP.MSR_DDN  AS NUMBER(20,10))       AS MSR_DDN
                  ,LP.ATTRIBUTE1
                  ,LP.ATTRIBUTE2    /* 2024.09.24 추가 */
                  ,LP.ATTRIBUTE3    /* 2024.09.24 추가 */
                  ,LP.ATTRIBUTE4    /* 2024.09.24 추가 */
                  ,LP.ATTRIBUTE5    /* 2024.09.24 추가 */
                  ,LP.ATTRIBUTE6    /* 2024.09.24 추가 */
                  ,LP.ATTRIBUTE7    /* 2024.09.24 추가 */
                  ,LP.ATTRIBUTE8    /* 2024.09.24 추가 */
                  ,LP.VER_ID        AS PRVS_VER_ID
                  ,LP.VER_SEQ       AS PRVS_VER_SEQ
                  ,LP.YYYYMM        AS REF_YYYYMM /* 2024.09.24 추가 */
             FROM SCP_MST_CAPA_LOSS_PLAN_LN_CUTF  LP
                , PRVS_CAPA_VERSION PV
            WHERE 1=1
              AND PV.PRVS_VER_ID        = LP.VER_ID
              AND PV.PRVS_VER_SEQ   = LP.VER_SEQ
              AND PV.DIVISION_ID        = LP.DIVISION_ID
              AND LP.YYYYMM = V_LOSS_RSLT_YYYYMM;  /* 6/10 M-1월(실적과 동일 년월) 계획 */

        /* ----------------- END 라인별 합계 PRVS */
        /* ----------------- END 라인별 합계 PRVS */


        /* ----------------- STart 라인별 합계 BIZP 사업계획 */
        /* ----------------- STart 라인별 합계 BIZP 사업계획 */

            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' LOSS 라인별 BIZP  - 사업계획버전 Capa Plan의 당월 계획 ');
            /* ----------------------------------------------------------------------------------------------------------------- */
            /* 원본 IF OBJECT_ID('TEMPDB..#BIZP_CAPA_LOSS_PLAN') IS NOT NULL DROP TABLE #BIZP_CAPA_LOSS_PLAN; -> GTT 초기화 */
            DELETE FROM GT_SMCC2_BIZP_CAPA_LOSS_PLAN;

            INSERT INTO GT_SMCC2_BIZP_CAPA_LOSS_PLAN ( DIVISION_ID, PLANT_ID, LINE_ID, OPERATION_ID, ELTR_LN_TP_CD, COMPANY_ID, SITE_ID, FACTORY_ID
                                                     , MSR_TP_CD, MSR_GR_CD, YYYYMM, MSR_NVL, MSR_DDN
                                                     , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8
                                                     , BIZP_VER_ID, BIZP_VER_SEQ, REF_YYYYMM )
            WITH BIZP_CAPA_VERSION AS (
                SELECT BIZP_VER_ID
                     , BIZP_VER_SEQ
                     , DIVISION_ID
                     , PROG_STAT
                  /*                     NOT NULL 이라(ALL_TAB_COLS 실측) MSSQL 에서도 값이 바뀌지 않는 무효 호출이다. */
                  FROM ( SELECT VER_ID                  AS BIZP_VER_ID
                              , NVL(VER_SEQ, 0)     AS BIZP_VER_SEQ
                              , DIVISION_ID             AS DIVISION_ID
                              , PROG_STAT
                           FROM SCP_MST_CAPA_VERSION PV
                          WHERE 1=1
                            AND DIVISION_ID     = V_DIVISION_ID
                            AND VER_ID          LIKE V_BIZP_YYYY || '%'     /* 2024/10/29 전월기준 전년도에 수립한 사업계획 버전 */
                            AND PROG_STAT       = '2'   /* 이전 2차 컷오프 완료된 버전 */
                            AND BIZ_PLAN_USE_YN = 'Y'   /* 사업계획 */
                          ORDER BY VER_ID   DESC
                                 , VER_SEQ  DESC )
                 WHERE ROWNUM = 1
            )
            SELECT LP.DIVISION_ID
                  ,LP.PLANT_ID
                  ,LP.LINE_ID
                  ,LP.OPERATION_ID
                  ,LP.ELTR_LN_TP_CD
                  ,LP.COMPANY_ID
                  ,LP.SITE_ID
                  ,LP.FACTORY_ID
                  ,LP.MSR_TP_CD
                  ,LP.MSR_GR_CD
                  ,'BIZP'           AS YYYYMM
                  ,CAST(LP.MSR_NVL AS NUMBER(20,10))    AS MSR_NVL
                  ,CAST(LP.MSR_DDN AS NUMBER(20,10))    AS MSR_DDN
                  ,LP.ATTRIBUTE1
                  ,LP.ATTRIBUTE2    /* 2024.09.24 추가 */
                  ,LP.ATTRIBUTE3    /* 2024.09.24 추가 */
                  ,LP.ATTRIBUTE4    /* 2024.09.24 추가 */
                  ,LP.ATTRIBUTE5    /* 2024.09.24 추가 */
                  ,LP.ATTRIBUTE6    /* 2024.09.24 추가 */
                  ,LP.ATTRIBUTE7    /* 2024.09.24 추가 */
                  ,LP.ATTRIBUTE8    /* 2024.09.24 추가 */
                  ,LP.VER_ID        AS BIZP_VER_ID
                  ,LP.VER_SEQ       AS BIZP_VER_SEQ
                  ,LP.YYYYMM        AS REF_YYYYMM /* 2024.09.24 추가 */
             FROM SCP_MST_CAPA_LOSS_PLAN_LN_CUTF LP
                , BIZP_CAPA_VERSION BV
            WHERE 1=1
              AND BV.BIZP_VER_ID        = LP.VER_ID
              AND BV.BIZP_VER_SEQ   = LP.VER_SEQ
              AND BV.DIVISION_ID        = LP.DIVISION_ID
              AND LP.YYYYMM = V_LOSS_RSLT_YYYYMM; /* 실적과 동일월  6/11 --- @V_VER_ID  -- 당월 계획 (사업계획 Capa버전의 당월계획) */

        /* ----------------- End  라인별 합계 BIZP 사업계획 */
        /* ----------------- End  라인별 합계 BIZP 사업계획 */


        /* ----------------- START 라인별 합계 실적 */
        /* ----------------- START 라인별 합계 실적 */

            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' LOSS 라인별 실적(M-1)  - 비부하/비가동/성능가동률/양품가동률 ');
            /* ----------------------------------------------------------------------------------------------------------------- */
            /* 원본 IF OBJECT_ID('TEMPDB..#LOSS_RSLT_WITH_ALTER_KEY') IS NOT NULL DROP TABLE #LOSS_RSLT_WITH_ALTER_KEY -> GTT 초기화 */
            DELETE FROM GT_SMCC2_LOSS_RSLT_AK;

            INSERT INTO GT_SMCC2_LOSS_RSLT_AK ( LN_ALTER_KEY, MSR_GR_CD, MSR_TP_CD, YYYYMM, MSR_NVL, YYYYMM_DDN )
            SELECT AK.LN_ALTER_KEY
                  ,LR.LOSS_GR_CD    AS MSR_GR_CD
                  ,CASE WHEN LR.LOSS_CD = 'QL_RT_LN'
                        THEN 'QL_RT'
                        ELSE LR.LOSS_CD
                    END             AS MSR_TP_CD
                  ,'RSLT'           AS YYYYMM
                  ,CAST(
                    CASE WHEN LR.LOSS_GR_CD = 'NAV'
                        THEN CAST(LR.LOSS_RT AS NUMBER) * CAST(LR.ATTRIBUTE1 AS NUMBER)  /* 2024/10/29 지표 제외 적용 실적 최대조업일수 적용 */
                        ELSE LR.LOSS_RT
                    END AS NUMBER(20,10))                           AS MSR_NVL  /* 5/14 비조업 일수로 반영 필요 */
                  ,MAX(CASE WHEN LR.LOSS_CD = 'AV_RT'
                            THEN CAST(LR.ATTRIBUTE1 AS NUMBER)
                            ELSE NULL
                        END)  OVER (PARTITION BY AK.LN_ALTER_KEY)   AS YYYYMM_DDN   /* 2024/10/29 지표 제외 적용 실적 최대조업일수 */
             FROM SCM_DNM_LOSS_LN_MMLY LR
                , GT_SMCC2_ALTER_KEY_INFO_LN AK
            WHERE 1=1
              AND AK.DIVISION_ID      = LR.DIVISION_ID
              AND AK.PLANT_ID     = LR.PLANT_ID
              AND AK.LINE_ID          = LR.LINE_ID
              AND AK.OPERATION_ID  = LR.OPERATION_ID
              AND AK.ELTR_LN_TP_CD = LR.ELTR_LN_TP_CD
              AND AK.COMPANY_ID   = LR.COMPANY_ID
              AND AK.SITE_ID          = LR.SITE_ID
              AND AK.FACTORY_ID   = LR.FACTORY_ID
              AND LR.LOSS_YM        = V_LOSS_RSLT_YYYYMM
              AND LR.PERD_DIVS_CD   = '1';  /* M-1월 1개월실적 */

            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' LOSS 라인별 실적(M-1)  - SOP적용된 실적(RSLT) 최대조업일수 Update'); /* 2024/10/29 */
            /* ----------------------------------------------------------------------------------------------------------------- */

            UPDATE GT_SMCC2_YYYYMM_DAYS_SOP SO
               SET SO.YYYYMM_DDN = ( SELECT AV.YYYYMM_DDN
                                       FROM GT_SMCC2_LOSS_RSLT_AK AV
                                      WHERE AV.YYYYMM           = SO.YYYYMM
                                        AND AV.LN_ALTER_KEY     = SO.LN_ALTER_KEY
                                        AND AV.MSR_TP_CD        = 'AV_RT'
                                        AND ROWNUM = 1 )
             WHERE 1=1
               AND EXISTS ( SELECT 1
                              FROM GT_SMCC2_LOSS_RSLT_AK AV
                             WHERE AV.YYYYMM        = SO.YYYYMM
                               AND AV.LN_ALTER_KEY  = SO.LN_ALTER_KEY
                               AND AV.MSR_TP_CD     = 'AV_RT' );

            /* ---------------------------------------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' LOSS 라인별 실적(M-1) - 설비대수/TactTime(대당평균)/PPM/이론Capa(일) 추가 ');
            /* 2024/06/10 M-2월에 계획한 M-1월 계획 */
            /* ----------------------------------------------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SMCC2_LOSS_RSLT_AK ( LN_ALTER_KEY, MSR_GR_CD, MSR_TP_CD, YYYYMM, MSR_NVL, YYYYMM_DDN )
            SELECT AK.LN_ALTER_KEY
                  ,LP.MSR_GR_CD
                  ,LP.MSR_TP_CD
                  ,'RSLT'           AS YYYYMM
                  ,LP.MSR_NVL
                  ,NULL             AS YYYYMM_DDN
            FROM GT_SMCC2_PRVS_CAPA_LOSS_PLAN  LP
                , GT_SMCC2_ALTER_KEY_INFO_LN AK
            WHERE 1=1
              AND AK.DIVISION_ID        = LP.DIVISION_ID
              AND AK.PLANT_ID       = LP.PLANT_ID
              AND AK.LINE_ID            = LP.LINE_ID
              AND AK.OPERATION_ID   = LP.OPERATION_ID
              AND AK.ELTR_LN_TP_CD  = LP.ELTR_LN_TP_CD
              AND AK.COMPANY_ID     = LP.COMPANY_ID
              AND AK.SITE_ID            = LP.SITE_ID
              AND AK.FACTORY_ID     = LP.FACTORY_ID
              AND LP.MSR_TP_CD IN ('EQP_NBU', 'TACT_TIME', 'PPM', 'THRY_CAPA_D');

            /* ---------------------------------------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' LOSS 라인별 실적(M-1) - 생산 Capa(일) 추가 ');
            /* ----------------------------------------------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SMCC2_LOSS_RSLT_AK ( LN_ALTER_KEY, MSR_GR_CD, MSR_TP_CD, YYYYMM, MSR_NVL, YYYYMM_DDN )
            SELECT LN_ALTER_KEY
                  ,'-'              AS MSR_GR_CD
                  ,'PROD_CAPA_D'    AS MSR_TP_CD
                  ,'RSLT'           AS YYYYMM
                  ,  CAST(MAX(CASE WHEN MSR_TP_CD = 'PROD_OP_RT'  THEN MSR_NVL ELSE NULL END) AS NUMBER)
                   * CAST(MAX(CASE WHEN MSR_TP_CD = 'THRY_CAPA_D' THEN MSR_NVL ELSE NULL END) AS NUMBER)    AS MSR_NVL
                  ,NULL             AS YYYYMM_DDN
             FROM GT_SMCC2_LOSS_RSLT_AK
            WHERE 1=1
              AND MSR_TP_CD IN ('PROD_OP_RT', 'THRY_CAPA_D')
            GROUP BY LN_ALTER_KEY;

            /* ---------------------------------------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' LOSS 라인별 실적(M-1) - 생산 Capa(월) 추가 ');
            /* ----------------------------------------------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SMCC2_LOSS_RSLT_AK ( LN_ALTER_KEY, MSR_GR_CD, MSR_TP_CD, YYYYMM, MSR_NVL, YYYYMM_DDN )
            SELECT LR.LN_ALTER_KEY
                  ,'-'                      AS MSR_GR_CD
                  ,'PROD_CAPA_M'            AS MSR_TP_CD
                  ,LR.YYYYMM                AS YYYYMM
                  ,CAST(MSR_NVL AS NUMBER) * YM.YYYYMM_DDN  AS MSR_NVL
                  ,YM.YYYYMM_DDN
             FROM GT_SMCC2_LOSS_RSLT_AK LR
                 , GT_SMCC2_YYYYMM_DAYS_SOP YM  /* 2024/8/29 SOP 적용 */
            WHERE 1=1
              AND YM.YYYYMM     = LR.YYYYMM
              AND YM.LN_ALTER_KEY= LR.LN_ALTER_KEY
              AND MSR_TP_CD = 'PROD_CAPA_D'
              AND LR.YYYYMM = 'RSLT';

            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' LOSS 라인별 합계 - 실적(M-1) 결과 추가');
            /* ----------------------------------------------------------------------------------------------------------------- */
            /* - 2024.05.17 base포함 당월계획 + result */
            /* ----------------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SMCC2_LOSS_PLAN_LN_TTZM(
                   LN_ALTER_KEY
                  ,MSR_TP_CD
                  ,MSR_GR_CD
                  ,YYYYMM
                  ,MSR_NVL
                  ,ATTRIBUTE10
                )
            SELECT LN_ALTER_KEY
                  ,MSR_TP_CD
                  ,MSR_GR_CD
                  ,YYYYMM
                  ,MSR_NVL
                  ,'[RSLT_LOSS_YM=' || V_LOSS_RSLT_YYYYMM || ']'    AS ATTRIBUTE10
             FROM GT_SMCC2_LOSS_RSLT_AK;

        /* ----------------- END 라인별 합계 실적 */
        /* ----------------- END 라인별 합계 실적 */


        /* ----------------- START 라인별 합계 부가정보 추가  5/21 */
        /* ----------------- START 라인별 합계 부가정보 추가  5/21 */
            /* ---------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 라인별 합계 부가정보 - 조업율/부하율/시간가동률/성능가동률/양품가동률 ');
            /* ---------------------------------------------------------------------------------------------------------------- */
            /* AV_RT    조업율 */
            /* LD_RT    부하율 */
            /* OP_RT    시간가동률 */
            /* PF_RT    성능가동률 */
            /* QL_RT    양품가동률 */
            /* ---------------------------------------------------------------------------------------------------------------- */
            /* 원본 IF OBJECT_ID('TEMPDB..#AV_LD_OP_PF_QL_LN') IS NOT NULL DROP TABLE #AV_LD_OP_PF_QL_LN; -> GTT 초기화 */
            DELETE FROM GT_SMCC2_AV_LD_OP_PF_QL_LN;

            INSERT INTO GT_SMCC2_AV_LD_OP_PF_QL_LN ( LN_ALTER_KEY, MSR_TP_CD, YYYYMM, MSR_GR_CD, MSR_NVL, MSR_SEQ )
            SELECT LN_ALTER_KEY
                  ,MSR_TP_CD
                  ,YYYYMM
                  ,MSR_GR_CD
                  ,CAST(MSR_NVL AS NUMBER)  AS MSR_NVL
                  ,CASE WHEN MSR_TP_CD = 'AV_RT' THEN 1
                        WHEN MSR_TP_CD = 'LD_RT' THEN 2
                        WHEN MSR_TP_CD = 'OP_RT' THEN 3
                        WHEN MSR_TP_CD = 'PF_RT' THEN 4
                        WHEN MSR_TP_CD = 'QL_RT' THEN 5
                    END MSR_SEQ
             FROM GT_SMCC2_LOSS_PLAN_LN_TTZM
            WHERE 1=1
              AND MSR_TP_CD IN ('AV_RT', 'LD_RT', 'OP_RT', 'PF_RT', 'QL_RT');

            /* ---------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 라인별 합계 부가정보 - 조업/부하/시간가동/성능가동/양품가동 일수');
            /* ---------------------------------------------------------------------------------------------------------------- */
            /* 일수정보 : MSR_DDN */
            /* AV_RT    조업율     : 조업일수      = 생산 Capa(월) / 생산 Capa(일) */
            /* LD_RT    부하율     : 부하일수      = 조업일수 * 부하율 */
            /* OP_RT    시간가동률   : 시간가동일수    = 부하일수 * 시간가동률 */
            /* PF_RT    성능가동률   : 성능가동일수    = 시간가동일수 * 성능가동률 */
            /* QL_RT    양품가동률   : 양품가동일수    = 성능가동일수 * 양품가동률 */
            /* ---------------------------------------------------------------------------------------------------------------- */
            /* 원본 IF OBJECT_ID('TEMPDB..#MSR_DDN_LN') IS NOT NULL DROP TABLE #MSR_DDN_LN; -> GTT 초기화 */
            DELETE FROM GT_SMCC2_MSR_DDN_LN;

            INSERT INTO GT_SMCC2_MSR_DDN_LN ( LN_ALTER_KEY, MSR_TP_CD, YYYYMM, MSR_GR_CD, MSR_NVL, P_DDN, C_DDN, MSR_SEQ )
            WITH RECURSIVE_DATA ( LN_ALTER_KEY, MSR_TP_CD, YYYYMM, MSR_GR_CD, MSR_NVL, P_DDN, C_DDN, MSR_SEQ ) AS (
                SELECT R.LN_ALTER_KEY
                      ,R.MSR_TP_CD
                      ,R.YYYYMM
                      ,R.MSR_GR_CD
                      ,CAST(NVL(R.MSR_NVL, 0) AS NUMBER)                                    AS MSR_NVL  /* 조업률 */
                      ,YM.YYYYMM_DDN                                                        AS P_DDN    /* 최대조업일수 */
                      ,CAST(NVL(R.MSR_NVL, 0) * YM.YYYYMM_DDN AS NUMBER)                    AS C_DDN        /* 조업일수 */
                      ,R.MSR_SEQ
                 FROM GT_SMCC2_AV_LD_OP_PF_QL_LN  R
                     , GT_SMCC2_YYYYMM_DAYS_SOP YM  /* 2024/8/29 SOP 적용 */
                WHERE R.MSR_SEQ = 1  /* AV_RT : 조업률/조업일수 */
                  AND YM.YYYYMM     = R.YYYYMM
                  AND YM.LN_ALTER_KEY= R.LN_ALTER_KEY
                UNION ALL
                SELECT C.LN_ALTER_KEY
                      ,C.MSR_TP_CD
                      ,C.YYYYMM
                      ,C.MSR_GR_CD
                      ,C.MSR_NVL
                      ,P.C_DDN                                                              AS P_DDN
                      ,CAST(CAST(C.MSR_NVL * P.C_DDN AS NUMBER(20,10)) AS NUMBER)           AS C_DDN
                      ,C.MSR_SEQ
                 FROM RECURSIVE_DATA P
                    , GT_SMCC2_AV_LD_OP_PF_QL_LN C
                     WHERE 1=1
                       AND C.LN_ALTER_KEY       = P.LN_ALTER_KEY
                       AND C.YYYYMM         = P.YYYYMM
                       AND C.MSR_SEQ        = P.MSR_SEQ + 1
            )
            SELECT C.LN_ALTER_KEY
                  ,C.MSR_TP_CD
                  ,C.YYYYMM
                  ,C.MSR_GR_CD
                  ,CAST(C.MSR_NVL AS NUMBER(20,10)) AS  MSR_NVL
                  ,CAST(C.P_DDN  AS NUMBER(20,10))  AS  P_DDN
                  ,CAST(C.C_DDN  AS NUMBER(20,10))  AS  C_DDN
                  ,MSR_SEQ
             FROM RECURSIVE_DATA C
            WHERE 1=1;

            /* ---------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 라인별 합계 부가정보 - 설비대수/이론Capa/TEEP');
            /* ---------------------------------------------------------------------------------------------------------------- */
            /* 원본 IF OBJECT_ID('TEMPDB..#EQP_NBU_THRY_CAPA_D') IS NOT NULL DROP TABLE #EQP_NBU_THRY_CAPA_D; -> GTT 초기화 */
            DELETE FROM GT_SMCC2_EQP_NBU_THRY_CAPA_D;

            INSERT INTO GT_SMCC2_EQP_NBU_THRY_CAPA_D ( LN_ALTER_KEY, YYYYMM, EQP_NBU, THRY_CAPA_D, TEEP, YYYYMM_DDN )
            SELECT LP.LN_ALTER_KEY
                  ,LP.YYYYMM
                  ,CAST(MAX(CASE WHEN LP.MSR_TP_CD = 'EQP_NBU'      THEN MSR_NVL ELSE NULL END) AS NUMBER(20,10))       AS EQP_NBU
                  ,CAST(MAX(CASE WHEN LP.MSR_TP_CD = 'THRY_CAPA_D'  THEN MSR_NVL ELSE NULL END) AS NUMBER(20,10))       AS THRY_CAPA_D
                  ,CAST(MAX(CASE WHEN LP.MSR_TP_CD = 'TEEP'         THEN MSR_NVL ELSE NULL END) AS NUMBER(20,10))       AS TEEP
                  ,CAST(MAX(YM.YYYYMM_DDN) AS NUMBER(20,10))                                                            AS YYYYMM_DDN
             FROM GT_SMCC2_LOSS_PLAN_LN_TTZM LP
                 , GT_SMCC2_YYYYMM_DAYS_SOP YM  /* 2024/8/29 SOP 적용 */
            WHERE 1=1
              AND YM.YYYYMM     = LP.YYYYMM
              AND YM.LN_ALTER_KEY= LP.LN_ALTER_KEY
              AND LP.MSR_TP_CD IN ('EQP_NBU', 'THRY_CAPA_D', 'TEEP')
            GROUP BY LP.LN_ALTER_KEY
                    ,LP.YYYYMM;

            /* ------------------------------------------------------------------------------------------------------------------------ */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 라인별 합계 부가정보 - 조업/부하/시간가동/성능가동/양품가동 일수/비율');
            /* ------------------------------------------------------------------------------------------------------------------------ */
            /* 원본 IF OBJECT_ID('TEMPDB..#AV_LD_OP_PF_QL_LN_RT_DDN') IS NOT NULL DROP TABLE #AV_LD_OP_PF_QL_LN_RT_DDN; -> GTT 초기화 */
            DELETE FROM GT_SMCC2_AV_LD_OP_PF_QL_RT_DDN;

            INSERT INTO GT_SMCC2_AV_LD_OP_PF_QL_RT_DDN ( LN_ALTER_KEY, YYYYMM, AV_RT, LD_RT, OP_RT, PF_RT, QL_RT
                                                       , YYYYMM_DDN, AV_DDN, LD_DDN, OP_DDN, PF_DDN, QL_DDN )
            SELECT LN_ALTER_KEY
                  ,YYYYMM
                  ,CAST(MAX(CASE WHEN MSR_TP_CD = 'AV_RT' THEN MSR_NVL  ELSE NULL END) AS NUMBER(20,10))    AS AV_RT
                  ,CAST(MAX(CASE WHEN MSR_TP_CD = 'LD_RT' THEN MSR_NVL  ELSE NULL END) AS NUMBER(20,10))    AS LD_RT
                  ,CAST(MAX(CASE WHEN MSR_TP_CD = 'OP_RT' THEN MSR_NVL  ELSE NULL END) AS NUMBER(20,10))    AS OP_RT
                  ,CAST(MAX(CASE WHEN MSR_TP_CD = 'PF_RT' THEN MSR_NVL  ELSE NULL END) AS NUMBER(20,10))    AS PF_RT
                  ,CAST(MAX(CASE WHEN MSR_TP_CD = 'QL_RT' THEN MSR_NVL  ELSE NULL END) AS NUMBER(20,10))    AS QL_RT
                  ,CAST(MAX(CASE WHEN MSR_TP_CD = 'AV_RT' THEN P_DDN        ELSE NULL END) AS NUMBER(20,10))    AS YYYYMM_DDN
                  ,CAST(MAX(CASE WHEN MSR_TP_CD = 'AV_RT' THEN C_DDN        ELSE NULL END) AS NUMBER(20,10))    AS AV_DDN
                  ,CAST(MAX(CASE WHEN MSR_TP_CD = 'LD_RT' THEN C_DDN        ELSE NULL END) AS NUMBER(20,10))    AS LD_DDN
                  ,CAST(MAX(CASE WHEN MSR_TP_CD = 'OP_RT' THEN C_DDN        ELSE NULL END) AS NUMBER(20,10))    AS OP_DDN
                  ,CAST(MAX(CASE WHEN MSR_TP_CD = 'PF_RT' THEN C_DDN        ELSE NULL END) AS NUMBER(20,10))    AS PF_DDN
                  ,CAST(MAX(CASE WHEN MSR_TP_CD = 'QL_RT' THEN C_DDN        ELSE NULL END) AS NUMBER(20,10))    AS QL_DDN
             FROM GT_SMCC2_MSR_DDN_LN
            WHERE 1=1
            GROUP BY LN_ALTER_KEY
                    ,YYYYMM;

        /* ----------------- END 라인별 합계 부가정보 추가    5/21 */
        /* ----------------- END 라인별 합계 부가정보 추가    5/21 */

