/* --------------------- Start 전극 ------------------------------------------------------------------------------------------------------- */

            /* -------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 전극 템프테이블 라인별 LOSS  -  #ELTR_LOSS_PLAN_LN');
            /* -------------------------------------------------------------------------------------------------------------- */
            /* 원본 IF OBJECT_ID('TEMPDB..#ELTR_LOSS_PLAN_LN') ... DROP + SELECT .. INTO .. WHERE 1=2 (빈 골격) -> GTT 초기화 */
            DELETE FROM GT_SMCC2_ELTR_LOSS_PLAN_LN;

            /* ------------------------------------------------------------------------------------------------------------------------------ */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 전극 템프테이블 모델별 LOSS Cutoff 데이터 -  #SCP_MST_CAPA_ELTR_LOSS_PLAN_MDL_CUTF');
            /* ------------------------------------------------------------------------------------------------------------------------------ */
            /* 원본 IF OBJECT_ID('TEMPDB..#SCP_MST_CAPA_ELTR_LOSS_PLAN_MDL_CUTF') ... DROP + SELECT .. INTO .. WHERE 1=2 (빈 골격) -> GTT 초기화 */
            DELETE FROM GT_SMCC2_ELTR_LOSS_PLAN_MDL;

            /* ----------------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 전극 모델별 Loss Plan Cutoff  -  #SCP_MST_CAPA_ELTR_LOSS_PLAN_MDL_CUTF');
            /* ----------------------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SMCC2_ELTR_LOSS_PLAN_MDL ( MDL_ALTER_KEY, LN_ALTER_KEY, DIVISION_ID, MDL_NM, PLANT_ID, LINE_ID, OPERATION_ID, ELTR_LN_TP_CD
                                                    , COMPANY_ID, SITE_ID, FACTORY_ID, MSR_TP_CD, YYYYMM, PFRSLT_NVL, BASE_NVL, MSR_GR_CD, MSR_NVL, MSR_DDN )
            SELECT  DENSE_RANK() OVER (PARTITION BY 'A'
                                          ORDER BY LS.MDL_NM
                                                  ,LS.PLANT_ID
                                                  ,LS.FACTORY_ID
                                                  ,LS.LINE_ID
                                                  ,LS.OPERATION_ID
                                                  ,LS.DIVISION_ID
                                                  ,LS.COMPANY_ID
                                                  ,LS.SITE_ID
                                                ) AS MDL_ALTER_KEY
                    ,DENSE_RANK() OVER (PARTITION BY 'A'
                                          ORDER BY LS.PLANT_ID
                                                  ,LS.FACTORY_ID
                                                  ,LS.LINE_ID
                                                  ,LS.OPERATION_ID
                                                  ,LS.DIVISION_ID
                                                  ,LS.COMPANY_ID
                                                  ,LS.SITE_ID
                                                ) AS LN_ALTER_KEY
                    ,LS.DIVISION_ID
                    ,LS.MDL_NM
                    ,LS.PLANT_ID
                    ,LS.LINE_ID
                    ,LS.OPERATION_ID
                    ,LS.ELTR_LN_TP_CD
                    ,LS.COMPANY_ID
                    ,LS.SITE_ID
                    ,LS.FACTORY_ID
                    ,CASE WHEN LS.MSR_TP_CD = 'AV_RT' AND LS.MDL_NM != '-'   /* 2024.08.29 for 모델별 조업률(일) 재계산 반영 */
                          THEN 'AV_RT_OLD'
                          ELSE LS.MSR_TP_CD
                     END                    AS MSR_TP_CD
                    ,LS.YYYYMM
                    ,LS.PFRSLT_NVL          AS PFRSLT_NVL
                    ,LS.BASE_NVL            AS BASE_NVL
                    /* 2025.02.05 개선/목표일 관리 기능 삭제 ,LS.IPRV_GOL_DIVS_CD */
                    /* 2025.02.05 개선/목표일 관리 기능 삭제 ,LS.IPRV_GOL_RT           AS IPRV_GOL_RT */
                    ,LS.MSR_GR_CD
                    ,LS.MSR_NVL             AS MSR_NVL
                    ,LS.MSR_DDN             AS MSR_DDN
            FROM SCP_MST_CAPA_ELTR_LOSS_PLAN_MDL_CUTF LS
            WHERE 1=1
              AND LS.VER_ID      = V_VER_ID
              AND LS.VER_SEQ     = V_VER_SEQ
              AND LS.DIVISION_ID = V_DIVISION_ID
              AND LS.MSR_TP_CD NOT IN ('PROD_TM');  /* 생산시간 제외 */


            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 전극 라인별 ALTER KEY 정보 - #ELTR_ALTER_KEY_INFO_LN');
            /* ----------------------------------------------------------------------------------------------------------------- */
            /* 원본 IF OBJECT_ID('TEMPDB..#ELTR_ALTER_KEY_INFO_LN') IS NOT NULL DROP TABLE #ELTR_ALTER_KEY_INFO_LN -> GTT 초기화 */
            DELETE FROM GT_SMCC2_ELTR_ALTER_KEY_LN;

            INSERT INTO GT_SMCC2_ELTR_ALTER_KEY_LN ( LN_ALTER_KEY, PLANT_ID, LINE_ID, OPERATION_ID, ELTR_LN_TP_CD, DIVISION_ID, COMPANY_ID, SITE_ID, FACTORY_ID )
            SELECT
                   LS.LN_ALTER_KEY
                  ,LS.PLANT_ID
                  ,LS.LINE_ID
                  ,LS.OPERATION_ID
                  ,MAX(LS.ELTR_LN_TP_CD)    AS ELTR_LN_TP_CD    /* 7/10 PK컬럼에서 제외 */
                  ,LS.DIVISION_ID
                  ,LS.COMPANY_ID
                  ,LS.SITE_ID
                  ,LS.FACTORY_ID
            FROM GT_SMCC2_ELTR_LOSS_PLAN_MDL LS
            GROUP BY
                   LS.LN_ALTER_KEY
                  ,LS.PLANT_ID
                  ,LS.LINE_ID
                  ,LS.OPERATION_ID
                  ,LS.DIVISION_ID
                  ,LS.COMPANY_ID
                  ,LS.SITE_ID
                  ,LS.FACTORY_ID;

            /* ---------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 전극 월별 일수 정보 -  #ELTR_YYYYMM_DAYS_INFO');
            /* ---------------------------------------------------------------------------------------------------------------- */
            /* 원본 IF OBJECT_ID('TEMPDB..#ELTR_YYYYMM_DAYS_INFO') IS NOT NULL DROP TABLE #ELTR_YYYYMM_DAYS_INFO; -> GTT 초기화 */
            DELETE FROM GT_SMCC2_ELTR_YYYYMM_DAYS;

            INSERT INTO GT_SMCC2_ELTR_YYYYMM_DAYS ( YYYYMM, YYYYMM_DDN )
            SELECT DISTINCT YYYYMM
                           ,CAST(
                                CASE WHEN LENGTH(YYYYMM) = 4
                                     THEN ADD_MONTHS(TO_DATE(YYYYMM || '0101', 'YYYYMMDD'), 12) - TO_DATE(YYYYMM || '0101', 'YYYYMMDD') /* 년일수 */
                                     ELSE ADD_MONTHS(TO_DATE(YYYYMM || '01', 'YYYYMMDD'), 1) - TO_DATE(YYYYMM || '01', 'YYYYMMDD')      /* 월일수 */
                                END AS NUMBER)  AS YYYYMM_DDN
             FROM GT_SMCC2_ELTR_LOSS_PLAN_MDL LS
            WHERE 1=1
              AND YYYYMM NOT IN ('BASE', 'RSLT', 'PRVS', 'BIZP')
            UNION ALL
            SELECT 'BASE'
                  ,CAST(ADD_MONTHS(TO_DATE(V_VER_ID || '01', 'YYYYMMDD'), 1) - TO_DATE(V_VER_ID || '01', 'YYYYMMDD') AS NUMBER)          /* 월일수 base (버전 당월) */
              FROM DUAL
            UNION ALL
            SELECT 'RSLT'
                  ,CAST(ADD_MONTHS(TO_DATE(V_LOSS_RSLT_YYYYMM || '01', 'YYYYMMDD'), 1) - TO_DATE(V_LOSS_RSLT_YYYYMM || '01', 'YYYYMMDD') AS NUMBER) /* 실적 월 일수 (M-1월) */
              FROM DUAL;

            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' Capa 재계산 - SOP Master 정보 - #SCP_MST_CAPA_ELTR_LINE_SOP'); /* 2024.08.30 */
            /* ----------------------------------------------------------------------------------------------------------------- */
            /* 원본 IF OBJECT_ID('TEMPDB..#SCP_MST_CAPA_ELTR_LINE_SOP') IS NOT NULL DROP TABLE #SCP_MST_CAPA_ELTR_LINE_SOP -> GTT 초기화 */
            DELETE FROM GT_SMCC2_ELTR_LINE_SOP;

            INSERT INTO GT_SMCC2_ELTR_LINE_SOP ( DIVISION_ID, COMPANY_ID, SITE_ID, PLANT_ID, FACTORY_ID, LINE_ID, OPERATION_ID, ELTR_LN_TP_CD
                                               , VALID_YN, SOP_DT, SOP_YM, CREATION_DATE, CREATED_BY, LAST_UPDATE_DATE, LAST_UPDATED_BY
                                               , SOP_DDN, SOP_YY, SOP_YY_DDN )
            SELECT SP.DIVISION_ID
                  ,SP.COMPANY_ID
                  ,SP.SITE_ID
                  ,SP.PLANT_ID
                  ,SP.FACTORY_ID
                  ,SP.LINE_ID
                  ,SP.OPERATION_ID
                  ,SP.ELTR_LN_TP_CD
                  ,SP.VALID_YN
                  ,SP.SOP_DT
                  ,SP.SOP_YM
                  ,SP.CREATION_DATE
                  ,SP.CREATED_BY
                  ,SP.LAST_UPDATE_DATE
                  ,SP.LAST_UPDATED_BY
                  ,CAST(SP.SOP_DDN AS NUMBER)   AS SOP_DDN
                  ,SUBSTR(SP.SOP_YM, 1, 4)      AS SOP_YY
                  ,CAST( ADD_MONTHS(TO_DATE(SUBSTR(SP.SOP_YM, 1, 4) || '0101', 'YYYYMMDD'), 12)
                       - TO_DATE(SP.SOP_DT, 'YYYYMMDD')
                                            AS NUMBER)  AS SOP_YY_DDN   /* 년일수 */
              FROM SCP_MST_CAPA_ELTR_LINE_SOP SP
             WHERE 1=1
               AND SP.DIVISION_ID   = V_DIVISION_ID
               AND SP.VALID_YN      = 'Y'
               AND SP.SOP_DT IS NOT NULL
               AND SP.SOP_YM IS NOT NULL
               AND SP.SOP_DDN IS NOT NULL
               AND SP.SOP_DDN      != 0;

            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' Capa 재계산 - 전극 라인별/월 일수 정보 WITH SOP - #ELTR_YYYYMM_DAYS_INFO_APPLIED_SOP');
            /* 조립 : DIVISION_ID, COMPANY_ID, SITE_ID, PLANT_ID, FACTORY_ID, LINE_ID, OPERATION_ID, ELTR_LN_TP_CD */
            /* ----------------------------------------------------------------------------------------------------------------- */
            /* 원본 IF OBJECT_ID('TEMPDB..#ELTR_YYYYMM_DAYS_INFO_APPLIED_SOP') IS NOT NULL DROP TABLE #ELTR_YYYYMM_DAYS_INFO_APPLIED_SOP -> GTT 초기화 */
            DELETE FROM GT_SMCC2_ELTR_YYYYMM_DAYS_SOP;

            INSERT INTO GT_SMCC2_ELTR_YYYYMM_DAYS_SOP ( LN_ALTER_KEY, YYYYMM, YYYYMM_DDN )
            WITH CAPA_LINE_SOP AS (
                SELECT SP.DIVISION_ID
                      ,SP.COMPANY_ID
                      ,SP.SITE_ID
                      ,SP.PLANT_ID
                      ,SP.FACTORY_ID
                      ,SP.LINE_ID
                      ,SP.OPERATION_ID
                      ,SP.SOP_DT
                      ,CASE WHEN YM.DV = 'Y'
                            THEN SP.SOP_YY
                            ELSE SP.SOP_YM
                        END AS SOP_YM
                      ,CASE WHEN YM.DV = 'Y'
                            THEN SP.SOP_YY_DDN
                            ELSE SP.SOP_DDN
                        END AS SOP_DDN
                 FROM GT_SMCC2_ELTR_LINE_SOP SP
                    , (SELECT 'Y' AS DV FROM DUAL
                                  UNION ALL
                                  SELECT 'M' AS DV FROM DUAL) YM
                WHERE 1=1
                  AND 1=1
            )
            SELECT AK.LN_ALTER_KEY
                  ,DI.YYYYMM
                  ,CAST(    /* 2024.09.12 */
                   CASE WHEN SO.SOP_YM IS NOT NULL AND DI.YYYYMM != 'BASE' /* 2024.10.16 base sop 적용 안함 */
                        THEN SO.SOP_DDN
                        ELSE DI.YYYYMM_DDN
                    END AS NUMBER)  AS YYYYMM_DDN
             FROM GT_SMCC2_ELTR_ALTER_KEY_LN AK
                 , GT_SMCC2_ELTR_YYYYMM_DAYS DI
                 , CAPA_LINE_SOP SO
             WHERE 1=1
               AND 1=1
               AND SO.DIVISION_ID(+)    = AK.DIVISION_ID
               AND SO.COMPANY_ID(+)     = AK.COMPANY_ID
               AND SO.SITE_ID(+)        = AK.SITE_ID
               AND SO.PLANT_ID(+)       = AK.PLANT_ID
               AND SO.FACTORY_ID(+)     = AK.FACTORY_ID
               AND SO.LINE_ID(+)        = AK.LINE_ID
               AND SO.OPERATION_ID(+)   = AK.OPERATION_ID
               AND SO.SOP_YM(+)         = CASE  WHEN DI.YYYYMM = 'BASE'
                                                        THEN  V_VER_ID
                                                        ELSE DI.YYYYMM
                                                   END;

            /* ---------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' LOSS 모델별 Cutoff 생성 - 조업률(일) 재계산 : AV_RT');  /* 2024.08.29 추가 */
            /* 조업일수 : SCP 생산 계획 / 생산 Capa(일) */
            /* ---------------------------------------------------------------------------------------------------------------- */
            /* GROUP BY 의 CONVERT(FLOAT, YM.YYYYMM_DDN) 은 YYYYMM_DDN 이 이미 FLOAT 이라 MSSQL 이 무효 캐스트로 소거하고
               YM.YYYYMM_DDN 자체를 그룹키로 쓴다(그래서 SELECT 에서 맨 컬럼 참조가 허용된다). Oracle 은 캐스트를 소거하지
               않아 ORA-00979 가 나므로 그룹키를 원래 의미대로 YM.YYYYMM_DDN 으로 적는다(값·그룹집합 동일). */
            INSERT INTO GT_SMCC2_ELTR_LOSS_PLAN_MDL ( MDL_ALTER_KEY, LN_ALTER_KEY, DIVISION_ID, MDL_NM, PLANT_ID, LINE_ID, OPERATION_ID, ELTR_LN_TP_CD
                                                    , COMPANY_ID, SITE_ID, FACTORY_ID, MSR_TP_CD, YYYYMM, PFRSLT_NVL, BASE_NVL, MSR_GR_CD, MSR_NVL, MSR_DDN )
            WITH AV_RT AS (
                SELECT
                       PC.MDL_ALTER_KEY
                      ,PC.LN_ALTER_KEY
                      ,PC.MSR_GR_CD
                      ,'AV_RT'  AS MSR_TP_CD
                      ,PC.YYYYMM
                      /* 조업률 */
                      ,CAST(
                       CASE WHEN MAX(CASE WHEN MSR_TP_CD = 'PROD_CAPA_D' THEN MSR_NVL ELSE NULL END)  = 0
                            THEN 0
                            ELSE   CAST(CAST(
                                      CAST(MAX(CASE WHEN MSR_TP_CD = 'SCP_PROD_PLAN'    THEN MSR_NVL ELSE NULL END) AS NUMBER)
                                    / CAST(MAX(CASE WHEN MSR_TP_CD = 'PROD_CAPA_D'  THEN MSR_NVL ELSE NULL END) AS NUMBER)
                                    AS NUMBER(20,10)) AS NUMBER)
                       END / YM.YYYYMM_DDN
                       AS NUMBER)   AS MSR_NVL
                       /* 조업일수 */
                      ,CAST(
                       CASE WHEN MAX(CASE WHEN MSR_TP_CD = 'PROD_CAPA_D' THEN MSR_NVL ELSE NULL END)  = 0
                            THEN 0
                            ELSE   CAST(
                                      CAST(MAX(CASE WHEN MSR_TP_CD = 'SCP_PROD_PLAN'    THEN MSR_NVL ELSE NULL END) AS NUMBER)
                                    / CAST(MAX(CASE WHEN MSR_TP_CD = 'PROD_CAPA_D'  THEN MSR_NVL ELSE NULL END) AS NUMBER)
                                    AS NUMBER(20, 10))
                       END
                       AS NUMBER)   AS MSR_DDN
                 FROM GT_SMCC2_ELTR_LOSS_PLAN_MDL  PC
                    , GT_SMCC2_ELTR_YYYYMM_DAYS_SOP YM /* 2024.08.29 SOP 적용 */
                WHERE 1=1
                  AND YM.YYYYMM     = PC.YYYYMM
                  AND YM.LN_ALTER_KEY= PC.LN_ALTER_KEY
                  AND PC.MSR_TP_CD IN ('SCP_PROD_PLAN', 'PROD_CAPA_D')
                GROUP BY PC.MDL_ALTER_KEY
                        ,PC.LN_ALTER_KEY
                        ,PC.MSR_GR_CD
                        ,PC.YYYYMM
                        ,YM.YYYYMM_DDN
            )
            SELECT AR.MDL_ALTER_KEY
                  ,AR.LN_ALTER_KEY
                  ,R.DIVISION_ID
                  ,R.MDL_NM
                  ,R.PLANT_ID
                  ,R.LINE_ID
                  ,R.OPERATION_ID
                  ,R.ELTR_LN_TP_CD
                  ,R.COMPANY_ID
                  ,R.SITE_ID
                  ,R.FACTORY_ID
                  ,AR.MSR_TP_CD
                  ,AR.YYYYMM
                  ,NVL(R.PFRSLT_NVL,  0.)               AS PFRSLT_NVL     /* 조업률 실적 */
                  ,1.                                       AS BASE_NVL       /* 모델별 Loss의 조업률은 100?. */
                  /* 2025.02.05 개선/목표일 관리 기능 삭제 ,NULL                                       AS IPRV_GOL_DIVS_CD */
                  /* 2025.02.05 개선/목표일 관리 기능 삭제 ,NULL                                       AS IPRV_GOL_RT */
                  ,AR.MSR_GR_CD
                  ,NVL(AR.MSR_NVL, 0.)                  AS MSR_NVL
                  ,NVL(AR.MSR_DDN, 0.)                  AS MSR_DDN
             FROM AV_RT AR
                , GT_SMCC2_ELTR_LOSS_PLAN_MDL R /* 2024.08.14 수정 */
            WHERE 1=1
              AND R.MDL_ALTER_KEY = AR.MDL_ALTER_KEY
              AND R.LN_ALTER_KEY    = AR.LN_ALTER_KEY
              AND R.YYYYMM      = AR.YYYYMM
              AND R.MSR_TP_CD       = 'AV_RT_OLD';

            /* --------------------------------------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 전극 모델별 Loss Plan 모델별 Cutoff Data -  #SCP_MST_CAPA_ELTR_LOSS_PLAN_MDL_CUTF - Base 추가');
            /* --------------------------------------------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SMCC2_ELTR_LOSS_PLAN_MDL ( MDL_ALTER_KEY, LN_ALTER_KEY, DIVISION_ID, MDL_NM, PLANT_ID, LINE_ID, OPERATION_ID, ELTR_LN_TP_CD
                                                    , COMPANY_ID, SITE_ID, FACTORY_ID, MSR_TP_CD, YYYYMM, PFRSLT_NVL, BASE_NVL, MSR_GR_CD, MSR_NVL, MSR_DDN )
            SELECT   LS.MDL_ALTER_KEY
                    ,LS.LN_ALTER_KEY
                    ,LS.DIVISION_ID
                    ,LS.MDL_NM
                    ,LS.PLANT_ID
                    ,LS.LINE_ID
                    ,LS.OPERATION_ID
                    ,MAX(LS.ELTR_LN_TP_CD)      AS ELTR_LN_TP_CD    /* 7/10 PK컬럼에서 제외 */
                    ,LS.COMPANY_ID
                    ,LS.SITE_ID
                    ,LS.FACTORY_ID
                    ,LS.MSR_TP_CD
                    ,'BASE' AS YYYYMM
                    ,MAX(LS.PFRSLT_NVL)
                    ,MAX(LS.BASE_NVL)
                    /* 2025.02.05 개선/목표일 관리 기능 삭제 ,MAX(LS.IPRV_GOL_DIVS_CD) */
                    /* 2025.02.05 개선/목표일 관리 기능 삭제 ,MAX(LS.IPRV_GOL_RT) */
                    ,MAX(LS.MSR_GR_CD)
                    ,MAX(LS.BASE_NVL)   AS MSR_NVL
                    ,NULL               AS MSR_DDN
             FROM GT_SMCC2_ELTR_LOSS_PLAN_MDL LS
            GROUP BY LS.MDL_ALTER_KEY
                    ,LS.LN_ALTER_KEY
                    ,LS.DIVISION_ID
                    ,LS.MDL_NM
                    ,LS.PLANT_ID
                    ,LS.LINE_ID
                    ,LS.OPERATION_ID
                    ,LS.COMPANY_ID
                    ,LS.SITE_ID
                    ,LS.FACTORY_ID
                    ,LS.MSR_TP_CD;

            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 전극 모델별 Loss - 속도 계산을 위한 SCP생산계획 추가');
            /* SCP_PROD_PLAN_C : speed 계획속도 정보가 없는 경우 0으로 반영 */
            /* ----------------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SMCC2_ELTR_LOSS_PLAN_MDL ( MDL_ALTER_KEY, LN_ALTER_KEY, DIVISION_ID, MDL_NM, PLANT_ID, LINE_ID, OPERATION_ID, ELTR_LN_TP_CD
                                                    , COMPANY_ID, SITE_ID, FACTORY_ID, MSR_TP_CD, YYYYMM, PFRSLT_NVL, BASE_NVL, MSR_GR_CD, MSR_NVL, MSR_DDN )
            SELECT LS.MDL_ALTER_KEY
                  ,LS.LN_ALTER_KEY
                  ,LS.DIVISION_ID
                  ,LS.MDL_NM
                  ,LS.PLANT_ID
                  ,LS.LINE_ID
                  ,LS.OPERATION_ID
                  ,MAX(LS.ELTR_LN_TP_CD)        AS ELTR_LN_TP_CD    /* 7/10 PK컬럼에서 제외 */
                  ,LS.COMPANY_ID
                  ,LS.SITE_ID
                  ,LS.FACTORY_ID
                  ,'SCP_PROD_PLAN_C'    AS MSR_TP_CD
                  ,LS.YYYYMM
                  ,NULL                 AS PFRSLT_NVL
                  ,NULL                 AS BASE_NVL
                  /* 2025.02.05 개선/목표일 관리 기능 삭제 ,NULL                   AS IPRV_GOL_DIVS_CD */
                  /* 2025.02.05 개선/목표일 관리 기능 삭제 ,NULL                   AS IPRV_GOL_RT */
                  ,'-'                  AS MSR_GR_CD
                  ,CASE WHEN NVL(MAX(CASE WHEN MSR_TP_CD = 'EQP_SPED'      THEN MSR_NVL ELSE NULL END), 0) = 0
                        THEN 0.
                        ELSE  CAST(MAX(CASE WHEN MSR_TP_CD = 'SCP_PROD_PLAN' THEN MSR_NVL ELSE NULL END) AS NUMBER)
                    END         AS MSR_NVL
                  ,NULL         AS MSR_DDN
             FROM GT_SMCC2_ELTR_LOSS_PLAN_MDL LS
            WHERE 1=1
              AND LS.MSR_TP_CD IN ('SCP_PROD_PLAN', 'EQP_SPED')
            GROUP BY
                   LS.MDL_ALTER_KEY
                  ,LS.LN_ALTER_KEY
                  ,LS.DIVISION_ID
                  ,LS.MDL_NM
                  ,LS.PLANT_ID
                  ,LS.LINE_ID
                  ,LS.OPERATION_ID
                  ,LS.COMPANY_ID
                  ,LS.SITE_ID
                  ,LS.FACTORY_ID
                  ,LS.YYYYMM;

            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 전극 모델별 Loss - 생산시간 추가');
            /* 생산시간(PROD_TM) : SCP생산계획 C / speed 계획 속도 */
            /* ----------------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SMCC2_ELTR_LOSS_PLAN_MDL ( MDL_ALTER_KEY, LN_ALTER_KEY, DIVISION_ID, MDL_NM, PLANT_ID, LINE_ID, OPERATION_ID, ELTR_LN_TP_CD
                                                    , COMPANY_ID, SITE_ID, FACTORY_ID, MSR_TP_CD, YYYYMM, PFRSLT_NVL, BASE_NVL, MSR_GR_CD, MSR_NVL, MSR_DDN )
            SELECT LS.MDL_ALTER_KEY
                  ,LS.LN_ALTER_KEY
                  ,LS.DIVISION_ID
                  ,LS.MDL_NM
                  ,LS.PLANT_ID
                  ,LS.LINE_ID
                  ,LS.OPERATION_ID
                  ,MAX(LS.ELTR_LN_TP_CD)    AS ELTR_LN_TP_CD    /* 7/10 PK컬럼에서 제외 */
                  ,LS.COMPANY_ID
                  ,LS.SITE_ID
                  ,LS.FACTORY_ID
                  ,'PROD_TM'    AS MSR_TP_CD
                  ,LS.YYYYMM
                  ,NULL         AS PFRSLT_NVL
                  ,NULL         AS BASE_NVL
                  /* 2025.02.05 개선/목표일 관리 기능 삭제 ,NULL           AS IPRV_GOL_DIVS_CD */
                  /* 2025.02.05 개선/목표일 관리 기능 삭제 ,NULL           AS IPRV_GOL_RT */
                  ,'-'          AS MSR_GR_CD
                  ,CASE WHEN NVL(MAX(CASE WHEN MSR_TP_CD = 'EQP_SPED'      THEN MSR_NVL ELSE NULL END), 0) = 0
                        THEN 0.
                        ELSE   CAST(MAX(CASE WHEN MSR_TP_CD = 'SCP_PROD_PLAN_C' THEN MSR_NVL ELSE NULL END) AS NUMBER)
                             / CAST(MAX(CASE WHEN MSR_TP_CD = 'EQP_SPED'        THEN MSR_NVL ELSE NULL END) AS NUMBER)
                    END         AS MSR_NVL
                  ,NULL         AS MSR_DDN
             FROM GT_SMCC2_ELTR_LOSS_PLAN_MDL LS
            WHERE 1=1
              AND LS.MSR_TP_CD IN ('SCP_PROD_PLAN_C', 'EQP_SPED')  /* EQP_SPED 정보가 없는 경우 SCP 생산계획 0으로 반영 */
            GROUP BY
                   LS.MDL_ALTER_KEY
                  ,LS.LN_ALTER_KEY
                  ,LS.DIVISION_ID
                  ,LS.MDL_NM
                  ,LS.PLANT_ID
                  ,LS.LINE_ID
                  ,LS.OPERATION_ID
                  ,LS.COMPANY_ID
                  ,LS.SITE_ID
                  ,LS.FACTORY_ID
                  ,LS.YYYYMM;

            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 전극 라인별 Loss - 비조업');
            /* ----------------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SMCC2_ELTR_LOSS_PLAN_LN ( LN_ALTER_KEY, MSR_GR_CD, MSR_TP_CD, YYYYMM, MSR_NVL, MSR_DDN, ATTRIBUTE1, ATTRIBUTE10 )
            SELECT AK.LN_ALTER_KEY
                  ,LS.MSR_GR_CD
                  ,LS.MSR_TP_CD
                  ,LS.YYYYMM
                  ,NVL(LS.MSR_NVL,0)    AS MSR_NVL
                  ,NVL(LS.MSR_NVL,0)    AS MSR_DDN          /* 2024.10.23 UI에서 입력된 MSR_NVL 값으로 MSR_DDN값 일치시킴 */
                  ,YM.YYYYMM_DDN        AS ATTRIBUTE1       /* 최대조업일수 */
                  ,NULL                 AS ATTRIBUTE10
             FROM SCP_MST_CAPA_ELTR_LOSS_PLAN_LN LS /* 라인별 Loss Current */
                , GT_SMCC2_ELTR_ALTER_KEY_LN AK
                , GT_SMCC2_ELTR_YYYYMM_DAYS_SOP YM  /* 2024/8/29 SOP적용 */
            WHERE 1=1
              AND 1=1
              AND AK.PLANT_ID       = LS.PLANT_ID
              AND AK.LINE_ID        = LS.LINE_ID
              AND AK.OPERATION_ID   = LS.OPERATION_ID
              AND AK.DIVISION_ID    = LS.DIVISION_ID
              AND AK.COMPANY_ID     = LS.COMPANY_ID
              AND AK.SITE_ID        = LS.SITE_ID
              AND AK.FACTORY_ID     = LS.FACTORY_ID
              AND YM.YYYYMM         = LS.YYYYMM
              AND YM.LN_ALTER_KEY   = AK.LN_ALTER_KEY
              AND LS.MSR_GR_CD = 'NAV'      /* 비조업 */
              AND LS.MSR_TP_CD != 'WT_RT';  /* 2024.08.29 물동없음 제외 (재계산 반영) */


            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 전극 라인별 Loss - 비조업 - WT_RT 물동없음 추가'); /* 2024.08.29 */
            /* ----------------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SMCC2_ELTR_LOSS_PLAN_LN ( LN_ALTER_KEY, MSR_GR_CD, MSR_TP_CD, YYYYMM, MSR_NVL, MSR_DDN, ATTRIBUTE1, ATTRIBUTE10 )
            WITH AV_DDN AS (
                /* non base */
                SELECT LS.LN_ALTER_KEY
                      ,LS.YYYYMM
                      ,SUM(MSR_DDN) AS AV_DDN /* 조업일수 */
                 FROM GT_SMCC2_ELTR_LOSS_PLAN_MDL LS
                WHERE 1=1
                  AND MSR_TP_CD = 'AV_RT'
                  AND MDL_NM    != '-'
                  AND YYYYMM    != 'BASE' /* 2024.09.27 */
                GROUP BY LS.LN_ALTER_KEY
                        ,LS.YYYYMM
                /* 2024.09.27 base  추가 */
                UNION ALL
                SELECT LN_ALTER_KEY
                      ,YYYYMM
                      ,YYYYMM_DDN AS AV_DDN
                  FROM GT_SMCC2_ELTR_YYYYMM_DAYS_SOP
                WHERE 1=1
                  AND YYYYMM = 'BASE'
            ), NAV_SUM AS (
                SELECT LS.LN_ALTER_KEY
                      ,LS.YYYYMM
                      ,SUM(MSR_NVL) AS NAV_DDN
                 FROM GT_SMCC2_ELTR_LOSS_PLAN_LN LS
                WHERE 1=1
                  AND LS.MSR_GR_CD = 'NAV' /* 비조업 */
                GROUP BY LS.LN_ALTER_KEY
                        ,LS.YYYYMM
            )
            SELECT NA.LN_ALTER_KEY
                  ,'NAV'                                                        AS MSR_GR_CD
                  ,'WT_RT'                                                      AS MSR_TP_CD
                  ,NA.YYYYMM
                  ,YM.YYYYMM_DDN - NVL(NA.NAV_DDN,0.) - NVL(AV.AV_DDN,0.)   AS MSR_NVL
                  ,YM.YYYYMM_DDN - NVL(NA.NAV_DDN,0.) - NVL(AV.AV_DDN,0.)   AS MSR_DDN
                  ,YM.YYYYMM_DDN                                                AS ATTRIBUTE1       /* 최대조업일수 */
                  ,NULL                                                         AS ATTRIBUTE10
              FROM NAV_SUM NA
                 , GT_SMCC2_ELTR_YYYYMM_DAYS_SOP YM /* 2024/8/29 SOP적용 */
                 , AV_DDN AV
            WHERE 1=1
              AND YM.YYYYMM         = NA.YYYYMM
              AND YM.LN_ALTER_KEY   = NA.LN_ALTER_KEY
              AND AV.LN_ALTER_KEY(+) = NA.LN_ALTER_KEY
              AND AV.YYYYMM(+)        = NA.YYYYMM;


            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 전극 라인별 Loss - 조업률 추가');
            /* 조업률 = 1 - (비조업일 / 최대조업일) */
            /* 2024.08.09 전극 조업일 계산 로직 수정 */
            /* 2024.08.09 변경전 조업일수 = 최대조업일 * 조업률 */
            /* 2024.08.09 변경후 조업일수 = 최대조업일 - SUM(비조업일) */
            /* ----------------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SMCC2_ELTR_LOSS_PLAN_LN ( LN_ALTER_KEY, MSR_GR_CD, MSR_TP_CD, YYYYMM, MSR_NVL, MSR_DDN, ATTRIBUTE1, ATTRIBUTE10 )
            SELECT LS.LN_ALTER_KEY
                  ,'-'              AS MSR_GR_CD
                  ,'AV_RT'          AS MSR_TP_CD
                  ,LS.YYYYMM
                  ,CAST(1 AS NUMBER) - CAST(SUM(MSR_NVL) AS NUMBER) / YM.YYYYMM_DDN AS MSR_NVL  /* 조업률 */
                  ,YM.YYYYMM_DDN - CAST(SUM(MSR_NVL) AS NUMBER)                     AS MSR_DDN  /* 조업일수 = 최대조업일수 - 비조업일합계 */
                  ,YM.YYYYMM_DDN    AS ATTRIBUTE1       /* 최대조업일수 */
                  ,NULL             AS ATTRIBUTE10
             FROM GT_SMCC2_ELTR_LOSS_PLAN_LN LS
                , GT_SMCC2_ELTR_YYYYMM_DAYS_SOP YM  /* 2024/8/29 SOP적용 */
            WHERE 1=1
              AND YM.YYYYMM         = LS.YYYYMM
              AND YM.LN_ALTER_KEY   = LS.LN_ALTER_KEY
              AND LS.MSR_GR_CD = 'NAV'
            GROUP BY LS.LN_ALTER_KEY
                    ,LS.YYYYMM
                    ,YM.YYYYMM_DDN;

            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 전극 라인별 Loss - 비부하 추가');
            /* ----------------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SMCC2_ELTR_LOSS_PLAN_LN ( LN_ALTER_KEY, MSR_GR_CD, MSR_TP_CD, YYYYMM, MSR_NVL, MSR_DDN, ATTRIBUTE1, ATTRIBUTE10 )
            SELECT LS.LN_ALTER_KEY
                  ,LS.MSR_GR_CD
                  ,LS.MSR_TP_CD
                  ,LS.YYYYMM
                  ,NVL(LS.MSR_NVL, 0)                                                   AS MSR_NVL      /* 비부하율 */
                  ,CAST(NVL(LS.MSR_NVL, 0) AS NUMBER) * CAST(AV.MSR_DDN AS NUMBER)      AS MSR_DDN      /* 비부하일수 = 비부하율 * 조업일수 */
                  ,AV.MSR_DDN                                                           AS ATTRIBUTE1   /* 조업일수 */
                  ,NULL                                                                 AS ATTRIBUTE10
             FROM GT_SMCC2_ELTR_LOSS_PLAN_MDL LS
                , GT_SMCC2_ELTR_LOSS_PLAN_LN AV
            WHERE 1=1
              AND AV.LN_ALTER_KEY = LS.LN_ALTER_KEY
              AND AV.MSR_TP_CD   = 'AV_RT' /* 조업률/조업일수 */
              AND AV.YYYYMM      = LS.YYYYMM
              AND LS.MSR_GR_CD  = 'NLD' /* 비부하 */
              AND LS.MDL_NM     = '-';

            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 전극 라인별 Loss - 부하율 추가');
            /* ----------------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SMCC2_ELTR_LOSS_PLAN_LN ( LN_ALTER_KEY, MSR_GR_CD, MSR_TP_CD, YYYYMM, MSR_NVL, MSR_DDN, ATTRIBUTE1, ATTRIBUTE10 )
            SELECT LS.LN_ALTER_KEY
                  ,'-'      AS MSR_GR_CD
                  ,'LD_RT'  AS MSR_TP_CD
                  ,LS.YYYYMM
                  ,CAST(1 AS NUMBER) - CAST(SUM(LS.MSR_NVL) AS NUMBER)  AS MSR_NVL      /* 부하율 */
                  ,CAST(CAST(
                   CAST(1 AS NUMBER) - CAST(SUM(LS.MSR_NVL) AS NUMBER) AS NUMBER(20,10)) AS NUMBER)
                   * AV.MSR_DDN                                         AS MSR_DDN      /* 부하일수 = 부하율 * 조업일수 */
                  ,AV.MSR_DDN                                           AS ATTRIBUTE1   /* 조업일수 */
                  ,NULL                                                 AS ATTRIBUTE10
             FROM GT_SMCC2_ELTR_LOSS_PLAN_LN LS
                , GT_SMCC2_ELTR_LOSS_PLAN_LN AV
            WHERE 1=1
              AND AV.LN_ALTER_KEY = LS.LN_ALTER_KEY
              AND AV.MSR_TP_CD   = 'AV_RT' /* 조업률/조업일수 */
              AND AV.YYYYMM      = LS.YYYYMM
              AND LS.MSR_GR_CD = 'NLD'  /* 비부하 */
            GROUP BY LS.LN_ALTER_KEY
                    ,LS.YYYYMM
                    ,AV.MSR_DDN;

            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 전극 라인별 Loss - 비가동 추가');
            /* ----------------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SMCC2_ELTR_LOSS_PLAN_LN ( LN_ALTER_KEY, MSR_GR_CD, MSR_TP_CD, YYYYMM, MSR_NVL, MSR_DDN, ATTRIBUTE1, ATTRIBUTE10 )
            SELECT LS.LN_ALTER_KEY
                  ,LS.MSR_GR_CD
                  ,LS.MSR_TP_CD
                  ,LS.YYYYMM
                  ,NVL(LS.MSR_NVL, 0)                                                   AS MSR_NVL      /* 비가동률 */
                  ,CAST(NVL(LS.MSR_NVL, 0) AS NUMBER) * CAST(LD.MSR_DDN AS NUMBER)      AS MSR_DDN      /* 비가동일수 = 비가동률 * 부하일수 */
                  ,LD.MSR_DDN                                                           AS ATTRIBUTE1   /* 부하일수 */
                  ,NULL                                                                 AS ATTRIBUTE10
             FROM GT_SMCC2_ELTR_LOSS_PLAN_MDL LS
                , GT_SMCC2_ELTR_LOSS_PLAN_LN LD
            WHERE 1=1
              AND LD.LN_ALTER_KEY = LS.LN_ALTER_KEY
              AND LD.MSR_TP_CD   = 'LD_RT' /* 부하률/부하일수 */
              AND LD.YYYYMM      = LS.YYYYMM
              AND LS.MSR_GR_CD  = 'NOP' /* 비가동 */
              AND LS.MDL_NM     = '-';

            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 전극 라인별 Loss - 시간가동률 추가');
            /* ----------------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SMCC2_ELTR_LOSS_PLAN_LN ( LN_ALTER_KEY, MSR_GR_CD, MSR_TP_CD, YYYYMM, MSR_NVL, MSR_DDN, ATTRIBUTE1, ATTRIBUTE10 )
            SELECT LS.LN_ALTER_KEY
                  ,'-'      AS MSR_GR_CD
                  ,'OP_RT'  AS MSR_TP_CD
                  ,LS.YYYYMM
                  ,CAST(1 AS NUMBER) - CAST(SUM(LS.MSR_NVL) AS NUMBER)  AS MSR_NVL          /* 시간가동률 */
                  ,CAST(CAST(
                   CAST(1 AS NUMBER) - CAST(SUM(LS.MSR_NVL) AS NUMBER) AS NUMBER(20,10)) AS NUMBER)
                   * LD.MSR_DDN                                         AS MSR_DDN      /* 시간가동일수 = 시간가동률 * 부하일수 */
                  ,LD.MSR_DDN                                           AS ATTRIBUTE1   /* 부하일수 */
                  ,NULL                                                 AS ATTRIBUTE10
             FROM GT_SMCC2_ELTR_LOSS_PLAN_LN LS
                , GT_SMCC2_ELTR_LOSS_PLAN_LN LD
            WHERE 1=1
              AND LD.LN_ALTER_KEY = LS.LN_ALTER_KEY
              AND LD.MSR_TP_CD   = 'LD_RT' /* 부하률/부하일수 */
              AND LD.YYYYMM      = LS.YYYYMM
              AND LS.MSR_GR_CD  = 'NOP' /* 비가동 */
            GROUP BY LS.LN_ALTER_KEY
                    ,LS.YYYYMM
                    ,LD.MSR_DDN;

            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 전극 라인별 Loss - 성능가동률 추가');
            /* ----------------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SMCC2_ELTR_LOSS_PLAN_LN ( LN_ALTER_KEY, MSR_GR_CD, MSR_TP_CD, YYYYMM, MSR_NVL, MSR_DDN, ATTRIBUTE1, ATTRIBUTE10 )
            SELECT LS.LN_ALTER_KEY
                  ,LS.MSR_GR_CD
                  ,LS.MSR_TP_CD
                  ,LS.YYYYMM
                  ,LS.MSR_NVL                                               AS MSR_NVL      /* 성능가동률 */
                  ,CAST(LS.MSR_NVL AS NUMBER) * CAST(OP.MSR_DDN AS NUMBER)  AS MSR_DDN      /* 성능가동일수 = 성능가동률 * 시간가동일수 */
                  ,OP.MSR_DDN                                               AS ATTRIBUTE1   /* 시간가동일수 */
                  ,NULL                                                     AS ATTRIBUTE10
                  /* - select * */
             FROM GT_SMCC2_ELTR_LOSS_PLAN_MDL LS
                , GT_SMCC2_ELTR_LOSS_PLAN_LN OP
            WHERE 1=1
              AND OP.LN_ALTER_KEY = LS.LN_ALTER_KEY
              AND OP.MSR_TP_CD   = 'OP_RT' /* 시간가동률/시간가동일수 */
              AND OP.YYYYMM      = LS.YYYYMM
              AND LS.MSR_TP_CD  = 'PF_RT'   /* 성능가동률 */
              AND LS.MDL_NM     = '-';

            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 전극 라인별 Loss - 양품가동률 추가');
            /* ----------------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SMCC2_ELTR_LOSS_PLAN_LN ( LN_ALTER_KEY, MSR_GR_CD, MSR_TP_CD, YYYYMM, MSR_NVL, MSR_DDN, ATTRIBUTE1, ATTRIBUTE10 )
            SELECT LS.LN_ALTER_KEY
                  ,LS.MSR_GR_CD
                  ,LS.MSR_TP_CD
                  ,LS.YYYYMM
                  ,LS.MSR_NVL                                               AS MSR_NVL      /* 양품가동률 */
                  ,CAST(LS.MSR_NVL AS NUMBER) * CAST(PF.MSR_DDN AS NUMBER)  AS MSR_DDN      /* 양품가동일수 = 양품가동률 * 성능가동일수 */
                  ,PF.MSR_DDN                                               AS ATTRIBUTE1   /* 성능가동일수 */
                  ,NULL                                                     AS ATTRIBUTE10
             FROM GT_SMCC2_ELTR_LOSS_PLAN_MDL LS
                , GT_SMCC2_ELTR_LOSS_PLAN_LN PF
            WHERE 1=1
              AND PF.LN_ALTER_KEY = LS.LN_ALTER_KEY
              AND PF.MSR_TP_CD   = 'PF_RT' /* 성능가동률/성능가동일수 */
              AND PF.YYYYMM      = LS.YYYYMM
              AND LS.MSR_TP_CD  = 'QL_RT'   /* 양품가동률 */
              AND LS.MDL_NM     = '-';

            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 전극 라인별 Loss - 생산가동률 추가');
            /* 생산가동률 = 부하율 * 시간가동률 * 성능가동률 * 양품가동률 */
            /* ----------------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SMCC2_ELTR_LOSS_PLAN_LN ( LN_ALTER_KEY, MSR_GR_CD, MSR_TP_CD, YYYYMM, MSR_NVL, MSR_DDN, ATTRIBUTE1, ATTRIBUTE10 )
            SELECT LS.LN_ALTER_KEY
                  ,'-'              AS MSR_GR_CD
                  ,'PROD_OP_RT'     AS MSR_TP_CD
                  ,LS.YYYYMM
                  ,  CAST(MAX(CASE WHEN LS.MSR_TP_CD = 'LD_RT' THEN MSR_NVL ELSE NULL END) AS NUMBER)
                   * CAST(MAX(CASE WHEN LS.MSR_TP_CD = 'OP_RT' THEN MSR_NVL ELSE NULL END) AS NUMBER)
                   * CAST(MAX(CASE WHEN LS.MSR_TP_CD = 'PF_RT' THEN MSR_NVL ELSE NULL END) AS NUMBER)
                   * CAST(MAX(CASE WHEN LS.MSR_TP_CD = 'QL_RT' THEN MSR_NVL ELSE NULL END) AS NUMBER)   AS MSR_NVL
                  ,NULL                                                                                 AS MSR_DDN
                  ,NULL                                                                                 AS ATTRIBUTE1
                  ,NULL                                                                                 AS ATTRIBUTE10
             FROM GT_SMCC2_ELTR_LOSS_PLAN_LN LS
            WHERE 1=1
              AND LS.MSR_TP_CD IN ('LD_RT', 'OP_RT', 'PF_RT', 'QL_RT')
            GROUP BY LS.LN_ALTER_KEY
                    ,LS.YYYYMM;

            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 전극 라인별 Loss - TEEP 추가');
            /* TEEP = 조업률 * 부하율 * 시간가동률 * 성능가동률 * 양품가동률 */
            /* ----------------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SMCC2_ELTR_LOSS_PLAN_LN ( LN_ALTER_KEY, MSR_GR_CD, MSR_TP_CD, YYYYMM, MSR_NVL, MSR_DDN, ATTRIBUTE1, ATTRIBUTE10 )
            SELECT LS.LN_ALTER_KEY
                  ,'-'              AS MSR_GR_CD
                  ,'TEEP'           AS MSR_TP_CD
                  ,LS.YYYYMM
                  ,  CAST(MAX(CASE WHEN LS.MSR_TP_CD = 'AV_RT' THEN MSR_NVL ELSE NULL END) AS NUMBER)
                   * CAST(MAX(CASE WHEN LS.MSR_TP_CD = 'LD_RT' THEN MSR_NVL ELSE NULL END) AS NUMBER)
                   * CAST(MAX(CASE WHEN LS.MSR_TP_CD = 'OP_RT' THEN MSR_NVL ELSE NULL END) AS NUMBER)
                   * CAST(MAX(CASE WHEN LS.MSR_TP_CD = 'PF_RT' THEN MSR_NVL ELSE NULL END) AS NUMBER)
                   * CAST(MAX(CASE WHEN LS.MSR_TP_CD = 'QL_RT' THEN MSR_NVL ELSE NULL END) AS NUMBER)   AS MSR_NVL
                  ,NULL                                                                                 AS MSR_DDN
                  ,NULL                                                                                 AS ATTRIBUTE1
                  ,NULL                                                                                 AS ATTRIBUTE10
             FROM GT_SMCC2_ELTR_LOSS_PLAN_LN LS
            WHERE 1=1
              AND MSR_TP_CD IN ('AV_RT', 'LD_RT', 'OP_RT', 'PF_RT', 'QL_RT')
            GROUP BY LS.LN_ALTER_KEY
                    ,LS.YYYYMM;

            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 전극 라인별 Loss - 생산계획 및 생산시간 추가');
            /* ----------------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SMCC2_ELTR_LOSS_PLAN_LN ( LN_ALTER_KEY, MSR_GR_CD, MSR_TP_CD, YYYYMM, MSR_NVL, MSR_DDN, ATTRIBUTE1, ATTRIBUTE10 )
            SELECT LS.LN_ALTER_KEY
                  ,LS.MSR_GR_CD
                  ,LS.MSR_TP_CD
                  ,LS.YYYYMM
                  ,SUM(LS.MSR_NVL)  AS MSR_NVL
                  ,NULL             AS MSR_DDN
                  ,NULL             AS ATTRIBUTE1
                  ,NULL             AS ATTRIBUTE10
             FROM GT_SMCC2_ELTR_LOSS_PLAN_MDL LS
            WHERE 1=1
              AND LS.MSR_TP_CD  IN ('SCP_PROD_PLAN', 'SCP_PROD_PLAN_C', 'PROD_TM')  /* SCP생산계획/생산시간 */
            GROUP BY LS.LN_ALTER_KEY
                    ,LS.MSR_GR_CD
                    ,LS.MSR_TP_CD
                    ,LS.YYYYMM;

            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 전극 라인별 Loss - 속도 추가');
            /* 속도 (EQP_SPED) : 생산계획 / 생산시간 */
            /* 생산계획 : 모델별 Speed 속도가 없는 경우 0으로 반영된 생산계획 */
            /* ----------------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SMCC2_ELTR_LOSS_PLAN_LN ( LN_ALTER_KEY, MSR_GR_CD, MSR_TP_CD, YYYYMM, MSR_NVL, MSR_DDN, ATTRIBUTE1, ATTRIBUTE10 )
            SELECT LS.LN_ALTER_KEY
                  ,'-'              AS MSR_GR_CD
                  ,'PPM'            AS MSR_TP_CD
                  ,LS.YYYYMM
                  ,CASE WHEN MAX(CASE WHEN LS.MSR_TP_CD = 'PROD_TM' THEN LS.MSR_NVL ELSE NULL END) = 0
                        THEN 0
                        ELSE CAST(MAX(CASE WHEN LS.MSR_TP_CD = 'SCP_PROD_PLAN_C'    THEN LS.MSR_NVL ELSE NULL END) AS NUMBER)
                           / CAST(MAX(CASE WHEN LS.MSR_TP_CD = 'PROD_TM'            THEN LS.MSR_NVL ELSE NULL END) AS NUMBER)
                    END             AS MSR_NVL
                  ,MAX(CASE WHEN LS.MSR_TP_CD = 'SCP_PROD_PLAN_C'   THEN LS.MSR_NVL ELSE NULL END)              AS MSR_DDN      /* SCP 생산계획 */
                  ,MAX(CASE WHEN LS.MSR_TP_CD = 'PROD_TM'           THEN LS.MSR_NVL ELSE NULL END)              AS ATTRIBUTE1   /* 시간 (SCP생산계획 / speed계획 속도) */
                  ,NULL                                                                                         AS ATTRIBUTE10
             FROM GT_SMCC2_ELTR_LOSS_PLAN_LN LS
            WHERE 1=1
              AND LS.MSR_TP_CD  IN ('SCP_PROD_PLAN_C', 'PROD_TM')   /* SCP생산계획 C /생산시간   -- EQP_SPED 정보가 없는 경우 SCP 생산계획 0으로 반영된 생산계획 */
            GROUP BY LS.LN_ALTER_KEY
                    ,LS.YYYYMM;

            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 전극 라인별 Loss - 설비대수 추가');
            /* ----------------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SMCC2_ELTR_LOSS_PLAN_LN ( LN_ALTER_KEY, MSR_GR_CD, MSR_TP_CD, YYYYMM, MSR_NVL, MSR_DDN, ATTRIBUTE1, ATTRIBUTE10 )
            SELECT LS.LN_ALTER_KEY
                  ,'-'              AS MSR_GR_CD
                  ,'EQP_NBU'        AS MSR_TP_CD
                  ,LS.YYYYMM
                  ,1.0              AS MSR_NVL
                  ,NULL             AS MSR_DDN
                  ,NULL             AS ATTRIBUTE1
                  ,NULL             AS ATTRIBUTE10
             FROM GT_SMCC2_ELTR_LOSS_PLAN_LN LS
            WHERE 1=1
              AND LS.MSR_TP_CD  = 'PPM';

            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 전극 라인별 Loss - 표준폭환산자 추가');
            /* ----------------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SMCC2_ELTR_LOSS_PLAN_LN ( LN_ALTER_KEY, MSR_GR_CD, MSR_TP_CD, YYYYMM, MSR_NVL, MSR_DDN, ATTRIBUTE1, ATTRIBUTE10 )
            SELECT LS.LN_ALTER_KEY
                  ,'-'              AS MSR_GR_CD
                  ,'SW_CNV_RT'      AS MSR_TP_CD
                  ,LS.YYYYMM
                  ,CASE WHEN AK.ELTR_LN_TP_CD = 'W'
                        THEN 2.0
                        ELSE 1.0
                    END             AS MSR_NVL          /* 표준폭환산자 (S:1, W:2) */
                  ,CASE WHEN AK.ELTR_LN_TP_CD = 'W'
                        THEN 1.0
                        ELSE 2.0
                    END             AS MSR_DDN          /* 배수(S:2, W:1) */
                  ,LS.MSR_NVL       AS ATTRIBUTE1       /* 시간(PROD_TM = 생산계획C / speed계획 속도) */
                  ,NULL             AS ATTRIBUTE10
             FROM GT_SMCC2_ELTR_LOSS_PLAN_LN LS
                , GT_SMCC2_ELTR_ALTER_KEY_LN AK
            WHERE 1=1
              AND AK.LN_ALTER_KEY = LS.LN_ALTER_KEY
              AND LS.MSR_TP_CD  = 'PROD_TM';        /* 시간 (SCP생산계획C / speed계획 속도) */

            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 전극 라인별 Loss - 이론 Capa (일) 추가');
            /* 이론 Capa (일) : 설비대수 * 속도 * 표준폭환산자 * 1440 */
            /* ----------------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SMCC2_ELTR_LOSS_PLAN_LN ( LN_ALTER_KEY, MSR_GR_CD, MSR_TP_CD, YYYYMM, MSR_NVL, MSR_DDN, ATTRIBUTE1, ATTRIBUTE10 )
            SELECT LS.LN_ALTER_KEY
                  ,'-'              AS MSR_GR_CD
                  ,'THRY_CAPA_D'    AS MSR_TP_CD
                  ,LS.YYYYMM
                  ,CAST(MAX(CASE WHEN LS.MSR_TP_CD = 'EQP_NBU'  THEN LS.MSR_NVL ELSE NULL END) AS NUMBER)    /* 설비대수 */
                  *CAST(MAX(CASE WHEN LS.MSR_TP_CD = 'PPM'      THEN LS.MSR_NVL ELSE NULL END) AS NUMBER)    /* 속도 */
                  *CAST(MAX(CASE WHEN LS.MSR_TP_CD = 'SW_CNV_RT'    THEN LS.MSR_NVL ELSE NULL END) AS NUMBER)    /* 표준폭환산자 */
                  *CAST(1440 AS NUMBER)     AS MSR_NVL
                  ,NULL             AS MSR_DDN
                  ,NULL             AS ATTRIBUTE1
                  ,NULL             AS ATTRIBUTE10
             FROM GT_SMCC2_ELTR_LOSS_PLAN_LN LS
            WHERE 1=1
              AND LS.MSR_TP_CD  IN ('EQP_NBU', 'PPM', 'SW_CNV_RT')
            GROUP BY LS.LN_ALTER_KEY
                    ,LS.YYYYMM;

            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 전극 라인별 Loss - 생산 Capa (일) 추가');
            /* 생산 Capa (일) : 이론 Capa (일) * 생산가동률 */
            /* ----------------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SMCC2_ELTR_LOSS_PLAN_LN ( LN_ALTER_KEY, MSR_GR_CD, MSR_TP_CD, YYYYMM, MSR_NVL, MSR_DDN, ATTRIBUTE1, ATTRIBUTE10 )
            SELECT LS.LN_ALTER_KEY
                  ,'-'              AS MSR_GR_CD
                  ,'PROD_CAPA_D'    AS MSR_TP_CD
                  ,LS.YYYYMM
                  ,CAST(MAX(CASE WHEN LS.MSR_TP_CD = 'THRY_CAPA_D'  THEN LS.MSR_NVL ELSE NULL END) AS NUMBER)    /* 이론 Capa (일) */
                  *CAST(MAX(CASE WHEN LS.MSR_TP_CD = 'PROD_OP_RT'       THEN LS.MSR_NVL ELSE NULL END) AS NUMBER)    /* 생산가동률 */
                                    AS MSR_NVL
                  ,NULL             AS MSR_DDN
                  ,NULL             AS ATTRIBUTE1
                  ,NULL             AS ATTRIBUTE10
             FROM GT_SMCC2_ELTR_LOSS_PLAN_LN LS
            WHERE 1=1
              AND LS.MSR_TP_CD  IN ('THRY_CAPA_D', 'PROD_OP_RT')
            GROUP BY LS.LN_ALTER_KEY
                    ,LS.YYYYMM;

            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 전극 라인별 Loss - 생산 Capa (월) 추가');
