            INSERT INTO GT_SMCC2_ELTR_LOSS_PLAN_LN ( LN_ALTER_KEY, MSR_GR_CD, MSR_TP_CD, YYYYMM, MSR_NVL, MSR_DDN, ATTRIBUTE1, ATTRIBUTE10 )
            SELECT LS.LN_ALTER_KEY
                  ,'-'              AS MSR_GR_CD
                  ,'PROD_CAPA_M'    AS MSR_TP_CD
                  ,LS.YYYYMM
                  ,CAST(LS.MSR_NVL AS NUMBER) * YM.YYYYMM_DDN
                                    AS MSR_NVL
                  ,NULL             AS MSR_DDN
                  ,NULL             AS ATTRIBUTE1
                  ,NULL             AS ATTRIBUTE10
             FROM GT_SMCC2_ELTR_LOSS_PLAN_LN LS
                , GT_SMCC2_ELTR_YYYYMM_DAYS_SOP YM  /* 2024/8/29 SOP적용 */
            WHERE 1=1
              AND YM.YYYYMM         = LS.YYYYMM
              AND YM.LN_ALTER_KEY   = LS.LN_ALTER_KEY
              AND LS.MSR_TP_CD  = 'PROD_CAPA_D';


        /* -- start 전극 실적 (M-1) */
        /* -- start 전극 실적 (M-1) */
        /* -- start 전극 실적 (M-1) */


            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 전극 LOSS 라인별 실적(M-1) -  #ELTR_LOSS_RSLT_WITH_ALTER_KEY');
            /* ----------------------------------------------------------------------------------------------------------------- */
            /* 원본 IF OBJECT_ID('TEMPDB..#ELTR_LOSS_RSLT_WITH_ALTER_KEY') IS NOT NULL DROP TABLE #ELTR_LOSS_RSLT_WITH_ALTER_KEY -> GTT 초기화 */
            DELETE FROM GT_SMCC2_ELTR_LOSS_RSLT_AK;

            INSERT INTO GT_SMCC2_ELTR_LOSS_RSLT_AK ( LN_ALTER_KEY, MSR_GR_CD, MSR_TP_CD, YYYYMM, MSR_NVL, MSR_DDN, YYYYMM_DDN )
            SELECT AK.LN_ALTER_KEY
                  ,LR.LOSS_GR_CD    AS MSR_GR_CD
                  ,LR.LOSS_CD       AS MSR_TP_CD
                  ,'RSLT'           AS YYYYMM
                  ,CAST(
                    CASE WHEN LR.LOSS_GR_CD = 'NAV'
                        THEN CAST(LR.LOSS_RT AS NUMBER) * CAST(LR.ATTRIBUTE1 AS NUMBER)  /* 2024/10/29 지표 제외 적용 실적 최대조업일수 적용 */
                        ELSE LR.LOSS_RT
                    END AS NUMBER(20,10))                           AS MSR_NVL          /* 5/14 비조업 일수로 반영 필요 */
                  ,CAST(
                    CASE WHEN LR.LOSS_GR_CD = 'NAV'
                         THEN CAST(LR.LOSS_RT AS NUMBER) * CAST(LR.ATTRIBUTE1 AS NUMBER)  /* 2024/10/29 지표 제외 적용 실적 최대조업일수 적용 */
                         ELSE CAST(LR.LOSS_TM_SSN AS NUMBER) / CAST(86400 AS NUMBER)
                     END AS NUMBER(20,10))                          AS MSR_DDN
                  ,MAX(CASE WHEN LR.LOSS_CD = 'AV_RT'
                            THEN CAST(LR.ATTRIBUTE1 AS NUMBER)
                            ELSE NULL
                        END)  OVER (PARTITION BY AK.LN_ALTER_KEY)   AS YYYYMM_DDN       /* 2024/10/29 지표 제외 적용 실적 최대조업일수 */
             FROM SCM_DNM_ELTR_LOSS_LN_MMLY LR
                , GT_SMCC2_ELTR_ALTER_KEY_LN AK
            WHERE 1=1
              AND AK.DIVISION_ID      = LR.DIVISION_ID
              AND AK.PLANT_ID     = LR.PLANT_ID
              AND AK.LINE_ID          = LR.LINE_ID
              AND AK.OPERATION_ID  = LR.OPERATION_ID
              AND AK.COMPANY_ID   = LR.COMPANY_ID
              AND AK.SITE_ID          = LR.SITE_ID
              AND AK.FACTORY_ID   = LR.FACTORY_ID
              AND LR.LOSS_YM        = V_LOSS_RSLT_YYYYMM
              AND LR.PERD_DIVS_CD   = '1'   /* M-1월 1개월실적 */
              AND LR.LOSS_CD NOT IN ('PF', 'PROD_AVG_SPED', 'MMD_SPED');

