            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 전극 LOSS 라인별 실적(M-1)  - SOP적용된 실적(RSLT) 최대조업일수 Update'); /* 2024/10/29 */
            /* ----------------------------------------------------------------------------------------------------------------- */

            UPDATE GT_SMCC2_ELTR_YYYYMM_DAYS_SOP SO
               SET SO.YYYYMM_DDN = ( SELECT AV.YYYYMM_DDN
                                       FROM GT_SMCC2_ELTR_LOSS_RSLT_AK AV
                                      WHERE AV.YYYYMM           = SO.YYYYMM
                                        AND AV.LN_ALTER_KEY     = SO.LN_ALTER_KEY
                                        AND AV.MSR_TP_CD        = 'AV_RT'
                                        AND ROWNUM = 1 )
             WHERE 1=1
               AND EXISTS ( SELECT 1
                              FROM GT_SMCC2_ELTR_LOSS_RSLT_AK AV
                             WHERE AV.YYYYMM        = SO.YYYYMM
                               AND AV.LN_ALTER_KEY  = SO.LN_ALTER_KEY
                               AND AV.MSR_TP_CD     = 'AV_RT' );

            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 전극 LOSS 라인별 실적(M-1) - 실적 추가');
            /* ----------------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SMCC2_ELTR_LOSS_PLAN_LN ( LN_ALTER_KEY, MSR_GR_CD, MSR_TP_CD, YYYYMM, MSR_NVL, MSR_DDN, ATTRIBUTE1, ATTRIBUTE10 )
            SELECT LR.LN_ALTER_KEY
                  ,LR.MSR_GR_CD
                  ,LR.MSR_TP_CD
                  ,'RSLT'           AS YYYYMM
                  ,LR.MSR_NVL
                  ,CASE WHEN LR.MSR_TP_CD = 'PF_RT'     THEN CAST(LR.MSR_NVL AS NUMBER) * CAST(OP.MSR_DDN AS NUMBER)                                            /* 성능가동일수  : 성능가동률 * 시간가동일수 */
                        WHEN LR.MSR_TP_CD = 'QL_RT'     THEN CAST(LR.MSR_NVL AS NUMBER)
                                                            * CAST(CAST((CAST(PF.MSR_NVL AS NUMBER) * CAST(OP.MSR_DDN AS NUMBER)) AS NUMBER(20,10)) AS NUMBER)  /* 양품가동일수  : 양품가동률 * 성능가동일수 (성능가동률 * 시간가동일수) */
                        ELSE LR.MSR_DDN
                    END             AS MSR_DDN
                  ,CASE WHEN LR.MSR_TP_CD = 'AV_RT' OR LR.MSR_GR_CD = 'NAV' THEN YM.YYYYMM_DDN  /* 조업/비조업       : 최대조업일수 */
                        WHEN LR.MSR_TP_CD = 'LD_RT' OR LR.MSR_GR_CD = 'NLD' THEN AV.MSR_DDN     /* 부하/비부하       : 조업일수 */
                        WHEN LR.MSR_TP_CD = 'OP_RT' OR LR.MSR_GR_CD = 'NOP' THEN LD.MSR_DDN     /* 시간가동/비가동 : 부하일수 */
                        WHEN LR.MSR_TP_CD = 'PF_RT'                         THEN OP.MSR_DDN     /* 성능가동률        : 시간가동일수 */
                        WHEN LR.MSR_TP_CD = 'QL_RT'                         THEN PF.MSR_DDN     /* 양품가동률        : 성능가동일수 */
                        ELSE NULL
                    END             AS ATTRIBUTE1
                  ,NULL             AS ATTRIBUTE10
             FROM GT_SMCC2_ELTR_LOSS_RSLT_AK LR
                , GT_SMCC2_ELTR_YYYYMM_DAYS_SOP YM  /* 2024/8/29 SOP적용 */
                , GT_SMCC2_ELTR_LOSS_RSLT_AK AV
                , GT_SMCC2_ELTR_LOSS_RSLT_AK LD
                , GT_SMCC2_ELTR_LOSS_RSLT_AK OP
                , GT_SMCC2_ELTR_LOSS_RSLT_AK PF
            WHERE 1=1
              AND YM.YYYYMM(+)      = 'RSLT' /* 실적년월 일수 */
              AND YM.LN_ALTER_KEY(+)= LR.LN_ALTER_KEY
              AND AV.LN_ALTER_KEY(+) = LR.LN_ALTER_KEY
              AND AV.MSR_TP_CD(+)   = 'AV_RT' /* 조업률/조업일수 */
              AND LD.LN_ALTER_KEY(+) = LR.LN_ALTER_KEY
              AND LD.MSR_TP_CD(+)   = 'LD_RT' /* 부하율/부하일수 */
              AND OP.LN_ALTER_KEY(+) = LR.LN_ALTER_KEY
              AND OP.MSR_TP_CD(+)   = 'OP_RT' /* 시간가동률/시간가동일수 */
              AND PF.LN_ALTER_KEY(+) = LR.LN_ALTER_KEY
              AND PF.MSR_TP_CD(+)   = 'PF_RT'; /* 성능가동률/성능가동일수 */

        /* -- end 전극 실적 (M-1) */
        /* -- end 전극 실적 (M-1) */
        /* -- end 전극 실적 (M-1) */


