            /* ---------------------------------------------------------------------------------------------------------------------------- */
            /* 원본 UPDATE TG SET .. FROM SCP_MST_CAPA_LOSS_PLAN_MDL_CUTF TG INNER JOIN #.. SC ON (10키) 는 Oracle 미지원.
               ★조인키에 SITE_ID 가 빠져 있는 것은 원본 그대로다(임의 보정 금지). 다중매치 가능성이 있어 */
            UPDATE SCP_MST_CAPA_LOSS_PLAN_MDL_CUTF    TG
               SET TG.ATTRIBUTE10       = '변경전[MSR_NVL=' || TO_CHAR(NVL(TG.MSR_NVL,0)) || '][MSR_DDN=' || TO_CHAR(NVL(TG.MSR_DDN,0)) || ']'
                  ,TG.MSR_DDN           = ( SELECT SC.MSR_DDN
