                  ,ATTRIBUTE2   /* (조업)조업일수/(부하)부하일수/(시간가동)시간가동일수/(성능가동)성능가동일수/(양품가동)양품가동일수 */
                  ,ATTRIBUTE3   /* 설비대수 */
                  ,ATTRIBUTE4   /* 이론 Capa */
                  ,ATTRIBUTE5   /* 부하율 */
                  ,ATTRIBUTE6   /* 시간가동률 */
                  ,ATTRIBUTE7   /* 성능가동률 */
                  ,ATTRIBUTE8   /* 2024.09.12 SOP적용 최대 조업일수 */
                  ,ATTRIBUTE10
                )
            SELECT V_VER_ID
                  ,V_VER_SEQ  /* - select '' */
                  ,AK.DIVISION_ID
                  ,AK.PLANT_ID
                  ,AK.LINE_ID
                  ,AK.OPERATION_ID
                  ,AK.ELTR_LN_TP_CD
                  ,AK.COMPANY_ID
                  ,AK.SITE_ID
                  ,AK.FACTORY_ID
                  ,LT.MSR_TP_CD
                  ,LT.YYYYMM
                  ,LT.MSR_GR_CD
                  ,LT.MSR_NVL
                  ,LT.MSR_DDN
                  ,V_PROGRAM_NAME       AS CREATED_BY
                  ,SYSDATE              AS CREATION_DATE
                  ,V_PROGRAM_NAME       AS LAST_UPDATED_BY
                  ,SYSDATE              AS LAST_UPDATE_DATE
                  ,CASE WHEN LT.MSR_TP_CD IN ('AV_RT', 'LD_RT', 'OP_RT', 'PF_RT', 'QL_RT')
                        THEN TO_CHAR(DN.P_DDN)  /* (조업)최대조업일수/(부하)조업일수/(시간가동)부하일수/(성능가동)시간가동일수/(양품가동)성능가동일수 */
                        WHEN LT.MSR_GR_CD = 'NLD'               /* 비부하 */
                        THEN TO_CHAR(RD.AV_DDN) /* 조업일수 */
                        WHEN LT.MSR_GR_CD = 'NOP'               /* 비가동 */
                        THEN TO_CHAR(RD.LD_DDN) /* 부하일수 */
                        WHEN LT.MSR_TP_CD = 'PPM'
                        THEN TO_CHAR(RD.QL_DDN) /* 양품가동일수 */
                        ELSE NULL
                    END AS ATTRIBUTE1
                  ,CASE WHEN LT.MSR_TP_CD IN ('AV_RT', 'LD_RT', 'OP_RT', 'PF_RT', 'QL_RT')
                        THEN TO_CHAR(DN.C_DDN)      /* (조업)조업일수/(부하)부하일수/(시간가동)시간가동일수/(성능가동)성능가동일수/(양품가동)양품가동일수 */
                        WHEN LT.MSR_TP_CD = 'PPM'
                        THEN TO_CHAR(ET.YYYYMM_DDN) /* 월(년)최대조업일수 */
                        ELSE NULL
                    END AS ATTRIBUTE2
                  ,TO_CHAR(NVL(ET.EQP_NBU ,0.)) AS ATTRIBUTE3   /* 설비대수 */
                  ,CASE WHEN LT.MSR_TP_CD = 'PF_RT'
                        THEN TO_CHAR(NVL(ET.THRY_CAPA_D, 0.))   /* 성능가동률 : 이론Capa */
                        WHEN LT.MSR_TP_CD = 'QL_RT'
                        THEN TO_CHAR(NVL(RD.AV_RT, 0.))         /* 8/14 양품가동률 변경(이론Capa->조업률) */
                        WHEN LT.MSR_TP_CD = 'PPM'
                        THEN TO_CHAR(ET.TEEP)                   /* PPM : TEEP */
                        ELSE NULL
                    END AS ATTRIBUTE4
                  ,CASE WHEN LT.MSR_TP_CD IN ('PF_RT', 'QL_RT')
                        THEN TO_CHAR(NVL(RD.LD_RT, 0.))
                        ELSE NULL
                    END AS ATTRIBUTE5   /* 부하율 */
                  ,CASE WHEN LT.MSR_TP_CD IN ('PF_RT', 'QL_RT')
                        THEN TO_CHAR(NVL(RD.OP_RT, 0.))
                        ELSE NULL
                    END AS ATTRIBUTE6   /* 시간가동률 */
                  ,CASE WHEN LT.MSR_TP_CD IN ('QL_RT')
                        THEN TO_CHAR(NVL(RD.PF_RT, 0.))
                        ELSE NULL
                    END AS ATTRIBUTE7   /* 성능가동률 */
                  ,CAST(YM.YYYYMM_DDN AS NUMBER(20,10))     AS ATTRIBUTE8   /* 2024.09.12 SOP적용 최대 조업일수 */
