            /* 원본 CONVERT(NVARCHAR(100), GETDATE(), 25) 은 style 25 = 'yyyy-mm-dd hh:mi:ss.mmm' 이다. */
            UPDATE SCP_MST_CAPA_VERSION CV
               SET PROG_STAT                = '2'   /* 2차 컷오프 완료 */
                  ,LAST_UPDATED_BY          = V_PROGRAM_NAME
                  ,LAST_UPDATE_DATE         = SYSDATE
                  ,ATTRIBUTE10              = '[PROG_STAT:''1'' to ''2'']' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3')
             WHERE 1=1
               AND CV.DIVISION_ID   = V_DIVISION_ID
               AND CV.VER_ID        = V_VER_ID
               AND CV.VER_SEQ       = V_VER_SEQ
               AND CV.PROG_STAT     = '1';  /* 1차 컷오프 완료 */

        /* ------------------------- end 버전 상태 처리 */
        /* ------------------------- end 버전 상태 처리 */


          COMMIT;  /* - transaction 종료   (원본 COMMIT TRAN ;) */

        /* ----- End Tran : ========================================================================================================== */
        /* ----- End Tran : ========================================================================================================== */

            V_LOG_TYPE := 'TXN';
            V_LOG_MESSAGE := 'END - ' || V_DIVISION_ID;
            V_DESCRIPTION := '[' || V_DIVISION_ID || '::' || V_VER_ID || '::' || TO_CHAR(V_VER_SEQ) ||  ']';
            D_EVENT_DATE := SYSDATE;
            PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER);
            V_LOG_MESSAGE := NULL;

        END LOOP;  /* --- // WHILE @@FETCH_STATUS = 0 */

        /* 2025.01.06 CPS_BATCH_PROC_RUN lookup 참조하여 next 버전 생성 프로시저 수행 */
        SELECT COUNT(*)
          INTO N_NEXT_VER_RUN
          FROM ( SELECT 1
                     FROM SCM_ADM_LOOKUP_MASTER_DETAIL LK
                    WHERE LK.LOOKUP_TYPE    = 'CPS_BATCH_PROC_RUN'
                      AND LK.SEGMENT1       = 'PR_SCP_MST_CAPA_CUTF_2ND'            /* 상위 프로시저 : 2차 컷오프 */
                      AND LK.SEGMENT2       = 'PR_SCP_MST_CAPA_VERSION_CREATION'    /* 하위 프로시저 : CPS 버전 생성 */
                      AND LK.VALID_YN       = 'Y'
                      AND LK.ATTRIBUTE1     = 'Y'                                       /* 수행여부 */
                      AND ROWNUM = 1
               );

        IF N_NEXT_VER_RUN > 0
        THEN
            /* ----------------------------------------------------------------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' 다음 Plan 버전 생성 ################################### ');
            /* ----------------------------------------------------------------------------------------------------------------- */
            PR_SCP_MST_CAPA_VERSION_CREATION;   /* 다음 버전 생성 */
        END IF;


      END IF; /* ---------------------------------- // IF @V_IS_MANUAL = 'Y' OR 2차 컷오프 수행일 */


        /* ------------------------------------- */
        /* -- 임시테이블 정리 */
        /* --------------------------------------- */
        /* 원본 IF OBJECT_ID('TEMPDB..#X') IS NOT NULL DROP TABLE #X; 는 GTT 를 DROP 할 수 없으므로 DELETE 로 옮긴다. */
        /* 조립/팩 */
        DELETE FROM GT_SMCC2_CUTOFF_DATE_INFO;
        DELETE FROM GT_SMCC2_CPS_FORMATION_OP;
        DELETE FROM GT_SMCC2_LOSS_PLAN_MDL_CUTF;
        DELETE FROM GT_SMCC2_LOSS_PLAN_LN_TTZM;
        DELETE FROM GT_SMCC2_SPEED_PLAN_CUTF;
        DELETE FROM GT_SMCC2_YYYYMM_DAYS_INFO;
        DELETE FROM GT_SMCC2_ALTER_KEY_INFO_LN;
        DELETE FROM GT_SMCC2_LOSS_MDL_CUTOFF_AK;
        DELETE FROM GT_SMCC2_PPM;
        DELETE FROM GT_SMCC2_AV_LD_OP_PF_QL;
        DELETE FROM GT_SMCC2_MSR_DDN;
        DELETE FROM GT_SMCC2_MSR_DDN_LN_SUM;
        DELETE FROM GT_SMCC2_LOSS_RSLT_AK;
        /*           IF OBJECT_ID('TEMPDB..#EQP_SPED_RESULT') IS NOT NULL DROP TABLE #EQP_SPED_RESULT; */
        DELETE FROM GT_SMCC2_PRVS_CAPA_LOSS_PLAN;
        DELETE FROM GT_SMCC2_BIZP_CAPA_LOSS_PLAN;
        DELETE FROM GT_SMCC2_AV_LD_OP_PF_QL_LN;
        DELETE FROM GT_SMCC2_MSR_DDN_LN;
        DELETE FROM GT_SMCC2_EQP_NBU_THRY_CAPA_D;
        DELETE FROM GT_SMCC2_AV_LD_OP_PF_QL_RT_DDN;
        DELETE FROM GT_SMCC2_LINE_SOP;
        DELETE FROM GT_SMCC2_YYYYMM_DAYS_SOP;
        /* -- 전극 */
        DELETE FROM GT_SMCC2_ELTR_LOSS_PLAN_LN;
        DELETE FROM GT_SMCC2_ELTR_LOSS_PLAN_MDL;
        DELETE FROM GT_SMCC2_ELTR_ALTER_KEY_LN;
        DELETE FROM GT_SMCC2_ELTR_YYYYMM_DAYS;
        DELETE FROM GT_SMCC2_ELTR_LOSS_RSLT_AK;
        DELETE FROM GT_SMCC2_ELTR_PRVS_LOSS_PLAN;
        DELETE FROM GT_SMCC2_ELTR_BIZP_LOSS_PLAN;
        DELETE FROM GT_SMCC2_ELTR_LINE_SOP;
        DELETE FROM GT_SMCC2_ELTR_YYYYMM_DAYS_SOP;


    EXCEPTION
        WHEN OTHERS THEN

            IF DBMS_TRANSACTION.LOCAL_TRANSACTION_ID IS NOT NULL THEN
                ROLLBACK;
            END IF;


            /* ERROR LOG */
            V_LOG_TYPE := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := SUBSTR('ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 500);
            D_EVENT_DATE := SYSDATE;
            PR_SCP_SYS_LOG_BATCH( P_PROGRAM_NAME    => V_PROGRAM_NAME
                                 ,P_LOG_TYPE        => V_LOG_TYPE
                                 ,P_LOG_COUNT       => N_LOG_COUNT
                                 ,P_LOG_MESSAGE     => V_LOG_MESSAGE
                                 ,P_DESCRIPTION     => V_DESCRIPTION
                                 ,P_EVENT_DATE      => D_EVENT_DATE
                                 ,P_USER_ID         => V_BATCH_USER
                                 );
            DBMS_OUTPUT.PUT_LINE(V_LOG_MESSAGE      || ' : ' || V_DESCRIPTION);

            RAISE_APPLICATION_ERROR(-20001
                                   ,'[' || V_PROGRAM_NAME || '] SQLCODE=' || SQLCODE || ' / SQLERRM=' || SQLERRM
                                    || ' / BACKTRACE=' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
    END;


    V_ELAPSED_SEC := ROUND((SYSDATE - V_START_TIME) * 86400);
    V_EXEC_TIME  :=  LPAD(TO_CHAR(TRUNC(V_ELAPSED_SEC / 60)), 2, '0') || ':' ||
                     LPAD(TO_CHAR(MOD(V_ELAPSED_SEC, 60)), 2, '0');
    /* 종료 LOG */
    V_LOG_TYPE := 'END';
    V_LOG_MESSAGE := '##### END of procedure #####';
    V_DESCRIPTION := '['  || V_EXEC_TIME || ']';
    D_EVENT_DATE := SYSDATE;
    PR_SCP_SYS_LOG_BATCH( P_PROGRAM_NAME    => V_PROGRAM_NAME
                         ,P_LOG_TYPE        => V_LOG_TYPE
                         ,P_LOG_COUNT       => N_LOG_COUNT
                         ,P_LOG_MESSAGE     => V_LOG_MESSAGE
                         ,P_DESCRIPTION     => V_DESCRIPTION
                         ,P_EVENT_DATE      => D_EVENT_DATE
                         ,P_USER_ID         => V_BATCH_USER
                         );
    DBMS_OUTPUT.PUT_LINE(V_LOG_MESSAGE      || ' : ' || V_DESCRIPTION);

    RETURN;

END;

PROCEDURE PR_SCP_MST_CHAR_CAPA
AS
/*
 * Program ID   : PR_SCP_MST_CHAR_CAPA
 * Description  : SCP_MST_CHAR_CAPA(특성 CAPA) 테이블 데이터 생성
 *
 *                -------------------------------------------------
 *                1. SCP_MST_CHAR_CAPA 데이터 임시테이블로 생성
 *                -------------------------------------------------
 *                   - 1) 컬럼
 *                        - scp_mst_char_capa.daily_capa_qty 컬럼 : scp_mst_tact_time 테이블에서 division_id, plant_site_id, item_id 별  SUM(ROUND((1440 * 60) / tact_time, 0))
 *                        - scp_mst_char_capa.item_id 컬럼        : item_id가 '-'는  TOTAL 값을 나타냄(1,999,999,999 으로 하드코딩함)
 *                   - 2) 대상
 *                        - 사업부별 scp_mst_tact_time 중 operation_id 가 A3000, A9000 (LINE CAPA 대상인 셀 공정)
 *                   - 3) 생성제외
 *                        - created_by, last_updated_by 컬럼의 아이디가 사용자가 등록/수정한 데이터는 생성안함(created_by, last_updated_by 가 'scp_batch'가 아닌 데이터는 생성안함)
 *
 *                -------------------------------------------------
 *                2. 자동생성된 SCP_MST_CHAR_CAPA 데이터 삭제
 *                -------------------------------------------------
 *                   - 자동생성된 데이터 삭제: created_by, last_updated_by 가 'scp_batch' 인 데이터만 삭제
 *
 *                -------------------------------------------------
 *                3. SCP_MST_CHAR_CAPA 데이터 INSERT
 *                -------------------------------------------------
 *
 *                -------------------------------------------------
 *                4. SCP_MST_CHAR_CAPA TOTAL 데이터 INSERT
 *                -------------------------------------------------
 *                    - SCP_MST_CHAR_CAPA 테이블의 division_id, plant_site_id  별 TOTAL 1개 생성
 *                    - item_id 컬럼        : '-'로 셋팅
 *                    - daily_capa_qty 컬럼 : 1999999999 로 셋팅
 * OutTable     :
 * Execute      :    EXEC PR_SCP_MST_CHAR_CAPA
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 *   2019.01.08   KSW           Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 *   2026.07.06   ZIONEX        [PJ202650304] NextSCM Migration
 */
    /* LOG 용 변수 설정 */
    V_BATCH_USER      VARCHAR2(150 CHAR) := 'scp_batch';
    V_PROGRAM_NAME    VARCHAR2(150 CHAR) := 'PR_SCP_MST_CHAR_CAPA';
    V_LOG_TYPE        VARCHAR2(30 CHAR);                /* START/END/ERROR/... */
    N_LOG_COUNT       INTEGER := 0;
    V_LOG_MESSAGE     VARCHAR2(1000 CHAR);
    V_DESCRIPTION     VARCHAR2(500 CHAR);
    V_TABLE_ID        VARCHAR2(150 CHAR) := 'SCP_MST_CHAR_CAPA';
    D_EVENT_DATE      DATE;

    D_CREATE_DATE     DATE := SYSDATE;                  /* 데이터 생성 시간 */
    V_ERRMSG          VARCHAR2(4000 CHAR);
BEGIN
    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := V_PROGRAM_NAME || ':' || ' SCP_MST_CHAR_CAPA INSERT';
    D_EVENT_DATE  := SYSDATE;
    PR_SCP_SYS_LOG_BATCH(P_PROGRAM_NAME => V_PROGRAM_NAME, P_LOG_TYPE => V_LOG_TYPE, P_LOG_COUNT => N_LOG_COUNT
                       , P_LOG_MESSAGE => V_LOG_MESSAGE, P_DESCRIPTION => V_DESCRIPTION, P_EVENT_DATE => D_EVENT_DATE, P_USER_ID => V_BATCH_USER);

    BEGIN
        /* 1. SCP_MST_CHAR_CAPA 생성데이터 임시테이블에 생성 */

        DELETE FROM GT_SMCC_TMP;

        /* SCP_MST_CHAR_CAPA 데이터 임시테이블로 생성 */
        INSERT INTO GT_SMCC_TMP
        (      DIVISION_ID
            ,  PLANT_SITE_ID
            ,  ITEM_ID
            ,  DAILY_CAPA_QTY
        )
        WITH WITH_TACT_TIME
        AS
        (    SELECT TT.DIVISION_ID
                 ,  TT.PLANT_SITE_ID
                 ,  TT.ITEM_ID
                 ,  SUM(ROUND((1440 * 60) / TT.TACT_TIME, 0)) AS SUM_DAILY_CAPA_QTY
             FROM   SCP_MST_TACT_TIME TT
             WHERE  TT.VALID_YN = 'Y'
             /* AND    TT.DIVISION_ID = @P_DIVISION_ID */
             AND    TT.OPERATION_ID IN ( SELECT  B.SEGMENT2 AS OPERATION_ID
                                         FROM    SCM_ADM_LOOKUP_MASTER_DETAIL A
                                                 INNER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL B
                                                 ON  A.SEGMENT1    = B.SEGMENT1
                                                 AND A.LOOKUP_TYPE = 'LOCATION_GROUP'
                                                 AND A.SEGMENT4    = 'Y' /* Capa 공정 여부 */
                                                 AND A.SEGMENT5    = 'Y' /* Line 별 Capa 적용 공정( Capa공정여부가 'N'이면  Line 별 Capa 적용 공정이 'Y'가 될수없음) */
                                                 AND A.VALID_YN    = 'Y'
                                                 AND B.LOOKUP_TYPE = 'LOCATION_GROUP_ROUTE'
                                                 AND B.VALID_YN    = 'Y'
                                                 AND B.SEGMENT3    = 'Y' /* Capa 세부 공정 여부 */
                                                 AND A.SEGMENT3    = 'A' /* 셀 Capa  공정(A3000, A9000) */
                                       ) /* LINE CAPA 대상인 셀 공정 */
             GROUP BY TT.DIVISION_ID, TT.PLANT_SITE_ID, TT.ITEM_ID
        ) /* WITH문 종료 */
        SELECT WTT.DIVISION_ID
             , WTT.PLANT_SITE_ID
             , WTT.ITEM_ID
             , WTT.SUM_DAILY_CAPA_QTY AS DAILY_CAPA_QTY
        FROM  WITH_TACT_TIME WTT
        WHERE NOT EXISTS ( SELECT 1
                           FROM   SCP_MST_CHAR_CAPA A
                           WHERE  A.DIVISION_ID        = WTT.DIVISION_ID
                           AND    A.PLANT_SITE_ID      = WTT.PLANT_SITE_ID
                           AND    A.ITEM_ID            = WTT.ITEM_ID
                           /* AND    A.VALID_YN           = 'Y' */
                           AND    (A.CREATED_BY         <> V_BATCH_USER /* 'scp_batch' */
                                   OR
                                   A.LAST_UPDATED_BY    <> V_BATCH_USER)
                         );

        N_LOG_COUNT   := SQL%ROWCOUNT;
        V_LOG_TYPE    := 'TXN';
        V_LOG_MESSAGE := '1.SCP_MST_CHAR_CAPA 생성 데이터 임시테이블에 생성';
        V_DESCRIPTION := 'SCP_MST_CHAR_CAPA INSERT 대상데이터 임시테이블에 생성' || ':' || TO_CHAR(D_EVENT_DATE, 'YYYYMMDD');
        D_EVENT_DATE  := SYSDATE;
        PR_SCP_SYS_LOG_BATCH(P_PROGRAM_NAME => V_PROGRAM_NAME, P_LOG_TYPE => V_LOG_TYPE, P_LOG_COUNT => N_LOG_COUNT
                           , P_LOG_MESSAGE => V_LOG_MESSAGE, P_DESCRIPTION => V_DESCRIPTION, P_EVENT_DATE => D_EVENT_DATE, P_USER_ID => V_BATCH_USER);

        /* 2. SCP_MST_CHAR_CAPA 삭제 : 자동생성된 데이터만( created_by, last_updated_by 가 'scp_batch' 인 데이터) 삭제 */
        DELETE FROM SCP_MST_CHAR_CAPA
        WHERE CREATED_BY      = V_BATCH_USER  /* 'scp_batch' */
        AND   LAST_UPDATED_BY = V_BATCH_USER  /* 'scp_batch' */
        /* AND   DIVISION_ID    = @P_DIVISION_ID */
        /*     OR VALID_YN = 'N' */
        ;

        N_LOG_COUNT   := SQL%ROWCOUNT;
        V_LOG_TYPE    := 'TXN';
        V_LOG_MESSAGE := '2.DELETE ' || V_TABLE_ID;
        V_DESCRIPTION := '사용자 아이디가 scp_batch로 생성된 데이터 삭제처리' || ':' || TO_CHAR(D_EVENT_DATE, 'YYYYMMDD');
        D_EVENT_DATE  := SYSDATE;
        PR_SCP_SYS_LOG_BATCH(P_PROGRAM_NAME => V_PROGRAM_NAME, P_LOG_TYPE => V_LOG_TYPE, P_LOG_COUNT => N_LOG_COUNT
                           , P_LOG_MESSAGE => V_LOG_MESSAGE, P_DESCRIPTION => V_DESCRIPTION, P_EVENT_DATE => D_EVENT_DATE, P_USER_ID => V_BATCH_USER);

        /* 3.SCP_MST_CHAR_CAPA 입력 */
        INSERT INTO /* PR_SCP_MST_CHAR_CAPA */ SCP_MST_CHAR_CAPA
        (  DIVISION_ID
         , PLANT_SITE_ID
         , ITEM_ID
         , DAILY_CAPA_QTY
         , VALID_YN
         , CREATED_BY
         , CREATION_DATE
         , LAST_UPDATED_BY
         , LAST_UPDATE_DATE
        )
        SELECT TT.DIVISION_ID
             , TT.PLANT_SITE_ID
             , TT.ITEM_ID
             , TT.DAILY_CAPA_QTY
             , 'Y'              AS VALID_YN
             , V_BATCH_USER     AS CREATED_BY
             , D_CREATE_DATE    AS CREATION_DATE
             , V_BATCH_USER     AS LAST_UPDATED_BY
             , D_CREATE_DATE    AS LAST_UPDATE_DATE
        FROM  GT_SMCC_TMP TT;

        /* TXN LOG */
        N_LOG_COUNT   := SQL%ROWCOUNT;
        V_LOG_TYPE    := 'TXN';
        V_LOG_MESSAGE := '3.INSERT INTO ' || V_TABLE_ID || ' (TOTAL제외)';
        V_DESCRIPTION := 'SCP_MST_CHAR_CAPA 데이터 생성(TOTAL 제외)' || ':' || TO_CHAR(D_EVENT_DATE, 'YYYYMMDD');
        D_EVENT_DATE  := SYSDATE;
        PR_SCP_SYS_LOG_BATCH(P_PROGRAM_NAME => V_PROGRAM_NAME, P_LOG_TYPE => V_LOG_TYPE, P_LOG_COUNT => N_LOG_COUNT
                           , P_LOG_MESSAGE => V_LOG_MESSAGE, P_DESCRIPTION => V_DESCRIPTION, P_EVENT_DATE => D_EVENT_DATE, P_USER_ID => V_BATCH_USER);

        /* 4.SCP_MST_CHAR_CAPA  TOTAL 생성 : 위 2.에서 생성된 데이터에서 division_id, plant_site_id 별 TOTAL값 생성 */
        /*   ( TOTAL 은  item_id컬럼에 '-'값으로, daily_capa_qty = 1999999999 값으로 입력함) */
        INSERT INTO /* PR_SCP_MST_CHAR_CAPA */ SCP_MST_CHAR_CAPA
        (  DIVISION_ID
         , PLANT_SITE_ID
         , ITEM_ID
         , DAILY_CAPA_QTY
         , VALID_YN
         , CREATED_BY
         , CREATION_DATE
         , LAST_UPDATED_BY
         , LAST_UPDATE_DATE
        )
        SELECT DIVISION_ID
            ,  PLANT_SITE_ID
            ,  '-'              AS ITEM_ID
            ,  1999999999       AS DAILY_CAPA_QTY    /* 1999999999은 하드코딩값 */
            , 'Y'               AS VALID_YN
            ,  V_BATCH_USER     AS CREATED_BY        /* 'scp_batch' */
            ,  D_CREATE_DATE    AS CREATION_DATE
            ,  V_BATCH_USER     AS LAST_UPDATED_BY   /* 'scp_bacth' */
            ,  D_CREATE_DATE    AS LAST_UPDATE_DATE
        FROM   SCP_MST_CHAR_CAPA
        /* WHERE  VALID_YN = 'Y' */
        GROUP BY DIVISION_ID, PLANT_SITE_ID;

        /* TXN LOG */
        N_LOG_COUNT   := SQL%ROWCOUNT;
        V_LOG_TYPE    := 'TXN';
        V_LOG_MESSAGE := '4.INSERT INTO ' || V_TABLE_ID || ' (TOTAL)';
        V_DESCRIPTION := 'SCP_MST_CHAR_CAPA TOTAL 데이터 생성' || ':' || TO_CHAR(D_EVENT_DATE, 'YYYYMMDD');
        D_EVENT_DATE  := SYSDATE;
        PR_SCP_SYS_LOG_BATCH(P_PROGRAM_NAME => V_PROGRAM_NAME, P_LOG_TYPE => V_LOG_TYPE, P_LOG_COUNT => N_LOG_COUNT
                           , P_LOG_MESSAGE => V_LOG_MESSAGE, P_DESCRIPTION => V_DESCRIPTION, P_EVENT_DATE => D_EVENT_DATE, P_USER_ID => V_BATCH_USER);

    EXCEPTION
        WHEN OTHERS THEN
            /* ERROR LOG */
            V_ERRMSG      := SQLERRM;
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(V_ERRMSG, 1, 1000);
            V_DESCRIPTION := SUBSTR('ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 500);
            D_EVENT_DATE  := SYSDATE;
            PR_SCP_SYS_LOG_BATCH(P_PROGRAM_NAME => V_PROGRAM_NAME, P_LOG_TYPE => V_LOG_TYPE, P_LOG_COUNT => N_LOG_COUNT
                               , P_LOG_MESSAGE => V_LOG_MESSAGE, P_DESCRIPTION => V_DESCRIPTION, P_EVENT_DATE => D_EVENT_DATE, P_USER_ID => V_BATCH_USER);
            RETURN;
    END;

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCP_SYS_LOG_BATCH(P_PROGRAM_NAME => V_PROGRAM_NAME, P_LOG_TYPE => V_LOG_TYPE, P_LOG_COUNT => 0
                       , P_LOG_MESSAGE => V_LOG_MESSAGE, P_DESCRIPTION => V_DESCRIPTION, P_EVENT_DATE => D_EVENT_DATE, P_USER_ID => V_BATCH_USER);
    RETURN;
END;

PROCEDURE PR_SCP_MST_GROUP_MODEL_MAPPING
(
      P_DIVISION_ID          IN VARCHAR2 DEFAULT NULL
)
/*******************************************************************************************************************
 * Program ID   : PR_SCP_MST_GROUP_MODEL_MAPPING
 * Description  : [재료비 TASK] 통합 integration 기초 정보 생성
 * OutTable     :
 * Execute      : EXEC PR_SCP_MST_GROUP_MODEL_MAPPING   @p_division_id = '81'
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2024.05.28                  Initial PJ20244573 LGES SCM SCP 생산모델 기반 공급계획 수립체계 구성 : 통합 integration 기초 정보 생성
 *
 * 2026.07.06   ZIONEX   [PJ202650304] NextSCM Migration
 *******************************************************************************************************************/
/* exec PR_SCP_MST_GROUP_MODEL_MAPPING '81' */
AS

    /* LOG 용 변수 설정 */
    V_BATCH_USER    VARCHAR2(150 CHAR) := 'scp_batch';
