    V_LOG_TYPE      VARCHAR2(30 CHAR);   /* START/END/ERROR/... */
    N_LOG_COUNT     NUMBER := 0;
    V_LOG_MESSAGE   VARCHAR2(1000 CHAR);
    V_DESCRIPTION   VARCHAR2(500 CHAR);
    V_TABLE_ID      VARCHAR2(150 CHAR) := 'SCP_MST_ITEM_GROUP_DETAIL';
    D_EVENT_DATE    DATE;

    /* 임시 실행시간 확인용 */
    V_START_TIME    DATE;
    V_EXEC_TIME     VARCHAR2(10 CHAR) := ''; /* '00:00' */
    V_SEC           NUMBER;

BEGIN

    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := V_PROGRAM_NAME || ':' || V_TABLE_ID || ' INSERT LOGIC';
    D_EVENT_DATE  := SYSDATE;
    PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER);

    /* 임시 실행시간 확인용 */
    V_START_TIME := SYSDATE;

    BEGIN

        INSERT
          INTO SCP_MST_ITEM_GROUP_DETAIL
             ( DIVISION_ID
             , PROJECT_CODE
             , ITEM_ID
             , VALID_YN
             , CREATION_DATE
             , CREATED_BY
             , LAST_UPDATE_DATE
             , LAST_UPDATED_BY )
        SELECT DISTINCT A.DIVISION_ID
             , A.PROJECT_CODE
             , A.ITEM_ID
             , 'Y'
             , SYSDATE
             , V_BATCH_USER
             , SYSDATE
             , V_BATCH_USER
          FROM SCM_MST_SITE_ITEM A
             , SCP_MST_FINAL_ITEM B
         WHERE A.DIVISION_ID            = B.DIVISION_ID(+)
           AND A.ITEM_ID                = B.ITEM_ID(+)
           AND A.DIVISION_ID            = NVL(P_DIVISION_ID, A.DIVISION_ID)
           AND A.ITEM_ID IS NOT NULL
           AND NVL(A.PROJECT_CODE, '-') <> '-'
           AND NOT EXISTS ( SELECT 1
                              FROM SCP_MST_ITEM_GROUP_DETAIL G
                             WHERE G.DIVISION_ID  = A.DIVISION_ID
                               AND G.PROJECT_CODE = A.PROJECT_CODE
                               AND G.ITEM_ID      = A.ITEM_ID
                          )
           AND A.VALID_YN = 'Y'
        ;

        /* TXN LOG */
        N_LOG_COUNT   := SQL%ROWCOUNT;
        COMMIT;
        V_LOG_TYPE    := 'TXN';
        V_LOG_MESSAGE := 'INSERT INTO ' || V_TABLE_ID;
        D_EVENT_DATE  := SYSDATE;
        V_DESCRIPTION := 'Process Complete...' || ':' || TO_CHAR(D_EVENT_DATE, 'YYYYMMDD');
        PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER);

    EXCEPTION
        WHEN OTHERS THEN

            /* IF @@TRANCOUNT > 0    */
            /*   BEGIN               */
            /*     ROLLBACK;         */
            /*   END;                */

            /* ERROR LOG */
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := 'ERROR_LINE : ' || SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 400);
            D_EVENT_DATE  := SYSDATE;
            PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER);

            /* 원본 MSSQL CATCH 는 ERROR LOG 후 return -1 로 예외를 삼킴(재전파 없음) → RETURN 으로 복원(END LOG 미실행). */
            RETURN;
    END;

    /* 임시 운영반영시에 주석처리 할것. */
    V_SEC       := ROUND((SYSDATE - V_START_TIME) * 86400);

    V_EXEC_TIME := CASE WHEN LENGTH(TO_CHAR(TRUNC(V_SEC / 60))) > 2 THEN NULL
                        ELSE LPAD(TO_CHAR(TRUNC(V_SEC / 60)), 2, '0') || ':' || LPAD(TO_CHAR(MOD(V_SEC, 60)), 2, '0')
                   END;

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '[' || NVL(P_DIVISION_ID, 'ALL') || '][' || V_EXEC_TIME || ']';
    D_EVENT_DATE  := SYSDATE;
    PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER);

END PR_SCP_MST_GROUP_MODEL_MAPPING;

PROCEDURE         PR_SCP_MST_MODEL_BOM_ADD_ASSY

/*
 * Program ID  : [PR_SCP_MST_MODEL_BOM_ADD_ASSY]
 * Description : Cell Product Model 기준으로 Cell Assy Model정보를 생성한다.

	* source table : SCM_MST_MODEL_BOM, SCP_MST_CELL_PROD_ASSY_MAP
	* target table : SCM_MST_MODEL_BOM
 *
 * Program History
 *============================================================================================================================
 *   Date		In Charge	Description
 *============================================================================================================================
 * 2023/06/22	hrkim		Initial Release  [PJ20230691] LGES SCM 역량 강화 위한 SCP 개선과제 이행 : 활성화코드 분리 대응
 * 2023/07/17	hrkim		PJ20230691 LGES SCM 역량 강화 위한 SCP 개선과제 이행 : 활성화코드 분리 대응 (8월 해외 오픈 대응)
 * 2023/07/26	hrkim		PJ20230691 LGES SCM 역량 강화 위한 SCP 개선과제 이행 : SCP_MST_CELL_PROD_ASSY_MAP 참조시 Valid_yn = 'Y' 조건 추가
 * 2025.09.08   kimcd       PJ20257329 최적화 Planning Input Constraint UI 개발 및 Master Validation 확산  :
 *                          제품 기준 NLevel 선정 로직 현실화
 *
 * 2026.07.06	ZIONEX		[PJ202650304] NextSCM Migration
 */
AS
    V_PROGRAM_NAME  VARCHAR2(150 CHAR) := 'PR_SCP_MST_MODEL_BOM_ADD_ASSY';
    V_LOG_TYPE      VARCHAR2(30 CHAR);
    N_LOG_COUNT     INTEGER := 0;
    V_LOG_MESSAGE   VARCHAR2(1000 CHAR);
    V_DESCRIPTION   VARCHAR2(500 CHAR);
    D_EVENT_DATE    DATE;
    V_BATCH_USER    VARCHAR2(150 CHAR) := 'scm_batch';
    V_START_TIME    DATE := SYSDATE;
    V_EXEC_TIME     VARCHAR2(10 CHAR);
    V_SEC           NUMBER;
BEGIN
    BEGIN

        /* 시작 LOG (START) : PR_SCM_SYS_LOG_BATCH (6 위치인자) */
        V_LOG_TYPE    := 'START';
        V_LOG_MESSAGE := '##### Start of procedure #####';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        /* 1. #tgt 대상 추출 (Cell Product MODEL -> Cell Assy MODEL) */
        INSERT INTO GT_ADDA_TGT
        ( BOM_PRIORITY, COMPANY_ID, DIVISION_ID, SITE_ID, PLANT_ID, MODEL_ID, PARENT_ITEM_ID, CHILD_ITEM_ID, CHILD_QTY, CHILD_UOM
        , ACCUMULATED_CHILD_QTY, CONCATENATE_ITEM, SORT_ORDER, LEAF_LEVEL, NLEVEL, CHILD_COMPANY_ID, CHILD_DIVISION_ID, CHILD_SITE_ID, CHILD_PLANT_ID
        , ALT_ID, ALT_PRIORITY, ALT_RATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10
        , ATTRIBUTE11, ATTRIBUTE12, ATTRIBUTE13, ATTRIBUTE14, CONCAT_ALT_PRIORITY, COPY_ALT_PRIORITY, SCP_PLAN_YN, ENG_ALT_ID, ENG_ALT_PRIORITY, ORG_ALT_ID, ORG_ALT_PRIORITY, CHILD_SEQ )
        SELECT
               ROW_NUMBER() OVER (PARTITION BY B.COMPANY_ID, B.DIVISION_ID, B.SITE_ID, B.PLANT_ID, M.ITEM_ID_ASSY
                                             , SUBSTR(B.CONCATENATE_ITEM, INSTR(B.CONCATENATE_ITEM, M.ITEM_ID_ASSY), LENGTH(B.CONCATENATE_ITEM))
                                  ORDER BY F.TCO_CELL_YN, M.ITEM_ID_PROD) AS BOM_PRIORITY
             , B.COMPANY_ID, B.DIVISION_ID, B.SITE_ID, B.PLANT_ID
             , M.ITEM_ID_ASSY AS MODEL_ID
             , CASE WHEN M.ITEM_ID_ASSY = B.CHILD_ITEM_ID THEN '*' ELSE B.PARENT_ITEM_ID END AS PARENT_ITEM_ID
             , B.CHILD_ITEM_ID, B.CHILD_QTY, B.CHILD_UOM, B.ACCUMULATED_CHILD_QTY
             , SUBSTR(B.CONCATENATE_ITEM, INSTR(B.CONCATENATE_ITEM, M.ITEM_ID_ASSY), LENGTH(B.CONCATENATE_ITEM)) AS CONCATENATE_ITEM
             , B.SORT_ORDER, B.LEAF_LEVEL
             , CASE WHEN INSTR(B.CONCATENATE_ITEM, M.ITEM_ID_ASSY) > 1
                    THEN B.NLEVEL - LENGTH(SUBSTR(B.CONCATENATE_ITEM, 1, INSTR(B.CONCATENATE_ITEM, M.ITEM_ID_ASSY)))
                              + LENGTH(REPLACE(SUBSTR(B.CONCATENATE_ITEM, 1, INSTR(B.CONCATENATE_ITEM, M.ITEM_ID_ASSY)), '^', ''))
                    ELSE B.NLEVEL
               END AS NLEVEL
             , B.CHILD_COMPANY_ID, B.CHILD_DIVISION_ID, B.CHILD_SITE_ID, B.CHILD_PLANT_ID
             , B.ALT_ID, B.ALT_PRIORITY, B.ALT_RATE
             , B.ATTRIBUTE1, B.ATTRIBUTE2, B.ATTRIBUTE3, B.ATTRIBUTE4, B.ATTRIBUTE5, B.ATTRIBUTE6, B.ATTRIBUTE7, B.ATTRIBUTE8, B.ATTRIBUTE9, B.ATTRIBUTE10
             , B.ATTRIBUTE11, B.ATTRIBUTE12, B.ATTRIBUTE13, B.ATTRIBUTE14, B.CONCAT_ALT_PRIORITY, B.COPY_ALT_PRIORITY, B.SCP_PLAN_YN
             , B.ENG_ALT_ID, B.ENG_ALT_PRIORITY, B.ORG_ALT_ID, B.ORG_ALT_PRIORITY, B.CHILD_SEQ
          FROM SCM_MST_MODEL_BOM B
             , SCP_MST_CELL_PROD_ASSY_MAP M
             , SCP_MST_FINAL_ITEM F
         WHERE 1 = 1
           AND M.DIVISION_ID = B.DIVISION_ID
           AND M.PLANT_ID = B.PLANT_ID
           AND M.ITEM_ID_PROD = B.MODEL_ID
           AND M.VALID_YN = 'Y'
           AND F.DIVISION_ID(+) = M.DIVISION_ID
           AND F.ITEM_ID(+) = M.ITEM_ID_PROD
           AND B.CONCATENATE_ITEM LIKE '%' || M.ITEM_ID_ASSY || '%';

        /* 2.2 DELETE : 기 생성된 Assy Model 삭제 */
        DELETE FROM SCM_MST_MODEL_BOM B
         WHERE 1 = 1
           AND EXISTS ( SELECT 1 FROM SCP_MST_CELL_PROD_ASSY_MAP M
                         WHERE M.DIVISION_ID = B.DIVISION_ID AND M.PLANT_ID = B.PLANT_ID AND M.ITEM_ID_ASSY = B.MODEL_ID );

        /* 2.2 INSERT : Assy Model 정보 등록 (BOM_PRIORITY=1, ATTRIBUTE15=CELL_ASSY) */
        INSERT INTO SCM_MST_MODEL_BOM
        ( COMPANY_ID, DIVISION_ID, SITE_ID, PLANT_ID, MODEL_ID, PARENT_ITEM_ID, CHILD_ITEM_ID, CHILD_QTY, CHILD_UOM, ACCUMULATED_CHILD_QTY
        , CONCATENATE_ITEM, SORT_ORDER, LEAF_LEVEL, NLEVEL, CHILD_COMPANY_ID, CHILD_DIVISION_ID, CHILD_SITE_ID, CHILD_PLANT_ID
        , ALT_ID, ALT_PRIORITY, ALT_RATE, INSERT_ID, INSERT_TIME, UPDATE_ID, UPDATE_TIME
        , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10
        , ATTRIBUTE11, ATTRIBUTE12, ATTRIBUTE13, ATTRIBUTE14, ATTRIBUTE15, CONCAT_ALT_PRIORITY, COPY_ALT_PRIORITY, SCP_PLAN_YN
        , ENG_ALT_ID, ENG_ALT_PRIORITY, ORG_ALT_ID, ORG_ALT_PRIORITY, CHILD_SEQ )
        SELECT B.COMPANY_ID, B.DIVISION_ID, B.SITE_ID, B.PLANT_ID, B.MODEL_ID, B.PARENT_ITEM_ID, B.CHILD_ITEM_ID, B.CHILD_QTY, B.CHILD_UOM, B.ACCUMULATED_CHILD_QTY
             , B.CONCATENATE_ITEM, B.SORT_ORDER, B.LEAF_LEVEL, B.NLEVEL, B.CHILD_COMPANY_ID, B.CHILD_DIVISION_ID, B.CHILD_SITE_ID, B.CHILD_PLANT_ID
             , B.ALT_ID, B.ALT_PRIORITY, B.ALT_RATE
             , V_PROGRAM_NAME, SYSDATE, V_PROGRAM_NAME, SYSDATE
             , B.ATTRIBUTE1, B.ATTRIBUTE2, B.ATTRIBUTE3, B.ATTRIBUTE4, B.ATTRIBUTE5, B.ATTRIBUTE6, B.ATTRIBUTE7, B.ATTRIBUTE8, B.ATTRIBUTE9, B.ATTRIBUTE10
             , B.ATTRIBUTE11, B.ATTRIBUTE12, B.ATTRIBUTE13, B.ATTRIBUTE14, 'CELL_ASSY', B.CONCAT_ALT_PRIORITY, B.COPY_ALT_PRIORITY, B.SCP_PLAN_YN
             , B.ENG_ALT_ID, B.ENG_ALT_PRIORITY, B.ORG_ALT_ID, B.ORG_ALT_PRIORITY, B.CHILD_SEQ
          FROM GT_ADDA_TGT B
         WHERE 1 = 1
           AND B.BOM_PRIORITY = 1;
        N_LOG_COUNT := SQL%ROWCOUNT;


        COMMIT;

    EXCEPTION
        WHEN OTHERS THEN
            ROLLBACK;
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := 'ERROR_LINE : ' || SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 480);
            D_EVENT_DATE  := SYSDATE;
            PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER);
            RAISE;
    END;

    /* 종료 LOG (END) : PR_SCP_SYS_LOG_BATCH (7 위치인자) */
    V_SEC := ROUND((SYSDATE - V_START_TIME) * 86400);
    V_EXEC_TIME := LPAD(TO_CHAR(FLOOR(V_SEC / 60)), 2, '0') || ':' || LPAD(TO_CHAR(MOD(V_SEC, 60)), 2, '0');
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '##### END of procedure #####';
    V_DESCRIPTION := '[' || V_EXEC_TIME || ']';
    D_EVENT_DATE  := SYSDATE;
    PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER);
END;

PROCEDURE PR_SCP_MST_NO_USE_3M
/*
 * Program ID   : PR_SCP_MST_NO_USE_3M
 * Description  : MRP NO USE 3M 데이터 이관
 * Program History
 *
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2022.07.27   vadabi3        Create   XIF_MRP_NO_USE_3M_OUT_IF => SCP_MST_NO_USE_3M
 * 2022.07.27   vadabi3        Modify   SCP_MST_NO_USE_3M 전체 삭제 후 새로 입력하는 방식 (=PI 요청)
 * 2025.06.19   김준규         [IT20250117A] NERP 오펀차수별 Mapping Code적용
 * 2026.07.06   ZIONEX         [PJ202650304] NextSCM Migration
 ----------------------------------------------------------------------------------------------------
  EXEC PR_SCP_MST_NO_USE_3M
 */
IS
    V_OPDV_CD               VARCHAR2(30 CHAR);
    V_YRQT                  VARCHAR2(30 CHAR);

    /* ----------------------------------------------------------------------------
       LOG 용 변수 설정
       ---------------------------------------------------------------------------- */
    V_BATCH_USER            VARCHAR2(150 CHAR) := 'scm_batch';
    V_PROGRAM_NAME          VARCHAR2(150 CHAR) := 'PR_SCP_MST_NO_USE_3M';
    V_LOG_TYPE              VARCHAR2(30 CHAR);   /* START/END/ERROR/... */
    N_LOG_COUNT             NUMBER := 0;
    N_LOG_COUNT_INSERT      NUMBER := 0;
    N_LOG_COUNT_UPDATE      NUMBER := 0;
    V_LOG_MESSAGE           VARCHAR2(1000 CHAR);
    V_DESCRIPTION           VARCHAR2(500 CHAR);
    D_EVENT_DATE            DATE;
    V_IFSEQNO               VARCHAR2(30 CHAR);
    N_HISTORY_SEQ           NUMBER;
    N_WORK_CNT              NUMBER;
    N_SUCCESS_CNT           NUMBER := 0;
    N_FAIL_CNT              NUMBER := 0;

    /* ----------------------------------------------------------------------
       2025.06.19 김준규 [IT20250117A] NERP 오펀차수별 Mapping Code적용 Start
       ---------------------------------------------------------------------- */
    V_NERP_ROLLIN_STAGE     VARCHAR2(30 CHAR);
    V_NERP_START_YYYYMMDD   VARCHAR2(8 CHAR);

BEGIN
    /* 2025.06.19 김준규 [IT20250117A] NERP 오펀차수별 Mapping Code적용 */

    BEGIN
        SELECT SEGMENT1
             , SEGMENT2
        INTO   V_NERP_ROLLIN_STAGE
             , V_NERP_START_YYYYMMDD
        FROM   ( SELECT LMD.SEGMENT1
                      , LMD.SEGMENT2
                 FROM   SCM_ADM_LOOKUP_MASTER_DETAIL LMD, SCM_ADM_LOOKUP_MASTER ALM
                 WHERE  ALM.LOOKUP_TYPE = LMD.LOOKUP_TYPE
                 AND    ALM.LOOKUP_TYPE = 'NERP_ROLLIN_STAGE'
                 AND    ALM.VALID_YN = 'Y'
                 AND    LMD.VALID_YN = 'Y' )
        WHERE  ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            NULL;
    END;

    /* ----------------------------------------------------------------------------
       시작 LOG
       ---------------------------------------------------------------------------- */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    N_WORK_CNT    := 0;

    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    /* 트랜잭션 (START) : As-Is BEGIN TRANSACTION PR_SCP_MST_NO_USE_3M_R -> Oracle 암시 트랜잭션 */
    BEGIN

        /* 인터페이스 테이블 처리 ROW UPDATE */
        /* --------------------------------------------------------------------------
           1. XIF_MRP_NO_USE_3M_OUT_IF_R_SN 배치 대상 체크
           -------------------------------------------------------------------------- */
        SELECT COUNT(*)
        INTO   N_LOG_COUNT
        FROM   XIF_MRP_NO_USE_3M_OUT_IF_R_SN
        WHERE  NVL(PROC_FLAG, 'N') = 'N';

        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, 'STEP1', N_LOG_COUNT, '배치 대상 Count ( PROC_FLAG : N => P) ', V_DESCRIPTION, D_EVENT_DATE);

        UPDATE XIF_MRP_NO_USE_3M_OUT_IF_R_SN X
        SET    X.PROC_FLAG = 'P'
             , X.PROC_DATE = SYSDATE
        WHERE  NVL(X.PROC_FLAG, 'N') = 'N'
        /* 2025.06.19 김준규 [IT20250117A] NERP 오펀차수별 Mapping Code적용 Start */
        /* OLD 코드는 반영이 되지 않게 처리 */
        AND    NOT EXISTS ( SELECT 1
                            FROM   NERP_CONV_MASTER NCM
                            WHERE  NCM.CODETYPE = 'PLANT_ID'
                            AND    NCM.OLD_VALUE1 = X.PLANT_CD
                            AND    NCM.ATTRIBUTE5 <= V_NERP_ROLLIN_STAGE );
        /* 2025.06.19 김준규 [IT20250117A] NERP 오펀차수별 Mapping Code적용 End */

        /* --------------------------------------------------------------------------
           2. SCP_MST_NO_USE_3M 전체 데이터 삭제 후 입력
              As-Is TRUNCATE : 단일 트랜잭션 원자성(에러시 ROLLBACK 복원) 보존 위해 DELETE로 변환
           -------------------------------------------------------------------------- */
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, 'STEP2', N_LOG_COUNT, 'TRUNCATE SCP_MST_NO_USE_3M', V_DESCRIPTION, D_EVENT_DATE);

        DELETE FROM SCP_MST_NO_USE_3M;

        /* --------------------------------------------------------------------------
           3-1. INSERT SCP_MST_NO_USE_3M
           -------------------------------------------------------------------------- */
        INSERT INTO SCP_MST_NO_USE_3M
        (
             COMPANY_ID
           , PLANT_ID
           , OPER_NM
           , MDM_GRP_01_NM
           , MDM_GRP_02_NM
           , ITEM_ID
           , ITEM_NM
           , STOCK_QTY
           , CUR_CD
           , STOCK_AMT
           , BASE_UOM
           , PIC_NO
           , PIC_NM
           , ATTRIBUTE1
           , ATTRIBUTE2
           , ATTRIBUTE3
           , ATTRIBUTE4
           , ATTRIBUTE5
           , CREATED_BY
           , CREATION_DATE
           , LAST_UPDATED_BY
           , LAST_UPDATE_DATE
        )
        SELECT NVL(CMPY_ID, '-')   AS CMPY_ID
             , NVL(PLANT_CD, '-')  AS PLANT_CD
             , OPER_NM
             , MDM_GRP_01_NM
             , MDM_GRP_02_NM
             , NVL(ITEM_CD, '-')   AS ITEM_CD
             , ITEM_NM
             , STOCK_QTY
             , CUR_CD
             , STOCK_AMT
             , BASE_UOM
             , NVL(PIC_NO, '-')    AS PIC_NO
             , PIC_NM
             , ATTR_01
             , ATTR_02
             , ATTR_03
             , ATTR_04
             , IF_SEQ
             , V_BATCH_USER
             , SYSDATE
             , V_BATCH_USER
             , SYSDATE
        FROM   XIF_MRP_NO_USE_3M_OUT_IF_R_SN
        WHERE  IF_SEQ IN ( SELECT IF_SEQ
                           FROM   ( SELECT IF_SEQ
                                         , RANK() OVER (PARTITION BY CMPY_ID, PLANT_CD, ITEM_CD ORDER BY IF_SEQ DESC) AS SEQ
                                    FROM   XIF_MRP_NO_USE_3M_OUT_IF_R_SN
                                    WHERE  PROC_FLAG = 'P' ) LIST
                           WHERE  LIST.SEQ = 1 );

        /* ---------------------------------------------------------
           전송 후 결과 처리
           --------------------------------------------------------- */
        /* 인터페이스 테이블 처리 ROW UPDATE */
        UPDATE XIF_MRP_NO_USE_3M_OUT_IF_R_SN
        SET    PROC_FLAG = 'Y'
             , PROC_MSG   = PROC_MSG || '이관대상 ' || TO_CHAR(SYSDATE, 'YYYY-MM-DD HH24:MI:SS".000"')
        WHERE  IF_SEQ IN ( SELECT ATTRIBUTE5 FROM SCP_MST_NO_USE_3M )
        AND    PROC_FLAG = 'P';

        /* 인터페이스 테이블 처리 대상 아닌 경우 ROW UPDATE */
        UPDATE XIF_MRP_NO_USE_3M_OUT_IF_R_SN
        SET    PROC_FLAG = 'S'
             , PROC_MSG   = PROC_MSG || '이관대상 제외 ' || TO_CHAR(SYSDATE, 'YYYY-MM-DD HH24:MI:SS".000"')
        WHERE  PROC_FLAG = 'P';

        /* ---------------------------------------------------------
           결과 처리 LOG
           --------------------------------------------------------- */
        V_LOG_TYPE    := 'HISTORY';
        V_DESCRIPTION := '@n_history_seq' || ':' || TO_CHAR(N_SUCCESS_CNT);
        D_EVENT_DATE  := SYSDATE;

        N_LOG_COUNT   := 1;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, 'Insert Count', N_LOG_COUNT, D_EVENT_DATE);

        SELECT COUNT(*)
        INTO   N_SUCCESS_CNT
        FROM   XIF_MRP_NO_USE_3M_OUT_IF_R_SN
        WHERE  PROC_FLAG = 'Y'
        AND    PROC_DATE > SYSDATE - 0.002;   /* 3분 이내 */
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_SUCCESS_CNT, '이관대상', N_SUCCESS_CNT, D_EVENT_DATE);

        SELECT COUNT(*)
        INTO   N_SUCCESS_CNT
        FROM   XIF_MRP_NO_USE_3M_OUT_IF_R_SN
        WHERE  PROC_FLAG = 'S'
        AND    PROC_DATE > SYSDATE - 0.002;   /* 3분 이내 */
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_SUCCESS_CNT, '이관대상 제외', N_SUCCESS_CNT, D_EVENT_DATE);

        SELECT COUNT(*)
        INTO   N_SUCCESS_CNT
        FROM   SCP_MST_NO_USE_3M;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_SUCCESS_CNT, 'SCP_MST_NO_USE_3M COUNT', N_SUCCESS_CNT, D_EVENT_DATE);

        IF DBMS_TRANSACTION.LOCAL_TRANSACTION_ID IS NOT NULL THEN
            COMMIT;
        END IF;

    EXCEPTION
        WHEN OTHERS THEN
            IF DBMS_TRANSACTION.LOCAL_TRANSACTION_ID IS NOT NULL THEN
                ROLLBACK;
            END IF;

            /* ---------------------------------------------------------
               ERROR LOG
               --------------------------------------------------------- */
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := 'ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
            D_EVENT_DATE  := SYSDATE;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    END;

    /* ---------------------------------------------------------
       종료 LOG
       --------------------------------------------------------- */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

END;

PROCEDURE PR_SCP_MST_OPERATION_LT_HIST
(
    P_DIVISION_ID       IN  VARCHAR2
  , P_SCM_SITE_ID       IN  VARCHAR2
  , P_ITEM_ID           IN  VARCHAR2
  , P_LT_OPERATION      IN  VARCHAR2
  , P_LT_DAY            IN  VARCHAR2
  , P_CREATED_BY        IN  VARCHAR2
  , P_CREATION_DATE     IN  VARCHAR2
  , P_LAST_UPDATED_BY   IN  VARCHAR2
)
IS
/*
 * Program ID   : PR_SCP_MST_OPERATION_LT_HIST
 * Description  : Operation LT History
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2018.10.25   hwyoon         Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 * 2026.09.27   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 */
    N_HISTORY_SEQ       NUMBER(10);

    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME      VARCHAR2(150 CHAR) := 'PR_SCP_MST_OPERATION_LT_HIST';
    V_LOG_TYPE          VARCHAR2(30 CHAR);
    N_LOG_COUNT         NUMBER(10) := 0;
    V_LOG_MESSAGE       VARCHAR2(1000 CHAR);
    V_DESCRIPTION       VARCHAR2(500 CHAR);
    D_EVENT_DATE        DATE;
    V_SQLERRM           VARCHAR2(4000 CHAR);
BEGIN

    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    SELECT SEQ1_SCP_MST_OPERATION_LT_H.NEXTVAL
      INTO N_HISTORY_SEQ
      FROM DUAL;

    INSERT INTO SCP_MST_OPERATION_LT_H
                (
                  HISTORY_SEQ
                , DIVISION_ID
                , SCM_SITE_ID
                , ITEM_ID
                , LT_OPERATION
                , LT_DAY
                , CREATED_BY
                , CREATION_DATE
                , LAST_UPDATED_BY
                , LAST_UPDATE_DATE
                , HISTORY_CREATION_DATE
                )
         VALUES (
                  N_HISTORY_SEQ
                , P_DIVISION_ID
                , P_SCM_SITE_ID
                , P_ITEM_ID
                , P_LT_OPERATION
                , TO_NUMBER(P_LT_DAY)
                , P_CREATED_BY
                /* ★원문은 최초등록일시를 문자로 받아 날짜 칸에 넣는다. 새 행이면 화면이 빈 값을 보내고
                      MSSQL 은 빈 문자를 1900-01-01 로 바꾼다(이력에 그런 행이 1,038건 있다).
                      기준 데이터베이스는 값이 없으면 넣을 수 없어(칸이 값을 요구) 같은 날짜로 맞춘다 */
                , CASE WHEN TRIM(P_CREATION_DATE) IS NULL
                       THEN DATE '1900-01-01'
                       ELSE TO_DATE(SUBSTR(P_CREATION_DATE, 1, 19), 'YYYY-MM-DD HH24:MI:SS')
                  END
                , P_LAST_UPDATED_BY
                , SYSDATE
                , SYSDATE
                );

    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

EXCEPTION
    WHEN OTHERS THEN
        V_SQLERRM := SQLERRM;

        /* AS-IS CATCH 는 이력만 남기고 부르는 쪽으로 오류를 넘기지 않는다 */
        INSERT INTO SCM_SYS_LOG_BATCH
                    (
                      PROGRAM_NAME, LOG_TYPE, LOG_COUNT, LOG_MESSAGE, DESCRIPTION
                    , EVENT_DATE, CREATION_DATE, CREATED_BY, LAST_UPDATE_DATE, LAST_UPDATED_BY
                    )
             VALUES (
                      V_PROGRAM_NAME, 'ERROR', NULL, V_SQLERRM, NULL
                    , SYSDATE, SYSDATE, V_PROGRAM_NAME, SYSDATE, V_PROGRAM_NAME
                    );

END PR_SCP_MST_OPERATION_LT_HIST;

PROCEDURE PR_SCP_MST_PIC_INFO
/*
 * Program ID   : PR_SCP_MST_PIC_INFO
 * Description  : MRP PIC INFO 데이터 이관
 * Program History
 *
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2022.07.27   vadabi3        Create   XIF_MRP_PIC_INFO_OUT_IF_R => SCP_MST_PIC_INFO
 * 2022.07.27   vadabi3        Modify   SCP_MST_PIC_INFO 전체 삭제 후 새로 입력하는 방식 (=PI 요청)
 * 2025.06.19   김준규         [IT20250117A] NERP 오펀차수별 Mapping Code적용
 * 2026.07.06   ZIONEX         [PJ202650304] NextSCM Migration
 ----------------------------------------------------------------------------------------------------
 EXEC PR_SCP_MST_PIC_INFO
 */
AS

    /* LOG 용 변수 설정 */
    V_BATCH_USER          VARCHAR2(150 CHAR) := 'scm_batch';
    V_PROGRAM_NAME        VARCHAR2(150 CHAR) := 'PR_SCP_MST_PIC_INFO';
    V_LOG_TYPE            VARCHAR2(30 CHAR); /* START/END/ERROR/... */
    N_LOG_COUNT           INTEGER := 0;
    V_LOG_MESSAGE         VARCHAR2(1000 CHAR);
    V_DESCRIPTION         VARCHAR2(500 CHAR);
    D_EVENT_DATE          DATE;
    V_IFSEQNO             VARCHAR2(30 CHAR);
    N_SUCCESS_CNT         NUMBER;
    N_FAIL_CNT            NUMBER;

    /* 2025.06.19 김준규 [IT20250117A] NERP 오펀차수별 Mapping Code적용 Start */
    V_NERP_ROLLIN_STAGE   VARCHAR2(30 CHAR);
    V_NERP_START_YYYYMMDD VARCHAR2(8 CHAR);

BEGIN

    N_SUCCESS_CNT  := 0 ;
    N_FAIL_CNT     := 0 ;

    /* 2025.06.19 김준규 [IT20250117A] NERP 오펀차수별 Mapping Code적용 Start */

    BEGIN
        SELECT SEGMENT1
             , SEGMENT2
          INTO V_NERP_ROLLIN_STAGE
             , V_NERP_START_YYYYMMDD
          FROM (SELECT A.SEGMENT1
                     , A.SEGMENT2
                  FROM SCM_ADM_LOOKUP_MASTER_DETAIL A
                     , SCM_ADM_LOOKUP_MASTER        B
                 WHERE B.LOOKUP_TYPE = A.LOOKUP_TYPE
                   AND B.LOOKUP_TYPE = 'NERP_ROLLIN_STAGE'
                   AND B.VALID_YN = 'Y'
                   AND A.VALID_YN = 'Y')
         WHERE ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            V_NERP_ROLLIN_STAGE   := NULL;
            V_NERP_START_YYYYMMDD := NULL;
    END;
    /* 2025.06.19 김준규 [IT20250117A] NERP 오펀차수별 Mapping Code적용 End */

    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := NULL;
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);


    BEGIN
        /* 1. XIF_MRP_PIC_INFO_OUT_IF_R_SN 배치 대상 count */
        SELECT COUNT(*)
          INTO N_LOG_COUNT
          FROM XIF_MRP_PIC_INFO_OUT_IF_R_SN
         WHERE NVL(PROC_FLAG, 'N') = 'N';
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, 'STEP1', N_LOG_COUNT, '배치 대상 Count ( PROC_FLAG : N => P) ', V_DESCRIPTION, D_EVENT_DATE);

        UPDATE XIF_MRP_PIC_INFO_OUT_IF_R_SN A
           SET PROC_FLAG = 'P'
             , PROC_DATE = SYSDATE
         WHERE NVL(PROC_FLAG, 'N') = 'N'
           /* 2025.06.19 김준규 [IT20250117A] NERP 오펀차수별 Mapping Code적용 Start */
           /* OLD 코드는 반영이 되지 않게 처리 */
           AND NOT EXISTS (SELECT 1
                             FROM NERP_CONV_MASTER B
                            WHERE B.CODETYPE = 'PLANT_ID'
                              AND B.OLD_VALUE1 = A.PLANT_CD
                              AND B.ATTRIBUTE5 <= V_NERP_ROLLIN_STAGE);
        /* 2025.06.19 김준규 [IT20250117A] NERP 오펀차수별 Mapping Code적용 End */

        /* 2. TRUNCATE SCP_MST_PIC_INFO (전체 데이터 삭제 후 입력) */
        /*    배치 대상 없을 시 기존 데이터 유지 */
        IF (N_LOG_COUNT < 1) THEN
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, 'BATCH SKIP', N_LOG_COUNT, 'NO BATCH DATA', V_DESCRIPTION, D_EVENT_DATE);
            RETURN;
        END IF;

        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, 'STEP2', N_LOG_COUNT, 'TRUNCATE SCP_MST_PIC_INFO', V_DESCRIPTION, D_EVENT_DATE);
        EXECUTE IMMEDIATE 'TRUNCATE TABLE SCP_MST_PIC_INFO';

        /* 3-1. INSERT SCP_MST_PIC_INFO */
        INSERT
          INTO SCP_MST_PIC_INFO
             ( PLANT_ID
             , ITEM_ID
             , PIC_NO
             , PIC_NM
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE )
        SELECT PLANT_CD
             , ITEM_CD
             , PIC_NO
             , PIC_NM
             , ATTR_01
             , ATTR_02
             , ATTR_03
             , ATTR_04
             , IF_SEQ        AS ATTRIBUTE5
             , V_BATCH_USER  AS CREATE_USER
             , SYSDATE       AS CREATE_DATE
             , V_BATCH_USER  AS UPDATE_USER
             , SYSDATE       AS UPDATE_DATE
          FROM XIF_MRP_PIC_INFO_OUT_IF_R_SN
         WHERE IF_SEQ IN (SELECT IF_SEQ
                            FROM (SELECT IF_SEQ
                                       , RANK() OVER(PARTITION BY PLANT_CD, ITEM_CD, PIC_NO ORDER BY IF_SEQ DESC) AS SEQ
                                    FROM XIF_MRP_PIC_INFO_OUT_IF_R_SN
                                   WHERE PROC_FLAG = 'P') SA
                           WHERE SA.SEQ = 1);

        /* 3-2. 처리 한 row 마킹 */
        UPDATE XIF_MRP_PIC_INFO_OUT_IF_R_SN
           SET PROC_FLAG = 'Y'
             , PROC_MSG  = PROC_MSG || '이관대상 ' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3')
             , PROC_DATE = SYSDATE
         WHERE IF_SEQ IN (SELECT ATTRIBUTE5
                            FROM SCP_MST_PIC_INFO)
           AND PROC_FLAG = 'P';

        UPDATE XIF_MRP_PIC_INFO_OUT_IF_R_SN
           SET PROC_FLAG = 'S'
             , PROC_MSG  = PROC_MSG || '이관대상 제외 ' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3')
             , PROC_DATE = SYSDATE
         WHERE PROC_FLAG = 'P';

        /* History LOG */
        V_LOG_TYPE    := 'HISTORY';
        V_DESCRIPTION := '@n_history_seq' || ':' || TO_CHAR(N_SUCCESS_CNT);
        D_EVENT_DATE  := SYSDATE;

        N_LOG_COUNT   := 1;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, 'Insert Count', TO_CHAR(N_LOG_COUNT), D_EVENT_DATE);

        SELECT COUNT(*)
          INTO N_SUCCESS_CNT
          FROM XIF_MRP_PIC_INFO_OUT_IF_R_SN
         WHERE PROC_FLAG = 'Y'
           AND PROC_DATE > SYSDATE - 0.002;  /* 3분 이내 */
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_SUCCESS_CNT, '이관대상', TO_CHAR(N_SUCCESS_CNT), D_EVENT_DATE);

        SELECT COUNT(*)
          INTO N_SUCCESS_CNT
          FROM XIF_MRP_PIC_INFO_OUT_IF_R_SN
         WHERE PROC_FLAG = 'S'
           AND PROC_DATE > SYSDATE - 0.002;  /* 3분 이내 */
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_SUCCESS_CNT, '이관대상 제외', TO_CHAR(N_SUCCESS_CNT), D_EVENT_DATE);

        SELECT COUNT(*)
          INTO N_SUCCESS_CNT
          FROM SCP_MST_PIC_INFO;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_SUCCESS_CNT, 'SCP_MST_PIC_INFO COUNT', TO_CHAR(N_SUCCESS_CNT), D_EVENT_DATE);


        IF DBMS_TRANSACTION.LOCAL_TRANSACTION_ID IS NOT NULL THEN
            COMMIT;
        END IF;


    EXCEPTION
        WHEN OTHERS THEN
            IF DBMS_TRANSACTION.LOCAL_TRANSACTION_ID IS NOT NULL THEN
                ROLLBACK;
            END IF;
            /* Error LOG */
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := SUBSTR('ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 500);
            D_EVENT_DATE  := SYSDATE;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_FAIL_CNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    END;

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := NULL;
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

END;

PROCEDURE PR_SCP_OPMZ_PLAN_CTRL_ACTV_M
(
     P_PLAN_START_YYYYMMDD  IN  VARCHAR2 DEFAULT NULL
    ,P_DIVISION_ID          IN  VARCHAR2 DEFAULT NULL
    ,P_OPMZ_PRS_ID          IN  VARCHAR2 DEFAULT NULL
    ,P_OPMZ_PLAN_GR_ID      IN  VARCHAR2 DEFAULT NULL
)
/*
 * Program ID   : PR_SCP_OPMZ_PLAN_CTRL_ACTV_M
 * Description  : 매주초 Plan Control 대상 Activity 데이터를 일괄 생성한다.
 *
 *				 - Source : SCP_OPMZ_PLAN_GR_ACTV_M
 *				 - Target : SCP_OPMZ_PLAN_CTRL_ACTV_M
 *
 * Program History
 *===================================================================================================
 *   Date      In Charge	Description
 *===================================================================================================
 * 2025.04.25	hrkim		PJ2024A332R 독립적 Planning 체계 및 Master Validation UI 구축 - Initial Release
 *
 * 2026.08.03	ZIONEX		[PJ202650304] NextSCM Migration
 */
IS


    V_PLAN_START_YYYYMMDD   VARCHAR2(8 CHAR)    := P_PLAN_START_YYYYMMDD;
    V_DIVISION_ID           VARCHAR2(50 CHAR)   := P_DIVISION_ID;
    V_OPMZ_PRS_ID           VARCHAR2(50 CHAR)   := P_OPMZ_PRS_ID;
    V_OPMZ_PLAN_GR_ID       VARCHAR2(50 CHAR)   := P_OPMZ_PLAN_GR_ID;

    /* 실행시간 확인용 */
    V_START_TIME    DATE                := SYSDATE;
    V_EXEC_TIME     VARCHAR2(10 CHAR)   := '';          /* '[00:00]'; */

    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME  VARCHAR2(150 CHAR)  := 'PR_SCP_OPMZ_PLAN_CTRL_ACTV_M'; /* Proc별 이름 설정 */
    V_LOG_TYPE      VARCHAR2(30 CHAR); /* START/END/ERROR/... */
    N_LOG_COUNT     INTEGER := 0;
    V_LOG_MESSAGE   VARCHAR2(1000 CHAR);
    V_DESCRIPTION   VARCHAR2(500 CHAR);
    D_EVENT_DATE    DATE;
    V_BATCH_USER    VARCHAR2(150 CHAR)  := 'scm_batch';

BEGIN

/* procedure body -- start */
/*  원본 세션 옵션(H-13) : SET TRANSACTION ISOLATION LEVEL READ COMMITTED;  /  SET NOCOUNT ON; */


    BEGIN
      BEGIN

        /* 시작 LOG  (START) */
        V_LOG_TYPE    := 'START';
        V_LOG_MESSAGE := '##### Start of procedure #####';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER);
        V_LOG_MESSAGE := NULL;

    /* ------- Begin Tran : ======================================================================================= */
    /*  BEGIN TRAN   --- transaction 시작 */

        /* ---------------------------------------------------------------------------------------------------------- */
        /* print convert(varchar(30), getdate(), 121) : style 121 = 'yyyy-mm-dd hh:mi:ss.mmm'(24시간·밀리초) */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || '기 등록 데이터 삭제 - SCP_OPMZ_PLAN_CTRL_ACTV_RUN_M ');
        /* ---------------------------------------------------------------------------------------------------------- */

        DELETE /* SELECT * */
          FROM SCP_OPMZ_PLAN_CTRL_ACTV_RUN_M A   /* WITH(NOLOCK) 제거(Oracle 읽기일관성) -- PLAN_START_YYYYMMDD, OPMZ_PRS_CD, OPMZ_PLAN_GR_ID, OPMZ_ACTV_CD */
         WHERE 1 = 1
           AND EXISTS (SELECT 1
                         FROM SCP_OPMZ_PLAN_GR_M B   /* WITH(NOLOCK) 제거 -- OPMZ_PLAN_GR_ID */
                        WHERE B.OPMZ_PLAN_GR_ID = A.OPMZ_PLAN_GR_ID
                          AND B.DIVISION_ID     = CASE WHEN NVL(V_DIVISION_ID, 'Z') = 'Z' THEN B.DIVISION_ID ELSE V_DIVISION_ID END)
           AND A.PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
           AND A.OPMZ_PRS_CD         = CASE WHEN NVL(V_OPMZ_PRS_ID, 'Z') = 'Z'     THEN A.OPMZ_PRS_CD     ELSE V_OPMZ_PRS_ID     END
           AND A.OPMZ_PLAN_GR_ID     = CASE WHEN NVL(V_OPMZ_PLAN_GR_ID, 'Z') = 'Z' THEN A.OPMZ_PLAN_GR_ID ELSE V_OPMZ_PLAN_GR_ID END;


        /* ---------------------------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || 'Activity 수행 데이터 삭제 - SCP_OPMZ_PLAN_CTRL_ACTV_M ');
        /* ---------------------------------------------------------------------------------------------------------- */
        /* 원본 : DELETE AD FROM SCP_OPMZ_PLAN_CTRL_ACTV_M AD INNER JOIN SCP_OPMZ_PLAN_GR_M PG ON PG.OPMZ_PLAN_GR_ID = AD.OPMZ_PLAN_GR_ID */
        DELETE /* SELECT * */
          FROM SCP_OPMZ_PLAN_CTRL_ACTV_M A   /* WITH(NOLOCK) 제거 -- PLAN_START_YYYYMMDD, OPMZ_PRS_CD, OPMZ_PLAN_GR_ID, OPMZ_ACTV_CD, OPMZ_PLAN_ID */
         WHERE 1 = 1
           AND EXISTS (SELECT 1
                         FROM SCP_OPMZ_PLAN_GR_M B   /* WITH(NOLOCK) 제거 -- OPMZ_PLAN_GR_ID */
                        WHERE B.OPMZ_PLAN_GR_ID = A.OPMZ_PLAN_GR_ID
                          AND B.DIVISION_ID     = CASE WHEN NVL(V_DIVISION_ID, 'Z') = 'Z' THEN B.DIVISION_ID ELSE V_DIVISION_ID END)
           AND A.PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
           AND A.OPMZ_PRS_CD         = CASE WHEN NVL(V_OPMZ_PRS_ID, 'Z') = 'Z'     THEN A.OPMZ_PRS_CD     ELSE V_OPMZ_PRS_ID     END
           AND A.OPMZ_PLAN_GR_ID     = CASE WHEN NVL(V_OPMZ_PLAN_GR_ID, 'Z') = 'Z' THEN A.OPMZ_PLAN_GR_ID ELSE V_OPMZ_PLAN_GR_ID END;


        /* ---------------------------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || '최적화 활동 데이터 생성 대상 추출 ');
        /* ---------------------------------------------------------------------------------------------------------- */

        INSERT
          INTO SCP_OPMZ_PLAN_CTRL_ACTV_M
             ( PLAN_START_YYYYMMDD
             , OPMZ_PRS_CD
             , OPMZ_PLAN_GR_ID
             , OPMZ_ACTV_CD
             , OPMZ_ACTV_SEQ
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE )
        SELECT V_PLAN_START_YYYYMMDD AS PLAN_START_YYYYMMDD
             , A.OPMZ_PRS_CD
             , A.OPMZ_PLAN_GR_ID
             , A.OPMZ_ACTV_CD
             , A.OPMZ_ACTV_SEQ
             , V_BATCH_USER AS CREATED_BY
             , SYSDATE AS CREATION_DATE
             , V_BATCH_USER AS LAST_UPDATED_BY
             , SYSDATE AS LAST_UPDATE_DATE
          FROM SCP_OPMZ_PLAN_GR_ACTV_M A         /* WITH(NOLOCK) 제거 -- OPMZ_PRS_CD, OPMZ_PLAN_GR_ID, OPMZ_ACTV_CD */
             , SCP_OPMZ_PLAN_GR_M B              /* WITH(NOLOCK) 제거 -- OPMZ_PLAN_GR_ID */
         WHERE 1 = 1
           AND B.OPMZ_PLAN_GR_ID = A.OPMZ_PLAN_GR_ID
           AND A.VALID_YN        = 'Y'
           AND A.OPMZ_PRS_CD     = CASE WHEN NVL(V_OPMZ_PRS_ID, 'Z') = 'Z'     THEN A.OPMZ_PRS_CD     ELSE V_OPMZ_PRS_ID     END
           AND A.OPMZ_PLAN_GR_ID = CASE WHEN NVL(V_OPMZ_PLAN_GR_ID, 'Z') = 'Z' THEN A.OPMZ_PLAN_GR_ID ELSE V_OPMZ_PLAN_GR_ID END
           AND B.DIVISION_ID     = CASE WHEN NVL(V_DIVISION_ID, 'Z') = 'Z'     THEN B.DIVISION_ID     ELSE V_DIVISION_ID     END;

      COMMIT ;  /* --- transaction 종료   (원본 COMMIT TRAN) */
    /* ------- End Tran : ========================================================================================================== */

        /* ----------------------------------------- */
        /* ---- 임시테이블 정리 */
        /* --------------------------------------------- */


      END;


    EXCEPTION
      WHEN OTHERS THEN

        IF DBMS_TRANSACTION.LOCAL_TRANSACTION_ID IS NOT NULL THEN
            ROLLBACK;
        END IF;

        /* ERROR LOG */
        V_LOG_TYPE    := 'ERROR';
        V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);

        V_DESCRIPTION := SUBSTR('ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 500);
        D_EVENT_DATE  := SYSDATE;
        PR_SCP_SYS_LOG_BATCH(P_PROGRAM_NAME  => V_PROGRAM_NAME
                            ,P_LOG_TYPE      => V_LOG_TYPE
                            ,P_LOG_COUNT     => N_LOG_COUNT
                            ,P_LOG_MESSAGE   => V_LOG_MESSAGE
                            ,P_DESCRIPTION   => V_DESCRIPTION
                            ,P_EVENT_DATE    => D_EVENT_DATE
                            ,P_USER_ID       => V_BATCH_USER
                            );
        DBMS_OUTPUT.PUT_LINE(V_LOG_MESSAGE      || ' : ' || V_DESCRIPTION);
        RETURN;


    END;


    V_EXEC_TIME := CASE WHEN LENGTH(TO_CHAR(TRUNC(ROUND((SYSDATE - V_START_TIME) * 86400) / 60))) > 2 THEN NULL
                        ELSE LPAD(TO_CHAR(TRUNC(ROUND((SYSDATE - V_START_TIME) * 86400) / 60)), 2, '0') || ':' ||
                             LPAD(TO_CHAR(MOD(ROUND((SYSDATE - V_START_TIME) * 86400), 60)), 2, '0')
                   END;

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '##### END of procedure #####';

    V_DESCRIPTION := CASE WHEN V_EXEC_TIME IS NULL THEN NULL ELSE '[' || V_EXEC_TIME || ']' END;
    D_EVENT_DATE  := SYSDATE;
    PR_SCP_SYS_LOG_BATCH(P_PROGRAM_NAME  => V_PROGRAM_NAME
                        ,P_LOG_TYPE      => V_LOG_TYPE
                        ,P_LOG_COUNT     => N_LOG_COUNT
                        ,P_LOG_MESSAGE   => V_LOG_MESSAGE
                        ,P_DESCRIPTION   => V_DESCRIPTION
                        ,P_EVENT_DATE    => D_EVENT_DATE
                        ,P_USER_ID       => V_BATCH_USER
                        );
    DBMS_OUTPUT.PUT_LINE(CASE WHEN V_DESCRIPTION IS NULL THEN NULL ELSE V_LOG_MESSAGE      || ' : ' || V_DESCRIPTION END);


END PR_SCP_OPMZ_PLAN_CTRL_ACTV_M;

PROCEDURE         PR_SCP_OPT_ENG_EE_INPUT_BOM

(
     P_PLAN_ID              VARCHAR2
    ,V_DIVISION_ID          VARCHAR2
    ,V_GROUP_ID             VARCHAR2
    ,V_PLAN_START_YYYYMMDD  VARCHAR2
    ,V_PLAN_END_YYYYMMDD    VARCHAR2
)
/* ============================================================
 * Program ID   : PR_SCP_OPT_ENG_EE_INPUT_BOM
 * Description  : SCP OPT ENG 전극(EE) BOM 입력데이터 생성
 *                전극 POST(ELEC_POST) -> COATING BOM 을 SCP_OPT_ENG_BOM 에 적재
 * Program History
 *------------------------------------------------------------
 * Date          In Charge      Description
 *------------------------------------------------------------
 * 2025.02.12    Taehyun        Initial Release
 * 2026.07.06    ZIONEX         [PJ202650304]  NextSCM Migration
 * ============================================================ */
AS
    V_PROGRAM_NAME    VARCHAR2(150 CHAR) := 'PR_SCP_OPT_ENG_EE_INPUT_BOM';
    V_PLAN_ID         VARCHAR2(50 CHAR)  := P_PLAN_ID;
    V_MESSAGE_TEXT    VARCHAR2(1000 CHAR);
    V_DETAIL_DATE     DATE;
    P_PLAN_NAME       VARCHAR2(8 CHAR);
    D_PLAN_NAME       DATE;
    V_CHK_BOM_BATCH   VARCHAR2(100 CHAR);
BEGIN
    PR_SCP_OPT_ENG_LOG_CRE_PROC('I','INPUT',V_PLAN_ID,V_PROGRAM_NAME,'START',NULL,NULL,NULL,V_PLAN_ID);

    BEGIN
        /* ---------------------------------------------------------------------- */
        /* CHECK BOM BATCH */
        /* ---------------------------------------------------------------------- */
        BEGIN
            SELECT LOG_TYPE INTO V_CHK_BOM_BATCH
              FROM ( SELECT LOG_TYPE
                     FROM   SCM_SYS_LOG_BATCH
                     WHERE  1=1
                     AND    PROGRAM_NAME = 'PR_SCP_MST_ALTER_BOM_BATCH'
                     ORDER BY LAST_UPDATE_DATE DESC )
             WHERE ROWNUM = 1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN V_CHK_BOM_BATCH := NULL;
        END;

        IF V_CHK_BOM_BATCH = 'START' THEN
            RAISE_APPLICATION_ERROR(-20002, 'BOM batch program is processing');
        END IF;

        /* ---------------------------------------------------------------------- */
        /* SET Param (당주 월요일 YYYYMMDD) */
        /* ---------------------------------------------------------------------- */
        P_PLAN_NAME := TO_CHAR(FN_NEXT_DAY(SYSDATE,'MON') - 7, 'YYYYMMDD');
        D_PLAN_NAME := TO_DATE(P_PLAN_NAME,'YYYYMMDD');

        /* ---------------------------------------------------------------------- */
        /* #DIVISION 적재 (전극 Division 과 동일 ATTRIBUTE4, EE 제외) */
        /* ---------------------------------------------------------------------- */
        DELETE FROM GT_OPTENG_EE_DIV;
        DELETE FROM GT_OPTENG_EE_BOM;

        INSERT INTO GT_OPTENG_EE_DIV ( DIVISION_ID )
        SELECT DIVISION_ID
        FROM   SCM_MST_DIVISION
        WHERE  VALID_YN = 'Y'
        AND    ATTRIBUTE3 <> 'EE'
        AND    ATTRIBUTE4 = ( SELECT ATTRIBUTE4 FROM SCM_MST_DIVISION WHERE DIVISION_ID = V_DIVISION_ID );

        /* ---------------------------------------------------------------------- */
        /* DATA Insert (@BOM_TEMP 적재) - 바로 INSERT하면 속도가 느림 */
        /* ---------------------------------------------------------------------- */
        INSERT INTO GT_OPTENG_EE_BOM
            ( PLAN_ID, BOM_ID, OP_SEQ, MATERIAL_CLASS_ID, MATERIAL_BUFFER_ID, PRIORITY, CONSUME_QUANTITY
            , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE14, ATTRIBUTE15 )
        SELECT V_PLAN_ID
              , CASE WHEN PLANT_SITE_ID IS NULL OR PARENT_ITEM_ID IS NULL OR STAGE IS NULL THEN NULL
                     ELSE PLANT_SITE_ID ||'::'|| PARENT_ITEM_ID ||'::'|| STAGE END        AS BOM_ID
              , 0                                                                         AS OP_SEQ
              , CHILD_STAGE                                                               AS MATERIAL_CLASS_ID
              , CASE WHEN PLANT_SITE_ID IS NULL OR CHILD_ITEM_ID IS NULL OR CHILD_STAGE IS NULL THEN NULL
                     ELSE PLANT_SITE_ID ||'::'|| CHILD_ITEM_ID ||'::'|| CHILD_STAGE END   AS MATERIAL_BUFFER_ID
              , 1                                                                         AS PRIORITY
              , CHILD_QTY                                                                 AS CONSUME_QUANTITY
              , PLANT_SITE_ID                                                             AS ATTRIBUTE1
              , PARENT_ITEM_ID                                                            AS ATTRIBUTE2
              , STAGE                                                                     AS ATTRIBUTE3
              , CHILD_ITEM_ID                                                             AS ATTRIBUTE14
              , CHILD_STAGE                                                               AS ATTRIBUTE15
        FROM (
            SELECT DISTINCT A.SCM_SITE_ID AS PLANT_SITE_ID
                 , A.ITEM_ID     AS PARENT_ITEM_ID
                 , 'ELEC_POST'   AS STAGE
                 , A.ITEM_ID     AS CHILD_ITEM_ID
                 , 'COATING'     AS CHILD_STAGE
                 , 1             AS CHILD_QTY
            FROM SCP_OPT_ENG_MODEL_LIST_N_SN A
            INNER JOIN ( SELECT DISTINCT FS.DIVISION_ID, FS.PLANT_SITE_ID, FS.ITEM_ID
                         FROM   SCM_MST_SITE_ITEM_PRIORITY FS
                         INNER JOIN GT_OPTENG_EE_DIV D
                             ON  FS.DIVISION_ID = D.DIVISION_ID
                         INNER JOIN SCM_MST_SITE S
                             ON  FS.DIVISION_ID   = S.DIVISION_ID
                             AND FS.PLANT_SITE_ID = S.SCM_SITE_ID
                             AND S.SITE_TYPE      = 'PLANT'
                             AND S.VALID_YN       = 'Y'
                             AND S.OPERATION_GROUP IN ('E')
                         WHERE  FS.TO_YYYYMMDD >= V_PLAN_START_YYYYMMDD
                       ) FS
                ON  1=1
                AND A.SCM_SITE_ID = FS.PLANT_SITE_ID
                AND A.ITEM_ID     = FS.ITEM_ID
            WHERE 1=1
            AND   A.PLAN_ID = V_PLAN_ID
            /* AND   A.STAGE   = 'COATING' */
        ) A;

        /* ---------------------------------------------------------------------- */
        /* 본테이블 INSERT */
        /* ---------------------------------------------------------------------- */
        INSERT INTO SCP_OPT_ENG_BOM_SN
            ( PLAN_ID, BOM_ID, OP_SEQ, MATERIAL_CLASS_ID, MATERIAL_BUFFER_ID, PRIORITY, CONSUME_QUANTITY
            , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE14, ATTRIBUTE15 )
        SELECT PLAN_ID, BOM_ID, OP_SEQ, MATERIAL_CLASS_ID, MATERIAL_BUFFER_ID, PRIORITY, CONSUME_QUANTITY
             , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE14, ATTRIBUTE15
        FROM GT_OPTENG_EE_BOM;

        /* ---------------------------------------------------------------------- */
        /* #DIVISION 정리 */
        /* ---------------------------------------------------------------------- */
        DELETE FROM GT_OPTENG_EE_DIV;

    EXCEPTION
        WHEN OTHERS THEN
            V_MESSAGE_TEXT := SQLERRM;
            PR_SCP_OPT_ENG_LOG_CRE_PROC('I','INPUT',V_PLAN_ID,V_PROGRAM_NAME,'ERROR',NULL,V_MESSAGE_TEXT,NULL,V_PLAN_ID);
            V_DETAIL_DATE  := SYSDATE;
            PR_SCP_OPT_ENG_LOG_DTL_PROC('U',V_PLAN_ID,'STEP01',NULL,NULL,V_DETAIL_DATE,NULL,V_MESSAGE_TEXT,'ERROR');
            RAISE_APPLICATION_ERROR(-20001, V_PROGRAM_NAME);
    END;

    /* ---------------------------------------------------------------------- */
    /* 종료 LOG */
    /* ---------------------------------------------------------------------- */
    IF V_MESSAGE_TEXT IS NULL THEN
        PR_SCP_OPT_ENG_LOG_CRE_PROC('I','INPUT',V_PLAN_ID,V_PROGRAM_NAME,'END',NULL,NULL,NULL,V_PLAN_ID);
        PR_SCP_OPT_ENG_LOG_DTL_PROC('U',V_PLAN_ID,'STEP01',NULL,NULL,NULL,NULL,NULL,NULL);
    END IF;

END PR_SCP_OPT_ENG_EE_INPUT_BOM;

