    /* ------------------------------------------------------------------
     * Procedure 기본조건.
     * SET TRANSACTION ISOLATION LEVEL READ COMMITTED 는
     * ------------------------------------------------------------------ */

    /* Set Prameter */
    V_PROGRAM_NAME        VARCHAR2(150 CHAR) := 'PR_SCP_OPT_ENG_EE_INPUT_MODEL_LIST';
