PROCEDURE PR_SCP_OPT_ENG_EE_INPUT_PLAN_MASTER
(
     P_PLAN_ID              VARCHAR2
    ,V_DIVISION_ID          VARCHAR2
    ,V_GROUP_ID             VARCHAR2
    ,V_PLAN_START_YYYYMMDD  VARCHAR2
    ,V_PLAN_END_YYYYMMDD    VARCHAR2
)
/* ============================================================
 * Program ID   : PR_SCP_OPT_ENG_EE_INPUT_PLAN_MASTER
 * Description  : SCP OPT ENG 전극(EE) 엔진 PLAN MASTER 입력데이터 생성
 * Program History
 *------------------------------------------------------------
 * Date          In Charge      Description
 *------------------------------------------------------------
 * 2025.02.05    Y.S.H          Initial Release
 * 2026.07.06    ZIONEX         [PJ202650304]  NextSCM Migration
 *                               상위 RUN_MAIN 이 호출하는 하위 단계이므로 내부 COMMIT 없음(부모 트랜잭션 소유).)
 * ============================================================ */
AS
    /* Set Prameter */
    V_PROGRAM_NAME       VARCHAR2(150 CHAR) := 'PR_SCP_OPT_ENG_EE_INPUT_PLAN_MASTER';
    V_PLAN_ID            VARCHAR2(50 CHAR)  := P_PLAN_ID;
    V_MESSAGE_TEXT       VARCHAR2(1000 CHAR);
    V_DETAIL_DATE        DATE;

    V_SCP_PLAN_TYPE      VARCHAR2(200 CHAR);
    V_SCP_PLAN_DATE      VARCHAR2(200 CHAR);
    V_SCP_PLAN_SEQ       VARCHAR2(200 CHAR);
BEGIN
    /* Step 3. SCP_OPT_ENG_ENGINE_DATA_CREATE_L_N 생성 */
    PR_SCP_OPT_ENG_LOG_CRE_PROC('I','INPUT',V_PLAN_ID,V_PROGRAM_NAME,'START',NULL,NULL,NULL,V_PLAN_ID);

    /* ------------------------------------------------------------------ */
    /* Transaction (START)                                                 */
    /* BEGIN TRANSACTION SCP_OPT_ENG_RUN_MAIN_PROC;                        */
    /* ------------------------------------------------------------------ */
    BEGIN
        /* 전극 Plan Type 확인 */
        BEGIN
            SELECT A.PLAN_START_YYYYMMDD
                 , A.PLAN_TYPE
                 , A.PLAN_SEQ
              INTO V_SCP_PLAN_DATE
                 , V_SCP_PLAN_TYPE
                 , V_SCP_PLAN_SEQ
              FROM (SELECT DIVISION_ID
                         , PLAN_START_YYYYMMDD
                         , PLAN_TYPE
                         , PLAN_SEQ
                         , PLAN_TYPE_ORDER
                         , CONFIRM_FLAG
                         , ROW_NUMBER() OVER (PARTITION BY DIVISION_ID ORDER BY PLAN_TYPE_ORDER DESC, PLAN_SEQ DESC) AS PLAN_RANK
                      FROM SCP_PLAN_VERSION_V
                     /* 전극 Division 에 해당하는 사업부 확인 */
                     WHERE DIVISION_ID         = V_DIVISION_ID /* 전극 Division 변수 */
                       AND PLAN_START_YYYYMMDD = TO_CHAR(FN_NEXT_DAY(TO_DATE(V_PLAN_START_YYYYMMDD,'YYYYMMDD'),'MON') - 7, 'YYYYMMDD') /* 해당 주 월요일 YYYYMMDD */
                   ) A
             WHERE A.PLAN_RANK = 1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN NULL;
            WHEN TOO_MANY_ROWS THEN NULL;
        END;

        /* ------------------------------------------------------------------ */
        /* INPUT START                                                         */
        /* ------------------------------------------------------------------ */
        /*
        --INSERT INTO SCP_OPT_ENG_PLAN_MASTER_SN (PLAN_ID,PLAN_START_DATE,PLAN_END_DATE,ATTRIBUTE1,ATTRIBUTE2,ATTRIBUTE15)
        --SELECT  @V_PLAN_ID
        --       ,PLAN_START_YYYYMMDD
        --       ,CONVERT(NVARCHAR(8),DATEADD(DAY,1,PLAN_END_YYYYMMDD),112) AS PLAN_END_YYYYMMDD
        --       ,DIVISION_ID
        --       ,PLAN_TYPE_CODE
        --       ,@V_SCP_PLAN_DATE+','+@V_SCP_PLAN_TYPE+','+@V_SCP_PLAN_SEQ -- SCP 전극 기준 Plan 정보
        --FROM    SCP_OPT_ENG_SCP_PLAN_ID_M_SN WITH(NOLOCK)
        --WHERE   1=1
        --AND     PLAN_ID = @V_PLAN_ID


        --INSERT INTO SCP_OPT_ENG_PLAN_MASTER_SN (PLAN_ID,PLAN_START_DATE,PLAN_END_DATE,ATTRIBUTE1,ATTRIBUTE2,ATTRIBUTE15)
        --SELECT  @V_PLAN_ID
        --       ,PLAN_START_YYYYMMDD
        --       ,CONVERT(NVARCHAR(8),DATEADD(DAY,1,PLAN_END_YYYYMMDD),112) AS PLAN_END_YYYYMMDD
        --       ,PM.DIVISION_ID
        --       ,PGM.OPMZ_PLAN_GR_NAME
        --       ,@V_SCP_PLAN_DATE+','+@V_SCP_PLAN_TYPE+','+@V_SCP_PLAN_SEQ
        --FROM     SCP_OPMZ_PLAN_M PM WITH(NOLOCK)
        --    INNER JOIN SCP_OPMZ_PLAN_GR_M PGM WITH(NOLOCK)
        --        ON PM.OPMZ_PLAN_GR_ID = PGM.OPMZ_PLAN_GR_ID
        --WHERE   PM.OPMZ_PLAN_ID = @V_PLAN_ID
        */


        INSERT
          INTO SCP_OPT_ENG_PLAN_MASTER_SN
             ( PLAN_ID
             , PLAN_START_DATE
             , PLAN_END_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE15 )
        SELECT V_PLAN_ID
             , PLAN_START_YYYYMMDD
             , PLAN_END_YYYYMMDD
             , DIVISION_ID
             , PLAN_GROUP_ID
             , V_SCP_PLAN_DATE||','||V_SCP_PLAN_TYPE||','||V_SCP_PLAN_SEQ
          FROM (SELECT PM.DIVISION_ID          AS DIVISION_ID
                     , PGM.OPMZ_PLAN_GR_NAME   AS PLAN_GROUP_ID
                     , PM.PLAN_START_YYYYMMDD  AS PLAN_START_YYYYMMDD
                     , TO_CHAR(TO_DATE(PM.PLAN_END_YYYYMMDD,'YYYYMMDD') + 1,'YYYYMMDD') AS PLAN_END_YYYYMMDD
                  FROM SCP_OPMZ_PLAN_M     PM
                     , SCP_OPMZ_PLAN_GR_M  PGM
                 WHERE PM.OPMZ_PLAN_GR_ID = PGM.OPMZ_PLAN_GR_ID
                   AND PM.OPMZ_PLAN_ID    = V_PLAN_ID
                UNION
                SELECT DIVISION_ID             AS DIVISION_ID
                     , PLAN_TYPE_CODE          AS PLAN_GROUP_ID
                     , PLAN_START_YYYYMMDD     AS PLAN_START_YYYYMMDD
                     , TO_CHAR(TO_DATE(PLAN_END_YYYYMMDD,'YYYYMMDD') + 1,'YYYYMMDD') AS PLAN_END_YYYYMMDD
                  FROM SCP_OPT_ENG_SCP_PLAN_ID_M_SN
                 WHERE 1=1
                   AND PLAN_ID = V_PLAN_ID) A;

        /* ------------------------------------------------------------------ */
        /* INPUT END                                                           */
        /* ------------------------------------------------------------------ */
    EXCEPTION
        /* ERROR LOG */
        /* ROLLBACK TRANSACTION PR_SCP_OPT_ENG_RUN_MAIN_PROC; */
        WHEN OTHERS THEN
            V_MESSAGE_TEXT := SQLERRM;
            PR_SCP_OPT_ENG_LOG_CRE_PROC('I','INPUT',V_PLAN_ID,V_PROGRAM_NAME,'ERROR',NULL,V_MESSAGE_TEXT,NULL,V_PLAN_ID);
            V_DETAIL_DATE  := SYSDATE;
            PR_SCP_OPT_ENG_LOG_DTL_PROC('U',V_PLAN_ID,'STEP01',NULL,NULL,V_DETAIL_DATE,NULL,V_MESSAGE_TEXT,'ERROR');
            RAISE_APPLICATION_ERROR(-20001, V_PROGRAM_NAME);
    END;

    /* 종료 LOG */
    IF V_MESSAGE_TEXT IS NULL THEN
        PR_SCP_OPT_ENG_LOG_CRE_PROC('I','INPUT',V_PLAN_ID,V_PROGRAM_NAME,'END',NULL,NULL,NULL,V_PLAN_ID);
        PR_SCP_OPT_ENG_LOG_DTL_PROC('U',V_PLAN_ID,'STEP01',NULL,NULL,NULL,NULL,NULL,NULL);
    END IF;

END PR_SCP_OPT_ENG_EE_INPUT_PLAN_MASTER;

PROCEDURE PR_SCP_OPT_ENG_EE_INPUT_SAFETY_STOCK
(
     P_PLAN_ID              VARCHAR2
    ,V_DIVISION_ID          VARCHAR2
    ,V_GROUP_ID             VARCHAR2
    ,V_PLAN_START_YYYYMMDD  VARCHAR2
    ,V_PLAN_END_YYYYMMDD    VARCHAR2
)
/* ============================================================
 * Program ID   : PR_SCP_OPT_ENG_EE_INPUT_SAFETY_STOCK
 * Description  : SCP OPT ENG 전극(EE) 엔진 Safety Stock 입력데이터 생성
 *                (max/min cover_day, min/max stock_qty 를 SCP_OPT_ENG_SAFETY_STOCK 에 적재)
 * Program History
 *------------------------------------------------------------
 * Date          In Charge      Description
 *------------------------------------------------------------
 * 2025.02.07    TAEHYUN        Initial Release
 * 2025.05.30    Philsu Park    OPT ENG LOOKUP 반영.
 * 2026.07.06    ZIONEX         [PJ202650304]  NextSCM Migration
 *                                 #DIVISION      -> GT_OPT_ENG_SS_DIVISION   (본 프로시저 전용 신규 GTT)
 *                               상위 RUN_MAIN 이 호출하는 하위 단계이므로 내부 COMMIT 없음(부모 트랜잭션 소유).
 *                               naked SELECT 없음(전부 INSERT..SELECT / SELECT INTO GTT / 스칼라대입) -> OUT 커서 미추가.
 * ============================================================ */
AS
    /* Set Param for Log */
    V_PROGRAM_NAME       VARCHAR2(150 CHAR) := 'PR_SCP_OPT_ENG_EE_INPUT_SAFETY_STOCK';
    V_PLAN_ID            VARCHAR2(50 CHAR)  := P_PLAN_ID;
    V_MESSAGE_TEXT       VARCHAR2(1000 CHAR);
    /* Set Param for Biz */
    V_DETAIL_DATE        DATE;
    V_P_PLAN_NAME        VARCHAR2(8 CHAR);
    V_D_PLAN_NAME        DATE;
    V_DEMAND_CUTOFF_DAY  VARCHAR2(8 CHAR);
    V_DM_MAX_VERSION     VARCHAR2(200 CHAR);
    V_CATHODE_PLAN_ID    VARCHAR2(50 CHAR);
    V_SINGLE_PLAN_TYPE   VARCHAR2(1 CHAR);
    V_PLAN_GROUP_ORG     VARCHAR2(20 CHAR);
BEGIN
    /* ---------------------------------------------------------------------- */
    /* Step 3. SCP_OPT_ENG_ENGINE_DATA_CREATE_L_N 생성 */
    /* ---------------------------------------------------------------------- */
    PR_SCP_OPT_ENG_LOG_CRE_PROC('I','INPUT',V_PLAN_ID,V_PROGRAM_NAME,'START',NULL,NULL,NULL,V_PLAN_ID);

    V_SINGLE_PLAN_TYPE := CASE WHEN SUBSTR(V_GROUP_ID, -2) = '_C' THEN 'C' WHEN SUBSTR(V_GROUP_ID, -2) = '_A' THEN 'A' ELSE '-' END;
    V_PLAN_GROUP_ORG   := CASE WHEN SUBSTR(V_GROUP_ID, -2) IN ('_C', '_A') THEN SUBSTR(V_GROUP_ID, 1, LENGTH(V_GROUP_ID) - 2) ELSE V_GROUP_ID END;

    /* ---------------------------------------------------------------------- */
    /* Transaction (START) */
    /* ---------------------------------------------------------------------- */
    /* BEGIN TRANSACTION SCP_OPT_ENG_RUN_MAIN_PROC; */
    /* ---------------------------------------------------------------------- */
    BEGIN

        DELETE FROM GT_OPT_ENG_SS_DIVISION;

        INSERT INTO GT_OPT_ENG_SS_DIVISION (DIVISION_ID)
        SELECT DIVISION_ID
        FROM   SCM_MST_DIVISION
        WHERE  VALID_YN = 'Y'
        AND    ATTRIBUTE3 <> 'EE'
        AND    ATTRIBUTE4 = (SELECT ATTRIBUTE4 FROM SCM_MST_DIVISION WHERE DIVISION_ID = V_DIVISION_ID);

        /* -------------------------------------------------------- */
        /* 1. 특정 Stage 전 구간 L0 / 0 처리 : COATING, ELEC_POST, BIZ */
        /* 2025.05.13 Philsu Park: max_cover_day L0 생성 제외.(주석처리) */
        /* 2025.05.30 Philsu Park: max_cover_day L0 활성화(주석 제거 - 신성재 책임님 요청) */
        /* 2025.07.10 Philsu Park: COATING은 max_cover_day 제외 (권순지 책임님 요청) */
        /* -------------------------------------------------------- */
        INSERT INTO SCP_OPT_ENG_SAFETY_STOCK_SN
                    (
                     PLAN_ID
                    ,BUFFER_ID
                    ,TYPE
                    ,START_DATE
                    ,END_DATE
                    ,VALUE
                    ,CALENDAR_LEVEL
                    )
        SELECT V_PLAN_ID                                          AS PLAN_ID
              ,BUFFER_ID                                          AS BUFFER_ID
              ,'max_cover_day'                                    AS TYPE
              ,V_PLAN_START_YYYYMMDD                              AS START_DATE
              ,V_PLAN_END_YYYYMMDD                                AS END_DATE
              ,TO_NUMBER('0')                                     AS VALUE
              ,'L0'                                               AS CALENDAR_LEVEL
        FROM   SCP_OPT_ENG_ITEM_SITE_SN
        WHERE  PLAN_ID = V_PLAN_ID
        /* AND   (STAGE IN ('COATING', 'ELEC_POST') */
        AND   (STAGE IN ('ELEC_POST')
            OR STAGE LIKE '%BIZ%'
              )

        /* -------------------------------------------------------- */
        /* 2. Lookup에 Stage 별 등록 확인 후 수정 처리 필요 */
        /* 2025.06.24 Philsu Park: BIZ Stage 도 max cover 반영될 수 있게 ROUTING Join 조건을 Outer로 변경. */
        /* 2025.09.03 Philsu Park: 동일 Start 날짜 중복으로 발생하는 케이스 있어 일단 Group By 처리. */
        /* 2025.11.04 Minyong Lee : Lookup -> UI 전환 (cover_day) */
        /* 2025.11.25 Minyong Lee : */
        /*      - ROUTING JOIN이 있다면 그대로 유지 */
        /*      - ITEM_SITE JOIN이 없다면 INNER JOIN 추가 */
        /*      - Sales Site Incoterms 구분 없이 STAGE 기준 JOIN */
        /*      - ITEM_SITE의 BUFFER_ID 그대로 사용 */
        /* -------------------------------------------------------- */
        UNION ALL
        SELECT V_PLAN_ID                                          AS PLAN_ID
              ,SIS.BUFFER_ID                                      AS BUFFER_ID
              ,'max_cover_day'                                    AS TYPE

              ,CASE WHEN CP.START_DATE <= V_PLAN_START_YYYYMMDD THEN V_PLAN_START_YYYYMMDD
                    ELSE CP.START_DATE
               END                                                AS START_DATE

              ,MAX(CASE WHEN CP.END_DATE >= V_PLAN_END_YYYYMMDD THEN V_PLAN_END_YYYYMMDD
                    ELSE CP.END_DATE
               END)                                               AS END_DATE

              ,MAX(CP.TEMP_VALUE)                                 AS VALUE
              ,'L1'                                               AS CALENDAR_LEVEL
        FROM(
            SELECT CP.SCM_SITE_ID    AS SCM_SITE_ID
                  ,CP.ITEM_ID        AS ITEM_ID
                  ,CP.STAGE          AS STAGE
                  ,'max_cover_day'   AS TYPE
                  ,CP.EFF_START_DATE AS START_DATE
                  ,CP.EFF_END_DATE   AS END_DATE
                  ,CP.VALUE          AS TEMP_VALUE
            FROM(
                /* SELECT LV.SEGMENT2     AS DIVISION */
                /* 	  ,LV.SEGMENT3     AS SCM_PLANT_ID */
                /* 	  ,SMS.PLANT_ID    AS PLANT_ID */
                /* 	  ,LV.SEGMENT4     AS ITEM_ID */
                /* 	  ,LV.SEGMENT5     AS STAGE */
                /* 	  ,LV.ATTRIBUTE1   AS EFF_START_DATE */
                /* 	  ,IIF(LV.ATTRIBUTE2<>'99991231',CONVERT(NVARCHAR(8),DATEADD(DAY,1,LV.ATTRIBUTE2),112),LV.ATTRIBUTE2)   AS EFF_END_DATE */
                /* 	  ,LV.ATTRIBUTE3   AS VALUE */
                /* FROM    SCP_OPMZ_LOOKUP_MASTER_DETAIL LV WITH(NOLOCK) */

                /* INNER JOIN SCM_MST_SITE SMS WITH(NOLOCK) */
                /* ON      1=1 --LV.SEGMENT2 = SMS.DIVISION_ID */
                /* AND     LV.SEGMENT3 = SMS.SCM_SITE_ID */

                /* INNER JOIN #DIVISION D WITH(NOLOCK) */
                /* ON SMS.DIVISION_ID = D.DIVISION_ID */

                /* WHERE   LV.LOOKUP_TYPE = 'SCP_OPT_ENG_CONST_PRECEDE' */
                /* AND     LV.VALID_YN    = 'Y' */
                /* AND     LV.SEGMENT2    = @V_DIVISION_ID */

                SELECT  CV.DIVISION_ID      AS DIVISION
                      , CV.SCM_SITE_ID      AS SCM_SITE_ID
                      , SMS.PLANT_ID        AS PLANT_ID
                      , CV.ITEM_ID          AS ITEM_ID
                      , CV.STAGE            AS STAGE
                      , CV.FROM_YYYYMMDD    AS EFF_START_DATE
                      , CASE WHEN CV.TO_YYYYMMDD <> '99991231' THEN TO_CHAR(TO_DATE(CV.TO_YYYYMMDD,'YYYYMMDD') + 1,'YYYYMMDD') ELSE CV.TO_YYYYMMDD END   AS EFF_END_DATE
                      , CV.TYPE_APPLY_DAY   AS VALUE
                FROM    SCP_OPMZ_PRECEDE_SAFETY_STOCK_DAY CV
                    INNER JOIN SCM_MST_SITE SMS
                        ON  CV.SCM_SITE_ID = SMS.SCM_SITE_ID
                    INNER JOIN GT_OPT_ENG_SS_DIVISION D
                        ON  SMS.DIVISION_ID = D.DIVISION_ID
                    LEFT OUTER JOIN SCP_OPMZ_PLAN_GR_M PG
                        ON  CV.OPMZ_PLAN_GR_ID = PG.OPMZ_PLAN_GR_ID
                    INNER JOIN  (
                                SELECT  DISTINCT ITEM_ID, STAGE
                                FROM    SCP_OPT_ENG_MODEL_LIST_N_SN
                                WHERE   PLAN_ID = V_PLAN_ID
                                ) MDL
                        ON  CV.ITEM_ID = MDL.ITEM_ID
                        AND CV.STAGE   = MDL.STAGE
                WHERE   1=1
                AND     CV.VALUE_TYPE   = 'MAX'
                AND     CV.VALID_YN     = 'Y'
                AND     CV.DIVISION_ID  = V_DIVISION_ID
                AND     CV.TO_YYYYMMDD   >= V_PLAN_START_YYYYMMDD
                AND     CV.FROM_YYYYMMDD < V_PLAN_END_YYYYMMDD
                AND     PG.OPMZ_PLAN_GR_NAME = V_PLAN_GROUP_ORG
                ) CP
            WHERE 1=1
            ) CP
            LEFT JOIN   (
                        SELECT  DISTINCT PLAN_ID,ATTRIBUTE1,ATTRIBUTE2,ATTRIBUTE3
                        FROM    SCP_OPT_ENG_ROUTING_SN
                        WHERE   PLAN_ID = V_PLAN_ID
                        ) RT
                ON  RT.PLAN_ID      = V_PLAN_ID
                AND CP.SCM_SITE_ID  = RT.ATTRIBUTE1
                AND CP.ITEM_ID      = RT.ATTRIBUTE2
                AND CP.STAGE        = RT.ATTRIBUTE3
            INNER JOIN  SCP_OPT_ENG_ITEM_SITE_SN SIS
                ON  SIS.PLAN_ID     = V_PLAN_ID
                AND CP.SCM_SITE_ID  = SIS.SITE_ID
                AND CP.ITEM_ID      = SIS.ITEM_ID
                AND CP.STAGE        = SIS.ATTRIBUTE3
        GROUP BY SIS.BUFFER_ID, CP.SCM_SITE_ID, CP.ITEM_ID, CP.STAGE
                , CASE WHEN CP.START_DATE <= V_PLAN_START_YYYYMMDD THEN V_PLAN_START_YYYYMMDD
                       ELSE CP.START_DATE END
        /* -------------------------------------------------------- */
        /* 3) Min Cover Day : Lookup 그대로 등록 */
        /* 2025.05.13 Philsu Park: Target_Biz의 Buffer_Id 채번룰 및 Lookup Join조건 수정 */
        /* Target_Biz의 BUffer_Id: Site::Item::Stage@Incoterms@Project */
        /* 2025.05.13 Philsu Park: ATT1, 2 조건 수정 */
        /* 2025.11.04 Minyong Lee : Lookup -> UI 전환 (cover_day) */
        /* -------------------------------------------------------- */
        /* UNION ALL */
        /* SELECT	 @V_PLAN_ID										AS PLAN_ID */
        /* 		,LV.SEGMENT3+'::'+LV.SEGMENT4+'::'+LV.SEGMENT5+IIF(SIS.ATTRIBUTE1 IS NULL ,'','@'+SIS.ATTRIBUTE1)+IIF(SIS.ATTRIBUTE2 IS NULL ,'','@'+SIS.ATTRIBUTE2)	AS BUFFER_ID */
        /* 		,'min_cover_day'								AS TYPE */
        /* 	    ,CASE WHEN LV.ATTRIBUTE1 <= @V_PLAN_START_YYYYMMDD THEN @V_PLAN_START_YYYYMMDD */
        /* 	          ELSE LV.ATTRIBUTE1 */
        /* 	     END AS START_DATE */

        /* 	    ,CASE WHEN IIF(LV.ATTRIBUTE2<>'99991231',CONVERT(NVARCHAR(8),DATEADD(DAY,1,LV.ATTRIBUTE2),112),LV.ATTRIBUTE2) >= @V_PLAN_END_YYYYMMDD THEN @V_PLAN_END_YYYYMMDD */
        /* 	          ELSE IIF(LV.ATTRIBUTE2<>'99991231',CONVERT(NVARCHAR(8),DATEADD(DAY,1,LV.ATTRIBUTE2),112),LV.ATTRIBUTE2) */
        /* 	     END AS END_DATE */
        /* 		,LV.ATTRIBUTE3									AS VALUE */
        /* 		,'L1'                                           AS CALENDAR_LEVEL */
        /* FROM SCP_OPMZ_LOOKUP_MASTER_DETAIL LV WITH(NOLOCK) */
        /*    INNER JOIN SCP_OPT_ENG_ITEM_SITE_SN SIS WITH(NOLOCK) */
        /*    	 ON  LV.SEGMENT3 = SIS.SITE_ID */
        /*    	 AND LV.SEGMENT4 = SIS.ITEM_ID */
        /*    	 AND SIS.PLAN_ID = @V_PLAN_ID */
        /*               AND LV.SEGMENT5 = SIS.ATTRIBUTE3 -- Type 기준으로만 Join 처리. */
        /*              --  AND LV.SEGMENT5 = SIS.ATTRIBUTE3 + IIF(SIS.ATTRIBUTE1 IS NULL ,'','@'+SIS.ATTRIBUTE1) */
        /* WHERE   LV.LOOKUP_TYPE	= 'SCP_OPT_ENG_CONST_SAFETY_STOCK' */
        /* AND     LV.VALID_YN		= 'Y' */
        /* AND     LV.SEGMENT2		= @V_DIVISION_ID */
        /*      AND     LV.ATTRIBUTE1   > @V_PLAN_START_YYYYMMDD -- +1일이 되지 않아서 등호 제거 */
        /*      AND     LV.ATTRIBUTE2   < @V_PLAN_END_YYYYMMDD   --END DATE가 하루 추가된 날짜이기 때문에, 등호 제거 */

        UNION ALL
        SELECT	V_PLAN_ID									AS PLAN_ID
              , SIS.BUFFER_ID           	                AS BUFFER_ID
              , 'min_cover_day'								AS TYPE
              , CASE
                    WHEN CV.FROM_YYYYMMDD <= V_PLAN_START_YYYYMMDD THEN V_PLAN_START_YYYYMMDD
                    ELSE CV.FROM_YYYYMMDD
                END AS START_DATE
              , CASE
                    WHEN (CASE WHEN CV.TO_YYYYMMDD <> '99991231' THEN TO_CHAR(TO_DATE(CV.TO_YYYYMMDD,'YYYYMMDD') + 1,'YYYYMMDD') ELSE CV.TO_YYYYMMDD END) >= V_PLAN_END_YYYYMMDD THEN V_PLAN_END_YYYYMMDD
                    ELSE (CASE WHEN CV.TO_YYYYMMDD <> '99991231' THEN TO_CHAR(TO_DATE(CV.TO_YYYYMMDD,'YYYYMMDD') + 1,'YYYYMMDD') ELSE CV.TO_YYYYMMDD END)
                END AS END_DATE
              , CV.TYPE_APPLY_DAY							AS VALUE
              , 'L1'                                        AS CALENDAR_LEVEL
        FROM    SCP_OPMZ_PRECEDE_SAFETY_STOCK_DAY CV
            INNER JOIN  SCP_OPT_ENG_ITEM_SITE_SN SIS
                ON  SIS.PLAN_ID     = V_PLAN_ID
                AND CV.SCM_SITE_ID  = SIS.SITE_ID
                AND CV.ITEM_ID      = SIS.ITEM_ID
                AND CV.STAGE        = SIS.ATTRIBUTE3
            LEFT OUTER JOIN SCP_OPMZ_PLAN_GR_M PG
                ON CV.OPMZ_PLAN_GR_ID = PG.OPMZ_PLAN_GR_ID
            INNER JOIN  (
                        SELECT  DISTINCT ITEM_ID, STAGE
                        FROM    SCP_OPT_ENG_MODEL_LIST_N_SN
                        WHERE   PLAN_ID = V_PLAN_ID
                        ) MDL
                ON  CV.ITEM_ID = MDL.ITEM_ID
                AND CV.STAGE   = MDL.STAGE
        WHERE   1=1
        AND     CV.VALUE_TYPE    = 'MIN'
        AND     CV.VALID_YN		 = 'Y'
        AND     CV.DIVISION_ID	 = V_DIVISION_ID
        AND     CV.TO_YYYYMMDD   >= V_PLAN_START_YYYYMMDD
        AND     CV.FROM_YYYYMMDD < V_PLAN_END_YYYYMMDD
        AND     PG.OPMZ_PLAN_GR_NAME = V_PLAN_GROUP_ORG

        /* -------------------------------------------------------- */
        /* 4) Min Cover Qty : Lookup 그대로 등록 */
        /* 2025.05.09 Philsu Park: Target_Biz의 Buffer_Id 채번룰 및 Lookup Join조건 수정 */
        /* Target_Biz의 BUffer_Id: Site::Item::Stage@Incoterms@Project */
        /* 2025.05.13 Philsu Park: ATT1, 2 조건 수정 */
        /* 2025.05.13 Philsu Park: ATT1, 2 조건 수정(Start ~ End 보다 룩업 등록구간이 큰 경우 계획구간만큼 생성.) */
        /* 2025.11.04 Minyong Lee : Lookup -> UI 전환 (stock_qty) */
        /* 2025.11.25 Minyong Lee : */
        /*      - ROUTING JOIN이 있다면 그대로 유지 */
        /*      - ITEM_SITE JOIN이 없다면 INNER JOIN 추가 */
        /*      - Sales Site Incoterms 구분 없이 STAGE 기준 JOIN */
        /*      - ITEM_SITE의 BUFFER_ID 그대로 사용 */
        /* -------------------------------------------------------- */
        /* UNION ALL */
        /* SELECT	 @V_PLAN_ID										AS PLAN_ID */
        /* 		-- ,LV.SEGMENT3+'::'+LV.SEGMENT4+'::'+LV.SEGMENT5+IIF(SIS.ATTRIBUTE2 IS NULL ,'','@'+SIS.ATTRIBUTE2)	AS BUFFER_ID */
        /*              ,LV.SEGMENT3+'::'+LV.SEGMENT4+'::'+LV.SEGMENT5+IIF(SIS.ATTRIBUTE1 IS NULL ,'','@'+SIS.ATTRIBUTE1)+IIF(SIS.ATTRIBUTE2 IS NULL ,'','@'+SIS.ATTRIBUTE2) AS BUFFER_ID */
        /* 		--,'min_cover_qty'								AS TYPE */
        /* 		,'min_stock_qty'								AS TYPE */
        /* 	    ,CASE WHEN LV.ATTRIBUTE1 <= @V_PLAN_START_YYYYMMDD THEN @V_PLAN_START_YYYYMMDD */
        /* 	          ELSE LV.ATTRIBUTE1 */
        /* 	     END AS START_DATE */

        /* 	    ,CASE WHEN IIF(LV.ATTRIBUTE2<>'99991231',CONVERT(NVARCHAR(8),DATEADD(DAY,1,LV.ATTRIBUTE2),112),LV.ATTRIBUTE2) >= @V_PLAN_END_YYYYMMDD THEN @V_PLAN_END_YYYYMMDD */
        /* 	          ELSE IIF(LV.ATTRIBUTE2<>'99991231',CONVERT(NVARCHAR(8),DATEADD(DAY,1,LV.ATTRIBUTE2),112),LV.ATTRIBUTE2) */
        /* 	     END AS END_DATE */
        /* 		,LV.ATTRIBUTE3									AS VALUE */
        /* 		,'L1'                                           AS CALENDAR_LEVEL */
        /* FROM SCP_OPMZ_LOOKUP_MASTER_DETAIL LV WITH(NOLOCK) */
        /*    LEFT OUTER JOIN SCP_OPT_ENG_ITEM_SITE_SN SIS WITH(NOLOCK) */
        /*    	 ON  LV.SEGMENT3 = SIS.SITE_ID */
        /*    	 AND LV.SEGMENT4 = SIS.ITEM_ID */
        /*    	 AND SIS.PLAN_ID = @V_PLAN_ID */
        /*              --  AND LV.SEGMENT5 = SIS.ATTRIBUTE3 + IIF(SIS.ATTRIBUTE1 IS NULL ,'','@'+SIS.ATTRIBUTE1) */
        /*               AND LV.SEGMENT5 = SIS.ATTRIBUTE3-- + IIF(SIS.ATTRIBUTE1 IS NULL ,'','@'+SIS.ATTRIBUTE1)  -- Biz 기준으로만 Join 해야 정상 Join됨. */
        /* WHERE   LV.LOOKUP_TYPE	= 'SCP_OPT_ENG_CONST_SAFETY_STOCK_QTY' */
        /* AND     LV.VALID_YN		= 'Y' */
        /* AND     LV.SEGMENT2		= @V_DIVISION_ID */
        /*      AND     GREATEST(LV.ATTRIBUTE1, @V_PLAN_START_YYYYMMDD) >= @V_PLAN_START_YYYYMMDD */
        /*      AND     LEAST(LV.ATTRIBUTE2, @V_PLAN_END_YYYYMMDD)      <= @V_PLAN_END_YYYYMMDD */
        /* AND     LV.ATTRIBUTE1 > @V_PLAN_START_YYYYMMDD -- +1일이 되지 않아서 등호 제거 */
        /* AND     LV.ATTRIBUTE2 < @V_PLAN_END_YYYYMMDD   --END DATE가 하루 추가된 날짜이기 때문에, 등호 제거 */
        /* AND     LV.ATTRIBUTE4 = @V_GROUP_ID */
        /* ; */

        UNION ALL
        SELECT  V_PLAN_ID										AS PLAN_ID
              , SIS.BUFFER_ID                                   AS BUFFER_ID
              , 'min_stock_qty'								    AS TYPE
              , CASE
                    WHEN SQ.FROM_YYYYMMDD <= V_PLAN_START_YYYYMMDD THEN V_PLAN_START_YYYYMMDD
                    ELSE SQ.FROM_YYYYMMDD
                END AS START_DATE
              , CASE
                    WHEN (CASE WHEN SQ.TO_YYYYMMDD <> '99991231' THEN TO_CHAR(TO_DATE(SQ.TO_YYYYMMDD,'YYYYMMDD') + 1,'YYYYMMDD') ELSE SQ.TO_YYYYMMDD END) >= V_PLAN_END_YYYYMMDD THEN V_PLAN_END_YYYYMMDD
         	        ELSE (CASE WHEN SQ.TO_YYYYMMDD <> '99991231' THEN TO_CHAR(TO_DATE(SQ.TO_YYYYMMDD,'YYYYMMDD') + 1,'YYYYMMDD') ELSE SQ.TO_YYYYMMDD END)
       	        END AS END_DATE
              , SQ.APL_QTY									    AS VALUE
              , 'L1'                                            AS CALENDAR_LEVEL
        FROM    SCP_OPMZ_SAFETY_STOCK SQ
            INNER JOIN  SCP_OPT_ENG_ITEM_SITE_SN SIS
                ON  SIS.PLAN_ID     = V_PLAN_ID
                AND SQ.SCM_SITE_ID  = SIS.SITE_ID
                AND SQ.ITEM_ID      = SIS.ITEM_ID
                AND SQ.STAGE        = SIS.ATTRIBUTE3
            LEFT OUTER JOIN SCP_OPMZ_PLAN_GR_M PG
                ON SQ.OPMZ_PLAN_GR_ID = PG.OPMZ_PLAN_GR_ID
            INNER JOIN  (
                        SELECT  DISTINCT ITEM_ID, STAGE
                        FROM    SCP_OPT_ENG_MODEL_LIST_N_SN
                        WHERE   PLAN_ID = V_PLAN_ID
                        ) MDL
                ON  SQ.ITEM_ID = MDL.ITEM_ID
                AND SQ.STAGE   = MDL.STAGE
        WHERE   1=1
        AND     SQ.VALUE_TYPE       = 'MIN'
        AND     SQ.VALID_YN		    = 'Y'
        AND     SQ.DIVISION_ID	    = V_DIVISION_ID
        AND     SQ.TO_YYYYMMDD      >= V_PLAN_START_YYYYMMDD
        AND     SQ.FROM_YYYYMMDD    < V_PLAN_END_YYYYMMDD
        AND     PG.OPMZ_PLAN_GR_NAME = V_PLAN_GROUP_ORG;

        /* ------------------------------------------------------------------------------------------------------------------ */
        /* 2025.05.09 Philsu Park */
        /* 5) Min Stock Qty : EE, 음극인 경우, 양극 Plan Output의 매주 월요일 COATING BOH를 min_stock_qty 로 활용. */
        /* 2025.07.09 Philsu Park: 음극 소요량 산출 시 수율비중 추가 반영. */
        /* ------------------------------------------------------------------------------------------------------------------ */
        /* START 2025.10.23 jongykim2: Capa - Yield(Elec) */
        DELETE FROM GT_OPT_ENG_SS_MST_YIELD;

        INSERT INTO GT_OPT_ENG_SS_MST_YIELD (DIVISION_ID, SCM_SITE_ID, ITEM_ID, YYYYMM, YIELD, VALID_YN)
        WITH DIVISION_T AS (
            SELECT 'EE' ELEC_DIVISION_ID
                 , T.DIVISION_ID
            FROM   GT_OPT_ENG_SS_DIVISION T
        )
        SELECT YE.DIVISION_ID
             , MS.SCM_SITE_ID
             , YE.ITEM_ID
             , YE.YYYYMM
             , CASE WHEN MS.OPERATION_GROUP = 'A' THEN YE.ASSY
                    WHEN MS.OPERATION_GROUP = 'E' THEN YE.ELEC_POST
               END AS YIELD
             , YE.VALID_YN
        FROM   SCP_OPMZ_YLD_ELEC YE
        INNER JOIN DIVISION_T D
        ON     D.ELEC_DIVISION_ID = YE.DIVISION_ID
        INNER JOIN SCM_MST_SITE MS
        ON      MS.DIVISION_ID = D.DIVISION_ID
        AND     MS.PLANT_ID = YE.PLANT_ID
        WHERE 	MS.SITE_TYPE 		= 'PLANT'
        AND 	MS.OPERATION_GROUP  IN ('A', 'E')
        AND 	MS.VALID_YN 		= 'Y'
        AND     YE.DIVISION_ID      = V_DIVISION_ID;
        /* END 2025.10.23 jongykim2: Capa - Yield(Elec) */
        IF (V_DIVISION_ID = 'EE' AND SUBSTR(V_PLAN_ID, -2) = '_A') THEN

                V_CATHODE_PLAN_ID := SUBSTR(V_PLAN_ID, 1, LENGTH(V_PLAN_ID) - 2) || '_C';

                INSERT INTO SCP_OPT_ENG_SAFETY_STOCK_SN
                    (
                        PLAN_ID
                        , BUFFER_ID
                        , TYPE
                        , START_DATE
                        , END_DATE
                        , VALUE
                        , CALENDAR_LEVEL
                    )
                WITH YIELD_MST AS (
                        /* START 2025.10.23 jongykim2: Capa - Yield(Elec) */
                        /* ----------------------------------------------------- */
                        /* 요청사항: 전극 수율 관리 룩업을 UI Table로 교체 */
                        /* Lookup Table: SCP_OPMZ_LOOKUP_MASTER_DETAIL */
                        /* Lookup Type: SCP_OPT_MASTER_YIELD */
                        /* Table: SCP_OPMZ_YLD_ELEC */
                        /* ------------------------------------------------------ */
                        SELECT    LU.ITEM_ID AS ITEM_ID
                                , LU.YYYYMM AS MONTH
                                , MAX(CASE WHEN SUBSTR(LU.SCM_SITE_ID, -1) = 'E' THEN CAST(LU.YIELD AS NUMBER(20, 4)) ELSE NULL END) AS POST_YIELD
                                , MAX(CASE WHEN SUBSTR(LU.SCM_SITE_ID, -1) = 'A' THEN CAST(LU.YIELD AS NUMBER(20, 4)) ELSE NULL END) AS ASSY_YIELD
                        FROM   GT_OPT_ENG_SS_MST_YIELD LU
                        WHERE  1 = 1
                        AND    LU.VALID_YN    = 'Y'
                        AND    (CASE WHEN VALIDATE_CONVERSION(LU.YIELD AS NUMBER) = 1 THEN TO_NUMBER(LU.YIELD) END) > 0
                        AND    LU.DIVISION_ID    = V_DIVISION_ID
                        AND    LU.YYYYMM BETWEEN SUBSTR(V_PLAN_START_YYYYMMDD, 1, 6) AND SUBSTR(V_PLAN_END_YYYYMMDD, 1, 6)
                        GROUP BY LU.ITEM_ID, LU.YYYYMM
                        /* BLOCKED 2025.10.23 jongykim2: Capa - Yield(Elec)
						SELECT    LU.SEGMENT4 AS ITEM_ID
                                , LU.SEGMENT5 AS MONTH
                                , MAX(IIF(RIGHT(LU.SEGMENT2, 1) = 'E', CONVERT(NUMERIC(20, 4), ATTRIBUTE1), NULL)) AS POST_YIELD
                                , MAX(IIF(RIGHT(LU.SEGMENT2, 1) = 'A', CONVERT(NUMERIC(20, 4), ATTRIBUTE1), NULL)) AS ASSY_YIELD
                        FROM   SCP_OPMZ_LOOKUP_MASTER_DETAIL LU WITH(NOLOCK)
                        WHERE  LU.LOOKUP_TYPE = 'SCP_OPT_MASTER_YIELD'
                        AND    LU.VALID_YN    = 'Y'
                        AND    LU.SEGMENT1    = @V_DIVISION_ID
                        AND    LU.SEGMENT5 BETWEEN SUBSTRING(@V_PLAN_START_YYYYMMDD, 1, 6) AND SUBSTRING(@V_PLAN_END_YYYYMMDD, 1, 6)
                        GROUP BY LU.SEGMENT4, LU.SEGMENT5 */ )
                    , CATHODE_BOM AS (
                        SELECT    AD.CHILD_ITEM_ID  AS ANODE_ITEM_ID
                                , CD.CHILD_ITEM_ID  AS CHATHODE_ITEM_ID
                                , AD.USAGE/CD.USAGE AS CAL_USAGE        /* ANODE 소요량/CATHODE 소요량 */
                        FROM (  SELECT  PARENT_ITEM_ID,CHILD_ITEM_ID,USAGE
                                FROM    SCP_MST_BOM_ELEC
                                WHERE   PARENT_ITEM_ID IN ( SELECT DISTINCT ITEM_ID
                                                            FROM   SCP_OPT_ENG_MODEL_LIST_N_SN
                                                            WHERE  PLAN_ID = V_CATHODE_PLAN_ID  /* !!나중에 양극 Plan Id 로 바꿔치기 필요. */
                                                            )
                                AND     SCP_YN          = 'Y'
                                AND     ELECTRODE_TYPE  = 'ANODE'
                                ) AD
                        INNER JOIN (    SELECT  PARENT_ITEM_ID,CHILD_ITEM_ID,USAGE
                                        FROM    SCP_MST_BOM_ELEC
                                        WHERE   PARENT_ITEM_ID IN ( SELECT DISTINCT ITEM_ID
                                                                    FROM   SCP_OPT_ENG_MODEL_LIST_N_SN
                                                                    WHERE  PLAN_ID = V_CATHODE_PLAN_ID  /* !!나중에 양극 Plan Id 로 바꿔치기 필요. */
                                                                    )
                                        AND     SCP_YN = 'Y'
                                        AND     ELECTRODE_TYPE = 'CATHODE'
                                    ) CD
                                ON AD.PARENT_ITEM_ID = CD.PARENT_ITEM_ID
                        GROUP BY AD.CHILD_ITEM_ID,CD.CHILD_ITEM_ID,AD.USAGE,CD.USAGE )
                    /* ------------------------------------------------------------ */
                    /* value : boh_qty값을 음극/양극 사용비율을 반영하여 값을 지정한다. */
                    /* 2025.05.14 Philsu Park: Buffer_ID를 음극기준으로 바꿔줘야됨. ITEM_ID를 REPLACE처리. */
                    /*                         + Model List 제약조건 추가. + 음극 소요량 산식 변경. */
                    /* 2025.06.13 Philsu Park: NVARCHAR convertion error 방지를 위한 NVACHAR -> FLOAT -> NUMERIC 형태로 컨버전. */
                    /* 2025.07.09 Philsu Park: 소요량 * ELEC_POST 수율비중 * ASSY 수율비중 */
                    /* ------------------------------------------------------------ */
                    SELECT    V_PLAN_ID                                                 AS PLAN_ID
                            , REPLACE(S.BUFFER, S.ITEM, BOM.ANODE_ITEM_ID)              AS BUFFER_ID
                            , 'min_stock_qty'                                           AS TYPE
                            , S."DATE"                                                  AS START_DATE
                            , TO_CHAR(CM.BASIS_DATE + 1,'YYYYMMDD')                      AS END_DATE
                            /* , TRY_CONVERT(NUMERIC(20,10), TRY_CONVERT(FLOAT, S.QTY)) * BOM.CAL_USAGE            AS [VALUE] */
                            , SUM(ROUND((CASE WHEN VALIDATE_CONVERSION(S.QTY AS NUMBER) = 1 THEN TO_NUMBER(S.QTY) END)
                                    * BOM.CAL_USAGE
                                    * NVL(CYD.POST_YIELD, 1)/NVL(AYD.POST_YIELD, 1)
                                    * NVL(CYD.ASSY_YIELD, 1)/NVL(AYD.ASSY_YIELD, 1), 4)) AS VALUE
                            , 'L5'                                                      AS CALENDAR_LEVEL
                    FROM    SCP_OPT_ENG_OUT_PLAN_RESULT_SN S
                    INNER JOIN SCM_SYS_CALENDAR_M CM       /* 월요일 조건 걸기 위해 Calendar Join. */
                        ON  CM.BASIS_YYYYMMDD   = S."DATE"     /* Bucket Start 날짜 기준으로.. */
                    INNER JOIN CATHODE_BOM BOM
                        ON  S.ITEM                          = BOM.CHATHODE_ITEM_ID
                    LEFT OUTER JOIN YIELD_MST CYD
                        ON  S.ITEM          = CYD.ITEM_ID
                        AND CM.BASIS_YYYYMM = CYD.MONTH
                    LEFT OUTER JOIN YIELD_MST AYD
                        ON  BOM.ANODE_ITEM_ID   = AYD.ITEM_ID
                        AND CM.BASIS_YYYYMM     = AYD.MONTH
                    WHERE   S.PLAN_ID                       = V_CATHODE_PLAN_ID    /* 실제로는 양극 PLAN_ID 가 들어가야 함. */
                    AND     S.TYPE                          = 'BOH'                     /* Output Result에서 BOH만 가져와야 함. */
                    AND     SUBSTR(S.BUFFER, -7)            = 'COATING'                 /* COATING BUFFER */
                    AND     CM.DAYOFWEEK                    = 'MON'                     /* 월요일 새벽 BOH를 사용. */
                    AND     (CASE WHEN VALIDATE_CONVERSION(S.QTY AS NUMBER) = 1 THEN TO_NUMBER(S.QTY) END)  > 0                         /* 재고수량 > 0 값만 사용 */
                    AND     S.SITE||BOM.ANODE_ITEM_ID   IN (SELECT DISTINCT SCM_SITE_ID||ITEM_ID
                                                                    FROM   SCP_OPT_ENG_MODEL_LIST_N_SN
                                                                    WHERE  PLAN_ID = V_PLAN_ID
                                                                    )
                    GROUP BY REPLACE(S.BUFFER, S.ITEM, BOM.ANODE_ITEM_ID), S."DATE", TO_CHAR(CM.BASIS_DATE + 1,'YYYYMMDD')
                    UNION
                    /* ------------------------------------------------------------ */
                    /* 전체 기간에 대해 default 값 0을 설정 : L0 */
                    /* 2025.06.13 Philsu Park: NVARCHAR convertion error 방지를 위한 NVACHAR -> FLOAT -> NUMERIC 형태로 컨버전. */
                    /* ------------------------------------------------------------ */
                    SELECT    V_PLAN_ID                                         AS PLAN_ID
                            , REPLACE(S.BUFFER, S.ITEM, BOM.ANODE_ITEM_ID)      AS BUFFER_ID
                            , 'min_stock_qty'                                   AS TYPE
                            , V_PLAN_START_YYYYMMDD                             AS START_DATE
                            , V_PLAN_END_YYYYMMDD                               AS END_DATE
                            , TO_NUMBER('0')                                    AS VALUE
                            , 'L0'                                              AS CALENDAR_LEVEL
                    FROM    SCP_OPT_ENG_OUT_PLAN_RESULT_SN S
                    INNER JOIN SCM_SYS_CALENDAR_M CM       /* 월요일 조건 걸기 위해 Calendar Join. */
                        ON  CM.BASIS_YYYYMMDD   = S."DATE"     /* Bucket Start 날짜 기준으로.. */
                    INNER JOIN CATHODE_BOM BOM
                        ON  S.ITEM                          = BOM.CHATHODE_ITEM_ID
                    WHERE   S.PLAN_ID                       = V_CATHODE_PLAN_ID        /* 실제로는 양극 PLAN_ID 가 들어가야 함. */
                    AND     S.TYPE                          = 'BOH'                     /* Output Result에서 BOH만 가져와야 함. */
                    AND     SUBSTR(S.BUFFER, -7)            = 'COATING'                 /* COATING BUFFER */
                    AND     CM.DAYOFWEEK                    = 'MON'                     /* 월요일 새벽 BOH를 사용. */
                    AND     (CASE WHEN VALIDATE_CONVERSION(S.QTY AS NUMBER) = 1 THEN TO_NUMBER(S.QTY) END)  > 0                         /* 재고수량 > 0 값만 사용 */
                    AND     S.SITE||BOM.ANODE_ITEM_ID   IN (SELECT DISTINCT SCM_SITE_ID||ITEM_ID
                                                                    FROM   SCP_OPT_ENG_MODEL_LIST_N_SN
                                                                    WHERE  PLAN_ID = V_PLAN_ID
                                                                    );
        END IF;

        /* -------------------------------------------------------- */
        /* 2025.07.08 Philsu Park: Max_Stock_Qty 추가 */
        /* 6) Max_Stock_Qty : PRECEDE_QTY Lookup 정보 기반 등록. */
        /* 2025.11.04 Minyong Lee : Lookup -> UI 전환 (stock_qty) */
        /* 2025.11.25 Minyong Lee : */
        /*      - ROUTING JOIN이 있다면 그대로 유지 */
        /*      - ITEM_SITE JOIN이 없다면 INNER JOIN 추가 */
        /*      - Sales Site Incoterms 구분 없이 STAGE 기준 JOIN */
        /*      - ITEM_SITE의 BUFFER_ID 그대로 사용 */
        /* -------------------------------------------------------- */
        /* INSERT INTO SCP_OPT_ENG_SAFETY_STOCK_SN */
        /*    ( */
        /*        PLAN_ID */
        /*        , BUFFER_ID */
        /*        , [TYPE] */
        /*        , [START_DATE] */
        /*        , END_DATE */
        /*        , [VALUE] */
        /*        , CALENDAR_LEVEL */
        /*    ) */
            /* SELECT	 @V_PLAN_ID										AS PLAN_ID */
            /*        ,LV.SEGMENT3+'::'+LV.SEGMENT4+'::'+LV.SEGMENT5+IIF(SIS.ATTRIBUTE1 IS NULL ,'','@'+SIS.ATTRIBUTE1)+IIF(SIS.ATTRIBUTE2 IS NULL ,'','@'+SIS.ATTRIBUTE2) AS BUFFER_ID */
            /*        ,'max_stock_qty'								AS [TYPE] */
            /*        ,CASE WHEN LV.ATTRIBUTE1 <= @V_PLAN_START_YYYYMMDD THEN @V_PLAN_START_YYYYMMDD */
            /*              ELSE LV.ATTRIBUTE1 */
            /*          END                                           AS [START_DATE] */
            /*        ,CASE WHEN IIF(LV.ATTRIBUTE2<>'99991231',CONVERT(NVARCHAR(8),DATEADD(DAY,1,LV.ATTRIBUTE2),112),LV.ATTRIBUTE2) >= @V_PLAN_END_YYYYMMDD THEN @V_PLAN_END_YYYYMMDD */
            /*              ELSE IIF(LV.ATTRIBUTE2<>'99991231',CONVERT(NVARCHAR(8),DATEADD(DAY,1,LV.ATTRIBUTE2),112),LV.ATTRIBUTE2) */
            /*          END                                           AS END_DATE */
            /*        ,LV.ATTRIBUTE3									AS [VALUE] */
            /*        ,'L0'                                           AS CALENDAR_LEVEL */
            /* FROM SCP_OPMZ_LOOKUP_MASTER_DETAIL LV WITH(NOLOCK) */
            /* LEFT OUTER JOIN SCP_OPT_ENG_ITEM_SITE_SN SIS WITH(NOLOCK) */
            /*    ON  LV.SEGMENT3 = SIS.SITE_ID */
            /*    AND LV.SEGMENT4 = SIS.ITEM_ID */
            /*    AND SIS.PLAN_ID = @V_PLAN_ID */
            /*    AND LV.SEGMENT5 = SIS.ATTRIBUTE3-- + IIF(SIS.ATTRIBUTE1 IS NULL ,'','@'+SIS.ATTRIBUTE1)  -- Biz 기준으로만 Join 해야 정상 Join됨. */
            /* WHERE   LV.LOOKUP_TYPE	= 'SCP_OPT_ENG_CONST_PRECEDE_QTY' */
            /* AND     LV.VALID_YN		= 'Y' */
            /* AND     LV.SEGMENT2		= @V_DIVISION_ID */
            /* AND     GREATEST(LV.ATTRIBUTE1, @V_PLAN_START_YYYYMMDD) >= @V_PLAN_START_YYYYMMDD */
            /* AND     LEAST(LV.ATTRIBUTE2, @V_PLAN_END_YYYYMMDD)      <= @V_PLAN_END_YYYYMMDD */
            /* -- AND     LV.ATTRIBUTE4 = @V_GROUP_ID  Group 단위 관리 안하고 있어서 주석처리. */
            /* ; */

        INSERT INTO SCP_OPT_ENG_SAFETY_STOCK_SN
            (
                PLAN_ID
                , BUFFER_ID
                , TYPE
                , START_DATE
                , END_DATE
                , VALUE
                , CALENDAR_LEVEL
            )
        SELECT  V_PLAN_ID										AS PLAN_ID
              , SIS.BUFFER_ID                                   AS BUFFER_ID
              , 'max_stock_qty'								    AS TYPE
              , CASE
                    WHEN SQ.FROM_YYYYMMDD <= V_PLAN_START_YYYYMMDD THEN V_PLAN_START_YYYYMMDD
                    ELSE SQ.FROM_YYYYMMDD
                END                                             AS START_DATE
              , CASE
                    WHEN (CASE WHEN SQ.TO_YYYYMMDD <> '99991231' THEN TO_CHAR(TO_DATE(SQ.TO_YYYYMMDD,'YYYYMMDD') + 1,'YYYYMMDD') ELSE SQ.TO_YYYYMMDD END) >= V_PLAN_END_YYYYMMDD THEN V_PLAN_END_YYYYMMDD
                    ELSE (CASE WHEN SQ.TO_YYYYMMDD <> '99991231' THEN TO_CHAR(TO_DATE(SQ.TO_YYYYMMDD,'YYYYMMDD') + 1,'YYYYMMDD') ELSE SQ.TO_YYYYMMDD END)
                END                                             AS END_DATE
              , SQ.APL_QTY									    AS VALUE
              , 'L1'                                            AS CALENDAR_LEVEL
        FROM    SCP_OPMZ_SAFETY_STOCK SQ
            INNER JOIN  SCP_OPT_ENG_ITEM_SITE_SN SIS
                ON  SIS.PLAN_ID     = V_PLAN_ID
                AND SQ.SCM_SITE_ID  = SIS.SITE_ID
                AND SQ.ITEM_ID      = SIS.ITEM_ID
                AND SQ.STAGE        = SIS.ATTRIBUTE3
            LEFT OUTER JOIN SCP_OPMZ_PLAN_GR_M PG
                ON SQ.OPMZ_PLAN_GR_ID = PG.OPMZ_PLAN_GR_ID
            INNER JOIN  (
                        SELECT  DISTINCT ITEM_ID, STAGE
                        FROM    SCP_OPT_ENG_MODEL_LIST_N_SN
                        WHERE   PLAN_ID = V_PLAN_ID
                        ) MDL
                ON  SQ.ITEM_ID = MDL.ITEM_ID
                AND SQ.STAGE   = MDL.STAGE
        WHERE   1=1
        AND     SQ.VALUE_TYPE       = 'MAX'
        AND     SQ.VALID_YN		    = 'Y'
        AND     SQ.TO_YYYYMMDD      >= V_PLAN_START_YYYYMMDD
        AND     SQ.FROM_YYYYMMDD    < V_PLAN_END_YYYYMMDD
        AND     PG.OPMZ_PLAN_GR_NAME = V_PLAN_GROUP_ORG;

        /* ---------------------------------------------------------------------- */
        /* Data Insert End */
        /* ---------------------------------------------------------------------- */

        DELETE FROM GT_OPT_ENG_SS_DIVISION;

    /* ---------------------------------------------------------------------- */
    EXCEPTION
    /* ---------------------------------------------------------------------- */
    /* ROLLBACK TRANSACTION PR_SCP_OPT_ENG_RUN_MAIN_PROC; */
    /* ---------------------------------------------------------------------- */
      /* ERROR LOG */
    /* ---------------------------------------------------------------------- */
        WHEN OTHERS THEN
            V_MESSAGE_TEXT := SQLERRM;
            /* ---------------------------------------------------------------------- */
            PR_SCP_OPT_ENG_LOG_CRE_PROC('I','INPUT',V_PLAN_ID,V_PROGRAM_NAME,'ERROR',NULL,V_MESSAGE_TEXT,NULL,V_PLAN_ID);
            /* ---------------------------------------------------------------------- */
            V_DETAIL_DATE := SYSDATE;
            /* ---------------------------------------------------------------------- */
            PR_SCP_OPT_ENG_LOG_DTL_PROC('U',V_PLAN_ID,'STEP01',NULL,NULL,V_DETAIL_DATE,NULL,V_MESSAGE_TEXT,'ERROR');
            /* ---------------------------------------------------------------------- */
            RAISE_APPLICATION_ERROR(-20001, V_PROGRAM_NAME);
    /* ---------------------------------------------------------------------- */
    END;

    /* ---------------------------------------------------------------------- */
    /* 종료 LOG */
    /* ---------------------------------------------------------------------- */
    IF V_MESSAGE_TEXT IS NULL THEN
    /* ---------------------------------------------------------------------- */
        PR_SCP_OPT_ENG_LOG_CRE_PROC('I','INPUT',V_PLAN_ID,V_PROGRAM_NAME,'END',NULL,NULL,NULL,V_PLAN_ID);
        PR_SCP_OPT_ENG_LOG_DTL_PROC('U',V_PLAN_ID,'STEP01',NULL,NULL,NULL,NULL,NULL,NULL);
    END IF;
    /* ---------------------------------------------------------------------- */
END PR_SCP_OPT_ENG_EE_INPUT_SAFETY_STOCK;

PROCEDURE PR_SCP_OPT_ENG_EE_RUN_MAIN_PROC
(
     P_PLAN_ID  VARCHAR2
)
/* ============================================================
 * Program ID   : PR_SCP_OPT_ENG_EE_RUN_MAIN_PROC
 * Description  : SCP OPT ENG 전극(EE) 엔진 INPUT 데이터 생성 통합 실행(오케스트레이터)
 *                (SCP 최신 Plan 정보 수집 -> LOOKUP 재적재 -> 단계별 INPUT 생성 프로시저 순차 호출)
 * Program History
 *------------------------------------------------------------
 * Date          In Charge      Description
 *------------------------------------------------------------
 * 2025.02.05    Y.S.H          Initial Release
 * 2025.05.30    Philsu Park    OPT ENG LOOKUP 반영.
 * 2026.07.29    ZIONEX         [PJ202650304]  NextSCM Migration
 *                               본 proc 이 생산자이므로 첫 INSERT 직전 DELETE 로 초기화하고,
 * ============================================================ */
IS
    /* Set Prameter */
    V_PROGRAM_NAME        VARCHAR2(150 CHAR) := 'PR_SCP_OPT_ENG_EE_RUN_MAIN_PROC';
    V_PLAN_ID             VARCHAR2(50 CHAR)  := P_PLAN_ID;
    V_MESSAGE_TEXT        VARCHAR2(1000 CHAR);
    V_DETAIL_START_DATE   DATE;
    V_DETAIL_END_DATE     DATE;

    V_DIVISION_ID          VARCHAR2(20 CHAR);
    V_GROUP_ID             VARCHAR2(20 CHAR);
    V_PLAN_START_YYYYMMDD  VARCHAR2(8 CHAR);
    V_PLAN_END_YYYYMMDD    VARCHAR2(8 CHAR);

    /*
    --DECLARE @T_SCP_PLAN        optTableType_SCP_PLAN; -- SCP Plan 정보 저장용 UserType Table
    */

BEGIN
    /* ------------------------------------------------------------------ */
    /* Procedure 기본조건.                                                 */

    /* SET TRANSACTION ISOLATION LEVEL READ COMMITTED / SET ANSI_WARNINGS OFF 는 */

    /* ------------------------------------------------------------------ */

    /* ------------------------------------------------------------------ */
    /* LOG DELETE                                                          */
    /* ------------------------------------------------------------------ */
    /*
    --DELETE FROM SCP_OPT_ENG_ENGINE_RUN_STATUS_SN        WHERE PLAN_ID = @V_PLAN_ID
    --DELETE FROM SCP_OPT_ENG_ENGINE_RUN_STATUS_DETAIL_SN WHERE PLAN_ID = @V_PLAN_ID
    */
    DELETE
      FROM SCP_OPT_ENG_ENGINE_DATA_CREATE_L_N_SN
     WHERE PLAN_ID = V_PLAN_ID;

    /* ------------------------------------------------------------------ */
    /* Step 1. ENGINE_RUN_STATUS 생성                                      */
    /* ------------------------------------------------------------------ */
    /*
    --EXEC PR_SCP_OPT_ENG_LOG_STATUS_PROC 'I',@V_PLAN_ID,'N','N','N','N','N','N','N','N',NULL,NULL
    */
    /* ------------------------------------------------------------------ */
    /* Step 2. ENGINE_RUN_STATUS_DETAIL 생성                               */
    /* ------------------------------------------------------------------ */
    /*
    --EXEC PR_SCP_OPT_ENG_LOG_DTL_PROC 'I',@V_PLAN_ID,NULL,NULL,NULL,NULL,NULL,NULL,NULL
    */
    /* ------------------------------------------------------------------ */
    /* Step 3. SCP_OPT_ENG_ENGINE_DATA_CREATE_L_N 생성                     */
    /* ------------------------------------------------------------------ */
    PR_SCP_OPT_ENG_LOG_CRE_PROC('I','INPUT',V_PLAN_ID,V_PROGRAM_NAME,'START',NULL,NULL,NULL,V_PLAN_ID);

    /* ------------------------------------------------------------------ */
    /* Transaction (START)                                                 */
    /* BEGIN TRANSACTION SCP_OPT_ENG_RUN_MAIN_PROC;                        */
    /* ------------------------------------------------------------------ */
    BEGIN
        /* ------------------------------------------------------------------ */
        /* INPUT Start                                                         */
        /* ------------------------------------------------------------------ */
        /*
        --EXEC PR_SCP_OPT_ENG_LOG_STATUS_PROC 'U',@V_PLAN_ID,NULL,'Y',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL
        */
        V_DETAIL_START_DATE := SYSDATE;
        /*
        --EXEC PR_SCP_OPT_ENG_LOG_DTL_PROC 'U',@V_PLAN_ID,'STEP01',NULL,NULL,@V_DETAIL_START_DATE,NULL,NULL,'RUNNING'
        */

        /*
        --SELECT  @V_DIVISION_ID         = DIVISION_ID
        --       ,@V_GROUP_ID            = PLAN_TYPE_CODE
        --       ,@V_PLAN_START_YYYYMMDD = PLAN_START_YYYYMMDD
        --       ,@V_PLAN_END_YYYYMMDD   = CONVERT(NVARCHAR(8),DATEADD(DAY,1,PLAN_END_YYYYMMDD),112)
        --FROM    SCP_OPT_ENG_SCP_PLAN_ID_M_SN WITH(NOLOCK)
        --WHERE   1=1
        --AND     PLAN_ID = @V_PLAN_ID


        --SELECT   @V_DIVISION_ID         = PM.DIVISION_ID
        --        ,@V_GROUP_ID            = PGM.OPMZ_PLAN_GR_NAME
        --        ,@V_PLAN_START_YYYYMMDD = PM.PLAN_START_YYYYMMDD
        --        ,@V_PLAN_END_YYYYMMDD   = CONVERT(NVARCHAR(8),DATEADD(DAY,1,PM.PLAN_END_YYYYMMDD),112)
        --FROM     SCP_OPMZ_PLAN_M PM WITH(NOLOCK)
        --    INNER JOIN SCP_OPMZ_PLAN_GR_M PGM WITH(NOLOCK)
        --        ON PM.OPMZ_PLAN_GR_ID = PGM.OPMZ_PLAN_GR_ID
        --WHERE   PM.OPMZ_PLAN_ID = @V_PLAN_ID
        */

        /* 원본 SELECT @var (무행=값 유지/NULL) -> SELECT INTO + NO_DATA_FOUND / TOO_MANY_ROWS 가드. */
        BEGIN
            SELECT SUBSTR(A.DIVISION_ID,1,20)
                 , SUBSTR(A.PLAN_GROUP_ID,1,20)
                 , A.PLAN_START_YYYYMMDD
                 , A.PLAN_END_YYYYMMDD
              INTO V_DIVISION_ID
                 , V_GROUP_ID
                 , V_PLAN_START_YYYYMMDD
                 , V_PLAN_END_YYYYMMDD
              FROM (SELECT PM.DIVISION_ID          AS DIVISION_ID
                         , PGM.OPMZ_PLAN_GR_NAME   AS PLAN_GROUP_ID
                         , PM.PLAN_START_YYYYMMDD  AS PLAN_START_YYYYMMDD
                         , TO_CHAR(TO_DATE(PM.PLAN_END_YYYYMMDD,'YYYYMMDD') + 1,'YYYYMMDD') AS PLAN_END_YYYYMMDD
                      FROM SCP_OPMZ_PLAN_M     PM
                         , SCP_OPMZ_PLAN_GR_M  PGM
                     WHERE PM.OPMZ_PLAN_GR_ID = PGM.OPMZ_PLAN_GR_ID
                       AND PM.OPMZ_PLAN_ID    = V_PLAN_ID
                    UNION
                    SELECT DIVISION_ID             AS DIVISION_ID
                         , PLAN_TYPE_CODE          AS PLAN_GROUP_ID
                         , PLAN_START_YYYYMMDD     AS PLAN_START_YYYYMMDD
                         , TO_CHAR(TO_DATE(PLAN_END_YYYYMMDD,'YYYYMMDD') + 1,'YYYYMMDD') AS PLAN_END_YYYYMMDD
                      FROM SCP_OPT_ENG_SCP_PLAN_ID_M_SN
                     WHERE 1=1
                       AND PLAN_ID = V_PLAN_ID) A;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN NULL;
            WHEN TOO_MANY_ROWS THEN NULL;
        END;

        /* 사업부별 SCP 최신 Plan 정보
           ON COMMIT PRESERVE ROWS 이므로 생산자(본 proc)가 첫 INSERT 직전 DELETE 로 초기화한다. */
        DELETE
          FROM GT_OPT_ENG_SCP_PLAN;

        INSERT
          INTO GT_OPT_ENG_SCP_PLAN
             ( DIVISION_ID
             , PLAN_START_YYYYMMDD
             , PLAN_TYPE
             , PLAN_SEQ )
        SELECT A.DIVISION_ID
             , A.PLAN_START_YYYYMMDD
             , A.PLAN_TYPE
             , A.PLAN_SEQ
          FROM (SELECT DIVISION_ID
                     , PLAN_START_YYYYMMDD
                     , PLAN_TYPE
                     , PLAN_SEQ
                     , PLAN_TYPE_ORDER
                     , CONFIRM_FLAG
                     , ROW_NUMBER() OVER (PARTITION BY DIVISION_ID ORDER BY PLAN_START_YYYYMMDD DESC, PLAN_TYPE_ORDER DESC, PLAN_SEQ DESC) AS PLAN_RANK
                  FROM SCP_PLAN_VERSION_V
                 /* 전극 Division 에 해당하는 사업부 확인 */
                 WHERE DIVISION_ID IN (SELECT DIVISION_ID
                                         FROM SCM_MST_DIVISION
                                        WHERE VALID_YN   = 'Y'
                                          AND ATTRIBUTE3 <> 'EE'
                                          AND ATTRIBUTE4 = (SELECT ATTRIBUTE4
                                                              FROM SCM_MST_DIVISION
                                                             WHERE DIVISION_ID = V_DIVISION_ID) /* 전극 Division 변수 */
                                      )
                   AND PLAN_START_YYYYMMDD >= TO_CHAR(FN_NEXT_DAY(TO_DATE(V_PLAN_START_YYYYMMDD,'YYYYMMDD'),'MON') - 14,'YYYYMMDD') /* 전주 월요일 YYYYMMDD */
                   AND PLAN_START_YYYYMMDD <= TO_CHAR(FN_NEXT_DAY(TO_DATE(V_PLAN_START_YYYYMMDD,'YYYYMMDD'),'MON') -  7,'YYYYMMDD') /* 당주 월요일 YYYYMMDD */
               ) A
         WHERE PLAN_RANK = 1;

        /* 2025.05.15 Philsu Park: 동일 Plan_Id 로 존재하는 데이터 지우고 수행 시점 기준으로 돌려야 함. */
        DELETE
          FROM SCP_OPT_ENG_LOOKUP_SN
         WHERE PLAN_ID = V_PLAN_ID;

        /* PLAN_ID 별 LOOKUP SETTING 확인을 위한 조치 /선웅 선임님 요청/20250514/김태현 선임 */
        INSERT
          INTO SCP_OPT_ENG_LOOKUP_SN
             ( PLAN_ID
             , LOOKUP_TYPE
             , SEGMENT1
             , SEGMENT2
             , SEGMENT3
             , SEGMENT4
             , SEGMENT5
             , SEGMENT6
             , SEGMENT7
             , SEGMENT8
             , SEGMENT9
             , SEGMENT10
             , DISPLAY_SEQ
             , VALID_YN
             , DESCRIPTION
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , ATTRIBUTE6
             , ATTRIBUTE7
             , ATTRIBUTE8
             , ATTRIBUTE9
             , ATTRIBUTE10
             , ATTRIBUTE11
             , ATTRIBUTE12
             , ATTRIBUTE13
             , ATTRIBUTE14
             , ATTRIBUTE15 )
        SELECT V_PLAN_ID
             , LOOKUP_TYPE
             , SEGMENT1
             , SEGMENT2
             , SEGMENT3
             , SEGMENT4
             , SEGMENT5
             , SEGMENT6
             , SEGMENT7
             , SEGMENT8
             , SEGMENT9
             , SEGMENT10
             , DISPLAY_SEQ
             , VALID_YN
             , DESCRIPTION
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , ATTRIBUTE6
             , ATTRIBUTE7
             , ATTRIBUTE8
             , ATTRIBUTE9
             , ATTRIBUTE10
             , ATTRIBUTE11
             , ATTRIBUTE12
             , ATTRIBUTE13
             , ATTRIBUTE14
             , ATTRIBUTE15
          FROM SCP_OPMZ_LOOKUP_MASTER_DETAIL
         WHERE LOOKUP_TYPE LIKE '%SCP_OPT%';

        PR_SCP_OPT_ENG_EE_INPUT_FROZEN_MASTER   (V_PLAN_ID);
        /* DELETE Proc 는 일반 사업부와 같이 사용 */
        PR_SCP_OPT_ENG_INPUT_DELETE_PROC        (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);

        PR_SCP_OPT_ENG_EE_INPUT_PLAN_MASTER     (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        PR_SCP_OPT_ENG_EE_INPUT_BUCKET          (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        /* NLF / BOM 정보 처리 추가 고민??? */
        PR_SCP_OPT_ENG_EE_INPUT_ASSIGN_MODEL_LIST(V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        /*
        -- EXEC PR_SCP_OPT_ENG_EE_INPUT_MODEL_LIST         @V_PLAN_ID, @V_DIVISION_ID, @V_GROUP_ID, @V_PLAN_START_YYYYMMDD, @V_PLAN_END_YYYYMMDD               -- NLF / BOM 정보 처리 추가 고민???
        */
        /* 1차 수정 완료 */
        PR_SCP_OPT_ENG_EE_INPUT_RESOURCE        (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        /* 1차 수정 완료 */
        PR_SCP_OPT_ENG_EE_INPUT_EVERY_DAY_CAL   (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        PR_SCP_OPT_ENG_EE_INPUT_PARAMETER       (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        /* 위치이동 */
        PR_SCP_OPT_ENG_EE_INPUT_BOM_ELEC        (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        /* 1차 수정 완료 / As-Is @T_SCP_PLAN 인자 -> 공유 GTT GT_OPT_ENG_SCP_PLAN 참조(실사용) */
        PR_SCP_OPT_ENG_EE_INPUT_DEMAND          (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        /* 1차 수정 완료 */
        PR_SCP_OPT_ENG_EE_INPUT_BOM             (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        /*
        --EXEC PR_SCP_OPT_ENG_EE_INPUT_BOM_ELEC           @V_PLAN_ID, @V_DIVISION_ID, @V_GROUP_ID, @V_PLAN_START_YYYYMMDD, @V_PLAN_END_YYYYMMDD               -- 1차 수정 완료
        */
        /* 1차 수정 : Cell Plant 재고를 전극으로 처리 필요 */
        PR_SCP_OPT_ENG_EE_INPUT_INCOMING_STOCK  (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        /* 1차 수정 완료 / As-Is @T_SCP_PLAN 인자 -> 공유 GTT 로 대체(死파라미터) */
        PR_SCP_OPT_ENG_EE_INPUT_SCHEDULED_MOVE  (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        /* 1차 수정 완료 */
        PR_SCP_OPT_ENG_EE_INPUT_ITEM_SITE       (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        /* 1차 수정 완료 / As-Is @T_SCP_PLAN 인자 -> 공유 GTT 로 대체(死파라미터) */
        PR_SCP_OPT_ENG_EE_INPUT_BOD             (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        /* 1차 수정 완료 */
        PR_SCP_OPT_ENG_EE_INPUT_ROUTING_RESOURCE(V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        /* 1차 수정 완료 */
        PR_SCP_OPT_ENG_EE_INPUT_ROUTING         (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        /* 1차 수정 완료 / As-Is @T_SCP_PLAN 인자 -> 공유 GTT 로 대체(死파라미터) */
        PR_SCP_OPT_ENG_EE_INPUT_ITEM_BOM_ROUTING(V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        /* 1차 수정 완료 */
        PR_SCP_OPT_ENG_EE_INPUT_SAFETY_STOCK    (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        /* 1차 수정 완료 / As-Is @T_SCP_PLAN 인자 -> 공유 GTT 로 대체(死파라미터) */
        PR_SCP_OPT_ENG_EE_INPUT_FROZEN_PLAN     (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        /* 1차 수정 완료 */
        PR_SCP_OPT_ENG_EE_INPUT_HORIZON_CAL     (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        /* 1차 수정 완료 */
        PR_SCP_OPT_ENG_EE_INPUT_AFTER_CORRECT   (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);

        /* ------------------------------------------------------------------ */
        /* 현재 미사용 Procedure                                               */
        /* ------------------------------------------------------------------ */
        /*
        --EXEC PR_SCP_OPT_ENG_EE_INPUT_COBY_PROD_ITEM @V_PLAN_ID
        */
        /* ------------------------------------------------------------------ */
        /*
        -- EXEC PR_SCP_OPT_ENG_EE_INPUT_HISTORY : INPUT의 속도와 결과에 영향주지 않고 별도 실행시킬 방법????
        */

        /* ------------------------------------------------------------------ */
        /* INPUT END                                                           */
        /* ------------------------------------------------------------------ */
        /*
        --EXEC PR_SCP_OPT_ENG_LOG_STATUS_PROC 'U',@V_PLAN_ID,NULL,NULL,'Y',NULL,NULL,NULL,NULL,NULL,NULL,NULL
        */
        V_DETAIL_END_DATE := SYSDATE;
        /*
        --EXEC PR_SCP_OPT_ENG_LOG_DTL_PROC 'U',@V_PLAN_ID,'STEP01',NULL,NULL,NULL,@V_DETAIL_END_DATE,NULL,'COMPLETED'
        */

    EXCEPTION
        /* ERROR LOG */
        /* ROLLBACK TRANSACTION PR_SCP_OPT_ENG_EE_RUN_MAIN_PROC; */
        WHEN OTHERS THEN
            V_MESSAGE_TEXT := SUBSTR(SQLERRM, 1, 1000);
            PR_SCP_OPT_ENG_LOG_CRE_PROC('I','INPUT',V_PLAN_ID,V_PROGRAM_NAME,'ERROR',NULL,V_MESSAGE_TEXT,NULL,V_PLAN_ID);
            RAISE_APPLICATION_ERROR(-20001, V_MESSAGE_TEXT);
    END;

    /* 종료 LOG */
    IF V_MESSAGE_TEXT IS NULL THEN
        PR_SCP_OPT_ENG_LOG_CRE_PROC('I','INPUT',V_PLAN_ID,V_PROGRAM_NAME,'END',NULL,NULL,NULL,V_PLAN_ID);
    END IF;

END;

PROCEDURE PR_SCP_OPT_ENG_ESS_INPUT_DELETE_PROC
(
     P_PLAN_ID              VARCHAR2
    ,V_DIVISION_ID          VARCHAR2
    ,V_GROUP_ID             VARCHAR2
    ,V_PLAN_START_YYYYMMDD  VARCHAR2
    ,V_PLAN_END_YYYYMMDD    VARCHAR2
)
/* ============================================================
 * Program ID   : PR_SCP_OPT_ENG_ESS_INPUT_DELETE_PROC
 * Description  : SCP OPT ENG ESS 엔진 INPUT 데이터(MAIN/HISTORY _SN 계열) 삭제
 * Program History
 *------------------------------------------------------------
 * Date          In Charge      Description
 *------------------------------------------------------------
 * 2025.02.05    Y.S.H          Initial Release
 * 2026.07.06    ZIONEX         [PJ202650304]  NextSCM Migration
 *                              (상위 PR_SCP_OPT_ENG_ESS_RUN_MAIN_PROC 이 호출하는 하위 단계이므로
 *                               MSSQL 표준 컬럼 미사용, GTT/시퀀스 없음. 삭제 대상은 전부 단순 단일테이블 DELETE.)
 * ============================================================ */
AS
    V_PROGRAM_NAME  VARCHAR2(150 CHAR) := 'PR_SCP_OPT_ENG_ESS_INPUT_DELETE_PROC';
    V_PLAN_ID       VARCHAR2(50 CHAR)  := P_PLAN_ID;
    V_MESSAGE_TEXT  VARCHAR2(1000 CHAR);
    V_DETAIL_DATE   DATE;
BEGIN
    /* ---------------------------------------------------------------------- */
    /* Step 3. SCP_OPT_ENG_ENGINE_DATA_CREATE_L_N 생성 */
    /* ---------------------------------------------------------------------- */
    PR_SCP_OPT_ENG_LOG_CRE_PROC('I','INPUT',V_PLAN_ID,V_PROGRAM_NAME,'START',NULL,NULL,NULL,V_PLAN_ID);

    /* ---------------------------------------------------------------------- */
    /* Transaction (START) */
    /* ---------------------------------------------------------------------- */
    /* BEGIN TRANSACTION SCP_OPT_ENG_RUN_MAIN_PROC; */
    /* ---------------------------------------------------------------------- */
    BEGIN
        /* ---------------------------------------------------------------------- */
        /* DELETE START FOR MAIN */
        /* ---------------------------------------------------------------------- */
        DELETE FROM SCP_OPT_ENG_PLAN_MASTER_SN               WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_BOD_SN                       WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_BOM_SN                       WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_BOM_ELEC_SN                  WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_ITEM_SITE_SN                 WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_ROUTING_SN                   WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_ITEM_BOM_ROUTING_SN          WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_RESOURCE_SN                  WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_ROUTING_RESOURCE_SN          WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_RESOURCE_EVERY_CALENDAR_SN   WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_INCOMING_STOCK_SN            WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_DEMAND_SN                    WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_BUCKETS_SN                   WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_COBY_PROD_ITEM_SN            WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_FROZEN_PLAN_SN               WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_GOALS_SN                     WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_OBJECTIVES_SN                WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_OBJECTIVE_GOAL_MAPPING_SN    WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_PHASES_SN                    WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_RESOURCE_HORIZON_CALENDAR_SN WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_SAFETY_STOCK_SN              WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_SCHEDULED_MOVE_SN            WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_MODEL_LIST_N_SN              WHERE PLAN_ID LIKE (P_PLAN_ID || '%');
        DELETE FROM SCP_OPT_ENG_INCOMING_STOCK_XTR_SN        WHERE PLAN_ID = P_PLAN_ID;
        /* ---------------------------------------------------------------------- */
        /* DELETE START FOR HISTORY */
        /* ---------------------------------------------------------------------- */
        DELETE FROM SCP_OPT_ENG_PLAN_MASTER_H_SN               WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_BOD_H_SN                       WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_BOM_H_SN                       WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_ITEM_SITE_H_SN                 WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_ROUTING_H_SN                   WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_ITEM_BOM_ROUTING_H_SN          WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_RESOURCE_H_SN                  WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_ROUTING_RESOURCE_H_SN          WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_RESOURCE_EVERY_CALENDAR_H_SN   WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_INCOMING_STOCK_H_SN            WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_DEMAND_H_SN                    WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_BUCKETS_H_SN                   WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_COBY_PROD_ITEM_H_SN            WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_FROZEN_PLAN_H_SN               WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_GOALS_H_SN                     WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_OBJECTIVES_H_SN                WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_OBJECTIVE_GOAL_MAPPING_H_SN    WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_PHASES_H_SN                    WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_RESOURCE_HORIZON_CALENDAR_H_SN WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_SAFETY_STOCK_H_SN              WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_SCHEDULED_MOVE_H_SN            WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_MODEL_LIST_N_H_SN              WHERE PLAN_ID LIKE (P_PLAN_ID || '%');
        /* ---------------------------------------------------------------------- */
        /* DELETE END */
        /* ---------------------------------------------------------------------- */
    EXCEPTION
        /* ---------------------------------------------------------------------- */
        /* ROLLBACK TRANSACTION PR_SCP_OPT_ENG_ESS_RUN_MAIN_PROC; */
        /* ---------------------------------------------------------------------- */
        /* ERROR LOG */
        /* ---------------------------------------------------------------------- */
        WHEN OTHERS THEN
            V_MESSAGE_TEXT := SUBSTR(SQLERRM, 1, 1000);
            PR_SCP_OPT_ENG_LOG_CRE_PROC('I','INPUT',V_PLAN_ID,V_PROGRAM_NAME,'ERROR',NULL,V_MESSAGE_TEXT,NULL,V_PLAN_ID);
            V_DETAIL_DATE := SYSDATE;
            PR_SCP_OPT_ENG_LOG_DTL_PROC('U',V_PLAN_ID,'STEP01',NULL,NULL,V_DETAIL_DATE,NULL,V_MESSAGE_TEXT,'ERROR');
            RAISE;
    END;
    /* ---------------------------------------------------------------------- */
    /* 종료 LOG */
    /* ---------------------------------------------------------------------- */
    IF V_MESSAGE_TEXT IS NULL THEN
        PR_SCP_OPT_ENG_LOG_CRE_PROC('I','INPUT',V_PLAN_ID,V_PROGRAM_NAME,'END',NULL,NULL,NULL,V_PLAN_ID);
        PR_SCP_OPT_ENG_LOG_DTL_PROC('U',V_PLAN_ID,'STEP01',NULL,NULL,NULL,NULL,NULL,NULL);
    END IF;
END;

PROCEDURE PR_SCP_OPT_ENG_ESS_INPUT_PLAN_MASTER
(
     P_PLAN_ID              VARCHAR2
    ,V_DIVISION_ID          VARCHAR2
    ,V_GROUP_ID             VARCHAR2
    ,V_PLAN_START_YYYYMMDD  VARCHAR2
    ,V_PLAN_END_YYYYMMDD    VARCHAR2
)
/* ============================================================
 * Program ID   : PR_SCP_OPT_ENG_ESS_INPUT_PLAN_MASTER
 * Description  : SCP OPT ENG ESS 엔진 PLAN MASTER 입력데이터 생성
 * Program History
 *------------------------------------------------------------
 * Date          In Charge      Description
 *------------------------------------------------------------
 * 2025.02.05    Y.S.H          Initial Release
 * 2026.07.06    ZIONEX         [PJ202650304]  NextSCM Migration
 *                               상위 RUN_MAIN 이 호출하는 하위 단계이므로 내부 COMMIT 없음(부모 트랜잭션 소유).)
 * ============================================================ */
AS
    /* Set Prameter */
    V_PROGRAM_NAME       VARCHAR2(150 CHAR) := 'PR_SCP_OPT_ENG_ESS_INPUT_PLAN_MASTER';
    V_PLAN_ID            VARCHAR2(50 CHAR)  := P_PLAN_ID;
    V_MESSAGE_TEXT       VARCHAR2(1000 CHAR);
    V_DETAIL_DATE        DATE;

    V_SCP_PLAN_DATE      VARCHAR2(8 CHAR);
    V_SCP_PLAN_TYPE      VARCHAR2(8 CHAR);
    V_SCP_PLAN_SEQ       VARCHAR2(8 CHAR);
BEGIN
    /* Step 3. SCP_OPT_ENG_ENGINE_DATA_CREATE_L_N 생성 */
    PR_SCP_OPT_ENG_LOG_CRE_PROC('I','INPUT',V_PLAN_ID,V_PROGRAM_NAME,'START',NULL,NULL,NULL,V_PLAN_ID);

    /* ------------------------------------------------------------------ */
    /* Transaction (START)                                                 */
    /* BEGIN TRANSACTION SCP_OPT_ENG_RUN_MAIN_PROC;                        */
    /* ------------------------------------------------------------------ */
    BEGIN
        /* ------------------------------------------------------------------ */
        /* INPUT START                                                         */
        /* ------------------------------------------------------------------ */
        /*
        --INSERT INTO SCP_OPT_ENG_PLAN_MASTER_SN (PLAN_ID,PLAN_START_DATE,PLAN_END_DATE,ATTRIBUTE1,ATTRIBUTE2,ATTRIBUTE15)
        --SELECT  @V_PLAN_ID
        --       ,PLAN_START_YYYYMMDD
        --       ,CONVERT(NVARCHAR(8),DATEADD(DAY,1,PLAN_END_YYYYMMDD),112) AS PLAN_END_YYYYMMDD
        --       ,DIVISION_ID
        --       ,PLAN_TYPE_CODE
        --       ,@V_SCP_PLAN_DATE+','+@V_SCP_PLAN_TYPE+','+@V_SCP_PLAN_SEQ
        --FROM    SCP_OPT_ENG_SCP_PLAN_ID_M_SN WITH(NOLOCK)
        --WHERE   1=1
        --AND     PLAN_ID = @V_PLAN_ID


        --INSERT INTO SCP_OPT_ENG_PLAN_MASTER_SN (PLAN_ID,PLAN_START_DATE,PLAN_END_DATE,ATTRIBUTE1,ATTRIBUTE2,ATTRIBUTE15)
        --SELECT  @V_PLAN_ID
        --       ,PLAN_START_YYYYMMDD
        --       ,CONVERT(NVARCHAR(8),DATEADD(DAY,1,PLAN_END_YYYYMMDD),112) AS PLAN_END_YYYYMMDD
        --       ,PM.DIVISION_ID
        --       ,PGM.OPMZ_PLAN_GR_NAME
        --       ,@V_SCP_PLAN_DATE+','+@V_SCP_PLAN_TYPE+','+@V_SCP_PLAN_SEQ
        --FROM     SCP_OPMZ_PLAN_M PM WITH(NOLOCK)
        --    INNER JOIN SCP_OPMZ_PLAN_GR_M PGM WITH(NOLOCK)
        --        ON PM.OPMZ_PLAN_GR_ID = PGM.OPMZ_PLAN_GR_ID
        --WHERE   PM.OPMZ_PLAN_ID = @V_PLAN_ID
        */

        /* 2025.06.20 김태현 : DEMAND에 필요한 SEMI 정보는 FROZEN 계획을 SSP로 선택하거나 SCP 다른 버전을 선택했더라도, 최신 SCP 계획을 가져오는 것이 맞음/재욱 책임님 확인 사항 -> PLAN_MASTER에 마킹 */
        BEGIN
            SELECT A.PLAN_START_YYYYMMDD
                 , A.PLAN_TYPE
                 , A.PLAN_SEQ
              INTO V_SCP_PLAN_DATE
                 , V_SCP_PLAN_TYPE
                 , V_SCP_PLAN_SEQ
              FROM (SELECT DIVISION_ID
                         , PLAN_START_YYYYMMDD
                         , PLAN_TYPE
                         , PLAN_SEQ
                         , PLAN_TYPE_ORDER
                         , CONFIRM_FLAG
                         , ROW_NUMBER() OVER (PARTITION BY DIVISION_ID ORDER BY PLAN_TYPE_ORDER DESC, CONFIRM_FLAG DESC, PLAN_SEQ DESC) AS PLAN_RANK
                      FROM SCP_PLAN_VERSION_V
                     WHERE DIVISION_ID         = V_DIVISION_ID
                       AND PLAN_START_YYYYMMDD = TO_CHAR(FN_NEXT_DAY(TO_DATE(V_PLAN_START_YYYYMMDD,'YYYYMMDD'),'MON') - 7, 'YYYYMMDD') /* 해당 주 월요일 YYYYMMDD */
                   ) A
             WHERE A.PLAN_RANK = 1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN NULL;
            WHEN TOO_MANY_ROWS THEN NULL;
        END;

        INSERT
          INTO SCP_OPT_ENG_PLAN_MASTER_SN
             ( PLAN_ID
             , PLAN_START_DATE
             , PLAN_END_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE15 )
        SELECT V_PLAN_ID
             , PLAN_START_YYYYMMDD
             , PLAN_END_YYYYMMDD
             , DIVISION_ID
             , PLAN_GROUP_ID
             , V_SCP_PLAN_DATE||','||V_SCP_PLAN_TYPE||','||V_SCP_PLAN_SEQ
          FROM (SELECT PM.DIVISION_ID          AS DIVISION_ID
                     , PGM.OPMZ_PLAN_GR_NAME   AS PLAN_GROUP_ID
                     , PM.PLAN_START_YYYYMMDD  AS PLAN_START_YYYYMMDD
                     , TO_CHAR(TO_DATE(PM.PLAN_END_YYYYMMDD,'YYYYMMDD') + 1,'YYYYMMDD') AS PLAN_END_YYYYMMDD
                  FROM SCP_OPMZ_PLAN_M     PM
                     , SCP_OPMZ_PLAN_GR_M  PGM
                 WHERE PM.OPMZ_PLAN_GR_ID = PGM.OPMZ_PLAN_GR_ID
                   AND PM.OPMZ_PLAN_ID    = V_PLAN_ID
                UNION
                SELECT DIVISION_ID             AS DIVISION_ID
                     , PLAN_TYPE_CODE          AS PLAN_GROUP_ID
                     , PLAN_START_YYYYMMDD     AS PLAN_START_YYYYMMDD
                     , TO_CHAR(TO_DATE(PLAN_END_YYYYMMDD,'YYYYMMDD') + 1,'YYYYMMDD') AS PLAN_END_YYYYMMDD
                  FROM SCP_OPT_ENG_SCP_PLAN_ID_M_SN
                 WHERE 1=1
                   AND PLAN_ID = V_PLAN_ID) A;

        /* ------------------------------------------------------------------ */
        /* INPUT END                                                           */
        /* ------------------------------------------------------------------ */
    EXCEPTION
        /* ERROR LOG */
        /* ROLLBACK TRANSACTION PR_SCP_OPT_ENG_ESS_RUN_MAIN_PROC; */
        WHEN OTHERS THEN
            V_MESSAGE_TEXT := SQLERRM;
            PR_SCP_OPT_ENG_LOG_CRE_PROC('I','INPUT',V_PLAN_ID,V_PROGRAM_NAME,'ERROR',NULL,V_MESSAGE_TEXT,NULL,V_PLAN_ID);
            V_DETAIL_DATE  := SYSDATE;
            PR_SCP_OPT_ENG_LOG_DTL_PROC('U',V_PLAN_ID,'STEP01',NULL,NULL,V_DETAIL_DATE,NULL,V_MESSAGE_TEXT,'ERROR');
            RAISE_APPLICATION_ERROR(-20001, V_PROGRAM_NAME);
    END;

    /* 종료 LOG */
    IF V_MESSAGE_TEXT IS NULL THEN
        PR_SCP_OPT_ENG_LOG_CRE_PROC('I','INPUT',V_PLAN_ID,V_PROGRAM_NAME,'END',NULL,NULL,NULL,V_PLAN_ID);
        PR_SCP_OPT_ENG_LOG_DTL_PROC('U',V_PLAN_ID,'STEP01',NULL,NULL,NULL,NULL,NULL,NULL);
    END IF;

END PR_SCP_OPT_ENG_ESS_INPUT_PLAN_MASTER;

