PROCEDURE PR_SCP_OPT_ENG_GM_EE_RUN_MAIN_PROC
(
     P_PLAN_ID  VARCHAR2
)
/* ============================================================
 * Program ID   : PR_SCP_OPT_ENG_GM_EE_RUN_MAIN_PROC
 * Description  : SCP OPT ENG GM 전극(GM_EE) 엔진 INPUT 데이터 생성 통합 실행(오케스트레이터)
 *                (SCP 최신 Plan 정보 수집 -> LOOKUP 재적재 -> 단계별 INPUT 생성 프로시저 순차 호출)
 * Program History
 *------------------------------------------------------------
 * Date          In Charge      Description
 *------------------------------------------------------------
 * 2025.02.05    Y.S.H          Initial Release
 * 2025.05.30    Philsu Park    OPT ENG LOOKUP 반영.
 * 2026.07.29    ZIONEX         [PJ202650304]  NextSCM Migration
 *                               본 proc 이 생산자이므로 첫 INSERT 직전 DELETE 로 초기화하고,
 * ============================================================ */
IS
    /* Set Prameter */
    V_PROGRAM_NAME        VARCHAR2(150 CHAR) := 'PR_SCP_OPT_ENG_GM_EE_RUN_MAIN_PROC';
    V_PLAN_ID             VARCHAR2(50 CHAR)  := P_PLAN_ID;
    V_MESSAGE_TEXT        VARCHAR2(1000 CHAR);
    V_DETAIL_START_DATE   DATE;
    V_DETAIL_END_DATE     DATE;

    V_DIVISION_ID          VARCHAR2(20 CHAR);
    V_GROUP_ID             VARCHAR2(20 CHAR);
    V_PLAN_START_YYYYMMDD  VARCHAR2(8 CHAR);
    V_PLAN_END_YYYYMMDD    VARCHAR2(8 CHAR);

    /*
    --DECLARE @T_SCP_PLAN        optTableType_SCP_PLAN; -- SCP Plan 정보 저장용 UserType Table
    */

BEGIN
    /* ------------------------------------------------------------------ */
    /* Procedure 기본조건.                                                 */

    /* SET TRANSACTION ISOLATION LEVEL READ COMMITTED / SET ANSI_WARNINGS OFF 는 */

    /* ------------------------------------------------------------------ */

    /* ------------------------------------------------------------------ */
    /* LOG DELETE                                                          */
    /* ------------------------------------------------------------------ */
    /*
    --DELETE FROM SCP_OPT_ENG_ENGINE_RUN_STATUS_SN        WHERE PLAN_ID = @V_PLAN_ID
    --DELETE FROM SCP_OPT_ENG_ENGINE_RUN_STATUS_DETAIL_SN WHERE PLAN_ID = @V_PLAN_ID
    */
    DELETE
      FROM SCP_OPT_ENG_ENGINE_DATA_CREATE_L_N_SN
     WHERE PLAN_ID = V_PLAN_ID;

    /* ------------------------------------------------------------------ */
    /* Step 1. ENGINE_RUN_STATUS 생성                                      */
    /* ------------------------------------------------------------------ */
    /*
    --EXEC PR_SCP_OPT_ENG_LOG_STATUS_PROC 'I',@V_PLAN_ID,'N','N','N','N','N','N','N','N',NULL,NULL
    */
    /* ------------------------------------------------------------------ */
    /* Step 2. ENGINE_RUN_STATUS_DETAIL 생성                               */
    /* ------------------------------------------------------------------ */
    /*
    --EXEC PR_SCP_OPT_ENG_LOG_DTL_PROC 'I',@V_PLAN_ID,NULL,NULL,NULL,NULL,NULL,NULL,NULL
    */
    /* ------------------------------------------------------------------ */
    /* Step 3. SCP_OPT_ENG_ENGINE_DATA_CREATE_L_N 생성                     */
    /* ------------------------------------------------------------------ */
    PR_SCP_OPT_ENG_LOG_CRE_PROC('I','INPUT',V_PLAN_ID,V_PROGRAM_NAME,'START',NULL,NULL,NULL,V_PLAN_ID);

    /* ------------------------------------------------------------------ */
    /* Transaction (START)                                                 */
    /* BEGIN TRANSACTION SCP_OPT_ENG_RUN_MAIN_PROC;                        */
    /* ------------------------------------------------------------------ */
    BEGIN
        /* ------------------------------------------------------------------ */
        /* INPUT Start                                                         */
        /* ------------------------------------------------------------------ */
        /*
        --EXEC PR_SCP_OPT_ENG_LOG_STATUS_PROC 'U',@V_PLAN_ID,NULL,'Y',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL
        */
        V_DETAIL_START_DATE := SYSDATE;
        /*
        --EXEC PR_SCP_OPT_ENG_LOG_DTL_PROC 'U',@V_PLAN_ID,'STEP01',NULL,NULL,@V_DETAIL_START_DATE,NULL,NULL,'RUNNING'
        */

        /*
        --SELECT  @V_DIVISION_ID         = DIVISION_ID
        --       ,@V_GROUP_ID            = PLAN_TYPE_CODE
        --       ,@V_PLAN_START_YYYYMMDD = PLAN_START_YYYYMMDD
        --       ,@V_PLAN_END_YYYYMMDD   = CONVERT(NVARCHAR(8),DATEADD(DAY,1,PLAN_END_YYYYMMDD),112)
        --FROM    SCP_OPT_ENG_SCP_PLAN_ID_M_SN WITH(NOLOCK)
        --WHERE   1=1
        --AND     PLAN_ID = @V_PLAN_ID


        --SELECT   @V_DIVISION_ID         = PM.DIVISION_ID
        --        ,@V_GROUP_ID            = PGM.OPMZ_PLAN_GR_NAME
        --        ,@V_PLAN_START_YYYYMMDD = PM.PLAN_START_YYYYMMDD
        --        ,@V_PLAN_END_YYYYMMDD   = CONVERT(NVARCHAR(8),DATEADD(DAY,1,PM.PLAN_END_YYYYMMDD),112)
        --FROM     SCP_OPMZ_PLAN_M PM WITH(NOLOCK)
        --    INNER JOIN SCP_OPMZ_PLAN_GR_M PGM WITH(NOLOCK)
        --        ON PM.OPMZ_PLAN_GR_ID = PGM.OPMZ_PLAN_GR_ID
        --WHERE   PM.OPMZ_PLAN_ID = @V_PLAN_ID
        */

        /* 원본 SELECT @var (무행=값 유지/NULL) -> SELECT INTO + NO_DATA_FOUND / TOO_MANY_ROWS 가드. */
        BEGIN
            SELECT SUBSTR(A.DIVISION_ID,1,20)
                 , SUBSTR(A.PLAN_GROUP_ID,1,20)
                 , A.PLAN_START_YYYYMMDD
                 , A.PLAN_END_YYYYMMDD
              INTO V_DIVISION_ID
                 , V_GROUP_ID
                 , V_PLAN_START_YYYYMMDD
                 , V_PLAN_END_YYYYMMDD
              FROM (SELECT PM.DIVISION_ID          AS DIVISION_ID
                         , PGM.OPMZ_PLAN_GR_NAME   AS PLAN_GROUP_ID
                         , PM.PLAN_START_YYYYMMDD  AS PLAN_START_YYYYMMDD
                         , TO_CHAR(TO_DATE(PM.PLAN_END_YYYYMMDD,'YYYYMMDD') + 1,'YYYYMMDD') AS PLAN_END_YYYYMMDD
                      FROM SCP_OPMZ_PLAN_M     PM
                         , SCP_OPMZ_PLAN_GR_M  PGM
                     WHERE PM.OPMZ_PLAN_GR_ID = PGM.OPMZ_PLAN_GR_ID
                       AND PM.OPMZ_PLAN_ID    = V_PLAN_ID
                    UNION
                    SELECT DIVISION_ID             AS DIVISION_ID
                         , PLAN_TYPE_CODE          AS PLAN_GROUP_ID
                         , PLAN_START_YYYYMMDD     AS PLAN_START_YYYYMMDD
                         , TO_CHAR(TO_DATE(PLAN_END_YYYYMMDD,'YYYYMMDD') + 1,'YYYYMMDD') AS PLAN_END_YYYYMMDD
                      FROM SCP_OPT_ENG_SCP_PLAN_ID_M_SN
                     WHERE 1=1
                       AND PLAN_ID = V_PLAN_ID) A;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN NULL;
            WHEN TOO_MANY_ROWS THEN NULL;
        END;

        /* 사업부별 SCP 최신 Plan 정보
           ON COMMIT PRESERVE ROWS 이므로 생산자(본 proc)가 첫 INSERT 직전 DELETE 로 초기화한다. */
        DELETE
          FROM GT_OPT_ENG_SCP_PLAN;

        INSERT
          INTO GT_OPT_ENG_SCP_PLAN
             ( DIVISION_ID
             , PLAN_START_YYYYMMDD
             , PLAN_TYPE
             , PLAN_SEQ )
        SELECT A.DIVISION_ID
             , A.PLAN_START_YYYYMMDD
             , A.PLAN_TYPE
             , A.PLAN_SEQ
          FROM (SELECT DIVISION_ID
                     , PLAN_START_YYYYMMDD
                     , PLAN_TYPE
                     , PLAN_SEQ
                     , PLAN_TYPE_ORDER
                     , CONFIRM_FLAG
                     , ROW_NUMBER() OVER (PARTITION BY DIVISION_ID ORDER BY PLAN_START_YYYYMMDD DESC, PLAN_TYPE_ORDER DESC, PLAN_SEQ DESC) AS PLAN_RANK
                  FROM SCP_PLAN_VERSION_V
                 /* 전극 Division 에 해당하는 사업부 확인 */
                 WHERE DIVISION_ID IN (SELECT DIVISION_ID
                                         FROM SCM_MST_DIVISION
                                        WHERE VALID_YN   = 'Y'
                                          AND ATTRIBUTE3 <> 'EE'
                                          AND ATTRIBUTE4 = (SELECT ATTRIBUTE4
                                                              FROM SCM_MST_DIVISION
                                                             WHERE DIVISION_ID = V_DIVISION_ID) /* 전극 Division 변수 */
                                      )
                   AND PLAN_START_YYYYMMDD >= TO_CHAR(FN_NEXT_DAY(TO_DATE(V_PLAN_START_YYYYMMDD,'YYYYMMDD'),'MON') - 14,'YYYYMMDD') /* 전주 월요일 YYYYMMDD */
                   AND PLAN_START_YYYYMMDD <= TO_CHAR(FN_NEXT_DAY(TO_DATE(V_PLAN_START_YYYYMMDD,'YYYYMMDD'),'MON') -  7,'YYYYMMDD') /* 당주 월요일 YYYYMMDD */
               ) A
         WHERE PLAN_RANK = 1;

        /* 2025.05.15 Philsu Park: 동일 Plan_Id 로 존재하는 데이터 지우고 수행 시점 기준으로 돌려야 함. */
        DELETE
          FROM SCP_OPT_ENG_LOOKUP_SN
         WHERE PLAN_ID = V_PLAN_ID;

        /* PLAN_ID 별 LOOKUP SETTING 확인을 위한 조치 /선웅 선임님 요청/20250514/김태현 선임 */
        INSERT
          INTO SCP_OPT_ENG_LOOKUP_SN
             ( PLAN_ID
             , LOOKUP_TYPE
             , SEGMENT1
             , SEGMENT2
             , SEGMENT3
             , SEGMENT4
             , SEGMENT5
             , SEGMENT6
             , SEGMENT7
             , SEGMENT8
             , SEGMENT9
             , SEGMENT10
             , DISPLAY_SEQ
             , VALID_YN
             , DESCRIPTION
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , ATTRIBUTE6
             , ATTRIBUTE7
             , ATTRIBUTE8
             , ATTRIBUTE9
             , ATTRIBUTE10
             , ATTRIBUTE11
             , ATTRIBUTE12
             , ATTRIBUTE13
             , ATTRIBUTE14
             , ATTRIBUTE15 )
        SELECT V_PLAN_ID
             , LOOKUP_TYPE
             , SEGMENT1
             , SEGMENT2
             , SEGMENT3
             , SEGMENT4
             , SEGMENT5
             , SEGMENT6
             , SEGMENT7
             , SEGMENT8
             , SEGMENT9
             , SEGMENT10
             , DISPLAY_SEQ
             , VALID_YN
             , DESCRIPTION
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , ATTRIBUTE6
             , ATTRIBUTE7
             , ATTRIBUTE8
             , ATTRIBUTE9
             , ATTRIBUTE10
             , ATTRIBUTE11
             , ATTRIBUTE12
             , ATTRIBUTE13
             , ATTRIBUTE14
             , ATTRIBUTE15
          FROM SCP_OPMZ_LOOKUP_MASTER_DETAIL
         WHERE LOOKUP_TYPE LIKE '%SCP_OPT%';

        PR_SCP_OPT_ENG_GM_EE_INPUT_FROZEN_MASTER   (V_PLAN_ID);
        /* DELETE Proc 는 일반 사업부와 같이 사용 */
        PR_SCP_OPT_ENG_INPUT_DELETE_PROC           (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);

        PR_SCP_OPT_ENG_GM_EE_INPUT_PLAN_MASTER     (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        PR_SCP_OPT_ENG_GM_EE_INPUT_BUCKET          (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        /* NLF / BOM 정보 처리 추가 고민??? */
        PR_SCP_OPT_ENG_GM_EE_INPUT_ASSIGN_MODEL_LIST(V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        /* 1차 수정 완료 */
        PR_SCP_OPT_ENG_GM_EE_INPUT_RESOURCE        (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        /* 1차 수정 완료 */
        PR_SCP_OPT_ENG_GM_EE_INPUT_EVERY_DAY_CAL   (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        PR_SCP_OPT_ENG_GM_EE_INPUT_PARAMETER       (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        /* 1차 수정 완료 / As-Is @T_SCP_PLAN 인자 -> 공유 GTT GT_OPT_ENG_SCP_PLAN 참조(실사용) */
        PR_SCP_OPT_ENG_GM_EE_INPUT_DEMAND          (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        /* 1차 수정 완료 */
        PR_SCP_OPT_ENG_GM_EE_INPUT_BOM             (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        /* 1차 수정 완료 */
        PR_SCP_OPT_ENG_GM_EE_INPUT_BOM_ELEC        (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        /* 1차 수정 : Cell Plant 재고를 전극으로 처리 필요 */
        PR_SCP_OPT_ENG_GM_EE_INPUT_INCOMING_STOCK  (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        /* 1차 수정 완료 / As-Is @T_SCP_PLAN 인자 -> 공유 GTT 로 대체 */
        PR_SCP_OPT_ENG_GM_EE_INPUT_SCHEDULED_MOVE  (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        /* 1차 수정 완료 */
        PR_SCP_OPT_ENG_GM_EE_INPUT_ITEM_SITE       (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        /* 1차 수정 완료 / As-Is @T_SCP_PLAN 인자 -> 공유 GTT 로 대체(死파라미터) */
        PR_SCP_OPT_ENG_GM_EE_INPUT_BOD             (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        /* 1차 수정 완료 */
        PR_SCP_OPT_ENG_GM_EE_INPUT_ROUTING_RESOURCE(V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        /* 1차 수정 완료 */
        PR_SCP_OPT_ENG_GM_EE_INPUT_ROUTING         (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        PR_SCP_OPT_ENG_INPUT_COBY_PROD_ITEM        (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        /* 1차 수정 완료 / As-Is @T_SCP_PLAN 인자 -> 공유 GTT 로 대체(死파라미터) */
        PR_SCP_OPT_ENG_GM_EE_INPUT_ITEM_BOM_ROUTING(V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        /* 1차 수정 완료 */
        PR_SCP_OPT_ENG_GM_EE_INPUT_SAFETY_STOCK    (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        /* 1차 수정 완료 / As-Is @T_SCP_PLAN 인자 -> 공유 GTT 로 대체(死파라미터) */
        PR_SCP_OPT_ENG_GM_EE_INPUT_FROZEN_PLAN     (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        /* 1차 수정 완료 */
        PR_SCP_OPT_ENG_GM_EE_INPUT_HORIZON_CAL     (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        /* 1차 수정 완료 */
        PR_SCP_OPT_ENG_GM_EE_INPUT_AFTER_CORRECT   (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);

        /* ------------------------------------------------------------------ */
        /* 현재 미사용 Procedure                                               */
        /* ------------------------------------------------------------------ */
        /*
        --EXEC PR_SCP_OPT_ENG_GM_EE_INPUT_COBY_PROD_ITEM @V_PLAN_ID
        */
        /* ------------------------------------------------------------------ */
        /*
        -- EXEC PR_SCP_OPT_ENG_GM_EE_INPUT_HISTORY : INPUT의 속도와 결과에 영향주지 않고 별도 실행시킬 방법????
        */

        /* ------------------------------------------------------------------ */
        /* INPUT END                                                           */
        /* ------------------------------------------------------------------ */
        /*
        --EXEC PR_SCP_OPT_ENG_LOG_STATUS_PROC 'U',@V_PLAN_ID,NULL,NULL,'Y',NULL,NULL,NULL,NULL,NULL,NULL,NULL
        */
        V_DETAIL_END_DATE := SYSDATE;
        /*
        --EXEC PR_SCP_OPT_ENG_LOG_DTL_PROC 'U',@V_PLAN_ID,'STEP01',NULL,NULL,NULL,@V_DETAIL_END_DATE,NULL,'COMPLETED'
        */

    EXCEPTION
        /* ERROR LOG */
        /* ROLLBACK TRANSACTION PR_SCP_OPT_ENG_GM_EE_RUN_MAIN_PROC; */
        WHEN OTHERS THEN
            V_MESSAGE_TEXT := SUBSTR(SQLERRM, 1, 1000);
            PR_SCP_OPT_ENG_LOG_CRE_PROC('I','INPUT',V_PLAN_ID,V_PROGRAM_NAME,'ERROR',NULL,V_MESSAGE_TEXT,NULL,V_PLAN_ID);
            RAISE_APPLICATION_ERROR(-20001, V_MESSAGE_TEXT);
    END;

    /* 종료 LOG */
    IF V_MESSAGE_TEXT IS NULL THEN
        PR_SCP_OPT_ENG_LOG_CRE_PROC('I','INPUT',V_PLAN_ID,V_PROGRAM_NAME,'END',NULL,NULL,NULL,V_PLAN_ID);
    END IF;

END;

PROCEDURE PR_SCP_OPT_ENG_GM_INPUT_AFTER_CORRECT
(
     P_PLAN_ID              VARCHAR2
    ,V_DIVISION_ID          VARCHAR2
    ,V_GROUP_ID             VARCHAR2
    ,V_PLAN_START_YYYYMMDD  VARCHAR2
    ,V_PLAN_END_YYYYMMDD    VARCHAR2
)
/* ============================================================
 * Program ID   : PR_SCP_OPT_ENG_GM_INPUT_AFTER_CORRECT
 * Description  : SCP OPT ENG GM 엔진 입력데이터 보정 (AFTER CORRECT)
 *                FROZEN CARRY OVER / MATERIAL CONSTRAINTS / LINE·EQ FULL LOADING
 *                / FROZEN PLAN / EVERY CALENDAR 재구성 / GM MATERIAL 재고 ROLLING
 *                / MONTHLYOFF BUCKET
 * Program History
 *------------------------------------------------------------
 * Date          In Charge      Description
 *------------------------------------------------------------
 * 2025.07.07    Philsu Park    Initial Release
 * 2026.07.29    ZIONEX         [PJ202650304]  NextSCM Migration
 * ============================================================ */
AS
    /*       SET TRANSACTION ISOLATION LEVEL READ COMMITTED)은 Oracle 기본 동작과 동일하여 이관 불필요 */
    V_PROGRAM_NAME           VARCHAR2(150 CHAR) := 'PR_SCP_OPT_ENG_GM_INPUT_AFTER_CORRECT';
    V_PLAN_ID                VARCHAR2(50 CHAR)  := P_PLAN_ID;
    V_MESSAGE_TEXT           VARCHAR2(1000 CHAR);
    V_DETAIL_DATE            DATE;
    V_PLAN_START_YYYYMM      VARCHAR2(6 CHAR);
    V_PLAN_END_YYYYMM        VARCHAR2(6 CHAR);
    V_FROZEN_CARRY_OVER_DATE VARCHAR2(100 CHAR);
    V_ROLLING_YN             VARCHAR2(1 CHAR);
    V_HORIZEN_ZERO_YN        VARCHAR2(1 CHAR);
    V_MONTHLYOFF_YN          VARCHAR2(1 CHAR);
    /*         @NO_WORK_TEMP         -> GT_OPT_ENG_GMAC_NOWORK @M_INV_RL_TEMP        -> GT_OPT_ENG_GMAC_MINVRL @FL_EC_EQ_TEMP        -> 死 테이블변수: 활성코드 미사용(주석처리 구로직에만 등장) → GTT 미생성 */
BEGIN
    /*  Step 3. SCP_OPT_ENG_ENGINE_DATA_CREATE_L_N 생성 */
    PR_SCP_OPT_ENG_LOG_CRE_PROC('I','INPUT',V_PLAN_ID,V_PROGRAM_NAME,'START',NULL,NULL,NULL,V_PLAN_ID);

    /* ---------------------------------------------------------------------- */
    /*  Transaction (START) */
    /* ---------------------------------------------------------------------- */
    /* BEGIN TRANSACTION SCP_OPT_ENG_RUN_MAIN_PROC; */
    /* ---------------------------------------------------------------------- */
    BEGIN
        /* ---------------------------------------------------------------------- */
        /*  Get Plan Mater Info */
        /* ---------------------------------------------------------------------- */
        BEGIN
            SELECT SUBSTR(PLAN_START_DATE,1,6), SUBSTR(PLAN_END_DATE,1,6)
              INTO V_PLAN_START_YYYYMM, V_PLAN_END_YYYYMM
              FROM SCP_OPT_ENG_PLAN_MASTER_SN
             WHERE PLAN_ID = V_PLAN_ID;
        EXCEPTION WHEN NO_DATA_FOUND THEN NULL; WHEN TOO_MANY_ROWS THEN NULL;
        END;

        /* FROZEN의 MAX일자를 FROZENCARRYOVERDATE로 지정 */
        /*           FROZEN 행이 없어 MAX 가 NULL 인 경우를 CASE 로 감싸 NULL 을 보존(미보존 시 아래 분기 발산) */
        SELECT CASE WHEN MAX(FROZEN_END_DATE) IS NULL THEN NULL
                    ELSE MAX(FROZEN_END_DATE) || ':000000' END
          INTO V_FROZEN_CARRY_OVER_DATE
          FROM SCP_OPT_ENG_FROZEN_MASTER_SN
         WHERE PLAN_ID = V_PLAN_ID
         AND   FROZEN_TYPE = 'PROD';

        /* FROZEN의 MAX일자가 PSD보다 작거나 없으면 PSD로 변경 */
        V_FROZEN_CARRY_OVER_DATE := CASE WHEN NVL(V_FROZEN_CARRY_OVER_DATE, V_PLAN_START_YYYYMMDD) <= V_PLAN_START_YYYYMMDD
                                         THEN V_PLAN_START_YYYYMMDD
                                         ELSE V_FROZEN_CARRY_OVER_DATE END || ':000000';

        /* ---------------------------------------------------------------------- */
        /*  Data UPDATE */
        /* 2025.05.27 Philsu Park: FROZENCARRYOVERDATE 값이 Fix를 보지 않게 제외. */
        /* 2025.09.18 THKIM : EQ도 LINE과 동일한 기준으로 UPDATE 하기 위해 수정 */
        /* ---------------------------------------------------------------------- */
        /* UPDATE SCP_OPT_ENG_RESOURCE_SN */
        /* SET SCP_OPT_ENG_RESOURCE_SN.FROZENCARRYOVERDATE           = A.FROZENCARRYOVERDATE */
        /*    ,SCP_OPT_ENG_RESOURCE_SN.FROZENCARRYOVERSETUPGROUPNAME = A.FROZENCARRYOVERSETUPGROUPNAME */
        /*    ,SCP_OPT_ENG_RESOURCE_SN.FROZENCARRYOVERSETUPITEMNAME  = A.FROZENCARRYOVERSETUPITEMNAME */
        /* FROM( */
        /*     SELECT     SFP2.PLAN_ID                 AS PLAN_ID */
        /*             ,SFP2.RESOURCE_ID              AS RESOURCE_ID */
        /*             --,SFP2.EFFECTIVE_DATE+':000000' AS FROZENCARRYOVERDATE */
        /*             ,CONVERT(NVARCHAR, DATEADD(DAY, 1, CONVERT(DATE,SFP2.EFFECTIVE_DATE)),112)+':000000' AS FROZENCARRYOVERDATE */
        /*             ,SFP2.ATTRIBUTE1              AS SITE_ID */
        /*             ,'LINE'                          AS RESOURCE_TYPE */
        /*             ,LU.SETUP_GROUP_ID              AS FROZENCARRYOVERSETUPGROUPNAME */
        /*             ,LU.SETUP_ID                  AS FROZENCARRYOVERSETUPITEMNAME */
        /*             ,SFP2.ATTRIBUTE3              AS GROUP_SETUP_CONTROL_CODE */
        /*             ,SFP2.ATTRIBUTE3              AS ITEM_SETUP_CONTROL_CODE */
        /*     FROM    (SELECT ROW_NUMBER() OVER ( PARTITION BY PLAN_ID, RESOURCE_ID ORDER BY EFFECTIVE_DATE DESC, ATTRIBUTE2 DESC) AS ROWNUM */
        /*                   ,SFP.* */
        /*              FROM   SCP_OPT_ENG_FROZEN_PLAN_SN SFP WITH(NOLOCK) */
        /*              WHERE  PLAN_ID = @V_PLAN_ID */
        /*              AND    SFP.ATTRIBUTE13 != 'LOOKUP_PROD_FIX' --2025.05.27 Philsu Park: FROZENCARRYOVERDATE 값이 Fix를 보지 않게 제외. */
        /*             ) SFP2 */
        /*             LEFT OUTER JOIN ( */
        /*                     SELECT  LU.SEGMENT2    AS DIVISION_ID */
        /*                            ,LU.SEGMENT3    AS SCM_SITE_ID */
        /*                            ,LU.SEGMENT4    AS LINE_ID */
        /*                            ,ITS.ITEM_ID    AS ITEM_ID */
        /*                            ,LU.ATTRIBUTE1  AS SETUP_GROUP_ID */
        /*                            ,IIF(LU.ATTRIBUTE2='',NULL,LU.ATTRIBUTE2) AS SETUP_ID */
        /*                            ,CONVERT(INT,CONVERT(NUMERIC(20,1),LU.ATTRIBUTE3)*86400)  AS GROUP_SETUP_TIME */
        /*                            ,CONVERT(INT,CONVERT(NUMERIC(20,1),LU.ATTRIBUTE4)*86400)  AS SETUP_TIME */
        /*                     FROM    SCP_OPMZ_LOOKUP_MASTER_DETAIL LU WITH(NOLOCK) */
        /*                     LEFT OUTER JOIN SCP_OPT_ENG_ITEM_SITE_SN ITS WITH(NOLOCK) */
        /*                     ON      ITS.SITE_ID = LU.SEGMENT3 */
        /*                     --AND     ITS.STAGE      = 'ASSY' */
        /*                     AND     ITS.STAGE      IN ('ASSY', 'MDLE', 'PACK', 'EOL', 'STK' ) */
        /*                     AND     ITS.SETUP_GROUP_ID = LU.SEGMENT5 */
        /*                     WHERE   LU.SEGMENT2    = @V_DIVISION_ID */
        /*                     AND     LU.LOOKUP_TYPE = 'SCP_OPT_ENG_CONST_SETUP' */
        /*                     AND     ITS.PLAN_ID    = @V_PLAN_ID */
        /*                     AND     LU.VALID_YN    = 'Y' */
        /*                 )LU */
        /*                 ON  SFP2.ATTRIBUTE1 = LU.SCM_SITE_ID */
        /*                 AND SFP2.ATTRIBUTE2 = LU.ITEM_ID */
        /*                 --AND SFP2.ATTRIBUTE3 = 'ASSY' */
        /*                 AND SFP2.ATTRIBUTE3 IN ('ASSY', 'MDLE', 'PACK', 'EOL', 'STK' ) */
        /*                 AND SFP2.ATTRIBUTE14+'@'+ATTRIBUTE3 = LU.LINE_ID */
        /*     WHERE 1=1 */
        /*     AND   SFP2.ROWNUM = 1 */
        /*     ) A */
        /* WHERE   SCP_OPT_ENG_RESOURCE_SN.PLAN_ID       = @V_PLAN_ID */
        /* AND     SCP_OPT_ENG_RESOURCE_SN.RESOURCE_TYPE = 'LINE' */
        /* AND     SCP_OPT_ENG_RESOURCE_SN.RESOURCE_ID   = A.RESOURCE_ID */

        /*           ★런타임주의: 파생 A 는 SFP2 에 LU 를 LEFT JOIN 하므로 조인키 (SITE_ID, LINE_ID, STAGE_BUFFER)
             SFP2.ATTRIBUTE3 IN (...) 이 있어 (+) 로 옮기면 WHERE 화되어 보존행이 사라짐 -> ANSI 유지. */
        UPDATE SCP_OPT_ENG_RESOURCE_SN R
           SET ( R.FROZENCARRYOVERDATE, R.FROZENCARRYOVERSETUPGROUPNAME, R.FROZENCARRYOVERSETUPITEMNAME )
             = ( SELECT A.FROZENCARRYOVERDATE, A.FROZENCARRYOVERSETUPGROUPNAME, A.FROZENCARRYOVERSETUPITEMNAME
                   FROM (
                        SELECT   SFP2.PLAN_ID                 AS PLAN_ID
                                ,SFP2.RESOURCE_ID             AS RESOURCE_ID
                                /* ,SFP2.EFFECTIVE_DATE+':000000' AS FROZENCARRYOVERDATE */
                                ,CASE WHEN SFP2.EFFECTIVE_DATE IS NULL THEN NULL
                                      ELSE TO_CHAR(TO_DATE(SUBSTR(SFP2.EFFECTIVE_DATE,1,8),'YYYYMMDD') + 1,'YYYYMMDD')||':000000' END AS FROZENCARRYOVERDATE
                                ,SFP2.ATTRIBUTE1              AS SITE_ID
                                ,SFP2.ATTRIBUTE14             AS LINE_ID
                                ,SFP2.ATTRIBUTE4              AS STAGE_BUFFER
                                ,'LINE'                       AS RESOURCE_TYPE
                                ,LU.SETUP_GROUP_ID            AS FROZENCARRYOVERSETUPGROUPNAME
                                ,LU.SETUP_ID                  AS FROZENCARRYOVERSETUPITEMNAME
                                ,SFP2.ATTRIBUTE3              AS GROUP_SETUP_CONTROL_CODE
                                ,SFP2.ATTRIBUTE3              AS ITEM_SETUP_CONTROL_CODE
                        FROM    ( SELECT ROW_NUMBER() OVER ( PARTITION BY PLAN_ID, RESOURCE_ID ORDER BY EFFECTIVE_DATE DESC, ATTRIBUTE2 DESC) AS RN
                                        ,SFP.*
                                   FROM   SCP_OPT_ENG_FROZEN_PLAN_SN SFP
                                   WHERE  PLAN_ID = V_PLAN_ID
                                   AND    SFP.ATTRIBUTE13 != 'LOOKUP_PROD_FIX' /* 2025.05.27 Philsu Park: FROZENCARRYOVERDATE 값이 Fix를 보지 않게 제외. */
                                ) SFP2
                                LEFT OUTER JOIN (
                                        SELECT  LU.SEGMENT2    AS DIVISION_ID
                                               ,LU.SEGMENT3    AS SCM_SITE_ID
                                               ,LU.SEGMENT4    AS LINE_ID
                                               ,ITS.ITEM_ID    AS ITEM_ID
                                               ,LU.ATTRIBUTE1  AS SETUP_GROUP_ID
                                               ,CASE WHEN LU.ATTRIBUTE2 IS NULL THEN NULL ELSE LU.ATTRIBUTE2 END AS SETUP_ID
                                               ,TRUNC(CAST(LU.ATTRIBUTE3 AS NUMBER(20,1))*86400)  AS GROUP_SETUP_TIME
                                               ,TRUNC(CAST(LU.ATTRIBUTE4 AS NUMBER(20,1))*86400)  AS SETUP_TIME
                                        FROM    SCP_OPMZ_LOOKUP_MASTER_DETAIL LU
                                        LEFT OUTER JOIN SCP_OPT_ENG_ITEM_SITE_SN ITS
                                        ON      ITS.SITE_ID = LU.SEGMENT3
                                        /* AND     ITS.STAGE      = 'ASSY' */
                                        AND     ITS.STAGE      IN ('ASSY', 'MDLE', 'PACK', 'EOL', 'STK' )
                                        AND     ITS.SETUP_GROUP_ID = LU.SEGMENT5
                                        WHERE   LU.SEGMENT2    = V_DIVISION_ID
                                        AND     LU.LOOKUP_TYPE = 'SCP_OPT_ENG_CONST_SETUP'
                                        AND     ITS.PLAN_ID    = V_PLAN_ID
                                        AND     LU.VALID_YN    = 'Y'
                                    ) LU
                                    ON  SFP2.ATTRIBUTE1 = LU.SCM_SITE_ID
                                    AND SFP2.ATTRIBUTE2 = LU.ITEM_ID
                                    /* AND SFP2.ATTRIBUTE3 = 'ASSY' */
                                    AND SFP2.ATTRIBUTE3 IN ('ASSY', 'MDLE', 'PACK', 'EOL', 'STK' )
                                    AND CASE WHEN SFP2.ATTRIBUTE14 IS NULL OR SFP2.ATTRIBUTE3 IS NULL THEN NULL
                                             ELSE SFP2.ATTRIBUTE14||'@'||SFP2.ATTRIBUTE3 END = LU.LINE_ID
                        WHERE 1=1
                        AND   SFP2.RN = 1
                        ) A
                  WHERE A.SITE_ID      = R.ATTRIBUTE1
                  AND   A.LINE_ID      = CASE WHEN R.RESOURCE_TYPE = 'LINE' THEN R.ATTRIBUTE15 ELSE R.ATTRIBUTE14 END
                  AND   A.STAGE_BUFFER = R.ATTRIBUTE4 )
         WHERE R.PLAN_ID       = V_PLAN_ID
         AND   R.RESOURCE_TYPE IN('LINE','EQ')
         AND   EXISTS (

                   SELECT 1
                   FROM ( SELECT ROW_NUMBER() OVER ( PARTITION BY PLAN_ID, RESOURCE_ID ORDER BY EFFECTIVE_DATE DESC, ATTRIBUTE2 DESC) AS RN
                                ,SFP.*
                           FROM   SCP_OPT_ENG_FROZEN_PLAN_SN SFP
                           WHERE  PLAN_ID = V_PLAN_ID
                           AND    SFP.ATTRIBUTE13 != 'LOOKUP_PROD_FIX'
                        ) SFP2
                   WHERE SFP2.RN = 1
                   AND   SFP2.ATTRIBUTE1  = R.ATTRIBUTE1
                   AND   SFP2.ATTRIBUTE14 = CASE WHEN R.RESOURCE_TYPE = 'LINE' THEN R.ATTRIBUTE15 ELSE R.ATTRIBUTE14 END
                   AND   SFP2.ATTRIBUTE4  = R.ATTRIBUTE4 );

        /* ---------------------------------------------------------------------- */
        /* 20250915/THKIM : GM은 FROZEN이 없는 경우에 실적 기준으로 FROZENCARRYOVER UPDATE */
        /*  2025.09.17 Philsu Park: Stage 조건 추가해서 실제 공정별 ITEM 찾아오게 수정. */
        /* ---------------------------------------------------------------------- */
        /*           ★런타임주의: 파생 A 는 RESOURCE_ID 당 1행(ROWNUM=1)이나 LU 아우터조인으로 다중행 가능
             -> YYYYMMDD 문자열 비교는 TO_DATE 로 맞춘다(MSSQL 은 문자열을 DATETIME 으로 암시변환). */
        UPDATE SCP_OPT_ENG_RESOURCE_SN R
           SET ( R.FROZENCARRYOVERDATE, R.FROZENCARRYOVERSETUPGROUPNAME, R.FROZENCARRYOVERSETUPITEMNAME )
             = ( SELECT A.FROZENCARRYOVERDATE, A.FROZENCARRYOVERSETUPGROUPNAME, A.FROZENCARRYOVERSETUPITEMNAME
                   FROM (
                        SELECT  TO_CHAR(TRUNC(PR.PLAN_DATE) + 1,'YYYYMMDD')||':000000'                   AS FROZENCARRYOVERDATE
                               ,LU.SETUP_GROUP_ID                                                        AS FROZENCARRYOVERSETUPGROUPNAME
                               ,LU.SETUP_ID                                                              AS FROZENCARRYOVERSETUPITEMNAME
                               ,PR.RESOURCE_ID                                                           AS RESOURCE_ID
                        FROM (
                            SELECT PR.PLANT_ID
                                  ,PR.ITEM_ID
                                  ,PR.LINE_ID
                                  ,PR.PLAN_DATE
                                  ,RS.SCM_SITE_ID
                                  ,RS.STAGE
                                  ,RS.STAGE_BUFFER
                                  ,RS.RESOURCE_ID
                                  ,ROW_NUMBER() OVER ( PARTITION BY RS.RESOURCE_ID ORDER BY PR.PLAN_DATE DESC, PR.ITEM_ID DESC) AS RN
                            FROM   SCM_DAILY_PRODUCT_RESULT_H_SN PR
                                     , (
                                            SELECT RE.ATTRIBUTE1  AS SCM_SITE_ID
                                                  ,RE.ATTRIBUTE3  AS STAGE
                                                  ,RE.ATTRIBUTE4  AS STAGE_BUFFER
                                                  ,NVL(RE.ATTRIBUTE14,RE.ATTRIBUTE15) AS LINE_ID
                                                  ,RE.RESOURCE_ID AS RESOURCE_ID
                                                  ,OP.OPERATION_ID
                                            FROM SCP_OPT_ENG_RESOURCE_SN RE
                                               , (SELECT   SEGMENT1 AS DIVISION_ID
                                                                ,SEGMENT2 AS PLAN_GROUP
                                                                ,SEGMENT3 AS STAGE
                                                                ,SEGMENT5 AS OPERATION_ID
                                                        FROM    SCP_OPMZ_LOOKUP_MASTER_DETAIL LV
                                                        WHERE   LOOKUP_TYPE = 'SCP_OPT_ENG_STAGE_OPERATION_MAP'
                                                        AND     SEGMENT1    = V_DIVISION_ID
                                                        AND     SEGMENT2    = V_GROUP_ID
                                                        AND     VALID_YN    = 'Y') OP
                                            WHERE OP.STAGE = RE.ATTRIBUTE3
                                            AND   RE.PLAN_ID = V_PLAN_ID
                                            AND   RE.ATTRIBUTE15 IS NOT NULL
                                            GROUP BY RE.ATTRIBUTE1, RE.ATTRIBUTE3, RE.ATTRIBUTE4, RE.ATTRIBUTE14, RE.ATTRIBUTE15, RE.RESOURCE_ID, OP.OPERATION_ID
                                            ) RS
                            WHERE PR.LINE_ID      = RS.LINE_ID
                            AND   PR.OPERATION_ID = RS.OPERATION_ID
                            AND   PR.PLAN_DATE   < TO_DATE(V_PLAN_START_YYYYMMDD,'YYYYMMDD')
                            AND   PR.PLAN_DATE   >= ADD_MONTHS(TO_DATE(V_PLAN_START_YYYYMMDD,'YYYYMMDD'),-2)
                            AND   PR.DIVISION_ID = V_DIVISION_ID
                            /*  AND   PR.OPERATION_ID = 'A9000' -- 질문 */
                            AND   PR.ACTUAL_GOOD_QTY > 0  /*  실적은 ACTUAL_GOOD_QTY */
                            GROUP BY PR.PLANT_ID,PR.ITEM_ID,PR.LINE_ID,PR.PLAN_DATE,RS.SCM_SITE_ID,RS.STAGE,RS.STAGE_BUFFER, RS.RESOURCE_ID
                            ) PR
                            LEFT OUTER JOIN (
                                        SELECT  LU.SEGMENT2    AS DIVISION_ID
                                               ,LU.SEGMENT3    AS SCM_SITE_ID
                                               ,LU.SEGMENT4    AS LINE_ID
                                               ,ITS.ITEM_ID    AS ITEM_ID
                                               ,LU.ATTRIBUTE1  AS SETUP_GROUP_ID
                                               ,CASE WHEN LU.ATTRIBUTE2 IS NULL THEN NULL ELSE LU.ATTRIBUTE2 END AS SETUP_ID
                                               ,TRUNC(CAST(LU.ATTRIBUTE3 AS NUMBER(20,1))*86400)  AS GROUP_SETUP_TIME
                                               ,TRUNC(CAST(LU.ATTRIBUTE4 AS NUMBER(20,1))*86400)  AS SETUP_TIME
                                        FROM    SCP_OPMZ_LOOKUP_MASTER_DETAIL LU
                                        LEFT OUTER JOIN SCP_OPT_ENG_ITEM_SITE_SN ITS
                                        ON      ITS.SITE_ID = LU.SEGMENT3
                                        AND     ITS.STAGE      IN ('ASSY', 'MDLE', 'PACK', 'EOL', 'STK' )
                                        AND     ITS.SETUP_GROUP_ID = LU.SEGMENT5
                                        WHERE   LU.SEGMENT2    = V_DIVISION_ID
                                        AND     LU.LOOKUP_TYPE = 'SCP_OPT_ENG_CONST_SETUP'
                                        AND     ITS.PLAN_ID    = V_PLAN_ID
                                        AND     LU.VALID_YN    = 'Y'
                                       ) LU
                                    ON  PR.SCM_SITE_ID = LU.SCM_SITE_ID
                                    AND PR.ITEM_ID = LU.ITEM_ID
                                    AND PR.STAGE IN ('ASSY', 'MDLE', 'PACK', 'EOL', 'STK' )
                                    AND PR.LINE_ID = SUBSTR(LU.LINE_ID,1,INSTR(LU.LINE_ID,'@')-1)
                        WHERE PR.RN = 1
                        ) A
                  WHERE A.RESOURCE_ID = R.RESOURCE_ID )
         WHERE R.PLAN_ID       = V_PLAN_ID
         AND   R.RESOURCE_TYPE IN('LINE','EQ')
         AND   R.FROZENCARRYOVERDATE IS NULL
         AND   EXISTS (
                   SELECT 1
                   FROM (
                        SELECT RS.RESOURCE_ID AS RESOURCE_ID
                              ,ROW_NUMBER() OVER ( PARTITION BY RS.RESOURCE_ID ORDER BY PR.PLAN_DATE DESC, PR.ITEM_ID DESC) AS RN
                        FROM   SCM_DAILY_PRODUCT_RESULT_H_SN PR
                             , (
                                        SELECT RE.ATTRIBUTE1  AS SCM_SITE_ID
                                              ,RE.ATTRIBUTE3  AS STAGE
                                              ,RE.ATTRIBUTE4  AS STAGE_BUFFER
                                              ,NVL(RE.ATTRIBUTE14,RE.ATTRIBUTE15) AS LINE_ID
                                              ,RE.RESOURCE_ID AS RESOURCE_ID
                                              ,OP.OPERATION_ID
                                        FROM SCP_OPT_ENG_RESOURCE_SN RE
                                           , (SELECT   SEGMENT1 AS DIVISION_ID
                                                            ,SEGMENT2 AS PLAN_GROUP
                                                            ,SEGMENT3 AS STAGE
                                                            ,SEGMENT5 AS OPERATION_ID
                                                    FROM    SCP_OPMZ_LOOKUP_MASTER_DETAIL LV
                                                    WHERE   LOOKUP_TYPE = 'SCP_OPT_ENG_STAGE_OPERATION_MAP'
                                                    AND     SEGMENT1    = V_DIVISION_ID
                                                    AND     SEGMENT2    = V_GROUP_ID
                                                    AND     VALID_YN    = 'Y') OP
                                        WHERE OP.STAGE = RE.ATTRIBUTE3
                                        AND   RE.PLAN_ID = V_PLAN_ID
                                        AND   RE.ATTRIBUTE15 IS NOT NULL
                                        GROUP BY RE.ATTRIBUTE1, RE.ATTRIBUTE3, RE.ATTRIBUTE4, RE.ATTRIBUTE14, RE.ATTRIBUTE15, RE.RESOURCE_ID, OP.OPERATION_ID
                                        ) RS
                        WHERE PR.LINE_ID      = RS.LINE_ID
                        AND   PR.OPERATION_ID = RS.OPERATION_ID
                        AND   PR.PLAN_DATE   < TO_DATE(V_PLAN_START_YYYYMMDD,'YYYYMMDD')
                        AND   PR.PLAN_DATE   >= ADD_MONTHS(TO_DATE(V_PLAN_START_YYYYMMDD,'YYYYMMDD'),-2)
                        AND   PR.DIVISION_ID = V_DIVISION_ID
                        AND   PR.ACTUAL_GOOD_QTY > 0
                        GROUP BY PR.PLANT_ID,PR.ITEM_ID,PR.LINE_ID,PR.PLAN_DATE,RS.SCM_SITE_ID,RS.STAGE,RS.STAGE_BUFFER, RS.RESOURCE_ID
                        ) A
                   WHERE A.RN = 1
                   AND   A.RESOURCE_ID = R.RESOURCE_ID );

        /* ---------------------------------------------------------------------- */
        /* 20250918/THKIM : FROZEN CARRY OVER DATE 일괄 UPDATE(LINE,EQ,MODEL) */
        /* ---------------------------------------------------------------------- */
        UPDATE  SCP_OPT_ENG_RESOURCE_SN
        SET     FROZENCARRYOVERDATE = V_FROZEN_CARRY_OVER_DATE
        WHERE   PLAN_ID = V_PLAN_ID
        AND     RESOURCE_TYPE IN('LINE','EQ','MODEL');

        /* ---------------------------------------------------------------------- */
        /*  2025.11.07 Minyong Lee : 단일모델 제약을 고려한 FROZENCARRYOVERSETUPGROUPNAME 통일 */
        /*  (MSSQL @SETUPGROUPNAME 테이블변수 -> GTT GT_OPT_ENG_GMAC_SGN, 진입부 DELETE 로 초기화) */
        /* ---------------------------------------------------------------------- */
        DELETE FROM GT_OPT_ENG_GMAC_SGN;

        INSERT INTO GT_OPT_ENG_GMAC_SGN (ATTRIBUTE4, FROZENCARRYOVERSETUPGROUPNAME)
        SELECT ATTRIBUTE4
             , MAX(A.FROZENCARRYOVERSETUPGROUPNAME) AS FROZENCARRYOVERSETUPGROUPNAME
        FROM   SCP_OPT_ENG_RESOURCE_SN A
        WHERE  PLAN_ID = V_PLAN_ID
        AND    RESOURCE_TYPE IN('LINE')
        GROUP BY STAGE, ATTRIBUTE4;

        /* (MSSQL UPDATE..FROM INNER JOIN @SETUPGROUPNAME -> 상관 UPDATE + EXISTS)
           ★런타임주의: @SETUPGROUPNAME 은 GROUP BY STAGE,ATTRIBUTE4 라 ATTRIBUTE4 당 다중행 가능 */
        UPDATE SCP_OPT_ENG_RESOURCE_SN A
           SET A.FROZENCARRYOVERSETUPGROUPNAME = ( SELECT SG.FROZENCARRYOVERSETUPGROUPNAME
                                                     FROM GT_OPT_ENG_GMAC_SGN SG
                                                    WHERE SG.ATTRIBUTE4 = A.ATTRIBUTE4 )
         WHERE A.PLAN_ID = V_PLAN_ID
         AND   A.RESOURCE_TYPE IN ('LINE', 'EQ')
         AND   EXISTS ( SELECT 1 FROM GT_OPT_ENG_GMAC_SGN SG WHERE SG.ATTRIBUTE4 = A.ATTRIBUTE4 );

        UPDATE SCP_OPT_ENG_RESOURCE_SN A
           SET A.FROZENCARRYOVERSETUPGROUPNAME = ( SELECT SG.FROZENCARRYOVERSETUPGROUPNAME
                                                     FROM GT_OPT_ENG_GMAC_SGN SG
                                                    WHERE SG.ATTRIBUTE4 = A.RESOURCE_NAME )
         WHERE A.PLAN_ID = V_PLAN_ID
         AND   A.RESOURCE_TYPE IN ('MODEL')
         AND   EXISTS ( SELECT 1 FROM GT_OPT_ENG_GMAC_SGN SG WHERE SG.ATTRIBUTE4 = A.RESOURCE_NAME );

        /* ---------------------------------------------------------------------- */
        /* BOD 중 TO_BUFFER나 FROM_BUFFER가 ITEM_SITE에 없는 데이터는 삭제 */
        /*  (MSSQL DELETE..FROM INNER JOIN -> DELETE + EXISTS) */
        /* ---------------------------------------------------------------------- */
        DELETE FROM SCP_OPT_ENG_BOD_SN BOD
         WHERE BOD.PLAN_ID = V_PLAN_ID
         AND   EXISTS (
                   SELECT 1
                   FROM (
                        SELECT PLAN_ID
                              ,BOD_ID
                        FROM(
                            SELECT A.PLAN_ID
                                  ,A.BOD_ID
                            FROM   SCP_OPT_ENG_BOD_SN A
                                 , SCP_OPT_ENG_ITEM_SITE_SN B
                           WHERE 1=1
                             AND B.PLAN_ID(+)   = A.PLAN_ID
                             AND B.BUFFER_ID(+) = A.TO_BUFFER_ID
                             AND A.PLAN_ID = V_PLAN_ID
                             AND B.PLAN_ID IS NULL
                            UNION ALL
                            SELECT A.PLAN_ID
                                  ,A.BOD_ID
                            FROM   SCP_OPT_ENG_BOD_SN A
                                 , SCP_OPT_ENG_ITEM_SITE_SN B
                           WHERE 1=1
                             AND B.PLAN_ID(+)   = A.PLAN_ID
                             AND B.BUFFER_ID(+) = A.FROM_BUFFER_ID
                             AND A.PLAN_ID = V_PLAN_ID
                             AND B.PLAN_ID IS NULL
                            ) A
                        GROUP BY A.PLAN_ID, A.BOD_ID
                    ) DEL
                   WHERE DEL.PLAN_ID = BOD.PLAN_ID
                   AND   DEL.BOD_ID  = BOD.BOD_ID );

        /* ---------------------------------------------------------------------- */
        /*  SCHEDULED_MOVE에 bod가 없으면 삭제 */
        /*  BOD가 없는 SCHEDULED MOVE가 있어도 엔진이 돌아가는지 검증을 위해 주석처리 */

        /* ---------------------------------------------------------------------- */
        DELETE FROM SCP_OPT_ENG_SCHEDULED_MOVE_SN A
         WHERE A.PLAN_ID = V_PLAN_ID
         AND   NOT EXISTS (
                   SELECT 1
                   FROM SCP_OPT_ENG_BOD_SN B
                   WHERE B.PLAN_ID        = A.PLAN_ID
                   AND   B.FROM_BUFFER_ID = A.FROM_BUFFER_ID
                   AND   B.TO_BUFFER_ID   = A.TO_BUFFER_ID
                   AND   B.TRANSPORT_MODE = A.TRANSPORT_MODE
                   AND   B.BOD_ID IS NOT NULL );

        /* ---------------------------------------------------------------------- */
        /*  LOAD PER UPDATE -> LOAD PER * YIELD */

        /* ---------------------------------------------------------------------- */
        UPDATE SCP_OPT_ENG_ROUTING_RESOURCE_SN RR
           SET RR.LOAD_PER = RR.LOAD_PER * ( SELECT RT.YIELD
                                               FROM SCP_OPT_ENG_ROUTING_SN RT
                                              WHERE RT.PLAN_ID    = RR.PLAN_ID
                                              AND   RT.ROUTING_ID = RR.ROUTING_ID
                                              AND   RT.OP_SEQ     = RR.OP_SEQ )
         WHERE RR.PLAN_ID = V_PLAN_ID
         AND   RR.RESOURCE_CLASS_ID IN('LINE','MODEL','EQ');

        /* ---------------------------------------------------------------------- */
        /*  FROZEN PLAN QUANTITY -> QUANTITY * YIELD */

        /*  ★런타임주의: ROUTING 이 ATTRIBUTE 조합에 유일키가 없어 다중매치 시 ORA-01427 가능(원본도 비결정적) */
        /* ---------------------------------------------------------------------- */
        UPDATE SCP_OPT_ENG_FROZEN_PLAN_SN FP
           SET FP.QUANTITY = FP.QUANTITY / NVL( ( SELECT RT.YIELD
                                                    FROM SCP_OPT_ENG_ROUTING_SN RT
                                                   WHERE RT.PLAN_ID     = FP.PLAN_ID
                                                   AND   RT.ATTRIBUTE1  = FP.ATTRIBUTE1
                                                   AND   RT.ATTRIBUTE2  = FP.ATTRIBUTE2
                                                   AND   RT.ATTRIBUTE3  = FP.ATTRIBUTE3
                                                   AND   RT.ATTRIBUTE14 = FP.ATTRIBUTE14
                                                   AND   RT.ATTRIBUTE15 = FP.ATTRIBUTE15 ), 1)
         WHERE FP.PLAN_ID = V_PLAN_ID;

        /* ---------------------------------------------------------------------- */
        /*  Delete Garbage Demand Data */
        /* ---------------------------------------------------------------------- */
        DELETE FROM SCP_OPT_ENG_DEMAND_SN
        WHERE   PLAN_ID = V_PLAN_ID
        AND     ATTRIBUTE13 = 'GROUP_DEMAND';

        /* ---------------------------------------------------------------------- */
        /* MATERIAL CONSTRAINTS */
        /*  2025.07.18 Philsu Park: EFF_START 날짜가 END 날짜보다 뒤에 있으면 안됨. */
        /* ---------------------------------------------------------------------- */

        INSERT INTO SCP_OPT_ENG_ITEM_BOM_ROUTING_SN(PLAN_ID,ROUTING_BOM_MAPPING_ID,BUFFER_ID,ROUTING_ID,BOM_ID,EFF_START_DATE,EFF_END_DATE,FROZEN_FENCE,PRIORITY
                                                    ,IN_CONTAINER_CATEGORY,IN_CONTAINER_SIZE,OUT_CONTAINER_CATEGORY,OUT_CONTAINER_SIZE)
        SELECT V_PLAN_ID AS PLAN_ID
              ,'RB'||SCM_SITE_ID||'::'||C_ITEM_ID||'::'||'MATERIAL_CONST'||'::-::-' AS ROUTING_BOM_MAPPING_ID
              ,SCM_SITE_ID||'::'||C_ITEM_ID||'::'||'MATERIAL_CONST'                 AS BUFFER_ID
              ,SCM_SITE_ID||'::'||C_ITEM_ID||'::'||'MATERIAL_CONST'||'::-::-'       AS ROUTING_ID
              ,NULL                                                           AS BOM_ID
              ,LEAST(V_PLAN_END_YYYYMMDD, EFF_END_DATE)                       AS EFF_START_DATE
              ,V_PLAN_END_YYYYMMDD                                            AS EFF_END_DATE
              ,NULL                                                           AS FROZEN_FENCE
              ,1                                                              AS PRIORITY
              ,NULL                                                           AS IN_CONTAINER_CATEGORY
              ,NULL                                                           AS IN_CONTAINER_SIZE
              ,NULL                                                           AS OUT_CONTAINER_CATEGORY
              ,NULL                                                           AS OUT_CONTAINER_SIZE
        FROM(
            /*  START 2025.11.19 jongykim2: Schelduled Reciept Information */
            SELECT   LU.PLANT_SITE_ID AS SCM_SITE_ID
                    ,LU.ITEM_ID AS P_ITEM_ID
                    ,LU.ITEM_ID_CHILD AS C_ITEM_ID
                    ,LU.TO_EXPC_QTY AS CON_QTY
                    ,TO_CHAR(TO_DATE(LU.TO_YYYYMMDD,'YYYYMMDD') + 1,'YYYYMMDD') AS EFF_END_DATE
                    ,ITS.STAGE     AS P_STAGE
            FROM     SCP_OPMZ_VIRTUAL_BOM LU
                   , SCP_OPMZ_PLAN_GR_M PG
                   , SCP_OPT_ENG_ITEM_SITE_SN ITS
            WHERE    LU.OPMZ_PLAN_GR_ID = PG.OPMZ_PLAN_GR_ID
            AND ITS.PLAN_ID = V_PLAN_ID
            AND LU.ITEM_ID = ITS.ITEM_ID
            AND ITS.ITEM_CLASS_ID NOT IN ('DEMAND')
            AND ITS.STAGE NOT IN ('A_DEGAS','B_DEGAS','EOL','INSP')
            AND LU.PLANT_SITE_ID = ITS.SITE_ID
            AND      1 = 1
            AND      LU.DIVISION_ID       = V_DIVISION_ID
            AND      PG.OPMZ_PLAN_GR_NAME = V_GROUP_ID
            AND      PG.VALID_YN          = 'Y'
            AND      LU.VALID_YN          = 'Y'
            /*  END 2025.11.19 jongykim2: Schelduled Reciept Information */
            /* -- BLOCKED 2025.11.19 jongykim2
            SELECT   LU.SEGMENT4   AS SCM_SITE_ID
                    ,LU.SEGMENT5   AS P_ITEM_ID
                    ,LU.ATTRIBUTE1 AS C_ITEM_ID
                    ,LU.ATTRIBUTE2 AS CON_QTY
                    --,LU.ATTRIBUTE2 AS EFF_END_DATE
                    ,CONVERT(NVARCHAR(8),DATEADD(DAY,1,LU.ATTRIBUTE3),112) AS EFF_END_DATE
                    ,ITS.STAGE     AS P_STAGE
            FROM     SCP_OPMZ_LOOKUP_MASTER_DETAIL LU WITH(NOLOCK)
            INNER JOIN SCP_OPT_ENG_ITEM_SITE_SN ITS WITH(NOLOCK)
            ON  ITS.PLAN_ID = @V_PLAN_ID
            AND LU.SEGMENT5 = ITS.ITEM_ID
            AND ITS.ITEM_CLASS_ID NOT IN ('DEMAND')
            AND ITS.STAGE NOT IN ('A_DEGAS','B_DEGAS','EOL','INSP')
            AND LU.SEGMENT4 = ITS.SITE_ID
            WHERE    LU.LOOKUP_TYPE = 'SCP_OPT_ENG_CONST_PACKING_MATERIAL'
            AND      LU.VALID_YN    = 'Y'
            AND      LU.SEGMENT2    = @V_DIVISION_ID
            AND      LU.SEGMENT3    = @V_GROUP_ID */
            ) MC
        GROUP BY SCM_SITE_ID, C_ITEM_ID, EFF_END_DATE;

        INSERT INTO SCP_OPT_ENG_ROUTING_SN(PLAN_ID,ROUTING_ID,OP_SEQ,LEAD_TIME,YIELD,ATTRIBUTE1,ATTRIBUTE2,ATTRIBUTE3)
        SELECT V_PLAN_ID
              ,SCM_SITE_ID||'::'||C_ITEM_ID||'::'||'MATERIAL_CONST'||'::-::-' AS ROUTING_ID
              ,0                                                         AS OP_SEQ
              ,0                                                         AS LEAD_TIME
              ,1                                                         AS YIELD
              ,SCM_SITE_ID                                               AS ATTRIBUTE1
              ,C_ITEM_ID                                                 AS ATTRIBUTE2
              ,'MATERIAL_CONST'                                          AS ATTRIBUTE3
        FROM(
            /*  START 2025.11.19 jongykim2: Schelduled Reciept Information */
            SELECT   LU.PLANT_SITE_ID AS SCM_SITE_ID
                    ,LU.ITEM_ID AS P_ITEM_ID
                    ,LU.ITEM_ID_CHILD AS C_ITEM_ID
                    ,LU.TO_EXPC_QTY AS CON_QTY
                    ,TO_CHAR(TO_DATE(LU.TO_YYYYMMDD,'YYYYMMDD') + 1,'YYYYMMDD') AS EFF_END_DATE
            FROM     SCP_OPMZ_VIRTUAL_BOM LU
                   , SCP_OPMZ_PLAN_GR_M PG
            WHERE    LU.OPMZ_PLAN_GR_ID = PG.OPMZ_PLAN_GR_ID
            AND      1 = 1
            AND      LU.DIVISION_ID       = V_DIVISION_ID
            AND      PG.OPMZ_PLAN_GR_NAME = V_GROUP_ID
            AND      PG.VALID_YN          = 'Y'
            AND      LU.VALID_YN          = 'Y'
            /*  END 2025.11.19 jongykim2: Schelduled Reciept Information */
            /* -- BLOCKED 2025.11.19 jongykim2
            SELECT   LU.SEGMENT4   AS SCM_SITE_ID
                    ,LU.SEGMENT5   AS P_ITEM_ID
                    ,LU.ATTRIBUTE1   AS C_ITEM_ID
                    ,LU.ATTRIBUTE2 AS CON_QTY
                    --,LU.ATTRIBUTE2 AS EFF_END_DATE
                    ,CONVERT(NVARCHAR(8),DATEADD(DAY,1,LU.ATTRIBUTE3),112) AS EFF_END_DATE
            FROM     SCP_OPMZ_LOOKUP_MASTER_DETAIL LU WITH(NOLOCK)
            WHERE    LU.LOOKUP_TYPE = 'SCP_OPT_ENG_CONST_PACKING_MATERIAL'
            AND      LU.VALID_YN    = 'Y'
            AND      LU.SEGMENT2    = @V_DIVISION_ID
            AND      LU.SEGMENT3    = @V_GROUP_ID */
        ) MC
        GROUP BY SCM_SITE_ID, C_ITEM_ID;

        /*           ★MSSQL CONCAT 은 NULL 을 빈문자로 취급 -> Oracle 결합연산자와 동일하므로 ATTRIBUTE13 은 보호 불필요 */
        INSERT INTO SCP_OPT_ENG_BOM_SN (PLAN_ID,BOM_ID,OP_SEQ,MATERIAL_CLASS_ID,MATERIAL_BUFFER_ID,PRIORITY,CONSUME_QUANTITY,ATTRIBUTE1,ATTRIBUTE2,ATTRIBUTE3,ATTRIBUTE4,ATTRIBUTE13,ATTRIBUTE14,ATTRIBUTE15)
        SELECT V_PLAN_ID                                       AS PLAN_ID
              ,CASE WHEN P_ITEM_ID IS NULL OR STAGE_BUFFER IS NULL THEN NULL
                    ELSE SCM_SITE_ID||'::'||P_ITEM_ID||'::'||STAGE_BUFFER END AS BOM_ID
              ,0                                                AS OP_SEQ
              ,'MATERIAL_CONST'||RN                             AS MATERIAL_CLASS_ID
              ,SCM_SITE_ID||'::'||C_ITEM_ID||'::'||'MATERIAL_CONST' AS MATERIAL_BUFFER_ID
              ,1                                                AS PRIORITY
              ,CON_QTY                                          AS CONSUME_QUANTITY
              ,SCM_SITE_ID                                      AS ATTRIBUTE1
              ,P_ITEM_ID                                        AS ATTRIBUTE2
              ,P_STAGE                                          AS ATTRIBUTE3
              ,STAGE_BUFFER                                     AS ATTRIBUTE4
              ,'MATERIAL_CONST'||SUBSTR(STAGE_BUFFER, GREATEST(-2, -LENGTH(STAGE_BUFFER))) AS ATTRIBUTE13
              ,C_ITEM_ID                                        AS ATTRIBUTE14
              ,'MATERIAL_CONST'                                 AS ATTRIBUTE15
        FROM(
            /*  START 2025.11.19 jongykim2: Schelduled Reciept Information */
            SELECT   LU.PLANT_SITE_ID AS SCM_SITE_ID
                    ,LU.ITEM_ID AS P_ITEM_ID
                    ,LU.ITEM_ID_CHILD AS C_ITEM_ID
                    ,LU.TO_EXPC_QTY AS CON_QTY
                    ,LU.TO_YYYYMMDD AS EFF_END_DATE
                    ,ITS.STAGE     AS P_STAGE
                    ,ITS.GRADE     AS STAGE_BUFFER
                    ,TO_CHAR(ROW_NUMBER() OVER ( PARTITION BY LU.ITEM_ID   ORDER BY LU.ITEM_ID  )) AS RN
            FROM     SCP_OPMZ_VIRTUAL_BOM LU
                   , SCP_OPMZ_PLAN_GR_M PG
                   , SCP_OPT_ENG_ITEM_SITE_SN ITS
            WHERE    LU.OPMZ_PLAN_GR_ID = PG.OPMZ_PLAN_GR_ID
            AND ITS.PLAN_ID = V_PLAN_ID
            AND LU.ITEM_ID = ITS.ITEM_ID
            AND ITS.ITEM_CLASS_ID NOT IN ('DEMAND')
            AND ITS.STAGE NOT IN ('A_DEGAS','B_DEGAS','EOL','INSP')
            AND LU.PLANT_SITE_ID = ITS.SITE_ID
            AND      1 = 1
            AND      LU.DIVISION_ID       = V_DIVISION_ID
            AND      PG.OPMZ_PLAN_GR_NAME = V_GROUP_ID
            AND      LU.VALID_YN          = 'Y'
            AND      PG.VALID_YN          = 'Y'
            GROUP BY LU.PLANT_SITE_ID ,LU.ITEM_ID ,LU.ITEM_ID_CHILD,LU.TO_EXPC_QTY,LU.TO_YYYYMMDD,ITS.STAGE, ITS.GRADE
            /*  END 2025.11.19 jongykim2: Schelduled Reciept Information */
            /* -- BLOCKED 2025.11.19 jongykim2
            SELECT   LU.SEGMENT4   AS SCM_SITE_ID
                    ,LU.SEGMENT5   AS P_ITEM_ID
                    ,LU.ATTRIBUTE1 AS C_ITEM_ID
                    ,LU.ATTRIBUTE2 AS CON_QTY
                    ,LU.ATTRIBUTE3 AS EFF_END_DATE
                    ,ITS.STAGE     AS P_STAGE
                    ,ITS.GRADE     AS STAGE_BUFFER
                    ,CONVERT(NVARCHAR, ROW_NUMBER() OVER ( PARTITION BY LU.SEGMENT5   ORDER BY LU.SEGMENT5  )) AS ROWNUM
            FROM     SCP_OPMZ_LOOKUP_MASTER_DETAIL LU WITH(NOLOCK)
            INNER JOIN SCP_OPT_ENG_ITEM_SITE_SN ITS WITH(NOLOCK)
            ON  ITS.PLAN_ID = @V_PLAN_ID
            AND LU.SEGMENT5 = ITS.ITEM_ID
            AND ITS.ITEM_CLASS_ID NOT IN ('DEMAND')
            AND ITS.STAGE NOT IN ('A_DEGAS','B_DEGAS','EOL','INSP')
            AND LU.SEGMENT4 = ITS.SITE_ID
            WHERE    LU.LOOKUP_TYPE = 'SCP_OPT_ENG_CONST_PACKING_MATERIAL'
            AND      LU.VALID_YN    = 'Y'
            AND      LU.SEGMENT2    = @V_DIVISION_ID
            AND      LU.SEGMENT3    = @V_GROUP_ID
            GROUP BY LU.SEGMENT4  ,LU.SEGMENT5  ,LU.ATTRIBUTE1,LU.ATTRIBUTE2,LU.ATTRIBUTE3,ITS.STAGE, ITS.GRADE */
            ) MC;

        INSERT INTO SCP_OPT_ENG_ITEM_SITE_SN (PLAN_ID,BUFFER_ID,SITE_ID,ITEM_ID,GRADE,SITE_TYPE,ITEM_CLASS_ID,INCH,FAB,STAGE,IS_INFINITE,IS_PURCHASED,PURCHASE_PERIOD
                                             ,IS_NO_CARRY,STORAGE_ID,STORAGE_PER,SETUP_ID,SETUP_GROUP_ID,ITEM_GROUP_ID,ATTRIBUTE3)
        SELECT V_PLAN_ID                                       AS PLAN_ID
              ,SCM_SITE_ID||'::'||C_ITEM_ID||'::'||'MATERIAL_CONST' AS BUFFER_ID
              ,SCM_SITE_ID                                      AS SITE_ID
              ,C_ITEM_ID                                        AS ITEM_ID
              ,'MATERIAL_CONST'                                 AS GRADE
              ,NULL                                             AS SITE_TYPE
              ,'MATERIAL'                                       AS ITEM_CLASS_ID
              ,NULL                                             AS INCH
              ,NULL                                             AS FAB
              ,'M0'                                             AS STAGE
              ,NULL                                             AS IS_INFINITE
              ,NULL                                             AS IS_PURCHASED
              ,NULL                                             AS PURCHASE_PERIOD
              ,NULL                                             AS IS_NO_CARRY
              ,NULL                                             AS STORAGE_ID
              ,NULL                                             AS STORAGE_PER
              ,NULL                                             AS SETUP_ID
              ,NULL                                             AS SETUP_GROUP_ID
              ,NULL                                             AS ITEM_GROUP_ID
              ,'MATERIAL'                                       AS ATTRIBUTE3
        FROM(
            /*  START 2025.11.19 jongykim2: Schelduled Reciept Information */
            SELECT   LU.PLANT_SITE_ID AS SCM_SITE_ID
                    ,LU.ITEM_ID AS P_ITEM_ID
                    ,LU.ITEM_ID_CHILD AS C_ITEM_ID
                    ,LU.TO_EXPC_QTY AS CON_QTY
                    ,LU.TO_YYYYMMDD AS EFF_END_DATE
            FROM     SCP_OPMZ_VIRTUAL_BOM LU
                   , SCP_OPMZ_PLAN_GR_M PG
            WHERE    LU.OPMZ_PLAN_GR_ID = PG.OPMZ_PLAN_GR_ID
            AND      1 = 1
            AND      LU.DIVISION_ID       = V_DIVISION_ID
            AND      PG.OPMZ_PLAN_GR_NAME = V_GROUP_ID
            AND      PG.VALID_YN          = 'Y'
            AND      LU.VALID_YN          = 'Y'
            /*  END 2025.11.19 jongykim2: Schelduled Reciept Information */
            /* -- END 2025.11.19 jongykim2
            SELECT   LU.SEGMENT4   AS SCM_SITE_ID
                    ,LU.SEGMENT5   AS P_ITEM_ID
                    ,LU.ATTRIBUTE1 AS C_ITEM_ID
                    ,LU.ATTRIBUTE2 AS CON_QTY
                    ,LU.ATTRIBUTE3 AS EFF_END_DATE
            FROM     SCP_OPMZ_LOOKUP_MASTER_DETAIL LU WITH(NOLOCK)
            WHERE    LU.LOOKUP_TYPE = 'SCP_OPT_ENG_CONST_PACKING_MATERIAL'
            AND      LU.VALID_YN    = 'Y'
            AND      LU.SEGMENT2    = @V_DIVISION_ID
            AND      LU.SEGMENT3    = @V_GROUP_ID */
            ) MC
        GROUP BY SCM_SITE_ID, C_ITEM_ID;

        /* ---------------------------------------------------------------------- */
        /* MATERIAL CONSTRAINTS - BOM UPDATE IN ITEM_BOM_ROUTING */
        /*  (MSSQL UPDATE..FROM INNER JOIN -> 상관 UPDATE + EXISTS. */

        /* ---------------------------------------------------------------------- */
        UPDATE SCP_OPT_ENG_ITEM_BOM_ROUTING_SN IBR
           SET IBR.BOM_ID = IBR.BUFFER_ID
         WHERE IBR.PLAN_ID = V_PLAN_ID
         AND   IBR.BOM_ID IS NULL
         AND   EXISTS (
                   SELECT 1
                   FROM (
                        /*  START 2025.11.19 jongykim2: Schelduled Reciept Information */
                        SELECT  BOM.PLAN_ID AS PLAN_ID
                               ,BOM.BOM_ID  AS BOM_ID
                        FROM    SCP_OPMZ_VIRTUAL_BOM LU
                              , SCP_OPMZ_PLAN_GR_M PG
                              , SCP_OPT_ENG_BOM_SN BOM
                        WHERE   LU.OPMZ_PLAN_GR_ID  = PG.OPMZ_PLAN_GR_ID
                        AND     BOM.PLAN_ID            = V_PLAN_ID
                        AND     BOM.MATERIAL_CLASS_ID  = 'MATERIAL_CONST'
                        AND     LU.ITEM_ID             = BOM.ATTRIBUTE2
                        AND     LU.PLANT_SITE_ID       = BOM.ATTRIBUTE1
                        AND     1 = 1
                        AND     LU.DIVISION_ID       = V_DIVISION_ID
                        AND     PG.OPMZ_PLAN_GR_NAME = V_GROUP_ID
                        AND     PG.VALID_YN          = 'Y'
                        AND     LU.VALID_YN          = 'Y'
                        /*  END 2025.11.19 jongykim2: Schelduled Reciept Information */
                        /* -- BLOCKED 2025.11.19 jongykim2
                        SELECT  BOM.PLAN_ID
                               ,BOM.BOM_ID
                        FROM    SCP_OPMZ_LOOKUP_MASTER_DETAIL LU WITH(NOLOCK)
                                INNER JOIN SCP_OPT_ENG_BOM_SN BOM WITH(NOLOCK)
                                    ON   BOM.PLAN_ID            = @V_PLAN_ID
                                    AND  BOM.MATERIAL_CLASS_ID  = 'MATERIAL_CONST'
                                    AND  LU.SEGMENT5            = BOM.ATTRIBUTE2
                                    AND  LU.SEGMENT4            = BOM.ATTRIBUTE1
                        WHERE   LU.LOOKUP_TYPE = 'SCP_OPT_ENG_CONST_PACKING_MATERIAL'
                        AND     LU.VALID_YN    = 'Y'
                        AND     LU.SEGMENT2    = @V_DIVISION_ID
                        AND     LU.SEGMENT3    = @V_GROUP_ID */
                        ) PM
                   WHERE PM.PLAN_ID = IBR.PLAN_ID
                   AND   PM.BOM_ID  = IBR.BUFFER_ID );

        /* ---------------------------------------------------------------------- */
        /*  FIX 반영할 때 FIX의 수량*완성TACK(단위 : 초) 만큼 EVERY_CALENDAR에 반영 */
        /*  AFTER에서 ROUTING_RESOURCE의 LOAD PER 값을 수정하기 때문에 AFTER에서 진행 */
        /*  2025.07.17 Philsu Park: 81_UC에 맞게 Join 조건 변경. */
        /*  2025.09.12 Philsu Park: Fix Item에 해당하는 Load_Per 값을 사용하게 수정. */
        /*  (MSSQL WITH PROD_FIX + UPDATE..FROM -> Oracle 상관 UPDATE + EXISTS. PL/SQL 은 UPDATE 앞 WITH 불가라 */
        /*   공통테이블식을 인라인뷰로 전개. PROD_FIX 는 조인키 (RESOURCE_ID,STAGE,START_DATE) 로 유일) */
        /* ---------------------------------------------------------------------- */
        UPDATE SCP_OPT_ENG_RESOURCE_EVERY_CALENDAR_SN EC
           SET EC.DAILY_VALUE = ( SELECT CEIL(CASE WHEN FIX.FIXED_VAL > 86400 THEN 86400 ELSE FIX.FIXED_VAL END)
                                    FROM (
                                        SELECT  LK.SEGMENT5||'::'||LK.ATTRIBUTE1                AS RESOURCE_ID
                                                , CASE WHEN LK.SEGMENT4 = 'F6000' THEN 'EOL'
                                                       WHEN LK.SEGMENT4 = 'A9000' THEN 'ASSY'
                                                       WHEN LK.SEGMENT4 = 'A8000' THEN 'STK'
                                                       END    AS STAGE
                                                /*  ,LK.ATTRIBUTE2                   AS ITEM_ID */
                                                ,LK.ATTRIBUTE3                   AS START_DATE
                                                ,TO_CHAR(TO_DATE(LK.ATTRIBUTE3,'YYYYMMDD') + 1,'YYYYMMDD') AS END_DATE
                                                ,SUM(CAST(LK.ATTRIBUTE4 AS NUMBER(20,10))*RS.LOAD_PER) AS FIXED_VAL
                                        FROM    SCP_OPMZ_LOOKUP_MASTER_DETAIL LK
                                              , SCP_OPT_ENG_ROUTING_RESOURCE_SN RS
                                        WHERE   RS.PLAN_ID      = V_PLAN_ID
                                        AND     RS.RESOURCE_ID  = LK.SEGMENT5||'::'||LK.ATTRIBUTE1
                                        AND     RS.ATTRIBUTE2   = LK.ATTRIBUTE2
                                        AND     RS.START_DATE  <= LK.ATTRIBUTE3
                                        AND     RS.END_DATE    >= TO_CHAR(TO_DATE(LK.ATTRIBUTE3,'YYYYMMDD') + 1,'YYYYMMDD')
                                        AND     LK.LOOKUP_TYPE = 'SCP_OPT_ENG_PROD_FIX'
                                        AND     LK.SEGMENT2    = V_DIVISION_ID
                                        AND     LK.SEGMENT3    = V_GROUP_ID
                                        AND     LK.VALID_YN    = 'Y'
                                        GROUP BY LK.SEGMENT5, LK.ATTRIBUTE1, LK.ATTRIBUTE3
                                                , CASE WHEN LK.SEGMENT4 = 'F6000' THEN 'EOL'
                                                       WHEN LK.SEGMENT4 = 'A9000' THEN 'ASSY'
                                                       WHEN LK.SEGMENT4 = 'A8000' THEN 'STK'
                                                       END  /* , LK.ATTRIBUTE2 */
                                        ) FIX
                                   WHERE FIX.RESOURCE_ID = EC.RESOURCE_ID
                                   AND   FIX.STAGE       = EC.ATTRIBUTE3
                                   AND   FIX.START_DATE  = EC.START_DATE )
              ,EC.UPDATE_ID   = EC.UPDATE_ID || '_AFTER'
              ,EC.UPDATE_TIME = SYSDATE
         WHERE 1=1
         AND   EC.PLAN_ID        = V_PLAN_ID
         AND   EC.CALENDAR_LEVEL = 'L6'
         AND   EXISTS ( SELECT 1
                          FROM (
                              SELECT  LK.SEGMENT5||'::'||LK.ATTRIBUTE1                AS RESOURCE_ID
                                      , CASE WHEN LK.SEGMENT4 = 'F6000' THEN 'EOL'
                                             WHEN LK.SEGMENT4 = 'A9000' THEN 'ASSY'
                                             WHEN LK.SEGMENT4 = 'A8000' THEN 'STK'
                                             END    AS STAGE
                                      ,LK.ATTRIBUTE3                   AS START_DATE
                              FROM    SCP_OPMZ_LOOKUP_MASTER_DETAIL LK
                                    , SCP_OPT_ENG_ROUTING_RESOURCE_SN RS
                              WHERE   RS.PLAN_ID      = V_PLAN_ID
                              AND     RS.RESOURCE_ID  = LK.SEGMENT5||'::'||LK.ATTRIBUTE1
                              AND     RS.ATTRIBUTE2   = LK.ATTRIBUTE2
                              AND     RS.START_DATE  <= LK.ATTRIBUTE3
                              AND     RS.END_DATE    >= TO_CHAR(TO_DATE(LK.ATTRIBUTE3,'YYYYMMDD') + 1,'YYYYMMDD')
                              AND     LK.LOOKUP_TYPE = 'SCP_OPT_ENG_PROD_FIX'
                              AND     LK.SEGMENT2    = V_DIVISION_ID
                              AND     LK.SEGMENT3    = V_GROUP_ID
                              AND     LK.VALID_YN    = 'Y'
                              GROUP BY LK.SEGMENT5, LK.ATTRIBUTE1, LK.ATTRIBUTE3
                                      , CASE WHEN LK.SEGMENT4 = 'F6000' THEN 'EOL'
                                             WHEN LK.SEGMENT4 = 'A9000' THEN 'ASSY'
                                             WHEN LK.SEGMENT4 = 'A8000' THEN 'STK'
                                             END
                              ) FIX
                         WHERE FIX.RESOURCE_ID = EC.RESOURCE_ID
                         AND   FIX.STAGE       = EC.ATTRIBUTE3
                         AND   FIX.START_DATE  = EC.START_DATE );

        /* ---------------------------------------------------------------------- */
        /*  (MSSQL UPDATE..FROM EC + RS + FIX -> 상관 UPDATE + EXISTS) */

        /* ---------------------------------------------------------------------- */
        UPDATE  SCP_OPT_ENG_RESOURCE_EVERY_CALENDAR_SN EC
        SET     EC.DAILY_VALUE = ( SELECT CEIL(CASE WHEN FIX.FIX_QTY*RS.LOAD_PER > 86400 THEN 86400 ELSE FIX.FIX_QTY*RS.LOAD_PER END)
                                     FROM SCP_OPT_ENG_ROUTING_RESOURCE_SN RS
                                        , (
                                          SELECT  CASE WHEN SEGMENT4 = 'F6000' THEN 'EOL'
                                                       WHEN SEGMENT4 = 'A9000' THEN 'ASSY'
                                                       WHEN SEGMENT4 = 'A8000' THEN 'STK'
                                                       END    AS STAGE
                                                  ,SEGMENT5   AS SITE_ID
                                                  ,ATTRIBUTE1 AS LINE_ID
                                                  ,ATTRIBUTE2 AS ITEM_ID
                                                 ,ATTRIBUTE3                   AS FIX_DATE
                                                 ,SUM(TRUNC(TO_NUMBER(ATTRIBUTE4))) AS FIX_QTY
                                          FROM    SCP_OPMZ_LOOKUP_MASTER_DETAIL
                                          WHERE   LOOKUP_TYPE = 'SCP_OPT_ENG_PROD_FIX'
                                          AND     SEGMENT2    = V_DIVISION_ID
                                          AND     SEGMENT3    = V_GROUP_ID
                                          AND     VALID_YN    = 'Y'
                                          GROUP BY SEGMENT4, SEGMENT5, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3
                                          ) FIX
                                    WHERE RS.PLAN_ID     = EC.PLAN_ID
                                    AND   RS.RESOURCE_ID = EC.RESOURCE_ID
                                    AND   EC.START_DATE >= RS.START_DATE
                                    AND   EC.END_DATE   <= RS.END_DATE
                                    AND   FIX.SITE_ID    = EC.ATTRIBUTE1
                                    AND   FIX.ITEM_ID    = EC.ATTRIBUTE2
                                    AND   FIX.STAGE      = EC.ATTRIBUTE3
                                    AND   FIX.LINE_ID    = EC.ATTRIBUTE15
                                    AND   EC.START_DATE  = FIX.FIX_DATE )
               ,EC.UPDATE_ID   = EC.UPDATE_ID || '_AFTER'
               ,EC.UPDATE_TIME = SYSDATE
        WHERE   1=1
        AND     EC.PLAN_ID= V_PLAN_ID
        AND     EC.CALENDAR_LEVEL = 'L6'
        AND     EXISTS ( SELECT 1
                           FROM SCP_OPT_ENG_ROUTING_RESOURCE_SN RS
                              , (
                                SELECT  CASE WHEN SEGMENT4 = 'F6000' THEN 'EOL'
                                             WHEN SEGMENT4 = 'A9000' THEN 'ASSY'
                                             WHEN SEGMENT4 = 'A8000' THEN 'STK'
                                             END    AS STAGE
                                        ,SEGMENT5   AS SITE_ID
                                        ,ATTRIBUTE1 AS LINE_ID
                                        ,ATTRIBUTE2 AS ITEM_ID
                                       ,ATTRIBUTE3  AS FIX_DATE
                                FROM    SCP_OPMZ_LOOKUP_MASTER_DETAIL
                                WHERE   LOOKUP_TYPE = 'SCP_OPT_ENG_PROD_FIX'
                                AND     SEGMENT2    = V_DIVISION_ID
                                AND     SEGMENT3    = V_GROUP_ID
                                AND     VALID_YN    = 'Y'
                                GROUP BY SEGMENT4, SEGMENT5, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3
                                ) FIX
                          WHERE RS.PLAN_ID     = EC.PLAN_ID
                          AND   RS.RESOURCE_ID = EC.RESOURCE_ID
                          AND   EC.START_DATE >= RS.START_DATE
                          AND   EC.END_DATE   <= RS.END_DATE
                          AND   FIX.SITE_ID    = EC.ATTRIBUTE1
                          AND   FIX.ITEM_ID    = EC.ATTRIBUTE2
                          AND   FIX.STAGE      = EC.ATTRIBUTE3
                          AND   FIX.LINE_ID    = EC.ATTRIBUTE15
                          AND   EC.START_DATE  = FIX.FIX_DATE );

        /* ---------------------------------------------------------------------- */
        /*  LINE FULL LOADING 조치 전에 미리 비조업을 담아둠 -> 호기 별  FULL LOADING에서 사용 */
        /*  (MSSQL @NO_WORK_TEMP 테이블변수 -> GTT GT_OPT_ENG_GMAC_NOWORK, 진입부 DELETE 로 초기화) */
        /* ---------------------------------------------------------------------- */
        DELETE FROM GT_OPT_ENG_GMAC_NOWORK;

        INSERT INTO GT_OPT_ENG_GMAC_NOWORK (START_DATE, STAGE)
        SELECT  CAL.BASIS_YYYYMMDD
               ,RE.STAGE
        FROM    SCP_OPT_ENG_RESOURCE_EVERY_CALENDAR_SN REC
              , SCP_OPT_ENG_RESOURCE_SN RE
              , SCM_SYS_CALENDAR_M CAL
        WHERE   REC.PLAN_ID        = RE.PLAN_ID
        AND     REC.RESOURCE_ID    = RE.RESOURCE_ID
        AND     CAL.BASIS_YYYYMMDD >= REC.START_DATE
        AND     CAL.BASIS_YYYYMMDD <  REC.END_DATE
        AND     REC.PLAN_ID        = V_PLAN_ID
        AND     REC.TYPE           = 'upper_limit'
        AND     REC.CALENDAR_LEVEL = 'L5'
        /* AND     REC.DAILY_VALUE    = 0 */
        AND     CAST(REC.DAILY_VALUE AS NUMBER(20,3))    = 0
        GROUP BY CAL.BASIS_YYYYMMDD, RE.STAGE;

        /* ---------------------------------------------------------------------- */
        /*  LINE FULL LOADING */
        /*  2025-07-29 THK : EVERY CALENDAR 조정 및 HORIZEN_CALENDAR, FROZEN PLAN INSERT */
        /*  (MSSQL @FL_EC_TEMP 테이블변수 -> GTT GT_OPT_ENG_GMAC_FLEC, 진입부 DELETE 로 초기화) */
        /* ---------------------------------------------------------------------- */
        DELETE FROM GT_OPT_ENG_GMAC_FLEC;

        INSERT INTO GT_OPT_ENG_GMAC_FLEC (PLAN_ID,RESOURCE_ID,STAGE,TYPE,START_DATE,DAILY_VALUE,CALENDAR_LEVEL,SCM_SITE_ID,LINE_ID)
        SELECT  EC.PLAN_ID         AS PLAN_ID
               ,EC.RESOURCE_ID     AS RESOURCE_ID
               ,RS.STAGE           AS STAGE
               ,EC.TYPE            AS TYPE
               ,CAL.BASIS_YYYYMMDD AS START_DATE
               ,EC.DAILY_VALUE     AS DAILY_VALUE
               ,EC.CALENDAR_LEVEL  AS CALENDAR_LEVEL
               ,EC.ATTRIBUTE1      AS SCM_SITE_ID
               ,EC.ATTRIBUTE15     AS LINE_ID
        FROM    SCP_OPT_ENG_RESOURCE_EVERY_CALENDAR_SN EC
              , SCP_OPT_ENG_RESOURCE_SN RS
              , SCM_SYS_CALENDAR_M CAL
              , SCP_OPMZ_LOOKUP_MASTER_DETAIL LU
        WHERE   EC.PLAN_ID         = RS.PLAN_ID
        AND     EC.RESOURCE_ID     = RS.RESOURCE_ID
        AND     CAL.BASIS_YYYYMMDD >= EC.START_DATE
        AND     CAL.BASIS_YYYYMMDD <  EC.END_DATE
        AND     LU.LOOKUP_TYPE     = 'SCP_OPT_ENG_GM_FULL_LOADING_LINE'
        AND     LU.SEGMENT1        = V_DIVISION_ID
        AND     LU.SEGMENT2        = V_GROUP_ID
        AND     RS.SITE_ID         = LU.SEGMENT3
        AND     RS.STAGE           = LU.SEGMENT4
        AND     LU.VALID_YN        = 'Y'
        AND     EC.PLAN_ID = V_PLAN_ID
        ORDER BY CAL.BASIS_YYYYMMDD, EC.TYPE, EC.ATTRIBUTE15;

        /* UPPER 기준 MAX LEVEL의 값을 가져와서 L7 UPPER 추가 */
        INSERT INTO GT_OPT_ENG_GMAC_FLEC (PLAN_ID,RESOURCE_ID,STAGE,TYPE,START_DATE,DAILY_VALUE,CALENDAR_LEVEL,SCM_SITE_ID,LINE_ID)
        SELECT MEC.PLAN_ID     AS PLAN_ID
              ,MEC.RESOURCE_ID AS RESOURCE_ID
              ,MEC.STAGE       AS STAGE
              ,MEC.TYPE        AS TYPE
              ,MEC.START_DATE  AS START_DATE
              ,VEC.DAILY_VALUE AS DAILY_VALUE
              ,'L7'            AS CALENDAR_LEVEL
              ,MEC.SCM_SITE_ID AS SCM_SITE_ID
              ,MEC.LINE_ID     AS LINE_ID
        FROM(
             SELECT PLAN_ID
                   ,RESOURCE_ID
                   ,STAGE
                   ,TYPE
                   ,START_DATE
                   ,MAX(CALENDAR_LEVEL) AS MAX_CALENDAR_LEVEL
                   ,SCM_SITE_ID
                   ,LINE_ID
             FROM GT_OPT_ENG_GMAC_FLEC
             WHERE TYPE = 'upper_limit'
             GROUP BY PLAN_ID, RESOURCE_ID, STAGE, TYPE, START_DATE, SCM_SITE_ID, LINE_ID
             ) MEC
              , GT_OPT_ENG_GMAC_FLEC VEC
        WHERE   MEC.PLAN_ID            = VEC.PLAN_ID
        AND     MEC.RESOURCE_ID        = VEC.RESOURCE_ID
        AND     MEC.STAGE              = VEC.STAGE
        AND     MEC.TYPE               = VEC.TYPE
        AND     MEC.START_DATE         = VEC.START_DATE
        AND     MEC.MAX_CALENDAR_LEVEL = VEC.CALENDAR_LEVEL
        AND     MEC.SCM_SITE_ID        = VEC.SCM_SITE_ID
        AND     MEC.LINE_ID            = VEC.LINE_ID;

        /* L7의 UPPER에 LOOKUP MARGIN 값을 곱해서 lower_limit L7 생성 */
        INSERT INTO GT_OPT_ENG_GMAC_FLEC (PLAN_ID,RESOURCE_ID,STAGE,TYPE,START_DATE,DAILY_VALUE,CALENDAR_LEVEL,SCM_SITE_ID,LINE_ID)
        SELECT EC.PLAN_ID
              ,EC.RESOURCE_ID
              ,EC.STAGE
              ,'lower_limit'
              ,EC.START_DATE
              ,CAST(EC.DAILY_VALUE AS NUMBER(20,3))*CAST(LU.ATTRIBUTE1 AS NUMBER(20,3))/100 AS DAILY_VALUE
              ,EC.CALENDAR_LEVEL
              ,EC.SCM_SITE_ID
              ,EC.LINE_ID
        FROM   GT_OPT_ENG_GMAC_FLEC EC
             , SCP_OPMZ_LOOKUP_MASTER_DETAIL LU
        WHERE  LU.LOOKUP_TYPE = 'SCP_OPT_ENG_GM_FULL_LOADING_LINE'
        AND    LU.SEGMENT1    = V_DIVISION_ID
        AND    LU.SEGMENT2    = V_GROUP_ID
        AND    EC.SCM_SITE_ID = LU.SEGMENT3
        AND    EC.STAGE       = LU.SEGMENT4
        AND    LU.VALID_YN    = 'Y'
        AND    EC.CALENDAR_LEVEL = 'L7';

        /* FROZEN구간과 FIX가 포함되어있는 날짜에 대해서는 L9,lower_limit 0으로 생성 */
        INSERT INTO GT_OPT_ENG_GMAC_FLEC (PLAN_ID,RESOURCE_ID,STAGE,TYPE,START_DATE,DAILY_VALUE,CALENDAR_LEVEL,SCM_SITE_ID,LINE_ID)
        SELECT REC.PLAN_ID         AS PLAN_ID
              ,REC.RESOURCE_ID     AS RESOURCE_ID
              ,RE.STAGE            AS STAGE
              ,'lower_limit'       AS TYPE
              ,CAL.BASIS_YYYYMMDD  AS START_DATE
              ,'0'                 AS DAILY_VALUE
              ,'L9'                AS CALENDAR_LEVEL
              ,REC.ATTRIBUTE1      AS SCM_SITE_ID
              ,REC.ATTRIBUTE15     AS LINE_ID
        FROM SCP_OPT_ENG_RESOURCE_EVERY_CALENDAR_SN REC
           , SCP_OPT_ENG_RESOURCE_SN RE
           , SCP_OPT_ENG_FROZEN_MASTER_SN FM
           , SCP_OPMZ_LOOKUP_MASTER_DETAIL LU
           , SCM_SYS_CALENDAR_M CAL
        WHERE   REC.PLAN_ID = RE.PLAN_ID
        AND     REC.RESOURCE_ID = RE.RESOURCE_ID
        AND     REC.PLAN_ID = FM.PLAN_ID
        AND     RE.STAGE    = FM.STAGE
        AND     FM.FROZEN_TYPE = 'PROD'
        AND     LU.LOOKUP_TYPE = 'SCP_OPT_ENG_GM_FULL_LOADING_LINE'
        AND     LU.SEGMENT1    = V_DIVISION_ID
        AND     LU.SEGMENT2    = V_GROUP_ID
        AND     RE.SITE_ID     = LU.SEGMENT3
        AND     RE.STAGE       = LU.SEGMENT4
        AND     LU.VALID_YN    = 'Y'
        AND     CAL.BASIS_YYYYMMDD >= FM.FROZEN_START_DATE
        AND     CAL.BASIS_YYYYMMDD < FM.FROZEN_END_DATE
        AND     CAL.BASIS_YYYYMMDD >= REC.START_DATE
        AND     CAL.BASIS_YYYYMMDD <  REC.END_DATE
        AND     REC.PLAN_ID = V_PLAN_ID
        AND     RE.RESOURCE_TYPE = 'LINE'
        AND     REC.TYPE = 'lower_limit'
        GROUP BY REC.PLAN_ID, REC.RESOURCE_ID, RE.STAGE , REC.TYPE, CAL.BASIS_YYYYMMDD, REC.ATTRIBUTE1, REC.ATTRIBUTE15
        UNION ALL
        SELECT REC.PLAN_ID         AS PLAN_ID
              ,REC.RESOURCE_ID     AS RESOURCE_ID
              ,RE.STAGE            AS STAGE
              ,'lower_limit'       AS TYPE
              ,CAL.BASIS_YYYYMMDD  AS START_DATE
              ,'0'                 AS DAILY_VALUE
              ,'L9'                AS CALENDAR_LEVEL
              ,REC.ATTRIBUTE1      AS SCM_SITE_ID
              ,REC.ATTRIBUTE15     AS LINE_ID
        FROM SCP_OPT_ENG_RESOURCE_EVERY_CALENDAR_SN REC
           , SCP_OPT_ENG_RESOURCE_SN RE
           , (
                        SELECT  CASE WHEN SEGMENT4 = 'F6000' THEN 'EOL'
                                     WHEN SEGMENT4 = 'A9000' THEN 'ASSY'
                                     WHEN SEGMENT4 = 'A8000' THEN 'STK'
                                     END    AS STAGE
                                ,SEGMENT5   AS SITE_ID
                                ,ATTRIBUTE1 AS LINE_ID
                               ,ATTRIBUTE3                   AS FIX_DATE
                               ,SUM(TRUNC(TO_NUMBER(ATTRIBUTE4))) AS FIX_QTY
                        FROM    SCP_OPMZ_LOOKUP_MASTER_DETAIL
                        WHERE   LOOKUP_TYPE = 'SCP_OPT_ENG_PROD_FIX'
                        AND     SEGMENT2    = V_DIVISION_ID
                        AND     SEGMENT3    = V_GROUP_ID
                        AND     VALID_YN    = 'Y'
                        GROUP BY SEGMENT4, SEGMENT5, ATTRIBUTE1, ATTRIBUTE3
                       ) FIX
           , SCP_OPMZ_LOOKUP_MASTER_DETAIL LU
           , SCM_SYS_CALENDAR_M CAL
        WHERE   REC.PLAN_ID = RE.PLAN_ID
        AND     REC.RESOURCE_ID = RE.RESOURCE_ID
        AND     FIX.SITE_ID     = RE.ATTRIBUTE1
        AND     FIX.STAGE       = RE.ATTRIBUTE3
        AND     FIX.LINE_ID     = RE.ATTRIBUTE15
        AND     REC.START_DATE  = FIX.FIX_DATE
        AND     LU.LOOKUP_TYPE = 'SCP_OPT_ENG_GM_FULL_LOADING_LINE'
        AND     LU.SEGMENT1    = V_DIVISION_ID
        AND     LU.SEGMENT2    = V_GROUP_ID
        AND     RE.SITE_ID     = LU.SEGMENT3
        AND     RE.STAGE       = LU.SEGMENT4
        AND     LU.VALID_YN    = 'Y'
        AND     CAL.BASIS_YYYYMMDD =  FIX.FIX_DATE
        AND     CAL.BASIS_YYYYMMDD >= REC.START_DATE
        AND     CAL.BASIS_YYYYMMDD <  REC.END_DATE
        AND     REC.PLAN_ID = V_PLAN_ID
        AND     RE.RESOURCE_TYPE = 'LINE'
        AND     REC.TYPE = 'lower_limit'
        GROUP BY REC.PLAN_ID, REC.RESOURCE_ID, RE.STAGE , REC.TYPE, CAL.BASIS_YYYYMMDD, REC.ATTRIBUTE1, REC.ATTRIBUTE15;

        /*  FROZEN구간을 제외하고 값이 0인 날짜는 HORIZEN CALENDAR로 이동 */
        INSERT INTO SCP_OPT_ENG_RESOURCE_HORIZON_CALENDAR_SN(PLAN_ID
                                                            ,RESOURCE_ID
                                                            ,TYPE
                                                            ,START_DATE
                                                            ,END_DATE
                                                            ,VALUE
                                                            ,ATTRIBUTE15
                                                            )
        SELECT REC.PLAN_ID
              ,REC.RESOURCE_ID
              ,REC.TYPE
              ,REC.START_DATE
              ,REC.END_DATE
              ,REC.DAILY_VALUE
              ,REC.ATTRIBUTE15
        FROM(
            SELECT PLAN_ID         AS PLAN_ID
                  ,RESOURCE_ID     AS RESOURCE_ID
                  ,STAGE           AS STAGE
                  ,TYPE            AS TYPE
                  ,MIN(START_DATE) AS START_DATE
                  /* ,MAX(START_DATE) AS END_DATE */
                  ,TO_CHAR(TO_DATE(MAX(START_DATE),'YYYYMMDD') + 1,'YYYYMMDD') AS END_DATE
                  ,DAILY_VALUE     AS DAILY_VALUE
                  ,'FULL_LOADING'  AS ATTRIBUTE15
            FROM(
                SELECT PLAN_ID
                      ,RESOURCE_ID
                      ,STAGE
                      ,TYPE
                      ,START_DATE
                      ,DAILY_VALUE
                      ,TO_DATE(START_DATE,'YYYYMMDD') - RN AS GRP
                FROM(
                    SELECT PLAN_ID
                          ,RESOURCE_ID
                          ,STAGE
                          ,TYPE
                          ,START_DATE
                          ,DAILY_VALUE
                          ,ROW_NUMBER() OVER(PARTITION BY RESOURCE_ID, TYPE ORDER BY START_DATE) AS RN
                    FROM   GT_OPT_ENG_GMAC_FLEC
                    WHERE  CALENDAR_LEVEL = 'L7'
                    AND    TYPE           = 'upper_limit'
                    AND    CAST(DAILY_VALUE AS NUMBER(20,3))   = 0
                    ) FEC
                ) GEC
            GROUP BY PLAN_ID, RESOURCE_ID, TYPE, DAILY_VALUE, GRP, STAGE
            ) REC
          , SCP_OPT_ENG_FROZEN_MASTER_SN FM
        WHERE REC.PLAN_ID    = FM.PLAN_ID
        AND   REC.STAGE      = FM.STAGE
        AND   FM.FROZEN_TYPE = 'PROD'
        AND   REC.START_DATE >= FM.FROZEN_END_DATE;

         /* FROZEN구간을 제외하고 값이 0인 날짜에 FROZEN PLAN을 86400/LOAD_PER -> 100을 넣어줌 */
        INSERT INTO SCP_OPT_ENG_FROZEN_PLAN_SN(PLAN_ID
                                              ,FROZEN_ID
                                              ,ROUTING_BOM_MAPPING_ID
                                              ,OP_SEQ
                                              ,RESOURCE_ID
                                              ,QUANTITY
                                              ,EFFECTIVE_DATE
                                              ,ATTRIBUTE1
                                              ,ATTRIBUTE2
                                              ,ATTRIBUTE3
        )
        SELECT  FE.PLAN_ID                         AS PLAN_ID
               ,CASE WHEN FE.RESOURCE_ID IS NULL OR FE.START_DATE IS NULL THEN NULL
                     ELSE FE.RESOURCE_ID||'::'||FE.START_DATE END           AS FROZEN_ID
               ,CASE WHEN FE.SCM_SITE_ID IS NULL THEN NULL
                     ELSE 'RB'||FE.SCM_SITE_ID||'::IDLE::IDLE' END          AS ROUTING_BOM_MAPPING_ID
               ,0                                  AS OP_SEQ
               ,FE.RESOURCE_ID                     AS RESOURCE_ID
               ,86400/RR.LOAD_PER                  AS QUANTITY
               ,FE.START_DATE                      AS EFFECTIVE_DATE
               ,FE.SCM_SITE_ID                     AS ATTRIBUTE1
               ,'IDLE'                             AS ATTRIBUTE2
               ,'IDLE'                             AS ATTRIBUTE3
        FROM    GT_OPT_ENG_GMAC_FLEC FE
              , SCP_OPT_ENG_ROUTING_RESOURCE_SN RR
              , SCP_OPT_ENG_FROZEN_MASTER_SN FM
        WHERE   FE.PLAN_ID = RR.PLAN_ID
        AND     CASE WHEN FE.SCM_SITE_ID IS NULL THEN NULL ELSE FE.SCM_SITE_ID||'::IDLE::IDLE' END = RR.ROUTING_ID
        AND     FE.RESOURCE_ID = RR.RESOURCE_ID
        AND     FE.PLAN_ID     = FM.PLAN_ID
        AND     FE.STAGE       = FM.STAGE
        AND     FM.FROZEN_TYPE = 'PROD'
        AND     1=1
        /*  AND     FE.CALENDAR_LEVEL = 'L7' */
        AND     FE.CALENDAR_LEVEL = 'L5'
        AND     CAST(FE.DAILY_VALUE AS NUMBER(20,3))    = 0
        AND     FE.TYPE           = 'upper_limit'
        AND     FE.START_DATE >= FM.FROZEN_END_DATE;

        /* L7 값이 0인 데이터는 삭제 */
        /*  (MSSQL DELETE..FROM INNER JOIN -> DELETE + EXISTS) */
        DELETE FROM GT_OPT_ENG_GMAC_FLEC FE
         WHERE FE.CALENDAR_LEVEL != 'L9'
         AND   EXISTS (
                   SELECT 1
                   FROM    GT_OPT_ENG_GMAC_FLEC DEL
                   WHERE   DEL.CALENDAR_LEVEL = 'L7'
                   AND     CAST(DEL.DAILY_VALUE AS NUMBER(20,3)) = 0
                   AND     DEL.RESOURCE_ID = FE.RESOURCE_ID
                   AND     DEL.START_DATE  = FE.START_DATE );

        /* 기존 데이터 삭제하고 다시 INSERT */
        /*  (MSSQL DELETE..FROM INNER JOIN -> DELETE + EXISTS) */
        DELETE FROM SCP_OPT_ENG_RESOURCE_EVERY_CALENDAR_SN EC
         WHERE EC.PLAN_ID = V_PLAN_ID
         AND   EXISTS (
                   SELECT 1
                   FROM SCP_OPT_ENG_RESOURCE_SN RS
                      , SCP_OPMZ_LOOKUP_MASTER_DETAIL LU
                   WHERE LU.LOOKUP_TYPE = 'SCP_OPT_ENG_GM_FULL_LOADING_LINE'
                   AND   LU.SEGMENT1    = V_DIVISION_ID
                   AND   LU.SEGMENT2    = V_GROUP_ID
                   AND   RS.SITE_ID     = LU.SEGMENT3
                   AND   RS.STAGE       = LU.SEGMENT4
                   AND   LU.VALID_YN    = 'Y'
                   AND   RS.PLAN_ID = EC.PLAN_ID
                   AND   RS.RESOURCE_ID = EC.RESOURCE_ID );

        INSERT INTO SCP_OPT_ENG_RESOURCE_EVERY_CALENDAR_SN(PLAN_ID
