        /*  (MSSQL SELECT TOP 100 ROW_NUMBER() ... FROM sys.objects 숫자생성 -> CONNECT BY LEVEL 로 대체) */
        DELETE FROM GT_OPT_ENG_GMAC_FLEQ2;

        INSERT INTO GT_OPT_ENG_GMAC_FLEQ2 (PLAN_ID,RESOURCE_ID,STAGE,TYPE,START_DATE,DAILY_VALUE,CALENDAR_LEVEL,SCM_SITE_ID,LINE_ID,ORI_LINE_ID,FULL_DAYS)
        SELECT  EC.PLAN_ID
               ,EC.RESOURCE_ID
               ,'STK'
               ,EC.TYPE
               ,CAL.BASIS_YYYYMMDD AS START_DATE
               ,EC.DAILY_VALUE
               ,EC.CALANDER_LEVEL
               ,EC.ATTRIBUTE1
               ,EC.ATTRIBUTE15
               ,EC.ORI_LINE_ID
               ,EC.FULL_DAYS
        FROM(
            SELECT V_PLAN_ID                                                    AS PLAN_ID
                  ,CASE WHEN RR.SITE_ID IS NULL OR RR.LINE_ID IS NULL OR LU.EQ_QTY IS NULL OR RR.BUFFER_STAGE IS NULL THEN NULL
                        ELSE RR.SITE_ID||'::'||RR.LINE_ID||'_'||LU.EQ_QTY||'@'||RR.BUFFER_STAGE END AS RESOURCE_ID
                  ,'upper_limit'                                                AS TYPE
                  ,V_PLAN_START_YYYYMMDD                                        AS START_DATE
                  ,V_PLAN_END_YYYYMMDD                                          AS END_DATE
                  ,86400                                                        AS DAILY_VALUE
                  ,'L0'                                                         AS CALANDER_LEVEL
                  ,RR.SITE_ID                                                   AS ATTRIBUTE1
                  ,CASE WHEN RR.LINE_ID IS NULL OR LU.EQ_QTY IS NULL THEN NULL
                        ELSE RR.LINE_ID||'_'||LU.EQ_QTY END                     AS ATTRIBUTE15
                  ,RR.LINE_ID                                                   AS ORI_LINE_ID
                  ,LU.FULL_DAYS                                                 AS FULL_DAYS
            FROM(
                SELECT  ATTRIBUTE1  AS SITE_ID
                       ,ATTRIBUTE15 AS LINE_ID
                       ,ATTRIBUTE3  AS STAGE
                       ,ATTRIBUTE4  AS BUFFER_STAGE
                FROM    SCP_OPT_ENG_ROUTING_RESOURCE_SN
                WHERE   PLAN_ID= V_PLAN_ID
                AND     RESOURCE_CLASS_ID = 'LINE'
                GROUP BY ATTRIBUTE1, ATTRIBUTE15, ATTRIBUTE3, ATTRIBUTE4
                ) RR
                     , (
                          SELECT LU.SEGMENT1   AS DIVISION_ID
                                ,LU.SEGMENT2   AS GROUP_ID
                                ,LU.SEGMENT3   AS SITE_ID
                                ,LU.SEGMENT4   AS STAGE
                                ,TO_CHAR(NUM.NUM) AS EQ_QTY
                                ,LU.ATTRIBUTE2 AS MARGIN
                                ,LU.ATTRIBUTE3 AS FULL_DAYS
                          FROM(
                              SELECT  LEVEL AS NUM
                              FROM    DUAL
                              CONNECT BY LEVEL <= 100
                              ) NUM
                            , SCP_OPMZ_LOOKUP_MASTER_DETAIL LU
                          WHERE LU.LOOKUP_TYPE = 'SCP_OPT_ENG_GM_FULL_LOADING_EQ'
                                AND LU.VALID_YN = 'Y'
                                AND NUM.NUM <= LU.ATTRIBUTE1
                                AND LU.SEGMENT1    = V_DIVISION_ID
                                AND LU.SEGMENT2    = V_GROUP_ID
                         ) LU
                   WHERE RR.SITE_ID = LU.SITE_ID
                    AND  RR.STAGE   = LU.STAGE
            UNION ALL
            SELECT V_PLAN_ID                                                    AS PLAN_ID
                  ,CASE WHEN RR.SITE_ID IS NULL OR RR.LINE_ID IS NULL OR LU.EQ_QTY IS NULL OR RR.BUFFER_STAGE IS NULL THEN NULL
                        ELSE RR.SITE_ID||'::'||RR.LINE_ID||'_'||LU.EQ_QTY||'@'||RR.BUFFER_STAGE END AS RESOURCE_ID
                  ,'lower_limit'                                                AS TYPE
                  ,V_PLAN_START_YYYYMMDD                                        AS START_DATE
                  ,V_PLAN_END_YYYYMMDD                                          AS END_DATE
                  ,86400                                                        AS DAILY_VALUE
                  ,'L0'                                                         AS CALANDER_LEVEL
                  ,RR.SITE_ID                                                   AS ATTRIBUTE1
                  ,CASE WHEN RR.LINE_ID IS NULL OR LU.EQ_QTY IS NULL THEN NULL
                        ELSE RR.LINE_ID||'_'||LU.EQ_QTY END                     AS ATTRIBUTE15
                  ,RR.LINE_ID                                                   AS ORI_LINE_ID
                  ,LU.FULL_DAYS                                                 AS FULL_DAYS
            FROM(
                SELECT  ATTRIBUTE1  AS SITE_ID
                       ,ATTRIBUTE15 AS LINE_ID
                       ,ATTRIBUTE3  AS STAGE
                       ,ATTRIBUTE4  AS BUFFER_STAGE
                FROM    SCP_OPT_ENG_ROUTING_RESOURCE_SN
                WHERE   PLAN_ID= V_PLAN_ID
                AND     RESOURCE_CLASS_ID = 'LINE'
                GROUP BY ATTRIBUTE1, ATTRIBUTE15, ATTRIBUTE3, ATTRIBUTE4
                ) RR
                     , (
                          SELECT LU.SEGMENT1   AS DIVISION_ID
                                ,LU.SEGMENT2   AS GROUP_ID
                                ,LU.SEGMENT3   AS SITE_ID
                                ,LU.SEGMENT4   AS STAGE
                                ,TO_CHAR(NUM.NUM) AS EQ_QTY
                                ,LU.ATTRIBUTE2 AS MARGIN
                                ,LU.ATTRIBUTE3 AS FULL_DAYS
                          FROM(
                              SELECT  LEVEL AS NUM
                              FROM    DUAL
                              CONNECT BY LEVEL <= 100
                              ) NUM
                            , SCP_OPMZ_LOOKUP_MASTER_DETAIL LU
                          WHERE LU.LOOKUP_TYPE = 'SCP_OPT_ENG_GM_FULL_LOADING_EQ'
                                AND LU.VALID_YN = 'Y'
                                AND NUM.NUM <= LU.ATTRIBUTE1
                                AND LU.SEGMENT1    = V_DIVISION_ID
                                AND LU.SEGMENT2    = V_GROUP_ID
                         ) LU
                   WHERE RR.SITE_ID = LU.SITE_ID
                    AND  RR.STAGE   = LU.STAGE
            )EC
              , SCP_OPT_ENG_RESOURCE_SN RS
              , SCM_SYS_CALENDAR_M CAL
        WHERE   EC.PLAN_ID = RS.PLAN_ID
        AND     EC.RESOURCE_ID = RS.RESOURCE_ID
        AND     CAL.BASIS_YYYYMMDD >= EC.START_DATE
        AND     CAL.BASIS_YYYYMMDD <  EC.END_DATE;

        /* FULL_DAYS 이전 일자에 대해서만 FROZEN 구간과 FIX 구간에 대해서 L9생성, FULL_DAYS 이후 일자에 대해선 전부 L9으로 생성 */
        /*  (원본 ORDER BY 1,2,3,4,5,6,7 은 포맷표준 FM-014(숫자 위치지정 금지)에 따라 동일 컬럼명으로 표기) */
        INSERT INTO GT_OPT_ENG_GMAC_FLEQ2 (PLAN_ID,RESOURCE_ID,STAGE,TYPE,START_DATE,DAILY_VALUE,CALENDAR_LEVEL,SCM_SITE_ID,LINE_ID,ORI_LINE_ID,FULL_DAYS)
        /* FROZEN 구간에 대해 L9으로 lower_limit 생성 */
        SELECT FEE.PLAN_ID         AS PLAN_ID
              ,FEE.RESOURCE_ID     AS RESOURCE_ID
              ,FEE.STAGE           AS STAGE
              ,'lower_limit'       AS TYPE
              ,FEE.START_DATE      AS START_DATE
              ,'0'                 AS DAILY_VALUE
              ,'L9'                AS CALENDAR_LEVEL
              ,FEE.SCM_SITE_ID     AS SCM_SITE_ID
              ,FEE.LINE_ID         AS LINE_ID
              ,FEE.ORI_LINE_ID     AS ORI_LINE_ID
              ,FEE.FULL_DAYS       AS FULL_DAYS
        FROM GT_OPT_ENG_GMAC_FLEQ2 FEE
           , (
                        SELECT  FM.STAGE           AS STAGE
                               ,CAL.BASIS_YYYYMMDD AS START_DATE
                        FROM    SCP_OPT_ENG_FROZEN_MASTER_SN FM
                              , SCM_SYS_CALENDAR_M CAL
                        WHERE   FM.PLAN_ID = V_PLAN_ID
                        AND     FM.FROZEN_TYPE = 'PROD'
                        AND     CAL.BASIS_YYYYMMDD >= FM.FROZEN_START_DATE
                        AND     CAL.BASIS_YYYYMMDD < FM.FROZEN_END_DATE
                        ) FM
        WHERE   FEE.STAGE      = FM.STAGE
        AND     FEE.START_DATE = FM.START_DATE
        AND     FEE.TYPE       = 'lower_limit'
        AND     FEE.START_DATE  < TO_CHAR(TO_DATE(V_PLAN_START_YYYYMMDD,'YYYYMMDD') + TRUNC(TO_NUMBER(FEE.FULL_DAYS)),'YYYYMMDD')
        UNION ALL
        /*  FIX 구간에 대해 L9으로 lower_limit 생성 */
        SELECT FEE.PLAN_ID         AS PLAN_ID
              ,FEE.RESOURCE_ID     AS RESOURCE_ID
              ,FEE.STAGE           AS STAGE
              ,'lower_limit'       AS TYPE
              ,FEE.START_DATE      AS START_DATE
              ,'0'                 AS DAILY_VALUE
              ,'L9'                AS CALENDAR_LEVEL
              ,FEE.SCM_SITE_ID     AS SCM_SITE_ID
              ,FEE.LINE_ID         AS LINE_ID
              ,FEE.ORI_LINE_ID     AS ORI_LINE_ID
              ,FEE.FULL_DAYS       AS FULL_DAYS
        FROM GT_OPT_ENG_GMAC_FLEQ2 FEE
           , (
                        SELECT  CASE WHEN SEGMENT4 = 'F6000' THEN 'EOL'
                                     WHEN SEGMENT4 = 'A9000' THEN 'ASSY'
                                     WHEN SEGMENT4 = 'A8000' THEN 'STK'
                                     END    AS STAGE
                                ,SEGMENT5   AS SITE_ID
                                ,ATTRIBUTE1 AS LINE_ID
                               ,ATTRIBUTE3                   AS FIX_DATE
                               ,SUM(TRUNC(TO_NUMBER(ATTRIBUTE4))) AS FIX_QTY
                        FROM    SCP_OPMZ_LOOKUP_MASTER_DETAIL
                        WHERE   LOOKUP_TYPE = 'SCP_OPT_ENG_PROD_FIX'
                        AND     SEGMENT2    = V_DIVISION_ID
                        AND     SEGMENT3    = V_GROUP_ID
                        AND     VALID_YN    = 'Y'
                        GROUP BY SEGMENT4, SEGMENT5, ATTRIBUTE1, ATTRIBUTE3
                       ) FIX
        WHERE   FIX.SITE_ID     = FEE.SCM_SITE_ID
        AND     FIX.STAGE       = FEE.STAGE
        AND     FIX.LINE_ID     = FEE.ORI_LINE_ID
        AND     FIX.FIX_DATE    = FEE.START_DATE
        AND     FEE.START_DATE  < TO_CHAR(TO_DATE(V_PLAN_START_YYYYMMDD,'YYYYMMDD') + TRUNC(TO_NUMBER(FEE.FULL_DAYS)),'YYYYMMDD')
        UNION ALL
        /*  FULL_DAYS 이후 구간에 대해 L9으로 lower_limit 생성 */
        SELECT FEE.PLAN_ID         AS PLAN_ID
              ,FEE.RESOURCE_ID     AS RESOURCE_ID
              ,FEE.STAGE           AS STAGE
              ,'lower_limit'       AS TYPE
              ,FEE.START_DATE      AS START_DATE
              ,'0'                 AS DAILY_VALUE
              ,'L9'                AS CALENDAR_LEVEL
              ,FEE.SCM_SITE_ID     AS SCM_SITE_ID
              ,FEE.LINE_ID         AS LINE_ID
              ,FEE.ORI_LINE_ID     AS ORI_LINE_ID
              ,FEE.FULL_DAYS       AS FULL_DAYS
        FROM  GT_OPT_ENG_GMAC_FLEQ2 FEE
        WHERE 1=1
        AND   FEE.TYPE = 'lower_limit'
        AND   FEE.START_DATE  >= TO_CHAR(TO_DATE(V_PLAN_START_YYYYMMDD,'YYYYMMDD') + TRUNC(TO_NUMBER(FEE.FULL_DAYS)),'YYYYMMDD')
        ORDER BY PLAN_ID, RESOURCE_ID, STAGE, TYPE, START_DATE, DAILY_VALUE, CALENDAR_LEVEL;

        /* FROZEN 구간보다 이후 날짜 구간에 대해서는 비조업 날짜에 FROZEN에  86400/LOAD_PER -> 100을 넣어줌 */
        INSERT INTO SCP_OPT_ENG_FROZEN_PLAN_SN(PLAN_ID
                                              ,FROZEN_ID
                                              ,ROUTING_BOM_MAPPING_ID
                                              ,OP_SEQ
                                              ,RESOURCE_ID
                                              ,QUANTITY
                                              ,EFFECTIVE_DATE
                                              ,ATTRIBUTE1
                                              ,ATTRIBUTE2
                                              ,ATTRIBUTE3
        )
        SELECT  FEE.PLAN_ID                               AS PLAN_ID
               ,CASE WHEN FEE.RESOURCE_ID IS NULL OR FEE.START_DATE IS NULL THEN NULL
                     ELSE FEE.RESOURCE_ID||'::'||FEE.START_DATE END            AS FROZEN_ID
               ,CASE WHEN FEE.SCM_SITE_ID IS NULL THEN NULL
                     ELSE 'RB'||FEE.SCM_SITE_ID||'::IDLE_EQ::IDLE_EQ' END      AS ROUTING_BOM_MAPPING_ID
               ,0                                         AS OP_SEQ
               ,FEE.RESOURCE_ID                           AS RESOURCE_ID
               ,86400/RR.LOAD_PER                         AS QUANTITY
               ,FEE.START_DATE                            AS EFFECTIVE_DATE
               ,FEE.SCM_SITE_ID                           AS ATTRIBUTE1
               ,'IDLE_EQ'                                 AS ATTRIBUTE2
               ,'IDLE_EQ'                                 AS ATTRIBUTE3
        FROM    GT_OPT_ENG_GMAC_FLEQ2 FEE
              , SCP_OPT_ENG_ROUTING_RESOURCE_SN RR
              , SCP_OPT_ENG_FROZEN_MASTER_SN FM
              , GT_OPT_ENG_GMAC_NOWORK NW
        WHERE   FEE.PLAN_ID = RR.PLAN_ID
        AND     CASE WHEN FEE.SCM_SITE_ID IS NULL THEN NULL ELSE FEE.SCM_SITE_ID||'::IDLE_EQ::IDLE_EQ' END = RR.ROUTING_ID
        AND     FEE.RESOURCE_ID = RR.RESOURCE_ID
        AND     FEE.PLAN_ID     = FM.PLAN_ID
        AND     FEE.STAGE       = FM.STAGE
        AND     FM.FROZEN_TYPE = 'PROD'
        AND     FEE.STAGE       = NW.STAGE
        AND     FEE.START_DATE  = NW.START_DATE
        AND     1=1
        AND     FEE.TYPE = 'upper_limit'
        AND     FEE.START_DATE >= FM.FROZEN_END_DATE
        AND     FEE.START_DATE <  TO_CHAR(TO_DATE(V_PLAN_START_YYYYMMDD,'YYYYMMDD') + TRUNC(TO_NUMBER(FEE.FULL_DAYS)),'YYYYMMDD');

        /*  비조업 날짜는 'L9'을 제외하고 전체 삭제 */
        /*  (MSSQL DELETE..FROM INNER JOIN -> DELETE + EXISTS) */
        DELETE FROM GT_OPT_ENG_GMAC_FLEQ2 FEE
         WHERE FEE.CALENDAR_LEVEL != 'L9'
         AND   EXISTS ( SELECT 1
                          FROM GT_OPT_ENG_GMAC_NOWORK NW
                         WHERE NW.START_DATE = FEE.START_DATE
                         AND   NW.STAGE      = FEE.STAGE );

        /* 날짜별로 다시 합쳐서 INSERT */
        INSERT INTO SCP_OPT_ENG_RESOURCE_EVERY_CALENDAR_SN(PLAN_ID
                                                          ,RESOURCE_ID
                                                          ,TYPE
                                                          ,START_DATE
                                                          ,END_DATE
                                                          ,CALENDAR_LEVEL
                                                          ,DAILY_VALUE
                                                          ,ATTRIBUTE1
                                                          ,ATTRIBUTE14
                                                          ,ATTRIBUTE15
                                                          )
        SELECT PLAN_ID         AS PLAN_ID
              ,RESOURCE_ID     AS RESOURCE_ID
              ,TYPE            AS TYPE
              ,MIN(START_DATE) AS START_DATE
              /* ,MAX(START_DATE) AS END_DATE */
              ,TO_CHAR(TO_DATE(MAX(START_DATE),'YYYYMMDD') + 1,'YYYYMMDD') AS END_DATE
              ,CALENDAR_LEVEL  AS CALENDAR_LEVEL
              ,DAILY_VALUE     AS DAILY_VALUE
              ,SCM_SITE_ID     AS ATTRIBUTE1
              ,'FULL_LOADING'  AS ATTRIBUTE14
              ,LINE_ID         AS ATTRIBUTE15
        FROM(
            SELECT PLAN_ID
                  ,RESOURCE_ID
                  ,TYPE
                  ,START_DATE
                  ,CALENDAR_LEVEL
                  ,DAILY_VALUE
                  ,SCM_SITE_ID
                  ,LINE_ID
                  ,TO_DATE(START_DATE,'YYYYMMDD') - RN AS GRP
            FROM(
                SELECT PLAN_ID
                      ,RESOURCE_ID
                      ,TYPE
                      ,START_DATE
                      ,CALENDAR_LEVEL
                      ,DAILY_VALUE
                      ,SCM_SITE_ID
                      ,LINE_ID
                      ,ROW_NUMBER() OVER(PARTITION BY RESOURCE_ID,TYPE,CALENDAR_LEVEL ORDER BY RESOURCE_ID,TYPE,CALENDAR_LEVEL,START_DATE) AS RN
                FROM GT_OPT_ENG_GMAC_FLEQ2
                ) REC
            ) GEC
        GROUP BY PLAN_ID, RESOURCE_ID, TYPE, CALENDAR_LEVEL, DAILY_VALUE, GRP, SCM_SITE_ID, LINE_ID;

        /* ---------------------------------------------------------------------- */
        /*  GM MATERIAL 재고 ROLLING */
        /*  MATERIAL BOM은 AFTER에서 만들기 때문에 AFTER에서 진행 */
        /* ---------------------------------------------------------------------- */
        /* (MSSQL 대입형 SELECT 는 다중행이면 마지막 행이 승리하고 0행이면 변수를 유지 -> 커서 FOR 루프로 재현.
           ATTRIBUTE1 은 VARCHAR2(150 CHAR) 이고 대상 변수는 1자리 -> MSSQL 무음 절단과 동일하게 SUBSTR 적용) */
        FOR C_ROLLING IN ( SELECT SUBSTR(ATTRIBUTE1,1,1) AS ATTRIBUTE1
                             FROM SCP_OPMZ_LOOKUP_MASTER_DETAIL
                            WHERE LOOKUP_TYPE = 'SCP_OPT_ENG_GM_ONOFF_TEMP'
                            AND   SEGMENT1 = V_DIVISION_ID
                            AND   SEGMENT2 = V_GROUP_ID
                            AND   VALID_YN = 'Y' )
        LOOP
            V_ROLLING_YN := C_ROLLING.ATTRIBUTE1;
        END LOOP;

        IF V_ROLLING_YN = 'Y' THEN
            /*  UI의 생산 실적과 동일한 기준으로 맞춤 */
            /*  (MSSQL @FP_RELEASE_PLAN_TEMP 테이블변수 -> GTT GT_OPT_ENG_GMAC_FPREL, 진입부 DELETE 로 초기화) */
            DELETE FROM GT_OPT_ENG_GMAC_FPREL;

            INSERT INTO GT_OPT_ENG_GMAC_FPREL (PLANT_ID, ITEM_ID, LINE_ID, PLAN_DATE, PLAN_IN_QTY)
            SELECT PLANT_ID
                  ,ITEM_ID
                  ,LINE_ID
                  ,PLAN_DATE
                  ,SUM(NVL(A.QTY_LANE,0) + NVL(A.DFCT_QTY2,0) + NVL(A.YIELD_LOSS_QTY,0) + NVL(A.PRDT_REQ_QTY2,0)) AS PLAN_IN_QTY
            FROM   SCM_DAILY_PRODUCT_RESULT_H_SN A
            WHERE PLAN_DATE   < TO_DATE(V_PLAN_START_YYYYMMDD,'YYYYMMDD')
            AND   DIVISION_ID = V_DIVISION_ID
            AND   OPERATION_ID = 'A9000' /*  질문 */
            GROUP BY PLANT_ID,ITEM_ID,LINE_ID,PLAN_DATE;

            /*  기준일 이후, PSD 이전 MATERIAL 재고 데이터 */
            /*  (MSSQL @M_INV_RL_TEMP 테이블변수 -> GTT GT_OPT_ENG_GMAC_MINVRL, 진입부 DELETE 로 초기화) */
            DELETE FROM GT_OPT_ENG_GMAC_MINVRL;

            INSERT INTO GT_OPT_ENG_GMAC_MINVRL (SCM_SITE_ID, M_ITEM_ID, BASE_DATE, EFFECTIVE_DATE, M_INV_QTY)
            /*  START 2025.11.19 jongykim2: Schelduled Reciept Information */
            SELECT  LU.PLANT_SITE_ID                           AS SCM_SITE_ID
                   ,LU.ITEM_ID_CHILD                           AS M_ITEM_ID
                   ,MIN(LU.TO_YYYYMMDD) OVER(PARTITION BY LU.PLANT_SITE_ID, LU.ITEM_ID_CHILD) AS BASE_DATE
                   ,LU.TO_YYYYMMDD                             AS EFFECTIVE_DATE
                   ,SUM(CAST(LU.TO_EXPC_QTY AS NUMBER(20,10))) AS M_INV_QTY
            FROM    SCP_OPMZ_SCHEDULED_RECIEPT_INFORMATION LU
                  , SCP_OPMZ_PLAN_GR_M PG
            WHERE   LU.OPMZ_PLAN_GR_ID = PG.OPMZ_PLAN_GR_ID
            AND     1 = 1
            AND     LU.DIVISION_ID       = V_DIVISION_ID
            AND     PG.OPMZ_PLAN_GR_NAME = V_GROUP_ID
            AND     LU.TO_YYYYMMDD  < V_PLAN_START_YYYYMMDD
            AND     PG.VALID_YN          = 'Y'
            AND     LU.VALID_YN          = 'Y'
            GROUP BY LU.PLANT_SITE_ID, LU.ITEM_ID_CHILD, LU.TO_YYYYMMDD;
            /*  END 2025.11.19 jongykim2: Schelduled Reciept Information */
            /*
            SELECT  SEGMENT4                                AS SCM_SITE_ID
                   ,SEGMENT5                                AS M_ITEM_ID
                   ,MIN(ATTRIBUTE3)                         AS BASE_DATE
                   ,ATTRIBUTE1                              AS EFFECTIVE_DATE
                   ,SUM(CONVERT(NUMERIC(20,10),ATTRIBUTE2)) AS M_INV_QTY
            FROM    SCP_OPMZ_LOOKUP_MASTER_DETAIL WITH(NOLOCK)
            WHERE   LOOKUP_TYPE = 'SCP_OPT_ENG_CONST_INCOMMING_MATERIAL'
            AND     SEGMENT2    = @V_DIVISION_ID
            AND     SEGMENT3    = @V_GROUP_ID
            AND     ATTRIBUTE3 <= ATTRIBUTE1 -- EFFECTIVE DATE가 BASE DATE보다 같거나 큰 재고가 대상
            AND     ATTRIBUTE1  < @V_PLAN_START_YYYYMMDD
            GROUP BY SEGMENT4, SEGMENT5, ATTRIBUTE1 */


            INSERT INTO SCP_OPT_ENG_INCOMING_STOCK_SN(PLAN_ID
                                                     ,STOCK_ID
                                                     ,BUFFER_ID
                                                     ,EFFECTIVE_DATE
                                                     ,TYPE
                                                     ,QUANTITY
                                                     ,ATTRIBUTE1
                                                     ,ATTRIBUTE2
                                                     ,ATTRIBUTE3
                                                     ,ATTRIBUTE4
                                                     ,ATTRIBUTE5
                                                     ,ATTRIBUTE6
                                                     )
            SELECT  V_PLAN_ID                                                  AS PLAN_ID
                   ,CASE WHEN SCM_SITE_ID IS NULL OR MAT_ID IS NULL OR ARR_DATE IS NULL THEN NULL
                         ELSE TYPE||'::'||SCM_SITE_ID||'::'||MAT_ID||'::'||STAGE||'::'||ARR_DATE END AS STOCK_ID
                   ,CASE WHEN SCM_SITE_ID IS NULL OR MAT_ID IS NULL THEN NULL
                         ELSE SCM_SITE_ID||'::'||MAT_ID||'::'||STAGE END        AS BUFFER_ID
                   ,ARR_DATE                                                   AS EFFECTIVE_DATE
                   ,TYPE                                                       AS TYPE
                   ,SUM(QTY)                                                   AS QUANTITY
                   ,SCM_SITE_ID                                                AS SITE_ID
                   ,MAT_ID                                                     AS ITEM_ID
                   ,STAGE                                                      AS STAGE
                   ,STAGE                                                      AS STAGE_BUFFER
                   ,'-'                                                        AS INCOTERMS
                   ,'-'                                                        AS PROJECT_CODE
            FROM(
                /*  기준일 이후, PSD 이전까지의 재고/실적 반영을 위해 */
                SELECT IR.SCM_SITE_ID           AS SCM_SITE_ID
                      ,IR.M_ITEM_ID             AS MAT_ID
                      ,'MATERIAL_CONST'         AS STAGE
                      ,V_PLAN_START_YYYYMMDD    AS ARR_DATE
                      ,IR.M_INV_QTY - PR.TOTAL_QTY AS QTY
                      ,'DR'                     AS TYPE
                /* FROM @M_INV_RL_TEMP IR: BLOCKED 2025.11.19 jongykim2 */
                FROM (/* ADDED 2025.11.19 jongykim2: Schelduled Reciept Information */
                      SELECT IR.SCM_SITE_ID
                            ,IR.M_ITEM_ID
                            ,SUM(IR.M_INV_QTY) AS M_INV_QTY
                      FROM   GT_OPT_ENG_GMAC_MINVRL IR
                      GROUP BY IR.SCM_SITE_ID, IR.M_ITEM_ID
                     ) IR
                        , (
                               /* BOM에서 찾은 상위 제품의 IN_QTY 생산 실적을 CONSUME_QTY와 곱해서 소요 수량을 구함 */
                               SELECT BD.SCM_SITE_ID               AS SCM_SITE_ID
                                     /* ,PR.ITEM_ID                   AS ITEM_ID */
                                     ,BD.C_ITEM_ID                 AS C_ITEM_ID
                                     ,SUM(NVL(PR.PLAN_IN_QTY,1))*BD.C_QTY AS TOTAL_QTY
                                     ,BD.C_QTY                     AS C_QTY

                               FROM  (
                                             /*  LOOKUP에 있는 MATERIAL 기준으로 BOM상위 제품을 찾음 */
                                             SELECT  MS.PLANT_ID          AS PLANT_ID
                                                    ,BOM.ATTRIBUTE2       AS P_ITEM_ID
                                                    ,BOM.ATTRIBUTE14      AS C_ITEM_ID
                                                    ,BOM.CONSUME_QUANTITY AS C_QTY
                                                    ,MI.BASE_DATE         AS BASE_DATE
                                                    ,MI.SCM_SITE_ID       AS SCM_SITE_ID
                                             FROM    SCP_OPT_ENG_BOM_SN BOM
                                                  , (
                                                           SELECT  SCM_SITE_ID
                                                                  ,M_ITEM_ID
                                                                  ,BASE_DATE
                                                           FROM    GT_OPT_ENG_GMAC_MINVRL
                                                           GROUP BY SCM_SITE_ID, M_ITEM_ID, BASE_DATE
                                                           ) MI
                                                  , SCM_MST_SITE MS
                                             WHERE   BOM.ATTRIBUTE1  = MI.SCM_SITE_ID
                                             AND     BOM.ATTRIBUTE14 = MI.M_ITEM_ID
                                             AND     MI.SCM_SITE_ID = MS.SCM_SITE_ID
                                             AND     BOM.PLAN_ID = V_PLAN_ID
                                             GROUP BY MS.PLANT_ID, BOM.ATTRIBUTE2, BOM.ATTRIBUTE14, BOM.CONSUME_QUANTITY, MI.BASE_DATE, MI.SCM_SITE_ID
                                            ) BD
                                    , GT_OPT_ENG_GMAC_FPREL PR
                              WHERE  PR.PLAN_DATE(+)  >= TO_DATE(BD.BASE_DATE,'YYYYMMDD')
                                AND  PR.PLAN_DATE(+)   < TO_DATE(V_PLAN_START_YYYYMMDD,'YYYYMMDD')
                                AND  PR.PLANT_ID(+)    = BD.PLANT_ID
                                AND  PR.ITEM_ID(+)     = BD.P_ITEM_ID
                                AND  PR.PLAN_IN_QTY(+) > 0
                               GROUP BY BD.SCM_SITE_ID,BD.C_ITEM_ID,BD.C_QTY
                               ) PR
                WHERE IR.SCM_SITE_ID = PR.SCM_SITE_ID
                AND   IR.M_ITEM_ID   = PR.C_ITEM_ID
                AND   IR.M_INV_QTY - PR.TOTAL_QTY > 0
                ) MC
            WHERE ARR_DATE < V_PLAN_END_YYYYMMDD
            GROUP BY TYPE, SCM_SITE_ID, MAT_ID, STAGE, ARR_DATE;
        END IF;

        /* ---------------------------------------------------------------------- */
        /*  2025.09.23/THKIM */
        /*  HORIZEN CALENDAR Infeasible 방지를 위한 BUCKET 추가 */

        /* ---------------------------------------------------------------------- */
        SELECT  CASE WHEN COUNT(*)>0 THEN 'Y' ELSE 'N' END
          INTO  V_MONTHLYOFF_YN
        FROM    SCP_OPT_ENG_PHASES_SN
        WHERE   PLAN_ID = V_PLAN_ID
        AND     BUCKETLISTCODE = 'monthlyoff';

        SELECT  CASE WHEN COUNT(*)>0 THEN 'Y' ELSE 'N' END
          INTO  V_HORIZEN_ZERO_YN
        FROM    SCP_OPT_ENG_RESOURCE_HORIZON_CALENDAR_SN
        WHERE   PLAN_ID = V_PLAN_ID
        AND     TYPE    = 'upper_limit'
        AND     VALUE   = 0;

        IF V_MONTHLYOFF_YN = 'Y' AND V_HORIZEN_ZERO_YN = 'Y' THEN
            DELETE FROM GT_OPT_ENG_GMAC_MOFF;

            /*  upper limit, VALUE = 0인 데이터 대상으로 날짜 추출 */
            INSERT INTO GT_OPT_ENG_GMAC_MOFF ("DATE")
            SELECT  START_DATE
            FROM    SCP_OPT_ENG_RESOURCE_HORIZON_CALENDAR_SN
            WHERE   PLAN_ID = V_PLAN_ID
            AND     TYPE    = 'upper_limit'
            AND     VALUE   = 0
            GROUP BY START_DATE
            UNION ALL
            SELECT  END_DATE
            FROM    SCP_OPT_ENG_RESOURCE_HORIZON_CALENDAR_SN
            WHERE   PLAN_ID = V_PLAN_ID
            AND     TYPE    = 'upper_limit'
            AND     VALUE   = 0
            GROUP BY END_DATE;

            /*  추출한 날짜 대상 매월 1일 추가 */
            INSERT INTO GT_OPT_ENG_GMAC_MOFF ("DATE")
            SELECT  DT."DATE"
            FROM(
                SELECT CASE WHEN BASIS_YYYYMM IS NULL THEN NULL ELSE BASIS_YYYYMM||'01' END AS "DATE"
                FROM(
                    SELECT  MIN("DATE") AS MIN_DATE
                           ,MAX("DATE") AS MAX_DATE
                    FROM    GT_OPT_ENG_GMAC_MOFF
                    ) DT
                  , SCM_SYS_CALENDAR_M CAL
                WHERE   CAL.BASIS_YYYYMMDD >= DT.MIN_DATE
                AND     CAL.BASIS_YYYYMMDD <= DT.MAX_DATE
                GROUP BY BASIS_YYYYMM
                ) DT
            WHERE DT."DATE" > V_PLAN_START_YYYYMMDD
            AND   DT."DATE" < V_PLAN_END_YYYYMMDD;

            /*  PSD, PED 추가 */
            INSERT INTO GT_OPT_ENG_GMAC_MOFF ("DATE") VALUES(V_PLAN_START_YYYYMMDD);
            INSERT INTO GT_OPT_ENG_GMAC_MOFF ("DATE") VALUES(V_PLAN_END_YYYYMMDD);

            /*  BUCKET에 입력 */
            INSERT INTO SCP_OPT_ENG_BUCKETS_SN(PLAN_ID
                                              ,BUCKET_NAME
                                              ,START_DATE
                                              )
            SELECT V_PLAN_ID     AS PLAN_ID
                  ,'monthlyoff'  AS BUCKET_NAME
                  ,MOT."DATE"    AS START_DATE
            FROM GT_OPT_ENG_GMAC_MOFF MOT
            WHERE NOT EXISTS ( SELECT 1
                               FROM   SCP_OPT_ENG_BUCKETS_SN B
                               WHERE  B.PLAN_ID    = V_PLAN_ID
                               AND    B.BUCKET_NAME = 'monthlyoff'
                               AND    B.START_DATE  = MOT."DATE" )
            GROUP BY MOT."DATE"
            ORDER BY MOT."DATE";
        END IF;

    /* ---------------------------------------------------------------------- */
    /*  ERROR LOG (MSSQL BEGIN CATCH / RAISERROR 대응) */
    /* ---------------------------------------------------------------------- */
    EXCEPTION
        WHEN OTHERS THEN
            /* ROLLBACK TRANSACTION PR_SCP_OPT_ENG_RUN_MAIN_PROC; */
            /* ---------------------------------------------------------------------- */
            /*  ERROR LOG */
            /* ---------------------------------------------------------------------- */

            V_MESSAGE_TEXT := SUBSTR(SQLERRM, 1, 1000);
            /* ---------------------------------------------------------------------- */
            PR_SCP_OPT_ENG_LOG_CRE_PROC('I','INPUT',V_PLAN_ID,V_PROGRAM_NAME,'ERROR',NULL,V_MESSAGE_TEXT,NULL,V_PLAN_ID);
            /* ---------------------------------------------------------------------- */
            V_DETAIL_DATE := SYSDATE;
            /* ---------------------------------------------------------------------- */
            PR_SCP_OPT_ENG_LOG_DTL_PROC('U',V_PLAN_ID,'STEP01',NULL,NULL,V_DETAIL_DATE,NULL,V_MESSAGE_TEXT,'ERROR');
            /* ---------------------------------------------------------------------- */
            RAISE_APPLICATION_ERROR(-20001, V_PROGRAM_NAME);
            /* ---------------------------------------------------------------------- */
    END;
    /* ---------------------------------------------------------------------- */

    /* ---------------------------------------------------------------------- */
    /*  종료 LOG */
    /* ---------------------------------------------------------------------- */
    IF V_MESSAGE_TEXT IS NULL THEN
    /* ---------------------------------------------------------------------- */
        PR_SCP_OPT_ENG_LOG_CRE_PROC('I','INPUT',V_PLAN_ID,V_PROGRAM_NAME,'END',NULL,NULL,NULL,V_PLAN_ID);
        PR_SCP_OPT_ENG_LOG_DTL_PROC('U',V_PLAN_ID,'STEP01',NULL,NULL,NULL,NULL,NULL,NULL);
    END IF;
    /* ---------------------------------------------------------------------- */
END PR_SCP_OPT_ENG_GM_INPUT_AFTER_CORRECT;

