PROCEDURE PR_SCP_OPT_ENG_GM_INPUT_PLAN_MASTER
(
     P_PLAN_ID              VARCHAR2
    ,V_DIVISION_ID          VARCHAR2
    ,V_GROUP_ID             VARCHAR2
    ,V_PLAN_START_YYYYMMDD  VARCHAR2
    ,V_PLAN_END_YYYYMMDD    VARCHAR2
)
/* ============================================================
 * Program ID   : PR_SCP_OPT_ENG_GM_INPUT_PLAN_MASTER
 * Description  : SCP OPT ENG GM 엔진 PLAN MASTER 입력데이터 생성
 * Program History
 *------------------------------------------------------------
 * Date          In Charge      Description
 *------------------------------------------------------------
 * 2025.02.05    Y.S.H          Initial Release
 * 2026.07.30    ZIONEX         [PJ202650304]  NextSCM Migration
 *                               상위 RUN_MAIN 이 호출하는 하위 단계이므로 내부 COMMIT 없음(부모 트랜잭션 소유).)
 * ============================================================ */
AS
    /* Set Prameter */
    V_PROGRAM_NAME       VARCHAR2(150 CHAR) := 'PR_SCP_OPT_ENG_GM_INPUT_PLAN_MASTER';
    V_PLAN_ID            VARCHAR2(50 CHAR)  := P_PLAN_ID;
    V_MESSAGE_TEXT       VARCHAR2(1000 CHAR);
    V_DETAIL_DATE        DATE;

    V_SCP_PLAN_DATE      VARCHAR2(8 CHAR);
    V_SCP_PLAN_TYPE      VARCHAR2(8 CHAR);
    V_SCP_PLAN_SEQ       VARCHAR2(8 CHAR);
BEGIN
    /* Step 3. SCP_OPT_ENG_ENGINE_DATA_CREATE_L_N 생성 */
    PR_SCP_OPT_ENG_LOG_CRE_PROC('I','INPUT',V_PLAN_ID,V_PROGRAM_NAME,'START',NULL,NULL,NULL,V_PLAN_ID);

    /* ------------------------------------------------------------------ */
    /* Transaction (START)                                                 */
    /* BEGIN TRANSACTION SCP_OPT_ENG_RUN_MAIN_PROC;                        */
    /* ------------------------------------------------------------------ */
    BEGIN
        /* ------------------------------------------------------------------ */
        /* INPUT START                                                         */
        /* ------------------------------------------------------------------ */
        /*
        --INSERT INTO SCP_OPT_ENG_PLAN_MASTER_SN (PLAN_ID,PLAN_START_DATE,PLAN_END_DATE,ATTRIBUTE1,ATTRIBUTE2,ATTRIBUTE15)
        --SELECT  @V_PLAN_ID
        --       ,PLAN_START_YYYYMMDD
        --       ,CONVERT(NVARCHAR(8),DATEADD(DAY,1,PLAN_END_YYYYMMDD),112) AS PLAN_END_YYYYMMDD
        --       ,DIVISION_ID
        --       ,PLAN_TYPE_CODE
        --       ,@V_SCP_PLAN_DATE+','+@V_SCP_PLAN_TYPE+','+@V_SCP_PLAN_SEQ
        --FROM    SCP_OPT_ENG_SCP_PLAN_ID_M_SN WITH(NOLOCK)
        --WHERE   1=1
        --AND     PLAN_ID = @V_PLAN_ID


        --INSERT INTO SCP_OPT_ENG_PLAN_MASTER_SN (PLAN_ID,PLAN_START_DATE,PLAN_END_DATE,ATTRIBUTE1,ATTRIBUTE2,ATTRIBUTE15)
        --SELECT  @V_PLAN_ID
        --       ,PLAN_START_YYYYMMDD
        --       ,CONVERT(NVARCHAR(8),DATEADD(DAY,1,PLAN_END_YYYYMMDD),112) AS PLAN_END_YYYYMMDD
        --       ,PM.DIVISION_ID
        --       ,PGM.OPMZ_PLAN_GR_NAME
        --       ,@V_SCP_PLAN_DATE+','+@V_SCP_PLAN_TYPE+','+@V_SCP_PLAN_SEQ
        --FROM     SCP_OPMZ_PLAN_M PM WITH(NOLOCK)
        --    INNER JOIN SCP_OPMZ_PLAN_GR_M PGM WITH(NOLOCK)
        --        ON PM.OPMZ_PLAN_GR_ID = PGM.OPMZ_PLAN_GR_ID
        --WHERE   PM.OPMZ_PLAN_ID = @V_PLAN_ID
        */

        /* 2025.06.20 김태현 : DEMAND에 필요한 SEMI 정보는 FROZEN 계획을 SSP로 선택하거나 SCP 다른 버전을 선택했더라도, 최신 SCP 계획을 가져오는 것이 맞음/재욱 책임님 확인 사항 -> PLAN_MASTER에 마킹 */
        BEGIN
            SELECT A.PLAN_START_YYYYMMDD
                 , A.PLAN_TYPE
                 , A.PLAN_SEQ
              INTO V_SCP_PLAN_DATE
                 , V_SCP_PLAN_TYPE
                 , V_SCP_PLAN_SEQ
              FROM (SELECT DIVISION_ID
                         , PLAN_START_YYYYMMDD
                         , PLAN_TYPE
                         , PLAN_SEQ
                         , PLAN_TYPE_ORDER
                         , CONFIRM_FLAG
                         , ROW_NUMBER() OVER (PARTITION BY DIVISION_ID ORDER BY PLAN_TYPE_ORDER DESC, CONFIRM_FLAG DESC, PLAN_SEQ DESC) AS PLAN_RANK
                      FROM SCP_PLAN_VERSION_V
                     WHERE DIVISION_ID         = V_DIVISION_ID
                       AND PLAN_START_YYYYMMDD = TO_CHAR(FN_NEXT_DAY(TO_DATE(V_PLAN_START_YYYYMMDD,'YYYYMMDD'),'MON') - 7, 'YYYYMMDD') /* 해당 주 월요일 YYYYMMDD */
                   ) A
             WHERE A.PLAN_RANK = 1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN NULL;
            WHEN TOO_MANY_ROWS THEN NULL;
        END;

        INSERT
          INTO SCP_OPT_ENG_PLAN_MASTER_SN
             ( PLAN_ID
             , PLAN_START_DATE
             , PLAN_END_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE15 )
        SELECT V_PLAN_ID
             , PLAN_START_YYYYMMDD
             , PLAN_END_YYYYMMDD
             , DIVISION_ID
             , PLAN_GROUP_ID
             , V_SCP_PLAN_DATE||','||V_SCP_PLAN_TYPE||','||V_SCP_PLAN_SEQ
          FROM (SELECT PM.DIVISION_ID          AS DIVISION_ID
                     , PGM.OPMZ_PLAN_GR_NAME   AS PLAN_GROUP_ID
                     , PM.PLAN_START_YYYYMMDD  AS PLAN_START_YYYYMMDD
                     , TO_CHAR(TO_DATE(PM.PLAN_END_YYYYMMDD,'YYYYMMDD') + 1,'YYYYMMDD') AS PLAN_END_YYYYMMDD
                  FROM SCP_OPMZ_PLAN_M     PM
                     , SCP_OPMZ_PLAN_GR_M  PGM
                 WHERE PM.OPMZ_PLAN_GR_ID = PGM.OPMZ_PLAN_GR_ID
                   AND PM.OPMZ_PLAN_ID    = V_PLAN_ID
                UNION
                SELECT DIVISION_ID             AS DIVISION_ID
                     , PLAN_TYPE_CODE          AS PLAN_GROUP_ID
                     , PLAN_START_YYYYMMDD     AS PLAN_START_YYYYMMDD
                     , TO_CHAR(TO_DATE(PLAN_END_YYYYMMDD,'YYYYMMDD') + 1,'YYYYMMDD') AS PLAN_END_YYYYMMDD
                  FROM SCP_OPT_ENG_SCP_PLAN_ID_M_SN
                 WHERE 1=1
                   AND PLAN_ID = V_PLAN_ID) A;

        /* ------------------------------------------------------------------ */
        /* INPUT END                                                           */
        /* ------------------------------------------------------------------ */
    EXCEPTION
        /* ERROR LOG */
        /* ROLLBACK TRANSACTION PR_SCP_OPT_ENG_RUN_MAIN_PROC; */
        WHEN OTHERS THEN
            V_MESSAGE_TEXT := SQLERRM;
            PR_SCP_OPT_ENG_LOG_CRE_PROC('I','INPUT',V_PLAN_ID,V_PROGRAM_NAME,'ERROR',NULL,V_MESSAGE_TEXT,NULL,V_PLAN_ID);
            V_DETAIL_DATE  := SYSDATE;
            PR_SCP_OPT_ENG_LOG_DTL_PROC('U',V_PLAN_ID,'STEP01',NULL,NULL,V_DETAIL_DATE,NULL,V_MESSAGE_TEXT,'ERROR');
            RAISE_APPLICATION_ERROR(-20001, V_PROGRAM_NAME);
    END;

    /* 종료 LOG */
    IF V_MESSAGE_TEXT IS NULL THEN
        PR_SCP_OPT_ENG_LOG_CRE_PROC('I','INPUT',V_PLAN_ID,V_PROGRAM_NAME,'END',NULL,NULL,NULL,V_PLAN_ID);
        PR_SCP_OPT_ENG_LOG_DTL_PROC('U',V_PLAN_ID,'STEP01',NULL,NULL,NULL,NULL,NULL,NULL);
    END IF;

END PR_SCP_OPT_ENG_GM_INPUT_PLAN_MASTER;

PROCEDURE PR_SCP_OPT_ENG_GM_RUN_MAIN_PROC
(
     P_PLAN_ID  VARCHAR2
)
/* ============================================================
 * Program ID   : PR_SCP_OPT_ENG_GM_RUN_MAIN_PROC
 * Description  : SCP OPT ENG GM 엔진 INPUT 데이터 생성 통합 실행(오케스트레이터)
 *                (SCP Plan 정보 수집 -> LOOKUP 재적재 -> 단계별 INPUT 생성 프로시저 순차 호출)
 * Program History
 *------------------------------------------------------------
 * Date          In Charge      Description
 *------------------------------------------------------------
 * 2025.07.07    Philsu Park    Initial Release
 * 2026.07.30    ZIONEX         [PJ202650304]  NextSCM Migration
 *                               MSSQL 대입형 SELECT 는 SELECT INTO + NO_DATA_FOUND 가드로,
 * ============================================================ */
IS
    /* Set Prameter */
    V_PROGRAM_NAME        VARCHAR2(150 CHAR) := 'PR_SCP_OPT_ENG_GM_RUN_MAIN_PROC';
    V_PLAN_ID             VARCHAR2(50 CHAR)  := P_PLAN_ID;
    V_MESSAGE_TEXT        VARCHAR2(1000 CHAR);
    V_DETAIL_START_DATE   DATE;
    V_DETAIL_END_DATE     DATE;

    V_DIVISION_ID          VARCHAR2(20 CHAR);
    V_GROUP_ID             VARCHAR2(20 CHAR);
    V_PLAN_START_YYYYMMDD  VARCHAR2(8 CHAR);
    V_PLAN_END_YYYYMMDD    VARCHAR2(8 CHAR);

    V_SCP_PLAN_DATE    VARCHAR2(8 CHAR);
    V_SCP_PLAN_TYPE    VARCHAR2(8 CHAR);
    V_SHIP_PLAN_SEQ    VARCHAR2(8 CHAR);
BEGIN
    /* ------------------------------------------------------------------ */
    /* Procedure 기본조건.                                                 */

    /* SET TRANSACTION ISOLATION LEVEL READ COMMITTED / SET ANSI_WARNINGS OFF 는 */

    /* ------------------------------------------------------------------ */

    /* ------------------------------------------------------------------ */
    /* LOG DELETE                                                          */
    /* 2025.05.21 Philsu Park: Status, Status Detail은 서버 프로그램에서 처리하기 때문에 로그 생성 및 기존 실행로그 삭제 하는 부분 주석처리. */
    /* ------------------------------------------------------------------ */
    /*
    --DELETE FROM SCP_OPT_ENG_ENGINE_RUN_STATUS_SN        WHERE PLAN_ID = @V_PLAN_ID
    --DELETE FROM SCP_OPT_ENG_ENGINE_RUN_STATUS_DETAIL_SN WHERE PLAN_ID = @V_PLAN_ID
    */
    DELETE
      FROM SCP_OPT_ENG_ENGINE_DATA_CREATE_L_N_SN
     WHERE PLAN_ID = V_PLAN_ID;

    /* ------------------------------------------------------------------ */
    /* Step 1. ENGINE_RUN_STATUS 생성                                      */
    /* ------------------------------------------------------------------ */
    /*
    --EXEC PR_SCP_OPT_ENG_LOG_STATUS_PROC 'I',@V_PLAN_ID,'N','N','N','N','N','N','N','N',NULL,NULL
    */
    /* ------------------------------------------------------------------ */
    /* Step 2. ENGINE_RUN_STATUS_DETAIL 생성                               */
    /* ------------------------------------------------------------------ */
    /*
    --EXEC PR_SCP_OPT_ENG_LOG_DTL_PROC 'I',@V_PLAN_ID,NULL,NULL,NULL,NULL,NULL,NULL,NULL
    */
    /* ------------------------------------------------------------------ */
    /* Step 3. SCP_OPT_ENG_ENGINE_DATA_CREATE_L_N 생성                     */
    /* ------------------------------------------------------------------ */
    PR_SCP_OPT_ENG_LOG_CRE_PROC('I','INPUT',V_PLAN_ID,V_PROGRAM_NAME,'START',NULL,NULL,NULL,V_PLAN_ID);

    /* ------------------------------------------------------------------ */
    /* Transaction (START)                                                 */
    /* BEGIN TRANSACTION SCP_OPT_ENG_RUN_MAIN_PROC;                        */
    /* ------------------------------------------------------------------ */
    BEGIN
        /* ------------------------------------------------------------------ */
        /* INPUT Start                                                         */
        /* ------------------------------------------------------------------ */
        /*
        --EXEC PR_SCP_OPT_ENG_LOG_STATUS_PROC 'U',@V_PLAN_ID,NULL,'Y',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL
        */
        V_DETAIL_START_DATE := SYSDATE;
        /*
        --EXEC PR_SCP_OPT_ENG_LOG_DTL_PROC 'U',@V_PLAN_ID,'STEP01',NULL,NULL,@V_DETAIL_START_DATE,NULL,NULL,'RUNNING'
        */

        /*
        --SELECT  @V_DIVISION_ID         = DIVISION_ID
        --       ,@V_GROUP_ID            = PLAN_TYPE_CODE
        --       ,@V_PLAN_START_YYYYMMDD = PLAN_START_YYYYMMDD
        --       ,@V_PLAN_END_YYYYMMDD   = CONVERT(NVARCHAR(8),DATEADD(DAY,1,PLAN_END_YYYYMMDD),112)
        --FROM    SCP_OPT_ENG_SCP_PLAN_ID_M_SN WITH(NOLOCK)
        --WHERE   1=1
        --AND     PLAN_ID = @V_PLAN_ID

        --SELECT   @V_DIVISION_ID         = PM.DIVISION_ID
        --        ,@V_GROUP_ID            = PGM.OPMZ_PLAN_GR_NAME
        --        ,@V_PLAN_START_YYYYMMDD = PM.PLAN_START_YYYYMMDD
        --        ,@V_PLAN_END_YYYYMMDD   = CONVERT(NVARCHAR(8),DATEADD(DAY,1,PM.PLAN_END_YYYYMMDD),112)
        --FROM     SCP_OPMZ_PLAN_M PM WITH(NOLOCK)
        --    INNER JOIN SCP_OPMZ_PLAN_GR_M PGM WITH(NOLOCK)
        --        ON PM.OPMZ_PLAN_GR_ID = PGM.OPMZ_PLAN_GR_ID
        --WHERE   PM.OPMZ_PLAN_ID = @V_PLAN_ID
        */

        /* 원본 SELECT @var (무행=값 유지/NULL) -> SELECT INTO + NO_DATA_FOUND / TOO_MANY_ROWS 가드. */
        BEGIN
            SELECT SUBSTR(A.DIVISION_ID,1,20)
                 , SUBSTR(A.PLAN_GROUP_ID,1,20)
                 , A.PLAN_START_YYYYMMDD
                 , A.PLAN_END_YYYYMMDD
              INTO V_DIVISION_ID
                 , V_GROUP_ID
                 , V_PLAN_START_YYYYMMDD
                 , V_PLAN_END_YYYYMMDD
              FROM (SELECT PM.DIVISION_ID          AS DIVISION_ID
                         , PGM.OPMZ_PLAN_GR_NAME   AS PLAN_GROUP_ID
                         , PM.PLAN_START_YYYYMMDD  AS PLAN_START_YYYYMMDD
                         , TO_CHAR(TO_DATE(PM.PLAN_END_YYYYMMDD,'YYYYMMDD') + 1,'YYYYMMDD') AS PLAN_END_YYYYMMDD
                      FROM SCP_OPMZ_PLAN_M     PM
                         , SCP_OPMZ_PLAN_GR_M  PGM
                     WHERE PM.OPMZ_PLAN_GR_ID = PGM.OPMZ_PLAN_GR_ID
                       AND PM.OPMZ_PLAN_ID    = V_PLAN_ID
                    UNION
                    SELECT DIVISION_ID             AS DIVISION_ID
                         , PLAN_TYPE_CODE          AS PLAN_GROUP_ID
                         , PLAN_START_YYYYMMDD     AS PLAN_START_YYYYMMDD
                         , TO_CHAR(TO_DATE(PLAN_END_YYYYMMDD,'YYYYMMDD') + 1,'YYYYMMDD') AS PLAN_END_YYYYMMDD
                      FROM SCP_OPT_ENG_SCP_PLAN_ID_M_SN
                     WHERE 1=1
                       AND PLAN_ID = V_PLAN_ID) A;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN NULL;
            WHEN TOO_MANY_ROWS THEN NULL;
        END;

        /*           @V_SCP_PLAN_DATE/@V_SCP_PLAN_TYPE/@V_SHIP_PLAN_SEQ 는 NVARCHAR(8) */
        BEGIN
            SELECT SUBSTR(A.PLAN_START_YYYYMMDD,1,8)
                 , SUBSTR(A.PLAN_TYPE,1,8)
                 , SUBSTR(TO_CHAR(A.PLAN_SEQ),1,8)
              INTO V_SCP_PLAN_DATE
                 , V_SCP_PLAN_TYPE
                 , V_SHIP_PLAN_SEQ
              FROM (SELECT DIVISION_ID
                         , PLAN_START_YYYYMMDD
                         , PLAN_TYPE
                         , PLAN_SEQ
                         , PLAN_TYPE_ORDER
                         , CONFIRM_FLAG
                      FROM SCP_PLAN_VERSION_V
                     WHERE DIVISION_ID         = V_DIVISION_ID
                       AND PLAN_START_YYYYMMDD = TO_CHAR(FN_NEXT_DAY(TO_DATE(V_PLAN_START_YYYYMMDD,'YYYYMMDD'), 'MON') - 7,'YYYYMMDD') /* 해당 주 월요일 YYYYMMDD */
                     ORDER BY PLAN_TYPE_ORDER DESC
                            , CONFIRM_FLAG DESC
                            , PLAN_SEQ DESC
                   ) A
             WHERE ROWNUM = 1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN NULL;
        END;

        /* PLAN_ID 별 LOOKUP SETTING 확인을 위한 조치 /선웅 선임님 요청/20250514/김태현 선임 */
        DELETE
          FROM SCP_OPT_ENG_LOOKUP_SN
         WHERE PLAN_ID = V_PLAN_ID;

        INSERT
          INTO SCP_OPT_ENG_LOOKUP_SN
             ( PLAN_ID
             , LOOKUP_TYPE
             , SEGMENT1
             , SEGMENT2
             , SEGMENT3
             , SEGMENT4
             , SEGMENT5
             , SEGMENT6
             , SEGMENT7
             , SEGMENT8
             , SEGMENT9
             , SEGMENT10
             , DISPLAY_SEQ
             , VALID_YN
             , DESCRIPTION
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , ATTRIBUTE6
             , ATTRIBUTE7
             , ATTRIBUTE8
             , ATTRIBUTE9
             , ATTRIBUTE10
             , ATTRIBUTE11
             , ATTRIBUTE12
             , ATTRIBUTE13
             , ATTRIBUTE14
             , ATTRIBUTE15 )
        SELECT V_PLAN_ID
             , LOOKUP_TYPE
             , SEGMENT1
             , SEGMENT2
             , SEGMENT3
             , SEGMENT4
             , SEGMENT5
             , SEGMENT6
             , SEGMENT7
             , SEGMENT8
             , SEGMENT9
             , SEGMENT10
             , DISPLAY_SEQ
             , VALID_YN
             , DESCRIPTION
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , ATTRIBUTE6
             , ATTRIBUTE7
             , ATTRIBUTE8
             , ATTRIBUTE9
             , ATTRIBUTE10
             , ATTRIBUTE11
             , ATTRIBUTE12
             , ATTRIBUTE13
             , ATTRIBUTE14
             , ATTRIBUTE15
          FROM SCP_OPMZ_LOOKUP_MASTER_DETAIL;

        /* 2025.06.19 TAEHYUN KIM:FROZEN MASTER 관리 */
        PR_SCP_OPT_ENG_GM_INPUT_FROZEN_MASTER      (V_PLAN_ID);
        PR_SCP_OPT_ENG_GM_INPUT_DELETE_PROC        (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        PR_SCP_OPT_ENG_GM_INPUT_PLAN_MASTER        (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        PR_SCP_OPT_ENG_GM_INPUT_BUCKET             (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        PR_SCP_OPT_ENG_GM_INPUT_ASSIGN_MODEL_LIST  (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        PR_SCP_OPT_ENG_GM_INPUT_RESOURCE           (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        PR_SCP_OPT_ENG_GM_INPUT_EVERY_DAY_CAL      (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        PR_SCP_OPT_ENG_GM_INPUT_PARAMETER          (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        PR_SCP_OPT_ENG_GM_INPUT_DEMAND             (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        PR_SCP_OPT_ENG_GM_INPUT_BOM                (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        PR_SCP_OPT_ENG_GM_INPUT_INCOMING_STOCK     (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        PR_SCP_OPT_ENG_GM_INPUT_SCHEDULED_MOVE     (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        PR_SCP_OPT_ENG_GM_INPUT_ITEM_SITE          (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        PR_SCP_OPT_ENG_GM_INPUT_BOD                (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        PR_SCP_OPT_ENG_GM_INPUT_ROUTING_RESOURCE   (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        PR_SCP_OPT_ENG_GM_INPUT_ROUTING            (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        PR_SCP_OPT_ENG_GM_INPUT_ITEM_BOM_ROUTING   (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        PR_SCP_OPT_ENG_GM_INPUT_COBY_PROD_ITEM     (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        PR_SCP_OPT_ENG_GM_INPUT_SAFETY_STOCK       (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        PR_SCP_OPT_ENG_GM_INPUT_FROZEN_PLAN        (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        PR_SCP_OPT_ENG_GM_INPUT_HORIZON_CAL        (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);
        PR_SCP_OPT_ENG_GM_INPUT_AFTER_CORRECT      (V_PLAN_ID, V_DIVISION_ID, V_GROUP_ID, V_PLAN_START_YYYYMMDD, V_PLAN_END_YYYYMMDD);

        /* ------------------------------------------------------------------ */
        /* INPUT END                                                           */
        /* ------------------------------------------------------------------ */
        /*
        --EXEC PR_SCP_OPT_ENG_LOG_STATUS_PROC 'U',@V_PLAN_ID,NULL,NULL,'Y',NULL,NULL,NULL,NULL,NULL,NULL,NULL
        */
        V_DETAIL_END_DATE := SYSDATE;
        /*
        --EXEC PR_SCP_OPT_ENG_LOG_DTL_PROC 'U',@V_PLAN_ID,'STEP01',NULL,NULL,NULL,@V_DETAIL_END_DATE,NULL,'COMPLETED'
        */

    EXCEPTION
        /* ERROR LOG */
        /* ROLLBACK TRANSACTION PR_SCP_OPT_ENG_GM_RUN_MAIN_PROC; */
        WHEN OTHERS THEN
            V_MESSAGE_TEXT := SUBSTR(SQLERRM, 1, 1000);
            PR_SCP_OPT_ENG_LOG_CRE_PROC('I','INPUT',V_PLAN_ID,V_PROGRAM_NAME,'ERROR',NULL,V_MESSAGE_TEXT,NULL,V_PLAN_ID);
            RAISE_APPLICATION_ERROR(-20001, V_MESSAGE_TEXT);
    END;

    /* 종료 LOG */
    IF V_MESSAGE_TEXT IS NULL THEN
        PR_SCP_OPT_ENG_LOG_CRE_PROC('I','INPUT',V_PLAN_ID,V_PROGRAM_NAME,'END',NULL,NULL,NULL,V_PLAN_ID);
    END IF;

END;

PROCEDURE PR_SCP_OPT_ENG_INPUT_BUCKET_BATCH
(
    P_PLAN_ID                IN VARCHAR2
  , P_DIVISION_ID            IN VARCHAR2
  , P_GROUP_ID               IN VARCHAR2
  , P_PLAN_START_YYYYMMDD    IN VARCHAR2
  , P_PLAN_END_YYYYMMDD      IN VARCHAR2
)
IS
/*
 * Program ID   : PR_SCP_OPT_ENG_INPUT_BUCKET_BATCH
 * Description  : 엔진 입력 버킷(SCP_OPT_ENG_BUCKETS) 정보를 생성한다.
 *                배치 계획은 Daily 버킷만 계획 시작~종료일 범위로 생성한다.
 *
 * Program History
 *===================================================================================================
 *   Date         In Charge   Description
 *===================================================================================================
 * 2025.02.05     Y.S.H       Initial Release
 * 2026.09.14                 Batch Plan Data Daily 로만 생성
 * 2026.10.07     JCH         MSSQL -> Oracle 전환
 */
    V_PROGRAM_NAME   VARCHAR2(150 CHAR)  := 'PR_SCP_OPT_ENG_INPUT_BUCKET_BATCH';
    V_PLAN_ID        VARCHAR2(50 CHAR)   := P_PLAN_ID;
    V_MESSAGE_TEXT   VARCHAR2(1000 CHAR);
    V_DETAIL_DATE    DATE;
BEGIN

    /* 시작 로그 */
    PR_SCP_OPT_ENG_LOG_CRE_PROC('I', 'INPUT', V_PLAN_ID, V_PROGRAM_NAME, 'START', NULL, NULL, NULL, V_PLAN_ID);

    BEGIN
        ------------------------------------------------------------------------
        -- Data Insert Start
        -- 2026.09.14 Batch Plan Data Daily로만 생성
        ------------------------------------------------------------------------
        INSERT INTO SCP_OPT_ENG_BUCKETS_SN
        (
            PLAN_ID
          , BUCKET_NAME
          , START_DATE
          , INSERT_ID
          , INSERT_TIME
          , UPDATE_ID
          , UPDATE_TIME
        )
        SELECT  V_PLAN_ID
              , 'DAILY'          AS BUCKETLISTCODE
              , DAILY_DAY
              , V_PROGRAM_NAME
              , SYSDATE
              , V_PROGRAM_NAME
              , SYSDATE
        FROM  (
               SELECT  CAL.BASIS_YYYYMMDD    AS DAILY_DAY
                     , CAL.BASIS_START_DATE  AS WEEKLY_DAY
                     , GREATEST(CAL.BASIS_YYYYMM || '01', P_PLAN_START_YYYYMMDD) AS MONTH_DAY
                     , ROW_NUMBER() OVER (ORDER BY CAL.BASIS_YYYYMMDD) AS DAY_NUM
               FROM    SCM_SYS_CALENDAR_M CAL
               WHERE   CAL.BASIS_YYYYMMDD BETWEEN P_PLAN_START_YYYYMMDD AND P_PLAN_END_YYYYMMDD
              ) BK
        GROUP BY DAILY_DAY;

        ------------------------------------------------------------------------
        -- Data Insert End
        ------------------------------------------------------------------------

        COMMIT;

    EXCEPTION
        WHEN OTHERS THEN
            /* 오류가 나면 이 프로시저가 바꾼 내용만 되돌리고 로그를 남긴 뒤 종료한다
               (원본 MSSQL 과 동일하게 오류를 상위로 전파하지 않는다) */
            IF DBMS_TRANSACTION.LOCAL_TRANSACTION_ID IS NOT NULL THEN
                ROLLBACK;
            END IF;
            V_MESSAGE_TEXT := SUBSTR(SQLERRM, 1, 1000);
            PR_SCP_OPT_ENG_LOG_CRE_PROC('I', 'INPUT', V_PLAN_ID, V_PROGRAM_NAME, 'ERROR', NULL, V_MESSAGE_TEXT, NULL, V_PLAN_ID);
            V_DETAIL_DATE := SYSDATE;
            PR_SCP_OPT_ENG_LOG_DTL_PROC('U', V_PLAN_ID, 'STEP01', NULL, NULL, V_DETAIL_DATE, NULL, V_MESSAGE_TEXT, 'ERROR');
    END;

    /* 종료 로그 (오류가 없었을 때만) */
    IF V_MESSAGE_TEXT IS NULL THEN
        PR_SCP_OPT_ENG_LOG_CRE_PROC('I', 'INPUT', V_PLAN_ID, V_PROGRAM_NAME, 'END', NULL, NULL, NULL, V_PLAN_ID);
        PR_SCP_OPT_ENG_LOG_DTL_PROC('U', V_PLAN_ID, 'STEP01', NULL, NULL, NULL, NULL, NULL, NULL);
    END IF;

END;

PROCEDURE PR_SCP_OPT_ENG_INPUT_DELETE_PROC
(
     P_PLAN_ID              VARCHAR2
    ,V_DIVISION_ID          VARCHAR2
    ,V_GROUP_ID             VARCHAR2
    ,V_PLAN_START_YYYYMMDD  VARCHAR2
    ,V_PLAN_END_YYYYMMDD    VARCHAR2
)
/* ============================================================
 * Program ID   : PR_SCP_OPT_ENG_INPUT_DELETE_PROC
 * Description  : SCP OPT ENG 엔진 INPUT 데이터(MAIN/HISTORY _SN 계열) 삭제 (계열 접두 없는 공용 base 판본)
 * Program History
 *------------------------------------------------------------
 * Date          In Charge      Description
 *------------------------------------------------------------
 * 2025.02.05    Y.S.H          Initial Release
 * 2026.07.30    ZIONEX         [PJ202650304]  NextSCM Migration
 *                              (호출자 전수조사 결과 PR_SCP_OPT_ENG_RUN_MAIN_PROC /
 *                               3개 상위 RUN_MAIN 만 호출하는 하위 단계(nested-only)이므로
 *                               MSSQL 표준 컬럼 미사용, GTT/시퀀스 없음. 삭제 대상은 전부 단순 단일테이블 DELETE.
 * ============================================================ */
AS
    /* ---------------------------------------------------------------------- */
    /* Set Prameter */
    /* ---------------------------------------------------------------------- */
    V_PROGRAM_NAME  VARCHAR2(150 CHAR) := 'PR_SCP_OPT_ENG_INPUT_DELETE_PROC';
    V_PLAN_ID       VARCHAR2(50 CHAR)  := P_PLAN_ID;
    V_MESSAGE_TEXT  VARCHAR2(1000 CHAR);
    V_DETAIL_DATE   DATE;
BEGIN
    /* ---------------------------------------------------------------------- */
    /* Procedure 기본조건. */
    /* ---------------------------------------------------------------------- */


    /* SET TRANSACTION ISOLATION LEVEL READ COMMITTED; */

    /* ---------------------------------------------------------------------- */
    /* Step 3. SCP_OPT_ENG_ENGINE_DATA_CREATE_L_N 생성 */
    /* ---------------------------------------------------------------------- */
    PR_SCP_OPT_ENG_LOG_CRE_PROC('I','INPUT',V_PLAN_ID,V_PROGRAM_NAME,'START',NULL,NULL,NULL,V_PLAN_ID);

    /* ---------------------------------------------------------------------- */
    /* Transaction (START) */
    /* ---------------------------------------------------------------------- */
    /* BEGIN TRANSACTION SCP_OPT_ENG_RUN_MAIN_PROC; */
    /* ---------------------------------------------------------------------- */
    BEGIN
        /* ---------------------------------------------------------------------- */
        /* DELETE START FOR MAIN */
        /* ---------------------------------------------------------------------- */
        DELETE FROM SCP_OPT_ENG_PLAN_MASTER_SN               WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_BOD_SN                       WHERE PLAN_ID = P_PLAN_ID;
