)
IS
/*
 * Program ID   : PR_SCP_OPT_ENG_INPUT_DELETE_PROC_BATCH
 * Description  : 엔진 입력/이력 테이블에서 해당 PLAN_ID 의 이전 데이터를 모두 삭제한다.
 *
 * Program History
 *===================================================================================================
 *   Date         In Charge   Description
 *===================================================================================================
 * 2025.02.05     Y.S.H       Initial Release
 * 2026.10.07     JCH         MSSQL -> Oracle 전환
 */
    V_PROGRAM_NAME   VARCHAR2(150 CHAR)  := 'PR_SCP_OPT_ENG_INPUT_DELETE_PROC_BATCH';
    V_PLAN_ID        VARCHAR2(50 CHAR)   := P_PLAN_ID;
    V_MESSAGE_TEXT   VARCHAR2(1000 CHAR);
