        DELETE FROM SCP_OPT_ENG_RESOURCE_EVERY_CALENDAR_SN   WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_INCOMING_STOCK_SN            WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_DEMAND_SN                    WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_BUCKETS_SN                   WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_COBY_PROD_ITEM_SN            WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_FROZEN_PLAN_SN               WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_GOALS_SN                     WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_OBJECTIVES_SN                WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_OBJECTIVE_GOAL_MAPPING_SN    WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_PHASES_SN                    WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_RESOURCE_HORIZON_CALENDAR_SN WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_SAFETY_STOCK_SN              WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_SCHEDULED_MOVE_SN            WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_MODEL_LIST_N_SN              WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_INCOMING_STOCK_XTR_SN        WHERE PLAN_ID = P_PLAN_ID;
        ------------------------------------------------------------------------
        -- DELETE START FOR HISTORY
        ------------------------------------------------------------------------
        DELETE FROM SCP_OPT_ENG_PLAN_MASTER_H_SN               WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_BOD_H_SN                       WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_BOM_H_SN                       WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_ITEM_SITE_H_SN                 WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_ROUTING_H_SN                   WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_ITEM_BOM_ROUTING_H_SN          WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_RESOURCE_H_SN                  WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_ROUTING_RESOURCE_H_SN          WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_RESOURCE_EVERY_CALENDAR_H_SN   WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_INCOMING_STOCK_H_SN            WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_DEMAND_H_SN                    WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_BUCKETS_H_SN                   WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_COBY_PROD_ITEM_H_SN            WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_FROZEN_PLAN_H_SN               WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_GOALS_H_SN                     WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_OBJECTIVES_H_SN                WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_OBJECTIVE_GOAL_MAPPING_H_SN    WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_PHASES_H_SN                    WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_RESOURCE_HORIZON_CALENDAR_H_SN WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_SAFETY_STOCK_H_SN              WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_SCHEDULED_MOVE_H_SN            WHERE PLAN_ID = P_PLAN_ID;
        DELETE FROM SCP_OPT_ENG_MODEL_LIST_N_H_SN              WHERE PLAN_ID = P_PLAN_ID;
        ------------------------------------------------------------------------
        -- DELETE END
        ------------------------------------------------------------------------

        COMMIT;

    EXCEPTION
        WHEN OTHERS THEN
            /* 오류가 나면 이 프로시저가 바꾼 내용만 되돌리고 로그를 남긴 뒤 종료한다
               (원본 MSSQL 과 동일하게 오류를 상위로 전파하지 않는다) */
            IF DBMS_TRANSACTION.LOCAL_TRANSACTION_ID IS NOT NULL THEN
                ROLLBACK;
            END IF;
            V_MESSAGE_TEXT := SUBSTR(SQLERRM, 1, 1000);
            PR_SCP_OPT_ENG_LOG_CRE_PROC('I', 'INPUT', V_PLAN_ID, V_PROGRAM_NAME, 'ERROR', NULL, V_MESSAGE_TEXT, NULL, V_PLAN_ID);
            V_DETAIL_DATE := SYSDATE;
            PR_SCP_OPT_ENG_LOG_DTL_PROC('U', V_PLAN_ID, 'STEP01', NULL, NULL, V_DETAIL_DATE, NULL, V_MESSAGE_TEXT, 'ERROR');
    END;

    /* 종료 로그 (오류가 없었을 때만) */
    IF V_MESSAGE_TEXT IS NULL THEN
        PR_SCP_OPT_ENG_LOG_CRE_PROC('I', 'INPUT', V_PLAN_ID, V_PROGRAM_NAME, 'END', NULL, NULL, NULL, V_PLAN_ID);
        PR_SCP_OPT_ENG_LOG_DTL_PROC('U', V_PLAN_ID, 'STEP01', NULL, NULL, NULL, NULL, NULL, NULL);
    END IF;

END;

PROCEDURE PR_SCP_OPT_ENG_INPUT_DEMAND
(
     P_PLAN_ID              VARCHAR2
    ,V_DIVISION_ID          VARCHAR2
    ,V_GROUP_ID             VARCHAR2
    ,V_PLAN_START_YYYYMMDD  VARCHAR2
    ,V_PLAN_END_YYYYMMDD    VARCHAR2
)
/* ============================================================
 * Program ID   : PR_SCP_OPT_ENG_INPUT_DEMAND
 * Description  : SCP OPT ENG 엔진 입력 - Demand 생성 (계열 접두 없는 base 판본)
 *                (UI 수정수요(SCP_OPMZ_DMD_ADJ) 선반영 -> DM Net Demand -> 소형(40) Shipment Plan Semi 수요를
 *                 @DM_INS_TEMP 에 모으고, LOOKUP 의 Demand 뭉치기 타입(A/B/C/D)별로 묶어
 *                 SCP_OPT_ENG_DEMAND_SN 에 적재한 뒤 Demand Group 과 Target Date 를 반영한다.
 *                 원본 DEMAND 는 SCP_OPT_ENG_DEMAND_ORIGIN_SN 에 백업한다.)
 * Program History
 *------------------------------------------------------------
 * Date          In Charge      Description
 *------------------------------------------------------------
 * 2025.02.07    Taehyun        Initial Release
 * 2025.03.24                   Bloack Target Date & Add Monlty Block for Speed
 * 2025.05.07    Philsu Park    소형 Demand Input 분기 추가를 위한 Snapshot data count.
 * 2025.05.19    Philsu Park    Demand 제외 처리 시 To 구간 제약 추가 적용.(ATT3)
 * 2025.05.26    김태현선임     상현 책임님 요청으로 SALES SITE 는 MEDEL LIST 를 고려하지 않도록 수정
 * 2025.06.09    Philsu Park    Demand 뭉치기 대상 마킹을 위한 Temp Update / A Type 은 별도 처리
 * 2025.06.10    Philsu Park    원본 DEMAND 를 백업한다.(동일 PLAN_ID 로 삭제 후 INSERT)
 * 2025.06.11    Philsu Park    B Type 별도 처리.
 * 2025.06.18    Philsu Park    Due Date 가 Plan 구간 바깥에 있으면 안되기 때문에 LEAST 처리.
 * 2025.06.19    김태현         DEMAND 에 필요한 SEMI 정보는 최신 SCP 계획을 가져오도록 변경
 * 2025.07.09    김태현 선임    UI 에서 수정한 수요 데이터 선 반영
 * 2025.07.15    Philsu Park    소형 Shipment SEMI 에도 Priority 값 반영.
 * 2025.07.24    Philsu Park    DemandTargetDate LOOKUP 관리형태를 YMD 로 변경.
 * 2025.08.12    Philsu Park    Workbench 에서 0 으로 들어온 케이스 제외.
 * 2025.08.25    Philsu Park    A Type 의 value 기준을 주차가 아닌 일로 변경 / C Type 추가.
 * 2025.08.27    Philsu Park    C Type 추가.
 * 2025.08.28    Philsu Park    DIO_QTY 를 계산하는 첫달 찾는 로직은 FIRST_ORDER 로 찾게 변경.
 * 2025.09.15    Philsu Park    Full Capa 입력값이 있으면 해당 값 활용, 없으면 Capa 정보에서 찾아옴.
 * 2025.09.30    Philsu Park    워크벤치 반영 재고와 동일 DEMAND_ID 는 제외
 * 2025.10.15    T.K.KIM        워크벤치에서 0 으로 들어온 데이터는 원천에서 안 가져오게하고 삭제
 * 2025.11.10    Minyong Lee    소형 Demand 제외 조건에 Stage 추가 적용을 위한 JOIN Depth 변경
 * 2025.11.17    Minyong Lee    Demand Exception Lookup -> UI 전환
 * 2025.11.18    Minyong Lee    Sales Site Priority Lookup -> UI 전환
 * 2025.12.15    jongykim2      Demand Group Master
 * 2026.03.09    Minyong Lee    D Type 추가.
 * 2026.07.30    ZIONEX         [PJ202650304] NextSCM Migration
 * --EXEC PR_SCP_OPT_ENG_INPUT_DEMAND 'PLAN_ID_001'
 * ============================================================ */
AS
    /* ---------------------------------------------------------------------- */
    /*  Procedure 기본조건. */


    /*    SET TRANSACTION ISOLATION LEVEL READ COMMITTED;     (Oracle 기본 격리수준과 동일) */
    /* ---------------------------------------------------------------------- */
    /* ---------------------------------------------------------------------- */
    /*  Set Param for Log */
    /* ---------------------------------------------------------------------- */
    V_PROGRAM_NAME           VARCHAR2(150 CHAR) := 'PR_SCP_OPT_ENG_INPUT_DEMAND';
    V_PLAN_ID                VARCHAR2(50 CHAR)  := P_PLAN_ID;
    V_MESSAGE_TEXT           VARCHAR2(1000 CHAR);
    MAX_TUESDAY              VARCHAR2(8 CHAR);
    /* ---------------------------------------------------------------------- */
    /*  Set Param for Biz */
    /* ---------------------------------------------------------------------- */
    V_DETAIL_DATE            DATE;
    P_PLAN_NAME              VARCHAR2(8 CHAR);
    D_PLAN_NAME              DATE;
    V_DEMAND_CUTOFF_DAY      VARCHAR2(8 CHAR);
    V_DM_MAX_VERSION         VARCHAR2(200 CHAR);

    V_START_WEEK             NUMBER(10);
    V_PLAN_TYPE              VARCHAR2(20 CHAR);
    V_SHIP_FROZEN            NUMBER(10);
    V_SHIP_FROZEN_DAY        VARCHAR2(8 CHAR);

    V_PROD_FROZEN_END_YMD    VARCHAR2(8 CHAR);

    V_SCP_PLAN_DATE          VARCHAR2(8 CHAR);
    V_SCP_PLAN_TYPE          VARCHAR2(8 CHAR);
    V_SCP_PLAN_SEQ           VARCHAR2(8 CHAR);
    V_CNT                    NUMBER(10);

    V_PLAN_END_YYYYMMDD_ORI  VARCHAR2(20 CHAR) := TO_CHAR(TO_DATE(V_PLAN_END_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD');

    V_SHIPMENT_SNAP_CNT      NUMBER(10);

    /* DEMAND GROUP       : @DM_TEMP        -> GT_OPT_ENG_DM_DMTMP */
    /*  셀 생산지 버퍼 추가 : @CELL_PROD_SITE -> GT_OPT_ENG_DM_CELLPROD */
    /* DEMAND INSERT TEMP  : @DM_INS_TEMP    -> GT_OPT_ENG_DM_DM_INS */
BEGIN
    /* 2025.02.07 Taehyun Initial Release */
    /* ---------------------------------------------------------------------- */
    /*  MSSQL 테이블변수는 매 실행 새 인스턴스이므로 GTT 는 진입부에서 DELETE 로 초기화한다. */
    /* ---------------------------------------------------------------------- */
    DELETE FROM GT_OPT_ENG_DM_DM_INS;
    DELETE FROM GT_OPT_ENG_DM_DMTMP;
    DELETE FROM GT_OPT_ENG_DM_CELLPROD;

    /* ---------------------------------------------------------------------- */
    /*  Step 3. SCP_OPT_ENG_ENGINE_DATA_CREATE_L_N 생성 */
    /* ---------------------------------------------------------------------- */
    PR_SCP_OPT_ENG_LOG_CRE_PROC('I','INPUT',V_PLAN_ID,V_PROGRAM_NAME,'START',NULL,NULL,NULL,V_PLAN_ID);

    /* ---------------------------------------------------------------------- */
    /*  Transaction (START) */
    /* ---------------------------------------------------------------------- */
    /* BEGIN TRANSACTION SCP_OPT_ENG_RUN_MAIN_PROC; */
    /* ---------------------------------------------------------------------- */
    BEGIN
    /* ---------------------------------------------------------------------- */
    /*  Get Plan Mater Info */
    /* ---------------------------------------------------------------------- */

    /* 2025.06.19 김태현 : DEMAND에 필요한 SEMI 정보는 FROZEN 계획을 SSP로 선택하거나 SCP 다른 버전을 선택했더라도, 최신 SCP 계획을 가져오는 것이 맞음/재욱 책임님 확인 사항 */
        BEGIN
            SELECT SUBSTR(A.PLAN_START_YYYYMMDD, 1, 8)
                 , SUBSTR(A.PLAN_TYPE, 1, 8)
                 , SUBSTR(TO_CHAR(A.PLAN_SEQ), 1, 8)
              INTO V_SCP_PLAN_DATE
                 , V_SCP_PLAN_TYPE
                 , V_SCP_PLAN_SEQ
            FROM  (SELECT DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, PLAN_SEQ, PLAN_TYPE_ORDER, CONFIRM_FLAG
                    FROM   SCP_PLAN_VERSION_V
                    WHERE  DIVISION_ID          = V_DIVISION_ID
                    AND    PLAN_START_YYYYMMDD  = TO_CHAR(FN_NEXT_DAY(TO_DATE(V_PLAN_START_YYYYMMDD, 'YYYYMMDD'), 'MON') - 7, 'YYYYMMDD') /*  해당 주 월요일 YYYYMMDD */
                    ORDER BY PLAN_TYPE_ORDER DESC, CONFIRM_FLAG DESC, PLAN_SEQ DESC
                    ) A
            WHERE ROWNUM = 1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN NULL;
        END;

        BEGIN
            SELECT  TO_NUMBER(ISO_WEEK)
              INTO  V_START_WEEK
            FROM    SCM_SYS_CALENDAR_M
            WHERE   BASIS_YYYYMMDD = V_PLAN_START_YYYYMMDD;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN NULL;
            WHEN TOO_MANY_ROWS THEN NULL;
        END;

        BEGIN
            SELECT  TO_NUMBER(SEGMENT4)
              INTO  V_SHIP_FROZEN
            FROM    SCP_OPMZ_LOOKUP_MASTER_DETAIL LV
            WHERE   LOOKUP_TYPE = 'SCP_OPT_SHIP_FROZEN'
            AND     VALID_YN    = 'Y'
            AND     SEGMENT1    = V_DIVISION_ID
            AND     SEGMENT2    = V_GROUP_ID
            /* AND     SEGMENT3    = 'PR' --임시 */
            AND     SEGMENT3    = V_SCP_PLAN_TYPE
            AND     ROWNUM      = 1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN NULL;
        END;

        V_SHIP_FROZEN_DAY := TO_CHAR(TO_DATE(V_SCP_PLAN_DATE, 'YYYYMMDD') + NVL(V_SHIP_FROZEN, 0), 'YYYYMMDD');

        BEGIN
            SELECT  M.FROZEN_END_DATE
              INTO  V_PROD_FROZEN_END_YMD
            FROM    SCP_OPT_ENG_FROZEN_MASTER_SN M
            WHERE   M.PLAN_ID  = V_PLAN_ID
            AND     M.STAGE = 'ASSY'
            AND     ROWNUM = 1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN NULL;
        END;

        /* ---------------------------------------------------------------------- */
        /*  Set Param for Demand */
        /* ---------------------------------------------------------------------- */
        SELECT  MAX(BASIS_YYYYMMDD)
          INTO  MAX_TUESDAY
        FROM    SCM_SYS_CALENDAR_M
        WHERE   BASIS_YYYYMMDD <= TO_CHAR(SYSDATE, 'YYYYMMDD')
        AND     DAYOFWEEK = 'TUE';

        P_PLAN_NAME := V_PLAN_START_YYYYMMDD; /* CONVERT(CHAR(8), DATEADD(DD, -7, DBO.FN_NEXT_DAY(GETDATE(), 'MON')), 112); -- 당주 월요일 YYYYMMDD */
        D_PLAN_NAME := TO_DATE(P_PLAN_NAME, 'YYYYMMDD') ;/* = CONVERT(CHAR(8), DATEADD(DD, -6, DBO.FN_NEXT_DAY(GETDATE(), 'MON')), 112); -- 당주 화요일 YYYYMMDD */
        SELECT  NVL(MAX(P.CUTOFF_YYYYMMDD), MAX_TUESDAY)
          INTO  V_DEMAND_CUTOFF_DAY
                                    /* , CONVERT(CHAR(8), DATEADD(DD, -6, DBO.FN_NEXT_DAY(GETDATE(), 'MON')), 112)) -- 당주 화요일 YYYYMMDD */
                                    FROM   DM_PLN_NET_DEMAND P
                                    WHERE  P.DIVISION_ID      = V_DIVISION_ID
                                    AND    P.CUTOFF_YYYYMMDD >= TO_CHAR(D_PLAN_NAME - 3, 'YYYYMMDD') /*  월요일 기준 최근 3일 이내 */
                                    AND    P.CUTOFF_YYYYMMDD <= TO_CHAR(D_PLAN_NAME + 6, 'YYYYMMDD'); /*  해당 주차 일요일 이전 */
        /* ---------------------------------------------------------------------- */
        SELECT  MAX(P.VERSION_NO)
          INTO  V_DM_MAX_VERSION
        FROM    DM_PLN_NET_DEMAND P
        WHERE   P.DIVISION_ID      = V_DIVISION_ID
        AND     P.CUTOFF_YYYYMMDD  = V_DEMAND_CUTOFF_DAY;
        /* ---------------------------------------------------------------------- */
        /*  셀 생산지 버퍼 추가 */
        /* ---------------------------------------------------------------------- */
        INSERT INTO GT_OPT_ENG_DM_CELLPROD
             ( SALES_SITE_ID
             , ITEM_ID
             )
        SELECT  SEGMENT3 AS SALES_SITE_ID
               ,SEGMENT4 AS ITEM_ID
        FROM    SCP_OPMZ_LOOKUP_MASTER_DETAIL
        WHERE   LOOKUP_TYPE = 'SCP_OPT_ENG_CONST_CELL_PROD_SITE'
        AND     SEGMENT1 = V_DIVISION_ID
        AND     SEGMENT2 = V_GROUP_ID;
        /* ---------------------------------------------------------------------- */
        /*  임시 */
        /* ---------------------------------------------------------------------- */
        /* SET @P_PLAN_NAME			= '20250310' */
        /* SET @V_DEMAND_CUTOFF_DAY	= '20250311' */
        /* SET @V_DM_MAX_VERSION		= 'MF_W_20250313_V001'     --3월 2주차 고정, 임시 */
        /* SET @V_DM_MAX_VERSION		= 'MF_W_20250311_V001'     --3월 2주차 고정, 임시 */
        /* ---------------------------------------------------------------------- */
        /*  2025.05.07 Philsu Park. */
        /*  소형 Demand Input 분기 추가를 위한 Snapshot data count. */
        /*  1. 동 주차의 Snapshot Data가 존재하는 경우 Snapshot 사용. */
        /*  2. 동 주차의 Snapshot Data가 존재하지 않는 경우 기존 Rule 적용(Shipment Plan Semi) */
        /* ---------------------------------------------------------------------- */
        BEGIN
            SELECT  COUNT(*)
              INTO  V_SHIPMENT_SNAP_CNT
            FROM    SCP_OPT_ENG_SHIPMENT_PLAN_SEMI_SNAPSHOT_SN S
            WHERE   S.DIVISION_ID           = V_DIVISION_ID
            AND     S.PLAN_START_YYYYMMDD   = V_PLAN_START_YYYYMMDD;
        END;
        /* ---------------------------------------------------------------------- */
        /*  Data Insert Start */
        /* ---------------------------------------------------------------------- */
        /* ---------------------------------------------------------------------- */
        /*  0. UI에서 수정한 수요 데이터 선 반영/김태현 선임/20250709 */
        /* ---------------------------------------------------------------------- */
        INSERT INTO GT_OPT_ENG_DM_DM_INS
            (PLAN_ID
            ,DEMAND_ID
            ,BUFFER_ID
            ,DEMAND_GROUP
            ,DUE_DATE
            ,TARGET_DATE
            ,SALES_CUTOFF_DATE
            ,EXPIRY_DATE
            ,PRIORITY
            ,QUANTITY
            ,PRIORITY_GROUP
            ,CUSTOMER_ID
            ,ALLOW_SHORT
            ,ATTRIBUTE1
            ,ATTRIBUTE2
            ,ATTRIBUTE3
            ,ATTRIBUTE4
            ,ATTRIBUTE5
            ,ATTRIBUTE6
            ,ATTRIBUTE7
            ,ATTRIBUTE8
            ,ATTRIBUTE9
            ,ATTRIBUTE10
            ,ATTRIBUTE11
            ,ATTRIBUTE12
            ,ATTRIBUTE13
            ,ATTRIBUTE14
            ,ATTRIBUTE15
            )
        SELECT  V_PLAN_ID
               ,AD.SCM_SITE_ID||'::'||AD.ITEM_ID||'::'||AD.STAGE||'@'||AD.INCOTERMS||'@'||AD.PROJECT_CODE||'::'||AD.DUE_DATE||'::'||'-'||'::'||AD.FCST_TYPE||CASE WHEN NVL(AD.CELL_PROD_SITE_ID,'-') = '-' THEN '' ELSE '::'||AD.CELL_PROD_SITE_ID END AS DEMAND_ID
               ,AD.SCM_SITE_ID||'::'||AD.ITEM_ID||'::'||AD.STAGE||'@'||AD.INCOTERMS||'@'||AD.PROJECT_CODE                                                                                                                AS BUFFER_ID
               /* ,SCM_SITE_ID+'::'+AD.ITEM_ID+'::'+AD.STAGE+'@'+INCOTERMS+'@'+PROJECT_CODE+IIF(ISNULL(AD.CELL_PROD_SITE_ID,'-') = '-','','::'+AD.CELL_PROD_SITE_ID)                                       AS BUFFER_ID */
               /*  MSSQL 결합 연산자는 NULL 을 전파한다. PRIORITY 는 TOSITE PRIORITY 아우터조인 유래라 NULL 가능하므로 CASE 로 재현한다. */
               ,CASE WHEN AD.PRIORITY IS NULL THEN NULL ELSE AD.INCOTERMS||'@'||'D'||AD.PRIORITY END      AS DEMAND_GROUP
               ,AD.DUE_DATE                                                                AS DUE_DATE
               ,NULL                                                                       AS TARGET_DATE
               ,NULL                                                                       AS SALES_CUTOFF_DATE
               ,NULL                                                                       AS EXPIRY_DATE
               ,AD.PRIORITY                                                                AS PRIORITY
               ,AD.QTY                                                                     AS QUANTITY
               ,CASE WHEN AD.PRIORITY IS NULL THEN NULL ELSE 'D'||AD.PRIORITY END          AS PRIORITY_GROUP
               ,NULL                                                                       AS CUSTOMER_ID
               ,NULL                                                                       AS ALLOW_SHORT
               ,AD.SCM_SITE_ID                                                             AS ATTRIBUTE1
               ,AD.ITEM_ID                                                                 AS ATTRIBUTE2
               ,AD.STAGE                                                                   AS ATTRIBUTE3
               ,AD.INCOTERMS                                                               AS ATTRIBUTE4
               ,AD.PROJECT_CODE                                                            AS ATTRIBUTE5
               ,NULL                                                                       AS ATTRIBUTE6
               ,NULL                                                                       AS ATTRIBUTE7
               ,AD.FCST_TYPE                                                               AS ATTRIBUTE8
               ,NULL                                                                       AS ATTRIBUTE9
               ,NULL                                                                       AS ATTRIBUTE10
               ,NULL                                                                       AS ATTRIBUTE11
               ,NULL                                                                       AS ATTRIBUTE12
               ,NULL                                                                       AS ATTRIBUTE13
               ,NULL                                                                       AS ATTRIBUTE14
               ,NULL                                                                       AS ATTRIBUTE15
        FROM(
            SELECT  DA.DIVISION_ID       AS DIVISION_ID
                   ,DA.PROJECT_CODE      AS PROJECT_CODE
                   ,DA.SCM_SITE_ID       AS SCM_SITE_ID
                   ,DA.ITEM_ID           AS ITEM_ID
                   ,DA.FCST_TYPE         AS FCST_TYPE
                   ,CASE WHEN NVL(MSE.VMI_YN, 'N' ) = 'Y' THEN 'DAP' ELSE DA.INCOTERMS END AS INCOTERMS
                   ,DA.CELL_PROD_SITE_ID AS CELL_PROD_SITE_ID
                   ,DA.DUE_DATE          AS DUE_DATE
                   ,SUM(DA.CHG_QTY)      AS QTY
                   ,TP.PRIORITY          AS PRIORITY
                   ,CASE   WHEN FI.OPERATION_GROUP = 'P' AND FI.FLOW_ID = 'P9500'                 THEN 'PACKBIZ'
                           WHEN FI.OPERATION_GROUP = 'P' AND FI.FLOW_ID = 'P5500'                 THEN 'MDLEBIZ'
                           WHEN FI.OPERATION_GROUP = 'P' AND FI.FLOW_ID NOT IN ('P5500', 'P9500') THEN 'SUBMDLEBIZ'
                           WHEN FI.OPERATION_GROUP = 'A'                                          THEN 'CELLBIZ'
                    ELSE '-' END AS STAGE


        FROM    SCP_OPMZ_DMD_ADJ DA
                INNER JOIN (SELECT DISTINCT DIVISION_ID, ITEM_ID, OPERATION_GROUP, FLOW_ID, ATTRIBUTE8
                            FROM   SCP_MST_FINAL_ITEM
                            WHERE  DIVISION_ID = V_DIVISION_ID
                            AND   ((DIVISION_ID  = '40' AND OPERATION_GROUP IN ('A') )      /*  소형은 CEll Biz 용 Demand 만 처리 */
                                     OR  (DIVISION_ID <> '40' AND OPERATION_GROUP IN ('A', 'P') )
                                  )
                           ) FI
                    ON    DA.ITEM_ID     = FI.ITEM_ID
                    AND   DA.DIVISION_ID = FI.DIVISION_ID
                /* ---------------------------------------------------------------------- */
                LEFT JOIN ( /*  VMI 대상 SITE 조회 */
                            SELECT DIVISION_ID, SCM_SITE_ID, VMI_YN
                            FROM   SCM_MST_SITE
                            WHERE  DIVISION_ID = V_DIVISION_ID
                                AND SITE_TYPE   = 'SALES'
                                AND  VALID_YN    = 'Y'
                                AND  VMI_YN      = 'Y'
                            ) MSE
                    ON   DA.DIVISION_ID      = MSE.DIVISION_ID
                    AND  DA.SCM_SITE_ID      = MSE.SCM_SITE_ID
                LEFT OUTER JOIN ( /* TOSITE PRIORITY CONSTRAINT */
                                    /* SELECT   SEGMENT4   AS ITEM_ID */
                                    /*         ,SEGMENT5   AS TO_SITE */
                                    /*         ,SEGMENT6   AS PRIORITY */
                                    /*         ,ATTRIBUTE1 AS FROM_DATE */
                                    /*         ,ATTRIBUTE2 AS TO_DATE */
                                    /* FROM    SCP_OPMZ_LOOKUP_MASTER_DETAIL WITH(NOLOCK) */
                                    /* WHERE   LOOKUP_TYPE = 'SCP_OPT_ENG_CONST_TOSITE_PRIORITY_NEW' */
                                    /* AND     SEGMENT2    = @V_DIVISION_ID */
                                    /* AND     SEGMENT3    = @V_GROUP_ID */
                                    /* AND     VALID_YN    = 'Y' */

                                    /*  2025.11.18 Minyong Lee : Sales Site Priority Lookup -> UI 전환 */
                                    SELECT  P.ITEM_ID       AS ITEM_ID
                                          , P.SCM_SITE_ID   AS TO_SITE
                                          , TO_CHAR(P.PRIO_RANK)     AS PRIORITY
                                          , P.FROM_YYYYMMDD   AS FROM_DATE
                                          , P.TO_YYYYMMDD     AS TO_DATE
                                    FROM    SCP_OPMZ_SALES_SITE_PRIORITY P
                                          , SCP_OPMZ_PLAN_GR_M PG
                                    WHERE   1=1
                                    AND     P.OPMZ_PLAN_GR_ID = PG.OPMZ_PLAN_GR_ID
                                    AND     PG.VALID_YN = 'Y'
                                    AND     P.VALID_YN = 'Y'
                                    AND     P.DIVISION_ID = V_DIVISION_ID
                                    AND     PG.OPMZ_PLAN_GR_NAME = V_GROUP_ID
                                ) TP
                    ON  DA.SCM_SITE_ID = TP.TO_SITE
                    AND DA.ITEM_ID     = TP.ITEM_ID
                    AND DA.DUE_DATE BETWEEN TP.FROM_DATE AND TP.TO_DATE

            WHERE   DA.VERSION_NO      = V_DM_MAX_VERSION
            AND     DA.DIVISION_ID     = V_DIVISION_ID
            AND     DA.CUTOFF_YYYYMMDD = V_DEMAND_CUTOFF_DAY
            AND     DA.DUE_DATE        >= P_PLAN_NAME
            AND     DA.DUE_DATE        <  V_PLAN_END_YYYYMMDD
            AND     DA.CHG_QTY         >= 0
            AND (   (V_DIVISION_ID = '40'
                                           /* 상현 책임님 요청으로 SALES SITE는 MEDEL LIST를 고려하지 않도록 수정/20250526/김태현선임 */
                                           /* AND CONCAT(A.SCM_SITE_ID,A.ITEM_ID) IN (SELECT DISTINCT CONCAT (SCM_SITE_ID,ITEM_ID) */
                                           /*                                         FROM    SCP_OPT_ENG_MODEL_LIST_N_SN WITH(NOLOCK) */
                                           /*                                         WHERE   PLAN_ID = @V_PLAN_ID */
                                           /*                                        ) */
                                           AND DA.CELL_PROD_SITE_ID||DA.ITEM_ID IN (SELECT DISTINCT SCM_SITE_ID||ITEM_ID
                                                                                         FROM    SCP_OPT_ENG_MODEL_LIST_N_SN
                                                                                         WHERE   PLAN_ID = V_PLAN_ID
                                                                                         )
                    )
                 OR (V_DIVISION_ID != '40' AND  DA.ITEM_ID IN (SELECT DISTINCT ITEM_ID
                                                               FROM    SCP_OPT_ENG_MODEL_LIST_N_SN
                                                               WHERE   PLAN_ID = V_PLAN_ID
                                                              )
                    )
               )
            GROUP BY DA.DIVISION_ID, DA.SCM_SITE_ID, DA.ITEM_ID, DA.INCOTERMS, DA.DUE_DATE, FI.FLOW_ID, FI.OPERATION_GROUP, TP.PRIORITY, DA.FCST_TYPE, DA.PROJECT_CODE, DA.CELL_PROD_SITE_ID, MSE.VMI_YN
            )AD
                LEFT OUTER JOIN GT_OPT_ENG_DM_CELLPROD CPS
                    ON  1=1
                    AND AD.SCM_SITE_ID = CPS.SALES_SITE_ID
                    AND AD.ITEM_ID     = CPS.ITEM_ID
                /* ---------------------------------------------------------------------- */
                /*  DEMAND 제외 대상 CELL ITEM 정보 : WHERE 절에서 제외 조건 처리 */
                /*  2025.05.19 Philsu Park: Demand 제외 처리 시 To 구간 제약 추가 적용.(ATT3) */
                /*  2025.11.10 Minyong Lee : 소형 Demand 제외 조건에 Stage 추가 적용을 위한 JOIN Depth 변경 */
                /* ---------------------------------------------------------------------- */
                LEFT JOIN (
                          /* SELECT SEGMENT2   AS DIVISION_ID */
                          /*      , SEGMENT3   AS SCM_SITE_ID */
                          /*      , SEGMENT4   AS ITEM_ID */
                          /*      , SEGMENT5   AS GROUP_ID */
                          /*      , ATTRIBUTE1 AS STAGE */
                          /*      , CASE */
                          /*            WHEN ISNULL(ATTRIBUTE2, '') = '' THEN @V_PLAN_START_YYYYMMDD -- NULL 이면 전 구간 제외 */
                          /*            ELSE ATTRIBUTE2 */
                          /*        END AS START_DATE  -- PLAN 제외 시작일자 */
                          /*      , CASE */
                          /*            WHEN ISNULL(ATTRIBUTE3, '') = '' THEN @V_PLAN_END_YYYYMMDD -- NULL 이면 전 구간 제외 */
                          /*            ELSE ATTRIBUTE3 */
                          /*        END AS END_DATE  -- PLAN 제외 끝일자 */
                          /* FROM   SCP_OPMZ_LOOKUP_MASTER_DETAIL LV WITH(NOLOCK) */
                          /* WHERE  LOOKUP_TYPE = 'SCP_OPT_ENG_DEMAND_EXCEPTION' */
                          /* AND    VALID_YN    = 'Y' */
                          /* AND    SEGMENT2    = @V_DIVISION_ID */
                          /* AND    SEGMENT5    = @V_GROUP_ID */

                            /*  2025.11.17 Minyong Lee : Demand Exception Lookup -> UI 전환 */
                            SELECT  D.DIVISION_ID           AS DIVISION_ID
                                  , D.SCM_SITE_ID           AS SCM_SITE_ID
                                  , D.ITEM_ID               AS ITEM_ID
                                  , PG.OPMZ_PLAN_GR_NAME    AS GROUP_ID
                                  , D.STAGE                 AS STAGE
                                  , CASE
                                        WHEN RTRIM(D.FROM_YYYYMMDD) IS NULL THEN V_PLAN_END_YYYYMMDD
                                        ELSE D.FROM_YYYYMMDD
                                    END                     AS START_DATE
                                  , CASE
                                        WHEN RTRIM(D.TO_YYYYMMDD) IS NULL THEN V_PLAN_END_YYYYMMDD
                                        ELSE D.TO_YYYYMMDD
                                    END                     AS END_DATE
                            FROM    SCP_OPMZ_DEMAND_EXCEPTION D
                                  , SCP_OPMZ_PLAN_GR_M PG
                            WHERE   1=1
                            AND     D.OPMZ_PLAN_GR_ID = PG.OPMZ_PLAN_GR_ID
                            AND     PG.VALID_YN = 'Y'
                            AND     D.VALID_YN = 'Y'
                            AND     D.DIVISION_ID = V_DIVISION_ID
                            AND     PG.OPMZ_PLAN_GR_NAME = V_GROUP_ID
                          ) DE
                    ON  AD.SCM_SITE_ID   = DE.SCM_SITE_ID
                    AND AD.ITEM_ID       = DE.ITEM_ID
                    AND ((AD.DIVISION_ID = '40' AND AD.STAGE = DE.STAGE) OR  /*  소형의 경우 JOIN 조건에 STAGE까지 고려 */
                         AD.DIVISION_ID <> '40')
            /*  DEMAND 제외 대상 처리 */
            WHERE   1=1
            AND     (RTRIM(DE.ITEM_ID) IS NULL OR                                                                 /*  수요 제외 대상이 아니거나 */
                     (RTRIM(DE.ITEM_ID) IS NOT NULL AND (AD.DUE_DATE < DE.START_DATE OR AD.DUE_DATE > DE.END_DATE))); /*  수요 제외 대상이어도 기간 범위 밖인 것 */
        /* ---------------------------------------------------------------------- */
        /*  1. DM Demand Insert */
        /*  2025.09.30 Philsu Park: 워크벤치 반영 재고와 동일 DEMAND_ID는 제외(@DM_INS_TEMP) */
        /* ---------------------------------------------------------------------- */
        INSERT INTO GT_OPT_ENG_DM_DM_INS
            (PLAN_ID
            ,DEMAND_ID
            ,BUFFER_ID
            ,DEMAND_GROUP
            ,DUE_DATE
            ,TARGET_DATE
            ,SALES_CUTOFF_DATE
            ,EXPIRY_DATE
            ,PRIORITY
            ,QUANTITY
            ,PRIORITY_GROUP
            ,CUSTOMER_ID
            ,ALLOW_SHORT
            ,ATTRIBUTE1
            ,ATTRIBUTE2
            ,ATTRIBUTE3
            ,ATTRIBUTE4
            ,ATTRIBUTE5
            ,ATTRIBUTE6
            ,ATTRIBUTE7
            ,ATTRIBUTE8
            ,ATTRIBUTE9
            ,ATTRIBUTE10
            ,ATTRIBUTE11
            ,ATTRIBUTE12
            ,ATTRIBUTE13
            ,ATTRIBUTE14
            ,ATTRIBUTE15
            )
        SELECT   DM.PLAN_ID
                ,DM.DEMAND_ID
                ,DM.BUFFER_ID
                ,DM.DEMAND_GROUP
                ,DM.DUE_DATE
                ,DM.TARGET_DATE
                ,DM.SALES_CUTOFF_DATE
                ,DM.EXPIRY_DATE
                ,DM.PRIORITY
                ,DM.QUANTITY
                ,DM.PRIORITY_GROUP
                ,DM.CUSTOMER_ID
                ,DM.ALLOW_SHORT
                ,DM.ATTRIBUTE1
                ,DM.ATTRIBUTE2
                ,DM.ATTRIBUTE3
                ,DM.ATTRIBUTE4
                ,DM.ATTRIBUTE5
                ,DM.ATTRIBUTE6
                ,DM.ATTRIBUTE7
                ,DM.ATTRIBUTE8
                ,DM.ATTRIBUTE9
                ,DM.ATTRIBUTE10
                ,DM.ATTRIBUTE11
                ,DM.ATTRIBUTE12
                ,DM.ATTRIBUTE13
                ,DM.ATTRIBUTE14
                ,DM.ATTRIBUTE15
        FROM    (
                SELECT  V_PLAN_ID                                                                  AS PLAN_ID
                      , DEMAND.SCM_SITE_ID||'::'||DEMAND.ITEM_ID||'::'||DEMAND.STAGE||'@'||DEMAND.INCOTERMS||'@'||DEMAND.PROJECT_CODE||'::'||DEMAND.DUE_DATE||'::'||'-'||'::'||DEMAND.FCST_TYPE||CASE WHEN NVL(DEMAND.CELL_PROD_SITE_ID,'-') = '-' THEN '' ELSE '::'||DEMAND.CELL_PROD_SITE_ID END AS DEMAND_ID
                      , DEMAND.SCM_SITE_ID||'::'||DEMAND.ITEM_ID||'::'||DEMAND.STAGE||'@'||DEMAND.INCOTERMS||'@'||DEMAND.PROJECT_CODE                                                                                                                        AS BUFFER_ID
                      /*  PRIORITY 는 TOSITE PRIORITY 아우터조인 유래라 NULL 가능 -> MSSQL 결합의 NULL 전파를 CASE 로 재현 */
                      , CASE WHEN DEMAND.PRIORITY IS NULL THEN NULL ELSE DEMAND.INCOTERMS||'@'||'D'||DEMAND.PRIORITY END AS DEMAND_GROUP
                      , DEMAND.DUE_DATE                                                            AS DUE_DATE
                      , NULL                                                                       AS TARGET_DATE
                      , NULL                                                                       AS SALES_CUTOFF_DATE
                      , NULL                                                                       AS EXPIRY_DATE
                      , DEMAND.PRIORITY                                                            AS PRIORITY
                      , DEMAND.QUANTITY                                                            AS QUANTITY
                      , CASE WHEN DEMAND.PRIORITY IS NULL THEN NULL ELSE 'D'||DEMAND.PRIORITY END  AS PRIORITY_GROUP
                      , NULL                                                                       AS CUSTOMER_ID
                      , NULL                                                                       AS ALLOW_SHORT
                      , DEMAND.SCM_SITE_ID                                                         AS ATTRIBUTE1
                      , DEMAND.ITEM_ID                                                             AS ATTRIBUTE2
                      , DEMAND.STAGE                                                               AS ATTRIBUTE3
                      , DEMAND.INCOTERMS                                                           AS ATTRIBUTE4
                      , DEMAND.PROJECT_CODE                                                        AS ATTRIBUTE5
                      , NULL                                                                       AS ATTRIBUTE6
                      , NULL                                                                       AS ATTRIBUTE7
                      , DEMAND.FCST_TYPE                                                           AS ATTRIBUTE8
                      , NULL                                                                       AS ATTRIBUTE9
                      , NULL                                                                       AS ATTRIBUTE10
                      , NULL                                                                       AS ATTRIBUTE11
                      , NULL                                                                       AS ATTRIBUTE12
                      , NULL                                                                       AS ATTRIBUTE13
                      , NULL                                                                       AS ATTRIBUTE14
                      , NULL                                                                       AS ATTRIBUTE15
                FROM   (
                       SELECT  A.DIVISION_ID  AS DIVISION_ID
                             , A.SCM_SITE_ID  AS SCM_SITE_ID
                             , A.ITEM_ID      AS ITEM_ID
                             , CASE
                                   WHEN B.OPERATION_GROUP = 'P' AND B.FLOW_ID = 'P9500'        THEN 'PACKBIZ'
                                   WHEN B.OPERATION_GROUP = 'P' AND B.FLOW_ID = 'P5500'        THEN 'MDLEBIZ'
                                   WHEN B.OPERATION_GROUP = 'P' AND B.FLOW_ID NOT IN ('P5500', 'P9500') THEN 'SUBMDLEBIZ'
                                   WHEN B.OPERATION_GROUP = 'A'    THEN 'CELLBIZ'
                               ELSE '-' END                                                               AS STAGE
                             , CASE WHEN NVL(MSE.VMI_YN, 'N' ) = 'Y' THEN 'DAP' ELSE A.INCOTERMS END   AS INCOTERMS
                             , A.ATTRIBUTE1                                                                 AS DUE_DATE
                             , SUM(A.QTY)                                                                   AS QUANTITY
                             , TP.PRIORITY                                                                  AS PRIORITY
                             , A.FCST_TYPE                                                                  AS FCST_TYPE
                             , A.PROJECT_CODE                                                               AS PROJECT_CODE
                             , A.CELL_PROD_SITE_ID                                                          AS CELL_PROD_SITE_ID


                       FROM DM_PLN_NET_DEMAND A
                       /* ---------------------------------------------------------------------- */
                           INNER JOIN (SELECT DISTINCT DIVISION_ID, ITEM_ID, OPERATION_GROUP, FLOW_ID, ATTRIBUTE8
                                       FROM   SCP_MST_FINAL_ITEM
                                       WHERE  DIVISION_ID = V_DIVISION_ID
                                    AND   ((DIVISION_ID  = '40' AND OPERATION_GROUP IN ('A') )      /*  소형은 CEll Biz 용 Demand 만 처리 */
                                          OR  (DIVISION_ID <> '40' AND OPERATION_GROUP IN ('A', 'P') )
                                             )
                                      ) B
                               ON    A.ITEM_ID     = B.ITEM_ID
                               AND   A.DIVISION_ID = B.DIVISION_ID
                       /* ---------------------------------------------------------------------- */
                           LEFT JOIN ( /*  VMI 대상 SITE 조회 */
                                       SELECT DIVISION_ID, SCM_SITE_ID, VMI_YN
                                       FROM   SCM_MST_SITE
                                       WHERE  DIVISION_ID = V_DIVISION_ID
                                           AND SITE_TYPE   = 'SALES'
                                           AND  VALID_YN    = 'Y'
                                           AND  VMI_YN      = 'Y'
                                       ) MSE
                               ON   A.DIVISION_ID      = MSE.DIVISION_ID
                               AND  A.SCM_SITE_ID      = MSE.SCM_SITE_ID
                       /* ---------------------------------------------------------------------- */
                           LEFT OUTER JOIN ( /* TOSITE PRIORITY CONSTRAINT */
                                           /* SELECT   SEGMENT4   AS ITEM_ID */
                                           /*         ,SEGMENT5   AS TO_SITE */
                                           /*         ,SEGMENT6   AS PRIORITY */
                                           /*         ,ATTRIBUTE1 AS FROM_DATE */
                                           /*         ,ATTRIBUTE2 AS TO_DATE */
                                           /* FROM    SCP_OPMZ_LOOKUP_MASTER_DETAIL WITH(NOLOCK) */
                                           /* WHERE   LOOKUP_TYPE = 'SCP_OPT_ENG_CONST_TOSITE_PRIORITY_NEW' */
                                           /* AND     SEGMENT2    = @V_DIVISION_ID */
                                           /* AND     SEGMENT3    = @V_GROUP_ID */
                                           /* AND     VALID_YN    = 'Y' */

                                            /*  2025.11.18 Minyong Lee : Sales Site Priority Lookup -> UI 전환 */
                                            SELECT  P.ITEM_ID       AS ITEM_ID
                                                  , P.SCM_SITE_ID   AS TO_SITE
                                                  , TO_CHAR(P.PRIO_RANK)     AS PRIORITY
                                                  , P.FROM_YYYYMMDD   AS FROM_DATE
                                                  , P.TO_YYYYMMDD     AS TO_DATE
                                            FROM    SCP_OPMZ_SALES_SITE_PRIORITY P
                                                  , SCP_OPMZ_PLAN_GR_M PG
                                            WHERE   1=1
                                            AND     P.OPMZ_PLAN_GR_ID = PG.OPMZ_PLAN_GR_ID
                                            AND     PG.VALID_YN = 'Y'
                                            AND     P.VALID_YN = 'Y'
                                            AND     P.DIVISION_ID = V_DIVISION_ID
                                            AND     PG.OPMZ_PLAN_GR_NAME = V_GROUP_ID
                                           ) TP
                               ON  A.SCM_SITE_ID = TP.TO_SITE
                               AND A.ITEM_ID     = TP.ITEM_ID
                               AND A.ATTRIBUTE1 BETWEEN TP.FROM_DATE AND TP.TO_DATE
                       WHERE   A.DIVISION_ID     =  V_DIVISION_ID
                       AND     A.CUTOFF_YYYYMMDD   =  V_DEMAND_CUTOFF_DAY
                       AND     A.VERSION_NO        =  V_DM_MAX_VERSION
                       AND     A.ATTRIBUTE1        >= P_PLAN_NAME
                       AND     A.ATTRIBUTE1        <  V_PLAN_END_YYYYMMDD
                       AND     A.QTY               >  0
                       /* AND     A.ITEM_ID IN ( SELECT DISTINCT ITEM_ID */
                       /*                    FROM    SCP_OPT_ENG_MODEL_LIST_N_SN WITH(NOLOCK) */
                       /*                    WHERE   PLAN_ID = @V_PLAN_ID */
                       /*                  ) */
                       /* 소형 생산지 구분을 위한 분리 */
                       AND ((V_DIVISION_ID = '40'
                                                      /* 상현 책임님 요청으로 SALES SITE는 MEDEL LIST를 고려하지 않도록 수정/20250526/김태현선임 */
                                                      /* AND CONCAT(A.SCM_SITE_ID,A.ITEM_ID) IN (SELECT DISTINCT CONCAT (SCM_SITE_ID,ITEM_ID) */
                                                      /*                                         FROM    SCP_OPT_ENG_MODEL_LIST_N_SN WITH(NOLOCK) */
                                                      /*                                         WHERE   PLAN_ID = @V_PLAN_ID */
                                                      /*                                        ) */
                                                      AND A.CELL_PROD_SITE_ID||A.ITEM_ID IN (SELECT DISTINCT SCM_SITE_ID||ITEM_ID
                                                                                                    FROM    SCP_OPT_ENG_MODEL_LIST_N_SN
                                                                                                    WHERE   PLAN_ID = V_PLAN_ID
                                                                                                    )
                            )
                            OR (V_DIVISION_ID != '40' AND  A.ITEM_ID IN (SELECT DISTINCT ITEM_ID
                                                              FROM    SCP_OPT_ENG_MODEL_LIST_N_SN
                                                              WHERE   PLAN_ID = V_PLAN_ID
                                                             )
                           )
                          )
                       /* ------------------------ */
                       GROUP BY A.DIVISION_ID, A.SCM_SITE_ID, A.ITEM_ID, MSE.VMI_YN, A.INCOTERMS, A.ATTRIBUTE1
                              , B.FLOW_ID, B.OPERATION_GROUP, TP.PRIORITY, A.FCST_TYPE,A.PROJECT_CODE,A.CELL_PROD_SITE_ID
                       ) DEMAND
                    LEFT OUTER JOIN GT_OPT_ENG_DM_CELLPROD CPS
                        ON  1=1
                        AND DEMAND.SCM_SITE_ID = CPS.SALES_SITE_ID
                        AND DEMAND.ITEM_ID     = CPS.ITEM_ID
                    /* ---------------------------------------------------------------------- */
                    /*  DEMAND 제외 대상 CELL ITEM 정보 : WHERE 절에서 제외 조건 처리 */
                    /*  2025.05.19 Philsu Park: Demand 제외 처리 시 To 구간 제약 추가 적용.(ATT3) */
                    /*  2025.11.10 Minyong Lee : 소형 Demand 제외 조건에 Stage 추가 적용을 위한 JOIN Depth 변경 */
                    /* ---------------------------------------------------------------------- */
                    LEFT JOIN   (
                                /* SELECT  SEGMENT2   AS DIVISION_ID */
                                /*       , SEGMENT3   AS SCM_SITE_ID */
                                /*       , SEGMENT4   AS ITEM_ID */
                                /*       , SEGMENT5   AS GROUP_ID */
                                /*       , ATTRIBUTE1 AS STAGE */
                                /*       , CASE */
