                    , A.ELEC_ITEM_ID
                    , A.CON_ITEM
                    , INSTR(A.CON_ITEM, '^', 1) AS CON01
                    , CASE
                        WHEN INSTR(A.CON_ITEM, '^', INSTR(A.CON_ITEM, '^', 1) + 1) = 0 THEN 1000
                        ELSE INSTR(A.CON_ITEM, '^', INSTR(A.CON_ITEM, '^', 1) + 1)
                        END AS CON02
                    , CASE
                        WHEN INSTR(A.CON_ITEM, '^', INSTR(A.CON_ITEM, '^', INSTR(A.CON_ITEM, '^', 1) + 1) + 1) = 0 THEN 1000
                        ELSE INSTR(A.CON_ITEM, '^', INSTR(A.CON_ITEM, '^', INSTR(A.CON_ITEM, '^', 1) + 1) + 1)
                        END AS CON03
                    , CASE
                        WHEN INSTR(A.CON_ITEM, '^', INSTR(A.CON_ITEM, '^', INSTR(A.CON_ITEM, '^', INSTR(A.CON_ITEM, '^', 1) + 1) + 1) + 1) = 0 THEN 1000
                        ELSE INSTR(A.CON_ITEM, '^', INSTR(A.CON_ITEM, '^', INSTR(A.CON_ITEM, '^', INSTR(A.CON_ITEM, '^', 1) + 1) + 1) + 1)
                        END AS CON04
            FROM    (
