            DELETE FROM GT_RPEP_TIR_SUB;

            INSERT INTO GT_RPEP_TIR_SUB
            SELECT    C.DIVISION_ID
                    , C.COMPANY_ID
                    , C.PLANT_ID
                    , C.ITEM_ID
                    , C.ELEC_ITEM_ID
            /* 2. 소요량 계산 */
                    , NVL((
                        SELECT  MAX(AB.CHILD_QTY) AS CHILD_ITEM_RATE
                        FROM    GT_RPEP_SCM_MST_BOM AB
                        WHERE   1 = 1
                            AND AB.PARENT_ITEM_ID = C.ITEM_ID
