                            AND AB.COMPANY_ID = C.COMPANY_ID
                            AND AB.PLANT_ID = C.PLANT_ID
                        ), 1) AS CHILD_ITEM_RATE01
                    , NVL((
                        SELECT  MAX(AB.CHILD_QTY) AS CHILD_ITEM_RATE
                        FROM    GT_RPEP_SCM_MST_BOM AB
                        WHERE   1 = 1
                            AND AB.PARENT_ITEM_ID = C.CHILD_ITEM_1
                            AND AB.CHILD_ITEM_ID = C.CHILD_ITEM_2
                            AND AB.DIVISION_ID = C.DIVISION_ID
                            AND AB.COMPANY_ID = C.COMPANY_ID
                            AND AB.PLANT_ID = C.PLANT_ID
                        ), 1) AS CHILD_ITEM_RATE02
                    , NVL((
                        SELECT  MAX(AB.CHILD_QTY) AS CHILD_ITEM_RATE
                        FROM    GT_RPEP_SCM_MST_BOM AB
                        WHERE   1 = 1
                            AND AB.PARENT_ITEM_ID  = C.CHILD_ITEM_2
                            AND AB.CHILD_ITEM_ID  = C.CHILD_ITEM_3
                            AND AB.DIVISION_ID = C.DIVISION_ID
                            AND AB.COMPANY_ID  = C.COMPANY_ID
                            AND AB.PLANT_ID  = C.PLANT_ID
                        ), 1) AS CHILD_ITEM_RATE03
            FROM    (
                        SELECT    B.DIVISION_ID
                                , B.COMPANY_ID
                                , B.PLANT_ID
                                , B.ITEM_ID
                                , B.ELEC_ITEM_ID
                                , B.CON_ITEM
                                , B.CON01
                                , B.CON02
                                , B.CON03
                                , B.CON04
                                , CASE
                                    WHEN B.CON01 = 1000 THEN 'N/A'
                                    WHEN B.CON02 = 1000 THEN SUBSTR(B.CON_ITEM, B.CON01 + 1, 1000)
                                    ELSE SUBSTR(B.CON_ITEM, B.CON01 + 1, (B.CON02 - B.CON01 - 1))
                                    END AS CHILD_ITEM_1
                                , CASE
                                    WHEN B.CON02 = 1000 THEN 'N/A'
                                    WHEN B.CON03 = 1000 THEN SUBSTR(B.CON_ITEM, B.CON02 + 1, 1000)
                                    ELSE SUBSTR(B.CON_ITEM, B.CON02 + 1, (B.CON03 - B.CON02 - 1))
                                    END AS CHILD_ITEM_2
                                , CASE
                                    WHEN B.CON03 = 1000 THEN 'N/A'
                                    WHEN B.CON04 = 1000 THEN SUBSTR(B.CON_ITEM, B.CON03 + 1, 1000)
                                    ELSE SUBSTR(B.CON_ITEM, B.CON03 + 1, (B.CON04 - B.CON03 - 1))
                                    END AS CHILD_ITEM_3
                        FROM    GT_RPEP_TIR_SUB_TEMP B
                    ) C;

            INSERT INTO GT_RPEP_TARGET_ITEM_RESULT
