                , A.ITEM_ID                                                           AS ELEC_MODEL
                , D.CELL_ITEM_ID                                                      AS CELL_MODEL
                , NVL(A.ELECTRODE_TYPE, E.ELECTRODE_TYPE)                             AS ELECTRODE_TYPE
