                , SYSDATE                                                             AS LAST_UPDATE_DATE
                , V_CREATION_SEQ                                                      AS CREATION_SEQ
        FROM    SCP_ANL_SHIPMENT_PLAN_SEMI A
                LEFT JOIN GT_RPEP_SITE B ON
                        A.FROM_SITE = B.SCM_SITE_ID
                LEFT JOIN GT_RPEP_SITE C ON
                        A.TO_SITE = C.SCM_SITE_ID
                LEFT JOIN GT_RPEP_FINAL_ITEM D ON
                        A.ITEM_ID = D.ITEM_ID
