PROCEDURE PR_SCP_SHIPMENT_ALLO_TARGET_40_PLAN
(
    P_DIVISION_ID       IN VARCHAR2 DEFAULT '40'
  , P_CUTOFF_YYYYMMDD   IN VARCHAR2 DEFAULT NULL
)
/*
 * Program ID  : [PR_SCP_SHIPMENT_ALLO_TARGET_40_PLAN]
 * Description : Ship Plan Amend수량 Allo Targe에 반영 (SHIPMENT PLAN FG)
 *				 - 매주 금요일에 당주 월요일에 생성된 Allo Target Plan정보를 삭제하고
 *			       당주 MA plan의 Shipment Plan Amend 수량으로 Allo Target Plan정보를 재생성한다.
 * Execute     :

				 EXEC PR_SCP_SHIPMENT_ALLO_TARGET_40_PLAN @P_DIVISION_ID = N'40', @P_CUTOFF_YYYYMMDD = N'20220711'
 *
 * Program History
 *=========================================================================================================================
 *   Date		In Charge	Description
 *=========================================================================================================================
 * 2022/07/18	hrkim		Initial Release  [PJ20216994] LGES Digital SCM 3 Level 가속화를 위한 개선 Phase 2
 * 2023/01/10	hrkim		[PJ20216994] LGES Digital SCM 3 Level 가속화를 위한 개선 Phase 2 : Cell 원통형만 대상으로 함
 * 2026.07.06   ZIONEX      [PJ202650304] NextSCM Migration
 *                           GT_SSAT_SHIPMENT_PLAN_FG, ON COMMIT PRESERVE ROWS, 재호출 대비 선(先) DELETE).
 *                           DELETE TOP(1000) 루프 -> DELETE ... AND ROWNUM<=1000 루프(SQL%ROWCOUNT=0 EXIT). ANSI JOIN -> (+).
 */
AS

    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME    VARCHAR2(150 CHAR) := 'PR_SCP_SHIPMENT_ALLO_TARGET_40_PLAN'; /* Proc별 이름 설정 */
    V_LOG_TYPE        VARCHAR2(30 CHAR); /* START/END/ERROR/... */
    N_LOG_COUNT       NUMBER := 0;
    V_LOG_MESSAGE     VARCHAR2(1000 CHAR);
    V_DESCRIPTION     VARCHAR2(500 CHAR);
    D_EVENT_DATE      DATE;
    V_BATCH_USER      VARCHAR2(150 CHAR) := 'PR_SCP_SHIPMENT_ALLO_TARGET_40_PLAN';

    /* 임시 실행시간 확인용 */
    V_START_TIME      DATE := SYSDATE;
    V_EXEC_TIME       VARCHAR2(10 CHAR) := ''; /* '[00:00]' */


    V_CUTOFF_YYYYMMDD VARCHAR2(8 CHAR);
BEGIN


    V_CUTOFF_YYYYMMDD := P_CUTOFF_YYYYMMDD;
    IF V_CUTOFF_YYYYMMDD IS NULL THEN
       V_CUTOFF_YYYYMMDD := TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7, 'YYYYMMDD'); /* 당주 월요일 YYYYMMDD */
    END IF;

    /* 시작 LOG (START) */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '##### Start of procedure #####';
    V_DESCRIPTION := P_DIVISION_ID || ' : ' || V_CUTOFF_YYYYMMDD;
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    V_LOG_MESSAGE := NULL; /* < - 변수 재사용을 위하여 초기화해야함 */

    BEGIN
        DBMS_OUTPUT.PUT_LINE('----------------------------------------');
        DBMS_OUTPUT.PUT_LINE('@P_DIVISION_ID =' || P_DIVISION_ID);
        DBMS_OUTPUT.PUT_LINE('@P_CUTOFF_YYYYMMDD =' || V_CUTOFF_YYYYMMDD);
        DBMS_OUTPUT.PUT_LINE('----------------------------------------');
    END;

    BEGIN

        /* PLAN 버전 정보 */
        DELETE FROM GT_SSAT_PLAN_INFO;

        INSERT
          INTO GT_SSAT_PLAN_INFO
        SELECT P.DIVISION_ID
             , P.PLAN_NAME     AS PLAN_START_YYYYMMDD
             , D.PLAN_TYPE
             , D.PLAN_SEQ
          FROM SCM_MST_PLAN         P
             , SCM_MST_PLAN_DETAIL  D
         WHERE D.DIVISION_ID  = P.DIVISION_ID
           AND D.PLAN_ID      = P.PLAN_ID
           AND D.PLAN_TYPE    = 'MA'   /* MA 고정 7/19 FN에서 MA로 변경 (신재욱 책임) */
           AND D.PLAN_STATUS  = '1'    /* 정상 완료 */
           AND D.CONFIRM_FLAG = 'Y'    /* 최종 Confirm */
           AND 1=1
           AND P.DIVISION_ID  = P_DIVISION_ID       /* 변수 처리 */
           AND P.PLAN_NAME    = V_CUTOFF_YYYYMMDD   /* 변수 처리 : 당주 월요일 */
           AND P.PLAN_CYCLE   = 'WEEKLY';

        /* SITE ITEM 부서 정보 */
        DELETE FROM GT_SSAT_DEPT_INFO_40;

        INSERT
          INTO GT_SSAT_DEPT_INFO_40
        WITH DEPT_INFO AS (
            SELECT SI.DIVISION_ID
                 , SI.SCM_SITE_ID
                 , SI.ITEM_ID
                 , SI.PROJECT_CODE
                 , UI.DEPT_ID
                 , ROW_NUMBER() OVER (PARTITION BY SI.DIVISION_ID
                                                 , SI.SCM_SITE_ID
                                                 , SI.ITEM_ID
                                          ORDER BY SI.CREATION_DATE DESC
                                                 , SI.PROJECT_CODE)  AS PJT_PRIORITY
              FROM SCM_MST_SITE_ITEM       SI
                 , SCM_MST_SSO_USER_INFO   UI
             WHERE UPPER(UI.USER_ID) = UPPER((SELECT COLUMN_VALUE
                                                FROM TABLE(STRING_SPLIT(SI.OWNER, ','))
                                               WHERE ROWNUM = 1))
               AND 1=1
               AND SI.DIVISION_ID = '40'
               AND SI.VALID_YN = 'Y'
        )
        SELECT DIVISION_ID
             , SCM_SITE_ID
             , ITEM_ID
             , PROJECT_CODE
             , DEPT_ID
             , PJT_PRIORITY
          FROM DEPT_INFO;

        /* ITEM 정보 */
        DELETE FROM GT_SSAT_ITEM_INFO;

        INSERT
          INTO GT_SSAT_ITEM_INFO
        SELECT MI.DIVISION_ID
             , MI.ITEM_ID
             , MAX(MI.NICK_NAME)       AS NICK_NAME
             , MAX(MI.SCP_EXTRA_SPEC)  AS EXTRA_SPEC
          FROM SCM_MST_ITEM_SN      MI
             , SCP_MST_FINAL_ITEM   FI   /* 2023.01.10 Cell 원통형만 대상 */
         WHERE FI.DIVISION_ID = MI.DIVISION_ID
           AND FI.ITEM_ID     = MI.ITEM_ID
           AND FI.OPERATION_GROUP      = 'A'   /* Cell */
           AND FI.CELL_TYPE_GROUP_CODE = 'C'   /* 원통형 */
           AND 1=1
           AND MI.DIVISION_ID = P_DIVISION_ID
         GROUP BY MI.DIVISION_ID
                , MI.ITEM_ID;

        /* ----------------------------------------------------------- */
        /* TXN LOG */
        /* ----------------------------------------------------------- */
        V_LOG_TYPE    := 'TXN';
        V_LOG_MESSAGE := 'INSERT INTO #tmp_SCP_ANL_SHIPMENT_PLAN_FG';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        /* SHIP_PLAN_AMEND */
        DELETE FROM GT_SSAT_SHIPMENT_PLAN_FG;

        INSERT
          INTO GT_SSAT_SHIPMENT_PLAN_FG
        SELECT SP.DIVISION_ID
             , SP.PLAN_START_YYYYMMDD
             , SP.TO_SITE
             , SP.ITEM_ID
             , SP.PROJECT_CODE
             , SP.YYYYMMDD
             , SP.QTY
          FROM SCP_ANL_SHIPMENT_PLAN_FG  SP
             , GT_SSAT_PLAN_INFO         PV
         WHERE SP.DIVISION_ID         = PV.DIVISION_ID
           AND SP.PLAN_START_YYYYMMDD = PV.PLAN_START_YYYYMMDD
           AND SP.PLAN_TYPE           = PV.PLAN_TYPE
           AND SP.SEQ                 = PV.PLAN_SEQ
           AND SP.MEASURE             = 'SHIP_PLAN_AMEND'
           AND 1=1
           AND SP.QTY != 0;

        BEGIN

            /* ----------------------------------------------------------- */
            /* TXN LOG */
            /* ----------------------------------------------------------- */
            V_LOG_TYPE    := 'TXN';
            V_LOG_MESSAGE := 'DELETE FROM SCP_ANL_ALLO_TARGET';
            D_EVENT_DATE  := SYSDATE;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

            /* ------------------------------------------------------------------------------------------- */
            /* 1. DELETE (TYPE=PLAN) */
            /* ------------------------------------------------------------------------------------------- */
            LOOP
                DELETE
                  FROM SCP_ANL_ALLO_TARGET
                 WHERE DIVISION_ID     = P_DIVISION_ID
                   AND CUTOFF_YYYYMMDD = V_CUTOFF_YYYYMMDD
                   AND TYPE            = 'PLAN'
                   AND ROWNUM         <= 1000;

                EXIT WHEN SQL%ROWCOUNT = 0;
            END LOOP;

            /* ----------------------------------------------------------- */
            /* TXN LOG */
            /* ----------------------------------------------------------- */
            V_LOG_TYPE    := 'TXN';
            V_LOG_MESSAGE := 'BEGIN - INSERT INTO SCP_ANL_ALLO_TARGET';
            D_EVENT_DATE  := SYSDATE;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

            /* ------------------------------------------------------------------------------------------- */
            /* 2. INSERT (TYPE=PLAN) */
            /* SCM팀 amend한 allo수량을 allo target에 반영 (Shipment plan FG 수량 : SHIP_PLAN_AMEND measure) */
            /* ------------------------------------------------------------------------------------------- */
            INSERT
              INTO SCP_ANL_ALLO_TARGET
                 ( DIVISION_ID
                 , TYPE
                 , CUTOFF_YYYYMMDD
                 , YYYY
                 , YYYYQQ
                 , YYYYMM
                 , ITEM_ID
                 , DEPT_ID
                 , NICK_NAME
                 , EXTRA_SPEC
                 , QTY
                 , CREATED_BY
                 , CREATION_DATE
                 , LAST_UPDATED_BY
                 , LAST_UPDATE_DATE )
            WITH SHIP_PLAN_AMEND AS (
                /* Shipment Plan Amend 정보 */
                SELECT SP.DIVISION_ID
                     , SP.PLAN_START_YYYYMMDD                                                AS CUTOFF_YYYYMMDD
                     , BC.YYYY
                     , (BC.YYYY || 'Q' || TO_CHAR(TO_DATE(BC.YYYYMMDD, 'YYYYMMDD'), 'Q'))    AS YYYYQQ
                     , BC.YYYYMM
                     , SP.ITEM_ID
                     , CASE WHEN SP.DIVISION_ID = '40'
                            THEN NVL(DI.DEPT_ID, DI2.DEPT_ID)
                            ELSE TS.DEPT_ID
                       END                                                                  AS DEPT_ID
                     , SUM(QTY)                                                             AS QTY
                  FROM GT_SSAT_SHIPMENT_PLAN_FG  SP
                     , SCM_MST_BUCKET            BC
                     , SCM_MST_SITE              TS
                     , GT_SSAT_DEPT_INFO_40      DI
                     , GT_SSAT_DEPT_INFO_40      DI2
                 WHERE BC.YYYYMMDD        = SP.YYYYMMDD
                   AND TS.DIVISION_ID(+)  = SP.DIVISION_ID
                   AND TS.SCM_SITE_ID(+)  = SP.TO_SITE
                   AND TS.SITE_TYPE(+)    = 'SALES'
                   AND DI.DIVISION_ID(+)  = SP.DIVISION_ID
                   AND DI.SCM_SITE_ID(+)  = SP.TO_SITE
                   AND DI.ITEM_ID(+)      = SP.ITEM_ID
                   AND DI.PROJECT_CODE(+) = SP.PROJECT_CODE
                   AND DI2.DIVISION_ID(+)  = SP.DIVISION_ID
                   AND DI2.SCM_SITE_ID(+)  = SP.TO_SITE
                   AND DI2.ITEM_ID(+)      = SP.ITEM_ID
                   AND DI2.PJT_PRIORITY(+) = 1
                   AND 1=1
                 GROUP BY SP.DIVISION_ID
                        , SP.PLAN_START_YYYYMMDD
                        , BC.YYYY
                        , (BC.YYYY || 'Q' || TO_CHAR(TO_DATE(BC.YYYYMMDD, 'YYYYMMDD'), 'Q'))
                        , BC.YYYYMM
                        , SP.ITEM_ID
                        , CASE WHEN SP.DIVISION_ID = '40'
                               THEN NVL(DI.DEPT_ID, DI2.DEPT_ID)
                               ELSE TS.DEPT_ID
                          END
            )
            SELECT SP.DIVISION_ID
                 , 'PLAN'         AS TYPE
                 , SP.CUTOFF_YYYYMMDD
                 , SP.YYYY
                 , SP.YYYYQQ
                 , SP.YYYYMM
                 , SP.ITEM_ID
                 , SP.DEPT_ID
                 , II.NICK_NAME
                 , II.EXTRA_SPEC
                 , SUM(QTY)       AS QTY
                 , V_BATCH_USER   AS CREATED_BY
                 , SYSDATE        AS CREATION_DATE
                 , V_BATCH_USER   AS LAST_UPDATED_BY
                 , SYSDATE        AS LAST_UPDATE_DATE
              FROM SHIP_PLAN_AMEND     SP
                 , GT_SSAT_ITEM_INFO   II
             WHERE II.DIVISION_ID = SP.DIVISION_ID
               AND II.ITEM_ID     = SP.ITEM_ID
               AND 1=1
             GROUP BY SP.DIVISION_ID
                    , SP.CUTOFF_YYYYMMDD
                    , SP.YYYY
                    , SP.YYYYQQ
                    , SP.YYYYMM
                    , SP.ITEM_ID
                    , SP.DEPT_ID
                    , II.NICK_NAME
                    , II.EXTRA_SPEC;

        END;

        /* ----------------------------------------------------------- */
        /* TXN LOG */
        /* ----------------------------------------------------------- */
        V_LOG_TYPE    := 'TXN';
        V_LOG_MESSAGE := 'END - INSERT INTO SCP_ANL_ALLO_TARGET';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);


        COMMIT;

    EXCEPTION
        WHEN OTHERS THEN
            ROLLBACK;
            /* ERROR LOG */
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := SUBSTR('ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 500);
            D_EVENT_DATE  := SYSDATE;
            PR_SCP_SYS_LOG_BATCH(P_PROGRAM_NAME => V_PROGRAM_NAME, P_LOG_TYPE => V_LOG_TYPE, P_LOG_COUNT => N_LOG_COUNT
                               , P_LOG_MESSAGE => V_LOG_MESSAGE, P_DESCRIPTION => V_DESCRIPTION, P_EVENT_DATE => D_EVENT_DATE
                               , P_USER_ID => V_BATCH_USER);
            DBMS_OUTPUT.PUT_LINE(V_LOG_MESSAGE || ' : ' || V_DESCRIPTION);
            RETURN;
    END;


    V_EXEC_TIME := CASE WHEN LENGTH(TO_CHAR(TRUNC(ROUND((SYSDATE - V_START_TIME) * 86400) / 60))) > 2 THEN NULL
                        ELSE LPAD(TO_CHAR(TRUNC(ROUND((SYSDATE - V_START_TIME) * 86400) / 60)), 2, '0') || ':' ||
                            LPAD(TO_CHAR(MOD(ROUND((SYSDATE - V_START_TIME) * 86400), 60)), 2, '0')
                   END;

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '##### END of procedure #####';
    V_DESCRIPTION := '[' || V_EXEC_TIME || ']';
    D_EVENT_DATE  := SYSDATE;
    PR_SCP_SYS_LOG_BATCH(P_PROGRAM_NAME => V_PROGRAM_NAME, P_LOG_TYPE => V_LOG_TYPE, P_LOG_COUNT => N_LOG_COUNT
                       , P_LOG_MESSAGE => V_LOG_MESSAGE, P_DESCRIPTION => V_DESCRIPTION, P_EVENT_DATE => D_EVENT_DATE
                       , P_USER_ID => V_BATCH_USER);
    RETURN;

END;

