    V_BP_DAYS                  PLS_INTEGER := 0;
    V_BP_PLAN_END_YYYYMMDD     VARCHAR2(8 CHAR) := '';
    /*  자식에 넘길 partial 문자열(원본 @p_partial2) */
    V_P_PARTIAL2               VARCHAR2(240 CHAR);
BEGIN


    /*  MSSQL @p_user_id 는 VARCHAR(100) 이라 100자에서 조용히 잘린다. Oracle 형식 파라미터는 길이 제약을 */
    V_BATCH_USER      := SUBSTR(P_USER_ID, 1, 100);

    /*  20231109 'PACK_MODEL_CHANGE','CELL_MODEL_CHANGE' 처리 안 함 : PI 요청 */
    IF P_MEASURE IN ('PACK_MODEL_CHANGE', 'CELL_MODEL_CHANGE') THEN
        /* 원본 L138 : return 1. ★정상 스킵이다(에러 아님 - PI 요청으로 형교환은 부모에서 처리하지 않는다). */
        RETURN;
    END IF;

  /*  시작 LOG */
    V_LOG_TYPE        := 'START';
    V_LOG_MESSAGE     := '########## Start of procedure ##########';
    V_DESCRIPTION     := V_PROGRAM_NAME || ':' || ' SCP_XLS_PSI_GLOBAL SAVE LOGIC';
    D_EVENT_DATE      := SYSDATE;
    PR_SCP_SYS_LOG_BATCH( P_PROGRAM_NAME  => V_PROGRAM_NAME
                        , P_LOG_TYPE      => V_LOG_TYPE
                        , P_LOG_COUNT     => N_LOG_COUNT
                        , P_LOG_MESSAGE   => V_LOG_MESSAGE
                        , P_DESCRIPTION   => V_DESCRIPTION
                        , P_EVENT_DATE    => D_EVENT_DATE
                        , P_USER_ID       => V_BATCH_USER
                        );

        /*  임시 실행시간 확인용 */
    V_START_TIME      := SYSDATE;
    V_EXEC_TIME       := '';

    /* PRINT @p_plan_type */
    /*  PLAN_TYPE이 FN일경우 수정금지 RETURN */
    /* [TEST] */
    IF P_PLAN_TYPE = 'FN' AND P_IS_DEBUG = 0 THEN
        /* 원본 L163 : return -1. ★정상 스킵이다(에러 아님 - FN(Final) 판본은 수정 금지). */
        RETURN;
    END IF;

    /* ------------------------------------------------------------------------------------------------------------- */
    /*  입력된 버전과 현재 버전이 다를 경우 RETURN */
    /* ------------------------------------------------------------------------------------------------------------- */
    V_DIVISION_ID           := P_DIVISION_ID;
    V_PLAN_START_YYYYMMDD   := P_PLAN_START_YYYYMMDD;
    V_PLAN_TYPE             := P_PLAN_TYPE;
    V_SEQ                   := P_SEQ;

    /*  MSSQL : SELECT TOP 1 @v_.. = .. FROM SCP_XLS_PSI_GLOBAL WHERE DIVISION_ID = @p_division_id (ORDER BY 없음).
        0행이면 MSSQL 은 변수 기존값을 그대로 두므로 SELECT INTO(NO_DATA_FOUND / 다행 ORA-01422)가 아니라 */
    FOR R IN ( SELECT DIVISION_ID
                    , PLAN_START_YYYYMMDD
                    , PLAN_TYPE
                    , SEQ
                 FROM SCP_XLS_PSI_GLOBAL
                WHERE DIVISION_ID = P_DIVISION_ID   /* 2022.03.23	KSW	GM JV 반영 */
                  AND ROWNUM = 1
             )
    LOOP
        V_DIVISION_ID           := R.DIVISION_ID;
        V_PLAN_START_YYYYMMDD   := R.PLAN_START_YYYYMMDD;
        V_PLAN_TYPE             := R.PLAN_TYPE;
        V_SEQ                   := R.SEQ;
    END LOOP;

    IF ( P_DIVISION_ID <> V_DIVISION_ID OR P_PLAN_START_YYYYMMDD <> V_PLAN_START_YYYYMMDD
         OR P_PLAN_TYPE <> V_PLAN_TYPE OR P_SEQ <> V_SEQ ) THEN
        /* 원본 L182 : return -1. ★정상 스킵이다(화면이 보고 있던 버전이 이미 바뀐 경우 저장을 건너뛴다). */
        RETURN;
    END IF;
    /* ------------------------------------------------------------------------------------------------------------- */

    /* PRINT @p_plan_type */
    BEGIN
      BEGIN

            /* ------------------------------------------------------------------------------------------- */
            /*  SCM_ADM_LOOKUP_MASTER_DETAIL.LOOKUP_TYPE  ='DAYOFWEEK_NO' */
            /*  저장할 요일 (월,화,수,목,금,토,일:2,3,4,5,6,7,1), 8이상은 일배분 */
            /* ------------------------------------------------------------------------------------------- */
            /* SELECT SEGMENT1, SEGMENT2,DESCRIPTION */
            /*  MSSQL SELECT TOP 1 @x_DAYOFWEEK_NO = ISNULL(SEGMENT2,8) : 0행이면 선언 초기값 8 이 유지된다
                -> 커서 FOR 루프. SEGMENT2 는 VARCHAR2(100 CHAR)(실측)이고 대상은 INT 라 TO_NUMBER 로 변환한다
                (MSSQL 도 varchar -> int 암묵 변환). */
            FOR R IN ( SELECT NVL(TO_NUMBER(SEGMENT2), 8) AS DAYOFWEEK_NO
                         FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                        WHERE LOOKUP_TYPE = 'SHIP_PLAN_SAVE_WEEK'   /* 'DAYOFWEEK_NO' */
                          AND SEGMENT1    = P_DIVISION_ID   /* DIVISION_ID */
                          AND VALID_YN    = 'Y'
                          AND ROWNUM      = 1
                     )
            LOOP
                X_DAYOFWEEK_NO := R.DAYOFWEEK_NO;
            END LOOP;

               /*  선택된 항목만 주로 변경해야 하기 때문에 반영하지 않도록 수정 2019.05.07 */
               /* SET @x_DAYOFWEEK_NO = '8' */

            /*  MSSQL CONVERT(VARCHAR(8), DATEADD(day, 364, @p_plan_start_yyyymmdd), 112). */
            V_P_TO_YYYYMMDD := TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 364, 'YYYYMMDD');

            /* ------------------------------------------------------------------------------------------- */
            /*  FROZEN 구간 대상 DATA 생성 */
            /* ------------------------------------------------------------------------------------------- */

            DELETE FROM GT_XPGT_SCM_MST_SITE;

            INSERT INTO GT_XPGT_SCM_MST_SITE
                 ( DIVISION_ID
                 , PLANT_ID
                 , OPERATION_GROUP
                 , SCM_SITE_ID
                 , SHIP_FROZEN
                 , SHIP_FROZEN_WEEK
                 , SHIP_FROZEN_WEEK_DAY
                 , PROD_FROZEN
                 , PROD_FROZEN_WEEK
                 , PROD_FROZEN_WEEK_DAY
                 , PROD_FROZEN_WEEK_DAY_MA
                 , FP_PLAN_PERIOD
                 , VALID_YN
                 , NEW_YN
                 , COMPANY_ID
                 , LOGISTIC_PLANT_ID
                 , PACKER_ITEM_ID_SUFFIX )
            SELECT S.DIVISION_ID
                 , S.PLANT_ID
                 , S.OPERATION_GROUP
                 , S.SCM_SITE_ID
                 , S.SHIP_FROZEN

                 , (TRUNC(S.SHIP_FROZEN / 7) + (CASE WHEN MOD(SHIP_FROZEN, 7) > 0 THEN 1 ELSE 0 END)) AS SHIP_FROZEN_WEEK
                   /*  MSSQL CONVERT(NVARCHAR(8), DATEADD(WEEK, n, @p_plan_start_yyyymmdd), 112) : 문자열이 */
                 , TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')
                           + (TRUNC(S.SHIP_FROZEN / 7) + (CASE WHEN MOD(SHIP_FROZEN, 7) > 0 THEN 1 ELSE 0 END)) * 7
                          , 'YYYYMMDD') AS SHIP_FROZEN_WEEK_DAY
                 , S.PROD_FROZEN
                 , (TRUNC(S.PROD_FROZEN / 7) + (CASE WHEN MOD(PROD_FROZEN, 7) > 0 THEN 1 ELSE 0 END)) AS PROD_FROZEN_WEEK
                 , TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')
                           + (TRUNC(S.PROD_FROZEN / 7) + (CASE WHEN MOD(PROD_FROZEN, 7) > 0 THEN 1 ELSE 0 END)) * 7
                          , 'YYYYMMDD') AS PROD_FROZEN_WEEK_DAY
                 , TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')
                           + (TRUNC((CASE WHEN ((S.PROD_FROZEN - 7) > 0) THEN (S.PROD_FROZEN - 7) ELSE 0 END) / 7)
                              + (CASE WHEN MOD((CASE WHEN ((S.PROD_FROZEN - 7) > 0) THEN (S.PROD_FROZEN - 7) ELSE 0 END), 7) > 0 THEN 1 ELSE 0 END)) * 7
                          , 'YYYYMMDD') AS PROD_FROZEN_WEEK_DAY_MA
                 , S.FP_PLAN_PERIOD
                 , S.VALID_YN
                 , S.NEW_YN
                 , S.COMPANY_ID
                 , S.LOGISTIC_PLANT_ID
                 , S.PACKER_ITEM_ID_SUFFIX
              FROM SCM_MST_SITE S
             WHERE S.SITE_TYPE   = 'PLANT'
               AND S.VALID_YN    = 'Y'
               AND S.DIVISION_ID = P_DIVISION_ID
                 ;


            V_P_CREATE_FROM_YYYYMMDD := SUBSTR(P_PLAN_START_YYYYMMDD, 1, 8);
            V_P_CREATE_TO_YYYYMMDD   := TO_CHAR(TO_DATE(V_P_CREATE_FROM_YYYYMMDD, 'YYYYMMDD') + 364, 'YYYYMMDD');

            /*  Plan End Date
                DATEDIFF(DAY, p.plan_name, p.horizon_end_date) : 두 컬럼 모두 YYYYMMDD 문자열(실측)이라 */
            FOR R IN ( SELECT P.HORIZON_END_DATE
                            , (CASE WHEN TO_DATE(P.HORIZON_END_DATE, 'YYYYMMDD') - TO_DATE(P.PLAN_NAME, 'YYYYMMDD') > 364 THEN 'Y' ELSE 'N' END) AS BP_FLAG
                            , (CASE WHEN TO_DATE(P.HORIZON_END_DATE, 'YYYYMMDD') - TO_DATE(P.PLAN_NAME, 'YYYYMMDD') > 364
                                    THEN TO_DATE(P.HORIZON_END_DATE, 'YYYYMMDD') - TO_DATE(P.PLAN_NAME, 'YYYYMMDD') - 363 ELSE 0 END) AS BP_DAYS
                         FROM SCM_MST_PLAN P
                        WHERE P.DIVISION_ID = P_DIVISION_ID
                          AND P.PLAN_ID     = (SELECT MAX(PLAN_ID)
                                                 FROM SCM_MST_PLAN P
                                                WHERE DIVISION_ID = P_DIVISION_ID
                                                  AND PLAN_ID < 9999)
                     )
            LOOP

                V_PET_DATE  := SUBSTR(R.HORIZON_END_DATE, 1, 12);
                V_BP_FLAG   := R.BP_FLAG;
                V_BP_DAYS   := R.BP_DAYS;
            END LOOP;

            /* ------------------------------------------------------------------------------------------- */
            /*  1 year 저장 프로시저 실행 */
            /* ------------------------------------------------------------------------------------------- */

            V_P_PARTIAL2 := SUBSTR(P_PARTIAL, 1, 52 * 2 - 1);

            /*  원본 L267 : EXEC @rows = PR_SCP_XLS_ADD_XLSPSI01_S @p_USER_ID = @p_user_id , ... */
            PR_SCP_XLS_ADD_XLSPSI01_S( P_USER_ID              => P_USER_ID
                                       , P_DIVISION_ID          => P_DIVISION_ID
                                       , P_PLAN_START_YYYYMMDD  => P_PLAN_START_YYYYMMDD
                                       , P_PLAN_TYPE            => P_PLAN_TYPE
                                       , P_SEQ                  => P_SEQ
                                       , P_ITEM_ID              => P_ITEM_ID
                                       , P_MEASURE              => P_MEASURE
                                       , P_XLS_KEY1             => P_XLS_KEY1
                                       , P_CREATE_FROM_YYYYMMDD => V_P_CREATE_FROM_YYYYMMDD
                                       , P_CREATE_TO_YYYYMMDD   => V_P_CREATE_TO_YYYYMMDD
                                       , P_WQTY01 => P_WQTY01 , P_WQTY02 => P_WQTY02 , P_WQTY03 => P_WQTY03 , P_WQTY04 => P_WQTY04 , P_WQTY05 => P_WQTY05
                                       , P_WQTY06 => P_WQTY06 , P_WQTY07 => P_WQTY07 , P_WQTY08 => P_WQTY08 , P_WQTY09 => P_WQTY09 , P_WQTY10 => P_WQTY10
                                       , P_WQTY11 => P_WQTY11 , P_WQTY12 => P_WQTY12 , P_WQTY13 => P_WQTY13 , P_WQTY14 => P_WQTY14 , P_WQTY15 => P_WQTY15
                                       , P_WQTY16 => P_WQTY16 , P_WQTY17 => P_WQTY17 , P_WQTY18 => P_WQTY18 , P_WQTY19 => P_WQTY19 , P_WQTY20 => P_WQTY20
                                       , P_WQTY21 => P_WQTY21 , P_WQTY22 => P_WQTY22 , P_WQTY23 => P_WQTY23 , P_WQTY24 => P_WQTY24 , P_WQTY25 => P_WQTY25
                                       , P_WQTY26 => P_WQTY26 , P_WQTY27 => P_WQTY27 , P_WQTY28 => P_WQTY28 , P_WQTY29 => P_WQTY29 , P_WQTY30 => P_WQTY30
                                       , P_WQTY31 => P_WQTY31 , P_WQTY32 => P_WQTY32 , P_WQTY33 => P_WQTY33 , P_WQTY34 => P_WQTY34 , P_WQTY35 => P_WQTY35
                                       , P_WQTY36 => P_WQTY36 , P_WQTY37 => P_WQTY37 , P_WQTY38 => P_WQTY38 , P_WQTY39 => P_WQTY39 , P_WQTY40 => P_WQTY40
                                       , P_WQTY41 => P_WQTY41 , P_WQTY42 => P_WQTY42 , P_WQTY43 => P_WQTY43 , P_WQTY44 => P_WQTY44 , P_WQTY45 => P_WQTY45
                                       , P_WQTY46 => P_WQTY46 , P_WQTY47 => P_WQTY47 , P_WQTY48 => P_WQTY48 , P_WQTY49 => P_WQTY49 , P_WQTY50 => P_WQTY50
                                       , P_WQTY51 => P_WQTY51 , P_WQTY52 => P_WQTY52
                                       , P_PARTIAL              => V_P_PARTIAL2
                                       , P_DAILYQTY             => P_DAILYQTY1
                                       , P_IS_DEBUG             => P_IS_DEBUG
                                       , O_RETURN_CODE          => V_ROWS
                                       );


            IF V_ROWS < 0 THEN
                GOTO RETURN_ERR_CODE;
            END IF;

            IF V_BP_FLAG = 'Y' THEN
                /* ------------------------------------------------------------------------------------- */
                /*  2 year 저장 프로시저 실행 */
                /* ------------------------------------------------------------------------------------- */
                /* CONVERT(VARCHAR(8), DATEADD(day, 1, @p_create_to_yyyymmdd), 112); */
                V_P_CREATE_FROM_YYYYMMDD := V_P_CREATE_TO_YYYYMMDD;
                /*  2022.08.17 중장기 버전 2 year 대응처리 */
                V_P_CREATE_TO_YYYYMMDD   := TO_CHAR(TO_DATE(V_P_CREATE_FROM_YYYYMMDD, 'YYYYMMDD') + 364, 'YYYYMMDD');


                V_P_PARTIAL2 := SUBSTR(P_PARTIAL, GREATEST(LENGTH(P_PARTIAL) - (52 * 2 - 1) + 1, 1), 52 * 2 - 1);

                PR_SCP_XLS_ADD_XLSPSI01_S( P_USER_ID              => P_USER_ID
                                           , P_DIVISION_ID          => P_DIVISION_ID
                                           , P_PLAN_START_YYYYMMDD  => P_PLAN_START_YYYYMMDD
                                           , P_PLAN_TYPE            => P_PLAN_TYPE
                                           , P_SEQ                  => P_SEQ
                                           , P_ITEM_ID              => P_ITEM_ID
                                           , P_MEASURE              => P_MEASURE
                                           , P_XLS_KEY1             => P_XLS_KEY1
                                           , P_CREATE_FROM_YYYYMMDD => V_P_CREATE_FROM_YYYYMMDD
                                           , P_CREATE_TO_YYYYMMDD   => V_P_CREATE_TO_YYYYMMDD
                                           , P_WQTY01 => P_WQTY53 , P_WQTY02 => P_WQTY54 , P_WQTY03 => P_WQTY55 , P_WQTY04 => P_WQTY56 , P_WQTY05 => P_WQTY57
                                           , P_WQTY06 => P_WQTY58 , P_WQTY07 => P_WQTY59 , P_WQTY08 => P_WQTY60 , P_WQTY09 => P_WQTY61 , P_WQTY10 => P_WQTY62
                                           , P_WQTY11 => P_WQTY63 , P_WQTY12 => P_WQTY64 , P_WQTY13 => P_WQTY65 , P_WQTY14 => P_WQTY66 , P_WQTY15 => P_WQTY67
                                           , P_WQTY16 => P_WQTY68 , P_WQTY17 => P_WQTY69 , P_WQTY18 => P_WQTY70 , P_WQTY19 => P_WQTY71 , P_WQTY20 => P_WQTY72
                                           , P_WQTY21 => P_WQTY73 , P_WQTY22 => P_WQTY74 , P_WQTY23 => P_WQTY75 , P_WQTY24 => P_WQTY76 , P_WQTY25 => P_WQTY77
                                           , P_WQTY26 => P_WQTY78 , P_WQTY27 => P_WQTY79 , P_WQTY28 => P_WQTY80 , P_WQTY29 => P_WQTY81 , P_WQTY30 => P_WQTY82
                                           , P_WQTY31 => P_WQTY83 , P_WQTY32 => P_WQTY84 , P_WQTY33 => P_WQTY85 , P_WQTY34 => P_WQTY86 , P_WQTY35 => P_WQTY87
                                           , P_WQTY36 => P_WQTY88 , P_WQTY37 => P_WQTY89 , P_WQTY38 => P_WQTY90 , P_WQTY39 => P_WQTY91 , P_WQTY40 => P_WQTY92
                                           , P_WQTY41 => P_WQTY93 , P_WQTY42 => P_WQTY94 , P_WQTY43 => P_WQTY95 , P_WQTY44 => P_WQTY96 , P_WQTY45 => P_WQTY97
                                           , P_WQTY46 => P_WQTY98 , P_WQTY47 => P_WQTY99 , P_WQTY48 => P_WQTY100 , P_WQTY49 => P_WQTY101 , P_WQTY50 => P_WQTY102
                                           , P_WQTY51 => P_WQTY103 , P_WQTY52 => P_WQTY104
                                           , P_PARTIAL              => V_P_PARTIAL2
                                           , P_DAILYQTY             => P_DAILYQTY2
                                           , P_IS_DEBUG             => P_IS_DEBUG
                                           , O_RETURN_CODE          => V_ROWS
                                           );


                IF V_ROWS < 0 THEN
                    GOTO RETURN_ERR_CODE;
                END IF;
            END IF;

        /*  2021.03.17   KSW            temp table 일괄 drop 스크립트 추가 - start */

        DELETE FROM GT_XPGT_SCM_MST_SITE;
        DELETE FROM GT_XPGT_DAY_SCP_XLS_PSI_GLOBAL;
        DELETE FROM GT_XPGT_SCP_XLS_PSI_GLOBAL_ORG;
        DELETE FROM GT_XPGT_SCP_ANL_SHIPMENT_PLAN_FG;
        DELETE FROM GT_XPGT_SCP_ANL_SHIPMENT_PLAN_SEMI;
        DELETE FROM GT_XPGT_SCP_ANL_PRODUCTION_PLAN;
        DELETE FROM GT_XPGT_SCP_XLS_PSI_GLOBAL_MODIFY;
        DELETE FROM GT_XPGT_LINE_WORKINGTIME_LOSS;
        DELETE FROM GT_XPGT_LINELOAD;
        DELETE FROM GT_XPGT_LINELOAD_WEEK;
        DELETE FROM GT_XPGT_LINELOAD_WEEK_PIVOT;
        /*  2021.03.17   KSW            temp table 일괄 drop 스크립트 추가 - end */

        /* --------------------------------------------------------- */
        /*  실행 Logic END -- */
        /* --------------------------------------------------------- */

        /*  TXN LOG */
        V_LOG_TYPE     := 'TXN';    /* 로그타입 */

        N_LOG_COUNT    := SQL%ROWCOUNT;
        V_LOG_MESSAGE  := 'INSERT INTO ' || V_TABLE_ID;
        /*  MSSQL CONVERT(CHAR(23), @d_event_date, 121) = YYYY-MM-DD HH:MI:SS.mmm. */
        V_DESCRIPTION  := 'Process Complete...' || ':' || TO_CHAR(D_EVENT_DATE, 'YYYY-MM-DD HH24:MI:SS');
        D_EVENT_DATE   := SYSDATE;
        PR_SCP_SYS_LOG_BATCH( P_PROGRAM_NAME  => V_PROGRAM_NAME
                            , P_LOG_TYPE      => V_LOG_TYPE
                            , P_LOG_COUNT     => N_LOG_COUNT
                            , P_LOG_MESSAGE   => V_LOG_MESSAGE
                            , P_DESCRIPTION   => V_DESCRIPTION
                            , P_EVENT_DATE    => D_EVENT_DATE
                            , P_USER_ID       => V_BATCH_USER
                            );

      END;

    EXCEPTION
      WHEN OTHERS THEN

        /*           IF @@TRANCOUNT > 0
             BEGIN
               ROLLBACK;
             END; */

        /*  ERROR LOG */
        V_LOG_TYPE     := 'ERROR';
        V_LOG_MESSAGE  := SUBSTR(SQLERRM, 1, 1000);

        V_DESCRIPTION  := SUBSTR('ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 500);
        D_EVENT_DATE   := SYSDATE;
        PR_SCP_SYS_LOG_BATCH( P_PROGRAM_NAME  => V_PROGRAM_NAME
                            , P_LOG_TYPE      => V_LOG_TYPE
                            , P_LOG_COUNT     => N_LOG_COUNT
                            , P_LOG_MESSAGE   => V_LOG_MESSAGE
                            , P_DESCRIPTION   => V_DESCRIPTION
                            , P_EVENT_DATE    => D_EVENT_DATE
                            , P_USER_ID       => V_BATCH_USER
                            );
        /* 원본 L412 : return -1 (★오류다 - CATCH 안이다).
           타지 않는다) RAISE 를 신설하지 않고 값 없는 RETURN 으로 옮긴다 */
        RETURN;
    END;

    /*  임시 운영반영시에 주석처리 할것. */


    V_EXEC_TIME  :=  LPAD(TO_CHAR(TRUNC(ROUND((SYSDATE - V_START_TIME) * 86400) / 60)), 2, '0') || ':' ||
                     LPAD(TO_CHAR(MOD(ROUND((SYSDATE - V_START_TIME) * 86400), 60)), 2, '0');

    /*  종료 LOG */
    V_LOG_TYPE     := 'END';
    V_LOG_MESSAGE  := '########## END of procedure ##########';

    V_DESCRIPTION  := CASE WHEN P_DIVISION_ID IS NULL OR P_PLAN_START_YYYYMMDD IS NULL
                             OR P_MEASURE IS NULL OR P_XLS_KEY1 IS NULL OR V_EXEC_TIME IS NULL
                           THEN NULL
                           ELSE '[' || P_DIVISION_ID || '][' || P_PLAN_START_YYYYMMDD || '][' || P_MEASURE
                                || '][' || P_XLS_KEY1 || '][' || V_EXEC_TIME || ']'
                      END;
    D_EVENT_DATE   := SYSDATE;
    PR_SCP_SYS_LOG_BATCH( P_PROGRAM_NAME  => V_PROGRAM_NAME
                        , P_LOG_TYPE      => V_LOG_TYPE
                        , P_LOG_COUNT     => N_LOG_COUNT
                        , P_LOG_MESSAGE   => V_LOG_MESSAGE
                        , P_DESCRIPTION   => V_DESCRIPTION
                        , P_EVENT_DATE    => D_EVENT_DATE
                        , P_USER_ID       => V_BATCH_USER
                        );
    /* 원본 L433 : return 1 (정상 종료). 부모의 반환값은 소비자가 0건이라 값 없이 종료한다. */
    RETURN;

    <<RETURN_ERR_CODE>>
    /* 원본 L435~L438 : _RETURN_ERR_CODE: BEGIN RETURN -1 END;
       원본 RETURN -1 은 소비자 0건이라 값 없이 종료한다. */
    RETURN;

END;

PROCEDURE PR_SCP_XLS_ADD_XLSPSI01_S
(
      P_USER_ID                  VARCHAR2
    /* ,@P_GUBUN                 VARCHAR(040)       -- MEASURE  @P_GUBUN  PACK / CELL / SUPPLY */
    , P_DIVISION_ID              VARCHAR2                     /* NVARCHAR(030) */
    , P_PLAN_START_YYYYMMDD      VARCHAR2                     /* NVARCHAR(008) */
    , P_PLAN_TYPE                VARCHAR2                     /* NVARCHAR(050) */
    , P_SEQ                      NUMBER
    , P_ITEM_ID                  VARCHAR2                     /* NVARCHAR(050) */
    , P_MEASURE                  VARCHAR2                     /* NVARCHAR(050)   MEASURE별 */
    , P_XLS_KEY1                 VARCHAR2
