        /*  2022.09.19 생산계획(PACK_PROD, CELL_PROD) 일배분로직 변경 - 1/7 에서 워킹타임(CAPA 로스타임을 고려한) 비율로 변경 */
        IF V_BATCH_MEASURE IN ('PACK_PROD', 'CELL_PROD') THEN
