            /*  Working Time 에 따른 daily 분배 */
            /* -------------------------------- */

            /*  라인정보 조회 (MSSQL 대입형 SELECT -> 커서 FOR 루프) */
            FOR R IN ( SELECT PROD_LINE
                            , FROM_SITE
                            , ATTRIBUTE9
                         FROM SCP_XLS_PSI_GLOBAL
                        WHERE 0 = 0
