                 )
            SELECT P_WQTY01, P_WQTY02, P_WQTY03, P_WQTY04, P_WQTY05
            , P_WQTY06, P_WQTY07, P_WQTY08, P_WQTY09, P_WQTY10
            , P_WQTY11, P_WQTY12, P_WQTY13, P_WQTY14, P_WQTY15
