                   , WORK_DATE
                   , LOSS_CODE
                   , TIME_TERM
                   , TIME_TERM_RESULT
                   , INSERT_ID
                   , INSERT_TIME
                   , UPDATE_ID
                   , UPDATE_TIME )
            VALUES ( Y.COMPANY_ID
