                   , Y.FROM_SITE
                   , Y.BOD_ID
                   /*  , Y.TRANSPORT_MODE */
                   , Y.MEASURE
                   , Y.YYYYMMDD
                   , Y.QTY
                   , Y.ORIGIN_FROM_DIVISION_ID
                   , Y.ORIGIN_TO_DIVISION_ID
                   , Y.ELECTRODE_TYPE
                   , V_BATCH_USER_SIM
                   , SYSDATE
                   , V_BATCH_USER_SIM
                   , SYSDATE );

