                     ,ATTRIBUTE6
                     ,ATTRIBUTE7
                     ,ATTRIBUTE8
                     ,ATTRIBUTE9
                     ,ATTRIBUTE10  */
                 , HISTORY_CREATION_DATE )
            SELECT SEQ1_SCP_ANL_SHIPMENT_PLAN_FG_H.NEXTVAL   /*  MSSQL NEXT VALUE FOR seq -> Oracle seq.NEXTVAL */
                 , DIVISION_ID
                 , PLAN_START_YYYYMMDD
