                                   AND A.BASIS_YYYYMMDD     <  V_BATCH_CREATE_TO_YYYYMMDD
                               ) Y
                /*  PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 - start */
             WHERE X.YYYYMMDD_COLUMN = Y.YYYYMMDD_COLUMN
               AND Y.YYYYMMDD >= V_BOD_FROM
