                         , SYSDATE
                         , V_BATCH_USER
                         , SYSDATE )
                         ;

            /* ------------------------------------------------------------------------------------------- */
            /*  SCP_ANL_SHIPMENT_PLAN_SEMI_H : History 입력(SEMI) */
            /* ------------------------------------------------------------------------------------------- */
