                           , BOD_ID
                           , MEASURE
                           , YYYYMMDD
                           , QTY
                           , UPDATE_REASON_BOD
                           , ORIGIN_FROM_DIVISION_ID
                           , ORIGIN_TO_DIVISION_ID
                           , ELECTRODE_TYPE
                           , CREATED_BY
                           , CREATION_DATE
                           , LAST_UPDATED_BY
                           , LAST_UPDATE_DATE
