                           ) X
                 , ( SELECT A.BASIS_YYYYMMDD AS YYYYMMDD
                                     /*  MSSQL REPLICATE('0', 3 - LEN(ROW_NUMBER() OVER(..))) + CONVERT(NVARCHAR, ROW_NUMBER() OVER(..)) */
                                     , 'QTY' || LPAD(TO_CHAR(ROW_NUMBER() OVER(ORDER BY A.BASIS_YYYYMMDD)), 3, '0') AS YYYYMMDD_COLUMN
