            /*  FROZEN 구간 UPDATE */
            /*  PLANT SITE(SCM_MST_SITE)의 SHIP_FROZEN ,PROD_FROZEN를 주단위로 변경하여 FROZEN 구간을 저장 내역에서 삭제한다. */
            /* ------------------------------------------------------------------------------------------- */
            IF V_BATCH_PLAN_TYPE IN ('MA', 'SE') AND V_BATCH_MEASURE IN ('PACK_PROD') THEN
                /*  MSSQL DELETE FROM #T FROM #T X INNER JOIN #S Y ON .. WHERE .. -> DELETE FROM t WHERE EXISTS (CV-063) */
                DELETE FROM GT_XPGT_SCP_ANL_PRODUCTION_PLAN X
                 WHERE EXISTS ( SELECT 1
                                  FROM GT_XPGT_SCM_MST_SITE Y
                                 WHERE Y.DIVISION_ID = X.DIVISION_ID
                                   AND Y.SCM_SITE_ID = X.SCM_SITE_ID
                                   AND X.YYYYMMDD    < (CASE WHEN V_BATCH_PLAN_TYPE = 'MA' THEN Y.PROD_FROZEN_WEEK_DAY_MA ELSE Y.PROD_FROZEN_WEEK_DAY END) );   /* 7 */
            END IF;

               /*  PROD_PLAN_AMEND */
               /*  MSSQL : INSERT INTO SCP_ANL_PRODUCTION_PLAN (..) SELECT .. FROM ( MERGE .. OUTPUT $action, Inserted.* )
                   AS Changes(..) WHERE Action = 'INSERT'   (composable DML - Oracle 무대응)
                   = MERGE 로 실제 INSERT 된 행마다 MEASURE='PROD_PLAN_ENGINE', QTY=0 짝 행을 하나 더 넣는 로직이다.
                   MERGE 가 INSERT 할 집합 = ON 절에 매칭되지 않는 원천행이므로, 같은 조건을 NOT EXISTS 로 뽑아
                   MERGE 직전에 짝 행을 먼저 INSERT 한다. 짝 행의 MEASURE 는 'PROD_PLAN_ENGINE' 이고
                   ON 절/PK 모두 MEASURE 를 포함하므로 뒤따르는 MERGE 의 매칭 결과에 영향을 주지 않는다(1:1 등가). */
               /*  INSERT 일경우 PROD_PLAN_ENGINE/PROD_PLAN_AMEND 쌍으로 입력한다. */
               INSERT INTO SCP_ANL_PRODUCTION_PLAN
                    ( DIVISION_ID
                    , PLAN_START_YYYYMMDD
                    , PLAN_TYPE
                    , SEQ
                    , OPERATION_GROUP
                    /* , CELL_ITEM_ID */
                    , SCM_SITE_ID
                    , ITEM_ID
                    , LINE_ID
                    , OPERATION_ID
                    , MEASURE
                    , YYYYMMDD
                    , QTY
                    , ORIGIN_DIVISION_ID
                    , ELECTRODE_TYPE
                    , CELL_QTY
                    , CREATED_BY
                    , CREATION_DATE
                    , LAST_UPDATED_BY
                    , LAST_UPDATE_DATE )
               SELECT Y.DIVISION_ID
                    , Y.PLAN_START_YYYYMMDD
                    , Y.PLAN_TYPE
                    , Y.SEQ
                    , Y.OPERATION_GROUP
                    /* , Inserted.CELL_ITEM_ID */
                    , Y.SCM_SITE_ID
                    , Y.ITEM_ID
                    , Y.LINE_ID
                    , NVL(Y.OPERATION_ID, '-') AS OPERATION_ID   /* 적재처 OPERATION_ID 는 NOT NULL 이라 빈값 센티넬 '-' (H-5) */
                    , 'PROD_PLAN_ENGINE' AS MEASURE
                    , Y.YYYYMMDD
                    , 0 AS QTY
                    , Y.ORIGIN_DIVISION_ID
                    , Y.ELECTRODE_TYPE
                    , Y.CELL_QTY
                    , V_BATCH_USER   AS CREATED_BY
                    , SYSDATE        AS CREATION_DATE
                    , V_BATCH_USER   AS LAST_UPDATED_BY
                    , SYSDATE        AS LAST_UPDATE_DATE
                 FROM GT_XPGT_SCP_ANL_PRODUCTION_PLAN Y
                WHERE NOT EXISTS ( SELECT 1
                                     FROM SCP_ANL_PRODUCTION_PLAN X
                                    WHERE 0 = 0
                        AND X.DIVISION_ID         = Y.DIVISION_ID          /* @v_batch_division_id  2021.10.25 튜닝개선요청에 따른 변경 */
                        AND X.PLAN_START_YYYYMMDD = Y.PLAN_START_YYYYMMDD  /* @v_batch_PLAN_START_YYYYMMDD */
                        AND X.PLAN_TYPE           = Y.PLAN_TYPE            /* @v_batch_PLAN_TYPE */
                        AND X.SEQ                 = Y.SEQ                  /* @v_batch_SEQ */
                        AND X.OPERATION_GROUP     = Y.OPERATION_GROUP
                        AND X.SCM_SITE_ID         = Y.SCM_SITE_ID
                        AND X.ITEM_ID             = Y.ITEM_ID
                        AND X.MEASURE             = Y.MEASURE
                        AND X.YYYYMMDD            = Y.YYYYMMDD
                        AND X.LINE_ID             = Y.LINE_ID
                        AND X.OPERATION_ID        = Y.OPERATION_ID
                        AND X.ORIGIN_DIVISION_ID  = Y.ORIGIN_DIVISION_ID
                        AND NVL(X.ELECTRODE_TYPE, ' ') = NVL(Y.ELECTRODE_TYPE, ' ')
                                 )
                    ;

                       MERGE INTO SCP_ANL_PRODUCTION_PLAN X
                        USING ( SELECT DIVISION_ID
                                     , PLAN_START_YYYYMMDD
                                     , PLAN_TYPE
                                     , SEQ
                                     , OPERATION_GROUP
                                     /* , CELL_ITEM_ID */
                                     , SCM_SITE_ID
                                     , ITEM_ID
                                     , LINE_ID
                                     , OPERATION_ID
                                     , MEASURE
                                     , YYYYMMDD
                                     , QTY
                                     , ORIGIN_DIVISION_ID
                                     , ELECTRODE_TYPE
                                     , CELL_QTY
                                  FROM GT_XPGT_SCP_ANL_PRODUCTION_PLAN
                                 /* WHERE QTY > 0 */
                              ) Y
                           ON ( 0 = 0
                                AND X.DIVISION_ID         = Y.DIVISION_ID          /* @v_batch_division_id  2021.10.25 튜닝개선요청에 따른 변경 */
                                AND X.PLAN_START_YYYYMMDD = Y.PLAN_START_YYYYMMDD  /* @v_batch_PLAN_START_YYYYMMDD */
                                AND X.PLAN_TYPE           = Y.PLAN_TYPE            /* @v_batch_PLAN_TYPE */
                                AND X.SEQ                 = Y.SEQ                  /* @v_batch_SEQ */
                                AND X.OPERATION_GROUP     = Y.OPERATION_GROUP
                                AND X.SCM_SITE_ID         = Y.SCM_SITE_ID
                                AND X.ITEM_ID             = Y.ITEM_ID
                                AND X.MEASURE             = Y.MEASURE
                                AND X.YYYYMMDD            = Y.YYYYMMDD
                                AND X.LINE_ID             = Y.LINE_ID
                                AND X.OPERATION_ID        = Y.OPERATION_ID
                                AND X.ORIGIN_DIVISION_ID  = Y.ORIGIN_DIVISION_ID
                                AND NVL(X.ELECTRODE_TYPE, ' ') = NVL(Y.ELECTRODE_TYPE, ' ')
                              )
                        WHEN MATCHED THEN
                        UPDATE
                           SET X.QTY               = Y.QTY
                             /* , X.CREATED_BY         = @v_batch_user */
                             /* , X.CREATION_DATE      = GETDATE()     */
                             , X.LAST_UPDATED_BY  = V_BATCH_USER
                             , X.LAST_UPDATE_DATE = SYSDATE
                        WHEN NOT MATCHED THEN
                          INSERT ( DIVISION_ID
                                 , PLAN_START_YYYYMMDD
                                 , PLAN_TYPE
                                 , SEQ
                                 , OPERATION_GROUP
                                 /* , CELL_ITEM_ID */
                                 , SCM_SITE_ID
                                 , ITEM_ID
                                 , LINE_ID
                                 , OPERATION_ID
                                 , MEASURE
                                 , YYYYMMDD
                                 , QTY
                                 , ORIGIN_DIVISION_ID
                                 , ELECTRODE_TYPE
                                 , CELL_QTY
                                 , CREATED_BY
                                 , CREATION_DATE
                                 , LAST_UPDATED_BY
                                 , LAST_UPDATE_DATE )
                          VALUES ( Y.DIVISION_ID
                                 , Y.PLAN_START_YYYYMMDD
                                 , Y.PLAN_TYPE
                                 , Y.SEQ
                                 , Y.OPERATION_GROUP
                                 /* , Y.CELL_ITEM_ID */
                                 , Y.SCM_SITE_ID
                                 , Y.ITEM_ID
                                 , Y.LINE_ID
                                 , Y.OPERATION_ID
                                 , Y.MEASURE
                                 , Y.YYYYMMDD
                                 , Y.QTY
                                 , Y.ORIGIN_DIVISION_ID
                                 , Y.ELECTRODE_TYPE
                                 , Y.CELL_QTY
                                 , V_BATCH_USER
                                 , SYSDATE
                                 , V_BATCH_USER
                                 , SYSDATE )
                                 ;

            /* ------------------------------------------------------------------------------------------- */
            /*  SCP_ANL_PRODUCTION_PLAN_H : History 입력 */
            /* ------------------------------------------------------------------------------------------- */
            /*  SELECT top 10 * FROM dbo.SCP_ANL_PRODUCTION_PLAN_H WITH (NOLOCK)      HISTORY_SEQ */
            /*  SET @n_history_seq = NEXT VALUE FOR SEQ1_SCP_ANL_PRODUCTION_PLAN_H */
                      INSERT INTO SCP_ANL_PRODUCTION_PLAN_H
                           ( HISTORY_SEQ
                           , DIVISION_ID
                           , PLAN_START_YYYYMMDD
                           , PLAN_TYPE
                           , SEQ
                           , OPERATION_GROUP
                           , SCM_SITE_ID
                           , ITEM_ID
                           , LINE_ID
                           , OPERATION_ID
                           , MEASURE
                           , YYYYMMDD
                           , QTY
                           , ORIGIN_DIVISION_ID
                           , ELECTRODE_TYPE
                           , CREATED_BY
                           , CREATION_DATE
                           , LAST_UPDATED_BY
                           , LAST_UPDATE_DATE
                           /* ,ATTRIBUTE1
                              ,ATTRIBUTE2
                              ,ATTRIBUTE3
                              ,ATTRIBUTE4
                              ,ATTRIBUTE5
                              ,ATTRIBUTE6
                              ,ATTRIBUTE7
                              ,ATTRIBUTE8
                              ,ATTRIBUTE9
                              ,ATTRIBUTE10 */
                           , HISTORY_CREATION_DATE )
                      SELECT SEQ1_SCP_ANL_PRODUCTION_PLAN_H.NEXTVAL
                           , DIVISION_ID
                           , PLAN_START_YYYYMMDD
                           , PLAN_TYPE
                           , SEQ
                           , OPERATION_GROUP
                           , SCM_SITE_ID
                           , ITEM_ID
                           , LINE_ID
                           , OPERATION_ID
                           , MEASURE
                           , YYYYMMDD
                           , QTY
                           , ORIGIN_DIVISION_ID
                           , ELECTRODE_TYPE
                           , V_BATCH_USER   AS CREATED_BY
                           , SYSDATE        AS CREATION_DATE
                           , V_BATCH_USER   AS LAST_UPDATED_BY
                           , SYSDATE        AS LAST_UPDATE_DATE
                           /* ,ATTRIBUTE1
                              ,ATTRIBUTE2
                              ,ATTRIBUTE3
                              ,ATTRIBUTE4
                              ,ATTRIBUTE5
                              ,ATTRIBUTE6
                              ,ATTRIBUTE7
                              ,ATTRIBUTE8
                              ,ATTRIBUTE9
                              ,ATTRIBUTE10 */
                           , SYSDATE        AS HISTORY_CREATION_DATE
                        FROM GT_XPGT_SCP_ANL_PRODUCTION_PLAN
                           ;

            /* ------------------------------------------------------------------------------------------- */
            /*  SCP_ANL_PRODUCTION_PLAN_FIX : FIX 입력 */
            /* ------------------------------------------------------------------------------------------- */
                      UPDATE SCP_ANL_PRODUCTION_PLAN_FIX X   /* FIX_ID, DIVISION_ID, OPERATION_GROUP, SCM_SITE_ID, ITEM_ID, LINE_ID, OPERATION_ID, YYYYMMDD */
                         SET ( QTY
                             , ATTRIBUTE1
                             , LAST_UPDATED_BY
                             , LAST_UPDATE_DATE ) =
                             ( SELECT Y.QTY
                                    , 'Y'
                                    , V_BATCH_USER
                                    , SYSDATE
                                 FROM GT_XPGT_SCP_ANL_PRODUCTION_PLAN Y
                                WHERE 0 = 0
                                  AND X.DIVISION_ID       = Y.DIVISION_ID
                                  AND X.OPERATION_GROUP   = Y.OPERATION_GROUP
                                  AND X.SCM_SITE_ID       = Y.SCM_SITE_ID
                                  AND X.ITEM_ID           = Y.ITEM_ID
                                  AND X.LINE_ID           = Y.LINE_ID
                                  AND X.OPERATION_ID      = Y.OPERATION_ID
                                  AND X.YYYYMMDD          = Y.YYYYMMDD
                                  AND ROWNUM              = 1 )
                       WHERE EXISTS ( SELECT 1
                                        FROM GT_XPGT_SCP_ANL_PRODUCTION_PLAN Y
                                       WHERE 0 = 0
                                         AND X.DIVISION_ID       = Y.DIVISION_ID
                                         AND X.OPERATION_GROUP   = Y.OPERATION_GROUP
                                         AND X.SCM_SITE_ID       = Y.SCM_SITE_ID
                                         AND X.ITEM_ID           = Y.ITEM_ID
                                         AND X.LINE_ID           = Y.LINE_ID
                                         AND X.OPERATION_ID      = Y.OPERATION_ID
                                         AND X.YYYYMMDD          = Y.YYYYMMDD );

            /* ------------------------------------------------------------------------------------------- */
            /*  SCP_ANL_PRODUCTION_PLAN_FIX : FIX History 입력 */
            /* ------------------------------------------------------------------------------------------- */
            /*  SET @n_history_seq = NEXT VALUE FOR SEQ1_SCP_ANL_PRODUCTION_PLAN_FIX_H */
            /*  SELECT NEXT VALUE FOR SEQ1_SCP_ANL_PRODUCTION_PLAN_FIX_H */
                      INSERT INTO SCP_ANL_PRODUCTION_PLAN_FIX_H
                           ( HISTORY_SEQ
                           , FIX_ID
                           , DIVISION_ID
                           , OPERATION_GROUP
                           , SCM_SITE_ID
                           , ITEM_ID
                           , LINE_ID
                           , OPERATION_ID
                           , YYYYMMDD
                           , QTY
                           , FIX_REASON
                           , ORIGIN_DIVISION_ID
                           , ELECTRODE_TYPE
                           , CREATED_BY
                           , CREATION_DATE
                           , LAST_UPDATED_BY
                           , LAST_UPDATE_DATE
                           /* ,ATTRIBUTE1
                              ,ATTRIBUTE2
                              ,ATTRIBUTE3
                              ,ATTRIBUTE4
                              ,ATTRIBUTE5
                              ,ATTRIBUTE6
                              ,ATTRIBUTE7
                              ,ATTRIBUTE8
                              ,ATTRIBUTE9
                              ,ATTRIBUTE10 */
                           , HISTORY_CREATION_DATE )
                      SELECT SEQ1_SCP_ANL_PRODUCTION_PLAN_FIX_H.NEXTVAL
                           , FIX_ID
                           , DIVISION_ID
                           , OPERATION_GROUP
                           , SCM_SITE_ID
                           , ITEM_ID
                           , LINE_ID
                           , OPERATION_ID
                           , YYYYMMDD
                           , QTY
                           , FIX_REASON
                           , ORIGIN_DIVISION_ID
                           , ELECTRODE_TYPE
                           , V_BATCH_USER   AS CREATED_BY
                           , SYSDATE        AS CREATION_DATE
                           , V_BATCH_USER   AS LAST_UPDATED_BY
                           , SYSDATE        AS LAST_UPDATE_DATE
                           /* ,ATTRIBUTE1
                              ,ATTRIBUTE2
                              ,ATTRIBUTE3
                              ,ATTRIBUTE4
                              ,ATTRIBUTE5
                              ,ATTRIBUTE6
                              ,ATTRIBUTE7
                              ,ATTRIBUTE8
                              ,ATTRIBUTE9
                              ,ATTRIBUTE10 */
                           , SYSDATE        AS HISTORY_CREATION_DATE
                        FROM SCP_ANL_PRODUCTION_PLAN_FIX
                       WHERE ATTRIBUTE1 = 'Y'
                           ;

              /*  History 구분을 위해 원상복구 */
              UPDATE SCP_ANL_PRODUCTION_PLAN_FIX X   /* FIX_ID, DIVISION_ID, OPERATION_GROUP, SCM_SITE_ID, ITEM_ID, LINE_ID, OPERATION_ID, YYYYMMDD */
                 SET X.ATTRIBUTE1 = NULL       /* History 구분을 위해 원상복구 */
               WHERE EXISTS ( SELECT 1
                                FROM GT_XPGT_SCP_ANL_PRODUCTION_PLAN Y
                               WHERE 0 = 0
                                 AND X.DIVISION_ID     = Y.DIVISION_ID
                                 AND X.OPERATION_GROUP = Y.OPERATION_GROUP
                                 AND X.SCM_SITE_ID     = Y.SCM_SITE_ID
                                 AND X.ITEM_ID         = Y.ITEM_ID
                                 AND X.LINE_ID         = Y.LINE_ID
                                 AND X.OPERATION_ID    = Y.OPERATION_ID
                                 AND X.YYYYMMDD        = Y.YYYYMMDD )
                 AND X.ATTRIBUTE1 = 'Y';

            END IF;

            /* --------------------------------------------------------- */
            /*  FROZEN 구간 복구 */
            /* --------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(P_CREATE_FROM_YYYYMMDD);
            DBMS_OUTPUT.PUT_LINE(P_CREATE_TO_YYYYMMDD);
            /* ------------------------------------------------------------------------------------------- */
            /*  전체 임시 테이블 생성  (#SCP_XLS_PSI_GLOBAL_MODIFY) */
            /* ------------------------------------------------------------------------------------------- */
            /*                DROP TABLE #SCP_XLS_PSI_GLOBAL_MODIFY
                CREATE TABLE #SCP_XLS_PSI_GLOBAL_MODIFY( XLS_KEY1 INT NOT NULL, DIVISION_ID NVARCHAR(30) NOT NULL,
                  CREATE_FROM_YYYYMMDD NVARCHAR(8) NOT NULL, QTY001 NUMERIC(20,10) NULL, .. QTY364 NUMERIC(20,10) NULL ) */
            DELETE FROM GT_XPGT_SCP_XLS_PSI_GLOBAL_MODIFY;

            DBMS_OUTPUT.PUT_LINE('66666666666666666666666666666');

            V_X_ITEM_ID         := '';
            /*  SCP_ANL_SHIPMENT_PLAN_FG/SEMI PK Parameter */
            V_X_OPERATION_GROUP := '';   /* BIZ_TYPE */
            V_X_PROJECT_CODE    := '';
            V_X_TO_SITE         := '';
            V_X_INCOTERMS       := '';
            V_X_FROM_SITE       := '';   /* SCM_SITE_ID */
            V_X_BOD_ID          := '';
            /*  SCP_ANL_PRODUCTION_PLAN PK Parameter */
            V_X_LINE_ID         := '';
            V_X_OPERATION_ID    := '';

            /*  MSSQL 대입형 SELECT : 0행이면 기존값 유지, 다행이면 마지막 행 -> 커서 FOR 루프(SELECT INTO 금지). */
            FOR R IN ( SELECT OPERATION_GROUP
                            , ITEM_ID
                            , PROD_LINE
                            , ATTRIBUTE9
                            , PROJECT_CODE
                            , TO_SITE
                            , INCOTERMS
                            , FROM_SITE
                            , BOD_ID
                         FROM SCP_XLS_PSI_GLOBAL_SMALL_PACK
                        WHERE DIVISION_ID          = V_BATCH_DIVISION_ID
                          AND PLAN_START_YYYYMMDD  = V_BATCH_PLAN_START_YYYYMMDD
                          AND CREATE_FROM_YYYYMMDD = V_BATCH_CREATE_FROM_YYYYMMDD
                          AND PLAN_TYPE            = V_BATCH_PLAN_TYPE
                          AND SEQ                  = V_BATCH_SEQ
                          AND XLS_KEY1             = V_BATCH_XLS_KEY1
                     )
            LOOP
                V_X_OPERATION_GROUP := R.OPERATION_GROUP;
                V_X_ITEM_ID         := R.ITEM_ID;
                V_X_LINE_ID         := R.PROD_LINE;
                V_X_OPERATION_ID    := R.ATTRIBUTE9;
                V_X_PROJECT_CODE    := R.PROJECT_CODE;
                V_X_TO_SITE         := R.TO_SITE;
                V_X_INCOTERMS       := R.INCOTERMS;
                V_X_FROM_SITE       := R.FROM_SITE;
                V_X_BOD_ID          := R.BOD_ID;
            END LOOP;

        /* --------------------------------------------------------- */
        /*  FROZEN 구간 복구 */
        /* --------------------------------------------------------- */
        /*  2022.08.25 PACK_PROD 만 FROZEN 처리되는 것으로 오류수정 */
        IF V_BATCH_MEASURE = 'PACK_PROD' THEN   /* XXXXXX */
            /* ------------------------------------------------------------------------------------------- */
            /*  저장후 시물레이션 데이터 UPDATE */
            /* ------------------------------------------------------------------------------------------- */
            /*  MSSQL SELECT @v = @v + .. FROM (..) ORDER BY .. (행별 문자열 누적 트릭, EP-013) */
            V_MQRY_SUM2 := '';
            FOR R IN ( SELECT ' SUM(CASE WHEN YYYYMMDD = ''' || A.YYYYMMDD || '''    THEN QTY ELSE 0 END ) AS '
                              || 'QTY' || LPAD(TO_CHAR(ROW_NUMBER() OVER(ORDER BY A.YYYYMMDD)), 3, '0') AS COL_EXPR
                         FROM ( SELECT A.BASIS_YYYYMMDD                      AS YYYYMMDD
                                     , A.BASIS_YYYYMMDD || TO_CHAR(31)       AS SORT_ORDER_NO
                                  FROM SCM_SYS_CALENDAR_M A
                                 /*  WHERE A.BASIS_YYYYMMDD >= @p_plan_start_yyyymmdd
                                       AND A.BASIS_YYYYMMDD <  @p_to_yyyymmdd  */
                                 WHERE A.BASIS_YYYYMMDD     >= V_BATCH_CREATE_FROM_YYYYMMDD
                                   AND A.BASIS_YYYYMMDD     <  V_BATCH_CREATE_TO_YYYYMMDD
                                 GROUP BY A.BASIS_YYYYMMDD
                              ) A
                        ORDER BY A.SORT_ORDER_NO )
            LOOP
                V_MQRY_SUM2 := V_MQRY_SUM2 || ',' || R.COL_EXPR || '' || CHR(10);
            END LOOP;

            V_MEXEC2 := '';
            /*  MSSQL INSERT INTO #.. WITH (TABLOCK) : TABLOCK 힌트는 Oracle 무대응이라 제거(H-13) */
            V_MEXEC2 := V_MEXEC2 || ' INSERT INTO GT_XPGT_SCP_XLS_PSI_GLOBAL_MODIFY  ' || CHR(10);

            /* ------------------------------------------------------------------------------------------- */
            /*  'SHIP_PLAN' */
            /*  PK : DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, SEQ, YYYYMMDD, BIZ_TYPE, ITEM_ID, PROJECT_CODE, TO_SITE, INCOTERMS, FROM_SITE, BOD_ID, MEASURE */
            /* ------------------------------------------------------------------------------------------- */
            V_MFG := '';
            V_MFG := V_MFG || ' SELECT  ''' || TO_CHAR(V_BATCH_XLS_KEY1) || ''' AS XLS_KEY1  ' || CHR(10);
            V_MFG := V_MFG || '         ,''' || V_BATCH_DIVISION_ID || ''' AS DIVISION_ID  ' || CHR(10);
            V_MFG := V_MFG || '         ,''' || V_BATCH_CREATE_FROM_YYYYMMDD || ''' AS CREATE_FROM_YYYYMMDD  ' || CHR(10);
            V_MFG := V_MFG || '           ' || V_MQRY_SUM2 || '                       ' || CHR(10);
            V_MFG := V_MFG || '    FROM SCP_ANL_SHIPMENT_PLAN_FG  ' || CHR(10);
            V_MFG := V_MFG || '    WHERE 0 = 0                                 ' || CHR(10);
            V_MFG := V_MFG || '    AND DIVISION_ID         =  ''' || V_BATCH_DIVISION_ID || '''' || CHR(10);
            V_MFG := V_MFG || '    AND PLAN_START_YYYYMMDD =  ''' || V_BATCH_PLAN_START_YYYYMMDD || '''' || CHR(10);
            V_MFG := V_MFG || '    AND PLAN_TYPE           =  ''' || V_BATCH_PLAN_TYPE || '''' || CHR(10);
            V_MFG := V_MFG || '    AND SEQ                 =  ' || TO_CHAR(V_BATCH_SEQ) || '' || CHR(10);
            V_MFG := V_MFG || '    AND BIZ_TYPE            =  ''' || V_X_OPERATION_GROUP || '''' || CHR(10);
            V_MFG := V_MFG || '    AND ITEM_ID             =  ''' || V_X_ITEM_ID || '''' || CHR(10);
            V_MFG := V_MFG || '    AND PROJECT_CODE        =  ''' || V_X_PROJECT_CODE || '''' || CHR(10);
            V_MFG := V_MFG || '    AND TO_SITE             =  ''' || V_X_TO_SITE || '''' || CHR(10);
            V_MFG := V_MFG || '    AND INCOTERMS           =  ''' || V_X_INCOTERMS || '''' || CHR(10);
            V_MFG := V_MFG || '    AND FROM_SITE           =  ''' || V_X_FROM_SITE || '''' || CHR(10);
            V_MFG := V_MFG || '    AND BOD_ID              =  ''' || V_X_BOD_ID || '''' || CHR(10);
            V_MFG := V_MFG || '    AND MEASURE             = ''SHIP_PLAN_AMEND'' ' || CHR(10);
            /*  SET @mFG = @mFG + ' 		AND YYYYMMDD            <  '''+ @p_to_yyyymmdd +''''+CHAR(10); */
            V_MFG := V_MFG || '    AND YYYYMMDD            >=  ''' || V_BATCH_CREATE_FROM_YYYYMMDD || '''' || CHR(10);
            V_MFG := V_MFG || '    AND YYYYMMDD            <  ''' || V_BATCH_CREATE_TO_YYYYMMDD || '''' || CHR(10);

            /* ------------------------------------------------------------------------------------------- */
            /*  'SEMI_SHIP_PLAN' */
            /*  PK : DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, SEQ, OPERATION_GROUP, ITEM_ID, FROM_SITE, BOD_ID, MEASURE, YYYYMMDD */
            /*  2021.04.2 KSW C20210420-000399-소형 Pack 시뮬레이터 Cell - Packer 반제품 Shipment 저장 가능하도록 수정 - start */
            /*                - CELL_SHIP_PLAN (Ship Plan(SCP)) Measure 를 SEMI_SHIP_PLAN 에 준하여 처리하는 로직을 추가, 주석해제 */
            /* ------------------------------------------------------------------------------------------- */
            V_MSEMI := '';
            V_MSEMI := V_MSEMI || ' SELECT  ''' || TO_CHAR(V_BATCH_XLS_KEY1) || ''' AS XLS_KEY1  ' || CHR(10);
            V_MSEMI := V_MSEMI || '         ,''' || V_BATCH_DIVISION_ID || ''' AS DIVISION_ID  ' || CHR(10);
            V_MSEMI := V_MSEMI || '         ,''' || V_BATCH_CREATE_FROM_YYYYMMDD || ''' AS CREATE_FROM_YYYYMMDD  ' || CHR(10);
            V_MSEMI := V_MSEMI || '           ' || V_MQRY_SUM2 || '                       ' || CHR(10);
            V_MSEMI := V_MSEMI || '    FROM SCP_ANL_SHIPMENT_PLAN_SEMI  ' || CHR(10);
            V_MSEMI := V_MSEMI || '    WHERE 0 = 0                                 ' || CHR(10);
            V_MSEMI := V_MSEMI || '    AND DIVISION_ID         =  ''' || V_BATCH_DIVISION_ID || '''' || CHR(10);
            V_MSEMI := V_MSEMI || '    AND PLAN_START_YYYYMMDD =  ''' || V_BATCH_PLAN_START_YYYYMMDD || '''' || CHR(10);
            V_MSEMI := V_MSEMI || '    AND PLAN_TYPE           =  ''' || V_BATCH_PLAN_TYPE || '''' || CHR(10);
            V_MSEMI := V_MSEMI || '    AND SEQ                 =  ' || TO_CHAR(V_BATCH_SEQ) || '' || CHR(10);
            V_MSEMI := V_MSEMI || '    AND OPERATION_GROUP     =  ''' || V_X_OPERATION_GROUP || '''' || CHR(10);
            V_MSEMI := V_MSEMI || '    AND ITEM_ID             =  ''' || V_X_ITEM_ID || '''' || CHR(10);
            V_MSEMI := V_MSEMI || '    AND FROM_SITE           =  ''' || V_X_FROM_SITE || '''' || CHR(10);
            V_MSEMI := V_MSEMI || '    AND BOD_ID              =  ''' || V_X_BOD_ID || '''' || CHR(10);
            V_MSEMI := V_MSEMI || '    AND MEASURE             = ''SHIP_PLAN_AMEND'' ' || CHR(10);
            /*  SET @mSEMI = @mSEMI + ' 		AND YYYYMMDD            <  '''+ @p_to_yyyymmdd +''''+CHAR(10); */
            V_MSEMI := V_MSEMI || '    AND YYYYMMDD            >=  ''' || V_BATCH_CREATE_FROM_YYYYMMDD || '''' || CHR(10);
            V_MSEMI := V_MSEMI || '    AND YYYYMMDD            <  ''' || V_BATCH_CREATE_TO_YYYYMMDD || '''' || CHR(10);

            /* ------------------------------------------------------------------------------------------- */
            /*  'PACK_PROD','CELL_PROD' */
            /*  PK : DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, SEQ, OPERATION_GROUP, SCM_SITE_ID, ITEM_ID, LINE_ID, OPERATION_ID, MEASURE, YYYYMMDD */
            /* ------------------------------------------------------------------------------------------- */
            V_MPROD := '';
            V_MPROD := V_MPROD || ' SELECT  ''' || TO_CHAR(V_BATCH_XLS_KEY1) || ''' AS XLS_KEY1  ' || CHR(10);
            V_MPROD := V_MPROD || '         ,''' || V_BATCH_DIVISION_ID || ''' AS DIVISION_ID  ' || CHR(10);
            V_MPROD := V_MPROD || '         ,''' || V_BATCH_CREATE_FROM_YYYYMMDD || ''' AS CREATE_FROM_YYYYMMDD  ' || CHR(10);
            V_MPROD := V_MPROD || '           ' || V_MQRY_SUM2 || '                       ' || CHR(10);
            V_MPROD := V_MPROD || '    FROM SCP_ANL_PRODUCTION_PLAN  ' || CHR(10);
            V_MPROD := V_MPROD || '    WHERE 0 = 0                                 ' || CHR(10);
            V_MPROD := V_MPROD || '    AND DIVISION_ID         =  ''' || V_BATCH_DIVISION_ID || '''' || CHR(10);
            V_MPROD := V_MPROD || '    AND PLAN_START_YYYYMMDD =  ''' || V_BATCH_PLAN_START_YYYYMMDD || '''' || CHR(10);
            V_MPROD := V_MPROD || '    AND PLAN_TYPE           =  ''' || V_BATCH_PLAN_TYPE || '''' || CHR(10);
            V_MPROD := V_MPROD || '    AND SEQ                 =  ' || TO_CHAR(V_BATCH_SEQ) || '' || CHR(10);
            V_MPROD := V_MPROD || '    AND OPERATION_GROUP     =  ''' || V_X_OPERATION_GROUP || '''' || CHR(10);
            V_MPROD := V_MPROD || '    AND SCM_SITE_ID         =  ''' || V_X_FROM_SITE || '''' || CHR(10);
            V_MPROD := V_MPROD || '    AND ITEM_ID             =  ''' || V_X_ITEM_ID || '''' || CHR(10);
            V_MPROD := V_MPROD || '    AND LINE_ID             =  ''' || V_X_LINE_ID || '''' || CHR(10);
