            /* ------------------------------------------------------------------------------------------- */
            /*  LINE_TOTAL_LOAD_ENGINE UPDATE (TACT_TIME,WORKING_TIME)  , PACK_PROD_LOAD */
            /* ------------------------------------------------------------------------------------------- */
            /*  Line Load 율 로직 작업중 */
            /* ------------------------------------------------------------------------------------------- */
            /*  IF OBJECT_ID('tempdb..#LINE_WORKINGTIME_BY_LOSS') IS NOT NULL DROP TABLE #LINE_WORKINGTIME_BY_LOSS */

            DELETE FROM GT_XPGT_LINE_WORKINGTIME_LOSS;

            /*  저장속도개선 : FN_LINE_WORKINGTIME_BY_LOSS 을 사용하지 않고 FN_LINE_WORKINGTIME_BY_LOSS 에 정의된 쿼리를 직접사용 */

            INSERT INTO GT_XPGT_LINE_WORKINGTIME_LOSS
                 ( DIVISION_ID
                 , SCM_SITE_ID
                 , OPERATION_ID
                 , LINE_ID
                 , YYYYMMDD
                 , WORKING_TIME )
            SELECT A.DIVISION_ID
                 , A.PLANT_SITE_ID AS SCM_SITE_ID
                 , A.OPERATION_ID
                 , A.LINE_ID
                 , A.YYYYMMDD

                 , (CASE WHEN C.LOSS_START_DATE IS NOT NULL THEN A.WORKING_TIME - TRUNC(NVL(C.SETUP_LOSS_TIME_MIN, 0))
                         ELSE A.WORKING_TIME - TRUNC(A.WORKING_TIME_RATE * NVL(B.SETUP_LOSS_TIME_MIN, 0)) END) AS WORKING_TIME
              FROM ( SELECT W.*
                          , W.WORKING_TIME / 1440.0 AS WORKING_TIME_RATE
                       FROM SCP_MST_WORKING_TIME W
                      WHERE W.DIVISION_ID   = V_BATCH_DIVISION_ID   /* '40'  20180709 주석처리 */
                        AND W.PLANT_SITE_ID = V_P_FROM_SITE
                   ) A
                   LEFT OUTER JOIN SCM_MST_SITE S
                           ON S.DIVISION_ID = A.DIVISION_ID
                          AND S.SCM_SITE_ID = A.PLANT_SITE_ID
                          AND (S.OSP_YN = 'N' OR (S.OSP_YN = 'Y' AND NVL(S.ATTRIBUTE1, 'N') = 'Y' AND A.LINE_ID <> '-'))
                   LEFT OUTER JOIN ( SELECT B.*
                                       FROM SCP_MST_LOSS_TIME B
                                      WHERE B.DIVISION_ID   = V_BATCH_DIVISION_ID
                                        AND B.PLANT_SITE_ID = V_P_FROM_SITE
                                   ) B
                           ON A.DIVISION_ID   = B.DIVISION_ID
                          AND A.PLANT_SITE_ID = B.PLANT_SITE_ID
                          AND A.FACTORY_ID    = B.FACTORY_ID
                          AND A.OPERATION_ID  = B.OPERATION_ID
                          AND A.LINE_ID       = B.LINE_ID
                   LEFT OUTER JOIN ( SELECT DIVISION_ID
                                          , PLANT_SITE_ID
                                          , FACTORY_ID
                                          , OPERATION_ID
                                          , LINE_ID
                                          , LOSS_START_DATE
                                          , LOSS_END_DATE
                                          , LOSS_TIME_MIN
                                          , SETUP_LOSS_TIME_MIN
                                       FROM SCP_MST_LOSS_TIME_EXCEPT
                                      WHERE DIVISION_ID   = V_BATCH_DIVISION_ID
                                        AND PLANT_SITE_ID = V_P_FROM_SITE
                                   ) C
                           ON A.DIVISION_ID   = C.DIVISION_ID
                          AND A.PLANT_SITE_ID = C.PLANT_SITE_ID
                          AND A.FACTORY_ID    = C.FACTORY_ID
                          AND A.OPERATION_ID  = C.OPERATION_ID
                          AND A.LINE_ID       = C.LINE_ID
                          AND A.YYYYMMDD      >= C.LOSS_START_DATE
                          AND A.YYYYMMDD      <= C.LOSS_END_DATE
             WHERE A.DIVISION_ID    = V_BATCH_DIVISION_ID
               AND A.YYYYMMDD      >= V_BATCH_CREATE_FROM_YYYYMMDD
               AND A.YYYYMMDD      <= V_BATCH_CREATE_TO_YYYYMMDD

            UNION ALL

            SELECT A.DIVISION_ID
                 , A.PLANT_SITE_ID
                 , A.OPERATION_ID
                 , A.LINE_ID
                 , A.YYYYMMDD
                 , ( SELECT NVL(SUM(NVL(C.DAILY_CAPA_QTY, 0)), 0)
                       FROM SCP_MST_OUTSOURCING_CAPA C
                      WHERE C.DIVISION_ID   = A.DIVISION_ID
                        AND C.PLANT_SITE_ID = A.PLANT_SITE_ID
                        AND C.ITEM_ID       = '-'
                   ) AS WORKING_TIME
              FROM ( SELECT W.*
                          , W.WORKING_TIME / 1440.0 AS WORKING_TIME_RATE
                       FROM SCP_MST_WORKING_TIME W
                          , SCM_MST_SITE         S
                      WHERE W.DIVISION_ID   = V_BATCH_DIVISION_ID
