 *       원본 L117 return -1 : PLAN_TYPE 이 FN 이면 수정금지 = ★정상 스킵(에러 아님)
 *       원본 L1351 return -1 : CATCH 블록 = 에러(로그만 남기고 흡수, 원본대로 RAISE 하지 않는다)
 *       원본 L1372 return 1 : 정상 종료
 *     ★#SCM_MST_SITE 는 이 프로시저가 만들지 않는다 - 부모 PR_SCP_XLS_ADD_XLSPSI03 가 채우고 자식이 읽는
 *     ★#DAY_SCP_XLS_PSI_GLOBAL 은 원본이 SCP_XLS_PSI_GLOBAL_SMALL_CELL(458컬럼) 의 SELECT * INTO 인데
 *   - WITH (NOLOCK) 은 Oracle 다중버전 읽기일관성으로 대응이 없어 전 구문에서 제거.
 *     같은 미매칭 집합을 뽑아 PROD_PLAN_ENGINE 짝 행을 먼저 INSERT 한다(1:1 등가).
 *   - IN 파라미터 재대입 불가 : 원본 L305 가 @p_user_id 를 덮어쓰므로 지역변수 V_P_USER_ID 로 옮겼다.
 */
AS
    /*  MSSQL @p_user_id VARCHAR(100). 본문 L305 에서 재대입하므로 IN 파라미터를 지역변수로 옮긴다 */
    V_P_USER_ID                  VARCHAR2(100 CHAR);
    /*  LOG 용 변수 설정 */
    V_BATCH_USER                 VARCHAR2(150 CHAR) := '';
    V_PROGRAM_NAME               VARCHAR2(150 CHAR) := 'PR_SCP_XLS_ADD_XLSPSI03_S';
    V_LOG_TYPE                   VARCHAR2(30 CHAR);        /* START/END/ERROR/... */
    N_LOG_COUNT                  INTEGER := 0;
    V_LOG_MESSAGE                VARCHAR2(1000 CHAR);
    V_DESCRIPTION                VARCHAR2(500 CHAR);
    V_TABLE_ID                   VARCHAR2(150 CHAR) := 'SCP_XLS_PSI_GLOBAL_SMALL_CELL';   /* 테이블 */
    D_EVENT_DATE                 DATE;
    /*  임시 실행시간 확인용 */
    V_START_TIME                 DATE;
    V_EXEC_TIME                  VARCHAR2(10 CHAR);        /* '[00:00]'; */
    V_P_TO_YYYYMMDD              VARCHAR2(8 CHAR);
    /*  HISTORY SEQ (원본은 선언만 하고 본문 사용 0건) */
    N_HISTORY_SEQ                INTEGER;
    /*  SCP_ANL_SHIPMENT_PLAN_FG/SEMI PK Parameter, SCP_ANL_PRODUCTION_PLAN PK Parameter */
    V_X_ITEM_ID                  VARCHAR2(50 CHAR);
    V_X_OPERATION_GROUP          VARCHAR2(50 CHAR);        /* BIZ_TYPE */
