    V_MQRY_SUM2                  CLOB;
    V_MEXEC2                     CLOB;
    V_MPROD                      CLOB;
    V_MQRY_SUM                   CLOB;
    V_MEXEC                      CLOB;
    /*  수정전 QTY 변수 */

    V_X_WQTY01 PLS_INTEGER := 0; V_X_WQTY02 PLS_INTEGER := 0; V_X_WQTY03 PLS_INTEGER := 0; V_X_WQTY04 PLS_INTEGER := 0; V_X_WQTY05 PLS_INTEGER := 0;
    V_X_WQTY06 PLS_INTEGER := 0; V_X_WQTY07 PLS_INTEGER := 0; V_X_WQTY08 PLS_INTEGER := 0; V_X_WQTY09 PLS_INTEGER := 0; V_X_WQTY10 PLS_INTEGER := 0;
