    V_X_WQTY31 PLS_INTEGER := 0; V_X_WQTY32 PLS_INTEGER := 0; V_X_WQTY33 PLS_INTEGER := 0; V_X_WQTY34 PLS_INTEGER := 0; V_X_WQTY35 PLS_INTEGER := 0;
