    O_RETURN_CODE := 1;


    /* LOG 용 변수 설정 */
    /*  MSSQL @p_user_id 는 VARCHAR(100) 이라 L305 의 문자열 덧붙이기가 100자에서 조용히 잘린다.
        같은 폭의 지역변수 + SUBSTR 로 그 절단까지 1:1 재현한다. */
    V_P_USER_ID       := SUBSTR(P_USER_ID, 1, 100);
    V_BATCH_USER      := V_P_USER_ID;

  /*  시작 LOG */
    V_LOG_TYPE        := 'START';
    V_LOG_MESSAGE     := '########## Start of procedure ##########';
    V_DESCRIPTION     := V_PROGRAM_NAME || ':' || ' SCP_XLS_PSI_GLOBALSMALL_CELL SAVE LOGIC';
    D_EVENT_DATE      := SYSDATE;
    PR_SCP_SYS_LOG_BATCH( P_PROGRAM_NAME  => V_PROGRAM_NAME
                        , P_LOG_TYPE      => V_LOG_TYPE
                        , P_LOG_COUNT     => N_LOG_COUNT
                        , P_LOG_MESSAGE   => V_LOG_MESSAGE
                        , P_DESCRIPTION   => V_DESCRIPTION
                        , P_EVENT_DATE    => D_EVENT_DATE
                        , P_USER_ID       => V_BATCH_USER
                        );

        /*  임시 실행시간 확인용 */
    V_START_TIME      := SYSDATE;
    V_EXEC_TIME       := '';

    /* PRINT @p_plan_type */
    /*  PLAN_TYPE이 FN일경우 수정금지 RETURN */
    IF P_PLAN_TYPE = 'FN' THEN
        /*  원본 L116~117 : if @p_plan_type = 'FN' return -1 */
        O_RETURN_CODE := -1;
        RETURN;
    END IF;

    /* --------------------------------------------------------------------------------------------------- */
    /* -- 입력된 버전과 현재 버전이 다를 경우 RETURN */
    /* --------------------------------------------------------------------------------------------------- */
    /*     DECLARE   @v_division_id          NVARCHAR(030) = @p_division_id
                 , @v_plan_start_yyyymmdd  NVARCHAR(008) = @p_plan_start_yyyymmdd
                 , @v_plan_type            NVARCHAR(050) = @p_plan_type
                 , @v_seq                  INT           = @p_seq

         SELECT TOP 1  @v_division_id          = DIVISION_ID
                     , @v_plan_start_yyyymmdd  = PLAN_START_YYYYMMDD
                     , @v_plan_type            = PLAN_TYPE
                     , @v_seq                  = SEQ
           FROM SCP_XLS_PSI_GLOBAL_SMALL_CELL WITH (NOLOCK)

       IF (@p_division_id <> @v_division_id OR @p_plan_start_yyyymmdd <> @v_plan_start_yyyymmdd OR @p_plan_type <> @v_plan_type OR @p_seq <> @v_seq)
         return -1                                                                    */
    /* --------------------------------------------------------------------------------------------------- */

      /* PRINT @p_plan_type */
    BEGIN
      BEGIN

            /*  CONVERT(VARCHAR(8), DATEADD(day, 364, @p_plan_start_yyyymmdd), 112) */
            V_P_TO_YYYYMMDD := P_CREATE_TO_YYYYMMDD;

            /* ------------------------------------------------------------------------------------------- */
            /*  수정하기전의 테이블에 존재하는 데이타를 가져와서 변수에 담아둔다. */
            /* ------------------------------------------------------------------------------------------- */
            /*  MSSQL 대입형 SELECT : 0행이면 기존값 유지, 다행이면 마지막 행 -> 커서 FOR 루프(SELECT INTO 금지). */
            FOR R IN ( SELECT WQTY01, WQTY02, WQTY03, WQTY04, WQTY05
                            , WQTY06, WQTY07, WQTY08, WQTY09, WQTY10
                            , WQTY11, WQTY12, WQTY13, WQTY14, WQTY15
                            , WQTY16, WQTY17, WQTY18, WQTY19, WQTY20
                            , WQTY21, WQTY22, WQTY23, WQTY24, WQTY25
                            , WQTY26, WQTY27, WQTY28, WQTY29, WQTY30
                            , WQTY31, WQTY32, WQTY33, WQTY34, WQTY35
                            , WQTY36, WQTY37, WQTY38, WQTY39, WQTY40
                            , WQTY41, WQTY42, WQTY43, WQTY44, WQTY45
                            , WQTY46, WQTY47, WQTY48, WQTY49, WQTY50
                            , WQTY51, WQTY52
                         FROM SCP_XLS_PSI_GLOBAL_SMALL_CELL
                        WHERE 0 = 0
                          AND DIVISION_ID          = P_DIVISION_ID
                          AND PLAN_START_YYYYMMDD  = P_PLAN_START_YYYYMMDD
                          AND CREATE_FROM_YYYYMMDD = P_CREATE_FROM_YYYYMMDD
                          AND SEQ                  = P_SEQ
                          AND XLS_KEY1             = P_XLS_KEY1
                     )
            LOOP
                V_X_WQTY01 := R.WQTY01; V_X_WQTY02 := R.WQTY02; V_X_WQTY03 := R.WQTY03; V_X_WQTY04 := R.WQTY04; V_X_WQTY05 := R.WQTY05;
                V_X_WQTY06 := R.WQTY06; V_X_WQTY07 := R.WQTY07; V_X_WQTY08 := R.WQTY08; V_X_WQTY09 := R.WQTY09; V_X_WQTY10 := R.WQTY10;
                V_X_WQTY11 := R.WQTY11; V_X_WQTY12 := R.WQTY12; V_X_WQTY13 := R.WQTY13; V_X_WQTY14 := R.WQTY14; V_X_WQTY15 := R.WQTY15;
                V_X_WQTY16 := R.WQTY16; V_X_WQTY17 := R.WQTY17; V_X_WQTY18 := R.WQTY18; V_X_WQTY19 := R.WQTY19; V_X_WQTY20 := R.WQTY20;
