                /*                    ★GT_XPGT_SCM_MST_SITE 는 부모 PR_SCP_XLS_ADD_XLSPSI03 가 채우는 결합쌍 공유 GTT 다(읽기 전용). */
                DELETE FROM GT_XPGT_SCP_ANL_PRODUCTION_PLAN X
                 WHERE EXISTS ( SELECT 1
                                  FROM GT_XPGT_SCM_MST_SITE Y
                                 WHERE Y.DIVISION_ID = X.DIVISION_ID
                                   AND Y.SCM_SITE_ID = X.SCM_SITE_ID
                                   AND X.YYYYMMDD    < (CASE WHEN P_PLAN_TYPE = 'MA' THEN Y.PROD_FROZEN_WEEK_DAY_MA ELSE Y.PROD_FROZEN_WEEK_DAY END) );   /* 7 */
            END IF;

               /*  PROD_PLAN_AMEND */
               /*  MSSQL : INSERT INTO SCP_ANL_PRODUCTION_PLAN (..) SELECT .. FROM ( MERGE .. OUTPUT $action, Inserted.* )
                   AS Changes(..) WHERE Action = 'INSERT'   (composable DML - Oracle 무대응)
                   = MERGE 로 실제 INSERT 된 행마다 MEASURE='PROD_PLAN_ENGINE', QTY=0 짝 행을 하나 더 넣는 로직이다.
                   MERGE 가 INSERT 할 집합 = ON 절에 매칭되지 않는 원천행이므로, 같은 조건을 NOT EXISTS 로 뽑아
                   MERGE 직전에 짝 행을 먼저 INSERT 한다(1:1 등가). */
               /*  INSERT 일경우 PROD_PLAN_ENGINE/PROD_PLAN_AMEND 쌍으로 입력한다. */
               INSERT INTO SCP_ANL_PRODUCTION_PLAN
                    ( DIVISION_ID
                    , PLAN_START_YYYYMMDD
                    , PLAN_TYPE
                    , SEQ
                    , OPERATION_GROUP
                    , SCM_SITE_ID
                    , ITEM_ID
                    , LINE_ID
                    , OPERATION_ID
                    , MEASURE
                    , YYYYMMDD
                    , QTY
                    , ORIGIN_DIVISION_ID
                    , ELECTRODE_TYPE
                    , CELL_QTY
                    , CREATED_BY
                    , CREATION_DATE
                    , LAST_UPDATED_BY
                    , LAST_UPDATE_DATE )
               SELECT Y.DIVISION_ID
                    , Y.PLAN_START_YYYYMMDD
                    , Y.PLAN_TYPE
                    , Y.SEQ
                    , Y.OPERATION_GROUP
                    /* , Inserted.CELL_ITEM_ID */
                    , Y.SCM_SITE_ID
                    , Y.ITEM_ID
                    , Y.LINE_ID
                    , NVL(Y.OPERATION_ID, '-') AS OPERATION_ID   /* 적재처 OPERATION_ID 는 NOT NULL 이라 빈값 센티넬 '-' (H-5) */
                    , 'PROD_PLAN_ENGINE' AS MEASURE
                    , Y.YYYYMMDD
                    , 0 AS QTY
                    , Y.ORIGIN_DIVISION_ID
                    , Y.ELECTRODE_TYPE
                    , Y.CELL_QTY
                    , V_P_USER_ID   AS CREATED_BY
                    , SYSDATE       AS CREATION_DATE
                    , V_P_USER_ID   AS LAST_UPDATED_BY
                    , SYSDATE       AS LAST_UPDATE_DATE
                 FROM GT_XPGT_SCP_ANL_PRODUCTION_PLAN Y
                WHERE NOT EXISTS ( SELECT 1
                                     FROM SCP_ANL_PRODUCTION_PLAN X
                                    WHERE 0 = 0
                        AND X.DIVISION_ID         = Y.DIVISION_ID          /* @p_division_id  2021.10.25 튜닝개선요청에 따른 변경 */
                        AND X.PLAN_START_YYYYMMDD = Y.PLAN_START_YYYYMMDD  /* @p_PLAN_START_YYYYMMDD */
                        AND X.PLAN_TYPE           = Y.PLAN_TYPE            /* @p_PLAN_TYPE */
                        AND X.SEQ                 = Y.SEQ                  /* @p_SEQ */
                        AND X.OPERATION_GROUP     = Y.OPERATION_GROUP
                        AND X.SCM_SITE_ID         = Y.SCM_SITE_ID
                        AND X.ITEM_ID             = Y.ITEM_ID
                        AND X.MEASURE             = Y.MEASURE
                        AND X.YYYYMMDD            = Y.YYYYMMDD
                        AND X.LINE_ID             = Y.LINE_ID
                        AND X.OPERATION_ID        = Y.OPERATION_ID
                        AND X.ORIGIN_DIVISION_ID  = Y.ORIGIN_DIVISION_ID
                        AND NVL(X.ELECTRODE_TYPE, ' ') = NVL(Y.ELECTRODE_TYPE, ' ')
                                 )
                    ;

                       MERGE INTO SCP_ANL_PRODUCTION_PLAN X
                        USING ( SELECT DIVISION_ID
                                     , PLAN_START_YYYYMMDD
                                     , PLAN_TYPE
                                     , SEQ
                                     , OPERATION_GROUP
                                     , SCM_SITE_ID
                                     , ITEM_ID
                                     , LINE_ID
                                     , OPERATION_ID
                                     , MEASURE
                                     , YYYYMMDD
                                     , QTY
                                     , ORIGIN_DIVISION_ID
                                     , ELECTRODE_TYPE
                                     , CELL_QTY
                                  FROM GT_XPGT_SCP_ANL_PRODUCTION_PLAN
                                 /* WHERE QTY > 0 */
                              ) Y
                           ON ( 0 = 0
                                AND X.DIVISION_ID         = Y.DIVISION_ID          /* @p_division_id  2021.10.25 튜닝개선요청에 따른 변경 */
                                AND X.PLAN_START_YYYYMMDD = Y.PLAN_START_YYYYMMDD  /* @p_PLAN_START_YYYYMMDD */
                                AND X.PLAN_TYPE           = Y.PLAN_TYPE            /* @p_PLAN_TYPE */
                                AND X.SEQ                 = Y.SEQ                  /* @p_SEQ */
                                AND X.OPERATION_GROUP     = Y.OPERATION_GROUP
                                AND X.SCM_SITE_ID         = Y.SCM_SITE_ID
                                AND X.ITEM_ID             = Y.ITEM_ID
                                AND X.MEASURE             = Y.MEASURE
                                AND X.YYYYMMDD            = Y.YYYYMMDD
                                AND X.LINE_ID             = Y.LINE_ID
                                AND X.OPERATION_ID        = Y.OPERATION_ID
                                AND X.ORIGIN_DIVISION_ID  = Y.ORIGIN_DIVISION_ID
                                AND NVL(X.ELECTRODE_TYPE, ' ') = NVL(Y.ELECTRODE_TYPE, ' ')
                              )
                        WHEN MATCHED THEN
                        UPDATE
                           SET X.QTY               = Y.QTY
                             /* , X.CREATED_BY         = @p_USER_ID */
                             /* , X.CREATION_DATE      = GETDATE()  */
                             , X.LAST_UPDATED_BY  = V_P_USER_ID
                             , X.LAST_UPDATE_DATE = SYSDATE
                        WHEN NOT MATCHED THEN
                          INSERT ( DIVISION_ID
                                 , PLAN_START_YYYYMMDD
                                 , PLAN_TYPE
                                 , SEQ
                                 , OPERATION_GROUP
                                 , SCM_SITE_ID
                                 , ITEM_ID
                                 , LINE_ID
                                 , OPERATION_ID
                                 , MEASURE
                                 , YYYYMMDD
                                 , QTY
                                 , ORIGIN_DIVISION_ID
                                 , ELECTRODE_TYPE
                                 , CELL_QTY
                                 , CREATED_BY
                                 , CREATION_DATE
                                 , LAST_UPDATED_BY
                                 , LAST_UPDATE_DATE )
                          VALUES ( Y.DIVISION_ID
                                 , Y.PLAN_START_YYYYMMDD
                                 , Y.PLAN_TYPE
                                 , Y.SEQ
                                 , Y.OPERATION_GROUP
                                 /* , Y.CELL_ITEM_ID */
                                 , Y.SCM_SITE_ID
                                 , Y.ITEM_ID
                                 , Y.LINE_ID
                                 , Y.OPERATION_ID
                                 , Y.MEASURE
                                 , Y.YYYYMMDD
                                 , Y.QTY
                                 , Y.ORIGIN_DIVISION_ID
                                 , Y.ELECTRODE_TYPE
                                 , Y.CELL_QTY
                                 , V_P_USER_ID
                                 , SYSDATE
                                 , V_P_USER_ID
                                 , SYSDATE )
                                 ;

            /* ------------------------------------------------------------------------------------------- */
            /*  SCP_ANL_PRODUCTION_PLAN_H : History 입력 */
            /* ------------------------------------------------------------------------------------------- */
            /*  SELECT top 10 * FROM dbo.SCP_ANL_PRODUCTION_PLAN_H WITH (NOLOCK)      HISTORY_SEQ */
            /*  SET @n_history_seq = NEXT VALUE FOR SEQ1_SCP_ANL_PRODUCTION_PLAN_H */
                      INSERT INTO SCP_ANL_PRODUCTION_PLAN_H
                           ( HISTORY_SEQ
                           , DIVISION_ID
                           , PLAN_START_YYYYMMDD
                           , PLAN_TYPE
                           , SEQ
                           , OPERATION_GROUP
                           , SCM_SITE_ID
                           , ITEM_ID
                           , LINE_ID
                           , OPERATION_ID
