                           , ELECTRODE_TYPE
                           , CREATED_BY
                           , CREATION_DATE
                           , LAST_UPDATED_BY
                           , LAST_UPDATE_DATE
                           /* ,ATTRIBUTE1 ,ATTRIBUTE2 ,ATTRIBUTE3 ,ATTRIBUTE4 ,ATTRIBUTE5
                              ,ATTRIBUTE6 ,ATTRIBUTE7 ,ATTRIBUTE8 ,ATTRIBUTE9 ,ATTRIBUTE10 */
                           , HISTORY_CREATION_DATE )
                      SELECT SEQ1_SCP_ANL_PRODUCTION_PLAN_H.NEXTVAL
                           , DIVISION_ID
                           , PLAN_START_YYYYMMDD
                           , PLAN_TYPE
                           , SEQ
                           , OPERATION_GROUP
                           , SCM_SITE_ID
                           , ITEM_ID
                           , LINE_ID
                           , OPERATION_ID
                           , MEASURE
                           , YYYYMMDD
                           , QTY
                           , ORIGIN_DIVISION_ID
