                     , PLANT_SITE_ID AS SCM_SITE_ID
                     , OPERATION_ID
                     , LINE_ID
                     , YYYYMMDD
                     , WORKING_TIME
                  FROM TABLE(FN_LINE_WORKINGTIME_BY_LOSS(P_DIVISION_ID, P_CREATE_FROM_YYYYMMDD, V_P_TO_YYYYMMDD, V_LINE_ID))
                 WHERE LINE_ID = V_LINE_ID
                     ;

                /* PRINT @v_line_id */

                /*  IF OBJECT_ID('tempdb..#LineLoad') IS NOT NULL DROP TABLE #LineLoad */
