                 X_WQTY37 := TRUNC(R.WQTY37); X_WQTY38 := TRUNC(R.WQTY38); X_WQTY39 := TRUNC(R.WQTY39); X_WQTY40 := TRUNC(R.WQTY40);
                 X_WQTY41 := TRUNC(R.WQTY41); X_WQTY42 := TRUNC(R.WQTY42); X_WQTY43 := TRUNC(R.WQTY43); X_WQTY44 := TRUNC(R.WQTY44);
                 X_WQTY45 := TRUNC(R.WQTY45); X_WQTY46 := TRUNC(R.WQTY46); X_WQTY47 := TRUNC(R.WQTY47); X_WQTY48 := TRUNC(R.WQTY48);
