/*
            -----------------------------------------------------------------------------------------------------------
             FROZEN 구간 대상 DATA 생성
            -----------------------------------------------------------------------------------------------------------
            IF OBJECT_ID('tempdb..#SCM_MST_SITE') IS NOT NULL
	              DROP TABLE #SCM_MST_SITE

                  SELECT
                         S.DIVISION_ID
	                      ,S.PLANT_ID
