/*
            -----------------------------------------------------------------------------------------------------------
             SCP_XLS_PSI_GLOBAL_ELECTRODE (XLSPSI05) 화면조회용 테이블에 해당 레코드를 수정한다.
            -----------------------------------------------------------------------------------------------------------
              PROD         --> SCP_ANL_PRODUCTION_PLAN.MEASURE 'PROD_PLAN_AMEND'
			-----------------------------------------------------------------------------------------------------------
             SOURCE TABLE 반영
            -----------------------------------------------------------------------------------------------------------
*/

            /* MSSQL : SET @v_batch_user = @v_batch_user_id + '[SIMULATION]'
               CASE 로 1:1 재현하고, NVARCHAR(150) 변수 대입의 묵시 절단도 SUBSTR 로 재현한다(CV-032). */
            V_BATCH_USER := CASE WHEN V_BATCH_USER_ID IS NULL
                                 THEN NULL
                                 ELSE SUBSTR(V_BATCH_USER_ID || '[SIMULATION]', 1, 150)
                            END;   /* UI 작업자와 시물레이션 작업자를 구분하기 위해서 */

            IF V_BATCH_MEASURE IN ('PROD_PLAN_AMEND') THEN   /* 'PROD_PLAN_AMEND' SCP_XLS_PSI_GLOBAL_ELECTRODE 테이블에 저장만 처리함. */
               /* ------------------------------------------------------------------------------------------- */
               /* WEEK DATA를 DAY DATA로 반영 */
               /* 확정 구간이 주에 포함될 경우 수정금지 구간을 제외하고, 일 배분해야 함. */
               /* ------------------------------------------------------------------------------------------- */

