	 		            --WHERE A.BASIS_YYYYMMDD     >= @p_create_from_yyyymmdd
                --          AND A.BASIS_YYYYMMDD     <  CONVERT(VARCHAR(8), DATEADD(day, 364, @p_create_from_yyyymmdd), 112)		--@p_to_yyyymmdd
