              DECLARE @mPROD NVARCHAR(MAX) = '';

		          SET @mPROD = @mPROD + ' SELECT  '''+ @p_xls_key1  +''' AS XLS_KEY1  '+CHAR(10);

		          SET @mPROD = @mPROD + ' 				' + @mQry_sum2 +'									      '+CHAR(10);
