                    , PLAN_TYPE
                    , SEQ
                 FROM SCP_XLS_PSI_GLOBAL_ESS
                WHERE ROWNUM = 1
             )
    LOOP
        V_DIVISION_ID           := R.DIVISION_ID;
        V_PLAN_START_YYYYMMDD   := R.PLAN_START_YYYYMMDD;
        V_PLAN_TYPE             := R.PLAN_TYPE;
        V_SEQ                   := R.SEQ;
    END LOOP;

    IF ( P_DIVISION_ID <> V_DIVISION_ID OR P_PLAN_START_YYYYMMDD <> V_PLAN_START_YYYYMMDD
         OR P_PLAN_TYPE <> V_PLAN_TYPE OR P_SEQ <> V_SEQ ) THEN
        /* 원본 L143 : return -1. ★정상 스킵이다(화면이 보고 있던 버전이 이미 바뀐 경우 저장을 건너뛴다). */
        RETURN;
    END IF;
    /* ------------------------------------------------------------------------------------------------------------- */

    DBMS_OUTPUT.PUT_LINE(P_PLAN_TYPE);   /*  MSSQL PRINT @p_plan_type (CV-027) */
    BEGIN
      BEGIN

            /*  MSSQL CONVERT(VARCHAR(8), DATEADD(day, 364, @p_plan_start_yyyymmdd), 112). */
            V_P_TO_YYYYMMDD := TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 364, 'YYYYMMDD');

            /* ------------------------------------------------------------------------------------------- */
            /*  FROZEN 구간 대상 DATA 생성 */
            /* ------------------------------------------------------------------------------------------- */

            DELETE FROM GT_XPGT_SCM_MST_SITE;

            INSERT
              INTO GT_XPGT_SCM_MST_SITE
                 ( DIVISION_ID
                 , PLANT_ID
                 , OPERATION_GROUP
                 , SCM_SITE_ID
                 , SHIP_FROZEN
                 , SHIP_FROZEN_WEEK
                 , SHIP_FROZEN_WEEK_DAY
                 , PROD_FROZEN
                 , PROD_FROZEN_WEEK
                 , PROD_FROZEN_WEEK_DAY
                 , PROD_FROZEN_WEEK_DAY_MA
                 , FP_PLAN_PERIOD
                 , VALID_YN
                 , NEW_YN
                 , COMPANY_ID
                 , LOGISTIC_PLANT_ID
                 , PACKER_ITEM_ID_SUFFIX )
            SELECT DIVISION_ID
                 , PLANT_ID
                 , OPERATION_GROUP
                 , SCM_SITE_ID
                 , SHIP_FROZEN

                 , (TRUNC(SHIP_FROZEN / 7) + (CASE WHEN MOD(SHIP_FROZEN, 7) > 0 THEN 1 ELSE 0 END)) AS SHIP_FROZEN_WEEK
                   /*  MSSQL CONVERT(NVARCHAR(8), DATEADD(WEEK, n, @p_plan_start_yyyymmdd), 112) : 문자열이 */
                 , TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')
                           + (TRUNC(SHIP_FROZEN / 7) + (CASE WHEN MOD(SHIP_FROZEN, 7) > 0 THEN 1 ELSE 0 END)) * 7
                          , 'YYYYMMDD') AS SHIP_FROZEN_WEEK_DAY
                 , PROD_FROZEN
                 , (TRUNC(PROD_FROZEN / 7) + (CASE WHEN MOD(PROD_FROZEN, 7) > 0 THEN 1 ELSE 0 END)) AS PROD_FROZEN_WEEK
                 , TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')
                           + (TRUNC(PROD_FROZEN / 7) + (CASE WHEN MOD(PROD_FROZEN, 7) > 0 THEN 1 ELSE 0 END)) * 7
                          , 'YYYYMMDD') AS PROD_FROZEN_WEEK_DAY
                 , TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')
                           + (TRUNC((CASE WHEN ((PROD_FROZEN - 7) > 0) THEN (PROD_FROZEN - 7) ELSE 0 END) / 7)
                              + (CASE WHEN MOD((CASE WHEN ((PROD_FROZEN - 7) > 0) THEN (PROD_FROZEN - 7) ELSE 0 END), 7) > 0 THEN 1 ELSE 0 END)) * 7
                          , 'YYYYMMDD') AS PROD_FROZEN_WEEK_DAY_MA
                 , FP_PLAN_PERIOD
                 , VALID_YN
                 , NEW_YN
                 , COMPANY_ID
                 , LOGISTIC_PLANT_ID
                 , PACKER_ITEM_ID_SUFFIX
              FROM SCM_MST_SITE
             WHERE SITE_TYPE   = 'PLANT'
               AND VALID_YN    = 'Y'
               AND DIVISION_ID = P_DIVISION_ID
                 ;

            /*  Plan End Date
                DATEDIFF(DAY, p.plan_name, p.horizon_end_date) : 두 컬럼 모두 YYYYMMDD 문자열(실측)이라 */
            FOR R IN ( SELECT A.HORIZON_END_DATE
                            , (CASE WHEN TO_DATE(A.HORIZON_END_DATE, 'YYYYMMDD') - TO_DATE(A.PLAN_NAME, 'YYYYMMDD') > 364 THEN 'Y' ELSE 'N' END) AS BP_FLAG
                            , (CASE WHEN TO_DATE(A.HORIZON_END_DATE, 'YYYYMMDD') - TO_DATE(A.PLAN_NAME, 'YYYYMMDD') > 364
                                    THEN TO_DATE(A.HORIZON_END_DATE, 'YYYYMMDD') - TO_DATE(A.PLAN_NAME, 'YYYYMMDD') - 363 ELSE 0 END) AS BP_DAYS
                         FROM SCM_MST_PLAN A
                        WHERE A.PLAN_ID     = (SELECT MAX(PLAN_ID)
                                                 FROM SCM_MST_PLAN SA
                                                WHERE SA.DIVISION_ID = P_DIVISION_ID
                                                  AND SA.PLAN_ID < 9999)
                          AND A.DIVISION_ID = P_DIVISION_ID
                     )
            LOOP

                V_PET_DATE  := SUBSTR(R.HORIZON_END_DATE, 1, 12);
                V_BP_FLAG   := R.BP_FLAG;
                V_BP_DAYS   := R.BP_DAYS;
            END LOOP;


            V_P_CREATE_FROM_YYYYMMDD := SUBSTR(P_PLAN_START_YYYYMMDD, 1, 8);
            V_P_CREATE_TO_YYYYMMDD   := TO_CHAR(TO_DATE(V_P_CREATE_FROM_YYYYMMDD, 'YYYYMMDD') + 364, 'YYYYMMDD');

            /* ------------------------------------------------------------------------------------------- */
            /*  1 year 저장 프로시저 실행 */
            /* ------------------------------------------------------------------------------------------- */
            /*  원본 : EXEC @rows = PR_SCP_XLS_ADD_XLSPSI06_S @p_USER_ID = @p_user_id , ... */
            PR_SCP_XLS_ADD_XLSPSI06_S( P_USER_ID              => P_USER_ID
