                                           , P_WQTY16 => P_WQTY68 , P_WQTY17 => P_WQTY69 , P_WQTY18 => P_WQTY70 , P_WQTY19 => P_WQTY71 , P_WQTY20 => P_WQTY72
                                           , P_WQTY21 => P_WQTY73 , P_WQTY22 => P_WQTY74 , P_WQTY23 => P_WQTY75 , P_WQTY24 => P_WQTY76 , P_WQTY25 => P_WQTY77
