                         , WORKING_TIME
                         , QTY )
                    SELECT ROW_NUMBER() OVER(ORDER BY X.YYYYMMDD) AS RN
                         , V_BATCH_XLS_KEY1
                         , X.YYYYMMDD
                         , X.WORKING_TIME
                         , 0.0            AS QTY
                      FROM ( SELECT A.DIVISION_ID
                                  , A.OPERATION_ID
                                  , A.LINE_ID
                                  , C.YYYYMMDD
                                  , A.WORKING_TIME
                               FROM ( SELECT BASIS_YYYYMMDD AS YYYYMMDD, 0 AS WORKING_TIME
