                                       INNER JOIN #SCM_MST_SITE Y
                                          ON Y.DIVISION_ID = X.DIVISION_ID
                                         AND Y.SCM_SITE_ID = X.FROM_SITE
                                       WHERE
                                           X.YYYYMMDD < Y.SHIP_FROZEN_WEEK_DAY;
                               END */
