                       , WQTY31, WQTY32, WQTY33, WQTY34, WQTY35
                       , WQTY36, WQTY37, WQTY38, WQTY39, WQTY40
                       , WQTY41, WQTY42, WQTY43, WQTY44, WQTY45
                       , WQTY46, WQTY47, WQTY48, WQTY49, WQTY50
                       , WQTY51, WQTY52
