                         , Y.WQTY46, Y.WQTY47, Y.WQTY48, Y.WQTY49, Y.WQTY50
                         , Y.WQTY51, Y.WQTY52
                            FROM GT_XPGT_LINELOAD_WEEK_PIVOT Y
                           WHERE Y.PROD_LINE    = X.PROD_LINE
                             AND X.DIVISION_ID  = Y.DIVISION_ID
                             AND X.FROM_SITE    = Y.SITE_ID
                             AND X.ATTRIBUTE9   = Y.OPERATION_ID
