        /* --------------------------------------------------------- */
        /*  실행 Logic END -- */
        /* --------------------------------------------------------- */

        /*  TXN LOG */
        V_LOG_TYPE     := 'TXN';    /* 로그타입 */

        N_LOG_COUNT    := SQL%ROWCOUNT;
        V_LOG_MESSAGE  := 'INSERT INTO ' || V_TABLE_ID;
        /*  MSSQL CONVERT(CHAR(23), @d_event_date, 121) = 'YYYY-MM-DD HH:MI:SS.mmm'. */
        V_DESCRIPTION  := 'Process Complete...' || ':' || TO_CHAR(D_EVENT_DATE, 'YYYY-MM-DD HH24:MI:SS');
        D_EVENT_DATE   := SYSDATE;
        PR_SCP_SYS_LOG_BATCH( P_PROGRAM_NAME  => V_PROGRAM_NAME
                            , P_LOG_TYPE      => V_LOG_TYPE
                            , P_LOG_COUNT     => N_LOG_COUNT
                            , P_LOG_MESSAGE   => V_LOG_MESSAGE
                            , P_DESCRIPTION   => V_DESCRIPTION
                            , P_EVENT_DATE    => D_EVENT_DATE
                            , P_USER_ID       => V_BATCH_USER_ID
                            );

      END;

    EXCEPTION
      WHEN OTHERS THEN

        /*           IF @@TRANCOUNT > 0
             BEGIN
               ROLLBACK;
             END; */

        /*  ERROR LOG */
        V_LOG_TYPE     := 'ERROR';
        V_LOG_MESSAGE  := SUBSTR(SQLERRM, 1, 1000);
        /*  MSSQL N'ERROR_LINE : ' + STR(ERROR_LINE()) + '[' + @p_measure + ']' 은 Oracle 무대응 -> */
        V_DESCRIPTION  := CASE WHEN P_MEASURE IS NULL
                               THEN NULL
                               ELSE SUBSTR('ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE || '[' || P_MEASURE || ']', 1, 500)
                          END;
        D_EVENT_DATE   := SYSDATE;
        PR_SCP_SYS_LOG_BATCH( P_PROGRAM_NAME  => V_PROGRAM_NAME
                            , P_LOG_TYPE      => V_LOG_TYPE
                            , P_LOG_COUNT     => N_LOG_COUNT
                            , P_LOG_MESSAGE   => V_LOG_MESSAGE
                            , P_DESCRIPTION   => V_DESCRIPTION
                            , P_EVENT_DATE    => D_EVENT_DATE
                            , P_USER_ID       => V_BATCH_USER_ID
                            );

        /*  MSSQL 원본 L4504 : return -1  (CATCH 안 = 오류 경로) */
        O_RETURN_CODE := -1;
        RETURN;
    END;

    /*  임시 운영반영시에 주석처리 할것. */

    /*  MSSQL REPLICATE('0', 2 - LEN(x)) + x -> LPAD(x, 2, '0') (CV-067).
        ※원본은 x 가 3자리 이상이면 REPLICATE 인자가 음수가 되어 NULL 을 돌려주지만 LPAD 는 앞자리를 자른다. */
    V_EXEC_TIME  :=  LPAD(TO_CHAR(TRUNC(ROUND((SYSDATE - V_START_TIME) * 86400) / 60)), 2, '0') || ':' ||
                     LPAD(TO_CHAR(MOD(ROUND((SYSDATE - V_START_TIME) * 86400), 60)), 2, '0');

    /*  종료 LOG */
    V_LOG_TYPE     := 'END';
    V_LOG_MESSAGE  := '########## END of procedure ##########';

    V_DESCRIPTION  := CASE WHEN P_DIVISION_ID IS NULL OR P_CREATE_FROM_YYYYMMDD IS NULL
                             OR P_MEASURE IS NULL OR V_BATCH_XLS_KEY1 IS NULL OR V_EXEC_TIME IS NULL
                           THEN NULL
                           ELSE '[' || P_DIVISION_ID || '][' || P_CREATE_FROM_YYYYMMDD || '][' || P_MEASURE
                                || '][' || LPAD(TO_CHAR(V_BATCH_XLS_KEY1), 10) || '][' || V_EXEC_TIME || ']'
                      END;
    D_EVENT_DATE   := SYSDATE;
    PR_SCP_SYS_LOG_BATCH( P_PROGRAM_NAME  => V_PROGRAM_NAME
                        , P_LOG_TYPE      => V_LOG_TYPE
                        , P_LOG_COUNT     => N_LOG_COUNT
                        , P_LOG_MESSAGE   => V_LOG_MESSAGE
                        , P_DESCRIPTION   => V_DESCRIPTION
                        , P_EVENT_DATE    => D_EVENT_DATE
                        , P_USER_ID       => V_BATCH_USER_ID
                        );
    /*  MSSQL 원본 L4526 : return 1  (정상 종료) */
    O_RETURN_CODE := 1;
    RETURN;

END;

PROCEDURE PR_SCP_XLS_EXCEL_BODY_XLSPSI02
(
    P_DIVISION_ID     IN  VARCHAR2
  , P_PGM_CODE        IN  VARCHAR2
  , P_PARAMETER1      IN  VARCHAR2  DEFAULT ''      /* researved */
  , P_PARAMETER2      IN  VARCHAR2  DEFAULT ''      /* researved */
  , P_PARAMETER3      IN  VARCHAR2  DEFAULT ''      /*  CELL_ITEM_ID LIST,  Delimeter는 (,) */
  , P_PARAMETER4      IN  VARCHAR2  DEFAULT ''      /* RESEARVED */
  , P_PARAMETER5      IN  VARCHAR2  DEFAULT ''      /*  DAY 구간의 ENDDATE (YYYYMMDD) */
  , P_IS_DEBUG        IN  NUMBER    DEFAULT 0
  , O_RESULT_CURSOR   OUT SYS_REFCURSOR
)
/*
 * Program ID   : [PR_SCP_XLS_EXCEL_BODY_XLSPSI02]
 * Description  : SCP SIMULATION EXCEL SHEET BODY QUERY
 * OutTable     :
 * Execute      :

  EXEC PR_SCP_XLS_EXCEL_BODY_XLSPSI02 @p_division_id   = '40'
                                                  ,@p_pgm_code      = 'XLSPSI02'
                                                  ,@p_parameter1    = ''
                                                  ,@p_parameter2    = ''
                                                  ,@p_parameter3    = 'MCCH125020A1'
                                                  ,@p_parameter4    = ''
                                                  ,@p_parameter5    ='20250303'


 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
  * 2019.01.07   YYDOK         Initial Release PJ20170278 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 *              KSG           과거 이력 정리
 * 2022.02.21   KSW			  DC link 적용
 * 2022.02.22   KSW           소형 Shipment plan 시뮬레이터 조회기능개선
 * 2022.04.07   KSW           소형 Shipment plan 시뮬레이터 조회기능개선2
 * 2022.05.02   KSW           Daily & Monthly Bucket 개선적용
 * 2022.05.13   KSW			  GM JV 반영
 * 2022.05.23   KSW			  ESS Pack 시뮬레이터 가동율시트 - Cell Total measure 추가
 * 2022.06.22   KSW			  소형 Shipment plan 시뮬레이터 From Site 컬럼추가
 * 2022.07.18   KSW			  PJ20216994 / LGES Digital SCM 3 Level 가속화를 위한 개선 Phase 2 :: ISUZU 적용
 * 2022.08.11   KSW           중장기 +1 Year 변경처리
 * 2022.08.30   KSW			  자동차 Cell 재고 개선건
 * 2022.09.21	KSW			  소형SCM개선요청사항 적용
 * 2022.09.30	KSW			  자동차 Load Ratio 조회안되게 변경
 * 2022.12.22   KSW			  XLSPSI21 소형 출하 시뮬레이터 - DEPT_NAME_EN 식별문제로 DEPT_ID 를 붙여서 식별하는 것으로 변경 :: 2022.12.22
 * 2023.02.09   KKH			  XLSPSI01 pack cell 순서로 다시 정렬
 * 2023.03.09   KKH			 소형 ISUZU 모델 제외 ( Flow Id  ‘P5500’ 또는 ‘P9500’ 인 Item 만 제외)
 * 2023.07.10   DHJ			  소형 출하시뮬레이터 INVENTORY, PROD_PLAN_ENGINE에 값을 가져올떄 CA모델 수량 합산 AS-IS : ONLY CP QTY, TO-BE : CP + CA QTY
 * 2023.07.25   DHJ			FIXED FOR BUG --* 2023.07.10   1298
 * 2023.08.04   KSK			PJ20230692  SCM 역량 강화 위한 SCP 개선과제 이행 Phase.2 (사업계획 수립에 따른 시뮬레이터 생산계획Bucket 확장 적용)
 * 2023.10.06   KHJ			확정구간의 기준을 LOOKUP 테이블을 우선참조하도록 함
 * 2023.10.12   KHJ			ESS-PACK(XLSPSI06). SHIP_REQ가 없는 것에 대해서 조회되지 않도록 기능개선.
 * 2023.12.01   KHJ			소형출하계획 (XLSPSI21). FROM_SITE별 출하계획 조회/할당/저장
 * 2023.12.15   OIJ			QUERY 정리(HAVING 삭제, JOIN 수정, IN구문 JOIN구문으로 일부변경)
 * 2023.12.29   KHJ			공용 Cell의 경우 BOH 로직 개선
 * 2024.03.22   KSK			ESS PROD LOAD조회 관련  SCP_XLS_PSI_GLOBAL_ESS_LOAD_RATIO_PACK_V와 SCP_XLS_PSI_GLOBAL_ESS_LOAD_RATIO_PACK_BP_V를
									    FN_XLS_PSI_GLOBAL_ESS_LOAD_RATIO_PACK으로 통합처리
 * 2024.09.25   KSK			팩셀관련메저의 정렬순서 보정(PACK/PACK-CELL/기타순서의 가중치 변경 10000,10010,10020=> 1, 10000, 10000000)

 * 2024.11.11   KSK         PR_SCP_XLS_EXCEL_BODY_QUERY 에서 소형팩 조회부분을 분리함
 * 2025.03.05   KSK         SHIP_REQ를 SHIP_PLAN 바로 위에 배치
 * 2025.03.06   KSK         성능개선위해 FN_SplitString를 시스템함수 String_Split로  대체
 * 2026.08.03   ZIONEX   [PJ202650304]  NextSCM Migration
*/
IS

    V_PLAN_START_YYYYMMDD    VARCHAR2(0008 CHAR) := NULL;
    V_PLAN_TYPE              VARCHAR2(4000 CHAR) := 'MA';
    V_SEQ                    VARCHAR2(0008 CHAR) := NULL;
    V_CREATE_TO_YYYYMMDD     VARCHAR2(0008 CHAR);
    V_CREATE_FROM_YYYYMMD2   VARCHAR2(0008 CHAR) := NULL;    /*  NVARCHAR(0008) 2차년도 구간시작일 */
    V_CREATE_TO_YYYYMMDD2    VARCHAR2(0008 CHAR) := NULL;
    V_SQL                    CLOB;


    /*   Plan End Date */
    V_BP_FLAG                VARCHAR2(0008 CHAR) := '';
    V_BP_DAYS                NUMBER(10)          := 0;       /*  INT */
    V_BP_PLAN_END_YYYYMMDD   VARCHAR2(0008 CHAR) := '';

    V_DAYEND_YYYYMMDD        VARCHAR2(0020 CHAR) := P_PARAMETER5;
    V_DAY_COLS               VARCHAR2(4000 CHAR) := '';
    V_DAY_COLS_N             VARCHAR2(32767 CHAR) := '';
    V_DAY_COLS_O             VARCHAR2(32767 CHAR) := '';

    /*  Dayily End 일자를 월 말일로 조정한다. */
    V_DAILY_LAST_YYYYMMDD    VARCHAR2(0008 CHAR) := '';

    /*  DECLARE @v_tbl_month TABLE (DAY_NUM INT, YYYYMMDD NVARCHAR(8), C_YEAR INT, C_MONTH INT) */


    TYPE T_TBL_MONTH_REC IS RECORD ( DAY_NUM  NUMBER(10)
                                   , YYYYMMDD VARCHAR2(0008 CHAR)
                                   , C_YEAR   NUMBER(10)
                                   , C_MONTH  NUMBER(10) );
    TYPE T_TBL_MONTH_TAB IS TABLE OF T_TBL_MONTH_REC;
    V_TBL_MONTH              T_TBL_MONTH_TAB := T_TBL_MONTH_TAB();

    /*  SELECT DISTINCT C_YEAR, C_MONTH 의 중복제거용 키셋(원본 DISTINCT 를 컬렉션에서 재현) */
    TYPE T_YM_SET IS TABLE OF PLS_INTEGER INDEX BY VARCHAR2(0064 CHAR);
    V_YM_SET                 T_YM_SET;
    V_YM_KEY                 VARCHAR2(0064 CHAR);
    V_I                      PLS_INTEGER;

    V_TBL_CNT                NUMBER(10)          := 0;       /*  INT */
    V_LP                     NUMBER(10)          := 0;       /*  INT */
    V_LP_2                   NUMBER(10)          := 0;       /*  INT */
    V_MONTH_TMP              VARCHAR2(32767 CHAR) := '';
    V_MONTH_COLS             VARCHAR2(32767 CHAR) := '';
    V_CURR_YEAR              NUMBER(10)          := 0;       /*  INT */
    V_CURR_MONTH             NUMBER(10)          := 0;       /*  INT */
    V_MONTH_TMP_2            VARCHAR2(32767 CHAR) := '';
    V_MONTH_COLS_2           VARCHAR2(32767 CHAR) := '';
    V_MONTH_COLS_O           VARCHAR2(32767 CHAR) := '';
    V_MONTH_COLS_N           VARCHAR2(32767 CHAR) := '';
    V_NEW_MONTH_COLS         VARCHAR2(32767 CHAR) := '';
    V_CURR_YEAR_2            NUMBER(10)          := 0;       /*  INT */
    V_CURR_MONTH_2           NUMBER(10)          := 0;       /*  INT */

BEGIN

/* ------- 계획관련 변수 초기화 시작 ----------------------------- */
    /*  SELECT @v_bp_flag = .., @v_bp_days = .. FROM scm_mst_plan (집계 없는 대입형 SELECT = 다행 가능) */
    /*   → 커서 FOR 루프(0행이면 초기값 유지, N행이면 마지막 행). 26ai/MSSQL 실측 = division 당 1행. */

    FOR R IN
    (
    SELECT (CASE WHEN TO_DATE(P.HORIZON_END_DATE, 'YYYYMMDD') - TO_DATE(P.PLAN_NAME, 'YYYYMMDD') > 364 THEN 'Y'
                 ELSE 'N'
            END) AS BP_FLAG
         , (CASE WHEN TO_DATE(P.HORIZON_END_DATE, 'YYYYMMDD') - TO_DATE(P.PLAN_NAME, 'YYYYMMDD') > 364 THEN TO_DATE(P.HORIZON_END_DATE, 'YYYYMMDD') - TO_DATE(P.PLAN_NAME, 'YYYYMMDD') - 363
                 ELSE 0
            END) AS BP_DAYS
      FROM SCM_MST_PLAN P
     WHERE P.DIVISION_ID = P_DIVISION_ID
       /* 최근의 플랜정보 조회시 상세정보가 유효한 것을 조건으로 수정함(KSK, 2024/11/11) */
       AND P.PLAN_ID = (SELECT MAX(A.PLAN_ID)
                          FROM SCM_MST_PLAN        A
                             , SCM_MST_PLAN_DETAIL B
                         WHERE A.DIVISION_ID = B.DIVISION_ID
                           AND A.PLAN_ID     = B.PLAN_ID
                           AND A.DIVISION_ID = P_DIVISION_ID
                           AND A.PLAN_ID     < 9999)
    ) LOOP
        V_BP_FLAG := R.BP_FLAG;
        V_BP_DAYS := R.BP_DAYS;
    END LOOP;

      /*  2022.03.24 KSW Daily & Monthly Bucket 개선적용 */
    /*  SELECT TOP 1 @v = MAX(..) : 집계라 항상 1행 → SELECT INTO 로 1:1(TOP 1 은 잉여) */
    SELECT MAX(PLAN_START_YYYYMMDD)
      INTO V_PLAN_START_YYYYMMDD
      FROM SCP_XLS_PSI_GLOBAL_SMALL_PACK;

        /*  1차년도 구간종료일 */
        V_CREATE_TO_YYYYMMDD := TO_CHAR(TO_DATE((V_PLAN_START_YYYYMMDD), 'YYYYMMDD') + 363, 'YYYYMMDD') ;
        /*  2차년도 구간시작일 */
        V_CREATE_FROM_YYYYMMD2 := FN_XLS_DATE(V_PLAN_START_YYYYMMDD, 364);
        /*  2차년도 구간종료일 */
        V_CREATE_TO_YYYYMMDD2 := TO_CHAR(TO_DATE((V_CREATE_FROM_YYYYMMD2), 'YYYYMMDD') + 363, 'YYYYMMDD') ;

        /*  원본: IF @p_is_debug = 1 select @v_plan_start_yyyymmdd as "@v_plan_start_yyyymmdd" , @v_create_to_yyyymmdd AS "@v_create_to_yyyymmdd" */


        IF P_IS_DEBUG = 1 THEN
            DBMS_OUTPUT.PUT_LINE('@v_plan_start_yyyymmdd=' || V_PLAN_START_YYYYMMDD
                              || ' @v_create_to_yyyymmdd=' || V_CREATE_TO_YYYYMMDD
                              || ' @v_create_from_yyyymmd2=' || V_CREATE_FROM_YYYYMMD2
                              || ' @v_create_to_yyyymmdd2=' || V_CREATE_TO_YYYYMMDD2);
        END IF;

        /*  SELECT TOP 1 .. ORDER BY : 인라인뷰 ORDER 후 ROWNUM = 1(CV-026). */

        FOR R IN
        (
        SELECT PLAN_TYPE
             , SEQ
          FROM (SELECT PLAN_TYPE
                     , SEQ
                  FROM SCP_XLS_PSI_GLOBAL_SMALL_PACK
                 WHERE PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
                 ORDER BY CREATION_DATE DESC)
         WHERE ROWNUM = 1
        ) LOOP
            V_PLAN_TYPE := R.PLAN_TYPE;
            V_SEQ       := R.SEQ;
        END LOOP;

/* ------- 계획관련 변수 초기화 완료 ----------------------------- */

        /*  지정된 일자의 월말 구하기 */

        /*   @p_parameter5 가 NULL 이면 As-Is 는 @v_daily_last_yyyymmdd = NULL 이므로 CASE 가드로 1:1 재현(CV-032). */
        V_DAILY_LAST_YYYYMMDD := TO_CHAR(TO_DATE((CASE WHEN SUBSTR(V_DAYEND_YYYYMMDD, 1, 6) IS NULL THEN NULL ELSE SUBSTR(V_DAYEND_YYYYMMDD, 1, 6) || '01' END), 'YYYYMMDD') + 31, 'YYYYMMDD');
        V_DAILY_LAST_YYYYMMDD := TO_CHAR(TO_DATE((CASE WHEN SUBSTR(V_DAILY_LAST_YYYYMMDD, 1, 6) IS NULL THEN NULL ELSE SUBSTR(V_DAILY_LAST_YYYYMMDD, 1, 6) || '01' END), 'YYYYMMDD') - 1, 'YYYYMMDD');
        /*  원본: IF @P_IS_DEBUG = 1 SELECT @v_daily_last_yyyymmdd AS "지정일자의 말일"  → DBMS_OUTPUT(H-9) */
        IF P_IS_DEBUG = 1 THEN
            DBMS_OUTPUT.PUT_LINE('지정일자의 말일=' || V_DAILY_LAST_YYYYMMDD);
        END IF;

/* ----- 1차년도 Daily 컬럼--------------------------------------------------------------------------------------------------------------------- */
        /*  SELECT @v = @v + .. FROM (..) : 행별 문자열 누적(T-SQL 관용구) → 커서 FOR 루프 누적(EP-013). */


        FOR R IN
        (
        SELECT X.R_NUM
          FROM (SELECT ROW_NUMBER() OVER(ORDER BY C.BASIS_YYYYMMDD ASC) AS R_NUM
                     , C.BASIS_YYYYMMDD AS E_YYYYMMDD
                  FROM SCM_SYS_CALENDAR_M C
                 WHERE C.BASIS_YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_CREATE_TO_YYYYMMDD) X
        ) LOOP
            V_DAY_COLS   := V_DAY_COLS   || 'QTY' || SUBSTR('00' || TO_CHAR(R.R_NUM), -3) || ', ';
            V_DAY_COLS_N := V_DAY_COLS_N || 'BB.QTY' || SUBSTR('00' || TO_CHAR(R.R_NUM), -3) || ' AS ' || 'QTY' || SUBSTR('00' || TO_CHAR(R.R_NUM), -3) || 'N, ';
            V_DAY_COLS_O := V_DAY_COLS_O || 'AA.QTY' || SUBSTR('00' || TO_CHAR(R.R_NUM), -3) || ' AS ' || 'QTY' || SUBSTR('00' || TO_CHAR(R.R_NUM), -3) || 'O, ';
        END LOOP;

        /*  원본: IF @P_IS_DEBUG = 1  SELECT @v_day_cols "@v_day_cols", @v_day_cols_N "@v_day_cols_N", @v_day_cols_O "@v_day_cols_O"  → DBMS_OUTPUT(H-9) */
        IF P_IS_DEBUG = 1 THEN
            DBMS_OUTPUT.PUT_LINE('@v_day_cols=' || V_DAY_COLS);
            DBMS_OUTPUT.PUT_LINE('@v_day_cols_N=' || V_DAY_COLS_N);
            DBMS_OUTPUT.PUT_LINE('@v_day_cols_O=' || V_DAY_COLS_O);
        END IF;


/* ----- Monthly 컬럼--------------------------------------------------------------------------------------------------------------------- */

        IF V_BP_FLAG = 'N' THEN

            /*  INSERT @v_tbl_month SELECT * FROM (..) X WHERE .. → 컬렉션 BULK COLLECT. */
            /*   SELECT * 의 위치대응: DAY_NUM←R_NUM, YYYYMMDD←E_YYYYMMDD, C_YEAR←C_YEAR, C_MONTH←C_MONTH */

            SELECT X.R_NUM
                 , X.E_YYYYMMDD
                 , X.C_YEAR
                 , X.C_MONTH
              BULK COLLECT INTO V_TBL_MONTH
              FROM (SELECT ROW_NUMBER() OVER(ORDER BY C.BASIS_YYYYMMDD ASC) AS R_NUM
                         , C.BASIS_YYYYMMDD AS E_YYYYMMDD
                         , TO_NUMBER(C.CALENDAR_YYYY) AS C_YEAR
                         , TO_NUMBER(C.CALENDAR_MONTH) AS C_MONTH
                      FROM SCM_SYS_CALENDAR_M C
                     WHERE C.BASIS_YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_CREATE_TO_YYYYMMDD) X
             WHERE X.E_YYYYMMDD > V_DAILY_LAST_YYYYMMDD  /* ------------다음달 1일 부터 364일 후 까지... */
            ;

            /*  SELECT @v_tbl_cnt = COUNT(*) FROM (SELECT DISTINCT C_YEAR, C_MONTH FROM @v_tbl_month WHERE ..) X */
            V_YM_SET.DELETE;
            V_TBL_CNT := 0;
            FOR V_I IN 1 .. V_TBL_MONTH.COUNT LOOP
                IF V_TBL_MONTH(V_I).YYYYMMDD <= V_CREATE_TO_YYYYMMDD THEN
                    V_YM_KEY := TO_CHAR(V_TBL_MONTH(V_I).C_YEAR) || '|' || TO_CHAR(V_TBL_MONTH(V_I).C_MONTH);
                    IF NOT V_YM_SET.EXISTS(V_YM_KEY) THEN
                        V_YM_SET(V_YM_KEY) := 1;
                        V_TBL_CNT := V_TBL_CNT + 1;
                    END IF;
                END IF;
            END LOOP;

            /*  SELECT TOP 1 @v_curr_year = C_YEAR, @v_curr_month = C_MONTH FROM @v_tbl_month WHERE .. */

            FOR V_I IN 1 .. V_TBL_MONTH.COUNT LOOP
                IF V_TBL_MONTH(V_I).YYYYMMDD <= V_CREATE_TO_YYYYMMDD THEN
                    V_CURR_YEAR  := V_TBL_MONTH(V_I).C_YEAR;
                    V_CURR_MONTH := V_TBL_MONTH(V_I).C_MONTH;
                    EXIT;
                END IF;
            END LOOP;

            WHILE (V_LP < V_TBL_CNT) LOOP
                V_MONTH_TMP := '';

                FOR V_I IN 1 .. V_TBL_MONTH.COUNT LOOP
                    IF V_TBL_MONTH(V_I).C_YEAR  = V_CURR_YEAR
                       AND V_TBL_MONTH(V_I).C_MONTH = V_CURR_MONTH THEN
                        V_MONTH_TMP := V_MONTH_TMP || 'QTY' || SUBSTR('00' || TO_CHAR(V_TBL_MONTH(V_I).DAY_NUM), -3) || '+';
                    END IF;
                END LOOP;

                V_MONTH_COLS := V_MONTH_COLS || '(' || SUBSTR(V_MONTH_TMP, 1, LENGTH(V_MONTH_TMP) - 1) || ') AS MQTY' || SUBSTR('0' || TO_CHAR(V_CURR_MONTH), -2) || ',';

                V_CURR_MONTH := V_CURR_MONTH + 1;

                IF (V_CURR_MONTH = 13) THEN
                    V_CURR_MONTH := 1;
