         , 0                  AS BEF_M5
         , 0                  AS BEF_M4
         , 0                  AS BEF_M3
         , 0                  AS BEF_M2
         , 0                  AS BEF_M1
         , 0                  AS BEF_M6_RESULT
         , 0                  AS BEF_M5_RESULT
         , 0                  AS BEF_M4_RESULT
         , 0                  AS BEF_M3_RESULT
         , 0                  AS BEF_M2_RESULT
         , 0                  AS BEF_M1_RESULT
