         , 0                  AS BEF_M6_RESULT
         , 0                  AS BEF_M5_RESULT
         , 0                  AS BEF_M4_RESULT
         , 0                  AS BEF_M3_RESULT
         , 0                  AS BEF_M2_RESULT
