                            FROM SCP_XLS_PSI_GLOBAL_ESS
                           WHERE MEASURE IN ('PACK_PROD_LOAD')
                             AND CREATE_FROM_YYYYMMDD = P_CREATE_FROM_YYYYMMDD )
                       WHERE RN > 1 )
