     WHERE X.CREATE_FROM_YYYYMMDD = P_CREATE_FROM_YYYYMMDD
       AND X.MEASURE IN ('PACK_PROD_LOAD_TOTAL')
       AND NOT EXISTS ( SELECT 1 FROM SCP_XLS_PSI_GLOBAL_ESS A
