PROCEDURE PR_SNAPSHOT_BATCH_TARGET_TABLES
IS
    V_SNAPSHOT_DTM   DATE         := SYSDATE;                                          /* 이번 회차 시각 */
    V_PREV_MON       VARCHAR2(8)  := TO_CHAR(TRUNC(SYSDATE, 'IW') - 7, 'YYYYMMDD');   /* 전주 월요일 */
    V_THIS_MON       VARCHAR2(8)  := TO_CHAR(TRUNC(SYSDATE, 'IW'), 'YYYYMMDD');       /* 당주 월요일 */
    V_KEEP_HOURS     NUMBER       := 168;                                              /* 보관 시간(7일) */
BEGIN
    /* 환율 : 전체 */
    INSERT
      INTO DM_MST_EXCHANGE_RATE_SNAPSHOT
    SELECT V_SNAPSHOT_DTM
         , DM_MST_EXCHANGE_RATE.*
      FROM DM_MST_EXCHANGE_RATE;

    /* 확정 수요계획 : 전주 월요일 이후 + 금액 measure 전 기간 */
    INSERT
      INTO DM_PLN_CFM_MKT_DEMAND_PLAN_SNAPSHOT
    SELECT V_SNAPSHOT_DTM
         , DM_PLN_CFM_MKT_DEMAND_PLAN.*
      FROM DM_PLN_CFM_MKT_DEMAND_PLAN
     WHERE (   YYYYMMDD >= V_PREV_MON
            OR MEASURE IN ('MKT_AMT_KRW', 'MKT_AMT_LOC'));

    /* MKT FCST : 전주 월요일 이후 + 81·81_UC EDI 원본 measure 전 기간 */
    INSERT
      INTO DM_PLN_MKT_FCST_SNAPSHOT
    SELECT V_SNAPSHOT_DTM
         , DM_PLN_MKT_FCST.*
      FROM DM_PLN_MKT_FCST
     WHERE (   YYYYMMDD >= V_PREV_MON
            OR (    DIVISION_ID IN ('81', '81_UC')
                AND MEASURE IN ('Backorder[Org.]', 'CUST_FCST_EDI_ORG', 'Commercial_Agreement[Org.]', 'Firm_Temp[Org.]'
                              , 'Immidiate[Org.]', 'Manumacturing_Material_Temp[Org.]', 'Material_Temp[Org.]', 'Planning_Forecast[Org.]')));

    /* 판매 기타 계획 : 전체 */
    INSERT
      INTO DM_PLN_SALES_ETC_PLAN_SNAPSHOT
    SELECT V_SNAPSHOT_DTM
         , DM_PLN_SALES_ETC_PLAN.*
      FROM DM_PLN_SALES_ETC_PLAN;

    /* 판매계획 : 당주 월요일 이후 */
    INSERT
      INTO DM_PLN_SALES_PLAN_SNAPSHOT
    SELECT V_SNAPSHOT_DTM
         , DM_PLN_SALES_PLAN.*
      FROM DM_PLN_SALES_PLAN
     WHERE YYYYMMDD >= V_THIS_MON;

    /* 확정 판가 : 전주 월요일 이후 */
    INSERT
      INTO DM_PLN_CFM_SELLING_PRICE_SNAPSHOT
    SELECT V_SNAPSHOT_DTM
         , DM_PLN_CFM_SELLING_PRICE.*
      FROM DM_PLN_CFM_SELLING_PRICE
     WHERE YYYYMMDD >= V_PREV_MON;

    /* 미래 판가 : 전주 월요일 이후 */
    INSERT
      INTO SCM_MST_FUTURE_PRICE_SNAPSHOT
    SELECT V_SNAPSHOT_DTM
         , SCM_MST_FUTURE_PRICE.*
      FROM SCM_MST_FUTURE_PRICE
     WHERE YYYYMMDD >= V_PREV_MON;

    /* 보관 시간 지난 회차 삭제 */
    DELETE
      FROM DM_MST_EXCHANGE_RATE_SNAPSHOT
     WHERE SNAPSHOT_DTM < V_SNAPSHOT_DTM - V_KEEP_HOURS / 24;

    DELETE
      FROM DM_PLN_CFM_MKT_DEMAND_PLAN_SNAPSHOT
     WHERE SNAPSHOT_DTM < V_SNAPSHOT_DTM - V_KEEP_HOURS / 24;

    DELETE
      FROM DM_PLN_MKT_FCST_SNAPSHOT
     WHERE SNAPSHOT_DTM < V_SNAPSHOT_DTM - V_KEEP_HOURS / 24;

    DELETE
      FROM DM_PLN_SALES_ETC_PLAN_SNAPSHOT
     WHERE SNAPSHOT_DTM < V_SNAPSHOT_DTM - V_KEEP_HOURS / 24;

    DELETE
      FROM DM_PLN_SALES_PLAN_SNAPSHOT
     WHERE SNAPSHOT_DTM < V_SNAPSHOT_DTM - V_KEEP_HOURS / 24;

    DELETE
      FROM DM_PLN_CFM_SELLING_PRICE_SNAPSHOT
     WHERE SNAPSHOT_DTM < V_SNAPSHOT_DTM - V_KEEP_HOURS / 24;

    DELETE
      FROM SCM_MST_FUTURE_PRICE_SNAPSHOT
     WHERE SNAPSHOT_DTM < V_SNAPSHOT_DTM - V_KEEP_HOURS / 24;

    COMMIT;
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        RAISE;
END PR_SNAPSHOT_BATCH_TARGET_TABLES;

PROCEDURE           "PR_SSP_ANL_ESS_REQ_NET" 

(
      P_DM_REQ_NO    IN VARCHAR2
    , P_DIVISION_ID  IN VARCHAR2
