    V_LOG_TYPE        VARCHAR2(30 CHAR);
    N_LOG_COUNT       INTEGER := 0;
    V_LOG_MESSAGE     VARCHAR2(1000 CHAR);
    V_DESCRIPTION     VARCHAR2(500 CHAR); /* 상세설명 */
    V_TABLE_ID        VARCHAR2(150 CHAR) := 'SSP_ANL_ESS_REQ_NET'; /* 테이블 필수 */
    D_EVENT_DATE      TIMESTAMP;
    V_INSERT_CNT      INTEGER := 0;
    V_INSERT_SUM      INTEGER := 0;
    V_IN_PARA_DATA    VARCHAR2(2000 CHAR);


    V_PLAN_START_YYYYMMDD VARCHAR2(8 CHAR);
    V_DIVISION_ID         VARCHAR2(10 CHAR);
    V_DM_REQ_NO           VARCHAR2(60 CHAR);
    V_STORAGE_ID          VARCHAR2(10 CHAR) := FN_GET_LOOKUP_VALUE('PR_SSP_ANL_ESS_REQ_NET', 'STORAGE_6006');

    INX                   INTEGER := 0;
    MAX_NUM               INTEGER := 0;

    L_PLAN_START_YYYYMMDD   VARCHAR2(8 CHAR);
    L_DIVISION_ID           VARCHAR2(10 CHAR);
    L_DM_REQ_NO             VARCHAR2(60 CHAR);
    L_ITEM_ID               VARCHAR2(50 CHAR);
    L_PLAN_QTY              NUMBER(20, 10);
    L_INV_QTY               NUMBER(20, 10);
    L_REMAIN_QTY            NUMBER(20, 10);
    L_INV_ALLO_QTY          NUMBER(20, 10);

BEGIN


    DELETE
      FROM GT_PRSSP_ANL_ESS_REQ_NET;

    V_IN_PARA_DATA := JSON_OBJECT('p_dm_req_no' VALUE P_DM_REQ_NO, 'p_division_id' VALUE P_DIVISION_ID);

    IF P_DIVISION_ID IS NULL THEN
        V_DIVISION_ID := '82';
    ELSE
        V_DIVISION_ID := P_DIVISION_ID;
    END IF;


    SELECT X.ATTRIBUTE1
      INTO V_PLAN_START_YYYYMMDD
      FROM SCM_ADM_LOOKUP_MASTER_DETAIL X
     WHERE X.LOOKUP_TYPE = 'SSP_ANL_ESS_PLAN'
       AND X.SEGMENT1    = V_DIVISION_ID
       AND X.VALID_YN    = 'Y';

    V_DM_REQ_NO := P_DM_REQ_NO;


    INSERT
      INTO GT_PRSSP_ANL_ESS_REQ_NET
         ( TID
         , PLAN_START_YYYYMMDD
         , DIVISION_ID
         , DM_REQ_NO
         , ITEM_ID
         , PLAN_QTY
         , INV_QTY
         , REMAIN_QTY )
    SELECT ROW_NUMBER() OVER (ORDER BY R.DIVISION_ID, R.DM_REQ_NO, R.ITEM_ID) AS TID
         , V_PLAN_START_YYYYMMDD
         , R.DIVISION_ID
         , R.DM_REQ_NO
         , R.ITEM_ID
         , R.PLAN_QTY
         , NVL(S.INV_QTY, 0)    AS INV_QTY
         , NVL(S.REMAIN_QTY, 0) AS REMAIN_QTY
      FROM SSP_ANL_ESS_REQ   R
         , SSP_ANL_ESS_STOCK S
     WHERE R.DIVISION_ID            = S.DIVISION_ID(+)
       AND R.ITEM_ID                = S.ITEM_ID(+)
       AND S.PLAN_START_YYYYMMDD(+) = V_PLAN_START_YYYYMMDD
       AND S.STORAGE_ID(+)          = V_STORAGE_ID
       AND R.DM_REQ_NO              = V_DM_REQ_NO
     ORDER BY R.DIVISION_ID
            , R.DM_REQ_NO
            , R.ITEM_ID;

    SELECT 1
         , COUNT(*)
      INTO INX
         , MAX_NUM
      FROM GT_PRSSP_ANL_ESS_REQ_NET;

    IF MAX_NUM = 0 THEN
        RETURN;
    END IF;

    /* ------------------------------------------------------------------------- */
    /* START LOG */
    /* ------------------------------------------------------------------------- */
    V_LOG_TYPE := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := V_PROGRAM_NAME||': ' ||V_TABLE_ID||' INSERT LOGIC';
    D_EVENT_DATE := SYSTIMESTAMP;

    PR_DM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER);

    WHILE INX <= MAX_NUM
    LOOP
        BEGIN

            SELECT PLAN_START_YYYYMMDD
                 , DIVISION_ID
                 , DM_REQ_NO
                 , ITEM_ID
                 , PLAN_QTY
                 , INV_QTY
                 , REMAIN_QTY
              INTO L_PLAN_START_YYYYMMDD
                 , L_DIVISION_ID
                 , L_DM_REQ_NO
                 , L_ITEM_ID
                 , L_PLAN_QTY
                 , L_INV_QTY
                 , L_REMAIN_QTY
              FROM GT_PRSSP_ANL_ESS_REQ_NET
             WHERE TID = INX;

            IF L_REMAIN_QTY >= L_PLAN_QTY THEN
                L_INV_ALLO_QTY := CASE WHEN (L_REMAIN_QTY - L_PLAN_QTY) > L_INV_QTY THEN L_REMAIN_QTY - L_INV_QTY ELSE L_PLAN_QTY END;
                L_REMAIN_QTY := L_REMAIN_QTY - L_INV_ALLO_QTY;
            ELSE
                L_INV_ALLO_QTY := L_REMAIN_QTY;
                L_REMAIN_QTY := 0;
            END IF;

            INSERT
              INTO SSP_ANL_ESS_REQ_NET
                 ( PLAN_START_YYYYMMDD
                 , DIVISION_ID
                 , DM_REQ_NO
                 , ITEM_ID
                 , PLAN_QTY
                 , INV_ALLO_QTY
                 , CREATED_BY
                 , CREATION_DATE
                 , LAST_UPDATED_BY
                 , LAST_UPDATE_DATE )
            VALUES ( L_PLAN_START_YYYYMMDD
                   , L_DIVISION_ID
                   , L_DM_REQ_NO
                   , L_ITEM_ID
                   , L_PLAN_QTY
                   , L_INV_ALLO_QTY
                   , V_BATCH_USER
                   , SYSDATE
                   , V_BATCH_USER
                   , SYSDATE );

            UPDATE SSP_ANL_ESS_STOCK
               SET REMAIN_QTY            = L_REMAIN_QTY
             WHERE PLAN_START_YYYYMMDD   = L_PLAN_START_YYYYMMDD
               AND DIVISION_ID           = L_DIVISION_ID
               AND ITEM_ID               = L_ITEM_ID
               AND STORAGE_ID            = V_STORAGE_ID;

            UPDATE SSP_ANL_ESS_REQ
               SET NET_YN     = 'Y'
             WHERE DM_REQ_NO  = L_DM_REQ_NO
               AND ITEM_ID    = L_ITEM_ID;

            V_INSERT_CNT := SQL%ROWCOUNT;
            V_INSERT_SUM := V_INSERT_SUM + V_INSERT_CNT;

            EXCEPTION WHEN OTHERS THEN
                /* --------------------------------------------------------- */
                /* ERROR LOG */
                /* --------------------------------------------------------- */
                V_LOG_TYPE := 'ERROR';
                V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);


                V_DESCRIPTION := 'ERROR_LINE : ' ||TO_CHAR(REGEXP_SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, '"[^"]*",[^0-9]*([0-9]+)', 1, 1, NULL, 1));
                D_EVENT_DATE := SYSTIMESTAMP;

                PR_DM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER
                                  , V_IN_PARA_DATA, TO_CHAR(SQLCODE), SQLERRM, DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);

                R_ERROR_MSG := SUBSTR(SQLERRM, 1, 1000);
                RETURN;

        END;

        INX := INX + 1;

    END LOOP;

    /* ------------------------------------------------------------------------- */
    /* TXN LOG */
    /* ------------------------------------------------------------------------- */
    V_LOG_TYPE := 'TXN';    /* 로그타입 */
    N_LOG_COUNT := V_INSERT_CNT;
    V_LOG_MESSAGE := 'INSERT INTO '|| V_TABLE_ID;
    V_DESCRIPTION := 'Process Complete...' || ':' || TO_CHAR(D_EVENT_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' [DIVISION]: ' || L_DIVISION_ID;
    D_EVENT_DATE := SYSTIMESTAMP;

    PR_DM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER);

    /* ------------------------------------------------------------------------- */
    /* END LOG */
    /* ------------------------------------------------------------------------- */
    V_LOG_TYPE := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE := SYSTIMESTAMP;

    PR_DM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, V_INSERT_SUM, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER);

    R_ERROR_MSG := 'OK';

    RETURN;

END;

PROCEDURE PR_SSP_ANL_SHIP_ERP_DOC_BATCH
/* ============================================================
 * Program ID   : [PR_SSP_ANL_SHIP_ERP_DOC_BATCH]
 * Description  : ERP 문서생성 수신 후 상태 UPDATE
 * OutTable     :
 * Execute      : EXEC PR_SSP_ANL_SHIP_CONFIRM_CHG_BATCH @p_change_type @p_change_req_no
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2018.04.25   LJH         Initial Release [PJ20182279] 전지본부 출하계획 시스템 구축 프로젝트
 * 2022/03/21   KIMYONGHO   SSP_ANL_SHIP_ERP_DO 테이블 DO 생성 여부 로직 추가
 * 2026.07.06   ZIONEX      [PJ202650304] NextSCM Migration
 * ============================================================ */
AS
    /* LOG 용 변수 설정 */
    V_BATCH_USER    VARCHAR2(150 CHAR) := 'ssp_batch';
    V_PROGRAM_NAME  VARCHAR2(150 CHAR) := 'PR_SSP_ANL_SHIP_ERP_DOC_BATCH';
    V_LOG_TYPE      VARCHAR2(30 CHAR);          /* START/END/ERROR/... */
    N_LOG_COUNT     NUMBER := 0;
    V_LOG_MESSAGE   VARCHAR2(1000 CHAR);
    V_DESCRIPTION   VARCHAR2(500 CHAR);         /* 상세설명 */
    V_TABLE_ID      VARCHAR2(150 CHAR) := 'PR_SSP_ANL_SHIP_ERP_DOC_BATCH';
    D_EVENT_DATE    DATE;

    /* 임시 실행시간 확인용 */
    V_START_TIME    DATE := SYSDATE;
    V_EXEC_TIME     VARCHAR2(10 CHAR);
    V_SECS          NUMBER;

    V_ERP_DO_STATUS VARCHAR2(1 CHAR)  := NULL;
    V_ERP_DO_NO     VARCHAR2(10 CHAR) := NULL;
BEGIN
    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := V_PROGRAM_NAME || ':' || ' SHIP_CONFIRM INSERT LOGIC';
    D_EVENT_DATE  := SYSDATE;
    PR_SCP_SYS_LOG_BATCH(P_PROGRAM_NAME => V_PROGRAM_NAME, P_LOG_TYPE => V_LOG_TYPE
      , P_LOG_COUNT => N_LOG_COUNT, P_LOG_MESSAGE => V_LOG_MESSAGE, P_DESCRIPTION => V_DESCRIPTION
      , P_EVENT_DATE => D_EVENT_DATE, P_USER_ID => V_BATCH_USER);

    BEGIN
        /* 3.SSP_ANL_SHIP_CONFIRM UPDATE : ERP 문서 수신 후 상태 및 DOC NO UPDATE SSP_ANL_SHIP_CONFIRM */
        UPDATE XIF_ERP_SHIP_DOC_R_SN
           SET TRANSFER_FLAG = 'P'
         WHERE TRANSFER_FLAG = 'N'
        ;

        FOR REC IN (SELECT CONFIRM_ID
                         , DOC_TYPE
                         , DOC_NO
                         , ITEM_NO
                         , DO_NO
                      FROM XIF_ERP_SHIP_DOC_R_SN
                     WHERE TRANSFER_FLAG = 'P'
                     ORDER BY IFSEQNO, TRANSFER_DATE)
        LOOP
            V_ERP_DO_STATUS := NULL;

            BEGIN
                SELECT 'C'
                     , DO_NO
                  INTO V_ERP_DO_STATUS
                     , V_ERP_DO_NO
                  FROM SSP_ANL_SHIP_ERP_DO
                 WHERE 1 = 1
                   AND CONFIRM_ID  = REC.CONFIRM_ID
                   AND DO_VALID_YN = 'Y'
                   AND ROWNUM      = 1
                ;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    V_ERP_DO_STATUS := NULL;
            END;

            /* 업데이트 수행 ERP_SO_NO , ERP_SO_ITEM_NO,  ERP_DO_NO, ERP_STATUS */
            /* DOC_TYPE : A: SO 생성, B: SO 취소, C: DO 생성, D: DO 취소 */
            IF REC.DOC_TYPE IN ('A', 'B') THEN
                UPDATE SSP_ANL_SHIP_CONFIRM
                   SET ERP_SO_NO      = CASE WHEN REC.DOC_TYPE = 'A' THEN REC.DOC_NO
                                             WHEN REC.DOC_TYPE = 'B' THEN NULL
                                             ELSE ERP_SO_NO
                                        END
                     , ERP_SO_ITEM_NO = REC.ITEM_NO
                     , ERP_DO_NO      = CASE WHEN REC.DOC_TYPE = 'C' THEN REC.DO_NO
                                             WHEN REC.DOC_TYPE = 'D' THEN CASE WHEN V_ERP_DO_STATUS = 'C' THEN V_ERP_DO_NO ELSE NULL END
                                             ELSE ERP_DO_NO
                                        END
                     , ERP_STATUS     = CASE WHEN V_ERP_DO_STATUS = 'C' THEN V_ERP_DO_STATUS ELSE REC.DOC_TYPE END
                 WHERE CONFIRM_ID     = REC.CONFIRM_ID
                ;
            ELSIF REC.DOC_TYPE IN ('C', 'D') THEN
                UPDATE SSP_ANL_SHIP_CONFIRM
                   SET ERP_SO_NO      = CASE WHEN REC.DOC_TYPE = 'C' THEN REC.DOC_NO
                                             ELSE ERP_SO_NO
                                        END
                     , ERP_SO_ITEM_NO = REC.ITEM_NO
                     , ERP_DO_NO      = CASE WHEN REC.DOC_TYPE = 'C' THEN REC.DO_NO
                                             WHEN REC.DOC_TYPE = 'D' THEN CASE WHEN V_ERP_DO_STATUS = 'C' THEN V_ERP_DO_NO ELSE NULL END
                                             ELSE ERP_DO_NO
                                        END
                     , ERP_STATUS     = CASE WHEN V_ERP_DO_STATUS = 'C' THEN V_ERP_DO_STATUS ELSE REC.DOC_TYPE END
                 WHERE CONFIRM_ID     = REC.CONFIRM_ID
                ;
            END IF;
        END LOOP;

        UPDATE XIF_ERP_SHIP_DOC_R_SN
           SET TRANSFER_FLAG = 'Y'
         WHERE TRANSFER_FLAG = 'P'
        ;

        /* IF data  삭제 (90일 이전 데이터 삭제) */
        DELETE
          FROM XIF_ERP_SHIP_DOC_R_SN
         WHERE CREATION_DATE < SYSDATE - 90
        ;
        N_LOG_COUNT := SQL%ROWCOUNT;

        /* 실행 Logic END */
        COMMIT;

        /* TXN LOG */
        V_LOG_TYPE    := 'TXN';
        V_LOG_MESSAGE := 'INSERT INTO ' || V_TABLE_ID;
        V_DESCRIPTION := 'Process Complete...' || ':' || TO_CHAR(D_EVENT_DATE, 'YYYYMMDD');
        D_EVENT_DATE  := SYSDATE;
        PR_SCP_SYS_LOG_BATCH(P_PROGRAM_NAME => V_PROGRAM_NAME, P_LOG_TYPE => V_LOG_TYPE
          , P_LOG_COUNT => N_LOG_COUNT, P_LOG_MESSAGE => V_LOG_MESSAGE, P_DESCRIPTION => V_DESCRIPTION
          , P_EVENT_DATE => D_EVENT_DATE, P_USER_ID => V_BATCH_USER);

    EXCEPTION
        WHEN OTHERS THEN
            ROLLBACK;

            /* ERROR LOG */
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := V_PROGRAM_NAME || 'ERROR_LINE : ';
            D_EVENT_DATE  := SYSDATE;
            PR_SCP_SYS_LOG_BATCH(P_PROGRAM_NAME => V_PROGRAM_NAME, P_LOG_TYPE => V_LOG_TYPE
              , P_LOG_COUNT => N_LOG_COUNT, P_LOG_MESSAGE => V_LOG_MESSAGE, P_DESCRIPTION => V_DESCRIPTION
              , P_EVENT_DATE => D_EVENT_DATE, P_USER_ID => V_BATCH_USER
              , P_IN_PARA_DATA => NULL, P_SQL_ERR_CODE => TO_CHAR(SQLCODE)
              , P_SQL_ERR_MSG => SQLERRM, P_SQL_BACKTRACE => DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
            RETURN;
    END;

    /* 임시 운영반영시에 주석처리 할것. */
    V_SECS      := ROUND((SYSDATE - V_START_TIME) * 86400);
    V_EXEC_TIME := LPAD(TO_CHAR(TRUNC(V_SECS / 60)), 2, '0') || ':' || LPAD(TO_CHAR(MOD(V_SECS, 60)), 2, '0');

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '[' || '][' || V_EXEC_TIME || ']';
    D_EVENT_DATE  := SYSDATE;
    PR_SCP_SYS_LOG_BATCH(P_PROGRAM_NAME => V_PROGRAM_NAME, P_LOG_TYPE => V_LOG_TYPE
      , P_LOG_COUNT => N_LOG_COUNT, P_LOG_MESSAGE => V_LOG_MESSAGE, P_DESCRIPTION => V_DESCRIPTION
      , P_EVENT_DATE => D_EVENT_DATE, P_USER_ID => V_BATCH_USER);

END;

PROCEDURE PR_SSP_ANL_SHIP_ERP_PO_IN_BATCH
AS
/* ==================================================================================================
 * Program ID   : [PR_SSP_ANL_SHIP_ERP_PO_IN_BATCH]
 * Description  : PO IN 수신 정보 처리
 * OutTable     :
 * Execute      :
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2021-05-06   KIMYONGHO      최초작성
 * 2026.07.06   ZIONEX   [PJ202650304] NextSCM Migration
 * ================================================================================================== */

    /* LOG 용 변수 설정 */
    V_BATCH_USER      VARCHAR2(150 CHAR) := 'ssp_batch';
/*  SET     @v_batch_user = @p_user_id */
    V_PROGRAM_NAME    VARCHAR2(150 CHAR) := 'PR_SSP_ANL_SHIP_ERP_PO_IN_BATCH';
    V_LOG_TYPE        VARCHAR2(30 CHAR);              /* START/END/ERROR/... */
    N_LOG_COUNT       INTEGER := 0;
    V_LOG_MESSAGE     VARCHAR2(1000 CHAR);
    V_DESCRIPTION     VARCHAR2(500 CHAR);             /* ▶ 상세설명 */
    V_TABLE_ID        VARCHAR2(150 CHAR) := 'SSP_ANL_ESS_PO_IN'; /* ▶ 테이블 필수 */
    D_EVENT_DATE      DATE;

    /* 임시 실행시간 확인용 */
    V_START_TIME      DATE := SYSDATE;
    V_EXEC_TIME       VARCHAR2(10 CHAR) := '';        /* '[00:00]' */

    V_COUNT           INTEGER := 0;

    V_IF_SEQ          XIF_ERP_PO_INFO_IN_R_SN.IF_SEQ%TYPE;
BEGIN

    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := V_PROGRAM_NAME||':'||' SSP_ANL_ESS_PO_IN INSERT LOGIC';
    D_EVENT_DATE  := SYSDATE;
    PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER);

    BEGIN

        /* 인터페이스 테이블 처리 ROW UPDATE */
        UPDATE XIF_ERP_PO_INFO_IN_R_SN
           SET PROC_FLAG           = 'P'
         WHERE NVL(PROC_FLAG, 'N') = 'N'
        ;

        /* CURSOR 선언 */
        FOR CUR_ESS_PO_IN_R IN (
            SELECT IF_SEQ
              FROM XIF_ERP_PO_INFO_IN_R_SN
             WHERE PROC_FLAG = 'P'
             ORDER BY IF_SEQ
        )
        LOOP

            V_IF_SEQ := CUR_ESS_PO_IN_R.IF_SEQ;

            MERGE INTO SSP_ANL_ESS_PO_IN C
            USING
            (
                   SELECT X.IF_SEQ
                        , X.IF_TYPE
                        , X.IF_RCV_DATE
                        , X.PROC_DATE
                        , X.PROC_MSG
                        , X.IFSEQNO
                        , X.PR_NO
                        , X.PO_NO
                        , X.PO_ITEM_SEQ
                        , X.PO_ITEM_ID
                        , X.PO_ITEM_DOC_NO
                        , X.PO_ITEM_DOC_GUBUN
                        , X.PO_ITEM_IN_DATE
                        , X.PO_ITEM_IN_QTY
                        , X.UOM
                        , X.LFBNR
                        , X.ATTRIBUTE1
                        , X.ATTRIBUTE2
                        , X.ATTRIBUTE3
                        , X.ATTRIBUTE4
                        , X.ATTRIBUTE5
                        , X.ATTRIBUTE6
                        , X.ATTRIBUTE7
                        , X.ATTRIBUTE8
                        , X.ATTRIBUTE9
                        , X.ATTRIBUTE10
                     FROM XIF_ERP_PO_INFO_IN_R_SN X
                    WHERE 1 = 1
                      AND PROC_FLAG = 'P'
                      AND IF_SEQ    = V_IF_SEQ
            ) N
            ON  ( C.PR_NO     = N.PR_NO
            AND   C.PO_NO     = N.PO_NO
            /* AND C.PO_ITEM_SEQ = N.PO_ITEM_SEQ */
            AND   C.PO_ITEM_ID = N.PO_ITEM_ID )
            WHEN MATCHED THEN
            UPDATE
               SET C.PO_ITEM_DOC_NO    = N.PO_ITEM_DOC_NO
                 , C.PO_ITEM_DOC_GUBUN = N.PO_ITEM_DOC_GUBUN
                 , C.PO_ITEM_IN_DATE   = N.PO_ITEM_IN_DATE
                 , C.PO_ITEM_IN_QTY    = N.PO_ITEM_IN_QTY
                 , C.UOM               = N.UOM
                 , C.LFBNR             = N.LFBNR
                 , C.ATTRIBUTE1        = N.ATTRIBUTE1
                 , C.ATTRIBUTE2        = N.ATTRIBUTE2
                 , C.ATTRIBUTE3        = N.ATTRIBUTE3
                 , C.ATTRIBUTE4        = N.ATTRIBUTE4
                 , C.ATTRIBUTE5        = N.ATTRIBUTE5
                 , C.ATTRIBUTE6        = N.ATTRIBUTE6
                 , C.ATTRIBUTE7        = N.ATTRIBUTE7
                 , C.ATTRIBUTE8        = N.ATTRIBUTE8
                 , C.ATTRIBUTE9        = N.ATTRIBUTE9
                 , C.ATTRIBUTE10       = N.ATTRIBUTE10
                 , C.LAST_UPDATED_BY   = V_BATCH_USER
                 , C.LAST_UPDATE_DATE  = SYSDATE
            WHEN NOT MATCHED THEN
            INSERT ( PR_NO
                   , PO_NO
                   , PO_ITEM_SEQ
                   , PO_ITEM_ID
                   , PO_ITEM_DOC_NO
                   , PO_ITEM_DOC_GUBUN
                   , PO_ITEM_IN_DATE
                   , PO_ITEM_IN_QTY
                   , UOM
                   , LFBNR
                   , ATTRIBUTE1
                   , ATTRIBUTE2
                   , ATTRIBUTE3
                   , ATTRIBUTE4
                   , ATTRIBUTE5
                   , ATTRIBUTE6
                   , ATTRIBUTE7
                   , ATTRIBUTE8
                   , ATTRIBUTE9
                   , ATTRIBUTE10
                   , CREATED_BY
                   , CREATION_DATE
                   , LAST_UPDATED_BY
                   , LAST_UPDATE_DATE
                   )
            VALUES ( N.PR_NO
                   , N.PO_NO
                   , N.PO_ITEM_SEQ
                   , N.PO_ITEM_ID
                   , N.PO_ITEM_DOC_NO
                   , N.PO_ITEM_DOC_GUBUN
                   , N.PO_ITEM_IN_DATE
                   , N.PO_ITEM_IN_QTY
                   , N.UOM
                   , N.LFBNR
                   , N.ATTRIBUTE1
                   , N.ATTRIBUTE2
                   , N.ATTRIBUTE3
                   , N.ATTRIBUTE4
                   , N.ATTRIBUTE5
                   , N.ATTRIBUTE6
                   , N.ATTRIBUTE7
                   , N.ATTRIBUTE8
                   , N.ATTRIBUTE9
                   , N.ATTRIBUTE10
                   , V_BATCH_USER
                   , SYSDATE
                   , V_BATCH_USER
                   , SYSDATE
                   );

        END LOOP;

        /* 인터페이스 테이블 처리 완료 UPDATE */
        UPDATE XIF_ERP_PO_INFO_IN_R_SN
           SET PROC_FLAG           = 'Y'
             , PROC_DATE           = SYSDATE
             , PROC_MSG            = 'S'
         WHERE NVL(PROC_FLAG, 'N') = 'P'
        ;


        /* IF data  삭제 (30일 이전 데이터 삭제) */
        DELETE
          FROM XIF_ERP_PO_INFO_IN_R_SN
         WHERE IF_RCV_DATE < SYSDATE - 30
        ;

        /* --------------------------------------------------------- */
        /* 실행 Logic END -- */
        /* --------------------------------------------------------- */
        IF DBMS_TRANSACTION.LOCAL_TRANSACTION_ID IS NOT NULL THEN
            COMMIT;
        END IF;


        /* TXN LOG */
        V_LOG_TYPE    := 'TXN';    /* ▶ 로그타입 */
        N_LOG_COUNT   := SQL%ROWCOUNT;
        V_LOG_MESSAGE := 'INSERT INTO '||V_TABLE_ID;
        V_DESCRIPTION := 'Process Complete...'||':'||TO_CHAR(D_EVENT_DATE, 'YYYYMMDD');
        D_EVENT_DATE  := SYSDATE;

        PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER);

    EXCEPTION WHEN OTHERS THEN
        IF DBMS_TRANSACTION.LOCAL_TRANSACTION_ID IS NOT NULL THEN
            ROLLBACK;
        END IF;

        /* ERROR LOG */
        V_LOG_TYPE    := 'ERROR';
        V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
        V_DESCRIPTION := SUBSTR(V_PROGRAM_NAME||'ERROR_LINE : '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 500);
        D_EVENT_DATE  := SYSDATE;
        PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER);
        RETURN;
    END;

    /* 임시 운영반영시에 주석처리 할것. */

    V_EXEC_TIME := CASE WHEN LENGTH(TO_CHAR(TRUNC(ROUND((SYSDATE - V_START_TIME) * 86400) / 60))) > 2 THEN NULL
                        ELSE LPAD(TO_CHAR(TRUNC(ROUND((SYSDATE - V_START_TIME) * 86400) / 60)), 2, '0')||':'||
                            LPAD(TO_CHAR(MOD(ROUND((SYSDATE - V_START_TIME) * 86400), 60)), 2, '0')
                   END;


    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '['||V_PROGRAM_NAME||']['||V_EXEC_TIME||']';
    D_EVENT_DATE  := SYSDATE;
    PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER);

    RETURN;

END;

PROCEDURE PR_SSP_DNM_FORMATION_POST_CELL
/***************************************************************************************************
 * Program ID   : PR_SSP_DNM_FORMATION_POST_CELL
 * Description  : SSP_FORMATION_POST_CELL_V 1시간 배치 적용
 * OutTable     :
 * Execute      : EXEC PR_SSP_DNM_FORMATION_POST_CELL
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 *   20210526   SSP Pjt.       Create
 *   2026.07.06 ZIONEX         [PJ202650304] NextSCM Migration
 ***************************************************************************************************/
IS
    /* LOG 용 변수 설정 */
    V_BATCH_USER        VARCHAR2(150 CHAR) := 'ssp_batch';

    V_PROGRAM_NAME      VARCHAR2(150 CHAR) := 'PR_SSP_DNM_FORMATION_POST_CELL';
    V_LOG_TYPE          VARCHAR2(30 CHAR);
    N_LOG_COUNT         NUMBER(19) := 0;
    V_LOG_MESSAGE       VARCHAR2(1000 CHAR);
    V_DESCRIPTION       VARCHAR2(500 CHAR);      /* ▶ 상세설명 */
    V_TABLE_ID          VARCHAR2(150 CHAR) := 'SSP_DNM_FORMATION_POST_CELL'; /* ▶ 테이블 필수 */
    D_EVENT_DATE        DATE;

    N_DM_REQ_CNT        NUMBER(19) := 0;
    V_DIVISION_ID       VARCHAR2(10 CHAR);
    V_DM_REQ_NO         VARCHAR2(60 CHAR) := '';

    V_START_TIME        DATE := SYSDATE;
    V_EXEC_TIME         VARCHAR2(10 CHAR) := '';

    V_FROM_YYYYMMDD     VARCHAR2(8 CHAR);
    V_TO_YYYYMMDD       VARCHAR2(8 CHAR);

    N_INX               NUMBER(19) := 0;
    N_MAX_NUM           NUMBER(19) := 0;


    V_SQL_ERRMSG        VARCHAR2(1000 CHAR);
    V_BACKTRACE         VARCHAR2(4000 CHAR);
BEGIN


    /* 원본 IF OBJECT_ID('tempdb..#TAB') IS NOT NULL DROP TABLE #TAB / CREATE TABLE #TAB */
    /* 원본 死주석 보존 : --DECLARE @TAB        TABLE */
    /*   → GTT GT_SDFPC_TAB(ON COMMIT PRESERVE ROWS) + 본문 시작 DELETE 초기화 */
    DELETE
      FROM GT_SDFPC_TAB;


    V_FROM_YYYYMMDD := TO_CHAR(SYSDATE, 'YYYYMMDD');


    V_TO_YYYYMMDD   := TO_CHAR(TO_DATE(V_FROM_YYYYMMDD, 'YYYYMMDD') + 60, 'YYYYMMDD');

    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := V_PROGRAM_NAME || ': ' || V_TABLE_ID || ' INSERT LOGIC';
    D_EVENT_DATE  := SYSDATE;

    PR_SCP_SYS_LOG_BATCH(P_PROGRAM_NAME => V_PROGRAM_NAME
                        ,P_LOG_TYPE     => V_LOG_TYPE
                        ,P_LOG_COUNT    => N_LOG_COUNT
                        ,P_LOG_MESSAGE  => V_LOG_MESSAGE
                        ,P_DESCRIPTION  => V_DESCRIPTION
                        ,P_EVENT_DATE   => D_EVENT_DATE
                        ,P_USER_ID      => V_BATCH_USER
                        );

    BEGIN

        INSERT
          INTO GT_SDFPC_TAB
             ( DIVISION_ID
             , CELL_ITEM_ID
             , SCM_SITE_ID
             , LINE_ID
             , PLAN_DATE
             , PLAN_QTY )
        SELECT FP.DIVISION_ID
             , FP.CELL_ITEM_ID
             , FP.SCM_SITE_ID
             , FP.LINE_ID
             , FP.PLAN_DATE
             , SUM(NVL(FP.PLAN_QTY, 0)) AS PLAN_QTY
          FROM SSP_FORMATION_POST_CELL_V FP
          /* FROM dbo.SCM_FORMATION_POST_CELL_V_SN FP WITH(NOLOCK) */
         WHERE FP.DIVISION_ID = '40'

           AND FP.PLAN_DATE >= V_FROM_YYYYMMDD
           AND FP.PLAN_DATE <= V_TO_YYYYMMDD
         GROUP BY FP.DIVISION_ID
             , FP.CELL_ITEM_ID
             , FP.SCM_SITE_ID
             , FP.LINE_ID
             , FP.PLAN_DATE;

        DELETE
          FROM GT_SDFPC_TAB
         WHERE CELL_ITEM_ID IS NULL;

        /* BEGIN TRAN TX_SH */
        MERGE INTO SSP_DNM_FORMATION_POST_CELL A
        USING GT_SDFPC_TAB B
           ON (    A.DIVISION_ID  = B.DIVISION_ID
               AND A.CELL_ITEM_ID = B.CELL_ITEM_ID
               AND A.SCM_SITE_ID  = B.SCM_SITE_ID
               AND A.LINE_ID      = B.LINE_ID
               AND A.PLAN_DATE    = B.PLAN_DATE
              )
        WHEN MATCHED THEN
            UPDATE
               SET A.PLAN_QTY         = B.PLAN_QTY
                 , A.LAST_UPDATED_BY  = V_BATCH_USER
                 , A.LAST_UPDATE_DATE = SYSDATE
        WHEN NOT MATCHED THEN
            INSERT
                 ( DIVISION_ID
                 , CELL_ITEM_ID
                 , SCM_SITE_ID
                 , LINE_ID
                 , PLAN_DATE
                 , PLAN_QTY
                 , CREATED_BY
                 , CREATION_DATE
                 , LAST_UPDATED_BY
                 , LAST_UPDATE_DATE )
            VALUES ( B.DIVISION_ID
                   , B.CELL_ITEM_ID
                   , B.SCM_SITE_ID
                   , B.LINE_ID
                   , B.PLAN_DATE
                   , B.PLAN_QTY
                   , V_BATCH_USER
                   , SYSDATE
                   , V_BATCH_USER
                   , SYSDATE );

        /* 원본 DELETE T FROM SSP_DNM_FORMATION_POST_CELL T LEFT OUTER JOIN #TAB S ... WHERE S.DIVISION_ID IS NULL (안티조인) → NOT EXISTS */

        DELETE
          FROM SSP_DNM_FORMATION_POST_CELL T
         WHERE NOT EXISTS (SELECT 1
                             FROM GT_SDFPC_TAB S
                            WHERE S.DIVISION_ID  = T.DIVISION_ID
                              AND S.CELL_ITEM_ID = T.CELL_ITEM_ID
                              AND S.SCM_SITE_ID  = T.SCM_SITE_ID
                              AND S.LINE_ID      = T.LINE_ID
                              AND S.PLAN_DATE    = T.PLAN_DATE);

        /* COMMIT TRAN TX_SH; */
        /* ----------------------------------------------------------- */
        /* 실행 Logic END */
        /* ----------------------------------------------------------- */

        /* TXN LOG */
        V_LOG_TYPE    := 'TXN';    /* ▶ 로그타입 */

        N_LOG_COUNT   := 1;
        V_LOG_MESSAGE := 'EXECUTE ' || V_PROGRAM_NAME;
        V_DESCRIPTION := 'Process Complete...' || ':' || TO_CHAR(D_EVENT_DATE, 'YYYYMMDD');
        D_EVENT_DATE  := SYSDATE;

        PR_SCP_SYS_LOG_BATCH(P_PROGRAM_NAME => V_PROGRAM_NAME
                            ,P_LOG_TYPE     => V_LOG_TYPE
                            ,P_LOG_COUNT    => N_LOG_COUNT
                            ,P_LOG_MESSAGE  => V_LOG_MESSAGE
                            ,P_DESCRIPTION  => V_DESCRIPTION
                            ,P_EVENT_DATE   => D_EVENT_DATE
                            ,P_USER_ID      => V_BATCH_USER
                            );

    EXCEPTION
        WHEN OTHERS THEN

            /* ROLLBACK TRAN TX_SH */

            /* ERROR LOG (원본 CATCH: RAISERROR/THROW 없이 흡수 후 RETURN -1 → Oracle도 흡수·RAISE 없음. */

            V_SQL_ERRMSG  := SUBSTR(SQLERRM, 1, 1000);
            V_BACKTRACE   := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
            V_LOG_TYPE    := 'ERROR';

            V_LOG_MESSAGE := V_SQL_ERRMSG;

            V_DESCRIPTION := SUBSTR(V_PROGRAM_NAME || 'ERROR_LINE : ' || V_BACKTRACE, 1, 500);
            D_EVENT_DATE  := SYSDATE;

            PR_SCP_SYS_LOG_BATCH(P_PROGRAM_NAME => V_PROGRAM_NAME
                                ,P_LOG_TYPE     => V_LOG_TYPE
                                ,P_LOG_COUNT    => N_LOG_COUNT
                                ,P_LOG_MESSAGE  => V_LOG_MESSAGE
                                ,P_DESCRIPTION  => V_DESCRIPTION
                                ,P_EVENT_DATE   => D_EVENT_DATE
                                ,P_USER_ID      => V_BATCH_USER
                                );

            /* 원본 IF OBJECT_ID('tempdb..#TAB') IS NOT NULL DROP TABLE #TAB → GTT는 세션 유지(DROP 미이관) */


            RETURN;

    END;


    /* 임시 운영반영시에 주석처리 할것. */


    V_EXEC_TIME := CASE WHEN LENGTH(TO_CHAR(TRUNC(ROUND((SYSDATE - V_START_TIME) * 86400) / 60))) > 2 THEN NULL
                        ELSE LPAD(TO_CHAR(TRUNC(ROUND((SYSDATE - V_START_TIME) * 86400) / 60)), 2, '0') || ':' ||
                            LPAD(TO_CHAR(MOD(ROUND((SYSDATE - V_START_TIME) * 86400), 60)), 2, '0')
                   END;

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '[' || '][' || V_EXEC_TIME || ']';
    D_EVENT_DATE  := SYSDATE;

    PR_SCP_SYS_LOG_BATCH(P_PROGRAM_NAME => V_PROGRAM_NAME
                        ,P_LOG_TYPE     => V_LOG_TYPE
                        ,P_LOG_COUNT    => N_LOG_COUNT
                        ,P_LOG_MESSAGE  => V_LOG_MESSAGE
                        ,P_DESCRIPTION  => V_DESCRIPTION
                        ,P_EVENT_DATE   => D_EVENT_DATE
                        ,P_USER_ID      => V_BATCH_USER
                        );

    /* 원본 IF OBJECT_ID('tempdb..#TAB') IS NOT NULL DROP TABLE #TAB → GTT는 세션 유지(DROP 미이관·진입부 DELETE로 초기화) */


    RETURN;
END PR_SSP_DNM_FORMATION_POST_CELL;

PROCEDURE PR_SSP_DNM_FP_PLAN_FROZEN
/***************************************************************************************************
 * Program ID   : PR_SSP_DNM_FP_PLAN_FROZEN
 * Description  : SCM_DNM_PLAN_FROZEN_V 1시간 배치 적용
 * OutTable     :
 * Execute      : EXEC PR_SSP_DNM_FP_PLAN_FROZEN
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2021.05.14   SSP Pjt.       Create
 * 2021.11.25   SSP Pjt.       성능개선을 위한 튜닝
 * 2022.04.01   SSP Pjt.       JV DIVISION_ID 적용
 * 2026.07.06   ZIONEX         [PJ202650304] NextSCM Migration
 ***************************************************************************************************/
IS
    /* LOG 용 변수 설정 */
    V_BATCH_USER        VARCHAR2(150 CHAR) := 'ssp_batch';

    V_PROGRAM_NAME      VARCHAR2(150 CHAR) := 'PR_SSP_DNM_FP_PLAN_FROZEN';
    V_LOG_TYPE          VARCHAR2(30 CHAR);
    N_LOG_COUNT         NUMBER(19) := 0;
    V_LOG_MESSAGE       VARCHAR2(1000 CHAR);
    V_DESCRIPTION       VARCHAR2(500 CHAR);      /* ▶ 상세설명 */
    V_TABLE_ID          VARCHAR2(150 CHAR) := 'SSP_DNM_FP_PLAN_FROZEN'; /* ▶ 테이블 필수 */
    D_EVENT_DATE        DATE;

    N_DM_REQ_CNT        NUMBER(19) := 0;
    V_DIVISION_ID       VARCHAR2(10 CHAR);
    V_DM_REQ_NO         VARCHAR2(60 CHAR) := '';

    V_START_TIME        DATE := SYSDATE;
    V_EXEC_TIME         VARCHAR2(10 CHAR) := '';

    V_FROM_YYYYMMDD     VARCHAR2(8 CHAR);
    V_TO_YYYYMMDD       VARCHAR2(8 CHAR);

    N_INX               NUMBER(19) := 0;
    N_MAX_NUM           NUMBER(19) := 0;


    V_SQL_CODE          VARCHAR2(100 CHAR);
    V_SQL_ERRMSG        VARCHAR2(1000 CHAR);
    V_BACKTRACE         VARCHAR2(4000 CHAR);
BEGIN


    /* ★GTT 초기화(ON COMMIT PRESERVE ROWS이므로 본문 시작 시 DELETE) */
    DELETE FROM GT_SDFPF_TAB;


    V_FROM_YYYYMMDD := TO_CHAR(SYSDATE - 2, 'YYYYMMDD');

    V_TO_YYYYMMDD   := TO_CHAR(TO_DATE(V_FROM_YYYYMMDD, 'YYYYMMDD') + 60, 'YYYYMMDD');

    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := V_PROGRAM_NAME || ': ' || V_TABLE_ID || ' INSERT LOGIC';
    D_EVENT_DATE  := SYSDATE;

    PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER);

    BEGIN

        INSERT INTO GT_SDFPF_TAB (DIVISION_ID
                                , SCM_SITE_ID
                                , ITEM_ID
                                , PLAN_DATE
                                , OPERATION_ID
                                , SITE_ID
                                , COMPANY_ID
                                , PLAN_QTY)
        SELECT FP.DIVISION_ID
             , FP.SCM_SITE_ID
             , FP.ITEM_ID
             , TO_CHAR(FP.PLAN_DATE, 'YYYYMMDD') AS PLAN_DATE
             , FP.OPERATION_ID
             , FP.SITE_ID
             , FP.COMPANY_ID
             , SUM(FP.PLAN_QTY) AS PLAN_QTY
          FROM (SELECT M.SCM_SITE_ID
                     , R.COMPANY_ID                                     /*  */
                     , R.DIVISION_ID                                    /*  */
                     , R.SITE_ID                                        /*  */
                     , R.PLANT_ID
                     , R.FACTORY_ID
                     , R.OPERATION_ID
                     , R.LOCATION
                     , R.TOP_ITEM_ID
                     , NVL(FI.PACKER_PLAN_ITEM_ID, R.ITEM_ID) AS ITEM_ID        /* 2018.06.29 */
                     , R.ITEM_ID AS ORIGIN_ITEM_ID                              /* 2018.06.29 */
                     , R.FP_PRODUCTION_TYPE
                     , R.MARKET
                     , R.LINE_ID
                     , R.ELECTRODE_TYPE
                     , R.PLAN_DATE
                     , R.PLAN_QTY                                       /* OUT 수량 */
                                                                        /* IN 수량 */
                     , CASE WHEN R.PLAN_IN_QTY <= 0 THEN R.PLAN_QTY
                            ELSE R.PLAN_IN_QTY
                       END AS PLAN_IN_QTY
                     , R.EQUIPMENT_ID
                  FROM SCM_DNM_FP_RELEASE_PLAN_V_SN R

                  LEFT JOIN SCP_MST_FINAL_ITEM FI                       /* 2018.06.29 */
                    ON R.DIVISION_ID = FI.DIVISION_ID
                   AND R.ITEM_ID     = FI.ITEM_ID

                  LEFT OUTER JOIN LATERAL (SELECT I.SCP_OPERATION_GROUP AS SCP_OPERATION_GROUP
                                             FROM SCM_MST_ITEM_SN I
                                            WHERE 1 = 1
                                              AND I.DIVISION_ID = R.DIVISION_ID
                                              AND I.ITEM_ID     = R.ITEM_ID
                                            FETCH FIRST 1 ROWS ONLY) OG ON (1 = 1)
                  LEFT OUTER JOIN LATERAL (SELECT I.SCM_SITE_ID AS SCM_SITE_ID
                                             FROM SCM_MST_SITE I
                                            WHERE 1 = 1
                                              AND I.PLANT_ID        = R.PLANT_ID
                                              AND I.OPERATION_GROUP = OG.SCP_OPERATION_GROUP
                                              AND I.SITE_TYPE       = 'PLANT'
                                              AND I.VALID_YN        = 'Y'
                                            FETCH FIRST 1 ROWS ONLY) M ON (1 = 1)
                 WHERE NVL(R.FP_PRODUCTION_TYPE, '-') NOT IN ('TEST', 'REWORK', 'M/C')) FP
             , SCM_MST_SITE FS
         WHERE FP.DIVISION_ID = FS.DIVISION_ID
           AND FP.SCM_SITE_ID = FS.SCM_SITE_ID
           AND FS.SITE_TYPE   = 'PLANT'
        /* AND FS.OSP_YN      = 'N' */
           AND FS.VALID_YN    = 'Y'
        /* AND FP.DIVISION_ID  IN (SELECT DIVISION_ID
                                     FROM SCM_MST_DIVISION WITH(NOLOCK)
                                    WHERE VALID_YN = 'Y'
                                      AND ATTRIBUTE3 IN ('81','82') ) */
           AND FP.DIVISION_ID IN ('81', '82', '81_UC', '81_HM', '81_ST', '81_HD', '81_HG')   /* 25.07.22 Adding '81_HG' */

           AND FP.PLAN_DATE   >= TO_DATE(V_FROM_YYYYMMDD, 'YYYYMMDD')
           AND FP.PLAN_DATE   <= TO_DATE(V_TO_YYYYMMDD, 'YYYYMMDD')
           AND FP.PLAN_QTY    > 0
           AND FP.PLAN_IN_QTY > 0
         GROUP BY FP.DIVISION_ID
                , FP.SCM_SITE_ID
                , FP.ITEM_ID
                , FP.PLAN_DATE
                , FP.OPERATION_ID
                , FP.SITE_ID
                , FP.COMPANY_ID;


        /* ----BEGIN TRAN TX_SH */

        MERGE INTO SSP_DNM_FP_PLAN_FROZEN A
        USING GT_SDFPF_TAB B
           ON (    A.DIVISION_ID  = B.DIVISION_ID
               AND A.SCM_SITE_ID  = B.SCM_SITE_ID
               AND A.ITEM_ID      = B.ITEM_ID
               AND A.PLAN_DATE    = B.PLAN_DATE
               AND A.OPERATION_ID = B.OPERATION_ID
               AND A.SITE_ID      = B.SITE_ID
               AND A.COMPANY_ID   = B.COMPANY_ID)
        WHEN MATCHED THEN
            UPDATE
               SET A.PLAN_QTY         = B.PLAN_QTY
                 , A.LAST_UPDATED_BY  = V_BATCH_USER
                 , A.LAST_UPDATE_DATE = SYSDATE
        WHEN NOT MATCHED THEN
            INSERT (DIVISION_ID
                  , SCM_SITE_ID
                  , ITEM_ID
                  , PLAN_DATE
                  , OPERATION_ID
                  , SITE_ID
                  , COMPANY_ID
                  , PLAN_QTY
                  , CREATED_BY
                  , CREATION_DATE
                  , LAST_UPDATED_BY
                  , LAST_UPDATE_DATE)
            VALUES (B.DIVISION_ID
                  , B.SCM_SITE_ID
                  , B.ITEM_ID
                  , B.PLAN_DATE
                  , B.OPERATION_ID
                  , B.SITE_ID
                  , B.COMPANY_ID
                  , B.PLAN_QTY
                  , V_BATCH_USER
                  , SYSDATE
                  , V_BATCH_USER
                  , SYSDATE);

        /* 원본 DELETE T FROM SSP_DNM_FP_PLAN_FROZEN T LEFT OUTER JOIN @TAB S ... WHERE S.DIVISION_ID IS NULL (안티조인) → NOT EXISTS */
        DELETE FROM SSP_DNM_FP_PLAN_FROZEN T
         WHERE NOT EXISTS (SELECT 1
                             FROM GT_SDFPF_TAB S
                            WHERE S.DIVISION_ID  = T.DIVISION_ID
                              AND S.SCM_SITE_ID  = T.SCM_SITE_ID
                              AND S.ITEM_ID      = T.ITEM_ID
                              AND S.PLAN_DATE    = T.PLAN_DATE
                              AND S.OPERATION_ID = T.OPERATION_ID
                              AND S.SITE_ID      = T.SITE_ID
                              AND S.COMPANY_ID   = T.COMPANY_ID);


        /* COMMIT TRAN TX_SH; */
        /* ----------------------------------------------------------- */
        /* 실행 Logic END */
        /* ----------------------------------------------------------- */

        /* TXN LOG */
        V_LOG_TYPE    := 'TXN';    /* ▶ 로그타입 */

        N_LOG_COUNT   := 1;
        V_LOG_MESSAGE := 'EXECUTE ' || V_PROGRAM_NAME;
        V_DESCRIPTION := 'Process Complete...' || ':' || TO_CHAR(D_EVENT_DATE, 'YYYYMMDD');
        D_EVENT_DATE  := SYSDATE;

        PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER);

        /* 표준배치: 정상경로 COMMIT(MSSQL autocommit 지속 의도 재현). 원본 COMMIT TRAN TX_SH는 주석(死)이나 배치 영속성 위해 COMMIT. */
        COMMIT;

    EXCEPTION
        WHEN OTHERS THEN

            /* ROLLBACK TRAN TX_SH */

            /* ERROR LOG (원본 CATCH: RAISERROR/THROW 없이 흡수 후 RETURN -1 → Oracle도 흡수·RAISE 없음. 명시 활성 TRAN 없어 ROLLBACK 미추가) */
            V_SQL_CODE    := TO_CHAR(SQLCODE);
            V_SQL_ERRMSG  := SUBSTR(SQLERRM, 1, 1000);
            V_BACKTRACE   := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := V_SQL_ERRMSG;
            V_DESCRIPTION := SUBSTR(V_PROGRAM_NAME || 'ERROR_LINE : ' || V_BACKTRACE, 1, 500);
            D_EVENT_DATE  := SYSDATE;

            PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER, NULL, V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE);


            RETURN;

    END;

    /* 임시 운영반영시에 주석처리 할것. */


    V_EXEC_TIME := CASE WHEN LENGTH(TO_CHAR(TRUNC(ROUND((SYSDATE - V_START_TIME) * 86400) / 60))) > 2 THEN NULL
                        ELSE LPAD(TO_CHAR(TRUNC(ROUND((SYSDATE - V_START_TIME) * 86400) / 60)), 2, '0') || ':' ||
                            LPAD(TO_CHAR(MOD(ROUND((SYSDATE - V_START_TIME) * 86400), 60)), 2, '0')
                   END;

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '[' || '][' || V_EXEC_TIME || ']';
    D_EVENT_DATE  := SYSDATE;

    PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER);


    RETURN;
END PR_SSP_DNM_FP_PLAN_FROZEN;

