    V_CUTOFF_DATE       DATE;

    N_INX               NUMBER(19) := 0;
    N_MAX_NUM           NUMBER(19) := 0;


    V_SQL_CODE          VARCHAR2(100 CHAR);
    V_SQL_ERRMSG        VARCHAR2(1000 CHAR);
    V_BACKTRACE         VARCHAR2(4000 CHAR);
BEGIN


    /* ★GTT 초기화(ON COMMIT PRESERVE ROWS이므로 본문 시작 시 DELETE) */
    DELETE FROM GT_SDMWH_TAB;

    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := V_PROGRAM_NAME || ': ' || V_TABLE_ID || ' INSERT LOGIC';
    D_EVENT_DATE  := SYSDATE;

    PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER);

    BEGIN

        /* 원본: INSERT INTO @TAB SELECT ... FROM [LGCE_FP_TR].[dbo].[SCM_MES_WIP_HISTORY_H] (크로스DB → 시노님 SCM_MES_WIP_HISTORY_H_SN) */


        INSERT
          INTO GT_SDMWH_TAB
             ( DIVISION_ID
             , FROM_SITE
             , ITEM_ID
             , LOT_ID
             , YYYYMMDD
             , WIPQTY2_ED )
        SELECT F.DIVISION_ID
             , S.SCM_SITE_ID AS FROM_SITE
             , M.PRODID AS ITEM_ID
             , SUBSTR(M.ATTRIBUTE7, 1, 8) AS LOT_ID
             , REPLACE(SUBSTR(M.CALDATE, 1, 10), '-', '') AS YYYYMMDD
             , SUM(M.WIPQTY2_ED) AS WIPQTY2_ED
          FROM SCM_MES_WIP_HISTORY_H_SN M
               INNER JOIN SCM_MST_FACTORY_SN F
            ON M.ATTRIBUTE2 = F.FACTORY_ID
               INNER JOIN SCM_MST_SITE S
            ON F.PLANT_ID = S.PLANT_ID
           AND F.SHOP_GROUP_ID = S.OPERATION_GROUP
           AND S.SITE_TYPE = 'PLANT'
           AND S.VALID_YN = 'Y'
         WHERE M.ATTRIBUTE7 IS NOT NULL
           AND M.PROCID = 'A3000'
           AND M.CALDATE BETWEEN SUBSTR(TO_CHAR(SYSDATE - 3, 'YYYY-MM-DD HH24:MI:SS'), 1, 10) || ' 00:00:00'
                             AND SUBSTR(TO_CHAR(SYSDATE, 'YYYY-MM-DD HH24:MI:SS'), 1, 10) || ' 00:00:00'
         GROUP BY F.DIVISION_ID
                , S.SCM_SITE_ID
                , M.PRODID
                , M.CALDATE
                , SUBSTR(M.ATTRIBUTE7, 1, 8);

        /* BEGIN TRAN TX_SH */
        MERGE INTO SSP_DNM_MES_WIP_HISTORY T
        USING GT_SDMWH_TAB S
           ON (    T.DIVISION_ID = S.DIVISION_ID
               AND T.FROM_SITE   = S.FROM_SITE
               AND T.ITEM_ID     = S.ITEM_ID
               AND T.LOT_ID      = S.LOT_ID
               AND T.YYYYMMDD    = S.YYYYMMDD
              )
        WHEN MATCHED THEN
            UPDATE
               SET T.WIPQTY2_ED       = S.WIPQTY2_ED
                 , T.LAST_UPDATED_BY  = V_BATCH_USER
                 , T.LAST_UPDATE_DATE = SYSDATE
        WHEN NOT MATCHED THEN
            INSERT
                 ( DIVISION_ID
                 , FROM_SITE
                 , ITEM_ID
                 , LOT_ID
                 , YYYYMMDD
                 , WIPQTY2_ED
                 , CREATED_BY
                 , CREATION_DATE
                 , LAST_UPDATED_BY
                 , LAST_UPDATE_DATE )
            VALUES ( S.DIVISION_ID
                   , S.FROM_SITE
                   , S.ITEM_ID
                   , S.LOT_ID
                   , S.YYYYMMDD
                   , S.WIPQTY2_ED
                   , V_BATCH_USER
                   , SYSDATE
                   , V_BATCH_USER
                   , SYSDATE );

        /* COMMIT TRAN TX_SH; */
        /* ----------------------------------------------------------- */
        /* 실행 Logic END */
        /* ----------------------------------------------------------- */

        /* TXN LOG */
        V_LOG_TYPE    := 'TXN';    /* ▶ 로그타입 */

        N_LOG_COUNT   := 1;
        V_LOG_MESSAGE := 'EXECUTE ' || V_PROGRAM_NAME;
        V_DESCRIPTION := 'Process Complete...' || ':' || TO_CHAR(D_EVENT_DATE, 'YYYYMMDD');
        D_EVENT_DATE  := SYSDATE;

        PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER);

        /* 표준배치: 정상경로 COMMIT(MSSQL autocommit 지속 의도 재현). 원본 COMMIT TRAN TX_SH는 주석(死)이나 배치 영속성 위해 COMMIT. */
        COMMIT;

    EXCEPTION
        WHEN OTHERS THEN

            /* ROLLBACK TRAN TX_SH */

            /* ERROR LOG (원본 CATCH: RAISERROR/THROW 없이 흡수 후 RETURN -1 → Oracle도 흡수·RAISE 없음. 명시 활성 TRAN 없어 ROLLBACK 미추가) */
            V_SQL_CODE    := TO_CHAR(SQLCODE);
            V_SQL_ERRMSG  := SUBSTR(SQLERRM, 1, 1000);
            V_BACKTRACE   := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := V_SQL_ERRMSG;
            V_DESCRIPTION := SUBSTR(V_PROGRAM_NAME || 'ERROR_LINE : ' || V_BACKTRACE, 1, 500);
            D_EVENT_DATE  := SYSDATE;

            PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER, NULL, V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE);


            RETURN;

    END;

    /* 임시 운영반영시에 주석처리 할것. */


    V_EXEC_TIME := CASE WHEN LENGTH(TO_CHAR(TRUNC(ROUND((SYSDATE - V_START_TIME) * 86400) / 60))) > 2 THEN NULL
                        ELSE LPAD(TO_CHAR(TRUNC(ROUND((SYSDATE - V_START_TIME) * 86400) / 60)), 2, '0') || ':' ||
                            LPAD(TO_CHAR(MOD(ROUND((SYSDATE - V_START_TIME) * 86400), 60)), 2, '0')
                   END;

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '[' || '][' || V_EXEC_TIME || ']';
    D_EVENT_DATE  := SYSDATE;

    PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER);


    RETURN;
END PR_SSP_DNM_MES_WIP_HISTORY;

