 *   Date       In Charge		Description
 *===================================================================================================
 * 2020.03.11   KIMYONGHO		Initial Release [] 전지GSCM(SSP) SM 운영
 * 2024.10.01   KHJ             NERP_SSP
 * 2026.08.03   ZIONEX          [PJ202650304]  NextSCM Migration
 */
 AS
    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME VARCHAR2(150 CHAR) := 'PR_SSP_IF_CHECK_SMS_SEND';
    V_LOG_TYPE     VARCHAR2(30 CHAR);   /* START/END/ERROR/... */
    N_LOG_COUNT    INTEGER := 0;
    V_LOG_MESSAGE  VARCHAR2(1000 CHAR);
    V_DESCRIPTION  VARCHAR2(500 CHAR);
    D_EVENT_DATE   DATE;
    V_TEXT         VARCHAR2(200 CHAR);
    V_CODE         VARCHAR2(10 CHAR);

    /* NERP 매핑코드 */
    V_C100         VARCHAR2(10 CHAR);
    V_G180         VARCHAR2(10 CHAR);
    V_G380         VARCHAR2(10 CHAR);
    V_G450         VARCHAR2(10 CHAR);
    V_G480         VARCHAR2(10 CHAR);
    V_G630         VARCHAR2(10 CHAR);


    V_RS           VARCHAR2(10 CHAR);
    V_MESSAGE      VARCHAR2(100 CHAR);

    /* Oracle 필수 추가: MSSQL 은 IF ( SELECT COUNT(*) ... ) < 1 처럼 IF 조건에 SELECT 를 직접 쓸 수 있으나
       PL/SQL 은 불가(PLS-00103) → SELECT COUNT(*) INTO N_CNT 후 IF N_CNT < 1 로 분해. 로직 동일. */
    N_CNT          INTEGER;
  BEGIN


    V_C100 := FN_GET_LOOKUP_VALUE('PR_SSP_IF_CHECK_SMS_SEND', 'ESOC');   /* C100 */
    V_G180 := FN_GET_LOOKUP_VALUE('PR_SSP_IF_CHECK_SMS_SEND', 'ESNJ');   /* G180 */
    V_G380 := FN_GET_LOOKUP_VALUE('PR_SSP_IF_CHECK_SMS_SEND', 'ESMI');   /* G380 */
    V_G450 := FN_GET_LOOKUP_VALUE('PR_SSP_IF_CHECK_SMS_SEND', 'ESNA');   /* G450 */
    V_G480 := FN_GET_LOOKUP_VALUE('PR_SSP_IF_CHECK_SMS_SEND', 'ESWA');   /* G480 */
    V_G630 := FN_GET_LOOKUP_VALUE('PR_SSP_IF_CHECK_SMS_SEND', 'ESNB');   /* G630 */


    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := NULL;
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);


    BEGIN
      BEGIN

        V_RS      := NULL;
        V_MESSAGE := NULL;

        /* XIF_MES_FORMATION_LOT_QMS_INSP_RESULT_R_SN
         A010 : 06, 14
         G182 : 09
        */

        /*               DROP TABLE #TEMP_XIF_MES_FORMATION_LOT_QMS_INSP_RESULT_R_SN
           CREATE TABLE #TEMP_XIF_MES_FORMATION_LOT_QMS_INSP_RESULT_R_SN (
               IF_RCV_DATE          datetime,
               PLANT_ID             nvarchar(30)    NULL
           ); */
        DELETE
          FROM GT_SSPSMS_MES_FORMATION_LOT;

        /* XIF_MES_ISS_WAIT_PALLET_R_SN
         A040 : 06
         A050 : 06
         G382 : 20, 21
         G451 : 09
         G481 : 15
         G631 : 09
         G634 : 09
        */

        /*               DROP TABLE #TEMP_XIF_MES_ISS_WAIT_PALLET_R_SN
           CREATE TABLE #TEMP_XIF_MES_ISS_WAIT_PALLET_R_SN (
               IF_RCV_DATE          datetime,
               PLANT_ID             nvarchar(30)    NULL
           ); */
        DELETE
          FROM GT_SSPSMS_MES_ISS_WAIT_PALLET;

        /* XIF_OWMS_SHIP_RESULT_R_SN
           XIF_OWMS_SHIP_RETURN_R_SN

         A002 : 06
         A010 : 06
         A040 : 06
         A050 : 06
         G182 : 09
         G184 : 09
         G382 : 21
         G451 : 09
         G481 : 15
        */

        /*               DROP TABLE #TEMP_XIF_OWMS_SHIP_RESULT_R_SN
           CREATE TABLE #TEMP_XIF_OWMS_SHIP_RESULT_R_SN (
               IF_RCV_DATE          datetime,
               PLANT_ID             nvarchar(30)    NULL
           ); */
        DELETE
          FROM GT_SSPSMS_OWMS_SHIP_RESULT;

        /*               DROP TABLE #TEMP_XIF_OWMS_SHIP_RETURN_R_SN
           CREATE TABLE #TEMP_XIF_OWMS_SHIP_RETURN_R_SN (
               IF_RCV_DATE          datetime,
               PLANT_ID             nvarchar(30)    NULL
           ); */
        DELETE
          FROM GT_SSPSMS_OWMS_SHIP_RETURN;

        /* XIF_OWMS_STOCK_R_SN
        A002
        A010
        A040
        A050
        G182
        G184
        G382
        G451
        G481
        G631
        G634

        */

        /*               DROP TABLE #TEMP_XIF_OWMS_STOCK_R_SN
           CREATE TABLE #TEMP_XIF_OWMS_STOCK_R_SN (
               IF_RCV_DATE          datetime,
               PLANT_ID             nvarchar(30)    NULL
           ); */
        DELETE
          FROM GT_SSPSMS_OWMS_STOCK;

/* INF-R 적용 이전
			INSERT INTO #TEMP_XIF_MES_FORMATION_LOT_QMS_INSP_RESULT_R_SN
			SELECT IF_SEQ, IF_ID, IF_RCV_DATE, PLANT_ID
			FROM XIF_MES_FORMATION_LOT_QMS_INSP_RESULT_R_SN WITH(NOLOCK)
			WHERE CONVERT(CHAR(10), IF_RCV_DATE, 23) = CONVERT(CHAR(10), GETDATE(), 23)

			INSERT INTO #TEMP_XIF_MES_ISS_WAIT_PALLET_R_SN
			SELECT IF_SEQ, IF_ID, IF_RCV_DATE, PLANT_ID
			FROM XIF_MES_ISS_WAIT_PALLET_R_SN WITH(NOLOCK)
			WHERE CONVERT(CHAR(10), IF_RCV_DATE, 23) = CONVERT(CHAR(10), GETDATE(), 23)

			INSERT INTO #TEMP_XIF_OWMS_SHIP_RESULT_R_SN
			SELECT IF_SEQ, IF_ID, IF_RCV_DATE, PLANT_ID
			FROM XIF_OWMS_SHIP_RESULT_R_SN WITH(NOLOCK)
			WHERE CONVERT(CHAR(10), IF_RCV_DATE, 23) = CONVERT(CHAR(10), GETDATE(), 23)

			INSERT INTO #TEMP_XIF_OWMS_SHIP_RETURN_R_SN
			SELECT IF_SEQ, IF_ID, IF_RCV_DATE, PLANT_ID
			FROM XIF_OWMS_SHIP_RETURN_R_SN WITH(NOLOCK)
			WHERE CONVERT(CHAR(10), IF_RCV_DATE, 23) = CONVERT(CHAR(10), GETDATE(), 23)

			INSERT INTO #TEMP_XIF_OWMS_STOCK_R_SN
			SELECT IF_SEQ, IF_ID, IF_RCV_DATE, PLANT_ID
			FROM XIF_OWMS_STOCK_R_SN WITH(NOLOCK)
			WHERE CONVERT(CHAR(10), IF_RCV_DATE, 23) = CONVERT(CHAR(10), GETDATE(), 23)
*/
/* INF-R 적용 후 */


        INSERT
          INTO GT_SSPSMS_MES_FORMATION_LOT
        SELECT IF_SEQ
             , IF_ID
             , IF_RCV_DATE
             , NVL(B.NEW_VALUE1, A.PLANT_ID) AS PLANT_ID
          FROM XIF_MES_FORMATION_LOT_QMS_INSP_RESULT_R_SN A   /* 원본 WITH(NOLOCK): Oracle 은 읽기일관성이라 대응 힌트 없음 */
             , NERP_CONV_MASTER                            B   /* 원본 WITH(NOLOCK) */
         WHERE A.PLANT_ID = B.OLD_VALUE1(+)
           AND B.CODETYPE(+) = 'PLANT_ID'
           AND B.ATTRIBUTE5(+) IN ('1ST', '2ND')
           AND TO_CHAR(IF_RCV_DATE, 'YYYY-MM-DD') = TO_CHAR(SYSDATE, 'YYYY-MM-DD');

        INSERT
          INTO GT_SSPSMS_MES_ISS_WAIT_PALLET
        SELECT IF_SEQ
             , IF_ID
             , IF_RCV_DATE
             , NVL(B.NEW_VALUE1, A.PLANT_ID) AS PLANT_ID
          FROM XIF_MES_ISS_WAIT_PALLET_R_SN A   /* 원본 WITH(NOLOCK) */
             , NERP_CONV_MASTER              B   /* 원본 WITH(NOLOCK) */
         WHERE A.PLANT_ID = B.OLD_VALUE1(+)
           AND B.CODETYPE(+) = 'PLANT_ID'
           AND B.ATTRIBUTE5(+) IN ('1ST', '2ND')
           AND TO_CHAR(IF_RCV_DATE, 'YYYY-MM-DD') = TO_CHAR(SYSDATE, 'YYYY-MM-DD');

        INSERT
          INTO GT_SSPSMS_OWMS_SHIP_RESULT
        SELECT IF_SEQ
             , IF_ID
             , IF_RCV_DATE
             , NVL(B.NEW_VALUE1, A.PLANT_ID) AS PLANT_ID
          FROM XIF_OWMS_SHIP_RESULT_R_SN A   /* 원본 WITH(NOLOCK) */
             , NERP_CONV_MASTER           B   /* 원본 WITH(NOLOCK) */
         WHERE A.PLANT_ID = B.OLD_VALUE1(+)
           AND B.CODETYPE(+) = 'PLANT_ID'
           AND B.ATTRIBUTE5(+) IN ('1ST', '2ND')
           AND TO_CHAR(IF_RCV_DATE, 'YYYY-MM-DD') = TO_CHAR(SYSDATE, 'YYYY-MM-DD');

        INSERT
          INTO GT_SSPSMS_OWMS_SHIP_RETURN
        SELECT IF_SEQ
             , IF_ID
             , IF_RCV_DATE
             , NVL(B.NEW_VALUE1, A.PLANT_ID) AS PLANT_ID
          FROM XIF_OWMS_SHIP_RETURN_R_SN A   /* 원본 WITH(NOLOCK) */
             , NERP_CONV_MASTER           B   /* 원본 WITH(NOLOCK) */
         WHERE A.PLANT_ID = B.OLD_VALUE1(+)
           AND B.CODETYPE(+) = 'PLANT_ID'
           AND B.ATTRIBUTE5(+) IN ('1ST', '2ND')
           AND TO_CHAR(IF_RCV_DATE, 'YYYY-MM-DD') = TO_CHAR(SYSDATE, 'YYYY-MM-DD');

        INSERT
          INTO GT_SSPSMS_OWMS_STOCK
        SELECT IF_SEQ
             , IF_ID
             , IF_RCV_DATE
             , NVL(B.NEW_VALUE1, A.PLANT_ID) AS PLANT_ID
          FROM XIF_OWMS_STOCK_R_SN A   /* 원본 WITH(NOLOCK) */
             , NERP_CONV_MASTER     B   /* 원본 WITH(NOLOCK) */
         WHERE A.PLANT_ID = B.OLD_VALUE1(+)
           AND B.CODETYPE(+) = 'PLANT_ID'
           AND B.ATTRIBUTE5(+) IN ('1ST', '2ND')
           AND TO_CHAR(IF_RCV_DATE, 'YYYY-MM-DD') = TO_CHAR(SYSDATE, 'YYYY-MM-DD');


        IF (TO_CHAR(SYSDATE, 'HH24') = '09') THEN   /* 하루 1회 09시에만 수행함. */
        BEGIN
            /* ---------------------------------------------------------------------------------------------------------------- */
            /* MSSQL SUBSTRING(CONVERT(CHAR(23), IF_RCV_DATE, 21),12,5) : style 21 = 'yyyy-mm-dd hh:mi:ss.mmm' 의 12~16번째 = 'hh:mi'
               Oracle GTT IF_RCV_DATE 는 DATE(밀리초 없음)이라 'YYYY-MM-DD HH24:MI:SS' 로 포맷해도 12~16번째 문자는 동일 */
            SELECT COUNT(*)
              INTO N_CNT
              FROM GT_SSPSMS_MES_FORMATION_LOT
             /* WHERE PLANT_ID IN ('A010','G182') */
             WHERE SUBSTR(TO_CHAR(IF_RCV_DATE, 'YYYY-MM-DD HH24:MI:SS'), 12, 5) BETWEEN '06:00' AND '10:00';

            IF N_CNT < 1 THEN   /* 데이터가 존재하지 않는경우 */
                BEGIN
                    V_TEXT := NULL;
                    V_CODE := NULL;
                    V_TEXT := '[' || 'XIF_MES_FORMATION_LOT_QMS_INSP_RESULT_R_SN' || ']';
                    V_CODE := '67';

                    /* PRINT '===============================================';			*/
                    SCM_ADM_SMS_SEND_BATCH(V_CODE, V_TEXT);

                END;
            END IF;
            /* ---------------------------------------------------------------------------------------------------------------- */

            SELECT COUNT(*)
              INTO N_CNT
              FROM GT_SSPSMS_MES_ISS_WAIT_PALLET
             /* WHERE PLANT_ID IN ('A040', 'A050', 'G451', 'G631', 'G634') */
             WHERE SUBSTR(TO_CHAR(IF_RCV_DATE, 'YYYY-MM-DD HH24:MI:SS'), 12, 5) BETWEEN '06:00' AND '10:00';

            IF N_CNT < 1 THEN   /* 데이터가 존재하지 않는경우 */
                BEGIN
                    V_TEXT := NULL;
                    V_CODE := NULL;
                    V_TEXT := '[' || 'XIF_MES_ISS_WAIT_PALLET_R_SN' || ']';
                    V_CODE := '67';

                    /* --EXEC SCM_ADM_SMS_SEND_BATCH @v_code, @v_text */

                END;
            END IF;
            /* ---------------------------------------------------------------------------------------------------------------- */
            SELECT COUNT(*)
              INTO N_CNT
              FROM GT_SSPSMS_OWMS_SHIP_RESULT
             /* WHERE PLANT_ID IN ('A002', 'A010', 'A040', 'A050', 'G182', 'G182','G184','G451') */
             WHERE SUBSTR(TO_CHAR(IF_RCV_DATE, 'YYYY-MM-DD HH24:MI:SS'), 12, 5) BETWEEN '06:00' AND '10:00';

            IF N_CNT < 1 THEN   /* 데이터가 존재하지 않는경우 */
                BEGIN
                    V_TEXT := NULL;
                    V_CODE := NULL;
                    V_TEXT := '[' || 'XIF_OWMS_SHIP_RESULT_R_SN' || ']';
                    V_CODE := '67';

                    SCM_ADM_SMS_SEND_BATCH(V_CODE, V_TEXT);

                END;
            END IF;
            /* ---------------------------------------------------------------------------------------------------------------- */
            SELECT COUNT(*)
              INTO N_CNT
              FROM GT_SSPSMS_OWMS_SHIP_RETURN
             /* WHERE PLANT_ID IN ('A002', 'A010', 'A040', 'A050', 'G182', 'G182','G184','G451')
                  --AND SUBSTRING(CONVERT(CHAR(23), IF_RCV_DATE, 21),12,5)  LIKE '06:%' */
             WHERE SUBSTR(TO_CHAR(IF_RCV_DATE, 'YYYY-MM-DD HH24:MI:SS'), 12, 5) BETWEEN '06:00' AND '10:00';

            IF N_CNT < 1 THEN   /* 데이터가 존재하지 않는경우 */
                BEGIN
                    V_TEXT := NULL;
                    V_CODE := NULL;
                    V_TEXT := '[' || 'XIF_OWMS_SHIP_RETURN_R_SN' || ']';
                    V_CODE := '67';

                    SCM_ADM_SMS_SEND_BATCH(V_CODE, V_TEXT);

                END;
            END IF;
            /* ---------------------------------------------------------------------------------------------------------------- */
            /*			--IF (
			--	SELECT COUNT(*)
			--	FROM #TEMP_XIF_OWMS_STOCK_R_SN
			--	 --WHERE PLANT_ID IN ('A002', 'A010', 'A040', 'A050', 'G182', 'G182','G184','G451')
			--	WHERE SUBSTRING(CONVERT(CHAR(23), IF_RCV_DATE, 21),12,5)  BETWEEN '06:00' AND '10:00'
			--	) < 1  -- 데이터가 존재하지 않는경우
			--		BEGIN
			--			SET @v_text = ''
			--			SET @v_code = ''
			--			SET @v_text = N'[' + 'XIF_OWMS_STOCK_R_SN' + N']'
			--			SET @v_code = '67'

			--			EXEC SCM_ADM_SMS_SEND_BATCH @v_code, @v_text

			--		END
            */

            SELECT COUNT(*)
              INTO N_CNT
              FROM SCM_ADM_LOOKUP_MASTER_DETAIL
             WHERE 1 = 1
               AND LOOKUP_TYPE = 'IF_STOCK_CHECK'
               AND SEGMENT2 = 'OWMS'
               AND SEGMENT4 = V_C100   /* 'C100' */
               AND SEGMENT5 = TO_CHAR(SYSDATE, 'YYYYMMDD')
               AND DESCRIPTION = 'OWMS STOCK';

            IF N_CNT < 1 THEN   /* 데이터가 존재하지 않는경우 */
                BEGIN
                    V_TEXT := NULL;
                    V_CODE := NULL;
                    /* 							SET @v_text = N'[' + 'XIF_OWMS_STOCK_R_SN - C100' + N']' */

                    V_TEXT := CASE WHEN V_C100 IS NULL THEN NULL
                                   ELSE '[' || 'XIF_OWMS_STOCK_R_SN - ' || V_C100 || ']'
                              END;
                    V_CODE := '67';

                    SCM_ADM_SMS_SEND_BATCH(V_CODE, V_TEXT);

                END;
            END IF;

        END;
        END IF;

        IF (TO_CHAR(SYSDATE, 'HH24') = '11') THEN   /* 하루 1회 11시에만 수행함. */
        BEGIN
            SELECT COUNT(*)
              INTO N_CNT
              FROM SCM_ADM_LOOKUP_MASTER_DETAIL
             WHERE 1 = 1
               AND LOOKUP_TYPE = 'IF_STOCK_CHECK'
               AND SEGMENT2 = 'OWMS'
               AND SEGMENT4 = V_G180   /* 'G180' */
               AND SEGMENT5 = TO_CHAR(SYSDATE, 'YYYYMMDD')
               AND DESCRIPTION = 'OWMS STOCK';

            IF N_CNT < 1 THEN   /* 데이터가 존재하지 않는경우 */
                BEGIN
                    V_TEXT := NULL;
                    V_CODE := NULL;
                    /* 							SET @v_text = N'[' + 'XIF_OWMS_STOCK_R_SN - G180' + N']' */
                    V_TEXT := CASE WHEN V_G180 IS NULL THEN NULL
                                   ELSE '[' || 'XIF_OWMS_STOCK_R_SN - ' || V_G180 || ']'
                              END;
                    V_CODE := '67';

                    SCM_ADM_SMS_SEND_BATCH(V_CODE, V_TEXT);

                END;
            END IF;

            SELECT COUNT(*)
              INTO N_CNT
              FROM SCM_ADM_LOOKUP_MASTER_DETAIL
             WHERE 1 = 1
               AND LOOKUP_TYPE = 'IF_STOCK_CHECK'
               AND SEGMENT2 = 'OWMS'
               AND SEGMENT4 = V_G450   /* 'G450' */
               AND SEGMENT5 = TO_CHAR(SYSDATE, 'YYYYMMDD')
               AND DESCRIPTION = 'OWMS STOCK';

            IF N_CNT < 1 THEN   /* 데이터가 존재하지 않는경우 */
                BEGIN
                    V_TEXT := NULL;
                    V_CODE := NULL;
                    /* 							SET @v_text = N'[' + 'XIF_OWMS_STOCK_R_SN - G450' + N']' */
                    V_TEXT := CASE WHEN V_G450 IS NULL THEN NULL
                                   ELSE '[' || 'XIF_OWMS_STOCK_R_SN - ' || V_G450 || ']'
                              END;
                    V_CODE := '67';

                    SCM_ADM_SMS_SEND_BATCH(V_CODE, V_TEXT);

                END;
            END IF;

            SELECT COUNT(*)
              INTO N_CNT
              FROM SCM_ADM_LOOKUP_MASTER_DETAIL
             WHERE 1 = 1
               AND LOOKUP_TYPE = 'IF_STOCK_CHECK'
               AND SEGMENT2 = 'OWMS'
               AND SEGMENT4 = V_G630   /* 'G630' */
               AND SEGMENT5 = TO_CHAR(SYSDATE, 'YYYYMMDD')
               AND DESCRIPTION = 'OWMS STOCK';

            IF N_CNT < 1 THEN   /* 데이터가 존재하지 않는경우 */
                BEGIN
                    V_TEXT := NULL;
                    V_CODE := NULL;
                    /* 							SET @v_text = N'[' + 'XIF_OWMS_STOCK_R_SN - G630' + N']' */
                    V_TEXT := CASE WHEN V_G630 IS NULL THEN NULL
                                   ELSE '[' || 'XIF_OWMS_STOCK_R_SN - ' || V_G630 || ']'
                              END;
                    V_CODE := '67';

                    SCM_ADM_SMS_SEND_BATCH(V_CODE, V_TEXT);

                END;
            END IF;

        END;
        END IF;

        IF (TO_CHAR(SYSDATE, 'HH24') = '16') THEN   /* 하루 1회 16시에만 수행함. */
        BEGIN
            /* ---------------------------------------------------------------------------------------------------------------- */
            /*			--IF (
			--	SELECT COUNT(*)
			--	FROM #TEMP_XIF_MES_FORMATION_LOT_QMS_INSP_RESULT_R_SN
			--	--WHERE PLANT_ID IN ('A010')
			--	  --AND SUBSTRING(CONVERT(CHAR(23), IF_RCV_DATE, 21),12,5)  LIKE '14:%'
			--	WHERE SUBSTRING(CONVERT(CHAR(23), IF_RCV_DATE, 21),12,5)  BETWEEN '14:00' AND '16:00'
			--	) < 1  -- 데이터가 존재하지 않는경우
			--		BEGIN
			--			SET @v_text = ''
			--			SET @v_code = ''
			--			SET @v_text = N'[' + 'XIF_MES_FORMATION_LOT_QMS_INSP_RESULT_R_SN' + N']'
			--			SET @v_code = '67'

			--			EXEC SCM_ADM_SMS_SEND_BATCH @v_code, @v_text

			--		END
            */
            /* ---------------------------------------------------------------------------------------------------------------- */
            SELECT COUNT(*)
              INTO N_CNT
              FROM GT_SSPSMS_MES_ISS_WAIT_PALLET
             /* WHERE PLANT_ID IN ('G481')
                AND SUBSTRING(CONVERT(CHAR(23), IF_RCV_DATE, 21),12,5)  LIKE '06:%' */
             WHERE SUBSTR(TO_CHAR(IF_RCV_DATE, 'YYYY-MM-DD HH24:MI:SS'), 12, 5) BETWEEN '14:00' AND '16:00';

            IF N_CNT < 1 THEN   /* 데이터가 존재하지 않는경우 */
                BEGIN
                    V_TEXT := NULL;
                    V_CODE := NULL;
                    V_TEXT := '[' || 'XIF_MES_ISS_WAIT_PALLET_R_SN' || ']';
                    V_CODE := '67';

                    /* --EXEC SCM_ADM_SMS_SEND_BATCH @v_code, @v_text */

                END;
            END IF;
            /* ---------------------------------------------------------------------------------------------------------------- */
            SELECT COUNT(*)
              INTO N_CNT
              FROM GT_SSPSMS_OWMS_SHIP_RESULT
             /* WHERE PLANT_ID IN ('G481') */
             WHERE SUBSTR(TO_CHAR(IF_RCV_DATE, 'YYYY-MM-DD HH24:MI:SS'), 12, 5) BETWEEN '14:00' AND '16:00';

            IF N_CNT < 1 THEN   /* 데이터가 존재하지 않는경우 */
                BEGIN
                    V_TEXT := NULL;
                    V_CODE := NULL;
                    V_TEXT := '[' || 'XIF_OWMS_SHIP_RESULT_R_SN' || ']';
                    V_CODE := '67';

                    SCM_ADM_SMS_SEND_BATCH(V_CODE, V_TEXT);

                END;
            END IF;
            /* ---------------------------------------------------------------------------------------------------------------- */
            SELECT COUNT(*)
              INTO N_CNT
              FROM GT_SSPSMS_OWMS_SHIP_RETURN
             /* WHERE PLANT_ID IN ('G481') */
             WHERE SUBSTR(TO_CHAR(IF_RCV_DATE, 'YYYY-MM-DD HH24:MI:SS'), 12, 5) BETWEEN '14:00' AND '16:00';

            IF N_CNT < 1 THEN   /* 데이터가 존재하지 않는경우 */
                BEGIN
                    V_TEXT := NULL;
                    V_CODE := NULL;
                    V_TEXT := '[' || 'XIF_OWMS_SHIP_RETURN_R_SN' || ']';
                    V_CODE := '67';

                    SCM_ADM_SMS_SEND_BATCH(V_CODE, V_TEXT);

                END;
            END IF;
            /* ---------------------------------------------------------------------------------------------------------------- */
            /*			--IF (
			--	SELECT COUNT(*)
			--	FROM #TEMP_XIF_OWMS_STOCK_R_SN
			--	--WHERE PLANT_ID IN ('A002', 'A010', 'A040', 'A050', 'G182', 'G182','G184','G451')
			--	WHERE SUBSTRING(CONVERT(CHAR(23), IF_RCV_DATE, 21),12,5)  BETWEEN '14:00' AND '16:00'
			--	) < 1  -- 데이터가 존재하지 않는경우
			--		BEGIN
			--			SET @v_text = ''
			--			SET @v_code = ''
			--			SET @v_text = N'[' + 'XIF_OWMS_STOCK_R_SN' + N']'
			--			SET @v_code = '67'

			--			EXEC SCM_ADM_SMS_SEND_BATCH @v_code, @v_text

			--		END
            */

            SELECT COUNT(*)
              INTO N_CNT
              FROM SCM_ADM_LOOKUP_MASTER_DETAIL
             WHERE 1 = 1
               AND LOOKUP_TYPE = 'IF_STOCK_CHECK'
               AND SEGMENT2 = 'OWMS'
               AND SEGMENT4 = V_G480   /* 'G480' */
               AND SEGMENT5 = TO_CHAR(SYSDATE, 'YYYYMMDD')
               AND DESCRIPTION = 'OWMS STOCK';

            IF N_CNT < 1 THEN   /* 데이터가 존재하지 않는경우 */
                BEGIN
                    V_TEXT := NULL;
                    V_CODE := NULL;
                    /* 							SET @v_text = N'[' + 'XIF_OWMS_STOCK_R_SN - G480' + N']' */
                    V_TEXT := CASE WHEN V_G480 IS NULL THEN NULL
                                   ELSE '[' || 'XIF_OWMS_STOCK_R_SN - ' || V_G480 || ']'
                              END;
                    V_CODE := '67';

                    SCM_ADM_SMS_SEND_BATCH(V_CODE, V_TEXT);

                END;
            END IF;

        END;
        END IF;

        IF (TO_CHAR(SYSDATE, 'HH24') = '22') THEN   /* 하루 1회 22시에만 수행함. */
        BEGIN
            /* ---------------------------------------------------------------------------------------------------------------- */
            SELECT COUNT(*)
              INTO N_CNT
              FROM GT_SSPSMS_MES_ISS_WAIT_PALLET
             /* WHERE PLANT_ID IN ('G382') */
             WHERE SUBSTR(TO_CHAR(IF_RCV_DATE, 'YYYY-MM-DD HH24:MI:SS'), 12, 5) BETWEEN '20:00' AND '22:00';

            IF N_CNT < 1 THEN   /* 데이터가 존재하지 않는경우 */
                BEGIN
                    V_TEXT := NULL;
                    V_CODE := NULL;
                    V_TEXT := '[' || 'XIF_MES_ISS_WAIT_PALLET_R_SN' || ']';
                    V_CODE := '67';

                    /* --EXEC SCM_ADM_SMS_SEND_BATCH @v_code, @v_text */

                END;
            END IF;
            /* ---------------------------------------------------------------------------------------------------------------- */
            SELECT COUNT(*)
              INTO N_CNT
              FROM GT_SSPSMS_OWMS_SHIP_RESULT
             /* WHERE PLANT_ID IN ('G382') */
             WHERE SUBSTR(TO_CHAR(IF_RCV_DATE, 'YYYY-MM-DD HH24:MI:SS'), 12, 5) BETWEEN '20:00' AND '22:00';

            IF N_CNT < 1 THEN   /* 데이터가 존재하지 않는경우 */
                BEGIN
                    V_TEXT := NULL;
                    V_CODE := NULL;
                    V_TEXT := '[' || 'XIF_OWMS_SHIP_RESULT_R_SN' || ']';
                    V_CODE := '67';

                    SCM_ADM_SMS_SEND_BATCH(V_CODE, V_TEXT);

                END;
            END IF;
            /* ---------------------------------------------------------------------------------------------------------------- */

            SELECT COUNT(*)
              INTO N_CNT
              FROM GT_SSPSMS_OWMS_SHIP_RETURN
             /* WHERE PLANT_ID IN ('G481') */
             WHERE SUBSTR(TO_CHAR(IF_RCV_DATE, 'YYYY-MM-DD HH24:MI:SS'), 12, 5) BETWEEN '20:00' AND '22:00';

            IF N_CNT < 1 THEN   /* 데이터가 존재하지 않는경우 */
                BEGIN
                    V_TEXT := NULL;
                    V_CODE := NULL;
                    V_TEXT := '[' || 'XIF_OWMS_SHIP_RETURN_R_SN' || ']';
                    V_CODE := '67';

                    SCM_ADM_SMS_SEND_BATCH(V_CODE, V_TEXT);

                END;
            END IF;
            /* ---------------------------------------------------------------------------------------------------------------- */

            /*			--IF (
			--	SELECT COUNT(*)
			--	FROM #TEMP_XIF_OWMS_STOCK_R_SN
			--	 --WHERE PLANT_ID IN ('A002', 'A010', 'A040', 'A050', 'G182', 'G182','G184','G451')
			--	WHERE SUBSTRING(CONVERT(CHAR(23), IF_RCV_DATE, 21),12,5)  BETWEEN '20:00' AND '22:00'
			--	) < 1  -- 데이터가 존재하지 않는경우
			--		BEGIN
			--			SET @v_text = ''
			--			SET @v_code = ''
			--			SET @v_text = N'[' + 'XIF_OWMS_STOCK_R_SN' + N']'
			--			SET @v_code = '67'

			--			EXEC SCM_ADM_SMS_SEND_BATCH @v_code, @v_text

			--		END
            */

            SELECT COUNT(*)
              INTO N_CNT
              FROM SCM_ADM_LOOKUP_MASTER_DETAIL
             WHERE 1 = 1
               AND LOOKUP_TYPE = 'IF_STOCK_CHECK'
               AND SEGMENT2 = 'OWMS'
               AND SEGMENT4 = V_G380   /* 'G380' */
               AND SEGMENT5 = TO_CHAR(SYSDATE, 'YYYYMMDD')
               AND DESCRIPTION = 'OWMS STOCK';

            IF N_CNT < 1 THEN   /* 데이터가 존재하지 않는경우 */
                BEGIN
                    V_TEXT := NULL;
                    V_CODE := NULL;
                    /* 							SET @v_text = N'[' + 'XIF_OWMS_STOCK_R_SN - G380' + N']' */
                    V_TEXT := CASE WHEN V_G380 IS NULL THEN NULL
                                   ELSE '[' || 'XIF_OWMS_STOCK_R_SN - ' || V_G380 || ']'
                              END;
                    V_CODE := '67';

                    SCM_ADM_SMS_SEND_BATCH(V_CODE, V_TEXT);

                END;
            END IF;

        END;
        END IF;

      END;


    EXCEPTION

      WHEN OTHERS THEN

        /* ERROR LOG */
        V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);

        INSERT
          INTO SCM_SYS_LOG_BATCH
             ( PROGRAM_NAME
             , LOG_TYPE
             , LOG_COUNT
             , LOG_MESSAGE
             , DESCRIPTION
             , EVENT_DATE
             , CREATION_DATE
             , CREATED_BY
             , LAST_UPDATE_DATE
             , LAST_UPDATED_BY )
        VALUES ( V_PROGRAM_NAME
               , 'ERROR'
               , NULL
               , V_LOG_MESSAGE
               , NULL
               , SYSDATE
               , SYSDATE
               , V_PROGRAM_NAME
               , SYSDATE
               , V_PROGRAM_NAME );


        COMMIT;

        /* 원본 CATCH 는 RAISERROR/THROW 없이 return -1 로 종료(예외 삼킴·호출자 전파 없음·종료LOG 생략)
           → Oracle 도 RAISE 없이 RETURN 으로 동일 재현(호출자 0건 = SQL Agent 잡이 반환코드를 받지 않음) */
        RETURN;

    END;

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := NULL;
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);


    COMMIT;

    /* return 1 (MSSQL 반환코드 — Oracle 프로시저는 반환값 없음) */

  END PR_SSP_IF_CHECK_SMS_SEND;

PROCEDURE PR_SSP_INT_SYSTEMEXEC_RUNJOB
(
    P_JOBID    IN VARCHAR2 DEFAULT ''
)
AS
/***************************************************************************************************
 * Program ID   : PR_SSP_INT_SYSTEMEXEC_RUNJOB
 * Description  :
 * OutTable     :
 * Execute      : EXEC PR_SSP_INT_SYSTEMEXEC_RUNJOB
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2021.10.01   SSP Pjt.       Create.
 * 2026.07.06   ZIONEX         [PJ202650304] NextSCM Migration
 ***************************************************************************************************/

    /* 선언 */
    V_EXECRSLTCODE     VARCHAR2(50 CHAR);
    V_EXECDTTM         DATE;
    V_EXECDTTM2        DATE;
    V_NEXTEXECDTTM     DATE;
    V_INQUIRYSTARTDTTM DATE;
    V_INQUIRYENDDTTM   DATE;
    V_ERRMSG           VARCHAR2(3000 CHAR);

    C_JOBID            VARCHAR2(50 CHAR);
    C_SPNAME           VARCHAR2(50 CHAR);
    C_EXECCLCVAL       VARCHAR2(50 CHAR);
    C_EXECCLCTYPE      VARCHAR2(50 CHAR);
    C_EXECSTAT         VARCHAR2(50 CHAR);
    C_FIRSTEXECDTTM    DATE;
    C_LTSEXECDTTM      DATE;
    C_NEXTEXECDTTM     DATE;
    C_INQUIRYSTARTDTTM DATE;
    C_INQUIRYENDDTTM   DATE;

    O_ERRFLAG          VARCHAR2(50 CHAR);
    O_ERRDESC          VARCHAR2(3000 CHAR);

    /*****************************************************************************************************************
    *-- 배치 조회
    *--    시스템 예약 실행 테이블에서 실행 중에 있지 않고 다음 실행 일시가 현재 시각보다 이전인 목록을 조회
    *--    SSP_INT_SYSTEMEXE.EXECSTAT의 값이 'Y'이면 실행 중, 'N'이면 대기 중임.
    *--    실행 중(EXECSTAT = 'Y')이어도 NEXTEXECDTTM(다음 실행 일시)의 값이 현 시점을 30분 초과하였으면
    *--    비정상 종료(실행 중일 때 윈도우 서비스 중단, 타임 아웃 등)되었던 것으로 판단하여 실행 대상에 포함함.
    *--    정상 실행 중인 경우라면 BizActor의 Timeout 설정, DB의 Timeout 설정 등에 의해
    *--    다음 실행 일시를 30분 초과하여 실행 중일 수 없다고 전제함 (Timeout 시간은 설정에 따라 다를 수 있음).
    ******************************************************************************************************************/
    CURSOR CUR_SYSTEMEXEC_RUN IS
    SELECT JOBID
         , SPNAME
         , EXECCLCVAL
         , EXECCLCTYPE
         , EXECSTAT
         , FIRSTEXECDTTM
         , LTSEXECDTTM
         , NVL(NEXTEXECDTTM, SYSDATE) AS NEXTEXECDTTM
         , INQUIRYSTARTDTTM
         , INQUIRYENDDTTM
      FROM SSP_INT_SYSTEMEXE
     WHERE USEYN = 'Y'
       AND CASE WHEN EXECSTAT = 'N' THEN 'Y'
                WHEN EXECSTAT = 'Y' AND (TRUNC(SYSDATE, 'MI') - TRUNC(NEXTEXECDTTM, 'MI')) * 1440 > 30 THEN 'Y'
                END = 'Y'
       AND CASE WHEN NEXTEXECDTTM <= SYSDATE THEN 'Y'
                WHEN NEXTEXECDTTM IS NULL THEN 'Y'
                END = 'Y'
       AND JOBID LIKE P_JOBID || '%'
       AND SP_GROUP = 'SSP'
     ORDER BY ORDER_NUM;

BEGIN

    /* 선처리 */


    /* 본처리 */
    OPEN CUR_SYSTEMEXEC_RUN;

    C_JOBID            := NULL;
    C_SPNAME           := NULL;
    C_EXECCLCVAL       := NULL;
    C_EXECCLCTYPE      := NULL;
    C_EXECSTAT         := NULL;
    C_INQUIRYSTARTDTTM := NULL;
    C_INQUIRYENDDTTM   := NULL;
    O_ERRFLAG          := NULL;
    O_ERRDESC          := NULL;

    FETCH CUR_SYSTEMEXEC_RUN
     INTO C_JOBID
         , C_SPNAME
         , C_EXECCLCVAL
         , C_EXECCLCTYPE
         , C_EXECSTAT
         , C_FIRSTEXECDTTM
         , C_LTSEXECDTTM
         , C_NEXTEXECDTTM
         , C_INQUIRYSTARTDTTM
         , C_INQUIRYENDDTTM;

    WHILE (CUR_SYSTEMEXEC_RUN%FOUND)
    LOOP
        V_EXECRSLTCODE     := 'F';
        V_EXECDTTM         := SYSDATE;
        V_NEXTEXECDTTM     := NULL;
        V_INQUIRYSTARTDTTM := NULL;
        V_INQUIRYENDDTTM   := NULL;
        V_ERRMSG           := '';

        /* 1) 다음 실행 일시 */
        V_NEXTEXECDTTM := FN_GET_SSP_INT_JOBNEXTTIME(C_EXECCLCVAL, C_EXECCLCTYPE, V_EXECDTTM, C_FIRSTEXECDTTM);

        /* 2) 현재 실행 일시 변경 */
        UPDATE SSP_INT_SYSTEMEXE
           SET EXECSTAT    = 'Y'
             , CUREXECDTTM = V_EXECDTTM
         WHERE JOBID = C_JOBID;

        /* 3) 프로시저 실행 */
        EXECUTE IMMEDIATE 'BEGIN ' || C_SPNAME || '(:1, :2, :3); END;'
                    USING IN C_JOBID, OUT O_ERRFLAG, OUT O_ERRDESC;

        V_EXECRSLTCODE := CASE WHEN O_ERRFLAG = 'N'   THEN 'S'
                               WHEN O_ERRFLAG IS NULL THEN 'S'
                               ELSE 'F'
                          END;
        V_ERRMSG    := O_ERRDESC;
        V_EXECDTTM2 := SYSDATE;

        /* 4) 실행결과 변경 */
        IF V_EXECRSLTCODE = 'S'
        THEN
            SELECT INQUIRYSTARTDTTM
                 , INQUIRYENDDTTM
              INTO V_INQUIRYSTARTDTTM
                 , V_INQUIRYENDDTTM
              FROM SSP_INT_SYSTEMEXE
             WHERE JOBID = C_JOBID;

            UPDATE SSP_INT_SYSTEMEXE
               SET EXECSTAT      = 'N'
                 , FIRSTEXECDTTM = NVL(FIRSTEXECDTTM, V_EXECDTTM2)
                 , LTSEXECDTTM   = V_EXECDTTM
                 , CUREXECDTTM   = NULL
                 , NEXTEXECDTTM  = V_NEXTEXECDTTM
                 , UPDUSERID     = 'ssp_batch'
                 , UPDDTTM       = V_EXECDTTM2
             WHERE JOBID = C_JOBID;

        ELSE
            V_INQUIRYSTARTDTTM := C_INQUIRYENDDTTM;
            V_INQUIRYENDDTTM   := NULL;
        END IF;

        /* 5) 실행로그 기록 */
        PR_SSP_INT_SYSTEMEXECLOG(C_JOBID
                                , V_EXECDTTM
                                , V_EXECDTTM2
                                , V_EXECRSLTCODE
                                , V_ERRMSG
                                , V_INQUIRYSTARTDTTM
                                , V_INQUIRYENDDTTM);

        FETCH CUR_SYSTEMEXEC_RUN
         INTO C_JOBID
             , C_SPNAME
             , C_EXECCLCVAL
             , C_EXECCLCTYPE
             , C_EXECSTAT
             , C_FIRSTEXECDTTM
             , C_LTSEXECDTTM
             , C_NEXTEXECDTTM
             , C_INQUIRYSTARTDTTM
             , C_INQUIRYENDDTTM;
    END LOOP;

    CLOSE CUR_SYSTEMEXEC_RUN;


    /* 후처리 */


    COMMIT;

    RETURN;
END;

PROCEDURE PR_SSP_MAIL_SEND_ADJUST_SUB
(
    P_TO_MAIL           IN  VARCHAR2
   ,P_SUBJECT           IN  VARCHAR2
   ,P_BODY_CONTENTS     IN  CLOB
   ,P_HTML_YN           IN  VARCHAR2
)
IS
/*
 * Program ID   : PR_SSP_MAIL_SEND_ADJUST_SUB
 * Description  : MAIL 발송
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2019/11/26   KIMYONGHO      최초작성
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 */
    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME  VARCHAR2(150 CHAR) := 'PR_SSP_MAIL_SEND_ADJUST_SUB';
    V_LOG_TYPE      VARCHAR2(30 CHAR);                                          /* START/END/ERROR/... */
    N_LOG_COUNT     NUMBER := 0;
    V_LOG_MESSAGE   VARCHAR2(1000 CHAR);
    V_DESCRIPTION   VARCHAR2(500 CHAR);
    D_EVENT_DATE    DATE;
    V_TO_MAIL       VARCHAR2(150 CHAR);
BEGIN

    /* 시작 LOG */
    V_LOG_TYPE := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    V_TO_MAIL := '';
    V_TO_MAIL := P_TO_MAIL;

    /* 원문은 발송 방식이 데이터베이스 내장 기능이라 기준 데이터베이스의 공용 발송 프로시저로 옮긴다 */
    IF (P_HTML_YN = 'Y') THEN
        SCM_ADM_MAIL_SEND(P_TO_MAIL, P_SUBJECT, P_BODY_CONTENTS, 'Y');
    ELSE
        SCM_ADM_MAIL_SEND(V_TO_MAIL, P_SUBJECT, P_BODY_CONTENTS, 'N');
    END IF;

    V_LOG_TYPE := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

EXCEPTION
    WHEN OTHERS THEN
        /* AS-IS CATCH 는 이력만 남기고 확정한다 — 부르는 쪽으로 오류를 넘기지 않는다 */
        PR_SSP_LOG_ERROR(V_PROGRAM_NAME, SUBSTR(SQLERRM, 1, 1000));

END PR_SSP_MAIL_SEND_ADJUST_SUB;

PROCEDURE PR_SSP_MAIL_SEND_BOD_REGISTRATION
(
    P_CATEGORY_ID   IN NUMBER
)
/*
 * Program ID   : PR_SSP_MAIL_SEND_BOD_REGISTRATION
 * Description  : MAIL 발송
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2021-06-18   KIMYONGHO      신규추가
 * 2026.07.06   ZIONEX  [PJ202650304]  NextSCM Migration
 */
AS
    V_RESULT            CLOB;
    V_RESULT2           CLOB;
    V_RESULT3           CLOB;
    V_RESULT4           CLOB;
    V_RESULT5           CLOB;
    V_TO_MAIL           VARCHAR2(4000 CHAR);
    V_HEAD_CONT         VARCHAR2(32767 CHAR);
    V_BODY_CONT         VARCHAR2(32767 CHAR);
    V_BODY_CONT_TEMP    VARCHAR2(32767 CHAR);
    V_TABLE_BODY        CLOB;
    V_MAIL_RECEIVER_LIST VARCHAR2(4000 CHAR);

    V_USE_TYPE_CODE     VARCHAR2(10 CHAR);
    V_SEGMENT1          VARCHAR2(100 CHAR);
    V_SEGMENT2          VARCHAR2(100 CHAR);
    V_SEGMENT3          VARCHAR2(100 CHAR);
    V_SEGMENT4          VARCHAR2(100 CHAR);
    V_SEGMENT5          VARCHAR2(100 CHAR);
    V_SEGMENT6          VARCHAR2(100 CHAR);
    V_SEGMENT7          VARCHAR2(100 CHAR);
    V_SEGMENT8          VARCHAR2(100 CHAR);
    V_SEGMENT9          VARCHAR2(100 CHAR);
    V_SEGMENT10         VARCHAR2(100 CHAR);
    V_COLUMN1           VARCHAR2(100 CHAR);
    V_COLUMN2           VARCHAR2(100 CHAR);
    V_COLUMN3           VARCHAR2(100 CHAR);
    V_COLUMN4           VARCHAR2(100 CHAR);
    V_COLUMN5           VARCHAR2(100 CHAR);
    V_COLUMN6           VARCHAR2(100 CHAR);
    V_COLUMN7           VARCHAR2(100 CHAR);
    V_COLUMN8           VARCHAR2(100 CHAR);
    V_COLUMN9           VARCHAR2(100 CHAR);
    V_COLUMN10          VARCHAR2(100 CHAR);
    V_USER_ID           VARCHAR2(150 CHAR);
    V_USER_NAME         VARCHAR2(300 CHAR);
    V_MOBILE_PHONE      VARCHAR2(60 CHAR);
    V_LANGUAGE_CODE     VARCHAR2(200 CHAR);
    V_EMAIL_ADDR        VARCHAR2(300 CHAR);
    V_FROM_MAIL         VARCHAR2(100 CHAR);
    V_FROM_PHONE        VARCHAR2(100 CHAR);
    V_PHONE_ADDR        VARCHAR2(100 CHAR);
    V_MAIL_TITLE        VARCHAR2(100 CHAR);
    V_USER_CNT          NUMBER;
    V_RANK              NUMBER;
    V_BODY_CONTENTS     CLOB;
    V_MESSAGE           CLOB;
    V_DETAIL_FLAG       VARCHAR2(1 CHAR);
    V_SQL_LONG_TEXT     VARCHAR2(4000 CHAR);
    V_CHECK             INTEGER;
    V_SQL_YN            VARCHAR2(1 CHAR);
    V_RECEIVER_TEMP     VARCHAR2(150 CHAR);

    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME      VARCHAR2(150 CHAR) := 'PR_SSP_MAIL_SEND_BOD_REGISTRATION';
    V_LOG_TYPE          VARCHAR2(30 CHAR);    /* START/END/ERROR/... */
    N_LOG_COUNT         INTEGER := 0;
    V_LOG_MESSAGE       VARCHAR2(1000 CHAR);
    V_DESCRIPTION       VARCHAR2(500 CHAR);
    D_EVENT_DATE        DATE;
    V_ERROR_MESSAGE     VARCHAR2(1000 CHAR);
BEGIN

    /********************************************************************************
    * 임시테이블(GTT) 초기화 (원본 #TblMailSendBatch DROP/CREATE -> GT_MAIL_BOD_REG DELETE)
    ********************************************************************************/
    DELETE FROM GT_MAIL_BOD_REG;


    SELECT COLUMN_VALUE
      INTO V_RESULT
      FROM TABLE(FN_SCM_ADM_GET_MAIL_SQL(P_CATEGORY_ID))
     WHERE ROWNUM = 1;

    /* EXEC @v_result; */

    /*       - a.SQL_LONG_TEXT(19c CLOB) 를 DBMS_LOB.SUBSTR(,4000,1)로 캡: 상위 SELECT DISTINCT z.* 가 */
    V_RESULT4 :=
'  SELECT DISTINCT z.* '||CHR(10)||
'     ,COUNT(user_id) over ( PARTITION BY  user_id ) user_cnt '||CHR(10)||
'      ,dense_rank() over( PARTITION BY  user_id ORDER BY user_id, segment1, segment2, segment3, segment4, segment5) rank '||CHR(10)||
'  FROM ( '||CHR(10)||
'  SELECT x.use_type_code '||CHR(10)||
'      , y.user_id '||CHR(10)||
'      , y.user_name '||CHR(10)||
'      , y.email_addr '||CHR(10)||
'      , y.mobile_phone '||CHR(10)||
'      ,x.language_code '||CHR(10)||
'      ,y.segment1 '||CHR(10)||
'      ,y.segment2 '||CHR(10)||
'      ,y.segment3 '||CHR(10)||
'      ,y.segment4 '||CHR(10)||
'      ,y.segment5 '||CHR(10)||
'      ,y.column1 '||CHR(10)||
'      ,y.column2 '||CHR(10)||
'      ,y.column3 '||CHR(10)||
'      ,y.column4 '||CHR(10)||
'      ,y.column5 '||CHR(10)||
'      ,x.mail_title '||CHR(10)||
'      ,x.body_contents '||CHR(10)||
'      ,x.sql_long_text '||CHR(10)||
'  FROM ('||V_RESULT||') y, '||CHR(10)||
'      ( SELECT a.use_type_code '||CHR(10)||
'              ,c.user_id '||CHR(10)||
'              ,e.UserName as user_name '||CHR(10)||
'              ,e.Email as email_addr '||CHR(10)||
'              ,e.CellPhoneNum as mobile_phone '||CHR(10)||
'              ,b.language_code '||CHR(10)||
'              ,b.mail_title '||CHR(10)||
'              ,d.SEGMENT3       header_contents '||CHR(10)||
'              ,CASE A.USE_TYPE_CODE WHEN ''MAIL'' THEN replace(b.message_content,chr(10),''<br><br>'') '||CHR(10)||
'                                    WHEN ''SMS'' THEN b.message_content END body_contents '||CHR(10)||
'              ,d.SEGMENT3      foot_contents '||CHR(10)||
'              ,DBMS_LOB.SUBSTR(a.SQL_LONG_TEXT,4000,1) SQL_LONG_TEXT '||CHR(10)||
'          FROM SCM_ADM_RECIPIENT_LIST a '||CHR(10)||
'              INNER JOIN SCM_ADM_RECIPIENT_MESSAGE b ON a.CATEGORY_ID = B.CATEGORY_ID '||CHR(10)||
'              LEFT OUTER JOIN SCM_ADM_RECIPIENT_ASSIGN c ON B.CATEGORY_ID = C.CATEGORY_ID  '||CHR(10)||
'              INNER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL d ON D.SEGMENT1 = B.LANGUAGE_CODE AND D.LOOKUP_TYPE = ''MAIL_HEADER_FOOT'' AND D.VALID_YN = ''Y''  '||CHR(10)||
'              LEFT OUTER JOIN TB_FX_User e ON B.LANGUAGE_CODE = E.Language AND C.USER_ID = E.UserID '||CHR(10)||
'          WHERE a.category_id   = '||TO_CHAR(P_CATEGORY_ID)||CHR(10)||
'              AND a.VALID_YN = ''Y'' '||CHR(10)||
'          ) x '||CHR(10)||
'      WHERE x.language_code = y.language_code   '||CHR(10)||
'     union all   '||CHR(10)||
'  SELECT x.use_type_code '||CHR(10)||
'      , x.user_id '||CHR(10)||
'      , x.user_name '||CHR(10)||
'      , x.email_addr '||CHR(10)||
'      , x.mobile_phone '||CHR(10)||
'      ,x.language_code '||CHR(10)||
'      ,y.segment1 '||CHR(10)||
'      ,y.segment2 '||CHR(10)||
'      ,y.segment3 '||CHR(10)||
'      ,y.segment4 '||CHR(10)||
'      ,y.segment5 '||CHR(10)||
'      ,y.column1 '||CHR(10)||
'      ,y.column2 '||CHR(10)||
'      ,y.column3 '||CHR(10)||
'      ,y.column4 '||CHR(10)||
'      ,y.column5 '||CHR(10)||
'      ,x.mail_title '||CHR(10)||
'      ,x.body_contents '||CHR(10)||
'      ,x.sql_long_text '||CHR(10)||
'  FROM ('||V_RESULT||') y, '||CHR(10)||
'      ( SELECT a.use_type_code '||CHR(10)||
'              ,c.user_id '||CHR(10)||
'              ,e.UserName as user_name '||CHR(10)||
'              ,e.Email as email_addr '||CHR(10)||
'              ,e.CellPhoneNum as mobile_phone '||CHR(10)||
'              ,b.language_code '||CHR(10)||
'              ,b.mail_title '||CHR(10)||
'              ,d.SEGMENT3       header_contents '||CHR(10)||
'              ,CASE A.USE_TYPE_CODE WHEN ''MAIL'' THEN replace(b.message_content,chr(10),''<br><br>'') '||CHR(10)||
'                                    WHEN ''SMS'' THEN b.message_content END body_contents '||CHR(10)||
'              ,d.SEGMENT3      foot_contents '||CHR(10)||
'              ,DBMS_LOB.SUBSTR(a.SQL_LONG_TEXT,4000,1) SQL_LONG_TEXT '||CHR(10)||
