'      WHERE x.language_code = y.language_code   '||CHR(10)||
'      ) z order by user_id '||CHR(10);


    EXECUTE IMMEDIATE 'INSERT INTO GT_MAIL_BOD_REG ( USE_TYPE_CODE, USER_ID, USER_NAME, EMAIL_ADDR, MOBILE_PHONE, LANGUAGE_CODE'
