        --			SET @v_body_contents = ''
        --			SET @v_check = 0
        --			SET @v_body_cont_temp = ''
        --			--MAIL 발송 LOG 저장
        --			EXEC SCM_ADM_SAVE_MAIL_SEND_BATCH_LOG @v_use_type_code
        --							,@p_category_id
