END;

PROCEDURE PR_SSP_MAIL_SEND_DELEGATE
(
    P_TYPE          IN  VARCHAR2
  , P_DIVISIONID    IN  VARCHAR2
  , P_DELEGATOR     IN  VARCHAR2
  , P_DELEGATEE     IN  VARCHAR2
  , P_FROM_DATE     IN  VARCHAR2
  , P_TO_DATE       IN  VARCHAR2
  , P_LANGUAGE      IN  VARCHAR2 DEFAULT 'KO'
  , P_HTML_YN       IN  VARCHAR2
)
IS
/*
 * Program ID   : PR_SSP_MAIL_SEND_DELEGATE
 * Description  : DELEGATE MAIL 발송
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2019/07/15   mcTheJ         [CSR ID:4044806] Model PIC 담당자 위임 기능 추가
 * 2026.09.27   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 *
 * 원문은 발송 방식이 데이터베이스 내장 기능이라 기준 데이터베이스의 공용 발송 프로시저로 옮긴다
 * (같은 계열 PR_SSP_MAIL_SEND_ADJUST_SUB 와 같은 방식).
 */
    C_DELIMITER             CONSTANT VARCHAR2(1 CHAR) := '^';

    V_TITLE                 VARCHAR2(1000 CHAR);
    V_CONTENTS              VARCHAR2(4000 CHAR);
    V_TABLE_BODY            VARCHAR2(32767 CHAR);

    V_DELEGATOR_MAIL        VARCHAR2(600 CHAR);
    V_DELEGATEE_MAIL        VARCHAR2(600 CHAR);

    V_DELEGATOR             VARCHAR2(1000 CHAR);
    V_DELEGATEE             VARCHAR2(1000 CHAR);

    V_FROM_DATE             VARCHAR2(10 CHAR);
    V_TO_DATE               VARCHAR2(10 CHAR);

    V_DIVISION_ID           VARCHAR2(4000 CHAR);
    V_MAIL_DIVISION_ID      VARCHAR2(4000 CHAR) := '';

    V_MAX_LOOP_CNT          NUMBER(10) := 0;
    V_MST_LOOP_CNT          NUMBER(10) := 0;

    V_PROGRAM_NAME          VARCHAR2(150 CHAR) := 'PR_SSP_MAIL_SEND_DELEGATE';
    V_LOG_TYPE              VARCHAR2(30 CHAR);
    N_LOG_COUNT             NUMBER(10) := 0;
    V_LOG_MESSAGE           VARCHAR2(1000 CHAR);
    V_DESCRIPTION           VARCHAR2(500 CHAR);
    D_EVENT_DATE            DATE;
BEGIN

    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    V_DELEGATOR_MAIL := P_DELEGATOR || '@lgensol.com';
    V_DELEGATEE_MAIL := P_DELEGATEE || '@lgensol.com';

    BEGIN
/* 2026.09.30 AJS 수정 (START) */
--        SELECT CASE WHEN P_LANGUAGE = 'KO' THEN A.USERNAME ELSE A.USERNAME_E END || '(' || P_DELEGATOR || ')'
        SELECT CASE WHEN P_LANGUAGE = 'KO' THEN A.USER_NM ELSE A.USER_ENG_NM END || '(' || P_DELEGATOR || ')'
/* 2026.09.30 AJS 수정 (END) */
          INTO V_DELEGATOR
/* 2026.09.30 AJS 수정 (START) */
--          FROM TB_FX_USER A
--         WHERE A.USERID = P_DELEGATOR
--           AND A.USEYN  = 'Y'
          FROM SCM_ADM_USER_M A
         WHERE A.USER_ID = P_DELEGATOR
           AND A.USE_YN = 'Y'
/* 2026.09.30 AJS 수정 (END) */
           AND ROWNUM   = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN V_DELEGATOR := '';
    END;

    BEGIN
/* 2026.09.30 AJS 수정 (START) */
--        SELECT CASE WHEN P_LANGUAGE = 'KO' THEN A.USERNAME ELSE A.USERNAME_E END || '(' || P_DELEGATEE || ')'
        SELECT CASE WHEN P_LANGUAGE = 'KO' THEN A.USER_NM ELSE A.USER_ENG_NM END || '(' || P_DELEGATEE || ')'
/* 2026.09.30 AJS 수정 (END) */
          INTO V_DELEGATEE
/* 2026.09.30 AJS 수정 (START) */
--          FROM TB_FX_USER A
--         WHERE A.USERID = P_DELEGATEE
--           AND A.USEYN  = 'Y'
          FROM SCM_ADM_USER_M A
         WHERE A.USER_ID = P_DELEGATEE
           AND A.USE_YN = 'Y'
/* 2026.09.30 AJS 수정 (END) */
           AND ROWNUM   = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN V_DELEGATEE := '';
    END;

    /* ★원문은 MSSQL SUBSTRING 시작을 0 으로 주어 앞 네 글자를 잘라 쓴다.
          Oracle 은 시작 1 · 길이 4 로 맞춘다 */
    V_FROM_DATE := SUBSTR(P_FROM_DATE, 1, 4) || '-' || SUBSTR(P_FROM_DATE, 5, 2) || '-' || SUBSTR(P_FROM_DATE, 7, 2);
    V_TO_DATE   := SUBSTR(P_TO_DATE,   1, 4) || '-' || SUBSTR(P_TO_DATE,   5, 2) || '-' || SUBSTR(P_TO_DATE,   7, 2);

    IF P_TYPE = 'S'
    THEN
        V_TITLE    := '[SSP] Approval Delegation';
        V_CONTENTS := P_DELEGATOR || ' delegated approval to ' || P_DELEGATEE;
    ELSE
        V_TITLE    := '[SSP] Canceled Approval Delegation';
        V_CONTENTS := P_DELEGATOR || ' has canceled approval  delegation to ' || P_DELEGATEE;
    END IF;

    V_MAX_LOOP_CNT := SCM_ARR_SPL_CNT(P_DIVISIONID, C_DELIMITER);

    WHILE LENGTH(P_DIVISIONID) > 0
      AND V_MST_LOOP_CNT < V_MAX_LOOP_CNT
    LOOP

        V_MST_LOOP_CNT := V_MST_LOOP_CNT + 1;

        V_DIVISION_ID  := SCM_ARR_SPL_VAL(P_DIVISIONID, C_DELIMITER, V_MST_LOOP_CNT);

        IF V_MAX_LOOP_CNT = V_MST_LOOP_CNT
        THEN
            V_MAIL_DIVISION_ID := V_MAIL_DIVISION_ID || V_DIVISION_ID;
        ELSE
            V_MAIL_DIVISION_ID := V_MAIL_DIVISION_ID || V_DIVISION_ID || ', ';
        END IF;

    END LOOP;

    V_TABLE_BODY := '
		<html>
				<head>
					<title>Untitled Document</title>
					<meta charset="UTF-8">
					<style>
						* {margin:0;padding:0;}
						body {font-family:Malgun Gothic, Arial, Helvetica, sans-serif;font-size:12px;line-height:1.8;color:#333333;}
						table {border-collapse:collapse;width:100%;}
						table th {background:#f5f5f5;border-bottom:1px solid #e1e1e1;}
						table td {background:#fff;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1;border-bottom:1px solid #e1e1e1;}
						table tbody th {border-left:1px solid #e1e1e1;text-align:right;padding:6px 8px;font-size:12px}
						table tbody td {padding:6px 8px;font-size:12px}
						table thead th {text-align:center;padding:3px;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1; border-bottom:1px solid #d1d1d1;font-size:12px}
						.hori-table table thead td {text-align:center;padding:3px;}
						.hori-table table tbody td {text-align:center;padding:3px;}
						.vertical-table, .hori-table {margin-bottom:20px;}
					</style>
				</head>
				<body>'
              || '<b>'
              || '<br></br>'
              || '<p>' || NVL(V_CONTENTS, '') || '<br>'
              || '- Division : ' || NVL(V_MAIL_DIVISION_ID, '') || '<br>'
              || '- Delegator : ' || NVL(V_DELEGATOR, '') || '<br>'
              || '- Delegatee : ' || NVL(V_DELEGATEE, '') || '<br>'
              || '- Period : ' || V_FROM_DATE || ' ~ ' || V_TO_DATE || ' (GMT&#43;09:00) Seoul<br></p>'
              || '<br></br>'
              || '<p>After accessing the SCM system, check the path below.<br>'
              || '* SCM > Master> Shipping Master> Delegate<br></p></b>'
              || '</body></html>';

    /* 위임자 메일 전송 */
    SCM_ADM_MAIL_SEND(V_DELEGATOR_MAIL, V_TITLE, V_TABLE_BODY, P_HTML_YN);

    /* 수임자 메일 전송 */
    SCM_ADM_MAIL_SEND(V_DELEGATEE_MAIL, V_TITLE, V_TABLE_BODY, P_HTML_YN);

    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

EXCEPTION
    WHEN OTHERS THEN
        /* AS-IS CATCH 는 이력만 남기고 확정한다 — 부르는 쪽으로 오류를 넘기지 않는다 */
        PR_SSP_LOG_ERROR(V_PROGRAM_NAME, SUBSTR(SQLERRM, 1, 1000));

END PR_SSP_MAIL_SEND_DELEGATE;

PROCEDURE PR_SSP_MAIL_SEND_PR_REQUEST
(
    P_PLAN_START_YYYYMMDD  IN  VARCHAR2
  , P_COMPANY_ID           IN  VARCHAR2
  , P_DM_REQUEST_NO        IN  VARCHAR2
  , P_LANGUAGE             IN  VARCHAR2
  , P_CATEGORY_ID          IN  VARCHAR2
  , O_RESULT_CURSOR        OUT SYS_REFCURSOR
)
/*
 * Program ID   : PR_SSP_MAIL_SEND_PR_REQUEST
 * Description  : PR발행 내용 요청자에게 MAIL 발송
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2021-06-24	KIMYONGHO	   신규추가
 * 2026.07.06  ZIONEX  [PJ202650304]  NextSCM Migration
 */
AS
    V_PROGRAM_NAME  VARCHAR2(150 CHAR) := 'PR_SSP_MAIL_SEND_PR_REQUEST';
    N_LOG_COUNT     NUMBER := 0;
    V_RESULT        CLOB := '';
    V_RESULT4       CLOB := '';
    V_HEAD_CONT     CLOB := '';
    V_BODY_CONT     CLOB := '';
    V_TABLE_BODY    CLOB := '';
    V_TO_MAIL       VARCHAR2(400 CHAR);
    V_MAIL_TITLE    VARCHAR2(200 CHAR);
    V_BODY_CONTENTS CLOB;
    V_USE_TYPE_CODE VARCHAR2(10 CHAR);
    V_CHECK         NUMBER := 0;
    V_RECEIVER_CNT     NUMBER := 0;
    V_RECEIVER_TMPCNT  NUMBER := 0;

    V_SEG1 VARCHAR2(100 CHAR); V_SEG2 VARCHAR2(100 CHAR); V_SEG3 VARCHAR2(100 CHAR); V_SEG4 VARCHAR2(100 CHAR);
    V_SEG5 VARCHAR2(100 CHAR); V_SEG6 VARCHAR2(100 CHAR); V_SEG7 VARCHAR2(100 CHAR); V_SEG8 VARCHAR2(100 CHAR);
    V_SEG9 VARCHAR2(100 CHAR); V_SEG10 VARCHAR2(100 CHAR);
    V_ERROR_MESSAGE VARCHAR2(1000 CHAR);
    V_RESULT_MSG    VARCHAR2(1100 CHAR);
    CR CONSTANT VARCHAR2(1 CHAR) := CHR(10);
BEGIN
    DELETE FROM GT_SMSPR_MAILBATCH;


    V_RESULT := 'SELECT A.DM_REQ_NO AS SEGMENT1' || CR
      || ', NVL(C.ERP_PO_STATUS,''-'') AS SEGMENT2' || CR
      || ', A.DIVISION_ID AS SEGMENT3, A.PROJECT_CODE AS SEGMENT4' || CR
      || ', NVL(FN_GET_PROJECT_NAME(A.DIVISION_ID,A.PROJECT_CODE),''-'') AS SEGMENT5' || CR
      || ', A.ITEM_SEQ AS SEGMENT6, A.ITEM_ID AS SEGMENT7, NVL(T.ITEM_NAME,''-'') AS SEGMENT8' || CR
      || ', A.UOM AS SEGMENT9, A.SCM_SITE_ID AS SEGMENT10' || CR
      || ', TO_CHAR(TO_DATE(A.YYYYMMDD,''YYYYMMDD''),''YYYY-MM-DD'') AS SEGMENT11' || CR
      || ', FLOOR(A.PLAN_QTY) AS SEGMENT12, DPD.PR_ITEM_DETAIL AS SEGMENT13' || CR
      || ', FLOOR(A.INV_ALLO_QTY) AS SEGMENT14, FLOOR(E.INV_ALLO_QTY) AS SEGMENT15' || CR
      || ', FLOOR(B.PR_REQ_QTY) AS SEGMENT16, B.PR_NO AS SEGMENT17' || CR
      || ', CASE WHEN ''' || P_LANGUAGE || ''' = ''KO'' THEN U.UserName ELSE U.UserName_E END || ''('' || A.ATTRIBUTE1 || '')'' AS SEGMENT18' || CR
      || ', (SELECT NVL(DEPT_NAME_KO,''-'') FROM SCM_MST_SSO_DEPT_INFO AA LEFT OUTER JOIN TB_FX_USER BB ON AA.DEPT_ID=BB.DEPT_ID WHERE BB.UserID=A.ATTRIBUTE1) AS SEGMENT19' || CR
      || ', ''Request No'' AS COLUMN1, ''PO Status'' AS COLUMN2, ''Div'' AS COLUMN3, ''Project Code'' AS COLUMN4' || CR
      || ', ''Project Name'' AS COLUMN5, ''Seq'' AS COLUMN6, ''Model'' AS COLUMN7, ''Model Name'' AS COLUMN8' || CR
      || ', ''UOM'' AS COLUMN9, ''TO Stie'' AS COLUMN10, ''Request Date'' AS COLUMN11, ''Request Qty'' AS COLUMN12' || CR
      || ', ''Item Detail'' AS COLUMN13, ''Allo Qty'' AS COLUMN14, ''Net Qty'' AS COLUMN15, ''PR Qty'' AS COLUMN16' || CR
      || ', ''PR No'' AS COLUMN17, ''Requestor'' AS COLUMN18, ''Team'' AS COLUMN19' || CR
      || ', ''' || P_LANGUAGE || ''' AS language_code, A.ATTRIBUTE1 AS USER_ID' || CR
      || ' FROM SSP_ANL_ESS_REQ A' || CR
      || ' JOIN SCM_MST_ITEM_SN T ON A.ITEM_ID=T.ITEM_ID AND A.DIVISION_ID=T.DIVISION_ID AND T.COMPANY_ID=''' || P_COMPANY_ID || ''' AND T.ITEM_TYPE IN (''Q'',''R'')' || CR
      || ' LEFT OUTER JOIN SSP_ANL_ESS_PR B ON A.DM_REQ_NO=B.DM_REQ_NO AND A.ITEM_SEQ=B.PR_ITEM_SEQ AND A.ITEM_ID=B.PR_ITEM_ID' || CR
      || ' LEFT OUTER JOIN SSP_ANL_ESS_PO C ON B.PR_NO=C.PR_NO AND B.PR_ITEM_ID=C.PO_ITEM_ID' || CR
      || ' LEFT OUTER JOIN (SELECT PR_NO,PO_NO,PO_ITEM_SEQ,PO_ITEM_ID,SUM(PO_ITEM_IN_QTY) AS PO_ITEM_IN_QTY FROM SSP_ANL_ESS_PO_IN GROUP BY PR_NO,PO_NO,PO_ITEM_SEQ,PO_ITEM_ID) D ON C.PO_NO=D.PO_NO AND C.PR_NO=D.PR_NO AND C.PO_ITEM_ID=D.PO_ITEM_ID' || CR
      || ' LEFT OUTER JOIN SSP_ANL_ESS_REQ_NET E ON E.DM_REQ_NO=A.DM_REQ_NO AND E.ITEM_ID=A.ITEM_ID AND E.PLAN_START_YYYYMMDD=''' || P_PLAN_START_YYYYMMDD || '''' || CR
      || ' LEFT OUTER JOIN DM_PLN_PR_DETAIL DPD ON A.DM_REQ_NO=DPD.REQUEST_NO AND A.ITEM_ID=DPD.ITEM_ID AND A.SCM_SITE_ID=DPD.SCM_SITE_ID AND A.PROJECT_CODE=DPD.PROJECT_CODE AND A.YYYYMMDD=DPD.YYYYMMDD' || CR
      || ' LEFT OUTER JOIN TB_FX_USER U ON A.ATTRIBUTE1=U.UserID AND U.UseYN=''Y''' || CR
      || ' WHERE A.DM_REQ_NO=''' || P_DM_REQUEST_NO || '''' || CR;


    V_RESULT := V_RESULT || ' UNION ALL ' || CR
      || 'SELECT DISTINCT A.DM_REQ_NO AS SEGMENT1' || CR
      || ', NVL(C.ERP_PO_STATUS,''-'') AS SEGMENT2, A.DIVISION_ID AS SEGMENT3, A.PROJECT_CODE AS SEGMENT4' || CR
      || ', NVL(FN_GET_PROJECT_NAME(A.DIVISION_ID,A.PROJECT_CODE),''-'') AS SEGMENT5' || CR
      || ', A.ITEM_SEQ AS SEGMENT6, A.ITEM_ID AS SEGMENT7, NVL(T.ITEM_NAME,''-'') AS SEGMENT8' || CR
      || ', A.UOM AS SEGMENT9, A.SCM_SITE_ID AS SEGMENT10' || CR
      || ', TO_CHAR(TO_DATE(A.YYYYMMDD,''YYYYMMDD''),''YYYY-MM-DD'') AS SEGMENT11' || CR
      || ', FLOOR(A.PLAN_QTY) AS SEGMENT12, DPD.PR_ITEM_DETAIL AS SEGMENT13' || CR
      || ', FLOOR(A.INV_ALLO_QTY) AS SEGMENT14, FLOOR(E.INV_ALLO_QTY) AS SEGMENT15' || CR
      || ', FLOOR(B.PR_REQ_QTY) AS SEGMENT16, B.PR_NO AS SEGMENT17' || CR
      || ', CASE WHEN ''' || P_LANGUAGE || ''' = ''KO'' THEN U.UserName ELSE U.UserName_E END || ''('' || A.ATTRIBUTE1 || '')'' AS SEGMENT18' || CR
      || ', (SELECT NVL(DEPT_NAME_KO,''-'') FROM SCM_MST_SSO_DEPT_INFO AA LEFT OUTER JOIN TB_FX_USER BB ON AA.DEPT_ID=BB.DEPT_ID WHERE BB.UserID=A.ATTRIBUTE1) AS SEGMENT19' || CR
      || ', ''Request No'' AS COLUMN1, ''PO Status'' AS COLUMN2, ''Div'' AS COLUMN3, ''Project Code'' AS COLUMN4' || CR
      || ', ''Project Name'' AS COLUMN5, ''Seq'' AS COLUMN6, ''Model'' AS COLUMN7, ''Model Name'' AS COLUMN8' || CR
      || ', ''UOM'' AS COLUMN9, ''TO Stie'' AS COLUMN10, ''Request Date'' AS COLUMN11, ''Request Qty'' AS COLUMN12' || CR
      || ', ''Item Detail'' AS COLUMN13, ''Allo Qty'' AS COLUMN14, ''Net Qty'' AS COLUMN15, ''PR Qty'' AS COLUMN16' || CR
      || ', ''PR No'' AS COLUMN17, ''Requestor'' AS COLUMN18, ''Team'' AS COLUMN19' || CR
      || ', ''' || P_LANGUAGE || ''' AS language_code, M.USER_ID AS USER_ID' || CR
      || ' FROM SSP_ANL_ESS_REQ A' || CR
      || ' INNER JOIN SCM_ADM_RECIPIENT_ASSIGN M ON M.CATEGORY_ID=''76''' || CR
      || ' JOIN SCM_MST_ITEM_SN T ON A.ITEM_ID=T.ITEM_ID AND A.DIVISION_ID=T.DIVISION_ID AND T.COMPANY_ID=''' || P_COMPANY_ID || ''' AND T.ITEM_TYPE IN (''Q'',''R'')' || CR
      || ' LEFT OUTER JOIN SSP_ANL_ESS_PR B ON A.DM_REQ_NO=B.DM_REQ_NO AND A.ITEM_SEQ=B.PR_ITEM_SEQ AND A.ITEM_ID=B.PR_ITEM_ID' || CR
      || ' LEFT OUTER JOIN SSP_ANL_ESS_PO C ON B.PR_NO=C.PR_NO AND B.PR_ITEM_ID=C.PO_ITEM_ID' || CR
      || ' LEFT OUTER JOIN (SELECT PR_NO,PO_NO,PO_ITEM_SEQ,PO_ITEM_ID,SUM(PO_ITEM_IN_QTY) AS PO_ITEM_IN_QTY FROM SSP_ANL_ESS_PO_IN GROUP BY PR_NO,PO_NO,PO_ITEM_SEQ,PO_ITEM_ID) D ON C.PO_NO=D.PO_NO AND C.PR_NO=D.PR_NO AND C.PO_ITEM_ID=D.PO_ITEM_ID' || CR
      || ' LEFT OUTER JOIN SSP_ANL_ESS_REQ_NET E ON E.DM_REQ_NO=A.DM_REQ_NO AND E.ITEM_ID=A.ITEM_ID AND E.PLAN_START_YYYYMMDD=''' || P_PLAN_START_YYYYMMDD || '''' || CR
      || ' LEFT OUTER JOIN DM_PLN_PR_DETAIL DPD ON A.DM_REQ_NO=DPD.REQUEST_NO AND A.ITEM_ID=DPD.ITEM_ID AND A.SCM_SITE_ID=DPD.SCM_SITE_ID AND A.PROJECT_CODE=DPD.PROJECT_CODE AND A.YYYYMMDD=DPD.YYYYMMDD' || CR
      || ' LEFT OUTER JOIN TB_FX_USER U ON A.ATTRIBUTE1=U.UserID AND U.UseYN=''Y''' || CR
      || ' WHERE A.DM_REQ_NO=''' || P_DM_REQUEST_NO || '''' || CR;


    V_RESULT4 := 'SELECT z.use_type_code, z.user_id, z.language_code' || CR
      || ', z.segment1,z.segment2,z.segment3,z.segment4,z.segment5,z.segment6,z.segment7,z.segment8,z.segment9,z.segment10' || CR
      || ', z.segment11,z.segment12,z.segment13,z.segment14,z.segment15,z.segment16,z.segment17,z.segment18,z.segment19' || CR
      || ', z.column1,z.column2,z.column3,z.column4,z.column5,z.column6,z.column7,z.column8,z.column9,z.column10' || CR
      || ', z.column11,z.column12,z.column13,z.column14,z.column15,z.column16,z.column17,z.column18,z.column19' || CR
      || ', z.mail_title, z.body_contents, z.sql_long_text' || CR
      || ', COUNT(user_id) OVER (PARTITION BY user_id) AS user_cnt' || CR
      || ', DENSE_RANK() OVER (ORDER BY user_id) AS rank' || CR
      || ' FROM (' || CR
      || '  SELECT x.use_type_code, y.user_id, x.language_code' || CR
      || '   ,y.segment1,y.segment2,y.segment3,y.segment4,y.segment5,y.segment6,y.segment7,y.segment8,y.segment9,y.segment10' || CR
      || '   ,y.segment11,y.segment12,y.segment13,y.segment14,y.segment15,y.segment16,y.segment17,y.segment18,y.segment19' || CR
      || '   ,y.column1,y.column2,y.column3,y.column4,y.column5,y.column6,y.column7,y.column8,y.column9,y.column10' || CR
      || '   ,y.column11,y.column12,y.column13,y.column14,y.column15,y.column16,y.column17,y.column18,y.column19' || CR
      || '   ,x.mail_title || ''_'' || y.segment1 || ''_['' || y.segment4 || '']'' AS mail_title' || CR
      || '   ,x.body_contents, x.sql_long_text' || CR
      || '  FROM (' || V_RESULT || ') y,' || CR
      || '   ( SELECT a.use_type_code, c.user_id, b.language_code, b.mail_title, d.SEGMENT3 AS header_contents' || CR
      || '        ,CASE A.USE_TYPE_CODE WHEN ''MAIL'' THEN REPLACE(b.message_content,CHR(10),''<br><br>'') WHEN ''SMS'' THEN b.message_content END AS body_contents' || CR
      || '        ,d.SEGMENT3 AS foot_contents, a.SQL_LONG_TEXT' || CR
      || '     FROM SCM_ADM_RECIPIENT_LIST a' || CR
      || '     INNER JOIN SCM_ADM_RECIPIENT_MESSAGE b ON a.CATEGORY_ID=B.CATEGORY_ID' || CR
      || '     LEFT OUTER JOIN SCM_ADM_RECIPIENT_ASSIGN c ON B.CATEGORY_ID=C.CATEGORY_ID' || CR
      || '     INNER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL d ON D.SEGMENT1=B.LANGUAGE_CODE AND D.LOOKUP_TYPE=''MAIL_HEADER_FOOT'' AND D.VALID_YN=''Y''' || CR
      || '     LEFT OUTER JOIN TB_FX_USER e ON B.LANGUAGE_CODE=E.Language AND C.USER_ID=E.UserID' || CR
      || '     WHERE a.category_id = ' || P_CATEGORY_ID || ' AND a.VALID_YN=''Y''' || CR
      || '   ) x' || CR
      || '  WHERE x.language_code = y.language_code' || CR
      || ' ) z ORDER BY user_id, segment6';

    /* 적재 (INSERT INTO #TblMailSendBatch exec(@v_result4)) */
    EXECUTE IMMEDIATE 'INSERT INTO GT_SMSPR_MAILBATCH ('
      || 'use_type_code,user_id,language_code,segment1,segment2,segment3,segment4,segment5,segment6,segment7,segment8,segment9,segment10,'
      || 'segment11,segment12,segment13,segment14,segment15,segment16,segment17,segment18,segment19,'
      || 'column1,column2,column3,column4,column5,column6,column7,column8,column9,column10,'
      || 'column11,column12,column13,column14,column15,column16,column17,column18,column19,'
      || 'mail_title,body_contents,sql_long_text,user_cnt,rank) ' || V_RESULT4;

    /* 시작 LOG */
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, 'START', N_LOG_COUNT, '########## Start of procedure ##########', '', SYSDATE);


    FOR R IN ( SELECT * FROM GT_SMSPR_MAILBATCH WHERE RANK = '1' ) LOOP
        IF R.USE_TYPE_CODE = 'MAIL' THEN
            IF V_CHECK = 0 THEN
                V_HEAD_CONT := '<tr>';
                IF R.COLUMN1  IS NOT NULL THEN V_HEAD_CONT := V_HEAD_CONT || '<th>' || R.COLUMN1  || '</th>'; END IF;
                IF R.COLUMN2  IS NOT NULL THEN V_HEAD_CONT := V_HEAD_CONT || '<th>' || R.COLUMN2  || '</th>'; END IF;
                IF R.COLUMN3  IS NOT NULL THEN V_HEAD_CONT := V_HEAD_CONT || '<th>' || R.COLUMN3  || '</th>'; END IF;
                IF R.COLUMN4  IS NOT NULL THEN V_HEAD_CONT := V_HEAD_CONT || '<th>' || R.COLUMN4  || '</th>'; END IF;
                IF R.COLUMN5  IS NOT NULL THEN V_HEAD_CONT := V_HEAD_CONT || '<th>' || R.COLUMN5  || '</th>'; END IF;
                IF R.COLUMN6  IS NOT NULL THEN V_HEAD_CONT := V_HEAD_CONT || '<th>' || R.COLUMN6  || '</th>'; END IF;
                IF R.COLUMN7  IS NOT NULL THEN V_HEAD_CONT := V_HEAD_CONT || '<th>' || R.COLUMN7  || '</th>'; END IF;
                IF R.COLUMN8  IS NOT NULL THEN V_HEAD_CONT := V_HEAD_CONT || '<th>' || R.COLUMN8  || '</th>'; END IF;
                IF R.COLUMN9  IS NOT NULL THEN V_HEAD_CONT := V_HEAD_CONT || '<th>' || R.COLUMN9  || '</th>'; END IF;
                IF R.COLUMN10 IS NOT NULL THEN V_HEAD_CONT := V_HEAD_CONT || '<th>' || R.COLUMN10 || '</th>'; END IF;
                IF R.COLUMN11 IS NOT NULL THEN V_HEAD_CONT := V_HEAD_CONT || '<th>' || R.COLUMN11 || '</th>'; END IF;
                IF R.COLUMN12 IS NOT NULL THEN V_HEAD_CONT := V_HEAD_CONT || '<th>' || R.COLUMN12 || '</th>'; END IF;
                IF R.COLUMN13 IS NOT NULL THEN V_HEAD_CONT := V_HEAD_CONT || '<th>' || R.COLUMN13 || '</th>'; END IF;
                IF R.COLUMN14 IS NOT NULL THEN V_HEAD_CONT := V_HEAD_CONT || '<th>' || R.COLUMN14 || '</th>'; END IF;
                IF R.COLUMN15 IS NOT NULL THEN V_HEAD_CONT := V_HEAD_CONT || '<th>' || R.COLUMN15 || '</th>'; END IF;
                IF R.COLUMN16 IS NOT NULL THEN V_HEAD_CONT := V_HEAD_CONT || '<th>' || R.COLUMN16 || '</th>'; END IF;
                IF R.COLUMN17 IS NOT NULL THEN V_HEAD_CONT := V_HEAD_CONT || '<th>' || R.COLUMN17 || '</th>'; END IF;
                IF R.COLUMN18 IS NOT NULL THEN V_HEAD_CONT := V_HEAD_CONT || '<th>' || R.COLUMN18 || '</th>'; END IF;
                IF R.COLUMN19 IS NOT NULL THEN V_HEAD_CONT := V_HEAD_CONT || '<th>' || R.COLUMN19 || '</th>'; END IF;
                V_HEAD_CONT := V_HEAD_CONT || '</tr>';
                V_CHECK := V_CHECK + 1;
            END IF;
            V_BODY_CONT := V_BODY_CONT || '<tr>';
            IF R.COLUMN1  IS NOT NULL THEN V_BODY_CONT := V_BODY_CONT || '<td align=''Center''>' || REPLACE(R.SEGMENT1,  CHR(10), ' ') || '</td>'; END IF;
            IF R.COLUMN2  IS NOT NULL THEN V_BODY_CONT := V_BODY_CONT || '<td align=''Center''>' || REPLACE(R.SEGMENT2,  CHR(10), ' ') || '</td>'; END IF;
            IF R.COLUMN3  IS NOT NULL THEN V_BODY_CONT := V_BODY_CONT || '<td align=''Center''>' || REPLACE(R.SEGMENT3,  CHR(10), ' ') || '</td>'; END IF;
            IF R.COLUMN4  IS NOT NULL THEN V_BODY_CONT := V_BODY_CONT || '<td align=''Center''>' || REPLACE(R.SEGMENT4,  CHR(10), ' ') || '</td>'; END IF;
            IF R.COLUMN5  IS NOT NULL THEN V_BODY_CONT := V_BODY_CONT || '<td align=''Center''>' || REPLACE(R.SEGMENT5,  CHR(10), ' ') || '</td>'; END IF;
            IF R.COLUMN6  IS NOT NULL THEN V_BODY_CONT := V_BODY_CONT || '<td align=''Center''>' || REPLACE(R.SEGMENT6,  CHR(10), ' ') || '</td>'; END IF;
            IF R.COLUMN7  IS NOT NULL THEN V_BODY_CONT := V_BODY_CONT || '<td align=''Center''>' || REPLACE(R.SEGMENT7,  CHR(10), ' ') || '</td>'; END IF;
            IF R.COLUMN8  IS NOT NULL THEN V_BODY_CONT := V_BODY_CONT || '<td align=''Center''>' || REPLACE(R.SEGMENT8,  CHR(10), ' ') || '</td>'; END IF;
            IF R.COLUMN9  IS NOT NULL THEN V_BODY_CONT := V_BODY_CONT || '<td align=''Center''>' || REPLACE(R.SEGMENT9,  CHR(10), ' ') || '</td>'; END IF;
            IF R.COLUMN10 IS NOT NULL THEN V_BODY_CONT := V_BODY_CONT || '<td align=''Center''>' || REPLACE(R.SEGMENT10, CHR(10), ' ') || '</td>'; END IF;
            IF R.COLUMN11 IS NOT NULL THEN V_BODY_CONT := V_BODY_CONT || '<td align=''Center''>' || REPLACE(R.SEGMENT11, CHR(10), ' ') || '</td>'; END IF;
            IF R.COLUMN12 IS NOT NULL THEN V_BODY_CONT := V_BODY_CONT || '<td align=''Center''>' || REPLACE(R.SEGMENT12, CHR(10), ' ') || '</td>'; END IF;
            IF R.COLUMN13 IS NOT NULL THEN V_BODY_CONT := V_BODY_CONT || '<td align=''Center''>' || REPLACE(R.SEGMENT13, CHR(10), ' ') || '</td>'; END IF;
            IF R.COLUMN14 IS NOT NULL THEN V_BODY_CONT := V_BODY_CONT || '<td align=''Center''>' || REPLACE(R.SEGMENT14, CHR(10), ' ') || '</td>'; END IF;
            IF R.COLUMN15 IS NOT NULL THEN V_BODY_CONT := V_BODY_CONT || '<td align=''Center''>' || REPLACE(R.SEGMENT15, CHR(10), ' ') || '</td>'; END IF;
            IF R.COLUMN16 IS NOT NULL THEN V_BODY_CONT := V_BODY_CONT || '<td align=''Center''>' || REPLACE(R.SEGMENT16, CHR(10), ' ') || '</td>'; END IF;
            IF R.COLUMN17 IS NOT NULL THEN V_BODY_CONT := V_BODY_CONT || '<td align=''Center''>' || REPLACE(R.SEGMENT17, CHR(10), ' ') || '</td>'; END IF;
            IF R.COLUMN18 IS NOT NULL THEN V_BODY_CONT := V_BODY_CONT || '<td align=''Center''>' || REPLACE(R.SEGMENT18, CHR(10), ' ') || '</td>'; END IF;
            IF R.COLUMN19 IS NOT NULL THEN V_BODY_CONT := V_BODY_CONT || '<td align=''Center''>' || REPLACE(R.SEGMENT19, CHR(10), ' ') || '</td>'; END IF;
            V_BODY_CONT := V_BODY_CONT || '</tr>';
        END IF;

        V_USE_TYPE_CODE := R.USE_TYPE_CODE; V_MAIL_TITLE := R.MAIL_TITLE; V_BODY_CONTENTS := R.BODY_CONTENTS;
        V_SEG1 := R.SEGMENT1; V_SEG2 := R.SEGMENT2; V_SEG3 := R.SEGMENT3; V_SEG4 := R.SEGMENT4; V_SEG5 := R.SEGMENT5;
        V_SEG6 := R.SEGMENT6; V_SEG7 := R.SEGMENT7; V_SEG8 := R.SEGMENT8; V_SEG9 := R.SEGMENT9; V_SEG10 := R.SEGMENT10;
    END LOOP;

    IF LENGTH(V_HEAD_CONT) > 0 THEN
        V_TABLE_BODY := ' <html><head><title>Untitled Document</title><style>'
          || '* {margin:0;padding:0;} body {font-family:Malgun Gothic, Arial, Helvetica, sans-serif;font-size:12px;line-height:1.8;color:#333333;}'
          || 'table {border-collapse:collapse;width:100%;} table th {background:#f5f5f5;border-bottom:1px solid #e1e1e1;}'
          || 'table td {background:#fff;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1;border-bottom:1px solid #e1e1e1;}'
          || 'table thead th {text-align:center;padding:3px;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1;border-bottom:1px solid #d1d1d1;font-size:12px}'
          || '</style></head><body>' || '</br>'
          || '<b>' || REPLACE(TO_CHAR(V_BODY_CONTENTS), CHR(10), '<br>') || '</b>'
          || '<div id="divBody" style="width: 100%; overflow-x: auto; overflow-y: auto; font-size: 9pt; line-break: auto;">'
          || '<table style=''border-top:2px solid #c8294b; width:1450px;''><thead>' || V_HEAD_CONT || '</thead>'
          || '<tbody>' || V_BODY_CONT || '</tbody></div></body></html>';

        SELECT COUNT(*) INTO V_RECEIVER_CNT FROM (SELECT DISTINCT USER_ID FROM GT_SMSPR_MAILBATCH) A;

        V_RECEIVER_TMPCNT := 0;
        WHILE V_RECEIVER_TMPCNT < V_RECEIVER_CNT LOOP
            V_RECEIVER_TMPCNT := V_RECEIVER_TMPCNT + 1;
            BEGIN
                SELECT USER_ID INTO V_TO_MAIL FROM (SELECT DISTINCT USER_ID FROM GT_SMSPR_MAILBATCH WHERE RANK = TO_CHAR(V_RECEIVER_TMPCNT)) A;
            EXCEPTION WHEN NO_DATA_FOUND THEN V_TO_MAIL := NULL; WHEN TOO_MANY_ROWS THEN NULL;
            END;
            IF V_TO_MAIL IS NOT NULL THEN
                BEGIN
                    SELECT V_TO_MAIL || CASE WHEN REGEXP_LIKE(NVL(DEPT_ID,'X'),'^[0-9]+$') THEN '@lgensol.com' ELSE '@lgespartner.com' END
                      INTO V_TO_MAIL FROM SCM_MST_SSO_USER_INFO WHERE USER_ID = V_TO_MAIL AND ROWNUM = 1;
                EXCEPTION WHEN NO_DATA_FOUND THEN NULL;
                END;


                PKG_SEND_MAIL.P_SEND_MAIL(V_TO_MAIL, V_MAIL_TITLE, V_TABLE_BODY, 'Y');
                /* MAIL 발송 LOG 저장 */
                SCM_ADM_SAVE_MAIL_SEND_BATCH_LOG(V_USE_TYPE_CODE, TO_NUMBER(P_CATEGORY_ID)
                  , V_SEG1, V_SEG2, V_SEG3, V_SEG4, V_SEG5, V_SEG6, V_SEG7, V_SEG8, V_SEG9, V_SEG10, '', V_TO_MAIL);
                V_TO_MAIL := '';
            END IF;
        END LOOP;
    END IF;

    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, 'END', N_LOG_COUNT, '########## END of procedure ##########', '', SYSDATE);
    DELETE FROM GT_SMSPR_MAILBATCH;
    COMMIT;

    OPEN O_RESULT_CURSOR FOR SELECT 'S' AS RESULT_CODE FROM DUAL;
EXCEPTION
    WHEN OTHERS THEN
        V_ERROR_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
        V_RESULT_MSG := '[' || TO_CHAR(SQLCODE) || ']' || V_ERROR_MESSAGE;
        BEGIN
            INSERT INTO SCM_SYS_LOG_BATCH (PROGRAM_NAME, LOG_TYPE, LOG_COUNT, LOG_MESSAGE, DESCRIPTION, EVENT_DATE
              , CREATION_DATE, CREATED_BY, LAST_UPDATE_DATE, LAST_UPDATED_BY)
            VALUES (V_PROGRAM_NAME, 'ERROR', NULL, V_ERROR_MESSAGE, NULL, SYSDATE, SYSDATE, V_PROGRAM_NAME, SYSDATE, V_PROGRAM_NAME);
            /* MAIL 발송 LOG 저장(에러) */
            SCM_ADM_SAVE_MAIL_SEND_BATCH_LOG('ERROR', TO_NUMBER(P_CATEGORY_ID), 'MAIN ERROR'
              , '', '', '', '', '', '', '', '', '', V_ERROR_MESSAGE, '');
            COMMIT;
        EXCEPTION WHEN OTHERS THEN NULL;
        END;
        /* error코드, error 메시지 반환 */
        OPEN O_RESULT_CURSOR FOR SELECT 'F' AS RESULT_CODE, V_RESULT_MSG AS MESSAGE FROM DUAL;
END;

PROCEDURE PR_SSP_MAIL_SEND_SCS_NORECEIVE_BOH
/*
 * Program ID   : PR_SSP_MAIL_SEND_SCS_NORECEIVE_BOH
 * Description  : PR_SSP_MAIL_SEND_SCS_NORECEIVE_BOH
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2021/12/02   SHINMYUNGSU	   최초 작성  PR_SSP_MAIL_SEND_SCS_NOTRECEIVE_BOH
 * 2026.07.06   ZIONEX      [PJ202650304] NextSCM Migration
 */
/* @p_language					NVARCHAR(MAX) */
AS


    P_LANGUAGE          VARCHAR2(4000 CHAR) := 'KO';
    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME      VARCHAR2(150 CHAR) := 'PR_SSP_MAIL_SEND_SCS_NORECEIVE_BOH';
    V_LOG_TYPE          VARCHAR2(30 CHAR);   /* START/END/ERROR/... */
    N_LOG_COUNT         INTEGER := 0;
    V_LOG_MESSAGE       VARCHAR2(1000 CHAR);
    V_DESCRIPTION       VARCHAR2(500 CHAR);
    D_EVENT_DATE        DATE;

   /********************************************************************************
	* 임시테이블만들기
	********************************************************************************/
    V_CUTOFF_DATE       VARCHAR2(4000 CHAR) := '';
    V_DIVISION_ID       VARCHAR2(4000 CHAR) := '40';
    V_OPERATION_GROUP   VARCHAR2(4000 CHAR) := 'P';
    V_DIS_CUTOFF_DATE   VARCHAR2(4000 CHAR);
    V_DEAD_LINE         VARCHAR2(4000 CHAR);

    /* 메일관련 변수들 */
    V_SEND_CNT          NUMBER;              /* 메일보내는 루프 카운드 */
    V_SEND_TMPCNT       NUMBER;              /* 메일보내는 루프 카운드 tmp */
    /* NVARCHAR(MAX) HTML 누적 → CLOB (폭 초과 ORA-06502 방지) */
    V_HEAD_CONT         CLOB;
    V_BODY_CONT         CLOB;
    V_MAIL_TITLE        VARCHAR2(100 CHAR);
    V_BODY_CONTENTS     VARCHAR2(4000 CHAR);

    V_PACKER            VARCHAR2(100 CHAR);
    V_PACKER_CODE       VARCHAR2(100 CHAR);
    V_MODEL_PIC         VARCHAR2(4000 CHAR);
    V_MAIL_RECEIVER     VARCHAR2(100 CHAR);
    V_TO_MAIL           VARCHAR2(400 CHAR);
    V_TABLE_BODY        CLOB;

    /* BEGIN CATCH 내 지역선언 @v_error_message (SQLERRM 정적SQL 직접삽입 금지 → 지역변수) */
    V_ERROR_MESSAGE     VARCHAR2(1000 CHAR);
BEGIN
    V_CUTOFF_DATE     := TO_CHAR(SYSDATE - 1, 'YYYYMMDD');
    V_DIS_CUTOFF_DATE := TO_CHAR(FN_CHAR_TO_DATE(V_CUTOFF_DATE), 'YYYY-MM-DD');
    V_DEAD_LINE       := TO_CHAR(FN_CHAR_TO_DATE(TO_CHAR(SYSDATE, 'YYYYMMDD')), 'YYYY-MM-DD') || ' 16:00 KR Time';


    DELETE FROM GT_SSPNRB_RESULT_1;
    DELETE FROM GT_SSPNRB_RESULT_2;
    DELETE FROM GT_SSPNRB_MAILSEND_P;
    DELETE FROM GT_SSPNRB_MAILSEND;

    BEGIN

    /*//시작 LOG */
        V_LOG_TYPE    := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
        /*//LOG END */

        /* 원본 데이터를 만든다... */
        INSERT INTO GT_SSPNRB_RESULT_1
        (
          PACKER
        , PACKER_CODE
        , MODEL_PIC
        , USER_ID
        )
        SELECT
            XXX.SITE_DESCRIPTION
           , XXX.FROM_SITE
           , XXX.PIC
           , XXX.USER_ID
        FROM
        (
            SELECT   NVL(FN_GET_SCM_SITE_DESCRIPTION('40', MODEL_PIC.FROM_SITE), MODEL_PIC.FROM_SITE) AS SITE_DESCRIPTION
                   , MODEL_PIC.FROM_SITE
                   , MODEL_PIC.MODEL
                   , MODEL_PIC.PIC
                   , MODEL_PIC.USER_ID
                   , NVL(SCS_STOCK.QTY, 0) AS QTY
            FROM
            (
                SELECT FROM_SITE
                      ,ITEM_ID AS MODEL

                      ,CASE WHEN P_LANGUAGE = 'KO'
                            THEN CASE WHEN U.USERNAME   IS NULL OR A.USER_ID IS NULL THEN NULL
                                      ELSE U.USERNAME   || '(' || A.USER_ID || ')' END
                            ELSE CASE WHEN U.USERNAME_E IS NULL OR A.USER_ID IS NULL THEN NULL
                                      ELSE U.USERNAME_E || '(' || A.USER_ID || ')' END
                       END AS PIC
                      ,A.USER_ID
                 FROM(
                        SELECT SI.SCM_SITE_ID FROM_SITE
                              ,SI.ITEM_ID
                              ,MU.USER_ID
                              /* ,MU.VALID_YN */
                        FROM SCM_MST_SITE_ITEM SI
                            JOIN SCM_MST_SITE  FS ON FS.DIVISION_ID = V_DIVISION_ID AND FS.OPERATION_GROUP = V_OPERATION_GROUP
                                                              AND FS.DIVISION_ID = SI.DIVISION_ID AND  FS.SCM_SITE_ID = SI.SCM_SITE_ID AND  FS.SITE_TYPE  = 'PLANT' AND FS.VALID_YN = 'Y'
                            LEFT OUTER JOIN SSP_MST_MODEL_USER MU ON MU.DIVISION_ID = SI.DIVISION_ID AND MU.FROM_SITE = SI.SCM_SITE_ID AND MU.ITEM_ID = SI.ITEM_ID
                        WHERE 1=1
                        GROUP BY FS.OPERATION_GROUP, SI.SCM_SITE_ID, SI.ITEM_ID, MU.USER_ID
                        /* GROUP BY SI.DIVISION_ID, FS.OPERATION_GROUP, SI.SCM_SITE_ID, SI.ITEM_ID, MU.USER_ID, MU.PART_LEADER, MU.TEAM_LEADER, MU.VALID_YN */
                 ) A
                LEFT OUTER JOIN TB_FX_USER U ON U.USERID = A.USER_ID
                /* WHERE a.VALID_YN = 'Y' */
            ) MODEL_PIC
            LEFT OUTER JOIN
            (
                SELECT PACKER_CODE, SUM(STOCK_QTY) AS QTY
                  FROM SCM_DNM_SCS_STOCK
                 WHERE 1 = 1
                   AND CUTOFF_DATE = V_CUTOFF_DATE
                   AND DIVISION_ID = V_DIVISION_ID
                   AND CELL_PACK = V_OPERATION_GROUP
                 GROUP BY PACKER_CODE
            ) SCS_STOCK
               ON MODEL_PIC.FROM_SITE = SCS_STOCK.PACKER_CODE
        ) XXX
        WHERE 1 = 1
          AND XXX.QTY <= 0
          AND XXX.PIC IS NOT NULL
        GROUP BY XXX.SITE_DESCRIPTION, XXX.FROM_SITE, XXX.PIC, XXX.USER_ID;

        /* 세로데이터를 가로로 만든다(MODEL_PIC)
           MSSQL STUFF((SELECT ','+MODEL_PIC ... FOR XML PATH('')),1,1,'') → Oracle LISTAGG(raw, XML 이스케이프 미재현) */
        INSERT INTO GT_SSPNRB_RESULT_2
        (
            PACKER
          , PACKER_CODE
          , MAIL_RECEIVER
          , MODEL_PIC
        )
        SELECT A.PACKER, A.PACKER_CODE, A.MAIL_RECEIVER, A.MODEL_PIC FROM
        (
            SELECT PACKER, PACKER_CODE, USER_ID AS MAIL_RECEIVER, (SELECT LISTAGG(T.MODEL_PIC, ',') WITHIN GROUP (ORDER BY T.MODEL_PIC)
                                    FROM GT_SSPNRB_RESULT_1 T WHERE T.PACKER = A.PACKER AND T.PACKER_CODE = A.PACKER_CODE
                                    ) AS MODEL_PIC FROM GT_SSPNRB_RESULT_1 A
        ) A GROUP BY A.PACKER, A.PACKER_CODE, A.MAIL_RECEIVER, A.MODEL_PIC;


        /* LOOK UP 테이블을 조인하여 최종 메일보낼 데이터를 만든다. */
        INSERT INTO GT_SSPNRB_MAILSEND_P
        (
            PACKER
          , PACKER_CODE
  		  , MODEL_PIC
          , MAIL_RECEIVER
        )
        SELECT PACKER, PACKER_CODE, MODEL_PIC, MAIL_RECEIVER FROM
        (
            SELECT PACKER, PACKER_CODE, MODEL_PIC, MAIL_RECEIVER FROM GT_SSPNRB_RESULT_2

            UNION ALL

            SELECT A.PACKER, A.PACKER_CODE, A.MODEL_PIC, M.SEGMENT2 AS MAIL_RECEIVER FROM SCM_ADM_LOOKUP_MASTER_DETAIL M , GT_SSPNRB_RESULT_2 A
            WHERE  M.LOOKUP_TYPE ='WARNING_MAIL_SEND_SCSBOH_40'
                AND  M.VALID_YN    ='Y'
                AND  M.SEGMENT1    ='SSP'
             GROUP BY A.PACKER, A.PACKER_CODE, A.MODEL_PIC, M.SEGMENT2
        ) A
        WHERE 1 = 1
        ;

        /* GT_SSPNRB_MAILSEND_P 에서 메일을 보내기 위해 DENSE_RANK()를 만든다.  MAIL_RECEIVER 별로 */
        INSERT INTO GT_SSPNRB_MAILSEND
        (
            RECEIVER_NUM
          , PACKER
          , PACKER_CODE
  		  , MODEL_PIC
          , MAIL_RECEIVER
        )
        SELECT DENSE_RANK() OVER (ORDER BY MAIL_RECEIVER) AS RECEIVER_NUM, PACKER, PACKER_CODE, MODEL_PIC, MAIL_RECEIVER
         FROM GT_SSPNRB_MAILSEND_P ORDER BY MAIL_RECEIVER, PACKER, MODEL_PIC;

        /* SELECT * FROM #TMP_RESULT_TABLE_1; */
        /* SELECT * FROM #TMP_MAILSEND_TABLE ORDER BY RECEIVER_NUM; */

        /* 루프를 돌면서 메일을 보내면 된다. */
        V_SEND_TMPCNT := 0;

        SELECT
            MAX(RECEIVER_NUM)
          INTO V_SEND_CNT
        FROM GT_SSPNRB_MAILSEND
        WHERE 1 = 1 ;

        WHILE V_SEND_TMPCNT < V_SEND_CNT
        LOOP
            /********************************************************************************
            * HEAD CONT
            ********************************************************************************/
            V_HEAD_CONT := '';
            V_HEAD_CONT := V_HEAD_CONT || '<tr>';

            V_HEAD_CONT := V_HEAD_CONT || '<th>' || 'Cut off date' || '</th>';
            V_HEAD_CONT := V_HEAD_CONT || '<th>' || 'Packer' || '</th>';
            V_HEAD_CONT := V_HEAD_CONT || '<th>' || 'Packer code' || '</th>';
            V_HEAD_CONT := V_HEAD_CONT || '<th>' || 'Model PIC' || '</th>';
            V_HEAD_CONT := V_HEAD_CONT || '<th>' || 'Dead line' || '</th>';

            V_HEAD_CONT := V_HEAD_CONT || '</tr>';

            V_MAIL_TITLE := '[SSP_Stock_Warning] Yesterday BOH has not been received.';
            V_BODY_CONTENTS := 'The BOH(Beginning On Hand) of the previous day has not been received until now. Encourage Packer to upload daily inventory. If stock is not received, it is not possible to change SSP shipping plan.
								';
            V_BODY_CONT := '';

            V_SEND_TMPCNT := V_SEND_TMPCNT + 1;

            SELECT
                MAX(MAIL_RECEIVER)
              INTO V_MAIL_RECEIVER
            FROM GT_SSPNRB_MAILSEND
            WHERE 1 = 1
              AND RECEIVER_NUM = V_SEND_TMPCNT		 /* V_SEND_TMPCNT 메일받는사람수 */
            ;

            V_TO_MAIL := V_MAIL_RECEIVER || '@lgensol.com';
            /* SET @v_to_mail = 'corewhite11@lgespartner.com';  -- 테스트용 */
            /* ================================================================ */


            FOR R_SEND IN (
                SELECT
                    PACKER
                  , PACKER_CODE
                  , MODEL_PIC
                  , MAIL_RECEIVER
                FROM GT_SSPNRB_MAILSEND
                WHERE 1 = 1
                  AND RECEIVER_NUM = V_SEND_TMPCNT
                ORDER BY PACKER, PACKER_CODE, MODEL_PIC, MAIL_RECEIVER
            )
            LOOP
                V_PACKER        := R_SEND.PACKER;
                V_PACKER_CODE   := R_SEND.PACKER_CODE;
                V_MODEL_PIC     := R_SEND.MODEL_PIC;
                V_MAIL_RECEIVER := R_SEND.MAIL_RECEIVER;

                V_BODY_CONT := V_BODY_CONT || '<tr>';

                V_BODY_CONT := V_BODY_CONT || '<td align=''center''>' || REPLACE(V_DIS_CUTOFF_DATE, CHR(10),' ') || '</td>';
                V_BODY_CONT := V_BODY_CONT || '<td align=''center''>' || REPLACE(V_PACKER, CHR(10),' ') || '</td>';
                V_BODY_CONT := V_BODY_CONT || '<td align=''center''>' || REPLACE(V_PACKER_CODE, CHR(10),' ') || '</td>';
                V_BODY_CONT := V_BODY_CONT || '<td align=''left''>' || REPLACE(V_MODEL_PIC, CHR(10),' ') || '</td>';
                V_BODY_CONT := V_BODY_CONT || '<td align=''left''>' || REPLACE(V_DEAD_LINE, CHR(10),' ') || '</td>';

                V_BODY_CONT := V_BODY_CONT || '</tr>';

            END LOOP;

            V_TABLE_BODY := '';
            V_TABLE_BODY := ' <html>
								<head>
										<title>Untitled Document</title>
										<style>
											* {margin:0;padding:0;}
											body {font-family:Malgun Gothic, Arial, Helvetica, sans-serif;font-size:12px;line-height:1.8;color:#333333;}
											table {border-collapse:collapse;width:100%;}
											table th {background:#f5f5f5;border-bottom:1px solid #e1e1e1;}
											table td {background:#fff;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1;border-bottom:1px solid #e1e1e1;}
											table tbody th {border-left:1px solid #e1e1e1;text-align:right;padding:6px 8px;font-size:12px}
											table tbody td {padding:6px 8px;font-size:12px}
											table thead th {text-align:center;padding:3px;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1; border-bottom:1px solid #d1d1d1;font-size:12px}
											.hori-table table thead td {text-align:center;padding:3px;}
											.hori-table table tbody td {text-align:center;padding:3px;}
											.vertical-table, .hori-table {margin-bottom:20px;}
										</style>
										</head>
										<body>' || '</br>' ||
												'<b>' || REPLACE(V_BODY_CONTENTS, CHR(10), '<br>') || '</b>' ||
												'<div id="divBody" style="width: 100%; overflow-x: auto; overflow-y: auto; font-size: 9pt; line-break: auto;">'    ||
											'<table style=''border-top:2px solid #c8294b; width:1150px;''>
											<thead>' || V_HEAD_CONT ||'</thead>
											<tbody>' || V_BODY_CONT || '</tbody>
											</div>
										</body>
								</html>';

                /*//메일 발송	일단 맊음	나중에 풀어야 된다. */
            SCM_ADM_MAIL_SEND(
                  V_TO_MAIL		/* 'corewhite11@lgespartner.com' -- @v_to_mail */
                , V_MAIL_TITLE
                , DBMS_LOB.SUBSTR(V_TABLE_BODY, 32767, 1)
                , 'Y'
            );

            SCM_ADM_SAVE_MAIL_SEND_BATCH_LOG('MAIL'
                            ,0
                            ,V_PROGRAM_NAME
                            ,V_MAIL_TITLE
                            ,V_DIVISION_ID
                            ,V_OPERATION_GROUP
                            ,V_MODEL_PIC
                            ,V_MAIL_RECEIVER
                            ,''
                            ,''
                            ,''
                            ,''
                            ,''
                            ,V_TO_MAIL);
                        /*//END : 메일 발송 */

            /* SELECT @v_to_mail, @v_mail_title, @v_body_cont, @TABLE_BODY; */
        END LOOP;

        V_LOG_TYPE    := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);


    EXCEPTION
        WHEN OTHERS THEN
        /* MSSQL : IF EXISTS (SELECT 1 FROM SYS.SYSCURSORS WHERE CURSOR_NAME = 'CUR_SEND') → CLOSE/DEALLOCATE CUR_SEND */


            ROLLBACK;

            DBMS_OUTPUT.PUT_LINE('STEP ERROR');

            BEGIN
                V_ERROR_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
                DBMS_OUTPUT.PUT_LINE(V_ERROR_MESSAGE);   /* print @v_error_message */

                INSERT INTO SCM_SYS_LOG_BATCH
                (
                    PROGRAM_NAME
                    , LOG_TYPE
                    , LOG_COUNT
                    , LOG_MESSAGE
                    , DESCRIPTION
                    , EVENT_DATE
                    , CREATION_DATE
                    , CREATED_BY
                    , LAST_UPDATE_DATE
                    , LAST_UPDATED_BY
                )
                VALUES
                (
                    V_PROGRAM_NAME
                    , 'ERROR'
                    , NULL
                    , V_ERROR_MESSAGE   /* ERROR_MESSAGE() */
                    , NULL
                    , SYSDATE
                    , SYSDATE
                    , V_PROGRAM_NAME
                    , SYSDATE
                    , V_PROGRAM_NAME
                );

                /* MAIL 발송 LOG 저장 */
                SCM_ADM_SAVE_MAIL_SEND_BATCH_LOG(
                    'ERROR'
                    , 0
                    , V_PROGRAM_NAME
                    , 'MAIN ERROR'
                    , ''
                    , ''
                    , ''
                    , ''
                    , ''
                    , ''
                    , ''
                    , ''
                    , V_ERROR_MESSAGE /* p_send_pgm */
                    , ''
                );
            END;

            /* error코드, errror 메시지 반환
               원본 naked SELECT 2건(result_code='F' / '['||ERROR_NUMBER()||']'||ERROR_MESSAGE()) */
            DBMS_OUTPUT.PUT_LINE('F');
            DBMS_OUTPUT.PUT_LINE('[' || TO_CHAR(SQLCODE) || ']' || SQLERRM);

            /* set @p_log_messge = @v_error_message; */

            /* return -1; */


    END;


    DELETE FROM GT_SSPNRB_RESULT_1;
    DELETE FROM GT_SSPNRB_RESULT_2;
    DELETE FROM GT_SSPNRB_MAILSEND_P;
    DELETE FROM GT_SSPNRB_MAILSEND;


    COMMIT;

    /* return 1; : MSSQL 반환코드(호출부 미사용) → Oracle 프로시저 반환값 없음 */
    RETURN;
END PR_SSP_MAIL_SEND_SCS_NORECEIVE_BOH;

PROCEDURE PR_SSP_MAIL_SEND_SHIP_PLAN_INTER_COM_PO

/*
 * Program ID   : PR_SSP_MAIL_SEND_SHIP_PLAN_INTER_COM_PO
 * Description  : SSP MAIL 발송 (PR_SSP_MAIL_SEND_SHIP_PLAN_INTER_COM_PO)
                  JOB.SSP_MAIL_SEND_SHIP_PLAN_INTER_COM_PO에서 호출 10분단위 호출 후 법인별 시업시간 기준 수행
 * Program History
 *===================================================================================================
 *   Date       In Charge		Description
 *===================================================================================================
 * 2020/07/13	juhlee			[PJ20199555]  공급 대응력 향상을 위한 자재재공 수급 점검 체계 개선
								 1. 발송 조건 :
								   - PO 미생성 된 Confirm된 Plan
								   - 현재일 ~ 현재일+3 (4일)
								   - 법인간거래 : TO_SITE가 PLANT (PACKER ,Warranty 포함)
								 2. 발송 주기
								   - Daily  법인별(TO SITE 기준) 시업시간 + 6시간 에 발송
								 3. 발송 대상(수신자)
								   - 전극 : Shipment Requestor PIC에 등록된 user
								   - 이외 : Look up 정보에 등록된 대상자 ( lookup명 :SHIP_PLAN_INTER_COM_MAIL_SEND )
											TO-SITE : ALL 설정 시 전극포함한 전체 수신
 * 2020/10/05	KIMYONGHO			'SHIP_PLAN_INTER_COM_MAIL_SEND' LOOKUP - FROM_SITE 추가
 * 2026.07.06	ZIONEX			[PJ202650304] NextSCM Migration
 *
 *  - 임시테이블 #TblSSPShip_Request_Mail -> GTT GT_SSP_SHIP_REQUEST_MAIL(ON COMMIT PRESERVE ROWS, 진입부 DELETE)
 *               (@profile_name 운영/개발 분기는 Oracle 무대응 -> 발송부 주석으로 원문 보존)
 */
AS


    /* [2026-07-23 결정] V_COMPANY_ID: LISTAGG 결과 저장 대상. 매칭 법인 다수 시 30자 초과 -> 전체배치 ORA-06502 방지 위해 4000 으로 확장(원본 NVARCHAR(30)) */
    V_COMPANY_ID              VARCHAR2(4000 CHAR) := '';

    V_MAIL_TITLE              VARCHAR2(100 CHAR);
    V_HEAD_CONT               VARCHAR2(32767 CHAR);
    V_BODY_CONT               VARCHAR2(32767 CHAR);
    V_BODY_TEXT               VARCHAR2(32767 CHAR);
    V_TO_MAIL                 VARCHAR2(32767 CHAR);
    V_TO_MAIL_BACK            VARCHAR2(32767 CHAR);

    V_TABLE_BODY              CLOB;
    V_MONTH_NAME              VARCHAR2(10 CHAR);

    V_MAIL_RECEIVER           VARCHAR2(600 CHAR);
    V_DIVISION_ID             VARCHAR2(30 CHAR);
    V_PO_NO                   VARCHAR2(50 CHAR);
    V_STATUS                  VARCHAR2(30 CHAR);
    V_ITEM_ID                 VARCHAR2(50 CHAR);
    V_NICK_NAME               VARCHAR2(100 CHAR);
    V_FROM_SITE               VARCHAR2(30 CHAR);
    V_FROM_SITE_DESCRIPTION   VARCHAR2(1000 CHAR);
    V_TO_SITE                 VARCHAR2(30 CHAR);
    V_TO_SITE_DESCRIPTION     VARCHAR2(1000 CHAR);
    V_SHIPMENT_QTY            VARCHAR2(32767 CHAR);
    V_YYYYMMDD                VARCHAR2(10 CHAR);
    V_TRANSPORT_MODE          VARCHAR2(50 CHAR);
    V_INCOTERMS               VARCHAR2(10 CHAR);
    V_LT_DAY                  VARCHAR2(10 CHAR);
    V_ETD_DATE                VARCHAR2(10 CHAR);
    V_EXP_SHIP_DATE           VARCHAR2(10 CHAR);
    V_ETA_DATE                VARCHAR2(10 CHAR);
    V_MODEL_PIC               VARCHAR2(302 CHAR);
    V_CONFIRM_ID              VARCHAR2(30 CHAR);

    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME            VARCHAR2(150 CHAR) := 'PR_SSP_MAIL_SEND_SHIP_PLAN_INTER_COM_PO';
    V_LOG_TYPE                VARCHAR2(30 CHAR);   /* START/END/ERROR/... */
    N_LOG_COUNT               INTEGER := 0;
    V_LOG_MESSAGE             VARCHAR2(1000 CHAR);
    V_DESCRIPTION             VARCHAR2(500 CHAR);
    D_EVENT_DATE              DATE;

    /* 계산용 변수 */
    V_RECEIVER_CNT            NUMBER := 0;	/* 총 수신자 명 */
    V_MAIL_DATA_CNT           NUMBER := 0;	/* 메일 Data 총 건수 */
    V_RECEIVER_LOOP_CNT       NUMBER := 0;	/* 수신자 비교 변수 */
    V_MAIL_DATA_LOOP_CNT      NUMBER := 0;	/* 메일 Data 비교 변수 */
    V_DATECHK                 NUMBER := 0;	/* 조정기간 Data 체크 건수 (원본 死변수 보존) */
    V_MAIL_CNT_CHK            NUMBER := 0;	/* 메일 View에 Data 있는지 체크 건수 (원본 死변수 보존) */
    V_MAILSENDCNT             NUMBER := 0;
    V_TMP_RECEIVER            VARCHAR2(32767 CHAR) := ''; /* 수신자 임시 변수 */


    V_SQLERRM                 VARCHAR2(4000 CHAR);
    V_ERROR_MESSAGE           VARCHAR2(1000 CHAR);   /* 원본 @v_error_message : 대입만 하고 사용처는 주석처리된 死변수 */

BEGIN


     /* 시업시간 추출 법인별 (TO_SITE 기준 법인) */
    /* 시업시간 + 6시간 후 메일 발송 */
    /* 10분위 수행시 07:0 까지 일치여부 확인 */
    /* SEGMENT2 = 법인별 시업시간 */
    /* FN_MULTY_TIME(SEGMENT3) 법인 현재 시간 */


    /* 원본 CONVERT(CHAR(8), SEGMENT2, 8) : 원천이 문자열이라 스타일 무시 = 선두 8자 -> 사용범위(1~4자)가 8자 이내이므로 SUBSTR 직접 사용 */
    SELECT LISTAGG(TT.COMPANY_ID, ',') WITHIN GROUP (ORDER BY TT.COMPANY_ID)
    INTO   V_COMPANY_ID
    FROM (
            SELECT SEGMENT4 AS COMPANY_ID
            FROM   SCM_ADM_LOOKUP_MASTER_DETAIL
            WHERE  LOOKUP_TYPE = 'BASIS_START_TIME_PLANT'
            AND    TO_CHAR(FN_MULTY_TIME(SEGMENT3), 'YYYYMMDD') = TO_CHAR(SYSDATE, 'YYYYMMDD')
            /* 시업시간 + 6시간 =  법인 현재시간 */

            AND    SUBSTR('00' || TO_CHAR(TO_NUMBER(SUBSTR(SEGMENT2, 1, 2)) + 6), -2) || SUBSTR(SEGMENT2, 3, 2)
                  =  SUBSTR(TO_CHAR(FN_MULTY_TIME(SEGMENT3), 'HH24:MI:SS'), 1, 4) /* 법인 현재시간 */
            GROUP BY SEGMENT4
        ) TT;


    /* V_COMPANY_ID := 'C100'; */

    /* 시업시간과 일치하지 않으면 미수행 */
    IF V_COMPANY_ID IS  NULL
    THEN
        RETURN  ;
    END IF;


    /* 임시Table 삭제------------------------------------------------- */
    /* 원본 IF OBJECT_ID('tempdb..#TblSSPShip_Request_Mail') IS NOT NULL DROP TABLE #TblSSPShip_Request_Mail */

    DELETE FROM GT_SSP_SHIP_REQUEST_MAIL;
    /* --------------------------------------------------------------- */

    /* 메일 수신자별 Index Data Temp Table------------------------------------------------------------------ */
    INSERT INTO GT_SSP_SHIP_REQUEST_MAIL
    ( RECEIVER_NUM, DATA_NUM, MAIL_RECEIVER, COMPANY_ID, DIVISION_ID, PO_NO, STATUS
    , ITEM_ID, NICK_NAME, FROM_SITE, FROM_SITE_DESCRIPTION, TO_SITE, TO_SITE_DESCRIPTION
    , QTY, YYYYMMDD, TRANSPORT_MODE, INCOTERMS, LT_DAY, ETD_DATE, EXP_SHIP_DATE, ETA_DATE
    , MODEL_PIC_USER_NAME, CONFIRM_ID )
    SELECT
        T0.RECEIVER_NUM
    ,   T0.DATA_NUM
    ,   T0.MAIL_RECEIVER
    ,   T0.COMPANY_ID
    ,   T0.DIVISION_ID
    ,   T0.PO_NO
    ,   T0.STATUS
    ,   T0.ITEM_ID
    ,   T0.NICK_NAME
    ,   T0.FROM_SITE
    ,   T0.FROM_SITE_DESCRIPTION
    ,   T0.TO_SITE
    ,   T0.TO_SITE_DESCRIPTION
    ,   T0.QTY
    ,   T0.YYYYMMDD
    ,   T0.TRANSPORT_MODE
    ,   T0.INCOTERMS
    ,   T0.LT_DAY
    ,   T0.ETD_DATE
    ,   T0.EXP_SHIP_DATE
    ,   T0.ETA_DATE
    ,   T0.MODEL_PIC_USER_NAME
    ,   T0.CONFIRM_ID
    FROM
    (

            SELECT DISTINCT
                   DENSE_RANK() OVER (ORDER BY X.MAIL_RECEIVER) AS RECEIVER_NUM
            ,      ROW_NUMBER() OVER (PARTITION BY X.MAIL_RECEIVER ORDER BY X.MAIL_RECEIVER, X.DIVISION_ID,X.COMPANY_ID, X.TO_SITE, X.ITEM_ID,X.YYYYMMDD , X.FROM_SITE,   X.TRANSPORT_MODE , X.INCOTERMS ) AS DATA_NUM
            ,      X.MAIL_RECEIVER
            ,      X.COMPANY_ID
            ,      X.DIVISION_ID
            ,      X.PO_NO
            ,      X.STATUS
            ,      X.ITEM_ID
            ,      X.NICK_NAME
            ,      X.FROM_SITE
            ,      X.FROM_SITE_DESCRIPTION
            ,      X.TO_SITE
            ,      X.TO_SITE_DESCRIPTION
            ,      X.QTY
            ,      X.YYYYMMDD
            ,      X.TRANSPORT_MODE
            ,      X.INCOTERMS
            ,      X.LT_DAY
            ,      X.ETD_DATE
            ,      X.EXP_SHIP_DATE
            ,      X.ETA_DATE
            ,      X.MODEL_PIC_USER_NAME
            ,      X.CONFIRM_ID
            FROM (
                    /* 전극 대상 - 수신자 : Shipment Requestor PIC(SSP_MST_MODEL_USER_EE) */
                    SELECT EM.USER_ID          AS MAIL_RECEIVER
                    ,      TS.COMPANY_ID       AS COMPANY_ID /* TO Site기준 */
                    ,      C.DIVISION_ID       AS DIVISION_ID
                    ,      C.ERP_SO_NO         AS PO_NO
                    ,      'Confirm'           AS STATUS
                    ,      C.ITEM_ID
                    ,      FN_GET_ITEM_NICKNAME(C.DIVISION_ID, C.ITEM_ID) AS NICK_NAME
                    ,      C.FROM_SITE
                    ,      FS.SITE_DESCRIPTION  AS FROM_SITE_DESCRIPTION
                    ,      C.TO_SITE
                    ,      TS.SITE_DESCRIPTION  AS TO_SITE_DESCRIPTION
                    ,      C.QTY
                    ,      C.YYYYMMDD
                    ,      C.TRANSPORT_MODE
                    ,      C.INCOTERMS
                    ,      C.CUSTOMER_LT     AS LT_DAY
                    ,      C.ETD_DATE
                    ,      FN_GET_SSP_EXPECTED_SHIP_DATE(C.DIVISION_ID, C.BOD_ID, C.YYYYMMDD)     AS EXP_SHIP_DATE
                    ,      C.ETA_DATE
                    ,      AM.USER_ID     AS MODEL_PIC_USER_ID /* 모델 담당자 */

                    ,      CASE WHEN AU.USERNAME IS NULL OR AM.USER_ID IS NULL THEN NULL
                                ELSE AU.USERNAME ||'('|| AM.USER_ID ||')' END AS MODEL_PIC_USER_NAME /*  모델 담당자 */
                    ,      C.CONFIRM_ID
                    ,      C.BIZ_TYPE
                    ,      C.ORIGIN_FROM_DIVISION_ID
                    ,      C.ORIGIN_TO_DIVISION_ID

                    FROM   SSP_ANL_SHIP_CONFIRM C
                        JOIN SCM_MST_SITE FS
                          ON FS.DIVISION_ID = C.ORIGIN_FROM_DIVISION_ID
                         AND FS.SCM_SITE_ID = C.FROM_SITE

                        JOIN SCM_MST_SITE TS
                          ON TS.DIVISION_ID = C.ORIGIN_TO_DIVISION_ID
                         AND TS.SCM_SITE_ID = C.TO_SITE
                         AND TS.SITE_TYPE   = 'PLANT' /* 법인간거래 (PACKER ,Warranty 포함) */

                        JOIN SSP_MST_MODEL_USER_EE EM  /* 전극 Requestor 담당자 (전극 메일 수신자) */
                          ON EM.DIVISION_ID = C.ORIGIN_TO_DIVISION_ID
                         AND EM.TO_SITE     = C.TO_SITE
                         AND EM.ITEM_ID     = C.ITEM_ID
                         AND EM.VALID_YN    = 'Y'

                        LEFT OUTER JOIN SSP_MST_MODEL_USER AM    /* 모델 담당자 */
                          ON AM.DIVISION_ID = C.ORIGIN_FROM_DIVISION_ID
                         AND AM.FROM_SITE   = C.FROM_SITE
                         AND AM.ITEM_ID     = C.ITEM_ID
                         AND AM.VALID_YN    = 'Y'

                        LEFT OUTER JOIN TB_FX_USER AU
                          ON AU.USERID = AM.USER_ID
                         AND AU.USEYN = 'Y'

                    WHERE  1=1
                    AND    C.CHANGE_TYPE ='C'
                    AND    C.QTY > 0
                    AND    C.YYYYMMDD >= TO_CHAR(SYSDATE, 'YYYYMMDD')
                    AND    C.YYYYMMDD <= TO_CHAR(SYSDATE + 3, 'YYYYMMDD')
                    AND    NVL(C.ERP_STATUS,'B') = 'B'  /* SO/PO 미 발행 대상: null, B ( ERP STATUS : A:SO/PO 생성 , B:SO/PO 취소, C:DO생성 , D:DO취소 ) */
                    AND    C.BIZ_TYPE = 'E'

                    UNION ALL
                    /* 전극 포함 - (수신자 : lookup 등록 SHIP_PLAN_INTER_COM_MAIL_SEND ) */
                    SELECT L.SEGMENT2          AS MAIL_RECEIVER
                    ,      TS.COMPANY_ID       AS COMPANY_ID /* TO Site기준 */
                    ,      C.DIVISION_ID       AS DIVISION_ID
                    ,      C.ERP_SO_NO         AS PO_NO
                    ,      'Confirm'           AS STATUS
                    ,      C.ITEM_ID
                    ,      FN_GET_ITEM_NICKNAME(C.DIVISION_ID, C.ITEM_ID) AS NICK_NAME
                    ,      C.FROM_SITE
                    ,      FS.SITE_DESCRIPTION  AS FROM_SITE_DESCRIPTION
                    ,      C.TO_SITE
                    ,      TS.SITE_DESCRIPTION  AS TO_SITE_DESCRIPTION
                    ,      C.QTY
                    ,      C.YYYYMMDD
                    ,      C.TRANSPORT_MODE
                    ,      C.INCOTERMS
                    ,      C.CUSTOMER_LT   AS LT_DAY
                    ,      C.ETD_DATE
                    ,      FN_GET_SSP_EXPECTED_SHIP_DATE(C.DIVISION_ID, C.BOD_ID, C.YYYYMMDD)     AS EXP_SHIP_DATE
                    ,      C.ETA_DATE
                    ,      AM.USER_ID                         AS MODEL_PIC_USER_ID    /*  모델 담당자 */
                    ,      CASE WHEN AU.USERNAME IS NULL OR AM.USER_ID IS NULL THEN NULL
                                ELSE AU.USERNAME ||'('|| AM.USER_ID ||')' END  AS MODEL_PIC_USER_NAME /* 모델 담당자 */
                    ,      C.CONFIRM_ID
                    ,      C.BIZ_TYPE
                    ,      C.ORIGIN_FROM_DIVISION_ID
                    ,      C.ORIGIN_TO_DIVISION_ID

                    FROM  SSP_ANL_SHIP_CONFIRM C
                        JOIN SCM_MST_SITE FS
                          ON FS.DIVISION_ID = C.ORIGIN_FROM_DIVISION_ID
                         AND FS.SCM_SITE_ID = C.FROM_SITE

                        JOIN SCM_MST_SITE TS
                          ON TS.DIVISION_ID = C.ORIGIN_TO_DIVISION_ID
                         AND TS.SCM_SITE_ID = C.TO_SITE
                         AND TS.SITE_TYPE   = 'PLANT' /* 법인간거래 (PACKER ,Warranty 포함) */

                        JOIN SCM_ADM_LOOKUP_MASTER_DETAIL L   /* lookup 등록 메일 수신자 */
                          ON  L.LOOKUP_TYPE ='SHIP_PLAN_INTER_COM_MAIL_SEND'
                         AND  L.VALID_YN    ='Y'
                         AND  L.SEGMENT3    = CASE WHEN L.SEGMENT3 = 'ALL' THEN 'ALL' ELSE C.TO_SITE END /* ALL일경우 전체 대상 */
                         /* * 2020/10/05	KIMYONGHO			'SHIP_PLAN_INTER_COM_MAIL_SEND' LOOKUP - FROM_SITE 추가 */
                         AND  L.SEGMENT4    = CASE WHEN L.SEGMENT4 = 'ALL' THEN 'ALL' ELSE C.FROM_SITE END /* ALL일경우 전체 대상 */
                        LEFT OUTER JOIN SSP_MST_MODEL_USER AM    /* 모델 담당자 */
                          ON AM.DIVISION_ID = C.ORIGIN_FROM_DIVISION_ID
                         AND AM.FROM_SITE   = C.FROM_SITE
                         AND AM.ITEM_ID     = C.ITEM_ID
                         AND AM.VALID_YN    = 'Y'

                        LEFT OUTER JOIN TB_FX_USER AU
                          ON AU.USERID = AM.USER_ID
                         AND AU.USEYN = 'Y'


                    WHERE  1=1
                    AND    C.CHANGE_TYPE ='C'
                    AND    C.QTY > 0
                    AND    C.YYYYMMDD >= TO_CHAR(SYSDATE, 'YYYYMMDD')
                    AND    C.YYYYMMDD <= TO_CHAR(SYSDATE + 3, 'YYYYMMDD')
                    AND    NVL(C.ERP_STATUS,'B') = 'B'  /* SO/PO 미 발행 대상: null, B ( ERP STATUS : A:SO/PO 생성 , B:SO/PO 취소, C:DO생성 , D:DO취소 ) */

            ) X
            WHERE 1=1
            AND   X.COMPANY_ID  IN ( SELECT TOKEN FROM TABLE(UF_FX_STRING_SPLIT(V_COMPANY_ID,',')) )
        /*	AND   X.MAIL_RECEIVER in ( 'juhlee' ,'kimkwanghee', 'kimbk1','kimyh8848') */

    ) T0;


    /* TEST */
    /* SELECT * FROM GT_SSP_SHIP_REQUEST_MAIL; */
    /* ---------------------------------------------------------------------------------- */

    /********************************************************************************
    * MAIL TITLE
    ********************************************************************************/
    V_MAIL_TITLE	 := '[Notice] Inter-company trade PO requestment';
    /********************************************************************************/

    /********************************************************************************
    * HEAD CONT
    ********************************************************************************/

    V_HEAD_CONT := '';
    V_HEAD_CONT := V_HEAD_CONT|| '<tr>';
    V_HEAD_CONT := V_HEAD_CONT|| '<th>' || 'Div' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT|| '<th>' || 'PO No' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT|| '<th>' || 'Status' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT|| '<th>' || 'Model' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT|| '<th>' || 'Nick Name' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT|| '<th width=''110px''>' || 'From Site' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT|| '<th width=''120px''>' || 'To Site' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT|| '<th width=''85px''>' || 'Shipment Qty' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT|| '<th width=''85px''>' || 'Shipment Date' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT|| '<th width=''45px''>' || 'Trans Mode' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT|| '<th>' || 'Incoterms' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT|| '<th>' || 'L/T(Day)' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT|| '<th width=''85px''>' || 'ETD' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT|| '<th width=''85px''>' || 'Expected Shipping Date' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT|| '<th width=''85px''>' || 'ETA' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT|| '<th>' || 'Model PIC' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT|| '<th>' || 'Confirm ID' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT|| '</tr>';


    /********************************************************************************/

    /********************************************************************************
    * CONT
    ********************************************************************************/
    V_BODY_TEXT	 :=
                          'The shipment Plan for inter-company trade Items have been confirm as follows
                            But, The PO has not been created yet. Please check the shipment plan and create PO.
                            Thank you
                            Best regards

							';
    V_BODY_CONT := '';
    /********************************************************************************/

    SELECT
        MAX(RECEIVER_NUM)
    INTO   V_RECEIVER_CNT
    FROM GT_SSP_SHIP_REQUEST_MAIL;


        /* 시작 LOG */
        V_LOG_TYPE := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        /* Loop 시작 */
        WHILE V_RECEIVER_CNT > V_RECEIVER_LOOP_CNT
        LOOP
            IF V_MAILSENDCNT=10 THEN
                DBMS_SESSION.SLEEP(5); /* FIVE seconds (원본 WAITFOR DELAY '00:00:05') */
                V_MAILSENDCNT := 0;	/* 10건 전송시마다 5초의 딜레이를 준 후 건수 초기화 */
            END IF;
            V_RECEIVER_LOOP_CNT := V_RECEIVER_LOOP_CNT + 1;

            V_MAIL_DATA_LOOP_CNT := 0;

            /* 원본 SELECT @v_tmp_receiver = MAIL_RECEIVER, @v_mail_data_cnt = MAX(Data_Num) ... GROUP BY MAIL_RECEIVER */

            BEGIN
                SELECT
                    MAIL_RECEIVER, MAX(DATA_NUM)
                INTO   V_TMP_RECEIVER, V_MAIL_DATA_CNT
                FROM GT_SSP_SHIP_REQUEST_MAIL
                WHERE RECEIVER_NUM = V_RECEIVER_LOOP_CNT
                GROUP BY MAIL_RECEIVER;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN NULL;
            END;


            V_TO_MAIL := CASE WHEN V_TMP_RECEIVER IS NULL THEN NULL ELSE V_TMP_RECEIVER||'@lgensol.com' END;

            V_TABLE_BODY := '';
            V_TABLE_BODY := '
			<html>
				<head>
					<title>Untitled Document</title>
					<meta charset="UTF-8">
					<style>
						* {margin:0;padding:0;}
						body {font-family:Malgun Gothic, Arial, Helvetica, sans-serif;font-size:12px;line-height:1.8;color:#333333;}
						table {border-collapse:collapse;width:100%;}
						table th {background:#f5f5f5;border-bottom:1px solid #e1e1e1;}
						table td {background:#fff;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1;border-bottom:1px solid #e1e1e1;}
						table tbody th {border-left:1px solid #e1e1e1;text-align:right;padding:6px 8px;font-size:12px}
						table tbody td {padding:6px 8px;font-size:12px}
						table thead th {text-align:center;padding:3px;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1; border-bottom:1px solid #d1d1d1;font-size:12px}
						.hori-table table thead td {text-align:center;padding:3px;}
						.hori-table table tbody td {text-align:center;padding:3px;}
						.vertical-table, .hori-table {margin-bottom:20px;}
					</style>
				</head>
				<body>' ||'</br>'||
					'<b>' || REPLACE(V_BODY_TEXT, CHR(10), '<br>') || '</b>' ||
						'<div id="divBody" style="width: 100%; overflow-x: auto; overflow-y: auto; font-size: 9pt; line-break: auto;">' ||
							'<table style=''border-top:2px solid #c8294b; width:1600px;''>
								<thead>' || V_HEAD_CONT ||'</thead> ';

            WHILE V_MAIL_DATA_CNT > V_MAIL_DATA_LOOP_CNT
            LOOP
                V_MAIL_DATA_LOOP_CNT := V_MAIL_DATA_LOOP_CNT + 1;


                BEGIN
                    SELECT
                          MAIL_RECEIVER
                        , DIVISION_ID
                        , PO_NO
                        , STATUS
                        , ITEM_ID
                        , NICK_NAME
                        , FROM_SITE
                        , FROM_SITE_DESCRIPTION
                        , TO_SITE
                        , TO_SITE_DESCRIPTION
                        , QTY
                        , CASE WHEN YYYYMMDD IS NULL THEN NULL
                               ELSE SUBSTR(YYYYMMDD, 1, 4) || '-' || SUBSTR(YYYYMMDD, 5, 2) || '-' || SUBSTR(YYYYMMDD, 7, 2) END
                        , TRANSPORT_MODE
                        , INCOTERMS
                        , LT_DAY
                        , CASE WHEN ETD_DATE IS NULL THEN NULL
                               ELSE SUBSTR(ETD_DATE     , 1, 4) || '-' || SUBSTR(ETD_DATE     , 5, 2) || '-' || SUBSTR(ETD_DATE     , 7, 2) END
                        , CASE WHEN EXP_SHIP_DATE IS NULL THEN NULL
                               ELSE SUBSTR(EXP_SHIP_DATE, 1, 4) || '-' || SUBSTR(EXP_SHIP_DATE, 5, 2) || '-' || SUBSTR(EXP_SHIP_DATE, 7, 2) END
                        , CASE WHEN ETA_DATE IS NULL THEN NULL
                               ELSE SUBSTR(ETA_DATE     , 1, 4) || '-' || SUBSTR(ETA_DATE     , 5, 2) || '-' || SUBSTR(ETA_DATE     , 7, 2) END
                        , MODEL_PIC_USER_NAME
                        , CONFIRM_ID
                    INTO
                          V_MAIL_RECEIVER
                        , V_DIVISION_ID
                        , V_PO_NO
                        , V_STATUS
                        , V_ITEM_ID
                        , V_NICK_NAME
                        , V_FROM_SITE
                        , V_FROM_SITE_DESCRIPTION
                        , V_TO_SITE
                        , V_TO_SITE_DESCRIPTION
                        , V_SHIPMENT_QTY
                        , V_YYYYMMDD
                        , V_TRANSPORT_MODE
                        , V_INCOTERMS
                        , V_LT_DAY
                        , V_ETD_DATE
                        , V_EXP_SHIP_DATE
                        , V_ETA_DATE
                        , V_MODEL_PIC
                        , V_CONFIRM_ID
                    FROM GT_SSP_SHIP_REQUEST_MAIL
                    WHERE 1 = 1
                      AND RECEIVER_NUM = V_RECEIVER_LOOP_CNT
                      AND DATA_NUM = V_MAIL_DATA_LOOP_CNT;
                EXCEPTION
                    WHEN NO_DATA_FOUND THEN NULL;
                END;


                V_BODY_CONT := '';
                V_BODY_CONT := V_BODY_CONT|| '<tr>' || CHR(13);
                V_BODY_CONT := V_BODY_CONT|| '<td>' || REPLACE(V_DIVISION_ID, CHR(10),' ') || '</td>';
                V_BODY_CONT := V_BODY_CONT|| '<td>' || REPLACE(V_PO_NO, CHR(10),' ') || '</td>';
                V_BODY_CONT := V_BODY_CONT|| '<td>' || REPLACE(V_STATUS, CHR(10),' ') || '</td>';
                V_BODY_CONT := V_BODY_CONT|| '<td>' || REPLACE(V_ITEM_ID, CHR(10),' ') || '</td>';
                V_BODY_CONT := V_BODY_CONT|| '<td>' || REPLACE(V_NICK_NAME, CHR(10),' ') || '</td>';
                V_BODY_CONT := V_BODY_CONT|| '<td>' || REPLACE(V_FROM_SITE_DESCRIPTION, CHR(10),' ') || '</td>';
                V_BODY_CONT := V_BODY_CONT|| '<td>' || REPLACE(V_TO_SITE_DESCRIPTION, CHR(10),' ') || '</td>';

                V_BODY_CONT := V_BODY_CONT|| '<td align=''right''>' || REPLACE(REPLACE(TO_CHAR(TO_NUMBER(V_SHIPMENT_QTY), 'FM999,999,999,999,990.00'), '.00', ''), CHR(10),' ') || '</td>';
                V_BODY_CONT := V_BODY_CONT|| '<td align=''center''>' || REPLACE(V_YYYYMMDD, CHR(10),' ') || '</td>';
                V_BODY_CONT := V_BODY_CONT|| '<td align=''center''>' || REPLACE(V_TRANSPORT_MODE, CHR(10),' ') || '</td>';
                V_BODY_CONT := V_BODY_CONT|| '<td align=''center''>' || REPLACE(V_INCOTERMS, CHR(10),' ') || '</td>';
                V_BODY_CONT := V_BODY_CONT|| '<td align=''right''>'  || REPLACE(V_LT_DAY, CHR(10),' ') || '</td>';
                V_BODY_CONT := V_BODY_CONT|| '<td align=''center''>' || REPLACE(V_ETD_DATE , CHR(10),' ') || '</td>';
                V_BODY_CONT := V_BODY_CONT|| '<td align=''center''>' || REPLACE(V_EXP_SHIP_DATE, CHR(10),' ') || '</td>';
                V_BODY_CONT := V_BODY_CONT|| '<td align=''center''>' || REPLACE(V_ETA_DATE , CHR(10),' ') || '</td>';
                V_BODY_CONT := V_BODY_CONT|| '<td>' || REPLACE(V_MODEL_PIC, CHR(10),' ') || '</td>';
                V_BODY_CONT := V_BODY_CONT|| '<td>' || REPLACE(V_CONFIRM_ID, CHR(10),' ') || '</td>';
                V_BODY_CONT := V_BODY_CONT|| '</tr>';


                V_TABLE_BODY := V_TABLE_BODY ||  V_BODY_CONT || '' || CHR(13);

            END LOOP;		/* 메일 Data Loop End */
            V_TABLE_BODY := V_TABLE_BODY || '</br></tbody> </div> </body> </html>';

            /*                    @profile_name = 'GSCM_MAIL_PROD' --운영
                   --@profile_name = 'GSCM_MAIL_TEST'   -- 개발환경 */


            PKG_SEND_MAIL.P_SEND_MAIL_CLOB(V_TO_MAIL
                             ,V_MAIL_TITLE
                             ,V_TABLE_BODY
                             ,'Y'
                              );

            /* MAIL 발송 LOG 저장 */
            SCM_ADM_SAVE_MAIL_SEND_BATCH_LOG( 'MAIL'
                            ,0
                            ,V_PROGRAM_NAME
                            ,V_MAIL_TITLE
                            ,V_DIVISION_ID
                            ,V_FROM_SITE_DESCRIPTION
                            ,V_ITEM_ID
                            ,V_NICK_NAME
                            ,''
                            ,''
                            ,''
                            ,''
                            ,'' /* p_send_pgm */
                            ,V_TO_MAIL);

            V_MAILSENDCNT := V_MAILSENDCNT + 1;
        END LOOP;			/* 수신자 Loop End */
        /* 종료 LOG */
        V_LOG_TYPE := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);


    /* 임시테이블 삭제(원본 DROP TABLE #TblSSPShip_Request_Mail -> Oracle GTT는 DELETE로 정리) */
    DELETE FROM GT_SSP_SHIP_REQUEST_MAIL;


EXCEPTION
    WHEN OTHERS THEN
        V_SQLERRM := SQLERRM;


        V_DESCRIPTION := SUBSTR(V_PROGRAM_NAME || 'ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 500);

        INSERT INTO SCM_SYS_LOG_BATCH
        (
            PROGRAM_NAME,			LOG_TYPE,			LOG_COUNT,				LOG_MESSAGE
          , DESCRIPTION,			EVENT_DATE,			CREATION_DATE,			CREATED_BY
          , LAST_UPDATE_DATE,		LAST_UPDATED_BY
        )
        VALUES
        (
            V_PROGRAM_NAME,		    'ERROR',			NULL,					V_SQLERRM
          , V_DESCRIPTION,		    SYSDATE,			SYSDATE,				V_PROGRAM_NAME
          , SYSDATE,				V_PROGRAM_NAME
        );   /* 원본 ERROR_PROCEDURE() = 본 프로시저명, ERROR_MESSAGE() = SQLERRM */

        IF DBMS_TRANSACTION.LOCAL_TRANSACTION_ID IS NOT NULL THEN
            COMMIT;
        END IF;

        V_ERROR_MESSAGE := SUBSTR(V_SQLERRM,1,1000);

        /* MAIL 발송 LOG 저장 */
        SCM_ADM_SAVE_MAIL_SEND_BATCH_LOG( 'MAIL'
            ,0
            ,V_PROGRAM_NAME
            ,V_MAIL_TITLE
            ,V_DIVISION_ID
            ,V_FROM_SITE_DESCRIPTION
            ,V_ITEM_ID
            ,V_NICK_NAME
            ,''
            ,''
            ,''
            ,''
            ,'' /* p_send_pgm */
            ,V_TO_MAIL);

        IF DBMS_TRANSACTION.LOCAL_TRANSACTION_ID IS NOT NULL THEN
            COMMIT;
        END IF;
    /*	V_LOG_MESSGE := V_ERROR_MESSAGE; */
        RETURN;

END PR_SSP_MAIL_SEND_SHIP_PLAN_INTER_COM_PO;

PROCEDURE           "PR_SSP_MAIL_SEND_SHIP_REQ_DELETE" (
    P_COMPANY_ID1  IN  VARCHAR2
  , P_LOG_MESSGE   OUT VARCHAR2
)
/*
 * Program ID   : PR_SSP_MAIL_SEND_SHIP_REQ_DELETE
 * Description  : SSP MAIL 발송 (PR_SSP_MAIL_SEND_SHIP_REQ_DELETE)
 * Program History
 *===================================================================================================
 *   Date       In Charge		Description
 *===================================================================================================
 * 2019/10/01	mcTheJ			Initial Release [PJ20189106} 전지.GSCM 고도화 이행 PROJECT
 * 2026.07.06	ZIONEX			[PJ202650304] NextSCM Migration
--Exec PR_SSP_MAIL_SEND_SHIP_REQ_DELETE 'C100', '';
 */
AS
    V_MAIL_TITLE             VARCHAR2(200 CHAR);
    V_HEAD_CONT              VARCHAR2(4000 CHAR);
    V_BODY_TEXT              VARCHAR2(4000 CHAR);
    V_TABLE_BODY             CLOB;
    V_BODY_CONT              VARCHAR2(4000 CHAR);
    V_TO_MAIL                VARCHAR2(4000 CHAR);
    V_PROGRAM_NAME           VARCHAR2(150 CHAR) := 'PR_SSP_MAIL_SEND_SHIP_REQ_DELETE';
    V_LOG_TYPE               VARCHAR2(30 CHAR);
    N_LOG_COUNT              NUMBER := 0;
    V_LOG_MESSAGE            VARCHAR2(1000 CHAR);
    V_DESCRIPTION            VARCHAR2(500 CHAR);
    D_EVENT_DATE             DATE;
    V_MAILSENDCNT            NUMBER := 0;
    V_ERROR_MESSAGE          VARCHAR2(1000 CHAR);

    V_DIVISION_ID            VARCHAR2(120 CHAR);
    V_FROM_SITE_DESCRIPTION  VARCHAR2(4000 CHAR);
    V_ITEM_ID                VARCHAR2(200 CHAR);
    V_NICK_NAME              VARCHAR2(4000 CHAR);
BEGIN
    /* MAIL TITLE */
    V_MAIL_TITLE := '[Notice]Insufficient stock for shipment request is deleted today''s shipment confirm';


    V_BODY_TEXT := 'Despite entering the shipment confirm period. We are unable to make shipment plan for shipment request due to insufficient inventory levels.
							If you need to execute the shipment, please use shipment change requset.
							Please refer to below table, the following items are deleted due to insufficient stock levels.
							Thank you.
							Best regards.

							';

    /* HEAD CONT */
    V_HEAD_CONT := '<tr>'
        || '<th>' || 'Div' || '</th>'
        || '<th width=''100px''>' || 'From Site' || '</th>'
        || '<th>' || 'Model' || '</th>'
        || '<th>' || 'Nick Name' || '</th>'
        || '<th>' || 'Requestor' || '</th>'
        || '<th>' || 'To Site*' || '</th>'
        || '<th>' || 'End Customer*' || '</th>'
        || '<th>' || 'FCST Type*' || '</th>'
        || '<th>' || 'Incoterms*' || '</th>'
        || '<th>' || 'Trans Mode*' || '</th>'
        || '<th width=''100px''>' || 'Date' || '</th>'
        || '<th width=''90px''>' || 'Qty' || '</th>'
        || '</tr>';

    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := NULL;
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);


    FOR RCV IN ( SELECT   MAIL_RECEIVER
                   FROM   SSP_MAIL_SHIP_REQ_DELETE_V
                  WHERE   COMPANY_ID = P_COMPANY_ID1
                  GROUP BY MAIL_RECEIVER
                  ORDER BY MAIL_RECEIVER ) LOOP


        /* [2026-10-07] 발송 간 대기 삭제 (사용자 지시 2026-10-06).
         * ★이 건은 수신자마다 본문이 달라 묶음 발송 대상이 아니다 — 묶음과 무관하게 대기 로직 자체를 삭제하라는 지시다.
         * 원본 MSSQL 의 WAITFOR DELAY 는 그대로 둔다 — 원본을 고치는 게 아니라 Oracle 발송 방식에 맞춘 것이다.
         * 삭제한 블록 : IF V_MAILSENDCNT = 10 THEN DBMS_SESSION.SLEEP(5); V_MAILSENDCNT := 0; END IF; */

        V_TO_MAIL := RCV.MAIL_RECEIVER || '@lgensol.com';

        V_TABLE_BODY := '
			<html>
				<head>
					<title>Untitled Document</title>
					<meta charset="UTF-8">
					<style>
						* {margin:0;padding:0;}
						body {font-family:Malgun Gothic, Arial, Helvetica, sans-serif;font-size:12px;line-height:1.8;color:#333333;}
						table {border-collapse:collapse;width:100%;}
						table th {background:#f5f5f5;border-bottom:1px solid #e1e1e1;}
						table td {background:#fff;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1;border-bottom:1px solid #e1e1e1;}
						table tbody th {border-left:1px solid #e1e1e1;text-align:right;padding:6px 8px;font-size:12px}
						table tbody td {padding:6px 8px;font-size:12px}
						table thead th {text-align:center;padding:3px;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1; border-bottom:1px solid #d1d1d1;font-size:12px}
						.hori-table table thead td {text-align:center;padding:3px;}
						.hori-table table tbody td {text-align:center;padding:3px;}
						.vertical-table, .hori-table {margin-bottom:20px;}
					</style>
				</head>
				<body>' || '</br>' ||
            '<b>' || REPLACE(NVL(V_BODY_TEXT, ' '), CHR(10), '<br>') || '</b>' ||
            '<div id="divBody" style="width: 100%; overflow-x: auto; overflow-y: auto; font-size: 9pt; line-break: auto;">' ||
            '<table style=''border-top:2px solid #c8294b; width:1200px;''>
								<thead>' || NVL(V_HEAD_CONT, ' ') || '</thead> ';

        FOR D IN ( SELECT   DIVISION_ID
                          , FROM_SITE_DESCRIPTION
                          , ITEM_ID
                          , NICK_NAME
                          , REQUESTOR
                          , TO_SITE_DESCRIPTION
                          , END_CUSTOMER
                          , FCST_TYPE
                          , INCOTERMS
                          , TRANSPORT_MODE
                          , SUBSTR(YYYYMMDD, 1, 4) || '-' || SUBSTR(YYYYMMDD, 5, 2) || '-' || SUBSTR(YYYYMMDD, 7, 2) AS YMD_FMT
                          , QTY
                     FROM   SSP_MAIL_SHIP_REQ_DELETE_V
                    WHERE   1 = 1
                      AND   COMPANY_ID    = P_COMPANY_ID1
                      AND   MAIL_RECEIVER = RCV.MAIL_RECEIVER
                    ORDER BY DIVISION_ID, FROM_SITE, ITEM_ID, REQUESTOR, TO_SITE, END_CUSTOMER, FCST_TYPE, INCOTERMS, TRANSPORT_MODE, YYYYMMDD ) LOOP

            V_BODY_CONT := '<tr>' || CHR(13)
                || '<td>' || REPLACE(NVL(D.DIVISION_ID, ' '), CHR(10), ' ') || '</td>'
                || '<td>' || REPLACE(NVL(D.FROM_SITE_DESCRIPTION, ' '), CHR(10), ' ') || '</td>'
                || '<td>' || REPLACE(NVL(D.ITEM_ID, ' '), CHR(10), ' ') || '</td>'
                || '<td>' || REPLACE(NVL(D.NICK_NAME, ' '), CHR(10), ' ') || '</td>'
                || '<td>' || REPLACE(NVL(D.REQUESTOR, ' '), CHR(10), ' ') || '</td>'
                || '<td>' || REPLACE(NVL(D.TO_SITE_DESCRIPTION, ' '), CHR(10), ' ') || '</td>'
                || '<td>' || REPLACE(NVL(D.END_CUSTOMER, ' '), CHR(10), ' ') || '</td>'
                || '<td>' || REPLACE(NVL(D.FCST_TYPE, ' '), CHR(10), ' ') || '</td>'
                || '<td>' || REPLACE(NVL(D.INCOTERMS, ' '), CHR(10), ' ') || '</td>'
                || '<td>' || REPLACE(NVL(D.TRANSPORT_MODE, ' '), CHR(10), ' ') || '</td>'
                || '<td align=''center''>' || REPLACE(NVL(D.YMD_FMT, ' '), CHR(10), ' ') || '</td>'
                /* [2026-10-07] 포맷마스크 자리수 확장 (사용자 승인).
                 * TO_CHAR 는 값이 마스크 자리수를 넘으면 오류가 아니라 '###...###' 을 돌려준다.
                 * 원본 MSSQL 은 CONVERT(VARCHAR, MONEY, 1) 로 제한이 없어(MONEY 상한 15자리) 큰 값에서 출력이 갈렸다.
                 * 마스크를 넓혀도 12자리 이하 결과는 그대로다(FM 이 선행 0·공백을 지운다) — 회귀 위험 없음. */
                || '<td align=''right''>' || REPLACE(NVL(REPLACE(TO_CHAR(D.QTY, 'FM999,999,999,999,990.00'), '.00', ''), ' '), CHR(10), ' ') || '</td>'
                || '</tr>';

            V_TABLE_BODY := V_TABLE_BODY || NVL(V_BODY_CONT, ' ') || CHR(13);

            V_DIVISION_ID           := D.DIVISION_ID;
            V_FROM_SITE_DESCRIPTION := D.FROM_SITE_DESCRIPTION;
            V_ITEM_ID               := D.ITEM_ID;
            V_NICK_NAME             := D.NICK_NAME;
        END LOOP;

        V_TABLE_BODY := V_TABLE_BODY || '</br></tbody> </div> </body> </html>';


        PKG_SEND_MAIL.P_SEND_MAIL(V_TO_MAIL, V_MAIL_TITLE, DBMS_LOB.SUBSTR(V_TABLE_BODY, 32767, 1), 'Y');

        /* MAIL 발송 LOG 저장 */
        /* [2026-10-07] P_CATEGORY_ID 를 NULL -> 0 으로 교정.
         *  SCM_ADM_SMS_MAIL_SEND_LOG.CATEGORY_ID 는 NUMBER NOT NULL 이고 하위 프로시저에 NVL 보정이 없어
         *  NULL 이면 ORA-01400 -> ORA-20001 로 RAISE 되고, 이 호출이 발송 바로 뒤에 있어
         *  첫 수신자만 메일을 받고 수신자 루프가 중단된다(2026-10-07 실측).
         *  원본 MSSQL 은 '-' 를 넘기는데 Oracle 파라미터가 NUMBER 라 0 으로 전달한다
         *  - 행 2·5·8·9·11·15 가 모두 0 을 쓰고 있어 그것과 맞춘다. */
        SCM_ADM_SAVE_MAIL_SEND_BATCH_LOG('MAIL', 0, V_PROGRAM_NAME, V_MAIL_TITLE, V_DIVISION_ID, V_FROM_SITE_DESCRIPTION, V_ITEM_ID, V_NICK_NAME, NULL, NULL, NULL, NULL, NULL, V_TO_MAIL);

        V_MAILSENDCNT := V_MAILSENDCNT + 1;
    END LOOP;

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := NULL;
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

EXCEPTION
    WHEN OTHERS THEN
        V_ERROR_MESSAGE := SUBSTR(SQLERRM, 1, 1000);

        V_DESCRIPTION := V_PROGRAM_NAME || 'ERROR_LINE : ' || SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 400);

        INSERT INTO SCM_SYS_LOG_BATCH
               ( PROGRAM_NAME
               , LOG_TYPE
               , LOG_COUNT
               , LOG_MESSAGE
               , DESCRIPTION
               , EVENT_DATE
               , CREATION_DATE
               , CREATED_BY
               , LAST_UPDATE_DATE
               , LAST_UPDATED_BY )
        VALUES ( V_PROGRAM_NAME
               , 'ERROR'
               , NULL
               , V_ERROR_MESSAGE
               , V_DESCRIPTION
               , SYSDATE
               , SYSDATE
               , V_PROGRAM_NAME
               , SYSDATE
               , V_PROGRAM_NAME );
        COMMIT;

        /* MAIL 발송 LOG 저장 (원본 CATCH 두번째 블록) */
        SCM_ADM_SAVE_MAIL_SEND_BATCH_LOG('MAIL', 0, V_PROGRAM_NAME, V_MAIL_TITLE, V_DIVISION_ID, V_FROM_SITE_DESCRIPTION, V_ITEM_ID, V_NICK_NAME, NULL, NULL, NULL, NULL, NULL, V_TO_MAIL);
        COMMIT;


        P_LOG_MESSGE := V_ERROR_MESSAGE;
END PR_SSP_MAIL_SEND_SHIP_REQ_DELETE;

PROCEDURE PR_SSP_MAIL_SHIP_REQ_MINUS_BALANCE
/*
 * Program ID   : PR_SSP_SHIP_REQ_MINUS_BALANCE_MAIL_SEND
 * Description  : SSP MAIL 발송 (Ship_Req_Minus_Balance_Mail_Send)
 * Program History
 *===================================================================================================
 *   Date       In Charge		Description
 *===================================================================================================
 * 2019/06/12	mcTheJ			[CSR ID:4016810] [요청] SSP Planning Horizen 연장에 따른 Shipment Request Logic 변경
								- Balance 음수일 때 메일
								- Shipment Request 마이너스 재고(Balance)에 대한 조정기간별 메일 발송
 * 2019/06.21	mcTheJ			profile name 수정, mail log  title 추가
 * 2026.08.02	ZIONEX			[PJ202650304] NextSCM Migration
--Exec PR_SSP_SHIP_REQ_MINUS_BALANCE_MAIL_SEND;
 */
AS


    V_MAIL_TITLE                VARCHAR2(100 CHAR);

    V_HEAD_CONT                 VARCHAR2(4000 CHAR);

    V_BODY_CONT                 CLOB;

    V_BODY_TEXT                 VARCHAR2(4000 CHAR);

    V_TO_MAIL                   VARCHAR2(4000 CHAR);

    V_TO_MAIL_BACK              VARCHAR2(4000 CHAR);

    V_TABLE_BODY                CLOB;

    V_MONTH_NAME                VARCHAR2(10 CHAR);

    V_MAIL_RECEIVER             VARCHAR2(600 CHAR);
    V_DIVISION_ID               VARCHAR2(30 CHAR);
    V_FROM_SITE                 VARCHAR2(30 CHAR);
    V_FROM_SITE_DESCRIPTION     VARCHAR2(4000 CHAR);
    V_ITEM_ID                   VARCHAR2(50 CHAR);
    V_NICK_NAME                 VARCHAR2(50 CHAR);
    V_REQUESTOR                 VARCHAR2(4000 CHAR);
    V_TO_SITE                   VARCHAR2(30 CHAR);
    V_TO_SITE_DESCRIPTION       VARCHAR2(4000 CHAR);
    V_END_CUSTOMER              VARCHAR2(4000 CHAR);
    V_FCST_TYPE                 VARCHAR2(4000 CHAR);
    V_INCOTERMS                 VARCHAR2(10 CHAR);
    V_TRANSPORT_MODE            VARCHAR2(50 CHAR);
    V_YYYYMMDD                  VARCHAR2(10 CHAR);
    V_QTY                       VARCHAR2(4000 CHAR);

    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME              VARCHAR2(150 CHAR) := 'PR_SSP_MAIL_SHIP_REQ_MINUS_BALANCE';
    V_LOG_TYPE                  VARCHAR2(30 CHAR);     /* START/END/ERROR/... */
    N_LOG_COUNT                 NUMBER(10) := 0;
    V_LOG_MESSAGE               VARCHAR2(1000 CHAR);
    V_DESCRIPTION               VARCHAR2(500 CHAR);
    D_EVENT_DATE                DATE;

    /* 계산용 변수 */
    V_RECEIVER_CNT              NUMBER(10) := 0;       /* 총 수신자 명 */
    V_MAIL_DATA_CNT             NUMBER(10) := 0;       /* 메일 Data 총 건수 */
    V_RECEIVER_LOOP_CNT         NUMBER(10) := 0;       /* 수신자 비교 변수 */
    V_MAIL_DATA_LOOP_CNT        NUMBER(10) := 0;       /* 메일 Data 비교 변수 */
    V_DATECHK                   NUMBER(10) := 0;       /* 조정기간 Data 체크 건수 */
    V_MAIL_CNT_CHK              NUMBER(10) := 0;       /* 메일 View에 Data 있는지 체크 건수 */
    V_MAILSENDCNT               NUMBER(10) := 0;
    /* 수신자 임시 변수. 원본 초기값 두따옴표(빈문자)는 Oracle 에서 NULL 이다(대체 표현 없음). */
    V_TMP_RECEIVER              VARCHAR2(4000 CHAR) := '';

    /* S : 현재 일자 */
    V_NOW_DATE                  VARCHAR2(8 CHAR);
    /* Confirm 기간------------------------------------------------------------ */
    V_CONFIRM_START_DATE        VARCHAR2(10 CHAR);


    V_ERROR_MESSAGE             VARCHAR2(1000 CHAR);
BEGIN

    /* 임시Table 삭제-------------------------------------------------
       ----------------------------------------------------------------- */
    DELETE
      FROM GT_SSPSRMB_SHIP_REQUEST_MAIL;

    /* S : 현재 일자----------------------------------------------------------- */

    V_NOW_DATE := TO_CHAR(SYSDATE, 'YYYYMMDD');

    /* -------------------------------------------------------------------------- */

    /* 현재 날짜에 대한 조정기간인지 체크--------------------------------------- */
    SELECT COUNT(*)
         , MAX(T.CONFIRM_START_DATE)
      INTO V_DATECHK
         , V_CONFIRM_START_DATE
      FROM (SELECT MAX(PLAN_START_YYYYMMDD) AS PLAN_START_YYYYMMDD
                 , CONFIRM_START_DATE
              FROM SSP_MST_SHIP_REQ
             WHERE 1 = 1
               AND CUTOFF_FLAG  = 'Y'
               AND CONFIRM_FLAG = 'N'
               AND V_NOW_DATE BETWEEN REQ_START_DATE AND REQ_END_DATE
             GROUP BY CONFIRM_START_DATE) T;
    /* ---------------------------------------------------------------------------- */
    /* 현재일자가 조정기간이 아니면 Return */
    IF V_DATECHK = 0 THEN
        RETURN;
    END IF;
    /* -------------------------------------- */
    /* 메일 발송에 필요한 영문 월명 찾기 */
    BEGIN
        SELECT SUBSTR(MONTH_FULL_NAME, 1, 10)
          INTO V_MONTH_NAME
          FROM SCM_SYS_CALENDAR_M
         WHERE 1 = 1
           AND BASIS_YYYYMMDD = V_CONFIRM_START_DATE
           AND ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            V_MONTH_NAME := NULL;
    END;
    /* -------------------------------------- */


    /* 메일 View에 Data 있는지 체크 */
    SELECT COUNT(*)
      INTO V_MAIL_CNT_CHK
      FROM SSP_MAIL_SHIP_REQ_MINUS_BALANCE_V
     WHERE 1 = 1;

    IF V_MAIL_CNT_CHK = 0 THEN
        RETURN;
    END IF;
    /* ------------------------------ */

    /* 메일 수신자별 Index Data Temp Table------------------------------------------------------------------ */
    INSERT
      INTO GT_SSPSRMB_SHIP_REQUEST_MAIL
         ( RECEIVER_NUM
         , DATA_NUM
         , MAIL_RECEIVER
         , DIVISION_ID
         , FROM_SITE
         , FROM_SITE_DESCRIPTION
         , ITEM_ID
         , NICK_NAME
         , REQUESTOR
         , TO_SITE
         , TO_SITE_DESCRIPTION
         , END_CUSTOMER
         , FCST_TYPE
         , INCOTERMS
         , TRANSPORT_MODE
         , YYYYMMDD
         , QTY )
    SELECT IA.RECEIVER_NUM
         , IA.DATA_NUM
         , IA.MAIL_RECEIVER
         , IA.DIVISION_ID
         , IA.FROM_SITE
         , IA.FROM_SITE_DESCRIPTION
         , IA.ITEM_ID
         , IA.NICK_NAME
         , IA.REQUESTOR
         , IA.TO_SITE
         , IA.TO_SITE_DESCRIPTION
         , IA.END_CUSTOMER
         , IA.FCST_TYPE
         , IA.INCOTERMS
         , IA.TRANSPORT_MODE
         , IA.YYYYMMDD
         , IA.QTY
      FROM (SELECT DENSE_RANK() OVER (ORDER BY MAIL_RECEIVER NULLS FIRST) AS RECEIVER_NUM
                 , ROW_NUMBER() OVER (PARTITION BY MAIL_RECEIVER
                                          ORDER BY MAIL_RECEIVER NULLS FIRST
                                                 , DIVISION_ID
                                                 , FROM_SITE
                                                 , ITEM_ID
                                                 , REQUESTOR NULLS FIRST
                                                 , TO_SITE
                                                 , END_CUSTOMER
                                                 , FCST_TYPE
                                                 , INCOTERMS
                                                 , TRANSPORT_MODE
                                                 , YYYYMMDD) AS DATA_NUM
                 , MAIL_RECEIVER
                 , DIVISION_ID
                 , FROM_SITE
                 , FROM_SITE_DESCRIPTION
                 , ITEM_ID
                 , NICK_NAME
                 , REQUESTOR
                 , TO_SITE
                 , TO_SITE_DESCRIPTION
                 , END_CUSTOMER
                 , FCST_TYPE
                 , INCOTERMS
                 , TRANSPORT_MODE
                 , YYYYMMDD
                 , QTY
              FROM SSP_MAIL_SHIP_REQ_MINUS_BALANCE_V) IA;
    /* ------------------------------------------------------------------------------------ */

    /********************************************************************************
    * MAIL TITLE
    ********************************************************************************/

    V_MAIL_TITLE := CASE WHEN V_MONTH_NAME IS NULL THEN NULL
                         ELSE '[Notice]Insufficient stock for '||V_MONTH_NAME||'(next month) shipping request(will be deleted soon)'
                    END;
    /********************************************************************************/

    /********************************************************************************
    * HEAD CONT
    ********************************************************************************/
    V_HEAD_CONT := '';
    V_HEAD_CONT := V_HEAD_CONT||'<tr>';
    V_HEAD_CONT := V_HEAD_CONT||'<th>'||'Div'||'</th>';
    V_HEAD_CONT := V_HEAD_CONT||'<th width=''100px''>'||'From Site'||'</th>';
    V_HEAD_CONT := V_HEAD_CONT||'<th>'||'Model'||'</th>';
    V_HEAD_CONT := V_HEAD_CONT||'<th>'||'Nick Name'||'</th>';
    V_HEAD_CONT := V_HEAD_CONT||'<th>'||'Requestor'||'</th>';
    V_HEAD_CONT := V_HEAD_CONT||'<th>'||'To Site*'||'</th>';
    V_HEAD_CONT := V_HEAD_CONT||'<th>'||'End Customer*'||'</th>';
    V_HEAD_CONT := V_HEAD_CONT||'<th>'||'FCST Type*'||'</th>';
    V_HEAD_CONT := V_HEAD_CONT||'<th>'||'Incoterms*'||'</th>';
    V_HEAD_CONT := V_HEAD_CONT||'<th>'||'Trans Mode*'||'</th>';
    V_HEAD_CONT := V_HEAD_CONT||'<th width=''100px''>'||'Date'||'</th>';
    V_HEAD_CONT := V_HEAD_CONT||'<th width=''90px''>'||'Qty'||'</th>';
    V_HEAD_CONT := V_HEAD_CONT||'</tr>';
    /********************************************************************************/

    /********************************************************************************
    * CONT
    ********************************************************************************/
    /* ★위 MAIL TITLE 과 동일 사유의 NULL 전파 가드(CASE) */
    V_BODY_TEXT := CASE WHEN V_MONTH_NAME IS NULL THEN NULL
                        ELSE 'Dear all,

							Your '||V_MONTH_NAME||'(next month) shipment requests can not be shipped out because of insufficient stock level.
							If we still have negative value for below model till cut-off date of request, all the shipment request will be deleted from the system.

							Please refer to below table and kindly ask you to check your next month request before cut-off date.

							Thank you.
							Best regards.

							'
                   END;
    V_BODY_CONT := '';
    /********************************************************************************/


    SELECT MAX(RECEIVER_NUM)
      INTO V_RECEIVER_CNT
      FROM GT_SSPSRMB_SHIP_REQUEST_MAIL;

    BEGIN
        /* 시작 LOG */
        V_LOG_TYPE    := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := '';

        D_EVENT_DATE  := SYSDATE;

        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        /* Loop 시작 */
        WHILE V_RECEIVER_CNT > V_RECEIVER_LOOP_CNT LOOP
            IF V_MAILSENDCNT = 10 THEN
                /* WAITFOR DELAY '00:00:05' (FIVE seconds) */
                DBMS_SESSION.SLEEP(5);
                /* 10건 전송시마다 5초의 딜레이를 준 후 건수 초기화 */
                V_MAILSENDCNT := 0;
            END IF;
            V_RECEIVER_LOOP_CNT := V_RECEIVER_LOOP_CNT + 1;

            V_MAIL_DATA_LOOP_CNT := 0;


            FOR R IN (SELECT MAIL_RECEIVER
                           , MAX(DATA_NUM) AS MAX_DATA_NUM
                        FROM GT_SSPSRMB_SHIP_REQUEST_MAIL
                       WHERE RECEIVER_NUM = V_RECEIVER_LOOP_CNT
                       GROUP BY MAIL_RECEIVER) LOOP
                V_TMP_RECEIVER  := R.MAIL_RECEIVER;
                V_MAIL_DATA_CNT := R.MAX_DATA_NUM;
            END LOOP;


            V_TO_MAIL := CASE WHEN V_TMP_RECEIVER IS NULL THEN NULL
                              ELSE V_TMP_RECEIVER||'@lgensol.com'
                         END;
            /* SET @v_to_mail = 'kahonmalu@lgensol.com'; */

            V_TABLE_BODY := '';
            V_TABLE_BODY := '
			<html>
				<head>
					<title>Untitled Document</title>
					<meta charset="UTF-8">
					<style>
						* {margin:0;padding:0;}
						body {font-family:Malgun Gothic, Arial, Helvetica, sans-serif;font-size:12px;line-height:1.8;color:#333333;}
						table {border-collapse:collapse;width:100%;}
						table th {background:#f5f5f5;border-bottom:1px solid #e1e1e1;}
						table td {background:#fff;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1;border-bottom:1px solid #e1e1e1;}
						table tbody th {border-left:1px solid #e1e1e1;text-align:right;padding:6px 8px;font-size:12px}
						table tbody td {padding:6px 8px;font-size:12px}
						table thead th {text-align:center;padding:3px;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1; border-bottom:1px solid #d1d1d1;font-size:12px}
						.hori-table table thead td {text-align:center;padding:3px;}
						.hori-table table tbody td {text-align:center;padding:3px;}
						.vertical-table, .hori-table {margin-bottom:20px;}
					</style>
				</head>
				<body>'||'</br>'||

                    '<b>'||REPLACE(V_BODY_TEXT, CHR(10), '<br>')||'</b>'||
                    '<div id="divBody" style="width: 100%; overflow-x: auto; overflow-y: auto; font-size: 9pt; line-break: auto;">'||
                    '<table style=''border-top:2px solid #c8294b; width:1200px;''>
								<thead>'||V_HEAD_CONT||'</thead> ';

            WHILE V_MAIL_DATA_CNT > V_MAIL_DATA_LOOP_CNT LOOP
                V_MAIL_DATA_LOOP_CNT := V_MAIL_DATA_LOOP_CNT + 1;

                FOR D IN (SELECT MAIL_RECEIVER
                               , DIVISION_ID
                               , FROM_SITE
                               , FROM_SITE_DESCRIPTION
                               , ITEM_ID
                               , NICK_NAME
                               , REQUESTOR
                               , TO_SITE
                               , TO_SITE_DESCRIPTION
                               , END_CUSTOMER
                               , FCST_TYPE
                               , INCOTERMS
                               , TRANSPORT_MODE
                               , SUBSTR(YYYYMMDD, 1, 4)||'-'||SUBSTR(YYYYMMDD, 5, 2)||'-'||SUBSTR(YYYYMMDD, 7, 2) AS YYYYMMDD_FMT
                               , QTY
                            FROM GT_SSPSRMB_SHIP_REQUEST_MAIL
                           WHERE 1 = 1
                             AND RECEIVER_NUM = V_RECEIVER_LOOP_CNT
                             AND DATA_NUM     = V_MAIL_DATA_LOOP_CNT) LOOP
                    V_MAIL_RECEIVER         := D.MAIL_RECEIVER;
                    V_DIVISION_ID           := D.DIVISION_ID;
                    V_FROM_SITE             := D.FROM_SITE;
                    V_FROM_SITE_DESCRIPTION := D.FROM_SITE_DESCRIPTION;
                    V_ITEM_ID               := D.ITEM_ID;

                    V_NICK_NAME             := SUBSTR(D.NICK_NAME, 1, 50);
                    V_REQUESTOR             := D.REQUESTOR;
                    V_TO_SITE               := D.TO_SITE;
                    V_TO_SITE_DESCRIPTION   := D.TO_SITE_DESCRIPTION;
                    V_END_CUSTOMER          := D.END_CUSTOMER;
                    V_FCST_TYPE             := D.FCST_TYPE;
                    V_INCOTERMS             := D.INCOTERMS;
                    V_TRANSPORT_MODE        := D.TRANSPORT_MODE;
                    V_YYYYMMDD              := D.YYYYMMDD_FMT;

                    V_QTY                   := TO_CHAR(D.QTY);
                END LOOP;

                V_BODY_CONT := '';
                V_BODY_CONT := V_BODY_CONT||'<tr>'||CHR(13);
                V_BODY_CONT := V_BODY_CONT||'<td>'||REPLACE(V_DIVISION_ID, CHR(10), ' ')||'</td>';
                V_BODY_CONT := V_BODY_CONT||'<td>'||REPLACE(V_FROM_SITE_DESCRIPTION, CHR(10), ' ')||'</td>';
                V_BODY_CONT := V_BODY_CONT||'<td>'||REPLACE(V_ITEM_ID, CHR(10), ' ')||'</td>';
                V_BODY_CONT := V_BODY_CONT||'<td>'||REPLACE(V_NICK_NAME, CHR(10), ' ')||'</td>';
                V_BODY_CONT := V_BODY_CONT||'<td>'||REPLACE(V_REQUESTOR, CHR(10), ' ')||'</td>';
                V_BODY_CONT := V_BODY_CONT||'<td>'||REPLACE(V_TO_SITE_DESCRIPTION, CHR(10), ' ')||'</td>';
                V_BODY_CONT := V_BODY_CONT||'<td>'||REPLACE(V_END_CUSTOMER, CHR(10), ' ')||'</td>';
                V_BODY_CONT := V_BODY_CONT||'<td>'||REPLACE(V_FCST_TYPE, CHR(10), ' ')||'</td>';
                V_BODY_CONT := V_BODY_CONT||'<td>'||REPLACE(V_INCOTERMS, CHR(10), ' ')||'</td>';
                V_BODY_CONT := V_BODY_CONT||'<td>'||REPLACE(V_TRANSPORT_MODE, CHR(10), ' ')||'</td>';
                V_BODY_CONT := V_BODY_CONT||'<td align=''center''>'||REPLACE(V_YYYYMMDD, CHR(10), ' ')||'</td>';

                V_BODY_CONT := V_BODY_CONT||'<td align=''right''>'||REPLACE(REPLACE(TO_CHAR(TO_NUMBER(V_QTY), 'FM999,999,999,990.00'), '.00', ''), CHR(10), ' ')||'</td>';
                V_BODY_CONT := V_BODY_CONT||'</tr>';


                V_TABLE_BODY := V_TABLE_BODY||V_BODY_CONT||''||CHR(13);

            END LOOP;		/* 메일 Data Loop End */
            V_TABLE_BODY := V_TABLE_BODY||'</tbody> </div> </body> </html>';

            /*                   , @recipients = @v_to_mail */
            PKG_SEND_MAIL.P_SEND_MAIL_CLOB(V_TO_MAIL, V_MAIL_TITLE, V_TABLE_BODY, 'Y');

            /* MAIL 발송 LOG 저장
               (V_USE_TYPE_CODE, P_CATEGORY_ID NUMBER, P_SEGMENT1~10, P_SEND_PGM, P_RECEIVER_ID) */
            SCM_ADM_SAVE_MAIL_SEND_BATCH_LOG('MAIL'
                            , 0
                            , V_MAIL_TITLE
                            , V_DIVISION_ID
                            , V_FROM_SITE_DESCRIPTION
                            , V_ITEM_ID
                            , V_NICK_NAME
                            , ''
                            , ''
                            , ''
                            , ''
                            , ''
                            , ''   /* p_send_pgm */
                            , V_TO_MAIL);

            V_MAILSENDCNT := V_MAILSENDCNT + 1;
        END LOOP;			/* 수신자 Loop End */
        /* 종료 LOG */
        V_LOG_TYPE    := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    EXCEPTION
        WHEN OTHERS THEN

            V_ERROR_MESSAGE := SUBSTR(SQLERRM, 1, 1000);


            V_DESCRIPTION := V_PROGRAM_NAME||'ERROR_LINE : '||SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 400);


            INSERT
              INTO SCM_SYS_LOG_BATCH
                 ( PROGRAM_NAME
                 , LOG_TYPE
                 , LOG_COUNT
                 , LOG_MESSAGE
                 , DESCRIPTION
                 , EVENT_DATE
                 , CREATION_DATE
                 , CREATED_BY
                 , LAST_UPDATE_DATE
                 , LAST_UPDATED_BY )
            VALUES ( V_PROGRAM_NAME
                   , 'ERROR'
                   , NULL
                   , V_ERROR_MESSAGE
                   , V_DESCRIPTION
                   , SYSDATE
                   , SYSDATE
                   , V_PROGRAM_NAME
                   , SYSDATE
                   , V_PROGRAM_NAME );


            IF DBMS_TRANSACTION.LOCAL_TRANSACTION_ID IS NOT NULL THEN
                COMMIT;
            END IF;


            V_ERROR_MESSAGE := SUBSTR(SQLERRM, 1, 1000);

            /* MAIL 발송 LOG 저장 */
            SCM_ADM_SAVE_MAIL_SEND_BATCH_LOG('MAIL'
                , 0
                , V_MAIL_TITLE
                , V_DIVISION_ID
                , V_FROM_SITE_DESCRIPTION
                , V_ITEM_ID
                , V_NICK_NAME
                , ''
                , ''
                , ''
                , ''
                , ''
                , ''   /* p_send_pgm */
                , V_TO_MAIL);

            IF DBMS_TRANSACTION.LOCAL_TRANSACTION_ID IS NOT NULL THEN
                COMMIT;
            END IF;

    END;

    /* 임시테이블 삭제 */
    DELETE
      FROM GT_SSPSRMB_SHIP_REQUEST_MAIL;
END PR_SSP_MAIL_SHIP_REQ_MINUS_BALANCE;

PROCEDURE PR_SSP_MAIL_SHIP_REQ_MINUS_BALANCE_40
(
    P_COMPANY_ID1   IN  VARCHAR2
  , P_LOG_MESSGE    OUT VARCHAR2
)
/*
 * Program ID   : PR_SSP_MAIL_SHIP_REQ_MINUS_BALANCE_40
 * Description  : SSP Mail 발송
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2020/11/24   KIMYONGHO	   신규추가
 * 2021.09.01   SSP Pjt.       SCP_MST_BOD_N_V 적용
 * 2026.07.31   ZIONEX      [PJ202650304] NextSCM Migration
 */
/*
 *     TEAM.USER_ID(+) IN (SELECT ...) 는 ORA-01799 로 거부됨(실측). 한 블록에서 ANSI+(+) 혼용은
 */
AS


    V_P_COMPANY_ID              VARCHAR2(10 CHAR);

    V_PLAN_START_YYYYMMDD       VARCHAR2(8 CHAR);
    V_FROM_YYYYMMDD             VARCHAR2(8 CHAR);
    V_TO_YYYYMMDD               VARCHAR2(8 CHAR);

    V_SITE_FROM_YYYYMMDD        VARCHAR2(8 CHAR);
    V_SITE_TO_YYYYMMDD          VARCHAR2(8 CHAR);

    V_BOH_YYYYMMDD              VARCHAR2(8 CHAR);
    V_STOCK_YYYYMMDD            VARCHAR2(8 CHAR);

    V_PROGRAM_ID                VARCHAR2(50 CHAR);
    V_SHEET_NAME                VARCHAR2(50 CHAR);

    V_FROMSITE_CNT              NUMBER(10);
    V_FROMSITE_TMPCNT           NUMBER(10);

    V_RECEIVER_CNT              NUMBER(10);
    V_RECEIVER_TMPCNT           NUMBER(10);

    V_ITEM_CNT                  NUMBER(10);
    V_ITEM_TMPCNT               NUMBER(10);

    V_TESTCNT                   NUMBER(10) := 0;

    V_MEASURECNT                NUMBER(10) := 0;

    /* 원본 NVARCHAR(max) HTML 누적 -> CLOB (VARCHAR2 32767 초과 시 ORA-06502 방지) */
    V_HEAD_CONT                 CLOB;
    V_BODY_CONT                 CLOB;
    V_RECEIVER_TEMP             VARCHAR2(150 CHAR);
    V_TO_MAIL                   VARCHAR2(4000 CHAR);
    V_TABLE_BODY                CLOB;
    V_BODY_CONTENTS             VARCHAR2(4000 CHAR);
    V_MAIL_TITLE                VARCHAR2(100 CHAR);
    V_MAIL_RECEIVER             VARCHAR2(100 CHAR);

    V_DIVISION_ID               VARCHAR2(100 CHAR);
    V_COMPANY_ID                VARCHAR2(100 CHAR);
    V_FROM_SITE_DESCRIPTION     VARCHAR2(100 CHAR);
    V_TO_SITE_DESCRIPTION       VARCHAR2(100 CHAR);
    V_DEPT_NAME_KO              VARCHAR2(100 CHAR);
    V_MKT_USER                  VARCHAR2(100 CHAR);
    V_ITEM_ID                   VARCHAR2(100 CHAR);
    V_ITEM_ID_TEMP              VARCHAR2(100 CHAR);
    V_NICK_NAME                 VARCHAR2(100 CHAR);
    V_MEASURE_NAME              VARCHAR2(100 CHAR);
    V_SEQ                       VARCHAR2(100 CHAR);

    V_SEGMENT1                  NUMBER;
    V_SEGMENT2                  NUMBER;
    V_SEGMENT3                  NUMBER;
    V_SEGMENT4                  NUMBER;
    V_SEGMENT5                  NUMBER;
    V_ITEM_SEQ                  NUMBER;
    V_ITEM_SEQ_TEMP             NUMBER := 0;

    V_MEASURE_SEQ               NUMBER;
    V_ROWSPANCNT                NUMBER;
    V_ROWSPANCNT2               NUMBER;
    V_CNT                       NUMBER(10);

    /* SCP FINAL PLAN INFO */
    V_SCP_PLAN_START_YYYYMMDD   VARCHAR2(8 CHAR);
    V_SCP_PLAN_TYPE             VARCHAR2(10 CHAR);
    V_SCP_SEQ                   INTEGER;


    V_LAST_PLAN_START_YYYYMMDD  VARCHAR2(8 CHAR)  := '';
    V_LAST_PLAN_TYPE            VARCHAR2(30 CHAR) := 'SP';
    V_LAST_SEQ                  INTEGER           := 0;

    V_P_SHEET_NAME              VARCHAR2(10 CHAR)   := 'Cell Biz';
    V_P_DIVISION_ID             VARCHAR2(30 CHAR)   := '40';
    V_P_TEAM_ID                 VARCHAR2(4000 CHAR);
    V_P_CUSTOMER                VARCHAR2(4000 CHAR);
    V_P_SCM_SITE_ID             VARCHAR2(4000 CHAR);
    V_P_PLANT_SITE_ID           VARCHAR2(4000 CHAR);
    V_P_PROJECT_CODE            VARCHAR2(4000 CHAR);
    V_P_ITEM_ID                 VARCHAR2(4000 CHAR);
    /* DECLARE @p_from_yyyymmdd  NVARCHAR(8) = CONVERT(NVARCHAR(8), DATEADD(DD,21,GETDATE()),112);
       DECLARE @p_to_yyyymmdd    NVARCHAR(8) = CONVERT(NVARCHAR(8), DATEADD(DD,25,GETDATE()),112); */
    V_P_FROM_YYYYMMDD           VARCHAR2(8 CHAR)  := '';
    V_P_TO_YYYYMMDD             VARCHAR2(8 CHAR)  := '';
    /* DECLARE @p_from_yyyymmdd  NVARCHAR(8) = '20201210';
       DECLARE @p_to_yyyymmdd    NVARCHAR(8) = '20201214'; */
    V_P_CREATED_BY              VARCHAR2(50 CHAR);
    V_DEBUG_MODE                VARCHAR2(1 CHAR)  := 'F';

    V_P_PROGRAM_ID              VARCHAR2(4000 CHAR) := 'SSP0026';

    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME              VARCHAR2(150 CHAR) := 'PR_SSP_MAIL_SHIP_REQ_MINUS_BALANCE_40';
    V_LOG_TYPE                  VARCHAR2(30 CHAR);   /* START/END/ERROR/... */
    N_LOG_COUNT                 INTEGER := 0;
    V_LOG_MESSAGE               VARCHAR2(1000 CHAR);
    V_DESCRIPTION               VARCHAR2(500 CHAR);
    D_EVENT_DATE                DATE;

    V_MAIL_COUNT                INTEGER := 0;

    V_ERROR_MESSAGE             VARCHAR2(1000 CHAR);

    /*       원본은 SCM_SYS_CALENDAR_M 에서 @v_site_from ~ @v_site_to(=from+4) 구간 basis_yyyymmdd 를 */
    V_D1                        VARCHAR2(8 CHAR);
    V_D2                        VARCHAR2(8 CHAR);
    V_D3                        VARCHAR2(8 CHAR);
    V_D4                        VARCHAR2(8 CHAR);
    V_D5                        VARCHAR2(8 CHAR);


    FUNCTION FMT_MONEY(P IN NUMBER) RETURN VARCHAR2 IS
    BEGIN
        IF P IS NULL THEN
            RETURN NULL;
        END IF;
        RETURN REPLACE(TO_CHAR(P, 'FM999,999,999,990.00'), '.00', '');
    END FMT_MONEY;
BEGIN

    V_P_COMPANY_ID := P_COMPANY_ID1;

    V_FROMSITE_TMPCNT := 0;
    V_RECEIVER_TMPCNT := 0;
    V_PLAN_START_YYYYMMDD := TO_CHAR(SYSDATE, 'YYYYMMDD');

    SELECT COUNT(*)
      INTO V_MAIL_COUNT
      FROM SCM_ADM_SMS_MAIL_SEND_LOG
     WHERE SEGMENT1 = V_PROGRAM_NAME
       AND SEGMENT2 = '40'
       AND SEGMENT3 = V_P_COMPANY_ID
       AND TO_CHAR(CREATION_DATE, 'YYYYMMDD') = V_PLAN_START_YYYYMMDD;

    IF V_MAIL_COUNT > 0 THEN
        RETURN;
    END IF;

    /* 원본의 IF OBJECT_ID('tempdb..#xxx') IS NOT NULL DROP TABLE #xxx (선행 정리) -> */
    /* SHIPMENT BOH */
    DELETE FROM GT_SSP0026_SHIP_FG;
    /* SHIPMENT ROW DATA */
    DELETE FROM GT_SSP0026_ROW;
    DELETE FROM GT_SSP0026_RAW;
    DELETE FROM GT_SSP0026_R01;
    DELETE FROM GT_SSP0026_R02;
    DELETE FROM GT_SSP0026_MAIL;
    DELETE FROM GT_SSP0026_PIVOT;
    DELETE FROM GT_SSP0026_FG;
    DELETE FROM GT_SSP0026_STD;

    /********************************************************************************
    * 임시테이블만들기
    ********************************************************************************/


    V_PROGRAM_ID := 'SSP0026';
    V_SHEET_NAME := 'Cell Biz';

    BEGIN
        /* //시작 LOG */
        V_LOG_TYPE    := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;   /* SYSDATETIME() -> 대상 P_EVENT_DATE 가 DATE (CV-055) */
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        /* //LOG END */
        BEGIN
            /* SELECT TOP 1 .. ORDER BY -> 인라인뷰 ORDER BY 후 ROWNUM = 1 (CV-026).
               원본 컬럼폭(PLAN_START_YYYYMMDD 100 / PLAN_TYPE 50) > 변수폭 -> MSSQL 대입 절단과 동일하게 SUBSTR */
            SELECT PLAN_START_YYYYMMDD, PLAN_TYPE, PLAN_SEQ
              INTO V_SCP_PLAN_START_YYYYMMDD, V_SCP_PLAN_TYPE, V_SCP_SEQ
              FROM
              (
                  SELECT SUBSTR(A.PLAN_START_YYYYMMDD, 1, 8) AS PLAN_START_YYYYMMDD
                       , SUBSTR(A.PLAN_TYPE, 1, 10)          AS PLAN_TYPE
                       , A.PLAN_SEQ                          AS PLAN_SEQ
                    FROM SCP_PLAN_VERSION_V A
                   WHERE 1 = 1
                     AND A.DIVISION_ID = V_P_DIVISION_ID
                     AND A.PLAN_CYCLE  = 'WEEKLY'
                     AND A.PLAN_TYPE   = 'FN'
                   ORDER BY A.PLAN_START_YYYYMMDD DESC, A.PLAN_TYPE_ORDER DESC, A.PLAN_SEQ DESC
              )
             WHERE ROWNUM = 1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                NULL;   /* MSSQL SELECT TOP 1 은 무행이면 변수를 바꾸지 않는다(NULL 유지) */
        END;

        /* 가장 최근 출하계획 버전 확인 */
        SELECT SUBSTR(MAX(PLAN_START_YYYYMMDD), 1, 8)
             , MAX(PLAN_SEQ)
             , SUBSTR(MAX(PLAN_TYPE), 1, 30)
          INTO V_LAST_PLAN_START_YYYYMMDD, V_LAST_SEQ, V_LAST_PLAN_TYPE
          FROM SSP_PLAN_VERSION_V
         WHERE PLAN_TYPE    = 'SP'
           AND DIVISION_ID  = V_P_DIVISION_ID
           AND CONFIRM_FLAG = 'Y';

        V_P_FROM_YYYYMMDD := V_LAST_PLAN_START_YYYYMMDD;
        V_P_TO_YYYYMMDD   := TO_CHAR(TO_DATE(V_LAST_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 56, 'YYYYMMDD');

        /* SSP_ANL_SHIP_PLAN_40 의 데이터 생성 시점이 달라 최신 생성 날짜를 조회한다. */
        INSERT INTO GT_SSP0026_STD   /* 기준 데이터 저장 */
        (
            DIVISION_ID, FROM_SITE, PLAN_START_YYYYMMDD
        )
        SELECT DISTINCT
               DIVISION_ID
             , FROM_SITE
             , PLAN_START_YYYYMMDD
          FROM
          (
              SELECT SP.DIVISION_ID
                   , SP.FROM_SITE
                   , SP.PLAN_START_YYYYMMDD
                   , RANK() OVER (PARTITION BY SP.FROM_SITE ORDER BY SP.PLAN_START_YYYYMMDD DESC) AS "RANK"
                FROM SSP_ANL_SHIP_PLAN_40 SP
               WHERE SP.DIVISION_ID = V_P_DIVISION_ID
                 AND SP.PLAN_START_YYYYMMDD >= TO_CHAR(SYSDATE - 1, 'YYYYMMDD')   /* 전일 */
                 AND SP.PLAN_START_YYYYMMDD <= TO_CHAR(SYSDATE, 'YYYYMMDD')       /* 당일 */
                 AND SP.QTY > 0
          ) A
         WHERE A."RANK" = 1;

        INSERT INTO GT_SSP0026_FG
        (
            DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, SEQ, ORDER_ID
          , ALLOCATION_QTY, FCST_TYPE, MASTER_ID, PLAN_ID, OUT_VERSION_ID
        )
        SELECT A.DIVISION_ID
             , A.PLAN_START_YYYYMMDD
             , A.PLAN_TYPE
             , A.SEQ
             , A.ORDER_ID
             , A.ALLOCATION_QTY
             , A.FCST_TYPE
             , A.MASTER_ID
             , A.PLAN_ID
             , A.OUT_VERSION_ID
          FROM SCP_PLN_SHIPMENT_PLAN_PEGGING A
         WHERE A.DIVISION_ID = V_P_DIVISION_ID
           AND A.PLAN_START_YYYYMMDD = V_SCP_PLAN_START_YYYYMMDD
           AND A.PLAN_TYPE           = V_SCP_PLAN_TYPE
           AND A.SEQ                 = V_SCP_SEQ;

        INSERT INTO GT_SSP0026_SHIP_FG
        (
            DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, SEQ, BIZ_TYPE, FCST_TYPE, ITEM_ID, TO_SITE
          , FROM_SITE, BOD_ID, TRANSPORT_MODE, MEASURE, YYYYMMDD, QTY, LAST_UPDATED_BY, LAST_UPDATE_DATE
        )
        SELECT DIVISION_ID
             , PLAN_START_YYYYMMDD
             , PLAN_TYPE
             , SEQ
             , MAX(OPERATION_GROUP)  AS BIZ_TYPE
             , FCST_TYPE
             , ITEM_ID
             , TO_SITE
             /* , INCOTERMS */
             , FROM_SITE
             , BOD_ID
             , TRANSPORT_MODE
             , MEASURE
             , YYYYMMDD
             , SUM(QTY)              AS QTY
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
          FROM
          (
              SELECT B.DIVISION_ID
                   , B.PLAN_START_YYYYMMDD
                   , B.PLAN_TYPE
                   , B.SEQ
                   , B.OPERATION_GROUP
                   , A.FCST_TYPE
                   , B.ITEM_ID
                   , B.TO_SITE
                   , B.FROM_SITE
                   , B.BOD_ID
                   , B.TRANSPORT_MODE
                   , B.MEASURE
                   , B.YYYYMMDD
                   , A.ALLOCATION_QTY  AS QTY
                   , REPLACE(B.LAST_UPDATED_BY, 'scp_batch', 'System') AS LAST_UPDATED_BY
                   , B.LAST_UPDATE_DATE
                FROM SCP_PLN_SHIPMENT_PLAN B
                   , GT_SSP0026_FG A
                   , SCM_MST_SITE T4
               WHERE 1 = 1
                 AND A.DIVISION_ID          = B.DIVISION_ID
                 AND A.PLAN_START_YYYYMMDD  = B.PLAN_START_YYYYMMDD
                 AND A.PLAN_TYPE            = B.PLAN_TYPE
                 AND A.SEQ                  = B.SEQ
                 AND A.ORDER_ID             = B.ORDER_ID
                 AND A.MASTER_ID            = B.MASTER_ID
                 AND A.PLAN_ID              = B.PLAN_ID
                 AND A.OUT_VERSION_ID       = B.OUT_VERSION_ID
                 AND B.DIVISION_ID          = T4.DIVISION_ID
                 AND B.TO_SITE              = T4.SCM_SITE_ID
                 AND T4.VALID_YN            = 'Y'
                 AND T4.OPERATION_GROUP IS NULL
                 AND B.DIVISION_ID          = V_P_DIVISION_ID
                 AND B.PLAN_START_YYYYMMDD  = V_SCP_PLAN_START_YYYYMMDD
                 AND B.PLAN_TYPE            = V_SCP_PLAN_TYPE
                 AND B.SEQ                  = V_SCP_SEQ
                 AND B.MEASURE              = 'SHIP_PLAN'
                 /* AND B.SEMI_YN              = 'N' */
                 AND B.OPERATION_GROUP      = 'A'
                 AND B.YYYYMMDD            >= V_P_FROM_YYYYMMDD
                 AND B.YYYYMMDD            <= V_P_TO_YYYYMMDD
          ) X
         GROUP BY DIVISION_ID
                , PLAN_START_YYYYMMDD
                , PLAN_TYPE
                , SEQ
                , FCST_TYPE
                , ITEM_ID
                , TO_SITE
                /* , INCOTERMS */
                , FROM_SITE
                , TRANSPORT_MODE
                , BOD_ID
                , MEASURE
                , YYYYMMDD
                , LAST_UPDATED_BY
                , LAST_UPDATE_DATE;

        /* -----------------------------------------------
           1. SCP Plan : SCP(Weekly) plant향 Shipment Plan
           ----------------------------------------------- */
        INSERT INTO GT_SSP0026_ROW
        (
            DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, MEASURE, YYYYMMDD, BOD_ID, QTY
          , INCOTERMS, TRANSPORT_MODE, FCST_TYPE, SEQ, LAST_UPDATED_BY, LAST_UPDATE_DATE, REMARK
        )
        SELECT SP.DIVISION_ID
             , SP.ITEM_ID
             , SP.FROM_SITE
             , SP.TO_SITE
             , 'SCP_SHIP_PLAN'   AS MEASURE
             , SP.YYYYMMDD
             , SP.BOD_ID
             , NVL(SP.QTY, 0)    AS QTY
             , BOD.INCOTERMS
             , BOD.TRANSPORT_MODE
             /* , ISNULL(SP.FCST_TYPE,'') AS FCST_TYPE */
             , '-'               AS FCST_TYPE
             , 1                 AS SEQ
             , SP.LAST_UPDATED_BY
             , SP.LAST_UPDATE_DATE
             , '-'               AS REMARK
          FROM SCP_ANL_SHIPMENT_PLAN_SEMI SP

            , (
                  SELECT DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, PLAN_SEQ, PLAN_ID, MODELING_ID, SORT_SEQ
                       , ROW_NUMBER() OVER (PARTITION BY DIVISION_ID
                                                ORDER BY PLAN_START_YYYYMMDD DESC, SORT_SEQ ASC, PLAN_SEQ DESC
                                           ) ROW_NUM
                    FROM
                    (
                        SELECT DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, PLAN_SEQ, PLAN_ID, MODELING_ID
                             , CASE WHEN PLAN_TYPE = 'PR' THEN 4
                                    WHEN PLAN_TYPE = 'MA' THEN 3
                                    WHEN PLAN_TYPE = 'SE' THEN 2
                                    WHEN PLAN_TYPE = 'FN' THEN 1
                                    ELSE 9
                               END AS SORT_SEQ
                          FROM SCP_PLAN_VERSION_V
                         WHERE 1 = 1
                           AND DIVISION_ID          = V_P_DIVISION_ID   /* 변수 */
                           AND PLAN_CYCLE           = 'WEEKLY'
                           /* 191219 FN만 조회 */
                           /* AND    plan_type       NOT IN ('TE', 'TM') */
                           AND PLAN_TYPE            = 'FN'
                           AND PLAN_START_YYYYMMDD >= TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 14, 'YYYYMMDD')
                    ) A
              ) PV
             , SCP_MST_BOD_N_V BOD
             , SCM_MST_SITE FS
             , SCM_MST_SITE TS
         WHERE 1 = 1
           AND SP.DIVISION_ID         = PV.DIVISION_ID
           AND SP.PLAN_START_YYYYMMDD = PV.PLAN_START_YYYYMMDD
           AND SP.PLAN_TYPE           = PV.PLAN_TYPE
           AND SP.SEQ                 = PV.PLAN_SEQ
           AND PV.ROW_NUM             = 1
           AND SP.MEASURE             = 'SHIP_PLAN_AMEND'
           AND SP.QTY                 > 0
           AND SP.OPERATION_GROUP     = 'A'
           AND SP.YYYYMMDD           >= V_P_FROM_YYYYMMDD
           AND SP.YYYYMMDD           <= V_P_TO_YYYYMMDD
           /* 원본 ( @p IS NULL OR @p = '' ) -> Oracle 은 '' 가 NULL 이라 IS NULL 하나로 동치(CV-028/H-4) */
           AND ( ( V_P_SCM_SITE_ID IS NULL ) OR SP.FROM_SITE IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(V_P_SCM_SITE_ID, ','))) )
           AND ( ( V_P_ITEM_ID     IS NULL ) OR SP.ITEM_ID   IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(V_P_ITEM_ID, ','))) )
           AND SP.DIVISION_ID = BOD.DIVISION_ID
           AND SP.BOD_ID      = BOD.BOD_ID
           AND FS.DIVISION_ID = SP.DIVISION_ID
           AND FS.SCM_SITE_ID = SP.FROM_SITE
           AND FS.VALID_YN    = 'Y'
           AND TS.DIVISION_ID = SP.DIVISION_ID
           AND TS.SCM_SITE_ID = SP.TO_SITE
           AND TS.VALID_YN    = 'Y'
           AND FS.PLANT_ID <> TS.PLANT_ID;

        /* SCP_SHIP_PLAN Meausre 생성 */
        INSERT INTO GT_SSP0026_ROW
        (
            DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, MEASURE, YYYYMMDD, BOD_ID, QTY
          , INCOTERMS, TRANSPORT_MODE, FCST_TYPE, SEQ, LAST_UPDATED_BY, LAST_UPDATE_DATE, REMARK
        )
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , A.FROM_SITE
             , A.TO_SITE
             , 'SCP_SHIP_PLAN'      AS MEASURE
             , A.YYYYMMDD
             , A.BOD_ID
             , NVL(A.QTY, 0)        AS QTY
             , C.INCOTERMS
             , C.TRANSPORT_MODE
             /* 원본 ISNULL(A.FCST_TYPE,'') : 원천 GT_SSP0026_SHIP_FG.FCST_TYPE 는 PEGGING NOT NULL 유래라 */
             , A.FCST_TYPE          AS FCST_TYPE
             , 1                    AS SEQ
             , A.LAST_UPDATED_BY
             , A.LAST_UPDATE_DATE
             , '-'                  AS REMARK
          FROM GT_SSP0026_SHIP_FG A
             , SCP_MST_BOD_N_V C
         WHERE C.DIVISION_ID(+)  = A.DIVISION_ID
           AND C.BOD_ID(+)       = A.BOD_ID
           AND C.DIVISION_ID(+)  = V_P_DIVISION_ID
           AND C.BOD_TYPE(+)     = 'SALES'
           AND A.DIVISION_ID  = V_P_DIVISION_ID
           AND A.MEASURE      = 'SHIP_PLAN'
           AND A.YYYYMMDD    >= V_P_FROM_YYYYMMDD
           AND A.YYYYMMDD    <= V_P_TO_YYYYMMDD;

        /* SHIP_REQ Meausre 생성 */
        INSERT INTO GT_SSP0026_ROW
        (
            DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, MEASURE, YYYYMMDD, BOD_ID, QTY
          , INCOTERMS, TRANSPORT_MODE, FCST_TYPE, SEQ, LAST_UPDATED_BY, LAST_UPDATE_DATE, REMARK
        )
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , A.PLANT_SITE_ID  AS FROM_SITE
             , A.SCM_SITE_ID    AS TO_SITE
             , 'SHIP_REQ'       AS MEASURE
             , A.YYYYMMDD
             , A.BOD_ID
             , A.QTY
             , A.INCOTERMS
             , A.TRANSPORT_MODE
             , A.FCST_TYPE
             , 2                AS SEQ
             , A.LAST_UPDATED_BY
             , A.LAST_UPDATE_DATE
             , '-'              AS REMARK
          FROM DM_PLN_SHIPMENT_REQ A
             , SCP_MST_BOD_N_V C
             , SCM_MST_SITE T4
         WHERE 1 = 1
           AND C.DIVISION_ID(+) = A.DIVISION_ID
           AND C.BOD_ID(+)      = A.BOD_ID
           AND C.DIVISION_ID(+) = V_P_DIVISION_ID
           /* AND C.BOD_TYPE     = 'SALES' */
           AND A.DIVISION_ID  = T4.DIVISION_ID
           AND A.SCM_SITE_ID  = T4.SCM_SITE_ID
           AND T4.VALID_YN    = 'Y'
           AND A.DIVISION_ID  = V_P_DIVISION_ID
           AND A.MEASURE      = 'SHIP_REQ'
           AND A.YYYYMMDD    >= V_P_FROM_YYYYMMDD
           AND A.YYYYMMDD    <= V_P_TO_YYYYMMDD;

        /* SHIP_PLAN Meausre 생성 */
        INSERT INTO GT_SSP0026_ROW
        (
            DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, MEASURE, YYYYMMDD, BOD_ID, QTY
          , INCOTERMS, TRANSPORT_MODE, FCST_TYPE, SEQ, LAST_UPDATED_BY, LAST_UPDATE_DATE, REMARK
        )
        SELECT SSP.DIVISION_ID
             , SSP.ITEM_ID
             , SSP.FROM_SITE
             , SSP.TO_SITE
             , 'SHIP_PLAN'          AS MEASURE
             , SSP.YYYYMMDD
             , BOD.BOD_ID
             , SSP.QTY
             , BOD.INCOTERMS        AS INCOTERMS
             , BOD.TRANSPORT_MODE   AS TR_MODE
             , SSP.FCST_TYPE
             , 3                    AS SEQ
             , '-'                  AS LAST_UPDATED_BY
             , SSP.LAST_UPDATE_DATE
             , '-'                  AS REMARK
          FROM SSP_ANL_SHIP_CONFIRM SSP

            , (
                  SELECT DISTINCT DIVISION_ID, ITEM_ID, SCP_OPERATION_GROUP
                    FROM SCM_MST_ITEM_SN
                   WHERE DIVISION_ID          = V_P_DIVISION_ID
                     AND SCP_OPERATION_GROUP  = 'A'   /* CELL/PACK 구분 */
                     AND ACTIVE_FLAG          = 'Y'
              ) IT
             , SCM_MST_SITE TS
             , SCP_MST_BOD_N_V BOD
         WHERE SSP.DIVISION_ID = IT.DIVISION_ID
           AND SSP.ITEM_ID     = IT.ITEM_ID
           AND SSP.DIVISION_ID = TS.DIVISION_ID
           AND SSP.TO_SITE     = TS.SCM_SITE_ID
           AND TS.VALID_YN     = 'Y'
           /* AND TS.SITE_TYPE    = 'SALES' */
           AND SSP.DIVISION_ID = BOD.DIVISION_ID
           AND SSP.BOD_ID      = BOD.BOD_ID
           AND SSP.DIVISION_ID  = V_P_DIVISION_ID   /* 변수 */
           AND SSP.QTY          > 0
           AND SSP.YYYYMMDD    >= V_P_FROM_YYYYMMDD
           AND SSP.YYYYMMDD    <= V_P_TO_YYYYMMDD
           AND SSP.CHANGE_TYPE  = 'C'
        UNION ALL
        SELECT P.DIVISION_ID
             , P.ITEM_ID
             , P.PLANT_SITE_ID      AS FROM_SITE
             , P.SCM_SITE_ID        AS TO_SITE
             , 'SHIP_PLAN'          AS MEASURE
             , P.YYYYMMDD
             , P.BOD_ID
             , P.QTY
             , P.INCOTERMS
             , P.TRANSPORT_MODE
             , P.FCST_TYPE
             , 3                    AS SEQ
             , '-'                  AS LAST_UPDATED_BY
             , P.LAST_UPDATE_DATE
             , '-'                  AS REMARK
          FROM DM_PLN_SHIPMENT_REQ P
             , SCM_MST_SITE FZ
             , SCM_MST_SITE T4
         WHERE 1 = 1   /* P.YYYYMMDD >= CONVERT(NVARCHAR(8), DATEADD(DD,ISNULL(FZ.SHIP_FROZEN,0),GETDATE()),112) -- 확정구간의 다음날짜가 나오므로 >= 로 처리함 */
           AND P.DIVISION_ID    = FZ.DIVISION_ID
           AND P.PLANT_SITE_ID  = FZ.SCM_SITE_ID
           AND FZ.VALID_YN      = 'Y'
           AND P.DIVISION_ID    = T4.DIVISION_ID
           AND P.SCM_SITE_ID    = T4.SCM_SITE_ID
           AND FZ.VALID_YN      = 'Y'
           /* AND T4.SITE_TYPE    = 'SALES' */
           AND P.YYYYMMDD >= V_P_FROM_YYYYMMDD
           AND P.YYYYMMDD <= V_P_TO_YYYYMMDD;

        /* POSTP_PLAN Meausre 생성 */
        INSERT INTO GT_SSP0026_ROW
        (
            DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, MEASURE, YYYYMMDD, BOD_ID, QTY
          , INCOTERMS, TRANSPORT_MODE, FCST_TYPE, SEQ, LAST_UPDATED_BY, LAST_UPDATE_DATE, REMARK
        )
        SELECT P.DIVISION_ID                    AS DIVISION_ID
             , P.CELL_ITEM_ID                   AS ITEM_ID
             , P.SCM_SITE_ID                    AS FROM_SITE
             , '-'                              AS TO_SITE
             , 'POSTP_PLAN'                     AS MEASURE
             , P.PLAN_DATE                      AS YYYYMMDD
             , '-'                              AS BOD_ID
             , P.PLAN_QTY                       AS QTY
             , '-'                              AS INCOTERMS
             , '-'                              AS TRANSPORT_MODE
             , '-'                              AS FCST_TYPE
             , 4                                AS SEQ
             , CAST(NULL AS VARCHAR2(50 CHAR))  AS LAST_UPDATED_BY
             , CAST(NULL AS DATE)               AS LAST_UPDATE_DATE
             , '-'                              AS REMARK
          FROM SSP_FORMATION_POST_CELL_V P
             , SCM_MST_SITE E
         WHERE E.DIVISION_ID = V_P_DIVISION_ID

           AND E.COMPANY_ID  = P_COMPANY_ID1
           AND E.DIVISION_ID = P.DIVISION_ID
           AND E.SCM_SITE_ID = P.SCM_SITE_ID
           AND P.DIVISION_ID  = V_P_DIVISION_ID
           AND P.PLAN_DATE   >= V_P_FROM_YYYYMMDD
           AND P.PLAN_DATE   <  V_P_TO_YYYYMMDD
           AND ( ( V_P_ITEM_ID IS NULL ) OR P.CELL_ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(V_P_ITEM_ID, ','))) );

        /* GROUP BY P.DIVISION_ID
           ,        P.CELL_ITEM_ID
           ,        P.SCM_SITE_ID
           ,        P.PLAN_DATE */

        /*        POSTP_PLAN Meausre 생성
        INSERT INTO #TMP_ROWDATA
        SELECT  P.DIVISION_ID				AS DIVISION_ID
        	, P.ITEM_ID					AS ITEM_ID
        	, P.FROM_SITE					AS FROM_SITE
        	, '-'						AS TO_SITE
        	, 'POSTP_PLAN'					AS MEASURE
        	, P.YYYYMMDD					AS YYYYMMDD
        	, '-'						AS BOD_ID
        	, P.QTY						AS QTY
        	, '-'						AS INCOTERMS
        	, '-'						AS TRANSPORT_MODE
        	, '-'						AS FCST_TYPE
        	, 4							AS SEQ
        	, NULL						AS LAST_UPDATED_BY
        	, NULL						AS LAST_UPDATE_DATE
        	, '-'						AS REMARK
         FROM SSP_ANL_SHIP_PLAN_40 P WITH(NOLOCK)
        INNER JOIN SCM_MST_SITE FS
           ON P.DIVISION_ID		= FS.DIVISION_ID
          AND P.FROM_SITE        = FS.SCM_SITE_ID
          AND FS.SITE_TYPE       = 'SALSE'
          AND FS.OPERATION_GROUP = 'A'
          AND FS.OSP_YN          = 'N'
          AND FS.VALID_YN        = 'Y'
        WHERE 1 = 1
          AND P.PLAN_START_YYYYMMDD = CONVERT(VARCHAR(8),GETDATE() , 112) -- 당일(현재는 현재일 -1)
          AND P.MEASURE		= 'POSTP_PLAN'
          AND P.DIVISION_ID      = @p_division_id
          AND P.YYYYMMDD         >= @p_from_yyyymmdd
          AND P.YYYYMMDD         <= @p_to_yyyymmdd
          AND (( @p_item_id		  IS NULL OR @p_item_id ='')		OR P.ITEM_ID		  IN (SELECT TOKEN FROM DBO.STRING_SPLIT(@p_item_id , ',')))
          AND (( @p_plant_site_id  IS NULL OR @p_plant_site_id ='')   OR P.FROM_SITE	  IN (SELECT TOKEN FROM DBO.STRING_SPLIT(@p_plant_site_id , ',')))
          AND P.qty            >  0
          AND P.DIVISION_ID    = '40' -- 소형(40) 인 경우만 조회
        */

        /* SITE_MOVE Meausre 생성 */
        INSERT INTO GT_SSP0026_ROW
        (
            DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, MEASURE, YYYYMMDD, BOD_ID, QTY
          , INCOTERMS, TRANSPORT_MODE, FCST_TYPE, SEQ, LAST_UPDATED_BY, LAST_UPDATE_DATE, REMARK
        )
        SELECT SSP.DIVISION_ID
             , SSP.ITEM_ID
             , SSP.FROM_SITE                    AS FROM_SITE
             , '-'                              AS TO_SITE
             , 'SITE_MOVE'                      AS MEASURE
             , SSP.YYYYMMDD
             , ''                               AS BOD_ID
             , SSP.QTY
             , ''                               AS INCOTERMS
             , ''                               AS TRANSPORT_MODE
             , ''                               AS FCST_TYPE
             , 5                                AS SEQ
             , CAST(NULL AS VARCHAR2(50 CHAR))  AS LAST_UPDATED_BY
             , CAST(NULL AS DATE)               AS LAST_UPDATE_DATE
             , '-'                              AS REMARK
          FROM SSP_ANL_SHIP_CONFIRM SSP
             , SCM_MST_SITE TS
             , SCM_MST_SITE FS
         WHERE 1 = 1
           AND SSP.DIVISION_ID = TS.DIVISION_ID
           AND SSP.TO_SITE     = TS.SCM_SITE_ID
           AND TS.SITE_TYPE    = 'PLANT'
           AND TS.VALID_YN     = 'Y'
           AND SSP.DIVISION_ID = FS.DIVISION_ID
           AND SSP.FROM_SITE   = FS.SCM_SITE_ID
           AND FS.VALID_YN     = 'Y'
           AND TS.PLANT_ID    <> FS.PLANT_ID
           AND SSP.DIVISION_ID = V_P_DIVISION_ID
           AND SSP.QTY         > 0
           AND SSP.YYYYMMDD   >= V_P_FROM_YYYYMMDD
           AND SSP.YYYYMMDD   <= V_P_TO_YYYYMMDD
           AND SSP.BIZ_TYPE    = 'A'
           AND SSP.CHANGE_TYPE = 'C'
           AND ( ( V_P_ITEM_ID IS NULL ) OR SSP.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(V_P_ITEM_ID, ','))) )
        UNION ALL
        SELECT R.DIVISION_ID
             , R.ITEM_ID
             , R.PLANT_SITE_ID                  AS FROM_SITE
             , '-'                              AS TO_SITE
             , 'SITE_MOVE'                      AS MEASURE
             , R.YYYYMMDD
             , ''                               AS BOD_ID
             , R.QTY
             , ''                               AS INCOTERMS
             , ''                               AS TRANSPORT_MODE
             , ''                               AS FCST_TYPE
             , 5                                AS SEQ
             , CAST(NULL AS VARCHAR2(50 CHAR))  AS LAST_UPDATED_BY
             , CAST(NULL AS DATE)               AS LAST_UPDATE_DATE
             , '-'                              AS REMARK
          FROM DM_PLN_SHIPMENT_REQ R
             , SCM_MST_SITE FS
             , SCM_MST_SITE TS
         WHERE 1 = 1
           AND FS.DIVISION_ID     = R.DIVISION_ID
           AND FS.SCM_SITE_ID     = R.PLANT_SITE_ID
           AND FS.SITE_TYPE       = 'PLANT'
           AND FS.OPERATION_GROUP = 'A'
           AND FS.OSP_YN          = 'N'
           AND FS.VALID_YN        = 'Y'
           AND TS.DIVISION_ID     = R.DIVISION_ID
           AND TS.SCM_SITE_ID     = R.SCM_SITE_ID
           AND TS.SITE_TYPE       = 'PLANT'
           AND TS.VALID_YN        = 'Y'
           AND R.DIVISION_ID      = V_P_DIVISION_ID
           AND R.MEASURE          = 'SHIP_REQ'
           AND R.YYYYMMDD        >= V_P_FROM_YYYYMMDD
           AND R.YYYYMMDD        <= V_P_TO_YYYYMMDD
           AND TS.PLANT_ID       <> FS.PLANT_ID
           AND R.QTY              > 0
           /* AND R.YYYYMMDD >= CONVERT(CHAR(8), DATEADD(DD, ISNULL(FS.SHIP_FROZEN,0), GETDATE()), 112) */
           AND ( ( V_P_ITEM_ID IS NULL ) OR R.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(V_P_ITEM_ID, ','))) );

        /* CUST_MOVE Meausre 생성 */
        INSERT INTO GT_SSP0026_ROW
        (
            DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, MEASURE, YYYYMMDD, BOD_ID, QTY
          , INCOTERMS, TRANSPORT_MODE, FCST_TYPE, SEQ, LAST_UPDATED_BY, LAST_UPDATE_DATE, REMARK
        )
        SELECT SSP.DIVISION_ID
             , SSP.ITEM_ID
             , SSP.FROM_SITE                    AS FROM_SITE
             , '-'                              AS TO_SITE
             , 'CUST_MOVE'                      AS MEASURE
             , SSP.YYYYMMDD
             , ''                               AS BOD_ID
             , SSP.QTY
             , ''                               AS INCOTERMS
             , ''                               AS TRANSPORT_MODE
             , ''                               AS FCST_TYPE
             , 5                                AS SEQ
             , CAST(NULL AS VARCHAR2(50 CHAR))  AS LAST_UPDATED_BY
             , CAST(NULL AS DATE)               AS LAST_UPDATE_DATE
             , '-'                              AS REMARK
          FROM SSP_ANL_SHIP_CONFIRM SSP
             , SCM_MST_SITE TS
             , SCM_MST_SITE FS
         WHERE 1 = 1
           AND SSP.DIVISION_ID = TS.DIVISION_ID
           AND SSP.TO_SITE     = TS.SCM_SITE_ID
           AND TS.SITE_TYPE    = 'SALES'
           AND TS.VALID_YN     = 'Y'
           AND SSP.DIVISION_ID = FS.DIVISION_ID
           AND SSP.FROM_SITE   = FS.SCM_SITE_ID
           AND FS.VALID_YN     = 'Y'
           AND TS.PLANT_ID    <> FS.PLANT_ID
           AND SSP.DIVISION_ID = V_P_DIVISION_ID
           AND SSP.QTY         > 0
           AND SSP.YYYYMMDD   >= V_P_FROM_YYYYMMDD
           AND SSP.YYYYMMDD   <= V_P_TO_YYYYMMDD
           AND SSP.BIZ_TYPE    = 'A'
           AND SSP.CHANGE_TYPE = 'C'
           AND ( ( V_P_ITEM_ID IS NULL ) OR SSP.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(V_P_ITEM_ID, ','))) )
        UNION ALL
        SELECT R.DIVISION_ID
             , R.ITEM_ID
             , R.PLANT_SITE_ID                  AS FROM_SITE
             , '-'                              AS TO_SITE
             , 'CUST_MOVE'                      AS MEASURE
             , R.YYYYMMDD
             , ''                               AS BOD_ID
             , R.QTY
             , ''                               AS INCOTERMS
             , ''                               AS TRANSPORT_MODE
             , ''                               AS FCST_TYPE
             , 5                                AS SEQ
             , CAST(NULL AS VARCHAR2(50 CHAR))  AS LAST_UPDATED_BY
             , CAST(NULL AS DATE)               AS LAST_UPDATE_DATE
             , '-'                              AS REMARK
          FROM DM_PLN_SHIPMENT_REQ R
             , SCM_MST_SITE FS
             , SCM_MST_SITE TS
         WHERE 1 = 1
           AND FS.DIVISION_ID     = R.DIVISION_ID
           AND FS.SCM_SITE_ID     = R.PLANT_SITE_ID
           AND FS.SITE_TYPE       = 'PLANT'
           AND FS.OPERATION_GROUP = 'A'
           AND FS.OSP_YN          = 'N'
           AND FS.VALID_YN        = 'Y'
           AND TS.DIVISION_ID     = R.DIVISION_ID
           AND TS.SCM_SITE_ID     = R.SCM_SITE_ID
           AND TS.SITE_TYPE       = 'SALES'
           AND TS.VALID_YN        = 'Y'
           AND R.DIVISION_ID      = V_P_DIVISION_ID
           AND R.MEASURE          = 'SHIP_REQ'
           AND R.YYYYMMDD        >= V_P_FROM_YYYYMMDD
           AND R.YYYYMMDD        <= V_P_TO_YYYYMMDD
           /* AND TS.plant_id <> FS.plant_id */
           AND R.QTY              > 0
           /* AND R.YYYYMMDD >= CONVERT(CHAR(8), DATEADD(DD, ISNULL(FS.SHIP_FROZEN,0), GETDATE()), 112) */
           AND ( ( V_P_ITEM_ID IS NULL ) OR R.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(V_P_ITEM_ID, ','))) );

        INSERT INTO GT_SSP0026_ROW
        (
            DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, MEASURE, YYYYMMDD, BOD_ID, QTY
          , INCOTERMS, TRANSPORT_MODE, FCST_TYPE, SEQ, LAST_UPDATED_BY, LAST_UPDATE_DATE, REMARK
        )
        /* WH_IN Meausre 생성 */
        SELECT T.DIVISION_ID
             , T.ITEM_ID
             , T.FROM_SITE
             , T.TO_SITE
             , 'WH_IN'                          AS MEASURE
             , T.YYYYMMDD
             , T.BOD_ID
             , T.QTY
             , T.INCOTERMS
             , T.TRANSPORT_MODE
             , T.FCST_TYPE
             , 6                                AS SEQ
             , CAST(NULL AS VARCHAR2(50 CHAR))  AS LAST_UPDATED_BY
             , CAST(NULL AS DATE)               AS LAST_UPDATE_DATE
             , '-'                              AS REMARK
          FROM SSP_ANL_SHIP_PLAN_40 T
             , GT_SSP0026_STD ST
         WHERE ST.DIVISION_ID         = T.DIVISION_ID
           AND ST.FROM_SITE           = T.FROM_SITE
           AND ST.PLAN_START_YYYYMMDD = T.PLAN_START_YYYYMMDD
           AND T.DIVISION_ID = V_P_DIVISION_ID
           AND T.MEASURE     = 'WH_IN'
           AND T.YYYYMMDD   >= V_P_FROM_YYYYMMDD
           AND T.YYYYMMDD   <= V_P_TO_YYYYMMDD
           AND T.BIZ_TYPE    = 'A';

        /* TOTAL_PLAN Meausre 생성 */
        INSERT INTO GT_SSP0026_ROW
        (
            DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, MEASURE, YYYYMMDD, BOD_ID, QTY
