             , '-'                              AS TO_SITE
             , 'WH_BOH_PLAN'                    AS MEASURE
             , A.YYYYMMDD
             , ''                               AS BOD_ID
             , SUM(CASE WHEN C.MEASURE = 'TOTAL_PLAN' AND C.YYYYMMDD = TO_CHAR(SYSDATE - 1, 'YYYYMMDD') THEN 0   /* @p_from_yyyymmdd */
                        /* WHEN C.MEASURE = 'TOTAL_PLAN' AND C.YYYYMMDD >= CONVERT(NVARCHAR(8), DATEADD(DD,21,GETDATE()),112) THEN -1 * ISNULL(C.QTY,0)  -- @p_from_yyyymmdd
                           WHEN C.MEASURE <> 'TOTAL_PLAN' AND C.YYYYMMDD = CONVERT(NVARCHAR(8), GETDATE()-1, 112) THEN 0
                           WHEN C.MEASURE <> 'TOTAL_PLAN' AND C.YYYYMMDD >= CONVERT(NVARCHAR(8), GETDATE(), 112) AND C.YYYYMMDD < A.YYYYMMDD THEN ISNULL(C.QTY, 0) */
                        ELSE 0 END) + NVL(A.STOCK_QTY, 0)  AS QTY
             /* , ISNULL(A.STOCK_QTY, 0) AS QTY */
             , ''                               AS INCOTERMS
             , ''                               AS TRANSPORT_MODE
             , ''                               AS FCST_TYPE
             , 9                                AS SEQ
             , CAST(NULL AS VARCHAR2(50 CHAR))  AS LAST_UPDATED_BY
             , CAST(NULL AS DATE)               AS LAST_UPDATE_DATE
             , '-'                              AS REMARK
          FROM
          (
              SELECT A.DIVISION_ID
                   , A.FROM_SITE            AS FROM_SITE
                   , A.ITEM_ID              AS ITEM_ID
                   , A.YYYYMMDD             AS YYYYMMDD
                   , SUM(NVL(A.QTY, 0))     AS STOCK_QTY
                FROM SSP_ANL_SHIP_PLAN_40 A
                   , GT_SSP0026_STD ST
               WHERE 1 = 1
                 AND ST.DIVISION_ID         = A.DIVISION_ID
                 AND ST.FROM_SITE           = A.FROM_SITE
                 AND ST.PLAN_START_YYYYMMDD = A.PLAN_START_YYYYMMDD
                 AND A.DIVISION_ID = V_P_DIVISION_ID
                 AND A.BIZ_TYPE    = 'A'
                 AND A.MEASURE     = 'WH_STOCK'
                 AND A.YYYYMMDD   >= V_P_FROM_YYYYMMDD   /* @v_last_plan_start_yyyymmdd */
                 AND A.YYYYMMDD   <= V_P_TO_YYYYMMDD
               GROUP BY A.DIVISION_ID
                      , A.FROM_SITE
                      , A.ITEM_ID
                      , A.YYYYMMDD
          ) A

        , (
              SELECT A.DIVISION_ID
                   , A.ITEM_ID AS ITEM_ID
                   , A.FROM_SITE
                   , A.YYYYMMDD
                   , A.MEASURE
                   , A.QTY
                FROM GT_SSP0026_ROW A
               WHERE 1 = 1
                 AND A.DIVISION_ID = V_P_DIVISION_ID
                 AND A.MEASURE    IN ('TOTAL_PLAN')
                 AND A.YYYYMMDD   >= V_LAST_PLAN_START_YYYYMMDD
                 AND A.YYYYMMDD   <= V_P_TO_YYYYMMDD
          ) C
         WHERE 1 = 1
           AND C.DIVISION_ID(+) = A.DIVISION_ID
           AND C.ITEM_ID(+)     = A.ITEM_ID
           AND C.YYYYMMDD(+)   <= A.YYYYMMDD
           AND C.FROM_SITE(+)   = A.FROM_SITE
         GROUP BY A.DIVISION_ID
                , A.ITEM_ID
                , A.FROM_SITE
                , A.YYYYMMDD
                , A.STOCK_QTY;

