PROCEDURE PR_SSP_XIF_PLM_SAMPLE_REQUEST_R
(
    P_IF_ID       IN  VARCHAR2
  , P_O_ERRFLAG   OUT VARCHAR2
  , P_O_ERRDESC   OUT VARCHAR2
)
/***************************************************************************************************
 * Program ID   : PR_SSP_XIF_PLM_SAMPLE_REQUEST_R
 * Description  : PLM 소형 샘플 출하 품의 진행 상태 수신
 * OutTable     : XIF_PLM_SAMPLE_REQUEST_R (I/F Table)
 * Execute      : EXEC PR_SSP_XIF_PLM_SAMPLE_REQUEST_R
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 20210801     SSP Pjt.       Create.
 * 2026.07.06   ZIONEX         [PJ202650304] NextSCM Migration
 *
*************************************************************************************************** */
IS
    /* LOG 용 변수 설정 */
    V_BATCH_USER          VARCHAR2(150 CHAR) := 'ssp_batch';
    V_PROGRAM_NAME        VARCHAR2(150 CHAR) := 'PR_SSP_XIF_PLM_SAMPLE_REQUEST_R';
    V_LOG_TYPE            VARCHAR2(30 CHAR);                            /* START/END/ERROR/... */
    N_LOG_COUNT           NUMBER := 0;
    V_LOG_MESSAGE         VARCHAR2(1000 CHAR);
    V_DESCRIPTION         VARCHAR2(500 CHAR);                          /* 상세설명 */
    V_TABLE_ID            VARCHAR2(150 CHAR) := 'XIF_PLM_SAMPLE_REQUEST_R';   /* 테이블 필수 */
    D_EVENT_DATE          DATE;
    V_INSERT_CNT          NUMBER := 0;
    V_INSERT_SUM          NUMBER := 0;


    V_IF_ID               VARCHAR2(50 CHAR);


    V_INX                 NUMBER := 0;
    V_MAX_NUM             NUMBER := 0;


    V_IF_SEQ              VARCHAR2(50 CHAR);
    V_CONFIRM_ID          VARCHAR2(50 CHAR);
    V_PLM_REQ_NO          VARCHAR2(50 CHAR);
    V_PLM_REQ_STATUS      VARCHAR2(50 CHAR);
    V_QMS_OQC_REQ_ID      VARCHAR2(50 CHAR);
    V_QMS_OQC_INSP_ID     VARCHAR2(50 CHAR);
    V_QMS_OQC_INSP_RESULT VARCHAR2(50 CHAR);
BEGIN
    /*-----------------------------------------------------------*/
    /* PREPROCESSING */
    /*-----------------------------------------------------------*/
    V_IF_ID     := 'OPLM_OSCM_SAMPLE_REQUEST';
    P_O_ERRFLAG := '';
    P_O_ERRDESC := '';


    DELETE FROM GT_XIF_PLM_SAMPLE_REQ_R;

    /*-----------------------------------------------------------*/
    /* START LOG */
    /*-----------------------------------------------------------*/
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := V_PROGRAM_NAME || ':' || ' XIF_PLM_SAMPLE_REQUEST_R_S INSERT LOGIC';
    D_EVENT_DATE  := SYSDATE;

    PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER);

    BEGIN

        /*****************************************************
         *
         *****************************************************/

        INSERT INTO GT_XIF_PLM_SAMPLE_REQ_R
             ( TID
             , IF_SEQ
             , CONFIRM_ID
             , PLM_REQ_NO
             , PLM_REQ_STATUS
             , QMS_OQC_REQ_ID
             , QMS_OQC_INSP_ID
             , QMS_OQC_INSP_RESULT
             )
        SELECT ROW_NUMBER() OVER (ORDER BY IF_SEQ)   AS TID
             , IF_SEQ
             , CONFIRM_ID
             , PLM_REQ_NO
             , PLM_REQ_STATUS
             , QMS_OQC_REQ_ID
             , QMS_OQC_INSP_ID
             , CASE WHEN QMS_OQC_INSP_RESULT = 'P' THEN 'Pass'
                    WHEN QMS_OQC_INSP_RESULT = 'F' THEN 'Fail'
                    ELSE QMS_OQC_INSP_RESULT END
          FROM XIF_PLM_SAMPLE_REQUEST_R_SN
         WHERE PROC_FLAG = 'N'
           AND IF_ID = V_IF_ID
         ORDER BY
               IF_SEQ;

        SELECT 1
             , COUNT(*)
          INTO V_INX
             , V_MAX_NUM
          FROM GT_XIF_PLM_SAMPLE_REQ_R;

        WHILE V_INX <= V_MAX_NUM
        LOOP

            SELECT IF_SEQ
                 , CONFIRM_ID
                 , PLM_REQ_NO
                 , PLM_REQ_STATUS
                 , QMS_OQC_REQ_ID
                 , QMS_OQC_INSP_ID
                 , QMS_OQC_INSP_RESULT
              INTO V_IF_SEQ
                 , V_CONFIRM_ID
                 , V_PLM_REQ_NO
                 , V_PLM_REQ_STATUS
                 , V_QMS_OQC_REQ_ID
                 , V_QMS_OQC_INSP_ID
                 , V_QMS_OQC_INSP_RESULT
              FROM GT_XIF_PLM_SAMPLE_REQ_R
             WHERE TID = V_INX;

            UPDATE SSP_ANL_SHIP_CONFIRM C
               SET C.ATTRIBUTE2 = V_PLM_REQ_NO
                 , C.ATTRIBUTE3 = V_PLM_REQ_STATUS
                 , C.ATTRIBUTE4 = V_QMS_OQC_REQ_ID
                 , C.ATTRIBUTE5 = V_QMS_OQC_INSP_ID
                 , C.ATTRIBUTE6 = V_QMS_OQC_INSP_RESULT
             WHERE C.CONFIRM_ID = V_CONFIRM_ID;

            V_INX := V_INX + 1;

        END LOOP;


        UPDATE XIF_PLM_SAMPLE_REQUEST_R_SN X
           SET X.PROC_FLAG = 'Y'
         WHERE EXISTS ( SELECT 1
                          FROM GT_XIF_PLM_SAMPLE_REQ_R T
                         WHERE T.IF_SEQ = X.IF_SEQ );

        V_INSERT_CNT := SQL%ROWCOUNT;                 /* As-Is @@ROWCOUNT (직전 UPDATE 건수) */
        V_INSERT_SUM := V_INSERT_SUM + V_INSERT_CNT;


        /*-----------------------------------------------------------*/
        /* TXN LOG */
        /*-----------------------------------------------------------*/
        V_LOG_TYPE    := 'TXN';                        /* 로그타입 */
        N_LOG_COUNT   := V_INSERT_CNT;                 /* @@ROWCOUNT; */
        V_LOG_MESSAGE := 'INSERT INTO ' || V_TABLE_ID;
        D_EVENT_DATE  := SYSDATE;
        V_DESCRIPTION := 'Process Complete...' || ':' || TO_CHAR(D_EVENT_DATE, 'YYYY-MM-DD HH24:MI:SS".000"');

        PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER);


    EXCEPTION
        WHEN OTHERS THEN
            /*-----------------------------------------------------------*/
            /* ERROR LOG */
            /*-----------------------------------------------------------*/

            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := 'ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
            D_EVENT_DATE  := SYSDATE;
            PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER);

    END;

    /* Interface History Data Deleting */
    DELETE FROM XIF_PLM_SAMPLE_REQUEST_R_SN
     WHERE IF_RCV_DATE < TRUNC(SYSDATE) - 30
       AND PROC_FLAG = 'Y';

    /*-----------------------------------------------------------*/
    /* END LOG */
    /*-----------------------------------------------------------*/
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;

    PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, V_INSERT_SUM, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER);

END;

