  V_DESCRIPTION := '';
  V_EVENT_DATE  := SYSDATE;

  PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, V_EVENT_DATE);

  BEGIN

    /* 인터페이스 테이블 처리 ROW UPDATE */
    UPDATE XIF_SCM_SCS_BOX_RESULT_R_SN
       SET PROC_FLAG = 'P'
     WHERE NVL(PROC_FLAG, 'N') = 'N'
       AND BOXING_DATE >= V_BOXING_DATE   /* LINE_ID 가 정상 IF 되는 일자 (by 장현석C) */
    /* AND    DIVISION_ID = V_DIVISION_ID */  /* 2022.08.24 */
    /* AND    PACK_QTY > 0 */                 /* 2022.08.10 */
    ;

    /* 지나간 배치까지 적용하기 위해 Cursor 로 처리 */
    /* declare cur_scs_box_prod_result cursor for */
    /* select if_seq */
    /* from   xif_scm_scs_box_result_r_sn a with(nolock) */
    /* where  1 = 1 */
    /* and    a.proc_flag = 'P' */
    /* and    a.division_id = @v_division_id */
    /* and    a.boxing_date >= @v_boxing_date */
    /* --and    pack_qty > 0  -- 2022.08.10 */
    /* group by a.if_seq */
    /* order by a.if_seq asc; */


/* INF-R 적용 이전
        declare cur_scs_box_prod_result cursor for
        select if_seq
        from   xif_scm_scs_box_result_r_sn a with(nolock)
        where  1 = 1
        and not exists (select 1
                          from scm_adm_lookup_master_detail b (nolock)
                         where a.division_id = b.segment1
                           and a.packer_code = b.segment2
                           and b.lookup_type = 'SCS_ASSY_PACKER'
                       )
        and    a.proc_flag = 'P'
        --and    a.division_id = @v_division_id
        and    a.boxing_date >= @v_boxing_date
        --and    pack_qty > 0  -- 2022.08.10
        group by a.if_seq
        order by a.if_seq asc;
*/

/* INF-R 적용 이후 */
    FOR REC IN (


        /* SCM_ADM_LOOKUP_MASTER_DETAIL B 는 NOT EXISTS 상관 서브쿼리(조인 아님) → 그대로.  */
        SELECT IF_SEQ
          FROM (
                SELECT IF_SEQ, DIVISION_ID
                     , NVL(X1.NEW_VALUE1, PACKER_CODE) AS PACKER_CODE
                     , PROC_FLAG, BOXING_DATE
                  FROM XIF_SCM_SCS_BOX_RESULT_R_SN A
                  LEFT OUTER JOIN NERP_CONV_MASTER X1
                    ON X1.CODETYPE = 'SCP_SITE_ID'
                   AND A.PACKER_CODE = X1.OLD_VALUE1
                   AND X1.ATTRIBUTE5 IN ('1ST', '2ND')
               ) A
         WHERE 1 = 1
           AND NOT EXISTS (SELECT 1
                             FROM SCM_ADM_LOOKUP_MASTER_DETAIL B
                            WHERE A.DIVISION_ID = B.SEGMENT1
                              AND A.PACKER_CODE = B.SEGMENT2
                              AND B.LOOKUP_TYPE = 'SCS_ASSY_PACKER'
                          )
           AND A.PROC_FLAG = 'P'
        /* AND    A.DIVISION_ID = V_DIVISION_ID */
           AND A.BOXING_DATE >= V_BOXING_DATE
        /* AND    PACK_QTY > 0  -- 2022.08.10 */
         GROUP BY A.IF_SEQ
         ORDER BY A.IF_SEQ ASC
    ) LOOP

        V_IF_SEQ := REC.IF_SEQ;

/* INF-R 적용 이전
            MERGE INTO scm_dnm_scs_prod_result a
            USING (
                   SELECT  PR_SSP_XIF_SCS_BOX_RSLT_SUM_R
                          v.division_id
                        , dbo.FN_GET_PACKER_PLAN_ITEM_ID(v.division_id, v.pack_model_code) AS item_id
                   FROM  (
                          SELECT --spart AS division_id
                                 ISNULL(division_id, '')             AS division_id
                               , CONVERT(CHAR(8), GETDATE()-1, 112)  AS cutoff_date -- 실제로는 의미 없음
                               , ISNULL(packer_code, '')             AS packer_code
                               , ISNULL(attr_01, '')                 AS line_id           -- attr_1 (Line_ID)
                          FROM   XIF_SCM_SCS_BOX_RESULT_R_SN  WITH(NOLOCK)
                          AND    proc_flag = 'P'
                          --AND    DIVISION_ID = @v_division_id
                          AND    BOXING_DATE >= @v_boxing_date
                         ) v
                   WHERE  division_id                 <> ''
                  ) b
            ON (       a.division_id     =  b.division_id
                   --AND a.cutoff_date   =  b.cutoff_date
                   AND a.pack_model_code =  b.pack_model_code -- Origin Item Id
               )
                 UPDATE SET
                             a.cutoff_date      =  b.cutoff_date
                            ,a.packer_code      =  b.packer_code

            INSERT (
                    division_id
                  , cutoff_date
                  , item_id
                  , packer_code
                  , line_id
                   )
                  , b.cutoff_date
                  , @v_batch_user
                   )
            ;
*/


/* INF-R 적용 이후 */
        MERGE INTO SCM_DNM_SCS_PROD_RESULT A
        USING (
               SELECT /* PR_SSP_XIF_SCS_BOX_RSLT_SUM_R */
                      V.DIVISION_ID
                    , V.CUTOFF_DATE
                    , V.SCM_SITE_ID
                    , FN_GET_PACKER_PLAN_ITEM_ID(V.DIVISION_ID, V.PACK_MODEL_CODE) AS ITEM_ID
                    , V.PACKER_CODE
                    , V.PACK_MODEL_CODE
                    , V.LINE_ID
                    , V.PROD_DATE
                    , V.PROD_QTY
                    , V.DEFECT_QTY
               FROM  (
                      SELECT /* spart AS division_id */
                             DIVISION_ID                          AS DIVISION_ID
                           , TO_CHAR(SYSDATE-1, 'YYYYMMDD')       AS CUTOFF_DATE /* 실제로는 의미 없음 */
                           , NVL(X1.NEW_VALUE1, PACKER_CODE)      AS SCM_SITE_ID
                           , NVL(X1.NEW_VALUE1, PACKER_CODE)      AS PACKER_CODE
                           , PACK_MODEL_CODE                      AS PACK_MODEL_CODE
                           , ATTR_01                             AS LINE_ID           /* attr_1 (Line_ID) */
                           , BOXING_DATE                         AS PROD_DATE
                           , NVL(PACK_QTY, 0)                     AS PROD_QTY
                           , '0'                                 AS DEFECT_QTY


                      FROM   XIF_SCM_SCS_BOX_RESULT_R_SN  A
                        LEFT OUTER JOIN  NERP_CONV_MASTER X1
                        ON  X1.CODETYPE = 'SCP_SITE_ID'
                        AND A.PACKER_CODE = X1.OLD_VALUE1
                        AND X1.ATTRIBUTE5 IN ('1ST', '2ND')
                      WHERE  IF_SEQ    = V_IF_SEQ
                      AND    PROC_FLAG = 'P'
                      /* AND    DIVISION_ID = V_DIVISION_ID */
                      AND    BOXING_DATE >= V_BOXING_DATE
                     ) V
               WHERE  DIVISION_ID     IS NOT NULL
               AND    SCM_SITE_ID     IS NOT NULL
               AND    PACK_MODEL_CODE IS NOT NULL
              ) B
        ON (       A.DIVISION_ID     =  B.DIVISION_ID
               /* AND A.CUTOFF_DATE    =  B.CUTOFF_DATE */
               AND A.SCM_SITE_ID     =  B.SCM_SITE_ID
               AND A.PACK_MODEL_CODE =  B.PACK_MODEL_CODE /* Origin Item Id */
               AND NVL(A.LINE_ID, ' ') =  NVL(B.LINE_ID, ' ')
               AND A.PROD_DATE       =  B.PROD_DATE
           )
        WHEN MATCHED THEN
             UPDATE SET
                         A.CUTOFF_DATE      =  B.CUTOFF_DATE
                        , A.PROD_QTY         =  B.PROD_QTY
                        , A.DEFECT_QTY       =  B.DEFECT_QTY
                        , A.ITEM_ID          =  B.ITEM_ID
                        , A.PACKER_CODE      =  B.PACKER_CODE
                        , A.LAST_UPDATED_BY  =  'BOX_U'/* @v_batch_user */
                        , A.LAST_UPDATE_DATE =  SYSDATE

        WHEN NOT MATCHED THEN
        INSERT (
                DIVISION_ID
              , CUTOFF_DATE
              , SCM_SITE_ID
              , ITEM_ID
              , PACKER_CODE
              , PACK_MODEL_CODE
              , LINE_ID
              , PROD_DATE
              , PROD_QTY
              , DEFECT_QTY
              , CREATED_BY
              , CREATION_DATE
              , LAST_UPDATED_BY
              , LAST_UPDATE_DATE
               )
        VALUES (
                B.DIVISION_ID
              , B.CUTOFF_DATE
              , B.SCM_SITE_ID
              , B.ITEM_ID
              , B.PACKER_CODE
              , B.PACK_MODEL_CODE
              , B.LINE_ID
              , B.PROD_DATE
              , B.PROD_QTY
              , B.DEFECT_QTY
              , V_BATCH_USER
              , SYSDATE
              , 'BOX_I'/* @v_batch_user */
              , SYSDATE
               )
        ;

        N_LOG_COUNT := N_LOG_COUNT + SQL%ROWCOUNT;

    END LOOP;

    /* --------------------------------------------------------- */
    /* INSERT LOG */
    /* --------------------------------------------------------- */
    /* SET @n_log_count = @@ROWCOUNT; */
    V_LOG_TYPE    := 'APPEND';
    V_LOG_MESSAGE := 'INSERT INTO scm_dnm_scs_prod_result';
    V_DESCRIPTION := 'if_seq = ' || V_IF_SEQ;
    V_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, V_EVENT_DATE);
          /* --------------------------------------------------------- */

    /* 처리된 row 마킹 */
    UPDATE XIF_SCM_SCS_BOX_RESULT_R_SN
       SET PROC_FLAG = 'Y'
     WHERE PROC_FLAG = 'P';

    /* IF data  삭제 (90일 이전 데이터 삭제) */
    DELETE
      FROM XIF_SCM_SCS_BOX_RESULT_R_SN
     WHERE IF_RCV_DATE < SYSDATE - 90;

    IF DBMS_TRANSACTION.LOCAL_TRANSACTION_ID IS NOT NULL THEN
      COMMIT;
    END IF;

  EXCEPTION
    WHEN OTHERS THEN
      IF DBMS_TRANSACTION.LOCAL_TRANSACTION_ID IS NOT NULL THEN
        ROLLBACK;
      END IF;
      /* ERROR LOG */
      V_LOG_TYPE    := 'ERROR';
      V_LOG_MESSAGE := SQLERRM;
      V_DESCRIPTION := SUBSTR('ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 500);
      V_EVENT_DATE  := SYSDATE;
      PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, V_EVENT_DATE
                         , NULL, TO_CHAR(SQLCODE), SQLERRM, DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
  END;

  /* 종료 LOG */
  V_LOG_TYPE    := 'END';
  V_LOG_MESSAGE := '########## END of procedure ##########';
  V_DESCRIPTION := '';
  V_EVENT_DATE  := SYSDATE;
  PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, V_EVENT_DATE);

END;

PROCEDURE PR_SSP_XIF_SCS_PROD_PLAN_R
/*
 * Program ID   : PR_SSP_XIF_SCS_PROD_PLAN_R
 * Description  : Packer 생산계획 I/F
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2020.07.31   KSG            Initial Release [전지 공급 대응력 향상을 위한 SCM 관리 체계 개선]
 * 2024.10.01   KHJ            NERP_SSP
 * 2026.07.06   ZIONEX         [PJ202650304] NextSCM Migration
 *                              - 배치 수신 proc(scm_batch, START/END/ERROR 로그). 결과셋 미소비 -> OUT 커서 미추가, 무파라미터 유지.
 *                              - @@ROWCOUNT 누적(MERGE 직후) -> SQL%ROWCOUNT 실값 누적.
 *                              - 'INF-R 적용 이전' 구 MERGE 블록은 死주석 전수보존(중첩 블록주석 de-nest).
 */
IS
    /* LOG 용 변수 설정 */
    V_BATCH_USER      VARCHAR2(150 CHAR) := 'scm_batch';
    V_PROGRAM_NAME    VARCHAR2(150 CHAR) := 'PR_SSP_XIF_SCS_PROD_PLAN_R';
    V_LOG_TYPE        VARCHAR2(30 CHAR); /* START/END/ERROR/... */
    N_LOG_COUNT       NUMBER := 0;
    V_LOG_MESSAGE     VARCHAR2(1000 CHAR);
    V_DESCRIPTION     VARCHAR2(500 CHAR);
    D_EVENT_DATE      DATE;
    V_IF_SEQ          VARCHAR2(30 CHAR);
    N_HISTORY_SEQ     NUMBER;
BEGIN


    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    BEGIN

        /* 인터페이스 테이블 처리 ROW UPDATE */
        UPDATE XIF_SCS_PROD_PLAN_R_SN
           SET PROC_FLAG = 'P'
         WHERE NVL(PROC_FLAG, 'N') = 'N';

        /* 지나간 배치까지 적용하기 위해 Cursor 로 처리 */
        FOR CUR_SCS_PROD_PLAN IN (
            SELECT IF_SEQ
              FROM XIF_SCS_PROD_PLAN_R_SN
             WHERE PROC_FLAG = 'P'
             GROUP BY IF_SEQ
             ORDER BY IF_SEQ ASC
        ) LOOP

            V_IF_SEQ := CUR_SCS_PROD_PLAN.IF_SEQ;

/*INF-R 적용 이전
            MERGE INTO scm_dnm_scs_prod_plan a
                USING (
                   SELECT  PR_SSP_XIF_SCS_PROD_PLAN_R
                        , dbo.FN_GET_PACKER_PLAN_ITEM_ID(v.division_id, v.pack_model_code) AS item_id
                          SELECT --spart AS division_id
                                 ISNULL(division_id, '')             AS division_id
                               , ISNULL(plan_version, CONVERT(CHAR(8), GETDATE(), 112))  AS cutoff_date -- plan_version 이 생산계획일임
                               , ISNULL(plan_version, '')            AS plan_version
                         ) v
                   WHERE  division_id                 <> ''
                       AND a.pack_model_code =  b.pack_model_code -- Origin Item Id
                   )
                     UPDATE SET

                INSERT (
                    division_id
                  , item_id
                  , plan_version
                   )
                       )
                ;
INF-R 적용 이전 끝 */
            /*INF-R 적용 이후*/
            MERGE INTO SCM_DNM_SCS_PROD_PLAN A
            USING (
                   SELECT /* PR_SSP_XIF_SCS_PROD_PLAN_R */
                          V.DIVISION_ID
                        , V.CUTOFF_DATE
                        , V.SCM_SITE_ID
                        , FN_GET_PACKER_PLAN_ITEM_ID(V.DIVISION_ID, V.PACK_MODEL_CODE) AS ITEM_ID
                        , V.PACKER_CODE
                        , V.PACK_MODEL_CODE
                        , V.LINE_ID
                        , V.PLAN_VERSION
                        , V.PLAN_OPERATION
                        , V.PLAN_TYPE
                        , V.SHIFT
                        , V.PROD_DATE
                        , V.PROD_QTY
                   FROM  (
                          SELECT /* spart AS division_id */
                                 A.DIVISION_ID                                       AS DIVISION_ID
                               , NVL(A.PLAN_VERSION, TO_CHAR(SYSDATE, 'YYYYMMDD'))   AS CUTOFF_DATE /* plan_version 이 생산계획일임 */
                               , NVL(X1.NEW_VALUE1, A.PACKER_CODE)                   AS SCM_SITE_ID
                               , NVL(X1.NEW_VALUE1, A.PACKER_CODE)                   AS PACKER_CODE
                               , A.PACK_MODEL_CODE                                   AS PACK_MODEL_CODE
                               , NVL(A.LINE_ID, ' ')                                 AS LINE_ID
                               , A.PLAN_VERSION                                      AS PLAN_VERSION
                               , NVL(A.PLAN_OPERATION, ' ')                          AS PLAN_OPERATION
                               , NVL(A.PLAN_TYPE, ' ')                               AS PLAN_TYPE
                               , NVL(A.SHIFT, ' ')                                   AS SHIFT
                               , NVL(A.PROD_DATE, ' ')                               AS PROD_DATE
                               , NVL(A.PROD_QTY, 0)                                  AS PROD_QTY


                          FROM   XIF_SCS_PROD_PLAN_R_SN A
                                 LEFT OUTER JOIN NERP_CONV_MASTER X1
                                   ON  X1.CODETYPE  = 'SCP_SITE_ID'
                                   AND A.PACKER_CODE = X1.OLD_VALUE1
                                   AND X1.ATTRIBUTE5 IN ('1ST', '2ND')
                          WHERE  A.IF_SEQ    = V_IF_SEQ
                          AND    A.PROC_FLAG = 'P'
                         ) V
                   WHERE  V.DIVISION_ID     IS NOT NULL
                   AND    V.SCM_SITE_ID     IS NOT NULL
                   AND    V.PACK_MODEL_CODE IS NOT NULL
                  ) B
            ON (       A.DIVISION_ID     =  B.DIVISION_ID
                   AND A.CUTOFF_DATE     =  B.CUTOFF_DATE
                   AND A.SCM_SITE_ID     =  B.SCM_SITE_ID
                   AND A.PACK_MODEL_CODE =  B.PACK_MODEL_CODE /* Origin Item Id */
                   AND A.LINE_ID         =  B.LINE_ID
                   AND A.PLAN_OPERATION  =  B.PLAN_OPERATION
                   AND A.PLAN_TYPE       =  B.PLAN_TYPE
                   AND A.SHIFT           =  B.SHIFT
                   AND A.PROD_DATE       =  B.PROD_DATE
               )
            WHEN MATCHED THEN
                 UPDATE SET
                             A.PROD_QTY         =  B.PROD_QTY
                            ,A.ITEM_ID          =  B.ITEM_ID
                            ,A.PACKER_CODE      =  B.PACKER_CODE
                           , A.PLAN_VERSION     =  B.PLAN_VERSION
                            ,A.LAST_UPDATED_BY  =  V_BATCH_USER
                            ,A.LAST_UPDATE_DATE =  SYSDATE

            WHEN NOT MATCHED THEN
            INSERT (
                    DIVISION_ID
                  , CUTOFF_DATE
                  , SCM_SITE_ID
                  , ITEM_ID
                  , PACKER_CODE
                  , PACK_MODEL_CODE
                  , LINE_ID
                  , PLAN_VERSION
                  , PLAN_OPERATION
                  , PLAN_TYPE
                  , SHIFT
                  , PROD_DATE
                  , PROD_QTY
                  , CREATED_BY
                  , CREATION_DATE
                  , LAST_UPDATED_BY
                  , LAST_UPDATE_DATE
                   )
            VALUES (
                    B.DIVISION_ID
                  , B.CUTOFF_DATE
                  , B.SCM_SITE_ID
                  , B.ITEM_ID
                  , B.PACKER_CODE
                  , B.PACK_MODEL_CODE
                  , B.LINE_ID
                  , B.PLAN_VERSION
                  , B.PLAN_OPERATION
                  , B.PLAN_TYPE
                  , B.SHIFT
                  , B.PROD_DATE
                  , B.PROD_QTY
                  , V_BATCH_USER
                  , SYSDATE
                  , V_BATCH_USER
                  , SYSDATE
                   )
            ;

            N_LOG_COUNT := N_LOG_COUNT + SQL%ROWCOUNT;

        END LOOP;

        /* --------------------------------------------------------- */
        /* INSERT LOG */
        /* --------------------------------------------------------- */
        /* SET @n_log_count = @@ROWCOUNT; */
        V_LOG_TYPE    := 'APPEND';
        V_LOG_MESSAGE := 'INSERT INTO scm_dnm_scs_prod_plan';
        V_DESCRIPTION := 'if_seq = ' || V_IF_SEQ;
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
              /* --------------------------------------------------------- */

        /* 처리된 row 마킹 */
        UPDATE XIF_SCS_PROD_PLAN_R_SN
           SET PROC_FLAG = 'Y'
         WHERE PROC_FLAG = 'P';

        /* IF data  삭제 (90일 이전 데이터 삭제) */
        DELETE
          FROM XIF_SCS_PROD_PLAN_R_SN
         WHERE IF_RCV_DATE < SYSDATE - 90;

        IF DBMS_TRANSACTION.LOCAL_TRANSACTION_ID IS NOT NULL THEN
            COMMIT;
        END IF;

    EXCEPTION
        WHEN OTHERS THEN
            IF DBMS_TRANSACTION.LOCAL_TRANSACTION_ID IS NOT NULL THEN
                ROLLBACK;
            END IF;
            /* ERROR LOG */
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := 'ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
            D_EVENT_DATE  := SYSDATE;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    END;

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

END;

PROCEDURE PR_SSP_XIF_SCS_STOCK_RSLT_SUM_R
