                      , V.STOCK_DATE
                      , V.CELL_PACK
                      , V.MODEL_CODE
                      , V.STOCK_QTY
                      , V.BAD_QTY
                   FROM (
                        SELECT /* spart AS division_id */
                               DIVISION_ID                                       AS DIVISION_ID
                             , NVL(STOCK_DATE, TO_CHAR(SYSDATE-1, 'YYYYMMDD'))    AS CUTOFF_DATE /* stock_date 가 EOH 기준일자임 */
                             , NVL(X1.NEW_VALUE1, A.PACKER_CODE)                  AS SCM_SITE_ID
                             , NVL(X1.NEW_VALUE1, A.PACKER_CODE)                  AS PACKER_CODE
                             , STOCK_DATE                                         AS STOCK_DATE
                             , CELL_PACK                                          AS CELL_PACK
                             , MODEL_CODE                                         AS MODEL_CODE
                             , NVL(STOCK_QTY, 0)                                  AS STOCK_QTY
                             , NVL(ATTR_05, '0')                                  AS BAD_QTY    /* 비가용 수량 */


                          FROM XIF_SCS_STOCK_RSLT_SUM_R_SN A
                          LEFT OUTER JOIN NERP_CONV_MASTER X1
                            ON X1.CODETYPE = 'SCP_SITE_ID'
                           AND A.PACKER_CODE = X1.OLD_VALUE1
                           AND X1.ATTRIBUTE5 IN ('1ST', '2ND')
                         WHERE IF_SEQ = V_IF_SEQ
                           AND PROC_FLAG = 'P'
                       ) V
                  WHERE DIVISION_ID IS NOT NULL
                    AND SCM_SITE_ID IS NOT NULL
                    AND MODEL_CODE IS NOT NULL
                ) B
          ON (    A.DIVISION_ID = B.DIVISION_ID
                 AND A.CUTOFF_DATE = B.CUTOFF_DATE
                 AND A.SCM_SITE_ID = B.SCM_SITE_ID
                 AND A.MODEL_CODE = B.MODEL_CODE /* Origin Item Id */
                 AND A.CELL_PACK = B.CELL_PACK
             )
          WHEN MATCHED THEN
               UPDATE SET
                           A.STOCK_QTY         =  B.STOCK_QTY
                          , A.ITEM_ID          =  B.ITEM_ID
                          , A.PACKER_CODE      =  B.PACKER_CODE
                          , A.STOCK_DATE       =  B.STOCK_DATE
                          , A.LAST_UPDATED_BY  =  V_BATCH_USER
                          , A.LAST_UPDATE_DATE =  SYSDATE
                          , A.ATTRIBUTE5       =  B.BAD_QTY

          WHEN NOT MATCHED THEN
          INSERT (
                  DIVISION_ID
                , CUTOFF_DATE
                , SCM_SITE_ID
                , ITEM_ID
                , PACKER_CODE
                , STOCK_DATE
                , CELL_PACK
                , MODEL_CODE
                , STOCK_QTY
                , CREATED_BY
                , CREATION_DATE
                , LAST_UPDATED_BY
                , LAST_UPDATE_DATE
                , ATTRIBUTE5
                 )
          VALUES (
                  B.DIVISION_ID
                , B.CUTOFF_DATE
                , B.SCM_SITE_ID
                , B.ITEM_ID
                , B.PACKER_CODE
                , B.STOCK_DATE
                , B.CELL_PACK
                , B.MODEL_CODE
                , B.STOCK_QTY
                , V_BATCH_USER
                , SYSDATE
                , V_BATCH_USER
                , SYSDATE
                , B.BAD_QTY
                 )
          ;

          N_LOG_COUNT := N_LOG_COUNT + SQL%ROWCOUNT;

      END LOOP;

      /* --------------------------------------------------------- */
      /* INSERT LOG */
      /* --------------------------------------------------------- */
      /* SET @n_log_count = @@ROWCOUNT; */
      V_LOG_TYPE    := 'APPEND';
      V_LOG_MESSAGE := 'INSERT INTO scm_dnm_scs_stock';
      V_DESCRIPTION := 'if_seq = ' || V_IF_SEQ;
      V_EVENT_DATE  := SYSDATE;
      PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, V_EVENT_DATE);
            /* --------------------------------------------------------- */

      /* 처리된 row 마킹 */
      UPDATE XIF_SCS_STOCK_RSLT_SUM_R_SN
         SET PROC_FLAG = 'Y'
       WHERE PROC_FLAG = 'P';

      /* IF data  삭제 (90일 이전 데이터 삭제) */
      DELETE
        FROM XIF_SCS_STOCK_RSLT_SUM_R_SN
       WHERE IF_RCV_DATE < SYSDATE - 90;

      IF DBMS_TRANSACTION.LOCAL_TRANSACTION_ID IS NOT NULL THEN
        COMMIT;
      END IF;

    END;

  EXCEPTION
    WHEN OTHERS THEN
      IF DBMS_TRANSACTION.LOCAL_TRANSACTION_ID IS NOT NULL THEN
        ROLLBACK;
      END IF;
      /* ERROR LOG */
      V_LOG_TYPE    := 'ERROR';
      V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
      V_DESCRIPTION := SUBSTR('ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 500);
      V_EVENT_DATE  := SYSDATE;
      PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, V_EVENT_DATE
                         , NULL, TO_CHAR(SQLCODE), SUBSTR(SQLERRM, 1, 1000), DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
  END;

  /* 종료 LOG */
  V_LOG_TYPE    := 'END';
  V_LOG_MESSAGE := '########## END of procedure ##########';
  V_DESCRIPTION := '';
  V_EVENT_DATE  := SYSDATE;
  PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, V_EVENT_DATE);

END;

PROCEDURE PR_UI_SQL_LOG
(
    P_PROG_ID       IN  VARCHAR2
  , P_USER_ID       IN  VARCHAR2
  , P_QUERY_ID      IN  VARCHAR2
  , P_QUERY_SEQ     IN  NUMBER
  , P_QUERY_VALUE   IN  VARCHAR2
  , P_JOB_TYPE      IN  VARCHAR2
  , P_START         IN  DATE
  , P_END           IN  DATE
  , P_INST_ID       OUT VARCHAR2
)
IS
    PRAGMA AUTONOMOUS_TRANSACTION;

	-- SEQ_UI_SQL
    V_INST_SEQ          NUMBER(10);
    V_INST_ID           VARCHAR2(20 CHAR);
    V_SQL               VARCHAR2(32767);

    V_EACH_LINESIZE     NUMBER(10);
    V_LINE              NUMBER(10);
    V_ROOP              NUMBER(10);
    V_START             NUMBER(10);
    V_END               NUMBER(10);
    V_LENGTH            NUMBER(10);

    V_LINE_TEXT         VARCHAR2(4000 CHAR);
BEGIN

    V_SQL := P_QUERY_VALUE;
	--SET @v_inst_id = convert(decimal(12,4),getdate())
	--SET @v_inst_id = REPLACE(@v_inst_id,'.','_');
	--SET @v_inst_id = @v_inst_id + LEFT(@p_user_id,10)
    V_INST_SEQ := SEQ_UI_SQL.NEXTVAL;
    V_INST_ID := TO_CHAR(V_INST_SEQ);

    V_EACH_LINESIZE := 4000;
    /* MSSQL LEN 은 후행 공백을 세지 않는다. 값이 비어 있으면 NULL 이 되어 아래 반복문을 한 번도 돌지 않는다(AS-IS 동일). */
    V_LENGTH := LENGTH(RTRIM(V_SQL));

    V_LINE := TRUNC(V_LENGTH / V_EACH_LINESIZE);
    V_LINE := V_LINE + 1;
    V_ROOP := 0;

    WHILE V_LINE > 0
    LOOP
        V_START := V_EACH_LINESIZE * V_ROOP + 1;
        V_LINE_TEXT := SUBSTR(V_SQL, V_START, V_EACH_LINESIZE);
		--print @line_text

        INSERT INTO TH_UIS_SQL_LOG
             ( PROG_ID
             , QUERY_ID
             , QUERY_SEQ
             , INST_SEQ
             , QUERY_VALUE
             , JOB_TYPE
             , START_TIME
             , END_TIME
             , INSERT_ID
             , INSERT_TIME
             )
        VALUES
             ( P_PROG_ID
             , P_QUERY_ID
						--@p_query_seq,
             , V_ROOP
             , V_INST_ID
             , V_LINE_TEXT
             , P_JOB_TYPE
             , P_START
             , P_END
             , P_USER_ID
             , SYSDATE
             );

        V_LINE := V_LINE - 1;
        V_ROOP := V_ROOP + 1;
    END LOOP;

    COMMIT;

    P_INST_ID := V_INST_ID;

END PR_UI_SQL_LOG;

PROCEDURE         "P_SYS0014_GET_GROUP_LIST_M" (
    P_SEARCH         IN  VARCHAR2,
    O_RC1            OUT SYS_REFCURSOR,
    O_RESULT_CURSOR  OUT SYS_REFCURSOR
)
AS
BEGIN
    OPEN O_RC1 FOR
    SELECT USER_GR_ID, USER_GR_NM, USE_YN
      FROM SCM_MGR.SCM_ADM_USER_GR_M
     WHERE P_SEARCH IS NULL OR P_SEARCH = ''
        OR UPPER(USER_GR_ID) LIKE '%' || UPPER(P_SEARCH) || '%'
        OR UPPER(USER_GR_NM) LIKE '%' || UPPER(P_SEARCH) || '%'
     ORDER BY USER_GR_ID;

    OPEN O_RESULT_CURSOR FOR
    SELECT '0' AS CODE, 'SUCCESS' AS MSG FROM DUAL;
EXCEPTION
    WHEN OTHERS THEN
        DECLARE V_ERR VARCHAR2(4000) := SUBSTR(SQLERRM, 1, 4000);
        BEGIN
            OPEN O_RC1 FOR SELECT NULL AS DUMMY FROM DUAL WHERE 1=0;
            OPEN O_RESULT_CURSOR FOR SELECT '-1' AS CODE, V_ERR AS MSG FROM DUAL;
        END;
END P_SYS0014_GET_GROUP_LIST_M;

PROCEDURE           "SCM0001_GET_DIVISION" 
(
