'       , z.sql_long_text'||CHR(10)||
'       , COUNT(z.user_id) OVER (PARTITION BY z.user_id) user_cnt'||CHR(10)||
'       , DENSE_RANK() OVER (PARTITION BY z.user_id ORDER BY z.user_id, z.segment1, z.segment2, z.segment3, z.segment4, z.segment5, z.segment6, z.segment7, z.segment8, z.segment9, z.segment10) rank_no'||CHR(10)||
'    FROM ('||CHR(10)||
'  SELECT x.use_type_code'||CHR(10)||
'       , CASE WHEN x.user_id IS NOT NULL THEN x.user_id'||CHR(10)||
'              WHEN y.user_id IS NOT NULL THEN y.user_id'||CHR(10)||
'              ELSE y.user_id'||CHR(10)||
'         END user_id'||CHR(10)||
'       , CASE WHEN x.user_name IS NULL THEN y.user_name'||CHR(10)||
'              WHEN y.user_name IS NULL THEN x.user_name'||CHR(10)||
'              ELSE y.user_name'||CHR(10)||
'         END user_name'||CHR(10)||
'       , CASE WHEN x.email_addr IS NULL THEN y.email_addr'||CHR(10)||
'              WHEN y.email_addr IS NULL THEN x.email_addr'||CHR(10)||
'              ELSE y.email_addr'||CHR(10)||
'         END email_addr'||CHR(10)||
'       , CASE WHEN x.mobile_phone IS NULL THEN y.mobile_phone'||CHR(10)||
'              WHEN y.mobile_phone IS NULL THEN x.mobile_phone'||CHR(10)||
'              ELSE y.mobile_phone'||CHR(10)||
'         END mobile_phone'||CHR(10)||
'       , x.language_code'||CHR(10)||
'       , y.segment1, y.segment2, y.segment3, y.segment4, y.segment5, y.segment6, y.segment7, y.segment8, y.segment9, y.segment10'||CHR(10)||
'       , y.column1, y.column2, y.column3, y.column4, y.column5, y.column6, y.column7, y.column8, y.column9, y.column10'||CHR(10)||
'       , x.mail_title'||CHR(10)||
'       , x.body_contents'||CHR(10)||
'       , x.sql_long_text'||CHR(10)||
'    FROM ('||V_RESULT||') y,'||CHR(10)||
'       ( SELECT a.use_type_code'||CHR(10)||
'              , c.user_id'||CHR(10)||
/* 2026.09.30 AJS 수정 (START) */
--'              , e.UserName as user_name'||CHR(10)||
--'              , e.Email as email_addr'||CHR(10)||
--'              , e.CellPhoneNum as mobile_phone'||CHR(10)||
'              , e.USER_NM as user_name'||CHR(10)||
'              , e.USER_EML as email_addr'||CHR(10)||
'              , e.USER_HPHN as mobile_phone'||CHR(10)||
/* 2026.09.30 AJS 수정 (END) */
'              , b.language_code'||CHR(10)||
'              , b.mail_title'||CHR(10)||
'              , d.SEGMENT3 header_contents'||CHR(10)||
'              , CASE a.USE_TYPE_CODE WHEN ''MAIL'' THEN REPLACE(b.message_content, CHR(10), ''<br><br>'')'||CHR(10)||
'                                     WHEN ''SMS'' THEN b.message_content'||CHR(10)||
'                END body_contents'||CHR(10)||
'              , d.SEGMENT3 foot_contents'||CHR(10)||
'              , a.SQL_LONG_TEXT'||CHR(10)||
'           FROM SCM_ADM_RECIPIENT_LIST a'||CHR(10)||
'                INNER JOIN SCM_ADM_RECIPIENT_MESSAGE b ON a.CATEGORY_ID = b.CATEGORY_ID'||CHR(10)||
'                LEFT OUTER JOIN SCM_ADM_RECIPIENT_ASSIGN c ON b.CATEGORY_ID = c.CATEGORY_ID'||CHR(10)||
'                INNER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL d ON d.SEGMENT1 = b.LANGUAGE_CODE AND d.LOOKUP_TYPE = ''MAIL_HEADER_FOOT'' AND d.VALID_YN = ''Y'''||CHR(10)||
/* 2026.09.30 AJS 수정 (START) */
--'                LEFT OUTER JOIN TB_FX_USER e ON b.LANGUAGE_CODE = e.Language AND c.USER_ID = e.UserID'||CHR(10)||
'                LEFT OUTER JOIN SCM_ADM_USER_M e ON b.LANGUAGE_CODE = e.LANG_CD AND c.USER_ID = e.USER_ID'||CHR(10)||
/* 2026.09.30 AJS 수정 (END) */
'          WHERE a.category_id = '||TO_CHAR(P_CATEGORY_ID)||CHR(10)||
'            AND a.VALID_YN = ''Y'''||CHR(10)||
'          ) x'||CHR(10)||
'   WHERE x.language_code = y.language_code'||CHR(10)||
'       ) z ORDER BY user_id';


    EXECUTE IMMEDIATE 'INSERT INTO GT_MAILBATCH ( USE_TYPE_CODE, USER_ID, USER_NAME, EMAIL_ADDR, MOBILE_PHONE, LANGUAGE_CODE'
        ||', SEGMENT1, SEGMENT2, SEGMENT3, SEGMENT4, SEGMENT5, SEGMENT6, SEGMENT7, SEGMENT8, SEGMENT9, SEGMENT10'
        ||', COLUMN1, COLUMN2, COLUMN3, COLUMN4, COLUMN5, COLUMN6, COLUMN7, COLUMN8, COLUMN9, COLUMN10'
        ||', MAIL_TITLE, BODY_CONTENTS, SQL_LONG_TEXT, USER_CNT, RANK_NO ) '||V_RESULT4;

    BEGIN
        /* 시작 LOG */
        V_LOG_TYPE := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := TO_CHAR(P_CATEGORY_ID);
        D_EVENT_DATE := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        V_CHECK := 0;
        V_BODY_CONT := '';
        V_RECEIVER_TEMP := '';

        FOR REC IN (SELECT * FROM GT_MAILBATCH ORDER BY USER_ID) LOOP
            V_USE_TYPE_CODE := REC.USE_TYPE_CODE;
            V_USER_ID       := REC.USER_ID;
            V_MAIL_TITLE    := REC.MAIL_TITLE;
            V_BODY_CONTENTS := REC.BODY_CONTENTS;
            V_SQL_LONG_TEXT := REC.SQL_LONG_TEXT;
            V_SEGMENT1  := REC.SEGMENT1;  V_SEGMENT2  := REC.SEGMENT2;  V_SEGMENT3  := REC.SEGMENT3;
            V_SEGMENT4  := REC.SEGMENT4;  V_SEGMENT5  := REC.SEGMENT5;  V_SEGMENT6  := REC.SEGMENT6;
            V_SEGMENT7  := REC.SEGMENT7;  V_SEGMENT8  := REC.SEGMENT8;  V_SEGMENT9  := REC.SEGMENT9;
            V_SEGMENT10 := REC.SEGMENT10;
            V_COLUMN1  := REC.COLUMN1;  V_COLUMN2  := REC.COLUMN2;  V_COLUMN3  := REC.COLUMN3;
            V_COLUMN4  := REC.COLUMN4;  V_COLUMN5  := REC.COLUMN5;  V_COLUMN6  := REC.COLUMN6;
            V_COLUMN7  := REC.COLUMN7;  V_COLUMN8  := REC.COLUMN8;  V_COLUMN9  := REC.COLUMN9;
            V_COLUMN10 := REC.COLUMN10;

            IF V_USE_TYPE_CODE = 'MAIL' THEN
                V_TO_MAIL := V_USER_ID || '@lgensol.com';

                IF V_SQL_LONG_TEXT IS NULL THEN
                    V_SQL_YN := 'N';
                    /* 메일 발송 */
                    PKG_DMF0003.P_SCM_ADM_MAIL_SEND(V_TO_MAIL, V_MAIL_TITLE, V_BODY_CONTENTS, 'N');
                    /* MAIL 발송 LOG 저장 (2025/08/19 kimcd : log 입력용 100자 절단) */
                    V_SEGMENT5_LOG := SUBSTR(V_SEGMENT5, 1, 100);
                    SCM_ADM_SAVE_MAIL_SEND_BATCH_LOG(V_USE_TYPE_CODE, P_CATEGORY_ID, V_SEGMENT1, V_SEGMENT2, V_SEGMENT3, V_SEGMENT4
                      , V_SEGMENT5_LOG, V_SEGMENT6, V_SEGMENT7, V_SEGMENT8, V_SEGMENT9, V_SEGMENT10, ' ', V_USER_ID);
                ELSE
                    IF V_RECEIVER_TEMP IS NULL THEN
                        V_RECEIVER_TEMP := V_TO_MAIL;
                    END IF;

                    IF V_RECEIVER_TEMP != V_TO_MAIL THEN
                        IF LENGTH(V_HEAD_CONT) > 0 THEN
                            V_TABLE_BODY := V_HTML_HEAD || '</br>'
                                || '<b>' || REPLACE(V_BODY_CONTENTS, CHR(10), '<br>') || '</b>'
                                || '<div id="divBody" style="width: 100%; overflow-x: auto; overflow-y: auto; font-size: 9pt; line-break: auto;">'
                                || '<table style=''border-top:2px solid #c8294b; width:1000px;''>'
                                || '<thead>' || V_HEAD_CONT || '</thead>'
                                || '<tbody>' || V_BODY_CONT || '</tbody>'
                                || '</div></body></html>';
                            /* 메일 발송 */
                            PKG_DMF0003.P_SCM_ADM_MAIL_SEND(V_RECEIVER_TEMP, V_MAIL_TITLE, V_TABLE_BODY, 'Y');
                            V_BODY_CONTENTS := '';
                            V_CHECK := 0;
                            V_BODY_CONT := '';
                            /* MAIL 발송 LOG 저장 */
                            V_SEGMENT5_LOG := SUBSTR(V_SEGMENT5, 1, 100);
                            SCM_ADM_SAVE_MAIL_SEND_BATCH_LOG(V_USE_TYPE_CODE, P_CATEGORY_ID, V_SEGMENT1, V_SEGMENT2, V_SEGMENT3, V_SEGMENT4
                              , V_SEGMENT5_LOG, V_SEGMENT6, V_SEGMENT7, V_SEGMENT8, V_SEGMENT9, V_SEGMENT10, ' ', V_RECEIVER_TEMP);
                            V_RECEIVER_TEMP := V_TO_MAIL;
                        END IF;
                    END IF;

                    V_SQL_YN := 'Y';
                    IF V_CHECK = 0 THEN
                        V_HEAD_CONT := '';
                        V_HEAD_CONT := V_HEAD_CONT || '<tr>';
                        IF V_COLUMN1  IS NOT NULL THEN V_HEAD_CONT := V_HEAD_CONT || '<th>' || V_COLUMN1  || '</th>'; END IF;
                        IF V_COLUMN2  IS NOT NULL THEN V_HEAD_CONT := V_HEAD_CONT || '<th>' || V_COLUMN2  || '</th>'; END IF;
                        IF V_COLUMN3  IS NOT NULL THEN V_HEAD_CONT := V_HEAD_CONT || '<th>' || V_COLUMN3  || '</th>'; END IF;
                        IF V_COLUMN4  IS NOT NULL THEN V_HEAD_CONT := V_HEAD_CONT || '<th>' || V_COLUMN4  || '</th>'; END IF;
                        IF V_COLUMN5  IS NOT NULL THEN V_HEAD_CONT := V_HEAD_CONT || '<th>' || V_COLUMN5  || '</th>'; END IF;
                        IF V_COLUMN6  IS NOT NULL THEN V_HEAD_CONT := V_HEAD_CONT || '<th>' || V_COLUMN6  || '</th>'; END IF;
                        IF V_COLUMN7  IS NOT NULL THEN V_HEAD_CONT := V_HEAD_CONT || '<th>' || V_COLUMN7  || '</th>'; END IF;
                        IF V_COLUMN8  IS NOT NULL THEN V_HEAD_CONT := V_HEAD_CONT || '<th>' || V_COLUMN8  || '</th>'; END IF;
                        IF V_COLUMN9  IS NOT NULL THEN V_HEAD_CONT := V_HEAD_CONT || '<th>' || V_COLUMN9  || '</th>'; END IF;
                        IF V_COLUMN10 IS NOT NULL THEN V_HEAD_CONT := V_HEAD_CONT || '<th>' || V_COLUMN10 || '</th>'; END IF;
                        V_HEAD_CONT := V_HEAD_CONT || '</tr>';
                        V_CHECK := V_CHECK + 1;
                    END IF;

                    V_BODY_CONT := V_BODY_CONT || '<tr>';
                    IF V_COLUMN1  IS NOT NULL THEN V_BODY_CONT := V_BODY_CONT || '<td>' || REPLACE(V_SEGMENT1 , CHR(10), ' ') || '</td>'; END IF;
                    IF V_COLUMN2  IS NOT NULL THEN V_BODY_CONT := V_BODY_CONT || '<td>' || REPLACE(V_SEGMENT2 , CHR(10), ' ') || '</td>'; END IF;
                    IF V_COLUMN3  IS NOT NULL THEN V_BODY_CONT := V_BODY_CONT || '<td>' || REPLACE(V_SEGMENT3 , CHR(10), ' ') || '</td>'; END IF;
                    IF V_COLUMN4  IS NOT NULL THEN V_BODY_CONT := V_BODY_CONT || '<td>' || REPLACE(V_SEGMENT4 , CHR(10), ' ') || '</td>'; END IF;
                    IF V_COLUMN5  IS NOT NULL THEN V_BODY_CONT := V_BODY_CONT || '<td>' || REPLACE(V_SEGMENT5 , CHR(10), ' ') || '</td>'; END IF;
                    IF V_COLUMN6  IS NOT NULL THEN V_BODY_CONT := V_BODY_CONT || '<td>' || REPLACE(V_SEGMENT6 , CHR(10), ' ') || '</td>'; END IF;
                    IF V_COLUMN7  IS NOT NULL THEN V_BODY_CONT := V_BODY_CONT || '<td>' || REPLACE(V_SEGMENT7 , CHR(10), ' ') || '</td>'; END IF;
                    IF V_COLUMN8  IS NOT NULL THEN V_BODY_CONT := V_BODY_CONT || '<td>' || REPLACE(V_SEGMENT8 , CHR(10), ' ') || '</td>'; END IF;
                    IF V_COLUMN9  IS NOT NULL THEN V_BODY_CONT := V_BODY_CONT || '<td>' || REPLACE(V_SEGMENT9 , CHR(10), ' ') || '</td>'; END IF;
                    IF V_COLUMN10 IS NOT NULL THEN V_BODY_CONT := V_BODY_CONT || '<td>' || REPLACE(V_SEGMENT10, CHR(10), ' ') || '</td>'; END IF;
                    V_BODY_CONT := V_BODY_CONT || '</tr>';
                END IF;
            ELSIF V_USE_TYPE_CODE = 'SMS' THEN

                NULL;
            END IF;
        END LOOP;

        IF V_SQL_YN = 'Y' THEN
            IF LENGTH(V_HEAD_CONT) > 0 THEN
                V_TABLE_BODY := V_HTML_HEAD || '</br>'
                    || '<b>' || REPLACE(V_BODY_CONTENTS, CHR(10), '<br>') || '</b>'
                    || '<div id="divBody" style="width: 100%; overflow-x: auto; overflow-y: auto; font-size: 9pt; line-break: auto;">'
                    || '<table style=''border-top:2px solid #c8294b; width:1000px;''>'
                    || '<thead>' || V_HEAD_CONT || '</thead>'
                    || '<tbody>' || V_BODY_CONT || '</tbody>'
                    || '</table></div></body></html>';
                /* 메일 발송 */
                PKG_DMF0003.P_SCM_ADM_MAIL_SEND(V_TO_MAIL, V_MAIL_TITLE, V_TABLE_BODY, 'Y');
                V_BODY_CONTENTS := '';
                V_CHECK := 0;
                V_BODY_CONT := '';
                /* MAIL 발송 LOG 저장 */
                V_SEGMENT5_LOG := SUBSTR(V_SEGMENT5, 1, 100);
                SCM_ADM_SAVE_MAIL_SEND_BATCH_LOG(V_USE_TYPE_CODE, P_CATEGORY_ID, V_SEGMENT1, V_SEGMENT2, V_SEGMENT3, V_SEGMENT4
                  , V_SEGMENT5_LOG, V_SEGMENT6, V_SEGMENT7, V_SEGMENT8, V_SEGMENT9, V_SEGMENT10, ' ', V_TO_MAIL);
            END IF;
        END IF;

        V_LOG_TYPE := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := TO_CHAR(P_CATEGORY_ID);
        D_EVENT_DATE := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    EXCEPTION
        WHEN OTHERS THEN

            V_ERROR_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            INSERT INTO SCM_SYS_LOG_BATCH ( PROGRAM_NAME, LOG_TYPE, LOG_COUNT, LOG_MESSAGE, DESCRIPTION, EVENT_DATE
                                          , CREATION_DATE, CREATED_BY, LAST_UPDATE_DATE, LAST_UPDATED_BY )
            VALUES ( V_PROGRAM_NAME, 'ERROR', NULL, V_ERROR_MESSAGE, NULL, SYSDATE
                   , SYSDATE, V_PROGRAM_NAME, SYSDATE, V_PROGRAM_NAME );
            COMMIT;

            /* MAIL 발송 LOG 저장 */
            SCM_ADM_SAVE_MAIL_SEND_BATCH_LOG('ERROR', P_CATEGORY_ID, 'MAIN ERROR', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', V_ERROR_MESSAGE, ' ');
            COMMIT;


            DBMS_OUTPUT.PUT_LINE('F');
            DBMS_OUTPUT.PUT_LINE('[' || TO_CHAR(SQLCODE) || ']' || SQLERRM);
    END;
END;

PROCEDURE           "SCM_ADM_MAIL_SEND_BATCH_MST" 

/*
 * Program ID   : SCM_ADM_MAIL_SEND_BATCH_MST
 * Description  : Mail 발송 정보 BATCH
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2018/03/05   ygkim   Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 * 2018/05/14   ygkim	Mail, SMS 구분 추가
 * 2018/10/05   ygkim   Mail 발송 시 UI 수신자 등록 여부를 가지고 발송 로직 구분
 * 2018/10/11   hwyoon	발송시간 10분단위로 변경
 * 2026.07.06   ZIONEX      [PJ202650304] NextSCM Migration
 *===================================================================================================
 */
/* @p_category_id int (사용하지 않는 파라메터) */
IS
    V_CATEGORY_ID         NUMBER;
    V_USE_TYPE_CODE       VARCHAR2(80 CHAR);
    V_CYCLE_CLASS_CODE    VARCHAR2(10 CHAR);
    V_DETAIL_CLASS_CODE   VARCHAR2(20 CHAR);
    V_SEND_TIME_TEXT      VARCHAR2(80 CHAR);

    V_WEEK_DAY            VARCHAR2(10 CHAR);
    V_MONTH_DAY           VARCHAR2(10 CHAR);
    V_TIME                VARCHAR2(10 CHAR);
    V_P_CATEGORY_ID       NUMBER;

    V_UI_USER_CNT         PLS_INTEGER;

    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME        VARCHAR2(150 CHAR) := 'SCM_ADM_MAIL_SEND_BATCH_MST';
    V_LOG_TYPE            VARCHAR2(30 CHAR);          /* START/END/ERROR/... */
    N_LOG_COUNT           PLS_INTEGER := 0;
    V_LOG_MESSAGE         VARCHAR2(1000 CHAR);
    V_DESCRIPTION         VARCHAR2(500 CHAR);
    D_EVENT_DATE          DATE;
    V_ERRMSG              VARCHAR2(1000 CHAR);

    CURSOR CUR_MAIN IS
        SELECT CATEGORY_ID
             , USE_TYPE_CODE
             , CYCLE_CLASS_CODE
             , DETAIL_CLASS_CODE
             , SEND_TIME_TEXT
          FROM (
                SELECT NRM.CATEGORY_ID
                     , NRM.USE_TYPE_CODE
                     , NRM.CYCLE_CLASS_CODE
                     , FLV.SEGMENT4 DETAIL_CLASS_CODE
                     , (SUBSTR(FLV1.SEGMENT4, 1, 2)||FLV2.SEGMENT4) SEND_TIME_TEXT  /* ,flv1.segment4 send_time_text */
                  FROM SCM_ADM_RECIPIENT_LIST        NRM
                     , SCM_ADM_LOOKUP_MASTER_DETAIL  FLV
                     , SCM_ADM_LOOKUP_MASTER_DETAIL  FLV1
                     , SCM_ADM_LOOKUP_MASTER_DETAIL  FLV2
                 WHERE NRM.CYCLE_CLASS_CODE   = FLV.SEGMENT1
                   AND NRM.DETAIL_CLASS_CODE  = FLV.SEGMENT2
                   AND NRM.SEND_TIME_TEXT     = FLV1.SEGMENT2
                   AND NVL(NULLIF(NRM.SEND_MIN_TIME_TEXT, ''), 'H00') = FLV2.SEGMENT2
                   AND NRM.VALID_YN           = 'Y'
                   AND FLV.LOOKUP_TYPE        = 'MAIL_SEND_CYCLE_DETAIL'
                   AND FLV.VALID_YN           = 'Y'
                   AND FLV1.LOOKUP_TYPE       = 'MAIL_SEND_CYCLE_DETAIL'
                   AND FLV1.VALID_YN          = 'Y'
                   AND FLV2.LOOKUP_TYPE       = 'MAIL_SEND_CYCLE_DETAIL'
                   AND FLV2.SEGMENT1          = 'HOUR'
                   AND NRM.CYCLE_CLASS_CODE  NOT IN ('DAY', 'RT')
                UNION ALL
                SELECT NRM.CATEGORY_ID
                     , NRM.USE_TYPE_CODE
                     , NRM.CYCLE_CLASS_CODE
                     , ''
                     , (SUBSTR(FLV.SEGMENT4, 1, 2)||FLV2.SEGMENT4) SEND_TIME_TEXT  /* ,flv.segment4 send_time_text */
                  FROM SCM_ADM_RECIPIENT_LIST        NRM
                     , SCM_ADM_LOOKUP_MASTER_DETAIL  FLV
                     , SCM_ADM_LOOKUP_MASTER_DETAIL  FLV2
                 WHERE NRM.CYCLE_CLASS_CODE   = FLV.SEGMENT1
                   AND NRM.DETAIL_CLASS_CODE  = FLV.SEGMENT2
                   AND NVL(NULLIF(NRM.SEND_TIME_TEXT, ''), 'H00') = FLV2.SEGMENT2
                   AND NRM.VALID_YN           = 'Y'
                   AND FLV.LOOKUP_TYPE        = 'MAIL_SEND_CYCLE_DETAIL'
                   AND FLV.VALID_YN           = 'Y'
                   AND FLV2.LOOKUP_TYPE       = 'MAIL_SEND_CYCLE_DETAIL'
                   AND FLV2.SEGMENT1          = 'HOUR'
                   AND NRM.CYCLE_CLASS_CODE  IN ('DAY', 'RT')
               ) A
         WHERE (
                   (V_P_CATEGORY_ID IS NULL AND CYCLE_CLASS_CODE != 'RT')
                OR (V_P_CATEGORY_ID IS NOT NULL AND CATEGORY_ID = V_P_CATEGORY_ID)
               );
BEGIN
    V_P_CATEGORY_ID := NULL;


    BEGIN
        SELECT A.DAYOFWEEK
             , A.CALENDAR_DAY
             , (SUBSTR(TO_CHAR(SYSDATE, 'HH24:MI:SS'), 1, 2)||SUBSTR(TO_CHAR(SYSDATE, 'HH24:MI:SS'), 4, 1)||'0')
          INTO V_WEEK_DAY
             , V_MONTH_DAY
             , V_TIME
          FROM SCM_SYS_CALENDAR_M A
         WHERE TRUNC(A.BASIS_DATE) = TRUNC(SYSDATE);
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            NULL;
    END;

    /* 시작 LOG */
    V_LOG_TYPE := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    FOR REC IN CUR_MAIN LOOP
        V_CATEGORY_ID := REC.CATEGORY_ID;
        V_USE_TYPE_CODE := REC.USE_TYPE_CODE;
        V_CYCLE_CLASS_CODE := REC.CYCLE_CLASS_CODE;
        V_DETAIL_CLASS_CODE := REC.DETAIL_CLASS_CODE;
        V_SEND_TIME_TEXT := REC.SEND_TIME_TEXT;

        IF V_USE_TYPE_CODE = 'MAIL' THEN
            V_UI_USER_CNT := 0;
            SELECT COUNT(USER_ID)
              INTO V_UI_USER_CNT
              FROM SCM_ADM_RECIPIENT_ASSIGN
             WHERE CATEGORY_ID = V_CATEGORY_ID;
        END IF;

        IF V_CYCLE_CLASS_CODE = 'DAY' THEN
            IF V_SEND_TIME_TEXT = V_TIME THEN
                IF V_USE_TYPE_CODE = 'MAIL' THEN
                    IF V_UI_USER_CNT > 0 THEN  /* UI에서 수신자가 등록되어 있는 경우 */

                        EXECUTE IMMEDIATE 'BEGIN SCM_ADM_MAIL_SEND_DATA(:1); END;' USING V_CATEGORY_ID;
                    ELSE  /* Sql에 수신자가 있는 경우 */
                        EXECUTE IMMEDIATE 'BEGIN SCM_ADM_MAIL_SEND_BATCH(:1); END;' USING V_CATEGORY_ID;
                    END IF;
                ELSE
                    SCM_ADM_SMS_SEND_BATCH(V_CATEGORY_ID);
                END IF;
            END IF;
        ELSIF V_CYCLE_CLASS_CODE = 'WEEK' THEN
            IF V_DETAIL_CLASS_CODE = V_WEEK_DAY AND V_SEND_TIME_TEXT = V_TIME THEN
                IF V_USE_TYPE_CODE = 'MAIL' THEN
                    IF V_UI_USER_CNT > 0 THEN  /* UI에서 수신자가 등록되어 있는 경우 */
                        EXECUTE IMMEDIATE 'BEGIN SCM_ADM_MAIL_SEND_DATA(:1); END;' USING V_CATEGORY_ID;
                    ELSE  /* Sql에 수신자가 있는 경우 */
                        EXECUTE IMMEDIATE 'BEGIN SCM_ADM_MAIL_SEND_BATCH(:1); END;' USING V_CATEGORY_ID;
                    END IF;
                ELSE
                    SCM_ADM_SMS_SEND_BATCH(V_CATEGORY_ID);
                END IF;
            END IF;
        ELSIF V_CYCLE_CLASS_CODE = 'MONTH' THEN
            IF V_DETAIL_CLASS_CODE = V_MONTH_DAY AND V_SEND_TIME_TEXT = V_TIME THEN
                IF V_USE_TYPE_CODE = 'MAIL' THEN
                    IF V_UI_USER_CNT > 0 THEN  /* UI에서 수신자가 등록되어 있는 경우 */
                        EXECUTE IMMEDIATE 'BEGIN SCM_ADM_MAIL_SEND_DATA(:1); END;' USING V_CATEGORY_ID;
                    ELSE  /* Sql에 수신자가 있는 경우 */
                        EXECUTE IMMEDIATE 'BEGIN SCM_ADM_MAIL_SEND_BATCH(:1); END;' USING V_CATEGORY_ID;
                    END IF;
                ELSE
                    SCM_ADM_SMS_SEND_BATCH(V_CATEGORY_ID);
                END IF;
            END IF;
        ELSIF V_CYCLE_CLASS_CODE = 'RT' THEN
            IF V_USE_TYPE_CODE = 'MAIL' THEN
                IF V_UI_USER_CNT > 0 THEN  /* UI에서 수신자가 등록되어 있는 경우 */
                    EXECUTE IMMEDIATE 'BEGIN SCM_ADM_MAIL_SEND_DATA(:1); END;' USING V_CATEGORY_ID;
                ELSE  /* Sql에 수신자가 있는 경우 */
                    EXECUTE IMMEDIATE 'BEGIN SCM_ADM_MAIL_SEND_BATCH(:1); END;' USING V_CATEGORY_ID;
                END IF;
            ELSE
                SCM_ADM_SMS_SEND_BATCH(V_CATEGORY_ID);
            END IF;
        END IF;
    END LOOP;

    IF SUBSTR(TO_CHAR(SYSDATE, 'HH24:MI:SS'), 1, 2) = '05' THEN
        DELETE
          FROM SCM_ADM_SMS_MAIL_SEND_LOG
         WHERE SEND_DATE < TRUNC(SYSDATE) - 15;
    END IF;

    V_LOG_TYPE := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);


EXCEPTION
    WHEN OTHERS THEN
        V_ERRMSG := SQLERRM;
        INSERT
          INTO SCM_SYS_LOG_BATCH
             ( PROGRAM_NAME
             , LOG_TYPE
             , LOG_COUNT
             , LOG_MESSAGE
             , DESCRIPTION
             , EVENT_DATE
             , CREATION_DATE
             , CREATED_BY
             , LAST_UPDATE_DATE
             , LAST_UPDATED_BY )
        VALUES ( V_PROGRAM_NAME
             , 'ERROR'
             , NULL
             , V_ERRMSG
             , 'v_category_id:' ||TO_CHAR(V_CATEGORY_ID)
             , SYSDATE
             , SYSDATE
             , V_PROGRAM_NAME
             , SYSDATE
             , V_PROGRAM_NAME );
        COMMIT;
END SCM_ADM_MAIL_SEND_BATCH_MST;

PROCEDURE         "SCM_ADM_MAIL_SEND_DATA" 
(
    P_CATEGORY_ID   IN NUMBER
)
/*
 * Program ID   : SCM_ADM_MAIL_SEND_DATA
 * Description  : MAIL 발송 BATCH - UI에서 수신자가 등록되어 있는 경우
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2018/10/05   ygkim                   Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 * 2018/10/10   ygkim                   Mail 내용이 있을 경우에만 발송되도록 수정
 * 2018/10/11   ygkim                   5명 이상일 경우 5명씩 나눠서 보내는걸로 수정
 * 2023/11/24   chaan           V1.1.1  PJ20216994 / LGES Digital SCM 3 Level 가속화를 위한 개선 Phase 2        - SQL 결과 컬럼이 10개로 제한 -> 컬럼 갯수에 상관없이 유연하게 대응하도록 변경
 *                                                                                                              - 테스트모드 추가 (메일 개발자에게만 발송)
 * 2023/12/14   chaan           V1.1.2  PJ20216994 / LGES Digital SCM 3 Level 가속화를 위한 개선 Phase 2        - SQL 쿼리 결과셋이 n 개 가능하도록 변경
 * 2026.07.06   ZIONEX  [PJ202650304]  NextSCM Migration
 * 2026.09.16   AJS     쿼리 구분자 CHR(8224)가 공백 두 칸으로 해석되어 † 로 교정, 4000바이트 넘는 쿼리 조각이 잘리지 않게 CLOB 단위로 분할
 *
 * ex) exec SCM_ADM_MAIL_SEND_DATA 8
 */
AS
    V_TEST_MODE             VARCHAR2(1 CHAR) := 'F';
    /* 개발자 이메일(전송 테스트용) */
    V_DEV_EMAIL             VARCHAR2(100 CHAR) := 'kimcd@lgespartner.com';

    /* SQL n개 처리를 위한 쿼리구문 구분자. MSSQL 원본 '†'(dagger, U+2020) = CHR(8224) */
    V_SQL_SEPERATOR         VARCHAR2(1 CHAR) := TO_CHAR(UNISTR('\2020'));             -- 2026.09.16 AJS
    N_SQL_LEN               PLS_INTEGER;                                              -- 2026.09.16 AJS
    N_SQL_START             PLS_INTEGER;                                              -- 2026.09.16 AJS
    N_SQL_POS               PLS_INTEGER;                                              -- 2026.09.16 AJS


    V_TABLE_CONTENTS        CLOB;
    V_CURR_TABLE_CONTENTS   CLOB;
    V_MAIL_TEXT             CLOB;
    V_SQL                   CLOB;
    V_CURR_SQL              CLOB;
    V_BODY_TITLE            CLOB;

    V_USER_ID               VARCHAR2(40 CHAR);
    V_MAIL_RECEIVER_LIST    VARCHAR2(4000 CHAR);
    V_MAIL_TITLE            VARCHAR2(100 CHAR);
    V_SEND_CNT              INTEGER := 0;
    V_USER_CNT              INTEGER := 0;

    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME          VARCHAR2(150 CHAR) := 'SCM_ADM_MAIL_SEND_DATA';
    V_LOG_TYPE              VARCHAR2(30 CHAR);
    N_LOG_COUNT             INTEGER := 0;
    V_LOG_MESSAGE           VARCHAR2(1000 CHAR);
    V_DESCRIPTION           VARCHAR2(500 CHAR);
    D_EVENT_DATE            DATE;


    V_ERROR_MESSAGE         VARCHAR2(1000 CHAR);
    V_ERR_PROC              VARCHAR2(600 CHAR);
    V_ERR_MSG               VARCHAR2(4000 CHAR);
    V_ERR_CODE              NUMBER;


    CURSOR CUR_SQL_SPLIT(P_STR IN VARCHAR2, P_DELIM IN VARCHAR2) IS
        SELECT TOKEN
          FROM TABLE(FN_STRING_SPLIT(P_STR, P_DELIM));


    CURSOR CUR_USER IS
        SELECT USER_ID
          FROM SCM_ADM_RECIPIENT_ASSIGN
         WHERE 1 = 1
           AND CATEGORY_ID = P_CATEGORY_ID;
BEGIN
    DBMS_LOB.CREATETEMPORARY(V_TABLE_CONTENTS, TRUE);

    SELECT COUNT(USER_ID)
      INTO V_USER_CNT
      FROM SCM_ADM_RECIPIENT_ASSIGN
     WHERE 1 = 1
       AND CATEGORY_ID = P_CATEGORY_ID;

    BEGIN
        SELECT MAIL_TITLE
             , REPLACE(MESSAGE_CONTENT, CHR(10), '<br><br>')
          INTO V_MAIL_TITLE
             , V_BODY_TITLE
          FROM SCM_ADM_RECIPIENT_MESSAGE
         WHERE 1 = 1
           AND CATEGORY_ID = P_CATEGORY_ID;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            V_MAIL_TITLE := NULL;
            V_BODY_TITLE := NULL;
    END;

    BEGIN
        SELECT SQL_LONG_TEXT
          INTO V_SQL
          FROM SCM_ADM_RECIPIENT_LIST
         WHERE 1 = 1
           AND CATEGORY_ID = P_CATEGORY_ID;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            V_SQL := NULL;
    END;

    BEGIN
        /* 시작 LOG */
        V_LOG_TYPE    := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := TO_CHAR(P_CATEGORY_ID);
        D_EVENT_DATE  := SYSDATE;

        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        DBMS_OUTPUT.PUT_LINE('GET TABLE DATAS - BEGIN ---------------------------------------------------------------------------------');


        IF V_SQL IS NOT NULL AND DBMS_LOB.GETLENGTH(V_SQL) > 0 THEN                       -- 2026.09.16 AJS
            N_SQL_LEN   := DBMS_LOB.GETLENGTH(V_SQL);                                     -- 2026.09.16 AJS
            N_SQL_START := 1;                                                             -- 2026.09.16 AJS

            LOOP                                                                          -- 2026.09.16 AJS
                N_SQL_POS := DBMS_LOB.INSTR(V_SQL, V_SQL_SEPERATOR, N_SQL_START, 1);      -- 2026.09.16 AJS

                V_CURR_SQL := NULL;                                                       -- 2026.09.16 AJS
                DBMS_LOB.CREATETEMPORARY(V_CURR_SQL, TRUE);                               -- 2026.09.16 AJS

                IF N_SQL_POS = 0 THEN                                                     -- 2026.09.16 AJS
                    IF N_SQL_LEN - N_SQL_START + 1 > 0 THEN                               -- 2026.09.16 AJS
                        DBMS_LOB.COPY(V_CURR_SQL, V_SQL, N_SQL_LEN - N_SQL_START + 1, 1, N_SQL_START);  -- 2026.09.16 AJS
                    END IF;                                                               -- 2026.09.16 AJS
                ELSE                                                                      -- 2026.09.16 AJS
                    IF N_SQL_POS - N_SQL_START > 0 THEN                                   -- 2026.09.16 AJS
                        DBMS_LOB.COPY(V_CURR_SQL, V_SQL, N_SQL_POS - N_SQL_START, 1, N_SQL_START);  -- 2026.09.16 AJS
                    END IF;                                                               -- 2026.09.16 AJS
                END IF;                                                                   -- 2026.09.16 AJS

                V_CURR_SQL := NVL(TRIM(V_CURR_SQL), ' ');                                 -- 2026.09.16 AJS

                V_CURR_TABLE_CONTENTS := NULL;                                            -- 2026.09.16 AJS

                UP_FX_GETHTMLBYSQL(V_CURR_SQL, 'COLUMN', 'SEGMENT', V_CURR_TABLE_CONTENTS);  -- 2026.09.16 AJS

                IF V_CURR_TABLE_CONTENTS IS NOT NULL THEN                                 -- 2026.09.16 AJS
                    DBMS_LOB.APPEND(V_TABLE_CONTENTS, V_CURR_TABLE_CONTENTS);             -- 2026.09.16 AJS
                END IF;                                                                   -- 2026.09.16 AJS

                EXIT WHEN N_SQL_POS = 0;                                                  -- 2026.09.16 AJS

                N_SQL_START := N_SQL_POS + LENGTH(V_SQL_SEPERATOR);                       -- 2026.09.16 AJS
            END LOOP;                                                                     -- 2026.09.16 AJS
        END IF;                                                                           -- 2026.09.16 AJS

        DBMS_OUTPUT.PUT_LINE('GET TABLE DATAS - END ---------------------------------------------------------------------------------');

        /* 대상 데이터가 있을때만 메일 발송 */
        IF DBMS_LOB.GETLENGTH(V_TABLE_CONTENTS) > 0 THEN

            V_MAIL_TEXT :=
                ' <html>
                <head>
                <title>Untitled Document</title>
                <style>
                    * {margin:0;padding:0;}
                    body {font-family:Malgun Gothic, Arial, Helvetica, sans-serif;font-size:11px;line-height:1.8;color:#333333;}
                    table {border-collapse:collapse;width:100%;}
                    table th {background:#f5f5f5;border-bottom:1px solid #e1e1e1;}
                    table td {background:#fff;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1;border-bottom:1px solid #e1e1e1;}
                    table tbody th {border-left:1px solid #e1e1e1;text-align:right;padding:6px 8px;font-size:11px}
                    table tbody td {text-align:left;padding:6px 8px;font-size:11px}
                    table thead th {text-align:center;padding:3px;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1; border-bottom:1px solid #d1d1d1;font-size:11px}
                    .hori-table table thead td {text-align:center;padding:3px;}
                    .hori-table table tbody td {text-align:center;padding:3px;}
                    .vertical-table, .hori-table {margin-bottom:20px;}
                </style>
                </head>
                <body>' || '</br>' || '<b>' || REPLACE(NVL(V_BODY_TITLE, ' '), CHR(10), '<br>') || '</b>' ||
                '<div id="divBody" style="width: 100%; overflow-x: auto; overflow-y: auto; font-size: 9pt; line-break: auto;">' ||
                '<table border=1 style="border-collapse: collapse; width:100%; white-space: nowrap; ">' ||
                V_TABLE_CONTENTS || '
                </div>
                </body>
                </html>';

            /* 메일 발송 루프 */
            V_USER_ID            := NULL;
            V_MAIL_RECEIVER_LIST := NULL;
            V_SEND_CNT           := 1;

            FOR U IN CUR_USER LOOP
                V_USER_ID := U.USER_ID;

                IF NVL(V_MAIL_RECEIVER_LIST, ' ') = ' ' THEN
                    V_MAIL_RECEIVER_LIST := V_USER_ID || '@lgensol.com';
                ELSE
                    V_MAIL_RECEIVER_LIST := V_MAIL_RECEIVER_LIST || ';' || V_USER_ID || '@lgensol.com';
                END IF;

                /* 테스트모드에는 개발자 메일로만 발송!!!!!!! */
                IF V_TEST_MODE = 'T' THEN
                    V_MAIL_RECEIVER_LIST := V_DEV_EMAIL;
                    V_USER_CNT           := 1;
                END IF;

                IF V_USER_CNT = V_SEND_CNT THEN
                    IF NVL(DBMS_LOB.SUBSTR(V_CURR_SQL, 1, 1), ' ') <> ' ' THEN

                        PKG_DMF0003.P_SCM_ADM_MAIL_SEND(V_MAIL_RECEIVER_LIST
                                        , V_MAIL_TITLE
                                        , DBMS_LOB.SUBSTR(V_MAIL_TEXT, 32767, 1)
                                        , 'Y');

                        V_BODY_TITLE := NULL;
                        DBMS_LOB.TRIM(V_TABLE_CONTENTS, 0);

                        SCM_ADM_SAVE_MAIL_SEND_BATCH_LOG('MAIL', P_CATEGORY_ID, 'SCM_ADM_MAIL_SEND_DATA', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, V_MAIL_RECEIVER_LIST);
                    ELSE

                        PKG_DMF0003.P_SCM_ADM_MAIL_SEND(V_MAIL_RECEIVER_LIST
                                        , V_MAIL_TITLE
                                        , DBMS_LOB.SUBSTR(V_BODY_TITLE, 32767, 1)
                                        , 'N');

                        /* MAIL 발송 LOG 저장 */
                        SCM_ADM_SAVE_MAIL_SEND_BATCH_LOG('MAIL', P_CATEGORY_ID, 'SCM_ADM_MAIL_SEND_DATA', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, V_MAIL_RECEIVER_LIST);
                    END IF;
                ELSE /* 5명 이상일 경우 */
                    IF MOD(V_SEND_CNT, 5) = 0 THEN
                        IF NVL(DBMS_LOB.SUBSTR(V_CURR_SQL, 1, 1), ' ') <> ' ' THEN
                            IF DBMS_LOB.GETLENGTH(V_TABLE_CONTENTS) > 0 THEN

                                PKG_DMF0003.P_SCM_ADM_MAIL_SEND(V_MAIL_RECEIVER_LIST
                                                , V_MAIL_TITLE
                                                , DBMS_LOB.SUBSTR(V_MAIL_TEXT, 32767, 1)
                                                , 'Y');

                                V_BODY_TITLE := NULL;
                                DBMS_LOB.TRIM(V_TABLE_CONTENTS, 0);

                                /* MAIL 발송 LOG 저장 */
                                SCM_ADM_SAVE_MAIL_SEND_BATCH_LOG('MAIL', P_CATEGORY_ID, 'SCM_ADM_MAIL_SEND_DATA', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, V_MAIL_RECEIVER_LIST);
                            END IF;
                        ELSE

                            PKG_DMF0003.P_SCM_ADM_MAIL_SEND(V_MAIL_RECEIVER_LIST
                                            , V_MAIL_TITLE
                                            , DBMS_LOB.SUBSTR(V_BODY_TITLE, 32767, 1)
                                            , 'N');

                            /* MAIL 발송 LOG 저장 */
                            SCM_ADM_SAVE_MAIL_SEND_BATCH_LOG('MAIL', P_CATEGORY_ID, 'SCM_ADM_MAIL_SEND_DATA', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, V_MAIL_RECEIVER_LIST);
                        END IF;

                        V_MAIL_RECEIVER_LIST := NULL;
                    END IF;
                END IF;

                V_SEND_CNT := V_SEND_CNT + 1;

                IF V_TEST_MODE = 'T' THEN
                    EXIT;
                END IF;
            END LOOP;
        END IF;

        V_LOG_TYPE    := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := TO_CHAR(P_CATEGORY_ID);
        D_EVENT_DATE  := SYSDATE;

        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    EXCEPTION
        WHEN OTHERS THEN

            V_ERR_PROC := SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 600);
            IF V_ERR_PROC IS NULL THEN
                V_ERR_PROC := 'SCM_ADM_MAIL_SEND_DATA';
            END IF;
            V_ERR_MSG  := SUBSTR(SQLERRM, 1, 4000);
            V_ERR_CODE := SQLCODE;


            INSERT
              INTO SCM_SYS_LOG_BATCH
                 ( PROGRAM_NAME
                 , LOG_TYPE
                 , LOG_COUNT
                 , LOG_MESSAGE
                 , DESCRIPTION
                 , EVENT_DATE
                 , CREATION_DATE
                 , CREATED_BY
                 , LAST_UPDATE_DATE
                 , LAST_UPDATED_BY )
            VALUES ( V_ERR_PROC
                 , 'ERROR'
                 , NULL
                 , V_ERR_MSG
                 , 'p_category_id:' || TO_CHAR(P_CATEGORY_ID)
                 , SYSDATE
                 , SYSDATE
                 , V_ERR_PROC
                 , SYSDATE
                 , V_ERR_PROC );
            COMMIT;

            V_ERROR_MESSAGE := SUBSTR(V_ERR_MSG, 1, 1000);

            /* MAIL 발송 LOG 저장 */
            SCM_ADM_SAVE_MAIL_SEND_BATCH_LOG('ERROR', P_CATEGORY_ID, 'MAIN ERROR', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, V_ERROR_MESSAGE, NULL);
            COMMIT;


    END;
END;

PROCEDURE SCM_ADM_NOTICE_DELETE_CONFIRM
/*
 * Program ID   : SCM_ADM_NOTICE_DELETE_CONFIRM
 * Description  : 로그는 15일치만 관리함
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2018/02/23   ygkim   Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 * 2026.03.24   김준규   [PJ20264226] NextSCM Pilot 설계 및 개발
 * 2026.07.06   ZIONEX   [PJ202650304] NextSCM Migration
 *
 */
AS

    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME VARCHAR2(150 CHAR) := $$PLSQL_UNIT;
    V_LOG_TYPE     VARCHAR2(30 CHAR);
    N_LOG_COUNT    INTEGER := 0;
    V_LOG_MESSAGE  VARCHAR2(1000 CHAR);
    V_DESCRIPTION  VARCHAR2(500 CHAR);
    D_EVENT_DATE   DATE;
    V_IN_PARA_DATA VARCHAR2(4000 CHAR);

BEGIN

    IF UTL_CALL_STACK.SUBPROGRAM(1).COUNT > 1 THEN
        V_PROGRAM_NAME := $$PLSQL_UNIT || '.' || UTL_CALL_STACK.SUBPROGRAM(1) (2);
    END IF;

    V_IN_PARA_DATA := NULL;

    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := NULL;
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    BEGIN
        DELETE
          FROM SCM_ADM_NOTICE_CONFIRM
         WHERE CREATION_DATE < SYSDATE - 15;
    END;


    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := NULL;
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    COMMIT;

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME
                            ,'ERROR'
                            ,0
                            ,SQLERRM
                            ,NULL
                            ,SYSDATE
                            ,P_IN_PARA_DATA  => V_IN_PARA_DATA
                            ,P_SQL_ERR_CODE  => SQLCODE
                            ,P_SQL_ERR_MSG   => SQLERRM
                            ,P_SQL_BACKTRACE => DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);

END;

PROCEDURE           "SCM_ADM_SAVE_MAIL_SEND_BATCH_LOG" 
(
      V_USE_TYPE_CODE   IN  VARCHAR2
    , P_CATEGORY_ID     IN  INTEGER
    , P_SEGMENT1        IN  VARCHAR2
    , P_SEGMENT2        IN  VARCHAR2  DEFAULT NULL
    , P_SEGMENT3        IN  VARCHAR2  DEFAULT NULL
    , P_SEGMENT4        IN  VARCHAR2  DEFAULT NULL
    , P_SEGMENT5        IN  VARCHAR2  DEFAULT NULL
    , P_SEGMENT6        IN  VARCHAR2  DEFAULT NULL
    , P_SEGMENT7        IN  VARCHAR2  DEFAULT NULL
    , P_SEGMENT8        IN  VARCHAR2  DEFAULT NULL
    , P_SEGMENT9        IN  VARCHAR2  DEFAULT NULL
    , P_SEGMENT10       IN  VARCHAR2  DEFAULT NULL
    , P_SEND_PGM        IN  VARCHAR2  DEFAULT NULL
    , P_RECEIVER_ID     IN  VARCHAR2  DEFAULT NULL
)
/*
 * Program ID   : SCM_ADM_SAVE_MAIL_SEND_BATCH_LOG
 * Description  : MAIL 발송 BATCH LOG 저장
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2018/03/07   ygkim   Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 * 2026.08.03   ZIONEX   [PJ202650304]  NextSCM Migration
 *
 */
AS
/* ------------------------------------------------------------------------------------------------
 * 변환(MSSQL -> Oracle) 재변환 메모 : MAIL 발송 BATCH LOG 저장
 *
 *   - 결과셋 반환 SELECT 2건은 Oracle 무대응(시그니처 고정으로 OUT 커서 추가 금지) -> 원본 보존만.
 *
 *      (Pilot 배포본은 END 로그가 아예 없어 FN_GET_CHECK_LOG_RUN_TIME 의 START-END 매칭 소요시간이
 * ------------------------------------------------------------------------------------------------ */

    PRAGMA AUTONOMOUS_TRANSACTION;

    V_PROGRAM_NAME       VARCHAR2(150 CHAR) := $$PLSQL_UNIT;
    V_LOG_TYPE           VARCHAR2(30 CHAR);          /* START/END/ERROR/... */
    N_LOG_COUNT          INTEGER := 0;
    V_LOG_MESSAGE        VARCHAR2(1000 CHAR);
    V_DESCRIPTION        VARCHAR2(500 CHAR);
    D_EVENT_DATE         DATE;
    V_DISPATCH_SERIAL_NO INTEGER;
    V_IN_PARA_DATA       CLOB;
    V_ERR_OCCURRED       BOOLEAN := FALSE;
    V_RAISE_MESSAGE      VARCHAR2(2000 CHAR);
BEGIN


    /* LOG 용 변수 설정 */

    IF UTL_CALL_STACK.SUBPROGRAM(1).COUNT > 1 THEN
        V_PROGRAM_NAME := $$PLSQL_UNIT||'.'||UTL_CALL_STACK.SUBPROGRAM(1)(2);
    END IF;

    V_IN_PARA_DATA := JSON_OBJECT('v_use_type_code' VALUE V_USE_TYPE_CODE
                                , 'p_category_id' VALUE P_CATEGORY_ID
                                , 'p_segment1' VALUE P_SEGMENT1
                                , 'p_segment2' VALUE P_SEGMENT2
                                , 'p_segment3' VALUE P_SEGMENT3
                                , 'p_segment4' VALUE P_SEGMENT4
                                , 'p_segment5' VALUE P_SEGMENT5
                                , 'p_segment6' VALUE P_SEGMENT6
                                , 'p_segment7' VALUE P_SEGMENT7
                                , 'p_segment8' VALUE P_SEGMENT8
