 * 변환(MSSQL->Oracle) 2026-07-01 SCMADM : 구 변환본 기계번역 파손(EXEC 괄호누락·MERGE AS·stray ';') 전면 재작성
 *   - 커서→FOR LOOP, GETDATE->SYSDATE, DATEADD(MONTH,-12,)->ADD_MONTHS(,-12), EXEC UP_FX_DeleteUserInfo->호출
 *   - MSSQL 문장별 autocommit → 사용자별 COMMIT(처리분 확정), 오류 시 현재사용자 ROLLBACK+로그(원본 CATCH 동등, 재발생 없음)
 *   - CATCH의 결과셋 SELECT('F'/에러)는 배치(스케줄러)라 소비자 없음 → 로그로 대체(H-9)
 *   - 의존 co-deploy: UP_FX_DeleteUserInfo
 * 2023.02.24   FP Pjt.        [E20230216-000381]로직정리
 * 2024.07.25   FP Prj.        [E20240722-000131]장기미접속 권환회수 기간 연장 요청의 건 : 3개월 -> 1년
 * 2026.07.06	ZIONEX		[PJ202650304] NextSCM Migration
 */
AS
    V_PROGRAM_NAME VARCHAR2(150 CHAR) := 'SCM_ADM_USER_LONGTERM_UNCONNECTED_CHECK';
    V_LOG_TYPE     VARCHAR2(30 CHAR);
    N_LOG_COUNT    INTEGER := 0;
    V_LOG_MESSAGE  VARCHAR2(1000 CHAR);
    V_DESCRIPTION  VARCHAR2(500 CHAR);
    V_ERRMSG       VARCHAR2(1000 CHAR);
    D_EVENT_DATE   DATE;
BEGIN
    /* 시작 LOG */
    V_LOG_TYPE := 'START'; V_LOG_MESSAGE := '########## Start of procedure ##########'; V_DESCRIPTION := NULL; D_EVENT_DATE := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    /* 2026.09.30 AJS 수정 (START) */
