        /* 2026.09.30 AJS 수정 (END) */

        /* 사용자별 그룹 권한 이력 저장 */
        -- [2026-10-06 / POJ] TB_FX_USERGROUPAUTHEXTENTION_H → SCM_ADM_USER_GR_UNIT_AUTH_MPG_M_H · HISTORY_SEQ·EDIT_YN·USE_YN 추가
        INSERT INTO SCM_ADM_USER_GR_UNIT_AUTH_MPG_M_H
               ( HISTORY_SEQ, USER_GR_ID, USER_ID, UNIT_TP_CD, UNIT_ID, UPPR_UNIT_ID, EDIT_YN, USE_YN
               , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, HISTORY_CREATION_DATE )
        /* 2026.09.30 AJS 수정 (START) */
--        SELECT   GROUPID, USERID, AUTHTYPE, CODE, PRNTCODE, 'SYSTEM', SYSDATE, 'SYSTEM', SYSDATE
--          FROM   TB_FX_USERGROUPAUTHEXTENTION
--         WHERE   USERID = REC.USERID;
        SELECT   SEQ1_SCM_ADM_USER_GR_UNIT_AUTH_MPG_M_H.NEXTVAL
               , USER_GR_ID, USER_ID, UNIT_TP_CD, UNIT_ID, UPPR_UNIT_ID, EDIT_YN, USE_YN
               , 'SYSTEM', SYSDATE, 'SYSTEM', SYSDATE, SYSDATE
          FROM   SCM_ADM_USER_GR_UNIT_AUTH_MPG_M
         WHERE   USER_ID = REC.USERID;
        /* 2026.09.30 AJS 수정 (END) */

        /* USER 및 GROUP 권한 모두 삭제 */
        UP_FX_DELETEUSERINFO(REC.USERID);


        DELETE FROM SCM_MST_AUTH_REQUEST WHERE USER_ID = REC.USERID;

        /* 장기 미접속 테이블 저장(재요청 시 VALID_YN 재조정) */
        -- [2026-10-06 / POJ] 확인필요 — TB_FX_USERLOCKLIST 는 TO-BE 짝 미확정(매핑표 04_확인필요 1번)이라 그대로 둔다
        MERGE INTO TB_FX_USERLOCKLIST X
        USING ( SELECT REC.USERID AS USERID FROM DUAL ) Y
        ON ( X.USERID = Y.USERID )
        WHEN MATCHED THEN
            UPDATE SET X.VALID_YN = 'Y', X.LAST_UPDATED_BY = 'SYSTEM', X.LAST_UPDATE_DATE = SYSDATE
        WHEN NOT MATCHED THEN
            INSERT ( USERID, VALID_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE )
            VALUES ( REC.USERID, 'Y', 'SYSTEM', SYSDATE, 'SYSTEM', SYSDATE );

        /* FP 권한 삭제 */
        UPDATE TH_UIS_USER_INSTANCE_RELATE_SN
           SET USE_AT_FLAG = 'N', UPDATE_ID = 'scm_batch', UPDATE_DTTM = SYSDATE
         WHERE USER_ID = REC.USERID AND USE_AT_FLAG = 'Y';

        /* 기존 FP 권한요청 REJECT 처리 */
        UPDATE FP_AUTH_REQUEST_INFO_M_SN
           SET APPROVAL_FLAG = 'N', DESCRIPTION = 'USER_LONGTERM_UNCONNECTED', APPROVAL_ID = 'scm_batch', APPROVAL_TIME = SYSDATE
         WHERE USER_ID = REC.USERID AND APPROVAL_FLAG = 'Y';

        COMMIT;
    END LOOP;


    V_LOG_TYPE := 'END'; V_LOG_MESSAGE := '########## END of procedure ##########'; V_DESCRIPTION := NULL; D_EVENT_DATE := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        V_ERRMSG      := SUBSTR(SQLERRM, 1, 1000);
        V_DESCRIPTION := V_PROGRAM_NAME || ' ERROR_LINE : ' || SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 300);
        INSERT INTO SCM_SYS_LOG_BATCH
               ( PROGRAM_NAME, LOG_TYPE, LOG_COUNT, LOG_MESSAGE, DESCRIPTION, EVENT_DATE
               , CREATION_DATE, CREATED_BY, LAST_UPDATE_DATE, LAST_UPDATED_BY )
        VALUES ( V_PROGRAM_NAME, 'ERROR', NULL, V_ERRMSG, V_DESCRIPTION, SYSDATE
               , SYSDATE, 'SYSTEM', SYSDATE, 'SYSTEM' );
        COMMIT;
END SCM_ADM_USER_LONGTERM_UNCONNECTED_CHECK;

PROCEDURE "SCM_ADM_USER_LONGTERM_UNCONNECTED_MAIL" 
/*
 * Program ID   : SCM_ADM_USER_LONGTERM_UNCONNECTED_MAIL
 * Description  : 장기 미접속 메일 전송
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2020.02.11   khj79          [C20200117-000310]권한 고정, 장기 미접속자 메일링 기능 - 장기 미접속(60일,83일) 안내 메일 전송
 * 2023.02.24   FP Prj.        [E20230216-000381]로직정리
 * 2024.07.25   FP Prj.        [E20240722-000131]장기미접속 권환회수 기간 연장 요청의 건 : 3개월 -> 1년
 * 2026.07.06   ZIONEX         [PJ202650304] NextSCM Migration
 */
AS
    V_USER_ID            VARCHAR2(30 CHAR);    /* 사용자ID */
    V_UNCONNECTED_TERM   VARCHAR2(10 CHAR);    /* 미접속기간 */
    V_MAIL_RECEIVER      VARCHAR2(30 CHAR);    /* 메일 수신자 */
    V_MAIL_SUBJECT       VARCHAR2(200 CHAR);   /* 메일 제목 */
    V_MAIL_BODY          VARCHAR2(4000 CHAR);  /* 메일 내용 */
    V_MAIL_CONTENT1      VARCHAR2(100 CHAR);   /* 메일 본문 내용1 */
    V_MAIL_CONTENT2      VARCHAR2(100 CHAR);   /* 메일 본문 내용2 */
    V_MAIL_CONTENT3      VARCHAR2(100 CHAR);   /* 메일 본문 내용3 */
    V_MAIL_CONTENT4      VARCHAR2(100 CHAR);   /* 메일 본문 내용4 */
    V_MAIL_SEND_CNT      NUMBER := 1;          /* 메일 전송 카운트 */

    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME       VARCHAR2(150 CHAR) := 'SCM_ADM_USER_LONGTERM_UNCONNECTED_MAIL';
    V_LOG_TYPE           VARCHAR2(30 CHAR);    /* START/END/ERROR/... */
    N_LOG_COUNT          INTEGER := 0;
    V_LOG_MESSAGE        VARCHAR2(1000 CHAR);
    V_DESCRIPTION        VARCHAR2(2000 CHAR);
    D_EVENT_DATE         DATE;
BEGIN
    /* 메일 내용 설정 */
    /* [2026-10-07] 비운영에서는 제목에 'DEV Oracle 개발서버 ' 를 붙인다 (사용자 결정).
     * 원본 MSSQL 은 SELECT @v_profile_name = IIF(db_name()='LGCE_SCMPROD','GSCM_MAIL_PROD','GSCM_MAIL_TEST')
     * 로 **운영/비운영을 메일 프로필로 구분**했는데, Oracle PKG_SEND_MAIL 은 프로필 개념이 없고
     * C_SMTP_HOST 단일 호스트라 그 구분이 사라졌다. 제목 표시로 그 목적을 대체한다.
     * 발송 동작은 원본 그대로(비운영에도 발송) — 행 10·17 과 같은 판정식이다. */
    IF SYS_CONTEXT('USERENV', 'DB_NAME') NOT LIKE 'OCGSCMP%' THEN
        V_MAIL_SUBJECT := 'DEV Oracle 개발서버 '||'GSCM 시스템 장기 미접속으로 인한 권한 회수 안내 ';
    ELSE
        V_MAIL_SUBJECT := 'GSCM 시스템 장기 미접속으로 인한 권한 회수 안내 ';
    END IF;
    V_MAIL_CONTENT1 := '업무혁신';
    V_MAIL_CONTENT2 := '귀하의 계정';
    /* [E20240722-000131]장기미접속 권환회수 기간 연장 요청의 건 : 365일 기준으로 5일 전, 당일 미접속시 */
    V_MAIL_CONTENT3 := '일 미접속으로 권한이 회수됩니다.';
    V_MAIL_CONTENT4 := 'GSCM 시스템에 접속하여 로그인 해주시기 바랍니다.';

    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := NULL;
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    /* 장기 미접속자 조회 (Guest, PermanentYN='Y' 인 사용자 제외)                     */
    /* [E20240722-000131] 장기미접속 권한회수 기간 : 365일 기준 5일 전(360)/당일(365) */
    /* MSSQL DATEDIFF(dd, LastLoginDateTime, GETDATE()) → TRUNC 일수차                */
    /* 2026.09.30 AJS 수정 (START) */
--    FOR REC IN ( SELECT USERID
--                      , TO_CHAR(TRUNC(SYSDATE) - TRUNC(LASTLOGINDATETIME))  AS UNCONNECTEDTERM
--                   FROM TB_FX_USER
--                  WHERE USEYN      = 'Y'
--                    AND USERID     != 'Guest'
--                    AND PERMANENTYN != 'Y'
--                    AND (TRUNC(SYSDATE) - TRUNC(LASTLOGINDATETIME)) IN (360, 365) )
    FOR REC IN ( SELECT USER_ID
                      , TO_CHAR(TRUNC(SYSDATE) - TRUNC(LOGN_DTM))           AS UNCONNECTEDTERM
                   FROM SCM_ADM_USER_M
                  WHERE USE_YN     = 'Y'
                    AND USER_ID    != 'Guest'
                    AND PERM_KEP_CNC_YN != 'Y'
                    AND (TRUNC(SYSDATE) - TRUNC(LOGN_DTM)) IN (360, 365) )
    /* 2026.09.30 AJS 수정 (END) */
    LOOP
        /* 2026.09.30 AJS 수정 (START) */
--        V_USER_ID          := REC.USERID;
        V_USER_ID          := REC.USER_ID;
        /* 2026.09.30 AJS 수정 (END) */
        V_UNCONNECTED_TERM := REC.UNCONNECTEDTERM;

        V_MAIL_RECEIVER    := V_USER_ID || '@lgensol.com';    /* 실제 사용자 */

        V_MAIL_BODY :=
            '<html><head><title>Untitled Document</title><meta charset="UTF-8">'
            || '<style>.textdecoration1 {PADDING-BOTTOM: 0cm; PADDING-TOP: 0cm; PADDING-LEFT: 0cm; PADDING-RIGHT: 0cm }'
            || '.textdecoration2 { FONT-FAMILY: LG스마트체 Regular; font-size : 12pt;}</style></head>'
            || '<body style="FONT-SIZE: 10pt; FONT-FAMILY: LG스마트체 Regular">'
            || '<div><table style="WIDTH: 495pt; BACKGROUND: #c6c6c4" cellSpacing=1 cellPadding=0 width=660 border=0><tbody>'
            || '<tr style="HEIGHT: 35.25pt"><td style="BORDER-TOP: medium none; HEIGHT: 35.25pt; BORDER-RIGHT: medium none; BACKGROUND: #f0f0f0; BORDER-BOTTOM: #c8284a 2.25pt solid; PADDING-BOTTOM: 0cm; PADDING-TOP: 9pt; PADDING-LEFT: 10.5pt; BORDER-LEFT: medium none; PADDING-RIGHT: 0cm" vAlign=top>'
            || '<p ><b><span style="FONT-SIZE: 10.5pt">' || V_MAIL_CONTENT1 || '<span lang=EN-US> Portal</span></span></b></p></td></tr>'
            || '<tr><td style="BACKGROUND: white; PADDING-BOTTOM: 0cm; PADDING-TOP: 0cm; PADDING-LEFT: 0cm; PADDING-RIGHT: 0cm"><div align=center>'
            || '<table  style="WIDTH: 436.5pt" cellSpacing=0 cellPadding=0 width=582 border=0><tbody>'
            || '<tr style="HEIGHT: 22.5pt"><td style="HEIGHT: 22.5pt; PADDING-BOTTOM: 0cm; PADDING-TOP: 0cm; PADDING-LEFT: 0cm; PADDING-RIGHT: 0cm"><p>&nbsp;</p></td></tr>'
            || '<tr><td class="textdecoration1"><p ><strong><span lang=EN-US style="FONT-FAMILY: 굴림; COLOR: #249697"></span></strong>'
            || '<strong><span style="FONT-FAMILY: 굴림; COLOR: #249697">' || V_MAIL_SUBJECT || '</span></strong></p></td></tr>'
            || '<tr><td><p>&nbsp;</p></td></tr>'
            || '<tr><td class="textdecoration1"><table  style="WIDTH: 100%" cellSpacing=0 cellPadding=0 width="100%" border=0><tbody>'
            || '<tr><td class="textdecoration1"><p class="textdecoration1">' || V_MAIL_CONTENT2 || ' (' || V_USER_ID || ')</p></td></tr>'
            || '<tr><td><p>&nbsp;</p></td></tr>'
            || '<tr><td class="textdecoration1"><p class="textdecoration1">' || V_UNCONNECTED_TERM || V_MAIL_CONTENT3 || '</p></td></tr>'
            || '<tr><td><p><span lang=EN-US></span>&nbsp;</p></td></tr>'
            || '<tr><td class="textdecoration1"><p class="textdecoration2">' || V_MAIL_CONTENT4 || '</p></td></tr>'
            || '<tr><td><p>&nbsp;</p></td></tr>'
            || '</tbody></table></td></tr></tbody></table></div></td></tr></tbody></table></body></html>';


        DBMS_OUTPUT.PUT_LINE(V_USER_ID || ', ' || V_UNCONNECTED_TERM || ',   ' || V_MAIL_RECEIVER);

        /* [2026-10-07] 발송 간 대기 삭제 (사용자 지시 2026-10-06).
         * ★이 건은 수신자마다 본문이 달라 묶음 발송 대상이 아니다 — 묶음과 무관하게 대기 로직 자체를 삭제하라는 지시다.
         * 원본 MSSQL 의 WAITFOR DELAY 는 그대로 둔다 — 원본을 고치는 게 아니라 Oracle 발송 방식에 맞춘 것이다.
         * 삭제한 블록 : IF MOD(V_MAIL_SEND_CNT, 10) = 0 THEN DBMS_SESSION.SLEEP(5); DBMS_OUTPUT.PUT_LINE(대기 안내문); END IF; */

        /* 메일 전송
               EXEC msdb.dbo.sp_send_dbmail @profile_name = @v_prorile_name, @recipients = @v_mail_receiver, @subject = @v_mail_subject, @body = @v_mail_body, @body_format = 'html'; */
        PKG_SEND_MAIL.P_SEND_MAIL(V_MAIL_RECEIVER, V_MAIL_SUBJECT, V_MAIL_BODY, 'Y');

        /* 메일 전송 카운트 증가 */
        V_MAIL_SEND_CNT := V_MAIL_SEND_CNT + 1;
    END LOOP;

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := NULL;
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

EXCEPTION
    WHEN OTHERS THEN

        V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
        V_DESCRIPTION := SUBSTR(V_PROGRAM_NAME || 'ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 2000);
        INSERT
          INTO SCM_SYS_LOG_BATCH
             ( PROGRAM_NAME
             , LOG_TYPE
             , LOG_COUNT
             , LOG_MESSAGE
             , DESCRIPTION
             , EVENT_DATE
             , CREATION_DATE
             , CREATED_BY
             , LAST_UPDATE_DATE
             , LAST_UPDATED_BY )
        VALUES ( V_PROGRAM_NAME
               , 'ERROR'
               , NULL
               , V_LOG_MESSAGE
               , V_DESCRIPTION
               , SYSDATE
               , SYSDATE
               , V_PROGRAM_NAME
               , SYSDATE
               , V_PROGRAM_NAME );
        COMMIT;


        DBMS_OUTPUT.PUT_LINE('F');
        DBMS_OUTPUT.PUT_LINE('[' || TO_CHAR(SQLCODE) || ']' || SQLERRM);
END;

FUNCTION           "SCM_ARR_SPL_CNT" 

(

    P_STRING     IN VARCHAR2   /* 분리할 문자열 */

  , P_SPLITCHAR  IN VARCHAR2   /* 구분할 문자 */

)

RETURN VARCHAR2

/*

 * FUNCTION NAME : SCM_ARR_SPL_CNT

 * DESCRIPTION   : 구분자로 분리되는 요소 개수 반환

 * PROGRAM HISTORY

 *--------------------------------------------------------------

 * 2026.07.06   ZIONEX  [PJ202650304]  NextSCM Migration

 */

AS



    V_TEMP           VARCHAR2(32767 CHAR);

    V_LENGTH         PLS_INTEGER;

    V_CURRENT_INDEX  PLS_INTEGER;

    V_NEXT_INDEX     PLS_INTEGER;

    V_MAXLOOP_CNT    PLS_INTEGER;



BEGIN



    V_LENGTH        := LENGTH(RTRIM(P_STRING));

    V_CURRENT_INDEX := 1;

    V_NEXT_INDEX    := 1;

    V_MAXLOOP_CNT   := 0;



    WHILE V_NEXT_INDEX > 0 LOOP



        V_NEXT_INDEX := INSTR(P_STRING, P_SPLITCHAR, V_CURRENT_INDEX);



        IF V_NEXT_INDEX = 0 THEN

            V_TEMP := SUBSTR(P_STRING, V_CURRENT_INDEX, (V_LENGTH - V_CURRENT_INDEX + 1));

        ELSE

            V_TEMP := SUBSTR(P_STRING, V_CURRENT_INDEX, (V_NEXT_INDEX - V_CURRENT_INDEX));

            V_CURRENT_INDEX := V_NEXT_INDEX + 1;

        END IF;



        V_MAXLOOP_CNT := V_MAXLOOP_CNT + 1;



    END LOOP;



    RETURN V_MAXLOOP_CNT;



END;

FUNCTION           "SCM_ARR_SPL_VAL" 

(

    P_STEXT  IN VARCHAR2                /* 대상 문자열 */

  , P_STR    IN VARCHAR2 DEFAULT '|'    /* 구분기호(Default '|') */

  , P_IDX    IN PLS_INTEGER             /* 배열 인덱스 */

)

RETURN VARCHAR2

/*

 * FUNCTION NAME : SCM_ARR_SPL_VAL

 * DESCRIPTION   : 구분기호로 나눈 배열의 인덱스 요소 반환

 * PROGRAM HISTORY

 *--------------------------------------------------------------

 * 2026.07.06   ZIONEX  [PJ202650304]  NextSCM Migration

 */

AS



    V_WORD        VARCHAR2(32767 CHAR);   /* 반환할 문자 */

    V_STEXT_DATA  VARCHAR2(32767 CHAR);

    V_NUM         PLS_INTEGER;

    V_STR         VARCHAR2(32767 CHAR);



BEGIN



    V_NUM        := 1;

    V_STR        := TRIM(P_STR);

    V_STEXT_DATA := TRIM(P_STEXT) || V_STR;



    WHILE P_IDX >= V_NUM LOOP



        IF INSTR(V_STEXT_DATA, V_STR) > 0 THEN

            /* 문자열의 인덱스 위치의 요소를 반환 */

            V_WORD := SUBSTR(V_STEXT_DATA, 1, INSTR(V_STEXT_DATA, V_STR) - 1);

            V_WORD := TRIM(V_WORD);



            /* 반환된 문자는 버린후 좌우공백 제거 */

            V_STEXT_DATA := TRIM(SUBSTR(V_STEXT_DATA, NVL(LENGTH(V_WORD), 0) + 2));

        ELSE

            V_WORD := NULL;

        END IF;



        V_NUM := V_NUM + 1;



    END LOOP;



    RETURN V_WORD;



END;

FUNCTION SCM_ARR_SPL_VAL_ENTITY
(
    P_STEXT  IN VARCHAR2                /* 대상 문자열 */
  , P_STR    IN VARCHAR2 DEFAULT '|'    /* 구분기호(Default '|') */
  , P_IDX    IN PLS_INTEGER             /* 배열 인덱스 */
)
RETURN VARCHAR2
/*
 * FUNCTION NAME : SCM_ARR_SPL_VAL_ENTITY
 * DESCRIPTION   : SCM_ARR_SPL_VAL + ENTITY(^!#:) 치환
 * PROGRAM HISTORY
 *--------------------------------------------------------------
 * 2026.07.06   ZIONEX  [PJ202650304]  NextSCM Migration
 */
AS

    /*
     * SCM_ARR_SPL_VAL과 차이점은 ESCAPE 문자의 처리에 관한 것이다
     * SCM_ARR_SPL_VAL은 aaa&hat;aaa^bbb&hat;bbb에 대해 INDEX 0, 1을 aaa&hat;aaa과 bbb&hat;bbb 값으로 리턴하나
     * [SCM_ARR_SPL_VAL_ENTITY]는 aaa^aaa와 bbb^bbb로 리턴한다. 그 효과로서 SCM_ARR_SPL_VAL_ENTITY은 구분기호(^)를 처리할 수 있다
     * 따라서 SCM_ARR_SPL_VAL_ENTITY 함수는 다중 루프가 진행될 경우(예를들어 a#a^a#b를 {{a}{a}},{{a},{b}}로 파싱할때 사용하면 엔티티 # (&sharp)을 치환하여
     * 2단계 파싱에 실패할 것이다. 항상 더이상 하위 파싱을 하지 않을 때(하위에서 SCM_ARR_SPL_VAL 또는 SCM_ARR_SPL_VAL_ENTITY를 사용하지 않을 때)
     * SCM_ARR_SPL_VAL_ENTITY를 사용한다
     * 다음 ENTITY(루프에 사용하는 탈출문자에 해당)를 지원하고, 현재 FP에서 동적파라미터(^)의 bucket 튜플(:) 구조체(#) 목록(!) 정보를 처리할 때 사용된다
     */

    /*
     * 지원 ENTITY 목록
     * ^ -> &hat;( &#94;은 지원하지 않는다)  동적 파라미터
     * ! -> &excl;( &#33;은 지원하지 않는다) 파라미터내 리스트
     * # -> &sharp; (&#9839;은 지원하지 않는다) 리스트 항목 내 리스트(구조체)
     * : -> &colon; (&#58;은 지원하지 않는다) 리스트 항목 내 키:값
     */

    V_WORD        VARCHAR2(32767 CHAR);   /* 반환할 문자 */
    V_STEXT_DATA  VARCHAR2(32767 CHAR);
    V_NUM         PLS_INTEGER;
    V_STR         VARCHAR2(32767 CHAR);

BEGIN

    V_NUM        := 1;
    V_STR        := TRIM(P_STR);
    V_STEXT_DATA := TRIM(P_STEXT) || V_STR;

    WHILE P_IDX >= V_NUM LOOP

        IF INSTR(V_STEXT_DATA, V_STR) > 0 THEN
            /* 문자열의 인덱스 위치의 요소를 반환 */
            V_WORD := SUBSTR(V_STEXT_DATA, 1, INSTR(V_STEXT_DATA, V_STR) - 1);
            V_WORD := TRIM(V_WORD);

            /* 반환된 문자는 버린후 좌우공백 제거 */
            V_STEXT_DATA := TRIM(SUBSTR(V_STEXT_DATA, NVL(LENGTH(V_WORD), 0) + 2));
        ELSE
            V_WORD := '';
        END IF;

        V_NUM := V_NUM + 1;

    END LOOP;

    V_WORD := SCM_ARR_SPL_VAL(V_WORD, ':', 2);

    V_WORD := REPLACE(V_WORD, '&hat;', '^');
    V_WORD := REPLACE(V_WORD, '&excl;', '!');
    V_WORD := REPLACE(V_WORD, '&sharp;', '#');
    V_WORD := REPLACE(V_WORD, '&colon;', ':');

    RETURN V_WORD;

END;

FUNCTION           "SCM_ARR_SPL_VAL_WITH_BLANK" 
(
    sText IN VARCHAR2,                       -- 대상 문자열
    str   IN VARCHAR2 DEFAULT '|',          -- 구분기호(Default '|')
    idx   IN PLS_INTEGER                    -- 배열 인덱스
)
RETURN VARCHAR2
/*
 * Program ID   : [SCM_ARR_SPL_VAL_WITH_BLANK]
 * Description  :  
 * Program History
 *===================================================================================================
 *   Date			In Charge			Description
 *===================================================================================================
 * 2026.03.11   jcnam        [PJ20264226] NextSCM Pilot 설계 및 개발 
 */
AS
    word       VARCHAR2(4000 CHAR);         -- 반환할 문자
    sTextData  VARCHAR2(32767 CHAR);
    v_str      VARCHAR2(1 CHAR);
    num        PLS_INTEGER;
    v_pos      PLS_INTEGER;
BEGIN
    num      := 1;
    v_str    := TRIM(str);
    sTextData := TRIM(sText) || v_str;

    WHILE idx >= num
    LOOP
        v_pos := INSTR(sTextData, v_str);

        IF v_pos > 0 THEN
            -- 문자열의 인덱스 위치의 요소를 반환
            word := SUBSTR(sTextData, 1, v_pos - 1);
            word := TRIM(word);
        ELSE
            word := NULL;
        END IF;

        num := num + 1;
    END LOOP;

    RETURN word;
END;

PROCEDURE "SCM_AUTH_REQ_MAIL_SEND" 
