         , SEGMENT3
         , GROUP_ID
         , DIVISION_ID
         , CREATION_DATE
         , APPROVAL_RESULT
         , MAIL_TITLE
         , BODY_CONTENTS
         , ROW_NO )
    SELECT A.USER_ID
         /* 2026.09.30 AJS 수정 (START) */
