         * 원본 MSSQL 은 이 건을 SCM_ADM_MAIL_SEND(행 17) 경유로 보내고 Oracle 행 17 에 같은 분기가 있는데,
         * Oracle 은 PKG_SEND_MAIL 을 직접 불러(계보 평탄화) 그 표시가 빠졌다.
         * 발송 동작은 원본 그대로 두고 식별만 되살린다 — 행 10·17 과 같은 판정식이다. */
        IF SYS_CONTEXT('USERENV', 'DB_NAME') NOT LIKE 'OCGSCMP%' THEN
            V_MAIL_TITLE := 'DEV Oracle 개발서버 '||V_MAIL_TITLE;
        END IF;


        PKG_SEND_MAIL.P_SEND_MAIL(V_TO_MAIL, V_MAIL_TITLE, V_BODY_CONTENTS, V_P_HTML_YN);

        /* --------------------------------------------------------------------------------------------------- */

        IF LENGTH(V_BODY_CONTENTS) > 100 THEN
            V_BODY_CONTENTS := SUBSTR(V_BODY_CONTENTS, 1, 100);
        END IF;

        /* MAIL 발송 LOG 저장(원본 주석처리 상태 보존) */
        /* SCM_ADM_SAVE_MAIL_SEND_BATCH_LOG('MAIL', V_CATEGORY_ID, V_MAIL_TITLE, V_BODY_CONTENTS */
        /*      , '', '', '', '', '', '', '', '', '' [p_send_pgm], V_TO_MAIL); */


        V_LOG_TYPE    := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    EXCEPTION
        WHEN OTHERS THEN

            V_ERR_MSG := SUBSTR(SQLERRM, 1, 1000);
            INSERT
              INTO SCM_SYS_LOG_BATCH
                 ( PROGRAM_NAME
                 , LOG_TYPE
                 , LOG_COUNT
                 , LOG_MESSAGE
                 , DESCRIPTION
                 , EVENT_DATE
                 , CREATION_DATE
                 , CREATED_BY
                 , LAST_UPDATE_DATE
                 , LAST_UPDATED_BY )
            VALUES ( V_PROGRAM_NAME
                 , 'ERROR'
                 , NULL
                 , V_ERR_MSG
                 , NULL
                 , SYSDATE
                 , SYSDATE
                 , V_PROGRAM_NAME
                 , SYSDATE
                 , V_PROGRAM_NAME );
            COMMIT;

            /* error코드, error 메시지 반환(원본 SELECT 결과셋 -> 배치 로그 캡처용 DBMS_OUTPUT, 소비자 없음) */
            DBMS_OUTPUT.PUT_LINE('F');
            DBMS_OUTPUT.PUT_LINE('[' || TO_CHAR(SQLCODE) || ']' || V_ERR_MSG);
    END;


    DELETE
      FROM GT_SARMS;
END;

FUNCTION           "SCM_SITE_TIME" 
(
    P_SITE_ID  IN VARCHAR2
)
RETURN DATE
/*
 * FUNCTION NAME : SCM_SITE_TIME
 * DESCRIPTION   : 사이트별 현재시각(UTC+오프셋, 서머타임 반영) 반환
 * PROGRAM HISTORY
 *--------------------------------------------------------------
 * 2026.07.06   ZIONEX  [PJ202650304]  NextSCM Migration
 */
AS

    V_SITE_TIME  DATE;
    V_SITE_ID    VARCHAR2(4000 CHAR) := P_SITE_ID;
    V_UTC        DATE;
    V_YEAR       VARCHAR2(4 CHAR);
    V_MAR1       DATE;
    V_NOV1       DATE;
    V_FROMDAY    DATE;
    V_TODAY      DATE;
    V_STANDARD   DATE;

BEGIN

    SELECT NVL(MAX(SITE_ID), 'A001')
      INTO V_SITE_ID
      FROM SCM_MST_SITE_SN
     WHERE SITE_ID = V_SITE_ID;

    V_UTC      := CAST(SYS_EXTRACT_UTC(SYSTIMESTAMP) AS DATE);
    V_STANDARD := V_UTC;
    V_YEAR     := SUBSTR(TO_CHAR(V_UTC, 'YYYYMMDD'), 1, 4);
    V_MAR1     := TO_DATE(V_YEAR || '-03-01', 'YYYY-MM-DD');
    V_NOV1     := TO_DATE(V_YEAR || '-11-01', 'YYYY-MM-DD');


    V_FROMDAY := ( CASE MOD(TRUNC(V_MAR1) - TRUNC(V_MAR1, 'IW') + 1, 7) + 1
                        WHEN 2 THEN V_MAR1 + 13
                        WHEN 3 THEN V_MAR1 + 12
                        WHEN 4 THEN V_MAR1 + 11
                        WHEN 5 THEN V_MAR1 + 10
                        WHEN 6 THEN V_MAR1 + 9
                        WHEN 7 THEN V_MAR1 + 8
                        WHEN 1 THEN V_MAR1 + 7
                   END ) + 7/24;


    V_TODAY := ( CASE MOD(TRUNC(V_NOV1) - TRUNC(V_NOV1, 'IW') + 1, 7) + 1
                      WHEN 2 THEN V_NOV1 + 6
                      WHEN 3 THEN V_NOV1 + 5
                      WHEN 4 THEN V_NOV1 + 4
                      WHEN 5 THEN V_NOV1 + 3
                      WHEN 6 THEN V_NOV1 + 2
                      WHEN 7 THEN V_NOV1 + 1
                      WHEN 1 THEN V_NOV1
                 END ) + 7/24;

    SELECT CASE WHEN V_STANDARD >= V_FROMDAY AND V_STANDARD <= V_TODAY
                THEN V_STANDARD + NVL(NVL(SUMMER_TIME, INTERVAL), 0) / 24
                ELSE V_STANDARD + NVL(INTERVAL, 0) / 24
           END
      INTO V_SITE_TIME
      FROM SCM_MST_SITE_SN A
     WHERE A.SITE_ID = V_SITE_ID
       AND ROWNUM <= 1;

    RETURN V_SITE_TIME;

END;

PROCEDURE SCM_SSP_ADJUST_MAIL_SEND_BATCH
/*
 * Program ID   : SCM_SSP_MAIL_SEND_BATCH
 * Description  : SSP MAIL 발송 (Adjust 메뉴)
 * Program History
 *===================================================================================================
 *   Date       In Charge		Description
 *===================================================================================================a
 * 2018/11/16	hwyoon			Initial Release [PJ20182279] 전지본부 출하계획 시스템 구축 프로젝트
 * 2019/06/11	mcTheJ			[CSR ID:3994058] [요청]생산관리 출하변경 시 사유 code화 관리
 * 2026.08.02	ZIONEX			[PJ202650304] NextSCM Migration
  */
AS
/*
 *     1.기능변환에서 상관 UPDATE + EXISTS 로 확정했고 3.에서 재결정하지 않는다(FM-025).
 *   - UPDATE 별칭 T1/T2 -> A/B 개명(4.70 FM-016), WHERE 나열순서 서브쿼리 -> 상수(4.73 FM-020).
 *   - 메일 발송 위임 호출 PR_SSP_ADJUST_MAIL_SEND, 로깅 PR_SCM_SYS_LOG_BATCH 는 1.ORA 그대로 유지
 */


    V_GRP_CHANGE_REQ  VARCHAR2(4000 CHAR);
    V_I               NUMBER(10);
    V_MAXNO           NUMBER(10);            /* 원본 @maxNo INT */

    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME    VARCHAR2(150 CHAR) := 'SCM_SSP_ADJUST_MAIL_SEND_BATCH';
    V_LOG_TYPE        VARCHAR2(30 CHAR);     /* START/END/ERROR/... */
    N_LOG_COUNT       NUMBER(10) := 0;
    V_LOG_MESSAGE     VARCHAR2(1000 CHAR);
    V_DESCRIPTION     VARCHAR2(500 CHAR);
    D_EVENT_DATE      DATE;


    V_SQLERRM         VARCHAR2(1000 CHAR);

BEGIN


    /* 원본 IF OBJECT_ID('tempdb..#TblSSPAdjustMailSendBatch') IS NOT NULL DROP TABLE #TblSSPAdjustMailSendBatch */
    DELETE
      FROM GT_SSPADJM_SENDBATCH;

    BEGIN

        /* 시작 LOG */
        V_LOG_TYPE := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        /* 원본 SELECT ... INTO #TblSSPAdjustMailSendBatch -> GTT INSERT ... SELECT */
        INSERT
          INTO GT_SSPADJM_SENDBATCH
             ( GRP_CHANGE_REQ
             , ROW_NUM )
        SELECT GRP_CHANGE_REQ
             , ROW_NUMBER() OVER (ORDER BY GRP_CHANGE_REQ) AS ROW_NUM
          FROM SSP_MST_SEND_MAIL_REQ
         WHERE TRANSFER_FLAG = 'N'
         GROUP BY GRP_CHANGE_REQ;

        V_I := 1;
        /* SET @maxNo = @@ROWCOUNT; */

        /* 원본 UPDATE ~ SET ~ FROM SSP_MST_SEND_MAIL_REQ T1 JOIN #Tbl T2 ON ... (MSSQL 전용 구문)
           -> 상관 UPDATE + EXISTS. SET 값이 상수 'Y' 라 다중매치 비결정성이 없어 MERGE 불요(ORA-30926 회피, CV-024). */
        UPDATE
               SSP_MST_SEND_MAIL_REQ A
           SET A.TRANSFER_FLAG = 'Y'
         WHERE EXISTS (SELECT 1
                         FROM GT_SSPADJM_SENDBATCH B
                        WHERE B.GRP_CHANGE_REQ = A.GRP_CHANGE_REQ)
           AND A.TRANSFER_FLAG = 'N';


        /* PRINT '1. BEFORE UPDATE-' */

        /* PRINT '2. AFTER UPDATE-' */

        /* SET @i = 1; */
        /* 원본 SET @maxNo = (SELECT MAX(ROWNUM) ...) : PL/SQL 대입 우변 SELECT 서브쿼리 불가 -> SELECT INTO */
        SELECT MAX(ROW_NUM)
          INTO V_MAXNO
          FROM GT_SSPADJM_SENDBATCH;

        /* -- CURSOR 사용 X : CURSOR는 공유되기 때문에 여러사람이 동시 메일 전송 시 중복 선언 불가. */

        WHILE V_I <= V_MAXNO LOOP


                SELECT GRP_CHANGE_REQ
                  INTO V_GRP_CHANGE_REQ
                  FROM GT_SSPADJM_SENDBATCH
                 WHERE ROW_NUM = V_I;

                /* PRINT '3. SEND MAIL-' */
                /* EXEC PR_SSP_ADJUST_MAIL_SEND @v_change_req_no; */


                PR_SSP_ADJUST_MAIL_SEND(V_GRP_CHANGE_REQ);

                V_I := V_I + 1;
        END LOOP;

		/*
		DECLARE CUR_SEND_REQ CURSOR FOR
		SELECT CHANGE_REQ_NO
		FROM #TblSSPAdjustMailSendBatch

		OPEN CUR_SEND_REQ;
		FETCH NEXT FROM CUR_SEND_REQ INTO @v_change_req_no

		WHILE @@FETCH_STATUS = 0
			BEGIN
				PRINT '3. SEND MAIL-'

				EXEC PR_SSP_ADJUST_MAIL_SEND @v_change_req_no;

				FETCH NEXT FROM CUR_SEND_REQ INTO @v_change_req_no;

			END;
		*/

        /* 종료 LOG */
        V_LOG_TYPE := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);


    EXCEPTION
        WHEN OTHERS THEN
            /* CLOSE CUR_SEND_REQ; */
            /* DEALLOCATE CUR_SEND_REQ; */
            BEGIN

            V_SQLERRM := SUBSTR(SQLERRM, 1, 1000);

            INSERT
              INTO SCM_SYS_LOG_BATCH
                 ( PROGRAM_NAME
                 , LOG_TYPE
                 , LOG_COUNT
                 , LOG_MESSAGE
                 , DESCRIPTION
                 , EVENT_DATE
                 , CREATION_DATE
                 , CREATED_BY
                 , LAST_UPDATE_DATE
                 , LAST_UPDATED_BY )
            VALUES ( V_PROGRAM_NAME
                   , 'ERROR'
                   , NULL
                   , V_SQLERRM
                   , NULL
                   , SYSDATE
                   , SYSDATE
                   , V_PROGRAM_NAME
                   , SYSDATE
                   , V_PROGRAM_NAME );


            IF DBMS_TRANSACTION.LOCAL_TRANSACTION_ID IS NOT NULL THEN
                COMMIT;
            END IF;
            END;


    END;

    /* 임시테이블 삭제 */
    /* 원본 IF OBJECT_ID('tempdb..#TblSSPAdjustMailSendBatch') IS NOT NULL DROP TABLE #TblSSPAdjustMailSendBatch */
    DELETE
      FROM GT_SSPADJM_SENDBATCH;

END SCM_SSP_ADJUST_MAIL_SEND_BATCH;

PROCEDURE SCM_SSP_CHECK_CONFIRM_CHANGETIME (
    P_CONFIRM_ID   IN  VARCHAR2,
    O_CURSOR       OUT SYS_REFCURSOR
)
/*
 * Program ID   : SCM_SSP_GET_ORDER_CONFIRM
 * Description  : SSP Order 변경시 2분 이후 수량 재변경 LOCK 기능
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2023/03/16   jilee          Initial Release SSP Order 변경시 2분 이후 수량 재변경 LOCK 기능
 * 2026.10.02   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 * 2026.10.06   AJS            AS-IS 대조 보완 : 2분 판정 분 경계 기준 · 실행 로그 · 오류 메시지 반환 · 변경 이력 1회 조회
 */
AS
    C_DELIMITER   CONSTANT VARCHAR2(1) := '^';
    V_MAX_CNT     PLS_INTEGER;
    V_CONFIRM_ID  VARCHAR2(4000);
    V_CHK         PLS_INTEGER;
    V_LOCKED      PLS_INTEGER;
    V_RESULT      VARCHAR2(1) := 'S';
    -- 2026.10.06 AJS 실행 로그 · 최근 변경일시 · 오류 반환용
    C_PROGRAM_NAME  CONSTANT VARCHAR2(150) := 'SCM_SSP_CHECK_CONFIRM_CHANGETIME';
    V_LAST_DATE     DATE;
    V_ERR_CODE      VARCHAR2(100);
    V_ERR_MSG       VARCHAR2(2000);
BEGIN
    -- 2026.10.06 AJS AS-IS 시작 로그 (START)
    PR_SCM_SYS_LOG_BATCH(C_PROGRAM_NAME
                       , 'START'
                       , 0
                       , '########## Start of procedure ##########'
                       , NULL
                       , SYSDATE);
    -- 2026.10.06 AJS AS-IS 시작 로그 (END)

    V_MAX_CNT := TO_NUMBER(SCM_ARR_SPL_CNT(P_CONFIRM_ID, C_DELIMITER));

    -- 2026.10.06 AJS AS-IS WHILE LEN(@p_confirm_id) > 0 조건 반영 (START)
    -- FOR I IN 1 .. NVL(V_MAX_CNT, 0) LOOP
    FOR I IN 1 .. (CASE WHEN LENGTH(RTRIM(P_CONFIRM_ID)) > 0 THEN NVL(V_MAX_CNT, 0) ELSE 0 END) LOOP
    -- 2026.10.06 AJS AS-IS WHILE LEN(@p_confirm_id) > 0 조건 반영 (END)
        V_CONFIRM_ID := SCM_ARR_SPL_VAL(P_CONFIRM_ID, C_DELIMITER, I);

        -- 2026.10.06 AJS 건수와 최근 변경일시를 한 번에 조회 (START)
        -- SELECT COUNT(*)
        --   INTO V_CHK
        --   FROM SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE DE
        --  WHERE DE.CONFIRM_ID = V_CONFIRM_ID;
        SELECT COUNT(*)
             , MAX(DE.LAST_UPDATE_DATE)
          INTO V_CHK
             , V_LAST_DATE
          FROM SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE DE
         WHERE DE.CONFIRM_ID = V_CONFIRM_ID;
        -- 2026.10.06 AJS 건수와 최근 변경일시를 한 번에 조회 (END)

        IF V_CHK > 0 THEN
            -- 가장 최근 변경이 2분 이내면 LOCK(1). NULL 은 과거로 간주(통과) — AS-IS ISNULL(...,2) 등가.
            -- 2026.10.06 AJS AS-IS DATEDIFF(MI) 는 지난 시간이 아니라 넘어간 분 경계 수 — 분 단위로 잘라 견준다 (START)
            -- SELECT CASE
            --          WHEN (SYSDATE - NVL(MAX(DE.LAST_UPDATE_DATE), DATE '1900-01-01')) * 1440 < 2
            --          THEN 1 ELSE 0
            --        END
            --   INTO V_LOCKED
            --   FROM SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE DE
            --  WHERE DE.CONFIRM_ID = V_CONFIRM_ID;
            IF ROUND((TRUNC(SYSDATE, 'MI') - TRUNC(NVL(V_LAST_DATE, DATE '1900-01-03'), 'MI')) * 1440) < 2 THEN
                V_LOCKED := 1;
            ELSE
                V_LOCKED := 0;
            END IF;
            -- 2026.10.06 AJS AS-IS DATEDIFF(MI) 는 지난 시간이 아니라 넘어간 분 경계 수 — 분 단위로 잘라 견준다 (END)

            IF V_LOCKED = 1 THEN
                -- 2026.10.06 AJS AS-IS 결과 칸(CHK1·CHK2)과 종료 로그 반영 (START)
                -- V_RESULT := 'X';
                -- EXIT;
                OPEN O_CURSOR FOR
                    SELECT 'X'    AS RESULT_CODE
                         , V_CHK  AS CHK1
                         , 0      AS CHK2
                      FROM DUAL;

                PR_SCM_SYS_LOG_BATCH(C_PROGRAM_NAME
                                   , 'END'
                                   , 0
                                   , '########## END of procedure ##########'
                                   , 'X ' || V_CONFIRM_ID
                                   , SYSDATE);
                RETURN;
                -- 2026.10.06 AJS AS-IS 결과 칸(CHK1·CHK2)과 종료 로그 반영 (END)
            END IF;
        END IF;
    END LOOP;

    -- 2026.10.06 AJS AS-IS 종료 로그 (START)
    PR_SCM_SYS_LOG_BATCH(C_PROGRAM_NAME
                       , 'END'
                       , 0
                       , '########## END of procedure ##########'
                       , NULL
                       , SYSDATE);
    -- 2026.10.06 AJS AS-IS 종료 로그 (END)

    OPEN O_CURSOR FOR SELECT V_RESULT AS RESULT_CODE FROM DUAL;
EXCEPTION
    WHEN OTHERS THEN
        -- 2026.10.06 AJS AS-IS 오류 로그 기록과 오류 메시지 반환 (START)
        -- OPEN O_CURSOR FOR SELECT 'F' AS RESULT_CODE FROM DUAL;
        V_ERR_CODE := TO_CHAR(SQLCODE);
        V_ERR_MSG  := SUBSTR(SQLERRM, 1, 2000);

        PR_SCM_SYS_LOG_BATCH(C_PROGRAM_NAME
                           , 'ERROR'
                           , NULL
                           , SUBSTR(V_ERR_MSG, 1, 1000)
                           , NULL
                           , SYSDATE
                           , SUBSTR('P_CONFIRM_ID=' || P_CONFIRM_ID, 1, 2000)
                           , V_ERR_CODE
                           , V_ERR_MSG
                           , SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 4000));

        OPEN O_CURSOR FOR
            SELECT 'F'                                    AS RESULT_CODE
                 , '[' || V_ERR_CODE || ']' || V_ERR_MSG  AS RESULT_MSG
              FROM DUAL;
        -- 2026.10.06 AJS AS-IS 오류 로그 기록과 오류 메시지 반환 (END)
END;

PROCEDURE SCM_SSP_MAIL_SEND
(
    P_REQUEST_NO     IN  VARCHAR2
   , P_REQUEST_STATUS IN  VARCHAR2
)
/*
 * Program ID   : SCM_SSP_MAIL_SEND
 * Description  : SSP MAIL 발송
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2018/03/06   ygkim   Initial Release [PJ20182279] 전지본부 출하계획 시스템 구축 프로젝트
 * 2018/05/29   ygkim   SCM_ADM_SAVE_MAIL_SEND_BATCH_LOG 저장 시 에러나는 부분 수정
 * 2018/06/24   AYJ     [CSR ID:4017012] Shipment Request 자동 메일 개선 요청의 건
 * 2019/07/16   mcTheJ  [CSR ID:4044806] Model PIC 담당자 위임 기능 추가 - 위임자 메일 추가
 * 2019/07/16   mcTheJ  [CSR ID:4044806] Model PIC 담당자 위임 기능 추가 - 위임자 메일 내용 변경
 * 2024/01/15   jilee   ERP D/O 생성건 자가 반려 수정건
 * 2024/04/19   jilee   ERP 오류 회신 추가, Valid 추가
 * 2024/04/24   hsbang  Partial Approved(P) 추가, CATEGORY 추가
 * 2026.07.06   ZIONEX  [PJ202650304]  NextSCM Migration
 */
AS
    V_TO_MAIL               VARCHAR2(4000 CHAR);
    V_CATEGORY_ID           NUMBER;
    V_APPROVAL_ID           VARCHAR2(4000 CHAR);
    V_REQUEST_ID            VARCHAR2(4000 CHAR);
    V_MAIL_TITLE            VARCHAR2(4000 CHAR);
    V_BODY_CONTENTS         CLOB;

    V_BODY_TEXT             CLOB;
    V_HEAD_CONT             CLOB;
    V_A_BODY_CONTENTS       CLOB;
    TABLE_BODY              CLOB;
    P_HTML_YN               VARCHAR2(1 CHAR);

    V_DIVISION_ID           VARCHAR2(30 CHAR);
    V_ITEM_ID               VARCHAR2(50 CHAR);
    V_NICK_NAME             VARCHAR2(50 CHAR);
    V_FROM_SITE             VARCHAR2(30 CHAR);
    V_FROM_SITE_DESCRIPTION VARCHAR2(4000 CHAR);
    V_TO_SITE               VARCHAR2(30 CHAR);
    V_TO_SITE_DESCRIPTION   VARCHAR2(4000 CHAR);
    V_MTK_OWNER             VARCHAR2(4000 CHAR);
    V_INCOTERMS             VARCHAR2(10 CHAR);
    V_YYYYMMDD              VARCHAR2(10 CHAR);
    V_QTY                   VARCHAR2(4000 CHAR);
    V_TRANSPORT_MODE        VARCHAR2(50 CHAR);
    V_NEW_YYYYMMDD          VARCHAR2(10 CHAR);
    V_NEW_QTY               VARCHAR2(4000 CHAR);
    V_NEW_TRANSPORT_MODE    VARCHAR2(50 CHAR);
    V_LAST_UPDATE_DATE      VARCHAR2(50 CHAR);
    V_LAST_UPDATE_BY        VARCHAR2(4000 CHAR);

    V_CONFIRM_ID            VARCHAR2(50 CHAR);
    V_ERP_DO_NO             VARCHAR2(50 CHAR);
    V_VALID_YN              VARCHAR2(10 CHAR);

    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME          VARCHAR2(150 CHAR) := 'SCM_SSP_MAIL_SEND';
    V_LOG_TYPE              VARCHAR2(30 CHAR); /* START/END/ERROR/... */
    N_LOG_COUNT             NUMBER := 0;
    V_LOG_MESSAGE           VARCHAR2(1000 CHAR);
    V_DESCRIPTION           VARCHAR2(500 CHAR);
    D_EVENT_DATE            DATE;

    /* 계산용 변수 */
    CHK                     NUMBER := 0; /* 쿼리결과 총 건수 */

    /* DECLARE @i INT=1 (LOOP용) */
    MAILCHKCNT              NUMBER := 0;


    V_DELEGATEE             VARCHAR2(4000 CHAR);


    V_ERROR_MESSAGE         VARCHAR2(1000 CHAR);
BEGIN


    V_TO_MAIL       := NULL;
    V_CATEGORY_ID   := 0;
    V_APPROVAL_ID   := NULL;
    V_REQUEST_ID    := NULL;
    V_MAIL_TITLE    := NULL;
    V_BODY_CONTENTS := NULL;

    /* 임시테이블 생성(출하 계획 승인) → GTT 초기화(DELETE) */
    DELETE
      FROM GT_SSP_APPROVED_MAILSEND;

    IF P_REQUEST_STATUS = 'Q' THEN /* 출하 계획 요청 */
        V_CATEGORY_ID := 14;
    ELSIF P_REQUEST_STATUS = 'A' THEN /* 출하 계획 승인 */
        V_CATEGORY_ID := 15;
    ELSIF P_REQUEST_STATUS = 'R' THEN /* 출하 계획 반려 */
        V_CATEGORY_ID := 16;
    ELSIF P_REQUEST_STATUS = 'S' THEN /* 출하 계획 자가반려 */
        V_CATEGORY_ID := 13;
    ELSIF P_REQUEST_STATUS = 'O' THEN /* 출하 계획 D/O 반려 */
        V_CATEGORY_ID := 11;
    ELSIF P_REQUEST_STATUS = 'E' THEN /* 출하 계획 ERP 반려 */
        V_CATEGORY_ID := 9;
    ELSIF P_REQUEST_STATUS = 'P' THEN /* 출하 계획 부분 승인 (2024.04.24, P 추가) */
        V_CATEGORY_ID := 10;
    END IF;

    /********************************************************************************
    * Mail Setup 메뉴에 등록된 메일 정보 조회
    ******************************************************************************* */
    FOR R IN (
        SELECT C.APPROVAL_USER                              AS APPROVAL_USER
             , C.REQUEST_USER                               AS REQUEST_USER
             , C.MAIL_TITLE || '[' || C.CHANGE_REQ_NO || ']' AS MAIL_TITLE
             , C.BODY_CONTENTS                              AS BODY_CONTENTS
          FROM (
                SELECT *
                  FROM (
                        SELECT A.APPROVAL_USER
                             , A.REQUEST_USER
                             , A.CHANGE_REQ_NO
                             , A.CHANGE_REQ_STATUS
                             , 'KO' AS LANGUAGE
                          FROM SSP_ANL_SHIP_CONFIRM_CHG_REQ A
                             , TB_FX_USER U
                         WHERE A.REQUEST_USER = U.USERID
                           AND U.USEYN = 'Y'
                       ) A
                     , (

                        SELECT A.USE_TYPE_CODE
                             , C.USER_ID
                             , E.USERNAME     AS USER_NAME
                             , E.EMAIL        AS EMAIL_ADDR
                             , E.CELLPHONENUM AS MOBILE_PHONE
                             , B.LANGUAGE_CODE
                             , B.MAIL_TITLE
                             , D.SEGMENT3     AS HEADER_CONTENTS
                             , CASE A.USE_TYPE_CODE WHEN 'MAIL' THEN REPLACE(B.MESSAGE_CONTENT, CHR(10), '<br><br>')
                                                    WHEN 'SMS' THEN B.MESSAGE_CONTENT END AS BODY_CONTENTS
                             , D.SEGMENT3     AS FOOT_CONTENTS
                             , A.SQL_LONG_TEXT
                          FROM SCM_ADM_RECIPIENT_LIST A
                          INNER JOIN SCM_ADM_RECIPIENT_MESSAGE B ON A.CATEGORY_ID = B.CATEGORY_ID
                          LEFT OUTER JOIN SCM_ADM_RECIPIENT_ASSIGN C ON B.CATEGORY_ID = C.CATEGORY_ID
                          INNER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL D ON D.SEGMENT1 = B.LANGUAGE_CODE AND D.LOOKUP_TYPE = 'MAIL_HEADER_FOOT' AND D.VALID_YN = 'Y'
                          LEFT OUTER JOIN TB_FX_USER E ON B.LANGUAGE_CODE = E.LANGUAGE AND C.USER_ID = E.USERID
                         WHERE A.CATEGORY_ID = V_CATEGORY_ID
                           AND A.VALID_YN = 'Y'
                       ) B
                 WHERE A.LANGUAGE = B.LANGUAGE_CODE
               ) C
         WHERE 1 = 1
           AND C.CHANGE_REQ_NO = P_REQUEST_NO
           AND C.CHANGE_REQ_STATUS = P_REQUEST_STATUS
    ) LOOP
        V_APPROVAL_ID   := R.APPROVAL_USER;
        V_REQUEST_ID    := R.REQUEST_USER;
        V_MAIL_TITLE    := R.MAIL_TITLE;
        V_BODY_CONTENTS := R.BODY_CONTENTS;
    END LOOP;

    /********************************************************************************
    * 출하 계획 요청 건 상세 내용
    ********************************************************************************/
    INSERT
      INTO GT_SSP_APPROVED_MAILSEND
         ( DIVISION_ID
         , ITEM_ID
         , NICK_NAME
         , FROM_SITE
         , FROM_SITE_DESCRIPTION
         , TO_SITE
         , TO_SITE_DESCRIPTION
         , MTK_OWNER
         , INCOTERMS
         , YYYYMMDD
         , QTY
         , TRANSPORT_MODE
         , NEW_YYYYMMDD
         , NEW_QTY
         , NEW_TRANSPORT_MODE
         , CONFIRM_ID
         , ERP_DO_NO
         , VALID
         , LAST_UPDATE_DATE
         , LAST_UPDATED_BY
         , "ROWNUM" )
    SELECT T0.DIVISION_ID
         , T0.ITEM_ID
         , T0.NICK_NAME
         , T0.FROM_SITE
         , T0.FROM_SITE_DESCRIPTION
         , T0.TO_SITE
         , T0.TO_SITE_DESCRIPTION
         , T0.MTK_OWNER
         , T0.INCOTERMS
         , T0.YYYYMMDD
         , T0.QTY
         , T0.TRANSPORT_MODE
         , T0.NEW_YYYYMMDD
         , T0.NEW_QTY
         , T0.NEW_TRANSPORT_MODE
         , T0.CONFIRM_ID
         , T0.ERP_DO_NO
         , T0.VALID
         , TO_CHAR(T0.LAST_UPDATE_DATE, 'YYYY-MM-DD HH24:MI:SS".000"') AS LAST_UPDATE_DATE
         /* [2026-10-07] NULL 전파를 원본과 맞춘다 (소급 교정 · 사용자 결정 「3번 = 전부」).
          * 원본 MSSQL : [dbo].[FN_GET_USER_NAME](X) + '(' + X + ')'
          *   그 함수는 스칼라 서브쿼리(`set @retVal = (select USER_NAME … where USER_ID = @str1 …)`)라
          *   **없는 ID 면 NULL** 을 돌려주고, `+` 가 NULL 을 전파해 **컬럼 전체가 NULL** 이 된다.
          * Oracle 은 `||` 라 이름만 빠지고 '(ID)' 가 남았다 — 2026-10-07 HSD 실측 :
          *   FN_GET_USER_NAME('ZZXNOUSER') = NULL · 식 결과 = '(ZZXNOUSER)'
          * 행 12(APPROVAL_NAME)·행 16(뷰 REQUESTOR)과 같은 형태로 맞춘다.
          * ★함수를 두 번 참조하게 된다 — Oracle 에 `||` 를 NULL 전파로 만드는 내장 수단이 없다.
          *   이 건은 발송 대상 행만 처리하므로 영향이 작다고 보지만, 성능이 문제되면
          *   인라인 뷰로 한 번만 계산하도록 바꿀 수 있다(구조 변경이라 별도 판단). */
         , CASE WHEN FN_GET_USER_NAME(T0.LAST_UPDATED_BY) IS NULL OR T0.LAST_UPDATED_BY IS NULL THEN NULL ELSE FN_GET_USER_NAME(T0.LAST_UPDATED_BY) || '(' || T0.LAST_UPDATED_BY || ')' END  AS LAST_UPDATED_BY
         , ROW_NUMBER() OVER (ORDER BY T0.DIVISION_ID, T0.ITEM_ID , T0.FROM_SITE, T0.TO_SITE, T0.YYYYMMDD, T0.TRANSPORT_MODE) AS "ROWNUM"
      FROM (

            SELECT D.DIVISION_ID
                 , D.ITEM_ID
                 , FN_GET_ITEM_NICKNAME(D.DIVISION_ID, D.ITEM_ID)              AS NICK_NAME
                 , D.FROM_SITE
                 , FN_GET_SCM_SITE_DESCRIPTION( D.DIVISION_ID , D.FROM_SITE )  AS FROM_SITE_DESCRIPTION
                 , D.TO_SITE
                 , FN_GET_SCM_SITE_DESCRIPTION( D.DIVISION_ID , D.TO_SITE )    AS TO_SITE_DESCRIPTION
                 , DBMS_LOB.SUBSTR(FN_GET_SSP_MKT_OWNER_NAME(S.OWNER, ',', 'KO'), 4000, 1) AS MTK_OWNER
                 , D.INCOTERMS
                 , SUBSTR(D.YYYYMMDD,1,4) || '-' || SUBSTR(D.YYYYMMDD,5,2) || '-' || SUBSTR(D.YYYYMMDD,7,2) AS YYYYMMDD
                 , REPLACE(REPLACE(TO_CHAR(D.QTY, 'FM999,999,999,999,990.00'), '.00', ''), CHR(10), ' ') AS QTY
                 , D.TRANSPORT_MODE
                 , SUBSTR(D.NEW_YYYYMMDD,1,4) || '-' || SUBSTR(D.NEW_YYYYMMDD,5,2) || '-' || SUBSTR(D.NEW_YYYYMMDD,7,2) AS NEW_YYYYMMDD
                 , REPLACE(REPLACE(TO_CHAR(D.NEW_QTY, 'FM999,999,999,999,990.00'), '.00', ''), CHR(10), ' ') AS NEW_QTY
                 , D.NEW_TRANSPORT_MODE
                 , D.PROJECT_CODE
                 , H.APPROVAL_DEPT
                 , CASE WHEN P_REQUEST_STATUS = 'A' THEN H.APPROVAL_TIME
                        WHEN P_REQUEST_STATUS = 'R' THEN H.APPROVAL_TIME
                    ELSE H.LAST_UPDATE_DATE END AS LAST_UPDATE_DATE
                 , CASE WHEN P_REQUEST_STATUS = 'A' THEN CASE WHEN H.DELEGATEE_USER IS NULL THEN H.APPROVAL_USER ELSE H.DELEGATEE_USER END
                        WHEN P_REQUEST_STATUS = 'R' THEN CASE WHEN H.DELEGATEE_USER IS NULL THEN H.APPROVAL_USER ELSE H.DELEGATEE_USER END
                    ELSE H.LAST_UPDATED_BY END AS LAST_UPDATED_BY
                 , NVL(C.CONFIRM_ID, '-') AS CONFIRM_ID
                 , NVL(C.ERP_DO_NO, '-')  AS ERP_DO_NO
                 , D.VALID_YN AS VALID
              FROM SSP_ANL_SHIP_CONFIRM_CHG_REQ H
              JOIN SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE D
                ON H.CHANGE_REQ_NO = D.CHANGE_REQ_NO
                   /* jilee Valid 해제 */
                   /* AND D.VALID_YN = 'Y' */
              LEFT OUTER JOIN  SCM_MST_SITE_ITEM S
                ON  S.DIVISION_ID  = CASE WHEN D.DIVISION_ID = 'EE' THEN D.ORIGIN_TO_DIVISION_ID ELSE D.DIVISION_ID END
               AND  S.SCM_SITE_ID  = D.TO_SITE
               AND  S.ITEM_ID      = D.ITEM_ID
               AND  S.PROJECT_CODE = D.PROJECT_CODE
              LEFT OUTER JOIN SSP_ANL_SHIP_CONFIRM C
                ON C.CONFIRM_ID = D.CONFIRM_ID
             WHERE  1 = 1
               AND    H.CHANGE_REQ_STATUS = P_REQUEST_STATUS
               AND    H.CHANGE_REQ_NO =  P_REQUEST_NO
           ) T0
     GROUP BY T0.DIVISION_ID
            , T0.ITEM_ID
            , T0.NICK_NAME
            , T0.FROM_SITE
            , T0.FROM_SITE_DESCRIPTION
            , T0.TO_SITE
            , T0.TO_SITE_DESCRIPTION
            , T0.MTK_OWNER
            , T0.INCOTERMS
            , T0.YYYYMMDD
            , T0.QTY
            , T0.TRANSPORT_MODE
            , T0.NEW_YYYYMMDD
            , T0.NEW_QTY
            , T0.NEW_TRANSPORT_MODE
            , T0.CONFIRM_ID
            , T0.ERP_DO_NO
            , T0.VALID
            , T0.LAST_UPDATE_DATE
            , T0.LAST_UPDATED_BY
     ORDER BY T0.DIVISION_ID
            , T0.ITEM_ID
            , T0.FROM_SITE
            , T0.TO_SITE
            , T0.YYYYMMDD
            , T0.TRANSPORT_MODE;

    SELECT COUNT(*)
      INTO CHK
      FROM GT_SSP_APPROVED_MAILSEND;

    /********************************************************************************
    * 출하 계획 요청 건 상세 내용 테이블 만들기
    ********************************************************************************/
    V_HEAD_CONT := '';
    V_HEAD_CONT := V_HEAD_CONT || '<tr>';
    V_HEAD_CONT := V_HEAD_CONT || '<th rowspan=''2''>' || 'Div' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th rowspan=''2''>' || 'Model' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th rowspan=''2''>' || 'Nick Name' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th rowspan=''2''>' || 'From Site' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th rowspan=''2''>' || 'To Site' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th rowspan=''2''>' || 'MKT Owner' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th rowspan=''2''>' || 'Incoterms' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th colspan=''3''>' || 'Old' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th colspan=''3''>' || 'New' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th colspan=''3''>' || 'Common' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '</tr>';
    V_HEAD_CONT := V_HEAD_CONT || '<tr>';
    V_HEAD_CONT := V_HEAD_CONT || '<th width=''90px''>' || 'Shipment Date' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th width=''90px''>' || 'Shipment Qty' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th width=''80px''>' || 'Trans Mode' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th width=''90px''>' || 'Shipment Date' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th width=''90px''>' || 'Shipment Qty' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th width=''80px''>' || 'Trans Mode' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th width=''80px''>' || 'Confirm Id' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th width=''80px''>' || 'Delivery Order' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th width=''80px''>' || 'Approved List' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '</tr>';

    V_A_BODY_CONTENTS := '';
    V_BODY_TEXT := '';

    MAILCHKCNT := MAILCHKCNT + 1; /* 한 행 FETCH시 마다 +1 */

    /* 첫 행 FETCH (0행이면 이전값 유지 : FOR 루프로 등가 구현) */
    FOR R IN (
        SELECT DIVISION_ID
             , ITEM_ID
             , NICK_NAME
             , FROM_SITE
             , FROM_SITE_DESCRIPTION
             , TO_SITE
             , TO_SITE_DESCRIPTION
             , MTK_OWNER
             , INCOTERMS
             , YYYYMMDD
             , QTY
             , TRANSPORT_MODE
             , NEW_YYYYMMDD
             , NEW_QTY
             , NEW_TRANSPORT_MODE
             , CONFIRM_ID
             , ERP_DO_NO
             , VALID
             , LAST_UPDATE_DATE
             , LAST_UPDATED_BY
          FROM GT_SSP_APPROVED_MAILSEND
         WHERE "ROWNUM" = MAILCHKCNT
    ) LOOP
        V_DIVISION_ID           := R.DIVISION_ID;
        V_ITEM_ID               := R.ITEM_ID;
        V_NICK_NAME             := R.NICK_NAME;
        V_FROM_SITE             := R.FROM_SITE;
        V_FROM_SITE_DESCRIPTION := R.FROM_SITE_DESCRIPTION;
        V_TO_SITE               := R.TO_SITE;
        V_TO_SITE_DESCRIPTION   := R.TO_SITE_DESCRIPTION;
        V_MTK_OWNER             := R.MTK_OWNER;
        V_INCOTERMS             := R.INCOTERMS;
        V_YYYYMMDD              := R.YYYYMMDD;
        V_QTY                   := R.QTY;
        V_TRANSPORT_MODE        := R.TRANSPORT_MODE;
        V_NEW_YYYYMMDD          := R.NEW_YYYYMMDD;
        V_NEW_QTY               := R.NEW_QTY;
        V_NEW_TRANSPORT_MODE    := R.NEW_TRANSPORT_MODE;
        V_CONFIRM_ID            := R.CONFIRM_ID;
        V_ERP_DO_NO             := R.ERP_DO_NO;
        V_VALID_YN              := R.VALID;
        V_LAST_UPDATE_DATE      := R.LAST_UPDATE_DATE;
        V_LAST_UPDATE_BY        := R.LAST_UPDATED_BY;
    END LOOP;

    /* WHILE @@FETCH_STATUS = 0 */
    WHILE MAILCHKCNT <= CHK + 1
    LOOP

        IF MAILCHKCNT = 1 THEN
            V_BODY_TEXT := CASE WHEN V_LAST_UPDATE_BY IS NULL OR V_LAST_UPDATE_DATE IS NULL THEN NULL ELSE V_BODY_TEXT || 'Last updated by : ' || V_LAST_UPDATE_BY || '    Last update Date : ' || V_LAST_UPDATE_DATE || '</br>' END;
        END IF;

        IF (MAILCHKCNT = CHK + 1) THEN

            TABLE_BODY := '';
            TABLE_BODY := ' <html>
                                <head>
                                <title>Untitled Document</title>
                                <style>
                                    * {margin:0;padding:0;}
                                    body {font-family:Malgun Gothic, Arial, Helvetica, sans-serif;font-size:12px;line-height:1.8;color:#333333;}
                                    table {border-collapse:collapse;width:100%;}
                                    table th {background:#f5f5f5;border-bottom:1px solid #e1e1e1;}
                                    table td {background:#fff;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1;border-bottom:1px solid #e1e1e1;}
                                    table tbody th {border-left:1px solid #e1e1e1;text-align:right;padding:6px 8px;font-size:12px}
                                    table tbody td {padding:6px 8px;font-size:12px}
                                    table thead th {text-align:center;padding:3px;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1; border-bottom:1px solid #d1d1d1;font-size:12px}
                                    .hori-table table thead td {text-align:center;padding:3px;}
                                    .hori-table table tbody td {text-align:center;padding:3px;}
                                    .vertical-table, .hori-table {margin-bottom:20px;}
                                </style>
                                </head>
                                <body>' || '</br>' ||
                        '<b>' || REPLACE(V_BODY_CONTENTS, CHR(10), '<br>') || '</b>' || '</br>' || '</br>' ||
                        '<b>' || REPLACE(V_BODY_TEXT, CHR(10), '<br>') || '</b>' ||
/*                      '<div id="divBody" style="width: 100%; overflow-x: auto; overflow-y: auto; font-size: 9pt; line-break: auto;">'    || '</br>' || */
                    '<table style=''border-top:2px solid #c8294b; width:1200px;''>
                    <thead>' || V_HEAD_CONT || '</thead>
                    <tbody>' || V_A_BODY_CONTENTS || '</tbody>
                    </div>
                </body>
            </html>';
        END IF;

        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<tr>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td>' || REPLACE(V_DIVISION_ID, CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td>' || REPLACE(V_ITEM_ID, CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td>' || REPLACE(V_NICK_NAME, CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td>' || REPLACE(V_FROM_SITE_DESCRIPTION, CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td>' || REPLACE(V_TO_SITE_DESCRIPTION, CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td>' || REPLACE(V_MTK_OWNER, CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td>' || REPLACE(V_INCOTERMS, CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td align=''center''>' || REPLACE(V_YYYYMMDD, CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td align=''right''>' || REPLACE(V_QTY, CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td>' || REPLACE(V_TRANSPORT_MODE, CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td align=''center''>' || REPLACE(V_NEW_YYYYMMDD, CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td align=''right''>' || REPLACE(V_NEW_QTY, CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td>' || REPLACE(V_NEW_TRANSPORT_MODE, CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td>' || REPLACE(V_CONFIRM_ID, CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td>' || REPLACE(V_ERP_DO_NO, CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td>' || REPLACE(V_VALID_YN, CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '</tr>';

        MAILCHKCNT := MAILCHKCNT + 1;

        FOR R IN (
            SELECT DIVISION_ID
                 , ITEM_ID
                 , NICK_NAME
                 , FROM_SITE
                 , FROM_SITE_DESCRIPTION
                 , TO_SITE
                 , TO_SITE_DESCRIPTION
                 , MTK_OWNER
                 , INCOTERMS
                 , YYYYMMDD
                 , QTY
                 , TRANSPORT_MODE
                 , NEW_YYYYMMDD
                 , NEW_QTY
                 , NEW_TRANSPORT_MODE
                 , CONFIRM_ID
                 , ERP_DO_NO
                 , VALID
                 , LAST_UPDATE_DATE
                 , LAST_UPDATED_BY
              FROM GT_SSP_APPROVED_MAILSEND
             WHERE "ROWNUM" = MAILCHKCNT
        ) LOOP
            V_DIVISION_ID           := R.DIVISION_ID;
            V_ITEM_ID               := R.ITEM_ID;
            V_NICK_NAME             := R.NICK_NAME;
            V_FROM_SITE             := R.FROM_SITE;
            V_FROM_SITE_DESCRIPTION := R.FROM_SITE_DESCRIPTION;
            V_TO_SITE               := R.TO_SITE;
            V_TO_SITE_DESCRIPTION   := R.TO_SITE_DESCRIPTION;
            V_MTK_OWNER             := R.MTK_OWNER;
            V_INCOTERMS             := R.INCOTERMS;
            V_YYYYMMDD              := R.YYYYMMDD;
            V_QTY                   := R.QTY;
            V_TRANSPORT_MODE        := R.TRANSPORT_MODE;
            V_NEW_YYYYMMDD          := R.NEW_YYYYMMDD;
            V_NEW_QTY               := R.NEW_QTY;
            V_NEW_TRANSPORT_MODE    := R.NEW_TRANSPORT_MODE;
            V_CONFIRM_ID            := R.CONFIRM_ID;
            V_ERP_DO_NO             := R.ERP_DO_NO;
            V_VALID_YN              := R.VALID;
            V_LAST_UPDATE_DATE      := R.LAST_UPDATE_DATE;
            V_LAST_UPDATE_BY        := R.LAST_UPDATED_BY;
        END LOOP;

    END LOOP;


    BEGIN
        /* 시작 LOG */
        V_LOG_TYPE := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE := SYSTIMESTAMP;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        IF P_REQUEST_STATUS = 'Q' THEN /* 출하 계획 요청 */
            V_TO_MAIL := V_APPROVAL_ID || '@lgensol.com';
        ELSIF P_REQUEST_STATUS IN ('A','P') THEN /* 출하 계획 승인(2024.04.24, P 추가) */
            V_TO_MAIL := V_REQUEST_ID || '@lgensol.com';
        ELSIF P_REQUEST_STATUS = 'R' OR P_REQUEST_STATUS = 'O' OR P_REQUEST_STATUS = 'E' THEN /* 출하 계획 반려 */
            V_TO_MAIL := V_REQUEST_ID || '@lgensol.com';
        ELSIF P_REQUEST_STATUS = 'S' THEN /* 출하 계획 자가반려 */
            V_TO_MAIL := V_APPROVAL_ID || '@lgensol.com';
        END IF;

        V_BODY_CONTENTS := TABLE_BODY;
        P_HTML_YN := 'Y';


        PKG_SEND_MAIL.P_SEND_MAIL(
                V_TO_MAIL
                , V_MAIL_TITLE
                , V_BODY_CONTENTS
                , P_HTML_YN
                );

        /* //대리자 검색================================================================================= */
        IF P_REQUEST_STATUS = 'Q' OR P_REQUEST_STATUS = 'S' THEN /* 출하 계획 요청 or 출하 계획 자가반려 */
            V_DELEGATEE := NULL;
            BEGIN
                SELECT DELEGATEE_ID
                  INTO V_DELEGATEE
                  FROM (
                        SELECT A.DELEGATEE_ID
                          FROM SSP_MST_DELEGATE A
                         WHERE A.DIVISION_ID = V_DIVISION_ID
                           AND A.USER_ID = V_APPROVAL_ID
                           AND A.VALID_YN = 'Y'
                           AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN A.FROM_DATE AND A.TO_DATE
                         GROUP BY A.DELEGATEE_ID
                       )
                 WHERE ROWNUM = 1;
            EXCEPTION WHEN NO_DATA_FOUND THEN V_DELEGATEE := NULL;
            END;
            IF V_DELEGATEE IS NOT NULL THEN
                V_TO_MAIL := V_DELEGATEE || '@lgensol.com';


                PKG_SEND_MAIL.P_SEND_MAIL(
                        V_TO_MAIL
                        , V_MAIL_TITLE
                        , V_BODY_CONTENTS
                        , P_HTML_YN
                        );
            END IF;
        END IF;
        /* /////////////////////////////////////////////////////////////////////////////////////////////////// */

        IF LENGTH(V_BODY_CONTENTS) > 100 THEN
            V_BODY_CONTENTS := SUBSTR(V_BODY_CONTENTS, 1, 100);
        END IF;

        /* MAIL 발송 LOG 저장 */
        SCM_ADM_SAVE_MAIL_SEND_BATCH_LOG('MAIL'
                        , V_CATEGORY_ID
                        , V_MAIL_TITLE
                        , V_BODY_CONTENTS
                        , ''
                        , ''
                        , ''
                        , ''
                        , ''
                        , ''
                        , ''
                        , ''
                        , '' /* p_send_pgm */
                        , V_TO_MAIL);

        V_LOG_TYPE := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE := SYSTIMESTAMP;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);


    EXCEPTION

        WHEN OTHERS THEN


            V_ERROR_MESSAGE := SQLERRM;
            INSERT
              INTO SCM_SYS_LOG_BATCH
                 ( PROGRAM_NAME
                 , LOG_TYPE
                 , LOG_COUNT
                 , LOG_MESSAGE
                 , DESCRIPTION
                 , EVENT_DATE
                 , CREATION_DATE
                 , CREATED_BY
                 , LAST_UPDATE_DATE
                 , LAST_UPDATED_BY )
            VALUES ( V_PROGRAM_NAME
                   , 'ERROR'
                   , NULL
                   , V_ERROR_MESSAGE
                   , NULL
                   , SYSTIMESTAMP
                   , SYSTIMESTAMP
                   , V_PROGRAM_NAME
                   , SYSTIMESTAMP
                   , V_PROGRAM_NAME );

            IF DBMS_TRANSACTION.LOCAL_TRANSACTION_ID IS NOT NULL THEN
                COMMIT;
            END IF;

            /* error코드, error 메시지 반환 (호출부 결과셋 미소비 → DBMS_OUTPUT, H-9b) */
            DBMS_OUTPUT.PUT_LINE('F');
            DBMS_OUTPUT.PUT_LINE('[' || TO_CHAR(SQLCODE) || ']' || V_ERROR_MESSAGE);

    END;

    /* 임시테이블 삭제 → GTT 정리(DELETE) */
    DELETE
      FROM GT_SSP_APPROVED_MAILSEND;
END;

PROCEDURE SCM_SSP_MODEL_USER_MAIL_SEND
(
    P_REQUEST_NO      IN VARCHAR2
  , P_REQUEST_STATUS  IN VARCHAR2
  , P_DIVISION_ID     IN VARCHAR2
  , P_FROM_SITE       IN VARCHAR2
  , P_ITEM_ID         IN VARCHAR2
)
/*
 * Program ID   : SCM_SSP_MODEL_USER_MAIL_SEND
 * Description  : SSP 모델 PIC 추가 사용자 MAIL 발송
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2023/01/25   jilee   Initial Release SSP_MST_MODEL_USER 등록된 추가 사용자 메일 발송
 * 2026.07.06   ZIONEX  [PJ202650304]  NextSCM Migration
 */
AS
    V_TO_MAIL               VARCHAR2(4000 CHAR);
    V_CATEGORY_ID           NUMBER;
    V_APPROVAL_ID           VARCHAR2(4000 CHAR);
    V_REQUEST_ID            VARCHAR2(4000 CHAR);
    V_MAIL_TITLE            VARCHAR2(4000 CHAR);
    V_BODY_CONTENTS         CLOB;
    V_BODY_CONTENTS_SH      VARCHAR2(100 CHAR);

    V_BODY_TEXT             CLOB;
    V_HEAD_CONT             CLOB;
    V_A_BODY_CONTENTS       CLOB;
    TABLE_BODY              CLOB;
    P_HTML_YN               VARCHAR2(1 CHAR);

    V_DIVISION_ID           VARCHAR2(30 CHAR);
    V_ITEM_ID               VARCHAR2(50 CHAR);
    V_NICK_NAME             VARCHAR2(50 CHAR);
    V_FROM_SITE             VARCHAR2(30 CHAR);
    V_FROM_SITE_DESCRIPTION VARCHAR2(4000 CHAR);
    V_TO_SITE               VARCHAR2(30 CHAR);
    V_TO_SITE_DESCRIPTION   VARCHAR2(4000 CHAR);
    V_MTK_OWNER             VARCHAR2(4000 CHAR);
    V_INCOTERMS             VARCHAR2(10 CHAR);
    V_YYYYMMDD              VARCHAR2(10 CHAR);
    V_QTY                   VARCHAR2(4000 CHAR);
    V_TRANSPORT_MODE        VARCHAR2(50 CHAR);
    V_NEW_YYYYMMDD          VARCHAR2(10 CHAR);
    V_NEW_QTY               VARCHAR2(4000 CHAR);
    V_NEW_TRANSPORT_MODE    VARCHAR2(50 CHAR);
    V_LAST_UPDATE_DATE      VARCHAR2(50 CHAR);
    V_LAST_UPDATE_BY        VARCHAR2(4000 CHAR);

    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME          VARCHAR2(150 CHAR) := 'SCM_SSP_MODEL_USER_MAIL_SEND';
    V_LOG_TYPE              VARCHAR2(30 CHAR); /* START/END/ERROR/... */
    N_LOG_COUNT             NUMBER := 0;
    V_LOG_MESSAGE           VARCHAR2(1000 CHAR);
    V_DESCRIPTION           VARCHAR2(500 CHAR);
    D_EVENT_DATE            DATE;

    /* 계산용 변수 */
    V_CHK                   NUMBER := 0; /* 쿼리결과 총 건수 */

    /* DECLARE @i INT=1;  -- LOOP용 */
    V_MAILCHKCNT            NUMBER := 0;

    V_MAX_LOOP_CNT          NUMBER;
    V_MST_LOOP_CNT          NUMBER;
    V_MODELUSERATTRIBUTE    VARCHAR2(4000 CHAR);
    V_MODELUSER             VARCHAR2(150 CHAR);
    V_DELIMITER             VARCHAR2(1 CHAR);


    V_ERROR_MESSAGE         VARCHAR2(1000 CHAR);
BEGIN


    V_TO_MAIL          := NULL;
    V_CATEGORY_ID      := 0;
    V_APPROVAL_ID      := NULL;
    V_REQUEST_ID       := NULL;
    V_MAIL_TITLE       := NULL;
    V_BODY_CONTENTS    := NULL;
    V_BODY_CONTENTS_SH := NULL;

    V_MAX_LOOP_CNT       := 0;
    V_MST_LOOP_CNT       := 0;
    V_MODELUSERATTRIBUTE := NULL;
    V_MODELUSER          := NULL;
    V_DELIMITER          := '^';

    /* 추가 메일 발송자 조회 : 수신자 갯수 확정시 추가 조건 넣기 */
    /* (MSSQL 스칼라 SELECT 대입 : SSP_MST_MODEL_USER PK=(DIVISION_ID,FROM_SITE,ITEM_ID)로 0/1행 → FOR 루프로 등가(0행=이전값 NULL 유지)) */
    FOR R IN (
        SELECT NVL(MU.ATTRIBUTE1, 'X') || V_DELIMITER || NVL(MU.ATTRIBUTE2, 'X') || V_DELIMITER || NVL(MU.ATTRIBUTE3, 'X')
               || V_DELIMITER || NVL(MU.ATTRIBUTE4, 'X') || V_DELIMITER || NVL(MU.ATTRIBUTE5, 'X') AS MODELUSERATTRIBUTE
          FROM SSP_MST_MODEL_USER MU
         WHERE MU.DIVISION_ID = P_DIVISION_ID
           AND MU.FROM_SITE   = P_FROM_SITE
           AND MU.ITEM_ID     = P_ITEM_ID
           AND MU.VALID_YN    = 'Y'
    ) LOOP
        V_MODELUSERATTRIBUTE := R.MODELUSERATTRIBUTE;
    END LOOP;

    /* 임시테이블 생성(출하 계획 승인) → GTT 초기화(DELETE) */
    DELETE FROM GT_SSP_APPR_MAILSEND2;

    /*
    --IF @p_request_status = 'Q' --출하 계획 요청
    --  BEGIN
    --      SET @v_category_id = 14
    --  END
    --ELSE IF @p_request_status = 'A' --출하 계획 승인
    --  BEGIN
    --      SET @v_category_id = 15
    --  END
    --ELSE IF @p_request_status = 'R' --출하 계획 반려
    --  BEGIN
    --      SET @v_category_id = 16
    --  END
    --ELSE IF @p_request_status = 'S' --출하 계획 자가반려
    --  BEGIN
    --      SET @v_category_id = 13
    --  END
    */

    /* 출하 계획 승인만 해당됨 */
    V_CATEGORY_ID := 15;

    /********************************************************************************
    * Mail Setup 메뉴에 등록된 메일 정보 조회
    * (MSSQL 스칼라 SELECT 대입 : 0행=이전값 유지, N행=마지막행 → FOR 루프로 등가 구현)
    ********************************************************************************/
    FOR R IN (
        SELECT C.MAIL_TITLE || '[' || C.CHANGE_REQ_NO || ']' AS MAIL_TITLE
             , C.BODY_CONTENTS                               AS BODY_CONTENTS
          FROM (
                SELECT *
                  FROM (

                        SELECT A.APPROVAL_USER
                             , A.REQUEST_USER
                             , A.CHANGE_REQ_NO
                             , A.CHANGE_REQ_STATUS
                             , 'KO' AS LANGUAGE
                          FROM SSP_ANL_SHIP_CONFIRM_CHG_REQ A
                             , TB_FX_USER U
                         WHERE A.REQUEST_USER = U.USERID
                           AND U.USEYN = 'Y'
                       ) A
                     , (

                        SELECT A.USE_TYPE_CODE
                             , C.USER_ID
                             , E.USERNAME     AS USER_NAME
                             , E.EMAIL        AS EMAIL_ADDR
                             , E.CELLPHONENUM AS MOBILE_PHONE
                             , B.LANGUAGE_CODE
                             , B.MAIL_TITLE
                             , D.SEGMENT3     AS HEADER_CONTENTS
                             , CASE A.USE_TYPE_CODE WHEN 'MAIL' THEN REPLACE(B.MESSAGE_CONTENT, CHR(10), '<br><br>')
                                                    WHEN 'SMS' THEN B.MESSAGE_CONTENT END AS BODY_CONTENTS
                             , D.SEGMENT3     AS FOOT_CONTENTS
                             , A.SQL_LONG_TEXT
                          FROM SCM_ADM_RECIPIENT_LIST A
                          INNER JOIN SCM_ADM_RECIPIENT_MESSAGE B ON A.CATEGORY_ID = B.CATEGORY_ID
                          LEFT OUTER JOIN SCM_ADM_RECIPIENT_ASSIGN C ON B.CATEGORY_ID = C.CATEGORY_ID
                          INNER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL D ON D.SEGMENT1 = B.LANGUAGE_CODE AND D.LOOKUP_TYPE = 'MAIL_HEADER_FOOT' AND D.VALID_YN = 'Y'
                          LEFT OUTER JOIN TB_FX_USER E ON B.LANGUAGE_CODE = E.LANGUAGE AND C.USER_ID = E.USERID
                         WHERE A.CATEGORY_ID = TO_CHAR(V_CATEGORY_ID)
                           AND A.VALID_YN = 'Y'
                       ) B
                 WHERE A.LANGUAGE = B.LANGUAGE_CODE
               ) C
         WHERE 1 = 1
           AND C.CHANGE_REQ_NO = P_REQUEST_NO
           AND C.CHANGE_REQ_STATUS = P_REQUEST_STATUS
    ) LOOP
        V_MAIL_TITLE    := R.MAIL_TITLE;
        V_BODY_CONTENTS := R.BODY_CONTENTS;
    END LOOP;

    /********************************************************************************
    * 출하 계획 요청 건 상세 내용
    ********************************************************************************/
    INSERT INTO GT_SSP_APPR_MAILSEND2
         ( DIVISION_ID
         , ITEM_ID
         , NICK_NAME
         , FROM_SITE
         , FROM_SITE_DESCRIPTION
         , TO_SITE
         , TO_SITE_DESCRIPTION
         , MTK_OWNER
         , INCOTERMS
         , YYYYMMDD
         , QTY
         , TRANSPORT_MODE
         , NEW_YYYYMMDD
         , NEW_QTY
         , NEW_TRANSPORT_MODE
         , LAST_UPDATE_DATE
         , LAST_UPDATED_BY
         , "ROWNUM" )
    SELECT T0.DIVISION_ID
         , T0.ITEM_ID
         , T0.NICK_NAME
         , T0.FROM_SITE
         , T0.FROM_SITE_DESCRIPTION
         , T0.TO_SITE
         , T0.TO_SITE_DESCRIPTION
         , T0.MTK_OWNER
         , T0.INCOTERMS
         , T0.YYYYMMDD
         , T0.QTY
         , T0.TRANSPORT_MODE
         , T0.NEW_YYYYMMDD
         , T0.NEW_QTY
         , T0.NEW_TRANSPORT_MODE
         , TO_CHAR(T0.LAST_UPDATE_DATE, 'YYYY-MM-DD HH24:MI:SS".000"') AS LAST_UPDATE_DATE
         /* [2026-10-07] NULL 전파를 원본과 맞춘다 (소급 교정 · 사용자 결정 「3번 = 전부」).
          * 원본 MSSQL : [dbo].[FN_GET_USER_NAME](X) + '(' + X + ')'
          *   그 함수는 스칼라 서브쿼리(`set @retVal = (select USER_NAME … where USER_ID = @str1 …)`)라
          *   **없는 ID 면 NULL** 을 돌려주고, `+` 가 NULL 을 전파해 **컬럼 전체가 NULL** 이 된다.
          * Oracle 은 `||` 라 이름만 빠지고 '(ID)' 가 남았다 — 2026-10-07 HSD 실측 :
          *   FN_GET_USER_NAME('ZZXNOUSER') = NULL · 식 결과 = '(ZZXNOUSER)'
          * 행 12(APPROVAL_NAME)·행 16(뷰 REQUESTOR)과 같은 형태로 맞춘다.
          * ★함수를 두 번 참조하게 된다 — Oracle 에 `||` 를 NULL 전파로 만드는 내장 수단이 없다.
          *   이 건은 발송 대상 행만 처리하므로 영향이 작다고 보지만, 성능이 문제되면
          *   인라인 뷰로 한 번만 계산하도록 바꿀 수 있다(구조 변경이라 별도 판단). */
         , CASE WHEN FN_GET_USER_NAME(T0.LAST_UPDATED_BY) IS NULL OR T0.LAST_UPDATED_BY IS NULL THEN NULL ELSE FN_GET_USER_NAME(T0.LAST_UPDATED_BY) || '(' || T0.LAST_UPDATED_BY || ')' END AS LAST_UPDATED_BY
         , ROW_NUMBER() OVER (ORDER BY T0.DIVISION_ID, T0.ITEM_ID, T0.FROM_SITE, T0.TO_SITE, T0.YYYYMMDD, T0.TRANSPORT_MODE) AS "ROWNUM"
      FROM (
            SELECT D.DIVISION_ID
                 , D.ITEM_ID
                 , FN_GET_ITEM_NICKNAME(D.DIVISION_ID, D.ITEM_ID)             AS NICK_NAME
                 , D.FROM_SITE
                 , FN_GET_SCM_SITE_DESCRIPTION(D.DIVISION_ID, D.FROM_SITE)    AS FROM_SITE_DESCRIPTION
                 , D.TO_SITE
                 , FN_GET_SCM_SITE_DESCRIPTION(D.DIVISION_ID, D.TO_SITE)      AS TO_SITE_DESCRIPTION
                 , DBMS_LOB.SUBSTR(FN_GET_SSP_MKT_OWNER_NAME(S.OWNER, ',', 'KO'), 4000, 1) AS MTK_OWNER  /* 함수 반환 CLOB → 상위 GROUP BY 위해 VARCHAR2 캡(ORA-00932 회피) */
                 , D.INCOTERMS
                 , SUBSTR(D.YYYYMMDD, 1, 4) || '-' || SUBSTR(D.YYYYMMDD, 5, 2) || '-' || SUBSTR(D.YYYYMMDD, 7, 2) AS YYYYMMDD
                 , REPLACE(REPLACE(TO_CHAR(D.QTY, 'FM999,999,999,999,990.00'), '.00', ''), CHR(10), ' ') AS QTY
                 , D.TRANSPORT_MODE
                 , SUBSTR(D.NEW_YYYYMMDD, 1, 4) || '-' || SUBSTR(D.NEW_YYYYMMDD, 5, 2) || '-' || SUBSTR(D.NEW_YYYYMMDD, 7, 2) AS NEW_YYYYMMDD
                 , REPLACE(REPLACE(TO_CHAR(D.NEW_QTY, 'FM999,999,999,999,990.00'), '.00', ''), CHR(10), ' ') AS NEW_QTY
                 , D.NEW_TRANSPORT_MODE
                 , D.PROJECT_CODE
                 , H.APPROVAL_DEPT
                 , CASE WHEN P_REQUEST_STATUS = 'A' THEN H.APPROVAL_TIME
                        WHEN P_REQUEST_STATUS = 'R' THEN H.APPROVAL_TIME
                        ELSE H.LAST_UPDATE_DATE END AS LAST_UPDATE_DATE
                 , CASE WHEN P_REQUEST_STATUS = 'A' THEN CASE WHEN H.DELEGATEE_USER IS NULL THEN H.APPROVAL_USER ELSE H.DELEGATEE_USER END
                        WHEN P_REQUEST_STATUS = 'R' THEN CASE WHEN H.DELEGATEE_USER IS NULL THEN H.APPROVAL_USER ELSE H.DELEGATEE_USER END
                        ELSE H.LAST_UPDATED_BY END AS LAST_UPDATED_BY
              FROM SSP_ANL_SHIP_CONFIRM_CHG_REQ    H
                 , SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE D
                 , SCM_MST_SITE_ITEM               S
             WHERE 1 = 1
               AND H.CHANGE_REQ_NO = D.CHANGE_REQ_NO
               AND S.DIVISION_ID(+)  = CASE WHEN D.DIVISION_ID = 'EE' THEN D.ORIGIN_TO_DIVISION_ID ELSE D.DIVISION_ID END
               AND S.SCM_SITE_ID(+)  = D.TO_SITE
               AND S.ITEM_ID(+)      = D.ITEM_ID
               AND S.PROJECT_CODE(+) = D.PROJECT_CODE
               AND D.VALID_YN = 'Y'
               AND H.CHANGE_REQ_STATUS = P_REQUEST_STATUS
               AND H.CHANGE_REQ_NO = P_REQUEST_NO
           ) T0
     GROUP BY T0.DIVISION_ID, T0.ITEM_ID, T0.NICK_NAME, T0.FROM_SITE, T0.FROM_SITE_DESCRIPTION, T0.TO_SITE, T0.TO_SITE_DESCRIPTION, T0.MTK_OWNER
            , T0.INCOTERMS, T0.YYYYMMDD, T0.QTY, T0.TRANSPORT_MODE, T0.NEW_YYYYMMDD, T0.NEW_QTY, T0.NEW_TRANSPORT_MODE, T0.LAST_UPDATE_DATE, T0.LAST_UPDATED_BY
     ORDER BY T0.DIVISION_ID, T0.ITEM_ID, T0.FROM_SITE, T0.TO_SITE, T0.YYYYMMDD, T0.TRANSPORT_MODE;

    SELECT COUNT(*)
      INTO V_CHK
      FROM GT_SSP_APPR_MAILSEND2;

    /********************************************************************************
    * 출하 계획 요청 건 상세 내용 테이블 만들기
    ********************************************************************************/
    V_HEAD_CONT := '';
    V_HEAD_CONT := V_HEAD_CONT || '<tr>';
    V_HEAD_CONT := V_HEAD_CONT || '<th rowspan=''2''>' || 'Div' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th rowspan=''2''>' || 'Model' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th rowspan=''2''>' || 'Nick Name' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th rowspan=''2''>' || 'From Site' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th rowspan=''2''>' || 'To Site' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th rowspan=''2''>' || 'MKT Owner' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th rowspan=''2''>' || 'Incoterms' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th colspan=''3''>' || 'Old' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th colspan=''3''>' || 'New' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '</tr>';
    V_HEAD_CONT := V_HEAD_CONT || '<tr>';
    V_HEAD_CONT := V_HEAD_CONT || '<th width=''90px''>' || 'Shipment Date' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th width=''90px''>' || 'Shipment Qty' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th width=''80px''>' || 'Trans Mode' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th width=''90px''>' || 'Shipment Date' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th width=''90px''>' || 'Shipment Qty' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th width=''80px''>' || 'Trans Mode' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '</tr>';

    V_A_BODY_CONTENTS := '';
    V_BODY_TEXT := '';

    V_MAILCHKCNT := V_MAILCHKCNT + 1; /* 한 행 FETCH시 마다 +1 */

    /* 첫 행 FETCH (0행이면 이전값 유지 : FOR 루프로 등가 구현) */
    FOR R IN (
        SELECT DIVISION_ID
             , ITEM_ID
             , NICK_NAME
             , FROM_SITE
             , FROM_SITE_DESCRIPTION
             , TO_SITE
             , TO_SITE_DESCRIPTION
             , MTK_OWNER
             , INCOTERMS
             , YYYYMMDD
             , QTY
             , TRANSPORT_MODE
             , NEW_YYYYMMDD
             , NEW_QTY
             , NEW_TRANSPORT_MODE
             , LAST_UPDATE_DATE
             , LAST_UPDATED_BY
          FROM GT_SSP_APPR_MAILSEND2
         WHERE "ROWNUM" = V_MAILCHKCNT
    ) LOOP
        V_DIVISION_ID           := R.DIVISION_ID;
        V_ITEM_ID               := R.ITEM_ID;
        V_NICK_NAME             := R.NICK_NAME;
        V_FROM_SITE             := R.FROM_SITE;
        V_FROM_SITE_DESCRIPTION := R.FROM_SITE_DESCRIPTION;
        V_TO_SITE               := R.TO_SITE;
        V_TO_SITE_DESCRIPTION   := R.TO_SITE_DESCRIPTION;
        V_MTK_OWNER             := R.MTK_OWNER;
        V_INCOTERMS             := R.INCOTERMS;
        V_YYYYMMDD              := R.YYYYMMDD;
        V_QTY                   := R.QTY;
        V_TRANSPORT_MODE        := R.TRANSPORT_MODE;
        V_NEW_YYYYMMDD          := R.NEW_YYYYMMDD;
        V_NEW_QTY               := R.NEW_QTY;
        V_NEW_TRANSPORT_MODE    := R.NEW_TRANSPORT_MODE;
        V_LAST_UPDATE_DATE      := R.LAST_UPDATE_DATE;
        V_LAST_UPDATE_BY        := R.LAST_UPDATED_BY;
    END LOOP;

    /* WHILE @@FETCH_STATUS = 0 */
    WHILE V_MAILCHKCNT <= V_CHK + 1
    LOOP

        IF V_MAILCHKCNT = 1 THEN
            V_BODY_TEXT := CASE WHEN V_LAST_UPDATE_BY IS NULL OR V_LAST_UPDATE_DATE IS NULL THEN NULL ELSE V_BODY_TEXT || 'Last updated by : ' || V_LAST_UPDATE_BY || '    Last update Date : ' || V_LAST_UPDATE_DATE || '</br>' END;
        END IF;

        IF (V_MAILCHKCNT = V_CHK + 1) THEN

            TABLE_BODY := '';
            TABLE_BODY := ' <html>
                                <head>
                                <title>Untitled Document</title>
                                <style>
                                    * {margin:0;padding:0;}
                                    body {font-family:Malgun Gothic, Arial, Helvetica, sans-serif;font-size:12px;line-height:1.8;color:#333333;}
                                    table {border-collapse:collapse;width:100%;}
                                    table th {background:#f5f5f5;border-bottom:1px solid #e1e1e1;}
                                    table td {background:#fff;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1;border-bottom:1px solid #e1e1e1;}
                                    table tbody th {border-left:1px solid #e1e1e1;text-align:right;padding:6px 8px;font-size:12px}
                                    table tbody td {padding:6px 8px;font-size:12px}
                                    table thead th {text-align:center;padding:3px;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1; border-bottom:1px solid #d1d1d1;font-size:12px}
                                    .hori-table table thead td {text-align:center;padding:3px;}
                                    .hori-table table tbody td {text-align:center;padding:3px;}
                                    .vertical-table, .hori-table {margin-bottom:20px;}
                                </style>
                                </head>
                                <body>' || '</br>' ||
                        '<b>' || REPLACE(V_BODY_CONTENTS, CHR(10), '<br>') || '</b>' || '</br>' || '</br>' ||
                        '<b>' || REPLACE(V_BODY_TEXT, CHR(10), '<br>') || '</b>' ||
                        /*              '<div id="divBody" style="width: 100%; overflow-x: auto; overflow-y: auto; font-size: 9pt; line-break: auto;">'    || '</br>' || */
                    '<table style=''border-top:2px solid #c8294b; width:1200px;''>
                    <thead>' || V_HEAD_CONT || '</thead>
                    <tbody>' || V_A_BODY_CONTENTS || '</tbody>
                    </div>
                </body>
            </html>';
        END IF;

        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<tr>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td>' || REPLACE(V_DIVISION_ID, CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td>' || REPLACE(V_ITEM_ID, CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td>' || REPLACE(V_NICK_NAME, CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td>' || REPLACE(V_FROM_SITE_DESCRIPTION, CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td>' || REPLACE(V_TO_SITE_DESCRIPTION, CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td>' || REPLACE(V_MTK_OWNER, CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td>' || REPLACE(V_INCOTERMS, CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td align=''center''>' || REPLACE(V_YYYYMMDD, CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td align=''right''>' || REPLACE(V_QTY, CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td>' || REPLACE(V_TRANSPORT_MODE, CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td align=''center''>' || REPLACE(V_NEW_YYYYMMDD, CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td align=''right''>' || REPLACE(V_NEW_QTY, CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td>' || REPLACE(V_NEW_TRANSPORT_MODE, CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '</tr>';

        V_MAILCHKCNT := V_MAILCHKCNT + 1;

        FOR R IN (
            SELECT DIVISION_ID
                 , ITEM_ID
                 , NICK_NAME
                 , FROM_SITE
                 , FROM_SITE_DESCRIPTION
                 , TO_SITE
                 , TO_SITE_DESCRIPTION
                 , MTK_OWNER
                 , INCOTERMS
                 , YYYYMMDD
                 , QTY
                 , TRANSPORT_MODE
                 , NEW_YYYYMMDD
                 , NEW_QTY
                 , NEW_TRANSPORT_MODE
                 , LAST_UPDATE_DATE
                 , LAST_UPDATED_BY
              FROM GT_SSP_APPR_MAILSEND2
             WHERE "ROWNUM" = V_MAILCHKCNT
        ) LOOP
            V_DIVISION_ID           := R.DIVISION_ID;
            V_ITEM_ID               := R.ITEM_ID;
            V_NICK_NAME             := R.NICK_NAME;
            V_FROM_SITE             := R.FROM_SITE;
            V_FROM_SITE_DESCRIPTION := R.FROM_SITE_DESCRIPTION;
            V_TO_SITE               := R.TO_SITE;
            V_TO_SITE_DESCRIPTION   := R.TO_SITE_DESCRIPTION;
            V_MTK_OWNER             := R.MTK_OWNER;
            V_INCOTERMS             := R.INCOTERMS;
            V_YYYYMMDD              := R.YYYYMMDD;
            V_QTY                   := R.QTY;
            V_TRANSPORT_MODE        := R.TRANSPORT_MODE;
            V_NEW_YYYYMMDD          := R.NEW_YYYYMMDD;
            V_NEW_QTY               := R.NEW_QTY;
            V_NEW_TRANSPORT_MODE    := R.NEW_TRANSPORT_MODE;
            V_LAST_UPDATE_DATE      := R.LAST_UPDATE_DATE;
            V_LAST_UPDATE_BY        := R.LAST_UPDATED_BY;
        END LOOP;

    END LOOP;


    BEGIN
        /* 시작 LOG */
        V_LOG_TYPE := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE := SYSTIMESTAMP;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        /*
        --IF @p_request_status = 'Q' --출하 계획 요청
        --  BEGIN
        --      SET @v_to_mail = @v_approval_id + '@lgensol.com'
        --  END
        --ELSE IF @p_request_status = 'A' --출하 계획 승인
        --  BEGIN
        --      SET @v_to_mail = @v_request_id + '@lgensol.com'
        --  END
        --ELSE IF @p_request_status = 'R' --출하 계획 반려
        --  BEGIN
        --      SET @v_to_mail = @v_request_id + '@lgensol.com'
        --  END
        --ELSE IF @p_request_status = 'S' --출하 계획 자가반려
        --  BEGIN
        --      SET @v_to_mail = @v_approval_id + '@lgensol.com'
        --  END
        */

        V_BODY_CONTENTS := TABLE_BODY;
        P_HTML_YN := 'Y';

        /* While Loop Start */
        V_MAX_LOOP_CNT := SCM_ARR_SPL_CNT(V_MODELUSERATTRIBUTE, V_DELIMITER);

        WHILE LENGTH(V_MODELUSERATTRIBUTE) > 0 AND V_MST_LOOP_CNT < V_MAX_LOOP_CNT
        LOOP
            /* @mst_loop_cnt 1증가 */
            V_MST_LOOP_CNT := V_MST_LOOP_CNT + 1;

            IF LENGTH(V_BODY_CONTENTS) > 100 AND V_MST_LOOP_CNT = 1 THEN
                V_BODY_CONTENTS_SH := SUBSTR(V_BODY_CONTENTS, 1, 100);
            END IF;

            V_MODELUSER := SCM_ARR_SPL_VAL(V_MODELUSERATTRIBUTE, V_DELIMITER, V_MST_LOOP_CNT);

            IF V_MODELUSER <> 'X' AND V_MODELUSER IS NOT NULL THEN
                V_TO_MAIL := V_MODELUSER || '@lgensol.com';


                PKG_SEND_MAIL.P_SEND_MAIL(
                        V_TO_MAIL
                        , V_MAIL_TITLE
                        , V_BODY_CONTENTS
                        , P_HTML_YN
                        );

                /*
                --//대리자 검색=================================================================================
                --IF @p_request_status = 'Q' OR @p_request_status = 'S' --출하 계획 요청 or 출하 계획 자가반려
                --BEGIN
                --  DECLARE @v_delegatee        NVARCHAR(MAX);
                --  SET @v_delegatee=  NULL;
                --  SET @v_delegatee = (SELECT TOP 1 A.DELEGATEE_ID FROM SSP_MST_DELEGATE A
                --                      WHERE A.DIVISION_ID = @v_division_id
                --                      AND A.USER_ID = @v_approval_id
                --                      AND A.VALID_YN = 'Y'
                --                      AND CONVERT(NVARCHAR(8), GETDATE(), 112) BETWEEN A.FROM_DATE AND A.TO_DATE
                --                      GROUP BY A.DELEGATEE_ID);
                --  IF LEN(ISNULL(@v_delegatee, '')) > 0
                --  BEGIN
                --      SET @v_to_mail = @v_delegatee + '@lgensol.com';
                --      -- 메일 발송
                --      EXEC SCM_ADM_MAIL_SEND @v_to_mail, @v_mail_title, @v_body_contents, @p_html_yn;
                --  END;
                --END;
                --///////////////////////////////////////////////////////////////////////////////////////////////////
                */

                /* MAIL 발송 LOG 저장 */
                SCM_ADM_SAVE_MAIL_SEND_BATCH_LOG('MAIL'
                                , V_CATEGORY_ID
                                , V_MAIL_TITLE
                                , V_BODY_CONTENTS_SH
                                , 'Add Mail User'
                                , ''
                                , ''
                                , ''
                                , ''
                                , ''
                                , ''
                                , ''
                                , '' /* p_send_pgm */
                                , V_TO_MAIL);
            END IF;
        END LOOP; /* While Loop End */

        V_LOG_TYPE := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE := SYSTIMESTAMP;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);


    EXCEPTION

        WHEN OTHERS THEN


            V_ERROR_MESSAGE := SQLERRM;
            INSERT INTO SCM_SYS_LOG_BATCH
                 ( PROGRAM_NAME
                 , LOG_TYPE
                 , LOG_COUNT
                 , LOG_MESSAGE
                 , DESCRIPTION
                 , EVENT_DATE
                 , CREATION_DATE
                 , CREATED_BY
                 , LAST_UPDATE_DATE
                 , LAST_UPDATED_BY )
            VALUES ( V_PROGRAM_NAME
                   , 'ERROR'
                   , NULL
                   , V_ERROR_MESSAGE
                   , NULL
                   , SYSTIMESTAMP
                   , SYSTIMESTAMP
                   , V_PROGRAM_NAME
                   , SYSTIMESTAMP
                   , V_PROGRAM_NAME );

            IF DBMS_TRANSACTION.LOCAL_TRANSACTION_ID IS NOT NULL THEN
                COMMIT;
            END IF;

            /* error코드, error 메시지 반환 (호출부 결과셋 미소비 → DBMS_OUTPUT, H-9b) */
            DBMS_OUTPUT.PUT_LINE('F');
            DBMS_OUTPUT.PUT_LINE('[' || TO_CHAR(SQLCODE) || ']' || V_ERROR_MESSAGE);

    END;

    /* 임시테이블 삭제 → GTT 정리(DELETE) */
    DELETE FROM GT_SSP_APPR_MAILSEND2;
END;

FUNCTION           "STRING_SPLIT"
(
    P_STR    IN VARCHAR2
  , P_DELIM  IN VARCHAR2
)
RETURN T_STR_TAB PIPELINED
/*
 * FUNCTION NAME : STRING_SPLIT
 * DESCRIPTION   : 구분자로 문자열 분리(토큰 목록 반환)
 * PROGRAM HISTORY
 *--------------------------------------------------------------
 * 2026.07.06   ZIONEX  [PJ202650304]  NextSCM Migration
 */
AS

    V_IDX        PLS_INTEGER;
    V_FOUND_IDX  PLS_INTEGER;
    V_STR        VARCHAR2(32767 CHAR) := P_STR;

BEGIN

    V_IDX       := 1;
    V_FOUND_IDX := INSTR(V_STR, P_DELIM);

    WHILE (V_FOUND_IDX > 0) LOOP
        PIPE ROW (TRIM(SUBSTR(V_STR, 1, V_FOUND_IDX - 1)));
        V_STR       := SUBSTR(V_STR, V_FOUND_IDX + 1);
        V_IDX       := V_IDX + 1;
        V_FOUND_IDX := INSTR(V_STR, P_DELIM);
    END LOOP;

    PIPE ROW (TRIM(V_STR));

    RETURN;

END;

