PROCEDURE           "UP_FX_GETHTMLBYSQL" 
(
      P_SQL                     IN  CLOB
    , P_HEADER_COL_PRE          IN  VARCHAR2 DEFAULT 'COLUMN'
    , P_DATA_COL_PRE            IN  VARCHAR2 DEFAULT 'SEGMENT'
    , P_HTML                    OUT CLOB
)
/*
 * Program ID   : UP_FX_GetHtmlBySQL
 * Description  : SQL 쿼리 결과를 HTML로 변환 해서 리턴한다
 * Program History
 *===================================================================================================
 * Date         In Charge       Description
 *===================================================================================================
   2023/11/24   chaan           V1.1.1  Initialize  - SQL 쿼리 결과를 HTML로 작성하는 공통 프로시저 추가
                                                    - 기존 SQL 결과 컬럼이 10개로 제한 -> 컬럼 갯수에 상관없이 유연하게 대응하도록 변경
   2026/07/03   ZIONEX          [PJ202650304]  NextSCM Migration
 */
AS

    V_CUR                 INTEGER;
    V_COL_CNT             INTEGER;
    V_DESC                DBMS_SQL.DESC_TAB;
    V_IGNORE              INTEGER;


    TYPE T_INT_LIST IS TABLE OF PLS_INTEGER INDEX BY PLS_INTEGER;
    V_HEADER_POS          T_INT_LIST;
    V_DATA_POS            T_INT_LIST;
    V_HCNT                PLS_INTEGER := 0;
    V_DCNT                PLS_INTEGER := 0;

    V_HEADER_PRE          VARCHAR2(4000 CHAR) := UPPER(NVL(P_HEADER_COL_PRE, 'COLUMN'));
    V_DATA_PRE            VARCHAR2(4000 CHAR) := UPPER(NVL(P_DATA_COL_PRE,   'SEGMENT'));

    V_CELL                VARCHAR2(4000 CHAR);
    V_HEADER_COL_VALUES   CLOB;
    V_DATA_COL_VALUES     CLOB;
    V_FIRST_ROW           BOOLEAN := TRUE;
    I                     PLS_INTEGER;


    FUNCTION XML_ESCAPE(P IN VARCHAR2) RETURN VARCHAR2 IS
    BEGIN
        IF P IS NULL THEN
            RETURN NULL;
        END IF;
        RETURN REPLACE(REPLACE(REPLACE(P, '&', '&amp;'), '<', '&lt;'), '>', '&gt;');
    END;
BEGIN
    DBMS_LOB.CREATETEMPORARY(V_HEADER_COL_VALUES, TRUE);
    DBMS_LOB.CREATETEMPORARY(V_DATA_COL_VALUES,   TRUE);


    V_CUR := DBMS_SQL.OPEN_CURSOR;
    DBMS_SQL.PARSE(V_CUR, P_SQL, DBMS_SQL.NATIVE);
    DBMS_SQL.DESCRIBE_COLUMNS(V_CUR, V_COL_CNT, V_DESC);


    FOR C IN 1 .. V_COL_CNT LOOP
        IF UPPER(V_DESC(C).COL_NAME) LIKE V_HEADER_PRE || '%' THEN
            V_HCNT := V_HCNT + 1;
            V_HEADER_POS(V_HCNT) := C;
        ELSIF UPPER(V_DESC(C).COL_NAME) LIKE V_DATA_PRE || '%' THEN
            V_DCNT := V_DCNT + 1;
            V_DATA_POS(V_DCNT) := C;
        END IF;
    END LOOP;


    FOR C IN 1 .. V_COL_CNT LOOP
        DBMS_SQL.DEFINE_COLUMN(V_CUR, C, V_CELL, 4000);
    END LOOP;

    V_IGNORE := DBMS_SQL.EXECUTE(V_CUR);


    LOOP
        EXIT WHEN DBMS_SQL.FETCH_ROWS(V_CUR) = 0;

        /* 헤더: MSSQL은 SELECT TOP 1 로 첫 행 값만 사용 */
        IF V_FIRST_ROW THEN
            I := V_HEADER_POS.FIRST;
            WHILE I IS NOT NULL LOOP
                DBMS_SQL.COLUMN_VALUE(V_CUR, V_HEADER_POS(I), V_CELL);
                DBMS_LOB.WRITEAPPEND(V_HEADER_COL_VALUES
                  , LENGTH('<th style="color: white; background: SlateGray">')
                  , '<th style="color: white; background: SlateGray">');
                IF V_CELL IS NOT NULL THEN
                    V_CELL := XML_ESCAPE(V_CELL);
                    DBMS_LOB.WRITEAPPEND(V_HEADER_COL_VALUES, LENGTH(V_CELL), V_CELL);
                END IF;
                DBMS_LOB.WRITEAPPEND(V_HEADER_COL_VALUES, LENGTH('</th>'), '</th>');
                I := V_HEADER_POS.NEXT(I);
            END LOOP;
            V_FIRST_ROW := FALSE;
        END IF;


        DBMS_LOB.WRITEAPPEND(V_DATA_COL_VALUES, LENGTH('<tr>'), '<tr>');
        I := V_DATA_POS.FIRST;
        WHILE I IS NOT NULL LOOP
            DBMS_SQL.COLUMN_VALUE(V_CUR, V_DATA_POS(I), V_CELL);

            IF V_CELL IS NULL THEN
                DBMS_LOB.WRITEAPPEND(V_DATA_COL_VALUES, LENGTH('<td></td>'), '<td></td>');
            ELSE
                V_CELL := XML_ESCAPE(V_CELL);
                DBMS_LOB.WRITEAPPEND(V_DATA_COL_VALUES, LENGTH('<td>'), '<td>');
                DBMS_LOB.WRITEAPPEND(V_DATA_COL_VALUES, LENGTH(V_CELL), V_CELL);
                DBMS_LOB.WRITEAPPEND(V_DATA_COL_VALUES, LENGTH('</td>'), '</td>');
            END IF;
            I := V_DATA_POS.NEXT(I);
        END LOOP;
        DBMS_LOB.WRITEAPPEND(V_DATA_COL_VALUES, LENGTH('</tr>'), '</tr>');
    END LOOP;

    DBMS_SQL.CLOSE_CURSOR(V_CUR);


    IF DBMS_LOB.GETLENGTH(V_HEADER_COL_VALUES) > 0 THEN
        V_HEADER_COL_VALUES := '<tr>' || V_HEADER_COL_VALUES || '</tr>';
    END IF;


    P_HTML := V_HEADER_COL_VALUES || V_DATA_COL_VALUES;
EXCEPTION
    WHEN OTHERS THEN
        IF DBMS_SQL.IS_OPEN(V_CUR) THEN
            DBMS_SQL.CLOSE_CURSOR(V_CUR);
        END IF;
        RAISE;
END;

